INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Au commencement Dieu créa le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Or la terre était invisible et vide; les ténèbres étaient au-dessus de l’abîme, et l’Esprit de Dieu était porté sur les eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Et Dieu dit: Soit la lumière, et la lumière fut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Dieu vit que la lumière était bonne, et il sépara la lumière des ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Dieu appela la lumière jour; il appela nuit les ténèbres. Et il y eut un soir, et il y eut un matin, et ce fut un jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Dieu dit ensuite: Qu’il y ait un firmament au milieu des eaux; qu’il sépare les eaux des eaux; et il en fut ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Dieu créa le firmament, il sépara les eaux qui étaient au-dessus du firmament, des eaux qui étaient au-dessous du firmament.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Il appela le firmament ciel. Et Dieu vit que cela était bien. Et il y eut un soir, et il y eut un matin, et ce fut un deuxième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Après quoi Dieu dit: Que les eaux, au-dessous du ciel, soient réunies en un seul amas, et que l’aride арраrut. Et il en fut ainsi: les eaux, au-dessous du ciel, furent réunies en un seul amas, et l’aride apparut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Dieu appela l’aride terre; il appela mers l’amas des eaux. Et Dieu vit que cela était bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Et Dieu dit: Que la terre produise des plantes herbacées, portant semence selon les espèces et les similitudes, et des arbres fertiles en fruits, qui aient en eux les semences propres à chaque espèce sur la terre. Et il en fut ainsi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'La terre produisit des plantes herbacées, portant semence selon les espèces et les similitudes, et des arbres fertiles en fruits ayant en eux les semences propres à chaque espèce sur la terre. Et Dieu vit que cela était bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Et il y eut un soir, et il y eut un matin, et ce fut un troisième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Dieu dit ensuite: Que des luminaires soient dans le firmament du ciel, pour luire sur la terre et séparer les jours et les nuits; qu’ils soient les signes des temps et des jours et des années;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Qu’ils brillent au firmament du ciel, pour éclairer la surface de la terre. Et il en fut ainsi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Dieu créa les deux grands luminaires: le plus grand luminaire pour présider aux jours, le luminaire le plus petit pour présider aux nuits. Il créa les étoiles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Qu’il plaça dans le firmament du ciel pour éclairer la surface de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Présider aux jours et aux nuits, et séparer la lumière des ténèbres. Et Dieu vit que cela était bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Et il y eut un soir, et il y eut un matin, et ce fut un quatrième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Et Dieu dit: Que les eaux produisent des reptiles, âmes vivantes, et des oiseaux volant sur la terre, sous le firmament du ciel. Et il en fut ainsi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Dieu créa les grands poissons, et tout reptile (âme vivante) que les eaux produisirent par espèces. Il créa tous les oiseaux ailés par espèces. Et Dieu vit que cela était bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Puis Dieu les bénit, disant: Croissez et multipliez, remplissez les eaux des mers; et que les oiseaux multiplient sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Et il y eut un soir, et il y eut un matin, et ce fut un cinquième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Dieu dit ensuite Que la terre produise des âmes vivantes, selon les espèces: quadrupèdes, reptiles, bêtes fauves de la terre, par espèces. Et il en fut ainsi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Dieu créa les bêtes fauves de la terre, par espèces, les bestiaux selon leurs espèces, et tous les reptiles de la terre par espèces. Et Dieu vit que cela était bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Alors Dieu dit: Créons l’homme à notre image et ressemblance, qu’il ait tout pouvoir sur les poissons de la mer, sur les oiseaux du ciel, et sur les bestiaux, et sur toute la terre, et sur les reptiles se traînant à terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Et Dieu créa l’homme; il le créa à l’image de Dieu; il les créa mâle et femelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Et Dieu les bénit, disant: Croissez et multipliez, remplissez la terre, et dominez sur elle; soyez maîtres des poissons de la mer, et des oiseaux du ciel, et de tous les bestiaux, et de toute la terre, et de tous les reptiles qui se traînent à terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Voyez, dit Dieu, je vous donne toutes les plantes à semence qui germent à la surface de la terre; que tous les arbres qui portent des fruits à semence soient à vous, pour être votre nourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Que toutes les bêtes fauves de la terre, tous les oiseaux du ciel, tous les reptiles qui se traînent à terre, et ont en eux une âme vivante, aient pour nourriture toute herbe verdoyante. Et il en fut ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Et Dieu regarda toutes les choses qu’il avait créées, et les trouva excellemment bonnes. Et il y eut un soir, et il y eut un matin, et ce fut un sixième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Le ciel et la terre furent ainsi achevés, avec toute leur parure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Dieu acheva, le sixième jour, ses œuvres, les œuvres qu’il avait faites; et il se reposa le septième jour de ses travaux, de tous les travaux qu’il avait accomplis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Et Dieu bénit le septième jour, et le sanctifia, parce que ce jour-là il s’était reposé de tous ses travaux, des travaux qu’il avait entrepris de faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Voilà le livre de la naissance du ciel et de la terre, telle qu’elle s’accomplit, le jour où le Seigneur Dieu acheva de créer le ciel et la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Et toute la verdure des champs avant qu’elle naquit de la terre, et toute plante herbacée avant qu’elle eût germé; car Dieu n’arrosait point encore la terre, comme aussi il n’y avait point d’homme pour la travailler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Seulement une fontaine jaillissait du sol, et abreuvait toute la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Pour faire l’homme, Dieu pétrit une masse d’argile extraite de la terre, et sur sa face, il souffla un souffle de vie, et l’homme devint une âme vivante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Or, Dieu avait créé un paradis dans Éden, à l’orient; et il y plaça l’homme qu’il venait de former.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Dieu aussi avait fait germer de la terre tout arbre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Pour arroser le paradis, un fleuve jaillissait d’Éden, d’où il sortait divisé en quatre bras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Le nom de l’un est Phison, celui qui entoure la terre d’Hévilat, d’où vient l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'On sait que l’or de cette terre est excellent; là aussi sont l’anthrax et la pierre verte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Le nom du second fleuve est Gehon; c’est celui qui entoure la terre d’Éthiopie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Le troisième fleuve est le Tigre; c’est celui qui coule en face des Assyriens. Le quatrième fleuve est l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Le Seigneur prit l’homme qu’il avait formé, et il le plaça dans le paradis de délices, pour y travailler et le garder.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Le Seigneur fit ensuite un précepte à Adam, disant: Tu te nourriras de tous les arbres du paradis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Mais de l’arbre de la science du bien et du mal, gardez-vous d’en manger, car, le jour où vous en mangerez, vous mourrez de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Puis le Seigneur dit: Il n’est pas bon que l’homme soit seul; créons-lui un aide semblable à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Or, Dieu avait aussi formé de la terre toutes les bêtes des champs et tous les oiseaux du ciel, et il les avait conduits devant Adam pour qu’il sût comment il les nommerait, car tout nom qu’Adam donna à chaque âme vivante devint, en effet, son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Adam donna des noms à tous les bestiaux, et à tous les oiseaux du ciel, et à toutes les bêtes des champs. Mais il ne se trouvait pas pour Adam d’aide semblable à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Alors Dieu fit tomber Adam en extase et l’endormit; puis il prit une de ses côtes, qu’il remplaça par de la chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Et de cette côte qu’il avait prise à Adam, il forma une femme, et il la conduisit à Adam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Et Adam dit: Ceci maintenant est un os de mes os et une chair de ma chair. Celle-ci sera appelée femme, parce qu’elle a été prise de la chair même de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'A cause de cela, l’homme quittera son père et sa mère, il restera fortement attaché à sa femme, et ils seront deux en une seule chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Ils étaient nus tous deux: Adam et sa femme; et ils n’en avaient point honte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Or, le serpent était le plus rusé de tous les animaux qu’avait créés sur la terre le Seigneur Dieu. Et le serpent dit à la femme: Pourquoi Dieu a-t-il dit: Ne mangez pas de tous les arbres du paradis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'La femme dit au serpent: Nous pouvons manger des fruits des arbres du paradis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Quant au fruit de l’arbre qui est au milieu du paradis, Dieu a dit: Vous n’en mangerez pas, vous n’y toucherez pas, afin que vous ne mouriez point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Le serpent dit à la femme: Vous ne mourrez point de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Car le Seigneur Dieu sait, au contraire, que le jour où vous en mangerez, vos yeux s’ouvriront, et vous serez comme des dieux, connaissant le bien et le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'La femme vit que l’arbre était bon comme aliment, qu’il était gracieux à l’œil, et magnifique à contempler. Et, ayant pris de son fruit, elle en mangea; de plus, elle en donna à son mari, et ils mangèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Aussitôt leurs yeux à tous les deux s’ouvrirent; ils reconnurent qu’ils étaient nus; ils attachèrent les unes aux autres des feuilles de figuier, et ils s’en firent des ceintures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Et ils entendirent la voix du Seigneur Dieu, se promenant l’après-midi dans le paradis, et Adam et sa femme se cachèrent de la face du Seigneur Dieu, dans l’ombrage des arbres du paradis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Le Seigneur Dieu appela Adam, et il lui dit: Adam, où es-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Celui-ci répondit: J’ai entendu votre voix, comme vous vous promeniez dans le paradis, et j’ai eu peur parce que je suis nu, et je me suis caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Dieu lui dit: Qui t’a fait savoir que tu es nu, si tu n’as mangé de l’arbre, de celui-là seul dont je t’avais défendu de manger?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Adam reprit: La femme que vous m’avez donnée pour être avec moi m’a donné elle-même du fruit de l’arbre, et j’en ai mangé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Le Seigneur Dieu dit alors à la femme: Pourquoi as-tu fait cela? Et la femme dit: Le serpent m’a trompée, et j’ai mangé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Le Seigneur Dieu dit au serpent: Parce que tu as fait cela, maudit sois-tu parmi tous les bestiaux et les bêtes fauves de la terre; tu marcheras sur la poitrine et le ventre, et tu mangeras de la terre tous les jours de ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'J’établirai une haine entre toi et la femme, et entre ta race et sa race. Il surveillera ta tête, et tu guetteras son talon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Puis le Seigneur dit à la femme: Je multiplierai et multiplierai tes gémissements et tes douleurs; tu enfanteras dans les douleurs, tu attendras le commandement de ton époux, et il te maîtrisera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Quant à Adam, Dieu lui dit: Parce que tu as écouté la voix de ta femme, et que tu as mangé de l’arbre, du seul dont je t’avais défendu de manger, maudite sera ta terre en tes travaux. Tu t’en nourriras dans les douleurs tous les jours de ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Elle produira pour toi des épines et de l’ivraie, et tu mangeras l’herbe des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'C’est à la sueur de ton front que tu mangeras ton pain jusqu’à ce que tu retournes dans la terre d’où tu as été tiré, parce que: Tu es terre, et tu t’en iras dans la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Adam donna à la femme le nom d’Ève (vie), parce qu’elle-même est mère de tous les vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Le Seigneur Dieu fit ensuite à Adam et à sa femme des tuniques de peau dont il les revêtit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Et Dieu dit: Voilà donc Adam devenu comme l’un de nous, pour connaître le bien et le mal; mais maintenant qu’il n’aille pas étendre la main et prendre encore de l’arbre de vie, et en manger, car il vivrait toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Et le Seigneur Dieu le chassa du paradis de délices, pour qu’il travaillât à la terre de laquelle il avait été tiré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Il bannit Adam; il l’établit à l’opposé du paradis de délices, et il plaça des chérubins, armés d’épées flamboyantes qu’ils faisaient tournoyer, pour garder le chemin de l’arbre de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Or, Adam connut Ève sa femme, qui, ayant conçu, enfanta Caïn; et elle dit: J’ai obtenu un homme grâce à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Ensuite elle enfanta son frère Abel, qui fut pasteur de brebis; de son côté Caïn s’adonna au labourage de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Après bien des jours, il arriva que Caïn apporta des fruits de la terre en offrande au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Or, Abel apporta des premiers-nés de son troupeau, et de leur graisse. Et Dieu regarda Abel et ses présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Mais il ne fit attention ni à Caïn, ni à son offrande; Caïn en fut très-affligé, et eut le visage tout abattu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Le Seigneur dit à Caïn: D’où vient que tu es si fort affligé et que ton visage est tout abattu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Si tu as bien fait de m’apporter des offrandes, en les choisissant mal n’as-tu pas péché? Calme-toi, le péché est sous ta puissance, et c’est à toi de le dominer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Et Caïn dit à Abel son frère: Allons aux champs. Et voilà que comme ils étaient aux champs, Caïn se leva contre son frère Abel et le tua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Et le Seigneur dit à Caïn: Où est Abel, ton frère? Il répondit: Je ne sais suis-je le gardien de mon frère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Le Seigneur Dieu dit: Qu’as-tu fait? le cri du sang de ton frère a retenti de la terre jusqu’à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Maintenant donc, maudit sois-tu sur la terre qui a ouvert la bouche pour recueillir de ta main le sang de ton frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Lorsque tu travailleras à la terre, elle n’emploiera pas sa force pour te faire ses dons; tu seras gémissant et tremblant sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Caïn dit au Seigneur: Mon crime est trop grand pour m’être pardonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Si vous me bannissez aujourd’hui de la face de cette terre, je serai caché loin de vos yeux; je serai gémissant et tremblant sur la terre, et le premier qui me rencontrera me tuera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Le Seigneur lui dit: Il n’en sera point ainsi; tout être qui tuerait Caïn encourrait sept châtiments. Et le Seigneur Dieu mit un signe à Caïn, pour que tout être qui le rencontrerait ne le tuât point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Or, Caïn s’éloigna de la face de Dieu, et il habita la terre de Nod vis-à-vis Éden.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Après cela Caïn connut sa femme, qui, ayant conçu, enfanta Enoch; ensuite Caïn bâtit une ville, et du nom de son fils, il la nomma Enoch.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Or, d’Enoch fut engendré Gaïdad, Gaïdad engendra Malalehël, Malalehël engendra Mathusala, et Mathusala engendra Lamech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Et Lamech épousa deux femmes: la première nommée Ada, la seconde nommée Sella.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ada enfanta Jabel; celui-ci fut le père de ceux qui demeurèrent sous des tentes, des nourrisseurs de bestiaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Et son frère eut le nom Jubal; celui-ci inventa le psaltérion et la cithare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Or Sella de son côté enfanta Thobel ou Tubalcaïn, et il fut ouvrier au marteau, forgeron du fer et de l’airain. La sœur de Tubalcaïn fut Noéma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Or, Lamech dit à ses femmes Ada et Sella: Écoutez ma voix, femmes de Lamech, faites attention à mes paroles: J’ai tué un homme pour mon malheur, un jeune homme pour ma meurtrissure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'On eût vengé sept fois le meurtre de Caïn; celui de Lamech le serait septante fois sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Or, Adam connut Ève sa femme, et, ayant conçu, elle enfanta un fils à qui elle donna le nom de Seth (substitué). Car, dit-elle, Dieu a fait sortir de moi un autre rejeton, en place d’Abel que Caïn a tué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Et à Seth naquit un fils, auquel il donna le nom d’Enos; celui-ci, plein de confiance, invoqua le nom du Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Voici le livre de la génération des hommes. Le jour où Dieu créa Adam, il le créa à l’image de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Il les créa mâle et femelle, il les bénit. Et il donna à l’homme le nom d’Adam, le jour où il les créa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Or, Adam vécut deux cent trente ans, il engendra, selon son espèce et à son image, et il nomma son fils Seth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Or, les jours que vécut Adam, après qu’il eut engendré Seth, formèrent sept cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Et tous les jours que vécut Adam formèrent neuf cent trente ans, et il mourut,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Seth vécut deux cent cinq ans, et il engendra Enos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Et Seth vécut, après qu’il eut engendré Enos, sept cent sept ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Ainsi tous les jours de Seth formèrent neuf cent douze ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enos vécut cent quatre-vingt-dix ans, et il engendra Cainan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Et après qu’il eut engendré Caïnan, Enos vécut cent quinze ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Tous les jours d’Enos formèrent neuf cent cinq ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Caïnan vécut cent soixante-dix ans, et il engendra Malalehel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Et Caïnan vécut, après qu’il eut engendré Malalehel, sept cent quarante ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Tous les jours de Caïnan formèrent neuf cent dix ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Malalehel vécut cent soixante-cinq ans, dra Jared.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Et Malalehel vécut, après qu’il eut engendré Jared, sept cent trente ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Tous les jours de Malalehel formèrent huit cent quatre-vingt-quinze ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jared vécut cent soixante-deux ans, et il engendra Énoch.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Et Jared vécut, après qu’il eut engendré Énoch, huit cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Tous les jours de Jared formèrent neuf cent soixante-deux ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Énoch vécut cent soixante-cinq ans, et il engendra Mathusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Or Enoch, après qu’il eut engendré Mathusalem vécut agréable à Dieu durant deux cents ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Et tous les jours d’Enoch formèrent trois cent soixante-cinq ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Énoch vécut agréable à Dieu; ensuite personne ne le vit plus, parce que Dieu le transporta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Mathusalem vécut cent soixante-sept ans, et il engendra Lamech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Et Mathusalem vécut, après qu’il eut engendré Lamech, huit cent deux ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Tous les jours que vécut Mathusalem formèrent neuf cent soixante-neuf ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamech vécut cent quatre-vingt-huit ans, et il engendra un fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Auquel il donna le nom de Noé (repos), disant: Celui-ci nous fera reposer de nos travaux, et des peines de nos mains, ainsi que de la malédiction que le Seigneur Dieu a infligée à la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Lamech vécut, après qu’il eut engendré Noé, cinq cent soixante-cinq ans, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Tous les jours de Lamech formèrent sept cent cinquante-trois ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Noé avait cinq cents ans, et il engendra trois fils: Sem, Cham et Japhet. Il vécut dans le temps que les hommes commencèrent à être nombreux sur la terre, et que des filles leur étaient nées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Or, les fils de Dieu, ayant vu que les filles des hommes étaient belles, prirent pour femmes, parmi toutes, celles dont ils firent choix,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Et le Seigneur Dieu dit: Mon esprit ne restera pas toujours avec ces hommes, parce qu’ils ne sont que chair. Désormais leurs jours formeront cent vingt ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Or, il y avait des géants sur la terre, en ces jourslà; car depuis que les fils de Dieu s’étaient unis aux filles des hommes, elles leur avaient enfanté ces géants, ces hommes du siècle, les fameux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Or, le Seigneur Dieu ayant vu que les méchancetés des hommes étaient multipliées sur la terre, et que chacun en son cœur tous les jours s’appliquait à penser au mal,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Il s’attrista en lui-même d’avoir créé l’homme sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Et Dieu réfléchit, et il dit: J’effacerai de la face de la terre l’homme que j’ai créé; tout sera détruit depuis l’homme jusqu’aux bestiaux, depuis les reptiles jusqu’aux oiseaux du ciel, parce que j’ai regret de les avoir créés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noé cependant trouva grâce devant le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Voici les générations de Noé. Noé, homme juste, irréprochable dans sa vie, Noé était agréable à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Et Noé engendra trois fils: Sem, Cham et Japhet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Or, la terre était corrompue devant Dieu, et pleine d’iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Et le Seigneur Dieu vit la terre toute corrompue, parce que toute chair sur la terre avait corrompu ses voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Et le Seigneur Dieu dit à Noé: Le temps fatal de tous les hommes est arrivé devant moi, parce que la terre est pleine de leurs iniquités; voilà donc que je vais détruire eux et toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Ainsi, fais-toi une arche d’arbres équarris; tu composeras l’arche de cellules, et tu l’enduiras de bitume, au dedans et en dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Voici comment tu feras l’arche: trois cents coudées de long, cinquante coudées de large, trente coudées de haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Tu construiras l’arche en rassemblant les bois les uns au-dessus des autres; tu donneras au faîte une coudée de plus d’élévation; tu feras la porte de l’arche sur les flancs; elle aura des chambres basses, un étage au-dessus, et un troisième étage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Car voilà que je prépare un déluge; j’amènerai de l’eau sur la terre pour anéantir toute chair ayant souffle de vie sous le ciel, et tout ce qui est sur la terre périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'J’établirai mon alliance avec toi; puis tu entreras dans l’arche, et avec toi entreront tes fils, ta femme, et les femmes de tes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Ensuite, de tous les bestiaux, de tous les reptiles, de toutes les bêtes fauves, et de toute chair, tu introduiras dans l’arche deux couples pris parmi tous, pour être nourris avec toi; il y aura mâle et femelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'De tous les oiseaux ailés, par espèces, et de tous les reptiles se traînant à terre, selon leurs espèces, deux couples, pris parmi tous, mâles et femelles, entreront près de toi, pour être nourris avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'En même temps tu prendras avec toi de tous les aliments que vous mangez, tu les transporteras près de toi, et ce sera pour votre nourriture et pour la leur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Et tout ce que lui ordonna le Seigneur Dieu, Noé l’accomplit exactement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Dieu dit alors à Noé: Entre dans l’arche avec toute ta maison, parce que parmi toute cette race, je t’ai vu juste devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De tous les bestiaux purs introduis auprès de toi sept couples, mâles et femelles, et de tous les animaux impurs deux couples mâles et femelles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'De tous les oiseaux purs du ciel sept couples mâles et femelles, et de tous les oiseaux impurs deux couples mâles et femelles, afin d’en conserver la semence pour toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Car, encore sept jours, et je ferai tomber la pluie sur toute la terre, quarante jours et quarante nuits; et j’effacerai de la face de toute la terre tout ce qui s’y élève et que j’ai fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Noé fit tout ce que lui ordonna le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Il était âgé de six cents ans, lorsque le déluge vint sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Bientôt Noé, et avec lui ses fils, et sa femme, et les femmes de ses fils entrèrent dans l’arche, à cause de l’eau du déluge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'De tous les oiseaux purs et de tous les oiseaux impurs, de tous les bestiaux purs et de tous les bestiaux impurs, ainsi que de tous les animaux qui rampent sur la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Deux couples mâles et femelles entrèrent auprès de Noé dans l’arche, selon que le Seigneur avait prescrit à Noé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Et après que les sept jours furent passés, l’eau du déluge vint sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'L’an six cent de la vie de Noé, le vingt-septième jour de la seconde lune, toutes les sources de l’abîme jaillirent et les cataractes du ciel furent rompues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'La pluie tomba sur la terre quarante jours et quarante nuits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'En ces jours-là, Noé, Sem, Cham, Japhet, fils de Noé, la femme de Noé et les trois femmes de ses fils, étaient entrés dans l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Et toutes les bêtes fauves, par espèces; tous les bestiaux, par espèces; tous les reptiles se traînant à terre, par espèces; tous les oiseaux ailés, par espèces;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Étaient entrés auprès de Noé, dans l’arche, par deux couples, mâles et femelles, de toute chair en laquelle était souffle de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Tous les mâles et femelles de toute chair étaient donc entrés dans l’arche, selon ce que le Seigneur avait prescrit à Noé, et le Seigneur Dieu avait fermé l’arche en dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Et le déluge fut sur toute la terre quarante jours et quarante nuits; l’eau se gonfla, et emporta l’arche qui s’éleva bien au-dessus de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Et l’eau dominait; elle montait, montait toujours sur la terre, et l’arche était portée sur la surface de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Et l’eau dominait beaucoup, beaucoup sur la terre; et elle couvrait toutes les hautes montagnes qui étaient sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'L’eau s’éleva à quinze coudées au-dessus de leur sommet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Alors mourut toute chair se mouvant sur la terre, oiseaux et bestiaux, bêtes fauves et reptiles se traînant à terre, et tout homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Tout ce qui avait souffle de vie, et tout ce qui vivait sur la terre ferme mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'L’eau effaça tout ce qui se mouvait sur la face de la terre, depuis l’homme jusqu’aux bestiaux, tous les reptiles, et les oiseaux du ciel. Ils furent tous effacés de la terre. Noé seul resta, et ceux qui étaient dans l’arche avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'L’eau se maintint au-dessus de la terre cent cinquante jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Puis, Dieu se souvint de Noé, et de toutes les bêtes fauves, et de tous les bestiaux, et de tous les oiseaux, et de tous les reptiles qui étaient avec lui dans l’arche. Il fit souffler un vent sur la terre, et l’eau céda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Les sources de l’abîme furent fermées, ainsi que les cataractes du ciel, et la pluie du ciel cessa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'L’eau qui fuyait sur la terre s’affaissa, et diminua après cent cinquante jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Et, le vingt-septième jour de la septième lune, l’arche s’arrêta sur le mont Ararat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Or, l’eau diminua jusqu’à la dixième lune, et, le premier jour de la dixième lune, les cimes des montagnes apparurent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Après quarante jours, Noé ouvrit la porte de l’arche qu’il avait faite, et fit partir un corbeau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Qui, étant sorti, ne revint plus, même après que l’eau se fut desséchée sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Après lui, Noé envoya une colombe pour voir si l’eau s’était retirée de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Mais la colombe, n’ayant point trouvé où poser ses pieds, revint auprès de lui dans l’arche, parce que l’eau était sur toute la surface de la terre. Et, ayant étendu la main, il la prit et l’introduisit auprès de lui dans l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Puis, après avoir attendu sept jours encore, il fit de nouveau partir de l’arche la colombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Et sur le soir la colombe revint près de lui, tenant en son bec un brin de branche et une feuille d’olivier. Noé reconnut alors que l’eau s’était retirée de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Et après avoir attendu encore sept jours, il fit de nouveau partir la colombe, qui ne revint plus auprès de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Or, l’an six cent un de la vie de Noé, le premier jour de la première lune, l’eau disparut sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Et, le vingt-septième jour de la seconde lune, la terre se trouva sèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Et le Seigneur Dieu parla à Noé, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sors de l’arche avec ta femme, et tes fils, et les femmes de tes fils, et toutes les bêtes fauves qui sont auprès de toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Et toute chair, depuis les oiseaux jusqu’aux bestiaux; fais aussi sortir tout reptile se traînant à terre; et croissez et multipliez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Noé sortit donc avec sa femme, et ses fils, et les femmes de ses fils;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Et toutes les bêtes fauves, et tous les bestiaux, et tout oiseau, et tout reptile se traînant à terre, selon leurs espèces, sortirent avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Et Noé éleva un autel au Seigneur; puis il prit de tous les bestiaux purs, et de tous les oiseaux purs, et il en offrit sur l’autel un holocauste au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Et le Seigneur Dieu respira un parfum délicieux. Et le Seigneur Dieu, ayant réfléchi, dit: Je ne veux plus maudire la terre à cause des œuvres des hommes, parce que l’esprit de l’homme, dès sa jeunesse, se complaît dans le mal. Je ne veux donc plus frapper toute chair vivante, comme je l’ai fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Tous les jours de la terre, les semailles et la moisson, le froid et l’ardente chaleur, l’automne et le printemps, ne se reposeront jamais plus, ni jour ni nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Dieu bénit Noé et ses fils, et il leur dit: Croissez et multipliez, remplissez la terre et dominez sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Vous inspirerez crainte et terreur à toutes les bêtes fauves de la terre, aux oiseaux du ciel, à tout ce qui se meut sur la terre, et à tous les poissons de la mer. Je les livre à vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Tout ce qui se meut et a vie vous servira d’aliment; je vous donne de même, dans les champs, toute plante potagère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Cependant, vous ne mangerez pas de chair ayant encore le sang et la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Car votre sang, le sang de votre vie, je le rechercherai jusque dans les griffes des bêtes fauves, et je rechercherai la vie de l’homme jusque dans les mains de l’homme son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Celui qui versera le sang de l’homme, le versera au prix de son propre sang, parce que j’ai créé l’homme à l’image de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Mais croissez et multipliez, remplissez la terre, et dominez sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Et Dieu parla à Noé et à ses fils, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Je rétablis mon alliance avec vous, avec votre postérité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Avec toute âme vivante, oiseaux et bestiaux, et avec toutes les bêtes fauves de la terre qui sont sorties de l’arche avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'J’établirai mon alliance en votre faveur; la chair ne périra pas de nouveau par le déluge, et il n’y aura plus de déluge qui détruise la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Et le Seigneur Dieu dit à Noé: Voici le signe de l’alliance que j’établis entre moi et vous et toute âme vivante, pour toutes les races futures:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Je place mon arc dans la nue, et il sera le signe de mon alliance avec la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Lorsque je rassemblerai les nuées sur la terre, l’arc paraîtra dans la nue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Et je me souviendrai de mon alliance avec vous et avec toute âme vivante et toute chair, et il n’y aura plus de déluge qui détruise toute chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Mon arc sera dans la nue; et à sa vue je me souviendrai de l’alliance éternelle entre moi et la terre, et toute âme vivante et toute chair qui est sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dieu dit à Noé: Tel est le signe de l’alliance que j’ai établi entre moi et toute chair qui est sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Or, les fils de Noé qui sortirent de l’arche étaient Sem, Cham et Japhet; Cham fut le père de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Tels sont les trois fils de Noé, pères des hommes qui furent semés sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noé commença à travailler à la terre, et il planta une vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Et il but du vin, et, s’étant enivré, il se mit nu en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Or, Cham, le père de Chanaan, vit la nudité de son père, et il s’en alla le dire à ses deux frères au dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Mais Sem et Japhet ayant pris un manteau, l’étendirent ensemble sur leurs épaules, s’approchèrent à reculons, et cachèrent la nudité de leur père; leur visage regardait à l’opposé, et ils ne virent point la nudité de leur père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Or, Noé, étant sorti du sommeil causé par le vin, apprit ce qu’avait fait à son sujet son fils puîné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Et il dit: Maudit soit l’esclave Chanaan; il sera le serviteur de ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Il dit ensuite: Béni soit le Seigneur, le Dieu de Sem, et l’esclave Chanaan sera serviteur de Sem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Que Dieu multiplie Japhet, que celui-ci habite sous les tentes de Sem, et que Chanaan soit son esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Noé vécut, après le déluge, trois cent cinquante ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Et tous les jours de Noé formèrent neuf cent cinquante ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Voici les générations des fils de Noé Sem, Cham et Japhet; des fils leur naquirent après le déluge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Fils de Japhet: Gomer, Magog, Madaï, Javan, Elisa, Thubal, Mosoch et Thiras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Fils de Gomer: Ascenez, Riphat, et Thogorma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Fils de Javan: Elisa, Tharsis, Cettim et Dodanim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Ceux-ci sont les pères des gentils, qui se partagèrent les îles et les eurent pour territoire, chacun selon sa langue, par tribus, par nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Fils de Cham: Chus, Mesraïm, Phuth et Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Fils de Chus: Saba, Hevila, Sabatha, Regma et Sabathaca. Fils de Regma: Saba et Dadan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Et Chus engendra Nemrod: celui-ci commença à être puissant sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Il était grand chasseur devant le Seigneur; c’est pourquoi l’on dit: Grand chasseur comme Nemrod devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Le commencement de son royaume fut Babylone, puis il eut Arach, Archad, Chalané, et la terre de Sennaar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De cette terre sortit Assur, qui bâtit Ninive, et la ville de Rhooboth et Chalé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Et Ressen, grande ville, entre Ninive et Chalé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mesraïm engendra les Ludim, les Ananim, les Laabim, les Nephtuïm,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Les Phétrusim, les Chasluïm (d’où est sorti Philistin) et les Caphtorins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Chanaan engendra Sidon son premier-né, puis le Hétéen, le Jébuséen,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'L’Amorrhéen, le Gergéséen, l’Évéen, l’Arucéen,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'L’Asennéen, l’Aradien, le Samaréen et l’Amathéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Après cela, les tribus des Chananéens se dispersèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Les limites des Chananéens étaient la côte depuis Sidon jusqu’à Gérara et Gaza; puis elles s’étendirent jusqu’à Sodome et Gomorrhe, et passèrent par Adama et Séboïm jusqu’à Léba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Tels furent les fils de Cham et leurs tribus, selon leurs langues, par contrées, et par nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Sem, frère de son puîné Japhet, fut père aussi, et eut Héber de l’un de ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Fils de Sem: Elam, Assur, Arphaxad, Lud, Aram et Caïnan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Fils d’Aram: Hus, Hul, Gether et Mès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arphaxad engendra Salé, et Salé engendra Héber.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'D’Héber naquirent deux fils, nommés, l’un Phaleg, parce que de son temps la terre fut partagée, et l’autre Jectan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Or, Jectan engendra Elmodad, Saleph, Asarmoth, Jaré,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Aduram, Uzal, Décla,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Ebal, Abimaël, Saba,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Hévila et Jobab: tels furent les fils de Jectan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Ils habitèrent depuis Messa jusqu’à Séphar, montagne de l’Orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Tels furent les fils de Sem et leurs tribus, selon leurs langues, par contrées et par nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Telles furent les tribus des fils de Noé, par familles et nations; et c’est ainsi que les fils de Noé peuplèrent les pays des nations, sur la terre, après le déluge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Toute la terre avait alors une même parole; il y avait une seule langue pour tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Et il arriva qu’en s’éloignant de l’Orient, ils trouvèrent en la terre de Sennaar une plaine où ils s’établirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Et chacun dit à son voisin: Allons, façonnons des briques et faisons-les cuire au feu. La brique leur servit donc de pierre, et le bitume de ciment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Puis ils dirent: Allons, bâtissons-nous une ville et une tour dont la tête ira jusqu’au ciel, et faisons-nous un nom, avant de nous disséminer sur toute la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Le Seigneur descendit voir la ville et la tour que bâtissaient les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Et il dit: Les voilà une seule famille, avec une seule et même langue, et s’ils ont commencé par de tels travaux, rien désormais ne pourra échouer de tout ce qu’ils entreprendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Allons, et étant descendus, confondons ici leur langage de telle sorte que nul n’entende plus la parole de son voisin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Et de ce lieu, Dieu les dispersa sur la face de toute la terre, et ils cessèrent de bâtir la ville et la tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'À cause de cela, ce lieu fut appelé Babel (confusion), parce que là le Seigneur confondit les langues de toute la terre, et dispersa les hommes sur la face de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Or, voici les générations de Sem: le fils Sem avait cent ans lorsqu’il engendra Arphaxad, deux ans après le déluge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Sem vécut, après avoir engendré Arphaxad, cinq cents ans; il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arphaxad vécut cent trente-cinq ans, et il engendra Salé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Et Arphaxad vécut, après avoir engendré Salé, quatre cents ans, et il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Salé vécut cent trente ans, et il engendra Héber.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Et Salé vécut, après avoir engendré Héber, trois cent trente ans; il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Héber vécut cent trente-quatre ans, et il engendra Phaleg.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Et Héber vécut, après avoir engendré Phaleg, deux cent soixante-dix ans; il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Phaleg vécut cent trente ans, et il engendra Réhu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Et Phaleg vécut, après avoir engendré Réhu, deux cent neuf ans; il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Réhu vécut cent trente-deux ans, et il engendra Sarug.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Et Réhu vécut, après avoir engendré Sarug, deux cent sept ans; il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Sarug vécut cent trente ans, et il engendra Nachor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Et Sarug vécut, après avoir engendré Nachor, deux cents ans; il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nachor vécut cent soixante-cinq ans, et il engendra Tharé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Et Nachor vécut, après avoir engendré Tharé, cinq cent vingt-cinq ans; il engendra des fils et des filles, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Tharé vécut soixante ans, et il engendra Abram, Nachor et Aram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Or voici les générations de Tharé: Tharé engendra Abram, Nachor et Aram, lequel engendra Lot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Et Aram mourut devant son père Tharé, en la terre où il était né, au pays des Chaldéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Et Abram ainsi que Nachor épousèrent des femmes. Le nom de la femme d’Abram était Sara; et le nom de la femme de Nachor, Melcha, fille d’Aran, père de Melcha et d’Iescha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sara était stérile, et elle n’enfanta point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Tharé prit Abram son fils, et Lot fils d’Aran, son petit-fils, et Sara, femme d’Abram, son fils, et il les emmena du pays des Chaldéens pour être transportés en la terre de Chanaan; ils allèrent ainsi jusqu’à Haran, et ils y demeurèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Et tous les jours de Tharé, en la terre de Haran, formèrent deux cent cinq ans, et il mourut à Haran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Le Seigneur dit alors à Abram: Sors de ta terre, de ta famille, et de la maison de ton père, pour te rendre en la terre que je te montrerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Je ferai sortir de toi un grand peuple; je te bénirai, je glorifierai ton nom, et il sera béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Je bénirai ceux qui te béniront; ceux qui te maudiront, je les maudirai, et en toi SERONT BÉNIES TOUTES LES tribus de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Et Abram s’en alla, comme avait dit le Seigneur, et Lot partit avec lui. Or, Abram avait soixante-quinze ans lorsqu’il sortit de Haran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Abram prit donc Sara, sa femme, Lot, fils de son frère, tout ce qui leur appartenait, tout ce qu’ils avaient acquis, toutes les âmes qu’ils avaient acquises dans Haran; et ils partirent pour passer en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Abram traversa cette terre dans toute sa longueur jusqu’au territoire de Sichem, vers le grand chêne. Or, les Chananéens habitaient alors cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Et le Seigneur apparut à Abram, et il lui dit: À ta race je donnerai cette terre; c’est pourquoi Abram bâtit là un autel au Seigneur qui lui était apparu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Et il alla de ce lieu vers la montagne, à l’orient de Béthel, il y dressa ses tentes, ayant Béthel à l’occident, et Angaï à l’orient; puis il éleva là un autel au Seigneur, et il invoqua le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Ensuite Abram partit, et, ayant marché, il campa dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Il y eut alors une famine en la contrée, et Abram descendit en Égypte pour y séjourner, parce que la famine avait prévalu dans le pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Or, il arriva qu’Abram, près d’entrer en Égypte, dit à Sara, sa femme: Je sais que tu es une femme très belle;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Il adviendra donc, quand les Égyptiens t’auront vue, qu’ils diront: C’est sa femme; alors ils me tueront, et ils s’empareront de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Dis donc Je suis sa sœur, afin qu’à cause de toi je sois mieux traité, et qu’en ta considération j’aie la vie sauve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Et lorsque Abram fut entré en Égypte, les Égyptiens virent que sa femme était très-belle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Les officiers du Pharaon la virent aussi; ils la vantèrent devant le Pharaon, et ils la conduisirent en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'À cause d’elle, ils traitèrent bien Abram, et il eut des brebis, des bœufs, des ânes, des serviteurs, des servantes, des mulets et des chameaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mais Dieu envoya au Pharaon et à sa famille de grandes et cruelles afflictions, à cause de Sara, femme d’Abram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Et le Pharaon ayant appelé Abram, lui dit: Pourquoi as-tu fait cela, et ne m’as-tu pas dit: C’est ma femme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Pourquoi as-tu dit: C’est ma sœur? Alors je l’ai prise pour qu’elle fût ma femme; or, maintenant voici ta femme devant toi; reprends-la, et pars aussitôt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Le Pharaon prescrivit à des hommes d’escorter Abram, sa femme, et tout ce qui lui appartenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Abram revint donc de l’Égypte avec sa femme, et tout ce qui lui appartenait; et Lot était avec lui dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram était fort riche en bestiaux, en argent et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Il revint au lieu d’où il était venu, dans le désert, vers Béthel, là où ses tentes avaient d’abord été, entre Béthel et Angaï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Au lieu même de l’autel qu’il y avait érigé au commencement, et il y invoqua le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Lot, qui accompagnait Abram, avait aussi des brebis, et des bœufs, et des tentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Or, cette terre ne pouvait suffire à leur commun séjour, car leurs richesses étaient nombreuses; cette terre ne pouvait donc suffire à leur séjour commun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Aussi une rixe survint-elle entre les pâtres des troupeaux d’Abram et les pâtres des troupeaux de Lot. Or, les Chananéens et les Phéréséens habitaient alors cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Abram dit à Lot: Qu’il n’y ait point de rixe entre moi et toi, entre mes pâtres et tes pâtres, car nous sommes frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'N’as-tu pas là devant toi toute la terre? Sépare-toi de moi; si tu vas à gauche, j’irai à droite; si tu vas à droite, j’irai à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Et Lot, ayant levé les yeux, vit toute la rive du Jourdain tout arrosée, comme elle était avant que Dieu eût bouleversé Sodome et Gomorrhe, semblable au paradis de Dieu, ou à la terre d’Égypte, jusqu’aux confins de Zogora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Lot choisit pour lui toute la rive du Jourdain, et il partit, s’éloignant de l’orient; chacun d’eux se sépara de son frère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram demeura en la terre de Chanaan, et Lot habita la ville des riverains, et il dressa ses tentes à Sodome.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Or, les hommes de Sodome étaient très-méchants et grands pécheurs devant Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Après que Lot se fut séparé d’Abram, Dieu dit à celui-ci Regarde de tes yeux, et vois, du lieu où tu es, le nord et le midi, l’orient et l’occident,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Parce que la terre que tu vois, je te la donnerai pour toi et ta race à toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Je multiplierai ta race comme le sable de la terre; si quelqu’un peut compter le sable de la terre, il pourra aussi compter ta postérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Pars, traverse cette contrée dans sa longueur et dans sa largeur, parce que je la donnerai à toi et à ta race pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Et, ayant levé ses tentes, Abram vint demeurer vers le chêne de Mambré qui était en Hébron, et il bâtit en ce lieu un autel au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Or, il arriva que pendant les règnes d’Amarphal, roi de Sennaar, et d’Arioch, roi d’Ellasar; Chodollo gomor, roi d’Élam, et Thargal, roi des nations');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Firent la guerre contre Balla, roi de Sodome, et Barsa, roi de Gomorrhe, et Sennaar, roi d’Adamą, et Symobor, roi de Séboïm, et le roi de Balac (aujourd’hui Ségor).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Tous ces derniers se confédérèrent dans le vallon Salé (aujourd’hui mer des Sels).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Pendant douze ans ils avaient servi Chodollogomor; mais dans la treizième année ils se révoltèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Et, en la quatorzième année, Chodollogomor arriva avec les rois ses alliés; ils vainquirent les géants d’Âsvaroth et de Carnaï, ainsi que les nations puissantes leurs alliées, et les Omméens de la ville de Savé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Et les Horrhéens qui habitent les montagnes de Séir, jusqu’au térébinthe de Phara, dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Puis, s’étant retournés, ils vinrent vers la fontaine du jugement, aujourd’hui Cadès, et ils vainquirent tous les chefs d’Amalec ainsi que les Amorrhéens qui habitent Asason-Thamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Mais le roi de Sodome sortit, et avec lui le roi de Gomorrhe, le roi d’Adama, le roi de Séboïm, le roi de Balac, aujourd’hui Ségor, et ils se rangèrent en bataille dans le vallon Salé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Contre Chodollogomor, roi d’Élam, Thargal, roi des nations, Amarphal, roi de Sennaar, et Arioch, roi d’Ellabar; cinq rois contre quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Or, le vallon Salé n’était que puits de bitume; bientôt le roi de Sodome s’enfuit avec le roi de Gomorrhe; ils furent vaincus, et ceux qui survécurent s’enfuirent dans les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Les vainqueurs prirent tous les chevaux de ceux de Sodome, tous leurs vivres; et ils partirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ils prirent aussi, avec tout son avoir, Lot, fils du frère d’Abram, car il habitait Sodome; et ils s’éloignèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Or, l’un de ceux qui s’étaient sauvés, survenant, apprit ces choses à Abram, le passager sur cette terre, qui demeurait auprès du chêne de l’Amorrhéen Mambré, frère d’Eschol, et frère d’Onan, tous alliés d’Abram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Celui-ci, ayant appris que son neveu Lot était captif, compta ses serviteurs au nombre de trois cent dix-huit, et il poursuivit les ravisseurs jusqu’à Dan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'La nuit venue, il tomba sur eux, avec ses serviteurs, les battit, et les chassa jusqu’à Hoba, qui est à la gauche de Damas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Il ramena tous les chevaux de Sodome, Lot son neveu, tous ses serviteurs, les femmes, et le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Le roi de Sodome sortit alors à sa rencontre, après avoir échappé au carnage fait par Chodollogomor et les rois ses alliés, dans la vallée de Saby (c’était le champ de bataille des rois).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Et Melchisédech, roi de Salem (Jérusalem), offrit des pains et du vin; car il était prêtre du Dieu Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Il bénit Abram, en disant: Béni soit Abram du Dieu Très-Haut qui a créé le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Béni soit le Dieu Très-Haut qui t’a soumis tes ennemis. Et Abram lui donna la dîme de toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Le roi de Sodome dit à Abram: Donne-moi les hommes, et prends pour toi les chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram dit au roi de Sodome: J’étendrai la main vers le Seigneur Dieu, le Très-Haut qui a créé le ciel et la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Pour attester que je ne veux pour moi rien de ce qui t’appartient, depuis la corde jusqu’à la courroie de la sandale, de peur que tu ne puisses dire: J’ai enrichi Abram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'J’excepte ce que les jeunes gens ont mangé, et la part de mes alliés Eschol, Onan et Mambré, qui prendront ce qui leur revient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Après ces choses, Abram dans une vision entendit la parole de Dieu qui lui disait Sois sans crainte, Abram, je te couvre de ma protection; ta récompense sera immense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abram répondit: Seigneur Dieu, que me donnerez-vous? Je m’en vais sans enfants; mais j’ai le fils de Masec, ma servante née chez moi; c’est Damas-Eliézer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Abram ajouta: Puisque vous ne m’avez point accordé de postérité, mon serviteur né chez moi recueillera mon héritage!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Et soudain la voix du Seigneur se fit entendre et lui dit Ce n’est pas lui qui sera ton héritier; il naîtra de toi celui qui aura ton héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Ensuite le Seigneur l’emmena dehors; et lui dit: Regarde le ciel, compte les étoiles si tu le peux telle,. ajouta-t-il, sera ta postérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abram crut en Dieu, et sa foi lui fut imputée à justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Le Seigneur lui dit: Je suis le Dieu qui t’ai amené de la terre des Chaldéens pour te donner en héritage cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Il répondit: Seigneur Dieu, à quoi reconnaîtrai-je que j’en hériterai?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Dieu lui dit: Prends une génisse de trois ans, une chèvre de trois ans, un bélier de trois ans, un pigeon et une colombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Abram prit les victimes, les coupa par moitiés, et plaça les moitiés vis-à-vis les unes des autres; mais il ne divisa pas les volatiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Et des oiseaux descendirent sur les corps, sur les moitiés de corps, et Abram s’assit à côté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Vers le coucher du soleil, Abram tomba en extase; une terreur profonde pleine de ténèbres s’empara de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Et il fut dit à Abram: Apprends que ta postérité habitera une terre étrangère; on les réduira en servitude, on les opprimera, et on les humiliera pendant quatre cents ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mais la nation à laquelle ils seront soumis, je la jugerai; ensuite ils en sortiront pour venir ici avec de grandes richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Quant à toi, tu t’en iras en paix vers tes pères, après avoir joui d’une heureuse vieillesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Et, à la quatrième génération, ta race reviendra ici, car jusqu’à présent les crimes des Amorrhéens n’ont pas encore comblé la mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Après le coucher du soleil, une flamme s’éleva, l’on vit un foyer lançant de la fumée, et des lampes de feu qui passaient entre les moitiés coupées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En ce jour-là, le Seigneur établit une alliance avec Abram, disant: Je donnerai cette, terre à ta race depuis le fleuve d’Égypte jusqu’à l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Je lui donnerai: les Cénéens, les Cénézéens, et les Cedmonéens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Et les Hettéens, les Phérézéens, et les Raphaïms,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Et les Amorrhéens, les Chananéens, les Évéens, les Gergéséens et les Jébuséens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sara, femme d’Abram, ne lui avait point donné d’enfants; elle avait une servante égyptienne nommée Agar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Elle dit donc à Abram: Le Seigneur a clos mes entrailles pour que je n’enfante point: Approche-toi de ma servante, afin que d’elle il me vienne un enfant. Abram prêta l’oreille à la parole de Sara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Et Sara, femme d’Abram, ayant pris l’Égyptienne Agar sa servante, après dix ans de séjour en la terre de Chanaan, la donna pour femme à Abram son mari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Celui-ci s’approcha d’Agar, et elle conçut; bientôt elle vit qu’elle portait un enfant; et sa maîtresse fut méprisée par elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Sara dit alors à Abram: Tu me traites injustement; j’ai placé sur ton sein ma servante; elle a vu qu’elle porte un enfant, et je suis méprisée par elle; que Dieu juge entre toi et moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram lui répondit: Voici ta servante dans tes mains; uses-en avec elle comme il te sera agréable. Et Sara la maltraita, et elle s’enfuit loin de sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'L’Ange du Seigneur vint la trouver dans le désert auprès d’une fontaine, celle qui est sur le chemin de Sur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Et lui dit: Agar, servante de Sara, d’où viens-tu, et où vas-tu? Je fuis, répondit-elle, loin de la face de Sara ma maîtresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'L’Ange du Seigneur ajouta: Retourne vers ta maîtresse, humilie-toi, et courbe-toi sous ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Il dit ensuite: Je multiplierai et multiplierai ta race; elle sera innombrable par sa multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Et l’Ange du Seigneur ajouta: Te voilà enceinte, tu enfanteras un fils, auquel tu donneras le nom d’Ismaël, parce que le Seigneur a ouï ton humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Ce sera un homme rude; ses mains seront sur tous et les mains de tous sur lui, et il habitera en face de tous ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Alors Agar invoqua le nom du Seigneur qui lui parlait, disant: Dieu, vous m’avez regardée; car, se dit-elle, j’ai vu en face celui qui m’est apparu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'À cause de cela, elle nomma la source: puits de celui que j’ai vu en face. Ce puits est entre Cadès et Barad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Bientôt Agar enfanta un fils à Abram, et Abram donna au fils que lui avait enfanté Agar, le nom d’Ismaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Or Abram avait quatre-vingt-six ans, lorsque Agar lui enfanta Ismaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Abram atteignit sa quatre-vingt-dix-neuvième année, et le Seigneur lui apparut, disant: Je suis ton Dieu; cherche à plaire à mes yeux; sois sans péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'J’établirai mon alliance entre moi et toi, et je te multiplierai beaucoup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Abram tomba la face contre terre, et Dieu lui parla, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Et moi voici que je fais alliance avec toi, tu seras le père d’une multitude de nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Et tu ne t’appelleras plus Abram, mais ton nom sera Abraham, parce que je t’ai fait le père de beaucoup de nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Et je t’augmenterai beaucoup, beaucoup; je te constituerai père de plusieurs peuples, des rois proviendront de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'J’établirai mon alliance entre moi et entre toi, et entre ta race après toi, dans toutes ses générations; alliance éternelle par laquelle je serai ton Dieu et le Dieu de ta race après toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Je te donnerai, et après toi à ta race, la terre que tu habites, toute la terre de Chanaan, pour héritage perpétuel, et je serai votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Dieu ajouta: De ton côté, tu maintiendras mon alliance, toi et ta postérité, dans toutes les générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Voici l’alliance que tu maintiendras entre moi et vous, c’est-à-dire ta postérité en toutes ses générations: Tout mâle parmi vous sera circoncis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Vous serez circoncis en la chair de votre prépuce, et ce sera le signe de l’alliance entre moi et vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Parmi vous, l’enfant de huit jours sera circoncis: tout enfant mâle en vos générations, tout serviteur, né dans votre maison, ou acheté à prix d’argent, provenant d’étrangers et non de votre sang,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Le serviteur né dans votre maison, et l’esclave acheté à prix d’argent, seront circoncis; ce sera là mon alliance sur votre chair, alliance éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Le mâle à qui, le huitième jour, on n’aura point circoncis la chair du prépuce, cette âme sera exterminée au milieu de sa famille, parce qu’elle aura violé mon alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Dieu dit ensuite à Abraham: Sara ta femme ne s’appellera plus Sara; Sarra sera son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Je la bénirai, je te donnerai d’elle un enfant que je bénirai, et qui sera père de plusieurs peuples; des rois de nations tireront de lui leur origine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Abraham tomba la face contre terre; il rit, et il se dit en lui-même au fond du cœur: Un fils naîtra-t-il de moi dans ma centième année? Sarra à quatre-vingt-dix-neuf ans, enfantera-t-elle?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Et Abraham dit à Dieu: Que mon Ismaël vive devant vous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Mais Dieu lui repartit: Oui, voici que Sarra ta femme t’enfantera un fils que tu appelleras Isaac, et j’établirai mon alliance avec lui, alliance éternelle, par laquelle je serai son Dieu, et le Dieu de sa race après lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Par rapport à Ismaël, je t’ai aussi exaucé: je l’ai béni; je l’augmenterai, et je le multiplierai beaucoup. Il engendrera douze nations, et je le ferai père d’un grand peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mais c’est avec Isaac que te doit donner Sarra, pareille époque, en l’année qui va suivre, que j’établirai mon alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Et Dieu, cessant de parler, remonta au-dessus d’Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Aussitôt, Abraham prit Ismaël son fils, et tous ses serviteurs nés en sa maison, et tous ses esclaves achetés, et tout mâle de sa maison, et il les circoncit, le jour même, selon ce qu’avait dit le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Or, Abraham avait quatre-vingt-dix-neuf ans lorsqu’il se circoncit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Et Ismaël son fils avait treize ans quand il le circoncit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Ce jour-là furent circoncis Abraham et son fils Ismaël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Et tous les hommes de sa maison, et ses domestiques, et ses esclaves achetés des nations étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Et Dieu lui apparut près du chêne de Mambré, tandis qu’il était assis sur la porte de sa tente à midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Comme il levait les yeux, il aperçut trois hommes placés au-dessus de lui; et les ayant vus, il courut de la porte de sa tente à leur rencontre, et il se prosterna jusqu’à terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'En disant: Seigneur, si j’ai trouvé grâce devant vous, ne passez point outre devant votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Que l’on prépare l’eau, que mes serviteurs vous lavent les pieds et rafraîchissez-vous sous le chêne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Pour moi, j’apporterai du pain, et vous mangerez; puis, vous poursuivrez votre voyage: c’est pour cela que vous êtes venus vers votre serviteur. Le Seigneur dit: Qu’il soit fait comme tu le demandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham se hâta donc d’entrer sous sa tente vers Sarra, et il lui dit: Dépêche-toi, pétris trois mesures de fleur de farine, et fais-nous cuire des pains sous la cendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Puis, Abraham courut aux bœufs, et prit un beau petit veau bien tendre, qu’il donna au serviteur, en le pressant de l’apprêter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'De son côté, il prit du beurre et du lait, ainsi que le veau qu’il avait fait préparer, et il plaça le tout devant ses hôtes qui mangèrent. Lui-même cependant se tenait devant eux sous le chêne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Le Seigneur lui dit: Où est Sarra ta femme? Il répondit: La voici sous la tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Je reviendrai, dit le Seigneur, vers toi à pareille époque, et Sarra ta femme aura un fils. Or, Sarra entendit derrière la porte de la tente où elle était.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Or, Abraham et Sarra étaient vieux, ayant vécu bien des jours; Sarra avait même cessé d’avoir ce qui arrive aux femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Sarra rit donc en elle-même, disant: Cela ne m’est point encore arrivé jusqu’ici, et mon seigneur est un vieillard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Mais le Seigneur dit à Abraham: Pourquoi Sarra a-t-elle ri en elle-même, disant: Enfanterai-je véritablement, moi qui suis devenue vieille?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Est-ce que rien est impossible à Dieu? Je reviendrai près de toi à pareille époque, et Sarra aura un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Alors Sarra nia, disant: Je n’ai point ri, car elle eut peur; et le Seigneur lui dit: Non, mais tu as ri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Et, s’étant levés de ce lieu, les trois hommes regardèrent du côté de Sodome et de Gomorrhe, et Abraham partit avec eux pour les reconduire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Bientôt le Seigneur dit: Ne dévoilerai-je point les choses que je fais à Abraham, mon serviteur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'À lui qui doit devenir père d’une nation grande et nombreuse, et en qui seront bénies toutes les nations de la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Car je sais qu’il donnera ses ordres à ses fils et à sa maison après lui; et ils garderont les voies du Seigneur en pratiquant l’équité et la justice, afin que le Seigneur accomplisse, en faveur d’Abraham, toutes les choses qu’il lui a dites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Le Seigneur ajouta: Le cri de Sodome et de Gomorrhe s’est élevé jusqu’à moi, et leurs péchés sont énormes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Étant donc descendu, je verrai si leurs actions répondent à ce cri qui m’est parvenu; et si non, je le saurai...');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'S’étant alors éloignés, les hommes s’en allèrent à Sodome, et Abraham resta devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Abraham s’approcha et dit: Perdrez-vous le juste avec les impies, et le juste sera-t-il comme l’impie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'S’il y a cinquante justes dans la ville, les perdrezvous? Ne ferez-vous point grâce à toute la contrée, à cause des cinquante justes, s’ils sont dans la ville?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Non, vous ne ferez point cette action de tuer le juste avec les impies, car le juste serait comme l’impie; il n’en sera point ainsi; vous qui jugez toute la terre, vous ne rendriez point justice!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Le Seigneur repartit: S’il y a cinquante justes en la ville de Sodome, j’épargnerai, à cause d’eux, toute la ville et la contrée entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Et Abraham répondant Maintenant, dit-il, j’ai commencé à parler à mon Seigneur, moi, terre et poussière!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Si les justes se réduisent à quarante-cinq, détruirez-vous toute la ville à cause des cinq? Le Seigneur dit: S’il s’y trouve quarante-cinq justes, je ne la détruirai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Et Abraham, continuant de parler au Seigneur, dit: S’il s’en trouve quarante? Le Seigneur reprit: En faveur des quarante, je ne la détruirai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Abraham dit ensuite: Qu’en sera-t-il, Seigneur, si je parle encore? S’il s’en trouve trente? Le Seigneur dit: En faveur des trente, je ne la détruirai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Abraham ajouta Puisqu’il m’est donné de parler au Seigneur, s’il s’en trouve vingt? Et le Seigneur répondit: Si j’en trouve vingt, je ne la détruirai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Et Abraham dit: Seigneur, parlerai-je encore une seule fois? S’il s’en trouve dix? Et le Seigneur dit: En faveur des dix, je ne la détruirai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Lorsqu’il eut cessé de parler à Abraham, le Seigneur partit, et celui-ci retourna au lieu qu’il habitait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Cependant, les deux Anges entrèrent à Sodome sur le soir, comme Lot était assis devant la porte de Sodome, et aussitôt qu’il les aperçut, il s’avança à leur rencontre, se prosternant la face contre terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Et il dit: Seigneurs, voyez, tournez vos pas vers la maison de votre serviteur, reposez-vous, lavez-y vos pieds, et le matin, vous étant levés, vous poursuivrez votre voyage. Ils répondirent: Non, nous nous reposerons sur la place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mais il les pressa tellement qu’ils lui cédèrent, et entrèrent en sa maison. Là, il leur fit un festin; il mit cuire pour eux des pains sans levain, et ils mangèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Et avant le coucher, les hommes de la ville de Sodome entourèrent la maison, depuis le jeune homme jusqu’au vieillard; tout le peuple à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Ils appelaient Lot, et ils lui disaient: Où sont les hommes qui sont entrés chez toi, à la nuit; amène-nous-les, afin que nous ayons commerce avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot sortit vers eux, devant le vestibule, en fermant derrière lui la porte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Et il leur dit: Non, mes frères, vous ne ferez point ce mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'J’ai deux filles qui n’ont pas connu d’hommes, je vais vous les amener, et vous en userez comme il vous plaira; mais ne faites rien d’inique contre ces hommes, car ils sont abrités sous le toit de ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Ils lui répondirent Va-t’en d’ici; tu n’es qu’un étranger: est-ce à toi d’être juge? Nous allons tout à l’heure te traiter plus mal qu’eux; et, faisant grande violence à Lot, ils s’approchèrent pour briser sa porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Alors, les deux hommes, étendant les mains, attirèrent Lot auprès d’eux dans la maison, dont ils refermèrent la porte aussitôt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Quant aux hommes qui l’assiégeaient, les voyageurs les frappèrent de cécité, du petit au grand, de sorte qu’ils ne furent plus capables de chercher la porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Les voyageurs dirent alors à Lot: As-tu ici des gendres, ou des fils, ou des filles? As-tu quelque autre des tiens dans la ville? emmène-les au dehors;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Parce que nous allons détruire ce lieu; car le cri qui s’en élève est monté jusqu’au Seigneur, qui nous a envoyés le détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Lot sortit alors pour parler à ses gendres, ceux qui avaient épousé ses filles, et il leur dit: Levez-vous, et sortez de cette ville, car le Seigneur va l’anéantir; mais, aux yeux de ses gendres, il parut plaisanter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Dès que le jour commença à poindre, les Anges pressèrent Lot, disant: Lève-toi, prends ta femme et les deux filles que tu as chez toi, et sors, de peur que tu ne périsses toi-même, au milieu des iniquités de cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Ils furent saisis d’effroi; mais les Anges prirent par la main Lot, sa femme et ses filles, parce que le Seigneur voulait les sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Dès qu’ils les eurent conduits dehors, ils dirent à Lot: Sauve, sauve la vie; ne regarde pas en arrière, et ne t’arrête en aucun lieu des alentours; réfugie-toi sur la montagne, pour ne pas périr toi-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lot leur dit: Seigneur, je vous en prie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Puisque votre serviteur a trouvé grâce devant vous, et que vous avez glorifié votre justice en me sauvant la vie, considérez que je ne pourrai pas me sauver sur la montagne; je crains d’être atteint par le fléau, et de mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Voyez cette ville si proche qui peut me servir de refuge; elle est petite, et là je serai sauvé. N’est-elle point petite? Ainsi mon âme vivra, grâce à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Le Seigneur lui dit: Je veux encore t’honorer en ceci je promets de ne point détruire la ville dont tu parles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Hâte-toi donc de t’y réfugier, car je ne pourrai rien faire que tu n’y sois arrivé. À cause de cela, Lot donna à cette ville le nom de Ségor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Comme le soleil se levait sur la terre, Lot entra dans Ségor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Et le Seigneur, de sa propre main, fit pleuvoir du haut du ciel, sur Sodome et Gomorrhe, du soufre et du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Il bouleversa ces deux villes, et tous les alentours, et tous ceux qui habitaient les villes, et tout ce que produisait la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Cependant, la femme de Lot regarda en arrière, et elle devint comme une colonne de sel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Dès l’aube du jour, Abraham se rendit au lieu où il s’était tenu devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Il regarda du côté de Sodome, de Gomorrhe et des alentours il vit que les flammes sortaient de terre comme la vapeur d’une fournaise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Ainsi, pendant qu’il détruisait toutes les villes voisines, Dieu se souvint d’Abraham, et retira Lot du milieu de la catastrophe, tout en bouleversant les villes que Lot habitait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot sortit ensuite de Ségor, et s’arrêta sur la montagne avec ses deux filles, car il avait eu peur de demeurer à Ségor; il s’établit dans une caverne avec ses deux filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'L’aînée dit à la plus jeune: Notre père est vieux, et il n’est plus personne sur la terre pour s’approcher de nous selon l’usage universel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Allons donc, faisons boire du vin à notre père, et dormons avec lui; ainsi nous susciterons à notre père une postérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Et elles firent boire du vin à leur père cette nuit même; puis l’aînée l’alla trouver, dormit avec lui; et il n’en sut rien, ni dans son sommeil, ni à son réveil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Le lendemain arrivé, l’aînée dit à la plus jeune: J’ai dormi hier avec notre père; faisons-lui boire encore du vin cette nuit, et tu l’iras trouver, tu dormiras avec lui, et nous susciterons à notre père une postérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Et cette nuit même elles firent boire du vin à leur père; la plus jeune l’alla trouver, dormit avec lui, et il n’en sut rien, ni dans son sommeil, ni à son réveil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Et les deux filles de Lot conçurent de leur père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'L’aînée enfanta un fils auquel elle donna le nom de Moab, disant: Il est de mon père. C’est le père des Moabites de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Pareillement la plus jeune enfanta un fils, et elle lui donna le nom d’Ammon, disant: Il est de ma race. C’est le père des Ammonites de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Abraham se transporta dans la terre du midi, et il demeura entre Cadès et Sur, puis il vint habiter en Gérare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Abraham dit alors de sa femme Sarra: Elle est ma sœur; car il avait crainte de dire: C’est ma femme, de peur qu’à cause d’elle les hommes de la ville ne le tuas sent. Et Abimélech, roi de Gérare, fit enlever Sarra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Or, le Seigneur entra vers Abimélech pendant son sommeil, la nuit, et dit: Tu vas mourir à cause de la femme que tu as prise, car elle est mariée à un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimélech ne s’était point encore approché d’elle; il dit donc Seigneur, perdrez-vous une nation juste pour avoir ignoré?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Lui-même ne m’a-t-il pas dit: C’est ma sœur? Elle-même n’a-t-elle point dit: Il est mon frère? C’est dans la pureté de mon cœur et l’équité de mes mains que j’ai fait cela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Le Seigneur lui dit, toujours pendant son sommeil: Je sais que tu as agi avec un cœur pur; aussi t’ai-je préservé de pécher contre moi. Je ne t’ai point laissé t’approcher de cette femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Rends-la donc à son mari; c’est un prophète qui priera pour toi, et tu.vivras; mais si tu ne la rends point, sache que tu périras avec tout ce qui est à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Abimélech s’étant hâté de se lever de grand matin, appela tous ses serviteurs, et leur répéta toutes ces paroles, et tous ces hommes eurent grande crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Abimélech appela aussi Abraham, et il lui dit: Pourquoi nous as-tu traités de la sorte; avions-nous péché envers toi pour que tu fisses tomber ainsi sur moi et sur mon royaume ce grand péché? Tu m’as fait ce que personne ne ferait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Et Abimélech ajouta: En vue de quoi en as-tu agi de la sorte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham répondit: Je me suis, en effet, dit: Peut-être n’y a-t-il point de piété en ce lieu, et vont-ils me tuer à cause de ma femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Du reste, elle est véritablement ma sœur de père et non de mère, et elle est devenue ma femme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Et il est advenu, lorsque Dieu m’a fait sortir de la maison de mon père, que j’ai dit à ma femme: Tu me rendras cet équitable service en tous lieux où nous irons; dis de moi: C’est mon frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Abimélech prit mille doubles drachmes, et des brebis, et des veaux, et des serviteurs et des servantes, qu’il donna à Abraham, et il lui rendit sa femme Sarra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Et Abimélech dit à Abraham: Voilà ma terre devant toi, séjourne où il te plaira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Il dit aussi à Sarra: Tu vois, je donne à ton frère mille drachmes; elles seront pour faire respecter ton visage et celui de tes suivantes; sois désormais véridique en tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Abraham pria Dieu, et Dieu guérit Abimélech, sa femme et ses servantes, et elles enfantèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Car le Seigneur avait fermé toutes les entrailles, en la maison d’Abimélech, à cause de Sarra, femme d’Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Ensuite le Seigneur visita Sarra, comme il avait dit; il accomplit la promesse qu’il lui avait faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Et ayant conçu, elle enfanta un fils à Abraham, dans sa vieillesse, au temps prédit par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abraham donna au fils nouveau-né que lui avait enfanté Sarra, le nom d’Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Et Abraham circoncit Isaac le huitième jour, comme l’avait ordonné Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham avait cent ans, lorsque naquit son fils Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Sarra dit alors: Le Seigneur m’a causé un doux rire; quiconque l’apprendra se réjouira avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Puis elle ajouta: Qui ira dire à Abraham que Sarra allaite un enfant, et que j’ai enfanté un fils dans ma vieillesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Et l’enfant se fortifia, il fut ensuite sevré, et Abraham fit un grand festin le jour où fut sevré son fils Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Sur ces entrefaites, Sarra ayant vu le fils d’Agar l’Égyptienne, qui était né à Abraham, jouant avec son fils Isaac,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Dit à Abraham: Chasse cette servante et son fils, car le fils de cette servante ne partagera pas ton héritage avec Isaac mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Cette parole, au sujet de son fils, parut très-dure à Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Mais le Seigneur dit à Abraham: Que ceci ne te semble point dur, ni au sujet de l’enfant, ni au sujet de la servante; tout ce que te dira Sarra tu dois l’écouter, car c’est par Isaac qu’existera ta race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Quant au fils de cette servante, j’en ferai le père d’une grande nation, parce qu’il est de ton sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Abraham se leva donc de grand matin, prit des vivres et une outre d’eau, et les donna à Agar; il mit ensuite l’enfant sur l’épaule d’Agar et la renvoya. Étant donc partie, elle erra dans le désert du côté du puits du serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Mais l’eau de l’outre s’épuisa, et Agar déposa l’enfant au pied d’un sapin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Et, s’étant écartée, elle s’assit à une portée d’arc, en regardant à l’opposé: Que du moins, disait-elle, je ne voie point mourir mon enfant! Elle s’assit donc à l’opposé; et, l’enfant ayant crié, elle pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Dieu entendit la voix de l’enfant du lieu où il était; un ange de Dieu appela Agar du haut du ciel, et il lui dit Agar, qu’y a-t-il? n’aie point crainte; car Dieu a entendu la voix de l’enfant, du lieu où il est.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Lève-toi, prends l’enfant et mène-le par la main: car je le ferai père d’une grande nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Et, Dieu lui ayant ouvert les yeux, elle vit un puits d’eau vive. Alors elle s’avança, remplit l’outre, et fit boire l’enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Or, Dieu était avec l’enfant; il grandit, habitant le désert, et il devint archer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Il demeura au désert, et sa mère le maria à une femme de Pharan en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'En ce temps-là, il advint qu’Abimélech, accompagné d’Ochosath, gardien de ses femmes, et de Phichol, général en chef de ses armées, parla à Abraham, disant: Le Seigneur soit avec toi en toutes tes entreprises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Jure-moi donc et atteste Dieu de ne traiter injustement ni moi, ni ma race, ni mon nom, mais, par égard pour la terre que tu habites, de te comporter envers moi avec la même justice dont j’ai usé envers toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Je le jurerai, répondit Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Et Abraham fit des reproches à Abimélech touchant les puits d’eau vive dont ses serviteurs s’étaient emparés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimélech repartit: Je ne sais point qui t’a fait cela, tu ne me l’as point appris, et je n’en ai rien ouï dire avant aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'En conséquence, Abraham prit des moutons et des bœufs, et les donna à Abimélech, puis tous les deux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Mais Abraham mit à part sept agneaux de brebis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Et Abimélech lui dit: Pourquoi ces sept agneaux de brebis que tu as mis à part?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Abraham répondit: Tu recevras de moi ces sept agneaux, et ils témoigneront que c’est moi qui ai creusé le puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'À cause de cela, il donna à ce lieu le nom de puits du Serment, parce que là ils jurèrent tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Ainsi, ils firent alliance au puits du Serment; et Abimélech, avec Ochosath, gardien de ses femmes, et Phichol, général en chef de ses armées, se leva, et retourna en la terre des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Ensuite, Abraham ensemença un champ vers le puits du Serment; il invoqua en ce lieu le nom du Seigneur Dieu éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Et il fut longtemps passager en la terre des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Il advint alors que Dieu tenta Abraham; il lui dit: Abraham, Abraham. Celui-ci répondit: Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Prends, lui dit Dieu, ton enfant, ton fils chéri, ton Isaac, que tu aimes tant; va en la haute terre, et là, offre-le en holocauste, sur l’une des montagnes que je te dirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Et Abraham, s’étant levé de grand matin, bâta son ânesse; il prit avec lui deux serviteurs et Isaac son fils; puis, ayant fendu le bois pour l’holocauste, il partit, et il arriva le troisième jour au lieu que lui avait dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Et Abraham, ayant levé les yeux, vit le lieu de loin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Et dit à ses serviteurs: Arrêtez-vous ici avec l’ânesse, moi de mon côté j’irai avec l’enfant jusque là-bas; puis après avoir adoré, nous reviendrons auprès de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Abraham prit donc le bois de l’holocauste, et il le donna à porter à Isaac; lui-même porta dans ses mains le feu et le glaive; et ils marchèrent à côté l’un de l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Cependant, Isaac dit à Abraham, son père Père, et celui-ci répondit: Qu’y a-t-il, mon enfant? Isaac reprit Voici le feu et le bois; où est la brebis pour l’holocauste?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham répondit: Dieu se pourvoira lui-même d’une brebis pour l’holocauste, mon enfant, et, ayant marché tous deux ensemble,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Ils arrivèrent au lieu que lui avait dit le Seigneur; Abraham y éleva un autel; il disposa le bois, et, ayant lié Isaac son fils, il le plaça sur l’autel par-dessus le bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Et il étendit la main pour saisir le glaive, afin d’égorger son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Alors un ange du Seigneur l’appela du ciel, disant: Abraham, Abraham; il répondit: Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Et l’ange dit: Ne porte pas la main sur l’enfant ne lui fais rien; car je sais maintenant que tu crains le Seigneur, puisque pour moi tu n’as pas épargné ton fils bien-aimé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Abraham, ayant levé les yeux, regarda; et voilà qu’un bélier se trouvait retenu par les cornes dans les broussailles de Sabec; aussitôt Abraham s’élance, prend le bélier, et l’offre en holocauste, au lieu de son fils Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Abraham appela ce lieu: Le Seigneur a vu; de sorte que l’on dit encore aujourd’hui: sur la montagne le Seigneur est apparu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'L’ange du Seigneur appela une seconde fois Abraham du haut du ciel, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Je l’ai juré par moi-même, dit le Seigneur: parce que tu as fait ce que tu viens de faire, et que, pour moi, tu n’as pas épargné ton fils bien-aimé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Je te bénirai et te bénirai, je multiplierai et multiplierai ta race, comme les étoiles du ciel, comme les grains de sable du rivage des mers, et ta race possédera les villes des ennemis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Et, en ta race, seront bénies toutes les nations de la terre, parce que tu as obéi à ma voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Abraham retourna auprès de ses serviteurs, et ils partirent pour revenir ensemble vers le puits du Serment; Abraham demeura vers le puits du Serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Ensuite un message vint à lui, disant: Melcha a aussi enfanté des fils à Nachor ton frère:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uz d’abord, puis Bayx son frère, et Camuel, père des Syriens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Chazad, Azay, Phaldès, ensuite Jeddar et Bathuel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bathuel a engendré Rebecca: voilà les huit fils que Melcha a enfantés à Nachor, frère d’Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Et sa concubine nommée Rheuma a, de son côté, enfanté Tabec, Taam, Tochos et Mocha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Or, la vie de Sarra atteignit cent vingt-sept ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Et Sarra mourut en la ville d’Arboc, dans la vallée (c’est aujourd’hui Hébron, en la terre de Chanaan). Abraham y vint pour pleurer Sarra et mener grand deuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Ensuite Abraham partit d’auprès de sa morte, et il parla aux fils de Het, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Je suis parmi vous passager et voyageur; accordez-moi donc l’achat d’un sépulcre parmi vous, et, me séparant de ma morte, je l’ensevelirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Les fils de Het répondirent à Abraham, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Non, Seigneur, écoute-nous: Tu es parmi nous un roi suscité de Dieu; ensevelis ta morte en nos sépulcres d’élite; nul de nous ne refusera de te céder son propre sépulcre pour que tu l’y ensevelisses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Et, s’étant levé, Abraham se prosterna devant les fils de Het, peuple de cette terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'En disant: Si votre cœur consent que j’ensevelisse ici ma morte que je ne verrai plus, écoutez-moi, et parlez en ma faveur à Éphron, fils de Saar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Pour qu’il me donne la double caverne qui lui appartient, celle qui fait partie de son champ; qu’il me la cède à prix d’argent, pour être ma sépulture au milieu de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Or, Éphron était assis parmi les fils de Het; et répondant à Abraham, l’Hettéen Éphron parla, les fils de Het l’entendant, ainsi que tous ceux qui entraient dans la ville, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Viens près de moi, Seigneur, et écoute-moi: Le champ et la caverne qu’il contient, je te les donne; je te les donne en présence de tous mes concitoyens; ensevelis ta morte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Abraham se prosterna devant le peuple de cette terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Et il dit à Éphron, en présence du peuple de cette terre: Puisque tu m’es favorable, écoute-moi: reçois le prix du champ, et j’y ensevelirai ma morte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron répondit à Abraham:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Nullement, Seigneur, j’ai bien entendu; la terre est de quatre cents doubles drachmes d’argent; mais qu’est-ce que cela peut faire entre moi et toi? Ensevelis donc ta morte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'À ces paroles d’Ephron, Abraham plaça devant lui l’argent qu’il avait dit, au su des fils de Het: quatre cents doubles drachmes d’argent, éprouvé par les marchands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Ainsi le champ d’Éphron, avec sa double caverne, qui est en face de Mambré, le champ et la caverne, et tous les arbres du champ et tout ce qui se trouvait compris dans ses limites,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Furent acquis à Abraham, en présence des fils de Het, et de tous ceux qui entraient en cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Après cela, Abraham ensevelit Sarra sa femme dans la double caverne du champ, laquelle fait face à Mambré aujourd’hui Hébron, en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Et le champ et la caverne qu’il contenait furent confirmés à Abraham, comme sépulture, par les fils de Het.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham était déjà vieux, ayant vécu bien des jours; et le Seigneur l’avait béni en toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Il dit à son serviteur le plus âgé de sa maison, l’intendant de toutes ses possessions (Eliézer): Mets ta main sous ma cuisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Je veux t’adjurer, par le Seigneur Dieu du ciel et de la terre, de ne pas prendre une femme pour mon fils Isaac parmi les filles des Chananéens, au milieu desquels je suis passager,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Mais d’aller en la terre où je suis né, dans ma tribu, et de ramener de là une femme pour mon fils Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Le serviteur lui dit: Si par hasard la femme ne veut pas revenir ici avec moi, ferai-je retourner ton fils dans la terre d’où tu es venu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham reprit: Garde-toi de faire retourner mon fils en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Le Seigneur Dieu du ciel et de la terre, qui m’a fait sortir de la maison de mon père, et du pays où je suis né, Celui qui m’a parlé, qui m’a fait serment, disant: Je donnerai cette terre à toi et à ta race; lui-même enverra son ange devant toi, et tu ramèneras de là une femme à mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Mais si la femme ne veut point venir ici avec toi, tu seras dégagé de ton serment, seulement ne fais point retourner là-bas mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Et le serviteur mit sa main sous la cuisse d’Abraham son seigneur, et il lui prêta serment sur cette affaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Après quoi, le serviteur prit avec lui dix chamelles, parmi les chameaux de son maître, et une part de tous les objets précieux de son seigneur; et, s’étant mis en marche, il alla en Mésopotamie, dans la ville de Nachor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Comme il était près de la ville, vers le puits des Eaux, sur le soir, au moment où les femmes sortent pour puiser de l’eau, il fit arrêter ses chamelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Et il dit: Seigneur Dieu de mon seigneur Abraham, préparez devant moi une heureuse voie aujourd’hui, et soyez miséricordieux envers mon seigneur Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Je me suis arrêté vers cette fontaine, au moment où les filles des habitants de la ville sortent pour puiser de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Que la vierge à laquelle je dirai: Penche ta cruche afin que je boive, et qui me dira: Bois, et je ferai boire tes chamelles jusqu’à ce qu’elles cessent de boire, soit celle que vous aurez préparée pour votre serviteur Isaac; par là je reconnaîtrai que vous avez été miséricordieux envers mon seigneur Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Il avait à peine achevé ces paroles au fond de son cœur que Rebecca, celle qui était née à Bathuel, fils de Melcha, femme de Nachor, frère d’Abraham, sortait avec une cruche sur l’épaule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'La jeune fille était d’une grande beauté; elle était vierge, nul homme ne l’avait connue; étant descendue à la fontaine, elle remplit sa cruche et remonta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Le serviteur courut à sa rencontre, et dit: Fais-moi boire un peu d’eau de ta cruche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Elle dit aussitôt: Bois, seigneur; et, se hâtant, elle descendit la cruche sur son bras, et le fit boire jusqu’à ce qu’il cessât de boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Elle dit ensuite: Je puiserai aussi de l’eau pour tes chamelles, jusqu’à ce que toutes aient bu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Et, se hâtant, elle vida sa cruche dans l’abreuvoir, courut au puits pour puiser encore, et puisa pour toutes les chamelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Cependant, l’homme l’observait, en gardant le silence, pour connaître si le Seigneur lui avait heureusement préparé sa voie ou non.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Lorsque toutes les chamelles eurent cessé de boire, il prit des boucles d’oreilles d’or pesant une drachme, et lui mit au bras deux bracelets pesant dix drachmes d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Puis il l’interrogea, en disant: De qui es-tu fille? dis-moi si chez ton père il y a place où nous loger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Elle répondit: Je suis la fille de Bathuel, fils de Melcha qui l’a enfanté à Nachor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Il y a, ajouta-t-elle, chez nous beaucoup de paille et de foin, et place où vous loger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Et l’homme rendant grâces, adora le Seigneur, en disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Béni soit le Seigneur Dieu de mon seigneur Abraham, qui n’a point détourné de mon seigneur sa justice et sa vérité; le Seigneur a heureusement dirigé mes pas jusqu’à la maison du frère de mon seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Et l’enfant, ayant couru, annonça dans la maison de sa mère ce qui venait de se passer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Or, Rebecca avait un frère nommé Laban; celui-ci sortit à la hâte et courut vers l’homme auprès de la fontaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Lorsqu’il eut vu les boucles d’oreilles et les bracelets aux bras de sa sœur, lorsqu’il eut entendu Rebecca dire L’homme m’a parlé ainsi, il vint à son tour vers l’homme qui se tenait, avec ses chamelles, auprès de la fontaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Et il lui dit: Viens, entre, ô toi béni du Seigneur: pourquoi restes-tu dehors? j’ai préparé la maison et une place pour tes chamelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Et l’homme entra dans la maison; Laban ôta les bâts des chamelles, donna de la paille et du foin aux chamelles, ainsi que de l’eau à l’homme et aux hommes de sa suite, pour se laver les pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Puis, il leur offrit des pains à manger, mais l’homme dit: Je ne mangerai point que je n’aie dit ce que j’ai à dire; et Laban dit: Parle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'L’homme dit alors: Je suis serviteur d’Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Le Seigneur a béni extrêmement mon seigneur; il l’a grandi, il lui a donné des menus troupeaux, et des bœufs, et de l’argent, et de l’or, et des serviteurs, et des servantes, et des chameaux, et des ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'De plus Sarra, femme de mon seigneur, à enfanté à mon seigneur, dans ses vieux jours, un fils unique, auquel mon seigneur a donné tout ce qu’il possédait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Et mon seigneur m’a adjuré, disant: Tu ne prendras pas une femme pour mon fils parmi les filles des Chananéens, au milieu desquels je suis passager en leur terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Mais tu t’en iras dans la maison de mon père et dans ma tribu, et tu ramèneras de là une femme pour mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Peut-être, répondis-je à mon seigneur, la femme ne voudra-t-elle pas venir avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Et il m’a dit: Le Seigneur Dieu, devant qui j’ai trouvé grâce, enverra son ange avec toi, et préparera heureusement ta voie, et tu prendras une femme pour mon fils, en ma tribu, dans la maison de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Si, quand tu seras allé dans ma tribu, ils ne t’accordent rien, tu seras délié de ma malédiction et dégagé du serment que je t’ai fait prêter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Or, étant arrivé aujourd’hui vers la fontaine, j’ai dit: Seigneur Dieu de mon seigneur Abraham, si vous dirigez heureusement mes pas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Voilà que je me suis arrêté vers la fontaine, au moment où les filles des hommes de la ville sortent pour puiser de l’eau; que la vierge à laquelle je dirai: Fais-moi boire un peu d’eau de ta cruche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Et qui dira: Bois, je vais puiser de l’eau pour tes chamelles; que cette vierge soit la femme préparée par le Seigneur pour son serviteur Isaac; par là je reconnaîtrai que vous avez été miséricordieux envers mon seigneur Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'J’avais à peine achevé ces mots dans mon cœur, qu’aussitôt Rebecca sortit, ayant une cruche sur son épaule; elle descendit à la fontaine, elle puisa, et je lui dis Fais-moi boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Et, s’étant hâtée, elle descendit la cruche sur son bras, en disant: Bois, puis je ferai boire tes chamelles; et je bus, et elle fit boire mes chamelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Je l’interrogeai ensuite, et lui dis: De qui es-tu fille? apprends-le-moi. Je suis, répondit-elle, fille de Bathuel, fils de Nachor, que lui a enfanté Melcha. Et je lui mis les boucles d’oreilles, et je mis à ses bras les bracelets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Et, rendant grâces, j’adorai le Seigneur; je bénis le Seigneur Dieu de mon seigneur Abraham, qui m’avait heureusement dirigé dans la véritable voie, afin que je prisse, pour son fils, la fille du frère de mon seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Si donc vous voulez traiter mon seigneur selon la miséricorde et la justice, dites-le-moi; sinon, congédiez-moi, afin que je rebrousse chemin, à droite ou à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Laban et Bathuel répondirent: C’est du Seigneur que vient la chose, nous ne pouvons t’objecter ni bien ni mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Voici devant toi Rebecca; prends-la, pars, et qu’elle soit la femme du fils de ton seigneur, selon ce que le Seigneur a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'En entendant leurs paroles, le serviteur d’Abraham se prosterna la face contre terre devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Puis, le serviteur ayant montré des joyaux d’argent et d’or ainsi que des vêtements, les donna à Rebecca; il fit aussi des présents à son frère et à sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Ils mangèrent alors et ils burent, lui et les hommes de sa suite, ensuite ils se couchèrent. Et, s’étant levé de grand matin, le serviteur dit: Congédiez-moi, afin que je retourne auprès de mon seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Les frères et la mère de la vierge dirent: Que la jeune fille reste avec nous dix jours encore, et ensuite elle partira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Mais il leur dit: Ne me retenez pas; le Seigneur m’a heureusement préparé la voie; congédiez-moi afin que je retourne auprès de mon seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Ils repartirent: Appelons l’enfant, interrogeons ses lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Et ils appelèrent Rebecca, et ils lui dirent: Partiras-tu avec cet homme? Je partirai, répondit-elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Ils congédièrent donc Rebecca leur sœur avec ce qui lui appartenait, ainsi que le serviteur d’Abraham et les hommes de sa suite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Ils bénirent Rebecca, et ils lui dirent: Tu es notre sœur; sois mère de milliers de myriades, et que ta race possède les villes de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Ensuite Rebecca s’étant levée avec ses servantes, elles montèrent sur les chamelles et elles partirent avec l’homme. Et le serviteur, prenant avec lui Rebecca, se remit en marche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Or, Isaac se promenait alors dans le désert, vers le puits de la Vision, car il habitait en la terre qui est au midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'C’était le soir; Isaac était sorti dans la plaine pour se distraire, et, ayant levé les yeux, il vit les chamelles qui arrivaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebecca, ayant aussi levé les yeux, aperçut Isaac; aussitôt elle descendit de sa chamelle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Et dit au serviteur: Quel est cet homme qui marche dans la plaine à notre rencontre? Le serviteur répondit: C’est mon seigneur. Ayant donc pris son grand voile, elle s’en enveloppa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Le serviteur raconta à Isaac toutes les choses qu’il avait faites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Entré en la demeure de sa mère, Isaac prit Rebecca pour sa femme et il la chérit; et il fut consolé au sujet de Sarra, sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham prit encore une autre femme du nom de Cettura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Elle lui enfanta Zameran, Jezan, Madal, Madian, Jesboc et Sué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jezan engendra Saba et Dedan; fils de Dedan: Assurim, Latusim et Laomim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Fils de Madian: Gephar, Aphir, Enoch, Abida et Elduga. Tous ceux-ci étaient issus de Cettura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Or, Abraham donna tout ce qu’il possédait à Isaac, son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Quant aux fils de ses concubines, Abraham leur fit des présents; de son vivant, il les envoya loin de son fils Isaac, à l’orient, en la terre des Orientaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Bientôt le nombre des jours que vécut Abraham forma cent soixante- ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Et Abraham mourut dans une belle vieillesse, âgé et plein de jours, et il fut réuni à son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Isaac et Ismaël, ses fils, l’ensevelirent en la double caverne dans le champ de l’Hettéen Ephron, fils de Saar, en face de Mambré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'C’était le champ et la caverne qu’Abraham avait achetés des fils de Het; ils y ensevelirent Abraham, auprès de sa femme Sarra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Or, après la mort d’Abraham, Dieu bénit son fils Isaac, qui demeura vers le puits de la Vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Voici les générations d’Ismaël, fils d’Abraham, que lui enfanta l’Égyptienne Agar, servante de Sarra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Voici les noms des fils d’Ismaël, conformes aux noms de leurs tribus: Nabaïoth, le premier-né d’Ismaël, puis Cédar, Abdéel, Massan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Masma, Duma, Massi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Puis Choddan, Théman, Jéthur, Naphis et Cedma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ceux-ci sont les fils d’Ismaël; ces noms sont ceux qu’ils portèrent sous leurs tentes, dans leurs camps; ils formèrent douze chefs d’autant de nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Ismaël vécut cent trente-sept ans, et il mourut, et il fut réuni à sa race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Il avait demeuré entre Hévilat et Sur, qui est en face de l’Égypte, du côté des Assyriens, vis-à-vis ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Voici les générations d’Isaac, fils d’Abraham; Abraham engendra Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Or, Isaac avait quarante ans lorsqu’il prit pour femme Rebecca, fille de Bathuel, le Syrien, de la Mésopotamie syrienne, sœur de Laban, le Syrien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaac pria au sujet de sa femme Rebecca, parce qu’elle était stérile; et le Seigneur l’exauça; Rebecca conçut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Comme deux enfants s’agitaient en ses entrailles, elle dit: Cela devait-il m’arriver? pourquoi cela m’arrive-t-il? Et elle s’en alla interroger le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Le Seigneur lui dit: Deux nations sont en ton sein; deux peuples en sortiront pour se séparer; l’un dominera l’autre, et le plus grand sera soumis au moindre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Et les jours de l’enfantement étant accomplis, elle se trouvait avoir deux jumeaux en ses entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Le premier-né sortit roux, tout velu, semblable à une peau de bête fauve; et elle lui donna le nom d’Ésau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Après lui sortit son frère, sa main tenait le pied d’Ésau; aussi lui donna-t-elle le nom de Jacob. Isaac avait ans, lorsque Rebecca les enfanta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Les jeunes gens grandirent; Ésau fut un homme rustique, habile chasseur; Jacob fut un homme paisible, se plaisant à la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaac affectionnait Ésau, parce qu’il se nourrissait de son gibier; mais Rebecca chérissait Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Or, Jacob avait fait cuire un mets, comme Ésau arriva de la plaine, défaillant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Et Ésau dit à Jacob: Laisse-moi manger de cette bouillie rousse; car je suis défaillant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Jacob répondit à Ésau: Cède-moi aujourd’hui ton droit d’aînesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Ésau reprit: Je vais mourir; à quoi me sert mon droit d’aînesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jacob lui dit: Prête-moi serment aujourd’hui, et son frère jura; ainsi le droit d’aînesse d’Ésau fut transmis à Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Jacob donna donc à son frère du pain et de la bouillie de lentilles; Ésau mangea et il but; puis, s’étant levé, il partit, sans se mettre davantage en peine de son droit d’aînesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Il y eut alors une famine dans la contrée, outre la première qui avait eu lieu du temps d’Abraham. Isaac s’en alla chez Abimélech, roi des Philistins, en Gérare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Car le Seigneur lui apparut et lui dit: Ne descends pas en Égypte, mais demeure en la terre que je te dirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Demeure en cette terre, je serai avec toi, je te bénirai; je donnerai toute cette terre à toi et à ta race; je maintiendrai le serment que j’ai fait à ton père Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Je multiplierai ta postérité comme les étoiles du ciel, je donnerai à ta race toute cette terre, et toutes les nations de la terre seront bénies en ta postérité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Parce que ton père Abraham a écouté ma parole, a gardé mes commandements, mes préceptes, mes jugements et mes lois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Et Isaac demeura en Gérare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Les hommes de la ville l’interrogèrent au sujet de Rebecca sa femme, et il dit: C’est ma sœur; car il avait crainte de dire: C’est ma femme; de peur que les hommes de la ville ne vinssent à le tuer à cause de Rebecca, parce qu’elle était d’une grande beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Il fut longtemps en ce lieu, et Abimélech, roi de Gérare, s’étant penché à sa fenêtre, vit Isaac jouant avec Rebecca, sa femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Et il appela Isaac, et il lui dit: Elle est donc ta femme? Pourquoi as-tu dit: C’est ma sœur? Isaac répondit: Je l’ai dit, de peur de mourir à cause d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimélech lui dit: Pourquoi nous as-tu traités de la sorte? Peu s’en est fallu que quelqu’un de notre race n’ait dormi avec ta femme, et tu nous aurais fait tomber par ignorance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Abimélech aussitôt donna ses ordres à son peuple, disant: Quiconque touchera à cet homme ou à sa femme périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Isaac ensemença cette terre, et il obtint, cette année, de l’orge au centuple, car le Seigneur le bénit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Et l’homme fut glorifié; il prospéra avec le temps jusqu’à devenir très-grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Il eut des menus troupeaux de brebis, des troupeaux de bœufs et beaucoup de terres. Les Philistins lui portèrent même envie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Et tous les puits que les serviteurs de son père avaient creusés de son vivant, ils les bouchèrent et les remplirent de terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Alors, Abimélech dit à Isaac: Éloigne-toi, car tu es devenu beaucoup plus puissant que nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Isaac partit donc; il vint camper dans la vallée de Gérare, et il y demeura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Là, il déblaya les puits que les serviteurs de son père avaient creusés, et qui avaient été comblés par les Philistins après la mort d’Abraham; et il donna à ces puits les mêmes noms que leur avait donnés son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Les serviteurs d’Isaac creusèrent encore dans la gorge de Gérare; et ils y trouvèrent un puits d’eau vive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Sur ce, les pâtres de Gérare combattirent contre les pâtres d’Isaac, disant que l’eau leur appartenait; aussi les serviteurs d’Isaac donnèrent-ils à ce puits le nom de puits de l’Iniquité; les Philistins, en effet, avaient été injustes envers lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'S’étant éloigné, il creusa un autre puits; comme ils contestèrent aussi celui-là, il lui donna le nom de puits de l’Inimitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Et, s’étant éloigné, il creusa un puits nouveau pour lequel il n’y eut point de combat, et il le nomma puits de Latitude, disant: Le Seigneur maintenant nous a dilatés et agrandis sur cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Enfin, de là il remonta vers le puits du Serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Dès la première nuit, le Seigneur lui apparut, et il lui dit Je suis le Dieu d’Abraham ton père; n’aie point de crainte, car je suis avec toi; je te bénirai, et je multiplierai ta race, à cause d’Abraham ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'En conséquence, il bâtit en ce lieu un autel; il Y invoqua le nom du Seigneur; il y dressa ses tentes, et ses serviteurs y creusèrent un puits, toujours dans la gorge de Gérare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Abimélech vint le trouver de Gérare, avec Ochosath, gardien de ses femmes, et Phichol, général en chef de ses armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Et Isaac leur dit: Pourquoi venez-vous vers moi, vous qui m’avez haï et chassé loin de vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Ils répondirent: Nous avons vu que le Seigneur est avec toi, et nous avons dit: Qu’un intervienne entre nous et toi; nous voulons faire avec toi une alliance;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Pour que tu ne nous veuilles pas plus de mal que nous ne t’en avons voulu, et que tu agisses envers nous comme envers toi, nous, qui même t’avons si bien traité et t’avons congédié en paix; maintenant béni sois-tu du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Il leur fit donc un festin, et ils mangèrent, et ils burent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Puis, s’étant levés de grand matin, ils se firent un serment mutuel; Isaac les congédia, et ils partirent avec une sauvegarde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Or, il arriva en ce même jour que les serviteurs d’Isaac survenant lui donnèrent des nouvelles du puits qu’ils avaient creusé, et ils dirent: Nous n’avons point trouvé d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Et Isaac appela ce puits: puits du Serment; c’est pourquoi encore de nos jours la ville qui s’y trouve s’appelle puits du Serment (Bersabée).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Or, Esau avait quarante ans, et il prit pour femmes: Judith, fille de l’Hettéen Beoch, et Basemath, fille de l’Hettéen Elon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Mais elles étaient en désaccord avec Isaac et avec Rebecca.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Or, il arriva qu’Isaac ayant vieilli, ses yeux s’affaiblirent, et il appela son fils aîné Ésau, disant: Mon fils; et celui-ci répondit: Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Voilà que j’ai vieilli, dit Isaac, et j’ignore le jour de ma fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Maintenant donc, prends ton équipement, ton carquois et ton arc, sors dans la plaine, chasse pour moi du gibier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Prépare-moi le mets que j’aime, et apporte-le-moi, afin que je mange et que mon âme te bénisse avant de mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Or, Rebecca entendit Isaac, comme il parlait à son fils Ésau; et pendant que celui-ci allait dans la plaine chasser du gibier pour son père,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Rebecca dit à son fils puîné Jacob: J’ai entendu ton père, comme il parlait à ton frère Ésau, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Apporte-moi du gibier, et prépare-moi un mets, afin qu’après avoir mangé je te bénisse devant le Seigneur avant de mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Maintenant donc, mon fils, obéis-moi et fais ce que je vais te prescrire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Va aux menus troupeaux, apporte-m’en deux beaux chevreaux tendres, je préparerai pour ton père le mets qu’il aime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Et tu le lui porteras, afin qu’il mange et qu’il te bénisse avant de mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jacob dit à sa mère: Ésau, mon frère, est velu, et j’ai la peau unie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Je crains que mon père ne vienne à me toucher; il lui semblera que je le méprise, et j’attirerai sur moi sa malédiction au lieu de sa bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Sa mère lui dit: Je prends sur moi cette malédiction-là, mon enfant; obéis seulement à mes ordres, pars et apporte-moi ce que j’ai demandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Il partit donc, et il apporta les deux chevreaux à sa mère; et celle-ci prépara le mets qu’aimait son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Ensuite, Rebecca ayant pris la belle robe d’Ésau son fils aîné, qu’elle-même gardait en la maison, elle en revêtit Jacob, son plus jeune fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Elle entoura de la peau des chevreaux ses avant-bras et les parties nues de son cou;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Elle remit dans les mains de son fils Jacob les pains et le mets qu’elle avait préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Puis, il les porta à son père, et il dit: Père; celui-ci répondit: Me voici; qui es-tu, enfant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jacob reprit: Je suis Esau ton premier-né; j’ai fait ce que tu m’as dit: lève-toi donc, mets-toi sur ton séant, mange de mon gibier, et que ton âme me bénisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Isaac dit à son fils: Comment donc en as-tu trouvé si vite, ô enfant? Et il répondit: C’est le Seigneur ton Dieu qui l’a procuré et amené devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Isaac dit à Jacob: Viens près de moi, que je te touche, enfant, pour connaître si tu es ou non mon fils Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jacob s’approcha d’Isaac son père; et celui-ci le toucha, et il dit: D’une part la voix de Jacob, d’autre part les mains d’Esau!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Et il ne reconnut pas Jacob, car les mains de Jacob étaient velues comme les mains d’Esau, son frère; et il le bénit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Et il dit: Tu es mon fils Esau? et Jacob dit: Je le suis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Sers-moi, dit Isaac, et je mangerai de ton gibier, afin que mon âme te bénisse. Son fils le servit aussitôt, et il mangea; il lui apporta du vin, et il but.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Et Isaac dit: Approche, enfant, et embrasse-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Et s’étant approché, il l’embrassa; son père sentit le parfum de ses vêtements, et il le bénit en disant: Voilà que le parfum de mon fils est comme le parfum d’un champ couvert de fleurs que le Seigneur a béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Que le Seigneur te fasse part de la rosée du ciel et de la graisse de la terre, qu’il te donne abondance de pain et de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Que les nations te soient soumises, et que les princes se prosternent devant toi; sois le seigneur de ton frère, et que les fils de ton père se prosternent à tes pieds; maudit soit celui qui te maudira, béni celui qui te bénira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Or, ceci arriva: comme Isaac cessait de bénir Jacob son fils, au moment même où celui-ci s’éloignait de la face d’Isaac son père, Esau son frère revint de la chasse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Il prépara pareillement le mets, le porta à son père, et lui dit Père, lève-toi, et mange du gibier de ton fils, afin que ton âme me bénisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Isaac lui dit alors: Qui es-tu? Je suis, répondit-il, ton fils premier-né, Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Isaac s’extasia d’une extase grande et profonde, et il dit Qui donc est celui qui, ayant chassé, m’a apporté de son gibier, et m’a fait manger avant que tu sois revenu? Je l’ai béni, et il sera béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Or, Ésau, ayant ouï ces paroles, jeta un grand cri plein d’amertume, et il dit: Bénis-moi donc aussi, père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Isaac répondit: Ton frère est venu, employant la ruse, et a pris ta bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Sur quoi Esau s’écria: C’est justement qu’il a reçu le nom de Jacob, car il m’a supplanté encore cette fois. Il m’avait d’abord pris mon droit d’aînesse, et maintenant il vient de prendre ma bénédiction. Et s’adressant à Isaac, il ajouta: Père, n’as-tu point réservé une bénédiction pour moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaac lui répondit: Je l’ai fait ton seigneur, j’ai fait ses serviteurs tous ses frères, je l’ai affermi par le pain et le vin que puis-je encore pour toi, enfant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Et Ésau dit à son père: N’as-tu qu’une seule bénédiction, père? Bénis-moi donc aussi, père. Et Isaac étant troublé, Ésau jeta un grand cri et pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Isaac reprit: C’est la graisse de la terre qui sera ton partage avec la rosée du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Tu vivras de ton glaive, et tu seras soumis à ton frère, jusqu’à ce que tu ôtes et délies son joug de ton cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Or, Ésau était profondément irrité contre Jacob à cause de la bénédiction que lui avait donnée son père; et Ésau dit en sa pensée: Viennent les jours du deuil de mon père, et je tuerai mon frère Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Ces paroles d’Ésau furent rapportées à Rebecca; elle envoya chercher Jacob, son plus jeune fils, et elle lui dit: Ton frère Ésau menace de te tuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Maintenant donc, enfant, sois docile à ma voix; lève-toi, et fuis rapidement en Mésopotamie, chez Laban mon frère, à Haran,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Et demeure avec lui quelque temps,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Jusqu’à ce que la haine et la colère d’Ésau se détournent de toi, qu’il oublie ce que tu lui as fait, et que j’envoie quelqu’un te rappeler; pars, de peur qu’en un seul jour je cesse d’être mère en vous perdant tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Rebecca dit aussi à Isaac: La vie m’est devenue amère à cause des filles des Hettéens; si Jacob prend femme parmi les filles de cette race, à quoi me sert la vie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Isaac ayant appelé Jacob, le bénit et lui donna ses ordres, disant: Tu ne prendras point femme parmi les filles des Chananéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Lève-toi, va en Mésopotamie, dans la maison de Bathuel, père de ta mère, et ramènes-en pour toi une femme des filles de Laban, frère de Rebecca;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Et mon Dieu te bénira, te grandira, te multipliera; tu seras père d’une foule de nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Qu’il te donne la bénédiction d’Abraham pour toi et ta postérité, afin que tu hérites de la terre où tu n’es que passager, et que Dieu a donnée à Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Isaac congédia ainsi Jacob, qui alla en Mésopotamie chez Laban, fils de Bathuel le Syrien, et frère de Rebecca, mère de Jacob et d’Ésau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Or, Ésau vit qu’Isaac avait béni Jacob, qu’il l’avait envoyé en Mésopotamie avec sa bénédiction, afin qu’il y prît femme, et qu’il lui avait donné ses ordres, disant: Tu ne prendras point femme parmi les filles des Chananéens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Et que Jacob obéissant à son père et à sa mère, était parti pour la Mésopotamie syrienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Esau, voyant donc que les filles de Chanaan étaient méchantes aux yeux de son père Isaac,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'S’en alla auprès d’Ismaël et prit pour femme, outre ses femmes, Maeleth, fille d’Ismaël, sœur de Nabeoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Cependant Jacob, étant parti du puits du Serment, prit la route de Haran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Et il arriva en un endroit où il se reposa, car le soleil était couché; il prit des pierres, les plaça du côté de sa tête, et il se coucha en cet endroit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'S’étant endormi, il vit une échelle plantée en terre dont l’extrémité atteignait le ciel, et sur cette échelle les anges de Dieu montaient et descendaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Et au-dessus de l’échelle se tenait le Seigneur, qui lui dit: Je suis le Dieu d’Abraham et le Dieu d’Isaac; n’aie point de crainte la terre sur laquelle tu dors, je la donnerai à toi et à ta race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Ta postérité sera comme le sable de la terre; elle s’étendra à l’occident, au midi, au nord et à l’orient, et en toi et en ta race seront bénies toutes les tribus de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Je suis avec toi pour te garder en toute voie où tu marcheras; je te ramènerai en cette terre, et je ne t’abandonnerai point que je n’aie accompli les choses que je t’ai dites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Jacob, en s’éveillant, s’écria: Le Seigneur est en ce lieu, et je ne le savais pas!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Et il eut crainte, et il dit: Que ce lieu est redoutable! Il n’est rien moins que la maison du Seigneur, et la porte même du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Jacob se leva de grand matin, prit la pierre qu’il avait mise sous sa tête, et la posa comme une colonne; puis sur son sommet il répandit de l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Il donna à ce lieu le nom de maison du Seigneur (Béthel), car Ulam Luz était auparavant le nom qu’il portait,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Et il fit un vœu, disant: Si le Seigneur Dieu est avec moi, s’il me garde en la voie où je marche, s’il me donne du pain à manger et des vêtements pour m’envelopper,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'S’il me ramène sain et sauf en la maison de mon père, le Seigneur sera mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Et cette pierre que j’ai posée comme une colonne, sera pour moi la maison de Dieu; et de toutes les choses que vous me donnerez, Seigneur, je séparerai le dixième pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Puis, s’étant remis en marche, Jacob s’en alla en la terre d’Orient chez Laban, fils de Bathuel le Syrien, frère de Rebecca, mère de Jacob et d’Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Il aperçut un puits dans la plaine et trois troupeaux de brebis, arrêtés près du puits, car c’était là que l’on abreuvait les troupeaux, et il y avait une grande pierre sur l’ouverture du puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Lorsque tous les troupeaux étaient rassemblés, les pâtres faisaient rouler la pierre de l’ouverture du puits, et ils donnaient à boire au bétail, puis, ils remettaient la pierre à sa place, au-dessus du puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Et Jacob dit: Frères, d’où êtes-vous? Nous sommes, répondirent-ils, d’Haran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Il ajouta Connaissez-vous Laban, petit-fils de Nachor? et ils dirent: Nous le connaissons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Et il leur dit: Se porte-t-il bien? et ils répondirent: Il se porte bien; voilà Rachel sa fille, qui vient avec ses brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Le jour est encore grand, dit Jacob, et ce n’est point l’heure où l’on rassemble les troupeaux; faites donc boire vos brebis et -les au pâturage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Ils repartirent: Nous ne le pourrons avant la réunion de tous les pâtres; à eux tous, ils détourneront la pierre de l’ouverture du puits, et nous ferons boire notre bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Comme il leur parlait encore, Rachel, fille de Laban, les rejoignit avec les brebis de son père, car elle menait paître les brebis de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Et lorsque Jacob vit Rachel, fille de Laban, frère de sa mère, et les brebis de Laban, frère de sa mère, s’étant approché, il détourna la pierre de l’ouverture du puits, et fit boire les brebis de Laban, frère de sa mère;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Et Jacob donna un baiser à Rachel, et, élevant la voix, il pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Il apprit à Rachel qu’il était neveu de son père, et fils de Rebecca; aussitôt s’étant mise à courir, elle raconta tout à son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'À peine Laban eut-il entendu le nom de Jacob, fils de sa sœur, qu’il courut à sa rencontre, et l’ayant serré dans ses bras, il le baisa; puis il le conduisit en sa demeure, et Jacob raconta à Laban toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Laban lui dit: Tu es de mes os et de ma chair. Et Jacob resta avec lui tous les jours d’une lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Laban dit ensuite à Jacob: Parce que tu es mon frère, tu ne dois pas me servir gratuitement; dis-moi donc quelle récompense tu veux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Or, Laban avait deux filles: l’aînée se nommait Lia, et la plus jeune Rachel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lia avait les yeux faibles, Rachel était belle de visage et pleine de grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Jacob aimait Rachel, et il dit: Je te servirai sept ans pour Rachel, ta plus jeune fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Mieux vaut, lui dit Laban, la donner à toi qu’à un autre homme; demeure donc avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Jacob servit donc sept années pour Rachel, et les ans furent devant lui comme de courtes journées, à cause de la tendresse qu’il avait pour elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Et Jacob dit à Laban: Donne-moi ma femme afin que j’habite avec elle, car les jours sont accomplis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Laban réunit tous les hommes du lieu, et il célébra les noces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Mais, le soir venu, il prit sa fille Lia et l’introduisit auprès de Jacob, qui s’approcha d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Or, Laban donna à sa fille Lia, pour servante, Zelpha, qui lui appartenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Lorsque le matin parut, Jacob reconnut Lia, et il dit à Laban Pourquoi m’as-tu fait cela; n’est-ce pas pour Rachel que je t’ai servi? Pourquoi m’as-tu trompé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban répondit: Il n’est point d’usage en notre pays de donner la plus jeune avant l’aînée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Achève la semaine de celle-ci, et je te donnerai encore l’autre pour prix des travaux que tu feras ensuite pour moi pendant sept autres années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jacob fit ainsi: il acheva la semaine de Lia, et Laban lui donna pour femme sa fille Rachel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Laban donna à sa fille, pour servante, Balla, qui lui appartenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Et Jacob s’approcha de Rachel; il la chérit plus que Lia, et il servit pour elle sept autres années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Mais le Seigneur ayant vu que Lia était haïe, lui ouvrit les entrailles, tandis que Rachel resta stérile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Et Lia ayant conçu, enfanta à Jacob un fils qu’elle appela Ruben, disant: Le Seigneur a vu mon humiliation, et il m’a donné un fils; maintenant donc mon époux m’aimera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Elle conçut derechef, et elle enfanta un second fils, et elle dit: Le Seigneur a entendu que je suis haïe, et il m’a donné encore celui-ci; elle l’appela Siméon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Elle conçut une troisième fois, et elle enfanta un fils, et elle dit: Désormais mon époux sera avec moi, car je lui ai donné trois fils; à cause de cela elle l’appela Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Et ayant encore conçu, elle enfanta un fils, et elle dit: Maintenant encore en ceci je louerai le Seigneur; c’est pourquoi elle donna à l’enfant le nom de Juda; puis elle cessa d’enfanter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Cependant, Rachel, voyant qu’elle n’enfantait point pour Jacob, fut jalouse de sa sœur, et elle dit à Jacob: Donne-moi des enfants, sinon je mourrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jacob, irrité contre Rachel, lui dit Suis-je l’égal de Dieu, qui t’a privé de fruits de tes entrailles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Et Rachel dit à Jacob: Voici ma servante Balla: approche-toi d’elle, elle enfantera sur mes genoux, et par elle, moi aussi, j’aurai des enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Elle lui donna donc pour femme Balla, sa servante, et Jacob s’approcha d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Et Balla, la servante de Rachel, conçut, et elle enfanta à Jacob un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Le Seigneur m’a jugée, dit alors Rachel, il a entendu ma voix, et il m’a donné un fils; c’est pourquoi elle donna à l’enfant le nom de Dan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Balla, la servante de Rachel, conçut encore, et elle enfanta à Jacob un second fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Et Rachel dit: Le Seigneur m’a secourue; j’ai lutté contre ma sœur et j’ai prévalu; en conséquence elle donna à l’enfant le nom de Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Lia, voyant qu’elle avait cessé d’enfanter, prit Zelpha, sa servante, et la donna pour femme à Jacob, qui s’approcha d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Et Zelpha, la servante de Lia, conçut; elle enfanta à Jacob un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Et Lia dit: À la bonne heure; et elle le nomma Gad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Zelpha, la servante de Lia, conçut encore, et elle enfanta à Jacob un second fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Et Lia dit: Heureuse je suis, car les femmes m’estiment heureuse; et elle le nomma Aser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Or, un jour Ruben sortit pendant la moisson du froment, et il trouva dans le champ des fruits de mandragores, et, il les apporta à Lia sa mère, et Rachel dit à sa sœur Lia: Donne-moi des mandragores de ton fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Et Lia lui dit: N’est-ce pas assez pour toi de m’avoir pris mon époux; me prendras-tu encore les mandragores de mon fils? Ce n’est pas ce que j’entends, dit Rachel; que Jacob dorme cette nuit avec toi pour prix des mandragores de ton fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Lors donc que Jacob revint du champ le soir, Lia sortit à sa rencontre, et lui dit: Tu t’approcheras aujourd’hui de moi, car je t’ai obtenu, pour les mandragores de ton fils; et il dormit cette nuit avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Dieu exauça Lia; elle conçut, et elle enfanta à Jacob un cinquième fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Et elle dit: Le Seigneur m’a récompensée d’avoir donné ma servante à mon époux; elle nomma donc l’enfant Issachar, c’est-à-dire récompense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lia conçut encore, et elle enfanta à Jacob un');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Alors elle dit: Le Seigneur vient de me faire un don précieux mon époux m’aimera, parce que je lui ai donné un sixième fils; et elle nomma celui-ci Zabulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Après cela, elle enfanta une fille qu’elle appela Dina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Cependant, Dieu se souvint de Rachel; il l’exauça, et lui ouvrit les entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Elle conçut donc, et enfanta à Jacob un fils; et Rachel dit: Dieu a effacé mon opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Elle nomma l’enfant Joseph, et elle dit: Que Dieu m’accorde encore un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Or, il arriva qu’après que Rachel eut enfanté Joseph, Jacob dit à Laban: Congédie-moi, que je retourne en mon lieu natal, en mon pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Rends-moi mes femmes et mes enfants pour lesquels je t’ai servi; qu’enfin je parte, car tu sais la servitude à laquelle je me suis assujetti pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban lui dit: Si j’ai trouvé grâce devant toi, puisque j’ai expérimenté que Dieu m’a béni depuis ton arrivée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Fixe-moi ta récompense, et tu l’auras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Tu sais, répondit Jacob, combien je t’ai servi, et ce qu’est devenu ton bétail avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Car avant moi tu en avais peu, et il s’est multiplié grandement; le Seigneur Dieu t’a béni sous mes pas. Maintenant donc, quand me ferai-je aussi une maison?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Et Laban lui dit Que te donnerai — je? Jacob répondit: Tu ne me donneras rien, si tu consens à ce que je vais te dire: je paîtrai encore tes troupeaux et je les garderai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Fais-les tous passer aujourd’hui devant nous; puis sépare désormais, parmi les agneaux, tout rejeton brun, et parmi les chèvres, tout rejeton mêlé de blanc ou tacheté; ce sera ma récompense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Dès demain ma justice me servira, puisque telle est avec toi ma récompense. Que tout ce qui chez moi ne sera pas tacheté ou mêlé de blanc parmi les chèvres, ni brun parmi les agneaux, me soit imputé à larcin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Et Laban lui dit: Qu’il soit fait selon ta parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Dès ce jour-là, il sépara de ses troupeaux les boucs tachetés et mêlés de blanc, les chèvres tachetées et mêlées de blanc, les agneaux bruns mis à part des blancs, et il les confia à ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Et il mit trois journées de marche entre ses fils et Jacob. Or, Jacob paissait le reste des troupeaux de Laban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Et Jacob prit une baguette verte de styrax, une autre de noyer et une de platane, et les ayant dépouillées jusqu’à l’écorce blanche, il laissa tout autour une bande d’écorce verte, en sorte que le blanc, mis à découvert, les fit paraître toutes bigarrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Il mit les baguettes écorcées dans les bras des abreuvoirs, afin que quand les troupeaux viendraient boire de l’eau, les femelles conçussent devant elles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Et les femelles conçurent devant les baguettes, et elles mirent bas des petits mêlés de blanc, ou bigarrés, ou cendrés-tachetés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Et Jacob sépara les agneaux: il plaça en avant des troupeaux tout mâle mêlé de blanc, tout agneau bigarré, et il prit pour lui les rejetons qui devaient lui revenir, sans les mêler avec les troupeaux de Laban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Lorsque venait le temps où concevaient les mères, Jacob plaçait les baguettes devant les troupeaux dans les abreuvoirs, pour que les femelles conçussent en face des baguettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Et quand les femelles avaient enfanté, il n’en plaçait plus. Il advint donc que les rejetons sans marque appartinrent à Laban; ceux qui étaient marqués appartinrent à Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Et l’homme s’enrichit beaucoup, beaucoup; il eut quantité de bétail, et des bœufs, et des serviteurs et des servantes, et des chameaux et des ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Cependant, Jacob entendit les fils de Laban se dire entre eux: Jacob a pris tous les biens de notre père; c’est des biens de notre père qu’il s’est fait cette gloire où nous le voyons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Et Jacob regarda la face de Laban, et il vit qu’elle n’était pas pour lui comme la veille et l’avant-veille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Le Seigneur lui-même dit à Jacob: Retourne au pays de ton père, dans ta famille; je serai avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Aussitôt, Jacob envoya chercher Lia et Rachel dans la plaine où étaient les troupeaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Et il leur dit: Je vois que la face de votre père n’est pour moi ni comme hier, ni comme le jour précédent; cependant le Dieu de mon père a été avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Vous savez vous-mêmes que j’ai servi votre père de toutes mes forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Néanmoins, il m’a trompé, et pendant dix portées d’agneaux, il a changé ma récompense, mais Dieu ne lui a pas permis de me faire tort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'S’il disait: Les bigarrés seront ta récompense, toutes les brebis produisaient des rejetons bigarrés; s’il disait, au contraire: Les blancs seront ton salaire, toutes les brebis produisaient des rejetons blancs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Le Seigneur a enlevé ainsi tout le bétail de votre père, pour me le donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Voici ce qui est arrivé: Lorsque les mères concevaient, j’eus pendant mon sommeil une vision; je vis que les béliers et les boucs couvrant les brebis et les chèvres étaient blancs-mêlés, bigarrés et cendrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Et, pendant mon sommeil, l’ange du Seigneur m’a dit: Jacob; et j’ai répondu: Qu’y a-t-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'L’ange m’a dit: Lève les yeux, vois les boucs et les béliers couvrant les chèvres et les brebis; ils sont blancs-mêlés, bigarrés et cendrés. J’ai vu tout ce que te fait Laban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Je suis le Dieu qui t’apparus en la demeure de Dieu, où tu as oint pour moi une colonne, et où tu m’as fait un vœu. Maintenant donc, lève-toi et pars de cette terre; retourne au pays où tu es né, et je serai avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Rachel et Lia lui dirent: Est-ce que nous avons encore une part ou un héritage en la maison de notre père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Ne nous a-t-il pas traitées en étrangères? Il nous a vendues, et il a dévoré avec avidité l’argent qu’il avait retiré de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Que toute la richesse, toute la gloire que Dieu a enlevées à notre père, soient à nous et à nos enfants; maintenant donc fais tout ce que Dieu t’a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Et Jacob, s’étant levé, prit sur des chamelles ses femmes et ses enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Il emmena tout ce qui lui appartenait, tant ce qu’il avait acquis en Mésopotamie, que ce qui lui était propre, pour retourner auprès de son père Isaac, en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Cependant, Laban était allé tondre ses brebis, et Rachel déroba les idoles de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jacob se cacha de Laban le Syrien, ne lui faisant point savoir qu’il s’enfuyait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Il s’en alla rapidement avec ce qui lui appartenait, traversa l’Euphrate, et hâta sa marche vers la montagne de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Le troisième jour, on apprit à Laban le Syrien que Jacob s’était enfui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Aussitôt, prenant avec lui ses frères, il se mit à sa poursuite, et, au bout de sept jours, il l’atteignit en la montagne de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Or, Dieu vint vers Laban le Syrien la nuit, pendant son sommeil, et il lui dit: Garde-toi de parler méchamment à Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Bientôt Laban eut atteint Jacob, qui avait dressé ses tentes sur la montagne; Laban fit arrêter ses frères sur les monts de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Qu’as-tu fait? dit-il à Jacob; pourquoi as-tu fui secrètement? pourquoi m’as-tu volé et m’as-tu emmené mes filles comme des captives conquises par le glaive?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Si tu m’avais averti, je t’aurais reconduit joyeusement avec des musiciens, au son des tambours et des cithares.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Mais je n’ai pas été jugé digne de baiser mes petits-enfants et mes filles; tu as bien agi en insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Mon bras est assez fort pour te maltraiter; mais le Dieu de ton père m’a parlé cette nuit, disant: Garde-toi de parler méchamment à Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Pars donc, puisque tu désires si ardemment retourner dans la maison de ton père; mais pourquoi as-tu dérobé mes dieux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jacob répondit à Laban: J’avais crainte, et je me disais Qu’il n’aille point m’enlever ses filles et tout ce qui m’appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Jacob ajouta: Celui chez qui tu trouveras tes dieux, qu’il ne vive point parmi nos frères; reconnais chez moi ce qui t’appartient et prends-le. Or, il ne croyait pas qu’il y eût rien chez lui, car il ignorait que Rachel sa femme eût dérobé les idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Étant entré dans la demeure de Lia, Laban chercha et ne trouva rien. Il sortit de la demeure de Lia, chercha dans celle de Jacob, puis dans la demeure des deux servantes, et il ne trouva rien; il entra aussi en la demeure de Rachel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Or, Rachel avait pris les idoles, et les ayant cachées dans le bât de sa chamelle, elle s’était assise par-dessus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Elle dit à son père: Ne t’indigne pas, seigneur; je ne puis me lever devant toi, il m’est advenu ce qui arrive aux femmes. Et Laban chercha dans toute la demeure, et il ne trouva pas les idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Jacob alors s’indigna, éclata en reproches contre Laban, et il se mit à lui dire: Quelle est mon iniquité, quel est mon crime, pour que tu m’aies poursuivi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Et pour que tu aies fouillé tous les meubles de ma demeure? Qu’as-tu trouvé des choses de ta maison? Mets-le donc là devant tes frères et devant mes frères, qu’ils jugent entre nous deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'J’ai passé avec toi vingt de mes années; tes brebis et tes chèvres n’ont jamais été stériles; jamais je n’ai mangé des béliers de tes troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Je ne t’ai point compté ce qu’ont pris les bêtes fauves, et j’ai payé du mien les rapts de jour et les rapts de nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'J’ai été brûlé par la chaleur des jours, glacé par la froidure des nuits; le sommeil avait fui de mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Voilà vingt ans que je suis dans ta maison; je t’ai servi quatorze années pour prix de tes deux filles, et six pour tes menus troupeaux, et toi tu as changé ma récompense durant dix portées d’agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si le Dieu de mon père Abraham et la crainte d’Isaac n’étaient pas de mon côté, tu m’eusses renvoyé les mains vides; Dieu a vu mon humiliation et la fatigue de mes bras, et il t’a fait hier ses reproches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laban répondit à Jacob: Tes filles sont mes filles, et tes fils sont mes fils, ce bétail est mon bétail, tout ce que tu vois est à moi et à mes filles. Comment pourrai-je leur nuire à elles et à leurs enfants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Viens donc, je veux faire une alliance qui soit un témoignage entre moi et toi. Et il lui dit: Il n’y a personne avec nous; que Dieu soit témoin entre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Jacob, ayant pris une pierre, et l’ayant dressée en forme de colonne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Dit à ses frères: Rassemblez des pierres. Et ils rassemblèrent des pierres dont ils firent un autel, sur lequel ils mangèrent; et Laban dit à Jacob: Cet autel est témoin aujourd’hui entre toi et moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Laban l’appela l’autel du témoignage, et Jacob l’autel du témoin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Et Laban dit à Jacob: Voilà l’autel et la colonne que j’ai élevés entre moi et toi; cet autel est témoin, cette colonne porte témoignage. C’est pourquoi l’autel fut appelé l’Autel porte témoignage (Galaad),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Et: La vision qui a été vue; que Dieu regarde entre nous deux, puisque nous allons nous séparer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Si tu humilies mes filles; si avec elles tu prends d’autres femmes, fais attention: personne ne nous voit et n’est avec nous, mais Dieu est témoin entre moi et toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Et il dit à Jacob: Voici pour témoins cet autel et cette colonne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Si jamais je franchis de ton côté ou si tu franchis du mien cet autel et cette colonne dans de mauvais desseins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Que le Dieu d’Abraham et le Dieu de Nachor juge entre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Et Jacob jura par l’objet de la crainte d’Isaac son père; il offrit un sacrifice sur la montagne, et convoqua ses frères; ils mangèrent, et ils burent, et ils dormirent sur la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Ensuite, Laban se leva de grand matin, embrassa ses fils et ses filles, les bénit, et, s’étant retourné, il s’en fut en son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jacob, de son côté, reprit sa route, et, ayant levé les yeux, il vit un camp de Dieu déployé. Les anges de Dieu vinrent à sa rencontre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Jacob en les voyant s’écria: Voici un camp de Dieu; et il nomma ce lieu les Camps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Et Jacob envoya des messagers à son frère Esau, en la terre de Séir, dans le pays d’Édom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Et il leur donna ses ordres, disant: Vous parlerez ainsi à mon seigneur Esau: Ton serviteur Jacob te parle ainsi: J’ai habité auprès de Laban; j’y suis resté jusqu’à cette heure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'J’y ai acquis des bœufs, et des ânes, et du menu bétail, et des serviteurs et des servantes; j’envoie des messagers à mon seigneur Esau, afin que son serviteur trouve grâce devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Les messagers revinrent vers Jacob, disant: Nous sommes allés chez ton frère Esau, et voici qu’il vient à ta rencontre avec quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Jacob eut grande crainte, et il était très-indécis; il divisa en deux troupes les hommes qui l’accompagnaient, ainsi que les bœufs, et les chamelles, et les brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Jacob se disait: Si Esau marche sur l’une des troupes et la combat, la seconde du moins pourra être sauvée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Et Jacob dit: Dieu de mon père Abraham, Dieu de mon père Isaac, Seigneur, vous qui m’avez dit: Retourne en la terre où tu es né, et je te serai favorable,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'C’est assez pour moi de toute la justice et de toute la vérité dont vous avez usé envers votre serviteur; car j’ai traversé le Jourdain n’ayant que ce bâton, et je reviens possesseur de deux troupes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Délivrez-moi de la main de mon frère, de la main d’Esau, car je le crains; je crains qu’en arrivant il ne frappe et moi, et la mère avec ses enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'C’est vous qui avez dit: Je te serai favorable, et je rendrai ta race aussi nombreuse que le sable de la mer, dont nul ne saurait compter l’abondance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Il dormit cette nuit dans l’endroit où il était, il prit ensuite des biens qu’il portait, pour en faire des présents, et il envoya à son frère Esau:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Deux cents chèvres, vingt boucs, deux cents brebis, vingt béliers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Quarante chamelles à lait et leurs petits, quarante bœufs, dix taureaux, vingt ânes et dix poulains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Il les envoya par des serviteurs, chaque espèce formant un troupeau; et il dit à ses serviteurs: Marchez devant moi, et laissez un intervalle entre deux troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Puis, il donna ses ordres à celui qui était en tête, disant: Lorsque Esau mon frère te rencontrera et t’interrogera, disant: De qui es-tu? où vas-tu? à qui sont les bêtes qui marchent devant toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Tu répondras: À ton serviteur Jacob; il envoie des présents à mon seigneur Ésau, et voici qu’il vient derrière nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Il donna ensuite ses ordres au premier serviteur, au second, au troisième et à tous ceux qui marchaient avec les troupeaux, disant: Répondez en ces termes à Ésau, lorsque vous le rencontrerez;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Dites Voici ton serviteur Jacob qui vient derrière nous. Car, se dit-il, je l’apaiserai par les présents qui vont au-devant de lui, et, après cela, je le verrai face à face, et il m’accueillera favorablement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Les présents partirent en avant et s’éloignèrent de lui; et cette nuit-là il coucha dans le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Et, s’étant levé pendant la nuit, il prit les deux femmes, les deux servantes et les onze garçons; puis, il traversa le gué de Jaboch:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Il les prit, puis il traversa le fleuve, et tout ce qui lui appartenait traversa aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Jacob resta seul; alors un homme lutta contre lui jusqu’au matin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Et, voyant qu’il ne pouvait l’emporter, il toucha le gras de la cuisse de Jacob, qui s’engourdit dans la lutte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'L’ange lui dit. Laisse-moi partir, car l’aurore s’est levée; il répondit: Je ne te laisserai point partir que tu ne m’aies béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'L’ange repartit: Quel est ton nom? il répondit: Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Tu ne te nommeras plus Jacob, reprit l’ange, Israël sera ton nom parce que tu as été fort contre Dieu, et que tu seras fort contre les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Jacob lui fit cette question: Apprends — moi ton nom. Pourquoi, répondit-il, me demandes-tu mon nom? et sur le lieu même il le bénit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Jacob nomma cet endroit Vision de Dieu; Car, dit-il, j’ai vu Dieu face à face, et la vie m’a été conservée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'La vision de Dieu s’étant évanouie, le soleil se leva sur lui, et Jacob boitait de la cuisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'À cause de cela les fils d’Israël, aujourd’hui encore, ne mangent point le nerf du gras de la cuisse qui fut engourdi, parce que le gras de la cuisse de Jacob fut touché et que le nerf s’engourdit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Bientôt Jacob ayant levé les yeux, vit son frère Esau arriver avec quatre cents hommes, et Jacob rangea séparément les enfants, autour de Lia, de Rachel et des deux servantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Il mit en avant les deux servantes et leurs fils, puis par derrière Lia et ses enfants, et enfin Rachel avec Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Lui-même s’avança devant eux tous, et se prosterna sept fois jusqu’à terre avant d’arriver à Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Celui-ci accourut à sa rencontre, l’embrassa, lui jeta ses bras autour du cou, et le baisa, et ils pleurèrent tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Or, Esau ayant levé les yeux, vit les femmes et les enfants, et il dit: Quoi! sont-ils à toi? Jacob répondit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Les servantes et leurs enfants s’approchèrent aussi, et ils se prosternèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Et Lia s’approcha avec ses enfants, et ils se prosternèrent; Rachel enfin s’approcha avec Joseph, et ils se prosternèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Or, Esau dit: Quoi! les troupeaux que j’ai rencontrés sont-ils aussi à toi? Jacob répondit: Je les ai envoyés pour que ton serviteur trouve grâce devant toi, seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Et son frère dit: J’ai de grandes possessions, frère, garde tes biens pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Si j’ai trouvé grâce devant toi, reprit Jacob, accepte mes présents, car j’ai vu ta face comme on verrait la face de Dieu; tu me feras ce plaisir:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Prends donc les présents que je t’ai apportés, parce que le Seigneur dans sa miséricorde m’en a gratifié, et que tout cela est à moi. Et il usa de contrainte, et son frère accepta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Or, Esau dit: Partons, et marchons droit devant nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Jacob lui répondit: Mon seigneur sait que les enfants sont délicats, que des brebis et des vaches pleines m’accompagnent; si donc je les presse un seul jour, tout mon bétail mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Que mon seigneur précède son serviteur, et de mon côté je me hâterai en chemin, selon les forces de ce qui marche devant moi, et selon le pas des enfants, jusqu’à ce que j’aie rejoint mon seigneur en Séir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Et son frère reprit: Je laisserai avec toi une partie des gens qui m’accompagnent. Il répondit: Pourquoi cela? il me suffit d’avoir trouvé grâce devant toi, seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Et ce jour-là même Esau reprit, pour retourner à Séir, le chemin par lequel il était venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'De son côté Jacob s’en alla dresser ses tentes; il éleva là pour lui des tentes, et pour ses troupeaux des abris; c’est pourquoi il nomma ce lieu les Tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'De là, Jacob passa à Salem, ville des Sécimes qui est en la terre de Chanaan, où il était rentré en revenant de la Mésopotamie Syrienne, et il campa en face de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Il acheta d’Emmor, père de Sichem, au prix de cent agneaux, la portion du champ où il avait dressé ses');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Il y éleva un autel, et il invoqua le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Or, Dina, fille de Lia et de Jacob, sortit pour voir les filles du voisinage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Et Sichem, fils d’Emmor, Évéen, chef de cette terre, la vit, et l’ayant prise, il dormit avec elle et la déshonora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Il s’attacha de toute son âme à Dina, fille de Jacob; il aima la jeune fille, et lui parla selon sa pensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Sichem parla aussi à son père Emmor, disant: Donne-moi pour femme cette jeune fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jacob apprit que le fils d’Emmor avait déshonoré Dina, sa fille. Ses fils étaient alors dans la plaine avec ses grands troupeaux, et Jacob garda le silence jusqu’à ce qu’ils fussent revenus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Cependant, Emmor, père de Sichem, sortit et vint trouver Jacob afin de lui parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Et les fils de Jacob revinrent des champs; lorsqu’ils eurent tout appris, les hommes furent saisis de douleur; leur affliction fut grande, parce que Sichem avait porté la honte en Israël, en dormant avec la fille de Jacob. Et ils dirent: Il n’en sera pas ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Emmor, de son côté, leur parla en ces termes: Sichem, mon fils, a préféré en son cœur votre fille; donnez-la-lui donc pour femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Contractez des mariages avec nous, vos filles, prenez nos filles pour vos fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Et habitez parmi nous; voici devant vous une vaste terre; habitez-la, parcourez-la, et possédez — en votre part.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sichem, lui aussi, dit au père de Dina et à ses frères Puissé-je trouver grâce devant vous, puissiez-vous me dire: Nous te la donnerons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Élevez sa dot à une somme immense, et je donnerai ce que vous direz; donnez-moi pour femme cette jeune fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Et les fils de Jacob répondirent à Sichem et à son père Emmor avec artifice; ils leur parlèrent ainsi parce qu’ils avaient déshonoré leur sœur Dina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Siméon et Lévi, frères de Dina, leur dirent: Nous ne pouvons pas accomplir ce que vous demandez, ni donner notre sœur à un homme des vôtres qui n’est pas circoncis car c’est pour nous un opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'À cette seule condition nous ne ferons qu’un avec vous et nous demeurerons parmi vous devenez comme nous, et que chez vous tout mâle soit circoncis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Nous vous donnerons alors nos filles, et nous prendrons nos femmes parmi vos filles; nous demeurerons parmi vous, et nous serons comme une seule race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mais, si vous refusez de vous circoncire, nous reprendrons notre fille et nous nous éloignerons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Ces paroles furent agréables à Emmor et à Sichem, fils d’Emmor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Et le jeune homme ne tarda pas à s’y conformer, car il s’était attaché à la fille de Jacob, et il était le plus glorifié de tous, en la maison de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Emmor et son fils allèrent donc devant la porte de leur ville, et ils parlèrent en ces termes aux hommes de la cité:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ces hommes sont pacifiques; qu’ils habitent notre contrée, et qu’ils la parcourent; voici devant eux un vaste pays. Nous prendrons pour femmes leurs filles, et nous leur donnerons les nôtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Ces hommes demeureront avec nous, et ne feront avec nous qu’un seul peuple, à la seule condition que tout mâle parmi nous soit circoncis comme ils le sont eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'De la sorte leurs menus troupeaux et leur bétail, et tous leurs biens ne seront-ils pas à nous? Rendons-nous semblables à eux en ce point seulement, et ils demeureront avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Tous ceux qui étaient venus devant la porte de la ville obéirent à Emmor et à Sichem son fils, et ils circoncirent tous les mâles parmi eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Or, le troisième jour, pendant que tous étaient en proie à la souffrance, les deux fils de Jacob, Siméon et Lévi, prirent chacun leur glaive; et ils entrèrent dans la ville sans danger, et ils tuèrent tous les mâles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Ils passèrent Emmor et son fils Sichem au fil de l’épée, prirent Dina dans la maison de Sichem, et sortirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Les fils de Jacob survinrent au milieu du carnage, et ils pillèrent la ville dans laquelle leur sœur Dina avait été déshonorée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ils s’emparèrent des brebis, et des bœufs, et des ânes, tant dans la ville qu’aux champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Ils prirent ensuite tous les corps vivants et tous les vêtements, firent captives les femmes, et pillèrent tout ce qu’il y avait dans la ville et dans les habitations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Mais Jacob dit à Siméon et à Lévi: Vous m’avez rendu odieux, je vais être en abomination à tous les habitants de la contrée, aux Chananéens et aux Phérézéens. Et comme je suis le moindre en nombre, ils se réuniront contre moi et me massacreront; je serai anéanti moi et ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Mais ils lui répondirent: Fallait-il donc qu’ils abusassent de notre sœur comme d’une prostituée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Dieu dit ensuite à Jacob: Lève-toi, pars pour Béthel, établis là ta demeure, et élève en ce lieu un autel au Dieu qui t’y est apparu, lorsque tu fuyais Esau ton frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Jacob alors dit aux siens et à tous ceux qui étaient avec lui: Faites disparaître du milieu de vous les dieux étrangers qui s’y trouvent; purifiez-vous et changez de vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Puis, levons-nous, allons à Béthel; nous y bâtirons un autel au Dieu qui m’a exaucé en un jour d’affliction, à celui qui fut avec moi, et qui m’a sauvé dans la voie où je marchais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Ils donnèrent donc à Jacob les dieux étrangers qui étaient entre leurs mains, ainsi que les pendants d’oreilles. Jacob les enfouit sous le térébinthe des Sécimes, et on ne les a jamais retrouvés jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Israël décampa de la terre des Sécimes, et une terreur causée par Dieu tomba sur toutes les villes des alentours, en sorte que les fils de Jacob ne furent point poursuivis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Et Jacob ainsi que tout le peuple qui était avec lui arrivèrent à Luza, la même que Béthel, en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Il y bâtit un autel, et il donna à ce lieu le nom de Bethel, parce que c’est là que le Seigneur lui était apparu, quand il fuyait Esau son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Cependant Déborra, la nourrice de Rachel, mourut, et elle fut ensevelie sous un chêne au-dessous de Béthel, et Jacob nomma l’arbre Chêne de deuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Or, Dieu apparut encore à Jacob en Luza, à son retour de la Mésopotamie Syrienne, et Dieu le bénit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Et lui dit: Tu ne t’appelleras plus Jacob, mais ton nom sera Israël. Et il s’appela Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Dieu lui dit: Je suis ton Dieu: croîs et multiplie; des nations et des réunions de nations proviendront de toi, et des rois sortiront de tes reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'La terre que j’ai donnée à Abraham et à Isaac, je te la donne; elle sera à toi, et après toi je donnerai cette terre à ta race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Après quoi, Dieu s’éloigna de lui et du lieu où il avait parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Aussitôt, Jacob, au lieu même où Dieu lui avait parlé, dressa une colonne de pierre sur laquelle il répandit des libations et versa de l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Et il nomma Bethel le lieu où Dieu lui avait parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Ensuite ayant décampé de Béthel, Jacob dressa ses tentes au delà de la tour de Gader. Comme il approchait de Habrath pour arriver en Éphratha, Rachel enfanta, et elle souffrit beaucoup dans l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Il advint, pendant qu’elle enfantait ainsi péniblement, que la sage-femme lui dit: Prends courage, c’est un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Or, au moment où son âme allait la quitter, car elle mourut, elle lui donna le nom de Fils de ma douleur (Bénoni), mais le père l’appela Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Rachel mourut donc et fut ensevelie sur le chemin de l’hippodrome d’Éphratha, aujourd’hui Bethléem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Et Jacob dressa sur son sépulcre une colonne qu’on nomme encore aujourd’hui: Colonne du sépulcre de Rachel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Or, tandis qu’Israël demeurait en cette terre, Ruben s’éloigna et dormit avec Balla, concubine de son père Jacob. Israël apprit le fait et l’eut en abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Or, les fils de Jacob étaient douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Fils de Lia: premier-né de Jacob, Ruben, puis Siméon, Lévi, Issachar et Zabulon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Fils de Rachel, Joseph et Benjamin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Fils de Balla, servante de Rachel, Dan et Nephthali;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Fils de Zelpha, servante de Lia, Gad et Aser: tels sont les fils de Jacob qui lui naquirent en la Mésopotamie Syrienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Jacob alla ensuite en Mambré, auprès d’Isaac son père, dans la ville de la plaine qui est Hébron, en la terre de Chanaan, où Abraham et Isaac furent passagers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Bientôt les jours que vécut Isaac formèrent cent quatre-vingts ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Isaac mourut, et il se réunit à son peuple, âgé et plein de jours; ses fils Ésau et Jacob l’ensevelirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Voici les générations d’Esau, le même qu’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau prit ses femmes parmi les filles des Chananéens: Ada fille d’Elom, Hettéen, et Olibema, fille d’Ana, fils de Sébégon, Évéen;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Et Basemath, fille d’Ismaël, sœur de Nabéoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada lui enfanta Eliphaz, et Basemath, Raguel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Olibema enfanta Jéhul, Jéglon et Coré; tels sont les fils d’Esau qui lui naquirent en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ensuite Esau prit ses femmes, ses fils, toutes les personnes de sa maison, et tout ce qui lui appartenait, et tous ses bestiaux, et tout ce qu’il avait acquis, et tout ce qu’il s’était approprié en la terre de Chanaan. Et Esau sortit de la terre de Chanaan, s’éloignant de la face de son frère Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Car, leur avoir était trop considérable pour qu’ils demeurassent ensemble, et la terre de leur parcours ne pouvait pas les recevoir tous deux, à cause de la multitude de leurs possessions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Esau habita donc en la montagne de Séir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Voici les générations d’Esau, le même qu’Edom, père des Edomites, en la montagne de Séir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Et voici les noms des fils d’Esau: Eliphaz, fils d’Ada, femme d’Esau, et Raguel, fils de Basemath, femme d’Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Eliphaz eut pour fils: Théman, Omar, Sophar, Gatham et Cenez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Thamna fut la concubine d’Eliphaz, fils d’Esau, et elle lui enfanta Amalec: tels sont les fils d’Ada, femme d’Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Et voici les fils de Raguel: Nachoth, Zaré, Somé, Mozé tels sont les fils de Basemath, femme d’Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Et voici les fils d’Olibema, fille d’Ana, fils de Sébégon, femme d’Esau: Jéhu, Jéglon et Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Voici les chefs fils d’Esau: fils d’Eliphaz, premierné d’Esau, le chef Théman, le chef Omar, le chef Sophar, le chef Cenez;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Le chef Coré, le chef Gatham, le chef Amalec; ces chefs sont nés d’Eliphaz en la terre d’Idumée; ce sont les fils d’Ada, femme d’Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Et voici les fils de Raguel, fils d’Esau: le chef Nachoth, le chef Zaré, le chef Somé, le chef Mozé; ces chefs sont nés de Raguel en la terre d’Edom; ce sont les fils de Basemath, femme d’Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Et voici les fils d’Olibema, femme d’Esau: le chef Jéhu, le chef Jéglon, le chef Coré; ces chefs sont nés d’Olibema, femme d’Esau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Tels sont les chefs nés d’Esau; on les appelle aussi fils d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Voici les fils de Séir, Horréen, habitant la contrée: Lotan, Sobal, Sébégon, Ana,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Asar et Rison; ces chefs des Horréens sont nés du fils Séir, en la terre d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Et les fils de Lotan furent Horri et Héman; Thamna fut sœur de Lotan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Voici les fils de Sobal: Golam, Manachath, Ébal, Sophar et Omar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Voici les fils de Sébégon: Aia et Ana; c’est cet Ana qui trouva Jamin dans le désert, comme il paissait les bêtes de somme de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Voici les enfants d’Ana: Dison et Olibema, fille d’Ana.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Et voici les fils de Dison: Amada, Asban, Ithran et Harran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Voici les fils d’Asar: Balaam, Zucam et Jucam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Voici les fils de Rison: Hus et Aran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Et voici les chefs des Horréens: le chef Lotan, le chef Sobal, le chef Sébégon, le chef Ana,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Le chef Dison, le chef Asar, le chef Rison: tels sont les chefs des Horréens en leurs commandements, dans la terre d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Et voici les rois qui ont régné en Edom, avant qu’un roi régnât en Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'En Edom régna Balac, fils de Béor; le nom de sa ville est Dennaba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Balac mourut, et à sa place régna Jobab, fils de Zara de Bosra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Jobab mourut, et à sa place régna Asom, de la terre de Théman.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Asom mourut, et à sa place régna Adad, fils de Barad, qui battit Madian dans la plaine de Moab; le nom de sa ville est Gethaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Adad mourut, et à sa place régna Samada de Massecca.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Samada mourut, et à sa place régna Saül de Rooboth, celle qui est auprès du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Saül mourut, et à sa place régna Ballanan, fils d’Achobor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Ballanan mourut, et à sa place régna Arad, fils de Barad; le nom de sa ville est Phogor, et il eut pour femme Méectabel, fille de Matraith, fils de Mézaab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Voici les noms des chefs nés d’Esau, en leurs tribus, leurs villes, leurs contrées, leurs nations le chef Thamna, le chef Gola, le chef Jether,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Le chef Olibema, le chef Ela, le chef Phinon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Le chef Cenez, le chef Théman, le chef Mazar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Le chef Magdiel, le chef Zaphoïn: tels furent les chefs d’Edom, lorsqu’ils demeurèrent en la terre qu’ils avaient acquise; et leur père fut Esau ou Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Cependant, Jacob demeurait dans la terre où son père avait été passager, la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Voici les générations de Jacob. Joseph avait dix-sept ans, et il paissait, avec ses frères, les brebis de son père; il était le plus jeune, et il paissait les brebis avec les fils de Balla, et avec les fils de Zelpha, femmes de son père; et ils portèrent contre Joseph à leur père une méchante accusation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Jacob aimait Joseph plus qu’aucun de ses fils, parce qu’il était le fils de sa vieillesse; et il lui fit faire une tunique bigarrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Ses frères, ayant vu que son père l’aimait plus qu’aucun de ses fils, le haïrent; et ils ne pouvaient plus lui dire une seule parole de paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Or, Joseph, ayant eu un songe, le rapporta à ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Il leur dit: Écoutez le songe que j’ai eu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Il me semblait que vous faisiez des gerbes au milieu du champ: ma gerbe se tenait debout et restait droite, et vos gerbes entourant la mienne se prosternaient devant elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Ses frères lui dirent: Est-ce que tu dois être roi et régner sur nous, ou nous dominer comme un seigneur? Et ils le haïssaient plus encore, à cause de ses songes et à cause de son récit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Il eut plus tard un autre songe qu’il raconta à son père et à ses frères, disant: J’ai encore eu un songe; le voici c’était comme le soleil, et la lune, et onze étoiles qui m’adoraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Son père le réprimanda, et lui dit: Qu’est-ce que ce songe que tu as eu? Est-ce donc que moi, et ta mère, et tes frères, nous en viendrons à t’adorer sur la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Ainsi ses frères le jalousaient; quant au père, il méditait sur ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Sur ces entrefaites, ses frères partirent pour paître en Sichem les brebis de leur père;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Et Israël dit à Joseph: Tes frères ne paissent-ils pas en Sichem? Viens, que je t’envoie auprès d’eux; et il dit: Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Jacob lui dit: Vas-y; vois si tes frères se portent bien, ainsi que les brebis, et rapporte-le moi. Joseph étant donc parti de la vallée d’Hébron pour aller en Sichem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Un homme le rencontra errant dans la campagne, et l’homme l’interrogea, disant: Que cherches-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Il répondit: Je cherche mes frères; dis-moi où ils paissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'L’homme reprit: Ils ont quitté leur pâturage, car je les ai entendus se dire: Allons en Dothaïn. Joseph alla aussitôt où étaient ses frères, et il les trouva en Dothaïn.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Dès qu’ils l’aperçurent de loin, bien avant qu’il les eût abordés, ils pensèrent méchamment à le faire mourir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Et ils se dirent entre eux: Voilà le songeur qui vient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Maintenant donc allons, tuons-le, et jetons-le dans une des citernes; puis nous dirons: Une bête fauve l’a mangé; nous verrons alors ce qu’il adviendra de ses songes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Ce qu’ayant entendu Ruben, il résolut de l’arracher de leurs mains, et il dit: Non, ne lui donnons pas le coup de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Ruben, qui voulait l’arracher de leurs mains et le rendre à son père, leur dit: Ne versez pas de sang; jetez-le dans une des citernes du désert, mais ne portez pas les mains sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Lors donc que Joseph arriva près de ses frères, ils le dépouillèrent de la tunique bigarrée dont il était vêtu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Et, l’ayant pris, ils le jetèrent dans la citerne, qui alors se trouvait vide; il n’y avait pas une goutte d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Ils s’assirent ensuite pour manger du pain, et, ayant levé les yeux, ils virent des voyageurs ismaélites arrivant de Galaad avec leurs chamelles chargées de parfums, de gomme et de myrrhe qu’ils allaient vendre en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Alors, Juda dit à ses frères: Que nous reviendra-t-il d’avoir fait périr notre frère, et de cacher son sang?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Vendons-le plutôt à ces Ismaélites et ne portons pas les mains sur lui, car il est notre frère et notre chair. Ses frères Y consentirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Comme les marchands madianites approchaient, ils tirèrent Joseph de la citerne, le mirent sur pied, et le vendirent aux Ismaélites vingt drachmes d’or; et les hommes emmenèrent Joseph en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Cependant, Ruben était revenu vers la citerne, et n’y voyant point Joseph, il déchira ses vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Puis se tournant vers ses frères, il leur dit: L’enfant n’est plus là; et moi, où désormais irai-je?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Ils prirent la tunique de Joseph, égorgèrent un chevreau pris parmi les chèvres, souillèrent de sang la tunique bigarrée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Et la renvoyèrent à leur père; ceux qui la portaient lui dirent: Nous avons trouvé cette tunique, vois si ce n’est pas la tunique de ton fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Il la reconnut aussitôt, et dit: C’est la tunique de mon fils; une bête fauve l’a mangé, une bête fauve a ravi Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Et Jacob déchira ses vêtements; il ceignit ses reins d’un cilice, et il pleura son fils bien des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'En vain ses fils se réunirent-ils avec ses filles, et vinrent-ils tous pour le consoler; il ne voulut point être consolé, disant: Je descendrai près de mon fils au sein de la terre en pleurant. Et le père de Joseph le pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Quant aux Madianites, ils vendirent Joseph en Égypte, à Putiphar, eunuque du Pharaon, chef de ses cuisines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'En ce temps-là, il advint que Juda se sépara de ses frères, et s’en alla chez un Odollamite, dont le nom était Hiras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Juda vit là une fille de Chananéen dont le nom était Sué; il la prit, et il s’approcha d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Celle-ci ayant conçu, enfanta un fils qu’elle nomma Her.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Puis, ayant conçu de nouveau, elle enfanta un fils qu’elle nomma Onan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Elle enfanta encore un fils qu’elle appela Séla; or, elle habitait Chasbi lorsqu’elle les enfanta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Juda prit pour Her, son premier-né, une femme dont le nom était Thamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Her, premier-né de Juda, fut méchant devant le Seigneur, et Dieu le fit périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Juda dit alors à Onan: Approche-toi de la femme de ton frère, épouse-la, et relève la race de ton frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mais Onan, sachant que les enfants ne seraient point pour lui, lorsqu’il s’approchait de la femme de son frère, répandait la semence à terre, afin de ne point donner de race à son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Et il parut méchant devant Dieu pour avoir fait cela, et Dieu fit mourir celui-là aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Juda dit alors à Thamar, sa bru: Reste veuve dans la maison de ton père jusqu’à ce que mon fils Séla soit grand. Mais il se disait en lui-même: Prenons garde que celui-là aussi ne meure comme ses frères. Et Thamar, étant partie, demeura en la maison de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Les jours s’écoulèrent, et Sué, femme de Juda, mourut; après que Juda se fut consolé, il s’en alla avec Hiras, son pâtre Odollamite, en Thanina, vers ceux qui tondaient ses brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Et des gens vinrent à Thamar, sa bru, disant: Voici que ton beau-père monte en Thamna pour tondre ses brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Alors, elle quitta ses vêtements de veuve, et mit son large voile; elle se fit belle, et elle s’assit devant la porte d’Enan qui est sur le chemin de Thamna, car elle voyait que Séla avait grandi et que Juda ne la lui faisait point prendre pour femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Juda l’ayant vue, la prit pour une prostituée, car elle avait voilé sa figure, et il ne la reconnut pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Il quitta le chemin pour aller à elle, et il lui dit: Laisse-moi m’approcher de toi; car il ne savait pas que c’était sa bru; elle lui dit: Que me donneras-tu si tu t’approches de moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Je t’enverrai, répondit-il, un chevreau de mon troupeau de chèvres; elle repartit: Tu me donneras des gages jusqu’à ce que tu me l’aies envoyé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Et il reprit: Quel gage te donnerai-je? Ton anneau, dit-elle, ton petit collier, et la baguette que tu as à la main. Il les lui donna donc; il s’approcha d’elle, et elle conçut de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Puis, s’étant levée, elle partit, ôta et replia son large voile, et elle remit ses vêtements de veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'De son côté, Juda donna le chevreau à son pâtre d’Odollam, pour qu’il retirât ses gages des mains de la femme; mais celui-ci ne put la trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Il interrogea les hommes du lieu: Où est la prostituée qui s’est assise à Enan sur le chemin? Ils lui dirent qu’il n’y avait pas de prostituée dans le pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Et il retourna près de Juda: Je n’ai trouvé personne, dit-il, et les hommes du lieu affirment qu’il n’y a point chez eux de prostituée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Et Juda dit: Qu’elle retienne les gages, mais que l’on se garde de nous faire des reproches: car j’ai envoyé le chevreau, et tu n’as point trouvé la personne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Or, il advint, trois mois après, que des gens allèrent trouver Juda, disant: Thamar, ta bru, s’est prostituée, et elle a conçu de sa prostitution; et Juda dit: Qu’on l’amène et qu’elle soit brûlée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Comme on l’emmenait, elle envoya à son beau-père, disant: C’est de l’homme à qui ces choses appartiennent que j’ai conçu; et elle ajouta: Reconnais à qui sont l’anneau, le petit collier et la baguette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Et Juda les reconnut, et il dit: Thamar est plus juste que moi, car je ne l’ai point donnée à Séla mon fils. Mais il ne la connut plus de nouveau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Or, il advint, lorsqu’elle allait enfanter, que deux jumeaux étaient dans ses entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Et pendant qu’elle enfantait, l’un présenta d’abord une main à laquelle la sage-femme attacha de l’écarlate, disant Celui-ci sortira le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Dès qu’il eut retiré sa main, soudain son frère sortit, et la sage-femme dit: Pourquoi est-ce toi qui as rompu la clôture? et elle lui donna le nom de Pharès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Après cela l’autre frère sortit, ayant encore au bras l’écarlate, et elle le nomma Zara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Cependant, Joseph fut conduit en Égypte, et Putiphar, eunuque du Pharaon, Égyptien, chef des cuisines, l’acheta des Ismaélites qui l’avaient amené.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Or, le Seigneur était avec Joseph; c’était un homme à qui tout réussissait, et il demeura dans la maison auprès de son maître égyptien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Son maître savait que le Seigneur était avec lui, et que, quoi qu’il entreprît, le Seigneur mettrait en ses mains le succès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Joseph trouva donc grâce devant son maître, et il lui était agréable, et son maître l’établit chef de sa maison; il lui confia tout ce qui lui appartenait, et il n’en disposa plus que par les mains de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Or, lorsqu’il l’eut établi chef de sa maison, et lui eut confié tout ce qui lui appartenait, le Seigneur bénit la maison de l’Égyptien à cause de Joseph, et la bénédiction du Seigneur fut sur tout ce qu’il possédait, en sa maison et à ses champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Il confia donc à Joseph et remit en ses mains tout ce qui lui appartenait, et il ne sut rien par lui-même, hormis le pain qu’il mangeait. Joseph était beau de visage, et plein de grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Or, après tout cela il arriva que la femme de Putiphar jeta les yeux sur Joseph, et lui dit: Dors avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Mais lui ne voulut point, et il dit à la femme de son maître Mon seigneur ne connaît rien dans sa maison, à cause de sa confiance en moi; il a remis en mes mains tout ce qu’il possède.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Rien dans cette maison n’est au-dessus de mon pouvoir: il ne s’est rien réservé hormis toi, parce que tu es sa femme; comment donc ferai-je cette méchante action, et me rendrai-je à ce point coupable devant Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Et quand tous les jours elle parlait à Joseph, il refusait toujours de dormir avec elle, et de s’unir à elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Or, un jour il advint que Joseph entra dans la maison au sujet de ses travaux, et nul de ceux de la maison ne se trouvait à l’intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Et elle le tira par son manteau, disant: Dors avec moi; mais lui, laissant le manteau dans ses mains, il s’échappa, et sortit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Lorsqu’elle vit qu’il lui avait laissé son manteau dans les mains, qu’il s’était échappé, et était sorti,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Elle appela tous ceux de sa maison, et dit: Voyez, Putiphar nous a amené un serviteur hébreu pour nous outrager; il est entré ici disant: Dors avec moi, et j’ai jeté de grands cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Mais lorsqu’il a entendu que j’élevais la voix et que je criais, il a laissé chez moi son manteau, s’est échappé, et est sorti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Elle retint donc le manteau près d’elle jusqu’à ce que le maître revînt en sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Elle lui fit le même récit, disant: Il est venu près de moi ce serviteur hébreu que tu as introduit chez nous, pour m’outrager, et il m’a dit: Je dormirai avec toi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Et lorsqu’il a entendu que j’élevais la voix et que je criais, il a laissé chez moi son manteau, s’est échappé et est sorti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'À peine le maître eut-il entendu les paroles de sa femme, lui affirmant que son serviteur l’avait ainsi traitée, qu’il fut transporté de colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'I prit Joseph et il le jeta en prison, au même lieu où étaient renfermés les prisonniers du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Et le Seigneur était avec Joseph; il répandit sur lui sa miséricorde, il lui fit trouver grâce devant le gardien des prisonniers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Le geôlier en chef confia même à Joseph la prison avec tous ceux qu’on y avait amenés; et tout ce qui se faisait là, c’était par Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Le gardien en chef de la prison ne voyait plus rien par lui-même; car tout était entre les mains de Joseph, parce que le Seigneur était avec lui, et que dans tout ce qu’il entreprenait le Seigneur mettait le succès en ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'À la suite de ces événements, il arriva que le grand échanson du roi d’Égypte et le grand panetier se rendirent coupables envers leur seigneur le roi d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Et le Pharaon fut transporté de colère contre ses deux eunuques: le grand échanson et le grand panetier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Il les fit jeter en prison, au lieu même où avait été conduit Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Et le geôlier les confia à Joseph qui prit soin d’eux; ils furent bien des jours dans la prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Après quoi, tous les deux en la même nuit eurent un songe; cette vision en songe du grand échanson et du grand panetier du roi d’Égypte dans la prison était telle qu’on va dire:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Joseph étant entré près d’eux le matin, les vit tout troublés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Il interrogea les eunuques du Pharaon qui étaient en prison avec lui, au pouvoir de son maître, disant: Pourquoi vos visages sont-ils attristés aujourd’hui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Ils répondirent: Nous avons eu chacun un songe, et il n’y a personne ici pour les interpréter. Joseph leur dit: N’est-ce pas à Dieu qu’il appartient de les expliquer? Racontez-les-moi donc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Le grand échanson raconta donc à Joseph le songe qu’il avait eu, et il dit: Pendant mon sommeil, une vigne était devant moi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Elle avait trois souches, et elle était en fleur, projetant des bourgeons, et même des grappes de raisin mûr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Comme j’avais en ma main la coupe du Pharaon, je pris une grappe et je la pressai dans la coupe que je remis en la main du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Voici, lui dit Joseph, l’interprétation de ton songe: Les trois souches sont trois jours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Encore trois jours, et le Pharaon se souviendra de tes services; il te rétablira dans ta charge de grand échanson, et tu mettras la coupe en la main du Pharaon, comme autrefois quand tu lui versais à boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mais souviens-toi de moi, au nom de toi-même, lorsque tu seras heureux; use envers moi de miséricorde, parle en ma faveur au Pharaon, afin qu’il me tire de cette forteresse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Car c’est par un larcin que j’ai été enlevé de la terre des Hébreux, puis, en ce pays j’ai été jeté en prison, sans avoir rien fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Le grand panetier, voyant qu’il avait si bien interprété, dit à son tour à Joseph: Moi aussi j’ai eu un songe: il me semblait porter sur ma tête trois corbeilles de grain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'La corbeille la plus élevée contenait toutes les espèces de gâteaux dont mange le Pharaon; et les oiseaux du ciel aussi mangeaient dans la corbeille la plus haute qui était sur ma tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Et Joseph, répondant, lui dit: Voici ton interprétation les trois corbeilles sont trois jours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Encore trois jours, et le Pharaon séparera ta tête de ton corps; il te suspendra à une croix, et les oiseaux du ciel mangeront de tes chairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Le troisième jour vint, jour de la naissance du Pharaon, et il fit un festin à tous ses serviteurs. Mais, du milieu d’eux, il se souvint de l’office du grand échanson et de l’office du grand panetier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Il rétablit le grand échanson en son office, et celui-ci mit la coupe dans les mains du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Quant au grand panetier, il fut suspendu à une croix, selon ce que leur avait dit Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Cependant, le grand échanson ne se souvint point de Joseph, et le laissa en oubli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Deux ans après, le Pharaon eut un songe: il lui sembla se tenir près du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Il crut voir en sortir sept vaches extrêmement belles et grasses en leur chair, qui se mirent à paître dans la prairie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Après celles-là, il sortit du fleuve sept autres vaches, laides et maigres, qui se mirent à paître à côté des autres sur la rive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Mais les sept vaches laides et maigres dévorèrent les sept autres belles et grasses, et le Pharaon s’éveilla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Il eut ensuite un second songe: c’étaient sept épis sortant d’une même tige, beaux et choisis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Et après ceux-là poussèrent sept épis maigres et amincis par le vent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Les sept épis maigres et amincis par le vent mangèrent les épis choisis et pleins. Et le Pharaon s’éveilla: le songe était fini.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Lorsque le jour parut, son âme fut troublée; il envoya mander tous les interprètes de l’Égypte et tous les sages; il leur raconta ses songes, et il n’y eut là personne pour les expliquer au Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Alors, le grand échanson parla au Pharaon, disant: Je me souviens aujourd’hui de ma faute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Le Pharaon était irrité contre ses serviteurs, et il nous avait mis en prison dans la maison du chef des cuisines, moi et le grand panetier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Et nous eûmes chacun un songe en la même nuit; le grand panetier et moi séparément, nous eûmes chacun un songe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Or, il y avait là, avec nous, un jeune Hébreu, serviteur du chef des cuisines; nous lui dîmes nos songes, et il les interpréta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Et, selon son interprétation, il nous advint à moi d’être rétabli dans mon office, et au grand panetier d’être suspendu à une croix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Le Pharaon envoya aussitôt mander Joseph; ses gens l’amenèrent, le rasèrent, lui passèrent une autre robe, et il entra vers le Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Et le Pharaon dit à Joseph: J’ai eu un songe, et il n’est ici personne pour l’interpréter; or, j’ai ouï dire que des songes t’ayant été racontés, tu en avais donné l’interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joseph répondit au Pharaon: Sans l’aide de Dieu il ne peut être donné au Pharaon de réponse salutaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Et le Pharaon dit à Joseph: En mon sommeil, il me sembla me tenir sur les bords du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Je crus voir sortir du fleuve sept vaches extrêmement belles et grasses en leur chair, qui se mirent à paître dans la prairie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Derrière elles, il sortit du fleuve sept autres vaches, mauvaises, laides et maigres, telles que dans toute l’Égypte je n’en ai jamais vu de plus laides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Et les sept vaches laides et maigres mangèrent les sept premières, qui étaient belles et grasses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Celles-ci entrèrent dans leurs entrailles; et il ne parut point qu’elles eussent été ainsi absorbées dans leur ventre, car l’aspect des maigres resta ce qu’il était d’abord; et, après m’être éveillé, je me rendormis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Ensuite, j’eus dans mon sommeil une nouvelle vision: il me sembla que sept épis se levaient sur une même tige, beaux et pleins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Et sept autres épis, maigres et amincis par le vent, poussèrent après ceux-là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Puis, les sept épis maigres et amincis par le vent mangèrent les sept épis beaux et pleins. J’ai parlé aux interprètes, et il ne s’est trouvé parmi eux personne pour me donner une explication.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Joseph répondit au Pharaon: Le songe du Pharaon est un seul et même songe; Dieu a montré au Pharaon ce qu’il doit faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Les sept vaches grasses sont sept années, les sept épis pleins sont sept années aussi; le songe du Pharaon est un seul et même songe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Les sept vaches maigres qui sortent du fleuve après les premières, sont sept années, et les sept épis maigres, amincis par le vent, sont sept années: il y aura sept années de famine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'C’est ce que je viens de dire au Pharaon: Dieu lui a montré ce qu’il veut faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Pendant sept années, il y aura grande abondance en toute la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Ensuite, viendront sept années de famine, et l’on oubliera l’abondance qu’il y aura eu en toute l’Égypte; la famine épuisera toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Et l’abondance ne laissera pas de traces sur la terre à cause de la famine qui viendra après elle; car cette famine sera terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Si le songe du Pharaon s’est produit deux fois, c’est pour signifier qu’il est véritablement la parole de Dieu, et que Dieu est près de l’accomplir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Maintenant donc, choisis un homme intelligent et sage, et mets-le à la tête de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Que le Pharaon agisse: qu’il institue des chefs de canton en la contrée, et que ces chefs envoient tous les produits de l’Égypte, pendant les sept années d’abondance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Qu’ainsi l’on réunisse toutes les denrées de ces bonnes années qui vont venir, que l’on amoncelle tout le blé sous la main du Pharaon, et que des vivres soient gardés dans les villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Ces vivres conservés seront pour l’Égypte, pendant les sept années de famine qui viendront en la contrée, et elle ne sera pas consumée par le fléau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Ce discours fut agréable au Pharaon et à tous ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Et le Pharaon dit à tous ses serviteurs: Où pourrons-nous trouver un pareil homme en qui soit l’esprit de Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Il dit aussi à Joseph: Puisque Dieu t’a fait voir toutes ces choses, il n’y a pas d’homme plus sage et plus intelligent que toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tu seras à la tête de ma maison, mon peuple entier obéira à ta parole, je ne serai au-dessus de toi que par le trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Et le Pharaon dit à Joseph: Je te mets aujourd’hui à la tête de toute la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Puis, le Pharaon ôtant l’anneau de sa main, le mit à la main de Joseph; il le revêtit d’une robe du lin le plus fin, et lui passa autour du cou un collier d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Il le fit monter sur un char, le second de ses chars, et il fit proclamer par un héraut qu’il l’avait mis à la tête de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Ensuite, il dit à Joseph: Je suis le Pharaon, nul sans ta volonté ne lèvera la main dans la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Le Pharaon changea le nom de Joseph en celui de Psonthomphanech, et il lui donna pour femme Aseneth, fille de Pétéphrès, prêtre d’Héliopolis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Joseph avait trente ans, lorsqu’il comparut devant le roi d’Égypte; il s’éloigna du Pharaon, et il parcourut tout le royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Pendant les sept années d’abondance la terre fut couverte de gerbes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Il recueillit alors tous les vivres de ces sept années, pendant lesquelles il y eut abondance en la terre d’Égypte, et il les plaça dans les villes: en chaque ville, les vivres des champs d’alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Joseph amoncela du blé, innombrable comme le sable de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Cependant, avant que vinssent les sept années de famine, deux fils naquirent de Joseph et d’Aseneth, fille de Pétephréès, prêtre d’Héliopolis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Joseph donna au premier-né le nom de Manassé, parce que, dit-il, Dieu m’a fait oublier toutes mes peines et toutes celles de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Il appela le second Ephraïm, parce que, dit-il, Dieu m’a grandi dans mon humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Et les sept années d’abondance qui furent en la terre d’Égypte s’écoulèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Et les sept années de famine commencèrent à venir, comme avait dit Joseph. Et la famine régnait sur toute la terre, mais il y avait du pain dans toute l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Et toute l’Égypte eut faim; le peuple cria devant le Pharaon pour avoir du pain. Et le Pharaon dit à tous les Égyptiens: Allez à Joseph, et faites ce qu’il vous dira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'La famine était sur la face de toute la terre; Joseph ouvrit donc tous les magasins de blé, et il en vendit à tous les Égyptiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'De tous les pays on venait en Égypte acheter à Joseph; car la famine régnait sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Or, Jacob, ayant vu qu’il y avait vente en Égypte, dit à ses fils: D’où vient votre nonchalance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Je sais qu’il y a du blé en Égypte; descendez-y et achetez-nous un peu de blé, afin que nous vivions et ne mourions pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Et les dix frères de Joseph allèrent acheter du blé en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mais Jacob n’envoya pas, avec ses frères, Benjamin, le frère de Joseph: Car, dit-il, j’ai peur qu’une maladie ne le prenne en chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Les fils de Jacob allèrent donc acheter, en compagnie de ceux qui partaient: car la famine était en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Or, Joseph était le chef de la contrée, et il vendait à tous les peuples de la terre; les frères de Joseph, étant arrivés, se prosternèrent devant lui, la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'À la vue de ses frères, Joseph les reconnut; mais il ne se fit point connaître à eux; il leur parla même avec sévérité, et il leur dit: D’où venez-vous? Et ils dirent: De la terre de Chanaan, acheter du blé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Joseph reconnaissait bien ses frères, mais ils ne le reconnaissaient point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Il se souvint alors des songes qu’il avait eus, et il leur dit Vous êtes des espions; vous êtes venus épier ce qui se fait en la contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Et ils dirent: Non, seigneur, tes serviteurs sont venus acheter des vivres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Nous sommes tous fils d’un seul homme, nous sommes pacifiques, et tes serviteurs ne sont pas des espions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Non, reprit-il, vous êtes venus pour voir ce qui se fait en la contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Et ils dirent: Tes serviteurs étaient douze frères en la terre de Chanaan; le plus jeune est aujourd’hui avec notre père, et l’autre ne vit plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joseph leur dit: C’est bien cela, c’est ce que je vous ai dit vous êtes des espions;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'C’est par là que vous serez reconnus. Par la santé du Pharaon! vous ne sortirez pas d’ici que votre frère le plus jeune n’y soit venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Envoyez l’un de vous et qu’il amène votre frère; en attendant, vous allez être retenus jusqu’à ce que vos paroles soient confirmées, et que l’on sache si vous dites vrai ou non. Si vous avez menti, par la santé du Pharaon! vous êtes des espions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Et il les mit en prison trois jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Le troisième jour venu, il leur dit: Faites ce que je vais vous dire, et vous vivrez, car je crains Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si vous êtes pacifiques, que l’un de vous reste en prison, et que les autres partent; allez, emportez votre blé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Et amenez-moi votre frère le plus jeune: ainsi vos paroles seront confirmées; si vous vous y refusez, apprêtez-vous à mourir. Et ils firent comme il avait dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Sur quoi, chacun dit à son frère: Oui, c’est mérité, car nous sommes coupables au sujet de notre frère; nous n’avons eu aucun souci de l’affliction de son âme; lorsqu’il nous suppliait, nous ne l’avons pas écouté; c’est pourquoi cette affliction est tombée sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben ajouta: Ne vous ai-je point dit: Ne maltraitez pas l’enfant? Mais vous n’avez rien voulu entendre, et voilà que son sang est vengé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Ils parlaient entre eux et ne savaient pas que Joseph les entendît, car il s’était servi avec eux d’un interprète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Et Joseph, s’étant éloigné, pleura; revenu auprès d’eux, il leur parla, prit Siméon, et l’enchaîna devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Cependant, Joseph ordonna qu’on remplit leurs sacs, que dans chacun on remît l’argent, et qu’on leur donnât des vivres pour la route; et il fut fait comme il avait dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Après avoir chargé le blé sur leurs ânes, ils se mirent en route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Or, l’un d’eux, ayant délié son sac pour faire manger les ânes à la première halte, vit, à l’entrée du sac, sa bourse d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Et il dit à ses frères: L’argent m’a été rendu, le voici dans mon sac; leur cœur fut saisi, ils se troublerent; car ils se disaient les uns aux autres: Pourquoi Dieu nous a-t-il fait cela?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Arrivés chez Jacob, leur père, en la terre de Chanaan, ils lui racontèrent tout ce qui leur était advenu, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'L’homme maître de la contrée nous a parlé sévèrement, et il nous a emprisonnés comme espions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Nous lui avons dit: Nous sommes pacifiques, nous ne sommes point des espions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Nous étions douze frères, fils du même père; l’un ne vit plus, et le plus jeune est aujourd’hui avec notre père, en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Mais l’homme maître de la contrée nous a dit: Vous me donnez vous-mêmes le moyen de savoir si vous n’êtes pas des espions, et si vous êtes pacifiques: laissez-moi l’un de vous, et, prenant les vivres que vous avez achetés pour votre maison, partez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Allez me chercher votre plus jeune frère: je connaîtrai alors que vous n’êtes point des espions, mais que vous êtes pacifiques; je vous rendrai votre frère, et vous pourrez négocier en ce pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Or, lorsqu’ils vidèrent leurs sacs, chacun trouva dans son sac sa bourse d’argent; ils virent les bourses d’argent, leur père les vit aussi, et ils eurent crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Sur quoi Jacob, leur père, s’écria: Vous m’avez privé de mes enfants: Joseph n’est plus; Siméon n’est plus; me prendrez-vous aussi Benjamin? C’est sur moi que tout tombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruben répondit à son père: Fais mourir mes deux fils si je ne te ramène le tien; remets-le entre mes mains, et je le reconduirai près de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Mais Jacob dit: Mon fils ne partira pas avec vous; son frère est mort, celui-ci seul m’est resté; une maladie le prendra dans le chemin où vous irez, et, de tristesse, vous ferez descendre ma vieillesse au sein de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Cependant, la famine persistait sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Lorsqu’ils eurent fini de manger le blé qu’ils avaient rapporté d’Égypte, leur père dit: Partez de nouveau, et achetez-nous un peu de blé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Juda répondit: L’homme maître de la contrée a protesté, et nous a dit: Vous ne verrez pas ma face, si votre frère le plus jeune n’est pas avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si donc tu envoies avec nous notre frère, nous descendrons et nous t’achèterons du blé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Mais si tu n’envoies pas avec nous notre frère, nous ne partirons pas, car l’homme nous a dit: Vous ne verrez pas ma face, si votre frère le plus jeune n’est pas avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Pourquoi, dit Israël, m’avez-vous fait ce mal de dire à l’homme que vous aviez un frère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Et ils reprirent: L’homme nous a interrogés sur nous et notre famille, disant: Votre père vit-il encore? Avez-vous un frère? Nous lui avons répondu selon ses questions. Pouvions-nous prévoir qu’il nous dirait; Amenez-moi votre frère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Juda dit alors à Israël, son père: Envoie l’enfant avec moi, et nous partirons, afin que nous vivions et que nous ne mourions pas, nous et toute ta maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'C’est moi qui reçois mon frère, réclame-le de ma main; si je ne le ramène pas en ta demeure, si je ne le remets pas devant tes yeux, je serai coupable envers toi tous les jours de ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Si nous n’avions point ainsi tardé, nous serions déjà revenus deux fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Et Jacob, leur père, dit: Puisqu’il en est ainsi, faites comme je vais dire: prenez dans vos sacs des fruits de cette terre, et portez à l’homme des présents de gomme et de miel, portez-lui de l’encens, de la térébenthine, de la myrrhe et des amandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Emportez le double d’argent; reportez celui qui a été retrouvé dans vos sacs, de peur que ce ne soit une méprise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Enfin, prenez votre frère, et descendez chez l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Que Dieu vous fasse trouver grâce devant lui; qu’il renvoie votre frère qu’il a gardé, et aussi Benjamin; et moi cependant, me voici comme sans enfants! sans enfants!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Ayant ainsi pris les dons, et l’argent double, les hommes emmenèrent Benjamin; ils descendirent en Égypte, et ils parurent devant Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Lorsqu’il les vit, lorsqu’il vit Benjamin son frère, né de la même mère que lui, il dit à l’intendant de sa maison Conduis ces hommes, égorge et apprête des victimes; ces hommes mangeront avec moi, à midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Le serviteur fit ce qu’avait commandé Joseph, et il introduisit les hommes en la maison de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Or, les hommes, se voyant en la maison de Joseph, dirent entre eux: On nous amène ici, à cause de l’argent remporté dans nos sacs la première fois, pour nous calomnier, mettre la main sur nous, nous faire esclaves, et prendre nos ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Ayant donc abordé l’intendant de Joseph, ils lui parlèrent dans le vestibule de la maison,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Disant: Nous te prions, seigneur; nous sommes venus une fois acheter du blé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Et, lorsque nous arrivâmes à la première halte, nous ouvrîmes nos sacs, et l’argent de chacun s’y trouvait; maintenant, nous rapportons en nos mains cet argent, du même poids.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Nous avons de plus, avec nous, d’autre argent pour acheter du blé; mais nous ne savons pas qui a remis l’argent dans nos sacs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Il leur répondit: Dieu vous soit propice; n’ayez point de crainte: votre Dieu, le Dieu de vos pères, a mis des trésors dans vos sacs; car pour moi j’ai encore votre argent, qui est de bon aloi. Ensuite, il fit venir Siméon auprès d’eux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Il leur apporta de l’eau à laver les pieds, et il fit manger leurs ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Pour eux, ils apprêtèrent leurs présents, en attendant que Joseph vint à midi; car ils avaient appris qu’il se disposait à dîner où ils étaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Joseph entra dans la maison, et ils lui présentèrent les dons qu’ils tenaient en leurs mains, se prosternant devant lui la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Il leur dit: Comment vous portez-vous? Puis il ajouta: Est-il en bonne santé votre père, le vieillard dont vous m’avez parlé? Vit-il encore?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Ils répondirent: Ton serviteur notre père est en bonne santé; il vit encore. Il reprit: Dieu bénisse cet homme; et, s’étant courbés, ils se prosternèrent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Alors, Joseph, ayant levé les yeux, aperçut Benjamin, son frère, né de la même mère que lui, et il dit: C’est là votre frère le plus jeune, que vous aviez promis de m’amener? Et il ajouta: Dieu aie pitié de toi, enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Aussitôt Joseph fut troublé; ses entrailles étaient émues à cause de son frère, il avait besoin de pleurer; et étant entré dans sa chambre à coucher, il y pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Puis s’étant lavé le visage, il revint; et, se maîtrisant, il dit: Servez le repas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'L’on servit des mets, à lui d’abord, puis à ses frères, à part, puis à part aussi aux Égyptiens qui dînaient avec lui, car les Égyptiens ne peuvent manger avec les Hébreux; c’est à leurs yeux une abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Les frères de Joseph étaient assis en face de lui: le premier né, selon son droit d’aînesse; le plus jeune, selon son âge tendre; et chacun était hors de soi en face de son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'L’on apporta devant eux des parts que leur envoyait Joseph, mais la part de Benjamin était cinq fois plus grande que toutes les autres; et ils burent, et ils se réjouirent avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Joseph donna ses ordres à l’intendant de sa maison, disant Fais remplir de vivres les sacs de ces hommes, autant qu’ils en pourront emporter, et que l’on place l’argent de chacun à l’entrée de son sac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Mets aussi ma coupe dans le sac du plus jeune, avec le prix de son blé. Et tout ce que Joseph avait commandé fut fait comme il avait dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Dès que le jour parut, les hommes furent congédiés avec leurs ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Comme ils étaient hors de la ville et pas encore très loin, Joseph dit à l’intendant de sa maison: Lève-toi, cours à la poursuite de ces hommes, arrête-les, et dis-leur: Pourquoi rendez-vous le mal pour le bien? Pourquoi m’avez-vous dérobé la coupe d’argent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'N’est-ce pas celle en laquelle boit mon seigneur? Il s’en sert pour deviner en prenant les augures; c’est bien mal ce que vous avez fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Celui-ci les rejoignit, et il leur répéta ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Ils répondirent: Pourquoi notre seigneur parle-t-il ainsi? Dieu préserve tes serviteurs d’avoir fait ce que tu');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Si nous l’avons rapporté, de la terre de Chanaan, l’argent retrouvé dans nos sacs, comment aurions-nous dérobé or ou argent, dans la maison de ton seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Celui de tes serviteurs sur qui tu trouveras la coupe, qu’il soit mis à mort, et que tous nous devenions esclaves de notre seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Soit, reprit-il; il sera fait comme vous dites: mais celui-là seulement sur qui je trouverai la coupe sera mon esclave; les autres seront absous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Ils se hâtèrent; chacun descendit son sac, et l’ouvrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Puis l’homme fouilla, en commençant par l’aîné jusqu’à ce qu’il arrivât au plus jeune, et il trouva la coupe dans le sac de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Alors, ils déchirèrent leurs vêtements; chacun remit son sac sur son âne, et ils retournèrent à la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Juda entra, avec ses frères, vers Joseph, qui était encore où ils l’avaient déjà vu, et ils tombèrent devant lui la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph leur dit: Pourquoi ayez-vous fait une telle action? Ne saviez-vous point qu’un homme comme moi devine en prenant les augures?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda repartit: Que répondrons-nous, qu’avons-nous à dire, et comment serons-nous justifiés? Dieu a découvert l’iniquité de tes serviteurs, nous serons les esclaves de notre seigneur, nous et celui sur qui la coupe a été trouvée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Dieu me préserve, reprit Joseph, d’agir de la sorte; l’homme sur qui la coupe a été trouvée sera mon esclave; mais vous, retournez en toute sécurité chez votre père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Sur quoi Juda, s’étant rapproché de lui, parla en ces termes: Je t’en conjure, seigneur, que ton serviteur dise encore une parole devant toi, et ne t’irrite pas contre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Seigneur, tu as interrogé tes serviteurs, disant: Avez-vous un père ou un frère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Et nous avons dit au seigneur: Nous avons un père avancé en âge, et il a un plus jeune fils, fruit de sa vieillesse; le frère de celui-ci est mort: lui seul est resté de sa mère, et son père l’aime tendrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Et tu as dit à tes serviteurs: Amenez-le devant moi, j’aurai soin de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Et nous avons dit au seigneur: L’enfant ne pourra quitter son père; s’il quitte son père, celui-ci mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Tu as ajouté: Si votre frère le plus jeune ne vient pas avec vous, vous ne verrez plus mon visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Lorsque nous fûmes de retour chez ton serviteur notre père, nous lui rapportâmes les paroles de notre seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Et notre père nous dit: Partez encore, achetez-nous un peu de blé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Et nous dîmes: Nous ne pourrons aller en Égypte; mais si notre frère le plus jeune vient avec nous, nous y descendrons. Car nous ne verrons pas la face de l’homme, notre frère le plus jeune n’étant pas avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'À quoi ton serviteur notre père répondit; Vous savez que ma femme m’a enfanté deux fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'L’un est sorti de chez moi; vous m’avez dit qu’il avait été la proie d’une bête farouche, et je ne l’ai pas revu jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Si donc vous emmenez loin de moi celui-ci, et qu’une maladie le prenne en chemin, de tristesse, vous ferez descendre ma vieillesse au sein de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Maintenant donc, si je retourne devant ton serviteur notre père, et si l’enfant n’est pas avec nous, lui qui à sa vie tient suspendue la vie de notre père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Dès que notre père aura vu que l’enfant n’est pas avec nous, il mourra de douleur, et nous ferons descendre au tombeau la vieillesse de ton serviteur, notre père à nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Ton serviteur a reçu de son père l’enfant, en disant: Si je ne le ramène pas en ta demeure, si je ne le remets pas devant tes yeux, je serai coupable envers toi tous les jours de ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Que je reste donc, en échange de l’enfant, esclave de mon seigneur, et que l’enfant parte avec ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Car comment retournerais-je devant le père, l’enfant n’étant pas avec nous? Que je demeure ici et ne sois pas témoin de la douleur dont sera saisi mon père!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Cependant, Joseph ne pouvait plus se retenir devant tous ceux qui l’entouraient; il dit donc: Que l’on éloigne de moi tout le monde; et nul ne resta près de Joseph, lorsqu’il se fit reconnaître par ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Et il éleva la voix avec des sanglots: tous les Égyptiens l’entendirent; on put l’ouïr dans tout le palais du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Joseph dit à ses frères: Je suis Joseph; mon père vit-il encore? Ses frères ne pouvaient lui répondre, tant ils étaient troublés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Et Joseph dit à ses frères: Approchez-vous de moi, et ils s’approchèrent; il ajouta: Je suis Joseph, votre frère, que vous avez vendu en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Ne vous affligez pas; qu’il ne vous paraisse point douloureux de m’avoir vendu ici; car c’est pour notre salut que Dieu m’y a envoyé avant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Cette année-ci est la deuxième année de famine; il y aura cinq ans encore sans labourage ni moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Dieu, en effet, m’a envoyé avant vous pour conserver votre race sur la terre, et pour nourrir vos nombreux descendants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Ce n’est donc point vous qui m’avez envoyé ici, mais Dieu, qui m’a fait comme le père du Pharaon, maître de toute sa maison, et chef de toute l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Hâtez-vous de retourner chez mon père, et dites-lui: Voici ce que dit ton fils Joseph: Dieu m’a fait maître de toute l’Égypte; descends donc auprès de moi, n’y mets point de retard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Tu habiteras en la terre de Gessen d’Arabie, et tu seras auprès de moi, toi, tes fils, et les fils de tes fils, et tes brebis, et tes bœufs, et tout ce qui t’appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Là, je te nourrirai, car il y aura encore cinq années de famine, et tu ne périras pas, ni tes fils, ni tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Vos yeux voient, et aussi ceux de Benjamin, mon frère, que c’est ma bouche qui vous parle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Annoncez donc à mon père toute ma gloire en Égypte, et tout ce que vous avez vu; faites hâte, et amenez ici mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Et se jetant au cou de Benjamin, son frère, il pleura sur lui, Benjamin pleurant aussi sur le sein de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Et, ayant embrassé ses frères, il pleura sur eux; après cela ses frères lui parlèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Le bruit s’en répandit dans le palais du Pharaon; chacun disait: Les frères de Joseph sont venus. Le Pharaon s’en réjouit, et toute sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Le Pharaon dit alors à Joseph: Dis à tes frères: Chargez vos ânes, et retournez en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Prenez votre père et tout ce qui vous appartient, puis venez auprès de moi, je vous donnerai de tous les biens de l’Égypte, et vous mangerez la moelle de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Toi cependant, ordonne qu’ils emmènent des chars d’Égypte pour vos enfants et pour vos femmes; dis-leur: Prenez votre père, et arrivez ici;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Et ne songez pas à regretter vos meubles, car tous les biens de l’Égypte sont à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Ainsi firent les fils d’Israël; Joseph leur donna des chars, selon les ordres du roi Pharaon; il leur donna des vivres pour la route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Et il leur donna deux robes à chacun; mais à Benjamin, il donna trois cents pièces d’or et cinq robes à changer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Il envoya à son père de semblables présents, avec dix ânes chargés de richesses d’Égypte, et dix mulets chargés de vivres, pour son père pendant le voyage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Puis, il congédia ses frères, et il leur dit: N’allez pas vous quereller en route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Ainsi, il remontèrent de la terre d’Égypte, et arrivèrent en la terre de Chanaan, chez Jacob leur père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Et ils lui rapportèrent tout, disant: Ton fils Joseph vit, et il commande à toute la terre d’Égypte. Jacob, tout hors de lui, ne pouvait les croire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Alors, il lui répétèrent toutes les paroles que Joseph leur avait dites, et lorsqu’il eut vu les chars envoyés par Joseph, ses esprits se ranimèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Israël s’écria: Grand est mon bonheur si Joseph mon fils vit encore; j’irai, et je le verrai avant de mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israël étant parti avec tout ce qu’il possédait, arriva au puits du Serment, et il offrit un sacrifice au Dieu de son père Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Et Dieu, pendant la nuit, parla, en une vision, à Israël, disant Jacob, Jacob; celui-ci répondit: Qu’y a-t-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Le Seigneur lui dit: Je suis le Dieu de tes pères, ne crains pas de descendre en Égypte, je t’y ferai chef d’une grande nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Je descendrai avec toi en Égypte, et je ne cesserai de te grandir jusqu’à ta mort, et Joseph te fermera les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Jacob se leva du puits du Serment, et les fils d’Israël firent monter leur père, avec ses femmes et ses richesses, sur les chars que Joseph avait envoyés pour les transporter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Et ayant pris tout ce qui leur appartenait, tout le bétail qu’ils avaient acquis dans la terre de Chanaan, ils entrèrent en Égypte: Jacob, et, avec lui, toute sa race,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Ses fils et les fils de ses fils, ses filles et les filles de ses filles; car il avait conduit en Égypte toute sa race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Or, voici les noms des fils d’Israël entrés en Égypte avec Jacob leur père. Jacob et ses fils; premier-né de Jacob, Ruben.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Fils de Ruben: Enoch et Phallos, Asron et Charmi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Fils de Siméon: Jémuël, Jamin, Aod, Achin, Saar et Saül, nés de Chananitis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Fils de Lévi: Gerson, Caath et Mérari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Fils de Juda: Her, Onan, Séla, Pharès et Zara; Onan et Her étaient morts en la terre de Chanaan; et de Pharès naquirent Esron et Jémuël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Fils d’Issachar: Thola, Phua, Asum et Sambran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Fils de Zabulon: Sered, Allon et Achoel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Ceux-là sont nés de Lia, qui les enfanta à Jacob, en la Mésopotamie syrienne, outre Dina leur fille; total des âmes, fils et filles: trente-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Fils de Gad: Saphon, Aggis, Sannis, Thasoban, Aëdis, Aroëdis et Areëlis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Fils d’Aser: Jemma, Jessua, Jéhul, Baria et Sara, leur sœur; fils de Baria: Chobor et Melchil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Ceux-là sont nés de Zelpha, que Laban donna à Lia, sa fille; et elle enfanta ses fils à Jacob: onze âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Fils de Rachel, femme de Jacob: Joseph et Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Fils de Joseph en la terre d’Égypte, nés d’Aseneth, fille de Pétéphrès, prêtre d’Héliopolis: Manassé et Ephraïm; fils de Manassé, né de sa femme syrienne Machir; et Machir engendra Galaad. Fils d’Ephraïm, frère de Manassé: Sutalam et Taam; fils de Sutalam: Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Fils de Benjamin: Bala, Bochor et Asbel; fils de Bala: Géra, Noéman, Anchis, Rhos et Mamphim; Géra engendra Arad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Ceux-là sont nés de Rachel, qui enfanta ses fils à Jacob; total: dix-huit âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Fils de Dan: Asom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Fils de Nephthali: Asiel, Goni, Issaar, Sollem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ceux-là sont nés de Balla, que Laban donna à Rachel, sa fille, qui les enfanta à Jacob; total des âmes: sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Et toutes les âmes issues de Jacob entrèrent avec lui en Égypte, au nombre de soixante-six, outre les femmes des fils de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Les fils de Joseph, nés de lui en la terre d’Égypte, étaient au nombre de neuf. Il y avait donc, de la maison de Jacob, soixante-quinze âmes en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Jacob envoya devant lui Juda à la rencontre de Joseph, vers la ville des héros, en la terre de Rhamessès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'De son côté, Joseph, ayant attelé son char, alla vers la ville des héros, à la rencontre de son père, et dès qu’il eut vu son père, il lui sauta au cou en versant d’abondantes larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Et Israël dit à Joseph: Je puis maintenant mourir, puisque j’ai vu ton visage, et que tu vis encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Joseph dit à ses frères: Je vais rapporter toutes choses au Pharaon, et lui dire: Mes frères et la maison de mon père, qui étaient en la terre de Chanaan, sont venus près de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Ce sont des pasteurs: ils étaient nourrisseurs de bétail, et ils ont amené leurs troupeaux, leurs bœufs et tout ce qu’ils possèdent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Lors donc que le Pharaon vous appellera et vous dira: Quel est votre labeur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Dites: Tes serviteurs sont pâtres; nous l’avons toujours été depuis notre enfance jusqu’à ce jour, nous et nos pères. Après cela, vous habiterez la terre de Gessen, car les Égyptiens ont en abomination tous les pasteurs de troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Joseph, les ayant quittés, fit un rapport au Pharaon, disant: Mon père, mes frères, et leurs troupeaux, leurs bœufs et tout ce qu’ils possèdent, sont arrivés de la terre de Chanaan; ils sont en la terre de Gessen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Il choisit, parmi ses frères, cinq hommes qu’il plaça devant le Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Et le Pharaon dit aux frères de Joseph Quel est votre labeur? Ils répondirent: Tes serviteurs sont pasteurs de brebis; nous le sommes ainsi que nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Ils dirent ensuite au Pharaon: Nous sommes venus séjourner en passant sur cette terre, car tes serviteurs n’ont point de pâturages pour leur bétail, à cause de la famine qui sévit en la terre de Chanaan; maintenant donc qu’il nous soit permis de demeurer en la terre de Gessen. Et le Pharaon dit à Joseph: Qu’ils demeurent en la terre de Gessen, et, si tu connais parmi eux des hommes capables, fais-les chefs de mes troupeaux. C’est ainsi que vinrent en Égypte, auprès de Joseph, Jacob et ses fils, et que le roi Pharaon l’apprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Le Pharaon dit aussi à Joseph: Ton père et tes frères sont venus auprès de toi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Voici devant toi la terre d’Égypte: établis ton père et tes frères en une terre de choix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Joseph amena Jacob, son père, devant le Pharaon, et Jacob bénit le Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Le Pharaon dit à Jacob: Quel est le nombre des années de ta vie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jacob répondit: Les jours des années de ma vie, depuis que je suis passager sur la terre, font cent trente ans. Ils ont été courts et mauvais, et n’ont point égalé en nombre les jours des années de la vie de mes pères, lors de leur passage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Et Jacob, ayant béni le Pharaon, sortit d’auprès de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Joseph établit son père et ses frères; il leur donna des possessions en la terre d’Égypte, en la meilleure contrée, c’est-à-dire en la terre de Rhamessès, selon ce que le Pharaon avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Et Joseph distribua du blé, tant par tête, à son père et à ses frères, et à toute la maison de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Car il n’y avait point de blé sur la terre, et la famine sévissait cruellement. La terre d’Égypte et la terre de Chanaan dépérissaient à cause de la famine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Joseph accumula tout l’argent qui se trouvait en la terre d’Égypte et en la terre de Chanaan, pour prix du blé que l’on achetait et qu’il distribuait. Il porta tout cet argent en la demeure du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Enfin l’argent fut épuisé dans la terre d’Égypte et dans celle de Chanaan, et tous les Égyptiens vinrent à Joseph, disant Donne-nous des vivres; faut-il que nous mourions devant toi, parce que nous n’avons plus d’argent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph leur dit: Amenez-moi vos troupeaux, et je vous donnerai des vivres en échange de vos troupeaux, puisque vous n’avez plus d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Ils amenèrent à Joseph leurs troupeaux, et Joseph leur donna des vivres en échange des chevaux, des brebis et des ânes; et, cette année-là, il les nourrit de blé échangé contre tout leur bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Ils vinrent à lui, l’année finie, et ils lui dirent: Nous faudra-t-il donc périr devant notre seigneur, parce que notre argent, nos richesses, notre bétail ont passé entre les mains de notre seigneur, et qu’il ne nous reste plus rien devant lui que notre corps et notre terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Afin donc que nous ne mourions pas et que la terre ne devienne point déserte, achète-nous nous-mêmes avec notre terre, en échange de vivres; et nous, avec notre terre, nous serons esclaves du Pharaon. Donne-nous de la semence afin que nous semions, et que nous vivions, et que nous ne mourions pas, et que la terre ne devienne point déserte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Et Joseph acheta pour le Pharaon toutes les terres des Égyptiens; car les Égyptiens vendaient leurs terres au Pharaon, à cause de la famine qui sévissait sur eux, et la terre appartint au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Joseph lui asservit tout le peuple, qui devint esclave depuis l’une des extrémités de l’Égypte jusqu’à l’autre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Hormis les terres des prêtres, que Joseph n’acheta pas, car le Pharaon leur donnait gratuitement des vivres; ils vécurent ainsi des vivres que leur avait donnés le Pharaon, et ils ne vendirent point leurs terres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Joseph dit ensuite à tous les Égyptiens: J’ai acquis aujourd’hui pour le Pharaon vous et vos terres; prenez de la semence, et ensemencez les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Ainsi la terre produira; vous donnerez la cinquième part au Pharaon, et les quatre autres seront à vous, pour ensemencer les terres et pour vous nourrir, vous et vos maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Et ils dirent: Tu nous as sauvés; nous avons trouvé grâce devant notre seigneur, et nous serons les esclaves du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Joseph leur imposa ainsi la loi qui subsiste encore aujourd’hui en la terre d’Égypte, de donner la cinquième part au Pharaon; hormis les terres des prêtres, qui n’appartiennent pas au Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Israël demeura donc en la terre de Gessen d’Égypte, et ses fils y possédaient, et ils croissaient, et ils multipliaient extrêmement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Jacob vécut encore dix-sept ans en la terre d’Égypte; et les jours de la vie de Jacob formèrent cent quarante-sept ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Or, les jours d’Israël approchaient de leur fin; il appela son fils Joseph, et il lui dit: Si j’ai trouvé grâce devant toi, mets la main sous ma cuisse, et tu me feras en vérité la miséricorde de ne point m’ensevelir en Égypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Mais de me faire reposer auprès de mes pères. Tu me transporteras d’Égypte pour m’ensevelir dans leur sépulcre; et Joseph dit: Je ferai selon ta parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Et Jacob dit: Jure-le-moi; et Joseph le lui jura. Israël s’inclina en adorant sur l’extrémité de son bâton.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Après cela l’on vint dire à Joseph que son père était malade; alors, prenant ses deux fils Manassé et Ephraïm, il se rendit auprès de Jacob,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Et l’on alla dire à Jacob: Voici ton fils Joseph qui arrive auprès de toi. À ces mots, Israël, fatigué, s’assit sur sa couche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Et Jacob dit à Joseph: Mon Dieu m’est apparu à Luza, en la terre de Chanaan; il m’a béni,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Et il m’a dit: Je te ferai croître et multiplier; je te ferai chef d’une réunion de nations; je donnerai cette terre comme héritage perpétuel à toi, et après toi à ta');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Maintenant donc, tes fils Ephraïm et Manassé, qui te sont nés en Égypte avant que j’y vinsse, sont les miens tout comme Ruben et Siméon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mais les rejetons que tu engendreras après ceux-ci, seront comptés parmi les tribus de leurs frères, et on les nommera d’après l’héritage de ceux-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Lorsque je revins de la Mésopotamie syrienne, ta mère, Rachel, mourut en la terre de Chanaan, comme j’étais près d’arriver à Ephratha, en suivant l’hippodrome de la terre d’Habratha, et je l’ensevelis sur le chemin de l’hippodrome: ce lieu est aujourd’hui Bethleem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Or, Israël, ayant vu les fils de Joseph, dit: Qui sont-ils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph dit à son père: Ce sont les fils que Dieu m’a donnés ici; et Jacob reprit: Amène-les-moi, que je les bénisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'C’est que Jacob avait les yeux affaiblis par l’âge, et il ne pouvait plus bien voir; Joseph amena les enfants à son père; celui-ci les serra dans ses bras et les baisa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Israël dit alors à Joseph: Voilà que je n’ai point été privé de te revoir, et de plus Dieu m’a montré tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Joseph les fit avancer, et ils se prosternèrent devant Jacob la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Or, Joseph, ayant pris ses fils, plaça l’un, Ephraïm, à sa main droite et à la gauche d’Israël, et l’autre, Manassé, à sa main gauche et à la droite d’Israël, et il les mena ainsi tout près de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Alors, Israël étendit la main droite, et la posa sur la tête d’Ephraïm, qui était le plus jeune, et il posa la main gauche sur la tête de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Et les bras ainsi croisés, il les bénit et il dit: Que le Dieu devant qui mes pères Abraham et Isaac ont trouvé grâce, que le Dieu qui a pris soin de moi depuis ma jeunesse jusqu’à ce jour,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Que l’ange qui m’a tiré de tous mes périls, bénisse ces deux enfants. En eux seront invoqués mon nom et le nom de mes pères Abraham et Isaac; qu’ils se multiplient à l’infini sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Or, Joseph ayant vu que son père avait posé la main droite sur la tête d’Ephraïm, en fut affligé, et il prit la main de son père pour l’ôter de la tête d’Ephraïm et la remettre sur celle de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Et Joseph dit à son père: Ce n’est pas ainsi, père, car celui-ci est le premier-né; pose la main droite sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mais Jacob ne voulut pas, et il dit: Je le sais, enfant, je le sais; celui-ci pareillement sera chef de peuple, celui-ci pareillement sera glorifié, mais son frère le plus jeune sera plus grand que lui, et sa race s’étendra en plusieurs nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Et ce même jour il les bénit, et dit: En vous l’on bénira Israël, en disant: « Puisse Dieu te traiter comme Ephraïm et comme Manassé. » Il plaça ainsi Ephraïm avant Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Israël dit ensuite à Joseph: Je meurs, mais Dieu sera avec vous, et il vous reconduira en la terre de vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Et je te donne, comme part d’élite, outre ce qu’auront mes fils, Sicime, que j’ai enlevée aux Amorrhéens par mon arc et mon glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Alors, Jacob appela ses fils, et il leur dit: Venez tous, que je vous annonce ce qui vous arrivera dans les derniers jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Venez tous, et écoutez-moi, fils de Jacob: écoutez Israël, écoutez votre père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, mon premier-né, toi ma force, et la tête de mes enfants, dur à supporter, dur par ton orgueil,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Tu t’es répandu comme une eau qui déborde: tu ne croîtras plus: car tu es entré dans la couche de ton père, et tu as souillé le lit où tu étais monté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Siméon et Lévi, frères, ont accompli ensemble l’iniquité de leur dessein:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Que mon âme n’entre point dans leur conseil, que mon cœur ne s’émeuve point dans leurs réunions; car, en leur colère, ils ont tué des hommes; en leur fureur, ils ont tranché les nerfs du taureau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maudite soit leur fureur, parce qu’elle est obstinée; maudite soit leur colère, parce qu’elle s’est endurcie; je les partagerai en Jacob; je les disperserai en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, que tes frères chantent tes louanges; tu poseras tes mains sur le dos de tes ennemis, et les fils de ton père se prosterneront devant toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Lionceau de lion, Juda, par ton rejeton, mon fils, tu seras élevé; tu t’étendras pour dormir, comme un lion et comme un lionceau: qui le réveillera?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Les chefs ne cesseront jamais de sortir de Juda, ni les souverains de son sang, jusqu’à ce qu’advienne ce qui lui est réservé; c’est lui qui sera l’attente des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Il attachera à la vigne son ânesse, et au sarment le poulain de son ânesse, puis il lavera sa robe dans le vin, et son manteau dans le sang de la grappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Ses yeux, plus que le vin, inspireront la joie, et il aura des dents plus blanches que le lait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulon demeurera près de la mer, vers le port des navires, et il s’étendra jusqu’à Sidon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issachar a convoité le bien; il s’est fixé au milieu des autres parts;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Il a vu que la stabilité est bonne, que la terre est grasse, il a consacré ses bras au travail; il est devenu laboureur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan jugera son peuple aussi bien qu’aucune autre tribu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Et que Dan devienne comme un serpent sur la route, couché dans le sentier; qu’il morde les jambes du cheval, et le cavalier tombera à la renverse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Attendant du Seigneur le salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Quant à Gad, l’incursion des ennemis l’assaillira; elle s’attaquera à ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Aser, son pain sera gras, et il donnera, même aux rois, des délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nephthali s’étale comme un rejeton plein de beauté dans ses branches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph est un fils d’accroissement, c’est mon fils prospère et bien-aimé: ô mon fils le plus jeune, reviens près de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Se concertant contre lui, ils ont fait l’injustice, et les maîtres de l’arc se sont attaqués à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Et leurs arcs ont été brisés par la force; et leurs bras ont été paralysés par la main du Dieu tout-puissant de Jacob; Israël en a été fortifié par le Dieu de ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Et mon Dieu t’a secouru; du haut des cieux il a répandu sur toi la bénédiction du ciel et la bénédiction de la terre productrice de toutes choses: à cause de la bénédiction des mamelles et des entrailles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'De la bénédiction de ton père et de ta mère. Joseph a été fortifié, et il a été béni plus que les montagnes immuables, plus que les collines éternelles ces bénédictions subsisteront sur la tête de Joseph, et sa tête s’est élevée au-dessus de la tête de ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin, loup ravissant.; le matin il mange encore, et au soir on lui donne de la nourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Tels étaient les fils de Jacob. Leur père leur dit ces choses; il les bénit, et il donna à chacun sa bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Et il leur dit: Je vais me réunir à mon peuple; ensevelissez-moi avec mes pères, dans la caverne d’Ephron l’Hettéen,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'Dans la caverne double qui fait face à Mambré, en la terre de Chanaan, et qu’Abraham a achetée d’Ephron l’Hettéen, pour en faire une sépulture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Là sont ensevelis Abraham et sa femme Sarra, Isaac et sa femme Rebecca, et enfin Lia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Ils sont ensevelis dans le champ et la caverne achetés des fils de Het.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Et Jacob cessa de donner ses ordres à ses fils, puis, ayant ramené ses pieds sur sa couche, il défaillit, et il se réunit à son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Joseph aussitôt se jeta sur la face de son père, le baisa et le pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Puis il ordonna à ses serviteurs préposés aux funérailles d’embaumer son père, et ses serviteurs embaumèrent Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Ils y employèrent quarante jours, car tel est le nombre des jours de l’embaumement, et l’Égypte fut en deuil soixante-dix jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Dès que les jours du deuil furent écoulés, Joseph s’adressa aux grands officiers du Pharaon, et il leur dit: Si j’ai trouvé grâce devant vous, parlez de moi au Pharaon, dites-lui que mon père m’a adjuré, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Tu m’enseveliras dans le sépulcre que j’ai creusé pour moi en la terre de Chanaan; que maintenant donc je parte pour ensevelir mon père, et je reviendrai auprès de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Et le Pharaon dit à Joseph: Pars et ensevelis ton père comme il t’en a adjuré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Joseph partit donc pour ensevelir son père; et avec lui partirent tous les serviteurs du Pharaon, les anciens de sa maison, tous les anciens du peuple d’Égypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Et toute la famille de Joseph, ses frères, toute sa famille paternelle ainsi que toute sa parenté; mais les brebis et les bœufs restèrent en la terre de Gessen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Des chars et des cavaliers partirent en outre avec Joseph, et ils formèrent un camp très-nombreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Arrivés à l’aire d’Atad, qui est au delà du Jourdain, ils pleurèrent Jacob avec de grands et violents gémissements, et Joseph fit à son père un deuil de sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Les hommes qui habitaient la terre de Chanaan virent le deuil auprès de l’aire d’Atad, et ils dirent: C’est un grand deuil des Égyptiens. À cause de cela on appela Deuil d’Égypte ce lieu qui est au delà du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Ainsi firent à leur père les enfants de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Ils le transportèrent en la terre de Chanaan, et ils l’ensevelirent dans la caverne double qu’avait achetée Abraham d’Ephron l’Hettéen, en face de Mambré, pour en faire une sépulture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Après cela, Joseph retourna en Égypte avec ses frères et tous ceux qui l’avaient accompagné pour ensevelir Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Et les frères de Joseph, leur père mort, se dirent: Craignons que Joseph ne nous garde rancune, et ne nous fasse porter la peine de toute la méchanceté que nous avons montrée pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Sur quoi, ils allèrent trouver Joseph, et ils lui dirent: Ton père au moment de mourir t’a adjuré, et nous a dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Parlez en ces termes à Joseph: Remets à tes serviteurs leur iniquité et le crime qu’ils ont commis en exerçant contre toi leur malice. Pardonne maintenant l’iniquité des serviteurs du Dieu de ton père. Or, pendant qu’ils parlaient ainsi, Joseph pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Et, s’étant approchés de lui, ils lui dirent: Nous sommes tes esclaves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph leur répondit: N’ayez point de crainte, car je suis de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vous m’avez voulu du mal; mais Dieu m’a voulu du bien, afin qu’advînt ce qui est aujourd’hui et qu’un peuple nombreux fût nourri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Il leur dit encore: N’ayez point de crainte: je vous nourrirai vous et vos familles. Et il les consola, et il leur parla au cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Après cela, Joseph demeura en Égypte avec ses frères, et toute la famille de son père; et Joseph vécut cent dix ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Joseph vit des fils d’Ephraïm jusqu’à la troisième génération, et les fils de Machir, fils de Manassé, naquirent sur les genoux de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Joseph parla ensuite à ses frères, et il leur dit: Je meurs; mais Dieu vous visitera, et il vous conduira de cette terre en la terre qu’il a promise à nos pères Abraham, Isaac et Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Et Joseph adjura ses frères, disant: Lorsque Dieu vous visitera, emportez d’ici mes ossements avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Joseph mourut à cent dix ans, et après qu’ils l’eurent embaumé, ils le mirent dans un cercueil en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Voici les noms des fils d’Israël venus en Égypte avec Jacob, leur père, et qui y entrèrent chacun avec toute sa famille:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Siméon, Lévi, Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issachar, Zabulon, Benjamin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan et Nephthali, Gad et Aser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Joseph, de son côté, était déjà en Égypte; or, il y avait en tout soixante-quinze âmes provenant de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Et Joseph mourut, ainsi que tous ses frères, et toute cette génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Puis, les fils d’Israël crûrent et se multiplièrent; ils se répandirent, et ils se fortifièrent beaucoup, beaucoup: ils semblaient pulluler de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Mais un autre roi s’éleva sur l’Égypte, qui ne connaissait pas Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Et il dit à sa nation: Voilà que cette race des fils d’Israël forme une multitude immense et plus forte que nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Allons donc, et employons contre eux l’artifice, de peur qu’ils ne se multiplient encore; car si une guerre survenait, ils se joindraient aux ennemis, et, nous ayant vaincus, ils sortiraient de cette contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'En conséquence, il établit sur eux des intendants des travaux, afin qu’ils les épuisassent par le labeur; et ils bâtirent des villes fortes au Pharaon: Pitho, Rhamessès et On, aujourd’hui Héliopolis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Mais plus on les opprimait, plus ils devenaient nombreux, plus leur force devenait immense, immense; et les Égyptiens avaient en abomination les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Les Égyptiens opprimaient donc par la force les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Et ils affligeaient leur vie par de durs travaux, par l’argile, par la brique, par le labeur des champs; et ils les asservissaient par la violence à tous ces travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Alors, le roi des Égyptiens parla aux sages-femmes des Hébreux qui s’appelaient la première, Séphora, la seconde, Phua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Et il dit: Lorsque vous accoucherez des femmes d’Hébreux, et qu’elles auront enfanté, si c’est un garçon, tuez-le; si c’est une fille, conservez-la.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mais les sages-femmes craignirent Dieu, et n’exécutèrent point les ordres du roi d’Égypte; elles laissèrent vivre les enfants mâles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Alors, le roi d’Égypte appela les sages-femmes, et leur dit: Pourquoi agissez-vous de la sorte, et laissez-vous vivre les enfants mâles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Et les sages-femmes dirent au Pharaon: Les femmes des Hébreux ne sont pas comme les Égyptiennes; avant l’arrivée des sages-femmes, elles enfantent, et l’accouchement est fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Et Dieu fit du bien aux sages-femmes; et le peuple se multiplia et se fortifia beaucoup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Et parce que les sages-femmes avaient eu la crainte de Dieu, elles se firent de bonnes maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Le Pharaon donna aussi ses ordres à son peuple, disant Tout enfant mâle qui naîtra aux Hébreux, jetez-le dans le fleuve; et laissez vivre toutes les filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Or, il y avait un homme de la tribu de Lévi qui épousa une des filles de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Elle conçut, et elle enfanta un garçon, et, l’ayant vu plein de grâces, ils le cachèrent pendant trois lunes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Lorsqu’ils ne purent le cacher plus longtemps, sa mère prépara pour lui une corbeille qu’elle couvrit d’un enduit de poix et de bitume; elle y plaça l’enfant, et elle posa la corbeille dans le marais sur la rive du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Comme la sœur de l’enfant observait de loin pour savoir ce qu’il deviendrait,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'La fille du Pharaon descendit au fleuve pour se baigner, tandis que ses servantes se promenaient sur la rive; elle aperçut dans le marais la corbeille, et elle envoya une servante, qui la retira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'L’ayant ouverte, elle vit un enfant pleurant dans la corbeille; aussitôt la fille du Pharaon résolut de le sauver, et elle dit: C’est un enfant des Hébreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Et la sœur dit à la fille du Pharaon: Veux-tu que je t’appelle une nourrice, parmi les femmes des Hébreux, pour allaiter l’enfant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Va, dit la fille du Pharaon; et la jeune fille, étant partie, appela la mère de l’enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'La fille du Pharaon dit à celle-ci: Soigne-moi cet enfant, et allaite-le, je te donnerai une récompense; la femme prit donc l’enfant et l’allaita.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'L’enfant s’étant développé, elle le conduisit à la fille du Pharaon; et il fut pour elle comme un fils, et elle le nomma Moïse, Car, dit-elle, nous l’avons retiré de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Or, il arriva qu’après bien des jours, Moïse, étant devenu un homme, sortit près de ses frères les fils d’Israël; il pensait à leurs souffrances, lorsqu’il aperçut un Égyptien qui frappait un Hébreu, l’un de ses frères les enfants d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Après avoir regardé tout alentour, ne voyant personne, il tua l’Égyptien, et il l’enfouit dans le sable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Le jour suivant, étant sorti, il vit deux Hébreux en venir aux mains, et il dit à celui qui avait tort: Pourquoi frappes-tu ton frère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Celui-ci dit: Qui t’a établi chef et juge sur nous? Veux-tu me tuer comme tu as tué hier l’Égyptien? Moïse fut saisi de crainte, et il se dit: La chose est-elle connue à ce point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Le Pharaon, l’ayant apprise, voulut faire périr Moïse; mais celui-ci s’éloigna de la face du Pharaon; il passa en la terre de Madian, et, étant arrivé en la terre de Madian, il s’assit auprès d’un puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Or, le prêtre de Madian avait sept filles qui paissaient les brebis de leur père Jéthro; et elles vinrent puiser de l’eau jusqu’à ce qu’elles eussent rempli les abreuvoirs, et fait boire les brebis de leur père Jéthro.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Des pâtres, étant survenus, les chassèrent; mais Moïse, s’étant levé, les délivra; il puisa de l’eau pour elles, et abreuva leurs brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Lorsqu’elles furent de retour chez Raguel, leur père, il leur dit: Pourquoi revenez-vous sitôt aujourd’hui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Elles lui répondirent: Un Égyptien nous a défendues contre les pâtres; il a puisé de l’eau pour nous, et a fait boire nos brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Et il dit à ses filles: Où est-il? Pourquoi avez-vous laissé là cet homme? Appelez-le donc, et qu’il mange de notre pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Et Moïse demeura chez l’homme, qui bientôt donna pour femme à Moïse sa fille Séphora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Celle-ci conçut, et elle enfanta un fils, que Moïse nomma Gersam: Car, dit-il, je suis passager en une terre étrangère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Cependant, après un grand nombre de jours, mourut le roi d’Égypte; en ce temps-là les fils d’Israël gémissaient à cause de leurs travaux, et poussaient des cris de douleur, et les cris qu’ils jetèrent, à cause de leurs travaux, montèrent jusqu’à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Et il entendit leurs gémissements: il se souvint de son alliance avec Abraham, Isaac et Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Et Dieu regarda les fils d’Israël, et se fit connaître à eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Moïse, cependant, paissait les brebis de Jéthro, son beau-père, prêtre de Madian; il conduisit les brebis au-dessous du désert, et il arriva en la montagne d’Horeb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Là, l’ange du Seigneur lui apparut dans un feu flamboyant qui sortait d’un buisson; Moïse voit que le buisson est enflammé et qu’il ne brûle point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Et Moïse se dit: Approchons, voyons cette grande vision, ce buisson qui ne brûle pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Dès que le Seigneur vit qu’il approchait pour voir, il l’appela du buisson; disant: Moïse, Moïse; il répondit: Qu’y a-t-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Et le Seigneur dit: Ne viens pas jusqu’ici: dénoue la chaussure de tes pieds; car le lieu où tu t’es arrêté est terre sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Le Seigneur dit encore: Je suis le Dieu de ton père, le Dieu d’Abraham, le Dieu d’Isaac, le Dieu de Jacob; et Moïse détourna le visage, car il n’osait point regarder Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Le Seigneur dit ensuite à Moïse: J’ai vu l’oppression de mon peuple en Égypte; j’ai entendu leur cri au sujet des intendants des travaux; je sais leur peine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Et je suis descendu pour les tirer des mains des hommes de l’Égypte, pour les faire sortir de cette terre, et les conduire en la terre vaste et fertile, en la terre où coulent le lait et le miel, en la terre des Chananéens, des Hettéens, des Amorrhéens, des Phérézéens, des Évéens et des Jébuséens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Le cri d’Israël est venu jusqu’à moi, et j’ai vu les maux dont les Égyptiens les accablent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Pars donc maintenant; va devant le Pharaon, roi d’Égypte, et tu feras sortir de cette terre mon peuple, les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Et Moïse dit à Dieu: Qui suis-je, moi, pour aller devant le Pharaon, roi d’Égypte, et pour faire sortir de la terre d’Égypte les fils d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Et Dieu répondit à Moïse, disant: Je serai avec toi; pour preuve que c’est moi qui t’envoie, lorsque tu emmèneras mon peuple de l’Égypte, vous sacrifierez à Dieu sur cette même montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Et Moïse dit à Dieu: Ainsi donc, j’irai vers les fils d’Israël, et je leur dirai: Le Dieu de vos pères m’a envoyé près de vous; alors, ils me demanderont quel est son nom que leur dirai-je?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Dieu répondit à Moïse: Je suis Celui qui est; et Dieu ajouta Tu parleras en ces termes aux fils d’Israël: m’a envoyé près de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Et Dieu ajouta: Tu parleras en ces termes aux fils d’Israël LE SEIGNEUR Dieu de vos pères, le Dieu d’Abraham, le Dieu d’Isaac, le Dieu de Jacob, m’a envoyé près de vous. Tel est mon nom immortel, le mémorial des générations et des générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Va donc rassembler les anciens des fils d’Israël, et dis-leur Le Seigneur Dieu de nos pères m’est apparu,: le Dieu d’Abraham, d’Isaac et de Jacob, et il m’a dit: Je vous ai surveillés et surveillés, vous et tout ce qui est arrivé en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Et Dieu ajouta: Je vous délivrerai de l’oppression des Égyptiens pour vous faire passer en la terre des Chananéens, des Hettéens, des Amorrhéens, des Phérézéens, des Gergéséens, des Évéens, des Jébuséens, en la terre où coulent le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Alors, ils seront dociles à ta voix, et tu entreras avec les anciens d’Israël chez le Pharaon, roi d’Égypte, et tu lui diras: Le Dieu des Hébreux nous a appelés; nous irons donc dans le désert, à trois journées de marche, pour sacrifier à notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Je sais cependant que le Pharaon, roi d’Égypte, ne vous laissera point partir, sinon forcé par ma main puissante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Alors, étendant mon bras, je frapperai les Égyptiens par toutes sortes de prodiges opérés sur eux, et après cela le roi vous laissera partir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Et je ferai trouver grâce à ce peuple devant les Égyptiens, car lorsque vous fuirez vous ne partirez point à vide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Toute femme demandera à sa voisine et à son hôtesse des vases d’or et d’argent, et des vêtements; vous en chargerez vos fils et vos filles. Dépouillez ainsi les Égyptiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Moïse répondit à Dieu, disant: Et s’ils ne me croient point, s’ils sont indociles à ma voix (car ils me diront sans doute Dieu ne t’est point apparu), que leur dirai-je?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Et le Seigneur lui dit: Qu’as-tu là dans ta main? Une baguette, répondit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Le Seigneur reprit: Jette-la à terre. Il la jeta à terre et elle devint serpent, et Moïse s’en éloigna bien vite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Le Seigneur dit ensuite à Moïse: Étends la main et saisis la queue du serpent. Il étendit la main, et il saisit la queue du serpent, qui redevint baguette dans sa main,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Tandis que Dieu disait: C’est pour qu’ils croient en toi et à cette apparition devant toi du Dieu de tes pères, du Dieu d’Abraham, du Dieu d’Isaac, du Dieu de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Puis le Seigneur ajouta: Mets ta main dans ton sein. Il mit la main dans son sein, et, lorsqu’il la retira, elle était devenue comme de la neige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Dieu dit encore: Remets ta main dans ton sein. Il remit la main dans son sein, et dès qu’il l’eut retirée, elle avait repris la couleur de la chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Et Dieu dit: S’ils ne te croient point et ne se rendent pas à la voix du premier signe, ils croiront à la voix du second.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'S’ils ne croient pas à ces deux signes, et qu’ils restent indociles à ta voix, tu prendras de l’eau du fleuve, tu la verseras à terre, et cette eau du fleuve que tu auras prise deviendra du sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Et Moïse dit à Dieu: Je vous conjure, Seigneur, je ne suis point capable; je ne l’étais ni hier, ni le jour précédent, je ne le suis pas même depuis que vous avez commencé à parler à votre serviteur; je suis bègue et lent à m’exprimer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Le Seigneur répondit à Moïse: Qui a donné une bouche à l’homme, qui l’a fait muet et sourd, qui l’a fait clairvoyant ou aveugle? n’est-ce point moi, le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Marche donc, et je t’ouvrirai la bouche, et je te suggérerai ce que tu auras à dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Et Moïse dit: Je vous conjure, Seigneur, choisissez un autre tout à fait capable, celui que vous devez envoyer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Le Seigneur fut irrité contre Moïse, et il dit: N’as-tu pas Aaron ton frère, le lévite: je sais qu’il parlera, lui, pour toi; il viendra à ta rencontre; et, après t’avoir vu, il sera rempli de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Tu lui parleras, tu feras passer mes paroles par sa bouche, et j’ouvrirai ta bouche et la sienne, je vous suggérerai ce que vous aurez à faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Il parlera à ta place au peuple, il sera ta bouche, et tu seras pour lui la parole de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Cette même baguette qui a été changée en serpent, tu la prendras dans ta main, et par elle tu feras des prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Alors, Moïse s’éloigna, rentra chez Jéthro son beau-père, et dit: Je vais partir et retourner vers mes frères en Égypte; je verrai s’ils vivent encore. Et Jéthro dit à Moïse: Va et porte-toi bien. Or, après un grand nombre de jours, le roi d’Égypte était mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Le Seigneur avait dit à Moïse en Madian Pars, retourne en Égypte, car ceux qui en voulaient à ta vie ne sont plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Moïse ayant donc pris sa femme et ses enfants, les fit monter sur des ânes, et retourna en Égypte. Il prit aussi en sa main sa baguette, celle qu’il avait auprès de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Et le Seigneur dit à Moïse Marche, rentre en Égypte, et tu verras les prodiges que j’accomplirai par tes mains; tu les feras devant le Pharaon, et j’endurcirai son cœur, et il ne congédiera pas le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Et tu diras au Pharaon: Voici ce que dit le Seigneur Israël est mon fils premier-né;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Et je te dis: Congédie mon peuple, afin qu’il m’offre un sacrifice; si tu refuses de le congédier, prends-y garde, je ferai périr ton fils premier-né.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Or, pendant le voyage, à la halte, un ange du Seigneur rencontra Moïse, et il cherchait à le tuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Aussitôt Séphora, ayant pris un caillou, circoncit son fils, et Moïse tomba aux pieds de l’ange, disant: Il vient de couler, le sang de la circoncision de mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Et l’ange le laissa libre parce qu’il avait dit; Il vient de couler, le sang de la circoncision de mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Cependant, le Seigneur dit à Aaron: Va dans le désert à la rencontre de Moïse. Aaron étant parti, rencontra son frère en la montagne de Dieu (Horeb), et ils s’embrassèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Moïse redit à son frère toutes les paroles du Seigneur au sujet de sa mission, et tous les ordres qu’il lui avait donnés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Ensuite, il partit avec Aaron, et ils rassemblèrent les anciens des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Et Aaron dit toutes les paroles que le Seigneur avait dites à Moïse, et il fit des miracles devant le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Le peuple crut; il se réjouit de ce que le Seigneur avait visité les fils d’Israël, et vu leur oppression; et le peuple, s’étant prosterné, adora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Après cela, Moïse entra avec son frère chez le Pharaon, et ils lui dirent: Voici ce que dit le Seigneur Dieu d’Israël: Congédie mon peuple, afin qu’ils me célèbrent une fête dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Et le Pharaon dit: Quel est donc celui-ci pour que je lui obéisse jusqu’à congédier les fils d’Israël? Je ne connais pas le Seigneur, et je ne congédie point Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Et ils reprirent: Le Dieu des Hébreux nous');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Le roi d’Égypte leur dit: Moïse, Aaron, pourquoi détournez-vous le peuple de ses travaux? Allez, que chacun de vous retourne à ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Le Pharaon dit encore: Ce peuple se multiplie maintenant de plus en plus; gardons-nous de leur donner aucun relâche en leurs travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Et il fit un ordre aux intendants et aux secrétaires des travaux, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ne donnez plus de paille au peuple pour faire de la brique comme hier et le jour précédent; qu’ils s’en aillent et qu’ils recueillent de la paille pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Imposez-leur néanmoins par jour la même quantité de briques qu’ils ont toujours faite, n’en ôtez rien; car ils ont du temps à perdre, c’est pour cela qu’ils ont crié Levons-nous, et sacrifions à notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Aggravons les travaux de ces hommes; et que leurs préoccupations soient là, au lieu d’être à de vains discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Les intendants et leurs préposés les pressèrent donc, et ils parlèrent au peuple, disant: Voici ce que dit le Pharaon: Je ne vous donnerai plus de paille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Allez vous-mêmes recueillir pour vous de la paille où vous en pourrez trouver; d’ailleurs votre tâche ne sera diminuée en rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Et le peuple se dispersa parmi toute l’Égypte pour ramasser du chaume et s’en servir au lieu de paille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Cependant, les intendants les pressaient, disant: Achevez vos travaux jour par jour, comme lorsqu’on vous donnait de la paille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Les secrétaires de la race d’Israël, institués au dessus du peuple, furent même fustigés par les intendants du Pharaon, qui disaient: Pourquoi n’avez-vous pas fait aujourd’hui la même quantité de briques qu’hier et auparavant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Et les secrétaires de la race d’Israël étant entrés vers le Pharaon, lui dirent en jetant des cris: Pourquoi traite-t-on de la sorte tes serviteurs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'On ne donne plus de paille à tes serviteurs, et l’on nous dit de faire de la brique, et tes serviteurs ont été fustigés seras-tu donc injuste envers ton peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Il répondit: Vous perdez du temps, vous demeurez oisifs, et à cause de cela vous dites: Sacrifions à notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Sortez donc à l’instant et travaillez; vous n’aurez plus de paille, et vous fournirez la même quantité de briques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Et les secrétaires de la race d’Israël se virent dans le malheur, car on leur disait: Vous ne retrancherez rien à la quantité de briques qui vous est imposée par jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Ayant rencontré Aaron et Moïse qui venaient au-devant d’eux, comme ils sortaient de chez le Pharaon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Ils leur dirent: Que Dieu vous voie et vous juge, parce que vous nous avez mis en mauvaise odeur devant le Pharaon et devant ses serviteurs, plaçant le glaive en sa main pour nous faire périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Moïse se tourna vers le Seigneur et dit: Je vous conjure, Seigneur, pourquoi avez-vous affligé ce peuple? Et pourquoi m’avez-vous envoyé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Car, depuis que je suis entré chez le Pharaon pour lui parler en votre nom, il a maltraité ce peuple, et vous n’avez point délivré votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Et le Seigneur dit à Moïse: Bientôt tu verras ce que je vais faire au Pharaon: sous ma main puissante, il congédiera le peuple; sous mon bras très-haut, il le renverra de sa contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Dieu parla encore à Moïse et lui dit: Je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'J’ai révélé à Abraham, à Isaac, à Jacob, que je suis leur Dieu, mais je ne leur ai point révélé mon nom:.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'J’ai fait alliance avec eux pour leur donner la terre de Chanaan, la terre en laquelle ils ont demeuré comme passagers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'J’ai entendu les gémissements qu’arrache aux fils d’Israël l’asservissement auquel les Égyptiens les ont réduits, et je me suis souvenu de mon alliance avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Va donc et parle aux fils d’Israël; dis-leur: Je suis le Seigneur; je vous dégagerai de la domination des Égyptiens, je vous délivrerai de la servitude, je vous affranchirai par un bras très-haut et un jugement redoutable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Vous serez mon peuple et je serai votre Dieu, et vous connaîtrez que c’est moi le Seigneur votre Dieu qui vous aurai délivrés de la domination des Égyptiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Je vous conduirai en la terre sur laquelle j’ai étendu la main, pour la donner à Abraham, Isaac et Jacob, et je vous la donnerai en héritage, moi le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Et Moïse parla, comme il lui était dit, aux fils d’Israël; mais leur pusillanimité et la dureté de leurs travaux firent qu’ils n’écoutèrent point Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Le Seigneur parla alors à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Entre, parle au Pharaon roi d’Égypte, afin qu’il renvoie de sa contrée les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mais Moïse résista au Seigneur, disant: Les fils d’Israël ne m’ont pas écouté; comment le Pharaon m’écoutera-t-il, moi qui ne sais pas parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Ainsi le Seigneur parla à Moïse et à son frère, et leur ordonna d’aller trouver le Pharaon roi d’Égypte, pour qu’il eût à renvoyer de l’Égypte les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Or, voici les chefs de leurs familles paternelles: Fils de Ruben, premier-né d’Israël: Enoch et Phallu, Hesron et Charmi; telles sont les familles issues de Ruben.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Fils de Siméon: Jamuel, Jamin, Aod, Jachin, Saar et Saül, né de la Phénicienne; telles sont les familles des fils de Siméon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Voici les noms des fils de Lévi, par familles: Gerson, Caath et Mérari; Lévi vécut cent trente-sept ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Et voici les fils de Gerson: Lobni et Sémeï, noms que portent leurs familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Fils de Caath: Amram, Isaar, Hébron et Oziel; Caath vécut cent trente-trois ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Fils de Mérari: Moholi et Musi; telles sont les maisons par familles qui eurent pour père Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram prit pour femme Jochabed, fille du frère de son père, et elle lui enfanta Aaron, Moïse et Mariam (Marie), leur sœur; Amram vécut cent trente-deux ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Fils d’Isaar: Coré, Népheg et Zéchri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Fils d’Oziel: Misaël, Elisaphan et Ségri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron prit pour femme Élisabeth, fille d’Aminadab, sœur de Nahasson, et elle lui enfanta Nadab, Abiu, Eleazar et Ithamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Fils de Coré: Asir, Elcana, Abiasar; tels sont les fils de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eléazar, fils d’Aaron, prit pour femme l’une des filles de Phutiel, et elle lui enfanta Phinéès; tels sont, par familles, les chefs issus de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Cet Aaron, ce Moïse, sont ceux à qui Dieu dit de faire sortir de la terre d’Égypte les fils d’Israël et toutes leurs forces;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ce sont eux qui parlèrent au Pharaon, roi d’Égypte; Aaron lui-même et Moïse sont ceux qui conduisirent, hors de la terre d’Égypte, les fils d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Le jour où le Seigneur parla à Moïse en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Le Seigneur parla ensuite à Moïse, disant: Je suis le Seigneur; dis au Pharaon, roi d’Égypte, les choses que je te dis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mais Moïse résista au Seigneur, disant: Je suis bègue; comment le Pharaon m’écoutera-t-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Le Seigneur dit alors à Moïse: Voilà que je t’ai fait comme le Dieu du Pharaon; Aaron, ton frère, sera ton prophète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tu diras à celui-ci tout ce que je te prescris; et Aaron, ton frère, dira au Pharaon de renvoyer de sa contrée les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Cependant, j’endurcirai le cœur du Pharaon, puis, je multiplierai mes signes et mes prodiges en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Le Pharaon ne vous écoutera pas; je ferai tomber ma main sur la terre d’Égypte, et, par ma puissance, j’en ferai sortir mon peuple, les fils d’Israël, après les avoir vengés d’une manière terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Et tous les Égyptiens connaîtront que je suis le Seigneur qui étends ma main sur la terre d’Égypte, et, du milieu de ce peuple, je ferai sortir les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Et Moïse avec Aaron exécuta ce que le Seigneur leur avait prescrit; tous les deux obéirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Moïse avait quatre-vingts ans, et Aaron, son frère, quatre-vingt-trois ans, lorsqu’ils parlèrent au Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Or, le Seigneur avait dit à Moïse et à son frère:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Si le Pharaon vous dit: Donnez-nous quelque signe, faites quelque prodige, tu diras à ton frère: Prends ta baguette, et jette-la à terre devant le Pharaon et ses serviteurs, et elle sera changée en serpent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Moïse entra donc avec Aaron devant le Pharaon et ses serviteurs, et ils firent ce que leur avait prescrit le Seigneur; Aaron jeta sa baguette devant le Pharaon et ses serviteurs, et elle fut changée en serpent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Alors, le Pharaon convoqua les sages et les magiciens de l’Égypte, et les magiciens de l’Égypte firent comme Aaron, en s’aidant de leurs sortilèges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Chacun d’eux jeta sa baguette, et les baguettes furent changées en serpents; mais la baguette d’Aaron dévora les leurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Et le cœur du Pharaon s’endurcit; il n’écouta pas ceux qui lui firent connaître les ordres du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Et le Seigneur dit à Moïse: Le cœur du Pharaon s’est endurci; il s’obstine à ne point renvoyer le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Aborde le Pharaon dès le matin; il fait à cette heure sa promenade sur l’eau; tu l’attendras sur la rive du fleuve, et tu auras à la main la baguette qui a été changée en serpent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Et tu diras au Pharaon; Le Seigneur Dieu des Hébreux m’a envoyé à toi, disant: Renvoie mon peuple pour qu’il m’offre un sacrifice dans le désert; jusqu’à présent tu ne m’as point écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Or, voici ce que dit le Seigneur: À ce signe, tu connaîtras que je suis le Seigneur; voilà que je vais frapper de ma baguette l’eau du fleuve, et elle sera changée en sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Les poissons du fleuve mourront, le fleuve lui-même deviendra fétide, et les Égyptiens ne pourront plus en boire les eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Le Seigneur dit encore à Moïse: Dis à ton frère Aaron Prends à la main ta baguette, étends la main sur les eaux de l’Égypte, sur les bras du fleuve, sur les canaux, sur les marais, sur tout amas d’eau de la contrée; et les eaux seront changées en sang dans toute la terre d’Égypte, même dans les vases de bois et de pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Moïse et Aaron firent ce que Dieu leur avait ordonné; celui-ci, ayant levé sa baguette, frappa l’eau du fleuve devant le Pharaon et ses serviteurs, et toute l’eau du fleuve fut changée en sang,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Les poissons du fleuve moururent, le fleuve devint fétide, et les Égyptiens ne purent boire de ses eaux, et il y eut du sang sur toute la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Les magiciens de l’Égypte firent encore comme Aaron, en s’aidant de leurs sortilèges, et le cœur du Pharaon s’endurcit; il n’écouta ni Moïse ni son frère, ainsi que l’avait dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Après cela, le Pharaon partit, il rentra en ses demeures, et il ne changea pas de pensées, même ayant vu ce prodige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Cependant, tous les Égyptiens creusèrent sur les bords du fleuve pour trouver de l’eau, mais ils ne purent boire de l’eau du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Et sept jours se passèrent après que le Seigneur eut frappé le fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Alors, le Seigneur dit à Moïse: Entre chez le Pharaon, dis-lui Voici ce que dit le Seigneur: Renvoie mon peuple, pour qu’il m’offre un sacrifice dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Si tu refuses de le renvoyer, je vais frapper ton territoire et le couvrir de grenouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Le fleuve vomira des grenouilles; elles monteront, et entreront dans tes palais, dans tes chambres à coucher, dans tes lits, dans toutes les habitations de tes serviteurs et de ton peuple, et jusque dans tes pâtes et dans tes fours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Les grenouilles monteront sur toi, sur tes serviteurs et sur ton peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Le Seigneur dit encore à Moïse: Dis à ton frère: Étends avec la main ta baguette sur le fleuve, sur les bras, sur les canaux, sur les marais, et fais-en sortir des grenouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Aaron étendit la main sur les eaux de l’Égypte, et il en fit sortir des grenouilles; et les grenouilles montèrent, et elles couvrirent la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Les magiciens de l’Égypte firent comme lui, en s’aidant de leurs sortilèges, et ils amenèrent des grenouilles sur la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Alors, le Pharaon appela Aaron et Moïse, et il dit: Priez pour moi le Seigneur; qu’il détourne les grenouilles de moi et des Égyptiens, et je renverrai votre peuple, et il sacrifiera au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Et Moïse dit au Pharaon: Indique-moi le moment où je dois prier pour toi, pour tes serviteurs et pour ton peuple, afin que les grenouilles s’éloignent de toi, de ton peuple et de vos demeures; elles disparaîtront de partout, hormis du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Et le Pharaon ayant dit: Au point du jour. Moïse reprit Comme tu l’as dit; afin que tu voies que nul sur la terre n’est semblable au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Les grenouilles s’éloigneront de toi, de vos maisons,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Et Moïse sortit avec Aaron du palais du Pharaon. Moïse invoqua le Seigneur pour faire partir les grenouilles, comme l’avait demandé le Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Et le Seigneur exauça la prière de Moïse: les grenouilles des maisons, des étables et des champs moururent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'On en ramassa des monceaux et des monceaux; et la terre en exhala une odeur infecte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Mais, se voyant en repos, le Pharaon endurcit encore son cœur; il n’écouta plus ni Aaron ni Moïse, ainsi que l’avait dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Et le Seigneur dit à Moïse: Dis à Aaron: Étends avec la main ta baguette, et frappe la poussière du sol; il viendra des moucherons sur les hommes, sur les quadrupèdes, et sur toute la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Aaron étendit donc avec la main sa baguette; il frappa la poussière du sol, et il vint des moucherons sur les hommes, sur les quadrupèdes; des moucherons vinrent sur toute la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Les magiciens de l’Égypte firent comme lui, en s’aidant de leurs sortilèges, afin de chasser les moucherons, mais ils ne le purent; les moucherons demeurèrent sur les hommes et sur les quadrupèdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Et les magiciens du Pharaon dirent: Le doigt de Dieu est ici; mais le cœur du Pharaon était endurci; il ne les écouta pas, ainsi que l’avait dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Le Seigneur dit ensuite à Moïse: Lève-toi de grand matin, et attends le Pharaon; il sortira pour faire sa promenade sur l’eau, et tu lui diras: Voici ce que dit le Seigneur Renvoie mon peuple, afin qu’il m’offre un sacrifice dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Si tu ne renvoies pas mon peuple, je ferai tomber sur toi et tes serviteurs, sur ton peuple et sur vos maisons, des mouches canines; et les maisons des Égyptiens seront remplies de mouches, ainsi que la terre où elles sont bâties.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Et j’illustrerai, en ce jour-là, la terre de Gessen sur laquelle est mon peuple; il n’y aura pas de mouches en elle, afin que tu voies que je suis le Seigneur Dieu de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Ainsi, je marquerai la différence entre mon peuple et le tien; ces choses arriveront demain sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Le Seigneur fit ce qu’il avait dit; et les mouches arrivèrent; il y en eut une multitude dans les demeures du Pharaon, dans les maisons de ses serviteurs, dans toute la terre d’Égypte; la terre fut dévastée par les mouches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Le Pharaon alors appela Moïse et son frère, et il dit: Allez sacrifier au Seigneur votre Dieu, dans le pays même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Moïse répondit: Il ne peut en être ainsi; nos sacrifices au Seigneur notre Dieu sont abominables aux Égyptiens; si donc nous faisons devant eux des sacrifices qui leur sont abominables, nous serons lapidés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Nous ferons trois journées de marche dans le désert, et nous sacrifierons à notre Dieu, selon ce que nous a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Et le Pharaon leur dit: Je vous congédie; sacrifiez à votre Dieu dans le désert; mais ne portez pas plus loin vos pas; priez aussi le Seigneur pour moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Je vais, dit Moïse, sortir et prier Dieu, et demain matin les mouches s’éloigneront de tes serviteurs et de ton peuple. Mais garde-toi, Pharaon, de nous tromper encore en refusant de congédier le peuple pour qu’il sacrifie au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Et Moïse sortit du palais du Pharaon, et il pria Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Le Seigneur exauça la prière de Moïse; il transporta les mouches loin du Pharaon, de ses serviteurs et de son peuple; pas une seule ne resta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mais le Pharaon, même en cette circonstance, endurcit son cœur, et il ne voulut pas renvoyer le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Le Seigneur dit alors à Moïse: Entre chez le Pharaon; dis-lui: Voici ce que dit le Seigneur Dieu des Hébreux Renvoie mon peuple, afin qu’il m’offre un sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Si tu refuses de renvoyer mon peuple, si tu le retiens encore,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'La main du Seigneur s’appesantira sur le bétail de tes champs, sur tes chevaux, tes ânes, tes chamelles, tes bœufs et tes brebis; la mortalité sera grande et terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Et je montrerai avec éclat la différence entre le bétail des Égyptiens et celui des fils d’Israël; nulle bête ne mourra parmi celles des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Dieu a même fixé le temps; il a dit: Dans la journée de demain, le Seigneur accomplira sur la contrée cette menace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Le lendemain, le Seigneur tint parole, et tout le bétail des Égyptiens mourut; mais rien ne périt parmi les bestiaux des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Et le Pharaon, même après avoir vu que, parmi les bestiaux des fils d’Israël, rien n’avait péri, s’endurcit le cœur; il ne renvoya pas le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Le Seigneur alors parla à Moïse et à son frère, disant Prenez plein vos mains de la cendre de fournaise, et que Moïse la jette en l’air devant le Pharaon et ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Qu’elle forme un tourbillon de poussière sur toute la terre d’Égypte; et il y aura sur les hommes de l’Égypte, et sur les quadrupèdes, des ulcères et des tumeurs enflammées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Ils prirent donc de la cendre de forge devant le Pharaon; Moïse la jeta en l’air, et il vint aux hommes ainsi qu’aux quadrupèdes, des ulcères et des tumeurs enflammées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Les magiciens eux-mêmes ne purent demeurer en présence de Moïse, à cause des ulcères, car il vint des ulcères aux magiciens dans toute l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Et le Seigneur endurcit le cœur du Pharaon; il n’écouta ni Aaron ni Moïse, ainsi que l’avait dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Après cela, le Seigneur dit à Moïse: Lève-toi de grand matin, et présente-toi devant le Pharaon, et dis-lui Voici ce que dit le Seigneur Dieu des Hébreux: Renvoie mon peuple, afin qu’il m’offre un sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Car, en ce moment, je fais tomber sur ton cœur, sur celui de tes serviteurs et sur celui de ton peuple, tous mes coups, afin que tu voies que nul sur la terre n’est semblable au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Aussitôt que j’aurai laissé tomber ma main, je te frapperai, et je ferai périr ton peuple, et il sera effacé de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Tu n’as été conservé qu’afin que je montre en toi ma force, et pour que mon nom soit révélé à toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Quoi donc! tu insultes encore mon peuple en refusant de le renvoyer!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Eh bien, moi, dès demain, à pareille heure, je ferai tomber une grêle abondante, telle qu’il n’y en a jamais eu en Égypte, depuis le jour de sa fondation jusqu’à aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Hâte-toi d’abriter tout le bétail que tu as aux champs, car les hommes et les bestiaux qui se trouveront aux champs, et qui ne seront pas rentrés, seront surpris par la grêle et périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Ceux des serviteurs du Pharaon qui craignaient la parole de Dieu rassemblèrent leurs bestiaux en leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Ceux qui ne faisaient aucune attention à la parole du Seigneur, laissèrent leur bétail aux champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Et le Seigneur dit à Moïse: Étends la main vers le ciel, et la grêle tombera sur toute la terre d’Égypte, sur les hommes, sur les bestiaux et sur toutes les plantes qui couvrent la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Moïse étendit donc la main vers le ciel, et le Seigneur envoya tonnerre et grêle; le feu parcourut la terre, et le Seigneur fit tomber une pluie de grêle sur toute la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'La grêle tombait mêlée de flammes; elle était terriblement épaisse, telle qu’il n’y en avait jamais eu en Égypte depuis que la nation s’y était établie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Tout fut donc frappé par la grêle dans toute l’étendue de l’Égypte, depuis l’homme jusqu’aux bestiaux. Toute l’herbe des champs fut frappée par la grêle; et tous les arbres des campagnes furent brisés par elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Excepté dans la terre de Gessen, où étaient les fils d’Israël; là il n’y eut point de grêle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Et le Pharaon fit appeler Moïse et son frère, et il leur dit: J’ai péché jusqu’à cette heure; le Seigneur est juste; mon peuple et moi nous sommes des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Priez donc pour moi le Seigneur, pour faire cesser la voix de Dieu, la grêle et les flammes, et je vous congédierai, et vous ne continuerez plus de demeurer ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Moïse répondit: Aussitôt sorti de la ville, j’étendrai les mains vers le Seigneur, et les voix cesseront; la grêle et la pluie s’arrêteront, et tu connaîtras que la terre est au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mais je sais que ni toi, ni tes serviteurs, vous ne craignez point le Seigneur encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Or, le lin et l’orge avaient été frappés, car l’orge était levée et le lin était monté en graine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mais le froment et l’épeautre n’avaient pas été frappés, parce qu’ils étaient tardifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Moïse, ayant quitté le Pharaon et la ville, étendit les mains vers le Seigneur, et les voix cessèrent, et il n’y eut plus sur la terre ni grêle ni pluie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Le Pharaon ayant vu que les voix, et la grêle et la pluie avaient cessé, continua de pécher, et il endurcit son cœur, et le cœur des hommes de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'S’étant ainsi endurci le cœur, le Pharaon refusa de congédier les fils d’Israël, ainsi que le Seigneur l’avait dit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Et le Seigneur parla à Moïse, disant: Entre vers le Pharaon, car j’ai endurci son cœur et celui des hommes de sa maison, afin qu’à l’avenir ces signes arrivent sur eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Et que vous racontiez à vos enfants, et aux enfants de vos enfants, comment les Égyptiens m’auront servi de jouet, et les signes que j’aurai faits chez eux; ainsi vous connaîtrez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Moïse, avec son frère, entra donc chez le Pharaon, et il lui dit Voici ce que dit le Seigneur Dieu des Hébreux: Jusqu’à quand refuseras-tu de me révérer? Renvoie mon peuple, afin qu’il m’offre un sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Si tu refuses de renvoyer mon peuple, demain, à pareille heure, je ferai venir sur ce territoire une multitude de sauterelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Qui couvrira la face de la terre; tu ne pourras voir la terre; et tout ce qui sort de terre, tout ce qu’a épargné la grêle, tout arbre qui germe pour vous sur ce territoire sera dévoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Tes demeures en seront remplies, ainsi que les maisons de tes serviteurs et toute habitation en la terre d’Égypte. Jamais vos pères ni vos ancêtres n’ont vu pareilles choses, depuis le jour où ils sont venus en cette contrée jusqu’à aujourd’hui. Et Moïse, s’étant détourné, quitta le Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Alors, les serviteurs du Pharaon dirent au roi: Jusqu’à quand subsistera ce scandale? Renvoie ces hommes, afin qu’ils sacrifient à leur Dieu; préfères-tu apprendre que l’Égypte a péri?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Ils firent ainsi revenir auprès du Pharaon Moïse et son frère, et le roi leur dit: Allez et sacrifiez à votre Dieu; mais quels sont ceux qui doivent partir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Et Moïse dit: Nous partirons avec nos jeunes hommes et nos vieillards, avec nos fils et nos filles, avec nos brebis et nos bœufs, car c’est la fête du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Et il répondit: Que le Seigneur soit avec vous, comme je vous renvoie; laisserai-je donc échapper vos possessions aussi; vous voyez que la malice réside en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Non pas ainsi; mais que les hommes portent ce qu’ils sacrifient au Seigneur, puisque c’est ce que vous demandez. Et on les chassa de la présence du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Le Seigneur dit alors à Moïse: Étends la main sur la terre d’Égypte, que des sauterelles montent sur la terre; qu’elles dévorent toutes les herbes de la contrée, et tous les fruits des arbres qu’a épargnés la grêle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Moïse leva sa baguette vers le ciel, et le Seigneur envoya sur la terre un vent du midi, tout le jour et toute la nuit suivante; dès que l’aurore parut, le vent du midi amena les sauterelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Il les répandit sur toute la terre d’Égypte, il les fit tomber en innombrables multitudes sur tout le territoire de l’Égypte. Jamais auparavant il n’était venu pareille nuée de sauterelles, et, après celle-là, jamais il n’en sera de semblable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Elle couvrit toute la face de la terre, et la terre en fut dévastée; elle dévora toutes les herbes de la terre, et tous les fruits des arbres que la grêle avait épargnés. Il ne resta rien de vert, ni sur les arbres, ni aux champs, dans toute la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Aussitôt, le Pharaon appela Moïse et son frère, et il leur dit: J’ai péché contre le Seigneur votre Dieu et contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Remettez-moi encore cette fois mon péché, et priez le Seigneur votre Dieu, pour qu’il me délivre de ce fléau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Moïse quitta le Pharaon, et pria le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Et le Seigneur envoya du nord un vent violent qui enleva les sauterelles et les jeta dans la mer Rouge. Il ne resta pas une seule sauterelle en toute l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mais le Seigneur endurcit le cœur du Pharaon, et celui-ci ne congédia pas les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Et le Seigneur dit à Moïse: Étends la main vers le ciel, et que des ténèbres enveloppent la terre d’Égypte, des ténèbres palpables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Moïse étendit donc la main vers le ciel, et il vint des ténèbres, un sombre tourbillon, qui enveloppa l’Égypte durant trois jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Pendant trois jours nul ne vit son frère: ces trois jours durant, nul ne se leva de sa couche; quant aux fils d’Israël, la lumière était en tous les lieux où ils se trouvaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Le Pharaon appela encore Aaron et Moïse, disant: Allez, sacrifiez au Seigneur votre Dieu; quant à vos brebis et vos bœufs, vous les laisserez; mais que vos bagages s’en aillent avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Et Moïse dit au Pharaon: Tu nous accorderas encore des holocaustes et des victimes que nous offrirons au Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Nos troupeaux doivent partir avec nous et nous n’en laisserons pas une corne, car c’est parmi eux que nous prendrons les victimes pour le Seigneur notre Dieu. Nous ne pouvons savoir ce que nous sacrifierons au Seigneur notre Dieu, avant d’être arrivés là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mais le Seigneur endurcit le cœur du Pharaon; et il ne voulut point les laisser partir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Et le Pharaon dit: Éloigne-toi de ma présence, garde-toi de voir encore mon visage, car le jour où je te verrai, tu mourras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Et Moïse reprit: Tu l’as dit, je ne paraîtrai plus devant ta face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Et le Seigneur dit à Moïse: Je frapperai d’une dernière plaie le Pharaon et l’Égypte; après cela, il vous renverra de sa contrée, et lorsqu’il vous congédiera avec tout ce qui vous appartient, il aura hâte de vous voir partir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Parle donc en secret à ton peuple; que chacun demande à son voisin des vases d’argent et d’or, et des vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Le Seigneur a fait en sorte que son peuple trouve grâce devant les Égyptiens, et ceux-ci lui prêteront; car Moïse est très-grand aux yeux des Égyptiens, du Pharaon et de ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Et Moïse dit: Voici ce que dit le Seigneur: Vers le milieu de la nuit je viendrai en Égypte:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Et tout premier-né, en la terre d’Égypte, mourra; depuis le premier-né du Pharaon qui est assis sur le trône, jusqu’au premier-né de la servante qui tourne la meule, et jusqu’au premier-né des bestiaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Et il y aura dans toute l’Égypte une grande lamentation, telle qu’il ne s’en est jamais entendu, et qu’il ne s’en fera plus entendre de semblable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Tandis que chez tous les fils d’Israël, depuis l’homme jusqu’aux bestiaux, pas un chien ne grondera de la langue; afin que tu saches quelle différence éclatante le Seigneur fera entre les Égyptiens et les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Tous tes serviteurs que voici viendront à moi, et ils se prosterneront devant moi, en disant: Pars avec tout ton peuple; retourne d’où tu es venu, et alors je partirai; et Moïse quitta le Pharaon avec colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Et le Seigneur dit à Moïse: Le Pharaon ne vous écoutera pas, afin que je multiplie et multiplie mes signes et mes prodiges en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Or, Moïse et Aaron avaient fait tous ces signes et ces prodiges devant le Pharaon en la terre d’Égypte; mais le Seigneur avait endurci le cœur du Pharaon, et celui-ci n’avait point consenti à congédier les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Et le Seigneur parla à Moïse et à son frère, en la terre d’Égypte, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Cette lune est pour vous le commencement des lunes, la première des lunes de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Parle à toute la synagogue des fils d’Israël, disant: Que le dixième jour de cette lune chacun de vous prenne une tête de son bétail dans sa maison paternelle; chacun une victime par maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Que ceux qui sont en leurs maisons trop peu nombreux pour consommer une victime, s’associent à leurs plus proches voisins, selon le nombre des âmes, afin de compléter le nombre nécessaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'La victime sera sans tache, mâle et d’un an; vous la prendrez parmi les agneaux et les chevreaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Vous la garderez jusqu’au quatorzième jour de la lune, et sur le soir, chez tout le peuple des fils d’Israël, on l’égorgera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Chacun prendra de son sang, et en mettra sur les deux montants de la porte et sur le seuil de la maison en laquelle il l’aura mangée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Cette nuit-là on mangera les chairs rôties au feu; l’on mangera aussi des azymes avec des laitues amères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Vous ne mangerez les chairs ni crues ni bouillies dans l’eau, mais seulement rôties au feu; vous mangerez la tête, les pieds et les viscères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Que rien n’en reste au matin; vous ne broierez pas non plus les os; et ce qui resterait au matin, vous le consumerez par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Vous mangerez ainsi: les reins ceints, les sandales aux pieds, le bâton à la main, et vous mangerez à la hâte c’est la pâque du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'En cette nuit-là, je traverserai toute l’Égypte, je frapperai tout premier-né en la terre d’Égypte, depuis les hommes jusqu’aux bestiaux, et j’exercerai ma justice sur tous les dieux des Égyptiens, moi le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Alors, le sang sera pour vous un signe sur les maisons où vous demeurez; je verrai ce sang, et je vous sauverai, et il n’y aura point parmi vous de plaie qui broie, lorsque je frapperai la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Ce jour-là vous sera en souvenir, et vous le fêterez comme la fête du Seigneur en toutes vos générations; vous le fêterez, c’est une loi éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Pendant sept jours vous mangerez des azymes, et à partir du premier, vous ferez disparaître le levain de vos demeures; quiconque mangera du levain, du premier au septième jour, cette âme sera retranchée d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Et le premier jour sera appelé saint, le septième jour aussi sera appelé saint par vous; vous ne ferez en ces deux jours aucune œuvre servile; vous ne ferez rien que ce qui se fait pour toute âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Et vous observerez ce précepte; car, en ce jour-là, je conduirai toute votre armée hors de la terre d’Égypte, et vous consacrerez ce jour-là, en toutes vos générations: c’est une loi éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'À partir du soir du quatorzième jour de la première lune, vous mangerez des azymes jusqu’au soir du vingt-unième jour de la lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Pendant sept jours qu’il ne se trouve pas de levain en vos demeures; quiconque mangera du pain levé, qu’il soit né dans le peuple ou étranger, cette âme sera retranchée du peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Vous ne mangerez pas de pain levé; dans toutes vos demeures, vous mangerez des azymes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Et Moïse appela les anciens des fils d’Israël, et il leur dit: Séparez-vous, prenez chacun une tête de menu bétail par famille, et immolez la pâque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Vous prendrez une branche d’hysope, vous la baignerez dans le sang laissé près de la porte, et avec le sang vous en effleurerez le linteau et les deux montants. Chacun de vous se gardera jusqu’à l’aurore de franchir le seuil de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Alors, le Seigneur viendra frapper les Égyptiens; il verra le sang sur le linteau et les montants des portes, et le Seigneur passera outre; il ne permettra pas à l’exterminateur d’entrer en vos maisons pour vous frapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Ce que je viens de vous dire, vous le garderez comme loi éternelle pour vous-mêmes et pour vos descendants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Lorsque vous serez entrés en la terre que vous donnera le Seigneur selon sa promesse, vous conserverez ce rite sacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Et quand vos fils vous diront: Quel est ce sacrifice?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Vous répondrez: C’est le sacrifice de la pâque du Seigneur, parce que lorsqu’en Égypte il a frappé les Égyptiens, il a protégé les maisons des fils d’Israël et sauvé leurs demeures. À ces mots le peuple, s’étant prosterné, adora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Et les fils d’Israël se séparèrent pour faire ce que le Seigneur avait prescrit à Aaron et à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Et, le milieu de la nuit étant venu, le Seigneur frappa tout premier-né en la terre d’Égypte, depuis le premier-né du Pharaon assis sur le trône, jusqu’au premier-né de la captive dans sa prison, et jusqu’au premier-né des bestiaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Le Pharaon se leva durant la nuit, ainsi que tous ses serviteurs, et tous les Égyptiens; il y eut un long cri en la terre d’Égypte, car il n’était pas de maison où il n’y eût un mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Et le Pharaon appela, durant la nuit, Moïse et son frère, et il leur dit: Levez-vous, sortez de mon royaume avec les fils d’Israël; allez et sacrifiez au Seigneur votre Dieu, comme vous l’avez demandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Emmenez vos brebis et vos bœufs, partez et bénissez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Et les Égyptiens en toute hâte contraignaient le peuple pour le faire sortir de la contrée: Car, disaient-ils, nous allons tous périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Aussitôt, le peuple prit sur ses épaules sa farine en pâte non encore levée, et ses pains enveloppés dans des vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Or, les fils d’Israël avaient exécuté l’ordre de Moise; ils avaient demandé aux Égyptiens des vases d’argent et d’or, et des vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Le Seigneur avait fait trouver grâce au peuple devant les Égyptiens qui leur avaient tout prêté; et ainsi le peuple dépouilla les Égyptiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Et les fils d’Israël partirent de Rhamessès pour Soccoth au nombre de six cent mille hommes de pied, outre les bagages,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Et avec eux une innombrable mêlée de brebis, de bœufs et de bêtes de somme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Et ils firent cuire la pâte qu’ils avaient emportée d’Égypte; ils en firent des azymes cuits sous la cendre; car elle n’était pas levée, tant les Égyptiens les avaient pressés de partir; ils n’avaient donc pu différer, et ils n’avaient point préparé de vivres pour la route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Or, le séjour que les fils d’Israël avaient fait tant dans la terre d’Égypte que dans celle de Chanaan, avait duré quatre cent trente ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Et, après ces quatre cent trente ans, il advint que toute l’armée du Seigneur sortit de la terre d’Égypte pendant la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Cette nuit doit être consacrée au Seigneur, comme lorsqu’il les a tirés de la terre d’Égypte; cette même nuit est à garder pour le Seigneur durant toutes les générations des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Le Seigneur dit ensuite à Moïse et à son frère: Voici la loi de la pâque: Nul étranger ne prendra part au repas pascal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Tout serviteur né dans la famille, tout esclave acheté à prix d’argent sera circoncis par vous; alors il participera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Le passager et le mercenaire n’y prendront point part.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'La pâque sera mangée dans les maisons, et vous ne porterez hors de la maison aucune part des chairs, et vous ne broierez pas un seul os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toute la synagogue d’Israël fera ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Et si quelqu’un est venu vers vous comme prosélyte, pour faire la pâque du Seigneur, circoncisez tout mâle dans sa famille; alors il sera admis à la faire, et il sera comme celui qui est né dans le pays; nul incirconcis ne prendra part à la pâque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Il n’y aura qu’une loi, tant pour l’indigène, que pour celui qui arrivera comme prosélyte parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Et les fils d’Israël firent ce que le Seigneur avait prescrit pour eux à Aaron et à Moïse; ils le firent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Et en ce jour-là, le Seigneur conduisit hors de la terre d’Égypte les fils d’Israël avec toute leur armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Consacre-moi tout premier-né, tout être qui aura ouvert des entrailles maternelles parmi les fils de mon peuple, depuis l’homme jusqu’aux bestiaux; il est à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Moïse dit donc au peuple: Souvenez-vous de ce jour où vous êtes sortis de la terre d’Égypte et de la maison de servitude, d’où le Seigneur nous a tirés par sa main puissante ce jour-là vous ne mangerez pas de levain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Vous partez aujourd’hui dans la lune des nouveaux blés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Et lorsque le Seigneur vous aura conduits en la terre des Chananéens, des Hettéens, des Amorrhéens, des Évéens, des Jébuséens, des Gergéséens et des Phérézéens, terre qu’il a promis à vos pères de vous donner, terre où coulent le lait et le miel, vous observerez en cette lune cette loi religieuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Pendant six jours vous mangerez des azymes; le septième jour, c’est la fête du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Vous mangerez des azymes sept jours; on ne verra pas de pain levé, vous n’aurez pas de levain en tout votre territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'En ce jour-là, tu instruiras ton fils, disant: C’est à cause de ce qu’a fait pour moi le Seigneur lorsque nous sommes sortis d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Et ce sera pour toi un signe attaché à ta main, un mémorial devant tes yeux, afin que la loi du Seigneur soit sur tes lèvres; car c’est par une main puissante que le Seigneur t’a tiré de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Et, dans la suite des jours, vous observerez cette loi au temps marqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Lorsque le Seigneur ton Dieu t’aura introduit en la terre des Chananéens, qu’il a promise à tes pères, et qu’il te donnera,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Tu mettras à part, pour le Seigneur, tout mâle ayant ouvert les entrailles de sa mère; tu consacreras au Seigneur, parmi le bétail et parmi les menus troupeaux, tout mâle qui aura ouvert les entrailles de sa mère: parmi tout ce qui naîtra, tu consacreras ainsi les mâles au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'En échange de tout ânon, ayant ouvert les entrailles de l’ânesse, tu pourras donner une brebis; si tu ne l’échanges, tu en paieras la rançon; tu paieras la rançon de tout premier-né de tes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Et lorsque ton fils t’interrogera sur ces choses, disant: Pourquoi cela? Dis-lui: Parce que le Seigneur, par sa main puissante, nous a tirés de la terre d’Égypte et de la maison de servitude,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Et que, quand le Pharaon s’est endurci à ne point nous congédier, il a fait périr tout premier-né en la terre d’Égypte, depuis le premier-né des hommes jusqu’au premier-né des bestiaux. Voilà pourquoi je sacrifie au Seigneur toute tête de bétail qui a ouvert les entrailles de sa mère; et pourquoi je rachèterai tout premier-né de mes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Ce sera là un signe attaché à ta main, et un mémorial devant tes yeux; car c’est par une main puissante que le Seigneur t’a tiré de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Or, lorsque le Pharaon eut congédié le peuple, Dieu ne montra pas aux fils d’Israël la route qui passe par la terre des Philistins, quoique ce fût la plus courte. Car, dit le Seigneur, prenons garde que le peuple ne se repente, en prévoyant des combats, et qu’il ne retourne en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Dieu lui fit faire un détour par le chemin qui traverse le désert jusqu’à la mer Rouge. Ce fut la cinquième génération des fils d’Israël qui sortit de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Moïse prit avec lui les ossements de Joseph: car celui-ci avait adjuré sous serment les fils d’Israël, et il avait dit: Le Seigneur vous visitera, et vous emporterez d’ici mes ossements avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Les fils d’Israël allèrent de Soccoth camper Othom vers le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Dieu les guidait, le jour, par une colonne de nuée pour leur montrer la route; la nuit, par une colonne de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Jamais, devant le peuple entier, la colonne de nuée ne manqua pendant le jour, ni la colonne de feu pendant la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Le Seigneur dit ensuite à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Parle aux fils d’Israël, qu’ils se détournent, qu’ils transportent leurs tentes à l’opposite du campement actuel, entre Magdol et la mer, en face de Béelséphon; tu les feras camper là, près de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Et le Pharaon dira à son peuple: Les fils d’Israël sont errants dans la contrée, et pris par le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Mais, moi, j’endurcirai le cœur du Pharaon; il vous poursuivra, et je serai glorifié en lui et en toute son armée; et tous les fils des Égyptiens sauront que je suis le Seigneur. C’est, en effet, ainsi qu’ils firent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'On annonça au roi des Égyptiens que le peuple avait fui; et le cœur du Pharaon et celui de ses serviteurs se tournèrent contre le peuple, et ils dirent: Qu’avons-nous fait? pourquoi avons-nous congédié les fils d’Israël, de sorte qu’ils ne nous serviront plus?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Le Pharaon attela donc ses chars, et il emmena avec lui tout son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Il prit six cents chars d’élite, avec toute la cavalerie des Égyptiens, et tous les grands du royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Et le Seigneur endurcit le cœur du Pharaon, roi d’Égypte, ainsi que celui de ses serviteurs; le Pharaon poursuivit les fils d’Israël; mais, dans leur marche, les fils d’Israël étaient conduits par une puissante main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Les Egyptiens, les ayant poursuivis, les trouvèrent campés près de la mer. Tous les chevaux, tous les chars du Pharaon, sa cavalerie et son armée se déployèrent, contre le camp, en face de Béelséphon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Le Pharaon s’approcha; et les fils d’Israël, ayant levé les yeux, virent les Égyptiens campés derrière eux, et ils eurent grande crainte. Les fils d’Israël invoquèrent le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Et ils dirent à Moïse: C’est parce que nous n’avions pas de tombeaux en Égypte, que tu nous as amenés pour mourir dans le désert. Pourquoi nous as-tu fait cela en nous tirant de l’Égypte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'N’est-ce point là ce que nous te disions en Égypte: Laisse-nous servir les Égyptiens; mieux vaut pour nous les servir que d’aller périr dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Rassurez-vous, répondit Moïse au peuple, faites halte, et soyez attentifs au salut que le Seigneur va vous envoyer aujourd’hui même. Ces Égyptiens que vous apercevez en ce moment, vous ne les verrez plus à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Le Seigneur combattra pour vous, pendant que vous resterez tranquilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Et le Seigneur dit à Moïse: Que cries-tu vers moi? Parle aux fils d’Israël, et qu’ils lèvent leur camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Four toi, prends ta baguette: étends la main sur la mer; ouvre ses flots; les fils d’Israël entreront au milieu de la mer comme sur un sol affermi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Et j’endurcirai le cœur du Pharaon et de tous les Égyptiens; ils y entreront après vous, et je serai glorifié en ce Pharaon, en son armée entière, en ses chars et en sa cavalerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Et tous les Égyptiens connaîtront que je suis le Seigneur, lorsque je me serai glorifié en ce Pharaon, en ses chars et en ses chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Cependant, l’ange du Seigneur qui précédait les fils d’Israël, changea de place et passa derrière eux; la colonne de nuée, quittant leur front, se posa derrière eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Elle se mit entre le camp des Égyptiens et le camp des fils d’Israël, et s’y tint; il y eut obscurité et ténèbres; les deux camps étaient séparés par la nuit, et, durant toute la nuit, ils ne se rejoignirent point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Alors, Moïse étendit la main sur la mer, et le Seigneur, durant toute la nuit, fit souffler un vent violent sur la mer les flots s’ouvrirent, et la mer fut à sec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Et les fils d’Israël entrèrent au milieu de la mer comme sur un sol affermi; les eaux formaient un mur à droite et un mur à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Les Égyptiens les poursuivirent; toute la cavalerie du Pharaon, les chars et les écuyers entrèrent à leur suite au milieu des flots.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'La veille du matin arrivée, le Seigneur abaissa ses regards sur l’armée des Égyptiens, du milieu de la colonne de nuée et de feu, et il confondit l’armée des Égyptiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Il embarrassa les essieux de leurs chars, il les poussa violemment; et les Égyptiens se dirent: Fuyons loin de la face d’Israël, car le Seigneur combat pour eux contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Mais le Seigneur dit à Moïse: Étends la main sur la mer, que l’eau reprenne son cours, qu’elle couvre les Égyptiens, les chars et les écuyers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Et Moïse étendit la main sur la mer; comme le jour paraissait, l’eau commença à reprendre sa place, et les Égyptiens s’enfuyaient devant les eaux, et le Seigneur confondit les Égyptiens au milieu de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'L’eau, qui reprenait sa place, couvrait les chars et les écuyers, et toute l’armée du Pharaon: de tous ceux qui, derrière Israël, étaient entrés dans la mer, il n’en échappa pas un seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Cependant, les fils d’Israël avaient marché à pied sec au fond de la mer, l’eau formant pour eux un mur à droite et un mur à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'En ce jour-là, le Seigneur sauva Israël des mains des Égyptiens; et Israël vit les cadavres des Égyptiens sur les bords de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Alors, Israël vit la grande main du Seigneur; il vit comme elle avait frappé les Égyptiens; et le peuple eut crainte du Seigneur; il crut en Dieu et en son serviteur Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Alors, Moïse chanta, avec les fils d’Israël, ce cantique au Seigneur; ils dirent: Chantons au Seigneur, car il s’est glorifié avec éclat, et il a précipité dans la mer le cheval et le cavalier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Il m’a sauvé, il a été mon secours et mon protecteur; c’est mon Dieu, et je le glorifierai; c’est le Dieu de mon père, et je l’exalterai;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'C’est le Seigneur qui broie les armées le Seigneur est son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Il a précipité dans la mer les chars du Pharaon et son armée, et les grands de son royaume montés sur des chars; la mer Rouge les a engloutis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Il les a cachés sous les flots; ils se sont enfoncés dans l’abîme comme une pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Votre droite, Seigneur, a été glorifiée en sa force; votre main droite, Seigneur, a brisé les ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'À la plénitude de votre gloire, vous avez exterminé nos persécuteurs, vous avez déchaîné votre colère; elle les a dévorés comme de la paille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Au souffle de votre colère, l’eau s’est séparée, les eaux se sont dressées comme un mur; les flots se sont affermis au milieu de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'L’ennemi a dit: Je poursuivrai, je saisirai, je partagerai les dépouilles; je rassasierai mon âme, je tuerai à coups de glaive; ma main prévaudra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Vous avez envoyé votre souffle: la mer les a cachés; ils ont été submergés, comme du plomb, sous les ondes impétueuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Qui donc est semblable à vous parmi les dieux, ô Seigneur? Qui donc est semblable à vous, Dieu, glorifié au milieu des saints, admirable en gloire, fécond en prodiges?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Vous avez étendu votre droite, la terre les a engloutis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Dans votre justice vous avez guidé votre peuple que vous avez racheté, vous l’avez consolé par votre force, pour le conduire au séjour saint de votre repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Les nations ont entendu et se sont irritées; les douleurs de la femme qui enfante ont saisi le peuple Philistin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Les chefs d’Edom et les princes des Moabites se sont hâtés, la crainte les a frappés; tous ceux de Chanaan se sont consumés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Que la terreur et l’épouvantement les assaillent; qu’ils soient pétrifiés par la grandeur de votre bras, jusqu’à ce que soit passé votre peuple, ô Seigneur, jusqu’à ce que soit passé ce peuple que vous avez acquis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Conduisez ce peuple, établissez-le en la montagne de votre héritage, en la demeure digne de vous que vous vous êtes préparée, Seigneur, en ce lieu consacré qu’ont préparé vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Le Seigneur règne sur les siècles, sur les siècles et au delà.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Les chevaux du Pharaon, ses chars et leurs écuyers, sont entrés dans la mer; et le Seigneur a ramené sur eux les flots, et les fils d’Israël ont marché à pied sec au fond de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Alors, Marie, la prophétesse, sœur d’Aaron, prit en ses mains un tambour, et toutes les femmes sortirent à sa suite, en dansant et en frappant leurs tambours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Et Marie entonna le chœur, disant: Chantons au Seigneur, car il s’est glorifié avec éclat; il a précipité dans la mer le cheval et le cavalier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Après cela, Moïse fit quitter aux fils d’Israël les bords de la mer Rouge, et il les conduisit dans le désert de Sur. Ils firent trois journées de marche dans le désert, et ils ne trouvèrent point d’eau à boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Arrivés à Mara, ils ne purent boire l’eau qui s’y trouvait, parce qu’elle était amère; c’est pourquoi ils appelèrent ce lieu Amertume (Mara).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Et le peuple murmura contre Moïse, disant: Que boirons-nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Moïse aussitôt cria au Seigneur, et le Seigneur lui montra un arbre dont il jeta le bois dans l’eau; et l’eau devint douce. Là, Dieu lui proposa sa loi et sa justice, après l’avoir éprouvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Et le Seigneur lui dit: Si tu écoutes la voix du Seigneur ton Dieu et fais ce qui lui est agréable, si tu observes ses commandements et restes docile à sa justice, je ne te frapperai d’aucune des plaies dont j’ai frappé l’Égypte, car je suis le Seigneur ton Dieu, ton Dieu qui te guéris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'De là, ils vinrent à Elim, où il y avait douze sources d’eau vive et soixante-dix palmiers; et ils campèrent au bord des eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Partie d’Elim, toute la synagogue des fils d’Israël arriva au désert de Sin, qui est entre Elim et Sina; et le quinzième jour du second mois, après la sortie d’Égypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Tout le peuple d’Israël murmura contre Aaron et Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Plût à Dieu, leur dirent les fils d’Israël, que nous eussions péri frappés par le Seigneur en la terre d’Égypte, lorsque nous étions assis devant des marmites pleines de viande, et que nous mangions du pain à satiété; puisque vous nous avez conduits en ce désert pour faire mourir de faim tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Et le Seigneur dit à Moïse: Voilà que je vais faire tomber des pains du ciel; le peuple sortira de ses tentes, et il les recueillera pour chaque jour, afin que je l’éprouve, et que je sache s’il marchera selon ma loi ou non.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Le sixième jour chacun préparera ce qu’il aura rapporté, et ce sera le double de ce qu’on recueillera chaque jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Et Moïse et Aaron dirent à toute la synagogue des fils d’Israël Ce soir vous reconnaîtrez que c’est le Seigneur qui vous a tirés de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Et, à l’aurore, vous verrez la gloire du Seigneur, qui a entendu vos murmures contre Dieu; car, que sommes-nous, pour que vous murmuriez contre nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Moïse dit encore: Le Seigneur montrera sa gloire en vous donnant le soir des chairs à manger, et le matin des pains à satiété; car il a entendu vos murmures contre nous, et que sommes-nous? Ce n’est point contre nous que sont vos murmures, mais contre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Ensuite Moïse dit à Aaron: Dis à toute la synagogue des fils d’Israël: Allez devant Dieu, il a entendu vos murmures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Dès qu’Aaron eut parlé à toute la synagogue des fils d’Israël, et qu’ils se furent retournés du côté du désert, la gloire du Seigneur leur apparut en une nuée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'J’ai entendu le murmure des fils d’Israël, dis-leur: Sur le soir vous mangerez de la chair, et à l’aurore vous vous rassasierez de pain, et vous connaîtrez que je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Sur le soir, il vint, en effet, des cailles qui couvrirent tout le camp; le matin, une rosée tomba autour du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Et voilà que, sur la face du désert, il y eut une chose légère, semblable à de la coriandre blanche, semblable à du givre sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Ce qu’ayant vu, les fils d’Israël se dirent entre eux Qu’est-ce que cela? Car ils ne savaient ce que c’était; et Moïse leur dit: C’est le pain que le Seigneur vous donne à manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Voici le commandement du Seigneur: Recueillez-en chacun pour votre famille un gomor par tête, selon le nombre de vos âmes; que chacun de vous en recueille avec ceux qui demeurent sous sa tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Ainsi firent les fils d’Israël; ils en ramassèrent: l’un beaucoup, l’autre moins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Puis, ils mesurèrent au gomor, selon le nombre de têtes; et ceux qui eurent le plus, n’eurent point trop, et ceux qui eurent le moins, eurent assez; chacun en ramassa autant qu’il lui en fallait pour les siens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Et Moïse leur dit: N’en laissez rien pour demain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mais tous n’obéirent pas à Moïse; quelques-uns en gardèrent pour le lendemain, et il en sortit des vers; une mauvaise odeur s’en exhala, et Moïse s’irrita contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Ils en recueillirent ainsi tous les matins, chacun selon ses besoins, et, quand le soleil répandait sa chaleur, le reste fondait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Le sixième jour vint, et ils en recueillirent le double, deux gomors par tête, et tous les princes de la synagogue vinrent en faire le rapport à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Moïse leur dit N’est-ce point là le commandement du Seigneur? Demain est le jour du sabbat, le saint · repos du Seigneur: tout ce que vous avez à cuire, cuisez-le; tout ce que vous avez à préparer, préparez-le; et tout le superflu vous le laisserez pour demain en réserve dans vos tentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Ils en conservèrent jusqu’au lendemain, comme le leur avait ordonné Moïse, et il n’y eut point de mauvaise odeur, et il ne s’y trouva pas de vers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Alors, Moïse dit: Mangez cela aujourd’hui, car');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Vous recueillerez six jours; mais le septième, le jour du sabbat, il n’y aura rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Or, le septième jour, quelques-uns sortirent pour ramasser de ces vivres, et ils ne trouvèrent rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Et le Seigneur dit à Moïse: Jusqu’à quand refuserez-vous d’obéir à mes commandements et à ma loi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Voyez, ce jour-ci est le sabbat prescrit par le Seigneur; c’est pourquoi, le sixième jour, il vous a donné les vivres de deux jours. Que chacun reste en repos sous sa tente, que nul ne sorte le septième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Et, le septième jour, le peuple observa le sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Quant à cet aliment, les fils d’Israël lui donnèrent le nom de manne; il ressemblait à la graine de coriandre blanche, et il avait le goût de la fleur de farine, mêlée avec le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Et Moïse dit: Voici le commandement du Seigneur: Remplissez de manne un gomor pour le conserver à votre postérité; qu’elle voie le pain que vous avez mangé dans le désert, quand le Seigneur vous eut fait sortir de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Moïse dit aussi à Aaron Prends un vase d’or, verses-y le gomor de manne, et dépose-le devant le Seigneur pour le conserver à votre postérité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Comme Dieu l’a prescrit à Moïse. Et Aaron déposa le vase devant le témoignage pour le conserver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Les fils d’Israël mangèrent de la manne jusqu’à ce qu’ils fussent arrivés en leur demeure; ils s’en nourrirent jusqu’à ce qu’ils eussent atteint la frontière de la Phénicie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Le gomor était le dixième de trois mesures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Après avoir quitté le désert de Sin, la synagogue des fils d’Israël établit ses campements comme le prescrivit le Seigneur et campa en Rhaphidin, où il n’y avait point d’eau à boire pour le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Alors, le peuple injuria Moïse, disant: Donne-nous de l’eau, afin que nous buvions; et Moïse leur dit: Pourquoi m’injuriez-vous? Pourquoi tentez-vous le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'En ce lieu, le peuple souffrit de la soif, et le peuple murmura contre Moïse, disant: Qu’as-tu fait? Nous as-tu tirés de l’Égypte pour nous faire mourir de soif, nous, et nos enfants et notre bétail?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Moïse aussitôt cria au Seigneur, disant: Que ferai-je à ce peuple! Encore un peu, et ils me lapideront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Et le Seigneur dit à Moïse: Avance-toi en face de ce peuple, prends avec toi quelques-uns des anciens du peuple, prends à la main la baguette avec laquelle tu as frappé le fleuve, et pars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Et moi je me tiens, avant que tu y arrives, sur les rochers d’Horeb; là tu frapperas la pierre; il en sortira de l’eau, et le peuple boira. Ainsi fit Moïse devant les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Et il nomma ce lieu Tentation et Outrage, à cause des injures des fils d’Israël, et parce qu’ils avaient tenté le Seigneur, disant: Le Seigneur est-il avec nous, oui ou non?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Peu après, Amalec vint apporter la guerre à Israël en Rhaphidin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Et Moïse dit à Josué: Choisis avec toi les hommes forts; sors à leur tête demain matin, et range-les en bataille devant Amalec; cependant, je me tiendrai sur la cime du mont, la baguette de Dieu à la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Josué fit ce que lui avait prescrit Moïse; il sortit, se rangea en bataille devant Amalec, et Moïse, avec Aaron et Hur, monta sur la cime du mont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Or, il advint que, lorsque Moïse levait les bras, Israël l’emportait; mais quand il les baissait, Amalec triomphait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Comme ses bras se fatiguaient, Hur et Aaron placèrent sous lui une pierre, sur laquelle il s’assit; puis, Aaron et Hur soutinrent ses bras l’un d’un côté, l’autre de l’autre; et les bras de Moïse furent soutenus jusqu’au coucher du soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Josué mit en fuite Amalec, et il passa tout son peuple au fil de l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Et le Seigneur dit à Moïse: Écris cela sur un livre, que ce soit un mémorial; ensuite dis à Josué cette parole: J’effacerai de la terre le souvenir d’Amalec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Et Moïse bâtit au Seigneur un autel, qu’il nomma: le Seigneur est mon refuge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Car, dit-il, le Seigneur, d’une main inflexible, combattra contre Amalec de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Cependant Jéthro, prêtre de Madian, beau-père de Moïse, apprit tout ce que le Seigneur Dieu d’Israël avait fait en faveur de son peuple; car le Seigneur avait tiré Israël de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Et Jéthro, beau-père de Moïse, avait reçu Séphora, femme de Moïse, après la séparation,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Ainsi que ses deux fils, l’un, qu’à sa naissance il nomma Gersam, parce que, dit-il, je suis passager en une contrée étrangère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'L’autre, qu’il nomma Eliézer, parce que, dit-il, Dieu est mon auxiliaire, et il m’a tiré des mains du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jéthro, beau — père de Moïse, les fils de celui-ci et sa femme, partirent donc pour l’aller trouver dans le désert, où il campait sur la montagne du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Et l’on vint dire à Moïse: Voilà que ton beau-père Jéthro arrive avec ta femme et tes deux fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Moïse alla à la rencontre de son beau-père; il se prosterna devant lui, et il le baisa; après qu’ils se furent tous embrassés, il les conduisit sous sa tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Là, Moïse raconta à son beau-père tout ce que le Seigneur avait fait aux Égyptiens et au Pharaon, à cause d’Israël, ainsi que toutes ses souffrances sur la route, depuis que le Seigneur les avait tirés d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jéthro fut saisi d’admiration pour les bienfaits de Dieu en faveur du peuple, et parce qu’il l’avait tiré des mains des Égyptiens, et des mains du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Et Jéthro dit: Béni soit le Seigneur, parce qu’il a tiré Israël des mains des Égyptiens, et des mains du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Je reconnais aujourd’hui à ce qui est advenu, quand les Égyptiens vous ont poursuivis, que le Seigneur est grand au-dessus de tous les dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Et Jéthro, beau-père de Moïse, fit des holocaustes et des sacrifices à Dieu. Or, Aaron et tous les anciens d’Israël survinrent pour manger des pains devant le Seigneur, avec le beau-père de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'À l’aurore, Moïse s’assit pour juger le peuple, et la multitude comparut devant Moïse, depuis le matin jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Jéthro, ayant vu tout ce qu’il faisait en faveur du peuple, dit: Que fais-tu? Pourquoi sièges-tu seul, quand le peuple comparaît devant toi, depuis le matin jusqu’au soir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Moïse répondit à son beau — père: Tout le peuple vient à moi, demander jugement au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Quand une contestation s’élève entre eux, ils viennent à moi, je juge chacun, et je leur rappelle les commandements de Dieu et sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Et le beau-père de Moïse lui dit: Tu n’agis pas bien en cette œuvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Tu consumeras toi et ton peuple par une fatigue insoutenable; trop pesante est cette œuvre pour toi, et tu ne pourras la faire seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Écoute-moi donc; je te donnerai un conseil, et Dieu sera avec toi; sois pour le peuple l’interprète des choses de Dieu, et rapporte à Dieu ses paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Tu leur déclareras les ordres de Dieu et sa loi; tu leur indiqueras les voies en lesquelles ils doivent marcher, et les œuvres qu’ils auront à faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Cependant, choisis parmi le peuple, pour te les associer, des hommes forts et pieux, des hommes justes, haïssant l’orgueil; mets à la tête du peuple des chefs de mille hommes, des chefs de cent, des chefs de cinquante et des chefs de dix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Qu’ils jugent le peuple à toute heure, qu’ils te rapportent toute affaire d’importance, qu’ils jugent eux-mêmes les causes les plus faciles; ils allégeront ainsi ton labeur en le partageant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si tu exécutes ce projet, Dieu te fortifiera, et tu pourras tenir bon, et ce peuple s’en ira en paix au lieu où il doit aller.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Moïse fut docile au conseil de son beau-père, et il exécuta ce qu’il lui avait dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Moïse, parmi tous les fils d’Israël, choisit des hommes forts; il les mit à la tête du peuple chefs de mille, chefs de cent, chefs de cinquante, chefs de dix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Ceux-ci jugèrent le peuple à toute heure; ils rapportèrent à Moïse toute affaire d’importance, et ils jugèrent eux-mêmes toute affaire facile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Alors, Moïse congédia son beau-père, et celui-ci retourna dans son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Le troisième jour du troisième mois après la sortie d’Égypte, les fils d’Israël arrivèrent dans le désert de Sin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Étant partis de Rhaphidin, ils arrivèrent dans le désert de Sin, et Israël y dressa ses tentes en face de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Et Moïse monta sur la montagne de Dieu, du haut de laquelle Dieu l’appela, et lui dit: Voici ce que tu diras à la maison de Jacob, ce que tu déclareras aux fils d’Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vous avez vu vous-mêmes ce que j’ai fait aux Égyptiens; je vous ai enlevés comme sur des ailes d’aigle, et je vous ai amenés près de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Si maintenant vous écoutez ma parole, si vous gardez mon alliance, vous serez mon peuple à part, parmi toutes les nations, car la terre entière est à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Vous serez pour moi un sacerdoce royal, une nation sainte; répète ces paroles aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Après cela, Moïse descendit, convoqua les anciens du peuple, et leur transmit toutes ces paroles que Dieu leur adressait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Et tout le peuple répondit d’un même cœur, et s’écria: Tout ce que Dieu a dit nous le ferons, nous lui obéirons. Et Moïse rapporta ces paroles à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Le Seigneur dit alors à Moïse: Voilà que je viens à toi en une colonne de nuée, afin que le peuple m’entende te parler, et qu’ils te croient à jamais. Moïse ensuite répéta au Seigneur les paroles du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Et le Seigneur dit à Moïse: Descends, porte témoignage au peuple; purifie-le aujourd’hui et demain; qu’ils lavent leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Qu’ils se tiennent prêts pour le troisième jour; car, en ce troisième jour, le Seigneur descendra sur la montagne de Sina devant tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Et tu sépareras le peuple, disant: Gardez-vous de gravir la montagne, ou d’y poser le pied; quiconque aura touché la montagne mourra de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Qu’aucune main ne la touche; celui qui la touchera, homme ou bête, sera lapidé ou percé de flèches, il ne vivra pas; lorsque le tonnerre, les trompettes et la nuée se seront éloignés de la montagne, quelques-uns pourront y monter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Moïse descendit donc de la montagne vers le peuple; il les purifia, et ils lavèrent leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Puis, il dit au peuple: Tenez-vous prêts; pendant trois jours ne vous approchez point de vos femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Or, le troisième jour vint, et, vers l’aurore, il Y eut sur le mont Sina des éclairs et une sombre nuée; le son de la trompette retentit avec éclat, et tout le peuple en son camp trembla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Et Moïse mena le peuple hors du camp, au-devant de Dieu, et ils se tinrent au pied de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Tout le mont Sina lançait de la fumée, parce que Dieu, enveloppé de feu, y était descendu. Et la fumée s’élevait comme celle d’une fournaise; et le peuple était en une grande stupeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Le son de la trompette redoublait d’éclat; et Moïse parla, et Dieu, de sa bouche, répondit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Et le Seigneur descendit sur le mont Sina, sur la cime de la montagne, et le Seigneur appela Moïse sur la cime, et Moïse y monta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Et le Seigneur parla à Moïse, et il lui dit: Descends, porte témoignage au peuple; prends garde qu’ils ne s’approchent pour voir Dieu, et que parmi eux une multitude ne périsse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Que les prêtres, qui approchent Dieu, se purifient, de peur que Dieu n’en fasse mourir plusieurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Et Moïse dit à Dieu: Le peuple ne pourra s’avancer sur la montagne de Sina; car vous nous avez vous-même porté témoignage, quand vous avez dit: Sépare la montagne et sanctifie-la.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Et le Seigneur lui dit: Va, descends et remonte avec Aaron; que ni les prêtres ni le peuple ne fassent d’efforts pour monter vers le Seigneur, de peur que Dieu n’en détruise plusieurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Moïse descendit donc vers le peuple, et il lui parla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Alors, le Seigneur prononça tous les discours qui suivent, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Je suis le Seigneur ton Dieu, qui t’ai tiré de la terre d’Égypte, de la maison de servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Tu n’auras point d’autres dieux que moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Tu ne te feras pas d’idoles ni d’images d’aucune chose existant au ciel, sur la terre, sous la terre et dans les eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Tu ne les adoreras point, tu ne les serviras pas; car je suis le Seigneur ton Dieu, Dieu jaloux, vengeant sur les enfants les péchés des pères, jusqu’à la troisième et à la quatrième génération de ceux qui me haïssent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Et faisant miséricorde, pendant des milliers de générations, à ceux qui m’aiment et qui observent mes commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Tu ne prendras pas en vain le nom du Seigneur ton Dieu; car le Seigneur, ton Dieu, ne regardera point comme pur celui qui aura pris son nom en vain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Souviens-toi de sanctifier le jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Pendant six jours travaille, et fais tous tes ouvrages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mais le septième jour est le sabbat (repos) du Seigneur ton Dieu; tu ne feras aucune œuvre en ce jour-là: ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bœuf, ni ton âne, ni aucune de tes bêtes, ni le prosélyte demeurant avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Car, en six jours, le Seigneur a créé le ciel, et la terre, et la mer, et tout ce qu’ils contiennent, et il s’est reposé le septième jour; c’est pourquoi Dieu a béni le septième jour, et il l’a sanctifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honore ton père et ta mère, afin que tu sois heureux et que tu vives longtemps sur la terre fortunée que te donnera le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Tu ne seras point adultère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Tu ne voleras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Tu ne tueras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Tu ne porteras point de faux témoignage contre ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Tu ne convoiteras point la femme de ton prochain; tu ne convoiteras point la maison de ton prochain, ni son champ, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni une seule de ses bêtes, ni rien de ce qui est à ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Tout le peuple entendait la voix et le son des trompettes, il voyait les lueurs et la montagne fumante; et, frappé de terreur, tout le peuple se tenait au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Et ils dirent à Moïse, parle-nous, toi; que le Seigneur cesse de nous parler, de peur que nous ne mourions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Et Moïse leur répondit: Rassurez-vous; c’est pour vous éprouver que Dieu est venu, afin que la crainte de Dieu soit en vous, et que vous ne péchiez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Tandis que le peuple d’Israël se tenait au loin, Moïse entra dans la nuée sombre où était Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Et le Seigneur dit à Moïse: Voici ce que tu diras à la maison de Jacob, ce que tu déclareras aux fils d’Israël: Vous avez vu vous-mêmes que du ciel je vous ai parlé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Vous ne vous ferez pas de dieux d’argent, vous ne ferez point pour vous de dieux d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Vous ferez un autel de terre, et vous y sacrifierez vos holocaustes et vos hosties pacifiques, brebis ou génisses, en tout lieu où j’imposerai mon nom; et je viendrai vers toi, et je te bénirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Et, si tu me bâtis un autel en pierres, tu les emploieras sans les tailler, car tu les profanerais en portant le ciseau sur elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Tu ne monteras pas par des degrés à mon autel, de peur qu’auprès de l’autel tu ne sois découvert indécemment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Voici les ordonnances que tu leur mettras sous les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Si tu achètes un serviteur hébreu, il te servira six ans, et à la septième année, il s’en ira libre sans rançon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'S’il est entré seul, il sortira seul; si sa femme est entrée avec lui, sa femme sortira avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si son maître lui a donné une femme, et qu’elle lui ait enfanté des fils et des filles, la femme et les enfants seront à son maître; lui seul sortira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Si le serviteur dit: J’aime mon maître, ma femme et mes enfants; je refuse de devenir libre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Son maître le conduira au tribunal de Dieu, il le placera devant la porte contre le seuil, et il lui percera les oreilles avec une petite alène; alors le serviteur restera à son service à perpétuité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Si un homme vend sa fille comme esclave, elle ne sortira pas comme sortent les servantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Que si elle n’a pas été agréable au maître après leurs fiançailles, il la laissera aller moyennant rançon; mais il ne pourra la vendre chez une nation étrangère, sous prétexte qu’il aurait trouvé en elle un motif de répudiation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'S’il l’a fiancée à son fils, il la traitera selon la justice due aux filles libres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Si le maître la remplace pour lui-même par une autre, il ne la sèvrera ni de sa société, ni de vêtements, ni des choses nécessaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'S’il manque à l’une de ces trois conditions, elle sortira sans rançon, sans rien payer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Si un homme en frappe un autre et si celui-ci meurt, que le premier soit puni de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mais si c’est involontairement, s’il a frappé un homme que Dieu aura livré à ses mains, je désignerai un lieu où il se réfugiera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Si un homme a guetté son prochain et l’a tué par ruse, s’il s’est enfui\', tu le prendras, même à mon autel, pour qu’il soit mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Que celui qui frappera son père ou sa mère soit puni de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Que celui qui maudira son père ou sa mère soit puni de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Que celui qui aura ravi un des fils d’Israël soit puni de mort; soit que l’ayant forcé, il l’ait vendu, soit qu’on le trouve chez lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Si deux hommes se sont querellés, et que l’un ait frappé son prochain du poing ou avec une pierre, et que celui-ci ne meure pas, mais qu’il ait gardé le lit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'S’il peut sortir appuyé sur un bâton, celui qui l’aura frappé ne sera pas condamné, mais il l’indemnisera pour le chômage, et il paiera les frais de la guérison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Si un homme frappe du bâton son serviteur ou sa servante, et si la mort s’ensuit, il sera poursuivi en justice pour être puni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Mais si le blessé survit un jour ou deux, que le maître ne soit pas poursuivi; car c’est son argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Si deux hommes se battent et qu’une femme grosse soit frappée, et qu’il en sorte un enfant non encore formé, le coupable paiera le dommage, selon l’estimation du mari de la femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mais si l’enfant est formé, le coupable donnera vie pour vie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Oil pour œil, dent pour dent, main pour main, pied pour pied,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brûlure pour brûlure, plaie pour plaie, meurtrissure pour meurtrissure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Si un homme a porté un coup à l’œil de son serviteur ou à l’œil de sa servante, et que l’œil soit perdu, il renverra libre le blessé, pour prix de l’œil perdu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'S’il a cassé une dent à son serviteur ou une dent à sa servante, il les renverra libres, pour prix de la dent perdue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Si un taureau a frappé de sa corne un homme ou une femme et que le blessé en meure, le taureau sera lapidé et l’on ne mangera pas sa chair, mais le maître du taureau sera innocenté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Si le taureau a depuis longtemps l’habitude de frapper de la corne, qu’on l’ait déclaré à son maître sans qu’il l’ait enfermé, et que le taureau tue homme ou femme, le taureau sera lapidé et le maître mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Si une rançon lui est imposée, il pourra racheter sa vie au prix de la rançon qui lui aura été imposée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Si le taureau a frappé de sa corne un fils ou une fille, la sentence sera la même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'S’il a blessé un serviteur ou une servante, on donnera au maître trente drachmes d’argent, et le taureau sera lapidé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Si quelqu’un creuse un puits, ou bâtit une citerne en pierres de taille et qu’il n’en couvre pas l’orifice, et qu’un veau ou un âne y tombe,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Le maître du puits ou de la citerne sera puni, il donnera de l’argent à leur maître, mais la bête morte sera pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Si le taureau d’un homme frappe à mort le taureau de son voisin, ils vendront le taureau vivant, ils en partageront le prix, et ils partageront le taureau mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'S’il est reconnu que le taureau avait depuis longtemps l’habitude de frapper de la corne, et qu’on l’avait déclaré au maître sans qu’il l’eût enfermé, celui-ci rendra taureau pour taureau, et la bête morte sera pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Si un homme vole un veau ou une brebis, et qu’il l’égorge ou le vende, il rendra cinq veaux pour le veau, et quatre brebis pour la brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si le voleur a été trouvé perçant le mur, et que blessé, il meure; il n’y a point de meurtre à son sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Si le soleil était levé, celui qui a frappé le voleur est coupable qu’on le mette à mort; si le voleur n’a rien, qu’on le vende pour prix de l’objet volé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si la bête volée vit encore et est trouvée dans ses mains, depuis l’âne jusqu’à la brebis, il en rendra le double.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Si quelqu’un cause du dommage dans un champ ou une vigne, et s’il laisse son bétail paître dans le champ d’autrui, il indemnisera de son propre champ, selon ses produits. Si tout le champ d’autrui a été dévoré, il indemnisera du meilleur de son champ et du meilleur de sa vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Si un feu rencontrant des épines gagne de proche en proche et brûle des meules ou des épis, ou la récolte d’un champ, celui qui aura allumé le feu paiera la perte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Si un homme donne à son voisin de l’argent ou un objet à garder, et que le dépôt soit volé en la maison du dépositaire, si le voleur est découvert il rendra le double;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Mais si le voleur n’est pas trouvé, le dépositaire ira devant Dieu et jurera qu’il n’a point agi méchamment au sujet du dépôt,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Ni du délit déclaré; que l’on ait pris veau, ou âne, ou brebis, ou vêtement, ou quoi que ce soit, un jugement sera rendu devant Dieu entre le plaignant et le dépositaire, et celui qui sera découvert par le Seigneur restituera le double.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Si un homme donne à garder à son voisin âne ou veau, brebis ou autre bête, et que la bête soit malade ou morte, ou prise de vive force par l’ennemi sans que personne le sache,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Il y aura, entre les deux hommes, serment devant Dieu; le dépositaire jurera qu’il n’a pas agi méchamment au sujet du dépôt; le voisin ainsi l’agréera, et il n’y aura point d’indemnité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Mais si la bête a été dérobée chez lui, il indemnisera le maître de la bête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Si elle a été prise par une bête fauve, il le conduira sur ses traces, et ne devra rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Si un homme a emprunté à son voisin une bête qui tombe malade, qui meure ou qui soit prise de vive force par l’ennemi, et cela en l’absence du maître, il paiera l’indemnité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Mais si le maître était avec la bête, l’emprunteur ne paiera rien; si c’était un homme à gages, il perdra son salaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Si un homme trompe une vierge qui n’est point encore fiancée, et s’il dort avec elle, il lui donneră une dot et l’épousera;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Mais s’il s’y refuse ou si le père de la vierge ne veut pas qu’il l’ait pour femme, il lui donnera autant d’argent qu’on en donne pour doter les vierges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Vous ne souffrirez point les magiciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Celui qui se sera accouplé à une bête, punissez-le de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Celui qui sacrifiera à des dieux autres que le Seigneur sera exterminé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Vous ne maltraiterez pas l’étranger et vous ne l’opprimerez point; car vous étiez étranger en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Vous ne maltraiterez jamais la veuve ni l’orphelin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Si vous les maltraitez, s’ils crient vers moi, j’entendrai leurs cris;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Et je serai courroucé en mon cœur, et je vous ferai périr par l’épée; vos femmes deviendront veuves, et vos enfants orphelins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si chez toi tu prêtes de l’argent à ton frère pauvre, tu ne le presseras pas, et tu ne lui demanderas point d’intérêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si tu as pris en nantissement le manteau de ton voisin, tu le lui rendras avant le coucher du soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Car c’est son vêtement unique, l’unique voile de sa nudité avec quoi dormirait-il? Si donc il crie vers moi, je l’écouterai, parce que je suis miséricordieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Tu ne maudiras point les dieux, tu n’injurieras point le prince de ton peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Tu ne différeras point l’offrande des prémices de tes aires et de tes pressoirs; tu me donneras les premiers-nés de tes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Tu me donneras aussi le premier-né de ta génisse, de ta brebis, de ton ânesse; tu le laisseras sept jours sous sa mère; le huitième jour tu me le donneras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Vous serez des hommes saints devant moi, et vous ne mangerez point de chair enlevée par les bêtes fauves; vous la jetterez aux chiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Tu n’accueilleras point un vain bruit; tu ne t’entendras point avec l’injuste pour porter un injuste témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Tu ne seras pas avec le plus grand nombre pour le mal, et tu ne te joindras pas à la multitude pour dévier avec le plus grand nombre et exclure la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Tu n’auras pas de pitié même en faveur du pauvre dans les jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Si tu rencontres égaré le bœuf ou l’âne de ton ennemi, ramène-le et rends-le-lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si tu vois, tombé sous sa charge, l’âne de ton ennemi, tu ne passeras pas outre, mais tu aideras ton ennemi à le relever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Garde-toi de faire dévier la justice, quand tu jugeras le pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Abstiens-toi de toute sentence inique; ne fais périr ni l’innocent, ni le juste; n’absous pas l’impie pour des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'N’accepte point de présents: les présents aveuglent les yeux de ceux qui voient; ils pervertissent les paroles de justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'N’opprimez pas l’étranger; car vous savez ce qu’est la vie de l’étranger; vous avez été vous-mêmes étrangers en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Tu ensemenceras ta terre six ans, et tu recueilleras ses produits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mais la septième année, tu feras rémission et tu la laisseras reposer, et les pauvres de ta maison mangeront ses fruits; et ce qui en restera, les bêtes sauvages le mangeront. Tu en useras de même à l’égard de ta vigne et de ton plant d’oliviers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Pendant six jours, tu feras des travaux; mais le septième jour repos, afin que, ton bœuf et ton âne se reposent, afin que le fils de ta servante et le mercenaire étranger respirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Observez tout ce que je vous ai dit; ne gardez point le souvenir du nom des dieux étrangers, qu’on ne l’entende jamais sortir de votre bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Fêtez-moi à trois époques de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Ayez soin de faire la fête des azymes; pendant sept jours vous mangerez des azymes, selon ce que je vous ai prescrit, au moment opportun du mois des nouveaux blés; car c’est en ce mois que tu es sorti d’Égypte; tu ne paraîtras point devant moi les mains vides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Fais aussi la fête de la moisson, des prémices de tes travaux, quel que soit le grain que tu aies semé en ton champ; puis, la fête de fin d’année, quand tu auras recueilli tous les fruits de tes champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'À trois époques de l’année, tout mâle chez toi comparaîtra devant ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Lorsque j’aurai chassé les nations devant toi, lorsque j’aurai dilaté tes limites, tu ne verseras pas sur des pains levés le sang des sacrifices; tu ne garderas pas jusqu’au lendemain la graisse de ma fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Tu feras offrande à la maison du Seigneur ton Dieu des prémices de ton champ; tu ne feras point cuire d’agneau dans le lait de sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Voilà que j’envoie devant toi mon ange, afin qu’il te protége dans la voie, et qu’il t’introduise en la terre que je t’ai préparée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Fais attention à toi, écoute-le, et ne lui désobéis point; car il ne te cédera pas, puisque mon nom est avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Si vous prêtez à ma voix une oreille attentive, si vous faites tout ce que je vous prescris, et si vous maintenez mon alliance, vous serez mon peuple à part parmi toutes les nations; car toute la terre est à moi, mais vous serez pour moi un sacerdoce royal et une nation sainte. Dis toutes ces paroles aux fils d’Israël: Si vous prêtez l’oreille à ma voix, si vous faites ce que je prescris, je haïrai ceux qui vous haïssent, je serai l’ennemi de vos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Car mon ange marchera pour te guider, et il t’introduira chez l’Amorrhéen, l’Hettéen, le Phérézéen, le Chananéen, le Gergéséen, l’Evéen, le Jébuséen; et je les détruirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Tu n’adoreras pas leurs dieux, et tu ne feras pas à ces dieux de sacrifices; tu n’imiteras pas ces peuples en leurs œuvres; mais tu les extermineras, tu briseras leurs colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Et tu sacrifieras au Seigneur ton Dieu; alors, je bénirai ton pain et ton vin et ton eau, et je détournerai de vous les maladies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Il n’y aura point sur votre terre d’homme sans enfants, de femme stérile; je multiplierai le nombre de vos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'J’enverrai devant toi l’épouvante; je frapperai de stupeur les nations chez qui tu entreras, je mettrai en fuite tous les ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'J’enverrai devant toi des essaims de guêpes, et tu chasseras loin de toi les Amorrhéens, et les Evéens, et les Chananéens, et les Hettéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Je ne les expulserai pas en une année, de peur que la terre promise ne devienne un désert, et que les bêtes fauves des champs ne pullulent pour te nuire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Je les chasserai devant toi peu à peu, jusqu’à ce que tu aies multiplié et que tu partages la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Et je poserai tes limites de la mer Rouge à la mer des Philistins, et du désert au grand fleuve Euphrate. Je livrerai à tes mains ceux qui sont établis en la terre, et je les chasserai loin de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Tu ne feras point alliance avec ces peuples ni avec leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Et ils ne demeureront point dans ta terre, de peur qu’ils ne te fassent pécher contre moi; car si tu sers leurs dieux, ils seront pour toi un sujet de chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Le Seigneur dit encore à Moïse: Monte vers le Seigneur avec Aaron, Nadab, Abiud et soixante-dix des anciens d’Israël; qu’ils adorent de loin le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Moïse seul viendra près du Seigneur; les autres n’approcheront pas de lui, et le peuple ne montera pas');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Moïse descendit donc; il rapporta au peuple toutes les paroles et les ordonnances de Dieu; et le peuple répondit tout d’une voix, et il dit: Nous exécuterons tout ce que t’a dit le Seigneur; nous obéirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Moïse écrivit ensuite toutes les paroles du Seigneur, et, s’étant levé de grand matin, il éleva un autel au pied de la montagne, plus douze pierres pour les douze tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Puis, il envoya les jeunes gens des fils d’Israël, et ils amenèrent des holocaustes, et ils sacrifièrent à Dieu de jeunes veaux, comme hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Moïse, ayant pris la moitié du sang, la versa en des urnes, et il répandit l’autre moitié devant l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Et prenant le livre de l’alliance, il le lut au peuple, qui répondit: Nous ferons tout ce qu’a dit le Seigneur; nous obéirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Et Moïse, ayant pris le sang des urnes, aspergea le peuple, et il dit: Voici le sang de l’alliance que le Seigneur a cimentée avec vous au sujet de toutes ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Après cela, Moïse monta avec Aaron, Nadab, Abiud et soixante-dix des anciens d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Et ils virent le lieu où se tenait le Dieu d’Israël; ils virent sous ses pieds comme un ouvrage en pierres de saphir, comme une image du firmament du ciel dans sa pureté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Cependant, aucun des élus d’Israël n’expira; ils se présentèrent au lieu où était le Seigneur, et ils mangèrent, et ils burent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Le Seigneur alors dit à Moïse: Monte jusqu’à moi sur la montagne, et je te donnerai les tables de pierre, la loi et les commandements que j’ai écrits pour les gouverner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Et Moïse s’étant levé avec Josué, ils montèrent sur la cime de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Ils avaient dit aux anciens: Ne bougez d’où vous êtes jusqu’à ce que nous revenions vers vous; voici avec vous Aaron et Hur: si quelqu’un a une cause à juger, qu’il aille devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Moïse donc avec Josué monta sur la montagne, et une nuée enveloppa la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'La gloire de Dieu descendit sur le mont Sina, pendant six jours la nuée enveloppa la montagne, et le septième jour, Dieu, du milieu de la nuée, appela Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Et la gloire de Dieu apparaissait sur la cime du mont comme un feu flamboyant, aux yeux des enfants d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Moïse entra au milieu de la nuée, il monta sur la cime, et il y resta quarante jours et quarante nuits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Parle aux fils d’Israël, prends des prémices de toutes choses, au gré de leur cœur, recueillez pour moi ces prémices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Voici les prémices que vous prendrez d’eux: de l’or, de l’argent, de l’airain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'De l’hyacinthe, de la pourpre, de l’écarlate double, du fil de lin, des poils de chèvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Des peaux de béliers teintes en rouge, des peaux bleues, des bois incorruptibles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'De l’huile à éclairer, des parfums pour l’huile de l’onction et pour la composition de l’encens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Des cornalines, des pierres à graver pour l’éphod et pour la longue robe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Et tu me feras un sanctuaire, et j’apparaîtrai parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Tu feras ce lieu et ses ornements conformément au modèle du tabernacle que je te montre sur la montagne, conformément au modèle des ornements; voici comment tu les feras:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Tu feras, pour moi, l’arche du témoignage en bois incorruptibles longue de deux coudées et demie, large d’une coudée et demie, haute d’une coudée et demie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Et tu la revêtiras d’or pur; tu la revêtiras d’or en dehors et au dedans, et elle aura des cymaises d’or, tournées en cercle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Tu fabriqueras pour elle quatre anneaux d’or, que tu poseras sur les quatre côtés: deux anneaux sur le côté antérieur, deux anneaux sur le côté de derrière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Tu feras aussi des leviers de bois incorruptible, que tu revêtiras d’or pur le plus fin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Et tu les introduiras dans les anneaux des coins de l’arche, afin d’enlever l’arche par leur moyen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Les leviers demeureront toujours dans les anneaux de l’arche, et seront immuables,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Et tu mettras dans l’arche les témoignages que je te donnerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Pour couvrir l’arche, tu feras un propitiatoire d’or le plus pur, long de deux coudées et demie, large d’une coudée et demie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Et tu feras deux chérubins d’or ciselé, que tu poseras des deux côtés du propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Les deux chérubins seront, l’un, sur un côté du propitiatoire; l’autre, sur l’autre côté; tu feras les deux chérubins sur les deux côtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Les deux chérubins auront les ailes étendues en haut, ils ombrageront de leurs ailes le propitiatoire, le visage tourné l’un vers l’autre; vers le propitiatoire, sera tourné le visage des chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Et tu placeras le propitiatoire au haut de l’arche, et, dans l’arche, tu mettras les témoignages que je te donnerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'De cette arche, je me manifesterai à toi, je te parlerai du haut du propitiatoire, entre les deux chérubins qui seront sur l’arche du témoignage, et je te donnerai tous mes ordres pour les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Tu feras aussi, en la revêtant d’or pur, une table de deux coudées, large d’une coudée, haute d’une coudée et demie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Et tu feras, tout autour d’elle, des cymaises d’or; et elle aura une couronne d’une palme de largeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Et tu mettras à la couronne une cymaise tordue tout autour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Tu feras quatre anneaux d’or, et tu poseras les quatre anneaux au-dessous de la couronne, aux quatre coins où seront les pieds de la table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Ces anneaux seront pour recevoir les leviers, afin par leur moyen d’enlever la table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Tu feras ces leviers en bois incorruptible, tu les revêtiras d’or pur, et par leur moyen on enlèvera la table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Tu feras pour elle les plats, et les encensoirs, et les urnes à puiser des libations, et les coupes pour les répandre; tu les feras en or pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Et tu placeras sur la table les pains de proposition, pour être sans cesse devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Et tu feras un chandelier d’or pur, il sera ciselé; sa tige, ses branches, ses coupes, ses pommes et ses lis, seront tout d’une pièce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Six branches sortiront des côtés: trois d’un côté, trois de l’autre côté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Et tu feras, pour chaque branche, trois coupes façonnées comme des noix; et, sur chaque branche, une pomme et un lis; telles seront les six branches sortant du chandelier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Et tu feras, sur le chandelier, quatre coupes façonnées comme des noix, et ses pommes et ses lis seront avec les branches;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Il y aura une pomme sous deux branches du chandelier, et une pomme sous quatre branches du chandelier; il en sortira donc six branches. Et il y aura, sur le chandelier, quatre coupes façonnées comme des noix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Que les pommes et les branches soient tout d’une pièce, et que l’ensemble soit d’une seule pièce d’or ciselé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Et tu feras, pour le chandelier, sept lampes, et tu les poseras par-dessus, et elles brilleront sur une seule rangée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Et tu feras, en or pur, ses mouchettes et ses récipients.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Tous ces appareils pèseront un talent d’or pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Examine, et fais selon le type qui t’est montré sur la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Et tu feras le tabernacle avec dix courtines de fin lin retors, d’hyacinthe, de pourpre, d’écarlate retors, ouvrage varié, œuvre du tisserand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Chaque courtine aura vingt-huit coudées de long, sur quatre de large; de même mesure seront toutes les courtines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinq courtines seront ajustées l’une tenant à l’autre, et les cinq autres courtines seront attachées l’une à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Tu feras des attaches d’hyacinthe sur la lisière de l’une des courtines, pour la nouer à la suivante; tu feras de même sur la lisière de la courtine opposée, pour la nouer à la première.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Tu feras cinquante attaches à chaque courtine, et tu feras cinquante attaches à la suivante, pour les réunir l’une à l’autre, les attaches se correspondant face à face exactement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Tu feras cinquante anneaux d’or, et tu joindras les courtines l’une à l’autre à l’aide des anneaux, et elles formeront un seul tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Tu feras aussi des couvertures en peaux velues pour abriter et envelopper le tabernacle; et tu en feras onze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Elles auront trente coudées de long, sur quatre de large; de même mesure seront toutes les couvertures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Tu joindras cinq couvertures, et tu joindras les six autres couvertures, et tu replieras en deux la moitié de la sixième sur le devant du tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Tu feras cinquante attaches sur la lisière de chaque couverture, pour les réunir ensemble; et tu feras cinquante attaches sur la lisière de la couverture suivante, pour l’adapter à la première.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Tu feras cinquante anneaux d’airain, au moyen desquels tu réuniras les attaches, et tu joindras ainsi les couvertures qui n’en formeront plus qu’une seule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Et tu fixeras par le bas et par les deux extrémités l’excédant de longueur des couvertures du tabernacle; la moitié de couverture qui restera, tu la replieras, car il y aura excédant de couvertures du tabernacle, et tu en envelopperas le derrière du tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Tu replieras l’excédant de longueur des couvertures du tabernacle, une coudée d’un côté et une coudée de l’autre, de telle sorte qu’il soit couvert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Tu feras, pour le tabernacle, une toiture double, le dessous en toisons de béliers teintes en rouge; et pardessus une couverture de peaux de béliers teintes en bleu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Et tu feras les colonnes du tabernacle en bois incorruptible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Chaque colonne aura dix coudées de haut, sur une coudée et demie d’épaisseur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Il y aura à chaque colonne deux jointures correspondant l’une à l’autre; et il y en aura à toutes les colonnes du tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Il y aura vingt colonnes du côté du nord;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Puis, tu feras quarante bases d’argent pour les vingt colonnes; une colonne aura une base pour chacune de ses extrémités; une autre colonne une base pour chacune de ses extrémités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Et le second côté, celui du midi, aura vingt colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Elles auront quarante ornements d’argent; une colonne aura un ornement pour chacune de ses extrémités; une autre colonne un ornement pour chacune de ses extrémités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Et derrière le tabernacle, du côté de la mer (à l’occident), il y aura six colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Tu feras aussi deux colonnes sur les angles du tabernacle, derrière le tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Elles seront semblables par la base, et semblables par les chapiteaux qui seront réunis. Ainsi tu feras pour les deux angles qui seront semblables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Il y aura huit colonnes et seize bases d’argent; à chaque colonne une base, pour chacune de ses extrémités, et à une autre colonne une base, pour chacune de ses extrémités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Et tu feras des barres de bois incorruptible: cinq pour chaque colonne de l’un des côtés du tabernacle;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Cinq barres par colonne de l’autre côté du tabernacle, et cinq barres par colonne des angles de derrière du tabernacle, du côté de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'La barre du milieu, entre deux colonnes, ira de l’une à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Tu revêtiras d’or fin toutes les colonnes; et tu feras en or les anneaux dans lesquels tu engageras les barres, et tu revêtiras les barres d’or pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Tu dresseras ainsi le tabernacle, selon le modèle qui t’en a été montré sur la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Tu feras aussi un voile d’hyacinthe, de pourpre, d’écarlate filé, et de lin filé, et il sera tissu: œuvre variée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Et tu le placeras sur quatre colonnes incorruptibles, revêtues d’or pur, qui auront des chapiteaux d’or et quatre bases d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Tu poseras le voile sur les colonnes, et tu introduiras, à l’intérieur du voile, l’arche du témoignage, et le voile séparera pour vous le saint du Saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Avec ce voile, tu cacheras l’arche du témoignage dans le Saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Et tu placeras la table devant le voile, et le chandelier vis-à-vis la table, du côté du tabernacle qui regardera le midi; et la table sera au nord.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Tu feras en outre, à la porte du tabernacle, un voile d’hyacinthe, de pourpre, d’écarlate filé, et de lin filé; œuvre du brodeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Et tu feras, pour le voile, cinq colonnes que tu revêtiras d’or pur, et leurs chapiteaux seront d’or, et les cinq bases seront d’airain jeté en fonte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Tu feras ensuite un autel de bois incorruptible, long de cinq coudées, large de cinq coudées; il aura quatre faces, et trois coudées de haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Tu feras des cornes aux quatre angles du haut; les cornes seront en saillie, et revêtues d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Tu feras une couronne à l’autel; et tu feras en airain sa table, et ses burettes, et ses réchauds, et ses crochets, et tous ses ustensiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Tu feras aussi, pour l’autel, une grille d’airain à mailles; et tu feras, pour les quatre angles, quatre anneaux d’airain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Que tu mettras au-dessous de la grille de l’autel; et la grille s’étendra jusqu’au milieu de celui-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Tu feras pour l’autel des leviers de bois incorruptible, que tu revêtiras d’airain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Et que tu introduiras dans les anneaux, le long des côtés de l’autel, pour l’enlever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tu feras l’autel creux et en panneaux, selon le modèle qui t’a été montré sur la montagne; c’est ainsi que tu le feras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Tu formeras, pour le tabernacle, un parvis du côté du sud; les tentures du parvis seront de lin filé, longues de cent coudées de ce côté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Il aura vingt colonnes avec vingt bases; leurs anneaux et les agrafes seront revêtus d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'De même, du côté du nord, la tenture sera de cent coudées de long, avec vingt colonnes, et leurs vingt bases d’airain; et tu revêtiras d’argent les bases, les anneaux et les agrafes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'La largeur du parvis, du côté de la mer, sera de cinquante coudées, avec dix colonnes et dix bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'La largeur du parvis, à l’orient, sera de cinquante coudées, avec dix colonnes et dix bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Et les tentures du parvis auront, d’un côté, quinze coudées de haut, avec trois colonnes et trois bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'De l’autre côté, les tentures auront quinze coudées de haut, avec trois colonnes et trois bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'À la porte du parvis, il y aura un voile haut de vingt coudées en hyacinthe, pourpre, écarlate filé et lin filé, avec broderies à l’aiguille; il y aura quatre colonnes et quatre bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Toutes les colonnes, autour du parvis, seront revêtues d’argent; elles auront des chapiteaux d’argent, et des bases d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Le parvis aura, des deux côtés, cent coudées de long, et devant et derrière cinquante coudées de large; ses tentures auront en hauteur vingt-cinq coudées, et les colonnes auront des bases d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Et tout l’ameublement, et tous les ustensiles, et les piquets du parvis seront d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Ordonne encore aux fils d’Israël de te donner de l’huile d’olive, sans lie, pure, pilée au mortier, pour brûler et éclairer; car la lampe doit brûler toujours,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Dans le tabernacle du témoignage, devant le voile de l’alliance; Aaron et ses fils la feront brûler devant le Seigneur du soir au matin. C’est une loi perpétuelle pour toutes les générations des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Fais aussi venir vers toi Aaron, ton frère, et ses fils, pour que, parmi les fils d’Israël, Aaron, Nadab, Abiu, Eleazar et Ithamar, fils d’Aaron, soient mes prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Et tu feras des vêtements sacrés pour Aaron, frère, en signe de gloire et d’honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Parle aux sages d’intelligence, à ceux que j’ai remplis de l’esprit de sagesse; qu’ils fassent la tunique sacrée d’Aaron, avec laquelle il exercera, dans le lieu saint, mon sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Voici les vêtements qu’ils feront: le rational, l’éphod, la longue robe, la tunique garnie d’une frange, la tiare et la ceinture; ils feront les vêtements sacrés d’Aaron et de ses fils, pour qu’ils exercent mon sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Et ils emploieront l’or, l’hyacinthe, la pourpre, l’écarlate et le lin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'L’éphod sera en fin lin retors, tissu du brodeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'L’éphod sera de deux pièces jointes l’une à l’autre, et attachées sur les côtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Et le tissu des deux pièces dont il se couvrira, sera d’or pur, d’hyacinthe, de pourpre, d’écarlate filé et de lin retors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Tu prendras deux pierres fines d’émeraude, et tu y graveras les noms des fils d’Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Six noms sur l’une des deux pierres, et les six autres noms sur la seconde pierre, selon l’ordre de leur naissance:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Œuvre de l’art de travailler la pierre; tu y graveras les noms des fils d’Israël comme on grave un cachet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Et tu mettras les deux pierres sur les épaulières de l’éphod, pour servir de mémorial aux fils d’Israël. Aaron portera les noms des fils d’Israël sur ses deux épaules; c’est un mémorial pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Tu feras aussi des boucles en or pur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Et deux petites chaînes d’or pur tressé, mêlées de fleurs, et tu passeras ces chaînes tressées dans les boucles, pour qu’elles soient fixées sur l’éphod par devant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Et tu feras le rational du jugement, œuvre du brodeur, selon la mesure de l’éphod; tu le feras d’or, d’hyacinthe, de pourpre, d’écarlate filé, et de lin filé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Tu le feras carré; il sera double, long d’un palme, large d’un palme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Et tu y entrelaceras un tissu, enchâssant quatre rangées de pierres; il y aura une rangée de cornaline, de topaze et d’émeraude: première rangée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'La seconde rangée sera d’escarboucle, de saphir, de jaspe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'La troisième: de ligure, d’agate, d’améthyste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'La quatrième de chrysolithe, de béril et d’onyx; ces pierres seront montées sur or, enchâssées dans l’or. Les pierres seront ainsi rangées par ordre, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Porteront les noms des fils d’Israël: douze pierres, douze noms gravés comme on grave un cachet; chacune aura le nom d’une des douze tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Et tu feras, sur le rational, des chaînes tressées, ouvrage en mailles d’or pur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Ainsi que deux anneaux d’or, que tu mettras sur les deux coins supérieurs du rational.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Tu placeras les chaînes en mailles d’or, dans les anneaux des deux côtés du rational.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Tu les passeras dans les deux boucles des épaulières de l’éphod, par devant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Tu feras aussi deux anneaux d’or, et tu les poseras sur les deux extrémités du rational, d’une pointe à l’autre de l’éphod, par derrière et en dedans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Tu feras deux anneaux d’or, et tu les poseras sous les épaulières de l’éphod, par devant, pour qu’ils correspondent à la couture du tissu de l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Tu serreras ainsi le rational, au moyen des anneaux qui y seront fixés, et des anneaux de l’éphod, faisant saillie sur l’hyacinthe, entrelacés dans le tissu de l’éphod, afin que le rational ne se détache point de l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Et Aaron portera les noms des fils d’Israël sur le rational du jugement et sur sa poitrine lorsqu’il entrera dans le saint; c’est un mémorial devant Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Tu mettras sur le rational du jugement: Manifestation et Vérité; et le rational sera sur la poitrine d’Aaron lorsqu’il entrera dans le saint devant le Seigneur. Et Aaron portera toujours, sur sa poitrine, le jugement des fils d’Israël devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Et tu feras tout entière en hyacinthe la longue robe qui sera portée sous l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Elle aura au milieu une ouverture, et cette ouverture, ronde, sera bordée d’un collet; œuvre tissue, formant la lisière du tissu entier, pour qu’elle ne se déchire point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Et tu feras, sous la bordure de la robe au bas, en hyacinthe, pourpre, écarlate filé et lin filé, tout autour de la robe de dessous, des grenades fleuries d’où sortiront de petits boutons de grenades. Il y aura aussi de semblables boutons de grenades en or, et il y aura entre eux tout autour de petites clochettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Une clochette suivra chaque bouton de grenade qui semblera fleurir sous la bordure de la robe de dessous, tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Et lorsque Aaron, exerçant le sacerdoce, entrera dans le sanctuaire devant le Seigneur ou en sortira, le son des clochettes se fera entendre, pour qu’il ne meure pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Tu feras une plaque d’or pur, et tu y graveras, comme on grave sur un cachet:.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Tu la poseras sur de l’hyacinthe filé; et elle sera sur la tiare, par devant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Elle sera sur le front d’Aaron, et Aaron ôtera les péchés de leurs choses saintes, les manquements de toutes les choses saintes que consacreront les fils d’Israël. Et elle sera toujours sur le front d’Aaron, afin que le Seigneur leur soit favorable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Les franges qui garniront les vêtements, seront de lin, et la tiare aussi sera de lin, et la ceinture sera un ouvrage de broderie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'En outre, tu feras, pour les fils d’Aaron, des tuniques et des ceintures, et tu leur feras des mitres, en signe de gloire et d’honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Tu en vêtiras Aaron, ton frère, et après lui ses fils; puis, tu les oindras, tu consacreras leurs mains, et tu les sanctifieras, afin qu’ils remplissent les fonctions de prêtres devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Tu leur feras aussi des caleçons de lin pour cacher la nudité de leur chair; les caleçons descendront de la hanche aux genoux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Aaron et ses fils les auront lorsqu’ils entreront dans le tabernacle du témoignage, ou lorsqu’ils iront sacrifier à l’autel du saint. Ainsi, ils ne se rendront pas coupables de péché, et ils ne mourront pas; c’est une loi perpétuelle pour Aaron et pour sa race après lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Voici ce que tu leur feras: tu les sanctifieras pour qu’ils exercent mon sacerdoce. Tu prendras donc du troupeau un jeune veau, et deux béliers sans tache,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Avec des pains sans levain pétris dans l’huile, des gâteaux sans levain arrosés d’huile; tu les feras de fine fleur de farine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Et tu les poseras en une corbeille, et tu les emporteras dans la corbeille en même temps que tu emmèneras le veau et les deux béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Tu conduiras Aaron et ses fils sur la porte du tabernacle du témoignage, et tu les laveras dans l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Après quoi, tu prendras les vêtements saints, et tu en revêtiras Aaron, ton frère; tu lui mettras la tunique, la robe traînante, l’éphod et le rational; tu attacheras sur lui le rational à l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Tu lui poseras la tiare sur la tête, et tu placeras sur la tiare la lame sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Alors, tu prendras de l’huile de la consécration, et tu la verseras sur sa tête, et tu l’oindras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Tu conduiras ensuite ses fils, que tu revêtiras de leurs tuniques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Tu les ceindras de leurs ceintures, tu leur poseras les mitres sur la tête, et ils seront mes prêtres à jamais; et tu consacreras les mains d’Aaron et de ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Ensuite, tu mèneras le veau sur la porte du tabernacle du témoignage; Aaron et ses fils imposeront leurs mains sur la tête du veau devant le Seigneur, auprès de la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Et tu égorgeras le veau devant le Seigneur, vers la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Puis, tu prendras du sang du veau, et, de ton doigt, tu en mettras sur les cornes de l’autel; quant au reste du sang, tu le répandras tout entier au pied de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Tu prendras aussi la graisse qui enveloppe les entrailles, le lobe du foie, les deux rognons avec la graisse qui les couvre, et tu poseras le tout sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Et tu brûleras, hors du camp, les chairs du veau, sa peau et la fiente: car c’est pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Ensuite, tu prendras l’un des béliers: Aaron et ses fils imposeront les mains sur la tête du bélier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Tu l’égorgeras, et tu prendras de son sang que tu répandras devant l’autel, tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Puis, tu partageras par membres le bélier, et tu laveras dans l’eau les intestins ainsi que les pieds, et tu les poseras sur les membres avec la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Tu offriras le bélier tout entier sur l’autel; c’est l’holocauste du Seigneur, en odeur de suavité; c’est le parfum pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Tu prendras le second bélier; Aaron et ses fils imposeront les mains sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Et tu l’égorgeras; tu prendras de son sang, et tu en mettras sur le lobe de l’oreille droite d’Aaron, sur l’extrémité de sa main droite, sur l’extrémité de son pied droit, sur les lobes des oreilles droites de ses fils, sur les extrémités des mains droites de ses fils, et sur les extrémités des pieds droits de ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Tu prendras aussi du sang de l’autel et de l’huile de l’onction, et tu en aspergeras Aaron et ses vêtements, ainsi que ses fils et leurs vêtements; et Aaron avec ses vêtements, ses fils et leurs vêtements, seront sanctifiés; puis, tu répandras tout autour de l’autel le sang du bélier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Et tu prendras la chair du bélier, la graisse qui enveloppe les entrailles, le lobe du foie, les deux rognons avec la graisse qui les entoure et l’épaule droite: car cela est consacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Tu prendras un pain fait avec de l’huile et un gâteau de la corbeille des azymes, de ceux déposés devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Tu mettras ces choses dans les mains d’Aaron, et dans les mains de ses fils, tu les sépareras pour être consacrées au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Et après les avoir reprises de leurs mains, tu les porteras sur l’autel des holocaustes, en odeur de suavité pour le Seigneur; c’est l’oblation au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Tu prendras ensuite la poitrine du bélier de la consécration, lequel appartient à Aaron, et tu le mettras à part comme chose réservée au Seigneur, et ce sera ta portion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Tu sanctifieras aussi la poitrine mise à part, et l’épaule qui a été enlevée et mise à part du bélier de la consécration, par Aaron et ses fils;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Ce sera une loi perpétuelle des fils d’Israël pour Aaron et ses fils; cette part est, en effet, réservée; c’est une offrande des fils d’Israël, parmi les hosties pacifiques offertes par eux au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'La tunique du sanctuaire qui appartient à Aaron sera à ses fils après lui; c’est avec ces vêtements qu’ils seront oints et que leurs mains seront consacrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Pendant sept jours, le prêtre qui lui succédera parmi ses fils, pour entrer dans le tabernacle du témoignage et servir dans les choses saintes, en sera revêtu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Tu prendras le bélier de la consécration, et tu feras cuire ses chairs en lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Et Aaron et ses fils mangeront les chairs du bélier, avec les pains de la corbeille, non loin de la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Ils mangeront ces choses par lesquelles eux auront été sanctifiés, et leurs mains consacrées lors de leur consécration; nul étranger n’en mangera, car ce sont choses saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Et s’il reste jusqu’au lendemain des pains et des chairs de la victime de la consécration, tu les brûleras, elles ne seront point mangées, car c’est chose consacrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tu feras ainsi pour Aaron et ses fils tout ce que je t’ai commandé; pendant sept jours tu consacreras leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Et le veau expiatoire des péchés, tu l’offriras le jour de la purification; tu purifieras l’autel en faisant sur lui ces saintes offrandes; et tu l’oindras pour le sanctifier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Pendant sept jours, tu purifieras l’autel, tu le sanctifieras; et l’autel sera très — saint; quiconque touchera l’autel sera sanctifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Voici ce que tu feras sur l’autel: tu y sacrifieras chaque jour deux agneaux d’un an sans tache, en oblation perpétuelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Tu sacrifieras l’un des deux agneaux le matin, et tu sacrifieras le second agneau sur le soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Et tu offriras par agneau un dixième de mesure de fleur de farine pétrie dans le quart d’un hin d’huile faite au mortier, avec une libation d’un quart de hin de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Tu sacrifieras le second agneau sur le soir, et le sacrifice se fera de même que celui du matin, avec la même libation; tu l’offriras en odeur de suavité; c’est le sacrifice au Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Sacrifice perpétuel dans votre race, devant la porte du tabernacle du témoignage, là où je me manifesterai à toi en te parlant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Là où je donnerai mes ordres aux fils d’Israël, et où je serai sanctifié en ma gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Je sanctifierai le tabernacle du témoignage, ainsi que l’autel, je sanctifierai Aaron ainsi que ses fils, pour qu’ils exercent mon sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Et je serai invoqué par les fils d’Israël, et je serai leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Et ils connaîtront que je suis le Seigneur leur Dieu qui les ai tirés de la terre d’Égypte, pour être par eux invoqué, pour être leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Tu feras l’autel de l’encens en bois incorruptible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Tu lui donneras une coudée de long sur une coudée de large; il sera quadrangulaire et haut de deux coudées; il aura des cornes en saillie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Tu revêtiras d’or pur sa grille et ses panneaux tout autour, et ses cornes, et tu lui feras tout autour une couronne d’or en torsade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Et sous sa couronne en torsade tu feras deux anneaux d’or pur, un dé chaque côté; ils serviront d’anses aux leviers pour l’enlever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Ceux-ci seront de bois incorruptible, et tu les revêtiras d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Tu placeras l’autel devant le voile qui couvre l’arche du témoignage, où je me manifesterai à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Et tous les matins, sur cet autel, Aaron fera brûler le parfum composé et précieux; pendant qu’il nettoiera les lampes, il brûlera de l’encens sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Le soir aussi, lorsque Aaron allumera les lampes, il brûlera de l’encens sur l’autel; l’encens fumera toujours, toujours devant le Seigneur jusqu’à vos dernières générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Tu n’apporteras point d’autre parfum sur l’autel; tu n’y déposeras ni fruit, ni offrande; tu n’y répandras pas de libations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Une fois par an Aaron priera sur l’autel et les cornes de l’autel pour apaiser Dieu; il purifiera l’autel avec le sang de la purification, jusqu’à vos dernières générations; car il est très-saint pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Le Seigneur parla encore à Moïse, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Si tu fais le dénombrement des fils d’Israël, en les inspectant, chacun donnera au Seigneur la rançon de sa vie, et il n’y aura point chez eux de désastre pendant qu’ils seront inspectés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Et voici ce qu’ils donneront, à mesure qu’ils se présenteront devant toi pour être visités, une drachme conforme à la double drachme consacrée ayant vingt oboles; cette drachme offerte par eux sera pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Quiconque passera à la visite, âgé de vingt-trois ans et au-dessus, fera cette offrande au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Le riche n’ajoutera rien, le pauvre ne retranchera rien à cette drachme donnée en offrande au Seigneur pour le rendre propice à vos âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Tu prendras l’argent de l’offrande des fils d’Israël, et tu l’emploieras à l’œuvre du tabernacle du témoignage, afin que le Seigneur se souvienne d’eux et soit propice aux âmes des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Le Seigneur continua de parler à Moïse, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Fais un réservoir d’airain à base d’airain, pour qu’on s’y lave; tu le placeras entre le tabernacle du témoignage et l’autel, à l’entrée du tabernacle du témoignage, et tu y verseras de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Et Aaron et ses fils avec cette eau se laveront les pieds et les mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Ils se laveront avec de l’eau, avant d’entrer dans le tabernacle du témoignage, afin de ne point mourir lorsqu’ils s’approcheront de l’autel, pour exercer le sacerdoce et offrir les holocaustes au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Ils se laveront avec de l’eau les pieds et les mains, avant d’entrer dans le tabernacle du témoignage; ils se laveront avec de l’eau, afin qu’ils ne meurent pas loi perpétuelle pour Aaron et ses générations après lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Le Seigneur parla encore à Moïse, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Prends des parfums, de la fleur de myrrhe choisie, prends-en cinq cents sicles; prends deux cent cinquante sicles de cinnamome odoriférant; prends autant de canne aromatique,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Avec cinq cents sicles d’iris, au poids du sicle consacré, et un hin d’huile d’olive,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Et fais-en de l’huile parfumée, un chrême saint, le baume par excellence, produit de l’art du parfumeur; ce sera une huile sainte pour les onctions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Et tu en oindras le tabernacle du témoignage, l’arche du tabernacle du témoignage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Avec tout son ameublement, et le chandelier, et tous ses ustensiles, et l’autel de l’encens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'L’autel des holocaustes, la table avec tous ses ustensiles et le lavoir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Tu les sanctifieras, et ces choses seront saintes: quiconque les touchera sera sanctifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Tu oindras aussi Aaron et ses fils, et tu les sanctifieras, pour qu’ils exercent mon sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Tu parleras ensuite aux fils d’Israël, et tu leur diras Cette huile parfumée, chrême de l’onction, sera sainte pour vous et pour vos générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Nulle chair n’en sera ointe; on n’en fera point de pareille; c’est chose sainte, elle sera sacrée pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Celui qui en fera de pareille, celui qui en donnera à un étranger, sera exterminé parmi le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Et le Seigneur dit à Moïse: Prends en égale quantité de l’huile de myrrhe, de l’onyx, du galbanum odoriférant, et de l’encens diaphane.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Et l’on en composera un encens odoriférant, produit de l’art du parfumeur, œuvre pure et sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Tu le couperas en petites parcelles, et tu en brûleras devant les témoignages, dans le tabernacle du témoignage, d’où je me manifesterai à toi; cet encens sera pour vous très-saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Et vous n’en ferez point de pareil pour vous-mêmes; il sera par vous consacré au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Celui qui en fera de pareil pour jouir de son parfum, périra parmi le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Le Seigneur parla ensuite à Moïse, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'J’ai appelé par son nom: Beseléel, fils d’Urias, fils d’Ur, de la tribu de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Et je l’ai rempli d’un divin esprit de sagesse, d’intelligence et de science pour concevoir et diriger toutes sortes de travaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Pour construire et pour travailler l’or, l’argent, l’airain, l’hyacinthe, la pourpre et l’écarlate filé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Pour tailler la pierre, et mettre en œuvre le bois, et accomplir toute sorte d’ouvrages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Je l’ai constitué lui et Oliab, fils d’Achisamach, de la tribu de Dan; et j’ai donné, à tout cœur intelligent, la science, et ils s’appliqueront à exécuter tout ce que je t’ai prescrit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Le tabernacle du témoignage, l’arche de l’alliance, le propitiatoire dont elle sera couverte, l’ameublement du tabernacle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Et les autels, la table avec tous ses ustensiles, le chandelier d’or très-pur avec tous les siens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Le réservoir et sa base,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Les vêtements sacerdotaux d’Aaron et ceux de ses fils, pour exercer mon sacerdoce,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'L’huile de l’onction, et l’encens composé pour le sanctuaire; ils les feront selon ce que je t’ai prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Le Seigneur parla encore à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Donne mes ordres aux fils d’Israël, et dis-leur: Observez mon sabbat; c’est un signe qui vient de moi, pour vous et pour vos générations, afin que vous connaissiez que je suis le Seigneur et que c’est moi qui vous sanctifie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Observez le sabbat, parce qu’il est consacré au Seigneur; celui qui le profanera mourra de mort: toute âme qui fera œuvre en ce jour-là sera exterminée parmi le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Tu travailleras six jours; le septième, sabbat, repos consacré au Seigneur: quiconque fera œuvre le septième jour mourra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Dans toutes les générations, et les fils d’Israël observeront le sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'C’est un testament éternel entre moi et les enfants d’Israël, c’est un signe éternel en moi, parce qu’en six jours le Seigneur a fait le ciel et la terre, et que le septième jour il s’est reposé et a cessé de créer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Lorsque le Seigneur eut fini de parler à Moïse sur le mont Sina, il lui donna les deux tables du témoignage, tables de pierre gravées par le doigt de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Cependant, le peuple, voyant que Moïse tardait à descendre de la montagne, se rassembla autour d’Aaron, et il dit: Lève-toi et fais-nous des dieux qui marchent devant nous; car pour Moïse, cet homme qui nous a tirés de la terre d’Égypte, nous ne savons pas ce qui lui est arrivé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Aaron leur dit: Ôtez les boucles d’or des oreilles de vos femmes et de vos filles, et apportez-les-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Et ils ôtèrent les boucles d’or des oreilles de leurs femmes et de leurs filles, et ils les apportèrent à Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Les ayant reçues de leurs mains, il les façonna selon un modèle, et il en fit un veau jeté en fonte, et il dit: Voici tes dieux, Israël, ceux qui t’ont fait sortir de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Et Aaron voyant le peuple, érigea devant lui un autel, et il cria à haute voix: C’est demain la fête du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Et s’étant levé de grand matin, il fit venir les holocaustes et il apporta les hosties pacifiques; cependant, le peuple s’assit pour boire et manger, puis il se leva pour jouer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Le Seigneur parla alors à Moïse, et lui dit: Pars au plus vite; descends d’ici, car il a prévariqué, ton peuple, ce peuple que tu as tiré de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Ils sont bien vite sortis de la voie que je leur avais prescrite; ils se sont fait un veau d’or, ils l’ont adoré, ils lui ont sacrifié, et ils ont dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Voici tes dieux, Israël, ceux qui t’ont fait sortir de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Laisse-moi donc, que dans mon courroux contre eux je les écrase, et je te placerai ensuite à la tête d’un grand peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Et Moïse pria devant la face du Seigneur Dieu, et il dit Pourquoi, Seigneur, êtes-vous plein de colère contre votre peuple, contre ce peuple que vous avez tiré de la terre d’Égypte, par votre grande puissance et votre bras très-haut?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Que les Égyptiens ne puissent pas dire: C’est par méchanceté qu’il les a fait sortir, pour les faire périr dans les montagnes et disparaître de la terre; apaisez le courroux de votre cœur, soyez miséricordieux envers la perversité de votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Souvenez-vous de vos serviteurs Abraham, Isaac et Jacob, à qui de vous-même vous avez juré, disant: Je multiplierai votre race comme les étoiles du ciel; et ajoutant que vous leur donneriez toute cette terre, et qu’ils la posséderaient à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Et le Seigneur s’apaisa et conserva son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Et s’étant retourné, Moïse descendit de la montagne, tenant en ses mains les deux tables du témoignage, tables de pierre gravées en deux colonnes à droite et à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Ces tables étaient l’œuvre de Dieu, les caractères de Dieu y étaient gravés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Alors, entendant la voix du peuple, Josué dit à Moïse Des cris de guerre viennent du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Et Moïse dit: Non, ce n’est pas la voix qui excite le courage, ni la voix qui crie la fuite, mais une voix chantant le vin, que j’entends.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Arrivé près du camp, lorsqu’il vit le veau d’or et les danses, il se courrouça en son cœur, il rejeta de ses mains les deux tables, et les brisa au pied de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Puis, prenant le veau qu’ils avaient fait, il le consuma dans les flammes, il le réduisit en poudre, mit dans de l’eau cette poudre et la fit boire aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Et Moïse dit à Aaron: Que t’a fait ce peuple pour que tu aies fait tomber sur lui cet énorme péché?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron répondit: Ne t’irrite pas, seigneur; tu connais la violence de ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Ils m’ont dit: Fais-nous des dieux qui marchent devant nous; car pour Moïse, cet homme qui nous a amenés de la terre d’Égypte, nous ne savons pas ce qui lui est arrivé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Et je leur ai dit: Si quelqu’un de vous a de l’or, qu’il en dispose. Et ils m’en ont donné, et je l’ai jeté en fonte, et ce veau en est sorti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Moïse ayant vu que le peuple était brisé; car Aaron l’avait brisé, grand sujet de joie pour ses ennemis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Moïse se tint debout sur la porte du camp, et dit: Qui de vous est pour le Seigneur? qu’il vienne à moi. Et tous les fils de Lévi se réunirent autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Et il leur dit: Voici ce que dit le Seigneur Dieu d’Israël: Ceignez chacun votre glaive, traversez le camp, allez d’une porte à l’autre, et que chacun tue son frère, son voisin, son proche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Et les fils de Lévi firent ce que leur avait commandé Moïse, et en ce jour-là trois mille hommes du peuple périrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Et Moïse leur dit: Chacun de vous aujourd’hui a consacré ses mains au Seigneur avec son fils ou son frère, pour attirer sur vous la bénédiction du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Le lendemain Moïse dit au peuple Vous avez commis un énorme péché; je vais maintenant monter vers Dieu, afin d’implorer son pardon pour votre crime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Moïse retourna donc vers le Seigneur, et il dit: Je vous implore, Seigneur, ce peuple a commis un énorme péché ils se sont fait des dieux d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Mais maintenant, si vous le voulez, remettez-leur ce péché; sinon effacez-moi de votre livre que vous avez écrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Le Seigneur répondit à Moïse: Si quelqu’un pèche contre moi, c’est lui que j’effacerai de mon livre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Va, descends et guide ce peuple jusqu’au lieu que je t’ai dit; mon ange marchera devant ta face, et au jour où je les visiterai je ferai retomber sur eux leur péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Et le Seigneur frappa le peuple, à cause du veau d’or qu’avait fait Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Le Seigneur dit alors à Moïse: Pars, quitte ce lieu, toi et ton peuple que tu as tiré de la terre d’Égypte; væ jusqu’à la terre que j’ai promise à Abraham, à Isaac, à Jacob, quand je leur ai dit: Je la donnerai à votre race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'J’enverrai mon ange devant ta face, et il chassera l’Amorrhéen, l’Hettéen, le Phérézéen, le Gergéséen, l’Évéen, le Jébuséen et le Chananéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Je t’introduirai dans la terre où coulent le lait et le miel, mais je ne marcherai point avec toi; parce que tu as un peuple revêche et que je craindrais de te faire périr sur la route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Le peuple, ayant ouï cette parole menaçante, pleura amèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Et le Seigneur dit aux fils d’Israël: Vous êtes un peuple revêche, prenez garde que je ne fasse tomber sur vous une nouvelle plaie et que je ne vous extermine; quittez donc vos vêtements de gloire et votre parure, et je vous montrerai ce que je veux faire pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Les fils d’Israël ôtèrent leurs robes ainsi que leurs parures, en s’éloignant du mont Horeb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Moïse prit à part son tabernacle, et il le dressa hors du camp, à une grande distance, et il fut nommé tabernacle du témoignage; et quiconque cherchait le Seigneur sortait et venait auprès du tabernacle, hors du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Lorsque Moïse entrait dans le tabernacle, hors du camp, tout le peuple se tenait chacun devant la porte de sa tente les yeux fixés sur Moïse, jusqu’à ce qu’il fût entré dans le tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Or, dès que Moïse était entré dans le tabernacle, une colonne de nuée descendait et s’arrêtait vers la porte, et elle parlait à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Tout le peuple voyait la colonne de nuée devant la porte du tabernacle, et tout le peuple debout adorait, chacun de la porte de sa tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Et le Seigneur parlait à Moïse face à face, comme on parle à son propre ami. Moïse revenait ensuite au camp; et son serviteur Josué, jeune homme, fils de Nau, ne sortait pas du tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Moïse dit au Seigneur: Vous m’avez dit: Conduis ce peuple, et vous ne m’avez point montré celui que vous m’enverrez pour m’accompagner, mais vous m’avez dit: Je te connais avant tous les autres, et tu as trouvé grâce devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Si donc j’ai trouvé grâce devant vous, montrez-vous à moi; que je vous voie véritablement, afin que réellement je trouve grâce devant vous, et que je sois assuré que vous avez choisi pour votre peuple cette grande nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Et le Seigneur répondit: Moi-même je marcherai devant toi et je te ferai trouver le repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Moïse reprit: Si vous-même ne marchez point avec moi, ne me faites pas partir d’ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Comment, en effet, sera-t-il manifeste que moi et le peuple avons trouvé grâce devant vous, si vous ne marchez pas avec nous? Mais si vous m’accompagnez moi et votre peuple, nous serons glorifiés aux yeux de toutes les nations qui sont sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Le Seigneur dit alors à Moïse: Je ferai ce que tu demandes; car tu as trouvé grâce devant moi, et je te connais avant tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Moïse ajouta: Montrez-vous donc vous-même à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Et le Seigneur reprit: Je passerai devant toi dans ma gloire, et je prononcerai mon nom: Le Seigneur, devant toi; j’aurai pitié de qui j’aurai pitié, et je ferai miséricorde à qui je ferai miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Et le Seigneur ajouta: Tu ne peux voir mon visage; car nul homme, en voyant mon visage, ne vivra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Et le Seigneur dit: Vois ce lieu, près de moi, tu te tiendras sur cette pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Lorsque passera ma gloire, je te mettrai dans l’enfoncement du rocher, et je t’ombragerai de ma main jusqu’à ce que j’aie passé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Puis, j’ôterai ma main, et alors tu me verras par derrière; mais mon visage ne sera pas vu par toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Le Seigneur dit encore à Moïse: Taille-toi deux tables de pierre semblables aux premières, et monte près de moi sur la montage; je graverai sur ces tables les paroles qui étaient sur les premières, que tu as brisées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Sois prêt dès l’aurore, et viens sur le mont Sina, tu te tiendras là auprès de moi, sur la cime de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Que personne ne monte avec toi et ne se montre sur aucun lieu de la montagne, que ni bœufs ni brebis ne paissent auprès d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Et Moïse tailla deux tables de pierre semblables aux premières, et, s’étant levé de grand matin, il alla, comme lui avait dit le Seigneur, sur le mont Sina, tenant les deux tables de pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Le Seigneur descendit alors en une nuée; Moïse s’approcha de lui, et il invoqua le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Et le Seigneur passa devant sa face, et Moïse l’invoqua, disant Seigneur Dieu, plein de clémence, patient, abondant en miséricorde, véritable,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Fidèle à garder la justice et la compassion envers des milliers; ôtant l’iniquité, la faute, le péché, ne disculpant jamais le coupable, punissant les crimes des pères sur les enfants et les petits-enfants jusqu’à la troisième ou quatrième génération!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Moïse se hâta d’adorer, la face contre terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Et il dit: Si j’ai trouvé grâce devant mon Seigneur, qu’il marche avec nous; le peuple est revêche, mais vous');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Et le Seigneur dit à Moïse: J’établis mon alliance avec toi devant tout ton peuple; je ferai des choses glorieuses, que l’on n’a jamais vues sur la terre ni chez aucune nation. Et tout le peuple que tu conduis verra les œuvres de Dieu, les merveilles que je ferai pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Sois attentif à tout ce que je te prescris: je vais chasser devant votre face l’Amorrhéen, le Chananéen, le Phérézéen, l’Hettéen, l’Évéen, le Gergéséen et le Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Garde-toi de jamais faire d’alliance avec ceux qui sont établis sur cette terre en laquelle tu vas entrer, de peur qu’ils ne soient pour vous un sujet de chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Démolissez leurs autels, brisez leurs colonnes, arrachez leurs bois sacrés; quant aux images de leurs dieux, consumez-les dans la flamme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'N’adorez point de dieux étrangers, car le Seigneur Dieu est nommé zélateur; c’est un Dieu jaloux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ne fais jamais alliance avec ceux qui sont établis sur cette terre, de peur que les tiens ne se prostituent à leurs dieux, et ne leur offrent des sacrifices; que les habitants ne t’invitent et que tu n’en manges avec eux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'De peur aussi que tu ne prennes de leurs filles pour tes fils, ou que tu ne donnes de tes filles à leurs fils, et que tes filles ne se prostituent à leurs dieux, et que tes fils ne se prostituent à leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Tu ne te feras pas de dieux jetés en fonte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Tu observeras la fête des azymes. Pendant sept jours, tu mangeras des azymes, comme je te l’ai ordonné, dans la saison et durant la lune des blés nouveaux, car c’est dans la lune des blés nouveaux que tu es sorti de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Tout mâle, ayant ouvert des entrailles, sera à moi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Le premier-né de l’ânesse, tu les rachèteras moyennant une brebis, et, si tu ne les rachètes, tu en paieras la valeur. Tu rachèteras tout premier-né de tes fils; tu ne te présenteras point devant moi les mains vides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Tu travailleras six jours, mais le septième est le repos; il y aura repos pour la semence, repos pour la moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Tu me feras la fête des semaines, au commencement de la moisson des froments, et la fête de la récolte au milieu de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trois fois par an, que tout mâle parmi vous se présente devant le Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Car, lorsque j’aurai chassé devant toi les nations, et dilaté tes limites, nul ne convoitera ta terre, si tu montes pour te présenter devant le Seigneur ton Dieu, à trois époques de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Tu n’immoleras pas sur du pain fermenté les victimes que tu feras brûler pour moi; et tu ne garderas rien, jusqu’au matin suivant, des victimes de la pâque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tu déposeras en la maison du Seigneur ton Dieu les prémices de ta terre; tu ne feras point cuire d’agneau au lait de sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Le Seigneur Dieu dit encore à Moïse: Écris toimême ces paroles; car c’est sur ces paroles que je fonde mon alliance avec toi et avec Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Et Moïse était là devant le Seigneur quarante jours et quarante nuits; il ne mangea pas de pain, il ne but point d’eau; et il grava sur les tables les commandements de l’alliance: le Décalogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Et lorsque Moïse descendit de la montagne, il tenait en ses mains les deux tables; mais, tout en descendant de la montagne, Moïse ignorait que son visage était devenu glorieux, par la conversation du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Cependant, Aaron et tous les anciens d’Israël virent Moïse; ils virent que son visage était glorieux, et ils craignirent de s’approcher de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Moïse les appela; Aaron aussitôt se retourna vers lui avec tous les chefs du peuple, et Moïse leur parla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Ensuite, tous les fils d’Israël l’abordèrent, et il leur prescrivit tout ce que le Seigneur lui avait prescrit à lui-même sur le mont Sina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Et, lorsqu’il eut cessé de parler, il étendit un voile devant son visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Lorsque Moïse ensuite allait parler au Seigneur, il ôtait son voile jusqu’à ce qu’il revînt répéter aux fils d’Israël tout ce que lui avait prescrit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Et les fils d’Israël voyaient que le visage de Moïse était glorieux, et Moïse étendait un voile sur son visage jusqu’à ce qu’il s’en allât parler au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Moïse ensuite rassembla toute la synagogue d’Israël, et il dit Voici les commandements que le Seigneur veut que vous observiez:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Tu travailleras pendant six jours; mais le septième jour, repos, sabbat saint, repos du Seigneur; périsse quiconque fera œuvre en ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'N’allumez point de feu en vos demeures le jour du sabbat; je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Et Moïse parla à toute la synagogue d’Israël, disant: Voici l’ordre qu’a imposé le Seigneur, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Prenez, parmi vos biens, l’offrande du Seigneur; que quiconque s’y soumet de bon cœur, apporte au Seigneur des prémices: de l’or, de l’argent, de l’airain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'De l’hyacinthe, de la pourpre, de l’écarlate double filé, du lin filé et des poils de chèvre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Et des toisons de béliers teintes en rouge, et des toisons bleues, et des bois incorruptibles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'De l’huile à éclairer, des parfums pour l’huile de l’onction et pour la composition de l’encens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Et des cornalines, des pierres à graver pour l’éphod et pour la robe traînante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Qu’ensuite, tout homme sage, parmi vous, vienne, et façonne tout ce que le Seigneur a prescrit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Le tabernacle, avec les attaches, les voiles, les agrafes, les leviers et les colonnes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, '(18) L’arche du témoignage, avec ses leviers, son propitiatoire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'les voiles et les tentures du parvis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'avec ses colonnes; les pierres d’émeraude, l’encens et l’huile de l’onction;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'la table et tous ses accessoires;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'le chandelier et tous ses accessoires;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'l’autel et tous ses accessoires;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'les vêtements saints du prêtre Aaron,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, '13. Et les vêtements sacerdotaux, les tuniques sacerdotales de ses fils, l’huile de l’onction et l’encens composé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, '14. Et la synagogue entière des fils d’Israël s’éloigna de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, '15. Bientôt ils revinrent, apportant, chacun au gré de son cœur, en oblation au Seigneur, des dons pour tous les travaux du tabernacle du témoignage, pour ses accessoires et les vêtements saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, '16. Et les hommes apportèrent, chacun au gré de son cœur, des joyaux d’or de leurs femmes: des cachets, des boucles d’oreilles, des anneaux, des attaches de tresse et des bracelets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, '17. Et tous ceux qui avaient de l’or en apportèrent comme oblation au Seigneur; ceux qui avaient du lin, des toisons bleues, des toisons de béliers teintes en rouge, en apportèrent aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, '18. Parmi ceux qui faisaient ainsi leurs offrandes, d’autres apportèrent de l’argent ou de l’airain, comme oblation au Seigneur; ceux qui avaient des bois incorruptibles, et ce qu’il fallait pour les travaux auxquels on se préparait, en apportèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, '19. Toute femme adroite et intelligente, habile à filer, apporta des fils d’hyacinthe, de pourpre, d’écarlate et de lin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, '20. Et toutes les femmes, inspirées par de sages pensées, filèrent les poils de chèvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, '21. Les princes apportèrent les pierres d’émeraude, et les pierres qui devaient couvrir l’éphod et le rational,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, '22. Ainsi que tous les parfums nécessaires à l’huile de l’onction et à l’encens composé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, '23. Tout homme et toute femme, dont le cœur les y portait, se réunirent pour faire les travaux que le Seigneur avait prescrits par la voix de Moïse; les fils d’Israël apportèrent ainsi leurs oblations au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, '24. Moïse dit alors aux fils d’Israël: Le Seigneur a appelé par son nom Beseléel, fils d’Urias, fils d’Ur, de la tribu de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, '25. Et il l’a rempli d’un divin esprit de sagesse, d’intelligence et de science en toutes choses,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, '26. Pour qu’il dirige tous les travaux de construction, et qu’il façonne l’or, l’argent et l’airain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, '27. Pour qu’il taille les pierres, pour qu’il mette en œuvre les bois, pour qu’il fasse tous les ouvrages de sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, '28. Le Seigneur lui a donné, à lui et à Oliah, fils d’Achisamach, de la tribu de Dan, de progresser en habileté d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, '29. Il a rempli l’un et l’autre de sagesse, d’intelligence, d’esprit, pour qu’ils sachent faire tous les ouvrages du sanctuaire, les tissus et les broderies, pour qu’ils tissent l’écarlate et le lin, pour qu’ils achèvent toute œuvre d’art et de broderie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'En conséquence, Beseléel, Oliab, et tous les hommes sages d’esprit auxquels avaient été données la sagesse et la science, se mirent à l’œuvre pour faire tous les ouvrages du sanctuaire, comme les avait ordonnés le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Moïse appela Beseléel et Oliab, et tous les sages à qui Dieu avait mis la science au cœur, et tous ceux qui voulaient spontanément concourir à achever les travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Ceux-ci prirent chez Moïse les oblations qu’avaient apportées les fils d’Israël, pour les travaux du sanctuaire; en outre, ils recueillaient eux-mêmes les offrandes de ceux qui en apportaient chaque matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Bientôt tous les sages qui, chacun en son art, faisaient les travaux du sanctuaire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Vinrent dire à Moïse: Le peuple apporte plus que ne demandent les travaux que le Seigneur a ordonnés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Moïse alors donna ses ordres, et il fit faire, dans le camp, cette proclamation: Que ni homme ni femme ne fasse plus rien pour les prémices du sanctuaire; et il fut interdit au peuple d’en apporter encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Car les offrandes déjà faites étaient suffisantes pour l’achèvement de tout ce qu’il y avait à faire; elles furent même surabondantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, '(1) Et tout sage en cet art, parmi ceux qui travaillaient, fit les vêtements du sanctuaire et du Saint des saints pour le prêtre Aaron, ainsi que le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, '(2) Et l’on fit l’éphod d’or, d’hyacinthe, de pourpre, d’écarlate filé et de lin filé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, '(3) L’on coupa les feuilles d’or en fils aussi fins que des cheveux, pour les tisser avec l’hyacinthe, la pourpre, l’écarlate filé et le lin filé; l’on fit un tissu de ces divers fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, '(4) L’on fit les deux éphods joints l’un à l’autre des deux côtés, les deux tissus se rattachant l’un à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, '(5) Les deux éphods furent pareillement tissus d’or, d’hyacinthe, de pourpre, d’écarlate filé et de lin filé, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, '(6) Les travailleurs préparèrent aussi les deux pierres d’émeraude, agrafées ensemble, montées sur or, portant, gravées comme on grave un cachet, les noms des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, '(7) Ils les mirent sur les deux épaulières de l’éphod, pour servir de mémorial aux fils d’Israël, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, '(8) Et ils firent le rational, tissu orné de broderies, en harmonie avec l’éphod, tissu d’or, d’hyacinthe, de pourpre, d’écarlate filé et de lin filé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, '(9) Ils firent le rational double et carré, long d’un palme, large d’un palme; double.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, '(10) Ils y entrelacèrent un tissu, enchâssant quatre rangées de pierres, une première rangée: de cornaline, de topaze et d’émeraude;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, '(11) Une seconde rangée: d’escarboucle, de saphir, de jaspe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, '(12) Une troisième rangée: de ligure, d’agathe, d’améthyste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, '(13) Une quatrième enfin: de chrysolithe, de béril et d’onyx; toutes pierres montées sur or, enchâssées dans l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, '(14) Ces pierres furent marquées des noms des douze fils d’Israël; on y grava leurs noms comme on grave sur des cachets, douze noms pour les douze tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, '(15) Et les travailleurs firent, sur le rational, des chaînes tressées en mailles d’or pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, '(16) Ils firent deux boucles et des anneaux d’or; ils placèrent les deux anneaux d’or sur les deux coins supérieurs du rational.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, '(17) Ils placèrent les chaînes en mailles d’or, sur les anneaux, des deux côtés du rational.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, '(17) Et, aux jointures, ils passèrent les chaînes à mailles dans les deux boucles, et ils les ajustèrent sur les épaulières de l’éphod, par devant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, '(18) Ils firent encore deux anneaux d’or, qu’ils placèrent sur les deux extrémités du rational, d’une pointe à l’autre de l’éphod, par derrière et en dedans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, '(19) Et ils firent deux anneaux d’or, qu’ils posèrent sous les épaulières de l’éphod, par devant, et les ajustèrent à la couleur du tissu de l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, '(19) Beseléel serra ainsi le rational, au moyen de ces anneaux et des anneaux de l’éphod, faisant saillie sur l’hyacinthe, entrelacés dans le tissu de l’éphod, afin que le rational fût fixé à l’éphod, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, '(20) Les travailleurs firent en outre la longue robe, de dessous l’éphod, tout entière en hyacinthe,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, '(21) Et l’ouverture de la robe, au milieu, bordée d’un collet, pour qu’elle ne se déchirât point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, '(22) Ils firent, sous la bordure de la robe de dessous, tout en bas, comme de petits boutons sortant de grenades en fleur; ils les firent d’hyacinthe, de pourpre, d’écarlate filé et de lin filé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, '(23) Ils firent des clochettes d’or, et ils placèrent les clochettes, sur la bordure de la robe de dessous, tout autour, entremêlées de pommes de grenade;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, '(24) Une clochette d’or et une grenade se succédaient sur la bordure de la robe de dessous, pour le prêtre exerçant le sacerdoce, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, '(25) Ils firent des tuniques de lin, tissé pour Aaron et ses fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, '(27) Et des mitres de lin, et la tiare de lin, et les caleçons de lin filé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, '(28) Et les ceintures de lin, d’hyacinthe, de pourpre, d’écarlate filé; œuvre variée, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, '(29) Ils firent aussi la lame d’or, la lame de sainteté, en or pur; et Beseléel grava sur la plaque, comme sur un cachet: SAINTETÉ DU Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, '(30) Et il la posa sur la bordure d’hyacinthe pour l’attacher au haut de la tiare, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Ensuite ils firent, pour le tabernacle, dix courtines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, '(9) La longueur de l’une des courtines fut de vingt-huit coudées; elles eurent toutes la même longueur, sur une largeur de quatre coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, '(35) Et ils firent le voile d’hyacinthe, de pourpre, d’écarlate filé et de lin filé: œuvre tissue, œuvre variée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, '(36) Qu’ils placèrent sur quatre colonnes de bois incorruptible revêtu d’or fin, avec des chapiteaux d’or et des bases d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, '(37) Et ils firent le voile de la porte du tabernacle du témoignage; ils le firent d’hyacinthe, de pourpre, d’écarlate filé et de lin filé: œuvre variée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, '(38) Ils revêtirent d’or ses cinq colonnes, et les anneaux, et les chapiteaux, et les volutes; ils firent en airain les cinq bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, '(9) Ils firent le côté sud du parvis, les tentures du parvis en lin filé, sur une longueur de cent coudées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, '(10) Et leurs vingt colonnes et leurs vingt bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, '(11) Ils firent le côté nord sur une longueur de cent coudées, comme le côté du midi, et les vingt colonnes et les vingt bases;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, '(12) Et le côté de l’occident avec les tentures sur une longueur de cinquante coudées, et ses dix colonnes, et ses dix bases;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, '(13) Et le côté de l’orient avec les tentures sur une longueur de cinquante coudées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, '(14) Ayant, d’un côté, quinze coudées de haut, avec trois colonnes et trois bases;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, '(15) Et, de l’autre côté de la porte du parvis, ils firent des tentures de quinze coudées, et trois colonnes, et trois bases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, '(16) Ils firent de lin filé toutes les draperies du tabernacle;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, '(17) Et les bases de leurs colonnes en airain, avec leurs attaches d’argent, leurs chapiteaux revêtus d’argent, et les colonnes revêtues d’argent: toutes les colonnes du parvis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, '(18) Et la tenture de la porte du parvis, œuvre variée d’hyacinthe, de pourpre, d’écarlate filé et de lin filé; elle avait vingt coudées de haut, et cinq coudées de large, comme les tentures du parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, '(19) Et les quatre colonnes, avec leurs quatre bases d’airain, leurs attaches d’argent, leurs chapiteaux revêtus d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, '(20) Enfin, ils firent d’airain tous les piquets du parvis, et ils les revêtirent d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, '(21) Telle fut l’ordonnance du tabernacle du témoignage, comme le Seigneur l’avait prescrit à Moïse; le tabernacle fut le lieu sacerdotal; les lévites le gardèrent, à commencer par Ithamar, fils du prêtre Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, '(22) Et Beseléel, fils d’Urias, de la tribu de Juda, le fit comme le Seigneur l’avait prescrit à Moïse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, '(23) Avec Oliab, fils d’Achisamach, de la tribu de Dan, qui dirigea la fabrication des tissus et des broderies d’ornements, et qui fit tisser l’écarlate et le lin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, '(1) Et Beseléel fit l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, '(2) Il la revêtit d’or pur au dedans et au dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, '(3) Et, pour elle, il jeta en fonte quatre anneaux d’or, deux d’un côté, deux de l’autre côté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, '(5) Assez larges pour qu’en y passant les leviers, on pût enlever l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, '(6) Au-dessus de l’arche, il fit le propitiatoire en or pur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, '(7) Avec les deux chérubins d’or,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, '(8) L’un des chérubins sur l’un des bords du propitiatoire, l’autre chérubin sur l’autre bord,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, '(9) Ombrageant de leurs ailes la surface du propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, '(10) Il fit, pour être placé devant l’arche, la table');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, '(11) En or pur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, '(13) Et, pour elle, il jeta en fonte quatre anneaux, deux sur l’un des côtés, deux sur l’autre côté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, '(14) Assez larges pour qu’en y passant les leviers, on pût enlever la table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, '(15) Il fit les leviers de l’arche et de la table, et il les revêtit d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, '(16) Il fit aussi en or les vases de la table, les assiettes, les encensoirs, les urnes à puiser les libations, les coupes à les répandre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, '(17) Et il fit, pour porter la lumière, le chandelier d’or, à tige droite inflexible, avec les branches sortant de ses deux côtés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, '(18) Les fleurs tenant aux branches, qui étaient trois à droite et trois à gauche, semblables les unes aux autres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, '(19) Et leurs petites lampes, posant sur leurs extrémités, façonnées comme des noix, avec les becs qui en sortent pour en être les foyers lumineux, et le septième bec, sur la pointe extrême du chandelier, en or massif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, '(23) Et les sept lampes d’or, reposant sur le chandelier, avec leurs mouchettes d’or, et leurs récipients en or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Il revêtit d’argent les colonnes; il jeta en fonte les colonnes, les anneaux d’or; il revêtit d’or les leviers, ainsi que les colonnes du voile intérieur; il fit les attaches d’or, les boucles d’or du tabernacle, les boucles du parvis, et les boucles d’airain pour tendre la couverture extérieure; il jeta en fonte les chapiteaux d’argent du tabernacle, les chapiteaux d’airain de la porte du tabernacle et de la porte du parvis; il fit aussi les attaches d’argent sur les colonnes qu’il avait revêtues d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Et il fit les piquets du tabernacle, et les piquets du parvis, tous en airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, '(1) Il fit l’autel d’airain, avec les encensoirs d’airain, qui avaient appartenu aux hommes de la troupe de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, '(2) Et il fit les vases de l’autel avec son foyer, sa base, les coupes et les crochets d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, '(3) Il fit aussi pour l’autel une devanture en forme de grillage, au-dessous du foyer, descendant jusqu’à la moitié de l’autel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, '(4) Et il adapta quatre anneaux aux quatre angles supérieurs de cette devanture de l’autel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, '(7) Assez larges pour qu’en y passant les leviers, on pût enlever l’autel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, '(29) Il fit encore l’huile sainte de l’onction, et composa l’encens: œuvre pure de l’art du parfumeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, '(8) Il fit le réservoir d’airain et sa base d’airain, avec l’airain des miroirs des femmes, qui jeûnèrent devant la porte du tabernacle le jour où il le dressa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, '(28,29) Il fit le réservoir, afin que Moïse et Aaron et ses fils s’y lavassent les pieds et les mains,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, '(30) Avant d’entrer dans le tabernacle du témoignage ou de monter à l’autel pour exercer le sacerdoce; ils s’y lavaient comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, '(24) Tout l’or qui fut mis en œuvre pour la fabrication des choses saintes provint des prémices; il y en eut vingt-neuf talents ou sept cent vingt sicles, au poids du sicle consacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, '(26) L’oblation d’argent faite par tous les hommes du peuple ayant passé à la visite, monta à cent talents et dix-sept cent soixante-quinze sicles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, '(25) Une drachme par tête ou un demi-sicle, au poids du sicle consacré; les hommes de vingt ans et au-dessus qui passèrent à la visite, furent au nombre de six cent trois mille cinq cent cinquante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, '(27) Les cent talents d’argent furent employés à la fonte des cent chapiteaux du tabernacle et de la tenture intérieure; cent talents, cent chapiteaux: un talent par chapiteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, '(28) Avec les dix-sept cent soixante-quinze sicles d’argent, Beseléel fit les chapiteaux des colonnes, revêtit leurs chapiteaux et les orna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, '(29) L’airain des prémices produisit soixante talents et quinze cents sicles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, '(30) Ils en firent les bases des portes du tabernacle du témoignage, et les bases du parvis, tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, '(31) Ainsi que les bases des portes du parvis, les piquets du tabernacle, les piquets du parvis tout alentour, la devanture de l’autel et tous ses accessoires, tous les ustensiles du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, '(31) Les fils d’Israël firent ces œuvres, comme le Seigneur l’avait prescrit à Moïse; et, du reste des prémices, ils fabriquèrent les vases pour exercer le sacerdoce devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, '(1) Avec le reste de l’hyacinthe, de la pourpre, de l’écarlate, ils firent les vêtements d’Aaron, pour qu’il s’en revêtit en exerçant le sacerdoce dans le sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, '(32) Et ils portèrent les vêtements à Moïse, ainsi que le tabernacle et son ameublement, ses bases et ses chapiteaux, ses leviers, ses colonnes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, '(34) L’arche de l’alliance et ses leviers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, '(37) L’autel et tous ses accessoires; l’huile de l’onction et l’encens composé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, '(36) Le chandelier d’or pur, les lampes à brûler de l’huile, et l’huile à éclairer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, '(35) La table de la proposition, et tous ses accessoires, avec les pains à y déposer, les vêtements du sanctuaire qui étaient pour Aaron;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, '(25) Et les robes sacerdotales de ses fils;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, '(40) Les tentures du parvis, les colonnes, le voile de l’entrée du tabernacle, et celui de l’entrée du parvis, tous les vases du tabernacle et tous ses ustensiles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, '(33) Les toisons de béliers apprêtées et teintes en rouge, les couvertures bleues et les autres couvertures supérieures;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, '(40) Les piquets enfin et tous les ustensiles nécessaires aux œuvres du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, '(42) Tout ce que le Seigneur avait prescrit à Moïse, les fils d’Israël le firent; ils fabriquèrent tous les vases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, '(43) Et Moïse vit que tous les travaux étaient faits de la manière prescrite par le Seigneur à Moïse; les fils d’Israël les avaient ainsi faits, et Moïse les bénit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Le Seigneur parla ensuite à Moïse, et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Le premier jour de la première lune, le jour de la nouvelle lune, tu dresseras le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Tu placeras l’arche du témoignage, et tu la couvriras du voile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Tu introduiras la table sur laquelle tu poseras les pains de proposition; tu introduiras aussi le chandelier, et tu placeras ses lampes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Tu placeras l’autel d’or, pour brûler l’encens devant l’arche, et tu placeras le voile de l’entrée du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Tu placeras l’autel des holocaustes, devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Tu placeras le réservoir entre le tabernacle du témoignage et l’autel, et tu y mettras de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Et tu couvriras le tabernacle tout alentour, et tu sanctifieras tout ce qui lui appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Tu prendras de l’huile de l’onction, et tu oindras le tabernacle avec tous ses vases, et ils seront saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Tu oindras l’autel des holocaustes et tous ses accessoires; tu sanctifieras l’autel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Et l’autel sera très-saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Ensuite, tu conduiras Aaron et ses fils sur la porte du tabernacle du témoignage, et tu le laveras avec de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Tu revêtiras Aaron de ses vêtements saints, tu l’oindras, tu le sanctifieras, et il exercera mon sacerdoce. Tu conduiras aussi ses fils, et tu les revêtiras de leurs tuniques, tu les oindras comme tu auras oint leur père, et ils seront tous mes prêtres. Le chrême sera conservé pour leur onction sacerdotale à toujours, en toutes les générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Et Moïse fit tout ce que lui avait prescrit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Et dans la première lune de la seconde année depuis la sortie d’Égypte, le jour de la nouvelle lune, le tabernacle fut dressé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Moïse dressa le tabernacle; il plaça les chapiteaux, il plaça les leviers, il érigea les colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Il tendit les courtines sur le tabernacle; il plaça la couverture supérieure sur le tabernacle, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Et ayant pris les témoignages, il les mit dans l’arche, et il passa les leviers sous l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Ensuite il transporta l’arche dans le tabernacle, et il la couvrit avec le voile, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Il plaça la table dans le tabernacle du témoignage, du côté du septentrion, en dehors du voile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Il posa sur la table les pains de proposition devant le Seigneur, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Il plaça le chandelier dans le tabernacle du témoignage, du côté du midi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Il plaça les lampes devant le Seigneur, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Il plaça l’autel d’or dans le tabernacle du témoignage, devant le voile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Et il brûla sur l’autel l’encens composé, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Il plaça l’autel des holocaustes devant la porte du tabernacle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Et mit, entre l’autel et le tabernacle du témoignagne, le réservoir, dans lequel il versa de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Puis, il dressa le parvis autour du tabernacle et de l’autel Moïse accomplit tous ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Et une nuée enveloppa le tabernacle du témoignage; le tabernacle fut rempli de la gloire du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Et Moïse ne put entrer dans le tabernacle du témoignage, parce que la nuée l’enveloppait d’ombre, et que le tabernacle était rempli de la gloire du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Or, lorsque la nuée s’élevant découvrait le tabernacle du témoignage, les fils d’Israël devaient lever leur camp et emmener tous leurs bagages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Si elle ne s’élevait pas, ils ne préparaient point leur départ, jusqu’à ce qu’elle s’élevât.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Car la nuée se tenait le jour sur le tabernacle, et le feu s’y tenait la nuit, à la vue des fils d’Israël dans leurs campements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Le Seigneur rappela Moïse, du tabernacle du témoignage; le Seigneur lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Parle aux fils d’Israël, et dis-leur: Quiconque parmi vous amènera une offrande au Seigneur, donnera de son bétail (et c’est parmi les bœufs et les brebis que vous prendrez vos offrandes).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si son don est un holocauste, il conduira de ses bœufs un mâle sans tache vers la porte du tabernacle du témoignage, et il l’offrira tel qu’il soit agréable en présence du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Il imposera la main sur la tête de l’hostie agréable au Seigneur, afin qu’elle lui soit propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Et l’on égorgera le bœuf devant le Seigneur; les prêtres fils d’Aaron feront l’oblation du sang, qu’ils répandront ensuite autour de l’autel placé devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Après avoir écorché l’holocauste, ils le couperont par membres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Puis, les prêtres fils d’Aaron mettront du feu sur l’autel, et ils entasseront du bois sur le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Et les prêtres fils d’Aaron poseront sur le bois enflammé de l’autel les parts de la victime, ainsi que la tête et la graisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Ils laveront avec de l’eau les intestins et les pieds, et placeront le tout sur l’autel; c’est l’holocauste, le sacrifice, l’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Si le don au Seigneur est pris parmi les menus troupeaux, si l’holocauste est un agneau ou un chevreau, l’homme le choisira mâle et sans tache, et il imposera les mains sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'On l’égorgera à côté de l’autel, au nord, devant le Seigneur, et les prêtres fils d’Aaron en répandront le sang autour de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Puis, ils le couperont par membres, y compris la tête et la graisse; les prêtres placeront le tout sur le bûcher enflammé de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Ils laveront avec de l’eau les entrailles et les pieds; et le prêtre en fera l’offrande, et il les placera sur l’autel: c’est l’holocauste, le sacrifice, l’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Si c’est parmi les oiseaux que l’on prend l’offrande pour le Seigneur, le don sera choisi parmi les tourterelles ou les colombes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Et le prêtre l’offrira devant l’autel, lui repliera la tête, la posera sur l’autel, et fera couler le sang goutte à goutte, pour qu’il tombe au pied de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Il arrachera le gésier et les plumes, et il les jettera près de l’autel, du côté du levant, où sont les cendres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Il cassera les ailes, sans les couper, et il posera la victime sur le bois enflammé de l’autel; c’est l’holocauste, le sacrifice, l’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Mais si une âme apporte une oblation, son don devra être de fine fleur de farine, sur laquelle il versera de l’huile, et il posera par-dessus de l’encens; c’est un sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Il portera son offrande aux prêtres fils d’Aaron, et le prêtre en prendra une pleine poignée de fleur de farine avec de l’huile et tout l’encens qu’il placera sur l’autel comme mémorial de l’offrande; c’est le sacrifice, l’odeur de suavité pour le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Le reste de l’offrande sera pour Aaron et ses fils, comme chose très-sainte des sacrifices au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Si le don qu’on offre en sacrifice au Seigneur est cuit au four, qu’il soit de fleur de farine, que ce soit un pain azyme pétri dans l’huile ou un gâteau azyme imprégné d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Et si l’oblation est cuite à la poêle, qu’elle soit de fleur de farine qu’on aura pétrie, sans levain, dans l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Tu la rompras par morceaux, sur lesquels tu verseras de l’huile; c’est le sacrifice au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Si le présent est cuit sur le gril, qu’il soit de fleur de farine pétrie dans l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Et l’homme offrira en sacrifice celle de ces choses qu’il aura pétrie; il l’apportera au prêtre, et, s’étant approché de l’autel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Le prêtre en prendra le mémorial, qu’il posera sur l’autel; c’est le sacrifice de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Le reste du sacrifice sera pour Aaron et ses fils; comme chose très-sainte des sacrifices au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Toute offrande que vous apporterez au Seigneur vous la ferez sans levain; vous n’apporterez jamais ni levain, ni miel, pour en faire vos oblations au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Comme prémices, vous pourrez les offrir au Seigneur; mais on ne les placera point sur l’autel en odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Tous vos présents de sacrifice seront salés avec du sel; ne négligez pas le sel de l’alliance du Seigneur dans vos oblations; sur tous vos présents vous offrirez du sel au Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Lorsque tu offriras des premiers fruits au Seigneur, ce sera de nouveaux épis égrugés et grillés: telle sera l’offrande de tes premiers fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Tu verseras sur elle de l’huile, et tu mettras pardessus de l’encens: c’est un sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Et le prêtre en prendra le mémorial, qui sera une part des épis, et l’huile et tout l’encens; c’est le sacrifice au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Si le présent au Seigneur est une hostie pacifique, si l’homme la prend parmi ses bœufs ou ses vaches, il la choisira sans tache pour l’amener devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Et il imposera les mains sur la tête de la victime, il l’égorgera devant le Seigneur à la porte du tabernacle du témoignage; et le prêtres fils d’Aaron répandront le sang sur l’autel des holocaustes, tout autour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Et ils présenteront, de l’hostie pacifique, comme sacrifice au Seigneur, la graisse qui enveloppe les entrailles ainsi que la graisse qui est sur les entrailles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Les deux rognons, la graisse qui les entoure, celle des cuisses, et le lobe du foie que le prêtre enlèvera avec les rognons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Et les prêtres fils d’Aaron les porteront sur les holocaustes, sur le bois enflammé de l’autel; c’est le sacrifice, l’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Si le présent au Seigneur est une hostie pacifique prise parmi les menus troupeaux mâle ou femelle, l’homme la choisira sans tache pour en faire l’offrande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Si son offrande est un agneau, il l’amènera devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Après avoir imposé les mains sur la tête de l’hostie, il l’égorgera devant la porte du tabernacle du témoignage, et les prêtres fils d’Aaron répandront le sang sur l’autel, tout autour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Ensuite le prêtre prendra de l’hostie pacifique, comme sacrifice au Seigneur, la graisse et les reins intacts avec les lombes; il les offrira avec toute la graisse qui enveloppe les entrailles, ainsi que toute la graisse qui est dans les entrailles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Les deux rognons, la graisse qui les entoure, celle des cuisses, et le lobe du foie qu’il aura enlevé avec les rognons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Le prêtre les offrira sur l’autel; c’est le sacrifice d’odeur de suavité, le sacrifice au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Si le don est pris parmi les chèvres, l’homme l’amènera pareillement devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Il imposera les mains sur sa tête, et on l’égorgera devant le Seigneur à la porte du tabernacle du témoignage; les prêtres fils d’Aaron répandront le sang sur l’autel, tout autour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Et l’un d’eux offrira, de l’hostie, comme sacrifice au Seigneur, la graisse qui enveloppe les entrailles, toute la graisse qui est dans les entrailles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Les deux rognons, la graisse qui les entoure, celle des cuisses, et le lobe du foie qu’il aura enlevé avec les rognons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Et le prêtre les portera sur l’autel: sacrifice d’odeur de suavité pour le Seigneur; toute graisse est pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'C’est une loi perpétuelle pour toutes vos générations, en toutes vos demeures: Ne mangez ni graisse, ni sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Le Seigneur parla à Moïse, et il lui dit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Parle aux fils d’Israël, et dis-leur: Si une âme pèche involontairement contre l’un des commandements dų Seigneur, et fait quelqu’une des choses que l’on ne doit pas faire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Si de son côté, l’oint, le grand prêtre pèche, de manière à induire le peuple en péché, le grand prêtre amènera au Seigneur, pour racheter la faute qu’il aura commise, un veau sans tache pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Il amènera le veau en présence du Seigneur devant la porte du tabernacle du témoignage, il imposera ses mains sur la tête du yeau en présence du Seigneur, et il égorgera le veau en présence du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Ensuite l’oint, le prêtre, dont les mains ont été consacrées, prenant du sang de la victime, le portera dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Le prêtre trempera son doigt dans le sang, et avec le sang, il fera sept aspersions, en présence du Seigneur, devant le voile du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Et le prêtre mettra du sang de la victime sur les cornes de l’autel de l’encens composé, qui est devant le Seigneur, dans l’intérieur du tabernacle du témoignage. Ensuite, il répandra tout le sang du veau près de la base de l’autel des holocaustes, qui est devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Puis, il enlèvera toute la graisse du veau offert pour le péché la graisse qui enveloppe les entrailles, la graisse qui est dans les entrailles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Les deux rognons avec la graisse qui les entoure, celle des cuisses, et le lobe du foie qu’il aura enlevé avec les rognons,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'De la même manière qu’il enlève la graisse de l’hostie pacifique, et il la portera sur l’autel de l’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Quant à la peau du veau et toute sa chair, avec la tête, les extrémités, les intestins et la fiente,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Et le veau tout entier, on les portera hors du camp en un espace nettoyé, là où l’on met la cendre, et on le brûlera sur un bûcher enflammé sur la cendre répandue au lieu où il sera brûlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Mais si quelque cérémonie sacrée est omise involontairement par toute la synagogue d’Israël, s’ils font contre l’un des commandements du Seigneur une chose qui ne doive pas être faite, et pèchent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Et que le péché qu’ils ont commis vienne à être connu, toute la synagogue amènera pareillement un veau sans tache, pris parmi les bœufs, pour le péché, et il le présentera devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Les anciens de la synagogue imposeront leurs mains sur la tête de l’hostie, devant le Seigneur, et on égorgera le yeau devant le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Puis, l’oint, le prêtre portera du sang du veau dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Le prêtre trempera son doigt dans le sang du veau, et il fera sept aspersions en présence du Seigneur, en face du voile du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Le prêtre mettra du sang sur les cornes de l’autel de l’encens composé qui est devant le Seigneur, dans l’intérieur du tabernacle; ensuite, il répandra tout le sang du veau près de la base de l’autel des holocaustes, qui est devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Il enlèvera du veau toute la graisse, qu’il portera sur l’autel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Et il fera du veau comme il a fait du veau offert pour le péché ainsi fera-t-il, et le prêtre priera pour eux, et leur péché leur sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Ils porteront ensuite tout le veau hors du camp, et ils le brûleront tout entier comme ils auront brûlé le premier veau: c’est le péché de tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Si un prince a péché: s’il a fait contre l’un des commandements du Seigneur son Dieu, involontairement, une chose qui ne doive pas être faite, s’il a commis un péché ou un délit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Si le péché dans lequel il est tombé, vient à lui être connu, il présentera pour offrande un bouc, pris parmi les chèvres, et sans tache;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Il imposera la main sur la tête du bouc, et on l’égorgera dans le lieu où l’on égorge les victimes d’holocauste devant le Seigneur: c’est le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Ensuite, le prêtre, avec son doigt, mettra du sang du péché sur les cornes de l’autel des holocaustes, et il répandra tout le sang au pied de l’autel des holocaustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Puis, il portera toute la graisse sur l’autel, comme on fait pour la graisse d’une hostie pacifique, et le prêtre priera pour lui au sujet de son péché, qui lui sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Si, parmi le peuple, une âme pèche involontairement en faisant, contre les commandements de Dieu, quelque chose que l’on ne doit pas faire, et commet un péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Si le péché dans lequel elle est tombée, vient à lui être connu, elle portera pareillement une hostie du troupeau de chèvres; elle offrira une femelle sans tache pour le péché qu’elle aura commis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Et elle imposera la main sur la tête de son péché, et l’on égorgera la chèvre du délit au lieu où l’on égorge les victimes d’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Le prêtre ensuite prendra de son sang avec le doigt, il en mettra sur les cornes de l’autel des holocaustes, et il répandra tout le sang au pied de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Puis, il enlèvera toute la graisse, comme on enlève la graisse d’une hostie pacifique, et il la portera sur l’autel, pour être au Seigneur une odeur de suavité. Et le prêtre priera pour cette âme, et son péché lui sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Si l’offrande qu’elle apporte, pour son péché, est prise parmi les brebis, ce sera une femelle sans tache qu’elle devra offrir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'L’homme imposera les mains sur la tête de son péché, et l’on égorgera l’hostie dans le lieu où l’on égorge les victimes d’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Ensuite, le prêtre ayant pris avec le doigt du sang du péché, en mettra sur les cornes de l’autel des holocaustes, et il répandra tout le sang au pied de l’autel des holocaustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Puis, il enlèvera toute la graisse, comme on enlève');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Si une âme pèche et entend quelqu’un faisant un serment, si elle a été témoin de la chose, et qu’elle ne découvre pas ce qu’elle a vu et connu elle-même, elle se rendra coupable d’un délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Si une âme touche une chose impure: cadavre, proie impure de bête fauve, cadavre impur et abominable, cadavre de bétail impur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Ou l’une des impuretés de l’homme, l’une de ces impuretés qui souillent quand on les a touchées; si, l’ignorant d’abord, elle vient à le savoir, elle se trouve coupable d’un délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'L’âme injuste qui, ayant de ses lèvres promis de faire, bien ou mal, l’une de ces choses que l’homme promet sous serment, la perd de vue, si elle vient à s’en souvenir et manque à quelque chose de ce qu’elle a promis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Cette âme confessera son délit, et les choses en quoi elle a péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Et, à cause de son offense au Seigneur, à cause de son délit, elle prendra, dans ses menus troupeaux, une femelle, brebis ou chevrette, pour le péché; et le prêtre priera Dieu pour elle au sujet du délit qu’elle aura commis, et son délit lui sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Si ses facultés sont insuffisantes pour donner une brebis, l’homme offrira, pour son péché au Seigneur, deux tourterelles ou deux pigeonneaux, l’un pour le délit, l’autre pour l’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Il les portera au prêtre, et le prêtre apportera le premier à l’autel pour le délit; il repliera la tête du côté de la seconde vertèbre, mais il ne l’enlèvera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Il aspergera du sang du délit les côtés de l’autel, et il fera couler le sang goutte à goutte au pied de l’autel: car c’est le délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Il fera, du second oiseau, un holocauste, comme il convient, et le prêtre priera Dieu pour l’homme au sujet du délit qu’il aura commis, et son délit lui sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Si ses facultés sont insuffisantes pour qu’il apporte un couple de tourterelles ou deux pigeonneaux, il apportera en don, pour son péché, un dixième d’éphi de fine fleur de farine. Il ne versera point l’huile sur la farine, et, sur elle, il ne mettra pas d’encens, parce qu’elle est offerte à cause d’un délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'L’homme portera au prêtre le dixième d’éphi, et le prêtre ayant pris une pleine poignée de farine, la mettra sur l’autel des holocaustes comme mémorial de l’oblation: c’est le délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Et le prêtre priera Dieu pour l’homme au sujet du délit qu’il aura commis en une de ces choses, et son délit lui sera remis. Le reste de l’oblation sera pour le prêtre, comme sacrifice de fleur de farine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Le Seigneur parla encore à Moïse, et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'L’âme qui aura eu un oubli et péché involontairement contre une des choses saintes du Seigneur, apportera, pour son délit, au Seigneur, un bélier sans tache du troupeau de brebis, évalué en sicles d’argent, au poids du sicle du sanctuaire; ce sera pour le manquement qu’elle aura commis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Et ce qui a fait défaut dans les choses saintes, elle le rendra; elle ajoutera même un cinquième de sa valeur, qu’elle donnera au prêtre, et le prêtre, au moyen de son bélier, lui rendra Dieu propice au sujet de son péché, et son péché lui sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'L’âme qui, sans s’en apercevoir, aura péché et fait, au sujet de l’un quelconque des commandements de Dieu, quelque chose que l’on ne doit point faire, aura commis ainsi un délit, et contracté un péché,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Présentera au prêtre un bélier sans tache de son troupeau de brebis, d’un prix en argent proportionné à son péché; et le prêtre priera Dieu pour elle à cause de son ignorance, et parce qu’elle ne savait pas qu’elle avait péché, et son péché lui sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Car cette âme a commis un délit devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Et le Seigneur parla à Moïse, et il lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'L’âme qui aura péché, qui aura méprisé et méprisé les commandements du Seigneur, et qui aura frauduleusement agi envers son prochain, au sujet d’un dépôt ou d’une association, ou en le volant, enfin, qui aura commis quelque injustice envers son prochain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Ou qui aura trouvé une chose perdue, et, au sujet de cette chose, aura menti ou qui aura fait un faux serment concernant l’une des affaires que font les hommes, de telle sorte que, par l’un de ces moyens, elle ait péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Que cette âme, qui aura commis l’un de ces délits, rende le bien dont elle s’est emparée, qu’elle répare le tort qu’elle aura fait, qu’elle rende le dépôt qui lui aura été confié ou la chose qu’elle aura trouvée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Quelle que soit la chose au sujet de laquelle elle aura prêté un faux serment, elle la rendra tout entière, en y ajoutant un cinquième en sus; elle la rendra au maître, le jour même où elle aura été convaincue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Pour son délit, qu’elle présente en outre au Seigneur un bélier sans tache de son troupeau de brebis, d’un prix proportionné à son péché,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Et le prêtre priera Dieu pour elle, et son péché lui sera remis en chacune des choses en quoi elle aura failli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Donne ces ordres à Aaron et à ses fils; dis-leur: Voici la règle des holocaustes; voici comment on les brûlera: on les brûlera sur l’autel toute la nuit jusqu’au point du jour, et le feu brûlera toujours sur l’autel, et il ne sera pas éteint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Le prêtre ensuite revêtira une tunique de lin, et il passera autour de son corps des caleçons de lin, et il enlèvera de l’autel les restes de l’hostie que le feu aura consumée, les restes de l’holocauste, et il les déposera contre l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Puis, il quittera sa tunique pour un autre vêtement, et il emportera le résidu de l’holocauste hors du camp, dans un lieu pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Le feu brûlera sur l’autel, il ne sera pas éteint, et le prêtre y fera brûler du bois de grand matin, et il y entassera les holocaustes, sur lesquels il posera la graisse des hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Le feu brûlera toujours sur l’autel, et il ne sera pas éteint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Voici la règle du sacrifice que les fils d’Aaron feront devant le Seigneur, en face de l’autel:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Le prêtre enlèvera une pleine poignée de la fleur de farine du sacrifice, avec l’huile et tout l’encens qui sont sur le sacrifice, et il portera cette part sur l’autel; ce sera le sacrifice, l’odeur de suavité, le mémorial pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Aaron et ses fils mangeront le reste du sacrifice; ce sera un azyme mangé en lieu saint; ils le mangeront dans le parvis du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'On n’y mettra pas de levain; c’est la part des sacrifices au Seigneur que je leur ai donnée; elle est très-sainte, comme celle du sacrifice pour le péché et celle du sacrifice pour le délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Tout mâle, parmi les prêtres, la mangera; c’est la loi perpétuelle des sacrifices pour toutes vos générations: quiconque en aura mangé sera sanctifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Voici l’oblation qu’Aaron et ses fils feront au Seigneur, à partir du jour où tu les oindras: Le dixième d’un éphi de fleur de farine en sacrifice, moitié le matin et moitié le soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'On le fera frire dans l’huile, à la poêle; on l’offrira en rouleau et brisé par fragments; c’est le sacrifice d’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'L’oint, le prêtre, celui des fils d’Aaron qui lui succédera, fera le sacrifice; c’est une loi éternelle; tout sera consumé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Car, tout sacrifice de prêtre sera un holocauste; on n’en mangera rien,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Le Seigneur parla encore à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Parle à Aaron et à ses fils; dis-leur: Voici la loi des sacrifices pour le péché: c’est dans le lieu où l’on immole les holocaustes que l’on immolera devant le Seigneur les victimes pour le péché; elles seront choses très-saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Le prêtre qui les offrira, les mangera; il les mangera en lieu saint, dans le parvis du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Quiconque aura touché les chairs d’une victime, sera sanctifié; et quiconque aura eu son manteau aspergé de sang, ou aura été aspergé lui-même, sera lavé en lieu');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Le vase de poterie dans lequel on aura fait cuire les chairs, sera brisé, et si on les a fait cuire en un vase d’airain, on le nettoiera et on le lavera avec de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Tout mâle, parmi les prêtres, les mangera; elles sont choses très-saintes devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Toute victime, pour le péché, dont on aura introduit du sang dans le tabernacle du témoignage, pour intercéder dans le saint, ne sera pas mangée, mais consumée par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Voici la règle du sacrifice d’un bélier pour toute espèce de faute. La victime est chose très-sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'C’est dans le lieu où l’on immole les holocaustes que l’on immolera le bélier pour la faute, et l’on répandra son sang sur la base de l’autel, tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Et l’on offrira, du bélier, toute la graisse et les reins, et toute la graisse qui enveloppe les entrailles, et toute la graisse qui est dans les entrailles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'On enlèvera les deux rognons avec la graisse qui les entoure, celle des cuisses et le lobe du foie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Et le prêtre les portera sur l’autel: c’est l’hostie au Seigneur, pour la faute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Tout mâle, parmi les prêtres, les mangera; il les mangera en lieu saint; elles seront choses très-saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Semblable au sacrifice pour le péché, est le sacrifice pour la faute; la loi est une pour l’un et pour l’autre; c’est au prêtre qui aura intercédé par ce sacrifice que l’hostie restera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Le prêtre qui aura immolé l’holocauste offert par un homme, après avoir immolé la victime, en aura la peau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'En tout sacrifice de fleur de farine, cuite au four, ou sur le gril, ou à la poêle à frire, l’offrande restera au prêtre qui l’aura faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'En tout sacrifice de farine, pétrie ou non pétrie dans l’huile, l’offrande sera partagée également entre les fils d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Voici la loi de l’hostie pacifique que l’on offrira au Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si elle est offerte comme louange à Dieu, l’homme offrira aussi, avec l’hostie de louange, des pains de fleur de farine pétris dans l’huile, et des gâteaux azymes arrosés d’huile, et de la fleur de farine pétrie dans l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Il offrira ses dons avec des pains levés, et avec l’hostie pacifique de louange à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'On prendra un de ces présents pour l’offrir en oblation au Seigneur; le reste appartiendra au prêtre qui répandra le sang de l’hostie pacifique;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Et les chairs de l’hostie pacifique de louange seront à lui; elle sera mangée le jour même où elle aura été offerte; on n’en conservera rien pour le lendemain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Si l’offrande est un vœu ou un sacrifice volontaire, l’hostie sera mangée le jour même où on l’aura conduite, et le jour suivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Ce qui, le troisième jour, resterait de ses chairs, sera consumé par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Si l’on vient à en manger le troisième jour, elle cessera d’être favorable à celui qui l’aura offerte; elle ne lui sera point comptée: c’est une souillure. L’âme qui en aura mangé se rendra coupable de péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Nulle chair qui aura touché une chose impure ne sera mangée; elle sera consumée par le feu. Tout homme pur pourra manger de la chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Mais l’âme qui aura mangé des chairs de l’hostie pacifique qui sont au Seigneur, ayant quelque impureté sur elle, cette âme périra parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'L’âme qui aura touché quoi que ce soit d’impur, soit de l’impureté de l’homme, soit des quadrupèdes impurs, soit de quelque impureté abominable, et mangera des hosties pacifiques qui sont au Seigneur, périra parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Parle aux fils d’Israël; dis-leur: Vous ne mangerez point de la graisse des bœufs, ni des brebis, ni des chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Faites n’importe quoi de la graisse des cadavres ou des têtes de bétail enlevées par des bêtes fauves, mais n’en mangez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Quiconque aura mangé de la graisse des bestiaux qu’il aura conduits, comme hosties au Seigneur, périra parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Vous ne mangerez point de sang des bestiaux ni des oiseaux, en aucune de vos demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Toute âme qui mangera du sang, périra parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Parle encore aux fils d’Israël, et dis-leur: Celui qui offrira une hostie pacifique, fera aussi au Seigneur présent d’une part de l’hostie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Ses mains porteront les offrandes au Seigneur, savoir: la graisse de la poitrine et le lobe du foie; il les portera afin de les déposer comme dons devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Le prêtre offrira la graisse sur l’autel, et la poitrine sera pour Aaron et ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'De vos hosties pacifiques, vous donnerez l’épaule droite, qui est réservée au prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Celui des fils d’Aaron qui offrira du sang et de la graisse de l’hostie pacifique, aura, pour sa part, l’épaule droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Car j’ai pris, sur les hosties pacifiques des fils d’Israël, la poitrine, mise à part, et l’épaule réservée, pour les donner à Aaron et à ses fils; c’est la loi perpétuelle des sacrifices des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Telle est des sacrifices au Seigneur la part acquise par l’onction d’Aaron et par l’onction de ses fils, du jour où cette onction leur a attribué l’exercice du sacerdoce de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'C’est ce que le Seigneur a prescrit de leur donner le jour où il les a oints parmi les fils d’Israël; c’est une loi perpétuelle pour vos générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Telle est la loi des holocaustes et des sacrifices pour le péché, pour la faute, pour la consécration et pour les hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Comme le Seigneur l’a prescrit à Moïse, sur le mont Sina, le jour où, dans le désert de Sina, il a prescrit aux fils d’Israël de faire les sacrifices au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Prends Aaron et ses fils, ainsi que leurs vêtements, l’huile de l’onction, le veau pour le péché, les deux béliers et la corbeille des azymes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Et rassemble toute la synagogue devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Moïse fit ce qu’ordonnait le Seigneur: il rassembla toute la synagogue devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Et Moïse dit à la synagogue: Voici ce que le Seigneur a ordonné de faire:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Alors, Moïse fit approcher Aaron et ses fils, et il les lava avec de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Il mit à Aaron la tunique, il le ceignit de la ceinture; il le revêtit de la robe longue, et, sur la robe, il plaça l’éphod,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Qu’il ajusta et serra sur lui par ses liens; sur l’éphod il plaça le rational, et sur le rational, la Manifestation et la Vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Ensuite, il posa la tiare sur la tête d’Aaron, et sur la tiare, devant le front, il mit la plaque d’or, la plaque sainte, consacrée, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Moïse prit de l’huile de l’onction,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Dont il fit sept aspersions sur l’autel; il en oignit l’autel, et il le sanctifia avec tous ses accessoires; il sanctifia aussi le réservoir avec sa base; il oignit le tabernacle avec tout son ameublement, et il le sanctifia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Moïse versa de l’huile de l’onction sur la tête d’Aaron; il l’oignit et il le sanctifia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Après cela, Moïse fit approcher les fils d’Aaron; il les revêtit de tuniques, il les ceignit de ceintures, et il leur mit des tiares, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Ensuite, Moïse fit approcher le veau offert pour le péché; et Aaron ainsi que ses fils imposèrent les mains sur la tête du veau pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Moïse l’égorgea, puis, il prit de son sang, et, du doigt, il en mit sur les cornes de l’autel; il purifia l’autel lui-même, répandit au pied le sang, et sanctifia l’autel pour faire sur lui la propitiation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Moïse prit aussi toute la graisse des entrailles, le lobe du foie, les deux rognons et la graisse qui les entoure; il porta le tout sur l’autel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Et le veau, sa peau, ses chairs et la fiente furent brûlés hors du camp, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Moïse fit aussi approcher le bélier pour l’holocauste; Aaron et ses fils imposèrent les mains sur la tête du bélier; Moïse l’égorgea, et en répandit le sang autour de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Puis, il le dépeça par membres; il fit l’oblation de la tête, des membres et de la graisse; et il lava avec de l’eau les entrailles et les pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Et Moïse porta tout le bélier sur l’autel: c’était l’holocauste, le sacrifice d’odeur de suavité pour le Seigneur, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Moïse fit approcher le second bélier, le bélier de la consécration; Aaron et ses fils imposèrent les mains sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Moïse l’égorgea; il prit de son sang, et il en mit sur le lobe de l’oreille droite d’Aaron, sur l’extrémité de sa main droite, et sur l’extrémité de son pied droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Moïse fit approcher les fils d’Aaron, et il mit du sang sur les lobes de leurs oreilles droites, sur les extrémités de leurs mains droites, et sur les extrémités de leurs pieds droits; Moïse ensuite répandit le sang autour de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Après quoi, il prit la graisse, les reins, la graisse des entrailles et le lobe du foie, les deux rognons, avec la graisse qui les entoure, et l’épaule droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Puis, il prit, dans la corbeille de la consécration placée devant le Seigneur, un pain azyme, un pain à l’huile avec un gâteau, et il les mit sur la graisse et sur l’épaule droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Et il posa le tout dans les mains d’Aaron et de ses fils, et il présenta le tout comme part consacrée, en présence du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Cela fait, Moïse retira le tout de leurs mains, et il le porta sur l’autel au-dessus de l’holocauste de la consécration, qui est le sacrifice de suave odeur pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Ayant ensuite pris la poitrine du bélier de la consécration, Moïse en fit l’oblation au Seigneur, et ce fut la part de Moïse, comme le lui avait prescrit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Moïse prit de l’huile de la consécration, ainsi que du sang déposé sur l’autel, et il en aspergea Aaron et ses vêtements, et, en même temps, les fils d’Aaron et leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Ainsi, il sanctifia Aaron et ses vêtements, et ses fils et leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Et Moïse dit à Aaron et à ses fils: Faites cuire les chairs dans le parvis du tabernacle du témoignage en lieu saint; mangez-les là avec les pains qui sont dans la corbeille de la consécration, comme me l’a prescrit le Seigneur lorsqu’il m’a dit: Aaron et ses fils les mangeront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Et consumez par le feu le reste des chairs et du pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Pendant sept jours, ne sortez pas du tabernacle, jusqu’à ce que soient accomplis les jours de votre consécration; car c’est en sept jours que le Seigneur consacrera vos mains,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Comme il l’a fait le jour où il m’a ordonné de le faire, pour qu’il vous soit propice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Et, pendant ces sept jours, vous demeurerez assis devant la porte du tabernacle du témoignage, le jour et la nuit; vous observerez les commandements du Seigneur, afin que vous ne mouriez point; car tels sont les ordres que m’a donnés le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Et Aaron et ses fils exécutèrent tous les ordres que le Seigneur avait donnés à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Le huitième jour, Moïse appela Aaron, ses fils et les anciens d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Et Moïse dit à Aaron: Prends, parmi les bœufs, un jeune veau pour le péché; prends un bélier sans tache pour l’holocauste, et offre-les au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Et parle aux anciens d’Israël, disant: Prenez, parmi les chèvres, un bouc pour le péché; prenez ensuite un jeune veau et un agneau d’un an sans tache, pour l’holocauste;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Puis, le veau et le bélier pour hosties pacifiques devant le Seigneur, puis, de la fleur de farine pétrie dans l’huile, car le Seigneur aujourd’hui vous apparaîtra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Et ils amenèrent devant le tabernacle du témoignage les victimes que Moïse avait ordonné de prendre; toute la synagogue s’approcha, et se tint debout devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Alors Moïse dit: Voici l’ordre qu’a donné le Seigneur, exécutez-le, et la gloire du Seigneur va vous apparaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Moïse dit aussi à Aaron: Approche-toi de l’autel, sacrifie la victime pour ton péché, brûle ton holocauste, et prie pour toi et pour ta maison; ensuite, sacrifie les victimes données par le peuple, et prie pour eux tous, comme le Seigneur l’a prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Et Aaron s’approcha de l’autel, et il égorgea le veau. pour son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Les fils d’Aaron lui présentèrent le sang, dans lequel il trempa son doigt; il en mit sur les cornes de l’autel, et il répandit le reste au pied de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Ensuite, il posa sur l’autel la graisse, les rognons et le lobe du foie de la victime pour le péché, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Et il consuma par le feu, hors du camp, les chairs et la peau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Il égorgea aussi l’holocauste; les fils d’Aaron lui en présentèrent le sang, et il le répandit autour de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Ils lui présentèrent l’holocauste dépecé par membres, et il plaça sur l’autel la tête et les membres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Puis, il lava, avec de l’eau, les entrailles et les pieds, et il les plaça au-dessus de l’holocauste sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Il offrit le don du peuple; il prit le bouc pour le péché du peuple, l’égorgea, et le nettoya, comme la précédente victime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Et il l’offrit en holocauste, selon les règles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Il offrit le sacrifice, dont il prit entre ses mains une part qu’il posa sur l’autel, en sus de l’holocauste du matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Il égorgea le veau et le bélier, hosties pacifiques du peuple, et les fils d’Aaron lui présentèrent le sang, et il le répandit tout autour de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Il prit la graisse du veau, les reins du bélier, la graisse qui enveloppe les entrailles, les deux rognons avec la graisse qui les entoure, et le lobe du foie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Et il mit la graisse par-dessus les poitrines, et il porta toute la graisse sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Puis Aaron enleva la poitrine et l’épaule droite, portions mises à part pour l’offrande au Seigneur, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Alors, ayant étendu les mains sur le peuple, Aaron le bénit; et il descendit après avoir sacrifié les victimes pour le péché, les holocaustes, et les hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Aussitôt, Moïse avec Aaron entra dans le tabernacle du témoignage; puis, étant sortis, ils bénirent tout le peuple, et la gloire du Seigneur apparut au peuple tout entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Et il descendit du Seigneur un feu qui dévora les victimes déposées sur l’autel, les holocaustes et la graisse; tout le peuple le vit, et, saisis d’admiration, ils tombèrent la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Cependant, deux des fils d’Aaron, Nadab et Abiu, ayant pris chacun leur encensoir, y mirent du feu, sur lequel ils jetèrent de l’encens; ils offrirent donc devant le Seigneur un autre feu que celui qu’il leur avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Et il descendit du Seigneur un feu qui les dévora, et ils moururent devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Moïse dit alors à Aaron: C’est là ce qu’avait dit le Seigneur Je serai sanctifié en ceux qui m’approchent, je serai glorifié devant toute la synagogue. Et Aaron fut pénétré de componction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Moïse appela Misaël et Elisaphan, fils d’Oziel, frère du père d’Aaron, et il leur dit: Approchez et enlevez vos frères de devant le sanctuaire, portez-les hors du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Et ils approchèrent, et ils les portèrent hors du camp, dans leurs propres tuniques, comme avait dit Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Moïse dit à Aaron et aux fils qui lui restaient, Eléazar et Ithamar: N’ôtez point les tiares de vos têtes, ne déchirez pas vos vêtements, si vous ne voulez mourir, et faire tomber sur tout le peuple la colère du Seigneur. Vos frères, toute la maison d’Israël, pleureront l’embrasement dans lequel Nadab et Abiu ont été consumés par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ne franchissez pas pour sortir la porte du tabernacle du témoignage si vous ne voulez mourir, car l’huile de l’onction du Seigneur est sur vous. Et ils firent selon la parole de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Et le Seigneur parla aussi à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Ni toi, ni tes fils, ne boirez de vin ou de boisson fermentée lorsque vous entrerez dans le tabernacle du témoignage, et lorsque vous approcherez de l’autel, afin que vous ne mouriez point; c’est une loi perpétuelle en toutes vos générations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Pour marquer la séparation entre les choses saintes et les profanes, entre les choses pures et les impures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Et pour enseigner aux fils d’Israël toutes les lois que leur a dites le Seigneur, par l’intermédiaire de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Moïse dit à Aaron et aux fils qui lui restaient, Eleazar et Ithamar: Prenez la part réservée des sacrifices au Seigneur, et mangez les azymes près de l’autel; c’est la chose très-sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Et mangez-la en lieu saint: car telle est pour toi et pour tes fils la loi des sacrifices au Seigneur, c’est ainsi qu’elle m’a été prescrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Quant à la poitrine mise à part, et à l’épaule réservée, mangez-les en lieu saint, toi, tes fils et ta maison; car, selon la loi des hosties pacifiques des fils d’Israël, c’est la part qui a été donnée à toi et à tes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'L’épaule mise à part, et la poitrine réservée, ils les offriront au-dessus des holocaustes et de la graisse, et ils les mettront à part devant le Seigneur; ce sera une loi perpétuelle pour toi, tes fils et tes filles, comme le Seigneur l’a prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Et Moïse chercha de toutes parts le bouc expiatoire du péché, et il avait été brûlé. Et Moïse s’irrita contre les fils qui restaient à Aaron, Éleazar et Ithamar, et il leur dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Pourquoi n’avez-vous pas mangé ce qui était pour le péché dans le lieu saint? c’est chose très-sainte; le Seigneur vous l’a donnée à manger, pour que vous ôtiez le péché du peuple, et que vous priiez le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Car on n’a point porté de son sang en lieu saint; mangez-la donc dans le lieu saint devant le Seigneur, comme l’a commandé le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Et Aaron parla à Moïse, disant: Puisqu’on a offert aujourd’hui les victimes pour leurs péchés, et leurs holocaustes devant le Seigneur, et que ces choses me sont arrivées, puis-je manger aujourd’hui des victimes pour le péché? Le Seigneur l’aura-t-il pour agréable?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Moïse l’entendit, et il l’approuva.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Et le Seigneur parla à Moïse, à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Parlez aux fils d’Israël, dites-leur: Voici, parmi tous les animaux de la terre, ceux que vous mangerez:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Toute bête au pied fourchu dont le sabot se sépare en deux cornes, et est en même temps bête ruminante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Mais voici les animaux dont vous ne mangerez pas, même s’ils ruminent ou s’ils ont le pied fourchu, et si leur sabot se sépare en deux cornes: le chameau, qui rumine, mais n’a pas le pied fourchu: il est impur pour vous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Le lièvre, qui ne rumine pas et n’a pas le pied fourchu: il est impur pour vous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Le porc-épic, qui ne rumine pas et n’a pas le pied fourchu: il est impur pour vous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Le pourceau, qui a le pied fourchu et la corne fendue en ongles, mais qui ne rumine pas: il est impur pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Vous ne mangerez pas des chairs de ces bêtes; vous ne toucherez pas à leurs corps morts; ils sont impurs pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Voici ce que vous mangerez de tout ce qui est dans les eaux tout ce qui a des nageoires et des écailles, dans les eaux, dans la mer et les torrents, vous en mangerez;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Et ce qui n’a ni nageoires ni écailles dans les eaux, dans la mer, dans les torrents, parmi tous les êtres que les eaux produisent, et parmi tout ce qui a vie dans les eaux, est impur, et vous le tiendrez pour abominable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Vous ne mangerez point de leurs chairs, et leurs corps morts vous seront en abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Et tout ce qui dans les eaux n’a ni écailles, ni nageoires, est abomination pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Parmi les oiseaux voici ceux que vous tiendrez pour abominables et dont vous ne mangerez point: l’aigle, le griffon et l’aigle de mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Le vautour, le milan et ses analogues,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'L’autruche, la chouette, la mouette et ses analogues,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Tous les corbeaux et leurs analogues, l’épervier et ses analogues,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Le hibou, le plongeur, l’ibis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Le porphyrion, le pélican, le cygne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Le héron, le pluvier et ses analogues, la huppe et la chauve-souris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Parmi les êtres ailés, tous ceux qui se traînent et marchent sur quatre pieds, vous seront en abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Mais vous mangerez celles des bêtes ailées qui, se traînant et marchant sur quatre pieds, ont ceux de derrière plus longs que ceux de devant, et s’en aident pour bondir sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Parmi les bêtes ailées, vous mangerez celles-ci: le bruchos et ses analogues, l’attacos et ses analogues, l’ophiomachos et ses analogues, la sauterelle et ses analogues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Tout reptile quadrupède, parmi les bêtes ailées, est pour vous abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Par eux, vous serez souillés; quiconque aura touché leurs corps morts sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Quiconque aura enlevé leurs corps morts lavera ses vêtements, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Parmi les bestiaux, ceux qui ont le pied fourchu et le sabot séparé, et qui ne ruminent pas, seront impurs pour vous; quiconque aura touché leurs corps morts sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Parmi les bêtes sauvages, celles qui marchent sur des mains et qui marchent sur quatre mains, seront impures pour vous; quiconque aura touché leurs corps morts sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Celui qui aura enlevé leurs corps morts lavera ses vêtements, et sera impur jusqu’au soir; elles sont impures pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Parmi celles qui se traînent à terre, voici celles qui seront impures pour vous: la belette, le rat, le crocodile terrestre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'La musaraigne, le caméléon, le chalabotis, le lézard et la taupe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ces bêtes seront impures pour vous, parmi celles qui se traînent à terre; quiconque aura touché leurs corps morts, sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Toute chose sur quoi l’une d’elles sera tombée morte, sera impure; que ce soit vase de bois, vêtement, cuir ou sac, ou tout autre meuble dont on se sert pour travailler; on le lavera dans l’eau, et il restera impur jusqu’au soir; alors il redeviendra pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Tout vase de poterie dans l’intérieur duquel tombera l’une de ces bêtes, quoi qu’il contienne, sera impur;\" il sera brisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Tout aliment dont on mange, tout breuvage bu en quelque vase que ce soit et dans lequel tombera de l’eau de ce vase, seront impurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Toute chose sur laquelle sera tombée l’une de ces bêtes mortes sera impure: si c’est un fourneau ou une marmite, on les purifiera; car ces bêtes sont impures, et elles seront impures pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Toutefois les fontaines, les citernes, les nappes d’eau où elles seront tombées resteront pures; mais celui qui touchera leurs corps morts sera impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'S’il tombe quelque chose de leurs corps morts sur une graine, sur de la semence près d’être ensemencée, cette graine sera pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mais si l’on répand sur n’importe quelle graine, de l’eau où soit tombé l’un de leurs corps morts, cette graine sera impure pour tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'S’il meurt quelqu’un des bestiaux dont vous pouvez manger, celui qui touchera à son cadavre sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Celui qui mangera de ces corps morts, lavera ses vêtements, il sera impur jusqu’au soir; celui qui enlèvera les corps morts lavera ses vêtements, se baignera lui-même, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Tout reptile qui rampe sur la terre sera pour vous abominable; on n’en mangera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Parmi les êtres rampants et se traînant à terre, tout ce qui marche sur son ventre, et tout ce qui marche toujours à quatre pattes, et tout ce qui a beaucoup de pieds est abominable pour vous; n’en mangez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Gardez-vous de rendre abominables vos âmes en usant des reptiles qui se traînent à terre, de vous souiller et de vous rendre impurs à cause d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Car je suis le Seigneur votre Dieu, et vous serez sanctifiés, vous serez saints parce que je suis saint, moi, le Seigneur votre Dieu; et vous ne souillerez pas vos âmes en usant des reptiles qui se meuvent sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Car je suis le Seigneur qui vous ai tirés de la terre d’Égypte, pour être votre Dieu; et vous serez saints parce que je suis saint, moi, le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Telle est la loi concernant les quadrupèdes, les oiseaux, et tout être vivant se mouvant dans l’eau, et tout être vivant qui rampe sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Telle est la séparation entre les purs et les impurs, entre les animaux que l’on peut manger, et ceux dont on ne peut goûter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Parle aux fils d’Israël, et dis-leur: La femme qui aura été fécondée et qui aura enfanté un garçon sera impure pendant sept jours, jours de séparation à cause du flux ordinaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Et le huitième jour, elle circoncira son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Ensuite, pendant trente-trois jours, elle restera en son sang impur; elle ne touchera à rien de saint; elle n’entrera pas dans le sanctuaire jusqu’à ce que les jours de la purification soient accomplis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Si elle a enfanté une fille, elle sera impure deux fois sept jours à cause du flux ordinaire, et pendant soixante-six jours, elle restera dans son sang impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Et lorsque les jours de sa purification seront accomplis, qu’elle ait enfanté un garçon ou une fille, elle offrira au prêtre, en holocauste, devant la porte du tabernacle du témoignage, un agneau sans tache, et pour le péché une petite colombe avec une tourterelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Et le prêtre sacrifiera les hosties au Seigneur; il priera pour elle, et il la purifiera de la fontaine de son sang; telle est la loi pour celle qui aura enfanté un fils ou une fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Si ses facultés sont insuffisantes pour qu’elle donne un agneau, elle prendra deux tourterelles ou deux petits de colombes, qui seront l’un l’holocauste, l’autre la victime du péché; et le prêtre priera pour elle, et elle sera purifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Et le Seigneur parla à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'S’il vient à un homme sur la peau de sa chair une tache luisante, et s’il vient à la peau de sa chair une plaie de lèpre, il sera conduit au prêtre Aaron ou à l’un des prêtres ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Le prêtre examinera la tache sur la peau de sa chair; or, si le poil sur la tache est devenu blanc, si l’aspect de la plaie présente un enfoncement dans la peau de la chair, c’est la plaie de la lèpre; le prêtre la verra et déclarera l’homme impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Mais s’il a sur la peau de sa chair une tache blanche et luisante, si la plaie ne présente pas d’enfoncement dans la peau de sa chair, si le poil n’a pas blanchi, mais reste de couleur foncée, le prêtre séparera la tache sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Et le septième jour, le prêtre observera la tache; s’il voit qu’elle persiste sur la peau et n’a nullement changé, alors, il séparera l’homme sept jours pour la seconde fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Le septième jour, le prêtre visitera l’homme une seconde fois, et s’il voit une tache de couleur foncée qui n’a pas changé de nature sur la peau, alors, il déclarera que l’homme est pur: ce n’est qu’une tache; et ayant lavé ses vêtements, il sera pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mais si sa tache luisante a changé de nature et s’est déplacée sur la peau, après que le prêtre aura visité l’homme pour le déclarer pur; l’homme sera de nouveau visité par le prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Celui-ci l’observera, et voilà que la tache a encore changé de nature sur la peau; alors, il déclarera que l’homme est impur; c’est la lèpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Si un homme a une plaie de lèpre, il ira devant le prêtre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Celui-ci le visitera, et s’il voit qu’une cicatrice blanche paraît sur la peau, si la cicatrice a rendu le poil blanc, et s’il y a de la chair vive dans la trace sur la chair saine,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'C’est une lèpre ancienne sur la peau du corps, et le prêtre déclarera l’homme impur, et il le séparera parce qu’il est impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Si la lèpre fleurit et fleurit sur la peau, si elle couvre toute la peau de l’homme de la tête aux pieds, partout où le prêtre portera les yeux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Le prêtre observera, et voilà que la lèpre a couvert toute la peau du corps; alors, il déclarera l’homme pur quant à la tache, car elle a changé et est devenue blanche; l’homme est pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mais le jour, quel qu’il soit, où sur l’homme apparaîtra de la chair vive, il sera déclaré impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Le prêtre observera la chair vive; et la chair vive fera déclarer l’homme impur; car il est impur: c’est la lèpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mais si la chair vive se cicatrise et redevient blanche, l’homme se présentera au prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Le prêtre observera, et s’il voit que la peau est devenue blanche, il déclarera que la tache est pure; en ce cas l’homme est pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Mais si la chair est ulcérée dans la peau et qu’elle se guérisse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Si, à la place de l’ulcère, il vient une cicatrice blanche, ou luisante et blanchissante, ou tirant sur le rouge, l’homme sera visité par le prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Le prêtre observera, et s’il voit que la plaie a creusé au-dessous de la peau et que les poils sont devenus blancs, il déclarera l’homme impur; c’est la lèpre, elle s’est formée dans l’ulcère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mais si le prêtre ayant fait la visite, il y a des poils blancs en l’ulcère; si l’ulcère n’a pas creusé au-dessous de la peau, s’il est devenu obscur, le prêtre séparera l’homme sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Si l’ulcère s’est étendu et étendu sur la peau, le prêtre déclarera encore l’homme impur; c’est une plaie de lèpre; elle s’est formée dans l’ulcère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Si la tache blanche persiste au même lieu et ne s’étend pas, c’est une cicatrice d’ulcère; le prêtre déclarera que l’homme est pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Si la chair est vivement enflammée dans la peau; si, dans la part guérie de l’inflammation, il reste à la peau une tache luisante, blanche ou rougeâtre, ou très blanche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Le prêtre observera l’homme, et s’il voit que dans la tache luisante le poil devient blanc et que son aspect présente un enfoncement dans la peau; c’est une lèpre, elle s’est formée dans l’inflammation; et le prêtre déclarera l’homme impur; c’est une plaie de lèpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mais si, lorsque le prêtre aura observé, il ne voit point de poil blanc dans la tache luisante, si elle n’a point fait d’enfoncement au-dessous de la peau, si elle est de couleur obscure, il séparera l’homme pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Et le septième il le visitera; si la trace s’est étendue et étendue sur la peau, il le déclarera impur; c’est une plaie de lèpre, elle s’est formée dans l’inflammation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Mais si la tache luisante persiste à la même place et ne s’est pas étendue sur la peau, si elle est de couleur sombre, c’est une cicatrice de l’inflammation, et le prêtre déclarera l’homme pur, car c’est la marque de l’inflammation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Si un homme ou une femme a une plaie de lèpre dans la barbe ou dans les cheveux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Le prêtre visitera la plaie, et s’il voit qu’elle présente un enfoncement au-dessous de la peau et que le poil est devenu blond et grêle, il déclarera la personne impure; c’est une teigne, une lèpre de la tête ou une lèpre de la barbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Mais lorsque le prêtre aura visité la plaie de la teigne, s’il n’y a pas apparence d’enfoncement au-dessous de la peau, s’il ne voit pas de poils blonds, il séparera la plaie pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Le septième, il la visitera, et si elle ne s’est point étendue, s’il n’y a pas en elle de poils blonds, si elle ne présente pas l’aspect d’un enfoncement dans la peau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Il rasera la peau et ne rasera pas la teigne, et une seconde fois il séparera la plaie pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Le septième jour, le prêtre visitera la teigne; s’il voit qu’elle ne s’est point étendue sur la peau après que la personne aura été rasée, qu’elle ne présente point l’aspect d’un enfoncement au-dessous de la peau, le prêtre déclarera la personne pure; elle lavera ses vêtements et sera pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mais si la teigne s’est étendue sur la peau après que la personne aura été déclarée pure,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Le prêtre la visitera encore, et s’il voit que la teigne s’est étendue sur la peau, le prêtre n’examinera pas si le poil est devenu blond; la personne est impure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mais si, à ses yeux, la teigne reste à la même place, s’il y pousse des poils noirs, la teigne est guérie, la personne est pure; le prêtre la déclarera pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Si un homme ou une femme présente à la peau des taches blanches et luisantes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Le prêtre observera, et s’il voit que sur la peau il y a des taches blanches et luisantes; c’est une dartre farineuse qui s’est produite à la peau; la personne est pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Si un homme perd ses cheveux, il est chauve, il est pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'S’il perd les cheveux de devant la tête, il est chauve sur le front, il est pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Si, soit au sommet chauve de la tête, soit au front chauve, survient une plaie blanche ou rouge, l’homme a la lèpre, au sommet de la tête ou au front.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Le prêtre le visitera, et s’il voit qu’il y a une plaie blanche ou rouge au sommet de la tête ou du front, ressemblant à la lèpre ordinaire sur la chair,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'L’homme est lépreux; le prêtre le déclarera impur; la plaie est sur la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Que les vêtements du lépreux soient dénoués, qu’on lui découvre la tête, qu’on lui enveloppe la bouche, et il sera appelé impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Il restera impur, tous les jours durant lesquels la plaie sera sur lui; il demeurera à part, son séjour sera hors du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'S’il survient une tache de lèpre à un vêtement de laine ou de lin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Ou à la chaîne, ou à la trame, ou aux fils du lin, ou aux fils de la laine, ou à un cuir, ou à tout ouvrage en cuir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Si la tache devient verdâtre ou couleur de rouille sur le cuir, sur le vêtement, sur la chaîne, sur la trame, sur tout ouvrage en cuir, c’est une tache de lèpre; on la montrera au prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Le prêtre verra la tache, et pendant sept jours il la séparera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Le septième jour, le prêtre visitera la tache, et si elle s’est étendue sur le vêtement, sur la chaîne, sur la trame, sur la peau travaillée n’importe comment, la tache est une lèpre persistante; l’objet est impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Le prêtre brûlera le vêtement, ou la chaîne, ou la trame, qu’elle soit de laine ou de lin; il brûlera la peau travaillée qui sera tachée, car c’est une lèpre persistante; l’objet sera consumé par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Mais lorsque le prêtre l’aura visité, si la tache ne s’est étendue ni sur le vêtement, ni sur la chaîne, ni sur la trame, ni sur l’ouvrage en cuir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Le prêtre donnera ses ordres: l’homme lavera devant lui la tache, et le prêtre séparera encore la tache pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Et le prêtre verra la tache, après qu’elle aura été lavée; si elle n’a pas changé d’apparence, quoiqu’elle ne se soit pas étendue, l’objet est impur, il sera consumé par le feu, puisque la tache a persisté sur le vêtement, ou sur la chaîne, ou sur la trame.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Si, après le lavage, le prêtre voit que la tache a pris une teinte sombre, il déchirera cette part du vêtement, de la chaîne, de la trame, ou du cuir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Et si la tache reparaît sur le vêtement, sur la chaîne, sur la trame ou sur l’ouvrage en cuir, c’est une lèpre qui se montre; on consumera par le feu ce qui est taché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Et le vêtement, ou la chaîne, ou la trame, ou l’ ouvrage en cuir, qui aura été lavé et dont la tache aura disparu, sera lavé derechef et sera pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Telle est la loi des taches de lèpre sur les vêtements de laine ou de lin, sur les chaînes et les trames, sur les peaux travaillées; c’est ainsi qu’on les déclarera purs ou impurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Voici la loi du lépreux: le jour où il sera purifié on le conduira au prêtre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Celui-ci sortira du camp et l’inspectera; s’il voit que la tache de lèpre est guérie sur le lépreux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Il donnera ses ordres, et l’on prendra pour le purifié deux petits oiseaux purs et vivants, ainsi que du bois de cèdre, de l’écarlate filé et de l’hysope.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Le prêtre donnera ses ordres, et l’on égorgera l’un des oiseaux, dans un vase de terre, sur de l’eau vive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Le prêtre prendra l’oiseau vivant, avec le bois de cèdre, l’écarlate filé et l’hysope, et il les trempera dans le sang de l’oiseau égorgé sur de l’eau vive;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Il aspergera sept fois le purifié, et celui-ci sera pur; puis il laissera l’oiseau vivant s’envoler dans la campagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Le purifié lavera ensuite ses vêtements, et on lui rasera tout le corps; on le lavera avec de l’eau, et il sera pur; après cela, il entrera dans le camp et demeurera sept jours hors de sa maison. `');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Le septième jour, on lui rasera la tête, le menton, les sourcils, et tout le corps; il lavera ses vêtements, et il se lavera le corps avec de l’eau, et il sera pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Le huitième jour, il prendra deux agneaux d’un an sans tache, et une brebis d’un an sans tache, pour le sacrifice, ainsi que trois dixièmes d’éphi de fleur de farine pétrie dans l’huile, et une mesure d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Le prêtre qui purifiera l’homme, le placera avec les offrandes, en présence du Seigneur, devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Puis, il prendra l’un des deux agneaux, et il l’offrira pour le délit, en même temps que la mesure d’huile, et il les mettra à part devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'On égorgera l’agneau dans le lieu où l’on immole les holocaustes et les victimes pour le péché, dans le lieu saint. Car la victime pour le péché est comme celle pour le délit; elle appartient au prêtre, c’est chose très-sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Le prêtre prendra du sang de la victime pour le délit, et il en mettra sur l’oreille droite du purifié et sur l’extrémité de sa main droite, et sur l’extrémité de son pied droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Ensuite le prêtre, ayant pris la mesure d’huile, en versera dans sa main gauche;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Il trempera le doigt de la main droite dans l’huile de la main gauche, et il fera sept aspersions devant le Seigneur. Quant à l’huile restée dans sa main gauche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Il en mettra sur le lobe de l’oreille droite du purifié, et sur l’extrémité de sa main droite, et sur l’extrémité de son pied droit, comme il a mis du sang de la victime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Puis, il répandra le reste de l’huile qu’il aura dans. la main sur la tête du purifié, et il priera pour lui devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Après cela, le prêtre fera le sacrifice pour le');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Il portera l’holocauste et le sacrifice sur l’autel devant le Seigneur; et il priera pour l’homme, et celui-ci sera purifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Si l’homme est pauvre, si ses facultés sont insuffisantes pour qu’il apporte ces choses, il prendra comme offrande un seul agneau pour le délit, afin de se rendre Dieu propice, et il présentera un dixième d’éphi de fleur de farine pétrie dans l’huile, en sacrifice, et une mesure d’huile,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Et deux tourterelles ou deux petits de colombes, selon ce que lui permettront ses facultés, l’un pour le péché, l’autre pour l’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Le huitième jour, pour être purifié, il portera ces offrandes au prêtre devant la porte du tabernacle du témoignage, en présence du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Et le prêtre, ayant pris l’agneau du délit et la mesure d’huile, les placera, comme offrande, devant le Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Il égorgera l’agneau du délit, il prendra du sang de la victime et il en mettra sur le lobe de l’oreille droite du purifié, sur l’extrémité de sa main droite et sur l’extrémité de son pied droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Ensuite, le prêtre se versera de l’huile dans la main gauche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Et avec le doigt de la main droite, il fera, devant le Seigneur, sept aspersions de l’huile de sa main gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Et le prêtre mettra de l’huile de sa main gauche sur le lobe de l’oreille droite du purifié, sur l’extrémité de sa main droite et sur l’extrémité de son pied droit, à la même place qu’il a mis le sang de la victime pour le délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Ce qui restera d’huile dans la main gauche du prêtre, il le répandra sur la tête du purifié, et le prêtre priera pour le purifié devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Il sacrifiera les tourterelles ou jeunes colombes, selon ce que les facultés du purifié lui auront permis d’apporter,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'L’une pour le péché, l’autre pour l’holocauste avec le sacrifice, et le prêtre priera pour le purifié devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Telle est la règle pour la tache de lèpre et pour celui qui ne peut présenter toutes les offrandes de la purification.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Le Seigneur parla encore à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Lorsque vous serez entrés en la terre de Chanaan que je vous donne pour héritage, et que je ferai paraître la tache de lèpre sur les maisons de la terre qui vous appartiendra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Le maître de la maison ira l’annoncer au prêtre, disant Il se montre comme une tache dans ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Et le prêtre ordonnera que l’on démeuble la maison, avant qu’il y entre pour voir la tache, de peur que les meubles de la maison ne deviennent tous impurs; cela fait, il entrera pour visiter la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Puis, il observera la tache, et s’il voit des cavités verdâtres ou rousses qui s’enfoncent dans les murs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Il sortira, et, se tenant sur la porte, il séparera la maison pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Le septième jour, le prêtre reviendra, et il examinera la maison, et s’il voit que la tache s’est étendue sur les murs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Il donnera ses ordres, et l’on enlèvera les pierres sur lesquelles est la tache, et on les jettera hors de la ville, en lieu impur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Ensuite, on raclera l’intérieur de la maison tout alentour, et la poussière enlevée sera jetée hors de la ville, en lieu impur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'On prendra d’autres pierres grattées que l’on mettra à la place de celles que l’on aura ôtées, et l’on prendra un autre enduit avec lequel la maison sera recrépie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Si la tache revient dans la maison, après qu’on en aura enlevé les pierres, raclé et recrépi les murs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Le prêtre entrera encore et observera: si la tache s’est étendue dans la maison, c’est une lèpre persistante dans la maison; la maison est impure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Alors, on démolira la maison, et l’on portera hors de la ville, en lieu impur, ses bois, ses pierres et tous les décombres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Celui qui sera entré dans la maison, durant l’un des jours où elle aura été séparée, sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Celui qui aura couché dans la maison lavera ses vêtements et sera impur jusqu’au soir; celui enfin qui aura mangé dans la maison lavera ses vêtements et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mais si le prêtre entre et examine, s’il voit que la tache ne s’est pas étendue dans la maison, après qu’on l’a recrépie, il purifiera la maison; la tache est effacée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Et il prendra, pour purifier la maison, deux oiseaux purs vivants, et du bois de cèdre, et de l’écarlate filé, et de l’hysope.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Il égorgera l’un des oiseaux, dans un vase de terre, sur de l’eau vive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Puis, il prendra le bois de cèdre, l’écarlate filé, l’hysope et l’oiseau vivant, et il les trempera dans le sang de l’oiseau égorgé sur de l’eau vive, et il fera dans la maison sept aspersions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Il purifiera ainsi la maison par le sang de l’oiseau égorgé, et avec l’eau vive, l’oiseau vivant, le bois de cèdre, l’hysope et l’écarlate filé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Après quoi, il lâchera l’oiseau vivant hors de la ville dans la campagne; il priera pour la maison, et elle sera pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Telle est la loi pour toute tache de lèpre, toute plaie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Pour la lèpre de vêtements et de maisons,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Pour la lèpre provenant de cicatrices, de pustules et de taches luisantes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Et pour la notification du jour où l’on est impur et de celui où l’on est purifié: telle est la loi de la lèpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Le Seigneur parla à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Parlez aux fils d’Israël, dites-leur: S’il survient à un homme un écoulement du corps, cet écoulement est impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Voici la règle de son impureté: S’il s’écoule de son corps de cette semence par laquelle son corps a été formé, il y a impureté en lui. Tous les jours durant lesquels s’écoule de son corps ce liquide dont son corps a été formé, son impureté subsiste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Tout lit sur lequel aura dormi l’homme atteint de la gonorrhée est impur; tout siège où il se sera assis est');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'L’homme qui aura touché sa couche lavera ses vêtements, se lavera lui-même avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Celui qui se sera assis sur le siège où s’est assis l’homme atteint de la gonorrhée, lavera ses vêtements, se lavera lui-même avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Celui qui aura touché la chair de l’homme atteint de la gonorrhée, lavera ses vêtements, se lavera lui-même avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Si l’homme atteint de la gonorrhée a craché sur un autre homme, celui-ci lavera ses vêtements, se lavera lui-même avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Toute garniture du bât de l’âne sur lequel sera monté l’homme atteint de la gonorrhée, sera impure jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Quiconque touchera quoi que ce soit de ce qui aura été alors sous lui, sera impur jusqu’au soir; celui qui enlèvera les harnais lavera ses vêtements, se lavera lui-même avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Celui qui aura seulement touché l’homme atteint de la gonorrhée, et ne se sera pas lavé les mains, lavera ses vêtements, se lavera les mains avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Le vase de terre qu’aura touché l’homme atteint de la gonorrhée sera brisé; le vase de bois sera lavé avec de l’eau et redeviendra pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Si l’homme atteint de la gonorrhée est purifié de son écoulement, il comptera lui-même pour sa purification sept jours, après lesquels il lavera ses vêtements et son corps avec de l’eau, et il sera pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Le même jour, il prendra deux tourterelles ou deux petits de colombes, et il les portera, en présence du Seigneur, devant la porte du tabernacle du témoignage; il les donnera au prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Et le prêtre les sacrifiera l’un pour le péché, l’autre pour l’holocauste; le prêtre priera pour l’homme devant le Seigneur, pour l’expiation de son écoulement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'L’homme qui aura eu une pollution nocturne se lavera tout le corps avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Le vêtement ou la peau, tachés par la pollution, seront lavés avec de l’eau, et seront impurs jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Si une femme est couchée avec un homme et qu’il l’ait polluée, ils se laveront tous les deux avec de l’eau, et seront impurs jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'La femme qui perd du sang et a un écoulement de son corps, restera sept jours dans son flux menstruel; quiconque la touchera sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Toute chose sur laquelle elle se sera couchée pendant ses menstrues, toute chose sur laquelle elle se sera assise sera impure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Quiconque touchera sa couche lavera ses vêtements, se lavera le corps avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Quiconque aura touché un meuble sur lequel elle se sera assise, lavera ses vêtements, se lavera lui-même avec de l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Celui qui la touchera, qu’elle soit au lit ou assise sur un meuble, sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Si quelqu’un couche avec elle, l’impureté qu’elle a passera sur lui, il sera impur sept jours; la couche sur laquelle il aura dormi avec elle sera impure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Si une femme perd du sang plusieurs jours, hors de l’époque menstruelle, et si après cette époque l’écoulement continue, elle sera impure tant que durera cet écoulement impur, comme pendant son flux menstruel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Et toute couche sur laquelle elle aura dormi, pendant cet écoulement, sera comme sa couche lors de son flux menstruel, et tout meuble sur lequel elle se sera assise aura la même impureté que pendant son flux menstruel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Quiconque l’aura touchée sera impur; il lavera ses vêtements et son corps avec de l’eau, et il sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Mais si elle redevient pure de son écoulement, il lui sera encore compté sept jours, au bout desquels elle sera déclarée pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Et le huitième jour, elle prendra deux tourterelles ou deux petits de colombes qu’elle portera au prêtré devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Le prêtre les sacrifiera, l’un pour le péché, l’autre pour l’holocauste, et le prêtre priera pour elle devant le Seigneur, en expiation de son flux impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Ainsi vous apprendrez aux fils d’Israël à se garder de leurs impuretés, et ils ne mourront pas à cause de leurs impuretés, pour avoir souillé par elles mon tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Telle est la loi de l’homme atteint de la gonorrhée, de celui à qui survient une pollution qui le rend impur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'De la femme qui perd le sang du flux menstruel, et de l’homme atteint de la gonorrhée ou d’un écoulement; c’est une loi pour l’homme et la femme, et pour l’homme qui aurait commerce avec une femme pendant ses menstrues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Après que les deux fils d’Aaron eurent expiré pendant qu’ils offraient au Seigneur un feu étranger, le Seigneur parla à Moïse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Et lui dit: Fais savoir à Aaron ton frère qu’il ne doit point entrer à toute heure dans le Saint des saints, à l’intérieur du voile du sanctuaire, devant le propitiatoire qui est sur l’arche du témoignage, afin qu’il ne meure pas; car j’apparaîtrai dans une nuée au-dessus du propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Aaron entrera dans le sanctuaire de la manière suivante: il amènera un veau, pris parmi les bœufs, pour le péché, et un bélier pour l’holocauste;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Il revêtira la tunique de lin sanctifiée, il aura sur la chair un caleçon de lin, il ceindra une ceinture de lin, et il posera sur sa tête une tiare aussi de lin; ce sont les vêtements saints dont il se revêtira après s’être lavé tout le corps avec de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Et il se fera donner, par la synagogue des fils d’Israël, deux jeunes boucs, pris parmi les chèvres, pour le péché, et un bélier pour l’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Aaron fera, pour son propre péché, l’offrande du veau, et il priera pour lui-même et pour toute sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Puis, il prendra les deux boucs et les placera en présence du Seigneur, devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Et Aaron jettera sur les deux boucs deux sorts: un sort pour le bouc du Seigneur, un sort pour le bouc émissaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Ensuite, Aaron amènera le bouc que le sort aura désigné pour le Seigneur, et il l’offrira pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Quant au bouc sur qui sera tombé le sort de l’émissaire, il le placera vivant devant le Seigneur, pour prier sur lui et le chasser comme émissaire, et il l’enverra dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Après cela, Aaron fera approcher le veau offert pour son propre péché, il priera pour lui-même et pour sa maison, et il égorgera le veau pour son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Il prendra aussi l’encensoir, garni de charbons du feu de l’autel placé devant le Seigneur, il remplira ses mains de l’encens habilement composé, et il le portera au delà du voile intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Et il mettra l’encens sur le feu devant le Seigneur, et la vapeur de l’encens enveloppera le propitiatoire qui est sur l’arche du témoignage; ainsi Aaron ne mourra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Il prendra du sang du veau, et il aspergera du doigt le propitiatoire du côté de l’orient; il fera ainsi avec le doigt sept aspersions de sang devant le propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Puis, il égorgera le bouc pour le péché, celui qui est pour le peuple devant le Seigneur; il portera de son sang à l’intérieur du voile, et en fera, comme avec le sang du veau, des aspersions devant le propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Et il purifiera le saint de toutes les impuretés des fils d’Israël, de tous leurs péchés et iniquités. Ainsi fera-t-il pour le tabernacle du témoignage, élevé parmi eux, au milieu de leur impureté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Nul homme ne demeurera dans le tabernacle du témoignage, à partir du moment où il y sera entré pour prier dans le saint, jusqu’à ce qu’il en sorte. Et il priera pour lui et pour sa maison, et pour toute la synagogue des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Ensuite, il reviendra vers l’autel qui est devant le Seigneur, il priera sur lui, et il prendra du sang du veau et du bouc, et il en mettra sur les cornes de l’autel, tout autour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Puis, il fera du doigt sept aspersions de sang sur l’autel, et il purifiera l’autel des impuretés du peuple et le sanctifiera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Il achèvera ainsi la purification du sanctuaire du tabernacle du témoignage et de l’autel, et celle des prêtres; après cela, il fera approcher le bouc vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Aaron imposera les mains sur sa tête, il confessera sur lui tous les dérèglements des fils d’Israël, toutes leurs iniquités, tous leurs péchés; il les mettra sur la tête du bouc vivant, et il le chassera, à l’aide d’un homme préparé pour cette fin, jusque dans le désert;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Et le bouc emportera sur lui dans la terre sans chemins tous les péchés d’Israël. Aaron chassera le bouc dans le désert;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Après quoi, il entrera dans le tabernacle du témoignage, il ôtera la robe de lin qu’il aura revêtue pour entrer dans le sanctuaire, et il l’y déposera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Il lavera son corps avec de l’eau en lieu saint; il revêtira sa robe, puis étant sorti, il brûlera son holocauste et celui du peuple, et il priera pour lui-même et pour sa maison, pour le peuple et pour les prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Il portera sur l’autel la graisse des victimes pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'L’homme qui aura emmené le bouc émissaire lavera aussi ses vêtements et son corps avec de l’eau, et il rentrera dans le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Quant au veau et au bouc qui sont pour le péché et dont le sang a été introduit pour intercéder dans le sanctuaire, on les portera hors du camp et on les consumera par le feu avec leurs peaux, leurs chairs et leur fiente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Celui qui les aura brûlés lavera ses vêtements et son corps avec de l’eau, et il rentrera dans le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Voici encore pour vous une loi perpétuelle: dans la septième lune, le dixième jour de la lune, vous humilierez vos âmes; vous ne ferez aucune œuvre, ni l’indigène, ni le prosélyte venu parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Car, en ce jour-là, on priera pour vous afin de vous purifier de tous vos péchés, devant le Seigneur, et vous serez purifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ce repos sera le sabbat pour vous, et vous humilierez vos âmes: c’est une loi perpétuelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Le prêtre qui aura reçu l’onction, et dont les mains auront été consacrées pour exercer le sacerdoce après son père, priera, et il revêtira la robe de lin, la robe sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Il purifiera le Saint des saints, le tabernacle du témoignage, l’autel, ainsi que les prêtres et toute la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Et ce sera pour vous une loi perpétuelle de purifier les fils d’Israël de tous leurs péchés une fois par an; on le fera comme le Seigneur l’a ordonné à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Parle à Aaron et à ses fils et à tous les fils d’Israël; dis-leur Voici la loi qu’a prescrite le Seigneur, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Tout homme, soit des fils d’Israël, soit des prosélytes demeurant parmi vous, qui sacrifiera dans le camp où hors du camp, veau, brebis ou chèvre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Et ne l’amènera point devant la porte du tabernacle du témoignage pour l’offrir en holocauste ou en hostie pacifique, hostie acceptable et de suave odeur pour le Seigneur, mais qui l’immolera dehors, sans l’offrir devant la porte du tabernacle du témoignage pour en faire don au Seigneur, ce sang sera imputé à cet homme; il a versé le sang. Cette âme sera exterminée du milieu de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Afin que les fils d’Israël offrent en sacrifice tout ce qu’ils tueront aux champs, et qu’ils l’apportent pour le Seigneur, au prêtre, devant la porte du tabernacle. du témoignage, et qu’ils le sacrifient en hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Le prêtre répandra le sang autour de l’autel, en présence du Seigneur, devant la porte du tabernacle du témoignage, et il offrira la graisse en odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Et ils ne sacrifieront plus de victime aux vaines idoles auxquelles ils se prostituent; c’est une loi perpétuelle pour toutes vos générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Dis-leur encore: Tout homme, soit des fils d’Israël, soit des fils de prosélytes demeurant parmi vous, qui offrira un holocauste ou tout autre sacrifice,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Et ne l’amènera point devant la porte du tabernacle du témoignage pour l’offrir au Seigneur, sera exterminé parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Si un homme quelconque, soit des fils d’Israël, soit des prosélytes demeurant parmi vous, mange du sang, je tournerai ma face contre cette âme qui aura mangé du sang, et je l’exterminerai parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Car la vie de toute chair, c’est son sang, et je vous ai donné le sang pour intercéder sur l’autel en faveur de vos âmes, car le sang intercède pour l’âme de celui qui l’offre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'C’est pourquoi j’ai dit aux fils d’Israël: Nulle âme');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Tout homme donc, soit des fils d’Israël, soit des prosélytes demeurant parmi vous, qui aura pris à la chasse quelque bête fauve ou oiseau qui se mange, en répandra le sang et le couvrira de terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Car la vie de toute chair est dans son sang, et j’ai dit aux fils d’Israël: Vous ne mangerez le sang d’aucune chair, parce que la vie de toute chair est dans son sang; quiconque en mangera sera exterminé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Toute âme qui, soit parmi les indigènes, soit parmi les prosélytes, aura mangé de la chair morte ou d’une proie enlevée par une bête fauve, lavera ses vêtements, se lavera avec de l’eau et sera impure jusqu’au soir; après quoi, on la déclarera pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Mais, si elle ne lave pas ses vêtements, si elle ne lave pas son corps avec de l’eau, elle portera son iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Parle aux fils d’Israël, dis-leur: Je suis le Seigneur votre Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Vous ne vous conduirez pas selon les mœurs de l’Égypte, où vous avez demeuré; vous ne vous conduirez pas selon les mœurs de la terre de Chanaan, où je vous mène; vous ne marcherez point suivant leurs lois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Vous exécuterez mes jugements, vous observerez mes préceptes, et vous marcherez selon ce qu’ils prescrivent je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Vous garderez tous mes préceptes et tous mes jugements, et vous les exécuterez. L’homme qui les exécutera vivra par eux: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nul homme ne s’approchera d’une parente de sa chair, pour mettre à découvert sa nudité: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Tu ne mettras pas à découvert la nudité de ton père ni de ta mère; c’est ta mère, tu ne mettras pas à découvert sa nudité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Tu ne mettras pas à découvert la nudité de ta belle-mère; c’est la nudité de ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Tu ne mettras pas à découvert la nudité de ta sœur consanguine ou utérine, née à la maison ou dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Tu ne mettras pas à découvert la nudité de la fille de ton fils, ni de la fille de ta fille; c’est ta propre nudité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Tu ne mettras pas à découvert la nudité de la fille de ta belle mère; elle est comme ta sœur consanguine, tu ne mettras pas à découvert sa nudité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Tu ne mettras pas à découvert la nudité de la sœur de ton père; elle est des proches de ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Tu ne mettras pas à découvert la nudité de la sœur de ta mère; elle est des proches de ta mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Tu ne mettras pas à découvert la nudité du frère de ton père, et tu n’auras pas commerce avec sa femme; car vous êtes proches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Tu ne mettras pas à découvert la nudité de ta bru; c’est la femme de ton fils, tu ne mettras pas à découvert sa nudité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Tu ne mettras pas à découvert la nudité de la femme de ton frère; c’est la nudité de ton frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Tu ne mettras pas à découvert la nudité de cette femme ni de sa fille; tu ne prendras pas la fille de son fils, ni la fille de sa fille, pour mettre sa nudité à découvert; elles sont tes proches, et ce serait une impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Tu ne donneras pas à ta femme, encore vivante, sa sœur pour rivale, et tu ne mettras pas à découvert la nudité de celle-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Tu ne t’approcheras pas de la femme pour mettre sa nudité à découvert, quand elle est assise à part à cause de son impureté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Tu n’auras pas commerce avec la femme de ton prochain, pour te souiller avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Tu ne donneras pas de tes enfants pour qu’ils servent Moloch, et tu ne souilleras pas mon nom saint: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Tu n’auras pas commerce avec un autre homme, comme avec une femme, car c’est une abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Tu n’auras pas commerce avec un quadrupède, pour te souiller avec lui; nulle femme n’aura commerce avec un quadrupède, car c’est une abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ne vous souillez d’aucune de ces choses; car toutes les nations que je vais chasser devant vous en sont souillées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'La terre en est souillée, et c’est à cause de leur iniquité que je les punis; la terre s’est soulevée d’horreur contre ceux qui l’habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Vous observerez toutes mes lois, tous mes préceptes, et vous ne commettrez aucune de ces abominations, pas plus l’indigène que le prosélyte établi parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Car ce sont toutes les abominations qu’ont commises les hommes de cette terre qui vous ont précédés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'De peur que la terre ne se soulève d’horreur contre vous, parce que vous la souilleriez; elle s’est soulevée contre les nations qui vous précèdent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'C’est pourquoi quiconque commettra quelqu’une de ces abominations, sera exterminé parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Vous observerez mes préceptes, afin que vous ne suiviez en rien toutes ces coutumes abominables qui ont existé avant vous, et que vous n’en soyez point souillés; car je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Parle à toute la synagogue des fils d’Israël, dis-lui: Soyez saints, parce que je suis saint, moi, le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Que chacun craigne son père et sa mère; observez mes sabbats: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Vous ne vous attacherez point aux idoles, vous ne vous ferez pas des dieux de métal fondų: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Lorsque vous offrirez au Seigneur une hostie pacifique, c’est de votre meilleur que vous sacrifierez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'L’hostie sera mangée le jour où vous l’offrirez et le lendemain; s’il en reste le troisième jour, consumez-le par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Si l’on en mange le troisième jour, le sacrifice est nul et ne sera pas accepté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Celui qui en mangera se rendra coupable de péché, parce qu’il aura profané les choses saintes du Seigneur; et les âmes qui en auront mangé, seront exterminées parmi le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Lorsque vous moissonnerez en votre terre, vous n’achèverez pas strictement votre moisson, vous ne recueillerez point les épis tombés çà et là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Vous ne revendangerez point vos vignes, vous ne recueillerez pas les grains tombés, vous les laisserez pour le pauvre et pour l’étranger: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Vous ne volerez point, vous ne mentirez point, nul ne calomniera son prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Vous ne jurerez pas injustement par mon nom, vous ne souillerez pas le nom saint du Seigneur votre Dieu je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Tu ne feras point tort à ton prochain, tu ne voleras point; le salaire du journalier ne demeurera pas chez toi jusqu’au lendemain matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Tu ne maudiras point le sourd et ne mettras point de pierre d’achoppement devant l’aveugle, et tu craindras le Seigneur ton Dieu: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Vous ne commettrez point d’injustice dans le jugement; tu ne feras point acception de personne en faveur du mendiant; tu ne craindras pas la face du puissant; tu jugeras ton prochain selon la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Tu ne marcheras point dans la ruse au milieu de ton peuple; tu ne machineras point contre le sang de ton prochain je suis le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Tu ne haïras point ton frère au fond du cœur; tu réprimanderas ton prochain, et tu ne te rendras point, cause de lui, coupable de péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Ta main n’exercera pas la vengeance; tu ne t’irriteras point contre les enfants de ton peuple; tu aimeras ton prochain comme toi-même: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Vous observerez ma loi; tu ne feras pas saillir tes bêtes par des bestiaux d’une autre espèce; tu ne sèmeras pas diverses graines dans ta vigne; tu ne porteras pas de vêtements tissus de deux fils disparates.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Si un homme a commerce avec une femme, et que cette femme soit une servante réservée à un homme; si elle n’est ni rachetée ni affranchie, ils seront visités et punis; mais ils ne seront point mis à mort, parce que la femme n’a pas été affranchie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'L’homme amènera au Seigneur, pour son délit, un bélier devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Et le prêtre priera devant le Seigneur en sacrifiant le bélier du péché, pour le péché que l’homme a commis, et son péché lui sera remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Lorsque vous serez entrés en la terre que le Seigneur votre Dieu vous donne, et que vous y aurez planté toutes sortes d’arbres fruitiers, et que vous les aurez émondés tout autour, leurs fruits pendant trois ans seront impurs pour vous; on ne les mangera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Et, en la quatrième année, tous les fruits seront saints; ils seront fruits d’actions de grâces et appartiendront au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Et, en la cinquième année, vous mangerez des fruits; tout ce que l’arbre produira sera à vous: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Vous ne mangerez pas sur les hauts lieux; vous n’userez ni des augures ni des auspices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Vous ne couperez pas en rond votre chevelure, vous laisserez votre barbe croître naturellement sous le menton.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Vous ne ferez point d’incisions sur votre corps à l’occasion d’un mort, vous ne pointillerez point de caractères sur votre peau: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Tu ne profaneras point ta fille par la prostitution, et la terre ne sera point souillée, autrement elle serait remplie de déréglements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Vous observerez mes sabbats, vous révèrerez mon sanctuaire: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Vous ne suivrez ni ventriloques ni enchanteurs, vous seriez souillés par eux: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Tu te lèveras devant les cheveux blancs, tu honoreras le vieillard, et tu craindras ton Dieu: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Si quelque étranger vient s’établir dans votre terre, vous ne l’opprimerez point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'L’étranger qui viendra parmi vous sera comme un indigène; et tu l’aimeras comme toi-même, car tu as été étranger en la terre d’Égypte: je suis le Seigneur votre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Tu ne feras pas d’injustice dans tes jugements, dans tes mesures, tes poids et tes balances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Vous aurez des balances et des poids justes, et d’équitables mesures: je suis le Seigneur votre Dieu qui vous ai tirés de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Et vous observerez toutes mes lois et tous mes préceptes, vous les exécuterez: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Dis encore aux fils d’Israël: Si quelqu’un du peuple ou de ceux qui ont été faits prosélytes livre de ses enfants à Moloch, qu’il meure de mort, que les habitants de la terre le lapident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Pour moi, je tournerai ma face contre cet homme, je l’exterminerai parmi son peuple, parce qu’il aura donné de ses enfants à Moloch, profané mes choses saintes, et souillé le nom des choses qui me sont consacrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Si les fils d’Israël, habitant la terre, détournent leurs yeux de cet homme, pendant qu’il livre de ses enfants à Moloch, afin de ne pas le mettre à mort,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Je tournerai ma face contre cet homme et contre sa parenté; je le détruirai avec tous ceux qui auront consenti à ce qu’il se prostitue aux princes; je les exterminerai parmi leur peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'L’âme qui suivra les ventriloques et les enchanteurs pour se prostituer après eux, je tournerai contre elle ma face, et je la détruirai parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Vous serez saints, parce que je suis saint, moi le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Vous observerez mes préceptes et vous les mettrez en pratique; je suis le Seigneur qui vous sanctifie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Quiconque profèrera une malédiction contre son père ou sa mère, qu’il meure de mort. A-t-il maudit son père ou sa mère, il est coupable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Si un homme commet un adultère avec la femme d’autrui, avec la femme de son voisin, que l’on mette à mort l’homme et la femme adultères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Si un homme dort avec la femme de son père, s’il a mis à découvert la nudité de son père, que l’homme et la femme meurent de mort; ils sont coupables tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Si un homme dort avec sa bru, que l’un et l’autre meurent de mort; ils ont commis une impiété; ils sont coupables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Si un homme a commerce avec un autre homme comme avec une femme, qu’ils meurent de mort tous les deux; ils ont commis une abomination; ils sont coupables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Si un homme prend pour femmes la fille et la mère de celle-ci, il a commis une abomination; qu’on le brûle vif avec les deux femmes, et l’iniquité ne sera point au milieu de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Si un homme a commerce avec un quadrupède, qu’il meure de mort; tuez aussi la bête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Si une femme se fait approcher par un');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Si un homme prend sa sœur consanguine ou utérine, s’il voit sa honte et si elle voit la sienne, ils sont coupables; ils seront exterminés en présence des membres de leur famille. L’homme a mis à découvert la nudité de sa sœur; ils porteront leur péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Si un homme a commerce avec une femme pendant ses menstrues, et qu’il ait mis sa nudité à découvert, ils seront tous les deux exterminés du sein de leur famille: lui, pour avoir dévoilé la fontaine; elle, pour avoir montré le flux de son sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Tu ne mettras pas à découvert la nudité de ta sœur utérine et consanguine; car ceux qui mettent à nu leur parenté porteront leur péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Si quelqu’un a commerce avec une de ses parentes, et met à découvert la nudité de sa parenté, ils mourront l’un et l’autre sans enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Si quelqu’un prend la femme de son frère, c’est une impureté, il a mis à découvert la nudité de son frère; lui et cette femme mourront sans enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Vous observerez tous mes préceptes et mes jugements, vous les mettrez en pratique; et la terre en laquelle je vous conduis pour que vous l’habitiez, ne se soulèvera pas contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Vous ne marcherez point selon les lois des nations que je vais chasser devant vous, car elles ont fait toutes ces choses, et je les ai prises en abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Et je vous ai dit: Vous aurez leur terre pour héritage, je vous la donnerai en possession cette terre où coulent le miel et le lait: je suis le Seigneur votre Dieu qui vous ai séparés de toutes les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Et vous vous séparerez vous-mêmes, distinguant S’ils ont commerce ensemble. entre les bêtes pures et les bêtes impures, les oiseaux purs et les oiseaux impurs, et vous ne souillerez point vos âmes avec les bestiaux, les oiseaux ou les reptiles que je vous ai désignés comme impurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Et vous serez saints pour moi, parce que je suis saint, moi, le Seigneur votre Dieu, qui vous ai séparés de toutes les nations pour être à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Tout homme ou toute femme qui sera ventriloque ou enchanteur, mourra de mort; ils seront tous deux lapidés; ils sont coupables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Et le Seigneur parla à Moïse, disant: Parle aux prêtres, fils d’Aaron, et dis-leur: Qu’ils ne se souillent point auprès des morts de votre nation,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Si ce n’est à la mort du parent le plus proche: d’un père, d’une mère, d’un fils ou d’une fille,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'D’une sœur vierge qui n’a point encore été donnée à un homme; pour ceux-là, le prêtre pourra contracter une souillure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Il ne contractera pas soudainement de souillure au milieu de son peuple, de manière à être profané.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Vous ne vous raserez pas la tête à cause d’un mort; ils ne se raseront pas la barbe, ils ne se feront pas d’incisions dans les chairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Les prêtres seront saints, consacrés à leur Dieu; ils ne profaneront pas le nom de Dieu; car ils offrent les sacrifices du Seigneur, les oblations de leur Dieu; ils seront donc saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ils n’épouseront ni prostituée, ni femme profanée, ni femme répudiée par son mari; car le prêtre est saint, consacré au Seigneur son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Tu le sanctifieras, et c’est lui qui présentera les dons faits au Seigneur votre Dieu; il sera saint, parce que je suis saint, moi, le Seigneur qui le sanctifie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'La fille du prêtre qui se profanera par la fornication, et profanera le nom de son père, sera consumée par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Le grand prêtre, celui qui est grand parmi ses frères, à qui l’on a versé sur la tête l’huile du Christ, celui qui a été consacré pour revêtir les ornements, n’ôtera jamais sa tiare, et ne déchirera pas ses vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Il n’entrera pas auprès d’un mort, et ne contractera pas de souillure même pour son père ou sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Il ne sortira pas du lieu saint, et ne profanera pas ce qui a été sanctifié par son Dieu, parce que l’huile dü Christ de son Dieu est sur lui: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Il prendra pour femme une vierge de sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Il n’épousera ni veuve, ni femme répudiée, profanée ou prostituée; mais il prendra pour femme une vierge de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Il ne profanera pas son sang au milieu du peuple: je suis le Seigneur qui le sanctifie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Dis à Aaron: L’homme de ta famille, en vos générations futures, qui aura une tâche, n’entrera pas pour présenter les offrandes au Seigneur son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Tout homme qui aura une tache n’entrera point: l’aveugle, le boiteux, celui qui a le nez coupé, celui à qui manque une oreille,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Celui qui a une main ou un pied difforme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Le bossu, celui qui a une taie sur l’œil, celui qui n’a point de cils, celui qui a la rogne ou une dartre vive, ou à qui il manque un testicule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Tout membre de la race d’Aaron qui a quelque tache, ne s’approchera point pour offrir les sacrifices à son Dieu, parce qu’il y a une tache en lui; il n’entrera point pour offrir les dons à Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Mais il mangera des choses saintes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Seulement, il n’entrera point devant le voile, et ne s’approchera pas de l’autel, parce qu’il a une tache, et il ne profanera pas le sanctuaire de son Dieu; car je suis le Seigneur, et c’est moi qui sanctifie les prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Et Moïse dit ces choses à Aaron et à ses fils, ainsi qu’à tous les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Dis à Aaron et à ses fils qu’ils soient très-attentifs pour les choses saintes; qu’ils ne profanent mon saint nom en aucune des choses qu’ils me consacrerónt: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Dis-leur: Dans la suite de vos générations, tout homme de votre famille qui s’approchera des choses saintes, de celles que les fils d’Israël consacreront au Seigneur, et qui aura en lui quelque impureté, sera exterminé par moi: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'L’homme, de la famille du prêtre Aaron, atteint de la lèpre ou de la gonorrhée, ne mangera point des choses saintes avant d’avoir été purifié, non plus que celui qui aura touché un animal impur, ou qui aura eu une émission de semence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Ou qui aura touché un reptile impur qui l’ait souillé, ou un autre homme qui l’aura souillé par une impureté quelconque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'L’homme, ainsi souillé par attouchement, sera impur jusqu’au soir; il ne mangera des choses saintes qu’après s’être lavé le corps avec de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Après le coucher du soleil, il sera pur et mangera des choses saintes, puisque c’est sa nourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Il ne mangera ni corps mort ni proie enlevée par une bête fauve, il en serait souillé: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Ils observeront mes préceptes, afin de ne point porter de péché en les violant, et de ne pas mourir pour les avoir profanés: je suis le Seigneur qui les sanctifie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Nul, d’une autre famille, ne mangera des choses saintes; ni l’hôte du prêtre, ni son journalier, ne mangeront des choses saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mais, si le prêtre, à prix d’argent, a acquis un esclave, celui-ci mangera de ses aliments; les serviteurs, nés en sa maison, pareillement, en pourront manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'La fille du prêtre, si elle s’unit à un homme d’une autre famille, ne mangera pas des prémices du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Si la fille du prêtre devient veuve, ou si elle est répudiée, pourvu qu’elle n’ait pas d’enfants, elle retournera en sa demeure paternelle, sur le même pied que durant sa jeunesse, et elle mangera des aliments de son père; mais nul étranger à la famille n’en pourra manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Tout homme qui, par ignorance, aura mangé des choses saintes, fera une restitution équivalente, y ajoutera un cinquième en sus, et donnera le tout au prêtre, comme chose sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Et l’on ne profanera pas les choses saintes des fils d’Israël, qu’ils ont destinées au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'On se rendrait coupable d’un délit en mangeant de ces choses saintes; car je suis le Seigneur qui ai sanctifié les prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Parle à Aaron et à ses fils, et à toute la synagogue des fils d’Israël, et dis-leur: Tout homme, des fils d’Israël ou des prosélytes, demeurant parmi eux en Israël, qui apportera des victimes après une confession, ou par une élection quelconque, pour être offertes en holocaustes à Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Présentera des bêtes mâles et sans tache, acceptables par vous, prises parmi les bœufs, les brebis ou les chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Tout ce qui aura quelque tache ne sera point présenté au Seigneur, puisqu’il ne serait point acceptable par vous-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Tout homme qui offrira au Seigneur une hostie pacifique, soit par vœu, soit par élection, soit à l’occasion de l’une de vos fêtes, prendra, parmi les bœufs ou les brebis, une victime sans tache, acceptable, n’ayant aucune difformité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Nulle bête, aveugle, ou ayant soit une fracture, soit la langue coupée, soit la peau couverte de boutons, la rogne, ou une dartre vive, ne sera présentée au Seigneur; vous n’en ferez point une hostie sur l’autel du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Tu immoleras pour toi-même le veau ou la brebis qui aura les oreilles ou la queue coupées; mais il ne sera pas reçu pour l’accomplissement de ton vœu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Tu ne présenteras pas au Seigneur de bête châtrée par compression, ou par amputation, ou par arrachement; vous n’en sacrifierez point en votre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Vous ne recevrez pas non plus, de la main de l’étranger, aucune de ces choses pour les offrir en don à votre Dieu, parce qu’il y a un vice et une tache en elles; vous ne les recevrez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Le veau, ou l’agneau, ou le chevreau nouveau-né, restera sept jours sous sa mère, et, à partir du huitième jour, il pourra être choisi comme victime et offrande au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Vous ne sacrifierez pas le même jour la vache, la brebis et leurs rejetons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Lorsque vous sacrifierez une victime d’action de grâces au Seigneur, qu’elle soit acceptable par vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Elle sera mangée le jour même du sacrifice; vous ne laisserez point de sa chair pour le lendemain: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Ainsi, vous observerez mes commandements et vous les exécuterez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Et vous ne profanerez pas le nom du Saint, et je serai sanctifié au milieu des fils d’Israël: je suis le Seigneur qui vous sanctifie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Et qui vous ai tirés de la terre d’Égypte pour être votre Dieu je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Parle aux fils d’Israël, et dis-leur: Les fêtes du Seigneur, que vous appellerez saintes et solennelles, ce sont mes fêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Pendant six jours, vous ferez vos travaux; le septième jour est le sabbat, repos saint et solennel, consacré au Seigneur; vous ne ferez aucune œuvre ce jour-là; c’est le sabbat du Seigneur, partout où vous serez établis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Voici les fêtes saintes et solennelles que vous célébrerez à leurs époques:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Au premier mois, le quatorzième jour de la lune, vers le milieu de la soirée, c’est la pâque du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Et le quinzième jour de cette lune, c’est la fête des azymes du Seigneur; pendant sept jours vous mangerez des azymes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Le premier jour sera saint et solennel parmi vous; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Pendant sept jours vous présenterez des holocaustes au Seigneur, et le septième jour sera parmi vous saint et solennel; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Parle aux fils d’Israël, et dis-leur: Lorsque vous serez entrés en la terre que je vous donne, et que vous y ferez la moisson, vous apporterez au prêtre une gerbe, comme prémices de votre moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Et il présentera la gerbe au Seigneur, afin qu’il l’accepte pour vous; le prêtre la présentera dès le lendemain du premier jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Et, le jour même où vous apporterez la gerbe, vous immolerez une brebis d’un an et sans tache, en holocauste au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Et pour son oblation vous offrirez deux dixièmes de fleur de farine pétris dans l’huile; c’est le sacrifice au Seigneur, l’odeur de suavité pour le Seigneur, et ses libations seront faites avec le quart d’une mesure de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Vous ne mangerez ni pain ni grains grillés de la nouvelle récolte, avant ce jour, avant d’avoir offert vos oblations à votre Dieu. C’est une loi perpétuelle pour toutes vos générations, partout où vous demeurerez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Et, à partir du lendemain du sabbat, jour où vous présenterez la gerbe de prémices, vous compterez sept semaines complètes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Y compris le jour qui suivra la dernière semaine,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Vous apporterez de vos demeures des pains de prémices; ce seront deux pains faits avec deux dixièmes de fleur de farine, les premiers pains levés faits des prémices au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Et avec les pains vous présenterez sept agneaux d’un an sans tache, un veau pris parmi les bœufs, et deux béliers sans tache, en holocauste au Seigneur, avec leurs oblations et libations; ce sera le sacrifice d’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Après cela, on immolera, pour le péché, un bouc pris parmi les chèvres, et deux agneaux d’un an, comme hosties pacifiques offertes avec les pains de prémices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Et le prêtre placera la victime, pour le péché, devant le Seigneur, avec le monceau des pains de prémices, et avec les deux agneaux offerts comme hosties pacifiques; ils seront consacrés au Seigneur, et appartiendront au prêtre qui en aura fait l’offrande,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Vous appellerez ce jour-là solennel, et il sera saint pour vous, vous ne ferez en ce jour aucune œuvre servile; c’est une loi perpétuelle en toutes vos générations, partout où vous demeurerez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Lorsque vous moissonnerez en votre terre, vous n’achèverez pas strictement votre moisson, vous ne recueillerez pas les épis de blé tombés çà et là, vous les laisserez pour le pauvre et pour l’étranger: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Parle aux fils d’Israël, dis-leur: Lors de la septième');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Vous ne ferez aucune œuvre servile, et vous présenterez un holocauste au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Le dixième jour de la septième lune, c’est le jour de l’expiation, qui sera parmi vous saint et solennel, et vous humilierez vos âmes, et vous offrirez un holocauste au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Vous ne ferez ce jour-là aucune œuvre servile, car c’est le jour de l’expiation destiné à effacer vos fautes devant le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Toute âme qui ne s’humiliera point en elle-même ce jour-là, sera exterminée parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Et toute âme qui, en ce jour-là, fera quelque œuvre servile, périra parmi son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Vous ne ferez aucune œuvre; c’est une loi perpétuelle pour toutes vos générations, dans tous vos séjours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ce sera pour vous le sabbat des sabbats, et vous humilierez vos âmes; le neuvième jour, d’un soir à l’autre, vous célèbrerez ce sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Parle aux fils d’Israël, et dis-leur: Le quinzième jour de cette septième lune, c’est la solennité des tabernacles; elle durera sept jours consacrés au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Le premier jour sera saint et solennel; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Pendant sept jours, vous offrirez des holocaustes au Seigneur, et le huitième jour sera parmi vous saint et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Telles sont les fêtes du Seigneur, que vous appellerez saintes et solennelles, et dans lesquelles vous offrirez au Seigneur des hosties, des holocaustes, avec leurs oblations et leurs libations, chaque jour de fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Ce sera en outre des sabbats du Seigneur, et de vos dons ordinaires, et en outre de tous vos vœux, et des offrandes volontaires que vous ferez au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Ainsi, à commencer par le quinzième jour de cette septième lune, lorsque vous aurez recueilli tous les produits de la terre, vous célèbrerez, pendant sept jours, la fête du Seigneur; le premier jour, il y aura repos; le huitième jour, repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Et, le premier jour, vous prendrez des plus beaux fruits de vos arbres, des palmes de palmier, des rameaux d’arbres touffus, des branches de saule et des branches du gattilier qui borde les torrents, pour vous réjouir, devant le Seigneur votre Dieu, ces sept jours de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'C’est une loi perpétuelle en toutes vos générations; le septième mois vous célèbrerez cette fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Pendant sept jours vous demeurerez sous des tentes; tout enfant d’Israël demeurera sous la tente;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Afin que vos descendants sachent que j’ai fait demeurer sous des tentes les fils d’Israël, lorsque je les ai tirés de la terre d’Égypte: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Ainsi, Moïse apprit aux fils d’Israël les fêtes du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Donne tes ordres aux fils d’Israël, qu’ils t’apportent de l’huile d’olive pure, de l’huile à éclairer faite d’olives pilées, afin que la lampe brûle sans cesse');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Devant le voile intérieur du tabernacle du témoignage. Aaron et ses fils la feront brûler sans cesse devant le Seigneur, du soir au matin; c’est une loi perpétuelle pour toutes vos générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Vous allumerez les lampes sur le chandelier d’or pur, devant le Seigneur; elles brûleront jusqu’au matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Et vous prendrez de la fleur de farine, et vous en ferez douze pains, chacun de deux dixièmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Vous les poserez en deux propositions, six pains par proposition, sur la table d’or pur, devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Et vous poserez, sur chaque proposition, de l’encens pur et du sel qui seront pour les pains, comme un mémorial placé devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Chaque jour de sabbat, on les placera devant le Seigneur, en présence des fils d’Israël, en signe de perpétuelle alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Puis, ils appartiendront à Aaron et à ses fils, qui les mangeront en lieu saint; car c’est chose souverainement sainte, et à eux destinée parmi les offrandes faites au Seigneur; loi perpétuelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Or, le fils d’une femme israélite, qui était aussi fils d’un Égyptien, et demeurait parmi les enfants d’Israël, sortit et vint à se battre dans le camp avec un Israélite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Et le fils de la femme israélite, ayant prononcé le NOM, l’avait maudit; on le conduisit donc à Moïse. Or, sa mère s’appelait Salomith, fille de Dabri, de la tribu de Dan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Aussitôt, il fut mis en prison pour être jugé, selon le commandement du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Et le Seigneur parla à Moise, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Emmène hors du camp l’homme qui a blasphémé; que tous ceux qui l’ont entendu posent leurs mains sur sa tête, et que tout le peuple le lapide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Parle ensuite aux fils d’Israël, et dis-leur: Tout homme qui maudira Dieu portera son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Et celui qui blasphèmera le nom saint de Dieu, mourra de mort; que toute la synagogue d’Israël le lapide; prosélyte ou indigène, quiconque aura blasphémé le nom du Seigneur, périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Que l’homme qui aura frappé un autre homme jusqu’à lui ôter la vie, meure de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Celui qui aura frappé une tête de bétail qui en sera morte, rendra bête pour bête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Celui qui aura défiguré son prochain par une blessure, sera défiguré pareillement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Meurtrissure pour meurtrissure, œil pour œil, dent pour dent; qu’à celui qui aura défiguré son prochain par une blessure, la même blessure soit faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Quiconque aura frappé un homme, si cet homme meurt, sera mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Il n’y aura qu’une même justice pour le prosélyte et pour l’indigène; car je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Et Moïse parla aux fils d’Israël; ceux-ci entraînèrent le blasphémateur hors du camp, et ils le lapidèrent; et les fils d’Israël firent ce qu’avait prescrit le Seigneur à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Et le Seigneur parla à Moïse sur le mont Sina, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Parle aux fils d’Israël, et dis-leur: Lorsque vous serez entrés en la terre que je vous donne, la terre que je vous donne se reposera aussi; c’est le sabbat du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Tu ensemenceras ton champ six années, tu tailleras ta vigne six années, et tu en recueilleras les fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Mais la septième année sera un sabbat, le repos de la terre, le sabbat du Seigneur: tu n’ensemenceras pas on champ, tu ne tailleras pas ta vigne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Et tu ne moissonneras pas les produits spontanés de ton champ, et tu ne vendangeras pas la grappe, qui sera pour toi chose sainte; ce sera une année de repos pour la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Et le sabbat de la terre sera une source d’aliments pour toi, ton serviteur, ta servante, ton mercenaire et l’étranger résidant auprès de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Quant à tes troupeaux et aux bêtes sauvages qui sont en ton champ, tout fruit de ce champ sera leur nourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Et tu compteras sept repos d’années, sept fois sept années, et tu auras sept semaines d’années, quarante-neuf ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Vous sonnerez de la trompette par toute votre terre, le dixième jour du septième mois; le jour de la propitiation, vous sonnerez de la trompette par toute votre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Et vous sanctifierez cette année, la cinquantième année, et vous proclamerez la RÉMISSION sur la terre pour tous ceux qui l’habitent: tel sera pour vous le signal de l’année de rémission. Alors chacun rentrera dans ses possessions, chacun retournera en sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ainsi, la cinquantième année proclamera pour vous la rémission; vous n’ensemencerez pas, vous ne moissonnerez pas ce que la terre produirait d’elle-même, vous ne vendangerez pas les grappes, qui seront pour vous chose sainte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Parce que c’est la proclamation de la rémission; elle est sainte pour vous; vous mangerez au jour le jour le produit spontané des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En l’année où la rémission sera ainsi proclamée chacun rentrera dans ses anciennes possessions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Si tu vends ou achètes à ton prochain, garde-toi de l’affliger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Tu achèteras de ton prochain selon le nombre des années écoulées depuis la proclamation; le prix de la vente sera réglé sur le nombre des récoltes faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Plus est grand le nombre des années, plus sa possession vaut; moins est grand le nombre des années moins sa possession vaut, puisqu’elle doit être évaluée selon le nombre des récoltes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Nul n’affligera son prochain; et tu craindras le Seigneur ton Dieu: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Et vous ferez selon mes commandements et mes jugements vous les observerez, vous les mettrez en pra· tique, et vous habiterez sur la terre en assurance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'La terre vous donnera des fruits, et vous en serez rassasiés, et vous l’habiterez en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Que si vous dites: Que mangerons-nous en cette septième année, si nous ne semons ni ne récoltons nos fruits?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Sachez que je vous enverrai ma bénédiction en la sixième année, qui produira des fruits pour trois ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Et la huitième année vous sèmerez, et vous vous');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'La terre ne se vendra point irrévocablement, car elle est mienne, et vous n’êtes que des prosélytes et des passagers devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Pour toute terre, jadis possédée par vous, vous pourrez donner le prix du rachat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Si ton frère, qui est avec toi, devient pauvre, et vend une partie de son héritage, son parent pourra venir et racheter ce que son frère aura vendu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Mais, s’il n’a pas de proche, si sa main est pourvue en abondance, et qu’il se trouve avoir le prix suffisant du rachat,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Il comptera les années de vente, et il rendra à l’homme à qui elle a été faite, le prix de celles qui restent, et il rentrera dans sa possession.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Et si sa main n’est pas assez pourvue pour suffire au rachat, le champ vendu restera à l’acheteur jusqu’à la sixième année après la rémission, et celui-ci en sortira par l’effet de la rémission, et le vendeur rentrera dans sa possession.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Si un homme a vendu, dans une ville fermée, une maison habitable, il y aura aussi faculté de rachat jusqu’à un temps déterminé; le rachat pourra se faire pendant une année entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Mais, si elle n’a pas été rachetée avant que l’année soit accomplie, cette maison, qui est dans une ville fortifiée, appartiendra irrévocablement à l’acheteur et à toutes ses générations; il n’en sortira pas lors de la rémission.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Les maisons des villages, qui ne sont point');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Les villes des lévites aussi, les maisons des villes qui sont leur héritage, pourront toujours être rachetées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Quiconque aura acheté des lévites une maison d’une des villes qui sont leur héritage, sera évincé de son achat lors de la rémission, parce que les maisons des lévites sont leur héritage au milieu des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Et les champs réservés, dépendants de leurs villes, ne seront pas vendus, parce que c’est là leur perpétuel héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Si ton frère, celui qui est avec toi, est devenu pauvre, qu’il manque de ressources auprès de toi, tu prendras soin de lui comme du prosélyte ou du passager, et ton frère vivra avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Tu ne prendras pas de lui d’usure, pas même s’il retrouvait l’abondance, et tu craindras ton Dieu: je suis le Seigneur; et ton frère vivra avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Tu ne lui prêteras pas à intérêt ton argent, et tu ne lui donneras pas de tes aliments pour qu’il t’en rende davantage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Je suis le Seigneur votre Dieu qui vous ai tirés de la terre d’Égypte, pour vous donner la terre de Chanaan, afin d’être votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Et si ton frère, auprès de toi, vient à déchoir et à se vendre à toi, ce ne sera jamais comme esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Il sera pour toi comme un mercenaire ou un domestique, il travaillera chez toi jusqu’à l’année de la rémission.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Mais à cette époque, il redeviendra libre et ses enfants avec lui, et il rentrera dans sa famille, et il courra reprendre possession de son patrimoine;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Parce que ceux que j’ai tirés de la terre d’Égypte sont mes serviteurs à moi, nul d’entre eux ne sera vendu comme un esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Tu ne l’accableras pas de travail, et tu craindras le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Tous les serviteurs et servantes que tu auras, tu les rachèteras des nations qui t’entourent. C’est d’elles que vous achèterez vos serviteurs et vos servantes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Comme aussi des fils des étrangers demeurant parmi vous vous les achèterez d’eux et de toutes leurs familles qui seront sur votre terre, pour être votre propriété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Et, après vous, vous les donnerez en partage à vos enfants, et ils seront votre propriété perpétuelle; mais des ils d’Israël, nul ne tourmentera son frère par des travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Et si la main de quelque prosélyte ou étranger fixé chez vous a trouvé l’abondance, et que votre frère, réduit l’indigence, ait été vendu à ce prosélyte, à lui, ou à sa famille,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Après avoir été vendu, il pourra être racheté; l’un e ses frères le rachètera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Le frère de son père, ou le fils du frère de son ère le rachètera, ou quelqu’un de sa tribu, de sa famille et de son sang, le rachètera; et, si sa main est suffisamment pourvue, il se rachètera lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'On supputera le temps depuis sa vente jusqu’à la prochaine rémission, et le prix de son rachat sera celui u mercenaire, selon le nombre des années qui restent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'S’il y a plus d’années, il ajoutera au prix de son achat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'S’il ne reste que peu d’années, jusqu’à celle de la émission, il supputera, et, selon le nombre d’années, il');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Ce sera année par année, selon le temps qui restera; et tu ne l’accableras pas de travail en ta présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'S’il n’est racheté d’aucune de ces manières, il s’er ira en liberté l’année de la rémission, lui et ses enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Parce que les fils d’Israël sont mes serviteurs; c sont mes serviteurs, que j’ai tirés de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Je suis le Seigneur votre Dieu; vous n’aurez point d’idoles faites de vos mains ou sculptées, vous n’érigerez pas pour vous de colonnes, vous ne dresserez pas d pierres significatives en votre terre pour les adorer: j suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Vous observerez mes sabbats, et vous craindrez me choses saintes je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si vous marchez selon mes préceptes, si vous observez mes commandements et les mettez en pratique,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Je vous enverrai de la pluie au temps opportun, e la terre donnera ses récoltes, et les arbres des champ porteront des fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'La moisson chez vous tendrą la main à la vendange, et la vendange aux semailles; vous mangerez du pain à satiété, vous habiterez votre terre en assurance, e la guerre ne passera pas par votre territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Je donnerai la paix à votre pays, et vous vous reposerez; il n’y aura personne pour vous causer de l’effroi et j’exterminerai de votre terre les bêtes malfaisantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Vous chasserez vos ennemis, et ils tomberont devant vous au milieu du carnage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Cinq de vous en chasseront cent, et cent en chasseront des myriades, et les ennemis tomberont devant vous frappés par le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Je tournerai mes regards vers vous, je vous ferai croître et vous multiplierai, et j’établirai avec vous mon alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Vous mangerez les récoltes anciennes, tellement anciennes, que vous les rejetterez à l’arrivée des nouvelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'J’établirai au milieu de vous mon tabernacle, et mon âme ne vous aura point en abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Et je marcherai avec vous, je serai votre Dieu, et vous serez mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Je suis le Seigneur votre Dieu qui vous ai tirés de la terre d’Égypte où vous étiez esclaves; j’ai brisé les chaînes de votre joug, et je vous ai conduits libres en assurance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mais si vous n’obéissez point, si vous n’exécutez pas mes commandements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Si vous leur êtes indociles, si votre âme s’irrite contre mes jugements au point de ne plus mettre mes préceptes en pratique et de briser mon alliance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Voici ce que je vous ferai, moi: j’affermirai parmi vous la misère, la gale et la jaunisse, qui vous sécheront les yeux, et vous consumeront l’âme; vous sèmerez en vain vos grains, vos ennemis s’en nourriront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Je tournerai ma face contre vous, et vous tomberez devant vos ennemis; ceux qui vous haïssent vous chasseront, et vous fuirez, quoique personne ne vous poursuive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Et si après cela vous ne m’obéissez point encore, je continuerai de vous châtier sept fois, à cause de vos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Je briserai l’excès de votre orgueil, et je ferai qué pour vous le ciel soit de fer et la terre d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Votre force s’épuisera vainement, la terre ne vou s');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Et si après cela votre marche est encore oblique, si vous refusez de m’obéir, je vous enverrai sept plaies pour vos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Je déchaînerai contre vous les bêtes féroces de la terre; elles vous dévoreront, et elles prendront votre bétail; je réduirai votre nombre à rien, et vos routes demeureront désertes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Et si après cela vous n’êtes point corrigés, si votre marche est encore oblique en ma présence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Moi aussi je marcherai avec vous dans les voies obliques de ma colère, moi aussi je vous frapperai sept fois, à cause de vos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Et je dirigerai contre vous le glaive vengeur de l’alliance méconnue; vous vous réfugierez dans vos villes, mais j’enverrai contre vous la mort, et vous serez livrés aux ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Je vous contristerai par la famine; alors dix femmes cuiront vos pains dans un seul four, et on vous les distribuera à la ration; vous mangerez, et vous ne serez jamais rassasiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Et si après cela vous continuez de ne me point obéir, si devant moi votre marche est oblique,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Moi aussi je marcherai avec vous dans les voies obliques de ma colère, je vous châtierai sept fois pour vos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Et vous mangerez les chairs de vos fils, vous mangerez les chairs de vos filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Je renverserai vos colonnes, j’anéantirai vos sculptures de bois, et je mettrai vos cadavres sur vos idoles renversées, et mon âme vous aura en horreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Je dévasterai vos villes, je désolerai vos sanctuaires, et je ne me réjouirai plus du parfum de vos sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Je rendrai déserte votre terre, et vos ennemis qui l’habitent en seront frappés d’étonnement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Et je vous disperserai parmi les nations; le glaive se promènera sur vous; je vous détruirai, votre territoire sera abandonné et vos villes désertes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alors, la terre jouira du repos sabbatique, pendant tous les jours de sa désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Et vous serez en la terre de vos ennemis, et votre terre observera le sabbat, et elle jouira du repos sabbatique; elle en jouira tous les jours de sa désolation, pour compenser tous vos sabbats violés, lorsque vous l’habitiez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Ceux d’entre vous qui survivront, je leur mettrai au cœur l’accablement de la servitude en la terre de leurs ennemis; le bruit d’une feuille emportée par le vent les mettra en fuite; ils courront comme les fuyards en une bataille, et ils tomberont sans que personne les poursuive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Et, de même que dans une déroute, le frère verra son frère avec indifférence, quoique personne ne les poursuive; et vous ne pourrez résister à vos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Vous périrez au milieu des nations, et la terre de vos ennemis vous dévorera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Et ceux de vous qui survivront, pourriront à cause de leurs péchés et des péchés de leurs pères; ils seront consumés en la terre de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Alors, ils confesseront leurs péchés et les péchés de leurs pères, ils confesseront qu’ils ont prévariqué, qu’ils m’ont méprisé, qu’ils ont marché devant moi dans des voies obliques;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Et voyant que moi aussi j’ai marché avec eux dans les voies obliques de ma colère, et que je vais les détruire en la terre de leurs ennemis, leur cœur incirconcis se convertira, et ils reconnaîtront leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Et je me souviendrai de l’alliance de Jacob et de l’alliance d’Isaac; je me souviendrai de l’alliance d’Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Je me souviendrai de leur pays qu’ils auront abandonné. Leur terre retrouvera ses sabbats perdus, lorsqu’elle sera désolée à cause d’eux, et qu’ils recevront la peine de leurs iniquités, pour avoir méprisé mes jugements et détesté mes préceptes dans leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Cependant, lorsqu’ils étaient dans la terre de leurs ennemis, je ne les ai pas méprisés, je ne les ai pas eus en horreur jusqu’à les exterminer et rompre mon alliance avec eux; car je suis le Seigneur leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Je me souviendrai de leur première alliance, lorsque je les ai fait sortir de la terre d’Égypte, de la maison de servitude, à la face des nations, pour être leur Dieu; je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Tels sont mes jugements et mes préceptes; telle est la loi que le Seigneur a établie entre lui et les fils d’Israël sur le mont Sina, par le ministère de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Parle aux fils d’Israël, et dis-leur: Celui qui fera');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Paiera, si c’est un homme de vingt à soixante ans, cinquante drachmes d’argent au poids du sanctuaire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Et, si c’est une femme, trente drachmes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'S’il s’agit d’un jeune garçon de quinze à vingt ans, le prix sera vingt drachmes, et pour une jeune fille, dix drachmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'D’un mois à cinq ans le prix pour un jeune garçon sera cinq drachmes, et pour une fille, trois drachmes d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'S’il s’agit d’un homme de soixante ans et au-dessus, le prix sera quinze drachmes d’argent, et dix drachmes pour une femme:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Si la personne est trop pauvre pour payer le prix, elle se présentera devant le prêtre qui évaluera ce qu’elle peut donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Si l’on fait don au Seigneur d’un des bestiaux qu’on peut offrir, l’objet donné au Seigneur sera chose sainte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Il ne sera pas échangé; on ne substituera pas le bon au mauvais, non plus que le mauvais au bon; si l’homme fait un échange, s’il substitue une tête de bétail à une autre, la première et la seconde seront choses saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Si l’homme n’a qu’une bête impure, de celles dont on ne fait pas d’offrandes au Seigneur, il placera la bête devant le prêtre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Celui-ci, qu’elle soit bonne ou mauvaise, l’estimera, et l’on s’en tiendra à son estimation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Si l’homme la rachète, il ajoutera un cinquième en sus du prix de l’estimation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Si un homme a consacré au Seigneur sa maison comme chose sainte, le prêtre, qu’elle soit bonne ou mauvaise, l’estimera, et l’on s’en tiendra à son estimation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Si l’homme qui aura consacré sa maison au Seigneur la rachète, il ajoutera un cinquième au prix de l’estimation, et elle sera à lui de nouveau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Si un homme consacre au Seigneur une part de son champ héréditaire, on l’estimera selon la quantité de grain que l’on y sème: cinquante drachmes d’argent pour une mesure d’orge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'S’il a consacré son champ immédiatement après l’année de la rémission, on s’en tiendra à l’estimation qu’on aura faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'S’il consacre son champ peu de temps avant la rémission, le prêtre lui portera en compte l’argent selon les années qui restent jusqu’à la rémission, et il sera fait une soustraction sur son estimation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Si celui qui aura consacré son champ au Seigneur le rachète, il ajoutera un cinquième au prix de l’estimation, et il sera à lui de nouveau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'S’il ne rachète pas son champ, et s’il le vend à un autre homme, il ne pourra plus le racheter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Et la rémission étant venue, le champ appartiendra au Seigneur; le champ sera remis en la possession du prêtre, comme terre consacrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Si, après avoir consacré une part d’un champ, par lui acheté, qui ne faisait pas partie de son champ héréditaire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'L’homme veut ensuite la racheter, le prêtre en évaluera le prix d’après l’année de la rémission; et, le jour du rachat, l’homme paiera ce prix, comme chose consacrée au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Et à la rémission le champ sera rendu à celui de qui l’autre l’aura acheté, et qui l’avait recueilli en héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Toute somme d’argent sera payée au poids du sanctuaire, vingt oboles par drachme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Tout premier-né de votre bétail appartiendra au Seigneur, et nul ne le consacrera; que ce soit un veau, un agneau ou un chevreau, il appartiendra au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'On évaluera le premier-né des quadrupèdes impurs; le maître donnera le montant de cette estimation avec un cinquième en sus, et la bête lui appartiendra; s’il ne la rachète pas, elle sera vendue selon l’estimation que l’on en aura faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Nul objet consacré par l’homme au Seigneur, de ce qu’il possède, depuis l’homme jusqu’aux bestiaux, ou de ses champs héréditaires, ne pourra être vendu ni racheté. Tout objet consacré sera chose très-sainte appartenant au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Tout être vivant qui aura été consacré par les hommes, ne pourra être racheté, mais il mourra de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Toute dîme de la terre, toute dîme des grains de la terre et des fruits des arbres, appartient au Seigneur; elle lui est consacrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Mais, si un homme rachète sa dîme à prix d’argent, il donnera un cinquième en sus de l’estimation, et elle lui appartiendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Toute dîme des bœufs, des brebis et des chèvres, toute dîme de ce qui marche en troupeau, sous le bâton du pasteur, appartiendra au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Et tu ne substitueras pas le bon au mauvais, ni le mauvais au bon; si tu fais cet échange, les deux bêtes seront saintes et ne pourront être rachetées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Tels sont les préceptes que le Seigneur a à Moïse sur le mont Sina, pour les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Et le Seigneur parla à Moïse dans le tabernacle du témoignage, au désert de Sina, le premier du second mois de la seconde année, après la sortie d’Égypte, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Prenez le nombre de toute la synagogue d’Israël, et comptez-les par familles, par maisons paternelles, par têtes et par leurs noms.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Tout mâle de vingt ans et au-dessus, tout Israélite pouvant marcher au combat, comptez-le dans l’armée. Tu feras ce dénombrement avec Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Faites-vous seconder par les princes des diverses tribus et familles paternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Voici les noms des hommes qui vous assisteront; parmi ceux de Ruben, Elisur, fils de Sédiur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Parmi ceux de Siméon: Salamiel, fils de Surisadaï;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Parmi ceux de Juda: Nahasson, fils d’Aminadab;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Parmi ceux d’Issachar: Nathanaël, fils de Sogar;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Parmi ceux de Zabulon: Eliab, fils de Chaïlon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Parmi ceux de Joseph et d’Éphraïm Elisama, fils d’Emiud; et parmi ceux de Manassé: Gamaliel, fils de Phadasur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Parmi ceux de Benjamin: Abidan, fils de Gadéoni;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Parmi ceux de Dan: Achièzer, fils d’Amisadaï;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Parmi ceux d’Aser: Phagéel, fils d’Echran;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Parmi ceux de Gad: Eliasaph, fils de Raguel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Et parmi ceux de Nephthali: Achire, fils d’Enan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ce sont les plus illustres du peuple, les princes de leurs tribus selon leur origine paternelle, commandants de mille hommes en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Moïse et Aaron prirent donc les hommes nominativement désignés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Puis, ils rassemblèrent tout le peuple, le premier jour du second mois de la seconde année, et ils firent le dénombrement; ils prirent les noms de tous les mâles de vingt ans et au-dessus, selon leur naissance, par familles et par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Comme le Seigneur l’avait prescrit à Moïse; ils firent ce recensement dans le désert de Sina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Les fils de Ruben, premier-né d’Israël, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles et par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Et le recensement de la tribu de Ruben donna quarante-six mille cinq cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Les fils de Siméon, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement pat familles, par branches, par maisons paternelles et par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Et le recensement de la tribu de Siméon donna cinquante-neuf mille trois cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Les fils de Juda, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Et le recensement de la tribu de Juda donna soixante-quatorze mille six cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Les fils d’Issachar de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Et le recensement de la tribu d’Issachar donna cinquante-quatre mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Les fils de Zabulon, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Et le recensement de la tribu de Zabulon donna cinquante-sept mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Les fils de Joseph, fils d’Éphraïm, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Et le recensement de la tribu d’Éphraïm donna quarante mille cinq cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Les fils de Manassé, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Et le recensement de la tribu de Manassé donna trente-deux mille deux cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Les fils de Benjamin, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Et le recensement de la tribu de Benjamin donna trente-cinq mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Les fils de Gad, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Et le recensement de la tribu de Gad donna quarante-cinq mille six cent cinquante hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Les fils de Dan, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Et le recensement de la tribu de Dan donna soixantedeux mille sept cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Les fils d’Aser, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Et le recensement de la tribu d’Aser donna quarante-un mille cinq cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Les fils de Nephthali, de vingt ans et au-dessus, tous ceux qui pouvaient aller à l’armée, furent comptés nominativement par familles, par branches, par maisons paternelles, par têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Et le recensement de lå tribu de Nephthali donna cinquante-trois mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Tel fut le dénombrement que fit Moïse avec Aaron, et les chefs d’Israël au nombre de douze, un homme par tribu, pris dans la tribu de sa maison paternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Et le recensement total des fils d’Israël, de vingt ans et au-dessus, en état de porter les armes, donna');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Six cent trois mille cinq cent cinquante hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mais les lévites de la tribu paternelle de Lévi ne furent point recensés parmi les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Car le Seigneur avait parlé à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Tu ne recenseras pas la tribu de Lévi, et tu̟ n’en prendras pas le nombre parmi les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Tu donneras aux lévites le soin du tabernacle du témoignage, de ses ornements et de tout ce qu’il renferme; et ils transporteront le tabernacle avec tous ses ornements; ils exerceront le sacerdoce dans le tabernacle, et ils camperont autour du tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Lorsqu’il faudra enlever le tabernacle, les lévites l’enlèveront, et lorsqu’il faudra dresser le tabernacle, ils le dresseront; que l’homme d’une autre tribu qui s’en approcherait soit mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Lorsque les fils d’Israël camperont en corps d’armée, chacun au rang à lui assigné, selon la branche à laquelle il appartient,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Que les lévites campent en cercle, près du tabernacle du témoignage, et il n’y aura point de péché parmi les fils d’Israël. Les lévites seuls auront la garde du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Et tout ce que le Seigneur avait prescrit à Moïse et à Aaron, les fils d’Israël le firent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Le Seigneur parla ensuite à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Que les fils d’Israël campent en face les uns des autres, chaque homme restant à son rang sous ses enseignes, avec sa maison paternelle; qu’ils campent autour du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Les premières tentes du côté de l’orient seront sous le commandement du camp de Juda, avec leur armée, et le chef des fils de Juda sera Nahasson, fils d’Aminadab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Son armée, selon le recensement, est de soixante-quatorze mille six cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'À côté, campera la tribu d’Issachar; leur chef sera Nathanaël, fils de Sogar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Son armée, selon le recensement, est de cinquante-quatre mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'À côté, campera la tribu de Zabulon; leur chef sera Eliab, fils de Chaïlon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Son armée, selon le recensement, est de cinquante-sept mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Tous les hommes recensés du camp de Juda forment un corps de cent quatre-vingt-six mille quatre cents hommes; ils lèveront le camp les premiers avec toutes leurs forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Le camp de Ruben se rangera du côté du midi; et le chef des fils de Ruben sera Elisur, fils de Sédiur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Son armée, selon le recensement, est de quarante-six mille cinq cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'À côté, campera la tribu de Siméon; leur chef sera Salamiel, fils de Surisadaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Son armée, selon le recensement, est de cinquante-neuf mille trois cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'À côté, campera la tribu de Gad; leur chef sera Eliasaph, fils de Raguel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Son armée, selon le recensement, est de quarante-cinq mille six cent cinquante hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Tous les hommes recensés du camp de Ruben, forment un corps de cent cinquante-un mille trois cent cinquante hommes; ils décamperont les seconds avec toutes leurs forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Le tabernacle du Seigneur sera dressé, et le camp des lévites sera placé au centre des camps; on marchera dans le même ordre que l’on dressera les tentes, chacun restant au corps auquel il appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Le camp d’Ephraïm se rangera du côté de l’occident; le chef des fils d’Ephraïm sera Elisama, fils d’Emiud.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Son armée, selon le recensement, est de quarante mille cinq cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'À côté, campera la tribu de Manassé; leur chef sera Gamaliel, fils de Phadasur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Son armée, selon le recensement, est de trentedeux mille deux cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'À côté, campera la tribu de Benjamin; leur chef sera Abidan, fils de Gadéoni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Son armée, selon le recensement, est de trentecinq mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Tous les hommes recensés du camp d’Ephraïm forment un corps de cent huit mille cent hommes; ils décamperont avec toutes leurs forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Le camp de Dan se rangera du côté du nord; et le chef des fils de Dan sera Achiézer, fils d’Amisadaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Son armée, selon le recensement, est de soixante-deux mille sept cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'À côté, campera la tribu d’Aser; leur chef sera Phagéel, fils d’Echran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Son armée, selon le recensement, est de quarante-un mille cinq cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'À côté, campera la tribu de Nephthali; leur chef sera Achire, fils d’Enan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Son armée, selon le recensement, est de cinquante-trois mille quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Tous les hommes recensés du camp de Dan forment un corps de cent cinquante-sept mille six cents hommes; ils décamperont les derniers, selon leur rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Tel est le dénombrement des fils d’Israël, par maisons paternelles; le total du recensement de leurs forces donne six cent trois mille cinq cent cinquante hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Or, les lévites, comme le Seigneur l’avait prescrit à Moïse, ne furent point recensés avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Et les fils d’Israël firent tout ce que le Seigneur avait prescrit à Moïse; ils campèrent dans l’ordre à eux assigné, ils marchèrent en continuant de se tenir les uns près des autres, rangés par familles et par tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Voici les générations d’Aaron et de Moïse, le jour où le Seigneur parla à Moïse en la montagne de Sina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Voici les noms des fils d’Aaron: premier-né, Nadab, puis Abiu, Eléazar et Ithamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Tels sont les noms des fils d’Aaron, des prêtres qui reçurent l’onction sainte, et dont les mains furent consacrées, pour qu’ils exerçassent le sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nadab et Abiu moururent devant le Seigneur, tandis qu’ils offraient devant le Seigneur, dans le désert de Sina, un feu étranger; et comme ils n’avaient pas d’enfants, Eléazar et Ithamar exercèrent le sacerdoce avec Aaron leur père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Prends la tribu de Lévi et place les lévites devant le prêtre Aaron, pour qu’ils l’assistent dans le service divin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Ils seront chargés d’accomplir les œuvres du culte, devant le tabernacle du témoignage, en son nom, et au nom des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Et ils garderont tous les ornements du tabernacle du témoignage, et ils accompliront, pour les fils d’Israël, toutes les œuvres du tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Tu donneras les lévites à Aaron et à ses fils les prêtres; les lévites sont le don qui m’a été fait parmi les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Et tu établiras Aaron et ses fils sur le tabernacle du témoignage; ils seront chargés du sacerdoce, et des choses qui concernent tant l’autel que l’extérieur du voile du sanctuaire. Tout homme étranger à la tribu de Lévi, qui touchera aux choses sacrées, mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Et le Seigneur parla à Moise, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'J’ai pris, parmi les fils d’Israël, les lévites en échange de tout premier-né des fils d’Israël. Les lévites seront la rançon des premiers-nés; ils seront à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Car tout premier-né est à moi; du jour où j’ai frappé tout premier-né en la terre d’Égypte, je me suis consacré tout premier-né en Israël, depuis l’homme jusqu’aux bestiaux; tout premier-né m’appartiendra: je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Et le Seigneur parla à Moïse dans le désert de Sina, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Fais le dénombrement des fils de Lévi, par branches, par maisons paternelles; recensez tous les mâles: ceux qui sont nés dans le mois et au-dessus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Moïse et Aaron firent le recensement selon l’ordre du Seigneur, comme il le leur avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Voici les noms des fils de Lévi: Gerson, Caath et Mérari;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Voici les noms des fils de Gerson, par branches: Lobeni et Sémeï;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Et ceux des fils de Caath, par branches: Amram, Isaar, Hébron et Oziel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Et ceux des fils de Mérari, par branches: Moholi et Musi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gerson proviennent les branches de Lobeni et de Sémeï; telles sont les branches des Gersonites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Tout mâle d’un mois et au-dessus étant compté, leur recensement a donné sept mille cinq cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Or, les fils de Gerson camperont derrière le tabernacle du côté de l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Le chef de la maison paternelle des branches de Gerson sera Eliasaph, fils de Daël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'La fonction des fils de Gerson dans le tabernacle du témoignage sera de garder le tabernacle lui-même et sa couverture, la porte d’entrée du tabernacle du témoignage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Les téntures du parvis, les voiles de la porte du parvis qui entoure le tabernacle, et tout le reste de ses');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'De Caath proviennent les branches d’Amram, d’Isaar, d’Hébron et d’Oziel; telles sont les quatre branches des Caáthités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Tout mâle d’un mois et au-dessus étant compté, leur recensement à donné un total de huit mille six cents hommes, chargés de garder le sanctuaire et le Saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Les branches des fils de Caath camperont du côté du tabernacle qui regarde le midi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Et le chef de la maison paternelle des branches de Caath sera Elisaphan, fils d’Oziel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Ils auront la garde de l’arche, de la table, du chandelier, des autels et des ornements du sanctuaire, servant au culte sacré, ainsi que du voile intérieur, et de tous les ouvrages qui s’y rapportent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Et le chef des chefs des lévites, Eléazar, fils d’Aaron, est préposé à la garde du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Mérari proviennent les branches de Moholi et de Musi; telles sont les branches des Mérarites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Tout mâle d’un mois et au-dessus étant compté, le recensement a donné six mille cinquante âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Et le chef de la maison paternelle des branches de Mérari sera Suriel, fils d’Abichaïl; ils camperont du côté du tabernacle qui regarde le nord;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Ils seront chargés de conserver les chapiteaux du tabernacle, ses leviers, ses colonnes, ses bases avec tous leurs accessoires, et tout ce qui leur appartient;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Et les colonnes qui entourent le parvis avec leurs bases, les piquets et les cordages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Ceux qui camperont du côté de l’orient devant le tabernacle du témoignage, c’est-à-dire Moïse et Aaron et ses fils, auront pour fonction, parmi les fonctions des fils d’Israël, la garde du sanctuaire. Tout homme étranger à la tribu de Lévi, qui touchera les choses saintes, mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Le total des lévites dont Moïse, avec Aaron, fit le recensement selon l’ordre du Seigneur, par branches, tout mâle d’un mois et au-dessus étant compté, s’éleva à vingt-deux mille âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Le Seigneur parla ensuite à Moïse, disant: Fais le dénombrement de tous les mâles premiers-nés des fils d’Israël d’un mois et au-dessus; prenez-en le compte nominativement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Et prends pour moi les lévites en échange des premiers-nés des fils d’Israël: je suis le Seigneur; prends aussi pour moi le bétail des lévites en échange des premiers-nés du bétail des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Moïse fit, comme le lui avait prescrit le Seigneur, le recensement de tous les premiers-nés des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Et le total des premiers-nés mâles, d’un mois et au-dessus, comptés nominativement, s’éleva à vingt-deux mille deux cent soixante-treize âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Le Seigneur dit encore Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Prends les lévites en échange des premiers-nés des fils d’Israël, et le bétail des lévites en échange des premiers-nés du bétail des fils d’Israël, et les lévites seront à moi je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Prends aussi la rançon des deux cent soixante-treize fils d’Israël qui excèdent le nombre des lévites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Prends cinq sicles par tête, au poids du sanctuaire; vingt oboles par sicle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Tu donneras cet argent à Aaron et à ses fils; ce sera la rançon de ceux que ne rachètent pas les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Moïse prit donc l’argent, la rançon de ceux que ne rachetaient pas les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Et il reçut des premiers-nés des fils d’Israël treize cent soixante-cinq sicles, au poids du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Et, selon l’ordre du Seigneur, Moïse donna la rançon du surplus à Aaron et à ses fils, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Et le Seigneur parla à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Prends, parmi les fils de Lévi, le total des fils de Caath, par branches, par maisons paternelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Depuis vingt-cinq ans et au-dessus jusqu’à cinquante, de tous ceux qui entrent pour le service divin, et pour faire toutes les œuvres du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Voici le ministère des fils de Caath dans le tabernacle du témoignage et le Saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Lorsque Israël lèvera le camp, Aaron et ses fils entreront dans le tabernacle, et ils détendront le voile intérieur, et ils envelopperont l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Ils placeront par-dessus une couverture de peaux bleues, et par-dessus encore ils jetteront un voile bleu, puis, ils passeront les leviers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Et sur la table de proposition, ils étendront une nappe pourpre, sur laquelle ils mettront les plats, les encensoirs, les urnes, les coupes à libations, avec les pains qui sont toujours exposés sur cette table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Ils jetteront par-dessus une nappe écarlate qu’ils envelopperont d’une couverture de peaux bleues, et ils passeront les leviers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Ils prendront ensuite une nappe bleue, et ils en envelopperont le chandelier, les lampes, les pincettes, les burettes et tous les vases à l’huile qui servent à leurs fonctions saintes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Et ils déposeront le chandelier avec tous ses accessoires dans une couverture de peaux bleues, et ils le placeront sur des brancards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Sur l’autel d’or, ils étendront une nappe bleue, et par-dessus une couverture de peaux couleur d’hyacinthe; puis ils passeront les leviers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Ils prendront tous les vases, tous les instruments liturgiques employés dans le sanctuaire, et ils les déposeront sur une nappe bleue, puis, ils les envelopperont d’une couverture de peaux, et ils les placeront sur des brancards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Ils mettront aussi le couvercle sur l’autel des holocaustes, et ils le couvriront d’une nappe pourpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Et ils y placeront tous les vases employés dans la liturgie, les foyers, les crochets, les coupes, le couvercle, tout l’ameublement de l’autel; ils les envelopperont d’une couverture de peaux bleues, puis, ils passeront les leviers. Et ils prendront une nappe pourpre, et ils en envelopperont le réservoir avec sa base qu’ils poseront dans une couverture de peaux bleues, et ils le mettront sur des brancards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Et lorsque, aux levers du camp, Aaron et ses fils auront achevé d’envelopper les choses saintes, ainsi que tous les vases sacrés, les fils de Caath entreront dans le tabernacle pour les enlever, et ils ne toucheront pas aux choses saintes, s’ils ne veulent pas mourir; les fils de Caath les transporteront ensuite hors du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eléazar, fils du grand prêtre Aaron, veillera à l’huile du chandelier, à l’encens composé, aux sacrifices quotidiens, et à l’huile de l’onction; il aura l’inspection du tabernacle entier et de tout ce qu’il contient à l’usage des œuvres saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Et le Seigneur parla à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Gardez-vous d’exposer à périr, parmi la tribu de Lévi, la famille de Caath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Faites ce que je vais dire, et ils vivront; ils ne mourront pas lorsqu’ils s’approcheront du Saint des saints: qu’Aaron et ses fils les précèdent et les placent chacun à son brancard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Et qu’ils n’entrent pas de manière à voir soudain les choses saintes, car ils mourraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Le Seigneur dit aussi à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Prends le total des fils de Gerson par maisons paternelles, par branches,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Depuis vingt-cinq ans et au-dessus jusqu’à cinquante, de tous ceux qui entrent dans le tabernacle du témoignage, pour le service divin et pour faire leurs œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Voici le ministère de la famille des fils de Gerson: servir et enlever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Ils enlèveront les couvertures du tabernacle et le tabernacle du témoignage lui-même, sa première couverture et la couverture bleue d’en haut, avec le voile de l’entrée du tabernacle du témoignage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Et les tentures du parvis qui l’entourent; ils prendront soin aussi de tous les instruments liturgiques se rapportant à leur service.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Le ministère des fils de Gerson, en tous leurs devoirs et en toutes leurs œuvres, s’exercera sous la direction d’Aaron et de ses fils, et tu noteras, en prenant les noms de chacun, toutes les choses qu’ils enlèveront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tel est le ministère des fils de Gerson dans le tabernacle du témoignage, et ils l’exerceront sous la direction d’Ithamar, fils d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Faites le recensement des fils de Mérari, par branches, par maisons paternelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Depuis vingt-cinq ans et au-dessus jusqu’à cinquante, de tous ceux qui entrent dans le tabernacle du témoignage, pour le service de ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Et voici leur fonction et leur part de travail dans le tabernacle du témoignage: ils porteront les chapiteaux du tabernacle, ses leviers, ses colonnes et leurs bases, le voile intérieur, avec ses colonnes et leurs bases, ainsi que le voile de la porte du tabernacle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Et aussi les colonnes du parvis qui l’entoure, avec leurs bases, les colonnes du voile de la porte du parvis et leurs bases, leurs piquets et cordages, leurs divers accessoires, et tout ce qui leur appartient. Vous noterez, en prenant les noms de chacun, toutes les choses qu’ils enlèveront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Tel est le ministère de la famille des fils de Mérari, en toutes leurs œuvres dans le tabernacle du témoignage; ils l’exerceront sous la direction d’Ithamar, fils d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Et Moïse, avec Aaron et les chefs d’Israël, recensa par branches, par maisons paternelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'De vingt-cinq ans et au-dessus jusqu’à cinquante, tous les fils de Caath, qui entraient dans le tabernacle du témoignage, pour les œuvres du service divin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Et leur recensement par branches donna deux mille sept cent cinquante âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Tel fut, selon l’ordre donné par le Seigneur à Moïse, le recensement fait par Moïse et Aaron, des fils de Caath, qui servaient dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Et ils recensèrent par branches, par maisons paternelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'De vingt-cinq ans et au-dessus jusqu’à cinquante, tous les fils de Gerson, qui entraient, pour le service divin et pour faire leurs œuvres, dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Et leur recensement par branches, par maisons paternelles, donna deux mille six cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Tel fut le recensement fait par Moïse et Aaron, selon l’ordre donné par le Seigneur à Moïse, de tous les fils de Gerson, qui servaient dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Ils recensèrent également par branches, par maisons paternelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'De vingt-cinq ans et au-dessus jusqu’à cinquante, tous les fils de Mérari, qui entraient dans le tabernacle du témoignage pour les œuvres du service divin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Et le recensement par branches, par maisons paternelles, donna trois mille deux cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Tel fut le recensement des fils de Mérari, fait par Moïse et Aaron, selon l’ordre donné par le Seigneur à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Tous les recensés que dénombrèrent Moïse, Aaron et les chefs lévites d’Israël, par branches et par maisons paternelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'De vingt-cinq ans et au-dessus jusqu’à cinquante, tous ceux qui entraient dans le tabernacle du témoignage, pour l’œuvre des œuvres, et pour transporter ce qu’il y avait à enlever,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Tous ces recensés furent au nombre de huit mille cinq cent quatre-vingts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'On les recensa selon l’ordre donné par le Seigneur à Moïse, homme par homme, en désignant à chacun sa part de labeur, et ce qu’il aurait à emporter; le recensement s’opéra comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Ordonne aux fils d’Israël de chasser du camp tout lépreux, toute personne atteinte de la gonorrhée, toute personne souillée à cause d’un mort,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Homme ou femme: qu’ils les chassent du camp, qu’ils ne les laissent point souiller le camp où j’habite avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Et les fils d’Israël obéirent; ils chassèrent du camp ces personnes, comme le Seigneur l’avait prescrit à Moïse; ainsi firent les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Le Seigneur dit encore à Moise:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Parle aux fils d’Israël et dis-leur: L’homme ou la femme qui aura commis des péchés humains, qui aura méprisé les commandements, et se sera rendu coupable d’un délit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Confessera son péché et rachètera son délit; le cinquième en sus sera ajouté au capital et payé à celui qui aura souffert du délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Et si nul ne se présente pour exiger la réparation, la réparation offerte au Seigneur appartiendra au prêtre, outre le bélier de propitiation que l’on aura immolé, et avec lequel on offrira, pour le délinquant, un sacrifice propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Toutes les prémices habituellement consacrées par les fils d’Israël, que l’on aura présentées au Seigneur, appartiendront aussi au prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Ce que chacun a offert sur l’autel lui appartient, ce que l’on en donne au prêtre est à celui-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Le Seigneur dit aussi à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Parle aux fils d’Israël, et dis-leur: Lorsqu’une femme aura manqué à son mari et l’aura méprisé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'En ayant eu commerce avec un homme; quand même elle eût échappé aux regards de son mari et réussi à cacher sa faute, quand même elle eût péché sans témoin et eût été souillée sans avoir pu être surprise;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Si l’époux est saisi d’un esprit de jalousie, s’il est jaloux de sa femme qui est souillée, ou bien si l’époux est saisi d’un esprit de jalousie, s’il est jaloux de sa femme, quoiqu’elle n’ait pas été souillée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Il la conduira devant le prêtre, et il fera, à son occasion, l’offrande d’un décime d’éphi de fleur de farine d’orge, sur laquelle il ne versera pas d’huile et ne posera pas d’encens; car c’est un sacrifice de jalousie, un mémorial rappelant le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Ensuite, le prêtre conduira la femme, et il la placera devant le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Puis, il prendra de l’eau vive et pure dans un vase de poterie; il ramassera de la poussière sur le sol du tabernacle, et la jettera dans l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Et le prêtre placera la femme devant le Seigneur, il lui découvrira la tête, et lui donnera à tenir le mémorial, le sacrifice de jalousie, et il gardera dans sa main l’eau du reproche et des malédictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Après quoi, le prêtre adjurera la femme, et il lui dira: Si personne n’a eu commerce avec toi, si tu n’as point failli et n’es point souillée devant ton époux, pars impunie, éloigne-toi de l’eau du reproche et des malédictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mais si, étant sous puissance de mari, tu as été souillée, si autre que ton mari a eu commerce avec toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Je t’adjure, et tes faux serments attireront sur toi cette malédiction: que le Seigneur te donne sa malédiction comme parjure, qu’au milieu de ton peuple le Seigneur fasse tomber ta cuisse, qu’il fasse éclater ton ventre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Cette eau maudite va entrer dans ton sein pour faire éclater ton ventre et faire tomber ta cuisse; et la femme répondra: Amen, amen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Le prêtre écrira les malédictions en un livre, et il les effacera dans l’eau du reproche et des malédictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Et la femme boira de l’eau du reproche et des malédictions; l’eau maudite du reproche entrera dans son sein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Le prêtre prendra ensuite, des mains de la femme, le sacrifice de jalousie, et il placera l’oblation devant le Seigneur; il la portera sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Et le prêtre prendra une poignée de l’oblation pour en être le mémorial, et il en fera l’offrande sur l’autel; après quoi, la femme boira le reste de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Et ceci arrivera si elle a été souillée, si, en se cachant, elle a échappé aux regards de son mari, aussitôt que l’eau maudite du reproche entrera dans son sein, ses entrailles s’enfleront, sa cuisse tombera, et la femme sera maudite par tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mais si la femme n’a pas été souillée, si elle est pure, elle partira impunie et redeviendra féconde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Telle est la loi de la jalousie en vertu de laquelle la femme sous puissance de mari ayant péché, ayant été souillée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Ou bien l’époux ayant été saisi d’un esprit de jalousie, étant devenu jaloux de sa femme, il la placera devant le Seigneur pour que le prêtre accomplisse ce que la loi prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Par là l’homme sera exempt de péché, et la femme portera son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Parle aux fils d’Israël, et dis-leur: La femme ou l’homme qui aura fait généreusement le vœu de se consacrer au Seigneur et de rester pur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'S’abstiendra de vin et de boisson fermentée; ne boira ni vinaigre de vin, ni vinaigre de boisson fermentée; ne boira rien de ce qui se fait avec le raisin; ne mangera pas de raisin, soit frais cueilli, soit séché au soleil,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Durant tous les jours du vœu; la personne vouée ne mangera rien de ce qui provient de la vigne ou du raisin, depuis le pépin jusqu’à la peau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Durant tous les jours de la purification; elle ne se passera point le rasoir sur la tête jusqu’à la fin des jours qu’elle aura voués au Seigneur; elle sera sainte en laissant croître la chevelure de sa tête,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Durant tous les jours du vœu au Seigneur; elle ne s’approchera d’aucune créature morte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Elle ne se souillera point à cause d’un père mort, ni d’une mère, ni d’un frère, ni d’une sœur, parce qu’elle aura sur soi-même et sur la tête le vœu à Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Durant tous les jours du vœu, elle sera sainte, consacrée au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Si quelqu’un tombe mort subitement auprès de la personne qui s’est vouée, son vœu en sera souillé, et elle se rasera la tête le jour même de sa purification; elle se rasera une seconde fois la tête le septième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Et le huitième, elle portera au prêtre deux tourterelles ou deux petits de colombes, devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Et le prêtre en offrira un pour le péché, et l’autre pour l’holocauste; le prêtre intercédera pour elle au sujet de la souillure que lui aura causée le mort, et il consacrera sa tête, en ce jour,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Au Seigneur, pour toute la durée du vœu; et la personne offrira un agneau d’un an pour le délit; et les jours qui auront précédé ne lui seront pas comptés, parce que son vœu aura été souillé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Telle est la loi des vœux; lorsque les jours du vœu seront accomplis, la personne présentera elle-même ses dons, devant la porte du tabernacle du témoignage;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Elle offrira au Seigneur un agneau d’un an sans tache pour l’holocauste, une brebis d’un an sans tache pour le péché, un bélier d’un an sans tache comme hostie pacifique,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Une corbeille d’azymes de fleur de farine, pétris dans l’huile, et des gâteaux azymes arrosés d’huile, avec leur oblation et leur libation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Le prêtre offrira ces dons au Seigneur, et il sacrifiera les victimes pour le péché et pour l’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Il offrira le bélier, comme hostie pacifique, au Seigneur, outre la corbeille d’azymes. Et le prêtre fera l’oblation et la libation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Alors, la personne vouée rasera, devant la porte du tabernacle du témoignage, sa tête vouée, et elle jettera sa chevelure dans le feu allumé sous l’hostie pacifique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Et le prêtre prendra l’épaule cuite du bélier, avec un pain azyme de la corbeille, et un gâteau azyme; il les mettra dans la main de la personne vouée, après qu’elle aura rasé sa tête vouée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Puis, le prêtre les déposera sur l’autel, comme part du Seigneur, et ce sera chose sainte; ce sera la poitrine mise à part, l’épaule réservée, appartenant au prêtre; après cela, la personne vouée pourra boire du yin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Telle est la loi de la personne qui fait un vœu et du présent qu’elle doit offrir au Seigneur à cette occasion, sans parler des dons que ses facultés lui permettent de faire, selon l’extension de son vœu, et conformément à la loi de consécration.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Parle à Aaron et à ses fils; dis-leur: Voici comme vous bénirez les fils d’Israël; vous leur direz:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Que le Seigneur te bénisse et te garde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Que le Seigneur fasse luire sur toi son visage, et qu’il ait pitié de toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Qu’il lève sur toi sa face, et qu’il t’accorde la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Et ils feront descendre mon nom sur les fils d’Israël, et moi, le Seigneur, je les bénirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Le même jour où il eut achevé de dresser le tabernacle du témoignage, Moïse l’oignit et le sanctifia, ainsi que les ornements, l’autel et ses accessoires; il les oignit et les sanctifia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Et les princes d’Israël firent leurs offrandes; c’étaient les douze chefs de leurs maisons paternelles, les chefs des tribus, ceux qui avaient présidé au recensement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Ils amenèrent leurs présents devant le Seigneur: six grands chariots couverts et douze bœufs, un chariot pour deux chefs, un bœuf pour chacun; et ils les conduisirent devant le tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Et le Seigneur dit à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Accepte-les d’eux, ils seront employés aux œuvres liturgiques du tabernacle du témoignage, et tu les donneras aux lévites, selon la nature de leurs services.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Moïse accepta donc les chariots avec les bœufs, et il les donna aux lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Il donna deux chars et quatre bœufs aux fils de Gerson, en proportion de leur service liturgique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Il donna quatre chars et huit bœufs aux fils de Mérari, en proportion de leur service liturgique, dirigé par Ithamar, fils d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Mais il ne donna rien aux fils de Caath, parce que leur service se fait dans l’intérieur du sanctuaire, et qu’ils portent les objets sur leurs épaules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Les princes firent aussi des offrandes pour la dédicace de l’autel, le jour où il fut oint, et apportèrent leurs présents devant l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Et le Seigneur dit à Moïse: Les princes offriront jour par jour leurs présents pour la dédicace de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Nahasson, fils d’Aminadab, chef de la tribu de Juda, fut celui qui fit son présent le premier jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Il offrit un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine, pétrie dans l’huile, pour l’oblation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Une navette d’or du poids de dix sicles, remplie de parfums.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Un veau pris parmi les bœufs, un bélier, un agneau d’un an pour l’holocauste,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Un bouc pris parmi les chèvres, offert pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Et, comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande de Nahasson, fils d’Aminadab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Le second jour, Nathanaël, fils de Sogar, chef de la tribu d’Issachar, fit son présent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Il offrit un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile pour l’oblation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Une navette d’or du poids de six sicles, remplie de parfums,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Un veau pris parmi les bœufs, un bélier, un agneau d’un an pour l’holocauste,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Un bouc pris parmi les chèvres, offert pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Et, comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande de Nathanaël, fils de Sogar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Au troisième jour, ce fut Eliab, fils de Chaïlon, chef de la tribu de Zabulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Son présent consistait en un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile pour l’oblation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Une navette d’or du poids de dix sicles, remplie de parfums,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Un veau pris parmi les bœufs, un bélier, un agneau d’un an pour l’holocauste,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Un bouc pris parmi les chèvres, offert pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Comme hosties pacifiques, il offrit deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande d’Eliab, fils de Chaïlon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Le quatrième jour fut le tour d’Elisur, fils de Sédiur, de la tribu de Ruben.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Son présent consistait en un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pour l’oblation,');
