INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Un bouc pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Comme hosties pacifiques, il offrit deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande d’Elisur, fils de Sédiur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Au cinquième jour ce fut Salamiel, fils de Surisadaï, chef de la tribu de Siméon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Il offrit un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pour l’oblation;');
