INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'Et, comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande de Salamiel, fils de Surisadaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Au sixième jour ce fut Elisaph, fils de Raguel, chef de la tribu de Gad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Son offrande fut un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile, pour l’oblation;');
