INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Le septième jour fut le tour d’Elisama, fils d’Emiud, chef de la tribu d’Ephraïm,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Qui donna pour offrande un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile, pour l’oblation;');
