INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'Et, comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande d’Elisama, fils d’Emiud.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Le huitième jour ce fut Gamaliel, fils de Phadasur, chef de la tribu de Manassé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Qui offrit un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile, pour l’oblation;');
