INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'Et, comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande de Gamaliel, fils de Phadasur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Au neuvième jour ce fut Abidan, fils de Gadéoni, chef de la tribu de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Son offrande consistait en un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile, pour l’oblation;');
