INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'Comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande d’Abidan, fils de Gadéoni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Le dixième jour, Achiézer, fils d’Amisadaï, chef de la tribu de Dan, fit son offrande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Elle consistait en un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile, pour l’oblation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Une navette d’or du poids de dix sicles, remplie de parfums,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Un veau pris parmi les bœufs, un bélier, un agneau d’un an pour l’holocauste,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Un bouc pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Comme hosties pacifiques, il donna deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande d’Achiézer, fils d’Amisadaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Au onzième jour, Phagéel, fils d’Echran, chef de la tribu d’Aser,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Offrit un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile, pour l’oblation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Une navette d’or du poids de dix sicles, remplie de parfums,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Un veau pris parmi les bœufs, un bélier, un agneau d’un an pour l’holocauste,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Un bouc pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Et, comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande de Phagéel, fils d’Echran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Le douzième jour l’offrande fut celle d’Achire, fils d’Enan, chef de la tribu de Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'C’étaient un plat d’argent du poids de cent trente doubles drachmes, une coupe d’argent de soixante-dix sicles au poids du sanctuaire, l’un et l’autre remplis de fleur de farine pétrie dans l’huile, pour l’oblation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Une navette d’or du poids de dix sicles, remplie de parfums,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Un veau pris parmi les bœufs, un bélier, un agneau d’un an pour l’oblation,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Un bouc pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Et, comme hosties pacifiques, deux génisses, cinq béliers, cinq boucs, cinq brebis d’un an. Telle fut l’offrande d’Achire, fils d’Enan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Telle fut la dédicace de l’autel, le jour où Moïse l’oignit; les chefs d’Israël donnèrent douze plats d’argent, douze coupes d’argent, douze navettes d’or,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Cent trente sicles par plat, soixante-dix sicles par coupe; total de l’argent de ces pièces deux mille quatre cents sicles au poids du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Douze navettes d’or, pleines de parfums; total de l’or des navettes: cent vingt sicles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Total des têtes pour l’holocauste: douze veaux, douze béliers, douze agneaux d’un an, outre leurs oblations et leurs libations; total des têtes pour le péché: douze boucs pris parmi les chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Total des têtes d’hosties pacifiques: vingt-quatre génisses, soixante béliers, soixante boucs, soixante brebis d’un an sans tache. Telle fut la dédicace de l’autel après qu’on l’eut couvert de présents et qu’on l’eut oint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Et lorsque Moïse entrait dans le tabernacle du témoignage pour parler au Seigneur, il entendait la voix du Seigneur lui parlant du haut du propitiatoire, qui était sur l’autel du témoignage, entre les deux chérubins; c’est ainsi que le Seigneur lui parlait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Le Seigneur dit encore à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Parle à Aaron, et dis-lui: Lorsque tu auras disposé en rang les lampes du chandelier, les sept lampes éclaireront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Et ainsi fit Aaron; il alluma, sur une seule rangée, les lampes du chandelier, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Voilà comme était fabriqué le chandelier: il était d’or inflexible, tige et lis, selon la forme que le Seigneur avait indiquée à Moïse; ainsi avait-il fait le chandelier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Prends les lévites parmi les fils d’Israël, et purifie-les.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Voilà comment tu feras cette purification: tu les aspergeras de l’eau de la purification; on passera le rasoir sur tout leur corps; ils laveront leurs vêtements, et ils seront purs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Ensuite, ils prendront un veau parmi les bœufs, avec de la fleur de farine pétrie dans l’huile, pour son oblation; tu prendras encore, parmi les bœufs, un veau d’un an pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Et tu conduiras les lévites devant le tabernacle du témoignage. Là, après avoir rassemblé toute la synagogue des fils d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Tu présenteras les lévites devant le Seigneur, et les fils d’Israël imposeront leurs mains sur la tête des lévites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Aaron les séparera des fils d’Israël, comme une offrande faite au Seigneur; et les lévites seront pour travailler aux œuvres du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Ensuite, les lévites imposeront leurs mains sur les veaux, et tu sacrifieras l’un pour le péché, l’autre pour l’holocauste au Seigneur, afin que ce sacrifice leur soit propitiatoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Tu placeras alors les lévites en présence du Seigneur, devant Aaron et ses fils, et tu les donneras au Seigneur comme offrande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Ainsi, tu sépareras les lévites des fils d’Israël, et ils seront à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Après cela, les lévites seront introduits pour travailler aux œuvres du tabernacle; c’est ainsi que tu les purifieras, et que tu en feras l’offrande devant le Seigneur, car ils sont l’offrande qui m’est due parmi les fils d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'En échange de tous les premiers-nés des fils d’Israël; je les ai pris pour moi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Parce que tout premier-né, parmi les fils d’Israël, m’appartient, depuis l’homme jusqu’aux bestiaux; le jour où j’ai frappé tout premier-né en Égypte, je me suis consacré les premiers-nés d’Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Et j’ai pris les lévites en échange des premiers-nés d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Les lévites m’ayant été donnés en offrande, je les ai donnés moi-même à Aaron et à ses fils, afin qu’ils fassent les œuvres des fils d’Israël dans le tabernacle du témoignage, et qu’ils prient pour les fils d’Israël; et nul des fils d’Israël ne s’approchera des choses saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Moïse, avec Aaron et toute la synagogue des fils d’Israël, fit donc, au sujet des lévites, ce que le Seigneur lui avait prescrit; et ainsi les fils d’Israël firent pour les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Et les lévites se purifièrent; ils lavèrent leurs vêtements; après quoi, Moïse les donna à Aaron, comme offrande au Seigneur. Ce dernier pria pour eux, afin de les purifier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Et, après cela, les lévites entrèrent pour faire leur service liturgique dans le tabernacle du témoignage, devant Aaron et ses fils, comme le Seigneur l’avait prescrit à Moïse; ainsi fit-on pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Voici encore ce qui concerne les lévites: À vingt-cinq ans et au-dessus, ils entreront, pour leur ministère, dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'À cinquante ans, ils s’éloigneront du service saint; à cet âge, nul lévite n’y sera employé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Son frère exercera le ministère dans le tabernacle du témoignage; lui-même ne fera plus rien. Tu régleras ainsi les fonctions des lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Et le Seigneur parla à Moïse dans le désert de Sina, en la seconde année depuis leur sortie d’Égypte, pendant le premier mois, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Parle, et que les fils d’Israël fassent la pâque au moment indiqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Le quatorzième jour de la première lune, sur le soir, tu feras la pâque comme il est prescrit; tu la feras selon sa loi et ses rites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Moïse ordonna donc aux fils d’Israël de célébrer la pâque,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'À partir du quatorzième jour de la lune, dans le désert de Sina, comme le Seigneur le lui avait prescrit; et ils obéirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Cependant, quelques hommes qui étaient impurs à cause d’un mort s’approchèrent; empêchés par là de faire la pâque ce même jour, ils vinrent auprès d’Aaron et de Moïse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Et ils dirent à ce dernier: Nous qui sommes impurs à cause d’un mort, devons nous seuls, parmi les fils d’Israël, être privés d’offrir des dons au Seigneur, dans le temps qu’il a prescrit?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Attendez, leur répondit Moïse; je vais ouïr ce que le Seigneur ordonnera vous concernant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Et le Seigneur dit à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Parle aux fils d’Israël, et dis-leur: Tout homme qui sera impur à cause d’un mort, ou qui sera en voyage loin de vous, en toutes vos générations, fera aussi la pâque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Le quatorzième jour de la seconde lune au soir, il la célébrera; il la mangera avec des azymes et des légumes amers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Il n’en laissera rien pour le jour suivant; il n’en broiera pas les os; il fera la pâque selon la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Tout homme pur qui ne sera pas en voyage au loin, et qui manquera de faire la pâque, sera exterminé parmi le peuple, pour n’avoir pas fait d’offrande au Seigneur dans le temps prescrit; cet homme portera son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Et si un prosélyte s’est réuni à vous en votre terre, il fera aussi la pâque du Seigneur; il la fera selon la loi et les rites; il n’y aura qu’une loi parmi vous pour le prosélyte et pour l’indigène.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Le jour où fut dressé le tabernacle, une nuée enveloppa la maison du témoignage. Et le soir, il y eut, sur le tabernacle, comme un feu jusqu’au matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Et il en fut de même toujours; le tabernacle fut enveloppé le jour d’une nuée, et comme d’un feu pendant la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Lorsque la nuée montait et s’éloignait du tabernacle, aussitôt les fils d’Israël levaient le camp, et au lieu où la nuée s’arrêtait les fils d’Israël stationnaient. Car il leur avait été dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Les fils d’Israël stationneront et lèveront leur camp à l’ordre du Seigneur; tous les jours pendant lesquels la nuée ombragera le tabernacle, les fils d’Israël camperont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Aussi longtemps que la nuée sera étendue sur le tabernacle, les fils d’Israël obéiront à l’ordre de Dieu, et ils ne lèveront point leur camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Et, dociles à la voix du Seigneur, ils s’arrêteront tant que la nuée ombragera le tabernacle; au commandement du Seigneur, ils lèveront leur camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Lorsque la nuée aura persisté du soir au matin et qu’elle s’enlèvera le matin, ils lèveront le camp dans la journée ou dans la nuit suivante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Et si la nuée maintient son ombre au delà d’une lune entière, les fils d’Israël continueront de camper, et ils ne se mettront point en marche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Ils ne partiront qu’au commandement du Seigneur; tels étaient les commandements de Dieu que leur avait transmis Moïse; ils s’y conformaient et ils obéissaient aux ordres du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Fais deux trompettes d’argent, fais-les au marteau; elles te serviront à convoquer la synagogue et à lever le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Lorsque tu les feras sonner, toute la synagogue se rassemblera devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Si une seule trompette sonne, les chefs d’Israël seuls viendront auprès de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Si elles font entendre toutes les deux un signal convenu, on enlèvera les tentes qui sont tendues à l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'À un second signal, on enlèvera les tentes qui sont tendues au midi; au troisième signal, on enlèvera les tentes qui sont tendues à l’occident; au quatrième signal, on enlèvera les tentes qui sont au nord; chaque enlèvement de tentes aura son signal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Et pour rassembler la synagogue, on sonnera des deux trompettes; mais sans aucun de ces signaux convenus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Ce sont les prêtres fils d’Aaron qui sonneront des trompettes; ce sera une loi perpétuelle pour vous, en toutes vos générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Lorsque vous sortirez de votre terre pour combattre vos ennemis rangés devant vous, vous donnerez les signaux au son des trompettes, et le Seigneur se souviendra de vous, et vous serez sauvés des mains de vos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Dans vos fêtes et jours de réjouissance, ainsi qu’aux nouvelles lunes, on sonnera de la trompette pour vos holocaustes et pour vos hosties pacifiques, et le Seigneur se souviendra de vous je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'En la seconde année, au second mois, le vingtième jour de la lune, la nuée monta et s’éloigna du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Et les fils d’Israël, avec tous leurs bagages, levèrent leur camp du désert de Sina; la nuée s’arrêta sur le désert de Pharan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'La première troupe qui se mit en marche, selon l’ordre du Seigneur transmis par Moïse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Fut celle des fils de Juda, ayant à sa tête Nahasson, fils d’Aminadab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'À la tête de l’armée de la tribu des fils d’Issachar, était Nathanaël, fils de Sogar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Et à la tête de l’armée de la tribu des fils de Zabulon, Eliud, fils de Chaïlon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Les fils de Gerson détendirent le tabernacle et partirent, suivis des fils de Mérari, qui transportèrent le tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Ensuite se mirent en marche les troupes du camp des fils de Ruben, ayant à leur tête Elisur, fils de Sédiur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'À la tête de l’armée de la tribu des fils de Siméon, était Salamiel, fils de Surisadaï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Et à la tête de l’armée de la tribu des fils de Gad, Elisaph, fils de Raguel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Les fils de Caath partirent ensuite, emportant les choses saintes pour dresser le tabernacle au lieu de l’arrivée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Après eux, partirent les troupes du camp d’Ephraïm, ayant à leur tête Elisama, fils d’Emiud.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'À la tête de l’armée de la tribu des fils de Manassé, était Gamaliel, fils de Phadasur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Et à la tête de l’armée de la tribu des fils de Benjamin, était Abidan, fils de Gadéoni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'La troupe du camp des fils de Dan partit la dernière, ayant à sa tête Achiézer, fils d’Amisadaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'À la tête de l’armée de la tribu des fils d’Aser, était Phagéel, fils d’Echran,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Et à la tête de l’armée de la tribu des fils de Nephthali, Achire, fils d’Enan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Telles étaient les armées des fils d’Israël, qui décampèrent ainsi avec toutes leurs possessions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Alors, Moïse dit à Obad, fils du Madianite Raguel, beau-père de Moïse: Nous partons pour le lieu dont le Seigneur a dit: Je vous le donnerai. Viens avec nous, et nous te traiterons bien, car le Seigneur a fait de belles promesses aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Et Obad lui répondit: Je ne partirai point, si ce n’est pour ma terre, afin de rejoindre ma famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Ne nous abandonne pas, lui repartit Moïse, puisque tu nous as accompagnés dans le désert, et tu seras l’un de nos anciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Si tu viens avec nous, tu auras part aux bienfaits que nous attendons du Seigneur, et nous te traiterons bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Après avoir quitté la montagne du Seigneur, ils firent trois journées de marche, et pendant ce voyage de trois jours, l’arche du témoignage les précédait, pour qu’ils reconnussent le lieu où ils devaient s’arrêter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Dès la pointe du jour, la nuée les couvrait de son ombre pendant qu’ils abandonnaient leur campement de la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Et toutes les fois que l’on enlevait l’arche, Moïse disait Levez-vous, Seigneur, que vos ennemis soient mis en fuite, et que tous ceux qui vous haïssent soient dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Toutes les fois que l’on faisait reposer l’arche, il disait: Revenez, Seigneur, auprès des myriades de myriades des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Alors, le peuple murmura méchamment contre le Seigneur qui l’entendit, et, transporté de colère, il alluma un feu qui dévora une partie du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Aussitôt, le peuple, à grands cris, invoqua Moïse, qui pria le Seigneur, et le feu s’éteignit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Et ils nommèrent ce lieu Embrasement, parce que le Seigneur au milieu d’eux l’avait embrasé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Ensuite les étrangers mêlés parmi eux furent saisis de concupiscence, et les fils d’Israël aussi s’assirent en pleurant et disant: Qui nous rassasiera de chairs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Nous nous souvenons des poissons que nous mangions pour rien en Égypte, et des pastèques, des melons, des poireaux, des oignons et de l’ail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Et maintenant notre âme est toute desséchée, rien devant nos yeux, hormis la manne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Or, la manne était comme de la graine de coriandre, son aspect était celui du givre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Le peuple la recueillait çà et là, puis il la broyait sous la meule, et il la mettait en pâte; enfin on la faisait cuire à la poêle ou on en faisait des gâteaux, qui avaient la saveur de gâteaux à l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Et lorsque la rosée du matin descendait sur le camp, la manne tombait avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Or, Moïse entendit les lamentations de leurs familles, chacune devant sa porte. Et le Seigneur fut transporté d’une violente colère; Moïse lui-même jugea qué les pleurs étaient coupables,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Et il dit au Seigneur: Pourquoi affligez-vous votre serviteur? Pourquoi n’ai-je pas trouvé grâce devant vous, quand vous m’avez exposé aux chocs de ce peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Ai-je donc porté ce peuple tout entier dans mes flancs? Est-ce moi qui l’ai enfanté pour que vous me disiez: Prends ce peuple sur ton sein, comme le nouveau-né que la nourrice allaite, jusqu’à ce qu’il arrive en la contrée promise à ses pères?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Où trouver des chairs pour tout ce peuple qui m’invoque en pleurant, et me dit: Donne-nous des chairs et que nous mangions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Je ne puis seul porter tout ce peuple; c’est pour moi un trop pesant fardeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Si vous continuez de me traiter ainsi, tuez-moi, enlevez-moi, si j’ai trouvé grâce devant vous; que je ne voie plus mon affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Et le Seigneur dit à Moïse: Rassemble soixante-dix des anciens d’Israël, de ceux qui te sont connus comme anciens du peuple; amène-les avec leurs scribes devant la porte du tabernacle du témoignage, et qu’ils s’y tiennent avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Et j’y descendrai pour m’entretenir avec toi; je prendrai de l’esprit qui est en toi, et je le répandrai sur eux, et ils porteront avec toi le fardeau du peuple, et tu ne seras pas seul à le soutenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Et tu diras au peuple: Purifiez-vous dès l’aurore et vous mangerez des chairs, puisque vous avez pleuré devant le Seigneur, disant: Qui nous rassasiera de chairs? C’est en Égypte qu’il faisait bon pour nous. Le Seigneur vous donnera des chairs à manger; vous mangerez de la chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Vous n’en mangerez pas seulement un jour, deux jours, cinq jours, dix jours, vingt jours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Vous en mangerez tout le mois, jusqu’à ce qu’elle vous sorte par les narines, et elle sera pour vous comme un choléra, parce que vous n’avez point eu foi au Seigneur qui est parmi vous, et que vous avez pleuré devant lui, disant Pourquoi sommes-nous sortis de l’Égypte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Moïse répondit: Ce peuple parmi lequel je me trouve compte six cent mille hommes à pied, et vous dites, Seigneur: Je leur donnerai à manger, et ils mangeront pendant un mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Quand on égorgerait pour eux bœufs et brebis, en auraient-ils assez? Quand on réunirait tous les poissons de la mer, leur pourraient-ils suffire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Le Seigneur dit à Moise: La main du Seigneur ne suffit-elle point à tout? Tu sauras bientôt si c’est ou non ma parole qui t’arrive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Moïse sortit, et il rapporta au peuple les paroles du Seigneur; il réunit soixante-dix hommes des anciens du peuple, et il les plaça devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Et le Seigneur descendit dans une nuée, d’où il parla à Moïse; il prit de l’esprit qui était en lui, et le répandit sur les soixante-dix anciens, et dès que l’esprit se posa sur eux, ils prophétisèrent, et ils ne se conduisirent plus selon leur bon plaisir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Or, deux hommes avaient été laissés dans le camp, l’un nommé Eldad et l’autre Modad, et l’esprit se posa aussi sur eux; ils étaient de ceux qu’on avait inscrits, mais ils n’étaient point allés devant le tabernacle; toutefois, ils prophétisèrent dans le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Aussitôt un jeune homme accourut pour l’apprendre à Moïse. Eldad et Modad, lui dit-il, prophétisent dans le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Et Josué, fils de Nau, qui se tenait auprès de Moïse, homme excellent, prenant la parole, dit: Moïse, notre maître, empêche-les.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Et Moïse lui dit: Es-tu mon zélateur? Puisse tout le peuple du Seigneur prophétiser, quand le Seigneur répand sur eux son esprit!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Et Moïse rentra dans le camp, avec les anciens d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Alors, un vent s’éleva, excité par le Seigneur, poussant à travers la mer une nuée de cailles qu’il jeta çà et là tout alentour du camp, jusqu’à la distance d’une journée de marche, et elles volaient à deux coudées au-dessus de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Et le peuple, s’étant levé, passa le jour entier, la nuit et tout le jour suivant, à recueillir des cailles; celui qui en eut le moins en ramassa dix mesures, et ils en mirent sécher pour eux tout autour du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Mais les chairs étaient encore sous leurs dents; elles n’étaient point consommées, lorsque le Seigneur s’irrita contre le peuple, et le frappa d’une très-grande plaie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Et l’on nomma ce lieu Sépulcres de la concupiscence, parce qu’on y ensevelit le peuple qui avait trop désiré. Des Sépulcres de la concupiscence le peuple partit pour Aseroth, et le peuple s’arrêta en Aseroth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Cependant, Marie avec Aaron parla contre Moïse, à cause de la femme éthiopienne que Moïse avait épousée, car il avait pris une femme éthiopienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Et ils se dirent l’un à l’autre: Est-ce à Moïse seul que le Seigneur a parlé? Ne a-t-il pas parlé pareillement? Et le Seigneur entendit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Or, Moïse était le plus doux des hommes existant alors sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Soudain le Seigneur dit à Moïse, à Aaron et à Marie: Sortez tous les trois, allez au tabernacle du témoignage. Et ils sortirent tous les trois pour aller au tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Le Seigneur descendit en une colonne de nuée, et il s’arrêta devant la porte du tabernacle du témoignage. Aaron et Marie furent appelés, et tous les deux s’avancèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Le Seigneur leur dit: Écoutez ce que je vais dire: Lorsqu’il y aura parmi vous un prophète du Seigneur, je me manifesterai à lui en des visions, et je lui parlerai pendant son sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Il n’en est pas ainsi de mon serviteur Moïse, qui m’est fidèle entre tous ceux de ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'À lui je parlerai bouche à bouche clairement, et non en termes obscurs; il a vu la gloire du Seigneur: comment donc n’avez-vous pas crainte de parler contre mon serviteur Moïse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Et la colère du Seigneur éclata contre eux, et le Seigneur partit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'La nuée s’éloigna du tabernacle, et aussitôt Marie se trouva couverte d’une lèpre blanche comme neige; Aaron la regarda, et voilà qu’elle était lépreuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Et Aaron dit à Moïse: Je te conjure, Seigneur, ne nous fais pas porter la peine de notre péché, car nous avons commis une ignorance, nous avons péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Que ce mal n’aille pas la rendre semblable à un cadavre, à un avorton qui sort des entrailles de sa mère, et ronger la moitié de ses chairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Aussitôt, Moïse invoqua le Seigneur, et il dit: 0 Dieu, je vous en conjure, guérissez-la.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Le Seigneur répondit à Moïse: Si son père lui eût craché au visage, ne serait-elle pas sept jours dans sa honte? Qu’elle soit donc séparée sept jours hors du camp, ensuite elle Y reviendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Marie fut donc séparée sept jours hors du camp, et le peuple ne partit pas qu’elle ne fût purifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Après cela le peuple, étant parti d’Aseroth, campa dans le désert de Pharap.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Envoie devant toi des hommes; qu’ils reconnaissent la terre de Chanaan que je donne aux fils d’Israël afin qu’ils s’y établissent; envoie un homme par tribu, par famille paternelle; prends-le parmi les princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Et, selon l’ordre du Seigneur, Moïse fit partir du désert de Pharan des hommes tous princes des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Et voici leurs noms: De la tribu de Ruben, Samuel, fils de Zachur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'De la tribu de Siméon, Saphat, fils de Suri;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'De la tribu de Juda, Caleb, fils de Jéphoné;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'De la tribu d’Issachar, Ilaal, fils de Joseph;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'De la tribu d’Ephraïm, Osée, fils de Nau;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'De la tribu de Benjamin, Phalti, fils de Raphu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'De la tribu de Zabulon, Gudiel, fils de Sudi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'De la tribu de Manassé, fils de Joseph, Gaddi, fils de Susi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'De la tribu de Dan, Amiel, fils de Gamali;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'De la tribu d’Aser, Sathur, fils de Michel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'De la tribu de Nephthali, Nabi, fils de Sabi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'De la tribu de Gad, Gudiel, fils de Machi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Tels sont les noms des hommes que Moïse envoya reconnaître la terre promise; or, Moïse avait donné à Osée, fils de Nau, le surnom de Josué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Moïse les envoya reconnaître la terre de Chanaan, et il leur dit: Traversez ce désert et montez sur la colline;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Vous verrez ce qu’est cette terre; quel est le peuple qui l’habite, s’il est puissant ou faible, s’ils sont peu ou beaucoup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Vous verrez aussi ce qu’est la terre en laquelle ils demeurent, si elle est bonne ou mauvaise; l’état des villes qu’ils habitent, si elles sont ouvertes ou entourées de remparts;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Si la terre est grasse ou stérile, si elle produit ou non des arbres; vous ferez plus, vous rapporterez des fruits de cette terre; or, on était aux jours du printemps qui précèdent la maturité de la grappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Et ils marchèrent en explorant la terre depuis le désert de Sin, jusqu’à Rohob à l’entrée d’Emath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Ils montèrent le long du désert, et ils poussèrent jusqu’à Hébron, où résidaient Achiman, Sessi et Thelami, issus d’Enac; Hébron avait été fondée sept ans avant Tanis d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Arrivés au vallon de la Grappe, ils l’explorèrent; ils y prirent un rameau avec sa grappe et ils l’emportèrent sur des leviers; ils cueillirent aussi des grenades et des figues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Et ils nommèrent ce lieu vallon de la Grappe, à cause de celle qu’ils y avaient coupée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Ils revinrent ensuite après avoir exploré la terre pendant quarante jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Et, ayant marché, ils rejoignirent Aaron et Moïse, et toute la synagogue des fils d’Israël, dans le désert de Pharan-Cadès; ils rendirent compte de leur voyage à eux et à toute la synagogue, et ils montrèrent les fruits de la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Et, s’adressant à Moïse, ils dirent: Nous sommes allés en la terre où tu nous as envoyés; c’est une terre où coulent le lait et le miel, et voilà ses fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Mais que la nation qui l’habite est vaillante! Combien il y a de villes fortes entourées de superbes remparts! Nous y avons vu les enfants d’Enac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Amalec demeure au midi de cette terre; l’Hettéen, et le Jébuséen, et l’Amorrhéen, habitent la région montagneuse; le Chananéen occupe les rives de la mer Morte et du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Et Caleb fit taire le peuple qui entourait Moïse, et il dit: N’importe, nous marcherons et nous nous partagerons cette terre; nous sommes assez forts pour prévaloir contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Mais ses compagnons disaient: N’y allons pas, nous ne pourrons vaincre ces peuples, ils sont plus puissants que nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Ainsi ils inspirèrent aux enfants d’Israël la crainte de la terre qu’ils avaient explorée, et ils dirent: La terre où nous avons passé pour la reconnaître, dévore ceux qui s’y établissent; le peuple que nous y avons trouvé est d’une très-grande taille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 34, 'Nous y avons vu des géants, auprès desquels nous étions comme des sauterelles; voilà ce que nous étions auprès d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Et toute la synagogue, élevant la voix, jeta les hauts cris; toute cette nuit, le peuple pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Bientôt, tous les fils d’Israël murmurèrent contre Aaron et Moïse, et toute la synagogue leur dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Que ne sommes-nous morts en la terre d’Égypte! que ne sommes-nous morts dans ce désert! Pourquoi le Seigneur nous conduit-il contre un pays où nous périrons en combattant? Nos femmes, nos enfants seront la proie des vainqueurs; maintenant donc il vaut mieux retourner en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Et ils se disaient l’un à l’autre: Donnons-nous un chef et retournons en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Alors, Moïse et Aaron tombèrent la face contre terre devant toute la synagogue des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Et parmi ceux qui avaient exploré cette terre, Josué, fils de Nau, et Caleb, fils de Jéphoné, déchirèrent leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Et ils dirent à toute la synagogue des fils d’Israël: La terre que nous avons explorée est extrêmement fertile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Puisque le Seigneur nous a choisis, il nous conduira en cette terre et il nous la donnera; c’est une terre où coulent le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Ne soyez donc point rebelles au Seigneur, n’ayez aucune crainte de ces peuples, ils seront notre pâture; leur fortune les abandonne, ne les redoutez pas, le Seigneur est avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Et toute la synagogue s’écria: Lapidons-les. Mais la gloire du Seigneur apparut dans la nuée aux yeux de tous les fils d’Israël, devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Et le Seigneur dit à Moïse: Jusqu’à quand ce peuple m’irritera-t-il? jusqu’à quand refusera-t-il de croire en moi, malgré tous les prodiges que j’ai faits pour lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Je les frapperai à mort; je les exterminerai; et je ferai de toi et de la maison de ton père une nation grande et beaucoup plus nombreuse que celle-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Moïse répondit au Seigneur: L’Égypte saura toujours que vous avez fait sortir ce peuple par votre puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Les nations de cette terre ont déjà même appris que vous êtes le Seigneur de ce peuple, que vous vous êtes montré à découvert à leurs yeux, ô Seigneur, que votre nuée s’est arrêtée sur eux, et que vous les précédez, le jour, en une colonne de nuée; la nuit, en une colonne de feu:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Et vous broieriez ce peuple comme un seul homme! Mais alors les peuples qui connaissent votre nom, diraient:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'C’est pour n’avoir entrer le peuple en la terre qu’il leur avait promise, que le Seigneur les a exterminés dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Seigneur, que votre puissance éclate donc de la manière que vous avez annoncée, quand vous avez dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Le Seigneur est patient, miséricordieux et véridique; il remet dérèglements, iniquités et péchés; il ne purifie pas le coupable, et il punit les fautes des pères sur les enfants jusqu’à la troisième ou à la quatrième génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Selon votre grande miséricorde, remettez-lui son péché; soyez-lui favorable comme vous l’avez été depuis l’Égypte jusqu’ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Et le Seigneur dit à Moïse: Je leur suis favorable comme tu le demandes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mais j’en jure par ma vie et par mon nom qui est vivant, par la gloire du Seigneur qui remplira toute la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Nul de ces hommes qui, ayant vu ma gloire et les prodiges que j’ai faits en Égypte et dans le désert, viennent ainsi de me tenter pour la dixième fois, et sont encore indociles à ma voix,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Ne verra la terre que j’ai promise à leurs pères; je la donne à leurs enfants qui sont ici avec moi, qui ne connaissent ni le bien ni le mal, jeunes encore et sans expérience; aucun de ceux qui m’ont irrité ne la verra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Quant à mon serviteur Caleb, qui a un autre esprit, et qui m’a été docile, je le conduirai en cette terre où il est entré, et sa race y aura une part d’héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Or, Amalec et le Chananéen demeurent dans le vallon, au delà de la colline; demain donc, reprenez le chemin de la mer Rouge, et reportez vos tentes dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Et le Seigneur parla à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Jusqu’à quand supporterai-je cette méchante synagogue? Leur murmure contre moi, le murmure des fils d’Israël contre vous, je l’ai entendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Dites-leur donc: J’en jure par ma vie, dit le Seigneur, je vous traiterai selon ce que vous dites à mes oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Vos cadavres tomberont dans le désert; personne de toute cette multitude, nul de ceux qui parmi vous ont vingt ans et au-dessus, qui ont été recensés et qui ont murmuré contre moi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'N’entrera en la terre sur laquelle j’avais étendu la main pour que vous y vinssiez dresser vos tentes, hormis Caleb, fils de Jéphoné, et Josué, fils de Nau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Ce sont ces enfants dont vous avez dit: Ils seront la proie des vainqueurs, que j’introduirai en la terre que vous avez dédaignée; elle sera leur héritage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Tandis que vos cadavres tomberont dans le désert!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Vos enfants demeureront quarante ans dans le désert, ils porteront la peine de votre prévarication, jusqu’à ce que vos cadavres soient consumés dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Autant de jours vous avez employés à explorer cette terre, autant d’années vous porterez la peine de votre prévarication; vous la porterez quarante ans, et vous connaîtrez ce que peut mon courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Je suis le Seigneur, et j’ai dit: C’est ainsi que je traiterai cette méchante synagogue qui s’est soulevée contre moi; ils se consumeront dans le désert, et ils y mourront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Et les hommes que Moïse avait envoyés pour reconnaître la terre promise, et qui à leur retour, à cause de cela, avaient murmuré devant la synagogue, en rapportant de méchants discours contre cette terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Ces hommes moururent, frappés devant le Seigneur, pour avoir mal parlé de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Josué, fils de Nau, et Caleb, fils de Jéphoné, seuls, survécurent parmi ces hommes qui avaient exploré cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Moïse fit connaître ces choses à tous les fils d’Israël, et le peuple s’affligea vivement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Et, s’étant levés de grand matin, ils montèrent au sommet de la colline, et ils dirent: Nous montons au lieu qu’a indiqué le Seigneur, parce que nous avons péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Moïse leur dit: Pourquoi transgressez-vous encore l’ordre du Seigneur? Vous ne réussirez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ne montez pas, car le Seigneur n’est point avec vous, et vous tomberez devant vos ennemis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Amalec et le Chananéen sont là devant vous, et vous périrez par le glaive, car vous marchez contre l’ordre du Seigneur, et le Seigneur n’est pas avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Malgré cela, ils montèrent sur le sommet de la colline, et ni l’arche de l’alliance ni Moïse ne bougèrent du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Or, Amalec et le Chananéen demeuraient au delà de la colline; ils descendirent au-devant d’Israël, le mirent en fuite, et le taillèrent en pièces jusqu’à Herman; et le peuple rentra sous ses tentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Le Seigneur dit alors à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Parle aux fils d’Israël, et dis-leur: Lorsque vous serez entrés en la terre que je vous donne pour que vous l’habitiez,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'Et que parmi vos bœufs ou vos menus troupeaux vous sacrifierez au Seigneur des holocaustes ou des hosties pacifiques, soit pour accomplir un vœu, soit volontairement, ou bien afin de répandre dans vos fêtes une odeur de suavité pour le Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Celui qui fera ce don au Seigneur, présentera en même temps en oblation un décime d’éphi de fleur de farine pétrie dans un quart de mesure d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Et vous donnerez un quart de mesure de vin pour la libation sur l’holocauste ou sur l’hostie; voilà ce qu’il faudra donner par agneau; c’est le sacrifice d’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Et si vous sacrifiez un bélier en holocauste ou comme hostie pacifique, l’oblation sera de deux décimes d’éphi de fleur de farine pétrie dans un tiers de mesure d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Et vous présenterez un tiers de mesure de vin pour la libation, afin qu’elle répande une odeur de suavité devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Si vous sacrifiez une tête prise parmi vos bœufs, soit en holocauste, soit pour l’accomplissement d’un vœu, soit comme hostie pacifique,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Vous présenterez en outre une oblation de trois décimes de fleur de farine pétrie dans une demi-mesure d’huile,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Et une demi-mesure de vin pour la libation: et le sacrifice répandra une odeur de suavité devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Vous ferez ainsi pour chaque veau, pour chaque bélier, pour chaque agneau, pour chaque tête prise parmi les brebis ou les chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Quel que soit le nombre des victimes que vous sacrifierez, voilà ce que vous ferez pour chacune;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Tout indigène fera ainsi ses offrandes, afin que vos sacrifices soient en odeur de suavité devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Et si un prosélyte est venu demeurer avec vous en votre terre, ou s’il est né parmi vous en vos familles, il offrira les sacrifices d’odeur de suavité au Seigneur, de la même manière que vous; ainsi fera pour le Seigneur la synagogue tout entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Il n’y aura qu’une loi pour vous et pour les prosélytes demeurant parmi vous; c’est une loi perpétuelle en toutes vos générations; le prosélyte sera comme vous devant le Seigneur. Il n’y aura qu’une loi, qu’une justice pour vous et pour le prosélyte demeurant parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Le Seigneur dit encore à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Parle aux fils d’Israël, et dis-leur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Pendant que vous entrerez en la terre où je vous conduis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Lorsque vous mangerez des pains de cette terre, vous mettrez à part une offrande, qui sera la portion du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Prémices de vos pàtes; vous mettrez à part, comme offrande, le pain provenant de ces prémices, de même que l’offrande des aires; vous emporterez le pain qui sera');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Prémices de vos pâtes, et vous le donnerez au Seigneur; ce sera son offrande durant toutes vos générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Mais, si vous n’exécutez point tous les ordres que le Seigneur a donnés à Moïse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Et qu’il vous a transmis par la voix de ce dernier; si vous y manquez, à partir du jour où vous les avez reçus et à l’avenir, en toutes vos générations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Si la faute a été commise involontairement à l’insu de la synagogue, le peuple entier sacrifiera un veau sans tache, pris parmi les bœufs, en holocauste, en odeur de suavité pour le Seigneur, avec son oblation et sa libation selon la règle, et en outre un bouc pris parmi les chèvres, pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Et le prêtre intercèdera pour toute la synagogue des fils d’Israël; et la faute leur sera remise, parce qu’elle aura été involontaire, et qu’ils auront apporté leur offrande et fait un sacrifice au Seigneur pour le péché et le délit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Et la faute sera remise à toute la synagogue des fils d’Israël; elle sera pareillement remise au prosélyte demeurant parmi vous, parce que pour tout le peuple elle aura été involontaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Si une âme seule a péché involontairement, elle offrira une chèvre d’un an pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Et le prêtre priera pour cette âme négligente qui aura péché involontairement devant le Seigneur, afin de lui rendre le Seigneur favorable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Il n’y aura qu’une loi pour l’indigène des fils d’Israël, et pour le prosélyte demeurant avec eux, lorsqu’ils auront péché involontairement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Tout indigène ou prosélyte qui de lui-même pèchera par orgueil et irritera Dieu, sera exterminé au milieu du peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Car il aura méprisé la parole du Seigneur, et rendu vains les commandements; il sera broyé, et son péché sera en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Comme les fils d’Israël étaient dans le désert, ils virent un homme qui ramassait du bois le jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Ceux qui le trouvèrent ramassant du bois le jour du sabbat, le conduisirent devant Moïse, Aaron et toute la synagogue d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Et on le mit en prison; car ils n’avaient point décidé ce qu’ils lui feraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Alors, le Seigneur parla à Moïse, disant: Que cet homme meure de mort, que toute la synagogue le lapide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Toute la synagogue le mena donc hors du camp, et le lapida, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Le Seigneur dit ensuite à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Parle aux fils d’Israël, et dis-leur Faites des franges aux bords de vos manteaux, en toutes vos générations, ajoutez à la frange un effilé couleur d’hyacinthe;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Cet effilé sera mêlé aux franges, vous l’aurez sous les yeux, et vous vous souviendrez des commandements du Seigneur, vous les observerez et vous ne vous laisserez pas pervertir par vos mauvaises pensées, ni par des yeux qui vous feraient tomber dans la fornication.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Vous vous souviendrez de mes commandements et vous les mettrez en pratique, et vous serez saints pour votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Je suis le Seigneur votre Dieu qui vous ai tirés de la terre d’Égypte pour être votre Dieu; je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Alors, Coré, fils d’Isaar, lequel était fils de Caath, fils de Lévi, se concerta avec Dathan et Abiron, fils d’Eliab, et Hon, fils de Phéleth, fils de Ruben.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Et ils se révoltèrent contre Moïse, et avec eux deux cent cinquante des fils d’Israël, tous princes de la synagogue, siégeant au conseil, et hommes de renom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Ils s’attroupèrent devant Moïse et Aaron, et ils dirent: Qu’il vous suffise que toute la synagogue soit sainte, et que le Seigneur soit avec nous. Pourquoi donc vous placez-vous à la tête de la synagogue du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Moïse, les ayant ouïs, se prosterna la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Il répondit à Coré et à toute sa troupe: Dieu ne nous perd pas de vue, il connaît ceux qui sont à lui, il connaît les saints, et il les fait venir jusqu’à lui; ceux qu’il a ehoisis i les fait approcher de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Faites ceci: Vous Coré et ses partisans, prenez des encensoirs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'Mettez-y du feu, demain vous y mettrez de l’encens devant le Seigneur; et celui que le Seigneur a choisi sera saint; que cela vous suffise, fils de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Et Moïse dit à Coré: Écoutez-moi, fils de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'N’est-ce pas assez pour vous que le Dieu d’Israël vous ait distingués parmi la synagogue d’Israël, et vous ait fait monter jusqu’à lui, afin que vous fassiez les services liturgiques du tabernacle, et que vous vous teniez devant le tabernacle où vous servez les prêtres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'N’est-ce pas assez qu’il t’ait élevé jusqu’à lui, toi et tes frères les fils de Lévi? faut-il que vous réclamiez de plus le sacerdoce?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Est-ce ainsi que toi et toute ta troupe, vous vous réunissez contre Dieu? Et qui est-il Aaron, pour que vous murmuriez contre lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Alors, Moïse fit appeler Dathan et Abiron, fils d’Eliab, et ils dirent: Nous n’irons pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'N’est-ce pas assez que tu nous aies soit-disant conduits en une terre où coulent le lait et le miel, pour nous faire périr dans le désert?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Oui, tu es chef; oui, tu nous as conduits en une terre où coulent le lait et le miel; oui, tu nous as donné pour héritage des vignes et des champs; il faut que tu aies aveuglé ces hommes qui te suivent; nous ne te suivrons pas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Moïse fut vivement indigné, et il dit au Seigneur N’acceptez point leurs sacrifices; je ne leur ai rien pris de ce qui leur est précieux, je n’ai affligé aucun d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Moïse dit ensuite à Coré: Sanctifie ta troupe, et demain matin tenez-vous prêts devant le Seigneur, toi et les tiens d’une part, et de l’autre part Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Prenez chacun un encensoir, mettez-y de l’encens; présentez au Seigneur deux cent cinquante encensoirs; qu’Aaron et les tiens aient chacun le leur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Chacun prit donc son encensoir, y mit du feu et y jeta de l’encens; cependant, Moïse et Aaron se tenaient devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Coré et toute sa troupe étaient soulevés contre eux devant la porte du tabernacle du témoignage, lorsque la gloire du Seigneur apparut à toute la synagogue d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Et le Seigneur parla à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Éloignez-vous de cette troupe; je vais à l’instant la détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Et ils tombèrent la face contre terre en s’écriant: Dieu, Dieu des esprits et de toute chair, parce qu’un seul a péché, la colère du Seigneur frappera-t-elle toute la synagogue?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Parle à la synagogue, dis-leur: Éloignez-vous de la troupe de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Moïse se leva, et il alla droit aux tentes de Dathan et d’Abiron, et tous les anciens d’Israël le suivirent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Et il dit à la synagogue: Éloignez-vous des tentes de ces méchants hommes; ne touchez à rien de ce qui est à eux, si vous ne voulez périr à cause de leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Et ils formèrent un cercle à distance autour de la tente de Coré; alors, Dathan et Abiron sortirent, et ils se tenaient sur les portes de leurs tentes avec leurs femmes, leurs enfants et leurs bagages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Moïse dit au peuple: Vous allez connaître que le Seigneur m’a envoyé pour faire toutes ces œuvres, et que je ne les fais point de moi-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Si ces hommes meurent de la mort commune à tous, si le Seigneur les considère comme les autres hommes, le Seigneur ne m’a pas envoyé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Mais le Seigneur va faire éclater un prodige, la terre ouvrira sa bouche; elle dévorera ces hommes, leurs familles, leurs tentes, tout ce qui leur appartient; ils descendront vivants sous la terre, et vous reconnaîtrez qu’ils ont irrité le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'À peine avait-il achevé ces mots, que la terre se fendit sous ces hommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Elle s’ouvrit et elle les dévora, eux, leurs maisons, tous ceux qui étaient avec Coré, et même leur bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Ils descendirent vivants sous la terre avec tout ce qui leur appartenait, et la terre les cacha, et ils furent détruits au milieu de la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Aussitôt, tout Israël qui les entourait, s’enfuit à leurs cris, disant: Prenons garde que la terre ne nous dévore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Et un feu sortit de la gloire du Seigneur, et il dévora les deux cent cinquante hommes qui offraient de l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Le Seigneur dit alors à Moïse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Et à Eleazar, fils du grand prêtre Aaron: Otez du milieu de ces hommes brûlés les encensoirs d’airain, et jetez çà et là le feu étranger, car les encensoirs de ces pécheurs sont devenus sacrés à cause de leur mort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Faites-en au marteau des plaques dont vous entourerez l’autel; car ils ont été présentés devant le Seigneur, ils sont sacrés, et ils seront un signe pour les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Eleazar, fils du grand prêtre Aaron, prit donc les encensoirs d’airain qu’avaient présentés les hommes brûlés, et ils en firent comme une tenture autour de l’autel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'C’était un mémorial pour les fils d’Israël, afin que nul étranger à la famille d’Aaron ne s’en approchât pour offrir de l’encens au Seigneur, et qu’il n’arrivât plus ce qui était arrivé à Coré et à sa troupe rebelle, selon ce que le Seigneur avait dit par la voix de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Mais le lendemain, les fils d’Israël murmurèrent contre Moïse et Aaron, disant: Vous avez fait périr le peuple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Pendant que la synagogue, s’ameutant contre Moïse et Aaron, se précipitait vers le tabernacle du témoignage, voilà que la nuée l’enveloppa, et que la gloire du Seigneur apparut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Aussitôt, Moïse et Aaron entrèrent devant la façade du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Et le Seigneur parla à Moïse et Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Éloignez-vous de cette synagogue, je vais à l’instant la détruire; et ils tombèrent la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Et Moïse dit à Aaron: Prends l’encensoir, mets-y du feu, jettes-y de l’encens, et hâte-toi de le promener parmi le camp, pour apaiser Dieu en sa fureur; car la colère s’est élancée de la gloire du Seigneur, et elle a commencé à frapper le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Aussitôt, Aaron, comme le lui prescrivait Moïse, prit l’encensoir, et courut parmi la synagogue; la destruction du peuple était commencée; le prêtre jeta de l’encens sur le feu et pria pour le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Il se tint entre les morts et les vivants, et la destruction s’arrêta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Il y eut en cette journée quatorze mille sept cents morts, outre ceux qui avaient péri à cause de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Alors, Aaron retourna vers Moïse devant la porte du tabernacle du témoignage. La destruction avait cessé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Le Seigneur dit ensuite à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Parle aux fils d’Israël, prends de chacun des chefs de tribu une baguette, et, sur chacune des douze baguettes, écris le nom de chacun d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Écris aussi le nom d’Aaron sur la baguette de Lévi, c’est une baguette à part; et les chefs feront l’offrande de ces baguettes par tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Place-les ensuite dans le tabernacle devant le témoignage; c’est par elles que je me manifesterai à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Et la baguette de celui que j’aurai choisi reverdira, et je rejetterai loin de moi le murmure que les fils d’Israël ont fait éclater contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Moïse parla donc aux fils d’Israël; tous les chefs donnèrent chacun une baguette, et il y eut douze baguettes pour les douze tribus, et en outre celle d’Aaron parmi les autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Moïse plaça les baguettes devant le Seigneur dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Et le lendemain il entra avec Aaron dans le tabernacle du témoignage; la baguette d’Aaron, de la maison de Lévi, avait germé; elle portait un bourgeon, une fleur s’y épanouissait, et elle promettait des fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Après cela, Moïse ôta toutes les baguettes de devant le Seigneur, et il les porta aux fils d’Israël; ils les virent, et chaque chef reprit la sienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Et le Seigneur dit à Moïse: Dépose la baguette d’Aaron devant le témoignage, afin qu’elle soit conservée comme signe pour les fils des indociles; que le murmure de ceux-ci s’apaise, et ils ne mourront point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Moïse et Aaron firent ce qu’avait prescrit le Seigneur; ainsi firent-ils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Et les fils d’Israël parlèrent à Moïse, disant: Voilà que nous périssons, que nous sommes consumés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Tous ceux qui touchent au tabernacle du témoignage meurent; mourrons-nous tous jusqu’au dernier?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Et le Seigneur dit à Aaron: Toi et tes fils, et ta famille paternelle, vous assumerez les péchés des saints; toi et tes fils vous assumerez les péchés du sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Entoure-toi de tes frères, de la tribu de Lévi, ta famille paternelle; qu’ils se joignent à toi et qu’ils te servent, quand vous vous tiendrez devant le tabernacle du témoignage, toi et tes fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Et ils auront pour fonction la garde du tabernacle; mais ils ne s’approcheront ni des choses saintes ni de l’autel, et, non plus que vous, ils ne mourront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Et ils se réuniront à toi, et ils garderont le tabernacle du témoignage, et ils feront tous les services liturgiques du tabernacle; nul homme d’une autre race ne s’approchera de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Vous aurez pour fonction la garde des choses saintes et de l’autel; et il n’y aura point de colère contre les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'J’ai choisi vos frères les lévites, parmi les fils d’Israël, comme une offrande faite au Seigneur, afin qu’ils fassent les services liturgiques du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Toi et tes fils, vous exercerez fidèlement votre sacerdoce dans toutes les cérémonies de l’autel et de l’intérieur du voile, et vous accomplirez les cérémonies liturgiques qui sont l’offrande de votre sacerdoce; et si un homme étranger à ta famille s’en mêle, il mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Et le Seigneur parla à Moïse et à Aaron, disant: Je suis le Seigneur: je vous ai donné la garde de toutes les prémices qui me sont consacrées par les fils d’Israël; je les ai données à toi, et, après toi, à tes fils pour honoraires, par une loi perpétuelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Et telle sera votre part des choses saintes, des choses consacrées, des oblations, des dons, des sacrifices, des victimes pour le délit ou pour le péché: tout ce qui m’est consacré des choses saintes, sera pour toi et tes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Vous les mangerez en lieu très-saint, toi et tes fils, les mâles seulement; ce sera pour toi chose sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Vous aurez encore les prémices de tous les dons, de toutes les offrandes des fils d’Israël; je les donne à toi, à tes fils et à tes filles, par une loi perpétuelle; toute âme pure en ta famille les mangera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Toutes prémices d’huile, toutes prémices de vin et de pain, toutes prémices qu’ils auront offertes au Seigneur, je vous les donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Les premiers fruits de leurs champs, qu’ils apporteront au Seigneur, seront pour toi; toute âme pure en ta maison en mangera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Tout ce qui sera donné, en conséquence d’un vœu, chez les fils d’Israël, sera pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Tout premier-né de toute chair, qu’ils doivent offrir au Seigneur, t’appartiendra, depuis l’homme jusqu’aux bestiaux; mais les premiers-nés des hommes seront rachetés au prix d’une rançon, et tu abandonneras au prix d’une rançon les premiers-nés des animaux impurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'La rançon d’une tête d’un mois est évaluée cinq sicles au poids du sanctuaire, vingt oboles par sicle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Tu ne renonceras pas, moyennant rançon, au premier-né du troupeau de bœufs, ni au premier-né des brebis, ni au premier-né des chèvres; c’est chose sainte: tu en répandras le sang au pied de l’autel, et tu en offriras la graisse, comme sacrifice d’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Et les chairs seront à toi, comme la poitrine mise à part et l’épaule droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Toute portion réservée des choses saintes que les fils d’Israël mettront à part, je la donne à toi, à tes fils et à tes filles: c’est une loi perpétuelle, c’est une alliance de sel à perpétuité devant le Seigneur, pour toi et ta postérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Et le Seigneur dit à Aaron: Tu n’auras point comme eux d’héritage, et de part en leur terre; je suis ta part et ton héritage au milieu des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Je donne aux fils de Lévi toutes les dîmes pour héritage en Israël, et pour prix de leurs services liturgiques dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Les fils d’Israël ne s’approcheront plus du tabernacle du témoignage; ce serait un péché qui leur apporterait la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Les lévites feront seuls le service liturgique du tabernacle du témoignage, et ils assumeront les péchés du peuple; c’est une loi perpétuelle en toutes vos générations; parmi les fils d’Israël, les lévites n’auront point d’héritage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Parce que je leur ai donné pour héritage les dîmes que les fils d’Israël réserveront au Seigneur; c’est pourquoi je leur ai dit: Parmi les fils d’Israël vous n’aurez point d’héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Et le Seigneur dit à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Parle aux lévites et dis-leur: Lorsque vous prendrez des fils d’Israël la dîme que je vous donne pour héritage, vous en réserverez la part du Seigneur: la dîme de la dîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'On vous comptera d’abord votre part, tant du blé des aires que du vin des pressoirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Alors, de toutes les dîmes que vous aurez reçues des fils d’Israël, vous réserverez les parts du Seigneur, et, de chaque dîme, vous donnerez la part du Seigneur à Aaron le prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'De tous vos dons, réservez la part du Seigneur; de toutes vos prémices, réservez ce qui est consacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Dis-leur encore: Lorsque vous aurez réservé la part du Seigneur, et ce qui est consacré de vos prémices, on délivrera aux lévites ce qui leur revient, tant du blé des aires que du vin des pressoirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Vous le consommerez en tout lieu, vous et vos familles; c’est l’honoraire de vos services liturgiques dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Et vous n’assumerez point de péché parce que vous aurez réservé les prémices; et vous ne profanerez pas les choses saintes d’Israël, afin que vous ne mouriez point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Le Seigneur parla encore à Moïse et à Aaron, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Voici sur la loi de purification les détails que le Seigeur a réglés, disant: Parle aux fils d’Israël et qu’ils t’amènent une génisse rousse sans tache, sans difformité, qui n’ait point encore porté le joug.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Tu la donneras à Eléazar le prêtre; puis, on la conduira hors du camp, en lieu pur, et on l’égorgera devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Eléazar prendra de son sang, et il en fera sept aspersions sur la façade du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Puis, on la brûlera devant lui; le cuir et la chair, le sang et la fiente seront consumés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Après quoi, le prêtre prendra du bois de cèdre, de l’hysope, de l’écarlate, et l’on jettera ces choses au milieu du bûcher qui consumera la génisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Le prêtre lavera ensuite ses vêtements; il se lavera le corps avec de l’eau; il rentrera dans le camp, et il sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'L’homme qui aura brûlé la génisse lavera aussi ses vêtements, et il se lavera le corps avec de l’eau, et il sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Un homme pur recueillera les cendres de la génisse, et il les déposera hors du camp en lieu pur; et la synagogue des fils d’Israël veillera à ce qu’elle soit; l’eau de l’aspersion est chose purifiante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'L’homme donc qui aura recueilli les cendres de la génisse lavera ses vêtements, et il sera impur jusqu’au soir c’est une loi perpétuelle pour vous et pour les prosélytes établis parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Celui qui aura touché un homme mort sera impur sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Il sera purifié avec l’eau de l’aspersion, le troisième et le septième jour, et il sera pur; s’il n’est aspergé le troisième et le septième jour, il ne le sera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Quiconque aura touché le cadavre d’un homme mort, et n’aura point été purifié, a souillé le tabernacle du Seigneur; il sera exterminé en Israël, parce qu’il n’aura pas été aspergé de l’eau de l’aspersion. Il est impur, et son impureté est encore en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Autre loi: Si un homme est mort dans une maison, quiconque entrera dans la maison et tout ce que la maison renferme seront impurs sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Tout vase ouvert qui n’aura pas de couvercle attaché sera impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Quiconque aura touché, sur le lieu d’un meurtre, soit un cadavre, soit des ossements humains, soit un sépulcre, sera impur sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'On prendra pour l’impur des cendres de la génisse brûlée pour la purification, et on répandra sur elles de l’eau vive en un vase.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Ensuite un homme pur prendra de l’hysope, il la trempera dans l’eau, et il en aspergera soit la maison, les meubles, les âmes qui s’y trouvent, soit l’homme qui aura touché les ossements humains, ou le champ du meurtre, ou le mort, ou la sépulture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Et l’homme pur aspergera l’impur, le troisième et le septième jour, et celui-ci sera purifié le septième jour; alors, il lavera ses vêtements, il se lavera avec de l’eau, et il sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'L’homme qui aura été souillé, et n’aura pas été purifié, sera exterminé du milieu du peuple, parce qu’il aura souillé les choses saintes du Seigneur, et qu’il n’aura pas été aspergé de l’eau de l’aspersion; il est impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Ce sera pour vous une loi perpétuelle, et celui qui aspergera avec l’eau de l’aspersion lavera ses vêtements, et celui qui aura touché l’eau de l’aspersion sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Tout ce qu’aura touché un homme impur sera également impur, et celui qui touchera une de ces choses sera impur jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Toute la synagogue des fils d’Israël revint dans le désert de Sin durant le premier mois, et elle demeura en Cadès; or, Marie mourut en ce lieu, et elle Y fut ensevelie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Et il n’y avait point là d’eau pour la synagogue; elle se rassembla donc tumultueusement autour de Moïse et d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Et le peuple injuria Moïse, disant: Que ne sommesnous morts lorsque nos frères ont été détruits devant le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Pourquoi avez-vous conduit le peuple en ce désert, où nous périssons, nous et nos bestiaux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Dans quel but nous avez-vous amenés de l’Egypte en ce lieu maudit, où il n’y a ni semailles, ni figues, ni vignes, ni grenades, ni même d’eau à boire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Aussitôt, Moïse et Aaron, s’éloignant de la synagogue, allèrent devant la porte du tabernacle du témoignage, et ils se prosternèrent la face contre terre; alors, la gloire du Seigneur leur apparut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Prends ta baguette; toi et ton frère, convoquez la synagogue, et parlez au rocher qui est devant vous, il vous donnera ses eaux; vous ferez jaillir pour vous de l’eau du rocher, et vous abreuverez la synagogue et les bestiaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Moïse prit la baguette déposée devant le Seigneur, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Et Moïse et Aaron convoquèrent la synagogue devant le rocher, et Moïse lui dit: Écoutez-moi, incrédules; tirerons-nous pour vous de l’eau de ce rocher?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Puis, Moïse étendit la main, et de sa baguette il frappa deux fois le rocher. Aussitôt, l’eau jaillit en abondance; la synagogue but et elle abreuva ses bestiaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Le Seigneur dit alors à Moïse et à Aaron: Vous n’avez pas eu assez de foi pour me sanctifier devant les fils d’Israël, c’est pourquoi vous n’introduirez point ce peuple dans la terre que je vous ai donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Cette eau est appelée l’eau de contradiction, parce qu’en ce lieu les fils d’Israël injurièrent Moïse devant le Seigneur, et que le Seigneur fut sanctifié en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'De Cadès, Moïse envoya des messagers au roi d’Edom, disant: Ton frère Israël dit ces choses: Tu sais toutes les peines qui nous ont assaillis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Nos pères sont descendus en Égypte; nous avons habité l’Égypte bien des années, et les Égyptiens nous ont opprimés, comme nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Nous avons invoqué le Seigneur, et il a entendu nos cris; il a envoyé son ange, il nous a fait sortir de la terre d’Égypte, et nous voilà arrivés en la ville de Cadès du côté de tes frontières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Nous allons donc passer par ton territoire; nous ne traverserons ni les champs, ni les vignes; nous ne boirons point l’eau de tes citernes; nous suivrons le grand chemin, sans nous détourner à droite ni à gauche, jusqu’à ce que nous ayons dépassé tes limites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Mais Edom lui dit: Tu ne passeras point par mon territoire; si tu insistes, j’irai à ta rencontre pour te combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Les fils d’Israël repartirent: Nous passerons le long de la montagne, et si de l’eau qui t’appartienne est bue par nous ou nos troupeaux, nous te la paierons; mais il ne peut être question de cela, nous passerons le long de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Mais Edom dit: Tu ne passeras point par mon territoire; et il sortit à la rencontre d’Israël avec une multitude redoutable et des bras puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Ainsi Edom ne voulut pas permettre à Israël de franchir sa frontière, et Israël se détourna de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Les fils d’Israël partirent de Cadès, et ils arrivèrent dans la montagne de Hor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Et le Seigneur parla à Moïse et à Aaron en la montagne de Hor, sur les frontières de la terre d’Edom, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Qu’Aaron aille rejoindre son peuple: car vous ne devez point entrer en la terre que j’ai donnée aux fils d’Israël, parce que vous m’avez irrité au sujet de l’eau de contradiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Prends Aaron et son fils Eléazar, et fais-les monter sur la montagne de Hor, devant toute la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Ote à Aaron sa robe pour en revêtir Eléazar son fils; qu’Aaron se réunisse à son peuple et meure en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Moïse fit ce qu’avait prescrit le Seigneur; il fit monter Aaron sur la montagne de Hor devant toute la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Il ôta à Aaron les vêtements sacerdotaux, il en revêtit son fils Eléazar, et Aaron mourut sur le sommet de la montagne, puis Moïse descendit de la montagne avec Eléazar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Toute la synagogue vit qu’Aaron était mort; et toute la maison d’Israël pleura Aaron trente jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Cependant, le Chananéen roi d’Arad, voisin du désert, apprit qu’Israël s’avançait par le chemin d’Atharin. Aussitôt, il prit les armes contre Israël, et il lui enleva quelques prisonniers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Israël fit alors un vœu au Seigneur, disant: Si vous me livrez ce peuple qui est sous ma main, je l’anathématiserai lui et ses villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Le Seigneur ouït la voix d’Israël, et il lui livra le Chananéen; Israël, de son côté, l’anathématisa lui et ses villes, et il donna à ce lieu le nom d’Anathème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Ils levèrent ensuite leur camp de la montagne de Hor pour quitter le chemin de la mer Rouge et tourner autour d’Edom; mais dans ce voyage le peuple défaillit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Il injuria Dieu et Moïse, disant: Qu’allons-nous devenir? Tu nous a tirés de l’Égypte pour nous faire mourir dans le désert où il n’y a ni pain ni eau; notre âme se révolte contre cette maigre manne dont nous sommes nourris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Alors, le Seigneur envoya contre le peuple des serpents dont le venin était mortel, et ils mordirent le peuple, et une multitude des fils d’Israël périt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Et le peuple alla trouver Moïse, disant: Nous avons péché; nous avons injurié le Seigneur et toi; prie donc le Seigneur qu’il éloigne de nous les serpents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Moïse pria le Seigneur pour le peuple, et le Seigneur dit à Moïse: Fais un serpent, et pose-le au haut d’une enseigne; quand un serpent mordra un homme, quiconque sera mordu et regardera ce signe, vivra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Moïse fit donc un serpent d’airain qu’il plaça au haut d’une enseigne, et quand un serpent mordait un homme, celui-ci regardait le serpent d’airain, et il vivait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Les fils d’Israël se mirent en marche, et ils s’arrêtèrent en Oboth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Étant partis d’Oboth, ils campèrent en Achalgé, hors de la région du désert qui regarde Moab du côté du levant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Partis de nouveau, ils campèrent dans le val de Zared.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'De ce lieu, ils campèrent sur l’Arnon, dans la région du désert qui fait saillie sur les limites des Amorrhéens; cet Arnon est frontière de Moab, entre Moab et l’Amorrhéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'C’est pourquoi il est écrit en un livre: La guerre du Seigneur a embrasé Zoob et les torrents d’Arnon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Et il a placé auprès des torrents la demeure de Ar, qui est contiguë aux frontières de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Or, il y a en ce lieu un puits: c’est le puits au sujet duquel le Seigneur dit à Moïse: Rassemble le peuple, et je leur donnerai de l’eau, et ils boiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Alors, Israël chanta ce cantique autour du puits: Célébrez le puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Les chefs l’ont creusé; les rois des nations, durant leur règne, tandis qu’ils étaient les maîtres, l’ont revêtu de pierres de taille. Après cela, le peuple d’Israël alla du puits à Manthanaïn;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Ensuite, de Manthanaïn à Nahaliel, de Nahaliel à Bamoth;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'De Bamoth à Janin, en la plaine de Moab, que l’on voit de la cime du roc escarpé regardant le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Alors, Moïse envoya les anciens à Séhon, roi des Amorrhéens, avec des paroles pacifiques, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Nous passerons par ton territoire et nous suivrons la route; nous ne nous écarterons ni dans les champs, ni dans les vignes; nous ne boirons point d’eau de ton puits; nous suivrons le grand chemin jusqu’à ce que nous ayons dépassé tes limites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mais Séhon ne permit point à Israël de franchir ses frontières; il rassembla tout son peuple, et il sortit pour se ranger en bataille devant Israël, dans le désert; il vint à Jasa, et il se rangea en bataille devant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Israël le vainquit avec grand carnage, et se rendit maître de son territoire depuis Arnon jusqu’à, sur les frontières des fils d’Ammon, car Jazer est ville frontière des Ammonites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Israël prit toutes ses villes, et Israël habita toutes les villes des Amorrhéens, Esebon et ses dépendances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Car Esebon était la ville de Séhon, roi des Amorrhéens; il avait d’abord fait la guerre au roi de Moab, et il avait pris tout son territoire depuis Arœr jusqu’à l’Arnon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'C’est pourquoi on dit en proverbe: Venez en Esebon, où a été bâtie et peuplée la ville de Séhon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Car le feu est sorti d’Esebon, c’était la flamme de la guerre de Séhon, et elle a dévoré jusqu’à Moab, elle a dévoré les colonnes d’Arnon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Malheur à toi, Moab; tu as péri, peuple de Chamos; leurs fils se sont vendus pour vivre, et leurs filles sont captives du roi des Amorrhéens Séhon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Leur race est à jamais détruite d’Esebon à Dibon; et les femmes ont encore allumé le feu dans Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Or, Israël occupa toutes les villes des Amorrhéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Moïse envoya reconnaître Jazer; ils la prirent avec ses bourgs, et ils chassèrent les Amorrhéens qui l’habitaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'À leur retour, ils prirent la route qui conduit à Basan, et Og, roi de Basan, sortit à leur rencontre avec tout son peuple, pour combattre en Edraï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Mais le Seigneur dit à Moïse: Ne le crains pas, je l’ai livré à tes mains, lui, tout son peuple et tout son territoire; tu le traiteras comme tu as traité Séhon, roi des Amorrhéens, qui demeurait en Esebon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Alors, Moïse vainquit Og et ses fils, et tout son peuple; nul n’en resta vivant, et il s’empara de son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Les fils d’Israël, étant partis, campèrent à l’ouest de Moab, sur les rives du Jourdain, en face de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Or, Balac, fils de Séphor, avait vu comme Israël venait de traiter l’Amorrhéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Moab eut donc grande crainte du peuple qui était très-nombreux; Moab fut saisi d’effroi à l’aspect des fils d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Et dit aux anciens de Madian: Ce peuple va maintenant nous dévorer, comme un veau dévore l’herbe des champs; il va dévorer tout ce qui l’entoure. En ce temps-là Balac, fils de Séphor, était roi de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Et il envoya des anciens à Phathura, qui est sur la rivière du territoire des fils de son peuple, pour appeler Balaam, fils de Béor, disant: Voilà qu’un peuple est venu d’Égypte, il couvre la face de la terre, il est campé tout près de moi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Viens donc, et maudis ce peuple, car il est plus puissant que nous; si nous pouvions les frapper séparément, je les chasserais de cette terre. Or, je le sais, ceux que tu bénis sont bénis, ceux que tu maudis sont maudits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Et les anciens de Moab, portant des présents, partirent avec les anciens des Madianites; arrivés chez Balaam, ils lui répétèrent les paroles de Balac,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Et il leur dit: Reposez-vous ici cette nuit, et je vous rapporterai ce que m’aura dit le Seigneur; les princes de Moab demeurèrent donc chez Balaam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Et Dieu dit à Balaam: Qui sont ces hommes que tu as chez toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Balaam répondit à Dieu: Balac, fils de Séphor, roi de Moab, me les a envoyés, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Un peuple est venu d’Égypte, il couvre la face de la terre, et il est campé tout près de moi; viens donc et maudis-le; peut-être pourrai-je ainsi le vaincre et le chasser de la contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Dieu dit à Balaam; tu ne partiras pas avec eux; tu ne maudiras pas ce peuple, car il est béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'S’étant donc levé de grand matin, Balaam dit aux princes de Balac: Retournez vers votre maître, Dieu ne me permet pas de partir avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Et les princes de Moab, s’étant levés, arrivèrent chez Balac, disant: Balaam ne veut pas venir avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Balac lui envoya des chefs plus nombreux et plus en honneur que les premiers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Ils allèrent chez Balaam, et ils lui dirent: Voici ce que dit Balac: Je t’en supplie, ne tarde pas à venir chez moi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Je te comblerai d’honneurs; tout ce que tu me demanderas, je te l’accorderai; mais viens et maudis ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Balaam répondit aux princes de Balac: Balac dût-il me donner plein sa maison d’argent et d’or, il m’est impossible de ne pas tenir compte de la parole du Seigneur Dieu, ni de songer à faire plus ou moins qu’il ne m’a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Vous aussi restez donc cette nuit chez moi, et je saurai ce que le Seigneur me dira de nouveau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'La nuit, Dieu vint à Balaam, et il lui dit: Puisque ces hommes sont venus te chercher, lève-toi et suis-les, mais tu feras selon la parole que je te dirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Balaam, s’étant levé de grand matin, bâta son ânesse et partit avec les princes de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Et Dieu se courrouça en son cœur de ce qu’il était parti, et l’ange de Dieu se leva pour l’arrêter; lui cependant, s’en allait avec son ânesse, et ses deux serviteurs étaient avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'L’ânesse, ayant vu l’ange de Dieu qui lui barrait la route l’épée nue à la main, se détourna et prit à travers champs; Balaam la frappa de sa baguette, pour la ramener sur la voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Et l’ange de Dieu se tint dans les sentiers des vignes, ayant un mur à droite et un mur à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'L’ânesse, ayant vu l’ange de Dieu, se froissa contre le mur et froissa le pied de Balaam; celui-ci continua de la frapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Mais l’ange de Dieu continua de les troubler; il s’en alla se placer dans un défilé où il n’y avait à se détourner ni à droite, ni à gauche..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'L’ânesse, ayant vu l’ange de Dieu, s’abattit sous Balaam. Celui-ci se mit en colère, et il frappa l’ânesse avec sa baguette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Alors, Dieu ouvrit la bouche de l’ânesse, et elle dit à Balaam: Que t’ai-je fait pour que tu me frappes ainsi jusqu’à trois fois?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Balaam répondit à l’ânesse: Tu t’es jouée de moi, et si j’avais une épée à la main, je t’en aurais déjà percée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Et l’ânesse dit à Balaam: Ne suis-je pas ton ânesse, sur laquelle tu es monté depuis ta jeunesse jusqu’à ce jour? T’ai-je jamais méprisé, et maltraité ainsi? Et il dit: Non.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Or, Dieu ouvrit les yeux de Balaam, et Balaam vit l’ange du Seigneur lui barrant la route, l’épée nue à la main, et, s’étant courbé, il se prosterna la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'L’ange de Dieu lui dit: Pourquoi as-tu frappé ton ânesse jusqu’à trois fois? Me voici, je suis venu pour t’arrêter, parce que ton voyage ne m’est pas agréable; l’ânesse m’a vu, et elle s’est détournée trois fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Et si elle ne s’était détournée, je t’eusse fait périr; quant à elle, je l’aurais épargnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Balaam dit à l’ange du Seigneur: J’ai péché, mais je ne savais pas que vous me barriez la route, et s’il ne vous plaît point que je poursuive, je m’en retournerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Mais l’ange de Dieu dit à Balaam: Va avec ces hommes; seulement sois attentif à répéter la parole que je te dirai. Balaam alla donc avec les princes de Balac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Celui-ci ayant appris que Balaam arrivait, sortit à sa rencontre jusqu’à la ville de Moab, qui est sur l’Arnon, à l’extrémité de la contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Et Balac dit à Balaam: Ne t’ai-je point envoyé querir? Pourquoi n’es-tu pas venu vers moi? Réellement, ne suis-je point assez puissant pour t’honorer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Balaam dit à Balac: Me voici, je suis venu à toi; maintenant, sera-t-il en mon pouvoir de te dire quoi que ce soit? La parole que Dieu mettra dans ma bouche, je te la dirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Balaam partit ensuite avec Balac, et ils arrivèrent aux villes où étaient ses domaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Balac sacrifia des brebis et des bœufs; puis, il en envoya à Balaam et aux princes qui l’accompagnaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Le lendemain, Balac ayant pris Balaam, le fit monter vers la colonne de Baal, et de là il lui montra une part du peuple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Balaam dit à Balac: Elève-moi ici sept autels, et prépare ici sept bœufs et sept béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balac fit comme avait dit Balaam, et il sacrifia un bœuf et un bélier par autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Balaam dit encore à Balac: Reste auprès de tes victimes, victimes, et j’irai voir si Dieu se manifeste à moi; ce qu’il m’apprendra, je te le répèterai. Et Balac resta près des victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Balaam alla donc interroger Dieu; il marcha droit devant lui, et Dieu lui apparut; Balaam dit à Dieu: J’ai préparé sept autels, et j’ai placé sur chaque autel un bœuf et un bélier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Alors, Dieu mit sa parole en la bouche de Balaam, et il lui dit: Quand tu seras de retour auprès de Balac, Voici ce que tu lui diras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Balaam retourna ensuite vers Balac; or, celui-ci se tenait auprès de ses holocaustes, avec tous les princes de Moab; et l’Esprit de Dieu vint en Balaam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Et Balaam, commençant son discours prophétique, dit: Balac, roi de Moab, in\'a fait venir de la Mésopotamie et des montagnes de l’orient, et il m’a dit: Viens, fais des imprécations contre Jacob; maudis Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Pourquoi ferais-je des imprécations contre celui à qui le Seigneur ne veut point de mal? Pourquoi maudirais-je celui que Dieu ne maudit point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Je le vois de ces montagnes, je l’aperçois du haut de ces collines: voici un peuple qui demeurera isolé, il ne sera point compté parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Qui connaîtra la race de Jacob, et qui énumèrera les tribus d’Israël? Puisse mon âme mourir avec les âmes justes; puisse ma race être comme celle-là!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Balac dit alors à Balaam: Qu’as-tu fait? Je t’ai appelé pour que tu maudisses mes ennemis, et voilà que tu les bénis!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Balaam répondit à Balac: Ne dois-je pas fidèlement répéter les paroles que Dieu a mises dans ma bouche?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Balac repartit: Viens avec moi en un autre lieu d’où tu ne pourras voir tout ce peuple; tu en verras une part sans le voir tout entier; maudis-le de cet endroit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Et il l’emmena au plus haut du champ, sur le plateau d’un rocher, et il y éleva sept autels, et il plaça sur chaque autel un bœuf et un bélier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Balaam dit à Balac: Reste auprès de tes victimes, je vais interroger Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Et Dieu vint à la rencontre de Balaam; il lui mit sa parole dans la bouche, et il lui dit: Retourne auprès de Balac; voici ce que tu lui diras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Et Balaam retourna vers Balac, qui se tenait près de ses holocaustes, avec tous les princes de Moab. Balac lui dit: Que t’a dit le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Et Balaam, commençant son discours prophétique, dit: Lève-toi, Balac, et écoute; écoute comme témoin, fils de Séphor:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'On ne tient pas Dieu en suspens comme l’homme; on ne le menace pas comme les fils de l’homme; lui qui a dit, ne fera-t-il pas? Il parlera sa parole ne subsisterat-elle pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Quant à moi, il m’a choisi pour bénir, et je bénirai; rien ne m’en détournera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Il n’y aura point de souffrance en Jacob, on ne verra point de douleur en Israël. Le Seigneur son Dieu est avec lui, la gloire de ses princes est en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'C’est Dieu qui l’a tiré d’Égypte; sa gloire est comme celle de la licorne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Il n’y a point d’augures en Jacob, il n’y a point d’art divinatoire en Israël; au temps voulu Jacob entendra la parole, Israël entendra ce que Dieu doit accomplir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Son peuple se lèvera comme un lionceau; il s’exaltera comme un lion; il ne dormira point qu’il n’ait dévoré sa proie et bu le sang du carnage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Et Balac dit à Balaam: Si tu n’as pu les maudire, du moins ne les bénis pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Balaam répondit à Balac: Ne t’ai-je point dit: La parole que me dira le Seigneur, je la répèterai?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Et Balac dit à Balaam: Viens, je vais t’emmener ailleurs, pour voir si là du moins il plaira à Dieu que tu les maudisses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Balac emmena Balaam sur la cime de Phégor, qui s’étend vers le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Et Balaam dit à Balac: Élève-moi ici sept autels, et prépare-moi sept bœufs et sept béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balac fit comme avait dit Balaam, et il sacrifia un bœuf et un bélier par autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Balaam, ayant vu qu’il était agréable au Seigneur de bénir Israël, n’alla point, comme il avait coutume, au-devant des auspices; il se tourna du côté du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Ayant levé les yeux, Balaam vit Israël campé par tribus, et l’Esprit de Dieu vint en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Et, commençant son discours prophétique, il dit: Il parle, Balaam, le fils de Béor; il parle, cet homme, le voyant de la vérité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Il parle, celui qui entend les paroles du Tout-Puissant, celui qui a vu dans son sommeil la vision de Dieu, et dont les yeux ont été dessillés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Que tes demeures sont belles, ô Jacob! que tes tentes sont belles, ô Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Elles sont comme des forêts pleines d’ombres, comme des jardins au bord d’un fleuve, comme des tabernacles qu’a dressés le Seigneur, comme des cèdres auprès des eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Un homme sortira de cette race, et il sera maître de beaucoup de nations, et la royauté de Gog sera glorifiée, et son royaume grandira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'C’est Dieu qui l’a tirée d’Égypte; sa gloire est comme celle de la licorne. Elle dévorera les nations ennemies, elle fera sortir la mœlle de leurs os, elle les percera de ses flèches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Israël s’est couché, il s’est endormi comme un lion et comme un lionceau; qui le réveillera? Ceux qui te béniront, seront bénis; ceux qui te maudiront, seront maudits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Alors, Balac s’irrita contre Balaam, il claqua de ses deux mains, et dit à Balaam: Je t’ai appelé pour maudire mon ennemi, et voilà que tu le bénis pour la troisième fois!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Fuis donc, retourne dans ton pays; j’avais dit: Je l’honorerai; mais maintenant le Seigneur t’a privé de l’honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Et Balaam dit à Balac: N’ai-je point dit à tes messagers qui sont venus chez moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Balac dût-il me donner plein sa maison d’argent et d’or, il m’est impossible de ne pas tenir compte de la parole du Seigneur, et de faire moi-même qu’elle soit bonne ou mauvaise; ce que Dieu dira, je le dirai,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Maintenant que je retourne en mon pays, écoute, et je te révèlerai ce que ce peuple fera à ton peuple en la suite des temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Et, commençant son discours prophétique, il dit: Balaam, fils de Béor, parle; il parle cet homme, le voyant de la vérité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Qui a entendu les paroles de Dieu, qui tient sa science du Tout-Puissant, qui a vu dans son sommeil la vision de Dieu, et dont les yeux ont été dessillés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Je lui annoncerai Celui qui n’est pas encore, Celui que je glorifie et qui est éloigné; une étoile sortira de Jacob, un homme s’élèvera d’Israël, il broiera les princes de Moab, il dépouillera tous les fils de Seth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edom sera son héritage; Esau, son ennemi, sera son héritage; Israël a marché dans sa force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Il s’éveillera le lion de Jacob, et il détruira ce qui se sera échappé de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Et Balaam, dans sa vision, ayant vu Amalec, reprit son discours prophétique, et il dit: Amalec est à la tête des gentils, et cette race périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Et ayant vu le Cénéen, il reprit son discours prophétique, et il dit: Ta demeure est forte; mais quand même tu cacherais tes petits dans les rochers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Quand même des enfants de fourberie naîtraient pour Béor, Assur t’emmènera captif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Et ayant vu Og, il reprit son discours prophétique, et il dit: Hélas! hélas! qui vivra lorsque Dieu fera ces choses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Et Il sortira des mains des Citians, et ceux-ci humilieront Assur, et ils humilieront les Hébreux, et eux-mêmes périront tous à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Après cela, Balaam, s’étant levé, partit pour sa contrée, et Balac retourna dans sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Le peupie demeura en Settim, et il se souilla par la prostitution des filles de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Elles le convièrent aux sacrifices de leurs idoles; il mangea de leurs victimes, et il adora leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Israël fut consacré à Belphégor, et, en son cœur, le Seigneur s’irrita contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Le Seigneur dit à Moïse: Prends tous les chefs du peuple, et, à la lumière du soleil, fais un exemple devant le Seigneur; alors, la colère du Seigneur se détournera d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Moïse dit donc aux tribus d’Israël: Tuez ceux de vos frères qui sont consacrés à Belphégor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Or, l’un des fils d’Israël survint, et entraîna son frère chez une Madianite, devant Moïse et devant toute la synagogue des fils d’Israël, et ceux-ci se prirent à pleurer devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Ce que voyant Phinéès, fils d’Eléazar, fils du grand prêtre Aaron, il se leva du milieu de l’assemblée, et prit à la main une javeline,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Et il entra dans la chambre sur les pas de l’Israélite, et il perça l’homme et la femme, et celle-ci eut les entrailles déchirées; et la plaie qui affligeait Israël cessa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Cette plaie avait fait périr vingt-quatre mille âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Le Seigneur parla ensuite à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Phinéès, fils d’Eléazar, fils du grand prêtre Aaron, vient d’apaiser ma colère et de la détourner des fils d’Israël, contre lesquels je suis plein de jalousie; je n’ai pas exterminé les fils d’Israël, quoique je fusse jaloux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Répète ceci: J’accorde à Phinéès une alliance de paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Cette alliance sacerdotale sera perpétuelle pour lui et sa postérité, parce qu’il a été zélé pour son Dieu, et qu’il l’a apaisé en faveur des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'L’Israélite, frappé avec la Madianite, se nommait Zambri; il était fils de Salmon, l’un des chefs de famille de la tribu de Siméon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Et la Madianite s’appelait Cozbi; elle était fille de Sur, chef de la nation d’Ommoth, qui est une famille issue de Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Et le Seigneur parla à Moïse, disant: Parle aux fils d’Israël, dis-leur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Soyez ennemis des Madianites; frappez-les,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Parce qu’avec leurs ruses ils sont vos ennemis; ils vous ont trompés par le moyen de Phégor et de Cozbi, fille d’un chef de Madian, leur sœur, celle qui a été frappée le jour de la plaie que vous avait attirée Phégor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Après la plaie, il advint que le Seigneur parla à Moïse et au grand prêtre Eléazar, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Faites, par familles paternelles, le dénombrement des fils d’Israël de vingt ans et au-dessus, en état de porter les armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Moïse, avec le prêtre Eléazar, donna ses ordres en Araboth de Moab, vis-à-vis Jéricho, et il convoqua');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Les hommes de vingt ans et au-dessus, comme le Seigneur l’avait prescrit à Moïse. Voici les fils d’Israël qui sortirent de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben était le premier-né de Jacob; fils de Ruben: Enoch, et la famille des Enochites, Phallu, et la famille des Phalluites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Hesron, de qui sortit la famille des Hesronites; Charmi, de qui sortit la famille des Charmites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Telles étaient les branches de Ruben, et leur recensement donna quarante-trois mille sept cent trente âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Parmi les fils de Phallu, il y eut Eliab,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Les fils d’Eliab furent: Namuel, Dathan et Abiron; ils étaient illustres parmi le peuple, et ce furent eux qui se soulevèrent contre Moïse et Aaron lors du rassemblement de Coré et de la révolte contre le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Et la terre, ayant ouvert sa bouche, les dévora, dans le même temps que Coré périt avec son attroupement, lorsque le feu consuma les deux cent cinquante qui furent l’occasion d’un prodige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Mais les fils de Coré ne moururent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Voici les fils de Siméon et leurs familles: de Namuel, sortit la famille des Namuélites; de Jamin, celle des Jaminites; de Jachin, celle des Jachinites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'De Zaré, sortit la famille des Zaréites; de Saül, celle des Saülites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Telles étaient les branches de Siméon, et leur recensement donna vingt-deux mille deux cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Voici les fils de Juda: Her et Onan, qui moururent en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Et il y eut d’autres fils de Juda, et voici leurs familles de Séla, sortit la famille des Sélaïtes; de Pharès, celle des Pharésites; de Zara, celle des Zaraïtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Et les fils de Pharès furent: Hesron, de qui sortit la famille des Hesronites; et Jamun, de qui sortit la famille des Jamunites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Telles étaient les branches de Juda, comprenant, selon leur recensement, soixante-seize mille cinq cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Voici les fils d’Issachar, par familles: de Thola, sortit la famille des Tholaïtes; de Phua, celle des Phuaïtes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'De Jasub, celle des Jasubites; de Semram, celle des Semramites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Telles étaient les branches d’Issachar; d’après leur recensement, il y eut soixante-quatre mille quatre cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Voici les fils de Zabulon: de Sared, sortit la famille des Sarédites; d’Elon, celle des Elonites; de Jalel, celle des Jalélites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Telles étaient les branches de Zabulon, et leur recensement donna soixante mille cinq cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Voici les fils de Gad: de Séphon, sortit la famille des Séphonites; d’Aggi, celle des Aggites; de Suni, celle des Sunites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'D’Ozni, celle des Oznites; de Her, celle des Hérites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'D’Arod, celle des Arodites; d’Ariel, celle des Ariélites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Telles étaient les branches des fils de Gad; d’après leur recensement, il y eut quarante-quatre mille cinq cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Voici les fils d’Aser: de Jemna, sortit la famille des Jemnaïtes; de Jessui, celle des Jessuites; de Brié, celle des Briéites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'D’Hober, celle des Hobérites; de Melchiel, celle de Melchiélites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Aser eut aussi une fille du nom de Sara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Telles étaient les branches d’Aser; d’après leur recensement, il y eut quarante-trois mille quatre cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Voici les branches de Manassé et d’Ephraïm, fils de Joseph:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Familles des fils de Manassé: de Machir, sortit la familles des Machirites; Machir engendra Galaad; de Galaad, sortit la famille des Galaadites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Voici les fils de Galaad: de Jézer, sortit la famille des Jézérites; et d’Hélec, celle des Hélécites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'D’Asriel, celle des Asriélites; et de Sichem, celle des Sichémites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'De Sémida, celle des Sémidaïtes; et d’Epher, celle des Ephérites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Or, parmi les fils d’Epher, Salphaad n’eut point de fils, mais des filles, et voici les noms des filles de Salphaad Maala, Noa, Hégla, Melcha et Thersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Telles étaient les branches de Manassé, et leur recensement donna cinquante-deux mille sept cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Voici les fils d’Ephraïm de Suthala, sortit la famille des Suthalaïtes; de Bécher, celle des Béchérites; de Théhen, celle des Théhénites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Voici les fils de Suthala: Eden, et la famille de Edénites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Telles étaient les branches des fils d’Ephraïm, et leur recensement donna trente-deux mille cinq cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Telles étaient les branches des fils de Joseph. Voici les fils de Benjamin par familles: de Béla, sortit la famille des Bélaïtes; d’Asbel, celle des Asbélites; et d’Ahiram, celle des Ahiramites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'De Supham, celle des Suphamites; de Hupham, celle des Huphamites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Voici les fils de Béla; de Héred, sortit la famille des Hérédites; et de Noéman, celle des Noémanites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Telles étaient les branches des fils de Benjamin, et leur recensement donna trente-cinq mille cinq cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Voici les fils de Dan par familles: de Suham, fils de Dan, sortit la famille des Suhamites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Toutes les familles portaient le nom de Suham, et leur recensement donna soixante-quatre mille quatre cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Voici les fils de Nephthali par familles: de Jésiel, sortit la famille des Jésiélites; de Gémi, celle des Gémites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'De Jéser, celle des Jésérites; et de Sellem, celle des Sellémites,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Telles étaient les branches de Nephthali, et leur dénombrement donna quarante-trois mille trois cents âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Voici le total du dénombrement des fils d’Israël: six cent un mille sept cent trente hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Le Seigneur parla ensuite à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'La terre sera partagée par têtes entre ces hommes, pour qu’ils la possèdent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Aux plus nombreux, tu donneras les plus fortes parts, et aux moins nombreux des parts moindres, chacun selon le recensement aura sa part d’héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'La terre sera partagée au sort par chaque tête; on tirera les sorts par tribus paternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Tu leur distribueras leur héritage par la voie du sort, quel que soit le nombre de la tribu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Voici les fils de Lévi par familles; de Gerson, sortit la famille des Gersonites; de Caath, celle des Caathites; et de Mérari, celle des Mérarites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Voici les familles des fils de Lévi: les Lobénites, les Hébronites, les Coréites, les Musites; Caath engendra aussi Amram;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'La femme de celui-ci se nommait Jochabed, issue de Lévi; elle eut tous ses enfants en Égypte, et fut mère d’Aaron, de Moïse et de leur sœur Marie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'D’Aaron naquirent Nadab, Abiu, Eléazar et Ithamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Nadab et Abiu moururent pendant qu’ils offraient au Seigneur un feu étranger, dans le désert de Sina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Le recensement des lévites donna vingt-trois mille mâles d’un mois et au-dessus; ils n’avaient point été recensés avec les fils d’Israël, parce qu’il ne leur était point donné d’héritage parmi les fils d’ Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Tel fut le dénombrement des fils d’Israël que firent Moïse et Eleazar le prêtre, en Araboth de Moab, sur les rives du Jourdain, en face de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Dans ce nombre, il n’y avait pas un homme qui eût été recensé par Moïse et Aaron, lors du dénombrement fait dans le désert de Sina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Car le Seigneur avait dit: Ils mourront de mort dans le désert, et pas un d’eux n’était resté, hormis Caleb, fils de Jéphoné, et Josué, fils de Nau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Alors, les filles de Salphaad, fils d’Opher, fils de Galaad, fils de Machir, de la tribu de Manassé, des fils de Joseph, se présentèrent, et voici leurs noms: Maala, Noa, Egla, Melcha et Thersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Et, se tenant devant Moïse, ainsi que devant Eleazar le prêtre, devant les chefs et toute la synagogue, vers la porte du tabernacle du témoignage, elles dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Notre père est mort dans le désert, et il n’était point de l’attroupement de Coré, soulevé contre le Seigneur; il est mort à cause de son propre péché, et il n’avait pas de fils. Que le nom de notre père ne soit pas effacé du milieu de sa tribu, parce qu’il n’a point laissé de fils; donneznous une possession parmi les frères de notre père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Moïse porta leur demande devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Les filles de Salphaad ont parlé selon la justice; tu leur donneras un héritage parmi les frères de leur père, tu leur attribueras le lot qu’aurait eu leur père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Tu parleras ensuite aux fils d’Israël, et tu leur diras:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Si un homme meurt, et qu’il n’ait point de fils, vous donnerez son héritage à ses filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'S’il n’a pas de filles, vous donnerez son héritage à son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'S’il n’a point de frère, vous donnerez son héritage au frère de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'S’il n’existe point de frère de son père, vous donnerez son héritage à son plus proche parent dans sa tribu, pour que celui-ci possède ce qui lui appartient; loi inviolable pour les fils d’Israël, selon ce que le Seigneur a prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Et le Seigneur dit à Moïse: Monte sur la hauteur qui borne la vallée du Jourdain: c’est le mont Nébo, et de là, vois la terre de Chanaan que je donne pour héritage aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Tu la verras, et tu iras aussi te réunir à ton peuple, comme s’y est réuni ton frère Aaron sur la montagne de Hor;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Parce que vous avez méprisé ma parole dans le désert de Sin, lorsque la synagogue a refusé de me sanctifier; vous ne m’avez point sanctifié au sujet de l’eau en leur présence; c’était l’eau de la contradiction, en Cadès, dans le désert de Sin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Et Moïse dit au Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Que le Seigneur des esprits et de toute chair discerne et choisisse un homme');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Qui entre et sorte à la tête du peuple, et qui le mène et le ramène, afin que la synagogue du Seigneur ne soit pas comme un troupeau qui n’a point de pasteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Et le Seigneur parla à Moïse, disant: Prends avec toi Josué, fils de Nau; l’homme a en lui l’esprit, et tu lui imposeras les mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Tu le placeras devant Éléazar le prêtre, et tu lui donneras mes ordres devant la synagogue, et tu donneras mes ordres au peuple à son sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Tu répandras sur lui ta gloire, afin que les fils d’Israël lui obéissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Il se tiendra devant Eléazar le prêtre, et on lui demandera le jugement des lumières du Seigneur. Au commandement de la bouche du Seigneur, lui et les fils d’Israël, d’un commun accord, iront et reviendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Moïse fit ce qu’avait prescrit le Seigneur; il prit Josué et il le plaça devant Eléazar le prêtre, et devant tout le peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Il lui imposa les mains, et il le constitua chef d’Israël, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Le Seigneur parla encore à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Donne mes ordres aux fils d’Israël, et dis-leur: Vous ne négligerez pas de m’offrir en vos fêtes mes présents, mes offrandes, mes oblations d’odeur de suavité agréable au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Dis-leur: Voici les holocaustes que vous présenterez au Seigneur des agneaux d’un an, sans tache, deux par jour, en holocauste perpétuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Tu sacrifieras le premier agneau le matin, et tu sacrifieras le second le soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Tu présenteras, comme oblation, le dixième d’un éphi de fleur de farine, pétrie dans un quart de mesure (hin) d’huile,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'C’est l’holocauste perpétuel qui a commencé sur le mont Sina, odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'La libation sera d’un quart de mesure par agneau; tu la répandras dans le sanctuaire pour le Seigneur; elle sera de liqueur fermentée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Et tu sacrifieras le second agneau le soir; tu le sacrifieras avec la même oblation et la même libation, comme odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Le jour du sabbat, chaque sacrifice sera de deux agneaux d’un an sans tache, et il y aura deux décimes de fleur de farine pétrie dans l’huile pour l’oblation, et une double libation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Ce sera l’holocauste des sabbats, outre l’holocauste perpétuel et sa libation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Aux nouvelles lunes, vous sacrifierez en holocauste au Seigneur: deux veaux pris parmi les bœufs, un bélier et sept agneaux d’un an sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Il y aura trois décimes de fleur de farine pétrie dans l’huile, par veau, deux décimes de fleur de farine pétrie dans l’huile, par bélier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Et un décime de décime de fleur de farine pétrie dans l’huile, par agneau; c’est l’oblation d’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Leur libation sera d’une demi-mesure par veau, d’un tiers de mesure par bélier, et d’un quart de mesure de vin par agneau; tel est l’holocauste pour chaque lune de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Et pour le péché, un bouc pris parmi les chèvres sera sacrifié au Seigneur, outre l’holocauste perpétuel, et il y sera joint sa libation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Et le premier mois, le quatorzième jour de la lune, pâque du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Le quinzième jour de la lune, c’est la solennité: pendant sept jours vous mangerez des azymes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Le premier de ces jours sera solennel et saint pour vous; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Et vous amènerez des holocaustes pour les sacrifier au Seigneur, savoir: deux veaux pris parmi les bœufs, un bélier, sept agneaux d’un an, tous à vos yeux sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Leur oblation sera de fleur de farine pétrie dans l’huile trois décimes par veau, deux décimes par bélier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Et un décime de décime par agneau, pour les sept agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Tu offriras aussi pour le péché un bouc pris parmi les chèvres qui expiera les péchés de tous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Outre l’holocauste perpétuel du matin, qui ne doit pas discontinuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Vous offrirez ainsi chaque jour, pendant les sept jours de la fête, vos sacrifices d’odeur de suavité pour le Seigneur, outre l’holocauste perpétuel; tu feras les libations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Et le septième jour sera saint et très-célèbre pour vous; vous ne ferez ce jour-là aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Et le jour des moissons nouvelles, lorsque vous offrirez au Seigneur le nouveau sacrifice des semaines, ce jour sera saint et célèbre pour vous; vous ne ferez aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Et vous offrirez en holocauste, comme sacrifice d’odeur de suavité pour le Seigneur, deux veaux pris parmi les bœufs, un bélier et sept agneaux d’un an, sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Leur oblation sera de fleur de farine pétrie dans l’huile trois décimes pour un veau, deux décimes pour un bélier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Un décime de décime par agneau, pour les sept agneaux; et vous offrirez un bouc pris parmi les chèvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Pour le péché, afin qu’il expie le péché de vous tous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Outre l’holocauste perpétuel; et vous me sacrifierez des victimes elles seront à vos yeux sans tache, et accompagnées de leurs libations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Le septième mois, le premier jour de la lune sera solennel et saint pour vous; vous ne ferez aucune œuvre servile; c’est pour vous le jour des signaux que donnent ·les trompettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Et vous offrirez en holocauste, comme sacrifice d’odeur de suavité pour le Seigneur, un veau pris parmi les bœufs, un bélier et sept agneaux d’un an, sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Leur oblation sera de fleur de farine pétrie dans l’huile, trois décimes par veau, deux décimes par bélier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'Un décime de décime par agneau, pour les sept agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Et vous offrirez pour le péché un bouc pris parmi les chèvres qui expiera les péchés de vous tous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Outre les holocaustes, à cause de la nouvelle lune, et leurs oblations et leurs libations, et outre l’holocauste perpétuel les oblations et les libations seront faites selon la règle; ce sera le sacrifice d’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Le dixième jour de la même lune sera solennel et saint pour vous, et vous ne ferez aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Vous offrirez en holocauste, comme sacrifice d’odeur de suavité pour le Seigneur, un veau pris parmi les bœufs, un bélier et sept agneaux d’un an, tous à vos yeux sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Et leur oblation sera de fleur de farine pétrie dans l’huile, trois décimes par veau, deux décimes par bélier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Un décime de décime par agneau, pour les sept agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Et vous offrirez pour le péché un bouc pris parmi les chèvres qui expiera le péché de vous tous, outre celui de la purification, et outre l’holocauste perpétuel; les oblations et les libations se feront selon la règle; ce sera le sacrifice d’odeur de suavité pour le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Le quinzième jour de ce septième mois sera solennel et saint pour vous; vous ne ferez aucune œuvre servile, et vous ferez pendant sept jours la fête du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Vous offrirez en holocauste, comme sacrifice d’odeur de suavité pour le Seigneur: le premier jour, treize veaux pris parmi les bœufs, deux béliers, quatorze agneaux d’un an, tous sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Leurs oblations seront de fleur de farine pétrie dans l’huile, trois décimes par veau pour les treize veaux, deux décimes par bélier pour les deux béliers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'Un décime de décime par agneau, pour les quatorze agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Et vous offrirez pour le péché un bouc pris parmi les chèvres, outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Et le second jour: douze veaux, deux béliers, quatorze agneaux d’un an, tous sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Les oblations et les libations seront quant aux veaux, aux béliers et aux agneaux, selon leur nombre et selon la règle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Et vous offrirez pour le péché un bouc pris parmi les chèvres; outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Le troisième jour: onze veaux, deux béliers, quatorze agneaux sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Les oblations et les libations pour les veaux, les béliers et les agneaux se feront selon le nombre des victimes, et selon la règle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Vous offrirez, pour le péché, un bouc pris parmi les chèvres, outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Et le quatrième jour: dix veaux, deux béliers, quatorze agneaux d’un an sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Les oblations, les libations, pour les veaux, les béliers et les agneaux, se feront selon le nombre des victimes et selon la règle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Vous offrirez aussi pour le péché un bouc pris parmi les chèvres, outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Et le cinquième jour: neuf veaux, deux béliers, quatorze agneaux d’un an sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Les oblations et les libations, pour les veaux, les béliers et les agneaux se feront selon le nombre des victimes et selon la règle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'De plus vous offrirez pour le péché un bouc pris parmi les chèvres, outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Et le sixième jour: huit veaux, deux béliers, quatorze agneaux d’un an saps tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Les oblations et les libations, pour les veaux, les béliers et les agneaux, se feront selon le nombre des victimes et selon la règle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Et vous offrirez pour le péché un bouc pris parmi les chèvres, outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Le septième jour: sept veaux, deux béliers, quatorze agneaux d’un an sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Les oblations et les libations, pour les veaux, les béliers et les agneaux, se feront selon le nombre des victimes et selon la règle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Vous offrirez ensuite pour le péché un bouc pris parmi les chèvres, outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Le huitième jour sera pour yous la fin de la fête; vous ne ferez ce jour-là aucune œuvre servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Et vous offrirez en holocauste, comme sacrifice d’odeur de suavité pour le Seigneur, un veau, un bélier, sept agneaux d’un an sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Les oblations et les libations seront selon le nombre des victimes et selon la règle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Et vous offrirez pour le péché un bouc pris parmi les chèvres, outre les offrandes de l’holocauste perpétuel, leurs oblations et leurs libations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Tels sont les sacrifices que vous ferez au Seigneur en vos fêtes; il y aura en outre vos vœux, vos dons volontaires, vos holocaustes, vos oblations et libations, et vos hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Moïse rapporta aux fils d’Israël tout ce que lui avait prescrit le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Et Moïse parla aux chefs des tribus d’Israël, et il leur dit Voici la chose qu’a prescrite le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Quiconque aura fait un vœu au Seigneur, ou aura fait un serment, ou aura fait une promesse touchant sa propre vie, ne souillera pas sa parole; il exécutera ce qui est sorti de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Si c’est une femme qui a fait un vœu au Seigneur, ou fait une promesse en sa jeunesse dans la maison de son père; si son père apprend ce vœu ou cette promesse, et s’il garde le silence, tous ces vœux subsisteront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Tout ce qu’elle aura promis touchant sa vie, demeurera en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Mais, si son père lui refuse son consentement, le jour où il aura appris ses vœux ou ses promesses faites touchant sa vie, ces vœux, ces promesses ne subsisteront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Si elle se marie, si elle tombe sous la puissance d’un époux encore chargée de ses vœux ou des promesses de ses lèvres faites touchant sa vie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Et si son mari l’apprend, et s’il garde le silence le jour où il l’aura appris, ces vœux, ces promesses faites touchant sa vie, subsisteront pareillement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Mais, si son mari lui refuse son consentement le jour où il aura appris ses vœux ou ses promesses faites touchant sa vie, ni ces vœux, ni ces promesses ne tiendront, parce que son mari lui aura refusé son consentement, et le Seigneur la purifiera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Le vœu d’une veuve ou d’une femme répudiée, la promesse qu’elle aura faite touchant sa vie, demeureront en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Si le vœu de la femme est fait dans la maison de son mari, et qu’elle y fasse sous serment une promesse touchant sa vie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Si son mari l’apprend, et s’il garde le silence avec elle, et s’il ne lui refuse pas son consentement, ses vœux, ses promesses faites touchant sa vie, subsisteront contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Mais, si son époux, le jour où il aura appris ce qui est sorti de ses lèvres, annule ses vœux ou ses promesses touchant sa vie, ces vœux et ces promesses ne subsisteront pas, parce que son époux les aura annulés, et le Seigneur la purifiera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Tout vœu, tout serment qui la lierait pour affliger sa vie, devra être confirmé par son époux, ou il l’en affranchira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'S’il garde le silence plusieurs jours, il aura confirmé les vœux et les promesses dont elle était chargée; il les aura confirmés pour elle, parce qu’il aura gardé le silence le jour où il les aura appris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Mais si l’époux, passé le jour où il les aura appris, les annule, il assumera sur lui le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Telles sont les règles que le Seigneur a prescrites à Moïse entre le mari et la femme, entre le père et ses jeunes filles demeurant en la maison paternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Poursuis la vengeance des fils d’Israël contre les Madianites, puis tu seras réuni à ton peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Et Moïse parla au peuple, et il lui dit: Armez parmi vous les hommes, et marchez contre Madian, pour lui faire sentir la vengeance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Envoyez au combat mille hommes par tribu pris dans toutes les tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Et l’on compta, parmi les myriades d’Israélites, mille hommes par tribu; en tout douze mille hommes armés en guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Et Moïse fit partir les mille hommes par tribu formant une armée, avec Phinéès, fils d’Eléazar, fils d’Aaron leur prêtre, auquel il donna les vases saints et les trompettes des signaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Ils en vinrent aux mains avec Madian, comme l’avait prescrit Moïse, et ils tuèrent toute la population mâle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Et ils tuèrent les rois de Madian, au milieu des hommes tués: Evi, Recun, Sur, Hur et Ribé, tous les cinq rois de Madian; dans le carnage, ils firent périr aussi, par le glaive, Balaam, fils de Béor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Et ils firent captives les femmes de Madian; ils pillèrent leurs bagages, leur bétail, tout ce qu’ils possédaient, et ils abattirent leur puissance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Et ils livrèrent aux flammes toutes leurs villes et tous leurs villages,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Et ils prirent tout leur butin, tout ce qu’ils avaient enlevé depuis l’homme jusqu’aux bestiaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Et ils conduisirent à Moïse, à Eléazar le prêtre, à tous les fils d’Israël, leurs captures, leurs prises, leur butin, dans le camp d’Araboth de Moab, sur la rive du Jourdain en face de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Moïse sortit du camp à leur rencontre avec Eléazar et tous les princes du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Et Moïse s’irrita contre les chefs de l’armée, chefs de mille hommes et centeniers revenant du combat;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Et Moïse leur dit: Pourquoi avez-vous pris vivantes toutes les femmes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Ce sont elles qui se donnaient aux fils d’Israël, selon le conseil de Balaam, pour leur faire renier et mépriser la parole du Seigneur, à cause de Phégor; et de là est venue la plaie de la synagogue du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Puis donc que vous avez tué tous les hommes, sans en épargner un seul, tuez pareillement toute femme qui a eu commerce avec l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'N’épargnez que celles qui n’ont point connu l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Cependant, dressez vos tentes hors du camp, demeurez-y sept jours; quiconque aura transporté ou touché un cadavre, sera purifié le troisième et le septième jour; vous serez purifiés avec votre butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Et vous purifierez vos vêtements, vos ustensiles de cuir, vos tissus de poil de chèvre, vos vases de bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Eleazar aussi dit aux hommes de l’armée revenant du combat: Voici les détails de la loi de purification que le Seigneur a prescrite à Moïse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'L’or, l’argent, l’airain, le fer, le plomb et l’étain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Tout ce qui résiste à la flamme sera purifié par le feu et non par l’eau de la purification; tout ce qui ne va pas au feu sera passé à l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Vous laverez vos vêtements le septième jour et vous serez purifiés; après cela vous rentrerez dans le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Prends le nombre des objets sauvés depuis l’homme jusqu’au bétail, prends-le avec Eléazar le prêtre et les princes des tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Partagez par moitié le butin entre les hommes qui ont combattu et toute la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Et réservez la part du Seigneur; prenez sur la moitié qui revient aux hommes qui ont combaltu une tête sur cinq cents, tant des femmes que des bœufs, brebis, chèvres et ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Et donnez à Eléazar le prêtre les prémices du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Et sur la moitié revenant aux fils d’Israël, tu prendras une tête sur cinquante, tant des femmes que des bœufs, brebis, chèvres ou ânes, et tu les donneras aux lévites qui veillent à la garde du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Moïse, aidé d’Eléazar le prêtre, ce que le Seigneur avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Et le nombre exorbitant des têtes de bétail que les hommes de guerre avaient enlevé, s’éleva à six cent soixante-quinze mille brebis ou chèvres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Soixante-douze mille bœufs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Et soixante-un mille ânes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Et il y eut trente-deux mille âmes humaines, c’est-à-dire femmes n’ayant point connu l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'La part de ceux qui avaient combattu fut d’abord la moitié des brebis ou chèvres: trois cent trente-sept mille cinq cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Il y eut pour la part du Seigneur six cent soixantequinze brebis ou chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Et il y eut pour les hommes trente-six mille bœufs, et pour la part du Seigneur soixante-douze bœufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Et il y eut encore pour les hommes trente mille cinq cents ânes, et pour la part du Seigneur soixante-un ânes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Et il y eut pour les hommes seize mille âmes humaines, et pour la part du Seigneur trente-deux âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Et Moïse, comme le lui avait prescrit le Seigneur, donna à Eléazar le prêtre, la part du Seigneur, les prémices de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Prises sur la moitié revenant à ceux des fils d’Israël qui avaient combattu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'Et la moitié revenant à la synagogue fut de trois cent trente-sept mille cinq cents brebis ou chèvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Trente-six mille bœufs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Trente mille cinq cents ânes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Et seize mille âmes humaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Et, sur la moitié des fils d’Israël, Moïse prit une tête sur cinquante depuis l’homme jusqu’aux bestiaux, et il les donna aux lévites gardiens du tabernacle du Seigneur, comme le Seigneur le lui avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Et tous les chefs de l’armée, chefs de mille hommes ou centeniers, vinrent trouver Moïse, et ils lui dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Tes serviteurs ont emmené le nombre d’hommes de guerre que tu leur avais confié, et pas un d’eux n’a péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Et tous ceux de nous qui ont combattu apportent un don au Seigneur: soit un vase d’or, soit un collier, soit un bracelet, soit un anneau, soit une épingle à cheveux; nous consacrons ces joyaux au Seigneur pour nous le rendre propice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Et Moïse et Eléazar le prêtre, prirent de leurs mains cet or et ces joyaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Et ces joyaux d’or pris par les chefs de mille et les centeniers pesaient seize mille sept cent cinquante sicles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Car chaque homme de guerre avait eu pour soi le butin qu’il avait pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Et Moïse et Eléazar prirent l’or des chefs de mille et des centeniers; et ils portèrent les vases dans le tabernacle du témoignage pour être un mémorial des fils d’Israël devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Or, les fils de Ruben et les fils de Gad étaient fort riches en bétail, et ils virent que la contrée de Jazer et la contrée de Galaad étaient excellentes pour les troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Et les fils de Ruben avec les fils de Gad s’étant approchés, parlèrent à Moïse, à Eléazar le prêtre, et à tous les princes du peuple, et ils leur dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Ataroth, et Dibon, et Jazer, et Namra, et Esebon, et Eléalé, et Sébama, et Nébo, et Béon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Et la terre que le Seigneur vient de donner aux fils d’Israël, sont une contrée nourricière de bestiaux, et tes serviteurs ont des bestiaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Ils ajoutèrent: Si nous avons trouvé grâce devant toi, que cette terre soit donnée pour héritage à tes serviteurs, et ne nous conduis pas au delà du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Moïse répondit aux fils de Ruben et au fils de Gad: Vos frères vont au combat, et vous, resterez-vous ici?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Pourquoi détournez-vous les pensées des fils d’Israël qui ne voudront plus entrer dans la terre que le Seigneur leur a donnée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'N’est-ce point ce qu’ont fait vos pères, lorsque, de Cadès-Barné, je les ai envoyés reconnaître ce territoire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Ils sont allés jusqu’à la vallée de la Grappe, ils ont reconnu le pays, et ils ont détourné le cœur des fils d’Israël pour les empêcher d’entrer en la terre que le Seigneur leur avait donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Alors, le Seigneur s’irrita, et il dit avec serment:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Jamais ces hommes qui sont sortis d’Égypte, ceux de vingt ans et au-dessus, discernant le bien et le mal, ne verront la terre que j’ai promise à Abraham, à Isaac et à Jacob; car ils n’ont point voulu me suivre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Hormis Caleb, fils de Jéphoné, et Josué, fils de Nau qui s’est séparé des autres envoyés, parce que ceuxlà n’ont pas hésité à me suivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Et le Seigneur s’étant irrité contre les fils d’Israël, les a fait tourner sur eux-mêmes dans le désert, durant quarante années, jusqu’à ce qu’ait péri toute cette génération qui avait fait le mal devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Et vous, race d’hommes coupables, voilà que vous vous soulevez comme vos pères, pour augmenter encore le courroux du Seigneur contre Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Vous voulez vous séparer de lui, et encore une fois l’abandonner dans le désert; mais vous pècherez contre toute cette synagogue!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Et ils s’approchèrent de Moïse, et ils dirent: Nous bâtirons ici des étables pour nos brebis et nos grands troupeaux; nous bâtirons des villes pour nos familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Quant à nous, armés de pied en cap, nous marcherons au premier rang des fils d’Israël, jusqu’à ce que nous les avons conduits où ils doivent résider, pendant que nos familles demeureront dans les villes que nous aurons fortifiées contre les habitants de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nous ne retournerons pas les rejoindre, que les fils d’Israël ne se soient partagés leurs héritages respectifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Et nous n’aurons point de part sur l’autre rive du Jourdain, parce que nous prenons pour notre héritage la rive orientale du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Moïse leur répondit: Si vous agissez selon cette promesse, si devant le Seigneur vous vous armez pour la guerre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'Si les combattants de vos tribus marchent au delà du Jourdain, devant le Seigneur, jusqu’à ce que ses ennemis soient broyés en sa présence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'Et qu’en sa présence la terre soit conquise, vous pourrez partir, et vous serez innocents aux yeux du Seigneur et aux yeux d’Israël; et la terre que vous demandez vous appartiendra devant le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mais si vous faites autrement, vous serez coupables devant le Seigneur; et vous connaîtrez votre péché quand des plaies vous seront infligées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Bâtissez donc des villes pour vos familles, et des étables pour vos troupeaux; exécutez tout ce qui est sorti de votre bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Les fils de Ruben et les fils de Gad dirent alors à Moïse Tes serviteurs feront ce que notre maître nous ordonne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Nos serviteurs, et nos femmes, et tout notre bétail, demeureront dans les villes de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Et tes serviteurs marcheront en ordre et armés, en présence du Seigneur, pour combattre, comme le Seigneur l’a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Moïse réunit auprès d’eux Eléazar le prêtre, et Josué, fils de Nau, et les princes des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Et Moïse dit à ces derniers: Si les fils de Ruben et les fils de Gad passent avec vous le Jourdain, tous armés pour la guerre, devant le Seigneur; si vous soumettez la terre au delà du fleuve, vous leur donnerez en héritage la terre de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Mais, s’ils ne marchent pas avec vous, armés pour la guerre, devant le Seigneur, faites passer avant vous, dans la terre de Chanaan, leurs serviteurs, leurs femmes et leur bétail, et donnez-leur une part de la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Les fils de Ruben et les fils de Gad répondirent: Ce que le maître dit à ses serviteurs, nous le ferons;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Nous entrerons en armes, devant le Seigneur, dans la terre de Chanaan, et vous nous donnerez notre part, sur la rive gauche du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Moïse, donna donc aux fils de Gad, et aux fils de Ruben, et à la moitié de la tribu de Manassé, le royaume de Séhon, roi des Amorrhéens, et le royaume d’Og, roi de Basan, terre et villes, villes et banlieues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Et les fils de Gad bâtirent Dibon, Ataroth, Aroër,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Sophar et Jazer, et ils les fortifièrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Ils bâtirent aussi Namram et Bétharam, villes fortes, avec des étables pour les troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Les fils de Ruben bâtirent Esebon, Eléalé, Cariathim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Et Béelméon, villes entourées de murs, ainsi que Sabana; et ils donnèrent leurs propres noms aux villes qu’ils élevèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Et le fils de Machir, fils de Manassé, alla à Galaad; il la prit, et détruisit l’Amorrhéen qui l’habitait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Moïse donna Galaad à Machir, fils de Manassé, qui y demeura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Et Jaïr, fils de Manassé, marcha, et il prit les villages des Amorrhéens, et il les appela: Villages de Jaïr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Et Nébo marcha, prit Caath et ses bourgs, et leur donna son nom; il les appela Nébo.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Voici les stations des fils d’Israël, après que Moïse et Aaron les eurent fait sortir d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Par les ordres du Seigneur, Moïse écrivit leurs départs et leurs campements. Or, voici ces stations:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Ils partirent de Rhamessès le premier mois, le quinzième jour de la lune; le lendemain de la pâque, les fils d’Israël partirent sous une haute et puissante main, devant tous les fils de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Les Égyptiens ensevelirent chez eux tous les morts qu’avait frappés le Seigneur, tous les premiers-nés de la terre d’Égypte, et le Seigneur tira vengeance de leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Partis de Rhamessès, les fils d’Israël campèrent en Soccoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Partis de Soccoth, ils campèrent à Etham (Othom), qui est à l’extrémité du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Ils partirent d’Etham, et campèrent vers le golfe de Phihahiroth, qui est en face de Béelséphon, et ils étaient campés vis-à-vis Magdole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Partis de Phihahiroth, ils passèrent au milieu de la mer Rouge pour gagner le désert, et ils firent trois journées de marche dans le désert, et ils campèrent à Mara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Ils quittèrent Mara, et vinrent en Elim. Or, il y avait à Elim douze fontaines et soixante-dix tiges de palmiers; ils campèrent en ce lieu, à cause de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Puis, ils partirent d’Elim, et ils campèrent au bord de la mer Rouge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Et ils partirent de la mer Rouge, et ils campèrent dans le désert de Sin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Partis du désert de Sin, ils vinrent camper en Daphca.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Et ils partirent de Daphca, et ils campèrent en Alus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Et ils partirent d’Alus, et ils campèrent à Rhaphidin; or, il n’y avait point là de l’eau pour que le peuple pût boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Ayant quitté Rhaphidin, ils dressèrent leurs tentes dans le désert de Sina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Du désert de Sina, ils vinrent camper aux Sépulcres de concupiscence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Ils s’éloignèrent des Sépulcres de concupiscence, et campèrent à Haseroth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Partis d’Haseroth, ils allèrent camper à Rethma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'De Rethma, ils vinrent camper en Rhemmompharès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Ils partirent de Rhemmompharès, et ils campèrent en Lebna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Partis de Lebna, ils campèrent en Ressa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'De Ressa, ils vinrent dresser leurs tentes en Céélatha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Et ils partirent de Céélatha, pour aller camper à Sépher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Ayant quitté Sépher, ils campèrent en Arada.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Ils partirent d’Arada, et campèrent en Maceloth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'De Maceloth, ils dressèrent leurs tentes en Thabath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Et ils partirent de Thabath, pour venir camper à Tharé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Partis de Tharé, ils campèrent à Methca.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'De Methca, ils vinrent camper à Hesmona.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Et ils partirent de Hesmona, pour aller camper à Moseroth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Ayant quitté Moseroth, ils campèrent à BénéJaacan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Partis de Béné-Jaacan, ils vinrent camper en la montagne de Gadgad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'De la montagne de Gadgad, ils vinrent camper à Jétébatha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Et ils partirent de Jétébatha, pour aller dresser leurs tentes en Hébrona.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Puis, ayant quitté Hébrona, ils campèrent en AsionGaber.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Partis d’Asion-Gaber, ils vinrent camper dans le désert de Sin, d’où, étant sortis, ils campèrent dans le désert de Pharan qui est Cadès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Partis de Cadès-Barné, ils vinrent camper sur la montagne de Hor, près de la terre d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Et Aaron monta sur la montagne par ordre du Seigneur, et il y mourut, en la quarantième année de la sortie d’Égypte, le cinquième mois, le premier de la lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aaron avait cent vingt-trois ans lorsqu’il mourut sur la montagne de Hor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Et, le Chananéen, roi d’Arad, qui demeurait en la terre de Chanaan, apprit que les fils d’Israël étaient en marche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Ils partirent ensuite de la montagne de Hor, et vinrent camper en Salmona.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Ayant quitté Salmona, ils campèrent en Phunon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Partis de Phunon, ils dressèrent leurs tentes à Oboth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Puis, ils s’éloignèrent d’Oboth, pour venir camper à Gié-Abarim, au delà et près des frontières de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Et ils partirent de Gié-Abarim, pour séjourner à Dibon-Gad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'De Dibon-Gad, ils vinrent camper à Helmon-Déblathaim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Partis de Helmon-Déblathaïm, ils campèrent sur les montagnes d’Abarim, en face de Nébo.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Ayant quitté les montagnes d’Abarim, il campèrent à l’occident de Moab, sur le Jourdain, en face de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Ensuite, ils campèrent aux bords du Jourdain de Beth-Simoth, à Abelsatim, à l’occident de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Et le Seigneur parla à Moïse, à l’occident de Moab, sur le Jourdain, en face de Jéricho, et il lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Parle aux fils d’Israël, et dis-leur: Vous allez traverser le Jourdain pour entrer en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Et, devant vous, vous exterminerez tous ceux qui habitent cette terre; vous détruirez leurs tours, leurs idoles jetées en fonte, et leurs colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Vous détruirez tous les peuples de la terre promise, et vous l’habiterez; car je vous la donne pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Vous la partagerez entre vos tribus; donnant plus aux plus nombreux, et moins aux moindres en nombre. Quelle que soit la part qu’à chacun désignera le sort, chacun la possèdera; le partage se fera par tribus paternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Mais, si vous n’exterminez pas devant vous tous les habitants de la terre, ceux que vous aurez épargnés seront des traits en vos yeux, des flèches en vos flancs; ils seront vos ennemis sur la terre que vous habiterez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Et alors, je vous traiterai vous-mêmes comme j’avais résolu de les traiter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Donne mes ordres aux fils d’Israël, et dis-leur: Vous allez entrer en la terre de Chanaan; cette terre, avec ses limites, vous appartiendra comme héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Au midi, vous la possèderez depuis le désert jusqu’au territoire d’Edom; de ce côté, la limite sera d’abord le rivage oriental de la mer Salée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Vos limites au midi tourneront autour de la montée d’Acrabin; elles traverseront Ennac (Senna), et elles descendront au delà de Cadès-Barné; puis, elles sortiront du village d’Arad, et elles passeront par Asémona.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'À partir d’Asémona, elles suivront les contours du torrent d’Égypte, et finiront à la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Ensuite, vous aurez pour limites la mer, la grande mer vous limitera; ce sera la frontière occidentale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Au nord, voici quelle sera votre limite: à partir de la mer, vous mesurerez pour vous la montagne, le long de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Et vous mesurerez pour vous de montagne en montagne; votre frontière, après être entrée dans Emath, ira jusqu’à Saradac (Sadada).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Ensuite, elle sortira de Déphron (Zéphronie), et finira en Arsenain (Enan): telle sera votre frontière du nord.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Et vous mesurerez votre frontière orientale d’Arsenaïn à Séphama;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Elle descendra de Séphama en Béla (Rébla), au delà des frontières, et de Béla à l’extrémité de la rive orientale de la mer de Cénéreth (Génésareth).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Puis, elle suivra le cours du Jourdain, et elle finira par la mer Salée: telle sera votre terre, telles seront ses limites tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Moïse donna donc cet ordre aux fils d’Israël, disant: Voici la terre que vous vous partagerez au sort, comme l’a prescrit le Seigneur, pour la distribuer aux neuf tribus et à la demi-tribu de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Car les fils de Ruben, les fils de Gad, pár familles paternelles, et une demi-tribu de Manassé, ont reçu leurs parts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Deux tribus et une demi-tribu ont pris leur part, vis-à-vis Jéricho, sur la rive orientale du Jourdain, au sud-est.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Voici les noms des hommes qui procèderont au partage de la terre: Eléazar le prêtre, et Josué, fils de Nau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Et vous prendrez par tribu un prince qui tirėra au sort la part de la tribu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Voici les noms de ces princes, pour la tribu de Juda Caleb, fils de Jéphoné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Pour la tribu de Siméon: Samuel, fils d’Ammiud.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Pour la tribu de Benjamin: Elidad, fils de Chaselon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Pour la tribu de Dan: Bocchi, fils de Jogli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Pour les fils de Joseph, de la tribu de Manassé: Hanniel, fils d’Ephod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Pour la tribu d’Ephraïm: Camuel, fils de Sephthan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Pour la tribu de Zabulon: Elisaphan, fils de Pharnach.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Pour la tribu d’Issachar: Phaltiel, fils d’Ozan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Pour la tribu d’Aser: Ahiud, fils de Salomi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Et pour la tribu de Nephthali: Phédaël, fils d’Ammiud.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Tels furent ceux à qui le Seigneur ordonna de faire les parts des fils d’Israël, en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Le Seigneur parla à Moïse, à l’occident de Moab, sur le Jourdain, vis-à-vis Jéricho, et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Donne mes ordres aux fils d’Israël: que sur leurs parts ils donnent aux lévites des villes que ceux-ci habiteront; qu’ils leur donnent les banlieues de ces villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Les villes seront leur demeure, les banlieues celle de leur bétail et de leurs bêtes de somme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Les banlieues des villes des lévites s’étendront depuis les remparts jusqu’à une distance de deux mille coudées tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Vous mesurerez, hors de la ville, deux mille coudées au levant, deux mille coudées au midi, deux mille coudées au couchant, deux mille coudées au nord; puis, vous donnerez aux lévites la ville placée au milieu et tout ce territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Et vous donnerez aux lévites: d’abord les six villes d’asile, où pourra se réfugier quiconque aura commis un meurtre, et en outre quarante-deux villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Vous donnerez donc en tout aux lévites quarantehuit villes avec leurs banlieues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Et, sur les parts des fils d’Israël, vous prendrez beaucoup de villes à ceux qui en auront beaucoup, et moins à ceux qui en auront moins; chaque tribu donnera des villes aux lévites, selon l’étendue de son propre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Et le Seigneur parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Parle aux fils d’Israël, et dis-leur: Vous traverserez le Jourdain pour entrer en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Et vous séparerez de vos villes des villes d’asile, où pourra se réfugier quiconque aura involontairement frappé à mort une autre âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Et dans ces villes, le meurtrier trouvera un asile contre le vengeur du sang, et il ne sera pas mis à mort avant d’avoir été jugé par la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Et les six villes que vous donnerez, seront pour vous des asiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Il y aura trois de ces villes sur la rive gauche du Jourdain, et trois en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'L’asile sera pour les fils d’Israël, ainsi que pour le prosélyte et pour l’étranger établi parmi vous; ces villes seront des asiles où pourra se réfugier quiconque aura involontairement frappé à mort une autre âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Si quelqu’un a frappé avec un instrument de fer, et si l’homme est mort, il y a meurtre; que le meurtrier meure de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Si quelqu’un a frappé en lançant une pierre assez grosse pour faire mourir, et si l’homme est mort, il y a meurtre; que le meurtrier meure de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Si quelqu’un a frappé en lançant un objet en bois capable de faire mourir, et si l’homme est mort, il y a meurtre; que le meurtrier meure de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Le vengeur du sang lui-même tuera le meurtrier; partout où il le rencontrera, il le tuera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Si un homme, excité par son inimitié contre un autre, se place en embuscade et lui lance n’importe quel objet, et si celui-ci meurt,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Ou s’il l’a frappé de la main dans sa colère, si celui-ci meurt, que celui qui a frappé meure de mort, il y a meurtre; que le meurtrier meure de mort; le vengeur du sang tuera le meurtrier lorsqu’il le rencontrera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mais si, soudain, sans y être porté par quelque inimitié, sans qu’il y ait eu embuscade, un homme lance contre un autre un instrument quelconque,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Ou une pierre assez grosse pour faire mourir; s’il l’atteint, et si celui-ci meurt, sans que l’autre ait jamais été son ennemi, ou ait cherché à lui faire du mal,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'La synagogue jugera entre le meurtrier et le vengeur du sang, selon la règle de ces sortes de jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Si la synagogue décharge le meurtrier contre le vengeur du sang, il sera reconduit en la ville d’asile où il aura trouvé refuge, et il y demeurera jusqu’à la mort du grand prêtre qui a reçu l’onction sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Si le meurtrier sort de la ville où il se sera réfugié,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'Et que le vengeur du sang le rencontre hors de sa ville de refuge, et vienne à tuer le meurtrier, il n’est pas coupable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Que le meurtrier demeure donc dans la ville de refuge jusqu’à la mort du grand prêtre; après la mort du grand prêtre, il retournera dans la ville où est son patrimoine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Telle est la loi selon laquelle vous jugerez, en toutes vos générations, partout où vous habiterez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Tu mettras à mort quiconque aura tué un homme, après avoir entendu des témoins; un seul témoin ne suffira pas pour faire condamner à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Vous ne recevrez point de rançon de l’homme reconnu coupable d’avoir tué; il doit mourir de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Vous ne recevrez point de rançon de celui qui se sera réfugié dans une ville d’asile, pour qu’il puisse retourner en sa demeure avant la mort du grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Vous ne souillerez point de sang la terre que vous allez habiter, car le sang souille la terre, et la terre ne sera jamais apaisée au sujet du sang qui aura été versé sur elle, si ce n’est par le sang du meurtrier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Et vous ne souillerez point la terre que vous allez habiter, et où j’habiterai au milieu de vous; car je suis le Seigneur qui demeure au milieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Et les chefs de famille des fils de Galaad, fils de Machir, fils de Manassé, de la tribu des fils de Joseph, s’approchèrent, et parlèrent à Moïse, ainsi qu’à Eléazar le prêtre, et aux chefs des familles paternelles du peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Disant Le Seigneur a permis à notre maître de distribuer par le sort l’héritage des fils d’Israël, le Seigneur a prescrit au maître de donner la part de notre frère Salphaad à ses filles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Et celles-ci se marieront dans les tribus d’Israël, et leur héritage sera distrait du patrimoine de nos pères pour être ajouté au patrimoine de la tribu où elles se seront mariées; et il sera séparé de leur patrimoine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Or, quand viendra le jubilé des fils d’Israël, leur héritage sera ajouté à l’héritage de la tribu où elles se seront mariées, et leur héritage demeurera séparé de nos héritages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Et Moïse prit la décision du Seigneur, et il donna cet ordre aux fils d’Israël, disant: La tribu des fils de Joseph a dit ce que vous savez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Voici ce qu’a prononcé le Seigneur au sujet des filles de Salphaad: Qu’elles épousent ceux qui leur sont agréables; mais qu’elles se marient à des hommes de leur famille paternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Et l’héritage des fils d’Israël ne passera point d’une tribu à une autre tribu, parce que chacun des fils d’Israël ne se mariera que dans l’héritage de la tribu de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Et toute fille qui recueillera, pour cause de parenté, un héritage parmi les tribus des fils d’Israël, ne pourra épouser qu’un homme de sa famille paternelle, afin que les fils d’Israël héritent chacun du patrimoine de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Ainsi, l’héritage des fils d’Israël ne passera pas d’une tribu à une autre tribu; mais chacun des fils d’Israël se mariera dans la tribu de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Les filles de Salphaad firent donc comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Or, les filles de Salphaad se nommaient: Thersa, Egla, Melcha, Noa et Maala, et elles épousèrent de leurs parents, issus comme elles');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'De la tribu de Manassé, fils de Joseph; et leur héritage resta dans leur tribu paternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Tels sont les préceptes, les décisions, les jugements, que le Seigneur fit connaître à Moïse, à l’occident de Moab, au bord du Jourdain, vis-à-vis Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Voici les paroles que Moïse dit à tout Israël au delà du Jourdain, dans le désert situé à l’Occident près de la mer Rouge, entre Pharan-Tophel, Lobon, Aulon et Catachryse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, '(Il y a onze journées de marche d’Horeb à Cadès-Barné, dans la montagne de Séir.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'En la quarantième année, le dixième mois, le premier jour de la lune, Moïse parla à tous les fils d’Israël, sur tout ce que le Seigneur lui avait prescrit pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Après avoir défait Séhon, roi des Amorrhéens, qui résidait en Esebon, et Og, roi de Basan, qui demeurait en Astaroth et Edraï;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Dans la contrée au delà du Jourdain, en la terre de Moab, Moïse commença d’expliquer la loi de Dieu, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Le Seigneur à Horeb vous a parlé, et il vous a dit: C’est assez demeurer en cette montagne;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Mettez-vous en marche, partez, traversez les montagnes des Amorrhéens; allez chez tous ceux qui, autour d’Araba, habitent la région du midi; entrez en la contrée maritime des Chananéens; allez sur l’Anti-Liban, jusqu’au grand fleuve, jusqu’au fleuve de l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Voyez le Seigneur vous a donné cette terre qui est devant vous, entrez-y; partagez l’héritage qu’il a promis à vos pères Abraham, Isaac et Jacob, pour eux et leur postérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'En ce temps-là, je vous ai parlé, disant: Je ne pourrai seul vous conduire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Le Seigneur votre Dieu vous a multipliés, et voilà que vous êtes aujourd’hui nombreux comme les étoiles du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Que le Seigneur Dieu de vos pères continue et vous multiplie mille fois plus encore; et qu’il vous bénisse comme il vous l’a promis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Mais comment pourrai-je seul soutenir le fardeau de vos importunités et de vos contradictions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Choisissez vous-mêmes des hommes sages, expérimentés et intelligents, pris dans vos tribus, et je les mettrai à votre tête, et ils seront vos chefs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Et vous m’avez répondu: Il est bon d’exécuter la chose que tu as dite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Et j’ai pris parmi vous des hommes expérimentés, sages, intelligents, et je les ai institués chefs de mille hommes, chefs de cinquante hommes, chefs de dix hommes, pour vous commander, et pour être vos scribes et vos juges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Et, en ce temps-là, j’ai donné mes ordres à vos juges, disant: Écoutez avec attention vos frères, et jugez équitablement, entre un homme et son frère ou son prosélyte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Pour juger tu ne feras pas acception des personnes; tu jugeras le grand comme le petit, tu ne craindras la présence d’aucun homme, car le jugement vient de Dieu; et si vous trouvez la cause difficile, apportez-la-moi, et je l’entendrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'En ce temps-là, je vous ai prescrit tous les commandements que vous exécuterez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Et nous sommes partis d’Horeb, et nous avons parcouru tout ce grand et redoutable désert; nous avons suivi la route que vous avez vue, jusqu’aux montagnes des Amorrhéens, comme nous l’avait prescrit le Seigneur notre Dieu, et nous sommes arrivés à Cadès-Barné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Et je vous ai dit: Vous voici aux montagnes des Amorrhéens, le Seigneur Dieu vous les donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Voyez le Seigneur votre Dieu vous donne la terre qui est devant vous; montez-y, partagez-la, comme le Seigneur l’a dit à vos pères; n’ayez point de crainte et point de faiblesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Alors, vous m’avez entouré et vous avez dit: Envoyons devant nous des hommes, qu’ils explorent cette terre, qu’ils reviennent nous dire la route que nous devons prendre, et les villes où nous devons entrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Ce discours me fut agréable, et je pris parmi vous douze hommes, un homme par tribu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Et ils partirent, s’engagèrent dans les montagnes, allèrent jusqu’au vallon de la Grappe, et l’explorèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Et ils prirent en leurs mains des fruits de la terre, et ils vous les rapportèrent, disant: C’est une bonne terre que le Seigneur nous donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Mais vous refusâtes d’y monter; vous n’eûtes point foi en la parole du Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Et, murmurant sous vos tentes, vous dîtes: C’est parce que le Seigneur nous hait qu’il nous a tirés de l’Égypte, pour nous livrer aux Amorrhéens et pour que nous soyons exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Où allons-nous? Vos frères vous ont perverti le cœur, disant: Nous avons vu là une nation grande et nombreuse, plus puissante que nous, et de fortes murailles s’élevant jusqu’au ciel, et des hommes fils des géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Et je vous dis: Ne vous effrayez pas; ne les craignez point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Le Seigneur votre Dieu marche à votre tête, il combattra pour vous, il fera pour vous selon tout ce qu’il a fait en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Et dans ce désert que vous avez vu, durant cette marche aux monts des Amorrhéens, le Seigneur ton Dieu t’a porté sur son sein, comme jamais homme n’a porté son enfant, en toute voie que tu as parcourue, jusqu’à ton arrivée à ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Cependant, vous n’avez point eu foi à cette parole du Seigneur votre Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Qui vous précède en ce voyage pour vous choisir chaque station, vous guidant le jour par une nuée, et lá nuit par une colonne de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Et le Seigneur, ayant ouï la rumeur de vos paroles, s’irrita, et dit avec serment!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Nul de ces hommes ne verra cette contrée que j’ai promise à leurs pères,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Hormis Caleb, fils de Jéphoné; celui-ci la verra, et je lui donnerai le champ sur lequel il a marché, pour lui et ses fils, parce qu’il s’est attaché aux choses du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Et à cause de vous, le Seigneur s’irrita contre moi, et il dit: Toi non plus, tu n’entreras pas en la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josué, fils de Nau, qui se tient auprès de toi, y entrera: fortifie-le, parce que c’est lui qui en fera le partage à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Et tous les jeunes enfants qui ne savent pas aujourd’hui discerner le bien et le mal, y entreront; c’est à ceux-là que je la donnerai, et ils se la partageront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Quant à vous, rebroussez chemin; allez dresser vos tentes dans le désert, et reprenez le chemin de la mer Rouge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Et vous me répondîtes: Nous avons péché devant le Seigneur notre Dieu, partons donc, et combattons comme le Seigneur notre Dieu nous l’a prescrit. Chacun prit donc ses armes de guerre, et vous, étant rassemblés, vous montâtes sur la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Et le Seigneur me dit: Dis-leur: Si vous ne voulez être broyés par vos ennemis, ne montez pas, ne livrez pas bataille; car je ne suis point avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Et je vous répétai ces paroles, et vous ne m’écoutâtes point, vous n’obéîtes point au Seigneur, et, passant outre avec violence, vous montâtes sur la montagne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Et l’Amorrhéen habitant ces montagnes sortit à votre rencontre, et il vous poursuivit comme font les abeilles, et ils vous taillèrent en pièces de Séir à Horma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Et vous étant ralliés, vous pleurâtes devant le Seigneur votre Dieu; mais le Seigneur n’écouta pas vos cris, et il ne fit point attention à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Puis, vous demeurâtes en Cadès-Barné bien des jours, vous savez les jours que vous y êtes restés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Et, nous étant mis en route, nous partîmes pour le désert, par le chemin de la mer Rouge, comme me l’avait dit le Seigneur, et pendant bien des jours nous contournâmes la montagne de Séir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Et le Seigneur me dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'C’est assez côtoyer cette montagne, partez donc et allez vers le septentrion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Donne au peuple mes ordres, disant: Vous passerez le long des frontières de vos frères les fils d’Esau, qui habitent en Séir, et ils auront crainte de vous, et ils vous redouteront grandement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Ne leur faites point la guerre, car de leur territoire je ne vous donne pas la longueur d’un pied, parce que j’ai donné pour héritage aux fils d’Esau la montagne de Séir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Achetez-leur des vivres à prix d’argent, et mangez; prenez-leur de l’eau à la mesure pour de l’argent, et buvez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Car, le Seigneur notre Dieu t’a béni en tous les travaux de tes mains; considère comment tu as sillonné le grand et redoutable désert. Voici quarante ans que le Seigneur est avec toi, et tu n’as manqué d’aucune chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Nous passâmes donc près de nos frères les fils d’Esau qui habitent la montagne de Séir, par le chemin d’Araba à partir d’Asion-Gaber, et en faisant un détour, nous arrivâmes sur la route du désert de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Et le Seigneur me dit: Ne soyez point hostiles aux Moabites, ne leur faites point la guerre; je ne vous ai rien donné de ce territoire, car j’ai donné Arœr aux fils de Lot pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Les Ommin l’ont habité les premiers: nation grande et nombreuse, puissante comme ceux d’Enac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Ils seront toujours réputés Raphaïm, comme ceux d’Enac, mais ils ont été nommés Ommin par les Moabites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Or, en Séir le Horrhéen habita d’abord, et les fils d’Esau le détruisirent; ils effacèrent cette nation devant eux; et à leur place ils habitèrent Séir, comme Israël a fait en la terre de son héritage, que le Seigneur lui a donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Levez-vous donc, partez et côtoyez le vallon de Zared.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Or, nous avons mis trente — huit ans à venir de Cadès-Barné au vallon de Zared, et pendant ce temps toute la génération des hommes en état de porter les armes avait péri dans le camp, comme l’avait juré le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Et la main du Seigneur était sur eux pour les faire périr au milieu du camp, jusqu’à ce qu’ils eussent succombé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Et lorsque les hommes en état de porter les armes eurent péri parmi le peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Le Seigneur me parla, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tu vas aujourd’hui côtoyer les limites de Moab du côté d’Arœr;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Vous serez près des fils d’Ammon; né leur soyez point hostiles, ne leur faites point la guerre; je ne t’ai rien donné du territoire des fils d’Ammon, car j’ai donné cette terre pour héritage aux fils de Lot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Elle sera réputée terre de Raphaïm, car les Raphaïm ont été ses premiers habitants, et les Ammonites les ont surnommés Zochommin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Nation grande et nombreuse, plus puissante que vous, comme ceux d’Enac. Le Seigneur les a détruits devant les Ammonites; ceux-ci ont pris possession de leur terre, et à leur place, ils l’ont habitée jusqu’à ces temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Ainsi avait-il fait en faveur des fils d’Esau qui habitent Séir; ceux-ci, ayant effacé devant eux le Horrhéen, ont pris possession de sa terre, et, à sa place, l’ont habitée jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Pareillement les Évéens qui demeurent en Asedoth jusqu’à Gaza, et les Cappadociens venus de la Cappadoce, les ont détruits en cette contrée et l’habitent à leur place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Levez-vous donc et partez, passez le long du torrent d’Arnon; je vous livre Séhon l’Amorrhéen, roi d’Esebon, et son territoire; commencez à posséder; engagez la guerre avec lui, aujourd’hui même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Commence à jeter la terreur et la crainte de ton nom sur la face de toutes les nations qui sont sous le ciel; que ceux qui entendront ton nom soient troublés, que devant ta face elles ressentent les douleurs de la femme qui enfante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Alors, du désert de Cédamoth, j’envoyai des anciens à Séhon, roi d’Esebon, avec des paroles pacifiques, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Je traverserai ton territoire; je suivrai la route sans m’écarter ni à droite ni à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Donne-moi à prix d’argent des vivres, et je mangerai; donne-moi pour de l’argent de l’eau, et je boirai; je passerai seulement à pied;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Comme me l’ont permis les fils d’Esau qui résident en Séir, et les Moabites qui demeurent en Arœr, afin que j’atteigne le Jourdain pour entrer en la terre que notre Dieu nous a donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Et Séhon, roi d’Esebon, ne nous permit pas de passer sur son territoire; car le Seigneur avait obscurci son esprit et endurci son cœur, afin qu’il tombât entre tes mains, comme il advint en ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Et le Seigneur me dit: Voilà que je commence par te livrer Séhon, roi d’Esebon, et son territoire; commence toi aussi par prendre possession de sa contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Et Séhon, roi d’Esebon, sortit à notre rencontre, avec tout son peuple, pour nous combattre en Jassa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Et le Seigneur nous le livra: nous battîmes lui, ses fils, tout son peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Et nous nous rendîmes maîtres de ses villes en ce temps-là; nous détruisîmes toutes les villes, nous exterminâmes femmes et enfants, nous n’en laissâmes personne en vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Nous ne prîmes que le bétail et la dépouille des villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Depuis Arœr qui est sur les bords du torrent d’Arnon, et la ville bâtie dans la gorge même, jusqu’aux montagnes de Galaad, il n’y eut point de ville qui nous échappât; le Seigneur notre Dieu nous les livra toutes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Mais nous ne nous approchâmes, ni des fils d’Ammon, ni de ce qui borde le torrent de Jaboc, ni des villes de la région montagneuse, selon ce que le Seigneur Dieu nous avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Et nous nous remîmes en marche, en suivant la route de Basan, et Og, roi de Basan, sortit à notre rencontre avec son peuple pour nous combattre en Edraï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Et le Seigneur me dit: Ne le crains pas, je l’ai livré à tes mains avec tout son peuple et son territoire; traitele comme tu as traité Séhon, roi des Amorrhéens, qui résidait en Esebon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Et le Seigneur notre Dieu nous le livra, lui et tout son peuple; nous le battîmes si complètement, que rien ne reste de sa race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'En ce temps-là, nous nous rendîmes maîtres de toutes ses villes; il n’y en eut pas une que nous ne prîmes: les soixante villes et tout le territoire d’Argob, possession du roi Og de Basan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Toutes villes fortes, avec de hautes murailles, des portes et des barrières, nous les détruisîmes, outre les villes des Phérézéens, qui étaient très-nombreuses,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Comme nous avions détruit celles de Séhon, roi d’Esebon; nous détruisîmes tour à tour chaque ville, nous exterminâmes femmes et enfants,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Ainsi que tout le bétail. Et nous prîmes pour notre butin toute la dépouille des villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'En ce temps nous devînmes maîtres, à la place des deux rois amorrhéens, de toute la rive gauche du Jourdain, depuis le torrent d’Arnon jusqu’à Hermon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Les Phéniciens nomment Hermon Sanior, et les Amorrhéens Sanir.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Nous prîmes toutes les villes de Misor avec tout Galaad, et tout Basan, jusqu’à Esga et Edraï, villes du royaume de Og en Basan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Og, roi de Basan, était seul resté de la race de Raphaïm son lit était de fer; on le voit dans la citadelle des fils d’Ammon; il a de long neuf coudées d’homme adulte sur quatre de large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Et nous héritâmes de cette terre en ce temps-là, à partir d’Arœr, qui est sur le bord du torrent d’Arnon: j’ai donné à Ruben et à Gad la moitié de la montagne de Galaad et ses villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'J’ai donné à la demi-tribu de Manassé le reste de Galaad, et tout Basan, royaume de Og, et tout le territoire d’Argob, toute cette partie de Basan; cette terre est réputée terre de Raphaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaïr, fils de Manassé, a pris tous les alentours d’Argob jusqu’aux confins de Gessari et de Machathi, et il leur a donné, d’après son nom, le nom de ThanothJaïr, que porte aujourd’hui le royaume de Basan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Et j’ai donné Galaad à Machir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'À Ruben et à Gad, j’ai donné le territoire au-dessous de Galaad, jusqu’au torrent d’Arnon; ils ont pour limite, de ce côté, le milieu du torrent, et ils s’étendent jusqu’ Jaboc; le torrent les sépare des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Ils ont en outre Araba; et la limite qui les sépare de Machénéreth est le Jourdain, jusqu’à la mer d’Araba ou mer Salée, sous Asedoth ou Phasga, du côté de l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Or, en ce temps, je vous dis: Le Seigneur notre Dieu vous a donné cette terre en partage; mais que vos hommes forts prennent les armes, qu’ils marchent à l’avant-garde de vos frères, fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Que vos femmes, vos enfants et votre bétail, que je sais être très — nombreux, demeurent seuls dans les villes que je vous ai données.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Jusqu’à ce que le Seigneur notre Dieu ait établi et fixé vos frères comme vous, et qu’ils se soient pareillement partagé le territoire que le Seigneur notre Dieu leur donne au delà du Jourdain; alors vous reviendrez chacun dans l’héritage que je vous ai distribué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Et en ce temps-là, je dis à Josué: Le peuple a vu dé ses yeux comment le Seigneur notre Dieu a traité ces deux rois; c’est ainsi que le Seigneur notre Dieu traitera tous les royaumes contre lesquels tu marcheras de l’autre côté du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'N’aie d’eux aucune crainte, parce que le Seigneur notre Dieu combattra pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Et, en ce temps-là, je fis au Seigneur cette prière:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Seigneur Dieu, vous avez commencé à montrer à votre serviteur, votre force, votre puissance, votre main robuste et votre bras très-haut; car quel dieu y a-t-il dans le ciel et sur la terre pour faire ce que vous avez fait, et avec autant de vigueur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Je passerai donc le fleuve, et je verrai cette bonne terre au delà du Jourdain, cette montagne fertile et l’Anti-Liban?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mais le Seigneur, à cause de vous, ne me regarda point, et il ne m’exauça pas; il me dit: C’est assez, ne continue pas un tel discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Monte sur la cime du roc, lève les yeux à l’occident, au nord, au midi et à l’orient, vois de tes yeux, mais tu ne passeras pas le Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Donne mes ordres à Josué; fortifie-le, et encourage-le; car c’est lui qui traversera le fleuve devant le peuple; c’est lui qui leur partagera la terre que tu auras vue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Et nous campâmes dans la vallée près du temple de Phégor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Maintenant donc, ô Israël, écoutez les saintes lois et les préceptes que je vous enseigne aujourd’hui à pratiquer, afin que vous viviez et multipliiez; et qu’entrés en la terre que le Seigneur Dieu vous donne, vous la partagiez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Vous n’ajouterez rien aux choses que je vous prescris, vous n’en retrancherez rien; vous observerez les commandements du Seigneur votre Dieu que je vous intime aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vos yeux ont vu tout ce que le Seigneur votre Dieu a fait au sujet de Belphegor: le Seigneur votre Dieu a effacé de son peuple tout homme qui a marché dans les voies de Belphégor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Et vous, les fidèles au Seigneur votre Dieu, tous vous vivez encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Je vous ai fait connaître la loi et les jugements comme me les a dictés le Seigneur, pour que vous les mettiez en pratique dans la terre où vous allez entrer et que vous vous partagerez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Observez-les, exécutez-les; c’est là votre sagesse et votre intelligence aux yeux des nations qui entendront parler de toute cette loi, et elles diront: Voilà un peuple sage et intelligent, voilà un grand peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Existe-t-il une autre grande nation dont Dieu s’approche comme le fait de vous le Seigneur notre Dieu, en toutes les circonstances où nous l’invoquons?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Existe-t-il une grande nation qui ait en elle des jugements et des ordonnances pleines de justice, comme toute cette loi que j’annonce devant vous aujourd’hui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Garde-toi toi-même, et veille attentivement sur ton âme; n’oublie rien des choses que tes yeux ont vues; qu’elles ne sortent de ton cœur aucun des jours de ta vie; et tu raconteras à tes fils, aux fils de tes fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Cette journée, où en Horeb vous étiez devant le Seigneur votre Dieu, ce jour de l’Église, où le Seigneur m’avait dit: Rassemble devant moi le peuple; qu’ils écoutent mes paroles, afin qu’ils apprennent à me craindre tous les jours de leur vie sur la terre, et qu’ils instruisent leurs fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Et vous vous teniez au pied de la montagne, et la montagne était enflammée jusqu’au ciel, et il y avait alentour obscurité, ténèbres, tempête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Et le Seigneur vous parlait du milieu du feu; il vous faisait entendre les commandements que vous recueilliez en vous-mêmes, et vous ne voyiez point sa face, mais vous entendiez sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Et il vous instruisit de son alliance qui vous obligeait à suivre les dix commandements, et il les grava sur deux tables de pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'En ce temps-là, le Seigneur me prescrivit de vous enseigner la loi de justice et les jugements, pour que vous les mettiez en pratique sur la terré où vous allez entrer, et que vous allez vous partager.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Et vous veillerez attentivement sur vos âmes, car vous n’avez point vu d’image le jour où le Seigneur, en Horeb, vous parla du haut de la montagne, au milieu du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Vous ne transgresserez point la loi, et vous ne vous ferez point d’image, point de représentation de mâle ou de femelle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Point d’image des bêtes qui existent sur la terre, point d’image des oiseaux qui volent sous le ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Point d’image des reptiles qui se traînent sur la terre, point d’image des poissons qui vivent dans les eaux au-dessous de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Et qu’en regardant le ciel, en voyant le soleil, la lune, les étoiles et toute la parure des cieux, tu ne t’égares point jusqu’à les adorer et à sacrifier à des choses que le Seigneur ton Dieu a distribuées à toutes les nations sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Et le Seigneur vous a choisis, il vous a tirés de la terre d’Égypte, de la fournaise de fer d’Égypte, afin que vous soyez pour lui son peuple, son héritage, comme vous l’êtes aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Et le Seigneur, à cause des paroles que vous aviez dites, s’est irrité contre moi, et il a juré que je ne traverserais pas le Jourdain, et que je n’entrerais pas en la terre que le Seigneur votre Dieu vous donne pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Voilà que je meurs en cette terre; je ne traverserai pas le Jourdain: c’est vous qui le passerez, et qui vous partagerez cette terre fortunée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Veillez sur vous; n’oubliez pas l’alliance que le Seigneur votre Dieu a faite pour vous, ne manquez pas à la loi; ne faites pas pour vous d’image sculptée des choses que vous a désignées le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Car le Seigneur ton Dieu est un feu qui consume, c’est un Dieu jaloux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Or, quand tu auras des fils et des fils de tes fils, quand vous aurez duré longtemps sur la terre, si vous manquez à la loi, si vous faites des images sculptées de quelque créature, si devant le Seigneur vous faites le mal au point de l’irriter,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Aujourd’hui, devant vous, je prends à témoin le ciel et la terre, que vous serez effacés de cette terre où vous allez entrer, en passant le Jourdain, pour vous la partager; vous n’y demeurerez pas longtemps, mais vous serez exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Et le Seigneur vous dispersera parmi toutes les nations, et un petit nombre des vôtres survivra parmi les gentils, chez qui le Seigneur vous conduira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Et là, vous servirez des dieux étrangers, œuvre de la main des hommes, bois ou pierre, qui ne verront, ni n’entendront, ni ne mangeront; qui n’auront point d’odorat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Et là, vous chercherez le Seigneur votre Dieu, et vous le trouverez, lorsqu’en votre affliction vous le chercherez de tout votre cœur et de toute votre âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Et tous ces discours te retrouveront à la fin des jours, et tu te convertiras au Seigneur ton Dieu, et il entendra ta voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Car le Seigneur ton Dieu est un Dieu miséricordieux; il ne t’abandonnera pas, il ne te détruira point, il n’oubliera pas l’alliance qu’avec tes pères le Seigneur ton Dieu a jurée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Interrogez les premiers jours, les jours écoulés avant vous, depuis le jour où Dieu a créé l’homme sur la terre; demandez, d’une extrémité à l’autre du ciel, s’il est jamais rien arrivé de semblable à cette grande parole de Dieu, si l’on a rien ouï de semblable;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Si jamais nation a entendu la voix du Dieu vivant, parlant du milieu du feu, comme tu l’as entendue: et tu vis encore;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Si Dieu, se mêlant à une nation, a entrepris, pour la posséder en propre, de la prendre au milieu des peuples par des épreuves, par des signes et des prodiges, des combats, une main puissante, et un bras très-haut, et de grandes merveilles, comme toutes celles que le Seigneur notre Dieu a faites en Égypte sous tes yeux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Afin que tu saches que le Seigneur ton Dieu est Dieu, et que nul ne l’est que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Du haut du ciel sa voix s’est fait entendre pour t’instruire, et, sur la terre, il t’a montré son grand feu, et, du milieu du feu, tu as ouï sa parole,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Parce qu’il a aimé tes pères, et qu’il t’a choisi, toi, leur postérité, et que lui-même t’a fait sortir d’Égypte par sa grande puissance;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Pour exterminer devant ta face des nations grandes et plus fortes que toi, pour t’introduire en leur terre, et te la donner en héritage, comme tu l’as aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Sache donc, et répète toujours en ta pensée, que le Seigneur ton Dieu est Dieu, au haut du ciel et ici-bas sur la terre, et que nul n’est Dieu que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Observe sa loi et ses commandements que je t’intime aujourd’hui, afin que tu sois heureux, et tes fils après toi, afin que tu vives de longs jours sur la terre que le Seigneur ton Dieu te donne à perpétuité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Après cela, Moïse sépara, sur la rive droite du Jourdain, trois villes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Où pût se réfugier le meurtrier qui, involontairement et sans précédente haine, aurait tué son prochain, afin qu’à l’une de ces villes il pût trouver refuge, et vivre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bosor, dans le désert, en la plaine de Ruben; Ramoth en Galaad, appartenant à Gad; et Gaulon en Basan, appartenant à Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Voici la loi que Moïse exposa devant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Voici les témoignages, les préceptes et les jugements que Moïse fit connaître aux fils d’Israël après leur sortie d’Égypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Sur la rive du Jourdain, dans la vallée voisine du temple de Phégor, en la terre du roi des Amorrhéens, Séhon, qui habitait Esebon, et que vainquirent Moïse et les fils d’Israël, après leur sortie d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Alors, ils partagèrent sa terre et la terre de Og, roi de Basan; tous les deux étaient des rois amorrhéens; ils régnaient sur la rive orientale du Jourdain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Depuis Arœr, sur le bord du torrent d’Arnon, jusqu’à la montagne d’Hermon, dans le royaume de Séhon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'C’est-à-dire sur tout le territoire d’Araba, sur la rive orientale du Jourdain, au-dessous du rocher d’Asedoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Et Moïse convoqua tout Israël, et il dit: Écoute, Israël, les jugements et les ordonnances que je vais te faire entendre aujourd’hui: retiens-les, et veille à les mettre en pratique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Le Seigneur votre Dieu a fait alliance avec vous en Horeb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ce n’est point avec vos pères que le Seigneur a fait cette alliance, mais avec vous, vous tous assemblés ici, vivant encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Le Seigneur vous a parlé face à face en la montagne, au milieu du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Et moi, en ce temps-là, je me tenais entre le Seigneur et vous, pour vous rapporter les paroles du Seigneur; car vous étiez épouvantés à l’aspect du feu, et vous ne montiez point sur la montagne; et le Seigneur a dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Je suis le Seigneur ton Dieu qui t’ai fait sortir de la terre d’Égypte, de la maison de servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Tu n’auras point d’autres dieux devant ma face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Tu ne te feras point d’idoles, ni d’images d’aucune chose existant dans le ciel, sur la terre, sous la terre et dans les eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Tu ne les adoreras point, tu ne les serviras point; car je suis le Seigneur ton Dieu, Dieu jaloux, vengeant sur les enfants les péchés des pères, jusqu’à la troisième ou à la quatrième génération de ceux qui me haïssent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'Et faisant miséricorde, pendant des milliers de générations, à ceux qui m’aiment et qui observent mes commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Tu ne prendras pas en vain le nom du Seigneur ton Dieu; car le Seigneur ton Dieu ne regardera point comme pur celui qui aura pris son nom en vain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Sois attentif le jour du sabbat à le sanctifier, comme te l’a prescrit le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Pendant six jours, travaille et fais tous tes ouvrages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Mais le septième jour est le sabbat du Seigneur ton Dieu; tu ne feras aucune œuvre en ce jour-là, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bœuf, ni ton âne, ni aucune de tes bêtes, ni le prosélyte demeurant avec toi; ton serviteur, ta servante, ton âne, se reposeront comme toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Souviens-toi que tu étais esclave en Égypte, et que le Seigneur Dieu t’en a fait sortir par une main puissante, par un bras très-haut; c’est pourquoi le Seigneur ton Dieu te commande d’observer le jour du sabbat et de le sanctifier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Honore ton père et ta mère, comme te l’a prescrit le Seigneur ton Dieu, afin que tu sois heureux, et que tu vives longtemps sur la terre que te donne le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Tu ne tueras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Tu ne seras pas adultère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Tu ne voleras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Tu ne porteras pas de faux témoignage contre ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Tu ne convoiteras pas la femme de ton prochain; tu ne convoiteras pas la maison de ton prochain, ni son champ, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni aucune de ses bêtes, ni rien de ce qui est à ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Telles sont les paroles que le Seigneur a dites en la montagne, devant toute votre synagogue, au milieu du feu; alentour, il y avait obscurité, ténèbres, tempête, grands éclats de tonnerre; et il n’y a rien ajouté, et il å gravé ces paroles sur deux tables de pierre, et il me les a données.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Et, pendant que vous écoutiez la voix qui sortait du feu, la montagne était enflammée; alors, vous vîntes à moi, vous tous, vous princes de vos tribus, avec vos anciens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Vous dites: Voilà que le Seigneur notre Dieu nous a montré sa gloire, et nous avons entendu sa voix du milieu du feu; nous savons aujourd’hui que le Seigneur Dieu peut parler à un homme, et celui-ci vivre encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Maintenant, prends garde que nous ne mourions; car ce grand feu va nous dévorer, si nous continuons d’écouter la voix du Seigneur notre Dieu, et nous périrons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'En effet, quelle chair aura entendu, comme nous, la voix du Dieu vivant, parlant du milieu du feu, et vivra encore?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Approche-toi donc seul, écoute tout ce que dira le Seigneur notre Dieu, et tu nous répéteras tout ce que t’aura dit le Seigneur notre Dieu, et nous le saurons, et nous obéirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Et le Seigneur ouït la rumeur de vos discours pendant que vous me parliez, et il me dit: J’ai ouï la rumeur des discours de ce peuple, j’ai entendu tout ce qu’il t’a dit; et, en tout, il a bien parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Puissent leurs cœurs ne point changer, afin qu’ils me craignent et observent mes commandements; alors, ils prospèreront, eux et leurs fils, à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Va, et dis-leur: Retournez sous vos tentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Cependant, demeure auprès de moi, et je te dirai les commandements, les jugements et les ordonnances que tu auras à leur enseigner, afin qu’ils les mettent en pratique dans la terre que je leur donne pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Soyez donc attentifs à vous conduire comme l’a prescrit le Seigneur votre Dieu; ne vous écartez ni à droite ni à gauche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'En toute voie où le Seigneur votre Dieu vous a prescrit de marcher, si vous voulez qu’il vous donne prospérité et repos; et vous vivrez de longs jours en la terre qui sera votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Voici les commandements, les jugements et les ordonnances que le Seigneur notre Dieu a prescrit de vous enseigner, pour que vous les mettiez en pratique dans la terre où vous allez entrer, et qui sera votre héritage;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Pour que vous craigniez le Seigneur votre Dieu, et que vous observiez tous ses commandements et ses jugements que je vous intime aujourd’hui, vous et vos fils, et les fils de vos fils, tous les jours de votre vie, afin que vous viviez de longs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Écoute, Israël, veille à les observer, afin que tu prospères et que tu multiplies grandement, comme l’a promis le Seigneur Dieu de tes pères, qui te donne une terre où coulent le lait et le miel: voici les jugements et les ordonnances que le Seigneur a prescrits aux fils d’Israël dans le désert, après leur sortie de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Écoute, Israël: le Seigneur notre Dieu est le seul Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Tu aimeras le Seigneur ton Dieu de tout ton esprit, de toute ton âme, de toute ta force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Et les commandements que je t’intime aujourd’hui demeureront dans ton cœur et en ton âme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Tu les enseigneras à tes enfants, tu les répéteras devant eux, assis en ta maison, marchant sur les chemins, te mettant au lit, et te levant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Tu les attacheras comme un signe à ta main; ils resteront fixés devant tes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Tu les écriras sur le seuil de tes maisons, sur les montants de tes portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Et lorsque le Seigneur ton Dieu t’aura introduit en la terre qu’il a promise à tes pères Abraham, Isaac et Jacob, pour te donner des villes grandes et belles, que tu n’as pas bâties,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Des maisons pleines de tous biens, que tu n’as pas remplies; des citernes revêtues de pierres, que tu n’as point taillées; des vignes et des oliviers, que tu n’as point plantés; lorsque tu auras mangé et que tu te seras rassasié,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Sois attentif à ne point oublier le Seigneur ton Dieu, qui t’a fait sortir de la terre d’Égypte, de la maison de servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Tu craindras le Seigneur ton Dieu, tu ne serviras que lui, tu t’attacheras à lui, tu jureras par son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ne marche point à la suite d’autres dieux, des dieux des nations qui t’entourent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Car le Seigneur ton Dieu est jaloux de toi; crains que le Seigneur ton Dieu, irrité contre toi, ne t’extermine sur la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Tu ne tenteras point le Seigneur ton Dieu, comme vous l’avez fait le jour de la tentation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Tu observeras les commandements du Seigneur ton Dieu, les témoignages et les ordonnances qu’il t’a fait connaître;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Tu feras ce qui est agréable et bon aux yeux du Seigneur ton Dieu, afin que tu prospères, que tu entres en la terre fortunée que le Seigneur a promise à tes pères, et qu’elle soit ton héritage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Après que tu auras chassé devant toi tous tes ennemis, comme l’a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Et lorsque à l’avenir ton fils te questionnera, disant: Quels sont les témoignages, les ordonnances et les jugements que le Seigneur notre Dieu nous a prescrits?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Tu répondras à ton fils: Nous étions esclaves du Pharaon en la terre d’Égypte, et le Seigneur nous a fait sortir de cette contrée par une main puissante et un bras très-haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Le Seigneur a fait devant nous des signes, des prodiges éclatants, et mauvais pour l’Égypte, le Pharaon et sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Et il nous a fait sortir de cette terre, pour nous donner celle qu’il avait promise à nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Et le Seigneur nous a prescrit de suivre tous ces préceptes, de craindre le Seigneur notre Dieu, afin que tous les jours nous soient prospères, et que nous vivions comme aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Et sa miséricorde sera avec nous, si nous sommes attentifs à observer ces commandements devant le Seigneur notre Dieu, comme il nous l’a prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Lorsque le Seigneur t’aura introduit en la terre où tu vas, pour qu’elle soit ton héritage, et que devant tes yeux il aura fait disparaître de grandes nations: l’Hettéen, le Gergéséen, l’Amorrhéen, le Chananéen, le Phérézéen, l’Évéen et le Jébuséen, sept nations nombreuses et plus fortes que toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Et que le Seigneur ton Dieu te les aura livrées, et que tu les auras vaincues, tu les effaceras entièrement, tu ne feras pas d’alliance avec elles, tu seras pour elles sans pitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Vous ne ferez point de mariages avec elles; tu ne donneras point à son fils ta fille, et tu ne prendras point sa fille pour ton fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Car sa fille détournerait ton fils de moi, et il servirait d’autres dieux, et le Seigneur se courroucerait contre son peuple, et il t’exterminerait tout à coup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Voici comme vous les traiterez: vous enlèverez leurs autels, vous briserez leurs colonnes, vous arracherez leurs bois sacrés, vous consumerez par la flamme les images sculptées de leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Car tu es un peuple saint, le peuple du Seigneur ton Dieu, et le Seigneur ton Dieu t’a choisi pour que tu sois son propre peuple, séparé de toutes les nations qui existent sur la surface de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Le Seigneur ne vous a point préférés, il ne vous a pas choisis parce que vous êtes plus nombreux qu’aucune de ces nations; car vous êtes moindres en nombre que chacun de ces peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Mais il vous aime et il tient le serment qu’il a fait à vos pères. Voilà pourquoi le Seigneur vous a guidés d’une main puissante; il t’a fait sortir de la maison de servitude, il t’a délivré de la maison du Pharaon, roi d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Tu sauras que le Seigneur ton Dieu, le seul Dieu, est un Dieu fidèle, réservant son alliance et sa miséricorde à ceux qui l’aiment et à ceux qui observent ses commandements, pendant des milliers de générations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Mais se vengeant dès le début de ceux qui le haïssent; ceux-là, il les extermine; il ne met point de retard avec ceux qui le haïssent, il en tirera une vengeance soudaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Tu observeras les commandements, les jugements et les ordonnances que je t’intime aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Aussi longtemps que tu obéiras à ces préceptes, que tu t’appliqueras à les mettre en pratique, le Seigneur ton Dieu te conservera l’alliance et la miséricorde qu’il a promises à tes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Et il t’aimera, et il te bénira; il te multipliera, il bénira les fruits de tes entrailles, et les produits de ta terre ton blé, ton vin, ton huile, tes grands et menus troupeaux sur la terre que le Seigneur a juré à tes pères de te donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Tu seras béni au-dessus de toutes les nations; il n’y aura point parmi vous d’hommes sans enfants, ni de femme stérile; il n’y aura point non plus de stérilité parmi les troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Et le Seigneur ton Dieu te préservera de toute maladie, et de ces mauvaises contagions de l’Égypte que tu as vues; il ne fera tomber sur toi aucune de celles que tu y as connues, et il en frappera ceux qui te haïssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Et tu mangeras ce que tu auras enlevé à ces nations; le Seigneur te le donne; ton œil ne les prendra pas en pitié, et tu ne serviras point leurs dieux, car ce serait pour toi un achoppement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Et si, en ta pensée, tu dis: Telle de ces nations est plus forte que moi, comment pourrai-je l’exterminer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Rassure-toi; rappelle à ton souvenir tout ce qu’a fait le Seigneur ton Dieu au Pharaon et aux Égyptiens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Les grandes épreuves que tes yeux ont vues, les signes et les grands prodiges, la main puissante et le bras très-haut; de même que le Seigneur ton Dieu t’a délivré, de même il te fera triompher de toutes les nations dont tu redoutes la face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Le Seigneur ton Dieu enverra contre elles des essaims de guêpes, jusqu’à ce qu’ils aient détruit celles qui t’auraient échappé et se seraient cachées devant toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Tu ne seras pas blessé en face d’elles parce que le Seigneur ton Dieu est avec toi: Dieu grand et puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Le Seigneur ton Dieu les détruira peu à peu devant toi; tu ne pourras les exterminer soudain, de peur que la contrée ne devienne un désert, et que les bêtes farouches ne se multiplient contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Le Seigneur ton Dieu te les livrera; tu les détruiras lentement jusqu’à ce qu’enfin tu les aies exterminées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Et il te livrera leurs rois, et tu effaceras leur nom de ce pays; nul ne te résistera face à face, jusqu’à ce que tu les aies exterminées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Tu consumeras par la flamme les images sculptées de leurs dieux; tu ne convoiteras ni l’or ni l’argent qui les ornent; tu ne le prendras pas pour toi, de peur que tu n’en sois puni; car c’est une abomination pour le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Tu n’emporteras point d’abominations en ta demeure, car tu serais anathème comme elles; tu les détesteras, tu les auras en abomination: elles sont anathèmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Vous serez attentifs à mettre en pratique tous les commandements que je vous intime aujourd’hui, afin que vous viviez, que vous multipliiez, que vous entriez en la terre promise à vos pères par le Seigneur votre Dieu, et qu’elle soit votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Tu n’oublieras point tout le chemin par lequel le Seigneur t’a conduit dans le désert, afin de t’affliger, de t’éprouver et de faire en sorte que ce qui est dans ton cœur soit connu, et que l’on sache si tu observeras ou non ses commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Il t’a affligé, il t’a affamé et il t’a nourri de la manne, que n’avaient point connue tes pères, afin de t’apprendre que l’homme ne vit pas seulement de pain, mais que l’homme vivra de toute parole sortie de la bouche de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Les vêtements que tu portais n’ont point vieilli; tes sandales, sous tes pieds, ne se sont point usées; tes pieds ne sont point devenus calleux; voilà quarante ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Connais donc en ton cœur que comme un homme instruit son fils, ainsi t’instruit le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Tu observeras les commandements du Seigneur ton Dieu, pour marcher en toutes ses voies et avoir crainte de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Car le Seigneur ton Dieu va t’introduire en cette terre fertile et fortunée, où des torrents d’eau et des fontaines, jaillissant des abîmes, coulent dans la plaine et sur le flanc des montagnes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Terre de froment, de vignes, de figuiers et de grenadiers; terre d’huile d’olive et de miel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Terre où ce n’est pas en compagnie de la pauvreté que tu mangeras ton pain, où tu ne manqueras d’aucune chose; terre dont les pierres sont de fer, et dont les montagnes te fourniront de l’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Et tu mangeras et tu seras rassasié, et tu béniras le Seigneur ton Dieu sur la terre fortunée qu’il t’a donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Applique-toi en toi-même à te souvenir du Seigneur ton Dieu, à observer, sans en rien omettre, ses commandements, ses jugements et ses ordonnances que je t’intime aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Garde-toi, quand tu auras mangé et que tu te seras rassasié, et que tu te seras bâti de belles maisons et que tu les habiteras,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Et que tes bœufs et tes menus troupeaux se seront multipliés, et que ton or et ton argent se seront multipliés, et que, pour toi, toutes les choses qui t’appartiennent se seront multipliées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'D’enorgueillir ton cœur, et d’oublier ton Dieu qui t’a fait sortir de la terre d’Égypte, de la maison de servitude;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Qui t’a guidé à travers ce désert, grand et redoutable, où tu as trouvé le serpent qui mord, et le scorpion, et la soif, et point d’eau; le Dieu qui, pour toi, a fait jaillir des fontaines du flanc de rochers à pic;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Qui, dans le désert, t’a nourri de la manne que tu ne connaissais pas, et que n’avaient point connue tes pères, afin de t’affliger, de t’éprouver, puis de te combler de bienfaits jusqu’à tes derniers jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Ne va donc pas dire en ton cœur: La vigueur de mon bras m’a donné cette grande puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Mais souviens-toi du Seigneur ton Dieu; car c’est lui qui te donne la force d’acquérir cette puissance, pour établir l’alliance que le Seigneur a jurée jadis avec tes pères, comme avec toi aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Or, si tu perds le souvenir du Seigneur ton Dieu, si tu marches à la suite de dieux étrangers, si tu les sers, si tu les adores, je prends à témoin contre vous le ciel et la terre que vous serez détruits, abîmés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Comme les débris des nations qu’il va détruire devant votre face; vous serez détruits pareillement, pour n’avoir pas obéi à la parole du Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Écoute, Israël: tu vas traverser aujourd’hui le Jourdain, pour prendre le territoire de grandes nations beaucoup plus fortes que toi, et pour prendre de grandes villes, dont les remparts montent jusqu’au ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Pour supplanter un peuple grand et nombreux, et de haute taille, les fils d’Enac, que tu connais; car, tu sais le proverbe: Qui résistera en face aux fils d’Enac?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Et tu vas savoir que le Seigneur ton Dieu lui-même marchera à ta tête; ton Dieu est un feu consumant; c’est lui qui les exterminera, c’est lui qui les chassera loin de ta face, et il les détruira promptement, comme te l’a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Garde-toi de dire en ton cœur, tandis que le Seigneur ton Dieu dissipera ces nations devant toi: C’est à cause de ma justice que le Seigneur m’a conduit, pour me donner en héritage cette terre fortunée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Non, ce n’est pas à cause de ta justice, ce n’est pas à cause de la sainteté de ton cœur que tu vas avoir leur terre pour héritage, mais c’est à cause de l’iniquité de ces nations que le Seigneur détruira devant toi, afin d’établir l’alliance que le Seigneur a jurée avec nos pères: Abraham, Isaac et Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Tu connaîtras aujourd’hui que ce n’est point à cause de ta justice que le Seigneur ton Dieu te donne en héritage cette terre fortunée, à toi, peuple revêche que tu es.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Souviens-toi, n’oublie point combien tu as irrité le Seigneur ton Dieu dans le désert, depuis le jour où vous êtes sortis d’Égypte, jusqu’à votre arrivée au lieu où nous sommes; vous avez persévéré dans l’insoumission au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'En Horeb, vous avez-irrité le Seigneur, et il s’est courroucé contre vous, au point de vouloir vous exterminer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Comme j’étais monté sur la montagne pour prendre les tables de pierre, les tables de l’alliance que le Seigneur a faite avec vous; j’y restai quarante jours et quarante nuits, et je n’y mangeai pas de pain, et je n’y bus pas d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Et Dieu me donna les deux tables de pierre, écrites du doigt du Seigneur; toutes les paroles que le Seigneur avait dites devant vous sur la montagne, au jour de l’Église, y étaient écrites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Le Seigneur me donna donc les deux tables de pierre, les tables de l’alliance, après quarante jours et quarante nuits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Et le Seigneur me dit: Lève-toi, et descends bien vite d’ici; car ton peuple, que tu as fait sortir d’Égypte, s’est égaré. Ils se sont promptement écartés de la voie que je leur ai marquée, et ils se sont fait une image en fonte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Et le Seigneur me dit: Je te l’ai répété plus d’une fois je connais, j’ai vu ce peuple; c’est un peuple revêche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laisse-moi donc les détruire, et j’effacerai leur nom sous le ciel, et je te mettrai à la tête d’une nation grande et forte, plus nombreuse que celle-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Je partis donc; je descendis de la montagne. Or, la montagne était enflammée, et lançait du feu jusqu’au ciel, et je tenais dans mes deux mains les deux tables du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Et, quand je vis que vous aviez péché devant le Seigneur notre Dieu, que vous vous étiez fait une image en fonte, que vous vous étiez écartés de la voie où le Seigneur vous avait prescrit de marcher,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Je saisis les deux tables, je les jetai de mes deux mains, et je les brisai devant vous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Et je priai devant le Seigneur une seconde fois, quarante jours et quarante nuits comme la première, et je ne mangeai pas de pain, et je ne bus point d’eau, et je priai pour tous vos péchés, pour le mal que vous aviez fait devant le Seigneur Dieu en l’irritant ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Je suis encore effrayé du courroux, de la fureur que ressentait le Seigneur contre vous, au point de vouloir vous exterminer; or, en ce temps-là, le Seigneur m’exauça.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Mais il était courroucé contre Aaron, au point de vouloir l’exterminer; et, en ce temps-là, je priai aussi pour Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Et votre péché, le veau que vous aviez fabriqué, je le consumai dans le feu, je le pilai, après l’avoir battu et réduit en lames très-minces; je le réduisis en poudre, et je jetai cette poussière dans le torrent qui descend de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Ensuite, au lieu de l’embrasement, au lieu de la tentation, au lieu des sépulcres de la concupiscence, vous irritâtes encore le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Et lorsque le Seigneur vous fit sortir de Cadès-Barné, disant: Montez et prenez possession de la terre que je vous donne, vous fûtes encore indociles à la parole du Seigneur votre Dieu, vous n’eûtes point foi en lui, et vous n’obéîtes point à sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Vous avez été désobéissants envers le Seigneur, à partir du jour où il s’est fait connaître à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Et je priai devant le Seigneur quarante jours et quarante nuits, le même temps que la première fois, car le Seigneur menaçait de vous exterminer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Et je priai Dieu, et je dis: Seigneur, roi des dieux, n’exterminez pas votre peuple, votre héritage que vous avez racheté, et que vous avez fait sortir de l’Égypte par votre grande force, par votre main puissante et votre bras très-haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Souvenez-vous d’Abraham, d’Isaac et de Jacob, vos serviteurs, à qui vous avez juré par vous-même; n’attachez point vos regards sur l’endurcissement de ce peuple, sur ses impiétés, sur ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Prenez garde que les habitants de la terre d’où vous l’avez fait sortir ne disent: C’est parce qu’il n’a pu les introduire dans la terre dont il leur avait parlé, c’est aussi parce qu’il les avait en haine, que le Seigneur les a conduits dans le désert afin de les faire périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Ce peuple est votre peuple, votre héritage, vous l’avez fait sortir d’Égypte par votre grande force, votre main puissante et votre bras très-haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'En ce temps-là, le Seigneur me dit: Taille-toi deux tables de pierre semblables aux premières, et monte vers moi sur la montagne; tu feras aussi une arche de bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Et tu graveras, sur les tables, les commandements qui étaient sur celles que tu as brisées, et tu les placeras dans l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Et je fis l’arche de bois incorruptible, et je taillai les tables de pierre, semblables aux premières, et je montai sur la montagne, les deux tables dans les deux mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Et le Seigneur écrivit sur les deux tables, conformément à ce qui était écrit la première fois, les dix commandements qu’il avait prononcés devant vous sur la montagne, au milieu du feu, et le Seigneur me les donna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Et, étant parti, je descendis de la montagne, et je déposai les tables dans l’arche que j’avais faite, et elles y demeurèrent, comme me l’avait prescrit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Et les fils d’Israël levèrent leur camp de Béroth, qui était aux fils de Jacim, et ils allèrent en Misadaï; c’est là que plus tard Aaron mourut et fut enseveli, et que son fils Éléazar fut consacré prêtre à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'De là, les fils d’Israël partirent pour Gadgad, et de Gadgad pour Etebatha, terre où il y a des torrents d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'En ce temps-là, le Seigneur désigna la tribu de Lévi pour transporter l’arche du Seigneur, pour se tenir devant le Seigneur, servir et prier en son nom, comme ils l’ont fait jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'À cause de cela, les Lévites n’ont point de part ni d’héritage parmi leurs frères; le Seigneur seul est leur héritage, comme il leur a été dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Et moi, je m’étais tenu sur la montagne quarante jours et quarante nuits; et, en ce temps-là, le Seigneur m’exauça, et il ne persista pas à vous exterminer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Et le Seigneur me dit: Pars, marche à la tête de ce peuple; qu’ils entrent en la terre que j’ai juré à leurs pères de leur donner, et qu’elle soit leur héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Et maintenant, Israël, qu’est-ce que le Seigneur ton Dieu te demande, sinon de le craindre, de marcher en toutes ses voies, et de l’aimer, et de prier le Seigneur ton Dieu de tout ton cœur et de toute ton âme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'D’observer les commandements du Seigneur ton Dieu, et les préceptes de justice que je t’intime aujourd’hui, afin que tu sois heureux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'C’est au Seigneur ton Dieu que sont le ciel, et le ciel des cieux, et la terre, et tout ce qu’elle renferme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Et cependant le Seigneur a choisi vos pères pour les aimer, et après eux il vous a choisis, vous leur postérité, de préférence à toutes les nations, comme il se voit aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Ayez soin de circoncire votre dureté de cœur, gardez-vous de votre entêtement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Car le Seigneur votre Dieu, c’est le Dieu des dieux, le Seigneur des seigneurs, le Dieu grand, fort et redoutable, qui ne fait pas acception des personnes et ne se laisse point gagner par des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Il fait justice à l’étranger, à l’orphelin et à la veuve; il aime l’étranger, il lui donne des vivres et des vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Vous aimerez aussi l’étranger, car vous étiez étrangers en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Tu craindras le Seigneur ton Dieu, tu le serviras, tu t’attacheras à lui et tu jureras en son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Il est ta gloire; il est ton Dieu, lui qui a fait toutes les choses grandes et glorieuses que tes yeux ont vues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Tes pères étaient au nombre de soixante-dix âmes, lorsqu’ils arrivèrent en Égypte; et maintenant le Seigneur ton Dieu t’a fait aussi nombreux que les étoiles du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Tu aimeras le Seigneur ton Dieu, tu observeras tous les jours ses commandements, et ses ordonnances, et ses jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Vous connaissez aujourd’hui (car je ne parle pas à vos enfants, qui ne savent point et n’ont point vu) la correction du Seigneur votre Dieu, et sa grandeur, et sa main puissante, et son bras très-haut;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Ses signes, et les prodiges qu’il a faits au milieu de l’Égypte, devant le Pharaon, roi d’Égypte, aux yeux de toute la contrée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Et ce qu’il a fait de l’armée des Égyptiens, et de leurs chars, et de leurs chevaux, et de toutes leurs forces; et comme l’eau de la mer Rouge les a submergés, tandis qu’ils vous poursuivaient; et comment le Seigneur les a détruits, tellement que nul n’a reparu jusqu’à ce jour;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Et tout ce que le Seigneur a fait pour vous dans le désert, jusqu’à votre arrivée en ce lieu où nous sommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Et comme il a traité Dathan et Abiron, fils d’Eliab, fils de Ruben, que la terre, après avoir ouvert la bouche, a dévorés, au milieu des fils d’Israël, avec leurs familles et leurs tentes, et tout ce qui leur appartenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Vos yeux ont vu, en outre, toutes les grandes choses que le Seigneur vient d’accomplir pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Vous observerez donc tous les commandements que je vous intime aujourd’hui, afin que vous viviez, que vous multipliiez, et que la terre où, après avoir passé le Jourdain, vous allez entrer pour en prendre possession, soit votre héritage;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'Afin que vous viviez de longs jours sur la terre que le Seigneur a promise à vos pères et à leur postérité; terre où coulent le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Car la terre où tu entres, pour qu’elle soit ton héritage, n’est point comme la terre d’Égypte, d’où vous êtes venus jusqu’ici, et où lorsque l’on a semé les grains, on les arrose avec les pieds, comme un jardin de légumes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Cette terre où tu entres pour en prendre possession, est une terre de montagnes et de plaines; elle n’a d’autre arrosement que la pluie du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Sur cette terre, le Seigneur veille toujours; les yeux du Seigneur ton Dieu sont toujours sur elle, depuis le commencement jusqu’au dernier jour de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Or, si vous écoutez attentivement, si vous observez tous les commandements que je vous intime aujourd’hui, si vous aimez le Seigneur votre Dieu, si vous le servez de tout votre cœur, de toute votre âme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Lui, de son côté, donnera de la pluie à la terre selon la saison, soit au printemps, soit en automne, et tu récolteras ton blé, ton vin et ton huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Et il donnera dans tes champs, à ton bétail, abondance de fourrage. Et quand tu auras mangé, quand tu seras rassasié,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Sois attentif en toi-même à ce que ton cœur ne se gonfle pas, de peur que tu ne pèches, que tu ne serves des dieux étrangers, et que tu ne les adores.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Car le Seigneur, irrité contre vous, tiendrait fermé le ciel, et il n’y aurait point de pluie, et la terre ne donnerait pas ses fruits, et vous péririez rapidement par la stérilité de cette terre fortunée que le Seigneur vous a donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Mettez ces paroles au fond de vos cœurs et de vos âmes; attachez-les comme un signe à votre main; qu’elles restent fixées devant vos yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Vous les apprendrez à vos enfants, en causant avec eux, assis en vos maisons, marchant sur les chemins, vous mettant au lit, et vous levant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Vous les écrirez sur le seuil de vos maisons, sur les montants de vos portes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Afin que vous viviez longuement, et que votre postérité sur la terre que le Seigneur a promise à vos pères, en héritage, subsiste aussi longtemps que le ciel au-dessus de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Et si vous écoutez attentivement, si vous observez les commandements que je vous recommande aujourd’hui de mettre en pratique, si vous aimez le Seigneur votre Dieu, si vous marchez en toutes ses voies, si vous vous attachez à lui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Le Seigneur, de son côté, rejettera loin de vous tous les Gentils, et vous prendrez l’héritage de nations grandes, et plus fortes que vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Tout lieu où vous aurez laissé la trace de vos pieds vous appartiendra; vos limites s’étendront du désert à l’Anti-Liban; du grand fleuve de l’Euphrate à la mer occidentale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nul ne tiendra devant vous; le Seigneur répandra la terreur et la crainte de votre nom, sur toute la face de la terre où vous allez entrer, comme l’a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Voilà que je place sous vos yeux la bénédiction et la malédiction:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'La bénédiction, si vous obéissez aux commandements du Seigneur votre Dieu que je vous intime aujourd’hui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'La malédiction, si vous n’obéissez pas aux commandements du Seigneur votre Dieu que je vous intime aujourd’hui, si vous vous écartez de la voie que je vous indique, et si vous allez servir d’autres dieux que vous ne connaissez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Et lorsque le Seigneur ton Dieu t’aura introduit dans la terre où tu vas entrer, pour qu’elle soit ton héritage, tu placeras la bénédiction sur la montagne de et la malédiction sur le mont Hébal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Ne les vois-tu pas de l’autre côté du Jourdain, derrière le chemin qui mène à l’occident de la terre des Chananéens, où demeurent, au couchant, ceux de Galgala, près du grand chêne?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Vous allez, en effet, passer le Jourdain, pour entrer en la terre que le Seigneur vous donne en héritage pour toujours, et y faire votre demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Et vous veillerez à exécuter tous ces préceptes et ces jugements que je vous intime aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Voici les préceptes et les jugements que vous aurez soin d’exécuter, en la terre que le Seigneur Dieu de vos pères vous donne pour héritage, tous les jours de votre vie sur la terre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Vous bouleverserez de fond en comble tous les lieux où les Gentils sacrifiaient à leurs dieux et que vous allez posséder, soit au sommet des monts, soit sur des tertres, soit sous des arbres touffus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Et vous détruirez leurs autels, vous briserez leurs colonnes, vous abattrez leurs bois sacrés et vous consumerez par la flamme les images sculptées de leurs dieux, et leur nom sera effacé sur cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Vous ne servirez pas ainsi le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Mais vous vous dirigerez avec amour vers le lieu que vous choisira le Seigneur en l’une de vos villes, pour le consacrer sous son nom, et pour qu’il y soit invoqué; c’est là que vous irez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'C’est là que vous offrirez vos holocaustes, et vos sacrifices, et vos prémices, et vos offrandes soit d’actions de grâces, soit votives, soit volontaires, et les premiers-nés de vos bœufs et de vos menus troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'C’est là que vous mangerez devant le Seigneur votre Dieu, et que vous vous réjouirez de toutes choses que vous et vos familles aurez en la main, selon que le Seigneur votre Dieu vous aura bénis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Vous ne ferez plus, comme vous faites ici maintenant, chacun à votre gré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Car jusqu’à ce jour vous n’étiez point arrivés au lieu de repos, dans l’héritage que le Seigneur vous donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Et vous traverserez le Jourdain, et vous demeurerez en la terre que le Seigneur vous donne en héritage; il vous défendra contre tous les ennemis dont vous serez entourés, et vous y demeurerez dans une entière assurance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Et il y aura là le lieu que le Seigneur choisira pour que son nom y soit invoqué; c’est là que vous porterez tout ce que je vous prescris: vos holocaustes, vos sacrifices,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Et vous vous réjouirez devant le Seigneur votre Dieu, vous et vos fils, et vos filles, et vos serviteurs, et vos servantes, avec le lévite qui demeure dans vos villes, car il n’a ni lot ni part d’héritage au milieu de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Sois attentif à ne point sacrifier d’holocauste, n’importe en quel lieu que tu aies vu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Mais seulement dans le lieu que choisira le Seigneur ton Dieu parmi l’une de vos tribus; c’est là que vous offrirez vos holocaustes, et que vous ferez les offrandes que je vous commande aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Cependant, tu pourras tuer de ton bétail, au gré de tes désirs, et manger des chairs selon que le Seigneur ton Dieu t’aura béni, en toute ville; l’impur parmi vous et le pur en mangeront dans le même lieu, comme on mange du cerf ou du daim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Mais vous ne mangerez point le sang; répandez-le par terre, comme de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Tu ne pourras consommer en tes villes la dîme de ton blé, de ton vin, de ton huile, ni les premiers-nés de tes bœufs ou de tes menus troupeaux, ni tes offrandes votives, ni celles d’actions de grâces, ni les prémices du fruit de vos travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Tu consommeras toutes ces choses devant le Seigneur ton Dieu, dans le lieu seul que le Seigneur choisira, toi et ton fils, et ta fille, et ton serviteur, et ta servante, et le prosélyte établi en vos villes. Et tu te réjouiras devant le Seigneur ton Dieu de toutes ces choses que tu posséderas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Sois attentif à ne point négliger le lévite, tant que tu vivras sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Et si le Seigneur ton Dieu dilate tes limites, comme il te l’a promis, et si tu dis: Je veux manger de la chair; si les désirs de ton âme t’excitent à manger de la chair, tu pourras en manger au gré des désirs de ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Et si le lieu choisi par le Seigneur ton Dieu pour que son nom y soit invoqué, est loin de toi, tu immoleras une part de tes bœufs et de tes menus troupeaux de la manière que je t’ai prescrite, et tu en mangeras dans tes villes, au gré des désirs de ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Tu en mangeras comme on mange du cerf ou du daim; l’impur parmi vous, et le pur en mangeront au même lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Sois très-attentif à ne point manger de sang; car le sang de la victime est la vie; la vie ne sera point mangée avec les chairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Ne mangez point le sang, répandez-le par terre, comme de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Ne le mange point, afin que tu prospères, et qu’après toi tes fils prospèrent, parce que tu auras fait ce qui est bon et agréable devant le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Mais tu prendras les choses consacrées, si tu en as, et tes offrandes votives, et tu iras au lieu choisi par le Seigneur pour que son nom y soit invoqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Tu sacrifieras tes holocaustes et tu offriras les chairs sur l’autel du Seigneur ton Dieu, et tu répandras le sang au pied de l’autel, et tu mangeras les chairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Prends garde, écoute; tu exécuteras toutes les paroles que je te mande, afin que tu prospères et que tes fils prospèrent à travers les siècles, parce que tu auras fait ce qui est bon et agréable devant le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Lorsque le Seigneur ton Dieu aura exterminé sous tes yeux les nations contre lesquelles tu marches pour partager leur terre, et que tu l’auras partagée, et que tu y demeureras,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Veille en toi-même et ne cherche point à les imiter après qu’elles auront été exterminées sous tes yeux; ne dis pas Ce que font les nations pour leurs dieux, je le ferai pareillement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Ne fais point comme elles pour ton Dieu, car elles font pour leurs dieux l’abomination du Seigneur, ce que le Seigneur exècre: elles livrent aux flammes, pour leurs dieux, leurs fils et leurs filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Veillez à mettre en pratique toutes les paroles que je vous mande aujourd’hui; tu n’y ajouteras rien, tu n’en retrancheras rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'S’il s’élève parmi vous un prophète ou un songeur ayant des songes, s’il vous annonce un signe ou un prodige,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Si le signe ou le prodige dont il aura parlé se fait, et s’il dit: Allons, servons d’autres dieux qui vous sont inconnus,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Vous n’écouterez point ce prophète ou ce songeur; car le Seigneur votre Dieu vous tente, pour savoir si vous l’aimez de tout votre cœur et de toute votre âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Vous suivrez le Seigneur votre Dieu; vous le craindrez; vous serez dociles à sa parole; vous vous attacherez à lui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Et ce prophète ou songeur mourra, parce qu’il aura parlé pour t’égarer loin du Seigneur ton Dieu qui t’a fait sortir de la terre d’Égypte, qui t’a délivré de la servitude; il aura parlé pour t’entraîner hors de la voie où le Seigneur ton Dieu t’a prescrit de marcher; vous détruirez parmi vous le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Et, si ton frère de père ou de mère, si ton fils, ta fille, ta femme qui repose sur ton sein, si l’ami que tu aimes comme ta vie, t’exhortent en secret, disant: Allons, servons d’autres dieux inconnus de tes pères et de toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Des dieux des nations qui vous entourent de près ou de loin, d’une extrémité à l’autre de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Tu n’y consentiras point, tu ne l’écouteras point; ton œil ne prendra pas en pitié sa faute; tu ne soupireras pas pour lui, tu ne le cacheras point;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Tu le feras connaître, tu le signaleras; tes mains s’élèveront les premières contre lui pour qu’il périsse; les mains du peuple viendront après.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Il sera lapidé, il mourra pour avoir cherché à te détourner du Seigneur ton Dieu qui t’a fait sortir de l’Égypte et de la maison de servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Tout Israël en l’apprenant aura crainte, et l’on évitera parmi vous de faire de nouveau un tel mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Et si, en l’une des villes que le Seigneur te donne pour que tu y demeures, tu entends dire par des gens:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Des hommes d’iniquité se sont élevés parmi nous, et ils ont égaré ceux qui habitent notre territoire, et ils ont dit: Allons, et servons des dieux qui vous sont inconnus,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Tu examineras, tu interrogeras, tu feras de nombreuses enquêtes, et s’il est manifeste que ces hommes ont ainsi parlé, et que cette abomination a eu lieu parmi vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Tu feras périr par le glaive tous ceux qui habitent cette contrée, et vous la déclarerez anathème, elle et tout ce qu’elle renferme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Et tu feras, sur le grand chemin, un monceau de toutes ses dépouilles, et tu livreras aux flammes, devant le Seigneur ton Dieu, la ville et ses dépouilles, et elle sera toujours inhabitée, et on ne la rebâtira plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Et rien de ce qui aura été frappé d’anathème ne te restera dans la main, afin que la colère du Seigneur se détourne, qu’il ait pitié de toi, qu’il te fasse miséricorde, et qu’il te multiplie, comme il l’a promis à tes pères,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Si tu es docile à la parole du Seigneur ton Dieu pour mettre en pratique les commandements que je t’intime aujourd’hui, et faire ce qui est bon et agréable devant le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Soyez les fils du Seigneur votre Dieu: Vous ne vous raserez point la chevelure au sujet d’un mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Car tu es un peuple saint pour le Seigneur ton Dieu, qui t’a choisi pour que tu sois son peuple particulier, séparé de toutes les nations qui couvrent la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Vous ne mangerez rien d’impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Voici les animaux que vous mangerez: rejetons des troupeaux de bœufs, de brebis et de chèvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Cerf, chevreuil, pycargue, gazelle, girafe,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Tout quadrupède à sabot, dont l’ongle se sépare en deux; et tout animal ruminant: vous pouvez en manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Voici les animaux que vous ne mangerez pas, soit parmi les ruminants, soit parmi ceux qui ont les pieds fourchus, ou les ongles fendus: chameau, lièvre, hérisson; s’ils ruminent, ils n’ont point le pied fourchu, ce qui pour vous les rend impurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Le porc s’il a le pied fourchu, l’ongle fendu, il ne rumine pas, ce qui pour vous le rend impur; vous ne mangerez pas de ses chairs, vous ne toucherez pas à son corps mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Vous mangerez, parmi tout ce qui vit dans l’eau, ce qui a nageoires et écailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Vous ne mangerez pas ce qui n’a ni nageoires ni écailles; c’est impur pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Vous mangerez tout oiseau pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Voici ceux que vous ne mangerez pas: aigle, griffon, aigle de mer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Vautour, milan et leurs semblables,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Corbeau et ses semblables,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Autruche, chouette et mouette,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Héron, cygne et ibis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Plongeon, épervier et leurs semblables, huppe et nycticorax,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Pélican, charadrion et leurs semblables, porphyrion et hibou;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Tous ceux des êtres ailés qui se traînent à terre sont impurs vous n’en mangerez point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Vous mangerez de tout oiseau pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Vous ne mangerez d’aucun corps mort; donnez-les à manger au prosélyte établi dans vos villes ou vendez-les, car vous êtes un peuple saint appartenant au Seigneur votre Dieu. Vous ne ferez point cuire d’agneau dans le lait de sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Tu prélèveras la dîme de tout fruit de tes semailles, de tout produit annuel de tes champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Tu la mangeras dans le lieu qu’aura choisi le Seigneur pour que son nom y soit invoqué; tu feras l’offrande des dîmes de ton blé, de ton vin, de ton huile, des premiers-nés de tes bœufs et de tes menus troupeaux, afin que tu saches craindre sans cesse le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Et si le chemin est long, si tu ne peux les transporter parce que tu résides loin du lieu choisi par le Seigneur pour que son nom y soit invoqué, et si le Seigneur t’a béni,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Tu paieras tes dîmes en argent; tu prendras l’argent dans tes mains, et tu iras au lieu que le Seigneur aura choisi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Là, tu rachèteras, à prix d’argent, toutes choses que ton âme désirera: bœufs, brebis, chèvres, ou vin et boisson fermentée; puis, tu les consommeras, devant le Seigneur ton Dieu, et tu te réjouiras, toi et ta famille,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Et le lévite de tes villes, parce qu’il n’a point, comme toi, de part ni d’héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Après trois ans, tu donneras toutes les dîmes de tes fruits; tu les déposeras en tes villes, la troisième année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Et le lévite y viendra, parce qu’il n’a point, comme toi, de part ni d’héritage; le prosélyte, l’orphelin, la veuve, viendront pareillement en tes villes, et ils mangeront de tes dîmes, et ils se rassasieront, afin que le Seigneur ton Dieu te bénisse en toutes tes œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Tous les sept ans tu feras la remise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Voici la règle de la remise: tu remettras à ton prochain toute dette qui t’est propre; tu ne réclameras rien de ton frère, car le Seigneur ton Dieu a proclamé la rémission.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Tu réclameras de l’étranger tout ce qu’il te doit; mais tu feras à ton frère remise de ta créance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Ainsi, il n’y aura pas chez toi d’indigent, parce que le Seigneur ton Dieu te bénira en la terre qu’il te donne en héritage, pour que tu la possèdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Si vous écoutez la parole du Seigneur votre Dieu, si vous lui êtes dociles, pour observer et mettre en pratique tous ces commandements que je vous intime aujourd’hui (car le Seigneur t’a béni, selon la promesse qu’il t’a faite),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Tu prêteras à intérêt à nombre de gentils; mais tu n’auras pas besoin d’emprunter; tu régneras sur les gentils, et ils ne régneront pas sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Si, dans l’une des villes en la terre que le Seigneur ton Dieu te donne, il y a avec toi parmi tes frères un indigent, tu n’endurciras pas ton cœur, tu ne fermeras pas ta main pour ton frère l’indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Tu ouvriras la main pour lui; tu lui prêteras tout ce qu’il te demandera selon ses besoins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Prends garde qu’il ne vienne en ton cœur quelque iniquité, quelque pensée secrète te disant: La septième année, l’année de la remise est proche; et qu’alors, tu ne regardes d’un mauvais œil ton frère indigent, et que tu ne lui donnes rien, car il invoquera contre toi le Seigneur notre Dieu, et il y aura en toi un grand péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Donne-lui donc, et donne-lui; prête-lui largement, autant qu’il te demandera, selon ses besoins; ne t’afflige pas en ton cœur de lui donner; car, à cause de cette action, le Seigneur ton Dieu te bénira en tous tes travaux, et en toutes choses où tu mettras la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Car il ne manquera jamais d’indigent sur la terre; c’est pourquoi je te prescris d’exécuter mes commandements ouvre tes mains à ton frère pauvre et indigent en ta terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Et si ton frère hébreu, ou ta sœur, femme israélite, te sont vendus à prix d’argent, ils te serviront six ans, et, en la septième année, tu les renverras libres de chez toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Et, en les renvoyant libres, tu ne les congédieras pas dénués de tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Tu les pourvoiras de provisions: de la chair de tes brebis, de ton blé, de ton vin; tu leur donneras selon que le Seigneur t’aura béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Et tu te souviendras que tu as été esclave en la terre d’Égypte, et que le Seigneur ton Dieu t’en a délivré; c’est pourquoi, je te prescris d’exécuter ce commandement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Et si ton serviteur te dit: Je ne sortirai point de chez toi, parce que je t’aime, toi et ta famille, et que tout prospère chez toi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Tu prendras une alène, et, devant la porte, tu lui perceras l’oreille, et il sera ton serviteur à perpétuité; tu feras de même pour ta servante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Qu’il ne te semble point dur de les congédier libres après qu’ils t’ont servi six ans, moyennant le salaire annuel des gens à gages, et le Seigneur ton Dieu te bénira en toutes tes œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Tout premier-né mâle de tes bœufs et de tes menus troupeaux, tu le consacreras au Seigneur; tu ne travailleras pas avec le premier-né de tes génisses, tu ne tondras pas le premier-né de tes brebis ou de tes chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Tu le mangeras devant le Seigneur, d’année en année, avec ta famille, au lieu que le Seigneur ton Dieu aura choisi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Mais, s’il a quelque vice ou difformité, s’il est boiteux ou aveugle, ne le sacrifie pas au Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Tu le mangeras en tes villes; l’impur parmi vous et le pur en mangeront, comme on mange du cerf ou du daim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Seulement, vous ne mangerez point le sang, vous le répandrez par terre comme de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Observe le mois des blés nouveaux, et tu feras la pâque du Seigneur ton Dieu, parce que dans le mois des blés nouveaux, tu es sorti nuitamment de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Tu sacrifieras, pour la pâque du Seigneur ton Dieu, des bœufs, des brebis et des chèvres, au lieu seul que le Seigneur ton Dieu aura choisi afin que son nom y soit invoqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Avec la victime, tu ne mangeras pas de pain levé; pendant sept jours, avec ses chairs, tu mangeras des azymes, pain de la mortification, parce qu’à la hâte vous êtes sortis de l’Égypte, et parce qu’il faut vous souvenir du jour de votre sortie d’Égypte, tous les jours de votre vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'On ne verra pas chez toi de pain levé, en tout ton territoire, pendant sept jours; rien ne restera des chairs des victimes que tu auras sacrifiées sur le soir du premier jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Tu ne pourras sacrifier la pâque dans aucune des villes que le Seigneur ton Dieu te donne;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Mais au lieu seul que le Seigneur ton Dieu aura choisi pour que son nom y soit invoqué; tu sacrifieras la pâque sur le soir, au coucher du soleil, vers l’heure où tu es sorti de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Tu feras bouillir ou rôtir les chairs, et tu les mangeras au lieu seul qu’aura choisi le Seigneur ton Dieu, et, le lendemain matin, pars, retourne en tes demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Tu mangeras des azymes pendant six jours; le septième jour, pour finir, sera la fête du Seigneur ton Dieu; tu ne feras ce jour-là aucune œuvre, sauf toutes les choses que l’on fait à cause d’un mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Tu compteras en toi-même sept semaines, à partir du jour où ta faux commencera la moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Tu célébreras ensuite la fête des semaines du Seigneur ton Dieu, selon tes facultés, selon ce que t’aura donné le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Tu te réjouiras devant le Seigneur ton Dieu, toi et ton fils, et ta fille, et ton serviteur, et ta servante, et le lévite, et le prosélyte, et l’orphelin, et la veuve, qui se trouvent parmi vous, au lieu seul que le Seigneur aura choisi pour que son nom y soit invoqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Et tu te souviendras que tu as été esclave en la terre d’Égypte, et tu observeras et exécuteras les commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Tu célébreras la fête des tabernacles pendant sept jours, lorsque tu auras recueilli, tant sur l’aire que dans le pressoir, les fruits de tes champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Tu te réjouiras, en cette fête, toi, et ton fils, et ta fille, et ton serviteur, et ta servante, et le lévite, et le prosélyte, et l’orphelin, et la veuve, qui se trouveront dans tes villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Tu célébreras cette fête pendant sept jours en l’honneur du Seigneur ton Dieu, au lieu seul qu’aura choisi le Seigneur, et le Seigneur te bénira en toutes tes récoltes, en toutes œuvres de tes mains, et tu seras plein de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trois fois par an, tout mâle parmi vous se présentera devant le Seigneur votre Dieu, au lieu seul qu’aura choisi le Seigneur, pour la fête des azymes, pour la fête des semaines et pour la fête des tabernacles; nul ne se présentera les mains vides devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Chacun de vous offrira selon ses facultés, et selon que le Seigneur l’aura béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Tu institueras pour toi des juges et des scribes dans les villes que le Seigneur te donne par tribus; ils jugeront le peuple, et rendront des jugements équitables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Ils ne feront point pencher la justice, ils ne feront point acception des personnes, ils n’accepteront point de présents; car les présents aveuglent le sage, et ôtent aux justes leur intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Vous vous efforcerez de rendre justice selon l’équité, afin que vous viviez et que vous entriez en la terre que le Seigneur vous donne, pour qu’elle soit votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Tu ne planteras point de bois sacré; tu ne planteras aucun autre arbre auprès de l’autel de ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Tu ne t’érigeras point de colonnes; le Seigneur ton Dieu les exècre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Tu ne sacrifieras pas au Seigneur ton Dieu de bœufs, de brebis ou de chèvres qui aient quelque difformité ou quelque vice; car c’est une abomination pour le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Et s’il se trouve, en l’une des villes que le Seigneur te donne, un homme ou une femme qui fasse le mal devant le Seigneur ton Dieu, et viole son alliance');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'En servant des dieux étrangers, et en adorant le soleil ou l’un des ornements du ciel que le Seigneur t’a défendu d’adorer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'Et qu’on te l’ait déclaré et que tu aies fait avec soin une enquête, et qu’il soit manifeste que cette abomination est en Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Tu emmèneras dehors cet homme ou cette femme; vous lapiderez le coupable, il mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Il mourra sur trois témoignages, sur deux témoignages; mais un seul témoignage ne suffira pas pour qu’on le mette à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'La main des témoins lui jettera la première pierre; viendra ensuite la main du peuple vous couperez le mal par la racine au milieu de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Et lorsque dans vos villes, en un jugement, tu ne pourras prononcer entre le sang et le sang, entre une cause et une cause, entre lèpre et lèpre, entre controverse et controverse; tu te lèveras et tu monteras au lieu que le Seigneur ton Dieu aura choisi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Et tu te présenteras devant le prêtre, devant les lévites, devant le juge qu’il y aura en ces jours-là, et ils examineront et ils te déclareront le jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Tu feras selon la chose qu’ils t’auront déclarée du lieu que le Seigneur ton Dieu aura choisi, et tu veilleras à exécuter ce qu’ils t’auront donné pour loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Tu agiras en conséquence de la loi et du jugement qu’ils t’auront dits; tu ne t’écarteras ni à droite ni à gauche de la chose qu’ils t’auront déclarée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'L’homme qui par orgueil ne s’y conformera pas, et qui n’obéira pas au prêtre, exerçant alors le sacerdoce au nom du Seigneur, et au juge qu’il y aura en ces jours-là, cet homme sera mis à mort; vous déracinerez le mal en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Et tout le peuple l’ayant appris aura crainte, et il ne s’adonnera pas à l’impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Et lorsque tu seras entré en la terre que le Seigneur te donne, lorsque tu l’auras partagée, et que tu y seras établi, et que tu diras: Je mettrai un chef au-dessus de moi, comme les autres nations qui nous entourent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Tu mettras au-dessus de toi le chef que choisira le Seigneur Dieu; tu mettras pour te commander comme chef, l’un de tes frères; tu ne prendras pas pour chef un étranger, car il n’est pas ton frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Qu’il n’ait pas une nombreuse cavalerie, qu’il ne fasse point retourner le peuple en Égypte afin d’y multiplier le nombre de ses chevaux, car le Seigneur a dit; Vous ne reprendrez jamais cette voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Qu’il ne prenne pas un grand nombre de femmes, de peur que son cœur ne s’égare, et qu’il n’amasse pas beaucoup d’or et d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Qu’il écrive de sa main le présent Deutéronome, aussitôt établi au pouvoir, en un livre que lui donneront les prêtres et les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Qu’il porte ce livre partout, qu’il le lise tous les jours de sa vie, afin qu’il apprenne à craindre le Seigneur, à observer toutes ses lois, à mettre en pratique tous ses jugements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Afin que son cœur ne s’exalte point orgueilleusement au-dessus de ses frères, qu’il ne s’écarte des commandements ni à droite ni à gauche, et qu’il vive de longs jours sur le trône, lui et ses enfants, au milieu des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'La tribu entière de Lévi, prêtres et lévites, n’aura ni part ni héritage en Israël; ils vivront des oblations au Seigneur, selon leurs services.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Ils n’auront point d’héritage parmi leurs frères; le Seigneur seul est leur héritage, comme il le leur a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Et voici la loi pour les prêtres, concernant les offrandes du peuple et les sacrifices des veaux ou des brebis: tu donneras au prêtre l’épaule, les joues et la poitrine,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Et les prémices de ton blé, de ton vin, de ton huile; tu lui donneras aussi les prémices des rejetons de tes menus troupeaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Parce que le Seigneur l’a choisi, entre toutes les tribus, pour qu’il se tienne devant le Seigneur Dieu, pour qu’il exerce le sacerdoce, pour que lui et ses fils bénissent en son nom le peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Lorsque le lévite, de l’une des villes qu’il habite, partira au gré de son désir, et viendra au lieu qu’aura choisi le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Il servira, au nom du Seigneur son Dieu, comme tous ses frères les lévites qui se tiendront en ce lieu devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Il mangera la portion qui lui est assignée indépendamment de la vente de ce qui lui revient dans sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Lorsque tu seras entré en la terre que le Seigneur ton Dieu te donne, tu n’apprendras pas à imiter les abominations des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Il ne se trouvera parmi vous personne qui, pour purifier son fils ou sa fille, les fasse passer par le feu; qui use de la divination, qui prédise, qui prenne les augures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Tu ne chercheras pas à charmer par des incantations magiques, à devenir sorcier ni interprète des prodiges, à interroger les morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Car quiconque fait ces choses est une abomination pour le Seigneur ton Dieu; c’est à cause de ces abominations que le Seigneur exterminera les gentils devant ta face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Tu seras parfait devant le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Car les nations dont tu vas prendre l’héritage, écoutent les devins et ceux qui prédisent l’avenir, et tu es instruit autrement par le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Le Seigneur ton Dieu suscitera parmi tes frères UN PROPHÈTE semblable à moi; c’est lui que vous écouterez,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Parce que, en Horeb, tu en as fait la demande au Seigneur ton Dieu, le jour de l’Église; tu as dit: Que nous ne continuions plus d’entendre la voix du Seigneur notre Dieu, que nous ne voyions plus ce grand feu, de peur que nous ne mourions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Et le Seigneur m’a dit: Ils ont bien parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Je susciterai pour eux, parmi leurs frères, un prophète semblable à toi; et je mettrai mes paroles dans sa bouche, et il leur parlera selon ce que je lui prescrirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Et je tirerai vengeance de tout homme qui n’écoutera pas ce que ce prophète lui aura dit en mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Tout autre prophète qui sera assez impie pour dire en mon nom une parole que je ne lui aurai point commandé de dire, ou qui parlera au nom d’autres dieux, ce prophète sera mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Et si tu dis en ton cœur: Comment discernerons-nous la parole que le Seigneur n’aura pas dite?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Tout ce qu’aura dit ce prophète au nom du Seigneur et qui n’arrivera pas, qui ne se réalisera pas, n’aura point été dit par le Seigneur. Ce prophète aura parlé dans son impiété vous ne le recevrez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Lorsque le Seigneur votre Dieu aura effacé les nations dont il vous donne le territoire, et que vous aurez recueilli leur héritage, vous demeurerez en leurs villes et en leurs maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Vous séparerez vous-mêmes trois villes au milieu de la terre que le Seigneur vous donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Dispose pour toi la voie, fais trois parts du territoire que le Seigneur ton Dieu te donne en héritage, et que dans chacune il y ait un refuge pour le meurtrier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Voici la loi concernant le meurtrier qui s’y sera réfugié: il vivra, s’il a commis un meurtre involontairement, sans aucune haine précédente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Celui qui sera entré après son prochain en une forêt de chênes pour y couper du bois, et dont la main, en coupant du bois, aura laissé échapper la hache, de sorte que le fer, se séparant du manche, ait atteint son prochain, et lui ait donné la mort, se réfugiera dans l’une de ces villes, et il vivra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'De peur que le vengeur du sang, le cœur enflammé, ne le poursuive et ne le surprenne, faisant une longue route, et ne le frappe à mort, quoiqu’il ne soit pas condamné à périr, puisqu’il n’avait aucune précédente haine contre le défunt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'C’est pourquoi je te donne ce commandement, et je dis: Pour toi-même, sépare trois villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Et si le Seigneur ton Dieu dilate tes limites, comme il l’a promis à tes pères, et s’il te donne toute la terre qu’il a promis à tes pères de te donner,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Si tu écoutes et si tu mets en pratique ces commandements que je t’intime aujourd’hui: d’aimer le Seigneur ton Dieu, de marcher tous les jours en toutes ses voies; tu ajouteras, de toi-même, trois villes à ces trois villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Et le sang innocent ne sera pas répandu en la terre que le Seigneur te donne pour héritage, et nul chez toi ne sera coupable de ce sang versé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mais, s’il existe chez toi un homme haïssant son prochain, s’il l’a guetté, s’il s’est levé contre lui, s’il l’a frappé à mort; si l’autre a succombé et si lui-même se réfugie dans l’une de ces villes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Les anciens de sa ville enverront après lui, et on l’y saisira, et on le livrera aux mains du vengeur du sang, et il mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Ton œil ne prendra pas en pitié cet homme, et tu purifieras Israël du sang innocent versé, et tu prospéreras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Tu ne déplaceras pas les bornes que tes pères auront posées au lot qui te sera échu en partage en la terre que le Seigneur ton Dieu te donne pour que tu la possèdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Un seul témoin ne suffira pas contre un homme au sujet de quelque iniquité, de quelque faute, de quelque péché que celui-ci aurait commis; le jugement s’appuiera sur deux ou trois témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Et si un témoin inique s’est levé contre un homme, l’accusant d’impiété,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'On amènera les deux hommes, entre lesquels il y aura contestation devant le Seigneur, et devant les prêtres, et devant les juges qu’il y aura en ces jours-là;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Les juges examineront avec soin, et s’ils voient que c’est un témoin inique qui s’est levé contre son frère pour porter de faux témoignages,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Vous lui ferez subir le châtiment qu’il aurait attiré sur son frère, et vous déracinerez le mal parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Ceux qui auraient fait de même auront crainte, et ils ne continueront plus de commettre cette mauvaise action parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Ton œil ne prendra pas en pitié un tel homme: vie pour vie, œil pour œil, dent pour dent, main pour main, pied pour pied.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Lorsque tu iras en guerre contre tes ennemis, et que tu verras des chevaux et des cavaliers et un peuple plus nombreux que toi, n’aie point de crainte; car le Seigneur ton Dieu, qui t’a fait sortir de la terre d’Égypte, est avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Au moment de combattre, le grand prêtre s’avancera et parlera au peuple, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Écoutez, enfants d’Israël: Vous allez livrer bataille à vos ennemis; conservez votre fermeté de cœur, n’ayez point de crainte, ne rompez pas les rangs, ne vous détournez pas de leur face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Car le Seigneur votre Dieu, qui marche à votre tête, combattra vos ennemis et vous sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Les scribes aussi parleront au peuple, disant: Est-il parmi vous un homme qui, ayant bâti une maison neuve, n’en ait point fait la dédicace? Qu’il parte, qu’il retourne en sa maison s’il craint de succomber en ce combat, et qu’un autre que lui ne fasse cette dédicace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Est-il un homme qui ait planté une vigne et n’en ait point joui? Qu’il parte, qu’il retourne en sa maison, s’il craint de succomber en ce combat, et qu’un autre que lui ne jouisse de sa vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Est-il un homme qui ait épousé une femme et ne l’ait pas encore possédée? Qu’il parte, qu’il retourne en sa maison, s’il craint de succomber en ce combat, et qu’un autre que lui ne possède sa femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Et les scribes continueront de parler au peuple, disant: Est-il un homme qui tremble et qui en son cœur ait crainte? Qu’il parte, et qu’il retourne en sa maison pour qu’il ne rende pas craintif, comme le sien, le cœur de son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Et, dès que les scribes auront cessé de parler, ils placeront les chefs de l’armée à la tête du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Et si vous êtes près d’une ville pour donner l’assaut ou inviter les habitants à la paix:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'S’ils vous répondent pacifiquement, s’ils vous ouvrent leurs portes, que tout ce peuple, que tous ceux par vous trouvés en cette ville, soient vos tributaires et vos sujets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'S’ils ne vous écoutent pas, s’ils prennent les armes, assiégez la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Et si le Seigneur vous la livre, faites périr par le glaive tous les mâles qu’elle renferme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Épargnez les femmes et le butin: emparez-vous de tout le bétail, de tout ce qui appartient à la ville, de toutes ses richesses, nourrissez-vous de toutes les provisions des ennemis que le Seigneur vous livre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Traitez de même les villes lointaines, étrangères aux nations que le Seigneur vous livre pour vous donner leur terre comme héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Ne prenez vivant aucun des hommes qui les habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Frappez d’anathème: Hettéen, Amorrhéen, Chananéen, Phérézéen, Évéen, Jébuséen et Gergéséen, comme vous l’a prescrit le Seigneur votre Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'De peur qu’ils ne vous apprennent à pratiquer les abominations qu’ils commettent pour leurs dieux, et que vous ne deveniez coupables envers le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Si vous avez investi une ville plusieurs jours pour la combattre jusqu’à ce qu’elle succombe, ne détruisez pas ses arbres en y mettant la cognée, mangez — en les fruits sans les abattre. L’arbre des champs est-il un homme, pour entrer devant toi dans ton retranchement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Mais tu abattras les arbres que tu sais ne pas produire de fruits, tu en feras des palissades contre la ville qui te résiste, jusqu’à ce qu’elle te soit livrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Si, en la terre que le Seigneur te donne pour héritage, on trouve le cadavre d’un homme frappé à mort dans les champs, et si l’on ignore qui a porté le coup,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Tes anciens et tes juges sortiront et mesureront à quelle distance sont les villes au milieu desquelles on aura trouvé le corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'On verra quelle est la ville la plus proche du cadavre; alors, les anciens de cette ville prendront, parmi les bœufs, une génisse, non encore soumise au joug;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Puis, ils feront descendre la génisse en un ravin inculte, et, dans ce ravin, ils trancheront les muscles du cou de la génisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Ensuite, viendront les prêtres et les lévites choisis par le Seigneur Dieu pour se tenir auprès de lui et pour bénir en son nom, car c’est à eux qu’il appartient de condamner et d’absoudre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Tous les anciens de la ville la plus proche du cadavre se laveront les mains sur la tête de la génisse immolée dans le ravin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Puis, ils diront: Nos mains n’ont pas versé ce sang, et nos yeux n’ont rien vu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Seigneur, soyez propice au peuple d’Israël que vous avez délivré; faites que le sang innocent ne tombe pas sur le peuple d’Israël; et pour eux le cri du sang innocent sera apaisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Et tu auras effacé du milieu du peuple la tache du sang innocent, si tu as fait ce qui est bon et agréable devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Si tu vas en guerre contre des ennemis, si, le Seigneur te les ayant livrés, tu t’empares de leurs richesses,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Et si tu vois parmi le butin une femme qui soit belle; si tu la désires et si tu la prends pour femme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Tu la conduiras en ta demeure, tu lui raseras la tête, tu lui couperas les ongles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Tu lui ôteras les vêtements de la captivité; elle restera en ta maison pendant un mois, elle pleurera son père et sa mère; après cela tu t’approcheras d’elle, tu auras commerce avec elle; elle sera ta femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Et si tu ne la veux plus, tu la renverras libre, parce que tu l’auras humiliée, et tu ne la vendras pas à prix d’argent, et tu ne la mépriseras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Si un homme a deux femmes, l’une bien-aimée, l’autre haïe, et qu’elles enfantent, la détestée comme la bien-aimée, et que le fils premier-né soit de la femme haïe;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Le jour où l’homme fera le partage dé ses biens, il ne pourra transmettre le droit d’aînesse au fils de la bien-aimée, au mépris du fils premier-né, provenant de la femme haïe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Il reconnaîtra celui-ci comme son premier-né, et lui donnera double part dans tous ses biens, parce qu’il est l’aîné des enfants et que cette double part appartient au droit d’aînesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Si un homme a un fils indocile, querelleur, sourd à la voix de son père et de sa mère; s’ils le réprimandent sans qu’il les écoute,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Son père et sa mère, l’ayant pris avec eux, le conduiront auprès des anciens devant la porte de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Et ils diront aux hommes de leur ville: Notre fils que voici est désobéissant et querelleur; sourd à notre voix, il court les festins et s’enivre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Alors, les hommes de la ville le lapideront; il mourra et vous aurez déraciné parmi vous le mal, et les autres enfants indociles l’apprenant auront crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Si un homme coupable d’un crime capital est mis à mort, et que vous l’ayez pendu à une potence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Que son corps n’y passe point la nuit; enterrez-le le même jour dans une fosse, car tout homme pendu à une potence est maudit de Dieu; ne souillez donc pas la terre que Dieu vous donne en héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Si tu vois errant dans le chemin le bœuf de ton frère, ou sa brebis, tu ne les y laisseras pas; tu te hâteras de les ramener à ton frère et tu les lui rendras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Si ton frère ne demeure point près de toi, si tu ne le connais pas, tu mèneras la bête en ta maison, où elle restera jusqu’à ce que ton frère la réclame, alors tu la lui rendras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tu feras de même pour son âne, pour son manteau, pour tout ce qu’aura perdu ton frère; quoi que ce soit qu’il ait perdu, si tu le trouves, tu ne pourras pas le négliger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Aussitôt que tu auras vu l’âne de ton frère ou son bœuf tombé dans le chemin, tu ne passeras pas outre sans l’aider à le relever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'La femme ne portera pas de vêtements d’homme, l’homme ne portera pas de robe de femme; quiconque fait ces choses est en abomination au Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Si tu trouves devant toi dans le chemin, ou sur un arbre, ou à terre, un nid d’oiseau, avec les petits ou les œufs, et la mère qui les couve, tu ne prendras pas la mère en même temps que sa couvée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Tu laisseras aller la mère et n’emporteras que la couvée, afin que tu sois heureux et que tu vives de longs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Si tu achèves de bâtir une maison, tu y mettras une balustrade, et tu n’auras point occasionné de meurtre en ta maison, si quelqu’un vient à tomber de la terrasse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Tu ne sèmeras pas dans ta vigne de graines de diverses espèces, de peur que le grain que tu aurais semé ne soit consacré en même temps que le fruit de ta vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Tu n’attelleras pas ensemble pour labourer un bœuf et un âne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Tu ne te revêtiras pas d’étoffes trompeuses de laine et de lin tissus ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tu te feras des torsades sur les quatre franges des manteaux que tu porteras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Si un homme a pris une femme, si, ayant cohabité avec elle, il la prend en haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'S’il la flétrit par ses prétextes, s’il lui donne un mauvais renom, disant: J’ai pris cette femme, j’ai eu commerce avec elle, je n’ai point trouvé chez elle les signes de la virginité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Le père et la mère de la femme présenteront aux anciens, devant la porte de la ville, les preuves de la virginité de leur enfant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Le père et la mère de la femme diront aux anciens: J’ai donné ma fille que voici pour femme à cet homme et il l’a prise en haine,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Et il la flétrit par ses prétextes, disant: Je n’ai point trouvé à ta fille les signes de la virginité. Or, voici les preuves de la virginité de ma fille; à ces mots ils déploieront le vêtement devant les anciens de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Alors, les anciens prendront le mari et lui feront une réprimande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Puis, ils le condamneront à une amende de cent sicles, qu’ils donneront au père de la jeune femme, parce que l’époux aura terni le renom d’une vierge israélite; celle-ci restera sa femme, et il ne pourra jamais la répudier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Mais si les paroles de l’époux sont véritables, si l’on n’a point trouvé chez la jeune femme les signes de la virginité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'On entraînera la jeune femme devant la maison de son père; elle sera lapidée, elle mourra, parce qu’elle se sera livrée à l’impudicité parmi les fils d’Israël, et se sera prostituée dans la maison de son père; ainsi vous aurez déraciné du milieu de vous le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Si un homme est trouvé couché avec la femme d’autrui, faites-les mourir tous les deux, la femme et l’homme surpris avec elle, et vous aurez déraciné parmi vous le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Si une jeune vierge est fiancée à un homme, et si un autre homme l’ayant rencontrée dans la ville a eu commerce avec elle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Conduisez-les tous les deux devant la porte de la ville, lapidez-les, qu’ils meurent: la jeune fille, parce que dans la ville, elle n’aura point crié au secours; l’homme, parce qu’il aura souillé la femme de son prochain; ainsi vous aurez déraciné parmi vous le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Mais si l’homme a surpris la fille aux champs, et si, usant de violence, il a eu commerce avec elle, ne faites périr que l’homme qui aura abusé d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Quant à la jeune fille, elle ne sera point coupable du crime capital, mais l’homme sera punissable autant que s’il s’était levé contre son prochain et l’eût tué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Parce qu’il aura surpris la jeune fiancée dans les champs, et que, quand même elle eût crié, il n’y aurait eu là personne pour la secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Si un homme rencontre une jeune fille vierge et non fiancée, si, usant de violence, il a commerce avec elle et s’il est surpris,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Il donnera au père de la jeune fille cinquante doubles drachmes d’argent, et elle sera sa femme, car il aura attenté à son honneur: il ne pourra jamais la répudier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nul ne prendra la femme de son père, et ne soulèvera la couverture de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'L’homme qu’on a fait eunuque ou qui l’est devenu par mutilation, n’entrera pas dans l’Église du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Le fils de prostituée n’entrera pas dans l’Église du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'L’Ammonite, le Moabite n’entreront pas dans l’Église du Seigneur jusqu’à la dernière génération; qu’ils n’y entrent point, qu’ils n’y entrent jamais;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Car ils ne sont point venus à votre rencontre avec des vivres et de l’eau lorsque vous arriviez d’Égypte, et ils avaient convoqué à prix d’argent, de la Mésopotamie, Balaam, fils de Béor, afin qu’il vous maudît.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Et le Seigneur ton Dieu ne fit pas à la volonté de Balaam, et le Seigneur ton Dieu changea en bénédictions les malédictions, parce que le Seigneur ton Dieu t’aime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Tu ne leur diras jamais de paroles pacifiques ou conciliantes, tant que tu existeras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Tu n’auras point en abomination l’Iduméen, car il est ton frère; ni l’Égyptien, car tu as été passager en sa contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Leurs fils, s’il s’en établit parmi vous, entreront à la troisième génération dans l’Église du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Garde-toi de toute action mauvaise, lorsque tu iras en guerre contre les ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'S’il se trouve parmi vous un homme qu’une pollution de nuit aura rendu impur, il sortira du camp sans y rentrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Et, sur le soir, il lavera son corps avec de l’eau, et après le soleil couché il rentrera au camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Il y aura un lieu indiqué hors du camp, où l’on ira lorsque l’on aura besoin hors du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Tu auras un piquet passé dans la ceinture, et, lorsque tu te seras accroupi hors du camp, tu creuseras avec ce piquet, puis, ramenant la terre, tu cacheras ton impureté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Car le Seigneur ton Dieu viendra dans le camp pour te favoriser et te livrer ton ennemi; ton camp sera donc saint; qu’il n’y paraisse pas de souillure, qu’on la rejette au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Tu ne livreras pas, à son maître étranger, l’esclave qui s’échappant se sera attaché à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Il demeurera avec toi, et il demeurera parmi vous, où il lui sera agréable; garde-toi de l’opprimer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Il n’y aura pas de fille d’Israël qui se prostitue; ni de fils d’Israël qui fréquente des prostituées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Il n’y aura point d’initiée parmi les jeunes filles, ni d’initié parmi les fils d’Israël; n’offre pas dans la maison du Seigneur le salaire de la prostituée ni le prix d’un chien; l’un et l’autre sont en abomination au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Tu ne prendras à ton frère aucun intérêt, ni pour de l’argent, ni pour des vivres, ni pour quoi que ce soit que tu lui aurais prêté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Tu prêteras à intérêt aux étrangers, mais non à ton frère, afin que le Seigneur ton Dieu te bénisse en tous tes travaux, sur la terre où tu entres pour qu’elle soit ton héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Si tu as fait un vœu au Seigneur, tu ne mettras pas de retard à l’accomplir, car le Seigneur ton Dieu le réclamerait de toi, et il te serait imputé à péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Mais si tu n’avais pas entendu faire de vœu, il n’y aurait pas en toi de péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Tout ce qui sera sorti de tes lèvres, tu l’observeras; tu feras au Seigneur ton Dieu le présent qu’aura promis ta bouche, comme tu l’auras voué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Si tu entres dans la moisson de ton prochain, il t’est permis de cueillir à la main un épi, mais ne va pas mettre la faux dans la moisson de ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Si tu entres dans la vigne de ton prochain, il t’est permis de manger une grappe assez grosse pour que ton âme en soit rassasiée, mais ne va pas mettre du raisin dans un panier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Si un homme a pris une femme, s’il a cohabité avec elle et s’il arrive qu’elle n’ait point trouvé grâce devant lui, parce qu’il aura remarqué en elle quelque difformité; s’il a écrit à son sujet un acte de divorce, s’il le lui a remis, et s’il l’a expulsée de sa maison;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Si, étant partie, elle est devenue la femme d’un autre époux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Si ce dernier époux l’a pareillement prise en haine, lui a écrit aussi un acte de divorce et le lui a remis, et s’il vient à mourir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Il ne sera point permis au premier époux qui l’aura congédiée de la reprendre pour femme, après qu’elle aura été souillée; ce serait une abomination devant le Seigneur votre Dieu; gardez-vous de souiller la terre que le Seigneur votre Dieu vous donne pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Si un homme a pris femme récemment, il n’ira pas à la guerre, on ne le chargera d’aucune affaire, il restera tranquille à sa maison; pendant un an, il se réjouira de la femme qu’il aura épousée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Tu ne prendras pas en nantissement les meules du moulin, ni celle de dessous, ni celle de dessus, car les meules sont le nantissement de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Si un homme est convaincu d’avoir volé un de ses frères fils d’Israël, si, après s’être rendu maître de lui, il l’a vendu, il mourra, et tu auras déraciné le mal du milieu de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Garde-toi avec soin de la tache de la lèpre; tu veilleras à suivre en toute chose la règle que prescriront les prêtres lévites; tu veilleras à faire ce que je t’ai ordonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Souviens-toi de ce que le Seigneur ton Dieu a fait à Marie, durant votre voyage au sortir de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Si ton prochain est ton débiteur, quelle que soit la dette, tu n’entreras pas en sa maison pour y prendre de lui un gage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Tu te tiendras dehors, et l’homme t’apportera son gage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Si l’homme est pauvre, tu ne te remettras pas au lit, ayant son gage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Tu le lui rendras vers le coucher du soleil; qu’il dorme dans son manteau, et il te bénira, et il attirera sur toi la miséricorde du Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Tu ne feras pas tort de son salaire au pauvre ni à l’indigent, soit de tes frères, soit des prosélytes établis en tes villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Tu lui paieras son salaire le jour même; que le soleil ne se couche pas sur son salaire; car il est pauvre, il ne trouverait rien chez lui, il crierait contre toi au Seigneur, et tu te serais chargé d’un péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Les pères ne mourront pas pour leurs enfants, ni les fils pour leurs pères; chacun mourra à cause de son propre péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Tu ne feras point dévier la justice au sujet de l’étranger, de l’orphelin, de la veuve; tu ne prendras pas en nantissement le vêtement de la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Souviens-toi que tu as été esclave en la terre d’Égypte, et que le Seigneur ton Dieu t’en a délivré; c’est pour cela que je te prescris d’observer ces règles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Lorsque tu auras fait la moisson de ton champ, si une javelle a été oubliée dans ton champ, tu n’y retourneras pas pour l’aller prendre; elle sera pour l’étranger, l’orphelin ou la veuve, afin que le Seigneur te bénisse en toutes les œuvres de tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Lorsque tu auras fait la récolte de tes olives, tu ne retourneras pas glaner celles que tu aurais oubliées; elles seront pour l’étranger, l’orphelin ou la veuve; souvienstoi que tu as été esclave en la terre d’Égypte et que le Seigneur ton Dieu t’en a délivré; c’est pour cela que je te prescris d’observer ces règles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Lorsque tu auras vendangé ta vigne, tu ne vendangeras pas derechef pour prendre les grappes que tu aurais oubliées; elles seront pour l’étranger, l’orphelin ou la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Souviens-toi que tu as été esclave en la terre d’Égypte, et que le Seigneur ton Dieu t’en a délivré; c’est pour cela que je te prescris ces règles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'S’il s’élève un différend entre des hommes et s’ils comparaissent en justice, on les jugera; on justifiera le juste, on condamnera l’impie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Si l’impie mérite d’être châtié, tu le feras asseoir devant les juges, et on le fustigera devant eux selon son impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'On lui donnera quarante coups de fouet, sans en ajouter; si tu ajoutais au nombre fixé, si tu donnais encore des coups, ton frère serait honteusement défiguré devant toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Tu ne muselleras pas ton bœuf broyant des épis sur l’aire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Si de deux frères vivant sous le même toit, l’un vient à mourir sans enfants, la femme du défunt ne s’en ira pas pour suivre un homme qui ne lui soit point proche; le frère de son époux s’approchera d’elle, il la prendra pour femme, il cohabitera avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Et l’on inscrira au nom du défunt l’enfant qu’elle mettra au monde, afin que ce nom ne soit pas effacé d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Si l’homme ne veut pas prendre la femme de son frère, la femme ira devant la porte de la ville, disant: Le frère de mon mari refuse de faire revivre le nom de son frère en Israël; le frère de mon mari ne le veut pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Alors, les anciens de sa ville appelleront l’homme, ils lui parleront, et s’il leur répond: Je ne la veux point prendre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'La femme de son frère s’approchera des anciens; l’homme déliera la sandale de l’un de ses pieds, et la femme lui crachera au visage, disant: Ainsi soit fait à l’homme qui en Israël ne relèvera pas la maison de son frère;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Et la maison de cet homme sera appelée en Israël: maison de celui qui a délié sa sandale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Si deux hommes se battent pour un même objet, frère contre frère, et si la femme de l’un d’eux s’approche pour tirer son mari des mains de celui qui le frappe, et si, portant la main sur ce dernier, elle lui saisit les parties,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Tu couperas cette main, ton œil ne prendra pas la femme en pitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Il n’y aura pas dans ton sac poids et poids, un grand ou un petit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Il n’y aura pas en ta maison mesure et mesure, une grande ou une petite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Ton poids sera vrai et juste, ta mesure sera vraie et juste, afin que tu vives de longs jours sur la terre que le Seigneur ton Dieu te donne pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Car quiconque fait ces choses, quiconque pratique l’iniquité est en abomination au Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Souviens-toi de ce que t’a fait Amalec, durant ton voyage, au sortir de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Il s’opposa à toi sur la route; il s’en prit aux traîneurs exténués de fatigue derrière toi; car tu souffrais de la faim, et tu étais fatigué, et il n’eut point crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Ceci donc sera fait: Quand le Seigneur ton Dieu, malgré tous tes ennemis, t’aura mis en repos dans la contrée qu’il te donne pour héritage, tu effaceras sous le ciel le nom d’Amalec; garde-toi de l’oublier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Lorsque tu seras entré en la terre que le Seigneur ton Dieu te donne en héritage, et que tu l’auras partagée, et que tu y seras établi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Tu prendras des prémices des fruits de la terre que le Seigneur ton Dieu te donne, et tu les déposeras en des corbeilles, et tu iras au lieu que le Seigneur ton Dieu aura choisi pour que son nom y soit invoqué,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Et tu iras trouver le prêtre de ces temps-là, et tu lui diras: J’atteste aujourd’hui au Seigneur mon Dieu que je suis entré en la terre que le Seigneur mon Dieu a promis à nos pères de nous donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Et le prêtre prendra de tes mains la corbeille, et il la posera sur l’autel du Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Et il prendra la parole pour toi, et il dira devant le Seigneur ton Dieu: Mon père a quitté la Syrie, et il est descendu en Égypte; il y est entré peu nombreux, et il y est devenu une grande nation, une innombrable multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Et les Égyptiens nous maltraitèrent, ils nous humilièrent; ils nous imposèrent de durs travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Et nous invoquâmes le Seigneur notre Dieu; il nous entendit, il vit notre humiliation, nos labeurs, notre oppression.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Et le Seigneur lui-même nous fit sortir d’Égypte, par sa grande force, par sa main puissante, par son bras très-haut, par de grandes merveilles, des signes et des prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Et il nous a conduits en ce lieu; il nous a donné cette terre, terre où coulent le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Et maintenant j’offre les premiers fruits de la terre que vous m’avez donnée, Seigneur, terre où coulent le lait et le miel. Puis, tu laisseras ces prémices devant le Seigneur ton Dieu, et tu te prosterneras devant le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Et tu te réjouiras de tous les biens que le Seigneur ton Dieu t’aura donnés, et avec toi toute ta famille, et le lévite, et l’étranger établi parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Et lorsque, dans la troisième année, tu auras fini de donner toute dîme de tes fruits, tu donneras une seconde dîme au lévite, à l’étranger, à l’orphelin et à la veuve, et ils mangeront dans tes villes, et ils se réjouiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Et tu diras au Seigneur: J’ai pris dans ma maison ces choses saintes, je les ai données au lévite, à l’étranger, à l’orphelin, à la veuve; j’ai fait selon vos commandements, je ne les ai point transgressés, je n’en ai rien oublié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Et, dans le deuil, je n’ai rien mangé de ces choses saintes, je n’ai rien offert d’impur; je n’en ai rien consacré à un mort; j’ai obéi à la parole du Seigneur mon Dieu, j’ai fait ce que vous m’avez prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Voyez-moi, du ciel votre demeure, bénissez Israël votre peuple et la terre que vous lui avez donnée, comme vous l’avez promis à nos pères, cette terre où coulent le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'En ces jours-là, le Seigneur ton Dieu t’a commandé d’exécuter les commandements, les jugements et les ordonnances de justice; observe-les donc, et exécute-les de tout ton cœur et de toute ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Tu as pris Dieu pour ton Dieu, et afin de marcher en toutes ses voies, d’observer ses commandements, et d’obéir à sa parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Et le Seigneur t’a pris pour que tu sois son propre peuple, comme il te l’a dit, et pour que tu observes ses commandements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Et pour que tu sois au-dessus des autres nations, autant qu’il t’a élevé en renom, en célébrité et en gloire, et pour que tu sois le peuple saint du Seigneur ton Dieu, comme il l’a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Et Moïse, avec les anciens, continua de donner des ordres à Israël, et il dit: Observez tous les commandements que je vous intime aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Le jour où tu auras traversé le Jourdain pour entrer en la terre que le Seigneur ton Dieu te donne, tu dresseras pour toi de grandes pierres que tu récrépiras de chaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Tu écriras ensuite sur ces pierres tous les articles de la loi, aussitôt que vous aurez tous franchi le Jourdain, et que vous serez entrés en la terre que le Seigneur Dieu de vos pères vous donne, terre où coulent le lait et le miel, comme le Seigneur l’a dit à vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Dès que vous aurez franchi le Jourdain, vous dresserez ces pierres dont je vous parle, sur le mont Hébal, puis vous les récrépirez de chaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Et vous bâtirez au même lieu un autel au Seigneur votre Dieu, un autel de pierres, où il n’entrera point de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Vous le bâtirez de pierres sans défaut, et sur cet autel vous offrirez des holocaustes au Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Vous offrirez sur cet autel les hosties pacifiques; vous mangerez, vous vous rassasierez, et vous vous réjouirez devant le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Et sur les pierres vous écrirez toute la loi, trèsmanifestement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Et Moïse, avec les prêtres lévites, continua de parler à tout Israël, et il dit: Fais silence, écoute, Israël, aujourd’hui tu es devenu le peuple du Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Et tu seras docile à la parole du Seigneur, tu exé cuteras ses commandements et ses ordonnances, que je t’intime aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Et ce jour-là même, Moïse donna des ordres au peuple, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Voici ceux qui se tiendront sur le mont Garizim, après avoir passé le Jourdain, pour bénir le peuple: Siméon, Lévi, Juda, Issachar, Joseph, Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Voici ceux qui se tiendront sur le mont Hébal, du côté de la malédiction: Ruben, Gad, Aser, Zabulon, Dan et Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Et les lévites, parlant à haute voix, diront à tout Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Maudit soit l’homme qui fera une image sculptée ou jetée en fonte, abomination du Seigneur, ouvrage de la main d’un artisan, et qui la placera en un lieu secret; et le peuple entier répondant, dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Maudit celui qui n’honore pas son père ou sa mère; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Maudit celui qui déplace les bornes de son voisin; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Maudit celui qui égare l’aveugle dans le chemin; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Maudit celui qui fait dévier la justice à l’égard de l’étranger, de l’orphelin et de la veuve; et tout le peuple dira Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Maudit celui qui a commerce avec la femme de son père, et soulève la couverture de son père; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Maudit celui qui a commerce avec une bête; et le peuple entier dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Maudit celui qui a commerce avec la sœur de son père ou de sa mère; et le peuple entier dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Maudit celui qui a commerce avec sa fille; et tout le peuple dira: Ainsi soit-il. Maudit soit celui qui a commerce avec la sœur de sa femme; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Maudit celui qui frappe son prochain dans une embuscade; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Maudit soit celui qui acceptera des présents pour condamner à mort et verser le sang innocent; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Maudit tout homme qui ne persévèrera pas en tous les articles de cette loi, pour les mettre en pratique; et tout le peuple dira: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Et si tu écoutes la parole du Seigneur ton Dieu, si tu observes et exécutes avec docilité ses commandements que je t’intime aujourd’hui, le Seigneur ton Dieu te fera plus de dons qu’à nulle des nations de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Et toutes ses bénédictions viendront sur toi, et elles te trouveront, si tu es docile à la parole du Seigneur, après l’avoir écoutée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Tu seras béni en ta ville et béni dans tes champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Bénis seront les fruits de tes entrailles, et les produits de ta terre, et tes grands troupeaux de bœufs, et tes menus troupeaux de brebis ou de chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Bénis seront tes greniers et les choses que tu Y déposeras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Béni seras-tu, soit que tu entres, soit que tu sortes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Que le Seigneur ton Dieu te livre tes ennemis qui te résisteront: ils seront broyés devant toi; ils viendront à toi par un seul chemin, il y aura sept voies par lesquelles ils s’enfuiront devant ta face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Que le Seigneur bénisse tes celliers et toute chose où tu auras mis la main, en la terre qu’il te donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Que le Seigneur te soutienne pour que tu sois son peuple saint, comme il l’a promis à tes pères. Si tu es docile à la parole du Seigneur ton Dieu, si tu marches en toutes ses voies,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Toutes les nations de la terre te considèreront, parce que le nom du Seigneur aura été invoqué par toi, et elles te redouteront,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Et le Seigneur ton Dieu multipliera tes biens; il multipliera les fruits de tes entrailles, les rejetons de tes troupeaux, les produits de tes champs, en la terre qu’il a promis à tes pères de te donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Que le Seigneur t’ouvre son inestimable trésor: le ciel, pour donner de la pluie à tes champs au temps opportun; qu’il bénisse toutes les œuvres de tes mains, et tu prêteras à beaucoup de nations et tu ne leur emprunteras rien, et tu règneras sur beaucoup de nations et elles ne règneront point sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Que le Seigneur te place au premier rang et jamais au dernier, que tu sois au-dessus et non au-dessous. Si tu es docile à la parole du Seigneur en toutes les choses que je te prescris aujourd’hui d’observer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Tu ne t’écarteras ni à droite ni à gauche d’aucun des commandements que je t’intime aujourd’hui, pour suivre d’autres dieux et les servir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Mais si tu es indocile à la parole du Seigneur ton Dieu, si tu n’observes pas tous ses commandements que je t’intime aujourd’hui, alors viendront sur toi toutes les malédictions, et elles t’atteindront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Tu seras maudit dans la ville et maudit dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Maudits seront tes greniers et les choses que tu y déposeras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Maudits seront les fruits de tes entrailles, et les produits de ta terre, et tes grands troupeaux de bœufs, et tes menus troupeaux de brebis et de chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Tu seras maudit, soit que tu entres, soit que tu sortes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Que le Seigneur t’envoie l’indigence, la faim dévorante, l’insuccès en toute chose où tu mettras la main, jusqu’à ce qu’il t’ait exterminé, jusqu’à ce qu’il t’ait rapidement détruit à cause de tes mauvaises mœurs, et parce que tu l’auras abandonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Que le Seigneur attache sur toi la peste, jusqu’à ce qu’il t’ait effacé de la terre où tu entres pour qu’elle soit ton héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Que le Seigneur te frappe de détresse, de fièvre, de frisson, d’irritation, d’air corrompu, de jaunisse; que les maladies te tourmentent jusqu’à ce qu’elles t’aient détruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Au-dessus de ta tête le ciel sera pour toi d’airain, et sous tes pieds le sol sera de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Que le ciel au lieu de pluie te donne pour tes champs des trombes de poussière; que des amas de sable tombent du ciel jusqu’à ce qu’ils t’aient broyé, jusqu’à ce qu’ils t’aient rapidement anéanti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Que le Seigneur, devant tes ennemis, te livre au carnage; tu iras à eux par un seul chemin, et il y aura sept voies par lesquelles tu t’enfuiras devant leur face, et tu seras dispersé parmi tous les royaumes de la terre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Et vos morts seront la pâture des oiseaux du ciel et des bêtes fauves de la terre qui s’en repaîtront, et il n’y aura personne pour les épouvanter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Que le Seigneur te donne au fondement les ulcères d’Égypte, la gale, et une telle démangeaison que tu n’y puisses trouver remède.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Que le Seigneur te frappe de démence, d’aveuglement et de stupidité d’esprit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Et tu marcheras à tâtons en plein midi, comme un aveugle marche à tâtons dans les ténèbres; rien ne te réussira, tu seras opprimé et dépouillé chaque jour, et il n’y aura personne pour te secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Tu prendras une femme, et un autre la possèdera; tu bâtiras une maison, et tu n’y demeureras point; tu planteras une vigne, et tu ne la vendangeras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Ton bœuf sera égorgé devant toi, et tu n’en mangeras rien; ton âne te sera ravi, et ne te sera pas rendu; tes brebis seront livrées à tes ennemis, et il n’y aura personne pour te secourir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tes fils et tes filles seront livrés à une nation étrangère, et tes yeux le verront et ils en sècheront, et ta main sera impuissante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Les fruits de ta terre et de tous tes travaux seront dévorés par une nation que tu ne connais pas, et tu seras chaque jour opprimé et broyé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Et tu seras saisi de stupeur de tout ce que tes yeux verront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Que le Seigneur te frappe de mauvais ulcères aux genoux et aux jambes, de telle sorte que, des pieds à la tête, tu ne puisses plus guérir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Que le Seigneur conduise toi et tes chefs chez une nation que tu ne connais pas, que n’ont pas connue tes pères, où tu serviras d’autres dieux, des dieux de pierre ou de bois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Où tu seras un sujet de proverbes, de paraboles et de récits que répèteront tous les gentils chez qui t’aura conduit le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Tu emporteras aux champs beaucoup de semence, et tu en rapporteras peu de grains; la sauterelle les aura dévorés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Tu planteras une vigne, mais tu auras beau la cultiver, tu ne boiras pas de vin; le ver aura mangé la grappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Tu auras des oliviers sur tout ton territoire, et tu ne t’oindras pas d’huile; les olives auront coulé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Tu engendreras des fils et des filles, tu ne les conserveras pas; ils seront emmenés en captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'La nielle détruira tous tes arbres et les produits de tes champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'L’étranger, établi auprès de toi, montera, montera; mais toi, tu descendras toujours plus bas;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Il te prêtera, et tu ne lui prêteras pas; il sera au premier rang, et toi au dernier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Et toutes ces malédictions fondront sur toi, et elles te poursuivront, et elles t’atteindront jusqu’à ce que tu sois exterminé et détruit, parce que tu auras été indocile à la parole du Seigneur, et que tu n’auras pas observé ses commandements que je t’ai intimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Et il y aura perpétuellement en ta race des signes et des prodiges,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'En punition de ce que tu n’auras pas servi le Seigneur ton Dieu avec joie et avec un esprit reconnaissant pour la multitude de ses bienfaits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Et tu serviras les ennemis que le Seigneur ramè→ nera contre toi; tu les serviras en souffrant de la faim, de la soif, du dénûment de toutes choses; et il te mettra autour du cou un collier de fer, jusqu’à ce qu’il t’ait exterminé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Le Seigneur amènera contre toi, de l’extrémité de la terre, une nation rapide comme le vol de l’aigle, une nation dont tu n’entendras pas la langue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Une nation au front éhonté, chez qui nul ne respectera le visage du vieillard et n’aura pitié de la jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Elle dévorera les rejetons de tes bestiaux et les fruits de tes champs; elle ne te laissera ni blé, ni vin, ni huile; elle dévorera tes grands troupeaux de bœufs, et tes menus troupeaux de chèvres et de brebis, jusqu’à ce qu’elle t’ait détruit');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Et broyé dans tes villes, jusqu’à ce qu’elle ait renversé tous les remparts hauts et redoutables en lesquels tu te confiais sur ton territoire; et elle t’opprimera dans les villes que je t’ai données.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Et tu te nourriras des fruits de tes entrailles, de la chair des fils et des filles que je t’aurai donnés, tant seront grands ta détresse et les fléaux que t’auront apportés les ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Le délicat parmi vous, le voluptueux, regardera d’un œil de convoitise son frère, la femme qui reposera sur son sein, les enfants qui lui resteront et qui auront été épargnés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Et nul d’eux ne fera part à qui que ce soit des chairs de ses enfants dont il se nourrira, car il ne lui en sera rien resté, tant seront grands ta détresse et les fléaux que t’auront apportés les ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Et la délicate parmi vous, la voluptueuse, dont le pied n’aura jamais essayé de marcher sur la terre, tant elle sera tendre et amollie, regardera d’un œil de convoitise son époux sur son sein, et son fils et sa fille,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Et la jeune fille qui sort à peine de ses entrailles, et le jeune fils qu’elle vient d’enfanter; elle mangera leurs chairs en cachette, à cause de son indigence de toutes choses, tant seront grands sa détresse et les fléaux que tes ennemis auront apportés dans tes villes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Si tu refuses d’exécuter tous les articles de la loi écrite en ce livre, et de craindre le nom redoutable que tu dois vénérer, ce nom redoutable:,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Le Seigneur rendra célèbres tes plaies et les plaies de ta race, plaies grandes et extraordinaires, maladies malignes et cruelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Il fera revivre toutes les plaies d’Égypte, ces plaies cruelles dont tu as été effrayé devant les Égyptiens; et tous ces maux s’attacheront à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Le Seigneur fera fondre sur toi, jusqu’à ce qu’il t’ait exterminé, toute plaie, toute maladie, écrite ou non écrite en ce livre de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Et pour avoir été indociles à la parole du Seigneur votre Dieu vous resterez en petit nombre, au lieu de continuer à être comparables, par votre multitude, aux étoiles du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'De même que le Seigneur se sera réjoui à vous combler de biens, à vous multiplier, de même le Seigneur se réjouira à vous exterminer; et vous serez enlevés rapidement de cette terre en laquelle vous entrez pour qu’elle soit votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Le Seigneur ton Dieu te dispersera chez toutes les nations d’une extrémité à l’autre de la terre, et là, tu serviras d’autres dieux de terre ou de bois, auxquels n’auront cru ni toi ni tes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Ce n’est pas tout chez ces nations, il ne t’accordera pas de repos, et il n’y aura point de lieu où s’arrête la plante de tes pieds; et là, le Seigneur te donnera un autre cœur, un cœur incrédule, et des yeux défaillants et une âme épuisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Et ta vie sera suspendue devant tes yeux, et tu craindras nuit et jour, et tu ne croiras pas à ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Tu diras le matin: Oh! si venait le soir! et tu diras le soir Oh! si venait le matin! à cause des terreurs que ressentira ton âme, et des visions qui frapperont tes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Et le Seigneur te reconduira en Égypte sur des barques hors de ce chemin dont j’ai dit: Vous ne le reverrez plus; et là, vos ennemis vous mettront en vente comme esclaves, hommes et femmes, et il n’y aura point d’acheteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 69, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Voilà les conditions de l’alliance que le Seigneur prescrivit à Moïse de faire avec les fils d’Israël, en la terre de Moab, outre l’alliance qu’il avait précédemment faite avec eux en Horeb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Et Moïse convoqua tous les fils d’Israël, et il leur dit: Vous avez vu tout ce que devant vous, en la terre d’Égypte, le Seigneur a fait au Pharaon, à ses serviteurs, et à toute la contrée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Vos yeux ont été frappés de ces grandes épreuves, de ces signes et de ces prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Et jusqu’à ce jour le Seigneur ne vous a pas donné un cœur pour comprendre, des yeux pour voir, des oreilles pour écouter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Il vous a fait errer pendant quarante ans dans le désert, et vos vêtements n’ont pas vieilli, vos sandales sous vos pieds ne se sont pas usées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Vous n’avez pas mangé de pain, vous n’avez bu ni vin ni liqueur fermentée, afin, a dit le Seigneur, que vous sachiez que je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Vous êtes ainsi venus jusqu’au lieu où vous êtes, et Séhon, roi d’Esebon, et Og, roi de Basan, sont sortis à notre rencontre pour nous combattre, et nous les avons vaincus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Nous avons pris leur terre je l’ai donnée en héritage à Ruben, à Gad, et à une demi-tribu de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Veillez à vous conformer à toutes les paroles de l’alliance, afin que vous fassiez toutes choses avec intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Or, vous voici tous aujourd’hui devant le Seigneur votre Dieu chefs et tribus, anciens, juges, scribes, peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Femmes, enfants, étrangers établis dans le camp, depuis le fendeur de bois jusqu’au porteur d’eau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Pour entrer dans l’alliance du Seigneur votre Dieu et pour entendre ses malédictions, comme le Seigneur les règle aujourd’hui devant vous');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Au moment de vous instituer son peuple; luimême sera ton Dieu, comme il l’a dit et juré à tes pères Abraham, Isaac et Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Et ce n’est pas pour vous seuls que j’établis cette alliance et ces malédictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'C’est aussi bien pour ceux qui ne sont pas ici aujourd’hui avec vous, que pour ceux qui sont ici aujourd’hui avec vous devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Car vous savez comment nous avons demeuré en la terre d’Égypte, et comment nous avons passé au milieu des nations que vous avez rencontrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Vous avez vu leurs abominations, et les idoles de bois ou de pierre, d’argent ou d’or, qui existent chez elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Et il n’y a parmi vous ni homme, ni femme, ni famille, ni tribu, dont la pensée se soit écartée du Seigneur votre Dieu, et qui ait servi les dieux des nations; il n’y a point parmi vous de racine nourrie de fiel et d’amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Or, après avoir ouï les termes de cette malédiction, s’il arrive que quelqu’un s’encourage en son cœur, et dise: Que les menaces du Seigneur s’accomplissent sur moi, car je veux marcher dans l’égarement de mon âme; crains alors que le pécheur ne perde avec lui l’innocent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Dieu ne sera plus propice à cet homme; la jalousie, la colère du Seigneur s’enflammeront soudain contre lui; toutes les malédictions de l’alliance, écrites en ce livre, l’assailliront, et son nom sera effacé sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Et le Seigneur le séparera des fils d’Israël par ses fléaux, conformément aux malédictions de l’alliance écrites en ce livre de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Lorsqu’une autre génération, lorsque vos fils qui naîtront après vous, et l’étranger qui de loin viendra sur cette terre, verront ces plaies et les fléaux que le Seigneur fera tomber sur elle;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Lorsqu’ils verront le soufre et le sel fulminant, et ces champs qui ne seront point ensemencés, qui ne produiront rien, où nulle plante ne poussera, qui seront bouleversés comme Sodome, Gomorrhe et Adama-Siboïm, qu’en sa colère le Seigneur a détruites;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Ils diront et les gentils diront pareillement: Pourquoi le Seigneur traite-t-il ainsi cette terre? Que veut dire ce grand courroux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Et on répondra: C’est parce qu’ils ont abandonné l’alliance du Seigneur Dieu de leurs pères, l’alliance que Dieu avait faite avec leurs pères, après les avoir tirés de la terre d’Égypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Et parce que, s’en étant éloignés, ils ont servi d’autres dieux qu’ils n’avaient point connus, au culte desquels il ne les avait point destinés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Voilà pourquoi le Seigneur s’est enflammé de courroux contre cette terre, au point de faire tomber sur elle toutes les malédictions écrites au livre de sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Et dans les transports de sa colère le Seigneur les a enlevés de cette contrée qui leur appartenait, et il les a chassés, comme vous voyez, sur une terre lointaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Les choses secrètes sont au Seigneur notre Dieu; les choses révélées sont pour vous et vos enfants à toujours, afin que vous accomplissiez toutes les paroles de cette loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Lorsque ces choses, cette bénédiction, puis cette malédiction que je te fais connaître, se seront réalisées pour toi, et lorsque tu te les seras rappelées en ton cœur parmi les nations chez qui le Seigneur t’aura dispersé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'Lorsque tu te seras converti au Seigneur ton Dieu, et que tu seras docile à sa parole pour exécuter de tout ton cœur et de toute ton âme ce que je te prescris aujourd’hui,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Le Seigneur réparera le mal que t’auront fait tes péchés; il aura pitié de toi, et il te fera revenir du milieu des gentils chez qui le Seigneur t’aura dispersé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Quand même tu serais disséminé sous tout le ciel, d’une extrémité à l’autre, le Seigneur te rassemblerait, le Seigneur t’en ramènerait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Le Seigneur ton Dieu te fera rentrer en la terre que tes pères t’auront transmise, et tu la possèderas; le Seigneur te comblera de biens, et il te sera plus favorable encore qu’à tes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Dieu purifiera ton cœur et le cœur de ta race, pour que tu aimes le Seigneur ton Dieu de tout ton cœur et de toute ton âme, et pour que tu vives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Le Seigneur transportera toutes ses malédictions sur tes ennemis, sur ceux qui te haïssent et t’auront persécuté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Et tu seras converti, tu seras docile à la parole du Seigneur ton Dieu, et tu exécuteras ses commandements que je t’intime aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Alors, le Seigneur te bénira en toute œuvre de tes mains, et dans les fruits de tes entrailles, et dans les rejetons de tes bestiaux, et dans les récoltes de tes champs; car le Seigneur aura recommencé à faire sa joie de ta prospérité, comme il s’était réjoui de celle de tes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Et tu seras docile à la parole du Seigneur pour observer ses commandements, ses jugements et ses ordonnances écrits au livre de cette loi, si tu t’es converti au Seigneur ton Dieu de tout ton cœur et de toute ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Le commandement que je te donne aujourd’hui n’est pas excessif ni hors de ta portée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Il n’est point au plus haut du ciel, de sorte que tu puisses dire Qui s’élèvera pour nous jusqu’au ciel, et recueillera pour nous ce commandement, afin qu’après l’avoir entendu, nous l’exécutions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Il n’est point au delà de la mer, de sorte que tu puisses dire: Qui pour nous se transportera au delà de la mer, et recueillera pour nous ce commandement, afin qu’après l’avoir entendu, nous l’exécutions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'La parole est auprès de toi; elle est dans ta bouche et dans ton cœur, et dans tes mains pour que tu l’accomplisses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Je place aujourd’hui devant toi la vie et la mort, le bien et le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Si tu es docile à ce commandement du Seigneur ton Dieu, que je t’intime aujourd’hui: d’aimer le Seigneur ton Dieu, de marcher en toutes ses voies, d’observer ses jugements et ses ordonnances, vous vivrez tous, vous serez nombreux, et le Seigneur ton Dieu te bénira sur toute la terre en laquelle tu seras entré pour en faire ton héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mais si ton cœur change, si tu deviens indocile, et I. — 16 si en ton égarement tu adores d’autres dieux, si tu les sers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Je te déclare aujourd’hui que vous périrez, et que vous ne passerez point de longs jours sur la terre au delà du Jourdain, où tu vas entrer pour qu’elle soit ton héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Je prends maintenant à témoin devant vous le ciel et la terre, que je place devant vous la vie et la mort, la bénédiction et la malédiction: puisses-tu choisir la vie, afin que tu vives, toi et ta race, pour');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Aimer le Seigneur ton Dieu, être docile à sa parole, et t’attacher à lui. Voilà la vie et la longue durée de tes jours sur la terre, que le Seigneur a promise à tes pères Abraham, Isaac et Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Et Moïse acheva de dire toutes ces paroles à tous les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Et il leur dit: J’ai cent vingt ans, je ne pourrai plus bientôt entrer ni sortir; et le Seigneur m’a dit: Tu ne passeras pas le Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Le Seigneur ton Dieu qui marche à ta tête, exterminera lui-même ces nations à ton aspect, et tu prendras possession de leur héritage par les soins de Josué, qui va marcher à ta tête, comme l’a prescrit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Et le Seigneur ton Dieu les traitera, elles et leur terre, comme il a traité Séhon et Og, les deux rois des Amorrhéens, en deçà du fleuve; il les exterminera comme il les a exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Le Seigneur vous les a livrées, et vous leur ferez ce que j’ai prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Sois fort et agis en homme, n’aie ni crainte ni faiblesse; ne te laisse pas frapper de stupeur devant elles, car le Seigneur ton Dieu, qui marche parmi nous, ne t’a point abandonné ni délaissé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Et Moïse appela Josué, et il lui dit devant tout Israël: Sois fort, agis en homme; car tu entreras, à la tête de ce peuple, en la terre que le Seigneur a promis à vos pères de leur donner, et tu la partageras entre les tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Le Seigneur, qui marche parmi nous, ne t’abandonnera pas, et il ne t’a pas délaissé; n’aie ni crainte, ni faiblesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Moïse écrivit les paroles de cette loi en un livre, et il le donna aux prêtres fils de Lévi, qui transportent l’arche de l’alliance du Seigneur, ainsi qu’aux plus anciens des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Et Moïse, en ce jour-là, leur donna des ordres, et il dit: Après sept ans, l’année de la rémission, pendant la fête des tabernacles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Lorsque tout Israël se sera rassemblé pour comparaître devant le Seigneur notre Dieu, au lieu qu’aura choisi le Seigneur, vous lirez cette loi devant tout Israël, qui se tiendra attentif,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Lorsque tout le peuple: hommes, femmes, enfants, étranger établi en vos villes, sera réuni; afin qu’il l’entende et qu’il apprenne à craindre le Seigneur; et ils seront instruits à obéir à toutes les paroles de cette loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Et leurs fils qui l’ignoreront encore écouteront et apprendront à craindre le Seigneur votre Dieu, tous les jours qu’ils vivront sur la terre au delà du Jourdain, en laquelle vous allez entrer pour qu’elle soit votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Et le Seigneur dit à Moïse: Voilà que le jour de ta mort est venu, appelle Josué; tenez-vous devant la porte du tabernacle du témoignage, pour que je lui donne mes ordres. Et ils se tinrent devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Alors, le Seigneur descendit en une nuée, et il s’arrêta devant la porte du tabernacle du témoignage, et la colonne de nuée demeura devant la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Puis, le Seigneur dit à Moïse: Voilà que tu vas dormir avec tes pères, et ce peuple se lèvera, et il se prostituera à la suite des dieux étrangers de la terre où il entre; ils me délaisseront, et ils déchireront l’alliance que j’ai faite avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'En ce jour-là, je serai enflammé de colère et je les abandonnerai, et je détournerai d’eux mon visage; et ce peuple sera dévoré; en ce jour-là, des maux sans nombre, des afflictions s’empareront de lui; et il dira: Ces maux me sont venus parce que le Seigneur n’est pas avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Pour moi, en ce jour-là, je détournerai d’eux mon visage à cause de tous les vices auxquels ils se seront adonnés, car ils se seront pervertis avec des dieux étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Écrivez donc les paroles de ce cantique, et enseignez-le aux fils d’Israël, et faites-le passer par leur bouche, afin que, devant moi, ce cantique porte témoignage pour les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Je les introduirai dans cette terre fortunée que j’ai promis à leurs pères de leur donner, terre où coulent le lait et le miel; et ils mangeront, et, s’étant repus, ils sentiront la satiété, et ils s’égareront avec les dieux étrangers; ils les serviront, ils m’irriteront et déchireront mon alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Mais ce cantique portera témoignage devant moi; en effet, ni leur bouche, ni la bouche de leur race ne l’ou blieront tout à fait; et moi, je sais leur malice et ce qu’ils feront aujourd’hui même, avant que je les aie introduits en cette terre fortunée que j’ai promise à leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'En ce jour-là donc, Moïse écrivit ce cantique, et il l’apprit aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Et il donna des ordres à Josué, et il lui dit: Sois fort et agis en homme, car tu vas conduire les fils d’Israël en la terre que le Seigneur leur a promise, et le Seigneur sera avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Or, quand Moïse eut achevé d’écrire, jusqu’audernier mot, toutes les paroles de cette loi, en un livre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Il donna ces ordres aux lévites qui transportent l’arche de l’alliance du Seigneur, et il leur dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Prenez le livre de cette loi, déposez-le sur les côtés de l’arche de l’alliance du Seigneur votre Dieu, et là, il sera pour vous un témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Je connais, ô Israël, votre humeur provoquante, votre entêtement; je sais qu’aujourd’hui même, tandis que je vis encore parmi vous, vous êtes aigris contre les choses du Seigneur; comment donc ne le seriez-vous pas après ma mort?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Amenez-moi vos chefs de tribus, vos anciens, vos juges, vos scribes, afin qu’à leurs oreilles je dise toutes ces paroles, et je prendrai à témoin le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Car, je sais qu’aussitôt après ma mort, vous vous abandonnerez à l’iniquité et vous vous écarterez de la voie que je vous ai tracée; et peu de jours après, les maux fondront sur vous, parce que vous aurez fait le mal devant le Seigneur, jusqu’à l’irriter contre vos mauvaises œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Et, aux oreilles de l’Église, Moïse prononça les paroles de ce cantique jusqu’à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Sois attentif, ciel, et je parlerai; terre, écoute les paroles de ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Que mes leçons soient attendues comme la pluie, que mes paroles descendent comme la rosée, comme une ondée sur le gazon, comme des gouttes d’eau sur l’herbe des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Car j’ai invoqué le nom du Seigneur; reconnaissez la grandeur de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Dieu, ses œuvres sont véritables, toutes ses voies sont la justice, c’est le Dieu fidèle en qui il n’est point d’iniquité, le Seigneur juste et saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Ils n’étaient pas à lui ces enfants coupables qui ont péché, race fourbe et pervertie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Est-ce là ce que tu rends au Seigneur, peuple insensé, dénué de sagesse? N’est-il pas ton père, qui t’a possédé, et qui t’a créé, et qui t’a pétri?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Souviens-toi des jours d’autrefois, considère les années, de générations en générations; interroge ton père, il t’instruira; questionne tes anciens, ils te répondront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Quand le Très-Haut a dispersé les nations, quand il a disséminé les fils d’Adam, il a fixé les limites des nations, selon le nombre de ses anges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Et il a pris pour sa part son peuple Jacob; il s’est réservé pour héritage Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Il a pourvu à ses besoins dans le désert sur une terre aride où son peuple souffrait de la soif; il l’a enveloppé, il l’a élevé, il l’a conservé comme la prunelle de l’œil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Tel un aigle abrite son aire et aime ses aiglons, tel le Seigneur a étendu ses ailes, a recueilli son peuple et l’a pris sur ses reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Le Seigneur seul les a conduits; il n’y avait point avec eux de dieux étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Il leur a fait vaincre la force d’une terre rebelle; il les a nourris des fruits des champs; ils ont tiré du miel des rochers, et de l’huile des pierres les plus dures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Jacob a mangé du beurre de ses vaches et du lait de brebis; il a mangé la graisse des agneaux et des béliers, les rejetons des taureaux et des boucs, avec la mœlle du froment; ils ont bu du vin, sang de la grappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Ainsi, Jacob a mangé, il s’est repu; mais le bienaimé est devenu rétif, il s’est engraissé, il a grossi, il s’est enrichi, et il a délaissé Dieu son créateur; il s’est éloigné de Dieu son sauveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Et ils m’ont aigri au sujet des dieux étrangers; ils m’ont rempli d’amertume, à cause de leurs abominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Ils ont sacrifié aux démons et point à Dieu; ils ont sacrifié à des dieux qu’ils ne connaissaient pas, qui sont venus récemment et soudain, que ne connaissaient pas leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Tu as délaissé le Dieu qui t’a fait naître, tu as oublié le Dieu qui t’a nourri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Et le Seigneur l’a vu et il a été jaloux, et il a été exaspéré par la colère, car ce sont ses fils et ses filles qui l’ont irrité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Alors, il a dit: Je détournerai d’eux ma face, et je leur révèlerai ce qui leur adviendra aux derniers jours, car c’est une race pervertie; ce sont des enfants auxquels on ne peut avoir foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ils m’ont rendu jaloux contre ce qui n’est point Dieu; ils m’ont irrité avec leurs idoles, et moi aussi je les rendrai jaloux contre ce qui n’est point encore à mes yeux une nation; je les irriterai par les grâces que j’aurai faites à une nation maintenant sans intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Le feu que mon courroux a allumé brûlera jusque sous la terre; il dévorera la terre et ses fruits, il dévorera les fondements des montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Je réunirai contre eux des fléaux, et je les combattrai de mes traits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Épuisés par la faim, devenus la pâture des oiseaux de proie, énervés sans ressource, je déchaînerai contre eux les dents des bêtes fauves, et la fureur de celles qui rampent sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Au dehors, le glaive les privera de leurs enfants; en leurs demeures, l’épouvante tuera le jeune homme et la vierge, l’enfant à la mamelle et le vieillard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'J’ai dit: Je les disperserai et j’effacerai leur souvenir parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Je le ferais si ce n’était la colère de leurs ennemis, si je ne craignais que ceux-ci ne vivent longtemps, qu’ils ne prennent confiance en eux-mêmes, qu’ils ne disent: Notre bras très-haut et non le Seigneur a fait toutes ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'C’est une nation où le conseil a péri, et il n’y a pas en eux de sagesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Ils n’ont jamais songé à comprendre; qu’ils reçoivent ces choses que le cours du temps leur amènera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Comment un seul mettra-t-il en fuite mille hommes, et comment deux hommes poursuivront-ils des myriades, si ce n’est que Dieu les a vendus, et que le Seigneur les a livrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Leurs dieux ne sont pas comme notre Dieu, et nos ennemis sont des insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Leur vigne provient de la vigne de Sodome, leur sarment vient de Gomorrhe; leur grappe est une grappe de fiel, leur raisin est plein d’amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Leur vin est du venin de serpents; c’est le venin mortel des aspics.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Ces choses ne sont-elles pas amassées par moi, ne sont-elles pas scellées parmi mes trésors?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Le jour de la vengeance, je les punirai lorsque leur pied aura glissé; le jour de leur destruction est proche, et ce qui est préparé contre vous est là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Le Seigneur jugera son peuple et sera consolé par ses serviteurs, car il a vu son peuple paralysé, défaillant sous la vengeance divine; ils en sont tout énervés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Et le Seigneur a dit: Où sont leurs dieux, en qui ils ont mis leur confiance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Vous mangiez la graisse de leurs victimes, vous buviez le vin de leurs libations; où sont-ils? Qu’ils se lèvent, qu’ils vous secourent, qu’ils viennent vous abriter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Voyez, voyez que moi, je suis; et il n’y a point de Dieu excepté moi; je donne la mort et la vie, je frappe et je guéris, et nul ne peut délivrer de mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'J’élèverai le bras jusqu’au ciel, et, par ma main droite, je jurerai, et je dirai: Je vis de toute éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'J’aiguiserai mon glaive comme l’éclair, ma main saisira le jugement, je me vengerai de mes ennemis, je punirai ceux qui me haïssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'J’enivrerai mes flèches de sang, je repaîtrai mon glaive des chairs saignantes des morts et des captifs, je le repaîtrai de la cervelle des chefs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Réjouissez-vous, cieux, avec son peuple; que tous les anges de Dieu se prosternent devant lui. Réjouissezvous, nations, avec son peuple, et que tous les fils de Dieu se fortifient en lui, parce que le sang de ses fils a été vengé. Et il se vengera, et il fera justice de ses ennemis, et il punira ceux qui le haïssent. Et le Seigneur purgera la terre de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'En ce jour-là, Moïse écrivit donc ce cantique, et il l’apprit aux fils d’Israël; et Moïse s’approcha, et il fit entendre au peuple toutes les paroles de cette loi, lui et Josué, fils de Nau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Et Moïse acheva de parler à tout Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Et il leur dit: Attachez-vous en votre cœur à tous ces commandements que je vous intime aujourd’hui; prescrivez à vos enfants de les observer et de mettre en pratique toutes les paroles de cette loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Car, ce n’est pas pour vous une loi vaine; cette loi est votre vie, et, à cause de cette loi, vous passerez de longs jours sur la terre au delà du Jourdain, où vous allez entrer pour qu’elle soit votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Et le Seigneur, en ce jour-là, parla à Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Monte sur la cime d’Abarim, montagne du territoire de Nébo qui est en la terre de Moab, vis-à-vis Jéricho, et contemple la terre de Chanaan que je donne aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Et meurs sur la cime où tu seras monté, et réunistoi à ton peuple; de même que ton frère Aaron est mort sur la montagne de Hor, et a été réuni à son peuple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Parce que, comme les fils d’Israël, vous n’avez pas eu foi en ma parole au sujet de l’eau de contradiction à Cadès-Barné, dans le désert de Sin, et parce que vous ne m’avez pas sanctifié devant les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Tu verras devant toi la terre promise, mais tu n’y entreras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Voici les bénédictions que donna Moïse, homme de Dieu, aux fils d’Israël avant sa mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Il dit: Le Seigneur est venu de Sina, et hors de Séir; il s’est manifesté à nous, et il a passé rapidement de la montagne de Pharan à Cadès, avec des myriades d’anges, et ses anges se tenaient à sa droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Et il a épargné son peuple, et tous les saints sont sous sa main; ils sont sous lui, et le peuple a reçu de sa bouche');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'La loi que Moïse vous a prescrite, pour être l’héritage de la synagogue de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Elle sera comme un prince, avec le bien-aimé, tant que tous les princes du peuple seront unis avec les tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Que Ruben vive, qu’il ne meure pas, qu’il soit considérable par le nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Et voici la bénédiction de Juda: Écoutez, Seigneur, la voix de Juda, vous viendriez parmi son peuple; ses mains décideront pour lui, et vous serez son protecteur contre ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Et il dit à Lévi: Donnez à Lévi ses manifestations, donnez à l’homme consacré sa VÉRITÉ; il a été éprouvé par les tentations; au sujet de l’eau de contradiction, il a été injurié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'C’est lui qui dit à son père et à sa mère: Je ne vous ai point vus, et qui ne connaît pas ses frères, et qui ne reconnaît pas ses fils; il garde vos saintes lois, Seigneur, il veille à votre alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Ils déclareront à Jacob vos ordonnances, et à Israël votre loi; ils apaiseront votre colère avec de l’encens; ils placeront des holocaustes sur votre autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Seigneur, bénissez sa force; ayez pour agréables les œuvres de ses mains; brisez les reins des ennemis qui sont près de l’assaillir, et que ceux qui le haïssent n’osent point lever la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Et il dit à Benjamin, bien-aimé du Seigneur: Il a dressé ses tentes avec sécurité, et Dieu, tous les jours, étendra sur lui son ombre, et il s’est reposé entre les épaules de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Et il dit à Joseph: Sa terre est la terre de la bénédiction du Seigneur; c’est la terre des fruits du ciel et de la rosée, et des sources qui jaillissent de l’abîme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Et des récoltes qui mûrissent en leur saison, au gré de la marche du soleil et des phases de la lune,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Soit sur les sommités des premières collines, soit sur les cimes des monts éternels,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'En la saison de la plénitude de la terre. Puissent toutes les grâces de Celui qui s’est manifesté dans le buisson ardent, venir sur la tête de Joseph qui a été glorifié au-dessus de ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Sa beauté est celle du premier-né du taureau, ses cornes sont comme celles de la licorne; avec elles il frappera toutes les nations à la fois, jusqu’aux confins de la terre. Telles seront les myriades d’Ephraïm, tels seront les millions de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Et il dit à Zabulon: Réjouis-toi, Zabulon, par tes excursions, et qu’Issachar se réjouisse sous ses tentes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'On exterminera des nations, et vous y serez appelés, et en ce lieu vous offrirez les sacrifices de justice, et la richesse de la mer et le commerce des habitants du rivage vous allaiteront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Et il dit à Gad: Béni soit celui qui dilate Gad; il s’est reposé comme un lion après avoir broyé les bras et la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Et il a vu ses prémices, parce que, en ce lieu, a été partagée la terre des princes réunis aux chefs du peuple. Le Seigneur a fait justice, et il a été équitable envers Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Et il dit à Dan: Dan, lionceau de lion; il s’élancera de Basan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Et il dit à Nephthali: À Nephthali, plénitude de choses agréables; qu’il soit rempli de la bénédiction du Seigneur; il aura en partage l’Occident et le Midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Et il dit à Aser: Béni soit Aser en ses enfants; il sera agréable à ses frères, il se baignera les pieds dans l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Le fer et l’airain seront sa chaussure; ta force sera comme tes jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Rien n’est comparable au Dieu du bien-aimé; ton protecteur marche sur le ciel, il a toute la magnificence du firmament.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Et la royauté de Dieu t’abritera, et tu seras protégé par la force de ses bras éternels, et, devant ta face, il chassera ton ennemi, et lui dira: Meurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Et Israël sera seul à dresser ses tentes avec sécurité sur la terre de Jacob, au milieu de l’abondance du blé et du vin; pour toi le ciel se couvrira de nuages qui répandront de la rosée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Heureux Israël! quel peuple est semblable à toi, sauvé par le Seigneur? Ton protecteur te placera sous son bouclier; et son épée sera ta gloire; et tes ennemis chercheront à te tromper par leurs mensonges, et tu leur marcheras sur le cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Et Moïse monta, d’Araboth en Moab, sur le mont Nébo, au faîte de la cime de Phasga, qui est en face de Jéricho, et le Seigneur lui montra toute la terre de Galaad jusqu’à Dan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Et toute la terre de Nephthali, et toute la terre d’Ephraïm, et toute la terre de Manassé, et toute la terre de Juda jusqu’à la mer extrême,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Et le désert, et le territoire de Jéricho (ville des Phéniciens), jusqu’à Ségor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Et le Seigneur dit à Moïse: Voici la terre que j’ai promise à Abraham, à Isaac et à Jacob, disant: Je la donnerai à votre race. Je te l’ai fait voir, mais tu n’y entreras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Et Moïse, serviteur du Seigneur, mourut en la terre de Moab, par l’ordre du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Et on l’ensevelit en Haï près du temple de Phogor, et nul jusqu’à ce jour n’a vu son sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Or, Moïse était âgé de cent vingt ans lorsqu’il mourut; ses yeux n’étaient pas obscurcis, sa taille ne s’était point courbée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Et les fils d’Israël pleurèrent Moïse en Araboth de Moab sur le Jourdain, vis-à-vis Jéricho, durant trente jours, et les jours du deuil de Moïse s’écoulèrent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Et Josué, fils de Nau, fut rempli de l’esprit d’ intelligence; car Moïse lui avait imposé les mains. Les fils d’Israël lui obéirent, et ils se réglèrent dans leur conduite sur ce que le Seigneur avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Et il ne s’éleva plus en Israël de prophète comme Moïse, que le Seigneur connut face à face,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Au milieu de tous les signes et prodiges que le Seigneur lui ordonna de faire sur la terre d’Égypte, contre le Pharaon, ses serviteurs et toute sa contrée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Grandes merveilles que, par une main puissante, Moïse opéra devant tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Après la mort de Moïse, le Seigneur parla à Josué, fils de Nau, ministre de Moïse, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Moïse mon serviteur est mort; maintenant donc lève-toi; traverse le Jourdain, toi et tout ce peuple; entre dans la terre que je leur donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Tout coin de terre qu’aura foulé la plante de vos pieds, je vous le donnerai, comme j’ai dit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Je vous donnerai le désert et l’Anti-Liban jusqu’au grand fleuve, le fleuve de l’Euphrate, et la contrée, jusqu’à la dernière mer, qui sera votre limite du côté du couchant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nul homme ne tiendra contre vous durant tous les jours de ta vie; et de même que j’étais avec Moïse je serai avec toi; je ne t’abandonnerai pas, je ne te mépriserai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Sois fort et agis en homme, car c’est toi qui partageras à tout ce peuple la terre que j’ai juré de donner à vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Sois fort et agis en homme, afin d’observer et de pratiquer ce que t’a prescrit Moïse mon serviteur, et ne dévie ni à droite ni à gauche, afin qu’en toutes tes œuvres tu aies l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Les paroles du livre de cette loi seront sans cesse sur tes lèvres; tu méditeras sur elles nuit et jour, pour que tu saches accomplir tout ce qui y est écrit; alors, tu prospéreras; ta voie sera heureuse, et tu auras l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Voilà ce que je te commande: Sois fort et agis en homme; n’aie point de faiblesse, point de crainte, car le Seigneur ton Dieu sera avec toi partout où tu iras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Et Josué donna des ordres aux scribes du peuple, disant Entrez au milieu du camp du peuple, et donnez des ordres au peuple, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Préparez des vivres, parce que dans trois jours vous traverserez le Jourdain, pour prendre possession de la terre que vous donne le Seigneur Dieu de vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Ensuite Josué dit à Ruben, à Gad et à la demitribu de Manassé:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Souvenez-vous de ce que vous a commandé Moïse, serviteur de Dieu, disant: Le Seigneur votre Dieu vous a mis en repos et vous a donné cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Que vos femmes, vos enfants, vos bestiaux, demeurent en la terre qu’il vous a donnée; pour vous, bien armés, vous passerez le fleuve en tête de vos frères, tous ceux du moins qui sont dans la force de l’âge, et vous combattrez avec eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Jusqu’à ce que le Seigneur notre Dieu ait octroyé le repos à vos frères comme à vous-mêmes, et qu’ils aient aussi hérité de cette terre que le Seigneur Dieu leur donne. Alors, vous retournerez chacun à l’héritage que vous a donné Moïse sur la rive orientale du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Et répondant à Josué, ils dirent: Nous ferons tout ce que tu nous prescris, et en tout lieu où tu nous enverras, nous irons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Comme en toutes choses nous obéissions à Moïse, ainsi nous t’obéirons; seulement que le Seigneur notre Dieu soit avec toi de même qu’il était avec Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Celui qui te désobéirait, et qui serait indocile à tes ordres, qu’il meure. Ainsi donc, sois fort et agis en homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Et Josué, fils de Nau, envoya de Sétim deux jeunes gens afin d’explorer la terre, disant: Entrez dans ce pays, voyez-le; voyez Jéricho. Les deux jeunes gens étant partis entrèrent à Jéricho; ils allèrent à la maison d’une femme prostituée dont le nom était Rahab, et ils y logèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Or, des gens en avertirent le roi de Jéricho, et dirent: Deux hommes des fils d’Israël se sont introduits ici, pour nous espionner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Aussitôt, le roi de Jéricho envoya dire à Rahab: Fais sortir les hommes qui sont arrivés en ta maison cette nuit; car ils sont venus pour nous espionner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Mais la femme ayant pris les deux hommes, les cacha; et elle répondit aux émissaires du roi: Des hommes sont venus chez moi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Puis, comme on fermait la porte à l’heure des ténèbres, ces hommes sont partis; je ne sais où ils sont allés; faites les poursuivre; peut-être les prendrez-vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Elle-même cependant les avait fait monter sur la terrasse, et elle les avait cachés sous de la paille de lin, qu’elle y avait amassée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Les hommes se mirent donc à leur poursuite, par la route qui mène au gué du Jourdain, et l’on ferma les portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Lorsqu’ils furent sortis pour les poursuivre, et avant que les jeunes gens fussent endormis, la femme monta vers eux sur sa maison,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Et elle leur dit: Je sais que le Seigneur vous a donné cette terre; et la crainte de vos armes est tombée');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Car nous avons appris de quelle manière le Seigneur Dieu a mis à sec la mer Rouge devant vous, comme vous sortiez de la terre d’Égypte, et tout ce qu’il a fait aux deux rois des Amorrhéens de l’autre rive du fleuve, à Séhon et Og, que vous avez exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Ayant ouï ces choses, la stupeur a bouleversé nos âmes, et, à votre approche, il ne restait plus souffle de vie en aucun de nous, parce que le Seigneur votre Dieu est Dieu, là-haut, dans les cieux, et, ici-bas, sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Or, maintenant jurez-moi, par le Seigneur Dieu, que, comme je vous fais miséricorde, vous ferez miséricorde à la maison de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Épargnez la maison de mon père: ma mère, mes frères, toute ma famille et tout ce qui lui appartient; arrachez à la mort ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Et les hommes répondirent: Notre vie pour ta vie, dussions-nous périr. Aussitôt elle reprit: Lorsque le Seigneur vous aura livré cette ville, vous me ferez justice et miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Puis, elle les fit descendre par la fenêtre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Et elle leur dit: Partez par les montagnes, de peur que ceux qui vous poursuivent ne vous rencontrent; jusqu’à ce qu’ils soient revenus, tenez-vous-y cachés; restez là trois jours, et après cela remettez-vous en route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Alors, les hommes lui dirent: Nous sommes dégagés de ce serment envers toi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Voici comment: dès que nous entrerons sur le territoire de la ville, tu prendras comme signal ce cordon écarlate que tu attacheras à la fenêtre par laquelle tu nous as fait descendre; ensuite tu rassembleras chez toi, dans cette maison, ton père, ta mère, tes frères, toute la famille de ton père et tout ce qui t’appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Quiconque passera le seuil de ta maison, pour en sortir, sera coupable envers lui-même, et nous serons, ά son égard, dégagés de notre serment, qui nous lie envers tous ceux qui resteront avec toi dans ta maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Mais si quelqu’un vient à nous faire tort ou à dévoiler ces paroles que nous te disons, nous serons dégagés de ce serment que nous t’avons prêté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Elle leur répondit: Qu’il soit fait selon ce que vous dites: Puis, elle les renvoya, et ils partirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Ils allèrent dans les montagnes, où ils demeurèrent trois jours; cependant, ceux qui les poursuivaient les cherchèrent par tous les chemins, et ils ne les trouvèrent point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Les deux jeunes gens revinrent sur leurs pas; ils descendirent des montagnes, traversèrent le fleuve, rejoignirent Josué, fils de Nau, et lui racontèrent tout ce qui leur était arrivé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Et ils dirent à Josué: Le Seigneur a livré cette terre à nos mains; tout habitant de cette terre est dans la consternation devant nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Et Josué fut debout de grand matin, et il leva le camp de Sétim. Ils marchèrent jusqu’au Jourdain; et là ils firent halte avant de le traverser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Après trois jours, les scribes parcoururent le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'Ils donnèrent au peuple les ordres de Josué, et dirent Lorsque vous verrez l’arche de l’alliance du Seigneur notre Dieu, et nos prêtres et nos lévites la portant, quittez chacun votre poste et marchez à sa suite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Mais laissez un grand intervalle entre vous et elle, tenez-vous à une distance de deux mille coudées; gardez-vous d’en approcher, afin que vous sachiez la voie que vous devez suivre, car vous n’avez jamais fait semblable chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Et Josué dit au peuple: Sanctifiez-vous pour demain, car demain le Seigneur fera au milieu de vous des merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Et Josué dit aux prêtres: Enlevez l’arche de l’alliance du Seigneur et marchez devant le peuple. Les prêtres enlevèrent donc l’arche de l’alliance du Seigneur, et ils marchèrent devant le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Et le Seigneur dit à Josué: C’est aujourd’hui que je commence à te rehausser aux yeux de tous les fils d’Israël, afin qu’ils sachent que de même que j’étais avec Moïse, je serai avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Et maintenant, donne mes ordres aux prêtres qui portent l’arche de l’alliance; dis-leur: Lorsque vous serez entrés dans les eaux du Jourdain, arrêtez-vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Et Josué dit aux fils d’Israël: Venez ici, écoutez les paroles du Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Vous reconnaîtrez en elles, et en leur accomplissement, que le Dieu vivant est parmi vous, et qu’il exterminera devant votre face le Chananéen, l’Hettéen, l’Hévéen, le Phérézéen, le Gergéséen, le Jébuséen et l’Amorrhéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Voilà que l’arche de l’alliance du Seigneur de toute la terre va traverser le Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Choisissez douze hommes des fils d’Israël, un de chaque tribu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Et ceci arrivera: Lorsque les pieds des prêtres portant l’arche de l’alliance du Seigneur de toute la terre s’arrêteront dans l’eau du Jourdain, l’eau inférieure s’écoulera et les eaux supérieures s’arrêteront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Et le peuple s’éloigna de ses tentes pour traverser le Jourdain; cependant, les prêtres transportèrent, en avant du peuple, l’arche de l’alliance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Mais, au moment où entraient dans le Jourdain les prêtres portant l’arche de l’alliance du Seigneur, au moment où leurs pieds commencèrent à être baignés dans l’eau du fleuve du Jourdain, coulant à pleins bords, puisque c’était le temps de la moisson des froments,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Les eaux supérieures s’arrêtèrent; elles s’arrêtèrent formant une masse compacte et immense, qui s’étendit bien loin, bien loin, jusqu’à Cariathiarim. L’eau qui descendait, s’écoula dans la mer d’Araba ou la mer de Sel, jusqu’à ce qu’il n’en restât plus, et le peuple s’arrêta devant Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Et, pendant que tous les fils d’Israël traversaient à pied sec, les prêtres, qui portaient l’arche de l’alliance du Seigneur, se tinrent immobiles et à pied sec au milieu du fleuve, jusqu’à ce que tout le peuple en eût achevé le passage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Lorsque tout le peuple eut achevé de franchir le Jourdain, le Seigneur parla à Josué, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Prends douze hommes parmi le peuple, un de chaque tribu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Puis, donne-leur cet ordre: Ramassez au milieu du Jourdain douze pierres convenables; transportez-les avec vous, placez-les dans le campement où vous dresserez vos tentes pour cette nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Et Josué, ayant fait venir douze hommes illustres entre les fils d’Israël, un de chaque tribu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Leur dit: Descendez, sous mes yeux, devant l’arche du Seigneur, au milieu du Jourdain, et, après avoir pris là chacun une pierre, apportez-la sur vos épaules, selon le nombre des tribus en Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Afin qu’elles soient pour vous un signe immuable et perpétuel; et que quand à l’avenir ton fils t’interrogera, disant Que signifient pour vous ces pierres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Tu l’expliques à ton fils, et lui dises: Elles nous rappellent que le Jourdain s’est arrêté devant l’arche de l’alliance du Seigneur de toute la terre, lorsqu’elle y a passé; et ces pierres seront un mémorial pour vous, pour les fils d’Israël, jusqu’à la consommation des temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Les fils d’Israël exécutèrent ce que le Seigneur avait prescrit à Josué; après avoir pris du milieu du Jourdain douze pierres, comme le Seigneur le prescrivit à Josué, après que les fils d’Israël eurent achevé le passage du fleuve, ils les emportèrent avec eux dans le camp, et les y déposèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Et Josué plaça douze autres pierres dans le lit même du fleuve, au lieu où étaient les pieds des prêtres qui transportaient l’arche de l’alliance du Seigneur; elles y sont restées jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Car les prêtres qui transportaient l’arche de l’alliance se tinrent immobiles dans le Jourdain, jusqu’à ce que Josué eût exécuté tout ce qu’il avait annoncé au peuple, selon l’ordre du Seigneur; or, le peuple tout entier avait franchi le fleuve;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Et après que le peuple eut achevé le passage, l’arche de l’alliance du Seigneur passa, précédée de ceux qui portaient les pierres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Les fils de Ruben, les fils de Gad et la demi-tribu de Manassé, prêts au combat, avaient passé aussi, en avant des autres fils d’Israël, comme Moïse l’avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Quarante mille combattants de ces tribus traversèrent le fleuve devant le Seigneur, pour combattre sous les murs de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Et ce jour-là, le Seigneur exalta Josué aux yeux de toute la race d’Israël, et ils eurent crainte de lui comme de Moïse, au temps où il vivait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Et le Seigneur parla à Josué, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Ordonne aux prêtres qui portent l’arche du témoignage et de l’alliance, de sortir du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Et Josué commanda aux prêtres, disant: Sortez du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Aussitôt que les prêtres, qui portaient l’arche de l’alliance du Seigneur, eurent quitté le lit du Jourdain et posé leurs pieds sur la rive, l’eau du fleuve reprit impétueusement son cours, et coula à pleins bords, comme auparavant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Le passage du Jourdain eut lieu le dixième jour du premier mois, et les fils d’Israël campèrent en Galgala, à l’orient de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Là, Josué plaça les douze pierres qu’il avait tirées du Jourdain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Et il dit: Lorsque vos fils vous interrogeront, disant: Que signifient ces pierres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Apprenez à vos fils qu’Israël a passé le fleuve à pied sec,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Et que le Seigneur a desséché son lit devant vous, jusqu’à ce que vous l’eussiez traversé, comme il a desséché devant nous la mer Rouge, jusqu’à ce que nous l’eussions passée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Afin que toutes les nations de la terre sachent que la puissance du Seigneur est irrésistible, et qu’en toutes vos œuvres vous honoriez le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Lorsque les rois des Amorrhéens de la rive droite du fleuve, et les rois des Phéniciens de la côte, apprirent que le Seigneur Dieu avait desséché le Jourdain devant les fils d’Israël pendant qu’ils le traversaient, leur intelligence fut paralysée, l’épouvante les saisit, et il ne leur resta pas ombre de prudence devant les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Vers ce temps-là, le Seigneur dit à Josué: Fais-toi des couteaux de pierre tranchante, convoque les fils d’Israël de la seconde génération, et soumets-les à la circoncision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Et Josué fit des couteaux de pierre tranchante, et il circoncit les fils d’Israël, au lieu appelé: les collines des Prépuces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'C’est ainsi que Josué purifia les fils d’Israël: tous ceux qui étaient nés dans le voyage, et tous ceux qui, à la sortie d’Égypte, n’avaient point été circoncis, Josué les circoncit tous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Car, pendant quarante-deux ans, Israël avait erré dans le désert de Mabdaris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'C’est pourquoi la plupart des hommes en état de porter les armes, qui, après la sortie d’Égypte, s’étaient montrés indociles aux ordres du Seigneur, n’avaient point été circoncis; aussi le Seigneur les avait-il condamnés à ne jamais voir la terre que le Seigneur avait juré de donner à leurs pères, terre où coulaient le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Et à ces hommes, le Seigneur substitua leurs fils, ceux que Josué circoncit, parce qu’ils étaient nés pendant le voyage, et n’avaient point été circoncis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Après leur circoncision, ils se tinrent en repos et restèrent dans leur camp jusqu’à ce qu’ils fussent guéris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Et le Seigneur dit à Josué, fils de Nau: J’ai effacé aujourd’hui parmi vous l’opprobre d’Égypte, et le nom de Galgala fut donné à ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Ensuite, les fils d’Israël célébrèrent la pâque le quatorzième jour de la lune, après le coucher du soleil, à l’occident de Jéricho, sur la rive du Jourdain, dans la plaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Ils mangèrent des azymes faits du blé nouveau de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Ce jour-là, il n’y eut plus de manne; dès que les fils d’Israël eurent mangé du grain de cette terre, la manne cessa de tomber pour eux. Ils récoltèrent dans cette année les fruits de la terre des Phéniciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Et comme Josué était dans le pays de Jéricho, voilà que, levant les yeux, il vit devant lui un homme debout, une épée nue à la main. Et Josué l’abordant, lui dit: Es-tu des nôtres, ou de nos ennemis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Et l’homme lui répondit: Je suis le prince de la milice du Seigneur, et je suis venu maintenant près de toi. À ces mots, Josué tomba la face contre terre, et dit: Maître, que commandes-tu à ton serviteur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'L’archange du Seigneur reprit: Ôte la chaussure de tes pieds, car le lieu où tu les poses est saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Cependant, Jéricho était entourée de murs et fermée; et personne n’en sortait, et personne n’y entrait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Et le Seigneur dit à Josué: Voilà que je livre à tes mains Jéricho, son roi et ses hommes puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Fais-la donc investir par tes gens de guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Et voici ce qui sera: Lorsque vous sonnerez de la trompette, que tout le peuple ensemble jette un cri; à ce cri, les murs de la ville s’écrouleront d’eux-mêmes, et le peuple y entrera, chacun se précipitant droit dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Josué, fils de Nau, alla auprès des prêtres, et il leur parla, disant Annoncez au peuple qu’il ait à investir la ville. Que les hommes de guerre, bien armés, marchent devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Que sept prêtres, tenant les sept trompettes sacrées, marchent pareillement devant le Seigneur, et qu’ils sonnent fortement, et que l’arche de l’alliance du Seigneur les suive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Que les hommes de guerre passent devant, et que derrière eux les prêtres, qui suivront l’arche de l’alliance du Seigneur, sonnent de la trompette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Et Josué donna ces ordres au peuple, disant: Ne criez point, que personne n’entende votre voix jusqu’à ce que le Seigneur vous fasse connaître le jour où il faudra crier: alors, vous jetterez un grand cri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Et l’arche de l’alliance de Dieu, ayant fait le tour de laville, rentra aussitôt dans le camp, où elle passa la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Le second jour, Josué se leva de grand matin, et les prêtres transportèrent l’arche de l’alliance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Et les sept prêtres, ceux qui tenaient les sept trompettes, marchèrent devant elle, devant le Seigneur; après eux sortirent les hommes de guerre, puis tout le reste du peuple, derrière l’arche de l’alliance du Seigneur. Et les prêtres sonnèrent de la trompette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Et le reste du peuple fit six fois le tour de la ville, en la serrant de près; puis, on rentra de nouveau dans le camp, et l’on fit la même chose pendant six jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Et le septième jour, de grand matin, le peuple se leva, et ce jour-là il fit sept fois le tour de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Enfin, au septième tour, les prêtres sonnèrent de la trompette, et Josué dit aux fils d’Israël: Criez, car le Seigneur vous a livré la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Elle sera anathème pour le Seigneur des armées, elle et tout ce qu’elle contient, hormis Rahab la prostituée; épargnez cette femme et tout ce que vous trouverez dans sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Cependant, gardez-vous soigneusement de toucher à rien de ce qui est anathème; ne vous laissez pas entraîner à rien prendre de ce qui est anathème, de peur que vous n’attiriez l’anathème sur le camp des fils d’Israël, et que vous ne nous fassiez briser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Tout l’argent, tout l’or, l’airain et le fer, seront consacrés au Seigneur; on les portera dans le trésor du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Alors, les prêtres sonnèrent de la trompette, et dès qu’il ouït les trompettes, le peuple tout entier jeta un cri grand et fort, et le mur de l’enceinte s’écroula de toutes parts, et tout le peuple monta dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Et Josué la frappa d’anathème, elle et tout ce qu’elle renfermait, depuis l’homme jusqu’à la femme, depuis l’enfant jusqu’au vieillard, avec le bétail et les bêtes de somme; tout fut passé au fil de l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Cependant, Josué dit aux deux jeunes hommes qu’il avait envoyés à la découverte: Allez à la maison de la femme, faites-l’en sortir, elle et tout ce qui lui appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Et les deux jeunes hommes, qui avaient été envoyés à la découverte, entrèrent dans la maison de la femme, et ils emmenèrent Rahab, et son père, et sa mère, et ses frères, et toute sa parenté, et tout ce qui lui appartenait, et ils la firent demeurer hors du camp d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'La ville fut consumée par le feu avec tout ce qu’elle renfermait, hormis l’argent, l’or, l’airain et le fer, que l’on transporta dans le trésor du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Et Josué épargna Rahab la prostituée, avec toute la famille de son père; il les fit demeurer au milieu d’Israël jusqu’à ce jour, parce qu’elle avait caché les jeunes hommes que Josué avait envoyés à la découverte dans Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Josué ce jour-là, devant le Seigneur, adjura le peuple, disant: Maudit soit l’homme qui rebâtira cette ville; c’est dans la mort de son premier-né qu’il en jettera les fondations, et dans celle du dernier de ses fils qu’il en posera les portes. Ainsi arriva-t-il à Hozan de Béthel: c’est en perdant Abiron, son premier-né, qu’il jeta les fondations de cette ville, et dans la mort du seul fils qui lui restait, qu’il en posa les portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Or, le Seigneur était avec Josué, et le nom de Josué remplissait toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Mais, les fils d’Israël commirent un grand péché; ils violèrent l’anathème, et Achar, fils de Charmi, fils de Zambri, fils de Zaré, de la tribu de Juda, prit une part de ce qui était anathème; et le Seigneur fut rempli de colère contre les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Josué, à ce moment, envoya des hommes en Haï, qui est vers Béthel, disant: Allez reconnaître Haï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Les hommes montèrent donc, observèrent Haï, retournèrent auprès de Josué, et lui dirent: Ne fais pas monter tout le peuple; que seulement deux ou trois mille hommes partent, et ils réduiront la ville; ne conduis pas là le peuple entier, car ils sont en petit nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Et trois mille combattants environ montèrent; mais, ils s’enfuirent devant les hommes d’Haï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Les hommes d’Haï en tuèrent trente-six; puis, ils les poursuivirent à partir de la porte de la ville, et ils les accablèrent de coups sur les pentes de la colline. Le cœur du peuple en fut frappé d’effroi, et son courage fut comme l’eau qui s’écoule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Josué alors déchira ses vêtements, Josué resta jusqu’au soir devant le Seigneur, la face contre terre, avec les anciens d’Israël, et ils se jetèrent des cendres sur la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Et Josué dit: Je vous conjure, Seigneur, pourquoi votre serviteur a-t-il fait passer le Jourdain à ce peuple pour être livré à l’Amorrhéen et périr? Que ne sommes-nous restés, que ne nous sommes-nous établis sur l’autre rive!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Et que dirai-je, maintenant qu’Israël a tourné le dos devant son ennemi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'À cette nouvelle le Chananéen et tous ceux qui habitent cette terre, vont nous envelopper, et ils nous feront disparaître de leur terre; et alors que ferez-vous pour glorifier votre nom?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Et le Seigneur dit à Josué: Lève-toi pourquoi donc es-tu tombé la face contre terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Le peuple a péché; ils ont violé l’alliance que j’ai faite avec lui, en dérobant, pour la mettre parmi leurs meubles, une part de l’anathème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Les fils d’Israël ne peuvent donc pas résister à leurs ennemis; ils fuiront devant eux, parce qu’ils sont devenus anathèmes. Je ne continuerai plus d’être avec vous, à moins que vous ne retranchiez l’anathème du milieu de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Lève-toi, purifie le peuple, prescris-lui de se purifier pour demain; dis-lui; Voici ce que dit le Seigneur Dieu d’Israël: Un anathème est parmi vous, et vous ne pourrez point résister à vos ennemis jusqu’à ce que vous ayez retranché l’anathème du milieu de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Vous vous rassemblerez tous, par tribus, demain au matin, et il y aura une tribu que désignera le Seigneur; vous ferez avancer chaque famille, et, dans celle que désignera le Seigneur, vous ferez avancer chaque maison, et, dans celle que désignera le Seigneur, vous ferez avancer chaque homme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Et l’homme que désignera le Seigneur, sera consumé par le feu avec tout ce qui lui appartient, parce qu’il a violé l’alliance du Seigneur, et qu’il a commis un péché en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Et Josué, de grand matin, rassembla le peuple par tribus, et la tribu de Juda fut désignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Elle s’avança par familles, et la famille de Zaré fut désignée; elle s’avança homme par homme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Et Achar, fils de Zambri, fils de Zaré, fut désigné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Et Josué dit à Achar: Glorifie aujourd’hui le Seigneur Dieu d’Israël, donne confession à Dieu, et déclaremoi ce que tu as fait; ne me cache rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Or, Achar répondit à Josué, et il lui dit: Véritablement j’ai péché devant le Seigneur Dieu d’Israël. Voici ce que j’ai fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'J’ai vu dans le butin un vêtement bigarré, deux cents sicles d’argent, un lingot d’or du poids de cinquante sicles, et, les ayant convoités, je les ai pris. Je les ai cachés sous ma tente, l’argent au-dessous de tout le reste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Aussitôt, Josué dépêcha des hommes qui coururent à la tente dans le camp; et les objets étaient cachés dans la tente d’Achar, et l’argent au-dessous de tout le reste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Ils les retirèrent de la tente, et les ayant apportés à Josué et aux anciens d’Israël, ils les déposèrent devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Et Josué saisit Achar, fils de Zaré, et il le conduisit à la vallée d’Achor, avec ses fils, ses filles, son bétail, ses bêtes de somme, ses brebis, sa tente et tout ce qui lui appartenait. Tout le peuple le suivit, et il les mena en Emécachor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Là, Josué dit à Achar: Pourquoi nous as-tu perdus? Que de même le Seigneur t’extermine aujourd’hui. Et tout Israël le lapida.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Puis, ils formèrent sur lui un grand monceau de pierres, et le Seigneur apaisa son courroux. À cause de cela, ce lieu, jusqu’à nos jours, s’est appelé Emécachor (Vallée du trouble.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Et le Seigneur dit à Josué: N’aie point de crainte, point de faiblesse; prends avec toi tous les gens de guerre, et monte en Haï: voilà que j’ai livré à tes mains le roi d’Haï et son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Tu feras à Haï ce que tu as fait à Jéricho et à son roi; mais tu prendras pour toi tout le bétail; dresse d’abord une embuscade derrière la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Josué se leva donc et avec lui tous les gens de guerre, afin de marcher sur Haï. Or, Josué choisit trente mille hommes dans la force de l’âge, et il les fit partir pendant la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Et il leur donna des ordres, disant: Placez-vous en embuscade derrière la ville. Ne vous en éloignez pas beaucoup, et tenez-vous prêts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Moi, cependant, et tous ceux qui m’accompagnent, nous nous approcherons des remparts, et il adviendra que quand les habitants d’Haï sortiront à notre rencontre, comme ils l’ont fait récemment, nous fuirons devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Et lorsqu’ils se seront lancés à notre poursuite, nous les attirerons loin de la ville, et ils diront: Ces gens-là fuient devant nous de la même manière que précédemment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Alors, levez-vous, quittez votre embuscade, et entrez dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Faites comme je viens de dire: c’est l’ordre que je vous donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Et Josué les congédia; ils gagnèrent le lieu de l’embuscade, et ils se placèrent entre Béthel et Haï, à l’occident de cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Ensuite, Josué s’étant levé de grand matin, inspecta le peuple; et lui-même, avec les anciens, monta en Haï devant tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Tous les gens de guerre marchèrent à sa suite, et arrivèrent devant la ville du côté de l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Cependant, l’embuscade était à l’occident de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Et dès que le roi d’Haï aperçut Josué et les siens, il se hâta de sortir directement à leur rencontre pour les combattre; car il ne savait pas qu’une embuscade était dressée de l’autre côté de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Josué et Israël le virent, et ils reculèrent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Et les hommes d’Haï poursuivirent les fils d’Israël, et ils s’éloignèrent de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Nul n’était resté dans Haï; tous poursuivaient les fils d’Israël; ils avaient laissé la ville ouverte, et ils s’attachaient aux pas d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Alors, le Seigneur dit à Josué: Étends la main et le javelot, que tu tiens, vers la ville; car je te l’ai livrée. Et les hommes de l’embuscade vont quitter promptement leur place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Et Josué étendit la main et le javelot vers la ville; à ce moment les hommes de l’embuscade sortirent promptement de leur place; ils partirent, ils entrèrent dans la ville, la prirent et se hâtèrent de la livrer aux flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Et les hommes d’Haï, ayant regardé ce qui se passait derrière eux, virent la fumée qui s’élevait de la ville jusqu’au ciel, et ils n’eurent plus de refuge ni d’une part ni de l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Dès que Josué et tout le peuple eurent reconnu que les hommes de l’embuscade avaient pris la ville, et que la fumée de l’incendie s’élevait jusqu’au ciel, ils firent volte-face et frappèrent les hommes d’Haï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Et l’embuscade sortit de la ville à la rencontre de ceux-ci, qui se trouvèrent enveloppés par tous les guerriers du camp, les uns devant eux, les autres sur leurs derrières; ils furent accablés au point que nul ne put fuir; nul ne survécut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Toutefois, l’on prit vivant le roi d’Haï et on le mena devant Josué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Quand les fils d’Israël eurent achevé de tuer tous ceux de Haï qui étaient en plaine, ou qu’ils avaient trouvés sur les pentes de la colline, car ils les poursuivirent tant qu’il en resta, Josué retourna sur la ville et la passa au fil de l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Ce jour-là, douze mille âmes succombèrent, hommes et femmes; tous les habitants de Haï furent tués.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Il ne resta que le butin, réservé aux fils d’Israël, selon l’ordre du Seigneur que leur avait transmis Josué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Et Josué acheva d’incendier la ville; il en fit un tombeau inhabitable à jamais, et resté tel jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Et il suspendit à une croix le roi d’Haï, qu’il y laissa jusqu’au soir. Au coucher du soleil, Josué fit détacher son cadavre, que l’on jeta dans une fosse; puis, on mit sur lui un monceau de pierres qui subsiste encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Lorsque ces nouvelles parvinrent aux rois des Amorrhéens de la rive droite du fleuve, à ceux de la montagne, à ceux du plat pays, à ceux de la côte de la grande mer, à ceux qui avoisinent l’Anti-Liban et aux Hettéens, aux Chananéens, aux Phérézéens, aux Évéens, aux Amorrhéens, aux Gergéséens et aux Jébuséens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Ils se réunirent à la fois pour combattre Josué et Israël. Alors, Josué éleva un autel au Seigneur Dieu d’Israël sur le mont Hébal,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, '(30-31) Selon ce que Moïse, serviteur de Dieu, avait prescrit aux fils d’Israël et qu’il est écrit en la loi de Moïse; cet autel fut construit en pierres brutes que le fer n’avait point travaillées; Josué y posa des holocaustes au Seigneur et des hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, '(32) Et sur les pierres il écrivit le Deutéronome, la loi de Moïse, devant les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, '(33) Alors, tout Israël, ses anciens, les juges et les scribes de l’arche se faisaient face; tandis que les prêtres et les lévites transportaient l’arche de l’alliance du Seigneur. Le prosélyte s’y trouvait avec l’indigène; moitié de cette multitude se tenait près des montagnes de Garizin, l’autre moitié près du mont Hébal, comme l’avait prescrit à la première génération, Moïse, serviteur de Dieu, pour les bénédictions à donner au peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, '(34) Après cela, Josué lut toutes les paroles de la loi, les bénédictions et les malédictions, et tout ce qui est écrit en la loi de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, '(35) Et de tous les ordres de Moïse à Josué, il n’y eut pas une seule parole que celui-ci ne lût aux oreilles de toute l’Église des fils d’Israël, hommes, femmes, enfants et prosélytes qui s’étaient réunis à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, '(4) Eux aussi usèrent d’artifice; ils se pourvurent de vivres, se tinrent prêts et partirent, ayant lié sur leurs épaules de vieux sacs, de vieilles outres de vin déchirées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, '(5) Le tour de leurs chaussures ainsi que leurs sandales étaient usés et rapiécés; leurs vêtements montraient la corde, et le pain de leur approvisionnement était desséché, moisi, rongé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, '(6) Ils vinrent ainsi auprès de Josué, au camp d’Israël en Galgala, et ils dirent à Josué et à Israël: Nous arrivons d’une contrée lointaine, et maintenant faites avec nous une alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, '(7) Aussitôt, les fils d’Israël dirent à l’Horréen: Prenez garde; n’habitez-vous pas notre territoire? En ce cas, comment pourrions-nous faire alliance avec vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, '(8) Mais ils répondirent à Josué: Nous sommes tes esclaves. Et Josué leur dit: D’où êtes-vous? et d’où venez-vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, '(9) Ils reprirent Tes esclaves arrivent d’une contrée très-lointaine, au nom du Seigneur ton Dieu; car nous avons ouï son nom, nous avons appris tout ce qu’il a fait en Egypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, '(10) Et comment il a traité les rois des Amorrhéens qui étaient au delà du fleuve: Séhon, roi des Amorrhéens, et Og, roi de Basan, qui demeurait en Astaroth et en Edraïn.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, '(11) À ces nouvelles, nos anciens et tous ceux qui habitent notre contrée nous ont dit: Prenez avec vous des vivres pour la route, allez à leur rencontre, et dites-leur: Nous sommes vos esclaves, et maintenant faites avec nous une alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, '(12) Voici nos pains qui étaient chauds quand nous nous en sommes approvisionnés, le jour où nous sommes partis pour venir près de vous; ils sont maintenant desséchés et rongés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, '(13) Et ces outres de vin que nous avons remplies neuves, vous les voyez déchirées; cependant, nos vêtements et nos chaussures se sont usés durant notre bien long voyage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, '(14) Alors, les chefs d’Israël prirent de ces provisions, et ils n’interrogèrent point le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, '(15) Josué leur accorda donc la paix; il fit avec eux une alliance qui les préserva de tout dommage, et les chefs de la synagogue leur prêtèrent serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, '(16) Trois jours après la conclusion de l’alliance, on leur apprit que c’étaient des voisins, et qu’ils habitaient leur territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, '(17) Ensuite, les fils d’Israël levèrent leur camp, et eux allèrent à leurs villes; or, leurs villes étaient Gabaon, Caphira, Beroth et Cariathiarim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, '(18) Mais les fils d’Israël ne les combattirent point, parce que tous les chefs leur avaient prêté serment, au nom du Seigneur Dieu d’Israël. Et tout le peuple se prit à murmurer contre les chefs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, '(19) Et les chefs dirent à tout le peuple: Nous leur avons prêté serment au nom du Seigneur Dieu d’Israël, et maintenant nous ne pouvons les toucher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, '(20) Voici ce que nous ferons: accordons-leur la vie et réservons-les, et il n’y aura point contre nous de colère, à cause du serment que nous leur avons prêté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, '(21) Ils vivront et ils seront les fendeurs de bois, les porteurs d’eau de toute la synagogue, comme les chefs le leur ont dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, '(22) Et Josué, les ayant appelés auprès de lui, leur dit: Pourquoi m’avez-vous trompé, disant: Nous sommes très-éloignés de toi; tandis que vous êtes de ceux qui habitent le territoire qui nous appartient?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, '(23) Maintenant, vous voici frappés de malédiction; jamais vous ne cesserez d’être esclaves, fendeurs de bois, porteurs d’eau à mon service et au service de mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 28, '(24) Et ils répondirent à Josué, disant: On nous a rapporté que le Seigneur ton Dieu a prescrit à Moïse, son serviteur, de prendre possession de cette terre et d’exterminer devant vous, nous et tous ceux qui l’habitent; à votre approche, nous avons donc été remplis de crainte pour notre vie, et nous avons fait cette chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 29, '(25) Maintenant, voilà que nous sommes en vos mains; faites de nous ce qui vous sera agréable, ce que vous jugerez à propos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 30, '(26) Or, voilà ce qu’on fit à leur égard: ce jour-là même, Josué les retira des mains des fils d’Israël, et ceux-ci ne les tuèrent point;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 31, '(27) Et ce jour-là même, Josué en fit des fendeurs de bois, des porteurs d’eau pour tout le peuple, et pour l’autel du Seigneur. À cause de cela, les Gabaonites devinrent fendeurs de bois et porteurs d’eau pour l’autel du Seigneur; ils le sont encore de nos jours, et ils doivent servir au lieu qu’aura choisi le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Et lorsque Adonibézec, roi de Jérusalem, ouït dire que Josué, après avoir pris Haï, l’avait détruite, qu’il avait traité cette ville et son roi de la même manière que Jéricho et le roi de Jéricho, et que les Gabaonites s’étaient livrés à Josué et à Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Lui et les siens eurent aussi d’eux une grande crainte; car ils n’ignoraient pas que la ville de Gabaon était grande comme l’une des métropoles, et que tous ses geus de guerre étaient vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Adonibézec, roi de Jérusalem, envoya donc vers Elam, roi d’Hébron, vers Phidon, roi de Jérimuth, vers Jéphré, roi de Lachis, vers Dabin, roi d’Odollam, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Venez, montez près de moi, soyez mes auxiliaires et allons prendre Gabaon, car ses habitants se sont livrés à Josué et aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Et les cinq rois des Jébuséens se mirent en marche, le roi de Jérusalem, le roi d’Hébron, le roi de Jérimuth, le roi de Lachis et le roi d’Odollam, eux et tous leurs peuples, et ils investirent Gabaon, et ils l’assiégèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Alors, les Gabaonites envoyèrent à Josué dans le camp d’Israël, en Galgala, disant: Ne retire pas tes mains de tes serviteurs; monte auprès de nous rapidement; viens à notre secours et délivre-nous. Car tous les rois des Amorrhéens qui habitent la montagne se sont réunis contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Et Josué partit de Galgala, et avec lui tous les gens de guerre, tous les hommes dans la force de l’âge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Et le Seigneur dit à Josué: Ne les crains pas, car je les ai livrés à tes mains, et pas un d’eux ne subsistera devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Josué marcha donc toute la nuit, au sortir de Galgala, et parut devant eux à l’improviste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Et le Seigneur les frappa de stupeur à l’aspect des fils d’Israël; le Seigneur à Gabaon en fit un grand massacre, et Israël les poursuivit par le chemin qui descend le mont Oronin, les taillant en pièces jusqu’à Azéca et Macéda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Pendant qu’ils fuyaient devant les fils d’Israël, sur les pentes du mont Oronin, le Seigneur jeta sur eux, du haut du ciel, des pierres de grêle jusqu’à Azéca, et ces pierres de grêle en tuèrent plus que les fils d’Israël n’en avaient fait périr par le glaive dans le combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Alors, Josué parla au Seigneur, le jour même où Dieu avait livré l’Amorrhéen au bras d’Israël, lorsqu’il les eut accablés en Gabaon, et qu’ils furent écrasés devant les fils d’Israël. Et Josué dit: Que le soleil s’arrête sur Gabaon, et la lune sur le val d’Aïlon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Et le soleil s’arrêta, et la lune se tint en repos, jusqu’à ce que le Seigneur eût tiré vengeance des ennemis. Le soleil resta au milieu du ciel, et il ne s’avança pas du côté de l’occident, durant le cours de toute une journée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Et il n’y eut jamais, avant ou après, pareil jour où le Seigneur écoutât ainsi un homme, parce que le Seigneur combattait avec Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Cependant, les cinq rois s’étaient échappés; ils s’étaient cachés dans la caverne de Macéda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Et des gens en informèrent Josué, disant: On a trouvé les cinq rois cachés dans la caverne qui est en Macéda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Et Josué dit: Roulez des pierres à l’entrée de la caverne, et placez des hommes pour la garder.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Pour vous, ne cessez pas de poursuivre vos ennemis; serrez de près leur arrière-garde, et ne souffrez pas qu’ils entrent dans leurs villes, car le Seigneur Dieu les a livrés à nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Lorsque Josué et les fils d’Israël eurent achevé cet immense carnage, ils s’arrêtèrent enfin, et ceux qui avaient pu fuir se réfugièrent dans leurs places fortifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'De son côté, tout le peuple d’Israël retourna sain et sauf en Macéda, et rejoignit Josué; pas un des fils d’Israël ne souffla mot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Alors, Josué dit: Ouvrez la caverne, faites-en sortir les cinq rois, et me les amenez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Et l’on amena de la caverne les cinq rois: le roi de Jérusalem, le roi d’Hébron, le roi de Jérimuth, le roi de Lachis et le roi d’Odollam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Lorsqu’on les eut amenés devant Josué, il convoqua tout Israël, et il dit aux chefs des combattants, à ceux qui marchaient auprès de lui: Avancez, et mettez-leur le pied sur le cou. Et ils s’avancèrent, et ils mirent le pied sur le cou des cinq rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Et Josué dit aux siens: N’ayez ni crainte ni faiblesse; soyez forts, agissez en hommes, car le Seigneur traitera de même tous les ennemis que vous aurez à combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Puis, Josué tua les rois; il les suspendit à cinq croix, et ils y restèrent jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Vers le coucher du soleil, Josué ordonna de les détacher; on les jeta dans la caverne où ils s’étaient enfuis, et l’on roula devant la caverne des pierres qui y sont encore aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Ce jour-là même, Israël prit Macéda, où il passa au fil de l’épée et extermina tout ce qui avait souffle de vie; nul n’y fut épargné, nul ne s’en échappa; et Israël traita le roi de Macéda comme il avait traité le roi de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Après cela, Josué, et avec lui tout Israël, partirent de Macéda pour Lebna, qu’ils assiégèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Et le Seigneur la livra aux mains d’Israël; ils la prirent, et prirent son roi; ils passèrent au fil de l’épée tout ce qui avait souffle de vie; nul n’y fut épargné, nul ne s’en échappa, et ils traitèrent le roi de Lebna comme ils avaient traité le roi de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Après cela, Josué, et avec lui tout Israël, partirent de Lebna pour Lachis, qu’ils investirent et assiégèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Et le Seigneur livra Lachis aux mains d’Israël; ils la prirent le second jour; ils la passèrent au fil de l’épée, et ils la détruisirent comme ils avaient détruit Lebna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Alors, Elam, roi de Gazer, s’avança au secours de Lachis; mais Josué la passa, ainsi que tout son peuple, au fil de l’épée, au point de ne pas laisser un seul survivant ni un seul fuyard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Après cela, Josué, et avec lui tout Israël, partirent de Lachis pour Odollam, qu’ils investirent et assiégèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Et le Seigneur la livra aux mains d’Israël; il la prit ce jour-là même, et il passa au fil de l’épée tout ce qui avait souffle de vie, comme il avait fait à Lachis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Ensuite, Josué, et avec lui tout Israël, partirent pour Hébron, qu’ils investirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Ils y passèrent au fil de l’épée tout ce qui avait souffle de vie; nul ne fut épargné; comme à Odollam, ils détruisirent la ville et tout ce qu’elle renfermait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Ensuite, Josué, et avec lui tout Israël, se tournèrent sur Dabir, qu’ils investirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Ils la prirent ainsi que son roi et ses bourgades; ils la passèrent au fil de l’épée; ils détruisirent la ville et tout ce qui en elle avait souffle de vie; ils n’y laissèrent pas un seul survivant; ils la traitèrent, elle et son roi, comme ils avaient traité Hébron et le roi d’Hébron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Et Josué frappa toute la contrée montagneuse, et Nageb, et le plat pays, et Asedoth, et leurs rois; il n’y laissa pas un être vivant, il extermina tout ce qui avait souffle de vie, comme le lui avait prescrit le Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Depuis Cadès-Barné jusqu’à Gaza, et Gosom tout entière jusqu’à Gabaon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Josué dévasta de fond en comble toute la terre, et il fit périr ses rois, parce que le Seigneur Dieu d’Israël combattait avec son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'À ces nouvelles, Jabis, rois d’Asor, envoya des messages à Jobab, roi de Maron, au roi de Symoon, au roi d’Asiph,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Aux rois voisins de la grande Sidon, qui habitaient les montagnes et Araba, vis-à-vis Cénéroth, et la plaine et Phenaddor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Aux rois Chananéens de la côte orientale, aux rois Amorrhéens de la côte, aux Hettéens, aux Phérézéens, au Jébuséens, qui habitaient les montagnes, aux Évéens et à ceux qui habitaient sous Hermon dans la contrée de Massyma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Et tous ces peuples sortirent et leurs rois avec eux, semblables par leur multitude au sable de la mer, avec une cavalerie nombreuse et des chars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Et tous leurs rois se réunirent, et ils arrivèrent en même temps vers les eaux de Maron, et ils y campèrent pour combattre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Et le Seigneur dit à Josué: N’aie point de crainte devant eux, car demain, à cette même heure, je te les livrerai; ils fuiront à l’aspect d’Israël; tu couperas les jarrets de leurs chevaux, et tu brûleras leurs chars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Et soudain, Josué avec tous ses hommes de guerre, ayant marché contre eux sur les eaux de Maron, les attaqua dans la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Et le Seigneur les livra aux mains d’Israël. Israël, les taillant en pièces, les poursuivit jusqu’à la grande Sidon, jusqu’à Maseron et jusqu’à la plaine de Massoch du côté de l’orient. Et ils les détruisirent, et ils ne laissèrent pas un seul survivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Josué les traita comme l’avait prescrit le Seigneur: il coupa les jarrets de leurs chevaux, et brûla leurs chars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'En ce temps-là, Josué, revenant sur ses pas, prit Asor et son roi. Or, cette ville était jadis la reine de tous ces royaumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Israël passa au fil de l’épée tout ce qui en elle avait souffle de vie; il extermina tout, il n’y laissa point un être vivant; et il livra Asor aux flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Ensuite, Josué prit toutes les villes capitales, et tous leurs rois, qu’il passa au fil de l’épée; il extermina tous les habitants, comme l’avait ordonné Moïse, serviteur de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Mais Israël n’incendia aucune des villes entourées de remparts; de ces villes, Asor fut la seule incendiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Les fils d’Israël prirent pour eux toutes ses dépouilles; ils passèrent les hommes au fil de l’épée jusqu’à ce qu’ils les eussent tous exterminés; ils n’en laissèrent pas un seul vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Ainsi l’avait prescrit le Seigneur à son serviteur Moïse; ainsi l’avait prescrit Moïse à Josué; ainsi fit Josué, qui n’omit rien des ordres de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Et Josué prit toute la contrée montagneuse, toute la terre de Nageb, toute la terre de Gosom, tout le plat pays, la plaine à l’occident, la montagne d’Israël et les basses terres au pied de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'À partir des monts de Chelcha, il prit aussi le territoire qui monte vers Séir, et celui qui s’étend jusqu’à Balagad, et les plaines situées au pied du Liban, sous le mont Hermon. Il prit tous les rois de ces contrées, il les détruisit, il les extermina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Bien des jours s’écoulèrent pendant que Josué fit la guerre à ces rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Il n’y eut pas une ville qui ne fût prise par Israël; ils les prirent toutes par la force des armes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Parce que (et cela vint du Seigneur) leurs habitants se fortifièrent le cœur et marchèrent contre Israël, afin qu’ils fussent exterminés, qu’on ne leur fit point de quartier, mais qu’ils périssent, comme le Seigneur avait dit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'En ces temps-là, Josué les attaqua, et il fit disparaître Enac de la contrée montagneuse d’Hébron, de Dabir, d’Anaboth, de la montagne d’Israël, et de toutes les montagnes de Juda; Josué les extermina et détruisit leurs villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Et nul de la race d’Enac ne fut épargné par les fils d’Israël, hormis dans Gaza, dans Geth, et dans Aseldo, où il en fut laissé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Et Josué prit toute la terre promise, selon que le Seigneur avait prescrit à Moïse; et Josué la donna pour héritage à Israël en la partageant entre ses tribus. Et la terre fut en repos après les combats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Et voici les rois que firent disparaître les fils d’Israël, et dont la terre devint l’héritage de ces derniers au delà du Jourdain, sur la rive orientale, depuis le val d’Arnon jusqu’au mont Hermon (toute la terre d’Araba, à l’orient):');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Séhon, roi des Amorrhéens, qui demeurait en Esebon et régnait sur tout le pays, depuis Arnon qui est dans la vallée dont elle occupe une partie, et depuis le milieu de Galaad jusqu’à Jaboc, limite des fils d’Ammon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Et sur Araba jusqu’à la rive orientale de la mer de Cénéroth, et jusqu’à la rive orientale de la mer d’Araba (la mer des Sels), vers la route d’Asimoth, à partir de Théman, qui est sous Asedoth-Phasga.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Et le roi de Basan, Og, reste des géants, qui habitait en Astaroth et en Édraïn, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Régnait, depuis le mont Hermon et depuis Secchaï, sur toute la terre de Basan, jusqu’aux confins de Gergési, sur Machis et sur la moitié de Galaad, limitrophe de Séhon, roi d’Esebon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moïse, serviteur de Dieu, et les fils d’Israël détruisirent ces deux rois, et ils donnèrent leurs royaumes en héritage à Ruben, à Gad et à la demi-tribu de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Et voici les rois des Amorrhéens que détruisirent Josué et les fils Israël en deçà du Jourdain, du côté de l’occident, depuis Balagad, dans la plaine au-dessous du Liban, jusqu’aux montagnes de Chelcha qui s’élèvent vers Séir. Et Josué donna leurs royaumes en héritage aux tribus d’Israël en tirant les portions au sort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Dans la montagne, et dans la plaine, et dans Araba, et dans Asedoth, et dans le désert, en Nageb, il détruisit l’Hettéen, l’Amorrhéen, le Chananéen, le Phérézéen, l’Évéen et le Jébuséen,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Le roi de Jéricho, le roi d’Haï qui est près de Béthel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Le roi de Jérusalem, le roi d’Hébron,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Le roi de Jérimuth, le roi de Lachis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Le roi d’Elam, le roi de Gazer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Le roi de Dabir, le roi de Gader,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Le roi d’Hermath, le roi d’Ader,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Le roi de Lebna, le roi d’Odollam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Le roi d’Elath,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Le roi de Taphut, le roi d’Opher,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Le roi d’Ophec d’Aroc, le roi d’Asom, le roi de Symoon, le roi de Mambroth, le roi d’Aziph, le roi de Cadès, le roi de Zachac, le roi de Maredoth, le roi de Jécom du mont Carmel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Le roi d’Odollam de Phennéaldor, le roi de Géi en Galilée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Le roi de Thersa; en tout: vingt-neuf rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Et Josué était vieux, ayant vécu bien des jours, et le Seigneur dit à Josué: Tu as vécu bien des jours, et une grande part de votre héritage est délaissée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Voilà quelle est cette terre qui reste à partager: le territoire des Philistins, Gésiri et le Chananéen,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Depuis le désert qui est devant l’Égypte, jusqu’aux confins d’Accaron, à gauche des Chananéens; elle est comprise dans les cinq principautés des Philistins, savoir: Gaza, Azot, Ascalon, Geth et Accaron, et dans le pays de l’Évéen;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'À partir de Théman, et dans tout le territoire Chananéen qui fait face à Gaza. Il y a encore le territoire des Sidoniens, jusqu’à Aphec et jusqu’aux confins des Amorrhéens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Puis, tout le territoire de Galiath des Philistins, et tout le Liban, depuis ses bases orientales et depuis Galgal, sous le mont Hermon, jusqu’à l’entrée d’Emath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Les habitants de la contrée montagneuse depuis le Liban, jusqu’à Masereth en Memphomaïm, et tous les Sidoniens, je les exterminerai devant Israël. Distribue donc par le sort, aux fils d’Israël, leur territoire ainsi que je te l’ai prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Maintenant, partage toute cette terre depuis le Jourdain, jusqu’à la grande mer de l’occident, et donne-la en héritage aux neuf tribus et à la demi-tribu de Manassé. La grande mer sera sa limite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Moïse a donné la rive orientale du Jourdain aux deux tribus de Ruben et de Gad, et à l’autre demi-tribu de Manassé; Moïse serviteur de Dieu la leur a donnée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Depuis Arœr, qui est sur le bord du torrent d’Arnon; il leur a donné la ville qui est au milieu de la vallée, et tout le territoire de Misor à partir de Médaban,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'Et toutes les villes de Séhon, roi des Amorrhéens, qui régnait en Esebon jusqu’aux confins des fils d’Ammon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Et tout Galaad et les confins de Gésiri et ceux de Machati; tout le mont Hermon et tout Basan jusqu’à Acha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Et tout le royaume d’Og, roi de Basan, qui régnait en Astaroth et en Edraïn; ce dernier était un reste des géants, et Moïse le vainquit, et il le fit mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Les fils d’Israël ne détruisirent ni Gésiri, ni Machati, ni le Chananéen. Et le roi de Gésiri et celui de Machati demeurèrent parmi les fils d’Israël, et y demeurent encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'À la seule tribu de Lévi il ne fut point donné d’héritage. Le Seigneur Dieu d’Israël lui-même est son héritage, comme l’a dit le Seigneur aux lévites. Or, voici le partage que fit Moïse aux fils d’Israël en Araboth des Moabites, sur la rive gauche du Jourdain, en face de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Moïse donna à la tribu de Ruben sa part, selon le nombre des familles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Ses limites comprirent Arœr, qui est sur le bord du torrent d’Arnon, et la ville qui s’élève au milieu de la vallée et tout Misor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Jusqu’à Esebon, avec toutes les villes qui sont en Misor, et Dibon, Bémon-Baal, la maison de Méelboth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Basan, Bacedmoth, Méphaad,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Cariathim, Sébama, Sérada et Sion, sur le mont Enab,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bethphogor, Asedoth-Phasga, Betthasinoth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Et toutes les villes de Misor, et tout le royaume de Séhon, roi des Amorrhéens, que Moïse vainquit avec tous les princes de Madian: Evi, Roboc, Sur, Hur et Rhobé, prince des dépouilles de Sion, et tous les habitants de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Et le devin Balaam, fils de Béor, fut tué au fort du combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Ruben eut le Jourdain pour limite occidentale. Tel fut l’héritage de Ruben par familles, tels furent ses villes et ses villages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Et Moïse donna, par familles, la part de la tribu de Gad,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Dont les limites renfermèrent Jazer, toutes les villes de Galaad, la moitié du territoire des Ammonites, jusqu’à Araba qui est en face d’Arad,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'Le territoire depuis Esebon jusqu’à Araboth, en face de Messapha; Botanim, Maan, jusqu’aux confins de Dibon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Enadom, Othargaï, Benthanabré, Socchotha, Saphan et le reste du royaume de Séhon, roi d’Esebon. Et la rive orientale du Jourdain fut sa limite, jusqu’aux bords de la mer de Cénéreth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Tels furent l’héritage et les villes des fils de Gad, par familles; ils combattirent par familles, puisque leurs villes et leurs villages leur furent distribués par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Et Moïse donna, par familles, la part de la demitribu de Manassé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Dont les limites renfermèrent: le territoire à partir de Maan, tout le royaume de Basan, tout le royaume de Og, roi de Basan, toutes les bourgages de Jaïr qui sont en Basan, soixante villes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Et Moïse donna la moitié de Galaad, plus, en Basan, Astaroth et Edraïn, villes royales du roi Og, aux fils de Machir, fils de Manassé, c’est-à-dire à la moitié des fils de Machir, fils de Manassé, par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Ce sont ceux à qui Moïse, en Araboth de Moab, distribua des héritages sur la rive orientale du Jourdain, en face de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Et voici ceux des fils d’Israël qui eurent en la terre de Chanaan des héritages que leur distribuèrent le prêtre Eléazar, Josué, fils de Nau, et les chefs de famille des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Ils les distribuèrent par la voie du sort aux neuf tribus et à la demi-tribu de Manassé, de la manière que le Seigneur avait prescrite à Josué, à partir de la rive occidentale du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Et parmi eux, Josué ne donna point d’héritage aux lévites,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Attendu que des fils de Joseph étaient issues les deux tribus de Manassé et d’Ephraïm. Et il ne fut point attribué de part aux lévites dans la terre promise, mais des villes pour habitation, et du bétail, et des banlieues, réservées pour leurs bestiaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Les fils d’Israël exécutèrent ce que leur avait prescrit Moïse, et ils partagèrent la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Les fils de Juda vinrent trouver Josué en Galgala, et Caleb, fils de Jéphoné le Cénézéen, lui parla en ces termes: Tu sais la parole qu’a dite le Seigneur à Moïse, homme de Dieu en Cadès-Barné, concernant moi et toimême.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Car j’avais quarante ans, lorsque Moïse, serviteur de Dieu, m’envoya de Cadès-Barné, pour reconnaître cette terre. Et je lui fis un rapport, selon sa pensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Mes frères, ceux qui étaient montés avec moi, firent changer le cœur du peuple; et moi je persistai à suivre le Seigneur mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Ce jour-là, Moïse me fit une promesse, disant: La terre sur laquelle tu as marché sera ton héritage et celui de tes enfants à perpétuité, parce que tu as persisté à suivre le Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Et maintenant, le Seigneur m’a conservé, comme il l’avait dit: Nous sommes dans la quarante-cinquième année depuis le jour où le Seigneur a dit cette parole à Moïse. Or, Israël a erré dans le désert, et aujourd’hui voilà que j’ai quatre-vingt-cinq ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Je suis encore aussi robuste que lorsque Moïse m’a envoyé; j’ai encore la même vigueur à la guerre pour entrer et sortir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Je te demande donc cette montagne, selon ce que ce jour-là m’a promis le Seigneur, parce que ce jour-là, tu as entendu sa promesse. Maintenant voici les villes d’Enac grandes et fortifiées. Si donc le Seigneur est avec moi, j’exterminerai ceux qui les habitent, comme me l’a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Et Josué le bénit, et il donna la ville d’Hébron pour héritage à Caleb, fils de Jéphoné, frère de Cénez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'À cause de cela, Hébron est restée jusqu’à ce jour l’héritage de Caleb, fils de Jéphoné le Cénézéen, pour sa fidélité à suivre les commandements du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Le nom d’Hébron était autrefois Argob; c’était la métropole de la race d’Enac. Et la terre fut en repos après les combats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Et les limites de la tribu de Juda, par familles, s’étendent au midi des confins de l’Idumée et du désert de Sin jusqu’à Cadès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Puis, elles vont du côté du midi jusqu’aux bords de la mer Salée, du côté de la colline qui regarde le midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Et ensuite, elles passent devant les hauteurs d’Acrabin; elles contournent Séna; elles montent au midi de Cadès-Barné, elles sortent d’Asoron et montent à Sérada pour aller à l’occident de Cadès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Et elles sortent de Selmona; puis, elles traversent le pays jusqu’au torrent d’Egypte, et finissent à la mer. Telles sont les limites de Juda du côté du midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'À l’orient, Juda a pour limite toute la mer Salée jusqu’au Jourdain. Et au nord, en partant du Jourdain et des collines de la mer Salée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Ses limites montent vers Béthaglaam; elles passent au nord de Bétharaba; elles montent sur la roche de Béon, fils de Ruben;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Elles côtoient le quart de la vallée d’Achor; elles descendent vers Galgal, qui est en face de la colline d’Adammin au midi de la vallée; elles traversent les eaux de la fontaine du Soleil, elles aboutissent à la fontaine de Rhogel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Elles remontent ensuite la vallée d’Ennom, au-dessus de Jébus, la même que Jérusalem, qu’elles laissent au midi; puis, elles passent sur la cime des monts qui sont au couchant en face de la vallée d’Ennom, et au nord sur les confins de la contrée de Raphaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'De ces sommités, la limite traverse les eaux de la fontaine Naphtho, puis le mont Ephron, d’où elle descend en Baala, la même que Cariathiarim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Elle tourne au sortir de Baala vers l’occident; elle côtoie le mont Assa au nord, au-dessus de la ville d’larin, la même que Chaslon; elle descend vers la Ville du Soleil, qu’elle laisse au nord.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Ensuite, elle passe au nord au-dessus d’Accaron; puis, elle traverse Socchoth; puis, elle incline au midi; puis, elle passe vers Lebna, où elle finit à l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Et à l’occident la tribu de Juda a pour limite la grande mer elle-même. Telles sont les frontières qui entourent la tribu de Juda par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Et à Caleb, fils de Jéphoné, il fut donné une part, au milieu des fils de Juda, par ordre du Seigneur; Josué lui donna la ville d’Arboc, métropole d’Enac, la même qu’Hébron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Et Caleb, fils de Jéphoné, y extermina les trois fils d’Enac Susi, Tholami et Achima.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'De là, Caleb partit pour attaquer les habitants de Dabir, qui était autrefois la Ville des Lettres (Cariath-Sépher).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Et Caleb dit: Celui qui prendra et réduira la Ville des Lettres et s’en rendra maître, je lui donnerai pour femme ma fille Ascha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Et Gothoniel, fils de Cénez, de la famille de Caleb<ref><ref>Son neveu. (Voyez Juges,, 13.), prit la ville, et Caleb lui donna pour femme sa fille Ascha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Pendant qu’elle s’en allait, elle se concerta avec lui, disant: Je demanderai un champ à mon père, et montée sur son âne elle cria, et Caleb lui dit: Qu’as-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Et elle lui dit: Accorde-moi un bienfait; tu m’as donné Nageb, donne-moi en outre un pâturage; et son père lui donna, avec Gonethla haute, Gonethla inférieure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Voici l’héritage de la tribu de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Leurs villes furent près des confins d’Edom, vers le désert Beseléel, Ara et Asor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Icam, Rhegma et Aruel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Cadès, Asorionaïn et Ménam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Balmenan et ses villages,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Et Aseron, nommée aussi Asor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Sen, Salmaa et Molada,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Séri et Béphalath,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Cholaséola, Bersabée, leurs villages et leurs ha');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Bala, Bacoc et Asom,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Elbudad, Béthel et Herma,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Sécelac, Macharim et Séthennac,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Labos, Sala et Eromoth: vingt-neuf villes avec leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Dans la plaine: Astaol, Rhaa et Assa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Rhamen, Tano, Ilouthoth et Méani,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jermuth, Odollam, Membra, Saocho et Jazéca,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Sacarim, Gadera et leurs villages: quatorze villes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senna, Adasan et Magadalgad,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dalad, Maspha et Jacharéel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Basedoth et Idéadaléa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Chabré, Machès et Maachos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Geddor, Bagadiel, Noman et Machédan: seize villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Lebna, Ithac et Anoch,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jana et Nasib,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Céilam, Aciézi, Césib, Bathésar et Elom: dix villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Accaron et ses villages et leurs hameaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Après Accaron, Gemna et toutes les villes qui sont près d’Asedoth et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asiédoth et ses villages et ses hameaux, Gaza et ses villages et ses hameaux, jusqu’au torrent d’Égypte; la grande mer est sa limite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Et dans les montagnes: Samir, Jéther et Socha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Rhenna et la Ville des Lettres, la même que Dabir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anon, Es, Man et Esam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosom, Chalu, Channa et Gélom: onze villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Erem, Rhemna et Soma,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Jemaïm, Béthachu et Phacua,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Eyma, Cariath-Arboc, la même qu’Hébron et Soraïth: onze villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maor, Carmel, Ozib et Itan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jariel, Aricam et Zacanaïm,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Gabaa et Thamnatha: neuf villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Elua, Bethsur et Geddon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Magaroth, Béthanam et Thécum: six villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Théco, Ephrata, la même que Bethleem, Phagor, Etan, Culon, Tatam, Thobès, Carem, Galem, Théther et Manocho: onze villes et leurs villages; Cariath-Baal, la même que Cariathiarim et Sothéba: deux villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Baddargis, Tharabaam et Enon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Et Eochiosa et Naphlazon, et les villes de Sadon et d’Ancadès: sept villes et leurs villages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Or, le Jébuséen habitait Jésusalem, et les fils de Juda ne purent les détruire; les Jébuséens ont ainsi demeuré en Jérusalem jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 64, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'La limite des fils de Joseph part du Jourdain, en face de Jéricho, du côté de l’orient; et de Jéricho, elle monte dans les montagnes désertes de Béthel-Luza;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Elle traverse Béthel et côtoie les confins d’Achatarothi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Puis, elle se rapproche de la mer à partir des confins d’Aptalim, jusqu’aux confins de Béthoron-la-Basse; c’est là qu’elle aboutit à la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Les fils de Joseph, Éphraïm et Manassé, eurent là leur héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Les limites des fils d’Éphraïm s’étendirent en proportion du nombre de leurs familles. La limite de leur héritage passe, du côté de l’orient, par Ataroth et Eroc, jusqu’à Béthoron-la-Haute et à Gazara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Elle aboutit à la mer dans Icasmon, laissant au nord Therma. Du côté de l’orient, elle tourne en Thénasa et en Sellis, et elle passe à l’orient de Janoca,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'De Macho, d’Ataroth et de leurs villages; puis, eile va vers Jéricho et finit au Jourdain,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'De Tapho, elle gagne la mer Salée vers Chelcana, et elle aboutit à cette mer; tel est l’héritage des fils d’Éphraïm par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Les villes qui sont attribuées aux fils d’Éphraïm sont toutes enclavées, ainsi que leurs villages, dans l’héritage des fils de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Les fils d’Éphraïm n’exterminèrent pas le Chananéen qui réside en Gazer; le Chananéen habita cette ville en Ephraïm, jusqu’à ce que vint le Pharaon d’Égypte, qui la prit et l’incendia. Alors, les Égyptiens tuèrent les Chananéens, les Phérézéens et tous les citoyens de Gazer, et le Pharaon la donna en dot à sa fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'L’héritage de la tribu des fils de Manassé, premierné de Joseph, fut donné dans les pays de Galaad et de Basan, d’abord à Machir, premier-né de Manassé, père de Galaad, car c’était un guerrier vaillant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Puis, au reste des fils de Manassé par familles, aux fils de Jézi, aux fils de Célez, aux fils de Jéziel, aux fils de Sichem, aux fils de Symarim et aux fils d’Opher: tels étaient les chefs mâles des familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Or, à Salphaad, fils d’Opher, il n’était point né de fils, mais des filles; et voici les noms des filles de Salphaad: Maala, Nova, Egla, Melcha et Thersa;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Elles comparurent devant Eléazar le prêtre, devant Josué et devant les princes, disant: Notre Dieu a commandé par la voix de Moïse qu’il nous fût donné un héritage, au milieu de nos frères; selon l’ordre du Seigneur, on leur donna donc un héritage parmi les frères de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Les terres qu’on leur distribua étaient du côté d’Anassa et de la plaine de Labec, dans la contrée de Galaad, qui est au delà du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Parce que les filles des fils de Manassé devaient avoir leur part, au milieu de leurs frères, et que la contrée de Galaad appartenait aux fils de Manassé qui étaient restés de l’autre côté du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'La limite des fils de Manassé commence à Délanath, lieu situé vis-à-vis les fils d’Anath; puis, elle s’avance vers Jamin, vers Jassib et vers la fontaine de Taphthoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Tout cela appartient aux fils de Manassé, et Tapheth, sur les limites de Manassé, est aux fils d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Ensuite, la limite descend, du côté du midi, vers le val de Carana, le long du val de Jariel-Téréminthe, qui appartient à Ephraïm, au milieu des villes de Manassé, et la limite de Manassé du côté du nord entre dans le torrent, et elle aboutit à la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'La rive méridionale du torrent appartient à Ephraïm, et la rive septentrionale à Manassé; la mer est la limite de ces derniers; au nord, ils atteignent Aser, et Issachar du côté du levant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Manassé pénètre dans Issachar et dans Aser; il leur prend Bethsan et ses villages, les habitants de Dor et les villages de cette ville, les habitants de Mageddo et les villages de cette ville, enfin, le tiers de Mapheta et les villages de cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Les fils de Manassé n’ont pu détruire ces villes. Et le Chananéen continua d’habiter la contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Lorsque les fils d’Israël, devenus plus puissants, eurent assujetti les Chananéens, quoiqu’ils fussent maîtres de les exterminer, ils les épargnèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Or, les fils de Joseph parlèrent à Josué, disant: Pourquoi ne nous as-tu donné qu’une part, qu’un seul héritage? Je suis un peuple nombreux, et le Seigneur m’a béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Et Josué leur dit: Tu es un peuple nombreux, monte dans la forêt et défriche-la pour toi, si tu es trop à l’étroit sur les montagnes d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Et ils dirent: Les montagnes d’Ephraïm ne nous plaisent point, car le Chananéen qui y demeure à Bethsan et ses villages, dans la vallée de Jesraël, a une cavalerie d’élite et du fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Et Josué dit aux fils de Joseph: Puisque tu es un peuple nombreux et que tu as une grande puissance, tu ne le borneras pas à un seul héritage;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'La forêt t’appartiendra; car il y a là une forêt, tu la défricheras; elle sera à toi, lorsque tu auras exterminé le Chananéen; quoiqu’il ait une cavalerie d’élite, tu es plus fort que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'En ce temps-là, toute la synagogue des fils d’Israël se réunit à Silo; ils y dressèrent le tabernacle du témoignage, et la terre promise était subjuguée par eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Or, il y avait encore sept tribus des fils d’Israël qui ne s’étaient point mises en possession d’un héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Josué dit donc aux fils d’Israël: Jusqu’à quand diffèrerez-vous de partager la terre que vous a donné le Seigneur notre Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Choisissez parmi vous trois hommes par tribu; qu’ils partent, qu’ils parcourent la terre, qu’ils reviennent devant moi me la décrire et me dire comme il convient de la partager.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Et les hommes vinrent près de lui, et il leur fit sept parts, disant: Juda sera leur limite au midi, et les fils de Joseph au nord.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Pous vous, partagez la terre en sept parties et revenez me faire ici votre rapport; ensuite, je vous désignerai vos parts, par la voie du sort, devant le Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Et il n’y aura point de part pour les fils de Lévi parmi vous; car le sacerdoce du Seigneur est leur partage. Quant à Gad, Ruben et la demi-tribu de Manassé, ils ont pris possession de leur héritage sur la rive orientale du Jourdain, telle que le leur a donné Moïse, serviteur de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Les hommes se levèrent pour partir, et Josué leur prescrivit de parcourir toute la terre, disant: Allez, et parcourez la terre, et revenez vers moi, ici en Silo, où je vous désignerai vos parts, par la voie du sort, devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Ils partirent, parcoururent et virent la terre dont ils firent la description en un livre, où ils indiquèrent sept parts, et qu’ils apportèrent à Josué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Celui-ci tira leurs lots au sort à Silo, devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Le lot de la tribu de Benjamin, par familles, fut désigné le premier; Josué leur donna des limites entre les fils de Juda et les fils de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Leur frontière septentrionale, partant du Jourdain, passe derrière Jéricho, au nord; puis, elle s’étend à l’occident, à travers les montagnes, et elle aboutit à Béthon de Mabdara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'De ce lieu, la frontière passe au midi de Luza, la même que Béthel; ensuite, elle descend à Maatarob-Orech, vers les montagnes qui sont au midi de Béthoron-la-Basse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Après cela, elle traverse et côtoie le territoire qui regarde l’occident, et qui part, au midi, des montagnes en face de Béthoron-Sud. Elle aboutit à Cariath-Baal, la même que Cariathiarim, ville des fils de Juda. Tel est le côté de l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Au midi, la limite part du territoire de Cariath-Baal; elle traverse Gasin jusqu’à la fontaine des eaux de Naphtho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Ensuite, elle descend vers le territoire qui est vis-àvis la forêt de Sonnam, située au nord d’Emec-Rhaphaïn; puis à Géenna, passant derrière Jébus au midi; puis, vers la fontaine Rhogel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Ensuite, elle traverse la fontaine Bethsamys;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Puis, elle côtoie Galiloth, qui est en face de la hauteur d’Ethamim; elle descend vers la roche de Béon, fils de Ruben, Elle passe, au nord, derrière Bétharaba, et descend vers la rive septentrionale de la mer Salée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Et elle y finit, au midi de la rive droite du Jourdain. Telle est la frontière méridionale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Le Jourdain est sa limite du côté de l’orient; tel est l’héritage des fils de Benjamin, par familles; telles sont ses limites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Les villes des fils de Benjamin, par familles, sont: Jéricho, Béthégéo, Amécasis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bétharaba, Saré, Bésana,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Eïn, Pharé, Ephratha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Carapha, Céphira, Moni et Gabaa: douze villes avec leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gabaon, Rhama, Béirotha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Massima, Miron, Amocé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Phira, Caphan, Nacan, Sélécan, Tharéila, Jébus, la même que Jérusalem, Gabaoth et Jarin: treize villes et leurs villages; tel est l’héritage des fils de Benjamin, par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Et le lot des fils de Siméon fut désigné le deuxième; leur héritage fut enclavé dans celui des fils de Juda;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Ils eurent pour héritage Bersabée, Samaa, Caladam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Arsola, Bola, Jason,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Erthula, Bula, Herma,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Sicelac, Bethmachéreb, Sarsusim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Et Batharoth et ses champs treize villes et leurs villages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Eremmon, Thalga, Jéther et Asan: quatre villes, et leurs villages');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Qui entourent les villes jusqu’à Balec, en passant au midi de Bameth. Tel est l’héritage des fils de Siméon, par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'L’héritage de la tribu des fils de Siméon fut pris dans celui de Juda, parce que la part de Juda était plus grande que la leur, et l’héritage des fils de Siméon fut enclavé dans leur héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Le lot des fils de Zabulon, par familles, fut désigné le troisième. Leur héritage a pour limites Esédecgola,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'La mer et Magelda; ensuite, la frontière atteint Bétharaba, dans la vallée située en face de Jecman;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Puis, elle revient à Sedduc, du côté de l’orient, en face de Bethsamys, vers les confins de Chaselotheth; elle traverse Dabiroth et elle monte vers Phangaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'De là, elle se contourne, du côté de l’orient, visà-vis Gébéré, vers la ville de Catasem, et elle traverse Rhemmonaa, Matharaoza.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Ensuite, du côté du nord, elle tourne vers Amoth et aboutit à Géphaël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'À Catharath, à Nabaal, à Symoon, à Jéricho et à Bethman..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tel est l’héritage de la tribu des fils de Zabulon, par familles; leurs villes et leurs villages y sont renfermés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Le lot d’Issachar fut désigné le quatrième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Ses limites renferment Jazel, Chasaloth, Sunam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Agim, Siona, Rhéiroth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Anachéreb, Dabiron, Cison, Rhebès,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Emarec, Bersaphès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Et la frontière atteint Gethbor et Salim qu’elle laisse à l’orient, et Bethsamys; elle se termine au Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tel est l’héritage de la tribu des fils d’Issachar, avec leurs villes et leurs villages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Le lot des fils d’Aser, par familles, fut désigné le cinquième..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Ses limites renferment Exéléceth, Aleph, Béthoc, Céaph,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Elimelech, Amiel, Maasa; et vers la mer la frontière atteint le Carmel, Sion et Labanath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Elle rebrousse, à l’orient, par Béthégéneth; elle atteint Zabulon, Engaï et Phthéel, au nord; puis, elle entre en Saphthébethmé et Inaël, et elle traverse Chobamasomel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Elbon, Rhaab, Ememaon, Canthan, jusqu’à la grande Sidon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Ensuite, elle revient dans Rhama et jusqu’à la fontaine de Masphassat, et jusqu’au territoire des Tyriens; puis, elle revient vers Jasiph, et elle aboutit à la mer, à Apoleb, à Echozob,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'À Archob, à Aphec et à Rhaau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tel est l’héritage de la tribu des fils d’Aser, par familles, avec leurs villes et leurs villages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Le lot de Nephthali fut désigné le sixième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Ses frontières renferment Moolam, Mola, Bésémiim, Armé, Naboc, Jepthamé jusqu’à Dodam, et elles aboutissent au Jourdain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Elles reviennent du côté de la mer en Aththabor; de là elles traversent Jacana et atteignent au sud Zabulon, à l’occident Aser, et à l’orient le Jourdain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Elles renferment aussi les villes fortifiées des Tyriens: Tyr, Omathadaceth, Cénéreth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Armeth, Araël, Azor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Cadès, Assari et la fontaine d’Asor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Céroë, Mégalaarim, Beththamé, Thessamys;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tel est l’héritage de la tribu des fils de Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Le lot de Dan fut désigné le septième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Ses frontières renferment Sarath, Asa, et les villes de Sammays,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Salamir, Ammon, Silatha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Thamnatha, Accaron,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Alcatha, Bégethon, Gébéélan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Azor, Banébacat, Géthremmon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Et, à l’occident, Jéracon, près des confins de Joppé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Tel est l’héritage de la tribu des fils de Dan, par familles, avec leurs villes et leurs villages. Et les fils de Dan n’écrasèrent pas l’Amorrhéen qui les assiégeait dans les montagnes; l’Amorrhéen ne leur permettait pas de descendre dans les vallées, et leur ôtait par force une part de leur territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Les fils de Dan se mirent donc en campagne, et ils portèrent la guerre sous les murs de Lachis; ils la prirent, la passèrent au fil de l’épée et l’habitèrent; ils lui donnèrent le nom qu’elle porte, Lasen-Dan. Toutefois, l’Amorrhéen continua de demeurer en Elom et en Salamin. Puis, la main d’Ephraïm s’appesantit sur lui, et il devint tributaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Chaque tribu se mit en marche pour entrer en possession de toute la contrée que renfermaient ses limites. Et les fils d’Israël donnèrent parmi eux un héritage à Josué, fils de Nau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Selon l’ordre de Dieu. Ils lui donnèrent la ville qu’il demanda Thamnasarach, dans la montagne d’Ephraïm. Et il bâtit la ville, et il l’habita.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Telles furent les distributions de terres que firent Eléazar le prêtre, Joseph, fils de Nau, et les chefs de famille des tribus; ils les firent à Silo, par la voie du sort, devant le Seigneur, auprès des portes du tabernacle du témoignage. Et chacun partit pour se mettre en possession de son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 52, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 53, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 54, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Et le Seigneur parla à Josué, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Parle aux fils d’Israël, dis-leur: Donnez les villes de refuge que je vous ai dites par Moïse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Villes de refuge pour le meurtrier qui involontairement aura frappé à mort; ces villes seront pour vous des refuges, et le meurtrier ne sera point tué par le vengeur du sang, avant d’avoir comparu en jugement devant la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Josué désigna donc Cadès, en Galilée, dans les montagnes de Nephthali; Sichem, dans les montagnes d’Éphraïm; la ville d’Arboc, la même qu’Hébron, dans les montagnes de Juda. ́');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Et au delà du Jourdain, il désigna Bosor dans le désert, dans la plaine de la tribu de Ruben; Arémoth, en Galaad, de la tribu de Gad, et, dans le royaume de Basan, Gaulon, de la tribu de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Telles sont les villes qui furent choisies pour les fils d’Israël, et pour le prosélyte résidant parmi eux, afin de servir de refuge à tout homme qui porterait involontairement un coup mortel, et afin qu’il ne pérît pas, de la main du vengeur de sang, avant d’avoir comparu en jugement devant la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Et les chefs de famille des fils de Lévi allèrent trouver Eleazar le prêtre, Josué, fils de Nau, et les chefs de famille des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'Ils leur parlèrent, en Silo, dans la terre de Chanaan, disant: Le Seigneur a ordonné à Moïse de nous donner des villes à habiter et leurs banlieues, pour notre bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'En conséquence, les fils d’Israël donnèrent aux lévites pour les posséder en héritage, selon l’ordre du Seigneur, des villes avec leurs banlieues;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Le lot de la famille de Caath fut désigné le premier, et les fils d’Aaron, prêtres et lévites, eurent treize villes des tribus de Juda, de Siméon et de Benjamin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Le reste des fils de Caath eut dix villes des tribus d’Ephraïm, et de Dan et de la demi-tribu de Manassé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Le lot des fils de Gerson fut ensuite désigné; ils eurent treize villes des tribus d’Issachar, d’Aser et de Nephthali et de la demi-tribu de Manassé, au delà du Jourdain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Le lot des fils de Mérari, par familles, fut désigné; ils eurent douze villes des tribus de Ruben, de Gad et de Zabulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Les fils d’Israël donnèrent aux lévites, par le sort, ces villes avec leurs banlieues, comme le Seigneur l’avait prescrit à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'La tribu de Juda, celle de Siméon et une part de celle de Benjamin, livrèrent ces villes, et elles furent possédées');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Par les fils d’Aaron, de la famille de Caath, de la tribu de Lévi, parce que le sort les leur avait assignées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'On leur donna aussi Cariath-Arboc, métropole des fils d’Enac, la même qu’Hébron dans les montagnes de Juda, et la banlieue qui l’entoure;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Quant aux champs de la ville et à ses villages, Josué les avait donnés en pleine possession aux fils de Caleb, fils de Jéphoné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Aux fils d’Aaron, il donna cette ville d’Hébron, comme ville de refuge pour les meurtriers, avec toutes les dépendances qui y étaient attachées; il leur donna aussi Lemna et ses dépendances;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Elom et ses dépendances, Téma et ses dépendances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Gella et ses dépendances, Dabir et ses dépendances, Bethsamys et ses dépendances: neuf villes des deux tribus de Juda et de Siméon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Asa et ses dépendances, Tana et ses dépendances;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Ils eurent, de la tribu de Benjamin, Gabaon et ses dépendances, Gatheth et ses dépendances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathoth et ses dépendances, Gamala et ses dépendances quatre villes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'En tout treize villes pour les prêtres, fils d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Les familles des fils de Caath, le reste des lévites issus de Caath eurent d’abord la ville des prêtres dans la tribu d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'On leur donna Sichem, la ville de refuge pour les meurtriers, avec ses dépendances; ils eurent, en outre, Gazara, sa banlieue et ses dépendances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Et les deux Béthoron avec leurs dépendances: quatre villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Ils eurent encore, de la tribu de Dan, Helcotaïm et ses dépendances, Géthédan et ses dépendances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Elon et ses dépendances, Géthéremmon et ses dépendances: quatre villes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Et, de la demi-tribu de Manassé, Tanach et ses dépendances, et Jébada et ses dépendances: deux villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'En tout dix villes et leurs dépendances pour le reste des fils de Caath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Aux lévites, fils de Gerson, il fut donné, de l’autre demi-tribu de Manassé, la ville assignée aux meurtriers, Gaulon, dans le royaume de Basan, avec ses dépendances, et Bosora avec ses dépendances: deux villes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'De la tribu d’Issachar Cison et ses dépendances, Debba et ses dépendances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Remmath et ses dépendances, et la Fontaine des Lettres, avec ses dépendances: quatre villes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'De la tribu d’Aser: Basella avec ses dépendances, et Dabbon avec ses dépendances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Chelcat avec ses dépendances, et Rhaab avec ses dépendances: quatre villes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'De la tribu de Nephthali, la ville de refuge Cadès en Galilée et ses dépendances, Nemmath et ses dépendances, et Themmon avec ses dépendances: trois villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'En tout pour les fils de Gerson, par familles, treize villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'À la famille des fils de Mérari, au reste des lévites, il fut donné de la tribu de Zabulon, Maan et sa banlieue, Cadès et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Sella et sa banlieue: trois villes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Et au delà du Jourdain, en face de Jéricho, de la tribu de Ruben, la ville de refuge Bosor, dans le désert, la même que Miso et sa banlieue, Jazer et sa banlieue, Decmon et sa banlieue, Mapha et sa banlieue: quatre villes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'De la tribu de Gad, la ville de refuge Ramoth en Galaad et sa banlieue, Camin et sa banlieue, Esebon et sa banlieue, Jazer et sa banlieue en tout quatre villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Telles sont toutes les villes données par familles, au reste des lévites, aux fils de Mérari, et leur nombre fut limité à douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Les lévites eurent ainsi, au milieu des possessions des fils d’Israël, quarante-huit villes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Et leurs banlieues; ils eurent chaque ville avec sa banlieue, et toutes ces villes étaient entourées de banlieues. Josué eut alors achevé de visiter la terre promise, et d’assigner à chacun ses limites. Or, les fils d’Israël avaient fait la part de Josué, selon l’ordre du Seigneur. Ils lui avaient donné la ville qu’il avait demandée, Thamnasachar, dans les montagnes d’Ephraïm; il l’avait bâtie et il l’habitait. Josué y recueillit les couteaux de pierre avec lesquels il avait circoncis les fils d’Israël nés pendant le voyage dans le désert; il les déposa en Thamnasachar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'C’est ainsi que le Seigneur donna à Israël toute la terre qu’il avait promis à leurs pères de leur donner, ils en prirent possession et ils l’habitèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Et le Seigneur, comme il l’avait promis à leurs pères, rétablit la paix tout alentour; de tous leurs ennemis, nul ne se souleva contre eux. Le Seigneur avait livré tous leurs ennemis à leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Aucune des bonnes paroles que le Seigneur avait dites aux fils d’Israël ne tomba à terre; toutes furent vérifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Alors, Josué convoqua les fils de Ruben, les fils de Gad et la demi-tribu de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Et il leur dit: Vous avez obéi à tout ce que vous avait ordonné Moïse, serviteur de Dieu; vous avez été dociles à ma voix, quand je vous ai rappelé tout ce qu’il vous avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Vous n’avez point abandonné vos frères, durant tous ces jours nombreux, et jusqu’à ce moment vous avez exécuté l’ordre du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Or, maintenant le Seigneur notre Dieu a donné la paix à nos frères, comme il le leur avait promis. Partez donc, retournez en vos demeures et dans la terre que Moïse vous a assignée au delà du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Mais veillez diligemment à mettre en pratique les commandements et la loi que Moïse, serviteur de Dieu, vous a ordonné de pratiquer, savoir: d’aimer le Seigneur votre Dieu, de marcher en toutes ses voies, d’observer ses commandements, de vous attacher étroitement à lui, de le servir de tout votre esprit et de toute votre âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Et Josué les bénit, les congédia, et ils retournèrent en leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, '(Moïse avait donné des terres à la demi-tribu de Manassé dans le royaume de Basan, et Josué en avait donné à l’autre demi-tribu parmi leurs frères de ce côté du Jourdain à l’occident.) Lorsque Josué les renvoya dans leurs demeures, et qu’il les bénit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Ils retournèrent en leurs demeures avec beaucoup de richesses. Ils avaient partagé avec leurs frères un immense butin fait sur les ennemis: de nombreux troupeaux de bétail, de l’argent, de l’or et du fer, et beaucoup de vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Les fils de Ruben, les fils de Gad et la demi-tribu de Manassé se séparèrent donc des fils d’Israël à Silo, dans la terre de Chanaan, pour retourner en Galaad, dans la contrée qu’ils possédaient, et que le Seigneur, par la main de Moïse, leur avait donnée pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Et ils arrivèrent en Galaad sur le Jourdain, qui est dans la terre de Chanaan. Et les fils de Ruben, les fils de Gad et la demi-tribu de Manassé bâtirent en ce lieu, sur la rive du Jourdain, un grand autel qu’on apercevait de loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Or, les fils d’Israël l’apprirent de gens qui leur dirent Voilà que les fils de Ruben, les fils de Gad et la demi-tribu de Manassé, ont bâti un autel sur les confins de la terre de Chanaan, en Galaad aux bords du Jourdain, hors du territoire des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Aussitôt, tous les fils d’Israël se rassemblèrent en Silo, pour s’en aller leur faire la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Et les fils d’Israël envoyèrent aux fils de Ruben, aux fils de Gad, et aux fils de la demi-tribu de Manassé, en la terre de Galaad, Phinées, fils d’Eléazar, fils d’Aaron le grand prêtre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Et avec lui dix chefs, chacun chef d’une famille paternelle de toutes les tribus d’Israël; ces chefs de famille, en Israël, sont commandants de mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Ils se rendirent auprès des fils de Ruben, des fils de Gad et de la demi-tribu de Manassé, en la terre de Galaad, et ils leur parlèrent, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Toute la synagogue du Seigneur dit ces choses: Quel est ce péché que vous avez commis devant le Dieu d’Israël, en vous détournant aujourd’hui du Seigneur, et en vous bâtissant un autel, pour être des apostats du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Est-ce si peu de chose à vos yeux que le crime de Phogor dont nous ne sommes pas encore purifiés, et qui a été une plaie dans la synagogue du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Et vous, vous vous détournez du Seigneur; or, si vous vous en détournez aujourd’hui, demain sa colère éclatera contre tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Mais quoi! la terre que vous possédez est-elle trop petite? Passez dans la terre que possède le Seigneur, dans celle où est dressé le tabernacle du Seigneur; venez la partager avec nous, et ne vous détournez pas du Seigneur; ne soyez pas apostats du Seigneur en élevant un autel autre que l’autel du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'N’avez-vous pas vu Achar, fils de Zaré, quand il a péché au sujet de l’anathème? La colère du Seigneur n’a-t-elle pas éclaté contre tout Israël? A-t-il péri seul à cause du péché que lui seul avait commis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Les fils de Ruben, les fils de Gad et la demi-tribu de Manassé, répondirent aux chefs d’Israël, et ils dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Dieu est le Seigneur Dieu, et Dieu, Dieu lui-même sait, et toute la synagogue d’Israël saura si nous avons commis contre le Seigneur le péché d’apostasie; si cela est, qu’il cesse dès ce jour de nous protéger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Si nous avons bâti pour nous un autel en esprit d’apostasie contre le Seigneur notre Dieu, pour brûler sur cet autel des holocaustes, y offrir des hosties pacifiques, le Seigneur se vengera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Mais nous avons fait cela par précaution, de peur que plus tard vos enfants ne disent aux nôtres: Qu’y a-t-il entre vous et le Dieu d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Le Seigneur vous a séparés de nous par le Jourdain, et vous n’avez point part au Seigneur. Ainsi, vos fils repousseront nos fils comme des étrangers, pour qu’ils n’honorent point le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Nous avons donc résolu d’élever cet autel, non pour y faire des oblations, non pour y sacrifier des victimes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Mais pour qu’il soit entre vous et nous, entre votre postérité et la nôtre, un témoignage du culte que nous rendrons au Seigneur devant son tabernacle, par nos oblations de fruits, nos victimes et nos hosties pacifiques; de sorte que plus tard vos enfants ne disent point aux nôtres: Vous n’avez point part au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Et nous avons dit: S’il arrive un jour qu’ils tiennent ce langage à nous ou à notre postérité, il leur sera répondu Voyez cette image de l’autel du Seigneur que nos pères ont faite, non pour y offrir des fruits ou des victimes, mais pour qu’elle soit un témoignage entre vous et nous et entre nos fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Que Dieu nous préserve donc aujourd’hui de nous détourner du Seigneur, d’être apostats du Seigneur, au point de bâtir pour nous un autel d’holocaustes et d’hosties pacifiques, autre que l’autel du Seigneur qui existe devant son tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Après avoir entendu les explications des fils de Ruben, des fils de Gad et de la demi-tribu de Manassé, Phinées le prêtre, et les chefs de la synagogue d’Israël en furent réjouis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Et Phinées le prêtre dit aux fils de Ruben, aux fils de Gad et à la demi-tribu de Manassé: Nous reconnaissons maintenant que le Seigneur est avec vous, parce que vous n’avez point commis de péché contre le Seigneur, et que vous sauvez les fils d’Israël de la main du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Et Phinées le prêtre, et les chefs, quittant les fils de Ruben, les fils de Gad et la demi-tribu de Manassé, retournèrent de la terre de Galaad en celle de Chanaan auprès des fils d’Israël, et ils leur rapportèrent tout ce qui s’était dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Et cela réjouit les fils d’Israël; et, après leur avoir parlé, ils bénirent tous le Dieu des fils d’Israël, et ils renoncèrent à marcher contre eux en guerre, et à ravager le domaine des fils de Ruben, des fils de Gad et de la demi-tribu de Manassé, qui continuèrent de l’habiter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Et Josué appela l’autel des fils de Ruben, des fils de Gad et de la demi-tribu de Manassé: Autel du témoignage, parce que, dit-il, il rend entre eux témoignage que le Seigneur est leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Et bien des jours s’étaient écoulés après que le Seigneur avait donné le repos à Israël; les ennemis qui l’entouraient étaient désarmés. Josué était vieux, et avait vécu bien des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Et Josué convoqua tous les fils d’Israël, leurs anciens, leurs chefs, leurs juges, leurs scribes, et il leur dit: Je suis vieux, j’ai vécu bien des jours,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Et vous avez vu comment le Seigneur notre Dieu a traité toutes ces nations devant vous, parce que le Seigneur lui-même a combattu pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Vous voyez que je vous ai soumis ce qui reste de toutes ces nations parmi vous, sur les territoires de vos tribus; je les ai exterminées entre le Jourdain et la grande mer qui sera votre limite à l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Le Seigneur votre Dieu lui-même continuera de les exterminer devant vous, jusqu’à ce qu’elles soient toutes détruites; il enverra contre elles des bêtes farouches, tant qu’il ne les aura pas exterminées devant vous, elles et leurs rois; vous hériterez de leurs terres, comme l’a dit le Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Efforcez-vous donc avec zèle de garder et de pratiquer tout ce qui est écrit au livre de la loi de Moïse, afin de ne vous en écarter ni à droite ni à gauche;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Afin de ne vous point mêler à ces nations qui existent encore. Que le nom de leurs dieux ne soit jamais prononcé parmi vous; gardez-vous de les servir ou de les adorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Mais restez fortement attachés au Seigneur notre Dieu, comme vous l’avez été jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Et le Seigneur exterminera, devant votre face, ces nations grandes et puissantes; nulle, jusqu’à ce jour, n’a tenu devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Un seul de vous a mis en fuite mille hommes, parce que le Seigneur notre Dieu lui-même a combattu pour vous, comme il vous l’a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Et vous veillerez diligemment à aimer le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Car, si vous vous détournez de lui, si vous vous joignez aux nations qui sont restées parmi vous, si vous contractez chez elles des mariages, si vous vous mêlez à elles et elles à vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Vous reconnaîtrez que le Seigneur ne continuera plus d’exterminer ces nations devant votre face. Et pour vous, elles seront des filets, des piéges, des clous sous vos pieds, et des flèches dans vos yeux, jusqu’à ce que vous soyez effacés de cette terre fortunée que vous a donnée le Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Pour moi, je m’en vais à grands pas sur le chemin de la vie, comme font ceux qui sont sur la terre. Et vous, vous reconnaîtrez, en vos cœurs et en vos âmes, que nulle parole n’est tombée à terre de toutes celles qu’a prononcées le Seigneur notre Dieu sur tout ce qui vous concernait, et qu’il n’en a laissé aucune en arrière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Or, de même que toutes les bonnes paroles du Seigneur se sont accomplies pour vous, de même le Seigneur sera fidèle à toutes ses menaces, jusqu’à ce qu’il vous ait effacés de cette terre fortunée que vous a donnée le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Si vous violez l’alliance du Seigneur notre Dieu que lui-même vous a donnée pour loi, si vous vous en allez servir d’autres dieux et les adorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Josué rassembla toutes les tribus d’Israël en Silo; il convoqua leurs anciens, leurs scribes, leurs juges, et il les plaça devant Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Et Josué dit à tout le peuple: Voici ce que dit le Seigneur Dieu d’Israël Nos pères, dans les premiers temps, et Tharé, père de Nachor, ont demeuré au delà du fleuve, et ils ont servi des dieux étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Et j’ai pris votre père Abraham, au delà du fleuve, je l’ai amené en cette terre; j’ai multiplié sa race, je lui ai donné Isaac, et à Isaac, j’ai');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Donné Jacob et Esau; j’ai donné à Esau pour héritage la montagne de Séir. Or, Jacob et ses fils sont descendus en Égypte, et ils sont devenus en ce pays une nation grande, nombreuse et puissante. Les Égyptiens les ont opprimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Mais, j’ai frappé l’Égypte avec les miracles que j’ai faits au milieu d’elle;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Et après cela, Dieu a fait sortir vos pères de l’Égypte; vous êtes entrés dans la mer Rouge; les Égyptiens y ont poursuivi vos pères avec des chars et des chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Et nous avons crié au Seigneur, et il a placé une nuée sombre entre nous et les Égyptiens, et il a ramené sur eux les eaux de la mer, et il les en a couverts. Vos yeux ont vu tout ce que le Seigneur a fait en Égypte, et vous êtes restés bien des jours dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Enfin, le Seigneur nous a conduits en la terre des Amorrhéens qui demeuraient sur l’autre rive du Jourdain, et il nous les a livrés; vous avez pris possession de leur territoire, et vous les avez exterminés devant votre face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'En ce temps-là, Balac, fils de Séphor, roi de Moab, s’est levé, et il s’est rangé en bataille contre Israël; et il a envoyé chercher Balaam pour qu’il vous maudît.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mais le Seigneur, qui ne voulait point vous perdre, nous a bénis, et il nous a tirés de leurs mains, et il nous les a livrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Ensuite, vous avez traversé le Jourdain et vous êtes arrivés à Jéricho; les habitants de Jéricho, l’Amorrhéen, le Chananéen, le Phérézéen, l’Évéen, le Jébuséen, l’Héttéen et le Gergéséen, vous ont résisté; le Seigneur les a livrés à vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Il a lancé avant vous des essaims de guêpes, et il a chassé devant vous douze rois des Amorrhéens, non par votre glaive, non par vos flèches;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Il vous a donné une terre que vous n’aviez point labourée, et des villes que vous n’aviez point bâties, dont vous avez fait vos demeures. Il vous a donné des vignes et des oliviers que vous n’aviez point plantés, dont vous avez mangé les fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Maintenant donc, craignez le Seigneur; servez-le en toute droiture et justice. Faites disparaître les dieux étrangers qu’ont servis vos pères au delà de l’Euphrate ou en Égypte, et servez le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Si cependant il ne vous est point agréable de servir le Seigneur, choisissez-vous dès aujourd’hui quelque dieu à servir, soit parmi ceux de vos pères au delà de l’Euphrate, soit parmi ceux des Amorrhéens dont vous habitez la terre. Pour moi et ma maison, nous servirons le Seigneur, parce qu’il est saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Et le peuple répondant, dit: Dieu nous préserve d’abandonner le Seigneur pour servir d’autres dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Le Seigneur notre Dieu est le seul Dieu. C’est lui qui a fait sortir d’Égypte nous et nos pères, et qui nous a gardés tout le long de la voie que nous avons suivie, et au milieu de toutes les nations que nous avons traversées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Et le Seigneur a chassé devant notre face l’Amorrhéen et toutes les nations qui habitaient la terre. Nous servirons donc le Seigneur, car il est notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Et Josué dit au peuple: Vous ne pourrez point servir le Seigneur: car c’est un Dieu saint; c’est un Dieu jaloux, et il ne tolèrera point vos péchés ni vos iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Dès que vous abandonnerez le Seigneur et que vous servirez d’autres dieux, il fondra sur vous pour vous punir, et il vous accablera de maux au lieu du bien qu’il vous a fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Et le peuple dit à Josué: Non, non; nous servirons le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Et Josué dit au peuple: Vous êtes vous-mêmes témoins entre vous que vous avez choisi le service du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Et maintenant, faites disparaître les dieux étrangers que vous avez parmi vous, et dirigez vos cœurs vers le Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Et le peuple dit à Josué: Nous servirons le Seigneur, et nous serons dociles à sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Ce jour-là, Josué fit alliance avec le peuple, et il lui donna la loi et le jugement en Silo, devant le tabernacle du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Et il écrivit toutes ces paroles dans le livre des lois de Dieu; il prit une grande pierre, et il la dressa, sous le térébinthe, devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Et Josué dit au peuple. Voyez cette pierre; elle portera parmi vous témoignage; elle a entendu tout ce qui vient d’être dit ici par le Seigneur; car c’est lui qui vous a parlé aujourd’hui, et cette pierre portera parmi vous témoignage jusqu’aux derniers des jours, lorsque vous viendrez à mentir au Seigneur mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Josué alors congédia le peuple, et chacun se rendit à sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Israël servit donc le Seigneur durant tous les jours de Josué, et durant tous les jours des anciens dont la vie s’était prolongée avec la sienne, et qui avaient vu toutes les œuvres du Seigneur en faveur d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Après ces choses, Josué, fils de Nau, serviteur de Dieu, mourut âgé de cent dix ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'On l’ensevelit sur les limites de son héritage, en Thamnasarach, dans les montagnes d’Ephraïm, au nord des montagnes de Galaad. Et lorsqu’on l’eut déposé là dans son sépulcre, on y plaça près de lui les couteaux de pierre avec lesquels il avait circoncis les fils d’Israël en Galgala, comme l’avait prescrit le Seigneur, lorsqu’il les eut amenés de l’Égypte; et les couteaux y sont encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Les fils d’Israël avaient rapporté de l’Égypte les ossements de Joseph, et ils les inhumèrent à Sichem dans le champ que Jacob avait acheté au prix de cent agneaux, des Amorrhéens qui habitaient Sichem, et qu’il avait donné à Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Ensuite, Eléazar, fils d’Aaron le grand prêtre, mourut, et il fut enseveli en Gabaar, qu’il avait donnée à Phinées, dans la montagne d’Ephraïm. Ce jour-là, les fils d’Israël, ayant pris l’arche de Dieu, la transportèrent dans leurs rangs. Et Phinées fut prêtre à la place de son père Eléazar, jusqu’à ce que lui-même mourût et fût inhumé dans sa terre de Gabaar. Et les fils d’Israël retournèrent chacun en son lieu et dans sa ville, et ils adorèrent Astarté, Astaroth et les dieux des nations qui les entouraient. Et le Seigneur les livra aux mains d’Eglom, roi de Moab, qui les tyrannisa pendant dix-huit ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Il advint, après la mort de Josué, que les fils d’Israël consultèrent le Seigneur, disant: Quel chef nous conduira contre les Chananéens pour les combattre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Et le Seigneur dit: Juda marchera; voilà que j’ai mis en sa main la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Et Juda dit à Siméon, son frère: Viens avec moi sur mes terres, et nous livrerons bataille aux Chananéens, ensuite j’irai avec toi sur ton territoire. Et Siméon marcha avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Juda partit donc, et le Seigneur livra à ses mains le Chananéen et le Phérézéen; il les tailla en pièces à Bézec au nombre de dix mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Après avoir surpris à Bézec Adonibézec, ils lui livrèrent bataille, et taillèrent en pièces le Chananéen et le Phérézéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Adonibézec prit la fuite, ils coururent après lui, l’atteignirent et lui coupèrent les extrémités des pieds et des mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Alors, Adonibézec dit: Soixante-dix rois à qui j’avais fait couper les extrémités des pieds et des mains ont ramassé ce qui tombait sous ma table. Dieu m’a donc traité comme j’ai traité autrui. Et ils le conduisirent à Jérusalem, où il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Et, les fils de Juda assiégèrent Jérusalem; ils la prirent, ils passèrent les habitants au fil de l’épée, et ils incendièrent la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Après cela, les fils de Juda descendirent pour combattre le Chananéen qui habitait les montagnes du midi et la plaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Et Juda marcha contre le Chananéen qui habitait Hébron, et tout Hébron sortit à sa rencontre; le nom d’Hébron était autrefois Cariath-Arboc-Sépher; Juda vainquit Sessi, Achiman et Tholmi, de la race d’Enac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'De là, il monta pour attaquer Dabir; or, le nom de Dabir était autrefois Cariath-Sépher, ou Ville des Lettres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Et Caleb dit: Celui qui montera à l’assaut de la Ville des Lettres et la prendra, je lui donnerai pour femme ma fille Ascha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Et Gothoniel, fils de Cénez, frère puîné de Caleb, prit la ville; et Caleb lui donna pour femme sa fille Ascha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Tandis qu’elle s’en allait, Gothoniel lui persuada de demander à son père un champ, et, montée sur son âne, elle murmura et cria: Tu m’as établie en une terre du midi. Et Caleb lui dit: Qu’as-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Et Ascha lui dit: Accorde-moi un bienfait; tu m’as établie en une terre du midi; tu me donneras une terre arrosée d’eau. Et Caleb lui donna, selon son cœur, une terre arrosée en haut et en bas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'En ce temps-là, les fils de Jéthro le Cinéen, beau-père de Moïse, montèrent de la Ville des Palmiers, pour se réunir aux fils de Juda, dans le désert, au midi de Juda, vers la descente d’Arad, et ils demeurèrent parmi le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Ensuite, Juda marcha avec son frère Siméon; ils vainquirent le Chananéen qui habitait en Sépheth, ils l’exterminèrent, et ils donnèrent à cette ville le nom d’Anatheme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Mais Juda ne prit possession ni de Gaza, ni de son territoire; ni d’Ascalon, ni de son territoire; ni d’Accaron, ni de son territoire; ni d’Asor, ni de son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Toutefois, le Seigneur était avec Juda; il eut dans son héritage la contrée montagneuse, mais il ne put exterminer les habitants de la côte, parce que Rhéchab s’y opposait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Quant à Caleb, on lui avait donné, selon l’ordre de Moïse, le territoire d’Hébron, où il eut dans son héritage les trois villes des fils d’Enac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Les fils de Benjamin ne purent s’emparer du territoire des Jébuséens qui habitaient Jerusalem; les Jébuséens, jusqu’à ce jour, ont donc habité Jérusalem avec les fils de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'De leur côté, les fils de Joseph montèrent à Béthel, et le Seigneur était avec eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Et, après avoir établi leur camp, ils reconnurent Béthel, dont le nom était autrefois Luza.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Or, les gardes virent un homme qui sortait de la ville; ils le prirent, et ils lui dirent: Montre-nous par où l’on peut entrer dans la ville, et nous serons miséricordieux envers toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Et il leur montra l’entrée de la ville, et ils passèrent la ville au fil de l’épée, et ils laissèrent aller l’homme avec toute sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'L’homme s’en alla dans la terre d’Hettim; il y bâtit une ville, et il lui donna le nom de Luza, qu’elle porte encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manassé ne détruisit ni Bethsan, qui est une ville des Scythes; ni ses filles, ni ses alentours; ni Thanac, ni ses dépendances; ni les habitants de Dor, ni leurs dépendances; ni l’habitant de Balac, ni ses filles, ni ses dépendances; ni Magedo, ni ses filles, ni ses alentours; ni Jéblaam, ni ses filles, ni ses alentours. Les Chananéens commencèrent à habiter cette terre avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Mais, lorsque Israël eut pris des forces, il assujettit le Chananéen au tribut, quoiqu’il ne le détruisît pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Ephraïm ne détruisit pas le Chananéen qui habitait Gazer; le Chananéen continua de demeurer à Gazer avec lui, et lui paya un tribut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulon ne détruisit pas les habitants de Cédron, ni ceux de Domana. Le Chananéen continua de demeurer avec lui, et devint son tributaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser ne détruisit pas les habitants d’Accho; ils devinrent ses tributaires; il ne détruisit pas les habitants de Dor, ni ceux de Sidon, de Dalaph, d’Aschazi, de Chebda, de Naï et d’Eréo.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Aser demeura au milieu des Chananéens qui habitaient cette terre, parce qu’il ne put les détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Nephthali ne détruisit pas les habitants de Bethsamys, ni ceux de Béthanath; Nephthali demeura au milieu du Chananéen qui habitait la contrée. Ceux de Bethsamys et de Béthanath devinrent ses tributaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'L’Amorrhéen resserra Dan sur les montagnes; il ne lui permit pas de descendre dans les vallées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Les Amorrhéens commencèrent même à habiter la montagne de l’Argile, où il y a des ours et des renards; ils eurent Myrsinon et Thalabin; mais la main de la maison de Joseph s’appesantit sur l’Amorrhéen, et celui-ci devint son tributaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Les limites de l’Amorrhéen furent la montée d’Acrabin, les rochers et les hauteurs qui les dominent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'En ce temps-là, un ange du Seigneur vint de Galgala vers le Champ des Pleurs, vers Béthel et vers la maison de Joseph, à qui il dit: Voici ce que dit le Seigneur: Je vous ai fait sortir d’Égypte, je vous ai conduits en la terre que j’ai promise à vos pères, et j’ai dit: Je ne romprai pas l’alliance perpétuelle que j’ai faite avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Et vous, vous ne ferez point alliance avec les peuples de cette terre, vous n’adorerez point leurs dieux, mais vous en briserez les images, et vous démolirez leurs autels. Or, vous avez été indociles à ma voix: car vous avez fait ce qui vous était défendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Et j’ai dit: Je n’exterminerai point ces peuples devant votre face, et ils seront pour vous un sujet d’angoisse, et leurs dieux vous seront un objet de scandale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Lorsque l’ange du Seigneur eut dit ces paroles à tous les fils d’Israël, le peuple éleva la voix et pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Ils donnèrent à ce lieu le nom de Champ des Pleurs, et ils y sacrifièrent au Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Or, lorsque Josué avait congédié le peuple, chacun était allé prendre possession de son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Et le peuple avait servi le Seigneur durant tous les jours de Josué et durant tous les jours des anciens, dont la vie s’était prolongée avec la sienne, et qui avaient vu toutes les œuvres du Seigneur en faveur d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Et Josué, fils de Nau, serviteur de Dieu, était mort âgé de cent dix ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Et on l’avait enseveli sur les limites de son héritage en Thamnatharès, dans les montagnes d’Ephraïm au nord des montagnes de Gaas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Toute cette génération s’était réunie à ses pères; et il s’éleva après elle une autre génération qui ne connaissait point le Seigneur, ni les œuvres du Seigneur en faveur d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Les fils d’Israël alors firent le mal devant le Seigneur, et ils servirent les Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Ils abandonnèrent le Seigneur Dieu de leurs pères qui les avait fait sortir de l’Égypte, et ils suivirent d’autres dieux parmi les dieux des nations qui les entouraient; ils les adorèrent, et ils excitèrent le courroux du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Ils l’abandonnèrent, et ils servirent Baal et les Astartés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Alors le Seigneur fut courroucé contre Israël; il les livra aux mains de pillards qui les dépouillèrent; il les fit retomber entre les mains de leurs ennemis tout alentour, et ils ne purent résister devant leurs ennemis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'De quelque côté qu’ils marchassent. Et la main du Seigneur était sur eux pour leur mal, comme l’avait dit le Seigneur Dieu, comme il le leur avait juré, et il les affligea beaucoup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Ensuite, le Seigneur suscita des juges, et le Seigneur sauva le peuple des mains de ceux qui en faisaient leur proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Et le peuple n’obéit pas aux juges, parce qu’il s’était prostitué à la suite des dieux étrangers, et qu’il les avait adorés; il dévia rapidement des voies où avaient marché ses pères; il cessa d’écouter comme eux la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Et lorsque le Seigneur avait suscité des juges pour les fils d’Israël, et que le Seigneur était avec le juge, il les sauvait des mains de leurs ennemis, durant tous les jours du juge, parce que le Seigneur était ému de leurs gémissements devant ceux qui les assiégeaient et les affligeaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Mais, lorsque le juge était mort, ils changeaient et retombaient dans une corruption plus grande que celle de leurs pères, en suivant d’autres dieux, en les servant et en les adorant. Ils ne pouvaient alors renoncer à leurs habitudes ni à leurs voies d’endurcissement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Le Seigneur se courrouça donc contre Israël, et il dit Pour punir ce peuple d’avoir abandonné l’alliance que j’avais faite avec ses pères, et de n’avoir pas écouté ma parole,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Je ne ferai plus périr un seul homme de ceux qu’a laissés en cette terre Josué, fils de Nau, et qu’a laissés le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Pour éprouver par eux Israël, et voir s’il persévérerait ou non dans la voie du Seigneur qu’avaient suivie leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Et le Seigneur permettra encore que les nations qu’il n’a pas livrées aux mains de Josué, ne soient point exterminées rapidement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Voici les peuples que laissa le Seigneur pour éprouver par eux en Israël, tous ceux qui n’avaient point vu les guerres de Chanaan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Uniquement pour l’amour des générations des fils d’Israël, dans le but de leur apprendre la guerre (mais les générations précédentes n’avaient point connu ces choses):');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Les cinq principautés des Philistins, tout le Chananéen, et le Sidonien, et l’Évéen, qui habitait le Liban, depuis les montagnes d’Hermon jusqu’à Labo-Emath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Et cela arriva pour que le Seigneur éprouvât par eux Israël, et pour qu’il connût si le peuple était docile aux commandements que Dieu avait intimés à ses pères par la voix de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Les fils d’Israël habitaient donc au milieu du Chananéen, de l’Hettéen, de l’Amorrhéen, du Phérézéen, de l’Évéen et du Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Et ils prirent leurs filles pour femmes, et ils donnèrent à leurs fils des filles d’Israël, et ils servirent leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Ainsi, les fils d’Israël firent le mal devant le Seigneur; ils oublièrent le Seigneur leur Dieu, et ils servirent les Baal et les bois sacrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Et le Seigneur se courrouça contre Israël; il le livra aux mains de Chusarsathaïm, roi de la Syrie des fleuves, et les fils d’Israël furent assujettis huit ans à Chusarsathaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Et les fils d’Israël crièrent au Seigneur, et le Seigneur suscita pour Israël un sauveur qui les délivra; ce fut Othoniel, fils de Cénez, frère puîné de Caleb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Et l’esprit du Seigneur vint en lui, il jugea Israël, et il sortit pour combattre Chusarsathaïm. Le Seigneur livra à ses mains Chusarsathaïm, roi de la Syrie des fleuves, et sa main prévalut contre Chusarsathaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Et la terre fut en repos durant quarante années, et Othoniel, fils de Cénez, mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Aussitôt, les fils d’Israël recommencèrent à faire le mal devant le Seigneur, et le Seigneur fortifia Eglom, roi de Moab, contre les fils d’Israël, parce qu’ils avaient fait le mal devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'S’étant adjoint tous les fils d’Ammon et d’Amalec, il se mit en marche, il vainquit Israël, et il s’empara de la Ville des Palmiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Puis, les fils d’Israël furent assujettis dix-huit ans à Eglom, roi de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Et les fils d’Israël crièrent au Seigneur, et il leur suscita un sauveur, Aod, fils de Géra, fils de Jémini, homme ambidextre; les fils d’Israël envoyèrent par ses mains des présents à Eglom, roi de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Aod se fit un poignard à double tranchant de la longueur de sa main, et il se l’attacha sous son manteau, contre la cuisse droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Et il partit portant des présents à Eglom, roi de Moab; Eglom était un homme obèse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Et lorsque Aod eut achevé de lui remettre les présents, il sortit et congédia ceux qui les avaient apportés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Lui-même étant revenu des carrières de Galgal, dit à Eglom: O roi, un mot en secret. Et Eglom lui dit: Garde le silence. Et il éloigna tous ceux qui se tenaient auprès de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Aod s’approcha de lui; or, il était assis tout à fait seul dans son appartement d’été. Et Aod lui dit: Ô roi, un mot de mon Dieu pour toi seul. Et Eglom se leva de son trône pour être plus près d’Aod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Et pendant qu’il se levait, Aod étendit la main gauche, prit le poignard sur sa cuisse droite, et l’enfonça dans les entrailles d’Eglom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Il fit entrer aussi la poignée après la lame, et la graisse se referma tout le long de l’arme, parce qu’il n’avait point retiré le poignard de la blessure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Aod sortit par le vestibule; il évita les gardes, après avoir tiré sur lui les portes de l’appartement, et les avoir verrouillées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Il sortit donc, et les serviteurs du roi survinrent; ils virent or, voilà que les portes de l’appartement étaient verrouillées; alors ils dirent: Ne va-t-il pas délivrer ses pieds dans l’appartement d’été?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Et ils attendirent jusqu’à ce que la rougeur leur vînt au visage; enfin, comme personne n’ouvrait la porte de l’appartement d’été, ils prirent la clef; ils ouvrirent, et virent leur maître étendu mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Cependant, Aod s’était sauvé tandis qu’ils étaient pleins de trouble, et nul ne s’occupa de lui; il passa près des carrières, et il arriva sain et sauf à Sétirotha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Aussitôt qu’Aod eut atteint la terre d’Israël, il fit sonner du cor dans les montagnes d’Ephraïm; les fils d’Israël descendirent avec lui de leurs montagnes, et il se mit à leur tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Puis, il leur dit Suivez-moi, car le Seigneur Dieu nous a livrés nos ennemis de Moab. Ils le suivirent, et s’emparèrent des gués du Jourdain qui étaient devant Moab, et ils ne permirent à aucun Moabite de passer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Ce jour-là, ils vainquirent Moab; ils tuèrent dix mille hommes, tous gras et pleins de force; pas un seul combattant n’échappa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Ce jour-là Moab fut humilié par les mains d’Israël, et la terre resta en repos quatre-vingts ans, et Aod les jugea jusqu’à ce qu’il mourût.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Après lui s’éleva Samegar, fils de Dinach; il vainquit les Philistins, au nombre de six cents hommes, avec un soc de charrue. Et lui aussi sauva Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Mais, les fils d’Israël recommencèrent à faire le mal devant le Seigneur, et Aod était mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Le Seigneur alors livra les fils d’Israël aux mains de Jabin, roi de Chanaan, qui régnait en Asor; le général de son armée était Sisara, et celui-ci demeurait en Arisoth des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Et les fils d’Israël crièrent au Seigneur, parce que ce roi avait neuf cents chars armés de faux, et que depuis vingt ans il opprimait cruellement Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'En ce temps-là, Débora, prophétesse, femme de Lapidoth, jugeait Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Elle siégeait sous le palmier de Débora, entre Rhama et Béthel, dans les montagnes d’Ephraïm; et les fils d’Israël venaient à elle pour être jugés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Débora envoya chercher Barac, fils d’Abinéem, de Cadès en Nephthali, et elle lui dit: Le Seigneur ne t’a-t-il pas donné ces ordres: Tu t’en iras au mont Thabor; tu prendras avec toi dix mille hommes des fils de Nephthali et des fils de Zabulon, puis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'J’amènerai vers toi, dans le torrent de Cison, Sisara, général de l’armée de Jabin, et ses chars, et ses troupes, et je le livrerai à tes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'À quoi Barac répondit: Si tu pars avec moi, je partirai; sinon, je ne partirai pas car je ne sais pas le jour où le Seigneur me favorisera de la compagnie de son ange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Et elle dit: Je partirai avec toi; mais sache que tu n’auras point le premier rang dans la voie où tu veux marcher; car le Seigneur livrera Sisara aux mains d’une femme. Débora se leva donc, et elle partit de Cadès avec Barac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Et Barac appela de Cadès le secours de Zabulon et de Nephthali; dix mille hommes le suivirent, et Débora partit avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Or, Haber le Cinéen s’était éloigné de Caïna et des fils de Jobab, allié de Moïse; et il avait dressé sa tente vers le Chêne des Ravisseurs, qui touche à Cadès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Quand on apprit à Sisara que Barac, fils d’Abinéem, était allé sur le mont Thabor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Sisara rassembla tous ses chars, ses neuf cents chars armés de faux, avec tout le peuple qui habitait comme lui Arisoth des gentils, et il les mena dans le torrent de Cison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Débora dit à Barac: Debout, voici le jour où le Seigneur te livre Sisara; car le Seigneur va marcher à notre tête. Et Barac descendit du mont Thabor suivi de dix mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Et le Seigneur frappa Sisara d’épouvante; ses chars s’embarrassèrent; tout son camp fut passé au fil de l’épée devant Barac; et Sisara descendit de son char, et il s’enfuit à pied.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Et Barac poursuivit ses chars et les débris du camp jusqu’à Arisoth des gentils; toute l’armée de Sisara fut passée au fil de l’épée; il n’en resta pas un seul homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Cependant, Sisara s’enfuit à pied dans la tente de Jaël, femme du Cinéen Haber son ami; car il y avait paix entre Jabin, roi d’Asor, et Haber le Cinéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Et Jaël sortit à la rencontre de Sisara, et elle lui dit: Entre, mon seigneur, cache-toi chez moi, n’aie point de crainte. Et il se cacha chez elle dans la tente, et elle l’enveloppa d’un manteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Or, Sisara lui dit: Donne-moi à boire un peu d’eau, car j’ai bien soif. Et elle lui ouvrit l’outre à lait, et elle le fit boire; puis, elle le recouvrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Et Sisara lui dit: Tiens-toi devant la porte de la tente; et si quelqu’un vient à toi, et te demande: Y a-t-il ici un homme? réponds: Il n’y en a point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Et Jaël, femme d’Haber, prit un des clous de la tente; elle mit un marteau dans sa main, elle s’approcha de Sisara furtivement, et elle lui enfonça dans la tempe le clou qui traversa de part en part jusqu’à terre; et l’homme, perdant connaissance, fut enveloppé de ténèbres, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Bientôt Barac parut poursuivant Sisara; Jaël sortit à sa rencontre, et elle lui dit: Viens, je vais te montrer l’homme que tu cherches. Il entra auprès d’elle, et il vit Sisara étendu mort, le clou dans la tempe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Ainsi, le Seigneur Dieu, ce jour-là, mit en déroute le roi Jabin, devant les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Et la main des fils d’Israël prévalut de plus en plus contre Jabin, roi de Chanaan, jusqu’à ce qu’ils l’eussent détruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Ce jour-là, Débora et Barac, fils d’Abinéem, chantèrent ainsi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Une révélation s’est faite en Israël, quand le peuple a été de bonne volonté; bénissez le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Écoutez, rois; prêtez l’oreille, princes; je vais chanter un psaume au Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Seigneur, quand vous êtes sorti de Séir, quand vous avez quitté les champs d’Edom, la terre a tremblé, le ciel a fait tomber de la rosée, les nuages ont répandu de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Les montagnes ont été ébranlées à la face du Seigneur Eloï, et aussi le Sina, à la face du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Durant les jours de Samegar, fils d’Anath, durant les jours de Jaël, ils ont quitté les voies, ils ont pris des sentiers, ils ont suivi des chemins détournés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Les hommes forts ont manqué en Israël, ils ont manqué jusqu’à ce que vînt Débora, jusqu’à ce que s’élevât une mère en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Ils s’étaient choisi de nouveaux dieux; alors, les ennemis ont attaqué même les villes des princes. Si l’on avait vu alors un bouclier et une lance parmi les quarante mille guerriers d’Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mon cœur est tout aux commandements donnés à Israël; vous qui parmi le peuple êtes de bonne volonté, bénissez le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vous qui montez sur des ânesses belles et luisantes, vous qui êtes assis sur le siége où l’on rend la justice, vous qui vous avancez sur la route des siéges ou vers cette route; racontez ces hauts faits,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Loin du bruit des perturbateurs, au milieu de ceux qui puisent paisiblement de l’eau, au lieu où l’on rend la justice. Seigneur, multipliez la justice en Israël. Alors, le peuple du Seigneur descendra aux portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Réveille-toi, réveille-toi, Débora, réveille-toi, réveille-toi; chante un cantique; debout, ô Barac; emmène en captivité tes prisonniers, fils d’Abinéem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Ce jour-là, est descendu ce qui restait des forts. Le peuple du Seigneur est descendu avec le Seigneur, et les vaillants excités par moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Ephraïm les a déracinés en Amalec, et, à votre suite, Seigneur, Benjamin et tout votre peuple. Ceux de Machir sont descendus avec moi, ardents à chercher l’ennemi; et ceux de Zabulon, même ceux qui maniaient la plume des scribes raconteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Les princes d’Issachar étaient avec Débora; ainsi, elle envoya Balac à pied dans les vallons, sur le territoire de Ruben, où il y a grandes angoisses atteignant le cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Pourquoi demeurent-ils, au milieu des parcs, à entendre les beuglements de leurs grands troupeaux, pendant les discordes de Ruben? là, il y a de grandes épreuves du cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Galaad est de l’autre côté du Jourdain, où il a dressé ses tentes. Et Dan, pourquoi se tient-il sur ses barques? Aser s’est assis sur la côte maritime, il habite vers les embouchures de ses cours d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Le peuple de Zabulon a exposé sa vie à la mort; Nephthali est venu sur les hauts lieux de sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Les rois se sont rangés en bataille, les rois de Chanaan ont combattu en Thanaach, près des eaux de Mageddo; ils n’ont point recueilli de butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Les étoiles, du haut du ciel, ont pris part à la lutte, sans quitter leurs voies; elles ont combattu contre Sisara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Le torrent de Cison les a balayés, le torrent des anciens, le torrent de Cison! Mon âme dans sa force foulera aux pieds les ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Lorsque les jambes des chevaux furent embarrassées, ses forts se hâtèrent de fuir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Maudite soit Méroz, dit l’ange du Seigneur, maudissez-la. Maudits soient tous ceux qui l’habitent, parce qu’ils ne sont point venus au secours du Seigneur, parce qu’ils ne lui ont point envoyé leurs hommes vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Bénie soit, parmi les femmes, Jaël, l’épouse d’Haber le Cinéen; que sous leurs tentes les femmes la bénissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Il avait demandé de l’eau; elle lui donna du lait dans une coupe; elle lui présenta le beurre que l’on offre aux grands;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Elle étendit sa main gauche vers le clou et sa main droite vers le marteau des travailleurs; elle en frappa Sisara, elle fit entrer le clou dans sa tête, et elle frappa encore, et elle poussa le clou au travers de sa tempe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Et il roula entre ses pieds, il défaillit, et il mourut entre ses pieds; il s’était étendu devant elle, et il mourut dans son sommeil, et, au lieu même où il s’était endormi, la vie l’abandonna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'La mère de Sisara s’est penchée à sa fenêtre, et, regardant par le treillis, elle a dit: Pourquoi son char tarde-t-il? D’où vient que son attelage se fait attendre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Les sages princesses qui l’entouraient lui ont répondu, et elle-même a répété leurs paroles:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Ne le trouvera-t-on pas distribuant le butin? Mais elle pleurera, et pleurera sur la tête de l’homme; des étoffes teintes pour Sisara, des étoffes teintes de couleurs diverses, de riches étoffes, des dépouilles, tout autour de sa tête!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Ainsi périssent tous vos ennemis, ô Seigneur! Que ceux qui aiment le Seigneur soient comme le lever du soleil dans toute sa puissance. La terre ensuite fut en repos durant quarante années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Les fils d’Israël firent encore le mal devant le Seigneur, et le Seigneur les livra aux mains de Madian, pendant sept années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Et la main de Madian prévalut sur Israël; et les fils d’Israël, à l’aspect de Madian, se firent des cachettes dans les montagnes; ils se firent des grottes et des murs de défense dans les rochers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Quand les fils d’Israël avaient semé, Madian montait avec Amalec; les fils de l’Orient marchaient dans leurs rangs, et ils campaient chez eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Et ils détruisaient leurs fruits jusqu’aux portes de Gaza, et ils ne laissèrent rien de ce qui sert à la vie en la terre d’Israël, et ils n’épargnaient ni bœuf ni âne parmi les troupeaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Parce qu’ils montaient avec tous leurs biens et avec leurs tentes, nombreux comme des sauterelles lorsqu’elles foisonnent; leur multitude et celle de leurs chameaux étaient innombrables; ils dominaient sur la terre d’Israël, et ils la dévastaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Israël était tout appauvri devant la face de Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Et les fils d’Israël crièrent au Seigneur, à cause de Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Et le Seigneur envoya un prophète aux fils d’Israël, et l’homme leur dit: Voici ce que dit le Seigneur Dieu d’Israël Je suis Celui qui vous ai tirés de la terre d’Égypte, qui vous ai fait sortir de votre maison de servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Je vous ai arrachés des mains de l’Égyptien et de tous ceux qui vous opprimaient; j’ai banni ceux-ci de devant votre face, et je vous ai donné leur territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Et je vous ai dit: Je suis le Seigneur votre Dieu; n’ayez point crainte des dieux des Amorrhéens, parmi lesquels vous résiderez en leur terre. Mais vous n’avez pas été dociles à ma voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Ensuite, un ange du Seigneur vint, et il s’arrêta sous le térébinthe d’Ephratha, en la terre de Joas, fils d’Esdri, comme son fils Gédéon battait du blé dans le pressoir pour échapper aux regards des Madianites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'L’ange du Seigneur lui apparut, et il lui dit: Le Seigneur est avec toi, fort parmi les plus vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Et Gédéon dit: Je vous prie, mon Seigneur; si le Seigneur est avec nous, pourquoi ces maux nous sont-ils venus? Et où sont tous ces miracles que nous ont racontés nos pères, disant: N’est-ce point le Seigneur qui nous a fait sortir de l’Égypte? Maintenant, il nous a renversés, il nous a livrés aux mains de Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'L’ange du Seigneur le regarda, et lui dit: Marche en ta force, et tu délivreras Israël des mains de Madian. Voilà que pour cela je t’envoie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Et Gédéon lui dit: Je vous prie, mon Seigneur, et comment sauverai-je Israël? Voilà que mes mille hommes sont sans force dans Manassé, et je suis le moindre de la maison de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'L’ange reprit: Le Seigneur sera avec toi, et tu vaincras Madian comme un seul homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Et Gédéon lui dit: Si j’ai trouvé miséricorde à vos yeux, et si vous accomplissez aujourd’hui par moi tout ce que vous m’avez promis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Ne vous éloignez pas d’ici que je n’y revienne; j’apporterai une victime, et je la sacrifierai devant vous. Et l’ange répondit: Je vais rester jusqu’à ton retour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gédéon rentra donc; il prépara un chevreau, et des pains sans levain d’une mesure de farine (éphi); il mit les chairs sur une corbeille, il versa le jus dans un vase; il porta tout cela à l’ange sous le térébinthe, et il s’approcha de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Et l’ange de Dieu lui dit: Prends les chairs et les azymes, dépose-les sur cette pierre, et répands le jus pardessus; ainsi fit Gédéon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Et l’ange du Seigneur étendit le bout de la baguette qu’il tenait à la main; il toucha les chairs et les azymes, et il s’éleva de la pierre une flamme qui dévora les chairs et les azymes; et l’ange du Seigneur disparut à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Gédéon vit ainsi que c’était un ange du Seigneur, et il dit Hélas! hélas! Seigneur, mon Seigneur, j’ai vu face à face un ange du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Et le Seigneur lui dit: La paix soit avec toi; n’aie point crainte, tu ne mourras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Gédéon éleva en ce lieu un autel au Seigneur, et il le nomma la Paix du Seigneur, comme on le nomme de nos jours, car il subsiste encore en Ephratha, ville du père Esdri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Cette nuit même il advint que le Seigneur dit à Gédéon: Prends le taureau de ton père, avec une seconde tête de sept ans; puis tu renverseras l’autel de Baal appartenant à ton père, et tu détruiras le bois sacré qui est tout auprès;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Cela fait, tu élèveras un autel au Seigneur ton Dieu sur la cime de ce mont Maozi, en signe de résistance; tu prendras la seconde tête de bétail, et tu l’offriras comme holocauste, en la brûlant avec les arbres du bois sacré que tu auras détruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Gédéon prit dix de ses serviteurs, et il fit ce que le Seigneur lui avait dit. Or, comme il craignait, à cause de la maison de son père et des hommes de la ville, de le faire en plein jour, il le fit la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Les hommes de la ville se levèrent de grand matin, et voilà que l’autel de Baal était renversé, et le bois sacré situé tout auprès détruit; et ils virent la seconde tête de bétail que Gédéon avait offerte, sur l’autel qu’il avait élevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Chacun dit à son voisin: Qui a fait cela? Ils s’informèrent, et ils apprirent que c’était Gédéon, fils de Joas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Les hommes de la ville dirent alors à Joas: Amènenous ton fils; qu’il soit mis à mort, parce qu’il a renversé l’autel de Baal et qu’il a détruit le bois sacré situé auprès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Et Gédéon, fils de Joas, dit à tous les hommes de la ville, qui s’étaient soulevés contre lui: Allez-vous plaider pour Baal? est-ce vous qui le sauverez? Que celui qui plaidera pour Baal soit mis à mort avant le lever du jour. Si Baal est Dieu, qu’il se venge, puisqu’on a renversé son autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Et il se donna à lui-même ce jour-là le nom de Jérobaal, en disant: Que Baal se venge, puisque son autel a été renversé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'En ce temps-là, Madian, Amalec, et les fils de l’Orient, étaient rassemblés tous à la fois; ils campaient dans la vallée de Jezraël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Et l’esprit du Seigneur vint en Gédéon; il fit sonner du cor, et sur ses pas Abiézer accourut à son secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Alors, il dépêcha des messagers à tout Manassé, à Azer, à Zabulon et à Nephthali, et il marcha au-devant des hommes de ces tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Et Gédéon dit à Dieu Si votre volonté est de sauver par ma main Israël, comme vous avez dit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Voyez je dépose dans l’aire cette toison de laine; que la rosée se montre sur la toison seule et qu’il y ait sécheresse sur toute la terre, et je reconnaîtrai votre volonté de sauver par ma main Israël, comme vous avez dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Il en fut ainsi. Gédéon se leva de grand matin; il pressa la toison, la rosée coula de la laine, et remplit d’eau un bassin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Ensuite, Gédéon dit à Dieu: Que votre courroux ne s’enflamme point contre moi, et je parlerai une seule fois encore, je ferai une seule fois encore l’épreuve de la toison que la sécheresse se montre sur la toison seule, et la rosée sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Dieu fit ainsi en cette nuit même: la sécheresse se montra sur la toison seule, et il y eut de la rosée sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Après cela, Jérobaal, le même que Gédéon, se leva de grand matin, et tout le peuple avec lui; ils campèrent vers la fontaine d’Arad, et le camp de Moab était au nord de la fontaine, du côté de Gabaathamoré, dans le vallon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Et le Seigneur dit à Gédéon: Le peuple qui te suit est nombreux, tellement que je ne livrerai pas Madian à ses mains, de peur qu’Israël n’aille se glorifier contre moi, et ne dise: C’est ma main qui m’a sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Parle donc au peuple, disant: Y a-t-il ici quelqu’un qui craigne et faiblisse? que celui-là s’en aille, qu’il s’ éloigne des montagnes de Galaad. Or, vingt-deux mille du peuple partirent, et dix mille restèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Et le Seigneur dit à Gédéon: Ce peuple est encore nombreux; fais-le descendre auprès de l’eau, et là je le purifierai pour toi. Et celui de qui je te dirai: Il doit marcher avec toi, marchera; celui de qui je te dirai: Il ne doit point marcher avec toi, ne marchera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Et Gédéon conduisit le peuple auprès de l’eau, et le Seigneur lui dit: Celui qui prendra de l’eau avec la langue, comme le font les chiens, tu le placeras d’un côté, et tu placeras d’un autre côté tous ceux qui se mettront à genoux pour boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Or, le nombre de ceux qui prirent de l’eau dans leur main et la portèrent à leur bouche s’éleva à trois cents, et tout le reste du peuple se mit à genoux pour boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Et le Seigneur dit à Gédéon: C’est avec les trois cents hommes qui ont pris de l’eau dans leurs mains que je vous sauverai et vous livrerai Madian; tout le reste du peuple s’en ira, chacun en son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Les trois cents prirent donc tous les vivres du peuple et leurs cors, et Gédéon congédia tout Israël, chacun en sa demeure, puis il encouragea les trois cents. Cependant, le camp des Madianites était au-dessous de lui, au fond de la vallée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Et cette nuit-là même, il advint que le Seigneur lui dit: Debout, descends sur leur camp, car je l’ai livré à tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Si tu crains de descendre seul, descends sur le camp avec Phara, ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Écoute ce qu’ils diront; après cela, tes mains seront fortifiées, et tu descendras pour attaquer le camp. Il descendit, accompagné seulement de Phara, son serviteur, vers la plus avancée des compagnies de cinquante hommes qui étaient dans le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Et Madian, Amalec et les fils de l’Orient étaient entassés au fond de la vallée, comme les sauterelles quand elles foisonnent; la multitude de leurs chameaux était innombrable, et ils étaient comme le sable sur le rivage de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Quand Gédéon survint, voilà qu’un homme racontait à son voisin un songe, et il disait: J’ai eu un songe; j’ai vu un pain de pâte d’orge roulant sur le camp des Madianites; il arriva jusqu’à une tente, il la frappa et la fit tomber; il renversa de fond en comble la tente, et elle tomba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Or, son voisin lui répondit: Le pain n’est autre chose que l’épée de Gédéon, fils de Joas, homme d’Israël. Le Seigneur a livré à ses mains Madian et notre camp tout entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Gédéon, ayant ouï le récit du songe et son interprétation, adora le Seigneur; il rentra au camp d’Israël, et il dit: Levez-vous, parce que le Seigneur a livré à nos mains le camp des Madianites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Il divisa ses trois cents hommes en trois troupes, et il leur donna des cors à tous, et dans l’autre main des pots vides, et dans chaque pot une lampe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Et il leur dit: Soyez attentifs à ce que je ferai, et faites de même. J’entrerai par la tête du camp, et comme je ferai vous ferez aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Je ferai retentir mon cor, et vous sonnerez de même tout à l’entour du camp, et vous direz: Au Seigneur et à Gédéon!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Gédéon et ses cent hommes entrèrent donc par la tête du camp, au commencement de la seconde veille; le bruit qu’ils firent réveilla les gardes; et ils sonnèrent du cor, et ils agitèrent les pots qu’ils tenaient à la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Les trois troupes sonnèrent du cor, et brisèrent leurs pots; alors, les hommes, tenant de la main gauche les lampes et de la main droite les cors, qu’ils faisaient retentir, crièrent: L’épée du Seigneur et de Gédéon!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Chaque homme resta en place tout autour du camp, et tout le camp se mit à courir; les Madianites se donnèrent des ordres confus, et ils s’enfuirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Et les trois cents cors sonnaient toujours, et le Seigneur tourna l’épée de chaque Madianite contre son voisin dans le camp tout entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Le camp s’enfuit jusqu’à Bethséed, Tagaragatha, Abelméula, tirant vers Rabath. En Israël, Nephthali, Aser, tout Manassé apportèrent leur secours, et ils poursuivirent Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Et Gédéon dépêcha des messagers dans toutes les montagnes d’Ephraïm, disant: Descendez à la rencontre de Madian, emparez-vous de l’eau jusqu’à Béthéra, emparez-vous du cours du Jourdain. Et tous les hommes d’Ephraïm crièrent, et ils s’emparèrent de l’eau jusqu’à Béthéra; ils s’emparèrent du cours du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Et ils prirent les chefs de Madian Oreb et Zeb; ils tuèrent Oreb à Sur-Oreb; ils tuèrent Zeb en Jacephzeph. Et ils poursuivirent Madian, et ils rapportèrent, de l’autre côté du Jourdain, à Gédéon, les têtes de Zeb et d’Oreb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Les hommes d’Ephraïm dirent à Gédéon: Pourquoi nous as-tu fait l’injure de ne point nous appeler quand tu marchais pour combattre les Madianites? Et ils lui parlèrent durement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Et il leur dit: Qu’ai-je fait maintenant qui égale ce que vous avez fait? Une petite grappe d’Ephraïm ne vaut-elle pas mieux que la vendange d’Abiézer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Le Seigneur a livré à vos mains les chefs de Madian, Oreb et Zeb. Aurais-je pu faire autant que vous? Alors, leur courroux se détourna de lui, quand il leur eut dit cette parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Ensuite, Gédéon marcha au Jourdain, il le traversa, et les trois cents hommes avec lui; ils étaient affamés, mais ils poursuivaient toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Et Gédéon dit aux hommes de Socchoth: Donnezmoi des pains pour nourrir le peuple qui me suit, car ils tombent de défaillance; et voilà que je poursuis Zébé et Salmana, rois de Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Mais les chefs de Socchoth dirent: Est-ce que la main de Zébé et de Salmana est déjà dans ta main, pour que nous donnions des vivres à ta troupe?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Et Gédéon dit: À cause de votre refus, lorsque le Seigneur aura livré à nos mains Zébé et Salmana, je broierai vos chairs à force de coups d’épines du désert et de Barcenim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'De là, il monta en Phanuel, où il leur fit la même demande; les hommes de Phanuel lui répondirent de la même manière que ceux de Socchoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Et Gédéon dit aux hommes de Phanuel: À mon retour, après la paix, je démolirai cette tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Or, Zébé et Salmana étaient alors en Carcar; leur camp renfermait environ quinze mille hommes, débris de tout le camp des étrangers; et ceux qui avaient péri n’étaient pas moins de cent vingt mille portant l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Et Gédéon prit le chemin des ennemis dont les tentes étaient à l’orient de Nabé et de Jégébal, et il attaqua le camp, et le camp était sans méfiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Et Zébé et Salmana s’étant enfuis, il les poursuivit, il les prit, et frappa d’épouvante l’armée entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Ensuite, Gédéon, fils de Joas, revint de la bataille des hauteurs d’Arès, où il l’avait livrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Et il surprit un jeune garçon des hommes de Socchoth; il le questionna, et il écrivit, d’après lui, les noms des chefs et des anciens de Socchoth: soixante-dixsept hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Et Gédéon se rendit auprès des chefs de Socchoth, et il dit: Voici Zébé et Salmana, au sujet desquels vous m’avez outragé, disant: Est-ce que la main de Zébé et de Salmana est dans ta main, pour que nous donnions des vivres à tes hommes défaillants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Puis, il prit les anciens de la ville; il prit des épines du désert et de Barcenim, et il fit meurtrir de coups avec les épines les hommes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Et il démolit la tour de Phanuel, et il tua les hommes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Et il dit à Zébé et Salmana: Comment étaient les hommes que vous avez tués au mont Thabor? Et ils dirent: Tel nous te voyons, tels ils étaient; ils semblaient des fils des rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Et Gédéon dit: C’étaient mes frères, fils de ma mère, vive le Seigneur! Si vous les aviez épargnés, je ne vous ferais point mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Puis, il dit à Jéther, son premier-né: Lève-toi, et tue-les. Mais le jeune homme ne tira point son épée, car il avait crainte, parce qu’il était jeune encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Zébé et Salmana dirent: Lève-toi toi-même, et tombe sur nous, car ta force est celle d’un homme. Gédéon se leva donc, et il tua Zébé et Salmana. Et il prit les croissants qui ornaient le cou de leurs chameaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Israël dit alors à Gédéon: Seigneur, règne sur nous, toi et ton fils et le fils de ton fils, parce que tu nous as sauvés des mains de Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Mais Gédéon leur dit: Je ne règnerai point sur vous, et mon fils ne règnera point sur vous; le Seigneur règnera sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Et Gédéon ajouta: Je vous ferai une demande: Que chacun me donne, de sa part du butin, les pendants d’oreilles. Ces hommes avaient tous des pendants d’oreilles d’or, parce qu’ils étaient Ismaélites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Ils répondirent: Nous te les donnerons avec empressement. Aussitôt, il déploya son manteau, et chacun y jeta les pendants d’oreilles de sa part de butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Le poids des pendants d’oreilles qu’il avait demandés, fut de dix-sept cents sicles d’or, outre les bossettes, les torsades, les vêtements et les robes de pourpre que portaient les rois de Madian, et les ornements qui entouraient le cou de leurs chameaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gédéon en fit un éphod, et il le plaça en Ephratha, sa ville. Et là, tout Israël se prostitua à l’occasion de cet éphod, qui fut une pierre d’achoppement pour Gédéon et pour sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Et Madian fut réduit à rien devant les fils d’Israël; il ne continua plus de relever la tête, et la terre fut en repos quarante années durant les jours de Gédéon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Jérobaal, fils de Joas, s’en retourna, et demeura dans sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Il avait soixante-dix fils, nés de lui, parce qu’il avait beaucoup de femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Il avait aussi une concubine à Sichem, et celle-là, pareillement, lui donna un fils, qu’elle nomma Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gédéon, fils de Joas, mourut en sa ville, et il fut enseveli dans le sépulcre de Joas, son père, en Ephratha d’Abi-Esdri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Gédéon mort, les fils d’Israël se pervertirent; ils se prostituèrent aux Baal, et ils firent alliance avec Baal afin qu’il fût leur dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Et les fils d’Israël ne se souvinrent plus du Seigneur, du Dieu qui les avait délivrés des mains de tous ceux d’alentour qui les opprimaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Et ils furent sans égard pour la maison de Jérobaal (le même que Gédéon), et ils oublièrent le bien que celui-ci avait fait à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Et Abimélech, fils de Jérobaal, alla trouver à Sichem les frères de sa mère, et il parla à eux et à toute la famille du père de sa mère, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Dites donc à tous les hommes de Sichem: Quel est le meilleur pour vous d’être gouvernés par soixante-dix hommes, tous fils de Jérobaal, ou de n’avoir qu’un seul chef? Et n’oubliez pas que je suis de vos os et de votre chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Et les frères de sa mère parlèrent de lui à tous les hommes de Sichem, de sorte que leur cœur inclina pour Abimélech, parce que, dirent-ils, c’est notre frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Ils lui donnèrent donc soixante-dix sicles d’argent du temple du Baal-Bérith. Et Abimélech prit à son service des mercenaires méchants et dénués de tout, qui le suivirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Aussitôt, il entra dans la maison de son père, en Ephratha, et massacra, sur une même pierre, ses frères, les fils de Jérobaal, soixante-dix hommes. Il n’y eut d’épargné que Joatham, le plus jeune fils de Jérobaal, parce qu’il s’était caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Après cela, tous les hommes de Sichem, les juges, et toute la maison de Bethmaalo se réunirent, et ils marchèrent, et ils proclamèrent roi Abimélech, sous le chêne qui se trouva être le Chene de la sédition, à Sichem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'On l’apprit à Joatham, et il partit; il s’en fut sur la cime du mont Garizin; là, il éleva la voix, il pleura, et il leur dit Écoutez-moi, hommes de Sichem, et Dieu vous écoutera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Les arbres se mirent en mouvement, et ils se rassemblèrent pour oindre un roi qui régnât sur eux, et ils dirent à l’olivier: Règne sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Et l’olivier leur dit: Puis-je abandonner mon huile dont les hommes se servent pour honorer Dieu, et m’en aller pour être élevé à la tête des arbres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Et les arbres dirent au figuier: Viens, règne sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Et le figuier leur dit: Puis-je abandonner mon doux suc et mes excellents fruits, et m’en aller pour être élevé à la tête des autres arbres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Et les arbres dirent à la vigne: Viens, règne sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Et la vigne leur dit: Puis-je abandonner mon vin qui réjouit Dieu et les hommes, et m’en aller pour être élevé à la tête des arbres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Et tous les arbres dirent au nerprun: Viens, toi, et règne sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Et le nerprun dit aux arbres: Si, en vérité, vous me donnez l’onction pour que je règne sur vous, venez, demeurez sous mon ombre; sinon, qu’une flamme sorte de moi et qu’elle dévore les cèdres du Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Et vous, maintenant, si c’est en vérité et en toute perfection que vous avez agi, et que vous avez proclamé roi Abimélech, si vous avez traité avec bienveillance Jérobaal et sa maison, et si vous avez dignement récompensé mon père');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'D’avoir commandé vos armées, jeté sa vie aux hasards des combats, et délivré Israël des mains de Madian;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Vous qui vous êtes soulevés aujourd’hui contre la maison de mon père, et avez tué sur une même pierre ses fils, soixante-dix hommes, et avez proclamé roi Abimélech, fils de sa servante, pour qu’il règne sur Sichem, parce qu’il est votre frère;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Si c’est en vérité et en toute perfection que vous avez agi envers Jérobaal et toute sa famille, faites votre joie d’Abimélech, et que lui aussi mette sa joie en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Sinon, qu’une flamme sorte d’Abimélech, qu’elle dévore les hommes de Sichem et la maison de Bethmaalo, et qu’une flamme sorte des hommes de Sichem et de la maison de Bethmaalo, et qu’elle dévore Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Ensuite, Joatham s’enfuit; il courut, et se rendit à Béor, où il demeura loin de son frère Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Abimélech régna trois ans sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Et Dieu envoya un mauvais esprit entre Abimélech et les hommes de Sichem; les hommes de Sichem méprisèrent la maison d’Abimélec, et rejetèrent sur lui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'L’iniquité exercée contre les soixante-dix fils de Jérobaal; ils firent retomber le sang de ses frères, qu’il avait tués, sur lui, et sur les hommes de Sichem qui avaient prêté appui à ses mains pour qu’il tuât ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Alors, les hommes de Sichem lui dressèrent des embûches sur les cimes des monts; ils pillèrent tout ce qui passait près d’eux sur la route; et on vint l’annoncer au roi Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Et Gaal, fils de Jobel, survint avec ses frères; ils passèrent à Sichem, et les hommes de Sichem espérèrent en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Ils sortirent dans les champs, ils vendangèrent et ils pressurèrent le raisin, et ils formèrent des chœurs de danse. Ils firent des offrandes en la maison de leur dieu, ils mangèrent, ils burent, et ils maudirent Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Et Gaal, fils de Jobel, dit: Qu’est donc Abimélech? quel est ce fils de Sichem pour que nous lui soyons asservis? N’est-il pas fils de Jérobaal? n’est-ce pas son serviteur Zébul qui vous surveille, vous et les fils d’Emmor, père de Sichem? Pourquoi donc leur serions-nous asservis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Que l’on remette le peuple entre mes mains, et j’expulserai cet Abimélech, et je lui dirai: Complète ton armée et sors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Or, Zébul, chef de la ville, apprit les discours de Gaal, fils de Jobel, et il en fut courroucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Et il dépêcha secrètement des messagers à Abimélech, disant: Voilà que Gaal, fils de Jobel, et ses frères, sont venus à Sichem, et ils campent autour de la ville contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Maintenant, pars au milieu de la nuit, avec la partie du peuple qui est pour toi, et dresse-leur une embuscade dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Demain, au lever du soleil, tiens-toi prêt, étendstoi vers la ville; il marchera contre toi avec sa suite; alors tu lui feras tout le mal que tu pourras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Abimélech et tous ses adhérents partirent donc au milieu de la nuit, et, formant quatre troupes, ils dressèrent une embuscade contre Sichem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'De son côté, Gaal, fils de Jobel, se mit en mouvement et se rangea près de la porte de la ville; bientôt, Abimélech et sa troupe sortirent de leur embuscade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Quand Gaal, fils de Jobel, vit des hommes en armes, il dit à Zébul: Voilà que des hommes descendent du sommet des montagnes; et Zébul lui dit: Tu prends pour des hommes l’ombre des montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Et Gaal continua de parler, et il dit: Voilà que des hommes descendent du côté de la mer et ils sortent des entrailles de la terre, et une autre troupe s’avance par la route d’Hélon-Maonenim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Et Zébul lui dit: Qu’est devenue ta langue; ne disais-tu pas Qu’est donc cet Abimélech, pour que nous lui soyons asservis? N’est-ce point là l’armée que tu comptais pour rien? Marche maintenant, et livre-lui bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Et Gaal alla au-devant des hommes de Sichem, et il combattit Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Mais Abimélech le poursuivit, et il s’enfuit devant Abimélech, et beaucoup de morts tombèrent jusqu’à la porte de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Abimélech entra ensuite dans Arma, et Zébul chassa Gaal et ses frères, qui ne purent demeurer à Sichem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Le lendemain, le peuple, à son tour, sortit dans les champs, et l’on en instruisit Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Il prit ses hommes, les divisa en trois troupes, et les mit en embuscade dans les champs; lorsqu’il vit le peuple sortir de la ville, il marcha contre lui, et il fut vainqueur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimélech et ses chefs poussèrent en avant, et ils s’arrêtèrent près des portes de la ville; en même temps les chefs des deux autres troupes se déployèrent contre tous ceux qui étaient dans les champs, et ils les vainquirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abimélech, tout ce jour-là, fut aux prises avec la ville; il s’en rendit maître, il massacra tout le peuple qu’elle renfermait; il la détruisit, et il y sema du sel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Tous les hommes de la tour de Sichem l’ouïrent, et ils se rassemblèrent en Béthelbérith;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Et l’on vint dire à Abimélech que tous les hommes de la tour de Sichem étaient réunis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Aussitôt, Abimélech monta sur la montagne de Selmon, avec toutes ses forces, prit en sa main des haches, coupa un rameau, l’enleva, le mit sur ses épaules, et dit aux siens: Ce que vous me verrez faire, faites-le aussi à l’instant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Chaque homme coupa un rameau; ils suivirent tous Abimélech, ils déposèrent les rameaux autour du lieu de rassemblement, et ils y mirent le feu, et ils brûlèrent tous les hommes du rassemblement. Ainsi tous ceux de la tour de Sichem périrent; environ mille hommes et femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Abimélech partit de Béthelbérith, assiégea Thèbes et la prit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Il y avait au milieu de la ville une forte tour, où tous les hommes et les femmes de la ville se réfugièrent; ils fermèrent les portes sur eux, et ils montèrent sur la plate-forme de la tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Abimélech alla jusqu’à la tour, l’investit, et s’approcha de la porte de la tour, afin de la brûler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Mais, une femme jeta un éclat de meule sur la tête d’Abimélech, et elle lui brisa le crâne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Il cria aussitôt pour appeler le serviteur qui portait ses armes, et il lui dit: Tire mon épée et tue-moi, de peur que l’on ne dise: Une femme l’a tué. Et son serviteur le transperça, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Et les hommes d’Israël virent qu’Abimélech était mort, et chacun retourna en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Ainsi, Dieu fit retomber sur Abimélech sa cruauté envers sa famille paternelle, et le meurtre de ses soixantedix frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Et Dieu fit retomber sur la tête des hommes de Sichem toute leur méchanceté, et il accomplit contre eux la malédiction de Joatham, fils de Jérobaal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Après la mort d’Abimélech, un fils de son oncle maternel fut suscité pour sauver Israël: ce fut Thola, fils de Phua, de la tribu d’Issachar; il demeurait à Samir, dans les montagnes d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Il jugea Israël vingt-trois ans; puis, il mourut, et il fut enseveli à Samir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Après lui, s’éleva Jaïr de Galaad, qui jugea Israël vingt-deux ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Il avait trente-deux fils qui montaient sur trentedeux poulains, et trente-deux villes leur appartenaient; on appelle ces villes, encore de nos jours, les cités de Jaïr, en la terre de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Jaïr mourut, et il fut enseveli à Rhamnon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Alors, les fils d’Israël recommencèrent à faire le mal devant le Seigneur; ils servirent les Baal, les Astaroth, les dieux d’Aram, les dieux de Sidon, les dieux de Moab, les dieux des fils d’Ammon, et les dieux des Philistins; ils abandonnèrent le Seigneur, et ils ne le servirent plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Et le Seigneur se courrouça contre Israël, il les livra aux mains des Philistins et des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'En ce temps-là, ceux-ci opprimèrent et meurtrirent les fils d’Israël, durant dix-huit années; c’est-à-dire tous les fils d’Israël, au delà du Jourdain, en la terre des Amorrhéens qui est celle de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Ensuite, les fils d’Ammon traversèrent le Jourdain pour combattre Juda, Benjamin et Ephraïm; et les fils d’Israël furent grandement affligés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Et les fils d’Israël crièrent au Seigneur, disant: Nous avons péché contre vous, parce que nous avons abandonné Dieu pour servir Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Et le Seigneur dit aux fils d’Israël: Ne vous ai-je point sauvés de l’Égypte, de l’Amorrhéen, des fils d’Ammon, des Philistins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Des Sidoniens, d’Amalec, de Madian, de tous ceux qui vous ont opprimés? N’avez-vous point crié au Seigneur? ne vous ai-je point délivrés de leurs mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Ne m’avez-vous point abandonné pour servir d’autres dieux? À cause de cela, je ne vous sauverai plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Allez, criez aux dieux que vous vous êtes choisis, qu’ils vous sauvent au temps de votre affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Et les fils d’Israël dirent au Seigneur: Nous avons péché, traitez-nous comme il sera bon à vos yeux, seulement délivrez-nous aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Et ils expulsèrent du milieu du peuple les dieux étrangers, et ils servirent le Seigneur seul, et son âme s’apaisa à cause de l’anxiété d’Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Et les fils d’Ammon vinrent camper en Galaad; et les fils d’Israël se réunirent et campèrent sur une cime élevée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Le peuple et les fils de Galaad se dirent entre eux: Quel est l’homme qui le premier livrera bataille aux fils d’Ammon, et qui sera le chef de tous ceux qui habitent Galaad?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jephté, fils de Galaad, était un homme très-fort; il était né d’une prostituée qui l’avait eu de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Or, la femme de Galaad avait enfanté pour celui-ci des fils; et les fils de cette femme devinrent grands, et ils chassèrent Jephté, et ils lui dirent: Tu n’auras point part à l’héritage de notre père, parce que tu es le fils d’une prostituée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Jephté s’enfuit donc de devant la face de ses frères, et il demeura en la terre de Tob. Et des hommes dénués de tout se rassemblèrent autour de Jephté, et ils sortirent avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Lorsque les fils d’Ammon furent en guerre avec Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Les anciens de Galaad allèrent prendre Jephté en la terre de Tob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Et ils dirent à Jephté: Viens, tu seras notre chef, et nous livrerons bataille aux fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Et Jephté dit aux anciens de Galaad: N’est-ce point vous qui m’avez haï, et qui m’avez expulsé de la maison paternelle, et qui m’avez chassé loin de vous? Pourquoi donc êtes-vous venus ici, maintenant que vous avez besoin de moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Et les anciens de Galaad dirent à Jephté: Nous sommes venus te trouver, pour que tu viennes avec nous, que tu combattes les fils d’Ammon, et que tu sois le chef de tous ceux qui habitent Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Et Jephté dit aux fils de Galaad: Si vous m’emmenez pour livrer bataille aux fils d’Ammon, et si le Seigneur me les livre, vous me laisserez dominer sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Et les anciens de Galaad dirent à Jephté: Que le Seigneur soit témoin entre nous, si nous n’agissons pas selon ta parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Jephté partit donc avec les anciens de Galaad; le peuple le mit à sa tête et le reconnut pour chef; et Jephté dit toutes ses paroles devant le Seigneur en Massépha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Et Jephté dépêcha des envoyés au roi des fils d’Ammon, disant: Qu’y a-t-il entre moi et toi, pour que tu viennes ici apporter la guerre en ma contrée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Le roi des fils d’Ammon dit aux envoyés de Jephté Parce qu’Israël, en venant d’Égypte, s’est emparé de mon territoire depuis l’Arnon jusqu’au Jaboc, et jusqu’au Jourdain; maintenant rends-nous-le pacifiquement, et je me retirerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jephté insista, et il dépêcha au roi des fils d’Ammon des envoyés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Qui lui dirent: Voici ce que dit Jephté: Israël n’a point pris la terre de Moab, ni la terre des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'En venant de l’Égypte, Israël a traversé le désert jusqu’à la mer de Siph, et est arrivé à Cadès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'De là, Israël a envoyé des messagers au roi d’Edom, disant: Je passerai par ta terre, et le roi d’Edom ne les a pas écoutés; et Israël a envoyé au roi de Moab, qui n’a pas voulu acquiescer à leur demande. Et Israël a campé en Cadès;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Puis, il s’est avancé par le désert; il a tourné autour de la terre d’Edom et de la terre de Moab; il a passé à l’orient de la terre de Moab, il a dressé ses tentes au delà du torrent d’Arnon; mais il n’est point entré en Moab, puisque l’Arnon est hors des limites de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Après cela, Israël a envoyé des messagers à Séhon, roi des Amorrhéens, roi d’Esebon, et Israël lui a dit: Permets que nous traversions ta terre jusqu’au pays qui nous appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Séhon ne s’est pas fié à Israël pour le laisser traverser son territoire, et Séhon a rassemblé tout son peuple, et il a campé en Jasa, et il a combattu Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Le Seigneur Dieu d’Israël a livré Séhon et tout son peuple aux mains d’Israël, qui l’a accablé; et Israël a pris possession de tout le territoire de l’Amorrhéen qui habitait cette terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Depuis l’Arnon jusqu’au Jaboc, et du désert au Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Et maintenant que le Seigneur Dieu d’Israël a fait disparaître l’Amorrhéen de devant la face de son peuple Israël, ce serait toi qui prendrais son héritage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'N’est-ce point toi qui hérites de ceux dont Chamos, ton dieu, te livre l’héritage? Hériterons-nous de tous ceux que le Seigneur notre Dieu a fait disparaître de devant vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'D’ailleurs, l’emportes-tu en vaillance sur Balac, fils de Séphor, roi de Moab? Est-ce qu’il a combattu et combattu Israël? est-ce qu’il a lui fait guerre sur guerre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Lorsque Israël eut habité trois cents ans Esebon et son territoire, Arœr et son territoire, et toutes les villes auprès du Jourdain? Et pourquoi donc pendant tout ce temps ne les as-tu pas réclamées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Ce n’est donc point moi aujourd’hui qui ai failli envers toi; tu agis mal à mon égard, en apportant la guerre en ma contrée; que le Seigneur juge entre les fils d’Israël et les fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Or, le roi des fils d’Ammon ne fit point attention aux paroles que Jephté lui avait fait dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Et l’Esprit du Seigneur vint sur Jephté, qui traverṣa Galaad, Manassé, et passa au delà des hauteurs de Galaad, de l’autre côté des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Et Jephté fit un vœu au Seigneur; il dit: Si vous livrez à ma main les fils d’Ammon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Le premier qui, venant à ma rencontre, franchira les portes de ma maison, lorsque j’y retournerai après la paix, celui-là sera au Seigneur; je le lui offrirai en holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Jephté s’approcha donc des fils d’Ammon pour les combattre, et le Seigneur les livra à ses mains;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Il les écrasa dans vingt villes, depuis Arœr jusqu’à l’Arnon, et jusqu’à Ebel-Charmin; il les frappa d’une très-grande plaie, et les fils d’Ammon furent humbles devant la face des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Puis, Jephté revint à Massépha en sa maison, et voilà que sa fille en sortit à sa rencontre, avec des tambours et des chœurs; elle était son unique enfant, il n’avait point d’autre fille, ni de fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Lorsqu’il la vit il déchira ses vêtements, et il dit: Hélas! hélas! ma fille, tu m’as consterné cruellement, et toi seule causes ma consternation, car j’ai contre toi ouvert la bouche devant le Seigneur, et je ne puis m’en dédire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Et elle lui dit; Père, as-tu ouvert la bouche devant le Seigneur? Dispose de moi selon ce qui est sorti de ta bouche, puisque le Seigneur a tiré par toi vengeance des fils d’Ammon tes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Elle dit encore à son père: Que mon père exauce cette prière: Laisse à ta fille deux mois; et je partirai; et j’irai par les monts, et je pleurerai ma virginité, moi et mes compagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Et il lui dit: Pars; et il la congédia pour deux mois; elle partit, elle et ses compagnes, et elle pleura sa virginité sur les monts,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'À la fin des deux mois, elle retourna vers son père, et il accomplit en elle le vœu qu’il avait fait; or, elle ne connut point d’homme, et elle fut l’occasion d’une loi en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'D’âge en âge, les filles d’Israël s’en vont quatre jours par an pleurer la fille de Jephté, fils de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Les hommes d’Ephraïm crièrent, et ils passèrent au nord, et ils dirent à Jephté: Pourquoi donc es-tu allé combattre les fils d’Ammon, sans nous convoquer pour marcher avec toi? Nous mettrons le feu à ta maison, sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Et Jephté leur dit: Nous faisions une violente guerre aux fils d’Ammon, moi et mon peuple; je vous ai appelés, mais vous ne m’avez point délivré de leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Ainsi, j’ai vu que vous ne me sauveriez pas; j’ai confié ma vie à mes mains; j’ai attaqué les fils d’Ammon, et le Seigneur me les a livrés. Pourquoi donc aujourd’hui venez-vous me combattre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Jephté réunit ensuite tous les hommes de Galaad, et il livra bataille à Ephraïm; et les hommes de Galaad vainquirent ceux d’Ephraïm, qui avaient dit: Vous, gens de Galaad, vous êtes des fugitifs d’Ephraïm; vous demeurez au milieu d’Ephraïm et au milieu de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Galaad s’empara avant Ephraïm des gués du Jourdain; et les fuyards d’Ephraïm dirent: Laissez-nous passer; or, à chacun, les hommes de Galaad disaient: N’es-tu pas d’Ephraïm? et il répondait: Non.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Et ils lui disaient: Prononce épi; et il le prononçait mal; alors, ils le saisissaient, et le tuaient près du gué du Jourdain. En ce jour-là, quarante-deux mille hommes d’Ephraïm tombèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Ensuite, Jephté jugea Israël six ans, et il mourut, et il fut enseveli dans sa ville de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Après lui, Abessan de Bethléem jugea Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Il avait trente fils et trente filles; et il maria celles-ci hors de sa demeure, et il y amena du dehors trente filles pour ses fils; et il jugea Israël sept ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Abessan mourut, et il fut enseveli à Bethléem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Après lui, Elon, le Zabulonien, jugea Israël dix ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Il mourut, et il fut enseveli dans la ville d’Elon, en la terre de Zabulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Après lui, Abdon, fils d’Ellel, le Pharathonien, jugea Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Il avait quarante fils et trente petits-fils qui montaient sur soixante-dix poulains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Abdon, fils d’Ellel, mourut, et il fut enseveli à Pharathon en la terre d’Ephraïm, sur la montagne d’Amalec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Et les fils d’Israël recommencèrent à faire le mal devant le Seigneur, et le Seigneur les livra pendant quarante années aux mains des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Or, il y avait un homme de Saraa, d’une famille de la tribu de Dan, et il se nommait Manué, et sa femme était stérile, et elle n’avait point enfanté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Et l’ange du Seigneur apparut à la femme, et il lui dit: Femme stérile, toi qui n’avais point enfanté, voilà que tu concevras un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Maintenant, garde-toi de boire du vin ou d’autre boisson enivrante, et ne mange rien d’impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Voilà que tu as un fruit en tes entrailles, et tu accoucheras d’un fils, et le fer ne passera point sur sa tête, parce que, dès le sein de sa mère, l’enfant sera Nazir de Dieu, et c’est lui qui commencera à délivrer Israël des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'La femme rentra et elle dit à son mari: Un homme de Dieu est venu vers moi, et son aspect était, comme l’aspect d’un ange de Dieu, grandement redoutable; je ne lui ai point demandé d’où il est, et il ne m’a point dit son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Et il m’a dit: Voilà que tu as un fruit en tes entrailles, et tu accoucheras d’un fils; maintenant, ne bois ni vin ni boisson enivrante, et ne mange rien d’impur, parce que l’enfant sera consacré au Seigneur, dès les entrailles de sa mère jusqu’au jour de sa mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Et Manué pria le Seigneur, et il dit: Regardez-moi, Seigneur Adonaï; l’homme de Dieu que vous avez envoyé, qu’il vienne encore vers nous, et qu’il nous apprenne ce que nous ferons de l’enfant qui doit naître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Dieu exauça le vœu de Manué, et l’ange de Dieu vint encore auprès de la femme; or, elle était assise aux champs, et Manué son mari n’était point avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Et la femme, se hâtant, courut l’annoncer à son mari, et elle lui dit: Voilà que l’homme qui est venu vers moi l’autre jour vient de m’apparaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Et Manué se leva, suivit sa femme, arriva près de l’homme, et dit: Es-tu l’homme qui a parlé à ma femme? et l’ange répondit: Je le suis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Et Manué dit: Maintenant tu vas parler; que sera-t-il décidé concernant l’enfant? que devra-t-il faire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Et l’ange du Seigneur dit à Manué: Il s’abstiendra de tout ce que j’ai dit à la femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Il ne mangera rien de ce qui sort de la vigne; il ne boira ni vin ni boisson enivrante, il ne mangera rien d’impur, il observera tout ce que j’ai prescrit à la femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Et Manué dit à l’ange du Seigneur: Laisse-nous te retenir ici, et nous préparerons devant toi un chevreau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Mais l’ange du Seigneur dit à Manué: Si vous me retenez je ne mangerai pas de tes pains; si tu prépares un holocauste, offre-le au Seigneur. Or, Manué ne savait pas que c’était un ange du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Et Manué dit à l’ange du Seigneur: Quel est ton nom, afin que nous puissions te glorifier, quand tes paroles seront accomplies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Et l’ange du Seigneur lui répondit: Pourquoi me demandes-tu mon nom, qui est Admirable?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Alors, Manué prit le chevreau et l’oblation; puis, il les offrit au Seigneur sur une pierre; il le fit en s’écartant des usages, et Manué et sa femme regardèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Et il advint, pendant que la flamme s’élevait de l’autel jusqu’aux cieux, que l’ange du Seigneur monta dans la flamme; Manué et sa femme le virent, et ils tombèrent la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Et l’ange du Seigneur disparut aux yeux de Manué et de sa femme. Alors, Manué reconnut que c’était un ange du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Et il dit à sa femme: Nous mourrons de mort, parce que nous avons vu Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Mais sa femme lui répondit: Si le Seigneur avait voulu nous faire périr, il n’eût point pris de nos mains l’holocauste et les oblations; il ne nous eût point révélé ces choses; il ne nous eût point en cette occasion fait entendre ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Et la femme accoucha d’un fils qu’elle nomma Samson; l’enfant devint grand, et le Seigneur le bénit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Et au camp de Dan, l’Esprit du Seigneur commença à l’accompagner entre Saraa et Esthaol.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Et Samson descendit en Thamnatha, où il vit une femme parmi les filles des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Il s’en retourna, et il l’apprit à son père et à sa mère, et il dit: J’ai vu, en Thamnatha, une femme parmi les filles des Philistins; maintenant, prenez-la, et me la donnez pour femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Son père et sa mère lui répondirent: N’y a-t-il point de filles de tes frères? n’est-il point une seule femme parmi tout notre peuple, pour que tu ailles prendre femme chez des étrangers incirconcis? Et Samson dit à son père: Prends-la pour moi, parce qu’elle est à mes yeux celle qui me convient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Son père et sa mère ne savaient pas qu’il agissait par la volonté du Seigneur, et qu’il cherchait un sujet de vengeance contre les Philistins; car, en ce temps-là, les Philistins dominaient sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Samson descendit donc avec son père et sa mère en Thamnatha, et il alla seul jusqu’à la vigne de Thamnatha, et voici venir à sa rencontre un jeune lion rugissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'L’Esprit du Seigneur s’élança sur Samson, qui broya le lionceau comme il eût broyé une jeune chèvre; or, il n’avait rien dans les mains, et il ne raconta ce qu’il avait fait ni à son père ni à sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Ils reprirent leur route, et ils parlèrent à la femme; et, aux yeux de Samson, elle était celle qui lui convenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Quelque temps après, il y alla de nouveau, afin de l’épouser, et il se détourna pour voir le cadavre du lion, et voilà qu’il y avait dans sa gueule un essaim d’abeilles et du miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Il prit du miel dans ses mains, et il s’en alla en mangeant. Quand il eut rejoint son père et sa mère, il leur en donna, et ils en mangèrent; mais il ne dit point qu’il l’avait pris dans la gueule du lion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Son père descendit auprès de la femme; et là, Samson prépara un festin pour sept jours, parce qu’ainsi font les jeunes gens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Quand les gens le virent, ils invitèrent trente convives, et ceux-ci se tinrent auprès de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Et Samson leur dit: Je vous propose une énigme; si vous la devinez très-bien, pendant ces sept jours de festin, et si vous l’expliquez, je vous donnerai trente suaires et trente tuniques pour vous vêtir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Si vous ne pouvez me l’expliquer, vous me donnerez trente vêtements de lin et trente tuniques changeantes. Et ils répondirent: Propose ton énigme, que nous l’entendions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Et il leur dit: L’aliment a été tiré du mangeur; la douceur de la force. Or, ils passèrent trois jours sans pouvoir expliquer l’énigme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Le quatrième jour, ils dirent à la femme de Samson: Trompe ton mari, et qu’il t’explique l’énigme; sinon nous te livrerons aux flammes, toi et la maison de ton père. Est-ce que vous nous avez invités pour nous extorquer nos biens?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Alors, la femme de Samson pleura auprès de lui, et elle lui dit: Sans doute tu me hais; tu ne m’aimes point, puisque tu ne m’as pas expliqué l’énigme que tu as proposée aux enfants de mon peuple. Samson répondit: Si je ne l’ai expliquée ni à mon père ni à ma mère, te l’expliquerai-je à toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Et elle pleura auprès de lui pendant le reste des sept jours que dura le festin; le septième jour, il lui expliqua l’énigme, parce qu’elle ne cessait de le troubler; et elle l’expliqua aux enfants de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Les hommes de la ville lui dirent donc le septième jour, avant le lever du soleil: Qu’y a-t-il de plus doux que le miel? Qu’y a-t-il de plus fort que le lion? Et Samson leur dit: Si vous n’aviez point labouré avec ma génisse, vous ne sauriez point mon énigme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Aussitôt, l’Esprit du Seigneur s’élança sur lui; il alla en Ascalon, il y tua trente hommes, il prit leurs vêments, et il donna leurs tuniques changeantes à ceux qui avaient expliqué l’énigme. Et Samson fut courroucé, et il revint à la maison de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Et la femme de Samson épousa l’un des amis qu’il aimait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Après cela, au temps de la moisson du froment, Samson partit avec un chevreau pour visiter sa femme, et il dit: Je veux entrer auprès de ma femme dans la chambre nuptiale; mais son beau-père ne lui permit pas d’entrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Il le retint, disant: J’ai pensé que tu la haïssais, et je l’ai donnée à l’un de tes amis; n’a-t-elle pas une sœur plus belle et plus jeune? Qu’elle soit ta femme, au lieu de la première.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Et Samson leur dit: Je suis irrépréhensible cette fois; je suis innocent, cette fois encore, à l’égard des Philistins, en leur faisant du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Et Samson s’en étant allé, prit trois cents renards et trois cents torches; il accoupla les renards côte à côte, et il attacha une torche entre deux queues;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Puis, il alluma les torches, et il lança les renards au milieu des blés des Philistins; les blés furent brûlés depuis le sol jusqu’à l’épi, et la flamme atteignit les vignes et les oliviers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Les Philistins dirent: Qui a fait cela? Et on leur répondit: C’est Samson, l’époux de Thamni, parce que le père de celle-ci lui a pris sa femme et l’a donnée à l’un de ses amis. Et les Philistins partirent, et ils la livrèrent aux flammes, elle et la maison de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Et Samson dit: Puisque vous l’avez traitée de la sorte, certes, j’en tirerai vengeance sur vous, jusqu’à ce qu’il me plaise de cesser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Et il les frappa en les bouleversant; ce fut une plaie très-grande; ensuite, il alla s’établir dans le souterrain de la roche d’Etam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Les Philistins, s’étant mis en campagne, campèrent en Juda, et ils essuyèrent un échec au lieu dit la Mâchoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Et Juda leur dit: Pourquoi avez-vous marché contre nous? Ils répondirent: Nous sommes venus pour exterminer Samson et le traiter comme il nous a traités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Trois mille hommes de Juda descendirent alors à la caverne de la roche d’Etam, et ils dirent à Samson: Ne sais-tu pas que les Philistins nous dominent? Pourquoi donc nous as-tu amené cette affaire? Et Samson leur dit: Je les ai traités comme ils m’avaient traité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Et ils lui dirent: Nous sommes descendus pour te lier et te remettre en leurs mains. Et Samson leur dit: Jurez que vous-mêmes, vous n’êtes point venus contre moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Ils lui répondirent: Nullement, mais nous allons te charger de liens pour te livrer à eux, et nous ne te tuerons pas. Ils le lièrent donc avec deux cordes neuves, et ils l’enlevèrent de cette roche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'De là, ils allèrent jusqu’au lieu dit la Mâchoire, et les Philistins jetèrent de grands cris, et ils accoururent à sa rencontre. Aussitôt, l’Esprit du Seigneur s’élança sur lui, et les cordes qui lui retenaient les bras furent pour lui comme de l’étoupe brûlée, les liens de ses mains se rompirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Et il trouva à terre une mâchoire d’âne, et il étendit la main, et il la ramassa, et, avec cette mâchoire, il tua mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Et Samson dit: Avec une mâchoire d’âne, je les ai détruits, et je les ai détruits; avec une mâchoire d’âne, j’ai tué mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Lorsqu’il eut cessé de parler et qu’il eut jeté la mâchoire, il appela ce lieu l’Élévation de la Mâchoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Il avait bien soif et il pleura devant le Seigneur, et il dit Il vous a plu d’opérer cette grande délivrance par la main de votre serviteur; vais-je maintenant mourir de soif et retomber entre les mains des incirconcis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Et le Seigneur ouvrit le creux de la mâchoire, et de l’eau en jaillit, et Samson but, et il ranima ses esprits, et il revint à la vie. À cause de cela, on donna à cette source le nom de Fontaine de l’Invocation, et encore de nos jours elle existe au lieu dit la Mâchoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Or, Samson jugea vingt ans Israël aux jours des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Et Samson alla à Gaza, où il vit une femme prostituée, chez laquelle il entra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Des gens l’apprirent aux hommes de Gaza, disant: Samson est venu ici. Et ils l’entourèrent, et ils l’épièrent à la porte de la ville, et ils ne bougèrent de toute la nuit, disant Quand l’aurore brillera, nous le tuerons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Samson resta couché jusqu’à minuit, et, s’étant levé au milieu de la nuit, il prit les portes de la ville avec les deux jambages; puis, les soulevant à l’aide du verrou, il les mit sur ses épaules. Alors, il monta au sommet de la montagne qui fait face à Hébron, où il les déposa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Après cela, il aima une femme d’Alsorech, dont le nom était Dalila.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Et les chefs des Philistins allèrent trouver cette femme, et ils lui dirent: Trompe-le; découvre en quoi réside sa grande force, et comment nous prévaudrons sur lui; puis, nous l’enchaînerons afin de l’humilier. Et nous te donnerons chacun onze cents sicles d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Dalila dit donc à Samson: Fais-moi connaître en quoi réside ta grande force, et comment tu pourrais être enchaîné et vaincu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Samson lui dit: Si l’on m’attachait avec sept cordes humides, nullement altérées, je serais énervé, et je ressemblerais à un autre homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Les chefs des Philistins lui apportèrent sept cordes humides, nullement altérées; et, avec ces cordes, elle l’attacha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Et ils se tenaient cachés dans sa chambre, et elle lui dit: Voici les Philistins, Samson. Et il rompit les cordes comme on brise une tresse d’étoupes, dès qu’on lui fait sentir le feu; et la cause de sa force resta inconnue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Et Dalila dit à Samson: Voilà que tu m’as trompée en me disant des mensonges. Apprends-moi, maintenant, avec quels liens il faudrait t’enchaîner?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Et il lui dit: Si l’on me liait de cordes neuves, avec lesquelles on n’ait encore fait aucune œuvre, je serais énervé et je ressemblerais à un autre homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Et Dalila prit des cordes neuves, et, avec ces cordes, elle l’attacha. Cependant, les chefs sortirent de leur cachette, et elle dit: Voici les Philistins, Samson. Il rompit les cordes autour de ses bras comme de l’étoupe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Et Dalila dit à Samson: Voilà que tu m’as trompée en me disant des mensonges; apprends-moi avec quels liens il faudrait t’enchaîner. Et il lui répondit: Si tu faisais un tissu des sept tresses de ma tête et d’une chaîne de fil, si tu l’enfonçais dans le mur, en le maintenant par un clou, je serais aussi faible qu’un autre homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Dès qu’il fut endormi, Dalila prit les sept tresses de sa tête; elle en fit un tissu avec une chaîne de fil, elle fixa ce tissu dans le mur à l’aide d’un clou, et elle dit: Voici les Philistins, Samson. Soudain, il sortit de son sommeil, et il arracha du mur le clou du tissu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Et Dalila dit à Samson: Comment dis-tu: Je t’aime, quand ton cœur n’est point avec moi? Tu m’as trois fois trompée, et tu ne m’as point appris en quoi réside ta grande force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Elle en vint donc à le poursuivre de ses paroles pendant des jours entiers, à le tourmenter, à affaisser son courage, jusqu’à le réduire à l’extrémité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Et il lui ouvrit sans réserve son cœur, et il lui dit: Jamais le fer n’a passé sur ma tête, parce que, depuis les entrailles de ma mère, je suis consacré au Seigneur; lors donc qu’on me rasera, ma force s’évanouira; je serai énervé, et je ressemblerai à un autre homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Dalila vit bien qu’il lui avait ouvert son cœur sans réserve, et elle envoya chercher les chefs des Philistins, disant Venez, cette fois encore, car il m’a ouvert son cœur sans réserve. Et les chefs des étrangers allèrent auprès d’elle, et ils apportèrent l’argent dans leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Et Dalila endormit Samson sur ses genoux; puis, elle appela un homme qui rasa les sept tresses de sa tête; et elle fut la première à l’humilier, car sa force s’était évanouie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Dalila dit: Voici les Philistins, Samson. Et il s’éveilla, se disant: J’en sortirai comme les autres fois, et je saurai me délivrer; car il ignorait que le Seigneur s’était retiré de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Mais les Philistins le saisirent, lui arrachèrent les yeux, et le transportèrent à Gaza, où ils le mirent en prison avec des entraves d’airain aux pieds; enfin, ils lui firent tourner la meule, dans la maison du geôlier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Et sa chevelure commença à repousser après qu’il eut été rasé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Et les chefs des Philistins étaient réunis pour offrir un grand sacrifice à Dagon leur dieu, et pour se réjouir. Dieu a livré, disaient-ils, à nos mains Samson notre ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Et le peuple l’a vu, et il a chanté en l’honneur de son dieu, parce qu’il avait livré à ses mains l’ennemi, celui qui faisait de la patrie un désert, et qui multiplia it les morts parmi nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Lorsque leur cœur se fut ainsi réjoui, ils dirent: Faites venir Samson de la geôle, pour qu’il nous serve de jouet. L’on fit donc venir Samson de la maison du geôlier, et il leur servit de jouet; ils le souffletèrent, et ils le placèrent entre les colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Et Samson dit au jeune homme qui le menait par la main Fais-moi toucher les colonnes sur lesquelles repose le temple, et je m’y appuierai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Or, le temple était rempli d’hommes et de femmes; il y avait là tous les chefs des Philistins, et, sur la plateforme, environ trois mille hommes et femmes, qui regardaient Samson et le jeu qu’on faisait de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Et Samson pleura devant le Seigneur, et il dit: Seigneur Adonaï, souvenez-vous de moi, et me rendez encore une fois mes forces, ô mon Dieu! qu’une fois au moins je tire vengeance des Philistins, pour mes deux yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Et Samson saisit les deux colonnes du temple sur lesquelles reposait l’édifice et où il s’était appuyé; il en prit une de la main droite, l’autre de la main gauche;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Et Samson dit: Mort à moi et aux Philistins! Puis, il ébranla les colonnes avec force; le temple s’écroula sur les chefs et sur le peuple qu’il contenait. Et Samson en mourant fit périr plus d’hommes qu’il n’en avait tué pendant sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Ses frères et la famille de son père vinrent le prendre. Et ils s’en retournèrent, et ils l’ensevelirent entre Saraa et Esthaol, dans le sépulcre de Manué son père. Or, il avait jugé Israël vingt ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Il y avait, dans les montagnes d’Ephraïm, un homme qui se nommait Michas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Et il dit à sa mère: Les onze cents sicles d’argent que tu as pris pour toi, et au sujet desquels tu m’as adjuré avec des imprécations, en me disant: « Vois, l’argent est avec moi; » ces sicles, je les ai pris. Et sa mère répondit: Béni soit mon fils, au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Et il rendit à sa mère les onze cents sicles d’argent, et sa mère s’écria: J’ai consacré au Seigneur cet argent, qui passe de ma main en celle de mon fils, pour qu’on en fasse une sculpture et un ouvrage en fonte, et je te le remettrai tout à l’heure à cet effet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Et il rendit l’argen\' à sa mère, qui en prit deux cents sicles pour les donner à un orfévre; celui-ci en âît une sculpture et un ouvrage en fonte; après quoi, ces images restèrent en la maison de Michas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'La maison de Michas était pour lui la maison de Dieu; il fit un éphod, des théraphim, et il remplit la main de l’un de ses fils qui fut chez lui le prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'En ces jours-là, il n’y avait point de roi en Israël; chacun faisait ce qui était droit à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Or, il y avait un jeune homme de Bethleem en Juda qui était lévite, et demeurait là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Cet homme, étant parti de Bethléem, ville de Juda, afin de demeurer en un autre lieu à son gré, atteignit les montagnes d’Ephraïm, et il trouva sur son chemin la maison de Michas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Et Michas lui dit: D’où viens-tu? Et il lui dit: Je suis lévite de Bethléem en Juda; je vais demeurer en un autre lieu à mon gré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Et Michas lui dit: Reste avec moi; sois pour moi un père et un prêtre, je te donnerai dix sicles par jour, avec des vêtements et ce qui sert à la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Le lévite entra donc; il commença à demeurer auprès de l’homme, et le jeune homme fut pour lui comme l’un de ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Michas remplit la main du lévite; celui-ci fut chez lui le prêtre, et il fit partie de la maison de Michas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Alors, Michas dit: Je reconnais maintenant que le Seigneur me favorise, puisqu’un lévite est prêtre chez moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'En ce temps-là, il n’y avait point de roi en Israël, et la tribu de Dan cherchait un héritage où elle pût demeurer, parce que, jusqu’à ces jours-là, il ne lui était point échu d’héritage au milieu des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Les fils de Dan envoyèrent donc de Saraa et d’Esthaol cinq hommes vaillants de leurs familles, afin d’explorer la terre et de l’observer avec soin; et ils leur dirent: Allez, et observez avec soin la terre. Et les hommes allèrent dans les montagnes d’Ephraïm, jusqu’à la maison • de Michas, et ils logèrent');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'En la maison de Michas; là, ayant entendu la voix du jeune lévite, ils allèrent à lui, et lui dirent: Qui t’a amené ici? Que fais-tu en ce lieu? Comment y es-tu traité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Il leur répondit: Voici comment me traite Michas: il me salarie, et je suis chez lui le prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Et ils lui dirent: Consulte donc Dieu, pour que nous sachions si le voyage que nous avons entrepris réussira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Et le prêtre leur dit: Allez en paix, le voyage que vous faites est sous la protection du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Ensuite, les cinq hommes partirent; ils arrivèrent à Laïs, et ils virent un peuple qui y demeurait sans inquiétude, tranquille comme le pays des Sidoniens; il était en paix sans que personne vînt l’effrayer ou le troubler en quoi que ce fût. Il n’y avait pas là de maître pour extorquer ses richesses; il était d’ailleurs éloigné des Sidoniens, et sans rapport avec les autres hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Et les cinq hommes revinrent auprès de leurs frères en Saraa et en Esthaol, et ils dirent à leurs frères: Pourquoi restez-vous ici?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Ils ajoutèrent: Levez-vous, et marchons contre eux; nous avons vu une terre qui est excellente, et vous vous tenez en repos! Ne tardez pas à partir et à vous mettre en possession de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Aussitôt que vous serez arrivés, vous entrerez chez un peuple qui demeure sans inquiétude en une vaste terre que le Seigneur a livrée à nos mains, où rien ne manque de ce que produit la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Alors, six cents hommes bien armés, tous des familles de Dan, partirent de Saraa et d’Esthaol.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Ils montèrent et ils campèrent sur le territoire de Cariathiarim en Juda. À cause de cela, ce lieu s’appelle encore de nos jours le camp de Dan; il est derrière Cariathiarim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Ils traversèrent ensuite les montagnes d’Ephraïm, et arrivèrent auprès de la maison de Michas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Et les cinq hommes qui avaient été envoyés à la découverte en Laïs, s’expliquèrent; ils dirent à leurs frères Sachez qu’il y a en cette maison un éphod, et des théraphim, et une sculpture et un ouvrage en fonte; voyez maintenant ce que vous ferez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Les cinq hommes y allèrent, et entrèrent dans la maison où était le jeune lévite, chez Michas, et ils questionnèrent le lévite pacifiquement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Cependant, les six cents hommes en armes se tenaient près de la porte de la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Et les cinq hommes, qu’on avait envoyés d’abord à la découverte, étaient entrés chez Michas, où le prêtre se trouvait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Ceux-ci saisirent l’éphod, et les théraphim, et la sculpture et l’ouvrage en fonte, et le prêtre leur dit: Que faites-vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Et ils lui dirent: Garde le silence, mets ta main sur ta bouche; viens avec nous, sois pour nous un père et un prêtre; ne vaut-il pas mieux pour toi être le prêtre d’une tribu et de la maison d’une famille d’Israël, que le prêtre de la maison d’un seul homme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Le cœur du prêtre se réjouit; il prit l’éphod, et les théraphim, et la sculpture et l’ouvrage en fonte, et il se rendit au milieu de la troupe en armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Tous ensemble se remirent en marche; ils s’éloignèrent ayant placé en avant les enfants, le bétail et les bagages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Ils étaient déjà à une certaine distance de la maison de Michas, quand Michas et les hommes des maisons voisines de la maison de Michas, jetant de grands cris, atteignirent les fils de Dan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Les fils de Dan firent volte-face, et ils dirent à Michas: Qu’as-tu? Pourquoi jettes-tu ces cris?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Et Michas répondit: Vous avez pris la sculpture que j’avais faite; vous emmenez le prêtre, et que me restet-il? Comment pouvez-vous me dire: Pourquoi jettes-tu ces cris?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Et les fils de Dan lui dirent: Que ta voix n’arrive plus jusqu’à nous, de peur que des hommes irrités, courant sur vous, ne prennent ta vie et la vie de toute ta famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Puis, les fils de Dan se remirent en marche; Michas, voyant qu’ils étaient les plus forts, s’en retourna chez lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Et les fils de Dan emportèrent ce qu’avait fabriqué Michas; ils emmenèrent le prêtre qui demeurait avec lui, et ils arrivèrent à Laïs chez un peuple paisible, plein de sécurité; ils le passèrent au fil de l’épée, et ils livrèrent la ville aux flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Il n’y avait là personne pour défendre ce peuple; car il était loin de Sidon, sans rapport avec les autres hommes, et il vivait dans la vallée de la maison de Rhaab; les fils de Dan rebâtirent la ville, où ils demeurèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Et ils appelèrent la ville: Dan, du nom de leur père, fils d’Israël; car, auparavant, elle se nommait Ulamaïs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Les fils de Dan y dressèrent la statue. Et Jonathan, fils de Gerson, fils de Manassé, lui et ses fils furent prêtres de la tribu de Dan, jusqu’au jour de sa captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Et ils se servirent pour eux de la statue que Michas avait faite, tout le temps que la maison de Dieu fut à Silo. En ces jours-là, il n’y avait point de roi en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Or, il y avait dans les montagnes d’Ephraïm un lévite qui prit une femme concubine de Bethleem en Juda;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Puis, sa femme le quitta pour s’en retourner à la maison de son père, à Bethléem en Juda; elle y était depuis quatre mois entiers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Quand son mari, s’étant levé, s’en alla vers elle pour parler à son cœur et la ramener avec lui; il emmenait son serviteur et deux ânes. Elle l’introduisit dans la maison de son père; le père de la jeune femme le vit, et il fut joyeux de la rencontre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Le beau-père du lévite, le père de la jeune femme retint son gendre, qui resta avec lui trois jours; ils mangèrent, ils burent et ils logèrent chez lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Le quatrième jour parut; et, s’étant levés de grand');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Tous les deux s’assirent donc, ils mangèrent et burent ensemble, et le père de la jeune femme dit à l’époux Allons, passe ici la nuit, et ton cœur s’en trouvera bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Mais l’homme se leva pour partir; puis, son père le contraignant, il s’assit, et il passa la nuit dans la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Le cinquième jour, il se leva de grand matin pour s’en aller, et le père de la jeune femme lui dit: Fortifie ton cœur, reste ici jusqu’au déclin du jour. Et ils mangèrent ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Quand l’homme se leva pour partir avec sa femme et son serviteur, son beau-père, le père de la jeune femme lui dit: Voilà que le jour décline vers le soir, passe la nuit avec nous, et ton cœur s’en trouvera bien; demain, vous vous lèverez de grand matin, et tu retourneras en ta demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mais l’homme ne consentit point à passer là encore une nuit; il se leva et partit, et il alla jusqu’en face de Jébus, la même que Jérusalem; il avait avec lui ses deux ânes chargés, et sa femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Ils poussèrent donc jusqu’à Jébus. Or, le jour était bien avancé, et le serviteur dit à son maître: Viens, et nous entrerons dans cette ville de Jébus, et nous y passerons la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Le maître lui dit: N’entre pas dans une ville étrangère, où il n’y a point de fils d’Israël; allons jusqu’à Gabaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Puis, il ajouta: Allons, approchons-nous de l’une de ces deux villes; nous logerons à Gabaa ou à Rhama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Et, passant outre, ils marchèrent; le soleil se coucha comme ils traversaient le territoire de Gabaa, qui est de la tribu de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Ils entrèrent en cette ville pour y passer la nuit; et étant entrés, ils s’assirent sur la place de la ville. Or, il n’y eut pas un homme qui les conduisît dans sa maison afin de les loger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Cependant, un homme âgé revenait, sur le tard, de ses travaux des champs, et cet homme était des montagnes d’Ephraïm; il habitait Gabaa, et les hommes de cette ville étaient des fils de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Il leva les yeux, et il vit le voyageur sur la place de la ville; alors, l’homme âgé lui dit: Où vas-tu, et d’où es-tu parti?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Et le lévite lui répondit: Nous allons de Bethleem en Juda, aux montagnes d’Ephraïm. Je suis de ce lieu; j’étais allé à Bethléem en Juda, et je retourne à ma maison, et il n’y a pas ici un homme qui me conduise en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Cependant, nous avons pour nos ânes de la litière et du fourrage; nous avons du pain et du vin pour moi, ta servante et le jeune homme; aucune chose ne manque donc à tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Alors, l’homme âgé reprit: La paix soit avec toi; d’ailleurs, tu trouveras chez moi tout ce dont tu as besoin; tu ne passeras pas la nuit sur cette place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Et il l’introduisit dans sa maison, où il prépara un endroit pour loger ses ânes; puis, ils se lavèrent les pieds, et ils mangèrent et ils burent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Ils étaient donc à se réjouir le cœur. Or, voilà que les hommes de la ville, fils de parents pervers, entourèrent la maison, frappèrent à la porte, et dirent à l’homme, au maître de la maison, au vieillard: Amènenous l’homme qui est entré en ta demeure, afin que nous le connaissions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Et le maître de la maison sortit auprès d’eux, et il dit: Mes frères, ne maltraitez pas cet homme, après qu’il est entré dans ma maison; ne commettez pas une action si insensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'J’ai une fille vierge, et lui a une femme; je vais vous les amener: déshonorez-les, traitez-les comme bon vous semblera; mais, avec cet homme, ne faites pas l’action insensée que vous dites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mais les hommes ne consentirent point à l’écouter; enfin, le lévite prit sa femme, et il la leur conduisit au dehors; ils la connurent et l’outragèrent toute la nuit jusqu’au matin, et ils la renvoyèrent lorsqu’ils virent poindre le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Et la femme s’en fut à l’aurore; elle tomba devant la porte de la maison où était son mari, elle y resta jusqu’au jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Le lévite se leva dès le matin; il ouvrit la porte de la maison, il sortit pour reprendre sa route, et voilà que la femme, sa concubine, était étendue devant la porte de la maison, les mains sur le seuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Et il lui dit: Lève-toi, et partons. Elle ne répondit point, car elle était morte. Et il la plaça sur un âne, et il l’emmena où il demeurait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Là, saisissant son glaive, il prit sa femme, et il la divisa en douze parts, qu’il envoya par tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Et tout homme qui les vit s’écria: Jamais, depuis le jour où les fils d’Israël sortirent d’Égypte jusqu’à celuici, pareille chose ne s’est vue. Tenez conseil au sujet de cette femme, et parlez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Tous les fils d’Israël sortirent, depuis Dan jusqu’à Bersabée, y compris la terre de Galaad; la synagogue se réunit comme un seul homme devant le Seigneur à Massépha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Toutes les tribus d’Israël se formèrent devant le Seigneur, en assemblée du peuple de Dieu, au nombre de quatre cent mille hommes à pied, en état de porter les armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Or, les fils de Benjamin apprirent que les fils d’Israël étaient allés en Massépha; ils y vinrent, et les fils d’Israël leur dirent Expliquez-vous: où ce crime a-t-il été commis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Le lévite, le mari de la femme tuée répondit et il dit: J’étais entré avec ma femme à Gabaa en Benjamin, pour y passer la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Quand les hommes de Gabaa se levèrent contre moi; ils m’entourèrent dans la maison où j’étais logé, voulant me mettre à mort, et ils ont outragé ma femme, et elle en est morte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Je l’ai saisie, je l’ai coupée en morceaux, et je l’ai envoyée sur toute l’étendue de l’héritage des fils d’Israël, parce qu’une souillure et une abomination ont été commises en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Voyez donc, ô vous tous fils d’Israël, tenez ici conseil, et parlez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Et tout le peuple se leva comme un seul homme, disant Nul de nous ne retournera en sa ville, nul de nous ne rentrera dans sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Dès maintenant, voilà ce qu’il faut faire contre Gabaa. Ceux que le sort va désigner marcheront sur cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Nous prendrons dix hommes sur cent de toutes les tribus d’Israël, cent sur mille, mille sur dix mille; nous les approvisionnerons de vivres, et nous les ferons partir pour Gabaa en Benjamin, afin qu’ils la traitent comme le mérite l’abomination qu’elle a commise en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Et tout Israël s’était assemblé contre la ville comme un seul homme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Et les tribus d’Israël envoyèrent, dans toute la tribu de Benjamin, des hommes qui dirent: Quel est le forfait qui a été commis parmi vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Maintenant, livrez-nous ces hommes, fils de pervers, qui se trouvent en Gabaa; nous les mettrons à mort, et nous purifierons Israël de ce crime. Mais, les fils de Benjamin ne voulurent point écouter la voix de leurs frères les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Les fils de Benjamin de toutes les villes se rassemblèrent à Gabaa, pour sortir à la rencontre des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Et, ce jour-là, les fils de Benjamin, venus de leurs villes, furent recensés au nombre de vingt-trois mille combattants, outre les habitants de Gabaa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Qui furent recensés au nombre de sept cents hommes d’élite, tous ambidextres et frondeurs habiles, lançant des pierres sans s’écarter du but de l’épaisseur d’un cheveu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Et d’Israël, hormis Benjamin, il se trouva quatre cent mille hommes portant l’épée, tous exercés aux combats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Ceux-ci se levèrent, montèrent à Béthel, consultèrent Dieu, et dirent: Qui de nous sera élevé au commandement pour livrer bataille aux fils de Benjamin? Le Seigneur répondit: Juda sera votre chef.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Les fils d’Israël se levèrent de grand matin, et ils campèrent devant Gabaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Et tout Israël sortit du camp pour attaquer Benjamin, et ils en vinrent aux mains avec Gabaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Les fils de Benjamin sortirent de Gabaa, et détruisirent ce jour-là vingt-deux mille hommes d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Mais, Israël reprit courage, et il recommença le combat au lieu même où la veille on s’était rencontré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Or, les fils d’Israël étaient montés devant le Seigneur, et ils avaient pleuré jusqu’au soir, et ils avaient consulté le Seigneur, disant: Continueronsnous d’approcher pour combattre nos frères les fils de Benjamin? Et le Seigneur leur avait répondu: Marchez contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'En cette seconde journée les fils d’Israël marchèrent contre les fils de Benjamin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'En cette seconde journée, les fils de Benjamin sortirent de Gabaa à leur rencontre, et dix-huit mille des fils d’Israël, tous portant l’épée, périrent encore sur le champ de bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Alors, tous les fils d’Israël, tout le peuple, montèrent en Béthel, et ils pleurèrent, et ils s’assirent devant le Seigneur, et ils jeûnèrent tout le jour jusqu’au soir, et ils offrirent en holocauste des victimes sans tache,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Devant le Seigneur, car, en ce temps-là, l’arche de l’alliance du Seigneur Dieu était à Béthel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Et Phinées, fils d’Eléazar, fils d’Aaron, en ces jours-là, se tenait devant l’arche. Les fils d’Israël consultèrent donc le Seigneur, disant: Continuerons-nous de sortir pour combattre nos frères les fils de Benjamin? Et le Seigneur leur dit: Partez, demain je vous les livrerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Et les fils d’Israël dressèrent des embuscades autour de Gabaa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Et les fils d’Israel marchèrent, le troisième jour, contre les fils de Benjamin, et ils en vinrent aux mains, comme les deux autres fois, devant Gabaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Car les fils de Benjamin marchèrent à la rencontre du peuple; ils sortirent tous de la ville; ils commencèrent à faire tomber des morts dans les rangs du peuple, comme les deux autres fois, sur les chemins qui conduisent l’un à Béthel, l’autre aux champs de Gabaa. Trente hommes environ d’Israël furent atteints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Et les fils de Benjamin dirent: Ils tombent devant nous comme auparavant. Et les fils d’Israël dirent: Fuyons, attirons-les sur les chemins loin de la ville. Ainsi firent-ils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Chacun quitta son poste pour reculer jusqu’à BaalThamar; cependant l’embuscade d’Israël survint de Maraagabé, où elle se tenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Dix mille hommes d’élite, pris parmi tout Israël, arrivèrent en face de Gabaa, et la bataille fut terrible, et les fils de Benjamin ne s’aperçurent pas que le mal fondait sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Et, ce jour-là, le Seigneur frappa Benjamin devant les fils d’Israël, et les fils d’Israël détruisirent de Benjamin vingt-cinq mille cent hommes, tous portant l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Et les fils de Benjamin se virent accablés; car les fils d’Israël leur avaient fait place, comptant sur l’embuscade préparée contre Gabaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Or, pendant qu’ils avaient reculé, l’embuscade s’était ébranlée, elle s’était déployée autour de la ville, elle s’y était répandue, et elle avait passé tout au fil de l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Les fils d’Israël étaient convenus d’un signal; l’embuscade devait faire monter au-dessus de la ville une colonne de fumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Les fils d’Israël avaient ainsi reconnu que l’embuscade venait de prendre Gabaa; c’est alors qu’ils avaient engagé la bataille; d’abord Benjamin leur avait tué cent trente hommes, et il avait dit: Les voilà qui tombent encore devant nous comme à la première bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Et le signal se montrait plus évident encore au-dessus de la ville, comme une colonne de fumée. Benjamin, ayant regardé derrière lui, vit la ruine de la ville et la fumée s’élevant jusqu’au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'C’est alors qu’Israël fit volte-face, et que Benjamin s’enfuit, quand il reconnut que le mal fondait sur lui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Devant les fils d’Israël; et il tourna les yeux sur le chemin du désert et il prit la fuite; mais le combat l’atteignit, et ceux des autres villes le détruisirent pendant qu’il passait au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Ils frappèrent Benjamin, ils le poursuivirent, pied à pied, depuis Nua, jusqu’aux monts qui regardent Gabaa du côté de l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Là, dix-huit mille hommes de Benjamin périrent, tous dans la force de l’âge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Et les débris de cette armée, regardant autour d’eux, s’enfuirent au désert, du côté du rocher de Rhemmon; mais, chemin faisant, les fils d’Israël en moissonnèrent encore cinq mille; puis, les poursuivant jusqu’à Gedan, ils tuèrent en outre deux mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Tous ceux de Benjamin qui ce jour-là périrent, montèrent à vingt-cinq mille hommes portant l’épée, tous dans la force de l’âge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Et les débris de cette armée, ayant regardé autour d’eux, s’enfuirent dans le désert vers le rocher de Rhemmon, au nombre de six cents hommes; ils campèrent en ce lieu pendant quatre mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Et les fils d’Israël parcourant la tribu de Benjamin passèrent tout au fil de l’épée, gens et troupeaux; tout ce qu’ils rencontrèrent périt; et les villes qui se trouvèrent sur leur route furent livrées aux flammes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Après cela, les fils d’Israël en Massépha prêtèrent ce serment: Nul de nous ne donnera sa fille en mariage à un homme de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Le peuple revint ensuite à Béthel; il y demeura jusqu’au soir devant Dieu, et ils élevèrent la voix, et ils pleurèrent amèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Et ils dirent: Seigneur, pourquoi faut-il que ce malheur soit arrivé, et que l’une des tribus ait été retranchée d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Le jour parut, et le peuple se leva de grand matin, et il bâtit en ce lieu un autel, et il offrit en holocauste des victimes sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Et les fils d’Israël dirent: Qui donc de tout le peuple n’a point paru à l’assemblée devant le Seigneur? Car ils avaient prêté un serment solennel contre ceux qui n’étaient point montés à Massépha devant le Seigneur, disant: Qu’ils soient mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Et les fils d’Israël furent touchés de regret au sujet de Benjamin, leur frère, et ils dirent: L’une des tribus aujourd’hui a été retranchée d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Que ferons-nous pour les survivants qui n’ont point de femmes, nous qui avons juré devant le Seigneur de ne point leur donner nos filles en mariage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Puis, ils dirent: Est-il quelqu’un parmi les tribus d’Israël qui ne soit point venu devant le Seigneur à Massépha? Et on leur déclara qu’il n’était venu au camp personne de Jabès-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'En effet, le peuple fut recensé, et il n’y avait là aucun des habitants de Jabès-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Aussitôt, la synagogue fit marcher deux mille vaillants hommes contre cette ville, et elle leur donna ses ordres, disant: Allez et passez au fil de l’épée les habitants de Jabès-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Voici ce que vous ferez: Tout homme et toute femme ayant connu la couche d’un homme, vous les anathématiserez; quant aux vierges, vous les réserverez. Et ils firent ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Or, ils trouvèrent parmi les habitants de Jabès-Galaad quatre cents vierges qui ne connaissaient ni les hommes, ni la couche des hommes, et ils les amenèrent au camp de Silo, en la terre de Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Alors, toute la synagogue dépêcha des envoyés qui parlèrent aux fils de Benjamin en la roche de Rhemmon, et ils les appelèrent à un entretien pacifique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'En ce temps-là, Benjamin revint aux fils d’Israël, et les fils d’Israël leur donnèrent en mariage les filles qu’ils avaient épargnées en Jabès-Galaad. Et ils l’eurent pour agréable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Cependant le peuple fut encore touché de regrets au sujet de Benjamin, parce que le Seigneur avait retranché l’une des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Et les anciens de l’assemblée dirent: Que feronsnous pour que les survivants aient des femmes? Toutes les femmes de Benjamin avaient péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Les anciens dirent encore: Que l’héritage reste à ceux de Benjamin qui survivent, et l’une des tribus d’Israël ne sera point effacée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Mais, nous ne pouvons leur accorder en mariage nos filles, puis qu’entre nous nous avons juré, disant: Maudit celui qui mariera sa fille à Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Ils ajoutèrent: C’est bientôt la fête du Seigneur que l’on a célébrée d’âge en âge à Silo (cette ville est au nord de Béthel, à l’orient du chemin qui monte de Béthel à Sichem et au midi de Lebona).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Puis, ils donnèrent leurs instructions aux fils de Benjamin, disant: Allez et cachez-vous dans les vignes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Vous observerez, et, quand vous verrez les filles des habitants de Silo sortir pour former des chœurs de danses, sortez aussi des vignes et enlevez chacun l’une des filles de Silo; emmenez-la en Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Et, lorsque leurs pères ou leurs frères viendront nous demander justice, nous leur dirons pour vous: Faites miséricorde; nul de nous n’a pu prendre femme dans le combat; vous-mêmes ne nous en avez point donné; c’est de votre part qu’est la faute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Les fils de Benjamin agirent ainsi; ils prirent autant de femmes qu’ils étaient d’hommes, parmi celles qui dansaient; après les avoir ravies, ils les emmenèrent, et ils retournèrent en leur héritage, où ils rebâtirent leurs villes et ils demeurèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Les fils d’Israël en temps-là se dispersèrent, et chacun rentra dans sa tribu, dans sa famille., dans son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Et, en ces jours-là, il n’y avait point de roi en Israël; chacun faisait ce que bon lui semblait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Du temps des juges, il y eut une famine sur la terre; et un homme partit de Bethleem en Juda, pour aller aux champs de Moab, lui, et sa femme et ses deux fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Le nom de l’homme était Elimelech, et le nom de sa femme Noémi, et les noms de ses deux fils, Maalon et Chélaïon, Ephrathéens de Bethléem en Juda. Ainsi, ils allèrent aux champs de Moab et ils y demeurèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Or, Elimelech, le mari de Noémi, mourut, et elle resta veuve avec deux fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Et ils épousèrent des femmes moabites: l’une se nommait Orpha, la seconde se nommait Ruth, et ils passèrent là dix années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Et tous les deux moururent aussi: Maalon et Chélaïon, la femme resta ainsi privée de son mari et de ses deux fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Alors, elle se leva avec ses deux brus, et elles s’en allèrent des champs de Moab, parce qu’elles y avaient appris que le Seigneur avait visité son peuple pour lui donner du pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Elle quitta donc le lieu où elle était, et ses deux brus avec elle; elles se mirent en route pour retourner en la terre de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Et Noémi dit à ses deux brus: Allez, retournez chacune en la maison de votre mère; que le Seigneur soit miséricordieux envers vous comme vous l’avez été pour nos morts et pour moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Que le Seigneur vous l’accorde, et vous retrouverez l’une et l’autre la maison d’un époux. Puis, elle les baisa, et elles élevèrent la voix, et elles se prirent à pleurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Et elles lui dirent: Nous irons avec toi chez ton peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Mais Noémi dit: Allez-vous-en, mes filles. Pourquoi viendriez-vous avec moi? Ai-je encore en mes entrailles des fils qui puissent être vos époux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Allez-vous-en, mes filles, parce que je suis trop vieille pour être avec un mari, et que du reste j’ai dit: Quand même je pourrais prendre un mari et enfanter des fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Les attendriez-vous jusqu’à qu’ils soient devenus hommes; et, poux eux, vous abstiendriez-vous d’être avec des maris? Ne venez point, mes filles; car j’ai bien de la peine à votre sujet, parce que la main du Seigneur s’est appesantie sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Et elles élevèrent la voix et elles pleurèrent encore; Orpha baisa sa belle-mère, et elle s’en retourna chez son peuple; mais Ruth suivit Noémi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Et Noémi dit à Ruth: Vois, ta sœur retourne à son peuple et à ses dieux; fais comme elle, et accompagne ta sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Et Ruth dit: Ne me parle plus de m’éloigner de toi et de t’abandonner, parce qu’où tu iras, j’irai; où tu demeureras, je demeurerai; ton peuple est mon peuple, ton Dieu est mon Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Où tu mourras, je mourrai, et c’est là que je serai ensevelie; que le Seigneur me punisse, et qu’il me punisse encore si je te quitte; car la mort seule nous séparera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Voyant donc sa ferme volonté de partir avec elle, Noémi cessa de lui parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Elles marchèrent toutes deux jusqu’à ce qu’elles arrivassent à Bethléem; et, dès qu’elles furent entrées à Bethleem, toute la ville fut en rumeur à leur sujet, et les femmes dirent: N’est-ce point Noémi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Et elle leur dit: Ne m’appelez point Noémi (belle); appelez-moi Mara (amère), parce que le Tout-Puissant m’a remplie d’amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Pleine je suis partie, et vide me renvoie le Seigneur. Pourquoi m’appelleriez-vous Noémi, puisque le Seigneur m’a humiliée et que le Tout-Puissant m’a accablée de maux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Noémi et sa bru Ruth la Moabite étaient donc revenues des champs de Moab, et elles étaient entrées à Bethleem comme on commençait à moissonner les orges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Il y avait un homme connu de Noémi et de son époux; cet homme, parent d’Elimelech, était riche, et il se nommait Booz.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Et Ruth la Moabite dit à Noémi: Je m’en vais aux champs, et je ramasserai des épis à la suite des moissonneurs, chez celui aux yeux de qui je trouverai grâce; et Noémi répondit: Va, ma fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Elle partit done, et, étant arrivée, elle glana dans un champ, derrière les moissonneurs; elle était tombée par aventure sur un endroit du champ de Booz, le parent d’Elimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Et voilà que Booz vint de Bethléem, et il dit aux moissonneurs Le Seigneur soit avec vous; et ils lui dirent Que le Seigneur te bénisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Et Booz dit à son serviteur, qui était placé au-dessus des moissonneurs: Qui est cette jeune fille?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Son serviteur, qui était placé au-dessus des moissonneurs, répondit: C’est la jeune Moabite, qui est revenue avec Noémi du champ de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Elle m’a dit: Je glanerai et je recueillerai des épis derrière les moissonneurs; et elle a glané depuis le matin jusqu’au soir, et elle n’a pas pris dans le champ un moment de repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Alors, Booz dit à Ruth: N’as-tu pas entendu, ma fille? Ne va pas glaner dans un autre champ; ne t’éloigne pas d’ici, et attache-toi aux pas de mes filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Les yeux fixés sur le champ où elles moissonnent, tu iras après elles; voilà que j’ai commandé à mes serviteurs de te respecter. Et quand tu auras soif, tu iras aux vaisseaux, et tu boiras où boivent mes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Et, pour témoigner son respect, elle tomba la face contre terre, et elle lui dit: Comment ai-je trouvé grâce devant tes yeux pour que tu m’honores, moi qui suis une étrangère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Et il répondit: On m’a raconté tout ce que tu as fait pour ta belle-mère après la mort de son mari, et comment tu as quitté ton père et ta mère et le lieu de ta naissance, et comment tu es venue chez un peuple qu’auparavant tu ne connaissais pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Que le Seigneur rémunère ta bonne action; que le Seigneur Dieu d’Israël, à qui tu es venue pour t’abriter sous ses ailes, t’accorde un salaire abondant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Et elle reprit: Que je trouve, seigneur, grâce devant tes yeux, puisque tu m’as consolée, et que tu as parlé au cœur de ta servante, et je serai comme l’une de tes servantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Et Booz lui dit: Voici le moment de manger, viens ici; tu mangeras du pain et tu tremperas ta bouchée dans le vinaigre. Ruth s’assit donc auprès des moissonneurs, et Booz lui présenta des gâteaux de farine; elle mangea et elle fut rassasiée, et il lui en resta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Ensuite, elle se leva pour glaner, et Booz donna ses ordres à ses serviteurs, disant: Laissez-la glaner au milieu des javelles et gardez-vous de la molester.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'En apportant les épis, apportez-en pour elle, et en les jetant à terre, jetez pour elle une part de ce que vous recueillez; elle glanera, elle mangera, et vous ne lui ferez aucun reproche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Et elle glana jusqu’à la nuit, puis elle battit les épis qu’elle avait ramassés, et elle en tira près d’une me-sure d’orge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Elle l’emporta et elle rentra dans la ville; sa bellemère vit ce qu’elle avait recueilli, et Ruth lui donna les restes qu’elle avait rapportés des mets dont elle s’était rassasiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Et sa belle-mère lui dit: Où as-tu glané aujourd’hui, où as-tu travaillé? Béni soit celui qui t’a accueillie. Et Ruth apprit à sa belle-mère où elle avait travaillé, et elle lui dit L’homme chez qui j’ai glané aujourd’hui se nomme Booz.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Et Noémi dit à sa bru: Béni soit-il, au nom du Seigneur, parce que sa miséricorde n’a manqué ni aux vivants, ni aux morts. Et Noémi ajouta: L’homme nous est proche, c’est un de nos parents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Et Ruth reprit: C’est sans doute pour cela qu’il m’a dit: Attache-toi aux pas de mes filles jusqu’à ce qu’elles aient achevé toute ma moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Et Noémi dit à Ruth, sa bru: Bon, mon enfant, si tu marches avec ses filles, on ne te contrariera pas dans un autre champ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Ruth s’attacha donc aux pas des filles de Booz pour glaner jusqu’à la fin de la moisson des orges et des froments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Or, comme elle était assise auprès de sa belle-mère, Noémi sa belle-mère lui dit: Fille, ne chercherai-je point pour toi le repos afin que tu sois heureuse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Maintenant, Booz, dont tu as fréquenté les filles, ne nous est-il pas connu? Écoute: Il doit vanner cette nuit de l’orge dans son aire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Lave-toi donc et te parfume, revêts-toi de ton bel habillement et monte à son aire. Ne te montre pas à l’homme qu’il n’ait fini de manger et de boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Lorsqu’il sera couché, et que tu sauras le lieu où il sera couché, tu iras, tu lèveras ce qui couvre ses pieds, tu te coucheras, et lui-même t’apprendra ce que tu auras à faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Et Ruth répondit: Je ferai tout ce que tu viens de dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Et elle se rendit à l’aire, et elle fit tout ce que sa belle-mère lui avait recommandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Et Booz mangea et il but; son cœur fut réjoui et il alla se coucher au coin d’un tas de blé; elle le suivit en silence et elle leva ce qui couvrait ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Or, à minuit l’homme s’éveilla, et il fut saisi d’étonnement et de trouble en voyant une femme couchée à ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Et il dit? Qui es-tu? Elle répondit: Je suis Ruth ta servante, et tu étendras ton aile sur ta servante, parce que tu es rédempteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Et Booz reprit: Bénie sois-tu au nom du Seigneur, ma fille, parce que tu as été bonne et miséricordieuse à la fin plus encore qu’au commencement, et que tu n’as point recherché les jeunes gens pauvres ou riches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Maintenant, ma fille, n’aie point de crainte: tout ce que tu demanderas, je te l’accorderai; car toute la tribu de mon peuple sait que tu es une femme forte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Il est vrai que je suis ton parent, mais il en est un plus proche que moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Demeure ici la nuit et demain: s’il veut t’épouser, qu’il t’épouse; mais s’il ne veut t’épouser, je t’épouserai, moi, vive le Seigneur. Couche-toi donc jusqu’à l’aurore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Elle resta couchée à ses pieds jusqu’au lendemain; puis, elle se leva avant que l’on pût se reconnaître de près, et Booz lui dit: Que personne ne sache qu’une femme est venue à mon aire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Il ajouta: Soulève le manteau que tu portes; elle le soutint, et il y versa six mesures d’orge; il l’en chargea, et elle rentra dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Et Ruth alla retrouver sa belle-mère, et celle-ci lui dit: Ma fille! et l’autre lui raconta tout ce que l’homme avait fait pour elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Elle ajouta: Il m’a donné ces dix mesures d’orge, et il m’a dit: Tu ne rentreras pas les mains vides chez ta belle-mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Or, celle-ci dit: Ne bouge pas, fille, jusqu’à ce que tu apprennes que la chose a réussi, car l’homme n’aura pas de repos qu’il ne l’ait terminée aujourd’hui même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Booz alla vers la porte de la ville, et après s’y être assis, il vit venir le parent dont il avait parlé; et Booz lui dit: Approche, assieds-toi ici, homme dissimulé. Et l’autre approcha et il s’assit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Et Booz prit dix des anciens de la ville, et il leur dit: Asseyez-vous là. Et ils s’assirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Et Booz dit au parent le plus proche: Il y a un champ de notre frère Elimelech qui a été donné à Noémi, laquelle est revenue de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Et moi j’ai dit que je t’en informerais et te dirais: Prends-en possession devant ceux qui sont assis, tous anciens de notre peuple. Si tu veux racheter, rachète; si tu ne le veux, déclare-le-moi; je saurai qu’il n’y a plus personne qui doive racheter, et je viens après toi. Et l’autre répondit: Je rachèterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Et Booz lui dit: Le jour où tu acquerras le champ des mains de Noémi, et du consentement de Ruth la Moabite, femme du défunt, il faudra que tu la prennes aussi afin de faire revivre le nom de son mari sur son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Et le parent le plus proche dit: Je ne suis point capable de le racheter pour moi-même, sinon au détriment de mon propre héritage; rachète pour toi-même ce que j’ai le droit de racheter, parce que je ne puis le racheter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Or, dès longtemps en Israël cette règle existait concernant les rachats et les marchés: pour confirmer toute parole, l’homme détachait sa chaussure et la donnait à son proche, qui reprenait son droit de rachat. Tel était le témoignage en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Le parent le plus proche dit donc à Booz: Acquiers pour toi tous mes droits de rachat. Et il dénoua sa chaussure, et il la lui donna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Et Booz dit aux anciens et à tout le peuple: Vous êtes témoins aujourd’hui que j’ai acheté de Noémi tous les biens d’Elimelech et tout ce qui appartenait à Chélaïon et à Maalon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Et que de plus, je prends pour ma femme Ruth la Moabite, femme de Maalon, afin de faire revivre le nom du défunt sur son héritage; et le nom du défunt ne sera effacé ni parmi ses frères, ni dans sa tribu. Vous en êtes témoins aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Et tout le peuple qui était près de la porte s’écria: Témoins! Et les anciens dirent: Fasse le Seigneur que la femme qui entre dans ta maison soit comme Rachel et comme Lia, qui l’une et l’autre ont fondé la maison d’Israël, et ont été des femmes fortes en Ephratha; que son nom demeure en Bethléem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Et que ta maison ressemble à la maison de Pharès que Thamar enfanta à Juda, par la postérité que le Seigneur fera naître pour toi de cette jeune servante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Booz prit donc Ruth pour sa femme et il eut commerce avec elle; le Seigneur lui accorda de concevoir, et elle enfanta un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Et les femmes dirent à Noémi: Béni soit le Seigneur qui ne t’a point laissé manquer d’un rédempteur, et qui veut aujourd’hui que ton nom vive en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Tu auras un soutien qui ranimera ton âme, qui nourrira ta vieillesse: ta belle-fille qui t’aime, et qui vaut mieux pour toi que sept fils, l’a enfanté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Et Noémi prit l’enfant et elle le mit dans son sein, et elle fut pour lui comme une nourrice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Et les voisins lui donnèrent un nom, disant: Un fils est né à Noémi, et ils le nommèrent Obed; c’est lui qui fut le père de Jessé, père de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Et voici la postérité de Pharès: Pharès engendra Esron;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Et Esron engendra Aram, et Aram engendra Aminadab;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Et Aminadah engendra Naasson, et Naasson engendra Salmon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Et Salmon engendra Booz, et Booz engendra Obed;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Et Obed engendra Jessé, et Jessé engendra David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Il y avait dans les montagnes d’Ephraïm un homme d’Armathaïm-Sipha; il se nommait Elcana, fils de Jéréméel, fils d’Eliu, fils de Thocé, l’un des Nasib');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Il avait deux femmes: le nom de la première était Anne; le nom de la seconde, Phenenna; or, Phenenna avait des enfants, et Anne n’en avait point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Les jours s’écoulèrent, et l’homme partit de la ville d’Armathaïm pour adorer le Seigneur Dieu sabaoth, et lui sacrifier en Silo; Héli et ses deux fils Ophni et Phinéès étaient alors prêtres du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Le jour venu, Elcana sacrifia; puis, il donna des parts à Phenenna, sa femme, et à ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Mais il ne donna qu’une part à Anne, parce qu’elle n’avait pas d’enfants. Cependant, Elcana aimait Anne plus que la première; et le Seigneur avait clos ses entrailles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Car le Seigneur, quels que fussent son affliction et l’abattement causé par son affliction, ne lui avait point donné d’enfants. Elle était découragée, parce que le Seigneur avait clos ses entrailles, et ne lui avait point donné d’enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Les choses se passaient de la sorte tous les ans lorsqu’elle montait à la maison du Seigneur; elle était abattue, et elle pleurait, et elle ne mangeait point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Et son époux Elcana lui dit: Anne; et elle répondit: Me voici, seigneur; et il reprit: Qu’as-tu à pleurer? Pourquoi ne manges-tu point? Pourquoi ton cœur te fait-il souffrir? Ne suis-je pas pour toi meilleur que dix enfants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Et, après qu’ils eurent mangé à Silo, Anne se leva, puis elle alla se placer devant le Seigneur, pendant qu’Héli le prêtre était sur son siège, devant le seuil du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Là, tout affligée en son cœur, elle fit au Seigneur une prière, et elle se prit à pleurer amèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Et elle fit un vœu au Seigneur, disant: Adonaï, Seigneur, Eloé sabaoth<ref>Dieu des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Et pendant qu’elle prolongeait sa prière devant le Seigneur, Héli le prêtre était attentif au mouvement de ses lèvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Car elle parlait en son cœur, et elle remuait les lèvres, mais on n’entendait point sa voix; or, Héli la crut ivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Et le serviteur d’Héli alla lui dire: Jusqu’à quand seras-tu donc ivre? Va-t’en avec ton vin; retire-toi de devant le Seigneur.</ref>, si vous jetez les yeux sur l’humiliation de votre servante, si vous vous souvenez de moi, si vous donnez à votre servante un fils, je vous le consacrerai jusqu’au jour de sa mort; il ne boira ni vin ni boisson enivrante, et le fer ne passera jamais sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Anne répondit, et elle dit au prêtre: Non, seigneur, je suis aujourd’hui une femme pleine d’affliction, je n’ai bu ni vin ni boisson enivrante, et je répands mon âme devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne prends pas ta servante pour une fille de pestilence; c’est à cause de l’abondance de mes méditations que j’ai prolongé jusqu’à ce moment ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Héli reprenant, lui dit: Va en paix, que le Dieu d’Israël t’accorde toute ta prière, tout ce que tu lui as demandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Alors, elle dit: Ta servante a trouvé grâce devant tes yeux. Et la femme s’en alla, elle rentra à son logis, elle mangea et but avec son mari, et son visage cessa d’être abattu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Ensuite, s’étant levés de grand matin, ils adorèrent le Seigneur, et reprirent leur chemin; Elcana rentra dans sa maison d’Armathaïm, et il connut Anne; or, le Seigneur se souvint d’elle, et elle conçut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Le temps révolu, elle enfanta un fils, et elle l’appela Samuel, parce que, dit-elle, je l’avais demandé au Seigneur Dieu sabaoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Or, son époux Elcana, avec toute sa famille, monta à Silo pour offrir au Seigneur le sacrifice de la saison, ses oblations votives, et la dîme de tous les fruits de ses champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Mais Anne ne partit pas avec lui, et elle dit à son époux J’irai quand l’enfant ira, quand je l’aurai sevré, et qu’il sera présenté au Seigneur pour y rester toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Son époux Elcana lui répondit: Fais ce que bon te semble, demeure ici jusqu’à ce que tu l’aies sevré; que le Seigneur accomplisse toutes les paroles qui sont sorties de ta bouche. Et la femme ne bougea pas, et elle allaita son fils jusqu’à ce qu’elle le sevrât.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Alors, elle partit avec Elcana pour Silo; ils avaient un bœuf de trois ans, des pains, un éphi de fleur de farine et un nébel de vin; elle entra à Silo dans la maison du Seigneur, et son enfant était avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Et ils le conduisirent devant le Seigneur; son père égorgea la victime que de saison en saison il sacrifiait au Seigneur; il présenta l’enfant après avoir égorgé le bœuf; et Anne, la mère de l’enfant, le conduisit à Héli,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Et elle dit: Je te prie, seigneur, aussi vrai que tu vis, je suis la femme que tu as vue assise devant toi, priant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'J’ai prié pour obtenir cet enfant, et le Seigneur a exaucé la prière que je lui avais faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Cet enfant, je le donne au Seigneur pour être tous les jours de sa vie au service du Seigneur; puis, elle dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Mon cœur s’est affermi dans le Seigneur, ma force s’est relevée en mon Dieu, ma bouche s’est dilatée contre mes ennemis; je me suis réjouie, parce que vous m’avez sauvée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Car nul n’est saint comme le Seigneur, nul n’est juste comme mon Dieu, nul n’est saint, hormis vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne vous glorifiez pas, ne dites point de paroles superbes; que nul mot résonnant ne sorte de votre bouche, parce que le Seigneur est le Dieu des sciences, et que Dieu prépare ses desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'L’arc des puissants a été énervé, et les faibles se sont revêtus de force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Ceux qui regorgeaient de biens ont été humiliés, et les pauvres n’ont pas eu de regards pour la terre, parce que la stérile a enfanté sept fois, et que celle qui avait beaucoup d’enfants a perdu sa fécondité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Le Seigneur distribue la mort et la vie; il conduit aux enfers et il en ramène.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Le Seigneur appauvrit et il enrichit; il abaisse et il élève;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Il tire l’indigent de la poussière et le mendiant de la fange, pour les faire asseoir parmi les puissants du peuple, et leur donner en héritage un trône de gloire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Il accomplit les vœux des suppliants; il bénit les années du juste, tandis que l’homme, par sa propre force, ne peut rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Le Seigneur réduit à la faiblesse son adversaire; le Seigneur est saint: que le sage ne se glorifie pas en sa sagesse, que le puissant ne se glorifie pas en sa puissance, que le riche ne se glorifie pas en sa richesse. Comprendre et connaître le Seigneur, pratiquer la justice et l’équité sur la terre, voilà de quoi l’on peut se glorifier. Le Seigneur est remonté aux cieux; il a fait retentir son tonnerre, il jugera jusqu’aux extrémités de la terre. Il donne à nos rois leur puissance, et il élèvera la force de son Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Après cela, elle laissa l’enfant devant le Seigneur, et elle retourna en Armathaïm. Cependant, l’enfant était employé au service du Seigneur, devant le prêtre Héli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Et les fils d’Héli le prêtre étaient des enfants de pestilence, ne connaissant pas le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Or, tel était le droit du prêtre: quand quelqu’un');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'Il la plongeait dans la grande marmite, de terre ou d’airain, et tout ce que saisissait la fourchette était pour le prêtre. Voilà ce qui se faisait à l’égard de tous ceux d’Israël qui venaient en Silo sacrifier au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Et avant que l’on brûlât la graisse, en odeur de suavité pour le Seigneur, le serviteur du prêtre accourait, et disait à l’homme qui offrait le sacrifice');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'A quoi l’homme venu pour sacrifier répondait: Laisse-nous d’abord brûler la graisse, comme il convient, et tu prendras pour toi tous les morceaux que ton âme désire. Mais il disait: Non, donne-les-moi tout de suite, ou je les prendrai de force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Le péché des fils du prêtre était très-grand devant le Seigneur, parce qu’ils méprisaient le sacrifice du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Cependant, Samuel était employé au service du Seigneur, et l’enfant était revêtu d’un éphod de lin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Sa mère lui fit en outre un petit manteau double, et elle le lui apporta le jour de la fête, lorsqu’elle monta avec son mari pour faire le sacrifice de la saison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Et Héli bénit Elcana et sa femme, disant: Que le Seigneur, en te donnant des enfants de cette femme, te récompense du serviteur que tu lui as consacré. Et l’homme retourna à sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Et le Seigneur visita Anne; elle enfanta encore trois fils et deux filles; et Samuel avait grandi devant le Seigneur. saient pas le devoir du prêtre à l’égard du peuple, et ne se conformaient pas à la loi. (Voyez Exode, xxix, 27, 28; Lévit., VII, 31 à 34.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Or, Héli était très-avancé en âge; il apprit ce que faisaient ses fils aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Et il leur dit: Pourquoi faites-vous les choses que j’ai ouïes de la bouche de tout le peuple du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ne les faites plus, enfants, car la nouvelle que j’ai entendue n’est pas une bonne nouvelle; ne vous conduisez plus ainsi; car ce ne sont pas de bonnes nouvelles quand on me rapporte que vous empêchez le peuple de servir Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Si un homme pèche contre un homme, on adressera pour lui des prières au Seigneur; mais s’il a péché contre le Seigneur, qui priera pour lui? Mais ils n’écoutèrent pas la voix de leur père, parce que le Seigneur voulait les détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Et le jeune Samuel marchait; il était bon avec le Seigneur et avec les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Alors, un homme de Dieu vint auprès d’Héli, et dit: Voici ce que dit le Seigneur: Je me suis révélé à la famille de ton père quand elle était encore en Égypte, esclave dans la maison du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'J’ai choisi la famille de ton père, parmi les puissants d’Israël, pour me servir, monter à l’autel, brûler de l’encens et porter l’éphod. J’ai donné à la famille de ton père, pour sa nourriture, une part de tout ce que les fils d’Israël offrent en sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Pourquoi donc as-tu regardé d’un œil avide mes victimes et mon encens? Pourquoi donc as-tu donné plus de gloire à tes fils qu’à moi, au point qu’ils consomment avant moi les prémices de toutes les victimes d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'A cause de cela, voici ce que dit le Seigneur Dieu d’Israël J’avais dit: Ta famille, la famille de ton père se tiendra près de moi à toujours. Et maintenant, le Seigneur dit Non, parce que je glorifierai ceux qui me glorifient, et que celui qui me méprise sera méprisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Voilà que les temps approchent où j’exterminerai ta race, la postérité de ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Il n’y aura plus jamais en ma maison un seul vieillard de ta race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Et celui des tiens que je n’exterminerai pas en l’éloignant de mon autel, ses yeux s’éteindront, sa vie se consumera; et tout le reste périra par le glaive des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Or, voilà pour toi le signe, et il viendra sur tes deux fils, Ophni et Phinéès: ils mourront tous les deux le même jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Je susciterai alors pour moi un prêtre fidèle, qui pratiquera tout ce qui est en mon cœur et en mon âme; j’édifierai pour lui une maison fidèle, et il passera devant mon Christ, à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Celui de ta famille qui survivra, viendra se prosterner devant lui pour une obole, et dira: Admets-moi à l’une de tes distributions sacerdotales, afin que je mange du pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Cependant, le jeune Samuel était employé au service du Seigneur devant Héli le prêtre; en ces jours-là, la parole du Seigneur était rare; il n’y avait plus de visions faisant connaître ses volontés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Et en ce temps-là, il advint qu’Héli dormait au lieu accoutumé; ses yeux commençaient à s’affaiblir; il n’y voyait plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'C’était avant le moment où l’on visitait la lampe de Dieu, et Samuel dormait dans le sanctuaire auprès de l’arche de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Et le Seigneur appela: Samuel, Samuel; et l’enfant dit Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Et il courut auprès d’Héli, et il lui dit: Me voici, puisque tu m’as appelé. Mais Héli répondit: Je ne t’ai point appelé, retourne-t’en et te rendors. Il s’en retourna donc, et il se rendormit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Le Seigneur recommença, il appela: Samuel, Samuel; l’enfant alla une seconde fois auprès d’Héli, et il dit: Me voici, puisque tu m’as appelé. Mais le prêtre lui répondit: Je ne t’ai point appelé, retourne-t’en et te rendors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Or, c’était avant que Samuel connût Dieu, et que la parole du Seigneur lui eût été révélée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Le Seigneur, continuant, appela Samuel une troisième fois; l’enfant se leva, il alla auprès d’Héli, et il dit: Me voici, puisque tu m’as appelé. Le prêtre comprit alors que le Seigneur avait appelé l’enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Il dit donc: Retourne-t’en, et rendors-toi, mon fils, et, si l’on t’appelle encore, tu diras: Parlez, votre serviteur vous écoute. Et Samuel s’en retourna, et il se recoucha au lieu accoutumé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Le Seigneur vint, s’arrêta, et l’appela comme les autres fois, et Samuel dit: Parlez, votre serviteur vous écoute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Et le Seigneur dit: Voilà que j’exécute ce que j’ai dit en Israël; quiconque l’ouïra, ses deux oreilles en tin teront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'En ce jour-là, je susciterai contre Héli toutes les choses dont j’ai menacé sa famille; je commencerai et j’achèverai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Je lui ai annoncé que je punirais à perpétuité sa famille, à cause des iniquités de ses fils; car ses fils ont outragé Dieu, et il ne les a point réprimandés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Non, les choses ne peuvent aller ainsi: j’ai juré à la famille d’Héli que son iniquité ne pouvait être expiée ni par l’encens ni par les sacrifices à perpétuité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Et Samuel resta couché jusqu’au matin; il se leva dès l’aurore, et il ouvrit les portes de la maison du Seigneur. Or, Samuel craignit de raconter sa vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Et Héli dit à Samuel: Samuel, mon enfant. Et il répondit: Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Puis, le prêtre reprit: Quelle est la parole qui t’a été dite? ne me cache rien; que le Seigneur te punisse, et qu’il te punisse encore, si tu me caches rien de ce qu’ont ouï tes oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Samuel lui répéta donc toutes les paroles du Seigneur, il ne lui cacha rien. Et le prêtre dit: C’est le Seigneur; il fera ce que bon lui semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Et Samuel grandit et prospéra, car le Seigneur était avec lui; et pas une de ses paroles ne fut vaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Et depuis Dan jusqu’à Bersabée, tout Israël sut que Samuel était un fidèle prophète du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Le Seigneur continua de se montrer en Silo, parce que le Seigneur s’était révélé à Samuel. D’une extrémité à l’autre de la terre promise, tout Israël crut que Samuel était un prophète du Seigneur. Or, Héli était très-avancé en âge; et ses fils marchaient dans leur voie, et leur voie était mauvaise devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'En ces jours-là, les Philistins se rassemblèrent pour combattre Israël; et Israël sortit à leur rencontre; il campa vers Abenézer; de leur côté, les ennemis étaient campés en Aphec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Et les Philistins se déployèrent devant Israël; l’on en vint aux mains, et Israël plia, laissant quatre mille hommes sur le champ de bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Le peuple rentra dans le camp, et les enfants d’Israël dirent: Pourquoi le Seigneur aujourd’hui nous a-t-il fait tomber devant les Philistins? Prenons à Silo l’arche de notre Dieu; qu’elle vienne au milieu de nous, elle nous sauvera des mains de nos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Le peuple envoya donc en Silo, et l’on en apporta l’arche du Seigneur qui s’y tient assis entre les chérubins; les deux fils d’Héli, Ophni et Phinéès, accompagnaient l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Lorsque l’arche du Seigneur arriva dans le camp, tout le peuple d’Israël cria tout d’une voix, et la terre en retentit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Les Philistins ouïrent cette clameur, et ils dirent: D’où viennent ces grands cris dans le camp des Hébreux? Et ils surent que l’arche du Seigneur était entrée au camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Alors, ils eurent crainte et ils dirent: Ce sont leurs dieux qui sont venus vers eux dans le camp; malheur à nous! sauvez-nous aujourd’hui, Seigneur, car rien de pareil n’est avenu précédemment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Malheur à nous! qui nous sauvera des mains de ces dieux inflexibles? Ce sont les dieux qui ont frappé l’Égypte de toutes sortes de plaies dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Soyez forts, Philistins, agissez en hommes, afin que les Hébreux ne vous asservissent pas comme vous les avez asservis; oui, soyez hommes et combattez-les.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Et ils les combattirent; et Israël fut vaincu; et chacun s’enfuit en sa demeure. Et la plaie fut bien grande trente mille combattants d’Israël succombèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Et l’arche de Dieu fut prise, et les deux fils d’Héli, Ophni et Phinéès, moururent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Un homme de Jéminé, en ce jour-là, courut du champ de bataille à Silo, les vêtements déchirés, la tête couverte de cendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Il arriva, et il vit Héli sur son siége, devant sa porte, regardant le chemin, car son cœur était plein d’inquiétude à cause de l’arche de Dieu; or, l’homme entra dans la ville pour apporter les nouvelles, et la ville jeta les hauts cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Héli entendit ces cris de détresse, et il dit: Quelle est cette clameur? Et l’homme s’étant hâté se montra, et lui raconta tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Héli avait quatre-vingt-dix ans; ses yeux étaient sans force, il n’y voyait plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Et Héli dit aux hommes qui l’entouraient: Quelle est cette clameur? Quand l’homme, s’étant hâté, se montra et lui dit: C’est moi qui arrive de l’armée; aujourd’hui, je me suis enfui comme les autres du champ de bataille; et Héli lui dit: Qu’est-il donc avenu, mon fils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Le jeune homme répondit et il dit: Tout Israël a pris la fuite devant les Philistins; le peuple a été frappé d’une grande plaie, tes deux fils sont morts, et l’arche de Dieu est prise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Dès que l’homme eut parlé de l’arche de Dieu, le prêtre tomba de son siége à la renverse devant la porte, il se cassa les reins, et il mourut; car il était avancé en âge et pesant; il y avait vingt ans qu’il jugeait Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Sa bru, femme de Phinéès, grosse et près d’enfanter, entendit que l’arche était prise, que son beau-père mourait, que son mari avait été tué; elle pleura et elle accoucha, car les douleurs de l’enfantement soudain lui vinrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Comme elle allait mourir, les femmes qui l’entouraient lui dirent: N’aie point de crainte, car tu as enfanté un fils; et elle ne répondit pas: son cœur ne sentait plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Et l’on appela l’enfant Ibarchaboth, à cause de l’arche de Dieu, à cause du beau-père de la femme, et à cause de son mari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Et les femmes dirent: La gloire d’Israël s’en est allée, puisque l’arche du Seigneur a été prise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Et les Philistins prirent l’arche de Dieu, et ils la portèrent d’Abenézer à Azot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Et les Philistins prirent l’arche du Seigneur, et ils la portèrent dans le temple de Dagon, et ils la posèrent auprès de Dagon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Et les hommes d’Azot s’étant levés de grand matin, entrèrent dans le temple de Dagon, et ils virent Dagon renversé, la face contre terre, devant l’arche de Dieu; ils relevèrent Dagon et le remirent à sa place; puis, la main du Seigneur s’appesantit sur les hommes d’Azot; elle les tourmenta, elle les frappa à l’anus, tant ceux de la ville que ceux de son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Lorsqu’ils se levèrent de bonne heure, le jour suivant, ils virent Dagon renversé, la face contre terre, devant l’arche de l’alliance du Seigneur; la tête de Dagon et ses mains avaient été enlevées jusqu’à la façade d’Amapheth, et ses deux poignets gisaient sur le portique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Le torse seul de Dagon était resté. A cause de cela, encore de nos jours, ni les prêtres de Dagon, ni ceux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'La main du Seigneur s’appesantit donc sur les hommes d’Azot; le Seigneur fit fourmiller, tant dans leurs maisons qu’au milieu de leurs champs, une multitude de rats; en même temps, la mort répandit un grand trouble dans toute la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Les hommes d’Azot, voyant ce qui se passait, dirent: C’est parce que l’arche du Dieu d’Israël réside parmi nous, que sa main est si dure pour nous-mêmes et pour Dagon, notre dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Alors, ils firent partir des messagers pour convoquer chez eux les chefs des Philistins; ceux-ci venus, ils dirent: Que ferons-nous de l’arche du Dieu d’Israël? Les Géthéens dirent: Que l’on envoie chez nous l’arche du Dieu. En conséquence, on envoya à Geth l’arche du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Dès qu’elle y fut arrivée, la main du Seigneur répandit dans cette ville un très-grand trouble; elle frappa les hommes depuis le plus grand jusqu’au plus petit, elle les frappa à l’anus, et les Géthéens firent des siéges pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Puis, ils envoyèrent l’arche de Dieu à Ascalon; lorsqu’elle y entra, les habitants crièrent et dirent: Pourquoi nous amenez-vous l’arche du Dieu d’Israël? est-ce pour faire périr notre peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Et ils firent partir des messagers pour convoquer les chefs des Philistins; ceux-ci venus, ils dirent: Renvoyez l’arche du Dieu d’Israël; qu’elle réside en son lieu; qu’elle ne nous fasse point périr, nous et notre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Car, dans toute ville où elle entre, elle apporte un grand trouble. Et ceux qui ne meurent pas sont frappés à l’anus. Or, le cri de toute la ville s’éleva jusqu’au');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'L’arche fut sept mois sur la terre des étrangers, et les rats y fourmillèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Alors, les Philistins appelèrent leurs prêtres, leurs devins, leurs magiciens, et ils leur dirent: Que ferons-nous de l’arche du Seigneur? Apprenez-nous comment nous la renverrons au lieu où elle réside.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Et ils dirent: Si vous renvoyez l’arche de l’alliance du Seigneur Dieu d’Israël, ne la renvoyez point vide; mais en la rendant faites des dons à cause de votre plaie; cela fait, vous serez guéris, l’arche vous sera propice, et la main du Seigneur ne pèsera plus sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Que donnerons-nous à cause de notre plaie? dirent-ils; les prêtres répondirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Cinq anus d’or, selon le nombre des chefs des Philistins, à cause de la plaie qui vous a frappés, chefs et peuple, et autant de rats d’or semblables aux rats qui ont dévasté votre contrée. Vous glorifierez ainsi le Seigneur afin que sa main cesse de peser sur vous, sur vos dieux et sur votre pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Pourquoi vous endurcir le cœur, comme l’ont endurci l’Égypte et le Pharaon? N’est-ce pas après que le Seigneur se fut joué d’eux, qu’ils congédièrent les Hébreux et que ceux-ci partirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Maintenant donc prenez du bois et faites un chariot neuf; prenez deux vaches n’ayant vêlé qu’une fois, séparez-les de leurs veaux; attelez-les au chariot, et renvoyez les veaux à l’étable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Ensuite, vous prendrez l’arche et vous la placerez sur le chariot avec tous les objets d’or que vous donnerez en expiation, et que vous renfermerez dans une cassette à côté d’elle; puis, vous la renverrez, vous pousserez l’attelage et vous vous en éloignerez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Après cela, vous serez attentifs: si elle prend par Bethsamys la route de son pays, c’est le Seigneur qui vous a frappés de ces grandes plaies; sinon, nous reconnaîtrons que ce n’est point sa main qui nous a touchés, mais qu’un accident nous est advenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Les Philistins suivirent ces conseils; ils prirent deux vaches qui n’avaient encore vêlé qu’une fois; ils les attelèrent au chariot, et ils retinrent leurs veaux à l’étable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Ils posèrent sur le chariot l’arche du Seigneur et la cassette contenant les rats d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Et les vaches marchèrent droit au chemin qui mène à Bethsamys; elles ne quittèrent point la voie, tirant avec effort, sans dévier ni à droite ni à gauche; les chefs des Philistins les suivirent à distance, jusqu’aux confins de Bethsamys.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Or, ceux de Bethsamys moissonnaient les froments dans la vallée; ils virent l’arche du Seigneur et ils coururent pleins de joie au-devant d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Et le chariot entra dans le champ d’Osée de Bethsamys; les hommes dressèrent auprès de l’arche une grande pierre; ils fendirent le bois du chariot, et ils offrirent les vaches en holocauste au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Ensuite, les lévites soulevèrent l’arche du Seigneur et la cassette avec les objets d’or qu’elle contenait; ils les posèrent sur la grande pierre, et les hommes de Bethsamys, ce jour-là, firent des holocaustes et des oblations au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Les cinq chefs des Philistins les ayant aperçus, retournèrent à Ascalon le jour même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Voici d’où venaient les anus d’or que les Philistins donnèrent à cause de la plaie du Seigneur: un d’Azot, un de Gaza, un d’Ascalon, un de Geth et un d’Ac caron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Et les rats d’or étaient en même nombre que toutes les villes des Philistins soumises aux cinq chefs, depuis les villes fortifiées, jusqu’au village du Phérézéen et à la grande pierre sur laquelle on posa l’arche de l’alliance du Seigneur, dans le champ d’Osée le Bethsamite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Parmi les hommes de Bethsamys, les fils de Jéchonie n’eurent point à se féliciter parce qu’ils regardèrent l’arche du Seigneur, qui frappa à mort soixantedix de leurs chefs, outre cinquante mille hommes. Le peuple fut plongé dans le deuil parce que le Seigneur l’avait frappé d’une très-grande plaie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Et les hommes de Bethsamys dirent: Qui pourra aller et venir en présence du Seigneur, du Dieu saint? Chez qui, en nous quittant, ira l’arche du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Et ils dépêchèrent des messagers aux habitants de Cariath-larim, disant: Les Philistins ont rendu l’arche du Seigneur, venez et emmenez l’arche avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Et les hommes de Cariath-larim vinrent; ils emmenèrent l’arche de l’alliance du Seigneur, et ils l’introduisirent dans la maison qu’Aminadab possédait sur la colline. Puis ils sanctifièrent son fils Eléazar, afin qu’il gardât l’arche de l’alliance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'A partir du jour où l’arche entra à Cariath-larim, bien des jours s’écoulèrent, elle y était déjà depuis vingt ans, quand tout Israël se tourna vers le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Alors, Samuel parla à toute la maison d’Israël, disant: Si c’est de tout votre cœur que vous revenez à Dieu, chassez du milieu de vous les dieux étrangers, détruisez leurs bois sacrés, préparez vos âmes pour le Seigneur Dieu, ne servez que lui seul; et il vous affranchira du joug des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Les fils d’Israël chassèrent donc Baal; ils détruisirent les bois sacrés d’Astaroth, et ils ne servirent que le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Et Samuel dit: Réunissez tout Israël en Masphath; et je prierai pour vous le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Et ils se rassemblèrent en Masphath; ils puisèrent de l’eau, et la répandirent sur la terre devant le Seigneur; ce jour-là ils jeûnèrent, et ils dirent: Nous avons péché devant le Seigneur. Puis, Samuel jugea les fils d’Israël en Masphath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Et les Philistins apprirent que tous les fils d’Israël étaient assemblés en Masphath, les chefs des Philistins se mirent aussitôt en marche contre Israël; les fils d’Israël le surent, et ils eurent crainte des étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Et les fils d’Israël dirent à Samuel: Ne cesse pas de crier pour nous au Seigneur ton Dieu; il nous sauvera des mains de nos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel prit un agneau de lait, et avec tout le peuple, il l’offrit en holocauste au Seigneur; Samuel cria au Seigneur en faveur du peuple, et le Seigneur l’exauça.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Samuel était à offrir l’holocauste pendant que les Philistins s’avançaient pour combattre Israël; et ce jour-là le Seigneur fit entendre contre les Philistins la grande voix du tonnerre; ils furent confondus, et ils s’enfuirent devant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Et les hommes d’Israël sortirent de Masphath, poursuivirent les Philistins, et les taillèrent en pièces jusqu’au-dessous de Bethchor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Après cela, Samuel prit une pierre qu’il dressa entre Masphath et la vieille ville; et il l’appela Abenézer, Pierre du Secours; et il dit: Jusqu’en ce lieu le Seigneur nous a secourus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Ainsi, le Seigneur humilia les Philistins; ils cessèrent d’envahir le territoire d’Israël, et la main du Seigneur se tourna contre les Philistins durant tous les jours de Samuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Et les Philistins rendirent toutes les villes qu’ils avaient prises aux fils d’Israël; ils les rendirent à Israël depuis Ascalon jusqu’à Azot. Israël recouvra ses limites qu’il reprit aux Philistins; cependant la paix régnait entre Israël et l’Amorrhéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Ensuite, Samuel jugea le peuple, durant tous les jours de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Tous les ans il voyageait; il passait dans sa tournée par Béthel, Galgala et Masphath; et en tous ces lieux saints, il jugeait Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Enfin, il rentrait en Armathaïm, où était sa demeure; il y jugeait Israël, et il y bâtit un autel au Sei gneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Et Samuel devint vieux, et il institua ses fils juges d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Voici les noms de ces fils: le premier-né s’appelait Joël, le second Abia; ils jugeaient en Bersabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Mais ses fils ne marchèrent pas en ses voies; ils en furent détournés par l’intérêt; ils acceptèrent des présents et ils firent dévier la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'En conséquence, les fils d’Israël se rassemblèrent; ils allèrent trouver Samuel en Armathaïm,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Et ils lui dirent: Écoute, tu es devenu vieux, et tes fils ne marchent pas en tes voies; donne-nous donc un roi comme en ont les autres nations, afin qu’il nous juge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Cette parole parut mauvaise à Samuel, lorsqu’ils dirent: Donne-nous un roi, afin qu’il nous juge; et Samuel pria le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Or, le Seigneur dit à Samuel: Écoute la voix du peuple, fais comme ils te diront; ce n’est point toi, c’est moi qu’ils ont méprisé et dont ils ne veulent pas pour régner sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'C’est ce qu’ils ont toujours fait à mon égard depuis le jour où je les ai tirés de l’Égypte jusqu’à ce moment: ils m’ont abandonné, et ils ont servi d’autres dieux; ils te traitent de même maintenant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Obéis donc à leur voix; seulement prends-les à témoin, et prends-les à témoin pour leur faire connaître les droits du roi qui régnera sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Et Samuel répéta toutes les paroles du Seigneur au peuple qui lui demandait un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Il leur dit: Voici quels seront les droits du roi qui régnera sur vous: Il prendra vos fils, et il les placera sur ses chars de guerre ou parmi ses cavaliers; il les fera courir devant ses chars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Il s’en fera des centeniers et des chefs de mille hommes; il leur fera faire sa moisson et sa vendange; il leur fera fabriquer des armes de guerre, et les pièces diverses de ses chariots.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Il prendra vos filles pour préparer ses parfums, cuire son pain, et faire sa cuisine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Il prendra vos champs, vos vignes, vos meilleurs oliviers, pour les donner à ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Il prendra la dîme de vos grains et de votre vendange, pour la donner à ses eunuques et à ses esclaves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Il prendra vos serviteurs, vos servantes, vos bœufs et vos ânes; il prendra la dîme de tous les fruits de vos travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Il prendra la dîme de votre bétail, et vous serez ses esclaves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Et, ce jour-là, vous crierez à cause du roi que vous vous serez choisi; et, ce jour-là, le Seigneur ne vous écoutera point, parce que c’est vous-mêmes qui aurez voulu ce roi pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Mais le peuple ne voulut pas écouter Samuel, et il dit: Nullement, mais nous aurons un roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Nous serons comme toutes les nations; notre roi nous jugera, il marchera à notre tête et il dirigera nos guerres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Et Samuel écouta tous les discours du peuple, et il les transmit au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Et le Seigneur dit à Samuel: Obéis-leur, et donneleur un roi. Alors, Samuel dit aux fils d’Israël: Que chacun s’en retourne en sa ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Et il y avait parmi les fils de Benjamin un homme appelé Cis, fils d’Abiel, fils de Jared, fils de Bachir, fils d’Aphec, fils d’un puissant Jéminéen. C’était un homme puissant et fort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Il avait un fils dont le nom était Saül, homme de grande taille, bon et vaillant; nul des fils d’Israël n’était meilleur que lui, et il dépassait de toute la tête tout le reste du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Les ânesses de Cis, père de Saül, s’étaient égarées; et Cis dit à Saül, son fils: Prends avec toi l’un des serviteurs; partez, et cherchez les ânesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Ils traversèrent les montagnes d’Ephraïm; ils traversèrent le territoire de Selcha, et ils ne trouvèrent rien; ils traversèrent le territoire de Ségalim, les ânesses n’y étaient pas; ils traversèrent le territoire de Jamin, et ils ne trouvèrent rien encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Comme ils passaient près de Siph, Saül dit au serviteur qui l’accompagnait: Viens, retournons chez nous, de peur que mon père ne s’inquiète plus de nous que des ânesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Le serviteur lui répondit: Écoute, il y a en cette ville un homme de Dieu, un homme renommé; tout ce qu’il prédit arrive. Allons-y donc, afin qu’il nous fasse connaître la voie que nous devons prendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Et Saül dit au serviteur qui l’accompagnait: Je le veux bien, nous irons; mais que porterons-nous à l’homme de Dieu? Il ne nous reste plus rien du pain que nous avions emporté dans nos valises, et nous n’avons rien à offrir à l’homme de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Le serviteur répondit à Saül, et il lui dit: Je trouve à l’instant sous ma main un quart de sicle d’argent; tu le donneras à l’homme de Dieu, et il nous fera connaître notre chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Or, jadis en Israël, tout homme qui allait consulter Dieu, disait Allons chez le voyant, parce que jadis le peuple donnait au prophète le nom de voyant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saül dit donc à son serviteur: Ton conseil est bon, allons-y. Et ils allèrent à la ville où demeurait l’homme de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Comme ils gravissaient le coteau qui monte à la ville, ils rencontrèrent des jeunes filles qui venaient de puiser de l’eau, et ils leur dirent: Le voyant est-il là?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Les jeunes filles leur répondirent: Il y est; le voici devant vous; il est venu à la ville à cause du jour, parce qu’aujourd’hui il y a pour le peuple un sacrifice en Bama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Lorsque vous serez entrés dans la ville, vous l’y trouverez encore avant qu’il soit monté en Bama pour manger. Le peuple ne mangera pas qu’il ne soit arrivé, car c’est lui qui bénit le sacrifice; après cela, les invités mangent. Montez donc; pendant toute cette journée vous êtes sûrs de le trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Et ils montèrent à la ville; ils étaient déjà au centre de la ville, quand Samuel sortit pour monter en Bama, et ils le rencontrèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'La veille de l’arrivée de Saül, le Seigneur l’avait annoncée à Samuel, en disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'À pareille heure, demain, j’enverrai auprès de toi un homme de la tribu de Benjamin; tu l’oindras comme roi de tout mon peuple; et il sauvera Israël des mains des Philistins, car j’ai considéré l’abaissement de mon peuple, ses cris sont venus jusqu’à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Quand Samuel vit Saül, le Seigneur lui dit: Voici l’homme dont je t’ai parlé; c’est lui qui règnera sur mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Et Saül aborda Samuel, au milieu de la ville, et il lui dit: Indique-moi la maison du voyant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel répondit à Saül, et il lui dit: Je suis le voyant, monte devant moi en Bama; mange aujourd’hui avec moi; demain, je te congédierai, et je te dévoilerai tout ce qui est en ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Ne songe plus aux ânesses qui étaient perdues il y a trois jours; elles sont retrouvées. Et à qui donc seront les choses précieuses d’Israël, si ce n’est à toi et à la maison de ton père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saül répondit, et il dit: Ne suis-je pas des fils de Jéminée, du moindre des cantons d’une tribu d’Israël, du moindre principat de tout Benjamin? Pourquoi m’adresses-tu de telles paroles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Et Samuel prit Saül avec son serviteur, il les introduisit en Bama dans la salle du festin; il leur donna place parmi les premiers des convives, qui étaient environ soixante-dix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Et Samuel dit au cuisinier: Apporte-moi l’épaule que je t’ai donnée, et que je t’ai dit de garder chez toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Le cuisinier avait fait cuire l’épaule, il la plaça devant Saül, et Samuel lui dit: Voilà ce qui t’est réservé; prends cette épaule et mange, car on l’a mise auprès de toi pour qu’elle soit un témoignage de préférence aux yeux de tous les autres; coupe et mange. Ce jour-là donc, Saül mangea avec Samuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Ensuite, il revint du haut lieu à la ville, où l’on fit pour Saül un lit sur la terrasse, et il y dormit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Lorsque le jour vint à poindre, Samuel appela Saül sur la terrasse, disant: Lève-toi, et je te congédierai. Saül se leva, il sortit avec Samuel, et ils passèrent les portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Comme ils descendaient le coteau, Samuel dit à Saül Ordonne à ton serviteur de s’en aller devant nous, et arrête-toi, afin qu’aujourd’hui tu entendes la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Alors, Samuel prit une petite fiole d’huile, il la vida sur sa tête, il le baisa, et lui dit: Le Seigneur ne vient-il pas de t’oindre pour que tu sois chef de son peuple Israël? Tu règneras sur le peuple du Seigneur; tu le sauveras des mains de ses ennemis. Voici le signe à quoi tu reconnaîtras que tu es oint par le Seigneur, comme roi de son héritage:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Aussitôt qu’aujourd’hui tu te seras éloigné de moi, tu rencontreras, près du sépulcre de Rachel, en la montagne de Benjamin, deux hommes, courant à grands pas; ils te diront: On a retrouvé les ânesses que vous êtes allés chercher; ton père ne compte plus pour rien les ânesses, et il prépare grande chère, à cause de vous, disant Que ferai-je pour mon fils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Tu partiras de ce lieu; ensuite, tu iras jusqu’au chêne de Thabor; là, tu trouveras trois hommes montant vers le Seigneur en Béthel, et portant: l’un, trois chevreaux; le second, trois corbeilles pleines de pains; le troisième, une outre de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Ils te demanderont si tu vas bien, et te donneront deux de leurs pains, que tu accepteras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Après cela, tu arriveras sur la colline de Dieu, où les Philistins ont un tertre fortifié, et où réside le Nasib philistin; quand tu y seras entré, tu rencontreras un chœur de prophètes descendant du haut lieu, précédés d’instruments à cordes, de tambours et de flûtes; tous prophétisant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Et l’esprit du Seigneur s’élancera sur toi; tu prophétiseras avec eux, et tu seras devenu un autre homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Lorsque tous ces signes seront venus, fais tout ce que te suggérera l’occasion, parce que Dieu sera avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Tu descendras en face de Galgal, et je te rejoindrai pour offrir un holocauste et des hosties pacifiques; tu attendras mon arrivée sept jours; ensuite, je t’instruirai de tout ce que tu auras à faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Dès que Saül se fut retourné pour s’éloigner de Samuel, Dieu changea son cœur, et, ce jour-là, tous les signes arrivèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'De ce lieu, il se rendit à la colline, il vit devant lui le chœur des prophètes, l’Esprit de Dieu s’élança sur lui, et il prophétisa au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Or, tous ceux qui le connaissaient précédemment, le virent; il était au milieu des prophètes; et, parmi le peuple, chacun dit à son voisin: Qu’est-il arrivé au fils de Cis? Saül aussi est-il au nombre des prophètes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'L’un d’eux répondit, et il dit: Quel est donc son père? A cause de cela, ce mot est passé en proverbe: Saül aussi est-il au nombre des prophètes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Ensuite, il cessa de prophétiser, et il alla sur la colline à l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Et l’un de ses parents dit à lui et à son serviteur: Où êtes-vous allés? A quoi ils répondirent: Chercher les ânesses, mais nous ne les avons pas trouvées, et nous sommes entrés chez Samuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Puis, le parent dit à Saül: Fais-moi connaître ce que t’a dit Samuel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saül répondit: Que les ânesses étaient retrouvées; mais il ne lui dit rien de la royauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Et Samuel convoqua tout le peuple devant le Seigneur, à Masphath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Et il dit aux fils d’Israël: Voici ce qu’a dit le Seigneur Dieu d’Israël: J’ai fait sortir d’Égypte les fils d’Israël, je vous ai tirés des mains du Pharaon, roi d’Égypte, et de tous les rois qui vous avaient opprimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Aujourd’hui, vous avez rejeté le Dieu qui seul est votre Sauveur en tous vos maux, en toutes vos afflictions, et vous avez dit: Nous le voulons, donne-nous un roi. Maintenant donc, présentez-vous devant le Seigneur, par tribus, par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Samuel fit alors avancer toutes les tribus d’Israël, et le sort désigna la tribu de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Il fit avancer la tribu de Benjamin, par familles, et le sort désigna la famille de Mattari. On fit avancer la famille de Mattari homme par homme, et le sort désigna Saül, fils de Cis. Samuel le demanda, mais on ne le trouva point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Et Samuel interrogea encore le Seigneur, disant: L’homme est-il venu ici? Et le Seigneur lui répondit: Il est caché parmi les bagages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Il y courut, il l’y trouva, et il l’amena au milieu du peuple. Or, il dépassait le peuple entier de toute la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Samuel dit alors à tout le peuple: Avez-vous vu celui que le Seigneur s’est choisi? a-t-il parmi vous son pareil? Tout le peuple fut de son avis, et ils crièrent: Vive le roi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Samuel apprit ensuite au peuple les justes droits du roi; il les transcrivit en un livre qu’il déposa devant le Seigneur. Enfin, Samuel congédia tout le peuple, et chacun retourna en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Saül rentra dans sa maison à Gabaa; et les hommes vaillants, dont Dieu avait touché le cœur pour qu’ils s’unissent à Saül, l’accompagnèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Mais les fils de pestilence dirent: Est-ce celui-là qui nous sauvera? Et ils le méprisèrent, et ils ne lui portèrent point de présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Environ un mois plus tard, Naas l’Ammonite, s’étant mis en marche, campa vers Jabès-Galaad. Tous les hommes de Jabès-Galaad lui dirent alors: Fais avec nous alliance, et nous te servirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Mais Naas l’Ammonite leur dit: Je ferai alliance avec vous, à la condition de vous arracher à tous l’œil droit, et j’imposerai un opprobre à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Les hommes de Jabès lui dirent: Accorde-nous sept jours; nous dépêcherons des envoyés sur tout le territoire d’Israël, et, si personne ne vient nous sauver, nous nous rendrons à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Et les messagers allèrent trouver Saül en Gabaa; ils répétèrent au peuple ces discours, et tout le peuple, élevant la voix, se prit à pleurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Or, Saül à ce moment revenait des champs, après le matin, et il dit: Pourquoi le peuple pleure-t-il? On lui rapporta les paroles des hommes de Jabès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Lorsque Saül les eut entendues, l’Esprit du Seigneur s’élança sur lui, et, en son cœur, il se courrouça vivement contre l’Ammonite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Il prit deux vaches, et il les dépeça, et il envoya leurs membres sur tout le territoire d’Israël, par la main de messagers, disant: C’est ainsi que seront traités ceux qui ne marcheront pas avec Saül et avec Samuel. Un transport suscité par le Seigneur vint au peuple d’Israël, et il cria comme un seul homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Et Saül les passa en revue à Bésech en Bama; il y avait d’Israël six cent mille hommes, et de Juda soixantedix mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Il dit alors aux messagers, qui étaient revenus: Portez ces paroles aux hommes de Jabès: A demain votre salut, au moment de la grande chaleur du soleil. Les messagers retournèrent à la ville, et racontèrent tout aux hommes de Jabès; ceux-ci en furent remplis de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Les hommes de Jabès dirent alors à Naas l’Ammonite Demain, nous nous rendrons à vous, et vous nous traiterez comme bon vous semblera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Le lendemain, Saül divisa le peuple en trois corps; ils entrèrent dans le camp ennemi pendant la garde de l’aurore, et ils frappèrent les fils d’Ammon jusqu’à ce que le jour s’échauffàt. Les survivants se dispersèrent, et il n’en resta pas deux ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Et le peuple dit à Samuel: Qui donc prétendait que Saül ne règnerait pas sur nous? Livre-nous-les ces hommes, et nous les mettrons à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Mais Saül dit: Personne ne mourra en un jour où le Seigneur a sauvé Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Et Samuel dit au peuple: Allons à Galgala; nous inaugurerons en cette ville la royauté nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Tout le peuple se rendit à Galgala, et là, devant le Seigneur, Samuel sacra Saül comme roi; il y fit au Seigneur des sacrifices, et il y offrit des hosties pacifiques. Et Samuel et le peuple se réjouirent extrêmement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Ensuite, Samuel dit à tout Israël: Voyez, j’ai fait tout ce que vous m’avez demandé, et je vous ai donné un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Voici maintenant qu’un roi marche à votre tête; pour moi, je suis vieux et vais me tenir en repos; je laisse parmi vous mes fils, après avoir marché à votre tête depuis ma naissance jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Or, répondez-moi devant le Seigneur et devant son oint: A qui de vous ai-je pris un bœuf ou un âne? Qui de vous ai-je opprimé? qui ai-je violenté? de qui ai-je accepté l’offrande de quoi que ce soit, même d’une chaussure? Déclarez-le, et je restituerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Et chacun dit à Samuel: Tu n’as point commis d’iniquités envers nous; tu ne nous as point opprimés, tu ne nous a point violentés, tu n’as rien pris à aucun d’entre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Et Samuel dit au peuple: Le Seigneur est témoin, l’oint du Seigneur est témoin aujourd’hui que vous n’avez rien à me réclamer; et ils dirent: Témoin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel dit encore au peuple: Je prends à témoin le Seigneur qui a suscité Moïse et Aaron, qui a tiré vos pères de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Maintenant, tenez-vous tranquilles; je vais vous juger devant le Seigneur, je vous dévoilerai toute la justice du Seigneur, tout ce qu’il a fait pour vous et pour vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Lorsque Jacob et ses fils se furent établis en Égypte, l’Égypte les humilia; et vos pères crièrent au Seigneur, et le Seigneur envoya Moïse avec Aaron qui conduisirent vos pères hors de l’Égypte, et les mirent en possession de cette terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Ensuite, vos pères méconnurent le Seigneur leur Dieu, et il les livra aux mains de Sisara, général de Jabin, roi d’Azor; puis, aux mains des Philistins; puis, aux mains du roi de Moab, et il combattit du côté de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Alors, ils crièrent au Seigneur; ils dirent: Nous avons péché, car nous avons abandonné le Seigneur, et nous avons servi Baal dans les bois sacrés; délivrez-nous des mains de nos ennemis, et nous vous servirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Et le Seigneur a suscité Jérobaal, puis Barac, puis Jephté, puis Samuel; il vous a délivrés des mains des ennemis qui vous entourent, et vous avez habité en paix vos maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Et, vous avez vu récemment que Naas, roi des fils d’Ammon, marchait contre vous, et vous avez dit: Nous le voulons, il faut qu’un roi règne sur nous. Et cependant, le Seigneur notre Dieu était notre roi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Or maintenant, voici le roi que vous avez élu; vous voyez que le Seigneur vous a donné un roi, et vous prospérerez,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Si vous craignez le Seigneur, si vous le servez, si vous êtes dociles à sa voix, si vous ne résistez point à ses paroles, si vous et votre roi vous marchez avec le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mais si vous êtes indociles à la voix du Seigneur, si vous résistez à ses paroles, la main du Seigneur s’appesantira sur vous et sur votre roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Maintenant retirez-vous tranquilles, et vous verrez le grand prodige que le Seigneur va faire éclater à vos yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'N’est-ce pas aujourd’hui la moisson du froment? Je vais invoquer le Seigneur; il vous enverra le tonnerre et la pluie, et vous reconnaîtrez et vous verrez combien a été grande votre méchanceté devant le Seigneur, quand vous avez demandé pour vous un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Samuel invoqua donc le Seigneur, et, en ce jourlà, le Seigneur envoya le tonnerre et la pluie. Alors, tout le peuple eut une grande crainte du Seigneur et de Samuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Et tout le peuple dit à Samuel: Prie le Seigneur ton Dieu pour tes serviteurs, afin que nous ne mourions pas, parce qu’à tous nos péchés nous avons ajouté la faute de demander pour nous un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Et Samuel dit au peuple: N’ayez point de crainte; vous avez commis réellement tous cette faute; mais ne vous écartez pas des voies du Seigneur, servez-le de tout votre cœur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Ne vous laissez pas égarer par des dieux qui n’existent point, qui ne peuvent rien, qui ne délivrent personne, puisqu’ils ne sont que néant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Tandis que le Seigneur, à cause de son grand nom, ne répudiera pas son peuple, car le Seigneur vous a visiblement choisis pour être son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Pour moi, je me garderai de pécher contre le Seigneur, et de cesser de prier pour vous. Je servirai le Seigneur, et je vous montrerai la voie bonne et droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Mais craignez le Seigneur, servez-le dans la vérité et de tout votre cœur, puisque vous avez vu les grandes choses qu’il a faites parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Et si vous retombez dans le péché, vous périrez vous et votre roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Après cela, Saül choisit trois mille hommes, parmi ceux d’Israël. Il y en eut avec lui deux mille à Machmas et en la montagne de Béthel, et avec Jonathas mille, à Gabaa en Benjamin. Le reste du peuple fut congédié, et chacun retourna en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Jonathas battit le Nasib, étranger qui demeurait sur la colline; les Philistins l’apprirent, et Saül fit retentir la trompette en toute la terre promise, disant: Les esclaves secouent le joug.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Et tout Israël écouta ceux qui publiaient: Saül a détruit le Nasib étranger; et Israël se souleva contre les Philistins, et tous les fils d’Israël suivirent Saül en Galgala.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Cependant, les Philistins se réunirent pour porter la guerre en Israël; ils firent marcher contre Israël trente mille chars, six mille cavaliers et des piétons nombreux comme le sable de la mer; ils campèrent à Machmas, en face de Béthoron du Midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Or, Israël vit qu’il était trop faible pour les aborder; et le peuple se cacha dans les cavernes, dans les lieux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Ceux qui avaient passé le Jourdain le traversèrent encore pour se réfugier dans les territoires de Gad et de Galaad. Et Saül était encore à Galgala, et toute la troupe qui le suivait était frappée d’effroi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Il laissa écouler sept jours, comme le lui avait dit Samuel; mais Samuel ne vint pas le trouver en Galgala, et la troupe qui l’entourait se dispersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Et Saül dit: Amenez ici des victimes pour que je prépare un holocauste et des hosties pacifiques; puis, il offrit l’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Comme il achevait le sacrifice, Samuel arriva, t Saül sortit à sa rencontre afin de lui rendre hommage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Et Samuel dit: Qu’as-tu fait? Et Saül répondit: J’ai vu que le peuple autour de moi se dispersait, que tu n’étais point venu au temps indiqué, et que les Philistins étaient réunis à Machmas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Et j’ai dit: Maintenant les Philistins vont descendre sur moi à Galgala et je n’ai point prié devant le Seigneur: je me suis donc résolu à offrir l’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Et Samuel dit à Saül: Tu as agi en insensé, car tu n’as point obéi à mon ordre, à l’ordre du Seigneur, au moment où le Seigneur t’avait préparé sur son peuple une royauté perpétuelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Maintenant donc cette royauté ne te restera pas, et Dieu se cherchera un homme selon son cœur; et le Seigneur le chargera de gouverner son peuple, parce que tu n’as pas observé le commandement du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Et Samuel partit, il quitta Galgala, et ce qu’il y avait encore là de peuple suivit Saül pour rejoindre les hommes de guerre. Quand ils furent arrivés de Galgala en Gabaa, Saül passa en revue la troupe qui se trouvait avec lui; elle était réduite à six cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Et Saül, avec son fils Jonathas et la troupe qui les avait suivis, s’arrêta à Gabaa en Benjamin, où tous pleurèrent; cependant les Philistins étaient campés à Machmas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Et ceux-ci, portant avec eux le ravage, sortirent de leur camp en trois troupes: l’une prit le chemin de Gophera sur le territoire de Sogal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Une autre prit la route de Béthoron; la troisième, le chemin de Gabaa, qui fait un détour vers Haï des Sabim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Et, sur tout le territoire d’Israël, on ne trouvait pas un seul forgeron, parce que les Philistins avaient dit: Il ne faut pas que les Hébreux fabriquent lance ou épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Et tout Israël descendait chez les Philistins pour forger chacun sa faucille, ses outils, sa hache ou sa faux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'On était près de vendanger; or, pour un outil à dents, il fallait payer trois sicles, et autant pour une hache ou pour une faux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Et, dans les jours de la guerre de Machmas, on ne trouva pas une épée ni une lance dans la main de l’un des fils d’Israël qui accompagnaient Saül et Jonathas; on n’en eût trouvé que dans les mains du roi et de son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Cependant, des Philistins étaient sortis du côté opposé au camp de Machmas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Or, un jour vint où Jonathas, fils de Saül, dit au serviteur qui portait ses armes: Viens, allons à la station des Philistins du côté opposé au lieu où nous sommes; et il n’en dit rien à son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saül était campé au sommet de la colline, sous le grenadier qui est en Magdon, ayant avec lui environ six cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Et Achias, fils d’Achitob, frère de Jochabed, fils de Phinéès, fils d’Héli, était prêtre à Silo portant l’éphod. Et le peuple ne savait pas que Jonathas était parti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Au milieu du passage par où Jonathas voulait pénétrer parmi les Philistins, il y a un chemin bordé à droite et à gauche de rochers, qu’on appelle l’un Basès, l’autre Senna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Ce chemin était, d’une part, au nord de celui qui venait de Machmas; d’autre part, au midi de celui qui venait de Gabaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Et Jonathas dit au serviteur qui portait ses armes: Viens, marchons à la station de ces incirconcis; voyons si le Seigneur fera quelque chose pour nous, car le Seigneur n’est pas astreint à sauver avec beaucoup d’hommes plutôt qu’avec un petit nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Le serviteur qui portait ses armes répondit: Fais selon le mouvement de ton cœur, je suis avec toi; mon cœur est comme ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Et Jonathas lui dit: Voici que nous allons monter au-dessus de ces hommes; puis nous roulerons en bas sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'S’ils nous disent: Halte-là; attendez que nous vous ayons parlé, nous nous arrêterons, et nous ne monterons pas pour les attaquer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Mais, s’ils nous disent: Montez vers nous, nous monterons, car le Seigneur nous les a livrés, ce sera là notre signe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Et tous les deux parvinrent à la station des Philistins, qui se dirent: Voici des Hébreux; ils sortent des cavernes où ils étaient cachés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Aussitôt, les hommes de la station s’adressèrent à Jonathas et à celui qui portait ses armes, disant: Montez vers nous, et nous vous ferons connaître quelque chose. A ces mots, Jonathas dit à celui qui portait ses armes: Suis-moi, le Seigneur nous les a livrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Jonathas monta donc en s’aidant des mains comme des pieds, et celui qui portait ses armes le suivit; les Philistins se trouvèrent face à face avec Jonathas quand celui-ci se mit à les frapper; son serviteur alors arrivait derrière lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Or, ce fut le premier fait d’armes de Jonathas et de son serviteur; ils leur tuèrent une vingtaine d’hommes, avec des dards, des frondes et des cailloux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Et l’effroi se répandit dans le camp et la plaine; toutes les troupes de la station et les pillards au dehors, saisis de stupeur, furent incapables d’agir; la contrée trembla, et le Seigneur répandit partout l’épouvante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Cependant, les éclaireurs de Saül virent de Gabaa le trouble du camp et les hommes qui fuyaient çà et là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Et Saül dit aux siens: Examinez bien, et voyez qui des nôtres est parti; ils cherchèrent, et l’on ne trouva ni Jonathas ni celui qui portait ses armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Et Saül dit à Achias: Présente l’éphod; car, en ce jour-là, Achias portait l’éphod devant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Pendant que Saül parlait au prêtre, la rumeur du camp des Philistins, toujours croissante, se répandit et se répandit. Et Saül dit au prêtre: Joins les mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Saül aussitôt, avec toute sa troupe, se porta au combat; il vit les ennemis tournant les uns contre les autres leurs épées; c’était une confusion vraiment très grande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Les Hébreux, devenus depuis peu esclaves dans le camp des Philistins, se soulevèrent pour se joindre à Israël, à Saül, à Jonathas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Et tous ceux d’Israël, qui s’étaient cachés dans les montagnes d’Ephraïm, apprirent que les Philistins fuyaient; et ils se mirent à leur poursuite; et, ce jour-là, le Seigneur sauva Israël. La bataille fut livrée en Bamoth, et Saül eut environ dix mille hommes avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'On combattit dans toutes les villes des montagnes d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Or, Saül, ce jour-là, commit un grand péché par ignorance: il prononça une malédiction contre le peuple, disant: Maudit soit l’homme qui mangera avant le soir; car je veux avant tout tirer vengeance de mon ennemi. Et nul, parmi le peuple, ne goûta de pain, tandis que, sur toute la terre, chacun prenait son repas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Et devant le champ de bataille, la forêt de Jaal était remplie de miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Le peuple passait près des abeilles, et s’en allait devisant, et nul n’osait porter la main à sa bouche; car ils redoutaient l’imprécation portée au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jonathas, qui n’avait point entendu son père adjurer le peuple, étendit la pointe de la baguette qu’il tenait à la main, la trempa dans un rayon de miel, porta la main à sa bouche, et ses yeux recouvrèrent la vue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Aussitôt, l’un du peuple s’écria, et lui dit: Ton père a vivement adjuré le peuple; il a dit: Maudit soit l’homme qui mangera avant le soir. Or, le peuple était à bout de forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Jonathas le savait, et il dit: Mon père trouble la terre promise; sois témoin que mes yeux ont recouvré la vue, dès que j’ai eu goûté un peu de ce miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Si le peuple s’était rassasié des vivres qu’il a trouvés parmi les dépouilles des ennemis, il y eût eu de ceux-ci un plus grand carnage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Or, ce jour-là, il avait exterminé nombre de Philistins à Machmas, et le peuple était accablé de fatigue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Et, le soir venu, le peuple, se jetant sur les dépouilles, prit des brebis, des bœufs, des veaux, et les égorgea à terre; puis, il les mangea avec leur sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Et des gens le rapportèrent à Saül, disant: Le peuple a péché contre le Seigneur, il a mangé des chairs avec du sang. Et Saül dit: Roulez-moi de Getthaïm ici une grande pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Cela fait, Saül dit à ces gens: Dispersez-vous parmi le peuple, dites-leur d’amener ici chacun son veau ou sa brebis; qu’on égorge les victimes sur cette pierre, et vous, gardez-vous de pécher envers le Seigneur en les mangeant avec leur sang. Le peuple amena donc là ce qu’il avait à conduire, et on égorgea les victimes au même lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Et Saül y bâtit un autel au Seigneur; ce fut le premier autel que Saül éleva au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Ensuite, Saül dit: Poursuivons toute la nuit les Philistins, nous leur ferons des prisonniers, jusqu’à ce que le jour paraisse, et nous n’en laisserons pas échapper un seul. A quoi ils répondirent: Fais ce que bon te semble. Mais le prêtre dit: Allons d’abord au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Et Saül fit cette question au Seigneur: Si je poursuis les Philistins, les livrerez-vous aux mains d’Israël? Le Seigneur ne lui répondit point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Et Saül dit: Faites venir ici tous les rangs d’Israël: que l’on sache lequel d’entre eux aujourd’hui a péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Car, vive le Seigneur qui a sauvé Israël, s’il est reconnu que c’est Jonathas mon fils, Jonathas sera mis à mort. Et, parmi le peuple, nul ne répondit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Alors, Saül dit à chaque homme d’Israël: Vous serez asservis; moi et mon fils Jonathas nous serons asservis. Et le peuple dit à Saül: Fais ce que bon te semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Et Saül dit: Seigneur Dieu d’Israël, pourquoi refusez-vous aujourd’hui de répondre à votre serviteur? Est-il en moi ou en mon fils Jonathas quelque iniquité? Donnez-nous des signes, et, s’ils nous accusent, donnez à votre peuple Israël, donnez-lui le privilége de l’innocence. Et le sort désigna Saül et Jonathas; le peuple sortit innocent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Puis, Saül dit: Agitez les sorts entre moi et Jonathas mon fils. Celui qu’indiquera le Seigneur, qu’il soit mis à mort. Le peuple, à ces mots, dit à Saül: Cela ne peut être; mais Saül imposa silence au peuple. L’on agita donc les sorts entre lui et Jonathas son fils, et le sort désigna Jonathas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Alors, Saül dit à Jonathas: Déclare-moi ce que tu as fait. Jonathas le lui avoua, et dit: J’ai goûté, au bout de la baguette que je tenais à la main, un peu de miel, et voilà que je meurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Et Saül dit: Que le Seigneur me punisse, et qu’il me punisse encore, si tu ne meurs aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Mais le peuple dit à Saül: Celui qui vient de sauver si bravement Israël mourra-t-il? Vive le Seigneur! pas un cheveu ne tombera de sa tête, car le peuple de Dieu a été vainqueur aujourd’hui. Le peuple, en ce jour-là, pria donc pour Jonathas, et il ne mourut pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Et Saül renonça à poursuivre les Philistins; et ceux-ci retournèrent en leur pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Saül, en obtenant par le sort la royauté, avait été chargé par le sort de faire œuvre pour Israël; tout alentour, il combattit donc ses ennemis: Moab, les fils d’Ammon, les fils d’Edom, Béthéor, le roi de Suba et tous les Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Il fut un homme fort; il vainquit Amalec, et il tira Israël des mains de ceux qui le foulaient aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Les fils de Saül étaient Jonathas, Jessui et Melchisa; ses filles se nommaient: la première, Mérob, la plus jeune, Michol.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Le nom de sa femme était Achinoom, fille d’Achimaas; son général s’appelait Abner, fils de Ner, parent de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Car Cis était père de Saül, et Ner, père d’Abner, était fils de Jamin, fils d’Abiel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'La guerre contre les Philistins fut rude pendant toute la vie de Saül, et tous les hommes puissants et les braves que voyait Saül, il les réunissait autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Et Samuel dit à Saül: Le Seigneur m’a jadis envoyé pour t’oindre roi d’Israël; maintenant, écoute la voix du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Voici ce que dit le Seigneur sabaoth: Je veux tirer vengeance de ce qu’a fait Amalec contre Israël lorsqu’il est venu à sa rencontre sur sa voie, comme il revenait d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Marche donc, et tu frapperas Amalec et Hiérim, et ce qui lui appartient; tu ne t’en approprieras rien, tu extermineras tout. Amalec sera anathème avec tout ce qui lui appartient; tu n’en épargneras aucune chose. Tu mettras à mort hommes et femmes, nourrissons et nourrices, bœufs et brebis, chamelles et ânesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Et Saül convoqua le peuple, et il passa en revue, à Galgala, quatre cent mille combattants, outre trente mille hommes de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Puis, Saül marcha sur la ville d’Amalec, et il se mit en embuscade dans le torrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Et Saül dit au Cénéen: Éloigne-toi et te sépare des Amalécites, de peur que je ne te confonde avec eux, car tu as été miséricordieux pour les fils d’Israël quand ils revenaient d’Égypte. Et le Cénéen se sépara d’Amalec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Et Saül battit Amalec, depuis Evilat jusqu’à Sur, en face de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Il prit vivant Agag, roi d’Amalec, et il passa au fil de l’épée tout le peuple, tout Hiérim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Mais Saül et tout le peuple laissèrent vivre Agag; ils épargnèrent ce qu’il y avait de meilleur parmi ses brebis, ses bœufs, ses vivres, le vin de ses vignes, tous ses biens; ils résolurent de ne les point détruire, et ils détruisirent toutes les choses viles ou de peu de valeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Et la parole du Seigneur vint à Samuel, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Je me reproche d’avoir fait roi Saül, parce qu’il a cessé de me suivre, et qu’il n’a point observé mes ordres; Samuel en fut abattu, et il cria toute la nuit au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Et Samuel se leva de grand matin; dès l’aurore, il partit à la rencontre d’Israël. On l’alla rapporter à Saül, disant: Samuel est arrivé au mont Carmel; il a levé une poignée d’hommes. A ce moment, Samuel tourna son char, et il descendit à Galgala vers Saül, comme celui-ci offrait en holocauste au Seigneur les prémices des dépouilles qu’il avait amenées d’Amalec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Samuel s’approcha de Saül, et Saül lui dit: Béni sois-tu au nom du Seigneur, j’ai fait tout ce qu’a ordonné le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Mais Samuel dit à Saül: Quels sont donc ces bêlements de brebis qui parviennent à mes oreilles, et ces mugissements de bœufs que je viens d’entendre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Et Saül lui dit: J’ai amené ce bétail d’Amalec; le peuple a épargné les plus belles têtes pour les sacrifier au Seigneur; j’ai détruit tout le reste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Alors, Samuel dit à Saül: Permets, je vais te dévoiler ce que cette nuit m’a dit le Seigneur. Et Saül répondit: Parle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Et Samuel dit à Saül: N’es-tu point petit à ses yeux, toi qui règnes sur les tribus d’Israël? C’est le Seigneur qui t’a sacré roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Et le Seigneur t’a envoyé contre Amalec, et il t’a dit: Marche, et extermine. Mets à mort ce peuple qui a péché contre moi; fais-lui la guerre jusqu’à ce que tu l’aies détruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Pourquoi donc n’as-tu pas été docile à la voix du Seigneur? Pourquoi as-tu pris sur toi de disposer du butin? Pourquoi as-tu fait le mal devant le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'C’est, reprit Saül, pour avoir écouté la clameur du peuple; je suivais la voie que m’avait indiquée le Seigneur; j’avais fait prisonnier Agag, et exterminé Amalec;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mais le peuple prit des dépouilles ce qu’il y avait de meilleur, parmi les brebis et les bœufs, pour les sacrifier, en Galgala, au Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Les holocaustes, dit Samuel, et les victimes sontils plus agréables au Seigneur que l’obéissance à sa voix? La docilité vaut mieux que les offrandes; l’obéissance vaut mieux que la graisse des béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'La désobéissance est un péché comme la divination; les theraphim amènent peines et douleurs. Parce que tu as dédaigné la parole du Seigneur, le Seigneur te rejettera du trône d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'J’ai péché, répondit Saül, en transgressant l’ordre du Seigneur et le tien; j’ai eu crainte du peuple, et j’ai écouté sa clameur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Maintenant, ôte-moi mon péché, reviens avec moi, et j’adorerai le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Mais Samuel dit à Saül: Je ne reviendrai plus vers toi; parce que tu as méprisé la parole du Seigneur, le Seigneur te méprisera; tu ne seras plus roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Et Samuel se retourna pour partir, mais Saül saisit le pan de son double manteau, et il le déchira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Et Samuel lui dit: Le Seigneur, par tes mains, a déchiré aujourd’hui ta royauté en Israël; il la donnera à ton prochain qui vaut mieux que toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Israël aussi sera déchiré en deux parts; le Seigneur ne changera pas, et il ne se repentira pas; car il n’est point comme un homme pour se repentir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Et Saül dit: J’ai péché; mais ne laisse pas de m’honorer devant les anciens d’Israël et devant mon peuple; viens-t’en avec moi, et j’adorerai ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Et Samuel revint auprès de Saül, et celui-ci adora le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Samuel dit ensuite: Amenez-moi Agag, roi d’Amalec; et Agag arriva tout tremblant. Et Agag dit: Fautil que la mort soit si amère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Et Samuel dit à Agag: De même que par ton glaive les femmes sont restées sans enfants, ta mère, parmi les femmes, tout à l’heure n’aura plus d’enfant. Et Samuel égorgea Agag devant le Seigneur, à Galgala.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Puis, Samuel retourna en Armathaïm, et Saül partit pour sa demeure à Gabaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Et Samuel cessa de visiter Saül jusqu’au jour de sa mort; mais il pleurait sur lui, parce que le Seigneur s’était repenti d’avoir fait Saül roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Enfin le Seigneur dit à Samuel: Jusqu’à quand pleureras-tu sur Saül, puisque je l’ai rejeté, ne voulant plus qu’il règne sur Israël? Remplis d’huile ta corne, et viens; je t’enverrai chez Jessé, en Bethléem, car j’ai choisi un roi parmi ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Et Samuel dit: Comment irai-je? Saül en sera informé et il me tuera. A quoi le Seigneur répondit: Prends avec toi une génisse; puis, tu diras: Je suis venu la sacrifier au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Tu inviteras Jessé au sacrifice, et je t’apprendrai ce que tu auras à faire; alors, tu donneras l’onction à celui que je te dirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Et Samuel fit tout ce que lui avait prescrit le Seigneur; il arriva en Bethléem, et les anciens de la ville s’étonnèrent grandement de sa venue, et ils dirent: Nous apportes-tu la paix, ô voyant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Il répondit: Oui, la paix; je suis venu sacrifier au Seigneur. Purifiez-vous aujourd’hui, et réjouissez-vous avec moi. Et il purifia Jessé et ses fils, et il les invita au sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Lorsqu’ils entrèrent, il vit Eliab, et il dit: Est-ce que l’oint du Seigneur est devant lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Et le Seigneur dit à Samuel: Ne fais pas attention à son extérieur ni à sa grande taille; je l’ai rejeté. Car Dieu ne voit pas comme l’homme; l’homme regarde la figure, Dieu regarde le cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Ensuite, Jessé appela Aminadab; il parut devant Samuel, et Samuel dit: Le Seigneur n’a point choisi celui-là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Alors, Jessé introduisit Sama, et Samuel dit encore: Le Seigneur ne l’a point non plus choisi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Et Jessé introduisit ses sept fils devant Samuel; mais Samuel dit: Ce n’est aucun de ceux-là qu’a choisi le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Et Samuel dit à Jessé: N’as-tu pas d’autres enfants? Et il répondit: Il y en a encore un plus petit; il est à garder le troupeau. Et Samuel dit à Jessé: Envoie-le chercher, car nous ne nous mettrons pas à table qu’il ne soit venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Jessé le fit venir; or, il était roux, avait de beaux yeux, et était d’aspect agréable devant le Seigneur. Le Seigneur dit donc à Samuel: Lève-toi, et sacre David; c’est lui qui est bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Samuel prit la corne d’huile, et il le sacra au milieu de ses frères; et l’Esprit du Seigneur s’élança sur lui à partir de ce jour-là et ne le quitta plus. Après cela, Samuel se leva et retourna en Armathaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Et l’Esprit du Seigneur se retira de Saül, et un mauvais esprit, envoyé par le Seigneur, le tourmenta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Et les serviteurs de Saül lui dirent: Voilà que le mauvais esprit du Seigneur te tourmente;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Permets à tes serviteurs de parler devant toi, et de chercher pour leur maître un homme habile à toucher de la harpe. Quand le mauvais esprit sera sur toi, l’homme touchera de sa harpe, et il te fera du bien, et il te calmera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Saül dit à ses serviteurs: Voyez, trouvez-moi un homme habile à toucher de la harpe, et amenez-le-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'L’un de ses serviteurs prit la parole, et dit: Je connais le fils de Jessé de Bethléem; il est habile à toucher de la harpe; c’est un homme intelligent et brave; il est plein de sagesse, d’aspect agréable, et le Seigneur est avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Et Saül dépêcha des messagers auprès de Jessé, disant Envoie-moi ton fils David, celui qui garde ton troupeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Alors, Jessé prit un gomor de pain, une outre de vin, un chevreau; il les remit entre les mains de David, et il l’envoya auprès de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Et David fut introduit devant Saül; il lui fut présenté; Saül l’aima beaucoup, et il le chargea de porter ses armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Et Saül fit dire à Jessé: Que David reste auprès de moi, parce qu’il a trouvé grâce à mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Or, quand le mauvais esprit était sur Saül, David prenait sa harpe, il en touchait, et il calmait Saül; il lui faisait du bien, et chassait le mauvais esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Et les Philistins rassemblèrent leur armée pour combattre; ils se réunirent vers Socchoth en Juda; ils campèrent entre Socchoth et Azéca-Ephermen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Et Saül et les hommes d’Israël se réunirent; ils campèrent dans la vallée, et ils se rangèrent en bataille devant les Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Les étrangers se tenaient sur une montagne, et Israël était sur la montagne opposée: une vallée les séparait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Or, un homme d’une grande force sortit des rangs des Philistins; il était de Geth, et il se nommait Goliath; il avait quatre coudées et une spithame.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Il portait sur la tête un casque, et sur la poitrine une cotte de mailles; cette armure pesait cinq mille sicles d’airain ou de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Sur ses jambes étaient des cnémides d’airain, et entre ses deux épaules était un bouclier d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'La hampe de sa javeline était semblable à un mât de tisserand; la pointe pesait six cents sicles de fer; et celui qui portait ses armes le précédait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Il s’avança en criant vers les rangs d’Israël, et il dit: Pourquoi êtes-vous venus vous mettre en bataille devant nous? Ne suis-je pas un Philistin; n’êtes-vous pas les Hébreux de Saül? Choisissez parmi vous un homme, et qu’il descende près de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'S’il est capable de me combattre, s’il triomphe de moi, nous serons vos esclaves; si c’est moi qui l’emporte, et si je le tue, vous serez nos esclaves et vous nous servirez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Le Philistin ajouta: Voyez, j’ai défié aujourd’hui l’armée d’Israël; donnez-moi donc un homme, et que nous combattions seul à seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Saül et tout Israël entendirent ces paroles du Philistin; ils en furent hors d’eux-mêmes, et ils eurent grande crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, '(32) Alors, David dit à Saül: Que le cœur de mon maître ne soit pas abattu; ton serviteur marchera, et il combattra ce Philistin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, '(33) Mais Saül dit à David: Tu n’es point capable de combattre ce Philistin; tu n’es qu’un enfant, et il est homme de guerre depuis sa jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, '(34). Et David dit à Saül: Ton serviteur était berger chez son père, il gardait les troupeaux, et quand venait un lion ou un ours, quand ils prenaient tour à tour une tête du troupeau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, '(35) Je courais après le ravisseur, je le frappais, je lui arrachais sa proie de la gueule; puis, comme il s’ élançait sur moi, je le saisissais à la gorge, je venais à bout de lui, et je le tuais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, '(36) Ton serviteur a tué le lion et l’ours, il en sera de même de cet incirconcis; pourquoi donc n’irai-je pas le tuer, et effacer aujourd’hui l’outrage qu’il fait à Israël? Car, quel est cet incirconcis qui a défié l’armée du Dieu vivant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, '(37) Le Seigneur, qui m’a tiré des griffes du lion et de celles de l’ours, me retirera de la main de cet incirconcis. Et Saül dit à David: Marche, le Seigneur sera avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, '(38) Saül alors revêtit David d’une cuirasse; il lui mit sur la tête son propre casque d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, '(39 et 40) Par-dessus la cuirasse, David ceignit son épée, et il essaya une fois et deux fois de marcher ainsi; mais il se fatigua, et dit à Saül: Je ne pourrai marcher avec ces armes, je n’y suis point accoutumé. Et on les lui ôta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, '(41) Et il prit à la main sa houlette; il choisit cinq cailloux polis par le torrent; il les mit tous dans la panetière de berger qu’il portait sur lui; enfin, il s’arma de sa fronde, et il marcha contre le Philistin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, '(42) Goliath vit David, et il le méprisa, parce que c’était un jeune garçon, qu’il était roux et qu’il avait de beaux yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, '(43) Et le Philistin dit à David: Me prends-tu pour un chien, toi qui viens à moi avec une houlette et des pierres? Et David reprit: Nullement, mais pour moins qu’un chien. Et le Philistin maudit David en invoquant tous ses dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, '(44) Et le Philistin dit à David: Viens, approche, que je donne ta chair aux oiseaux du ciel et aux bêtes fauves des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, '(45) Mais, David dit au Philistin Tu marches contre moi avec le glaive, la javeline, le bouclier; moi je marche contre toi, au nom du Seigneur Dieu sabaoth, Dieu de l’armée d’Israël que tu as insultée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, '(46) Le Seigneur aujourd’hui t’enfermera dans ma main; je te tuerai, je te trancherai la tête; aujourd’hui je donnerai tes lambeaux et les lambeaux de l’armée des Philistins aux oiseaux du ciel et aux bêtes fauves de la terre. Toute la terre alors reconnaîtra que Dieu est avec Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, '(47) Toute cette Église connaîtra que le Seigneur ne sauve point avec le glaive et la javeline; car cette guerre est du Seigneur, et il vous livrera à nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, '(48) A ces mots, le Philistin s’ébranla, et il marcha à la rencontre de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, '(49) De son côté, David porta sa main à sa panetière; il y prit un caillou; il le lança avec la fronde, et il atteignit le Philistin au front; la pierre, à travers le casque, pénétra dans le crâne, et Goliath tomba la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, '(51) Et David courut, s’arrêta sur lui, prit son glaive, le tua et lui trancha la tête. Les Philistins virent que leur homme fort était tué, et ils prirent la fuite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, '(52) Alors, les hommes d’Israël et de Juda se levèrent, poussant de grands cris de joie, et poursuivirent les fuyards jusqu’à l’entrée de Geth et jusqu’aux portes d’Ascalon. Une multitude de Philistins tomba sur les chemins de ces villes, et sur celui d’Accaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, '(53) Et les hommes d’Israël s’en retournèrent après avoir poursuivi les Philistins, et détruisirent leur camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, '(54) Et David prit la tête du Philistin et il l’emporta à Jérusalem, et il plaça en sa demeure les armes de Goliath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, '(6) Et les chœurs de danseuses, transportées de joie, sortirent de toutes les villes d’Israël à la rencontre de David, avec des tambours et des cymbales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, '(7) Les femmes entonnaient le chant et elles disaient Saül les a tués par milliers, et David par myriades.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, '(8) La chose parut mauvaise à Saül, et il dit: Elles attribuent à David des myriades, et à moi des milliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, '(12) Et Saül fut alarmé au sujet de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, '(13) Il l’éloigna de sa personne; il lui donna un commandement de mille hommes, et David fit ses évolutions devant le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, '(14) Et David en toutes ses démarches se conduisit avec prudence, car le Seigneur était avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, '(15) Et Saül vit sa grande sagesse, et il eut crainte de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, '(16) Or, tout Israël et tout Juda aimaient David, parce qu’il marchait à la tête du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, '(20) Et Michol, fille de Saül, aima David; on l’alla dire à Saül, et la nouvelle lui plut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, '(21) Car Saül dit: Je la lui donnerai, et ce sera pour lui une pierre d’achoppement. La main des Philistins était alors contre Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, '(22) Et Saül donna ses ordres à ses serviteurs, disant: Parlez en secret à David, et dites-lui: Voilà que le roi se plaît avec toi, tous ses serviteurs t’aiment, sois donc le gendre du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, '(23) Les serviteurs de Saül répétèrent tout bas ces paroles à David, et il leur répondit: Est-ce si peu de chose à vos yeux de devenir gendre du roi? Je suis d’humble condition et nullement illustre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, '(24) Et les serviteurs de Saül lui firent leur rapport, en conséquence de ce que leur avait dit David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, '(25) Et Saül reprit: Voilà ce que vous direz à David: Le roi n’a que faire de présents, si ce n’est de cent prépuces de Philistins, pour se venger des ennemis du roi. Saül comptait ainsi le jeter entre les mains des étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, '(26) Les serviteurs de Saül répétèrent ces paroles à David, et il lui parut bon d’être gendre du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, '(27) David partit donc, il se mit en campagne avec ses hommes, il tua cent Philistins, rapporta leurs prépuces, et devint gendre du roi; Saül lui donna pour femme sa fille Michol.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, '(28) Et Saül vit que le Seigneur était avec David, et que tout Israël l’aimait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, '(29) Et il se défia encore davantage de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Et Saül parla à Jonathas son fils, ainsi qu’à tous ses serviteurs, pour qu’ils tuassent David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Or, Jonathas, fils de Saül, aimait beaucoup David, et Jonathas avertit David, disant: Saül cherche à te tuer; prends donc garde à toi; dès demain à l’aurore, cachetoi et demeure caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Quant à moi, je sortirai et je m’arrêterai avec mon père dans le champ où tu seras; je lui parlerai de toi; je verrai ce qu’il en est, et je te le ferai savoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Et Jonathas parla favorablement de David à son père, et il lui dit: Que le roi ne se rende pas coupable envers David, son serviteur, car il n’est point coupable envers toi, et toutes ses actions sont bonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Il a placé sa vie dans sa main, il a tué l’étranger, et le Seigneur nous a sauvés d’une manière éclatante; tout Israël l’a vu et s’en est réjoui: pourquoi donc pècherais-tu contre le sang innocent, en tuant sans sujet David?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Saül se rendit aux paroles de Jonathas; Saül prêta serment, et il dit: Vive le Seigneur, David ne mourra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Et Jonathas appela David; il lui répéta tout cet entretien, et il l’amena auprès de Saül, qui fut pour lui ce qu’il était précédemment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Or, Saül eut une nouvelle guerre; et David remporta la victoire; il combattit les Philistins; et il les frappa d’une très-grande plaie, et ils s’enfuirent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Alors, un mauvais esprit de Dieu saisit Saül; celuici dormait dans sa maison la javeline à la main, et David touchait de la harpe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Et Saül, s’éveillant, chercha à tuer David d’un coup de javeline, mais David s’esquiva, la javeline frappa le mur; David s’enfuit et fut sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Cette nuit-là, Saül envoya des messagers à la maison de David pour l’épier et le tuer dès le matin; mais Michol, femme de David, l’avertit, disant: Si cette nuit même tu ne sauves pas ta vie, demain tu seras mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Et Michol fit sortir David par la fenêtre; il partit, s’enfuit et fut sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Et Michol prit une image qu’elle posa sur le lit; à la tête elle mit du poil de chèvre, et elle couvrit le corps d’un manteau. être un mannequin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Or, Saül avait envoyé des messagers pour prendre David, et ils vinrent lui dire qu’il était malade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Il les renvoya chez David, disant: Amenez-le-moi et qu’il meure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Les messagers retournèrent chez David et ils virent l’image sur le lit, et à la tête le poil de chèvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Et Saül dit à Michol Pourquoi m’avoir ainsi trompé en faisant échapper mon ennemi? Le voilà sauvé. Et Michol dit à Saül: Il m’a dit: Laisse-moi fuir; sinon je te tuerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Or, David s’était enfui, et il était sauvé; il se rendit chez Samuel en Armathaïm, et il lui raconta tout ce que lui avait fait Saül. Aussitôt, Samuel partit avec David, et ils séjournèrent à Navath en Rhama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Et des gens le rapportèrent à Saül, disant: Voilà que David est à Navath en Rhama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Et Saül envoya des messagers pour prendre David; or, ils virent l’assemblée des prophètes, Samuel à leur tête, et l’Esprit de Dieu vint sur les messagers de Saül, et ils prophétisèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Des gens l’allèrent dire à Saül, et il envoya d’autres messagers; et ceux-ci pareillement se mirent à prophétiser; Saül en envoya d’autres qui prophétisèrent encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Enfin, Saül s’enflamma de colère; il partit luimême pour Armathaïm, et alla jusqu’au puits de l’aire qui est à Séphi; il s’informa et il dit: Où sont Samuel et David? On lui répondit: Ils sont à Navath en Rhama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Saül partit donc pour Navath en Rhama, et l’Esprit de Dieu vint aussi sur lui, et il alla prophétisant, jusqu’à l’entrée de Navath en Rhama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Là, il se dépouilla de ses vêtements; il prophétisa devant l’assemblée, et il resta nu</ref>C’est-à-dire qu’il quitta ses vêtements royaux, et ne garda que les habits de dessous.</ref>, tout ce jour-là et toute la nuit, se tenant prosterné; à cause de cela on dit: Saül aussi est-il au nombre des prophètes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Et David s’enfuit de Navath en Rhama; il alla trouver Jonathas, et il lui dit: Qu’ai-je fait? Quelle est ma faute? En quoi ai-je péché contre ton père, pour qu’il en veuille à ma vie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Et Jonathas lui dit: Éloigne cette pensée: tu ne mourras point. Vois donc, mon père ne fait aucune chose, petite ou grande, sans me la confier; pourquoi me cacherait-il ce dessein? Cela ne peut être.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'David répondit à Jonathas: Ton père n’ignore pas que j’ai trouvé grâce devant tes yeux, et il s’est dit: Ne faisons point connaître ce dessein à Jonathas, de peur qu’il ne refuse d’y consentir; mais vive le Seigneur et vive ton âme! ce que je t’ai dit est vrai; il n’y a plus d’intervalle entre moi et la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jonathas repartit: Que désire ton âme, et que feraije pour toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Et David reprit: C’est demain la nouvelle lune; je ne m’assoirai point pour manger, tu me feras sortir, et je me cacherai dans les champs jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Et, si ton père me cherche, tu lui diras: David m’a demandé avec instance de courir jusqu’à Bethléem, sa ville, parce que toute sa tribu y fait le sacrifice du jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Et s’il répond: C’est bien, ton serviteur aura retrouvé la paix; mais s’il te répond durement, crois que le mal en lui touche à sa consommation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Tu seras donc miséricordieux envers ton serviteur, parce qu’entre lui et toi tu as voulu que soit faite l’alliance de Dieu. Mais s’il est quelque iniquité en ton serviteur, mets-le toi-même à mort; car, en ce cas, qu’est-il besoin que tu me conduises jusqu’à ton père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonathas répondit: Éloigne cette pensée; car si je reconnais que mon père va consommer quelque méchanceté contre toi, quand même ce serait ailleurs qu’en ta ville, je te le dirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Et David reprit: Qui m’apprendra si ton père a répondu durement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonathas lui dit: Pars et attends-moi aux champs. Or bientôt, tous les deux se retrouvèrent dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Et Jonathas dit à David: Le Seigneur Dieu d’Israël sait que, selon l’opportunité, je sonderai les sentiments de mon père avant trois jours; s’il est bien disposé pour toi, je ne t’enverrai personne aux champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Si tu as à craindre quelque mal, que Dieu me punisse et me punisse encore, si je ne te le dévoile pas; alors, je te ferai échapper, tu t’en iras en paix; et le Seigneur sera avec toi, comme il était avec mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Si je suis encore vivant, tu seras miséricordieux pour moi, et si je meurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Ni toi ni les tiens ne priverez ma famille de votre miséricorde à jamais. Oui, si je ne t’avertis; lorsque le Seigneur fera disparaître un à un de la face de la terre les ennemis de David, que le nom de Jonathas se trouve du nombre, et que le Seigneur punisse les ennemis de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Et Jonathas réitéra le serment qu’il avait prêté à David, parce qu’il aimait du fond de l’âme celui qui l’aimait tant lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Et Jonathas dit: Demain nouvelle lune, on te cherchera, et l’on examinera ton siége.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Tu attendras trois jours attentif à toutes choses, et tu te tiendras où tu te retires habituellement dans les jours de travail, près de la roche d’Ergab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Et moi, je lancerai trois fois des flèches dans la direction d’Amattari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Et j’enverrai un jeune serviteur, disant: Va, retrouve-moi ma flèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Et si je lui dis: Voici la flèche à ta droite ou à ta gauche, ramasse-la; toi, David, tu pourras approcher, la paix est avec toi, il n’y a rien à craindre, vive le Seigneur! Mais si je dis au jeune homme: Voilà la flèche plus loin devant toi; pars, le Seigneur t’envoie plus loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Je prends à témoin le Seigneur à jamais de ce que nous venons de nous dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Et David se cacha dans le champ, et il y eut une nouvelle lune, et le roi se mit à table pour manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Il s’assit comme d’habitude sur son siége qui était appuyé au mur; il avait passé avant Jonathas, et Abner s’assit à côté de Saül; or, la place du fils de Jessé était vide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saül, ce jour-là, ne dit rien, ayant cette pensée: C’est évidemment la marque qu’il n’est point pur, parce qu’il ne s’est point purifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Vint ensuite le lendemain de la pleine lune, le second jour, et la place du fils de Jessé était vide. Ce que voyant Saül, il dit à Jonathas, son fils: Pourquoi David ne s’est-il pas mis à table hier ni aujourd’hui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonathas répondit: David m’a demandé d’aller jusqu’à Bethléem, sa ville;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Il m’a dit: Permets-le-moi, je t’en conjure; parce que toute notre tribu offre dans la ville un sacrifice; mes frères m’ont invité; maintenant donc, si j’ai trouvé grâce devant tes yeux, j’irai et je verrai mes frères. Voilà pourquoi il ne s’est point assis à la table du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Et Saül s’enflamma de colère contre Jonathas; il lui dit: Fils de filles éhontées, ne savais-je pas que tu étais l’associé du fils de Jessé, à ta honte et à la honte de ta mère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Tant que le fils de Jessé vit sur la terre, ta royauté n’a pas de consistance. Maintenant donc, envoie quelqu’un prendre ce jeune homme, car il est fils de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Mais, Jonathas répondit à Saül: Pourquoi mourrait-il? qu’a-t-il fait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Et Saül leva sa javeline contre Jonathas pour le tuer; Jonathas reconnut ainsi que la méchanceté de son père contre David touchait à sa consommation, et qu’il voulait le faire périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Plein de courroux, il quitta brusquement la table, et, le second jour de la lune, il ne prit aucun aliment, parce qu’il était accablé de douleur à cause de David, et que la violence de son père contre celui-ci avait éclaté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Le malin venu, Jonathas sortit dans la plaine comme il en était convenu avec David, et il emmena un jeune garçon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Et il dit à l’enfant: Cours, trouve-moi les flèches que j’ai lancées. Le serviteur courut, et Jonathas tira une seconde flèche plus loin que la première.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Et l’enfant arriva où était celle-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Et Jonathas lui cria: L’autre flèche est plus loin; vite, hâte-toi, ne t’arrête point. Et l’enfant ramassa les flèches de Jonathas, et il les rapporta à son maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Or, l’enfant ne savait rien; il n’y avait d’informés que Jonathas et David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Et Jonathas donna au serviteur son arc et ses flèches, et il dit: Va-t’en, retourne à la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Comme l’enfant y arrivait, David sortit des rochers, tomba la face contre terre, et adora trois fois Jonathas; ensuite, ils se baisèrent tous les deux, et ils pleurèrent tous les deux jusqu’à ce qu’ils se séparas sent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Et Jonathas dit à David: Va en paix, que notre mutuel serment subsiste; car nous avons juré, au nom du Seigneur, quand nous avons dit: Le Seigneur sera témoin pour toujours entre toi et moi, entre ma postérité et la tienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 43, 'David s’éloigna donc, et Jonathas rentra dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'David se rendit à Nomba chez le prêtre Abimélech; Abimélech, étonné de sa venue, lui dit: Pourquoi es-tu seul, et n’y a-t-il personne avec toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David dit au prêtre: Le roi aujourd’hui m’a donné ce commandement: Que nul ne sache l’affaire pour laquelle je t’envoie, et dont je te charge. J’ai donc convoqué mes serviteurs au lieu dit la Foi de Dieu (PhellaniMaimoni).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Maintenant, as-tu sous la main cinq pains? Donnemoi ce que tu pourras trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Le prêtre répondit à David, et il lui dit: Je n’ai point sous la main de pains profanes, je n’ai que des pains consacrés; si tes gens se sont au moins abstenus de femmes, ils en peuvent manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'David reprit: Quant aux femmes, depuis trois jours, nous nous en sommes abstenus; lorsque je suis parti, tous mes hommes ont été purifiés; mais la route ellemême les souille; c’est pourquoi nous nous purifions aujourd’hui en lavant nos vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Alors, Abimélech le prêtre lui donna les pains de proposition; car il n’y avait là d’autres pains que ceux qu’on venait d’ôter de devant la face du Seigneur, pour les remplacer par des pains chauds, le jour même où David les prit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Or, il se trouvait là un serviteur de Saül, retenu devant le Seigneur; il se nommait Doeg le Syrien, et il faisait paître les mulets de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Et David dit à Abimélech: Vois si tu as ici sous la main quelque javeline ou quelque épée; car je n’ai pris ni mon glaive ni aucune arme, tant l’affaire du roi exigeait de précipitation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Et le prêtre dit: Voici l’épée de Goliath le Philistin, que tu as vaincu dans le vallon d’Ela; elle est enveloppée dans un manteau; si tu la veux, tu peux l’emporter; hormis cette arme, il n’en est aucune ici. A quoi David répondit: Donne-la-moi; elle n’a pas sa pareille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Le prêtre la lui donna, et David partit. Ce jour-là, il s’enfuit loin de Saül, et il alla chez Achis, roi de Geth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Et les serviteurs d’Achis dirent à leur maître: N’est-ce point là David, le roi de la terre? N’est-ce pas celui dont les danseuses, en chantant, disaient: Saül les a tués par milliers, David les a tués par myriades?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Et David pesa ces paroles en son cœur, et il eut grande crainte en présence du roi Achis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Aussitôt, devant lui, il se donna un nouvel aspect, et, ce jour-là, il usa de feinte; il tambourina sur les portes de la ville; il fit de ses mains des gestes insensés; il tomba contre les battants des portes, et l’écume ruisselait sur sa barbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Et Achis dit à ses serviteurs: Voyez, cet homme est épileptique. Pourquoi me l’avez-vous amené?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Ai-je besoin d’épileptiques? A quoi bon l’avoir amené pour qu’il tombe en épilepsie devant moi? Il n’entrera pas dans ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Ainsi, David s’éloigna et il fut sauvé; il se réfugia dans la caverne d’Odollam; ses frères, la famille de son père, l’apprirent, et ils l’y allèrent trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Et ils lui amenèrent tous les nécessiteux, tous les hommes perdus de dettes, tous ceux qui souffraient en leur âme; il fut leur chef, et il eut autour de lui quatre cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Et David partit pour Maspha en Moab, et il dit au roi des Moabites: Que mon père et ma mère demeurent chez toi jusqu’à ce que je sache ce que fera de moi le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Il toucha le roi de Moab, et ses parents demeurèrent auprès du roi tout le temps que David passa dans le fort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Enfin, Gad le prophète dit à David: Ne te tiens pas renfermé dans une forteresse; mets-toi en campagne, et tu entreras en la terre de Juda. David partit donc, et il s’établit dans la ville de Saric.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Et Saül fut informé que l’on avait reconnu David et les hommes qui l’accompagnaient. Saül demeurait alors sur la colline qui domine les champs de Rhama; il avait en main sa javeline, et tous ses serviteurs l’entouraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Et Saül dit à ses serviteurs qui l’entouraient: Écoutez-moi, fils de Benjamin; croyez-vous que véritablement le fils de Jessé vous donne à tous des terres ou des vignes, qu’il fasse de vous tous des centeniers ou des commandants de mille hommes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Vous qui êtes tous conjurés contre moi, sans que nul m’informe de l’alliance faite entre mon fils Jonathas et le fils de Jessé, sans que nul ait souci de moi et m’apprenne que mon fils a excité contre moi mon serviteur pour m’en faire un ennemi, comme il l’est maintenant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Et Doeg le Syrien, le surveillant des mulets de Saül, répondit: J’ai vu le fils de Jessé à Nomba chez Abimélech le prêtre, fils d’Achitob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Le prêtre a consulté pour lui le Seigneur; il lui a donné des vivres, et il lui a donné le glaive de Goliath le Philistin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Le roi envoya chercher Abimélech, fils d’Achitob, et tous les fils de son père, et les prêtres de Nomba; ils comparurent tous devant Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Et le roi dit: Écoute, fils d’Achitob. Sur quoi l’autre dit Me voici; parle, seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Et Saül reprit: Pourquoi es-tu d’intelligence contre moi avec le fils de Jessé? Ne lui as-tu pas donné des pains? N’as-tu pas pour lui consulté le Seigneur, afin qu’il se déclarât mon ennemi, comme il l’est maintenant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Il répondit au roi: Qui donc, parmi tes serviteurs, t’était fidèle autant que David? N’était-il point le gendre du roi, le ministre de tes commandements, honoré en ta maison?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Est-ce aujourd’hui la première fois que j’aurais consulté pour lui le Seigneur? Nullement. Que le roi ne porte point une telle accusation contre son serviteur et contre toute la famille de mon père; car ton serviteur ne savait de ce qui se passe nulle chose, ni grande ni petite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Et le roi Saül dit: Tu mourras, Abimélech, toi et toute la famille de ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Puis, le roi dit aux émissaires qui se tenaient auprès de lui: Emmenez les prêtres du Seigneur, et mettez-les à mort, parce que leur main est avec David; ils le savaient en fuite, et ils ne me l’ont point révélé. Mais les serviteurs du roi refusèrent de porter la main sur les prêtres du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Le roi dit donc à Doeg: Ceci te regarde, tombe sur les prêtres. Et Doeg le Syrien s’en chargea; et, ce jour-là, il tua tous les prêtres du Seigneur, au nombre de trois cent cinq hommes, tous portant l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Ensuite, il passa au fil de l’épée Nomba, la ville des prêtres hommes et femmes, nourrissons et nourrices; bœufs, ânes et brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Un seul fils d’Abimélech, fils d’Achitob, fut sauvé; il se nommait Abiathar, et il se réfugia auprès de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Et Abiathar apprit à David que Saül avait fait périr tous les prêtres du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Et David dit à Abiathar: J’avais prévu, ce jour-là, que Doeg le Syrien dirait tout à Saül. Je suis cause de la mort de ton père et de sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Demeure avec moi, n’aie point de crainte; car partout où je chercherai à mettre en sûreté ma vie, je chercherai à mettre en sûreté la tienne, puisque tu t’es placé sous ma garde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Et des gens vinrent dire à David: Voilà que les Philistins assiégent Ceïla; ils ravagent tout, et ils foulent aux pieds les aires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Et David consulta le Seigneur, disant: Me mettrai-je en campagne? Serai-je victorieux contre les Philistins? Le Seigneur répondit: Marche, tu vaincras les Philistins, et tu délivreras Ceïla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Mais ses hommes lui dirent: Vois donc; ici même, en Juda, nous ne sommes point sans crainte; que sera-ce si nous marchons sur Ceila, et si nous nous mesurons avec les forces des Philistins?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Et David consulta une seconde fois le Seigneur, et le Seigneur lui répondit');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Et David, avec ses hommes, marcha sur Ceïla; il combattit les Philistins, qui s’enfuirent de devant sa face; il enleva leur bétail; il les frappa d’une grande plaie, et les habitants de Ceïla furent sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Or, Abiathar, fils d’Abimélech, après s’être réfugié auprès de David, le suivit à Ceïla, tenant en sa main l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'On apprit à Saül que David était entré à Ceïla, et Saül dit Dieu l’a livré à mes mains; il s’est lui-même enfermé, puisqu’il est entré dans une ville où il y a des portes et des barrières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Alors, Saül enjoignit à tout le peuple de descendre sur Ceïla pour y assiéger David et les siens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Et David sut que Saül ne cachait pas ses mauvais desseins contre lui; et David dit à Abiathar le prêtre: Apporte l’éphod du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Et David dit: Seigneur Dieu d’Israël, votre serviteur a ouï dire que Saül désire marcher sur Ceïla, et détruire à cause de moi cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Sera-t-elle investie? Saül y viendra-t-il, comme l’a ouï dire votre serviteur? Seigneur Dieu d’Israël, faites-le savoir à votre serviteur. Et le Seigneur répondit: Elle sera investie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Et David se leva avec ses hommes au nombre de quatre cents; ils sortirent de Ceïla, et ils marchèrent tant, qu’ils purent aller. On apprit à Saül que David s’était échappé de Ceïla, et il ne songea plus à l’assiéger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Et David campa à Massera dans le désert; il campa dans le désert sur la montagne de Ziph, en la terre aride, et Saül le cherchait tous les jours, et le Seigneur ne le livrait pas à ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Et David s’aperçut que Saül était venu le chercher; à ce moment, David était sur la montagne aride, en la nouvelle Ziph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Jonathas, fils de Saül, l’y alla trouver, et il le fortifia en Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Et il lui dit: N’aie point crainte, la troupe de mon père ne te trouvera pas; tu règneras sur Israël, et je serai ton second; Saül, mon père, le sait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Ainsi, tous les deux firent alliance devant le Seigneur; puis, David resta en la Ville-Neuve, et Jonathas retourna chez lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Et des Ziphéens montèrent de la terre aride à la colline où était Saül, et ils lui dirent: Ne sais-tu pas que David est chez nous caché à Massera, dans les défilés et en la Ville-Neuve, sur la colline d’Echéla, qui est à droite de Jessème?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Maintenant donc que tout va au gré des désirs du roi, qu’il descende avec nous; il est enfermé entre les mains du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Et Saül leur dit: Soyez bénis au nom du Seigneur, parce que vous avez eu souci de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Partez, et faites de nouveaux apprêts; suivez ses pas dès qu’il ira quelque part, dans l’endroit que vous dites, de peur qu’il n’use de stratagème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Voyez, informez-vous, je vous suivrai; et, s’il est en cette contrée, je le chercherai avec les myriades des fils de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Les Ziphéens s’éloignèrent, et ils précédèrent Saül. David et ses gens étaient dans le désert de Maon, au couchant, à la droite de Jessème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Saül et les siens l’y allèrent chercher; mais David en fut averti, et il descendit dans les rochers du désert de Maon; et Saül, le sachant, poursuivit David dans le désert de Maon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Or, Saül et ses hommes cheminaient sur l’un des flancs de la montagne, et David et ses hommes sur l’autre flanc, celui-ci s’efforçant de se cacher de l’autre, qui, avec les siens, campait près de lui et de sa troupe, afin de les prendre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Quand un messager vint à Saül, disant: Hâte-toi, accours, les Philistins ont envahi notre territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Saül s’en retourna donc; il cessa de poursuivre David, et il marcha contre les Philistins. A cause de cela, ce lieu s’appelle la Roche de la Séparation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'David partit de là, et il campa dans les défilés d’Engaddi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Lorsque Saül revint, après avoir poursuivi les Philistins, on lui dit: David est dans le désert d’Engaddi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Il prit avec lui trois mille hommes, choisis parmi tout Israël, et il alla chercher David et les siens en face de Saddéem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Il arriva vers les troupeaux de brebis que l’on fait paître sur cette route, et il y avait là une caverne. Saül y entra pour décharger son ventre, tandis que David et les siens étaient assis au fond de la caverne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Et les hommes de David lui dirent: Voici le jour qu’a dit le Seigneur, où il va te livrer ton ennemi; faisen donc ce que bon te semble. Mais David se leva, et il enleva furtivement un pan du manteau double de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Et le cœur de David le fit souffrir, parce qu’il avait enlevé le pan du manteau de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Et David dit à ses hommes: Dieu me garde de rien faire à mon maître, à l’oint du Seigneur; je ne porterai point la main sur lui, parce qu’il est l’oint du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Par ces paroles, David persuada ses gens, et il ne leur permit point de se lever pour tuer Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Saül se leva et reprit sa route. Et David sortit après lui de la caverne, et lui cria ces mots: Seigneur roi; celuici se retourna pour regarder, quand David, se courbant jusqu’à terre, l’adora,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Et lui dit: Pourquoi donc as-tu écouté les propos de gens qui disaient: Vois, David en veut à ta vie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Tes yeux aujourd’hui ont vu comment, dans la caverne, le Seigneur t’avait livré à mes mains; je n’ai point voulu te faire périr; je t’ai épargné, et j’ai dit: Je ne porterai point la main sur mon maître, parce qu’il est l’oint du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Voici, dans ma main, le pan de ton manteau; c’est moi qui l’ai coupé, et je ne t’ai point tué. Reconnais donc aujourd’hui que de ma part il n’y a ni méchanceté, ni impiété, ni rébellion; je n’ai point péché envers toi, et cependant tu tends des piéges à ma vie pour me la prendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Que le Seigneur juge entre moi et toi, et le Seigneur me vengera sur toi-même; mais je ne lèverai jamais la main sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Comme dit l’ancien proverbe: C’est de l’homme sans loi que viendra le péché. Je ne lèverai donc jamais la main sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Maintenant, roi d’Israël, à qui en as-tu? Qui poursuis-tu? Tu poursuis un chien mort, tu poursuis un puceron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Que le Seigneur soit arbitre et juge entre moi et toi; que le Seigneur voie, qu’il prononce sur ma cause, qu’il me délivre de tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Or, quand David eut cessé de parler à Saül, ceci advint: Saül s’écria: Est-ce toi que j’entends, mon fils David? Et Saül éleva la voix, et il pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Et Saül dit à David: Tu es plus juste que moi; tu m’as rendu le bien pour le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Tu viens de m’apprendre quelle bonne action tu as faite aujourd’hui envers moi, quand le Seigneur m’avait livré à tes mains, et que tu ne m’as point tué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Or, si un homme trouve son ennemi dans la détresse, et qu’il le remette dans le bon chemin, comme tu as fait aujourd’hui pour moi, le Seigneur lui rend le bien pour le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Je reconnais donc maintenant que tu régneras, et que la royauté d’Israël s’affermira en tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Jure-moi à l’instant, au nom du Seigneur, qu’après moi tu ne détruiras pas ma race, et que tu n’effaceras pas mon nom de la maison de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'David le jura à Saül; celui-ci retourna en sa demeure, et David, avec les siens, remonta au défilé de Massera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Et Samuel mourut; et tout Israël se rassembla pour pleurer sur lui, et on l’inhuma dans la ville d’Armathaïm. Cependant David s’en retourna au désert de Maon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Il y avait alors en Maon un homme d’une trèsgrande taille, et ses troupeaux étaient sur le mont Carmel; il possédait trois mille brebis et mille chèvres; or, il était à tondre ses brebis sur le Carmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'L’homme s’appelait Nabal, et sa femme Abigail, femme excellente par l’intelligence, et très-belle de visage; mais l’homme était dur, méchant dans ses habitudes; c’était un homme grossier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'David apprit dans le désert que Nabal, du Carmel, tondait ses brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Et il envoya dix jeunes serviteurs, leur disant: Montez sur le Carmel, allez trouver Nabal et saluez-le en mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Voici ce que vous lui direz: Bonne santé à toi pour toujours, prospérité à ta maison et à tout ce que tu possèdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Or, voici que je viens d’apprendre que tes bergers faisaient la toute; ce sont ceux qui étaient avec nous dans le désert; nous ne leur avons jamais fait obstacle. Nous n’avons rien exigé d’eux, aussi longtemps qu’ils ont demeuré sur le Carmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Interroge tes serviteurs, et ils te le déclareront; pour nous, tes serviteurs aussi, puissions-nous trouver grâce à tes yeux, car nous sommes venus en un jour heureux. Donne donc à ton fils David quelque chose que tu aies sous la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Les serviteurs partent; ils répètent à Nabal, au nom de David, toutes les paroles que celui-ci leur a dites. Mais Nabal fit un bond en arrière,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Et répondant aux serviteurs de David, il dit: Qu’est-ce que David? Qu’est-ce que le fils de Jessé? Le monde est plein aujourd’hui de serviteurs qui s’échappent de la maison de leur maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Oui, je vais prendre mon pain, mon vin, les victimes que j’ai sacrifiées pour mes tondeurs, et je vais les donner à des hommes qui viennent je ne sais d’où!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Les serviteurs reprirent donc le chemin par lequel ils étaient venus, et ils arrivèrent, et ils rapportèrent cette réponse à David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Alors, David dit à ses gens: Que chacun de vous ceigne son épée. Et environ quatre cents hommes s’en allèrent avec David; il en resta deux cents auprès des bagages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Et l’un des serviteurs de Nabal parla à sa femme Abigail, disant: Voilà que David a envoyé du désert des messagers pour bénir notre maître, et il leur a tourné le dos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Ce sont des hommes très-bienveillants pour nous; ils ne nous ont point fait obstacle, ils n’ont rien exigé de nous, durant tout le temps que nous avons passé près d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Et, tandis que nous étions aux champs, ils étaient pour nous comme un retranchement, nuit et jour, durant tout le temps que nous avons été près d’eux paissant nos troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Et maintenant réfléchis, vois ce que tu as à faire; car le malheur fond sur notre maître et sa maison; luimême est un fils de pestilence, et il n’y a pas à lui parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Et Abigail se hâta; elle prit deux cents pains, deux vases pleins de vin, cinq brebis apprêtées, cinq éphi de fleur de farine, un gomor de raisins secs, deux cents cabas de figues, et elle les chargea sur des ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Puis, elle dit à ses serviteurs: Partez devant moi; voilà que je vous suis. Mais elle ne dit rien à son mari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Or, tandis qu’elle cheminait sur son ânesse et qu’elle descendait cachée par les plis de la montagne, David et ses gens montaient par le même chemin, de sorte qu’elle les rencontra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Et David disait: J’ai gardé équitablement dans le désert un homme injuste et tout ce qui lui appartenait, je n’ai jamais ordonné qu’on lui en prît la moindre chose, et il m’a rendu le mal pour le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Que le Seigneur punisse David et le punisse encore, si de tout ce qui est à Nabal je laisse jusqu’à demain matin quelque chose en vie, ne fût-ce qu’un chien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Et Abigail vit David; aussitôt, elle sauta de son ânesse, elle tomba devant David la face contre terre, et resta prosternée');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'A ses pieds, disant: Ne fais retomber sur moi que ma propre iniquité, seigneur; que ta servante te parle; écoute les paroles de ta servante;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Que mon seigneur ne fasse pas attention à cet homme de pestilence; car il est bien ce que son nom indique; il se nomme Nabal (fou), et la folie est avec lui. Mais moi, ta servante, je n’ai point vu les serviteurs de mon seigneur, que tu avais envoyés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Maintenant, mon seigneur, vive le Seigneur et vive ton âme! D’autant plus que ton Seigneur t’a empêché de verser le sang innocent et de te venger par ta main. Puissent ressembler à Nabal tes ennemis et ceux qui veulent nuire à mon seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Accepte donc cette bénédiction que ta servante a apportée à mon seigneur; tu la distribueras aux serviteurs qui accompagnent mon seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Détourne de ta servante la peine de l’iniquité, car le Seigneur, pour mon seigneur, édifiera certainement une maison sûre; le Seigneur combat pour mon seigneur en toutes ses batailles, et jamais le malheur ne se trouvera avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Et si un homme s’élève qui te poursuive, et en veuille à ta vie, l’âme de mon seigneur sera maintenue dans les liens de la vie par la volonté du Seigneur Dieu, et tu feras tournoyer la vie de tes adversaires, comme au milieu d’une fronde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Et lorsque le Seigneur aura fait à mon seigneur tout le bien qu’il lui a promis, il te donnera la mission de régner sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Et mon seigneur n’aura point commis le péché et l’abomination de verser, sans cause, le sang innocent ni de se venger par sa main; et le Seigneur sera bienveillant pour mon seigneur; et tu te souviendras de ta servante, tu seras bienveillant pour elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Et David dit à Abigaïl: Béni soit le Seigneur Dieu d’Israël, qui t’a envoyée aujourd’hui au-devant de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Bénie sois ta résolution; bénie sois-tu toi-même, qui m’as empêché aujourd’hui de verser le sang innocent et de me venger par ma main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Mais, vive le Seigneur Dieu vivant d’Israël, qui m’empêche aujourd’hui de te maltraiter! sans ton empres sement à venir à ma rencontre, j’avais dit: Je ne laisserai rien en vie chez Nabal jusqu’à demain matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'David prit de ses mains tout ce qu’elle lui avait apporté, et il lui dit: Retourne en paix à ta demeure. Vois, je t’ai accordé ce que tu m’as demandé, et je me suis réjoui de ta présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Abigaïl rentra donc chez Nabal, et il y avait en sa maison un festin comme un festin de roi; Nabal montrait la joie de son cœur; il était complètement ivre. Jusqu’aux lueurs du matin, sa femme ne lui dit aucune chose, grande ni petite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Le jour parut; comme Nabal avait cuvé son vin, elle lui raconta tout; aussitôt le cœur lui manqua et luimême fut comme une pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Il passa en cet état dix jours; puis, le Seigneur l’ayant frappé, il expira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'David l’apprit, et il dit: Béni soit le Seigneur, qui a jugé l’outrage que j’avais reçu de Nabal, et qui a sauvé son serviteur des mains des méchants, et qui a fait retomber l’iniquité de Nabal sur sa tête. Ensuite, David envoya chez Abigaïl, et lui fit parler pour la prendre en mariage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Les serviteurs de David arrivèrent au Carmel chez Abigaïl, et ils lui parlèrent, disant: David nous a envoyés vers toi afin de te prendre pour sa femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'A ces mots, elle se leva et elle se prosterna la face contre terre, et elle dit: Voici ta servante, emploie-la comme une esclave à laver les pieds de tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Abigail se releva, elle monta sur une ânesse, cinq jeunes filles l’accompagnèrent; elle suivit les serviteurs de David, et elle fut sa femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David avait déjà épousé Achinaam de Jezraël; toutes les deux étaient ses femmes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Et Saül avait donné sa fille Michol, la femme de David, à Phalti, fils d’Amis de Rhomma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Après cela, des Ziphéens vinrent de la terre aride chez Saül à Gabaa, disant: Voilà que David est caché parmi nous sur la colline d’Echéla, en face de Jessème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Alors, Saül partit et descendit au désert de Ziph pour chercher David, avec trois mille hommes choisis en tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Il campa sur la route en la colline d’Echéla, vis-à-vis Jessème, tandis que David demeurait dans le désert. Et David vit que Saül était venu pour le poursuivre dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Et David envoya des éclaireurs, et il sut que Saül était arrivé en forces de Ceïla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Et David se leva sans bruit, et il se rendit au lieu où dormait Saül; il y avait là son général Abner, fils de Ner; Saül dormait sur un chariot couvert, ayant toute sa troupe campée autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'David s’adressant à Abimélech le Hettéen, et à Abessa, fils de Sarvia, frère de Joab, leur dit: Qui viendra avec moi dans le camp jusqu’à Saül? Et Abessa répondit: Moi, je t’accompagnerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Et David avec Abessa se glissa parmi la troupe pendant la nuit. Saül dormait d’un profond sommeil sur un chariot couvert, sa javeline plantée en terre près de sa tête; Abner et ses gens dormaient autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Abessa dit à David: Le Seigneur aujourd’hui enferme ton ennemi dans tes mains; je vais à l’instant, d’un seul coup de javeline, le faire rouler à terre; je n’aurai pas besoin de le frapper deux fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Mais David dit à Abessa: Garde-toi de l’outrager; car qui peut sans crime porter la main sur l’oint du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Et David ajouta: Vive le Seigneur! il ne mourra que quand le Seigneur le frappera, soit que son jour vienne et qu’il expire, soit qu’il succombe en combattant et aille rejoindre ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Que le Seigneur me préserve de porter la main sur l’oint du Seigneur; maintenant, prends à son chevet sa javeline et la fiole d’eau, puis allons-nous-en.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Ainsi, David prit auprès du chevet la javeline et la fiole d’eau, et ils s’en allèrent. Nul ne les vit, nul ne sut qu’ils étaient là, nul ne s’éveilla; tous dormaient, car le Seigneur avait fait tomber sur eux une profonde torpeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'David traversa le camp, et il s’arrêta au loin, du côté opposé, sur la cime de la montagne; il y avait entre eux et lui un grand espace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'De là, David appela la troupe, et s’adressant à Abner, il dit: Ne répondras-tu point, Abner. Et Abner répondit, et il dit: Qui es-tu, toi qui appelles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Et David dit à Abner: N’es-tu pas un homme? Qui donc te vaut en Israël? Pourquoi ne gardes-tu pas le roi ton maître? Car quelqu’un du peuple est entré dans le camp pour le tuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Ce n’est pas une bonne action que tu as faite là. Vive le Seigneur! vous êtes tous fils du meurtre, vous qui êtes commis à la garde du roi votre maître, l’oint du Seigneur. Maintenant, je te prie, la javeline du roi et la fiole d’eau qui étaient aussi auprès de son chevet, où sont-elles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Cependant, Saül reconnut la voix de David, et il dit: Est-ce ta voix, mon fils David? Et David répondit: C’est ton serviteur, Seigneur roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Puis, il ajouta: Pourquoi le maître poursuit-il ainsi son serviteur? En quoi ai-je péché? Quelle iniquité a-t-on trouvée en moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Maintenant donc que le roi mon maître écoute la parole de son serviteur. Si c’est Dieu qui t’excite contre moi, que ton sacrifice soit d’agréable odeur. Mais si ce sont des fils des hommes, maudits soient-ils devant le Seigneur, parce qu’ils m’ont chassé, de peur que je ne m’affermisse en l’héritage du Seigneur; et ils m’ont dit: Va-t’en, et sers d’autres dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Que mon sang ne soit point répandu sur la terre à la face du Seigneur, parce que le roi d’Israël est venu chercher ma vie, comme l’oiseau de nuit, quand il chasse dans les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Et Saül dit: J’ai péché, reviens, mon fils David, je ne te ferai point de mal, en récompense de ce qu’à tes yeux ma vie est précieuse. J’ai agi aujourd’hui comme un insensé, et j’ai ignoré beaucoup de choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Et David reprit la parole; et il dit: Voilà la javeline du roi; que l’un des serviteurs approche, et qu’il la prenne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Et le Seigneur accordera à chacun, selon sa foi et son équité. Cette nuit, quand le Seigneur t’a livré à mes mains, je n’ai pas voulu porter la main sur l’oint du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Et de même que ta vie a été précieuse à mes yeux, ma vie sera précieuse devant le Seigneur, et il m’abritera et il me délivrera de toutes mes afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Et Saül dit à David: Béni sois-tu, mon fils, tu prospéreras, et tu seras très puissant. Alors, David s’en alla à sa demeure, et Saül retourna à la ville où il résidait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Et David dit en son cœur: Je tomberai un jour entre les mains de Saül, et je n’ai rien de bon à attendre, si je ne me réfugie dans la terre des Philistins; Saül alors cessera de me chercher sur toutes les montagnes d’Israël; et j’échapperai à ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'David partit donc avec les six cents hommes qui l’accompagnaient, et il alla chez Achis, fils d’Ammach, roi de Geth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Et David s’établit chez Achis, lui et ses gens, chacun avec sa famille; David avait avec lui ses deux femmes: Achinaam la Jezraélite, et Abigaïl, femme de Nabal du Carmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Et l’on alla rapporter à Saül que David s’était réfugié à Geth, et il cessa de le chercher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Et David dit à Achis: Si ton serviteur a trouvé grâce à tes yeux, que l’on me donne, dans une des villes de ce pays, un lieu où je demeurerai; car pourquoi ton serviteur réside-t-il avec toi dans ta ville royale?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Ce jour-là même, Achis lui donna Sécelac; à cause de cela, Sécelac a fait partie du royaume de Juda jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Et le nombre des jours que David passa sur les terres des Philistins fit quatre mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Or, David et sa troupe sortaient, et ils attaquaient tout Gesiri et l’Amalécite. Et la contrée était habitée, depuis les postes fortifiés de Gelampsur, jusqu’à la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'David frappait cette contrée, et il n’y laissait vivants ni homme ni femme; il enlevait les bœufs, les ânes, les chameaux, les vêtements; puis, il s’en retournait et revenait chez Achis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Alors, Achis disait à David: Qui as-tu attaqué aujourd’hui? David répondait: Ceux qui sont au midi de la Judée, au midi de Jesmega, au midi de Cénézi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Je n’ai laissé vivants ni homme ni femme pour les amener à Geth; car je ne veux pas, disais-je, qu’ils parlent de nous dans Geth, et qu’ils disent: Voilà ce qu’a fait David. Telles furent ses habitudes tout le temps qu’il demeura sur les terres des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Et David inspira la plus grande confiance à Achis, qui se disait: On l’a indignement traité au milieu de son peuple en Israël, et il sera toujours mon serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Or, en ces jours-là; il arriva que les Philistins rassemblèrent dans leur camp, pour aller en guerre chez Israël. Et Achis dit à David: Sache que tu iras en guerre avec nous, toi et tes gens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Et David dit à Achis: Que ton serviteur soit informé de ce qu’il fera. A quoi Achis répondit: Tu commanderas, tout le temps de la guerre, mes gardes du corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Or, Samuel mourut; tout Israël pleura sur lui, et on l’ensevelit dans Armathaïm, sa ville. Et Saül détruisit dans la terre promise les sorciers et tous les devins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Cependant, les Philistins se rassemblent; ils partent, et ils campent à Sonam. Saül aussi leva tous les hommes d’Israël, et il établit son camp à Gelboé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Saül vit le camp des Philistins; il eut crainte, et son cœur défaillit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Il consulta le Seigneur, et le Seigneur ne lui répondit ni par des songes, ni par des signes sensibles, ni par des prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Alors, Saül dit à ses serviteurs: Informez-vous d’une sorcière; je l’irai trouver, et je consulterai par elle. Et ses serviteurs lui dirent: Il y a une sorcière à Endor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Saül se déguisa donc, s’enveloppant de vêtements étrangers; il partit avec deux hommes, arriva chez la femme pendant la nuit, et lui dit: Prédis-moi l’avenir par tes sortilèges, et amène-moi celui que je te dirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'La femme lui répondit: Tu sais ce qu’a fait Saül; comment il a exterminé, en la terre, les sorciers et les devins; pourquoi donc tendre un piège à ma vie, afin de la détruire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Mais Saül lui prêta serment, et dit: Vive le Seigneur! tu ne recevras, en cette circonstance, aucun mauvais traitement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Sur quoi la femme dit: Qui t’amènerai-je? Saül répondit: Amène-moi Samuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Aussitôt, la femme vit Samuel; elle jeta un grand cri, et elle dit au roi: Pourquoi m’as-tu trompée? Tu es Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Et le roi lui dit: N’aie point crainte; dis qui tu as vu. Et la femme répondit: J’ai vu des dieux sortant de terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Qu’as-tu reconnu? dit-il. Et elle répondit: Un homme, se tenant droit et s’élevant hors de terre, revêtu d’un manteau double. Saül comprit que c’était Samuel; il se prosterna la face contre terre, et il le salua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Et Samuel dit: À quel sujet m’as-tu troublé pour me faire apparaître? Saül répondit: Je suis cruellement accablé; les Philistins me font la guerre, et Dieu s’est retiré de moi; il ne m’a plus exaucé, soit par les prophètes, soit en songe; maintenant donc, je t’ai appelé pour que tu m’apprennes ce que j’ai à faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel répondit: Pourquoi m’interroges-tu, quand le Seigneur s’est retiré de toi, et qu’il est avec ton prochain?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Le Seigneur t’a traité comme il t’avait dit par ma bouche; il brisera ta royauté dans ta main, et il la donnera à ton prochain, à David,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Parce que tu as été indocile aux ordres du Seigneur, et que tu n’as pas accompli contre Amalec les désirs de sa colère; voilà pourquoi le Seigneur t’a fait ces choses aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Et le Seigneur livrera Israël et toi-même aux Philistins. Demain, toi et tes fils, vous succomberez, et le Seigneur livrera le camp d’Israël aux ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Et soudain Saül tomba tout de son long à terre, épouvanté des paroles de Samuel; il n’y eut plus en lui aucune force; or, il n’avait rien mangé ni pendant tout le jour, ni cette nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Alors, la femme s’approcha de Saül; elle vit son angoisse, et elle lui dit: Ta servante a été docile à tes ordres; j’ai remis ma vie en tes mains; j’ai écouté tes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'C’est à toi maintenant d’écouter ta servante: je vais t’apporter des aliments; mange, et tu reprendras des forces; ensuite, tu pourras te remettre en marche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Il refusa de manger; mais ses serviteurs et la femme le pressèrent tant, qu’il leur céda; il se leva donc de terre et s’assit sur un siège.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Or, la femme avait dans sa maison une génisse grasse; elle se hâta de la sacrifier, elle prit de la farine, elle la pétrit et elle fit cuire des azymes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Puis, elle les servit à Saül et à ses serviteurs; ils mangèrent, et ils partirent avant la fin de la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Cependant, les Philistins concentrèrent toutes leurs forces vers Apha, et Israël campa à Endor en Jezraël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Et les chefs des Philistins allaient en avant, par troupes de cent et de mille hommes; et David, suivi de ses gens, marchaient au dernier rang avec Achis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Or, les chefs des Philistins dirent: Qui sont ceux-là qui nous suivent? Achis leur répondit: N’est-ce pas David le serviteur de Saül, roi d’Israël; voilà bien des jours qu’il est avec nous; la seconde année commence, et, depuis qu’il s’est attaché à moi, jusqu’à ce moment, je n’ai trouvé en lui rien à redire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Les chefs des Philistins s’offensèrent de sa réponse, et ils lui dirent: Renvoie cet homme, qu’il s’en aille en la demeure où tu l’as établi; ne le laisse pas ici, et qu’il ne vienne point avec nous au combat; craignons qu’il ne nous trahisse. Comment se réconcilierait-il avec son maître, sinon avec les têtes de nos hommes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'N’est-ce pas ce David de qui l’on chantait, en dansant: Saül les a tués par milliers, David les a tués par myriades?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Achis fit donc appeler David, et il lui dit: Vive le Seigneur! tu es à mes yeux droit et bon; tu sors du camp et tu y rentres avec moi, et je n’ai découvert en toi aucune méchanceté, depuis le jour où tu es venu me trouver, jusqu’à ce moment. Mais, aux yeux des chefs, tu n’es point bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Ainsi, retire-toi; pars en paix; c’est le moyen de ne rien faire qui semble mal aux chefs des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Et David dit à Achis: Que t’ai-je fait, et qu’as-tu à reprocher à ton serviteur, depuis le jour où je suis arrivé devant toi, jusqu’à ce moment, pour que l’on me défende de combattre les ennemis du roi mon maître?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Achis répondit à David: A mes yeux, tu es bon; mais les chefs des Philistins ont dit: Il ne viendra pas au combat avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Lève-toi donc demain de grand matin, emmène tes serviteurs; retournez au lieu où je vous ai établis, et ne laisse point entrer en ton cœur de mauvaise pensée, parce que, selon moi, tu es bon. Levez-vous pour vous mettre en route avant qu’il fasse jours et partez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Et David avec ses gens se leva de grand matin; ils partirent pour garder la terre des Philistins, et ceux-ci allèrent à Jezraël pour livrer bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Et comme David et ses gens rentraient à Sécelac, le troisième jour, il était arrivé qu’Amalec, ayant fait une incursion contre le midi de Sécelac, avait pris et incendié cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Sans y tuer toutefois ni petit, ni grand, ni homme, ni femme, ni rien qui eût vie. Ils emmenaient donc les habitants captifs, et s’en retournaient par le chemin qui conduit chez eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Quand David et ses hommes rentrèrent dans la ville, voilà qu’elle était brûlée, et que leurs femmes, leurs fils et leurs filles, s’en allaient en captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'A cette vue, David et ses gens élevèrent la voix, et ils pleurèrent jusqu’à ce qu’ils n’eussent plus de force pour pleurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Or, les deux femmes de David étaient captives, Achinaam la Jezraélite, et Abigaïl, femme de Nabal du Carmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Et David fut accablé de douleur; car le peuple parlait de le lapider, tant chacun avait de chagrin dans l’âme, à cause de ses fils et de ses filles. Mais David se fortifia en Dieu son Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Et il dit à Abiathar le prêtre, fils d’Abimélech: Apporte l’éphod.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Et David consulta le Seigneur, disant: Si je poursuis ces gens, les atteindrai-je? Et le Seigneur lui répondit: Poursuis-les, tu les atteindras, et tu les extermineras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Ainsi, David partit en personne avec les six cents hommes de sa troupe; ils allèrent jusqu’au torrent de Bosor; là, une partie d’entre eux s’arrêta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Et il continua de s’avancer avec quatre cents hommes, et il en laissa deux cents campés sur la rive du Bosor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Et ses hommes trouvèrent dans les champs un Égyptien qu’ils saisirent et lui amenèrent; on lui donna du pain, il mangea, et on lui fit boire de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'On lui donna en outre un cabas de figues; il en mangea, et ses esprits se ranimèrent; car, depuis trois jours et trois nuits, il n’avait ni bu ni mangé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Et David lui dit: À qui appartiens-tu? D’où es-tu? Le jeune Égyptien répondit: Je suis serviteur d’un Amalécite; mon maître m’a abandonné, parce que, depuis trois jours, j’étais malade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Nous avons fait une incursion au midi de Chéléthi, de la Judée, et de Chélab; puis, nous avons incendié Sécelac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David lui dit: Pourrais-tu me conduire où sont ces gens? A quoi il répondit: Jure-moi par ton Dieu que tu ne me feras point mourir, et que tu ne me livreras pas à mon maître, aussitôt je te conduirai contre ces gens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Et le jeune homme l’y conduisit. Or, voilà que les Amalécites étaient dispersés sur la face de toute leur terre, mangeant, buvant, et faisant fête de toutes les grandes dépouilles qu’ils avaient rapportées, tant du territoire des Philistins que de celui de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'David fondit sur eux, et il les tailla en pièces, depuis le lever de l’aurore jusqu’au crépuscule, et encore le lendemain; pas un seul homme n’échappa, hormis quatre cents jeunes garçons, qui montaient des chamelles, et qui s’enfuirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'David recouvra tout ce qu’avaient pris les Amalécites, et il ramena ses deux femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Et nulle chose, grande ou petite, ne fut perdue; et les dépouilles, les fils et les filles, et tout ce qui leur avait été enlevé, David le recouvra en entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'De plus, il s’empara de toutes les brebis, de tous les bœufs, et il les fit marcher devant les dépouilles qu’ils venaient de reprendre; et, au sujet de ce butin repris, on disait: Voici les dépouilles de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Il arriva ainsi vers les deux cents hommes qu’il avait dispensés de le suivre, et qu’il avait postés sur le torrent de Bosor; ils allèrent à la rencontre de David et de sa troupe; lui-même s’avança près d’eux, et ils le saluèrent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Et tous les hommes de pestilence, les méchants, parmi ceux qui venaient de combattre avec David, se récrièrent, et dirent: Parce qu’ils n’ont point avec nous poursuivi l’ennemi, nous ne leur donnerons rien des dépouilles que nous ramenons; qu’ils se contentent de reprendre chacun leur femme et leurs enfants, et qu’ils s’en aillent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Et David dit: Vous ne ferez point cela, après que le Seigneur nous a pris sous sa garde, et nous a livré l’Amalécite; car le Seigneur nous a livré ces gens qui nous avaient envahis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Et qui donc écouterait de tels discours? Ceux qui sont restés auprès des bagages ne sont pas moins que vous; ils auront une part égale à celle des combattants; ils partageront également.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'À partir de ce jour-là, on a toujours fait ainsi; c’est devenu chez Israël une loi, une ordonnance, qui s’observe encore aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'David revint à Sécelac, et il envoya une part des dépouilles aux anciens de Juda et à ses voisins les plus proches, disant: Voici des dépouilles des ennemis du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Pour ceux de Bethsur, pour ceux du midi de Rhama, pour ceux de Géthor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Pour ceux d’Aroer, pour ceux d’Ammadi, pour ceux de Saphi, pour ceux d’Esthié,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Pour ceux de Geth, pour ceux de Cimath, pour ceux de Saphec, pour ceux de Thémath, pour ceux du Carmel, pour ceux des villes de Jérémiel, pour ceux des villes de Cénézi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Pour ceux de Jérimuth, pour ceux de Bersabée, pour ceux de Nomba,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'Pour ceux d’Hébron et pour ceux de tous les lieux où David avec ses hommes a passé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Et les Philistins livrèrent bataille à Israël, et les hommes d’Israël prirent la fuite devant eux; ils furent taillés en pièces dans la montagne de Gelboé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Les Philistins entourèrent Saül et ses trois fils; ils tuèrent Jonathan, Aminadab et Melchisa, fils de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Et le poids de la guerre tomba sur Saül; des archers l’atteignirent, et il fut blessé au flanc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Alors, Saül dit au serviteur qui portait ses armes: Tire ton épée, et perce-moi, de peur que ces incirconcis ne m’approchent, ne me percent et ne m’outragent. Le serviteur, qui portait ses armes, ne le voulut pas, car il avait grande crainte; mais Saül prit l’épée et se jeta sur la pointe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Le serviteur, qui portait ses armes, vit que Saül était mort; lui-même se jeta sur son épée, et il mourut avec son maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Ainsi Saül, ses trois fils et le serviteur qui portait ses armes, périrent ensemble ce jour-là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Les hommes d’Israël qui étaient de l’autre côté de cette vallée, ceux des rives du Jourdain virent que l’armée était en fuite, et que Saül et ses fils étaient morts; alors ils abandonnèrent leurs villes et se cachèrent; et les Philistins survinrent, et ils prirent possession de leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Et, le lendemain, les vainqueurs dépouillèrent les morts; ils trouvèrent Saül et ses trois fils gisant dans les montagnes de Gelboé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Ils défigurèrent le roi; ils lui ôtèrent ses armes, et ils les envoyèrent aux villes d’alentour en la terre des Philistins, annonçant ces nouvelles à leurs idoles et au peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Ils déposèrent les armes dans le temple d’Astarté, et ils clouèrent le corps au mur de Bethsam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Or, ceux de Jabès-Galaad apprirent comment les Philistins avaient traité Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Et tous les hommes vaillants se levèrent; ils marchèrent toute la nuit, enlevèrent des murs de Bethsam les corps de Saül et de Jonathan, et les transportèrent à Jabès, où ils les brûlèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Enfin, ils recueillirent leurs ossements; ils les inhumèrent en un champ de Jabès, et ils jeûnèrent sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Saül était mort quand David revint de son expédition contre Amalec, il resta deux jours à Sécelac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Et le troisième jour, voilà qu’un homme arriva du camp d’Israël, les vêtements déchirés, la tête couverte de cendres; en entrant devant David, il tomba la face contre terre et il l’adora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'D’où viens-tu? lui dit David; il répondit: Du camp d’Israël; j’ai pu m’échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Et David lui dit: Qu’y a-t-il? Parle; et il répondit: Le peuple s’est enfui du champ de bataille; un grand nombre a péri, Saül et Jonathas sont morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Et David dit au jeune homme qui lui apportait ces nouvelles: Comment sais-tu que Saül et son fils Jonathas ont péri?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Le jeune homme reprit: J’étais par hasard en la montagne de Gelboé, et voilà que Saül était appuyé sur sa javeline, et les chars et les chefs des cavaliers couraient sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Or, ayant jeté derrière lui ses regards, il m’aperçut, il m’appela, et je lui dis: Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Qui es-tu? demanda-t-il, je répondis: Je suis un Amalécite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Et il me dit: Monte sur moi et tue-moi, car d’ horribles ténèbres m’arrêtent, et la vie en moi est tout entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Et je montai sur lui et je le tuai; car je voyais bien qu’il ne survivrait pas à sa chute. Ensuite, j’ai pris, sur sa tête, la couronne; autour de son bras, le bracelet, et je les ai apportés ici à mon maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Et David prit à deux mains ses vêtements et il les déchira, et tous les hommes de sa suite déchirèrent leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Puis, ils se lamentèrent, ils jeûnèrent jusqu’au soir, ils pleurèrent sur Saül, sur Jonathas, sur le peuple de Juda et sur la maison d’Israël, parce qu’ils avaient été frappés par l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Et David dit au jeune homme qui lui avait apporté ces nouvelles D’où es-tu? il répondit: Je suis fils d’un colon amalécite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Comment, lui dit David, n’as-tu pas eu crainte de lever la main pour tuer l’oint du Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Et David ayant appelé l’un de ses serviteurs, lui dit: Approche, et tombe sur lui. Le serviteur frappa donc l’Amalécite, et il le tua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Et David dit: Que ton sang retombe sur ta tête; car c’est ta bouche qui a porté témoignage contre toi, quand tu as dit: J’ai tué l’oint du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Alors, David fit cette lamentation sur Saül et sur Jonathas, son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Et il commanda qu’on l’apprît aux fils de Juda, et elle est écrite au livre du Juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Considère, Israël, ceux de tes enfants qui sont morts en tes montagnes; comment sont tombés les puissants!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Ne l’annoncez pas dans Geth, ne le racontez pas dans les rues d’Ascalon, de peur que les filles des Philistins ne se réjouissent, de peur que les filles des incirconcis ne triomphent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Montagnes de Gelboé, que la rosée, que les pluies du ciel ne descendent plus sur vous, que vos champs ne donnent plus de prémices, car c’est là que le bouclier des vaillants a perdu sa gloire. Le bouclier de Saül n’était pas oint avec de l’huile;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Le sang des blessés, la graisse des puissants, ne manquaient jamais à l’arc de Jonathas, ni à l’épée de Saül, quand ils revenaient du combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saül et Jonathas, bien-aimés et gracieux, vous n’êtes point séparés; nobles dans la vie, nobles dans la mort, ils ne sont point séparés; ils étaient plus agiles que l’aigle, plus forts que le lion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Filles d’Israël, pleurez sur Saül qui vous revêtait de robes d’écarlate, et ornait d’or votre parure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Comment sont tombés les puissants au milieu de la bataille? Et Jonathas et ceux qui ont péri sur vos montagnes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Je pleure sur toi, Jonathas mon frère; qu’à mes yeux tu étais beau! ton amitié pour moi me ravissait plus que l’amour des femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Comment sont tombés les puissants? comment les armes de guerre ont-elles été brisées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Après cela, David consulta le Seigneur, disant: Irai-je en l’une des villes de Juda? Et le Seigneur lui répondit: Va. Et David demanda: Où irai-je? À Hébron, reprit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Et David partit pour Hébron, avec ses deux femmes Achinoam la Jezraélite et Abigail, femme de Nabal du Carmel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Et avec ses hommes, chacun emmenant sa famille; ainsi, ils habitèrent les villes d’Hébron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Alors, des hommes de la Judée vinrent, et ils sacrèrent David pour qu’il régnât sur la tribu de Juda; ces hommes lui apprirent que ceux de Jabès-Galaad avaient inhumé Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Et David envoya des messagers aux chefs de JabèsGalaad, et il leur dit: Bénis soyez-vous par le Seigneur, parce que vous avez été miséricordieux envers votre maître, envers Saül l’oint du Seigneur, et que vous l’avez inhumé, lui et son fils Jonathas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Que le Seigneur vous traite selon sa miséricorde et sa vérité; pour moi, j’en userai bien avec vous, parce que vous avez bien agi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Et maintenant que vos mains soient fortes; soyez vaillants vous-mêmes; car votre maître Saül n’est plus, et la maison de Juda m’a sacré, afin que je règne sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Mais, Abner, fils de Ner, général de Saül, prit Isboseth, fils de Saül, et il l’emmena du camp de Manaam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Et il le fit reconnaître roi par la contrée de Galaad, par Thasiri, par Jezraël, par Ephraïm, par Benjamin, par tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Isboseth, fils de Saül, avait quarante ans lorsqu’il devint roi d’Israël; il régna deux ans, hormis sur la maison de Juda, qui obéissait à David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Et David régna à Hébron sur la maison de Juda, sept ans et demi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Cependant, Abner, fils de Ner, et les serviteurs d’Isboseth, fils de Saül, s’en allèrent de Manaam en Gabaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'De son côté, Joab, fils de Sarvia, avec la troupe de David, sortit d’Hébron, et il arriva en même temps qu’eux vers la fontaine de Gabaon; ils campèrent les uns en deçà, les autres au delà de la fontaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Et Abner dit à Joab: Que ces jeunes gens se lèvent et qu’ils viennent jouer devant nous; à quoi Joab répondit: Qu’ils se lèvent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Et douze des serviteurs d’Isboseth, fils de Saül, tous de la tribu de Benjamin, se portèrent à la rencontre de douze serviteurs de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Et chacun saisit d’une main la tête de celui qui lui faisait face, puis, de l’autre main, il lui enfonça dans le flanc son épée, et ils tombèrent tous en même temps. Et l’on appela ce lieu qui est en Gabaon, le Champ des Traîtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Ce jour-là, il y eut une terrible bataille; Abner et les hommes d’Israël échouèrent devant les serviteurs de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Il se trouvait là trois fils de Sarvia, Joab, Abessa et Asaël; or, Asaël avait les pieds légers comme un daim libre dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Et Asaël se lança à la poursuite d’Abner; il s’attacha à ses pas, sans s’écarter à droite ni à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abner regardant derrière lui, s’écria: N’es-tu pas Asaël? l’autre reprit: Je le suis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abner lui dit: Détourne-toi à droite ou à gauche, attaque l’un des jeunes serviteurs, et prends pour toi ses armes. Mais Asaël refusa de s’écarter ni à droite ni à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abner continua de lui parler, disant: Éloigne-toi donc de moi, de peur que d’un coup je ne t’étende à terre; comment alors oserais-je lever les yeux devant Joab?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Où en veux-tu venir? Retourne vers Joab, ton frère. Mais il ne voulut pas s’éloigner, et Abner le frappa du bas de sa javeline au ventre, la pointe ressortit par les reins. Asaël tomba, et il mourut en s’affaissant sur lui-même; tous ceux qui arrivèrent au lieu où il était mort s’arrêtèrent autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Et Joab et Abessa s’élancèrent à la poursuite d’Abner; le soleil se couchait alors; et ils allèrent jusqu’à la colline d’Amma, qui est en face d’Haï, où monte le chemin du désert de Gabaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Mais les fils de Benjamin, s’étant ralliés auprès de la troupe d’Abner, ne formaient plus qu’un seul corps; ils se rangèrent sur la crête d’une colline.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Et Abner appela Joab, et il lui dit: Est-ce que l’épée dévorera sans relâche? Ne sais-tu pas qu’elle peut devenir amère à la fin? Qu’attends-tu donc pour ordonner aux tiens de ne plus poursuivre nos frères?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Et Joab répondit: Vive le Seigneur! si tu n’avais parlé, aucun des nôtres qui, depuis le matin, poursuivent leurs frères, ne se fût arrêté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Et Joab sonna de la trompette, et toute l’armée s’arrêta; elle ne poursuivit plus Israël, et le combat finit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Partis le soir même, Abner et ses hommes marchèrent toute la nuit; ils traversèrent le Jourdain, le côttoyèrent et rentrèrent dans leur camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joab revint sur ses pas, laissant partir Abner; il rassembla tout le peuple, et il vit que des serviteurs de David, il manquait dix-neuf hommes outre Asaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Et les serviteurs de David avaient tué trois cent soixante des fils de Benjamin, qui accompagnaient Abner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Et ils emportèrent le corps d’Asaël pour l’ensevelir à Bethléem, dans le sépulcre de son père; Joab et ses hommes marchèrent aussi toute la nuit; le jour paraissait quand ils arrivèrent à Hébron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Et la guerre se prolongea entre la maison de David et celle de Saül. Avec le temps la première se fortifia, l’autre s’affaiblit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Et des fils naquirent à David en Hébron; son premier-né fut Amnon, fils d’Achinoam la Jezraélite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Le second fut Daluia, fils d’Abigaïl du Carmel; le troisième, Absalon, fils de Maacha, fille de Tholmi, roi de Gessir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Le quatrième, Ornia, fils d’Agith; le cinquième, Saphatia, fils d’Abital,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Et le sixième, Jethéraam, fils d’Egal, femme de David; tels furent les fils qui naquirent à David en Hébron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Pendant la guerre entre la maison de Saül et la maison de David, Abner commandait les forces de la maison de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Or, Respha, fille de Jol, avait été concubine de Saül. Et Isboseth, fils de Saül, dit à Abner: Pourquoi astu commerce avec la concubine de mon père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Abner ressentit un grand courroux, à cause de cette parole d’Isboseth, et il lui dit: Est-ce que je suis une tête de chien? J’ai eu compassion de la maison de Saül ton père, et de ses frères, et de ses proches; je n’ai point passé au camp de David, et tu m’accuses, et tu me trouves en faute au sujet d’une femme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Que le Seigneur punisse Abner, et qu’il le punisse encore, si, ce jour même, je n’agis pas selon la promesse que le Seigneur a faite à David,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'D’enlever la royauté à la maison de Saül, et d’élever le trône de David sur Israël et sur Juda, depuis Dan jusqu’à Bersabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Isboseth n’eut pas la force de répondre un mot à Abner, tant il le craignait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Et Abner envoya des messagers à David en Thélam, où il se trouvait alors, et il lui dit: Fais alliance avec moi, et voilà que ma main est à toi, pour te ramener toute la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Et David dit: Je ferai volontiers alliance avec toi, sauf une condition que je te demande; la voici: Tu ne verras point ma face, si tu ne m’amènes Michol, fille de Saül, lorsque tu reviendras pour voir ma face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Et David envoya des messagers à Isboseth, fils de Saül, disant Rends-moi ma femme Michol, que j’ai épousée quand j’eus pris cent prépuces de Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Isboseth l’envoya reprendre à son mari Phaltiel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Et son mari la suivit, en pleurant, jusqu’à Baracim, où Abner lui dit: Va-t’en, retourne chez toi. Alors, il s’en retourna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abner dit ensuite aux anciens d’Israël: Précédemment, vous désiriez que David régnât sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Faites-le donc roi, car le Seigneur a dit de David: Par la main de mon serviteur David, je délivrerai Israël des mains des Philistins et de tous ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abner parla de même aux fils de Benjamin, et il vint à Hébron dire à David tout ce qui était agréable à Israël et à la maison de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Abner arriva chez David, à Hébron, accompagné de vingt hommes, et David leur fit un festin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Et Abner dit à David: Je vais me mettre en campagne; je rassemblerai tout Israël en faveur du roi mon maître, et je ferai alliance avec le peuple, et tu seras roi de tous ceux sur qui en ton âme tu désires régner. Après cela, David congédia Abner, qui se retira en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'À ce moment, les serviteurs de David avec Joab revenaient d’une incursion, et ils rapportaient de nombreuses dépouilles; Abner, quittant Hébron, parce que David l’avait congédié, s’en allait en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Quand Joab et toute sa troupe survinrent, on alla dire à Joab Abner, fils de Ner, est venu chez David, et celui-ci l’a congédié, et il est parti en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Et Joab, entrant auprès du roi, lui dit: Pourquoi as-tu fait cela? Voilà qu’Abner t’est venu trouver, et tu l’as congédié, et il est parti en paix?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Ne connais-tu pas la méchanceté d’Abner, fils de Ner; ne sais-tu pas qu’il est arrivé pour te tromper, pour épier tes allées et venues, et s’informer de toutes tes actions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Et Joab sortit, et il envoya après Abner des messagers qui le ramenèrent du puits de Seïram; mais David n’en sut rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Abner revint donc à Hébron. Or, Joab le conduisit traîtreusement à l’écart près de la porte, sous prétexte de lui parler, et il le frappa au ventre; et Abner mourut en expiation du sang d’Asaël, frère de Joab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'David ne tarda pas à l’apprendre, et il s’écria: Je suis innocent, et mon royaume est innocent à toujours, devant le Seigneur, du sang d’Abner, fils de Ner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Qu’il retombe sur la tête de Joab et sur toute la maison de son père; qu’il y ait toujours en sa famille des malsains, des lépreux, des infirmes s’appuyant sur un bâton, des hommes périssant par l’épée, et d’autres manquant de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Or, Joab et son frère Abessa avaient constamment épié Abner, parce qu’en Gabaon, pendant la bataille, il avait tué leur frère Asaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Et David dit à Joab et à toute la troupe qui était avec lui: Déchirez vos vêtements, couvrez-vous de cilices, et pleurez sur Abner. Et le roi David marcha derrière le brancard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'On ensevelit Abner en Hébron, et David éleva la voix, et il pleura sur le sépulcre, et tout le peuple pleura sur Abner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Et le roi fit une lamentation sur Abner, et il dit: La mort d’Abner sera-t-elle comme la mort d’un Nabal?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'On ne t’a point amené pieds et mains liés comme un Nabal; tu es tombé devant des fils d’iniquité; et tout le peuple assemblé pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Et tout le peuple s’approcha de David pour l’exhorter à manger du pain; or, il faisait encore jour, et David jura, disant: Que le Seigneur me punisse et me punisse encore, si, avant le coucher du soleil, je goûte ni pain ni quoi que ce soit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Et le peuple vit la vérité, et il eut pour agréable ce que le roi avait fait devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Tout le peuple et tout Israël, ce jour-là, reconnurent que ce n’était point par la volonté du roi qu’Abner, fils de Ner, avait été mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Et le roi dit à ses serviteurs: Ne savez-vous pas qu’un grand prince est tombé aujourd’hui en Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Et que, pour moi, je ne suis encore que comme un parent, un vassal de roi? Les fils de Sarvia sont plus durs que moi. Que le Seigneur traite, selon leur méchanceté, ceux qui font le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Quand Isboseth, fils de Saül, apprit qu’Abner, fils de Ner, était mort à Hébron, ses bras en furent énervés, et tous les hommes d’Israël défaillirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Or, il y avait deux chefs des troupes d’Isboseth, fils de Saül l’un se nommait Baana, et l’autre Rhéchab; ils étaient fils de Rhemmon, de Bèroth de la tribu de Benjamin; car Bèroth était comptée parmi les villes de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Ceux de Bèroth ont depuis émigré à Géthaïm, où, de nos jours encore, ils sont colons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Il restait de Jonathas, fils de Saül, un fils de cinq ans, infirme des pieds; car, lorsqu’on vint de Jezraël annoncer que Saül et Jonathas étaient morts, la nourrice de cet enfant le prit dans ses bras et s’enfuit. En se hâtant de l’éloigner, elle le laissa tomber, et il resta boiteux; il se nommait Miphiboseth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Et les fils de Rhemmon le Bérothéen, Rhéchab et Baana partirent; et, par la grande chaleur du jour, ils entrèrent chez Isboseth, comme il dormait sur un lit de repos, à l’heure de midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Le gardien de la porte avait vanné du froment, sa tête s’était affaissée, et il s’était endormi; Rhéchab et Baana poussèrent donc plus avant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Ils pénètrent dans la maison où Isboseth dormait sur son lit de repos, en sa chambre à coucher; ils le frappent, le tuent, lui tranchent la tête, qu’ils emportent, et marchent toute la nuit du côté de l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Et ils portèrent à David, en Hébron, la tête d’Isboseth, et ils dirent au roi: Voici la tête d’Isboseth, fils de Saül, ton ennemi, qui te cherchait pour te faire périr; le Seigneur a achevé aujourd’hui de venger, de Saül et de sa race, le seigneur roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Et David répondit à Rhéchab et à Baana son frère, fils de Rhemmon le Bérothéen, et il leur dit: Vive le Seigneur! le sauveur de mon âme en toutes ses afflictions,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Celui qui est venu m’annoncer la mort de Saül, et qui croyait m’apporter une bonne nouvelle, je l’ai saisi et l’ai fait mourir en Sécelac, où il s’attendait à recevoir une récompense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Et maintenant, de méchants hommes ont tué un homme juste, dans sa maison, sur sa couche. Certes, je vous demanderai compte du sang que votre main À versé, et je vous effacerai de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'David donna donc ses ordres à ses serviteurs, et ils les tuèrent; puis, ils leurs coupèrent les mains et les pieds, et les pendirent vers la fontaine d’Hébron; et ils inhumèrent la tête d’Isboseth dans le sépulcre d’Abner, fils de Ner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Toutes les tribus d’Israël allèrent ensuite trouver David à Hébron, et elles lui dirent: Vois, nous sommes tes os et ta chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Précédemment, quand Saül régnait encore sur nous, c’est toi qui conduisais et qui ramenais Israël. Et le Seigneur t’avait dit: Tu seras le pasteur du peuple d’Israël, tu seras le chef de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Tous les anciens d’Israël allèrent aussi en Hébron auprès du roi; et David fit alliance avec eux devant le Seigneur en Hébron, et ils sacrèrent David roi de tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'David avait trente ans quand il commença de régner, et il régna quarante ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Il régna sept ans et demi à Hébron sur Juda, et trente-trois ans à Jérusalem sur Israël et Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'David avec son armée marcha contre Jérusalem et les Jébuséens qui l’habitaient. Or, on dit à David: Tu n’entreras pas là, car les aveugles et les boiteux s’y sont opposés, disant David n’entrera pas ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'David enleva, de prime abord, Sion la citadelle; la même que la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Et, ce jour-là, David dit: Que tous ceux qui frapperont les Jébuséens les poignardent, ainsi que les aveugles et les boiteux, et les ennemis de David. De là vient le proverbe: Les aveugles et les boiteux n’entreront pas dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'David s’établit dans la forteresse, et elle fut appelée la ville de David. Il bâtit la ville même au pied de la citadelle tout alentour, et il bâtit sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'David allait ainsi grandissant, et le Seigneur tout-puissant était avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Et Hiram, roi de Tyr, envoya à David des messagers, des bois de cèdre, des charpentiers, des tailleurs de pierre, et ils bâtirent la maison de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Et David reconnut que le Seigneur l’avait préparé pour être roi d’Israël, et que sa royauté était exaltée pour le bien-être de tout le peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Il prit encore des femmes et des concubines de Jérusalem, lorsqu’il y fut venu d’Hébron. Et il eut encore des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Voici les noms de ceux qui naquirent à Jérusalem: Samua, Sobab, Nathan, Salomon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Ebéhar, Elisué, Naphé, Japhia,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Elidaé, Eliphalath, Samaé, Jessibath, Nathan, Galamaan, Jébahar, Theïsus, Eliphalat, Naged, Naphec, Janathas, Leasamys, Baalimath et Eliphaath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Cependant, les Philistins apprirent que David avait été sacré roi d’Israël, et ils se levèrent tous pour l’aller prendre. David en fut informé, et il se renferma dans la citadelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Les Philistins s’avancèrent, et ils se réunirent dans le val des Géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Et David consulta le Seigneur, disant: Dois-je marcher contre les Philistins? me les livrerez-vous? Et le Seigneur répondit à David: Marche, car je te les livrerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Et David vint au lieu appelé Brisement d’en haut, et il battit les Philistins en ce lieu, et il s’écria: Le Seigneur a brisé devant moi nos ennemis, comme brisent les eaux des torrents. À cause de cela, ce lieu a reçu le nom de Brisement d’en haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Et les Philistins abandonnèrent là leurs dieux, et David avec son armée s’en empara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Puis, les Philistins se remirent en campagne, et ils se réunirent encore dans le val des Géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Alors, David consulta le Seigneur, et le Seigneur lui dit: Ne les attaque pas, fais un détour, et tu te mettras en défense près du Champ des Pleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Et ceci arrivera: Lorsque tu entendras, dans le bois du Champ des Pleurs, des voix comme de gens qui y seraient renfermés, tu engageras la bataille; car le Seigneur marchera devant toi pour que tu tailles en pièces les Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David fit ce que lui avait prescrit le Seigneur, et il tailla en pièces les Philistins depuis Gabaon jusqu’au territoire de Gazera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Et David rassembla encore toute la jeunesse d’Israël, environ soixante-dix mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Puis, il se mit en marche avec tout son peuple et une partie des princes de Juda, pour une expédition dont le but était de ramener l’arche de Dieu, sur laquelle était invoqué le nom du Seigneur Dieu des armées, qui résidait entre les chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Ils placèrent donc l’arche du Seigneur sur un chariot neuf, et ils l’enlevèrent de la maison que possédait Aminadab sur la colline. Oza et ses frères, fils d’Aminadab, conduisaient le chariot avec l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Et ses frères précédaient l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'David et les fils d’Israël, avec une harmonie pleine de force, jouaient devant le Seigneur d’une multitude d’instruments harpes, lyres, tambours, cymbales et flûtes, au milieu des cantiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Et ils arrivèrent à l’aire de Nachor. Là, Oza étendit la main sur l’arche de Dieu, pour la raffermir, et il la saisit, parce que l’un des bœufs l’avait ébranlée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Et le Seigneur, en son âme, s’irrita contre Oza, et Dieu le frappa sur le lieu, et il mourut à côté de l’arche du Seigneur, devant Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'David fut abattu, parce que Dieu avait châtié Oza; et ce lieu fut appelé le Châtiment d’Oza, nom qu’il porte encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Et David, ce jour-là, eut crainte du Seigneur, et il dit: Comment l’arche du Seigneur entrera-t-elle chez moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Et David ne voulut pas que l’on déposât chez lui, dans la ville de David, l’arche de l’alliance du Seigneur; il la fit donc placer en la maison d’Abdara le Géthéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'L’arche du Seigneur resta trois mois en la maison d’Abdara le Géthéen; et le Seigneur bénit toute la maison d’Abdara et tout ce qui lui appartenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Or, des gens vinrent l’apprendre au roi David, disant Le Seigneur a béni la maison d’Abdara et tout ce qui lui appartient, à cause de l’arche de Dieu. Alors, David partit, et il amena, plein de joie, l’arche du Seigneur de la maison d’Abdara à la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Il y avait avec lui ceux qui devaient porter l’arche, sept chœurs; et, pour les sacrifices, un veau et des béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Et David touchait, devant le Seigneur, d’un instrument accordé, et il était revêtu d’une robe de forme inaccoutumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'David, avec toute la maison d’Israël, conduisit l’arche du Seigneur au son de la trompette et à grands cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Lorsque l’arche entra dans la ville de David, Michol, fille de Saül, se penchant à sa fenêtre, vit le roi David danser et toucher de la harpe devant le Seigneur, et en son cœur elle le méprisa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'On transporta l’arche du Seigneur, et on la déposa à sa place, au milieu du tabernacle que David avait dressé');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'David acheva les sacrifices, et il bénit le peuple au nom du Seigneur Dieu des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Ensuite, il distribua à tout le peuple, et à toute l’armée d’Israël, depuis Dan jusqu’à Bersabée, aux femmes aussi bien qu’aux hommes, un gâteau de froment par tête, une pâte cuite à la poêle, et une tranche de bœuf cuite sur la braise. Après cela, le peuple s’en alla chacun en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Et David s’en retourna pour bénir sa maison; or, Michol, fille de Saül, sortit à sa rencontre, et elle le salua, et elle lui dit: Quelle gloire a donc trouvée aujourd’hui le roi d’Israël à se dévêtir, aux yeux des servantes et de ses serviteurs, comme on se dévêt en dansant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Et David dit à Michol: Je danserai devant le Seigneur; béni soit le Seigneur qui m’a élu, et qui m’a préféré à ton père et à toute ta famille pour me faire roi de tout son peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Je jouerai de la harpe, je danserai devant le Seigneur, je me dévêtirai encore de la même manière, je serai un insensé à tes yeux et aux yeux de tes servantes, qui aujourd’hui, dis-tu, ne m’ont point honoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Et la fille de Saül, Michol, n’eut point d’enfants jusqu’au jour de sa mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Après que le roi se fut établi en sa demeure, et que le Seigneur lui eut donné l’héritage de tous les ennemis qui l’entouraient, ceci arriva:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Le roi dit à Nathan le prophète: Voilà que j’habite une maison de cèdre, tandis que l’arche du Seigneur repose au milieu d’un tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Nathan répondit au roi: Tout ce qui est en ton cœur, va, et fais-le, parce que le Seigneur est avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Mais cette nuit même, la parole du Seigneur vint à Nathan, et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Va, et dis à mon serviteur David: Voici ce que dit le Seigneur: Tu ne me bâtiras point un temple pour que je l’habite,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Parce que je n’ai point résidé dans un temple depuis que j’ai tiré de l’Égypte les fils d’Israël jusqu’à ce jour, et qu’en marchant je me tenais abrité sous un tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'En quelque lieu que j’aie passé, avec tout Israël, ai-je jamais dit, à celle des tribus que j’avais chargée de prendre soin de tout le peuple: Pourquoi ne m’avez-vous point bâti une maison de cèdre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Dis encore à mon serviteur David: Voici ce que dit le Seigneur tout-puissant: Je t’ai tiré des bergeries pour que tu sois roi de mon peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Je t’ai accompagné partout où tu as marché, j’ai exterminé devant toi tous tes ennemis, et je t’ai rendu célèbre autant que les plus renommés des grands de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Et j’adopterai un lieu pour mon peuple Israël; je l’y fixerai, et il s’y abritera; chacun aura sa demeure, et il ne sentira plus d’inquiétudes, et le fils de l’iniquité ne l’affligera plus comme il a fait dès le commencement,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Depuis les temps où j’ai donné des juges à mon peuple. Et je t’affranchirai de tous tes ennemis, et le Seigneur te fera savoir qu’il te formera une maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Et quand tes jours seront remplis, quand tu te seras endormi avec tes pères, j’élèverai après toi ta race, j’élèverai celui qui sera issu de ton sang, et je préparerai son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Celui-là bâtira un temple en mon nom; je dresserai son trône pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Je serai pour lui un père, et il sera pour moi un fils; et, si une iniquité provient de lui, je le châtierai avec la verge qui châtie les hommes; je lui porterai les coups que l’on porte aux fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Mais je ne lui retirerai point ma miséricorde, comme je l’ai retirée à ceux qui se sont éloignés de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Et sa maison sera une maison sûre, et, devant moi, sa royauté subsistera à jamais; et son trône sera toujours debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Ainsi, Nathan répéta à David toutes les paroles que lui-même avait ouïes en sa vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Alors, le roi David entra devant le Seigneur, et il dit: Qui suis-je, Seigneur, mon Seigneur, et qui est ma maison, pour que vous m’aimiez à ce point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'J’étais bien petit devant vous, Seigneur, mon Seigneur, et vous m’avez parlé de la maison de votre serviteur pour un avenir lointain; Seigneur, mon Seigneur, les hommes ont-ils une telle loi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Et que pourrait David vous dire encore? Vous connaissez maintenant votre serviteur, ô Seigneur! mon Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Vous avez agi pour l’amour de votre serviteur, et selon votre cœur vous avez opéré ces grandes choses afin que votre serviteur les connaisse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Et qu’il vous glorifie, mon Seigneur; car nul ne vous ressemble, nul que vous n’est Dieu parmi tous ceux dont nos oreilles ont entendu parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Et quelle autre nation sur la terre est comme le peuple d’Israël, que vous avez guidé, racheté et fait votre peuple, pour qu’il divulgue votre nom, pour qu’il agisse avec éclat et grandeur, de telle sorte que vous chassiez les nations et leurs tabernacles devant le peuple que vous avez tiré de l’Égypte afin qu’il soit à vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Car, vous avez préparé pour vous-même le peuple d’Israël; il sera votre peuple à jamais; et vous, Seigneur, vous êtes son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Et maintenant, mon Seigneur, confirmez la parole que vous avez dite concernant votre serviteur et sa maison, Seigneur tout - puissant, Dieu d’Israël; maintenant donc, comme vous avez dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Que votre nom soit glorifié à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Seigneur tout-puissant, Dieu d’Israël, vous avez révélé vos desseins à votre serviteur, disant: Je te bâtirai une maison. A cause de cela votre serviteur a trouvé dans son cœur cette prière qu’il vous adresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Et maintenant, Seigneur, mon Seigneur, vous êtes Dieu, et vos paroles seront vraies, c’est vous qui avez dit ces excellentes paroles concernant votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Commencez donc; et bénissez la maison de votre serviteur pour qu’elle subsiste toujours devant vous, car Seigneur, mon Seigneur, vous l’avez promis; ainsi la maison de votre serviteur sera bénie, et bénie pour exister à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Il advint, après cela, que David battit les Philistins, et qu’il les mit en fuite. Et David leur imposa un tribut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Ensuite, David vainquit Moab; il fit coucher les captifs à terre, et il les fit mesurer par séries; il y en eu deux séries que l’on mit à mort et deux qui eurent la vie sauve. Moab resta asservi à David, et il lui paya un tribut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David vainquit aussi Adraazar, fils de Rhaab, roi de Suba, qui s’était mis en campagne pour se rendre maître des rives de l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'David lui prit mille chars, sept mille cavaliers et vingt mille piétons. Il énerva les attelages de tous les chars, sauf une centaine qu’il garda pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Alors, les Syriens de Damas s’avancèrent pour porter secours à Adraazar, roi de Suba, et David tua aux Syriens vingt-deux mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Puis, il mit une garnison dans la Syrie de Damas; le Syrien lui fut asservi, et il lui paya un tribut. Ainsi, le Seigneur protégea David partout où il porta ses');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Et David prit les bracelets d’or que portaient les serviteurs d’Adraazar, roi de Suba, et il les consacra dans Jérusalem. Sésac, roi d’Égypte, s’en empara lorsqu’il entra à Jérusalem, au temps de Roboam, fils de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'David recueillit, à Métébac et dans les principales villes d’Adraazar, une prodigieuse quantité d’airain, dont Salomon se servit pour fabriquer la mer d’airain, les colonnes, les piscines et tous les vases du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Thu, roi d’Hémath, ayant appris que David avait taillé en pièces toute l’armée d’Adraazar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Envoya vers David son fils Jedduram pour lui demander la paix et le féliciter de sa victoire sur Adraazar, car il était son ennemi. Et Jedduram apporta au roi David des vases d’argent, des vases d’or et des vases d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Et le roi David les consacra au Seigneur; comme il consacra l’argent et l’or de toutes les villes conquises,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Tant de l’Idumée, que de Moab, des fils d’Ammon, des Philistins, d’Amalec et d’Adraazar, fils de Rhaab, roi de Suba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'David s’était donc fait un grand renom, et, à son retour, il écrasa Gébélem à l’Idumée qui avait levé dixhuit mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Et il mit des garnisons dans l’Idumée entière, et tous les Iduméens furent asservis au roi. Ainsi, le Seigneur en toutes ses guerres avait protégé David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'David régna sur tout Israël, et il rendit bonne justice à tout son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Et Joab, fils de Sarvia, commandait l’armée; Josaphat, fils d’Achilud, recueillait les actes publics.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Sadoc, fils d’Achitob, et Achimélech, fils d’Abiathar, étaient prêtres, et Sasa, scribe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Banaïas, fils de Joad, était conseiller; Chéléthi, Phéléthi, et les fils de David étaient maîtres du palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Et David dit: Reste-t-il encore un rejeton de la maison de Saül, afin que je sois envers lui miséricordieux pour l’amour de Jonathas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Or, il y avait dans la maison de Saül un serviteur qui se nommait Siba; on le fit venir auprès de David, et le roi lui dit: Tu es Siba? Et il répondit: Je suis ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Et le roi lui dit: Reste-t-il encore un homme de la maison de Saül pour que j’exerce envers lui la miséricorde de Dieu? Et Siba répondit au roi: Il existe un fils de Jonathas, infirme des pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Le roi dit: Où est-il? Et Siba répondit au roi: Voici; il est en la maison de Machir, fils d’Amiel de Lodabar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Et le roi David envoya des gens, et il le retira de la maison de Machir, fils d’Amiel en Lodabar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Et Miphiboseth, fils de Jonathas, fils de Saül, comparut devant le roi David; il tomba la face contre terre et il le salua, et David lui dit: Miphiboseth; et il répondit: Voici ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David lui dit: N’aie point crainte, car je serai miséricordieux envers toi pour l’amour de Jonathas, ton père; je te rendrai tous les champs de Saül, père de ton père, et tu mangeras tous les jours à ma table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Et Miphiboseth se prosterna, et il dit: Qui suis-je donc, moi, ton serviteur, pour que tu aies jeté les regards sur un chien mort tel que je suis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Et le roi appela Siba, le serviteur de Saül, et il lui dit: Tout ce qui appartenait à Saül et dépendait de sa maison, je l’ai donné au fils de ton maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Va donc, avec tes fils et tes serviteurs, labourer ses terres, et tu apporteras au fils de ton maître le pain qu’il mangera, et Miphiboseth, fils de ton maître, mangera toujours du pain à ma table. Or, Siba avait quinze fils et vingt serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Et Siba répondit au roi: Tout ce que le roi mon maître a prescrit à son serviteur, son serviteur l’exécutera. Et Miphiboseth mangea à la table de David comme l’un des fils du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Or, Miphiboseth avait un fils tout petit qui se nommait Micha; et tous ceux qui habitaient la maison de Siba étaient ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Et Miphiboseth résida à Jérusalem, et il mangea toujours à la table du roi; or, il était boiteux des deux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Après cela, il advint que le roi des fils d’Ammon mourut, et qu’Annon, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Et David dit: Je serai compatissant envers Annon, fils de Naas, de même que son père a été compatissant pour moi; en conséquence, il envoya, pour le consoler de la mort de son père, des serviteurs qui allèrent en la contrée des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Mais, les princes des fils d’Ammon dirent à Annon, leur maître Est-ce pour glorifier devant toi ton père que David envoie ces consolateurs? N’est-ce point plutôt pour s’informer de ta ville, et pour la reconnaître par eux-mêmes, que David a chargé ses serviteurs de venir auprès de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Annon saisit donc les serviteurs de David; il leur rasa la barbe, il coupa le bas de leurs manteaux, à partir du milieu des reins, et il les chassa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'On vint dire à David ce qui leur était arrivé, et il envoya des gens à leur rencontre; car ils étaient cruellement déshonorés, et il leur dit: Demeurez à Jéricho jusqu’à ce que votre barbe ait repoussé; puis, alors vous reviendrez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Les fils d’Ammon, voyant que le peuple de David se tenait pour outragé, firent partir des messagers, et ils enrôlèrent à prix d’or les Syriens de Bethraam, ceux de Suba, ceux de Rhoob, qui leur fournirent vingt mille piétons; le roi d’Amalec en fournit mille, et Istob douze mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'David l’apprit et il mit en mouvement Joab avec toute l’armée, et les hommes vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Et les fils d’Ammon sortirent, et ils se rangèrent en bataille près de la porte de Suba en Syrie; cependant, Rhoob, Istob et Amalec étaient détachés dans la campagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Joab reconnut qu’il aurait à livrer bataille devant son front et sur ses derrières; il rangea donc en face des Syriens les plus vaillants des jeunes fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Et il confia à son frère Abessa le reste de l’armée, qui se déploya contre les fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Et il dit à son frère: Si les Syriens l’emportent sur moi, tu viendras à mon aide, et si les fils d’Ammon te font plier, j’irai te secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Sois fort, agissons en hommes, pour l’amour de notre peuple et des villes de notre Dieu; que le Seigneur ensuite fasse à sa volonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Et Joab avec sa troupe tomba sur les Syriens, et ceux-ci s’enfuirent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Quand les fils d’Ammon virent que les Syriens fuyaient, ils s’enfuirent eux-mêmes devant Abessa, et ils s’enfermèrent dans leur ville; Joab les Ꭹ laissa pour revenir à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Mais la Syrie, voyant qu’elle avait échoué devant Israël, se leva tout entière, pour reprendre l’attaque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Adraazar dépêcha des messagers, et il appela les Syriens des rives du fleuve Chalamac, et ils se rendirent à Elam. Et Sobac, général de l’armée d’Adraazar, fut mis à leur tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'On en instruisit David, qui réunit tout Israël, passa le Jourdain, et atteignit Elam. Et les Syriens se déployèrent devant David, et ils lui livrèrent bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Les Syriens s’enfuirent devant Israël; David leur détruisit sept cents chars et quarante mille cavaliers; et il frappa mortellement Sobac, général de leur armée, qui mourut sur le lieu même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Et tous les rois, serviteurs d’Adraazar, voyant qu’il avait échoué devant Israël, se donnèrent à David; ils lui furent asservis, et la Syrie eut crainte de secourir encore les fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Le cours de l’année ramena le temps où les rois se mettent en campagne, et David fit partir Joab, ses serviteurs et tout Israël; ils ravagèrent la contrée des fils d’Ammon, et ils assiégèrent Rhabbath; cependant, David était resté à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Et ceci advint: sur le soir, David se leva de sa couche, et il se promena sur la plate-forme de la maison royale; et, de sa plate-forme, il vit une femme qui se baignait; or, la femme était extrêmement belle de visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Et David envoya, et il s’informa de la femme, et on lui dit: N’est-ce point Bersabée, fille d’Eliab, femnie d’Urie l’Hettéen?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Aussitôt, David, dépêchant des messagers, la fit prendre, s’approcha d’elle, et dormit avec elle; puis, lorsqu’elle se fut purifiée de son impureté, elle retourna en sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'La femme conçut; elle le fit savoir à David, et elle dit: Je suis enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Et David fit dire à Joab: Envoie près de moi Urie l’Hettéen, et Joab envoya Urie près de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Urie arriva, et il entra chez le roi, et David lui demanda comment allaient Joab, et l’armée, et la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Et David dit à Urie: Va à ta maison, et lave-toi les pieds. Urie sortit donc de la demeure royale, et, derrière lui, on porta un mets de la table du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Mais Urie dormit devant la porte du roi, parmi les serviteurs de son maître, et il n’alla pas jusqu’à sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'On l’alla dire à David; il sut qu’Urie n’était pas allé jusqu’à sa maison, et David dit à Urie: Ne viens-tu pas de faire un voyage? Pourquoi n’es-tu pas entré en ta demeure?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Et Urie répondit à David: L’arche, Israël et Juda demeurent sous des tentes; mon maître Joab et les serviteurs de mon maître sont campés en plein air, et moi j’entrerais en ma maison pour manger et boire, et dormir avec ma femme! Comment ferais-je pareille chose? Vive ton àme! je ne la ferai jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Et David dit à Urie: Demeure encore avec nous aujourd’hui; demain, je te congédierai. Urie passa donc à Jérusalem cette journée là et le lendemain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Ensuite, David l’invita; il mangea, il but, il s’enivra, et il sortit sur le soir pour dormir où il s’était déjà couché, parmi les serviteurs de son maître; mais il n’entra point en sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Le jour parut, et David écrivit une lettre à Joab, et il la remit à Urie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Voici ce qu’en sa lettre il disait: Conduis Urie au fort du péril, et laisse-le là seul; qu’il soit frappé et qu’il meure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Et, pendant que Joab plaçait des gardes autour de la ville, il donna à Urie un poste où il savait qu’il se trouvait des hommes vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Ces hommes, en effet, firent une sortie; ils combattirent Joab; plusieurs hommes de l’armée, serviteurs de David, tombèrent, et Urie l’Hettéen fut au nombre des morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Et Joab envoya rapporter à David tout ce qui venait de se passer dans ce combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Et il donna ses instructions au messager, disant: Lorsque tu auras fini de rapporter à David tout ce qui s’est passé dans le combat,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Peut-être le roi se mettra-t-il en colère, et te dira-t-il Pourquoi donc combattre si près de la ville? Ne saviez-vous pas que du haut des remparts on vous atteindrait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Qui donc a renversé Abimélech, fils de Jérobaal, fils de Ner? N’est-ce pas une femme qui lui a lancé, de la muraille, un éclat de meule dont il est mort à Thamasi? Pourquoi donc vous êtes-vous approchés du rempart? Alors, tu répondras: Urie l’Hettéen, ton serviteur, est du nombre des morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Le messager de Joab se rendit à Jérusalem, et, selon l’ordre de Joab, il fit au roi le rapport de tout ce qui était arrivé à la guerre; David s’emporta contre Joab, et il dit au messager: Pourquoi vous être approchés de la ville pour combattre? Ne saviez-vous pas que vous seriez atteints du haut des remparts? Qui donc a frappé Abimélech, fils de Jérobaal? N’est-ce pas une femme qui a lancé sur lui, de la muraille, un éclat de meule dont il est mort à Thamasi? Pourquoi donc vous êtes-vous approchés du rempart?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Le messager répondit à David: Parce que ceux de la ville ont prévalu sur nous; ils ont fait une sortie dans la campagne; puis, nous les avons repoussés jusqu’aux portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Alors, des archers ont tiré du haut des remparts sur tes serviteurs; plusieurs des serviteurs du roi ont péri; ton serviteur Urie l’Hettéen est du nombre des morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Et David dit au messager: Voici ce que tu diras à Joab Ne t’afflige pas de cet événement; le glaive dévore tantôt celui-ci, tantôt celui-là; fortifie tes postes autour de la ville, enlève-la, et t’en rends maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Et la femme d’Urie apprit que son mari était mort, et elle pleura sur son mari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Le temps du deuil écoulé, David envoya près d’elle, la fit venir en sa demeure, et la prit pour femme; elle lui enfanta un fils. Mais l’action que David avait commise était mauvaise aux yeux du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Et le Seigneur envoya à David Nathan le prophète; celui-ci entra chez le roi, et il lui dit: Il y avait en une ville deux hommes, l’un riche, l’autre pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Le riche possédait une multitude de brebis et de bœufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Le pauvre n’avait rien qu’une petite brebis; il l’avait achetée, il en avait pris soin, il l’avait nourrie, et elle avait crû auprès de lui en même temps que ses fils; elle mangeait de son pain, buvait dans sa coupe, dormait sur son sein; elle était pour lui comme une fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Or, un voyageur vint chez le riche, et celui-ci n’eut garde de prendre de ses moutons ni de ses bœufs pour faire un festin au voyageur étranger; mais il prit la brebis du pauvre, et il l’apprêta pour l’homme qui était venu chez lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'David entra dans une grande colère contre le riche, et il dit à Nathan: Vive le Seigneur! c’est un fils de la mort qui a fait cela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Il paiera la brebis sept fois pour ne l’avoir point épargnée, et pour avoir commis une telle action.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Et Nathan dit à David: Tu es l’homme qui a fait cela. Voici ce que dit le Seigneur Dieu d’Israël: C’est moi qui t’ai sacré roi de mon peuple, et qui t’ai tiré des mains de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Je t’ai donné la maison de ton maître, et tu as sur ton sein les femmes de ton maître. Je t’ai donné la maison d’Israël et de Juda, et, si c’est peu, j’y ajouterai encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Pourquoi donc as-tu méprisé la parole du Seigneur, au point de faire le mal à ses yeux? Tu as livré au glaive▸ Urie l’Hettéen; tu as pris pour femme sa femme, après l’avoir tué lui-même par l’épée des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Eh bien! maintenant, le glaive ne cessera plus de menacer ta maison, parce que tu m’as méprisé, et que tu as pris pour femme la femme d’Urie l’Hettéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Voici ce que dit le Seigneur: Je susciterai contre toi des maux qui sortiront de ta maison, et je prendrai tes femmes sous tes yeux, et je les donnerai à ton prochain, et il dormira avec elles à la face de ce soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Tu as fait cela en cachette, et moi je ferai cette chose devant tout Israël, et à la face de ce soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Et David dit à Nathan: J’ai péché contre le Seigneur. Et Nathan dit à David: Le Seigneur a ôté ton péché; tu ne mourras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Mais, comme par cette action tu as donné aux ennemis du Seigneur l’occasion de l’irriter, le fils que tu as engendré mourra de mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Nathan retourna en sa maison, et le Seigneur frappa le fils que la femme d’Urie l’Hettéen avait enfanté à David, et l’enfant languit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'David pria le Seigneur pour son enfant, et David jeûna, et il se tint renfermé, et il passa les nuits couché sur la dure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Et les anciens de sa maison accoururent pour le relever; mais il ne se releva pas, et il ne mangea point avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Le septième jour, enfin, l’enfant mourut, et les serviteurs de David craignirent de lui annoncer que l’enfant était mort. Car, dirent-ils, nous lui parlions de l’enfant, tandis qu’il vivait, et il ne nous écoutait pas; comment lui dirons-nous que l’enfant est mort? Il fera contre lui-même quelque chose de funeste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'David s’aperçut que ses serviteurs chuchotaient entre eux; il comprit que l’enfant était mort, et il dit à ses serviteurs: L’enfant est-il mort? Il est mort, dirent-ils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Aussitôt, David se releva, se baigna, se parfuma, changea de vêtements, et entra dans la maison du Seigneur; après l’avoir adoré, il revint en sa maison, et demanda qu’on lui servît à manger; on le servit, et il mangea.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Et ses serviteurs lui dirent: Que fais-tu donc, à cause de l’enfant? Tandis qu’il vivait encore, tu jeûnais, tu pleurais, tu ne pouvais dormir, et, à peine l’enfant mort, tu t’es levé, tu as mangé et tu as bu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'David répondit: Tant qu’il vivait, je pleurais et je jeûnais; car, qui sait, disais-je, si le Seigneur n’aura pas compassion de moi, et s’il ne laissera pas l’enfant vivre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Maintenant, il est mort: à quoi bon jeûner? Est-ce que je pourrais le rappeler? C’est moi qui irai à lui; mais il ne reviendra point à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Ensuite, David consola Bersabée, sa femme; il s’approcha d’elle, il dormit avec elle; elle conçut, et elle enfanta un fils qu’elle nomma Salomon; or, le Seigneur aima cet enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Le Seigneur envoya Nathan le prophète, et celui-ci, de la part du Seigneur, surnomma l’enfant Jeddedi (aimable à Dieu).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Cependant, Joab avait investi Rhabbath chez les fils d’Ammon, et il prit la ville royale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Il envoya des messagers à David, et il dit: J’ai assiégé Rhabbath; j’ai pris la ville des eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Maintenant, rassemble tout le reste du peuple, viens camper devant Rhabbath, et enlève-la, pour que je ne l’enlève pas moi-même; car toute la gloire m’en reviendrait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'David leva donc tout le peuple; il marcha sur Rhabbath, il donna l’assaut, et il la prit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Alors, il enleva sur la tête de leur roi Molchom sa couronne, qui pesait un talent d’or, et qui était ornée de pierres précieuses; elle allait à la tête de David. Enfin, il rapporta de cette ville un immense butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Il emmena tout le peuple qui l’habitait, et il l’extermina en plaçant les uns sous des scies, sous des herses de fer, sous des cognées de bûcheron; en jetant les autres dans les fours à brique. Il traita de même toutes les villes des fils d’Ammon. Ensuite, David et toute son armée retournèrent à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Voici ce qui advint ensuite: Absalon, fils de David, avait une sœur extrêmement belle; elle se nommait Thamar, et Amnon, fils de David, l’aimait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Amnon souffrait au point de dépérir, à cause de Thamar sa sœur; car elle était vierge, et il lui semblait téméraire de rien tenter auprès d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Amnon avait un compagnon nommé Jonadab, fils de Samaa, frère de David; or, Jonadab était un homme très-rusé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Il dit donc à Amnon: Qu’as-tu, ô fils du roi! pour que tu t’affaiblisses ainsi de jour en jour? Ne me le confieras-tu point? Amnon lui répondit: J’aime Thamar, la sœur de mon frère Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jonadab lui dit: Mets-toi au lit, et fais-toi malade; ton père viendra te voir, et tu lui diras: Que Thamar, ma sœur, vienne; qu’elle me coupe mes bouchées, qu’elle prépare sous mes yeux des aliments, afin que je la voie faire, et que je mange de sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon se mit au lit, et se fit malade; son père l’alla voir, et Amnon lui dit: Que Thamar, ma sœur, vienne auprès de moi; qu’elle fasse cuire devant moi deux petits gâteaux, et je mangerai de sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Et David chercha Thamar dans la maison, et il lui dit Va-t’en chez ton frère, et prépare-lui à manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Et Thamar alla à la maison d’Amnon, son frère, quand il était couché. Elle prit de la pâte, la pétrit, et en fit sous ses yeux de petits gâteaux qu’elle mit cuire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Ensuite, elle prit la poêle, et elle la vida devant lui; mais il ne voulut pas manger, et il dit: Que l’on fasse sortir tous les hommes qui sont debout ici. Tout le monde s’en alla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Et Amnon dit à Thamar: Apporte-moi auprès de mon lit ma nourriture, et je mangerai de ta main; Thamar prit donc les gâteaux qu’elle avait préparés, et elle les porta à son frère Amnon vers son lit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Elle l’engagea à manger, et il la saisit, et il lui dit: Viens, dors avec moi, ma sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Et elle lui dit: Mon frère, ne m’avilis pas; car pareille chose ne doit pas se faire en Israël; ne fais pas cette folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Comment supporterais-je mon opprobre? Et toi, tu passerais pour un insensé en Israël. Parle plutôt à mon père; il ne m’éloignera pas de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Mais Amnon ne voulut rien entendre; il fut plus fort qu’elle; il l’humilia, et il dormit avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Et Amnon la prit soudain en grande haine, et sa haine l’emporta sur l’amour qu’il avait auparavant; car sa dernière méchanceté fut plus grande que la première. Amnon lui dit donc: Lève-toi, et va-t’en.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Thamar lui parla au sujet de cette grande méchanceté qu’il faisait en la chassant; plus grande, dit-elle, que la première; mais Amnon ne voulut rien entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Et il appela le serviteur qui se tenait à l’entrée de l’appartement, et il lui dit: Chasse-moi d’ici cette femme, et ferme la porte sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Elle avait un vêtement à longues manches comme en portaient les filles du roi qui étaient vierges. Et le serviteur la mit dehors, puis il ferma la porte sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Et Thamar prit de la cendre, s’en couvrit la chevelure, déchira son vêtement à longues manches, croisa les mains sur sa tête, et s’en alla, jetant les hauts cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Absalon, son frère, lui dit: Est-ce qu’Amnon, ton frère, a été avec toi? Alors, ma sœur, sois muette, car c’est ton frère. Ne prends pas à cœur d’ébruiter cette affaire. Ainsi Thamar demeura, comme une veuve, en la maison de son frère Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Le roi David apprit tout, et il en fut violemment courroucé, mais il ne chagrina point Amnon; car il l’aimait, parce que c’était son premier-né.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Quant à Absalon, il ne dit mot à son frère, ni en bien ni en mal; mais il le prit en haine pour avoir avili Thamar, sa sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Et ceci advint: au bout de deux années, on faisait la tonte pour Absalon en Belasor, sur le territoire d’Ephraïm, et Absalon invita tous les fils du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Absalon, d’abord, alla trouver le roi, et lui dit: Voilà que l’on fait la tonte pour ton serviteur, que le roi et tous ses fils viennent chez ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Le roi répondit à Absalon: Non, mon fils, nous n’irons pas tous; nous ne voulons point t’être à charge. Absalon le pressa; mais il ne céda point, et il le bénit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Alors, Absalon lui dit: Si tu refuses, que du moins mon frère Amnon vienne avec nous. Le roi lui répondit: Pourquoi donc irait-il avec toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Absalon le pressa, et David laissa partir avec lui Amnon et tous ses fils. Absalon leur fit un festin comme un festin de roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Puis, il donna ses ordres à ses serviteurs, disant: Faites attention; quand le cœur d’Amnon se complaira dans le vin, je vous dirai: Frappez Amnon et le mettez à mort; n’ayez point de crainte; n’est-ce point moi qui vous le commande? Soyez hommes, agissez en fils de la force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Les serviteurs d’Absalon exécutèrent contre Amnon ce que leur avait prescrit leur maître. Et tous les fils du roi se levèrent; chacun d’eux se mit en selle sur sa mule, et ils s’enfuirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Pendant qu’ils étaient encore en route, on vint dire à David: Absalon a tué tous les fils du roi, et il n’en reste pas un seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'À ces mots, le roi se leva; il déchira ses vêtements, et il se jeta à terre; et tous ses serviteurs qui l’entouraient déchirèrent leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Et Jonabab, fils de Samaa, frère de David, prit la parole, et il dit: Que le roi mon maître ne dise pas que tous ses serviteurs les fils du roi ont été mis à mort, car Amnon seul a péri; et c’était sur les lèvres d’Absalon depuis le jour où sa sœur Thamar a été humiliée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Maintenant donc, que le roi mon maître n’ait pas à cœur tout ce qu’on lui a rapporté, quand on a dit: Tous les fils du roi sont morts, car Amnon seul n’existe plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Or, Absalon s’était enfui; cependant, le serviteur qui faisait sentinelle leva les yeux, et il vit une nombreuse troupe qui accourait et descendait de la montagne; il entra pour l’apprendre au roi, et il dit: J’ai vu des hommes sur le chemin d’Oronen; ils descendent la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Et Jonabab dit au roi Tu vois, les fils du roi sont vivants; il est a Ivenu ce qu’avait dit ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Comme il achevait de parler, les fils du roi entrèrent; ils élevèrent la voix et ils pleurèrent; le roi aussi el tous ses serviteurs se prirent à pleurer amèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Or, Absalon s’était enfui; il se réfugia chez Tholmi, fils d’Emiud, roi de Gedsur, en la terre de Chamaachad, et le roi David pleura tous les jours son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalon s’était donc enfui, et il s’était retiré à Gedsur, où il demeura trois ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Le roi David renonça à le faire poursuivre, parce qu’il était consolé de la mort d’Amnon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Et Joab, fils de Sarvia, reconnut que le cœur de David revenait à Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Et il fit venir de Thécoé une femme expérimentée, à qui il dit: Pleure, prends des habits de deuil, ne te parfume pas, sóis comme une femme qui, depuis bien des jours, se lamente sur un mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Tu iras ainsi trouver le roi, et tu lui parleras comme je vais te dire. Et Joab mit les paroles sur les lèvres de la femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'La femme de Thécoé entra donc chez le roi; elle tomba la face contre terre, et elle l’adora, s’écriant: Salut,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Le roi lui dit: Que veux-tu? Elle répondit: Je suis une veuve, mon mari est mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Et ta servante avait deux fils; or, ils se sont battus dans les champs; il n’y avait là personne pour les séparer; l’un des deux a renversé son frère, et l’a tué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Et voilà que toute la famille s’élève contre ta servante, disant: Livre-nous celui qui a frappé son frère; nous lui ôterons la vie pour la vie de son frère qu’il a tué, et nous prendrons votre héritage. Ainsi, ils veulent éteindre l’étincelle qui me reste, afin qu’il n’y ait plus rien, sur la face de la terre, ni de mon mari, ni de son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Et le roi dit à la femme: Porte-toi bien; va en ta demeure; je donnerai des ordres à ton sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Et la femme de Thécoé dit à David: Que l’iniquité, ô roi, mon maître, retombe sur moi et sur la maison de mon père, que le roi et son trône en soient innocents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Le roi reprit: Quel est donc celui de ta famille qui t’a parlé? Amène-le-moi, et il ne touchera pas à ton fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'A quoi la femme répondit: Que le roi n’oublie point que le Seigneur son Dieu a désigné plus d’un vengeur du sang pour faire périr le meurtrier; veille à ce qu’on ne vienne pas m’enlever mon fils. Et David répondit: Vive le Seigneur! on ne lui fera pas tomber un cheveu de la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Alors, la femme ajouta: Que ta servante dise encore un mot au roi mon maître; et il répondit: Parle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Et la femme dit: Pourquoi donc as-tu cette pensée contre le peuple de Dieu? Ou cette parole de la bouche du roi est-elle comme un serment, pour que le roi n’ait pas encore rappelé celui qu’il a banni?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Nous mourrons tous de mort, nous serons comme l’eau qui s’écoule sur la terre et ne revient plus; Dieu prendra notre âme, et le roi a encore la pensée de repousser au loin celui qu’il a banni!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Maintenant que je suis venue dire cette parole au roi mon maître, le peuple me verra, et ta servante a dit: Qu’il soit parlé au roi mon maître, peut-être fera-t-il ce que dit sa servante;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Car le roi l’entendra. Qu’il protège sa servante contre l’homme qui veut dépouiller moi et mon fils de notre part dans l’héritage de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Et la femme ajouta: Le roi mon maître, comme un ange de Dieu, écoute le bon et le méchant; puisse donc la promesse qu’il m’a faite s’exécuter comme un sacrifice que l’on a voué, et le Seigneur ton Dieu sera avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Le roi reprit et il dit à la femme: Ne me cache rien de ce que je vais te demander, et la femme répondit: Que le roi mon maître parle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Et le roi dit: La main de Joab n’est-elle pas avec toi, en tout ceci? La femme répondit: Vive ton âme! ô roi mon maître, il n’y a pas à s’écarter à droite ni à gauche de ce que vient de dire le roi mon maître, car c’est ton serviteur Joab qui m’a donné ses ordres, et c’est lui qui a mis toutes ces paroles sur les lèvres de ta servante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'C’est pour ne point aborder de front une telle affaire, que Joab ton serviteur a pris ce détour. Mais, mon seigneur est sage, il a la sagesse de l’ange de Dieu pour discerner toute chose sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Et le roi dit à Joab: Voilà que j’ai fait pour toi comme tu avais dit; pars et ramène mon fils Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Et Joab tomba la face contre terre; il adora et bénit le roi. Puis, il dit: Aujourd’hui ton serviteur reconnaît qu’il a trouvé grâce devant tes yeux, ô roi mon maître, puisque tu as fait comme ton serviteur avait dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Joab se releva, il alla à Gedsur, et il amena Absalon à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Mais le roi dit: Qu’il retourne en sa demeure; qu’il ne voie point ma face. Absalon retourna donc en sa demeure, et il ne vit point la face du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Or, il n’y avait pas en tout Israël d’homme loué comme Absalon; depuis la plante des pieds jusqu’au sommet de la tête, il n’avait pas un défaut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Lorsqu’il se coupait les cheveux, et il se les coupait au commencement de chaque année, parce qu’il ́était incommodé de leur poids, il en recueillait deux cents sicles pesant, au poids du sicle royal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Absalon avait trois fils et une fille qui se nommait Thamar; celle-ci était extrêmement belle; elle fut la femme de Roboam, fils de Salomon, et elle lui enfanta Abia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Absalon demeura deux ans à Jérusalem, et il ne vit point la face du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Ensuite, Absalon envoya chez Joab pour que celuici le menât chez le roi, mais il ne voulut point venir; Absalon envoya une seconde fois; Joab refusa encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Enfin, Absalon dit à ses serviteurs: Voilà que Joab a dans la plaine un champ auprès des miens et où il y a de l’orge; allez, et mettez-y le feu. Les serviteurs d’Absalon incendièrent donc le champ; les serviteurs de Joab déchirèrent leurs vêtements, ils accoururent chez lui, et ils dirent: Les serviteurs d’Absalon viennent de brûler ton champ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Et Joab, se levant, alla trouver Absalon en sa demeure, et il lui dit: Pourquoi tes serviteurs ont-ils porté la flamme dans mon champ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalon dit à Joab. Je t’ai envoyé querir, disant: Viens chez moi, je veux t’envoyer dire au roi: Pourquoi ai-je quitté Gedsur? J’ai trouvé doux de rentrer en ma demeure, mais je ne vois point la face du roi. S’il y a en moi une iniquité, que l’on me mette à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Joab rentra chez le roi et lui raconta tout; puis, il appela Absalon, et celui-ci entra auprès du roi, et il l’adora, et il tomba la face contre terre devant la face du roi; et le roi baisa Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Il arriva ensuite qu’Absalon se fit faire des chars, il exerça des chevaux, et il eut cinquante hommes pour courir devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Et Absalon se levait de grand matin, il se tenait sur le chemin près de la porte, et tout homme qui était en procès, qui allait demander jugement au roi, Absalon l’appelait et lui disait: De quelle ville es-tu? A quoi l’autre répondait: Ton serviteur est de l’une des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Et Absalon lui disait: Ta cause est bonne et claire, mais il n’y a chez le roi personne pour t’écouter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Et il ajoutait: Que ne suis-je institué juge en cette terre; tout homme qui aurait procès ou contestation viendrait à moi, et je le jugerais?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Et lorsque l’homme s’approchait pour le saluer, il étendait la main, l’attirait à lui et le baisait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Absalon agit de cette manière avec tous ceux d’Israël qui allaient en justice devant le roi, et il gagna le cœur de tous les hommes d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Il avait quarante ans passés, et il dit à son père: Je vais partir pour Hébron, afin de m’acquitter d’un vœu que j’ai fait au Seigneur..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Car ton serviteur, lorsqu’il demeurait à Gedsur en Syrie, a fait ce vœu: Si le Seigneur m’accorde de rentrer à Jérusalem, je ferai un sacrifice au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Et le roi lui dit: Va en paix. Et il se leva et il alla en Hébron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'De là, Absalon envoya des émissaires parmi toutes les tribus d’Israël, disant: Quand vous entendrez sonner du cor, dites: Absalon dans Hébron est proclamé roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Absalon avait avec lui deux cents hommes, des premiers de Jérusalem qui l’avaient suivi en toute simplicité, ne sachant rien de ses projets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Et pendant le sacrifice, il fit venir de Gola, sa ville, Achitophel, fils de Théconi, conseiller de David. Et il y eut une conspiration redoutable, et le peuple qui était venu auprès d’Absalon, était très-nombreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Or, un homme courut l’annoncer à David, disant: Le cœur des hommes d’Israël s’est tourné vers Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Et David dit à tous les serviteurs qu’il avait avec lui en Jérusalem: Levez-vous et prenons la fuite, car il n’y a point pour nous de salut devant Absalon; hâtez-vous, de peur qu’il ne nous devance et ne nous prenne, qu’il ne nous apporte le mal, et qu’il ne passe la ville au fil de l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Et les serviteurs du roi lui dirent: Que la volonté du roi notre maître soit faite; voici tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Et le roi sortit à pied, avec toute sa maison; et le roi laissa, pour garder sa demeure, dix de ses concubines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Le roi sortit donc à pied avec tous ses serviteurs, et ils s’arrêtèrent à une maison éloignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Là, tous ses serviteurs défilèrent devant lui; tout Chéléthi, tout Phéléthi; puis, ils firent halte sous les oliviers dans le désert. Tout le peuple le suivait de près ainsi que toute sa maison, et tous les hommes forts, au nombre de six cents combattants. Ils défilèrent devant lui comme tout Chéléthi, tout Phéléthi, et tous les Géthéens au nombre de six cents venus à pied de Geth; quand ceux ci passèrent devant le roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Il dit à Ethi le Géthéen: Pourquoi es-tu venu aussi avec nous? Va-t’en et reste chez ton roi, car tu es étranger et tu as émigré de ta contrée natale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Tu ne fais que d’arriver; dois-je sitôt t’emmener avec nous? Tu changerais encore de lieux; hier tu es sorti, et aujourd’hui je te ferais venir avec nous! Pour moi, j’irai où je pourrai; va-t’en et emmène tes frères qui t’ont suivi, le Seigneur te traitera selon sa miséricorde et sa vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Or, Ethi répondit au roi: Vive le Seigneur et vive le roi mon maître! où ira mon maître, à la vie et à la mort, là sera ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Et le roi dit à Ethi: Viens et traverse le torrent. Alors, le Géthéen Ethi, le roi, tous ses serviteurs, toute la foule qui le suivait, passèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Cependant, toute la terre pleurait en jetant les hauts cris, tout le peuple avait passé le torrent de Cédron, le roi l’avait traversé aussi. Et tous prirent le chemin qui mène au désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'A ce moment, Sadoc et avec lui tous les lévites');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Et le roi dit à Sadoc: Retourne à la ville avec l’arche de Dieu; si je trouve grâce devant le Seigneur, il m’y fera rentrer moi-même; il me fera revoir l’arche et sa beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Et s’il me dit: Je ne me complais plus à être en toi; me voici, qu’il fasse de moi ce que bon lui semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Le roi dit donc à Sadoc le prêtre: Retourne en paix à la ville avec Achimaas, ton fils, et Jonathas, fils d’Abiathar, vos deux fils vous suivront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Pour moi, je m’en vais en Araboth du désert, je serai sous les armes, jusqu’à ce que vous m’ayez fait savoir quelque nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Ainsi, Sadoc et Abiathar ramenèrent à Jérusalem l’arche de Dieu, et elle y demeura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Et David monta sur la montagne des Oliviers; en montant, il pleurait, la tête voilée; il allait pieds nus, et avec lui tout le peuple, la tête voilée, montait et pleurait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Or, des gens vinrent dire à David: Achitophel est au nombre des séditieux qui suivent Absalon. Et David dit: Seigneur mon Dieu, confondez les desseins d’Achitophel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'David était allé jusqu’à Rhos, où il adorait le Scigneur, quand arriva devant lui Chusaï, son compagnon bien-aimé, les vêtements déchirés, la tête couverte de cendres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Et David lui dit: Si tu viens avec nous, tu seras pour moi un fardeau;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Mais si tu retournes à la ville, et si tu dis à Absalon: J’ai vu passer tes frères; j’ai vu passer le roi ton père, et maintenant, ô roi! je suis ton serviteur, laissemoi vivre; j’étais jadis, et tout à l’heure encore, serviteur de ton père, et maintenant je suis le tien; tu confondras les desseins d’Achitophel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Tu auras avec toi Sadoc et Abiathar les prêtres, et toute parole que tu pourras surprendre dans la maison du roi, tu en donneras connaissance aux prêtres Sadoc et Abiathar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Ils ont avec eux leurs deux fils Achimaas, fils de Sadoc, et Jonathas, fils d’Abiathar; vous me ferez savoir, en me les envoyant, toute parole que vous aurez surprise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Et Chusaï, le favori de David, rentra dans Jérusalem au moment où Absalon venait d’y faire son entrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'David s’était à peine éloigné de Rhos, quand arriva, devant lui, Siba, le serviteur de Miphiboseth, avec deux ânes chargés; or, il y avait sur les ânes deux cents pains, cent sacs de raisins secs, cent sacs de dattes et un nebel de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Et le roi dit à Siba: Que veux-tu faire de cela? Siba répondit: Les bêtes sont à la famille du roi, pour qu’elle les monte; les pains et les dattes, aux jeunes serviteurs, pour qu’ils les mangent; le vin, à ceux qui tomberont de fatigue dans le désert, pour qu’ils le boivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'David reprit: Où est le fils de ton maître? Et Siba répondit: Il est resté à Jérusalem, parce qu’il a dit: Aujourd’hui la maison d’Israël va me rendre la royauté de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Et le roi dit à Siba: Tout ce qui appartenait à Miphiboseth est à toi; et Siba, se prosternant, lui répondit: Puissé-je avoir trouvé grâce à tes yeux, ô roi, mon maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Et le roi David alla jusqu’à Bathurim, et il sortit de là un homme de la famille de Saül, nommé Sémeï, fils de Géra; il sortit; et, en marchant, il maudissait David;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Il jetait des pierres au roi et à tous ses serviteurs. Or, tout le peuple était là avec tous les hommes vaillants, les uns à droite, les autres à la gauche du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Sémeï maudissait donc, disant: Hors d’ici, hors d’ici, homme de sang, homme de péché!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Le Seigneur a fait retomber sur toi tout le sang de la maison de Saül, après que tu as régné à sa place. Et le Seigneur a donné ton royaume à ton fils Absalon; te voilà pris dans ta propre méchanceté, parce que tu es un homme de sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Abessa, fils de Sarvia, dit à David Pourquoi ce chien mort maudit-il le roi mon maître? Je vais à lui, et je lui trancherai la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Mais le roi répondit: Qu’y a-t-il entre vous et moi, fils de Sarvia? Laisse-le, et qu’il continue de maudire, car le Seigneur lui a dit de maudire David; qui donc ira lui dire: D’où vient que tu agis de la sorte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'David dit encore à Abessa et à tous ses serviteurs: Voilà que mon fils, sorti de mes entrailles, en veut à ma vie, et en outre vous entendez maintenant ce fils de Benjamin; laissez-le maudire, car le Seigneur le lui a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'S’il advient que le Seigneur jette un regard sur mon humiliation, il me rendra ses bienfaits pour prix des malédictions de cet homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Et David continua de suivre la route avec tous les siens; et Semeï, sur les flancs de la montagne, s’attachant à ses pas, continua de le maudire, de lui jeter des pierres, et de faire voler sur lui la poussière du chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Le roi et tout le peuple qui l’accompagnait arrivèrent à Bathurim exténués de fatigue; ils y reprirent haleine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalon venait donc d’entrer à Jérusalem, et avec lui tous les hommes d’Israël, et Achitophel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Quand Chusaï, le favori de David, alla trouver Absalon, et lui dit: Vive le roi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalon dit à Chusaï: Voilà comme tu as compassion de ton ami? Pourquoi n’es-tu pas parti avec ton ami?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Dieu m’en garde, reprit Chusaï; je suivrai celui qu’ont choisi le Seigneur, et tout le peuple et tout Israël; je serai à lui, je résiderai où il résidera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Et, encore une fois, qui donc servirais-je, si ce n’est le fils de mon maître? Comme j’ai servi ton père, je te servirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Absalon dit ensuite à Achitophel: Délibérez entre vous sur ce que nous ferons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Et Achitophel dit à Absalon: Approche-toi des concubines de ton père, qu’il a laissées pour garder son pa lais; tout Israël apprendra que tu as déshonoré ton père, et les mains de ceux de ton parti seront fortifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Puis, ils dressèrent une tente sur la plate-forme du palais, et Absalon s’approcha des concubines de son père aux yeux de tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Les conseils que donnait Achitophel, en ces premiers jours, étaient reçus comme ceux d’un homme qui aurait consulté Dieu. Ainsi pensaient de tout conseil d’Achitophel David aussi bien qu’Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Et Achitophel dit à Absalon: Je vais choisir douze mille hommes, et je partirai, et je poursuivrai David cette nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Il sera fatigué, énervé, quand je l’attaquerai et le remplirai de trouble; tout le peuple qui l’entoure fuira, et je frapperai le roi dès qu’il sera seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Ensuite, je te ramènerai tout le peuple, et il te reviendra comme revient une épouse auprès de son mari; puisque tu n’en veux qu’à la vie d’un seul homme, tout le peuple sera en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Le conseil parut excellent à Absalon et à tous les anciens d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Et Absalon dit: Appelez Chusaï d’Arach; sachons ce que celui-là aussi pourra nous dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Chusaï entra donc auprès d’Absalon, et Absalon lui dit Voici comme a parlé Achitophel; ferons-nous ce qu’il a conseillé? Si ce n’est pas ton avis, parle à ton tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Pour cette fois, répondit Chusaï, le conseil d’Achitophel n’est pas bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'El Chusaï ajouta: Tu connais ton père et ses hommes; ils sont très-vaillants, et leur âme est pleine d’amertume. Ils ressemblent à l’ours à qui, dans les champs, on a enlevé ses petits, ou au sanglier hérissé de la plaine; ton père est un guerrier, et il ne laisse pas son armée prendre de repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Maintenant, il est à couvert dans les montagnes ou dans quelque autre lieu, et vous ne l’aurez pas plutôt assailli qu’un bruit se répandra, et que l’on dira: Il y a eu un massacre de ceux qui suivent Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Et même le fils de la vaillance, dont le cœur est comme le cœur du lion, défaillira; car tout Israël sait que ton père est un homme vaillant, et qu’il est entouré de fils vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'C’est pourquoi voici ce que je préfère de beaucoup: rassemble auprès de toi tout Israël, depuis Dan jusqu’à Bersabée, aussi nombreux que le sable du rivage de la mer; et mets-toi en campagne au milieu de cette multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Alors, nous marcherons contre lui en l’un des lieux où nous pensons le trouver; nous tomberons sur lui à l’improviste, comme la rosée tombe sur la terre, et nous n’épargnerons ni lui ni un seul des hommes qui l’accompagnent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Et s’il s’est réfugié avec ses gens en quelque ville, tout Israël apportera des câbles devant cette ville, et nous en entraînerons les débris jusqu’au torrent, afin qu’il n’en reste pas une pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Absalon et tout Israël s’écrièrent: Le conseil de Chusaï d’Arach vaut mieux que le conseil d’Achitophel. Et le Seigneur voulut que le sage dessein d’Achitophel fût confondu, afin que le Seigneur fit tomber sur Absalon toute sorte de maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Et Chusaï d’Arach dit aux prêtres Sadoc et Abiathar: Voilà ce qu’avait conseillé Achitophel à Absalon et aux anciens du peuple; voilà ce que je leur ai conseillé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Maintenant, faites-le rapidement savoir à David; qu’on lui dise: Ne passe pas la nuit à Araboth dans le désert; hâte-toi de traverser le Jourdain, de peur que le roi et tous les siens ne périssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Or, Jonathas et Achimaas étaient restés vers la fontaine de Rhogel; une servante y courut et leur transmit le message; eux-mêmes partirent pour le porter au roi David; car il n’était pas possible qu’on les eût vus entrer dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Mais un jeune serviteur les vit en marche, et il l’alla rapporter à Absalon. Cependant, ils s’étaient hâtés, et ils étaient déjà dans la maison d’un homme de Bahurim, qui avait dans sa cour une citerne, où ils descendirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Alors, la femme de cet homme étendit une couverture sur l’orifice de la citerne; elle y mit sécher du blé, et la chose ne fut point découverte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Les serviteurs d’Absalon vinrent dans la maison vers la femme, et ils lui dirent: Où sont Achimaas et Jonathas? Elle répondit: Ils ont passé un peu au delà du torrent. Et les serviteurs cherchèrent; et, ne les ayant pas trouvés, ils retournèrent à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Lorsqu’ils se furent éloignés, les deux jeunes gens sortirent de leur citerne, s’en allèrent, et dirent tout à David; puis, ils ajoutèrent: Hâte-toi de traverser le fleuve, car voici le conseil qu’a donné contre toi Achitophel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'David se leva, ainsi que tout le peuple qui l’accompagnait; ils passèrent le Jourdain jusqu’au lever de l’aurore, et il n’y eut pas un seul des siens qui restàt en deçà du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Quand Achitophel vit que son conseil n’était pas suivi, il bâta son ânesse, retourna en sa demeure dans sa ville, donna des instructions à sa famille, se pendit, et mourut; on l’ensevelit dans le sépulcre de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Cependant, David passa en Manaïm, et Absalon franchit à son tour le Jourdain avec tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Et Absalon mit à la tête de l’armée, à la place de Joab, Amessaï, fils d’un homme qui se nommait Jéther le Jezraélite; celui-ci l’avait eu d’Abigail, fille de Naas, sœur de Sarvia, mère de Joab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Or, tout Israël et Absalon campèrent en la terre de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Lorsque David était arrivé en Manaïm, Uesbi, fils de Naas, de Rhabbath, ville des fils d’Ammon, Machis, fils d’Amiel de Ladabar, et Berzelli le Galaadite, de Rhogellim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Lui apportèrent dix tapis laineux des deux côtés, dix marmites, des vases d’argile, du froment, de l’orge, de la pâte, de la farine, des fèves, des lentilles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Du miel, du beurre, des moutons et du fromage de vache; ils offrirent tout cela à David et au peuple qui l’accompagnait; car ils s’étaient dit: Ce peuple a faim, il est exténué et il souffre de la soif dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Et David inspecta le peuple qui était avec lui, et lui donna des centeniers et des commandants de mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Puis, il fit partir le tiers de son armée avec Joab; le second tiers avec Abessa, fils de Sarvia, frère de Joab; le dernier tiers avec Ethi le Géthéen; et David dit aux siens: Moi aussi je me mettrai en campagne avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Et ils s’écrièrent: Ne sors point; car, si nous venions à fuir, ce n’est pas nous que tes ennemis ont à cœur; si la moitié de nous venait à périr, ce n’est pas nous qu’ils ont à cœur, parce que tu vaux dix mille de nous. Il est bon maintenant que tu restes dans la ville, où tu es notre soutien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Le roi reprit: Je ferai ce qui est agréable à vos yeux. Et le roi se tint à deux pas de la porte, tandis que sa troupe entière sortait par corps de cent et de mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Et le roi donna des ordres à Joab, Abessa et Ethi, disant: Pour l’amour de moi, épargnez Absalon; toute l’armée entendit ce que le roi prescrivait aux chefs, concernant Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Toute l’armée étant sortie, se rangea en face d’Israël dans la forêt, et la bataille fut livrée dans la forêt d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Là, Israël échoua contre les serviteurs de David; il y eut, en ce jour-là, un grand carnage; Israël perdit vingt mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Le combat s’étendit sur toute la terre environnante, et le nombre de ceux que dévora la forêt surpassa le nombre de ceux que le glaive avait dévorés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Or, Absalon se trouva face à face avec des serviteurs de David; il était monté sur sa mule, la mule entra sous le branchage touffu d’un grand chêne, et la tête d’Absalon fut prise dans le chêne; il resta donc suspendu entre le ciel et la terre, et la mule s’échappa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Un homme le vit, en informa Joab, et lui dit: Voilà que j’ai vu Absalon suspendu sous un chêne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Et Joab dit à l’homme qui lui apportait cette nouvelle: Tu l’as vu; et pourquoi ne l’as-tu pas d’un seul coup jeté à terre? Je t’aurais donné dix sicles d’argent avec une ceinture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'L’homme reprit: Pour moi, quand même j’aurais reçu mille sicles d’argent, je ne porterais pas la main sur le fils du roi, parce que nous avons ouï le roi donner ses ordres à toi, à Abessa et à Ethi, disant: Pour l’amour de moi, épargnez mon fils Absalon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Que l’on n’attente pas à sa vie. Toute l’affaire serait connue de David, et toi-même tu serais contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Alors, Joab s’écria: C’est donc moi qui le ferai; je ne resterai pas ainsi devant toi. A ces mots, il prit en ses mains trois traits et il les lança dans le cœur d’Absalon, qui vivait encore, suspendu au milieu du chêne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Puis, dix serviteurs, qui portaient les armes de Joab, entourèrent Absalon, et le frappant, ils l’achevèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Et Joab fit sonner du cor; et l’armée, revenant sur ses pas, cessa de poursuivre Israël, et Joab épargna le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Ensuite, il prit Absalon, le jeta au fond d’une crevasse, sous la chênaie, dans une fosse profonde, et le recouvrit d’un grand monceau de pierres; tout Israël s’enfuit chacun sous sa tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalon, de son vivant, avait dressé pour lui une colonne, près de laquelle il fut pris; et il l’avait ainsi dressée afin d’avoir une colonne dans le val du Roi; car, disait-il, je n’ai point de fils qui perpétuerait la mémoire de mon nom. Et de nos jours encore on nomme cette colonne, la Main d’Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Or, Achimaas, fils de Sadoc, dit: Je vais courir et porter au roi la bonne nouvelle que le Seigneur l’a tiré des mains de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Mais, Joab lui répondit: Aujourd’hui tu ne serais pas le messager d’une bonne nouvelle, un autre jour tu la porteras plus à propos. A ce moment ce ne serait pas une bonne nouvelle, parce que le fils du roi est mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Et Joab dit à Chusaï: Va rapporter au roi ce que tu as vu. Chusaï se proșterna devant Joab et partit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Achimaas, fils de Sadoc, reprit la parole et dit à Joab: Je vais courir après Chusaï. Mon fils, répondit Joab, pourquoi veux-tu courir? Reste; ce n’est point une bonne nouvelle, et tu n’auras aucun profit à la porter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'L’autre repartit: Qu’en sera-t-il, si je cours? Cours donc, reprit Joab. Et Achimaas courut par le chemin de Cechar, et il devança Chusaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Or, David était assis entre les deux portes, quand une sentinelle placée sur la plate-forme de la porte du rempart leva les yeux, et vit un homme seul qui courait devant elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'La sentinelle élevant la voix l’annonça au roi, et le roi dit S’il est seul, il a sur les lèvres une bonne nouvelle. Or, l’homme allait toujours et il approchait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Et la sentinelle, voyant un autre homme qui courait, cria pour être entendue au bas de la porte, et dit: Voilà un autre homme qui court seul, et le roi dit: Celui-ci encore apporte une bonne nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'La sentinelle reprit: Je reconnais à sa manière de courir que le premier est Achimaas, fils de Sadoc. C’est un homme bon, dit le roi, il n’arrivera qu’avec une bonne nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Et Achimaas éleva la voix, et il cria: La paix; puis, il se prosterna devant le roi la face contre terre, et il dit: Béni soit le Seigneur Dieu qui a fait échouer les hommes dont la main s’était levée contre le roi mon maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'David répondit: Mon fils Absalon se porte-t-il bien? Et Achimaas reprit: J’ai vu une grande multitude au moment où Joab venait d’envoyer le serviteur du roi et ton serviteur, mais je n’ai point su ce qui se passait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Et le roi dit: Mets-toi de côté et reste ici. Achimaas se détourna et ne bougea plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Alors, Chusaï arriva, et il dit: Bonne nouvelle pour le roi mon maître! le Seigneur t’a vengé aujourd’hui de ceux qui s’étaient levés contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Le roi répondit: Mon fils Absalon se porte-t-il bien? Et Chusaï répondit: Puissent les mêmes maux qui ont frappé le jeune homme atteindre tous tes ennemis, et ceux qui se sont levés contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Et le roi fut troublé; il monta dans la salle au-dessus de la porte, il pleura, et en s’y promenant il s’écriait: Mon fils Absalon, mon fils, mon fils Absalon, qui m’accordera de mourir au lieu de toi? Ma mort au lieu de la tienne, mon fils Absalon, mon fils!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Or, des gens le rapportèrent à Joab, disant: Voilà que le roi pleure et se lamente à cause d’Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'La victoire de ce jour s’est changée en deuil pour tout le peuple, parce que le peuple a ouï que le roi s’affligeait à cause de son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Et l’armée se glissa en cachette dans la ville, comme s’y glisse une armée honteuse d’avoir pris la fuite pendant le combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Et le roi se voila la face, et le roi s’écria à haute voix, disant Absalon, mon fils! Absalon, mon fils!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Enfin, Joab entra auprès du roi en sa demeure, et il dit: Tu outrages tous les serviteurs qui aujourd’hui ont pris parti pour toi, et pour la vie de tes fils, de tes filles, de tes femmes et de tes concubines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Puisque tu aimes ceux qui te haïssent et que tu hais ceux qui t’aiment, tu fais connaître que tes princes et tes serviteurs ne te sont rien; car je sais à présent que si Absalon était vivant, et nous tous morts, à tes yeux ce serait bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Lève-toi, sors, parle au cœur de tes serviteurs; car, je te jure par le Seigneur que si tu ne te mets en marche aujourd’hui, pas un homme ne passera cette nuit auprès de toi. Reconnais-le en toi-même: ce serait pour toi un malheur plus grand que tous ceux qui te sont venus, depuis ta première jeunesse jusqu’à cette heure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Alors, le roi se leva, s’assit sur la porte, et toute l’armée se dit: Voilà le roi assis sur la porte. Et toute l’armée s’approcha du roi devant la porte; car Israël s’était enfui chacun sous sa tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Et le peuple de toutes les tribus d’Israël se mit à discuter, disant: Le roi David nous a délivrés de tous nos ennemis; c’est lui qui nous a affranchis du joug des Philistins, et il vient de s’enfuir de sa terre, de son royaume, à cause d’Absalon!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Cet Absalon que nous avions sacré, pour qu’il régnât sur nous, a été tué dans la bataille; pourquoi donc ne parlez-vous pas de rappeler David? Or, les discours de tout Israël arrivèrent jusqu’au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Et le roi David envoya auprès des prêtres Sadoc et Abiathar, disant: Parlez aux anciens de Juda, ditesleur: Pourquoi donc êtes-vous les derniers à rappeler le roi en sa demeure? Les discours de tout Israël sont arrivés jusqu’au roi, au lieu où il réside.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Vous êtes mes frères, vous êtes ma chair et mes os: pourquoi donc êtes-vous les derniers à ramener le roi dans sa demeure?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Et vous direz à Amessaï: David dit: N’es-tu pas ma chair et mes os? Que le Seigneur me punisse et qu’il me punisse encore, si tu ne deviens pas, devant moi pour toujours, le général en chef de toutes nos armées, à la place de Joab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Il gagna ainsi le cœur de tous les hommes de Juda, comme le cœur d’un seul homme; et ils envoyèrent au roi, et ils lui dirent: Reviens avec tous tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Et le roi se mit en marche; il alla jusqu’au Jourdain, et tous les hommes de Juda se portèrent à sa rencontre à Galgala, pour le ramener en deçà du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Et Seméï, fils de Géra, de la famille de Jémini en Bathurim, se hâta, et il se mêla aux hommes de Juda, pour aller au-devant du roi David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Il avait avec lui mille hommes de Benjamin, et Siba le serviteur de Saül, et ses quinze fils, et ses vingt serviteurs; ils marchèrent droit au Jourdain, au-devant du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Et ils préparèrent le service du passage du roi; ils lui menèrent un bac pour exciter l’ardeur de la maison du roi, et pour qu’il fût fait selon le bon plaisir de David. Or, Seméï, fils de Géra, se jeta devant lui la face contre terre, dès qu’il eut passé le Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Et il dit au roi: Que mon Seigneur ne tienne pas compte de mon iniquité, qu’il ne se souvienne pas que son serviteur a péché le jour où mon seigneur est sorti de Jérusalem; puisse-t-il ne l’avoir point à cœur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Car ton serviteur a reconnu sa faute, et voilà que j’arrive aujourd’hui le premier de tout Israël et de la maison de Joseph, pour m’humilier devant le roi mon seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Abessa, fils de Sarvia, dit: Est-ce que Seméï ne sera pas mis à mort, pour avoir maudit l’oint dụ Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Mais David dit: Qu’y a-t-il entre vous et moi, fils de Sarvia, pour qu’aujourd’hui vous ne tendiez un piége? Nul homme en Israël aujourd’hui ne sera mis à mort; est-ce que j’ignore que je règne sur Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Et le roi dit à Sémeï: Tu ne mourras point; et il le lui jura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Miphiboseth, petit-fils de Saül, alla aussi à la rencontre du roi; il n’avait pris aucun soin de ses pieds; il ne s’était point coupé les ongles, il ne s’était point rasé autour des lèvres, il n’avait point lavé ses vêtements, depuis le jour où le roi avait quitté Jérusalem jusqu’à ce jour où il revenait en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Et lorsqu’il alla à la rencontre du roi retournant à Jérusalem, David lui dit; Pourquoi n’es-tu point venu avec moi, Miphiboseth?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Miphiboseth lui répondit: O roi mon seigneur, mon serviteur m’a trompé, car ton serviteur lui avait dit: bâte-moi l’ânesse, que je la monte, et je suivrai le roi (tu sais que ton serviteur est boiteux).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Or, Siba a usé d’artifice à l’égard de ton serviteur, devant le roi mon seigneur. Le roi mon seigneur est comme un ange de Dieu, qu’il fasse de moi ce que bon lui semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Car tous ceux de la maison de mon père étaient des hommes de mort, devant le roi mon seigneur, quand tu as fait de ton serviteur l’un de tes convives, Quelle justification peut donc m’être permise pour que je crie encore devant le roi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Et le roi lui dit: Qu’est-il besoin que tu parles davantage? J’ai prononcé: Siba et toi vous partagerez les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Miphiboseth reprit: Qu’il prenne tout, puisque le roi mon seigneur rentre en paix dans sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Or, Berzelli le Galaadite était sorti de Rhogellim, et il avait passé le Jourdain avec le roi, afin de l’escorter de l’autre côté du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Berzelli était un homme très-âgé: il avait quatrevingts ans; il avait nourri le roi pendant son séjour à Manaïm, car il était extrêmement riche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Le roi lui dit: Tu vas venir plus loin avec moi, et je nourrirai, auprès de moi, ta vieillesse à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Mais Berzelli lui répondit: Combien de jours me reste-t-il à vivre, pour que j’aille avec le roi à Jérusalem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'J’ai aujourd’hui quatre-vingts ans; puis-je encore discerner le bon et le mauvais? Ton serviteur trouve-t-il quelque goût à ce qu’il mange et à ce qu’il boit? Écoutet-il avec plaisir la voix des chanteurs et des chanteuses? Pourquoi ton serviteur irait-il attrister son seigneur et son roi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Ton serviteur accompagnera son roi quelque peu au delà du fleuve. Pourquoi donc le roi me donnerait-il une si grande récompense?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Que ton serviteur reste en repos; je mourrai dans ma ville, auprès du sépulcre de mon père et de ma mère; voilà ton serviteur Chamaam, mon fils; il suivra plus loin le roi mon seigneur; traite-le comme bon te semblera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Le roi reprit: Que Chamaam vienne avec moi, et je le traiterai de mon mieux; et tout ce que tu pourras désirer de ina main, je le ferai pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Et l’armée entière franchit le Jourdain, le roi passa; puis, il baisa Berzelli et le bénit, et celui-ci retourna en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Le roi se rendit ensuite à Galgala, et Chamaam le suivit; il y avait avec le roi tout le peuple de Juda et la moitié d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Et tous ceux d’Israël allèrent trouver le roi, et ils lui dirent Pourquoi nos frères de Juda nous ont-ils dérobé le roi? Pourquoi l’ont-ils escorté quand il a traversé le fleuve avec toute sa maison et tous les hommes de sa suite?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Ceux de Juda répondirent à ceux d’Israël, et ils dirent Pourquoi le roi nous est-il proche? et pourquoi à ce sujet vous irritez-vous si fort? Avons-nous mangé aux dépens du roi? nous a-t-il fait des présents? a-t-il levé quelque tribut pour nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Et ceux d’Israël répliquèrent: Nous avons dix bras au service du roi, nous sommes vos premiers-nés, nous sommes plus que vous auprès de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 44, 'Pourquoi donc nous injurier et ne pas tenir compte de ce qu’avant Juda nous avons parlé de ramener notre roi? Or, les paroles de ceux de Juda avaient été plus dures que celles d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Et il y avait là, parmi les hommes inculpés, un homme pervers; il se nommait Sabé, fils de Bochori, de la famille de Jémini; il sonna du cor, et il dit: Nos champs ne dépendent point de David; nous ne tenons pas notre héritage du fils de Jessé. Israël, que chacun de nous retourne sous sa tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Et tous ceux d’Israël qui suivaient David s’en allèrent avec Sabé, fils de Bochori; et ceux de Juda se serrèrent autour de leur roi, depuis le Jourdain jusqu’à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Et le roi rentra en sa demeure à Jérusalem; là, il prit ses dix concubines qu’il avait laissées pour garder le palais, les fit renfermer et les nourrit; mais il ne s’ approcha plus d’elles, et elles furent recluses jusqu’au jour de leur mort, vivant comme des veuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Après cela, le roi dit à Amessaï: Fais-moi venir dans trois jours les hommes de Juda, et reviens ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Et Amessaï partit pour convoquer Juda; mais il tarda plus que ne le lui avait prescrit David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Et David dit à Abessa: Maintenant Sabé, fils de Bochori, va nous faire plus de mal qu’Absalon; prends donc avec toi les serviteurs de ton maître, et poursuis-le, avant qu’il ait trouvé quelque ville forte, car alors il obscurcirait nos yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Et Abessa sortit pour le poursuivre avec les hommes de Joab, et Chéléthi, et Phéléthi et tous les vaillants; tous sortirent de Jérusalem afin de poursuivre Sabé, fils de Bochori.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Ils étaient vers la grande pierre que l’on voit en Gabaon, quand Amessaï arriva devant l’armée. Joab avait une casaque sur son vêtement, et par-dessus la ceinture, une dague dont le fourreau était attaché le long de sa hanche; cette dague n’était pas plutôt tirée qu’elle frappait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Et Joab dit à Amessaï: Es-tu en bonne santé, mon frère? En même temps, de la main droite, il lui prit la barbe pour le baiser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amessaï ne prit point garde à la dague que Joab tenait à la main; celui-ci le frappa au ventre; les entrailles se répandirent à terre, et il ne lui porta pas un second coup, car il était mort; puis Joab, avec son frère Abessa, se mit à la poursuite de Sabé, fils de Bochori.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Cependant, un serviteur de Joab s’arrêtant près du corps d’Amessaï, dit: Qui veut Joab; qui est pour David, et veut suivre Joab?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Et Amessaï, baigné dans son sang, gisait au milieu du chemin, quand un homme, voyant que toute l’armée s’arrêtait, traîna le corps dans un champ voisin, et le couvrit d’un manteau, parce qu’il avait remarqué que chacun s’arrêtait auprès de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Aussitôt qu’il l’eut retiré du chemin, tout Israël passa, et se mit avec Joab à la poursuite de Sabé, fils de Bochori.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Celui-ci, à travers toutes les tribus d’Israël, atteignit Abel et Bethmacha; à ce moment, tous ceux de Charrhi étaient rassemblés, et ils le suivirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'On le rejoignit, on l’assiégea dans Abel et Permacha; on l’entoura de terrasses qu’on poussa jusqu’aux remparts; et toute l’armée de Joab se préparait à les saper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Quand une femme expérimentée cria du haut de la muraille: Écoutez, écoutez, dites à Joab qu’il approche, j’ai à lui parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Il s’approcha d’elle, et la femme dit: Es-tu Joab? Je le suis, dit-il; et elle reprit: Écoute un mot de ta servante. Il répliqua: Je t’écoute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Alors, elle dit: Il y avait un proverbe chez nos pères; lorsque parmi les fidèles d’Israël, un de leurs desseins venait à manquer, on disait: Il faut consulter et consulter à Abel ou à Dan. Maintenant tes hommes consultent et consultent en Abel, après avoir, eux aussi, défailli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Or, Abel te répond: Je suis pacifique parmi les appuis d’Israël, et toi, tu cherches à faire périr une ville et une métropole d’Israël; pourquoi veux-tu jeter dans l’abîme l’héritage du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Et Joab prit la parole, et il dit: Dieu me soit propice, qu’il me soit propice, je ne veux ni abîmer, ni détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Ce n’est point de cela qu’il s’agit, mais un homme des montagnes d’Ephraïm qui se nomme Sabé, fils de Bochori, a levé la main contre le roi David. Livrez-moi celuilà seul, et je m’éloignerai soudain de la ville. Et la femme dit à Joab: Voilà que sa tête va tomber devant toi du haut de la muraille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Aussitôt, la femme entra à l’assemblée du peuple, et elle parla sagement à toute la ville. On trancha la tête de Sabé, fils de Bochori, et on la jeta devant Joab; celuici fit sonner du cor; l’armée se dispersa, chacun retourna en sa demeure. Et Joab revint à Jérusalem auprès du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab commandait toute l’armée d’Israël; Banaïas, fils de Joïada, avait sous ses ordres Chéléthi et Phéléthi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoniram était intendant des impôts, et Josaphath, fils d’Achilud, garde des actes publics.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Susa était scribe, Sadoc et Abiathar, prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Iras, fils d’Iarin, était prêtre de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Et du temps de David, il y eut une famine qui dura trois années consécutives. David questionna le Seigneur, et le Seigneur dit: Sur Saül et sur sa maison pèse une iniquité qui demande encore de son sang, parce qu’il a mis à mort les Gabaonites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Le roi David appela les Gabaonites, et il s’entretint avec eux. Or, les Gabaonites ne sont point fils d’Israël, mais un débris des Amorrhéens, et les fils d’Israël leur avaient prêté serment; malgré cela, Saül entreprit de les exterminer, dans son zèle pour les fils d’Israël et de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'David dit donc aux Gabaonites: Que puis-je faire pour vous? comment pourrai-je vous apaiser afin que vous bénissiez l’héritage du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Et les Gabaonites répondirent: Entre nous et entre Saül et sa famille, il n’est question ni d’argent, ni d’or, et nul en Israël ne doit, à cause de nous, mourir. Et David reprit: Que voulez-vous dire? Parlez, je le ferai pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Et ils dirent au roi: L’homme qui a tourné contre nous ses forces, qui nous a traqués, qui a conçu le vain projet de nous exterminer, nous voulons l’effacer de sorte qu’il ne reste rien de lui, sur tout le territoire d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Livre-nous sept de ses fils, afin qu’en Gabaon, ville de Saül, nous les exposions au soleil pour le Seigneur; sept fils de Saul, choisis pour le Seigneur. Et le roi dit: Je vous les livrerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Le roi épargna Miphiboseth, fils de Jonathas, fils de Saül, à cause du serment du Seigneur que s’étaient mutuellement prêté Jonathas et David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Mais il prit les deux fils de Respha, fille d’Aïa, qu’elle avait eus de Saül: Hermoni et Miphiboseth, et les cinq fils de Michol, fille de Saül, qu’elle avait eus d’Esdriel, fils de Berzelli, le Moülathite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Et il les remit aux Gabaonites, qui les exposèrent au soleil, sur la montagne, devant le Seigneur, et tous les sept succombèrent ensemble. Ils moururent dans les premiers jours de la moisson, comme on commençait à couper les orges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Et Respha, fille d’Aïa, prit un cilice, et, au commencement de la moisson des orges, elle se plaça près de la roche; elle y demeura jusqu’à ce que l’eau du ciel tombât sur les morts, et elle ne laissa pas les oiseaux du ciel se poser sur eux, pendant le jour, ni les bêtes fauves des champs les atteindre, pendant la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'On alla dire à David ce que faisait Respha, fille d’Aïa, concubine de Saül; puis, on détacha les cadavres; et Dan, fils de Joa, de la race des géants, les prit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Après cela, David partit, et il reprit les ossements de Saül et ceux de Jonathas, aux hommes de Jabès-Galaad qui les avaient dérobés dans les rues de Bethsam, où les Philistins les avaient cloués, le jour de leur victoire sur Saül en Gelboé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Et il rapporta de cette ville les ossements de Saül et ceux de Jonathas, et il recueillit les ossements des sept exposés au soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Et l’on ensevelit tous ces ossements, en Benjamin, sur les flancs de la montagne, dans le sépulcre de Cis, père de Saul; on exécuta tout ce que David avait prescrit, et après cela Dieu exauça les vœux de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Ensuite, la guerre s’alluma encore entre les Philistins et Israël. David se mit en campagne avec ses serviteurs; dans une bataille contre les Philistins, lui-même sortit des rangs, et de l’autre côté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Jesbi, de la race des géants. Celui-ci portait une javeline dont la pointe pesait trois cents sicles d’airain; à sa ceinture pendait une massue, et il pensait tuer David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mais Abessa vint au secours du roi; il frappa le Philistin et il le tua. Alors, les hommes de David jurèrent et dirent: Tu ne viendras plus à la guerre avec nous, de peur que tu n’éteignes la lampe d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Après cela, il y eut encore un combat près de Geth avec les Philistins. Alors, Sebocha, d’Astaroth, tua Seph, de la race des géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Puis, il y eut une bataille à Rhom avec les Philistins, et Éléanan, fils d’Ariorgim de Bethléem, tua Goliath le Géthéen, qui portait une javeline dont le bois ressemblait au mât d’un tisserand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Il y eut encore un combat à Geth. Et il y avait un homme de grande taille, ayant six doigts à chaque main et six doigts à chaque pied, en tout vingt-quatre doigts. Et il était aussi de la race des géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Et il défiait Israël; il fut tué par Jonathas, fils de Sémeï, frère de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Tous les quatre étaient issus des géants, et ils étaient nés à Geth dans la famille de Rhapha, et ils tombèrent sous les coups de David ou de ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Et David chanta ce cantique au Seigneur, le jour où le Seigneur l’eut délivré de Saül et de tous ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Et il dit, en ce cantique: Seigneur, mon rocher, ma forteresse, mon sauveur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Mon Dieu sera mon gardien, je me confierai à lui; mon protecteur, mon salut, mon refuge, vous me sauverez de l’homme inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'J’invoquerai le Seigneur, à qui appartient la louange, et il me délivrera de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Car les brisements de la mort m’ont investi, les torrents de l’iniquité m’ont frappé d’épouvante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Les angoisses de la mort m’ont entouré, l’agonie de la mort a pris l’avance sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Dans mes afflictions j’invoquerai le Seigneur, je crierai à mon Dieu; de son temple, il entendra ma voix, mes cris arriveront à ses oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'La terre a été troublée, et elle a tremblé; les fondements du ciel ont été bouleversés, et ils se sont déchirés, parce que la colère du Seigneur a éclaté contre la terre et le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Dans sa fureur une fumée s’exhale, le feu de sa bouche est dévorant; des charbons en ont été embrasés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Il a abaissé les cieux et il est descendu, et les ténèbres s’étendaient sous ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Et il s’est assis sur les chérubins, et il a pris son essor, et il s’est montré sur les ailes des vents,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Et il s’est voilé de ténèbres. Et autour de lui, comme un tabernacle, il a étendu l’obscurité des eaux, condensées dans les nuées de l’air.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Et les lueurs qui le précédaient ont mis des charbons en feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Le Seigneur a tonné du haut du ciel, le Très-Haut a fait retentir sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Il a lancé des traits et il a dispersé mes ennemis; il a fait tomber la foudre et il les a mis hors d’euxmêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Aux reproches du Seigneur, sous le souffle de sa colère, on a vu les gouffres de la mer, et les bases de la terre ont apparu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Et il a envoyé d’en haut son ange, et il m’a pris, et il m’a tiré du tumulte des eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Il m’a délivré de la force de mes ennemis, de ceux qui me haïssaient et qui l’emportaient sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Les jours de mon affliction s’étaient précipités sur moi; mais le Seigneur a été mon appui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Il m’a conduit dans de libres espaces, et il m’a affranchi, parce qu’il se complaisait en moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Le Seigneur m’a rétribué selon ma justice; il m’a rétribué selon la pureté de mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Parce que j’ai suivi les voies du Seigneur, et que je n’ai point outragé mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Parce que ses jugements et ses justices ont toujours été devant moi, et que je ne m’en suis jamais écarté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Je serai sans tache à ses yeux, et je me tiendrai en garde contre mes déréglements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Le Seigneur me rétribuera selon ma justice, et selon la pureté de mes mains devant ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Avec le saint vous serez saint, avec l’homme accompli vous serez accompli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Avec l’excellent vous serez excellent, avec le méchant vous serez méchant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Vous sauverez le peuple pauvre, et vous ferez baisser les yeux des superbes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Car, ô Seigneur, vous êtes ma lumière, et le Seigneur brillera devant moi dans mes ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Avec votre aide je courrai comme un homme fort; avec l’aide de mon Dieu je franchirai des remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Le Tout-Puissant, ses voies sont irréprochables; la parole du Seigneur est forte, éprouvée par le feu. Le Seigneur abrite tous ceux qui ont foi en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Qui donc est fort, hormis le Seigneur? Qui donc sera créateur, hormis notre Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Le Tout-Puissant, c’est lui qui me fortifie par sa puissance, et qui m’a préparé une voie irréprochable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Il rendu mes pieds légers comme ceux des cerfs; il m’a placé sur les hauts lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Vous avez exercé mes mains aux combats; vous avez brisé par mon bras un arc d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Vous m’avez donné, Seigneur, le bouclier qui me sauve; mon obéissance à vos ordres m’a grandi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'L’espace sous mes pas s’est étendu, et mes jambes ont conservé leur fermeté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Je poursuivrai mes ennemis, et je les effacerai, et je ne reviendrai point qu’ils ne soient anéantis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Je les briserai, et ils ne se relèveront point; ils tomberont sous mes pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Et vous, par votre puissance, vous me fortifierez, Seigneur, pendant la bataille, et vous courberez sous moi ceux qui contre moi se sont levés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Vous m’avez fait voir le dos de mes ennemis, vous avez mis à mort ceux qui me haïssaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Ils n’ont plus de secours; ils crieront au Seigneur, mais le Seigneur ne les exaucera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Je les ai broyés comme de la poussière; je les ai aplatis comme la boue du chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Vous me préserverez, ô Seigneur, des contradictions des peuples; et vous me maintiendrez à la tête des nations; un peuple que je ne connaissais pas m’a été asservi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Les fils des étrangers m’avaient trompé; ils ont ouï votre parole, et ils m’ont été dociles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Les fils des étrangers seront rejetés avec mépris, et ils trébucheront dans leurs places de retraite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Vive le Seigneur! béni soit mon gardien, et Dieu, le gardien de mon salut, sera glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Le Seigneur qui m’a vengé, en châtiant par mon bras les nations, est tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Il m’a tiré de leurs mains; vous m’élèverez encore, ô Seigneur, au-dessus de ceux qui se lèveront contre moi, vous me défendrez contre les hommes violents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'À cause de cela, Seigneur, je vous rendrai gloire parmi toutes les nations, et je chanterai votre nom,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Ô vous, qui rendez grand le salut de votre roi, qui êtes miséricordieux envers David, votre christ, et envers sa postérité à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Voici les dernières paroles de David, du fidèle David, fils de Jessé, de l’homme fidèle que le Seigneur a suscité pour être le christ du Dieu de Jacob, et dont les psaumes ont été agréables au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'L’Esprit du Seigneur m’a parlé, sa parole est sur ma langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Le Dieu d’Israël parle. Le gardien d’Israël me propose une parabole: J’ai fait, dit-il, cette question aux hommes: Comment vous affermirez-vous dans la crainte de l’oint du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Qu’au sein de la lumière matinale de Dieu, ajoutet-il, l’on voie se lever le soleil. La splendeur du Seigneur ne s’efface point; elle naît comme l’herbe des champs naît de la pluie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Ainsi n’est point ma maison devant le Tout-Puissant; mais il a fait avec moi une alliance perpétuelle, toujours efficace, et, en tout temps, observée; et c’est là tout mon salut; tout mon désir est en elle, et les méchants ne fleuriront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Tous sont comme l’épine méprisée que l’on ne prend pas avec la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'L’homme ne se fatiguera pas à son sujet. On y emploiera le fer et le bois de la lance, et elle sera brûlée; eux aussi seront brûlés dans leur opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Voici les noms des hommes vaillants de David: Isboseth le Chananéen, chef de la première triade; Adinon l’Asonien, qui, un jour, tira l’épée contre huit cents hommes à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Après lui, Eléanan, fils de son oncle paternel, fils de Dudi, de l’un des trois vaillants qui accompagnaient David. Un jour, Dudi insulta les Philistins; ils se réunirent pour livrer bataille, Israël s’avança.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Et lui se leva, et tailla en pièces les Philistins jusqu’à ce que sa main fût fatiguée; et sa main ne put se détacher de son glaive. Et le Seigneur, ce jour-là, sauva son peuple d’un grand péril; l’armée revint vers Dudi, et elle n’eut plus qu’à dépouiller les morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Après Eléanan, Samaïa, fils d’Asa, l’Aruchéen. Les Philistins s’étaient rassemblés dans Théria; et il y avait là un champ de lentilles, et devant eux l’armée d’Israël s’était enfuie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Et il demeura comme une colonne au milieu du champ, et il le reprit, et il tailla en pièces les Philistins. Et le Seigneur sauva son peuple d’un grand péril.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Les trois premiers des trente avaient rejoint jadis en Cason David à la caverne d’Odollam, et les Philistins en armes étaient campés dans le val des Géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David se tenait dans sa forteresse, et les Philistins avaient un poste à Bethleemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Et David eut un désir, et il dit: Qui m’apportera à boire de l’eau de la citerne qui est sous la porte de Bethleem? Or, en ce temps-là, le gros des Philistins était à Bethléem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Aussitôt, les trois vaillants s’ouvrirent un passage à travers le camp des Philistins, et ils puisèrent de l’eau dans la citerne sous la porte de Bethléem, et ils l’emportèrent, et ils la présentèrent à David; mais il ne voulut pas la boire, et il en fit une libation au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Et il dit Dieu me préserve d’en rien faire; je croirais boire le sang des hommes qui ont exposé leur vie. Et il ne voulut point boire. Voilà ce qu’avaient fait les trois vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Il y avait encore Abessa, frère de Joab, fils de Sarvia, chef d’une seconde triade; seul, il avait levé sa javeline contre trois cents qui périrent; et il s’était fait un nom parmi les trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Et, dans sa triade, il fut illustre, et il en devint le chef; mais il n’alla pas si loin que ceux de la première triade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Et il y avait Banaïas de Cabeséel, fils de Joad, homme distingué aussi par ses actions; seul, il tua deux fils d’Ariel de Moab; ce fut lui qui descendit dans une citerne, un jour de neige, et qui y tua un lion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Il tua encore un Egyptien de grande taille, et l’Égyptien tenait une javeline haute comme une échelle; il l’attaqua n’ayant qu’un bâton; il la lui arracha, et s’en servit pour le tuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Voilà ce que fit Banaïas, et il avait un nom dans la seconde triade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Et, dans sa triade, il fut illustre; mais il n’alla pas si loin que ceux de la première triade. David le fit son conseiller. Voici les noms des autres hommes vaillants du roi David:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asaël, frère de Joab, l’un des trente; Eléanan, fils de Dudi, de Bethléem, oncle paternel du premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Séma le Rhudéen;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Sellès le Celothi; Iras, fils d’Isca, de Thecoé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiézer l’Anothite, des fils de l’Anothite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Ellon l’Aoïte; Noré le Netophatite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Esthai, fils de Riba, de Gabaeth; Ephratéen, fils de Benjamin; Asmoth le Bardiamite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Emasa le Salabonite; Jonathas, fils d’Asan;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Samnan l’Arodite; Amnan, fils d’Araï le Saraürite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Aliphaleth, fils d’Asbite, fils de Machachachi; Héliab, fils d’Achitophel le Gélonite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Asaraï du Carmel, fils d’Uréoërchi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Gaal, fils de Nathan; Bonni, fils de Galaadi; Héli l’Ammanite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Adroï des torrents;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Gadabiel, fils de l’Arabothaïte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Geloré de Béthoron, qui portait les armes de Joab, fils de Sarvia;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Iras l’Ethéréen; Gérab l’Ethénéen;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urie l’Hettéen: en tout trente-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'La colère du Seigneur s’enflamma encore contre Israël; et il poussa David contre le peuple, en lui disant: Va, et fais le dénombrement d’Israël et de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Et le roi dit à Joab, général de ses troupes, qui était avec lui Parcours toutes les tribus d’Israël et de Juda, depuis Dan jusqu’à Bersabée; fais le recensement du peuple, et j’en saurai le nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab répondit au roi: Puisse le Seigneur Dieu ajouter à ce peuple, et le rendre cent fois aussi nombreux qu’il l’est; puisse le roi mon maître le voir de ses yeux; mais pourquoi le roi mon maître a-t-il formé ce dessein?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Mais la volonté du roi prévalut sur Joab et les autres chefs de l’armée. Joab partit donc avec les chefs des forces qui entouraient David, pour faire le recensement du peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Et ils traversèrent le Jourdain, et ils campèrent dans les champs d’Aroer, à droite de la ville, au milieu de la gorge de Gad et d’Eliézer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Ils allèrent ensuite en Galaad et dans la terre de Thabason, la même qu’Adasaï; ils passèrent par Danidan, par Udan, et ils firent le tour de Sidon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Puis, ils allèrent à Mapsar de Tyr, et dans toutes les villes de l’Evéen et du Chananéen; et ils retournèrent au sud de Juda en Bersabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Et ils parcoururent toute la terre; enfin, ils rentrèrent à Jérusalem au bout de neuf mois et vingt jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Et Joab remit au roi le dénombrement du peuple qu’il avait recensé. Il y avait en Israël huit cent mille hommes dans la force de l’âge, portant l’épée, et en Juda cinq cent mille combattants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Et le cœur de David le tourmenta, après qu’il eut compté le peuple, et il dit au Seigneur: J’ai gravement péché en ce que je viens de faire, ô Seigneur; remettez à votre serviteur son iniquité, car j’ai commis une insigne folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Et David se leva de grand matin, et la parole du Seigneur vint à Gad le voyant, le prophète, et le Seigneur lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Va, et parle à David, disant: Voici ce que dit le Seigneur Je t’apporte trois choses: choisis pour toi l’une d’elles, et tu l’auras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Et Gad entra chez le roi, lui parla, et lui dit: Choisis pour toi ce que tu veux qui arrive; il y aura ou trois années de famine en ta terre, ou trois mois, pendant lesquels tu fuiras devant tes ennemis qui te poursuivront, ou trois jours de mortalité dans ton royaume. Réfléchis, et vois ce que je dois répondre à Celui qui m’envoie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Et David dit à Gad: De toutes parts le choix m’est cruel; mais j’aime mieux me livrer aux mains du Seigneur, parce qu’il a eu souvent compassion de moi; je ne tomberai point dans les mains des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'David choisit donc la mortalité; or, on était au temps de la moisson; et le Seigneur envoya la mort en Israël depuis le point du jour jusqu’à midi; la peste commença à frapper le peuple, et, de Dan à Bersabée, soixante-dix mille hommes périrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Et l’ange de Dieu étendit la main sur Jérusalem pour la détruire; mais le Seigneur eut compassion de ses maux, et il dit à l’ange exterminateur qui détruisait le peuple: C’est assez, arrête ta main. Or, l’ange du Seigneur était auprès de l’aire d’Orna le Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'David, quand il vit l’ange du Seigneur frapper le peuple, parla au Seigneur, et lui dit Me voici, c’est moi qui ai péché; mais ces brebis qu’ont-elles fait? Que votre main soit contre moi et contre la maison de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Et ce jour-là, Gad vint à David, et il lui dit: Lèvetoi, et dresse un autel au Seigneur dans l’aire d’Orna le Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Et David se leva, comme le lui prescrivait Gad, et comme à Gad l’avait prescrit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Orna était penché à sa fenêtre, et voyant le roi qui venait à lui avec ses serviteurs, il sortit, se prosterna devant le roi la face contre terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Et dit: Pourquoi le roi mon maître est-il venu chez son serviteur? David répondit: C’est pour t’acheter ton aire, et y bâtir un autel au Seigneur, afin que cette peste cesse d’atteindre le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Et Orna dit à David: Que le roi mon maître prenne et consacre ce que bon lui semble; voici mes bœufs pour l’holocauste; les jougs et le chariot serviront à les brûler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Ainsi, Orna donna tout au roi, et il lui dit: Que le Seigneur ton Dieu te bénisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Mais le roi repartit: Je n’accepte point, je t’achèterai ce que tu m’offres, moyennant un bon prix; je ne présenterai point au Seigneur un holocauste qui ne me coûte rien. Et David acheta l’aire avec les boeufs cinquante sicles d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Aussitôt, David bâtit l’autel au Seigneur; puis, il y offrit des holocaustes et des hosties pacifiques. Salomon embellit plus tard l’autel, qui était d’abord fort petit. Pour le moment, le Seigneur exauça les vœux de la terre, et la peste cessa en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Et le roi David était vieux, ayant vécu bien des jours; on l’entourait de vêtements, et il n’était point réchauffé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Ses serviteurs dirent alors: Que l’on cherche pour le roi une jeune vierge; elle se tiendra à ses côtés, elle le réchauffera, elle dormira avec lui, et le roi notre maître sera réchauffé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Et, ayant cherché, sur tout le territoire d’Israël, une fille belle et jeune, ils trouvèrent Abisag la Sunamite, et ils l’emmenèrent au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'La jeune fille était merveilleusement belle, et elle réchauffait le roi, elle le servait; mais le roi ne la connut point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Or, Adonias, fils d’Aggith, s’enorgueillit, et il dit: Je régnerai. Il se procura des chars, des cavaliers, et cinquante hommes pour courir devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Et son père n’y mit point obstacle, en lui disant: Pourquoi fais-tu cela? Il était extrêmement beau, et sa mère l’avait enfanté aprè s’Absalon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Ses confidents furent Joab, fils de Sarvia, et Abiathar le prêtre, qui se mirent du parti d’Adonias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mais Sadoc le prêtre, Banaïas, fils de Joïada, Nathan le prophète, Sémeï, Rhési, les vaillants de David, ne suivirent point Adonias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Et Adonias sacrifia des brebis, des bœufs et des agneaux, près de la pierre de Zoéléthi, qui tient à la fontaine de Rhogel, et il convia tous ses frères et tous les forts de Juda, serviteurs de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Mais il n’invita ni Nathan le prophète, ni Banaïas, ni les vaillants, ni Salomon son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Et Nathan dit à Bethsabée, mère de Salomon: Ne sais-tu point qu’Adonias, fils d’Aggith, est proclamé roi? Est-ce que David notre seigneur l’ignore?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Maintenant donc, viens, et je te donnerai un conseil sauve ta vie, sauve la vie de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Viens, entre chez le roi, et dis-lui: 0 roi mon maître, n’as-tu pas juré à ta servante qu’après toi ton fils Salomon règnerait et qu’il s’assiérait sur ton trône? Pourquoi donc Adonias est-il proclamé roi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Pendant que tu parleras encore au roi, j’arriverai à ta suite, et je complèterai ton discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Et Bethsabée entra chez le roi dans sa chambre à coucher; le roi était bien vieux, et Abisag la Sunamite était à servir le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Bethsabée se prosterna pour saluer le roi, et le roi lui dit: Qu’as-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Seigneur, répondit-elle, tu as juré à ta servante au nom du Seigneur ton Dieu, et tu lui as dit: Après moi, ton fils Salomon régnera; il s’assiéra sur mon trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Et maintenant, voici qu’Adonias est proclamé roi, et toi, ô roi mon maître, tu l’ignores.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Il a sacrifié à profusion des bœufs, des agneaux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Cependant, ô roi mon maître, les yeux de tout Israël sont dirigés sur toi; déclare-leur donc qui, après toi, s’assiéra sur le trône du roi mon maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Sans cela, dès que le roi mon maître se sera endormi avec ses pères, moi et mon fils Salomon nous serons des criminels.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Elle parlait encore au roi, quand Nathan le prophète survint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Et l’on vint dire au roi: Voici Nathan le prophète; il fut introduit en présence du roi, et il salua le roi la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Et Nathan dit: 0 roi mon maître, as-tu dit: Adonias, après moi, règnera, et il s’assiéra sur mon trône?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Car il est parti aujourd’hui même; il a sacrifié à profusion des bœufs, des agneaux et des brebis; il a convié tous les fils du roi, les chefs de l’armée et le prêtre Abiathar, qui sont avec lui à manger et à boire, et ils ont crié Vive le roi Adonias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mais il n’a point invité moi ton serviteur, ni Sadoc le prêtre, ni Banaïas, fils de Joïada, ni Salomon ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Est-ce arrivé par la volonté du roi mon maître, qui n’a point voulu faire connaître à ses serviteurs celui qui s’assiérait sur le trône du roi mon maître après lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Et le roi David s’écria: Rappelez Bethsabée; et elle rentra devant le roi, et elle se tint debout devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Alors, le roi prêta serment, et dit: Aussi vrai que vit le Seigneur, qui a délivré mon âme de toute tribulation,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Ce que je t’ai juré au nom du Seigneur Dieu d’Israël, quand j’ai dit: Salomon, ton fils, règnera après');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Et Bethsabée se prosterna la face contre terre pour saluer le roi, et elle s’écria: Vive à jamais David le roi mon maître!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Et le roi David dit: Faites-moi venir Sadoc le prêtre, Nathan le prophète, et Banaïas, fils de Joïada; et ils entrèrent devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Et le roi leur dit: Prenez avec vous les serviteurs de votre maître, placez mon fils Salomon sur ma mule, et conduisez-le à la fontaine de Gihon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Là, que Sadoc le prêtre, et Nathan le prophète, le sacrent roi d’Israël; après cela, sonnez du cor, et criez: Vive le roi Salomon!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Il s’assiéra sur mon trône, et il règnera à ma place; car c’est moi qui ai commandé qu’il règne sur Israël et sur Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Et Banaïas, fils de Joïada, dit à David: Ainsi soit-il; que le Seigneur Dieu du roi mon maître confirme sa parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Que le Seigneur soit avec Salomon comme il a été avec le roi mon maître; qu’il élève son trône au-dessus du trône du roi mon maître David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Et Sadoc le prêtre partit avec Nathan le prophète, Banaïas, fils de Joïada, Chéléthi et Phéléthi; ils firent monter Salomon sur la mule du roi, et ils le conduisirent à la fontaine de Gihon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Sadoc avait pris dans le tabernacle la corne d’huile, et il sacra Salomon; puis, il sonna du cor, et tout le peuple cria: Vive le roi Salomon!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Et tout le peuple revint à sa suite; il forma des chœurs de danse, il montra une très-grande allégresse, et la terre à ses cris fut ébranlée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Adonias l’entendit ainsi que tous ses convives qui achevaient de manger. Joab distingua le son du cor, et il dit: Quel est ce son qui nous vient de la ville?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Il parlait encore, quand survint Jonathas, fils d’Abiathar le prêtre, et Adonias lui dit: Entre, tu es un homme vaillant, et tu nous apportes de bonnes nouvelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Mais Jonathas répondit et il dit: Assurément, car le roi notre maître a proclamé roi Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Et il a envoyé avec lui Sadoc le prêtre, et Nathan le prophète, Banaïas, fils de Joïada, Chéléthi et Phéléthi; et ils l’ont fait monter sur la mule du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Ensuite, Sadoc le prêtre, et Nathan le prophète, l’ont sacré vers la fontaine de Gihon. Le peuple les suit avec joie, et la ville en retentit; c’est le bruit que vous avez entendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Salomon est assis sur le trône du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Et les serviteurs du roi sont entrés pour bénir le roi notre maître David, disant: Puisse le Seigneur rendre illustre le nom du roi Salomon, plus encore que ton nom! puisse-t-il élever son trône au-dessus de ton trône! Et pendant qu’ils parlaient, le roi sur son lit adorait le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Puis, le roi a ainsi parlé: Béni soit le Seigneur Dieu d’Israël, qui m’accorde aujourd’hui qu’un fils de mon sang soit assis sur mon trône, comme je le vois de mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Les convives d’Adonias furent hors d’eux-mêmes, et chacun s’en retourna en sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Et Adonias eut crainte de se présenter devant Salomon; s’étant levé, il partit, et il embrassa la corne de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'On en informa Salomon, à qui l’on dit: Voilà que ton frère Adonias redoute le roi Salomon; il a embrassé la corne de l’autel, et il dit: Que Salomon me jure aujourd’hui qu’il ne fera point périr par l’épée son serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Et Salomon dit: Qu’il soit un homme vaillant, et pas un cheveu ne tombera de sa tête; mais si l’on découvre en lui quelque méchanceté, il mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Et Salomon envoya des hommes pour le retirer de l’autel; il fut introduit, et il se prosterna devant le roi Salomon, et son frère lui dit: Retourne en ta demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Le jour où David allait mourir était proche; et il parla à son fils Salomon en ces termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Je m’en vais dans la voie de toute la terre; quant à toi, sois fort et agis en homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Observe les commandements du Seigneur ton Dieu, afin de marcher dans ses voies, de garder ses commandements, sa justice, ses jugements, et les préceptes qui sont écrits en la loi de Moïse; conduis-toi sagement en toutes choses, comme je te l’ai prescrit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Afin que le Seigneur confirme la parole qu’il a dite Si tes fils sont attentifs à suivre leur voie, devant moi, dans la vérité et de tout leur cœur, jamais il ne manquera d’homme issu de toi pour monter sur le trône d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Or, tu sais ce que m’a fait Joab, fils de Sarvia; tu sais comment il a traité les deux chefs de l’armée d’Israël: Abner, fils de Ner, et Amessaï, fils de Jéther. Il les a tués; le sang, réservé au combat, il l’a fait couler pendant la paix; il a versé le sang innocent sur la ceinture qui ceignait ses reins, et sur les sandales qui chaussaient ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tu feras ce que t’inspirera ta sagesse, et tu ne laisseras pas sa vieillesse descendre en paix au tombeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Et tu seras bienveillant pour les fils de Berzelli le Galaadite; ils seront de ceux qui mangeront à ta table, car c’est ainsi qu’ils ont agi envers moi quand je fuyais devant Absalon ton frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Tu vois avec toi Sémeï, fils de Géra, de la famille de Jémini de Bathurim; c’est lui qui m’a poursuivi de malédictions bien amères, le jour où je m’en allais au camp; à mon retour, il est venu à ma rencontre vers le Jourdain; je lui ai alors prêté serment au nom du Seigneur, et j’ai dit: Je ne te ferai point mourir par l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Tu ne l’innocenteras point, car tu es un homme sage; tu sauras comment le traiter, et tu feras descendre sa vieillesse au tombeau dans le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Et David s’endormit avec ses pères, et il fut enseveli dans la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Les jours du règne de David sur Israël formèrent quarante ans; il régna sept ans à Hébron et trente-trois ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Et Salomon s’assit sur le trône de David son père, et son règne était parfaitement préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Ensuite, Adonias, fils d’Aggith, entra chez Bethsabée, mère de Salomon; il se prosterna devant elle, et elle lui dit En entrant, nous apportes-tu la paix? Et il répondit: La paix;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'J’ai à te dire un mot. Parle, reprit-elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Tu sais, lui dit-il, que la royauté m’appartenait, et que tout Israël avait jeté les yeux sur moi pour que je régnasse; mais la royauté a été détournée de moi, et elle a passé à mon frère, parce que telle était la volonté du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Maintenant, j’ai à te faire une seule demande; ne détourne pas de moi ton visage. Et Bethsabée lui dit: Parle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Et il continua: Parle au roi Salomon; car il ne détournera pas de toi son visage; qu’il me donne pour femme Abisag la Sunamite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'À quoi Bethsabée reprit: Bien; je parlerai au roi en ta faveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Bethsabée alla trouver le roi Salomon, afin de lui parler en faveur d’Adonias. Le roi se leva, alla au-devant d’elle, la baisa et s’assit sur son trône; puis on plaça un trône pour la mère du roi, et elle s’assit à sa droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Et elle lui dit: J’ai à te faire une petite demande; ne repousse pas mon visage. Et le roi répondit: Demande, ma mère, et je ne te repousserai point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Et elle dit: Que la Sunamite Abisag soit donnée pour femme à ton frère Adonias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Le roi Salomon répondit, et il dit à sa mère: Pourquoi as-tu demandé Abisag pour Adonias? Demande aussi pour lui la royauté, car il est mon frère, il est plus âgé que moi, et il a pour compagnon Abiathar le prêtre, et Joab, fils de Sarvia, général en chef.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Et le roi jura au nom du Seigneur, disant: Que le Seigneur me punisse, et qu’il me punisse encore, si, en faisant cette demande, Adonias n’a pas parlé contre sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Maintenant, vive le Seigneur qui m’a préparé, qui m’a placé sur le trône de David mon père, qui a établi ma maison comme il l’avait promis! aujourd’hui même Adonias mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Salomon confia l’exécution de ce dessein à Banaïas, fils de Joïada. Celui-ci tua Adonias, qui mourut le jour même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Et le roi dit à Abiathar le prêtre: Retourne vite à ton champ en Astaroth, car tu es, en ce jour-ci, un homme digne de mort; toutefois, je ne te ferai point périr, parce que tu as porté devant mon père l’arche de l’alliance du Seigneur, et que tu as souffert en tout ce qu’a souffert David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Et Salomon interdit le sacerdoce à Abiathar, pour que s’accomplit la parole que le Seigneur avait prononcée contre la maison d’Héli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'La nouvelle en arriva jusqu’à Joab, fils de Sarvia; or, Joab avait été l’un des convives d’Adonias, et il ne s’était point rapproché de Salomon. Joab se réfugia dans le tabernacle du Seigneur, et il embrassa la corne de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Et l’on vint l’annoncer au roi Salomon; on lui dit: Joab s’est réfugié dans le tabernacle du Seigneur, et le voilà qui tient la corne de l’autel. Aussitôt, Salomon envoya auprès de Joab, et il lui dit: Que t’arrive-t-il, pour que tu te réfugies à l’autel? Joab répondit: J’ai eu crainte de toi, et je me suis réfugié auprès du Seigneur. Et Salomon envoya Banaïas, fils de Joïada, disant: Va, tue-le, et ensevelis-le.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Banaïas, fils de Joïada, alla trouver Joab dans le tabernacle du Seigneur, et il lui dit: Voici ce que dit le roi: Sors; mais Joab répondit: Je ne sortirai point, c’est ici que je mourrai. Banaïas retourna chez le roi, et il lui dit: Voici ce que j’ai dit à Joab, voici ce qu’il m’a répondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Le roi reprit: Va et fais-lui comme il a dit: Tuele, ensevelis - le, et tu auras aujourd’hui détourné de moi et de la maison de mon père le sang que Joab a versé sans motif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Le Seigneur a ramené sur sa tête le sang de son iniquité, car il est allé à la rencontre de deux hommes plus justes et meilleurs que lui; il les a fait périr par le glaive, et mon père David ne savait rien du meurtre d’Abner, fils de Ner, général en chef d’Israël, ni du meurtre d’Amessaï, fils de Jéther, général en chef de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Leur sang est retombé sur sa tête, et sur la tête de sa postérité à jamais. Que la paix du Seigneur soit toujours avec David, avec sa race, avec sa maison et avec son trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Et Banaïas, fils de Joïada, alla retrouver Joab; il le tua, et il l’inhuma dans sa maison près du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Le roi, à sa place, donna le commandement de l’armée à Banaïas, et la royauté fut affermie dans Jérusalem. Sadoc fut premier prêtre à la place d’Abiathar. Et Salomon, fils de David, régna en Jérusalem sur Israël et sur Juda; le Seigneur doua Salomon d’une grande intelligence, d’une grande sagesse et d’une richesse de cœur plus abondante que le sable du rivage de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Et le roi appela Semei, et il lui dit: Bâtis pour toi une maison dans Jérusalem, demeures-y, et de là tu n’iras en aucun lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Le jour où tu en sortirais, où tu passerais le torrent de Cédron, sache-le bien, tu mourrais de mort; et ton sang retomberait sur ta tête. Et le roi, ce jour-là, lui fit prêter serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Ensuite, Sémeï dit au roi: La parole que tu as dite est bonne, ô roi mon maître, ainsi fera ton serviteur. Et Sémeï demeura trois ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Après trois ans, deux serviteurs de Sémeï s’enfuirent chez Achis, fils de Maacha, roi de Geth. On l’apprit à Sémeï en lui disant: Voilà tes serviteurs à Geth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Et Sémeï se leva, bâta son ânesse et,’en alla chez Achis à Geth, pour réclamer ses deux serviteurs; puis il revint, et les ramena de Geth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Or, on l’apprit à Salomon en lui disant: Sémeï est allé de Jérusalem à Geth, et il a ramené ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Aussitôt, le roi envoya querir Sémeï, et il lui dit: Ne t’ai-je point fait prêter serment par le Seigneur, ne t’ai-je pas attesté, disant: Le jour où tu sortiras de Jérusalem, où tu iras à droite ou à gauche, sache-le bien, tu mourras?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Pourquoi n’as-tu point gardé le serment du Seigneur, et le commandement que je t’avais donné?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Et le roi ajouta: Tu connais, ton cœur sait tout le mal que tu as fait à David mon père; le Seigneur a fait retomber ta méchanceté sur ta tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Cependant, Salomon est béni, et le trône de David est affermi devant le Seigneur à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Et le roi donna ses ordres à Banaïas, fils de Joïada, qui sortit avec Sémeï et le tua. Le roi Salomon était doué d’une grande intelligence et d’une grande sagesse. Israël et Juda, aussi nombreux que le sable du rivage de la mer, mangeaient, buvaient et se réjouissaient. Et Salomon était chef dans tous les royaumes; ils lui apportaient des présents; et ils lui furent asservis aussi longtemps qu’il vécut. Salomon le premier s’ouvrit les principautés du Liban; il bâtit Thermé (Palmyre), dans le désert. Or, voici quel était le déjeuner de Salomon Trente mesures de fleur de farine, soixante mesures de farine pétrie, dix veaux choisis, vingt bœufs pris au pâturage, cent brebis, et, en outre, des cerfs, des daims et les meilleurs oiseaux des champs. Il était chef de toute la contrée, de ce côté de l’Euphrate, depuis Raphi jusqu’à Gaza, et de tous les rois en deçà du fleuve. Et la paix régnait tout alentour de ses territoires; Juda et Israël demeuraient avec confiance chacun sous sa vigne et son figuier, mangeant et buvant, célébrant leurs fêtes, depuis Dan jusqu’à Bersabée, tout le temps de la vie de Salomon. Or voici les chefs de Salomon: d’abord Azarias, fils de Sadoc, le prêtre; et Ornia, fils de Nathan, chef de ceux qui se tenaient près du roi; ensuite à la tête de sa maison venaient: Suba, scribe; Baza, fils d’Achithalam, gardien des actes publics; Abi, fils de Joab, général en chef; Achire, fils d’Edraï, intendant des transports; Banaïas, fils de Joïada, grand maître du palais et des bâtiments; Cachur, fils de Nathan, conseiller. Et Salomon avait quarante mille cavales pour ses chars et douze mille étalons; il était chef de tous les rois depuis le fleuve jusqu’au territoire des Philistins et jusqu’aux frontières de l’Égypte. Et Salomon, fils de David, régnait en Jérusalem sur Israël et sur Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 47, '');
