INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 57, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 58, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 59, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 60, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 61, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 62, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 63, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 64, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 65, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 66, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 67, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 68, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 69, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 70, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 71, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, '-');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Mais le peuple sacrifiait encore sur les hauts lieux, parce que le temple du Seigneur n’était pas encore bâti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Or, Salomon aimait le Seigneur, et marchait en la voie des commandements du roi David son père; seulement il sacrifiait et encensait sur les hauts lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Et il partit pour Gabaon, afin d’y offrir un sacrifice; car c’était le lieu le plus élevé et le plus célèbre. Salomon offrit en holocauste mille victimes sur l’autel de Gabaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Et la nuit venue, le Seigneur apparut à Salomon pendant son sommeil, et le Seigneur lui dit: Demande-moi quelque chose pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Et Salomon répondit: Vous avez usé d’une grande miséricorde envers mon père David votre serviteur, parce qu’il avait marché devant vous dans les voies de la vérité et de la justice, et dans la droiture du cœur. Et gardant envers lui cette grande miséricorde, vous avez fait monter son fils sur le trône où il est aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Vous venez, Seigneur mon Dieu, de mettre à la place de David mon père, moi votre serviteur, moi qui suis encore un jeune adolescent, et qui ne sais encore ni entrer, ni sortir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Et votre serviteur se trouve au milieu de votre peuple, du peuple nombreux que vous vous êtes choisi, d’un peuple innombrable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Donnez donc à votre serviteur un cœur qui écoute, qui juge votre peuple selon la justice, et qui sache discerner le bien et le mal; car qui pourrait juger votre peuple, ce peuple puissant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Et il fut agréable au Seigneur que Salomon eût fait cette demande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Et le Seigneur lui dit: Parce que tu m’as demandé cette chose, et que tu ne m’as pas demandé pour toi de longs jours, que tu ne m’as pas demandé des richesses, que tu ne m’as pas demandé la mort de tes ennemis, mais que tu m’as demandé pour toi la sagesse, afin de discerner ce qui est juste,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, '(12) J’ai déjà fait selon ta parole: voilà que je t’ai doué d’un cœur prudent et sage; il n’a existé avant toi personne qui te ressemble, et après toi, on ne verra jamais ton semblable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, '(13) Je t’ai donné, en outre, ce que tu n’as pas demandé, la richesse et la gloire, au point que nul des rois ne t’a jamais égalé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, '(14) Si tu marches en ma voie comme a marché David ton père, en gardant mes commandements et mes ordonnances, je t’accorderai, de plus, de longs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, '(15) Et Salomon s’éveilla, et il n’oublia point ce songe; il se leva, et rentra dans Jérusalem; il se plaça debout devant l’autel et devant l’arche du Seigneur en Sion; puis, il sacrifia des holocaustes et des hosties pacifiques; enfin il fit préparer un grand festin pour lui-même et pour tous ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, '(16) Alors, deux femmes prostituées apparurent en présence du roi, et elles se tinrent debout devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, '(17) L’une des deux femmes dit: Je te prie, Seigneur Moi et cette femme nous habitons la même maison, et dans cette maison nous avons enfanté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 29, '(18) Trois jours après que je fus accouchée, cette femme est accouchée aussi; nous étions ensemble, et il n’y avait personne que nous deux dans la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 30, '(19) Or, l’enfant de cette femme est mort la nuit dernière, parce qu’elle s’était couchée sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 31, '(20) Et elle s’est levée au milieu de la nuit; et elle a pris mon enfant dans mes bras, et elle l’a mis en son sein; et son fils mort elle l’a placé en mon sein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 32, '(21) Je me suis réveillée de grand matin pour allaiter mon fils, et l’enfant était mort; or, comme je le regardais bien attentivement aux premières lueurs du jour, je vis que ce n’était pas le fils que j’avais enfanté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 33, '(22) L’autre femme s’écria: Du tout, mais mon fils est vivant, c’est ton fils qui est mort. Et elles parlaient ainsi devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 34, '(23) Et le roi dit à l’une: Tu dis: Celui-ci, le vivant, est mon fils, et le fils de cette femme est mort; puis il dit à l’autre: Tu dis: Du tout, mais mon fils est vivant, et c’est ton fils qui est mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 35, '(24) Et le roi ajouta: Que l’on prenne un glaive. Et l’on apporta un glaive devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 36, '(25) Et le roi dit: Coupez en deux cet enfant vivant qui est à la mamelle, donnez-en la moitié à celle-ci, la moitié à celle-là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 37, '(26) Et la femme à qui était l’enfant vivant se hâta de parler au roi, car ses entrailles étaient troublées à cause de son fils, et elle dit: Je te prie, Seigneur, qu’on lui donne l’enfant, qu’on ne le fasse pas mourir. Mais l’autre dit: Qu’il ne soit ni pour elle, ni pour moi, partagez-le.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 38, '(27) Et le roi prit la parole, et il dit: Donnez l’enfant à celle qui a dit: Donnez-lui l’enfant, ne le faites pas mourir; celle-là est sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 39, '(28) Et tout Israël ouït le jugement qu’avait rendu le roi, et ils eurent crainte du roi, car ils virent');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Salomon régnait donc sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Et voici les chefs qui étaient avec lui: Azarias, fils de Sadoc;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Eliaph et Achia, fils de Séba, scribes; Josaphath, fils d’Achilud, gardien des actes publics.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Banaïas, fils de Joïada, général de l’armée; Sadoc et Abiathar, prêtres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Ornia, fils de Nathan, chef de ceux qui se tenaient près du roi, et Zabuth, fils de Nathan, ami du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Achisar était économe, et Eliac économe; Eliab, fils de Saph, était chef des tribus, et Adoniram, fils d’Audon, intendant des impôts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Et Salomon avait douze officiers sur tout Israël, pour approvisionner le roi et toute sa maison; chaque tribu faisait l’approvisionnement d’un mois par année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Voici leurs noms: Béen, fils de Or, en la montagne d’Ephraïm; le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Ben-Dacar, à Macès, à Salabin, à Bethsamys et à Elon, jusqu’à Géthanan; le second.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ben-Esdi en Araboth, Socho et tout le territoire d’Opher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben-Aminadab avait tout Nephthador; il avait épousé Téphath, fille de Salomon; encore un.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Bana, fils d’Achilud, avait Ithaanach, Mageddo et toute la maison de Dan, vers Saséthan sous Esraé, et le territoire depuis Bethsan jusqu’à Sabelmaüla, et jusqu’à Maèber-Lucam; encore un.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ben-Naber était à Rhaboth-Galaad, et avait tout le territoire d’Ergab en Basan, soixante villes grandes et fortes avec des verrous d’airain; encore un.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Achinadab, fils de Saddo, avait Manaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaas était en Nephthali; celui-ci avait épousé Basemmath, fille de Salomon; encore un.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baanan, fils de Chusi, était en Aser et en Baaloth;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Sémeï, fils d’Ela en Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, '(19) Gaber, fils d’Adaï, en la terre de Gad, de Séhon, roi d’Esebon, et de Og, roi de Basan, et il était Naseph (Nasib) en la terre de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, '(17) Josaphat, fils de Phuasud, en Issachar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, '(27) Ainsi, les officiers approvisionnaient le roi Salomon, et chacun avait son mois pour subvenir à ce qui était demandé pour sa table; et ils n’intervertissaient jamais l’ordre établi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, '(28) Ils faisaient transporter l’orge et la paille pour les chevaux de selle et les attelages du roi, en tout lieu où il se trouvait, chacun selon ce qui lui était prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Et voici ce qu’il fallait chaque jour à Salomon: trente mesures de fleur de farine, et soixante mesures de farine pétrie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Dix veaux choisis, vingt bœufs pris au pâturage, et cent brebis, et en outre des cerfs, des chevreuils parqués et engraissés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Car il était chef de toute la contrée en deçà de l’Euphrate, et la paix régnait tout alentour de ses territoires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, '(29) Et le Seigneur avait doué Salomon d’une grande intelligence, d’une grande sagesse, et d’une richesse de cœur abondante comme le sable du rivage de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, '(30) La sagesse de Salomon s’accrut et surpassa celle des anciens, celle de tous les sages de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, '(31) Et il était le plus sage des hommes; il était plus sage que Géthan le Zarite, qu’Enan, que Chalcad et que Darala, fils de Mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, '(32) Et il dit trois mille proverbes et cinq mille cantiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, '(33) Et il disserta sur tous les arbres, depuis le cèdre du Liban jusqu’à l’hysope qui sort des murailles; il parla de tous les quadrupèdes, de tous les oiseaux, de tous les reptiles et de tous les poissons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, '(34) Et tous les peuples venaient pour entendre la sagesse de Salomon; et combien y eut-il de rois de la terre qui vinrent entendre la sagesse de Salomon! Et Salomon avait épousé la fille du Pharaon d’Égypte; il l’avait amenée dans la ville de David, en attendant qu’il eût achevé le temple du Seigneur, ainsi que son propre palais et les remparts de Jérusalem. Alors, le Pharaon vint d’Égypte; il prit Gazer et il la livra aux flammes; il extermina le Chananéen qui habitait Mergab, et il donna ces conquêtes à sa fille, femme de Salomon, et Salomon rebâtit Gazer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Et Hiram, roi de Tyr, envoya ses serviteurs, sachant que Salomon avait été oint à la place de David, son père; car Hiram avait aimé David tous les jours de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Salomon envoya aussi des messagers à Hiram, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Tu sais que David, mon père, n’a pu bâtir un temple au nom du Seigneur mon Dieu, à cause des guerres qui ont');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Maintenant, le Seigneur mon Dieu m’a donné la paix tout alentour; il n’est point de complot contre moi ni de mauvais desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Et voilà que j’ai résolu de bâtir un temple au nom du Seigneur mon Dieu, comme le Seigneur Dieu l’a dit à David mon père: C’est ton fils, que je mettrai sur le trône à ta place, qui bâtira un temple à mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Donne donc tes ordres, et que l’on coupe des arbres du Liban; voici mes serviteurs pour aider les tiens, et je te paierai le salaire de tes services comme tu le demanderas; car tu sais que parmi nous personne n’est aussi habile que les Sidoniens à travailler le bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Or, Hiram fut grandement réjoui d’entendre ces paroles, et il dit: Béni soit aujourd’hui le Seigneur, qui a donné à David un fils aussi sage pour gouverner ce peuple nombreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Puis, il envoya dire à Salomon: J’ai ouï toutes les choses au sujet desquelles tu as envoyé près de moi; je ferai tout ce que tu veux; cèdres et sapins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Mes serviteurs transporteront tout du Liban à la mer; on en formera des radeaux jusqu’au lieu que tu m’indiqueras; là, je les ferai délier, et tu les enlèveras, et tu feras tout ce que je désire en donnant des vivres à ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Hiram donna donc à Salomon des cèdres, des sapins et tout ce qu’il voulut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Et Salomon donna à Hiram vingt mille mesures de froment pour alimenter sa maison, et vingt mille me sures d’huile battue; voilà ce que Salomon donna par an à Hiram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Or, le Seigneur avait donné à Salomon la sagesse comme il le lui avait dit. Et la paix régnait entre Hiram et Salomon, qui contractèrent entre eux une alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Le roi imposa une corvée à tout Israël, et il requit pour ce service trente mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Il les fit partir pour le Liban, dix mille par dix mille qui se relevaient mois par mois; ils passaient un mois au Liban et deux mois chez eux. Adoniram était à leur tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Et Salomon employait soixante-dix mille hommes à transporter les matériaux, et quatre-vingt mille à tailler des pierres dans la montagne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Sans compter les conducteurs des travaux; il y en avait trois mille six cents habiles à ces sortes d’œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Et l’on mit trois ans à préparer les pierres et les bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Ce fut en l’an quatre cent quarante de la sortie d’Égypte, pendant le second mois de la quatrième année du règne de Salomon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, '(17) Que le roi donna l’ordre de prendre des pierres, grandes et chères, pour les fondations du temple, et des pierres parfaitement taillées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, '(18) Les fils de Salomon et les fils d’Hiram les taillèrent et les transportèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, '(37) En la quatrième année on jeta les fondements du temple du Seigneur, pendant le mois de Zin, le second mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, '(38) En la onzième année du règne de Salomon, pendant le mois de Baal, le huitième mois, le temple fut achevé, selon sa destination et selon les plans arrêtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, '(2) Le temple que le roi bâtit au Seigneur avait quarante coudées de long, vingt de large et vingt-cinq d’élévation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, '(3) Le vestibule, sur la façade de l’édifice, était long de vingt coudées, la largeur même du temple en sa façade. Et le roi bâtit le temple, et il l’acheva.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, '(4) Il fit au temple des fenêtres inclinées et cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, '(5) Il fit, contre les murs du temple, des étages qui entouraient le temple et l’oracle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, '(6) L’étage inférieur avait cinq coudées de large; celui du milieu six, le troisième sept; il les sépara extérieurement du temple tout alentour, pour que cette construction ne s’engageât pas dans le mur du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, '(7) Le temple fut bâti en pierres blanches taillées à angles droits; et, pendant qu’on l’élevait, on n’entendit dans le temple ni le marteau, ni la hache, ni aucun outil de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '(8) Le porche de l’étage inférieur était sous l’aile droite du temple; un escalier tournant menait au milieu; et, du milieu, au troisième étage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, '(9) Salomon bâtit ainsi le temple; il l’acheva, et il le lambrissa de cèdre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, '(10) Il éleva tout le long du temple des panneaux, ayant chacun cinq coudées de hauteur, et il les maintint dans des cadres de bois de cèdre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Il fit ainsi en bois de cèdre le dedans du temple, depuis le sol jusqu’au haut des murs et jusqu’aux solives; il revêtit l’intérieur de lambris de bois, et il fit tout alentour une corniche de sapin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Il éleva une cloison de vingt coudées depuis le sol du temple jusqu’aux solives; au delà de cette cloison étaient l’oracle et le Saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Et la nef avait quarante coudées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, '(19) Jusqu’à la cloison qui la séparait de l’oracle, où devait être renfermée l’arche de l’alliance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, '(20) Or, cet oracle avait vingt coudées de long, vingt coudées de large, vingt coudées de haut, et il le revêtit de lames d’or. Et il fit devant l’oracle l’autel du Seigneur et il le revêtit d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, '(21) Il revêtit d’or tout le temple en toutes ses parties.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, '(23) Il fit dans l’oracle deux chérubins de la taille de dix coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, '(24) L’un avait des ailes de cinq coudées, et le second avait des ailes de cinq coudées; de la naissance d’une aile à la naissance de l’autre, il y avait dix coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, '(25) Le second était semblable au premier, et ils avaient l’un et l’autre les mêmes dimensions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, '(25) L’un des deux chérubins était d’une taille de dix coudées, et l’autre pareillement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, '(27) Et les deux chérubins étaient placés au milieu du temple intérieur, et ils ouvraient les ailes; l’extrémité de l’aile de l’un touchait à l’un des murs, l’extrémité de l’aile de l’autre touchait au mur opposé; au milieu du temple, les deux autres ailes de chacun se rejoignaient par leurs extrémités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, '(28) Le roi revêtit d’or les chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, '(29) Il fit, sur tous les murs autour du temple, des ciselures, œuvre variée, et il sculpta des palmes intérieurement et extérieurement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, '(30) Il revêtit d’or le plancher du temple au dedans et au dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, '(31) A l’entrée de l’oracle, il posa des portes de bois de genièvre, avec des pilastres à quatre faces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, '(34) Les deux portes du temple étaient en sapin; l’un des battants avait deux feuilles avec des gonds; l’autre avait aussi deux feuilles avec des gonds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, '(35) Ils étaient ornés de chérubins et de palmes aux feuilles déployées, et les saillies étaient revêtues d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, '(36) Il bâtit le parvis intérieur: trois assises de pierres de taille, et tout alentour un lambris de cèdre. Et il plaça parallèlement à la façade du temple le voile du parvis du vestibule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, '(13) Le roi Salomon envoya demander et obtint Hiram de Tyr,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, '(14) Fils d’une femme veuve, issu de la tribu de Nephthali. Son père était un Tyrien, forgeron plein d’art, d’intelligence et d’habileté pour faire toutes sortes d’ouvrages d’airain; quand on l’eut amené au roi Salomon, il lui fit tous ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, '(15) Il jeta en fonte les deux colonnes du vestibule du temple, chacune haute de dix-huit coudées, ayant quatorze coudées de périmètre et des cannelures de quatre doigts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, '(1) Il jeta en fonte, pour les colonnes, deux chapiteaux, ayant chacun cinq coudées de haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, '(17) Il fabriqua deux filets d’airain pour couvrir les deux chapiteaux des colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, '(18) Et, pour chaque chapiteau, une guirlande suspendue; deux lignes de grenades d’airain en forme de filets, suspendues en guirlande, une ligne au-dessus de l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, '(19 et 21) Il dressa les colonnes du vestibule du temple à l’un, il donna le nom de Jachum, et à l’autre, il donna le nom de Boloz.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, '(22) Et il plaça, dans les chapiteaux des colonnes, dans le sens de la façade du vestibule, des lis d’airain de quatre coudées; une architrave réunit les deux colonnes, et il y eut de chaque côté une architrave en retour, de la même épaisseur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, '(23) Et il fit la mer complètement circulaire; tout autour, il y avait dix coudées d’un bord à l’autre; elle était profonde de cinq coudées, et avait trente-trois coudées de circonférence intérieure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, '(24) Au-dessous de ses bords, il fit des étais tout alentour, dix par coudée; ses bords s’évasaient comme une coupe en forme de fleur de lis; et elle avait une palme d’épaisseur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, '(25) Il fit douze bœufs sous la mer trois regardant le septentrion, trois regardant l’occident, trois regardant le midi, trois regardant le levant; leurs queues étaient tournées vers l’intérieur du temple, et la mer les couvrait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, '(27) Il fit dix bassins d’airain, chacun long de cinq coudées, large de quatre, haut de six.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, '(28) Ces bassins étaient composés de pièces de rapport, et les pièces rapportées étaient entre les parties saillantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, '(29) Et, sur les pièces rapportées, entres les parties saillantes, il fit des lions, des bœufs, des œuvres variées; et, sur les parties saillantes, en dessus comme en dessous, les places des lions et des bœufs, œuvre allant en pente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, '(30) Et chaque bassin avait quatre roues d’airain, ses accessoires étaient d’airain; et, des quatre côtés, il y avait des supports sous les cuvettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, '(32) Il y avait des crampons dans les bassins et dans les roues; la hauteur d’une roue était d’une demi-coudée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, '(33) Et les roues étaient faites comme les roues d’un char; leurs crampons, leurs bandes, leurs accessoires, étaient jetés en fonte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, '(34) Les quatre supports, aux quatre coins de chaque bassin, faisaient saillie sur lui, et les maintenaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, '(35) Le bassin, dans sa partie supérieure, était terminé par une moulure saillante d’une demi-coudée tout alentour; les crampons s’emboîtaient dans son contour, et le bassin avait une ouverture à l’emboîtement des crampons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, '(36) Toute sa surface était ornée de chérubins, de lions et de palmes; chacune de ces sculptures faisant saillie sur le fond tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, '(37) Et les dix bassins étaient faits de même, et avaient les mêmes dimensions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, '(38) Et il fit dix cuvettes d’airain, profondes de quatre coudées, contenant chacune quarante congés; et chacune de ces cuvettes fut placée dans l’un des dix bassins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, '(39) Hiram plaça cinq bassins du côté de l’aile droite du temple, les cinq autres du côté de l’aile gauche, et la mer du côté de l’aile droite, à l’orient vers le midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, '(40) Et Hiram fit encore les chaudières, les poêles et les coupes; enfin, il acheva tous les travaux qu’il fit pour le roi Salomon dans le temple du Seigneur, savoir: (41) les deux colonnes et les deux guirlandes pour leurs chapiteaux, et deux filets pour couvrir les deux guirlandes des cannelures qui étaient sur les colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, '(42) Les quatre cents grenades entremêlées dans les filets; deux rangées de grenades par filet, pour voiler les guirlandes de la coupe, en forme de lis, sur les deux colonnes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, '(43) Les dix bassins et les dix cuvettes posées dans les bassins;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, '(44) La mer et les douze bœufs sous la mer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, '(45) Les chaudières, les poêles, les coupes et tous les vases que Salomon lui avait commandés pour le temple du Seigneur, et les quarante-huit colonnes du palais du roi et du temple du Seigneur. Tels furent les travaux qu’Hiram fit en entier pour le roi Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, '(47) On ne pesa point l’airain que l’on y employa; la quantité en fut telle qu’on ne put la mesurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, '(46) On jeta l’airain en fonte auprès du Jourdain dans une terre argileuse, entre Socchoth et Sira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, '(48) Salomon prit les ornements qu’Hiram avait faits dans le temple du Seigneur: l’autel d’or, la table d’or des pains de proposition;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, '(49) Les cinq chandeliers d’or placés à gauche, et les cinq placés à droite de la face de l’oracle, tous d’or et de pièces rajustées; et les petites lampes, et les luminaires, et les burettes d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, '(50) Il avait fait faire aussi les panneaux des portiques, les clous, les coupes, les plats et les encensoirs d’or, et les panneaux des portes intérieures du temple et du Saint des saints, et les portes d’or de la nef.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, '(51) Tous les travaux du temple du Seigneur que Salomon fit faire étant terminés, il transporta les objets d’or et d’argent consacrés par David son père, et par lui-même, et il les déposa dans le trésor du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, '(1) Ensuite, Salomon fit bâtir pour lui-même un palais en treize ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, '(2) Il le bâtit en cèdres du Liban; ce palais était long de cent coudées, large de cinquante, haut de trente; il avait trois rangs de colonnes de cèdre; et les traverses entre les chapiteaux étaient en cèdre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, '(3) Il plafonna le palais au-dessus des colonnes; chaque rang de colonnes en comptait quarante-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, '(4) Et il fit trois chambres par rangée, et elles étaient également espacées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, '(5) Il fit toutes les portes, et les intervalles formant les chambres étaient carrés, et les portes correspondaient aux portes dans les trois rangées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, '(6) Il fit un vestibule de colonnes, lequel avait cinquante coudées de long et cinquante coudées de large, et se rattachait à un autre vestibule qui lui faisait face; et il y avait, sur la façade des vestibules, des colonnes très grosses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, '(7) Il fit aussi le vestibule des trônes, où le roi jugeait; c’était la galerie du jugement;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, '(8) Et le palais auquel appartenaient ces vestibules et où le roi devait demeurer avait un parvis, par où on allait à ces vestibules, et construit comme eux; il fit encore le palais de la fille du Pharaon, que le roi avait épousée, de même architecture que les vestibules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, '(9) Tous ces bâtiments étaient en bonnes pierres de taille, sculptées par intervalles extérieurement, depuis le sol jusqu’à la corniche; au dehors il y avait un grand parvis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, '(10) Ses fondations étaient de grandes et belles pierres, longues de dix et de huit coudées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, '(11) En haut desquelles il y avait de belles pierres aussi grandes que les pierres de taille, et des cèdres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, '(12) Et il y avait autour du parvis trois rangs de pierres de taille, et un rang de cèdres sculptés. Ainsi Salomon acheva tout son palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Lorsqu’au bout de vingt ans, Salomon eut achevé de bâtir le temple du Seigneur et son palais, il rassembla dans Sion tous les anciens d’Israël pour enlever de la ville de David (la même que Sion) l’arche de l’alliance du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Au mois d’Athanin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Et les prêtres transportèrent l’arche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Ainsi que le tabernacle du témoignage, et les objets consacrés dans le tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Et le roi et tout Israël, devant l’arche, sacrifiaient des brebis et des bœufs en quantité innombrable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Les prêtres introduisirent l’arche à sa place, dans l’oracle du temple, dans le Saint des saints, sous les ailes des chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Car les chérubins déployaient leurs ailes au-dessus de l’emplacement de l’arche, et ils en couvraient l’arche et ses leviers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Ces leviers étaient dressés, et leurs extrémités se voyaient dès l’entrée du Saint des saints devant l’oracle, mais on ne pouvait les voir du dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Il n’y avait rien dans l’arche sinon les deux tables de pierre, les tables de l’alliance que Moïse y avait déposées sur le mont Horeb, et sur lesquelles le Seigneur avait écrit son alliance avec les fils d’Israël lorsqu’ils revenaient de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Or, quand les prêtres sortirent du Saint des saints il advint qu’une nuée remplit le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Et les prêtres ne purent y demeurer, ni faire le service divin, à cause de la nuée; car la gloire du Seigneur avait rempli le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Alors, le roi se retourna vers le peuple, et il bénit tout Israël, et toute l’Église d’Israël était restée debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Et il dit: Béni soit aujourd’hui le Seigneur Dieu d’Israël, qui, de sa bouche, a parlé concernant David mon père, et qui de ses mains a rempli ses promesses, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Depuis le jour où j’ai tiré de l’Égypte mon peuple Israël, je n’ai choisi en Israël ni ville, ni tribu, pour qu’on bâtit un temple où résidât mon Nom; puis, j’ai choisi Jérusalem pour que mon nom y réside, et j’ai choisi David pour qu’il soit sur mon peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Or, mon père avait en son cœur la pensée de bâtir un temple au nom du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Et le Seigneur dit à David, mon père: En récompense de ce que la pensée t’est venue au cœur de bâtir un temple à mon nom, tu as fait de belles actions, parce que cette pensée était en ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Néanmoins, tu ne bâtiras point ce temple, mais ton fils, qui sortira de toi, le bâtira à mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Le Seigneur a relevé la parole qu’il avait dite, j’ai été suscité à la place de David mon père; et je me suis assis sur le trône d’Israël, comme l’avait dit le Seigneur; et j’ai bâti un temple au nom du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'J’y ai préparé un emplacement pour l’arche qui renferme l’alliance du Seigneur avec nos pères, tandis qu’il les ramenait de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Ensuite, Salomon se tint devant l’autel du Seigneur et devant toute l’Église d’Israël; il étendit les deux mains vers le ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Et il dit: Seigneur Dieu d’Israël, il n’est point au ciel ni sur la terre de Dieu tel que vous, gardant alliance et miséricorde pour le serviteur qui marche de tout son cœur devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Vous avez gardé cette alliance et cette miséricorde, pour votre serviteur David; car vous avez parlé de votre bouche, et de vos mains vous avez rempli vos promesses; comme il se voit aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Maintenant, Seigneur Dieu d’Israël, gardez pour votre serviteur David, mon père, cette parole que vous lui avez dite: Il ne manquera jamais d’hommes de ton sang pour être assis sur le trône d’Israël devant ma face, pourvu que tes enfants observent leurs voies, et qu’ils marchent à mes yeux comme toi-même as marché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Maintenant, Seigneur Dieu d’Israël, que votre promesse à David mon père, votre serviteur, soit confirmée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Est-il donc croyable que Dieu réside sur la terre parmi les hommes? Si le ciel et le ciel des cieux ne peuvent vous contenir, combien moins encore ce temple que j’ai bâti à votre nom?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'O Seigneur Dieu d’Israël, ayez égard à ma demande; écoutez aujourd’hui la prière que vous fait votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Que vos yeux soient ouverts nuit et jour sur ce temple, sur ce lieu dont vous avez dit: C’est là que sera mon nom; et écoutez-y la prière que vous y fait nuit et jour votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Oui, vous écouterez la prière de votre serviteur et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Quelque péché qu’un homme ait commis contre son prochain, même quand il aura songé à le maudire, s’il vient, s’il se confesse, dans le temple devant votre autel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Du haut du ciel vous l’entendrez et vous agirez, et vous jugerez le peuple d’Israël, de telle sorte que l’inique sera considéré comme inique; que vous ferez retomber sur sa tête son égarement dans ses voies, que le juste sera justifié, et que vous le rétribuerez selon son équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Lorsque votre peuple Israël tombera devant ses ennemis parce qu’il aura péché contre vous, ils se convertiront, ils rendront gloire au nom du Seigneur; ils prieront, et ils supplieront en votre temple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Alors, du haut du ciel vous les écouterez, vous leur remettrez leurs péchés, et vous les ramènerez dans la terre que vous avez donnée à leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Lorsque vous aurez fermé le ciel, et qu’il n’y aura plus de pluie parce que les fils d’Israël auront péché contre vous, ils prieront en ce lieu; ils rendront gloire au nom du Seigneur, et ils détesteront leurs péchés, après que vous les aurez humiliés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Et du haut du ciel vous les écouterez, et vous remettrez les péchés de vos serviteurs, de votre peuple; vous leur montrerez la bonne voie qu’ils doivent suivre, et vous accorderez de la pluie à la terre que vous avez donnée pour héritage à votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Lorsqu’il y aura famine, lorsqu’il y aura mortalité par suite de la chaleur brûlante ou du ravage des saute');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Toute prière, toute supplication que l’homme vous fera dans le temple les mains étendues, après avoir reconnu la plaie de son cœur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Vous l’écouterez du haut du ciel, du lieu où est votre demeure; vous serez miséricordieux, vous agirez et vous rétribuerez l’homme selon sa voie, selon ce que vous aurez vu dans son cœur, car vous seul connaissez le cœur de tous les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Ainsi auront-ils crainte de vous tout le temps qu’ils vivront en la terre que vous avez donnée à nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Lorsque l’étranger qui n’est point de votre peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'Entrera aussi et priera dans ce lieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Du haut du ciel, du lieu où est votre demeure, vous accomplirez tout ce que vous aura demandé l’étranger, afin que tous les peuples connaissent votre nom, qu’ils aient crainte de vous comme le peuple d’Israël, et qu’ils sachent que votre nom est invoqué dans ce temple que j’ai bâti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Si votre peuple va en guerre contre ses ennemis dans une voie où vous lui ferez prendre la fuite, il invoquera le nom du Seigneur en se tournant vers la ville que vous vous êtes choisie, et vers le temple que j’ai bâti à');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Et, du haut du ciel, vous écouterez sa demande et sa prière, et vous rendrez sur lui votre jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Ils pècheront contre vous, car il n’est point d’homme qui ne pèche, et vous les emmènerez, vous les livrerez');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Et, dans la terre où on les aura conduits, ils convertiront leurs cœurs, ils se repentiront dans le lieu de leur exil, et ils vous prieront, disant: Nous avons péché, nous avons été déréglés et iniques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'Et ils reviendront à vous de tout leur cœur, de toute leur âme, en la demeure de leurs ennemis où vous les aurez transportés; et ils vous prieront, tournés vers la terre que vous avez donnée à leurs pères, vers la ville que vous vous êtes choisie, et vers ce temple que j’ai bâti au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Et du haut du ciel, du lieu où est votre demeure, vous les écouterez,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Vous leur remettrez leurs iniquités, leurs péchés contre vous, et toutes leurs prévarications; vous leur accorderez d’exciter la compassion des ennemis qui les retiendront en captivité, et ceux-ci leur feront miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Car c’est votre peuple, c’est votre héritage, que vous avez tiré de la terre d’Égypte, du milieu d’une fournaise de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Que vos yeux, que vos oreilles, restent ouverts à la prière que vous fait votre serviteur, à la prière que vous fait votre peuple Israël; écoutez-les en toutes les choses pour lesquelles ils vous invoqueront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Car c’est vous qui les avez mis à part, entre tous les autres peuples, pour être votre héritage, comme vous l’aviez promis à Moïse, lorsque vous avez ramené nos pères de la terre d’Égypte, Seigneur, ô Seigneur. Alors, Salomon parla du temple qu’il avait fait bàtir; il fit connaître le soleil dans le ciel Le Seigneur a voulu habiter dans une nuée ténébreuse; bâtis-moi, a-t-il dit, un temple, une demeure magnifique pour que j’y habite d’une manière nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Lorsque Salomon eut achevé toute cette prière, cette oraison au Seigneur, il se tint debout après s’être agenouillé devant l’autel du Seigneur; puis, les mains étendues vers le ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Debout, il bénit à haute voix toute l’Église d’Israël, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Béni soit aujourd’hui le Seigneur qui a donné la paix à Israël son peuple, selon tout ce qu’il avait dit! Nulle de ses paroles ne s’est trouvée en défaut parmi toutes les bonnes paroles qu’il avait dites par la bouche de Moïse, son serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Puisse le Seigneur Dieu être avec nous comme il a été avec nos pères, puisse-t-il ne nous jamais abandonner, et ne nous point détourner');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'D’incliner vers lui nos cœurs, de marcher dans toutes ses voies et d’observer tous ses commandements, tous les préceptes qu’il a donnés à nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Puissent ces prières que je viens de faire ici devant le Seigneur notre Dieu être près de lui nuit et jour, qu’elles donnent la justice à votre serviteur, et à votre peuple Israël, à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Afin que tous les peuples de la terre sachent que le Seigneur Dieu est le seul Dieu, et qu’il n’y a point d’autre Dieu que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Puissent nos cœurs être parfaits devant le Seigneur notre Dieu, marcher saintement dans ses préceptes, et observer ses commandements, comme aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Ensuite, le roi et tous les fils d’Israël immolèrent des victimes devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Et le roi Salomon sacrifia des hosties pacifiques et les offrit au Seigneur: vingt-deux mille bœufs, cent vingt mille brebis; puis, le roi et tous les fils d’Israël firent la dédicace du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Ce jour-là, le roi consacra le milieu du parvis devant la façade du temple; car c’est là qu’il fit les holocaustes et les sacrifices, et qu’il brûla la graisse des hosties pacifiques, parce que l’autel d’airain dressé devant le Seigneur était trop petit pour suffire aux holocaustes et aux hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Et le roi Salomon, ce jour-là, commença la fête, et avec lui tout Israël, une immense assemblée accourue depuis les gorges d’Emath jusqu’au fleuve d’Égypte, devant le Seigneur notre Dieu, au temple qu’on lui avait bâti; ils mangeaient, buvaient et se réjouissaient devant le Seigneur notre Dieu, pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Et le huitième jour, Salomon congédia le peuple, et ils bénirent le roi. Et chacun s’en retourna en sa demeure plein de joie, le cœur pénétré des biens que le Seigneur avait accordés à David son serviteur, ainsi qu’à Israël son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Après que Salomon eut achevé de bâtir le temple du Seigneur et le palais du roi, et tout ce qu’il avait eu dessein de construire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Le Seigneur apparut une seconde fois à Salomon, comme en Gabaon déjà il lui était apparu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Et le Seigneur lui dit: J’ai entendu ta prière et les oraisons que tu as faites devant noi; et je t’ai accordé tout ce que tu avais demandé, j’ai sanctifié ce temple que tu as bâti pour que mon nom y résidât à jamais; mes yeux et mon cœur y seront toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Pour toi, si tu marches devant moi, comme a marché David ton père, en droiture et sainteté de cœur, pour agir selon tout ce que je t’ai ordonné; si tu observes mes commandements et mes ordonnances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Je maintiendrai à jamais ton trône sur Israël comme je l’ai promis à David ton père, disant: Jamais il ne manquera d’hommes issus de toi pour régner sur Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mais si vous et vos enfants vous détournez de moi, si vous n’observez point les commandements et les ordonnances que Moïse vous a fait connaître; si vous suivez, si vous servez d’autres dieux, si vous les adorez,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'J’enlèverai Israël de la terre où je l’ai établi; le temple que j’ai sanctifié par mon nom, je le rejetterai de devant ma face; Israël sera, parmi tous les peuples, comme une chose effacée, comme un sujet de moquerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Ce temple si haut sera en un tel état, que le passant, frappé de stupeur, sifflera et dira: Pourquoi donc le Seigneur a-t-il ainsi traité cette terre et ce temple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Et on lui répondra: C’est pour avoir abandonné le Seigneur leur Dieu, qui avait ramené leurs pères de l’Égypte, et de la maison de servitude; ils se sont attachés à des dieux étrangers, ils les ont adorés, et les ont servis; voilà pourquoi le Seigneur a fait retomber sur eux leurs propres crimes. Or, le roi Salomon avait déjà conduit la fille du Pharaon de la ville de David au palais qu’en ces temps-là il s’était bâti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Pendant les vingt ans qu’il mit à construire les deux édifices, le temple du Seigneur et le palais du roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiram, roi de Tyr, vint en aide à Salomon en lui donnant des cèdres et des sapins, de l’or et tout ce qu’il voulut; en échange le roi donna à Hiram vingt villes de la province de Galilée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Et Hiram sortit de Tyr, et alla en Galilée pour voir les villes que lui avait données Salomon; mais elles ne lui plurent pas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Et il dit: Que sont ces villes que tu m’as données, frère? Et il les appela Orion, nom qu’elles portent encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Ensuite, Hiram apporta à Salomon cent vingt talents d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, '(26) C’est pourquoi, le roi Salomon construisit un vaisseau en Asion-Gaber, qui est limitrophe d’Elath, sur le rivage de la mer Rouge, en la terre d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '(27) Et le roi Hiram envoya sur le vaisseau des serviteurs, matelots exercés à naviguer sur mer, qui s’embarquérent avec les serviteurs de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Et ils allèrent à Ophir; et ils y prirent cent vingt talents d’or, et ils les apportèrent au roi Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Et la reine de Saba ouït le nom de Salomon et le nom du Seigneur, et elle vint pour éprouver le roi en lui proposant des énigmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Elle entra dans Jérusalem avec une suite nombreuse, et des chameaux chargés de parfums et d’une immense quantité d’or et de pierres précieuses; elle fut introduite auprès de Salomon, et elle lui dit toutes les choses qu’il y avait en son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Salomon l’éclaira sur toutes ses questions; il n’y eut pas une de ses questions à laquelle le roi négligeât de répondre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Et la reine de Saba vit toute la sagesse de Salomon, le palais qu’il avait bâti,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Les mets de sa table, les logements de ses serviteurs, la tenue de ses officiers, ses vêtements, ses échansons, et les holocaustes qu’il offrait dans le temple du Seigneur, et elle en fut hors d’elle-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Et elle dit au roi Salomon: C’était la vérité qu’on m’avait dite en mon pays,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Au sujet de ton éloquence et de ta sagesse; j’avais refusé de croire ce qu’on m’en avait rapporté, jusqu’à ce que je fusse venue moi-même et que j’eusse vu de mes yeux; et je reconnais qu’on ne m’avait point appris la moitié de ce qui réellement existe. Tu as beaucoup ajouté aux merveilles dont j’avais ouï parler chez moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Heureuses tes femmes, heureux tes serviteurs qui sont toujours auprès de toi, et qui recueillent toute ta');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Béni soit le Seigneur ton Dieu qui s’est complu en toi, pour te donner le trône d’Israël, parce que le Seigneur Dieu aime ce peuple, et qu’il l’affermira pour toujours. Le Seigneur t’a fait leur roi pour que les jugements soient selon la justice et selon l’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Elle donna à Salomon cent vingt talents d’or, et une immense quantité d’épices et de pierres précieuses. Il n’était jamais arrivé à Jérusalem autant d’épices que la reine de Saba en donna au roi Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Et le vaisseau d’Hiram qui avait transporté l’or d’Ophir, apporta une énorme quantité de bois rares et de pierres précieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Et le roi fit avec les bois des balustrades pour le temple et le palais; puis, des lyres et des harpes pour les');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Et le roi Salomon donna à la reine de Saba tout ce qu’elle voulut, tout ce qu’elle lui demanda, outre ce qu’il lui donna spontanément. Et elle s’en alla, et elle retourna en sa contrée avec tous ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Et le poids de l’or, qui arriva au roi Salomon en une année, fut de six cent soixante-six talents,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Sans compter les tributs de ceux qui lui étaient soumis, marchands, rois de la rive gauche de l’Euphrate, ou princes de la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Et Salomon fit faire trois cents javelines d’or battu, chacune de trois cents sicles d’or,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Et trois cents armures d’or battu, de trois mines d’or chacune; et il les consacra dans le palais de bois du Liban.’');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Il fit faire aussi un grand trône d’ivoire, qu’il revêtit de lames d’or très-fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'On montait sur le trône par six degrés; il y avait des faces de taureaux derrière le trône, deux bras des deux côtés du siége et deux lions auprès des bras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Il y avait douze lions sur les degrés, six à droite, six à gauche; on ne voyait rien de semblable dans aucun royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Et tous les vases dont se servait Salomon étaient d’or, ses baignoires étaient d’or; tous les meubles du palais de bois du Liban étaient d’or et de pièces rapportées. On n’y voyait point d’argent; car ce métal était compté pour rien du temps de Salomon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Et cela parce que Salomon avait un vaisseau de Tharsis à la mer, avec la flotte d’Hiram; tous les trois ans un vaisseau venait de Tharsis chargé d’or, d’argent et de pierres rares et travaillées. Voici l’emploi des richesses que le roi amassa Il bâtit le temple du Seigneur, son propre palais, les remparts de Jérusalem, la citadelle qui renfermait l’enceinte de la ville de David, Assur, Magdal, Gazer, Béthoron-la-Haute, Jéthermuth, toutes les villes des chars et toutes les villes des cavaliers; il éleva des constructions tant à Jérusalem que dans la terre promise, pour prévenir les séditions des peuples qu’on avait épargnés: de l’Hettéen, de l’Amorrhéen, du Phérézéen, du Chananéen, de l’Evéen et du Jébuséen, de tous ceux qui n’étaient point du sang d’Israël, et dont les fils vivaient dans la terre promise, parce que les fils d’Israël n’avaient pu les exterminer; Salomon les avait obligés à payer un tribut qu’ils paient encore de nos jours. Or, Salomon n’exigeait rien des fils d’Israël, parce qu’ils étaient ses guerriers, ses serviteurs, ses chefs, les intendants de ses chars et ses cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Et Salomon fut grand en science et en richesses par-dessus tous les rois de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Tous les rois de la terre demandèrent à le voir, et à entendre la sagesse que Dieu avait mise en son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Et, chaque année, ils lui apportaient tous des présents des vases d’or, des vêtements, de la myrrhe, des épices, des chevaux et des mules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomon avait, pour ses chars, quatre mille cavales, et dix mille chevaux pour ses cavaliers; il les avait mis dans les villes des chars ou auprès de lui à Jérusalem, et il était chef de tous les rois depuis l’Euphrate jusqu’au territoire des Philistins et aux frontières de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Et le roi rendit à Jérusalem l’or et l’argent aussi communs que les pierres; il y amena autant de cèdres qu’il y a de mûriers dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Salomon tirait des chevaux de l’Égypte; il y avait à Thécoé un marché royal, et on les allait prendre à Thécoé à prix d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'L’attelage d’un char, venant d’Égypte, coûtait cent sicles d’argent et cinquante sicles par cheval. Il en était de même pour tous les rois des Hettéens et de la Syrie; ces achats venaient par mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Et le roi Salomon aimait les femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, '(3) Il avait sept cents femmes princesses et trois cents concubines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, '(1) Il avait epousé des femmes étrangères: la fille du Pharaon, puis des Moabites, des Ammonites, des Syriennes, des Iduméennes, de Hettéennes et des Amorrhéennes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, '(2) Des femmes de ces peuples dont le Seigneur avait dit aux fils d’Israël « Vous n’aurez point avec eux de commerce, ni eux avec vous, de peur qu’ils ne détournent vos cœurs vers leurs idoles. » Salomon s’était attaché à elles, il les aimait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, '(4) Et, au temps de sa vieillesse, son cœur ne fut point parfait à l’égard du Seigneur son Dieu, comme le cœur de David, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, '(3) Car les femmes étrangères détournèrent son cœur vers leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Alors, Salomon bâtit un haut lieu à Chamos, idole de Moab; à leur roi, idole des fils d’Ammon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, '(5) Et à Astarté, abomination des Sidoniens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, '(8) À toutes ses femmes étrangères, il accorda de sacrifier à leurs idoles et de les encenser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, '(6) Et Salomon fit le mal devant le Seigneur; il ne suivit point le Seigneur, comme l’avait suivi David, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, '(9) Et le Seigneur se courrouça contre Salomon, parce qu’il avait détourné son cœur du Seigneur Dieu d’Israël qui lui était apparu deux fois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, '(10) Et lui avait expressément commandé de ne jamais suivre d’autres dieux, d’être attentif à faire tout ce qu’avait prescrit le Seigneur Dieu; en effet, son cœur n’était point parfait à l’égard du Seigneur, comme le cœur de David, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, '(11) Et le Seigneur dit à Salomon: En punition de ce que tu as agi de la sorte et n’as point gardé mes commandements et mes ordonnances que je t’avais donnés, je déchirerai dans tes mains ton royaume, et j’en donnerai une part à ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, '(12) Seulement, à cause de David, ton père, je ne ferai point ces choses de ton vivant; je retirerai des mains de ton fils cette part du royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, '(13) Car je ne le lui prendrai pas tout entier; je laisserai un sceptre à ton fils, à cause de David, mon serviteur, et à cause de Jérusalem, ville que j’ai choisie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(14) Et le Seigneur avait suscité des satans contre Salomon Ader l’Iduméen et Esron, fils d’Eliadaé de Raama, jadis serviteur d’Adadézer, roi de Suba; ils avaient');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, '(15) Or, ceci était advenu: Dans le temps que David exterminait Edom, et que Joab, général de son armée, était à ensevelir les morts, car ils frappaient tous les mâles dans l’Idumée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, '(16) (Joab y passa six mois avec tout Israël, jusqu’à ce qu’ils eussent détruit tous les mâles de l’Idumée.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, '(17) Ader s’enfuit emmenant avec lui tous les Iduméens, serviteurs de son père; il se réfugia en Égypte, alors petit enfant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, '(18) Et des hommes de la ville de Madian s’étaient soulevés; quand Ader et les siens entrèrent dans Pharan, prirent avec eux les hommes, et allèrent chez le Pharaon, roi d’Égypte. Ader fut introduit auprès du Pharaon; le roi lui donna une demeure, et lui assigna des vivres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, '(19) Et Ader trouva grâce devant le Pharaon, et le roi lui fit épouser la sœur de sa femme Thécémina, la sœur aînée de Thécémina.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, '(20) Cette sœur de Thécémina enfanta pour Ader un fils nommé Ganebath, que Thécémina éleva avec les fils du Pharaon; Ganebath était donc parmi les fils du Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, '(21) Lorsque Ader apprit en Égypte que David dormait auprès de ses pères, et que Joab, général de son armée, était mort; il dit au Pharaon: Congédie-moi, et je retournerai dans mon pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, '(22) Et le Pharaon répondit à Ader: Que te manquet-il parmi nous? Pourquoi demandes-tu à retourner en ton pays? Ader reprit: Je désire que tu me congédies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Et il revint en sa contrée. Voilà d’où venait la méchanceté d’Ader, il contristait Israël et il régnait sur Édom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Or, Jéroboam, fils de Nabat l’Ephrathéen de Sarira, fils d’une femme veuve, était serviteur de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Voici à quelle occasion il leva les mains contre le roi son maître. Le roi Salomon était à bâtir la citadelle, et il entourait de murs l’enceinte de la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Jéroboam était vaillant, et Salomon discerna que le jeune serviteur était un homme d’action, et il le nomma intendant des tributs de la maison de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'En ce temps-là, Jéroboam sortit de Jérusalem, et il fut rencontré sur la route par Achias, le prophète silonite. Achias se détourna du chemin, et Achias était enveloppé d’un manteau neuf; ils étaient seuls tous les deux dans les champs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Et Achias ôta son manteau neuf et le déchira en douze parts,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Et il dit à Jéroboam: Prends pour toi dix de ces lambeaux; car voici ce que dit le Seigneur Dieu d’Israël: Je déchirerai entre les mains de Salomon son royaume, et je te donnerai dix tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Et il lui restera deux tribus, à cause de mon serviteur David, et à cause de Jérusalem, ville que j’ai choisie parmi toutes les tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'C’est en punition de ce qu’il m’a abandonné; de ce qu’il a sacrifié à Astarté, abomination des Sidoniens, à Chamos, aux idoles de Moab et à leur roi, abomination des fils d’Ammon, et de ce qu’il n’a point marché en toutes mes voies pour faire devant moi ce qui est droit, comme l’a fait David, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Toutefois, je ne retirerai point de sa main le royaume entier; je le lui laisserai même tout le reste de sa vie, à cause de David, son père, mon élu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mais je prendrai le royaume des mains de son fils, et je te donnerai dix tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Et je laisserai à son fils deux tribus, afin qu’il y ait toujours devant moi, pour mon serviteur David, un trône en Jérusalem, dans la ville que je me suis choisie pour que mon nom y résidât.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Pour toi, je te prendrai, et tu régneras comme le désire ton âme; tu seras roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Et, si tu observes tout ce que je t’ordonnerai, si tu marches en mes voies, si tu fais devant moi ce qui est droit, en gardant mes commandements et mes ordonnances, comme a fait David, mon serviteur, je serai avec toi, et je te bâtirai une maison sûre, de même que j’en ai bâti une pour David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, '(40) Et Salomon chercha à faire périr Jéroboam; mais il partit, et s’enfuit auprès de Sésac, roi d’Égypte, et il y demeura jusqu’à la mort de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, '(41) Le reste de l’histoire de Salomon, tout ce qu’il a fait, toute sa sagesse, ne sont-ils pas écrits au livre de la vie de Salomon?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, '(42) Salomon régna quarante ans sur tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, '(43) Et il s’endormit avec ses pères, et on l’ensevelit en la ville de David. Dès que Jéroboam, fils de Nabat, l’apprit, comme il était encore en Égypte, où il s’était établi pour éviter la colère de Salomon, il revint à sa ville, en la terre de Sarira, dans la montagne d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, '(44) Le roi Salomon s’était endormi avec ses pères, et Roboam, son fils, régnait à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Alors, le roi Roboam se rendit à Sichem, parce que tout Israël y était venu pour le proclamer roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, '(3) Et le peuple parla au roi Roboam, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, '(4) Ton père a rendu pesant notre joug; allége donc maintenant la servitude trop dure de ton père; que notre joug soit moins lourd, et nous te servirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '(5) Et il leur dit: Allez-vous-en pendant trois jours, puis, revenez près de moi, et ils s’en allèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, '(6) Et le roi consulta les anciens qui, du vivant de Salomon, son père, se tenaient auprès de lui, disant: Que me conseillez-vous de répondre à ce peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, '(7) Ils lui dirent: Si aujourd’hui tu te montres le serviteur de ce peuple, si tu te montres agréable pour lui, si tu lui dis de bonnes paroles, ils seront tes serviteurs tous les jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, '(8) Mais il dédaigna le conseil que les anciens lui avaient donné, et il consulta les jeunes gens élevés avec lui, et qui se tenaient auprès de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, '(9) Et il leur dit: Que me conseillez-vous? Que dois-je répondre à ce peuple qui me dit: Allége le joug que nous a mis ton père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, '(10) Or, les jeunes gens élevés avec lui, et qui se tenaient auprès de lui, dirent: Tu diras ces choses à ce peuple qui t’a dit: Ton père a rendu pesant notre joug, maintenant donc, allége-le, tu leur diras ces choses: Mon petit doigt est plus gros que les reins de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Mon père vous a chargés d’un joug pesant, je le rendrai pour vous plus pesant encore. Mon père vous a châtiés à coups de fouet, moi je vous châtierai avec des scorpions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Or, tout Israël se réunit autour du roi Roboam, le troisième jour, comme il le leur avait prescrit, disant: Revenez dans trois jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Et le roi leur répondit durement, car il avait dédaigné le conseil que les anciens lui avaient donné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Et il leur parla selon le conseil des jeunes gens, et il leur dit: Mon père vous a chargés d’un joug pesant, je le rendrai pour vous plus pesant encore; mon père vous a châtiés à coups de fouet, je vous châtierai avec des scorpions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Et le roi n’avait point écouté les fils d’Israël, parce que le Seigneur s’était tourné contre lui, afin de confirmer la parole qu’il avait dite concernant Jéroboam, fils de Nabat, par Achias le Silonite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Quand Israël vit que le roi ne l’avait pas écouté, le peuple répondit au roi: Qu’y a-t-il entre nous et David? Notre héritage ne dépend pas du fils de Jessé. Hâte-toi, Ô Israël! de retourner en tes demeures; et toi, David, nourris ta maison. Et Israël s’en alla chacun en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, '(18) Alors, le roi leur envoya Adonisam, intendant des impôts; ils le lapidèrent, il mourut; et le roi Roboam s’empressa de fuir pour se renfermer dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, '(19) Et jusqu’à nos jours la maison de David a été rejetée par Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Et tout Israël apprit que Jéroboam était revenu d’Égypte, et ils l’envoyèrent chercher pour venir à l’assemblée; ils le proclamèrent roi d’Israël, et il ne resta plus à la maison de David que les tribus de Juda et de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Cependant, Roboam était entré à Jérusalem; il réunit la synagogue de Juda et la tribu de Benjamin, cent vingt mille jeunes gens allant à la guerre, afin de combattre Israël, et de recouvrer la royauté pour le fils de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mais la parole du Seigneur vint à Samaias, homme de Dieu, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Parle à Roboam, fils de Salomon, roi de Juda, à toute la maison de Juda, à Benjamin et au reste du peuple, dis-leur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Voici ce que dit le Seigneur: Ne partez pas, ne combattez point vos frères, les fils d’Israël; retournez chacun en votre demeure, car cette chose est de moi. Ils obéirent à la parole du Seigneur, et, selon son ordre, ils renoncèrent à marcher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Ensuite, Jéroboain rebâtit Sichem en la montagne d’Ephraïm, et il y demeura; puis, il sortit, et il bâtit Pharmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Et Jéroboam se dit en son cœur: La royauté va retourner à la maison de David;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Si ce peuple continue de faire des sacrifices dans le temple du Seigneur à Jérusalem, le cœur du peuple retournera au Seigneur et à son maître Roboam, roi de Juda, et ils me feront périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Le roi prit donc conseil, et il se décida; il fit deux génisses d’or, et il dit au peuple: C’est assez de voyages à Jérusalem; Israël, voici tes dieux, qui t’ont ramené de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Et il plaça l’une des deux génisses à Béthel, et il donna l’autre à Dan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Et cette chose devint une cause de péché; le peuple alla jusqu’à Dan, devant l’une des deux génisses, et il abandonna le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Il bâtit des temples sur les hauts lieux; il prit des prêtres de toutes les tribus du peuple, et ces prêtres n’étaient pas des fils de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Jéroboam institua aussi une fête le huitième mois, quinzième jour de la lune, le jour même que l’on fêtait en la terre de Juda, et il monta à l’autel qu’il avait élevé à Béthel pour y sacrifier aux génisses qu’il avait fabriquées, et il plaça en Béthel les prêtres des hauts lieux qu’il avait consacrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Et il monta à l’autel qu’il avait dressé, le quinzième jour du huitième mois, pendant la fête qu’il avait imaginée en son cœur; il fit célébrer cette fête par les fils d’Israël, et il monta à l’autel pour y sacrifier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 50, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 51, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 52, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 53, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 54, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Or, voilà qu’un homme de Dieu vint de Juda à Béthel avec la parole du Seigneur, et Jéroboam était devant l’autel pour y sacrifier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Et l’homme cria contre l’autel avec la parole du Seigneur, et il dit: Autel! autel! Voici ce que dit le Sei');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Et, ce jour même, l’homme donna un signe, et dit Voici la parole qu’a dite le Seigneur; il a dit: Voilà que l’autel est fendu; la graisse qu’on y a déposée va se répandre à terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Lorsque le roi Jeroboam eut ouï les paroles de l’homme de Dieu et ses imprécations contre l’autel, il étendit sur lui la main, et il dit: Saisissez-le. Aussitôt la main que de l’autel il avait étendue vers l’homme, se dessécha, et il ne put la ramener à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Et l’autel se fendit, et la graisse qu’on y avait déposée se répandit à terre, selon le signe que l’homme de Dieu avait donné avec la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Alors, le roi Jéroboam dit à l’homme de Dieu: Prie devant le Seigneur ton Dieu, que je puisse ramener ma main. L’homme de Dieu pria devant le Seigneur, et il rendit au roi l’usage de sa main, qui redevint comme auparavant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Après cela, le roi dit à l’homme de Dieu: Entre avec moi dans ma demeure, déjeune, et je te ferai des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mais l’homme de Dieu dit au roi: Tu me donnerais la moitié de ta maison que je n’y entrerais pas avec toi; je ne mangerai pas de pain, je ne boirai point d’eau en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Car le Seigneur, avec sa parole, m’a fait un ordre, il a dit: Ne mange pas de pain, ne bois point d’eau, et, en t’en allant, ne prends pas le chemin par où tu es venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Et il s’en retourna par un autre chemin, et il ne prit point celui par où il était venu à Béthel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Or, il y avait à Béthel un prophète avancé en âge, et ses fils allèrent lui raconter les œuvres que, ce jour-là, l’homme de Dieu avait faites en Béthel, et les paroles qu’il avait dites au roi. Et leur père changea de visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Et leur père dit: Par où s’en va-t-il? Ses fils lui montrèrent le chemin que venait de prendre l’homme de Dieu venu de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Et il dit à ses fils: Bâtez-moi l’âne; ils lui bâtèrent son âne, et il courut après l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Il prit le même chemin que l’homme de Dieu; et il le trouva assis sous un chêne, et il lui dit: Es-tu l’homme de Dieu venu de Juda? L’autre répliqua: Je le suis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Et il lui dit: Viens avec moi, et mange du pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Je ne puis te suivre, reprit l’autre, ni manger du pain ni boire de l’eau en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Car le Seigneur m’a donné ses ordres de sa propre bouche; il a dit: Ne mange pas là de pain, n’y bois point d’eau, et, en t’en allant, ne prends pas le chemin par où tu es venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Mais le vieillard lui dit: Moi aussi je suis comme toi prophète; un ange du Seigneur m’a parlé avec la parole du Seigneur, disant: Ramène-le avec toi en ta maison; qu’il mange du pain, qu’il boive de l’eau. Or, le vieillard le trompait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Il revint donc, il mangea du pain, il but de l’eau en sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Et ceci advint: Comme ils étaient assis à table, la parole du Seigneur vint au prophète qui l’avait ramené.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Et il dit à l’homme de Dieu qui était venu de Juda: Voici ce que dit le Seigneur: En punition de ce que tu as irrité la parole du Seigneur, de ce que tu n’as point gardé le commandement que t’avait fait le Seigneur ton Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'De ce que tu es revenu, de ce que tu as bu et mangé dans ce lieu, après qu’il t’avait dit: « Tu n’y mangeras pas de pain, tu n’y boiras point d’eau,» ton corps n’entrera pas dans le sépulcre de tes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Or, quand l’homme de Dieu eut mangé du pain et bu de l’eau, il bâta son âne, et s’en alla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Mais un lion le trouva en route, et le tua; son corps resta étendu sur le chemin; l’âne ne bougea pas, et le lion se tint auprès du corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Et des hommes vinrent à passer; ils virent le cadavre gisant sur le chemin, et le lion se tenant auprès du cadavre; puis, ils entrèrent dans la ville où demeurait le vieux prophète, et ils racontèrent ce qu’ils avaient vu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Le vieillard l’apprit, et il s’écria: Ce doit être l’homme de Dieu qui a irrité la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Et il sortit, et il trouva le cadavre gisant sur le chemin, l’âne et le lion se tenant auprès du corps; et le lion n’avait point mangé le mort, et il n’avait point déchiré l’âne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Le prophète souleva le corps de l’homme de Dieu, le plaça sur son âne, et le ramena à la ville, afin de l’ensevelir');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Dans son propre sépulcre; et ils pleurèrent sur lui, disant: Hélas! frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Après qu’ils eurent pleuré sur lui, le vieillard dit à ses fils Quand je mourrai, ensevelissez-moi dans le sépulcre où l’homme de Dieu a été enseveli; placez-moi auprès de ses ossements, afin que mes ossements soient sauvés avec les siens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Car la chose qu’il a dite d’après la parole du Seigneur, concernant l’autel de Béthel et les temples des hauts lieux en Samarie, s’accomplira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Après ces choses, Jéroboam ne se repentit point de sa méchanceté; il continua de prendre, parmi tout le peuple, des prêtres des hauts lieux. Le premier venu put avoir la main pleine, et devenir prêtre sur les hauts lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Ce fut le péché de la maison de Jéroboam, cause de sa perte et de sa disparition de la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, '(21) Cependant, Roboam, fils de Salomon, régnait sur Juda; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem, dans la ville que, parmi toutes les tribus d’Israël, le Seigneur s’était choisie pour qu’y résidât son nom; sa mère, nommée Naama, était Ammonite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, '(22) Roboam fit le mal devant le Seigneur, et il l’irrita, en faisant tout ce que faisaient ses pères quand ils tombaient dans le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, '(23) Le peuple se bâtit des hauts lieux et des colonnes; il eut des bois sacrés sur toutes les collines élevées; et il adora sous tous les arbres touffus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, '(24) Et il y eut une association dans la terre promise; il s’y commit toutes les abominations des peuples que le Seigneur avait exterminés devant la face des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, '(25) Aussi, la cinquième année du règne de Roboam, Sésac, roi d’Égypte, marcha contre Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Et il prit tous les trésors du temple du Seigneur, et tous les trésors du palais du roi, et les javelines d’or que David avait enlevées aux fils d’Adrazaar, roi de Suba, pour les placer à Jérusalem, et les armures d’or qu’avait fait fabriquer Salomon; Sésac emporta tout en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, '(27) Roboam remplaça les armures d’or par des armures d’airain, et il les mit sous la surveillance des chefs de ses coureurs, qui gardaient la porte de son palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, '(28) Et lorsque le roi entrait dans le temple du Seigneur, ses coureurs portaient les armures et les attachaient dans le dépôt des coureurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, '(29) Quant au reste de l’histoire de Roboam, n’estil pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, '(30) Et il y eut une guerre continuelle entre Roboam et Jéroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, '(31) Et Roboam s’endormit avec ses pères; il fut enseveli auprès d’eux en la ville de David, et son fils Abiam le remplaça.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'En la dix-huitième année du règne de Jéroboam, fils de Nabat, Abiam, fils de Roboam, devint roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Et il régna trois ans à Jérusalem; sa mère, fille d’Absalon, se nommait Maacha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Et il marcha dans les péchés que son père avait faits devant lui, et son cœur ne fut point parfait avec le Seigneur son Dieu, comme l’était le cœur de son père David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mais, à cause de David, le Seigneur lui donna un rejeton, afin de maintenir ses enfants après lui, et d’affermir Jérusalem;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Parce que David avait fait ce qui est droit devant le Seigneur, et que, pendant toute sa vie, il ne s’était jamais écarté des commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Quant au reste de l’histoire d’Abiam, n’est-il pas écrit au livre des Faits et gestes des rois de Juda? Et la guerre ne cessa pas entre Abiam et Jéroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Et Abiam s’endormit avec ses pères, en la vingtquatrième année du règne de Jéroboam; il fut enseveli auprès de ses pères en la ville de David; et son fils Asa régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Dans la vingt-quatrième année du règne de Jéroboam, roi d’Israël, Asa devint roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Il régna quarante et un ans à Jérusalem; sa mère, fille d’Absalon, se nommait Ana.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Et Asa fit ce qui était droit devant le Seigneur, comme son père David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Et il détruisit, dans la terre promise, les initiations, et il abolit les infâmes pratiques qu’avaient adoptées ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Il expulsa Ana, sa mère, pour qu’elle ne fût plus rien, parce qu’elle réunissait une association d’inities dans son bois sacré, et il abattit ses refuges, et il les livra aux flammes dans la vallée de Cédron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mais il ne détruisit pas les hauts lieux; néan moins, le cœur d’Asa fut parfait avec Dieu tout le temps qu’il vécut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Et il transporta les colonnes de son père; il transporta dans le temple du Seigneur ses colonnes d’or et d’argent, et ses vases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Et la guerre ne cessa point entre Asa et Baasa, roi d’Israël, tout le temps de leur vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Baasa, roi d’Israël, marcha contre Juda, et il se mit à bâtir Rhama, pour qu’il n’y eût personne qui pût sortir ni rentrer, en faveur du roi Asa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Asa, alors, prit tout l’argent et tout l’or qui se trouva dans les trésors du temple et du palais; il les confia à ses serviteurs, et il les envoya chez le fils d’Ader, fils de Tabremon, fils d’Esion, roi de Syrie, qui résidait à Damas, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Fais alliance entre moi et toi, entre la maison de mon père et la maison de ton père; voilà que je t’ai envoyé des présents: de l’argent et de l’or; viens, romps ton alliance avec Baasa, roi d’Israël, et il s’éloignera de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Et Ben-Ader écouta le roi Asa; il fit partir les chefs de ses armées contre les villes d’Israël; ils dévastèrent Ahion, Dan, Abel de la maison de Maacha, et tout Cennereth jusqu’aux confins de Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Quand Baasa l’apprit, il abandonna les constructions de Rhama, et il retourna à Thersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Et le roi Asa, dans Enacim, donna ses ordres à tout Juda, ils enlevèrent les pierres de Rhama, et les bois que Baasa avait employés pour la bâtir. Ensuite, le roi s’en servit pour fortifier toutes les collines de Benjamin, et pour y établir la tour du guet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Quant au reste de l’histoire d’Asa, à toutes les actions qu’il fit en sa puissance, à toutes les villes qu’il bâtit, ne sont-ils pas inscrits au livre des Faits et gestes des rois de Juda? Toutefois, dans sa vieillesse, il perdit l’usage de ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Et Asa s’endormit avec ses pères; il fut enseveli auprès d’eux en la ville de David, son aïeul. Et Josaphat, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nabat, fils de Jéroboam, devint roi d’Israël dans la seconde année du règne d’Asa en Juda, et Nabat régna deux ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Et il fit le mal devant le Seigneur; il marcha dans la voie de son père, et dans les péchés où il avait fait tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Et Baasa, fils d’Achias, l’assiégea à la tête de la maison de Bélaan, fils d’Achias; il l’entoura de palissades à Gabathon, ville des Philistins, que Nabat et tout Israël avaient investie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Et Baasa le tua, la troisième année du règne d’Asa en Juda, et il régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Dès qu’il fut proclamé, il extermina toute la maison de Jéroboam; nul de ceux des siens, qui avait souffle de vie, ne fut épargné, jusqu’à ce que tout eût péri, selon la parole que le Seigneur avait dite par la voix de son serviteur Achias le Silonite,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Concernant les péchés de Jéroboam, et le péché où il avait fait tomber Israël pour irriter le Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Quant au reste de l’histoire de Nabat, n’est-il pas écrit au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'En la troisième année du règne d’Asa en Juda, Baasa, fils d’Achias, fut proclamé roi d’Israël, et-il régna vingt-quatre ans à Thersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Et il fit le mal devant le Seigneur; il marcha dans la voie de Jéroboam, fils de Nabat, et dans les péchés où il avait fait tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Et la parole du Seigneur vint à Jéhu, fils d’Anani; celui-ci dit à Baasa:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'En punition de ce qu’après avoir été, par moi, tiré de la poussière et élevé sur le trône d’Israël, tu as marché dans la voie de Jéroboam, tu as fait tomber dans le péché tout mon peuple d’Israël, qui, par ses vanités, a excité ma colère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Je susciterai des ennemis contre toi Baasa et contre toute ta maison, et je leur livrerai ta maison comme je t’ai livré la maison de Jéroboam, fils de Nabat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Les chiens dévoreront celui du sang de Baasa qui mourra dans la ville; et les oiseaux du ciel dévoreront celui qui mourra dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Quant au reste de l’histoire de Baasa, n’est-il pas écrit au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Et Baasa s’endormit avec ses pères; il fut enseveli à Thersa, et son fils régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Or, le Seigneur avait parlé par la voix de Jéhu, fils d’Anani, contre Baasa et sa maison, à cause de tout le mal qu’il avait fait devant le Seigneur, pour irriter le Seigneur par les œuvres de ses mains, et pour que sa maison devînt comme celle de Jéroboam; et Baasa avait tué Jéhu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Et Ela, fils de Baasa, régna deux ans sur Israël, à Thersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Et Zambri, chef de la moitié de sa cavalerie, se révolta contre lui; comme il était à boire, et déjà ivre, dans la maison d’Osa, son économe, à Thersa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zambri entra, le frappa, le tua, et régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Et, aussitôt qu’il fut proclamé roi, et qu’il se fut assis sur le trône,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Il extermina toute la famille de Baasa, selon la parole qu’avait dite le Seigneur sur la maison de Baasa, par la voix de Jéhu le prophète,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Concernant les péchés de Baasa et de son fils Ela, et le péché où ils avaient fait tomber Israël, qui, par ses vanités, avait irrité le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Quant au reste de l’histoire d’Ela, n’est-il pas écrit au livre des faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Zambri régna sept jours à Thersa; alors, Israël était campé devant Gabathon, ville des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Et le peuple ouït dans le camp que l’on disait: Zambri s’est révolté et il a tué le roi; aussitôt, le peuple d’Israël proclama roi Ambri, qui, ce jour-là, commandait l’armée et le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Et Ambri, avec tout Israël, partit de Gabathon, et il assiégea Thersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Quand Zambri vit que sa ville était prise, il se réfugia dans un souterrain de son palais; puis, il brûla sur lui le palais, et il mourut,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'A cause des péchés qu’il avait commis en faisant le mal devant le Seigneur, en faisant tomber Israël dans le péché, et en marchant dans la voie de Jéroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Pour le reste de l’histoire de Zambri, n’est-il pas écrit au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Alors, le peuple d’Israël se divisa: la moitié voulut pour roi Thamni, fils de Gonath; l’autre moitié, Ambri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Le peuple qui suivait Ambri l’emporta sur le peuple qui suivait Thamni, fils de Gonath; Thamni mourut, en ce temps-là, ainsi que Joram, son frère, et Ambri régna après Thamni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'En la trente et unième année du règne d’Asa en Juda, Ambri fut reconnu roi d’Israël; il régna douze ans, dont six à Thersa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Et Ambri acheta la montagne de Samarie, de Samar, qui était maître de cette montagne, au prix de deux talents d’argent; il bâtit sur la montagne une ville qu’il appela Samarie, du nom de celui qui la lui avait vendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Et Ambri fit le mal devant le Seigneur; il fit le mal plus que tous ceux qui avaient régné avant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Il marcha dans toutes les voies de Jéroboam, fils de Nabat, et dans les péchés où il avait fait tomber tout Israël qui, par ses vanités, avait irrité le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Quant au reste de l’histoire d’Ambri, aux actions qu’il fit dans sa puissance, ne sont-ils pas écrits au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Et Ambri s’endormit avec ses pères; il fut inhumé à Samarie, et son fils Achab régna à sa place. En la onzième année du règne d’Ambri, Josaphat, fils d’Asa, âgé de trente-cinq ans, monta sur le trône de Juda, et il régna vingt-cinq ans à Jérusalem. Sa mère, fille de Seli, se nommait Gazuba. Il marcha dans la voie d’Asa, son père; il ne s’en écarta pas, et il ne cessa point d’être droit devant le Seigneur. Toutefois, il ne détruisit point les hauts lieux; on Y sacrifiait encore, on y brûlait de l’encens. Quant à ce qu’il fit de concert avec le roi d’Israël, à toutes les actions qu’il fit en sa puissance, à toutes ses guerres, ne sont-ils pas écrits au livre des Faits et gestes des rois de Juda? Le reste des réunions d’initiés, qui s’étaient rétablies au temps de son père Asa, il le fit disparaître de la terre promise. En ce temps-là, il n’y avait point de roi dans la Syrie, mais un Nasib. Le roi Josaphat construisit un vaisseau à Tharsis, afin d’aller à Ophir chercher de l’or; mais il ne partit pas, parce qu’il fut brisé en Asion - Gaber. Alors, le roi d’Israël dit à Josaphat: J’enverrai mes serviteurs avec les tiens sur un vaisseau; mais Josaphat ne le voulut pas. Et Josaphat s’endormit avec ses pères; il fut enseveli auprès d’eux dans la ville de David, et son fils Joram régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'La seconde année du règne de Josaphat en Juda, Achab commença, dans Samarie, un règne de vingtdeux ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Et Achab fit le mal devant le Seigneur; il fit le mal plus que tous ceux qui avaient régné avant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Il ne lui suffit pas de marcher dans les péchés de Jéroboam, fils de Nabat; il prit pour femme Jézabel, fille d’Ethbaal, roi des Sidoniens; il l’imita, il servit Baal, et l’adora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Et il éleva un autel à Baal dans le temple d’abomination qu’il avait bâti à Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Il planta un bois sacré, et il continua ses abominations pour irriter le Seigneur et perdre son âme. Il fit le mal plus que tous ceux qui, avant lui, avaient régné sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'En ces jours-là, Achiel le Béthélite rebâtit Jéricho en sacrifiant son premier-né, Abiron, qui mourut comme il jetait les fondations; et Segub, le plus jeune de ses tils, qui mourut quand il posa les portes, selon la parole que le Seigneur avait dite par la voix de Josué, fils de Nau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Or, Elie le prophète thesbite, de Thesba en Galaad, dit à Achab: Vive le Seigneur, Dieu des armées, Dieu d’Israël, devant qui je suis, il n’y aura en ces années ni rosée ni pluie, sinon à ma voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Et la parole du Seigneur vint à Élie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Va-t’en d’ici du côté de l’orient, et cache-toi dans le torrent de Chorrath, en face du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Tu boiras de l’eau du torrent, et j’ordonnerai aux corbeaux de te nourrir en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Et Elie fit selon la parole du Seigneur; il s’établit dans le torrent de Chorrath, en face du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Et les corbeaux lui apportèrent des pains à l’aurore, et des chairs le soir; et il but de l’eau du torrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Quelque temps après le torrent se tarit, car il n’y eut point de pluie sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Et la parole du Seigneur vint à Elie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Lève-toi et va-t’en à Sarepta chez les Sidoniens; là, j’ai prescrit à une femme veuve de te nourrir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Et il se leva, et il partit pour Sarepta; arrivé devant les portes de la ville, il y vit une femme veuve qui ramassait du bois. Et Elie cria après elle, et il lui dit: Prends un peu d’eau dans une cruche, et je boirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Elle en alla prendre; puis, le prophète cria après elle, et il lui dit: Apporte-moi un morceau du pain que tu as en ta maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Mais la femme répondit: Vive le Seigneur ton Dieu! je n’ai pas un seul pain cuit, je n’ai qu’un peu de farine dans la maie et quelques gouttes d’huile dans la fiole; je vais ramasser deux petits morceaux de bois; puis, je');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elie répliqua: Rassure-toi; rentre et fais ce que tu viens de dire; fais de plus pour moi un petit pain; tu me l’apporteras d’abord, tu en feras ensuite pour toi et pour tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Car voici ce que dit le Seigneur: La maie ne manquera plus de farine, et l’huile ne baissera plus dans la fiole, jusqu’au jour où le Seigneur donnera de la pluie à la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Et la femme s’en alla; elle pétrit, elle mangea; et le prophète et ses enfants mangèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Et la maie ne manqua plus de farine, et l’huile ne baissa pas dans la fiole, selon la parole que le Seigneur avait dite par la voix d’Elie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Après cela, le fils de la femme maîtresse de la maison tomba malade, et sa maladie fut très-violente; enfin le souffle de la vie se retira de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Et la femme dit à Elie: Qu’y a-t-il entre moi et toi, homme de Dieu? Es-tu venu chez moi pour rappeler le souvenir de mes péchés, et pour faire mourir mon fils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Et le prophète répondit à la femme: Donne-moi ton fils. Et il le prit de son sein; et il le porta dans la chambre où il demeurait, et il l’étendit sur sa couche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Là, il cria et il dit: Malheur à moi, Seigneur! je vous prends à témoin en faveur de cette veuve chez qui j’habite; vous l’avez affligée en faisant mourir son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Ensuite, il souffla trois fois sur l’enfant, il invoqua le Seigneur, et il dit: Seigneur mon Dieu, que l’âme de cet enfant revienne en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Et il en fut ainsi. L’enfant jeta un grand cri;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Et Elie descendit de sa chambre dans la maison, et il le rendit à sa mère; et il lui dit: Regarde, ton enfant est en vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Et la femme dit à Elie: Je reconnais que tu es un homme de Dieu; la parole de Dieu dans ta bouche est véritable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Après bien des jours, la parole du Seigneur vint à Élie pendant la troisième année, disant: Pars, présente-toi devant Achab, et je donnerai de la pluie à la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Et Elie partit pour se présenter devant Achab. En ce temps-là, il y avait à Samarie une famine trèsgrande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Et Achab appela son économe Abdias; or, Abdias craignait beaucoup le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Quand Jézabel frappait les prophètes du Seigneur, Abdias avait pris cent hommes qui prophétisaient; il les avait cachés cinquante par cinquante dans des cavernes où il les avait nourris de pain et d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Et Achab dit à Abdias: Viens, parcourons la contrée, visitons les torrents et les fontaines; peut-être trouverons-nous de l’herbe; nous y ferons paître les chevaux et les mules, et ils ne périront pas dans les étables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Et ils se partagèrent les territoires à visiter; Achab prit une route; Abdias, de son côté, en prit une autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Comme Abdias s’en allait seul sur un chemin, Elie arriva seul à sa rencontre. Abdias, pressant le pas, tomba la face contre terre, et il dit: Est-ce bien toi, Elie, mon maître?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Elie répondit: C’est moi; pars, et dis à ton maître: Voici Elie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Abdias reprit: Quel péché ai-je fait pour que tu livres ton serviteur aux mains d’Achab, afin qu’il me fasse mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Vive le Seigneur ton Dieu! il n’est ni peuple ni royaume où mon maître n’ait envoyé pour te prendre, et quand on disait: Élie n’est pas ici, il portait la flamme en ce royaume et en ses campagnes, parce qu’il ne t’avait point trouvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Et maintenant, tu veux que je parte et que je dise à ton maître: Voici Élie!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Voici ce qui adviendra: Lorsque je me serai éloigné de toi, l’Esprit du Seigneur te ravira en une terre je ne sais laquelle; et je me présenterai devant Achab et je t’annoncerai; mais lui, ne te trouvant pas, me fera mourir; or, ton serviteur, depuis son enfance, a la crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Ne sais-tu pas, ô mon maître, que quand Jézabel tuait les prophètes du Seigneur, j’ai caché cent prophètes du Seigneur, cinquante par cinquante, en des cavernes, et que je les ai nourris de pain et d’eau?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Et maintenant, tu veux que je parte et que je dise à mon maître: Voici Elie! Mais il me tuera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elie reprit: Vive le Seigneur Dieu des armées, devant qui je suis! aujourd’hui même Achab me verra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Abdias alla donc à la rencontre d’Achab; il lui annonça le prophète, et Achab accourut au-devant d’Elie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Aussitôt qu’il aperçut Elie, il s’écria: Es-tu donc celui qui pervertit Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Et le prophète répondit: Ce n’est point moi qui pervertis Israël, mais toi-même et la maison de ton père; car, vous abandonnez le Seigneur votre Dieu pour suivre Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Donne à ce moment tes ordres: rassemble devant moi, sur le mont Carmel, tout le peuple des dix tribus avec les quatre cent cinquante prophètes de l’opprobre, et les quatre cents prophètes des bois sacrés, qui mangent à la table de Jézabel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Et Achab envoya par tout Israël; et il rassembla sur le mont Carmel tous les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Devant eux tous, il mena Elie, et celui-ci leur dit: Jusqu’à quand boiterez-vous des deux jambes? Si le Seigneur est Dieu, suivez le Seigneur; si Baal est Dieu, suivez Baal. Et le peuple ne souffla mot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Elie dit ensuite au peuple: Il n’y a plus que moi de prophète du Seigneur; les prophètes de Baal sont quatre cent cinquante, et les prophètes des bois sacrés quatre cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Que l’on nous donne deux bœufs; qu’ils en choisissent un pour eux, qu’ils le séparent par membres, qu’ils le posent sur le bûcher sans qu’on y mette le feu; moi cependant j’apprêterai de même l’autre bœuf, et je n’allumerai point le bûcher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Criez alors au nom de vos dieux, et moi j’invoquerai le nom du Seigneur mon Dieu; le Dieu qui nous exaucera en envoyant de la flamme, celui-là est Dieu. A ces mots tout le peuple répondit, et il dit: Tu as bien parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Aussitôt, Elie dit aux prophètes de l’opprobre: Choisissez pour vous l’un des bœufs, et apprêtez-le les premiers, car vous êtes nombreux; invoquez le nom de vos dieux, et n’allumez pas le bûcher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Ils prirent le bœuf, ils l’apprêtèrent, ils invoquèrent le nom de Baal depuis l’aurore jusqu’au milieu du jour, et ils dirent: Exaucez-nous, ô Baal, exauceznous. Mais il n’y avait point de voix pour leur répondre, point d’oreilles pour les ouir, et ils passaient et repassaient devant l’autel qu’ils avaient élevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Le milieu du jour vint, et le Thesbite Elie les railla, et il dit: Invoquez-le à grands cris, puisque vous le dites dieu; il est peut-être à méditer, il est peut-être en affaire, ou peut-être il dort, et il se réve illera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Ils firent donc leurs invocations à grands cris; puis, selon leurs rites, ils se firent des entailles avec des poignards et des lancettes, de telle sorte que le sang ruissela sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Et ils prophétisèrent jusqu’à ce que le soleil commençât à décliner. Le moment étant venu où l’on place sur l’autel les victimes, Elie le Thesbite dit aux prophètes des abominations: Retirez-vous maintenant, et je ferai mon holocauste. Et ils se retirèrent, et ils partirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Alors, Elie dit au peuple: Approchez-vous de moi, et tout le peuple s’approcha de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Et Elie prit douze pierres selon le nombre des tribus issues d’Israël à qui le Seigneur avait dit: Israël sera ton nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Et il mit en œuvre ces pierres au nom du Seigneur, et il répara l’autel qui avait été renversé; autour de l’autel il creusa une rigole, qui eût contenu deux mesures de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Et il empila du bois fendu sur l’autel qu’il avait construit, sépara par membres l’holocauste, le posa sur les éclats de bois, et l’empila sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Puis, il dit: Prenez-moi quatre cruches d’eau que vous répandrez sur l’holocauste et sur le bois. Ainsi firentils, et il dit: Redoublez; ils redoublèrent, et il dit: Recommencez une troisième fois, et ils recommencèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Et l’eau coula autour de l’autel, et la rigole en fut remplie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Et Elie cria au ciel, disant: Seigneur Dieu d’Abraham, d’Isaac et d’Israël, exaucez-moi, Seigneur, exaucez-moi aujourd’hui en m’envoyant de la flamme; que tout le peuple reconnaisse que vous êtes le Seigneur Dieu d’Israël, que je suis votre serviteur, et que je n’ai rien sinon par vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Exaucez-moi, Seigneur, exaucez-moi; que le peuple reconnaisse que vous êtes le Seigneur Dieu, et vous convertirez le cœur de ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Et une flamme descendit du ciel, envoyée par le Seigneur; elle dévora l’holocauste, le bûcher, l’eau de la rigole; elle effleura les pierres de l’autel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Et le peuple tomba la face contre terre, et il dit: En vérité, le Seigneur Dieu est le seul Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elie dit ensuite au peuple: Saisissez les prophètes de Baal, que pas un seul ne soit épargné. Ils les saisirent, et Elie les traîna au torrent de Cisson, et là, il les égorgea.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Elie dit ensuite à Achab: Pars, mange et bois; car il y a un bruit de pluie qui arrive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Et Achab partit pour manger et boire; et le prophète monta sur le Carmel; là, il se pencha vers la terre, la tête entre les genoux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Puis, il dit à son serviteur: Va, et regarde du côté de la mer. Le serviteur regarda, et il dit: Il n’y a rien. Mais son maître lui dit: Retournes-y sept fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Et le serviteur y retourna sept fois; à la septième fois il vit un petit nuage semblable au pied d’un homme, et ce nuage amenait de l’eau; le maître alors dit au serviteur: Va trouver Achab, et dis-lui: Attelle ton char et mets-toi en route, de peur que la pluie ne te surprenne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Bientôt çà et là le ciel s’obscurcit de nuées, le vent souffla, et il tomba une grande pluie. Et Achab, en pleurant, s’en alla à Jezraël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Et la main du Seigneur s’étendit sur Élie, et il serra sur ses reins sa ceinture, et il courut devant Achab jusqu’à Jezraël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Et Achab apprit à Jézabel sa femme tout ce qu’avait fait Élie, et comment il avait tué les prophètes par l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Et Jézabel envoya chez Élie, et elle dit: Si tu es Élie, moi je suis Jézabel: que Dieu me punisse et me punisse encore, si demain, à pareille heure, je n’ai pas fait de ta vie ce que tu as fait de la vie de chacun d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Et Élie eut crainte; il se leva; il s’éloigna pour sauver sa vie, et se rendit à Bersabée en Juda, où il laissa son serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Lui-même s’enfonça dans le désert à une journée de marche; il s’assit sous un genévrier, et il demanda la mort, disant: C’est assez, prenez maintenant mon âme, ô Seigneur, car je ne suis pas meilleur que mes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Et il se coucha et il s’endormit sous le genévrier; or voilà qu’un ange le toucha, et lui dit: Lève-toi et mange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Il regarda, et il vit auprès de sa tête des gâteaux d’épeautre et une fiole d’eau; il se leva, il mangea, il but et il s’endormit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'L’ange du Seigneur revint une seconde fois, le toucha, et lui dit: Lève-toi et mange, car tu as à faire un long chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Et il se leva; il mangea et il but, et il partit fortifié par ces aliments, et il marcha quarante jours et quarante nuits jusqu’au mont Horeb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Là, il entra dans la caverne; il en fit sa demeure, et la parole du Seigneur vint à lui, disant: Que fais-tu là, Elie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Le prophète répondit: J’ai eu le cœur rempli de zèle pour le Seigneur Tout-Puissant, parce que les fils d’Israël vous ont abandonné, qu’ils ont renversé vos autels, et tué par l’épée vos prophètes; seul j’ai survécu, et ils en veulent à ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Or, la voix reprit: Tu partiras demain; mais tienstoi devant le Seigneur sur la montagne, regarde: le Seigneur va passer. Aussitôt, voilà qu’un vent violent passa, déchirant la montagne, brisant les rochers, et le Seigneur n’était pas dans le vent; après le vent, il y eut un tremblement de terre, et le Seigneur n’était pas dans le tremblement de terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Après le tremblement de terre, vint une flamme, et le Seigneur n’était pas dans la flamme; après la flamme, vint le murmure d’un souffle léger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Quand Elie entendit ce souffle, il se voila le visage de son manteau de peau de brebis; puis, il sortit et il se tint à l’entrée de la caverne; alors, une voix s’approcha de lui, disant: Que fais-tu là, Elie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Et le prophète répondit: J’ai eu le cœur plein de zèle pour le Seigneur Tout-Puissant, parce que les fils d’Israël ont abandonné votre alliance, renversé vos autels, et tué par l’épée vos prophètes; seul j’ai survécu, et ils en veulent à ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Et le Seigneur lui dit: Pars, remets-toi en marche, prends le chemin du désert de Damas, tu iras, et tu sacreras Azaël pour être roi de Syrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Et tu sacreras Jéhu, fils de Namsi, pour être roi d’Israël; et tu sacreras Elisée, fils de Saphat, pour être prophète après toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Celui qu’épargnera l’épée d’Azaël, Jéhu le mettra à mort; celui qu’épargnera l’épée de Jéhu, Elisée le mettra à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Et je me réserve, en Israël, sept mille hommes, les seuls qui n’aient point fléchi le genou devant Baal, les seuls dont la bouche ne l’ait point adoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Et Elie partit de ce lieu, et il trouva Elisée, fils de Saphat; celui-ci labourait avec des bœufs; il avait devant lui douze attelages, et seul il les conduisait. Le prophète alla droit à Elisée, et jeta sur lui son manteau de peau de brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Et Elisée abandonna ses bœufs; il suivit à grands pas Elie, et il lui dit: Je vais embrasser mon père; puis, je t’accompagnerai. Elie reprit: Reviens, car j’ai travaillé pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Et il s’éloigna d’Elie, il prit ses couples de bœufs, il les sacrifia, il les fit cuire avec l’attirail des attelages, il les donna au peuple, et il mangea; enfin il rejoignit Elie et il le servit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Et Naboth le Jezraélite avait une vigne attenante à l’aire d’Achab, roi de Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Et Achab parla à Naboth, disant: Donne - moi ta vigne, j’en ferai mon jardin potager, car elle près de ma demeure; je te donnerai une vigne meilleure que la tienne. Si tu le préfères, je te donnerai de l’argent pour prix de ta vigne, et elle sera mon jardin potager.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Mais, Nabaoth dit à Achab: Dieu me préserve de te donner l’héritage de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Et l’esprit d’Achab fut troublé; il s’étendit sur sa couche, se voila le visage, et ne mangea pas de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Et Jézabel sa femme entra vers lui, et elle lui dit: D’où vient que tu as l’esprit troublé, et que tu ne manges pas de pain?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Il lui répondit: C’est parce que j’ai parlé à Naboth le Jezraélite, disant: Donne-moi à prix d’argent ta vigne, ou, si tu veux, je te donnerai en échange une autre vigne, et qu’il m’a répondu: Je ne te donnerai pas l’héritage de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Jézabel sa femme lui dit: Conduis-toi donc en roi envers Israël, lève-toi, mange du pain, reviens à toi, et moi je te donnerai la vigne de Naboth le Jezraélite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Ensuite, elle écrivit au nom d’Achab une lettre qu’elle scella du sceau royal, et elle l’envoya aux anciens et aux premiers de la ville qui demeuraient avec Naboth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Or, elle avait écrit ceci dans la lettre: Ordonnez un jeûne et faites asseoir Naboth parmi les premiers du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Puis, devant lui, apostez deux hommes, fils de pervers, qui portent témoignage contre lui, disant: I a blasphémé contre Dieu et le roi, qu’on l’emmène, qu’on le lapide, qu’il meure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Et les hommes de sa ville, les anciens et les plus riches qui demeuraient avec lui, firent comme avait dit Jézabel dans la lettre qu’elle leur avait envoyée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Ils ordonnèrent un jeûne, ils firent asseoir Naboth parmi les chefs du peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Et les deux hommes, fils de pervers, entrèrent, et ils s’assirent devant Naboth, et ils portèrent témoignage contre lui, disant: Tu as blasphémé contre Dieu et le roi. Et on l’emmena hors de la ville, on le lapida, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Puis, on envoya un message à Jézabel, disant: Naboth a été lapidé et il est mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Dès que Jézabel eut ouï le message, elle dit à Achab: Lève-toi, hérite de la vigne de Naboth le Jezraélite, qui n’a point voulu te la donner à prix d’argent; car Naboth n’est plus vivant, il est mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Dès qu’Achab ouït que Naboth le Jezraélite était mort, il déchira ses vêtements et se couvrit d’un cilice; mais ensuite, il se leva, et il alla à la vigne de Naboth pour en prendre possession.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Et le Seigneur parla à Elie le Thesbite, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Lève-toi, va trouver Achab, roi d’Israël, à Samarie, car il est dans la vigne de Naboth; il y est allé pour en prendre possession.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Et tu lui parleras, disant: Voici que dit le Seigneur: Comme tu as tué et hérité, voici, à cause de cela, ce que dit le Seigneur: En tout lieu où les chiens et les pourceaux ont léché le sang de Naboth, les chiens lècheront ton sang, et les prostituées se baigneront dans ton sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Et Achab dit à Elie: Tu m’as donc trouvé, ô mon ennemi? Le prophète répondit: Je t’ai trouvé, en ce que tu t’es follement vendu pour faire le mal devant le Seigneur, et l’irriter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Et c’est moi qui ferai fondre sur toi les malheurs, qui allumerai le feu après toi, qui détruirai tout måle de la maison d’Achab, tout ce qui est enfermé, tout ce qui reste encore en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Et je ferai de ta maison ce que j’ai fait de la maison de Jeroboam, fils de Nabat, et de la maison de Baasa, fils d’Achias, parce que tu m’as irrité et que tu as fait tomber dans le péché tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Ensuite, le Seigneur s’adressant à Jézabel lui dit Les chiens te dévoreront dans les murs de Jezraël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Celui de la maison d’Achab qui mourra dans la ville, les chiens le dévoreront; celui qui mourra dans les champs, sera dévoré par les oiseaux du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Quant à Achab, il a follement agi en se vendant pour faire le mal devant le Seigneur, perverti par sa femme Jézabel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Il s’est rendu très-abominable pour avoir marché à la suite des idoles, et imité tout ce que faisait l’Amorrhéen que le Seigneur a exterminé devant la face des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'A ces mots, Achab fut tout contrit devant la face du Seigneur; il s’en alla pleurant; il déchira sa tunique, il se couvrit le corps d’un cilice et il jeûna (il s’était déjà enveloppé d’un cilice le jour où il avait frappé Naboth le Jezraélite); et il s’en alla tout humilié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Et la parole du Seigneur vint encore à son serviteur Elie au sujet d’Achab, et le Seigneur lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'As-tu vu comme Achab était contrit devant ma face? Je ne ferai point fondre sur lui ces malheurs de son vivant, mais ce sera du vivant de son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Cependant Ben-Ader rassembla toute son armée, partit et assiégea Samarie; il avait avec lui trente-deux rois, toute sa cavalerie et tous ses chars. Et ils se mirent en campagne; ils assiégèrent Samarie, et ils donnèrent l’assaut à ses remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Puis, le roi de Syrie envoya dans la ville dire à Achab, roi d’Israël: Voici ce que dit Ben-Ader:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Ton argent et ton or m’appartiennent; tes femmes et tes enfants m’appartiennent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Le roi d’Israël répondit: Comme tu l’as dit, ô roi mon maître, je t’appartiens, et toutes les choses que je possède.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Les messagers vinrent encore, et ils dirent: Voici ce que dit Ben-Ader: Je t’ai envoyé dire: Tu me livreras ton argent et ton or, et tes femmes et tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Demain donc, à pareille heure, j’enverrai près de toi mes serviteurs; ils fouilleront dans ta maison et dans les maisons de tes serviteurs, et ils prendront toutes les choses désirables à leurs yeux, sur lesquelles ils auront mis la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Alors, le roi d’Israël convoqua tous les anciens de la terre promise, et il dit: Écoutez, voyez quelle lâcheté demande cet homme il me demande mes femmes, mes fils et mes filles. Quant à mon argent et à mon or, je ne les lui ai point refusés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Et les anciens et tout le peuple s’écrièrent: Ne l’écoute pas, n’y consens point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Il dit donc aux messagers de Ben-Ader: Dites à votre maître Toutes les choses pour lesquelles tu as d’abord envoyé à ton serviteur, je les ferai, mais cette dernière chose je ne puis la faire. Et les hommes partirent, et ils rapportèrent sa réponse à leur maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Ben-Ader envoya encore à lui, disant: Que le Seigneur me punisse, et qu’il me punisse encore, si votre tanière à renards de Samarie suffit pour contenir les piétons de mon armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Le roi d’Israël reprit: C’est assez que le ne se glorifie pas comme l’homme qui se tient droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Lorsque cette réponse fut rapportée au Syrien, il était à boire sous sa tente avec tous les rois ses alliés, et il dit à ses serviteurs: Élevez un retranchement. Ils firent donc un retranchement autour de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Or, voilà qu’un prophète arriva devant Achab, roi d’Israël, et dit: Voici ce que dit le Seigneur: As-tu vu cette innombrable multitude? Eh bien! aujourd’hui je te la livre, et tu reconnaîtras que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Et Achab demanda: Par qui? Et le prophète reprit Voici ce que dit le Seigneur: Par les jeunes fils des chefs des provinces. Et Achab dit: Qui commencera le combat? Le prophète répondit: Toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Et Achab passa en revue les jeunes fils des chefs des provinces; ils étaient deux cent trente; après cela, il passa en revue l’armée, toute formée d’hommes vaillants; il y en avait sept mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Puis, il sortit au milieu du jour, comme Ben-Ader était à boire et à s’enivrer en Socchoth, lui et les trentedeux rois ses alliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Et les jeunes fils des chefs des provinces sortirent d’abord; on l’alla rapporter au roi de Syrie, disant: Des hommes sont arrivés de Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Et il répondit: S’ils viennent en paix, prenez-les vivants; s’ils viennent en guerre, prenez-les vivants. 19. Et les jeunes fils des chefs des provinces sortirent de la ville; cependant l’armée les suivait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Et chacun frappa l’homme le plus près de lui; puis, une seconde fois, chacun frappa l’homme le plus près de lui; aussitôt, la Syrie prit la fuite, Israël la poursuivit, et Ben-Ader s’échappa sur le cheval d’un simple cavalier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Et le roi d’Israël sortit; il prit tous les chevaux avec les chars, et il fit des Syriens un grand carnage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Ensuite, le prophète alla trouver le roi d’Israël, à qui il dit: Fortifie-toi, observe, et vois ce que tu as à faire; car, l’année révolue, Ben-Ader, roi de Syrie, reviendra contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Et les serviteurs du roi de Syrie lui dirent: Le Dieu d’Israël est le Dieu des montagnes, et non le Dieu des vallées; voilà pourquoi ils nous ont vaincus; si nous leur faisons la guerre dans la plaine, nous l’emporterons sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Fais ceci: renvoie les rois chacun en leur demeure, remplace-les par les princes des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Et nous te donnerons une autre armée aussi nombreuse que celle qui a été détruite; un cheval remplacera un cheval, des chars remplaceront les chars; nous les combattrons dans la plaine, et nous l’emporterons sur eux. Et le roi les écouta, et il fit ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'L’année révolue, Ben-Ader passa en revue les forces de la Syrie, et il se porta en Aphèca pour combattre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Les fils d’Israël aussi passèrent en revue leur armée, et ils marchèrent contre eux. Et Israël campa vis-à-vis leur camp; ils étaient comme deux troupeaux de chèvres, et les Syriens remplissaient la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Alors, l’homme de Dieu revint, et il dit au roi d’Israël: Voici ce que dit le Seigneur: En punition de ce que la Syrie a dit Le Dieu d’Israël est le Dieu des montagnes et non le Dieu des vallées, je te livrerai cette armée innombrable, et tu reconnaîtras que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Et les deux camps restèrent sept jours l’un vis-àvis de l’autre; le septième jour la bataille s’engagea, et Israël tua aux Syriens cent mille piétons en une seule journée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 30, 'Et les survivants se réfugièrent dans Aphèca, dont les murs s’écroulèrent sur vingt-sept mille de ceux qui s’étaient échappés; Ben-Ader se cacha dans l’alcôve d’une chambre à coucher;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 31, 'Et il dit à ses serviteurs Je sais que les rois d’Israël sont des rois miséricordieux; couvrons nos reins de cilices, passons-nous des cordes autour du cou, et sortons au-devant du roi d’Israël; peut-être il nous renverra la vie sauve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 32, 'Et ils se couvrirent les reins de cilices; ils se passèrent des cordes autour du cou, et ils dirent au roi d’Israël Ton serviteur Ben-Ader dit: Que j’aie la vie sauve. Achab répondit: Vit-il encore? Il est mon frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 33, 'Les serviteurs en tirèrent bon présage; ils firent des libations, et ils s’emparèrent de la parole qui était sortie de la bouche d’Achab, et ils dirent: Ben-Ader est ton frère. Il reprit: Allez le chercher et amenez-le. Ben-Ader sortit de sa retraite pour aller près d’Achab, et ses serviteurs le firent monter auprès de lui sur un char.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 34, 'Et Achab dit: Je te rendrai les villes que mon père a prises au tien; tu pourras te faire des issues à Damas, comme mon père en a fait à Samarie, et je te renverrai après avoir conclu alliance avec toi. Et ils firent alliance, et il le renvoya.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 35, 'Mais un homme, l’un des fils des prophètes, dit, d’après la parole du Seigneur, à son voisin: Frappe-moi. Mais l’autre ne voulut pas le frapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 36, 'Et le prophète lui dit: En punition de ce que tu');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 37, 'Et le prophète alla trouver un autre homme, et il lui dit Frappe-moi. L’homme le frappa, le frappa encore, et l’accabla de coups.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 38, 'Ensuite, le prophète partit, et il se tint sur le chemin qu’avait pris le roi; or, il s’était bandé les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 39, 'Quand le roi vint à passer, il cria après lui, disant: Ton serviteur est allé à la guerre, et voilà qu’un homme m’a amené un homme, et m’a dit: Garde cet homme; s’il s’échappe, tu me donneras ta vie pour sa vie, ou tu paieras un talent d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 40, 'Mais ton serviteur a eu beau regarder tout alentour çà et là, l’homme s’est évadé. A ces mots, le roi d’Israël s’écria: Tu me tends un piége; tu l’as tué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 41, 'Et le prophète se hâta d’ôter le bandeau qui couvrait ses yeux. Alors, le roi reconnut que c’était l’un des prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 42, 'Et le prophète lui dit: Voici ce que dit le Seigneur: Parce que tu as laissé échapper un méchant homme, ta vie pour sa vie, ton peuple pour son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 43, 'Le roi d’Israël s’en alla donc confondu et attristé; puis, il rentra dans Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Et il y demeura trois ans, sans qu’il y eût guerre entre Israël et la Syrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Pendant la troisième année, Josaphat, roi de Juda, alla visiter le roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Or, le roi d’Israël dit à ses serviteurs: Savez-vous que Ramoth-Galaad nous appartient, et que nous gardons le silence sans la réclamer du roi de Syrie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Puis, le roi d’Israël dit à Josaphat: Viendras-tu avec nous reprendre Ramoth-Galaad?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Josaphat répondit: Comme je suis, tu es; ton peuple est comme mon peuple, tes chevaux sont comme mes chevaux. Et Josaphat, roi de Juda, dit encore au roi d’Israël Consulte aujourd’hui le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Le roi d’Israël rassembla donc tous les prophètes, environ quatre cents, et il leur dit: Irai-je en guerre à Ramoth-Galaad ou m’abstiendrai-je? Ils répondirent: Marche, et le Seigneur la livrera aux mains du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Et Josaphat dit au roi d’Israël: N’y a-t-il pas ici un prophète du Seigneur par qui nous puissions consulter le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Le roi d’Israël répondit à Josaphat: Il y a ici un homme par qui l’on peut consulter le Seigneur; mais je le hais, parce qu’il me dit non de bonnes, mais de mauvaises choses; c’est Michée, fils de Jemla. Josaphat reprit Que le roi ne parle pas ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Et le roi d’Israël appela un eunuque, et il lui dit: Amene ici tout de suite Michée, fils de Jemla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Or, le roi d’Israël et Josaphat, roi de Juda, couverts de leurs armures, étaient assis chacun sur leur trône, vers la porte de Samarie, et tous les prophètes prophétisaient devant eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Et Sédécias, Chananéen, s’était fait des cornes de fer, disant: Voici ce que dit le Seigneur: Avec ces cornes, tu frapperas la Syrie jusqu’à ce qu’elle soit détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'En même temps, tous les prophètes prophétisaient ainsi: Marche sur Ramoth-Galaad, tu réussiras; le Seigneur livrera à tes mains le roi de Syrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Et le messager qui était allé quérir Michée, lui dit: Voilà que tous les prophètes, tout d’une voix, disent de bonnes choses concernant le roi. Sois donc aussi en paroles comme l’un d’eux, et dis de bonnes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Mais Michée reprit: Vive le Seigneur! ce que le Seigneur me dira, je le répèterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Puis, il alla devant le roi, et le roi lui dit: Michée, irai-je en guerre à Ramoth-Galaad, ou m’abstiendrai-je? Et il répondit: Marche, le Seigneur fera réussir ce qui est dans les mains du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Et le roi lui dit: Combien de fois t’adjurerai-je, pour que tu me dises la vérité au nom du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Michée répondit: Il n’en est pas ainsi; car j’ai vu tout Israël dispersé dans les montagnes comme un troupeau sans pasteur. Et le Seigneur a dit: Le Seigneur n’est-il point leur Dieu? Que chacun aille en paix en sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Et le roi d’Israël dit à Josaphat, roi de Juda: Ne te l’ai-je point dit que cet homme me prophétise non de bonnes, mais de mauvaises choses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Michée reprit: Non pas, ce n’est point moi; écoute la parole du Seigneur; ce n’est pas ainsi: j’ai vu le Dieu d’Israël assis sur son trône, et toute l’armée du ciel se tenait près de lui à sa droite et à sa gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Et le Seigneur dit: Qui trompera Achab, roi d’Israël, pour qu’il parte en campagne, et qu’il succombe à Ramoth-Galaad? Et l’un répondait d’une sorte, et l’autre d’une autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Quand un esprit s’avançant, se plaça devant le Seigneur, et dit: C’est moi qui le tromperai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Et le Seigneur lui dit: De quelle manière? Et il reprit Je partirai, et je serai un esprit trompeur dans la bouche de tous ses prophètes. Puis, le Seigneur dit: Tu le tromperas, tu prévaudras; va, et fais ce que tu as dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Voilà donc que maintenant le Seigneur a placé un esprit trompeur dans la bouche de tous tes prophètes; car le Seigneur a dit sur toi de mauvaises choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Et Sédécias le Chananéen, s’avançant, frappa Michée à la joue, et il dit: Quel est l’esprit du Seigneur qui parle par ta voix?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Michée reprit: Tu le verras le jour où tu fuiras de chambre en chambre pour t’y cacher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Et le roi d’Israël dit: Prenez Michée; menez-le à Semer, chef de la ville, et dites à Joas, fils du chef,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'De mettre cet homme en prison, où on le nourrira du pain et de l’eau de l’affliction, jusqu’à ce que je revienne en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Et Michée reprit: Si tu reviens en paix, le Seigneur n’a point parlé par ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Le roi d’Israël partit avec Josaphat, roi de Juda, pour Ramoth-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Et le roi d’Israël dit au roi de Juda: Je me déguiserai, et j’engagerai la bataille, et tu auras mes vêtements. Le roi d’Israël se déguisa donc, et il engagea la bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Or, le roi de Syrie donna cet ordre aux trente-deux chefs de ses chars: N’attaquez ni petit ni grand, mais le roi d’Israël seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Quand les chefs des chars virent Josaphat, roi de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Aussitôt qu’ils reconnurent que ce n’était pas le roi d’Israël, ils s’éloignèrent de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Et l’un d’eux tendit son arc, visa droit au but, et frappa le roi d’Israël entre le poumon et la poitrine. Le roi dit alors à son cocher: Tourne bride, et emmène-moi hors de la mêlée; j’ai une blessure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Et, ce jour-là, le combat tournait en déroute; Achab resta sur son char, devant les Syriens, depuis le matin jusqu’au soir; il perdit, par sa blessure, des flots de sang qui coulèrent jusqu’au fond du char; et le soir, il mourut; et, depuis qu’il avait fui, son sang avait coulé jusqu’au fond du char.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Au coucher du soleil, le héraut de l’armée s’arrêta, disant: Que chacun retourne en sa ville et en sa terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Car le roi est mort. Ceux d’Israël revinrent donc à Samarie, et ils ensevelirent le roi dans cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Or, ils lavèrent le char à la fontaine de Samarie; les pourceaux et les chiens léchèrent le sang, et les prostituées se baignèrent dans le sang, selon la parole que le Seigneur avait dite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Quant au reste de l’histoire d’Achab, à la description du palais d’ivoire qu’il éleva, et de toutes les villes qu’il bâtit, ne sont-ils pas écrits au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Achab s’étant endormi avec ses pères, son fils Ochozias régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Cependant, Josaphat, fils d’Asa, régna sur Juda; son règne avait commencé la quatrième année de celui d’Achab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Il avait alors trente-cinq ans, et il régna vingt');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Et il marcha dans la voie d’Asa, son père; il ne s’en écarta point, et il fut agréable aux yeux du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Seulement, il ne détruisit point les hauts lieux; le peuple y sacrifiait encore, et l’on y brûlait de l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Et Josaphat vécut en paix avec le roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Quant au reste de l’histoire de Josaphat et de ses actions dans sa puissance, n’est-il pas écrit au livre des faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Et Josaphat s’endormit avec ses pères; il fut enseveli auprès d’eux en la ville de David, son aïeul, et son fils Joram régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Et Ochozias, fils d’Achab, régna sur Israël en Samarie; son règne commença la dix-septième année de celui de Josaphat, et il dura deux ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Et il fit le mal devant le Seigneur; il marcha dans la voie d’Achab, son père, dans la voie de Jézabel, sa mère, et dans le péché où la maison de Jéroboam, fils de Nabat, fit tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Il servit Baal, et il l’adora; il irrita le Seigneur Dieu d’Israël, de la même manière qu’on l’avait irrité avant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Après la mort d’Achab, Moab se souleva contre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Et Ochozias tomba à travers le treillis de sa chambre haute, en Samarie; il en fut malade; et il fit partir des messagers auxquels il dit: Allez demander à Baal-Mouche, dieu d’Accaron, si je survivrai à cette maladie? Ils partirent, et ils le questionnèrent pour leur roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Or, un ange du Seigneur appelant Élie le Thesbite, dit: Lève-toi, va à la rencontre des messagers d’Ochozias, roi de Samarie, et tu leur diras: Est-ce qu’il n’y a point de Dieu en Israël, que vous allez interroger Baal-Mouche, dieu d’Accaron? Il n’en sera pas ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Voici ce que dit le Seigneur: La couche sur laquelle tu es monté, tu n’en descendras plus; car assurément tu mourras. Élie partit donc, et il leur dit ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Et les messagers retournèrent auprès de leur maître, qui leur dit: Pourquoi êtes-vous revenus?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Ils répondirent: Un homme est venu à notre rencontre, il nous a dit: Retournez auprès du roi qui vous a envoyés, et dites-lui: Voici ce que dit le Seigneur: Est-ce qu’il n’y a point de Dieu en Israël, que tu vas consulter Baal-Mouche, le dieu d’Accaron? Il n’en sera point ainsi. La couche sur laquelle tu es montée, tu n’en descendras plus, car tu mourras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Ainsi, après leur retour, ils rapportèrent au roi les paroles d’Élie, et le roi leur dit: Comment est l’homme qui a été à votre rencontre, et qui vous a dit ces paroles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Ils reprirent: C’est un homme velu, qui est vêtu d’une peau de brebis. Et le roi s’écria: C’est Élie le Thesbite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Puis, il envoya vers lui un chef de cinquante hommes; le chef partit avec sa troupe, et il vit Élie assis sur la cime de la montagne, et il lui dit: Descends, homme de Dieu, le roi te demande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Or, Élie répondit: Si je suis un homme de Dieu, le feu du ciel va tomber et dévorer toi et tes cinquante hommes. Aussitôt, le feu du ciel tomba et dévora le chef avec sa troupe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Le roi lui envoya une seconde fois un chef et ses cinquante hommes. Et le chef dit à Élie Homme de Dieu Voici ce que dit le roi: Descends au plus vite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Le prophète répondit: Si je suis un homme de Dieu, le feu du ciel va tomber et dévorer toi et tes cinquante hommes. Aussitôt, le feu du ciel tomba, et dévora le chef avec sa troupe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Et le roi envoya encore un chef et ses cinquante hommes; et ce troisième chef partit, se mit à genoux devant Élie, le pria, et lui dit: Homme de Dieu, que ma vie et celle de ces cinquante hommes, tes serviteurs, ne soient pas sans prix à tes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Le feu du ciel est tombé et a dévoré déjà deux chefs de cinquante hommes; maintenant donc, que ma vie ne soit pas sans prix à tes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Or, l’ange du Seigneur dit au prophète: Descends avec lui, ne crains rien d’eux. Et le prophète se leva, et il se rendit avec eux au-devant du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Et il lui dit: Voici ce que dit le Seigneur: Pourquoi as-tu envoyé des messagers consulter Baal-Mouche, dieu d’Accaron? Ce ne sera point ainsi: la couche sur laquelle tu es monté, tu n’en descendras plus, car tu mourras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Il mourut, en effet, selon la parole du Seigneur que le prophète lui avait dite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Quant au reste de l’histoire d’Ochozias, n’est-il pas écrit au livre des faits et gestes des rois d’Israël? Et Joram, fils d’Achab, régna douze ans sur Israël en Samarie. Son règne commença la dix-huitième année de celui de Josaphat, roi de Juda. Et il fit le mal devant le Seigneur, mais point autant que ses frères et sa mère; il renversa même les colonnes que son père avaient élevées à Baal, et il les fit briser. Seulement, il resta attaché aux péchés qu’avait commis la maison de Jéroboam, et où elle avait fait tomber Israël. Il ne s’en corrigea pas, et la colère du Seigneur fut excitée contre la maison d’Achab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Or, dans le temps que le Seigneur ravit Élie, comme au ciel au milieu d’un tourbillon, Élie et Élisée sortirent de Galgala.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Et Élie dit à Élisée: Reste ici, car Dieu veut que j’aille jusqu’à Béthel. Élisée répondit: Vive le Seigneur, et vive ton âme, je ne te quitterai pas. Ils entrèrent donc à Béthel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Et les fils des prophètes qui étaient à Béthel, s’approchèrent d’Élisée, et ils lui dirent: Ne sais-tu pas qu’aujourd’hui le Seigneur doit ravir ton maître au-dessus de ta tête? Il répondit: Oui, je le sais, gardez le silence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Élie dit ensuite à Élisée: Reste ici, car Dieu veut que j’aille jusqu’à Jéricho. Et il répondit: Vive le Seigneur, et vive ton âme! je ne te quitterai pas. Ils entrèrent donc à Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Et les fils des prophètes qui étaient à Jéricho s’approchèrent d’Élisée, et ils lui dirent: Ne sais-tu pas qu’aujourd’hui le Seigneur doit ravir ton maître au-dessus de ta tête? Il répondit: Oui, je le sais, gardez le silence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Élie lui dit ensuite: Reste ici, le Seigneur veut que j’aille jusqu’au Jourdain. Élisée répondit: Vive le Seigneur et vive ton âme! je ne te quitterai point. Ils marchèrent donc tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Or, il y avait au loin, vis-à-vis d’eux, cinquante fils des prophètes, et ils s’arrêtèrent l’un et l’autre aux bords du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Et Élie prit sa peau de brebis, la fit tourner, et en frappa l’eau du fleuve et l’eau se sépara à leur droite et à leur gauche; ils passèrent tous les deux, et ils s’en furent dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Pendant qu’ils traversaient le Jourdain, Élie dit à Élisée Demande ce que je ferai pour toi avant d’être ravi loin de toi. Élisée répondit: Que j’aie part à ton double esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Élie reprit: Tu as demandé une chose difficile: si tu me vois quand je serai ravi d’auprès de toi, il en sera pour toi ainsi; sinon, cela ne sera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Ils parlaient ainsi en marchant, et voilà qu’un char de feu et des chevaux de feu les séparèrent l’un de l’autre; puis, Élie fut ravi dans un tourbillon comme au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Et Élisée le vit, et il cria: Père, père, char et conducteur d’Israël. Bientôt il ne le vit plus; et il saisit ses vêtements, et il les déchira en deux lambeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Ensuite, Élisée ramassa la peau de brebis qui était tombée de dessus Élie, et s’en retourna. Il s’arrêta aux bords du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Et il prit la peau de brebis qui était tombée de dessus Élie, en frappa l’eau du fleuve, et dit: Où est maintenant le Dieu d’Élie? Et il frappa les eaux, qui s’ouvrirent à droite et à gauche, et Élisée passa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Les fils des prophètes qui étaient à Jéricho, sur la rive opposée, le virent alors arriver, et dirent: L’esprit d’Élie est resté sur Élisée. Et ils allèrent à sa rencontre, et se prosternèrent devant lui la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Puis, ils lui dirent: Il y a avec tes serviteurs cinquante hommes vaillants; qu’ils partent, qu’ils s’informent de ton maître; est-ce que l’Esprit du Seigneur l’a ravi, et l’a jeté dans le Jourdain ou sur l’une des montagnes, ou sur l’une des collines? Mais Élisée répondit: N’envoyez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Ils le pressèrent tant qu’il en eut honte, il dit enfin Envoyez; en conséquence, ils firent partir cinquante hommes qui cherchèrent trois jours, et ne trouvèrent point Élie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Ils revinrent auprès d’Élisée, car il s’était établi à Jéricho, et il leur dit: Ne vous avais-je point dit: Ne partez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Or, les hommes de la ville dirent à Élisée: Voilà');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Et Élisée dit: Prenez-moi une cruche neuve et mettez-y du sel. Ils prirent donc une cruche, et la lui apportèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Ensuite, Élisée alla à la source, y versa le sel, et dit: Voici ce que dit le Seigneur: J’ai assaini ces eaux; il n’y aura plus ici ni mortalité ni stérilité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Et les eaux sont restées saines jusqu’à nos jours, selon la parole qu’avait dite Élisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'De là, il monta à Béthel, et comme il marchait dans le chemin, de petits enfants sortirent de la ville, le raillèrent, et lui dirent: Monte, chauve, monte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Il se retourna, les vit, et les maudit au nom du Seigneur; or, voilà que deux ours s’élancèrent de la forêt, et mirent en pièces quarante-deux de ces enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'De là, il alla au mont Carmel, puis il retourna à Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Et Joram, fils d’Achab, commença à régner sur Israël, la dix-huitième année du règne de Josaphat en Juda, et il régna douze ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Et il fit le mal aux yeux du Seigneur, mais point autant que son père et sa mère; il renversa même les colonnes de Baal que son père avait élevées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Seulement, il resta attaché au péché de Jéroboam, fils de Nabat, où celui-ci avait fait tomber Israël; il ne s’en éloigna point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Et Mosa, roi de Moab, était nourrisseur de troupeaux, et il rendait au roi d’Israël cent mille moutons et cent mille béliers dans leur toison, de ceux qu’il élevait chaque année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Après la mort d’Achab, le roi de Moab refusa son tribut au roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Et le roi Joram, ce jour-là, sortit de Samarie, et il passa en revue Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Il partit ensuite, et envoya des gens à Josaphat, roi de Juda, disant: Le roi de Moab m’a refusé son tribut: marcheras-tu avec Israël pour combattre Moab? Il répondit: Je marcherai; tu es comme moi, je suis comme toi; ton peuple est comme mon peuple; tes chevaux sont comme mes chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Et il ajouta: Quel chemin prendrai-je? Joram lui dit: Le chemin du désert d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Et le roi d’Israël partit avec le roi de Juda et le roi d’Edom; ils firent sept journées de marche; or, le camp manquait d’eau pour le bétail qui suivait l’armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Le roi d’Israël dit alors: Malheur à nous! le Seigneur a appelé, sur ce chemin, les trois rois pour les livrer aux mains de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Et Josaphat dit: N’y a-t-il point ici de prophète du Seigneur par qui nous puissions le consulter? L’un des serviteurs du roi d’Israël répondit: Il y a ici Élisée, fils de Saphat, celui qui versait de l’eau sur les mains d’Élie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josaphat reprit: La parole du Seigneur est avec lui. Et le roi d’Israël, ainsi que le roi de Juda et le roi d’Edom, l’alla trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Or, Élisée dit au roi d’Israël: Qu’y a-t-il entre moi et toi? Va aux prophètes de ton père et aux prophètes de ta mère. Le roi d’Israël reprit: Le Seigneur n’a-t-il pas appelé les trois rois pour les livrer aux mains de Moab?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Élisée répondit: Vive le Seigneur Dieu des armées devant qui je me tiens! je ne t’aurais point regardé, je ne t’aurais point vu, si je n’avais respecté la présence de Josaphat, roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Maintenant, amenez-moi un joueur de harpe. Or, dans le temps que celui-ci jouait, la main du Seigneur fut sur Élisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Et il s’écria: Voici ce que dit le Seigneur: Creusez dans cette vallée, faites-y une multitude de fossés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Car voici ce que dit le Seigneur: Vous ne verrez point de vent, vous ne verrez point de pluie; néanmoins cette vallée se remplira d’eau, et vous boirez, puis vous abreuverez vos chevaux et votre bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Ceci est chose légère aux yeux du Seigneur; et je livrerai Moab à vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Vous raserez toutes ses forteresses, vous abattrez tous ses arbres fruitiers, vous comblerez toutes les fontaines, et vous rendrez stérile toute bonne terre en la couvrant de cailloux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Le lendemain matin, tandis qu’on brûlait la graisse des victimes, les eaux jaillirent du chemin d’Edom, et la terre en fut couverte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Or, tout Moab apprit que les trois rois venaient le combattre; et il convoqua de toutes parts ses hommes de guerre, et il dit: Malheur à moi! Et l’armée se rangea sur la frontière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Et ils se levèrent de grand matin, et le soleil se leva sur les eaux, et Moab vit en face des eaux rouges comme du sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Et il dit: Voici du sang versé par l’épée; les rois se seront combattus, chacun aura tué son voisin; maintenant, Moab, à toi les dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Et ils entrèrent dans le camp d’Israël; mais Israël était debout, il tailla Moab en pièces; les fuyards se dispersèrent devant lui, il entra dans leur contrée et il frappa Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Il rasa ses villes fortes; sur toute terre fertile, chaque homme porta un caillou, de sorte qu’elle en fut couverte; les vainqueurs comblèrent toutes les fontaines; ils abattirent tous les arbres fruitiers; il ne resta que les pierres des remparts abattus. Des frondeurs parcoururent la contrée et la frappèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Quand il vit la bataille perdue, le roi de Moab s’entoura de sept cents hommes vaillants, qui, l’épée à la main, cherchèrent à passer à travers Edom; mais ils ne le purent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Et il prit son fils premier-né, désigné pour régner à sa place, et il l’offrit en holocauste sur les remparts; tout Israël en eut un grand remords; ils s’éloignèrent de lui, et ils retournèrent en la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Et une femme des fils des prophètes invoqua le secours d’Élisée, disant: Mon mari, ton serviteur, est mort, et tu sais que ton serviteur avait la crainte de Dieu; or, son créancier est venu réclamer pour lui mes deux fils, et ils seront ses esclaves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Élisée répondit: Que ferai-je pour toi? Qu’as-tu en ta maison? Elle reprit: Ta servante n’a rien dans sa maison, sinon l’huile dont je dois m’oindre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Et il lui dit: Va, demande à tous tes voisins des vases vides, et ne te contente pas d’un petit nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Puis, tu rentreras; tu fermeras la porte sur toi et sur tes fils; tu verseras ton huile dans ces vases; et à mesure que tu les auras remplis, tu les enlèveras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Elle s’éloigna d’Élisée; et ferma sa porte sur elle et sur ses fils: ceux-ci lui apportèrent les vases, elle y versa l’huile jusqu’à ce qu’ils en fussent pleins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Et elle dit à ses fils: Approchez encore un vase. Il n’y en a plus, dirent-ils. Et l’huile cessa de couler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Alors elle alla trouver l’homme de Dieu, et lui raconta ce qui venait d’arriver. Élisée lui dit: Pars, et donne de l’huile en paiement; tu acquitteras ainsi ta dette; ensuite, toi et tes deux fils vous vivrez du reste de l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Un autre jour, Élisée traversa Sunam; il y avait là une femme riche qui le contraignit de manger de son pain; plus tard, toutes les fois qu’il entrait en cette ville après une longue marche, il allait chez elle, et il y mangeait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Et la femme dit à son mari: Je vois bien que ce saint homme qui vient toujours chez nous est un homme de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Préparons pour lui une chambre haute, il ne la lui faut pas bien grande; mettons-y un lit, une table, une chaise, une lampe, et il y couchera quand il viendra chez nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Or, un jour, il entra dans cette maison, monta à sa chambre, et se mit au lit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Puis, il dit à Giézi, son serviteur: Appelle-moi cette Sunamite. Giézi l’appela, et elle se tint devant Élisée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Qui dit à son serviteur, dis-lui: Voilà que pour nous tu t’es donné tous ces soins: que devons-nous faire en ta faveur? As-tu quelque chose à demander au roi ou à l’un des chefs de l’armée? Elle répondit: Je suis dans ma maison, au milieu de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Or, Élisée dit à Giézi: Que faut-il faire pour elle? Giézi, son serviteur, répondit: Elle n’a point de fils, et son mari est vieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Et il la rappela; mais elle était restée près de la porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Élisée lui dit: A pareille époque l’an prochain, en cette même saison, tu vivras et tu embrasseras un fils. Et elle s’écria: Non, seigneur, ne trompe point ta servante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'En effet, la femme conçut; elle enfanta un fils au temps, en la saison, que lui avait dits Élisée, et elle vécut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Et l’enfant grandit, et un jour qu’il était vers son père auprès des moissonneurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Il dit à son père: Ma tête! ma tête! Et le père dit à son serviteur: Porte-le à sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Et le serviteur le porta à sa mère, qui le tint couché sur ses genoux jusqu’au milieu du jour; alors, il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Et elle l’emporta, l’étendit sur le lit de l’homme de Dieu, ferma sur lui la porte et sortit de la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Puis, elle appela son mari et lui dit: Envoie-moi l’un de tes serviteurs et une ânesse; je courrai jusqu’à l’homme de Dieu, et je reviendrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Mais il dit: Pourquoi veux-tu l’aller trouver ce jour-ci, qui n’est ni sabbat ni nouvelle lune? Or, elle reprit C’est bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Aussitôt, elle bâta son ânesse, et elle dit à son serviteur: Allons, marche, ne m’arrête point, sur ma monture, que je ne te dise: C’est ici; alors tu iras trouver l’homme de Dieu au mont Carmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Elle partit donc, et alla jusqu’à l’homme de Dieu sur la montagne. Dès qu’Élisée l’aperçut venant à lui, il dit à Giézi, son serviteur: Voilà certainement cette Sunamite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Cours à sa rencontre, dis-lui: Vas-tu bien, et ton époux, et ton enfant? Elle répondit: Tout va bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Puis, elle aborda Élisée sur la montagne, elle lui baisa les pieds, et Giézi s’avança pour la repousser; mais Élisée lui dit: Laisse-la, car son âme est pleine de douleur, et le Seigneur s’est caché de moi; il ne me l’a point dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Et la femme ajouta: Est-ce que j’avais demandé à mon maître un fils? N’avais-je point dit: Ne me trompe pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Et Élisée dit à Giézi: Ceins-toi les reins, prends en ta main mon bâton, et pars; si tu rencontres un homme, ne le bénis pas; si un homme te bénit, ne lui réponds pas; ensuite, tu poseras mon bâton sur le visage de l’enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Et la mère de l’enfant dit: Vive le Seigneur et vive ton âme! je ne te quitterai point. Élisée se leva donc, et la suivit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Cependant, Giézi la devança; il posa le bâton sur le visage de l’enfant; mais il n’y avait plus de voix pour lui répondre, plus d’oreilles pour l’ouïr; enfin il revint au-devant d’elle, et lui dit: L’enfant ne s’est point réveillé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Et Élisée entra dans la maison; il vit l’enfant mort étendu sur son lit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Et à peine entré dans la maison, Élisée ferma la porte sur eux tous, et il adora le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Il monta sur le lit; il se coucha sur l’enfant; il mit sa bouche contre sa bouche, ses yeux contre ses yeux, ses mains sur ses mains; il se courba sur lui, et la chair de l’enfant fut réchauffée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Et le prophète descendit; il marcha çà et là dans la maison; puis, il remonta et se courba sur l’enfant, jusqu’à sept fois; et l’enfant ouvrit les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Alors, Élisée appelant à grands cris son serviteur, lui dit Fais venir cette Sunamite. Il la fit venir; elle entra auprès du prophète, et il lui dit: Prends ton fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'La femme s’avança, se jeta aux pieds du prophète, et l’adora la face contre terre; puis, elle prit son enfant et sortit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Élisée retourna à Galgala; il y avait là grande famine, et les fils des prophètes étaient assis devant lui. Élisée dit à son serviteur: Prends une grande chaudière et fais cuire à manger pour les fils des prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Lui-même alla aux champs recueillir des légumes sauvages; il trouva une vigne, il y prit des courges sau vages plein son manteau, et il les jeta dans la chaudière, sans qu’on le vît.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Cela fait, il porta aux hommes à manger, et tandis qu’ils mangeaient de cette bouillie, ils jetèrent un cri, et dirent: La mort est dans la chaudière, ô homme de Dieu. Et ils ne purent manger davantage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Alors, il dit: Prenez de la farine et jetez-la dans la chaudière; et s’adressant à Giézi, son serviteur, il ajouta: Donne de cette bouillie au peuple et qu’ils mangent. Et il n’y eut plus rien de mauvais dans la chaudière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Et un homme vint de Bétharisa, et il présenta à l’homme de Dieu de ses prémices: vingt pains d’orge avec des cabas de figues; et l’homme de Dieu dit: Donnez cela au peuple, et qu’ils mangent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'A quoi son serviteur répondit: Pourquoi donner cela à cent hommes! Mais Élisée reprit: Donne-le au peuple, qu’il mange; car le Seigneur a dit: Ils mangeront et ils en laisseront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Et ils mangèrent et ils en laissèrent, selon la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Et Naaman, général de l’armée syrienne, était un homme considérable aux yeux de son maître, et d’un aspect imposant; c’était par lui que le Seigneur avait sauvé la Syrie, et l’homme était très-puissant, mais il était lépreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Or, des maraudeurs sortis de la Syrie avaient emmené captive, de la terre d’Israël, une petite fille qui servait la femme de Naaman,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Cette fille dit à sa maîtresse: Plût à Dieu que mon maître fût en présence du prophète de Dieu en Samarie; il le guérirait de sa lèpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Et la femme entra auprès de son seigneur, et elle lui dit: La jeune fille de la terre d’Israël a parlé de telle et telle manière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Et le roi de Syrie dit à Naaman: Vas-y, va, et j’enverrai une lettre au roi d’Israël. Naaman partit donc, et il prit avec lui dix talents d’argent, six mille sicles d’or, et dix robes diverses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Et il porta au roi d’Israël la lettre où il était écrit: Dès que tu auras reçu cette lettre, tu guériras de sa lèpre mon serviteur Naaman, que j’ai envoyé auprès de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Quand le roi d’Israël eut lu la lettre, il déchira ses vêtements, et il s’écria Suis-je un Dieu pour donner la mort et la vie? Pourquoi celui-ci envoie-t-il un homme auprès de moi, afin que je le guérisse de sa lèpre? Vous le voyez, il cherche un prétexte contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Aussitôt qu’Élisée apprit que le roi d’Israël avait déchiré ses vêtements, il envoya près de lui, disant: Pourquoi as-tu déchiré tes vêtements? Que Naaman vienne me trouver, qu’il sache qu’en Israël il y a un prophète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Et Naaman y alla avec ses chevaux et son char, et il se tint à la porte d’Élisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Et le prophète lui envoya un messager, qui lui dit: Pars et baigne-toi sept fois dans le Jourdain, ta chair te reviendra, et tu seras guéri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Mais, Naaman irrité s’en alla en disant: Je m’étais dit: Il va certainement venir me trouver; il se tiendra devant moi, il invoquera le nom du Seigneur son Dieu, il imposera les mains sur mes plaies, et il me guérira de la lèpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Les eaux de l’Abana et du Pharphar, fleuves de Damas, ne valent-elles pas mieux que toutes les eaux du Jourdain? Si je m’y baigne après mon retour, ne serai-je point plus tôt guéri? Et il s’éloigna, et il partit courroucé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Et ses serviteurs s’approchèrent de lui, disant: Si le prophète t’avait prescrit une grande chose, ne la ferais-tu point? A plus forte raison, puisqu’il t’a dit: Baigne-toi, et tu seras guéri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Et Naaman, ayant mis pied à terre, se baigna sept fois dans le Jourdain selon la parole d’Élisée; et sa chair redevint comme la chair d’un petit enfant; il était guéri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Et il retourna en personne auprès d’Élisée avec toute sa troupe; arrivé vers le prophète, il se tint debout devant lui, et dit: Je reconnais qu’il n’y a point de Dieu sur la terre sinon en Israël; maintenant reçois la bénédiction de ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Élisée répondit: Vive le Seigneur, devant qui je me tiens! je n’accepterai rien. L’autre le pressa d’accepter, mais il ne le voulut pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Et Naaman dit: Puisque tu refuses, que l’on donne du moins à ton serviteur assez de terre pour charger deux mulets; car ton serviteur ne fera plus d’holocaustes, et ne brûlera plus d’encens pour d’autres dieux; il ne sacrifiera qu’au Seigneur, à cause de cette affaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Et que le Seigneur pardonne à ton serviteur, si, lorsque mon maître entrera dans le temple de Remman, pour y adorer, appuyé sur mon bras, je me prosterne aussi dans le temple de Remman, pendant que mon maître y adorera; que le Seigneur pardonne alors à ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Le prophète dit à Naaman: Va-t’en en paix. Et il s’éloigna pour retourner en la terre de Debratha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Mais Giézi, le serviteur d’Élisée, se dit: Voilà que mon maître s’est abstenu de rien accepter des choses qu’avait apportées ce Naaman le Syrien; vive le Seigneur! je courrai après lui, et j’en obtiendrai quoi que ce soit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Et Giézi courut après Naaman; le Syrien le vit courant après lui, et il retourna son char pour le rencontrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Et Giézi dit: Tout va bien, mon maître m’envoie, disant: Voilà que deux jeunes gens fils de prophètes m’arrivent des montagnes d’Éphraïm, donne-leur un talent d’argent et deux robes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naaman répondit: Prends un double talent d’argent. Et il prit deux talents d’argent, en deux sacs, et deux robes, puis il les donna à porter à ses deux serviteurs qui partirent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Il arriva à la brune, prit de leurs mains les présents, les déposa dans la maison, et congédia les deux h ommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Lui-même entra ensuite, et se tint auprès de son maître. Or, Élisée lui dit: Giézi, d’où viens-tu? Celui-ci répondit: Ton serviteur ne s’éloigne ni à droite, ni à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Et le prophète reprit: Est-ce que mon cœur n’était pas avec toi quand l’homme a retourné son char pour aller à ta rencontre? Et maintenant, tu as pris de l’argent, tu as reçu des robes; tu veux acheter des oliviers, des vignes, des brebis, des bœufs, des serviteurs et des servantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Eh bien! la lèpre de Naaman s’attachera à toi et à ta race pour toujours. Et Giézi sortit de sa présence, couvert d’une lèpre blanche comme la neige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Et les fils des prophètes dirent à Élisée: Vois, le lieu où nous demeurons devant toi est étroit pour nous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Allons donc jusqu’au Jourdain, que chaque homme prenne là une solive, puis nous y construirons pour nous une maison où nous demeurerons. Et il répondit: Allez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'L’un d’eux ajouta doucement: Viens avec tes serviteurs; et il reprit: J’irai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Et il partit avec eux; ils arrivèrent au Jourdain, et ils abattirent des arbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Or, pendant que l’un d’eux coupait un tronc, le fer de sa cognée tomba dans l’eau, et il cria: Hélas! maître, la voilà perdue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'L’homme de Dieu dit: Où est-elle tombée? L’autre lui montra la place; Élisée écorça une branche, il l’y jeta, et le fer surnagea.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Et le prophète dit: Relève-le pour toi. L’autre étendit la main et le reprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Cependant, le roi de Syrie était à combattre Israël; il tint conseil avec ses serviteurs, et il dit: Je camperai en un tel lieu où l’on peut se cacher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Et Élisée envoya au roi d’Israël, disant: Prends garde de passer en cet endroit, car le roi de Syrie y est caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Et le roi d’Israël fit reconnaître le lieu que lui avait dit Élisée, et il s’en garda plus d’une et plus de deux fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Et l’âme du roi de Syrie en fut émue; il convoqua ses serviteurs, et il leur dit: Ne me direz-vous point qui me trahit auprès du roi d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Or, l’un d’eux répondit: Cela n’est pas, ô roi mon maître, mais Élisée le prophète fait connaître au roi d’Israël les discours que tu tiens jusque dans l’alcôve de ta chambre à coucher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Et il leur dit: Allez, voyez où il est, et j’enverrai des gens le prendre. Ils s’en allèrent, et ils lui firent dire: Le voici en Dothaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Et il y envoya des cavaliers, des chars, une force imposante; et ses gens y arrivèrent de nuit, et ils investirent la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'S’étant levé de grand matin, le serviteur d’Élisée sortit, et il vit l’armée qui entourait la ville; il vit les cavaliers, les chars, et il dit au prophète: Hélas! maître, comment ferons-nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Mais son maître répondit: N’aie point de crainte; car ceux qui sont avec nous, surpassent en nombre ceux qui sont avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Puis, le prophète pria, det it: Seigneur, ouvrez les yeux de mon serviteur, qu’il voie. Et le Seigneur ouvrit les yeux du serviteur; il vit la montagne couverte de chevaux de feu et de chars de feu, tout autour d’Élisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Et ces chevaux et ces chars descendirent à lui; alors, il pria le Seigneur, et il dit: Frappez ce peuple d’aveuglement. Et le Seigneur les frappa d’aveuglement, selon la parole du prophète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Élisée leur dit: Ce n’est point ici la ville, Vous n’êtes pas dans le chemin. Suivez-moi, et je vous mènerai vers l’homme que vous cherchez. Et il les conduisit à Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Quand ils y furent entrés, le prophète dit: Seigneur, ouvrez-leur les yeux, qu’ils voient. Et le Seigneur leur ouvrit les yeux, et ils virent. Or, voilà qu’ils étaient au milieu de Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'En les voyant, le roi d’Israël dit à Élisée: Faut-il frapper, père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Il répondit: Ne les frappe point; frappe-t-on de l’arc ou de l’épée ceux que l’on a fait captifs? Prépare pour eux des pains et de l’eau; qu’ils mangent et boivent, pour s’en retourner ensuite auprès de leur maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Le roi leur fit donc grande chère, ils mangèrent et burent; après quoi, il les renvoya, et ils s’en allèrent retrouver leur maître, et les bandes de la Syrie cessèrent leurs excursions dans la terre d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Quelque temps après, Ben-Ader, roi de Syrie, réunit toute son armée, se mit en campagne, et assiégea Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Et il y eut une grande famine en Samarie; le siége se prolongea au point que la tête d’un âne valut cinquante sicles d’argent, et un peu de fiente de pigeon cinq sicles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Comme le roi d’Israël passait sur les remparts,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Il lui dit: Si le Seigneur ne te sauve, comment pourrai-je te sauver? Ai-je rien du pressoir ou de l’aire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Le roi ajouta: Que t’arrive-t-il? Elle reprit: La femme que voilà m’a dit: Donne-moi ton fils, aujourd’hui nous le mangerons, et demain nous mangerons le mien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Nous avons donc fait bouillir mon fils et nous l’avons mangé; puis, je lui ai dit le lendemain: Donne-moi ton fils, et aujourd’hui nous le mangerons; mais elle a caché son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Lorsque le roi d’Israël eut ouï les paroles de la femme, il déchira ses vêtements, il traversa le rempart, et le peuple vit le cilice sur ses chairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Et il s’écria: Que Dieu me punisse et qu’il me punisse encore, si la tête d’Élisée est encore aujourd’hui sur ses épaules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Or, Élisée était assis en sa demeure, et les anciens étaient assis auprès de lui. Et le roi avait envoyé contre lui un homme; avant que celui-ci arrivât, le prophète dit aux anciens: Ne savez-vous pas que le fils du meurtre a envoyé prendre ma tête? Voyez, quand son messager sera arrivé; fermez la porte et retenez-le en dedans; n’entendez-vous point derrière lui le bruit des pas de son maître?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Comme il parlait encore, le messager entra et dit: C’est le Seigneur qui fait fondre sur nous ces maux; que puis-je encore attendre du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Et le prophète répondit: Écoute la parole du Seigneur Voici ce que dit le Seigneur: Demain, à pareille heure, la mesure de fleur de farine se vendra un sicle, et la double mesure d’orge se vendra un sicle à la porte de Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Le grand officier (c’était celui sur le bras duquel le roi s’appuyait) dit à Élisée: A moins que le Seigneur n’en fasse tomber du ciel des cataractes, cette parole peut-elle s’accomplir? Et le prophète reprit Tu le verras de tes yeux, mais tu n’en mangeras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Or, il y avait quatre lépreux devant les portes de la ville, et ils se dirent entre eux: Pourquoi resterions-nous ici jusqu’à la mort?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Si nous disons: Entrons dans la ville, nous y mourrons, car il y a grande famine dans la ville; et, si nous restons ici, nous y mourrons. Allons donc; et tombons dans le camp des Syriens; s’ils nous prennent vivants, nous vivrons; s’ils nous mettent à mort, eh bien! nous mourrons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Et ils se levèrent avant le jour pour entrer dans le camp des Syriens; ils entrèrent par un côté du camp où il n’y avait point un seul homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Car le Seigneur avait fait retentir dans le camp des Syriens un bruit de chars et de chevaux, comme d’une grande armée. Et chaque Syrien avait dit à son frère: Sans doute le roi d’Israël a pris à sa solde les rois des Hettéens et les rois de l’Égypte, pour qu’ils marchent contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Ils s’étaient donc levés, et s’étaient enfuis dans les ténèbres; ils avaient abandonné leurs tentes, leurs chevaux et leurs ânes; laissé le camp comme il était, et pris la fuite pour sauver leur vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Et les lépreux, ayant fait quelques pas dans le camp, entrèrent sous une tente, mangèrent, burent, enlevèrent de l’argent, de l’or, des vêtements, et s’en allèrent; ensuite, un peu plus loin, ils entrèrent sous une autre tente, y prirent encore du butin; puis, ils en sortirent, et se cachèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Et ils se dirent entre eux: En resterons-nous là? Ce jour est un jour de bonne nouvelle; si nous gardons le silence, si nous demeurons ici jusqu’à la prochaine aurore, nous serons en faute; partons donc, entrons dans la ville, et faisons notre rapport dans le palais du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Ils s’en allèrent, appelèrent à grands cris aux portes de la ville, et dirent à ceux qui vinrent: Nous sommes entrés dans le camp des Syriens; il n’y a ni homme ni voix humaine; il n’y a plus que les chevaux et des ânes attachés, et leurs tentes sont restées comme elles étaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Et les gardes de la porte appelèrent à grands cris; puis, on porta la nouvelle au palais du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Le roi se leva qu’il était encore nuit, et il dit à ses serviteurs: Je vais vous expliquer ce qu’a fait le Syrien: il sait que nous sommes affamés; il est allé hors du camp pour se cacher dans la campagne, disant: Ils vont sortir, nous les prendrons vivants, et nous entrerons dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Or, l’un de ses serviteurs répondit: Que l’on prenne cinq chevaux parmi ceux qui restent encore vivants, de cette grande multitude des chevaux d’Israël; nous les enverrons là, et nous verrons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Et ils prirent deux cavaliers que le roi d’Israël envoya derrière le roi de Syrie, disant: Allez, et voyez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Ces hommes suivirent les traces de l’armée jusqu’au Jourdain, et ils virent toute la route couverte de vêtements et de harnais que, dans leur frayeur, les Syriens avaient jetés; puis, ils revinrent faire au roi leur rapport.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Et le peuple sortit et pilla le camp des Syriens; la mesure de fleur de farine se vendit un sicle, selon la parole du Seigneur, et la double mesure d’orge se vendit un sicle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Or, le roi avait placé devant la porte le grand officier, sur le bras duquel il s’appuyait habituellement; et le peuple le foula aux pieds devant la porte, et il mourut, comme le lui avait dit l’homme de Dieu, quand il était venu auprès de lui comme messager du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Alors, s’accomplit la parole d’Élisée au roi, quand il avait dit: La double mesure d’orge se vendra un sicle, et la mesure de fleur de farine un sicle, et ce sera demain, à pareille heure, devant la porte de Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Or, le grand officier avait répondu au prophète: A moins que le Seigneur n’en fasse tomber du ciel des cataractes, cette parole peut-elle s’accomplir? A quoi Élisée avait repris: Tu le verras de tes yeux, mais tu n’en mangeras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Et il en fut ainsi; le peuple le foula aux pieds devant la porte, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Ensuite, Élisée parla à la femme dont il avait ressuscité le fils, disant: Lève-toi; pars, toi et ta maison; va, demeure où tu pourras; car le Seigneur a appelé sur cette terre la famine; elle y est venue pour sept ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Et la femme se leva; elle fit selon la parole d’Élisée, elle et toute sa maison; puis, elle demeura sept ans au pays des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'A la fin des sept ans, la femme revint du pays des Philistins en sa ville, et elle alla réclamer du roi sa maison et ses champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Or, le roi avait parlé à Giézi, serviteur d’Élisée, homme de Dieu, disant: Raconte-moi toutes les grandes choses qu’a faites Élisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Et ceci advint: tandis qu’il racontait au roi comment il avait ressuscité l’enfant mort, la femme dont Élisée avait ressuscité le fils entra pour réclamer du roi sa maison et ses champs. Et Giézi s’écria: O roi mon maître, voici la femme, et voici son fils qu’Élisée a ressuscité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Le roi questionna la femme, qui lui raconta tout; et le roi lui donna un eunuque, à qui il dit: Rends-lui tout ce qui était à elle, et tous les produits de ses champs, depuis le jour où elle les a quittés jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Et Élisée alla à Damas, où Ben-Ader, roi de Syrie, était malade; on alla dire à ce dernier: L’homme de Dieu est venu jusqu’ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Et le roi dit à Azaël: Prends en ta main un présent; va trouver l’homme de Dieu, et, par lui, demande au Seigneur si je guérirai de cette maladie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Azaël partit à la rencontre du prophète, ayant en la main un présent, et, de tout ce qu’il y avait de bon à Damas, la charge de quarante chameaux; il marcha, s’arrêta devant Élisée, et il lui dit: Ton fils Ben-Ader, roi de Syrie, m’envoie t’interroger, disant: Guérirai-je de cette maladie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Élisée dit: Retourne-t’en, et dis-lui: Tu vivras certainement; mais le Seigneur m’a appris qu’il mourrait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Or, l’homme de Dieu était en présence d’Hazaël; il lui parla tout confus, et il se prit à pleurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Et Azaël lui dit: Pourquoi mon seigneur pleuret-il? Il répondit: Parce que je sais combien de malheurs tu causeras aux fils d’Israël; tu livreras aux flammes leurs forteresses, tu feras périr par l’épée leurs plus vaillants, tu écraseras leurs enfants à la mamelle, et tu feras avorter les femmes enceintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Et Azaël répondit: Qu’est donc ce chien mort, ton serviteur, pour accomplir de telles choses? Et le prophète reprit: Le Seigneur m’a montré que tu serais roi de Syrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Et il se sépara d’Élisée pour rentrer chez son maître; celui-ci lui demanda: Que t’a dit Élisée? Il répondit: Que tu vivras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Et, quand vint l’aurore, il prit un manteau épais, le plongea dans l’eau, et en couvrit la figure du roi qui mourut, et Azaël régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'La cinquième année du règne de Joram en Israël, et, du vivant de Josaphat, roi de Juda, Joram, fils de Josaphat, commença à régner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Il avait trente-deux ans, et il régna huit ans en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Il marcha dans la voie des rois d’Israël, comme avait fait la maison d’Achab, parce que la fille d’Achab était sa femme, et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Mais le Seigneur ne voulut pas détruire Juda, à cause de David, son serviteur; car il avait promis de lui donner un flambeau, et de le conserver toujours à ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Sous le règne de Joram, Edom s’affranchit du joug de Juda, et se donna un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Et Joram marcha sur Séir avec tous ses chars; il tailla en pièces Edom, qui l’avait enveloppé lui et les chefs des chars; et ce peuple s’enfuit chacun en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Toutefois, Edom s’affranchit pour toujours du joug de Juda; en ce même temps-là, Lobna s’affranchit pareillement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Quant au reste de l’histoire de Joram, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Et Joram s’endormit avec ses pères; il fut enseveli');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Son règne commença dans la onzième année du règne de Joram en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Il avait vingt-deux ans, et il régna un an à Jérusalem, et sa mère était Athalie, issue d’Ambri, roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Il marcha dans la voie de la maison d’Achab, et il fit le mal devant le Seigneur, comme la maison d’Achab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Il alla avec Joram, fils d’Achab, combattre Azaël, roi des Syriens, à Ramoth-Galaad, où les Syriens blessèrent Joram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Et le roi Joram revint à Jezraël pour se guérir des blessures qu’il avait reçues à Ramoth-Galaad, dans la bataille livrée au roi de Syrie; et Ochozias, fils de Joram, alla voir Joram, fils d’Achab, parce qu’il était malade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Alors, le prophète Élisée appela l’un des fils des prophètes, et il lui dit: Ceins-toi les reins; prends en tes mains cette fiole d’huile, et va à Ramoth-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Entre, et tu verras Jéhu, fils de Josaphat fils de Namsi; tu iras auprès de lui et tu l’emmèneras du milieu de ses frères, en un lieu retiré de ses appartements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Et tu prendras la fiole d’huile; tu la lui verseras sur la tête, et tu diras: Voici ce que dit le Seigneur: Je t’ai sacré roi d’Israël; cela dit, tu ouvriras la porte, et tu partiras rapidement sans t’arrêter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Et le jeune prophète alla en Ramoth-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Il entra, il vit les chefs de l’armée assis ensemble, et il dit: Un mot à toi, chef. Jéhu demanda: Auquel de nous? Il répondit: A toi, chef,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Et Jéhu se leva, et ils allèrent à l’intérieur de la maison; là, le prophète lui versa l’huile sur la tête, et lui dit Voici ce que dit le Seigneur Dieu d’Israël: Je t’ai sacré roi du peuple du Seigneur, roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Et tu extermineras de devant ma face la maison d’Achab, ton maître; tu vengeras le sang des prophètes, mes serviteurs, et le sang de tous mes serviteurs qu’a répandu la main de Jézabel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Et celui qu’a répandu toute la maison d’Achab; tu extermineras tout mâle de la maison d’Achab, tout ce qui se tient enfermé et survit en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Et je traiterai la maison d’Achab comme celle de Jéroboam, fils de Nabat, comme celle de Baasa, fils d’Achias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Et les chiens dévoreront Jézabel dans le champ de Jezraël, et il n’y aura personne qui l’ensevelisse. Puis, le prophète ouvrit la porte et s’enfuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Jéhu revint auprès des serviteurs de son maître, et ils lui dirent: Tout va bien. Pourquoi cet épileptique est-il venu te trouver? Il leur répondit: Vous connaissez l’homme et son bavardage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Mais ils dirent: Nullement, raconte-nous-le donc. Alors, Jéhu leur dit: Il m’a parlé de telle et de telle manière, ajoutant: Voici ce que dit le Seigneur: Je t’ai sacré roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Dès qu’ils l’eurent ouï, ils s’empressèrent; chacun ôta son manteau et le mit sous les pieds de Jéhu au faîte des degrés; puis, ils sonnèrent du cor, et ils dirent: Jéhu est roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Ainsi, Jéhu, fils de Josaphat, fils de Namsi, se révolta contre Joram. Alors, Joram défendait RamothGalaad, avec tout Israël, contre Azaël, roi de Syrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Et le roi Joram était revenu à Jezraël pour se guérir des blessures que les Syriens lui avaient faites quand il avait combattu Azaël, roi de Syrie. Et Jéhu dit aux siens Si votre âme est avec moi, ne laissez sortir de la ville personne qui puisse aller tout dire à Jezraël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Ensuite, Jéhu monta à cheval, partit, et descendit à Jezraël, où le roi Joram était à panser les blessures que lui avaient faites les flèches des archers syriens quand il avait combattu Azaël, roi de Syrie; car il était vaillant et plein de force. Et Ochozias, roi de Juda, était venu voir Joram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Et une sentinelle montée sur la tour de Jezraël, vit la poussière que soulevait Jéhu en approchant; et elle dit Je vois de la poussière. A quoi Joram répondit: Prends un cavalier; fais-le partir au-devant d’eux; qu’il demande Est-ce la paix?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Et un cavalier partit à leur rencontre, et il dit: Voici ce que dit le roi Est-ce la paix? Jéhu répliqua: Qu’y a-t-il entre toi et la paix? Va te joindre à ceux qui me suivent. Cependant, la sentinelle fit ce rapport: Le messager est allé jusqu’à eux, et il n’est point revenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Et elle envoya un second messager; celui-ci arriva près d’eux, et il dit: Voici ce que dit le roi: Est-ce la paix? Jéhu répliqua: Qu’y a-t-il entre toi et la paix? Va te joindre à ceux qui me suivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'L’homme en sentinelle fit derechef ce rapport: Il est allé jusqu’à eux, et il n’est point revenu; le chef paraît être Jéhu, fils de Namsi; car il marche comme un furieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Et Joram dit: Qu’on attelle. On attela son char; et Joram, roi d’Israël, sortit avec Ochozias, roi de Juda, chacun sur son char; ils allèrent à la rencontre de Jéhu, et ils le trouvèrent dans le champ de Naboth le Jezraélite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Dès que Joram vit Jéhu, il s’écria: Est-ce la paix, Jéhu? Jéhu répondit: Quoi! la paix! quand Jézabel, ta mère, multiplie ses débauches et ses sortiléges?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Alors, Joram tourna bride, s’enfuit, et dit au roi de Juda Trahison! Ochozias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Mais Jéhu tendit son arc avec force, et il atteignit Joram entre les épaules; la flèche lui traversa le cœur, et il s’affaissa sur ses genoux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Puis, Jéhu dit à Badecar, son lieutenant: Jette-le dans le champ de Naboth le Jezraélite; car je me souviens, et tu te souviens aussi, que, quand nous étions sur un char à la suite d’Achab, son père, le Seigneur a prononcé cette sentence:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Si je n’avais point vu hier le sang de Naboth et le sang de ses fils! dit le Seigneur; mais je les vengerai dans ce champ même, dit le Seigneur. Maintenant, prends-le et jette-le dans le champ, selon la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Et Ochozias, roi de Juda, vit tout, et il prit la fuite par le chemin de Bethgan; Jéhu le poursuivit, et il dit: Tuez aussi celui-là. L’un de ses gens le frappa sur son char comme il montait en Haï (la même que Jéblaam). Et Ochozias se réfugia dans Mageddo, où il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Ses serviteurs le placèrent sur son char; ils le ramenèrent à Jérusalem, et ils l’ensevelirent dans son sépulcre en la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Ochozias était devenu roi de Juda, la onzième année du règne de Joram en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Ensuite, Jéhu entra dans Jezraël; Jézabel l’ouït, elle se farda le tour des yeux, orna sa tête, et se pencha à sa fenêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Quand Jéhu passa, elle lui cria: Zambri s’est-il bien trouvé d’avoir tué son maître?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Il leva les yeux vers sa fenêtre; il la vit, et il dit: Qui es-tu? Descends auprès de moi. Or, il y avait là deux eunuques qui se penchèrent vers lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Jéhu leur dit: Jetez-la par la fenêtre. Et ils la jetèrent; son sang jaillit sur les murs et sur les chevaux, et les chevaux la foulèrent aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Ensuite, Jéhu entra dans le palais; il mangea et il but; puis, il dit: Allez voir cette maudite, et ensevelissezla, car c’est une fille de roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Et ses gens sortirent pour l’inhumer; mais ils ne trouvèrent plus rien d’elle que le crâne, les pieds et les paumes des mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Ils rentrèrent; ils lui en firent le rapport, et il dit: C’est la parole du Seigneur qu’il a dite par Élie le Thesbite, disant Dans les champs de Jezraël, les chiens dévoreront les chairs de Jézabel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Et son cadavre sera comme du fumier sur la surface du champ de Jezraël, et nul ne pourra dire: C’est Jézabel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Il y avait alors en Samarie soixante-dix fils d’Achab; Jéhu écrivit une lettre qu’il envoya dans Samarie aux chefs, aux anciens de la ville et aux gardiens des enfants d’Achab; il leur disait:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Aussitôt que cette lettre vous sera parvenue, vous qui avez avec vous les fils de votre maître, et des chars, et des forteresses, et des armes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Vous considèrerez quel est le meilleur et le plus droit des fils de votre maître, vous le placerez sur le trône de son père, et vous combattrez pour la maison de votre maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Or, ils eurent crainte, et ils dirent: Si deux rois n’ont pu tenir devant lui, comment lui résisterons-nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Et les chefs du palais, ceux de la ville, ainsi que les anciens et les gardiens des enfants, envoyèrent des messagers à Jéhu, disant: Nous aussi nous sommes tes serviteurs; tout ce que tu nous diras nous le ferons; nous ne proclamerons point de roi, nous ferons ce que bon te semblera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Jéhu leur écrivit une seconde lettre, où il disait: Si vous êtes à moi, si vous êtes dociles à mes ordres, prenez les têtes des hommes fils de votre maître, et apportez-les-moi demain, à pareille heure, en Jezraël. Or, les fils du roi étaient au nombre de soixante-dix, et les premiers de la ville les élevaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Dès que la lettre leur fut parvenue, ils prirent les fils du roi et ils les égorgèrent au nombre de soixantedix. Puis, ils mirent les têtes dans des paniers, et ils les envoyèrent à Jéhu en Jezraël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Et le messager de Jéhu revint, et il fit son rapport, disant Ils ont apporté les têtes des fils du roi. Et Jéhu dit: Faites-en deux monceaux, et laissez-les jusqu’à demain matin des deux côtés de la porte de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'L’aurore parut, et il sortit; il s’arrêta, et il dit à tout le peuple: Vous êtes justes: voilà que je me suis révolté contre mon maître, je l’ai tué; mais qui donc à frappé tous ceux-ci?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Vous le voyez, nulle des paroles que le Seigneur a dites contre la maison d’Achab ne devait tomber à terre; le Seigneur a exécuté tout ce qu’il nous avait dit par Élie, son serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Et Jéhu extermina tout ce qu’il y avait encore de la maison d’Achab en Jezraël, et tous ses hommes éminents, tous ses amis et ses prêtres; pas un seul ne fut épargné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Puis, il se mit en marche pour Samarie; il était dans la maison des bergers, sur la route,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Quand il rencontra les frères d’Ochozias, roi de Juda, et il leur dit: Qui êtes-vous? Ils répondirent: Nous sommes les frères d’Ochozias, et nous sommes partis pour saluer les fils du roi et les fils de la reine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Aussitôt, il dit: Prenez-les vifs. On les prit, et on les égorgea dans la maison des bergers: quarante-deux hommes! il n’en resta pas un seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Et, s’étant éloigné de ce lieu, il rencontra Jonadab, fils de Rhéchab; celui-ci le bénit, et Jéhu lui dit: Ton cœur est-il sincèrement avec le mien, comme mon cœur est avec le tien? Jonadab répondit: Il l’est. Jéhu reprit: S’il l’est, donne-moi la main. Jonadab lui donna la main, et Jéhu le fit monter à côté de lui sur son char.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Et il lui dit: Viens avec moi, tu verras mon zèle pour le Seigneur. Puis, il le fit asseoir sur le siège.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Et il entra dans Samarie, et il extermina tout ce qui restait d’Achab, jusqu’à ce qu’il l’eût effacé, selon la parole que le Seigneur avait dite par la bouche d’Élie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Ensuite, Jéhu rassembla tout le peuple, et il leur dit: Achab a servi faiblement Baal, Jéhu le servira magnifiquement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Maintenant donc, vous tous prophètes de Baal, convoquez ici tous ses serviteurs et tous ses prêtres, sans qu’il manque un seul homme, car je vais faire un grand sacrifice à Baal; quiconque se cachera sera mis à mort. Or, Jéhu usait d’artifice pour détruire tous les serviteurs de Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Il ajouta: Sanctifiez le sacerdoce de Baal. Et on fit une proclamation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Et Jéhu envoya des messagers en tout Israël, disant: Que de tous ses serviteurs, de tous ses prêtres, de tous ses prophètes, aucun ne fasse défaut, car je prépare un grand sacrifice. Celui qui ne viendra point ne restera pas en vie. Et tous les serviteurs de Baal vinrent, ainsi que tous ses prêtres et tous ses prophètes; il n’y eut pas un homme qui ne vînt. Et ils entrèrent dans le temple de Baal, et le temple de Baal fut rempli d’un bout à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Et Jéhu dit au gardien des vêtements du temple: Apporte des robes pour tous les serviteurs de Baal. Et le gardien leur en donna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Et Jéhu, avec Jonadab, fils de Rhéchab, entra dans le temple de Baal, et il dit aux serviteurs de Baal: Cherchez, voyez s’il y a parmi vous des serviteurs du Seigneur, ou seulement des serviteurs de Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Puis, il pénétra plus loin pour offrir l’encens et les holocaustes. Or, il avait aposté dehors quatre-vingts de ses hommes, leur disant: Celui qui laissera échapper l’un de ceux que je livre entre vos mains, paiera de sa vie celle qu’il aura sauvée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Après qu’il eut consumé l’holocauste, Jéhu dit à ses gardes et à ses officiers: Entrez, frappez-les, n’en laissez pas sortir un seul. Et ils les passèrent au fil de l’épée; ils les jetèrent sur le chemin; et, du temple de Baal, ils retournèrent à la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Et ils emportèrent la colonne de Baal, et ils la brûlèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Ils abattirent les colonnes de Baal, et, du temple, ils firent des latrines, qui existent encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Jéhu effaça Baal de la terre d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Seulement, il ne se retira pas du péché de Jéroboam, fils de Nabat, du péché où il avait fait tomber Israël; il conserva les génisses d’or de Béthel et de Dan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Le Seigneur dit à Jéhu: En récompense de ce que tu as fait d’agréable à mes yeux, de ce que tu as traité selon mon cœur la maison d’Achab, tes fils règneront sur Israël jusqu’à la quatrième génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mais Jéhu ne fut pas attentif à marcher de tout son cœur selon la loi du Seigneur Dieu d’Israël; il ne se retira pas du péché de Jéroboam, du péché où il avait fait tomber tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Et, en ces jours-là, le Seigneur commença de châtier Israël; Azaël le vainquit sur toutes ses frontières,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Jusqu’à la rive orientale du Jourdain; il envahit toute la terre de Galaad, savoir: les tribus de Gad et de Ruben, et le territoire de Manassé, à partir d’Aroer, qui est sur les bords du torrent d’Arnon, et Galaad et Basan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Quant au reste de l’histoire de Jéhu, aux actions qu’il fit en sa puissance et à ses combats, ne sont-ils pas écrits au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Et Jéhu s’endormit avec ses pères; on l’ensevelit en Samarie, et son fils Joachaz régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Jéhu avait régné vingt ans sur Israël en Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Et Athalie, mère d’Ochozias, ayant vu que son fils était mort, détruisit toute la race royale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mais Josabeth, fille du roi Joram, sœur d’Ochozias, enleva Joas, fils de son frère; elle le déroba du milieu des fils du roi que l’on massacrait, et le mit, avec sa nourrice, dans une alcôve des chambres à coucher; puis, elle le cacha d’Athalie, et il ne fut point tué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Il resta six ans caché avec elle dans le temple du Seigneur, pendant qu’Athalie régnait sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Dans la septième année, Joïada envoya des messagers, et convoqua les centeniers des gardes et des coureurs; il les emmena dans le temple du Seigneur, et il fit avec eux l’alliance du Seigneur; il leur fit prêter serment, leur montra le fils du roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Et leur donna ses ordres, disant: Voilà ce que vous ferez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Le tiers de vos hommes, entrant en semaine, gardera la porte qui mène au palais du roi; un autre tiers gardera la porte de la grande rue, et le dernier tiers la porte derrière les coureurs; vous garderez tous le temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Et vous formerez deux troupes; tous ceux qui sortiront de semaine garderont aussi le temple du Seigneur auprès du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Ils entoureront le roi les armes à la main; quiconque entrera dans les rangs mourra; ils ne quitteront pas le roi, soit qu’il entre, soit qu’il sorte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Et les centeniers firent tout ce que leur avait prescrit le sage Joïada. Chacun d’eux prit ses hommes; et ceux qui entraient en semaine se réunirent à ceux qui en sortaient, et ils s’introduisirent auprès de Joïada le prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Et le prêtre leur donna les épées et les lances du roi David qui étaient dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Et chacun des coureurs se tenait, les armes à la main, tant à droite qu’à gauche de l’autel, occupant les deux ailes du temple et entourant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Alors, Joïada leur présenta le fils du roi Ochozias; il lui donna la couronne et le livre de la loi, il le proclama roi et il le sacra; et les assistants battirent des mains, et ils crièrent: Vive le roi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Et Athalie entendit la clameur de ceux du peuple qui couraient; elle entra, parmi le peuple, dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Elle vit le roi assis sur son trône selon la coutume; puis, autour de lui, les chanteurs, les trompettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Et le prêtre Joïada donna ses ordres aux centeniers, chefs de l’armée; il leur dit: Entraînez-la hors des rangs; quiconque la suivra, mourra de mort par l’épée. Et le prêtre ajouta Qu’elle ne meure point dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Ils mirent donc la main sur elle; et ils sortirent, prenant le chemin par où passaient les chevaux de la maison du roi, et là, ils la tuèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Et Joïada fit alliance entre le Seigneur et le roi; puis, entre le Seigneur et le peuple, pour que le peuple demeurât le peuple de Dieu; puis, enfin, entre le roi et le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Et tout le peuple de la terre entra dans le temple de Baal; ils le renversèrent, ils brisèrent ses autels et ses images, et ils tuèrent devant l’autel Mathan, prêtre de Baal. Ensuite, Joïada plaça des surveillants dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Il se mit à la tête des centeniers, des gardes, des coureurs et de tout le peuple de la terre; ils emmenèrent le roi du temple du Seigneur, et ils prirent la rue de la porte des coureurs du roi, et ils le firent asseoir sur le trône royal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Et tout le peuple de la terre fut en joie; la ville resta calme; Athalie avait péri par l’épée dans le palais du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Joas avait sept ans quand commença son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Joas monta sur le trône la septième année du règne de Jéhu; il régna quarante ans à Jérusalem; le nom de sa mère était Sabía de Bersabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Et Joas fit ce qui était droit devant le Seigneur tant que le prêtre Joïada vécut pour l’éclairer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Seulement, aucun des autels des hauts lieux ne fut déplacé; le peuple y fit encore des sacrifices et y brûla de l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Or, Joas dit aux prêtres: Que les prêtres prennent tout l’argent des choses saintes, entrant dans le temple du Seigneur, et provenant soit des évaluations, soit des dons que chacun fait au gré de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Que les prêtres le prennent, chacun selon son rang, et qu’ils l’emploient aux réparations du temple partout où ils en trouveront à faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'En la vingt-troisième année du règne de Joas, le temple n’était pas encore entièrement réparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Alors, le roi Joas fit venir le prêtre Joïada et les autres prêtres, et il leur dit: Pourquoi le temple n’estil pas réparé? Désormais, ne prenez plus d’argent selon votre rang; donnez-le pour réparer le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Et les prêtres consentirent à ne plus recevoir d’argent du peuple, pourvu qu’ils ne fussent plus chargés des réparations du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Et Joad le prêtre prit une cassette; il en troua le couvercle, et il le mit près de l’autel, en la demeure d’un homme appartenant au temple du Seigneur. Puis, les prêtres, gardiens de la porte, y versèrent tout l’argent trouvé dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Lorsqu’ils virent qu’il y avait beaucoup d’argent dans la cassette, le scribe du roi et le grand prêtre lièrent et comptèrent l’argent trouvé dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Puis, ils remirent l’argent qu’on avait recueilli entre les mains de ceux qui exécutaient les travaux signalés par les surveillants du temple du Seigneur; ils en donnèrent aussi aux charpentiers et aux constructeurs employés au temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Ainsi qu’aux maçons et aux tailleurs de pierre, afin qu’ils achetassent des bois et des pierres de taille pour consolider le temple, jusqu’à ce que l’on eût dépensé tout ce que l’on avait reçu, pour les réparations du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Mais on ne devait rien prendre de l’argent offert dans le temple du Seigneur, pour fabriquer les portes d’argent, les clous, les fioles, les trompettes, les vases d’or et les vases d’argent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Parce qu’on devait le donner à ceux qui faisaient les réparations; et ceux-ci l’employèrent à consolider le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Et l’on ne demanda pas de comptes aux hommes à qui l’argent fut donné, pour qu’ils le remissent aux ouvriers chargés des travaux, parce que les réparations furent exécutées de bonne foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'L’argent dû pour les péchés, l’argent dû pour les omissions, tout ce qu’on apporta dans le temple alla aux prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'En ce temps-là, Azaël, roi de Syrie, sortit pour combattre Geth, et il s’en empara; puis, il se retourna pour marcher sur Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Mais Joas, roi de Juda, prit toutes les offrandes consacrées par Josaphat, par Joram et par Ochozias, ses pères, rois de Juda; il prit ses propres offrandes et tout l’or qui se trouva, soit dans le temple du Seigneur, soit dans le palais du roi; puis, il envoya tout à Azaël, roi de Syrie; et celui-ci s’éloigna de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Quant au reste de l’histoire de Joas, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Et ses serviteurs se révoltèrent; ils tramèrent un complot, et ils frappèrent Joas en la maison de Mello qui est à Sella.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jézirchar, fils de Jémuath, et Jézébuth, fils de Somer, ses serviteurs, le frappèrent, et il mourut; on l’ensevelit auprès de ses pères en la ville de David; et son fils Amasias régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'En la vingt-troisième année du règne de Joas, fils d’Ochozias, roi de Juda, Joachaz, fils de Jéhu, commença en Samarie un règne qui dura dix-sept ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Et il fit le mal aux yeux du Seigneur; il marcha dans les péchés où Jéroboam, fils de Nabat, avait fait tomber les fils d’Israël, et il ne s’en retira point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Et le Seigneur se courrouça contre Israël; il les livra aux mains d’Azaël, roi de Syrie, et aux mains d’Ader, fils d’Azaël, tant que ces rois vécurent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Mais Joachaz implora le Seigneur, et le Seigneur l’écouta, parce qu’il vit l’affliction d’Israël; car le roi de Syrie l’affligeait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Et le Seigneur sauva Israël; le peuple fut affranchi du joug des Syriens, et les fils d’Israël furent tranquilles en leurs demeures comme autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Cependant, ils ne se retirèrent point des péchés où la maison de Jéroboam avait fait tomber Israël; ils marchèrent dans ces péchés, et laissèrent debout le bois sacré en Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Or, Joachaz n’avait plus d’armée, sauf cinquante cavaliers, dix chars et dix mille piétons, parce que le roi de Syrie avait détruit ses troupes, et les avait broyées comme la poussière que l’on foule aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Quant au reste de l’histoire de Joachaz, aux actions qu’il fit en sa puissance, ne sont-ils pas écrits au livre des Faits et gestes des rois d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Et Joachaz s’endormit avec ses pères; on l’ensevelit en Samarie, et Joas, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'En la trente-septième année du règne de Joas, roi de Juda, Joas, fils de Joachaz, roi d’Israël, commença en Samarie un règne qui dura seize ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Et il fit le mal aux yeux du Seigneur, et il ne se retira point des péchés où Jéroboam avait fait tomber Israël; il marcha dans ces péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Quant au reste de l’histoire de Joas, roi d’Israël, et à ses combats avec Amasias, roi de Juda, ne sont-ils pas écrits au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Et Joas s’endormit avec ses pères; il avait assis sur son trône Jéroboam, et il fut enseveli en Samarie avec les rois d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Et Élisée tomba malade, de la maladie dont il mourut; Joas, roi d’Israël, l’alla trouver; il pleura devant lui, et il dit: Père, père, char et conducteur d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Élisée lui dit: Prends un arc et une flèche; il prit donc un arc et une flèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Puis, le prophète dit au roi: Place ta main sur l’arc. Joas y plaça la main, et Élisée imposa ses mains sur les mains du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Ensuite, il dit: Ouvre la fenêtre du côté de l’orient. Le roi ouvrit, et Élisée lui dit: Lance le trait. Il le lança, et le prophète dit: Trait de salut du Seigneur, trait de salut contre la Syrie; tu triompheras de la Syrie en Aphec, jusqu’à ce que tu l’aies consumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Élisée lui dit encore: Prends l’arc et les flèches. Le roi les prit, et le prophète dit au roi: Frappe la terre. Et le roi frappa trois fois; puis, il s’arrêta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'L’homme de Dieu s’en affligea sur lui, et il dit: Si tu avais frappé cinq ou six fois, tu aurais frappé la Syrie jusqu’à ce que tu l’eusses consumée. Maintenant, tu ne remporteras sur elle que trois victoires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Et le prophète mourut, et on l’ensevelit; et des maraudeurs de Moab, au commencement de cette année, vinrent dans la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Or, ceci advint: pendant qu’on ensevelissait Élisée, on vit le corps d’un maraudeur; on le jeta dans la fosse du prophète; il y roula, il toucha les ossements d’Élisée, il ressuscita et il se leva sur ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Azaël avait grandement affligé le peuple tout le temps de la vie de Joachaz.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mais le Seigneur eut pitié et compassion des fils d’Israël; il les regarda favorablement, à cause de son alliance avec Abraham, Isaac et Jacob; et le Seigneur ne voulut pas les détruire, il ne les rejeta pas de devant sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Et Azaël mourut, et son fils Ader régna après lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Alors, Joas, fils de Joachaz, se remit en campagne, et il prit à Ader les villes que son père avait prises à Joachaz. Joas remporta trois victoires, et il reprit les villes d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'En la seconde année de Joas, fils de Joachaz, roi d’Israël, commença le règne d’Amasias, fils de Joas, roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Il avait alors vingt-cinq ans, et il en régna vingtneuf en Jérusalem; le nom de sa mère était Joadim de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Et il fit ce qui était droit aux yeux du Seigneur, mais non pas comme David, son aïeul. Il fit tout ce qu’avait fait Joas, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Il ne détruisit point les hauts lieux; le peuple offrit encore des sacrifices, et brûla de l’encens sur les hauts lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Quand la royauté fut affermie dans ses mains, il tua ceux de ses serviteurs qui avaient frappé son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mais il ne fit pas périr les fils des meurtriers, se conformant à ce qui est écrit au livre de la loi de Moïse, et à l’ordonnance du Seigneur, disant: Les pères ne seront pas mis à mort à cause des fils, et les fils ne seront pas mis à mort à cause des pères; chacun mourra pour son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Ensuite, il tailla en pièces, dans la vallée des Sels, dix mille hommes de l’Idumée; et il prit, en cette guerre, le rocher auquel il donna le nom de Jéthoël, nom qui lui est resté jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Alors, Amasias envoya des messagers à Joas, fils de Joachaz, fils de Jéhu, roi d’Israël, disant: Viens, que nous nous voyions face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Mais Joas, roi d’Israël, fit répondre au roi de Juda: Le chardon du Liban envoya des gens au cèdre pour lui dire: Donne ta fille à mon fils pour femme; et les bêtes fauves du champ voisin passèrent, et elles foulèrent aux pieds le chardon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Tu as battu l’lduméen, et ton cœur s’est exalté; glorifie-toi tranquillement en ta demeure; à quoi bon me cherches-tu querelle pour ta perte? Tu tomberas, et avec toi Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Amasias ne l’écouta point; et Joas, roi d’Israël, partit, et ils se virent face à face à Bethsamys en Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Mais Juda tomba devant Israël, et chacun s’enfuit en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Et Joas, roi d’Israël, fit prisonnier, à Bethsamys, Amasias, fils de Joas, fils d’Ochozias; il entra à Jérusalem, et il abattit le rempart depuis la porte d’Ephraïm jusqu’à la porte de l’angle, sur une longueur de quatre cents coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Il prit l’argent et l’or, et tous les ornements qu’il trouva soit dans le temple du Seigneur, soit dans le palais du roi; il se fit donner des ôtages, et il retourna en Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Quant au reste de l’histoire de Joas, et à ses combats avec Amasias, ne sont-ils pas écrits au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Et Joas s’endormit avec ses pères; il fut enseveli à Samarie avec les rois d’Israël, et Jéroboam, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amasias, fils de Joas, roi de Jérusalem, vécut encore quinze ans après la mort de Joas, fils de Joachaz, roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Quant au reste de l’histoire d’Amasias, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Et il y eut un complot contre lui en Jérusalem; il se réfugia à Lachis, où les conjurés le poursuivirent, et ils le tuèrent dans cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Puis, ils l’enlevèrent sur un char, et il fut enseveli à Jérusalem auprès de ses pères, dans la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Et tout le peuple de Juda fit choix d’Azarias, alors âgé de seize ans, et ils le proclamèrent roi à la place d’Amasias son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Ce fut lui qui bâtit Elath, après l’avoir reprise pour Juda, lorsque le roi eut été déposé auprès de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'En la quinzième année du règne d’Amasias, fils de Joas, roi de Juda, Jéroboam, fils de Joas, roi d’Israël, commença un règne qui dura quarante et un ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Et il fit le mal devant le Seigneur; il ne se retira pas des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Ce fut lui qui rétablit les limites d’Israël, depuis l’entrée d’Emath jusqu’à la mer d’Araba, selon la parole que le Seigneur Dieu d’Israël avait fait connaître par son serviteur le prophète Jonas, fils d’Amathi, de Gethchopher;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Parce que le Seigneur avait vu l’abaissement bien triste d’Israël, son petit nombre, son asservissement, son indigence et son isolement; car il n’était personne qui secourût Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Et le Seigneur dit qu’il ne voulait pas effacer sous les cieux la race d’Israël; mais il la sauva par les mains de Jéroboam, fils de Joas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Quant au reste de l’histoire de Jéroboam, et aux actions qu’il fit en sa puissance, et aux combats qui rendirent Damas et Emath de Juda à Israël, ne sont-ils pas écrits au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Et Jéroboam s’endormit avec ses pères, avec les rois d’Israël, et Zacharias, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'En la vingt-septième année du règne de Jeroboam en Israël, Azarias, fils d’Amasias, monta sur le trône de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Il avait seize ans quand il devint roi, et il régna cinquante-deux ans à Jérusalem; sa mère se nommait Jéchélie de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Et il fit ce qui était droit aux yeux du Seigneur; il fit tout ce qu’avait fait son père Amasias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Mais il ne détruisit point les hauts lieux, et le peuple offrit encore des sacrifices et brûla de l’encens sur les hauts lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Or, le doigt du Seigneur avait touché le roi, et il fut lépreux jusqu’à sa mort, et il passa son règne dans une maison séparée; Joatham, fils du roi, régissait le palais, et jugeait le peuple de la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Quant au reste de l’histoire d’Azarias, n’est-il pas écrit au livre des Faits et gestes des rois de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Et Azarias s’endormit avec ses pères; on l’ensevelit auprès d’eux en la ville de David, et Joatham, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'En la trente-huitième année du règne d’Azarias en Juda, Zacharias, fils de Jéroboam, commença en Samarie un règne qui dura six mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Et il fit le mal aux yeux du Seigneur comme avaient fait ses pères; il ne se retira point des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Et Sellum, fils de Jabès, et d’autres conspirèrent contre lui; ils le frappèrent devant le peuple et le tuèrent; et Sellum régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Le reste de l’histoire de Zacharie est écrit au livre des Faits et gestes des rois d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Le Seigneur avait dit à Jéhu: Tes fils se maintiendront sur le trône d’Israël jusqu’à la quatrième génération. Et sa parole s’accomplit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sellum, fils de Jabès, fut proclamé roi; en la trente-neuvième année du règne d’Azarias en Juda, Sellum commença à Samarie un règne qui ne dura qu’un mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Car, Manahem, fils de Gaddi, vint de Tharsila, entra dans Samarie, et y frappa Sellum, fils de Jabès, et il le tua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Le reste de l’histoire de Sellum et sa révolte sont écrits au livre des faits et gestes des rois d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Alors, Manahem dévasta Thersa, tout ce qu’elle contenait et tout son territoire, parce que cette ville lui avait fermé ses portes; il en fit le sac, et il fit avorter des femmes enceintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'En la trente-neuvième année du règne d’Azarias en Juda, Manahem, fils de Gaddi, commença en Samarie un règne qui dura dix ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Et il fit le mal aux yeux du Seigneur, et il ne se relira pas des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Pendant son règne, Phua, roi des Assyriens, envahit la terre; et Manahem lui donna mille talents d’argent pour qu’il fût son allié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Et Manahem leva cet argent en Israël, sur tout homme riche, lui prenant cinquante sicles pour les donner au roi des Assyriens; Phua s’en retourna, et il ne resta point dans la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Quant au reste de l’histoire de Manahem, n’est-il pas écrit au livre des Faits et gestes des rois d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Et Manahem s’endormit avec ses pères, et son fils Phaceïa régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'En la cinquantième année du règne d’Azarias en Juda, Phaceïa commença en Samarie un règne qui dura deux ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Et il fit le mal aux yeux du Seigneur; il ne se retira pas des péchés où Jéroboam avait fait tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Et Phacée, fils de Romélie, un de ses grands officiers, conspira contre lui; il le frappa dans Samarie devant le palais du roi, avec Argob; Arias et cinquante hommes des quatre cents étaient avec lui; il le tua et il régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Le reste de l’histoire de Phaceïa est écrit au livre des Faits et gestes des rois d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'En la cinquante-deuxième année du règne d’Azarias en Juda, Phacée, fils de Romélie, commença en Samarie un règne qui dura vingt ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Il fit le mal aux yeux du Seigneur; il ne se retira pas des péchés où Jéroboam, fils de Nabat, avait fait tomber Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Sous le règne de Phacée, roi d’Israël, TheglathPhalasar, roi des Assyriens, vint prendre Aïon, Abel, Thamaacha, Anioch, Cenez, Asor, Galaan, la Galilée, toute la terre de Nephthali, et il emmena les habitants chez les Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Alors, Osée, fils d’Ela, trama un complot contre Phacée, fils de Romélie; il le frappa, le tua, et régna à sa place en la vingtième année de Joatham, fils d’Azarias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Le reste de l’histoire de Phacée est écrit au livre des Faits et gestes du roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'En la seconde année du règne de Phacée en Israël, Joatham, fils d’Azarias, devint roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Il avait vingt-cinq ans lorsqu’il monta sur le trône, et il régna seize ans à Jérusalem; sa mère se nommait Jerusa, fille de Sadoc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Et il fit ce qui est droit aux yeux du Seigneur, comme avait fait Azarias, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Mais il ne détruisit point les hauts lieux; le peuple faisait encore des sacrifices et brûlait de l’encens sur les hauts lieux; ce fut lui qui bâtit la porte supérieure du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Quant au reste de l’histoire de Joatham, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'En ces jours-là, le Seigneur commença d’envoyer contre Juda, Rasin, roi de Syrie, et Phacée, fils de Romélie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Et Joatham s’endormit avec ses pères; il fut enseveli auprès d’eux en la ville de David, son aïeul; et Achaz, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'En la dix-septième année du règne de Phacée, fils de Romélie, Achaz, fils de Joatham, devint roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Il avait vingt ans quand il monta sur le trône, et il régna seize ans à Jérusalem; il ne fit point ce qui est droit aux yeux du Seigneur son Dieu, aussi fidèlement que David, son aïeul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Et il marcha dans la voie des rois d’Israël; même il livra son fils aux flammes de Moloch, selon l’abomination des peuples que le Seigneur avait exterminés devant la face des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Et il immola des victimes sur les hauts lieux, sur les collines, et sous tout arbre touffu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Alors, Rasin, roi de Syrie, et Phacée, roi d’Israël, vinrent combattre sous les murs de Jérusalem; ils assiégèrent Achaz, mais ils ne purent prévaloir sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'En temps-là, Rasin reprit Elath pour la Syrie, il en chassa les Juifs, et des Iduméens y vinrent; et ils y sont demeurés jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Et Achaz envoya des messagers à Theglath-Phalasar, roi des Assyriens, disant Moi et mon fils, nous sommes tes serviteurs; viens, sauve-moi des mains du roi de Syrie, et des mains du roi d’Israël, qui se sont levés contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Achaz prit l’argent et l’or qui se trouva dans les trésors, soit du temple, soit du palais, et il en fit présent au roi d’Assyrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Et le roi des Assyriens l’écoula; il marcha sur Damas, la prit, la dépeupla, et mit à mort le roi Rasin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Et le roi Achaz alla dans Damas à la rencontre de Theglath-Phalasar; il vit un autel à Damas, et il envoya au prêtre Urie l’image de l’autel, ses proportions, sa structure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Et le prêtre Urie bâtit un autel selon le modèle que le roi lui avait envoyé de Damas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Puis, Achaz vit l’autel et il y monta;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Il fit son holocauste, son sacrifice et sa libation, et il répandit le sang de ses hosties pacifiques offertes sur l’autel');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'D’airain qui était devant le Seigneur. Et il transporta cet autel de devant la façade du temple, du lieu entre l’autel et le temple, et il le dressa du même côté en tirant vers le nord.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Ensuite, le roi Achaz donna ses ordres au prêtre Urie, disant Tu présenteras, sur le grand autel, l’holocauste du matin, les oblations du soir, l’holocauste du roi et son oblation, l’holocauste de tout le peuple, et son oblation et sa libation; tu répandras sur le même autel tout le sang de l’holocauste et tout le sang de toute autre victime, et l’autel d’airain le matin me sera réservé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Et Urie le prêtre fit tout ce que lui avait prescrit le roi Achaz.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Le roi Achaz effaça les ciselures des bassins, il enleva les cuvettes qu’ils supportaient, et il ôta, pour la mettre sur une base de pierre, la mer qui reposait sur les bœufs d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Et il construisit une base pour le trône dans le temple du Seigneur, et il transporta à l’intérieur la porte extérieure par laquelle le roi entrait dans le temple, à cause du roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Quant au reste de l’histoire du roi Achaz, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Et Achaz s’endormit avec ses pères; il fut enseveli dans la ville de David, et son fils Ezéchias régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'En la douzième année du règne d’Achaz, en Juda, Osée, fils d’Ela, commença en Samarie, sur Israël, un règne de neuf ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Et il fit le mal aux yeux du Seigneur, mais non comme les rois d’Israël qui avaient existé avant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Salmanasar, roi des Assyriens, marcha contre lui; Osée lui fut asservi, et il lui paya un tribut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Ensuite, Salmanasar trouva en Osée une iniquité, en ce qu’il avait envoyé des messagers à Ségor, roi d’Égypte, et n’avait point payé cette année-là le tribut au roi des Assyriens; et celui-ci l’assiégea et le jeta, enchaîné, dans une prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Puis, il parcourut toute la terre d’Israël, et monta à Samarie, qu’il assiégea trois ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Ce fut en la neuvième année du règne d’Osée, que Salmanasar prit Samarie, et transporta Israël en Assyrie, où il l’établit en Hala, en Habor, sur le fleuve Gozan, et sur les montagnes des Mèdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Et cela arriva, parce que les fils d’Israël avaient péché contre le Seigneur leur Dieu, qui les avait tirés de l’Égypte, et délivrés des mains du roi Pharaon; parce qu’ils avaient craint d’autres dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Car ils avaient marché dans les voies des nations que le Seigneur avait exterminées devant les fils d’Israël, et dans celles des rois d’Israël qui avaient fait de tels péchés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Et dans celles des enfants d’Israël, adonnés à des coutumes qui n’étaient point selon le Seigneur leur Dieu; ils s’étaient bâti des hauts lieux en toutes les villes, depuis les tours des guetteurs jusqu’aux cités entourées de remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Et ils s’étaient dressé des colonnes dans des bois sacrés sur toutes les hautes collines, et sous tous les arbres touffus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Et ils avaient fait des sacrifices sur tous les hauts lieux, comme les nations que le Seigneur avait expulsées de devant leur face; ils avaient formé de honteuses associations, ils avaient gravé des images pour irriter le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Et ils avaient servi des idoles au sujet desquelles le Seigneur leur avait dit: Ne faites point cette offense au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Cependant, le Seigneur protestait en Israël et en Juda par la bouche de tous ses voyants et de tous ses prophètes, disant: Détournez-vous de vos mauvaises voies, observez mes commandements et mes préceptes; suivez en toutes choses la loi que j’ai donnée à vos pères, et tout ce que je leur ai mandé par mes serviteurs les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mais ils ne l’écoutaient point; ils s’endurcissaient le cœur plus que ne l’avaient fait leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Ils ne gardaient aucun des témoignages que portait le Seigneur; ils marchaient à la suite des vanités, étant vains eux-mêmes; à la suite des nations qui les entouraient, au sujet desquelles le Seigneur leur avait dit: Ne faites pas comme elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Ils abandonnaient les commandements du Seigneur leur Dieu; ils s’étaient fait deux génisses jetées en fonte; ils plantaient des bois sacrés; ils adoraient toute l’armée du ciel, et ils servaient Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Et ils faisaient passer dans la flamme de Moloch leurs fils et leurs filles; ils usaient de la divination et des présages, et ils s’attachaient à faire le mal aux yeux du Seigneur et à l’irriter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Et le Seigneur conçut un grand courroux contre Israël; il le rejeta de devant sa face, et il ne resta que la seule tribu de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Et Juda lui-même n’observa point les commandements du Seigneur son Dieu; il marcha dans les voies d’Israël, et il répudia le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Et le Seigneur se courrouça contre toute la race d’Israël; il les ébranla, il les livra à tous ceux qui vinrent les piller, jusqu’à ce qu’il les rejetât de devant sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Il le fit surtout parce qu’Israël ayant rejeté la maison de David, et s’étant donné pour roi Jéroboam, fils de Nabat, Jéroboam entraîna Israël hors des voies du Seigneur, et lui fit commettre un grand péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Car, les fils d’Israël tombèrent tous dans le péché de Jéroboam, et ils ne s’en retirèrent point,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Jusqu’à ce que le Seigneur eût expulsé Israël de devant sa face, comme il l’en avait menacé par la voix de tous ses serviteurs les prophètes. Et Israël fut emmené en la terre des Assyriens, où il est encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Ensuite, le roi des Assyriens amena des hommes de Babylone, de Chuth, d’Aïa, d’Emath, de Sepharvaïm, et il les établit en Samarie à la place des fils d’Israël; ils se partagèrent son territoire, et ils demeurèrent dans ses villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Dans les premiers temps de leur séjour, ils ne craignaient point le Seigneur, et le Seigneur envoya contre eux des lions qui en tuèrent quelques-uns.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Ils le firent savoir au roi des Assyriens, disant: Les nations que tu as transportées et assises dans les villes de Samarie, ne connaissaient point les jugements du Dieu de cette terre; et il a envoyé contre eux des lions; et voilà que ces lions les tuent, parce qu’ils ne savent pas les jugements du Dieu de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Et le roi des Assyriens donna ses ordres, disant: Emmenez d’ici des gens, qu’ils partent, qu’ils demeurent avec vous; ils vous éclaireront sur les jugements du Dieu de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Et ils emmenèrent un des prêtres qu’on avait transportés de Samarie; il s’établit à Béthel; il les éclaira, et il leur apprit comme ils devaient craindre le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Mais, chaque nation fabriqua ses dieux; on les plaça dans les temples des hauts lieux que les Samaritains avaient construits; chaque nation eut les siens dans les villes qu’elle habitait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Ceux de Babylone avaient fabriqué Soccoth-Benith; ceux de Chuth, Ergel; ceux d’Emath, Asimath;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Les Evéens fabriquèrent Eblazer et Tharthac; ceux de Sepharvaïm firent le mal quand ils brûlèrent leurs fils dans les flammes d’Adra-Moloch et d’Ana-Moloch, leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Ils craignaient le Seigneur; mais ils avaient établi leurs abominations dans les temples des hauts lieux qu’avaient construits les Samaritains, chacun dans la ville que sa nation habitait; ils craignaient le Seigneur; mais ils avaient institué pour eux des prêtres des hauts lieux, et ils sacrifiaient dans les temples des hauts lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Ils craignaient le Seigneur, mais ils servirent leurs dieux selon l’usage des nations dont ils avaient été tirés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Jusqu’à ce jour, ils ont agi selon leurs usages; les mêmes gens craignent le Seigneur et agissent selon leurs mœurs, selon leurs usages, et en même temps selon la loi et les préceptes que le Seigneur a donnés aux fils de Jacob, qu’il a appelé aussi Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Avec qui le Seigneur fit jadis alliance, disant: Vous ne craindrez point d’autres dieux, vous ne les adorerez pas, vous ne les servirez point, vous ne leur ferez point de sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Vous ne craindrez, vous n’adorerez, vous n’honorerez par des sacrifices que le Seigneur qui vous a ramenés d’Égypte par sa toute-puissance, et par son bras très-haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Vous observerez toujours les ordonnances, les jugements, la loi et les commandements qu’il a écrits, pour que vous les pratiquiez; vous ne craindrez point d’autres dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Et vous n’abandonnerez point l’alliance qu’il a faite avec vous, et vous ne craindrez point d’autres dieux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Vous ne craindrez que le Seigneur votre Dieu, et il vous délivrera de tous vos ennemis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Vous ne suivrez point les pratiques que suivent les Gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Ces nations nouvelles craignaient donc le Seigneur, et elles servaient leurs idoles; et leurs fils, et les fils de leurs fils, ont fait comme leurs pères jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'En la troisième année du règne d’Osée, en Israël, Ezéchias, fils d’Achaz, devint roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Il avait vingt-cinq ans quand il monta sur le trône, et il régna vingt-neuf ans à Jérusalem; sa mère se nommait Abu, fille de Zacharie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Et il fit ce qui est droit aux yeux du Seigneur, se conformant à tout ce qu’avait fait David, son aïeul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Ce fut lui qui détruisit les hauts lieux, qui abattit les colonnes, qui arracha les bois sacrés, et le serpent d’airain qu’avait fait Moïse; car, jusqu’à ces jours-là, les enfants d’Israël l’avaient encensé; Ezéchias lui donna le nom de Neesthan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'En Dieu seul il mit son espérance, et après lui il n’y eut point en Juda de roi qui lui ressemblât, et il n’y en avait pas eu parmi ceux qui l’avaient précédé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Il s’attacha au Seigneur, et il ne cessa pas de le suivre; il observa tous les commandements qu’il avait donnés à Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Et le Seigneur était avec lui, et il montra de la sagesse en toutes ses entreprises; il se révolta contre le roi des Assyriens, et il ne lui resta pas asservi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Ce fut lui qui frappa les Philistins jusqu’à Gaza et sa banlieue, depuis les tours des guetteurs jusqu’aux cités fortifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'En la quatrième année du règne d’Ezéchias (la septième année du règne d’Osée, en Israël), Salmanasar, roi des Assyriens, ayant marché contre Samarie, l’assiégea.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Et il la prit au bout de trois ans, en la huitième année du règne d’Ezéchias (la neuvième du règne d’Osée, celle où tomba Samarie).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Puis, le roi des Assyriens transporta ses habitants en Haba et en Habor, sur le fleuve Gozan, et sur les montagnes des Mèdes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Parce que les Samaritains n’avaient point obéi à la voix du Seigneur, qu’ils avaient violé son alliance, qu’ils n’avaient ni écouté, ni pratiqué ce qu’il avait prescrit à son serviteur Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'En la quatorzième année du règne d’Ezéchias, Sennachérib, roi des Assyriens, vint assiéger les villes fortes de Juda, et il les prit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Alors, le roi Ezéchias envoya des messagers au roi des Assyriens à Lachis, disant: J’ai failli, éloigne-toi de moi; ce dont tu me chargeras, je le porterai. Et le roi des Assyriens chargea Ezéchias d’une taxe de trois cents talents d’argent et trois cents talents d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Et le roi de Juda donna tout l’argent qui se trouva dans le temple et dans les trésors de son palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'En ce temps-là, Ezéchias ôta l’or des portes du temple et les lames d’or dont il avait lui-même revêtu les colonnes, et il les donna au roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Et le roi des Assyriens envoya de Lachis, au roi Ezéchias, Tharthan, Rhaphis et Rhabsacès, accompagnés d’une forte armée; ils arrivèrent devant Jérusalem, et s’arrêtèrent à l’aqueduc de la piscine supérieure qui est sur le chemin du Champ du Foulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'De là, ils appelèrent à grands cris Ezéchias; aussitôt Eliacim, fils d’Helcias, l’économe; Sobna le scribe, et Joas, fils de Saphat, l’archiviste, vinrent les trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Et Rhabsacès leur dit: Dites à Ezéchias: Voici ce que dit le grand roi, le roi des Assyriens: Quel est l’appui en qui tu t’es confié?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Tu as dit (mais seulement des lèvres): Mon conseil, mon armée, inclinent pour la guerre; maintenant donc, en qui t’es-tu confié, pour te révolter contre nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Voyons, n’as-tu point foi en ce roseau brisé qu’on appelle l’Égypte? Il entrera dans la main de quiconque s’appuiera sur lui, et il la percera. Voilà comment est le Pharaon d’Égypte pour tous ceux qui se fient en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Mais, tu m’as dit: Nous nous confions en Dieu le Seigneur. Or, ce Dieu n’est-il pas le même dont Ezéchias a détruit, sur les hauts lieux, les autels, quand il a donné cet ordre à Jérusalem et à Juda: Vous adorerez, devant cet autel seul, dans Jérusalem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Eh bien! combats aujourd’hui mon maître le roi des Assyriens, et je te donnerai deux mille chevaux, si tu peux te donner toi-même deux mille cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Comment donc feras-tu reculer le moindre des chefs qui servent mon maître? Et tu mets ta confiance en l’Égypte, en ses chars, en ses chevaux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Est-ce que nous sommes venus détruire cette terre sans le Seigneur? Le Seigneur m’a dit: Marche sur cette terre, et détruis-la.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Et Eliacim, fils d’Helcias, Sobna et Joas dirent à Rhabsacès Parle syrien à tes serviteurs, car nous l’entendons; ne nous parle pas en langue judaïque. Pourquoi parles-tu pour être ouï du peuple qui est sur les remparts?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Mais Rhabsacès répondit: Est-ce que mon maître m’a envoyé dire ces paroles à ton maître et à toi? Ne sont-elles pas pour les hommes qui se tiennent sur les remparts, et qui sont réduits comme vous à manger leurs excréments et à boire leur urine?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Et Rhabsacès, se redressant, éleva la voix, et dit en langue judaïque: Écoutez les paroles du grand roi des Assyriens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Voici ce que dit le roi: Qu’Ezéchias ne vous excite point par ses discours, car il ne pourra vous arracher de mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Qu’Ezéchias ne vous fasse point espérer au Seigneur, disant: Le Seigneur nous délivrera; il ne livrera point sa ville au roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'N’écoutez point Ezéchias; car voici ce que dit le roi des Assyriens: Cherchez auprès de moi votre bénédiction; venez à moi, et chacun boira le vin de sa vigne, chacun mangera les fruits de son figuier, chacun boira l’eau de sa citerne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Jusqu’à ce que je revienne pour vous transporter en une terre comme la vôtre, en une terre de blé et de vignes, terre de pain et de vin, terre d’huile et de miel; et vous vivrez et vous ne mourrez point. N’écoutez point Ezéchias; car il vous trompe, quand il dit: Le Seigneur vous délivrera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Les dieux des nations qui tour à tour sont tombées dans les mains du roi, les ont-ils délivrées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Où est le dieu d’Emath et d’Arphad? Où est le dieu de Sepharvaïm, d’Ana et d’Aba? Ont-ils délivré Samarie de mes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Quel est donc celui des dieux, de toutes les nations, qui ait délivré sa terre de mes mains? Le Seigneur délivrera-t-il Jérusalem de mes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Et le peuple resta muet; personne ne répondit à ce discours; car le roi l’avait ainsi ordonné, disant: Ne lui répondez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Et l’économe Eliacim, fils d’Helcias, le scribe Sobna et l’archiviste Joas, fils de Saphat, rentrèrent auprès d’Ezéchias après avoir déchiré leurs vêtements; ils lui rapportèrent les paroles de Rhabsacès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Lorsque le roi Ezéchias les eut ouïs, il déchira aussi ses vêtements, se couvrit d’un cilice, et alla au temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Et il envoya Eliacim, et Sobna et Joas, couverts de cilices, auprès du prophète Isaïe, fils d’Amos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Et ils lui dirent: Voici ce que dit Ezéchias: Ce jour est un jour d’affliction, de reproches et de provocation; car les fils prêts à naître sont venus jusqu’aux douleurs; mais la mère, en mal d’enfant, n’a plus de force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Si, de quelque manière, le Seigneur avait ouï toutes les paroles de Rhabsacès, que le roi des Assyriens, son maître, a envoyé pour outrager le Dieu vivant, pour blasphémer par ces paroles qu’a sans doute entendues le Seigneur ton Dieu, prie donc pour ceux de nous qui restent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Ainsi, les serviteurs du roi Ezéchias vinrent à Isaïe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Et le prophète leur dit: Dites à votre maître: Voici ce que dit le Seigneur: Ne crains pas les paroles de blasphème que tu as entendues des serviteurs du roi d’Assyrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Voilà que je mets en lui un esprit; il va apprendre une nouvelle, il va retourner en son royaume, et je le ferai périr, par le glaive, en son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Pendant ce temps, Rhabsacès, ayant ouï dire que le roi était parti de Lachis, le rejoignit à Lobna, qu’il assiégeait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Alors, le roi entendit parler de Tharaca, roi d’Ethiopie; on disait: Voilà qu’il s’est mis en campagne pour te combattre. Sennacherib s’en retourna donc; il envoya des messagers à Ezéchias, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Que ton Dieu, en qui tu as mis ta confiance, ne t’excite pas, en te disant: Jérusalem ne sera pas livrée aux roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Tu as ouï tout ce que les rois d’Assyrie ont fait à toutes les contrées en les vouant à la destruction? Et toi tu leur échapperais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Est-ce que les dieux des nations que nos pères ont anéanties, les ont préservées? Ont-ils sauvé Gozan, et Haran, et Rhaphis et les fils d’Edem, qui habitaient Thaesthen?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Où sont les rois d’Emath et d’Arphad? Où est le roi des villes de Sepharvaïm, d’Ana et d’Aba?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Et Ezéchias prit cette lettre de Sennacherib des mains de ses messagers, et il la lut; puis, il monta au temple du Seigneur; il la déploya devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Et il dit: Seigneur Dieu d’Israël, qui êtes assis sur les chérubins, vous êtes le seul Dieu de tous les royaumes de la terre, vous avez créé le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Seigneur, inclinez votre oreille, et écoutez; Seigneur, ouvrez les yeux, et voyez; soyez attentif aux paroles que Seunachérib envoie pour outrager le Dieu vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Il est vrai, Seigneur, que les rois des Assyriens ont dépeuplé les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Ils ont livré leurs dieux aux flammes; car ce n’é');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Maintenant, Seigneur notre Dieu, délivrez-nous des mains de Sennachérib, et tous les royaumes de la terre sauront que vous seul êtes le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Et Isaïe, fils d’Amos, envoya un messager chez Ezé chias, disant: Voici ce que dit le Seigneur Dieu des armées, Dieu d’Israël: La prière que tu m’as faite au sujet de Sennacherib, roi des Assyriens, je l’ai entendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Voici les paroles qu’a dites sur lui le Seigneur: La vierge fille de Sion t’a méprisé, et elle t’a raillé; la vierge fille de Jérusalem a secoué sur toi la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Qui donc as-tu outragé? Contre qui donc as-tu blasphémé? Contre qui donc as-tu élevé la voix et lancé tes regards hautains? C’est contre le Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Tu as outragé le Seigneur par tes messagers, et tu as dit Avec la multitude de mes chars je suis monté sur la cime des montagnes, sur les pics du Liban; j’ai abattu ses grands cèdres et ses plus beaux cyprès; je suis venu au cœur de la forêt de chênes du Carmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Je me suis baigné dans des eaux étrangères, j’en ai bu; et, sous la plante de mes pieds, j’ai desséché tous les fleuves, même les plus profonds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Or, c’est moi le Seigneur qui ai formé ce dessein et qui l’ai accompli; j’ai d’abord excité l’insolence de bandes étrangères habiles à combattre les villes fortifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Et ceux qui les habitaient ont eu les mains énervées; ils ont tremblé, ils ont été couverts de honte. Ils sont devenus comme l’herbe des champs, comme la plante verte, comme le gazon des terrasses qu’en marchant on foule aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Je connaissais ta demeure, ton départ, ta fureur et ta rage contre moi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Tes menaces insolentes sont parvenues à mes oreilles; mais je mettrai un harpon dans tes narines et un mors à ta bouche, et je te renverrai par le chemin qu’en venant tu as pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Pour toi, Ezéchias, voici le signe mange cette année ce qui vient de soi-même; puis, l’année prochaine, ce qui aura poussé. En la troisième année, il Y aura semence et moisson; vous replanterez vos vignes et vous mangerez leurs fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Le Seigneur fera grandir le reste de la maison de Juda; ce qui en sera sauvé continuera d’enfoncer ses racines dans le sol et de produire des fruits au haut des branches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Car il sortira un reste de Jérusalem, un débris sauvé de la montagne de Sion; et cela nous sera accordé par l’amour du Seigneur des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'N’en est-il pas ainsi? Voici ce que dit le Seigneur, concernant le roi des Assyriens Il n’entrera point en cette ville, ses archers n’y lanceront pas une flèche; il n’y aura pas de bouclier qui s’avance contre elle, on n’élèvera point de retranchements autour de ses remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Il s’en retournera par le chemin qu’en venant il a pris, et il n’entrera point en cette ville, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'J’étendrai mon bouclier sur cette ville, à cause de moi-même, et à cause de David, mon serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Or, la nuit survint, et l’ange du Seigneur s’avança, et il extermina, dans le camp des Assyriens, cent quatre-vingt-cinq mille hommes; les survivants se levèrent dès l’aurore, et ils ne virent que des cadavres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Et Sennachérib partit; il s’en retourna, et il ne sortit plus de Ninive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Et, comme il adorait dans le temple son dieu Méserach, ses fils Adramelech et Sarasar le tuèrent à coups d’épée; puis, ils se sauvèrent en la terre d’Ararat, et Asordan, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'En ces jours-là, Ezéchias tomba malade d’une maladie mortelle; le prophète Isaïe, fils d’Amos, l’alla trouver, et lui dit Voici ce que dit le Seigneur: Donne tes ordres à ta maison; tu mourras, tu n’as plus guère à vivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Mais Ezéchias se retourna du côté du mur, et il pria le Seigneur, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Seigneur, souvenez-vous que j’ai marché devant vous dans la vérité et de tout mon cœur, et que j’ai fait ce que bon vous a semblé. Puis, Ezéchias se prit à pleurer amèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Isaïe était alors au milieu du parvis, et la parole du Seigneur vint à lui, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Rentre, et dis à Ezéchias, chef de mon peuple: Voici ce que dit le Seigneur Dieu de David, ton aïeul: J’ai entendu ta prière, j’ai vu tes larmes, je te guérirai; dans trois jours tu monteras au temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Et j’ajouterai quinze ans à ta vie; je sauverai toi et cette ville du roi des Assyriens; j’étendrai mon bouclier sur cette ville, à cause de moi-même et à cause de David, mon serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Et le prophète dit: Que l’on prenne un cabas de figues, qu’on les applique sur l’ulcère, et il sera guéri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Et Ezéchias dit au prophète: A quel signe reconnaîtrai-je que le Seigneur me guérira, et que dans trois jours je monterai au temple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Isaïe répondit: Voici le signe du Seigneur, qui te montrera que sa parole doit s’accomplir: L’ombre s’avancera-t-elle où reculera-t-elle de dix degrés?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Le roi reprit: L’ombre avancera facilement de dix degrés. Ce n’est point cela que je demande, mais que sur les marches elle recule de dix degrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Et le prophète cria au Seigneur; et l’ombre, sur les marches, recula de dix degrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'En ce temps-là, Marodach, fils de Baladan, roi de Babylone, envoya à Ezéchias une lettre et des présents, parce qu’il avait appris qu’Ezéchias était malade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ezéchias en fut réjoui, et il montra aux messagers d’abord toute la maison des épices, l’argent et l’or, les aromates et la bonne huile; ensuite, l’arsenal; puis, tout ce qui se trouvait en ses trésors. Il n’y eut rien qu’Ezéchias ne fît voir dans son palais et dans ses domaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Mais le prophète, Isaïe alla trouver le roi Ezéchias, et il lui dit: Que t’ont dit ces hommes, et d’où sontils venus? Le roi répondit: Ils sont venus vers moi d’une contrée lointaine, de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Le prophète reprit: Qu’ont-ils vu dans ton palais? Le roi dit: Ils ont vu ce que non palais renferme; il n’y a rien que je ne leur aie montré, soit dans mon palais, soit dans mes trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Et le prophète Isaïe dit à Ezéchias: Écoute la parole du Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Les jours approchent où tout ce que renferme ton palais sera pris, où tous les trésors que tes pères ont amassés jusqu’à ce moment, iront à Babylone. Et la parole du Seigneur ne sera pas en défaut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Quant à tes fils, qui sortiront de toi, que tu auras engendrés, l’ennemi les prendra, et ils seront eunuques dans le palais du roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Et Ezéchias dit à Isaïe: La parole que le Seigneur a dite est bonne; mais que la paix se maintienne tout le temps de ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Quant au reste de l’histoire d’Ezéchias, à ses guerres, à toutes ses actions, à la fontaine, l’aqueduc et l’eau qu’il a amenée dans la ville, ne sont-ils pas écrits au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Et Ezéchias s’endormit avec ses pères, et Manassé, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manassé avait douze ans quand il monta sur le trône, et il régna cinquante-cinq ans à Jérusalem; sa mère se nommait Apsiba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Et il fit le mal aux yeux du Seigneur: les abominations des peuples que le Seigneur avait détruits devant les fils d’Israel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Il se pervertit, et il rebâtit les hauts lieux qu’avait abattus Ezéchias, son père; il releva l’autel de Baal; il planta des bois sacrés, comme Achab, roi d’Israël; il adora toute l’armée du ciel, et il la servit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Il bâtit un autel dans le temple du Seigneur, qui avait dit: En Jérusalem je placerai mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Et il bâtit un autel à toute l’armée du ciel, dans chacun des deux parvis du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Et il fit passer de ses fils dans la flamme; il usa de la divination et des augures, il consacra des enclos; il multiplia les devins, faisant le mal aux yeux du Seigneur pour l’irriter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'L’idole du bois sacré, il la mit dans le temple, dont le Seigneur avait dit à David et à Salomon, son fils: En ce temple et en cette ville de Jérusalem, que j’ai choisie parmi toutes les tribus, je placerai mon nom pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Car je ne veux plus éloigner de la terre que j’ai donnée à leurs pères le pied des fils d’Israël, du moins de ceux qui garderont tout ce que j’ai prescrit, tous les commandements que leur a fait connaître Moïse, mon serviteur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mais ils n’écoutèrent pas le Seigneur; Manassé les égara, pour qu’ils fissent le mal aux yeux du Seigneur, plus encore que les nations que le Seigneur avait détruites devant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Et le Seigneur parla par la voix de ses serviteurs les prophètes, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'En punition de ce qu’a fait Manassé, de ses abominations, de ses crimes, qui surpassent ceux de l’Amorrhéen d’autrefois, de ce qu’il a fait tomber Israël dans le péché, par ses idoles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Il n’en sera pas ainsi. Voici ce que dit le Seigneur Dieu d’Israël: Voilà que j’apporte à Jérusalem et à Juda des maux tels, que les oreilles de quiconque les ouïra en tinteront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Et j’étendrai sur Jérusalem la mesure de Samarie et le niveau de la maison d’Achab; je récurerai Jérusalem comme on récure un vase que l’on retourne sens dessus dessous en l’essuyant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Je répudierai les restes de mon héritage; je les livrerai aux mains de leurs ennemis; ils seront pour tous leurs ennemis une proie et un butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'En punition de ce qu’ils ont fait le mal à mes yeux, et de ce qu’ils n’ont jamais cessé de m’irriter, depuis que j’ai tiré leurs pères de l’Égypte jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Or, Manassé répandit à grands flots le sang innocent, jusqu’à ce que, d’une extrémité à l’autre, il en eût rempli Jérusalem, outre les péchés où il fit tomber Juda en faisant le mal aux yeux du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Quant au reste de l’histoire de Manassé, et aux péchés où il tomba, ne sont-ils pas écrits au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Et Manassé s’endormit avec ses pères; il fut enseveli dans le jardin de son palais, dans le jardin d’Oza, et son fils Amos régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amos avait vingt-deux ans quand il monta sur le trône, et il régna deux ans à Jérusalem; sa mère se nommait Mésollam, fille d’Arus de Jétéba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Et il fit le mal aux yeux du Seigneur, comme l’avait fait Manassé, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Il marcha dans toutes les voies où son père avait marché, et il servit les idoles que son père avait servies, et il les adora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Il abandonna le Seigneur Dieu de ses pères; il ne marcha pas dans la voie du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Et les serviteurs d’Amos conspirèrent contre lui, et ils le tuèrent dans son palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Alors, le peuple de la terre mit à mort ceux qui avaient conspiré contre le roi Amos, et il proclama roi Josias, son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Quant au reste de l’histoire d’Amos, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Et on l’ensevelit en son sépulcre dans le jardin d’Oza, et Josias, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josias avait huit ans quand il monta sur le trône, et il régna trente et un ans à Jérusalem; sa mère se nommait Jedia, fille d’Edia de Basuroth..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Et il fit ce qui est droit aux yeux du Seigneur; il marcha dans toutes les voies de David, son aïeul; il n’en dévia ni à droite ni à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'En la troisième année du règne de Josias, le huitième mois, le roi envoya Saphan, fils d’Ezélie, fils de Mésollam, scribe du temple du Seigneur, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Monte auprès d’Helcias le grand prêtre; compte l’argent offert par le peuple dans le temple, et recueilli par les gardiens de la porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Qu’ils remettent cet argent aux ouvriers employés dans le temple. Et l’on donna cet argent aux ouvriers du temple, pour qu’ils y fissent des réparations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'On le donna aux charpentiers, aux constructeurs, aux maçons, pour acheter du bois et des pierres de taille, et consolider le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Mais on ne leur demanda pas compte de l’argent qui leur fut confié, parce que les travaux furent exécutés de bonne foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Or, le grand prêtre Helcias dit à Saphan le scribe: J’ai trouvé dans le temple le livre de la loi. Et il lui donna le livre; puis, Saphan le lut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Ensuite, il entra auprès du roi dans le temple; il lui rapporta ce qui avait été fait, et il dit: Tes serviteurs ont fondu l’argent trouvé dans le temple du Seigneur, et ils l’ont remis aux ouvriers du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Et Saphan le scribe ajouta: Le prêtre Helcias m’a donné un livre. Et Saphan le lut devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Quand Josias ouït les paroles du livre de la loi, il déchira ses vêtements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Et il donna ses ordres à Helcias le prêtre, à Achicam, fils de Saphan, à Achobor, fils de Michée, à Saphan le scribe, à Asaïe, serviteur du roi, et il leur dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Allez au Seigneur vous enquérir de moi, de tout le peuple, de tout Juda, concernant les paroles de ce livre qu’on a trouvé; car la colère dont le Seigneur s’est enflammé contre nous est grande, parce que nos pères n’ont point écouté les paroles de ce livre pour faire selon ce qui est écrit à notre sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Et le prêtre Helcias, Achicam, Achobor, Saphan et Asaïe, allèrent chez la prophétesse Olda, mère de Sellem, fils de Thécuan, fils d’Aras, gardien des vêtements. Elle demeurait à Jérusalem dans le quartier de Masena, et ils lui parlèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Et elle leur répondit: Voici ce que dit le Seigneur Dieu d’Israël Dites à l’homme qui vous a envoyés près de moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Voici ce que dit le Seigneur: Voilà que j’apporte des maux à ce lieu et à ceux qui l’habitent, selon les paroles du livre qu’a lu le roi de Juda;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'En punition de ce qu’ils m’ont abandonné, et de ce qu’ils ont encensé d’autres dieux, de sorte qu’ils m’ont irrité par toutes les œuvres de leurs mains; car ma colère est enflammée contre ce lieu, et elle ne s’éteindra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Quant au roi de Juda, qui vous a envoyés vous enquérir au Seigneur, dites-lui: Voici ce que dit le Seigneur Dieu d’Israël au sujet des paroles que tu as entendues:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'En récompense de ce que ton cœur ne s’est point endurci, de ce que devant moi tu es rentré en toi-même quand tu as ouï ce que j’ai dit contre ce lieu et contre ceux qui l’habitent, pour qu’ils soient effacés et maudits; de ce que tu as déchiré tes vêtements et pleuré en ma présence eh bien! moi aussi j’ai entendu, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Il n’en sera pas ainsi: voilà que je te réunis à tes pères; tu descendras en paix dans ton sépulcre, et tes yeux ne verront aucun des maux que j’apporte en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Et ils rapportèrent au roi ces paroles; et il envoya des messagers, et il assembla autour de lui tous les anciens de Juda et de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Et le roi monta au temple du Seigneur avec tout Juda, tous les habitants de Jérusalem, les prêtres, les prophètes, tout le peuple, depuis le petit jusqu’au grand, et il lut à leurs oreilles toutes les paroles du livre de l’alliance trouvé dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Ensuite, le roi, debout sur le piédestal, renouvela l’alliance devant le Seigneur, afin de suivre le Seigneur, de garder ses commandements, ses témoignages et ses justices, de tout son cœur, dans la plénitude de son âme; et enfin, de faire revivre toutes les paroles de l’alliance écrite dans le livre; or, tout le peuple acquiesça à l’alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Et le roi prescrivit à Helcias le grand prêtre, aux prêtres du second rang et aux gardiens de la porte, d’enlever du temple du Seigneur tous les vases faits pour Baal, pour le bois sacré et pour l’armée du ciel; il les brûla hors de Jérusalem dans la vallée de Cédron, et il en fit porter les cendres à Béthel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Puis, il brûla vifs les prêtres idolâtres qu’avaient institués les rois de Juda et qui encensaient sur les hauts lieux, soit dans les villes de Juda, soit autour de Jérusalem, et aussi ceux qui encensaient Baal, le soleil, la lune, les douze signes et toute l’armée du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Et il emporta l’idole des bois sacrés hors du temple, hors de Jérusalem dans le torrent de Cédron; il la réduisit en cendres qu’il dispersa sur la sépulture des fils du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Il démolit la demeure des initiés qu’on avait construite dans le temple, et où les femmes tissaient des tentes pour le bois sacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Il assembla ensuite tous les prêtres des villes de Juda; et il souilla les hauts lieux, où les prêtres avaient brûlé de l’encens, depuis Gebal jusqu’à Bersabée; puis, il abattit la maison des portes, à côté de la demeure de de Josué, prince de Jérusalem, à gauche, en sortant de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Cependant, les prêtres des hauts lieux ne montèrent plus à l’autel du Seigneur à Jérusalem, à moins qu’ils n’eussent mangé des azymes au milieu de leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Josias souilla encore Tapheth dans le val des fils d’Ennom, où ils faisaient passer dans la flamme de Moloch, les uns leurs fils, les autres leurs filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Il brûla les chevaux que les rois de Juda avaient consacrés au soleil, à l’entrée du temple, dans le trésor de Nathan, eunuque du roi, à Pharurim; il brûla en outre le char du soleil,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Et les autels que les rois de Juda avaient élevés sur la terrasse au-dessus de la chambre d’Achaz, et ceux que Manassé avait construits dans les deux parvis du temple; il en fit jeter les cendres dans le torrent de Cédron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Le roi souilla aussi le temple que Salomon, roi d’Israël, avait érigé en face de Jérusalem, à droite du chemin de la montagne de Mosthath, en l’honneur d’Astarté, abomination des Sidoniens et de Chamos, abomination de Moab et de Moloch, abomination des Ammonites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Il mit en pièces leurs colonnes, détruisit leurs bois sacrés, et remplit d’ossements humains le lieu où on les adorait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Puis, il abattit l’autel qu’en Bethel, sur le haut lieu, Jéroboam, fils de Nabat, avait élevé et où il avait fait tomber tout le peuple dans le péché; il le démolit. Il en broya les pierres, il les réduisit en poudre, et il brûla le bois sacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Et Josias, se détournant, vit les sépulcres de cette ville; aussitôt, il donna ses ordres: il en fit extraire les ossements, et il les brûla sur l’autel pour le souiller, selon la parole du Seigneur qu’avait dite l’homme de Dieu quand Jeroboam avait célébré la fête de l’autel; puis, se retournant encore, il leva les yeux et il vit la sépulture de cet homme de Dieu qui avait dit ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Et il dit: Quel est ce tombeau que j’aperçois? Et les hommes de la ville lui répondirent: Celui de l’homme de Dieu qui est venu de Juda, et qui a fait les imprécations contre l’autel de Béthel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Et le roi dit: Respectez-le; que nul n’enlève ses ossements. Et ses os furent sauvés avec ceux du prophète qui était venu de Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Josias détruisit donc tous les temples des hauts lieux que les rois d’Israël avaient élevés dans les villes de Samarie, pour y irriter le Seigneur, et il y fit la même chose qu’à Béthel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Et il sacrifia sur leurs autels tous les prêtres des hauts lieux qui étaient là, il y brûla les os des hommes, et il retourna à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Et le roi donna ses ordres à tout le peuple, disant: Immolez la pâque au Seigneur notre Dieu, comme il est écrit au livre de cette alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Car, on n’avait point ainsi célébré cette fête depuis le temps des Juges qui jugeaient Israël; ni sous les rois d’Israël, ni sous les rois de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Ce ne fut qu’en la dix-huitième année du règne de Josias, que l’on immola la pâque au Seigneur à Jérusale m');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'En outre, Josias extermina les initiés et les devins; il détruisit les idoles, les images et toutes les abominations qui existaient tant à Jérusalem qu’en Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Il n’y avait point eu auparavant de roi qui, comme lui, se convertît à Dieu de tout son cœur, de toute son âme et de toutes ses forces, conformément à la loi de Moïse; et il n’y en eut point après lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Mais le Seigneur ne détourna point la colère dont il était enflammé contre Juda, à cause des offenses qu’il avait reçues de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Et le Seigneur dit: J’expulserai aussi Juda de devant ma face comme j’ai expulsé Israël; je répudierai cette ville que j’avais choisie, cette Jérusalem, et le temple dont j’avais dit: C’est là que sera mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Quant au reste de l’histoire de Josias, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Sous son règne, le Pharaon d’Égypte Néchao marcha sur le fleuve Euphrate contre le roi des Assyriens; Josias se porta à sa rencontre, et Néchao le tua à Mageddo, au premier choc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Les serviteurs placèrent son corps sur un char, et le ramenèrent de Mageddo à Jérusalem, et ils l’ensevelirent dans son sépulcre; alors, le peuple de la terre prit Joachaz, fils de Josias; il le sacra, et il le proclama rọi à la place de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joachaz avait vingt-trois ans quand il monta sur le trône, et il régna trois mois à Jérusalem; le nom de sa mère était Amital, fille de Jérémie de Lobna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Et il fit le mal aux yeux du Seigneur, comme l’avaient fait ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Et le Pharaon Néchao le transporta en Rablaam dans la terre d’Emath, pour qu’il ne régnât point à Jérusalem; puis, il imposa à la terre un tribut de cent talents d’argent et de cent talents d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'A sa place, le Pharaon Néchao leur donna pour roi Eliacim, fils de Josias, et il changea son nom, et il l’appela Joacin. Et il emmena Joachaz en Égypte, où il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Joacin donna au Pharaon de l’argent et de l’or, mais il taxa la terre pour payer le tribut au Pharaon; chacun donna de l’argent et de l’or selon sa taxe; tout le peuple donna donc le tribut au Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Joacin avait vingt-cinq ans lorsqu’il monta sur le trône, et il régna onze ans à Jérusalem; sa mère se nommait Jeldaph, fille de Phadaël, de Rhumna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Et il fit le mal aux yeux du Seigneur comme avaient fait tous ses aïeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'En ce temps-là, Nabuchodonosor, roi de Babylone, vint, et Joacin lui fut asservi trois ans; ensuite il changea de pensée, et il refusa de lui obéir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Alors, le Seigneur envoya contre lui des bandes de la Chaldée, de la Syrie, de Moab et des fils d’Ammon; il les envoya en la terre de Juda pour prévaloir sur elle, selon la parole que le Seigneur avait dite par la voix de ses serviteurs les prophètes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'De plus, la colère du Seigneur contre Juda voulait l’expulser de devant sa face à cause des péchés de Manassé, et de tout ce qu’avait fait ce roi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Car il avait versé le sang innocent, il en avait rempli Jérusalem; et le Seigneur ne voulait point s’apaiser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Quant au reste de l’histoire de Joacin, n’est-il pas écrit au livre des Faits et gestes des rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Et Joacin s’endormit avec ses pères, et son fils Joachim, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Et le roi d’Égypte ne sortit plus de sa contrée, parce que, depuis le torrent d’Égypte jusqu’à l’Euphrate, le roi de Babylone avait pris tout ce qui appartenait à l’Égyptien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Joachim avait dix-huit ans quand il monta sur le trône, et il régna trois mois à Jérusalem; sa mère se nommait Nestha, fille d’Ellanastham, de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Et il fit le mal devant le Seigneur, comme avait fait son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'En ce temps-là, Nabuchodonosor, roi de Babylone, marcha sur Jérusalem, et la ville fut investie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Et Nabuchodonosor mit le siége devant la ville, et ses serviteurs la tinrent assiégée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Or, Joachim, roi de Juda, se rendit au roi de Babylone, lui, ses serviteurs, sa mère, ses chefs et ses eunuques; le roi de Babylone le fit captif en la huitième année de son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Et il enleva de Jérusalem tous les trésors du temple du Seigneur et tous les trésors du palais du roi; il brisa tous les vaisseaux d’or qu’avait faits, dans le temple, le roi Salomon, selon la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Et il emmena en captivité, au nombre de dix mille, tous les chefs, tous les hommes vaillants, et en outre tous les charpentiers et tous les maçons; il ne resta dans la terre que les indigents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Il transporta aussi à Babylone, Joachim, la mère du roi, les femmes du roi et ses eunuques; il conduisit tous les riches de la terre de Jérusalem à Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Et tous les hommes dans la force de l’âge au nombre de soixante-dix mille, et mille charpentiers ou maçons, tous faisant la guerre. Le roi Nabuchodonosor les emmena captifs à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Et il remplaça Joachim par Batthanias, fils de Josias, et il donna à ce roi le nom de Sédécias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sédécias avait vingt-neuf ans quand il monta sur le trône, et il régna onze ans à Jérusalem; le nom de sa mère était Amital, fille de Jérémie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Et il fit le mal devant le Seigneur, comme avait fait Joacin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Car, telle était la pensée du Seigneur contre Jérusalem et contre Juda, jusqu’à ce qu’il les eut expulsés de devant sa face. Or, Sédécias se révolta contre le roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Dans la neuvième année de son règne, le dixième mois, le roi Nabuchodonosor arriva de Babylone avec toute son armée contre Jérusalem; il campa autour de ses remparts, et il les enveloppa d’une muraille qu’il bâtit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Et la ville fut investie jusqu’au neuvième mois de la onzième année du règne de Sédécias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'La famine prévalait dans la cité, et il n’y avait pas de pains pour le peuple de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Une brèche fut faite aux murailles, et à la nuit les hommes de guerre sortirent par le chemin de la porte qui est entre les remparts, la porte même du jardin du roi; cependant, les Chaldéens entouraient le reste de la ville. Alors, le roi prit la route de la plaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Et l’armée des Chaldéens les poursuivit; Sédécias fut pris en Araboth-Jéricho, et toute sa troupe se dispersa tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Les Chaldéens firent donc le roi captif; ils le menèrent au roi de Babylone à Reblatha, et Nabuchodonosor prononça contre lui son arrêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Il égorgea tous ses fils sous ses yeux, qu’ensuite il arracha; puis, après l’avoir chargé de chaînes et d’entraves, il l’emmena à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Le septième jour du cinquième mois de la dixneuvième année du règne de Nabuchodonosor, Nabuzardan son général en chef, celui qui se tenait devant lui, marcha sur Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Et il livra aux flammes le temple du Seigneur, le palais du roi et toutes les maisons de Jérusalem; le géné~ ral en chef brûla tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'L’armée des Chaldéens rasa le rempart qui entourait la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Et Nabuzardan enleva tout ce qui survivait du peuple demeuré dans la ville, et ceux qui étaient tombés dans les mains du roi de Babylone, et tout le reste de la multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Il ne laissa pour être vignerons et laboureurs que la plus infime populace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Et les Chaldéens brisèrent les colonnes d’airain, les bassins et la mer d’airain du temple; et ils emportèrent le métal à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Ils prirent aussi les chaudières, les fourchettes, les coupes, les encensoirs et les vases d’airain employés dans dans le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Le général en chef prit les portes, les coupes d’or et d’argent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Les deux colonnes, la mer et les bassins que Salomon avait placés dans le temple; on ne sut pas le poids de tous les ornements d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Chaque colonne avait dix-huit coudées de haut; elle était surmontée d’un chapiteau d’airain, haut de trois coudées, avec un filet entouré de grenades; elles étaient toutes les deux pareilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Le général en chef fit aussi captifs Saraïas le grand prêtre, Sophonie prêtre du second rang, et les trois gardiens des portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'On prit en outre: hors de la ville, un eunuque commandant les hommes de guerre; dans la ville, cinq de ceux qui voyaient la face du roi, et le scribe du chef de l’armée qui rangeait les troupes en bataille, et soixante hommes de la campagne alors à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Nabuzardan conduisit les captifs au roi de Babylone, à Reblatha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Et Nabuchodonosor les frappa, et les fit mettre à mort à Reblatha dans la terre d’Emath; puis, il emmena Juda loin de sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Et à la tête du peuple qui resta sur le territoire de Juda, le roi mit Godolias, fils d’Achiman, fils de Saphan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Et tous les chefs de l’armée, eux et leurs hommes, apprirent que le roi avait choisi Godolias; alors, Ismaël, fils de Nathanie; Jonas, fils de Careth; Saraïas, fils de Thanamath le Nephthalite, et Jézonias, fils de Machathi, l’allèrent trouver avec leurs hommes à Maspha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Où Godolias prêta serment à eux et à leurs hommes, disant: Ne craignez plus d’invasion des Chaldéens, demeurez en votre terre, servez le roi de Babylone, et tout ira bien pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Et le septième mois, Ismaël, fils de Nathanie, de la race royale, et dix de ses hommes allèrent à Maspha; là, ils attaquèrent Godolias, et ils le tuèrent ainsi que les Chaldéens qui s’y trouvaient avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Et tout le peuple, du petit au grand, et les chefs de l’armée se levèrent, et ils s’en allèrent en Égypte, car ils craignaient les Chaldéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'En la trente-septième année de la captivité de Joachim, roi de Juda, le vingt-septième jour du douzième mois, Evilmerodach, roi de Babylone, dès la première année de son règne, releva la tête de Joachim, roi de Juda, et le fit sortir de prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Et il lui parla avec douceur, et il lui donna un trône plus élevé que les trônes des autres rois qui l’entouraient à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Il lui ôta ses vêtements de prisonnier, et il le fit manger, en sa présence, tous les jours de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Et sa portion, portion perpétuelle, lui fut donnée de la maison du roi; il en fut ainsi tous les jours de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Caïnan, Malalehel, Jared,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enoch, Mathusalem, Lamech, Noé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Fils de Noé: Sem, Cham, Japheth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Fils de Japheth: Gomer, Magog, Madaï, Javan, Elisa, Thobel, Mosoch et Thiras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Fils de Gomer: Ascenez, Rhiphath et Thorgama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Fils de Javan: Elisa, Tharsis, les Citians et les Rhodiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Fils de Cham: Chus, Mesraïm, Phuth et Chanaan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Fils de Chus: Saba, Evila, Sabatha, Regma et Sabathaca. Fils de Regma: Saba et Dadan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Et Chus engendra Nemrod; celui-ci commença à être puissant et chasseur sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, '(17) Fils de Sem: Elam, Assur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, '(24) Arphaxad, Salé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, '(25) Héber, Phaleg, Réhu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, '(26) Sarug, Nachor, Tharé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, '(27) Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, '(28) Fils d’Abraham: Isaac et Ismaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, '(29) Voici leurs familles: premier-né d’Ismaël: Nabaïoth, Cédar, Abdéel, Massan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, '(30) Masma, Duma, Massi, Choddan, Thêman,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, '(31) Jethur, Naphis, Cedma; voilà les fils d’Ismaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, '(32) Fils de Cettura, concubine d’Abraham: elle lui enfanta Zameran, Jezan, Madian, Madal, Jesboc et Sué. Fils de Jezan: Dedan et Saba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, '(33) Fils de Madian: Gephar, Aphir, Enoch, Abida et Elduga; voilà tous les fils de Cettura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, '(34) Abraham engendra Isaac. Fils d’Isaac: Jacob et Esaü.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, '(35) Fils d’Esaü: Eliphaz, Raguel, Jehul, Jeglon et Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, '(36) Fils d’Eliphaz: Thêman, Omar, Sophar, Gatham, Cenez, Thamna et Amalec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, '(37) Fils de Raguel: Nachoth, Zaré, Somé et Mozé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, '(38) Fils de Seïr: Lotan, Sobal, Sébégon, Ana, Dison, Asar et Rison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, '(39) Fils de Lotan Horri et Hêman; sœur de Lotan, Thamna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, '(40) Fils de Sobal: Alon, Machanath, Tébel, Sophi et Onan. Fils de Sébégon: Eth et Sonan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, '(41) Fils de Sonan: Dison. Fils de Dison: Emeron, Asebon, Jethram et Harran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, '(42) Fils d’Asar: Balaam, Zucam, Acan. Fils de Rison, Os et Aran.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, '(43) Et voici leurs rois: Balac, fils de Béor; le nom de sa ville est Dennaba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, '(44) Balac mourut, et Jobab, fils de Zara de Bosora, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, '(45) Jobab mourut, et Asom, de la terre des Thêmanites, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, '(46) Asom mourut, et Adad, fils de Barad, régna à sa place; ce fut lui qui vainquit Madian dans le champ de Moab; le nom de sa ville est Gethaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, '(47) Adad mourut, et Sebla (Samada) de Maseca régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, '(48) Sebla mourut, et Saul de Rooboth, sur l’Euphrate, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, '(49) Saul mourut, et Balaennor (Ballanan), fils d’Achobor, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, '(50) Balaennor mourut, et Arad, fils de Barad, régna à sa place; le nom de sa ville est Phogor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, '(51) Chefs d’Edom: le chef Thaman (Thamna), le chef Golada (Gola), le chef Jéther,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, '(52) Le chef Elibamas (Olibema), le chef Ela, le chef Phinon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, '(52) Le chef Cenez, le chef Thêman, le chef Bassor (Mazar),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, '(54) Le chef Magediel, le chef Zaphoïn voilà les chefs d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Voici les noms des fils d’Israël: Ruben, Siméon, Lévi, Juda, Issachar, Zabulon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph, Benjamin, Nephthali, Gad, Aser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Fils de Juda: Her, Onan, Sela; tous trois naquirent de la fille de Savas (Sué), la Chananéenne; et Her, le premier-né de Juda, fit le mal devant le Seigneur, qui le tua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Et Thamar, bru de Juda, enfanta Pharès et Zara; en tout cinq fils de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Fils de Pharès: Esron et Jemuhel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Fils de Zara Zambri, Etham, Aimuan, Calchal et Darad; en tout: cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Fils de Charmi: Achar, le perturbateur d’Israël, qui désobéit au sujet de l’anathème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Fils d’Etham: Azarias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Fils d’Esron, qui lui furent enfantés: Jeraméel, Aram et Caleb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Aram engendra Aminadab; Aminadab engendra Nahasson, chef de la maison de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahasson engendra Salmon; Salmon engendra Booz;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Booz engendra Obed; Obed engendra Jessé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Jessé engendra son premier-né Eliab, le second Aminadab, le troisième Samaa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nathanael le quatrième, Zabdé le cinquième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Azam le sixième, et David le septième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Et leurs sœurs furent Sarvia et Abigaïl. Les fils de Sarvia furent: Abessa, Joab et Asaël; trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abagaïl enfanta Amessab, et le père d’Amessab fut Jothor l’Ismaélite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Caleb, fils d’Esron, prit pour femmes Gazuba et Jerioth; voici ses fils: Jasar, Subab et Ardon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Et Gazuba mourut, et Caleb prit pour femme Ephratha, et elle lui enfanta Hur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur engendra Urias; Urias engendra Beseléel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Après cela, Esron eut commerce avec la fille de Machir, père de Galaad, et il la prit pour femme; il avait alors soixante-cinq ans, et elle lui enfanta Seruch.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Seruch engendra Jaïr; il possédait vingt-trois villes en Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Il prit de plus Gessur et Aram, villes de Jaïr, parmi les siennes, et la terre de Canath avec ses villes: soixante villes; toutes appartenaient aux fils de Machir, père de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Après la mort d’Esron, Caleb épousa Ephratha; or, Abia, femme d’Esron, lui avait enfanté Ascho, père de Thécoé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Les fils de Jeraméel, premier-né d’Esron, furent: Ram, premier-né; puis, Banaa, Aram et Asan, son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Et Jeraméel avait une autre femme qui se nommait Atara; celle-ci fut la mère d’Ozom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Les fils de Ram, premier-né de Jeraméel, furent: Maas, Jamin et Acor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Les fils d’Ozom furent: Samaï et Jadaé, et les fils de Samaï Nadab et Abisur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'La femme d’Abisur se nommait Abihaïl, et elle lui enfanta Achobor et Moël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Fils de Nadab: Salad et Aphaïn; Salad mourut sans enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Fils d’Aphaïn: Isémiel; fils d’Isémiel: Sosan; fils de Sosan: Dadaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Fils de Dadaï: Achisamas, Jéther, Jonatham; Jéther mourut sans enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Fils de Jonathan: Phaleth et Ozam; voilà les fils de Jonathan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sosan n’eut pas de fils, mais des filles; or, il avait un serviteur égyptien qui se nommait Johel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Et Sosan donna sa fille, pour femme, à son serviteur Johel; elle lui enfanta Ethi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Et Ethi engendra Nathan, et Nathan engendra Zabed.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabed engendra Aphamel, et Aphamel engendra Obed.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed engendra Jéhu, et Jéhu engendra Azarias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarias engendra Hellès, et Hellès engendra Eléaza.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eléaza engendra Sosomaï, et Sosomaï engendra Salum.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Salum engendra Jéhémie; Jéhémie engendra Elisama, et Elisama engendra Ismaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Fils de Caleb, frère de Jeraméel: Marisa, premierné; c’est le père de Siph; Marisa eut encore des fils, il fut le père d’Hébron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Fils d’Hébron: Coré, Thaphus, Rhicom et Samaa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Samaa engendra Rahem, père de Jéclan, et Jéclan engendra Samaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Mahon fut son fils, et Mahon fut le père de Bethsur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Gaïpha, concubine de Caleb, enfanta Aram, et Mosa et Gézué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Fils d’Adaï Ragem, Joatham, Sagar, Phalec, Gaïpha et Sagaé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Mocha, concubine de Caleb, enfanta Saber et Tharam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Sagaé engendra le père de Madmena, et Sahu, père de Mahabena, et le père de Gébal; la fille de Caleb s’appelait Ascha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Voilà les fils de Caleb. Voici les fils d’Hur, premierné d’Ephratha: Sobal, père de Cariathiarini,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salomon, père de Bétha, Lammon, père de Béthalaem, et Arim, père de Bethgedor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Fils de Sobal, père de Cariathiarim: Araa, Aïsi, Ammanith');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Et Umasphaé; villes de Jaïr: Ethalim, Miphitim, Hésamathim et Hémasaraïm, d’où sont sortis les Sarathéens et les fils d’Esthaam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Fils de Salomon: Béthalaem le Netophatite, Ataroth de la maison de Joab, la moitié de Malathi, et Ésari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Familles de lettrés, demeurant en Jabis: Thargathiim, et Samathiim et Sohathim. Ce sont les Cinéens, issus d’Emath, père de la maison de Rhéchab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Voici les fils de David qui lui naquirent à Hébron; le premier-né fut: Amnon, fils de la Jezraélite Achinaam; le second, Damniel (Daluia), fils d’Abigaïl du Carmel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Le troisième, Absalon, fils dé Moha (Maacha), fille de Tholmé, roi de Gedsur; le quatrième, Adonias (Ornia), fils d’Aggith;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Le cinquième, Saphatia, fils d’Abital; le sixième, Jethram, fils de sa femme Agla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Il en eut six à Hébron, et il y régna sept ans et demi; après quoi, il régna trente-trois ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Voici ceux qui lui naquirent en Jérusalem: Samaa, Sobab, Nathan et Salomon. Quatre fils de Bethsabée, fille d’Amiel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Puis, Ebaar, Elisa, Eliphaleth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nagé, Naphec, Japhie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eliada et Eliphala; en tout: neuf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Tous fils de David, outre les fils de ses concubines, et Thamar, leur sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Fils de Salomon: Roboam, Abias son fils, Asa son fils, Josaphat son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Joram son fils, Ochozias son fils, Joas son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Amasias son fils, Azarias son fils, Joathan son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Achaz son fils, Ezéchias son fils, Manassé son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Amon son fils, Josias son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Fils de Josias: Joanan le premier-né, Joacin le second, Sédécias le troisième, et Salum le quatrième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Fils de Joacin: Jéchonias son fils, Sédécias son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Fils de Jéchonias: Asir, Salathiel son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Melchiram, Phadaïas, Fanesar, Jécimie, Hosamath et Nabadias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Fils de Phadaïas: Zorobabel et Sémeï. Fils de Zorobabel: Mosollam et Ananias; Salometh fut leur sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Il eut encore: Asubé, Ool, Barachie, Asadie et Asobed; cinq fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Fils d’Ananias: Phalettie, Jésias son fils, Raphal son fils, Orna son fils, Abdias son fils, et Séchénias son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Fils de Sechénias: Samaïe. Fils de Samaïe: Hattus, Johel, Berri, Noadie et Saphat; six issus de Sechénias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Fils de Noadie Elithenan, Ezécie, Ezricam; trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Fils d’Elithenan: Odolie, Eliasebon, Phadaïe, Acub, Joanan, Dalaaïe et Anan; sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'De Juda sont issus: Pharès, Esron, Charmi, Hur, Sobal,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Et Rhada son fils. Et Sobal engendra Jeth, et Jeth engendra Achimaï et Laad; les Arathites (Sarathéens) sont issus d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Voici les fils d’Etham: Jezraël, Jesman et Jebdas; le nom de leur sœur était Eselebbon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Et Phanuel fut le père de Gedor, et Jazer le père d’Osan. Voilà les fils de Hur, du premier-né d’Ephratha, père de Béthalaem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Et Assur, père de Thécoé, eut deux femmes: Aoda et Thoada.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Et Aoda lui enfanta Ohaïe, Ephal, Thêman et Aasther; voilà tous les fils d’Aoda..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Fils de Thoada: Sereth, Saar et Esthanam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Et Coé engendra Enob et Sabatha; le frère de Rhéchab, fils d’Iarin, est issu de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Et Igabès fut plus illustre que ses frères, et sa mère lui donna le nom d’Igabès, disant: J’ai enfanté comme Gabès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Et Igabès invoqua le Dieu d’Israël, disant: Qu’il vous plaise de me bénir, et de me bénir, et de dilater mes limites; puisse votre main être avec moi; puissiez-vous faire connaître que vous ne m’abaisserez point. Et Dieu lui accorda tout ce qu’il avait demandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Et Caleb, père d’Ascha, engendra Machir; celui-ci, père d’Assathon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Engendra Bathraïas, Bessée et Thêman, père de la ville de Naas, frère d’Eselom, fils de Cenez; ce sont les hommes de Rhéchab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Et les fils de Cenez furent: Gothoniel et Saraïa; et Gothoniel eut pour fils Athath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Et Manathi engendra Gophera, et Saraïa engendra Jobab, père d’Ageaddaïr; car ils étaient tous artisans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Fils de Caleb, fils de Jéphoné: Her, Ada et Noom; Ada fut le père de Cenez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Fils d’Alehel: Zib, Zépha, Thiria et Eserel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Fils d’Esri: Jéther, Morad, Apher et Jamon; Jéther engendra Maron, Sémeï et Jesba, père d’Esthemon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Et sa femme Adia enfanta Jared, père de Gedor, et Aber, père de Sochon, et Hatiel, père de Zamon. Et Morad épousa Betthia, fille du Pharaon, et il en eut des fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Et Iduée, sœur de Nachaïm, père de Ceïla, fut mère de Garmi, et d’Esthemon le Nohathite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Fils de Semon: Amnon, Ana, fils de sa femme Phana, et Inon. Fils de Seï: Zoan, et les fils qu’il eut de Zoab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Fils de Sela, fils de Juda: Her, père de Léchab, et Laada, père de Marisa; les habitants d’Ephrathabac, qui appartient à la maison d’Esoba, sont issus d’eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Et Joacin, et les hommes de Hozeba, et Joas, et Saraph: ceux-ci demeurèrent en Moab, et Dieu les en ramena; Abederin, Athouciim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'C’étaient les potiers qui, avec le roi, habitaient Ataïm et Gadira; ils s’étaient enrichis dans ce royaume, et ils s’y étaient fixés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Fils de Siméon: Namuel, Jamin, Jarib, Zarès et Saül,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Salem son fils, Mabasam son fils, Masma son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Amuel son fils, Sabud son fils, Zacchur son fils, Sémeï son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Sémeï eut seize fils et six filles, et ses frères n’eurent pas beaucoup d’enfants. Et leurs familles ne se multiplièrent point comme les fils de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Et ils habitaient en Bersabée, en Molada, en Esersual,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'En Balaa, en Esem et en Tholad,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'En Bathuel, en Herma et en Sicelag (Sécelac),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'En Bethmarimoth, en Hemisuséosin et en la maison de Baruséorim; telles furent leurs villes jusqu’au roi David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Et leurs villages étaient: Etan, et Hin, et Rhemnon, et Thocca, et Esar; cinq villages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Et tous leurs villages étaient autour des villes jusqu’à Baal: tel était leur domaine, et telle était sa distribution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Et Mosobab, et Jémoloch, et Josias, fils d’Amasias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Et Johel, et Jéhu, fils d’Asabias, fils de Saraus fils d’Asiel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Et Elionaï, et Jocaba, et Jasuïe, et Asaïe, et Jediel, et Ismaël, et Bananias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Et Zuza, fils de Saphaï, fils d’Alon, fils de Jedia, fils de Semri, fils de Samaïe,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Furent ceux qui eurent le nom de chefs en leurs familles, et qui, en leurs maisons paternelles, se multiplièrent jusqu’à la multitude;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Et ils partirent, et ils allèrent jusqu’à Gérara, à l’orient d’Haï, chercher des pâturages pour leurs troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Et ils en trouvèrent d’excellents en abondance; et la contrée devant eux était vaste, et le calme et la paix y régnaient; car auparavant quelques fils de Cham seulement s’y étaient établis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Or, ceux dont les noms sont écrits ci-dessus, entrèrent chez eux au temps d’Ezéchias, roi de Juda; ils ruinèrent leurs demeures, ainsi que les Mineïens qu’ils y avaient trouvés, et ils les détruisirent entièrement, comme on le voit encore, et ils demeurèrent à leur place dans cette contrée, parce qu’il y avait des pâturages pour leur bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Et cinq cents hommes de ces fils de Siméon avec leurs chefs Phalaetti, Noadie, Raphaïe et Oziel, fils de Jési, se transportèrent en la montagne de Seïr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Et ils exterminèrent les restes d’Amalec, qui ne s’en sont jamais relevés jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Voici les fils de Ruben; il était le premier-né; mais parce qu’il s’était introduit dans la couche de son père, Jacob ayant donné sa bénédiction à son fils Joseph, le droit d’aînesse de Ruben ne lui était plus compté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Car Juda était fort parmi ses frères; le chef est sorti de lui, la bénédiction est restée à Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Fils de Ruben, premier-né d’Israël: Enoch, Phallus, Asron et Charmi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Fils de Johel: Sémeï et Banaïas son fils. Fils de Gug, fils de Sémeï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Micha, son fils Recha, son fils Johel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Son fils Behel, qu’emmena Thelgath-Phalnasar, roi des Assyriens; il était le chef des Rubénites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Et, avec lui, furent emmenés ses frères, selon le dénombrement qui en fut fait par familles; les chefs de ces familles étaient: Johel, Zacharie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Et Balec, fils d’Azuz, fils de Sama, fils de Johel. Balec demeurait en Aroer, et vers Nebo et Belmasson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Et il s’était étendu à l’orient jusqu’au désert, du côté de l’Euphrate, parce qu’il avait de nombreux troupeaux en la terre de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Et, sous le règne de Saül, ils furent en guerre avec leurs voisins, et ceux qui habitaient sous des tentes tombèrent entre leurs mains, et ils maîtrisèrent toute la contrée à l’orient de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Les fils de Gad, en face, demeurèrent en la terre de Basan jusqu’à Sela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Le premier-né fut Johel; le second Saphan; puis, venaient Jania, le scribe de Basan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Et ses frères, par familles paternelles: Michel, Mosollam, Sébée, Joré, Joachan, Zué et Obed; sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Les fils d’Abihaïl, fils d’Uri, fils d’Isaïe, fils de Galaad, fils de Michel, fils de Jésé, fils de Jeddé, fils de Baz,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Frère du fils d’Abdiel, fils de Guni, chef de la maison paternelle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Habitaient en Galaad, en Basan, en leurs bourgs et en tout le territoire de Saron jusqu’à ses limites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Leur dénombrement fut fait du temps de Joatham, roi de Juda, et de Jéroboam, roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Les fils de Ruben, Gad et la demi-tribu de Manassé comptaient quarante-quatre mille sept cent soixante hommes, dans la force de l’âge, portant glaive et bouclier, tendant l’arc, exercés à la guerre, propres à marcher au combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Et ils furent en guerre avec les Agaréens, les Ituréens, les Naphiséens et les Nadabéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Et ils l’emportèrent sur eux. Et les Agaréens, avec toutes leurs tentes, tombèrent entre leurs mains, parce que les vainqueurs avaient invoqué Dieu pendant la bataille; et Dieu les exauça, parce qu’ils avaient espéré en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Et ils prirent tout ce que les autres possédaient: cinquante mille chameaux, deux cent cinquante mille brebis, deux mille ânes; et la vie de cent mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Car une grande multitude de blessés succomba, parce que cette guerre s’était faite selon la volonté de Dieu, et les vainqueurs habitèrent le territoire des vaincus jusqu’à la captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Et la demi-tribu de Manassé s’étendit de Basan à Baal, Hermon, Sanir et la montagne d’Hermon; ses fils se multiplièrent dans le Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Et voici leurs chefs, par familles: Opher, Seï, Eliel, Jérémie, Oduïa et Jediel; hommes riches et renommés, chefs des familles de la demi-tribu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Et ils répudièrent le Dieu de leurs pères, et ils se prostituèrent à la suite des dieux de la terre que le Seigneur avait effacés devant leur face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Et le Dieu d’Israël excita l’esprit de Phaloch (Phul), roi d’Assur, et l’esprit de Thelgath-Phalnasar, roi d’Assur. Ce roi enleva Ruben, et Gad, et la demi-tribu de Manassé, et il les transporta en Haach, en Habor, et sur le fleuve Gozan, où ils sont restés jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Fils de Lévi: Gerson, Caath et Mérari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Fils de Caath: Amram et Isaar, Hébron et Oziel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Enfants d’Amram: Aaron, Moïse et Marie. Fils d’Aaron Nadab et Abiud, Eléazar et Ithamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eléazar engendra Phinéès, et Phinéès engendra Abisué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisué engendra Bocci, et Bocci engendra Ozi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Ozi engendra Zaraïas, et Zaraïas engendra Mariel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Mariel engendra Amarias, et Amarias engendra Achitob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Achitob engendra Sadoc, et Sadoc engendra Achimaas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Achimaas engendra Azarias, et Azarias engendra Johanan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Johanan engendra Azarias; ce fut lui qui exerça le sacerdoce dans le temple que Salomon bâtit à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azarias engendra Amarias, et Amarias engendra Achitob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Achitob engendra Sadoc, et Sadoc engendra Salom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Salom engendra Helcias, et Helcias engendra Azarias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azarias engendra Saraïas, et Saraïas engendr Josadac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Josadac fut enlevé, avec Juda et Jérusalem, par Nabuchodonosor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Fils de Lévi: Gerson, Caath et Mérari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Fils de Gerson: Lobeni et Sémeï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Fils de Caath: Amram et Isaar, Hébron et Oziel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Fils de Mérari: Mooli et Musi; voici les familles de Lévi, désignées par les noms de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'A Gerson et Lobeni son fils succèdent Jeth fils de ce dernier, Zamath son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Joab son fils, Addi son fils, Zara son fils, Jethri son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'De Caath descendent: Aminadab son fils, Coré son fils, Aser son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Elcana son fils, Abisaph son fils, Aser son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Thaat son fils, Uriel son fils, Saül son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'D’Elcana descendent encore: Amessi et Achimoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elcana son fils, Saphi son fils, Cénaath son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Eliab son fils, Jéroboam son fils, Elcana son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Fils de Samuel: Sari, premier-né, et Abias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Fils de Mérari: Mooli son fils, Lobeni son fils, Sémeï son fils, Oza son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Samaa son fils, Aggia son fils, Asaïas son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Et voici ceux que David institua chefs des chœurs du tabernacle, lorsqu’il eut transféré l’arche à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Et ils s’accompagnaient avec des instruments, devant le tabernacle du témoignage, jusqu’à ce que Salomon eût bâti le temple du Seigneur à Jérusalem. Et ils servaient, chacun selon la fonction qui lui était assignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Voici leurs noms et ceux de leurs pères de Caath descendait: Hêman, chantre et harpiste, fils de Johel, fils de Samuel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Fils d’Elcana, fils de Jéroboam, fils d’Eliel, fils de Thoü,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Fils de Suph, fils d’Elcana, fils de Maath, fils d’Amathi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Fils d’Elcana, fils de Johel, fils d’Azarias, fils de Saphanie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Fils de Thaath, fils d’Aser, fils d’Abiasaph, fils de Coré,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Fils d’Isaar, fils de Caath, fils de Lévi, fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Et Asaph, chantre comme lui, qui se tenait à sa droite, était fils de Barachias, fils de Samaa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Fils de Michel, fils de Baasie, fils de Melchias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Fils d’Athani, fils de Zaaraï, fils d’Adaï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Fils d’Etham, fils de Zammam, fils de Sémeï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Fils de Jeth, petit-fils de Gerson, fils de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Et de Mérari descendaient les chantres qui se tenaient à gauche, dont le chef était: Ethan, fils de Cisa, fils d’Abaï, fils de Maloch,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Fils d’Asebi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Fils d’Amessias, fils de Bani, fils de Semer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Fils de Mooli, fils de Musi, fils de Mérari, fils de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Et les lévites leurs frères, selon leurs familles paternelles, étaient attachés aux divers services du tabernacle de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Aaron, et, après lui, ses fils sacrifiaient sur l’autel des holocaustes et sur l’autel des parfums; ils remplissaient toutes les fonctions relatives au Saint des saints; et ils priaient pour Israël, conformément à ce que leur avait commandé Moïse serviteur de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Voici les fils d’Aaron: Eléazar son fils, Phinéès son fils, Abisué son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Bocci son fils, Ozi son fils, Saraïa son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Mariel son fils, Amarias son fils, Achitob son fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Sadoc son fils, Achimaas son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Voici les demeures, les bourgs et les territoires, assignés par le sort, selon leurs familles, aux fils d’Aaron, et aux fils de Caath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Il leur fut donné Hébron, en la terre de Juda, et sa banlieue tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Mais les champs de la ville et ses bourgs appartenaient à Caleb, fils de Jéphoné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Les villes de refuge furent aussi concédées aux fils d’Aaron, savoir: Hébron, Lobna et sa banlieue, Selna et sa banlieue, Esthamo et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Jethar et sa banlieue, Dabir et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asan et sa banlieue, Bethsamys et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Et, dans la tribu de Benjamin, Gabée et sa banlieue, Galemath et sa banlieue, Anathoth et sa banlieue. En tout treize villes par familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Et le sort assigna au reste des fils de Caath, par familles, dix villes de la demi-tribu de Manassé, en deçà du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Et aux fils de Gerson, par familles, treize villes des tribus d’Issachar, d’Aser, de Nephthali et de la demitribu de Manassé en Basan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Et aux fils de Mérari, par familles, douze villes des tribus de Ruben, de Gad et de Zabulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Et les fils d’Israël accordèrent aux lévites ces villes et leurs banlieues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Le sort désigna dans les tribus de Juda, de Siméon et de Benjamin, les villes auxquelles les lévites donnèrent leurs noms,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'D’après les familles des fils de Caath. Et ils eurent aussi des villes du territoire d’Ephraïm,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Y compris les villes de refuge: Sichem et sa banlieue, dans la montagne d’Ephraïm, Gazer et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jecmaan et sa banlieue, Béthoron et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Et, en d’autres territoires, Aïlon et sa banlieue, Gethremmon et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Et de la demi-tribu de Manassé: Anar et sa banlieue, Jemblaan et sa banlieue, selon les familles du reste des fils de Caath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Les fils de Gerson, par familles, eurent dans l’autre demi-tribu de Manassé, Golan en Basan et sa banlieue, Aseroth et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'Et dans la tribu d’Issachar: Cédés (Cadès) et sa banlieue, Deberi et sa banlieue, Dabor et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramoth, Aïnan et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Et dans la tribu d’Aser: Maasal et sa banlieue, Abdon et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Acac et sa banlieue, Rhoob et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Et dans la tribu de Nephthali: Cédés (Cadès) en Galilée et sa banlieue, Hamoth et sa banlieue, Cariathaïm et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Et dans la tribu de Zabulon le sort attribua au reste des fils de Mérari, Remmon et sa banlieue, Thabor et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'Et dans la vallée du Jourdain à l’occident du fleuve: Jéricho, et dans la tribu de Ruben: Bosor dans le désert et sa banlieue, Jasa et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Cadmoth et sa banlieue, Maephla et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Dans la tribu de Gad: Ramoth-Galaad et sa banlieue, Maanaïm et sa banlieue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Esébon et sa banlieue, Jazer et sa banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Quant aux fils d’Issachar, ils étaient quatre: Thola, Phua, Jasub et Sémeron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Fils de Thola: Ozi, Raphaïas, Jeriel, Jamaï, Jémasan et Samuel, chefs des familles issues de Thola; dont le nombre, au temps de David, fut de vingt-deux mille six cents hommes, tous nés forts et vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Fils d’Ozi: Jezraïe; fils de Jezraïe: Michel, Abdiu, Johel et Jésia; en tout cinq chefs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Et avec eux, il y eut dans leurs familles paternelles des hommes nés forts et vaillants, au nombre de trentesix mille en état de porter les armes; car ils avaient eu beaucoup de femmes et beaucoup d’enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Et leurs frères dans toutes les familles d’Issachar, hommes forts et vaillants aussi, étaient quatre-vingt-sept mille; tel fut leur nombre total.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Fils de Benjamin: Balé, Bachir et Jediel; trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Fils de Balé: Esebon, Ozi, Oziel, Jerimuth et Uri; cinq. Chefs des familles issues de Balé, au nombre de vingtdeux mille trente-quatre hommes forts et vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Fils de Bachir: Zémira, Joas, Eliézer, Elithénan, Amarias, Jerimuth, Abiud, Anathoth et Eliémeth; voilà tous les fils de Bachir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Et le nombre des familles dont, selon leur naissance, ils furent les premiers chefs, s’éleva jusqu’à vingt. mille deux cents hommes forts et vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Fils de Jediel: Balaan, fils de Balaan; Jaüs, Benjamin, Aoth, Chanana, Zêthan, Tharsi et Achisaar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Voilà tous les fils de Jediel, vaillants chefs de familles, dont le nombre fut de dix-sept mille deux cents hommes forts et vaillants, en état de porter les armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Saphin et Aphin étaient fils de Hor, et Hasom était fils d’Aor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Fils de Nephthali: Jasiel, Goni et Aser, Sellom, fils de ce dernier, et Balam son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Fils de Manassé: Esriel, qu’enfanta sa concubine la Syrienne, qui lui enfanta aussi Machir, père de Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Et Machir maria Aphin et Saphin; sa sœur s’appelait Moocha, et le nom du second fils fut Saphaad; or, Saphaad n’eut que des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Et Moocha, femme de Machir, enfanta un fils, et elle le nomma Pharès, et il eut un frère nommé Suros, le même que Galaad, et ses deux fils furent Ulam et Rocom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Fils d’Ulam: Badam; voilà les fils de Galaad, fils de Machir, fils de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Et sa sœur Malécheth enfanta Isud, Abiézer et Maëla;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Et Semira eut pour fils Aïm, Sichem, Lacim et Anian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Fils d’Ephraïm: Sothalath, Barad, Thaath, Elada, Saath,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Zabad, Sothelé, Azer et Eléad. Et des hommes de Geth les tuèrent tous, parce qu’ils s’étaient mis en campagne pour enlever leurs troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Et leur père Ephraïm s’affligea longtemps, et ses frères vinrent le consoler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Et il s’approcha de sa femme, et elle conçut, et elle eut un fils, et il le nomma Beria, parce que, dit-il, il est venu en ma maison dans notre malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Et sa fille s’appelait Saraa, et elle fut de ceux qui survécurent, et elle bâtit Béthoron-la-Haute et Béthoronla-Basse. Fils d’Ozan: Seïra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Et Raphé son fils, Saraph et Thaléès ses fils, et Thaen son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'A Laadan, son fils, naquit Amiud, père d’Elisamaï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Père de Nun, père de Josué; tels furent ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Et leur demeure était Béthel et ses bourgs, et Noaran à l’est, et à l’occident Gazer et ses bourgs. Et Sichem et ses bourgs, jusqu’à Gazar et ses bourgs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Et jusqu’aux confins des fils de Manassé, Bethsan et ses bourgs, Thanach et ses bourgs, Mageddo et ses bourgs, Dor et ses bourgs. C’est là qu’étaient établis les fils de Joseph, fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Enfants d’Aser: Jemna, Suïa, Isuï, Beria et Soré, sa sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Fils de Beria: Haber, Melchiel; ce dernier père de Berthaïth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Et Haber engendra Japhlet, Samer, Hothan et Sola, leur sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Fils de Japhlet: Phasec, Bamahel et Asith; voilà les fils de Japhlet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Fils de Samer: Achi, Rooga, Joba et Aram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Fils de son frère Banehelam (Hothan): Sopha, Imana, Sellès et Amal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Fils de Sopha Sué, Arnaphar, Suda, Barin, Imran,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Basan, Oa, Sama, Salisa, Jethra et Bééra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Fils de Jéther: Jephina, Phaspha et Ara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Fils d’Ola: Orech, Aniel et Rasia;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Tels furent les fils d’Aser, tous chefs de familles, dont le nombre fut de vingt-six mille hommes d’élite, forts et vaillants, en état de porter les armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Et Benjamin engendra Balé son premier-né, Asbel le second, Aara le troisième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noa le quatrième, Rapha le cinquième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Et les fils de Balé furent: Adir, Gera, Abiud,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abessué, Noama, Achias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephupham et Uram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Voici les fils d’Aod qui furent chefs des familles établies à Gabaa, et transportées ensuite à Machanathi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Nooma, Achias et Gera, le même que Jeglaam, qui engendra Aza et Jachicho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Et Saarin engendra dans les champs de Moab, après qu’il eut répudié Osin et Baada, ses femmes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Et il eut de sa femme Ada: Jolad, Sebia, Misa, Melchas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jébus, Zabia et Marma; tous chefs de familles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Et il avait eu d’Osin: Abitol et Alphaal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Fils d’Alphaal: Obed, Misaal, Somer (celui-ci bâtit Ona, et Aod et ses bourgs),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Et Beria et Sama (ceux-ci furent chefs des familles qui demeurèrent en Aïlam, et qui chassèrent les habitants de Geth),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Et ses frères furent Sosec, Arimoth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zabadie, Ored, Eder,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michel, Jespha et Joda, fils de Beria,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Et Zabadie, Mosollam, Azaci, Abar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Isamari, Jexlias et Jobab, fils d’Elphaal,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Et Jacim, Zachri, Zabdi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elionaï, Salathi, Elihéli,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaïe, Baraïe et Samarath, fils de Samaïth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Et Jesphan, Obed, Elihel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zechri, Anan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Ananie, Ambri, Aïlam, Anathoth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jathir, Jephudias et Phanuel, fils de Sosec,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Et Samsari, Saarias, Gotholie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jarasie, Erie et Zéchri, fils de Iroam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Voilà les chefs de famille selon leur naissance, et ils habitèrent Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Et en Gabaon demeura le père de Gabaon, sa femme se nommait Moacha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Et son fils premier-né Abdon; puis, venaient Sur, Cis, Baal, Nadab, Ner,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedur et son frère, Zachur et Maceloth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Et Maceloth engendra Samaa; et ceux-ci, vis-à-vis leurs frères, habitèrent Jérusalem avec leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Et Ner engendra Cis, et Cis engendra Saül, et Saül engendra Jonathas, Melchisué, Aminadab et Asabal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Et Jonathas engendra Meribaal, et Meribaal engendra Micha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Fils de Micha: Phithon, Melach, Tharach et Achaz.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Et Achaz engendra Jada, et Jada engendra Salémath, Asmoth et Zambri, et Zambri engendra Mesa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Et Mesa engendra Baana. Raphaïa fut son fils, Elasa son fils, Esel son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Et Esel eut six fils; voici leurs noms: Ezricam son premier-né; puis, Ismaïl, Saraïa, Abdias, Anan et Asa, tous fils d’Esel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Fils d’Asel, son frère: Aïlam le premier-né, Jas le second, et Eliphalet le troisième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Et les fils d’Aïlam étaient des hommes forts et vaillants, et ils tendaient l’arc, et leurs fils et les fils de leurs fils se multiplièrent jusqu’à cent cinquante. Tous étaient issus de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Voilà tout Israël et son dénombrement, et ceux qui furent inscrits au livre des Rois d’Israël et de Juda, après qu’ils eurent été transportés à Babylone à cause de tous leurs péchés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Et ceux qui les premiers revinrent en leurs possessions et dans les villes d’Israël, prêtres, lévites et autres à qui cela fut permis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Jérusalem fut repeuplée par des fils de Juda, des fils de Benjamin, des fils d’Ephraïm et des fils de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Il y eut parmi eux: Nothi, fils de Samiud, fils d’Amri, fils d’Ambraïm, fils de Buni, issus des fils de Pharès, fils de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Et de la famille de Seloni: Asaïe premier-né, et ses fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Issus de Zara; puis, Jehel et leurs frères au nombre de six cent quatre-vingt-dix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Et des fils de Benjamin: Salom, fils de Mosollam, fils d’Oduïa, fils d’Asinu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Et Jemnaa, fils de Jéroboam et Elo (ceux-ci étaient issus d’Ozi, fils de Machir), et Mosollam, fils de Saphatia, fils de Raguel, fils de Jemnaï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Et leurs frères, selon leur naissance, au nombre de neuf cent cinquante-six, tous chefs de familles dans leur tribu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Et parmi les prêtres: Jodaé, et Joarim, et Jachin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Et Azarias, fils d’Helcias, fils de Mosollam, fils de Sadoc, fils de Maraïoth, fils d’Achitob, grand prêtre du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Et Adaïe, fils d’Iraam, fils de Phaschor, fils de Melchia, et Maasaïa, fils d’Adiel, fils d’Ezira, fils de Mosollam, fils de Maselmoth, fils d’Emmer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Et leurs frères, chefs de familles dans leur tribu, au nombre de dix-sept cent soixante, hommes vaillants et forts employés au temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Et des lévites: Samaïe, fils d’Asob, fils d’Ezricam, fils d’Asabia, des fils de Mérari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Et Bacbacar, Arès, Galaal et Matthanias, fils de Micha, fils de Zéchri, fils d’Asaph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Et Abdias, fils de Samias, fils de Galaal, fils d’Idithun, et Barachie, fils d’Ossa, fils d’Elcana, qui demeurait dans les bourgs de Notephati.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Les portiers étaient: Salom, Acum, Telmon et Diman, et ses frères; Salom était leur chef.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Et jusqu’à ce jour, le chef est attaché à la porte royale du côté de l’orient; les portes sont les mêmes que celles des camps des fils de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Or, Sellum était fils de Coré, fils d’Abiasaph, fils de Coré, et ses frères les Coréites, entre autres services dans le temple, gardaient le tabernacle; et leurs pères dans les camps du Seigneur en avaient gardé l’entrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Et Phinéès, fils d’Eléazar, avait été leur chef devant le Seigneur, et après lui ceux-ci-dessus nommés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacharie, fils de Mosollam, gardait la porte du tabernacle du témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Tous ceux qu’on avait choisis pour garder les portes du temple étaient au nombre de deux cent douze; ils étaient dénombrés selon leurs résidences; David et Samuel le voyant les avaient institués, s’en remettant à leur foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Et eux et leurs fils gardaient les portes du temple, et, dans le temple, le tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Les portes regardaient les quatre vents du côté de l’orient, de la mer, de Borée et de Notos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Et leurs frères demeuraient dans leurs résidences, et en partaient pour qu’ils fussent relevés de sept en sept jours, à partir du jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'A quatre chefs étaient confiés les gardiens des portes, et les lévites veillaient à ce quel nul ne s’introduisît furtivement dans les chambres, ni dans le trésor du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Car la garde leur en était remise, et ils en avaient les clefs, et chaque matin dès l’aurore ils ouvraient les portes du lieu saint;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Et quelques-uns des leurs étaient chargés du service des vases, qu’on ne déplaçait pas sans qu’ils les eussent comptés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Et d’autres avaient la surveillance des provisions destinées aux choses saintes: de la fleur de farine, du vin, de l’huile, de l’encens, des aromates.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Et ceux qui préparaient les parfums et les aromates étaient pris parmi les fils des prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Et Matthathias, issu de Lévi, fils premier-né de Salom le Coréite, avait la surveillance de tout ce qui se préparait après les sacrifices dans la poêle à frire du grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Et Banaïas, issu de ses frères, de la maison de Caath, était chargé des pains de proposition que l’on consacrait de sabbat en sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Et les chefs des chantres-harpistes, de la famille des lévites, étaient désignés chaque jour, car jour et nuit ils étaient employés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Et les chefs distribués par familles demeuraient à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Or, Jehel avait habité Gabaon, qu’il avait fondée; et sa femme se nommait Moocha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Noms de ses fils: Abdon, premier-né; puis, Sur, Cis, Baal, Ner et Nadab,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedur et son frère, et Zachur et Maceloth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Et Maceloth engendra Samaa, et ceux-ci demeurèrent à Jérusalem au milieu de leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Et Ner engendra Cis, et Cis engendra Saül, et Saül engendra Jonathas, et Melchisué, et Aminadab et Asabal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Et Jonathas engendra Meribaal, et Meribaal engendra Micha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Fils de Micha: Phithon, Malach et Tharach.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Et Achaz engendra Juda, et Juda engendra Galemeth, Gazmoth et Zambri, et Zambri engendra Massa;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Et Massa engendra Baana, et Raphaïe son fils, et Elasa son fils, et Esel son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Et Esel eut six fils, et voici leurs noms: Ezricam, le premier-né; puis, Ismaël, Saraïa, Abdias, Anan et Asa; voilà les fils d’Esel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Et les Philistins livrèrent bataille à Israël, et les hommes d’Israël prirent la fuite devant eux, et ils furent taillés en pièces dans la montagne de Gelboé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Et les Philistins poursuivirent Saül et ses fils; ils tuèrent Jonathas, Aminadab et Melchisué, fils de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Et le poids de la bataille tomba sur Saül; les archers le trouvèrent, et ils dirigèrent leurs flèches et tous leurs efforts contre lui, et ils le percèrent de traits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Saül dit alors au serviteur qui portait ses armes: Tire ton épée et perce-moi, de peur que ces incirconcis ne m’approchent et ne m’outragent. Le serviteur qui portait ses armes ne le voulut pas, car il avait grande crainte. Mais Saül prit l’épée et se jeta sur la pointe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Et le serviteur qui portait ses armes vit que Saül était mort; lui-même se jeta sur son épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Et Saül et ses trois fils avaient succombé en cette bataille, et toute sa maison ensemble avait péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Et du vallon où s’était réfugié Israël, chacun vit que Saül et ses fils étaient morts, et ils s’enfuirent tous, abandonnant leurs villes. Les Philistins survinrent, et ils prirent possession de leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Le lendemain, ils sortirent pour dépouiller les morts, et ils trouvèrent Saül et ses fils gisant dans les montagnes de Gelboé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Et ils ôtèrent ses vêtements, prirent sa tête et ses armes, et les envoyèrent alentour en la terre des Philistins, pour annoncer ces nouvelles à leurs idoles et au peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Et ils déposèrent les armes dans le temple de leur dieu, et sa tête dans le temple de Dagon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Et les habitants de Galaad apprirent comment les Philistins avaient traité Saül et Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Et tous les hommes vaillants de Galaad se levèrent, enlevèrent le corps de Saül, et les corps de ses fils, les transportèrent à Jabès, et ensevelirent leurs ossements sous le chêne de Jabès, et ils jeûnèrent sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Ainsi mourut Saül, à cause des péchés commis par lui contre Dieu et contre les paroles du Seigneur qu’il n’avait point gardées; car il avait consulté une sorcière, et Samuel le prophète lui avait répondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Ensuite, tout Israël alla trouver David à Hébron, disant: Vois, nous sommes tes os et ta chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Précédemment, quand Saül régnait encore, c’est toi qui conduisais et ramenais Israël, et le Seigneur notre Dieu avait dit: Tu seras le pasteur d’Israël, tu seras le chef de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Et tous les anciens d’Israël allèrent en Hébron auprès du roi, et David fit alliance avec eux devant le Seigneur, en Hébron, et ils le sacrèrent roi d’Israël, selon la parole du Seigneur transmise par Samuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Et le roi et ses hommes partirent pour Jérusalem, la même que Jébus; les Jébuséens habitaient cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Et ils dirent à David: Tu n’entreras pas ici. Et il prit la forteresse de Sion, la même que la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Or, David avait dit: Celui qui, le premier, frappera le Jébuséen, sera général de mon armée; et Joab, fils de Sarvia, monta le premier à l’assaut, et il fut nommé général.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Et David s’établit dans la forteresse. A cause de cela, il l’appela Ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Et il bâtit la ville alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'David alla ainsi grandissant, et le Seigneur toutpuissant était avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Voici les chefs des vaillants qui étaient avec David, et qui l’aidèrent à affermir son pouvoir sur tout Israël, selon la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Voici les noms des vaillants de David: Jésebada, fils d’Achaman, le premier des trente. Ce fut lui qui tira l’épée seul contre trois cents, et les tua tous en une fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Après lui, Eléazar (Eléanan), fils de Dudi l’Ahonite; celui-ci était de la première triade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Il était avec David à Phasodamin, et les Philistins s’y réunirent pour livrer bataille. Or, il y avait un champ en partie couvert d’orge, et le peuple s’enfuit devant les Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Pour lui, il s’arrêta au milieu du champ, et il le sauva; il tailla en pièces les Philistins, et le Seigneur opéra une grande délivrance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Et trois, des trente chefs, se rendirent auprès de David, en la caverne d’Odollam, quand les Philistins étaient campés dans le val des Géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David se tenait dans sa forteresse, et les Philistins avaient un poste à Bethleem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Et David eut un désir, et il dit: Qui m’apportera à boire de l’eau de la citerne qui est sous la porte de Bethléem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Et les trois vaillants s’ouvrirent un passage à travers le camp des Philistins, et ils puisèrent de l’eau dans la citerne sous la porte de Bethléem, et ils l’emportèrent, et ils la présentèrent à David; mais il ne voulut pas la boire, et il en fit une libation au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Et il dit: Dieu me protége, je n’en ferai rien; je croirais boire le sang des hommes qui ont exposé leur vie. Et il ne voulut point boire; voilà ce qu’avaient fait les trois vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Il y avait encore Abisaï (Abessa), frère de Joab; celui-ci était chef d’une seconde triade; il avait tiré l’épée contre trois cents qu’il avait tués tous en une fois, et il s’était fait un nom parmi les trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Et, dans sa triade, il fut illustre, et il en devint le chef; mais il n’alla pas aussi loin que ceux de la première triade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Il y avait aussi Banaïas, fils d’un homme vaillant, fils de Joad; il avait fait beaucoup de belles actions en faveur de Cabséel; ce fut lui qui tua deux Ariel de Moab, et qui descendit dans une citerne, un jour de neige, et qui y tua un lion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Il tua encore un Égyptien, homme prodigieux, haut de cinq coudées, qui tenait dans sa main une javeline semblable au mât d’un tisserand; il l’attaqua, n’ayant qu’un bâton, il lui arracha des mains sa javeline, et il le tua avec cette javeline.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Voilà ce que fit Banaïas, fils de Joad, et son nom figurait dans la seconde triade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Et il fut plus illustre que les trente; mais il n’alla pas si loin que la première triade, et David le mit à la tête de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Et les vaillants de l’armée étaient: Asaël, frère de Joab; Eléanan, fils de Dudi de Bethléem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Samoth (Samaan) d’Arori, Hellès (Sellès) de Pheloni,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ora (Iras), fils d’Eccis (Isée) de Thécoé; Abiézer d’Anathoth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Soboch d’Usathi, Héli d’Achoni,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maraï de Netophath; Thaod, fils de Nooza de Netophath;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Aïri, fils de Rebié de la montagne de Benjamin; Banaïas de Pharathon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Uri de Nachali-Gaas, Abiel de Garabeth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azbon de Baromi, Eliaba de Salaboni,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Fils d’Aasam le Gizonéen; Jonathas, fils de Sola d’Arari;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Achim, fils d’Achar d’Arari; Elphat, fils de Thyrophar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'De Mechorathri; Achias de Pheloni,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Eseré de Chadmadaïm; Naaré, fils d’Azobé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Johel, fils de Nathan; Mebaal, fils d’Agari;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Selé, fils de l’Ammonite; Nachor de Beroth, qui portait les armes du fils de Sarvia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Iras de Jéther, Gaber de Jéther,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urie l’Hettéen; Zabet, fils d’Achaïas;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, fils de Saiza, l’un des chefs de Ruben; et il y en avait trente avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Anan, fils de Moocha; Josaphat le Matthanéen,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ozias d’Astaroth; Samatha et Jehiel, fils de Hothan d’Arari;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediel, fils de Sameri; et Jozaé son frère le Thosaïte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Elihel le Mahoïte, et Jaribi, et Josias son fils, et Jethama le Moabite, Daliel, et Obeth, et Jersiel le Mesobéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Et voici ceux qui accompagnaient David à Sicelag, quand il était contraint de se cacher de Saül, fils de Cis; et ils comptaient parmi les vaillants, hommes de secours dans les batailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Ils tiraient leur arc de la main droite et de la main gauche; ils étaient frondeurs et archers. Des frères de Saül, de la tribu de Benjamin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Le chef était Achiézer; puis, venaient Joas, fils d’Asma le Gabathéen; Johel, Jophalet, fils d’Asmoth; Berchia, Jehul d’Anathoth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Samaïas de Gabaon, vaillant parmi les trente, et leur chef, puis, Jérémie, Jézéel, Joanan, Joazobath de Garathiim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Azaï, Arimuth, Baalie, Samaraïe et Saphatias d’Haréphiel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elcana, Jesuni, Ozriel, Jozara, Sobocam et les Coréens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Et Jelia, Zabadie, fils de Joram, et ceux de Gédor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Et, de la tribu de Gad, des hommes vaillants et forts, quittant le désert, rejoignirent David; tous exercés aux combats, portant bouclier et javelines, hommes à face de lion, et légers à la course dans les montagnes, comme des chevreuils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Aza était le chef, Abdias le second, Eliab le troisième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Masmana le quatrième, Jérémie le cinquième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Jéthi le sixième, Eliab le septième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Joanan le huitième, Eléazer le neuvième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jérémia le dixième, Melcbanaï le onzième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Ils étaients les chefs de l’armée des fils de Gad; celui du moindre rang commandait cent hommes; celui du rang le plus élevé en commandait mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ce furent ceux-là qui passèrent le Jourdain pendant le premier mois, lorsqu’il coulait à pleins bords, et ils mirent en fuite tous ceux qui habitaient ses deux rives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Il vint aussi à David des auxiliaires des fils de Benjamin et de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Et David se porta au-devant d’eux, et il leur dit: Si vous êtes venus en paix, mon cœur sera bienveillant pour vous; mais si vous n’êtes point sincères, si vous avez dessein de me livrer à mes ennemis, que le Dieu de vos pères vous voie, et qu’il vous punisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Et l’esprit entra en Amasaï, un chef des trente, et il dit: David, fils de Jessé, marche avec ton peuple, la paix, la paix avec toi, la paix avec tes auxiliaires; car c’est ton Dieu qui t’a secondé. Et David les accueillit, et il leur donna des commandements dans l’armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Et des fils de Manassé vinrent à David, dans le même temps que les Philistins étaient en guerre avec Saül, et qu’ils avaient répudié le secours de David, parce que, dans leur conseil, les chefs des Philistins avaient dit: Il se réconciliera avec son maître Saül, en lui portant les têtes de nos hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Et comme il retournait à Sicelag, Edna, Josabath, Rodiel, Michel, Josabeth, Elimuth et Semathi, vinrent auprès de lui, de Manassé; c’étaient des chefs de mille hommes de Manassé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Et ils furent les auxiliaires de David contre ses ennemis; tous vaillants, comme ils l’étaient, prirent rang parmi les chefs de l’armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Car cette armée s’augmentait de jour en jour, et elle devenait forte comme l’armée de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Et voici le dénombrement des chefs de l’armée qui entrèrent avec David à Hébron, pour lui transmettre la royauté de Saül, selon la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Fils de Juda, portant lance et bouclier: six mille huit cents, prêts à combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Fils de Siméon, vaillants prêts à combattre: sept mille cent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Fils de Lévi: quatre mille six cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Joad conduisait les fils d’Aaron; il avait avec lui trois mille sept cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Sadoc, jeune homme fort et vaillant, avait amené, de sa famille paternelle, vingt-deux chefs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Fils de Benjamin, frères de Saül: trois mille; mais le plus grand nombre de cette tribu formait encore la garde du palais de Saül.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Fils d’Ephraïm vingt mille, vaillants et forts, hommes illustres dans leurs familles paternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Fils de la demi-tribu de Manassé: dix-huit mille, qui furent recensés nominativement, pour établir roi David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Fils d’Issachar, connaissant ce qu’exigeaient les circonstances, sachant ce qu’il y avait à faire pour Israël: deux cents, et avec eux tous leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Flis de Zabulon, allant au combat avec toutes les armes de guerre cinquante mille, auxiliaires de David, n’ayant pas les mains vides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Fils de Nephthali: mille chefs, et avec eux trentesept mille hommes, portant lance et bouclier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Fils de Dan, prêts à combattre: vingt-huit mille huit cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Fils d’Aser: quarante mille auxiliaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Fils de Ruben, de Gad, et de la demi-tribu de Manassé, au delà du Jourdain, portant toutes les armes de guerre: cent vingt mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Tous ces hommes, qui étaient aguerris et prêts à combattre, vinrent à Hébron, pleins d’un esprit pacifique, afin de proclamer David roi de tout Israël, et tout le reste du peuple n’avait qu’une âme pour couronner David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Et ils demeurèrent trois jours, mangeant et buvant ce que leurs frères avaient préparé pour eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Et David tint conseil avec tous ses chefs, centeniers ou commandants de mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Et David dit à toute l’Église d’Israël: Si cela vous paraît bon et agréable au Seigneur notre Dieu, envoyons chez nos frères qui sont restés en tout le territoire d’Israël, et chez les prêtres et les lévites, dans les villes où ils résident; qu’il se réunissent à nous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Et amenons auprès de nous l’arche de notre Dieu; car, depuis l’avénement de Saül, on ne l’a point demandée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Et toute l’Église dit qu’il fallait faire ainsi; car ce discours avait plu à tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Et David réunit tout Israël, depuis les confins de l’Égypte jusqu’aux défilés d’Emath, pour ramener l’arche de la ville d’larim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Et David la ramena; et tout Israël entra dans la ville de David, qui est en Juda, pour y introduire l’arche du Seigneur Dieu assis sur les chérubins, où est invoqué son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'On avait posé l’arche de Dieu sur un chariot neuf de la maison d’Aminadab; Oza et ses frères conduisaient l’attelage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Et David et tout Israël jouaient de tout leur cœur de la flûte, de la lyre, du tambour, et des cymbales, et de la harpe, au milieu des cantiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Et ils vinrent jusqu’à l’aire; là, Oza étendit la main pour maintenir l’arche que le mouvement d’un bœuf avait fait pencher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Mais le Seigneur s’irrita contre Oza, et il le frappa en ce lieu même, parce qu’il avait porté la main sur l’arche; et il mourut là devant Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Et David fut abattu, parce que Dieu avait châtié Oza, et ce lieu fut appelé le Châtiment d’Oza, nom qu’il porte encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Et, ce jour-là, David eut crainte du Seigneur, et il dit: Comment ferai-je entrer chez moi l’arche du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Et David ne ramena pas l’arche avec lui dans la ville de David; mais la fit placer en la maison d’Abdara le Géthéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Et l’arche du Seigneur resta trois mois en la maison d’Abdara le Géthéen, et le Seigneur bénit toute la maison d’Abdara et tout ce qui lui appartenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Et Hiram, roi de Tyr, envoya à David des messagers, des maçons et des charpentiers, avec des bois de cèdre, pour lui bâtir une maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Et David reconnut que le Seigneur l’avait préparé pour être roi d’Israël; car son royaume s’était élevé et agrandi pour le bien être du peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Et David prit encore des femmes à Jérusalem; elles lui enfantèrent des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Voici les noms de ceux qui naquirent à Jérusalem: Samaa, Sobab, Nathan, Salomon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Baar (Ebeher), Elisa (Elisua), Eliphaleth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nageth (Naged), Naphath (Naphec), Japhia,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Eliada et Eliphalat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Cependant, les Philistins apprirent que David avait été sacré roi de tout Israël; et ils se mirent tous en campagne pour l’attaquer; mais lui, l’ayant su, sortit à leur rencontre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Et ils s’avancèrent, et ils s’entassèrent dans le val des Géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Et David consulta Dieu, disant: Dois-je marcher contre les Philistins? me les livrerez-vous? Et le Seigneur lui répondit: Marche, car je te les livrerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Et il alla à Baal-Pharasin, où il les battit, et il s’écria Dieu, par mes mains, a brisé mes ennemis comme brisent les eaux des torrents. A cause de cela, il donna à ce lieu le nom de Brisement d’en haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Or, les Philistins avaient abandonné là leurs dieux, et David dit: Livrez-les aux flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Et les Philistins continuèrent la guerre, et ils so réunirent encore dans le val des Géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Et David consulta derechef le Seigneur, et le Seigneur lui dit: Ne les suis pas, fais un détour, et tu les aborderas près des poiriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Et ceci arrivera: Lorsque tu entendras, de la colline des Poiriers, le bruit sourd de l’ébranlement qu’ils donneront au sol, tu engageras la bataille; car alors le Seigneur marchera devant toi pour frapper le camp des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'David fit ce que lui avait prescrit le Seigneur, et il tailla en pièces les Philistins, depuis Gabaon jusqu’à Gazara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Et le nom de David se répandit sur toute la terre, et le Seigneur inspira à tous les peuples la crainte de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Et il se bâtit des demeures en la ville de David, et il prépara un lieu pour l’arche du Seigneur, et il fit un tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Alors David dit: Nul ne peut transporter l’arche de Dieu, sinon les lévites; car le Seigneur les a choisis pour porter l’arche du Seigneur et le servir éternellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Et David réunit tout le peuple de Jérusalem, pour transporter l’arche au lieu qu’il avait préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'David convoqua aussi les lévites, fils d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Des fils de Caath: Uriel leur chef, et ses frères: cent vingt hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Des fils de Mérari: Asaïe leur chef, et ses frères: deux cent vingt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Des fils de Gerson: Johel leur chef, et ses frères: cent trente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Des fils d’Elisaphat: Sémeï leur chef, et ses frères: deux cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Des fils d’Hébron: Elihel leur chef, et ses frères: quatre-vingts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Des fils d’Oziel: Aminadab leur chef, et ses frères: cent douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Et David appela les prêtres Sadoc et Abiathar avec les lévites: Uriel, et Asaïe, et Johel, et Sémeï, et Elihel, et Aminadab,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Et il leur dit: Vous êtes chefs de familles des lévites: purifiez-vous donc, et purifiez vos frères, et vous transporterez l’arche du Dieu d’Israël, au lieu que je lui ai préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Car, d’abord, parce que vouz n’étiez point là; le Seigneur Dieu nous a châtiés, pour ne l’avoir point cherché, selon la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Et les prêtres et les lévites se purifièrent, pour transporter l’arche du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Et les fils des lévites prirent l’arche de Dieu de la manière prescrite par Moïse, d’après la parole de Dieu et selon l’Écriture; puis, ils posèrent les leviers sur leurs épaules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Et David dit aux chefs des lévites: Choisissez parmi vos frères des chantres, s’accompagnant d’instruments: de lyres, de harpes et de cymbales, pour chanter bien haut des cantiques d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Et les lévites désignèrent Hêman, fils de Johel; puis, Asaph, fils de Barachia, un de leurs frères; puis, Ethan, fils de Cisaïe, un des fils de Mérari, un de leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Et, avec eux, au second rang, leurs frères Zacharie, Oziel, Semiramoth, Jehiel, Eliohel, Eliab, Banaïas, Maasaïe, Matthathias, Eliphena, Macélia, Abdedom, Jehiel et Ozias, qui étaient les portiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Les chantres harpistes: Héman, Asaph et Ethan, avaient des cymbales d’airain pour les faire retentir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zacharie et Oziel, Semiramoth, Jéhiel, Oni, Eliab, Maasaïe, Banaïas, avaient des lyres sur l’alcimoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Et Matthathias, et Eliphalu, et Macélia, et Abdedom, et Jehiel, et Ozias, avaient des harpes pour renforcer l’amasenith.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Honénias, chef des lévites, était maître du chant, à cause de son intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Barachias et Elcana étaient portiers de l’arche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Somnia, Josaphat, Nathanaël, Amasaï, Zacharie, Banaïas et Eliézer, les prêtres, sonnaient de la trompette devant l’arche de Dieu. Abdedom et Jehia étaient portiers de l’arche de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'David, et les anciens d’Israël et les chefs de mille hommes, partirent ainsi pour transférer l’arche de l’alliance de la maison d’Abdedom, avec allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Et comme Dieu fortifiait les lévites qui portaient l’arche de l’alliance du Seigneur, on sacrifia devant le cortége sept bœufs et sept béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Or, David était revêtu d’une robe de lin, ainsi que tous les lévites qui portaient l’arche de l’alliance du Seigneur, et les chantres-harpistes, et Honénias, maître du chant; David avait comme eux une robe de lin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Et tout Israël conduisait l’arche de l’alliance du Seigneur, jetant des cris de joie et chantant les uns au son des trompettes et des cymbales, les autres avec accompagnement de lyres et de harpes. Lorsque l’arche de l’alliance du Seigneur entra dans la ville de David, Michol, fille de Saül, se penchant à sa fenêtre, vit le roi David danser et toucher de la harpe; et, en son âme, elle le méprisa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Et ils introduisirent l’arche de Dieu, et la placèrent au milieu du tabernacle que David avait dressé pour elle, et l’on offrit devant Dieu des holocaustes et des hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Quand David eut fait ses offrandes d’holocaustes et d’hosties pacifiques, il bénit le peuple au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Et il donna à chaque homme et à chaque femme d’Israël un pain de boulanger, et un pain pétri avec du miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Et il institua devant l’arche de l’alliance du Seigneur ceux des lévites qui devaient y être employés, pour chanter et louer le Seigneur Dieu d’Israël, et lui rendre grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph fut le chef, et il eut pour second Zacharie; puis, Jehiel, Semiramoth et Jehiel, Matthathias, Eliab, Banaïas et Abdedom: Jehiel jouait de la lyre et de la harpe, et Asaph faisait retentir des cymbales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Banaïas et Oziel les prêtres, sonnaient toujours de la trompette devant l’arche de l’alliance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Et ce jour-là, pour la première fois, David prescrivit que l’on chantât les louanges du Seigneur, sous la direction d’Asaph et de ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Cantique. Rendez hommage au Seigneur, invoquez-le par son nom, faites connaître aux peuples ses désirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Chantez-le, chantez ses louanges; racontez à tous les merveilles qu’a faites le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Louez son saint nom; le cœur qui cherche à lui être agréable sera réjoui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Cherchez le Seigneur et soyez forts; cherchez toujours son visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Souvenez-vous des prodiges qu’il a faits, des merveilles et des jugements sortis de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Enfants d’Israël, ses serviteurs; fils de Jacob, ses élus;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Le Seigneur seul est notre Dieu; ses jugements sont sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Souvenons-nous toujours de son alliance, de la loi qu’il nous a donnée pour des milliers de générations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'De son alliance avec Abraham; de son serment à Isaac,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Il l’a confirmé à Jacob comme un commandement, à Israël comme une alliance impérissable,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Disant: Je te donnerai la terre de Chanaan; c’est ta part d’héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Alors, ils étaient en petit nombre, ils étaient humbles, et ils étaient passagers sur cette terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Et ils allèrent d’une nation à l’autre, et d’un royaume à un autre peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Et à nul homme il ne permit de prévaloir sur eux, et à leur sujet il châtia des rois:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Ne touchez point à mes christs; ne maltraitez pas mes prophètes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Chantez le Seigneur: que toute la terre le chante, proclamez chaque jour que lui seul est notre salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Racontez aux nations sa gloire, à tous les peuples ses merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Car le Seigneur est grand et digne de louanges infinies; il est redoutable plus que tous les dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Car, tous les dieux des nations sont des idoles, et notre Dieu a créé le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Gloire et louange à lui face à face; force et joie au lieu où il réside.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Tribus des nations, donnez au Seigneur, donnez au Seigneur force et gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Glorifiez le nom du Seigneur; prenez des dons et offrez-les au Seigneur en sa présence, et adorez le Seigneur dans ses demeures saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Que toute la terre ait crainte devant lui; que la terre s’affermisse et ne soit point ébranlée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Que le ciel se réjouisse, que la terre tressaille d’allégresse, et qu’ils disent aux nations: Le Seigneur règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'La mer bruira dans sa plénitude, et l’arbre des champs avec tout ce qu’il porte se réjouira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Alors, les arbres de la forêt se réjouiront devant le Seigneur, parce qu’il est venu juger la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Rendez hommage au Seigneur, parce qu’il est bon et que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Et dites: Sauvez-nous, ô Dieu notre salut; recueillez-nous et séparez-nous des nations, afin que nous chantions les louanges de votre saint nom, et que nous mettions notre gloire à vous louer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Béni soit le nom du Seigneur Dieu d’Israël dans tous les siècles des siècles, et tout le peuple dira: Amen. Et ils louèrent le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Et ils laissèrent là devant l’arche de l’alliance du Seigneur Asaph et ses frères, pour faire devant l’arche à perpétuité le service de chaque jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Ils laissèrent aussi Abdedom et ses frères, au nombre de soixante-huit, et Abdedom, fils d’Idithun, et Osa pour être portiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Et Sadoc le prêtre, avec ses frères les prêtres, fut laissé devant le tabernacle du Seigneur, sur le haut lieu de Gabaon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Afin d’offrir des holocaustes au Seigneur, sur l’autel des holocautes à perpétuité, matin et soir, selon qu’il est écrit en la loi du Seigneur, qu’il a donnée aux fils d’Israël par la voix de Moïse, son serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Et avec Sadoc étaient Hêman et Idithun, et le reste de ceux qu’on avait nominativement désignés pour louer le Seigneur, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Et ils avaient avec eux des trompettes et des cymbales, pour les faire retentir, et les instruments accompagnant les cantiques de Dieu. Et les fils d’Idithun étaient gardiens des portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Et le peuple s’en retourna chacun en sa demeure, et David s’en alla pour bénir sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Et quand David eut pris possession de son palais, il dit à Nathan le prophète: Voilà que j’habite une maison de cèdre, tandis que l’arche de l’alliance du Seigneur repose sous des courtines de peaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Et Nathan dit à David: Tout ce qui est en ton cœur, fais-le, car Dieu est avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mais, cette nuit même, la parole du Seigneur vint à Nathan, et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Va, et dis à mon serviteur David: Voici ce que dit le Seigneur: Tu ne me bâtiras pas un temple pour que je l’habite,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Parce que je n’ai point résidé dans un temple depuis que j’ai tiré de l’Égypte les fils d’Israël jusqu’à ce jour, et que je me suis tenu dans un tabernacle et sous un voile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'En quelque lieu que j’aie passé avec tout Israël, ai-je jamais dit à celle des tribus que j’avais chargée de prendre soin de tout le peuple: Pourquoi ne m’avez-vous point bâti une maison de cèdre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Dis encore à mon serviteur David: Voici ce que dit le Seigneur tout-puissant: Je t’ai tiré de la bergerie quand tu marchais derrière les troupeaux, pour que tu sois roi de mon peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Je t’ai accompagné partout où tu as marché, j’ai exterminé devant toi tous tes ennemis, et je t’ai rendu célèbre autant que les plus renommés des grands de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Et j’adopterai un lieu pour mon peuple Israël; je l’y fixerai et il s’y abritera, chacun aura sa demeure, et il ne sentira plus d’inquiétudes, et le fils de l’iniquité ne l’affligera plus comme il a fait dès le commencement,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Depuis les temps où j’ai donné des juges à mon peuple; j’ai humilié tous tes ennemis, et je t’augmenterai, et le Seigneur te fera une maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Et, quand tes jours seront remplis, quand tu te seras endormi avec tes pères, j’élèverai après toi ta race et celui qui sera issu de ton sang; et je préparerai son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Celui-là me bâtira un temple, et je dresserai son trône pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Je serai pour lui un père, et il sera pour moi un fils, et je ne lui retirerai point ma miséricorde, comme je l’ai retirée à ceux qui t’ont précédé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Et je l’établirai en mon temple, et en son royaume pour toujours; et son trône sera toujours debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Ainsi, Nathan répéta à David toutes ces paroles, que lui-même avait ouïes en sa vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Alors, le roi David s’en alla; et il se plaça devant le Seigneur, et il dit: Qui suis-je, Seigneur mon Dieu, et qu’est ma maison pour que vous m’aimiez à jamais?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Ce que vous en avez fait c’était à vos yeux peu de chose, ô mon Dieu, et vous avez parlé de la maison de votre serviteur pour un avenir lointain, et vous m’avez regardé comme on regarde un ami, et vous m’avez élevé, Seigneur mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Que pourra faire encore David devant vous pour vous glorifier? Vous connaissez maintenant votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Vous avez opéré ces grandes choses au gré de votre cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Seigneur, nul ne vous ressemble, nul n’est Dieu que vous, et vous vous êtes révélé par toutes les merveilles que nous avons ouï redire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Et il n’est point sur la terre de peuple qui ressemble à Israël votre peuple. Il n’en est point que Dieu ait guidé pour le racheter et s’en faire un peuple pour luimême, pour se faire à lui-même un grand et glorieux nom, et pour expulser les nations devant votre peuple que vous avez délivré de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Vous vous êtes donné, en Israël, un peuple qui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Maintenant donc, Seigneur, que la promesse que vous avez faite à votre serviteur, concernant sa maison, soit à jamais confirmée; faites comme vous avez dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Et que votre nom soit glorifié à jamais, et que l’on y ait foi, et que l’on dise: Seigneur, Seigneur tout-puissant, Dieu d’Israël, la maison de David votre serviteur est érigée devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Car, Seigneur Dieu, vous avez révélé vos desseins à votre serviteur, disant: Je te bâtirai une maison; c’est à ce sujet que votre serviteur a pensé à vous prier face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Et maintenant, Seigneur, vous seul êtes Dieu, et c’est vous qui avez fait à votre serviteur ces magnifiques promesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Commencez donc et bénissez la maison de votre serviteur, pour qu’elle subsiste toujours devant vous; car, Seigneur, vous l’avez déjà bénie, bénissez-la donc à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Il advint, après cela, que David battit les Philistins, et qu’il les mit en fuite; et il leur enleva Geth avec ses bourgs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Il vainquit Moab, et les fils de Moab lui furent asservis; et ils lui payèrent un tribut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David vainquit aussi, dans le pays d’Hémath, Adraazar, roi de Suba, qui s’était mis en campagne pour se rendre maître des rives de l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Et David prit aux vaincus mille chars, sept mille chevaux et vingt mille piétons; puis, il énerva les attelages de tous les chars, et n’en garda que cent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Et le Syrien de Damas marcha au secours d’, roi de Suba, et David tua au Syrien vingt-deux mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Et David mit une garnison dans la Syrie de Damas, et les Syriens lui furent asservis; ils lui payèrent un tribut. Et le Seigneur protégea David partout où il porta ses armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Et David prit les colliers d’or que portaient les serviteurs d’Adraazar, et il les consacra dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Et David recueillit à Mathabeth (Métébac), et dans les principales villes d’Adraazar, une prodigieuse quantité d’airain, dont Salomon se servit pour fabriquer la mer d’airain, et les colonnes et tous les vases d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Cependant Thoa (Thu), roi d’Hémath, apprit que David avait taillé en pièces toute l’armée d’Adraazar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Et il envoya vers David son fils Aduram (Jedduram), pour lui demander la paix et le bénir à cause de sa victoire sur Adraazar; car Thoa était ennemi d’Adraazar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Le roi David consacra au Seigneur tous les vases d’or, d’argent et d’airain, de même que l’argent et l’or qu’il avait pris à toutes les nations: à l’Idumée, à Moab, aux fils d’Ammon, aux Philistins et aux fils d’Amalec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Et Abessa, fils de Sarvia, tailla en pièces quatre-vingt mille Philistins dans le val d’Aïlon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Et il mit dans la vallée une garnison, et tous les Iduméens furent asservis à David, et le Seigneur protégea David partout où il porta ses armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Ainsi, David régna sur tout Israël, et il jugea tout son peuple selon l’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, fils de Sarvia, commandait l’armée; Josaphat, fils d’Achilud, recueillait les actes publics.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sadoc, fils d’Achitob, et Achimélech, fils d’Abiathar, étaient prêtres, et Susa (Sasa), scribe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Et Banaïas, fils de Joad, commandait Chéléthi et Phéléthi, et les fils de David étaient les premiers lieutenants du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Et Naas, roi des fils d’Ammon, mourut, et Anan (Annon), son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Et David dit: Je serai miséricordieux envers Anan, fils de Naas, de même que son père a été miséricordieux pour moi. En conséquence, il envoya des serviteurs pour le consoler au sujet de son père, et les serviteurs de David allèrent en la terre des fils d’Ammon, auprès d’Anan, pour le consoler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Mais, les princes des fils d’Ammon dirent à Anan: Est-ce pour glorifier devant toi ton père que David envoie ces consolateurs? N’est-ce point plutôt pour s’informer de ta ville et pour lá reconnaître que ses serviteurs sont venus près de toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Anan saisit donc les serviteurs de David; il leur rasa la barbe; il coupa leurs manteaux, depuis le milieu du corps jusqu’aux pieds; puis, il les chassa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'On vint dire à David ce qui leur était arrivé, et il envoya des gens à leur rencontre; car ils étaient cruellement déshonorés, et il leur dit: Demeurez à Jéricho jusqu’à ce que votre barbe ait repoussé; puis, alors vous reviendrez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Les fils d’Ammon, voyant que le peuple d’Israël se tenait pour outragé, Anan et les fils d’Ammon envoyèrent mille talents d’argent pour enrôler des chars et des cavaliers dans la Syrie de Mésopotamie, dans la Syrie Maacha et à Sobal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Ils enrôlèrent ainsi pour eux trente-deux mille chars, et le roi de Maacha avec tout son peuple. Ces auxiliaires vinrent, et ils campèrent vis-à-vis Médaba. Cependant, les fils d’Ammon, sortant de leurs villes, se rassemblèrent, et ils s’ébranlèrent pour combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'David l’apprit, et il mit en mouvement Joab avec toute l’armée des hommes vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Et les fils d’Ammon sortirent, et ils se rangèrent en bataille près des portes de la ville, et les rois leurs alliés campèrent, chacun de son côté, dans la campagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Joab reconnut qu’il aurait à livrer bataille devant son front et sur ses derrières; il rangea donc en face des Syriens les plus vaillants des jeunes fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Et il confia à son frère Abessa le reste de l’armée, qui se déploya devant les fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Et il dit à son frère: Si le Syrien l’emporte sur moi, tu viendras à mon aide, et si les fils d’Ammon te font plier, j’irai te secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sois fort, agis en homme, pour l’amour de notre peuple et pour les villes de notre Dieu; que le Seigneur ensuite fasse à sa volonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Et Joab avec sa troupe tomba sur les Syriens; et ceux-ci s’enfuirent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Quand les fils d’Ammon virent que les Syriens fuyaient, ils s’enfuirent eux-mêmes devant Abessa; et ils s’enfermèrent dans leur ville, et Joab revint à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Et le Syrien, voyant qu’Israël l’avait mis en fuite, envoya des messagers qui levèrent toute la Syrie des rives du Jourdain, et à sa tête Sophath (Sobac), général en chef de l’armée d’Adraazar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'On en instruisit David; il réunit tout Israël, passa le Jourdain, les atteignit et les aborda de front; aussitôt la bataille s’engagea.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Les Syriens s’enfuirent devant Israël; David leur tua sept mille hommes montés sur des chars, et quarante mille piétons; Sophath, le général en chef, périt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Et tous les serviteurs d’Adraazar, voyant qu’ils avaient échoué devant Israël, traitèrent avec David, et ils lui furent asservis. Quant au Syrien, il ne voulut plus secourir les fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Le cours de l’année ramena le temps où les rois se mettent en campagne. Joab emmena toutes les forces de l’armée, et il ravagea la contrée des fils d’Ammon; il assiégea ensuite Rhabba, pendant que David était resté à Jérusalem; Joab prit Rhabba (Rabbath), et la détruisit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Et David prit sur la tête du roi Molchom sa couronne, qui pesait un talent d’or, et qui était ornée de pierres précieuses; elle allait à la tête de David; enfin, il rapporta de cette ville un immense butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Et il emmena tout le peuple qui l’habitait, et il l’extermina en plaçant les uns sous des scies, les autres sous des haches de fer, d’autres sous la cognée du bûcheron. Ce fut ainsi que David traita tous les fils d’Ammon, et David et tout le peuple retournèrent à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Ensuite, la guerre recommença avec les Philistins de Gazer. Alors, Sobochaï le Sasathite tua Saphut, de la race des géants, après l’avoir humilié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Et il y eut une autre guerre avec les Philistins; et Eléanan, fils de Jaïr, tua Lachmi, frère de Goliath de Geth, qui portait une lance comme le mât d’un tisserand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Et il y eut encore une guerre avec Geth. Or, il y avait un homme de grande taille, issu des géants, et qui avait vingt-quatre doigts, six à chaque main, et six à chaque pied.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Et il insulta Israël; et Jonathas, fils de Samaa, frère de David, le tua. Ces hommes étaient de la race de Rhapha de Geth; ils étaient quatre, tous géants, et ils tombèrent sous les coups de David et de ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Et le diable se leva contre Israël; il excita le roi David à faire le dénombrement du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Le roi dit donc à Joab et aux chefs de l’armée: Allez et faites le dénombrement d’Israël, depuis Dan jusqu’à Bersabée; puis, rapportez-le-moi, et je saurai leur nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab répondit: Puisse le Seigneur ajouter à son peuple et le rendre cent fois aussi nombreux qu’il l’est, et puisse le roi mon maître le voir de ses yeux; puissent le voir aussi les serviteurs de mon maître; mais pourquoi mon maître a-t-il formné ce dessein? Est-ce pour qu’il soit imputé à péché au peuple d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mais, la volonté du roi prévalut sur Joab, et Joab partit, et il parcourut tout Israël, et il revint à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Et Joab remit à David le dénombrement du peuple qu’il avait recensé: il y avait en tout Israël onze cent mille hommes tirant l’épée, et en Juda étaient quatre cent soixante-dix mille hommes tirant l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Et Joab n’avait compté ni Lévi, ni Benjamin, parce qu’il avait cédé à contre-cœur au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Et la chose fut mauvaise devant Dieu, et il frappa Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Et David dit à Dieu: J’ai gravement péché en ce que je viens de faire, et maintenant remettez à votre serviteur son iniquité, car j’ai commis une insigne folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Et le Seigneur parla à Gad le voyant, et il lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Pars et adresse-toi à David, disant: Voici ce que dit le Seigneur: Je t’apporte trois choses; choisis pour toi l’une d’elles, et tu l’auras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Gad alla trouver David, et il lui dit: Voici ce que dit le Seigneur: Choisis pour toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Ou trois ans de famine, ou trois mois pendant lesquels tu fuiras devant tes ennemis qui te détruiront par le glaive, ou trois jours de mort causée par l’épée du Seigneur en toute cette terre, et par l’ange exterminateur parcourant tout l’héritage d’Israël: vois donc ce que je dois répondre à Celui qui m’envoie te répéter sa parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Et David dit à Gad: Le choix des trois parts m’est cruel; mais j’aime mieux me livrer aux mains du Seigneur, parce qu’il a eu souvent compassion de moi; je ne tomberai point dans les mains des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Et le Seigneur envoya la mort en Israël, et soixante-dix mille hommes d’Israël périrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Le Seigneur envoya aussi l’ange à Jérusalem pour l’exterminer, et comme il frappait, le Seigneur le vit et se repentit de tout ce mal, et il dit à l’ange exterminateur: C’est assez, arrête ta main. Or, l’ange du Seigneur était auprès de l’aire d’Orna le Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'David, ayant levé les yeux, vit l’ange du Seigneur se tenant entre la terre et le ciel; il avait à la main son épée nue, et il l’étendait sur Jérusalem. Et David et les anciens couverts de cilices tombèrent la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Et David dit à Dieu: N’est-ce pas moi qui ai prescrit de faire le dénombrement du peuple? C’est moi qui suis le coupable; j’ai grandement péché. Mais ces brebis qu’ont-elles fait? Seigneur mon Dieu, que votre main soit contre moi et contre la maison de mon père; qu’elle épargne ce peuple qui périt, ô Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Et l’ange du Seigneur dit à Gad de prescrire à David qu’il allât élever un autel au Seigneur dans l’aire d’Orna le Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Et David sortit, selon la parole que Gad lui avait dite au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Et Orna se retourna, et il vit le roi et quatre de ses fils, tous se cachant, et Orna était à vanner du froment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Et David arriva auprès d’Orna, et Orna, quittant l’aire, se prosterna la face contre terre devant David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Et David dit à Orna: Donne-moi l’emplacement de ton aire, et j’y bâtirai un autel au Seigneur; donne-le-moi à prix d’argent, et le fléau cessera de frapper le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Et Orna dit à David: Que le roi mon maître prenne et consacre ce que bon lui semble. Voici mes bœufs pour l’holocauste, ma charrue pour le brûler, et mon blé pour le sacrifice; je te donne tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Et le roi David dit à Orna: Nullement; certes, j’achèterai toutes ces choses, car elles valent de l’argent; je ne prendrai, pour le Seigneur, rien de ce qui est à toi; je ne présenterai pas au Seigneur un holocauste qui ne me coûte rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'David donna donc à Orna, pour son terrain, six cents sicles d’or, au poids du sicle du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Il bâtit l’autel du Seigneur, sur lequel il offrit des holocaustes et des hosties pacifiques; enfin, il cria au Seigneur, et le Seigneur l’exauça; le feu du ciel, descendant sur l’autel de l’holocauste, consuma la victime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Et le Seigneur parla à l’ange, et l’ange remit l’épée dans le fourreau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Dès lors, David, ayant vu que le Seigneur lui répondait dans l’aire d’Orna le Jébuséen, en fit un lieu de sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Or, en ce temps-là, le tabernacle du Seigneur que Moïse avait fait dans le désert, et l’autel des holocaustes, étaient sur le haut lieu de Gabaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Et David n’avait pu s’y transporter pour prier le Seigneur; il ne s’était point empressé d’y aller, à cause de l’épée de l’ange du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Et David dit: C’est ici la maison du Seigneur, et voici l’autel des holocaustes pour Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Puis, il ordonna de réunir tous les étrangers qui se trouvaient en la terre d’Israël, et il chargea des tailleurs de pierres de tailler des pierres, pour bâtir la maison de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Et David prépara beaucoup de fer, des clous pour les portes et leurs vanteaux, des gonds et une quantité d’airain d’un poids incalculable,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Et un nombre infini de cèdres que les Tyriens et les Sidoniens lui apportèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Et David dit: Mon fils Salomon est d’âge tendre, et la maison qui doit être bâtie au Seigneur surpassera en magnificence, en renom et en gloire, toutes celles de la terre; je préparerai tout pour cela. Et David fit ses apprêts à profusion avant de mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Et il appela Salomon, son fils, et il lui ordonna de bâtir le temple du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Et David dit à Salomon: Enfant, mon âme a voulu bâtir un temple au nom du Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mais la parole du Seigneur est venue à moi, disant: Tu as versé beaucoup de sang, tu as fait de grandes guerres; tu ne bâtiras point un temple à mon nom, parce que, devant moi, tu as répandu beaucoup de sang sur cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Voici qu’un fils t’est né; celui-là sera un homme de paix, et je le maintiendrai en paix avec tous les ennemis qui l’entourent; car son nom est Salomon, et j’accorderai, pendant sa vie, le repos et la paix à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'C’est lui qui bâtira un temple à mon nom, et il sera pour moi un fils, et moi je serai pour lui un père, et je dresserai son trône royal en Israël pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Maintenant, mon fils, le Seigneur sera avec toi; il te fera prospérer, et tu bâtiras le temple du Seigneur ton Dieu, comme il me l’a fait savoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Que le Seigneur te donne seulement l’intelligence et la sagesse, et il t’affermira sur Israël, pour que tu observes et que tu mettes en pratique la loi du Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Alors, il te fera prospérer, si tu veilles à observer les commandements et les préceptes que le Seigneur a donnés au peuple par la voix de Moïse. Sois fort, et agis en homme; n’aie ni crainte ni faiblesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Vois, dans ma pauvreté, j’ai préparé pour la maison du Seigneur: cent mille talents d’or, un million de talents d’argent, de l’airain et du fer en telle abondance, qu’on n’en peut dire le compte. J’ai aussi préparé des bois et des pierres, et tu y ajouteras encore,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Et tu t’adjoindras une multitude d’ouvriers, artisans, tailleurs de pierres, charpentiers, et tout homme habile à mettre en œuvre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'L’or, l’argent, et une masse innombrable d’airain et de fer. Courage donc, et agis, le Seigneur sera avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Ensuite, David ordonna à tous les chefs d’Israël de seconder Salomon, son fils, et il leur dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Le Seigneur n’est-il pas avec vous? Il vous a donné le repos tout alentour; il vous a livré ceux qui habitaient la terre promise, et la terre s’est soumise devant le Seigneur et devant son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Appliquez-vous donc, cœur et âme, à chercher le Seigneur, excitez-vous, et bâtissez pour votre Dieu un lieu saint, afin d’y transporter l’arche de l’alliance du Seigneur, avec les vases et les ornements consacrés à Dieu, qui résideront dans le temple élevé au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Or, David était vieux et plein de jours, et il proclama roi à sa place son fils Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Il rassembla tous les chefs d’Israël, les prêtres et les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Les lévites de trente ans et au-dessus furent comptés, et il s’en trouva trente-huit mille, savoir:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Vingt-quatre mille employés aux travaux du tabernacle du Seigneur, six mille scribes et juges;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Quatre mille portiers, et quatre mille chantres louant le Seigneur au son des instruments qu’avait faits David pour accompagner ses louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David les divisa, et il assigna leurs jours de service aux fils de Lévi, aux familles de Gerson, Caath et Mérari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Fils de Gerson: Edan (Lobeni) et Sémeï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Fils d’Edan Jehiel le premier, et Zêthan et Johel: trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Fils de Sémeï: Salomith, Jehiel et Dan. Tels sont les trois chefs des familles d’Edan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Fils de Sémeï: Jeth, Ziza, Joas et Beria. Tels sont les quatre fils de Sémeï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jeth était le premier, et Ziza le second; Joas et Beria n’eurent pas beaucoup d’enfants, et ils ne formèrent qu’une famille en une seule maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Fils de Caath: Amram, Isaar, Hébron, Oziel: quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Fils d’Amram: Aaron et Moïse, et Aaron fut désigné pour servir dans le Saint des saints, lui et ses fils, perpétuité, pour faire les sacrifices devant le Seigneur, pour servir et prier en son nom à perpétuité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Quant à Moïse, l’homme de Dieu, ses fils furent comptés dans la tribu de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Fils de Moïse: Gersam et Eliézer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Fils de Gersam: Sobahel le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliézer eut aussi des enfants: Rabia fut le premier, et Eliézer n’eut pas d’autres fils; mais les fils de Rabia multiplièrent extrêmement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Fils d’Isaar: Salomoth le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Fils d’Hébron: Jeria le premier, Amaria le second, Jéziel le troisième, Jécémias le quatrième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Fils d’Oziel: Micha le premier, Isia le second.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Fils de Mérari: Mooli et Musi. Fils de Mooli: Eléazar et Cis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eléazar mourut, et il n’avait point de fils, mais des filles, et les fils de Cis, leurs frères, les prirent pour femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Fils de Musi: Mooli, et Eder, et Jarimoth; trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Tels furent les fils de Lévi, par familles paternelles, chefs de leurs familles, selon le recensement par noms et par têtes, faisant le service du tabernacle du Seigneur, âgés de trente ans et au-dessus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Or, David dit: Le Seigneur Dieu d’Israël a donné le repos à son peuple, et il a choisi Jérusalem pour sa demeure à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Les lévites n’avaient donc plus dans leur service le transport du tabernacle et de ses ornements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Et, selon les dernières paroles de David, le dé nombrement des fils de Lévi, âgés de trente ans et audessus, avait été fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Et, d’après Aaron, il avait réglé les emplois dans la demeure du Seigneur, tant dans les parvis que dans les chambres, et pour ce qui concernait la purification du Saint des saints, et les autres services du tabernacle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Et les pains de proposition, et la fleur de farine des sacrifices, et les poêles à cuire les azymes, et la pâte, et les mesures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Et les louanges du Seigneur qu’on devait chanter du matin au soir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Et tous les holocaustes à offrir au Seigneur, tant les jours de sabbat qu’aux nouvelles lunes et aux fêtes, selon le nombre et les usages invariables, devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Et il était prescrit aux lévites de garder le tabernacle du témoignage, et le Saint des saints, et les fils d’Aaron leurs frères, pendant leur service dans le tabernacle du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Et les fils d’Aaron étaient: Nadab, Abiud, Eléazar et Ithamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Or, Nadab et Abiud moururent sous les yeux de leur père, et ils n’avaient point de fils; Eléazar et Ithamar, fils d’Aaron, eurent donc le sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Et David distingua les fils d’Eléazar, de qui descendait Sadoc, des fils d’Ithamar, de qui était issu Achimélech, selon leur recensement, et leurs services, et leurs familles paternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Et il se trouva, parmi ces hommes forts, plus de chefs des fils d’Eléazar que des fils d’Ithamar, et David mit les premiers à la tête de seize familles, les seconds à la tête de huit familles seulement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Et il leur distribua leurs services par le sort; car, parmi les uns comme parmi les autres, il y avait des chefs des choses saintes, et des chefs du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Et le scribe Samaïas, fils de Nathanaël de la tribu de Lévi, écrivit la liste en présence du roi et des chefs, aidé de Sadoc le prêtre, et d’Abimélech, fils d’Abiathar, et des chefs des familles paternelles des prêtres et des lévites, inscrivant tour à tour un nom provenant d’Eléazar, un nom provenant d’Ithamar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Le sort désigna en premier lieu Joarim; le second fut Jedia,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Le troisième Harib, le quatrième Séorim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Le cinquième Melchias, le sixième Meïamin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Le septième Cos, le huitième Abias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Le neuvième Jésua, le dixième Sechénias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Le onzième Eliabi, le douzième Jacim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Le treizième Opha, le quatorzième Jezbaal,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Le quinzième Belga, le seizième Hemmer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Le dix-septième Hézin, le dix-huitième Aphésé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Le dix-neuvième Phetaïe, le vingtième Ezecel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Levingt et unième Achim, le vingt-deuxième Gamul,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Le vingt-troisième Abdallé, le vingt-quatrième Maasé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Tel fut leur recensement, selon leurs services, pour pénétrer dans le tabernacle du Seigneur, d’après le règlement d’Aaron, leur père, tel que le Seigneur l’avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Voici le reste des fils de Lévi: Fils d’Amram: Sobael. Fils de Sobael: Jedia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Le chef des fils de Raabia:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Salomoth, fils de Isaar; Jath, des fils de Salomoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Les fils d’Ecdiu: Amadias le second, Jaziel le troisième, Jecmoam le quatrième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Des fils d’Oziel: Micha. Des fils de Micha: Samer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Le frère de Micha: Isia. Fils de Micha: Zacharie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Les descendants des fils de Mérari: Mooli et Musi. Les fils d’Ozia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Fils de Mérari: Joram, et Sacchur, et Abaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Mooli avait eu encore Eléazar et Ithamar; mais Eléazar était mort sans laisser de fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Jeraméel, issu des fils de Cis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Et Mooli, Eder et Jerimoth, issus de Musi. Tels étaient les fils des lévites par familles paternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Et ils tirèrent au sort, comme leurs frères les fils d’Aaron, en présence du roi, de Sadoc, d’Achimelech, et des chefs de familles des prêtres et des lévites; aussi bien les plus anciens chefs de familles que leurs frères les plus jeunes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Et le roi David et les chefs de l’armée réglèrent les fonctions des fils d’Asaph, d’Hêman et d’Idithun, chantres, s’accompagnant de harpes, de lyres et de cymbales, et qui furent employés tour à tour, selon leur nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Fils d’Asaph, attachés à la personne du roi: Sacchur, Joseph, Natharias et Enahel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Fils d’Idithun: Godolias, Suri, Iséas, Asabias et Matthathias; six, en comptant leur père Idithun, s’accompagnant de la harpe, et louant le Seigneur en lui rendant grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Fils d’Hêman: Bucias, Matthanias, Oziel, Subahel, Jerimoth, Ananias, Anan, Eliatha, Godollathi, Rometthiézer, Jesbasaca, Mallithi, Otheri et Méasoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Tous fils d’Hêman, premier chantre du roi pour louer Dieu et exalter sa puissance. Ainsi, Dieu avait donné à Hêman quatorze fils, outre trois filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Tous ses fils chantaient avec lui dans le tabernacle de Dieu, en s’accompagnant de harpes, de lyres et de cymbales; ils servaient en la demeure de Dieu, attachés à la personne du roi, ainsi qu’Asaph, Idithun et Hêman.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Et leur nombre, joint à celui de leurs frères, instruits à chanter le Seigneur, montait à deux cent quatrevingt-huit, tout compris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Et ils réglèrent aussi, par le sort, leur service journalier, après qu’ils furent classés, selon leur plus ou moins de science et de talent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Et le sort désigna, en premier lieu: Godolias, fils de Joseph, fils d’Asaph, et ses fils et ses frères; le second fut Héneïa, et ses fils et ses frères, au nombre de douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Le troisième Sacchur, et ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Le quatrième Jesri, et ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Le cinquième Nathan, et ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Le sixième Bucias, et ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Le septième Izeriel, et ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Le huitième Josias, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Le neuvième Matthanias, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Le dixième Sémeï, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Le onzième Asriel, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Le douzième Asabia, ses fils et ses frères douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Le treizième Subahel, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Le quatorzième Matthathias, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Le quinzième Jerimoth, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Le seizième Anania, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Le dix-septième Jesbasaca, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Le dix-huitième Ananias, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Le dix-neuxième Mallithi, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Le vingtième Eliatha, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Le vingt — unième Otheri, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Le vingt-deuxième Godolathi, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Le vingt-troisième Muzoth, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Le vingt-quatrième Rometthiézer, ses fils et ses frères: douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Ceux à qui les portes furent distribuées, étaient les fils de Coré, Mosellamia, de la famille d’Asaph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Et les fils de Mosellamia: Zacharie le premier-né, Jadiel le second, Zabadie le troisième, Jénuel le quatrième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Jolam le cinquième, Jonathan le sixième, Elionaï le septième, Abdedom le huitième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Et les fils d’Abdedom: Samaïas le premier-né, Jozabath le second, Joath le troisième, Sachar le quatrième, Nathanaël le cinquième,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Amiel le sixième, Issachar le septième, Phelathi le huitième; car Dieu l’avait béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Et à son premier fils Samaïas, des fils naquirent, et furent chefs dans leur famille, parce qu’ils étaient forts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Fils de Samaï: Otbni, Raphaël, Obed, Elzabath, Achiud, tous hommes forts, Elia, Sabachias et Isbacom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Tous issus d’Abdedom; eux, et leurs fils et leurs frères, remplissant avec énergie leurs fonctions, au nombre de soixante-deux, issus d’Abdedom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Mosellemia avait dix-huit fils et frères, tous hommes forts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Et les fils d’Osa, issu de Mérari, et qui n’était pas le premier-né, commandaient ce service; son père lui donna le commandement de la deuxième division.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Helcias venait après lui, Tablé était le troisième, Zacharie le quatrième; les fils et les frères d’Osa étaient en tout: treize.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'C’est entre eux que furent partagées les portes; chefs énergiques, servant avec autant de zèle que leurs frères, employés dans l’intérieur du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Et ils tirèrent au sort les portes où ils devaient être placés, après qu’on les eut classés, selon leur plus ou moins de force, par familles paternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Le sort désigna, pour la porte orientale, Sélémie et Zacharie; ensuite, les fils de Soaz, issu de Melchia, agitèrent les sorts, et celui de la porte du nord sortit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Abdedom eut la porte du midi, en face de la maison d’Esephim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Osa eut la seconde porte du côté de l’orient, après celle qui mène au vestibule des degrés; un garde visà-vis l’autre garde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Il y avait chaque jour six hommes à la porte orientale, quatre à celle du nord, quatre à celle du midi et deux à Esephim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Sous le portique, et avec Oza, du côté du couchant, après la porte du vestibule, trois; toutes ces gardes se correspondaient: six à l’orient, quatre au nord, quatre au midi, deux sous le portique d’Esephim, quatre au couchant et deux à l’entrée du chemin, sous le portique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Les portes étaient ainsi distribuées entre les fils de Coré et ceux de Mérari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Et des lévites, leurs frères, gardaient le trésor de la demeure du Seigneur et le trésor des consécrations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Ceux-là étaient fils de Ladan; ils étaient issus des fils de Gerson; les chefs des familles provenaient de Ladan, le fils de Ladan le Gersonite était Jehiel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Zethom et Johel, son frère, fils de Jehiel, étaient intendants du trésor de la demeure du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Avec les familles d’Amram, d’Issaar, d’Hébron et d’Oziel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Subael, issu de Gersam, fils de Moïse, était aussi intendant des trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Or, Eliézer, l’un de ses proches, eut pour fils Rabias, de qui descendirent: Josias, Joram, Zéchri et Salomoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ce Salomoth et ses frères eurent l’intendance de tous les trésors saints, que consacrèrent le roi David et les chefs de familles paternelles, commandants de mille hommes, ou centeniers, ou princes de l’armée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'C’étaient les choses qu’ils avaient enlevées des villes prises sur l’ennemi, et consacrées pour subvenir aux frais de construction du temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Ainsi, tout ce qu’avait consacré Samuel le prophète; Saül, fils de Cis; Abner, fils de Ner; Joab, fils de Sarvia, fut confié à Salomoth et à ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Honnias, issu d’Isaar, et ses fils, furent chargés de fonctions extérieures en Israël; ils étaient scribes et juges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Asubias, issu d’Hébron, et ses frères, hommes forts, au nombre de dix-sept cents, avaient la surveillance d’Israël, sur la rive occidentale du Jourdain, pour tout ce qui concernait le service du Seigneur et le gouvernement du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Urie était le chef de la postérité d’Hébron, par familles paternelles; or, la quarantième année du règne de David, elle fut recensée en Jazer-Galaad, et Urie fut reconnu vaillant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Ses frères, les chefs de famille, au nombre de deux mille sept cents, étaient aussi des hommes forts; le roi les institua intendants de Ruben, de Gad et de la demi-tribu de Manassé, pour tout ce qui concernait les commandements du Seigneur et les ordres du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Et, pendant le cours de l’année, de mois en mois, une division de vingt-quatre mille hommes, prise parmi tous les fils d’Israël, chefs de familles, commandants de mille hommes, centeniers, scribes et serviteurs, était employée à exécuter les ordres du roi; chaque division était relevée à son tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'A la tête de la première division employée le premier mois était Isboaz, fils de Zabdiel; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Il était issu de Pharès, et comme chef de tous les chefs de l’armée, il commandait pendant le premier mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'A la tête de la division du second mois était Dodia, fils d’Eccoc, et il y avait encore pour chef de cette division Maceloth; ils étaient chefs de vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Banaïas, fils de Joad le prêtre, était le troisième chef, il commandait la division du troisième mois, pareillement vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ce Banaïas était le plus vaillant des trente; il était à leur tête, et son fils Zabad commandait avec lui sa division.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Le quatrième, celui du quatrième mois, était Asaël, frère de Joab, et son fils Zabadie; ses fils et ses frères partageaient son commandement sur vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Le cinquième chef, celui du cinquième mois, était Samaoth le Jezraïte; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Le sixième, celui du sixième mois, était Oduïas, fils d’Eccès de Thécoé; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Le septième, celui du septième mois, était Hellès de Phallus, des fils d’Ephraïm; sa division comptait vingtquatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Le huitième, celui du huitième mois, était Sobochaï de Husathi, issu de Zara; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Le neuvième, celui du neuvième mois, était Abiézer d’Anathoth, de la terre de Benjamin; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Le dixième, celui du dixième mois, était Méhéra de Netophathi, issu de Zara; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Le onzième, celui du onzième mois, était Banaïas de Pharathon, des fils d’Ephraim; il commandait vingt-quatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Le douzième, celui du douzième mois, était Holdia de Netophathi, issu d’Othoniel; il commandait vingtquatre mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Et il y avait des chefs à la tête de chaque tribu; celui de Ruben était Eliézer, fils de Zéchri; celui de Siméon, Saphatias, fils de Maacha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Celui de Lévi, Asabias, fils de Camuel; Sadoc était chef de la famille d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Le chef de Juda était Eliab, l’un des frères de David; celui d’Issachar: Ambri, fils de Michel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Celui de Zabulon, Samaïas, fils d’Abdiu; celui de Nephthali Jerimoth, fils d’Oziel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Celui d’Ephraïm, Osé, fils d’Oziu; celui de la demi-tribu de Manassé: Johel, fils de Phadaïa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Celui de l’autre demi-tribu de Manassé, en Galaad, Jadaï, fils de Zadaïu; celui de Benjamin, Jasiel, fils d’Abner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Celui de Dan: Azariel, fils de Iroab; tels étaient les chefs de familles des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Et David ne fit point le dénombrement de ceux de vingt ans et au-dessous, car le Seigneur lui avait dit qu’il multiplierait Israël comme les étoiles du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Et Joab, fils de Sarvia, avait commencé le dénombrement du peuple, mais il ne l’acheva point; et ce dénombrement causa la colère qui éclata contre Israël, et le nombre que l’on avait trouvé fut supprimé du livre des faits et gestes du roi David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Asmoth, fils d’Adaël, fut trésorier du roi, et Jonathas, fils d’Ozia, trésorier de la contrée, des villes, des villages et des tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Esdri, fils d’Hélab, avait l’intendance des laboureurs et ouvriers travaillant à la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Semeï de Rahel, celle des champs; Zabni, fils de Jephni, celle des vignes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Balanan le Gedorite, celle des oliviers et des figuiers des champs; Joas, celle de l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Satraï le Saronite, celle des boeufs qui paissaient en Saron; et Sophat, fils d’Abdi, celle des bœufs à l’étable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Abias, l’Ismaélite, celle des chameaux; Jadias de Merathon, celle des ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Jaziz l’Agarite, celle des brebis. Tels étaient tous les intendants des domaines du roi David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonathas, oncle paternel de David, était conseiller, homme intelligent; et Jehel, fils d’Achami, était avec les fils du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitophel était conseiller du roi, et Chusi (Chusaï) son principal favori.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Après lui venaient Achitophel, Joad, fils de Banaïas et Abiathar. Joab était le général en chef du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Et David rassembla en Jérusalem tous les chefs d’Israël, les chefs des juges, tous les chefs des gardes qui tour à tour veillaient à la personne du roi, les commandants de mille hommes, les centeniers, les trésoriers, les intendants de ses domaines, ceux des troupeaux du roi, les gouverneurs de ses fils, les eunuques, les vaillants et les guerriers de l’armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Et David se plaça au milieu de l’assemblée, et il dit: Écoutez-moi, mes frères et mon peuple: J’ai eu le dessein de bâtir une maison de repos, pour l’arche de l’alliance un lieu du Seigneur, où notre Seigneur arrête ses pas; j’ai préparé ce qui convient pour cette construction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mais Dieu a dit: Tu ne bâtiras pas un temple où mon nom soit invoqué, parce que tu es un homme de guerre, et que tu as versé le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Le Seigneur Dieu d’Israël m’a choisi dans la maison de mon père pour être à jamais roi d’Israël, et il a choisi Juda pour sa tribu royale; dans Juda il a choisi la maison de mon père; et, parmi les fils de mon père, il a voulu que je fusse roi de tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Et, parmi tous mes fils, car le Seigneur m’en a accordé un grand nombre, il a choisi Salomon, mon fils, pour l’asseoir sur le trône du royaume du Seigneur, et pour qu’il soit roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Et Dieu m’a dit: Salomon, ton fils, bâtira mon parvis et mon temple; car je l’ai choisi pour qu’il soit mon fils, et je serai pour lui un père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Et je maintiendrai, dans tous les siècles, son royaume, s’il observe sans faiblir, comme il les observe maintenant, mes commandements et mes préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Je vous recommande donc en présence de toute l’Église du Seigneur, et devant notre Dieu qui nous entend, d’observer et d’aimer tous les commandements du Seigneur notre Dieu, afin que vous possédiez cette terre féconde, et que vous en transmettiez l’héritage à vos fils pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Et toi, Salomon, mon fils, reconnais le Dieu de tes pères, sers-le d’un cœur pur et d’une âme ferme, car le Seigneur sonde tous les cœurs et il connaît toutes les pensées. Si tu le cherches tu le trouveras, et si tu l’abandonnes il t’abandonnera pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Vois aujourd’hui que le Seigneur t’a choisi pour que tu lui bâtisses une maison où sera son sanctuaire; sois fort et agis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Ensuite, David donna à Salomon, son fils, le modèle du temple, de ses constructions, de ses trésors, de ses chambres hautes, des logements intérieurs et du propitiatoire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Et le plan, qu’il avait eu en l’esprit, du parvis du temple du Seigneur, de tous les vestibules d’alentour communiquant aux trésors, des trésors, des choses saintes et des chambres secrètes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Et le réglement du service journalier des prêtres et des lévites, pour toutes leurs œuvres liturgiques dans le temple du Seigneur, et des trésors où seraient déposés les vases liturgiques employés aux cérémonies du culte dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Et il donna le poids des vases d’or et d’argent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Des lampes et des chandeliers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Il donna pareillement le poids des tables de proposition, de chaque table d’or, et de chaque table d’argent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Et des fourchettes, et des coupes à libations, et des fioles d’or, et des encensoirs, et d’autres objets d’or et d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Il lui montra aussi le poids, en or pur, de toutes les parties de l’autel des parfums, et le modèle du char des deux chérubins aux ailes déployées, qui devaient ombrager l’arche de l’alliance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'David donna tout cela à Salomon en écriture de la main du Seigneur, avec la sagesse dont il fut assisté pour réaliser le modèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Et David dit à Salomon, son fils: Sois fort, agis en homme, exécute, n’aie ni crainte, ni faiblesse; car le Seigneur Dieu est avec toi; il ne te négligera pas, il ne t’abandonnera point que tu n’aies terminé toute l’œuvre destinée au service de son temple. Voici le modèle de sa nef et de son temple, de son trésor, des chambres hautes, des logements intérieurs et du propitiatoire; voici le plan du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Voici encore l’ordre des fonctions journalières des prêtres et des lévites, dans tout le service du temple du Seigneur; et tu seras assisté en ton œuvre par chaque homme zélé et habile en quelque art, et les princes et tout le peuple exécuteront tous tes commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Et le roi David dit à toute l’Église: Mon fils Salomon, en qui le Seigneur s’est complu, est jeune et délicat, et l’œuvre est grande, car elle n’est point pour l’homme, mais pour le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Autant que je l’ai pu, j’ai préparé pour le temple de mon Dieu de l’or, de l’argent, de l’airain, du fer, des bois, des pierres d’onyx, quantité de pierres chères et variées, toutes sortes de pierres précieuses, et beaucoup de marbre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'De plus, comme je mets ma joie en la demeure de mon Dieu, j’ai conservé l’or et l’argent que je me suis procuré pour moi-même; je le donne entièrement au temple de mon Dieu, outre ce que j’ai amassé pour la maison des choses saintes, savoir:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Trois mille talents d’or d’Ophir, et sept mille talents d’argent pur, pour que l’on en recouvre les murs du lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'L’or ne manquera pas pour ce qui doit être fait avec de l’or, ni l’argent pour ce qui doit être fait avec de l’argent, à chaque œuvre, il y aura ce qu’il faut à la main de l’artisan. Mais est-il quelqu’un qui désire aujourd’hui remplir ses mains pour le Seignenr?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Et les princes des familles le désirèrent, les princes des fils d’Israël ainsi que les commandants de mille hommes, et les centeniers, et les intendants des travaux, et les architectes du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Et ils donnèrent pour les travaux du temple du Seigneur cinq mille talents et dix mille sicles d’or; dix mille talents d’argent; dix-huit mille talents d’airain et cent mille talents de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Et celui chez qui il se trouva quelque pierre précieuse, la donna pour le trésor du temple par les mains de Jehiel, de la famille de Gerson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Et le peuple eut une grande joie à cause de ce zèle, car chacun eut ce zèle pour Dieu de plein cœur. Et le roi David fut comblé de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Et le roi David bénit le Seigneur devant toute l’Église, disant Béni soyez-vous, Seigneur Dieu d’Israël, ô notre Père, dans tous les siècles des siècles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'À vous, Seigneur, la magnificence, la force, la gloire, la victoire et la puissance; car vous êtes le maître de toutes les choses qui sont sur la terre et dans les cieux. Tous les rois des nations sont troublés devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'De vous viennent gloire et richesse; vous régnez sur toutes choses, ô Seigneur, prince de toutes les dominations; la force et le pouvoir résident en vos mains, et il dépend de vous, ô Tout-Puissant, de grandir et de fortifier toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Et maintenant, Seigneur, nous vous rendons hommage, nous louons votre nom et votre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Et qui suis-je, moi, et qui est mon peuple, pour que nous avons pu vous faire ces offrandes avec tant de zèle? Tout est à vous, et nous vous avons donné de ce qui vous appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Car nous sommes des passagers devant vous, et nous passons comme tous nos pères; nos jours sur la terre sont comme l’ombre, et rien n’a de la durée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Seigneur notre Dieu, toutes les richesses que j’ai préparées pour bâtir un temple à votre saint nom, viennent de vous; tout cela vous appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Et j’ai reconnu, ô mon Dieu, que c’est vous qui sondez les cœurs et que vous aimez la justice; et je vous ai fait mes offrandes dans la simplicité de mon cœur, et je viens de voir ici avec joie ce peuple mettre tant de zèle à vous faire ses offrandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Seigneur Dieu d’Abraham, d’Isaac et d’Israël nos pères, faites que votre peuple conserve toujours en son cœur le même amour, et dirigez son cœur vers vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Et donnez à mon fils Salomon un bon cœur pour exécuter vos commandements, pour être attentif à vos ordres et à vos témoignages, et pour conduire jusqu’à la fin la construction de votre temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Et David dit à toute l’Église: Bénissez le Seigneur notre Dieu. Et toute l’Église bénit le Seigneur Dieu de leurs pères; ils plièrent les genoux et ils adorèrent le Seigneur et le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Et David sacrifia au Seigneur; il offrit en holocauste à Dieu, dès le matin du jour suivant: mille bœufs, mille béliers, mille agneaux; il fit leurs libations, et il distribua des victimes en abondance à tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Et ils mangèrent, et ils burent avec joie devant le Seigneur toute la journée, et, pour la seconde fois, ils proclamèrent roi Salomon, fils de David; ils le sacrèrent roi devant le Seigneur, et ils sacrèrent Sadoc comme pontife.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Et Salomon s’assit sur le trône de David son père; il fut honoré, et tout Israël lui obéit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Les princes, les vaillants, et tous les fils du roi David son père, se soumirent à sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Et le Seigneur éleva Salomon au-dessus de tout Israël, il lui donna plus de gloire qu’à nul des rois qui l’avaient devancé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Or, David, fils de Jessé, avait régné sur Israël');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Quarante ans: sept à Hébron, trente-trois à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Et il finit en une heureuse vieillesse, plein de jours, de richesses et de gloire, et son fils Salomon régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Le reste des discours du roi David, ses premières et ses dernières paroles, sont écrits parmi les Récits de Samuel le voyant, de Nathan le prophète, et de Gad le voyant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Concernant tout son règne, ses guerres et les événements arrivés tant à lui qu’à Israël, et en tous les royaumes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Et Salomon, fils de David, s’affermit sur son trône; le Seigneur Dieu était avec lui, et il l’éleva au comble des grandeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Et Salomon parla à tout Israël, aux commandants de mille hommes, aux centeniers, aux juges, à tous les princes d’Israël et aux princes de sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Et il alla avec toute l’Église au lieu haut de Gabaon, où était le tabernacle du témoignage de Dieu, que Moïse serviteur de Dieu avait fait dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Quant à l’arche de Dieu, David l’avait retirée de Cariathiarim, parce qu’il lui avait préparé et dressé un tabernacle à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Mais l’autel d’airain qu’avait fait Béséléel, fils d’Urias, fils de Hur, était à Gabaon devant le tabernacle du Seigneur, et c’est là que Salomon avec toute l’Église alla interroger Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Et Salomon sacrifia sur l’autel d’airain devant le tabernacle du Seigneur; il y offrit un holocauste de mille victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'En cette nuit-là, le Seigneur apparut à Salomon, et il lui dit: Demande ce que tu veux que je te donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Et Salomon dit à Dieu: Vous avez usé d’une grande miséricorde envers David, mon père, et vous m’avez fait roi à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Et maintenant, Seigneur Dieu, que votre nom soit engagé en faveur de David, mon père. Car, vous m’avez proclamé roi d’un peuple aussi nombreux que la poussière des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Donnez-moi la sagesse et l’intelligence, pour que je puisse bien agir devant ce peuple; car, qui jugera votre grand peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Et Dieu dit à Salomon: En récompense de ce que cela était en ton cœur, et que tu ne m’as demandé ni richesses, ni gloire, ni la mort de tes ennemis, ni de longs jours, mais que tu m’as demandé la sagesse et l’intelligence, afin de juger mon peuple sur qui je t’ai établi roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Je te donne la sagesse et l’intelligence, et je te donnerai la richesse et la gloire, tellement que ton pareil n’a pas existé parmi les rois qui t’ont devancé, et n’existera pas parmi ceux qui te succèderont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Et Salomon s’en alla du haut lieu de Gabaon où était le tabernacle du témoignage, pour retourner à Jérusalem, et il régna sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Ensuite, Salomon rassembla ses chars et ses cavaliers; il eut quatorze cents chars et douze mille cavaliers; il laissa les chars dans les villes, mais la troupe demeura avec le roi à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Et le roi rendit à Jérusalem l’argent et l’or aussi communs que les pierres, et les cèdres en Judée aussi nombreux que les mûriers dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Salomon tirait des chevaux de l’Egypte; des marchands partaient par ses ordres, ayant été chargés de les lui acheter,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Et ils revenaient, et ils ramenaient de l’Égypte: un char moyennant six cents sicles d’argent; un cheval moyennant cent cinquante sicles. Et il en était de même pour ce qu’ils achetaient des rois des Hettéens ou de la Syrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Et Salomon ordonna que l’on bâtit un temple au nom du Seigneur; puis, pour lui-même, une demeure royale,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Il réunit soixante-dix mille manœuvres, quatre-vingt mille tailleurs de pierres qu’il envoya dans la montagne, et trois mille six cents conducteurs de leurs travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Il dépêcha des messagers à Hiram, roi de Tyr, disant: Tu en as bien usé avec David, mon père, tu lui as envoyé des cèdres pour bâtir le palais qu’il devait habiter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Or, voici que moi son fils, je bâtis un temple au nom du Seigneur mon Dieu, pour le lui consacrer, pour y brûler devant lui de l’encens, pour y exposer toujours les pains de proposition, pour y offrir les holocaustes du matin et du soir, ceux des sabbats, des nouvelles lunes, et des fêtes du Seigneur notre Dieu à perpétuité en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Le temple que je bâtis sera grand, parce que le Seigneur notre Dieu est grand plus que tous les dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Mais, qui donc peut lui élever un temple? Car le ciel et le ciel des cieux ne contiennent pas sa gloire. Et moi, qui suis-je pour lui bâtir un temple,’ si ce n’est seulement pour sacrifier devant lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Envoie-moi donc un homme adroit et instruit à façonner l’or, l’argent, l’airain, le fer, le porphyre, l’hyacinthe et l’écarlate; et quelqu’un sachant sculpter et ciseler, avec les gens habiles que j’ai auprès de moi à Jérusalem, et qu’a formés David mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Envoie-moi aussi des bois de cèdre, de genièvre et de pin du Liban, car je n’ignore pas comment tes serviteurs savent équarrir les arbres du Liban. Et tes serviteurs, avec les miens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Iront me préparer de la charpente en quantité, parce que la maison que je bâtis sera grande et magnifique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'A tes serviteurs les charpentiers, je donne gratuitement pour leur nourriture: vingt mille mesures de froment, vingt mille mesures d’orge, vingt mille mesures de vin, et vingt mille mesures d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Hiram, roi de Tyr, répondit par écrit, et il fit passer sa lettre à Salomon, disant: Le Seigneur aime ton peuple, c’est pourquoi il t’a fait régner sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Et Hiram ajouta: Béni soit le Seigneur Dieu d’Israël, qui a créé le ciel et la terre, qui a donné à David un fils sage, plein de savoir et d’intelligence; c’est ce fils qui bâtira le temple du Seigneur et son propre palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Et moi je t’envoie un homme intelligent et habile, Hiram, mon serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Sa mère est des filles de Dan, et son père un Tyrien; il sait façonner l’or, l’argent, l’airain, le fer, les pierres et le bois; il sait tisser avec le porphyre, l’hyacinthe, le lin et l’écarlate; il sait sculpter et ciseler; il n’est rien qu’il ne sache inventer; il exécutera tout ce que tu lui commanderas, aidé de tes hommes habiles, et des hommes habiles de mon seigneur David, ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Quant aux vivres, à l’orge, à l’huile, au vin dont a parlé mon seigneur, qu’il les envoie à ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Et nous, nous équarrirons des arbres du Liban, autant qu’il en faudra; nous en ferons des radeaux que nous conduirons par mer à Joppé, et tu les transporteras à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Alors, Salomon réunit tous les étrangers qui habitaient la terre d’Israël, après le dénombrement qu’avait fait son père David; or, il s’en trouvait cent cinquante-trois mille six cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Parmi eux, il prit soixante-dix mille manœuvres, quatre-vingt mille tailleurs de pierres, et trois mille six cents conducteurs des travaux, pour diriger cette multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Et Salomon commença à bâtir le temple du Seigneur à Jérusalem, sur le mont Moria, où le Seigneur était apparu à David, son père, au lieu que David avait préparé, dans l’aire d’Orna le Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Il commença à bâtir le second mois de la quatrième année de son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Et voici comme Salomon commença à bâtir le temple du Seigneur: il lui donna soixante coudées de longueur (ce fut la première mesure), et vingt coudées de largeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Le portique de la façade du temple eut vingt coudées de long; c’était la largeur même de l’édifice; sa hauteur fut de cent vingt coudées; Hiram le dora avec de l’or pur, intérieurement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Et il revêtit de lambris de cèdre le corps de l’édifice, et il le dora d’or pur, sur lequel il grava des palmiers et des chaînes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Et il orna le temple de pierres précieuses d’un vif éclat, et il le couvrit de lames d’or, et il y employa de l’or de Pharaïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Et il dora le temple, ses murs, ses portes, ses plafonds, les battants des portes, et il fit sur les parois des chérubins ciselés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Et il fit le Saint des saints, dont la façade avait vingt coudées de long, largeur du temple et dont les côtés étaient pareillement de vingt coudées; il le dora d’or pur du poids de six cents talents; pour les chérubins ciselés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Les clous pesaient chacun cinquante sicles d’or; il revêtit aussi d’or l’étage supérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Puis, il fit, dans le Saint des saints, deux chérubins de bois qu’il revêtit de lames d’or pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Les ailes des chérubins avaient un déploiement de vingt coudées; chaque aile était de cinq coudées, de sorte que l’aile droite de l’un des chérubins touchait un mur, et l’aile gauche de l’autre chérubin touchait le mur opposé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Les ailes des deux chérubins étaient donc déployées, et il y avait entre les deux ailes extrêmes une distance de vingt coudées. Ils étaient en pied, le visage tourné vers l’intérieur du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Il fit aussi un voile d’hyacinthe, de pourpre, d’écarlate et de lin, dans lequel étaient tissus des chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Et il fit, devant le temple, deux colonnes, hautes de trente-cinq coudées, avec des chapiteaux de cinq coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Et il fit des chaînes dans l’oracle, et il les plaça sur les chapiteaux des colonnes, et il fit cent petites grenades qu’il posa sur les chaînes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Et il plaça les colonnes sur la façade du temple, l’une à droite, l’autre à gauche, et il appela celle de droite Rectitude, et celle de gauche Force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Et il fit un autel d’airain, long de vingt coudées, large de vingt, haut de dix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Et il fit une mer, jetée en fonte, ronde, haute de cinq coudées, ayant dix coudées de diamètre, et trente coudées de circonférence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Il y avait, au-dessous de ses bords tout alentour, des figures de bœufs, et la piscine avait dix coudées de tour; on avait jeté en fonte deux espèces de bœufs, en deux sortes de moules,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Où on avait fait douze bœufs trois regardant le nord, trois l’occident, trois le midi, trois l’orient; la mer était posée sur eux, et le derrière de leur corps était caché par elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Elle avait un palme d’épaisseur, et ses bords étaient comme ceux d’une coupe, et ciselés de fleurs de lis; elle contenait trois mille mesures; il l’acheva,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Et il fit dix bassins: il en plaça cinq à droite et cinq à gauche, pour qu’on y lavât la matière des holocaustes; quant aux prêtres, ils se lavaient dans la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Et il fit dix chandeliers d’or, selon le modèle, et il les plaça dans la nef: cinq à droite, cinq à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Et il fit dix tables, et il les plaça dans la nef: cinq à droite, cinq à gauche; et il fit cent fioles d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Il fit aussi le parvis des prêtres, le grand parvis, les portes du parvis, et il revêtit d’airain leurs panneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Il plaça la mer du côté droit du temple, vers l’angle regardant l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Et Hiram fit les fourchettes, les poêles, la grille de l’autel et tous ses vases; et il acheva tous les travaux que lui avait commandés le roi Salomon pour le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Il fit deux colonnes, et, sur leurs têtes, des cordons aux chapiteaux, et deux filets pour couvrir les deux chapiteaux des têtes de ces colonnes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Et quatre cents clochettes d’or dans les deux filets, et deux sortes de grenades dans chaque filet, pour couvrir les deux chapiteaux des têtes de colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Et il fit dix bassins, et il fit les cuvettes pour les bassins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Et la mer, et les douze bœufs qui la supportent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Et les vases pour les pieds, les seaux, les marmites, les crochets, et les autres vases qui lui étaient commandés; il les fit en airain pur, et il les apporta au roi dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Le roi les avait jetés en fonte, dans la vallée du Jourdain, en une terre argileuse de la maison de Soccoth, entre cette ville et Saredatha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Et Salomon fit tous ces ustensiles à profusion, car l’airain ne put être épuisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Et il fit tous les vaisseaux du temple du Seigneur, l’autel d’or, les tables de proposition,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Les chandeliers et les lampes en or pur, qui devaient éclairer la façade de l’oracle, selon son plan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Il fit leurs mouchettes, leurs récipients, les coupes, les réchauds et les encensoirs, d’or pur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Et la porte intérieure du temple qui mène au Saint des saints, et les portes d’or du temple. Enfin, tous les travaux qu’avait commandés Salomon pour le temple du Seigneur, furent achevés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Et Salomon transporta dans le trésor du temple les choses saintes de David son père, et l’argent et l’or, et les vaisseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Alors, Salomon assembla dans Jérusalem tous les anciens du peuple, tous les princes des tribus, les princes des familles paternelles d’Israël, pour transférer de Sion (la même que la ville de David) l’arche de l’alliance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Et tout Israël fut assemblé devant le roi Salomon, pendant la fête, le septième mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Tous les anciens d’Israël y étaient venus; les lévites prirent l’arche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Le tabernacle du témoignage, et toutes les choses saintes que contenait le tabernacle; puis, les prêtres et les lévites le transportèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Or, le roi Salomon, toute la synagogue d’Israël, les hommes craignant Dieu, tous ceux d’entre eux qui étaient là rassemblés devant l’arche, sacrifiaient des bœufs et des brebis en quantité innombrable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Et les prêtres introduisirent l’arche de l’alliance du Seigneur au lieu qui lui était destiné dans l’oracle du temple, dans le Saint des saints, sous les ailes des chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Et les chérubins avaient les ailes déployées au-dessus du lieu où on mit l’arche, et les chérubins couvraient l’arche et les leviers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Mais les leviers faisaient saillie; et, de l’intérieur du Saint des saints, on en voyait la tête en s’adossant à la façade de l’oracle; du dehors on ne les voyait pas: et ils sont restés là jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Il n’y avait rien dans l’arche, sinon les deux tables que Moïse y avait déposées en Horeb; témoignage de l’alliance du Seigneur avec les fils d’Israël, quand il les eut fait sortir de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Et, au moment où les prêtres sortirent du sanctuaire (car tous avaient été consacrés, et ils n’étaient point divisés encore par ordre journalier de service),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Et, avec eux, les lévites, chanteurs de psaumes, tous subordonnés à Asaph, à Hêman, à Idithun, à leurs fils et à leurs frères, revêtus de robes de lin, portant des cymbales, des lyres, des harpes, se tenant en face de l’autel, et, avec eux, cent vingt prêtres sonnant de la trompette,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Les trompettes, les harpes et les chants se réunirent en une seule harmonie pour louer d’une seule voix et célébrer le Seigneur. Et les voix s’élevaient accompagnées des trompettes, des cymbales et des instruments des chanteurs, et elles disaient Rendez hommage à Dieu, parce qu’il est bon, et que sa miséricorde est éternelle. Alors, le temple fut rempli d’une nuée de gloire du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Et les prêtres ne purent y demeurer ni faire le service divin, à cause de la nuée; car la gloire du Seigneur avait rempli le temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Et Salomon s’écria: Le Seigneur avait dit qu’il habiterait dans le nuage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Et moi, Seigneur, j’ai construit à votre saint nom un temple, préparé pour vous abriter à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Puis, le roi se retourna, et il bénit toute l’Église d’Israël, et toute l’Église d’Israël était debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Et il ajouta: Béni soit le Seigneur Dieu d’Israël, qui, de sa bouche, a parlé, concernant David, mon père; et qui, de ses mains, a rempli ses promesses; il avait dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Depuis le jour où j’ai tiré mon peuple de l’Égypte, je n’avais point choisi de ville, parmi toutes les tribus d’Israël, pour qu’on bâtît un temple ou résidât mon nom; je n’avais point fait choix d’un homme qui fût le chef de mon peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Depuis, j’ai choisi Jérusalem pour que mon nom y réside, et j’ai choisi David pour qu’il soit sur mon peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Or, mon père avait en son cœur la pensée de bâtir un temple au nom du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Et le Seigneur dit à David, mon père: La pensée est venue en ton cœur de bâtir un temple à mon nom; il est bon qu’elle soit venue à ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Néanmoins, tu ne bâtiras point ce temple: c’est le fils issu de tes entrailles qui le bâtira à mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Le Seigneur a relevé la parole qu’il avait dite; j’ai été suscité à la place de David, mon père, et je me suis assis sur le trône d’Israël, comme l’avait dit le Seigneur, et j’ai bâti un temple au nom du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Et j’ai placé l’arche qui renferme l’alliance que le Seigneur a faite avec Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Ensuite, Salomon se tint devant l’autel du Seigneur et devant toute l’Église d’Israël, et il étendit les mains;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Car il avait fait un piédestal d’airain qu’il avait placé au milieu du parvis du grand prêtre; ce piédestal avait cinq coudées de long, sur cinq de large, et trois de haut; or, le roi y était monté, et il se mit à genoux devant toute l’Église d’Israël, et il étendit les mains vers le ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Et il dit: Seigneur Dieu d’Israël, il n’est point au ciel et sur la terre de Dieu tel que vous, gardant alliance et miséricorde pour vos serviteurs qui marchent de toute leur âme devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Ce que vous avez réservé à votre serviteur David, ce que vous lui avez promis, ce que vous lui avez dit de votre bouche, vous l’avez exécuté de vos mains, comme il se voit aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Maintenant, Seigneur Dieu d’Israël, gardez pour votre serviteur David, mon père, cette parole que vous lui avez dite: Il ne manquera jamais d’hommes de ton sang pour être assis sur le trône d’Israël, devant ma face, pourvu que tes enfants observent leurs voies, et qu’ils marchent, à mes yeux, comme toi-même as marché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Maintenant, Seigneur Dieu d’Israël, que votre promesse à David, mon père, votre serviteur, soit confirmée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Est-il donc croyable que Dieu réside sur la terre parmi les hommes? Si le ciel et le ciel des cieux ne peuvent vous contenir, comment ce temple, que j’ai bâti à votre nom, vous contiendrait-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'O Seigneur Dieu d’Israël, considérez la demande et la prière de votre serviteur, pour exaucer la demande et la prière que fait aujourd’hui devant vous votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Que vos yeux soient ouverts nuit et jour sur ce temple, sur ce lieu dont vous avez dit que votre nom y serait invoqué; accueillez la prière que vous fait en ce lieu votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Oui, vous écouterez la prière de votre serviteur et de votre peuple Israël, toutes les fois qu’ils prieront dans ce lieu; vous les entendrez du lieu que vous habitez au ciel, et vous les exaucerez, et vous leur serez propice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Si un homme a péché contre son prochain, et que celui-ci prête serment contre lui et qu’il lui défère le serment, et que le premier vienne jurer dans ce temple devant votre autel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Vous l’entendrez du haut du ciel, et vous agirez, et vous jugerez vos serviteurs, pour rétribuer l’inique et faire retomber ses mauvaises voies sur sa tête; pour justifier le juste et le rétribuer selon son équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Et si votre peuple Israël est frappé par son ennemi; s’ils ont péché contre vous, et qu’ils se convertissent, qu’ils rendent hommage à votre nom, qu’ils prient et supplient devant vous en ce temple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Vous les entendrez du haut du ciel, et vous serez miséricordieux pour les péchés de votre peuple Israël, et vous les ramènerez dans la terre que vous avez donnée à eux et à leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Lorsque vous aurez fermé le ciel et qu’il n’y aura plus de pluie, parce qu’ils auront péché contre vous, ils prieront en ce lieu, et ils rendront gloire à votre nom, et ils feront pénitence de leurs péchés, après que vous les aurez humiliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Et vous les entendrez du haut du ciel, et vous serez miséricordieux pour les péchés de vos serviteurs et de votre peuple Israël; car vous leur aurez montré la bonne voie qu’ils doivent suivre, et vous accorderez de la pluie à la terre que vous avez donnée en héritage à votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Lorsqu’il y aura en la terre: famine, mortalité, vents pestilentiels, jaunisse, sauterelles; lorsqu’un ennemi aura opprimé votre peuple devant ses villes; dans toutes nos plaies et nos peines,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Toute prière, toute supplication, que vous feront dans ce temple, les mains étendues, soit un homme, soit le peuple entier d’Israël, vous l’exaucerez. Si quelqu’un reconnaît sa faute et sa plaie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Vous l’écouterez du haut du ciel, du lieu où est votre demeure; vous serez miséricordieux, et vous rétribuerez chacun selon sa voie, selon ce que vous aurez vu dans son cœur, car vous seul connaissez le cœur des fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Ainsi, auront-ils crainte de toutes vos voies, tout le temps qu’ils vivront en la terre que vous avez donnée à nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Et tout étranger qui n’est point de votre peuple Israël, et qui viendra d’une contrée lointaine, à cause de votre grand nom, de votre forte main et de votre bras tout-puissant, entrera aussi et priera dans ce temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Et vous l’entendrez du haut du ciel, du lieu où est votre demeure; vous agirez selon la prière de l’étranger qui vous aura invoqué, afin que tous les peuples connaissent votre nom, et qu’ils aient crainte de vous, comme le peuple d’Israël, et qu’ils sachent que votre nom est invoqué dans ce temple que j’ai bâti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Si votre peuple va en guerre contre ses ennemis, en suivant la voie où vous l’aurez envoyé, et s’il invoque le nom du Seigneur, tourné vers la ville que vous vous êtes choisie, et vers le temple que j’ai bâti à votre nom,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Vous entendrez du haut du ciel sa demande et sa prière, et vous rendrez sur lui votre jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Ils pécheront contre vous, car il n’est point d’homme qui ne pèche; vous les frapperez, vous les livrerez à des ennemis qui les emmèneront captifs en leur terre voisine ou lointaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Et en la terre où ils auront été transportés, ils convertiront leurs cœurs, et ils se repentiront, et ils prieront dans leur captivité, disant: Nous avons péché, nous avons été déréglés et iniques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'Et ils reviendront à vous de tout leur cœur, de toute leur âme, en la contrée de ceux qui les auront pris, et où ils seront retenus captifs, et ils vous prieront, tournés vers la terre que vous avez donnée à leurs pères, vers la ville que vous vous êtes choisie, vers ce temple que j’ai bâti au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Et vous entendrez du haut du ciel, du lieu de votre demeure, leur demande et leur prière; vous les jugerez, et vous serez miséricordieux envers ce peuple qui aura péché contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Et maintenant, Seigneur, ouvrez les yeux, prêtez une oreille attentive à la prière que je fais en ce temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Levez-vous, ô Seigneur mon Dieu, pour entrer dans ce lieu de repos avec l’arche de votre force; que vos prêtres se revêtent du salut, et que vos enfants se réjouissent de vos biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Seigneur Dieu, ne vous détournez pas de votre christ; souvenez-vous de votre miséricorde envers David, votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Aussitôt que Salomon eut achevé sa prière, le feu du ciel descendit et dévora les holocaustes, et la gloire du Seigneur remplit le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Et, à ce moment-là, les prêtres ne purent entrer dans le temple, parce qu’il était rempli de la gloire du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Et tous les fils d’Israël virent le feu descendre, et la gloire du Seigneur remplir l’édifice, et ils tombèrent la face sur le pavé du temple, et ils adorèrent le Seigneur, et ils le louèrent, à cause de sa bonté et de sa miséricorde infinies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Ensuite, le roi et tout le peuple immolèrent des victimes devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Et le roi Salomon offrit en sacrifice vingt-deux mille bœufs, et cent vingt mille têtes de menu bétail; le roi et tout le peuple firent ainsi la dédicace du temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Et les prêtres, chacun à son poste, et les lévites, avec les instruments et les chants du roi David, rendaient gloire au Seigneur et à sa miséricorde éternelle; devant eux, des prêtres sonnaient de la trompette, et tout le peuple se tenait debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Et Salomon consacra le milieu du parvis du temple, car c’est là qu’il offrit les holocaustes et qu’il brûla la graisse des hosties pacifiques; car l’autel d’airain, qu’avait fait Salomon, ne suffisait pas à contenir les holocaustes, les oblations et la graisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Et le roi Salomon, en ce même temps-là, fit une fête de sept jours; avec lui était Israël, grande assemblée venue depuis l’entrée d’Emath jusqu’au fleuve d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Et le huitième jour il sanctifia la fin de la fête, parce que la fête de la Dédicace de l’autel avait duré sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Et le vingt-troisième jour du septième mois, il renvoya le peuple, chacun en sa demeure, la joie dans le cœur, pénétré des biens que le Seigneur avait accordés à David, à Salomon et à Israël, son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Or, Salomon avait achevé le temple du Seigneur, et son propre palais; et tout ce qu’en son âme il avait désiré faire dans le temple et dans le palais, il l’avait heureusement accompli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Et le Seigneur lui apparut pendant la nuit, et il dit: J’ai entendu ta prière; je me suis choisi ce lieu pour qu’il y eût un temple où l’on me sacrifiât.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Si je ferme le ciel et qu’il n’y ait point de pluie; si je commande aux sauterelles de dévorer vos arbres; si j’envoie la peste à mon peuple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Et si mon peuple, pour qui mon nom est invoqué, rentre en soi-même, s’il prie, s’il désire ma présence, s’il se détourne de la mauvaise voie, je l’entendrai du haut du ciel; je serai miséricordieux pour ses péchés, et je guérirai sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Et mes yeux seront ouverts, et mes oreilles seront attentives à la prière qui sera faite en ce temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Car j’ai choisi et sanctifié cette demeure pour que mon nom y réside éternellement, et mes yeux et mon cœur y seront dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Et, si tu marches devant moi comme ton père, si tu fais ce que je t’ai prescrit, si tu observes mes commandements et mes préceptes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Je maintiendrai ton trône royal, selon l’alliance que j’ai faite avec David, disant: Jamais, en Israël, il ne manquera de chef issu de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mais si vous vous pervertissez, si vous abandonnez les commandements et les préceptes que j’ai mis devant vous, si vous suivez, si vous servez d’autres dieux, si vous les adorez,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Je vous enlèverai de la terre que j’ai donnée à vos pères, je rejetterai loin de ma vue ce temple que j’ai consacré à mon nom; j’en ferai la fable et le jouet des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Et cette demeure superbe, le passant, à son aspect, sera frappé de stupeur, et il s’écriera: Quel sujet a donc eu le Seigneur pour traiter ainsi leur terre et ce temple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Et l’on répondra: C’est qu’ils ont abandonné le Seigneur Dieu de leurs pères, qui les avait ramenés de l’Égypte, et qu’ils ont pris d’autres dieux, qu’ils les ont adorés, qu’ils les ont servis; à cause de cela, il a fait fondre sur eux tous ces maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Le roi Salomon avait mis vingt ans à construire ces deux édifices: le temple du Seigneur et son propre palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Et il rebâtit les villes qu’Hiram lui avait données, et il y établit des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Puis, il se rendit à Bésoba, qu’il entoura de remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Et il bâtit Thoedmor (Palmyre) dans le désert, ainsi que toutes les places fortes du pays d’Emath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Et il fit de Béthoron-la-Haute et de Béthoron-la-Basse deux forteresses, avec murailles, portes et verrous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Et il bâtit Balaath, ainsi que toutes les places fortes qui lui appartenaient, toutes les villes des chars, les villes des cavaliers, enfin tout ce qu’il lui plut de bâtir tant à Jérusalem que dans le Liban, et dans tout son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Tout ce qui restait de l’Hettéen, de l’Amorrhéen, de l’Evéen, du Jébuséen; tout ce qui n’était point d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Mais qui descendait de ceux que les fils d’Israël n’avaient point exterminés, et qui étaient restés avec eux en la terre promise, furent obligés de payer à Salomon un tribut qu’ils paient encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Et Salomon ne permit point qu’il y eût en son royaume de serviteurs nés des fils d’Israël; car ceux-ci étaient des guerriers, des chefs, des vaillants, qui commandaient les chars et les cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Il y en avait à la tête des intendants du roi Salomon; on en comptait deux cent cinquante dirigeant les travaux du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Et Salomon conduisit la fille du Pharaon de la ville de David, au palais qu’il avait bâti pour elle, car il avait dit: Ma femme ne doit pas demeurer en la ville de David, roi d’Israël, parce qu’une ville où est entrée l’arche du Seigneur est sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Alors, Salomon offrit des holocaustes au Seigneur sur l’autel qu’il avait élevé au Seigneur devant le temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Selon la règle de chaque jour; il les offrit conformément aux commandements de Moïse sur les sabbats, les lunes et les fêtes des trois époques de l’année: fête des azymes, fête des semaines, fête des tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Ensuite, conformément à l’ordre établi par David, son père, il régla les fonctions des prêtres et celles des lévites, qui devaient servir et chanter journellement devant les prêtres; il désigna aussi les portiers; car, ainsi l’avait prescrit David, homme de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Et on ne s’écarta point des commandements du roi, concernant les prêtres et les lévites, en aucune chose, notamment en ce qui regardait les trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Tous les travaux avaient été préparés à partir du jour où Salomon avait jeté les fondations du temple, jusqu’à celui où la construction fut achevée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Alors, Salomon alla à Asiongaber et à Ailath, en la terre d’Idumée, près du rivage de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Là, Hiram lui envoya des vaisseaux et des serviteurs habitués à la mer; ceux-ci naviguèrent, avec les serviteurs de Salomon, jusqu’à Ophir; ils rapportèrent de là trois cent cinquante talents d’or, et ils revinrent auprès du roi Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Et la reine de Saba ouït le renom de Salomon, et elle vint à Jérusalem avec une suite nombreuse, pour éprouver le roi Salomon, en lui proposant des énigmes; or, elle avait des chameaux chargés d’épices, d’or et de pierres précieuses; elle vint ainsi auprès de Salomon, et elle lui dit tout ce qu’elle avait dans le cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Et Salomon résolut toutes ses questions, et il n’y eut pas un mot qu’il négligeât, auquel il ne répondît.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Et la reine de Saba vit la sagesse de Salomon, le palais qu’il avait bâti,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Les mets de sa table, les logements de ses serviteurs, la tenue de ses officiers et leurs vêtements, ses échansons, leur équipement et les holocaustes qu’il consacra dans le temple du Seigneur, et elle en fut hors d’elle-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Et elle dit au roi Salomon: C’était la vérité qu’on m’avait dite en mon pays, au sujet de ton éloquence et de ta sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Et j’avais refusé de croire à ce qu’on m’en avait rapporté, jusqu’à ce que je fusse venue moi-même et que j’eusse vu de mes yeux; je reconnais qu’on ne m’avait point appris la moitié de ta sagesse. Tu as dépassé ce que j’avais entendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Heureux tes hommes, heureux tes serviteurs qui sont toujours auprès de toi, et qui recueillent toute ta sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Béni soit le Seigneur ton Dieu qui s’est complu en toi et qui t’a mis sur le trône d’Israël, pour que tu sois roi selon le cœur du Seigneur ton Dieu; car le Seigneur ton Dieu aime ce peuple, et il veut l’affermir à jamais; et il t’a établi leur roi, afin que tu observes le jugement et la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Et elle donna à Salomon cent vingt talents d’or, avec une immense quantité d’épices, et des pierres précieuses. Il n’y eut, en aucun temps, des épices comme celles que la reine de Saba donna au roi Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Cependant, les serviteurs de Salomon et les serviteurs d’Hiram apportèrent à Salomon de l’or d’Ophir, des pins et des pierres précieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Le roi fit de ces pins les degrés du temple et du palais; il en fit aussi des cithares et des lyres pour les chanteurs, et on n’avait jamais vu de tels arbres auparavant dans la terre de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Et le roi Salomon donna à la reine de Saba tout ce qu’elle voulut, tout ce qu’elle demanda, hormis ce qu’elle-même lui avait donné. Et elle s’en retourna en son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Le poids de l’or qui arriva au roi Salomon en une année, fut de six cent soixante-six talents,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Outre les impôts sur les hommes et les droits payés par les marchands. Et tous les rois de l’Arabie, tous les princes de la terre promise apportaient au roi Salomon de l’argent et de l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Il fit faire deux cents longs boucliers d’or battu, chacun de six cents sicles d’or pur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Et trois cents petits boucliers d’or battu, chacun pesant trois cents sicles d’or; il les plaça tous dans le palais de bois du Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Il fit faire aussi un grand trône d’ivoire qu’il revêtit de lames d’or très-fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'On montait sur ce trône par six degrés revêtus d’or, et il y avait des bras des deux côtés du siége, et deux lions auprès des bras,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Et douze lions sur les degrés: six à droite, six à gauche; on ne voyait rien de semblable dans aucun royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Et tous les vases dont se servait Salomon étaient d’or, ainsi que tous les meubles du palais de bois du Libạn. On n’y voyait point d’argent, car ce métal était compté pour rien, du temps de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Et cela, parce qu’un vaisseau de Salomon partait pour Tharsis avec les serviteurs du roi Hiram, et tous les trois ans des bâtiments en revenaient chargés d’or, d’argent, d’ivoire et de singes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Ainsi, Salomon surpassa tous les rois en science et en richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Et tous les rois de la terre demandèrent à le voir, et à entendre la sagesse que Dieu avait mise en son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Et chaque année, ils lui apportaient des présents: des vases, de l’or, des vêtements, de la myrrhe, des épices, des chevaux et des mules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomon avait pour ses chars quatre mille cavales et douze mille cavaliers; il les avait mis dans les villes des chars ou auprès de lui à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Et il était le chef de tous les rois, depuis l’Euphrate jusqu’au territoire des Philistins, et aux frontières de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Et le roi rendit à Jérusalem l’or et l’argent aussi communs que les pierres; et les cèdres aussi nombreux que les mûriers des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Et Salomon tirait des chevaux de l’Égypte et de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Le reste des actes de Salomon, les premiers et les derniers sont écrits dans les Récits de Nathan le prophète, et d’Achias le Sélonite, et dans les Visions du voyant Johel, concernant Jéroboam, fils de Nabat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Et Salomon régna quarante ans sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Et Salomon s’endormit avec ses pères; on l’ensevelit en la ville de David, et son fils Roboam régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Et Roboam se rendit à Sichem, parce que tout Israël y était venu pour le proclamer roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Or, dès que Jéroboam, fils de Nabat, apprit ces nouvelles en Égypte, où il avait fui loin de Salomon, il en revint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Et le peuple l’envoya chercher, et il alla devant Roboam avec toute la synagogue, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Ton père a rendu notre joug bien dur; allége donc maintenant la servitude trop dure de ton père, que notre joug soit moins lourd, et nous te servirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Et il leur dit: Allez-vous-en pendant trois jours; puis, revenez auprès de moi; et le peuple s’en alla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Le roi Roboam réunit les anciens qui, du vivant de Salomon, son père, se tenaient auprès de lui, disant: Que me conseillez-vous de répondre à ce peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Il lui dirent: Si aujourd’hui tu es bienveillant pour ce peuple, si tu veux bien lui dire de bonnes paroles, ils seront tes serviteurs tous les jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mais, il dédaigna le conseil des anciens qu’il avait consultés, et il consulta les jeunes gens élevés avec lui, qui se tenaient devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Et il leur dit: Comment me conseillez-vous de répondre à ce peuple qui me dit: Allège le joug que nous a mis ton père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Or, les jeunes gens, élevés avec lui, dirent: Voici comment tu parleras à ce peuple qui t’a dit: Ton père a rendu pesant notre joug, allège-le pour nous, réponds-leur: Mon petit doigt est plus gros que le corps de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Mon père vous a châtiés avec un joug pesant, je le rendrai pour vous plus pesant encore; il vous a châtiés à coups de fouet, mais je vous châtierai avec des scorpions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Et Jeroboam revint le troisième jour, avec tout le peuple, auprès de Roboam comme il le leur avait prescrit, disant: Revenez dans trois jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Et le roi leur répondit durement, car il avait dédaigné le conseil des anciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Et il leur parla selon le conseil des jeunes gens, et il leur dit: Mon père vous a chargés d’un joug pesant, je le rendrai pour vous plus pesant encore; il vous a châtiés à coups de fouet, moi je vous châtierai avec des scorpions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Et le roi n’avait point écouté les fils d’Israël, parce que Dieu s’était tourné contre lui, disant: « Le Seigneur a relevé la parole qu’il a dite, par Achias le Sélonite, concernant Jéroboam, fils de Nabat,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Et tout Israël. » C’est pourquoi le roi ne l’avait pas écouté, et le peuple s’écria: Qu’y a-t-il entre nous et David? Notre héritage dépend-il du fils de Jessé? A tes tentes, ô Israël, et toi, David, veille sur ta maison. Et Israël s’en alla chacun en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Et les hommes d’Israël qui habitaient Juda rentrèrent en leurs villes, et Jéroboam régna sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Et le roi envoya aux autres fils d’Israël, Adoniram, intendant des impôts; ils le lapidèrent, il mourut; et le roi Roboam s’empressa de monter sur son char pour fuir, et se renfermer dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Et jusqu’à nos jours la maison de David a été rejetée par Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Roboam rentra donc à Jérusalem; puis, il réunit Juda et Benjamin, cent quatre-vingt mille jeunes gens allant à la guerre, afin de combattre Israël, et de recouvrer la royauté pour Roboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mais, la parole du Seigneur vint à Samaïas, homme de Dieu; disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Parle à Roboam, fils de Salomon, à tout Juda et à Benjamin, dis-leur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Voici ce que dit le Seigneur: Ne partez pas, ne combattez point vos frères les fils d’Israël, retournez chacun en votre demeure, car cette chose est de moi. Ils obéirent à la parole du Seigneur, et, selon son ordre, ils renoncèrent à marcher contre Jéroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Et Roboam habita Jérusalem, et il bâtit des places fortes en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Il bâtit encore Bethléem, Etan, Thécoé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bethsura, Sochoth, Odollam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Geth, Marisan, Ziph,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraï, Lachis, Azéca,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Saraa, Aïlon et Hébron, qui appartient à Juda et à Benjamin; toutes villes qu’il entoura de remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Et il les fortifia, et leur donna des chefs auxquels il assigna des vivres, de l’huile et du vin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Et il approvisionna chacune d’elles de lances et de boucliers, et il en multiplia les défenses; et il eut à lui Juda et Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Cependant, les prêtres et les lévites qui étaient en tout Israël, se rassemblaient auprès de lui de tous les points du territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Car, ils abandonnèrent leurs villes de résidence, et ils se rendirent en Juda et à Jérusalem, parce que Jéroboam et ses fils leur avaient ôté le service du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Et Jeroboam avait institué pour lui des prêtres des hauts lieux qui sacrifiaient aux idoles, aux choses vaines, aux veaux d’or, qu’avaient faits Jeroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Et il avait chassé des tribus d’Israël ceux qui dévouaient leur cœur à chercher le Seigneur Dieu d’Israël; et ils vinrent à Jérusalem pour sacrifier au Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Et ils affermirent le royaume de Juda, et Roboam, fils de Salomon, en fut fortifié pendant trois ans, parce qu’il marcha trois ans dans les voies de David et de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Roboam prit pour femmes Moolath, fille de Jerimuth, fils de David; et Abigail, fille d’Eliab, fils de Jessé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Celle-ci lui enfanta des fils: Jéhu, Samoria et Zaam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Après cela, il épousa Maacha, fille d’Absalon, et elle lui enfanta Abias, Jetthi, Zéza et Salémoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Or, Roboam aima Maacha, fille d’Absalon, plus que toutes ses femmes et ses concubines, car il avait dix-huit femmes et soixante concubines; il eut d’elles vingt-huit fils et soixante filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Et il fit Adias, fils de Maacha, chef de tous ses frères, car il avait dessein de lui laisser le trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Et il le fortifia plus que tous ses autres fils dispersés sur tout le territoire de Juda et de Benjamin, dans les villes entourées de remparts où Roboam maintenait abondance de vivres, et où il leur fit épouser beaucoup de femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Or, quand Roboam eut organisé son royaume et s’y fut affermi, il abandonna les commandements du Seigneur, et tout le peuple suivit son exemple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Et la cinquième année de son règne, parce qu’il avait péché contre le Seigneur, Susacim (Sésac), roi d’Égypte, marcha contre Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Avec douze cents chars, soixante mille chevaux et une multitude innombrable des Libyens, de Troglodytes et d’Éthiopiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Et ils s’emparèrent de toutes les forteresses de Juda, et ils arrivèrent devant Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Et Samaïas le prophète alla trouver Roboam et les princes de Juda, qui s’étaient réunis à Jérusalem par crainte de Susacim, et il leur dit: Voici que dit le Seigneur: Vous m’avez abandonné, et moi je vous abandonnerai pour vous livrer à Susacim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Et le roi et les chefs de Juda eurent honte, et ils dirent Le Seigneur est juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Quand le Seigneur vit qu’ils s’étaient repentis, la parole du Seigneur vint à Samaïas, disant: Ils se sont repentis, je ne les détruirai pas; je leur accorderai comme une ombre de salut, et ma colère ne tombera pas sur Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Ils seront asservis, et ils connaîtront la différence de ma servitude avec la servitude des rois de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Et Susacim, roi d’Égypte, marcha contre Jérusalem; il prit tous les trésors du temple du Seigneur, et tous les trésors du palais du roi, il prit tout; il prit aussi les boucliers d’or qu’avait faits Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, '(Le roi Roboam les remplaça par des boucliers d’airain). Et le roi Susacim mit au-dessus de lui des capitaines de ses gardes surveillant la porte du palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Et lorsque le roi entrait dans le temple du Seigneur, les gardes y entraient aussi, et avec les coureurs ceux qui allaient à la rencontre des coureurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Mais parce qu’il s’était repenti, le Seigneur détourna de lui sa colère, et il ne fut pas entièrement détruit; car il y avait encore en Juda de bonnes pensées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Et le roi Roboam se raffermit en Jérusalem et il régna; il avait quarante et un ans quand il monta sur le trône, et il régna dix-sept ans à Jérusalem dans la ville que, parmi toutes les tribus d’Israël, le Seigneur s’était choisie pour que son nom y fût invoqué; sa mère, nommée Noomma, était Ammonite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Et il fit le mal parce qu’il ne dirigea pas son cœur à la recherche de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Quant aux discours de Roboam, les premiers et les derniers, et à ses actions, ne sont-ils pas écrits dans les Récits de Samaïas le prophète, et d’Addo le voyant? Roboam fut toujours en guerre avec Jéroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Et Roboam alla rejoindre ses pères, et il fut enseveli dans la ville de David; et Abias, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'En la dix-huitième année du règne de Jéroboam, Abias commença à régner sur Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Il régna trois ans à Jérusalem; et le nom de sa mère était Maacha, fille d’Uriel de Gabaon. Abias ne cessa pas d’être en guerre avec Jéroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Et il rangea en bataille une armée de quatre cent mille hommes vaillants, et Jéroboam lui en opposa huit cent mille, vaillants aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Alors Abias monta sur la colline de Salomon qui est dans les montagnes d’Ephraïm, et il dit: Jeroboam, écoute-moi ainsi que tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Ne devez-vous pas savoir que par une alliance sacrée, le Seigneur notre Dieu a donné pour toujours le royaume d’Israël à David et à ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mais, Jéroboam, fils de Nabat, serviteur de Salomon, fils de David, s’est levé et s’est révolté contre son maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Et des hommes de pestilence, fils du péché, se sont joints à lui, qui s’est révolté contre Roboam, fils de Salomon, et Roboam, qui était jeune et d’un cœur craintif, n’osa lui tenir tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Et vous maintenant, vous dites que vous résisterez au royaume du Seigneur que possèdent les fils de David; et vous êtes nombreux, et vous avez avec vous les veaux d’or qu’a faits Jeroboam, pour qu’ils soient vos dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'N’avez-vous pas chassé les prêtres du Seigneur, les fils d’Aaron et les lévites? Ne vous êtes-vous point fait des prêtres parmi le peuple de toute la terre? Quiconque arrive, pour se consacrer, avec un bœuf du troupeau et sept béliers, le voilà prêtre de ce qui n’est point dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Quant à nous, nous n’avons point abandonné le Seigneur; ce sont ses prêtres, fils d’Aaron, et ses lévites qui le servent, et qui journellement');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Offrent des holocaustes au Seigneur, matin et soir, brûlent les parfums composés, déposent sur la table pure les pains de proposition, allument à la nuit le chandelier d’or et les lampes qui doivent brûler; car, nous observons les préceptes du Seigneur Dieu de nos pères, que Vous avez abandonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Voyez, le Seigneur et ses prêtres sont avec nous à notre tête; ce sont les trompettes sacrées qui nous donnent les signaux; fils d’Israël, gardez-vous de combattre le Seigneur, car vous ne réussirez à rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Cependant, Jéroboam ramena sur les derrières de Juda une embuscade qu’il avait dressée; il fut ainsi lui-même devant Juda, et son embuscade derrière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Et Juda se retournant regarda, et voilà que la bataille était devant et derrière lui; alors, il cria au Seigneur, et les prêtres sonnèrent de la trompette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Et les hommes de Juda crièrent, et il advint, pendant qu’ils jetaient de grands cris, que le Seigneur frappa Jéroboam et Israël devant Abias et Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Et les fils d’Israël s’enfuirent devant Juda, et le Seigneur les livra au roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abias et son peuple les frappèrent d’une grande plaie, et cinq cent mille hommes vaillants succombèrent du côté d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Et, en ce jour-là, les fils d’Israël furent humiliés, et les fils de Juda prévalurent, parce qu’ils avaient espéré en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abias poursuivit Jéroboam, il lui prit des villes: Béthel et ses bourgs, Jésyna et ses bourgs, Ephron et ses bourgs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Et Jéroboam fut sans force sous le règne d’Abias; enfin, le Seigneur le frappa, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Et Abias s’affermit, et il épousa quatorze femmes, dont il eut vingt-deux fils et seize filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Le reste de l’histoire d’Abias, ses actions et ses discours, sont écrits au livre du prophète Addo.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Et Abias mourut, et il alla rejoindre ses pères, et on l’ensevelit en la ville de David; et Asa, son fils, régna à sa place. Sous Asa, Juda fut en paix dix années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Et il fit ce qui est bon et droit devant le Seigneur son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Il répudia les autels des dieux étrangers et les hauts lieux; il brisa les colonnes, il abattit les bois sacrés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Et il dit à Juda de chercher le Seigneur Dieu de leurs pères, et de pratiquer sa loi et ses commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Et il détruisit, dans toutes les villes de Juda, les autels et les idoles, et paisiblement');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Il fortifia des places en Juda; car la terre était en paix. Il n’y eut point de guerre en ces années, parce que le Seigneur lui avait donné du repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Et il dit à Juda: Fortifions les villes, faisons-leur des murs, des tours, des portes, des verrous; nous prévaudrons sur la terre: car de même que nous avons cherché le Seigneur notre Dieu, il nous a cherchés; il nous a donné la paix tout alentour, et il nous a fait prospérer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Or, Asa avait en la terre de Juda une force de trois cent mille hommes portant javeline et bouclier; et, en la terre de Benjamin, deux cent quatre-vingt mille archers, ou fantassins armés à la légère; tous ces hommes étaient vaillants et aguerris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Et Zara l’Ethiopien marcha contre eux avec une armée d’un million d’hommes, et trois cents chars; il s’avança jusqu’à Marèsa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Asa sortit à sa rencontre, et rangea son armée en bataille dans la vallée, au nord de Marèsa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Et Asa cria au Seigneur son Dieu, et il dit: Seigneur, il ne vous est point impossible de sauver, soit avec beaucoup, soit avec peu; fortifiez-nous, Seigneur notre Dieu, car nous avons eu foi en vous, et c’est en votre nom que nous avons marché contre cette grande multitude. Seigneur notre Dieu, que l’homme ne prévaille pas contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Et le Seigneur frappa les Éthiopiens devant Juda, et les Éthiopiens s’enfuirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Asa et son peuple les poursuivirent jusqu’à Gedsor. Les Éthiopiens tombèrent jusqu’au dernier; car ils furent broyés devant le Seigneur et devant son armée, et les fils de Juda recueillirent d’innombrables dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Et ils détruisirent les bourgs autour de Gedsor; car un grand trouble, venant du Seigneur, était sur eux. Les fils de Juda pillèrent leurs villes, et ils firent un riche butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Ils détruisirent les tentes des troupeaux, ils dépouillèrent les habitants de la côte, ils emmenèrent quantité de moutons et de chameaux, et ils revinrent à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Et l’Esprit de Dieu descendit sur Azarias, fils d’Obed.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Et il sortit à la rencontre d’Asa, de Juda et de Benjamin, et il dit: Écoutez-moi, Asa, et tout Juda et Benjamin: le Seigneur est avec vous, parce que vous êtes avec lui; si vous le cherchez, vous le trouverez; si vous l’abandonnez, il vous abandonnera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Il y aura bien des jours en Israël sans vrai Dieu, sans prêtre qui le révèle, sans loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Mais Dieu les convertira au Seigneur Dieu d’Israël, ét il sera trouvé par eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Et, en ces jours-là, il n’y a point de paix pour agir; car un grand trouble, venant du Seigneur, est sur tous ceux qui habitent la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Et il y aura guerre de nation à nation, de ville à ville; car Dieu les aura troublés par toutes sortes d’afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Fortifiez-vous donc; que vos mains ne viennent point à défaillir; car il y a une récompense pour vos œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Après avoir entendu ces paroles et la prophétie d’Adad le prophète, le roi se fortifia, et il chassa les abominations de tout le territoire de Benjamin, et de Juda et de toutes les villes que possédait Jéroboam dans la montagne d’Ephraïm; et il fit la dédicace de l’autel du Seigneur qui était devant le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Puis, il rassembla Juda, Benjamin, les étrangers, résidant avec lui, venus d’Ephraïm, de Manassé et de Siméon; car beaucoup de ceux d’Israël s’étaient joints au roi, parce qu’ils avaient vu que le Seigneur était avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Et ils se réunirent à Jérusalem le troisième mois de la quinzième année du règne d’Asa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Et, ce jour-là, ils sacrifièrent au Seigneur, des dépouilles qu’ils avaient ramenées, sept cents bœufs et sept mille brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Et ils firent alliance pour chercher le Seigneur Dieu de leurs pères, de tout leur cœur et de toute leur âme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Et pour que quiconque, jeune ou vieux, homme ou femme, ne chercherait pas le Seigneur Dieu d’Israël, fût mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Et ils prêtèrent serment au Seigneur à haute voix, au son des trompettes et des cors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Et tout Juda se réjouit d’avoir juré, car il l’avait fait de tout son cœur, de toute son âme, et avec une pleine volonté de chercher le Seigneur; et ils le trouvèrent, et il leur donna la paix tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Et le roi expulsa Maacha, sa mère, pour qu’il n’y eût plus personne qui servît Astarté, et il abattit l’idole, et il la brûla dans le torrent de Cédron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Néanmoins, les hauts lieux n’étaient point détruits; ils prévalaient encore en Israël; mais le cœur d’Asa fut parfait tous les jours de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Et il consacra de nouveau les choses saintes de David, son aïeul, et celles du temple: argent, or et vaisseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Et il n’y eut point de guerre contre lui jusqu’à la trente-cinquième année de son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Et, en la trente-huitième année du règne d’Asa, le roi d’Israël marcha contre Juda, et il bâtit Rhama pour empêcher le roi Asa de sortir et d’entrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Et Asa prit tout l’argent et l’or des trésors, tant du temple que du palais, et il l’envoya au fils d’Ader, roi de Syrie, qui résidait à Damas, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Fais avec moi l’alliance qui existait entre ton père et le mien; voilà que je t’offre de l’argent et de l’or; viens, disperse Baasa, roi d’Israël, qu’il s’éloigne de mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Et le fils d’Ader accueillit la demande d’Asa; il fit partir les chefs de ses armées contre les villes d’Israël, qui dévastèrent Ahion, Dan, Abelmaïn, et tout ce qui environne Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Quand Baasa l’apprit, il abandonna les constructions de Rhama, et il renonça à son entreprise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Et le roi Asa rentra en possession de tout Juda, et il prit à Rhama les pierres et les bois que Baasa avait employés pour la bâtir, et il s’en servit pour construire Gabaa et Maspha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'En ce temps-là, Anani le prophète vint trouver Asa, roi de Juda, et il lui dit: Parce que tu t’es confié au roi de Syrie, et que tu n’as point eu foi en ton Dieu, l’armée de Syrie a échappé à tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Les Éthiopiens et les Libyens n’avaient-ils pas une armée nombreuse, pleine d’audace, forte par ses cavaliers et sa multitude? Tu as eu foi en Dieu, et il te l’a livrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Car les regards du Seigneur sont fixés sur la terre pour fortifier tout cœur parfait devant lui; en cela, tu as follement agi, et maintenant, tu seras toujours en guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Asa se mit en colère contre le prophète, et il le jeta en prison, tant il avait de courroux; et, en ce tempslà, Asa maltraita quelques-uns de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Et les actes d’Asa, les premiers et les derniers, sont écrits au livre des Rois de Juda et d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'En la trente-neuvième année de son règne, Asa souffrit d’un mal aux pieds, dont il fut très-malade; et, en cette maladie, il ne chercha pas le Seigneur, mais les médecins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Et Asa s’endormit avec ses pères, et il mourut en la quarantième année de son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Et on l’ensevelit dans le sépulcre qu’il s’était creusé en la ville de David; or, on l’avait étendu sur sa couche, on l’avait rempli d’aromates et de toutes les substances dont se composent les parfums, et on lui fit de magnifiques funérailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Et Josaphat, son fils, régna à sa place, et il prévalut sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Il mit des garnisons dans toutes les places fortes de Juda, et donna des chefs à toutes les villes de Juda et aux villes d’Ephraïm dont son père, Asa, s’était emparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Et le Seigneur fut avec Josaphat, parce qu’il marcha dans les voies qu’avait d’abord suivies son père, et qu’il ne chercha point les idoles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Mais qu’il chercha le Seigneur Dieu de son père, et qu’il marcha selon les préceptes de son père, et non selon les œuvres d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Et le Seigneur fit prospérer le royaume entre ses mains, et tout Juda offrit des présents à Josaphat, qui acquit ainsi beaucoup de gloire et de richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Et son cœur fut exalté dans les voies du Seigneur, et il détruisit les hauts lieux et les bois sacrés sur le territoire de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'En la troisième année de son règne, il envoya, pour enseigner dans les villes de Juda, ses chefs et les fils des hommes vaillants: Abdias, Zacharie, Nathanaël et Michée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Et, avec eux, les lévites Samaïas, Nathanias, Zabdias, Asihel, Semiramoth, Jonathas, Adonias, Tobias et Tobadonias; tous lévites, et les prêtres Elisama et Joram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Et ils enseignèrent en Juda; ils avaient le livre de la loi du Seigneur, ils le lisaient dans les villes de Juda, et ils instruisaient le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Et un grand trouble, venant du Seigneur, se répandit parmi les rois qui entouraient Juda, et ils ne firent point la guerre à Josaphat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Les Philistins lui envoyèrent de l’argent et d’autres dons; les Arabes lui amenèrent sept mille sept cents moutons et béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Et Josaphat alla toujours croissant jusqu’à la magnificence, et il bâtit en Judée des palais et des forteresses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Et il exécuta de nombreux travaux en Judée, et il eut à Jérusalem des guerriers vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'En voici le dénombrement par familles paternelles; en Juda, commandants de mille hommes: Ednas le chef, et avec lui trois cent mille hommes vaillants;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Joanan, et avec lui deux cent quatre-vingt mille hommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Amasias, fils de Zari, plein de zèle pour le Seigneur, et avec lui deux cent mille vaillants;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Et en Benjamin: Eliada, et avec lui deux cent mille archers ou fantassins armés à la légère;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Et Jozabad, et avec lui cent quatre-vingt mille hommes aguerris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Tels étaient ceux qui servaient le roi, outre ceux qu’il avait placés dans toutes les forteresses de la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'La gloire et la richesse de Josaphat s’accrurent encore, et il s’allia par un mariage à la famille d’Achab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Au bout de quelques années, il alla voir Achab en Samarie, et Achab immola, pour lui et sa suite, quantité de bœufs et de brebis; il lui fit beaucoup d’amitiés pour l’emmener avec lui contre Ramoth-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Et Achab, roi d’Israël, dit à Josaphat, roi de Juda: Viendras-tu avec moi à Ramoth-Galaad? L’autre répondit: Comme tu es, je suis; mon peuple est comme ton peuple, il fera la guerre comme lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Et Josaphat dit au roi d’Israël: Consulte aujourd’hui le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Et le roi d’Israël rassembla tous les prophètes, au nombre de quatre cents, et il leur dit: Irai-je en guerre à Ramoth-Galaad, ou m’abstiendrai-je? Et ils répondirent: Marche, le Seigneur les livrera aux mains du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Et Josaphat dit: N’y a-t-il plus ici un seul prophète du Seigneur par qui nous puissions consulter?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Et le roi d’Israël répondit à Josaphat: Il y a encore un homme par qui l’on peut consulter le Seigneur; mais je le hais, parce que, à mon sujet, il ne prophétise jamais le bien, mais toujours le mal. C’est Michée, fils de Semla. Et Josaphat reprit: Que le roi ne tienne pas un tel langage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Et le roi appela un eunuque, et il dit: Fais venir tout de suite Michée, fils de Semla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Or, le roi d’Israël et Josaphat, roi de Juda, revêtus de robes, étaient assis chacun sur son trône, sur l’esplanade de la porte de Samarie, et tous les prophètes prophétisaient devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'L’un d’eux, Sédécias, fils de Chanaan, s’était fait des cornes de fer, et il dit: Voici ce que dit le Seigneur: Avec ces cornes tu frapperas la Syrie jusqu’à ce qu’elle soit abattue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Et tous les prophètes prédisaient ainsi: Marche sur Ramoth-Galaad, et tu réussiras, et le Seigneur livrera à tes mains le roi de Syrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Et le messager qui était allé querir Michée dit à celui-ci Tous les prophètes n’ont qu’une voix pour dire de bonnes choses concernant le roi; que tes paroles soient comme celles de l’un d’eux, et tu auras bien parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Mais Michée répondit: Vive le Seigneur! ce que le Seigneur me dira, je le répéterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Et il alla devant le roi, et le roi lui dit: Michée, dois je aller en guerre à Ramoth-Galaad, ou m’en abstenir? Et il répondit: Marche, et tu réussiras, et ils te seront livrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Et le roi lui dit: Combien de fois t’adjurerai-je pour que tu ne me dises rien que la vérité au nom du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Et Michée reprit: J’ai vu Israël dispersé sur les montagnes, comme un troupeau sans pasteur. Et le Seigneur a dit: Ces hommes n’ont point de chef, que chacun retourne en paix dans sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Et le roi d’Israël dit à Josaphat, roi de Juda: Ne t’ai-je point dit qu’à mon sujet il ne prophétisait jamais le bien, mais toujours le mal?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Michée reprit: Il n’en est pas ainsi; écoutez la parole du Seigneur: J’ai vu le Seigneur assis sur son trône, et toute l’armée du ciel se tenait auprès de lui à sa droite et à sa gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Et le Seigneur a dit: Qui trompera Achab, roi d’Israël, pour qu’il parte et succombe à Ramoth-Galaad? Et l’un répondit au Seigneur d’une sorte, l’autre différemment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Et l’esprit sortit des rangs, et il se plaça devant le Seigneur, et il dit: C’est moi qui le tromperai. Et le Seigneur reprit: De quelle manière?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Et il dit: Je partirai, et je serai un esprit trompeur en la bouche de tous ses prophètes. Et le Seigneur dit: Tu le tromperas, et tu prévaudras; va, et fais ce que tu as dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Maintenant donc, voici que le Seigneur a placé un esprit trompeur en la bouche de tous tes prophètes, et le Seigneur t’a annoncé le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Alors, Sédécias le Chananéen s’avança, frappa Michée à la joue, et dit: Par quel chemin l’Esprit du Seigneur est-il sorti de moi pour te parler à toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Et Michée reprit: Tu le verras le jour où tu passeras de chambre en chambre pour te cacher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Et le roi d’Israël s’écria: Que l’on saisisse Michée; menez-le chez Emer, gouverneur de la ville, et chez le prince Joas, fils du roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Et dites: Voici ce que dit le roi: Emprisonnez cet homme; qu’il se nourrisse du pain et de l’eau de l’affliction jusqu’à je revienne en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Et Michée reprit: Si tu reviens en paix, le Seigneur n’a point parlé par ma bouche. Et il ajouta: Peuple, écoutez-moi tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Après cela, le roi d’Israël partit avec Josaphat, roi de Juda, pour Ramoth-Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Et le roi d’Israël dit au roi de Juda: Aide-moi à me déguiser, et j’engagerai la bataille, et toi tu auras mes vêtements. Le roi d’Israël se déguisa donc, et il engagea la bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Et le roi de Syrie donna cet ordre aux chefs des chars qui l’accompagnaient: N’attaquez ni petit ni grand, mais le seul roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Et ceci advint: quand les chefs des chars virent Josaphat, roi de Juda, ils se dirent: C’est le roi d’Israël. Et ils l’entourèrent pour l’attaquer; mais Josaphat cria au Seigneur, et le Seigneur voulut le sauver, et Dieu les détourna de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Et quand les chefs des chars virent que ce n’était pas le roi d’Israël, ils s’éloignèrent de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Alors, un homme adroit, ayant tendu son arc, frappa le roi d’Israël au flanc, au défaut de la cuirasse; et le roi dit à son cocher: Tourne bride, emmène-moi hors de la mêlée, car j’ai une blessure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Et la bataille fut perdue pour lui ce jour-là, et il resta jusqu’au soir sur son char, en face de l’armée syrienne, et, au soleil couchant, il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Et Josaphat, roi de Juda, revint en son palais à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Et le prophète Jéhu, fils d’Anani, sortit à sa rencontre, et il lui dit: Roi Josaphat, n’as-tu pas porté secours à un impie, et donné ton amitié à un ennemi du Seigneur? A cause de cela, la colère du Seigneur a été excitée contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Cependant, il s’est trouvé du bon en toi; car tu as détruit les bois sacrés en la terre de Juda, et, d’un cœur droit, tu as cherché Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Et Josaphat résida en Jérusalem; il en sortit encore une fois pour visiter le peuple depuis Bersabée jusqu’aux montagnes d’Ephraïm, et il les ramena au Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Et il institua des juges dans toutes les places fortes de Juda un par ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Et il dit aux juges Soyez attentifs à ce que vous faites; car vous ne jugez pas pour l’homme, mais pour le Seigneur, et les paroles du jugement sont avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Que la crainte du Seigneur soit donc en vous; veillez et agissez; car, avec le Seigneur notre Dieu, il n’est point d’iniquité; il n’y a point à considérer la personne, ni à recevoir des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Et Josaphat institua en Jérusalem des prêtres, des lévites et des chefs de familles d’Israël, pour juger les choses du Seigneur et les habitants de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Et il leur donna ses ordres, disant: Vous ferez votre devoir avec la crainte de Dieu, en la plénitude et en la sincérité de votre cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Quels que soient ceux de vos frères qui, de leurs villes, viendront à vous en justice, soit pour une décision entre le sang et le sang, soit pour une application des commandements et des préceptes, déterminez bien pour eux le droit et la sentence; et ils ne pécheront pas envers le Seigneur, et il n’y aura point de colère, ni contre vos frères, ni contre vous. Faites ainsi, et vous ne pécherez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Et Ananias le prêtre sera votre chef en ce qui concernera le Seigneur; Zabdias, fils d’Ismaël, prince de la maison de Juda, sera votre chef en ce qui concernera le roi, et vous aurez avec vous des scribes et des lévites; fortifiez-vous, et faites, et le Seigneur sera avec les bons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Après cela, les fils de Moab, les fils d’Ammon, et, avec eux, des Minéens, se mirent en campagne pour attaquer Josaphat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Et des gens vinrent et ils l’apprirent au roi, disant: Une grande multitude est venue contre toi des bords de la mer, du côté de la Syrie, et la voici en Asasan-Thamar (la même qu’Engaddi).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Et Josaphat eut crainte, et il s’appliqua à chercher le Seigneur, et il proclama un jeûne dans tout Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Et Juda se rassembla pour chercher le Seigneur; et, de toutes les villes de Juda, on vint pour chercher le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Et Josaphat, avec toute l’Église de Juda en Jérusalem, se tint debout dans le temple du Seigneur devant le parvis neuf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Et il dit: Seigneur Dieu de mes pères, n’êtes-vous point Dieu dans le ciel au-dessus de nous? N’êtes-vous pas le Seigneur de tous les royaumes des nations? N’est-ce pas en vos mains que réside la force du pouvoir? Est-il quelqu’un qui puisse vous résister?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'N’êtes-vous pas le Seigneur dont le bras a exterminé les habitants de cette terre, devant les fils d’Israël, votre peuple? Ne l’avez-vous point donnée pour toujours à la race d’Abraham, votre bien-aimé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Elle y demeure; elle y a bàti un lieu saint à votre nom, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Si le mal, le glaive, la vengeance, la mort, la famine, viennent sur nous, nous nous tiendrons devant le temple et devant vous, ô Seigneur, parce que votre nom est sur le temple, et, dans notre affliction, nous crierons à vous, et vous nous entendrez, et vous nous sauverez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Et maintenant, voilà que les fils d’Ammon, et Moab et ceux de la montagne de Seir, chez qui vous n’avez point permis à Israël de passer, à sa sortie d’Égypte (car il s’est détourné de leurs territoires, et ne les a point exterminés),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Voilà qu’ils nous attaquent pour entrer dans l’héritage que vous nous avez donné, et pour nous en bannir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Seigneur notre Dieu, ne les jugerez-vous pas? Car nous n’avons pas la force de résister à l’immense multitude qui marche contre nous, et nous ne savons que leur faire, sinon de tourner nos yeux vers vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Or, tout Juda était là devant le Seigneur, avec leurs enfants et leurs femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Et, dans l’Église, l’Esprit du Seigneur descendit sur Oziel, fils de Zacharie, des fils de Banaïas, des fils d’Elihel, fils du lévite Matthanias, des fils d’Asaph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Et il dit: Écoutez, ô Juda, et vous habitants de Jérusalem, et toi, roi Josaphat: voici ce que vous dit le Seigneur N’ayez point de crainte, ne tremblez pas devant cette multitude immense; car ce combat n’est point de vous, mais de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Marchez demain contre elle; ils monteront le coteau d’Assis, et vous les trouverez à l’extrémité du torrent qui traverse le désert de Jerihel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ce n’est point à vous de les combattre; comprenez cela, et voyez comme le Seigneur, ô Juda et Jérusalem, opèrera votre salut. N’ayez point de crainte, n’hésitez pas à marcher demain à leur rencontre: le Seigneur est avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Et Josaphat, et tout Juda et les habitants de Jérusalem s’étant prosternés la face contre terre, tombèrent devant le Seigneur pour l’adorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Puis, les lévites des fils de Caath et des fils de Coré se levèrent pour chanter à haute voix les louanges du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Et le peuple se leva dès l’aurore, et ils sortirent dans le désert de Thécoé; et, pendant qu’ils sortaient, Josaphat, se tenant immobile, cria, et dit: Écoutez-moi, Juda, et vous, habitants de Jérusalem, mettez votre confiance dans le Seigneur notre Dieu, et il se confiera en vous; mettez votre confiance dans son prophète, et vous prospérerez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Ensuite, il tint conseil avec le peuple; puis, il plaça en tête de l’armée, comme elle sortait, des chantres harpistes pour célébrer et louer les choses saintes, et ils disaient Rendez gloire au Seigneur, car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Et, au moment où ils commençaient à chanter ses louanges, le Seigneur excita la guerre entre les fils d’Ammon et Moab, d’une part, et ceux de la montagne de Seïr, d’autre part; ils avaient tous marché sur Israël, et ils se tournèrent les uns contre les autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Les fils d’Ammon et Moab se levèrent pour exterminer ceux de la montagne de Seïr, et, quand ils les eurent broyés, ils s’attaquèrent mutuellement, de sorte qu’ils se détruisirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Lors donc que Juda arriva sur la hauteur d’où l’on découvre le désert, il regarda et il vit cette multitude, et voilà qu’ils étaient tous tombés morts, et gisant à terre, pas un ne s’était échappé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Et Josaphat avec tout son peuple descendit pour recueillir les dépouilles; ils trouvèrent quantité de bétail, des bagages, des couvertures et des choses précieuses; ils les prirent et ils mirent trois jours à recueillir le butin, tant il y en avait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Le quatrième jour, ils reprirent leurs rangs dans le val de la bénédiction; car, en ce lieu, ils bénirent le Seigneur; à cause de cela cette vallée est appelée encore de nos jours la Vallée de la Bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Et tout Juda, Josaphat à sa tête, revint à Jérusalem avec une grande allégresse, car le Seigneur les avait comblés de joie aux dépens de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Et ils entrèrent à Jérusalem au son des harpes et des cithares, auxquelles se joignirent les trompettes quand ils arrivèrent au temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Et il y eut un grand trouble venant du Seigneur, parmi tous les royaumes de la terre, quand ils surent que le Seigneur avait combattu les ennemis d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Ainsi le royaume de Josaphat fut en paix; car le Seigneur, alentour, apaisa tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Et Josaphat régna en Jérusalem; il avait trente-cinq ans lorsqu’il monta sur le trône, et son règne dura vingt-cinq ans. Sa mère s’appelait Azuba, fille de Sali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Et il marcha dans les voies d’Asa, son père, et il ne s’en détourna pas, et il fit ce qui est droit aux yeux du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Cependant, les hauts lieux subsistèrent encore, et le peuple ne dirigea pas encore son cœur vers le Seigneur Dieu de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Le reste des actes de Josaphat, des premiers et des derniers, est compris dans les récits de Jéhu, fils d’Anani, qui écrivit le livre des Rois d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Après cela, Josaphat, roi de Juda, fit alliance avec Ochozias, roi d’Israël, et il pécha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'En agissant et en marchant avec lui pour construire une flotte qui partit d’Asion-Gaber, allant à Tharsis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Alors, Eliézer, fils de Dodia de Marise, prophétisa contre Josaphat, disant: Parce que tu t’es lié avec Ochozias, le Seigneur a détruit ton ouvrage; il a brisé ta flotte, et elle n’a pu aller jusqu’à Tharsis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Et Josaphat s’endormit avec ses pères; et il fut enseveli dans la ville de David, et Joram, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Il avait six frères nés de Josaphat: Azarias, Jehiel, Zacharie, Azarias, Michel et Zaphatias. Tels furent les fils de Josaphat, roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Leur père les avait richement dotés d’argent, d’or et d’armes avec des places fortes en Juda; mais il laissa le royaume à Joram, parce qu’il était le premier-né.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Et Joram se mit en marche dans son royaume, et il s’affermit, et il fit périr par le glaive tous ses frères avec quelques-uns des chefs d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Il avait trente-deux ans quand il monta sur le trône, et il régna huit ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Et il marcha dans la voie du roi d’Israël, comme avait fait la maison d’Achab, parce que sa femme était fille d’Achab, et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Toutefois, le Seigneur ne voulait pas détruire la maison de David, à cause de l’alliance qu’il avait faite avec lui, et parce qu’il avait promis de donner, à lui et à ses fils, un flambeau qui ne s’éteindrait jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'En ces jours-là, Edom se souleva contre Juda, et mit à sa tête un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Et Joram partit avec ses chefs et toute sa cavalerie, et il se leva la nuit, et il tailla en pièces Edom qui l’avait enveloppé; les chefs des chars, le peuple, tout s’enfuit chacun en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Or, Edom est resté en révolte contre Juda jusqu’à nos jours. En ce temps-là, Lomna se souleva aussi contre Joram, parce qu’il avait abandonné le Seigneur Dieu de ses pères,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Et qu’il avait bâti des hauts lieux dans les villes de Juda, et entraîné les habitants de Jérusalem à se prostituer, et qu’il avait égaré Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Alors, il lui vint une lettre du prophète Elie, disant: Voici ce que dit le Seigneur Dieu de David, ton aïeul: En punition de ce tu n’as point marché dans la voie de Josaphat, ton père, ni dans la voie d’Asa, roi de la Judée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Et de ce tu as marché dans les voies des rois d’Israël, et de ce que tu as entraîné Juda et les habitants de Jérusalem à se prostituer, comme s’est prostituée la maison d’Achab, et de ce que tu as tué tes frères, fils de ton père, qui valaient mieux que toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Voilà que le Seigneur va te frapper d’une grande plaie au milieu de ton peuple, de tes fils, de tes femmes, de toutes tes richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Tu seras atteint d’une maladie cruelle, d’un mal d’entrailles, et tous tes intestins sortiront de jour en jour par l’effet de cette maladie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Et le Seigneur excita contre Joram les Philistins, les Arabes et les voisins de l’Éthiopie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Et ils marchèrent sur Juda, et furent vainqueurs; ils enlevèrent tout ce qu’ils trouvèrent dans le palais du roi, avec ses fils et ses filles; il ne lui resta pas de fils, hormis Ochozias, le plus jeune de tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Après cela, le Seigneur le frappa d’un mal d’entrailles incurable; et les jours s’écoulèrent, et après deux ans accomplis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Le mal avait fait sortir tous ses intestins, et il mourut dans une angoisse cruelle. Et son peuple ne lui fit point de funérailles comme il en avait fait à Josaphat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Il était monté sur le trône à trente-deux ans, et il avait régné huit ans à Jérusalem, et il n’avait pas marché d’une manière digne de louange, et il fut enseveli dans la ville de David, mais non dans le sépulcre des rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Et les habitants de Jérusalem proclamèrent roi à sa place Ochozias, son plus jeune fils, car l’armée de brigands qui était venue de l’Arabie et des bords de la mer, avait tué ses aînés; ainsi, Ochozias, fils de Joram, monta sur le trône de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Il avait alors vingt ans, et il régna un an à Jérusalem; le nom de sa mère était Athalie; elle était issue d’Ambri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Et il marcha dans les voies de la maison d’Achab, parce que sa mère par ses conseils l’entraînait à pécher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Et il fit le mal devant le Seigneur comme la maison d’Achab, car d’elle seule il prit conseil après la mort de son père, et il se perdit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Marchant donc selon ses conseils, il se joignit à Joram, fils d’Achab, roi d’Israël, pour livrer bataille, à Ramoth-Galaad, au roi de Syrie Azaël, quand des archers atteignirent Joram.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Et Joram revint à Jezraël pour se guérir des blessures que les Syriens lui avaient faites en Ramoth-Galaad, lorsqu’il combattait Azaël, roi de Syrie. Et Ochozias, fils de Joram, roi de Juda, alla voir, en Jezraël, Joram, roi d’Israël, parce qu’il était malade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Et une catastrophe venant de Dieu arriva à Ochozias lorsqu’il y fut; car, alors Joram sortit avec lui contre Jéhu, fils de Namesseï, l’oint du Seignenr, suscité contre la maison d’Achab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Et au moment où Jéhu tirait vengeance de la maison d’Achab, il trouva là les princes de Juda, et les frères d’Ochozias employés à le servir, et il les tua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Ensuite, il ordonna de chercher Ochozias; on le prit en Samarie soignant ses blessures, on le conduisit à Jéhu qui le mit à mort, et on l’inhuma; car, dirent ces gens, il est issu de Josaphat qui de tout son cœur a cherché Dieu; il n’y avait plus personne de la maison d’Ochozias pour fortifier le pouvoir en son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Et Athalie, mère d’Ochozias, voyant son fils mort, se leva et détruisit toute la race royale en Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mais Josabeth, fille du roi Joram, enleva Joas, fils d’Ochozias; elle le déroba du milieu des fils du roi que l’on massacrait; et elle le mit, avec sa nourrice, dans une alcôve des chambres à coucher. Puis, Josabeth, fille de Joram, sœur d’Ochozias, femme de Joad le prêtre, le cacha d’Athalie, qui ne le tua pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Il resta six ans avec Joad caché dans le temple de Dieu, pendant qu’Athalie régnait sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Dans la huitième année, Joad se fortifia, il prit avec lui dans le temple du Seigneur les centeniers Azarias, fils de Joram; Ismaël, fils de Johanan; Azarias, fils d’Obed; Maasaïas, fils d’Adia, et Elisaphan, fils de Zacharie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Ceux-ci parcoururent Juda, rassemblèrent les lévites de toutes les villes de Juda et les chefs de familles d’Israël, et rentrèrent à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Et dans le temple du Seigneur toute l’Église de Juda fit alliance avec le roi, et Joad leur montra le fils du roi, et il leur dit: Voilà le fils du roi: qu’il règne, selon la parole du Seigneur concernant la maison de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Ecoutez donc ce que vous avez à faire: Que le tiers des prêtres et des lévites commence son service de semaine et garde les portes d’entrée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Que l’on place un autre tiers au palais du roi, le dernier tiers à la porte du milieu, et tout le peuple dans les parvis du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Que nul ne pénètre dans le temple hormis les prêtres, les lévites et ceux qui les servent. Ceux-là entreront parce qu’ils sont saints, et tout le peuple fera la garde sainte autour du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Et les lévites entoureront la personne du roi, les armes à la main; ils mettront à mort quiconque s’introduira dans le temple, et ils ne quitteront point le roi, soit qu’il entre, soit qu’il sorte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Les lévites et tout Juda se conformèrent aux ordres de Joad, et ceux qui sortaient de semaine restèrent avec ceux qui entraient en semaine, parce que le grand prêtre ne congédia point ceux dont le service finissait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Et Joad leur délivra les glaives, les boucliers et les armures du roi David, qui étaient dans le temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Et il rangea le peuple, chacun sous ses armes, autour du roi, à l’aile droite du temple, et à l’aile gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Alors, il amena le fils du roi; il lui donna la couronne et les témoignages; puis, Joad le prêtre et ses fils le proclamèrent roi, et ils le sacrèrent, et le peuple cria: Vive le roi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Et Athalie entendit la rumeur du peuple courant, applaudissant, louant le roi, et elle entra auprès du roi dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Et elle regarda, et voilà que le roi était sur son siége; et il y avait aux portes les princes, les trompettes, et, autour du roi, des princes et tout le peuple de la terre plein de joie; et les trompettes sonnaient, et les chantres au son des instruments chantaient des cantiques et des louanges; et Athalie déchira sa robe, et elle s’écria: Vous complotez et complotez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Et Joad s’avança pour donner ses ordres aux centeniers et aux chefs de l’armée, et il leur dit: Jetez-la hors du temple, suivez-la, qu’elle périsse par le glaive; et le prêtre ajouta: Qu’elle ne meure pas dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Et ils la laissèrent libre de ses mouvements, et elle franchit la porte qui mène aux chevaux de la maison du roi, et là, ils la tuèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Et Joad fit alliance avec le roi et avec le peuple, pour que Juda fût le peuple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Et tout le peuple de la terre entra dans le temple de Baal, et ils renversèrent son autel, et ils brisèrent ses idoles, et ils tuèrent devant l’autel Mathan, prêtre de Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Et Joad remit aux prêtres et aux lévites le service du temple de Dieu, rétablit l’ordre des temps où ils devaient être employés, comme l’avait prescrit David, tant pour la garde du temple que pour les offrandes d’holocaustes, selon qu’il est écrit en la loi de Moïse, en y ajoutant les réjouissances et les chants institués par David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Et les portiers veillèrent aux portes du temple, pour que nul homme impur n’y pût entrer sous aucun prétexte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Et il prit les chefs de famille, les vaillants, les chefs du peuple et tout le peuple de la terre, et ils firent monter le roi dans le temple du Seigneur, d’où il alla par la porte intérieure au palais du roi; là, ils assirent le roi sur le trône du royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Et tout le peuple de la terre fut en joie; la ville resta calme: Athalie avait été mise à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas avait sept ans quand il monta sur le trône, et il régna quarante ans à Jérusalem; sa mère s’appelait Sabia de Bersabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Et Joas fit ce qui est droit aux yeux du Seigneur, tant que Joad vécut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Joad lui fit épouser deux femmes, et il engendra des fils et des filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Après cela, la pensée de restaurer le temple entra dans le cœur de Joas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Il réunit donc les prêtres et les lévites, et il leur dit: Allez dans toutes les villes de Juda, et recueillez de tout Israël de l’argent pour réparer, d’année en année, le temple du Seigneur; hâtez-vous de partir. Mais les lévites ne se hâtèrent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Et le roi Joas appela Joad leur chef, et il lui dit: Pourquoi n’as-tu point veillé à ce que les lévites apportassent de Juda et de Jérusalem ce qu’a réglé Moïse l’homme de Dieu, quand il eut rassemblé Israël au sujet du tabernacle du témoignage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Car Athalie était pleine d’iniquité, et ses fils ont ébranlé le temple de Dieu; ils ont employé pour Baal les choses saintes du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Et le roi ajouta: Que l’on fasse une cassette, et qu’on la place extérieurement à la porte principale du temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Et que l’on proclame en Juda et à Jérusalem que chacun ait à apporter pour le Seigneur ce que Moïse, serviteur de Dieu, a dit dans le désert concernant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Alors, tous les chefs donnèrent, tout le peuple donna; chacun apporta son offrande et la jeta dans la cassette, jusqu’à ce qu’elle fût remplie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Or, quand les lévites virent que l’argent abondait, ils portèrent la cassette devant les intendants du roi; le scribe du roi avec l’intendant du grand prêtre vinrent, et ils vidèrent la cassette; puis, ils la remirent à sa place. Ils firent de même chaque jour, et ils recueillirent beaucoup d’argent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Que le roi et Joad donnèrent aux conducteurs des travaux du temple; ceux-ci engagèrent des tailleurs de pierre et des charpentiers, et des hommes habiles à forger le fer et l’airain, pour restaurer le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Et les travailleurs se mirent à l’œuvre, qui prospéra entre leurs mains; ils rétablirent le temple du Seigneur jusqu’aux fondations, et ils le consolidèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Quand ils eurent achevé, ils rapportèrent au roi et à Joad le reste de l’argent, et l’on fit des vases pour le temple du Seigneur, des ustensiles pour le service des holocaustes, des encensoirs d’or et d’argent. Enfin, on offrit des holocaustes perpétuels, tant que vécut Joad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Et Joad devint vieux, et plein de jours, et il mourut âgé de cent trente ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'On l’ensevelit en la ville de David avec les rois, parce qu’il avait été bon envers Israël, envers Dieu et envers son temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Et après sa mort les princes de Juda entrèrent auprès de Joas, et ils se prosternèrent devant lui, et il leur prêta l’oreille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Et ils abandonnèrent le temple du Seigneur Dieu de nos pères, et ils servirent Astarté et les idoles; or, en ce jour-là, il y eut une colère du Seigneur contre Juda et contre Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Il leur envoya des prophètes pour les ramener à lui; mais, ils ne les écoutèrent pas; il leur signifia sa volonté; mais, ils n’obéirent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Alors l’Esprit de Dieu vint sur Zacharie, fils de Joad, le prêtre, et il se plaça devant le peuple, et il s’écria: Voici ce que dit le Seigneur: Pourquoi transgressezvous les commandements du Seigneur? Vous ne prospèrerez pas, car vous avez abandonné le Seigneur, et il vous abandonnera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mais, ils se jetèrent sur lui, et, par l’ordre du roi Joas, ils le lapidèrent dans le parvis du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Ainsi, Joas oublia les bienfaits de Joad, et il fit lapider son fils. Celui-ci dit en mourant: Que le Seigneur voie et juge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Et après que l’année eut fini son cours, l’armée syrienne marcha contre Joas; elle attaqua Juda et Jérusalem; elle extermina, au milieu du peuple, tous les princes, et elle envoya leurs dépouilles au roi de Damas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Elle était venue peu nombreuse; mais Dieu lui avait livré une grande armée, parce que les fils de Juda avaient abandonné le Dieu de leurs pères, et que le Seigneur avait prononcé l’arrêt de Joas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Et après que les Syriens se furent éloignés de celui-ci, lorsqu’ils l’eurent laissé aux prises avec des maux cruels, ses serviteurs eux-mêmes portèrent la main sur lui pour le punir d’avoir versé le sang du fils de Joad le prêtre; ils le tuèrent sur sa couche, et il mourut; et on l’ensevelit dans la ville de David, mais non dans le sépulcre des rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Et ceux qui l’avaient assailli étaient Zabed, fils de Samaath l’Ammonite, et Jozabed, fils de Samareth le Moabite,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Et tous les fils de ce dernier, car il y en avait cinq, qui se joignirent à lui. Le reste est écrit aux Récits des rois; et Amasias, fils de Joas, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amasias avait vingt-cinq ans lorsqu’il monta sur le trône, et il régna vingt-neuf ans à Jérusalem; sa mère s’appelait Joadan de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Et il fit ce qui est droit devant Dieu, mais non avec plénitude de cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Lorsqu’il eut affermi sa royauté, il fit mettre à mort les serviteurs qui avaient tué le roi, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mais il ne fit pas périr leurs fils, se conformant à l’alliance de la loi du Seigneur. Car il est écrit, et tel est le commandement de Dieu: Les pères ne mourront pas à cause de leurs enfants, et les fils ne mourront pas à cause de leurs pères; mais chacun portera la peine de son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Ensuite, Amasias assembla la maison de Juda, et il les mit par familles paternelles sous des chefs de mille hommes et des centeniers, en Juda et en Jérusalem; il fit le dénombrement du peuple depuis vingt ans et au-dessus, et il trouva trois cent mille hommes capables de faire la guerre, sachant manier la javeline et le bouclier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Il enrôla de plus cent mille hommes d’Israël, vaillants et robustes, au prix de cent talents d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Mais un homme de Dieu vint le trouver, disant: Roi, n’emmène pas avec toi les troupes d’Israël, car le Seigneur n’est point avec Israël, ni avec aucun des fils d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Si tu les prends pour te renforcer, le Seigneur te mettra en fuite devant tes ennemis; car il appartient au Seigneur de renforcer une armée ou de la mettre en');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Alors, Amasias dit à l’homme de Dieu: Que deviendront les cent talents d’argent que j’ai donnés aux troupes d’Israël? Et l’homme de Dieu répondit: Il ne tient qu’au Seigneur de t’en rendre beaucoup plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Et Amasias éloigna l’armée qui était venue près de lui d’Ephraïm, pour que chacun retournât en sa demeure. Et ils se courroucèrent vivement contre Juda, et ils s’en allèrent chez eux la colère dans l’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Et Amasias se fortifia, et il prit son peuple, et il alla dans le val des Sels, et il tailla en pièces dix mille des fils de Seïr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Et les fils de Juda firent, en outre, dix mille pri sonniers; ils les transportèrent sur la cime du précipice, et ils les jetèrent au bas des rochers, et ces hommes furent déchirés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Et les hommes de l’armée qu’Amasias avait congédiés, pour qu’ils n’allassent pas en guerre avec lui, attaquèrent les villes de Juda, depuis Samarie jusqu’à Béthoron, et ils y tuèrent trois mille hommes, et ils y firent un riche butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Or, après qu’Amasias revint ayant vaincu l’Idumée, il en rapporta les dieux des fils de Séir, et il les tint pour des dieux véritables, et il se prosterna devant eux, et il leur fit des sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Et la colère du Seigneur s’enflamma contre Amasias, et il lui envoya le prophète, qui lui dit: Pourquoi as-tu cherché les dieux d’un peuple qu’ils n’ont pu délivrer de tes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Et, pendant que le prophète parlait encore, Amasias dit: Est-ce que je t’ai fait conseiller du roi? Contienstoi, si tu ne veux être fustigé. Et le prophète garda le silence, et il se dit: Je sais que le Seigneur a résolu de te détruire, parce que tu as fais cette chose, et que tu refuses d’écouter mes conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Ensuite, Amasias, roi de Juda, délibéra, et il envoya dire à Joas, fils de Joachaz, fils de Jéhu, roi d’Israël: Viens, que nous nous voyions face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Et Joas, roi d’Israël, envoya dire à Amasias: Le chardon du Liban envoya dire au cèdre du Liban: Donne. en mariage ta fille à mon fils; mais voilà que les bêtes fauves des campagnes, qui sont dans le Liban, allaient venir, et les bêtes fauves vinrent, et elles foulèrent aux pieds le chardon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Or, tu as dit: Voilà que j’ai vaincu l’Idumée. Et ton cœur impérieux s’est enorgueilli; reste donc en repos dans ta maison; car, pourquoi te mettre aux prises avec le malheur? Tu tomberas, et Juda avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mais Amasias ne l’écouta pas, car le Seigneur avait dessein de le livrer aux mains de Joas, parce qu’il avait cherché les dieux d’Edom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Joas, roi d’Israël, partit donc, et les deux rois se virent l’un l’autre à Bethsamys en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Et Juda tourna le dos devant Israël, et chacun s’enfuit en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Et Joas fit Amasias prisonnier, et il le ramena à Jérusalem; et il abattit un pan des remparts, long de quatre cents coudées, depuis la porte d’Ephraïm jusqu’à la porte de l’angle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Et il prit l’argent, l’or, tous les ornements qu’il trouvá dans le temple du Seigneur, ce qui provenait d’Abdedom, les trésors du palais du roi, des otages, et il retourna dans Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amasias, fils de Joas, roi de Juda, vécut encore quinze ans après la mort de Joas, fils de Joachaz, roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Les restes des actes d’Amasias, les premiers et les derniers, ne sont-ils pas écrits au livre des Rois de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Dans le temps où Amasias s’était éloigné du Seigneur, un complot éclata contre lui, et il s’enfuit de Jérusalem à Lachis; mais les révoltés envoyèrent à sa poursuite, et, en cette ville, ils le tuèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Et ils l’enlevèrent sur un char, et ils l’ensevelirent auprès de ses pères dans la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Tout le peuple de la terre prit alors Ozias, qui avait seize ans, et ils le proclamèrent roi à la place d’Amasias, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Il rebâtit Elath, et la rendit à Juda lorsque le roi se fut endormi avec ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Ozias avait seize ans quand il monta sur le trône, et il régna cinquante-deux ans à Jérusalem; sa mère s’appelait Jéchélie de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Et il fit ce qui est droit devant le Seigneur, comme avait fait d’abord Amasias, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Il chercha le Seigneur tant que vécut Zacharie, homme sage et craignant Dieu; tant qu’il vécut, Ozias chercha le Seigneur, et le Seigneur le fit prospérer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Il se mit en campagne, combattit les Philistins, renversa les murs de Geth, les murs de Jabner, les murs d’Azot, et bâtit des villes, près d’Azot, sur la terre des étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Et le Seigneur le fortifia contre les Philistins, contre les Arabes qui habitent au milieu des rochers, et contre les Minéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Alors, les Minéens lui firent des présents, et son nom se répandit jusqu’à l’entrée de l’Égypte; car il se fortifia extrêmement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Ozias bâtit aussi des tours dans Jérusalem: sur la porte de l’Angle, sur la porte de la Vallée, sur les angles, et il les fortifia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Et il bâtit des tours dans le désert, et il fit, en pierres de taille, une multitude de citernes, parce qu’il possédait de nombreux troupeaux dans les basses terres et dans la plaine, et il employait beaucoup de vignerons sur la montagne et sur le Carmel, car il était cultivateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Son armée était aguerrie; au dehors, elle se rangeait en bataille; à l’intérieur, elle se déployait pour qu’on en fit la revue; ceux qui la dénombraient étaient le scribe Jehiel, le juge Maasias, et Ananias le lieutenant du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Le nombre des vaillants, chefs de familles, qui allaient en guerre, s’élevait à deux mille deux cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Et ils commandaient une armée aguerrie de trois cent soixante-dix mille cinq cents hommes, qui marchaient au combat, pleins de force et de vaillance, pour défendre le roi contre ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Ozias les avait tous armés de longs boucliers, de javelines, de casques, d’arcs et de frondes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Et il fit exécuter à Jérusalem des machines, œuvres d’un habile calculateur, pour être sur les tours et sur les angles, ou pour lancer des traits ou de grosses pierres; partout, même au loin, on parla beaucoup de ses engins; car il en était merveilleusement secouru, et ẹn tirait une grande force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mais, comme il se fortifiait, son cœur s’enorgueillit pour sa perte; et il pécha contre le Seigneur son Dieu, et il entra dans le temple du Seigneur pour brûler de l’encens sur l’autel des parfums.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Et Azarias le prêtre y entra sur ses pas, accompagné de quatre-vingts prêtres du Seigneur, hommes intrépides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Et ils s’arrêtèrent devant le roi Ozias, et ils lui dirent Ce n’est pas à toi, Ozias, d’encenser le Seigneur, mais aux prêtres, fils d’Aaron, qui sont consacrés pour faire les sacrifices. Sors du Saint des saints, car tu t’es séparé du Seigneur, et cela ne tournera pas à ta gloire auprès de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Mais Ozias s’irrita; or, il avait à la main l’encensoir pour brûler de l’encens dans le temple, et, pendant qu’il s’irritait contre les prêtres, la lèpre parut sur son front, devant les prêtres dans le temple du Seigneur, au pied de l’autel des parfums.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Et le grand prêtre Azarias et les prêtres, en se retournant vers lui, virent la lèpre sur son front; ils eurent hâte de le faire sortir, et lui-même n’était pas moins empressé, car le Seigneur l’avait châtié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Le roi Ozias resta lépreux jusqu’au jour de sa mort; et lépreux, il demeura dans une maison isolée, parce qu’il avait été retranché du temple du Seigneur. Et Joatham, son fils, fut mis à la tête du royaume, jugeant le peuple de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Le reste des actes d’Ozias, les premiers et les derniers, ont été écrits par le prophète Jessé (Isaïe).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Et Ozias s’endormit avec ses pères, et on l’ensevelit auprès d’eux, dans le champ où est le sépulcre des rois, parce que, dirent-ils, il était lépreux. Et Joatham, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Joatham avait vingt-cinq ans lorsqu’il monta sur le trône, et il régna seize ans à Jérusalem; sa mère s’appelait Jerusa, fille de Sadoc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Et il fit ce qui est droit devant le Seigneur, comme avait fait Ozias, son père; mais il n’entra point dans le temple du Seigneur, et le peuple, encore une fois, se corrompit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Ce fut lui qui bâtit la porte du temple la plus élevée, et il ajouta beaucoup de constructions au mur d’Ophel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Dans la montagne de Juda et dans les bois, il éleva des maisons et des tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Il combattit le roi des fils d’Ammon, et le vainquit; les fils d’Ammon alors lui donnèrent par année cent talents d’argent, dix mille mesures de froment et dix mille mesures d’orge. Il reçut ce tribut la première année, et la seconde, et la troisième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Joatham avait été vainqueur, parce qu’il avait marché dans les voies du Seigneur son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Le reste des actes de Joatham; et sa guerre, et ses faits et gestes sont écrits au livre des Rois de Juda et d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Et Joatham s’endormit avec ses pères, et on l’ensevelit en la ville de David, et son fils Achaz régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Achaz avait vingt-cinq ans lorsqu’il monta sur le trône, et il régna seize ans à Jérusalem; et il ne fit point ce qui est droit devant le Seigneur, comme David, son aïeul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Mais il marcha dans les voies des rois d’Israël, car il fit des sculptures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Et il sacrifia à leurs idoles dans le val de Benennom, et il fit passer ses enfants à travers la flamme, selon les abominations des peuples que le Seigneur avait exterminés devant les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Et il brûla de l’encens sur les hauts lieux, et sur les terrasses des maisons, et sous les arbres touffus,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Alors le Seigneur Dieu le livra au roi de Syrie; il le frappa par ses mains, en permettant aux Syriens d’emmener à Damas une multitude de captifs; il le livra aussi au roi d’Israël, et de ses propres mains, il le frappa d’une grande plaie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Phacée, fils de Romélie, roi d’Israël, tua, en un seul jour, cent vingt mille hommes de Juda, forts et vaillants, parce qu’ils avaient abandonné le Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Et Zéchri, homme vaillant d’Ephraïm, tua Maasias, fils du roi; Esrican, son grand maître du palais, et Elcana, son lieutenant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Et les fils d’Israël firent parmi leurs frères trois cent mille captifs femmes, fils et filles; et ils leur enlevèrent un immense butin, et emportèrent les dépouilles à Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Or, il y avait là un prophète du Seigneur nommé Obed, qui sortit à la rencontre de l’armée pendant qu’elle revenait à Samarie, et il leur dit: Voilà que la colère du Seigneur Dieu de vos pères est sur Juda; il vous les a livrés, et vous les avez massacrés avec fureur, et le bruit en est monté jusqu’au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Et maintenant vous pensez garder comme esclaves les fils de Juda et de Jérusalem; mais ne suis-je point parmi vous pour prendre à témoin le Seigneur votre Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Écoutez-moi donc, et délivrez les captifs que vous avez enlevés chez vos frères; car la colère du Dieu terrible est sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Et les chefs des fils d’Ephraïm: Udie, fils de Jean; Barachias, fils de Mosolmoth; Ezéchias, fils de Sellem; et Amasias, fils d’Eldaï, s’élevèrent pareillement contre ceux qui revenaient du combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Et ils leur dirent: Vous n’introduirez point ici, chez nous, ces captifs; car, lorsque vous péchez contre le Seigneur, votre péché retombe sur nous; et vous entendez ajouter à vos péchés et à vos délits par ignorance, quand déjà vos fautes sont nombreuses, et quand une terrible colère du Seigneur est sur Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Et les guerriers mirent en liberté les captifs, et ils leur rendirent les dépouilles, devant les chefs de toute l’Église.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Et les hommes qui viennent d’être nominativement désignés, se levèrent, prirent soin des captifs, les vêtirent d’objets compris dans les dépouilles, les habillèrent, les chaussèrent, leur donnèrent des vivres pour manger, de l’huile pour se parfumer, firent monter les infirmes sur des ânes, les menèrent avec leurs frères jusqu’à Jéricho, ville des palmiers, et retournèrent à Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'En ce temps-là, le roi Achaz envoya chez le roi assyrien demander son secours, et voici pourquoi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Les Sidoniens faisaient des irruptions; ils frappaient Juda, et lui enlevaient des captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Les Philistins aussi avaient pris les armes contre les villes de la plaine, au midi de Juda, et s’étaient emparés de Bethsamys, d’Aïlon, de Galero, de Socho et de ses bourgs, de Thamna et de ses bourgs, de Gamzo et de ses bourgs, et ils s’y étaient établis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Car le Seigneur avait humilié Juda, à cause du roi Achaz qui s’était détourné du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Alors, Thelgath-Phalnasar, roi des Assyriens, intervint, mais contre lui, et il l’opprima.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Et Achaz prit les richesses du temple du Seigneur, celles du palais du roi, celles des demeures des princes, et il les donna au roi assyrien; or, celui-ci n’était pas venu pour le secourir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Mais pour l’écraser; cependant, le roi Achaz continua de se détourner du Seigneur, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Je chercherai les dieux de Damas qui me frappent. Puis, il ajouta: Ce sont les dieux du roi de Syrie qui lui donnent de la force; je leur sacrifierai donc, et ils me protégeront. Et ils furent une cause de chute pour lui et pour Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Achaz retira donc les vases du temple du Seigneur, il les brisa, ferma les portes du temple, et se fit des autels dans tous les carrefours de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Et il établit des hauts lieux dans toutes les villes de Juda pour que l’on y encensât des dieux étrangers; et les fils de Juda excitèrent le courroux du Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Le reste de ses faits et gestes, les premiers et les derniers, sont écrits au livre des Rois de Juda et d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Et Achaz s’endormit avec ses pères, et il fut enseveli en la ville de David; mais on ne le transporta pas dans le sépulcre des rois d’Israël, et son fils Ezéchias régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezéchias avait vingt-cinq ans lorsqu’il monta sur le trône, et il régna vingt-neuf ans à Jérusalem; sa mère s’appelait Abia, fille de Zacharie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Et il fit ce qui est droit devant le Seigneur, se conformant à tout ce qu’avait fait David, son aïeul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Dès qu’il fut affermi dans son royaume, le premier mois, il ouvrit les portes du temple du Seigneur, et il les restaura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Et il introduisit dans le temple les prêtres et les lévites, et il les réunit dans l’aile orientale de l’édifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Et il leur dit: Écoutez, lévites, purifiez-vous d’abord; puis, vous purifierez le temple du Dieu de vos pères, et vous rejetterez toute impureté du lieù saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Car vos pères se sont pervertis et ils ont fait le mal devant le Seigneur notre Dieu; ils l’ont abandonné, ils ont détourné leur face du tabernacle du Seigneur, et s’en sont éloignés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Ils ont fermé les portes du temple, ils ont éteint les lampes, ils n’ont plus brûlé d’encens, ils ont cessé d’offrir des holocaustes dans le lieu saint du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Alors, le Seigneur s’est vivement irrité contre Juda et contre Jérusalem; il les a livrés au trouble, à l’extermination et aux railleries, comme vous l’avez vu de vos yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Vos pères ont été frappés par le glaive; vos fils, vos filles et vos femmes, ont été emmenés captifs en une contrée étrangère, où ils sont encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'A cause de cela, il est maintenant en mon cœur de faire alliance avec le Seigneur Dieu d’Israël, et il détournera de nous sa terrible colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Ne différez pas, car le Seigneur vous a choisis pour que vous vous teniez en sa présence, pour que vous le serviez et que vous brûliez devant lui de l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Et les lévites se levèrent, savoir: Des fils de Caath, Maath, fils d’Amasi, et Johel, fils d’Azarias; des fils de Mérari Cis, fils d’Abdi, et Azarias, fils d’llaélel; des f’s de Gerson: Jodaad, fils de Zemmath, et Joadam; ceux-ci descendaient de Joacha;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Des fils d’Elisaphan: Zambri et Jehiel; des fils d’Asaph Zacharie et Matthanias;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Des fils d’Hêman: Jehiel et Sémeï; des fils d’Idithun Samaïas et Oziel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Et ils réunirent leurs frères, et ils se purifièrent selon l’ordre du roi, pour purifier ensuite le peuple du Seigneur, comme lui-même l’avait prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Et les prêtres entrèrent dans le temple du Seigneur pour le purifier, et ils rejetèrent toute impureté qu’ils trouvèrent dans le temple et dans le parvis; puis, les lévites prirent les choses impures pour les porter au torrent de Cédron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'La purification commença le premier jour du premier mois, pendant la nouvelle lune, et, le huitième jour, ils entrèrent dans le temple du Seigneur, et ils le purifièrent en huit jours; le seizième jour du premier mois, tout était terminé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Et ils allèrent trouver le roi Ezéchias, et ils lui dirent: Nous avons tout purifié dans le temple du Seigneur: l’autel des holocaustes et ses ustensiles, la table de proposition et ses accessoires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Tous les objets que le roi Achaz avait souillés pendant son règne et son apostasie, nous les avons purifiés et mis en ordre; voilà que tout est exposé devant l’autel du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Et le roi Ezéchias se leva de grand matin, et il assembla tous les chefs de la ville, et il monta au temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Et il offrit sept bœufs, sept béliers, sept agneaux et sept boucs, pour les péchés, pour le royaume, pour les saints et pour Israël; et il dit aux prêtres, fils d’Aaron, de monter à l’autel du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Et ils immolèrent les bœufs, et ils recueillirent le sang, et ils le répandirent sur l’autel; et ils immolèrent les béliers, et ils répandirent le sang sur l’autel; et ils immolèrent les agneaux, et ils répandirent le sang sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Et ils traînèrent devant le roi et devant l’assemblée entière les boucs pour les péchés, et ils imposèrent sur eux les mains;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Et les prêtres les immolèrent, et ils firent l’expiation en versant leur sang devant l’autel, et ils firent l’expiation en faveur de tout Israël; car le roi avait dit: L’holocauste et le sacrifice pour les péchés sont pour tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Et il établit les lévites dans le temple du Seigneur au son des cymbales, des cithares et des harpes, comme l’avait réglé le roi David, d’accord avec Gad le voyant, et Nathan le prophète; car le Seigneur transmet ses commandements par les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Les lévites furent installés au son des instruments de David, et les prêtres au son des trompettes sacrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Ensuite, Ezéchias ordonna de porter l’holocauste sur l’autel; et, lorsque l’on commença l’offrande de l’holocauste, on commença à chanter les louanges du Seigneur, au son des trompettes et des instruments de David, roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Et toute l’Église adora, et les chantres-harpistes chantèrent, et les trompettes sonnèrent jusqu’à ce que l’holocauste fût achevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Et, lorsque les victimes furent consumées, le roi se prosterna, ainsi que toute l’assistance, et ils adorèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Et le roi Ezéchias et les princes dirent aux lévites de chanter au Seigneur les psaumes tant du roi David que du prophète Asaph; ils chantèrent avec allégresse; puis, se prosternant, ils adorèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Et le roi Ezéchias prit la parole, et dit: Maintenant que vous vous êtes consacrés au Seigneur, amenez et offrez les victimes de louanges dans le temple du Seigneur; et l’Église offrit dans le temple des sacrifices et des louanges; et ceux qui avaient le cœur plein de zèle amenèrent des holocaustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Voici le nombre des holocaustes qu’offrit l’Église: soixante-dix boeufs, cent béliers, deux cents agneaux; tous pour les holocaustes au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Il y eut en outre six cents bœufs consacrés, et trois mille brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Or, les prêtres étaient en petit nombre, et ils ne suffisaient pas à enlever les peaux des victimes; leurs frères, les lévites, les aidèrent jusqu’à ce que l’œuvre fût achevée, et que les prêtres se fussent purifiés; car les lévites sont plus promptement purifiés que les prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Il y eut donc nombre de victimes pour les holocaustes; on brûla en grande quantité la graisse des hosties pacifiques, on répandit à flo’s les libations de l’holocauste, et les cérémonies du temple furent rétablies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Et Ezéchias et tout le peuple ressentirent une vive allégresse de ce que Dieu avait préparé cette fète à son peuple; car la chose s’était faite soudainement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Et Ezéchias envoya en tout Israël et en Juda, et il écrivit des lettres à Ephraim et à Manassé, pour qu’ils vinssent au temple du Seigneur à Jérusalem, faire la Pâque du Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Et le roi, et les princes et toute l’Église de Jérusalem, résolurent de faire la Pâque le second mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Car ils ne la pouvaient faire en ce moment, parce qu’il n’y avait point assez de prêtres consacrés, et que tout le peuple n’était point réuni à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Et cette décision fut agréable au roi et à toute l’Église.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Ils ordonnèrent aussi que l’on proclamât en tout Israël, depuis Bersabée jusqu’à Dan, que l’on eût à venir pour faire la Pàque du Seigneur Dieu à Jérusalem; car la multitude ne l’avait jamais faite comme le prescrit l’Écriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Les courriers, avec les lettres du roi et des princes, parcoururent tout Juda et tout Israël, selon l’ordre d’Ezéchias, et ils dirent: Fils d’Israël, revenez au Seigneur Dieu d’Abraham, d’Isaac et d’Israël; ramenez ceux dé vous qui survivent et qui ont échappé aux mains du roi d’Assyrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Ne soyez pas comme vos pères et vos frères; ils se sont séparés du Seigneur Dieu de leurs pères, et le Seigneur les a livrés à la dévastation, comme vous avez vu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Maintenant donc, n’endurcissez point vos cœurs comme vos pères; glorifiez le Seigneur votre Dieu, entrez dans le lieu saint qu’il a consacré pour toujours; servez le Seigneur votre Dieu, et il détournera de vous sa terrible colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Car, lorsque vous serez revenus au Seigneur, vos frères et vos enfants trouveront miséricorde chez ceux qui les ont emmenés captifs, et Dieu vous les ramènera en cette terre; car le Seigneur notre Dieu est miséricordieux et compatissant, et il ne détournera point de vous sa face, si nous retournons à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Et les courriers passèrent de ville en ville, dans les montagnes d’Ephraïm et de Manassé, jusqu’à Zabulon, et ils furent un sujet de risée et de raillerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Toutefois, des hommes d’Aser, de Manassé et de Zabulon, rentrèrent en eux-mêmes, et vinrent à Jérusalem en Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Car la main du Seigneur excita leur cœur à partir et à suivre les ordres du roi et des princes, selon la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Une grande multitude se réunit donc à Jérusalem pour faire la fête des azymes le second mois; l’Église fut très-nombreuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Et ils se levèrent, et ils abattirent dans Jérusalem tous les autels où l’on brûlait de l’encens pour les faux dieux; ils les enlevèrent et les jelèrent dans le torrent de Cédron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Et ils immolèrent la pâque le quatorzième jour de la seconde lune, et les prêtres et les lévites, s’étant repentis et purifiés, offrirent des holocaustes dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Et chacun se tint à son rang, selon leur ordonnance et selon les commandements de Moïse, homme de Dieu; les prêtres reçurent le sang des mains des lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Car la plus grande partie de l’Église ne s’était point encore sanctifiée, et les lévites étaient prêts à immoler la pâque pour tous ceux qui n’avaient pu se sanctifier au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Parmi le peuple d’Ephraïm, de Manassé, d’Issachar, de Zabulon, le plus grand nombre ne s’était pas purifié; mais ils mangèrent la pâque contrairement à l’Écriture; à cause de cela, Ezéchias fit pour eux cette prière, disant Que le Seigneur, dans sa bonté, soit propice');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'A tous les cœurs qui cherchent avec droiture le Seigneur Dieu de leurs pères, quoiqu’ils n’aient point la pureté que veulent les choses saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Et le Seigneur exauça Ezéchias, et il guérit tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Et les fils d’Israël, qui se trouvaient à Jérusalem, firent la fête des Azymes sept jours, en grande allégresse, célébrant chaque jour le Seigneur; et les prêtres et les lévites accompagnaient leurs chants avec les instruments consacrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Et Ezéchias parla au cœur des lévites et de tous ceux qui comprenaient le mieux le Seigneur, et ils firent la fête des Azymes sept jours, sacrifiant l’hostie pacifique, et rendant gloire au Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Et l’Église résolut de fêter une seconde fois sept jours, et ils les fêtèrent avec joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Car Ezéchias offrit à Juda et à l’Église mille bœufs et sept mille brebis, et les princes amenèrent, pour le peuple, mille bœufs et dix mille brebis, et il y eut une multitude de prêtres qui furent sanctifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Et toute l’Église était pénétrée de joie: prêtres, lévites, Église de Juda, peuple réuni à Jérusalem, prosélytes venus de la terre d’Israël, étrangers habitant Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Et l’allégresse fut grande en Jérusalem; on n’y avait point vu pareille fête depuis les jours de Salomon et de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Et les prêtres et les lévites se levèrent, et ils bénirent le peuple, et leur voix fut entendue, et leur prière monta jusqu’aux saintes demeures de Dieu dans le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Et, quand tout fut fini, ceux d’Israël qui se trouvaient dans les villes de Juda sortirent, brisèrent les colonnes, arrachèrent les bois sacrés, démolirent les hauts lieux et les autels, dans tout Juda, dans Benjamin, dans Ephraïm, dans Manassé jusqu’à la tin; et ceux d’Israël rentrèrent chacun en son héritage et en sa ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Et Ezéchias régla les services des prêtres et des lévites, chacun selon son emploi, tant pour les holocaustes que pour les hosties pacifiques, les louanges, les actions de grâces, et la garde des portes ou des parvis du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Il régla aussi la part que devait donner le roi, de ce qui lui appartenait, pour les holocaustes du matin et du soir, pour les holocaustes des sabbats, des nouvelles lunes et des fêtes désignées en la loi du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Et il dit au peuple qui habitait Jérusalem de donner la part des prêtres et des lévites, afin qu’ils fussent affermis dans le service du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Or, dès qu’il eut ordonné ces choses, Israël apporta en abondance les prémices du blé, du vin, de l’huile, du miel et de ce que produisent les champs; les fils d’Israël et de Juda apportèrent des dimes abondantes de tous leurs fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Et ceux qui habitaient les villes de Juda offrirent aussi la dîme de leurs boeufs, de leurs brebis, de leurs chèvres; et ils la consacrèrent au Seigneur leur Dieu, et ils apportèrent, et ils offrirent de toutes choses des monceaux, des monceaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Et ils commencèrent, le troisième mois, à empiler ces monceaux, et eurent fini le septième mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Et le roi Ezéchias et les princes vinrent, et ils virent ces monceaux, et ils bénirent le Seigneur et son peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Et Ezéchias questionna les prêtres et les lévites au sujet de ces monceaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Et le prêtre Azarias, chef de la maison de Sadoc, lui dit Depuis que l’on apporte de ces prémices dans le temple du Seigneur, nous avons bu, nous avons mangé et nous avons laissé beaucoup; car le Seigneur a béni son peuple, et ces monceaux nous sont restés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Et le roi ordonna que l’on préparât des magasins dans le temple du Seigneur, et on les prépara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Et l’on y transporta fidèlement les prémices et les dîmes, dont on donna l’intendance au lévite Honénias et à Sémeï, son frère et son lieutenant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Et Jehiel, Ozias, Naeth, Azaël, Jerimoth, Jozabad, Elihel, Samachie, Maath, Banaïas et ses fils, furent subordonnés à Honénias et à son frère Sémeï; ainsi que l’ordonnèrent le roi Ezéchias et Azarias, qui avait le premier rang dans le temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Et Coré le lévite, fils de Jemna, gardien de la porte orientale, eut l’intendance des dons que l’on faisait, soit comme prémices du Seigneur, soit pour le Saint des saints,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Par les mains d’Odom, de Benjamin, de Jésué, de Sémeï, d’Amarias et de Séchonias, ou par celles des prêtres à qui l’on se confiait; et ils en faisaient la distribution à leurs frères, selon leurs services journaliers, du petit au grand,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Hormis les enfants mâles de trois ans et au-dessous, à tous ceux qui entraient dans le temple du Seigneur, selon l’ordre des jours, pour s’acquitter des fonctions qui leur étaient assignées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Ainsi se fit la distribution aux prêtres, par familles paternelles. Quant aux lévites de vingt ans et au-dessus, pendant leurs services journaliers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Ils purent, dans leur classification, compter même leurs jeunes enfants, fils ou filles, quel qu’en fût le nombre, parce qu’ils avaient purifié fidèlement le sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Aux fils d’Aaron, exerçant le sacerdoce dans les villes, des hommes, nommés à cet effet en chaque ville, donnaient aussi une portion pour chaque mâle, parmi les prêtres; ils en donnaient pareillement à ceux qui étaient comptés comme lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Ezéchias établit cet ordre en tout Juda, et il fit ce qui est bon et droit devant le Seigneur son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Et en toute œuvre qu’il entreprit dans le temple du Seigneur, dans ses lois, dans ses ordonnances, il chercha son Dieu de toute son âme, et il agit, et il prospéra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Or, après ces choses faites avec sincérité, Sennachérib, roi des Assyriens, vint envahir Juda, et campa devant les villes fortes pour s’en emparer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Et Ezéchias vit que Sennachérib s’avançait et menaçait Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Et il tint conseil avec ses anciens et ses vaillants, leur proposant de clore les fontaines hors de la ville; et ils l’appuyèrent de toute leur force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Il assembla donc beaucoup de monde, et il renferma en des murs les eaux des fontaines, ainsi que le ruisseau qui traverse la ville, disant: C’est de peur que le roi d’Assyrie, venant, ne trouve une abondance d’eau qui le fortifierait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Et Ezéchias augmenta ses défenses; il rétablit toutes es parties des remparts qui s’étaient écroulées et les tours; il bâtit en dehors une seconde enceinte, il releva les fortifications de la ville de David; enfin, il fit faire beaucoup d’armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Ensuite, il mit des chefs de guerre à la tête du peuple qui s’assembla devant lui sur l’esplanade, vers la porte de la Vallée, et il lui parla au cœur, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Soyez forts, agissez en hommes, n’ayez ni crainte ni faiblesse devant le roi d’Assyrie, et devant les peuples qui le suivent; car il y a plus d’auxiliaires avec nous qu’avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Il a pour lui des bras de chair; nous, nous avons le Seigneur notre Dieu, qui combattra pour nous et nous sauvera. Et le peuple fut encouragé par le discours d’Ezéchias, roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Après cela, Sennacherib, roi des Assyriens, envoya ses serviteurs à Jérusalem, et lui-même, avec toute son armée, était autour de Lachis, et il envoya ses serviteurs au roi Ezéchias et à tout le peuple de Juda renfermé dans Jérusalem, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Voici ce que dit Sennacherib, roi des Assyriens: Sur quoi vous appuyez-vous pour rester immobiles dans l’enceinte de Jérusalem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Ezéchias ne vous a-t-il pas trompés, pour vous livrer à la faim, à la soif, à la mort, quand il vous a dit: Le Seigneur notre Dieu nous sauvera des mains du roi d’Assyrie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'N’est-ce point cet Ezéchias qui a détruit ses autels et ses hauts lieux, et qui a dit à Juda et à Jérusalem: Vous adorerez sur cet autel, et, sur cet autel, vous offrirez de l’encens?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ignorez-vous ce que moi et mes pères avons fait aux peuples de toute la terre? Parmi les dieux des nations de la terre, en est-il un seul qui ait pu sauver son peuple de mes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Qui l’a fait, parmi les dieux des nations que nos pères ont exterminées? Si nul d’eux n’a pu sauver son peuple de nos mains, votre Dieu pourra-t-il le faire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Qu’Ezéchias cesse donc de vous tromper, qu’il ne vous inspire pas une folle confiance, ne le croyez pas; car nul, des dieux des nations et des royaumes, n’a pu sauver son peuple de mes mains et des mains de nos pères, et votre Dieu ne vous sauvera pas non plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Or, les serviteurs de Sennachérib continuèrent de parler contre le Seigneur Dieu et contre son serviteur Ezéchias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Lui-même écrivit une lettre pour outrager le Seigneur Dieu d’Israël, et il dit: De même que les dieux des nations de la terre n’ont pu délivrer leurs peuples de mes mains, le Dieu d’Ezéchias ne pourra en aucune manière sauver son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Et l’un des serviteurs cria, en langue judaïque, au peuple de Jérusalem qui se tenait sur les remparts, l’invitant à haute voix à les seconder à démolir les murailles, à leur livrer la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Il parla aussi contre le Seigneur Dieu d’Israël, de la même manière que contre les dieux des nations de la terre, œuvres des mains des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Et, sur ces paroles, le roi Ezéchias et le prophète Isaïe, fils d’Amos, prièrent, et crièrent au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Et le Seigneur envoya un ange, et il extermina dans le camp assyrien tous les combattants, les chefs et les généraux. Et Sennacherib, la honte au front, retourna en son royaume, et il entra dans le temple de son Dieu; et des hommes, issus de son sang, le firent périr par le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Et le Seigneur sauva Ezéchias, ainsi que les habitants de Jérusalem, des mains de Sennachérib, roi d’Assyrie, et des mains de tous les rois, et il leur donna le repos tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Et nombre de gens apportèrent à Jérusalem des présents pour le Seigneur et pour Ezéchias, roi de Juda, et, après cela, il fut glorifié aux yeux de toutes les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'En ces jours-là, Ezéchias tomba malade à en mourir, et il pria le Seigneur, et le Seigneur l’exauça, et il lui donna un signe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mais Ezéchias ne lui rendit pas selon ce qu’il en avait reçu; son cœur s’enorgueillit, et la colère du Seigneur éclata contre le roi, contre Juda, contre Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Et Ezéchias s’humilia de s’être enorgueilli en son cœur, et, avec lui, tous les habitants de Jérusalem; et la colère du Seigneur ne vint plus sur eux tant que vécut Ezéchias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Et Ezéchias eut beaucoup de gloire et de richesses; il amassa, en ses trésors, de l’or, de l’argent, des pierreries; il eut des épices, des vases de prix et des arsenaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Il eut des villes où l’on conservait du blé, du vin et de l’huile; il eut des villages et des étables pour toute sorte de bétail, et des bergeries pour les menus troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Il eut des villes, qu’il bâtit pour lui-même, et une grande abondance de bœufs et de brebis; car le Seigneur lui donna d’immenses richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Ce fut Ezéchias qui fit l’aqueduc qui amena les eaux de la haute fontaine de Gihon en la ville basse de David, au midi. Ezéchias réussit en toutes ses entreprises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Néanmoins, le Seigneur l’abandonna pour l’éprouver et savoir ce qu’il avait dans le cœur, lorsque les envoyés des chefs de Babylone vinrent le trouver et le questionner sur le prodige qui avait éclaté en la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Le reste des actes d’Ezéchias et sa miséricorde sont écrits en la prophétie d’Isaïe, fils d’Amos, le prophète, et au livre des Rois de Juda et d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Et Ezéchias s’endormit avec ses pères, et on l’ensevelit au-dessus des sépulcres des fils de David; et tout Juda et les habitants de Jérusalem l’honorèrent et le glorifièrent à sa mort. Et Manassé, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manassé avait douze ans lorsqu’il monta sur le trône, et il régna cinquante-cinq ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Il fit le mal devant le Seigneur, et commit toutes les abominations des peuples que le Seigneur avait exterminés devant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Il se pervertit, et il releva les hauts lieux qu’avait détruits Ezéchias, son père; il dressa des colonnes à Baal, planta des bois sacrés, adora toute l’armée du ciel, et la servit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Et il bâtit des autels dans le temple dont le Seigneur avait dit: Mon nom sera toujours dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Et il bâtit des autels à toute l’armée du ciel, dans les deux parvis du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Et il fit passer ses enfants à travers la flamme dans le val de Benennom; et il consulta les devins, les augures et les sorciers; il accueillit des ventriloques et des enchanteurs; il fit de plus en plus le mal devant le Seigneur, pour exciter sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Et il plaça des statues et des images en fonte dans le temple dont le Seigneur avait dit à David et à Salomon, son fils En ce temple et à Jérusalem, que j’ai choisis parmi toutes les tribus d’Israël, j’établirai mon nom pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Et je n’éloignerai plus le pied d’Israël de la terre que j’ai donnée à leurs pères, pourvu qu’ils soient attentifs à faire tout ce que je leur ai commandé, en se conformant à toute la loi, aux ordonnances et aux jugements donnés par la main de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Ainsi, Manassé égara Juda et les habitants de Jérusalem, pour qu’ils fissent le mal, plus que toutes les nations que le Seigneur avait exterminées devant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Et le Seigneur parla à Manassé et à son peuple; mais ils ne l’écoutèrent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Et le Seigneur conduisit contre eux les chefs de l’armée du roi d’Assyrie, et ils prirent Manassé, et ils le chargèrent de chaînes, et ils l’emmenèrent à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Et, dans son affliction, il chercha la face du Seigneur son Dieu, et il s’humilia beaucoup devant la face du Seigneur Dieu de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Et il le pria; or, Dieu entendit ses cris; il l’exauça, et le ramena à Jérusalem dans son royaume, et Manassé reconnut que le Seigneur seul est Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Après cela, il bâtit le mur extérieur de la ville de David, du côté du midi, au sud du torrent, depuis l’entrée de la porte des Poissons, continuant tout autour jusqu’à Ophe!; il l’éleva beaucoup, et il établit des chefs de l’armée dans toutes les places fortes de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Et il enleva les dieux étrangers et les statues du temple du Seigneur, et les autels qu’il avait dressés sur la montagne du temple du Seigneur, tant dans Jérusalem que hors de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Et il releva l’autel du Seigneur, et il y sacrifia des hosties pacifiques et des victimes de louanges; et il dit à Juda de servir le Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Toutefois, le peuple sacrifia encore sur les hauts lieux; mais seulement au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Le reste des actes de Manassé, sa prière à Dieu, et les paroles des voyants qui lui parlèrent au nom du Seigneur Dieu d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'La prière qu’il fit à Dieu et qui fut exaucée, ses péchés, ses égarements, et les endroits où il bâtit des hauts lieux, et où il plaça des bois sacrés et des statues, avant de se convertir, sont écrits aux Récits des voyants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Et Manassé s’endormit avec ses pères, et on l’ ensevelit dans le jardin de son palais, et son fils Amon régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon avait vingt-deux ans quand il monta sur le trône, et il régna deux ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Et il fit le mal devant le Seigneur, comme avait fait son père; il sacrifia à toutes les idoles qu’avait faites Manassé, et il les servit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Et il ne s’humilia pas devant le Seigneur, comme s’était humilié son père; et il multiplia ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Et ses serviteurs se soulevèrent contre lui, et ils le tuèrent dans son palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Et le peuple de la terre massacra les révoltés, et il proclama roi, à la place d’Amon, Josias, son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josias avait huit ans quand il monta sur le trône, et il régna trente et un ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Il fit ce que est droit devant le Seigneur, et il marcha dans les voies de David, son aïeul; il ne s’en écarta ni à droite ni à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Et, dans la huitième année de son règne, il était encore un adolescent quand il commença à chercher le Seigneur Dieu de David; et, dans la douzième année, il se mit à purifier Juda et Jérusalem des hauts lieux, des bois sacrés, des ornements des autels et des idoles jetées en fonte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Et il renversa, de devant sa face, les autels de Baal et, au-dessus d’eux, les hauts lieux; il abattit les bois sacrés et les statues; il brisa les idoles jetées en fonte, il les réduisit en poudre, et les jeta sur la surface des tombeaux de ceux qui leur avaient sacrifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Et il brûla les ossements de leurs prêtres sur les autels; et il purifia Jérusalem et Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Puis, les villes de Manassé, d’Ephraïm, de Siméon et de Nephthali, et les bourgs qui les environnaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Et il détruisit les autels et les bois sacrés, et il réduisit en poudre les idoles, et il renversa tous les hauts lieux d’Israël, et il revint à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Dans la dix-huitième année de son règne, après avoir purifié la terre et son palais, il envoya Saphan, fils d’Ezélias, Maasa, chef de la ville, et Juach, fils de Joachaz, son secrétaire-archiviste, pour réparer le temple du Seigneur son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Il se rendirent auprès d’Helcias, le grand prêtre, et ils lui donnèrent l’argent offert au temple de Dieu, recueilli, par les lévites gardiens de la porte, des mains de Manassé, d’Ephraïm, des princes, de tout le reste d’Israël, des fils de Juda et de Benjanin, et des habitants de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Et ils donnèrent cet argent à ceux qui faisaient les travaux, qu’on avait établis dans le temple du Seigneur; ils le donnèrent à ceux qui faisaient ce qu’il y avait à faire pour restaurer et raffermir le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Ils ordonnèrent aussi aux charpentiers et aux maçons d’acheter des pierres de taille et des solives pour recouvrir les logements que les rois de Juda avaient abattus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Et ces hommes se mirent fidèlement à l’œuvre, et ils furent surveillés par Jeth et Abdias, lévites de la maison de Mérari, par Zacharie et Mosollam, des fils de Caath, et par tous les lévites qui savaient chanter et jouer des instruments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Et les manoeuvres et les ouvriers, chacun en son travail, étaient encore surveillés par les lévites scribes, juges et portiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Or, tandis que l’on transportait l’argent donné pour le temple du Seigneur, Helcias, le prêtre, trouva un livre de la loi du Seigneur donnée par Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Et Helcias prit la parole, et il dit à Saphan, le scribe: J’ai trouvé dans le temple du Seigneur un livre de la loi. Et Helcias donna le livre à Saphan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Et Saphan porta le livre au roi, et il lui rendit compte, disant: Voici le compte de tout l’argent qui a été remis à tes serviteurs chargés des travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Or, cet argent, trouvé dans le temple du Seigneur, avait été monnayé et distribué aux surveillants, puis aux ouvriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Et Saphan en rendit compte au roi, et il ajouta: Helcias m’a donné un livre. Et Saphan le lut devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Et quand Josias ouït les paroles du livre de la loi, il déchira ses vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Et il donna ses ordres à Helcias, à Achicam, fils de Saphan, à Abdom, fils de Michée, à Saphan, le scribe, à Asaïe, serviteur du roi, et il leur dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Allez et interrogez le Seigneur, pour moi et pour tout ce qui reste de Juda et d’Israël, au sujet des paroles du livre qui a été trouvé; car la colère du Seigneur s’est enflammée contre nous, parce que nos pères n’ont point obéi aux commandements du Seigneur, et n’ont point fait ce qui est écrit en ce livre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Or, Helcias et ceux à qui avait parlé le roi, allèrent trouver Olda, la prophétesse, femme de Sellem, fils de Thécoé, fils d’Aras; elle observait les commandements, et demeurait à Jérusalem dans le second quartier, et ils lui parlèrent relativement à ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Et elle leur répondit: Voici ce que dit le Seigneur Dieu d’Israël; dites à l’homme qui vous a envoyés chez moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Voici ce que dit le Seigneur: Voilà que j’amène le mal sur ce lieu, selon les paroles du livre qui a été lu devant le roi de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'En punition de ce qu’ils m’ont abandonné, de ce qu’ils ont brûlé de l’encens pour d’autres dieux, afin de m’irriter, par toutes les œuvres de leurs mains; car ma colère s’est enflammée contre ce lieu, et elle ne s’éteindra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Quant au roi de Juda qui vous a envoyés chez moi, pour interroger le Seigneur, dites-lui: Voici ce que dit le Seigneur Dieu d’Israël: Aux paroles que tu as entendues,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Ton cœur a été rempli de crainte; tu t’es humilié devant moi, lorsque tu as ouï mes menaces contre ce lieu et contre ceux qui l’habitent; tu t’es humilié devant moi; tu as déchiré tes vêtements; tu as pleuré devant moi, et moi aussi j’ai entendu, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Voilà que je te réunis à tes pères; tu seras déposé en paix dans ton sépulcre, et tes yeux ne verront aucun des maux que j’amène sur ce lieu et sur ceux qui l’habitent. Et ils rapportèrent au roi ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Et le roi envoya des messagers, et il rassembla les anciens de Juda et de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Et le roi monta au temple du Seigneur, avec tout Juda, tous les habitants de Jérusalem, les prêtres, les lévites et le peuple entier, depuis le petit jusqu’au grand, et il lut à leurs oreilles toutes les paroles du livre de l’alliance, trouvé dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Et le roi se tint debout sur le piédestal, et il fit une alliance devant le Seigneur, pour marcher devant le Seigneur, garder ses commandements, ses témoignages et ses ordonnances, de tout son cœur et de toute son âme, afin de se conformer à toutes les paroles de l’alliance écrites en ce livre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Et il fit lever tous ceux qui se trouvaient en Jérusalem; et Benjamin, et les habitants de Jérusalem firent une alliance dans le temple du Seigneur Dieu de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Et Josias expulsa toutes les abominations de toute la terre des fils d’Israël, et il obligea tous ceux qui se trouvaient dans la ville et en Israël à servir, tous les jours de sa vie, le Seigneur leur Dieu; et il ne se détourna point du Seigneur Dieu de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Et Josias fit la Pâque du Seigneur son Dieu, et il immola la pâque, le quatorzième jour de la première lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Et il établit les prêtres dans leurs fonctions, et il les fortifia pour qu’ils servissent dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Et il prescrivit aux hommes valides parmi les lévites d’Israël, de se consacrer au Seigneur; ils placèrent donc l’arche sainte dans le temple qu’avait bàti Salomon; puis, le roi dit aux lévites: Vous n’avez plus rien à porter sur vos épaules, maintenant servez le Seigneur votre Dieu et Israël son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Préparez-vous, par familles paternelles, selon l’ordre de vos services journaliers; conformez-vous aux règlements du roi David, et à l’ordre établi par son fils. Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Tenez-vous dans le temple, afin d’y servir par divisions de familles paternelles, pour vos frères les fils du peuple; c’est le privilége de la maison de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Immolez la pâque et préparez-la pour vos frères, afin d’observer la loi du Seigneur que Moïse a fait connaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Et Josias, pour que les enfants du peuple fissent la pâque, immola des brebis, des agneaux, des chevreaux, au nombre de trente mille, et trois mille bœufs, tous pris parmi les troupeaux qui lui appartenaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Et ses princes sacrifièrent aussi pour le peuple, les prêtres et les lévites. Helcias, et Zacharie, et Jehiel, princes des prêtres, donnèrent à ceux-ci, pour la pâque, deux mille six cents brebis, agneaux ou chevreaux, et trois cents bœufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Et Honenias, Banaïas, Samaïas, son frère Nathanaël, Asabias, Jéhiel et Jozabad, chefs des lévites, donnèrent à ceux-ci, pour la pâque, cinq mille têtes de menu bétail, et cinq cents bœufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Et le service fut régulièrement rétabli; les prêtres se tinrent à leur rang ainsi que les lévites selon leurs divisions, comme l’avait prescrit le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Et ils immolèrent la pâque, et les prêtres répandirent de leurs mains le sang des victimes, et les lévites en enlevèrent les peaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Et ils préparèrent les holocaustes qui furent répartis, parmi le peuple, selon leurs divisions, par familles paternelles, pour qu’on les offrit au Seigneur, dès le matin, comme il est écrit au livre de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Et ils rôtirent la pâque à la flamme, selon la loi, et ils firent bouillir les chairs saintes, dans des chaudières d’airain et des marmites, et tout se passa heureusement, et quand les chairs furent bien cuites, ils se hâtèrent de les distribuer aux enfants du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Ils en préparèrent ensuite pour eux-mêmes et pour les prêtres, car ces derniers restérent jusqu’à la nuit à offrir les holocaustes, et à brûler les graisses. Les lévites préparèrent donc leur propre repas, et celui de leurs frères les fils d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Pendant ce temps, les chantres-harpistes, fils d’Asaph, étaient à leur poste, selon les règlements de David, d’Asaph, d’Hêman et d’ldithun, prophètes de ce roi, ainsi que les chefs et les gardiens des portes; il ne leur était pas permis de s’éloigner du service et des choses saintes; ce furent donc encore leurs frères les lévites, qui préparèrent leur repas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Ainsi, chaque service du Seigneur, ce jour-là, pour la célébration de la pâque et les offrandes d’holocaustes sur l’autel du Seigneur, se fit régulièrement par les soins du roi Josias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Les fils d’Israël qui se trouvèrent à Jérusalem, en ce temps-là, firent aussi la pâque et la fête des azymes, pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Et il n’y avait pas eu en Israël pareille pâque, depuis le temps du prophète Samuel; nul des rois d’Israël n’avait fait la pâque comme la firent, pour le Seigneur, Josias, les prêtres et les lévites, tout Juda, ce qui se trouva là d’Israël, et les habitants de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Ce fut en la dix-huitième année du règne de Josias, que cette pâque fut célébrée. Or, après tout ce que le roi Josias avait fait dans le temple, il brûla les ventriloques, les devins, et les images, et les idoles, et les sodomites, qui étaient en la terre de Juda et en Jérusalem, afin de confirmer les paroles de la loi, écrites dans le livre qu’avait trouvé Helcias. Et il n’y avait point eu auparavant de roi comme lui, qui se convertît au Seigneur, de tout son cœur, de toute son âme et de toute sa force, selon toute la loi de Moïse, et il n’y en eut point après lui. Néanmoins, le Seigneur ne détourna point la terrible colère, dont il s’était enflammé contre Juda, à cause des offenses qu’il avait reçues de Manassé. Et le Seigneur dit: J’expulserai aussi Juda de devant ma face, comme j’ai expulsé Israël; et je répudierai cette ville que j’avais choisie, cette Jérusalem et ce temple dont j’avais dit: C’est là que sera mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Et le Pharaon Néchao, roi d’Égypte, marcha, sur le fleuve Euphrate, contre le roi des Assyriens, et Josias se porta à sa rencontre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Et Néchao lui envoya des messagers, disant: Qu’y a-t-il entre moi et toi, roi de Jérusalem? Je ne suis pas venu aujourd’hui pour te combattre, et Dieu m’a prescrit de me hâter. Fais attention au Dieu qui est avec moi, si tu ne veux que je t’extermine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mais Josias ne détourna point de lui sa face; il se fortifia pour le combatire, sans tenir compte des paroles de Néchao, dites de la part de Dieu, et il lui livra une bataille dans la plaine de Mageddo.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Là, des archers percèrent le roi Josias, et il dit à ses serviteurs Emmenez-moi, car je souffre cruellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Ses serviteurs le descendirent donc de son char, le placèrent sur un autre char qu’il avait, et l’emmenèrent à Jérusalem, où il mourut; il fut enseveli avec ses pères. Et tout Juda et Jérusalem pleurèrent sur Josias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jérémie a fait sur lui une lamentation que tous les chefs et les femmes des princes ont chantée jusqu’à ce jour; c’est devenu comme une loi en Israël, et elle est écrite au livre des Lamentations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Et les actions de Josias et son espérance furent conformes à ce qui est écrit en la loi du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Et ses actes, les premiers et les derniers, sont écrits au livre des Rois d’Israël et de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Le peuple prit Joachaz, fils de Josias, et il le sacra, et il le fit roi de Jérusalem, à la place de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joachaz avait vingt-trois ans quand il monta sur le trône, et il régna trois mois à Jérusalem; sa mère se nommait Amital, fille de Jérémie de Lobna, et il fit le mal devant le Seigneur; il suivit tous les mauvais exemples de ses pères; et le Pharaon Néchao le chargea de chaînes à Déblatha, en la terre d’Emath, pour qu’il ne régnàt pas à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Il l’emmena en Égypte, et il frappa la terre d’une contribution de cent talents d’argent et d’un talent d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Et le Pharaon Néchao fit roi de Juda, à la place de Josias son père, Eliacim, fils de Josias, et il changea son nom en celui de Joacim, et il prit son frère Joachaz, et il l’emmena en Égypte, où il mourut. Mais il avait donné l’argent et l’or au Pharaon; en ce temps-là, on commença sur la terre à lever une taxe réglée par le Pharaon; chacun, autant qu’il le put, emprunta l’argent et l’or du peuplede la terre, pour le donner au Pharaon Néchao.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Joacim avait vingt-cinq ans lorsqu’il monta sur le trône, et il régna onze ans à Jérusalem; sa mère s’appelait Zéchora, fille de Néria de Rhama; et il fit le mal devant le Seigneur, suivant tous les mauvais exemples de ses pères. Sous son règne, Nabuchodonosor, roi de Babylone, vint en la terre, et Joacim lui fut asservi trois ans, et il se révolta contre lui. Et le Seigneur envoya contre son peuple des Chaldéens, des maraudeurs, tant syriens que moabites, ou fils d’Ammon ou samaritains, qui ensuite s’éloignèrent pour confirmer la parole que le Seigneur avait dite par la voix de ses serviteurs les prophètes. Mais la colère du Seigneur persistait contre Juda, qu’il voulait expulser de devant sa face, à cause des péchés que Manassé avait commis, et du sang innocent qu’avait répandu Joacim, car il en avait rempli Jérusalem; toutefois le Seigneur n’avait pas dessein de les exterminer tout à fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Nabuchodonosor marcha donc contre Joacim, le chargea de chaînes d’airain, et l’emmena à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Alors, il emporta une part des vaisseaux du temple du Seigneur, et il les mit dans le temple de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Quant au reste des faits et gestes de Joacim, n’est-il pas écrit au livre des Récits des rois de Juda? Et Joacim s’endormit avec ses pères, et on l’ensevelit à Gonaza avec ses pères, et Jéchonias, son fils, fut proclamé roi à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jéchonias avait huit ans lorsqu’il monta sur le trône, et il régna trois mois et dix jours à Jérusalem, et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Et pendant le cours de l’année, le roi Nabuchodonosor envoya des troupes, et on l’emmena à Babylone avec tous les vases précieux du temple du Seigneur, et l’on proclama roi de Juda et de Jérusalem, Sédécias, frère de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sédécias avait vingt et un ans lorsqu’il monta sur le trône, et il régna onze ans à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Et il fit le mal devant le Seigneur, et il ne rentra en lui-même, ni devant le prophète Jérémie, ni à la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Il se révolta contre le roi Nabuchodonosor, après qu’au nom du Seigneur, le prophète l’eût adjuré de n’en rien faire; il endurcit son cœur et il se roidit le cou, de sorte qu’il ne retourna pas au Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Et les premiers de Juda, et les prêtres et le peuple de la contrée, multiplièrent les offenses en commettant les abominations des peuples étrangers, et ils souillèrent le temple du Seigneur à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Et le Seigneur Dieu de leurs pères les avertit en leur envoyant ses prophètes, en leur envoyant à chaque aurore des messagers, pour épargner son peuple et le lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mais ils raillaient ses envoyés, ils méprisaient ses discours, ils se moquaient de ses prophètes, jusqu’à ce qu’enfin la colère du Seigneur s’enflammât contre le peuple et fût implacable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Alors, le Seigneur amena contre eux le roi des Chaldéens, qui tua leurs jeunes fils par le glaive dans le temple et le sanctuaire; il n’épargna pas Sédécias, et n’eut point pitié des vierges de Jérusalem; les vainqueurs enlevèrent les anciens; le Seigneur leur avait livré toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Et tous les vaisseaux du temple de Dieu, grands et petits, et tous les trésors, tant du temple que du palais et des maisons des grands, furent transportés à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Et Nabuchodonosor brûla le temple du Seigneur; puis, il démolit les remparts de Jérusalem; il livra aux flammes tous ses palais, il détruisit tous les vases précieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Et il transporta le reste des habitants à Babylone, où ils furent esclaves du roi ou de ses fils, jusqu’à l’établissement de l’empire des Mèdes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Afin que la parole du Seigneur qu’avait fait connaître la bouche de Jérémie, le prophète, fût accomplie, et que la terre jouît de ses sabbats, et observât le sabbat tous les jours de sa désolation, jusqu’à l’achèvement des soixante-dix années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'La première année de la domination de Cyrus, roi des Perses, après l’accomplissement de la parole du Seigneur, qu’avait dite la bouche de Jérémie, le Seigneur excita l’esprit de Cyrus, roi des Perses, et il envoya dans tout le royaume une proclamation par écrit, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Voici ce que dit, à tous les royaumes de la terre, Cyrus, roi des Perses: Le Seigneur Dieu du ciel m’a donné le pouvoir, et il m’a prescrit de rebâtir son temple à Jérusalem, en Juda. Qui, parmi vous tous, est de son peuple? Qu’il parte; son Dieu sera avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Josias fit célébrer dans Jérusalem, la Pâque du Seigneur, et elle fut immolée le quatorzième du premier mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Ce prince ordonna que les prêtres, revêtus de leurs habits sacerdotaux, serviraient tour à tour dans le temple du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'et que les lévites, ministres sacrés d’Israël, se purifieraient devant le Seigneur; parce que son arche sainte était dans le temple qu’avait fait bâtir Salomon, fils du roi David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Vous ne la porterez plus sur vos épaules, et maintenant donc, occupez-vous au service de votre Dieu, et ayez soin de son peuple, chacun dans vos cantons et dans vos tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Servez tous dans le temple, selon que David, roi d’Israël, l’a ordonné, et que l’exigea autrefois la magnificence de Salomon son fils; et gardez vos départements en présence de vos frères, selon l’ordre et le rang que vous avez reçus de vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Immolez la Pâque, préparez les sacrifices à vos frères, et conformez-vous en toutes choses à l’ordre que Moïse reçut autrefois du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Et Josias fit distribuer au peuple qui se trouva à cette solennité, des moutons, des agneaux, des chèvres et des chevreaux, au nombre de trente mille, et trois mille veaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Ces choses furent fournies aux dépens du roi, selon la promesse qu’il en avait faite au peuple. Et l’on distribua');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Jéchonias, Semeias et Nathanael, ses frères, Hasabias, Oziel, et Caraba, donnèrent cinq mille moutons et cinq cents veaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Parmi la pompe de cette fête, les prêtres et les lévites se présentèrent avec les pains azymes, à la tête de leurs tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Et selon l’ordre et le rang de leurs familles, ils offraient les victimes au Seigneur, en présence du peuple, conformément à ce qui est écrit dans le livre de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 12, 'Ils firent rôtir les agneaux autant qu’il le fallait, et prirent avec plaisir le soin de faire cuire les victimes pacifiques dans des chaudrons et dans des marmites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 13, 'Les lévites en présentèrent d’abord à tout le peuple, et firent ensuite leurs parts et celle des prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 14, 'Car les prêtres furent occupés jusqu’à la nuit à offrir les graisses des victimes, et les lévites avaient soin de préparer à manger pour leurs frères, les enfants d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 15, 'Les chantres fils d’Asaph, étaient aussi là dans leur rang, selon que David l’avait ordonné; savoir, Asaph, Zacharie, et Jeddimus, tous chantres du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 16, 'Les portiers aussi gardaient les portes du temple sans s’éloigner un seul moment de leur office, c’est pourquoi leurs frères avaient soin de leur préparer à manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 17, 'Et tout ce qui regardait le sacrifice du Seigneur se trouva achevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 18, 'Et en ce jour-là, ils firent la Pâque, et ils offrirent des victimes au Seigneur, selon l’ordre du roi Josias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 19, 'Les enfants d’Israël qui se trouvèrent alors à Jérusalem, firent la Pâque et célébrèrent la fête des Azymes pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 20, 'Il n’y eut point de Pâque semblable à celle-ci dans Israël, depuis le temps du roi Samuel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 21, 'et de tous les rois d’Israël, il n’y en a point eu qui ait fait une Pâque comme celle que Josias fit avec les prêtres, les lévites, tout le peuple de Juda, les habitants de Jérusalem et tout ce qui se trouva d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 22, 'Cette Pâque fut célébrée la dix-huitième année du règne de Josias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 23, 'Ce prince se rendit agréable au Seigneur, et marcha dans la crainte de son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 24, 'Les ordonnances qu’il fit contre ces hommes criminels qui ont surpassé en impiété les nations mêmes, et qui n’ont point suivi les lois qu’Israël a reçues du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 25, 'Et après ces actions de Josias, Pharaon, roi d’Égypte, vint à Carchamis par le chemin qui est vers L’Euphrate, et Josias alla au-devant de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 26, 'Alors le roi d’Égypte envoya dire à Josias: Qu’y a-t-il entre vous et moi, ô roi de Juda?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 27, 'Je ne suis point envoyé du Seigneur pour vous faire la guerre, mais aux peuples qui sont sur l’Euphrate, hâtez-vous donc de vous retirer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 28, 'Josias ne voulut point s’en retourner, et se prépara à le combattre, sans avoir égard à ce que le prophète vint lui dire de la part du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 29, 'Et il s’avança en ordre de bataille dans les plaines de Mageddo; mais les chefs de l’armée ennemie l’ayant attaqué,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 30, 'Il dit à ses serviteurs: Emportez-moi hors du combat, car je suis fort blessé; et ils lui obéirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 31, 'Josias fut donc transporté dans un autre char, et étant revenu à Jérusalem, il y mourut et fut mis dans le tombeau de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 32, 'Toute la Judée fut dans je deuil: et ceux qui président aux chants lugubres, ainsi que leurs femmes, le pleurent encore jusqu’à ce jour, ce qui a passé comme une espèce de loi établie dans Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 33, 'Toutes ces choses sont écrites dans les histoires des rois de Juda; savoir, toutes les actions de Josias, ses faits glorieux, sa pénétration et son intelligence dans la loi de Dieu, tout ce qu’il a jamais fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 34, 'Alors les enfants d’Israël, prenant Jéchonias qui était âgé de trente-trois ans l’établirent roi en la place de Josias son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 35, 'Il ne régna que trois mois sur Israël: car le roi d’Égypte le déposa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 36, 'Et condamna le peuple à lui donner cent talents d’argent, et un talent d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 37, 'Il donna le royaume de Juda et de Jérusalem à Joacim, frère de Jéchonias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 38, 'Il chargea de chaînes les princes de sa cour, et Zaracel, son frère, qu’il en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 39, 'Joacim avait vingt-cinq ans quand il commença à régner en Juda et à Jérusalem, et il fit le mal en présence du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 40, 'Nabuchodonosor marcha contre lui, et après l’avoir chargé de chaînes, il l’emmena à Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 41, 'où il transporta aussi les vases sacrés et les consacra dans son temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 42, 'Il est parlé, dans les Annales des Rois, de l’impiété et des honteux dérèglements de Joacim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 43, 'Joachin, son fils, régna en sa place, et il n’avait que dix-huit ans lorsqu’il monta sur le trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 44, 'Il régna trois mois et dix jours dans Jérusalem, et il fit le mal devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 45, 'Vers la fin de cette année, Nabuchodonosor le fit amener à Babylone avec tous les vases sacrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 46, 'Et il donna à Sédécias le royaume de Juda et de Jérusalem. Ce prince avait alors vingt-et-un ans, et il en régna onze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 47, 'Il fit le mal devant le Seigneur, et il ne fut point effrayé des menaces que le prophète Jérémie vint lui faire de sa part.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 48, 'Il prêta serment au roi Nabuchodonosor, et se retira après s’être parjuré; et dans l’endurcissement de son cœur il viola les ordonnances du Seigneur, le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 49, 'Les princes du peuple commirent l’iniquité; leur impiété l’emporta sur celle des nations, et ils profanèrent le saint temple de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 50, 'Alors le Dieu de leurs pères envoya son ange pour les rappeler à lui, parce qu’il voulait leur pardonner et conserver la majesté de son temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 51, 'Mais ils se moquaient de ceux qui venaient de sa part, et traitaient indignement les prophètes qu’il a daigné leur envoyer de temps en temps;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 52, 'Jusqu’à ce que sa colère s’étant allumée contre son peuple et contre leur impiété, il eût ordonné aux rois des Chaldéens de marcher contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 53, 'Ces cruels ennemis répandirent autour du temple du Seigneur le sang des jeunes hommes d’Israël; et ils n’épargnèrent ni les enfants, ni les vieillards, ni les jeunes gens, ni les vierges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 54, 'Tout passa entre les mains des vainqueurs, qui, prenant de nouveau les vases sacrés du temple du Seigneur et les trésors du roi, les portèrent à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 55, 'Ils brûlèrent la maison du Seigneur; ils abattirent les murs de Jérusalem, et mirent le feu dans ses tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 56, 'Toute la splendeur de cette ville sainte fut anéantie sous leurs efforts. Ceux que le fer avait épargnés suivirent leurs vainqueurs à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 57, 'Et ils y furent réduits en servitude jusqu’à ce que l’empire eût passé aux Perses, afin que tout ce que Jérémie leur avait dit de la part du Seigneur fût accompli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 58, 'Et cette terre fut déserte pendant');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Cyrus étant roi des Perses, le Seigneur, pour accomplir la parole qu’il avait prononcée par la bouche de Jérémie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'toucha le cœur de ce prince, qui envoya aussitôt des lettres dans tous les lieux de sa domination,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Elles étaient écrites en ces termes: Voici ce que dit Cyrus, roi des Perses: Le Dieu d’Israël, le Seigneur souverain, m’a établi roi sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Et il m’a ordonné de lui élever un temple à Jérusalem, qui est en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Que tout ce qui se trouve de Juifs parmi nous s’en retournent à Jérusalem, et que leur Dieu soit avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Que tous les peuples voisins les aident de leur or et de leur argent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'De toutes sortes de dons, de leurs chevaux, de leurs bêtes de voiture et des autres choses que chacun de vous s’obligera de consacrer au Seigneur dans le temple de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Alors les chefs des tribus et des villes de Juda et de Benjamin, les prêtres et les lévites à qui le Seigneur inspira de retourner à Jérusalem et d’y relever son temple; tous ceux enfin qui demeuraient aux environs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'vinrent offrir leur or, leur argent et leurs chevaux, pendant que plusieurs autres faisaient des vœux que le Seigneur formait lui-même dans leurs cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Le roi Cyrus ayant pris les vases sacrés que Nabuchodonosor avait transportés de Jérusalem, et qu’il avait consacrés à l’idole,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'les donna à Mithridates, qui était garde de ses trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Et Mithridates les remit par son ordre entre les mains de Salmanasar, gouverneur de Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Voici le nombre de ces vases: deux mille quatre cents urnes d’argent, trente tasses d’argent, trente fioles d’or, deux mille quatre cents d’argent, et mille autres vases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Tous les vases d’or et d’argent étaient au nombre de cinq mille huit cent soixante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Et ils furent comptés à Salmanasar et à tous les captifs qui retournaient à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Or, sous le règne d’Artaxerxès, roi des Perses, quelques-uns de ceux qui étaient en Judée et à Jérusalem: Balsanius, Mithridates, Sabellius, Rathimus, Balthemus, Samelius, le secrétaire, ceux enfin qui habitaient la Samarie et les lieux d’alentour, écrivirent au roi Artaxerxès la lettre suivante:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Seigneur, vos serviteurs, Rathiffius l’inspecteur, Sabellius le secrétaire, et ceux de votre cour que vous avez établis gouverneurs de la Célésyrie et de la Phénicie, vous saluent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Que le Seigneur, notre roi, sache que les Juifs renvoyés de Babylone viennent à Jérusalem, cette ville rebelle et perfide; qu’ils en relèvent les murailles, qu’ils bâtissent les rues, et qu’ils rétablissent le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Si l’on n’arrête ces entreprises, ils refuseront non-seulement de payer les tributs, ils seront même en état de résister aux rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Et parce que le temple s’avance de jour en jour, nous avons cru qu’il était important de ne rien négliger à cet égard;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Mais d’en avertir le Seigneur notre roi, afin que s’il le juge à propos, l’on consulte les Annales de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Il y trouvera des avis que ses prédécesseurs ont laissés sur ce sujet, et il apprendra que cette ville a toujours été rebelle, qu’elle n’a cessé de troubler la tranquillité des rois et des nations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'que les Juifs ont toujours été portés à la révolte, que de tout temps ils ont suscité des guerres, et que c’est pour cela même que leur ville a été détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Maintenant donc, Seigneur notre roi, si vous permettez que les Juifs rebâtissent leur ville et qu’ils relèvent leurs murailles, sachez que vous vous fermez l’entrée de la Célésyrie et de la Phénicie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Alors le roi écrivit la lettre suivante à Rathimus, son inspecteur, à Balthemus, à Sabellius, son secrétaire, aux autres intendants et aux habitants de Samarie et de Phénicie:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Après avoir lu la lettre que vous m’avez écrite, j’ai fait consulter les histoires de mes pères, et il s’est trouvé que Jérusalem a été de tout temps ennemie de la domination;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'que le peuple qui l’habite est un peuple rebelle; toujours prêt à prendre les armes contre l’autorité la plus légitime, et a eu des rois puissants à qui la Phénicie et la Célésyrie ont payé des tributs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Maintenant donc j’ai ordonné qu’on les empêchât de bâtir leur ville, et que l’on fît cesser tous les travaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'de peur que leur malice n’augmente de plus en plus, et qu’un jour elle ne puisse troubler la tranquillité de notre empire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Après qu’on eut fait la lecture de ces lettres, Rathimus, Sabellius le secrétaire, et les autres intendants, se rendirent en diligence à Jérusalem avec des troupes de cavalerie et d’infanterie. Alors l’ouvrage du temple fut interrompu; on n’y travailla point jusqu’à la deuxième année du règne de Darius, roi des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Le roi Darius fit un grand festin à ses favoris;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'à tous les gouverneurs de Médie et de Perse, à tous les grands de sa cour, aux préteurs, aux consuls et aux satrapes, qui gouvernaient sous ses ordres les cent vingt-sept provinces qui sont depuis l’Inde jusqu’à l’Éthiopie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Après qu’ils eurent bien bu et bien mangé, et qu’ils se furent retirés, le roi monta dans sa chambre et se livra au sommeil, puis se réveilla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Alors les trois jeunes hommes qui veillaient à la garde de sa personne, se dirent l’un à l’autre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Que chacun de nous propose quelque question importante, et celui qui parlera avec plus de sagesse que les autres, recevra de grands présents du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Il sera revêtu de la pourpre, il boira dans un vase d’or, et dormira sur des étoffes précieuses. Il sera traîné dans un char dont les rênes seront d’or, il portera sur sa tête une tiare de fin lin et un collier autour de son cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Il méritera par sa sagesse d’être assis à la droite du roi, et il sera appelé son cousin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Ils écrivirent ensuite chacun leur question, et les mirent toutes sous le chevet du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Et ils dirent: Lorsque le roi sera éveillé, nous lui présenterons ces écrits, et la victoire restera, comme nous en sommes convenus, à celui de nous trois qui, au jugement du roi et des grands, aura fait voit — le plus de sagesse dans ses preuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Le premier de ces gardes écrivit: Il n’y a rien de plus fort dans le monde que le vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Le second écrivit: Il n’y a rien de plus fort que la puissance du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Et le troisième enfin écrivit: Il n’y a rien de plus fort que les femmes; mais la vérité est encore plus forte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Quand le roi fut éveillé, ils prirent leurs écrits et les lui présentèrent, le roi les lut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 14, 'Et avant fait assembler tous les gouverneurs des Perses et des Mèdes, les grands de sa cour, les préteurs et les préfets,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 15, 'il les fit asseoir, et on lut ces écrits en leur présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 16, 'Le roi dit ensuite: Appelez les jeunes gardes, et qu’ils s’expliquent eux-mêmes; et ils parurent aussitôt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 17, 'Et il leur dit: Déclarez-nous vous-mêmes les choses que vous avez écrites. Alors celui qui avait donné la force au vin parla le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 18, 'Et dit: Ô roi, combien le vin est-il plus fort que tous les hommes qui le boivent! il se rend maître de leurs pensées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 19, 'et il rend égales celles du roi et de l’orphelin, de l’esclave et de l’homme libre, du riche et du pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 20, 'Il leur inspire la confiance et la joie, il bannit la tristesse et le souvenir importun de leurs dettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 21, 'Il rend tous les cœurs contents, il leur ôte la mémoire du roi et des magistrats; il fait que l’on ne s’entretient que de biens et de fortune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 22, 'À peine les hommes sont-ils remplis de vin qu’ils oublient les droits de l’amitié et les liens du sang; et bientôt après ils courent aux armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 23, 'Et quand ils sont sortis de leur ivresse, ils ne se ressouviennent plus de ce qu’ils ont fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 24, 'Ô hommes! Y a-t-il donc quelque chose de plus fort que le vin, puisqu’il produit de pareils effets? Et, après avoir parlé de cette manière, il se tut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Le second garde parla ensuite et releva la force du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Ô vous qui m’écoutez! Y a-t-il quelque chose de plus fort que les hommes, eux qui se soumettent la terre, la mer, et tout ce qui est renfermé dans leurs vastes espaces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Le roi, cependant, est encore au-dessus d’eux; ils révèrent sa puissance et sont toujours prêts à exécuter ses ordres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'S’il les envoie contre les ennemis redoutables, ils marchent, ils franchissent les montagnes, renversent les murs, et les tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Ils perdent la vie, mais c’est après l’avoir ôtée aux autres, et, toujours soumis aux ordres du roi, si la victoire couronne leur valeur, ils lui apportent toutes les dépouilles de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Tous ceux aussi qui, loin des travaux de la guerre, cultivent en paix de riches campagnes, ne les voit-on pas après la moisson en apporter au roi les tributs et les prémices?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Si lui seul dit: Tuez, ils tuent: Pardonnez, ils pardonnent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Frappez, ils frappent: Détruisez, ils détruisent: Bâtissez, ils bâtissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'S’il dit: Coupez, ils coupent: Plantez, ils plantent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'Le peuple et les grands sont également soumis aux volontés d’un seul homme. Le roi s’assied, ensuite il boit et se livre au sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Ils veillent tous à la garde de sa personne; sans qu’il leur soit permis de s’écarter un moment pour vaquer à leurs propres affaires et ils se tiennent toujours en état d’exécuter ses ordres');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Ô hommes! comment donc y aura-il quelque chose au-dessus du roi, puisqu’il est ainsi honoré? Et il cessa de parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Le troisième, nommé Zorobabel, commença à relever la force des femmes et de la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Ô hommes, qui m’écoutez! Ni le roi, revêtu de toute sa grandeur, ni le vin, ni les hommes unis ensemble, ne sont pas ce qu’il y a de plus fort sur la terre: Qui peut donc être au-dessus de toutes ces choses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Ne sont-ce pas les femmes, puisque c’est d’elles seules que les rois et les peuples, qui dominent sur la terre et sur la mer, tirent leur origine?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Elles leur ont donné la naissance et elles ont élevé ceux qui, les premiers, ont planté la vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Elles tirent de leurs mains les habits dont les hommes se couvrent; elles font toute leur gloire, et ils ne peuvent se passer de femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Qu’ils aient en abondance de l’or ou de l’argent; qu’ils possèdent les choses les plus précieuses, si une femme belle et parée vient s’offrir à leurs yeux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'ils quittent tout pour l’avoir, ils la contemplent avec étonnement et se sentent plus de passion pour elle qu’ils n’en avaient auparavant pour leurs richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'L’homme abandonne son père qui l’a nourri; il se bannit même de son propre pays, pour s’attacher, sans réserve, à la femme dont il a fait choix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Il ne trouve de plaisir qu’à l’aimer, et il oublie, pour elle, son père, sa mère, et le lieu de sa naissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Les femmes n’exercent-elles donc pas l’empire sur vous, et n’est-ce pas pour elles que vous vous exposez à tant de peines et de travaux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'L’homme prend son épée, il va sur les chemins pour commettre des vols et des meurtres; il parcourt les rivières et les mers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Il voit un lion, et se cache dans les antres les plus creux: et quand il s’est enrichi de vols et de rapines, il vient tout mettre aux pieds de celle qu’il aime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 25, 'Encore un coup, l’homme chérit sa femme plus que son père et sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 26, 'Plusieurs d’entre eux les ont aimées jusqu’à en perdre la raison, et à se réduire en servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 27, 'D’autres ont sacrifié leur vie, et ont péché pour leur plaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 28, 'Refuseriez-vous donc encore de me croire? J’avoue, avec vous, que la puissance du roi est bien grande, puisque tous les peuples craignent si fort de l’offenser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 29, 'Cependant je voyais le très-grand roi avec sa concubine Apémène, fille de Bezads; elle était assise à sa droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 30, 'Et lui ayant ôté le diadème de dessus la tête, elle le mettait sur la sienne; et de sa main gauche elle le frappait à la joue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 31, 'Le roi néanmoins la regardait avec admiration; quand elle lui souriait, il faisait éclater sa joie; et quand elle se fâchait, il redoublait ses caresses, jusqu’à ce qu’elle lui eût rendu ses bonnes grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 32, 'Ô hommes! que pouvez-vous donc concevoir au-dessus des femmes, puisqu’elles exercent sur vous un tel empire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 33, 'Alors le roi et les grands de sa cour se regardèrent l’un l’autre, et Zorobabel, poursuivant son discours, commença à parler de la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 34, 'Ô hommes qui m’écoutez! serait-il donc possible qu’il y eût quelque chose de plus fort que les femmes? La terre est grande, le ciel est élevé, le soleil parcourt chaque jour ces espaces immenses, et revient avec rapidité au lieu d’où il était parti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 35, 'Toutes ces merveilles n’annoncent-elles pas la grandeur de celui qui les a faites? mais la vérité n’est-elle pas grande et plus forte que toute autre chose?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 36, 'Toute la terre en porte les plus vifs traits: Le ciel en fait l’éloge, toutes les créatures la respectent et la craignent, et elle n’a rien de mauvais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 37, 'Tout est mauvais dans le monde, le vin, le roi, les femmes, tous les enfants des hommes et toutes leurs œuvres; il n’y a point en eux de vérité, et ils périront dans leur iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 38, 'La vérité n’est point sujette au changement; son règne s’affermit dans l’éternité; elle subsiste et subsistera dans tout le cours des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 39, 'Elle n’a égard, ni aux personnes, ni à ce qui les distingue les unes d’avec les autres; elle traite les impies et les méchants dans toute la rigueur de sa justice, et tout le monde approuve ce qu’elle fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 40, 'Il n’y a rien d’injuste dans ses jugements, et elle est la force, le règne, la puissance et la majesté de tous les siècles. Gloire soit à jamais au Dieu de la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 41, 'Zorobabel avant cessé de parler, tout le peuple cria à haute voix: La vérité est grande, et rien n’égale sa force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 42, 'Alors le roi dit à Zorobabel: demandez-moi si vous voulez au delà même de ce que l’on est convenu, et je vous le donnerai: puisque vous avez parlé avec plus de sagesse que les autres, vous serez assis auprès de moi, et je vous appellerai mon cousin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 43, 'Zorobabel répondit au roi: Souvenez-vous du vœu que vous fîtes au jour que vous montâtes sur le trône des Perses, quand vous promîtes de relever les ruines de Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 44, 'et d’y faire reporter les vases qui en avaient été enlevés, et que Cyrus avait déjà mis à part dans ce dessein, lorsqu’il se fut rendu maître de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 45, 'Vous fîtes vœu de rebâtir le temple que les Iduméens avaient réduit en cendre, pendant que les Chaldéens ravageaient la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 46, 'Et maintenant, Seigneur, ce que je vous demande et ce que je regarde comme la plus grande récompense que je puisse obtenir est que vous rendiez au Roi du ciel le vœu que vous lui fîtes alors de votre propre bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 47, 'Darius s’étant levé aussitôt embrassa Zorobabel, et écrivit des lettres à tous les gouverneurs de l’empire, aux préfets et aux satrapes, leur ordonnant de le faire escorter, lui et tous les Juifs qui retournaient à Jérusalem pour la rebâtir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 48, 'Il envoya en même temps des ordres à tous les gouverneurs de Syrie, de Phénicie, et du Liban, de fournir aux Juifs les cèdres nécessaires pour cet ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 49, 'Outre cela il fit savoir à tous les Juifs qui s’en retournaient en Judée qu’il leur rendait la liberté, et qu’ils ne devaient point craindre que ni les préfets, les magistrats et les gouverneurs, vinssent les troubler dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 50, 'Que tout le pays qu’ils avaient possédé autrefois serait libre, et que les Iduméens sortiraient des forteresses de Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 51, 'Que tous les ans l’on payerait de son trésor vingt talents pour la construction du temple, jusqu’à ce qu’il fût entièrement achevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 52, 'Et que pour offrir chaque jour les holocaustes sur l’autel, ainsi qu’il était ordonné par la loi, l’on donnerait encore dix autres talents tous les ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 53, 'Que tous ceux qui retourneraient de Babylone à Jérusalem pour rebâtir cette ville, eussent une entière liberté, aussi bien que leurs enfants, et les prêtres qui les conduisaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 54, 'Il écrivit encore surtout ce que l’on devait fournir aux prêtres, et sur les ornements sacrés dont ils avaient besoin pour desservir dans le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 55, 'Qu’on fournirait aux lévites tout ce qui leur était nécessaire jusqu’à ce que le Temple fût achevé, et que Jérusalem fût bâtie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 56, 'Il ordonna de plus, qu’on donnerait des gages et des appointements à ceux qui seraient commis à la garde de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 57, 'Il renvoya les vases que Cyrus avait mis à part, et voulut qu’on les reportât tous à Jérusalem conformément à ce que ce prince avait ordonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 58, 'Ce jeune homme s’étant retiré se tourna du côté de Jérusalem, et rendit grâces au Roi du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 59, 'En disant: C’est vous, Seigneur, qui donnez la victoire; la sagesse et la gloire vous appartiennent, et je suis votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 60, 'Soyez à jamais béni, vous qui m’avez rempli de sagesse et d’intelligence. Je confesserai votre nom, ô Dieu de mes pères!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 61, 'Et ayant pris les lettres du roi, il vint à Babylone, et fit part de ces nouvelles à tous ceux de ses frères qui étaient dans cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 62, 'Et ils bénirent tous le Dieu de leurs pères, de la permission et de la liberté qu’ils avaient obtenue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 63, 'de retourner à Jérusalem, et d’y rebâtir le temple où son saint nom avait été invoqué; et ils passèrent sept jours dans la joie et dans les concerts de musique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Après cela on choisit les chefs des villes, selon l’ordre des familles et des tribus, afin qu’ils retournassent à Jérusalem avec leurs femmes, leurs fils et leurs filles, leurs serviteurs, leurs servantes et leurs troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Et le roi Darius envoya avec eux mille chevaux pour les escorter et les conduire en paix jusqu’à Jérusalem, au bruit des airs de musique, des tambours et des flûtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Tous les enfants d’Israël étaient ainsi dans la joie, et Darius les fit tous partir avec ses escortes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Voici les noms de ceux qui revinrent de Babylone, selon l’ordre de leurs villes, de leurs familles et de leurs tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Des prêtres: Les enfants de Phinéès, fils d’Aaron; Jésus, fils de Josédec; Joacim, fils de Zorobabel, fils de Salathiel, de la maison de David, de la race de Pharès et de la tribu de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Ce fut ce Zorobabel qui parla avec tant de sagesse en présence de Darius roi des Perses, la seconde année de son règne au premier mois, qui est celui de Nisan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Or voici ceux qui furent emmenés captifs de la Judée par Nabuchodonosor, roi de Babylone, qui revinrent à Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'et en Judée, chacun dans les villes et dans les départements d’où ils étaient; et qui suivirent Zorobabel et Jésus, savoir: Néhémias, Aréorès, Elimeus, Emmanius, Mardochée, Béelsurus, Mechpsatochor, Oliorus. Emonia était un de leurs chefs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Voici le nombre de tout le peuple d’Israël et de leurs chefs. Les enfants de Pharès, deux mille cent soixante-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Les enfants d’Arès, trois mille cinquante-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Les enfants de Phœmo, cent quarante-deux. — Les enfants de Jésus et de Joabes, mille trois cent deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Les enfants de Demu, deux mille quatre cent soixante-dix. Les enfants de Choraba, deux cent cinq. Les enfants de Banica, cent soixante-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Les enfants de Bebech, quatre cent trois. Les enfants d’Archad, quatre cent vingt-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Les enfants de Cham, trente-sept. Les enfants de Zoroar, deux mille soixante-sept. Les enfants d’Adin, quatre cent soixante-un.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Les enfants d’Aderectis, cent huit. Les enfants de Ciaso et de Zelas, cent sept. Les enfants d’Azoroc, quatre cent trente-neuf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Les enfants de Jedarboné, cent trente-deux. Les enfants d’Ananias, cent trente. Les enfants d’Asoni, quatre vingt-dix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Les enfants de Marsar, quatre cent vingt-deux. Les enfants de Zabarus, quatre-vingt-quinze. Les enfants de Sepolemon, cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 18, 'Les enfants de Nepopas, cinquante-cinq. Les enfants de Nechanatus, cent cinquante-huit. Les enfants de Cebethamus, cent trente-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 19, 'Les enfants de Crearpatros, qui s’appelle aussi Enocadie et de Modie, quatre cent vingt-trois; de Gramas et de Gabea, cent vingt-un;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 20, 'De Besselon et de Ceaggé, soixante-cinq; de Bastaro, cent vingt-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 21, 'De Bechenobes, cinquante-cinq; les enfants de Liptis, cent cinquante-cinq; les enfants de Labonni, trois cent cinquante-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 22, 'Les enfants de Sichem, trois cent soixante-dix. Les enfants de Suadon et de Cliomus, trois cent soixante-dix-huit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 23, 'les enfants d’Ericus, deux mille cent quarante-cinq. Les enfants d’Anaas, trois cent soixante-dix. Les enfants des Prêtres:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 24, 'Les enfants de Jeddus, fils d’Euther, fils d’Eliasib, trois cent soixante-douze. Les enfants d’Emerus, deux cent cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 25, 'Les enfants de Phasurii, trois cent cinquante-sept. Les enfants de Carée, deux cent vingt-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 26, 'Les Lévites, les enfants de Jésus en Caduhel, Bamis, Serebias, et Edias, soixante-quatorze. Et le nombre de ceux qui étaient au-dessus de douze ans montait à trente mille quatre cent soixante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 27, 'Les garçons, les filles et les femmes, au nombre de quarante mille deux cent quarante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 28, 'Les enfants des prêtres, dont la fonction était de chanter dans le temple: les enfants d’Asaph, cent vingt-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 29, 'Les portiers: les enfants d’Esmenni, d’Aser, d’Amon, d’Accuba, de Topa, de Tobi, tous au nombre de cent trente-neuf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 30, 'Les prêtres servant au temple: les enfants de Sel, les enfants de Gaspha, les enfants de Tobloch, les enfants de Carie, les enfants de Su, les enfants de Hellu, les enfants de Labana, les enfants d’Armacha, les enfants d’Accub, les enfants d’Utha, les enfants de Cetha, les enfants d’Aggab, les enfants d’Obaï, les enfants d’Anani, les enfants de Canna, les enfants de Geddu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 31, 'les enfants d’An, les enfants de Raddin, les enfants de Desanon, les enfants de Nachoba, les enfants Caseba, les enfants de Gazé, les enfants d’Ozui, les enfants de Sinoné, les enfants d’Attré, les enfants d’Hasten, les enfants d’Asiana, les enfants de Manei, les enfants de Nasissim, les enfants d’Accusu, les enfants d’Agista, les enfants d’Azui, les enfants de Favon, les enfants de Phasalon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 32, 'les enfants de Meedda, les enfants de Phusa, les enfants de Carée, les enfants de Barcus, les enfants de Sarée, les enfants de Coësi, les enfants de Nasir, les enfants d’Agisti, les enfants de Pedon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 33, 'les enfants de Salomon son fils, les enfants d’Asophot, les enfants de Phasida, les enfants de Celi, les enfants de Dedon, * les enfants de Gaddahel, les enfants de Sephegi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 34, 'les enfants d’Aggia, les enfants Sachareth, les enfants de Sabathen, les enfants de Caroneth, les enfants de Malsith, les enfants d’Amas, les enfants de Sasus, les enfants d’Addus, les enfants de Suba, les enfants d’Eura, les enfants de Rahotis, les enfants de Phasphat, les enfants de Malmon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 35, 'Tous les ministres du temple et les serviteurs de Salomon étaient au nombre de quatre cent quatre-vingt-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 36, 'Voici ceux qui vinrent de Thelmela et de Telharsa, sous la conduite de Carmellam et de Careth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 37, 'et qui ne purent faire connaître ni leurs villes, ni leurs familles, pour prouver qu’ils étaient du peuple d’Israël: les enfants de Dalari, de Tubal et de Nechodaïci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 38, 'Parmi les prêtres qui exerçaient leurs fonctions, on ne trouva point les enfants d’Obia, d’Achisos et d’Addin, qui épousa une des filles de Phargeleu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 39, 'Ses enfants furent appelés de son nom; mais, n’ayant point été trouvés sur les registres, ils furent privés des fonctions du sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 40, 'Et (Nehemias et) Astharas leur dit s’abstenir de la participation des choses saintes, jusqu’à ce qu’il s’élevât un souverain pontife rempli de science et de vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 41, 'Or tous les enfants d’Israël se montaient à quarante-deux mille trois cent quarante;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 42, 'sans les serviteurs et les servantes qui étaient au nombre de sept mille trois cent trente-sept, outre deux cent soixante-cinq chantres de l’un et de l’autre sexe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 43, 'Ils menaient avec eux quatre cent trente-cinq chameaux, sept mille trente-six chevaux, deux cent mille quarante-cinq mulets, et cinq mille vingt-cinq bêtes portant le joug.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 44, 'Quelques-uns des chefs des familles étant arrivés à Jérusalem, au lieu où avait été le temple, firent vœu de rebâtir le temple en la même place où il était auparavant, selon leur pouvoir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 45, 'et de mettre dans le trésor, pour les ouvrages du saint temple, douze mille mines d’or, et cinq mille d’argent, avec cent robes sacerdotales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 46, 'Les prêtres, les lévites, les chantres sacrés, les portiers, et tout le peuple d’Israël demeuraient tous dans Jérusalem et dans les villes voisines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 47, 'Et étant enfin rentrés dans leurs anciens héritages vers le commencement du septième mois, ils s’assemblèrent tous avec un même cœur dans le parvis de la porte orientale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 48, 'Alors Jésus, fils de Josedec, et les prêtres, ses frères, Zorobabel, fils de Salathiel, et ses frères, préparèrent l’autel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 49, 'pour y offrir les holocaustes, conformément à ce que Moïse, l’homme de Dien, avait ordonné dans le livre de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 50, 'Il s’y trouva des gens de toutes les autres nations de la terre. Ils (les Juifs) dressèrent autel en sa première place, et offrirent au Seigneur les victimes et les holocaustes du matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 51, 'Ils célébrèrent avec beaucoup de solennité la fête des Tabernacles, et les sacrifices du soir et du matin, ainsi qu’il est ordonné dans la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 52, 'Ils firent les oblations prescrites, les sacrifices du sabbat, des premiers jours du mois et de toutes les fêtes solennelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 53, 'Et tous ceux qui avaient fait des vœux au Seigneur, commencèrent à lui offrir des sacrifices, depuis le premier jour du septième mois, quoiqu’on n’eût point encore jeté les premiers fondements du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 54, 'Ils distribuèrent avec joie aux tailleurs de pierre et aux charpentiers, de l’argent et toutes sortes de nourritures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 55, 'Ils fournirent aussi aux Tyriens et aux Sidoniens des chariots pour aller chercher au Liban des poutres de cèdre, et les conduire ensuite sur des radeaux jusqu’au port de Joppé, ainsi que le portait l’ordonnance du roi Cyrus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 56, 'Zorobabel, fils de Salathiel, Josué, fils de Josedec et leurs frères, les prêtres, les lévites, tous ceux enfin qui étaient revenus de Babylone, s’étant assemblés à Jérusalem le second mois de la seconde année depuis leur retour,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 57, 'ils jetèrent les fondements du temple au temps de la nouvelle lune du second mois;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 58, 'et établirent des lévites, depuis l’âge de vingt ans et au-dessus, pour servir dans le temple à toutes sortes de fonctions. Alors Jésus se présenta ferme avec son fils et les lévites; tous animés d’un même esprit s’employaient avec joie à toutes les fonctions du temple, et à l’observation de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 59, 'Les prêtres revêtus de leurs ornements se présentèrent avec leurs trompettes; et les lévites, fils d’Asaph, avec des cymbales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 60, 'Et louant tous le Seigneur, ils bénissaient son nom avec les paroles de David, roi d’Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 61, 'et chantaient ce cantique au Seigneur: Que sa bonté et sa gloire s’étendront à jamais sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 62, 'Tout le peuple mêlait sa voix au son des trompettes, et bénissait le Seigneur, qui permettait enfin qu’on relevât son temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 63, 'Et plusieurs des prêtres, des lévites et des chefs de famille qui avaient vu le premier temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 64, 'Considérant les fondements de celui-ci, jetaient de grands cris mêlés de larmes, pendant que d’autres, élevant leurs voix, poussaient en l’air des cris de réjouissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 65, 'Et on ne pouvait discerner les cris de joie d’avec les plaintes de ceux qui pleuraient, parce que tout était confus dans cette grande clameur du peuple, et l’éclat en retentissait bien loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 66, 'Au bruit confus de toutes ces réjouissances, les ennemis de Juda et de Benjamin vinrent demander quel en était le sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 67, 'Et ayant appris que les Israélites, revenus de captivité, bâtissaient un temple au Seigneur le Dieu d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 68, 'ils vinrent trouver Zorobabel, Jésus et les chefs de famille, et leur dirent: Souffrez que nous bâtissions ce temple avec vous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 69, 'Parce que nous connaissons aussi votre Dieu, et nous l’avons toujours servi depuis que Asbarazeth, roi d’Assyrie, nous a transportés dans ce pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 70, 'Alors Zorobabel, Jésus, et les chefs des familles leur dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 71, 'Nous ne pouvons permettre que vous nous aidiez à bâtir un temple au Seigneur, le Dieu d’Israël; mais nous le bâtirons seuls, comme Cyrus, roi des Perses, nous l’a ordonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 72, 'Cependant les peuples voisins inquiétaient les Juifs, détruisaient les ouvrages, leur dressaient des embûches, et venaient avec main forte troubler leurs travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 73, 'Ils empêchèrent par ces violences que le temple ne fût achevé du temps de Cyrus; ainsi cet ouvrage fut interrompu l’espace de deux ans, jusqu’au règne de Darius.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Or, la seconde année du règne de Darius, les prophètes Aggée et Zacharie, petit-fils d’Addin, furent envoyés aux Juifs qui étaient à Jérusalem et dans le reste de la Judée, et ils prophétisèrent au nom du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Alors Zorobabel, fils de Salathiel, et Jésus, fils de Josédec, commencèrent à bâtir le temple du Seigneur à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Et pendant que les prophètes étaient avec eux et les encourageaient à l’ouvrage, Sisennès, satrape de Syrie et de Phénicie, Satrabuzanès. et les autres gouverneurs vinrent trouver les Juifs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Et leur dirent: Par quel ordre élevez-vous ce temple et rebâtissez-vous cette ville: et qui sont ceux qui conduisent ces travaux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Ils avaient été exactement instruits de tout ce qui se passait; mais les anciens des Juifs, qui étaient de retour de la captivité, trouvèrent grâce devant le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Et ils eurent la liberté de continuer les ouvrages du temple jusqu’à ce qu’on eût informé Darius de toutes choses, et qu’on eût su quelles étaient ses intentions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Voici la copie de la lettre qu’on en écrivit à Darius; Sisennès, satrape de Syrie et de Phénicie, Satrabuzanès et ceux qui gouvernent avec lui ces provinces, au roi Darius, salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Que le roi notre maître sache qu’étant entrés en Judée et que nous étant avancés jusqu’à Jérusalem, nous avons trouvé les Juifs occupés à bâtir une vaste maison à leur Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Et un temple de pierres polies et très-grandes, et revêtu au dedans de matières précieuses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Que cet ouvrage se fait avec grand soin et qu’il s’avance entre leurs mains de jour en jour; enfin qu’il s’achève avec une magnificence fort grande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Alors nous nous sommes informés des anciens, et nous leur avons dit: Qui vous a donné le pouvoir de bâtir cette maison et de relever ces murs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Nous leur avons même demandé les noms de leurs anciens et de ceux qui conduisent ces ouvrages, pour vous faire un rapport exact de toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Et ils ont répondu en ces termes aux demandes que nous leur avons faites: Nous sommes les serviteurs du Seigneur qui a créé le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Ce temples fut bâti il y a plusieurs années par un roi d’Israël, qui était très puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Mais nos pères ayant attiré sur eux la colère du Dieu du ciel par leurs péchés, il les livra entre les mains de Nabuchodonosor, roi de Babylone, roi de Chaldée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Ce prince détruisit par le feu cette maison sainte, et emmena à Babylone les habitants de cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Mais Cyrus, la première année de son règne, ordonna qu’on rebâtit la maison de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Et qu’on retirât du temple de Babylone tous les vases d’or et d’argent que Nabuchodonosor avait fait transporter de Jérusalem à Babylone; et ces vases furent rendus à Zorobabel et à Salmanasar, satrape,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Avec ordre de les remettre dans le temple de Jérusalem, de les y consacrer de nouveau, et d’y rebâtir la maison de Dieu au même lieu où elle était auparavant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Salmanasar se rendit aussitôt à Jérusalem, et il y jeta les fondements du temple du Seigneur; depuis ce temps-là jusqu’à présent on a travaillé à cet édifice, et il n’est par encore achevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Nous supplions donc le roi, s’il le juge à propos, qu’on fasse des recherches dans les archives de Cyrus, qui sont à Babylone;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Et si on trouve que c’est par l’ordre de ce prince qu’on a jeté les fondements du nouveau temple de Dieu, qu’il plaise au roi de nous faire savoir sur cela ses ordres et sa volonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 23, 'Alors le roi Darius commanda qu’on allât faire des recherches dans les archives; et il se trouva à Ecbatane, ville du pays des Mèdes, un livre où était écrit ce qui suit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 24, 'La première année du règne de Cyrus: Le roi Cyrus a ordonné que la maison de Dieu qui est à Jérusalem fût rebâtie au même lieu où l’on offrait le sacrifice continuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 25, 'Que sa hauteur fût de dix coudées; sa largeur de soixante; l’épaisseur des murs de trois pierres polies. Que la menuiserie des côtés fût d’un bois neuf, et pris dans un même endroit; et que tout l’argent nécessaire pour cette dépense fut fourni de la maison du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 26, 'Que les vases sacrés, d’or ou d’argent, que Nabuchodonosor avait transportés de Jérusalem à Babylone, fussent renvoyés au temple du Seigneur, et remis au même lieu où ils avaient été placés autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 27, 'Il a encore ordonné à Sisennès, satrape de Syrie et de Phénicie, à Satrabuzanès et aux autres gouverneurs, de veiller à l’exécution de ses ordres, et de ne point troubler les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 28, 'Et moi aussi je veux que ce temple s’achève; et j’ai ordonné qu’on fournit aux Juifs tout ce qui leur est nécessaire, jusqu’à ce que la maison du Seigneur soit entièrement bâtie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 29, 'Qu’une partie des tributs qui se lèvent sur la Phénicie et sur la Célésyrie soit donnée exactement à Zorobabel, chef des Juifs, pour l’entretien des sacrifices de taureaux, de béliers et d’agneaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 30, 'Qu’on distribue encore outre cela tous les ans du froment, du sel, du vin et de l’huile, selon la quantité que les prêtres exigeront par jour; et que toutes ces choses leur soient fournies sans aucun délai,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 31, 'afin qu’ils offrent des sacrifices au Dieu du ciel, et qu’ils prient pour la santé du roi et pour celle de ses enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 32, 'Nous ordonnons de plus, que, si quelqu’un, de quelque qualité et condition qu’il soit, viole ou méprise le moindre de ces ordres, on tire une pièce de bois de sa maison, qu’on la plante en terre, et qu’il y soit attaché, et qu’on confisque ses biens au profit du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 33, 'Que le Dieu qui a établi son nom en ce lieu-là, dissipe tous les royaumes et extermine les peuples qui étendront leurs mains pour détruire ou profaner cette maison qu’il a dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 34, 'Moi, Darius, j’ai fait cet édit, et je veux qu’il soit exécuté très-exactement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Alors Sisennès, satrape de Célésyrie et de Phénicie, Satrabuzanès et les autres gouverneurs, obéissant aux ordres de Darius,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Pressaient vivement les travaux du temple, et agissaient de concert avec les anciens des Juifs et ceux qui conduisaient l’ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Tout leur succédait heureusement, suivant la prophétie d’Aggée et de Zacharie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Car ils se conduisirent en toutes choses selon le commandement du Seigneur le Dieu d’Israël, et par l’ordre de Cyrus, de Darius et d’Artaxerxès, roi des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Et la maison de Dieu fut entièrement achevée le vingt-troisième jour du mois d’Adar, la sixième année du règne de Darius.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Alors les enfants d’Israël, les prêtres, les lévites, et tous ceux qui étaient revenus de captivité, firent la dédicace du temple du Seigneur, conformément à ce qui est ordonné dans la loi de Moïse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Et ils offrirent dans cette solennité cent taureaux, deux cents béliers, quatre cents agneaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Et douze chevreaux, pour les péchés de tout le peuple, selon le nombre des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Les prêtres et les lévites revêtus de leurs ornements, et placés dans l’ordre de leurs familles, s’acquittaient de leurs fonctions, selon qu’il est écrit dans le livre de Moïse. Les portiers se placèrent à chacune des portes du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Et les enfants d’Israël, avec ceux de leurs frères qui étaient revenus de Babylone, célébrèrent tous cette Pâque, le quatorzième de la lune du premier mois, après que les prêtres et les lévites se furent purifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Or les captifs ne s’étaient pas tous purifiés en même temps, mais les lévites s’étaient tous purifiés ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Ainsi ils immolèrent là Pâque pour tous les Israélites revenus de captivité, pour les prêtres, leurs frères, et pour eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Tous ceux des enfants d’Israël qui, pendant la captivité, s’étaient séparés des impiétés des nations étrangères et qui avaient cherché Dieu, ceux-là, dis-je, mangèrent la Pâque;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Et ils célébrèrent la fête des Azymes pendant sept jours, mangeant en présence du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Et lui rendirent grâces de ce qu’il avait inspiré au roi d’Assyrie de relever son temple et de les favoriser dans cette entreprise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Après ces choses, sous le règne d’Artaxerxès, roi des Perses, Esdras, fils d’Azarias, fils d’Helcias, fils de Salomé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Fils de Sadoc, fils d’Achitob, fils d’Ameri, fils d’Azabel, fils de Bocci, fils d’Abisué, fils de Phinée, fils d’Eléazar, fils d’Aaron, qui fut le premier pontife;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Esdras, dis-je, revint de Babylone; il était docteur et fort habile dans la loi que le Seigneur Dieu d’Israël avait donnée par le ministère de Moïse (pour être enseignée et pratiquée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Et le roi l’éleva en gloire, parce qu’il avait trouvé grâce devant lui, et qu’il était agréable à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Plusieurs des enfants d’Israël, des prêtres, des lévites, des chantres, des portiers, et des serviteurs du temple, remontèrent avec lui à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Et ils arrivèrent au cinquième mois de la septième année du règne d’Artaxerxès, étant partis à la nouvelle lune du premier mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Ils revinrent donc en Judée par ordre du roi, et Dieu les regarda favorablement pendant tout le voyage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Car Esdras avait eu grand soin de s’instruire de tout ce qui concernait la loi, afin qu’elle ne fût violée en aucun point, et qu’il put lui-même enseigner à Israël les préceptes et les ordonnances de son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Alors les secrétaires du roi Artaxerxès vinrent trouver Esdras, prêtre et docteur de la loi, et lui rendirent une lettre, dont voici la copie:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'ARTAXERXÈS, roi, à Esdras, prêtre et docteur de la loi du Seigneur, salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Ayant enfin résolu de vous combler de bienfaits, j’ai ordonné que quiconque se trouvera dans l’étendue de mon empire, du peuple d’Israël, de ses prêtres et de ses lévites, qui de son bon gré voudra retourner à Jérusalem, y aille avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Que ceux donc qui seront dans ce dessein s’assemblent et partent, ainsi qu’il m’a semblé bon, et de l’avis de mes favoris, les sept grands du conseil;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Afin qu’ils voient ce qui se passe à Jérusalem et dans le reste de la Judée, et que tout s’y fasse selon qu’il est ordonné dans la loi du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Qu’ils portent à Jérusalem les dons que moi et mes favoris avons voués au Dieu d’Israël, avec tout l’or et l’argent qui se trouvera appartenir au Seigneur, dans Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Et qui a été donné à cette nation pour être offert dans le temple de Jérusalem. Que cet or et cet argent soient recueillis pour acheter des taureaux, des agneaux, des moutons, des boucs, et toutes les autres choses nécessaires;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Afin qu’ils offrent des sacrifices au Seigneur sur son autel qui est à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Que si vous jugez à propos, vous et vos frères, de disposer de cet or et de cet argent en quelque manière que ce soit, usez-en selon les ordonnances et la volonté de votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'À l’égard des vases sacrés qui vous sont rendus pour servir au culte du Seigneur, ayez soin de les remettre dans la maison de votre Dieu à Jérusalem;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Et quant aux autres choses nécessaires pour les ouvrages, elles vous seront fournies du trésor royal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Et si vous et vos frères jugez à propos de disposer de quelque quantité d’or et d’argent que ce soit, usez-en selon les ordonnances et la volonté de votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Moi, Artaxerxès, roi des Perses, j’ai ordonné à tous mes trésoriers de Syrie et de Phénicie, que tout ce qu’Esdras, prêtre et docteur de la loi du Seigneur, demandera, lui soit promptement accordé, jusqu’à cent talents d’argent et cent talents d’or;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Cent muids de froment, cent tonneaux de vin, et ainsi de toutes les autres choses, sans en rien exiger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Qu’on ne viole en aucun point la loi du Dieu très-haut, de peur que sa colère ne se répande sur mon royaume, sur moi et sur mes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Nous vous déclarons encore que sur aucun des prêtres, des lévites, des chantres, des serviteurs et des autres officiers du temple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Vous ne pourrez imposer ni tribut, ni autre charge, ni exiger d’eux quoi que ce soit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Et vous, Esdras, selon la sagesse que vous avez reçue de votre Dieu, établissez des juges et des magistrats dans toute la Syrie et la Phénicie; et instruisez de la loi du Seigneur tous ceux qui ne la connaissent pas;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Afin que les violateurs de cette loi sainte soient condamnés sans rémission, ou à la mort, ou aux tourments, ou à l’amende, ou à l’exil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Alors Esdras s’écria: Béni soit le Dieu de nos pères qui a inspiré au roi le dessein de relever la gloire du temple du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Et qui m’a fait trouver grâce devant le roi et ses conseillers, devant ses amis et les grands de sa cour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'C’est pourquoi, étant assuré de la protection du Seigneur mon Dieu, j’ai assemblé les enfants d’Israël pour les ramener avec moi à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Voici les noms des chefs de famille qui sont revenus avec moi de Babylone, sous le règne d’Artaxerxès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Des enfants de Pharès, Gersomus; des enfants de Siemarith, Amenus; des enfants de David, Acchus, fils de Scecilia:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Des enfants de Pharès, Zacharias, et avec lui cent cinquante hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Des enfants de Moabilionis, Zaréi, et avec lui deux cent cinquante hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Des enfants de Zachuès, Jéchonias, fils Zecholé, et avec lui deux cent cinquante hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Des enfants de Sala, Maasias, fils de Gotholias; et avec lui soixante-dix hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 37, 'Des enfants de Saphatias, Zarias, fils de Michel; et avec lui quatre-vingts hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 38, 'Des enfants de Job, Abdias, fils de Jeheli; et avec lui deux cent douze hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 39, 'Des enfants de Banias, Salimoth, fils de Josaphia; et avec lui cent soixante hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 40, 'Des enfants de Béer, Zacharias, fils de Bébei; et avec lui deux cent huit hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 41, 'Des enfants d’Ezead, Jean, fils d’Eccetan; et avec lui cent dix hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 42, 'Des enfants d’Adonicam, qui sont les derniers et dont voici les noms: Eliphalam, fils de Gebel et Semeïas; et avec lui soixante-dix hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 43, 'Je les assemblai près du fleuve Thia, où nous campâmes pendant trois jours. Je fis ensuite la revue de cette multitude:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 44, 'Et n’y ayant trouvé aucun des fils des prêtres, ni des lévites,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 45, 'je choisis Eléazar,, Eccélon, Masman, Maloban, Enaathan, Saméa, Joribum, Natham, Envagam, Zacharias et Mosolanum, tous gens distingués et très-habiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 46, 'Je les envoyai vers Loddéum, qui était premier garde du trésor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 47, 'Et je les chargeai de lui dire, à lui, à ses frères et aux autres gardes du trésor, de nous envoyer ceux qui étaient destinés à exercer les fonctions du sacerdoce dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 48, 'Et comme la main favorable de notre Dieu était sur nous, ils nous amenèrent des hommes remplis de sagesse d’entre les enfants de Moholi, fils de Lévi, fils d’Israël, et Sarabia, avec ses fils et ses frères, qui faisaient en tout dix-huit personnes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 49, 'Des enfants de Chanania, Asbia, et Amin, avec leurs enfants, qui étaient quí au nombre de vingt personnes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 50, 'Et deux cent vingt de ceux que David et les princes avaient établis pour servir les lévites. Tous leurs noms étaient écrits dans les registres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 51, 'Après cela, j’ordonnai un jeune aux enfants d’ Israël en l’honneur du Seigneur, afin qu’il nous conduisit heureusement dans notre voyage; nous, tous ceux de notre suite, nos enfants et nos bestiaux; qu’il nous défendît contre tous les pièges;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 52, 'Car j’eus honte de demander au roi une escorte de gens de pied et de cheval pour nous mettre à couvert des insultes de nos ennemis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 53, 'Parce que nous lui avions dit que notre Dieu accordait toujours sa protection à ceux qui le cherchaient sincèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 54, 'Ensuite nous offrîmes nos prières au Seigneur qui nous a été favorable, et qui nous a fait ressentir les effets de sa protection.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 55, 'Je choisis ensuite douze hommes d’entre les chefs des familles et d’entre les prêtres, savoir: Sédébias, Asanna, et dix autres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 56, 'Et je pesai en leur présence l’or, l’argent, et les vases sacrés de la maison de notre Dieu, que le roi, les grands et les princes de sa cour, et tous les enfants d’Israël avaient offerts au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 57, 'Je leur mis donc entre les mains cent cinquante talents d’argent, des vases d’argent du poids de cent talents; cent talents d’or,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 58, 'Vingt-sept vases d’or, et douze d’un airain aussi fin et aussi brillant que l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 59, 'Et je leur dis: Vous êtes les ministres sacrés du Seigneur; ces vases sont aussi consacrés à son culte, et cet or et cet argent ont été offerts au Dieu de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 60, 'Gardez donc ce dépôt avec grand soin, jusqu’à ce que vous soyez de retour de Jérusalem et que vous l’ayez remis aux anciens du peuple, aux prêtres, aux lévites et aux chefs de familles, pour être conservé dans le temple dans le trésor du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 61, 'Les prêtres et les lévites, ayant reçu cet or et cet argent pour le porter à Jérusalem dans la maison de notre Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 62, 'Nous partîmes du fleuve Thia, le douzième du premier mois, continuant notre marche jusqu’à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 63, 'Y étant enfin arrivés, nous laissâmes passer trois jours, et le quatrième l’or et l’argent furent portés à la maison de notre Dieu, par Marimoth, fils de Jori, prêtre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 64, 'Il était accompagné d’Eléazar, fils de Phinées, de Josadus, fils de Jesu et de Médias, fils de Banni, le lévite;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 65, 'Et on écrivit sur-le-champ ce que pesait chaque chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 66, 'Alors ceux qui étaient revenus de captivité offrirent les sacrifices au Seigneur le Dieu d’Israël, savoir douze taureaux pour tout le peuple, quatre-vingt-six béliers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 67, 'Soixante-douze agneaux, douze boucs pour le péché, et douze génisses pour le salut; et le tout fut offert en sacrifice au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 68, 'Ensuite ils présentèrent les ordres du roi aux gouverneurs et aux satrapes de Célésyrie et de Phénicie: et depuis ce temps-là ils respectèrent le peuple d’Israël et le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 69, 'Et après que cela fut fait, les chefs des tribus me vinrent trouver et me dirent Le peuple d’Israël, ses chefs, les prêtres et les lévites, ne se sont point séparés');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 70, 'Des abominations des étrangers et des nations de la terre; des Chananéens, des Héthéens, des Phéréséens, des Jébuséens, des Moabites, des Égyptiens et des Iduméens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 71, 'Car ils ont pris de leurs filles et les ont épousées; ils ont aussi donné de ces filles à leurs fils, ils ont mêlé la race sainte avec les nations de la terre, et les princes et les grands d’Israël ont commis eux-mêmes cette iniquité dès le commencement de la captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 72, 'Lorsque je les eus entendus parler de la sorte, je déchirai mon manteau et ma tunique, je m’arrachai les cheveux de la tête et les poils de la barbe, et je m’assis tout abattu de tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 73, 'Alors tous ceux qui furent touchés des paroles du Dieu d’Israël, s’assemblèrent autour de moi pendant que je pleurais sur ce violemment de la loi; et dans la profonde tristesse où j’étais, je demeurai assis jusqu’au sacrifice du soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 74, 'Puis me levant du jeûne, et ayant mon manteau et ma tunique déchirés, je me mis à genoux et j’étendis mes mains vers le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 75, 'et je lui dis: Mon Dieu, je suis dans la confusion, et j’ai honte de lever les yeux devant vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 76, 'parce que nos péchés se sont élevés par-dessus nos têtes, que nos iniquités sont montées jusqu’au ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 77, 'Et que depuis le temps de nos pères jusqu’à ce jour nous n’avons point cessé de Vous offenser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 78, 'C’est pour cela que nous avons été livrés, nous, nos frères et nos prêtres, entre les mains des rois étrangers, et que nous avons été abandonnés, comme nous le sommes encore aujourd’hui, à l’épée, à la servitude, au pillage et à la confusion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 79, 'Et maintenant, Seigneur, combien est grande la miséricorde que vous nous faites de nous avoir laissés, nous qui sommes les rejetons de votre peuple; de nous avoir donné un établissement dans le lieu saint;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 80, 'd’avoir relevé la gloire et l’éclat de votre maison sainte, et de nous avoir nourris pendant tout le temps de notre esclavage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 81, 'Car notre Dieu ne nous point abandonnés pendant que nous avons été dans une terre étrangère; mais il nous a fait trouver grâce devant les rois de Perse, et leur a inspiré de nous donner les choses nécessaires à la vie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 82, 'de relever le temple, de rétablir Sion, qui avait été longtemps déserte et abandonnée, et de nous rétablir enfin dans Jérusalem et dans tout le pays de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 83, 'Et maintenant, ô mon Dieu, que dirons nous après tant de grâces? Car nous avons violé les commandements que vous nous aviez donnés par les prophètes vos serviteurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 84, 'en nous disant: La terre que vous allez posséder comme votre héritage est une terre impure, comme l’ont été celles de tous les autres peuples, et elle est remplie des ordures et des abominations dont ils l’ont couverte depuis une extrémité jusqu’à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 85, 'C’est pourquoi ne donnez point vos filles à leurs fils; ne prenez point leurs filles pour les faire épouser à vos fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 86, 'Et n’ayez jamais la paix avec eux, afin que, devenant puissants, vous mangiez en repos les biens de cette terre, et qu’après vous vos enfants en héritent et en jouissent pour jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 87, 'Tous ces maux nous sont arrivés à cause de la malignité de nos œuvres et de l’énormité de nos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 88, 'Vous nous aviez rendu notre première splendeur; et nous avons de nouveau transgressé votre loi, en prenant part à toutes les abominations des nations étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 89, 'Vous mettrez-vous donc en colère contre nous, jusqu’à exterminer entièrement votre peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 90, 'Seigneur Dieu d’Israël, vous êtes véritable dans vos promesses, nous sommes aujourd’hui les seuls restes véritables de la nation choisie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 91, 'Vous nous voyez abattus en votre présence dans la vue de nos iniquités: car, après ces excès, nous ne pouvons plus subsister devant votre face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 92, 'Lorsqu’Esdras priait de cette sorte, qu’il implorait la miséricorde de Dieu, qu’il répandait des larmes, et qu’il était étendu par terre devant le temple, une grande multitude d’hommes, de femmes, de jeunes garçons et de jeunes filles, s’assembla autour de lui; et tous ensemble ils pleurèrent amèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 93, 'Alors Jéchonias, fils de Jéhéli, élevant sa voix dit à Esdras: Nous avons violé la loi de notre Dieu, nous avons épousé des femmes parmi les nations étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 94, 'Et maintenant vous avez l’autorité sur tout le peuple d’Israël, jurons tous par le Seigneur que nous chasserons toutes ces femmes et tous ceux qui en sont nés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 95, 'Levez-vous donc et lisez au peuple la loi du Seigneur, comme nos pères nous l’ont ordonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 96, 'Car c’est à vous à le faire agissez donc avec force et nous vous y aiderons. Alors Esdras se leva et obligea les princes des prêtres, les lévites et tout le peuple d’Israël, de lui promettre avec serment qu’ils feraient ce qu’ils venaient de dire, et ils le lui jurèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Esdras, s’étant levé de devant le parvis du temple, s’en alla à la chambre de Jonathas, fils de Nasab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Et dans l’accablement où le jetaient les péchés du peuple, il y resta quelques jours sans prendre la moindre nourriture de pain ou d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Alors on publia dans toute la Judée que tous ceux qui étaient revenus de captivité s’assemblassent à Jérusalem;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'que l’on confisquerait les biens de quiconque ne s’y rendrait pas dans deux ou trois jours, selon l’ordre des anciens qui présidaient, et qu’il serait même regardé comme étranger par tous ceux de ses frères qui étaient revenus de la captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ainsi tous ceux de Juda et de Benjamin se trouvèrent à Jérusalem au temps marqué, et ils y vinrent le vingtième jour du neuvième mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Et tout le peuple se tint dans le parvis du temple, étant tout tremblant à cause du froid qu’il faisait alors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Et Esdras se levant leur dit: Vous avez commis l’iniquité en épousant des femmes étrangères, et vous avez ajouté ce péché à tous ceux d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Maintenant donc rendez gloire au Seigneur le Dieu de nos pères, et louez sa magnificence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Faites ce qui est agréable à ses yeux, en vous séparant des nations et des femmes étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Et tous répondirent à haute voix: Nous ferons ce que vous avez dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Mais parce que l’assemblée du peuple est grande, et que pendant le temps de l’hiver nous ne pouvons demeurer dehors, outre que ce n’est pas ici l’ouvrage d’un jour ni de deux, puisque un grand nombre d’entre nous sont coupables de ce péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Que les chefs du peuple et ceux d’entre nous qui ont épousé des femmes étrangères se présentent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Que les anciens et les magistrats viennent de tous les endroits, au jour qu’on leur marquera, jusqu’à ce qu’ils aient détourné la colère de notre Dieu, que nous nous sommes attirée par ce péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'On choisit donc pour cela Jonathas, fils d’Ezeli, et Ozias, fils de Thecam. On leur donna encore pour les aider Bozoramus, Lévis et Sabbathéus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Et ceux qui étaient revenus de captivité firent tout ce qui avait été ordonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 16, 'Alors Esdras, prêtre, choisit les');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 17, 'Et le dénombrement de ceux qui avaient épousé des femmes étrangères fut achevé le premier jour du premier mois de l’année suivante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 18, 'Entre les enfants des prêtres qui avaient épousé des femmes étrangères, on trouva ceux-ci:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 19, 'Des enfants de Jésus fils de Josédec et des enfants de ses frères, Maséas, Eliozerus, Joribus, et Joadéus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 20, 'On les obligea de chasser leurs femmes, et d’offrir un bélier pour l’expiation de leur péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 21, 'Des enfants de Semmeri: Maséas, Essès, Jéelech, Azarias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 22, 'Des enfants de Fosere, Limosias, Hismaënis, Nathanaée, Jussio, Reddus et Thalsas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 23, 'Des lévites: Jorabdus, Séméis, Colnis, Calitas, Factéas, Colvas et Elionas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 24, 'Des chantres sacrés: Eliasib, Zaccharus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 25, 'Des portiers: Salumus et Tolbanes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 26, 'Du peuple d’Israël: Des enfants de Foro Ozi, Rémias, Geddias, Melchias, Michel, Eléazar, Jammebias et Bannas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 27, 'Des enfants de Jolaman: Chamas, Zacharias, Jerrélus, Joddius, Hérimoth et Hélias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 28, 'Des enfants de Zathoïm: Eliadas, Liasumus, Zochias, Larimoth, Zabdis et Tébédias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 29, 'Des enfants de Zebès: Jean, Amanias, Zabdias et Eméus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 30, 'Des enfants de Banni: Olamus, Maluchus, Jeddéus, Jasub, Azabus et Jérimoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 31, 'Des enfants d’Abdin: Naathus, Moosias, Caléus, Raanas, Maaséas, Mathathias, Beséel, Bonnus et Manassès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 32, 'Des enfants de Nuaé: Nonéas, Asé, Melchias, Saméas, Simon, Benjamin, Ms. chus et Marras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 33, 'Des enfants d’Asom: Carianéus, Mathathias, Bannus, Eliphalac, Manassés et Siméi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 34, 'Des enfants de Banni: Jérémias, Moadias, Abram, Johel, Banéas, Pélias, Jonas, Marimoth, Eliasib, Mathanéus, Eliasis, Orizas, Dielus, Semedius, Zambris et Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 35, 'Des enfants de Nobéi: Idelus, Maththias, Sabadus, Zéchéda, Sédémi, Gesséi et Banéas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 36, 'Tous ceux-là avaient épousé des fermes étrangères, et ils les renvoyèrent avec les enfants qu’ils en avaient eus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 37, 'Les prêtres, les lévites, et tous les enfants d’Israël établis en Judée, se rendirent de tous côtés à Jérusalem, le premier jour du septième mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 38, 'Et s’étant tous assemblés dans la place de la porte sacrée qui est à l’orient,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 39, 'ils dirent à Esdras, prêtre et docteur, de leur apporter la loi que le Seigneur le Dieu d’Israël leur avait donnée par le ministère de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 40, 'Et le premier jour du septième mois, le pontife Esdras apporta la loi pour la lire à toute cette multitude, aux prêtres, aux hommes et aux femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 41, 'Et il la lut au milieu de la place qui est vis-à-vis la porte sacrée, depuis le matin jusqu’au soir, en présence des hommes et des femmes, et ils l’écoutèrent tous avec beaucoup d’attention.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 42, 'Esdras, prêtre et docteur, monta sur un tribunal de bois, élevé à ce dessein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 43, 'Il avait à sa droite, Mathathias, Samus, Ananias, Azarias, Urias, Ezéchias et Balsamus:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 44, 'Et à sa gauche, Faldeus, Misael, Malachias, Abusthas, Sabus, Nabadias et Zacharias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 45, 'Esdras prit le livre de la loi en présence de toute cette multitude au milieu de laquelle il présidait avec éclat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 46, 'Et quand il eut cessé de lire, tous se levèrent et se tinrent debout, pendant qu’Esdras bénissait le Seigneur, le Dieu tout-puissant, le Dieu des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 47, 'Tout le peuple répondit: Ainsi soit-il. Et levant les mains en haut, ensuite s’étant prosternés en terre, ils adorèrent le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 48, 'Et les lévites, Jésus, Banaéus, Sareias, Jaddimus, Accubus, Sabbathéus, Calihès, Azarias, Joradus, Ananias et Philias, lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 49, 'Et ils lisaient la loi du Seigneur a tout e peuple, et la lui expliquaient en même emps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 50, 'Atharathes dit ensuite à Esdras, prêtre et docteur, et aux lévites qui instruisaient le peuple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 51, 'Ce jour est consacré au Seigneur; cependant toute cette multitude entendant les paroles de la loi se mit à pleurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 52, 'Et Esdras leur dit: Retournez chacun chez vous, allez manger les viandes les plus grasses, et boire les vins les plus délicieux, et faites-en part à tous ceux qui n’en ont point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 53, 'Ce jour est consacré au Seigneur, et vous ne devez point le passer dans la tristesse; car le Seigneur va relever la gloire d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 54, 'Et les lévites allaient partout criant à haute voix. Ce jour est consacré au Seigneur, ne le passez point dans la tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 55, 'Alors ils se séparèrent tous pour aller boire, manger et se divertir; et ils firent part de leur abondance à ceux qui étaient dans le besoin; car ils avaient été extrêmement pénétrés des paroles de la loi. Et tous les enfants d’Israël se trouvèrent assemblés à Jérusalem pour y célébrer cette fête, selon l’ordre qu’ils en avaient reçu du Seigneur, le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'La première année de la domination de Cyrus, rọi des Perses, la parole du Seigneur qu’avait proférée la bouche de Jérémie le prophète, devait s’accomplir; le Seigneur excita l’esprit de Cyrus, roi des Perses, et il envoya en tout son royaume une proclamation par écrit, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Voici ce qu’a dit Cyrus, roi des Perses: Le Seigneur Dieu du ciel m’a donné tous les royaumes de la terre, et lui-même a jeté les yeux sur moi pour que je lui bâtisse un temple à Jérusalem en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Qui donc, parmi vous tous, est de son peuple? Son Dieu sera avec lui, et il partira pour Jérusalem en Judée; qu’il y bâtisse le temple du Dieu d’Israël; le seul Dieu est celui qui réside à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Tous ceux de ce peuple qui vivent encore, en quelque lieu qu’ils habitent, les hommes de ce lieu les aideront de dons en argent, en or, en meubles, ou en bestiaux, outre ce qu’ils offriront volontairement pour le temple de Dieu à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Alors, se levèrent les chefs de famille de Juda et de Benjamin, et les prêtres et les lévites, tous ceux que l’Esprit de Dieu excita à partir et à relever le temple du Seigneur à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Et tous ceux qui les entouraient leur fortifièrent les mains avec des vases d’argent, de l’or, des meubles, des bestiaux et des présents, outre les dons volontaires pour le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Et le roi Cyrus offrit les vases du temple du Seigneur que Nabuchodonosor avait enlevés de Jérusalem, et qu’il avait dédiés au temple de son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Cyrus, roi des Perses, les donna par la main de Mithradate le trésorier, et celui-ci les compta avec Sasabasar, chef de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'En voici le nombre: trente coupes d’or, mille d’argent, vingt-neuf de divers genres, trente coupes d’or,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Quatre cent dix doubles coupes d’argent, et mille autres vases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Il y avait en tout cinq mille quatre cents vases d’or et d’argent qui furent emportés par Sasabasar, du lieu d’exil de Babylone, à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Et voici les fils de la terre promise qui partirent de la captivité et du lieu d’exil où les avait transportés Nabuchodonosor, roi de Babylone, pour retourner à Jérusalem et en Juda, chacun en sa ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Ceux qui partirent avec Zorobabel furent: Josué, Néhémias, Saraïas, Réhélias, Mardochée, Balasan, Masphar, Bachué, Rehum, Baana. Voici le dénombrement du peuple d’Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Fils de Pharès: deux mille cent soixante-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Fils de Saphatia: trois cent soixante-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Fils d’Arès sept cent soixante-quinze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Fils de Phaath-Moab, issus des fils de Josué et de Joab deux mille huit cent douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Fils d’Elam: mille deux cent cinquante-quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Fils de Zatthua: neuf cent quarante-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Fils de Zacchu sept cent soixante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Fils de Banui: six cent quarante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Fils de Babaï six cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Fils d’Asgad: mille deux cent vingt-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Fils d’Adonicam: six cent soixante-six.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Fils de Bagué: deux mille cinquante-six.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Fils d’Addin quatre cent cinquante-quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Fils d’Ater, issu d’Ezéchias: neuf cent huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Fils de Bassu: trois cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Fils de Jora: cent douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Fils d’Asum: deux cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Fils de Gaber: quatre-vingt-quinze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 21, 'Fils de Bethléem: cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 22, 'Fils de Netopha: cinquante-six.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 23, 'Fils d’Anathoth cent vingt-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 24, 'Fils d’Asmoth: quarante-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 25, 'Fils de Cariathiarim, Haphira et Beroth: sept cent quarante-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 26, 'Fils de Rhama et de Gabaa: six cent vingt et un.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 27, 'Hommes de Machmas: cent vingt-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 28, 'Hommes de Béthel et d’Aïa: quatre cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 29, 'Fils de Nabu: cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 30, 'Fils de Magebis: cent cinquante-six.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 31, 'Fils d’Elamar: douze cent cinquante-quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 32, 'Fils d’Elam: trois cent vingt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 33, 'Fils de Lodadi et d’Ono, sept cent vingt-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 34, 'Fils de Jéricho: trois cent quarante-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 35, 'Fils de Senaa: trois mille six cent trente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 36, 'Prêtres, fils de Jedua, de la maison de Josué: neuf cent soixante-treize.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 37, 'Fils d’Emmer: mille cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 38, 'Fils de Phassur: douze cent quarante-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 39, 'Fils d’Erem: mille sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 40, 'Lévites, fils de Josué et de Cadmiel, des fils d’Oduia soixante-quatorze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 41, 'Chantres, fils d’Asaph cent vingt-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 42, 'Fils des portiers: fils de Sellom, fils d’Ater, fils de Telmon, fils d’Acub, fils d’Atita, fils de Sobaï: en tout, cent trente-neuf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 43, 'Les Nathinéens: fils de Suthia, fils d’Asupha, fils de Tabaoth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 44, 'Fils de Cadès, fils de Siaa, fils de Phadon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 45, 'Fils de Labano, fils d’Agaba, fils d’Acub,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 46, 'Fils d’Agab, fils de Selam, fils d’Anan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 47, 'Fils de Geddel, fils de Gaar, fils de Rhaïa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 48, 'Fils de Rason, fils de Necoda, fils de Gazem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 49, 'Fils d’Azo, fils de Phasé, fils de Basi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 50, 'Fils d’Asena, fils de Mounim, fils de Nephusim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 51, 'Fils de Bacbuc, fils d’Acupha, fils d’Arur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 52, 'Fils de Basaloth, fils de Maüda, fils d’Arsa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 53, 'Fils de Barcos, fils de Sisara, fils de Théma,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 54, 'Fils de Nasthié, fils d’Atupha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 55, 'Fils de serviteurs de Salomon, fils de Sotaï, fils de Sephèra, fils de Phadura,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 56, 'Fils de Jehèla, fils de Darcon, fils de Gedel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 57, 'Fils de Saphatia, fils d’Atil, fils de Phacherath, fils d’Aseboïm, fils d’Emeï;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 58, 'Total des Nathinéens et des fils d’Abdeselma: trois cent quatre-vingt-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 59, 'Et voici tous ceux qui partirent de Thelmelech: Thelaresa, Cherub, Hédan, Emmer; et ils n’étaient point');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 60, 'Fils de Dalaïa, fils de Bua, fils de Tobias, fils de Necoda six cent cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 61, 'Et parmi les fils des prêtres, les fils de Labia, les fils d’Accus, les fils de Berzellaï, qui épousa l’une des filles de Berzellaï le Galaadite, et qui prit son nom;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 62, 'Ceux-là cherchèrent leur généalogie, mais ils ne la trouvèrent pas, et ils furent rejetés du sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 63, 'Et l’athersastha leur dit de ne point manger des choses les plus saintes jusqu’à ce qu’un prêtre fût suscité, portant lumières et perfections.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 64, 'Or, toute l’Église réunie montait à environ quarante-deux mille trois cent soixante ames.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 65, 'Sans compter leurs serviteurs et leurs servantes au nombre de sept mille trois cent trente-sept, parmi lesquels il y avait deux cents chantres et chanteuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 66, 'Ils avaient sept mille trente-six chevaux, deux cent quarante-cinq mulets,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 67, 'Quatre cent trente-cinq chameaux, six mille sept cent vingt ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 68, 'Et quelques-uns des chefs de famille, lorsqu’ils entrèrent dans le temple du Seigneur à Jérusalem, offrirent volontairement de le relever au lieu qui était préparé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 69, 'Autant que le comportaient leurs richesses; ils donnèrent donc, au trésor des travaux, soixante et un mille mines d’or pur, cinq mille mines d’argent, et cent costumes sacerdotaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 70, 'Et les prêtres, et les lévites, et ceux du peuple, et les chantres, et les portiers, et les Nathinéens, et tout Israël, s’établirent dans leurs villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Et le septième mois arriva, et les fils d’Israël étaient dans leurs villes, et le peuple se rassembla comme un seul homme à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Et Josué, fils de Josédec, et les prêtres, ses frères, et Zorobabel, fils de Salathiel, et ses frères, s’étant mis en avant, bâtirent l’autel du Seigneur leur Dieu pour y offrir des holocaustes, comme il est écrit en la loi de Moïse, homme de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Ils le relevèrent d’abord où il était autrefois, car ils avaient crainte des peuples d’alentour; ils rétablirent l’holocauste du Seigneur, le matin et le soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Et ils célébrèrent la fête des tabernacles, ainsi qu’il est écrit, faisant les holocaustes quotidiens, selon le nombre déterminé jour par jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Puis, après la fête, ils offrirent l’holocauste perpétuel, les sacrifices des nouvelles lunes, et de toutes les fêtes consacrées au Seigneur, et ceux que l’on offrait volontairement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Le premier jour du septième mois, ils commencèrent à offrir des holocaustes au Seigneur, et les fondations du temple n’étaient pas encore jetées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Et ils donnèrent de l’argent aux tailleurs de pierres, aux charpentiers; quant aux Sidoniens et aux Tyriens qui leur amenèrent jusqu’au port de Joppé des cèdres du Liban, selon la permission que Cyrus, roi des Perses, leur avait accordée, ils leur donnèrent le manger et le boire, et de l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Et la seconde année de leur retour dans le temple du Seigneur à Jérusalem, le second mois, Zorobabel, fils de Salathiel; Josué, fils de Josedec, ce qui restait de leurs');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Josué, ses fils et ses frères; Cadmiel, de la maison de Juda, et ses fils, prirent la direction des travaux qui se faisaient dans le temple, secondés par les lévites, fils d’Henadad, et leurs fils et leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Ils jetèrent les fondations pour y asseoir le temple du Seigneur; cependant, les prêtres, revêtus de leurs robes, sonnèrent de la trompette, et les lévites, fils d’Asaph, au bruit des cymbales, chantaient les louanges du Seigneur, comme l’avait prescrit David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Ils louaient le Seigneur et lui rendaient grâces tour à tour, parce qu’il est bon, parce que sa miséricorde envers Israël doit durer toujours. Et dans sa joie, tout le peuple, à grands cris, louait le Seigneur, à cause de la fondation du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Et un grand nombre de prêtres, de lévites, de chefs de famille, avancés en âge, qui avaient vu le temple dans son premier état, et qui revoyaient de leurs yeux ce temple, élevaient la voix et pleuraient, tandis que la foule, en signe de joie, élevait encore plus haut le chant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Et nul ne pouvait distinguer les marques d’allégresse de la voix de ceux qui pleuraient, parce que le peuple jetait de grands cris, et que la rumeur en retentissait au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Et ceux qui opprimaient Juda et Benjamin ouïrent que les enfants de la captivité bâtissaient un temple au Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Et ils s’approchèrent de Zorobabel et des chefs de famille, et ils leur dirent: Nous bâtirons avec vous, parce que, comme vous, nous cherchons notre Dieu, et que nous lui sacrifions, depuis le temps d’Asaradan, roi des Assyriens, qui nous a transportés ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Et Zorobabel, et Josué, et le reste des chefs de famille d’Israël, leur répondirent: Ce n’est pas avec vous que nous bâtirons un temple à notre Dieu; car, nous seuls, tous ensemble, nous bâtirons au Seigneur notre Dieu, comme nous l’a prescrit Cyrus, roi des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Et le peuple de la terre affaiblissait les mains de Juda, et il l’empêchait de bâtir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Et des gens, salariés pour nuire aux fils de Juda, complotèrent pour ruiner leurs desseins, tant que vécut Cyrus, jusqu’au règne de Darius, roi des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Au commencement du règne d’Assuérus, ils écrivirent une lettre contre ceux qui habitaient Jérusalem et Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Et, durant les jours d’Arthasastha, Tabéel écrivit une lettre bienveillante à Mithradate et aux autres serviteurs; le collecteur des impôts écrivit à Arthasastha, roi des Perses, une lettre en syriaque avec la traduction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Rheum le chancelier, et Samsa le scribe, écrivirent aussi une lettre contre Jérusalem au roi Arthasastha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Voici ce que jugent Rhéum le chancelier, Samsa le scribe, et le reste de ceux qui, avec nous, sont tes serviteurs les Dinéens, les Apharsalhachéens, les Tharphaléens, les Apharséens, les Archyéens, les Babyloniens, les Susanachéens, les Davéens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Et les autres nations que le grand et vénérable Assenaphar a transportées dans les villes de Samarie; celles qui résident sur le territoire en deçà du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Suit la teneur de la lettre qu’ils envoyèrent: À Arthasastha, roi, ses serviteurs, en deçà du fleuve:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Que le roi sache que les Juifs qui sont partis de son territoire pour cette terre sont arrivés à Jérusalem, ville rebelle et méchante, qu’ils la rebâtissent, qu’ils en ont restauré les remparts, et qu’ils les ont élevés au-dessus des fondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Que le roi sache bien qu’aussitôt leur ville reconstruite et leurs murs réparés, ils cesseront d’être tes tributaires, ils ne donneront rien; et ainsi, ils feront tort aux rois;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Et il ne nous est point possible de voir le roi outragé; c’est pourquoi nous avons envoyé un message pour instruire le roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Afin que l’on regarde dans le livre des archives de tes pères, où tu trouveras et tu apprendras que cette ville est une ville rebelle, qu’elle fait tort aux rois et aux royaumes, qu’il y a toujours eu chez elle des esclaves fugitifs, et que c’est pour cela qu’elle a été dépeuplée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Nous déclarons donc au roi que, si cette ville est rebâtie, si ses remparts sont relevés, il n’y aura plus de paix pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Et le roi envoya dire à Rhéum le chancelier, à Samsa le scribe, et à ses serviteurs qui habitaient en Samarie et en deçà du fleuve: La paix;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Le collecteur des impôts que vous nous avez envoyé a été appelé devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Et j’ai fait un édit; puis, nous avons examiné, et nous avons trouvé que cette ville de tout temps s’est soulevée contre les rois; que la rébellion, que la désertion y résident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Or, il y a eu en Jérusalem des rois puissants; ils ont maîtrisé toute la contrée au delà de l’Euphrate; d’abondants revenus et des impôts leur ont été payés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Maintenant donc, faites un édit pour suspendre le travail de ces hommes; cette ville ne sera plus rebâtie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Soyez attentifs à maintenir cet édit; ne vous en relâchez point, de peur qu’un jour le mal ne s’y aggrave au détriment du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Le collecteur des impôts d’Arthasastha, roi, lut donc cette lettre devant Rhéum le chancelier, Samsa le scribe, et les autres serviteurs du roi, et ils allèrent en toute hâte à Jérusalem et en Juda avec des troupes et de la cavalerie, et ils arrètèrent les travaux du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 24, 'Ainsi, la reconstruction du temple de Dieu fut suspendue à Jérusalem, et on ne la reprit qu’à la seconde année du règne de Darius.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Or, Aggée le prophète, et Zacharie, fils d’Addo, firent, devant les Juifs qui se trouvaient en Juda et à Jérusalem, au nom du Dieu d’Israël, une prophétie qui les concernait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Alors, Zorobabel, fils de Salathiel, et Josué, fils de Josedec, se mirent en avant, et ils commencèrent à bâtir le temple de Dieu à Jérusalem, et les prophètes de Dieu étaient avec eux, leur prêtant secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'En ce temps-là, Thanthanaï, gouverneur de ce côté de l’Euphrate, et Satharbuzanaï, et les autres serviteurs du roi, vinrent à eux, et leur dirent: Qui a fait en votre faveur un édit pour que vous bâtissiez ce temple et que vous fassiez ces apprêts?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Et ils ajoutèrent: Quels sont les noms des hommes qui bâtissent cette ville?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Mais les yeux de Dieu étaient ouverts sur la captivité de Juda, et ces hommes ne suspendirent pas les travaux jusqu’à ce qu’un édit fût fait par Darius. Et alors, à ce sujet, le collecteur des impôts envoya');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'La traduction de la lettre qu’avaient écrite, pour le roi Darius, Thanthanaï, gouverneur de ce côté de l’Euphrate; Satharbuzanaï et les autres Apharsachéens, serviteurs du roi, sur la rive droite de l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Ils avaient écrit pour lui un rapport, et voici en quels termes: Paix entière au roi Darius.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Que le roi sache que nous sommes allés en Judée dans le temple du grand Dieu; or, ce temple est rebâti en pierres de choix, et des bois sont placés sur les murs, et ce travail est bien exécuté, et il va bien entre leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Après l’avoir vu, nous avons interrogé les anciens, et nous leur avons ainsi parlé: Qui a fait en votre faveur un édit pour que vous bâtissiez ce temple, et que vous fassiez ces apprêts?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Et nous leur avons demandé leurs noms, afin de te les faire connaître, et de prendre par écrit les noms de leurs chefs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Et voici ce qu’ils nous ont répondu: Nous sommes les serviteurs du Dieu du ciel et de la terre, et nous relevons ce temple qui avait été construit il y a bien des années; un grand roi d’Israël l’avait bâti, et il l’avait établi pour son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Mais, après cela, nos pères ont irrité le Dieu du ciel, qui les a livrés à Nabuchodonosor le Chaldéen, roi de Babylone; celui-ci a détruit ce temple, et emmené le peuple captif à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Mais, dans la première année de sa domination, Cyrus, roi des Perses, a fait un édit pour que le temple de Dieu fût rebâti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Et il a retiré du temple du roi les vases d’or et d’argent du temple de Dieu, enlevés de Jérusalem par Nabuchodonosor, et placés dans le temple de Babylone, et il les a remis au trésorier Sabanasar;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Et il lui a dit: Prends tous ces vases, pars, et remets-les à leur place dans le temple de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Alors, ce Sabanasar est venu, et il a jeté les fondations du temple de Dieu à Jérusalem; depuis ce temps, jusqu’à cette heure, on a travaillé à le construire, et il n’est pas encore achevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Et maintenant, si le roi le trouve bon, qu’il fasse faire des recherches dans le palais du trésor du roi de Babylone, afin de s’assurer que le roi Cyrus a fait un édit pour que le temple de Dieu fût relevé en Jérusalem; et, quand le roi s’en sera informé, qu’il envoie auprès de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Alors, le roi Darius fit un édit pour que l’on cherchât dans les bibliothèques où est le trésor de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Et l’on trouva en cette ville, dans le palais, un chapitre où ce mémorial était écrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'En la première année de la domination du roi Cyrus, le roi Cyrus a fait cet édit, touchant le saint temple de Dieu à Jérusalem: Que le temple soit rebâti, ainsi que le lieu où l’on sacrifiait des victimes. Et il en a déterminé la hauteur et la largeur: soixante coudées des deux parts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Et il a ajouté: Qu’il y ait trois étages en pierres dures et un en bois, et que la dépense soit supportée par le trésor royal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Que l’on rende les vases d’or et d’argent du temple de Dieu, apportés de Jérusalem par Nabuchodonosor, et mis à Babylone; qu’ils retournent au temple de Jérusalem, à la place où ils étaient, dans le temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Maintenant, vous, gouverneurs au delà du fleuve, vous, Satharbuzanaï et Apharsachéens, mes serviteurs au delà du fleuve, donnez-leur ces choses, et tenez-vous loin d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Laissez faire les travaux du temple de Dieu: que les chefs des Juifs, que leurs anciens bâtissent le temple au lieu où il était.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Un édit est aussi rendu par moi pour que vous ne vous mêliez en rien de ce que feront les anciens des Juifs, pendant qu’ils bâtiront le temple de ce Dieu, et que, dans le but de ne point arrêter les travaux, on donne avec zèle à ces hommes, sur les impôts du roi, levés au delà de l’Euphrate, ce qu’il faudra pour la dépense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Et, ce qui viendrait à leur manquer, qu’on le leur donne jour par jour, à mesure qu’ils le demanderont, soit des bœufs, des béliers, des agneaux, pour les holocaustes du Dieu du ciel, soit du froment, du sel, du vin et de l’huile, selon le besoin des prêtres qui se trouvent à Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Afin qu’ils fassent aisément leurs offrandes d’odeur de suavité au Dieu du ciel, et qu’ils prient pour la vie du roi et de ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Et j’ai fait un édit portant que quiconque s’écartera de mes ordres sera attaché à une poutre enlevée de sa maison, et mis à mort sur ce bois, et que sa maison sera confisquée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Puisse le Dieu, dont le nom résidera en ce temple, renverser tout roi ou peuple qui étendra la main pour endommager ou détruire le temple de Dieu à Jérusalem. Moi, Darius, j’ai fait cet édit; qu’on soit attentif à s’y conformer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Alors, Tanthanaï, gouverneur en deçà de l’Euphrate; Satharbuzanaï, et les autres serviteurs du roi à qui Darius avait écrit, lui obéirent avec zèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Et les anciens des Juifs et les lévites bâtirent, selon la prophétie d’Aggée le prophète, et de Zacharie, fils d’Addo; et ils bâtirent, et ils achevèrent le temple suivant la volonté de Dieu, et grâce aux édits de Cyrus, de Darius et d’Arthasastha, rois des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Et ils achevèrent le temple le troisième jour du mois d’adar, et la sixième année du règne de Darius.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Et les fils d’Israël, et les prêtres, et les lévites, et le reste des fils de l’exil, firent, avec allégresse, la dédicace du temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Pour la dédicace du temple de Dieu, ils offrirent cent bœufs, deux cents béliers, quatre cents agneaux; et l’offrande pour les péchés de tout Israël fut de douze boucs, nombre égal à celui des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Ils rétablirent les prêtres selon leurs divisions, et les lévites selon leurs catégories, pour le service de Dieu à Jérusalem, comme il est écrit au livre de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Et les fils de l’exil firent la Pâque le quatorzième jour du second mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 20, 'Car les prêtres et les lévites s’étaient purifiés; ils avaient tous été reconnus purs. Et ils immolèrent la pâque pour tous les fils de l’exil, et pour leurs frères les prêtres et les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 21, 'Et les fils d’Israël mangèrent la pâque, tant ceux qui étaient revenus de l’exil que ceux qui s’étaient préservés de l’impureté des peuples de la contrée, leurs voisins, et qui avaient cherché le Seigneur Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 22, 'Et ils célébrèrent la fête des Azymes durant sept jours avec allégresse; car le Seigneur les réjouit, et il avait incliné le cœur du roi d’Assyrie en leur faveur pour fortifier leurs mains dans les travaux du temple du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Et, après ces événements, sous le règne d’Arthasastha, roi des Perses, partit Esdras, fils de Saraïas, fils d’Azarias, fils d’Helcias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Fils de Selum, fils de Saddoc, fils d’Achitob,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Fils de Samarias, fils d’Esrias, fils de Maréoth, 4. Fils de Zaraïas, fils d’Ozias, fils de Bocci,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Fils d’Abisué, fils de Phinéès, fils d’Eléazar, fils d’Aaron le premier prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Cet Esdras partit de Babylone; il était scribe et trèsinstruit en la loi de Moïse donnée par le Seigneur Dieu d’Israël. Et le roi le lui permit, parce que la main du Seigneur son Dieu était près de lui en tout ce qu’il demandait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Et des chantres, et des portiers, et des Nathinéens, parmi les fils d’Israël, prêtres ou lévites, partirent pour Jérusalem en la septième année du règne du roi Arthasastha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Et ils arrivèrent à Jérusalem le cinquième mois de cette même année;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Car, le premier jour du premier mois, ils commencèrent à partir de Babylone, et, le premier jour du cinquième mois, ils entrèrent à Jérusalem, parce que la main du Seigneur était favorable à Esdras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Esdras, en effet, s’était adonné de tout son cœur à étudier la loi, à la mettre en pratique, et à enseigner aux fils d’Israël les commandements et les préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Et voici la traduction de l’ordre qu’Arthasastha donna à Esdras, scribe du livre des lois et commandements du Seigneur, plus de ses prescriptions concernant Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Arthasastha, roi des rois, à Esdras, scribe de la loi du Seigneur Dieu du ciel: Que ta demande et ma réponse s’accomplissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'J’ai fait un édit pour que, dans mon royaume, tout homme du peuple d’Israël, et des prêtres, et des lévites, qui le voudra, parte avec toi pour Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Esdras est envoyé par le roi et ses sept conseillers, pour visiter la Judée et Jérusalem, conformément à la loi de Dieu qui est en ta main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Et tu porteras l’or et l’argent que le roi et ses conseillers offrent volontairement, pour le temple du Seigneur, au Dieu d’Israël qui réside en Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Et tout l’argent et l’or que tu recueilleras en tout le royaume de Babylone, donné volontairement par le peuple et les prêtres, pour le temple de Dieu à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'À tous ceux qui iront à ce temple, prescris équitablement, selon ta loi, d’amener des agneaux avec leurs oblations et leurs libations; tu les offriras sur l’autel du temple du Seigneur votre Dieu à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Et si à toi et à tes frères il plaît, avec le reste de l’or et de l’argent, de faire quelque chose, faites-le comme il sera agréable à votre Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Et remettez en leur place, devant Dieu à Jérusalem, les vases qui te sont donnés pour le service du temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'S’il est en outre des choses nécessaires au temple de ton Dieu qu’il te semble bon de donner, tu les donneras aux frais du trésor royal');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Et de mon domaine. Moi, Arthasastha, roi, j’ai fait un édit pour que l’on donne promptement à Esdras, prêtre et scribe du Dieu du ciel, tout ce qu’il vous demandera mandera des trésors publics qui sont au delà de l’Euphrate,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Jusqu’à cent talents d’argent, cent mesures de froment, cent tonneaux de vin, cent tonnes d’huile; outre le sel, dont la quantité n’est pas fixée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Que tout ce qui est selon la volonté du Dieu du ciel soit exécuté. Et vous, mes serviteurs, veillez à ce que nul ne mette la main sur le temple du Dieu du ciel, de peur que sa colère ne s’allume contre le royaume du roi et de ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Sachez aussi, pour ce qui regarde tous les prêtres, lévites, chantres, portiers, Nathinéens, employés au service de ce Dieu, qu’ils n’ont point à vous payer d’impôt, et que vous n’avez point le pouvoir de leur rien demander de servile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Et toi, Esdras, comme tu as en ta main la sagesse de Dieu, institue des scribes et des juges, afin qu’au delà du fleuve ils rendent la justice à tout le peuple, à tous ceux qui connaissent la loi de ton Dieu, et enseignez cette loi à ceux qui l’ignorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Et quiconque ne se conformera pas avec zèle à la loi de Dieu et à la loi royale, sera jugé et condamné à mort, ou à une correction, ou à l’amende sur son bien, ou à la prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Béni soit le Seigneur Dieu de nos pères, qui a donné au roi un tel cœur, pour glorifier le temple du Seigneur à Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Et qui a fait tourner sur moi les yeux et la miséricorde du roi, de ses conseillers, des chefs du royaume et des grands. Et moi, j’ai été fortifié par la main bienveillante de Dieu qui s’est posée sur moi, et j’ai rassemblé les chefs d’Israël pour les emmener avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Et voici les noms des chefs de familles, qui sont venus avec moi sous le règne d’Arthasastha, roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Des fils de Phinéès, Gerson; des fils d’Ithamar, Daniel; des fils de David, Attus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Des fils de Sachanie et des fils de Phoros, Zacharie, et avec lui ses compagnons, cent cinquante hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Des fils de Phaath-Moab, Eliana, fils de Saraïa, et avec lui deux cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Et des fils de Zathoé, Sechénias, fils d’Aziel, et avec lui trois cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Et des fils d’Adin, Obed, fils de Jonathas, et avec lui cinquante hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Et des fils d’Elam, Isaïe, fils d’Athélie, et avec lui soixante-dix hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Et des fils de Saphatie, Zabadie, fils de Michel, et avec lui quatre-vingts mâles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Et des fils de Joab, Abadie, fils de Jehiel, et avec lui deux cent dix-huit hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Et des fils de Baani, Selimuth, fils de Joséphie, et avec lui cent soixante hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Et des fils de Babi, Zacharie, fils de Babi, et avec lui vingt-huit måles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Et des fils d’Asgad, Johanan, fils d’Accatan, et avec lui cent dix mâles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Et des fils d’Adonicam, les derniers, et voici leurs noms: Eliphalat, Jehel et Samaïa, et avec eux soixante mâles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Et des fils de Baguaï, Uthaï et Zabud, et avec eux soixante-dix mâles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Je les réunis vers le fleuve qui se rend à Evi, et nous y restâmes campés trois jours; et je m’informai du peuple et des prêtres, et je ne trouvai là pas un fils de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Ensuite, je donnai mes ordres à Eléazar, à Ariel, à Sémeïas et à Alonam, à Jarib, à Elnatham, à Nathan, à Zacharie, à Mesollam, à Joarim et à Elthanan, hommes doués de sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Et je les envoyai aux chefs, avec l’argent recueilli dans la contrée, et je leur mis sur les lèvres les paroles qu’ils avaient à dire à leurs frères les Athinéens, en leur remettant l’argent recueilli dans la contrée, afin qu’ils nous amenassent des chantres pour le temple de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Et comme la main de Dieu nous était favorable, ils nous amenèrent un homme: Sachon, des fils de Mooli, fils de Lévi, fils d’Israël, et d’abord arrivèrent ses fils et ses frères, en tout dix-huit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 19, 'Ils nous amenèrent aussi Asebie et Isaïe, des fils de Mérari, et ses frères et ses fils, vingt personnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 20, 'Et des Nathinéens que David et les chefs avaient donnés pour serviteurs aux lévites, deux cent vingt, tous désignés par leurs noms.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 21, 'Et là, sur le fleuve Ahua je proclamai un jeûne, pour nous humilier devant notre Dieu, et chercher par lui le droit chemin, pour nous et nos enfants, et tout notre bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 22, 'En effet, j’aurais eu honte de demander au roi des troupes et de la cavalerie, pour nous protéger en route contre tout ennemi, car nous avions dit au roi: La main de notre Dieu est sur tous ceux qui le cherchent pour le bien; mais sa puissance et sa colère sont sur tous ceux qui l’abandonnent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 23, 'Et nous jeûnâmes, nous fîmes à ce sujet notre prière au Seigneur, et il nous exauça.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 24, 'Et je donnai mes ordres à douze des chefs des prêtres à Saraïas, Asabie, et dix de leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 25, 'Et je pesai pour eux l’argent, l’or et les vases des prémices consacrées dans le temple de notre Dieu, que le roi, ses conseillers, ses princes, et tous ceux d’Israël, qu’on avait trouvés, avaient offerts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 26, 'Je pesai ainsi entre leurs mains six cent cinquante talents d’argent, cent vases d’argent et cent talents d’or;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 27, 'Et vingt tasses d’or du poids d’environ mille drachmes, et des vases de grand prix, en bel airain brillant, aussi précieux que s’ils eussent été d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 28, 'Puis, je leur dis: Vous êtes saints aux yeux du Seigneur; les vases sont saints, l’argent et l’or ont été volontairement donnés pour le Seigneur Dieu de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 29, 'Veillez sur eux et gardez-les jusqu’à ce que vous les pesiez devant les princes des prêtres, devant les lévites et devant les chefs de familles de Jérusalem, dans le tabernacle du temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 30, 'Cet or et cet argent pesés de cette manière, les prêtres et les lévites les reçurent pour les porter à Jérusalem, dans le temple du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 31, 'Alors, je levai mon camp du fleuve Ahua, le douzième jour du premier mois, pour aller à Jérusalem. Et la main du Seigneur notre Dieu était sur nous, et il nous préserva en route de tout ennemi, de toute attaque ou de toute hostilité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 32, 'Nous arrivâmes à Jérusalem, et nous y demeurâmes trois jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 33, 'Le quatrième jour, nous pesâmes l’argent, l’or et les vases, dans le temple du Seigneur, entre les mains de Merimoth, fils d’Urie, le prêtre, en présence d’Eléazar, fils de Phinéès; il y avait avec eux les lévites Josabad, fils de Josué, et Noadia, fils de Banaïa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 34, 'On en fit le compte, on en prit le poids, et le poids total fut écrit. En ce temps-là,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 35, 'Les fils de l’exil revenus de la captivité offrirent en holocauste, au Dieu d’Israël, douze bœufs pour tout Israël, quatre-vingt-onze béliers, soixante-dix-sept agneaux, et douze boucs pour le péché; tout cela fut offert en holocauste au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 36, 'Et les édits du roi furent donnés à ses intendants et à ses gouverneurs, d’en deçà du fleuve, qui glorifièrent. le peuple et le temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Après cela, les chefs vinrent me trouver, et ils me dirent Le peuple d’Israël, les prêtres, les lévites, ne sont plus séparés des peuples de la terre en leurs abominations; du Chananéen, de l’Hettéen, du Phérézéen, du Jébuséen, de l’Ammonite, du Moabite, du Mosérite, de l’Amorrhéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Ils se sont mariés, eux et leurs fils, parmi ces peuples, et la semence sainte s’est détournée dans les nations de la terre, et la main des princes a été la première, en cette infraction à la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Or, quand j’ouïs ces paroles, je déchirai mes vêtements, je fus saisi de crainte; je m’arrachai les cheveux et la barbe, et je m’assis tout contristé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Et tous ceux qui suivaient la loi du Dieu d’Israël s’assemblèrent auprès de moi, à cause de cette infraction aux préceptes; et moi, toujours assis, je gardai un morne silence jusqu’au sacrifice du soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Et pendant le sacrifice du soir, je sortis de mon abattement; après avoir déchiré mes vêtements, saisi de crainte, je me mis à genoux, et j’étendis mes mains vers le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Et je dis Seigneur, je suis plein de honte et de confusion, ô mon Dieu, en levant mon front devant vous; car nos dérèglements se sont accumulés sur nos têtes, et nos péchés ont monté jusqu’au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Depuis les jours de nos pères jusqu’à ce jour, nous avons vécu dans le péché, et à cause de nos transgressions, nous, nos rois, nos fils, nous avons été livrés aux rois des nations, par le glaive, la captivité, le pillage, et nous avons eu la honte au front comme nous l’avons encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Maintenant, notre Dieu a été bienveillant pour nous jusqu’à nous sauver, nous rétablir en ce lieu où est son sanctuaire, nous éclaircir les yeux, et nous accorder un peu de vie dans notre esclavage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Car nous sommes esclaves; toutefois, en notre servitude, le Seigneur notre Dieu ne nous a pas abandonnés, et il nous a fait trouver miséricorde devant les rois de Perse, pour qu’ils nous accordassent un peu de vie, qu’ils relevassent le temple de notre Dieu, qu’ils le rétablissent en sa désolation, et qu’ils nous rendissent plus de sûreté en Juda et à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Que dirons-nous après cela, ô notre Dieu? Car nous avons abandonné vos commandements;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Que vous nous aviez donnés par vos serviteurs les prophètes, disant: La terre où vous allez pour qu’elle soit votre héritage est une terre troublée de fond en comble par les abominations des peuples qui l’habitent, et qui l’ont remplie d’un bout à l’autre de leurs im puretés. 12. Ne donnez donc pas vos filles à leurs fils, et ne prenez point pour vos fils leurs filles; ne cherchez jamais leur pain ni leur bien-être, afin que vous vous affermissiez, que vous mangiez les biens de cette terre, et que vous les transmettiez en héritage à vos fils pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Or, après tout ce qui nous est advenu à cause de nos mauvaises actions et de nos grands péchés, vous nous avez sauvés, parce qu’il n’est point de Dieu tel que vous, et que vous avez ôté nos iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Et nous avons recommencé à répudier vos commandements, à nous marier parmi ces peuples; ô Seigneur, ne soyez pas irrité contre nous jusqu’à nous anéantir, sans que nul parmi nous échappe et soit épargné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Seigneur Dieu d’Israël, vous êtes juste, car nous voilà sains et saufs en ce jour; voilà que nous sommes devant vous dans nos péchés, et après de tels excès on ne peut subsister devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Et comme Esdras príait, et comme, en pleurant et priant, il élevait la voix devant le temple du Seigneur, la nombreuse Église d’Israël se rassembla auprès de lui, hommes, femmes et jeunes gens; et le peuple pleura, et en pleurant il éleva la voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Et Sechénias, fils de Jehel, des fils d’Elam, prit la parole, et il dit à Esdras: Nous avons violé la loi de notre Dieu, et nous avons épousé parmi les peuples de la terre promise des femmes étrangères; et maintenant, après cela, Israël espère encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Faisons donc alliance avec notre Dieu; et, s’il le veut, chassons toutes ces femmes et ceux qui sont nés d’elles. Lève-toi, inspire-leur la crainte des commandements de notre Dieu, et qu’il soit fait selon la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Lève-toi, car l’affaire te regarde, et nous sommes avec toi; sois fort et agis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Et Esdras se leva, et il fit prêter serment aux chefs, aux prêtres, aux lévites, à tout Israël, d’exécuter ses ordres, et ils le jurèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Et Esdras se leva de devant le temple, et il alla au trésor gardé par Johanan, fils d’Elisub, et il y entra, et il ne mangea pas de pain, et il ne but point d’eau, car il pleurait sur l’infidélité des fils de l’exil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Et l’on fit dans Juda et à Jérusalem une proclamation qui disait: Tous les fils de l’exil se réuniront à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Quiconque ne viendra pas dans trois jours, selon l’ordre des princes et des prêtres, tous ses biens seront anathématisés, et lui-même sera expulsé de l’Église des fils de l’exil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Tous les hommes de Juda et de Benjamin se rendirent donc à Jérusalem. On était au neuvième mois; le vingtième jour du même mois, tout le peuple se tint sur la place du temple de Dieu, à cause du trouble né de cette affaire, et à cause d’une tempête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Et Esdras, le prêtre, se leva, et il leur dit: Vous avez violé l’alliance, et vous avez épousé des femmes étrangères, pour ajouter aux péchés d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Rendez maintenant gloire au Seigneur Dieu de vos pères, et faites ce qui est agréable à ses yeux; séparezvous des peuples de la terre promise, et des femmes des étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Et toute l’Église s’écria: Grande est pour nous cette parole de toi que nous devons accomplir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Mais le peuple est nombreux, le temps est à l’orage, et il n’est pas possible de se tenir dehors plus longtemps; d’ailleurs, ce n’est point l’œuvre d’un ou de deux jours, car, à ce sujet, nous avons multiplié nos fautes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Que nos chefs restent, et qu’ils aillent, au temps prescrit, en toutes les villes, pour tous ceux qui ont épousé des femmes étrangères; que dans chaque ville ils s’adjoignent les anciens et les juges, afin de détourner de nous la colère du Seigneur notre Dieu, au sujet de ce péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Or, il n’y eut avec moi que Jonathas, fils d’Azaël, et Jasias, fils de Thécoé, et ils eurent pour aides Mesollam, et Sabbathaï, le lévite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Et voici ce que firent les chefs de l’exil le prêtre Esdras et les chefs de familles paternelles furent désignés tous nominativement, et ils partirent le premier jour du dixième mois pour faire des enquêtes sur cette affaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Et, le premier jour du premier mois, ils eurent fini, et connurent tous les hommes qui avaient épousé des femmes étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Et parmi eux furent trouvés des fils de prêtres nés de Josué, fils de Josédec et ses frères, savoir: Maasia, et Eliézer, et Jarib, et Gadalie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Et ils s’engagèrent à répudier leurs femmes, et ils donnèrent chacun un bélier de son troupeau, pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Il y eut des fils d’Emmer: Anani et Zabdia;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Et des fils d’Eram: Masahel, Elia, Samaïa, Jehel el Ozias;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Et des fils de Phasur: Elionaï, Maasia, Ismaël, Nathanaël, Jozabad et Elasa;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Et des lévites: Jozabad, Samu, Colia (le même que Colite), Phetheïa, Judas et Eliézer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Et des chantres: Elisabadi; et des portiers, Solmen, Telmen et Oduth;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Et d’Israël, des fils de Phoros: Ramia, Azia, Melchia, Méamin, Eléazar, Asabie et Banaïa;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Et des fils d’Hélam: Matthanias, Zacharie et Jahiel, Abdias, Jarimoth et Elie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Et des fils de Zathuca: Elionaï, Elisub, Matthanaï, Armoth, Zabad et Oziza;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Et des fils de Bubeï Johanan, Ananie, Zabu et Thali;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Et des fils de Banuï: Mosollam, Maluch, Adaïas, Jasub, Saluïa et Remoth;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Et des fils de Phaath-Moab: Edné, Chalel, Banaïa, Maasia, Matthanias, Béséléel, Banuï et Manassé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Et des fils d’Eram: Eliézer, Jésia, Melchia, Samaïas, Séméon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Benjamin, Baluch, Samaria;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Et des fils d’Asem: Metthanie, Matthatha, Zadab, Eliphalet, Jerami, Manassé, Sémeï;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Et des fils de Bani: Moodia, Amram, Uhel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Banaïas, Badaïas, Helcias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Vania, Marimoth, Eliasiph,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Matthanias, Matthanaï; et ainsi firent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Les fils de Banui, et les fils de Sémeï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Et Sélémia, et Nathan, et Adaïa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'Machadnabu, Séseï, Sariu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 41, 'Ezriel, et Sélémia, et Samaria,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 42, 'Et Sellum, Amaria, Joseph;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 43, 'Des fils de Nabu: Jahel, Matthanias, Zabad, Zebennas, Jadaï, Johel et Banaïa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 44, 'Tels furent ceux qui avaient épousé des femmes étrangères, et qui en avaient eu des enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Récits de Néhémias, fils d’Helcias. Au mois de chaseleu, en la vingtième année, j’étais à Suse, résidence royale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Et Anani, l’un de mes frères, vint, lui et des hommes de Juda, et je les questionnai, tant sur ceux qui étaient demeurés de la captivité et vivaient encore, que sur Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Et ils me dirent: Ceux qui sont demeurés, et qui ont été laissés de la captivité, sont dans la terre promise en grande détresse et opprobre; les murs de Jérusalem ont été abattus, et ses portes brûlées par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Or, quand j’eus ouï de telles paroles, je m’assis et pleurai, et, pendant plusieurs jours, me lamentai, et j’étais jeûnant et priant devant le Dieu du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Et je dis Que cela ne soit, je vous prie, Seigneur Dieu du ciel, Dieu fort, grand et redoutable qui gardez votre alliance et votre miséricorde à ceux qui vous aiment et observent vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Que votre oreille soit attentive, que vos yeux s’ouvrent, afin d’ouïr l’oraison de votre serviteur que je fais maintenant devant vous, nuit et jour, pour vos serviteurs les enfants d’Israël; et je me confesse pour les péchés des enfants d’Israël, en lesquels nous avons péché contre vous. Moi et la maison de mon père avons péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Nous avons rompu l’alliance; nous n’avons point gardé les commandements, les jugements et les ordonnances que vous avez intimés à Moise, votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Souvenez-vous de la parole que vous avez intimée à Moïse, votre serviteur, disant: Si vous manquez à notre alliance, je vous disperserai parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Et si vous revenez à moi, si vous gardez mes commandements, si vous les pratiquez, quand vous seriez disséminés jusqu’aux lieux où la terre touche le ciel, je vous en ramènerai, je vous réunirai en la terre que j’ai choisie pour que mon nom y réside.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Et voici vos serviteurs et votre peuple que vous avez rachetés par votre toute-puissance et votre forte main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Qu’ils ne demeurent pas ainsi, Seigneur; mais que votre oreille soit attentive à l’oraison de votre serviteur et à celle de vos serviteurs qui veulent craindre votre nom. Soyez-lui propice aujourd’hui à votre serviteur; faites qu’il trouve miséricorde devant les hommes; or, j’étais échanson du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Et, au mois de nisan, en la vingtième année du règne d’Arthasastha, le vin était devant moi, et je pris le vin et le versai au roi, et il n’y avait là en sa présence nul autre que moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Et le roi me dit: D’où vient que ton visage est mauvais, et que tu ne te contiens pas? Cela ne serait point si le mal n’était en ton cœur. Et j’eus grande crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Et je dis au roi: Que le roi vive toujours; comment mon visage ne serait-il pas mauvais, puisque la ville qui est la maison des sépulcres de mes pères est déserte, et que ses portes ont été brûlées par le feu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Et le roi me dit: A quel sujet me demandes-tu cela?. Et je priai le Dieu du ciel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Et je répondis au roi: S’il semble bon au roi, si son serviteur trouve grâce devant lui, je demande qu’il envoie son serviteur en Juda, à la ville des sépulcres de mes pères, et je la réédifierai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Et le roi et sa concubine qui siégeait auprès de lui, me dirent Jusqu’à quand durera ton voyage? quand reviendras-tu? Et le roi le trouva bon, et il me laissa partir, et je lui donnai un terme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Et je dis au roi: Si le roi le trouve bon, qu’il me donne des lettres pour les gouverneurs au delà de l’Euphrate, afin qu’ils ne mettent point d’obstacle à mon arrivée en Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Et une lettre adressée à Asaph, le garde du jardin qui appartient au roi, afin qu’il me fournisse du bois pour réparer les portes et les murs de la ville, et la maison où je me logerai. Et, comme la bonne main du Seigneur était avec moi, le roi me donna les lettres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Et j’arrivai chez les gouverneurs au delà de l’Euphrate, et je leur remis les lettres du roi. Or, le roi m’avait fait accompagner par des chefs de l’armée et par de la cavalerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Et Sanaballat l’Aronite, et Tobias, le serviteur ammonite, l’ouïrent; et il était mauvais pour eux qu’un homme fût venu faire du bien aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Et j’entrai à Jérusalem, et j’y restai trois jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Et je me levai de nuit, moi et quelque petit nombre de gens, et je ne dis à personne ce que Dieu m’avait mis dans le cœur de faire pour Israël; et je n’avais point de bête avec moi, sinon la bête sur laquelle j’étais monté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Et je sortis par la porte de la Vallée, passant devant la fontaine des Figuiers, et allant à la porte du Fumier; et je marchais le cœur brisé, à cause des remparts de Jérusalem qu’ils avaient abattus, et des portes qu’ils avaient brûlées par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Et je passai devant la porte de la Fontaine, puis, devant la piscine du Roi; et il n’y avait point de place par où la bête que j’avais sous moi pût passer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Alors, je m’en allai montant, de nuit, le long du torrent, et j’avais le cœur brisé, à cause du mur, et je revins à la porte de la Vallée, et je rentrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Et les sentinelles ne surent ni où j’étais allé ni ce que je voulais faire; et, jusque-là, je n’en avais rien dit aux Juifs, ni aux prêtres, ni aux premiers du peuple, ni aux chefs, ni au reste de ceux qui faisaient les travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Et je leur dis: Vous voyez l’affliction où nous sommes Jérusalem est déserte, et ses portes ont été brûlées par le feu. Allons, relevons les remparts de la ville, et nous ne serons plus outragés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Et je leur dis que la bonne main de Dieu était avec moi, à en juger par les paroles que le roi m’avait dites, et j’ajoutai: Levons-nous, édifions. Et leurs mains furent fortifiées en cette bonne œuvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Et Sanaballat l’Aronite, et Tobias le serviteur ammonite, et l’Arabe Gésam, le surent, et ils nous raillèrent, et ils vinrent à nous, et ils dirent: Qu’est-ce que vous faites? Vous révoltez-vous contre le roi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Et je leur répliquai, et je leur dis: Le Dieu du ciel lui-même mènera notre œuvre à bien; et nous, ses serviteurs, nous sommes purs, et nous édifierons. Quant à vous, vous n’avez ni part, ni droit, ni mémorial en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Et Eliasub le grand prêtre se leva avec ses frères les prêtres, et ils édifièrent la porte Probatique; eux-mêmes la sanctifièrent, et ils mirent ses battants; ils sanctifièrent aussi la tour de cent coudées, et la tour d’Anamehel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Et, auprès d’eux, édifièrent des hommes de Jéricho, et des fils de Zacchur, fils d’Amari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Les fils d’Asana édifièrent la porte des Poissons; eux-mêmes la couvrirent et mirent ses battants, serrures et verrous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Et, auprès d’eux, édifièrent Ramoth, fils d’Urie, fils d’Accos, et Mosollam, fils de Barachias, fils de Mazebel; et, auprès de ceux-ci, Sadoc, fils de Baana.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Et, après ce dernier, se trouvaient des hommes de Thécoé; mais les nobles n’offrirent pas de ployer leur cou pour un tel service.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Joad, fils de Phasec, et Mesulam, fils de Basodias, édifièrent la porte Ancienne; eux-mêmes la couvrirent et mirent ses battants, serrures et verrous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Et, auprès d’eux, édifièrent Maltias le Gabaonite, et Evaron le Méronothite, et des hommes de Gabaon et de Maspha, jusqu’au trône du gouverneur en deçà du fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Et, auprès de ce lieu, édifia Oziel, fils d’Arachias l’orfèvre. Et, auprès, Ananias, fils de Roceïm, et les siens terminèrent Jérusalem jusqu’aux murs de la Grande rue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Et, auprès d’eux, édifia Raphaïe, fils de Sur, chef de la moitié de la banlieue de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Et, auprès de lui, Jedaïe, fils d’Eromaph, édifia en face sa maison; et, auprès de lui, Attuth, fils d’Asabanias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Et, auprès de ce dernier, Melchias, fils d’Héram, et Asub, fils de Phaat-Moab, édifièrent jusqu’à la tour des Fours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Et, auprès de là, édifièrent Sallum, fils d’Alloès, chef de la moitié de la banlieue de Jérusalem, lui et ses filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Anun et les habitants de Zano relevèrent la porte de la Vallée; ils l’édifièrent eux-mêmes, et mirent ses battants, serrures et verrous; et ils réparèrent mille coudées de muraille jusqu’à la porte du Fumier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Et Melchias, fils de Réchab, chef de la banlieue de Bethaccharim, lui et ses fils relevèrent la porte du Fumier, et ils la couvrirent, et ils mirent ses battants, serrures et verrous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Salomon, fils de Cholezé, chef du territoire de Maspha, édifia la porte de la Fontaine; il y travailla lui-même, la couvrit, et mit ses battants et verrous; il fit aussi le mur de la piscine où on lave les toisons lors de la tonte du roi, jusqu’aux degrés qui descendent de la ville de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 16, 'Après lui, Néhémias, fils d’Azabuch, chef de la moitié de la banlieue de Bethsur, édifia jusqu’au jardin du sépulcre de David, et jusqu’à la piscine artificielle, et jusqu’à la maison des hommes vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 17, 'Après lui, édifièrent les lévites, sous Rahum, fils de Bani; à côté de celui-ci, Asabie, chef de la moitié de la banlieue de Ceila, avec ses habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 18, 'Et, après lui, étaient leurs frères, sous Béneï, fils d’Enadad, chef de l’autre moitié de la même banlieue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 19, 'Et, à côté de ceux-ci, Azur, fils de Josué, chef de Masphaï, releva une part de la tour de la Montée, celle qui tenait à l’angle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 20, 'Après lui, Baruch, fils de Zabu, édifia une autre part, depuis l’angle jusqu’à la porte de la maison d’Eliasub le grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 21, 'Après lui, Meramoth, fils d’Urie, fils d’Accos, édifia une autre part, à partir de la porte de la maison d’Eliasub, jusqu’à l’extrémité de cette maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 22, 'Après lui, édifièrent les prêtres, les hommes d’Ecchechar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 23, 'Après lui, Benjamin et Asub édifièrent devant leur maison; ensuite, Azarias, fils de Maasia, fils d’Anania, le long de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 24, 'Après celui-ci, Bani, fils d’Adad, édifia une autre part, depuis la maison d’Azarias, jusqu’à l’angle et jusqu’au tournant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 25, 'Phalach, fils d’Euzaï, édifia vis-à-vis l’angle où la tour fait saillie sur le palais du roi, et domine la cour de la prison; et, après lui, Phadaia, fils de Pharos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 26, 'Et les Nathinéens se placèrent en Ophel, jusqu’au jardin de la porte des Eaux, du côté de l’orient, où une tour s’élève en saillie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 27, 'Ensuite, ceux de Thécoé édifièrent une autre part, vis-à-vis la grande tour qui fait saillie, jusqu’au mur d’Ophla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 28, 'Les prêtres édifièrent au-dessus de la porte des Cavaliers, chacun en face de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 29, 'Après ceux-là, Saddoc, fils d’Emmer, édifia en face de sa maison; et, après lui, Samaïa, fils de Sechénias, garde de la porte orientale du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 30, 'Après celui-ci, Ananias, fils de Séléníias, et Anom, sixième fils de Séleph, édifièrent; puis, Mesulam, fils de Barachias, édifia en face du trésor dont il était le gardien; puis, Méchias, fils de Saréphi, édifia jusqu’à la maison des Nathinéens, et les petits marchands vis-à-vis la porte de Maphecad jusqu’aux degrés du tournant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 31, 'Enfin, les forgerons et des détaillants édifièrent du côté de la porte Probatique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Or, lorsque Sanaballat apprit que nous relevions les remparts, il le trouva mauvais, s’en courrouça grandement, et se moqua fort des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Et il dit devant ses frères (c’est-à-dire devant l’armée samaritaine): Il est donc vrai que les Juifs réédifient leur ville? Est-ce qu’ils feront des sacrifices? Est-ce qu’ils le pourront? Vont-ils aujourd’hui restaurer ces pierres qui ont été brûlées, et dont on a fait un monceau de décombres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Et Tobias l’Ammonite s’approcha de lui, et il dit à la multitude: Est-ce qu’ils sacrifieront et mangeront en ce lieu? Est-ce qu’un renard en sautant ne renversera pas leur muraille de pierres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Écoutez, ô notre Dieu, car nous sommes un sujet de raillerie; faites retomber ces outrages sur leurs têtes, et qu’eux-mêmes soient un sujet de raillerie en la terre où nous avons été captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Ne couvrez pas leur iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Or, lorsque Sanaballat, et Tobias, et les Arabes et les Ammonites, apprirent que les murs de Jérusalem reprenaient leur forme, et que leurs brèches commençaient à se fermer, ils le trouvèrent fort mauvais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Et ils se réunirent tous ensemble pour marcher contre Jérusalem, et la faire disparaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Alors, nous priâmes notre Dieu, et nous mîmes, nuit et jour, des gardes, à cause d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Et Juda dit: La force des ennemis est brisée; mais le monceau de ruines est énorme, et nous ne pourrons bâtir les remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Et nos oppresseurs dirent: Ils ne sauront, ils ne verront que lorsque nous arriverons au milieu d’eux, et nous les massacrerons, et nous ferons cesser l’œuvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Et les Juifs qui habitaient dans le voisinage, vinrent, et nous dirent: Ils arrivent de toutes parts contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Alors, je plaçai tout le peuple en bas, au pied des remparts, sous des abris, par familles, avec leurs épées, leurs javelines et leurs arcs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Et je regardai, me levai, et dis aux nobles, aux capitaines, à tout le reste du peuple: Ne craignez point leur face; souvenez-vous de notre Dieu grand et redoutable; combattez pour vos frères, vos fils, vos filles, vos femmes et vos foyers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Et aussitôt que nos ennemis apprirent qu’ils nous avaient été signalés, Dieu dissipa leurs conseils, et nous retournâmes aux remparts, chacun à son ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Et, à partir de ce jour, la moitié de ceux que j’avais attirés fit l’œuvre; l’autre moitié se rangea derrière les remparts avec des javelines, des boucliers, des arcs et des cuirasses; leurs chefs se tenant derrière toute la maison de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Et derrière ceux qui bâtissaient; ceux qui transportaient les matériaux ne quittaient point leurs armes; d’une main ils faisaient leur tâche, de l’autre ils tenaient un trait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Et chaque travailleur avait autour des reins son épée, et ils édifiaient, et celui qui sonnait de la trompette était auprès d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 18, 'Et je dis aux nobles, aux capitaines et au reste du peuple L’œuvre est grande et de longue étendue, et nous sommes dispersés sur le rempart, chacun loin de son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 19, 'N’importe où vous entendrez la trompette, accourez tous en ce lieu, et notre Dieu combattra avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 20, 'Ainsi, nous continuâmes nos travaux; la moitié de nous ne quitta point ses javelines, depuis les premières lueurs du jour jusqu’au lever des étoiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 21, 'Et, en ce temps-là, je dis au peuple: Que chacun, avec son serviteur, demeure au milieu de Jérusalem; la nuit on veillera, le jour on se mettra au travail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 22, 'Et j’étais là, et les hommes de garde se tenaient derrière moi, et nul de nous n’ôtait ses vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Et il y eut un grand cri du peuple et de leurs femmes, contre les Juifs leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Et les uns disaient: Nous sommes en grand nombre avec nos fils et nos filles, vendons-en; puis nous achèterons du blé, et nous mangerons, et nous vivrons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Et d’autres disaient Engageons nos champs, nos vignes, nos maisons; puis, nous achèterons du blé, et nous mangerons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'D’autres encore disaient: Nous avons emprunté de l’argent pour les impôts du roi, sur nos champs, et nos vignes, et nos maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Et maintenant, notre chair est comme la chair de nos frères; nos fils sont comme leurs fils, et nous traitons nos fils et nos filles comme des esclaves; et il y a de nos filles qui sont servantes, et nous n’avons pas le pouvoir de les racheter; car les nobles possèdent nos champs et nos vignes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Et j’eus une grande affliction, quand j’ouïs leur clameur et ces discours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Et je tins conseil en mon cœur, et je combattis les nobles et les princes, et je leur dis: Un homme peut-il demander à son frère ce que vous demandez? Et je convoquai contre eux une grande assemblée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Et je leur dis: Nous avons, de nos dons volontaires, racheté nos frères les Juifs qui avaient été vendus aux gentils, et vous vendez vos frères; mais vous seront-ils livrés? Et ils gardèrent le silence, et ils ne trouvèrent pas un mot à dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Et je dis Elle n’est pas bonne l’action que vous faites; ce n’est pas ainsi que vous vous soustrairez, par la crainte de Dieu, aux outrages des nations, vos ennemies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Or, mes frères, mes parents et moi-même, nous leurs avons prêté de l’argent et du blé; eh bien! renonçons à rien exiger d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Rendez-leur dès aujourd’hui leurs champs, leurs vignes, leurs oliviers et leurs maisons; et apportez-leur du blé, du vin et de l’huile pour prix de l’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Et ils dirent: Nous rendrons tout; nous ne leur demanderons rien, et nous ferons ce que tu dis. Et j’appelai les prêtres, et je les adjurai de faire selon cette parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Et je secouai mon manteau, et je dis Que Dieu ainsi secoue hors de sa maison et de son jardin tout homme qui n’accomplira pas cette parole; que cet homme soit ainsi secoué et vide. Et toute l’Église dit: Amen. Et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Depuis le jour où le roi m’avait commandé d’être leur chef en la terre de Juda: de la vingtième à la trentedeuxième année du règne d’Arthasastha, pendant douze ans, ni moi ni mes frères nous ne mangeâmes de vivres extorqués d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 15, 'Et toutes les extorsions dont mes devanciers les grevaient avant moi, leur avaient enlevé jusqu’à leur dernier argent; ils leur prenaient pour le pain et le vin quarante sicles par jour; et leurs agents avaient toute autorité sur le peuple; et moi je ne fis pas ainsi, en face de la crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 16, 'Et, pendant la réédification des murailles, je ne leur extorquai rien, je n’achetai point de champ, non plus qu’aucun de ceux que j’avais rassemblés pour cette œuvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 17, 'Et les Juifs, au nombre de cent cinquante, et ceux des gentils qui venaient d’alentour auprès de nous, mangeaient à ma table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 18, 'Et tous les jours on m’amenait un bœuf, six brebis de choix et un chevreau. Et, tous les dix jours, il me venait pour nous tous une ample provision de vin; et, avec tout cela, je ne pris jamais de vivres par extorsion, parce que la servitude avait été pesante pour le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 19, 'Souvenez-vous de moi, mon Dieu, pour mon bien, à cause de tout ce que j’ai fait en faveur de ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Or, lorsque Sanaballat, Tobias, l’Arabe Gésam et le reste de nos ennemis, ouïrent que j’avais relevé le mur, ils en perdirent le souffle; cependant, alors, je n’avais pas encore mis les battants des portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Et Sanaballat et Gésam m’envoyèrent des messagers, disant Viens, et rencontrons-nous tous ensemble dans l’un des bourgs de la plaine d’Ono. Mais, ils pensaient à me faire du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Je leur envoyai des messagers, disant: Je suis à faire une grande œuvre, et je ne pourrai descendre vers vous, de peur qu’elle ne soit suspendue; je descendrai dès qu’elle sera finie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Ils me firent dire derechef ces paroles, et je leur répondis comme la première fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Et Sanaballat m’envoya son serviteur, avec une lettre ouverte qu’il tenait à la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Et il y était écrit: On a ouï dire, parmi les nations, que toi et les Juifs pensez à vous révolter; et que, pour cela, tu édifies le rempart, et que tu seras leur roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Et, outre cela, tu as aposté pour toi des prophètes, afin que tu sièges à Jérusalem, comme roi de Juda. Or, maintenant, ces choses vont être rapportées au roi; viens donc, et tenons conseil ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Et je lui envoyai encore des messagers, disant: Cela n’est pas arrivé selon les paroles que tu dis, car tu les as feintes en ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Ils voulaient tous ainsi nous effrayer, et ils disaient: Leurs mains en seront énervées; quant à ce travail, il ne sera pas achevé; mais moi, je fortifiai mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Et j’entrai en la demeure de Sémeï, fils de Dalaïa, fils de Métabéhel, et il y était enfermé, et il me dit: Réunissons-nous dans le temple de Dieu, et nous en clorons les portes; car cette nuit ils viendront pour te tuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Et je répondis: Quel est l’homme qui entrera dans le temple, et pourra vivre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Et j’observai, et voilà que Dieu ne me l’avait pas envoyé; car sa prophétie était une fable inventée contre moi. En effet, Sanaballat et Tobias avaient salarié');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Contre moi une multitude de gens, afin que j’eusse peur, que je fisse ce qu’il conseillait, que je tombasse dans le péché, que j’eusse parmi eux un mauvais renom, et qu’ils m’outrageassent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Souvenez-vous, ô mon Dieu, de Tobias et de Sanaballat, selon leurs actions, et de Noadias le prophète, et des autres prophètes qui tentèrent de m’alarmer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 15, 'Et le mur fut achevé en cinquante-deux jours, le vingt-cinq du mois d’élal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 16, 'Et il advint, quand nos ennemis l’ouïrent, que toutes les nations d’alentour furent épouvantées, et qu’une grande frayeur tomba sur eux, et qu’ils connurent que l’achèvement de cette œuvre était de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 17, 'Et, en ces jours-là, des lettres de plusieurs nobles de Juda arrivaient à Tobias, et celles de Tobias leur arrivaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 18, 'Car plusieurs en Juda s’étaient engagés avec lui par serment, parce qu’il était gendre de Sechénias, fils d’Héraé; et que Jonan, son fils, avait épousé la fille de Mesulam, fils de Barachias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 19, 'Et ils me rapportaient ses paroles, et ils lui répétaient les miennes, et Tobias écrivait des lettres pour m’effrayer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Or, après que le mur fut bâti, les battants des portes placés, les portiers, les chantres et les lévites abrités,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Je donnai des ordres à mon frère Ananias, et à Ananias, gouverneur du palais de Jérusalem; car celui-ci était un homme sincère, et craignant Dieu plus que beaucoup d’autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Et je leur dis: Que les portes de Jérusalem ne soient point ouvertes avant le lever du soleil, et que, pendant que tout le monde est encore éveillé, on les ferme et fes verrouille; instituez aussi des gardes parmi les habitants de Jérusalem, chacun à son poste, chacun dans le quartier où est sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Or, la ville était grande et vaste, et le peuple en elle était peu nombreux; et les maisons n’étaient pas réédifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Et Dieu me mit au cœur de réunir les nobles, les chefs et le peuple, pour le recensement, et je trouvai le livre du recensement des premiers arrivés, et j’y vis écrit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Voici les fils de la terre promise, délivrés de la captivité où les avait emmenés Nabuchodonosor, roi de Babylone; chacun d’eux est de retour en sa ville: à Jérusalem et en Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Avec Zorobabel, Josué, Néhémias, Azarias, Reelma, Naémani, Mardochée, Balsan, Maspharath, Esdras, Boguias, Inaum, Baana et Masphar; hommes du peuple d’Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Fils de Phoros: deux mille cent soixante-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Fils de Saphatia: trois cent soixante-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Fils d’Era: six cent cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 11, 'Fils de Phaath-Moab, avec les fils de Josué et de Joab: deux mille six cent dix-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 12, 'Fils d’Elam: douze cent cinquante-quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 13, 'Fils de Zathuïa: huit cent quarante-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 14, 'Fils de Zacchu sept cent soixante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 15, 'Fils de Banuï: six cent quarante-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 16, 'Fils de Bébi: six cent vingt-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 17, 'Fils d’Asgad: deux mille trois cent vingt-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 18, 'Fils d’Adonicam six cent soixante-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 19, 'Fils de Bagoï, deux mille soixante-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 20, 'Fils d’Edin: six cent cinquante-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 21, 'Fils d’Ater, issu d’Ezéchias: quatre-vingt-dix-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 22, 'Fils d’Esam: trois cent vingt-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 23, 'Fils de Béseï: trois cent vingt-quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 24, 'Fils d’Ariph: cent douze. Fils d’Asen: deux cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 25, 'Fils de Gabaon: quatre-vingt-quinze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 26, 'Fils de Béthalem: cent vingt-trois. Fils d’Atopha: cinquante-six.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 27, 'Fils d’Anathoth: cent vingt-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 28, 'Hommes de Béthasmoth: quarante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 29, 'Hommes de Cariatharim, Caphira et Beroth: sept cent quarante-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 30, 'Hommes d’Arama et de Gabaa: six cent vingt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 31, 'Hommes de Machemas: cent vingt-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 32, 'Hommes de Béthel et d’Haï cent vingt-trois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 33, 'Hommes de Nabia: cent cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 34, 'Hommes d’Elamaar: douze cent cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 35, 'Fils d’Eram: trois cent vingt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 36, 'Fils de Jéricho: trois cent quarante-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 37, 'Fils de Lodadid et d’Ono, sept cent vingt et un.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 38, 'Fils de Sanana: trois mille neuf cent trente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 39, 'Prêtres, fils de Joad, appartenant à la maison de Jésus: neuf cent soixante-treize.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 40, 'Fils d’Emmer: mille cinquante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 41, 'Fils de Phaseür: douze cent quarante-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 42, 'Fils d’Eram: mille dix-sept.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 43, 'Lévites, fils de Jésus, fils de Cadmiel, avec les fils d’Uduïa soixante-quatorze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 44, 'Chantres, fils d’Asaph: cent quarante-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 45, 'Portiers, fils de Salum, fils d’Ater, fils de Telmon, fils d’Acub, fils d’Atita, fils de Sabi: cent trente-huit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 46, 'Nathinéens: fils de Seha, fils d’Aspha, fils de Labaoth,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 47, 'Fils de Ciras, fils d’Asuïa, fils de Phadon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 48, 'Fils de Labana, fils d’Agaba, fils de Selmeï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 49, 'Fils d’Anan, fils de Gadel, fils de Gaar,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 50, 'Fils de Rahaïa, fils de Rasson, fils de Necoda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 51, 'Fils de Gézam, fils d’Ozi, fils de Phesé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 52, 'Fils de Bési, fils de Meïnon, fils de Nephosasi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 53, 'Fils de Bacbuc, fils d’Achipha, fils d’Arur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 54, 'Fils de Basaloth, fils de Mida, fils d’Adasan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 55, 'Fils de Barcué, fils de Sisarath, fils de Théma,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 56, 'Fils de Nisia, fils d’Atipha,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 57, 'Fils des serviteurs de Salomon, fils de Suteï, fils de Sapharat, fils de Phérida,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 58, 'Fils de Jelel, fils de Dorcon, fils de Gadahel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 59, 'Fils de Saphatias, fils d’Ettel, fils de Phacarath, fils de Sabaïm, fils d’Emim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 60, 'Total des Nathinéens et des fils des serviteurs de Salomon: trois cent quatre-vingt-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 61, 'Et voici ceux qui partirent de Thelméleth, Thélarésa, Charub, Eron, Jemer, et ils n’étaient point capables de déclarer leurs familles paternelles ni leur race; à savoir s’ils étaient nés d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 62, 'Fils de Dalaïa, fils de Tobias, fils de Necoda: six cent quarante-deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 63, 'Et, parmi les prêtres, les fils d’Ebia, les fils d’Acos, les fils de Berzelli qui portaient ce nom, parce qu’ils avaient épousé des filles issues de Berzelli le Galaadite,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 64, 'Cherchèrent leur inscription sur le rôle de ceux qui étaient revenus, et ils ne le trouvèrent pas, et ils furent rejetés du sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 65, 'Or, l’athersastha leur dit de ne point manger des choses les plus saintes jusqu’à ce que surgît un prêtre pour les éclairer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 66, 'Et toute l’Église montait à environ quarante-deux mille trois cent soixante âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 67, 'Sans compter leurs esclaves et leurs serviteurs, au nombre de sept mille trois cent trente-sept; et il y avait deux cents chantres et chanteuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 68, 'Deux mille sept cents ânes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 69, 'Et Néhémias reçut, d’une partie des chefs des familles paternelles, pour le trésor des travaux, mille sicles d’or, cinquante fioles et trente costumes sacerdotaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 70, 'Et une autre part des chefs des familles paternelles donna, pour le trésor des travaux, vingt mille pièces d’or et deux mille deux cents pièces d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 71, 'Et le reste du peuple donna vingt mille pièces d’or, deux mille deux cents mines d’argent et soixante-sept costumes sacerdotaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 72, 'Et les prêtres, et les lévites, et les portiers et les chantres, et ceux du peuple, et les Nathinéens, et tout Israël, s’établirent dans leurs villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 73, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Et le septième mois arriva, et les fils d’Israël étaient dans leurs villes; et tout le peuple se rassembla, comme un seul homme, sur la place, devant la porte de l’Eau; et ils dirent à Esdras le scribe d’apporter le livre de la loi de Moïse que le Seigneur a intimée à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Et le premier jour du septième mois, Esdras, le prêtre, apporta la loi devant la multitude d’hommes et de femmes, et devant tous ceux qui pouvaient l’entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Et il la lut depuis l’heure où le soleil éclaire jusqu’au milieu du jour, devant les hommes et les femmes, et ils la comprenaient, et les oreilles de tout le peuple étaient attentives au livre de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Et Esdras, le scribe, se tenait sur une estrade de bois, et il y avait auprès de lui, à sa droite: Matthathias, Samaïas, Ananias, Urie, Helcias et Maasia; à sa gauche: Phadaïas, Misahel, Melchias, Asom, Asubadma, Zacharie et Mesollam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Et Esdras ouvrit le livre à la vue de tout le peuple, car lui-même était plus élevé que le peuple, et lorsqu’il ouvrit le livre, tout le peuple resta debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Et Esdras bénit le Seigneur, le Dieu très-grand, et le peuple élevant les mains, répondit: Amen. Et ils s’inclinèrent, et ils adorèrent le Seigneur la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Ensuite, Josué, Banaïas et Sarabias, expliquèrent la loi au peuple, et le peuple ne bougea pas de sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Et ils lurent dans le livre de la loi de Dieu; puis, Esdras enseigna, et il apprit au peuple à connaître le Seigneur, et le peuple comprit à la lecture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Alors, Néhémias et Esdras, le scribe et prêtre, et les lévites qui expliquaient la loi au peuple, dirent à tout le peuple: Ce jour est consacré au Seigneur notre Dieu, ne vous affligez pas, ne pleurez point. Car tout le peuple pleurait quand il entendait les paroles de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Et Néhémias leur dit: Allez, mangez des chairs grasses, buvez de douces boissons, et envoyez des parts à ceux qui n’en ont point, car ce jour est consacré au Seigneur notre Dieu, et ne soyez point abattus, puisque le Seigneur est notre force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Et les lévites faisaient taire tout le peuple, disant: Gardez le silence, car ce jour est saint, et ne soyez point abattus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Et tout le peuple s’en alla pour manger, boire, envoyer des parts et faire grande liesse, parce qu’il avait compris les paroles que Néhémias leur avait fait connaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Et le second jour, les chefs de famille, tout le peuple, les prêtres et les lévites, se réunirent autour d’Esdras, le scribe, pour qu’il les instruisît sur toutes les paroles de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Et ils trouvèrent écrit en la loi que le Seigneur avait commandé à Moïse que les fils d’Israël demeurassent sous des tabernacles, durant la fête du septième mois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Et qu’ils le publiassent au son de la trompette en toutes leurs villes et à Jérusalem. Et Esdras dit: Allez sur la montagne, rapportez-en des rameaux d’olivier, de cyprès, de tamaris, de palmier et de tous les arbres touffus, pour faire des tabernacles selon ce qui est écrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Et le peuple sortit, et il rapporta des rameaux, et ils se firent des tabernacles, chacun sur sa terrasse, ou dans sa cour, ou dans les parvis du temple du Seigneur, ou dans les rues de la ville jusqu’à la porte d’Ephraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Et toute l’Église, tous ceux qui étaient revenus de la captivité se firent des tabernacles, et ils demeurèrent sous des tabernacles; et depuis le temps de Josué, fils de Nau, jusqu’à ce jour-là, le peuple d’Israël n’avait pas fait ainsi, et grande fut sa joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 18, 'Et on lut dans le livre de la loi, tous les jours, depuis le premier jusqu’au dernier, et ils firent la fête sept jours, et le huitième jour la fin de la fête, selon la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Au vingt-quatrième jour de ce mois, les fils d’Israël se réunirent pour un jeûne, ayant des cendres sur la tête, et des cilices autour du corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Et les fils d’Israël se tinrent séparés de tout fils de l’étranger, et debout, ils confessèrent leurs péchés et les iniquités de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Et, chacun demeurant immobile à sa place, ils lurent dans le livre de la loi du Seigneur leur Dieu; et ils étaient là, se confessant au Seigneur, adorant le Seigneur leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Ensuite, Josué, les fils de Cadmiel, Sechénias, fils de Sarabie, et les fils d’Honeni se levèrent sur les degrés des lévites, et invoquèrent à grands cris le Seigneur leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Et les lévites Josué et Cadmiel dirent: Relevez-vous, bénissez le Seigneur notre Dieu, dans tous les siècles des siècles; que l’on bénisse, ô Seigneur, votre nom et votre gloire; que l’on vous exalte en toute bénédiction et louange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Et Esdras dit: Vous êtes le seul Seigneur, vous avez créé le ciel et le ciel des cieux, et toute l’armée céleste, et la terre et tout ce qui est en elle, et les mers et tout ce qui est en elles; c’est vous qui vivifiez toutes choses, et c’est vous que les armées du ciel adorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Vous êtes le Seigneur Dieu, et vous avez élu Abram, et vous l’avez amené du pays des Chaldéens, et vous lui avez donné le nom d’Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Et vous avez trouvé son cœur fidèle devant vous, et vous avez fait alliance avec lui, pour donner la terre des Chananéens, des Hettéens, des Amorrhéens, des Phérézéens, des Jébuséens et des Gergéséens, à lui et à sa race: et vous avez tenu parole, parce que vous êtes juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Et vous avez regardé l’affliction de nos pères en Égypte, et vous avez ouï leurs cris sur les bords de la mer Rouge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Et vous avez donné des signes et des prodiges en Égypte, sur Pharaon, ses serviteurs, tout le peuple de sa terre, parce que vous saviez qu’ils traitaient votre peuple orgueilleusement, et vous vous êtes fait un grand nom, comme vous vous le faites encore aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Et, devant eux, vous avez séparé la mer, et votre peuple l’a traversée à sec, et, ceux qui le poursuivaient, vous les avez jetés dans l’abîme comme une pierre dans l’eau profonde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Et le jour, vous avez guidé votre peuple par une colonne de nuée, et la nuit par une colonne de feu, pour éclairer la voie qu’il devait suivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Et vous êtes descendu sur le mont Sina, et, du haut du ciel, vous leur avez parlé, et vous leur avez donné des jugements droits, des lois de vérité, des commandements et des préceptes salutaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Et vous leur avez fait connaître votre sabbat saint, et vous leur avez intimé par la voix de Moïse, votre serviteur, la loi, les préceptes et les commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Et pour aliment, vous leur avez donné du pain du ciel, et pour leur soif, vous avez fait jaillir de l’eau des rochers, et vous leur avez dit d’entrer, pour qu’elle soit leur héritage, en la terre sur laquelle vous aviez étendu la main, promettant de la leur donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Mais, eux et nos pères se sont enorgueillis, et ils ont endurci leur cœur, et ils n’ont point obéi à vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Et ils ont refusé de rien entendre, et ils n’ont pas eu mémoire de vos merveilles, que vous aviez faites pour eux; et ils ont endurci leur cœur, et ils ont songé à rentrer en la servitude d’Égypte. Et vous, ô mon Dieu, miséricordieux et compatissant, clément et magnanime, vous ne les avez pas abandonnés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Même lorsqu’ils eurent jeté en fonte un veau d’or, et qu’ils eurent dit: Voilà les dieux qui nous ont fait sortir de l’Égypte. Et ils vous ont gravement offensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Mais vous, dans votre miséricorde infinie, vous ne les avez point abandonnés dans le désert; vous n’avez point détourné d’eux la colonne de nuée qui les guidait le jour, ni la colonne de feu qui, la nuit, éclairait leur voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Et vous leur avez donné votre bon esprit pour les instruire; vous n’avez point retiré la manne de leur bouche, et vous leur avez donné de l’eau en leur soif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Et vous les avez nourris quarante ans dans le désert, sans les laisser manquer de rien, et leurs vêtements ne se sont point usés, et leurs pieds n’ont point été meurtris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Et vous leur avez donné des royaumes, vous leur avez partagé des peuples, et ils ont possédé la terre de Séhon, roi d’Esebon, et la terre d’Og, roi de Basan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Et vous avez multiplié leurs fils comme les étoiles du ciel, et vous les avez introduits en la terre que vous aviez promise à leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Et ils en ont fait leur héritage, et vous avez écrasé devant eux les habitants de la terre des Chañanéens, et vous avez livré à leur merci les rois et les peuples de cette terre, pour qu’ils les traitassent comme il leur plaisait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Ils ont donc pris des villes superbes, ils ont hérité de maisons pleines de biens, de citernes en pierres de taille, de vignes, d’oliviers, et d’une multitude d’arbres fruitiers. Et ils ont mangé, et ils se sont rassasiés, et ils se sont engraissés, et ils ont abondé en délices par votre grande bonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Ensuite, ils ont changé; ils se sont retirés de vous; ils ont rejeté derrière eux la loi; ils ont tué vos prophètes qui les admonestaient pour les ramener à vous. Et ils vous ont gravement offensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Alors, vous les avez livrés aux mains de ceux qui les opprimaient; ceux-ci les ont écrasés, et, au temps de leur affliction, ils ont crié à vous; et vous, du haut du ciel, vous les avez entendus; et, en votre grande miséricorde, vous leur avez envoyé des sauveurs, et vous les avez tirés des mains de ceux qui les opprimaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Mais, après s’être reposés, ils ont encore fait le mal devant vous, et vous les avez livrés aux mains de leurs ennemis qui les ont maîtrisés. Et, derechef, ils ont crié à vous; et du haut du ciel, vous les avez encore entendus; et, en votre grande miséricorde, vous les avez délivrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Et vous les avez admonestés pour qu’ils se convertissent à votre loi; mais ils ne nous ont point écouté, et ils ont péché contre vos commandements et vos jugements, par lesquels, en les faisant, l’homme vivra. Et ils ont tourné le dos, et ils ont endurci leur cœur, et ils ne vous ont pas écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Vous avez différé avec eux bien des années, et vous les avez admonestés par votre esprit, par la voix de vos prophètes, et ils ne vous ont point écouté; enfin, vous les avez livrés aux peuples de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Mais, en votre grande miséricorde, vous ne les avez point anéantis, vous ne les avez point abandonnés; car, vous êtes fort, et compatissant, et miséricordieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Et maintenant, ô notre Dieu, Dieu fort, grand, puissant et redoutable, qui gardez votre alliance et votre miséricorde, ne tenez pas pour peu de chose toutes les souffrances qui ont atteint nous, nos rois, nos princes, nos prêtres, nos prophètes, nos pères et tout le peuple, depuis les jours du roi d’Assyrie, jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 33, 'Vous avez été juste en tout ce qui nous est advenu, car vous avez agi selon la vérité, et nous, nous avons péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 34, 'Nos rois, nos princes, nos prêtres, nos pères, n’ont pas observé votre loi; ils n’ont pas été attentifs à vos commandements, ni à vos témoignages que vous leur avez notifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 35, 'Et ils ne vous ont point servi dans votre royaume, au milieu de ces marques de votre grande bonté que vous leur avez données, dans cette terre vaste et grasse que vous avez fait apparaître devant eux, et ils ne se sont point détournés de leurs habitudes criminelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 36, 'Et voilà qu’aujourd’hui nous sommes esclaves, en cette terre que vous avez donnée à nos pères, pour manger ses fruits et ses bonnes choses; voilà que nous sommes esclaves en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 37, 'Et ses fruits sont abondants pour les rois que vous avez mis sur nous en punition de nos péchés; ils ont pouvoir sur nos corps et sur nos troupeaux, à leur gré, et nous sommes dans une grande affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 38, 'Et, à cause de tout cela, nous vous promettons alliance et nous l’écrivons, et nos princes, et nos lévites, et nos prêtres y mettent leur sceau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Et à la tête de ceux qui la scellèrent furent Néhémias artasastha, fils d’Achalias, et Sédécias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Fils d’Araïas, et Azarias, et Jérémie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Phasur, Amarias, Melchias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 4, 'Attus, Sebani, Maluch,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 5, 'Iram, Meramoth, Abdia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 6, 'Daniel, Gannathon, Baruch,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 7, 'Mesulam, Abia, Miamin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 8, 'Maazia, Belgaï, Samaïa, tous ceux-là prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 9, 'Puis les lévites: Josué, fils d’Azanias, Banaïu, des');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 10, 'Et ses frères Sabanias, Oduïa, Calitan, Phélia, Anan,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 11, 'Micha, Roob, Asébias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 12, 'Zacchor, Sarabia, Sebania,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 13, 'Odum; les fils de Banuaï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 14, 'Chefs du peuple Zathuïa, fils de Bani,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 15, 'Asgad, Bébai, Pharos, Phaath-Moab, Elam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 16, 'Adania, Bagoï, Hédin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 17, 'Ater, Ezéchias, Azur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 18, 'Oduïa, Esam, Bési,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 19, 'Ariph, Anathoth, Nobaï,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 20, 'Megaphès, Mesollam, Hézir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 21, 'Mesozébel, Saduc, Jeddua,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 22, 'Phattia, Anan, Anaïa,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 23, 'Osée, Ananias, Asub,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 24, 'Aloès, Phalaï, Sobec,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 25, 'Reüm, Essabana, Maasia,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 26, 'Et Aia, Ainan, Enam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 27, 'Maluch, Héram, Baana.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 28, 'Et tout le reste du peuple, les prêtres, les lévites, les portiers, les chantres, les Nathinéens et tous ceux qui s’étaient retirés des gentils de la terre, pour revenir à la loi de Dieu, et leurs femmes et leurs filles; tous ceux qui avaient savoir et intelligence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 29, 'Furent pressants avec leurs frères, et les excitèrent par leurs malédictions; et ceux-ci s’engagèrent, par malédictions et serments, à marcher selon la loi que Dieu a donnée par la main de Moïse, serviteur de Dieu, à garder les jugements, les préceptes et les commandements du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 30, 'A ne point donner nos filles en mariage aux peuples de la terre, et à ne point prendre leurs filles pour nos fils. nous dit, aux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 31, 'Nous n’achèterons rien, avons peuples de la terre qui viendront vendre le jour du sabbat; nous ne trafiquerons, ni le jour du sabbat, ni les jours sanctifiés; nous remettrons les dettes la septième année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 32, 'Nous établirons une ordonnance afin de lever sur nous un tiers de drachme, par an, pour le service du temple de notre Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 33, 'Pour les pains de proposition, pour le sacrifice perpétuel, et pour l’holocauste perpétuel, tant des sabbats que des nouvelles lunes, pour les fêtes et les jours saints, pour les péchés, pour les hosties pacifiques et pour les travaux du temple de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 34, 'Nous avons ensuite jeté les sorts, entre les prêtres, les lévites et le peuple, par familles paternelles, pour régler l’oblation du bois dans le temple de notre Dieu, aux époques prescrites chaque année, pour faire les holocaustes sur l’autel du Seigneur notre Dieu, comme il est écrit en la loi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 35, 'Pour que nous apportions les prémices des champs, et des arbres à fruit d’année en année, dans le temple du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 36, 'Et l’évaluation des fils premiers-nés, celle des premiers-nés des bêtes de somme, entre les mains des prêtres et des lévites de service dans le temple de Dieu, comme il est écrit en la loi, et les premiers-nés de nos bœufs et de nos brebis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 37, 'Et pour que nous apportions aux prêtres, pour le trésor du temple de Dieu, les prémices de notre blé, des fruits de nos arbres, du vin et de l’huile; et aux lévites la dîme de notre terre, et pour que les lévites perçoivent la dîme en toutes les villes de la terre que nous cultivons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 38, 'Et nous avons dit: Le prêtre, fils d’Aaron, aura part avec le lévite à la dîme des lévites; et les lévites offriront le dixième de leur dîme dans le temple de notre Dieu, et dans le trésor du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 39, 'Car, les fils d’Israël et les fils de Lévi apporteront au trésor les prémices de leur blé, de leur vin, de leur huile; et c’est là que seront les vases saints, sous la garde des prêtres, des serviteurs du temple, des chantres et des portiers; et nous n’abandonnerons pas le temple de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 1, 'Et les princes du peuple s’établirent à Jérusalem; et parmi le reste du peuple, le sort désigna un homme sur dix pour résider en la ville sainte, les neuf autres dixièmes se dispersèrent dans les villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 2, 'Et le peuple bénit tous les hommes qui offrirent volontairement de rester à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 3, 'Voici les princes de la terre qui habitèrent, soit Jérusalem, soit les villes de Juda; chacun demeura en son héritage et en sa ville: Israël, prêtres, lévites, Nathinéens, fils des serviteurs de Salomon:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 4, 'A Jérusalem, il y eut des fils de Juda et des fils de Benjamin; fils de Juda: Athaïa, fils d’Azia, fils de Zacharie, fils de Samarie, fils de Saphatia, fils de Malalehel; fils de Pharès;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 5, 'Maasia, fils de Baruch, fils de Chaluza, fils d’Ozias, fils d’Adaïas, fils de Joarib, fils de Zacharie, fils de Seloni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 6, 'Tous les fils de Pharès qui s’établirent à Jérusalem, étaient au nombre de trois cent soixante-huit, c’étaient des hommes vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 7, 'Fils de Benjamin: Selo, fils de Mesulam, fils de Joad, fils de Phadaïa, fils de Coleïa, fils de Maasia, fils d’Echiel, fils de Jésia,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 8, 'Et après lui Gebé, Séli, et neuf cent vingt-huit hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 10, 'Et il y avait les prêtres Jadia, fils de Joarib, Jachin, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 11, 'Saraïa, fils d’Elcias, fils de Mesulam, fils de Saddoc, fils de Marioth, fils d’Aïtoth, prince de la maison de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 12, 'Et leurs frères faisant les œuvres du temple, étaient au nombre de huit cent vingt-deux. Et Adaïa, fils de Jéroam, fils de Phalalia, fils d’Amasi, fils de Zacharie, fils de Phassur, fils de Melchias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 13, 'Et ses frères chefs de familles paternelles, au nombre de deux cent quarante-deux. Et Amasias, fils d’Esdriel, fils de Mesarimith, fils d’Emmer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 14, 'Et ses frères, hommes vaillants, au nombre de cent vingt-huit; et ils avaient pour surveillant Badiel, fils de l’un des puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 15, 'Et il y avait les lévites: Samaïa, fils d’Esricam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 16, 'Matthanias, fils de Micha, et Jobeb, fils de Samuï, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 17, 'Deux cent quatre-vingt-quatre hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 18, 'Et il y avait les portiers: Acub, Telamin et leurs frères, cent soixante-douze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 19, 'Et le surveillant des lévites était le fils de Bani, fils d’Ozi, fils d’Asabia, fils de Micha. Et il y avait les chantres, fils d’Asaph, employés au service du temple de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 20, 'Selon le règlement que le roi David avait fait pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 21, 'Et Phathaïa, fils de Baseza, tenait lieu de la main du roi, pour toutes les affaires concernant le peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 22, 'Et pour les affaires des bourgs et des champs. Et il y eut des fils de Juda, à Cariath-Arboc,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 23, 'Et à Josué,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 24, 'Et à Bersabée, et dans ses faubourgs, dont faisaient partie');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 25, 'Lachis et ses champs; mais à Bersabée était la résidence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 26, 'Et des fils de Benjamin habitaient de Gabaa à Machmas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 27, 'Et quelques-uns des lévites avaient leurs parts en Juda et Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 1, 'Et voici les prêtres et les lévites qui étaient revenus avec Zorobabel, fils de Salathiel et Josué: Saraia, Jérémie, Esdras,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 2, 'Amarias, Maluch,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 3, 'Sechénias;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 4, '(7) Tels étaient les princes des prêtres, et leurs frères du temps de Josué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 5, '(8) Et les lévites étaient Josué, Banuï, Cadmiel, Sarabia, Joad, Matthanias (celui-ci dirigeait les chants, et leurs frères étaient désignés pour les services journaliers).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 6, '(9-10) Or, Josué engendra Joacim, et Joacim engendra Eliasib, et Eliasib engendra Joad,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 7, '(11) Et Joad engendra Jonathas, et Jonathas engendra Jadu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 8, '(12) Et du temps de Joacim, ses frères, les prêtres et les chefs des familles paternelles, étaient, savoir: De la famille de Saraïa, Amarias; de celle de Jérémie, Ananias;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 9, '(13) De celle d’Esdras, Mesulam; de celle d’Amarias, Johanan;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 10, '(14) De celle d’Amaluch, Jonathas; de celle de Sechénias, Joseph;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 11, '(15) De celle d’Aré, Mannas; de celle de Marioth, Elcaï;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 12, '(16) De celle d’Adadaï, Zacharie; de celle de Ganathoth, Mesolam;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 13, '(17) De celle d’Abias, Zéchri; de celle de Miamin, Maadaï; de celle de Phéléthi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 14, '(18) De la famille de Balgas, Samué; de celle de Semias, Jonathan;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 15, '(19) De celle de Joarib, Matthanaï; de celle d’Edio, Ozi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 16, '(20) De celle de Salaï, Callaï; de celle d’Amec, Abed;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 17, '(21) De celle d’Elcias, Asabias; de celle de Jedeïu, Nathanaël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 18, '(22) Les lévites du temps d’Eliasib étaient Joad, Joas, Johanan et Idua, inscrits comme chefs de familles, ainsi que les prêtres sous le règne de Darius le Pèrse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 19, '(23) Les fils de Lévi, chefs de familles paternelles, ont été inscrits dans le livre du récit de ces temps, jusqu’aux jours de Johanan, fils d’Elisué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 20, '(24) Et les chefs des lévites étaient Asabia, et Sarabia, et Josué, et les fils de Cadmiel et leurs frères, se tenaient devant eux lorsqu’ils chantaient les louanges du Seigneur, journellement comme l’avait prescrit David, homme de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 21, '(25) Je ressemblai aussi les portiers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 22, '(26) Du temps de Joacim, fils de Josué, fils de Josédec, et du temps de Néhémias, et alors Esdras était prêtre et scribe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 23, '(27) Et lorsque l’on fit la dédicace des murs de Jérusalem, on chercha les lévites en leurs résidences pour les amener à Jérusalem, et faire la fête de la dédicace et les réjouissances, avec des actions de grâces et des chants accompagnés de harpes et de cymbales,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 24, '(28) Et les fils des chantres vinrent de la banlieue de Jérusalem, et de ses villages,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 25, '(29) Et de ses campagnes, car ils s’étaient bâti des demeures autour de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 26, '(30) Et les prêtres et les lévites, après s’être purifiés, purifièrent le peuple, et les portiers, et les remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 27, '(31) Et l’on fit monter les princes de Juda sur le rempart avec deux chœurs, pour chanter des actions de grâces à Dieu, et ils tournèrent sur le rempart à droite se dirigeant vers la porte du Fumier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 28, '(32) Et derrière les chantres marchaient Osaïas et la moitié des princes de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 29, '(33) Et Azarias, Esdras, Mesollam, Juda, Benjamin, Samaïas et Jérémie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 30, '(34) Et des fils des prêtres avec les trompettes: Zacharie, fils de Jonathas, fils de Samaïas, fils de Matthanias, fils de Michée, fils de Zacchur, fils d’Asaph,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 31, '(35) Et ses frères Samaïas, Oziel et Gelod, Jama, Aïas, Nathanaël, Juda et Anani, et ils chantaient les cantiques de David, homme de Dieu; et Esdras, le scribe, les avait devancés sur la porte pour chanter devant eux les louanges du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 32, '(36) Et ils montèrent par les degrés de la ville de David sur le mur, au-dessus du palais de ce roi, et ils allèrent jusqu’à la porte des Eaux d’Ephraïm; de là, ils passèrent à la porte des Poissons, puis à la tour d’Anamehel, et enfin à la porte Probatique. Et la voix des chantres retentissait, et ils attiraient tous les regards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 33, '(42) Et ce jour-là, on immola de nombreuses victimes et la joie était grande, car Dieu les avait grandement réjouis, et leurs femmes et leurs enfants prenaient part à ces réjouissances, et les cris joyeux de Jérusalem s’entendaient au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 34, '(43) Et ce jour-là, on institua des gardiens des trésors, des prémices et des dîmes, et des hommes pour les recueillir dans les villes, et on les choisit parmi les prêtres et les lévites; car Juda se réjouissait d’avoir vu les lévites et les prêtres reprendre leurs fonctions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 35, '(44) Et l’on remit en vigueur les règlements de David et de Salomon, son fils, concernant les purifications, ainsi que les chantres et les portiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 36, '(45) Car, du temps de David, Asaph était à la tête des chantres, et de ceux qui célébraient le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 37, '(46) Et du temps de Zorobabel et de Néhémias, tout le peuple d’Israël assigna des parts aux chantres et aux portiers; on les leur distribuait chaque jour. On donnait aussi aux lévites ce qui leur était dû de la chair des sacrifices, et les lévites donnaient aux fils d’Aaron la part qui leur en revenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 1, 'En ce jour-là, on lut à haute voix au peuple le livre de Moïse, et on y trouva écrit: Que les Ammonites et les Moabites ne devaient jamais entrer dans l’Église de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 2, 'Parce qu’ils n’étaient point venus au-devant d’Israël avec du pain et de l’eau, et qu’ils avaient salarié Balaam pour le maudire; mais, notre Dieu changea la malédiction en bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 3, 'Et lorsqu’ils eurent oui la loi, tous ceux qui s’étaient mêlés à Israël en furent séparés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 4, 'Or, avant cela, Eliasib, le prêtre, très-proche allié de Tobias, demeurait dans le trésor du temple de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 5, 'Et il s’était fait faire un vaste magasin dans le lieu où l’on déposait jadis les offrandes, l’encens, les vases, la dîme du blé, du vin et de l’huile, ce qui était dû aux lévites, aux chantres et aux portiers, et les prémices destinées aux prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 6, 'Et, en ce temps-là, je n’étais pas à Jérusalem. Car, dans la trente-deuxième année du règne d’Arthasastha, roi de Babylone, j’étais allé auprès du roi. Et, un certain nombre de jours étant accompli, je demandai au roi la permission de partir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 7, 'Et je revins à Jérusalem, et je reconnus le mal qu’avait fait Eliasib avec Tobias en lui faisant un magasin dans le parvis du temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 8, 'Et cela me parut très-mal; et je jetai hors du magasin tous les meubles de la maison de Tobias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 9, 'Et je parlai, et on purifia le magasin, et j’y fis replacer les vases du temple, les offrandes et l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 10, 'Et je reconnus qu’on n’avait plus donné la part des lévites, de sorte que les lévites et les chantres faisant œuvre au temple s’étaient enfuis chacun en sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 11, 'Et je fis des reproches aux officiers, et je leur dis: D’où vient que le temple du Seigneur est abandonné? Puis, je rassemblai les lévites et les chantres, et je les rétablis dans leurs fonctions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 12, 'Alors, tout Juda apporta dans les trésors la dîme du froment, de l’huile et du vin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 13, 'Entre les mains de Sélémias le prêtre, de Sadoc le scribe, et de Phadaïa, l’un des lévites. Et ils avaient auprès d’eux Anan, fils de Zacchur, fils de Matthanias; car ils étaient réputés fidèles, et ils furent chargés de faire les distributions à leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 14, 'Souvenez-vous de moi, ô mon Dieu, à cause de cela; que mes bonnes œuvres dans le temple du Seigneur Dieu ne soient point effacées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 15, 'En ces jours-là, je vis que dans Juda quelques-uns pressuraient le vin le jour du sabbat; je vis que d’autres transportaient des gerbes, que d’autres encore chargeaient leurs ânes de vin, de grappes, de figues, de toutes sortes de fardeaux, et qu’ils les conduisaient à Jérusalem le jour du sabbat. Et je les avertis des jours où ils pouvaient trafiquer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 16, 'Et des gens s’étaient établis à Jérusalem, apportant du poisson, vendant toutes sortes de marchandises aux Juifs, le jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 17, 'Et je réprimandai les fils de Juda de condition libre, et je leur dis: Quelle est cette mauvaise action que vous faites, en profanant le jour du sabbat?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 18, 'N’est-ce point là ce que faisaient vos pères? n’estce point la cause de tous les malheurs dont notre Dieu les a frappés, eux et notre ville? Et vous, n’attirerez-vous pas un surcroît de colère sur Israël en profanant le sabbat?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 19, 'Or, quand les portes de Jérusalem furent rétablies, la veille d’un sabbat, je parlai, et on ferma les portes; je parlai, et on ne les ouvrit qu’après le sabbat, et je mis de mes serviteurs à chaque porte pour qu’on ne pût introduire des fardeaux le jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 20, 'Et tous les marchands passèrent la nuit en plein air, et ils vendirent une ou deux fois hors de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 21, 'Et je les avertis, et je leur dis: Pourquoi passezvous la nuit devant les remparts? Si vous recommencez, j’étendrai la main sur vous. Depuis lors, ils ne vinrent plus le jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 22, 'Et je dis aux lévites qui s’étaient purifiés, et qui étaient venus garder les portes, de sanctifier le jour du sabbat: à cause de cela, souvenez-vous de moi, mon Dieu, et épargnez-moi, selon la plénitude de votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 23, 'Or, en ces jours-là, je vis que des Juifs avaient épousé des femmes d’Azot, et des Ammonites et des Moabites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 24, 'Et leurs fils parlaient à demi la langue d’Azot, et ils ne savaient point parler juif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 25, 'Et je les réprimandai, et je les maudis, et j’en frappai quelques-uns, et je leur rasai la tête, et je leur fis jurer devant Dieu de ne point donner leurs filles aux fils des étrangers, et de ne point faire épouser par leurs fils des filles étrangères, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 26, 'N’est-ce pas là le péché de Salomon, roi d’Israël? Il n’y avait point son pareil parmi les rois des nations: il aimait Dieu, Dieu lui avait donné le royaume entier d’Israël, et les femmes étrangères le pervertirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 27, 'Que nous n’apprenions plus que vous faites ce péché; que vous violez l’alliance avec notre Dieu; que vous épousez des femmes étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 28, 'Or, l’un des fils de Joad, le grand prêtre Elisab, était gendre de Sanaballat l’Horonite; je le chassai loin de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 29, 'Souvenez-vous d’eux, ô Seigneur, à cause de la violation du sacerdoce, et de votre alliance, touchant les prêtres et les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 30, 'Et je les purifiai de leur contact avec des étrangères, et je réglai les services journaliers des prêtres et des lévites,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 31, 'Et l’offrande du bois des holocaustes au temps prescrit, lorsque l’on taille la vigne. Souvenez-vous de moi, ô mon Dieu, dans votre mansuétude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Or, après ces choses, il advint durant les jours d’Artaxerxès, qui régnait depuis l’Inde sur cent vingt-sept contrées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'En ces jours-là, tandis qu’il trônait en la ville de Suse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'La troisième année de son règne, il advint qu’il fit un festin à ses amis et au reste des nations, et aux hommes considérables des Perses et des Mèdes, et aux premiers des satrapes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Et ensuite, après leur avoir montré les richesses de son royaume, et la splendeur de ses joies et de ses trésors, pendant cent quatre-vingts jours,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Lorsque les jours de ses noces furent remplis, il fit pendant six jours aux nations qui se trouvaient à Suse un festin dans le parvis du palais,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Orné de voiles du lin le plus fin, et de gaze tendue par des cordons de lin et de pourpre sur des socles d’or et d’argent, et sur des colonnes de marbre blanc et de pierre. Les lits, d’argent et d’or, étaient posés sur des mosaïques d’émeraudes, de nacre et de marbre blanc; et les couvertures transparentes, diversement brodées, étaient encadrées de feuilles de roses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Les coupes étaient d’argent et d’or, et il y avait une petite coupe en diamant évaluée trente mille talents; on les remplissait de vin abondant et doux, le même que le roi buvait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Et le repas ne se fit pas selon la loi établie; le roi l’avait ainsi voulu, et il avait ordonné à ses économes de se conformer à ses propres désirs et à ceux de ses convives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Et Vasthi, la reine, fit un festin pour les femmes dans l’intérieur du palais où résidait le roi Artaxerxès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Le septième jour, le roi, étant en belle humeur, dit à Aman, à Bazan, à Tharra, à Barazi, à Zatholtha, à Abataza et à Tharaba, les sept eunuques attachés à sa personne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'De lui amener la reine pour qu’il la couronnât, qu’il posât sur sa tête le diadème, et qu’il la montrât dans sa beauté aux chefs et aux nations; car elle était belle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Mais la reine Vasthi refusa de suivre les eunuques, et le roi en fut affligé, et il se mit en colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Et il dit à ses amis: Voici ce qu’a dit la reine, faites donc à ce sujet loi et jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Et Arcesée, Sarsathée et Maliséar, princes des Perses et des Mèdes, ceux qui se tenaient près du roi, et qui s’asseyaient les premiers après lui, s’approchèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Et ils lui firent connaître ce que selon la loi il était à propos de faire à la reine Vasthi, parce qu’elle n’avait point fait ce que lui avait commandé le roi par ses eunuques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Et Muchée dit au roi et aux princes: Vasthi, la reine, n’a pas nui au roi seul, mais aussi à tous les princes et aux grands officiers du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Et il leur dit les paroles de la reine, et comme elle avait contredit le roi, et continuant: De même, ajouta-t-il, qu’elle a contredit le roi Artaxerxès,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Les autres femmes des Perses et des Mèdes du premier rang, apprenant ce qu’elle a dit au roi, oseront à l’avenir ne point honorer leurs époux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Si donc le roi le juge à propos, qu’il rende un édit, qu’il l’écrive selon la loi des Perses et des Mèdes, que l’on ne puisse y déroger; qu’il défende à la reine de s’approcher désormais de sa personne, et que le roi donne le diadème royal à une femme meilleure qu’elle;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Et que l’édit qu’aura rendu le roi soit publié en tout son royaume. Alors, toutes les femmes mettront leurs soins à honorer leurs époux, depuis l’indigent jusqu’au riche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Or, ce conseil plut au roi et aux princes, et le roi fit comme avait dit Muchée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Et il envoya dans toutes les provinces de son royaume l’édit traduit en leurs diverses langues, afin qu’en toute demeure on eût crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Après ces choses, la colère du roi à la longue s’assoupit; mais il ne rechercha plus la reine, se souvenant de ce qu’elle avait dit, et du jugement qu’il avait rendu contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Et les serviteurs du roi dirent: Que l’on cherche pour le roi des jeunes filles chastes et belles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Que le roi donne ses ordres aux comarques de toutes les provinces de son royaume; qu’ils choisissent des jeunes filles vierges et belles pour le gynécée de la ville de Suse; qu’on les mette entre les mains de l’eunuque du roi gardien des femmes; et qu’on leur donne là des cosmétiques et toutes sortes de soins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Puis, la femme qui plaira au roi sera reine à la place de Vasthi. Ce projet fut agréable au roi, et il fit ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Or, il y avait en la ville de Suse un Juif qui se nommait Mardochée, fils de Jaïr, fils de Sémeï, fils de Cisée, de la tribu de Benjamin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Qui avait été fait captif à Jérusalem, parmi ceux qu’avait emmenés Nabuchodonosor, roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Il avait élevé une enfant, fille d’Aminadab, son oncle paternel, et elle se nommait Esther, et, ses parents étant morts, il l’avait élevée pour qu’elle fût sa femme, et la jeune fille était belle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Or, lorsque l’édit du roi fut publié, beaucoup de jeunes filles furent réunies à Suse entre les mains de l’eunuque Haï. Esther fut aussi conduite chez Haï, gardien des femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Et la jeune fille lui plut et elle trouva grâce à ses yeux, et il se hâta de lui donner des cosmétiques et sa part, et sept jeunes filles du palais pour la servir; il en usa bien avec elle et avec ses suivantes, dans le gynécée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Et Esther ne fit connaître ni ses parents ni sa patrie, car Mardochée lui avait défendu d’en rien déclarer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Et chaque jour Mardochée se promenait dans le parvis du gynécée, observant ce qui pouvait arriver à Esther.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Or, le moment où une jeune fille entre chez le roi, arrive quand les douze mois sont accomplis, car alors les jours de la purification sont écoulés; pendant six mois, elle s’est ointe d’huile de myrrhe, et pendant six mois d’aromates et de cosmétiques de femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Enfin, on l’introduit chez le roi, et l’eunuque à qui il en donne l’ordre la conduit, pour qu’elle aille auprès de lui, du gynécée aux chambres du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 14, 'Elle y entre le soir, et, le lendemain, elle retourne au second gynécée où est l’eunuque Haï, gardien des femmes, et on ne la reconduit plus chez le roi, à moins qu’il ne la demande par son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 15, 'Et quand fut accompli le temps après lequel Esther, fille d’Aminadab, oncle paternel de Mardochée, devait être présentée au roi, elle ne négligea rien de ce que lui prescrivit l’eunuque, gardien des femmes. Car il était donné à Esther de trouver grâce aux yeux de tous ceux qui la voyaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 16, 'Elle entra donc chez le roi Artaxerxès, le douzième mois qui est adar, la septième année de son règne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 17, 'Et le roi aima Esther, et elle trouva grâce à ses yeux plus que toutes les autres vierges, et il lui mit le diadème de reine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 18, 'Et le roi fit un festin à tous ses amis et à tous ses grands, et la fête dura sept jours, et il célébra magnifiquement le mariage d’Esther, et il fit remise de ce qui lui était dû par les sujets de son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 19, 'Et Mardochée servait dans le parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 20, 'Et Esther ne déclara point quelle était sa patrie; car Mardochée le lui avait défendu, lui prescrivant de craindre Dieu et de suivre ses commandements, comme lorsqu’elle demeurait en sa maison; et Esther ne changea rien à ses habitudes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 21, 'Et les deux eunuques, chefs des gardes du corps du roi, s’affligèrent des honneurs auxquels s’élevait Mardochée, et ils cherchèrent à tuer Artaxerxès');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 22, 'Et Mardochée découvrit le complot, et il le dit à Esther, qui dévoila tout au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 23, 'Or, le roi interrogea les eunuques et il les fit pendre; et il prescrivit d’écrire en un mémorial, dans les archives de la bibliothèque royale, une notice sur les bons offices de Mardochée, à sa louange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Et, après cela, le roi Artaxerxès glorifia Aman, fils d’Amadathe le Bugéen, et il l’exalta, et il le fit asseoir sur un siège au-dessus de tous ses amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Et tous ceux qui servaient dans le parvis l’adoraient, car ainsi l’avait ordonné le roi; et Mardochée ne se prosternait pas devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Et les serviteurs du parvis dirent à Mardochée: Mardochée, pourquoi désobéis-tu à ce qu’a dit le roi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Chaque jour ils lui parlaient ainsi, et il ne les écoutait pas; enfin, ils informèrent Aman que Mardochée résistait aux ordres du roi; or, Mardochée leur avait déclaré qu’il était Juif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Et Aman, en apprenant que Mardochée ne se prosternait pas devant lui, fut fort courroucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Et il résolut d’effacer tous les Juifs du royaume d’Artaxerxès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Et, en la douzième année du règne d’Artaxerxès, il prépara un édit, et il agita les sorts pour savoir le mois et le jour où il exterminerait en même temps la race de Mardochée, et le sort tomba sur le quatorzième du mois qui est appelé adar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Et il parla au roi disant: Il y a un peuple épars en toutes les provinces de ton royaume; leurs lois diffèrent de toutes les autres lois; ils n’obéissent point à celles du roi; il n’est pas à propos que le roi les laisse subsister.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'S’il plaît au roi, qu’il décrète qu’on les détruise, et moi je ferai rentrer au trésor royal dix mille talents d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Et le roi ôtant son anneau le remit à Aman pour sceller l’édit contre les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Et le roi lui dit: L’argent sera pour toi, fais de ce peuple ce qu’il te plaît.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Et, le treize du premier mois, les scribes du roi furent convoqués, et ils écrivirent, selon l’ordre d’Aman, aux généraux et aux gouverneurs des cent vingt-sept provinces de l’Inde à l’Éthiopie, et aux chefs des nations chacun en sa langue, de la part du roi Artaxerxès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Et des courriers portèrent dans tout le royaume le commandement de détruire en un seul jour, le premier du douzième mois, qui est adar, toute la race des Juifs, et de piller leurs biens. Or, voici la copie de la lettre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Et les copies de ces lettres furent publiées en chaque province, et il fut enjoint à chaque nation de se tenir prête pour le jour indiqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'On y avait mis de l’empressement à Suse, et le roi et Aman buvaient à pleines coupes; mais la ville était toute troublée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Or, Mardochée, instruit de ce qu’on avait fait, déchira ses vêtements, se ceignit d’un cilice et se couvrit de cendre; puis, s’élançant par les rues de la ville, il cria à haute voix: Un peuple innocent périt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Et il arriva devant la porte du roi, et il s’y tint debout; car il ne lui était pas permis d’entrer dans la cour, ayant un cilice et de la cendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Et en toute province, où l’édit avait été publié, les Juifs s’étaient couverts de cilices et de cendres, et l’on n’entendait que des cris, des gémissements et des pleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Et les servantes et les eunuques de la reine entrèrent, et lui dirent ce qui était advenu, et elle en fut troublée, et elle envoya prier Mardochée de se vêtir d’une robe et d’ôter son cilice, et il n’obéit pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Et Esther appela Achrathée, son eunuque, qui se tenait auprès d’elle, et elle l’envoya demander à Mardochée la vérité exacte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Et Mardochée lui fit connaître tout ce qui s’était passé, et la promesse qu’Aman avait faite au roi de verser au trésor dix mille talents d’argent, afin qu’il exterminât les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Et il lui donna, pour le montrer à Esther, l’édit affiché dans Suse sur ce massacre, et il lui dit: Recommande à la reine d’entrer chez le roi, pour l’implorer et le supplier en faveur du peuple, dis-lui: Souviens-toi de ton humble état, quand je te nourrissais de ma main. Pourquoi Aman, le second après le roi, a-t-il parlé contre nous afin que nous périssions? Invoque le Seigneur; parle au roi pour nous sauver de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Or, Achrathée, étant rentré, répéta toutes ces paroles à la reine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Et Esther lui répondit: Va retrouver Mardochée, et dis-lui:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Toutes les nations de l’empire savent que n’importe quel homme ou femme qui entre auprès du roi, dans l’intérieur du palais, sans y être appelé, n’a pas de salut à espérer; sauf celui sur qui le roi étend sa verge d’or; celui-là est sauvé. Et moi, voilà trente jours que je n’ai été appelée pour entrer chez le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Et Achrathée rapporta toutes les paroles d’Esther à Mardochée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Et Mardochée lui répondit: Rentre, et dis — lui: Esther, ne te dis pas à toi-même que dans tout le royaume, toi seule échapperais plutôt que tous les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Si en ce moment tu me désobéis, le secours et la protection viendront d’ailleurs aux Juifs, et toi, et la maison de ton père, vous périrez. Et qui sait si ce n’est pas à cette occasion que tu règnes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Et Esther renvoya à Mardochée l’homme qui était venu près d’elle, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Éloigne-toi, rassemble tous les Juifs qui sont à Suse, jeûnez pour moi; passez trois jours et trois nuits sans manger ni boire, et moi et mes suivantes, nous ne prendrons aucun aliment; alors j’entrerai chez le roi, contre la loi, dussé-je mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Et Mardochée, s’étant éloigné, fit ce que lui avait prescrit Esther; et il pria le Seigneur, se souvenant de toutes les œuvres de Dieu, et il dit: Seigneur, Seigneur, Roi de tous les rois; il n’est rien qui ne soit en votre puissance, et nul ne vous contredira si votre volonté est de sauver Israël. Vous avez créé le ciel et la terre et toutes les merveilles qui sont sous les cieux, vous êtes le Seigneur de toutes choses, et nul ne peut s’opposer au Seigneur. Rien ne vous est caché; vous savez, Seigneur, que ce n’est point par insolence, que ce n’est point par orgueil, que ce n’est point par vaine gloire, que j’ai refusé d’adorer le superbe Aman; car, pour le salut d’Israël, je lui eusse avec joie baisé la plante des pieds. Mais, je ne l’ai point adoré, de peur de mettre la gloire d’un homme au-dessus de la gloire de Dieu, et je n’adorerai personne hormis vous, mon Seigneur, et je ne ferai point de telles choses par orgueil. Et maintenant, Seigneur Dieu et Roi, Dieu d’Abraham, épargnez votre peuple, car ils nous regardent pour nous perdre, et dès l’origine ils ont désiré détruire votre héritage. Ne méprisez point votre peuple particulier que vous avez délivré de la terre d’Égypte; exaucez ma prière, soyez propice à ceux que vous vous êtes réservés en partage; changez notre deuil en fêtes, afin que vivants nous chantions votre nom, ô Seigneur; ne fermez pas la bouche de ceux qui vous louent, ô Seigneur. Et tout Israël jeta des cris de toute sa force, car ils avaient la mort devant les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Et le troisième jour, lorsqu’elle eut fini de prier, elle dépouilla les habits de la servitude et se revêtit de sa gloire, et redevenue éclatante, après avoir invoqué le Dieu qui voit toutes choses et qui sauve, elle prit avec elle deux servantes; sur l’une elle s’appuya comme une femme délicate; l’autre la suivit allégeant le poids de son manteau; et elle-même s’avança rougissant en la fraîcheur de sa beauté, le visage riant, plein de bienveillance, tandis que son cœur était oppressé par la crainte. Ayant franchi toutes les portes, elle s’arrêta devant le roi. Or, il était assis sur son trône royal, et il s’était revêtu de toute sa magnificence, et il était couvert d’or et de pierres précieuses, et il était terrible. Et quand il leva son front rayonnant de majesté, un éclair de fureur brilla dans son regard. Et la reine tomba, et son teint se changea en une mortelle pâleur, et elle se pencha sur la tête de la servante qui la précédait. Et Dieu adoucit l’esprit du roi; et saisi d’angoisse, Artaxerxès s’élança de son trône, et il la prit dans ses bras jusqu’à ce qu’elle revînt, et il la consola par des paroles caressantes, et il lui dit: Esther! qu’y a-t-il, je suis ton frère, rassure-toi, tu ne mourras point; mais notre loi est pour tous; approche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Et ayant levé sa verge d’or, il la posa sur son cou et il l’embrassa, et il lui dit: Parle-moi, et elle répondit: Je t’ai vu, seigneur, comme l’ange de Dieu, et mon cœur a été troublé par la crainte de ta gloire, car tu frappes d’admiration, ô seigneur, et ton visage est l’arbitre des grâces. Pendant qu’elle parlait, elle s’évanouit encore, et le roi fut troublé, et tous ses serviteurs la consolèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Et le roi dit: Que veux-tu, Esther? quelle est ta demande? Serait-ce la moitié de mon royaume, elle sera à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Et Esther dit: Ce jour est pour moi un jour de fête, s’il plaît au roi, qu’il vienne avec Aman à un festin que je fais aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Et le roi dit: Que l’on se hâte d’avertir Aman, afin que nous fassions selon la parole d’Esther. Et tous les deux assistèrent au festin qu’avait dit la reine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Et, pendant le repas, le roi lui dit: Qu’y a-t-il, reine Esther? Ce que tu demandes sera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Et elle répondit: Ma requête et ma demande?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Si j’ai trouvé grâce devant le roi, que le roi vienne encore avec Aman demain au festin que je leur ferai, et demain je ferai ma requête et ma demande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Et Aman, au comble de la joie, sortit d’auprès de son maître; et en apercevant dans le parvis le Juif Mardochée, il fut grandement courroucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Et aussitôt rentré chez lui, il convoqua ses amis et Zosara, sa femme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Et il leur décrivit ses richesses et les honneurs dont le roi l’avait revêtu, et comme il l’avait placé à la tête du royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Et il ajouta: La reine n’a invité personne au festin qu’elle vient de donner à son époux, si ce n’est moi, et je suis convié encore pour demain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Mais rien de tout cela ne me charmera tant que je verrai dans le parvis le Juif Mardochée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Et Zosara, sa femme, et ses amis lui dirent: Que l’on te fasse une potence de cinquante coudées; parles-en demain au roi dès l’aurore, et que Mardochée soit pendu à cette potence. Ensuite, va au festin avec ton maître, et sois joyeux. Et le conseil plut à Aman, et il fit dresser la potence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Or, cette nuit-là, le Seigneur éloigna du roi le sommeil, et Artaxerxès dit à son serviteur d’apporter le livre de ses archives et de le lui lire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Et il tomba sur ce qui était écrit concernant Mardochée, quand il avait fait connaître au roi le complot des deux eunuques qui le gardaient, et qui voulaient porter les mains sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Et le roi dit: Quels honneurs, quelle grâce Mardochée a-t-il reçus de moi? Et les serviteurs répondirent: Tu n’as rien fait pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Pendant que le roi se rappelait le zèle de Mardochée, Aman entra dans le parvis, et le roi dit: Y a-t-il quelqu’un dans le parvis? Or, Aman arrivait pour demander au roi de pendre Mardochée à la potence qu’il avait dressée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Et les serviteurs du roi répondirent: Voilà Aman dans le parvis. Et le roi dit: Appelez-le.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Et le roi dit à Aman: Que ferai-je pour l’homme que je veux glorifier? Et Aman se dit: Qui donc le roi veut-il glorifier, si ce n’est moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Et il répondit: Pour l’homme que le roi veut glorifier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Que les serviteurs du roi apportent la robe de fin lin dont il se revêt, et le cheval qu’il monte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Que cela soit donné à l’un des amis du roi, parmi ceux du premier rang; qu’il habille l’homme que le roi aime, qu’il le fasse monter à cheval, que dans toutes les places de la ville il proclame ces mots: Ainsi sera-t-il fait à tout homme que le roi honore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Et le roi dit à Aman: Tu as bien parlé; ainsi soit fait par toi au Juif Mardochée qui sert en mon parvis, et que rien ne soit négligé de ce que tu as dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Aman prit donc la robe, et le cheval, et il habilla Mardochée, et il le fit monter à cheval, et il parcourut toutes les rues de la ville, et il proclama ces mots: Ainsi sera-t-il fait à tout homme que le roi voudra honorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Et Mardochée revint au parvis, et Aman rentra en sa demeure avec un grand mal de tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Et il fit à Zosara, sa femme, et à ses amis, le récit de ce qui était advenu; et ses amis et sa femme lui dirent: Si Mardochée est de la race des Juifs, tu as commencé à être humilié devant lui; tu tomberas, et tu ne pourras te défendre contre lui; car le Dieu vivant est avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Comme ils parlaient encore, les eunuques vinrent presser Aman de se rendre au repas qu’Esther avait préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Le roi et Aman entrèrent pour boire avec la reine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Et, à ce second festin, le roi dit à Esther: Qu’y a-t-il, reine Esther? Quelle est ta requête, quelle est ta demande? Qu’il te soit accordé jusqu’à la moitié de mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Et elle répondit: Si j’ai trouvé grâce devant le roi, qu’il accorde à ma requête, ma vie, et à ma demande, mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Car moi et mon peuple nous sommes voués à la destruction, au pillage, à l’esclavage, nous et nos enfants, nos serviteurs et nos servantes. Mais je n’y ai point cru, parce que l’accusateur n’est pas digne du palais du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Et le roi Qui donc est celui qui a osé faire cette chose?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Et Esther dit: Notre ennemi c’est Aman, ce méchant homme. Or, Aman était plein de trouble à cause du roi et de la reine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Et le roi se leva de table pour aller dans le jardin, et Aman implora la reine; car il se voyait dans le malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Et le roi rentra du jardin, et Aman était tombé sur le lit en suppliant la reine, et le roi s’écria: Va-t-il jusqu’à faire violence à ma femme dans mon palais? A ces mots, Aman eut le visage bouleversé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Et Bugathan, l’un des eunuques, dit au roi: Aman a préparé pour Mardochée, qui a jadis averti le roi, une potence de cinquante coudées; elle est dressée dans sa maison. Et le roi dit: Qu’on l’y attache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Et Aman fut pendu à la potence qu’il tenaît prête pour Mardochée, et la colère du roi s’apaisa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Et, en ce jour-là même, le roi Artaxerxès fit don à Esther de tout ce que possédait Aman l’accusateur; et il appela Mardochée, car la reine lui avait dit leur parenté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Et le roi prit l’anneau qu’il avait ôté à Aman et il le remit à Mardochée; et la reine chargea celui-ci d’administrer les biens d’Aman.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Et, continuant de parler au roi, elle se jeta à ses pieds, et lui demanda de rendre nuls les mauvais desseins d’Aman, et ce qu’il avait fait contre les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Et le roi étendit sur Esther sa verge d’or, et elle fut encouragée à se placer auprès de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Et elle dit: S’il te plaît, si j’ai trouvé grâce, que l’on fasse révoquer les édits qu’a publiés Aman, ordonnant d’exterminer tous les Juifs qui sont en ton royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Car, comment pourrais — je voir la ruine de mon peuple? Comment pourrais-je survivre à la destruction de ma patrie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Et le roi dit à Esther: Puisque je t’ai donné tous les biens d’Aman, et que je t’en ai gratifié; puisque je l’ai fait pendre lui — même pour avoir porté les mains sur les Juifs, que demandes-tu encore?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Écrivez vous-mêmes en mon nom ce qu’il vous plaira, et scellez-le avec mon anneau; car nul ne peut contredire ce qui est écrit par l’ordre du roi, et revêtu de son scel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Les scribes furent donc convoqués le vingt-trois du premier mois, du mois de nisan, de la même année, et l’on écrivit ce qui était ordonné, concernant les Juifs, aux intendants et aux chefs des satrapes des cent vingt-sept provinces, depuis l’Inde jusqu’à l’Éthiopie, en la langue de chacune d’elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'On écrivit au nom du roi, et on scella de son sceau les lettres, et on les expédia par des courriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Elles prescrivaient de permettre aux Juifs, en chaque ville, de vivre selon leur loi, de leur porter secours, et de mettre à leur merci leurs ennemis et ceux qui résisteraient,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Dans le royaume d’Artaxerxès, le treizième jour du douzième mois qui est adar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Voici la copie de la lettre: Le grand roi Artaxerxès aux satrapes des cent vingt-sept provinces, de l’Inde à l’Éthiopie, aux gouverneurs des districts, et aux hommes dévoués à mon service, salut. Il arrive que plusieurs, après avoir été souvent honorés des bienfaits de la bonté, ambitionnent plus encore; non-seulement ils cherchent à maltraiter nos sujets, mais, incapables de modérer leur orgueil, ils méditent de mauvais desseins contre leurs bienfaiteurs; non-seulement ils veulent abolir la gratitude parmi les hommes, mais, exaltés par la vaine jactance de gens sans vertu, ils pensent se soustraire au jugement, fatal aux méchants, du Dieu qui voit toutes choses. Maintes fois la flatterie a rendu complices du crime de verser le sang innocent, et enveloppé de maux intolérables plusieurs de ceux qui sont investis de l’autorité, à qui est confié le maniement des affaires de leurs amis; certains hommes ayant trompé, par le faux raisonnement de la malice, la bienveillance sincère des puissants. Cela se peut voir moins par les plus anciennes histoires, que nous nous transmettons, qu’en examinant, sous nos pieds, les choses accomplies d’une manière criminelle par la pestilence d’hommes indignement revêtus du pouvoir; et il est de notre devoir, en vue de l’avenir, de préserver de trouble le royaume, et de donner la paix à tous les hommes, en usant de changements utiles, en jugeant, avec l’à-propos le plus équitable, les choses qui surviennent sous nos yeux. Aman, fils d’Amadathe, Macédonien en réalité, étranger au sang des Perses, bien éloigné de notre bonté naturelle, amicalement accueilli par nous, eut de notre amour, que nous portons à tous les hommes, une telle part que nous l’appelions notre père, que nous le faisions adorer par tous, et que nous lui avions donné la seconde place du royaume. Mais, il ne put maîtriser son orgueil, et il entreprit de nous ôter la vie et le pouvoir. D’abord, il nous demanda de perdre notre sauveur Mardochée, notre bienfaiteur en toute circonstance, et la reine Esther, notre irréprochable compagne, et tout leur peuple; et il me surprit par un tissu d’accusations calomnieuses. Et il espérait par ses artifices dépeupler nos provinces, et faire passer aux Macédoniens l’empire des Perses. Ce triple scélérat nous avait donc trahis au point de nous décider à exterminer les Juifs, quand nous avons reconnu que, loin d’être portés à mal faire, ils obéissaient aux lois les plus justes, qu’ils étaient les fils du Dieu vivant, très-grand et très-haut, qui nous a dirigés nous et nos ancêtres pour mettre notre royaume en la situation la plus florissante. En conséquence, vous agirez bien en n’exécutant pas l’édit que vous a envoyé Aman, fils d’Amadathe; car, pour ce qu’il a fait, il a été pendu avec toute sa famille devant les portes de Suse; Dieu lui-même, le maître de toutes choses, l’a promptement rétribué selon son mérite. Que la présente copie de lettre soit affichée en tout lieu, assurant aux Juifs la liberté de suivre leurs lois et d’user de leurs richesses; qu’au temps marqué pour leur affliction, le treize du douzième mois, du mois d’adar, ils puissent se défendre eux-mêmes contre ceux qui les attaqueraient. Car Dieu, maître de toutes choses, a changé en un jour de joie le jour où devait périr la race qu’il a choisie; et vous-mêmes, vous le rangerez parmi vos fêtes solennelles, et vous le célèbrerez par des festins universels; afin que, dès maintenant et à l’avenir, ce soit un jour de délivrance tant pour nous que pour les amis des Perses, et que, pour ceux qui conspirent contre nous, ce jour soit un mémorial de destruction. Toute ville ou province qui désobéira aux présentes prescriptions, ressentira ma colère, et périra par le fer et la flamme; il ne suffira pas qu’elle devienne inaccessible aux hommes, les bêtes fauves et les oiseaux la haïront à jamais. Et que l’on affiche cette copie en des places apparentes dans tout le royaume, et que, le jour indiqué, les Juifs se tiennent prêts à combattre leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Les courriers se hâtèrent de partir pour porter les ordres du roi, et l’édit fut affiché dans Suse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Et Mardochée sortit, revêtu d’une robe royale, ayant une couronne d’or et un diadème pourpre du lin le plus fin; et le peuple de Suse, l’ayant vu, se réjouit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Et, pour les Juifs, il y eut lumière et allégresse');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'En toute ville et province où l’on afficha l’édit et où il fut proclamé, ils firent des réjouissances et se donnèrent des repas. Et, parmi les gentils, beaucoup se circoncirent et judaïsèrent par crainte des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Le treize du douzième mois, du mois d’adar, l’édit du roi fut exécuté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Ce jour-là, les ennemis des Juifs périrent, et nul ne se défendit à cause de la crainte qu’ils avaient d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Et les officiers des satrapes, et les rois, et les scribes royaux, honorèrent les Juifs; car ils redoutaient Mardochée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Et l’édit du roi en vint à être loué dans tout le royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Et à Suse les Juifs tuèrent cinq cents hommes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Pharsannès, et Delphon, et Phasgas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Et Phardathas, et Barcas, et Sarbacas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Et Marmarinas, et Ruphès, et Arsès, et Zabuthis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Et ils enlevèrent les dix fils d’Aman, fils d’Amadathe le Bugéen, l’ennemi des Juifs, et ils pillèrent leurs maisons');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Ce même jour-là. Et on remit au roi le dénombrement de ceux qui, à Suse, avaient péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Et le roi dit à Esther: Les Juifs ont tué cinq cents hommes à Suse; combien penses-tu qu’ils en aient exterminé dans les provinces? Que demandes-tu encore, que te faut-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Et Esther répondit: Qu’il soit permis aux Juifs d’en user de même demain jusqu’à pendre les dix fils d’Aman. 13. Et le roi le voulut ainsi; et les corps des fils d’Aman furent livrés aux Juifs de la ville pour être pendus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Et les Juifs de Suse se réunirent le quatorze d’Adar, et ils tuèrent trois cents hommes, et ils ne prirent rien de leurs dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Les autres Juifs du royaume se réunirent et se prêtèrent un mutuel secours, et ils se débarrassèrent de leurs ennemis; car ils en tuèrent quinze mille, le treize d’adar, et ils ne prirent rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Et ils restèrent en repos le quatorze du même mois, car ils fêtèrent ce jour de repos par de grandes réjouissances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Mais les Juifs de Suse ne cessèrent le massacre qu’à fin du quatorze; et ils passèrent le quinze à se réjouir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'A cause de cela, les Juifs dispersés dans toutes les provinces ont coutume de fêter le quatorze d’adar, et chacun envoie des parts à son voisin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Mardochée écrivit ces choses en un livre, et il envoya dire à tous les Juifs qui demeuraient dans le royaume dArtaxerxès, soit près, soit loin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'D’instituer ces jours comme des jours heureux, et de fêter le treize et le quatorze d’adar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Car, en ces deux journées, les Juifs avaient été délivrés de leurs ennemis; et le mois, qui est adar, durant lequel ils avaient passé du deuil à la joie, et des douleurs à un jour heureux, fut consacré tout entier aux jours heureux des noces et des réjouissances; et chacun envoya des parts à ses amis et aux indigents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Et les Juifs se sont conformés depuis à ce qu’avait écrit Mardochée, leur faisant savoir:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Comme Aman, fils d’Amadathe le Macédonien, était devenu leur ennemi; comme il avait fait un édit, et agité les sorts pour les exterminer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Comme il était entré chez le roi, lui disant de faire pendre Mardochée; et comment tous les maux qu’il avait essayé de faire tomber sur les Juifs étaient tombés sur luimême, qui avait été pendu ainsi que ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'À cause de cela, ces jours furent appelés Phrurées, à cause des sorts (car, dans leur dialecte, les sorts se traduisent par Phrurées); à cause des paroles de ce livre de Mardochée, et à cause de ce qu’ils avaient souffert à ce sujet et de ce qui leur était advenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Et il régla les choses ainsi. Et les Juifs adoptèrent l’usage de ces fêtes pour eux et pour leur race, et pour ceux qui se joignirent à eux pour les observer, et ils ne feront jamais autrement; et ces jours sont un mémorial gardé de générations en générations en chaque ville, chaque famille, chaque province.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Et ces jours des Phrurées, disent-ils, seront gardés en tout temps, et le mémorial ne manquera à aucune génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Et la reine Esther, fille d’Aminadab, et le Juif Mardochée, écrivirent tout ce qu’ils avaient fait pour confirmer la lettre concernant les Phrurées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Et Mardochée et la reine Esther instituèrent pour eux-mêmes et les leurs, ces choses; et, en ce temps, ils établirent de leur propre autorité cette loi concernant leur délivrance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Et Esther fit cela par un commandement pour toujours, et elle l’écrivit en un mémoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Et le roi écrivit ce qui concernait l’empire de la terre et de la mer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Et sa puissance, et sa valeur, et ses richesses, et sa gloire, sont décrites dans le livre des rois des Perses et des Mèdes, comme un mémorial.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Et Mardochée fut le lieutenant du roi Artaxerxès, et il fut grand dans le royaume, et il fut glorifié par les Juifs; et, aimé de tous, il exposa la suite de l’événement à tout son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Et Mardochée dit: Tout cela vient de Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Car je me souviens de la vision que j’ai eue au sujet de ces événements, et rien de ce qu’elle annonçait n’a manqué d’advenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'La petite fontaine qui devint fleuve et qui fut lumière, soleil et onde abondante: c’est Esther, c’est elle qui est le fleuve; le roi l’a épousée et il l’a couronnée reine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Les deux dragons, c’est moi et Aman.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Les nations, c’est la foule qui s’assembla pour effacer le nom des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Et notre nation, c’est Israël qui invoqua Dieu et fut sauvé. Et le Seigneur a protégé son peuple, et il nous a délivrés de tous ces maux, et il a fait éclater des prodiges, et il a montré des signes, ce qui n’est jamais arrivé chez les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'A cause de cela, il a fait deux sorts: l’un pour son peuple, l’autre pour les autres nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Et les deux sorts ont comparu devant Dieu au moment et à l’heure, le jour où il devait juger toutes les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Et Dieu s’est souvenu de son peuple, et il a vengé son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Et les jours d’adar, le treize et le quatorze, seront célébrés devant Dieu par tout le peuple à jamais, par des réjouissances et des fêtes, en tout Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'La quatrième année du règne de Ptolémée et de Cléopâtré, Dosithée, qui dit être prêtre et lévite, accompagné de Ptolémée, son fils, apporta cette lettre sur les Phruréés; et, tous les deux, déclarèrent qu’elle avait été traduite à Jérusalem par Lysimaque, fils de Ptolémée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '');
