INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'La douzième année du règne de Nabuchodonosor, qui régna sur les Assyriens en la grande ville de Ninive, du temps d’Arphaxad, qui régnait sur les Mèdes en Ecbatane,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Celui-ci édifia autour d’Ecbatane un rempart en pierres de taille, larges de trois coudées, longues de six; et il donna aux murs une hauteur de soixante-dix coudées, et une largeur de cinquante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Et il éleva, au-dessus des portes de la ville, les tours à la hauteur de cent coudées; et il assit les fondations de la ville sur une largeur de soixante coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Et il fit des portes (portes qu’il rétablit), sur une hauteur de soixante-dix coudées, et leur largeur fut de quarante coudées, pour les sorties de ses vaillants et les manœuvres de ses piétons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Or, en ces jours-là, le roi Nabuchodonosor livra bataille au roi Arphaxad dans la vaste plaine qui est sur le territoire de Ragau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Tous ceux qui habitaient la région montagneuse, les rives de l’Euphrate, du Tigre, de l’Hydaspe et ceux de la plaine d’Erioch, roi des Élyméens, se réunirent à lui, et une multitude de nations allèrent ensemble combattre les fils d’Héléhul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 7, 'Et, avant la guerre, Nabuchodonosor, roi des Assyriens, envoya chez les Perses et chez tous les peuples de l’Occident qui habitaient la Cilicie, Damas, le Liban, l’Anti-Liban, et toutes les provinces maritimes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 8, 'Et le mont Carmel, et Galaad, et la haute Galilée, et la grande plaine d’Esdrelon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 9, 'Et toutes les villes de Samarie, et les rives du Jourdain jusqu’à Jérusalem, et Béthanie, et Chellus, et Cadès, et les bords du fleuve d’Égypte, et Taphas, et Ramsès, et toutes la terre de Gesen');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 10, 'Jusqu’au delà de Tanis et de Memphis, et toute l’Égypte jusqu’aux frontières de l’Éthiopie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 11, 'Or, toutes les nations qui habitaient toute la terre, méprisèrent les ordres de Nabuchodonosor, roi des Assy riens, et elles ne se joignirent pas à lui en cette guerre, parce qu’elles ne le craignaient pas, et qu’il était à leurs yeux comme un autre homme; et elles renvoyèrent ses messagers les mains vides en les outrageant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 12, 'Et Nabuchodonosor se mit en grand courroux contre toute cette terre, et il jura, par son trône et sa royauté, de tirer vengeance des Ciliciens, de Damas, et des Syriens, et de passer au fil de l’épée Moab, les fils d’Ammon, toute la Judée et l’Égypte jusqu’aux bords des deux mers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 13, 'Ensuite, il livra bataille, avec toutes ses forces, à Arphaxad en la dix-septième année de son règne, et il fut le plus fort, et il mit en déroute l’armée d’Arphaxad, sa cavalerie et ses chars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 14, 'Et il se rendit maître de toutes ses villes, et il poussa jusqu’à Ecbatane, et il prit ses tours, et il pilla ses places, et il fit son opprobre de ce qui avait fait son ornement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 15, 'Et il prit Arphaxad dans les montagnes de Ragau, et il le perça de ses traits, et il abattit sa puissance, qui ne s’est pas relevée jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 16, 'Et il revint avec ses captifs, lui et tous ses alliés et la multitude innombrable de ses guerriers, en Médie; il passa avec son armée cent vingt jours dans les festins et les délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Et, en la dix-huitième année de son règne, le vingt-deux du premier mois, il y eut un conseil dans le palais de Nabuchodonosor, pour tirer vengeance de toute la terre, comme il l’avait résolu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Et il convoqua tous ses serviteurs et ses grands, et il leur dévoila le mystère de sa résolution; et, de sa propre bouche, il décréta la ruine complète de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Et ils jugèrent qu’il fallait exterminer toute chair chez ceux qui n’avaient point suivi la parole de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Et lorsque le conseil fut achevé, Nabuchodonosor appela Holopherne, général en chef de ses armées, le second après lui, et il lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Voici ce que dit le grand roi, maître de toute la terre: Voilà que tu vas sortir de devant ma face, et prendre avec toi des hommes confiants en leur force, jusqu’à cent vingt mille piétons, et autant de chevaux avec leurs cavaliers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Puis, tu marcheras contre toute la terre de l’Occident, car ils n’ont point obéi à la parole de ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Et tu leur feras savoir qu’ils préparent la terre et l’eau; car, dans ma fureur, je marcherai contre eux, et je couvrirai, sous les pieds de mon armée, toute la surface de la terre, et je les livrerai en proie à mes guerriers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Et leurs cadavres rempliront les vallons et les torrents, et chaque fleuve débordera à cause des morts dont il sera rempli;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Et je ferai conduire les captifs aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Pars donc, envahis tous leurs territoires; ils se rendront à toi, et tu me les conserveras pour le jour de ma vengeance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Quant à ceux qui n’obéiront pas, tu n’auras d’eux aucune pitié; tu les feras massacrer, ou tu les emmèneras en tous tes domaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Par ma vie, par la force de mon royaume, j’ai dit, et je ferai ces choses de ma main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 13, 'Et toi, tu ne transgresseras en rien les paroles de ton maître; mais tu accompliras et accompliras tout ce que je t’ai commandé, et tu ne tarderas pas à l’accomplir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 14, 'Et Holopherne sortit de devant la face de son maître, et il convoqua tous les vaillants, et les généraux et les intendants de l’armée d’Assur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 15, 'Et il compta, pour entrer en campagne, autant d’hommes d’élite que son maître l’avait ordonné, par douzaines de myriades, et douze mille cavaliers portant des arcs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 16, 'Et il les disposa comme à la guerre on dispose une grande multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 17, 'Et il prit un immense convoi de chameaux, d’ânes et de mulets pour les bagages, et un innombrable approvisionnement de brebis, de bœufs et de chèvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 18, 'Et, pour chaque homme, abondance de vivres et des amas d’argent et d’or tirés du trésor royal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 19, 'Et il partit en personne avec toute son armée pour devancer, en cette expédition, le roi Nabuchodo nosor, et cacher toute la face de la terre d’Occident sous ses chars, ses chevaux et ses piétons d’élite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 20, 'Et cette multitude était comme une nuée de sauterelles, ou comme le sable de la terre; car on n’en savait pas le nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 21, 'Et, au sortir de Ninive, après trois jours de marche, il campa dans la plaine de Bectileth, près des montagnes, à gauche de la haute Cilicie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 22, 'Et il prit toute son armée, ses piétons, ses cavaliers et ses chars, et il entra dans les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 23, 'Et il rompit Phud et Lud, et ses troupes pillèrent tous les fils de Rassis et les fils d’Ismaël, ceux qui demeurent en face du désert, au midi des Helléens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 24, 'Et il passa l’Euphrate, et il traversa la Mésopotamie, et il renversa toutes les forteresses bâties sur le torrent d’Abron jusqu’à son embouchure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 25, 'Et il se rendit maître de la Cilicie entière, et il tailla en pièces tout ce qui lui résista; et il atteignit le territoire de Japhet qui s’étend au sud, en face de l’Arabie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 26, 'Et il enveloppa tous les fils de Madian, et il incendia leurs demeures, et il pilla leurs bergeries.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 27, 'Et il descendit dans la plaine de Damas, comme on moissonnait les froments, et il livra les champs à la flamme, et il fit disparaître brebis et boeufs, et il pilla les villes, ravagea les campagnes, et passa tous les jeunes hommes au fil de l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 28, 'Et la terreur, la crainte de lui tombèrent sur les peuples de la côte, sur ceux qui étaient en Sidon, et à Tyr, et à Sur, et à Ocina, et sur tous ceux de Jemnaan. Et les habitants d’Azot et d’Ascalon furent frappés d’épouvante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Et ils lui envoyèrent des messagers, avec des paroles pacifiques, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Voilà que nous, les serviteurs du grand roi Nabuchodonosor, nous sommes devant toi; use de nous comme bon te semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Voilà que nos maisons des champs, et toute notre plaine couverte de moissons, et nos brebis, et nos bœufs, et nos tentes, sont devant toi; uses-en comme bon te semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Voilà que nos villes et ceux qui les habitent sont tes esclaves; viens, entres-y comme il est agréable à tes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Et ces hommes arrivèrent auprès d’Holopherne, et ils lui rapportèrent ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Et il descendit, en la contrée maritime, lui et son armée, et il mit des garnisons dans les villes fortifiées, et il en prit les hommes d’élite comme auxiliaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Et ils l’accueillirent, eux et tout leur voisinage, avec des couronnes, des chœurs de danse et des tambours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Et il détruisit tout sur leur territoire, et il arracha les bois sacrés; et il avait résolu de briser tous les dieux de la terre, afin que les nations ne servissent plus que le seul Nabuchodonosor, et que toutes leurs langues, toutes leurs tribus l’invoquassent comme un Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Et il arriva en face d’Esdrelon, près de Dothaïn, qui est devant la grande chaîne de montagnes de la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 10, 'Et il campa entre Gébé et Scython, et il y resta un mois pour refaire tout l’approvisionnement de son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Et les fils d’Israël, qui demeuraient en Judée, ouïrent tout ce qu’Holopherne, général en chef de Nabuchodonosor, roi des Assyriens, avait fait aux nations, et de quelle manière il s’était emparé de leurs choses saintes pour les anéantir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Et ils eurent très-grande crainte de lui, et ils furent pleins de trouble, à cause de Jérusalem et du temple du Seigneur leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Car ils étaient récemment revenus de captivité; et tout le peuple de la Judée s’était de nouveau réuni, et les vases, et l’autel et le temple, après avoir été profanés, venaient d’être sanctifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Et ils envoyèrent des messagers sur tout le territoire de Samarie, ainsi qu’à Conus, à Béthoron, à Belmen, à Jéricho, à Hoba, à Aisora et dans le val de Salem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Et ils occupèrent toutes les cimes des hautes montagnes, fortifièrent leurs bourgs et les approvisionnèrent de vivres et de munitions de guerre; car leurs champs venaient d’être moissonnés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Et Joacim, qui était en ces jours-là grand prêtre à Jérusalem, écrivit aux habitants de Béthulie et de Betomesthem qui est devant Esdrelon, en face de la plaine voisine de Dothaïn,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Disant de garder les défilés de la région montagneuse; car c’est là qu’était l’entrée de la Judée, et il était facile de contenir les assaillants, la montée étant assez étroite pour que deux hommes suffisent contre tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Et les enfants d’Israël firent comme le leur prescrivirent Joacim le grand prêtre, et les anciens du peuple qui résidaient à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Et tous les hommes d’Israël crièrent au Seigneur avec une grande instance, et ils humilièrent leurs âmes avec une grande instance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 10, 'Et ils ceignirent de cilices eux, leurs femmes, leurs enfants, leurs chevaux, et tout étranger travaillant comme mercenaire ou acheté à prix d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 11, 'Et tout le peuple de Jérusalem, les hommes, les femmes, les enfants se prosternèrent devant le temple de Dieu, la tête couverte de cendres, et ils montrèrent leurs cilices au Seigneur, et ils entourèrent l’autel d’un cilice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 12, 'Et, tout d’une voix, avec instance, ils crièrent au Dieu d’Israël pour qu’il ne livrât pas leurs enfants et leurs femmes au pillage, les villes de leur héritage à la destruction, les choses saintes à la profanation, aux outrages, à la risée des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 13, 'Dieu entendit leur clameur et il vit leur affliction. Et le peuple jeûna bien des jours, en toute la Judée, et à Jérusalem devant le Saint des saints du Seigneur toutpuissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 14, 'Et Joacim le grand prêtre et tous les prêtres qui servaient devant le Seigneur, les reins ceints de cilices, offrirent l’holocauste perpétuel, et les vœux, et les dons volontaires du peuple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 15, 'Et ils avaient de la cendre sur leurs tiares, et ils criaient au Seigneur Dieu de toutes les armées, afin qu’il regardât pour son bien toute la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Et l’on vint dire à Holopherne, général en chef de l’armée d’Assur, que les fils d’Israël avaient fait des apprêts de guerre, qu’ils avaient clos les défilés des montagnes, muré toutes les cimes des monts, et créé des obstacles dans la plaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Et il s’enflamma d’une violente colère, et il convoqua tous les chefs de Moab, et les généraux d’Ammon, et les satrapes de la contrée maritime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Et il leur dit: Instruisez-moi, fils de Chanaan: quel est le peuple qui demeure dans les montagnes? Quelles sont les villes qu’ils habitent? Quel est le nombre de leur armée? En quoi consistent leur force et leur puissance? Quel roi ont-ils à la tête de leurs combattants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Pourquoi dédaignent-ils de se rendre auprès de moi, parmi tous les peuples de l’Occident?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Et Achior, chef de tous les fils d’Ammon, lui dit: Que mon maître écoute la parole de la bouche de son esclave, et je te ferai connaître la vérité sur le peuple qui habite ces montagnes que tu vois près de toi, et aucun mensonge ne sortira de la bouche de ton esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Ce peuple est issu de la Chaldée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Ils émigrèrent d’abord en la Mésopotamie, parce qu’ils ne voulurent point servir les dieux de leurs pères qui étaient en la terre de Chaldée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Et ils sortirent de la voie de leurs ancêtres, et ils adorèrent le Dieu du ciel, le Dieu qu’ils avaient appris à connaître, et, comme on les chassa de la face des faux dieux, ils s’enfuirent en Mésopotamie et ils y demeurèrent bien des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Et leur Dieu leur dit de quitter le lieu de leur passage, et de s’en aller en la terre de Chanaan, et ils s’y établirent, et ils devinrent très-riches en or, en argent et en bestiaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Et ils descendirent en Égypte, car une famine avait enveloppé la face de toute la terre de Chanaan, et ils y restèrent jusqu’à ce qu’ils s’y fussent accrus. Et ils s’y multiplièrent au point que leurs familles étaient innombrables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Et le roi d’Égypte se leva contre eux; et on les opprima par le travail, en leur faisant faire des briques, et on les humilia, et on les traita en esclaves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Et ils crièrent à leur Dieu, qui frappa l’Égypte de plaies sans remède; et les Égyptiens les chassèrent de devant leur face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Et Dieu, devant eux, mit à sec la mer Rouge,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 14, 'Et il les conduisit par la route de Sina et de CadèsBarné; ils chassèrent devant eux tous ceux qui habitaient le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 15, 'Et ils se fixèrent en la terre des Amorrhéens, et, en leur force, ils exterminèrent les Esebonites; et, après avoir passé le Jourdain, ils prirent possession de toute la contrée montagneuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 16, 'Et ils chassèrent de devant leur face le Chananéen, le Phérézéen, le Jébuséen, et ceux de Sichem, et tous les Gergéséens, et ils demeurèrent bien des jours en la terre promise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 17, 'Et, tant qu’ils ne péchèrent point devant leur Dieu, ils prospérèrent; car c’est un Dieu haïssant l’iniquité qu’ils ont avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 18, 'Mais, lorsqu’ils s’écartèrent de la voie qu’il leur avait tracée, ils furent exterminés en beaucoup de batailles contre de grandes multitudes; ils furent emmenés captifs en une terre étrangère, et le temple de leur Dieu fut abaissé au niveau du sol, et leurs villes furent prises par les ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 19, 'Et maintenant, s’étant convertis à leur Dieu, ils sont revenus des lieux où ils avaient été dispersés, et ils ont recouvré Jérusalem où sont leurs choses saintes, et ils ont repeuplé la contrée montagneuse qui était un désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 20, 'Sache donc, seigneur mon maître, s’il est quelque égarement parmi ce peuple, s’ils pèchent contre leur Dieu; informons-nous de ce qui est pour eux une cause de chute, et nous irons les combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 21, 'Mais, s’il n’y a point chez ce peuple de déréglement, que mon maître les évite, de peur que le Seigneur leur Dieu n’étende son bouclier sur eux, et que nous ne soyons la risée de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 22, 'Or, dès qu’Achior eut fini de parler, tout le peuple, qui se tenait autour de la tente, se mit à murmurer. Et les chefs d’Holopherne, et ceux des villes maritimes, et ceux de Moab, s’écrièrent: Il faut le mettre en pièces;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 23, 'Car nous ne craignons pas les fils d’Israël: c’est un peuple qui n’a ni troupes ni force pour nous livrer sérieusement bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 24, 'Marchons donc, Holopherne, notre maître; ta grande armée n’en fera qu’une bouchée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Dès que le tumulte des hommes, qui entourait le conseil, fut apaisé, Holopherne, général en chef de l’armée d’Assur, dit à Achior, devant tout le peuple des Philistins, et devant tous les fils de Moab:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Qui donc es-tu, Achior? que sont les mercenaires d’Ephraïm, pour que, parmi nous, tu aies prophétisé comme aujourd’hui, et que tu m’aies dit de ne point combattre la race d’Israël, parce que son Dieu la protége? Et qui donc est Dieu, si ce n’est Nabuchodonosor?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'C’est lui qui déploiera sa puissance, et il les fera disparaître de la face de la terre, et leur Dieu ne les sauvera pas. Et nous, ses serviteurs, nous les abattrons comme un seul homme; ils ne soutiendront pas le choc de nos chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Nous les brûlerons chez eux; leurs montagnes s’enivreront de leur sang, leurs plaines seront couvertes de leurs cadavres, et la trace de leurs pas ne subsistera même point devant nous; ils auront radicalement péri. Voilà ce que dit le roi Nabuchodonosor, le maître de toute la terre; il a parlé, et ses paroles ne seront point choses vaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Et joi, Achior, mercenaire d’Ammon, qui as dit ces paroles au jour de ton iniquité, à partir de ce jour tu ne verras plus mon visage, jusqu’à ce que j’aie tiré vengeance de cette race qui est sortie d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Et alors, le fer de mon armée, la foule de mes serviteurs traverseront tes flancs, et tu tomberas parmi leurs morts quand je serai revenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Et mes serviteurs vont te mener dans les montagnes, et ils te déposeront en l’une des villes par où l’on y monte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Et tu ne périras pas que tu ne sois frappé avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Et si en ton cœur tu espères qu’ils ne seront point pris, ne nous montre donc pas un visage si abattu. J’ai dit, nulle de mes paroles ne sera sans effet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Et Holopherne ordonna à ses serviteurs, qui se tenaient auprès de lui sous sa tente, de saisir Achior, de le conduire à Béthulie et de le livrer aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Et les serviteurs le prirent, et ils l’emmenèrent hors du camp dans la plaine, et, de là, ils passèrent, du milieu de la plaine, en la montagne, et ils arrivèrent aux fontaines qui sont au-dessous de Béthulie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 12, 'Lorsque les hommes de la ville les virent sur la cime de la montagne, ils s’armèrent, ils sortirent de la ville sur la cime de la montagne. Et tous les frondeurs les continrent, comme ils montaient encore, en lançant sur eux des pierres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 13, 'Alors, s’étant glissés au bas de la rampe, ils lièrent Achior, le laissèrent abattu au pied de la montagne, et retournèrent auprès de leur maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 14, 'Or, les fils d’Israël, qui étaient descendus de leur ville, s’arrêtèrent auprès de lui, lui ôtèrent ses liens, le conduisirent à Béthulie, et le menèrent aux chefs de leur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 15, 'Qui, en ces jours-là, étaient: Ozias, fils de Micha, de la tribu de Siméon; Habris, fils d’Othoniel, et Charmis, fils de Melchiel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 16, 'Et ceux-ci convoquèrent tous les anciens de la ville; et les jeunes gens, et les femmes accoururent à l’assemblée; et ils placèrent Achior au milieu de tout le peuple, et Ozias lui demanda ce qui était advenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 17, 'Et, répondant, il leur fit connaître tous les discours du conseil d’Holopherne, toutes les paroles que lui-même avait dites au milieu des chefs des fils d’Assur, et avec, quelle jactance Holopherne avait parlé contre la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 18, 'Et le peuple tomba la face contre terre, et il adora Dieu, et ils crièrent à lui, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 19, 'Seigneur Dieu du ciel, voyez leur orgueil, ayez pitié de l’humiliation de notre race, regardez aujourd’hui ceux qui vous sont consacrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 20, 'Et ils consolèrent Achior, et ils le louèrent grandement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 21, 'Et Ozias l’emmena de l’assemblée à sa maison, et il fit un festin aux anciens du peuple, et toute cette nuit ils implorèrent le secours du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Le lendemain, dès l’aurore, Holopherne donna l’ordre à toute son armée et à la multitude de ses auxiliaires, de marcher sur Béthulie, d’occuper les cols de la montagne, et de porter la guerre chez les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Et, en ces jours-là, chacun de ses vaillants et son armée entière partirent; il avait cent soixante-dix mille combattants à pied, et vingt-deux mille hommes de cavalerie, sans compter les bagages et les hommes à pied qui étaient avec eux: immense multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Et ils campèrent dans la vallée, au-dessous de Béthulie, vers les fontaines, et ils s’étendirent, en large, de Dothaïn à Belthem, et, en long, de Béthulie à Cyamone, qui est en face d’Esdrelon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Or, les fils d’Israël, quand ils virent cette multitude, furent grandement troublés, et ils se dirent les uns aux autres: Cette armée va bientôt balayer la face de toute la terre; ni les hautes montagnes, ni les ravins, ni les collines, ne pourront en soutenir le poids.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Et, chacun ayant pris ses armes de guerre, ils allumèrent des bûchers sur leurs tours, et ils veillèrent toute la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Le jour suivant, Holopherne déploya toute sa cavalerie devant les fils d’Israël qui étaient dans Béthulie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Et il reconnut le chemin montant à leur ville, examina les puits de leurs eaux, s’en rendit maître, y plaça un poste d’hommes vaillants, et rejoignit son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Alors, tous les chefs des fils d’Esau et de Moab, et les généraux des villes maritimes le vinrent trouver, et lui dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Que notre maître écoute une parole, de peur que son armée n’essuie quelque désastre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Car, le peuple d’Israël ne se confie point à ses javelines, mais à la hauteur des monts en lesquels il habite. Et, en effet, il n’est pas facile de monter sur les cimes de ses montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Maintenant donc, maître, ne leur fais pas la guerre, comme il est d’usage, en leur livrant bataille, et pas un homme de ton armée ne périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Demeure dans ton camp, préservant de tout péril chaque homme de ton armée; que tes serviteurs restent maîtres de la fontaine qui jaillit au pied de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Car, c’est là que tous les habitants de Béthulie viennent puiser, et la soif les dévorera, et ils livreront leur ville; nous, cependant, et nos troupes nous monterons sur les cimes voisines, et nous y camperons en avant-garde, pour que personne ne sorte de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Et ils seront consumés par la faim, eux et leurs femmes et leurs enfants, et avant que le glaive les frappe ils succomberont dans les rues où ils habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Et tu leur feras porter une peine sévère de ce qu’ils se sont révoltés, et de ce qu’ils ne sont point venus en paix à ta rencontre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Et ce conseil fut agréable à Holopherne et à tous ses serviteurs; et ils résolurent de faire comme ils avaient dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Et le camp des fils d’Ammon partit, et avec eux cinq mille des fils d’Assur, et ils campèrent dans le vallon, et ils s’emparèrent des eaux et des puits des eaux des enfants d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Et les fils d’Esau montèrent avec les fils d’Ammon, et ils campèrent dans les montagnes vis-à-vis Dothaïn, et ils envoyèrent de leurs hommes au midi et à l’est visà-vis Ecrebel, qui est près de Chus, sur le torrent de Mochmor, et le reste de l’armée des Assyriens était campé dans la plaine, et ils couvraient la face de toute la terre. Et leurs tentes, et leurs bagages étaient rangés en foule, et il y avait là une immense multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 19, 'Et les enfants d’Israël crièrent au Seigneur leur Dieu; car leur souffle était défaillant, parce que tous leurs ennemis les enveloppaient, et qu’il n’y avait pas à leur échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 20, 'Et le camp des Assyriens, piétons, chars et cavaliers, demeura trente-quatre jours autour d’eux, et l’eau que contenaient tous les vaisseaux des habitants de Béthulie vint à manquer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 21, 'Et leurs citernes étaient vides, et on leur donnait à boire à la ration, et ils n’avaient pas eu un seul jour de l’eau à satiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 22, 'Et leurs enfants étaient abattus; leurs femmes, et les jeunes gens mouraient de soif; ils tombaient dans les rues de la ville, et aux passages des portes; il n’y avait plus en eux aucune force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 23, 'Et tout le peuple se réunit autour d’Ozias et des chefs de la ville, jeunes hommes, femmes et enfants, et ils jetèrent une haute clameur, et ils dirent aux anciens:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 24, 'Que Dieu juge entre vous et nous; car vous avez commis parmi nous une grande iniquité en ne portant point des paroles pacifiques aux fils d’Assur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 25, 'Et maintenant, il n’est plus pour nous de défenseur; mais Dieu nous a vendus à leurs mains, pour que devant eux nous soyons abattus par la soif, et en grande perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 26, 'Appelez-les donc, rendez-leur la ville, qu’elle soit tout entière la proie du peuple d’Holopherne et de son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 27, 'Car il vaut mieux pour nous qu’ils nous ravissent; nous serons leurs esclaves, mais notre âme vivra, et nous ne verrons point la mort de nos petits-enfants sous nos yeux; nous ne verrons pas nos enfants et nos femmes, l’âme défaillante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 28, 'Nous prenons à témoin contre vous le ciel et la terre, et notre Seigneur Dieu de nos pères, qui nous punit de nos péchés et des péchés de nos pères, si toi, Ozias, tu ne fais aujourd’hui même comme nous venons de dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 29, 'Et il y eut un grand et unanime gémissement au milieu de l’assemblée, et ils crièrent, à haute voix, au Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 30, 'Et Ozias leur dit: Frères, prenez courage, persistons encore cinq jours pendant lesquels le Seigneur notre Dieu ramènera sur nous sa miséricorde, car il ne nous abandonnera pas jusqu’à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 31, 'Ce temps écoulé, s’il ne nous vient pas en aide, je ferai comme vous avez dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 32, 'Et il renvoya les hommes à leur poste sur les murs et les tours de la ville, et les femmes et les enfants en leurs demeures. Et toute la ville était dans une grande humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Or, en ces jours-là, Judith, fille de Mérari, fils d’Ox, fils de Joseph, fils d’Oziel, fils d’Helcias, fils d’Éliu, fils d’Helciu, fils d’Eliab, fils de Nathanaël, fils de Salamiel, fils de Sarasadaï, fils d’Israël, avait tout entendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Son mari Manassès, de sa tribu et de sa famille. paternelle, était mort pendant la moisson des orges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Car, comme il était à faire lier ses gerbes dans la plaine, il fut frappé à la tête d’un coup de soleil, et il se mit au lit, et il mourut en Béthulie, sa ville, et on l’ensevelit, auprès de ses pères, dans le champ entre Dothaïn et Bélamon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Et Judith était en sa maison, veuve depuis trois ans et quatre mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Et elle s’était dressé une tente, sur la terrasse de sa maison, et elle s’était ceinte d’un cilice, et elle portait les habits de son veuvage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Et elle avait jeûné, tous les jours de son veuvage, hormis le jour et la veille du sabbat, le jour et la veille des nouvelles lunes, ainsi que des fêtes et des réjouissances de la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Et elle était de belle prestance et d’une grande beauté, et Manassès, son mari, lui avait laissé de l’or et de l’argent, des serviteurs, des servantes, du bétail et des champs; et elle demeurait sur son bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Et il n’était personne qui dît contre elle une mauvaise parole, car elle avait grande crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Et elle avait ouï les mauvaises paroles du peuple contre le chef de la ville, parce qu’ils étaient défaillants faute d’eau. Et Judith avait ouï pareillement la réponse d’Ozias, et son serment de rendre dans cinq jours la ville aux Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'Et ayant envoyé sa servante, celle qui était à la tête de tous ses biens, elle appela Ozias, Habris et Charmis, les anciens de sa ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 11, 'Et ils vinrent chez elle, et elle leur dit: Écoutez-moi, chefs de ceux qui habitent Béthulie; ce n’est pas une parole juste que vous avez dite aujourd’hui devant le peuple, quand vous avez mis entre Dieu et vous le serment que vous avez prêté de rendre la ville à nos ennemis, si, dans cinq jours, le Seigneur ne vient pas à notre aide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 12, 'Et qui donc êtes-vous pour tenter aujourd’hui le Seigneur, et pour décider à la place de Dieu, parmi les fils des hommes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 13, 'Et maintenant, vous êtes à examiner le Seigneur tout-puissant, mais vous n’apprendrez jamais à le connaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 14, 'Vous ne trouvez pas le fond du cœur de l’homme; vous ne saisissez point ce qu’il roule en sa pensée. Comment donc scruterez-vous la pensée de Dieu qui a fait toutes ces choses? comment saurez-vous ce qu’il médite? comment pénétrerez-vous ses desseins? Vous ne le pouvez, mes frères; craignez donc d’irriter le Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 15, 'Craignez qu’il ne refuse de vous secourir dans cinq jours; il a le pouvoir de vous sauver dans le nombre de jours qu’il lui convient, ou de nous exterminer devant nos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 16, 'Gardez-vous d’extorquer la volonté du Seigneur notre Dieu, car Dieu ne peut être menacé comme un homme, ni gouverné comme un fils de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 17, 'C’est pourquoi, attendant de lui seul notre salut, il faut l’appeler à notre secours, et il entendra nos cris, si cela lui est agréable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 18, 'Parce que dans nos familles nul ne s’est élevé contre lui; il n’est aujourd’hui ni tribu, ni famille paternelle, ni canton, ni ville, parmi nous, qui adore des dieux faits de la main des hommes, comme il arrivait dans les premiers jours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 19, 'En punition de quoi nos pères ont été livrés au meurtre et au pillage, et ont fait une grande chute devant nos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 20, 'Nous n’avons jamais reconnu d’autre Dieu que lui; voilà pourquoi nous espérons qu’il n’abandonnera ni nous, ni ce qui est de notre race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 21, 'Car, si nous sommes pris, la Judée entière sera renversée, les choses saintes seront pillées, et il nous demandera compte de leur profanation,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 22, 'Et du massacre de nos frères, et de la captivité de la terre, et de la désolation de notre héritage; il fera retomber tous ces malheurs sur nos têtes, chez les nations où nous serons asservis, et nous deviendrons des sujets de scandale et d’outrages aux yeux de ceux qui seront nos maîtres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 23, 'Parce que notre servitude n’ira pas droit à nous attirer sa grâce, mais le Seigneur notre Dieu la fera tourner à notre déshonneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 24, 'Maintenant donc, frères, montrons à nos frères que leur vie dépend de nous, que les choses saintes, et le temple et l’autel, reposent sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 25, 'Par-dessus toutes choses, témoignons notre reconnaissance au Seigneur notre Dieu, qui nous éprouve comme nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 26, 'Souvenez-vous de ce qu’il a fait avec Abraham, et de quelle manière il a tenté Isaac, et de ce qui est advenu à Jacob en la Mésopotamie syrienne, lorsqu’il paissait les brebis de son oncle maternel Laban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 27, 'Il ne vous éprouve pas comme il a éprouvé ceux-ci, en sondant leur cœur, et il ne vous poursuit pas de sa vengeance; mais le Seigneur châtie, pour les avertir, ceux qui s’approchent de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 28, 'Et Ozias lui répondit: Tout ce que tu as dit part d’un cœur vertueux, et personne ne peut opposer quoi que ce soit à tes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 29, 'Et ce n’est pas d’aujourd’hui que ta sagesse éclate: depuis tes premiers jours, tout le peuple connaît ton intelligence et la beauté de ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 30, 'Mais le peuple, qui a eu bien soif, nous a mis dans la nécessité de faire comme nous leur avons dit, et d’assumer sur nous un serment que nous ne violerons point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 31, 'Prie donc pour nous, car tu es une femme pieuse, et le Seigneur enverra de la pluie pour remplir nos citernes, et nous ne manquerons plus d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 32, 'Et Judith leur dit: Écoutez-moi, et je ferai une action qui parviendra aux générations des générations de notre race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 33, 'Tenez-vous cette nuit vers la porte, et je sortirai avec ma servante; et, pendant les jours après lesquels vous avez dit que vous rendriez la ville à nos ennemis, le Seigneur, par mon intermédiaire, visitera Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 34, 'Ne scrutez pas mon dessein; je ne vous dirai rien que mon œuvre ne soit accomplie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 35, 'Et Ozias et les chefs lui dirent: Va en paix, et que le Seigneur marche devant toi pour tirer vengeance de nos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 36, 'Et ils sortirent de la tente de Judith, et ils retournèrent à leur poste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Et Judith tomba la face contre terre, et elle se couvrit la tête de cendre, et ne garda que son cilice; or, l’on venait, tout à l’heure, ce soir-là, d’offrir l’encens dans le temple de Dieu à Jérusalem, et Judith, à haute voix, cria au Seigneur, et elle dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Seigneur Dieu de mon père Siméon, à qui vous avez mis à la main un glaive pour tirer vengeance des étrangers quand ils eurent dénoué la ceinture de la jeune vierge pour la souiller, quand à sa honte ils eurent relevé ses vêtements et l’eurent outragée par leur violence; car vous avez dit: Cela ne peut pas être.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Et ils avaient fait des choses en punition desquelles vous avez livré leurs chefs au meurtre; et vous avez inondé de leur sang la couche où les retenait la ruse des fils de Jacob, et vous avez frappé les esclaves auprès des grands, et les grands sur leurs trônes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Et vous avez fait de leurs femmes une proie, et de leurs filles des captives. Et les fils de ceux que vous aimiez se sont partagé leurs dépouilles, parce qu’ils brûlaient de zèle pour vous, qu’ils avaient en abomination la tache faite à leur sang, et qu’ils avaient invoqué votre secours; ô Dieu, ô mon Dieu, exaucez-moi aussi, moi qui suis veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Car, c’est vous qui avez fait les choses antérieures à celles-ci, et celles-ci, et celles qui suivront. Vous avez conçu les choses d’à présent et celles de l’avenir; et tout ce que vous avez arrêté en votre esprit est arrivé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Et les choses que vous avez méditées ont comparu, et elles ont dit: Nous voici, et toutes vos voies sont préparées, votre jugement est déterminé d’avance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Or, maintenant voilà que les Assyriens ont grossi leurs troupes, ils se sont enorgueillis du cheval et du cavalier, ils se sont glorifiés du bras des piétons, ils ont mis leur espérance en des boucliers, des javelines, des arcs et des frondes; et ils ne savent pas que vous êtes le Seigneur qui broie les combats. Votre nom est le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Brisez leur force par votre puissance, renversez leur domination par votre colère, car ils veulent profaner votre sanctuaire, ils veulent souiller le tabernacle où reposent votre nom et votre gloire, ils veulent abattre avec le fer les cornes de votre autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Voyez leur arrogance, faites tomber votre courroux sur leurs têtes; donnez au bras de la veuve la force d’exécuter ce que la veuve a conçu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Frappez l’esclave auprès du maître et le maître auprès du serviteur, trompés tous les deux par les flatteries de mes lèvres; écrasez leur fierté par la main d’une femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Car votre force n’est pas avec la multitude, ni votre puissance avec les grands; mais vous êtes le Dieu des humbles, l’auxiliaire des petits, le défenseur des faibles, le refuge des méconnus, le sauveur des désespérés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Oui, oui, Dieu de mon père, Dieu de l’héritage d’Israël, maître des cieux et de la terre, créateur des eaux, roi de toutes vos créatures, vous exaucerez ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Faites que mes paroles et mes caresses trompeuses soient plaies et meurtrissures pour ceux qui ont conçu de cruels desseins contre votre alliance, votre temple, la montagne de Sion et la demeure où vous avez établi vos enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Répandez parmi tout votre peuple, parmi toute tribu, l’intelligence; qu’ils sachent que vous êtes le Dieu des royaumes et des armées, et qu’il n’est point pour la race d’Israël d’autre protecteur que vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Lorsqu’elle se fut arrêtée ayant crié au Seigneur, et qu’elle eut achevé toutes ces paroles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Elle se leva du lieu où elle était prosternée, appela sa servante, et descendit en la demeure où elle passait les jours de sabbat et les fêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Et elle rejeta le cilice dont elle était revêtue; elle ôta son habillement de veuve, se lava le corps avec de l’eau, se frotta de myrrhe épaisse, arrangea sa chevelure, et se coiffa d’un turban; puis, elle reprit les vêtements de ses jours de joie, ceux qu’elle portait quand Manassès, son mari, vivait encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Et elle noua sous ses pieds des sandales, mit ses bracelets, ses colliers, ses anneaux, ses pendants d’oreilles, toute sa parure; enfin, elle s’orna magnifiquement pour charmer les yeux de tous les hommes qui la verraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Et elle donna à sa servante une petite outre de vin et une fiole d’huile; et elle remplit un sac de pain, de figues, de vivres frais, et elle mit ces choses dans une double enveloppe, et elle en chargea sa servante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Et elles gagnèrent la porte de Béthulie, et elles y trouvèrent Ozias et les anciens de la ville, Habris et Charmis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Lorsqu’ils la virent; lorsqu’ils virent le changement de son visage et sa parure, ils furent émerveillés de sa beauté, et ils lui dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Que Dieu, que le Dieu de nos pères t’accorde sa grâce, qu’il accomplisse ce que tu as projeté pour l’orgueil des fils d’Israël et l’exaltation de Jérusalem. Et elle adora Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Et elle leur dit: Ordonnez qu’on m’ouvre la porte de la ville, et je sortirai pour mener à bonne fin les affaires dont nous nous sommes entretenus. Et ils ordonnèrent aux jeunes gens de lui ouvrir la porte, comme elle avait dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Et ils obéirent, et Judith sortit avec sa servante; les hommes de la ville la suivirent du regard jusqu’à ce qu’elle fût parvenue au pied de la montagne et qu’elle eût traversé le vallon, et ils ne l’aperçurent plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Et les deux femmes s’enfoncèrent tout droit dans le vallon, et elles rencontrèrent la garde avancée des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Ceux-ci prirent Judith, et lui firent ces questions: De quelles gens es-tu? d’où viens-tu? où vas-tu? Et elle dit: Je suis une fille des Hébreux, et je m’enfuis loin de leur face, parce qu’ils sont à la veille de devenir votre proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Et moi, je vais devant Holopherne, général en chef de votre armée, pour lui annoncer des choses véritables, et je lui montrerai un chemin par où il ira, et il se rendra maître de toute la montagne; et parmi ses hommes nulle chair ayant souffle de vie ne rendra le dernier soupir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Dès que les hommes eurent ouï ses paroles et qu’ils eurent vu son visage (et elle était devant eux merveilleuse par son extrême beauté), ils lui dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Tu as sauvé ta vie en te hâtant de descendre en présence de notre maître; va donc à sa tente; quelques-uns de nous vont te conduire, jusqu’à ce qu’ils t’aient remise entre ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Lorsque tu seras devant lui, ne crains rien en ton cœur, fais-lui connaître ce que tu nous as dit, et il te traitera bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Et ils choisirent entre eux cent hommes, et ceux-ci escortèrent Judith et sa servante, et ils les conduisirent à la tente d’Holopherne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Et il y eut des allées et venues dans tout le camp; car sa présence fut divulguée dans toutes les tentes; et on vint, et on l’entoura pendant qu’elle se tenait hors de la tente d’Holopherne, en attendant qu’on lui eût annoncé sa présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 19, 'Et tous admirèrent sa beauté, et ils s’émerveillèrent à cause d’elle, des fils d’Israël, et ils se dirent les uns aux autres: Qui méprisera ce peuple qui a chez lui de telles femmes? Il ne serait pas bon d’en épargner un seul homme, ceux qui resteraient seraient capables de séduire toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 20, 'Et les serviteurs d’Holopherne qui dormaient auprès de lui sortirent, et ils introduisirent Judith sous sa tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 21, 'Et Holopherne était à se reposer sur son lit dans un moustiquaire de pourpre et d’or, entrelacé d’émeraudes et de pierres précieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 22, 'Et ils la lui annoncèrent, et il vint dans l’avant-tente, et l’on portait devant lui des flambeaux d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Et Holopherne lui dit: Rassure-toi, femme, ne crains rien en ton cœur; je n’ai maltraité aucun des hommes qui ont bien voulu servir Nabuchodonosor, roi de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Et si ton peuple, qui habite la montagne, ne m’avait point méprisé, je n’aurais point levé contre eux ma javeline; mais ils se sont fait à eux-mêmes cela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Et maintenant, dis-moi pourquoi tu les as fuis, et es venue auprès de nous? Certes, tu viens pour ton salut; rassure-toi, tu vivras cette nuit, et les autres nuits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Il n’est personne pour te faire injure, mais on te traitera bien, comme il arrive à ceux qui servent mon maître, le roi Nabuchodonosor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Et Judith lui dit: Accueille les paroles de ta servante, et que ta servante te parle en face, et cette nuit je ne dirai rien à mon maître qui ne soit vrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Et si tu suis les conseils de ta servante, Dieu fera avec toi une chose parfaite, et mon maître ne sera frustré en rien de ce qu’il médite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Vive Nabuchodonosor, roi de toute la terre! vive sa puissance! il t’a envoyé pour le redressement de toute âme; car, ce ne sont pas seulement les hommes qui seront tes esclaves pour te servir, mais, les bêtes fauves des champs, et les troupeaux, et les oiseaux du ciel, à cause de ta force, vivront pour Nabuchodonosor et toute sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 8, 'J’ai entendu parler de ta sagesse et de toutes les ressources de ton âme, et il est connu de toute la terre que toi seul en tout le royaume tu es brave et expérimenté, et admirable dans les combinaisons de la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 9, 'J’ai appris aussi ce qu’Achior dit en ton conseil, nous avons ouï son discours, car les hommes de Béthulie lui ont donné asile, et il leur a fait connaître toutes les paroles qu’il t’a adressées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 10, 'Ne les dédaigne pas, seigneur maître, mais dépose-les en ton cœur; elles sont véritables; en effet, notre race ne sera pas punie, le glaive ne prévaudra pas contre elle, si elle n’a péché contre son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 11, 'Or maintenant, afin que mon maître ne soit pas rejeté et sans succès, la mort va tomber sur eux en face, car un péché par lequel ils ont irrité leur Dieu les a fait condamner, et ils se sont étrangement égarés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 12, 'En effet, manquant de vivres, n’ayant plus d’eau, ils ont le dessein de mettre la main sur leur bétail, et tout ce que, dans sa loi, Dieu leur a enjoint de ne pas manger, ils ont résolu de s’en repaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 13, 'Et les prémices de leur blé, et la dîme de leur huile et de leur vin, qu’ils réservaient comme consacrées aux prêtres qui se tiennent à Jérusalem devant notre Dieu, ils ont pris sur eux d’en user; et ils consommeront des choses que nul parmi le peuple n’a le droit de toucher de ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 14, 'Parce que ceux qui demeurent ici ont fait cela, ils ont envoyé des hommes à Jérusalem, pour que les anciens leur en donnent la permission;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 15, 'Et quand ils auront la réponse et qu’ils feront ces choses, ce jour-là même sera celui de leur ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 16, 'Voilà pourquoi moi, ta servante, en ayant été informée, je me suis échappée de leur ville. Et Dieu m’a envoyée pour accomplir avec toi des choses qui frapperont d’étonnement sur toute la terre ceux qui les apprendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 17, 'Car ta servante est pieuse; elle sert nuit et jour le Dieu du ciel; et maintenant, je demeurerai auprès de toi, ô mon maître, et ta servante ira chaque nuit dans le val lon, et je prierai Dieu, et il me dira quand ils commettront leurs péchés. Et je viendrai te le rapporter; tu sortiras avec toutes tes forces, et nul chez eux ne te tiendra tête. Et je serai ton guide au cœur de la Judée jusqu’à ce que je t’aie conduit devant Jérusalem, et je placerai ton trône dans son enceinte, et tu les emmèneras comme des brebis qui n’ont point de pasteur. Et pas un chien devant toi ne grondera de la langue, car tout cela m’a été dit par ma prévoyance, tout cela m’a été dévoilé, et je te suis envoyée pour te le faire connaître. Et ce discours fut agréable à Holopherne et à ses serviteurs, et ils admirèrent sa sagesse, et ils dirent: D’une extrémité de la terre à l’autre il n’est point une pareille femme pour la beauté du visage et pour le grand sens des paroles. Et Holopherne lui dit: Dieu a bien fait de t’envoyer avant ton peuple, pour que la victoire soit entre nos mains, et pour la perdition de ceux qui ont méprisé mon maître. Tu es attrayante par ta beauté, tu es bonne en toutes tes paroles; et, si tu fais comme tu as dit, ton Dieu sera pour moi un Dieu; tu demeureras dans le palais du roi Nabuchodonosor, et ta renommée se répandra par toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Et il ordonna qu’on la menât dans la tente où ses vases d’argent étaient déposés, et qu’on lui servit de ses mcts, et qu’elle bût de son vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Et Judith lui dit: Je n’en mangerai pas, de peur qu’ils ne nous soient à scandale: on me servira de ceux que j’ai apportés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Et Holopherne lui dit: Mais, lorsque ceux qui sont avec toi viendront à manquer, d’où en apporterons-nous de semblables pour te les donner; car il n’y a parmi nous personne de ta nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Et Judith reprit: Vive ta vie! ô mon maître, ta servante n’aura pas consommé ceux qui sont avec moi, avant que le Seigneur n’ait accompli, par ma main, ce qu’il a décidé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Et les serviteurs d’Holopherne l’introduisirent sous la tente, et elle sommeilla jusqu’au milieu de la nuit, et elle se leva à la veillée du matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Et elle envoya à Holopherne, disant: Que mon maître ordonne qu’on laisse ta servante sortir pour qu’elle aille faire sa prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Et Holopherne prescrivit à ses gardes de ne la point retenir, et elle passa trois jours dans le camp; et, chaque nuit, elle alla au ravin de Béthulie, et elle fit ses ablutions dans la fontaine des eaux que renfermait le camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Et, lorsqu’elle était revenue, elle priait le Seigneur Dieu d’Israël de la diriger dans la voie, pour le salut des fils de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'Et, étant rentrée pure, elle se tenait sous la tente jusqu’à ce que sur le soir on lui apportât sa nourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 10, 'Or, le quatrième jour, Holopherne fit un festin à ses serviteurs seuls, et il n’invita, à cette fête habituelle, aucun de ses convives accoutumés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 11, 'Et il dit à Bagoa, l’eunuque qui était placé au-dessus de tous ses esclaves: Va trouver cette femme d’Hébreu, qui est sous ta garde, persuade-lui de se rendre auprès de nous, et de manger et de boire avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 12, 'Car c’est pour nous une honte d’être aussi près d’une telle femme, et de n’avoir point commerce avec elle; et, si nous ne l’obtenons, on se rira de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 13, 'Et Bagoa, quittant Holopherne, entra près de Judith, et lui dit: Que cette belle jeune fille ne craigne pas de venir auprès de mon maître pour être honorée devant lui; elle boira joyeusement avec nous du vin, et, ce jour-ci, elle sera comme l’une des filles d’Assur qui se tiennent dans le palais de Nabuchodonosor;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 14, 'Et Judith répondit: Et qui suis-je moi, pour contredire mon maître? Tout ce qui sera agréable à ses yeux, je m’empresserai de le faire, et ce sera ma joie jusqu’au jour de ma mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 15, 'Et, s’étant levée, elle se para de ses beaux vêtements et de tous ses ornements de femme, et sa servante la précéda; et, pour elle, elle étendit à terre, en face d’Holopherne, les toisons à leur usage journalier, qu’elles avaient empruntées de Bagoa, et sur lesquelles elles se couchaient pour manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 16, 'Et Judith, étant entrée, s’y plaça, et le cœur d’Holopherne à son aspect fut troublé, et son âme en fut vivement agitée, et il nourrissait un désir violent de la posséder; et, depuis le jour où elle lui était apparue, il épiait l’occasion de la séduire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 17, 'Et Holopherne lui dit: Bois donc, et, avec nous, tiens-toi en joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 18, 'Et Judith répondit: Certes, je boirai, ô mon maître; car je me sens aujourd’hui plus glorieuse de vivre que je ne l’ai jamais été depuis ma naissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 19, 'Et elle prit, et elle mangea devant lui ce que sa servante lui avait préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Sur le soir, ses esclaves s’empressèrent de partir, et Bagoa ferma la tente en dehors, et il renvoya tous ceux qui se tenaient ordinairement auprès du maître, et ils allèrent se coucher; car ils étaient tous accablés, parce que le festin avait été des plus abondants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Judith demeura seule sous la tente avec Holopherne qui était étendu sur sa couche, le vin ruisselant autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Et Judith dit à sa servante de se tenir hors du lieu où elle couchait, et d’épier sa sortie, comme chaque jour; car elle avait dit qu’elle irait faire sa prière, et elle en avait parlé à Bagoa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Ils s’étaient donc tous éloignés de la présence du maître, et nul, du petit au grand, n’était resté sous le pavillon où il couchait. Alors, Judith, debout près du lit, dit en son cœur: Seigneur Dieu des armées, regardez en cet instant les œuvres de mes mains pour l’exaltation de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'C’est maintenant le temps de ressaisir votre héritage, et de faire ce que j’ai prémédité pour la ruine des ennemis qui se sont élevés contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Et s’étant approchée de la colonne du lit qui était au-dessus de la tête d’Holopherne, elle en décrocha son cimeterre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 7, 'Et elle se pencha sur le lit, et saisit les cheveux d’Holopherne, et elle dit: En ce jour fortifiez-moi, Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 8, 'Et elle le frappa deux fois au cou de toute sa force, et elle lui trancha la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 9, 'Et elle fit rouler le corps au bas de la couche, et elle enleva le moustiquaire suspendu aux colonnes, et aussitôt elle sortit, et elle donna à sa servante la tête d’Holopherne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 10, 'Et celle-ci la mit dans leur sac aux vivres, et elles sortirent ensemble, selon leur habitude; et, après avoir traversé le camp, elles firent le tour du ravin, et elles remontèrent la montagne de Béthulie, et elles arrivèrent aux portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 11, 'Et Judith cria de loin aux sentinelles: Ouvrez, ouvrez donc la porte, Dieu, notre Dieu, est avec nous, pour montrer encore sa force en Israël, et sa puissance contre ses ennemis, comme il a fait aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 12, 'Et lorsque les hommes de la ville eurent ouï sa voix, ils se hâtèrent de descendre auprès de la porte, et convoquèrent les anciens de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 13, 'Et tout le monde accourut, du petit au grand, car ils ne s’attendaient pas à son retour, et ils ouvrirent la porte, et ils les firent entrer, et, ayant allumé un grand feu, ils les entourèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 14, 'Et Judith leur dit à haute voix: Louez Dieu, louez-le; louez Dieu qui n’a point détourné sa miséricorde de la maison d’Israël, mais qui, cette nuit même, a brisé nos ennemis par ma main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 15, 'Et tirant du sac la tête, elle la leur montra, et elle dit Voici la tête d’Holopherne, général en chef de l’armée d’Assyrie, et voici le filet sous lequel il dormait lorsqu’il était ivre, et le Seigneur l’a frappé par la main d’une femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 16, 'Et vive le Seigneur qui m’a gardée en la voie où j’ai marché! car mon visage a trompé cet homme à sa perdition, et il n’a point fait avec moi de péché qui me souille et me déshonore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 17, 'Et tout le peuple fut en grande extase; et, s’étant prosternés, ils adorèrent Dieu, et ils crièrent tout d’une voix: Béni soyez-vous, ô notre Dieu, qui avez aujourd’hui avili les ennemis de votre peuple!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 18, 'Et Ozias lui dit: Bénie sois-tu, ma fille, par le Dieu très-haut, entre toutes les femmes qui existent sur la terre! Béni soit le Seigneur Dieu, créateur de la terre et du ciel, parce qu’il t’a dirigée pour frapper la tête du prince de nos ennemis!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 19, 'Et jamais l’espoir que tu as eu en Dieu ne s’effacera du cœur des hommes, qui se souviennent de la puissance de Dieu dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 20, 'Que le Seigneur te bénisse et t’exalte à jamais; qu’il te visite pour ton bien en récompense de ce que tu n’as pas ménagé ta vie, devant l’humiliation de notre race; mais tu es allée au-devant de notre chute, et tu as marché droit devant notre Dieu. Et le peuple tout entier s’écria: Ainsi soit-il, ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Et Judith leur dit: Écoutez-moi, frères, prenez cette tête, et suspendez-la aux créneaux de nos remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Et, aux premières lueurs du matin, quand le soleil se lèvera sur la terre, que chacun prenne les armes, que l’on nomme un chef, que tout homme fort sorte de la ville, comme pour descendre sur la garde avancée des Assyriens; mais vous ne descendrez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Ceux-ci, après s’être couverts de leurs armures, se replieront sur le camp, et ils réveilleront les généraux de l’armée d’Assur, et ils courront tous ensemble à la tente d’Holopherne, et ils ne le trouveront pas, et l’épouvante tombera sur eux, et ils s’enfuiront devant nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Alors, courant après eux, vous et tout ce qui habite le territoire d’Israël, renversez-les sur leurs chemins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Mais, avant de faire cela, appelez-moi Achior l’Ammonite, afin qu’ayant vu, il reconnaisse celui qui méprisait la maison d’Israël, et qui l’avait lui-même envoyé parmi nous comme à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'On fit donc venir Achior de la maison d’Ozias. Dès qu’il fut arrivé et qu’il eut vu la tête d’Holopherne à la main d’un homme de l’assemblée du peuple, il tomba la face contre terre, et le souffle lui manqua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Lorsqu’on l’eut fait revenir à lui, il se jeta aux pieds de Judith et il l’adora, et il dit: Bénie sois-tu en toute demeure de Juda et en toute nation! quiconque ouïra ton nom sera ému.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 8, 'Raconte-moi maintenant tout ce que tu as fait en ces derniers jours. Et Judith lui raconta, au milieu de tout le peuple, ce qu’elle avait fait depuis sa sortie jusqu’au moment où elle parlait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 9, 'Dès qu’elle eut terminé son récit, le peuple applaudit à haute voix, et des cris d’allégresse retentirent dans toute la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 10, 'Et Achior, ayant vu tout ce qu’avait fait le Dieu d’Israël, crut en lui avec ferveur, et il se fit circoncire, et il a été compté parmi la maison d’Israël jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 11, 'Dès les premières lueurs du matin, on suspendit aux remparts la tête d’Holopherne; et chaque homme. d’Israël prit les armes, et ils descendirent par cohortes la rampe de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 12, 'Et les fils d’Assur les virent, et ils envoyèrent des gens à leurs chefs. Or, ceux-ci allèrent trouver les généraux, les commandants de mille hommes, et tous leurs princes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 13, 'Qui s’approchèrent de la tente d’Holopherne, et dirent à celui qui était au-dessus de ses serviteurs: Éveille notre maître, car nos esclaves osent descendre pour nous attaquer, et pour que nous les exterminions enfin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 14, 'Et Bagoa entra, et il agita la portière de la tente, car il croyait son maître endormi avec Judith.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 15, 'Et, comme nul ne l’entendit, il ouvrit et pénétra dans le pavillon, et il trouva Holopherne étendu mort au pied du lit, et sa tête avait été enlevée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 16, 'Et il jeta les hauts cris, avec pleurs et sanglots, et il déchira ses vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 17, 'Et il courut à la tente où logeait Judith, et il ne la vit pas, et il s’élança vers la troupe en criant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 18, 'Les esclaves se sont révoltés; une femme des Hébreux a fait entrer la honte en la maison de Nabuchodonosor. Voilà qu’Holopherne gît à terre, et sa tête a été enlevée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 19, 'Lorsqu’ils eurent ouï ces paroles, les chefs de l’armée d’Assur déchirèrent leurs tuniques, et leur âme fut grandement troublée, et leurs cris et hautes clameurs se firent entendre au milieu du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Et lorsque ceux qui étaient sous les tentes l’ouïrent, ils furent hors d’eux-mêmes de ce qui venait d’arriver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Et la terreur et l’effroi tombèrent sur eux, et il n’y eut pas un homme qui restât ferme en présence de son voisin; et, s’étant dispersés tous à la fois, ils s’enfuirent par tous les chemins de la plaine et des montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Et ceux qui étaient campés autour de Béthulie, sur les hauteurs, prirent pareillement la fuite. Alors, tous les guerriers d’Israël se répandirent contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Et Ozias envoya des messagers à Bétomasthem, à Hobaï, à Hola et dans toute la contrée montagneuse d’Israël, publiant ce qui s’était accompli, afin que tous se missent à la poursuite des fugitifs pour les anéantir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Lorsque les fils d’Israël ouïrent ces nouvelles, tous, comme un seul homme, tombèrent sur eux, et ils les taillèrent en pièces jusqu’à Hobra; ceux de Jérusalem survinrent aussi de toutes les montagnes; car on leur avait appris ce qui était advenu dans le camp des ennemis. Galaad et la Galilée les enveloppèrent et leur firent de grandes plaies, jusqu’à ce qu’ils eussent dépassé Damas et son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 6, 'Cependant, ceux qui étaient restés à Béthulie tombèrent sur le camp d’Assur, le pillèrent et s’enrichirent beaucoup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 7, 'Et les fils d’Israël, revenant sur leurs pas, se rendirent maîtres de ce qui leur était échappé, et ils firent un immense butin dans les villages et dans les maisons des champs de la plaine et de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 8, 'Et le grand prêtre Joacim et les anciens des fils d’Israël, qui résidaient à Jérusalem, vinrent pour contempler le bien que le Seigneur avait fait à Israël, et pour voir Judith, et pour lui apporter des paroles de paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 9, 'Lorsqu’ils entrèrent chez elle, ils la bénirent tout d’une voix, et lui dirent: Tu es la gloire d’Israël, tu es la joie d’Israël, tu es l’orgueil de notre race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 10, 'Tu as fait de ta main toutes ces choses; tu as fait ces bonnes choses pour Israël; que Dieu se complaise en toi plus qu’en aucun du peuple. Bénie sois-tu à jamais par le Seigneur tout-puissant! Et tout le peuple s’écria: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 11, 'Et tout le peuple pilla le camp pendant trente jours, et ils donnèrent à Judith la tente d’Holopherne, toute son argenterie, ses lits, ses cratères et tous ses vases. Et, les ayant pris, elle les mit sur sa mule, ou elle attela ses chariots, et les y entassa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 12, 'Et toutes les femmes d’Israël accoururent pour la voir, et elles la bénirent, et elles formèrent pour elle un chœur de danses; et elle prit en ses mains des thyrses, et elle les donna aux femmes qui étaient avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 13, 'Et on couronna d’olivier elle et ses femmes. Et l’on vint de tout le peuple prendre part à la danse que menaient toutes les femmes, et les hommes d’Israël, en armes, couronnés aussi, les accompagnèrent de leurs chants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Et Judith entonna ce cantique de louanges au milieu de tout Israël, et tout le peuple le répéta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Et Judith dit: Préludez, pour mon Dieu, au son des tambours; chantez, pour le Seigneur, au son des cymbales; chantez pour lui, en mesure, un psaume nouveau; exaltez et invoquez son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Car le Seigneur est le Dieu qui broie les armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Et dans son camp, au milieu du peuple, il m’a arrachée de la main de ceux qui me poursuivaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Assur est venu des montagnes de l’aquilon; il est venu avec les myriades de son armée; leur multitude a comblé les vallons, leur cavalerie a couvert les collines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Il avait juré de livrer mon pays à la flamme, de faire périr mes jeunes hommes par le glaive, d’écraser mes enfants à la mamelle, de faire de mes enfants un butin, et de mes vierges une proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Le Seigneur tout-puissant les a effacés par la main d’une femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Car leur homme puissant n’est pas tombé sous les coups de jeunes guerriers; les fils des Titans ne l’ont point frappé, les grands géants ne l’ont point attaqué; mais Judith, fille de Mérari, l’a défait par la beauté de son visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Elle a ôté sa robe de veuve pour l’exaltation des affligés d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Elle a parfumé de myrrhe son visage, et a noué ses cheveux sous un turban; elle a pris une robe de lin pour le tromper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Sa petite sandale a ravi son œil, sa beauté a captivé son âme; le cimeterre a tranché sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 12, 'Les Perses ont frémi de l’audace d’une femme, et les Mèdes ont été brisés par sa hardiesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 13, 'Alors mes humbles ont jeté un cri de joie, et mes faibles les ont épouvantés, et ils ont été frappés de stupeur; ils ont élevé la voix, et ils ont pris la fuite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 14, 'Les enfants des jeunes femmes les ont percés, ils les ont blessés comme des esclaves fugitifs; le Seigneur leur a livré bataille, et ils ont péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 15, 'Je chanterai à Dieu un hymne nouveau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 16, 'Seigneur, vous êtes grand et glorieux; votre force émerveille; vous êtes invincible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 17, 'Que toutes vos créatures vous servent; car vous avez dit, et elles ont été; vous avez envoyé votre Esprit, et il a édifié, et il n’est personne qui n’obéisse à votre voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 18, 'Car les montagnes seront ébranlées à partir de leurs racines, en même temps que les eaux; et les rochers devant vous fondront comme de la cire, et vous êtes propice à ceux qui vous craignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 19, 'Tout sacrifice qu’on vous offre en odeur de suavité est petit; toute la graisse de vos holocaustes est très-petite; mais, celui qui craint le Seigneur est toujours grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 20, 'Malheur aux peuples qui s’attaquent à ma race! le Seigneur tout-puissant, au jour du jugement, les punira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 21, 'Il livrera leur chair aux vers et à la flamme, et ils pleureront en une souffrance éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 22, 'Lorsque le peuple rentra à Jérusalem, il adora Dieu; et, aussitôt qu’il se fut purifié, il offrit ses holocaustes, ses sacrifices volontaires et ses dons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 23, 'Et Judith consacra, comme offrande au Seigneur, tous les vases d’Holopherne, que lui avait donnés le peuple, et le moustiquaire qu’elle avait enlevé de sa couche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 24, 'Et le peuple passa trois mois en réjouissances à Jérusalem, devant les lieux saints, et Judith demeura avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 25, 'Ce temps écoulé, chacun s’en retourna à son héritage; et Judith, à Béthulie, où elle demeura sur ses biens; et elle fut, toute sa vie, pleine de gloire en toute la terre. Et beaucoup la désirèrent, et nul homme ne la connut, durant tous les jours de sa vie, depuis qu’elle eut perdu Manassès son mari; et elle fut réunie à son peuple. Et elle paraissait au dehors avec beaucoup de gloire. Et elle vieillit dans la maison de son époux jusqu’à cent cinq ans; et elle avait affranchi sa servante, et elle mourut à Béthulie, et on l’ensevelit dans la caverne de Manassès, son époux. Et la maison d’Israël la pleura sept jours, et, avant de mourir, elle avait partagé ses richesses entre tous les proches de Manassès et ceux de sa propre famille. Et nul n’effraya encore les fils d’Israël tant que vécut Judith, ni bien des jours après sa mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Livre des paroles de Tobit, fils de Tobiel, fils d’Ananiel, fils d’Aduel, fils de Gabaël, de la race d’Asiel, de la tribu de Nephthali,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Qui fut emmené captif, du temps d’Enemessar, roi d’Assyrie; de Thisbès qui est à droite de Cydios en Nephthali, dans la Galilée, au-dessus d’Aser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Moi, Tobit, j’ai marché dans les voies de la vérité et de la justice, tous les jours de ma vie, et j’ai fait beaucoup d’aumônes à mes frères et à mon peuple, partis avec moi pour Ninive en Assyrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Et lorsque j’étais dans mon pays en la terre d’Israël, enfant encore, tout Nephthali, la tribu de mon père, se sépara du temple de Jérusalem, ville choisie entre toutes les tribus d’Israël, pour que toutes y vinssent sacrifier. Or, le temple où résidait le Très-Haut avait été sanctifié, et il avait été bâti pour toutes les générations, à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Et toutes les tribus qui s’en étaient séparées sacrifiaient à Baal et à la génisse; et Nephthali, la tribu de mon père, aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Et moi seul j’allai bien des fois à Jérusalem les jours de fête, selon qu’il est écrit pour tout le peuple en la loi éternelle, portant avec moi les prémices et les dîmes des');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Je donnais la dîme aux fils de Lévi, employés à Jérusalem; et je vendais la seconde dîme, et je m’en allais, et j’en dépensais le prix à Jérusalem tous les ans,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Et je donnais la troisième dîme à qui je devais la donner, pour obéir aux ordres de Débora, mère de mon père; car mon père m’avait laissé orphelin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Et quand je fus un homme, j’épousai Anne, de la tribu de mon père, et j’eus d’elle Tobie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Et lorsque je fus emmené captif à Ninive, tous mes frères, et ceux de ma race, mangeaient de tous les aliments des gentils;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Et moi je gardais mon âme pour n’en point manger,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Me souvenant de Dieu de toute mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Et le Très-Haut me donna grâce et beauté devant Enemessar, et je fus pourvoyeur de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Et j’allai en Médie, et je déposai dix talents d’argent entre les mains de Gabaël, frère de Gabrias, à Ragès en Médie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Et lorsque Enemessar mourut, Sennachérib, son fils, régna à sa place; et ses voies furent mauvaises, et je ne pus continuer d’aller en Médie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Et, du temps d’Enemessar, j’avais fait beaucoup d’aumônes à mes frères:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'J’avais donné de mes pains aux affamés, de mes vêtements aux nus, et, si je voyais le cadavre de l’un de mes frères gisant derrière les murailles de Ninive, je l’ensevelissais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Et si Sennacherib, après qu’il fut revenu de la Judée en fugitif, faisait périr l’un d’eux, je l’ensevelissais à la dérobée. Car, dans sa fureur, il en tua beaucoup; et lorsque le roi fit chercher leurs corps, on ne les trouva plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Et l’un de ceux de Ninive s’en alla dénoncer au roi que c’était moi qui les inhumais, et je me cachai; mais ayant appris que l’on me cherchait pour me mettre à mort, j’eus peur, et je m’éloignai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Et tous mes biens furent pillés, et il ne me resta rien que ma femme Anne et mon fils Tobie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Or, cinquante jours n’étaient point passés, que deux de ses fils le tuèrent, et ils se réfugièrent au mont Ararat; et Sacherdon, son fils, régna à sa place, et il mit à la tête des finances royales Achiachare, fils de mon oncle Anaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Et Achiachare réclama en ma faveur, et je revins à Ninive. Or, Achiachare était échanson, garde du scel royal, intendant et maître des comptes, et il avait la seconde place du royaume, et il était mon cousin germain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Après mon retour à ma maison, quand ma femme Anne et mon fils Tobie m’eurent été rendus, vint la fête du cinquantième jour, qui est sanctifié à la fin des sept semaines, et il y eut chez moi un beau festin, et je me mis à table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Et, apercevant quantité d’aliments, je dis à mon fils: Va, et amène-moi le premier de nos frères indigents que tu pourras trouver, pourvu qu’il se souvienne du Seigneur; tu vois, je t’attends.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Et il rentra, et il dit: Père, un homme de notre peuple gît étranglé sur la place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Et moi, avant de goûter de rien, je ne fis qu’un saut, et je l’emportai dans la maison pour le garder jusqu’au coucher du soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Après cela, je me lavai, et je pris mon repas dans la tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Et je me souvins de la prophétie d’Amos, lorsqu’il a dit: Vos fêtes se changeront en deuil, et toutes vos joies en lamentations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Et je pleurai, et, lorsque le soleil fut couché, je m’en allai creuser une fosse, et j’inhumai mon frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Et mes voisins me raillèrent, disant: Il ne craint donc plus d’être mis à mort pour ce sujet? il s’est déjà enfui, et le voilà qui se remet à ensevelir les morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Et cette nuit même, quand j’eus achevé la sépulture, comme j’étais souillé, je me couchai contre le mur de ma cour; or, j’avais le visage découvert;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Et je ne savais pas qu’il y eût des passereaux dans le mur; et, comme mes yeux étaient ouverts, les passereaux firent tomber sur mes yeux leur fiente chaude, et il me vint des taies aux yeux; et j’allai aux médecins, et ils ne me servirent de rien, et Achiachare me nourrit jusqu’à ce que je partisse pour l’Elymaïs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Cependant, ma femme Anne alla travailler la laine dans les gynécées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Et elle envoya son travail aux maîtres qui, en retour, lui donnèrent un salaire, auquel ils ajoutèrent un chevreau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Or, lorsqu’elle revint vers moi, il se mit à crier, et je lui dis D’où vient ce chevreau? N’est-il pas volé? Rends-le à ses maîtres, car il n’est pas juste de manger ce que l’on dérobe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Et elle répondit: On me l’a donné outre mon salaire. Et je ne la crus pas, et je lui dis de le reporter aux maîtres, et je rougis d’elle. Et elle reprit: Où sont tes aumônes et tes œuvres de justice? Comme elles se révèlent toutes en toi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Et, le cœur contristé, je versai des larmes, et je priai dans ma douleur, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Vous êtes juste, ô Seigneur; toutes vos voies, toutes vos œuvres sont miséricorde et vérité; et vous jugez avec vérité et justice dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Souvenez-vous de moi, jetez sur moi vos regards; ne me punissez pas de mes péchés, ni de mes inadvertances, ni des péchés que mes pères ont commis devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Car ils ont désobéi à vos commandements, et vous nous avez livrés au pillage, à la captivité, à la mort, et nous sommes la fable et le jouet de toutes les nations chez qui vous nous avez dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Mais vos jugements sont nombreux et irréprochables; ils peuvent me traiter selon mes péchés et ceux de mes pères, parce que nous n’avions point été fidèles à votre loi, et que nous n’avions point marché devant vous dans la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Faites donc de moi ce que bon vous semble; ordonnez que le souffle me soit ôté, que je sois affranchi, que je devienne terre; car, mieux vaut pour moi mourir que vivre, puisque j’ai subi d’injustes reproches et qu’il est en moi une grande tristesse; ordonnez donc que dès maintenant je sois délivré de mes maux pour entrer dans le lieu éternel; ne détournez point de moi votre face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Or, ce même jour-là, il advint que Sara, fille de Raguel, d’Ecbatane en Médie, fut outragée par les servantes de son père,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Parce qu’elle avait été mariée à sept hommes, et que le mauvais démon Asmodée les avait tous fait périr avant qu’ils eussent été avec elle comme avec une femme. Et les servantes lui dirent: Ne vois-tu pas que c’est toi qui suffoques ces hommes? Tu en as eu déjà sept, et il n’en est pas un seul dont tu portes le nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Pourquoi nous fouettes-tu? Puisqu’ils sont morts, va les rejoindre; que jamais nous ne voyions de toi ni fils ni fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'A ces paroles, elle ressentit une douleur violente jusqu’à penser à s’étrangler; mais elle dit: Mon père n’a que moi si je fais cela, je serai son opprobre; et, de tristesse, je conduirai sa vieillesse au tombeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Et elle pria devant sa fenêtre, et elle dit: Béni soyez-vous, ô Seigneur mon Dieu; béni soit dans tous les siècles votre nom glorieux et saint; que toutes vos œuvres vous bénissent à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Et maintenant, Seigneur, je tourne vers vous mes yeux et mon visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'J’ai dit: Délivrez-moi des liens de cette terre; que je n’entende plus de tels outrages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Vous savez, Seigneur, que je suis pure de tout péché avec l’homme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Et que je n’ai point souillé, en cette terre de la captivité, mon nom ni le nom de mon père. Je suis fille unique, et mon père n’a point de fils pour recueillir son héritage, ni de proche parent qui ait un fils auquel je doive me réserver pour être sa femme, et déjà j’ai perdu sept maris. Pourquoi vivrais-je encore? Et s’il ne vous plaît pas de me faire mourir, ordonnez que l’on me considère, que l’on ait compassion de moi, que je n’entende plus de pareils outrages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Or, les prières de tous les deux furent entendues en même temps devant la gloire du grand Raphaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Et il fut envoyé pour guérir les deux affligés: pour enlever les taies de Tobit, pour donner en mariage à Tobie, fils de Tobit, Sara, fille de Raguel, et pour enchaîner Asmodée le mauvais démon; car c’est à Tobie qu’elle devait appartenir. Au même instant Tobit entra dans sa maison; et Sara, fille de Raguel, descendit de sa chambre à coucher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'En ces jours-là, Tobit se souvint de l’argent qu’il avait déposé chez Gabaël, à Ragès en Médie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Et il se dit: J’ai demandé la mort: pourquoi ne pas appeler mon fils Tobie, afin, qu’avant de mourir, je lui prescrive ce qu’il aura à faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Et, l’ayant appelé, il lui dit: Mon enfant, si je meurs, ensevelis-moi, et ne méprise pas ta mère: honore-la tous les jours de ta vie, fais ce qui lui sera agréable, et garde-toi de l’affliger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'N’oublie pas, mon enfant, les nombreux dangers qu’elle a courus, à cause de toi, quand tu étais dans ses entrailles; lorsqu’elle mourra, ensevelis-la, à mes côtés, dans le même sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Tous les jours, mon enfant, souviens-toi du Seigneur ton Dieu, ne consens pas à pécher ni à transgresser ses commandements. Fais la justice toute ta vie, et ne marche jamais dans les voies de l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Car, si tu fais la vérité, le succès s’en suivra en tous dont tes travaux, comme il advient à tous ceux qui font la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Donne en aumône une part de tes biens, et que ton œil ne te porte pas envie lorsque tu feras l’aumône. Ne détourne pas ton visage du mendiant, et le visage de Dieu ne se détournera pas de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Si tu as abondance de richesses, fais l’aumône en conséquence; si tu possèdes peu, ne crains pas de donner en aumône une part de ce peu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Ainsi, tu t’amasseras un trésor précieux pour le jour de la nécessité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Car l’aumône délivre de la mort; elle empêche qu’on n’entre dans les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'L’aumône est un précieux présent devant le Très-Haut, pour tous ceux qui la font.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Veille, mon enfant, sur toi-même pour ne t’adonner à aucune prostitution; et, d’abord, prends femme en la race de tes pères; n’épouse pas une femme étrangère qui ne serait pas de la tribu de ton père, car nous sommes fils des prophètes; Noé, Abraham, Isaac, sont nos premiers pères. N’oublie pas, mon enfant, qu’ils ont toujours pris femme parmi leurs frères; aussi, ils ont été bénis en leurs enfants, et leur postérité héritera de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Maintenant donc, mon enfant, aime tes frères, et ne va pas, dans l’orgueil de ton cœur, te détourner de tes frères, des fils et des filles de ton peuple, et dédaigner de prendre femme chez eux; car l’orgueil entraîne le désordre extrême et la perdition, la vanité entraîne l’abaissement et la grande pénurie, la vanité est la mère de la faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Que le salaire de l’homme, qui aura travaillé pour toi, ne demeure point chez toi la nuit, donne-le-lui sur-le-champ. Dieu te paiera de même si tu le sers. Veille sur toi-même, mon enfant, dans toutes tes œuvres, et sois discipliné en toutes tes démarches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Et ce que tu hais, ne le fais à personne; ne bois pas de vin jusqu’à t’enivrer, et que jamais l’ivresse ne marche avec toi dans ton chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Donne de tes mets aux affamés, et de tes vêtements');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Distribue ton pain sur la tombe des justes, n’en donne pas aux pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Prends conseil de tout homme sensé, et ne dédaigne aucun avis salutaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'En tout temps, bénis le Seigneur Dieu, et demande-lui que tes voies soient droites, que tous tes sentiers et toutes tes résolutions te mènent à bien. Car nulle nation ne possède le conseil, et c’est le Seigneur qui donne tous les biens; il humilie qui il veut et comme il veut. Et maintenant, mon enfant, souviens-toi de mes préceptes, et qu’ils ne s’effacent jamais de ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Je t’indique aujourd’hui les dix talents d’argent que j’ai déposés chez Gabaël, frère de Gabrias, à Ragès en Médie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'N’aie point crainte, mon enfant, de ce que nous sommes devenus pauvres; tu possèdes beaucoup si tu crains Dieu, si tu te détournes du péché, si tu fais ce qui est agréable au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Et Tobie répondit: Père, je ferai tout ce que tu m’as recommandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Mais, comment pourrai-je recevoir l’argent? Je ne connais point l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Et son père lui remit la cédule, et il lui dit: Cherche quelqu’un qui t’accompagne, et je lui donnerai un salaire, si je vis encore; et toi, va recevoir l’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Et il sortit pour chercher un homme, et il trouva Raphaël, qui était un ange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Mais il ne le savait pas, et il lui dit: Puis-je aller avec toi à Ragès en Médie, et connais-tu le pays?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Et l’ange lui répondit: Je partirai avec toi, et je sais le chemin; j’ai même séjourné chez mon frère Raguel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Et Tobie reprit Attends-moi, je vais le dire à mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Et l’ange lui dit: Va, et ne sois pas longtemps. Et, étant rentré, Tobie dit à son père: Voilà que j’ai trouvé quelqu’un pour venir avec moi. Et Tobit répondit: Appelle-le près de moi, que je sache de quelle tribu il est, et s’il y a sûreté à voyager avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Et il l’appela, et l’ange entra, et ils se saluèrent mutuellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Et Tobit lui dit: Frère, de quelle tribu et de quelle famille paternelle es-tu? Fais-le-moi connaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Et l’ange répondit: Est-ce ma tribu et ma famille que tu demandes, ou bien un serviteur qui aille avec ton fils? Et Tobit reprit: Je désire, frère, connaître ta famille et ton nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Et l’ange dit: Je suis Azarias, fils du grand Ananias, l’un de tes frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Et Tobit dit: Sois le bienvenu, frère, et ne te fâche pas de ce que j’ai demandé à connaître ta tribu et ta famille; il se rencontre que tu es mon frère, et que tu sors d’une belle et bonne maison. Car j’ai connu Ananias et Jonathas, fils de Sémeï le Grand, lorsque nous allions ensemble adorer à Jérusalem, et offrir la dîme de nos récoltes et les premiers-nés de nos troupeaux; ils ne tombaient point dans l’égarement de nos frères; frère, tu es d’une bien bonne souche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Mais dis-moi quel salaire j’aurai à te donner? Une drachme par jour, et ce qui sera nécessaire à toi comme à mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Et j’ajouterai encore à ta récompense, si vous revenez sains et saufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Et il leur plut ainsi; et Tobit dit à son fils: Disposetoi à partir, et bon succès. Et Tobie prépara ce qu’il lui fallait pour la route, et son père lui dit: Va avec cet homme, et que Dieu, qui habite le ciel, vous guide en chemin, que son ange vous guide en chemin. Et ils sortirent tous les deux, et le chien du jeune homme le suivit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Or, Anne, sa mère, pleura, et elle dit à Tobit: Pourquoi as-tu envoyé là notre enfant? N’est-ce point le bâton sur lequel s’appuyaient nos mains, quand il allait et venait devant nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Puisse cet argent ne plus avoir cours; puisse-t-il être changé en l’ordure de notre fils!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Ce que le Seigneur nous avait donné pour vivre nous suffisait bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Et Tobit lui dit: N’aie pas d’inquiétude, ma sœur, il reviendra sain et sauf, et tes yeux le verront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Car un bon ange l’accompagne, et son voyage réussira, et il reviendra sain et sauf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Et elle cessa de pleurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Et, poursuivant leur route, les voyageurs arrivèrent le soir sur les bords du Tigre, et ils y passèrent la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Or, le jeune homme descendit pour se baigner, et un poisson s’élança hors du fleuve, et il voulut dévorer le jeune homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Mais l’ange lui dit: Saisis-toi du poisson. Et le jeune homme saisit le poisson, et il le jeta sur la rive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Et l’ange lui dit: Ouvre le poisson, prends-en le cœur, le foie et le fiel, et conserve-les avec soin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Et le jeune homme fit ce que lui avait dit l’ange; puis, ayant fait rôtir le poisson, ils en mangèrent; ensuite, ils marchèrent, l’un et l’autre, jusqu’aux portes d’Ecbatane.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Et, en marchant, le jeune homme dit à l’ange: Frère Azarias, à quoi servent le cœur, le foie et le fiel du poisson?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Et l’ange répondit: Si quelqu’un, homme ou femme, est tourmenté par un démon ou un malin esprit, il faut brûler le cœur et le foie devant lui, et il ne sera plus tourmenté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Et si avec le fiel on oint un homme qui a des taies aux yeux, il sera guéri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Auprès de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'L’ange dit au jeune homme: Frère, nous passerons cette nuit chez Raguel, qui est de ta famille, et a une fille qu’on appelle Sara; je lui parlerai d’elle, afin qu’il te la donne pour femme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'L’héritage de Sara te revient, car tu es le seul de sa famille, et la jeune vierge est belle et prudente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Suis mon conseil, et je parlerai à son père, et quand nous reviendrons de Ragès nous ferons le mariage. Je sais que Raguel ne la donnera pas à un homme autre que celui que prescrit la loi de Moïse; sinon il exposerait cet homme à la mort, car il t’appartient de recueillir son héritage à l’exclusion de tout autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Alors, le jeune homme dit à l’ange: Mon frère Azarias, j’ai ouï dire que la jeune fille a été donnée à sept maris, et que tous sont morts dans la chambre nuptiale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Or, je suis le seul enfant de mon père, et j’ai peur en l’épousant de mourir comme les premiers; car un démon l’aime, et il ne fait de mal à personne, sinon à ceux qui s’approchent d’elle. Et je crains de périr et de conduire au tombeau dans la tristesse la vie de mon père et de ma mère, et ils n’ont point d’autre fils pour les ensevelir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Et l’ange lui dit: Ne te souviens-tu pas que ton père t’a recommandé de prendre femme en ta famille? Écoute-moi donc, frère, car elle sera ta femme, et ne t’inquiète nullement du démon; cette nuit même elle te sera donnée pour femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Et quand tu entreras dans la chambre nuptiale, prends le brasier aux parfums: jette, sur la cendre chaude, le cœur et le foie du poisson, et réduis-les en fumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Et le démon en sentira l’odeur, et il s’enfuira, et il ne reviendra plus dans les siècles des siècles; lorsque tu viendras ensuite auprès de ta femme, restez levés tous les deux, et criez au Dieu de miséricorde, et il vous sauvera, et il aura compassion de vous. N’aie point crainte, elle t’est de tout temps destinée, et tu la sauveras, et elle te suivra, et j’espère que tu auras d’elle des enfants. Et, en entendant ces paroles, Tobie aima Sara, et son cœur s’attacha vivement à elle, et il entra dans Ecbatane.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Et il arriva devant la maison de Raguel, et Sara vint à sa rencontre; elle souhaita le bonjour au jeune homme, et son père à tous les deux; puis, il les introduisit en sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Et Raguel dit à Edna, sa femme: Comme ce jeune homme ressemble à mon cousin Tobit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Et Raguel leur fit cette question: D’où êtes-vous, frères? Et ils lui répondirent: Nous sommes des fils de Nephthali, de ceux qui sont captifs à Ninive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Et il reprit: Connaissez-vous mon frère Tobit? Et ils dirent: Nous le connaissons. Et il reprit: Est-il en bonne santé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Et ils répondirent: Il vit et se porte bien. Et Tobie ajouta: Il est mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Et il s’élança, et il le baisa, et il se prit à pleurer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Et il le bénit, et il s’écria: O fils d’un homme honorable et bon. Puis, apprenant que Tobit avait perdu la vue, il fut contristé, et il pleura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Et Edna, sa femme, et Sara, sa fille, pleurèrent; ensuite, ils leur firent l’accueil le plus empressé, ils sacrifièrent un bélier, et ils servirent des mets en abondance. Et Tobie dit à Raphaël: Frère Azarias, parle à Raguel de ce que tu m’as dit en chemin, et que l’affaire s’accomplisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Et Raphaël parla à Raguel, et celui-ci dit à Tobie: Mange et bois, et tiens-toi joyeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'I t’appartient d’épouser mon enfant; mais je te déclarerai la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'J’ai donné ma fille à sept maris, et, lorsqu’ils s’approchèrent d’elle, ils moururent pendant la nuit. Pour le moment, tiens-toi joyeux. Et Tobie reprit: Je ne goûterai de rien que vous ne vous leviez et décidiez en ma faveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Et Raguel lui dit: Prends-la dès maintenant, comme la loi le veut; tu es son frère, et elle est à toi; le Dieu de miséricorde pour vous mènera tout au mieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Et il appela Sara sa fille, et lui prenant la main il la donna pour femme à Tobie, et il dit: Emmène-la, selon la loi de Moïse, et conduis-la à ton père. Et il les bénit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Et il appela Edna sa femme, et prenant un livre il écrivit le contrat, et il y apposa son scel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Et ils commencèrent à manger,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Et Raguel rappela Edna sa femme, et il lui dit: Sœur, prépare une nouvelle chambre à coucher, et mènes-y Sara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Et elle la prépara comme il avait dit, et elle y fit entrer sa fille, qui se mit à pleurer. Et elle vit couler les larmes de sa fille, et elle lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Aie confiance, mon enfant; puisse le Seigneur du ciel et de la terre t’accorder sa grâce en échange de cette affliction; aie confiance, ma fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Lorsqu’ils eurent fini leur repas, ils conduisirent Tobie auprès d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Or, en marchant, il se souvint des paroles de Raphaël: il prit donc le brasier aux parfums, et il mit sur la cendre chaude le cœur et le foie du poisson, et il les réduisit en fumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Et dès que le démon sentit l’odeur, il s’enfuit au fond de la haute Égypte, où l’ange l’enchaîna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Lorsque les deux époux furent enfermés, Tobie se leva du lit, et il dit: Lève-toi, sœur, et prions, afin que le Seigneur ait pitié de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Et Tobie commença, disant: Béni soyez-vous, Dieu de nos pères, béni soit à jamais votre nom saint et glorieux; béni soyez-vous du ciel et de toute créature.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Vous avez fait Adam, et vous lui avez donné pour aide et pour appui Ève sa femme; c’est d’eux qu’est née la race des hommes; c’est vous qui aviez dit: Il n’est point bon que l’homme soit seul, faisons-lui un aide à son image.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Et maintenant, Seigneur, ce n’est point par concupiscence que j’épouse ma sœur que voici, mais en esprit de vérité; envoyez-moi votre miséricorde, faites que nous vieillissions ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Et Sara dit avec lui: Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Et ils dormirent ensemble la nuit, et Raguel, s’étant levé, sortit, et il creusa une fosse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'En se disant: Celui-là ne sera-t-il pas mort aussi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Et Raguel rentra dans sa maison,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Et il dit à Edna sa femme: Envoie l’une de tes servantes, que l’on s’assure s’il vit; sinon, nous l’inhumerons sans que personne le sache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Et la servante, ayant ouvert la porte, entra, et elle les trouva tous les deux endormis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Et elle descendit, et elle annonça qu’il était vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Et Raguel bénit Dieu, et il s’écria: Béni soyez-vous, ô Dieu, recevez toute bénédiction pure et sainte; que vos saints vous bénissent, et toutes vos créatures, et tous vos anges, et vos élus; qu’ils vous bénissent dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Béni soyez-vous, parce que vous m’avez réjoui, et que, au lieu de ce que je craignais, vous avez agi envers moi, selon votre inépuisable miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Béni soyez-vous, parce que vous avez eu compassion de deux enfants uniques tous les deux; accordez-leur, ô Maître, votre pitié; qu’ils achèvent leur vie en santé dans l’allégresse et la miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Et il ordonna à ses serviteurs de combler la fosse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Et il fêta leurs noces pendant quatorze jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Et Raguel les adjura de ne point partir que les deux semaines de noces fussent accomplies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Après quoi, dit-il, tu prendras la moitié de mes biens, et tu t’en retourneras sain et sauf auprès de ton père. Tu auras le reste, ajouta-t-il, après ma mort et celle de ma femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Et Tobie appela Raphaël, et il lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Frère Azarias, prends avec toi ton serviteur et deux chameaux; va à Ragès en Médie chez Gabaël; touche pour moi l’argent, et amène Gabaël à mes noces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Car Raguel m’a adjuré de ne point m’en aller;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Et mon père compte les jours, et si je tarde beaucoup, grande sera sa tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Et Raphaël partit, et il logea chez Gabaël, et il lui remit la cédule, et l’autre apporta les sacs qui étaient encore scellés, et il les lui livra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Et ils se levèrent tous deux de grand matin, et ils vinrent aux noces, et Tobie bénit sa femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Cependant, Tobit son père comptait les jours, et lorsque les jours du voyage furent accomplis, voyant qu’il ne revenait pas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Il dit Est-ce qu’il aurait été confondu? Ou bien Gabaël serait-il mort, et personne ne serait-il là pour rendre l’argent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Et il tomba dans une grande tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Et sa femme lui dit: L’enfant est mort, car le temps du retour est passé. Et elle commença à pleurer, et elle dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Je n’ai pas à me reprocher, mon enfant, de t’avoir congédié, toi la lumière de mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Et Tobit lui dit: Tais-toi, ne t’inquiète pas, il se porte bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Et elle reprit Tais-toi, ne m’abuse pas, mon enfant est mort. Et tous les jours elle allait sur la route par laquelle il était parti. Et le jour elle ne prenait pas de nourriture, et la nuit elle ne cessait pas de pleurer Tobie. Enfin les quatorze journées que celui-ci avait juré de passer avec Raguel s’écoulèrent, et il lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Congédie-moi, car mon père et ma mère n’espèrent plus me revoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Et le beau-père repartit: Demeure auprès de moi, et j’enverrai chez ton père, et je l’informerai de ce qui te concerne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Et Tobie reprit: Laisse-moi retourner chez mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Et Raguel, s’étant levé, lui donna Sara sa femme, et lui donna la moitié de ses biens, en esclaves, en argent et en bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Et, l’ayant béni, il le congédia, disant: Que le Dieu du ciel vous fasse prospérer, enfants, tant que je vivrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Et il dit à sa fille: Honore ton beau-père et ta belle-mère; ils sont désormais tes parents; que j’entende de toi bonne renommée; et il la baisa. Et Edna dit à Tobie: Frère bien-aimé, que le Seigneur Dieu du ciel te conserve, qu’il m’accorde de te voir des enfants de Sara ma fille, afin que je me réjouisse devant le Seigneur. Voilà que je te confie ma fille, en disant: Garde-toi de la jamais affliger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Après cela, Tobie partit bénissant Dieu qui lui avait fait faire un si heureux voyage; et il bénissait Raguel et Edna sa femme, et il allait, jusqu’à ce qu’ils fussent près de Ninive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Et Raphaël dit à Tobie: Ne sais-tu pas, frère, comment tu as laissé ton père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Prenons l’avance sur ta femme, et préparons la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'N’oublie pas d’emporter le fiel du poisson. Et ils pressèrent le pas, et le chien les suivit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Et Anne était assise, cherchant des yeux son fils sur la route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Et elle l’aperçut qui venait, et elle cria à Tobit: Voilà mon fils qui vient, et l’homme qui est parti avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Et Raphaël dit: Je sais que ton père ouvrira les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Fais couler dans ses yeux le fiel du poisson; mordu par la douleur, il se frottera avec force, il fera tomber les taies, et il te verra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Or, Anne s’était mise à courir, et elle sauta au cou de son fils, et elle dit: Je t’ai revu, mon enfant; de ce moment je puis mourir. Et ils pleurèrent tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Et Tobit était sorti de sa maison, et il tomba, et son fils s’élança vers lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Et relevant son père, il fit couler dans ses yeux le fiel du poisson, disant: Aie confiance, père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Et pendant que les yeux lui cuisaient, Tobit se les frotta avec force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Et les taies se détachèrent, comme des écailles, par chaque coin d’œil, et en voyant son fils, il lui sauta au cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Et il pleura et il dit: Béni soyez-vous, ô mon Dieu, béni soit votre nom dans tous les siècles, bénis soient tous vos saints anges;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Car, après m’avoir châtié, vous avez eu pitié de moi; voilà que je vois Tobie mon fils. Et Tobie entra tout joyeux, et il fit à son père le récit des grandes choses qui lui étaient arrivées en Médie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Et Tobit s’avança à la rencontre de sa bru, plein de joie et bénissant le Seigneur, et il alla jusqu’à la porte de Ninive. Et les passants s’émerveillaient à le voir marcher, parce qu’il voyait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Et Tobit, à chaque pas, glorifiait devant eux le Seigneur, parce que Dieu avait eu pitié de lui. Et lorsqu’il arriva près de Sara sa bru, il la bénit, disant: Dieu veuille que tu sois en bonne santé, ma fille. Béni soit Dieu qui t’a conduite à nous; bénis soient ton père et ta mère. Et il y eut grande joie à Ninive parmi tous ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Et Achiachare et Nabbas ses cousins germains survinrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Et l’on célébra avec de grandes réjouissances les noces de Tobie, pendant sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Et Tobit appela son fils, et il lui dit: Songe, mon enfant, à la récompense de l’homme qui est venu avec toi; il convient de l’augmenter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Et il répondit: Père, je ne vois que justice à lui donner la moitié de ce que j’ai apporté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Car il m’a ramené sain et sauf, il a guéri ma femme; il m’a apporté mon argent, et il t’a guéri pareillement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Et le vieillard reprit: Cette moitié lui est due.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Et il appela l’ange et il lui dit: Accepte la moitié de ce que vous avez apporté, prends-la, et porte-toi bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Alors, l’ange les tira tous les deux à part, et leur dit: Bénissez Dieu; rendez-lui gloire, reconnaissez sa munificence et confessez son nom devant toutes ses créatures, à cause de ce qu’il a fait pour vous. Il est bon de bénir le Seigneur, d’exalter son nom, et de célébrer avec honneur les œuvres de Dieu; ne mettez donc pas de lenteur à chanter ses louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Il est louable de garder le secret des rois; mais pour les œuvres du Seigneur, il est glorieux de les révéler. Faites ce qui est bien, et le mal ne vous atteindra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Précieuse est la prière unie au jeûne, à l’aumône et à la justice. Mieux vaut la médiocrité avec la justice que l’abondance avec l’iniquité; mieux vaut faire l’aumône qu’amasser de l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Car l’aumône délivre de la mort; elle purifie de tous les péchés; ceux qui font l’aumône et la justice, la vie les remplira;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Mais les pécheurs sont les ennemis de leur propre vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Je ne veux rien vous celer, et je viens de dire: Il est louable de garder le secret des rois; mais, pour les œuvres du Seigneur, il est glorieux de les révéler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Eh bien! tandis que tu priais, en même temps que Sara ta bru, je transportais devant le Saint le souvenir de vos prières; et lorsque tu ensevelissais les morts, j’étais de même auprès de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Et lorsque tu n’as pas hésité à te lever et à quitter ton repas, afin d’aller ensevelir un mort, ta bonne action ne m’est pas restée cachée, et j’étais près de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Or, maintenant Dieu m’a envoyé pour te guérir, toi et Sara, ta bru.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Je suis Raphaël, l’un des sept anges saints, qui transportent les prières des saints et qui pénètrent jusqu’en face de la gloire du Saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Et les deux hommes furent troublés, et ils tombèrent la face contre terre, car ils avaient grande crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Et l’ange leur dit: Ne craignez rien, la paix soit avec vous; et bénissez à jamais le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Car ce n’est point par ma grâce à moi, mais par la volonté de notre Dieu, que je suis venu; bénissez-le donc dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Durant tous ces jours, bien que je parusse le faire, je ne mangeais, ni ne buvais, mais c’était une vision que vous aviez sous les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Rendez gloire à Dieu; car, pour moi, je remonte vers celui qui m’a envoyé, et écrivez en un livre tout ce qui s’est accompli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Et ils se relevèrent, et ils ne le virent plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Et ils racontaient les œuvres grandes et merveilleuses du Seigneur, disant comment son ange leur était apparu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Et dans le transport de sa joie, Tobit écrivit une prière, et il dit: Bénis soient dans tous les siècles le Dieu vivant et son règne!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'C’est lui qui châtie et fait miséricorde; il conduit aux enfers et il en ramène, et nul ne peut éviter sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Rendez-lui gloire, ô fils d’Israël, à la face des nations, car c’est lui qui chez elles vous a dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Montrez aux Gentils sa magnificence, glorifiez-le devant tout ce qui a vie, parce qu’il est notre Seigneur, et le Dieu notre Père, dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Et il nous flagellera à cause de nos iniquités, et il sera miséricordieux encore, et il nous réunira du milieu de toutes les nations chez qui vous aurez été dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Si vous retournez à lui de tout votre cœur et de toute votre âme pour faire la vérité en sa présence, lui-même reviendra à vous, et il ne vous cachera plus sa face. Voyez ce qu’il a fait pour vous; rendez-lui gloire à pleine voix; bénissez le Seigneur de la justice, exaltez le Roi des siècles. Pour moi, en la terre où je suis captif, je lui rends gloire, et je fais voir au peuple des pécheurs sa force et sa magnificence. Convertissez-vous, pécheurs; et faites la justice en sa présence; qui sait s’il vous sera favorable, s’il vous fera miséricorde?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'J’exalte mon Dieu; mon âme est au Roi du ciel, elle se glorifiera de sa magnificence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Proclamez-le tous; rendez-lui gloire dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Jérusalem, ville du Saint, il te flagellera à cause des œuvres de tes enfants, et il fera miséricorde aux fils des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Rends au Seigneur une grande gloire; bénis le Roi des siècles; afin qu’en toi son tabernacle soit relevé avec allégresse, qu’il y comble de joie les captifs, qu’il y aime les affligés dans toutes les générations du siècle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Nombre de nations lointaines viendront vers le nom du Seigneur Dieu, portant en leurs mains des présents, des présents pour le Roi du ciel; les générations des générations te causeront des transports d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Maudits soient tous ceux qui te haïssent! Bénis soient à jamais ceux qui t’aiment!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Réjouis-toi, tressaille d’allégresse, au sujet des fils des justes, car ils seront réunis, et ils béniront le Seigneur des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Ô heureux ceux qui t’aiment! ils mettront leur joie dans ta paix; heureux tous ceux qui se sont affligés de tes fléaux nombreux, car ils se réjouiront en contemplant toute ta gloire, et leur allégresse sera éternelle!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Que mon âme bénisse Dieu, le grand Roi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Parce qu’il rebâtira Jérusalem en émeraudes et en saphirs, parce qu’il l’entourera d’une muraille de pierres précieuses, et qu’il la couronnera de tours et de créneaux de l’or le plus pur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Parce qu’il pavera d’anthrax et de béril les places de Jérusalem, et qu’il les ornera de mosaïques en pierres d’Ophir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Et toutes ses rues diront: Alleluia, louange à Dieu, et elles répéteront: Béni soit le Dieu qui a exalté tous les siècles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Et Tobit cessa de célébrer le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Il avait cinquante-huit ans quand il perdit la vue, et il la recouvra huit ans après; et il fit de nombreuses aumônes; et il continua de craindre le Seigneur Dieu et de lui rendre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Et il atteignit une extrême vieillesse; et il appela son fils et les fils de son fils, et il dit à Tobie: Enfant, prends tes fils; voilà que je suis bien vieux et près de quitter la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Pars pour la Médie, mon enfant, car je crois tout ce qu’a dit sur Ninive le prophète Jonas; elle sera détruite; la Médie restera en paix plus longtemps. Or, mes frères seront dispersés loin de leur terre féconde, et Jérusalem deviendra un désert, et, dans son enceinte, le temple de Dieu sera livré aux flammes, et il restera longtemps désolé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Et Dieu leur fera encore miséricorde, et il les ramènera dans leur terre, et ils rebâtiront le temple, non comme le premier, jusqu’à ce que les temps soient accomplis. Puis, ils reviendront de la captivité, et ils bâtiront une riche Jérusalem, et dans ses murs ils rebâtiront à Dieu un temple plein de gloire, comme l’ont prédit les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Et tous les Gentils se convertiront sincèrement à la crainte du Seigneur Dieu, et ils enfouiront leurs idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Et toutes les nations béniront le Seigneur, et son peuple rendra gloire à Dieu, et le Seigneur glorifiera son peuple, et tous ceux qui aiment le Seigneur Dieu dans la vérité et la justice tressailliront d’allégresse, et ils seront miséricordieux pour nos frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Maintenant donc, mon enfant, abandonne Ninive; car tout ce qu’a prédit le prophète Jonas arrivera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Et toi observe la loi et les commandements, et ne cesse pas d’être juste et miséricordieux, afin de trouver le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Et ensevelis-moi avec honneur, et auprès de moi ta mère, et ne restez pas à Ninive. Enfant, vois comme Aman a traité Achiachare qui l’avait élevé; comme de la lumière il l’a conduit aux ténèbres, et quelle reconnaissance il a eue pour lui. Toutefois Achiachare a été sauvé; il a obtenu ce qui lui a été rendu; et Aman lui-même est descendu dans les ténèbres. Manassès a fait la miséricorde Achiachare a été tiré du piège de mort qu’on lui. avait tendu; Aman est tombé dans le piège et y a péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Vous voyez donc, mes enfants, ce que fait l’aumône et comment nous sauve la justice. Et tandis qu’il leur parlait, son âme l’abandonna sur son lit, et il avait cent cinquante-huit ans; et ils lui firent de belles funérailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Et lorsque Anne mourut, Tobie l’ensevelit auprès de son père; et il partit avec sa femme et ses enfants pour Ecbatane, où il demeura chez Raguel son beau-père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Et il eut une honorable vieillesse, et il ensevelit avec honneur son beau-père, et il hérita de tout leur bien, comme de celui de Tobit, son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Et il mourut âgé de cent vingt-sept ans à Ecbatane, en Médie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Et, avant de mourir, il apprit la ruine de Ninive que prit Nabuchodonosor, avec Asuéros, et il eut cette joie, avant de mourir, au sujet de Ninive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Après qu’Alexandre, fils de Philippe le Macédonien, qui sortit de la terre de Chettim, eut renversé Darius, roi des Mèdes et des Perses, il régna à sa place, et fut le premier roi des Grecs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Et il livra beaucoup de batailles, et il s’empara de beaucoup de places fortes, et il égorgea les rois de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Et il poussa jusqu’aux extrémités de la terre, et il prit les dépouilles d’une multitude de. Et la terre se tut en sa présence. Et il se glorifia, et son cœur s’enorgueillit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Alors il rassembla une puissante armée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Et il se rendit maître des contrées, des nations et des rois; et ils devinrent ses tributaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Et après cela il tomba malade, et il connut qu’il allait mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Et il appela ses serviteurs les plus renommés, nourris avec lui dès sa première jeunesse, et il leur partagea son empire, tandis qu’il vivait encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Et Alexandre avait régné douze ans, et il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Et ses serviteurs furent rois chacun au lieu qui lui était assigné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Et, lui mort, ils ceignirent tous le diadème, et, après eux, leurs fils durant nombre d’années; et ils multiplièrent les maux sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Et d’eux il sortit une racine de péché, Antiochus Épiphane, fils d’Antiochus, le roi qui avait été en otage à Rome, et qui régna dans la cent trente-septième année de l’empire des Grecs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'En ces jours-là, des fils pervertis s’élevèrent en Israël, et persuadèrent beaucoup d’hommes, disant: Allons, et faisons alliance avec les nations qui nous entourent; car depuis que nous nous tenons séparés d’elles, une multitude de maux sont tombés sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Et cette pensée fut bonne à leurs yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Et quelques-uns du peuple la prirent à cœur, et ils allèrent trouver le roi, et il leur donna pouvoir de vivre selon la loi des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Et ils bâtirent un gymnase à Jérusalem, selon la coutume des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Et ils cessèrent de se circoncire, et ils s’éloignèrent de l’alliance sainte, et ils se soumirent au joug des gentils, et ils se vendirent pour faire le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Et le royaume d’Antiochus parut suffisamment préparé à ses yeux, et il entreprit de régner sur l’Égypte, afin de régner sur deux royaumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Et il entra en Égypte avec une armée formidable, des chars, des éléphants et des cavaliers, et une grande. flotte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 19, 'Et il livra bataille à Ptolémée, roi d’Égypte; et Ptolémée ne tint pas devant lui et prit la fuite, et une multitude de blessés tombèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 20, 'Et les vainqueurs prirent les villes fortes de l’Égypte, et ils enlevèrent les dépouilles de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 21, 'Et Antiochus revint après avoir frappé l’Égypte en l’année cent quarante-troisième; et il marcha contre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 22, 'Et il entra dans Jérusalem avec une armée formidable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 23, 'Et, plein d’orgueil, il s’introduisit dans le lieu saint; et il prit l’autel d’or, et le chandelier et tous les vases du temple, et la table de proposition, et les coupes à libations et les urnes, et les encensoirs d’or, et le voile, et les couronnes, et les ornements d’or de la façade du temple, et il enleva tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 24, 'Et il prit l’argent et l’or, et les objets précieux et les trésors cachés qu’il put découvrir; et, ayant tout pris, il retourna dans son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 25, 'Et il avait fait un horrible massacre, et il avait tenu un langage superbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 26, 'Et il y eut un grand deuil en Israël, dans toutes leurs villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 27, 'Et les princes et les anciens gémirent, et les vierges et les jeunes hommes tombèrent en défaillance, et la beauté des femmes fut altérée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 28, 'Tout jeune époux se répandit en lamentations; toute jeune épouse pleura sur son lit nuptial.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 29, 'Et la terre trembla pour ceux qui l’habitaient, et toute la maison de Jacob fut revêtue de confusion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 30, 'Et après deux années révolues le roi envoya l’intendant des tribus dans les villes de Juda, et il entra à Jérusalem avec une troupe nombreuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 31, 'Et il leur tint par artifice des paroles pacifiques, et ils y crurent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 32, 'Et il tomba soudain sur la ville, et il la frappa d’une grande plaie, et il détruisit une multitude d’hommes en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 33, 'Et il enleva les dépouilles de la ville, et il la brûla par le feu; puis il démolit ses maisons et toute l’enceinte de ses remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 34, 'Et ils emmenèrent en captivité les femmes et les enfants, et ils se partagèrent les troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 35, 'Et ils relevèrent la cité de David, et ils l’entourèrent d’une muraille haute et forte, avec des tours, et ce fut leur citadelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 36, 'Et ils la peuplèrent d’une race de pécheurs, d’hommes pervertis, et ils s’y établirent fortement, et ils l’approvisionnèrent d’armes, de vivres; et, ayant réuni les dépouilles de Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 37, 'Ils les y déposèrent, et ils furent pareils à un grand filet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 38, 'Ils furent comme une embuscade autour du lieu saint, comme un mauvais démon toujours à côté d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 39, 'Et ils versèrent le sang innocent autour du temple, et ils souillèrent le saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 40, 'Et à cause d’eux les habitants de Jérusalem s’enfuirent, et cette ville fut la demeure d’étrangers; et elle devint étrangère à ses rejetons, et ses enfants l’abandonnèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 41, 'Son temple fut désolé comme le désert; ses fêtes se changèrent en deuil, ses sabbats en outrages, ses gloires en néant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 42, 'Son déshonneur s’étendit aussi loin que sa gloire, et sa grandeur devint affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 43, 'Et le roi Antiochus écrivit en tout son royaume, pour que tous ses peuples n’en fissent qu’un seul, et que chacun abandonnât ses coutumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 44, 'Et toutes les nations obéirent à la parole du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 45, 'Et beaucoup en Israël eurent pour agréable de le servir, et ils sacrifièrent à ses idoles, et ils profanèrent le sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 46, 'Et le roi envoya des lettres que des messagers portèrent à Jérusalem et aux villes de Juda, pour qu’elles eussent à suivre les coutumes des étrangers fixés sur leur territoire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 47, 'Et pour interdire les holocaustes, les sacrifices et les libations dans le temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 48, 'Et pour profaner les sabbats et les fêtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 49, 'Et pour souiller le saint des saints;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 50, 'Pour ériger en des enclos des autels à des idoles; pour sacrifier des fruits et des bêtes impurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 51, 'Pour les empêcher de circoncire leurs fils; pour qu’ils souillassent leurs âmes par toute sorte d’impuretés et de profanations, afin de leur faire oublier la loi et perdre de vue les commandements;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 52, 'Et finalement quiconque n’agirait point selon la parole du roi devait mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 53, 'Conformément à ces prescriptions, il écrivit en tout son royaume, et il institua des surveillants sur tout le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 54, 'Et il enjoignit aux villes de Juda de faire des sacrifices chacune en ses murs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 55, 'Et parmi le peuple un grand nombre se rassembla autour de ses officiers; ce furent tous ceux qui abandonnaient la loi. Et ils firent le mal en la terre sainte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 56, 'Et ils forcèrent Israël de se réfugier en des lieux cachés, où ils pussent leur échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 57, 'Et le quinzième jour du mois de Casleu, en la');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 58, 'Et ils offrirent de l’encens devant les portes des maisons et sur les places publiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 59, 'Et tous les livres de la loi qu’ils trouvèrent, ils les jetèrent au feu après les avoir mis en pièces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 60, 'Et celui chez qui l’on trouvait le livre de l’alliance, ou qui se conformait à la loi, était mis à mort, en exécution de l’édit d’Antiochus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 61, 'C’est ainsi que dans leur violence ils traitèrent Israël, et ceux qu’ils surprirent chaque mois dans les villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 62, 'Et le vingt-cinq du mois ils offraient l’encens sur l’autel dressé contre l’autel du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 63, 'Et, selon l’édit, les femmes qui pratiquaient la circoncision sur leurs fils, ils les mettaient à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 64, 'Et ils pendaient les enfants aux cous des mères, et ils pillaient leurs demeures, et ils faisaient mourir ceux qui avaient coopéré à la circoncision. Et beaucoup en Israël se fortifièrent, et s’affermirent dans la résolution de ne point manger de bêtes impures; et ils aimèrent mieux mourir que de se souiller par de tels aliments Et de professer l’alliance, et ils moururent. Et la colère du roi fut très-grande contre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'En ces jours-là, Mattathias, fils de Jean, fils de Siméon, prêtre des fils de Joarib, sortit de Jérusalem, et s’établit en Modin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Et il avait cinq fils: Jean, surnommé Caddis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Simon, surnommé Thassi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Judas, surnommé Machabée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Éléazar, surnommé Abaran, et Jonathan, surnommé Apphus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Et il vit les sacriléges qui se faisaient en Juda et en Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Et il dit: Malheur à moi! pourquoi m’est-il arrivé de voir l’affliction de mon peuple et la ruine de la ville sainte, et de demeurer ici pendant que Jérusalem est entre les mains de ses ennemis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Et que des étrangers sont les maîtres du sanctuaire? Son temple est devenu comme un homme sans gloire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Les vases dont elle était si fière ont été ravis comme une proie; ses enfants ont été tués sur les places, et ses jeunes hommes ont péri par l’épée de l’ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Quelle est la nation qui n’ait hérité de son royaume, qui ne se soit enrichie de ses dépouilles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Toute sa parure lui a été ôtée; et de libre elle est devenue esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Et nos choses saintes, notre beauté, notre gloire, ont fait place à la désolation, et les gentils les ont profanées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Pourquoi vivons-nous encore?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Et Mattathias et ses fils déchirèrent leurs vêtements, et ils se ceignirent de cilices, et ils versèrent des larmes abondantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Et il vint des envoyés du roi en la cité de Modin pour contraindre à apostasier et à offrir des sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Et beaucoup d’Israël les allèrent trouver, et Mattathias et ses fils se réunirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Et les envoyés du roi prirent la parole, et ils s’adressèrent à Mattathias, disant: Tu es un chef grand et renommé en cette ville, et tu as été établi sur tes fils et tes frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Maintenant donc avance le premier, et fais ce que commande le roi, comme ont fait toutes les nations, et les hommes de Juda, et ceux qui sont restés à Jérusalem; et toi et ta famille vous serez amis du roi, et toi et tes fils vous serez comblés d’argent, d’or et de nombreux présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Et Mattathias répondit, et il dit à haute voix: Quand toutes les nations qui résident dans l’empire du roi lui obéiraient, quand chacun s’éloignerait du culte de ses pères, et donnerait la préférence aux ordres du roi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Cependant mes fils, mes frères et moi nous marcherons dans l’alliance de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'À Dieu ne plaise que nous abandonnions la loi et les commandements!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Nous n’obéirons point aux ordres du roi, pour dévier de notre culte à droite ou à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Et comme il achevait ces mots, un homme de la Judée s’avança aux yeux de tous pour sacrifier sur l’autel de Modin, selon l’ordre du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Et Mattathias, en le voyant, fut transporté de zèle, et ses reins frémirent, et il assouvit sa colère conformément à la loi, et il courut, et il égorgea cet homme sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Et en même temps il tua l’homme du roi qui forçait à sacrifier, et il renversa l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Et il fut rempli du zèle de la loi, comme l’avait été Phinéès à l’égard de Zambri, fils de Salom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 27, 'Et il parcourut la ville à grands cris, disant: Que celui qui a le zèle de la loi et demeure ferme dans l’alliance, sorte et me suive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 28, 'Et lui et ses fils s’enfuirent dans les montagnes, et ils abandonnèrent tout ce qu’ils possédaient dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 29, 'Alors beaucoup d’hommes qui désiraient la justice et la loi, descendirent aussi dans le désert,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 30, 'Pour y demeurer, eux, leurs fils, leurs femmes et leurs troupeaux, parce que les maux s’étaient multipliés sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 31, 'Et l’on apprit aux hommes du roi et à l’armée qui étaient à Jérusalem, dans la ville de David, que ceux-ci étaient allés, pour éluder les ordres du roi, dans les retraites cachées du désert; et une troupe nombreuse courut à leur poursuite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 32, 'Et, les ayant atteints, elle campa près d’eux et leur livra bataille le jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 33, 'Et d’abord ils leur dirent: Que cela suffise, venez et faites selon l’ordre du roi, et vous vivrez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 34, 'Et ils répondirent: Nous n’irons pas, et nous ne ferons point selon l’ordre du roi, et nous ne profanerons point le jour du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 35, 'Et la troupe du roi attaqua soudain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 36, 'Mais ils ne se défendirent pas, et ils ne lancèrent pas contre eux une seule pierre, et ils ne barricadèrent point leurs retraites,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 37, 'Disant Mourons tous en notre innocence; le ciel et la terre sont témoins que vous nous faites périr sans jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 38, 'Et cette troupe leur livra bataille le jour du sabbat, et ils moururent, eux et leurs femmes, et leurs enfants et leur bétail, et il y avait là mille âmes d’hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 39, 'Et Mattathias et ses amis l’apprirent, et ils versèrent sur eux des larmes en abondance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 40, 'Et ils se dirent mutuellement: Si nous faisons comme ont fait nos frères, si nous ne combattons pont les gentils pour notre vie et notre loi, nous serons bientôt exterminés de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 41, 'Et ce jour-là ils prirent une résolution, disant: Quiconque viendra nous attaquer le jour du sabbat, résistons-leur et ne mourons point comme sont morts nos frères en leurs retraites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 42, 'Alors un grand rassemblement de Juifs se forma autour d’eux, hommes forts de l’armée d’Israël, tous dévoués à la loi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 43, 'Et tous ceux qui s’étaient soustraits aux maux communs se joignirent à eux et leur devinrent un appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 44, 'Et ils formèrent un corps d’armée, et ils frappèrent dans leur colère les pécheurs, et les prévaricateurs dans leur indignation. Et les autres, pour leur échapper, cherchèrent un refuge parmi les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 45, 'Et Mattathias avec ses amis parcourut les environs et renversa les autels;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 46, 'Et ils circoncirent avec courage tous les enfants incirconcis qu’ils trouvèrent par les terres d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 47, 'Et ils poursuivirent les fils de l’orgueil, et leur œuvre prospéra entre leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 48, 'Et ils défendirent la loi contre la main des rois et des gentils, et ils ne permirent pas à un impie de lever la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 49, 'Et les jours où Mattathias devait mourir approchèrent, et il dit à ses fils: Maintenant l’orgueil s’est affermi; voici le temps du châtiment, de la ruine et de la colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 50, 'Maintenant donc, enfants, soyez zélés pour la loi, et donnez votre vie pour l’alliance de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 51, 'Souvenez-vous de nos pères et de ce qu’ils ont fait pour leur postérité, et vous recueillerez une grande gloire et un renom éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 52, 'Abraham n’a-t-il pas été reconnu fidèle dans la tentation? Et cela ne lui a-t-il pas été imputé à justice?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 53, 'Joseph, au temps de la détresse, a gardé la loi, et il est devenu le maître de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 54, 'Phinéès, notre père, par l’ardeur de son zèle a mérité les honneurs du sacerdoce à perpétuité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 55, 'Josué, en accomplissant les ordres de Dieu, est devenu juge d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 56, 'Caleb, en rendant témoignage devant l’assemblée du peuple, a obtenu la terre qu’il a eue en héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 57, 'David, par sa douceur, s’est acquis le trône royal pour les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 58, 'Élie, brûlant de zèle pour la loi, a été ravi jusqu’au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 59, 'Ananias, Azarias, Misaël, ont été sauvés de la fournaise en restant fidèles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 60, 'Daniel, par son innocence, a échappé à la gueule des lions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 61, 'Rappelez-vous, en passant ainsi de génération en génération, que tous ceux qui espèrent dans le Seigneur ne succombent point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 62, 'N’ayez pas peur des paroles d’un homme pécheur; car sa gloire n’est que vers et pourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 63, 'Aujourd’hui il est haut placé, demain on ne le');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 64, 'Mais vous, enfants, fortifiez-vous en la loi et soyez hommes, parce qu’en la loi vous serez glorifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 65, 'Voici votre frère Siméon; je sais que c’est un homme de bon conseil; obéissez-lui tous les jours, et il sera pour vous comme un père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 66, 'Judas Machabée est depuis sa jeunesse un homme vaillant à la guerre; qu’il soit pour vous un chef d’armée, et il conduira le peuple aux combats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 67, 'Pour vous, associez-vous tous ceux qui pratiquent la loi, et vengez votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 68, 'Punissez les gentils, et attachez-vous aux préceptes de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 69, 'Puis il les bénit, et il fut réuni à ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 70, 'Et il mourut en sa cent quarante-septième année, et ses fils l’emportèrent dans le sépulcre de leurs pères en Modin, et tout le peuple d’Israël mena grand deuil à cause de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Et Judas, que l’on surnommait Machabée, son fils, s’éleva à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Et tous ses frères le secondèrent ainsi que tous ceux qui avaient été attachés à son père, et ils combattirent avec joie pour Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Il agrandit la gloire de son peuple, et il se revêtit d’une cuirasse comme un géant, et il ceignit ses armes de guerre, et il livra des batailles, et il abrita le camp avec son épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Et dans ses œuvres il ressemblait au lion ou à un lionceau rugissant contre sa proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Et il rechercha et poursuivit les pervers, et ceux qui troublaient son peuple, il les livra aux flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Et les méchants furent réprimés par la terreur de son nom, et tous les ouvriers d’iniquité furent dans le trouble, et le salut s’opéra par sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Et il irrita beaucoup de rois; mais par ses œuvres il réjouit Jacob, et dans les siècles des siècles sa mémoire sera bénie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Et il parcourut les villes de Juda, et il Ꭹ extermina les impies, et il détourna la colère de dessus Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Et il fut renommé jusqu’aux confins de la terre, et il rassembla ceux qui se croyaient perdus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'De son côté, Apollonius rassembla les gentils, et il partit de Samarie pour combattre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Et Judas en fut informé; et il alla à sa rencontre; il le battit et le tua, et il y eut une multitude de blessés, et le reste s’enfuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Et Judas enleva leurs dépouilles, et il s’empara de l’épée d’Apollonius, et il s’en servit dans les combats tous les jours de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Or Siron, chef de l’armée de Syrie, apprit que Judas était à la tête d’une grande multitude, et qu’il avait rassemblé autour de lui les fidèles pour marcher au combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Et il dit: Je me ferai un nom et je serai glorifié dans le royaume, et je taillerai en pièces Judas et ses compagnons qui méprisent l’ordre du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Et il se mit en marche, et il s’avança, ayant pour auxiliaire le camp des impies qui voulait le seconder et tirer vengeance des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Et ils allèrent jusqu’à la montée de Béthoron, et Judas sortit à leur rencontre avec une poignée d’hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Lorsque ceux-ci virent le camp qu’ils allaient · attaquer, ils dirent à Judas: Comment pourrons-nous, en si petit nombre, combattre une telle multitude d’hommes vaillants, épuisés que nous sommes pour n’avoir rien mangé d’aujourd’hui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Et Judas répondit: C’est une chance heureuse qu’une grande multitude soit à la merci d’un petit nombre; et il n’y a pas de différence pour le Dieu du ciel de sauver avec une poignée d’hommes ou avec une grande armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Car la victoire dans les combats ne dépend point du nombre des troupes, mais de la force du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Ils viennent à nous dans la plénitude de leur superbe et de leur iniquité pour nous enlever, nous, nos femmes et nos enfants, et pour nous dépouiller.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Nous combattons, nous, pour notre vie et pour nos lois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Et Dieu même les brisera devant nous; ne craignez donc rien d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 23, 'À peine eut-il cessé de parler qu’il s’élança rapidement sur eux, et Siron et son camp furent écrasés en sa présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 24, 'Et ils furent poursuivis sur les pentes de Béthoron, jusqu’à la plaine; ils perdirent environ huit cents hommes, et le reste s’enfuit sur les terres des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 25, 'Dès lors commença la crainte de Judas et de ses frères, et la terreur tomba sur les nations qui les entouraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 26, 'Et son nom arriva jusqu’au roi, et tous les gentils racontèrent les batailles de Judas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 27, 'Lorsque le roi Antiochus ouït ces nouvelles, il fut transporté de colère, et il expédia des ordres, et il réunit toutes les armées de son royaume en un camp formidable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 28, 'Et il ouvrit son trésor, et il approvisionna de vivres ses soldats pour un an, et il leur prescrivit de se tenir prêts à tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 29, 'Et il vit que l’argent manquait dans ses trésors, et que ses collecteurs retiraient peu de la terre sainte, à cause de ses divisions, et des plaies dont il l’avait frappée, en détruisant des lois qui subsistaient depuis les premiers jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 30, 'Et il eut peur de n’avoir plus, comme il y était accoutumé, ce qui lui était nécessaire pour ses dépenses, et pour les présents qu’il faisait jadis d’une main prodigue; en quoi il se signalait plus que les rois ses prédécesseurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 31, 'Et son âme ressentit une vive angoisse, et il résolut d’aller en Perse, de lever les tributs des provinces et d’en recueillir beaucoup d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 32, 'Et il laissa Lysias, homme de haut rang et du sang royal, à la tête des affaires de son royaume, depuis l’Euphrate jusqu’aux confins de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 33, 'Et il le chargea de surveiller jusqu’à son retour l’éducation de son fils Antiochus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 34, 'Et il lui confia la moitié de ses troupes et ses éléphants; et en conséquence de ce qu’il avait résolu sur le peuple de la Judée et sur Jérusalem, il lui ordonna');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 35, 'D’envoyer contre eux une armée pour écraser et anéantir la force d’Israël et le reste de Jérusalem, d’effacer de ce lieu jusqu’à leur mémoire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 36, 'Et d’établir sur tout leur territoire des fils d’étrangers à qui seraient distribuées les terres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 37, 'Le roi prit pour lui l’autre moitié de ses forces, et il partit d’Antioche, sa ville royale, en l’an cent quarante-sept; il passa l’Euphrate et il gagna le pays haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 38, 'Lysias choisit donc Ptolémée, fils de Dorymène, Nicanor et Gorgias, hommes puissants parmi les amis du roi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 39, 'Et il expédia avec eux quarante mille hommes et sept mille chevaux, pour entrer sur la terre de Juda, et la détruire selon la parole du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 40, 'Et ils se mirent en marche avec toutes ces forces, et ils arrivèrent, et ils campèrent dans la plaine, près d’Emmaüs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 41, 'Et les marchands de la contrée, ayant su leur arrivée, prirent avec eux une grande quantité d’or et d’argent, emmenèrent des serviteurs, et vinrent au camp pour acheter comme esclaves les fils d’Israël; et l’armée de Syrie se joignit aux généraux de Lysias, ainsi que les forces du pays des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 42, 'Et Judas et ses frères comprirent que la mesure des maux était comblée; et en voyant les armées qui campaient sur leur territoire ils apprirent l’ordre du roi prescrivant de ruiner et d’exterminer leur peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 43, 'Et ils se dirent les uns aux autres: Relevons notre peuple de son abaissement; combattons pour notre peuple et nos choses saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 44, 'Et la Synagogue se réunit, et elle se tint prête à la guerre, et elle pria le Seigneur, invoquant sa pitié et ses miséricordes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 45, 'Et Jérusalem était dépeuplée comme le désert; nul de ses enfants n’y entrait ou n’en sortait, et son lieu saint était foulé aux pieds; et des fils d’étrangers occupaient sa citadelle, devenue le réceptacle des gentils. Et toute joie était bannie de Jacob; et la flûte et la harpe étaient muettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 46, 'Et après s’être assemblés ils vinrent en Maspha, vis-à-vis de Jérusalem; car jadis Maspha était un lieu de prière pour Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 47, 'Et ce jour-là ils jeûnèrent; ils se revêtirent de cilices; ils se couvrirent la tête de cendres et ils déchirèrent leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 48, 'Et ils ouvrirent le livre de la loi aux passages où les gentils cherchaient quelque chose qui se rapportât à leurs idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 49, 'Et ils apportèrent les robes sacerdotales, les prémices et les dîmes; et ils appelèrent les Nazaréens qui avaient accompli leurs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 50, 'Et ils élevèrent la voix jusqu’au ciel, disant: Que ferons-nous de ces vieillards? où les conduirons-nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 51, 'Votre sanctuaire, Seigneur, est foulé aux pieds et profané; vos prêtres sont dans le deuil et l’humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 52, 'Et les nations sont réunies pour nous exterminer; vous savez ce qu’ils méditent contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 53, 'Comment pourrons-nous leur résister en face, si vous ne venez à notre secours?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 54, 'Et ils sonnèrent de la trompette, et ils jetèrent de grands cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 55, 'Et après cela Judas nomma les chefs du peuple, chefs de mille hommes, de cent hommes, de cinquante et de dix hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 56, 'Et ils dirent à ceux qui bâtissaient des maisons, ou qui étaient fiancés à des femmes, ou qui plantaient des vignes, et aux plus timides, de retourner chacun en sa demeure, selon la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 57, 'Et ils levèrent le camp de Maspha, et ils allèrent camper au midi d’Emmaüs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 58, 'Et Judas dit: Ceignez-vous, soyez des fils vaillants, et tenez-vous prêts à combattre demain à l’aurore contre ces gentils qui se sont rassemblés pour nous détruire, nous et nos choses saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 59, 'Car il vaut mieux mourir les armes à la main que d’être témoins des malheurs de notre peuple et de nos saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 60, 'Et que la volonté du Ciel soit faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Et Gorgias prit cinq mille hommes et mille chevaux d’élite, et il sortit du camp, la nuit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Pour tomber sur le camp des Juifs et les battre inopinément. Et des fils de la citadelle lui servaient de guides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Et Judas en fut informé, et il décampa lui-même avec ses vaillants pour assaillir l’armée du roi qui était à Emmaüs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Car les forces ennemies étaient encore disséminées hors de leur camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Gorgias arriva donc dans le camp des Juifs avant la fin de la nuit, et il n’y trouva personne, et il les chercha dans les montagnes; car, disait-il, ils ont fui devant nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Or, quand le jour parut, Judas était dans la plaine à la tête de trois mille hommes; mais ils n’avaient point d’armures ni de glaives autant qu’ils en auraient voulu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Et ils virent le camp des gentils fortifié, palissadé, et de la cavalerie alentour, tous gens aguerris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Et Judas dit aux hommes qui l’accompagnaient: N’ayez pas peur de cette multitude, et ne redoutez pas leur choc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Rappelez-vous comment vos pères ont été sauvés de la mer Rouge, lorsque le Pharaon les poursuivait avec son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Et maintenant, crions au ciel pour que le Seigneur aie pitié de nous, et qu’il se souvienne de l’alliance de nos pères; et il brisera ce camp sous nos yeux, aujourd’hui même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Et toutes les nations connaîtront qu’il est un Sauveur et un Rédempteur pour Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Et les étrangers levèrent les yeux, et ils les virent comme ils s’avançaient à leur rencontre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Et ils sortirent du camp pour les combattre, et ceux de Judas sonnèrent de la trompette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Et ils en vinrent aux mains, et ils écrasèrent les gentils, qui s’enfuirent à travers la plaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Et toute leur arrière-garde périt par l’épée, et Judas les poursuivit jusqu’à Gazeron, et jusqu’à la plaine de l’ldumée, jusqu’à Azot et Jamnias, et trois mille des leurs succombèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Puis Judas fit volte-face, et son armée cessa de les poursuivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 17, 'Et il dit au peuple: Ne songez point au butin, parce que la guerre est en face de vous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 18, 'Car Gorgias et sa troupe dans les montagnes ne sont pas loin. Mais tournez-vous maintenant contre ces ennemis, combattez-les, et après cela vous recueillerez les dépouilles en toute liberté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 19, 'Judas parlait encore, quand un parti ennemi apparut, observant des cimes de la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 20, 'Et ces hommes virent le gros de l’armée en fuite et le camp en flammes; car la fumée qui se voyait montrait ce qui était arrivé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 21, 'À cet aspect, ils furent frappés d’une grande crainte, et en même temps ils aperçurent dans la plaine la troupe de Judas préparée pour la bataille,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 22, 'Et ils s’enfuirent sur les terres des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 23, 'Et Judas retourna au camp pour en enlever les dépouilles; et ils prirent de l’or et de l’argent en abondance, de l’hyacinthe, de la pourpre marine et de grandes richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 24, 'Et à leur retour, ils chantèrent et ils bénirent le Seigneur qui est aux cieux, parce qu’il est bon et que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 25, 'Et le salut d’Israël fut grand en ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 26, 'Et ceux des étrangers qui s’étaient échappés se rallièrent, et annoncèrent à Lysias ce qui s’était passé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 27, 'À ces nouvelles, il fut confondu et découragé; car les choses n’étaient point advenues pour Israël comme il le voulait, ni pour eux-mêmes comme le roi l’avait ordonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 28, 'Or, l’année suivante, Lysias rassembla soixante mille hommes d’élite et cinq mille chevaux pour exterminer les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 29, 'Et ces forces entrèrent en Idumée, et elles campèrent en Bethsura, et Judas se porta à leur rencontre avec dix mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 30, 'Il reconnut que le camp était formidable, et il pria Béni soyez-vous, dit-il, ô Sauveur d’Israël, ô vous qui avez brisé l’attaque du puissant par la main de votre serviteur David, vous qui avez livré le camp des Philistins à Jonathas, fils de Saül, et à son écuyer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 31, 'Livrez cette armée aux mains de votre peuple d’Israël, et qu’ils soient confondus avec leurs forces et leur cavalerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 32, 'Frappez-les de terreur; amollissez leur courage superbe; qu’ils soient ébranlés et anéantis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 33, 'Détruisez-les par le glaive de ceux qui vous aiment, et que tous ceux qui connaissent votre nom publient vos louanges dans leurs cantiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 34, 'Et ils en vinrent aux mains, et cinq mille hommes du camp de Lysias tombèrent sous leurs coups.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 35, 'Or, en voyant la déroute de son armée, l’audace de Judas, et des gens prêts à vivre ou à mourir généreusement, Lysias partit pour Antioche, et il leva des troupes étrangères, et, en ayant renforcé sa première armée, il résolut de rentrer en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 36, 'Alors Judas et ses frères dirent: Voilà que nos ennemis ont été écrasés; allons purifier nos lieux saints, et en faire la dédicace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 37, 'Et il rassembla toutes ses troupes, et il se rendit à la montagne de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 38, 'Et ils virent le sanctuaire désolé, l’autel profané, les portes brûlées, les parvis couverts d’arbrisseaux comme ceux des forêts ou des montagnes, et les vestibules abattus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 39, 'Et ils déchirèrent leurs vêtements, et ils se frappèrent la poitrine en grand deuil, et ils se couvrirent la tête de cendres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 40, 'Et ils tombèrent la face contre terre, et ils sonnèrent de la trompette, et ils crièrent vers le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 41, 'Puis Judas commanda des hommes pour contenir ceux de la citadelle, pendant qu’il purifierait le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 42, 'Il choisit des prêtres irréprochables et dévoués à la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 43, 'Et ils purifièrent les lieux saints, et ils transportèrent en un lieu impur les pierres qui les avaient souillés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 44, 'Et ils délibérèrent sur ce qu’ils feraient de l’autel des holocaustes qui avait été profané.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 45, 'Et ils eurent la bonne pensée de le démolir, pour qu’il ne fût pas pour eux un sujet d’opprobre, parce que les gentils l’avaient souillé; et ils l’abattirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 46, 'Et ils en déposèrent les matériaux sur la montagne du temple, en un lieu convenable, jusqu’à ce que survînt un prophète pour leur répondre à ce sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 47, 'Et ils prirent des pierres entières, selon la loi, et ils érigèrent un autel nouveau, semblable à l’ancien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 48, 'Et ils restaurèrent le saint des saints et l’intérieur du temple, et ils sanctifièrent les parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 49, 'El ils fabriquèrent d’autres vases sacrés, et ils déposèrent dans le temple le chandelier, l’autel des parfums et la table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 50, 'Et ils brûlèrent l’encens sur l’autel, et ils allumèrent les lampes du chandelier qui éclairaient le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 51, 'Et ils posèrent des pains sur la table, et ils déployèrent les voiles, et ils menèrent à bonne fin l’œuvre qu’ils avaient entreprise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 52, 'Et ils se levèrent de grand matin, le vingt-cinquième jour du neuvième mois, le mois de Casleu, en l’année cent quarante-huitième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 53, 'Et ils offrirent un sacrifice, selon la loi, sur le nouvel autel des holocaustes qu’ils avaient fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 54, 'Dans la même saison et le même jour où les gentils l’avaient profané, ils en firent la dédicace au milieu des chants et au son des cithares, des harpes et des cymbales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 55, 'Et tout le peuple tomba la face contre terre, et ils adorèrent, et ils bénirent le Ciel qui les avait fait si heureusement réussir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 56, 'Et ils fêtèrent pendant huit jours la dédicace de l’autel, et ils offrirent avec joie des holocaustes, et ils immolèrent des hosties de salut et d’action de grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 57, 'Et ils ornèrent la façade du temple de couronnes d’or et de petits boucliers, et ils renouvelèrent les vestibules et les portes, et ils y mirent des battants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 58, 'Et il y eut une très-grande joie parmi le peuple, et les outrages des gentils furent effacés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 59, 'Et Judas et ses frères, et toute la synagogue d’Israël, décidèrent que tous les ans on célèbrerait pendant huit jours, à pareille époque, la dédicace de l’autel, à partir du vingt-cinquième jour du mois de Casleu, et qu’il y aurait des fêtes et des réjouissances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 60, 'Et en même temps ils entourèrent la montagne de Sion d’une haute muraille avec de fortes tours, de peur que les gentils ne revinssent la fouler aux pieds, comme ils avaient fait auparavant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 61, 'Et Judas y laissa des troupes pour y faire bonne garde, et il fortifia Sion pour qu’elle défendît Bethsura, et que le peuple eût une forteresse du côté de l’Idumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Or il advint que, quand les gentils d’alentour apprirent que l’autel avait été relevé, et le sanctuaire rebâti comme jadis, ils en furent violemment irrités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Et ils résolurent d’exterminer ceux de la race de Jacob qui étaient au milieu d’eux, et ils commencèrent à répandre la mort et le carnage parmi le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Cependant Judas était à combattre dans l’Idumée les fils d’Ésau et ceux d’Acrabattine, parce que par là ils investissaient Israël; et il les frappa d’une grande plaie, et il les comprima, et il leur enleva des dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Il se souvint aussi de la méchanceté des fils de Béan, qui étaient pour le peuple comme un filet et un piège, toujours tendus sur toutes les voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Et il les renferma dans leurs tours, et il campa près d’eux, et il les maudit, et il brûla leurs tours avec tous ceux qu’elles contenaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Puis il marcha contre les fils d’Ammon, et là il trouva des mains robustes et un peuple nombreux, dont Timothée était le chef.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Et il leur livra plusieurs batailles, et ils furent écrasés devant lui, et il les foula aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Puis il prit Jazer et ses filles, et il rentra en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Alors les nations de Galaad se levèrent contre ceux d’Israël qui étaient sur leurs frontières, voulant les exterminer; mais ceux-ci s’enfuirent dans la forteresse de Diathéma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Et ils envoyèrent des lettres à Judas et à ses frères, disant Les gentils qui nous entourent se sont rassemblés contre nous, afin de nous détruire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Et ils se préparent à venir et à occuper la forteresse où nous nous sommes réfugiés; et Timothée commande leurs troupes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Accours donc promptement, et tire-nous de leurs mains; car une multitude des nôtres est déjà tombée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Et tous nos frères qui étaient sur les terres de Tubin sont morts, et leurs femmes et leurs enfants ont été emmenés en captivité, et on leur a pris leurs bagages, et près d’un millier d’hommes a péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Comme Judas et ses frères lisaient ces lettres, d’autres messagers arrivèrent de la Galilée, les vêtements déchirés, et apportèrent de semblables nouvelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Et ils dirent: Les gentils de Ptolémaïs, de Tyr, de Sidon et de toute la Galilée se sont rassemblés pour nous perdre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Lorsque Judas et le peuple eurent ouï ces paroles, une grande assemblée se réunit pour délibérer sur ce qu’ils feraient pour leurs frères qui étaient dans la détresse et menacés de périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Et Judas dit à son frère Simon: Choisis-toi des hommes, et pars pour sauver nos frères de la Galilée. Pour moi et mon frère Jonathan, nous marcherons vers Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Et il laissa Joseph, fils de Zacharie, et Azarias, chefs du peuple, avec le reste des troupes pour garder la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Et il leur donna ses ordres, disant: Veillez sur le peuple, et n’engagez aucune guerre avec les gentils avant notre retour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'On donna à Simon trois mille hommes pour aller en Galilée, et à Judas huit mille pour aller en Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 21, 'Simon alla donc en Galilée, et il livra plusieurs batailles aux gentils; et les gentils furent brisés devant sa face, et il les poursuivit jusqu’aux portes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 22, 'De Ptolémaïs; et environ trois mille des leurs tombèrent, et il emporta leurs dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 23, 'Et il enleva les hommes de la Galilée et d’Arbatte, avec leurs femmes, leurs enfants et tout ce qu’ils possédaient, et il les emmena en Judée avec une grande joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 24, 'De leur côté, Judas Machabée et Jonathas, son frère, passèrent le Jourdain, et ils firent trois journées de marche dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 25, 'Et ils rencontrèrent les Nabatéens, et ils les abordèrent pacifiquement, et ceux-ci leur apprirent ce qui était arrivé à leurs frères en Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 26, 'Ils leur dirent que beaucoup d’entre eux étaient enfermés dans les citadelles de Bossora et de Bosor, d’Alem, de Chasphor, de Maced et de Carnaïn, toutes villes grandes et fortifiées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 27, 'Ils ajoutérent que d’autres étaient resserrés dans les villes de Galaad, et qu’on avait résolu de marcher le lendemain sur toutes ces citadelles, pour les y prendre et les tuer tous le même jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 28, 'Judas et ses troupes reprirent donc aussitôt le chemin du désert; ils attaquèrent aussitôt Bosor, et s’emparèrent de la ville; puis ils passèrent tous les mâles au fil de l’épée, ils enlevèrent leurs dépouilles et brûlèrent la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 29, 'Puis il se leva de nuit et se porta sur la forteresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 30, 'Et quand l’aurore parut, ils levèrent les yeux, et voilà qu’une multitude innombrable de troupes préparaient des échelles et des machines, pour enlever d’assaut la forteresse et s’emparer des assiégés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 31, 'Et Judas vit que le combat était engagé; et la clameur de la ville montait jusqu’au ciel avec le son des trompettes et les cris des guerriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 32, 'Et il dit aux hommes de l’armée: Combattez aujourd’hui pour vos frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 33, 'Et il les divisa en trois corps sur les derrières des assaillants, et ils sonnèrent de la trompette, et ils jetèrent de grands cris, en priant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 34, 'Et le camp de Timothée reconnut que c’était Machabée, et tous s’enfuirent devant lui; et il les frappa d’une grande plaie; et ce jour-là environ huit mille des leurs succombèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 35, 'Puis il marcha sur Maspha, et il l’attaqua, la prit et en tua tous les mâles; et il emporta leurs dépouilles, et il brûla la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 36, 'De là il continua et prit Chasphor et Maced, comme Bosor et le reste des villes de la Galaaditide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 37, 'Or, après ces choses, Timothée réunit une autre armée, et il établit son camp vis-à-vis de Raphon, au delà du torrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 38, 'Et Judas envoyà des éclaireurs pour reconnaître le camp, et ils lui en rendirent compte, disant: C’est un rassemblement de toutes les nations qui nous entourent; leur armée est innombrable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 39, 'Ils ont engagé les Arabes comme auxiliaires, et ils sont campés au delà du torrent, prêts à te livrer bataille. Judas alla à leur rencontre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 40, 'Et Timothée dit aux chefs de son armée: Lorsque Judas et ses troupes seront au bord du torrent, s’il passé le premier, nous ne pourrons soutenir son attaque, parce qu’il aura tout l’avantage sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 41, 'Mais s’il a peur et s’il campe au delà du fleuve, nous passerons l’eau, et nous prévaudrons sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 42, 'Or, lorsque Judas fut près du torrent, il rangea sur la rive les scribes du peuple, et il leur donna ses ordres, disant Ne permettez à personne de dresser sa tente, mais que tous marchent au combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 43, 'Et il passa le fleuve le premier, et tout le peuple s’élança à sa suite. Les gentils devant lui rompirent les rangs, jetèrent leurs armes et s’enfuirent dans l’enclos de Carnaïn.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 44, 'Et Judas prit la ville, et il livra l’enclos aux flammes avec ceux qui s’y étaient renfermés, et Carnaïn fut renversée, et il fut impossible désormais de tenir en face de Judas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 45, 'Et Judas rassembla tous ceux d’Israël qui demeuraient en Galaad, du petit au grand, avec leurs femmes et leurs enfants, et tout ce qu’ils possédaient, pour les emmener en la terre de Juda; et ce fut une troupe innombrable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 46, 'Et ils arrivèrent à Éphron; c’est une grande ville dans un étroit défilé; et il n’y avait pas à s’en écarter à droite ni à gauche; mais il fallait la traverser par le milieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 47, 'Et ceux de la ville s’y renfermèrent, et ils barricadèrent les portes avec des pierres. Et Judas leur fit porter des paroles pacifiques,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 48, 'Disant: Nous traverserons votre terre pour rentrer dans la nôtre; et nul ne vous fera tort; nos pieds seuls toucheront votre sol. Et ils refusèrent de lui ouvrir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 49, 'Et Judas fit publier dans le camp que chacun attaquât la ville du côté où il se trouvait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 50, 'Et les hommes de l’armée s’approchèrent, et ils attaquèrent la ville tout ce jour-là et toute la nuit, et la ville fut livrée entre leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 51, 'Et il fit passer tous les mâles au fil de l’épée, et il détruisit la ville de fond en comble; et il en emporta les dépouilles, et il la traversa sur les corps morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 52, 'Puis ils passèrent le Jourdain, dans la grande plaine, qui est en face de Bethsan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 53, 'Et Judas, jusqu’à ce qu’on fût arrivé en la terre de Judée, ne cessait de rallier les derniers, et de consoler tout le peuple sur toute la route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 54, 'Et ils montèrent sur la montagne de Sion avec allégresse et réjouissances; et ils offrirent des holocaustes, parce qu’ils étaient revenus en paix, sans avoir perdu aucun des leurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 55, 'Et durant les jours où Judas et Jonathas étaient en Galaad, et Simon, leur frère, en Galilée, devant Ptolémaïs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 56, 'Joseph, fils de Zacharie, et Azarias, chefs de l’armée, apprirent les grandes actions qu’ils avaient faites et les combats qu’ils avaient soutenus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 57, 'Et Joseph dit: Faisons-nous aussi un nom, et allons combattre les gentils qui nous entourent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 58, 'Et ils donnèrent leurs ordres à ceux de l’armée qu’ils commandaient, et ils marchèrent sur Jamnia.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 59, 'Et Gorgias sortit de la ville avec ses hommes pour les rencontrer et leur livrer bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 60, 'Et Joseph et Azarias furent mis en déroute, et ils furent poursuivis jusqu’aux frontières de la Judée; et ce jour-là deux mille hommes du peuple d’Israël tombèrent, et il y eut une grande déroute du peuple d’Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 61, 'Parce qu’ils n’avaient point obéi à Judas et à ses frères, s’imaginant faire aussi de grands exploits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 62, 'Mais ils n’étaient pas de la race de ces hommes auxquels était réservé le salut d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 63, 'Et Judas et ses frères furent extrêmement glorifiés aux yeux de tout Israël et de tous les gentils qui ouïrent leur nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 64, 'Et le peuple vint au-devant d’eux, en publiant leurs louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 65, 'Et Judas partit encore avec ses frères, et ils combattirent les fils d’Esau, en la terre qui est au midi, et ils s’emparèrent d’Hébron et de ses filles; et ils renversèrent leurs murailles, et ils brûlèrent les tours qui les environnaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 66, 'Et Judas partit pour entrer sur le territoire des étrangers, et il passa par Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 67, 'En ce jour, des prêtres en combattant furent tués, pour avoir voulu se signaler et avoir pris part à la guerre inconsidérément.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 68, 'Et Judas fit un détour sur Azot, en la terre des étrangers, et il renversa leurs autels, et il brûla les statues de leurs dieux, et il enleva les dépouilles des villes, et il revint en la terre de Judas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Cependant le roi d’Antiochus parcourait les pays hauts, et il apprit qu’il y avait en Perse la ville d’Élymaïs, renommée pour ses richesses et ses amas d’or et d’argent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Que son temple était extrêmement riche, et contenait des boucliers, des cuirasses et des armes d’or, laissés en ce lieu par Alexandre, fils de Philippe, roi de Macédoine, lequel avait été le premier roi des Grecs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Et il y alla, et chercha à surprendre la ville et à la piller; mais il ne le put, parce que ceux de la ville furent informés de ses desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Puis ils se soulevèrent pour le combattre; et il s’enfuit et il s’en revint de cette contrée avec une grande affliction, pour retourner à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Mais il était encore en Perse, lorsqu’on vint lui annoncer que ses armées avaient été mises en déroute en la terre de Judée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Que Lysias y était entré avec une armée plus considérable que les premières, et qu’il avait été battu pareillement; et que les vainqueurs s’étaient affermis avec des troupes, des armes et un riche butin enlevé aux camps des vaincus;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Et qu’ils avaient renversé l’abomination que luimême avait élevée sur l’autel de Jérusalem, et qu’ils avaient entouré de hauts remparts, comme autrefois, le temple et leur ville de Bethsura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'À cette nouvelle, le roi, saisi d’épouvante, fut consterné, et il se mit au lit, et il tomba malade de chagrin; car les choses n’avaient point tourné au gré de ses désirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Et il s’arrêta là plusieurs jours, parce que sa grande tristesse se renouvelait sans cesse, et il pensa qu’il allait mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Alors il appela ses amis et il leur dit: Le sommeil s’est éloigné de mes paupières, et je succombe à cause de l’inquiétude de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Et j’ai dit en mon cœur: Où s’arrêteront mon affliction et le trouble où je suis? j’étais heureux et aimé dans ma toute-puissance;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Et maintenant je me souviens des maux que j’ai infligés à Jérusalem; j’ai pris tous ses vases d’or et d’argent, et j’ai donné des ordres pour que les habitants fussent exterminés, et cela sans sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 13, 'Je reconnais donc qu’à cause de cela tous les malheurs m’adviennent; voilà que, dans l’excès de mon chagrin, je meurs sur une terre étrangère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 14, 'Et il appela Philippe, l’un de ses amis, et il le choisit pour être à la tête de son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 15, 'Et il lui donna son diadème, sa robe et son anneau, pour qu’il allât chercher son fils Antiochus, qu’il l’élevât et le fit régner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 16, 'Et c’est là que mourut le roi Antiochus en la cent quarante-neuvième année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 17, 'Et Lysias apprit que le roi était mort, et qu’il avait désigné pour lui succéder son fils Antiochus, qu’il avait élevé dès l’enfance, et il le surnomma Eupator.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 18, 'Cependant ceux de la citadelle fermaient à Israël toutes les issues du temple; et ils cherchaient en tout à nuire au peuple et à fortifier les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 19, 'Judas résolut donc de les exterminer, et il rassembla tout le peuple pour les investir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 20, 'Ils se réunirent tous à la fois, et ils les assiégèrent en la cent cinquantième année, et ils dressèrent contre eux des machines et des balistes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 21, 'Mais quelques-uns des assiégés s’échappèrent de leur étreinte, et quelques impies d’Israël se joignirent à eux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 22, 'Puis ils allèrent trouver le roi, et lui dirent: Jusques à quand refuseras-tu de nous rendre justice et de venger nos frères?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 23, 'Nous avons mis notre joie à servir ton père, à suivre ses ordres, à exécuter ses commandements;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 24, 'Et les fils de notre peuple sont assiégés dans la citadelle; et nos frères, à cause de notre fidélité pour toi, se sont détachés de nous; et ceux de nous qu’ils saisissent, ils les tuent, et ils pillent notre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 25, 'Et ce n’est pas seulement sur nous qu’ils ont étendu la main, mais sur tout notre territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 26, 'Et voilà qu’aujourd’hui ils ont même assis leur camp devant la citadelle de Jérusalem pour en être maîtres, ainsi que du temple, et ils ont fortifié Bethsura.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 27, 'Et si tu ne te hâtes de les surprendre, ils feront pire encore, et tu ne pourras plus les réprimer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 28, 'Et lorsqu’il les eut ouïs, le roi fut transporté de colère, et il convoqua tous ses amis, les chefs de son armée et les commandants de la cavalerie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 29, 'Et des troupes mercenaires vinrent d’autres royaumes et des îles de la mer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 30, 'Et il y eut cent mille hommes d’infanterie, vingt mille cavaliers et trente-deux éléphants exercés à la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 31, 'Alors ils traversèrent l’Idumée, et ils campèrent devant Bethsura, l’attaquèrent plusieurs jours, firent des machines; mais les assiégés sortirent, brûlèrent les machines et combattirent en héros.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 32, 'Puis Judas s’éloigna de la citadelle, et campa près de Bethzacharia, vis-à-vis le camp du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 33, 'Et le roi se leva avant le jour, et il lança vigoureusement son armée sur le chemin de Bethzacharia; les deux armées se préparèrent au combat, et on sonna de la trompette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 34, 'Les Syriens montrèrent aux éléphants du jus de raisin et de mûres, pour les exciter à combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 35, 'Et ils distribuèrent ces animaux par phalanges, et il y avait pour chaque millier d’hommes cuirassés de cottes de mailles et couverts de casques d’airain un éléphant et cinquante cavaliers d’élite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 36, 'Ceux-ci se tenaient à point nommé où se tenaient les éléphants, allaient où ils allaient et ne s’éloignaient point d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 37, 'Et les éléphants portaient, pour les protéger, de fortes tours de bois, couvertes de mantelets, armées de machines, et trente-deux combattants pris dans l’armée, outre l’Indien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 38, 'Et le reste de la cavalerie, flanqué par des ravins, était rangé aux deux ailes de l’armée, pour exciter les combattants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 39, 'Lorsque les rayons du soleil tombèrent sur les boucliers d’or et d’airain, l’éclat s’en répandit sur les montagnes, et les armures brillèrent comme des lampes de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 40, 'Or une partie de l’armée du roi était rangée sur de hautes cimes, et quelques-uns dans la plaine, et ils s’avançaient en bon ordre et avec précaution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 41, 'Et tous étaient émus en entendant la clameur d’une telle multitude, et le bruit de ses pas, et le fracas de ses armes; car c’était une forte et innombrable armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 42, 'Et Judas et ses troupes s’avancèrent pour combattre, et du premier choc six cents hommes de l’armée du roi tombèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 43, 'Et Éléazar, fils de Savaras, vit que l’un des éléphants, armé de la cuirasse royale, se distinguait parmi les autres bêtes, et il semblait que là était le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 44, 'Il se dévoua donc pour sauver son peuple et se faire ainsi un renom éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 45, 'Et il s’élança intrépidement au milieu de la phalange, tuant à droite et à gauche, et les rangs s’ouvrirent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 46, 'Et il se glissa sous l’éléphant, et il se tint sous lui, et il le tua, et la bête tomba à terre sur lui; et là mourut Éléazar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 47, 'Cependant les siens, voyant les forces du roi et l’impétuosité de ses soldats, s’éloignèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 48, 'De son côté, l’armée du roi se mit en marche sur Jérusalem pour les atteindre, et le roi campa faisant face à la Judée et à la montagne de Sion,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 49, 'Et il fit la paix avec ceux de Bethsura, qui sortirent de la ville; car ils n’avaient plus de vivres pour s’y tenir renfermés, parce que c’était dans le pays l’année du sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 50, 'Et le roi prit \'possession de Bethsura, et y laissa une garnison pour la conserver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 51, 'Et il tint longtemps le temple assiégé, et il dressa. des machines, des balistes et des engins à lancer des pierres ou du feu, des frondes et des scorpions pour lancer des traits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 52, 'De leur côté, les assiégés opposèrent des machines à ses machines, et ils résistèrent bien des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 53, 'Mais il n’y avait plus de vivres dans les magasins, car c’était la septième année; et ceux des gentils qui s’étaient établis en Judée avaient mangé le reste des provisions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 54, 'Et il n’était resté dans le lieu saint qu’un petit nombre d’hommes, parce que la famine régnait; et l’on s’était dispersé chacun en son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 55, 'Lysias apprit alors que Philippe, désigné par le roi Antiochus à sa dernière heure pour élever Antiochus, son fils, et le mettre sur le trône,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 56, 'Était revenu de la Perse et de la Médie avec les forces qu’avait emmenées le feu roi, et qu’il cherchait à s’emparer des affaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 57, 'Et il eut hâte de partir; et il dit donc au roi, aux chefs et aux hommes de l’armée: Notre nombre diminue chaque jour, nous avons peu de vivres, le lieu que nous assiègeons est fortifié, et les affaires du royaume reposent sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 58, 'Maintenant donc tendons la main à ces hommes, faisons la paix avec eux et avec tout leur peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 59, 'Et permettons-leur de suivre leurs anciennes coutumes; car c’est à cause de leurs lois abolies par nous qu’ils se sont irrités et qu’ils ont fait la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 60, 'Ce discours fut agréable au roi et aux chefs, et il envoya proposer la paix aux assiégés, qui l’acceptèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 61, 'Et le roi et les chefs prêtèrent serment, après quoi les assiégés sortirent de la forteresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 62, 'Et le roi entra dans la montagne de Sion, et il vit combien elle était fortifiée, et au mépris du serment juré, il ordonna d’abattre les remparts qui l’entouraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 63, 'Puis il partit précipitamment, et il marcha sur Antioche, trouva Philippe maître de la ville, et y rentra de force après lui avoir livré bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'L’an cent cinquante-un, Démétrius, fils de Séleucus, partit de Rome, et avec une poignée d’hommes il aborda en l’une des villes maritimes, et s’y déclara roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Or il advint que, comme il rentrait dans la demeure royale de ses pères, les troupes saisirent Antiochus et Lysias pour les lui amener.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Et il en fut informé, et il dit: Ne me montrez pas leur visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Et les troupes les tuèrent; et Démétrius s’assit sur le trône de son empire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Et tous les hommes impies et méchants d’Israël vinrent le trouver, et à leur tête était Alcime, qui ambitionnait le souverain sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Et ils accusèrent le peuple devant le roi, disant: Judas et ses frères ont détruit tes amis, et ils nous ont dispersés hors de notre territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Maintenant donc envoie un homme en qui tu aies confiance, qu’il parte et qu’il voie tout le mal qu’ils ont fait à nous et à une province du roi; et qu’il les châtie, eux et tous ceux qui les ont secondés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Et le roi choisit Bacchide, un de ses affidés, gouverneur des provinces au delà du fleuve; un des grands du royaume, et tout dévoué au roi. Et il l’envoya');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Avec l’impie Alcime, qu’il institua grand prêtre, et à qui il prescrivit de tirer vengeance des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Et ils partirent, et ils entrèrent en Judée à la tête d’une armée nombreuse, et ils envoyèrent des messagers à Judas et à ses frères avec des paroles pacifiques pour les tromper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Mais ceux-ci ne se laissèrent pas surprendre, sachant qu’ils étaient venus avec de grandes forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Et une assemblée de scribes se réunirent chez Alcime et Bacchide pour leur faire de justes propositions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Or les Assidéens étaient les premiers parmi les fils d’Israël, et ils voulaient leur demander la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Car, disaient-ils, un prêtre de la race d’Aaron est venu avec une armée, et il ne nous fera pas de mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Et il leur tint un langage pacifique, et il prêta serment, et il dit: Nous ne voulons de mal ni à vous ni à vos amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Et ils le crurent; et il prit parmi eux soixante hommes, et il les fit mettre à mort en un seul jour selon la parole qui est écrite:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ils ont répandu autour de Jérusalem le sang et la chair des saints; et nul ne s’est trouvé pour les ensevelir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Et la terreur les saisit, et tout le peuple en trembla; car, dirent-ils, il n’y a en eux ni vérité ni justice, et ils ont violé le pacte et le serment qu’ils avaient jurés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Et Bacchide partit de Jérusalem, et il campa en Bezeth, et il donna ses ordres, et il prit un grand nombre des hommes qui s’étaient éloignés de son parti, avec quelques-uns du peuple, et il les sacrifia dans un grand puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Et il confia le pays à Alcime, et lui laissa pour appui une armée; puis il alla rejoindre le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Cependant Alcime s’efforçait de s’affermir dans la dignité de grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Et tous ceux qui troublaient le peuple se réunirent autour de lui, et ils se rendirent maîtres de la terre de Judée, et frappèrent Israël d’une grande plaie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Et Judas vit tout le mal que faisaient Alcime et ceux des fils d’Israël qui le soutenaient, plus même que les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Il parcourut donc tout le territoire de la Judée, et tira vengeance des transfuges, et ils cessèrent de faire des incursions dans le pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Lorsque Alcime sut que Judas et ses compagnons croissaient en force et qu’il ne pouvait plus tenir contre eux, il retourna auprès du roi, et porta sur eux diverses accusations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Et le roi envoya Nicanor, l’un de ses chefs les plus renommés, ennemi déclaré d’Israël, et il lui prescrivit d’exterminer le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Et Nicanor vint à Jérusalem avec une armée nombreuse, et il fit porter à Judas et à ses frères des paroles pacifiques pour les tromper,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Disant: Qu’il n’y ait point de guerre entre vous et moi. Je viendrai avec un petit nombre d’hommes pour vous voir en face et en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Puis il alla trouver Judas, et ils s’embrassèrent pacifiquement, et des guerriers étaient apostés pour enlever Judas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 30, 'Mais le complot fut révélé à Judas; il sut que Nicanor était venu plein d’artifice, et il se cacha de lui, et il refusa de le revoir face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 31, 'Et Nicanor reconnut que son dessein était découvert, et il marcha contre Judas pour le combattre, près de Chapharsalama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 32, 'Mais environ cinq mille hommes de Nicanor furent taillés en pièces, et le reste s’enfuit en la cité de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 33, 'Après ces événements, Nicanor monta sur la montagne de Sion, et quelques-uns des prêtres et des anciens du peuple sortirent pour le saluer pacifiquement, et lui montrer l’holocauste offert en faveur du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 34, 'Et il se moqua d’eux et les railla; il les outragea et leur parla avec arrogance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 35, 'Et il prêta ce serment avec colère: Si dès maintenant Judas et sa troupe ne me sont pas livrés, voici ce qui arrivera: quand je reviendrai après avoir rétabli la paix, je brûlerai le temple. Et il s’éloigna plein de colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 36, 'Et les prêtres rentrèrent, et ils se tinrent en face de l’autel et du temple, et ils pleurèrent, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 37, 'C’est vous, Seigneur, qui avez choisi ce temple pour que votre nom y fût invoqué, pour qu’il fût chez votre peuple un lieu d’oraison et de prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 38, 'Punissez donc cet homme et son armée, qu’ils tombent sous le glaive; souvenez-vous de leurs menaces, que pas une seule ne s’accomplisse!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 39, 'Et Nicanor sortit de Jérusalem, et il campa en Béthoron, où l’armée de Syrie le renforça.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 40, 'Et Judas campa en Adasa avec trois mille hommes, et Judas se mit en prière, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 41, 'Lorsque les hommes du roi des Assyriens eurent blasphémé, votre ange descendit, ô Seigneur, et il en tua cent quatre-vingt-cinq mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 42, 'Écrasez de même aujourd’hui cette armée devant nous, et que les survivants sachent qu’ils ont mal parlé contre votre sanctuaire; jugez leur chef selon sa perversité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 43, 'Et les deux armées engagèrent la bataille le treizième jour du mois d’Adar; celle de Nicanor fut écrasée, et lui-même tomba le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 44, 'Et dès que les siens virent qu’il était mort, ils jetèrent leurs armes et s’enfuirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 45, 'Et durant tout le jour les vainqueurs les poursuivirent d’Adasa à Gazara, en sonnant derrière eux de la trompette, signal de leur victoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 46, 'Et de tous les villages de la Judée aux alentours les hommes sortirent, enveloppèrent les fuyards, les assaillirent et les passèrent tous au fil de l’épée; et pas un seul n’échappa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 47, 'Et ils recueillirent du butin et des dépouilles, et ils coupèrent la tête de Nicanor et cette main droite qu’il avait étendue avec arrogance, et ils emportèrent l’une et l’autre, et les exposèrent dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 48, 'Et le peuple fut au comble de la joie, et ils passèrent toute cette journée en grande réjouissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 49, 'Et ils résolurent que chaque année cette fête serait célébrée, le treize du mois d’Adar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 50, 'Et la terre de Judée demeura en paix quelque temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Cependant Judas ouït parler des Romains, de leur grande puissance, de leur bienveillance pour leurs alliés et pour ceux qui, recourant à eux, contractaient avec eux des liens d’amitié, et il sut qu’ils étaient tout-puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Et il apprit le récit de leurs guerres, et des grandes choses qu’ils avaient accomplies contre les Galates, et il sut qu’ils avaient assujetti ce peuple et l’avaient soumis au tribut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Il sut aussi ce qu’ils avaient fait en Espagne; qu’ils possédaient en cette contrée des mines d’or et d’argent; et qu’en tous lieux ils devenaient les maîtres par leur sagesse et leur grandeur d’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Si lointains que fussent les peuples, quand les rois qui les avaient attaqués étaient venus des extrémités de la terre, ils les avaient écrasés, les avaient frappés de grandes plaies, et avaient réduit les autres à des tributs annuels.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Ils avaient brisé Philippe et Persée; rois des Macédoniens, et leurs autres adversaires, et ils les avaient subjugués.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Et Antiochus le Grand, roi de l’Asie, ayant marché contre eux pour les combattre avec une armée innombrable, des cavaliers, des chars, et cent vingt éléphants, avait été écrasé par eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Et ils l’avaient pris vivant, et l’avaient contraint lui et ses successeurs à leur payer un énorme tribut et à leur donner, outre des otages, par convention expresse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'L’Inde, la Médie, la Lydie, et les plus belles provinces, et après les avoir reçues il les avaient concédées au roi Eumène.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Ensuite ceux de la Grèce, ayant résolu de se sou lever et de les massacrer, et, le complot leur ayant été dévoilé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Ils avaient envoyé contre eux un général, et ils les avaient combattus, et avaient tué une multitude d’hommes, et emmené en captivité leurs femmes et leurs enfants; puis ils les avaient dépouillés, et s’étaient rendus maîtres de leur contrée; et ils avaient abattu leurs forteresses, et depuis ce jour les tenaient en servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Et ils avaient ravagé ou asservi le reste des royaumes et des îles qui leur avaient résisté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Mais ils étaient restés les amis fidèles de ceux qui avaient recherché avec eux paix et alliance; et ils dominaient sur tous les royaumes de près ou de loin; et tous ceux qui entendaient leur nom les redoutaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Tous ceux qu’ils voulaient secourir et faire rois régnaient; ceux qu’ils voulaient renverser tombaient, tant ils étaient puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Et parmi eux nul ne posait de diadème sur sa tête; nul ne se revêtait de pourpre afin de s’en glorifier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Mais ils avaient institué un sénat, et chaque jour trois cent vingt sénateurs délibéraient sur les intérêts de la multitude, pour la bien gouverner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Et ils confiaient à un homme l’autorité pour un an, afin qu’il fût le maître de leur empire; et tous obéissaient à cet homme, et il n’y avait ni haine ni jalousie entre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Judas choisit donc Eupolème, fils de Jean, fils d’Accos, et Jason, fils d’Éléazar, et il les envoya à Rome pour contracter amitié et alliance avec eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 18, 'Et pour les prier de les délivrer du joug, parce qu’il prévoyait que le royaume des Grecs réduirait Israël en servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 19, 'Ils allèrent donc à Rome, et le chemin était bien long; et ils furent introduits dans le sénat, et ils eurent la parole, et ils dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 20, 'Judas Machabée et ses frères, et le peuple des Juifs nous ont envoyés vers vous pour que nous contractions avec vous paix et alliance, et que nous soyons inscrits parmi vos alliés et amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 21, 'Et la proposition fut agréable à leurs yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 22, 'Or voici le contenu de la lettre que le sénat écrivit sur des tablettes d’airain, et qu’il envoya à Jérusalem pour y être un monument d’alliance et de paix:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 23, 'Que toutes choses prospèrent pour les Romains et pour le peuple juif, tant sur mer que sur terre, à perpétuité; que le glaive et l’ennemi se tiennent loin d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 24, 'Si Rome d’abord ou ses alliés, en toute l’étendue de sa domination, sont engagés dans une guerre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 25, 'Le peuple des Juifs prendra les armes pour eux, selon que le temps le leur permettra, en la plénitude de leur cœur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 26, 'Et, ainsi qu’il a plu aux Romains, ceux-ci ne donneront et ne fourniront aux troupes juives ni vivres, ni armes, ni argent, ni vaisseaux; et les Juifs exécuteront leurs conventions sans rien recevoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 27, 'Et pareillement, si la nation des Juifs est la première attaquée, les Romains combattront pour eux de bonne foi, selon que le temps le leur permettra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 28, 'Et à ces troupes auxiliaires il ne sera donné ni vivres, ni armes, ni argent, ni vaisseaux; car il a plu ainsi à Rome, et les Romains exécuteront leurs conventions avec sincérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 29, 'Sous ces conditions les Romains ont traité avec le peuple juif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 30, 'Et si, ces conventions faites, l’une des deux parties veut y ajouter ou en retrancher, elles le feront à leur gré, et ce qu’elles auront ajouté ou retranché fera loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 31, 'Quant aux maux que leur a faits le roi Démétrius, nous lui en avons écrit, disant: Pourquoi as-tu appesanti ton joug sur nos amis et alliés les Juifs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 32, 'Si donc ils nous présentent encore une requête contre toi, nous leur rendrons justice, et nous te combattrons sur mer et sur terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Cependant Démétrius, ayant appris que Nicanor et ses troupes avaient péri dans une bataille, envoya une seconde fois Bacchide et Alcime en Judée, avec l’aile droite de son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Et ils prirent la route qui passe par Galgala, et ils campèrent devant Masaloth en Arbelles, et ils prirent cette ville, et ils mirent à mort beaucoup d’hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Et durant le premier mois de l’année cent cinquante-deuxième ils campèrent devant Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Puis ils partirent, et ils allèrent à Bérée avec vingt mille hommes et deux mille chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Judas était campé à Eléasa, et il avait avec lui trois mille hommes d’élite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Mais quand ils virent les forces ennemies, qui étaient si nombreuses, ils eurent grande crainte, et beaucoup s’échappèrent du camp, et il n’y demeura que huit cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Et Judas vit que son camp était dissous, et que la nécessité le forçait à combattre, et son cœur en fut brisé; car le temps lui manquait pour rallier les fuyards. Et il se sentit défaillir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Pourtant il dit à ceux qui lui restaient: Levonsnous, et marchons à l’ennemi; peut-être pourrons-nous le combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Et ils l’en détournèrent, disant: Nous ne pourrons rien; mais sauvons maintenant notre vie; puis nous reviendrons avec nos frères, et nous livrerons bataille; seuls nous sommes en trop petit nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Et Judas dit: Dieu me préserve de faire ce que vous dites et de fuir; si notre heure est arrivée, mourons avec courage pour nos frères, et ne laissons point de tache à notre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Et l’armée ennemie sortit du camp, et se rangea devant eux; et la cavalerie se divisa en deux corps, et les frondeurs et les archers précédèrent les troupes, et les plus braves se mirent au premier rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Bacchide était à l’aile droite, et la phalange s’approcha des deux côtés, et les trompettes sonnèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Les compagnons de Judas sonnèrent aussi de la trompette, et la terre retentit des cris des deux armées, et la bataille fut engagée depuis l’aurore jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Et Judas vit que Bacchide et la force de son armée étaient à l’aile droite, et il y courut avec tous les hommes de cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Et ils rompirent l’aile droite, et ils la poursuivirent jusqu’à la montagne d’Azot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Mais ceux de l’aile gauche virent la déroute de l’autre aile, et ils s’attachèrent aux pas de Judas, et ils tournèrent sa troupe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'La mêlée fut terrible, et de part et d’autre les morts tombèrent en foule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Et Judas fut tué, et le reste des siens s’enfuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 19, 'Et Jonathas et Simon, frères de Judas, l’enterrèrent, et ils l’ensevelirent à Modin, dans le sépulcre de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 20, 'Et ils le pleurèrent, et tout le peuple d’Israël mena grand deuil, et ils le pleurèrent plusieurs jours, et ils dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 21, 'Comment est tombé cet homme puissant qui sauvait Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 22, 'Le reste des actions de Judas, de ses guerres, de ses hauts faits et de ses traits de courage ne sont pas tous rapportés ici; car le nombre en est trop grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 23, 'Or, après la mort de Judas, tous les méchants, sur le territoire d’Israël, relevèrent la tête, et tous les ouvriers d’iniquité se sentirent renaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 24, 'En ces jours-là il y eut une extrême famine, et tout le pays, comme un transfuge, passa au parti des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 25, 'Et Bacchide fit choix d’hommes impies, et il les institua gouverneurs des provinces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 26, 'Et ils recherchèrent de tous côtés les amis de Judas, et ils les conduisirent à Bacchide, qui en tira vengeance et les traita avec outrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 27, 'Et il y eut en Israël une grande affliction, comme on n’en avait point vu depuis le temps qu’il ne paraissait plus de prophète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 28, 'Et tous les amis de Judas s’assemblèrent, et ils dirent à Jonathas:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 29, 'Depuis que ton frère Judas est mort, il n’est plus d’homme tel que lui pour marcher contre nos ennemis, contre Bacchide et contre ceux qui haïssent notre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 30, 'Maintenant donc, nous t’avons choisi pour être à sa place notre chef et notre prince, et combattre avec nous dans nos combats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 31, 'Et en ce temps-là Jonathas reçut le commandement, et il s’éleva à la place de son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 32, 'Bacchide le sut, et il le chercha pour le faire mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 33, 'Mais Jonathas et Simon, son frère, et tous leurs compagnons le surent, et ils s’enfuirent dans le désert de Thécoé, et ils s’arrêtèrent vers les eaux du lac d’Asphar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 34, 'Et Bacchide l’apprit le jour du sabbat, et il partit en personne avec toute son armée, et il passa le Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 35, 'Cependant Jonathas avait envoyé son frère Jean, à la tête d’une troupe d’hommes, pour prier les Nabatéens, ses amis, de prendre en dépôt leurs nombreux bagages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 36, 'Mais les fils de Jambri sortirent de Médaba, et ils prirent Jean et tout ce qu’il transportait, et ils s’éloignèrent avec le butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 37, 'Or, après ces événements, on vint dire à Jonathas et à Simon, son frère, qu’il y avait chez les fils de Jambri un grand mariage, et que l’on conduisait en grande pompe l’épousée, qui était de Médaba, et fille de l’un des plus riches Chananéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 38, 'Et ils se souvinrent de Jean leur frère, et ils partirent, et ils se cachèrent dans les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 39, 'Et ils levèrent les yeux et ils regardèrent; et voilà qu’il y avait une grande rumeur et de nombreux bagages, et le fiancé, ses amis et ses frères s’étaient mis en marche avec des tambours, des instruments et quantité d’équipages pour rencontrer l’autre cortége.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 40, 'Et les compagnons de Jonathas s’élancèrent de leur embuscade, et ils les tuèrent; et il y eut une multitude de morts, et quelques-uns s’échappèrent dans la montagne, et les vainqueurs prirent toutes leurs dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 41, 'Et la noce fut changée en deuil, et le son des instruments en lamentation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 42, 'Et ainsi ils tirèrent vengeance du sang de leur frère, et ils retournèrent sur le bord du Jourdain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 43, 'Or Bacchide, ayant ouï toutes ces choses, vint, le jour du sabbat, aux rives du Jourdain avec une armée considérable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 44, 'Et Jonathas dit à ses compagnons: Levons-nous maintenant, et combattons pour notre vie; car il n’en est pas aujourd’hui comme hier et le jour d’avant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 45, 'Voilà que la guerre est devant nous et derrière nous; nous avons d’un côté l’eau du Jourdain, de l’autre des marais et des bois, et il n’est pas d’issue par où nous puissions échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 46, 'Maintenant donc, criez au ciel, afin que nous soyons sauvés des mains de nos ennemis. Et la bataille s’engagea.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 47, 'Et Jonathas étendit la main pour frapper Bacchide; mais celui-ci l’évita et se retira en arrière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 48, 'Alors Jonathas et ses compagnons se jetèrent dans le Jourdain, et ils le passèrent à la nage, et les ennemis ne les poursuivirent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 49, 'Et ce jour-là Bacchide perdit environ mille hommes, et il retourna à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 50, 'Et il bâtit des forteresses dans la Judée: la citadelle de Jéricho, celle d’Emmaüs, et Béthoron, et Béthel, et Thamnatha-Pharathoni, et Téphon; et il les entoura de hautes murailles avec des portes et des barrières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 51, 'Et il y mit des garnisons pour continuer les hostilités contre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 52, 'Et il fortifia Bethsura et Gazara, et la citadelle de Jérusalem, et il y mit des troupes et des magasins de vivres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 53, 'Et il prit pour otages les fils des princes du pays, et il les enferma sous bonne garde dans la citadelle de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 54, 'Et durant le second mois de l’année cent cinquante-troisième, Alcime ordonna que l’on abattît le mur du parvis intérieur du temple, et il détruisit les travaux des prophètes; et il commença à démolir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 55, 'Mais en ce temps-là Alcime fut frappé, et son œuvre empêchée; sa bouche resta fermée, lui-même fut frappé de paralysie, et il ne put ni dire une parole ni rien prescrire concernant sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 56, 'Et Alcime mourut en ce temps-là, tourmenté de grandes souffrances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 57, 'Et Bacchide, voyant qu’Alcime était mort, retourna auprès du roi, et la terre de Judée fut deux ans en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 58, 'Et tous les méchants tinrent conseil, disant: Voilà que Jonathas et ses compagnons se tiennent en repos, sans méfiance; appelons Bacchide, et il les prendra tous en une seule nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 59, 'Et ils allèrent le trouver, et ils se concertèrent avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 60, 'Et il se mit en marche avec une armée nombreuse, et il fit passer en secret des dépêches à tous ses partisans en Judée, pour qu’ils eussent à saisir Jonathas et ses compagnons; mais ils ne le purent, parce que leur complot fut découvert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 61, 'Et Jonathas et Simon arrêtèrent parmi les hommees de la contrée cinquante des chefs de ce complot criminel, et ils les mirent à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 62, 'Et ils se retirèrent avec leurs compagnons à Bethbasi, dans le désert, et ils en réparèrent les brèches, et ils la mirent en état de défense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 63, 'Et Bacchide l’apprit, et il rassembla toutes ses forces, et il fit avertir ses partisans de la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 64, 'Et il vint poster son camp devant Bethbasi, et il l’assiègea pendant bien des jours, et il éleva des machines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 65, 'Et Jonathas laissa son frère Simon dans la ville; lui-même en sortit, et avec une troupe nombreuse il tint la campagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 66, 'Et il tua sous leurs tentes Odoarre et ses frères, et les fils de Phasiron; et il se mit à mettre en pièces ses ennemis, et à croître en puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 67, 'De leur côté, Simon son frère et ses compagnons firent une sortie, et ils brûlèrent les machines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 68, 'Et ils livrèrent bataille à Bacchide, et ils l’écrasèrent, et lui causèrent une grande affliction; car ses conseils et son excursion avaient été sans effet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 69, 'Et il fut transporté de colère contre les hommes pervers qui lui avaient conseillé de revenir en Judée, et il en tua un grand nombre, et résolut de s’en retourner dans son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 70, 'Jonathas le sut, et il lui envoya des députés pour traiter avec lui de la paix et de l’échange des captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 71, 'Bacchide l’accueillit favorablement, et il fit selon sa demande, et jura de ne plus chercher à lui faire aucun mal tout le reste de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 72, 'Et il lui rendit les captifs qu’il avait fait en Judée. Puis, étant parti, il retourna en son pays, et ne reparut plus sur leurs frontières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 73, 'Dès lors le glaive se reposa sur Israël, et Jonathas s’établit à Machmas, et il commença à être juge du peuple, et il effaça les impies en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Or, en l’année cent soixantième, Alexandre, fils d’Antiochus Épiphane, se souleva, et il prit Ptolémaïs, et les habitants l’accueillirent, et il régna sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'À cette nouvelle, le roi Démétrius rassembla de nombreuses forces, et il se mit en marche pour le rencontrer et lui livrer bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Et Démétrius envoya à Jonathas des lettres contenant des paroles pacifiques, afin de le glorifier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Car il se dit: Hâtons-nous de faire la paix avec lui, avant qu’il la fasse avec Alexandre contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Car il se souviendra des maux que nous lui avons faits, à lui, à ses frères et à son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Et il lui donna pouvoir de rassembler des troupes et de forger des armes; il le déclara son allié, et il voulut qu’on lui remît les otages qui étaient retenus dans la citadelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Jonathas alla donc à Jérusalem, et lut les lettres en présence de tout le peuple et de la garnison de la citadelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Et ils furent saisis d’une grande crainte, lorsqu’ils ouïrent que le roi lui donnait pouvoir de rassembler des troupes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Et ceux de la citadelle remirent à Jonathas les otages, et il les rendit à leurs pareuts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Et Jonathas résida à Jérusalem, et il se mit à rebâtir et à renouveler la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Et il dit à ceux qui exécutaient les travaux dė construire en pierres de taille le mur d’enceinte de la montagne de Sion pour la fortifier, et ils le firent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Et les étrangers qui demeuraient dans les forteresses élevées par Bacchide s’enfuirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Et chacun quitta le lieu où il était pour retourner en son pays..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Seulement quelques-uns de ceux qui avaient abandonné la loi et les commandements restèrent à Bethsura, qui était pour eux une place de refuge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Cependant le roi Alexandre fut informé du message que Démétrius avait envoyé à Jonathas; on lui raconta aussi les guerres et les hauts faits de ses frères et de lui, et les souffrances qu’ils avaient endurées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Et il dit: Trouverons-nous jamais un pareil homme? Faisons-nous aussi de lui dès maintenant un ami et un allié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Et il écrivit des lettres, et il les lui fit passer; en voici les termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Le roi Alexandre à son frère Jonathas, salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Nous avons appris que tu es un homme puissant et digne de notre amitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Nous t’instituons donc aujourd’hui grand prêtre de ton peuple, et nous voulons que tu sois appelé ami dụ roi, que tu sois attaché à nos intérêts et fidèle à notre alliance (et il lui envoya la pourpre et une couronne d’or).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 21, 'Et Jonathas se revêtit de la robe sainte dans le septième mois de l’année cent soixantième, le jour de la fête des tabernacles, et il rassembla des troupes, et il fit forger beaucoup d’armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 22, 'Démétrius apprit ces choses, et il en fut affiigé, et il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 23, 'Comment se fait-il qu’Alexandre nous ait devancés pour faire alliance avec les Juifs et s’en appuyer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 24, 'Moi aussi je vais leur écrire des paroles pacifiques accompagnées d’honneurs et de présents, afin qu’ils soient pour moi des auxiliaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 25, 'Et en conséquence il leur écrivit: Le roi Démétrius au peuple juif, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 26, 'Nous avons appris que vous êtes restés fidèles à notre traité, que vous demeurez en notre amitié, et que vous ne vous rapprochez point de nos ennemis, et nous nous en sommes réjoui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 27, 'Conservez-nous encore votre fidélité, et nous vous comblerons de biens en récompense de ce que vous ferez pour nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 28, 'Nous vous remettrons une multitude d’impôts, et nous vous ferons des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 29, 'Et dès maintenant je remets à tous les Juifs l’impôt sur le sel, et celui qu’ils payent à la couronne, et l’équivalent du tiers de la semence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 30, 'Et l’équivalent de la moitié des fruits des arbres; je cesserai dès aujourd’hui et ultérieurement de les percevoir en la terre de Judée et dans les trois provinces qui lui ont été annexées, depuis Samarie jusqu’à la Galilée. Ces impôts sont supprimés aujourd’hui et à toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 31, 'Que Jérusalem soit sainte et libre; et que son territoire, ses dîmes et ses tributs lui appartiennent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 32, 'Je renonce aussi de la possession à la citadelle de Jérusalem, et je permets au grand prêtre d’y établir pour la garder les hommes qu’il choisira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 33, 'Je rends la liberté gratuitement à toute âme de la Judée qui serait captive sur toute l’étendue de mon royaume, et je les affranchis même de tout ce qu’ils auraient à payer pour leur bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 34, 'Que toutes les fêtes, les sabbats, les nouvelles lunes, les jours consacrés, les trois jours avant une fête, et les trois jours après soient des jours d’immunité et de rémission pour tous les Juifs qui sont en mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 35, 'Et que nul n’ait le pouvoir de rien entreprendre contre l’un d’eux, ni de le troubler pour aucune affaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 36, 'Que l’on enrôle dans les armées du roi jusqu’à trente mille Juifs, et qu’on leur donne des subsides comme il convient qu’en reçoivent toutes les troupes du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 37, 'Et que l’on en place dans les grandes forteresses du roi, et partout où les besoins du royaume demandent de la fidélité; que leurs officiers et leurs chefs soient tirés de leur peuple, et qu’ils vivent selon leur loi, ainsi que l’a prescrit le roi pour ceux de la terre de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 38, 'Et que les trois provinces qui avoisinent la Judée, à partir de Samarie, dépendent de la Judée et soient réputées n’en faire qu’une seule, pour ne point obéir à d’autre autorité que celle du grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 39, 'Je fais présent de Ptolémaïs et de ses dépendances aux lieux saints de Jérusalem, pour toutes les dépenses qui ont rapport au temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 40, 'Et j’y ajoute quinze mille sicles d’argent, à prendre annuellement sur le trésor du roi et sur les revenus qui y sont versés des lieux environnants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 41, 'Et tout ce qui reste dans les caisses publiques, et que n’ont point employé les préposés aux dépenses, comme il est arrivé dans les premières années, ils le verseront à partir de ce jour pour les travaux du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 42, 'Et en outre les cinq mille sicles d’argent que l’on prélevait chaque année sur le compte des besoins du temple ne seront plus perçus, parce que cette somme appartient aux prêtres et aux ministres du lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 43, 'Et tous ceux qui se réfugieront dans le temple de Jérusalem et dans ses limites, débiteurs envers le roi ou en toute autre affaire, seront libérés, ainsi que tout ce qui leur appartient dans mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 44, 'Et en ce qui concerne la construction et le renouvellement des lieux saints, la dépense en sera faite aussi sur le trésor du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 45, 'Et en ce qui concerne la restauration des remparts de Jérusalem, la consolidation de son enceinte et la reconstruction des murailles dans toute la Judée, la dépense en sera faite également sur le trésor du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 46, 'Lorsque Jonathas et le peuple eurent ouï ces propositions, ils n’y eurent point confiance; car ils se souvenaient des maux dont le roi avait accablé Israël, et avec quelle cruauté il les avait opprimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 47, 'Mais ils furent favorables à Alexandre, parce qu’il avait le premier fait avec eux une paix réelle, et ils demeurèrent constamment ses alliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 48, 'Le roi Alexandre rassembla donc de grandes armées, et il campa en face de Démétrius.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 49, 'Les deux rois en vinrent aux mains; et l’armée de Démétrius prit la fuite, et Alexandre les poursuivit, et il prévalut sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 50, 'Et il continua à combattre sans interruption jusqu’au coucher du soleil, et ce jour-là Démétrius périt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 51, 'En conséquence, Alexandre envoya des ambassadeurs à Ptolémée, roi d’Égypte, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 52, 'Je suis rentré dans mon royaume; je me suis assis sur le trône de mes pères; j’ai ressaisi le pouvoir; j’ai écrasé Démétrius, et j’ai subjugué mes provinces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 53, 'Et dans la bataille que j’ai livrée Démétrius a péri, et lui et son armée ont été détruits, et je me suis assis sur le trône de mes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 54, 'Maintenant donc faisons alliance; donne-moi ta fille en mariage, et je serai ton gendre, et je ferai à toi et à ta fille des présents dignes de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 55, 'Et le roi Ptolémée répondit: Heureux est le jour où tu es rentré dans le pays de tes pères, et où tu t’es assis sur le trône de ton royaume!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 56, 'Et maintenant je ferai selon ce que tu m’as écrit; mais viens à ma rencontre à Ptolémaïs; ayons une entrevue, et je te prendrai pour gendre, comme tu l’as demandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 57, 'Et Ptolémée partit de l’Égypte avec sa fille Cléopâtre, et ils entrèrent à Ptolémaïs, en l’année cent soixante-deuxième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 58, 'Et le roi Alexandre alla à sa rencontre, et Ptolémée lui donna sa fille Cléopâtre, et le mariage fut célébré â Ptolémaïs, selon la coutume des rois, avec une grande magnificence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 59, 'Et Alexandre écrivit à Jonathas de venir le trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 60, 'Et il entra avec gloire à Ptolémaïs, et il y rencontra les deux rois, et il leur donna de l’argent et de l’or, et il fit de riches présents à leurs amis, et il trouva grâce devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 61, 'Et des hommes d’Israël à la langue empoisonnée, des hommes iniques se réunirent contre lui pour l’accuser auprès du roi; mais celui-ci ne fit pas attention à eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 62, 'Et le roi donna ses ordres, et l’on revêtit Jonathas de ses ornements, et on lui mit une robe de pourpre; cela fait, le roi lui donna place à ses côtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 63, 'Et il dit à ses chefs: Sortez avec lui; allez au milieu de la ville; proclamez que nul n’ait à l’accuser de quoi que ce soit, et que nul ne cherche à lui nuire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 64, 'Et ceci advint: quand ses accusateurs virent comme on proclamait sa gloire, et comme il était revêtu de pourpre, ils s’enfuirent tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 65, 'Et le roi l’honora; il le compta au nombre de ses principaux amis, et il le nomma général et gouverneur de province.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 66, 'Et Jonathas retourna à Jérusalem en paix et comblé de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 67, 'Et en la cent soixante-cinquième année Démétrius, fils de Démétrius, vint de la Crète en la contrée de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 68, 'Le roi Alexandre l’apprit et il en fut extrêmement affligé, et il retourna à Antioche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 69, 'Et Démétrius prit pour général Apollonius, qui-était en Colé-Syrie; et celui-ci rassembla une grande armée, et il campa vers Jamnia, et il envoya au grand prêtre Jonathas, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 70, 'Tu es le seul à t’élever contre moi, et à cause de toi je suis en butte aux railleries et aux outrages. Pourquoi te prévaloir de la position que tu occupes dans tes montagnes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 71, 'Maintenant donc, si tu as confiance en tes troupes, descends devant nous dans la plaine, et combattons l’un contre l’autre; car j’ai avec moi les forces des villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 72, 'Informe-toi et apprends qui je suis, et quels sont mes auxiliaires; ceux-là disent de vous: Vos pieds ne peuvent se soutenir devant nous; car deux fois tes pères ont été mis en déroute dans leur contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 73, 'Et aujourd’hui tu ne pourras résister en plaine au choc d’une telle cavalerie et d’une telle armée; car il n’y a là ni roches, ni pierres, ni lieu pour vous enfuir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 74, 'Or, lorsque Jonathas eut ouï les paroles d’Apollonius, il fut ému en son âme; il choisit dix mille hommes et sortit de Jérusalem, et Simon, son frère, se joignit à lui pour lui prêter secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 75, 'Et il campa devant Joppé; et ceux de la ville lui en fermèrent les portes, parce qu’Apollonius y avait mis garnison, et les Juifs l’assiégèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 76, 'Mais ceux de la ville eurent peur, et ils se rendirent, et Jonathas y entra en maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 77, 'Apollonius le sut, et il prit avec lui trois mille chevaux avec une nombreuse infanterie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 78, 'Et il marcha sur Azot, comme s’il eût voulu traverser cette ville, et en même temps il poussa en avant par la plaine; car il avait une forte cavalerie et il avait confiance en elle. Et Jonathas s’attacha à ses pas sur la route d’Azot, et les deux armées en vinrent aux mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 79, 'Et Apollonius laissa mille chevaux en embuscade derrière Jonathas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 80, 'Celui-ci n’apprit pas qu’il y avait des troupes sur ses derrières; et l’ennemi, l’entourant ainsi avec son armée, l’accabla de traits jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 81, 'Mais la troupe de Jonathas tint ferme, comme il l’avait ordonné, tandis que la cavalerie ennemie se fatigua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 82, 'Alors Simon lança son corps d’armée et attaqua la phalange; car les chevaux étaient énervés; il la rompit et la mit en fuite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 83, 'Et la cavalerie fut dispersée dans la plaine, et se réfugia dans Azot, et les hommes cherchèrent leur salut dans le temple de Beth-Dagon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 84, 'Mais Jonathas livra aux flammes Azot et les villes d’alentour; et il y fit un riche butin; et le temple de Dagon et ceux qui s’y étaient réfugiés furent livrés aux flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 85, 'Et huit mille hommes périrent tant par le glaive que par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 86, 'Puis Jonathas partit et porta son camp devant Ascalon; et ceux de la ville vinrent au-devant de lui, et lui rendirent de grands honneurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 87, 'Et Jonathas et ses compagnons rentrèrent à Jérusalem chargés de dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 88, 'Quand Alexandre ouït ces nouvelles, il éleva encore Jonathas en dignité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 89, 'Et il lui envoya l’agrafe d’or, qui se donne ordinairement aux parents du roi. Et il lui donna la ville d’Accaron en héritage, ainsi que son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Cependant le roi d’Égypte leva des armées aussi nombreuses que le sable du rivage de la mer, et il rassembla beaucoup de vaisseaux, et il chercha à s’emparer par ruse du royaume d’Alexandre pour le réunir au sien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Il passa donc en Syrie avec des paroles pacifiques, et les habitants des villes lui ouvrirent leurs portes, et ils allèrent à sa rencontre; car Alexandre avait donné ordre d’aller au-devant de lui, comme étant le beau père du roi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Mais quand Ptolémée entrait dans les villes, il laissait des garnisons dans chacune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Or, comme il approchait d’Azot, on lui montra le temple de Dagon brûlé, la ville et les faubourgs en ruines, et les cadavres de ceux qui étaient tombés dans la bataille ou qui avaient été brûlés; car on les avait mis en monceaux sur sa route.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Et on lui raconta avec un ton de blâme ce qu’avait fait Jonathas; et le roi garda le silence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Et Jonathas vint à Joppé au-devant du roi en grande pompe, et ils s’embrassèrent, et ils passèrent la nuit en cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Et Jonathas accompagna le roi jusqu’au fleuve qu’on appelle Eleuthère; et il rentra dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Cependant le roi Ptolémée se rendit maître de toutes les villes maritimes jusqu’à celle de Séleucie; car il avait conçu de mauvais desseins contre Alexandre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Et il envoya des ambassadeurs au roi Démétrius, disant Viens, faisons alliance, et je te donnerai ma fille qu’a épousée Alexandre, et tu règneras sur le royaume de ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Je me repens de lui avoir donné ma fille; car il a cherché à me faire périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 11, 'Et il l’accusait ainsi, à cause du désir qu’il avait de lui enlever son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 12, 'Et il lui reprit sa fille et il la donna à Démétrius; puis il s’éloigna ouvertement d’Alexandre, et leur inimitié éclata.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 13, 'Alors Ptolémée entra dans Antioche, et il mit sur sa tête deux diadèmes: celui de l’Asie et celui de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 14, 'Or le roi Alexandre était à ce moment en Cilicie, parce qu’en cette province quelques villes s’étaient révoltées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 15, 'Et il apprit ce qui se passait, et revint pour combattre Ptolémée; mais celui-ci, à la tête de son armée, le rencontra avec des forces considérables, et le mit en déroute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 16, 'Et Alexandre se réfugia en Arabie pour s’y cacher, et le roi Ptolémée fut couvert de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 17, 'Et l’Arabe Zabdiel coupa la tête d’Alexandre, et l’envoya à Ptolémée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 18, 'Et trois jours après le roi Ptolémée mourut, et les habitants des villes fortes en massacrèrent les garnisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 19, 'Et Démétrius régna en l’année cent soixante-septième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 20, 'En ces jours-là, Jonathas rassembla tous les hommes de la Judée, pour assièger la citadelle de Jérusalem, et il dressa contre elle un grand nombre de machines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 21, 'Mais quelques hommes pervers, qui haïssaient leur propre nation, se rendirent auprès du roi et lui apprirent que Jonathas assiègeait la citadelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 22, 'À cette nouvelle, il fut transporté de colère, et à peine l’eût-il ouï qu’il se mit en marche et se rendit à Ptolémaïs; là il écrivit à Jonathas de ne point assièger la citadelle, et de venir aussitôt à Ptolémaïs pour conférer avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 23, 'Jonathas, à la lecture de cette lettre, ordonna de continuer le siège; puis il choisit quelques-uns des anciens. d’Israël et des prêtres, et s’exposa lui-même au péril.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 24, 'Ayant pris de l’or et de l’argent, des manteaux et d’autres présents en grand nombre, il alla trouver le roi à Ptolémaïs, et il trouva grâce devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 25, 'Et quelques gens pervers de son peuple l’accusèrent encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 26, 'Mais le roi le traita comme l’avaient traité ses prédécesseurs, et il le glorifia en présence de tous ses amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 27, 'Et il le confirma dans le sacerdoce suprême et dans toutes les dignités qu’il avait précédemment, et il le compta au nombre de ses principaux amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 28, 'Et Jonathas demanda au roi d’exempter d’impôts la Judée et les trois provinces en Samarie, et il lui promit trois cents talents en retour:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 29, 'Le roi agréa sa proposition, et il écrivit à Jonathas, à ce sujet, des lettres ainsi conçues:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 30, 'Le roi Démétrius à son frère Jonathas et au peuple juif, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 31, 'Nous avons fait pour vous, et pour que vous la voyiez, une copie de la lettre que nous avons écrite à votre sujet à notre parent Lasthène.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 32, 'Le roi Démétrius à son père Lasthène, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 33, 'Nous avons jugé à propos de faire du bien au peuple juif, notre ami, fidèle observateur de la justice envers nous, en récompense de sa bonne volonté pour nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 34, 'En conséquence, le territoire entier de la Judée, et les trois provinces d’Aphéréma, de Lyddan et de Rhamathem, qui ont été annexées à la Judée, à partir de la Samaritide, et tout ce qui en dépend, nous les avons destinés aux prêtres de Jérusalem, pour remplacer les droits royaux que le roi prélevait précédemment dans ces sur les récoltes annuelles de la terre et sur les arbres fruitiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 35, 'Et tout notre futur revenu sur les dîmes, les impôts, les droits sur le sel de marais, et les couronnes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 36, 'Nous y renonçons sans réserve, et nulle de ces dispositions ne sera abrogée, maintenant et à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 37, 'Ayez donc soin maintenant d’en faire une copie, et qu’elle soit donnée à Jonathas, et affichée aux yeux de tous, sur la montagne sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 38, 'Quand le roi Démétrius vit que la terre se tenait en repos devant lui, et que rien ne lui résistait, il congédia toutes ses troupes, chacun dans ses foyers, sauf les forces étrangères qu’il avait levées dans les îles des gentils; et les armées du royaume de ses pères le prirent en haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 39, 'Or il y avait dans l’ancien parti d’Alexandre un certain Tryphon; il vit que toutes les troupes licenciées accusaient Démétrius, et il alla trouver l’Arabe Émalcué, qui élevait Antiochus, jeune fils d’Alexandre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 40, 'Et il était assidu auprès de lui, afin qu’il lui livrât ce jeune homme et le mît sur le trône de son père. Et il lui fit connaître ce qu’avait fait Démétrius, et la haine que lui portaient ses armées; et il passa plusieurs jours avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 41, 'Et Jonathas envoya des messagers au roi Démétrius, pour qu’il retirât la garnison de la citadelle de Jérusalem et celles des autres forteresses; car elles étaient toujours en guerre avec Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 42, 'Et Démétrius envoya des messagers auprès de Jonathas, disant: Non-seulement je ferai cela pour toi et pour ton peuple; mais je glorifierai toi et ton peuple, toutes les fois que j’en aurai l’occasion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 43, 'Maintenant tu agiras avec justice en m’envoyant des troupes auxiliaires, parce que toutes mes armées se sont éloignées de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 44, 'Et Jonathas lui envoya à Antioche trois mille hommes forts et vaillants, et ils arrivèrent auprès du roi, et le roi se réjouit de leur venue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 45, 'Mais ceux de la ville se rassemblèrent dans ses murs, au nombre de douze myriades d’hommes, et ils résolurent de tuer le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 46, 'Et le roi se réfugia dans son palais, et ceux de la ville s’emparèrent de toutes les issues, et ils commencèrent l’attaque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 47, 'Et le roi appela les Juifs à son aide, et ils se réunirent tous en un instant autour de lui; et tous à la fois ils se répandirent dans la ville; et ce jour-là ils y tuèrent environ dix myriades d’hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 48, 'Et ils brûlèrent la ville, et ils recueillirent en ce jour un immense butin, et ils sauvèrent le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 49, 'Pour les habitants, quand ils virent que les Juifs étaient maîtres de traiter la ville à leur gré, ils n’eurent plus de force en leurs pensées, et ils crièrent au roi en le priant, et ils dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 50, 'Tends-nous la main, et que les Juifs cessent de nous combattre, nous et la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 51, 'Et ils jetèrent leurs armes, et ils firent la paix, et les Juifs furent glorifiés devant le roi et devant tous les habitants du royaume, et ils retournèrent à Jérusalem chargés de grandes dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 52, 'Et Démétrius fut affermi sur le trône de son empire, et la terre se tint en repos devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 53, 'Or il trompa en tout ce qu’il avait dit; il changea à l’égard de Jonathas; il ne le rétribua pas selon ses promesses, et il l’opprima violemment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 54, 'Après cela, Tryphon reparut et avec lui Antiochus encore enfant; et il se proclama roi, et il ceignit le diadème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 55, 'Et toutes les armées que Démétrius avait dispersées');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 56, 'Et Tryphon prit les éléphants, et il se rendit maître d’Antioche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 57, 'Et le jeune Antiochus écrivit à Jonathas, disant: Je t’élève au sacerdoce suprême, et je te mets à la tête des quatre provinces, et tu seras l’un des amis du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 58, 'Et il lui envoya les coupes d’or pour son service, et il lui donna pouvoir de boire dans les coupes d’or, d’être vêtu de pourpre et de porter l’agrafe d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 59, 'Et il nomma Simon son frère général, depuis la côte de Tyr jusqu’aux confins de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 60, 'Et Jonathas sortit; il parcourut les rives du Jourdain, et il entra dans les villes au delà du fleuve; et les troupes de la Syrie se réunirent autour de lui comme alliées; puis il entra dans Ascalon, et ceux de la ville allèrent à sa rencontre pour lui rendre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 61, 'Et il partit de là pour Gaza, et ceux de la ville lui fermèrent les portes, et il l’assiéga, et il brûla ses faubourgs, et il les pilla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 62, 'Et ceux de Gaza demandèrent grâce à Jonathas, et il leur tendit la main droite; mais il prit comme otages les fils des chefs, et il les envoya à Jérusalem, et il parcourut la contrée jusqu’à Damas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 63, 'Et Jonathas apprit que les généraux de Démétrius étaient près de là, à Cadès en Galilée, avec des forces considérables, ayant dessein de l’entraîner à changer de parti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 64, 'Et il marcha à leur rencontre, et il laissa dans la province son frère Simon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 65, 'Et Simon campa devant Bethsura, et il l’attaqua pendant plusieurs jours, et il l’investit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 66, 'Et les habitants le prièrent de leur tendre la main droite, et il la leur donna; il les fit sortir de la ville; il en demeura maître et y mit garnison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 67, 'Et Jonathas et son armée campèrent vers les eaux de Gennésar, et ils se déployèrent de grand matin dans la plaine de Nasor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 68, 'Et voilà que l’armée des étrangers vint l’attaquer dans la plaine; et ils lui dressèrent une embuscade dans les montagnes, et, quand ils en vinrent aux mains,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 69, 'L’embuscade, sortant du lieu où elle était, engagea aussi le combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 70, 'Et de ce côté tous ceux du parti de Jonathas s’enfuirent, et nul ne demeura, hormis Mattathias, fils d’Abessalom, et Judas, fils de Chalphi, chefs des troupes d’élite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 71, 'Et Jonathas déchira ses vêtements, il se mit de la poussière sur la tête, et pria.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 72, 'Puis il retourna au combat contre les assaillants; il les mit en déroute, et ils s’enfuirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 73, 'Et ceux des siens qui avaient pris la fuite le virent, et ils se rallièrent autour de lui, et ils poursuivirent lės vaincus jusqu’à Cadès, où était leur camp, et euxmêmes y campèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 74, 'Et ce jour-là il tomba trois mille hommes du côté des étrangers, et Jonathas retourna à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Et Jonathas vit que l’occasion était favorable; il choisit donc des hommes, et il les envoya à Rome pour confirmer et renouveler l’alliance avec les Romains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Et il expédia des lettres, dans le même sens, aux Spartiates et en d’autres lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'Et les députés se rendirent à Rome, et ils entrèrent dans le sénat, et ils dirent: Le grand prêtre Jonathas et le peuple des Juifs nous ont envoyés vers vous, pour renouveler notre amitié et notre alliance avec vous comme autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'Et les Romains leur donnèrent des lettres pour ceux des leurs qui occupaient diverses provinces, afin qu’ils eussent à les reconduire en paix dans la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Voici la copie de la lettre écrite par Jonathas aux Spartiates:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Le grand prêtre Jonathas, et les anciens de Jérusalem, et les prêtres, et le reste du peuple juif, aux Spartiates leurs frères, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Jadis des lettres furent adressées au grand prêtre Onias, par Darius qui régnait chez vous, parce que vous êtes nos frères, comme on le voit en cet écrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Et Onias accueillit avec honneur l’homme qui en était chargé, et il en reçut les lettres qui attestaient notre alliance et notre amitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Et nous, sans que ces assurances nous fussent nécessaires, puisant notre consolation dans les livres sacrés qui sont entre nos mains,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Nous avons eu le désir de vous proposer de renouveler cette fraternité et cette alliance, pour éviter que nous ne devinssions étrangers les uns aux autres; car bien du temps s’est écoulé depuis que vous avez envoyé chez nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Nous du moins, sans y manquer en aucun temps, nous nous sommes souvenus de vous dans nos fêtes, et dans les jours consacrés où nous offrons des sacrifices, et dans nos prières, comme il est juste et convenable de se souvenir de ses frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Nous nous réjouissons donc de votre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Cependant bien des afflictions, bien des guerres nous ont circonvenus, et les rois qui nous entourent nous ont assaillis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Et nous n’avons pas voulu vous troubler, non plus que nos autres alliés et amis, à l’occasion de ces guerres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 15, 'Car nous avions le secours du Ciel, et nous avons été protégés contre nos ennemis, et nos ennemis ont été humiliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 16, 'Toutefois nous avons choisi Numénie, fils d’Antiochus, et Antipater, fils de Jason, et nous les avons envoyés aux Romains pour renouveler avec ceux-ci l’amitié et l’alliance d’autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 17, 'Et nous leur avons prescrit de passer chez vous, et de vous faire amitié, et de vous remettre des lettres concernant le renouvellement de notre fraternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 18, 'Et vous agirez bien aujourd’hui en répondant à ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 19, 'Voici la réponse aux lettres qui avaient été envoyées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 20, 'Oniarès, roi des Spartiates, à Onias, grand prêtre, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 21, 'Il a été trouvé en un écrit, concernant les Spartiates et les Juifs, qu’ils sont frères, et qu’ils sont de la race d’Abraham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 22, 'Et maintenant que cela nous est connu, vous agirez bien en nous écrivant si vous êtes en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 23, 'Or voici ce que nous vous répondons: Votre bétail et vos richesses sont à nous, et les nôtres sont à vous. Nous avons prescrit que cela vous fût annoncé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 24, 'Cependant Jonathas apprit que les généraux de Démétrius étaient rentrés en campagne pour le combattre, avec une armée plus nombreuse que la première.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 25, 'Il partit donc de Jérusalem, et il les rencontra dans la province d’Émath; car il ne leur avait pas donné le temps d’envahir son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 26, 'Et il envoya des espions dans leur camp; et ils revinrent, et lui déclarèrent qu’ils avaient pris leurs mesures pour l’attaquer à la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 27, 'Dès que le soleil fut couché, Jonathas ordonna aux siens de veiller et de se mettre sous les armes, et de se tenir toute la nuit prêts à combattre, et il plaça des avant-gardes autour du camp.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 28, 'Et les ennemis surent que Jonathas et ses troupes étaient préparés au combat, et ils eurent peur, et ils tremblèrent en leur âme, et ils allumèrent des feux dans leur camp et s’éloignèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 29, 'Cependant ni Jonathas ni ses gens ne soupçonnèrent rien jusqu’à l’aurore; car ils voyaient les feux allumés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 30, 'Et Jonathas les poursuivit, et il ne put les atteindre; car ils avaient passé les eaux de l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 31, 'Et Jonathas se tourna contre les Arabes qu’on appelle Zabédéens, et il les tailla en pièces et leur enleva des dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 32, 'Et, se remettant en marche, il entra dans Damas, et il parcourut toute cette coutrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 33, 'Simon de son côté poussa jusqu’à Ascalon et aux forteresses qui l’avoisinent, et se tourna contre Joppé et s’en empara.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 34, 'Car il était informé qu’ils avaient dessein de livrer la forteresse au parti de Démétrius, et il y laissa une garnison pour la garder.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 35, 'Puis Jonathas revint, et il réunit les anciens du peuple, et résolut avec eux de bâtir des places fortes en Judée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 36, 'Et d’exhausser les remparts de Jérusalem, et d’élever une haute muraille entre la citadelle et la ville pour les séparer et isoler la citadelle, et d’empêcher de vendre ou acheter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 37, 'Et le peuple se réunit pour rebâtir la ville, et il rapprocha le mur du torrent oriental, et il restaura le lieu qu’on appelle Chaphenatha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 38, 'Et Simon construisit Adida en Séphéla, et il la fortifia de portes et de verrous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 39, 'Cependant Tryphon cherchait à devenir roi de l’Asie, à prendre le diadème et à étendre la main sur le roi Antiochus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 40, 'Mais il eut peur que Jonathas ne lui fit obstacle et ne le combattît, et il cherchait le moyen de le surprendre et de le faire périr; et s’étant mis en marche, il vint à Bethsan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 41, 'Et Jonathas sortit à sa rencontre avec quarante mille hommes d’élite, prêts à lui livrer bataille, et il arriva devant Bethsan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 42, 'Et Tryphon vit que Jonathas était venu avec une armée nombreuse, et il n’osa pas étendre la main sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 43, 'Il l’accueillit donc avec de grands honneurs, et il le recommanda à tous ses amis, et il lui fit des présents, et ordonna à ses troupes d’obéir à Jonathas comme à luimême.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 44, 'Et il dit à Jonathas: Pourquoi donc as-tu donné tant de fatigue à tout ce peuple, quand il n’y a point de guerre entre nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 45, 'Renvoie-les tout de suite en leurs demeures; choisis pour toi quelques hommes qui t’accompagneront, et viens avec moi à Ptolémaïs, je te confierai cette ville avec le reste des places fortes et mes autres armées, et tous ceux qui dirigent mes affaires; après quoi je m’en retournerai; car je ne suis venu que pour cela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 46, 'Et Jonathas, persuadé, fit comme il avait dit, et il congédia ses troupes, qui retournèrent en la terre de Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 47, 'Il ne resta auprès de lui que trois mille hommes; il en renvoya encore deux mille en Galilée, et mille seulement l’accompagnèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 48, 'Or, lorsque Jonathas fut entré à Ptolémaïs, ceux de la ville fermèrent les portes; ils le saisirent et ils passèrent toute sa suite au fil de l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 49, 'Puis Tryphon expédia pour la Galilée et la GrandePlaine des troupes et de la cavalerie, avec ordre de faire main basse sur tous ceux qui y étaient venus avec Jonathas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 50, 'Mais ceux-ci, ayant ouï dire que Jonathas avait été pris et mis à mort avec sa suite, s’encouragèrent mutuellement, et s’avancèrent en masse, résolus à se défendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 51, 'Et ceux qui les poursuivaient, les voyant résolus à combattre pour leur vie, se retirèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 52, 'Ils rentrèrent donc tous en paix dans la terre de Judée, et ils pleurèrent Jonathas et les siens, et ils furent pleins de crainte, et tout Israël mena grand deuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 53, 'Et toutes les nations qui les entouraient entrepri→ rent de les écraser; car, dirent-ils, Ils n’ont plus ni chef ni auxiliaires; c’est donc le moment de les attaquer; effaçons-les de la mémoire des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 1, 'Cependant Simon apprit que Tryphon amenait une armée formidable pour entrer en la terre de Juda et la ravager.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 2, 'Il vit que le peuple était tremblant et frappé d’effroi, et il monta à Jérusalem, et il assembla le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 3, 'Et il les consola, et leur dit: Vous savez ce que moi et mes frères, et la maison de mon père, nous avons fait pour la loi et les choses saintes, et les guerres et les, angoisses que nous avons essuyées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 4, 'Pour cette cause, pour Israël, tous mes frères ont péri, et moi je suis resté seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 5, 'Et maintenant Dieu me préserve d’épargner ma vie dans l’affliction où nous sommes; car je ne vaux pas plus que mes frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 6, 'Loin de là, je prendrai la défense de mon peuple, des lieux saints, de nos femmes et de nos enfants; car toutes les nations, animées par la haine, se sont réunies pour nous écraser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 7, 'Et l’âme du peuple fut enflammée en entendant ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 8, 'Et ils répondirent à grands cris, disant: Tu es notre chef à la place de Judas et de Jonathas, ton frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 9, 'Combats pour nous, à la guerre, et tout ce que tu commanderas nous le ferons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 10, 'Et il rassembla tous ses hommes de guerre, et il se hâta d’achever les murs de Jérusalem, et en fortifia encore l’enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 11, 'Et il envoya Jonathas, fils d’Abessalom, et avec lui des forces suffisantes à Joppé, et Jonathas en chassa ceux qui l’occupaient, et il s’y établit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 12, 'Et Tryphon partit de Ptolémaïs avec une armée formidable pour entrer en Judée, et il avait avec lui Jonathas prisonnier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 13, 'Or Simon était campé en Adida, en face de la plaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 14, 'Mais quand Tryphon sut que Simon avait pris la place de son frère, et qu’il était disposé à lui livrer bataille, il lui envoya des ambassadeurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 15, 'Disant: Nous retenons Jonathas ton frère, à cause d’une somme d’argent qu’il doit au trésor royal, pour des affaires dont il a eu la conduite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 16, 'Et maintenant fais-nous remettre cent talents d’argent et ses deux fils comme ôtages, pour qu’une fois mis, en liberté, il ne se révolte pas contre nous, et nous le renverrops.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 17, 'Et Simon vit bien qu’il parlait ainsi pour le tromper; néanmoins il envoya l’argent et les deux enfants, de peur que le peuple ne le prît en haine et ne dît:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 18, 'C’est parce que l’on n’a envoyé ni l’argent ni ses fils que Jonathas a péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 19, 'Il envoya donc les enfants et les cent talents; et Tryphon, après l’avoir trompé par ses mensonges, ne délivra point Jonathas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 20, 'Ensuite Tryphon s’avança pour envahir la contrée et la ravager, et il tourna par la route qui mène à Ador. Et Simon et son armée vinrent à sa rencontre partout où il voulut passer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 21, 'Mais ceux de la citadelle lui dépêchèrent des émissaires pour presser Tryphon de venir les secourir par le désert et de leur envoyer des vivres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 22, 'Et Tryphon prépara toute sa cavalerie pour partir la nuit suivante; mais il tomba beaucoup de neige qui l’empêcha d’avancer. Il leva donc son camp, et vint en Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 23, 'Et comme il approchait de Bascama, il tua Jonathas et l’inhuma en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 24, 'Puis il revint sur ses pas et rentra dans son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 25, 'Et Simon envoya des gens, et il recueillit les os de Jonathas son frère, et il les déposa dans le sépulcre de ses pères à Modin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 26, 'Et le peuple d’Israël mena grand deuil, et pleura Jonathas pendant plusieurs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 27, 'Et Simon fit élever en pierres de taille sur la sépulture de son père et de ses frères un monument qui pût se voir des deux côtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 28, 'Et il dressa sept pyramides vis-à-vis l’une de l’autre, en l’honneur de son père, de sa mère et de ses quatre frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 29, 'Et il y fit graver des machines de guerre, et il les entoura de grandes colonnes où furent sculptées des armures complètes pour éterniser la gloire de ces guerriers, et, près des armures, des vaisseaux pour attirer les regards de tous les navigateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 30, 'Tel fut le sépulcre qu’il érigea à Modin, et qui subsiste encore de nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 31, 'Or Tryphon se mit en route avec le jeune roi Antiochus, pour le trahir, et il le tua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 32, 'Et il fut proclamé roi à sa place, et il posa sur sa tête le diadème de l’Asie, et il frappa d’une grande plaie toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 33, 'Pour Simon, il bâtit des forteresses en Judée, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 34, 'Et Simon choisit des hommes et les envoya au roi Démétrius pour qu’il affranchît la contrée; car tous les actes de Tryphon n’étaient que rapines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 35, 'Le roi Démétrius accueillit favorablement sa demande, et il lui répondit et lui écrivit cette lettre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 36, 'Le roi Démétrius à Simon, grand prêtre et ami des rois, aux anciens et au peuple juif, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 37, 'Nous avons reçu la couronne d’or et la palme que vous nous avez envoyées, et nous sommes disposé à faire avec vous une longue paix, et à écrire à ceux qui sont chargés de nos affaires de vous accorder vos franchises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 38, 'Que nos statuts en votre faveur soient maintenus, et que les forteresses bâties par vous vous appartiennent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 39, 'Nous vous remettons les fautes et les négligences que vous avez commises jusqu’à ce jour et la couronne que vous nous deviez; et s’il est quelque autre tribut imposé à Jérusalem, que ce tribut cesse d’être perçu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 40, 'Et si quelques-uns de vous sont disposés à s’enrôler dans mes troupes, qu’on les enrôle, et que la paix soit entre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 41, 'Ainsi, en la cent soixante-dixième année, le joug des gentils cessa de peser sur Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 42, 'Et le peuple d’Israël commença à écrire en tête des actes publics et des contrats: La première année, sous Simon, grand prêtre, grand chef et prince des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 43, 'En ces jours-là, Simon porta son camp devant Gaza, et l’investit; puis il dressa des machines; il s’approcha des remparts; il battit en brèche une tour et la renversa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 44, 'Et ceux qui étaient montés sur la machine sautèrent dans la ville, et y causèrent un grand trouble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 45, 'Et ceux de la ville montèrent sur les remparts, avec leurs enfants et leurs femmes, et ils déchirèrent leurs vêtements, et supplièrent à grands cris Simon de leur tendre la main droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 46, 'Et ils dirent: N’en use pas avec nous selon notre malice, mais selon ta miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 47, 'Et Simon se réconcilia avec eux, et il cessa de les combattre; mais il les fit sortir de la ville, et il purifia les maisons où il y avait des idoles; et cela fait, il entra dans la ville en chantant des hymnes et en bénissant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 48, 'Et il en ôta toute impureté, et il y établit des hommes accomplissant la loi, et il la fortifia, et s’y bâtit une demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 49, 'Cependant ceux de la citadelle étaient dans l’impossibilité de faire des sorties et d’entrer dans le pays, d’acheter et de vendre, et ils souffrirent cruellement de la famine, et un grand nombre moururent de faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 50, 'Et ils crièrent à Simon pour qu’il leur tendît la main droite, et il la leur tendit; et il les fit sortir, et purifia la citadelle de toutes ses souillures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 51, 'Et il y entra, des rameaux à la main, le vingt-troisième jour du second mois de l’année cent soixanteonzième, en chantant les louanges du Seigneur au son des harpes, des cymbales et des lyres, parce qu’un cnnemi redoutable avait été brisé et chassé d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 52, 'Et il statua que, chaque année, on fêterait ce jour par des réjouissances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 53, 'Et il fortifia, par des ouvrages avancés, la montagne du temple, du côté de la citadelle, et il y demeura lui-même avec toute sa suite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 54, 'Et Simon vit que Jean son fils était un homme, et il le mit à la tête de toutes ses forces; et Jean demeura en Gazara Il s’agit toujours de la forteresse de Jérusalem.</ref>.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 1, 'En la cent soixante-douzième année, le roi Démétrius rassembla toutes ses forces, et il alla en Médie, pour en tirer des secours, afin de combattre Tryphon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 2, 'Or Arsace, roi de Perse et de Médie, apprit que Démétrius était entré sur son territoire, et il envoya l’un de ses chefs avec l’ordre de le prendre vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 3, 'Ce chef se mit en marche, battit l’armée de Démétrius et fit le roi prisonnier; puis il le conduisit à Arsace, et celui-ci le jeta en prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 4, 'Et la Judée fut en repos tout le temps que vécut Simon; il chercha le bonheur de son peuple, et son pouvoir et sa gloire leur furent agréables durant tous ses jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 5, 'Outre ses autres grandes actions, il prit Joppé sur la côte, et il en fit un port d’où l’on se rendait aux îles de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 6, 'Et il étendit les frontières de son peuple, et il maîtrisa les provinces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 7, 'Et il recueillit un grand nombre de captifs, et il posséda Gazara et Bethsara, et la forteresse, et il en ôta toutes les impuretés; et il n’était personne qui pût lui résister.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 8, 'Les laboureurs cultivaient en paix leur terre, et les champs produisaient leurs récoltes, et les arbres leurs fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 9, 'Les anciens s’asseyaient sur les places et s’entretenaient de la prospérité de l’État; les jeunes hommes revêtaient des robes de gloire et des costumes de guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 10, 'Cependant Simon, tenait les forteresses approvisionnées de vivres, et il entretenait leurs remparts, et son nom devint célèbre jusqu’aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 11, 'Il établit la paix en la terre sainte, et Israël ressentit une grande joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 12, 'Et chacun s’assit sous sa vigne et son figuier, et nul ne leur inspira de crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 13, 'Et il n’y eut sur la terre personne qui les combattît, et les rois furent abattus en ces jours-là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 14, 'Et Simon fut l’appui des humbles de son peuple; et il rechercha la loi sainte, et il extermina le méchant et le pervers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 15, 'Il glorifia les lieux saints, et il multiplia les ornements du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 16, 'Or la nouvelle de la mort de Jonathas se répandit jusqu’à Rome et à Sparte, où elle causa une grande affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 17, 'Mais lorsque l’on y apprit que Simon son frère était devenu grand prêtre à sa place, et qu’il était maître de la terre et des villes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 18, 'On lui écrivit sur des tablettes d’airain pour renouveler le traité d’amitié et d’alliance fait avec ses frères Judas et Jonathas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 19, 'Et ces tablettes furent lues devant la synagogue à Jérusalem. Voici la copie des lettres qu’envoyèrent les Spartiates.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 20, 'Les princes et la ville de Sparte au grand prêtre Simon, aux anciens, aux prêtres et au reste du peuple des Juifs leurs frères, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 21, 'Les ambassadeurs envoyés à notre peuple nous ont fait connaître vos honneurs et votre gloire; et nous nous sommes réjouis de leur venue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 22, 'Et nous avons écrit ce qu’ils nous ont dit dans les décrets du peuple en ces termes: Numénie, fils d’Antiochus, et Antipater, fils de Jason, ambassadeurs des Juifs, sont venus auprès de nous pour renouveler notre alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 23, 'Et il a plu au peuple de les accueillir avec de grands honneurs, et de transcrire leurs propositions sur les registres publics, pour que le peuple des Spartiates en conserve le souvenir. Et nous en avons fait une copie pour Simon le grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 24, 'Après cela, Simon envoya à Rome Numénie avec un grand bouclier d’or du poids de mille mines, pour faire alliance avec les Romains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 25, 'Lorsque le peuple l’apprit, il dit: Comment rendrons-nous grâces à Simon et à ses fils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 26, 'Car lui et ses frères, et la maison de son père se sont affermis, et ils ont combattu les ennemis d’Israël, et ils lui ont rendu la liberté. Et ils firent une inscription sur des tablettes d’airain, et la mirent sur des colonnes en la montagne de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 27, 'Voici la copie de cette inscription: Le dix-huitième jour d’Élul, l’an cent soixante-deux, la troisième année du sacerdoce de Simon; à Saramel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 28, 'En la grande assemblée des prêtres et du peuple, des chefs de la nation et des anciens des provinces, il nous a été rappelé qu’il y avait eu beaucoup de guerres dans le pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 29, 'Or Simon, fils de Mattathias, fils des fils, de Jarib, et ses frères, se sont exposés au péril, et ont résisté aux ennemis de leur peuple, afin de maintenir leur sanctuaire et leur loi; et ils ont couvert leur nation d’une grande gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 30, 'Jonathas a rassemblé sa nation, et il est devenu grand prêtre, et il a été réuni à son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 31, 'Alors les ennemis ont voulu envahir leur pays, l’écraser, et étendre la main sur leur sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 32, 'Mais Simon s’est élevé, et il a combattu pour son peuple; et il a dépensé une grande partie de ses propres richesses, et il a donné des armures aux hommes vaillants de son peuple, et il leur a fourni des vivres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 33, 'Et il a fortifié les villes de la Judée, et Bethsura sur les frontières, où était jadis l’arsenal de ses ennemis, et il y a mis pour garnison des hommes de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 34, 'Et il a fortifié Joppé sur la côte, et Gazara sur les confins d’Azot, laquelle était jadis occupée par ses ennemis, et il y a établi des Juifs, et il l’a approvisionnée de tout ce qui convenait à leur défense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 35, 'Et le peuple a vu la conduite de Simon, et la gloire qu’il voulait répandre sur son peuple, et ils l’ont institué leur prince et leur grand prêtre, à cause de toutes ses actions, de sa justice et de sa fidélité à son pays, qu’il avait sans cesse cherché à relever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 36, 'Et de ses jours tout a prospéré dans ses mains; il a réussi à chasser les gentils de ses provinces, de la ville de David et de Jérusalem, où ils s’étaient construit une citadelle dont ils sortaient pour profaner autour d’eux les choses saintes et affliger d’une grande plaie la pureté de ces lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 37, 'Et dans cette citadelle il a établi des Juifs, et il l’a fortifiée pour la sûreté de la contrée et de la ville, et il a relevé les remparts de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 38, 'En outre, le roi Démétrius l’a confirmé dans le souverain sacerdoce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 39, 'Et il l’a compté au nombre de ses amis, et il l’a comblé d’honneurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 40, 'Car il avait appris que les Juifs étaient appelés par les Romains amis, alliés et frères, et qu’ils avaient accueilli avec honneur les ambassadeurs de Simon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 41, 'Et que les Juifs et les prêtres étaient heureux d’avoir Simon pour prince et grand prêtre à perpétuité, jusqu’à ce qu’un prophète digne de foi fût suscité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 42, 'Qu’étant leur chef, il s’occupât des choses saintes, et instituât des hommes de leur peuple chargés de diriger les travaux, administrer les provinces, et prendre soin des armes et des places fortes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 43, 'Et qu’il se réservât le service du sanctuaire, que chacun lui fût soumis; et que dans le pays tous les contrats fussent écrits en son nom, et qu’il se revêtit de pourpre et portât des ornements d’or;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 44, 'Et qu’il ne fût permis à personne, parmi le peuple et les prêtres, de rien omettre de ces choses, ni de contredire ce qu’il aurait ordonné, ni de réunir aucune assemblée dans le pays sans son consentement, ni de se revêtir de pourpre, ni de s’agrafer avec une agrafe d’or;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 45, 'Et que quiconque omettrait ou mépriserait quoi que ce soit de ces choses fût déclaré coupable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 46, 'Et tout le peuple fut heureux d’exécuter toutes les ordonnances de Simon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 47, 'Simon accepta donc le souverain sacerdoce, et il eut pour agréable d’être général et prince des Juifs et des prêtres, et de présider à tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 48, 'Et il fut décidé que cette inscription serait gravée sur des tablettes d’airain, et placée dans les galeries du temple en un lieu apparent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 49, 'Et que copie en serait déposée dans le trésor public, afin que Simon et ses fils pussent la conserver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 1, 'De son côté, Antiochus, fils du roi Démétrius, fit passer, des îles de la mer, une lettre adressée à Simon, prêtre et prince des Juifs, et à tout le peuple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 2, 'En voici le contenu: Le roi Antiochus à Simon, grand prêtre et souverain, et au peuple juif, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 3, 'Depuis que des hommes méchants se sont emparés du royaume de mes pères, j’ai voulu leur disputer la royauté, afin de la rétablir comme elle était précédemment. J’ai donc enrôlé des troupes nombreuses, et j’ai préparé des vaisseaux de guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 4, 'Or mon dessein est de pénétrer dans mes États, afin de punir ceux qui ont ruiné mes provinces, et qui ont désolé plusieurs villes de mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 5, 'Maintenant donc je confirme toutes les exemptions que les rois, mes prédécesseurs t’ont accordées, et je renonce à tous les autres dons auxquels ils ont renoncé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 6, 'Et je te permets de battre une monnaie propre à ton pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 7, 'J’entends que Jérusalem et les lieux saints soient libres. Toutes les armes que tu as fait forger, toutes les forteresses que tu as construites dans l’étendue de ta domination, qu’elles subsistent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 8, 'Que toute redevance royale, établie ou à instituer présentement et à l’avenir, te soit remise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 9, 'Aussitôt en possession de mon royaume, j’accorderai à toi, à ton peuple, et au temple de grands honneurs, afin que votre gloire soit manifeste en toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 10, 'L’an cent soixante-quatorze, Antiochus partit donc pour la terre de ses pères, et toutes les armées se joignirent à lui, de sorte qu’il ne resta autour de Tryphon qu’un petit nombre d’hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 11, 'Et le roi Antiochus le poursuivit; et, en fuyant, Tryphon atteignit Dora sur la côte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 12, 'Car il vit que le malheur était tombé sur lui, `et que ses armées l’abandonnaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 13, 'Et Antiochus campa devant Dora avec douze myriades de combattants et huit mille chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 14, 'Et il investit la ville, et les vaisseaux la resserrèrent du côté de la mer, et il pressa la ville par terre et par mer, et il ne permit à personne d’en sortir ni d’y entrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 15, 'Or Numénie revint alors avec ceux qui l’avaient accompagné à Rome, ayant des lettres pour les rois et les provinces, où était écrit ce qui suit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 16, 'Lucius, consul des Romains, au roi Ptolémée, salut:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 17, 'Les ambassadeurs des Juifs, nos amis et alliés, sont venus auprès de nous pour renouveler notre amitié et notre alliance, envoyés par le grand prêtre Simon et par le peuple des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 18, 'Ils nous ont apporté un bouclier d’or du poids de mille mines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 19, 'Il nous a donc été agréable d’écrire aux rois et aux provinces, afin qu’ils ne cherchent point à leur nuire, qu’ils n’attaquent ni eux, ni leurs villes, ni leur territoire, et ne soient point les auxiliaires de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 20, 'Il nous a plu aussi d’accepter le bouclier qu’ils nous ont offert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 21, 'Si donc quelques hommes pervers se réfugient de leur contrée dans la vôtre, livrez-les au grand prêtre Simon, afin qu’il les punisse selon sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 22, 'Et Lucius écrivit les mêmes choses au roi Démétrius, à Attale, à Ariarathe et à Arsace;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 23, 'Et à toutes les provinces à Lampsaque, aux Spartiates, à Délos, à Myndos, à Sycione, en Carie, à Samos, en Pamphylie, en Lycie, à Halicarnasse, à Rhodes, à Phasélide, à Cos, à Sidon, à Aradon, à Gortyne, à Gnide, à Chypre et à Cyrène.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 24, 'Et il en envoya une copie au grand prêtre Simon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 25, 'Or le roi Antiochus, pour assièger Dora, fit venir une seconde ligne de retranchements, s’en rapprochant toujours et dressant des machines, et il renferma Tryphon de telle sorte, qu’on ne pouvait plus ni entrer dans la ville ni en sortir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 26, 'Et Simon lui envoya comme auxiliaires des hommes d’élite; il lui envoya aussi de l’or, de l’argent et des vases précieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 27, 'Mais le roi refusa de les accepter, et il mit en oubli tout ce dont il était convenu précédemment, et il se détacha de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 28, 'Et il lui dépêcha Athénobius, l’un de ses affidés et son confident, pour lui dire: Vous retenez Joppé, Gazara et la citadelle de Jérusalem, villes de mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 29, 'Vous en avez dévasté le territoire et frappé la terre d’une grande plaie, et vous vous êtes rendus maîtres de plusieurs lieux de mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 30, 'Maintenant donc, rendez-moi les villes que vous avez prises, et payez-moi les impôts des lieux où vous dominez hors des limites de la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 31, 'Sinon, donnez-moi en échange cinq cents talents d’argent, et pour vos dévastations, et pour les impôts des villes cinq cents autres talents. Si vous ne le faites, nous marcherons contre vous et nous vous attaquerons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 32, 'Athénobius, l’ami du roi, se rendit donc à Jérusalem, et il vit la gloire de Simon, et l’étalage de ses coupes, ses vases d’or et d’argent, et son appareil magnifique, et il en fut surpris, et il lui répéta les paroles du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 33, 'Et Simon, répondant, lui dit: Nous n’avons point pris de contrée étrangère; nous ne nous sommes emparés de rien qui appartînt à des étrangers; nous sommes rentrés dans l’héritage de nos pères, que pendant longtemps nos ennemis avaient usurpé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 34, 'Mais nous avons mis à profit l’occasion, et nous avons repris l’héritage de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 35, 'En ce qui touche Joppé et Gazara que tu réclames, ces villes étaient pour notre terre une grande plaie, et nous les rachèterons au prix de cent talents. Et Athénobius ne lui répondit pas une parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 36, 'Et, plein de courroux, il retourna auprès du roi et lui rapporta les paroles et la gloire de Simon, et tout ce qu’il avait vu, et le roi fut transporté d’une grande colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 37, 'Cependant Tryphon, s’étant embarqué sur un navire, s’enfuit à Orthosiade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 38, 'Et le roi nomma Cendébée général de l’armée de la côte, et il lui donna de l’infanterie et de la cavalerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 39, 'Et il lui prescrivit de camper en face des Juifs, de fortifier Cédron, et d’en fermer les portes, afin de faire la guerre au peuple; et de sa personne il se mit à la poursuite de Tryphon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 40, 'Cendébée s’approcha donc de Jamnia, et il commença à irriter le peuple et à faire des incursions en Judée, et à enlever des captifs, ou à tuer des gens du peuple, et il fortifia Cédron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 41, 'Et il y mit des troupes et des chevaux, pour qu’ils fissent des sorties sur les routes de la Judée, comme le lui avait ordonné le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 1, 'Et Jean vint de Gazara, et il fit connaître à Simon son père ce que faisait Cendébée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 2, 'Et Simon appela ses deux fils aînés, Jean et Judas, et il leur dit: Moi et mes frères, et la maison de mon père, nous avons combattu les ennemis d’Israël, depuis notre jeunesse jusqu’à ce jour, et plus d’une fois nous avons réussi à sauver Israël par nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 3, 'Maintenant je suis vieux; mais vous, vous en êtes dignes par vos années et votre grand cœur; prenez ma place et celle de mon frère, marchez, combattez pour notre peuple, et que le Ciel vous soit en aide!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 4, 'Et il choisit dans la contrée vingt mille combattants et des chevaux; et ils marchèrent contre Cendébée, et ils couchèrent à Modin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 5, 'Et, s’étant levés dès l’aurore, ils allèrent dans la plaine, et voilà qu’une armée nombreuse de fantassins et de cavaliers était devant eux, et un torrent les en séparait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 6, 'Jean et sa troupe se déployèrent devant le front des ennemis; et il vit que le peuple hésitait à franchir le torrent, et il le passa le premier; et ses hommes le virent, et ils s’élancèrent après lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 7, 'Jean divisa son infanterie, et mit sa cavalerie au milieu; la cavalerie des ennemis était très-nombreuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 8, 'Alors les prêtres firent retentir les trompettes sacrées; Cendébée et son armée furent mis en déroute, et il tomba une multitude de blessés; le reste se réfugia dans la forteresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 9, 'Dans ce combat, Judas, frère de Jean, fut blessé; et Jean poursuivit les vaincus jusqu’à Cédron, qu’ils avaient fortifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 10, 'Ils s’enfuirent jusqu’aux tours qui sont dans les champs d’Azot, et Jean brûla Cédron; l’ennemi perdit deux mille hommes, et la Judée recouvra la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 11, 'Or Ptolémée, fils d’Abobi, avait été institué général en la plaine de Jéricho, et il avait beaucoup d’or et d’argent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 12, 'Car il était gendre du grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 13, 'Et son cœur s’enorgueillit, et il conçut le dessein de se rendre maître du pays, et il résolut de faire périr par trahison Simon et ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 14, 'Simon était alors à parcourir les villes des provinces et à s’occuper de leurs affaires, et il descendit à Jéricho avec ses fils Mattathias et Judas, l’an cent soixante-dix-sept, le onzième mois, qui est le mois de Sabat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 15, 'Le fils d’Abobi les accueillit traîtreusement dans le petit fort appelé Doc, qu’il avait bâti; et il leur donna un grand festin, et il y avait des hommes cachés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 16, 'Et lorsque Simon et ses fils furent étourdis par le vin, Ptolémée et les siens se levèrent, ils prirent leurs armes, ils assaillirent Simon qui était encore à table, et ils le tuèrent avec ses deux fils et quelques-uns de ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 17, 'Et il commit une grande trahison, et il rendit le mal pour le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 18, 'Alors Ptolémée écrivit au roi ce qui venait de se passer, et il lui envoya dire d’expédier une armée à son secours, pour qu’il lui livrât le pays et les villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 19, 'Et il envoya d’autres émissaires à Gazara pour tuer Jean, et il fit passer aux chefs de mille hommes des lettres, les invitant à le venir trouver, et promettant de leur donner de l’argent, de l’or et des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 20, 'Et il envoya d’autres émissaires pour surprendre Jérusalem et la montagne du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 21, 'Mais un homme ayant pris l’avance apprit à Jean en Gazara que son père et ses frères étaient morts, et que Ptolémée avait fait partir des gens pour le tuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 22, 'À cette nouvelle il fut frappé de stupeur; il prit les hommes qui arrivèrent pour le faire périr et il les mit à mort; car il savait qu’ils cherchaient à le tuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 23, 'Le reste des actions de Jean, de ses guerres, des hauts faits qu’il a accomplis, et l’énumération des remparts qu’il a bâtis, et tout ce qu’il a fait,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 24, 'Se trouvent au livre où est écrite l’histoire de son pontificat, à partir du jour où il devint grand prêtre à la place de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Aux frères Juifs qui sont en Égypte, salut. Les frères Juifs de Jérusalem et de la terre de Judée leur souhaitent une heureuse paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Que Dieu les bénisse, qu’il se souvienne de son alliance avec Abraham, Isaac et Jacob, ses fidèles serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Qu’il vous donne à tous un cœur pour que vous l’honoriez, et que vous fassiez sa volonté d’un grand cœur et d’une âme docile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Et qu’il ouvre vos cœurs à sa loi et à ses commandements; qu’il vous donne la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Qu’il exauce vos prières; qu’il se réconcilie avec vous, et qu’il ne vous abandonne point dans le temps mauvais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Et maintenant nous sommes ici à prier pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'L’an cent soixante-neuf, sous le règne de Démétrius, nous vous avons écrit dans l’affliction et dans les circonstances funestes qui nous sont survenues durant ces années où Jason et sa suite se sont éloignés de la terre sainte et du royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'On a brûlé les portes du temple; on a versé le sang innocent, et nous avons prié le Seigneur, et nous avons été exaucés; et nous avons offert des victimes et de la fleur de farine; nous avons allumé des lampes; nous avons déposé des pains sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Et maintenant nous vous avertissons, afin que vous célébriez la fête des Tabernacles du mois de Casleu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'L’an cent quatre-vingt-huit, nous, habitants de Jérusalem et de la Judée, et anciens de Judas, à Aristobule, précepteur du roi Ptolémée, qui est de la race des prêtres, ayant reçu l’onction sainte, et à ceux des Juifs de l’Égypte, salut et santé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Délivrés par Dieu de grands périls, nous lui en rendons de grandes actions de grâces; car nous avions à combattre un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Et c’est Dieu même qui avait fait surgir tous ceux qui ont pris les armes contre la ville sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Or ce prince, se trouvant en Perse avec une armée en apparence invincible, fut tué dans le temple de Nanée, au moment où, poussé par un esprit d’erreur, il consultait les prêtres de cette idole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'En effet, Antiochus avait été attiré en ce lieu, avec ses amis, comme pour épouser la déesse, et prendre en dot toutes ses richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Et les prêtres de Nanée, ayant étalé devant lui ses trésors, comme il était entré avec une faible escorte dans l’enceinte du temple, en ont fermé les portes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Aussitôt qu’il y eut pénétré; puis ils ont ouvert une porte cachée dans le lambris et ont écrasé le roi à coups de pierres, et, mettant sa suite en lambeaux, ils ont jeté membres et têtes à ceux du dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Que notre Dieu soit béni en toutes choses, puisqu’il a livré les impies!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 18, 'Songeant donc à célébrer, le vingt-cinq du mois de Casleu, la purification du temple, nous avons jugé nécessaire de vous le déclarer, afin que vous aussi vous célébriez la fête des Tabernacles et du feu qui brilla lorsque Néhémias, ayant rebâti le temple et l’autel, offrit un sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 19, 'Car lorsque nos pères furent emmenés en Perse, les prêtres pieux prirent en secret du feu de l’autel et le cachèrent au fond d’un puits sans eau, où ils le conservèrent avec sécurité, ce lieu étant inconnu de tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 20, 'Les années prescrites s’étant écoulées, au moment où Dieu le jugea à propos, Néhémias, congédié par le roi de Perse, envoya les descendants des prêtres qui avaient caché le feu pour le reprendre. Or ils déclarèrent n’avoir point trouvé de feu, mais une eau bourbeuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 21, 'Et il leur ordonná d’en puiser et de l’apporter. Et lorsque le sacrifice fut offert, il dit aux prêtres d’arroser de cette eau le bûcher et les victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 22, 'Ils obéirent; puis vint un moment où, d’abord voilé de nuages, le soleil brilla; et le bûcher fut enflammé, avec une telle vivacité, que tous les assistants en furent saisis de surprise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 23, 'Et les prêtres prièrent pendant que la victime était consumée, Jonathas parlant le premier, et les autres répondant');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 24, 'Comme Néhémias. Et telle fut leur prière: Seigneur, Seigneur, Dieu créateur de toutes choses, Dieu redoutable et tout-puissant, juste et miséricordieux, seul bon, seul roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 25, 'Seul dispensateur de toutes choses, seul juste, tout-puissant et éternel, sauveur d’Israël en tous ses maux; vous qui avez élus nos pères, et qui les avez sanctifiés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 26, 'Accueillez le sacrifice que vous offre tout votre peuple d’Israël, et gardez votre part, et sanctifiez-la.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 27, 'Rassemblez ceux de nous qui sont dispersés; déliez ceux qui sont captifs chez les gentils; regardez ceux que l’on tient pour méprisés et abominables; que les nations connaissent que vous êtes notre Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 28, 'Châtiez nos oppresseurs dans leur superbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 29, 'Enracinez votre peuple dans le lieu saint, selon la parole de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 30, 'Et les prêtres chantaient des hymnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 31, 'Puis lorsque le sacrifice fut consommé, Néhémias ordonna de répandre le reste de l’eau sur les grandes pierres de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 32, 'Et dès que le sacrifice fut accompli, la flamme s’alluma; mais elle fut absorbée par une lumière qui brilla sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 33, 'L’événement se divulgua, et l’on rapporta au roi de Perse que dans le lieu où les prêtres emmenés captifs avaient caché le feu, on n’avait trouvé que de l’eau, et que les hommes de la suite de Néhémias l’avaient employée pour purifier les victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 34, 'Alors le roi, ayant réfléchi sur cette affaire, entoura le puits d’une enceinte et en fit un lieu sacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 35, 'Et, plein de bienveillance pour Néhémias et les siens, il choisit beaucoup d’objets précieux, et il les leur distribua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 36, 'Et les compagnons de Néhémias nommèrent ce lieu Nephthar, ce qui veut dire Purification; mais beaucoup l’appellent Nephthaï.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'On voit dans les écrits de Jérémie le prophète qu’il recommanda à ceux que l’on emmenait captifs de prendre le feu; on y voit quels ordres ont été donnés, et ce que le prophète prescrivit aux émigrants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Après leur avoir rappelé la loi, de peur qu’ils ne vinssent à oublier les commandements du Seigneur, et à tomber dans l’égarement de l’esprit à la vue des idoles d’argent et d’or, et de leurs ornements;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Après leur avoir dit d’autres choses semblables, il les adjura de ne point détourner leur cœur de la loi de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'On voit encore dans ces écrits comment le prophète, ayant eu une révélation, ordonna que le tabernacle et l’arche le suivissent, lorsqu’il s’en alla sur la montagne d’où Moïse avait contemplé l’héritage de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Et Jérémie, y étant venu, trouva une retraite caverneuse où il transporta le tabernacle, l’arche et l’autel des parfums; après quoi il en ferma l’ouverture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Or quelques-uns de ceux qui l’avaient accompagné, y étant retournés pour reconnaître le chemin, ne purent le retrouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Dès que Jérémie le sut, il les réprimanda et leur dit: Ce lieu restera inconnu jusqu’à ce que Dieu s’apaise et réunisse la synagogue du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Alors, ajouta-t-il, le Seigneur dévoilera toutes ces choses, et la gloire du Seigneur et la nuée apparaîtront, comme elles se sont montrées à Moïse, et comme Salomon les a demandées, afin que le lieu saint fût magnifiquement sanctifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Ainsi se manifestait la sagesse avec laquelle il avait offert le sacrifice de la dédicace et de l’achèvement du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Tel, lorsque Moïse eut prié le Seigneur, le feu descendit du ciel et consuma les victimes; tel, lorsque Salomon eut prié, le feu descendit et dévora les holocaustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Et Moïse dit: Parce que la victime pour le péché n’a point été mangée, elle a été consumée par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'De même Salomon célébra durant huit jours la dédicace du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Or ces mêmes choses ont été aussi racontées dans les écrits et mémoires sur Néhémias; l’on y dit encore comment, ayant fondé une bibliothèque, il y rassembla ce que l’on avait écrit des rois et des prophètes, les œuvres de David, et les lettres des rois sur leurs offrandes au temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Judas a pareillement recueilli tous les récits qui se sont répandus pendant nos guerres, et ce recueil est dans nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Si donc vous avez besoin de quelques-uns de ces écrits, envoyez-nous des gens pour les emporter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'C’est en songeant à la fête de la Purification que nous vous avons écrit; aussi ferez-vous bien de la célébrer comme nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'C’est Dieu qui a sauvé tout son peuple, qui a rendu à chacun de nous son héritage, et à nous tous le royaume, le sacerdoce et le temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 18, 'Comme il l’avait promis dans la loi; et nous');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 19, 'Car il nous a sauvés de grandes calamités, et il a purifié le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 20, 'Or tout ce qui concerne Judas Machabée et ses frères, et la purification du temple, et la dédicace de l’autel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 21, 'Et les guerres soutenues tant contre Antiochus Épiphane que contre son fils Eupator;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 22, 'Et toutes les manifestations du Ciel en faveur des Juifs, leur dévouement et leur courage, puisqu’en si petit nombre ils ont enlevé du butin dans toute la contrée, chassé la multitude des barbares,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 23, 'Recouvré un temple si fameux par toute la terre habitée, affranchi la ville et rétabli les lois qui allaient tomber en désuétude, grâce à la bonté du Seigneur, qui leur était devenu propice;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 24, 'Tout ce que Jason de Cyrène avait publié en cinq livres, nous avons tenté de l’abréger en un seul ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 25, 'Car nous avons considéré le flot des choses qui s’écrivent et la difficulté qu’éprouvent, à cause de l’abondance des matières, ceux qui veulent entreprendre les récits de l’histoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 26, 'Nous avons eu en vue ceux qui veulent lire pour se distraire, comme ceux qui se plaisent à retenir facilement de mémoire; enfin nous avons eu dessein d’être utiles à tous ceux qui auront ce livre entre les mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 27, 'Et nous nous sommes chargés d’une pénible tâche; car il n’est point facile d’abréger: on n’y parvient pas sans sueurs et sans veilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 28, 'Comme celui qui prépare un festin et cherche le plaisir d’autrui, quoique ce ne soit point chose facile; ainsi, pour l’agrément et la joie de plusieurs, nous nous résignerons volontiers à la difficulté de l’œuvre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 29, 'Quant à l’exactitude des faits, nous nous soumettons à chacun de ceux qui les ont écrits, et nous nous appliquerons seulement à abréger leur ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 30, 'Car l’architecte d’une maison neuve doit imaginer l’ensemble de la construction, tandis que l’artiste qui la restaure ou qui la peint, n’a plus à s’occuper que de l’embellir. Ainsi je pense qu’il en est de même pour nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 31, 'Car d’une part pénétrer dans une suite de faits et en faire le récit, c’est rechercher avec beaucoup de soin les moindres particularités, et c’est le devoir de celui qui le premier écrit une histoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 32, 'D’autre part, entreprendre d’abréger ce qui a été dit, sans nuire à l’exactitude de l’œuvre, c’est le but de celui qui fait un résumé. Mais il est temps de commencer le récit, et de mettre un terme à la préface; car il serait étrange de prolonger la préface d’une histoire, quand on en abrège le récit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'La ville sainte était donc repeuplée; on y jouissait d’une paix profonde, et les lois étaient religieusement observées, grâce à la piété du grand prêtre Onias et à sa haine du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Il s’ensuivait que les rois eux-mêmes honoraient le lieu saint, et qu’ils glorifiaient le temple par des envois de très-grand prix;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Au point que Séleucus, roi d’Asie, subvenait de ses revenus propres à la dépense du culte et des sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Toutefois Simon, de la tribu de Benjamin, institué préfet du temple, essaya de faire quelque entreprise dans la ville contre le grand prêtre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Et, ne pouvant vaincre Onias, il alla trouver Apollonius, fils de Tharsée, qui en ce temps-là était général de la Colé-Syrie et de la Phénicie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Il lui dit qu’il y avait d’immenses richesses dans le trésor de Jérusalem, qu’on n’en pouvait calculer l’intérêt, qu’elles n’étaient pas employées aux frais des sacrifices, et qu’il serait possible de les faire tomber au pouvoir du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Or Apollonius, dans une entrevue avec le roi, lui signala les richesses qu’on lui avait dénoncées, et le roi, ayant fait choix d’Héliodore, son premier ministre, lui donna des ordres et l’envoya pour enlever les richesses dont on lui avait parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Héliodore aussitôt se mit en route, sous prétexte de parcourir les villes de la Colé-Syrie et de la Phénicie, mais réellement pour exécuter les desseins du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Il arriva à Jérusalem et fut amicalement accueilli par le grand prêtre de la ville; il lui dit alors ce que Simon avait révélé, et pourquoi lui-même était venu, lui demandant si, en vérité, les choses étaient ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'À ces mots, le grand prêtre lui montra que c’étaient les dépôts des veuves et des orphelins;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Qu’une grosse somme appartenait à Hyrcan, fils de Tobie, homme haut placé; que le trésor n’était point ce qu’avait rapporté l’impie Simon, qu’il consistait seulement en quatre cents talents d’argent et deux cents talents d’or;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 12, 'Qu’enfin il était absolument impossible de faire tort à ceux qui avaient mis leur confiance dans la sainteté du lieu, dans la majesté et l’inviolabilité d’un temple honoré du monde entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 13, 'Mais Héliodore, conformément aux ordres qu’il avait reçus du roi, répondit que toutes ces sommes devaient être enlevées pour le trésor royal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 14, 'Ayant donc fixé le jour, il vint pour diriger l’inspection de ces richesses. Cependant grande était l’anxiété dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 15, 'Les prêtres s’étaient jetés au pied de l’autel, en costume sacerdotal, et ils invoquaient dans les cieux le Législateur des dépôts, pour qu’il sauvât ce qui appartenait à ceux qui s’étaient fiés à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 16, 'Quiconque voyait le visage du grand prêtre en avait le cœur déchiré; car sa pâleur et l’altération de ses traits marquaient l’angoisse de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 17, 'La crainte qui se peignait en lui et le frémissement de son corps manifestaient aux yeux des spectateurs la douleur dont son cœur était rempli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 18, 'On sortait tumultueusement des maisons pour faire des prières publiques; car le temple était près de tomber dans le mépris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 19, 'Les femmes en foule accouraient dans les rues, le sein couvert de cilices; les vierges mêmes qui vivent renfermées s’en allaient, les unes aux portes, les autres vers les murs; quelques-unes se penchaient pour regarder par les fenêtres.,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 20, 'Toutes étendaient les mains vers le ciel, et priaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 21, 'C’était pitié de voir l’accablement de cette multitude confuse, et l’appréhension du grand prêtre dans une telle angoisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 22, 'Les prêtres suppliaient le Dieu tout-puissant de conserver les dépôts que les fidèles avaient faits en toute sécurité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 23, 'De son côté, Héliodore exécutait ce qui lui était prescrit. Dans le moment même où déjà, avec ses satellites, il était près du trésor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 24, 'Le Seigneur de nos pères, le maître de toutes les richesses, fit une grande manifestation, afin que tous ceux qui avaient osé pénétrer dans le temple, renversés par la vertu de Dieu, fussent frappés de crainte et de défaillance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 25, 'Un cheval leur apparut, monté par un cavalier terrible, resplendissant d’une magnifique armure, et, se précipitant avec fracas, il frappa Héliodore de ses pieds de devant; et l’on vit que les armes du cavalier étaient d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 26, 'Et devant lui parurent deux autres hommes, jeunes, brillants de force, magnifiques en leur gloire et merveilleusement ornés, et se plaçant des deux côtés d’Héliodore, ils le flagellèrent sans relâche, et lui firent une multitude de plaies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 27, 'Aussitôt qu’il fut tombé à terre et que les ténèbres l’eurent enveloppé, ses gens, le saisissant, le mirent dans une litière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 28, 'Et lui qui venait d’entrer avec le cortége de tous ses satellites dans le trésor qu’on lui avait signalé, ses gens, connaissant manifestement la puissance de Dieu, l’emportèrent dénué de tout secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 29, 'Frappé par la force divine, il était là gisant sans espoir et sans vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 30, 'Cependant le peuple bénissait Dieu, qui venait de glorifier son temple. Et le temple, qui tout à l’heure était plein de trouble et de terreur, dès que le Seigneur tout-puissant se fut manifesté, fut rempli de joie et de reconnaissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 31, 'Quelques-uns des amis d’Héliodore ne tardèrent pas à demander à Onias d’invoquer le Très-Haut, pour qu’il accordât la vie à cet homme qui était encore étendu près de rendre le dernier soupir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 32, 'Le grand prêtre, craignant que le roi n’eût l’idée que l’un des Juifs avait usé de maléfices envers Hélio dore, sacrifia une victime pour son salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 33, 'Or lorsque le grand prêtre eut fait un sacrifice propitiatoire, les mêmes jeunes hommes se montrèrent à Héliodore, vêtus des mêmes habits, et, se tenant debout, ils dirent: Tu dois beaucoup d’actions de grâces à Onias; car c’est à cause de lui que le Seigneur t’accorde de vivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 34, 'Toi donc qu’il a flagellé, fais connaître à tous les grandeurs du Seigneur tout-puissant. Ayant dit ces mots, ils devinrent invisibles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 35, 'De son côté, Héliodore, après avoir offert un sacrifice au Seigneur et fait de ferventes prières à Celui qui lui avait accordé de vivre, rendit grâces à Onias, et retourna auprès du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 36, 'Et devant tous il porta témoignage des œuvres du Dieu très-grand, qu’il avait vues de ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 37, 'Et le roi, ayant demandé à Héliodore qui il pourrait encore envoyer à Jérusalem, il répondit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 38, 'Si tu as un ennemi ou un serviteur perfide, envoie-le, et tu le reverras flagellé, si toutefois il échappe; car en ce temple est véritablement la vertu de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 39, 'Celui qui réside au ciel est le visiteur et le protecteur de ce lieu; il frappe et il perd ceux qui y vont avec de mauvais desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 40, 'Voilà donc ce qui advint d’Héliodore, et comment le trésor fut sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Cependant ce même Simon, le délateur des richesses et de sa patrie, dénonçait Onias comme étant lui-même l’instigateur d’Héliodore et l’auteur de tous les maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'I osait accuser de perfidie le bienfaiteur de la ville, le tuteur de ses concitoyens, le zélateur de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Sa haine fut portée au point que des meurtres furent même commis par quelques-uns de ceux qu’il favorisait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Onias, considérant le danger de cette ardeur de querelles et les fureurs d’Apollonius, général de la Cœlé-Syrie et de la Phénicie, qui renforçait la méchanceté de Simon, alla trouver le roi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Non qu’il fût devenu l’accusateur de quelques citoyens, mais ayant pour but l’utilité publique et spécialement celle de la masse du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Car il voyait que sans l’autorité prévoyante du roi il lui serait impossible de rétablir la paix, et de contenir les folles entreprises de Simon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Mais après la mort de Séleucus et l’avènement d’Antiochus Épiphane, Jason, frère d’Onias, obtint frauduleusement le souverain sacerdoce,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'En promettant au roi, dans une entrevue, trois cent soixante talents d’argent, outre quatre-vingts talents de diverses redevances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Il promit de plus cent cinquante autres talents, si on l’autorisait à établir un gymnase, d’élever les jeunes gens et d’inscrire les habitants de Jérusalem comme citoyens d’Antioche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Le roi y consentit; Jason saisit le pouvoir, et entreprit aussitôt de former ses concitoyens aux mœurs helléniques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Il répudia les édits bienveillants des rois obtenus pour les Juifs par Jean, père d’Eupolème, qui avait été de l’ambassade à Rome, chargée de conclure le traité d’amitié et d’alliance; il abolit les droits légitimes des citoyens, et il établit des coutumes contraires aux lois;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Car il mit beaucoup d’ardeur à fonder un gymnase dans les dépendances mêmes de la citadelle, et il entraîna les jeunes gens des meilleures familles à vivre en efféminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Aussi y eut-il un luxe d’hellénisme et une imitation de l’étranger, introduits par l’impureté triomphante de l’impie et faux grand prêtre Jason.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Ce fut au point que les prêtres n’eurent plus de zèle pour le service de l’autel; ils prirent en mépris le temple; ils négligèrent les sacrifices; ils s’empressèrent comme spectateurs aux exercices coupables de la palestre et du disque;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Comptant pour rien ce que vénéraient leurs pères, et préférant tout ce dont les Grecs se faisaient gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'À cause de cela, ils furent frappés d’une grave infortune; et ceux dont ils imitaient les mœurs, ceux auxquels ils voulaient ressembler en tout, ceux-là mêmes devinrent leurs ennemis, chargés de les punir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 17, 'Car on ne renonce pas impunément aux lois divines, et les temps qui vont suivre le feront voir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 18, 'On célébrait à Tyr des jeux qui reviennent tous les cinq ans, et le roi y assistait,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 19, 'Et l’infâme Jason y envoya, comme théores, des habitants de Jérusalem, qui s’étaient faits Antiochiens, portant trois cents drachmes d’argent pour un sacrifice à Hercule; or ces hommes demandèrent de ne les point employer à un sacrifice si peu convenable, et de les consacrer à une autre dépense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 20, 'Ainsi Jason les avait destinées à un sacrifice en l’honneur d’Hercule; mais ses envoyés les firent appliquer à construire des trirèmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 21, 'Cependant Apollonius, fils de Mnesthée, ayant été envoyé en Égypte à l’occasion de l’avènement du roi Ptolémée Philométor, Antiochus comprit qu’il était resté jusque-là étranger à ses propres affaires, et songea à veiller par lui-même à ses propres intérêts. Il partit donc pour Joppé, d’où il se rendit à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 22, 'Il y fut magnifiquement accueilli par Jason et les habitants; la ville était illuminée quand il y entra, et les acclamations furent universelles; il en sortit de même, et alla en Phénicie avec son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 23, 'Trois ans plus tard, Jason envoya Ménélas, frère de Simon, dont il a été parlé précédemment, pour porter au roi de l’argent et prendre des renseignements sur des affaires importantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 24, 'Or Ménélas, s’étant entretenu avec le roi et l’ayant flatté sur sa puissance, obtint pour lui-même le souverain sacerdoce, en donnant trois cents talents d’argent de plus que Jason.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 25, 'Il prit donc l’ordre du roi qui l’instituat, et s’en retourna, n’ayant rien qui fût digne d’un grand prêtre, mais l’âme d’un tyran cruel et les fureurs d’une bête farouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 26, 'Quant à Jason, après avoir supplanté son frère, il fut lui-même supplanté, puis chassé, et se réfugia chez les Ammonites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 27, 'Cependant Ménélas, en possession du pouvoir, ne remplit pas ses promesses et n’envoya point d’argent au roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 28, 'Quoique Sostrate, commandant de la citadelle, lui en eût fait demander, car il était chargé de faire rentrer les impôts; alors tous les deux furent appelés devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 29, 'Et Ménélas fut destitué du sacerdoce, où son frère Lysimaque le remplaça, et Sostrate fut nommé gouverneur des Cypriotes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 30, 'Comme ces choses se passaient, Tarsis et Mallo se révoltèrent, parce que le roi les avait données à sa concubine Antiochide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 31, 'Antiochus y courut pour les réprimer, et mit à la tête des affaires Andronique, l’un de ses grands dignitaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 32, 'Ménélas crut l’occasion favorable; il déroba du temple des vases précieux, et les donna à Andronique; quant aux autres, il les avait vendus à Tyr et dans les villes voisines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 33, 'Onias, qui s’était retiré à Daphné, faubourg d’Antioche, en un lieu d’asile, ayant été sûrement informé de cette conduite, réprimanda Ménélas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 34, 'Alors celui-ci prit à part Andronique et l’exhorta à s’emparer d’Onias; Andronique l’alla trouver, le persuada par ses artifices, lui tendit la main et lui prêta serment; et, malgré ses soupçons, il l’entraîna à sortir de son asile; Onias n’en fut pas plutôt sorti que, sans respect pour la justice, il le fit tuer en prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 35, 'Mais non-seulement les Juifs, mais beaucoup de gentils s’indignèrent et montrèrent leur mécontentement au sujet du meurtre inique d’un tel homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 36, 'Sur ces entrefaites, le roi revint de Cilicie, et les Juifs d’Antioche, auxquels se joignirent les Grecs, comme eux ennemis des méchants, l’abordèrent et l’entretinrent de ce que l’on disait de la mort d’Onias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 37, 'Antiochus, affligé en son âme, et touché de pitié, versa des larmes à cause de la sagesse et de la modération du défunt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 38, 'Et soudain, enflammé de colère, il dépouilla Andronique de la pourpre, il mit en pièces sa tunique, il le fit conduire à travers toute la ville au lieu même où il avait été criminel envers Onias, et là il fit tuer l’homicide, à qui le Seigneur infligea un châtiment digne de son crime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 39, 'Il y eut aussi plusieurs détournements sacriléges commis dans la ville sainte par Lysimaque, sur le conseil de Ménélas; et, le bruit s’en étant répandu, la multitude se souleva contre Lysimaque, qui avait déjà enlevé un grand nombre d’objets précieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 40, 'La foule ameutée étant pleine de fureur, Lysimaque arma trois mille hommes, et commença à se servir de ces mains iniques, leur ayant donné pour chef un certain tyran aussi avancé en âge et non moins extravagant que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 41, 'Le peuple vit la tentative de Lysimaque; aussitôt les uns saisirent des pierres, d’autres de gros bâtons, d’autres des poignées de cendre, et tous se jetèrent pêle-mêle sur les gens de Lysimaque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 42, 'Ils en blessèrent beaucoup, ils en tuèrent quelques-uns; ils les mirent tous en fuite, et massacrèrent dans le trésor le profanateur du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 43, 'Ainsi commença le jugement contre Ménélas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 44, 'Et le roi étant venu à Tyr, trois hommes lui furent envoyés par les anciens et plaidèrent la cause du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 45, 'Ménélas, se voyant abandonné, promit une grosse somme à Ptolémée, fils de Dorymène, pour fléchir le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 46, 'Ptolémée saisit le moment où le roi prenait l’air sous un péristyle, et il lui fit changer d’avis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 47, 'Et le roi gracia Ménélas, coupable de toutes les méchancetés, et il condamna à mort des infortunés qui eussent été reconnus innocents s’ils avaient plaidé leur cause devant des Scythes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 48, 'Ainsi subirent une prompte et injuste punition ceux qui avaient parlé en faveur de la ville, du peuple et des vases sacrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 49, 'C’est pourquoi les Tyriens, indignés de ce crime, leur firent de magnifiques funérailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 50, 'Cependant Ménélas, grâce à l’avidité d’hommes puissants, conserva le pouvoir, croissant en malice et tendant des piéges aux citoyens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Vers ce temps-là, Antiochus fit les apprêts d’une seconde expédition en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Or voici ce qui advint pendant environ quarante jours, des cohortes de cavaliers apparurent dans l’air, courant au-dessus de toute la ville, vêtus de robes d’or et armés de javelines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Des groupes de chevaux s’avançaient en bon ordre; ils se chargeaient, ils s’élançaient les uns contre les autres; et l’on voyait des boucliers se heurter, une multitude de dards et de glaives s’agiter en tous sens, des flèches voler, des armes d’or et des cuirasses lancer leur éclat de toutes parts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'C’est pourquoi tout le monde priait pour que cette apparition tournât à bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Cependant il se répandit un faux bruit de la mort d’Antiochus; alors Jason, prenant avec lui pour le moins mille hommes, attaqua inopinément la ville. Les hommes coururent aux remparts; mais il s’en rendit maître, et Ménélas se réfugia dans la citadelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Aussitôt Jason fit, sans épargner personne, un grand massacre de ses concitoyens, ne songeant pas que le succès contre des proches est le plus grand des malheurs. Il s’imaginait avoir remporté des trophées sur des ennemis, et non sur des hommes de sa race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Toutefois il ne put ressaisir le pouvoir; il ne recueillit que la honte de son mauvais dessein, et se retira encore une fois chez les Ammonites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Mais, par malheur pour lui, il fut emprisonné par ́Arétas, roi des Arabes; puis il s’enfuit de ville en ville, pourchassé par tous, haï comme déserteur de sa loi, abominable comme bourreau de sa patrie et ennemi de ses concitoyens, jusqu’à ce qu’il arrivât en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Enfin celui qui avait exilé de sa patrie un si grand nombre d’hommes mourut en exil chez les Lacédémoniens, où il avait espéré trouver un refuge à cause de sa parenté avec eux.··');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Et celui qui avait privé de la sépulture un si grand nombre de victimes ne fut point pleuré; on ne lui fit point de funérailles, et il n’eut point place au sépulcre de ses pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Cette affaire étant venue aux oreilles du roi, il soupçonna que les Juifs se détachaient de lui. C’est pourquoi il partit d’Égypte l’âme pleine d’une fureur sauvage, et il entra dans la ville comme s’il l’eût prise d’assaut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Et il ordonna à ses satellites de tuer sans merci tous ceux qu’ils rencontreraient, et d’égorger même ceux qui se sauveraient dans leurs maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Il y eut alors un horrible massacre de jeunes gens et de vieillards, une extermination d’hommes, de femmes et d’enfants, un carnage de vierges et d’enfants au berceau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Durant trois jours entiers il y eut huit myriades d’habitants massacrés, dont quatre dans la mêlée les armes à la main; et il y en eut de vendus presque autant que d’égorgés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Et, non content de ces massacres, Antiochus osa entrer dans le temple le plus saint de toute la terre, ayant pour guide Ménélas, traître à sa patrie et à ses lois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Et de ses mains impures prenant les vases sacrés et tout ce que les autres rois avaient offert pour ajouter à la gloire et à l’éclat du lieu saint, il les distribua avec mépris entre des mains profanes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 17, 'Et Antiochus s’enorgueillit en son âme; car il ne vit pas que le souverain Maître était irrité des péchés qui se commettaient dans la ville, et que de là venait l’humiliation du lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 18, 'Autrement, si les habitants eux-mêmes n’eussent été coupables de beaucoup de péchés, comme Héliodore envoyé précédemment par le roi Séleucus pour piller le trésor, il eût été soudain fouetté, chassé et puni de son audace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 19, 'Mais Dieu n’a pas choisi le peuple à cause du temple, il a choisi le temple à cause du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 20, 'Aussi le lieu lui-même a eu part à toutes les afflictions du peuple, comme il a eu part ensuite aux bienfaits du Seigneur. Et s’il a été abandonné pendant la colère du Tout-Puissant, il a été relevé dans toute sa gloire lorsque le souverain Maître se fut réconcilié avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 21, 'Antiochus, ayant donc enlevé du temple dix-huit cents talents, retourna à Antioche, s’imaginant en son orgueil et dans l’égarement de son esprit qu’il rendrait la terre navigable et la mer viable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 22, 'Il laissa des officiers avec mission de maltraiter le peuple à Jérusalem, Philippe, d’origine phrygienne, de mœurs plus barbares que celui qui l’avait nommé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 23, 'À Garizin, Andronique, et en outre Ménélas, le pire de tous à l’égard de ses concitoyens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 24, 'Le roi, étant donc tout disposé à déployer, sa haine contre les Juifs, mit en campagne Apollonius, le chef de toutes les atrocités, à la tête de vingt-deux mille hommes, lui ordonnant de tuer les hommes avancés en âge, et de vendre les jeunes gens et les femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 25, 'Celui-ci entra dans Jérusalem, affectant des manières pacifiques, et il se posséda jusqu’au jour saint du sabbat. Puis, profitant du moment où les Juifs observaient le repos prescrit, il commanda à ses gens de s’armer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 26, 'Et il perça de coups tous ceux qui sortirent pour les regarder, et, parcourant toute la ville les armes à la main, il renversa une multitude de morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 27, 'Or à cette époque Judas Machabée, lui dixième, s’était retiré dans le désert, vivant dans les montagnes avec les siens à la manière des bêtes fauves, se nourrissant d’herbes plutôt que de se souiller d’aliments impurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Peu de temps après, le roi envoya le vieillard Athénée pour contraindre les Juifs à abandonner les coutumes de leurs pères, et leur défendre de vivre selon les lois de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Bien plus, il souilla le temple de Jérusalem, et le surnomma temple de Jupiter-Olympien, et donna à celui de Garizin le nom de Jupiter-Hospitalier, parce que tous ceux qui habitaient cette ville étaient étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Et ce surcroît de maux fut pour le peuple bien cruel et difficile à supporter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Car le temple était rempli d’orgies et de débauches par des gentils dissolus et des filles impudiques; et des hommes pénétraient mêlés avec des femmes dans les saints parvis, et ils apportaient des choses défendues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Et l’autel était couvert de chairs impures que la loi interdisait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Il n’était plus possible de célébrer les sabbats, ni les fêtes de nos pères, ni simplement de confesser que l’on était Juif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Une amère nécessité amenait les fidèles aux sacrifices mensuels qui se faisaient le jour de la naissance du roi et aux fêtes des Bacchanales; on les contraignait de marcher en pompe avec des lierres en l’honneur de Bacchus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Un édit fut rendu, à l’instigation des Ptoléméens, pour que dans les villes grecques voisines on obligeât les Juifs à célébrer les mêmes fêtes et à sacrifier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Et que l’on égorgeât ceux qui ne se soumettraient pas aux coutumes grecques; on voyait donc partout régner la désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Ainsi deux femmes furent convaincues d’avoir circoncis leurs enfants; on les prit, on suspendit leurs enfants à leurs mamelles, on les entraîna par la ville, et on les précipita du haut des remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'D’autres étaient ensemble dans les cavernes du voisinage pour y célébrer en secret le septième jour; dénoncés à Philippe, ils furent tous brûlés; car ils n’osèrent se défendre, selon leur croyance et la sainteté du jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Je supplie ceux qui liront ce livre de ne point le repousser à cause de ces tristes événements, et de croire que ces persécutions eurent lieu non pour la ruine, mais pour la punition de notre race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Quand Dieu ne permet pas que l’on vive longtemps dans le péché, et qu’il ne tarde pas à en infliger le châtiment, c’est une grande marque de bonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 14, 'En effet, le souverain Maître n’agit point alors comme avec tous les gentils; car il attend pour les punir qu’ils aient comblé la mesure des péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 15, 'Tandis que, pour nous, il a jugé à propos d’agir comme il le fait, afin d’éviter de nous châtier plus tard, lorsque nous aurions atteint la plénitude des offenses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 16, 'C’est pourquoi il ne détourne jamais de nous sa miséricorde; et, en nous éprouvant par le malheur, il n’abandonne point son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 17, 'Mais que cela suffise pour notre instruction; après ce peu de mots il faut revenir à notre récit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 18, 'Éléazar, l’un des premiers scribes, homme déjà avancé en âge et du plus noble extérieur, fut contraint, la bouche ouverte de force, de manger de la chair de pourceau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 19, 'Mais lui, préférant une mort glorieuse à une vie criminelle, s’exposa volontairement au supplice;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 20, 'Et il cracha ce qu’il ne se croyait pas permis de goûter même pour sauver sa vie, regardant comme peu de chose ce qu’il lui faudrait souffrir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 21, 'Les préposés à ce sacrifice impie, depuis longtemps liés d’amitié avec lui, le prirent à part, et lui apportèrent des viandes cuites dont il lui était licite de faire usage, et l’invitèrent à feindre d’avoir mangé des chairs de la victime, comme le roi l’avait ordonné,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 22, 'Afin que, cela fait, il fût préservé de la mort; cette bienveillance leur était inspirée par leur ancienne affection pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 23, 'Mais Éléazar fit de sages réflexions dignes de son âge, de sa glorieuse vieillesse, de son heureux naturel, de ses beaux cheveux blancs et de la vie pure qu’il avait menée depuis l’enfance; et il n’hésita pas à dire qu’on le conduisit à la mort, se montrant serviteur fidèle des saintes lois de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 24, 'Car, dit-il, à mon âge il ne convient pas de feindre, de peur que des jeunes gens ne soupçonnent Éléazar d’avoir, à quatre-vingt-dix ans, embrassé les mœurs étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 25, 'Eux-mêmes alors, à cause de ma dissimulation pour conserver un reste de vie, seraient égarés; et j’aurais fait maudire ma vieillesse en la déshonorant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 26, 'Et quand j’échapperais pour le présent à la vengeance des hommes, vivant ou mort, je n’éviterais pas les mains du Tout-Puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 27, 'C’est pourquoi, si je meurs à présent avec courage, du moins je me montrerai digne de ma vieillesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 28, 'Je laisserai aux jeunes gens un noble exemple, puisque je serai mort noblement et sans hésiter pour nos lois saintes et vénérables. Ayant ainsi parlé, il marcha droit au supplice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 29, 'Ceux qui l’y conduisirent changèrent en dureté la douceur qu’ils avaient eue un moment; car les paroles qu’il venait de dire étaient, croyaient-ils, pleines d’arrogance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 30, 'Et, près de mourir sous leurs coups, il soupira, et dit: Le Seigneur, qui a la science sainte, voit que, maître d’échapper à la mort, je supporte, flagellé comme je suis, des douleurs cruelles selon la chair, mais qu’en mon âme je les souffre avec joie, par crainte de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 31, 'Il mourut donc de cette manière, laissant par sa mort, non-seulement à la jeunesse, mais à la plupart des gentils, un exemple de fermeté et de vertu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Or il advint aussi que, par ordre du roi, on voulut, en les déchirant à coups de fouet et de nerfs de bœuf, contraindre sept frères qu’on avait enlevés avec leur mère, à manger de la chair interdite de pourceau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'L’un d’eux, prenant la parole au nom de tous: Que demandes-tu? dit-il; que veux-tu apprendre de nous? Nous sommes prêts à mourir plutôt que de transgresser la loi de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Le roi, courroucé, commanda de mettre sur le feu des poêles et des chaudières. Et aussitôt qu’elles furent brûlantes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Il commanda de couper la langue à celui qui avait parlé; puis, après avoir enlevé la peau de sa tête, de lui couper le bout des pieds et des mains, devant sa mère et ses autres frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Lorsqu’on l’eut ainsi mutilé, il commanda qu’on le menât vers le feu, respirant encore, et qu’on le fit rôtir. Pendant le temps assez long où la vapeur s’exhala de la poêle, sa mère et ses frères s’encouragèrent mutuellement à mourir avec courage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Disant Le Seigneur Dieu voit la vérité, et il sera consolé en nous, comme Moïse l’a révélé dans son cantique, où il porte témoignage et dit: Il sera consolé en ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Le premier étant mort de cette manière, on livra le second aux bourreaux avec dérision; et après lui avoir enlevé la peau de la tête avec les cheveux, ils lui demandèrent s’il voulait manger du porc avant d’être torturé dans tous les membres de son corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Or il répondit en la langue de ses pères, et dit: Non. A cause de quoi il subit aussitôt les mêmes tortures que le précédent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Au moment de rendre le dernier soupir, il dit: Scélérat que tu es, tu m’ôtes la vie présente; mais le Roi de l’univers nous ressuscitera pour la vie éternelle, nous qui mourons à cause de ses lois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Après celui-là, on insulta au troisième; on lui demanda sa langue; il la présenta aussitôt, et il étendit ses mains sans hésiter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Et il dit courageusement: Je les tiens du ciel; mais à cause des lois de Dieu, je les méprise, et j’ai l’espérance que par sa volonté je les recouvrerai un jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'De sorte que le roi et les siens admiraient la fermeté de ce jeune homme et son mépris des souffrances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Celui-là mort, on tourmenta le quatrième des mêmes tortures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'Et au moment d’expirer, il dit: Heureux qui meurt de la main des hommes, plein de l’espérance qui vient de Dieu; Dieu le ressuscitera. Pour toi, ta résurrection ne sera point pour la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 15, 'Le cinquième vint ensuite, et on le tortura également; mais lui, regardant le roi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 16, 'Tu as pouvoir, lui dit-il, sur les hommes; quoique mortel toi-même, tu fais ce que tu veux; mais ne crois pas que notre race soit abandonnée de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 17, 'Attends, et tu verras sa souveraine puissance, et il te tourmentera de même toi et ta race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 18, 'Après celui-là, ils amenèrent le sixième; et au moment d’expirer il dit: Ne te trompe pas vainement; nous nous sommes attiré nous-mêmes ces souffrances, nous avons péché contre notre Dieu; c’est pourquoi ces choses dignes d’épouvante nous arrivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 19, 'Mais ne t’imagine pas que tu seras impuni, après avoir osé combattre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 20, 'Cependant, admirable au-dessus de toute expression, et digne d’une illustre mémoire, la mère, voyant périr ses sept fils en un seul jour, supporta leur supplice avec une âme généreuse, soutenue par son espérance dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 21, 'Elle exhortait chacun d’eux en la langue de ses pères, et, pleine d’un noble courage, alliait le courage d’un homme avec la tendresse d’une femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 22, 'Elle leur disait: Je ne sais comment vous avez été conçus en mes entrailles; ce n’est point moi qui vous ai donné ni l’esprit ni la vie; ce n’est point moi qui ai assemblé vos membres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 23, 'C’est pourquoi le Créateur du monde, celui qui a fait l’homme dès sa naissance, et qui a trouvé l’origine de toutes choses, vous rendra dans sa miséricorde l’esprit et la vie, parce que vous vous méprisez vous-mêmes pour l’amour de sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 24, 'Cependant Antiochus, se croyant insulté, et méprisant la voix qui le reprenait, comme le plus jeune survivait, non-seulement le tenta par ses promesses, mais voulut lui persuader par des serments qu’il le ferait riche et heureux, s’il abandonnait la loi de ses pères, qu’il serait son ami et lui confierait de grands emplois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 25, 'Mais le jeune homme ne lui prêtant aucune attention, le roi appela sa mère, et l’exhorta à donner à son fils des conseils de salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 26, 'Lorsqu’il l’eut longuement exhortée, elle lui promit de persuader son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 27, 'Et s’étant penchée vers lui, et raillant le tyran cruel, elle parla ainsi au jeune homme, dans la langue de ses pères: 0 mon fils, aie pitié de moi, qui t’ai porté neuf mois dans mes entrailles, moi qui t’ai allaité trois ans, moi qui t’ai amené à l’âge où tu es, moi qui t’ai nourri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 28, 'Je t’en conjure, enfant, regarde le ciel et la terre et tout ce qu’ils renferment, et sache que Dieu les a créés de rien, et qu’ainsi est née la race des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 29, 'N’aie pas peur de ce bourreau, sois digne de tes frères, et accepte la mort, afin que je ne te sépare point de tes frères dans la miséricorde de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 30, 'Comme elle parlait encore, le jeune homme s’écria: Qu’attendez-vous? je n’obéirai point aux ordres du roi; j’obéis à la loi qui a été donnée par Moïse à nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 31, 'Et toi, auteur de tous les maux des Hébreux, tu n’éviteras point le bras du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 32, 'Car c’est à cause de nos péchés que nous endurons ces souffrances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 33, 'Et si par ses châtiments et sa répression le Dieu vivant nous montre un moment sa colère, il ne tardera pas à se réconcilier avec ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 34, 'Et toi, impie, toi le plus scélérat de tous les hommes, ne t’enorgueillis pas vainement, en t’abandonnant à de folles espérances, en levant la main contre les serviteurs de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 35, 'Car tu n’as pas encore échappé au jugement du Tout-Puissant qui te surveille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 36, 'En ce moment, mes frères, après avoir subi une courte peine, sont entrés dans la vie éternelle, grâce à l’alliance de Dieu; et toi, par le jugement de Dieu, tu porteras le digne châtiment de ton orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 37, 'Quant à moi, comme mes frères, je livre mon corps et ma vie pour la loi de mes pères, et je supplie le Seigneur d’être bientôt propice envers son peuple, et de te forcer à confesser par ses châtiments et ses flagellations qu’il est le seul Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 38, 'Je supplie le Tout-Puissant de faire cesser, après ma mort et celle de mes frères, la juste colère qu’il a étendue sur toute ma race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 39, 'Et le roi, transporté de fureur, fut pour lui plus cruel encore que pour les autres, ne pouvant supporter qu’on se jouât de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 40, 'Et ainsi mourut le jeune homme, pur en toutes choses, et se confiant au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 41, 'Enfin la mère mourut la dernière, après ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 42, 'Mais en voilà assez au sujet des sacrifices et des cruautés d’Antiochus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Cependant Judas Machabée et ses compagnons s’introduisaient secrètement dans les bourgades, où ils convoquaient leurs parents et ceux qui étaient restés fidèles au judaïsme; et ils finirent par rassembler environ six mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Et ils implorèrent le Seigneur pour qu’il regardât son peuple, que tout le monde foulait aux pieds, et qu’il eût aussi pitié de son temple profané par les impies;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Qu’il fit miséricorde à la ville accablée et qui allait bientôt se trouver au niveau du sol, et qu’il écoutât le sang qui criait vers lui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Qu’il se rappelât les petits innocents injustement massacrés, et les blasphèmes portés contre son nom; enfin qu’il fît éclater sa haine contre les méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Or Machabée, une fois à la tête d’une troupe nombreuse, devint redoutable aux gentils, la colère du Seigneur s’étant changée en compassion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Il tombait inopinément sur les villes et les villages et il les brûlait; il savait prendre les meilleures positions, et se retournant à propos, il remportait la victoire sur un grand nombre d’ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Il choisissait les nuits surtout pour auxiliaires de tels desseins, et le bruit de sa valeur se répandait en tous lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Philippe ne fut pas longtemps à voir quels progrès faisait un homme qui chaque jour augmentait ses forces; il écrivit donc à Ptolémée, général de la Cœlé-Syrie et de la Phénicie, pour lui demander des renforts dans l’intérêt du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Celui-ci fit partir aussitôt Nicanor, l’un de ses principaux affidés qu’il avait sous la main, à la tête de vingt mille hommes de toutes nations, pour qu’il exterminât la race entière des Juifs. Il lui adjoignit Gorgias, l’un des généraux les plus expérimentés dans les affaires de la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Nicanor s’empara du tribut de deux mille talents que le roi payait aux Romains, se proposant de le remplir en vendant les captifs de la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Et d’avance il invita les marchands des villes maritimes à venir acheter des esclaves juifs, promettant de leur en donner quatre-vingt-dix pour un talent, et ne prévoyant pas que la vengeance du Tout-Puissant allait tomber sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'On fit savoir à Judas le départ de Nicanor, et il informa ses compagnons de l’approche de cette armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Les uns, frappés de crainte et manquant de confiance en la justice de Dieu, s’enfuirent et émigrèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Les autres vendirent ce qui leur restait, et en même temps ils priaient le Seigneur, de les délivrer de l’impie Nicanor, qui les vendait avant de les avoir attaqués,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 15, 'Et de les protéger, sinon à cause d’eux, du moins à cause de l’alliance de leurs pères, et parce qu’ils invoquaient en leur faveur le nom saint et grand de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 16, 'Or Machabée, ayant réuni ceux qui étaient demeurés, au nombre de six mille hommes, les conjura de ne point craindre les ennemis, de ne point se troubler de la multitude de gentils qui marchaient injustement contre eux, et de combattre vaillamment,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 17, 'Ayant sous les yeux l’indigne profanation du lieu saint, les railleries et les affronts soufferts par la ville outragée, et l’abolition des lois de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 18, 'Ils mettent, dit-il, leur confiance dans leurs armes et leur audace; nous, nous mettons notre confiance en Dieu, maître de toutes choses, qui peut d’un signe abattre ceux qui viennent nous attaquer, et l’univers même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 19, 'Il énuméra ensuite les exemples antiques de la protection de Dieu; il rappela comment Sennacherib avait perdu cent quatre-vingt-cinq mille hommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 20, 'Puis comment dans la bataille qu’ils avaient soutenue en Babylonie contre les Galates, quand, au nombre de huit mille avec quatre mille Macédoniens, comme ceux-ci hésitaient, les huit mille détruisirent douze myriades d’ennemis, grâce au secours du Ciel, et remportèrent une grande victoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 21, 'Après les avoir raffermis par ces souvenirs et les avoir disposés à mourir pour les lois et pour la patrie, il divisa l’armée en quatre corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 22, 'Et à la tête de chaque corps, autre que le sien, il mit ses frères Simon, Joseph et Jonathas, leur donnant à chacun mille cinq cents hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 23, 'Et aussitôt qu’Éléazar leur eut fait la lecture du livre saint, et montré le signe de la protection de Dieu, Judas, avec le premier corps, attaqua Nicanor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 24, 'Or, par l’aide du Tout-Puissant, ils égorgèrent plus de neuf mille ennemis, ils blessèrent et affaiblirent la plus grande partie de l’armée de Nicanor, et ils la forcèrent à fuir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 25, 'Et ils prirent l’argent de ceux qui étaient venus pour les acheter. Et ayant poursuivi les fuyards autant que possible,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 26, 'Ils s’arrêtèrent retenus par l’heure; car c’était la veille du sabbat: c’est pourquoi ils ne coururent pas après eux plus longtemps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 27, 'Ayant donc ramassé les armes et les dépouilles des ennemis, ils gardèrent le repos du sabbat, louant de toute leur âme le Seigneur, qui en ce jour-là les avait sauvés, et rendirent hommage à Celui qui commençait par eux à disposer de sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 28, 'Après le sabbat, ils distribuèrent aux blessés, aux veuves et aux orphelins une part des dépouilles; euxmêmes et les gens de leur suite se partagèrent le surplus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 29, 'Ces choses faites, la prière dite en commun, ils demandèrent à Dieu de se réconcilier pour toujours avec ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 30, 'Plus tard, ils en vinrent aux mains avec les troupes de Timothée et de Bacchide, et ils leur tuèrent plus de vingt mille hommes; ils se rendirent vaillamment maîtres de hautes forteresses, et prirent un immense butin; et ils en firent des parts égales pour euxmêmes, pour les blessés et les veuves, les orphelins et les vieillards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 31, 'Ensuite ils recueillirent les armes et les déposèrent avec soin en des lieux sûrs; puis ils portèrent à Jérusalem le reste des dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 32, 'L’un des ennemis tués était le général de l’armée de Timothée, le plus scélérat des hommes, et qui avait cruellement affligé les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 33, 'Pendant qu’ils fêtaient leur victoire dans leur patrie, ils apprirent que Callisthène et quelques autres qui avaient brûlé les portes du temple s’étaient réfugiés dans une petite maison; ils les y brûlèrent, et leur rendirent le juste salaire de leurs profanations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 34, 'Cependant le triple scélérat Nicanor, qui avait amené mille marchands pour leur vendre des Juifs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 35, 'Humilié, grâce au Seigneur, par ceux qu’il croyait plus faibles que lui, ôta ses vêtements d’honneur, s’enfuit à travers champs comme un déserteur, et rentra seul à Antioche, extrêmement malheureux d’avoir perdu son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 36, 'Et lui qui avait donné comme garantie de l’impôt dû aux Romains les captifs de Jérusalem, publia que les Juifs avaient Dieu pour auxiliaire, et qu’ainsi ils étaient invulnérables, parce qu’ils obéissaient aux lois qu’il avait établies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 1, 'Or en ce temps-là Antiochus revint honteusement des contrées de la Perse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 2, 'Car étant entré dans Persépolis, il s’était mis à piller le temple et à opprimer la ville. C’est pourquoi la multitude eut recours aux armes et le mit en fuite; et ainsi battu par les habitants, il fit une retraite humiliante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 3, 'Et comme il était près d’Ecbatane, il apprit ce qui était arrivé à Nicanor et à Timothée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 4, 'Transporté de fureur, il pensa à se venger sur les Juifs de la malice de ceux qui l’avaient forcé de fuir; c’est pourquoi il ordonna au conducteur de son char de pousser en avant et de hâter ce voyage, où la vengeance du Ciel le poursuivait. Car dans son orgueil il avait dit: Aussitôt arrivé à Jérusalem, j’en ferai le tombeau des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 5, 'Mais le Seigneur Dieu d’Israël, celui qui voit toutes choses, le frappa d’une plaie incurable, et telle qu’on n’en avait jamais vu. A peine eut-il proféré cette parole qu’il ressentit une extrême douleur d’entrailles et de cruelles tortures à l’intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 6, 'Et c’était justice; car il avait fait souffrir nombre de fois les entrailles d’autrui par des tourments inouïs, et il n’avait jamais rien rabattu de son orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 7, 'Et en ce moment il en était encore rempli; soufflant contre les Juifs le feu de sa colère, il ordonnait de hâter la marche, quand soudain il tomba du char qui roulait à grand fracas; sa chute fut violente, et tous les membres de son corps en furent meurtris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 8, 'Et lui qui tout à l’heure s’imaginait commander aux vagues de la mer, tant sa jactance était surhumaine, lui qui s’imaginait peser dans sa balance les hauteurs des monts, maintenant tombé dans la poudre, il fut transporté dans une litière, rendant manifeste aux yeux de tous la vertu de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 9, 'Et du corps de l’impie sortaient des vers; lui vivant, sa chair se détacha de ses os avec d’atroces douleurs; tout le camp même fut infecté de l’odeur de sa pourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 10, 'Et celui qui, un instant auparavant, semblait toucher aux étoiles, nul à présent ne pouvait supporter son intolérable puanteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 11, 'Alors, tout brisé, il commença à renoncer à son orgueil; il rentra en lui-même, lorsque, flagellé d’une manière surnaturelle, il sentit redoubler ses souffrances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 12, 'Et comme lui-même ne pouvait supporter sa puanteur, il dit: Il est juste de se soumettre à Dieu; et, mortel, il ne faut point nourrir avec orgueil des pensées qui ne conviennent qu’à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 13, 'Mais le scélérat priait un maître dont il n’avait plus à attendre aucune pitié, promettant');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 14, 'De déclarer libre la ville sainte, que naguère il avait hâte d’abaisser au niveau du sol pour en faire un to mbeau;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 15, 'De rendre semblables aux Athéniens tous les Juifs qu’il ne jugeait pas autrefois dignes de la sépulture, les destinant, eux et leurs enfants, à servir de pâture aux oiseaux de proie et aux bêtes féroces;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 16, 'D’orner des plus belles offrandes le temple saint qu’il avait jadis dépouillé, de lui rendre ses vases sacrés en beaucoup plus grand nombre, et de subvenir, de ses revenus personnels, aux frais des sacrifices;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 17, 'Outre cela, d’être Juif lui-même, et de parcourir tous les lieux habités pour y proclamer la puissance de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 18, 'Mais ses souffrances ne se calmèrent pas, car le juste jugement de Dieu était appesanti sur lui; alors, n’espérant plus rien, il écrivit aux Juifs la lettre ci-après transcrite, en forme de supplication, et conçue en ces termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 19, 'Le roi et général Antiochus aux bons citoyens Juifs salut, santé et bonheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 20, 'Si vous vous portez bien, si vos enfants et vos familles vont comme vous le désirez, j’en rends les plus grandes grâces à Dieu, ayant espérance dans le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 21, 'Pour moi, je suis malade, et je n’ai pour vous que des pensées de bienveillance et d’honneur. Comme je revenais de la Perse, je suis tombé en une maladie cruelle, et j’ai jugé nécessaire de m’occuper de la sécurité de tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 22, 'Ne sachant ce qui peut arriver de moi, quoique j’aie beaucoup d’espoir d’échapper à cette maladie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 23, 'Considérant que mon père, dans le temps qu’il porta ses armes contre les pays hauts, désigna son successeur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 24, 'Pour qu’en cas d’accident imprévu ou de fâcheuse nouvelle ceux de son royaume, sachant à qui les affaires étaient remises, ne fussent point troublés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 25, 'Songeant, en outre, que les rois mes voisins attendent l’occasion et chercheront à profiter des circonstances, je nomme roi mon fils Antiochus, que plus d’une fois, lorsque j’ai parcouru mes provinces supérieures, j’ai confié à plusieurs d’entre vous, en vous le recommandant. Et je lui écris la lettre ci-dessous transcrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 26, 'Je vous exhorte donc et vous supplie de vous souvenir de mes bienfaits envers le public et les particuliers, et de conserver à mon fils la bienveillance que vous aviez pour moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 27, 'Car je suis persuadé qu’il vous traitera avec modération et humanité, comme je l’en ai prié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 28, 'Ainsi donc ce meurtrier, ce blasphémateur, atteint des plus terribles maux, souffrant comme il avait fait souffrir les autres, expira dans les montagnes, sur une terre étrangère, d’une mort déplorable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 29, 'Philippe, son confident, ramena son corps; mais craignant le jeune Antiochus, il se retira chez Ptolémée Philométor, en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 1, 'Cependant Machabée et ses compagnons, conduits par le Seigneur, prirent soin du temple et de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 2, 'Ils renversèrent les autels que les étrangers avaient érigés sur la place publique et les enclos sacrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 3, 'Puis, ayant purifié le temple, ils élevèrent un autre autel, et ils tirèrent du feu des cailloux, et prirent de ce feu; et après deux ans d’interruption ils offrirent un sacrifice, et rétablirent l’encens, les lampes et les pains de proposition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 4, 'Cela fait, ils se prosternèrent et ils prièrent le Seigneur, pour ne plus tomber en de tels maux, demandant, s’ils péchaient encore, d’être châtiés par lui avec justice, mais de ne plus être livrés à des peuples barbares et blasphémateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 5, 'Le temple avait été profané par les étrangers le vingt-cinquième jour du mois de Casleu, et il se rencontra qu’il fut purifié à pareil jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 6, 'Et ils firent avec joie, pendant huit jours, une fête pareille à celle des Tabernacles, ayant souvenance que, peu de temps auparavant, ils avaient passé ce jour de fête dans les montagnes, dans des cavernes, où ils vivaient à la manière des bêtes fauves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 7, 'C’est pourquoi, portant des thyrses, des rameaux verts et des palmes, ils chantèrent des hymnes à la gloire de Celui qui les avait heureusement amenés à purifier le lieu qui lui était consacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 8, 'Et ils prescrivirent par un édit public que toute la nation juive fêterait tous les ans ces mêmes jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 9, 'Antiochus, surnommé Épiphane, était donc mort comme il a été dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 10, 'Nous allons raconter maintenant ce qui concerne Antiochus Eupator, né d’un père impie, sans nous étendre sur les maux que firent ses guerres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 11, 'À son avénement, il mit à la tête des affaires Lysias, général en chef de la Colé-Syrie et de la Phénicie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 12, 'Cependant Ptolémée, surnommé Macer, aima mieux observer à l’égard des Juifs ce qui était juste que de les traiter comme jadis avec iniquité, et il s’efforça de les gouverner pacifiquement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 13, 'Mais pour cela même il fut accusé par les amis d’Eupator, et il s’entendit de toutes parts appeler traître pour avoir abandonné Chypre, que lui avait confiée Philométor, pour s’être rapproché d’Antiochus Epiphane et pour avoir fait une fortune peu honorable; alors il perdit courage, prit du poison et se donna la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 14, 'Alors Gorgias devint général des provinces, entretint des mercenaires étrangers et fomenta des guerres continuelles contre les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 15, 'En même temps que lui, les Iduméens, s’étant emparés des forteresses avantageuses, dépouillèrent les Juifs, et en recevant ceux qui avaient fui de Jérusalem ils cherchaient à entretenir des hostilités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 16, 'Or les compagnons de Machabée, après avoir prié et demandé à Dieu d’être leur auxiliaire, firent irruption contre les places qu’occupaient les Iduméens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 17, 'Ils les attaquèrent avec vigueur, et les reprirent en repoussant les défenseurs des remparts, et ils égorgèrent ceux qu’ils en avaient précipités, et ils ne tuèrent pas moins de vingt mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 18, 'Environ neuf mille se réfugièrent dans deux tours très-fortes et approvisionnées de tout ce qu’il faut pour soutenir un siège.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 19, 'Machabée laissa pour les assaillir Simon, Joseph et Zacchée, avec un nombre d’hommes suffisant, et s’en alla de sa personne où il y avait urgence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 20, 'Mais la troupe de Simon, avide de richesses, se laissa séduire à prix d’argent par quelques-uns de ceux qui étaient dans les tours, et moyennant soixante-dix mille drachmes ils les laissèrent échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 21, 'Quand on eut appris à Machabée ce qui était advenu, il réunit les princes du peuple, et accusa ces hommes d’avoir vendu leurs frères à prix d’argent et délivré des ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 22, 'Il mit donc à mort ceux que l’on reconnut traîtres, et aussitôt il prit les deux tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 23, 'Ses armes prospéraient partout en ses mains; il tua encore dans ces deux forteresses plus de vingt mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 24, 'Cependant Timothée, qui précédemment avait été défait par les Juifs, leva une multitude de troupes étrangères, et tira de l’Asie une cavalerie nombreuse; puis il arriva comme pour faire passer toute la Judée sous le joug.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 25, 'À son approche, les compagnons de Machabée se mirent en prière, se couvrirent la tête de cendres et se ceignirent de cilices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 26, 'Ils se prosternèrent ensuite au pied de l’autel, et demandèrent à Dieu de leur être propice, d’être l’ennemi de leurs ennemis, et l’adversaire de leurs adversaires, comme il est dit en la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 27, 'Leur prière achevée, ils prirent les armes, sortirent de la ville et poussèrent en avant, aussi loin qu’ils purent; quand ils furent près de l’ennemi, ils s’arrêtèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 28, 'Aux premières lueurs du jour, des deux parts on engagea la bataille, les uns ayant pour gage certain de la victoire, outre leur vertu, la protection du Seigneur, les autres n’ayant d’autre guide que la fureur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 29, 'Le combat était acharné, quand du ciel apparurent aux ennemis cinq hommes tout éclatants, et montés sur des chevaux aux freins d’or; et les deux premiers se mirent à la tête des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 30, 'Ils prirent Machabée entre eux deux, le couvrant de leurs propres armes, et le rendirent invulnérable; cependant ils lancèrent aux ennemis des flèches et les traits de la foudre; ceux-ci, confondus, frappés d’aveuglement, pleins de trouble, furent taillés en pièces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 31, 'Vingt-cinq mille fantassins et six mille cavaliers périrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 32, 'Timothée se réfugia dans Gazara, ville réputée très-forte, où commandait Chéréas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 33, 'Les compagnons de Machabée, pleins de joie, l’assiégèrent quatre jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 34, 'Or les assiégés, confiants dans la force de la place, ne cessèrent de blasphémer et de proférer des paroles impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 35, 'Comme le cinquième jour commençait à poindre, vingt jeunes hommes de la troupe de Machabée, enflammés de colère par les blasphèmes qu’ils entendaient, escaladèrent comme des héros le rempart, et massacrèrent avec une fureur farouche tout ce qu’ils rencontrèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 36, 'D’autres montèrent pareillement, au milieu du désordre des assiégés; ils mirent le feu aux tours, ils allumèrent des bûchers et brûlèrent vifs les blasphémateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 37, 'Quelques-uns enfoncèrent les portes et ouvrirent le passage au reste de l’armée, qui prit la ville; on découvrit Timothée caché dans une citerne, et on l’égorgea avec Chéréas, son frère, et Apollophane.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 38, 'Ces exploits accomplis, ils bénirent le Seigneur, qui répandait sur Israël de si grands bienfaits, et qui leur avait donné la victoire, et ils lui rendirent grâces en chantant des hymnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 1, 'Or très-peu de temps après, Lysias, ministre du roi et son proche parent, placé à la tête des affaires, et supportant avec peine ce qui venait d’arriver,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 2, 'Mit sur pied quatre-vingt mille hommes et toute sa cavalerie; puis il marcha contre les Juifs, comptant peupler de Grecs la ville sainte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 3, 'Et faire du temple une source de revenus, comme le sont les temples des gentils, et vendre annuellement la dignité de grand prêtre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 4, 'Ne songeant nullement à la puissance de Dieu, mais fier de ses myriades de fantassins, de ses milliers de chevaux et de ses quatre-vingts éléphants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 5, 'Il entra donc en Judée, arriva devant Bethsura, place forte à environ cinq stades de Jérusalem, et la pressa vivement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 6, 'Lorsque les compagnons de Machabée apprirent qu’il assiègeait les forteresses, ils se réunirent au peuple entier; puis, gémissant et pleurant, ils prièrent le Seigneur d’envoyer un bon ange pour le salut d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 7, 'Machabée le premier prit les armes, et il exhorta les autres à se jeter avec lui dans le péril et à secourir leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 8, 'Ils partirent tous ensemble avec ardeur; et ils étaient encore en vue de Jérusalem, quand un cavalier vêtu de blanc parut à leur tête, agitant un bouclier d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 9, 'Alors tous à la fois bénirent le Dieu miséricordieux, et ils furent raffermis en leurs âmes, prêts à combattre non-seulement les hommes, mais les bêtes les plus farouches, et à renverser des murailles de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 10, 'Ils abordèrent l’ennemi résolûment; car ils avaient un auxiliaire venu du ciel, et le Seigneur leur était miséricordieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 11, 'Ils se ruèrent donc comme des lions sur les ennemis; ils couchèrent à terre onze mille fantassins et seize cents cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 12, 'Ils mirent tous les autres en fuite; la plupart de ceux qui s’échappèrent étaient blessés et avaient jeté leurs armes; pour Lysias, il sauva sa vie en fuyant honteusement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 13, 'Mais comme il n’était pas dépourvu de sens, il réfléchit sur sa défaite, et il comprit que les Hébreux étaient invincibles, parce que le Dieu tout-puissant était leur auxiliaire; il leur envoya donc des députés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 14, 'Et il obtint d’eux de terminer la guerre, sous toutes les conditions qui seraient reconnùes justes, s’offrant de persuader au roi d’être l’ami des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 15, 'Machabée consentit à tout ce que proposait Lysias, ayant en vue l’avantage du peuple; car toutes les réclamations que fit Machabée par écrit en faveur des Juifs, le roi les accorda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 16, 'Voici les lettres que Lysias écrivit aux Juifs; elles étaient ainsi conçues: Lysias au peuple juif, salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 17, 'Jean et Abessalom, que vous m’avez envoyés, m’ayant remis la réponse que vous avez écrite, m’ont demandé ce que j’en ordonnais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 18, 'Tout ce que je savais devoir être soumis au roi, je le lui ai fait connaître; et il a ratifié ce qui était admissible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 19, 'Si donc vous persévérez dans vos bonnes intentions pour traiter avec nous, je m’efforcerai désormais de devenir l’auteur de votre bien-être.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 20, 'Quant aux détails de nos conventions, j’ai donné mes instructions à vos envoyés et aux miens qui sont auprès de vous, pour qu’ils en confèrent avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 21, 'Portez-vous bien; l’an cent quarante-huit, le vingt-quatre du mois de Dioscorinthe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 22, 'Voici maintenant comment était conçue la lettre du roi Le roi Antiochus à son frère Lysias, salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 23, 'Notre père ayant été transporté parmi les dieux, comme nous voulons que les citoyens de notre royaume vivent sans trouble, en prenant soin de leurs affaires;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 24, 'Or, ayant appris que les Juifs n’ont point consenti, comme le voulait notre père, à adopter les mœurs grecques, mais qu’ils ont préféré leurs anciennes coutumes et demandent que nous tolérions leurs lois;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 25, 'De notre côté, notre désir étant que ce peuple aussi soit sans trouble, nous avons ordonné que le temple leur soit restitué, et qu’ils suivent les coutumes de leurs ancêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 26, 'Tu feras donc bien d’envoyer vers eux et de leur tendre la main droite, afin qu’ils connaissent nos intentions, qu’ils aient bon courage et continuent de veiller à leurs intérêts privés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 27, 'Enfin telle était la lettre écrite au peuple par le roi: Le roi Antiochus aux anciens des Juifs et aux autres Juifs, salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 28, 'Si vous vous portez bien, les choses vont à nos souhaits; et nous-même, nous sommes en bonne santé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 29, 'Ménélas nous a fait connaître que vous désiriez revenir et rentrer dans vos propriétés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 30, 'Ceux donc qui voudront revenir le pourront en toute sécurité jusqu’au trente du mois de Xanthique; notre signature en fait foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 31, 'Ils garderont leurs lois et useront de leurs aliments comme jadis, et nul d’eux en aucune manière ne sera inquiété pour des fautes commises par ignorance de nos coutumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 32, 'C’est pourquoi j’ai envoyé Ménélas pour en conférer avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 33, 'Portez-vous bien; l’an cent quarante-huit, le quinze du mois de Xanthique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 34, 'Les Romains écrivirent aussi aux Juifs une lettre ainsi conçue: Quintus Memmius et Titus Manlius, ambassadeurs des Romains, au peuple des Juifs, salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 35, 'Nous vous concédons les choses que Lysias, parent du roi, vous a concédées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 36, 'Quant à celles qu’il a jugé devoir soumettre au roi, envoyez-nous sans délai l’un des vôtres, après les avoir bien examinées, afin que nous en ordonnions comme il vous convient. Car nous allons à Antioche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 37, 'Hâtez-vous donc, faites partir vos députés, afin que nous sachions quelles sont vos intentions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 38, 'Portez-vous bien; l’an cent quarante-huit, le quinze de Xanthique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 1, 'Ce traité conclu, Lysias s’en retourna auprès du roi, et les Juifs se mirent à cultiver leurs champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 2, 'Or les généraux de la contrée, Timothée et Apollonius, fils de Gennée, Hiéronyme, Démophon, et, outre ceux-là, Nicanor, gouverneur de Chypre, ne les laissèrent point s’affermir ni vivre en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 3, 'Ceux de Joppé, à cette époque, commirent un acte impie: ils invitèrent les Juifs qui demeuraient parmi eux à monter avec leurs femmes et leurs enfants sur des barques toutes préparées, comme s’ils n’avaient eu aucune animosité contre eux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 4, 'Sur la foi d’un édit publié dans la ville, ils acceptèrent comme des gens désirant la paix, et n’ayant aucun soupçon; mais lorsqu’ils furent au large, on les coula à fond, au nombre d’au moins deux cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 5, 'Judas, ayant appris la cruauté commise contre des hommes de sa nation, donna ses ordres à ceux qui étaient avec lui; et après avoir invoqué Dieu, le juge équitable,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 6, 'Il marcha contre les meurtriers de ses frères; et, étant arrivé la nuit, il mit le feu au port, il brûla les navires et passa au fil de l’épée ceux qui cherchaient à s’yréfugier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 7, 'La place investie, Judas se retira; mais pour revenir et déraciner entièrement le gouvernement de Joppé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 8, 'Cependant il avait appris que ceux de Jamnia avaient aussi projeté de traiter de la même manière les Juifs domiciliés chez eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 9, 'Il envahit donc pendant la nuit Jamnia; il brûla le port et la flotte, et de Jérusalem on aperçut la flamme, quoique la distance soit de deux cent quarante stades.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 10, 'Comme il s’était remis en marche pour attaquer Timothée, à neuf stades de là, les Arabes tombèrent sur lui, au nombre de cinq mille hommes et cinq cents cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 11, 'Le combat fut acharné; mais, avec l’aide de Dieu, les compagnons de Judas l’emportèrent; vaincus, les Arabes nomades demandèrent à Judas de leur tendre la main droite, promettant de lui donner des pâturages et de se mettre d’ailleurs à son service.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 12, 'Judas, comprenant qu’ils lui seraient véritablement utiles en beaucoup de circonstances, consentit à faire la paix; et, après qu’ils se furent donnés la main droite, les Arabes se retirèrent sous leurs tentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 13, 'Il attaqua ensuite une ville forte, entourée de remparts, avec des ponts-levis, et habitée par des hommes de nations diverses; elle s’appelait Caspin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 14, 'Les assiégés, bien pourvus de vivres, et confiants en la force de leurs murailles, se conduisirent avec jactance, insultant les compagnons de Judas, blasphémant et disant des paroles injurieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 15, 'Les compagnons de Judas, après avoir invoqué le souverain Maître du monde, celui qui, du temps de Josué, renversa Jéricho sans béliers ni machines, se ruèrent contre la muraille comme des bêtes furieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 16, 'Ils prirent la ville par la volonté de Dieu; ils y firent un carnage incroyable, au point que l’étang voisin, large de deux stades, sembla ruisseler de sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 17, 'Ils firent ensuite une marche de sept cent cinquante stades et atteignirent Characa, où demeurent les Juifs appelés Tubiéniens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 18, 'Mais ils n’y surprirent pas Timothée; il s’était éloigné de ces lieux sans avoir rien pu faire, laissant une garnison dans une place forte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 19, 'Or Dosithée et Sosipater, chefs des compagnons de Machabée, y marchèrent et massacrèrent cette troupe d’au moins dix mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 20, 'De son côté, Machabée, ayant divisé son armée par cohortes, la dirigea contre Timothée, qui avait cent vingt mille fantassins et mille cinq cents chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 21, 'Timothée, informé de son approche, fit partir alors les femmes, les enfants, les bagages, pour le lieu que l’on appelle Carnion, presque inabordable et difficile à investir à cause d’une multitude de défilés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 22, 'Dès que la première cohorte de Judas parut, l’épouvante s’empara des ennemis; car Celui qui voit tout se manifestait à eux; ils furent mis en fuite les uns par les autres, frappés même par ceux de leur parti, au point que plusieurs eurent des épées passées au travers du corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 23, 'Judas les poursuivit à outrance, perçant de coups ces hommes criminels, et il en massacra jusqu’à trente mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 24, 'Timothée tomba entre les mains des soldats de Dosithée et de Sosipater, et il les supplia avec mille instances de le laisser partir sain et sauf, affirmant qu’il tenait prisonniers les pères ou les frères de beaucoup d’entre eux, et que s’il mourait, il leur arriverait malheur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 25, 'N’épargnant pas les serments pour les persuader, et promettant de renvoyer les prisonniers sans qu’ils eussent rien à souffrir. Ils le délivrèrent donc pour sauver leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 26, 'Judas marcha aussitôt sur Carnion et Atargatéion, où il tua vingt-cinq mille hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 27, 'Après avoir mis en déroute et exterminé ces ennemis, Judas attaqua Éphron, ville forte, résidence de Lysias et d’une multitude de gentils. De robustes guerriers, rangés sur les remparts, combattirent avec vigueur, et ils étaient pourvus de machines et de quantité de traits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 28, 'Les Juifs, après avoir invoqué le Tout-Puissant, celui qui dans sa puissance brise les forces des ennemis, prirent d’assaut la ville et couchèrent à terre les assiégés au nombre de vingt-cinq mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 29, 'De là ils allèrent à la ville des Scythes, à six cents stades de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 30, 'Mais les Juifs y résidant témoignèrent qu’ils avaient été traités par les citoyens avec bienveillance, et que dans les temps malheureux ils en avaient reçu de bons offices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 31, 'Ils en remercièrent les Scythes, et les exhortèrent à être doux de même à l’avenir envers leur race; après quoi ils rentrèrent à Jérusalem, au moment où allait commencer la fête des Semaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 32, 'Après la Pentecôte, ils marchèrent contre Gorgias, général de l’Idumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 33, 'Judas partit, ayant avec lui trois mille fantassins et quatre cents cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 34, 'On en vint aux mains, et il ne périt qu’un petit nombre de Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 35, 'Mais un certain Dosithée, des soldats de Bacénor, cavalier d’une grande force, saisit Gorgias, et, le tirant par sa chlamyde, il l’entraîna vigoureusement, animé du désir de prendre vivant cet homme maudit; mais un cavalier thrace survint qui lui coupa l’épaule, et Gorgias delivré s’enfuit à Marésa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 36, 'Cependant les cohortes d’Esdrin, ayant longtemps combattu, furent brisées de fatigue; Judas alors supplia le Seigneur de se montrer lui-même leur auxiliaire et leur guide au combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 37, 'Or à peine eut-il commencé à pousser le cri de guerre avec des hymnes dans la langue de ses pères, que, se précipitant à l’improviste sur ceux de Gorgias, il les mit en déroute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 38, 'Judas, ayant ensuite rallié son armée, la conduisit à la ville d’Odollam; elle y arriva le septième jour, fit les purifications accoutumées et célébra le sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 39, 'Le lendemain, ses gens, comme il était nécessaire, relevèrent les cadavres de ceux qui avaient été tués, et ils les ensevelirent dans les sépulcres de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 40, 'Et ils trouvèrent sous les tuniques des morts des objets consacrés aux idoles de Jamnia, qu’il est défendu aux Juifs de porter; et il fut visible pour tous que c’était la cause de leur perte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 41, 'Tous bénirent donc le Seigneur, juge équitable, qui avait rendu manifestes les choses cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 42, 'Et ils prièrent pour demander au Seigneur le pardon de ce péché. Cependant l’illustre Judas conjura le peuple de se garder pur de cette faute, puisqu’ils voyaient de leurs yeux comment étaient morts ceux qui en étaient coupables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 43, 'Puis il fit une collecte, recueillit deux mille drachmes d’argent, et les envoya à Jérusalem pour être employées à un sacrifice pour le péché; et il agit avec sagesse et piété en songeant à la résurrection.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 44, 'Car s’il n’avait point cru que ceux qui avaient péri dussent ressusciter, il eût trouvé superflu et puéril de prier pour les morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 45, 'De plus il considérait que les plus grandes grâces sont réservées à ceux qui meurent dans la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 46, 'Pensée sainte et pieuse. Voilà pourquoi il fit un sacrifice propitiatoire en l’honneur des morts, pour les absoudre de leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 1, 'L’an cent quarante-neuf, Judas fut informé qu’Antiochus Eupator marchait contre la Judée avec une grande multitude;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 2, 'Que Lysias, son ministre, l’accompagnait, et qu’ils avaient chacun une armée grecque de cent dix mille fantassins, cinq mille trois cents cavaliers, vingt-deux éléphants et trois cents chars armés de faux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 3, 'Que Ménélas était mêlé dans cette affaire, et que sous de faux prétextes il avait appelé Antiochus, non pour le salut de sa patrie, mais ne songeant qu’à s’affermir dans le souverain pouvoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 4, 'Mais le Roi des rois excita contre ce scélérat la colère d’Antiochus; et Lysias, ayant prouvé à celui-ci que Ménélas était l’auteur de tous les maux, il ordonna, comme c’est l’usage en cette contrée, de le conduire à Béræa, et de l’y mettre à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 5, 'Or il y avait là une tour de cinquante coudées pleine de cendre, et cette tour était couronnée de toutes parts d’une machine circulaire qui faisait glisser dans la cendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 6, 'C’est de là que l’on précipita pour le faire périr cet homme coupable de sacriléges et d’une multitude de crimes qui le poussèrent à sa perte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 7, 'Ainsi Ménélas mourut, ce prévaricateur, et il ne fut point déposé dans la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 8, 'Et c’était justice; car il avait maintes fois péché contre l’autel, dont le feu et la cendre étaient purs, et c’est dans la cendre qu’il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 9, 'Et ce roi barbare se mit en marche, plein de pensées superbes, et préparant aux Juifs des cruautés pires que celles de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 10, 'Judas en fut informé, et il ordonna au peuple d’invoquer nuit et jour le Seigneur, afin qu’une fois encore il secourût en ce moment');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 11, 'Ceux qui allaient être privés du temple saint et de la loi de leurs pères; le priant de ne point permettre que ce peuple, qui respirait depuis si longtemps, fût assujetti à des peuples blasphémateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 12, 'Ils firent ce qu’il ordonnait, et en même temps ils implorèrent la miséricorde du Seigneur, avec jeûnes et avec larmes, sans cesse prosternés durant trois jours; après les avoir encouragés, Judas leur commanda de marcher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 13, 'Pour lui, il tint conseil avec les anciens, et il résolut de partir avant que le roi eût envahi la Judée et pris les forteresses, et de remettre le jugement de cette entreprise à la protection du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 14, 'Il se confia donc au Créateur du monde, exhorta les siens à combattre courageusement jusqu’à la mort, pour leurs lois, pour le temple, la ville, la patrie et leurs concitoyens, et porta son camp autour de Modin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 15, 'Là il donna à ses compagnons le signe de la victoire de Dieu, et avec sa jeunesse d’élite, il attaqua pendant la nuit le quartier du camp où était la tente du roi; il tua quatre mille hommes, et le plus grand éléphant avec la troupe qu’il avait dans une tour avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 16, 'Enfin il remplit le camp de trouble et de terreur, et ils se retirèrent avec un plein succès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 17, 'Tout était achevé quand le jour commença à poindre, grâce à la protection du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 18, 'Mais le roi, après avoir éprouvé le courage des Juifs, essaya de prendre les lieux par artifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 19, 'Il commença par Bethsura, ville forte des Juifs; mais ses gens furent mis en déroute, et ils eurent le dessous, et son projet échoua.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 20, 'Or Judas ne cessa d’envoyer aux assiégés tout ce qui leur était nécessaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 21, 'Cependant Rhodocus, un homme de l’armée des Juifs, dévoilait à l’ennemi leurs secrets; on fit des recherches, on le surprit et on le mit en prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 22, 'Le roi fit à deux reprises des propositions à ceux de Bethsura; il leur tendit la main droite, il prit la leur et se retira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 23, 'Mais il combattit encore l’armée de Judas, fut vaincu, et apprenant que Philippe, qu’il avait laissé à Antioche à la tête de ses affaires, s’était révolté, il en fut confondu; usant alors de prières à l’égard des Juifs, il fit avec eux sous serment de justes conventions, et après cette réconciliation, il offrit un sacrifice, honora le temple, et fut l’un de ses bienfaiteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 24, 'Il embrassa Judas Machabée, et il le nomma général depuis Ptolémaïs jusqu’au pays des Gerréniens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 25, 'Lorsque ensuite il rentra dans Ptolémaïs, les habitants de cette ville, mécontents du traité, s’indignèrent, craignant qu’ils n’en voulussent point exécuter les conditions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 26, 'Mais Lysias monta sur le tribunal, fit valoir de bonnes raisons, persuada le peuple, l’apaisa et ramena la paix; le roi retourna enfin à Antioche: telle fut son entrée en Judée, et sa sortie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 1, 'Trois ans plus tard, les compagnons de Judas apprirent que Démétrius et Séleucus étaient entrés dans le port de Tripoli avec une flotte et une forte armée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 2, 'Qu’ils s’étaient rendus maîtres de la contrée et en avaient repoussé Antiochus et son ministre Lysias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 3, 'Un certain Alcime, précédemment grand prêtre, qui s’était volontairement souillé dans les temps de profanation, comprenant qu’en aucune manière il n’y-avait de salut pour lui, et que l’accès de l’autel lui était interdit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 4, 'Alla trouver le roi Démétrius, l’an cent cinquante-un, lui présentant une couronne d’or et une palme, outre des rameaux pris dans le temple. Et ce jour-là il ne fit rien de plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 5, 'Mais plus tard, saisissant l’occasion favorable à ses desseins (car Démétrius l’avait convoqué au conseil, et le roi lui demandait sur quels principes, sur quels conseils s’appuyaient les Juifs),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 6, 'Il dit: Les Juifs que l’on appelle Assidéens, dont Judas Machabée est le chef, fomentent les guerres et entretiennent les séditions, ne permettant pas au royaume d’avoir de la stabilité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 7, 'Voilà pourquoi, dépouillé de ma gloire héréditaire, je veux dire du souverain sacerdoce, je suis venu ici;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 8, 'D’abord parce que je m’occupe véritablement des intérêts du roi; en second lieu, parce que j’ai en vue ceux de mes concitoyens; car, à cause de ces désordres, notre race entière n’a pas peu à souffrir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 9, 'Toi donc, ô roi, puisque tu es informé de ces choses, veille à notre province, protége notre peuple éprouvé, aie pour nous la bienveillance que tu as pour tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 10, 'Tant que vivra Judas, il sera impossible de ramener la paix en nos affaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 11, 'À peine eut-il parlé de la sorte, que tous ses amis, pleins de haine contre Judas, enflammèrent Démétrius.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 12, 'Soudain il appela Nicanor, chef des éléphants, le nomma général de la Judée, et le congédia,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 13, 'Lui donnant l’ordre de prendre Judas vivant, de disperser ses compagnons et de rétablir Alcime comme souverain pontife du grand temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 14, 'Les gentils que Judas avait expulsés de la Judée formèrent une cohorte de l’armée de Nicanor, estimant que les maux et les infortunes des Juifs étaient des biens pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 15, 'Quand on apprit à Jérusalem la marche de Nicanor et l’union des gentils, les Juifs se couvrirent la tête de cendre, et prièrent Celui qui de tout temps avait soutenu son peuple et protégé son héritage par des signes manifestes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 16, 'Obéissant aux ordres de leur chef, il partirent surle-champ, et en vinrent aux mains avec les envahisseurs près du bourg de Dessau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 17, 'Or Simon, frère de Judas, engagé contre Nicanor, fut un peu troublé de l’attaque soudaine de ses adversaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 18, 'Toutefois Nicanor, apprenant quelle était la valeur des compagnons de Judas et avec quelle audace ils combattaient pour leur patrie, craignit de s’en remettre au jugement par le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 19, 'C’est pourquoi il envoya Posidonius et Théodote à Mattathias, pour tendre sa main droite aux Juifs et prendre la leur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 20, 'Après avoir longtemps examiné l’affaire, le chef, ayant communiqué ses projets à l’armée, et tout le monde étant d’accord, on convint de traiter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 21, 'On fixa le jour où, venant chacun de son côté, les deux généraux se réuniraient en un même lieu; et on apprêta pour eux des sièges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 22, 'Cependant Judas plaça des hommes armés en des positions favorables, de peur qu’à l’improviste il n’y eût quelque perfidie tentée par les ennemis, et il tomba d’accord avec Nicanor, et le traité fut conclu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 23, 'Nicanor entra dans Jérusalem où il ne fit aucun mal, et il congédia les troupes qu’il avait amenées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 24, 'Et il eut toujours Judas en sa présence, et il se sentit même pour lui de l’amitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 25, 'Il l’engagea à se marier pour avoir des enfants; et Judas se maria, et il jouit du repos, et il vécut familièrement avec Nicanor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 26, 'Cependant Alcime, voyant la mutuelle amitié et l’alliance qu’ils avaient faite, se rendit auprès de Démétrius, et lui dit que Nicanor s’occupait d’autre chose que de ses affaires et qu’il destinait, pour lui succéder au trône, le traître Machabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 27, 'Le roi fut hors de lui; et, irrité par les calomnies de ce scélérat consommé, il écrivit à Nicanor qu’il souffrait difficilement l’alliance conclue, lui enjoignant d’enchaîner Judas et de l’envoyer sans délai à Antioche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 28, 'Au reçu de cette lettre Nicanor fut confondu, et ne put se faire à l’idée de violer ses conventions au détriment d’un homme qui ne lui avait fait aucun mal,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 29, 'Mais il n’y avait point à résister au roi, et il épiait l’occasion d’user de stratagème pour prendre Machabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 30, 'Celui-ci, de son côté, s’aperçut que Nicanor n’était plus pour lui si bienveillant, et que leurs entrevues accoutumées devenaient moins amicales; il n’augura rien de bon de cette froideur; ayant donc rassemblé un grand nombre de ses compagnons, il se déroba à Nicanor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 31, 'Quand Nicanor vit que Judas l’avait prévenu par sa force et son habileté, il se rendit au temple grand et saint, et ordonna aux prêtres qui offraient les sacrifices de le lui livrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 32, 'Ils jurèrent qu’ils ne savaient où était l’homme qu’il cherchait; alors étendant la main vers le temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 33, 'Il jura à son tour et dit: Si vous ne me livrez Judas enchaîné, je raserai au niveau du sol ce sanctuaire de Dieu, je renverserai l’autel, et j’élèverai ici aux yeux de tous un temple à Bacchus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 34, 'Ayant ainsi parlé, il partit; de leur côté les prêtres, levant les mains au ciel, invoquèrent l’éternel protecteur de notre peuple, et dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 35, 'Seigneur de l’univers, qui n’avez besoin d’aucune chose, vous avez eu pour agréable que ce temple, où vous reposez sous une tente, fût parmi nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 36, 'Maintenant donc, Seigneur, saint de toute sainteté, préservez pour toujours de profanations nouvelles cette demeure récemment purifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 37, 'Or un certain Rhazis, des anciens de Jérusalem, fut signalé à Nicanor; c’était un homme aimant ses concitoyens, de bonne renommée, appelé le père des Juifs à cause de son dévouement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 38, 'Car dès les premiers temps il avait mené une vie pure dans le judaïsme, et pour le judaïsme il avait toujours exposé avec ardeur son corps et sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 39, 'Nicanor, résolu à manifester l’inimitié qu’il portait aux Juifs, envoya plus de cinq cents soldats pour le prendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 40, 'Car il ne doutait pas que son arrestation ne fût un grand malheur pour le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 41, 'Cette troupe était sur le point de forcer sa maison; déjà elle avait enfoncé la porte du vestibule, et ordonnait qu’on apportât du feu pour brûler les autres portes; ne pouvant donc échapper, il se frappa de son glaive,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 42, 'Aimant mieux mourir noblement que de tomber dans les mains des étrangers, et souffrir des outrages indignes de son rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 43, 'Mais dans la précipitation sa blessure ne lui donna pas une mort soudaine; et, la troupe se ruant dans sa demeure, il courut bravement à sa terrasse et se précipita sur la foule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 44, 'Et comme ils reculèrent tous, il se forma un cercle vide au milieu duquel il tomba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 45, 'Respirant encore, et enflammé de colère, il se releva, couvert de son sang qui jaillissait; et, malgré d’horribles blessures, il passa en courant au travers de la foule,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 46, 'Et, s’appuyant sur une pierre droite, ayant déjà perdu presque tout son sang, il s’arracha les entrailles, les jeta à deux mains sur ses ennemis, et pria le Maître de l’âme et de la vie de les lui rendre un jour; et ce fut ainsi qu’il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 1, 'Cependant Nicanor apprit que les compagnons de Judas étaient sur le territoire de Samarie, et il résolut en toute assurance de les attaquer le jour même du repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 2, 'Et quand les Juifs, qui le suivaient par contrainte, lui dirent: Ne les perds pas avec tant de fureur et de barbarie; rends gloire, à cause de sa sainteté, à ce jour que Celui qui voit tout honore de préférence;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 3, 'Ce triple scélérat demanda s’il était au ciel un Dieu tout-puissant qui ait prescrit d’observer le sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 4, 'Et ils lui répondirent: Le Seigneur tout-puissant, le Dieu vivant est au ciel; c’est lui qui a ordonné d’honorer le septième jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 5, 'Et moi aussi, reprit-il, je suis puissant sur la terre; j’ordonne de prendre les armes et d’accomplir les ordres du roi. Néanmoins il ne fut pas maître d’accomplir son mauvais dessein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 6, 'Nicanor, au comble de l’orgueil, avait résolu de faire des compagnons de Judas un trophée public.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 7, 'Pour Machabée, il était toujours confiant dans l’espoir d’obtenir la protection du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 8, 'Il exhorta donc les siens à ne rien craindre de l’attaque des gentils, à se souvenir du secours accoutumé que leur donnait le Ciel, et à compter que le Tout-Puissant leur accorderait encore son aide et la victoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 9, 'Il les entretint de la loi et des prophètes, il leur rappela les batailles qu’ils avaient gagnées, et il leur inspira une grande ardeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 10, 'Et après avoir relevé leurs courages il leur donna ses ordres, et leur représenta en même temps l’infidélité des gentils et la violation de leurs serments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 11, 'Les ayant donc armés tous, non de la sécurité que donnent les boucliers et les javelines, mais de la consolation qui découle des bonnes paroles, il leur raconta une vision digne de foi qu’il avait eue, et qui les combla tous de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 12, 'Voici cette vision: il avait vu, les mains étendues, priant pour tout le peuple juif, le grand prêtre Onias, cet homme vertueux, vénérable dans sa contenance, sage dans ses manières, distingué dans son langage, et dès l’enfance adonné à toutes les pratiques de la vertu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 13, 'Puis pareillement un homme lui était apparu, supérieur au premier en vieillesse et en gloire, encore plus admirable, et entouré d’une plus grande majesté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 14, 'Or Onias, parlant le premier, lui avait dit: Voici celui qui aime ses frères, et qui prie pour le peuple et la ville sainte; c’est Jérémie, le prophète de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 15, 'À ces mots Jérémie, étendant le bras, avait donné à Judas un glaive d’or; et en le lui donnant il avait ainsi parlé:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 16, 'Prends ce glaive: c’est un don de Dieu; avec lui tu briseras tes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 17, 'Animés par ces nobles paroles, capables de porter à la vertu et de fortifier les âmes, les jeunes gens résolurent non de rester dans le camp, mais de s’élancer généreusement, d’engager le combat comme des hommes de cœur, et de décider l’affaire, puisque Jérusalem, le temple et les choses saintes étaient en péril.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 18, 'Car dans cette lutte ils ne songeaient qu’en second lieu à leurs femmes, à leurs enfants, à leurs frères; leur plus grande crainte, et la première, était pour le temple saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 19, 'Quant aux citoyens restés dans la ville, leur angoisse n’était pas moindre, et ils étaient pleins de trouble à cause du combat qui devait se livrer au dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 20, 'Déjà on était de toutes parts dans l’attente de l’événement; les combattants déjà s’entre-choquaient; les armées étaient rangées en bataille, les éléphants occupaient la position la plus favorable, et la cavalerie tenait les deux ailes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 21, 'Quand Judas, ayant considéré le déploiement de cette multitude, l’éclat et la variété des armes, l’aspect sauvage des éléphants, leva les mains au ciel et invoqua le Seigneur, qui fait des prodiges et qui voit tout; car il savait que la victoire n’est pas réservée à la force des armes, mais que c’est lui qui en décide, et qui l’accorde aux plus dignes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 22, 'Et sa prière fut ainsi conçue: C’est vous, Maître, qui avez envoyé votre ange auprès d’Ézéchias, roi de Juda, et il a exterminé cent quatre-vingt-cinq mille hommes du camp de Sennachérib.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 23, 'Maintenant encore, Maître des cieux, envoyez votre ange devant nous, qu’il répande partout le trouble et la terreur. Que, par la grandeur de votre bras,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 24, 'Soient frappés ces hommes qui sont venus, le blasphème à la bouche, pour attaquer votre peuple saint. Telles furent ses paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 25, 'Cependant l’armée de Nicanor s’avançait au son des trompettes et des chants guerriers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 26, 'Tandis que Judas et ses compagnons, avec des prières et des invocations, en venaient aux mains avec l’ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 27, 'Leurs bras combattaient; mais leurs cœurs priaient le Seigneur, et ainsi ils étendirent à terre au moins trente-cinq mille hommes, et ils se réjouirent de ce que Dieu s’était si grandement manifesté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 28, 'Ils étaient sortis d’angoisse et déjà rompaient eurs rangs avec allégresse, quand ils reconnurent que Nicanor avait été tué, couvert de son armure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 29, 'Alors, au milieu des clameurs et de la confusion, ils bénirent le Tout-Puissant dans la langue de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 30, 'Et celui qui avait été dévoué corps et âme à ses concitoyens, celui qui pour eux avait dès sa jeunesse été plein d’amour, ordonna de couper la tête et le bras droit de Nicanor jusqu’à l’épaule, et de les porter à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 31, 'Il y alla lui-même, convoqua le peuple et les prêtres, se plaça devant l’autel, et envoya chercher ceux de la citadelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 32, 'Et il leur montra la tête de l’impie Nicanor, et le bras sacrilége qu’il avait avec tant d’insolence étendu contre la sainte demeure du Tout-Puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 33, 'Puis il coupa la langue de l’impie Nicanor, et il voulut qu’on en jetât les morceaux à manger aux oiseaux, et qu’on suspendît devant le temple les trophées remportés sur la démence de cet homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 34, 'Cependant tout le peuple bénit le glorieux Seigneur du ciel, disant: Béni celui qui a préservé de nouvelles profanations son lieu saint!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 35, 'On suspendit à la citadelle la tête de Nicanor, signe éclatant et visible pour tous de la protection de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 36, 'Et l’on rendit un édit public pour qu’on ne laissât point passer un si grand jour sans en faire la solennité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 37, 'Et qu’en conséquence on célébrât le treizième jour du mois, qui en syriaque s’appelle Adar, la veille du jour dit le jour de Mardochée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 38, 'Nicanor étant mort, comme je viens de dire, à partir de ce moment les Hébreux demeurèrent maîtres de la ville, et c’est là aussi que je finirai mon récit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 39, 'Si dans son arrangement il est utile et agréable, c’est ce que j’ai voulu; s’il est médiocre et de peu de valeur, la faute en est à moi. Car si l’on se trouve mal de boire du vin pur, si l’on ne se trouve pas mieux de ne boire que de l’eau, tandis qu’il est doux de boire un mélange d’eau et de vin, qui complète le plaisir, de même dans l’histoire c’est l’art et la conduite du récit qui charment les oreilles des auditeurs. C’est donc ici que je termine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Philopator ayant appris par ses coureurs qu’Antiochus lui avait enlevé plusieurs de ses forteresses, il rassembla toutes ses forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Et, suivi de sa sœur Arsinoé, il s’avança jusqu’à Raphie, où Antiochus s’était campé avec toute son armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Alors un certain Théodote songea à exécuter le dessein qu’il avait pris de tuer Ptolémée, dans l’espoir que sa tort ferait enfin cesser la guerre. Pour cet effet, il choisit parmi les troupes que ce prince lui avait confiées, celles qui lui parurent les plus propres à seconder son entreprise, et à la faveur de la nuit, il s’avança jusqu’à la tente de Ptolémée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Mais Dosithée, fils de Driusyle, Juif d’origine, et qui depuis avait renoncé à la loi et à la religion de ses pères, ayant été informé des complots secrets de Théodote, avait fait sortir Ptolémée de sa tente et n’y avait laissé qu’un homme de basse condition qu’ils tuèrent au lieu de ce prince.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Alors on se battit avec vigueur de part et d’autre, mais la victoire commençant à pencher du côté d’Antiochus, Arsinoé, les cheveux épars et les yeux baignés de larmes, courait dans tous les rangs, et conjurait les soldats de combattre généreusement pour leur propre liberté et pour celle de leurs femmes et de leurs enfants, leur promettant à tous deux mines d’or par tête, s’ils revenaient victorieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Elle eut bientôt remis la victoire dans son parti, et ses ennemis, ou périrent dans le combat, ou furent faits prisonniers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Ptolémée, échappé avec tant d’avantage aux mauvais desseins de ses ennemis, crut qu’il devait se montrer aux villes voisines, et rassurer par ses discours ceux que la crainte avait pu ébranler. Il fit partout des présents aux temples des dieux, et releva l’espérance de tous ses sujets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Les ambassadeurs des Juifs arrivèrent en ce temps-là; ils étaient chargés de présents, et venaient au nom de toute la nation le féliciter de sa nouvelle victoire. Ptolémée ne les eut pas plutôt vus à sa cour, qu’il se sentit enflammé plus que jamais du désir violent de passer en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Et sans délibérer davantage, il vint à Jérusalem, il y sacrifia au vrai Dieu, et s’acquitta de tout ce que la reconnaissance et la sainteté du lieu pouvaient exiger de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Étant ensuite entré dans le temple, il en admira l’excellente structure, et vit avec étonnement l’art et la magnificence qui régnaient partout. Alors la curiosité s’irritant de plus en plus, il déclara aux Juifs l’impatience où il était de pénétrer jusque dans le sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Ils lui représentèrent en vain que ce lieu auguste était interdit non-seulement à tous ceux de leur nation, mais même à leurs prêtres, à la réserve du souverain Pontife, et qu’encore n’y pouvait-il entrer qu’une seule fois l’année. Toutes les raisons furent inutiles contre un désir si violent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Et pendant qu’on lui montrait dans les livres saints l’endroit où cette loi était marquée (;.), il s’avançait vers le sanctuaire, disant avec fierté qu’aucune loi ne pourrait lui en défendre l’entrée, et que si cet honneur n’avait encore été accordé à personne avant lui, il était d’un rang à devoir l’obtenir. Leur ayant ensuite demandé pourquoi on ne l’avait empêché nulle part d’entrer dans les temples des dieux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Et quelqu’un lui ayant répondu hardiment qu’on l’aurait dû faire: Hé bien! dit-il, puisqu’on a eu quelques');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Alors les prêtres, revêtus de leurs ornements et le visage prosterné contre terre, prièrent le Dieu tout-puissant de les secourir dans cette extrémité et d’arrêter les efforts d’un prince orgueilleux. Au bruit des gémissements et des cris dont ils remplissaient le temple, toute la ville fut troublée, et dans l’incertitude de ce qui pouvait être arrivé, ils accoururent en foule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'De jeunes filles sortant des appartements où on les tenait auparavant renfermées, suivaient leurs mères, et se couvrant la tête de cendre et de poussière, elles faisaient retentir d’horribles clameurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'D’autres, nouvellement mariées, quittant leurs demeures, sans consulter la pudeur et les bienséances de leur sexe, couraient de tous côtés par la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Les mères et les nourrices abandonnaient leurs enfants encore tendres, les unes dans leurs maisons, les autres au milieu des rues, où elles n’avaient plus d’espérance de les retrouver, et elles accouraient au temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Et là toute cette multitude rassemblée sollicitait le ciel contre les entreprises d’un prince impie et orgueilleux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Quelques-uns même, plus hardis que les autres, se mirent devant lui pour l’empêcher d’avancer, criant qu’ils étaient résolus de prendre les armes et de combattre généreusement pour la défense de leur loi, aux dépens même de leurs propres vies. Ces discours n’ayant fait qu’augmenter le désordre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Les anciens et les prêtres eurent beaucoup de peine à les contenir; mais enfin ils les obligèrent de se retirer dans le lieu où l’on fait la prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Et pour eux, ils environnaient le prince, et mettaient tout en usage pour le détourner d’une entreprise si téméraire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Ptolémée, plus aigri par toutes ces résistances, fit quelques pas pour entrer, croyant qu’il en viendrait aisément à bout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Et alors les officiers mêmes de sa garde, s’unissant aux Juifs, priaient ensemble le Dieu tout-puissant de regarder son peuple d’un œil favorable, et de ne point laisser impuni un crime si énorme et si détestable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Du milieu de cette multitude effrayée sortait un cri confus et épouvantable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Toutes les parties du temple parurent emprunter des voix et les mêler avec celles du peuple pour conjurer le ciel de les anéantir plutôt que de souffrir l’abomination dans le lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Alors Simon, le souverain pontife, se prosterna vers le temple, et les mains élevées vers le ciel, il fit sa prière en ces termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Seigneur, Seigneur, Roi du ciel, souverain maître de toutes les créatures, source de toute sainteté... (1524), Dieu tout-puissant, jetez un regard favorable sur votre peuple, qui gémit sous l’oppression d’un roi impie, abominable et enflé de son audacieuse puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Ce vaste univers est l’ouvrage de vos mains, vous le gouvernez par de justes lois, et vous punissez avec rigueur ceux qui font de l’orgueil et de la violence la règle de leurs actions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Vous effaçâtes par un déluge universel l’impiété des premiers hommes, et avec eux périrent aussi les géants, ces hommes audacieux qui avaient mis toute leur confiance en leur propre force. (.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Vous consumâtes dans des torrents de soufre et de feu les habitants de Sodome, ces peuples si fameux par leur orgueil et leurs honteuses abominations; et vous fîtes de cette ville un exemple redoutable à tous les siècles, de la rigueur de vos jugements (.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Vous armâtes votre bras puissant contre Pharaon qui opprimait votre peuple sous une dure servitude; et après avoir frappé de plusieurs plaies ce prince endurci,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Vous l’ensevelîtes dans les profonds abîmes de la mer, avec ses chariots de guerre et toute son armée, et vous délivrâtes de ses mains le peuple dont vous étiez toute l’espérance, et qui, dans les transports de sa juste reconnaissance, publia par des cantiques la force de votre bras tout-puissant. (.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Seigneur, souverain Créateur de ce vaste univers, vous avez choisi cette ville; et quoique suffisant à vous-même, et n’ayant aucun besoin de vos créatures, vous vous l’êtes consacrée; vous y avez paru dans tout l’éclat de votre gloire, et vous l’avez rendue célèbre par la sainteté de votre nom redoutable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Vous avez aimé la maison d’Israël, et vous avez promis que quand même elle se serait éloignée de vous, et que, pour la punir, vous l’auriez réduite à la plus affreuse misère, vous écouteriez néanmoins les prières qu’elle viendrait vous offrir dans ce saint temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Vous êtes fidèle et véritable dans vos promesses; vous avez souvent secouru nos pères dans leurs afflictions, et touché de la sincérité de leurs larmes, vous les avez délivrés des maux extrêmes qu’ils souffraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Et maintenant, Seigneur, Dieu saint, le nombre et l’énormité de nos crimes nous ont réduits dans une affreuse servitude, nos ennemis triomphent de notre faiblesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Et pour comble de misère, un roi hardi et méchant est sur le point de profaner le seul endroit de la terre qui soit consacré à la sainteté de votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Car vous habitez au plus haut des cieux, et ce lieu est inaccessible à des hommes mortels. Mais, Seigneur, quoique vous ayez établi votre gloire au milieu d’Israël, et que vous ayez choisi cet endroit entre tous les autres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Ne vous vengez point sur nous de ces abominations, et ne faites point retomber sur voire peuple les châtiments que nos ennemis ont mérités, et que dans l’excès de leur orgueil ils ne disent: Nous avons foulé aux pieds le lieu saint, comme on foule les lieux profanes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Effacez nos péchés, ne vous ressouvenez plus de nos iniquités, et dans l’extrémité où nous nous trouvons réduits, faites éclater votre miséricorde. Hâtez-vous, Seigneur, de nous secourir, et en nous rendant la paix et la tranquillité, donnez à ce peuple abattu et humilié de justes sujets de vous offrir leurs louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Alors, celui à qui tout est présent, Dieu, la source de toute sainteté, exauça des vœux si purs. Il étendit son bras vengeur sur ce prince, qui allait ajouter à l’orgueil de son cœur l’insulte et l’emportment; et l’agitant avec violence, comme un faible roseau devenu le jouet du vent, il le renversa par terre sans force et sans mouvement, en sorte qu’accablé sous la main qui le frappait avec tant de justice, il ne trouvait plus de voix pour se faire entendre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'En même temps ses favoris et ses gardes, qui étaient les tristes témoins d’un châtiment si subit, craignirent qu’il n’expirât à leurs yeux, et saisis eux-mêmes d’une vive crainte, ils l’emportèrent de ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Ptolémée reprit peu à peu ses sens, et, tout brisé qu’il était, il n’eut aucun regret de son crime; mais en se retirant, il fit d’horribles menaces à tous les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Lorsqu’il fut de retour en Égypte, il mit le comble à sa malice, et soutenu de ses alliés et de ses amis, qui ne connaissaient pas plus que lui la justice et l’équité, il s’abandonna à toutes sortes de voluptés; il poussa même l’effronterie jusqu’à répandre partout les plus noires calomnies contre les Juifs, et engagea ses favoris à le soutenir par de lâches artifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Ayant donc résolu de flétrir la nation Juive par une infamie publique, il fit élever une colonne dans la tour qui était près de son palais. Elle portait par l’inscription que personne n’entrât dans les temples de l’Égypte, sans y sacrifier aux dieux; qu’on fit un dénombrement exact de tous les Juifs qui se trouvaient dans son empire, et qu’ils fussent réduits au rang des esclaves; que, si quelqu’un refusait de se soumettre à cet ordre, il fût mis à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Que ceux qui seraient enregistrés fussent marqués avec un fer chaud d’une feuille de lierre, pour preuve de leur consécration à Bacchus et de leur servitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Mais pour ne point s’attirer en même temps la haine de toute la nation, il ajouta que si quelques-uns d’entre eux voulaient se faire initier aux mystères de ses dieux, ils jouiraient des mêmes privilèges que les citoyens d’Alexandrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 23, 'Plusieurs Juifs renoncèrent aisément à la sainte alliance pour embrasser la religion du prince, dans l’espérance que ce changement leur ouvrirait la voie à toutes sortes d’honneurs et de dignités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 24, 'Mais d’autres, inébranlables dans leur foi, s’y tinrent courageusement attachés, et rachetant leur vie de quelques sommes d’argent, ils tâchaient de se délivrer d’une honteuse servitude; ils avaient une ferme assurance que le ciel combattrait enfin pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 25, 'Ils regardaient avec abomination et comme les véritables ennemis de leur nation ceux qui les avaient si indignement abandonnés, et ne voulaient avoir avec eux ni liaison, ni commerce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'L’impie Ptolémée instruit de toutes ces choses, entra dans une furieuse colère contre les Juifs d’Alexandrie, et s’irritant encore davantage contre ceux qui étaient répandus dans les autres endroits de l’empire, il ordonna qu’on les assemblât tous promptement dans un même lieu, et qu’on les y fit mourir par les supplices les plus honteux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Ces ordres ayant été donnés, les ennemis des Juifs profitant de ces conjonctures si favorables à leur animosité, publièrent partout qu’ils voulaient s’opposer à l’exécution des lois qu’on venait de faire contre leur nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Les Juifs cependant étaient inébranlables dans l’obéissance et la soumission qu’ils devaient aux puissances temporelles; mais comme ils craignaient Dieu et qu’ils cherchaient à se conformer en toutes choses à ses ordonnances, ils se séparaient et s’éloignaient des ennemis de son culte; ce qui les rendait odieux à un petit nombre de personnes, pendant qu’ils forçaient la multitude d’admirer l’innocence et la pureté de leur vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'En effet, dans les bruits que leurs ennemis répandirent contre eux, ils épargnèrent toujours leurs mœurs, et n’attaquèrent que la singularité de leur culte et de leur manière de vivre, disant que c’était une nation ennemie des rois et des puissances, et toujours prête à troubler la tranquillité publique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Pour les Grecs d’Alexandrie qui n’avaient aucun sujet d’inimitié contre les Juifs, ils virent avec douleur l’orage qui se formait contre eux et les mouvements qui allaient hâter leur perte, et dans l’impuissance où ils étaient de les secourir sous un gouvernement si tyrannique, ils venaient compatir à leurs malheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Et par des discours pleins de consolation, ils leur faisaient espérer que cette entreprise tomberait d’elle-même, et que Dieu rendrait inutiles les pernicieux desseins de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Leurs voisins, leurs amis, ceux avec qui ils avaient quelque liaison, s’unirent ensemble; et après en avoir attiré d’autres, ils promirent tous avec serment de ne rien négliger pour les secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Cependant Ptolémée, enflé de sa fortune présente, méprisait la puissance de Dieu, et persistant toujours dans la résolution de se venger des Juifs, il écrivit cette lettre contre eux:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Le roi Ptolémée-Philopator, aux généraux de nos armées, et à tous ceux qui combattent sous leurs ordres dans l’Égypte, et dans les autres lieux de notre empire, salut et prospérité. Nous jouissons nous-même d’une santé parfaite, et le bonheur nous accompagne en toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Après que nous eûmes entrepris l’expédition d’Asie, comme vous le savez, et que soutenus du puissant secours des dieux et de la valeur de nos troupes, nous eûmes fait réussir cette entreprise selon nos désirs, nous jugeâmes que pour soumettre les peuples de Célé-Syrie et de Phénicie nous n’avions point d’autres armes à employer que la douceur, l’humanité et les bienfaits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Et après avoir offert dans tous les temples nos vœux et nos dons, nous formâmes le dessein d’aller à Jérusalem, et d’y rendre de pareils hommages à la Divinité de ces hommes perfides et insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Ils parurent se réjouir à notre arrivée; mais comme cette joie n’était point sincère, à peine nous fûmes-nous avancés pour offrir nous-mêmes dans le temple les riches dons que nous y apportions que, rappelant leur ancien orgueil, ils nous en défendirent l’entrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Et oubliant cette haute puissance où nous nous sommes élevés par notre humanité envers tous les hommes, ils ne dissimulent plus la haine qu’ils ont pour nous; et comme s’ils étaient les seuls maîtres de la terre, ils s’élèvent avec insolence contre les rois leurs bienfaiteurs, et ne peuvent souffrir aucune autorité légitime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Outrés donc de tous ces excès, nous revînmes en Égypte pour y goûter les fruits de nos victoires, et nous laissâmes dans tous les lieux de notre passage des marques éclatantes de notre bonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Enfin, pour mettre le comble à notre générosité envers les Juifs, nous leur accordâmes, par un édit, le pardon général des injures passées, tant à cause des traités faits entre eux et nous, que pour la sûreté d’une infinité d’affaires que nous leur avions confiées avec trop de facilité; nous ne fîmes pas même difficulté de violer en leur faveur les anciens usages de cet empire, en les associant aux privilèges des citoyens d’Alexandrie, et en leur faisant part du sacerdoce perpétuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Mais eux, au contraire, par une méchanceté naturelle et plus forte que tous nos bienfaits, ne se sont pas contentés de rejeter avec mépris le droit de citoyens qu’on leur offrait. Ils regardent même avec abomination ceux de leur nation qui nous sont sincèrement attachés, et ils se flattent que les crimes dont ils nous croient coupables arrêteront enfin le cours de nos prospérités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Étant donc fortement convaincus qu’ils le roulent que de mauvais desseins contre nous, et pour empêcher qu’au premier signal de révolte nous ne trouvions dans ces hommes également traîtres et impies des ennemis redoutables,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Nous vous faisons savoir qu’aussitôt que vous aurez reçu ces lettres, vous ajoutez les tourments à l’insulte, et que vous cous les envoyiez chargés de chaînes avec leurs femmes et leurs enfants, afin qu’ils périssent par une mort honteuse et proportionnée à l’énormité de leurs crimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Car nous espérons que leur perte assurera pour toujours le bonheur et la tranquillité de notre empire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Quiconque, grand ou petit, se rendra protecteur des Juifs, sera puni avec toute sa maison par les supplices les plus honteux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Si quelqu’un, au contraire, vient à déceler un Juif, outre la confiscation de tous les biens du coupable, il aura, de plus, avec la liberté, deux mille drachmes d’argent qui lui seront payés de nos trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Toute maison où l’on trouvera un Juif caché, sera détruite par le feu et rendue à jamais inutile à quelque usage que ce soit. Tels étaient les termes de la lettre du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Dans tous les lieux où ces ordres furent publiés, éclatait la joie commune par des festins et par des acclamations générales, et dans la licence de ces fêtes se montrait enfin cette haine secrète qu’on nourrissait depuis longtemps contre les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Pour eux, ils étaient dans une affreuse désolation, et déploraient, avec les larmes les plus amères et les gémissements les plus vifs, la perte inévitable de leur nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Quelle province, quelle ville, quelles places, quels lieux enfin un peu connus des hommes, ne retentirent point de leurs malheurs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Les ordres des gouverneurs s’exécutaient partout avec tant de barbarie et d’inhumanité, que plusieurs mêmes de leurs ennemis, cédant aux sentiments d’une compassion naturelle, et frappés d’une vive image de l’instabilité des choses humaines, ne pouvaient s’empêcher d’accuser la rigueur avec laquelle on les chassait de toutes les villes pour les conduire en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'À la tête de toute cette multitude rassemblée marchaient des vieillards vénérables qui, malgré leurs corps pesants et courbés, étaient obligés de hâter leurs pas pour éviter les traitements cruels dont on ne rougissait point de les menacer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'De jeunes femmes enlevées à leurs époux parmi les réjouissances de leur nouveau mariage, tombaient tout d’un coup dans un deuil affreux, et changeaient en d’horribles gémissements leurs chansons et leurs cantiques. Elles cachaient sous la poussière, dont elles se couvraient la tête, les ornements et les parfums de leurs cheveux, et toutes liées ensemble, elles suivaient jusqu’au rivage des conducteurs barbares et inhumains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 7, 'Leurs nouveaux époux quittaient les couronnes qu’ils avaient sur leurs têtes, et dans l’attente de la mort des jours destinés chargés de chaînes pesantes, ils passaient au plaisir et à la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 8, 'En cet état, on les traînait avec violence jusqu’au vaisseau qui les devait transporter, les uns attachés par le cou aux bancs des rameurs, d’autres avaient des entraves aux pieds, et pour leur ôter jusqu’à la vue de la lumière pendant tous les jours de la navigation, on mit par dessus leurs têtes une couverture d’ais fort épais; ils furent traités comme les plus scélérats de tous les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 9, 'Les Juifs étant enfin arrivés en Égypte, le roi, ne voulant pas qu’ils eussent aucune communication avec les habitants d’Alexandrie, ni même avec ses troupes, ordonna qu’ils restassent sous des tentes dressées dans l’Hippodrome, qui était un lieu spacieux et très-favorable à exposer aux yeux de tous ceux qui entraient dans la ville et qui en sortaient, la vengeance qu’il allait exercer sur toute cette nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 10, 'Ayant ensuite été informé que quelques Juifs d’Alexandrie venaient souvent mêler leurs larmes à celles de leurs frères, il entra dans une étrange colère, et commanda qu’on traitât ces derniers comme les autres, qu’on les punît des mêmes supplices, et qu’on fit un dénombrement exact de toute la nation des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 11, 'Ajoutant que la servitude à laquelle on les avait déjà assujettis ne les garantirait pas des tourments les plus horribles, jusqu’à ce qu’il eût enfin le plaisir de les voir tous périr en un même jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 12, 'L’on fit donc ce dénombrement avec beaucoup d’exactitude et de diligence, et, quoique on y travaillât régulièrement depuis le lever du soleil jusqu’au soir, il ne put néanmoins être achevé au bout de quarante jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 13, 'Le roi cependant, dans le transport de sa joie faisait des festins à toutes les idoles, et se livrant sans réserve à l’erreur de son cœur, il donnait des éloges profanes et criminels à des dieux muets et incapables de le secourir, pendant qu’il vomissait d’horribles blasphèmes contre le Dieu tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 14, 'Enfin, après quarante jours de travail, les secrétaires rapportèrent qu’ils ne pouvaient plus suffire au dénombrement des Juifs à cause de leur nombre prodigieux, les uns se trouvant répandus dans diverses provinces, les autres se tenant cachés dans les maisons; en sorte que la chose n’était pas même possible quand tous les intendants de l’Égypte s’en mêleraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 15, 'Le roi, peu satisfait de ces raisons, leur fit des menaces très-sévères, et les accusa d’avoir reçu des présents pour soustraire les Juifs à sa vengeance. Cependant il ne douta plus de leur rapport lorsqu’il eut vu de ses propres yeux leurs registres remplis et leurs plumes entièrement usées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 16, 'Ce qui sans doute était l’ouvrage de cette Providence à qui rien ne résiste, et qui du haut du ciel où elle réside, faisait éprouver aux Juifs les effets de sa protection.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Ptolémée transporté d’une colère furieuse, et que rien n’était capable de fléchir, fait appeler Hermon, qui avait l’intendance des cinq cents éléphants, et lui ordonna que le lendemain l’on donnât à ces animaux une grande quantité de parfums broyés avec du vin pur, afin qu’enivrés de ce breuvage violent, ils se tournassent avec plus de fureur contre les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Il se rendit ensuite au festin auquel il avait invité ses courtisans et les généraux de ses armées, tous ennemis communs des Juifs. Hermon se hâtant d’exécuter les ordres du roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Envoya des gardes à l’entrée de la nuit pour lier les mains de tous les Juifs, et prit à leur égard toutes les sûretés imaginables, assuré que le jour suivant serait le dernier pour toute cette nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Et, en effet, leur perte paraissait inévitable dans l’impuissance où étaient les Juifs de rompre les fers dont on les avait garrottés; en cet état ils ne cessaient tous ensemble d’invoquer avec des larmes amères celui à qui appartient l’empire et la puissance sur toutes les créatures, conjurant ce père tendre, ce Dieu de miséricorde, de rendre inutiles les desseins impies qu’on avait formés contre eux, et de les garantir par un secours éclatant d’une mort à laquelle ils ne pouvaient échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Leurs prières parvinrent jusqu’au ciel, et Hermon avait déjà eu soin d’irriter la cruauté des éléphants, en leur faisant boire du vin mêlé d’encens, et s’était rendu au palais de grand matin pour en rendre compte au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Mais Dieu qui tient en sa puissance le repos du jour et de la nuit, ce présent plein de charmes qu’il a fait aux hommes avec tant de libéralité, envoya à Ptolémée un sommeil doux et profond,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Qui fit avorter ses projets funestes, et empêcha l’exécution des ordres qu’il avait donnés le jour précédent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Les Juifs voyant que le temps marqué pour leur supplice était passé, louaient le Dieu de toute sainteté, et le conjuraient de nouveau de faire éclater la puissance de son bras aux yeux des nations orgueilleuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Vers le milieu de la dixième heure du jour, les courtisans étaient assemblés depuis longtemps, lorsqu’un officier entra dans la chambre du roi, et l’ayant éveillé avec assez de peine, lui représenta que l’heure du repas était presque passée; le roi vint aussitôt dans la salle du festin, et après avoir fait asseoir tous les conviés en sa présence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Il les exhorta à donner le reste du jour aux plaisirs et aux délices de la table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Sur la fin du repas, il fit venir Hermon, et lui demanda d’une voix terrible et nenaçante pourquoi on ne l’avait pas encore délivré des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Hermon lui ayant répondu qu’il avait et les conviés l’ayant pleinement justifié sur cela: Hé bien, dit ce roi plus barbare que Chalaris, si un trop long sommeil leur a été favorable, et est cause que je ne suis point encore vengé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Qu’on prépare de nouveau les éléphants, afin que demain sans aucun délai ces ommes abominables cessent enfin de vivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Tous ceux qui étaient présents applaudirent aux discours du roi, et chacun se retira chez soi, moins pour se livrer au sommeil, que pour employer le temps qu’il en restait à imaginer de nouveaux genres l’insultes et d’outrages contre ce peuple malheureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Au chant du coq, Hermon avait déjà rangé ses éléphants sous de vastes galeries, toute la ville accourait en foule et attendait que le jour parût pour jouir de cet horrible spectacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Les Juifs, dans le peu de temps qui leur restait, levaient les mains vers le ciel, et par des torrents de larmes et les gémissements les plus vifs, ils conjuraient le Dieu tout-puissant de leur accorder encore de prompts secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Le jour commençait à paraître et les grands avaient été introduits dans l’appartement du roi, lorsque Hermon vint avertir qu’il était temps de sortir pour se placer, et qu’on allait exécuter les ordres du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Piolémée, surpris de voir sortir tout le monde avec tant d’ardeur et de précipitation, en demanda la cause à Hermon; car il ne se ressouvenait plus des ordres qu’il lui avait donnés le jour précédent, et Dieu, par un effet de sa puissance, avait effacé de la mémoire de ce prince tous les desseins formés contre les Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Alors Hermon et les grands de sa cour répondirent au roi qu’on avait disposé les éléphants et toutes les autres choses nécessaires pour le supplice des Juifs, selon le vif désir qu’il avait témoigné en avoir le jour précédent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Alors le roi changé tout d’un coup par une puissance invisible, entra dans une furiense colère contre Hermon, et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'S’il se fût agi du supplice de quelques-uns de vos enfants ou de vos parents, eussiez-vous excité les éléphants avec autant de zèle que vous l’avez fait contre les Juifs, qui ont toujours eu pour mes prédécesseurs une fidélité inviolable? Sachez donc que sans les services que vous m’avez rendus, et les liens étroits qu’une éducation commune a formés entre vous et moi, je vous ferais mourir en leur place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Hermon fut extrêmement troublé de mployé toute la nuit à exécuter ses ordres, ces menaces auxquelles il s’attendait si peu, et les grands de la cour s’étant retirés tristes et confus de devant le roi, ordonnèrent à tout le peuple de retourner chacun à leurs occupations ordinaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Les Juifs n’eurent pas plutôt appris ce qui s’était passé, que tous de concert ils bénirent le Dieu souverain qui les avait délivrés d’une manière si éclatante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Quelques jours après, Ptolémée donna un second festin, et après avoir exhorté les conviés de se réjouir, il fit appeler Hermon et lui dit d’un ton menaçant: Indigne serviteur, quand entin respecterez-vous mes ordres? Que demain donc, sans différer, les éléphants soient en état de me délivrer des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Ceux qui étaient à table avec le roi, indignés de ces fréquentes irrésolutions, lui parlèrent en ces termes: O roi, jusques à quand nous traiterez-vous comme des gens sans raison; il y a trois jours que vous vouliez la perte des Juifs, et aujourd’hui, changeant de sentiments, vous révoquez ces premiers ordres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Cependant toute la ville est troublée dans l’attente de ce qui arrivera, et les fréquentes assemblées font craindre pour elle les derniers malheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Alors, ce roi rempli de la fureur de Phalaris, sans écouter davantage ce que la pitié pouvait lui suggérer en faveur des Juifs qu’il avait résolu de perdre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Promit par un serment irrévocable qu’il les ferait tous périr sous les pieds des éléphants; que, retournant ensuite en Judée, il mettrait tout à feu et à sang; qu’il détruirait par le feu le temple dont on lui avait défendu l’entrée, et qu’il empêcherait qu’on y offrit davantage des sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Les courtisans se retirèrent très-satisfaits de ce discours, et de ce pas ils allèrent placer dans les endroits les plus commodes de la ville des troupes capables d’y maintenir la tranquillité et le bon ordre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Hermon, de son côté, employa les breuvages les plus violents pour sur exciter la férocité naturelle des éléphants, et voyant que le peuple avait prevenu l’aurore pour s’assembler à l’Hippodrome, il vint au palais, et engagea le roi à venir voir enfin ce qu’il avait désiré avec tant de passion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 31, 'Ptolémée s’animant de nouveau à la colère, suivit les éléphants dans l’hippodrome, pour y donner à sa cruauté un spectacle plein d’horreur et de barbarie, et digne enfin de son impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 32, 'Quand les Juifs aperçurent l’Horrible poussière qu’excitait en l’air, le concours d’éléphants, de gens de guerre et de spectateurs, ils se crurent au dernier instant de leur vie, et à la fin de leur triste attente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 33, 'Ainsi touchés d’une compassion mutuelle, et gémissant sur leur disgrâce commune, ils embrassaient leurs proches; les pères, les mères, les enfants s’embrassaient pour la dernière fois, tous fondaient en larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 34, 'Les mères présentaient à leurs enfants nouvellement nés une nourriture dont ils allaient être bientôt privés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 35, 'Tous ensuite rappelant ce que le ciel avait déjà fait en leur faveur, se prosternèrent contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 36, 'Et par des cris éclatants, ils conjuraient le Dieu tout-puissant d’avoir compassion de l’état où ils étaient réduits, et de les tirer des portes du tombeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 38, '');
