INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 50, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 51, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Alors un prêtre, nommé Éléazar, également respectable par son grand âge et par toutes sortes de vertus, fit cesser les cris des vieillards qui l’environnaient, et, s’adressant au Dieu tout-puissant, il le pria en ces termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Souverain monarque du ciel, Dieu tout-puissant, qui gouvernez tout l’univers avec tant de bonté; père de miséricorde, regardez favorablement la race d’Abraham, les enfants du juste Jacob, ce peuple choisi, qui a été transporté d’une terre étrangère, où il est prêt à succomber sous l’injustice de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Vous signalâtes autrefois votre puissance en faveur d’Israël dans ce même empire, et vous punîtes un roi superbe, cruel et endurci, en l’ensevelissant sous les eaux avec son armée et ses chariots de guerre. (.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Vous frappâtes Sennachérib qui avait mis sa confiance dans le nombre de ses soldats, et qui, après avoir soumis presque toute la terre, osa, dans son orgueil, blasphémer contre la ville sainte, vous en fîtes, aux yeux des nations, un exemple terrible de vos vengeances. ()');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Vous versâtes une douce pluie sur la fournaise de Babylone, et vous en fîtes sortir, sans aucun mal, ces trois jeunes hommes qui y étaient entrés avec joie pour y mourir, plutôt que de sacrifier aux idoles; mais vous ordonnâtes aux flammes de se répandre contre les ennemis de votre nom. (seq.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Vous retirâtes de la fosse aux lions Daniel, votre serviteur, que l’envie y avait fait descendre pour servir de proie à ces animaux cruels, et vous rendîtes Jonas à ses frères, après l’avoir retenu avec rigueur dans le ventre d’une baleine. (.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Et maintenant, Seigneur, vous qui détestez le crime et qui protégez l’innocence, Dieu de miséricorde, ne différez point de secourir un peuple que des nations abominables traitent avec tant d’injustice. (Jon. 1, 1 et seq.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Si nous avons commis l’iniquité dans cette terre étrangère, tirez-nous des mains de nos ennemis, et loin de leurs yeux, vengez vous vous-même,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'De peur que ces nations orgueilleuses ne se vantent d’avoir anéanti le peuple que vous aimiez, et qu’ils ne disent: le Dieu même qu’ils servent n’a pu les délivrer de nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Vous donc, Seigneur, qui, dans l’éternité de votre être, possédez la force et la souveraine puissance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Regardez-nous dans votre miséricorde, nous qui, par l’injustice et l’impiété de nos ennemis, allons perdre la vie comme les plus criminels de tous les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Que les nations soient saisies de frayeur, en voyant aujourd’hui les effets d’une puissance à qui rien ne résiste, et que votre force éclate enfin pour le salut de Jacob: les enfants mêlent leurs larmes avec celles de leurs parents, pour obtenir de vous cette faveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Apprenez aux nations que vous n’avez point détourné votre visage de dessus nous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 14, 'Et accomplissez la promesse que vous fîtes autrefois à votre peuple, en l’assurant que vous ne l’abandonneriez jamais, quand même il aurait été transporté dans une terre ennemie. (, 54.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 15, 'À peine Éleazar eut-il cessé de prier que Ptolémée entra dans l’Hippodrome, suivi des éléphants et de toutes les troupes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 16, 'À cet aspect, les Juifs poussèrent des cris vers le ciel; tous les lieux voisins en retentirent, et toute l’armée du roi en fut touchée jusqu’à répandre des larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 17, 'Alors, celui à qui la gloire, la vérité et la puissance appartiennent, fit sentir sa présence salutaire; il ouvrit les portes du ciel, et il en sortit deux anges revêtus d’un éclat terrible, et qui furent vus de tout le monde, excepté des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 18, 'Ils s’avancèrent vers les troupes ennemies, et y répandirent le trouble et la terreur, et les garrottant de liens invisibles, ils les rendirent sans force et sans mouvement: le roi, saisi et troublé dans toutes les parties de son corps, perdit tout d’un coup la mémoire de ce qu’il avait résolu de faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 19, 'Et les éléphants, se tournant contre ceux qui les suivaient, les foulaient sous leurs pieds et les écrasaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 20, 'Et Ptolémée lui-même, ébranlé par les cris affreux que jetaient les Juifs, qui s’étaient prosternés par terre dans l’attente de la mort,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 21, 'En eut pitié, et se repentit de tout ce qu’il avait fait contre eux; et, s’adressant à ses favoris avec une voix menaçante et entrecoupée de sanglots:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 22, 'Vous m’avez trompé, leur dit-il, et par une cruauté plus noire que celle des tyrans, et digne enfin de votre ingratitude, vous avez cherché à m’ôter en même temps la vie et la couronne, en formant secrètement des entreprises si funestes à l’Etat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 23, 'Par quel ordre injuste les Juifs se trouvent-ils rassemblés ici de toutes parts, pour y périr par de honteux supplices, eux qui n’ont j’amais troublé la tranquillité de cet empire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 24, 'Et qui, de tout temps, nous ont témoigné plus d’attachement et d’affection qu’aucun autre peuple, en s’exposant pour nous à des périls extrêmes et sans nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 25, 'Rompez au plus tôt ces liens dont on les a chargés injustement, et, pleins de regret de ce qui s’est passé, renvoyez-les en paix dans leurs maisons; car ils sont les enfants du Dieu tout-puissant qui vit au plus haut des cieux, et par qui cet empire est resté inébranlable depuis le premier de mes ancêtres jusqu’à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 26, 'Le roi cessa de parler, et les Juifs, se voyant déchargés de leurs chaînes, rendirent grâces à Dieu du secours qu’il leur avait accordé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 27, 'Ptolémée rentra ensuite dans Alexandrie, et ayant fait appeler l’intendant de sa maison, il lui ordonna de fournir aux Juifs, pendant sept jours, du vin et toutes les autres choses nécessaires pour leur nourriture, voulant qu’ils célébrassent leur délivrance dans le lieu même où s’étaient faits les tristes appareils de leurs supplices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 28, 'Les Juifs, échappés à tant de malheurs et à la mort même, dressèrent partout des tentes pour s’y livrer à la joie et aux plaisirs des festins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 29, 'Et quittant les airs tristes et lugubres, ils chantaient les doux cantiques de leur nation, et formaient des chœurs de danses en signe de la paix qu’ils venaient d’obtenir, et, au milieu de toutes ces réjouissances, ils publiaient la gloire et la puissance de celui qui les avaient sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 30, 'Ptolémée donna aussi un grand festin aux premiers de sa cour, et ne cessait de rendre grâces au ciel du salut inespéré qu’il leur avait accordé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 31, 'Pendant que ceux qui s’apprêtaient à triompher des Juifs et à les donner en proie aux oiseaux, ne remportaient, pour fruit de leur rage et de leurs efforts, que la honte et la confusion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 32, 'Les Juifs n’étaient donc occupés qu’à passer ces jours dans les festins, les danses, les actions de grâces et les cantiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 33, 'Ils en firent même une loi pour les races suivantes, et voulurent que ces jours de réjouissances fussent à jamais renouvelés, moins pour servir d’occasion au plaisir et à la bonne chère que pour rappeler dans tous les âges la mémoire d’un si grand bienfait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 34, 'Ayant ensuite été trouver le roi, ils lui demandèrent la permission de retourner chacun chez eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 35, 'Au reste, le dénombrement des Juifs dura l’espace de quarante jours, depuis le vingt-cinq du mois Pachon jusqu’au mois Epiphi, et l’on employa trois jours à disposer toutes choses pour les perdre, depuis le cinq d’Epiphi jusqu’au sept du même mois; mais le Dieu tout-puissant les regarda dans sa miséricorde, et les délivra par des prodiges éclatants, des mains de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 36, 'Ils furent nourris aux dépens du roi jusqu’au quatorzième jour auquel ils le vinrent trouver pour lui demander à s’en retourner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 37, 'Le roi le leur ayant accordé avec toutes sortes de marques de bonté, il écrivit des lettres très-pressantes à tous les gouverneurs de l’empire; elles étaient conçues en ces termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Le roi Ptolémée Philopator, à tous les gouverneurs et autres officiers de l’Égypte: salut et prospérité. Nous et nos enfants jouissons tous d’ure santé parfaite, le Dieu Souverain ayant fait réussir nos affaires selon nos désirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Quelques-uns de nos favoris, prévenus d’une haine injuste contre les Juifs, avaient obtenu de nous, après plusieurs instances, la permission de faire une exacte recherche de tous ceux de ce peuple qui vivent sous notre domination, et de les faire tous périr, comme des rebelles, par de nouveaux genres de supplices,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Disant qu’il n’y avait que ce moyen qui pût assurer la tranquillité de l’empire contre un peuple naturellement ennemi de tous les autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Après donc les avoir rassemblés ici de toutes parts avec une rigueur inouïe, et les avoir traités non pas même comme des esclaves, mais comme les plus criminels de tous les hommes, ils n’ont observé à leur égard aucune formalité, et par une cruauté plus horrible que n’est celle des barbares, ils ont tâché d’assouvir leur haine dans la perte entière de cette nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Pour nous, au contraire, suivant la tendresse paternelle que nous ressentons pour tous les hommes, nous avons conçu une vive indignation contre les auteurs de ces noirs desseins, et nous n’avons rien épargné pour tirer les Juifs de leurs mains cruelles; car nous avons reconnu qu’ils étaient sous la protection du Dieu du ciel, et qu’il les défendait comme un père défend ses propres enfants. Ayant donc rappelé la fidélité inviolable qu’ils ont toujours eue pour nous et pour nos prédécesseurs, nous les avons déclarés innocents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Et nous avons ordonné qu’on les laissât retourner dans les lieux ordinaires de leur résidence, sans qu’on leur fit la moindre insulte, ou qu’on leur reprochât jamais les traitements qu’ils avaient soufferts avec tant d’injustice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Sachez donc que si nous formons contre eux quelques mauvais desseins, ou que nous les inquiétions en quelque manière que ce soit, nous en répondrons, non à un homme, mais à un Dieu terrible et tout-puissant qui étendra sur nous un bras vengeur sans que nous puissions l’éviter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Les Juifs ayant reçu ces lettres, ne se pressèrent point de partir sur-le-champ; mais ils vinrent trouver le roi pour lui demander qu’il leur fût permis de punir par un juste supplice ceux de leur nation qui, sans y être contraints, n’avaient respecté ni le Dieu tout-puissant, ni la sainteté de sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Étant impossible, ajoutèrent-ils, que des hommes qui pour quelque intérêt temporel n’avaient point fait difficulté de violer les préceptes de leur Dieu, respectassent davantage les ordres d’un prince de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Le roi ayant reconnu la vérité de ce qu’ils lui disaient, les combla de louanges et leur accorda la perte de tous ceux des Juifs qui, dans l’étendue de son empire, avaient violé la loi du Seigneur, sans qu’ils pussent jamais appréhender aucune recherche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Les prêtres et toute la multitude des Juifs, après s’être acquittés d’une juste reconnaissance envers le roi, sortirent avec des transports de joie, louant tous le Seigneur à haute voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Et pleins d’un saint zèle, ils se jetèrent sur tous les Juifs impies qu’ils rencontraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Et en tuèrent ce jour-là plus de trois cents, pour étonner par cet exemple ceux qui dans la suite oseraient violer leur sainte loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Pour les autres qui lui avaient été fidèles jusqu’à la défendre au prix de leur propre vie, ils goûtaient les fruits salutaires de leur piété; et couronnés de toutes sortes de fleurs, ils sortaient de la ville formant des chœurs agréables d’hymnes, de cantiques et de cris de joie pour louer le Dieu de leurs pères du salut qu’il venait d’accorder à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Etant arrivés heureusement à Ptolémaïde, surnommée Rhodophoros, à cause de la nature le ce lieu qui porte quantité de roses, ils furent tous d’avis de différer de quelques jours leur embarquement,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Et de passer sept jours entiers dans la joie et dans les festins pour renouveler en ce jour leurs actions de grâces; car le roi avait ordonné qu’on leur fournit abondamment tout ce qui leur serait nécessaire pendant le voyage jusqu’à ce qu’ils fussent de retour chacun chez eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Après donc avoir laissé des');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Ils en partirent libres et contents, et achevèrent leur voyage avec beaucoup de bonheur. Aussitôt qu’ils furent arrivés, on exécuta partout les ordres du roi; ils furent rétablis dans leurs biens et dans leurs maisons, et devinrent plus puissants et plus redoutables à leurs ennemis qu’ils ne l’étaient auparavant; ils ne perdirent pas la moindre partie de ce qui leur appartenait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Car tout leur fut rendu selon l’inventaire qui s’en était fait par l’ordre du roi; en sorte que ceux qui en avaient détourné quelque partie, l’abandonnaient promptement dans la crainte d’être punis. C’était ainsi que le Dieu souverain achevait de protéger son peuple par des prodiges de sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Que celui qui a délivré Israël soit béni dans tous les siècles. Ainsi-soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'C\'est un sujet de haute philosophie que j\'ai le dessein de traiter: la raison pieuse est-elle la souveraine des passions? Aussi, je crois devoir vous conseiller de donner toute votre attention à la philosophie que je vais vous exposer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Le sujet, en effet du point de vue de la science, présente pour tout le monde un intérêt essentiel; en outre, il comporte l\'éloge de la plus grande des vertus, je veux dire de la prudence:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Si réellement on peut montrer non seulement que la raison maîtrise les passions qui s\'opposent à la tempérance, gloutonnerie et désir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Mais encore qu\'elle domine les passions qui s\'opposent à la justice, telles que la méchanceté, et les passions qui s\'opposent au courage, colère, douleur, peur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Comment donc, dira-t-on peut-être, si la raison commande aux passions, ne domine-t-elle pas l\'oubli et l\'ignorance? Cette objection est ridicule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'En effet, la raison commande non pas à ses propres passions, mais aux passions contraires à la justice, au courage, à la tempérance et à la prudence; et, si elle leur commande, c\'est non pas pour les supprimer, mais pour ne point céder devant elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Je pourrais vous apporter bien des preuves, tirées des cas les plus divers, à l\'appui de cette assertion que la raison pieuse est la dominatrice des passions;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Mais la preuve la plus forte, c\'est, à mon avis, la bravoure de ceux qui sont morts pour la vertu: Eléazar, les sept frères et leur mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Car eux tous, c\'est par leur mépris des souffrances, c\'est jusqu\'à la mort qu\'ils ont prouvé que la raison maîtrise les passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Et, certes, en considérant leurs vertus, je puis bien faire l\'éloge de ces héros qui, en ce jour que nous célébrons, sont morts avec leur mère pour la cause du bien; mais, en considérant les honneurs qu\'ils ont obtenus, laissez- moi aussi les déclarer bienheureux:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Par leur courage, par leur endurance, ils ont conquis l\'admiration non seulement du monde entier, mais encore de leurs propres bourreaux, et ainsi ils ont été causes de la chute de la tyrannie qui asservissait la nation; par leur constance ils ont vaincu le tyran, et c\'est par eux que le sol de la patrie a été purifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Mais j\'aurai tout loisir dans un instant de parler de leurs exploits: je dois commencer, selon mon habitude, par présenter la thèse d\'une manière générale, puis j\'en viendrai à leur histoire, rendant ainsi gloire au Dieu de toute sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Nous nous demandons donc si la raison est la dominatrice des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Ainsi, nous devons déterminer ce qu\'est la raison, ce qu\'est la passion, combien de classes de passions il y a, et si la raison commande à toutes les passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Je dis que la raison est l\'intelligence choisissant, avec un droit raisonnement, la vie de la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Je dis que la sagesse est la connaissance des choses divines et des choses mauvaises, et de leurs causes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Je dis encore qu\'elle est l\'éducation même de la Loi, par laquelle nous apprenons les choses divines dignement et les choses humaines utilement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'La sagesse comprend quatre classes: la prudence, la justice, le courage et la tempérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'La principale d\'entre elles est la prudence: c\'est par elle que la raison maîtrise les passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 20, 'Quant aux passions, les deux espèces les plus générales sont le plaisir et la douleur. Chacune d\'elles prend naissance et dans le corps et dans l\'âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 21, 'Nombreux aussi est le cortège des passions autour du plaisir comme autour de la douleur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 22, 'Devant le plaisir marche le désir, derrière le plaisir la joie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 23, 'Devant la douleur va la peur, derrière la douleur le chagrin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 24, 'La colère est une passion commune au plaisir et à la douleur, si l\'on pense à l\'offense qu\'on a subie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 25, 'Dans le plaisir se trouve en particulier l\'inclination au mal, celle des passions qui revêt le plus grand nombre de formes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 26, 'Dans l\'âme, jactance, avarice, vanité, dispute, envie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 27, 'Dans le corps, voracité, gloutonnerie, gourmandise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 28, 'Donc, le plaisir et la douleur étant comme deux plantes qui grandissent dans le corps et dans l\'âme, nombreux sont les rejetons qui poussent autour de ces deux passions:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 29, 'La raison, universelle jardinière, s\'occupe de chacun, émonde, taille, arrache, arrose, irrigue de mille manières, défrichant ainsi le taillis des inclinaisons et des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 30, 'La raison, en effet, est la chef des vertus et la dominatrice des passions. Constatez, je vous prie, en premier lieu, en observant l\'action inhibitrice de la tempérance, que la raison est la souveraine des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 31, 'La tempérance, n\'est-il pas vrai, consiste à maîtriser ses désirs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 32, 'Or, parmi les désirs, les uns relèvent de l\'âme, les autres du corps: il est clair que la raison domine les uns et les autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 33, 'Ainsi, quand nous sommes mus vers un mets défendu, d\'où vient que nous nous détournions du plaisir qu\'il peut nous procurer? N\'est-ce pas parce que la raison a le pouvoir de maîtriser cet appétit? C\'est mon avis, à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 34, 'Et quand nous avons envie de manger un poisson, d\'un oiseau, d\'un animal, bref d\'un mets quelconque que la Loi nous interdit, si nous nous abstenons c\'est à cause de la maîtrise qu\'exerce la raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 35, 'En effet, la passion de l\'appétit s\'arrête, vaincue, devant l\'intelligence tempérante, et tous les mouvements du corps sont domptés par la raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'D\'autre part, faut-il s\'étonner, si les désirs de l\'âme pour l\'union avec la beauté arrivent à perdre leur empire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'C\'est précisément l\'éloge qu\'a mérité Joseph le tempérant, à savoir que, par le jugement, il a maîtrisé la luxure;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Car, bien que jeune et en pleine vigueur pour le rapprochement sexuel, il a brisé, grâce à la raison, l\'aiguillon de la passion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Il est clair, d\'ailleurs, que la raison maîtrise non seulement le feu de la luxure, mais encore tous les désirs:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'La Loi, n\'est-il pas vrai, proclame: Tu ne désireras pas la femme de ton prochain, ni rien qui appartienne à ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Eh bien! Quand la Loi dit que nous ne désirerons pas, il m\'est bien plus facile de nous persuader que la raison a le pouvoir de commander aux désirs, comme aussi aux passions qui s\'opposent à la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Comment, en effet, un homme qui est par nature gourmand, glouton, ivrogne, peut-il être changé par l\'éducation s\'il n\'est pas évident que la raison est maîtresse des passions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'A la vérité, dès qu\'on met sa conduite en accord avec la Loi, si, par exemple, on est attaché à l\'argent, on fait violence à sa nature et l\'on prête sans intérêt à ceux qui sont dans le besoin, même si l\'approche de la septième année doit bientôt annuler la dette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Si l\'on est parcimonieux la Loi s\'impose à vous au nom de la raison et l\'on s\'abstient de glaner dans les champs ou d\'arracher les dernières grappes dans les vignes. Et dans tous les autres cas nous pouvons aussi reconnaître que la raison soit commander aux passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'La Loi, en effet, domine l\'amour qu\'on porte à ses parents: elle ne trahit jamais la vertu à cause d\'eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Elle maîtrise l\'amour qu\'on porte à son épouse: elle la corrige si elle commet une faute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Elle règne sur l\'amour qu\'on porte à ses enfants: elle les châtie quand ils sont méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Elle commande à l\'attachement qu\'on a pour ses amis: elle les blâme s\'ils font quelque chose de mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Enfin, ne pensez pas qu\'il soit invraisemblable que la raison, au nom de la Loi, maîtrise même la haine, et qu\'on s\'abstienne de couper les arbres fruitiers qui appartiennent aux ennemis, qu\'on sauve une bête que son adversaire a laissé échapper, qu\'on l\'aide à relever celle qui est tombée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'On peut également prouver que la raison commande aussi aux passions les plus violentes, l\'ambition, la vanité, la jactance, l\'orgueil, l\'envie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Toutes ces passions mauvaises, l\'intelligence tempérante les écarte, tout comme la colère; car elle command aussi à celle-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Moïse, il est vrai, s\'était irrité contre Datham et Abiron: cependant, il sut se garder de rien faire contre eux par colère, mais il apaisa sa colère par la raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'L\'intelligence tempérante, en effet, a le pouvoir comme je l\'ai dit, de triompher des passions, mais elle transforme les unes, tandis qu\'elle réduit les autres à l\'impuissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Pourquoi Jacob, notre père très sage, accuse-t-il les gens de Siméon et de Lévi d\'avoir, non par raison, massacré en masse les Sichémites? Il dit, en effet: Maudit soit leur colère!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Si la raison n\'était pas capable de commander à la colère, il ne parlerait pas ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Le jour où Dieu a créé l\'homme, il a planté en lui les passions et les inclinations:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Mais, à ce moment même, au-dessus de toutes il a placé comme sur un trône, par le moyen des organes des sens, l\'intelligence, sainte souveraine;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'A cette intelligence il a donné une loi: et qui vit selon cette Loi est roi d\'une royauté de tempérance, de justice, de bontés et de courage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Comment, donc, objecte-t-on si la raison commande aux passions, ne commande-t-elle pas l\'oubli et à l\'ignorance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Un tel propos est parfaitement ridicule. Il est clair, en effet, que la raison maîtrise non pas ses propres passions mais celles du corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Ainsi, nul d\'entre vous ne peut arracher un désir, mais la raison peut vous aider à ne pas devenir l\'esclave de ce désir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Nul d\'entre vous ne peut arracher de son âme la colère, mais la raison a le pouvoir de calmer la colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Nul d\'entre vous ne peut arracher la méchanceté, mais la raison peut vous aider dans la lutte et vous empêcher de capituler devant la méchanceté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'La raison, en effet, n\'est point l\'extirpateur des passions, mais leur adversaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'L\'exemple de la soif du roi David peut, à coup sûr, servir à rendre ce raisonnement plus clair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'David avait durant une journée entière combattu les étrangers, et aidé les guerriers de son peuple, il en avait tué un grand nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Le soir venu, couvert de sueur et très las, il alla vers la tente royale, autour de laquelle campait toute l\'armée de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Ils étaient donc tous occupés au repos:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Mais le roi, que consumait une soif intense, ne pouvait bien que les sources abondantes fussent à proximité, étancher sa soif avec cette eau;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Un désir irrationnel pour l\'eau qui se trouvait chez les ennemis se tendait et se détendait en lui, l\'enflammant et le consumant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Les gardes se mirent à murmurer contre ce désir du roi; mais deux jeunes gens, soldats robustes, humiliés de voir le roi en proie à ce désir, revêtirent leur armure, prirent une cruche et franchirent les retranchements adverses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Échappant aux sentinelles qui veillaient aux portes, ils allèrent à la découverte à travers tout le camp ennemi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Ils trouvèrent enfin la source et pleins de hardiesse, ils y puisèrent et apportèrent le breuvage au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Mais celui-ci, bien que brûlant des ardeurs de la soif, estima qu\'un breuvage auquel il avait donné une valeur de sang était pour l\'âme un épouvantable danger:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Il opposa donc la raison au désir et offrit cette eau en libation à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Car l\'intelligence tempérante est capable de triompher de la contrainte des passions: elle éteint le feu de leurs brûlures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Elle surmonte les douleurs du corps, si extrêmes qu\'elles soient et sûre de l\'excellence de la raison, elle repousse avec mépris toutes les dictatures de la passion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Mais il est temps puisque ce jour nous y invite, d\'exposer l\'histoire de la raison tempérante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Nos pères jouissaient d\'une profonde paix, grâce à la bonne observation de la Loi et leurs affaires allaient si bien que le roi d\'Asie, Sélencus Nicanor, levait pour eux l\'impôt destiné au service du temps et leur reconnaissait le droit de cité:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Lorsque quelques-uns se posant en novateurs, au mépris de la concorde générale, attirèrent sur nous toutes sortes de malheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Un certain Siméon était en lutte contre Onias, qui était alors grand prêtre, exerçant cette fonction à vie, homme du plus haut mérite. Mais, en dépit de toutes sortes de calomnies, il ne pouvait lui nuire dans l\'esprit du peuple; il prit alors la fuite, dans le dessin de trahir sa patrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Il alla trouver Appolinius, gouverneur de Syrie, de Phénicie et de Cilicie et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Je suis plein de zèle pour les intérêts du roi; je viens donc pour vous avertir qu\'il y a dans les trésors du temple de Jérusalem des millions appartenant à des particuliers: cette fortune n\'a rien à voir avec le temple, mais elle revient au roi Sélencus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Appolinius s\'informa des détails de l\'affaire. Puis il félicita Simon de sa sollicitude à l\'égard du roi, et se rendit auprès de Sélencus pour le prévenir de l\'existence de ce trésor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Ayant reçu tout pouvoir dans cette affaire, il marcha en hâte vers cette patrie, accompagné de Simon, l\'homme maudit et d\'une très forte armée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Aussitôt arrivé, il déclara que par ordre du roi, il venait prendre possession de l\'argent des particuliers déposé dans le trésor du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'A ces paroles, le peuple murmura et protesta, considérant qu\'il serait véritablement terrible que fussent spoliés ceux qui avaient confié leurs dépôts au trésor sacré et ils firent tout leur possible pour l\'empêcher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Mais Appolinius menaçant, se dirigea vers le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Les prêtres, les femmes, les enfants réunis dans le temple, supplièrent Dieu de protéger le Saint Lieu outragé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Comme Appolinius entrait avec une troupe en armes pour enlever l\'argent, du ciel apparurent des anges montés sur des chevaux et revêtus d\'armes éclatantes; une crainte et une frayeur immenses les saisirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Appolinius tomba à demi-mort sur le parvis des Gentils; il tendit les mains vers le ciel et en pleurant il supplia les Hébreux d\'intercéder pour lui et de fléchir l\'armée du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Il avait péché, disait-il et son péché était si grave qu\'il méritait la mort, mais, s\'il était sauvé il célébrerait devant tous les hommes la félicité du Saint Lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Ému par ces paroles et craignant aussi que le roi Sélencus n\'attribuât la mort d\'Appolinius à un complot tramé par les hommes et non à la justice divine, le grand prêtre Onias intercéda pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Ainsi sauvé par miracle, Appolinius se retira, ayant à rendre compte au roi de ce qui lui était arrivé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Le roi Sélencus mourut: son fils Antiochus Epiphane lui succéda sur le trône; c\'était un homme orgueilleux et terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Il ôta le souverain pontificat à Onias et le donna à Jason, frère d\'Onias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Qui s\'était engagé s\'il revenait de lui cette charge, à lui donner chaque année trois mille six cent soixante talents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Le roi lui confia donc le souverain pontificat et le gouvernement de la nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Jason introduisit dans la nation de nouvelles mœurs et un régime nouveau, entièrement contraires à la Loi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Non seulement il construisit un gymnase sur la citadelle même de notre patrie, mais encore il supprima le service du temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'La justice divine, irritée de ces crimes, attira sur eux l\'hostilité d\'Antiochus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Comme celui-ci avait fait la guerre en Egypte contre Ptolémée, il apprit que le bruit de sa mort s\'était répandu, les Jérosolymites en avaient témoigné une joie extrême;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Il marcha donc aussitôt contre eux, mit leur ville au pillage et prit un décret punissant de mort quiconque d\'entre eux semblerait vivre selon la Loi de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Mais il ne put aucunement détruire par ses décrets la fidélité du peuple à la Loi; il voyait au contraire ses menaces et ses châtiments tous réduits à l\'impuissance:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Des femmes mêmes pour avoir fait circoncire leurs enfants, bien qu\'elles savaient d\'avance quel serait leur sort, étaient précipitées du haut des murailles en même temps que leurs nouveau-nés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Voyant donc que le peuple continuait à mépriser ses décrets, il eut recours aux tourments pour forcer lui-même chacun de ceux qui appartenaient à la nation à manger des viandes impures et à abjurer le judaïsme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Le tyran Antiochus siégea donc ainsi que ses assesseurs: son trône était placé sur un lien élevé et les soldats en armes se tenaient debout en cercle autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Il ordonna aux gardes d\'amener chacun des hébreux et de les forcer à manger de la chair de porc et des viandes consacrées aux idoles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Que si quelques-uns refusaient de se souiller ainsi en mangeant, on le ferait mourir sur la roue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Après qu\'on en eût arrêté un grand nombre, le premier de la troupe qu\'on amena devant le roi fut un hébreu nommé Eléazar. Il était de la race sacerdotale, versé dans la connaissance de la Loi; déjà avancé en âge, il jouissait auprès de plusieurs personnes de la cour du tyran d\'une réputation de philosophe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Antiochus en le voyant lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Avant qu\'on ne commence à te torturer, je voudrais moi-même, ô vieillard, te donner le conseil de manger de la chair de porc et de te sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Je respecte ton âge et tes cheveux blancs mais malgré ces cheveux blancs, même une vie si longue tu ne semble pas atteindre à la philosophie, attaché que tu es aux pratiques des Juifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'En effet, d\'où vient l\'horreur que tu conçois pour la chair de cet animal qui est très bonne et dont la nature nous a fait don?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'C\'est une folie de ne pas jouir des plaisirs innocents et c\'est une injustice que de rejeter les dons de la nature.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Mais tu commettras, il me semble, une folie encore plus grande si à tes opinions creuses sur la vérité tu ajoutes le mépris de ma personne et attires ainsi sur toi le châtiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Ne vas-tu pas te réveiller des sornettes que débite votre philosophie? Ne vas-tu pas laisser là tes divagations [la raison], adopter une mentalité qui soit digne de ton âge et t\'adonner à la philosophie vraie, celle de l\'intérêt?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Ne béniras-tu pas mon exhortation charitable? N\'auras-tu pas pitié de ta vieillesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Pense en effet que même s\'il existe une puissance qui veille à l\'observation de ces pratiques auxquelles vous êtes attachés, cette puissance te pardonnerait toute transgression imputable à la contrainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Tandis que le tyran l\'exhortait ainsi à manger des viandes défendues, Eléazar demanda la permission de parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'L\'ayant reçue il se mit à prononcer ce discours:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Nous autres, Antiochus, qui sommes convaincus de vivre sous une loi divine, nous ne reconnaissons pas de plus forte contrainte que celle de l\'obéissance à notre Loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'C\'est pourquoi nous ne croyons pas pouvoir la transgresser de quelque manière que ce soit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Même en supposant avec toi que, en réalité notre Loi ne soit pas divine, si nous pensons, nous autres que cette Loi est divine, même dans ton hypothèse, il ne nous serait pas permis de renoncer à l\'opinion que nous avons de la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Ne crois donc pas que ce serait une faute légère que de manger des viandes impures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Car transgresser la Loi dans les petites choses est égal à la transgresser dans les grandes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Dans l\'un et l\'autre cas la Loi est méprisée tout semblablement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Tu te railles de notre philosophie comme si elle nous faisait vivre d\'une manière contraire à la raison:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Eh oui! Puisqu\'elle nous enseigne à la tempérance qui nous fait commander à toute la foule des plaisirs et des désirs; puisqu\'elle nous exerce au courage qui nous fait endurer volontairement toutes sortes de douleurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Puisqu\'elle nous instruit de la justice, qui quelles que soient les dispositions de l\'âme, nous fait agir avec équité puisqu\'elle nous enseigne la piété qui nous fait rendre au seul Dieu qui soit, un culte magnifique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'C\'est pourquoi nous ne mangeons pas de viandes impures; car nous croyons que la Loi est de Dieu et nous savons que le Créateur du monde quand il établit une loi, sait aussi se conformer à la nature et nous marquer sa tendresse:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Il nous ordonne de manger ce qui doit convenir à nos âmes mais les viandes qui doivent leur être contraires, il nous interdit d\'y goûter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'C\'est une violence tyrannique que de nous contraindre non seulement à transgresser la Loi mais aussi à manger rien que pour pouvoir te railler à nous voir prendre cette nourriture souillée que nous détestons!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Mais de ce rire-là tu ne riras pas à mon sujet!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Je ne violerai pas les sacrés serments de nos ancêtres qui ont juré d\'observer la Loi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Pas même si tu m\'arraches les yeux et répands mes entrailles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Non, je ne suis pas si vieux ni si lâche que ma raison ne soit encore en pleine jeunesse pour la cause de la piété!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 32, 'Contre cela prépare les roues! Attise le feu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 33, 'Non je n\'aurai point pitié de ma vieillesse au point de m\'employer moi- même à détruire la Loi de mes pères!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 34, 'Ô Loi qui nous instruit, je ne te trahirai point! Je ne t\'abandonnerai jamais, aimable tempérance!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 35, 'Je ne rougirai point de toi, ô raison philosophe! Je ne vous renierai point, glorieux sacerdoce et science de la Loi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 36, 'Tu ne souilleras point la bouche vénérable d\'un vieillard, ni le déclin d\'une vie toute conforme à la Loi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 37, 'Pur, me recevront mes pères, sans que j\'aie redouté tes contraintes mortelles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 38, 'Car tu peux sur les impies exercer ta tyrannie mais de mes convictions touchant la piété tu ne seras pas le maître ni par tes paroles ni par tes actes!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Telle fut l\'éloquente réponse d\'Eléazar aux exportations du tyran: les gardes alors l\'entourèrent et l\'entraînèrent brutalement vers les instruments de torture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Ils commencèrent par dépouiller le vieillard de tous ses vêtements: mais il restait paré de la noblesse qui rayonne de la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Puis il lui lièrent les bras de part et d\'autre et le frappèrent avec des fouets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Obéis aux ordres du roi! criait de l\'autre côté un héraut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Mais lui, généreux et noble, Eléazar en toute vérité, n\'était nullement ébranlé, tout comme s\'il n\'avait été torturé qu\'en songe;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Tenant ses yeux fixement levés vers le ciel, ce vieillard offrait ses chairs aux fouets pour être déchirées, le sang coulait de toutes parts et ses flancs n\'étaient plus que plaies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Il tomba sur le sol, son corps ne pouvait plus supporter les souffrances mais du moins sa raison demeura droite et inébranlable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Oui, l\'un des cruels gardes lui lançait en bondissant des coups de pied dans les côtes, pour l\'obliger à se relever chaque fois qu\'il tombait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Mais il endurait les souffrances méprisait la contrainte et restait fort parmi les tourments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Bravant les coups comme un noble athlète, ce vieillard triomphait de ses bourreaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Oui le visage baigné de sueur, la poitrine haletante, il faisait par sa constance l\'admiration de ceux-là mêmes qui le torturaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Quelques-uns des courtisans du roi, soit par pitié pour sa vieillesse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Soit par une sympathie qu\'éveillaient leurs amicales relations, soit par admiration pour son courage, s\'approchèrent alors de lui et lui dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Pourquoi dans de tels maux follement te donnes-tu à toi-même la mort, Eléazar?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Nous allons t\'apporter des aliments bouillis: toi fais semblant de manger du porc et sauve-toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Eléazar, comme si leur conseil rendait plus cruelles encore ses tortures s\'écria:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Non! Loin de nous une aussi abominable pensée! Nous n\'irons pas, nous enfants d\'Abraham jouer par faiblesse d\'âme une comédie indigne de nous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'En effet, ce serait une folie si nous qui avons vécu jusqu\'à la vieillesse dans l\'attachement à la vérité et qui conservons fidèles à la Loi notre opinion sur ce genre de vie, si dis-je nous venions maintenant à changer');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Et si notre personne devenait pour la jeunesse un modèle d\'impiété pour que nous servions d\'exemple à ceux qui mangent des mets impurs!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Ce serait une honte si nous prolongions notre vie de quelques jours pour être durant ces jours mêmes par notre couardise l\'objet de la risée générale,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Si nous encourions par notre lâcheté le mépris du tyran, si nous renoncions à l\'honneur de défendre jusqu\'à la mort notre Loi divine!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Tout au contraire nous autres enfants d\'Abraham mourrez noblement pour la cause de la piété!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Et vous! Gardes du tyran, qu\'attendez-vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Le voyant aussi magnanime en présence des contraintes et nullement ébranlé même par leur pitié, ils le conduisirent vers le feu:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Là ils le jetèrent, le brûlant avec des instruments de torture et ils lui versaient des liqueurs puantes dans les narines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Déjà consumé jusqu\'aux os et sur le point de défaillir il leva les yeux vers Dieu et dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Tu le sais ô Dieu! je pouvais me sauver, mais je meurs à cause de la Loi dans le supplice du feu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Sois propice à notre nation, satisfait de ce châtiment que nous supportons pour eux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Fais que mon sang les purifie et reçoit mon âme comme rançon de leurs âmes!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'C\'est en disant ces mots que le saint homme noblement mourut au milieu des tourments; jusque dans les dernières tortures, la raison l\'aida çà résister en champion de la Loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 31, 'On peut don affirmer que la raison pieuse est la dominatrice des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 32, 'Si en effet c\'était les passions qui avaient commandé à la raison, c\'est à elles que je rendrais le témoignage qu\'elles ont la suprématie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 33, 'Mais puisqu\'au contraire c\'est la raison qui a vaincu les passions c\'est à la raison qu\'il convient que nous attribuions le pouvoir et la souveraineté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 34, 'Et nous avons le droit de déclarer que le commandement appartient à la raison puisque celle-ci méprise même les souffrances qui viennent du dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 35, 'Car aussi il est ridicule. Et je prouve non seulement que la raison commande aussi aux plaisirs loin de leur céder.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'En effet semblable à un habile pilote la raison de notre père Eléazar gouverna le vaisseau de la piété au milieu de la mer des passions;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Les menaces du tyran qui le battaient comme la tempête, les tortures qui le submergeaient comme des lames,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Ne lui firent lâcher à aucun moment le gouvernail de piété jusqu\'à ce qu\'il cinglât vers le havre de l\'immortelle victoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Nulle ville assiégée à l\'aide des machines de guerre les plus nombreuses et les plus variées n\'a jamais résisté comme cet homme vraiment sacré: sa sainte âme attaquée par les coups, par les tortures, par le feu a vaincu ceux qui l\'assiégeaient, grâce à la raison unie à la piété qui le couvrait comme un bouclier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Car dressant sa pensée comme un rocher abrupt, notre père Eléazar brisa les flots furieux de la passion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Ô prêtre digne du sacerdoce tu n\'as point souillé tes dents saintes! Tu n\'as point par des mets impurs profané tes entrailles, elles qui ne s\'ouvrirent jamais qu\'à la piété et à la pureté!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Ô l\'écho de la Loi et le philosophe de la vie divine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'C\'est ainsi que doivent être ceux qui sont investis des fonctions saintes; des défenseurs de la Loi luttant contre les passions jusqu\'à la mort au prix de leur propre sang, au prix d\'une noble sueur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Ô père, par ta constance glorieuse tu as fortifié notre fidélité à la Loi par tes paroles vénérables tu as gardé de la ruine nos coutumes sacrées, par tes actes tu as confirmé les discours de la philosophie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Ô vieillard plus fort que les tourments et plus énergique que le feu qui te brûlait, roi très puissant des passions, Eléazar!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Car comme notre père Aaron, armé de l\'encensoir courut à travers la foule et vainquit l\'ange de feu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Ainsi à travers le feu, consumé, Eléazar le fils d\'Aaron garda sa raison immuable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Mais ce qui est le plus admirable c\'est que ce vieillard dont déjà l\'énergie corporelle était détendue, dont les muscles étaient relâchés, dont les nerfs étaient affaiblis, redevient un jeune homme');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Par l\'esprit de la raison et grâce à sa raison digne d\'Isaac, réduisit à l\'impuissance la torture aux cent têtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Ô bienheureuse vieillesse! ô vénérables cheveux blancs! ô vie fidèle à la loi, que le sceau authentique de la mort a porté à la perfection!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Si donc, à cause de la piété un vieillard a méprisé les tourments jusqu\'à la mort, il faut avouer que la raison pieuse est la souveraine des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Mais dirait-on peut-être, ce n\'est pas tout le monde qui maîtrise les passions, c\'est qu\'aussi tout le monde n\'a pas une raison prudente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Mais ceux qui de tout leur cœur s\'adonnent avec vigilance à la piété, ceux-là seuls sont capables de commander aux passions de la chair,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Convaincus qu\'en Dieu, ils ne meurent pas, comme ne sont pas morts non plus nos patriarches Abraham, Isaac, Jacob mais qu\'ils vivent en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Ne soyons donc point d\'objection dans le fait que certains apparaissent asservis à leurs passions, par suite de la faiblesse de leur raison:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Mais est-il possible qu\'un philosophe qui suit avec piété et intégralement la règle de la philosophie qui croit en Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'qui sait que c\'est un bonheur d\'endurer pour la vertu toutes sortes de souffrances, ne maîtrise pas les passions à cause de la piété?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Seul en effet l\'homme sage et tempérant, courageux est le maître des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Eh oui, c\'est pour cela que des adolescents adonnés à la philosophie ont su aussi grâce à la raison unie à la piété triompher d\'instruments de torture plus cruels encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Car le tyran, vaincu devant tous dans sa première tentative puisqu\'il n\'avait pu forcer un vieillard à manger des viandes impures, entra alors dans une violente colère et ordonna qu\'on lui amenât d\'autres Hébreux pris parmi les jeunes gens: s\'ils goûtaient des viandes impures on les relâcherait après qu\'ils auraient mangé; s\'ils refusaient on les soumettrait à des tortures encore plus cruelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'A peine eut-il donné cet ordre qu\'on amena devant lui sept frères, ainsi que leur vieille mère: ceux-ci étaient d\'une grande beauté, pudiques, distingués, d\'un charme extrême.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'En les voyant qui entouraient leur mère, placée comme dans un chœur, au milieu d\'eux, il s\'enquit à leur sujet et frappé par leur distinction et de leur noblesse, il leur sourit, les appela près de lui et leur dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Jeunes gens, je suis plein de bienveillance pour chacun de vous: j\'admire votre beauté et j\'honore hautement un tel nombre de frères. Aussi, non seulement je vous conseille de ne pas vous livrer à la même folie que ce vieillard qu\'on vient de torturer, mais encore je vous exhorte à céder à mon vouloir et à jouir de mon amitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Car tout comme je puis punir ceux qui désobéissent à mes ordres, je puis favoriser ceux qui m\'obéissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Croyez-moi bien vous recevrez des charges éminentes dans mon gouvernement si vous renoncez à la Loi ancestrale qui vous régit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Adoptez la manière de vivre des Grecs, changez vos habitudes, prenez goût à votre jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Car si vous me mettez en colère par votre désobéissance vous m\'obligerez à recourir à de terribles châtiments et à vous faire tous périr dans les tourments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Ayez donc pitié de vous-mêmes puisque de mon côté moi qui suis l\'ennemi de votre nation, j\'ai pitié de votre jeunesse et de votre beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Ne réfléchirez-vous donc point à ceci, qu\'à me désobéir vous ne gagnerez qu\'une chose: la mort dans les supplices?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Sur ces mots, il ordonna de mettre bien en évidence les instruments de torture afin de les amener par la crainte à manger des viandes impures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Les gardes alors présentèrent des roues, des instruments à disloquer les membres, des chevalets, des crocs, des catapultes, des chaudrons, des poêles, des gants, des mains de fer, des coins, des soufflets pour attiser le feu; le tyran prenant ces objets, disait:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Jeunes gens, tremblez! La justice que vous vénérez vous pardonnera une transgression imputable à la contrainte!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Mais il eurent beau entendre ces paroles persuasives, voir ces instruments terribles: non seulement ils n\'eurent point peur, mais encore leur philosophie les dressa contre le tyran et par leur sage raison ils abattirent sa tyrannie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Mais réfléchissions: supposons que quelques-uns d\'entre eux aient été timides et lâches; quel discours auraient-ils tenu? n\'est-ce point celui-ci:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Malheureux que nous sommes et par trop insensés! Un roi nous exhorte, nous parle pour notre bien: et nous refuserions de lui obéir!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Pourquoi mettre notre joie dans de vaines résolutions et oser commettre une désobéissance fatale?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Frères ne craindrons-nous pas les instruments de tortures? Ne réfléchirons-nous point aux menaces des tourments? N\'abandonnerions-nous point cette vanité et cette jactance qui nous mènent à la perte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Ayons pitié de notre jeunesse, ayons pitié de la vieillesse de notre mère!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Et mettons-nous bien dans l\'idée que si nous désobéissons, nous mourrons!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Quant à la justice divine, elle aussi nous pardonnera étant donné la contrainte car le roi nous épouvante!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 23, 'Pourquoi nous arracher nous-mêmes à la douceur de vivre? Pourquoi nous priver nous-mêmes des charmes de ce monde?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 24, 'Ne faisons pas violence à la fatalité, ne mettons pas notre point d\'honneur à nous faire torturer!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 25, 'La Loi elle-même ne nous punit point de mort s\'il y a contrainte, si nous sommes épouvantés par les instruments de torture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 26, 'D\'où nous vient un tel amour de la dispute? D\'où cet entêtement fatal tire-t-il pour nous son attrait alors que nous pouvons vivre tranquillement si nous obéissons au roi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 27, 'Mais les jeunes gens à l\'approche du supplice, ne dirent ni ne pensèrent rien de semblable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 28, 'Car ils étaient les contempteurs de la passion et les souverains maîtres de la douleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 29, 'Et ainsi, le tyran n\'eut pas plus tôt fini de les exhorter à manger des viandes impures que tous ensemble, d\'une seule voix et d\'une seule âme, ils lui dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Qu\'attends-tu, ô tyran? Nous sommes prêts à mourir plutôt que de transgresser les commandements de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'En effet nous devrions rougir devant nos aïeux si pour que nous obéissions à la Loi, Moïse ne nous servait pas aussi de conseiller!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Tyran, qui nous conseille mais pour que nous transgressions la Loi, n\'ait point pitié de nous, de nous-mêmes que tu hais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Car nous pensons que ta pitié qui ne nous promet le salut que si nous transgressions la Loi est plus cruelle que la mort elle-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Tu veux nous effrayer en nous menaçant de nous faire mourir dans les tourments: comme si Eléazar, il n\'y a qu\'un instant ne t\'avait rien appris!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Mais si les vieillards des Hébreux sont morts pour la pitié en endurant même les tortures, il est plus juste encore que nous mourions, nous les jeunes en méprisant les tourments par lesquels tu veux nous contraindre et dont a triomphé même ce vieillard notre maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Essaye donc, tyran! Mais si tu prends nos vies, si tu nous mets à mort pour la cause de la piété, ne crois pas que c\'est à nous que tu fais tort par ces tourments:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Car nous par ce supplice et par notre patience, nous remporterons le prix des vertueux combats et nous serons auprès de Dieu, de Dieu même pour qui nous souffrons,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Mais toi pour notre meurtre dont tu vas te souiller, tu auras à souffrir de la part de la justice divine par le feu, un tourment éternel proportionné à ton crime!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Telles furent leurs paroles: elles existèrent contre eux non seulement l\'indignation du tyran, du fait de leur désobéissance mais encore sa colère du fait de leur ingratitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Sur son ordre donc les bourreaux armés de fouets amenèrent l\'aîné des frères, déchirèrent sa tunique et lui lièrent les mains et les bras de part et d\'autre avec des courroies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Ils le frappèrent à coups de fouet; fatigués comme ils n\'obtenaient rien de lui, ils le jetèrent sur la roue:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Étendu autour de cette roue, le noble jeune homme fut écartelé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Tandis que tous ses membres se brisaient, il accusait le tyran en ces termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Impur tyran, ennemi de la Justice céleste, cœur cruel, ce n\'est pas un assassin que tu tortures de la sorte, ce n\'est pas un impie mais un défenseur de la Loi de Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Et comme les gardes lui disaient: Consens à manger pour te délivrer des tourments!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Il leur dit: Impurs valets! Votre roue n\'est pas assez forte pour étouffer ma raison! Coupez mes membres, brûlez mes chairs, tordez mes jointures:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'A travers tous les supplices, je vous ferai voir que seuls les enfants des Hébreux sont invincibles au service de la vertu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Comme il disait ces mots, ils placèrent au-dessous de lui un brasier et tout en attisant le feu ils tendaient la roue encore plus fort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'La roue était toute tachée de sang et les charbons entassés s\'éteignaient sous une pluie de sang et les chairs se répandaient tout autour des essieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Déjà se consumait la charpente des os: le magnanime jeune homme, vrai fils d\'Abraham ne poussa pas une plainte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Mais comme si dans le feu il se muait en un être incorruptible, il endura généreusement les tourments:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Imitez-moi mes frères, disait-il; ne désertez pas ma lutte, n\'abjurez point la fraternité qui unit nos courages, combattez le saint et noble combat de la piété!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'C\'est par la piété que la juste providence qui veille sur nous comme elle a veillé sur nos pères, deviendra propice à notre peuple et punira le tyran maudit!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'En prononçant ces mots, le saint jeune homme rendit l\'âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Tous furent dans l\'admiration de tant de constance: les gardes emmenèrent ensuite le second en âge des frères et gantés de moins de fer aux ongles aiguisés, ils le lièrent aux instruments de torture et à la catapulte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 27, 'Avant de le supplicier ils lui demandèrent s\'il voulait manger: mais il leur dit sa noble résolution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 28, 'Alors ces tigres, tirant avec les mains de fer depuis les muscles de la nuque, arrachèrent toute la chair jusqu\'au menton et toute la peau de la tête. Il supportait ce supplice sans être ébranlé, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 29, 'Qu\'elle est douce, sous toutes ses formes, la mort qu\'on souffre pour la cause de notre ancestrale piété! Au tyran il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 30, 'Ne crois-tu pas ô le plus cruel de tous les tyrans que tu souffres en ce moment des tortures pires que les miennes à voir ton orgueilleuse raison de tyran vaincue par notre endurance au service de la pitié?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 31, 'Car pour moi, les plaisirs que je goûte à cause de la vertu allègent ma douleur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 32, 'Mais toi tu souffres la torture dans les menaces même que profère ton impiété et tu n\'échapperas pas impur tyran aux justes châtiments de la colère divine!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Il supporta glorieusement la mort: on amena alors le troisième: un grand nombre de gens l\'exhortait de mille manières à goûter des viandes impures et à se sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Mais il cria: Ignorez-vous que c\'est le même père qui nous a engendré moi et ceux qui viennent de mourir, que c\'est la même mère qui nous a enfantés, que c\'est dans les mêmes doctrines que nous avons été nourris?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Je ne renie point la noble parenté de mes frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Irrité de l\'audace de ces viriles paroles ils lui désarticulèrent les mains et les pieds avec des instruments à disloquer, ils lui déboîtèrent les membres avec un levier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Irrité de l\'audace de ces viriles paroles ils lui désarticulèrent les mains et les pieds avec des instruments à disloquer, ils lui déboîtèrent les membres avec un levier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Ils lui brisèrent les doigts, les bras, les cuisses, les coudes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Comme par tous ces supplices ils n\'arrivaient pas à l\'étouffer, ils lui arrachèrent la peau et les extrémités des doigts, le scalpèrent à la manière des Scythes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Et aussitôt après l\'amenèrent sur la roue. Tandis qu\'autour de cette roue craquaient ses vertèbres, il voyait ses chairs en lambeaux et les gouttes des sangs qui coulaient de ses entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Au moment de mourir, il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Nous, ô très impur tyran, nous souffrons ainsi pour une discipline et pour une vertu divine;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Mais toi pour ton impiété et le meurtre dont tu te souilles, tu subiras des tourments sans fin!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Sa mort fut digne de celle de ses frères. Il amenèrent ensuite le quatrième et lui dirent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Ne te livre pas toi aussi à la même folie que tes frères, mais obéis au roi et sauve-toi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Mais il leur dit: Non! Vous n\'avez pas contre moi de feu assez brûlant pour faire de moi un lâche!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Par la mort bienheureuse de mes frères, par la perte éternelle du tyran, par la vie glorieuse des hommes pieux, non! Je ne renierai pas notre noble fraternité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Tyran, invente de nouveaux supplices afin que par ceux-ci même tu apprennes que je suis frère de ceux que tu viens de tourmenter!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'A ces mots, Antiochus le buveur de sang, l\'assassin tout pétri d\'impureté, ordonna qu\'on lui coupât la langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Mais il répliqua: Même si tu m\'enlèves l\'organe de la parole, Dieu entend même les muets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Vois, ma langue est sortie. Coupe, car tu ne mutileras pas pour cela notre raison!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'C\'est avec joie que pour Dieu nous nous laissons amputer des extrémités du corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Mais toi, bientôt Dieu te poursuivra car tu coupes une langue qui chantait les hymnes divines!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Celui-ci aussi mourut sous les coups et dans les tourments. Le cinquième alors se précipita, disant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Je ne vais pas, ô tyran me faire prier pour aller au supplice, pour la cause de la vertu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Mais c\'est de moi-même que je viens, pour que tu me mettes à mort, moi aussi, et que par un si grand nombre de crimes tu augmenteras le châtiment dont tu es redevable à la justice céleste!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Ennemi de la vertu et ennemi des hommes, qu\'avons-nous fait pour que tu nous maltraites ainsi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Ou crois-tu qu\'il soit mal de servir avec piété le Créateur du monde et de vivre suivant sa vertueuse Loi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Mais cela mérite des honneurs et non des tortures:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Comme il parlait ainsi, les gardes le lièrent et l\'entraînèrent vers la catapulte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Comme il parlait ainsi, les gardes le lièrent et l\'entraînèrent vers la catapulte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Comme il parlait ainsi, les gardes le lièrent et l\'entraînèrent vers la catapulte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Là ils le lièrent aux genoux, lui mirent ceux-ci dans des entraves de fer puis lui courbèrent les reins sur le coin rotatif: tout entier étendu autour de ce coin sur la roue, brisé et renversé en arrière comme un scorpion, tous ses membres étaient arrachés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'En cette situation, le souffle haletant et le corps étouffant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Belles, disait-il, mais contre ton gré tyran sont les faveurs que tu nous accordes: belles, puisque tu nous offres l\'occasion de montrer notre constance au service de la Loi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Celui-ci à son tour mourut; on amena alors le sixième, un tout jeune homme. Le tyran lui demanda s\'il voulait manger et être relâché. Mais il dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Je suis par l\'âge plus jeune que mes frères mais par la raison je suis du même âge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'En effet, c\'est dans le même idéal que nous sommes nés que nous avons été nourris: c\'est pour le même idéal aussi que nous devons mourir, tous de même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Aussi si c\'est ton bon plaisir de torturer ceux qui ne mangent pas de viandes souillées, torture!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Quand il eut dit ces mots ils l\'amenèrent vers la roue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Ils l\'étendirent sur elle soigneusement et tout en lui disloquant les vertèbres, ils le brûlèrent à petit feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Puis, il firent rougir au feu des broches aiguisées les lui enfoncèrent dans le dos, lui traversèrent les flancs et lui brûlèrent les entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Pendant ce supplice il disait: Ô saint combat auquel nous avons été appelés, nous frères si nombreux pour défendre la pitié: lutte difficile où nous n\'avons pas été vaincus!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Car elle est invincible, ô tyran, la science pieuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Sous les armes du bien je mourrai moi aussi, uni à mes frères');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Et je lancerai moi aussi un puissant vengeur contre toi, inventeur de supplices, ennemi de ceux qui pratiquent la vraie piété!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 24, 'Nous sommes six jeunes gens et nous avons renversé la tyrannie!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 25, 'Car le fait que tu n\'as pas pu faire fléchir notre raison ni nous forcer à manger des viandes impures, n\'est-ce pas le renversement de ta tyrannie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 26, 'Ton feu pour nous est froid, indolores les catapultes, impuissante ta violence!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 27, 'Car des gardes nous protègent non point ceux d\'un tyran mais ceux de la Loi divine. C\'est pourquoi notre raison demeure invincible!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Celui-ci à son tour mourut de la mort des bienheureux ayant été précipité dans une chaudière; le septième arriva, le plus jeune de tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Le tyran eut pitié de lui, bien que ses frères il les eut terriblement maltraités, et le voyant déjà enveloppé de liens, il le fit approcher et chercha à le persuader, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'De la folie de tes frères tu vois l\'issue: pour leur désobéissance ils sont morts dans les tourments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Quant à toi, si tu ne m\'obéissais pas, pauvre malheureux, dans les supplices toi aussi, tu mourrais d\'une mort précoce;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Mais si tu obéis tu seras mon ami et tu dirigeras les affaires de mon royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Tout en lui donnait ces conseils il fit venir la mère de l\'enfant dans l\'idée que déjà privée de tant de fils elle aurait pitié d\'elle-même et pousserait celui qui restait à obéir et à se sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Mais lui, quand en hébreu sa mère l\'eût exhorté comme nous le dirons un peu plus loin:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Déliez-moi dit-il; je veux parler au roi et à tous ses amis qui l\'accompagnent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Tout réjouis de cet ordre que leur donnait l\'enfant, ils s\'empressèrent de le délier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Il s\'approcha alors de la chaudière en courant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Tyran sacrilège, dit-il et de tous les méchants, le plus impie, tu n\'as pas en honte après avoir reçu de Dieu les richesses et la royauté, de mettre à mort ses serviteurs et de torturer ceux qui s\'exercent à la piété:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'A cause de cela la divine justice te réserve pour un feu plus vivace, pour un feu éternel et pour des tourments qui ne te lâcheront pas pendant toute l\'éternité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Tu n\'as pas eu honte alors que tu es un homme, ô la pire des bêtes sauvages de couper la langue à des hommes sensibles à la souffrance comme les autres, nés des mêmes éléments et de les accabler de tourments de cette manière-là:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Mais ceux-ci par leur noble trépas ont rempli envers Dieu le devoir de la piété; quant à moi tu te lamenteras amèrement pour avoir mis à mort sans raison les champions de la vertu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Aussi, continua-t-il sur le point de mourir lui aussi');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Je ne déserte point le témoignage qu\'on rendu mes frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'J\'invoque le Dieu de mes pères pour qu\'il soit propice à ma race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 18, 'Mais toi, il te châtiera et dans cette vie présente et après ta mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 19, 'Après cette imprécation il se jeta dans la chaudière et ainsi il rendit l\'âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Ainsi puisque les sept frères ont su mépriser les souffrances jusqu\'à la mort, il faut entièrement convenir que la raison pieuse est la souveraine des passions:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'De la même manière si en mangeant des viandes impures, ils s\'étaient rendus esclaves des passions, nous dirions qu\'ils ont été vaincus par elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Mais ce n\'est pas le cas ici! Au contraire par la raison si louable auprès de Dieu, ils l\'ont emporté sur les passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Et l\'on ne peut plus dédaigner la suprématie du jugement car ils ont maîtrisé et la passion et la douleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Comment donc peut-on ne pas reconnaître le pouvoir de la réflexion sur la passion chez ces jeunes gens, qui, d\'une part n\'ont pas reculé devant les souffrances causées par le feu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'En effet de même que les tours dressées en avant d\'un port réduisent les vagues menaçantes et assurent à ceux qui entrent, un refuge tranquille,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'De même chez ces adolescents la réflexion semblable à sept tours a fortifié le port de la piété et vaincus l\'intempérance des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Comme en un chœur saint et pieux ils s\'encourageaient les uns les autres:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Frères, disaient-ils, puissions-nous fraternellement mourir pour la Loi! Imitons les trois, les jeunes gens qui en Assyrie ont méprisé une fournaise ni plus ni moins redoutable!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Ne soyons pas des lâches quand il s\'agit de faire la preuve de notre piété!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Courage, frère! disait l\'un. Et un autre: Supporte noblement!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Un autre encore: Souvenez-vous de quelle race vous êtes ou de quel père la main, à cause de la piété, faillit égorger Isaac, sans que celui-ci résistât!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'L\'air radieux et plein de courage, tous ensemble et chacun se regardant l\'un l\'autre: Consacrons-nous à Dieu, disaient-ils, de tout notre cœur à Dieu qui nous a donné nos âmes et employons nos corps à la défense de la Loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Ne craignons point celui qui ne donne la mort qu\'en apparence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Car grand est le combat de l\'âme, grand aussi le danger: il consiste pour ceux qui transgressent ce commandement de Dieu en un éternel tourment!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Armons-nous donc de cette maîtrise que nous donne sur les passions la raison divine!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Après que nous aurons ainsi souffert nous serons reçus par Abraham, Isaac, Jacob et tous les pères nous loueront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Chaque fois qu\'un des frères était emmené ceux qui restaient disaient: Ne nous déshonore point frère et ne fais point mentir ceux qui viennent de mourir!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Vous connaissez les filtres de l\'amour fraternel; c\'est la divine et toute sage providence qui par le moyen du père les partage entre les enfants et les y enracine par le moyen du sein maternel:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Là chaque frère habite durant un temps égal, y est façonné dans la même durée, y croît du même sang, y mûrit au moyen de la même âme:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Puis après le même terme il est enfanté et il boit le lait aux mêmes sources: c\'est ainsi que se nouent les liens de l\'amour fraternel dans l\'âme des nourrissons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Puis ils grandissent chaque jour nourris à la même table, soumis aux mêmes habitudes quotidiennes, recevant la même éducation et s\'exerçant dans la Loi de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Or si l\'amour fraternel est naturellement si tendre, les sept frères étaient unis les uns aux autres encore plus profondément.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'En effet instruit dans la même Loi, s\'exerçant aux mêmes vertus, élevés ensemble dans une vie juste, ils s\'en aimaient encore davantage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Leur zèle commun pour la vertu fortifiait leur mutuelle concorde;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Car la raison unie à la piété rendait plus ardent encore leur amour fraternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Mais cependant, bien que la nature, la vie commune, la pratique de la vertu eussent renforcé les filtres de leur amour fraternel, ceux qui restaient supportaient à cause de la piété de voir leurs frères qu\'on suppliciait en proie aux tourments jusqu\'à la mort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Bien plus, ils les excitaient à subir la torture et ainsi non seulement ils méprisaient la douleur mais encore ils commandaient aux passions de l\'amour fraternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Ô raisons plus royales que les rois, plus libres que les hommes libres!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Ô saint et harmonieux accord des sept frères pour la piété!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Nul des sept jeunes gens ne trembla, nul n\'hésita devant le trépas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Mais tous ils se hâtèrent vers les tourments et vers la mort comme s\'ils courraient vers le chemin de l\'immortalité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'En effet, de même que les mains et les pieds se meuvent d\'accord suivant les injonctions de l\'âme, de même ces saints jeunes gens, comme si les soulevait l\'âme immortelle de la piété ont été unanime pour mourir au service de la piété!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ô semaine sacrée des frères si harmonieusement unis! Comme les sept jours de la création du monde autour de la semaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Ainsi, autour de la piété tournaient comme en un chœur les jeunes gens: pour eux était abolie la crainte des tourments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Nous tremblons nous maintenant en écoutant le récit de leurs tribulations: mais eux, non seulement ils voyaient, non seulement ils entendaient qu\'on menaçait de les châtier sur-le-champ, mais encore, ils souffraient et ce qu\'ils enduraient c\'était le supplice du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Est-il rien de plus douloureux? La puissance du feu, vive et prompte, a vite fait de dissoudre les corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Et cependant, ne considérez pas comme une chose étonnante que chez ces hommes, la raison ait eu le dessus au milieu même des tourments puisque l\'intelligence d\'une femme, elle aussi a méprisé les souffrances les plus variées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'La mère des sept jeunes gens en effet, a supporté les tortures infligées à chacun de ses enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Voyez tous les replis de la tendresse d\'une mère qui ramène tout à l\'amour du fruit de ses entrailles:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Les animaux dépourvus de raison eux-mêmes éprouvent le même amour et la même tendresse que les humains pour les êtres qu\'ils mettent au monde!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Prenons l\'exemple des oiseaux, les uns, ceux qui sont apprivoisés, nichent sous le toit des maisons pour défendre leurs petits;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Les autres au sommet des montagnes, dans les parois abruptes des précipices, dans les tours et sur les cimes des arbres, couvent leurs œufs, les font éclore et là ils tiennent en respect l\'assaillant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Si pourtant ils ne réussissent point à l\'écarter, ils volent en tournant autour du nid avec une douloureuse tendresse, dans leur langage ils appellent leurs petits et ils les secourent par tous les moyens en leur pouvoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Mais pourquoi donner plus de preuves de l\'amour maternel parmi les animaux dépourvus de raison,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Puisque les abeilles aussi à l\'époque où elles font leur miel, repoussent l\'assaillant frappent de leur dard comme d\'un glaive aux qui s\'approchent de leur progéniture et le défendent jusqu\'à la mort?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Mais la mère des jeunes gens dont l\'âme était semblable à celle d\'Abraham, l\'amour de ses enfants ne l\'a point ébranlée!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Ô raison, tyrannique maîtresse des passions de l\'amour maternel! Ô piété plus chère encore au cœur de cette mère que ses enfants!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Une mère doit choisir entre la piété et le salut de ses sept fils, salut de peu de durée sur la promesse du tyran:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'C\'est la piété qu\'elle préfère, elle qui sauve pour la vie éternelle selon la promesse de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Oh! En quels termes pourrais-je décrire les passions de l\'amour des parents pour leurs enfants? Nous imprimons merveilleusement dans l\'enfant comme dans une figurine la ressemblance de notre âme et de notre corps: surtout les mères parce qu\'elles sont naturellement en union plus intime que les père avec les êtres qu\'elles ont enfantés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'En effet, les mères ont l\'âme faible et plus elles ont d\'enfants, plus est grande l\'affection qu\'elles leur portent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Mais de toutes les mères, la mère des sept était la plus aimante, elles dont sept enfantements avaient enraciné la tendresse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Et que les douleurs causées par chacune de ces nombreuses naissances avaient comme contrainte à les chérir:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Pourtant pour la crainte de Dieu le salut de ses enfants, salut qui n\'eût été que de peu de durée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Ce n\'est pas tout: la vertu de ses fils, leur obéissance à la Loi augmentaient encore sa tendresse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Car ils étaient justes, tempérants, courageux, magnanimes, unis pour l\'amour fraternel et aimant leur mère au point de lui obéir en gardant les préceptes de la Loi, même jusqu\'à la mort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Mais cependant, si nombreux que fussent les liens de l\'amour maternel qui portaient cette mère à la tendresse, pour aucun d\'entre eux les tourments les plus divers ne purent ébranler sa raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Au contraire, la mère exhortait ses enfants, tous ensemble et un par un à mourir pour la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Ô sainte nature! Ô filtres de l\'amour des parents! ô voix du sang si pleine de tendresse! Ô passions indomptées des mères!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Cette mère voit ses fils un par un torturés, brûlés: mais elle reste inébranlable à cause de la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Elle voit leurs chairs se consumer dans le feu, les doigts de leurs pieds et de leurs mains palpiter sur le sol, les chairs de leurs têtes arrachées jusqu\'au menton traîner à terre semblables à des masques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Ô mère éprouvée aujourd\'hui par des souffrances plus cruelles que les douleurs mêmes de leur enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, '0 femme, la seule qui ait mis au monde la piété parfaite!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'L\'aîné ne t\'a point ébranlée, quand il rendait l\'âme, ni le second, quand dans les tourments il tournait vers toi un triste regard ni la troisième quand il expira:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Mai toi, tu contemplais les yeux de chacun, regardant, hagard, du milieu des tortures leur propre supplice, tu voyais leurs narines présentant les signes de la mort: et tu n\'as pas pleuré!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Sous tes yeux on brûlait la chair de tes enfants et encore la chair de tes enfants, on coupait des mains et des mains, on abattait tête sur tête, on faisait tomber cadavre sur cadavre; la foule sous tes yeux, remplissait le lieu où tes fils enduraient les tourments: et tu n\'as pas eu une larme!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Ni le chant des sirènes, ni la voix des cygnes n\'ont autant d\'attrait pour l\'oreille avide de ceux qui les écoutent que la voix de ces enfants appelant une mère au milieu du supplice:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 22, 'Combien cruels, combien nombreux les tourments de la mère quand ses fils étaient tourmentés par la roue et par le feu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 23, 'Mais la raison pieuse au milieu même des passions excita virilement son cœur à mépriser un amour maternel sans durée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 24, 'Bien qu\'elle fût témoin de la mort de ses sept fils et de la variété raffinée de leurs supplices, cette noble mère (...) à cause de sa foi en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 25, 'Elle était pour ainsi dire à un tribunal: elle voyait en son âme des conseillers terribles, la nature, la voix du sang, l\'amour maternel, le supplice de ses fils;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 26, 'Elle tenait dans ses mains, elle la mère, deux cailloux de vote, l\'un qui donnerait la mort à ses enfants, l\'autre qui les sauverait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 27, 'Elle ne voulut point d\'un salut qui n\'aurait sauvé ses sept fils que pour peu de temps,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 28, 'Mais elle se souvient de la constance du pieux Abraham dont elle était la fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 29, 'Ô mère de la nation! Vengeresse de la Loi! Protectrice de la piété! Victorieuse de la lutte qui se livra dans ton cœur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 30, 'Ô toi, plus noble qu\'un mâle par ta force, plus virile qu\'un homme par ton endurance!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 31, 'Comme dans le déluge universel, l\'arche de Noé qui portait en elle le monde, surmonta les assauts des vagues,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 32, 'Ainsi toi, la gardienne de la Loi, de toutes parts assaillie au milieu du déluge des passions, accablée par les tortures de tes fils comme par des vents déchaînés, tu as noblement supporté les tempêtes pour la cause de la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Concluons: si une femme et d\'un grand âge et mère de sept enfants a enduré la vue des tourments infligés à ses fils jusqu\'à la mort, il faut bien convenir que la raison pieuse est la souveraine des passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'J\'ai bel et bien montré non seulement que les hommes avaient maîtrisé les passions mais encore qu\'une femme avait méprisé les tourments les plus terribles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Moins cruels étaient les lions autour de Daniel, moins violent le feu de la chaudière qui brûlait Mishaël que l\'instinct de l\'amour maternel dont cette femme était enflammée à la vue de ses propres fils, de ses sept fils en proie aux supplices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Mais chez cette mère la raison unie à la piété éteignit les passions si nombreuses et si vives qu\'elles fussent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Considérez en effet que si cette femme avait eu une âme sans courage, bien qu\'elle fût une mère, elle se serait lamentée sur eux et peut-être aurait-elle tenu les propos que voici:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Ô infortunée que je suis! Ô tant de fois accablée par le malheur! J\'avais mis au monde sept fils et je ne suis plus la mère d\'aucun!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Ô vaines ces sept grossesses! Inutiles ces sept gestations de dix mois! Stériles les premiers soins que je leur ai donnés! Funestes mes allaitements!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'C\'est en vain que pour vous, ô mes enfants, j\'ai enduré tant de fois les douleurs de l\'enfantement et les soucis de l\'éducation plus pénibles encore!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Ô mes fils, dont les uns n\'étaient pas mariés, dont les autres n\'ont connu que d\'inutiles épousailles Je ne verrai point vos enfants, je n\'aurai pas la joie d\'être appelée grand-mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Hélas! Moi qui fut la mère de nombreux et beaux enfants, et suis maintenant une pauvre femme, veuve et abandonnée!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Et quand je mourrai, je n\'aurai pas un de mes fils pour m\'ensevelir!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Mais cette lamentation, la sainte et pieuse mère ne la proféra sur aucun de ses fils. Elle n\'en détourna aucun de la résolution de mourir, elle ne s\'attrista pas au moment de leur mort:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Mais au contraire comme si son intelligence eut été d\'acier et comme si elle enfantait à nouveau, pour l\'immortalité, la totalité de ses fils, elle les exhortait, elle les suppliait de mourir pour la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Ô mère, soldat de Dieu pour la cause de la piété! Toi, un vieillard, toi une femme! Tu as vaincu par ta constance le tyran lui-même, et par tes actes et par tes paroles tu as été trouvée plus forte qu\'un homme!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Quand tu fus enlevée avec tes enfants, debout tu regardais Eléazar pendant son supplice et en hébreu tu disais à tes enfants:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Mes fils, noble est le combat, appelés à ce combat pour porter témoignage pour notre nation, luttez avec ardeur pour la Loi de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Il serait honteux que ce vieillard eût enduré tant de douleurs pour la piété et que vous les jeunes vous fussiez effrayés devant les supplices!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Souvenez-vous que c\'est grâce à Dieu que vous avez une part en ce monde et que vous jouissez de la vie!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'C\'est pourquoi aussi vous devez supporter toutes les souffrances pour Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'C\'est pour lui aussi que votre père Abraham s\'empressait d\'égorger Isaac son fils, père d\'une nation et que celui-ci voyant la main de son père s\'abattre sur lui, armée du glaive, ne recula point de frayeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Et Daniel le juste fut jeté aux lions, et Ananias, Azarias et Mishaël furent précipités dans la fournaise ardente: pour Dieu ils supportaient tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 22, 'Vous aussi par conséquent, qui avez la même foi en Dieu, ne vous démontez pas:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 23, 'Car il serait absurde connaissant la piété de ne pas tenir tête à la souffrance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 24, 'C\'est en ces termes que la mère des sept exhortait ses fils et les persuadait de mourir plutôt que de transgresser le précepte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 25, 'Mais en outre, ils étaient convaincus aussi de cette vérité, que, quand on meurt pour Dieu, on vit désormais en Dieu, comme vivent Abraham, Isaac et Jacob et tous les patriarches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Quelques-uns des gardes ont rapporté comment sur le point d\'être saisie pour être mise à mort, elle se jeta dans le bûcher pour qu\'on ne toucha point son corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Ô mère, toi qui avec tes sept fils as brisé la violence du tyran, anéanti ses projets mauvais, montré la noblesse de la foi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Noblement appuyée sur tes fils comme un toit sur ses colonnes, tu as supporté sans fléchir l\'ébranlement des supplices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Courage donc, ô mère à l\'âme sainte, toi qui en Dieu possède un ferme espoir, soutien de ta patience!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'La lune dans le ciel, entourée d\'étoiles n\'a pas autant de majesté que toi: versant la lumière sur tes sept fils, brillants comme des astres, tu reçois de Dieu les honneurs dus à la piété, tu es changée en constellation, avec eux dans le ciel!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Car c\'est d\'Abraham leur père que sont nés tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'S\'il vous était permis de peindre comme sur un tableau l\'histoire de ta piété qui ne frémirait de voir une mère de sept enfants endurant jusqu\'à la mort les supplices les plus divers pour la cause de la piété?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Oui, il serait bien aussi d\'inscrire sur la tombe elle-même les paroles suivantes comme mémorial pour ceux de notre peuple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Ici un vieillard honoré du sacerdoce et une femme âgée et sept enfants sont ensevelis, victimes de la violence d\'un tyran résolu à détruire l\'état des Hébreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Eux aussi, ils ont vengé les droits de votre peuple en regardant vers Dieu et en endurant les tourments jusqu\'à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Car vraiment ce fut un combat divin que celui qu\'ils ont livré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'La vertu présidait la lutte: l\'épreuve voulait de l\'endurance: la victoire, c\'était l\'incorruptibilité dans une longue vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Eléazar ouvrit le combat; puis la mère des sept fils entra dans la lutte; les autres combattants, c\'étaient les frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'L\'adversaire c\'était le tyran; les spectateurs, le monde et l\'humanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'C\'est à la piété que revint la victoire: elle donna la couronne à ses athlètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Qui n\'admirerait ces athlètes de la Loi divine? qui ne serait saisi d\'étonnement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Le tyran lui-même et tout son conseil étaient émerveillés de leur patience;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Celle-ci leur a valu de se tenir maintenant près du divin trône et de vivre les jours de la bienheureuse éternité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Moïse dit, en effet: Et tous les saints sont sous tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Ceux-ci donc, s\'étant sanctifiés pour la cause de Dieu ont reçu non seulement cette récompense céleste mais encore celle-ci: c\'est la grâce à eux que les ennemis n\'ont point asservi notre peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Que le tyran a été châtié, que le sol de la patrie a été purifié, leur vie ayant servi pour ainsi dire de rançon pour le péché de notre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Par le sang de ces hommes pieux, par l\'expiation de leur mort, la Providence divine a sauvé Israël, naguère accablée de maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'En effet, le tyran Antiochus avait remarqué le courage de leur vertu et leur patience en exemple à ses soldats:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Ce qui leur inspira un tel dévouement et un tel courage soit dans la guerre d\'infanterie soit dans la guerre de siège, qu\'il fut vainqueur de tous ses ennemis et pilla leurs biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Ô enfants d\'Israël, issus de la semence d\'Abraham, obéissez à cette Loi, observez en tout la piété,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Sachant que la raison pieuse est la dominatrice des passions et aussi des souffrances que celles-ci aient leur cause en nous ou hors de nous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'C\'est pourquoi ayant offert leur corps aux souffrances à cause de la piété, non seulement ils se sont attirés l\'admiration des hommes mais encore ils ont été jugés dignes du divin partage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Et c\'est grâce à eux que le peuple a recouvré la paix: ils ont dans le pays restauré l\'observation de la Loi et réduit les ennemis à lever le siège.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Mais le tyran Antiochus a été puni dès cette terre et après sa mort, il continue à être châtié. En effet, comme il put absolument pas contraindre les gens de Jérusalem à adopter les mœurs de l\'étranger et à échanger les coutumes des pères pour un autre genre de vie, il dut alors s\'éloigner de Jérusalem et il marcha contre les Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'La mère des sept fils, elle la femme juste, disait encore ceci à ses enfants:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'J\'ai été une vierge innocente et je n\'ai point franchi le seuil de la maison paternelle, mais je gardais mon corps, édifié par Dieu au moyen de la côte du premier homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Nul corrupteur, le démon du désert, ne m\'a corrompue dans la plaine, nul souilleur, le serpent du mensonge, n\'a souillé l\'innocence de ma virginité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Puis, quand je fus à l\'âge de femme je demeurai avec mon mari. Quand ceux- ci devinrent grands, leur père mourut: heureux fut-il, car ayant vécu les jours où étaient présents les enfants, il n\'a point connu l\'heure où s\'en sont allés ces enfants!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'C\'est lui qui nous apprenait quand il était encore des nôtres, la Loi et les Prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Il nous lisait l\'histoire d\'Abel tué par Caïn, celle d\'Isaac offert en holocauste, celle de Joseph en prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Il nous parlait du zélé Phinées, il nous apprenait l\'histoire des jeunes gens dans la fournaise, Ananias, Azarias, Mishaël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Il glorifiait aussi Daniel dans la fosse aux lions et il le déclarait bienheureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Et il vous rappelait l\'Écriture d\'Isaïe, où il est dit: Même si tu passe à travers le feu, la flamme ne te brûlera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Il nous chantait les hymnes de David le psalmiste, qui dit: Nombreuses sont les tribulations des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Il nous citait les Proverbes de Salomon où il est dit: Le Seigneur est un arbre de vie pour ceux qui font sa volonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Il vous faisait connaître Ézéchiel, qui dit: Est-ce que revivront ces os desséchés?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Car il ne laissait point dans l\'oubli le cantique que Moïse vous a appris et qui enseigne:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'C\'est moi qui ferai mourir et qui ferai vivre. Ceci est votre vie la longueur de vos jours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Oh! Combien cruel ce jour, et pourtant non cruel, où le cruel tyran des Grecs fit brûler dans des chaudières bouillantes rougies au feu, puis dans sa fureur inhumaine, conduire vers la catapulte et de nouveau vers ses tourments de choix, les sept enfants de la sœur d\'Abraham,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Leur creva les prunelles des yeux, leur coupa la langue et les fit mourir dans les supplices les plus variés!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Pour ces crimes la justice divine a poursuivi et elle poursuivra encore ce maudit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Mais les fils d\'Abraham avec leur mère victorieuse sont maintenant rassemblés au lieu où sont les Pères, eux qui ont reçu des âmes pures et immortelles de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 24, 'A qui soit la gloire dans les siècles des siècles! Amen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Heureux l’homme qui n’est point allé au conseil des impies, qui ne s’est pas arrêté dans la voie des pécheurs et ne s’est point assis dans la chaire de pestilence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Mais dont la volonté est conforme à la loi du Seigneur, et qui, nuit et jour, méditera sur cette loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Il sera comme l’arbre planté au bord des eaux, et qui donnera son fruit en sa saison; ses feuilles ne tomberont jamais, et en toutes ses œuvres il prospérera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Ils ne sont pas ainsi les impies, ils ne sont pas ainsi; mais ils sont comme la paille que le vent balaie sur la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'C’est pourquoi les impies ne ressusciteront pas dans le jugement, ni les pécheurs dans l’assemblée des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Car le Seigneur connaît la voie des justes; et la voie des pécheurs périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'D’où vient que les nations ont frémi et que les peuples ont médité de vains complots?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Les rois de la terre se sont levés, et les chefs se sont réunis ensemble contre le Seigneur et contre son Christ, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Rompons leurs liens, rejetons loin de nous leur joug.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Celui qui habite aux cieux s’en rira, et le Seigneur se moquera d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Alors il leur parlera dans sa colère; et il les troublera dans sa fureur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Mais moi, il m’a institué roi de Sion, sa sainte montagne, et j’annonce les préceptes du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Le Seigneur m’a dit: Tu es mon fils; aujourd’hui je t’ai engendré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Demande-moi, et je te donnerai les nations pour héritage, et pour ta possession les limites de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Tu les gouverneras avec une verge de fer; tu les briseras comme un vaisseau d’argile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Et maintenant, rois, comprenez; instruisez-vous, juges de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Servez le Seigneur avec crainte, et réjouissez-vous en lui avec tremblement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Embrassez sa discipline, de peur que le Seigneur ne s’irrite, et que vous ne périssiez hors de la voie juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Lorsque soudain s’enflammera sa colère, heureux sont ceux qui ont confiance en lui!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Seigneur, pourquoi ceux qui m’affligent se sont-ils multipliés? Combien se soulèvent contre moi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Combien disent à mon âme qu’il n’est point de salut pour elle!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Mais vous, Seigneur, vous êtes mon appui et ma gloire; c’est vous qui relevez ma tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'De ma voix, j’ai crié au Seigneur, et il m’a entendu du haut de sa montagne sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Et je me suis endormi d’un profond sommeil; je me suis réveillé, car le Seigneur me défendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Je ne craindrai pas la foule du peuple qui m’assiège de tous côtés; levez-vous, Seigneur; sauvez-moi, mon Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Car vous avez frappé tous ceux qui m’ont poursuivi sans cause, et vous avez broyé les dents des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Le salut vient du Seigneur, et votre bénédiction est sur votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Lorsque je l’eus invoqué, le Dieu de ma justice, il m’exauça; vous m’avez dilaté en mon affliction. Ayez pitié de moi, et exaucez ma prière!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Fils des hommes, jusques à quand aurez-vous le cœur appesanti? D’où vient que vous aimez la vanité, et cherchez le mensonge?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Sachez donc que le Seigneur a rendu son Saint admirable; le Seigneur m’exaucera, lorsque je crierai vers lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Indignez-vous, mais ne péchez pas; soyez touchés de componction de ce que vous méditez sur votre couche au fond de vos cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Offrez le sacrifice de justice, et espérez au Seigneur; plusieurs disent: Qui nous fera voir les biens?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Seigneur, la lumière de votre face est empreinte sur nous; vous avez mis la joie dans mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Mes ennemis se sont multipliés dans l’abondance de leur pain, de leur vin, de leur huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Pour moi, je m’endormirai et me reposerai dans la paix;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Parce que vous, Seigneur, par une grâce singulière, vous m’avez établi dans l’espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Seigneur, recueillez mes paroles en votre oreille, soyez attentif à mes cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Écoutez la voix de ma prière, ô mon Roi, ô mon Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Car je vous invoquerai, Seigneur; dès l’aurore vous entendrez ma voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Dès l’aurore je me tiendrai devant vous, et je vous verrai; car vous n’êtes point un Dieu qui veuille l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Le méchant n’habitera point auprès de vous, les pécheurs ne resteront point sous vos yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Seigneur, vous haïssez tous ceux qui font le mal, vous perdez tous ceux qui disent le mensonge. Le Seigneur aura en abomination l’homme de sang et le trompeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Pour moi, dans l’abondance de votre miséricorde, j’entrerai en votre maison; j’adorerai en votre sanctuaire, pénétré de votre crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Seigneur, guidez-moi en votre justice, à cause de mes ennemis; rendez droite ma voie en votre présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Car il n’est point de vérité en leur bouche; leur cœur n’est que vanité. Leur gosier est un sépulcre ouvert, et avec leurs langues ils ont trompé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Jugez-les, ô mon Dieu! Que leurs desseins soient renversés; à cause de la multitude de leurs impiétés, repoussez-les, car ils vous ont exaspéré, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Mais ils se réjouiront en vous, tous ceux qui mettent en vous leur espérance; ils tressailliront à jamais d’allégresse, et vous habiterez en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Car vous bénirez le juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 1, 'Seigneur, ne me reprenez pas en votre fureur, ne me châtiez pas en votre colère. Ayez pitié de moi, Seigneur, car je suis infirme; guérissez-moi, Seigneur, car mes os sont bouleversés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 2, 'Et mon âme a été grandement troublée, et vous, jusques à quand, Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 3, 'Revenez, Seigneur, délivrez mon âme; sauvez-moi par votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 4, 'Car il n’est personne en la mort qui se souvienne de vous; et aux enfers, qui vous rendra gloire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 5, 'Je me suis fatigué à gémir; je laverai chaque nuit ma couche; j’arroserai mon lit de mes larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 6, 'Mon œil a été troublé par la fureur; je suis devenu vieux au milieu de tous mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 7, 'Éloignez-vous de moi, vous tous ouvriers d’iniquité; car le Seigneur a entendu la voix de mes larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 8, 'Le Seigneur a écouté mon oraison; le Seigneur a exaucé ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 9, 'Que tous mes ennemis rougissent de honte et soient troublés au fond de l’âme; qu’ils fuient soudain et soient grandement humiliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 1, 'Seigneur mon Dieu, j’ai espéré en vous; sauvez-moi de tous ceux qui me persécutent, et délivrez-moi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 2, 'De peur que, comme un lion, ils ne ravissent ma vie, s’il n’y a personne pour me sauver et me racheter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 3, 'Seigneur mon Dieu, si j’ai fait quelque faute, s’il y a quelque iniquité en mes mains,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 4, 'Si j’ai rendu le mal pour le mal, que je tombe dénué de tout, sous les coups de mes ennemis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 5, 'Que l’ennemi poursuive mon âme; qu’il la prenne, qu’à terre il foule aux pieds ma vie; qu’il enfouisse ma gloire sous la poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 6, 'Levez-vous, Seigneur, en votre colère; faites éclater votre grandeur jusqu’aux extrêmes frontières de mes ennemis. Réveillez-vous, Seigneur mon Dieu, selon le commandement que vous avez intimé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 7, 'Et la synagogue des peuples vous entourera. Et pour elle, remontez au plus haut des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 8, 'Le Seigneur juge les peuples. Jugez-moi, Seigneur, selon ma justice et mon innocence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 9, 'Que la méchanceté des pécheurs ait un terme, et vous dirigerez le juste, ô Dieu, qui sondez les cœurs et les reins!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 10, 'Il est juste que je sois aidé du Dieu qui sauve les hommes droits en leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 11, 'Dieu est un juge équitable, fort et patient; est-ce que chaque jour il déchaîne sa colère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 12, 'Si vous ne vous convertissez, il brandira son glaive; il a tendu son arc, et il le tient préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 13, 'Il y a mis des instruments de mort; il a préparé des flèches enflammées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 14, 'Voilà que le méchant a enfanté l’iniquité; il a conçu la douleur, il a donné le jour au péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 15, 'Il a ouvert une fosse, il l’a creusée; et il tombera dans la fosse qu’il a faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 16, 'Je rendrai gloire au Seigneur selon sa justice; je chanterai le nom du Seigneur Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 1, 'Seigneur, ô notre Dieu, que votre nom est admirable sur toute la terre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 2, 'Vous avez mis la parfaite louange dans la bouche des enfants à la mamelle, à cause de vos ennemis, pour confondre le haineux et le vindicatif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 3, 'Quand je vois les cieux, œuvres de vos doigts, la lune et les étoiles que vous avez créées, je dis:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 4, 'Qu’est donc l’homme, pour que vous vous souveniez de lui? ou le fils de l’homme, pour que vous le visitiez?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 5, 'Vous l’avez fait un peu moindre que les anges; vous l’avez couronné d’honneur et de gloire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 6, 'Et vous l’avez mis à la tête des œuvres de vos mains!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 7, 'Vous avez placé toutes choses sous ses pieds: les brebis et tous les bœufs, et même les bêtes des champs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 8, 'Les oiseaux du ciel, et les poissons de la mer et ceux qui parcourent les sentiers des mers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 9, 'O Seigneur, notre Seigneur, que votre nom est admirable sur toute la terre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 1, 'Je vous rendrai gloire, ô mon Dieu, de tout mon cœur; je raconterai vos merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 2, 'Je me réjouirai et je tressaillirai en vous; je chanterai votre nom, Dieu Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 3, 'Parce que vous avez réduit mes ennemis à tourner le dos; ils seront abattus et périront devant votre face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 4, 'Car vous avez jugé ma cause sur votre trône, ô vous qui jugez selon la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 5, 'Vous avez repris les nations, et l’impie a péri; vous avez effacé leur nom à jamais pour tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 6, 'Les glaives de l’ennemi ont été brisés pour toujours; et vous avez détruit leur cité. Leur souvenir s’est éteint avec fracas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 7, 'Mais le Seigneur subsiste éternellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 8, 'Et il jugera lui-même toute la terre selon l’équité; il jugera les peuples selon la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 9, 'Et le Seigneur s’est fait le refuge du pauvre, son défenseur en son affliction, au temps opportun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 10, 'Que ceux qui connaissent votre nom espèrent en vous, ô Seigneur; car vous n’avez point délaissé ceux qui vous cherchent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 11, 'Chantez un hymne au Seigneur, qui demeure en Sion; faites connaître aux Gentils les soins qui l’occupent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 12, 'Car il s’est souvenu d’eux, quand il a recherché leur sang; il n’a point oublié la prière des pauvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 13, 'Ayez pitié de moi, Seigneur; voyez mon humiliation causée par mes ennemis, vous qui m’avez relevé des portes de la mort:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 14, 'Afin que j’annonce toutes vos louanges aux portes de la fille de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 15, 'Je me réjouirai dans le salut qui vient de vous; les nations ont été saisies par la mort, qu’elles avaient préparée; leur pied s’est pris dans le filet même qu’elles avaient tendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 16, 'On reconnaîtra le Seigneur à ses jugements; le pécheur est enlacé dans les œuvres de ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 17, 'Que les pécheurs soient précipités dans l’enfer, et toutes les nations qui oublient Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 18, 'Car le mendiant ne sera pas toujours en oubli; la patience des pauvres ne sera point perdue pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 19, 'Levez-vous, Seigneur, de peur que l’homme ne s’affermisse; que les nations soient jugées devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 20, 'Seigneur, mettez sur eux un législateur; afin que les Gentils apprennent qu’ils sont hommes. (Changement de rhythme.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 21, 'Pourquoi, Seigneur, vous êtes-vous retiré au loin; et nous méprisez-vous dans l’affliction et au temps du besoin?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 22, 'Pendant que l’impie se gonfle d’orgueil, le pauvre se consume; les méchants seront pris dans les ruses qu’ils avaient conçues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 23, 'Car le pécheur se loue des désirs de son âme, et l’injuste est comblé de biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 24, 'Le pécheur a irrité Dieu; dans la plénitude de sa passion, il n’aura garde de le chercher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 25, 'Le Seigneur n’est point là devant lui. En tout temps ses voies sont souillées; vos jugements, mon Dieu, sont ôtés de devant sa face; et il prévaudra sur tous ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 26, 'Car il a dit en son cœur: Je ne serai point ébranlé, et de génération en génération je serai sans mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 27, 'Sa bouche est pleine de malédiction, d’amertume, de fourberies; la peine et la douleur sont sous sa langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 28, 'Il se tient en embuscade avec les riches, dans des lieux cachés, pour tuer l’innocent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 29, 'Les yeux tournés sur le pauvre, il l’épie en secret, comme le lion dans son antre; il dresse là ses embûches pour le ravir, après l’avoir attiré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 30, 'Il le renversera dans ses filets; puis il se baissera et tombera sur lui, quand il se sera rendu maître des pauvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 31, 'Car il a dit en son cœur: Dieu a oublié; il a détourné sa face pour ne plus jamais voir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 32, 'Levez-vous, Seigneur Dieu, levez votre main; n’oubliez pas les pauvres!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 33, 'Pourquoi l’impie a-t-il irrité Dieu? Car il a dit en son cœur: Il ne fera pas de recherches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 34, 'Mais vous voyez, vous êtes attentif à la peine et à la douleur, pour faire tomber dans vos mains les méchants; à vous seul le pauvre est confié, vous êtes le protecteur de l’orphelin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 35, 'Broyez le bras du méchant et du pécheur; son péché sera recherché, et on ne le trouvera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 36, 'Le Seigneur règnera éternellement dans les siècles des siècles; et vous, Gentils, vous périrez sur la terre qui lui appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 37, 'Le Seigneur a exaucé le désir des pauvres; votre oreille a entendu la préparation de leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 38, 'Jugez l’humble et l’orphelin, afin que l’homme sur la terre ne continue pas de s’enorgueillir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 1, 'Je me confie au Seigneur; comment dites-vous à mon âme Fuyez sur la montagne, comme un passereau?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 2, 'Car voici que les pécheurs ont tendu leur arc; la flèche est prête dans le carquois, afin de percer dans l’obscurité de la nuit les hommes au cœur droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 3, 'Ils ont détruit ce que vous aviez fait; mais le juste, qu’a-t-il fait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 4, 'Le Seigneur réside en son temple saint; le Seigneur a son trône au ciel; ses yeux sont fixés sur le pauvre; ses regards interrogent les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 5, 'Le Seigneur interroge le juste et l’impie; celui qui aime l’iniquité hait son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 6, 'Il fera pleuvoir les piéges sur les pécheurs; le fer, le soufre, le vent d’orage, sont une part de leur calice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 7, 'Car le Seigneur est juste, et il a toujours aimé la justice; sa face regarde l’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 1, 'Sauvez-moi, Seigneur, parce que la sainteté a défailli, et que les vérités ont été amoindries par les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 2, 'Chacun a dit à son prochain des choses vaines; leurs lèvres sont menteuses, et ils ont parlé avec un cœur double.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 3, 'Que le Seigneur perde les lèvres menteuses et les langues pleines de jactance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 4, 'Qui ont dit: Nous ferons valoir la puissance de notre langue; nos lèvres dépendent de nous; qui est notre maître?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 5, 'Je me lèverai maintenant, dit le Seigneur, à cause de la misère des indigents et du gémissement du pauvre; je le mettrai en sûreté, et avec lui j’agirai en toute liberté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 6, 'Les paroles de Dieu sont des paroles saintes, de l’argent éprouvé par le feu, dégagé de la terre, purifié sept fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 7, 'Vous, Seigneur, vous nous conserverez, vous nous garderez de cette génération à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 8, 'Les impies se promènent dans un cercle; c’est en vue de votre grandeur que vous avez multiplié les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 1, 'Jusques à quand, Seigneur, m’oublierez-vous? Jusques à quand détournerez-vous de moi votre face?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 2, 'Jusques à quand remplirai-je mon âme de vains projets, et mon cœur d’affliction durant tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 3, 'Jusques à quand mon ennemi s’élèvera-t-il sur moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 4, 'Regardez et écoutez-moi, Seigneur mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 5, 'Éclairez mes yeux, de peur que je ne m’endorme dans la mort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 6, 'De peur que mon ennemi ne vienne à dire: J’ai prévalu contre lui. Ceux qui m’oppriment tressailliront de joie, si je suis ébranlé. Et moi, j’ai espéré en votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 1, 'L’insensé a dit en son cœur: Il n’y a point de Dieu. Ils se sont corrompus; ils sont devenus abominables en leurs affections; pas un d’entre eux ne fait le bien, pas un seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 2, 'Le Seigneur, du haut du ciel, s’est penché sur les fils des hommes pour voir s’il en est qui comprenne et qui cherche Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 3, 'Tous ont dévié, et en même temps sont devenus inutiles; pas un ne fait le bien, pas un seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 4, 'S’instruiront-ils jamais tous ces ouvriers d’iniquité, ces hommes qui dévorent mon peuple, comme s’ils mangeaient du pain?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 5, 'Ils n’ont point invoqué le Seigneur; et ils ont tremblé de frayeur, quand il n’y avait pas à s’effrayer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 6, 'Car Dieu réside parmi la génération des justes; et vous, vous avez confondu le conseil du pauvre, parce que le Seigneur est son espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 7, 'Qui fera sortir de Sion le salut d’Israël? Quand le Seigneur aura ramené son peuple de la captivité, que Jacob tressaille d’allégresse, et qu’Israël se livre à la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 1, 'Seigneur, qui habitera dans votre tabernacle? Qui reposera sur votre montagne sainte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 2, 'Celui qui marche dans l’innocence et qui opère la justice;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 4, 'Le méchant n’est rien à ses yeux; il honore ceux qui craignent le Seigneur; s’il fait un serment à son prochain, il ne le trompe pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 5, 'Il n’a point prêté son argent à usure; il n’a point accepté de dons contre l’innocent. Celui qui fait ces choses ne sera point ébranlé dans l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 1, 'Gardez-moi, Seigneur, car j’ai mis en vous mon espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 2, 'J’ai dit au Seigneur: Vous êtes mon Seigneur, et vous n’avez nul besoin de mes biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 3, 'Quant aux saints qui sont sur la terre, il a fait éclater toutes ses volontés pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 4, 'Leurs infirmités se sont multipliées, et cependant ils ont couru rapidement; je ne rassemblerai plus leurs synagogues de sang; et de mes lèvres je ne mentionnerai pas leur nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 5, 'Le Seigneur est la part de mon héritage et de mon calice; c’est vous, Seigneur, qui me restituerez mon héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 6, 'Les cordeaux sont tombés pour moi aux meilleures places; car mon héritage est excellent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 7, 'Je bénirai le Seigneur, qui m’a donné l’intelligence; mes désirs aussi me pressaient vivement jusque dans la nuit même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 8, 'Je n’ai cessé de voir devant moi le Seigneur; car il se tient à ma droite, pour que je ne sois pas ébranlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 9, 'C’est pourquoi mon cœur s’est réjoui, ma langue a tressailli d’allégresse, et ma chair se reposera dans l’espérance:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 10, 'Parce que vous ne laisserez pas mon âme aux enfers; vous ne permettrez pas que votre Saint voie la corruption.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 11, 'Vous m’avez fait connaître les voies de la vie; vous me remplirez de joie par votre aspect; des délices éternelles sont à votre droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 1, 'Seigneur, exaucez ma justice; soyez attentif à ma demande; prêtez l’oreille à ma prière; elle ne sort point de lèvres trompeuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 2, 'Que mon jugement vienne de votre face; que vos yeux voient l’équité de ma cause.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 3, 'Vous avez éprouvé mon cœur, vous l’avez visité la nuit, vous m’avez éprouvé par le feu, et nulle iniquité n’a été trouvée en moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 4, 'Afin que ma bouche ne parle pas selon les œuvres des hommes; à cause des paroles de vos lèvres, je me suis maintenu en des voies difficiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 5, 'Assurez mes pas en vos sentiers, de peur que mes pieds ne soient ébranlés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 6, 'J’ai crié, ô mon Dieu, parce que vous m’avez déjà écouté; penchez vers moi votre oreille, et écoutez encore mes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 7, 'Montrez les merveilles de votre miséricorde, vous qui sauvez ceux qui espèrent en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 8, 'De ceux qui résistent à votre droite gardez-moi comme la prunelle de l’œil; abritez-moi sous l’ombre de vos ailes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 9, 'Loin de la face des impies qui m’ont affligé; mes ennemis ont environné mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 10, 'Ils ont fermé leur entrailles; leur bouche a exhalé l’orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 11, 'Ils m’ont repoussé, ils m’ont assiégé; ils ont résolu de tourner leurs yeux vers la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 12, 'Ils m’ont attendu, semblables au lion prêt à saisir sa proie ou au lionceau qui se cache dans son antre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 13, 'Levez-vous, Seigneur, devancez-les, et faites-les trébucher; retirez mon âme des mains de l’impie, et votre épée, des mains des ennemis de votre droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 14, 'Séparez-les, dès leur vie, de la terre promise et du petit nombre; car leur ventre est rempli de choses ravies à vos trésors cachés; ils sont rassasiés de chairs impures, et ils ont laissé leurs restes à leurs petits enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 15, 'Pour moi, je paraîtrai devant votre face, avec ma justice; je me rassasierai en contemplant votre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 1, 'Pour David, serviteur de Dieu: il a composé au Seigneur les paroles de ce psaume le jour que le Seigneur l’a sauvé des mains de tous ses ennemis, et des mains de Saül, et il a dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 2, 'Seigneur, je vous aimerai, vous qui êtes ma force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 3, 'Seigneur, mon appui, mon refuge et mon libérateur! Mon Dieu est mon auxiliaire, j’espérerai en lui, il est mon défenseur, la force de mon salut; c’est lui qui me protège.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 4, 'J’invoquerai le Seigneur en le louant, et je serai sauvé des mains de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 5, 'Les angoisses de la mort m’ont environné; des torrents d’iniquités m’ont grandement troublé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 6, 'J’étais investi par les tourments de l’enfer; j’avais été surpris par les filets de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 7, 'En ces afflictions, j’ai invoqué le Seigneur; j’ai crié vers mon Dieu: de sa demeure sainte il a entendu ma voix; mes cris arrivent jusqu’à lui, ils pénétreront dans ses oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 8, 'Et la terre a été ébranlée, elle a tremblé, et les assises des montagnes ont été troublées jusqu’en leurs fondements; et elles ont chancelé, parce que le Seigneur était courroucé contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 9, 'Sa colère a fait jaillir de la fumée; et son visage a lancé sa flamme; des charbons en ont été embrasés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 10, 'Il a incliné les cieux et il est descendu, et l’obscurité était sous ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 11, 'Et il est monté sur les Chérubins, et il a volé; il a volé sur les ailes des vents;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 12, 'Et il s’est entouré de ténèbres, et il y a fait son tabernacle dans l’eau sombre des nuées de l’air.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 13, 'Et les nuées ont passé devant lui, chassées par sa splendeur; il a lancé de la grêle et des charbons de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 14, 'Et le Seigneur a tonné du haut du ciel; et le Très-Haut a fait entendre sa voix;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 15, 'Et il a lancé ses flèches, et il a dispersé mes ennemis; il a multiplié les éclairs, et ils ont été troublés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 16, 'Et les sources des eaux ont apparu, et les fondements de la terre ont été visibles, à cause de vos menaces, Seigneur, à cause du souffle de votre colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 17, 'Il a envoyé son secours du haut des cieux, et il m’a pris; il m’a retiré des abîmes de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 18, 'Il m’a sauvé de mes puissants ennemis et de ceux qui me haïssent; car ils étaient plus forts que moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 19, 'Ils m’ont pris au dépourvu le jour de mon affliction; mais le Seigneur a été mon appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 20, 'Et il m’a conduit au large; il me sauvera, à cause de sa bonne volonté pour moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 21, 'Et le Seigneur me récompensera selon ma justice, et selon la pureté de mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 22, 'Car j’ai gardé les voies du Seigneur; je n’ai point été impie, m’écartant de mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 23, 'J’ai eu présents à l’esprit tous ses jugements; et ses justices je ne les ai point éloignées de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 24, 'Et je serai sans tache avec lui, et je me garderai de mon iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 25, 'Et le Seigneur me récompensera selon ma justice, et selon la pureté de mes mains qui est manifeste à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 26, 'Avec le saint vous serez saint, ô Seigneur, et avec l’homme innocent, vous serez innocent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 27, 'Avec l’élu, vous serez élu, et avec le méchant vous serez impitoyable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 28, 'Et vous sauverez le peuple des humbles, et vous humilierez les yeux du superbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 29, 'Vous ferez luire ma lampe, Seigneur mon Dieu, et vous éclairerez mes ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 30, 'Avec l’aide de mon Dieu je ne succomberai pas aux tentations, avec lui je franchirai le mur qui m’environne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 31, 'Ô mon Dieu, votre voie est irréprochable; les paroles du Seigneur ont été éprouvées comme le feu; il est le protecteur de ceux qui espèrent en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 32, 'Car qui est Dieu, sinon le Seigneur? qui est Dieu, sinon notre Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 33, 'C’est Dieu qui m’a ceint de force et qui a rendu ma voie sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 34, 'C’est lui qui a donné à mes pieds l’agilité du cerf, et qui m’a établi sur les hauts lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 35, 'C’est lui qui a exercé mes mains aux combats, et qui a rendu mes bras forts comme un arc d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 36, 'Vous m’avez accordé votre protection, pour mon salut; votre main droite m’a soutenu; vos châtiments ont réussi à me corriger; vos châtiments mêmes continueront de m’instruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 37, 'Vous avez élargi le chemin sous mes pas, et mes pieds n’ont point vacillé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 38, 'Je poursuivrai mes ennemis, je les saisirai, je ne reviendrai pas qu’ils ne soient exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 39, 'Je les broierai, et ils ne pourront se soutenir; ils tomberont sous mes pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 40, 'Et pour les combats vous m’avez ceint de force; vous avez abattu sous moi tous ceux qui s’étaient élevés contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 41, 'Et mes ennemis, vous leur avez fait tourner le dos devant moi; et ceux qui me haïssaient, vous les avez anéantis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 42, 'Ils ont crié, mais il n’y avait là personne qui les sauvât; ils ont crié au Seigneur, et il ne les a pas exaucés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 43, 'Je les briserai comme la poussière à la face du vent; je les balayerai comme la boue des places publiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 44, 'Arrachez-moi aux contradictions du peuple, vous me mettrez à la tête des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 45, 'Un peuple que je ne connaissais pas m’a été asservi; son oreille m’a entendu, et il m’a obéi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 46, 'Des fils révoltés m’ont menti, des fils révoltés ont vieilli et ont boité, en sortant de leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 47, 'Vive le Seigneur, béni soit le Seigneur mon Dieu, que le Dieu de mon salut soit exalté!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 48, 'C’est vous, mon Dieu, qui vous chargez de mes vengeances; vous qui me soumettez les peuples; vous, mon libérateur contre la colère de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 49, 'Vous m’élèverez au-dessus de ceux qui se sont révoltés contre moi; vous me délivrerez de l’homme inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 50, 'À cause de cela, Seigneur, je célèbrerai votre gloire parmi les nations, et je chanterai votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 51, 'Dieu exalte le salut de son roi; il est plein de miséricorde pour David son christ, et pour sa postérité dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 1, 'Les cieux racontent la gloire du Seigneur, et le firmament fait connaître l’œuvre de ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 2, 'Le jour parle de lui au jour; la nuit montre sa science à la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 3, 'Il n’y a langage ni paroles dont leur voix ne soit entendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 4, 'Leur voix s’est répandue sur toute la terre; leur parole est parvenue au bout du monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 5, 'Il a tendu son tabernacle dans le soleil; et le soleil ressemble au jeune époux sortant de son lit nuptial, il a tressailli de joie comme un géant pour courir dans sa voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 6, 'Il sort de l’extrémité du ciel; et son issue est à l’autre extrémité; et nul ne peut se mettre à l’abri de sa chaleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 7, 'La loi du Seigneur est immaculée, elle convertit les âmes; le témoignage du Seigneur est fidèle, il donne la sagesse aux enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 8, 'La justice du Seigneur est droite, elle réjouit le cœur; les préceptes du Seigneur brillent d’un vif éclat, ils éclairent les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 9, 'La crainte du Seigneur est sainte, elle persiste dans les siècles des siècles; les jugements du Seigneur sont vrais, et justifiés en eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 10, 'Ils sont infiniment plus désirables que l’or et les pierres précieuses; ils sont plus doux que le miel et que les rayons de miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 11, 'Aussi votre serviteur les garde-t-il; à les garder on gagne un riche salaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 12, 'Qui a conscience de ses chutes? Purifiez-moi de mes fautes les plus cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 13, 'Préservez votre serviteur des vices des étrangers. S’ils ne me dominent pas, alors je serai sans souillure et lavé d’un grand péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 14, 'Alors les paroles de ma bouche vous plairont, et les pensées de mon cœur seront toujours agréables devant vous. Seigneur, vous êtes mon aide et mon Rédempteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 1, 'Que le Seigneur t’exauce au jour de l’affliction; que le nom du Dieu de Jacob te protége!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 2, 'Que du lieu saint il t’envoie son secours, et que, de Sion, il prenne ta défense!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 3, 'Qu’il se souvienne de tout ton sacrifice, et que ton holocauste lui soit agréable!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 4, 'Qu’il te gratifie selon ton cœur et accomplisse tous tes desseins!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 5, 'Nous nous réjouirons de ton salut; nous serons glorifiés au nom du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 6, 'Que le Seigneur t’accorde toutes tes demandes! Je sais maintenant que le Seigneur a sauvé son Christ. Il l’exaucera du ciel son lieu saint; le salut qui vient de sa main droite est tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 7, 'Les uns se glorifient en leurs chevaux, les autres en leurs chars; pour nous, c’est dans le nom du Seigneur que nous nous glorifions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 8, 'Ceux-là se sont embarrassés dans leurs liens, et ils sont tombés; nous nous sommes levés et nous nous tenons debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 9, 'Seigneur, sauvez le roi, et exaucez-nous le jour où nous vous invoquerons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 1, 'Seigneur, le roi se réjouira de votre puissance; il sera, dans l’excès de sa joie, sauvé par vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 2, 'Vous l’avez gratifié selon les désirs de son âme; vous ne l’avez point sevré de ce que demandaient ses lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 3, 'Vous l’avez prévenu des bénédictions de votre douceur; vous avez posé sur sa tête une couronne de pierres précieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 4, 'Il vous avait demandé la vie, et vous lui avez donné de longs jours qui s’étendront dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 5, 'Sa gloire est grande d’avoir été sauvé par vous; vous avez mis sur lui la gloire et la magnificence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 6, 'Car vous le bénirez dans tous les siècles des siècles; vous le comblerez de joie en lui montrant votre face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 7, 'Aussi le roi espère dans le Seigneur; grâce à la miséricorde du Très-Haut, il ne sera jamais ébranlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 8, 'Que tous vos ennemis trouvent votre main; que votre droite trouve tous ceux qui vous haïssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 9, 'Au temps où votre face se tournera contre eux, vous les brûlerez comme dans une fournaise embrasée; le Seigneur les troublera de sa colère, et le feu les dévorera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 10, 'Vous détruirez leurs fruits sur la terre, et leurs fils d’entre les fils des hommes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 11, 'Parce qu’ils ont voulu déverser sur vous le mal; ils ont conçu des desseins dont ils ne pourront venir à bout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 12, 'Aussi vous leur ferez tourner le dos; et, pour recevoir vos derniers coups, vous retournerez leur visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 13, 'Levez-vous, Seigneur, en votre force; nous célèbrerons et nous chanterons vos grandeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 20, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 1, 'O Dieu, ô mon Dieu, regardez-moi; pourquoi m’avez-vous délaissé? la voix de mes péchés a fait fuir mon salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 2, 'O mon Dieu, je crierai vers vous le jour, et vous ne m’exaucerez point; je crierai la nuit, et ce n’est point folie à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 3, 'Mais vous, gloire d’Israël, vous résidez au lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 4, 'Nos pères ont espéré en vous; ils ont espéré, et vous les avez délivrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 5, 'Ils ont crié vers vous, et ils ont été sauvés; ils ont espéré en vous, et n’ont point été confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 6, 'Mais moi je suis un ver de terre et non un homme; opprobre des hommes et mépris du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 7, 'Tous ceux qui m’ont vu se sont moqués de moi; ils ont murmuré entre leurs lèvres, ils ont secoué la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 8, 'Ils ont dit: Il a mis son espoir en Dieu, que le Seigneur le sauve; qu’il le délivre, puisqu’il se complaît en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 9, 'C’est vous, il est vrai, qui m’avez tiré des entrailles de ma mère; et, à sa mamelle, j’espérais en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 10, 'Aussitôt sorti de son sein, j’ai été livré à vous; vous étiez mon Dieu dès le sein de ma mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 11, 'Ne vous éloignez point de moi; car l’affliction est proche, et nul ne me porte secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 12, 'Une multitude de jeunes taureaux m’investissent, des bœufs robustes m’ont entouré,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 13, 'Et ont ouvert contre moi leur bouche, comme un lion ravisseur et rugissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 14, 'Je me suis répandu comme de l’eau; tous mes os ont été dispersés; mon cœur dans ma poitrine est devenu comme de la cire liquide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 15, 'Ma force s’est desséchée comme la brique; ma langue s’est collée à mon palais, et vous m’avez poussé dans la poussière de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 16, 'Une multitude de chiens m’ont entouré; la synagogue des pervers m’assiége; ils m’ont percé les pieds et les mains,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 17, 'Ils ont compté mes os; ils m’ont observé et surveillé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 18, 'Ils se sont partagé mes vêtements, et ils ont tiré ma robe au sort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 19, 'Et vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 20, 'Délivrez mon âme du glaive; délivrez de la griffe des chiens mon unique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 21, 'Tirez-moi de la gueule du lion, et sauvez ma faiblesse de la corne des licornes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 22, 'Je célèbrerai votre nom parmi mes frères; je vous chanterai au milieu de l’église.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 23, 'O vous qui craignez le Seigneur, louez-le; et toi, peuple de Jacob, glorifie-le.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 24, 'Que toute la race d’Israël le craigne, parce qu’il');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 25, 'Vous serez ma louange dans la grande église; j’accomplirai mes vœux devant tous ceux qui vous craignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 26, 'Les pauvres mangeront, et ils seront rassasiés; et ceux qui cherchent le Seigneur le loueront; leurs cœurs vivront dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 27, 'Et jusqu’aux confins de la terre on se souviendra du Seigneur; on se convertira à lui; toutes les tribus des gentils se prosterneront devant lui pour l’adorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 28, 'Car la royauté appartient au Seigneur; il règnera sur les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 29, 'Tous les riches de la terre ont mangé et adoré; tous ceux qui descendent en la terre tomberont devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 30, 'Que mon âme aussi vive pour lui, toute ma postérité le servira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 31, 'La génération future sera annoncée au Seigneur; on fera connaître sa justice au peuple qui doit naître, et que le Seigneur s’est préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 21, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 22, 1, 'Le Seigneur est mon pasteur, et je ne manquerai de rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 22, 2, 'Il m’a fait demeurer en un gras pâturage; il m’a nourri d’une eau vivifiante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 22, 3, 'Il a converti mon âme; il m’a conduit dans les voies de la justice pour la gloire de son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 22, 4, 'Lors même que je cheminerais au milieu des ombres de la mort, je ne craindrais aucun mal, parce que vous êtes avec moi. Votre houlette et votre bâton m’ont rassuré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 22, 5, 'Vous avez préparé devant moi une table, afin que je résiste à ceux qui m’opprimaient. Vous avez oint ma tête avec de l’huile; et votre calice enivrant, qu’il est délicieux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 22, 6, 'Et votre miséricorde me suivra tous les jours de ma vie; et ma demeure sera la maison du Seigneur dans toute la durée des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 1, 'La terre est au Seigneur, et tout ce qu’elle contient, le monde et ceux qui l’habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 2, 'Il l’a fondée sur la mer, il l’a préparée sur les fleuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 3, 'Qui montera sur la montagne du Seigneur? qui se tiendra dans son sanctuaire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 4, 'Celui dont les mains sont innocentes et dont le cœur est pur; qui n’a point reçu en vain son âme; qui n’a point trompé son prochain par de faux serments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 5, 'Celui-là recevra la bénédiction du Seigneur, et la miséricorde de Dieu son Sauveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 6, 'Telle est la génération de ceux qui le cherchent, qui cherchent la face du Dieu de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 7, 'Princes, levez vos portes; ouvrez-vous, portes éternelles, et le Roi de gloire entrera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 8, 'Quel est donc le Roi de gloire? C’est le Seigneur fort et puissant, le Seigneur puissant au combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 9, 'Princes, levez vos portes; ouvrez-vous, portes éternelles, et le Roi de gloire entrera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 23, 10, 'Quel est donc ce Roi de gloire? C’est le Dieu des vertus, c’est lui qui est le Roi de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 1, 'Vers vous, Seigneur, j’ai élevé mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 2, 'O mon Dieu, je me suis confié en vous: que je ne sois pas confondu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 3, 'Que mes ennemis ne se moquent point de moi; car nul de ceux qui vous attendent ne sera confondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 4, 'Soient confondus tous ceux qui, dans leur vanité, agissent contre la justice; montrez-moi vos voies, faites-moi connaître vos sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 5, 'Conduisez-moi dans votre vérité, et instruisez-moi; car vous êtes, ô Dieu, mon Sauveur, et je vous ai attendu tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 6, 'Seigneur, souvenez-vous de votre compassion et de vos miséricordes; car vos miséricordes sont de toute éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 7, 'Ne vous rappelez pas les péchés de ma jeunesse ni mes inadvertances; Seigneur, souvenez-vous de moi en votre miséricorde, et à cause de votre bonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 8, 'Le Seigneur est doux, il est droit; aussi, par sa loi, il remettra dans la voie les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 9, 'Il guidera les doux dans la justice; il enseignera ses voies aux doux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 10, 'Toutes les voies du Seigneur sont miséricorde et vérité, pour ceux qui cherchent son alliance et ses témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 11, 'Pour l’amour de votre nom, Seigneur, vous me pardonnerez mon péché, parce qu’il est grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 12, 'Quel est l’homme qui craint le Seigneur? Le Seigneur lui prescrira une loi dans la voie que lui-même a choisie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 13, 'Son âme résidera au milieu des biens, et sa race héritera de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 14, 'Le Seigneur est la force de ceux qui le craignent, et son alliance existe pour leur être montrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 15, 'Mes yeux seront toujours tournés vers le Seigneur, parce que lui-même retirera mes pieds des filets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 16, 'Regardez-moi et ayez pitié de moi, car je suis seul et pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 17, 'Les afflictions de mon cœur se sont multipliées; délivrez-moi de ma détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 18, 'Voyez mon humiliation et ma douleur, et remettez-moi tous mes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 19, 'Voyez mes ennemis, comme ils se sont multipliés, et comme ils m’ont haï d’une haine injuste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 20, 'Gardez mon âme et délivrez-moi; que je ne sois point confondu, car j’ai espéré en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 21, 'Les innocents et les cœurs droits me sont attachés, Seigneur, parce que je vous ai attendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 24, 22, 'O mon Dieu, délivrez Israël de toutes ses afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 1, 'Jugez-moi, Seigneur, car j’ai cheminé en mon innocence; espérant au Seigneur, je ne serai point ébranlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 2, 'Éprouvez-moi, Seigneur, et tentez-moi; purifiez par le feu mon cœur et mes reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 3, 'Car votre miséricorde est devant mes yeux, et je me suis complu en votre vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 4, 'Je ne me suis point assis au conseil de vanité, et je n’entrerai point où sont les artisans d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 5, 'Je hais l’assemblée des méchants; je ne m’assiérai point avec les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 6, 'Je me laverai les mains parmi les innocents, et je me tiendrai autour de votre autel, ô Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 7, 'Afin d’entendre la voix de votre louange, et de raconter toutes vos merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 8, 'Seigneur, j’ai aimé la beauté de votre temple, et le tabernacle où habite votre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 9, 'O Dieu, ne perdez pas mon âme avec les impies, ni ma vie avec les hommes de sang,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 10, 'Dont les mains sont iniques, dont la droite est remplie de présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 11, 'Pour moi, j’ai cheminé en mon innocence; affranchissez-moi et ayez pitié de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 25, 12, 'Mon pied est resté dans la droite voie; je vous bénirai, Seigneur, dans les assemblées saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 1, 'Le Seigneur est ma lumière et mon salut: qui craindrai-je? Le Seigneur protège ma vie: de qui aurai-je peur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 2, 'Quand des hommes malfaisants se sont approchés de moi pour manger mes chairs, mes persécuteurs et mes ennemis eux-mêmes ont perdu leur force, et sont tombés. Lors même qu’une armée serait campée devant moi, mon cœur ne serait pas effrayé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 3, 'Lors même que la guerre s’élèverait contre moi, mon espérance serait encore dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 4, 'J’ai demandé une chose au Seigneur, et je la demanderai toujours: c’est que j’habite en la maison du Seigneur tous les jours de ma vie, pour contempler la beauté du Seigneur et visiter son temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 5, 'Car, aux jours de mon adversité, il m’a caché dans son tabernacle, il m’a abrité en son sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 6, 'Il m’a établi sur le roc, et maintenant voici qu’il élève ma tête au-dessus de mes ennemis. Je me suis tenu autour de son tabernacle, et j’y ai fait une oblation d’allégresse; je chanterai un psaume au Seigneur, je le célèbrerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 7, 'Seigneur, soyez attentif à ma voix et à mes cris; ayez pitié de moi et exaucez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 8, 'Mon cœur vous a parlé, j’ai cherché votre visage, Seigneur, et je le chercherai toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 9, 'Ne détournez point de moi votre face; en votre colère ne vous éloignez pas de votre serviteur; soyez mon aide, ne m’abandonnez pas, ô Dieu mon Sauveur, ne me méprisez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 10, 'Car mon père et ma mère m’ont délaissé; mais le Seigneur lui-même m’a recueilli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 11, 'Donnez-moi la loi qui montre votre voie; guidezmoi dans le droit chemin à cause de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 12, 'Ne me livrez pas au mauvais vouloir de ceux qui m’affligent; car de faux témoins se sont levés contre moi, et l’iniquité a menti à elle-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 13, 'Je crois que je verrai les biens du Seigneur sur la terre des vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 26, 14, 'Attends le Seigneur, sois homme; que ton cœur se fortifie, et attends le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 1, 'J’ai crié vers vous, Seigneur; ô mon Dieu, ne gardez pas sur moi le silence, de peur que, si vous vous taisez, je ne ressemble à ceux qui descendent dans le sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 2, 'Écoutez la voix de ma supplication quand je vous prie, et que j’élève les mains vers votre temple saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 3, 'N’entraînez pas mon âme avec les pécheurs; ne me perdez pas avec ceux qui font le mal ou qui disent à leur prochain des paroles de paix, tandis que la méchanceté est dans leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 4, 'Rétribuez ceux-là selon leurs œuvres, et selon la perversité de leurs desseins; donnez-leur selon les œuvres de leurs mains; rendez-leur ce qui leur est dû.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 5, 'Parce qu’ils n’ont rien compris aux œuvres du Seigneur, aux œuvres de ses mains, vous les détruirez; vous ne les édifierez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 6, 'Béni soit le Seigneur, parce qu’il a écouté la voix de ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 7, 'Le Seigneur est mon auxiliaire et mon protecteur; mon cœur a mis en lui son espérance, et j’ai été secouru, et ma chair a refleuri; et de tout cœur je lui rendrai grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 8, 'Le Seigneur est la force de son peuple; il est le défenseur qui délivre son Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 27, 9, 'Sauvez votre peuple, bénissez votre héritage, soyez son pasteur et glorifiez-le dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 1, 'Apportez au Seigneur, enfants de Dieu, apportez au Seigneur les petits des béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 2, 'Rendez au Seigneur gloire et honneur; glorifiez le nom du Seigneur; adorez le Seigneur en son saint parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 3, 'La voix du Seigneur est sur les eaux; le Dieu de gloire a tonné; le Seigneur est sur les grandes eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 4, 'La voix du Seigneur est puissante; la voix du Seigneur est pleine de magnificence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 5, 'La voix du Seigneur brise les cèdres; le Seigneur va broyer les cèdres du Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 6, 'Il les brisera comme un jeune taureau du Liban, comme le faon chéri de la licorne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 7, 'C’est la voix du Seigneur qui divise la flamme et le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 8, 'C’est la voix du Seigneur qui fait trembler le désert; le Seigneur ébranlera le désert de Cadès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 9, 'C’est la voix du Seigneur qui a préparé la naissance des cerfs; elle découvrira les forêts, et dans le temple du Seigneur chacun dira sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 10, 'Le Seigneur répandra sur la terre un déluge; le Seigneur est roi, et il siégera éternellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 28, 11, 'Le Seigneur fortifiera son peuple; le Seigneur bénira son peuple en lui donnant la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 1, 'Je vous exalterai, Seigneur; car vous m’avez relevé, et vous n’avez point fait de moi la joie de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 2, 'Seigneur mon Dieu, j’ai crié vers vous, et vous m’avez guéri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 3, 'Seigneur, vous avez ramené mon âme de l’enfer; vous m’avez sauvé parmi ceux qui descendent dans le sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 4, 'Chantez le Seigneur, vous ses saints; rendez-lui grâces au souvenir de sa sainteté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 5, 'Car la colère naît de son indignation, mais la vie est en sa volonté; le soir, il y aura des pleurs, et à l’aurore l’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 6, 'Pour moi, j’ai dit en ma prospérité: Je serai à jamais inébranlable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 7, 'Seigneur, votre volonté sainte me maintenait en ma force et ma beauté; vous avez détourné de moi votre visage, et j’ai été troublé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 8, 'Je crierai vers vous, Seigneur; j’adresserai mes prières à mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 9, 'De quelle utilité vous serait mon sang, si je tombais en corruption? Ma cendre vous rendrait-elle gloire? ferait-elle connaître votre vérité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 10, 'Le Seigneur m’a entendu, et il a eu pitié de moi; le Seigneur est devenu mon auxiliaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 11, 'Vous avez changé mes lamentations en joie; vous avez déchiré mon cilice; vous m’avez environné d’allégresse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 12, 'Afin que ma gloire chante vos louanges, et que la douleur ne me transperce plus. Seigneur mon Dieu, je vous rendrai éternellement grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 29, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 1, 'Seigneur, j’ai espéré en vous; que je ne sois point confondu éternellement. Délivrez-moi en votre justice, et sauvez moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 2, 'Penchez vers moi votre oreille; hâtez-vous de me sauver; soyez-moi un Dieu protecteur, et comme une maison de refuge, afin que je sois sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 3, 'Car vous êtes ma force et mon refuge; et pour l’amour de votre nom vous me guiderez et me nourrirez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 4, 'Vous me tirerez de ce piège qu’ils avaient caché pour moi; car vous êtes mon protecteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 5, 'Je remets mon âme en vos mains; vous m’avez racheté, Seigneur, Dieu de vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 6, 'Vous haïssez ceux qui s’attachent follement aux choses vaines; pour moi, j’ai placé mon espérance dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 7, 'Je trouverai mon bonheur et ma joie en votre miséricorde; car vous avez considéré mon humiliation, vous avez sauvé mon âme de sa détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 8, 'Vous ne m’avez pas enfermé dans les mains de mes ennemis; vous avez donné de l’espace à mes pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 9, 'Ayez pitié de moi, Seigneur, parce que je suis affligé; mon œil est troublé par la tristesse, et mon âme, et mes entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 10, 'Ma vie s’est éteinte dans la douleur, et mes années dans les sanglots; ma force a été brisée par la misère, et mes os ébranlés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 11, 'Je suis devenu un signe d’outrage pour tous mes ennemis et surtout pour mes voisins; je suis devenu l’effroi de mes proches; ceux qui m’ont vu se sont enfuis au dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 12, 'J’ai été mis en oubli dans les cœurs comme un mort; on m’a traité comme un vase brisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 13, 'J’ai ouï le blâme de plusieurs qui demeurent autour de moi; pendant qu’ils se réunissaient contre moi, ils ont tenu conseil pour m’ôter la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 14, 'Mais moi, Seigneur, j’ai mis en vous mon espérance, et j’ai dit: Vous êtes mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 15, 'Mon sort est entre vos mains; arrachez-moi de la main de mes ennemis et de ceux qui me persécutent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 16, 'Montrez à votre serviteur la lumière de votre visage; sauvez-moi par votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 17, 'Seigneur, que je ne sois point confondu, car je vous ai invoqué; que les impies rougissent et soient précipités en enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 18, 'Que les lèvres trompeuses deviennent muettes; car elles profèrent l’iniquité contre le juste avec orgueil et mépris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 19, 'Combien est grande, Seigneur, l’abondance de douceur que vous avez réservée à ceux qui vous craingnent! Vous l’avez rendue parfaite pour ceux qui espèrent en vous, devant les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 20, 'Ceux-là vous les cacherez dans le secret de votre face pour les préserver du trouble des hommes; vous les mettrez en votre tabernacle à l’abri de la contradiction des langues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 21, 'Béni soit le Seigneur, parce qu’il m’a merveilleusement manifesté sa miséricorde comme en une ville fortifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 22, 'Et moi j’ai dit dans le transport de mon âme: J’ai été rejeté loin de vos yeux; c’est pourquoi, Seigneur, lorsque j’ai crié vers vous, vous avez exaucé la voix de ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 23, 'Aimez le Seigneur, vous tous qui êtes ses saints; car le Seigneur cherche la vérité, et il rétribuera abondamment les superbes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 24, 'Soyez hommes; et que votre cœur se fortifie, vous tous qui espérez en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 30, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 1, 'Heureux ceux à qui leurs péchés ont été remis, et dont les fautes ont été couvertes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 2, 'Heureux l’homme à qui le Seigneur n’impute point de péché, et qui n’a pas de fraude sur les lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 3, 'Parce que j’ai gardé le silence, mes os ont vieilli, quand je criais tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 4, 'Jour et nuit votre main s’était appesantie sur moi; je me retournais dans ma détresse, tandis qu’une épine s’enfonçait en moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 5, 'Je vous ai fait connaître mon péché; je n’ai point caché mon iniquité. J’ai dit: Je confesserai à Dieu mon iniquité contre moi; et vous m’avez pardonné l’impiété de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 6, 'À cause de cela chaque saint vous fera sa prière au moment opportun; les grandes eaux même d’un déluge n’approcheront point de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 7, 'Vous êtes mon refuge dans la tribulation qui m’a environné; ô vous, ô ma joie, délivrez-moi de ceux qui m’ont investi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 8, 'Je te donnerai l’intelligence et je t’affermirai dans la voie où tu dois marcher; j’aurai toujours les yeux fixés sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 9, 'Ne soyez pas comme le cheval et le mulet, à qui manque l’intelligence serre leur bouche avec la bride et le frein, pour qu’ils ne s’approchent point de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 10, 'Les flagellations réservées aux pécheurs sont nombreuses; tandis que la miséricorde du Seigneur entourera celui qui espère en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 31, 11, 'O justes, livrez-vous dans le Seigneur à la joie et à tous ses transports; et glorifiez-vous en lui, vous tous dont le cœur est droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 1, 'Justes, mettez votre joie dans le Seigneur; la louange convient aux cœurs droits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 2, 'Chantez sur la cithare les louanges du Seigneur; chantez pour lui sur la harpe à dix cordes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 3, 'Chantez pour lui un cantique nouveau; chantez en accord et à haute voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 4, 'Car la parole du Seigneur est sûre; il est fidèle en toutes ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 5, 'Il aime la miséricorde et la justice; la terre est pleine de la miséricorde du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 6, 'Les cieux se sont affermis à la parole du Seigneur, et toute leur vertu au souffle de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 7, 'Il a rassemblé comme dans une outre les eaux de la mer; il a déposé les abîmes dans ses trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 8, 'Que toute la terre craigne le Seigneur; que ceux qui habitent le monde tremblent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 9, 'Car il a dit, et ils ont été; il a commandé, et ils ont été créés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 10, 'Le Seigneur dissipe les conseils des nations; il réprouve les pensées des peuples; il réprouve les desseins des princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 11, 'Mais le conseil du Seigneur dure éternellement; les pensées de son cœur vivent de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 12, 'Heureuse la nation dont le Seigneur est le Dieu; heureux le peuple qu’il s’est choisi pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 13, 'Le Seigneur a regardé du ciel, il a vu tous les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 14, 'De la demeure qu’il s’est préparée, il regarde tous ceux qui habitent la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 15, 'C’est lui qui a formé le cœur de chacun d’eux; il connaît toutes leurs œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 16, 'Un roi n’est pas sauvé par une armée nombreuse; un géant ne sera pas délivré par sa grande force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 17, 'Le cheval trompe celui qui en attend le salut, et la multitude de ses forces ne le sauvera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 18, 'Voilà que les yeux du Seigneur sont sur ceux qui le craignent et qui espèrent en sa miséricorde;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 19, 'Pour qu’il sauve leurs âmes de la mort, qu’il les nourrisse au temps de la famine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 20, 'Notre âme attend le Seigneur; car il est notre protecteur et notre auxiliaire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 21, 'Car en lui notre cœur mettra sa joie, et nous avons espéré en son saint nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 32, 22, 'Seigneur, répandez sur nous votre miséricorde, autant que nous l’avons espéré de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 1, 'En tout temps je bénirai le Seigneur; sa louange sera en tout temps dans ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 2, 'Mon âme se réjouira dans le Seigneur; que les doux écoutent et se réjouissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 3, 'Glorifiez avec moi le Seigneur, et exaltons son nom tous ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 4, 'J’ai cherché le Seigneur, et il m’a exaucé; il m’a tiré de toutes mes afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 5, 'Approchez-vous de lui, éclairez-vous de sa lumière, et votre face ne sera pas confondue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 6, 'Le pauvre a crié et le Seigneur l’a exaucé, et il l’a délivré de toutes ses afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 7, 'L’ange du Seigneur veillera autour de ceux qui craignent Dieu, et il les sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 8, 'Goûtez et voyez combien le Seigneur est doux; heureux l’homme qui espère en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 9, 'Craignez le Seigneur, vous tous qui êtes ses saints; car rien ne manque à ceux qui le craignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 10, 'Les riches sont devenus pauvres et ils ont eu faim; mais ceux qui cherchent le Seigneur ne manqueront d’aucun bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 11, 'Venez, enfants, écoutez-moi; je vous enseignerai la crainte du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 12, 'Quel est l’homme qui veut la vie, qui désire voir des jours heureux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 13, 'Que sa langue s’abstienne du mal, et ses lèvres du mensonge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 14, 'Détourne-toi du mal, et fais le bien; cherche la paix et la poursuis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 15, 'Les yeux du Seigneur sont sur les justes, et ses oreilles vers leurs prières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 16, 'Le visage du Seigneur est tourné contre ceux qui font le mal, pour effacer de la terre leur souvenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 17, 'Les justes ont crié, et le Seigneur les a exaucés; et il les a délivrés de toutes leurs afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 18, 'Le Seigneur est près de ceux dont le cœur est affligé; il sauvera les humbles d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 19, 'Les afflictions du juste sont nombreuses, et de toutes le Seigneur le délivrera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 20, 'Le Seigneur garde tous leurs os, pas un seul ne sera broyé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 21, 'La mort des pécheurs est le plus grand des maux, et ceux qui haïssent le juste périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 22, 'Le Seigneur affranchira les âmes de ceux qui le servent, et ceux qui espèrent en lui ne défailliront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 33, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 1, 'Seigneur, jugez ceux qui me nuisent; combattez ceux qui me font la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 2, 'Prenez vos armes et votre bouclier; levez-vous à mon aide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 3, 'Tirez le glaive et fermez la voie à ceux qui me poursuivent; dites à mon âme: Je suis ton salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 4, 'Que ceux qui en veulent à ma vie soient confondus et frappés de crainte; que ceux qui pensent à mal contre moi soient confondus et mis en fuite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 5, 'Qu’ils soient comme la poussière devant la face des vents; que l’ange du Seigneur les arrête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 6, 'Que leur voie soit glissante et ténébreuse; que l’ange du Seigneur les poursuive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 7, 'Parce que sans motif ils ont caché pour moi la mort dans un piège, et que sans motif ils ont fait des outrages à mon âme:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 8, 'Qu’un filet inconnu tombe sur eux; que les lacs qu’ils ont cachés les prennent; qu’ils trébuchent dans leurs propres pièges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 9, 'Et mon âme mettra sa joie dans le Seigneur; elle se délectera dans son salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 10, 'Tous mes os diront: Seigneur qui est semblable à vous? Vous sauvez l’indigent de mains plus fortes que lui; vous protégez le mendiant et le pauvre contre ceux qui le pillent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 11, 'De faux témoins se sont levés, et ils m’ont questionné sur ce que je ne savais pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 12, 'Ils me rendaient le mal pour le bien; ils ont desséché ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 13, 'Et moi, tandis qu’ils me tourmentaient, je me suis couvert d’un cilice; j’ai mortifié mon âme par le jeûne, et ma prière retournera en mon sein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 14, 'Je me complaisais en eux comme en un ami ou en mon frère; je m’étais humilié comme si j’eusse été dans le deuil et la tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 15, 'Et ils se réjouissaient contre moi, et ils s’assemblaient et réunissaient leurs forces contre moi, et je n’en savais rien; ils ont été dissipés, mais non contrits;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 16, 'Ils m’ont tenté; ils ont ricané avec grand mépris; ils ont grincé des dents sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 17, 'Seigneur, quand regarderez-vous vers moi? Sauvez mon âme de leur malice; délivrez des lions mon âme abandonnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 18, 'Je vous rendrai gloire en une église nombreuse; je vous louerai au milieu d’un grand peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 19, 'Que sois point la joie de ceux qui m’attaquent injustement, qui me haïssent sans raison et me regardent d’un œil méprisant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 20, 'Ils m’ont parlé pacifiquement; mais dans leur colère ils songeaient à me tromper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 21, 'Ils ont dilaté contre moi leur bouche, et ils ont dit: Bien, bien, nos yeux ont vu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 22, 'Vous aussi, Seigneur, vous avez vu; ne gardez pas le silence, Seigneur; ne vous éloignez pas de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 23, 'Levez-vous, Seigneur, appliquez-vous à mon jugement; mon Seigneur et mon Dieu, soyez attentif à ma cause.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 24, 'Jugez-moi, Seigneur, selon votre justice, mon Seigneur et mon Dieu, et qu’ils ne fassent pas de moi leur joie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 25, 'Qu’ils ne disent point en leur cœur: Bien, cela plaît à notre âme; qu’ils ne disent point: Nous l’avons dévoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 26, 'Que ceux qui se sont réjouis de mes maux soient confondus et honteux; que ceux qui ont parlé contre moi en se gonflant d’orgueil, soient enveloppés de crainte et de confusion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 27, 'Que ceux qui veulent ma justification soient dans la joie; qu’ils tressaillent d’allégresse; qu’ils ne cessent de dire: Dieu soit glorifié, et ceux qui désirent la paix de son serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 34, 28, 'Et ma langue célébrera votre justice; elle chantera chaque jour vos louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 1, 'L’injuste a dit en lui-même qu’il pècherait; il n’a point devant les yeux la crainte du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 2, 'Car il a agi frauduleusement en sa présence, au point que son iniquité lui a attiré sa haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 3, 'Les paroles de sa bouche sont fraude et iniquité; il n’a pas voulu comprendre pour faire le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 4, 'Sur sa couche, il a pensé au mal; il s’est arrêté en toute voie mauvaise; il n’a point haï la méchanceté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 5, 'Seigneur, votre miséricorde est au ciel, et votre vërité s’étend jusqu’aux nuages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 6, 'Votre justice est comme les montagnes de Dieu; vos jugements sont comme un abîme profond; Seigneur, vous sauverez les hommes et les bêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 7, 'Combien vous avez multiplié votre miséricorde, Ô mon Dieu! à l’ombre de vos ailes, les fils des hommes espèreront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 8, 'Ils s’enivreront de l’abondance de votre demeure; vous les abreuverez du torrent de vos délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 9, 'Car en vous est la fontaine de vie; et dans votre lumière nous verrons la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 10, 'Étendez votre miséricorde sur ceux qui vous connaissent, et votre justice sur les hommes au cœur droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 11, 'Que le pied de l’orgueil ne vienne point jusqu’à moi; que la main du pécheur ne m’ébranle jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 12, 'Là sont tombés les ouvriers d’iniquité; ils ont été repoussés, et ils n’ont pu se tenir debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 35, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 1, 'Ne cherche pas à imiter les méchants; ne porte pas envie à ceux qui font le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 2, 'Car, comme l’herbe des champs, ils seront bientôt flétris; comme la plante verte, ils ne tarderont pas à tomber.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 3, 'Espère au Seigneur et fais le bien; habite la terre, et tu seras nourri de ses richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 4, 'Délecte-toi dans le Seigneur, et il t’accordera ce que ton cœur aura demandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 5, 'Révèle au Seigneur ta voie; espère en lui, et il agira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 6, 'Il manifestera sa justice comme une lumière, et son jugement comme le midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 7, 'Soumets-toi au Seigneur, et prie-le; ne porte pas envie à celui qui prospère dans sa voie, à l’homme qui commet des injustices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 8, 'Calme ta colère, laisse tomber ton courroux; ne cherche pas à devenir méchant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 9, 'Car les méchants seront exterminés; mais ceux qui attendent le Seigneur auront la terre pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 10, 'Encore un peu de temps, et le pécheur ne sera plus; tu chercheras sa place, et tu ne la trouveras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 11, 'Mais les doux auront la terre pour héritage, et ils se délecteront dans la plénitude de la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 12, 'Le pécheur épiera le juste, et il grincera des dents contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 13, 'Et le Seigneur se rira de lui; car il voit que son jour approche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 14, 'Les pécheurs ont tiré l’épée; ils ont tendu leur arc pour abattre le pauvre et l’indigent, pour tuer ceux qui ont le cœur droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 15, 'Que leur glaive s’enfonce dans leur propre cœur, et que leur arc soit brisé!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 16, 'Mieux vaut la pauvreté du juste que les grandes richesses des pécheurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 17, 'Car les bras des pécheurs seront broyés, et le Seigneur affermit les justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 18, 'Le Seigneur connaît les voies des innocents, et leur héritage sera éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 19, 'Dans les temps de détresse, ils ne seront point confondus, et aux jours de famine ils seront rassasiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 20, 'Mais les pécheurs périront, et les ennemis de Dieu sont à peine parvenus aux honneurs et à la gloire qu’ils s’évanouissent comme une fumée qui se disperse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 21, 'Le pécheur emprunte, et il ne rendra pas; le juste a compassion, et il donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 22, 'Ceux qui bénissent le Seigneur auront la terre pour héritage; ceux qui le maudissent seront exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 23, 'Les pas de l’homme sont conduits par le Seigneur, qui se complaira dans sa voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 24, 'S’il tombe, il ne se brisera point; car le Seigneur le soutient de sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 25, 'J’ai été jeune et je suis devenu vieux, et je n’ai point vu le juste délaissé, ni ses enfants demander leur pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 26, 'Il est compatissant, et chaque jour il prête, et sa race sera bénie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 27, 'Détourne-toi du mal et fais le bien, et habite la terre dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 28, 'Car le Seigneur aime la justice, et il n’abandonnera jamais ses saints; il les prendra sous garde éternellement; les innocents seront vengés, et la race des impies sera détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 29, 'Les justes auront la terre pour héritage, et ils l’habiteront durant les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 30, 'La bouche du juste méditera la sagesse, et sa langue parlera la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 31, 'La loi de son Dieu est dans son cœur, et ses pas ne seront jamais chancelants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 32, 'Le pécheur épie le juste; il cherche à le faire périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 33, 'Mais le Seigneur ne le laissera pas en ses mains, et il ne le condamnera pas lorsqu’il sera jugé par le pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 34, 'Attends le Seigneur et garde sa voie, et il t’élèvera pour que tu hérites de la terre; et lorsque les pécheurs auront péri, tu verras!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 35, 'J’ai vu l’impie fier, exalté et élevé comme les cèdres du Liban:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 36, 'J’ai passé, et voilà qu’il n’était plus; et je l’ai cherché, et sa place n’a point été retrouvée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 37, 'Garde l’innocence, aie en vue la droiture; car il a une attente l’homme pacifique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 38, 'Mais les pervers seront exterminés tous à la fois; l’attente des impies, c’est la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 39, 'Le salut des justes vient du Seigneur; il est leur appui au temps de l’affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 36, 40, 'Et le Seigneur les soutiendra, et il les délivrera, et il les ravira aux pécheurs, et il les sauvera, parce qu’ils ont espéré en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 1, 'Seigneur, ne me réprimandez pas dans votre fureur; ne me châtiez pas dans votre colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 2, 'Car vos flèches m’ont transpercé, et vous avez appesanti sur moi votre main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 3, 'En ma chair il n’est plus rien de sain en face de votre colère; il n’est point de paix pour mes os en face de mes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 4, 'Car mes iniquités se sont accumulées plus haut que ma tête; elles me pèsent comme un lourd fardeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 5, 'Mes meurtrissures sont infectes et gangrenées à cause de ma folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 6, 'Je suis devenu misérable, entièrement courbé; j’ai marché tout le jour, plein de tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 7, 'Car mon âme a été remplie d’illusions, et il n’est rien de sain dans ma chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 8, 'J’ai été affligé et j’ai été humilié à l’excès; je rugissais à cause des gémissements de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 9, 'Tout mon désir est devant vous; mon gémissement ne vous est point caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 10, 'Mon cœur est troublé, ma force a défailli, et la lumière de mes yeux n’est point avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 11, 'Mes amis et mes proches se sont avancés et arrêtés contre moi, et ceux qui m’approchaient de plus près se sont tenus au loin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 12, 'Tandis que j’étais pressé avec violence par ceux qui cherchaient à m’ôter la vie, et que ceux qui pensaient à mal contre moi disaient des paroles menteuses, et tout le long du jour inventaient des tromperies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 13, 'Mais moi je ne les entendais non plus qu’un sourd, et comme un muet je n’ouvrais pas la bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 14, 'J’étais devenu semblable à un homme qui n’entend rien, et n’a rien à répliquer en sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 15, 'Car, ô Seigneur, j’espérais en vous, et vous m’exaucerez, Seigneur mon Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 16, 'Et j’ai dit: Que je ne sois point pour mes ennemis un sujet de joie, ceux qui parlaient orgueilleusement contre moi quand mes pieds étaient chancelants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 17, 'Car je suis prêt à être flagellé, et ma douleur m’est toujours présente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 18, 'Et je déclarerai mon iniquité; et je serai dans la douleur au sujet de mon péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 19, 'Cependant mes ennemis sont vivants, et ils se sont fortifiés contre moi, et le nombre de ceux qui me haïssent injustement s’est multiplié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 20, 'Ceux qui rendent le mal pour le bien m’ont calomnié, parce que je recherchais la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 21, 'Ne m’abandonnez pas, Seigneur mon Dieu, ne vous détournez point de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 22, 'Approchez-vous pour me secourir, ô Dieu de mon salut!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 37, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 1, 'J’ai dit: J’observerai mes voies pour ne point pécher de la langue. J’ai mis une garde à ma bouche, tandis que le pécheur se dressait contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 2, 'Je suis resté muet, je me suis humilié; je me suis abstenu même de bonnes paroles, et ma douleur s’en est accrue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 3, 'Mon cœur s’est échauffé en moi, et un feu s’allumera dans ma méditation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 4, 'J’ai dit de ma langue: Seigneur, faites-moi connaître ma fin et quel est le nombre de mes jours, pour que je sache ce qui me reste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 5, 'Voilà que vous avez envieilli mes jours, et ma substance est comme rien devant vous. En vérité, toutes choses, tout homme vivant ne sont que vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 6, 'Cependant l’homme passe comme une ombre, et il se trouble follement. Il thésaurise, et il ne sait pour qui il amassera ses trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 7, 'Et maintenant quelle est mon attente? N’est-ce pas le Seigneur? Et ma substance n’est-elle pas en vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 8, 'Retirez-moi de toutes mes iniquités, vous qui m’avez donné en opprobre à l’insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 9, 'Je suis resté muet, et je n’ai point ouvert la bouche; car c’est vous qui avez fait cela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 10, 'Détournez de moi vos plaies; car j’ai défailli sous la force de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 11, 'Vous avez châtié l’homme par vos réprimandes, à cause de son iniquité. Vous avez fait dessécher son âme comme la toile de l’araignée; toutefois l’homme se trouble follement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 12, 'Seigneur, écoutez ma prière et ma supplication; entendez mes larmes; ne gardez pas le silence, car je suis sur la terre un passager, un voyageur comme l’ont été tous mes pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 13, 'Épargnez-moi, afin que je respire avant de disparaître; et je ne serai plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 38, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 1, 'J’ai attendu le Seigneur dans une vive attente, et il a fait attention à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 2, 'Et il a exaucé mon oraison, et il m’a tiré du lac de misère et du bourbier fangeux; et il a établi mes pieds sur le roc, et il a dirigé mes pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 3, 'Et il a mis sur mes lèvres un nouveau cantique, un hymne à notre Dieu. Nombre d’hommes verront cela, et ils auront crainte; et ils espéreront en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 4, 'Heureux l’homme qui espère au nom du Seigneur, et qui n’a point eu de regards pour les vanités, ni pour de trompeuses folies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 5, 'Vous avez fait, Seigneur mon Dieu, beaucoup de choses merveilleuses; nul n’est semblable à vous en vos pensées; je les ai annoncées; j’en ai parlé, elles sont innombrables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 6, 'Vous n’avez voulu ni offrandes ni victimes; mais vous m’avez donné des oreilles; vous n’avez demandé ni holocaustes ni oblations pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 7, 'Alors j’ai dit: Voici que je viens. En tête du livre il est écrit de moi');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 8, 'Que je dois faire votre volonté, ô mon Dieu; c’est ce que j’ai résolu, et votre loi est au milieu de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 9, 'J’ai prêché votre justice en une grande église, et voilà que je ne retiendrai point mes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 10, 'Seigneur, vous connaissez ma justice; je n’ai point caché votre justice en mon cœur, et j’ai dit votre salut. Je n’ai point cité devant une assemblée nombreuse ni votre vérité ni votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 11, 'Vous donc, Seigneur, n’éloignez point de moi votre compassion; votre vérité et votre miséricorde m’ont toujours secouru.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 12, 'Car des maux innombrables m’ont environné, mes iniquités m’ont saisi, et je n’ai pu voir; elles se sont multipliées plus que les cheveux de ma tête, et mon cœur a défailli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 13, 'Seigneur, qu’il vous plaise de me sauver; Seigneur, regardez et secourez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 14, 'Que ceux qui cherchent ma vie pour la détruire soient tous ensemble confondus et frappés de crainte; que ceux qui me veulent mal tournent le dos et soient couverts de honte!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 15, 'Que ceux qui me crient: Ha! ha! soient aussitôt chargés de confusion!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 16, 'Que tous ceux qui vous cherchent, Seigneur, tressaillent et se réjouissent; que ceux qui aiment votre salut disent sans cesse: Que le Seigneur soit glorifié!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 17, 'Et moi je suis un mendiant et un pauvre; mais le Seigneur s’inquiètera de moi: ô mon Dieu, vous êtes mon aide et mon protecteur, ne tardez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 39, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 1, 'Heureux celui qui comprend le mendiant et le pauvre; aux jours mauvais Dieu le délivrera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 2, 'Que le Seigneur le garde et le fasse vivre; qu’il lui donne la félicité sur la terre; qu’il ne le livre pas aux mains de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 3, 'Que le Seigneur lui porte secours sur le lit de sa douleur, vous avez remué toute sa couche en son infirmité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 4, 'Pour moi, j’ai dit: Seigneur, ayez pitié de moi, guérissez mon âme; car j’ai péché contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 5, 'Mes ennemis ont mal parlé contre moi: Quand mourra-t-il? quand périra son nom?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 6, 'Si l’un d’eux entrait pour me voir, son cœur parlait faussement; il amassait en lui-même son iniquité; il sortait, et il parlait avec d’autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 7, 'Tous mes ennemis chuchotaient contre moi; ils tramaient ma perte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 8, 'Ils ont formé un dessein inique contre moi; mais celui qui est couché ne pourra-t-il ressusciter?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 9, 'Car l’homme de ma paix, en qui j’avais espéré, celui qui mangeait mon pain, a levé fièrement son talon sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 10, 'Mais vous, Seigneur, ayez pitié de moi et ressuscitez-moi, et je leur rendrai ce qu’ils méritent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 11, 'En cela j’ai connu que vous m’avez aimé; car mon ennemi ne se réjouira point de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 12, 'Vous m’avez protégé à cause de mon innocence; et vous m’avez établi devant vous pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 13, 'Béni soit le Seigneur, Dieu d’Israël, dans tous les siècles des siècles! Ainsi soit-il, ainsi soit-il!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 40, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 1, 'Comme le cerf désire les fontaines des eaux, ainsi mon âme vous désire, ô mon Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 2, 'Mon âme a eu soif du Dieu vivant; quand viendrai-je? quand paraîtrai-je devant la face de Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 3, 'Mes larmes ont été mon pain nuit et jour, parce que chaque jour on m’a dit: Où est ton Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 4, 'Je m’en suis souvenu, et j’ai épanché mon âme en moi-même; car je pénètrerai dans le merveilleux tabernacle, jusqu’à la maison de Dieu, parmi les chants d’action de grâces et d’allégresse de ceux qui prennent part à une fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 5, 'O mon âme, pourquoi es-tu triste, et pourquoi me troubles-tu? Espère en Dieu; car je lui rendrai grâces, à lui mon salut et mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 6, 'O mon Dieu! mon âme a été troublée en moi; aussi me souviendrai - je de vous sur la terre du Jourdain, et d’Hermonim, et de la petite montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 7, 'À la voix de vos cataractes, l’abîme appelle l’abîme. Toutes vos grandes vagues, tous vos flots ont passé sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 8, 'Le jour, le Seigneur commandera à sa miséricorde; la nuit, il la manifestera. Ma prière au Dieu de ma vie est en moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 9, 'Je dirai à Dieu: Vous êtes mon auxiliaire; pourquoi m’avez-vous oublié? D’où vient que je chemine tout abattu pendant que mon ennemi m’opprime?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 10, 'Pendant que mes os sont brisés, mes persécuteurs m’outragent en me disant chaque jour: Où est ton Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 11, 'O mon âme, pourquoi es-tu triste, et pourquoi me troubles-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 41, 12, 'Espère en Dieu; car je lui rendrai grâces, à lui le salut, à lui mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 42, 1, 'Jugez-moi, ô mon Dieu; séparez ma cause de celle d’une nation impie; sauvez-moi de l’homme inique et trompeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 42, 2, 'Car, ô mon Dieu, vous êtes ma force; pourquoi m’avez-vous repoussé? et d’où vient que je chemine tout abattu, quand mon ennemi m’opprime?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 42, 3, 'Envoyez-moi votre lumière et votre vérité; elles m’ont guidé, elles m’ont conduit sur votre montagne sainte et dans vos tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 42, 4, 'Et j’entrerai à l’autel de Dieu, vers le Dieu qui réjouit ma jeunesse. Je vous rendrai gloire sur la cithare, ô Dieu, ô mon Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 42, 5, 'O mon âme, pourquoi es-tu triste, et pourquoi me troubles-tu? Espère en Dieu; car je lui rendrai grâces, à lui le salut de ma face, à lui mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 42, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 1, 'O Dieu, nous l’avons ouï de nos oreilles; nos pères nous ont fait connaître l’œuvre que vous avez faite en leurs jours, aux jours antiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 2, 'Votre main a exterminé les nations; mais eux, vous les avez établis, et vous avez affligé les gentils, vous les avez chassés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 3, 'Car ce n’est point l’épée de nos pères qui les a mis en possession de notre héritage; ce n’est point leur bras qui les a sauvés; mais c’est votre droite et votre bras, et la lumière de votre face, parce que vous vous êtes complu en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 4, 'Vous êtes vous-même mon roi et mon Dieu; vous avez ordonné le salut de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 5, 'Par vous, nous aurons la force de soulever nos ennemis, et en votre nom nous mépriserons ceux qui se lèvent contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 6, 'Car je n’espérerai point en mon arc, et ce n’est pas mon glaive qui me sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 7, 'C’est vous qui nous avez déjà sauvés de nos persécuteurs, et ceux qui nous haïssaient, vous les avez confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 8, 'En Dieu nous serons loués tout le jour, et nous rendrons grâces à son nom éternellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 9, 'Mais maintenant vous nous avez repoussés et confondus, et vous ne sortirez plus avec nos armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 10, 'Vous nous avez tourné le dos devant nos ennemis, et ceux qui nous haïssent nous ont pillés à leur profit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 11, 'Vous nous avez livrés comme des brebis bonnes à manger; vous nous avez dispersés parmi les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 12, 'Vous leur avez vendu pour rien votre peuple, et il n’y a pas eu foule pour l’acheter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 13, 'Vous avez fait de nous l’opprobre de nos voisins, la risée et la raillerie de ceux qui nous entourent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 14, 'Vous avez fait de nous la fable des gentils; sur nous les peuples secouent la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 15, 'J’ai tout le jour ma honte devant moi, et la confusion de ma face m’a couvert,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 16, 'À la voix de celui qui m’injurie et m’outrage, à la face de mon ennemi et de mon persécuteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 17, 'Toutes ces choses sont venues sur nous; mais nous ne vous avons point oublié; nous n’avons point violé votre alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 18, 'Notre cœur ne s’est pas éloigné; mais vous avez détourné nos sentiers de votre voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 19, 'Car vous nous avez humiliés en un lieu d’affliction, et l’ombre de la mort nous a enveloppés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 20, 'Si nous avions oublié le nom de notre Dieu, si nous avions étendu les mains vers des dieux étrangers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 21, 'Dieu ne rechercherait-il pas ces choses? Car seul il connaît les secrets des cœurs. À cause de vous nous mourons tout le jour; nous sommes comptés comme les brebis du sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 22, 'Réveillez-vous; pourquoi dormez-vous, Seigneur? Levez-vous, et ne nous repoussez pas jusqu’à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 23, 'Pourquoi détournez-vous votre face? Avez-vous oublié notre pauvreté et notre affliction?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 24, 'Car notre âme est abaissée jusqu’à la poussière, et notre ventre est collé sur le sol.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 25, 'Levez-vous, Seigneur; venez à notre secours, et délivrez-nous pour la gloire de votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 43, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 1, 'Mon cœur a exhalé une bonne parole; je dédie mes œuvres au Roi. Ma langue est le roseau d’un scribe écrivant avec rapidité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 2, 'Tu es plus beau que les fils des hommes; la grâce est répandue sur tes lèvres. À cause de cela, Dieu t’a béni à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 3, 'Ceins l’épée qui s’appuie sur ta cuisse, ô Puissant!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 4, 'En ta jeunesse et en ta beauté, tends ton arc, marche et prospère, et règne par l’amour de la vérité, de la douceur et de la justice, et ta droite te guidera merveilleusement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 5, 'Tes traits sont aiguisés, ô Puissant; ils renverseront les peuples; ils perceront le cœur des ennemis du Roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 6, 'Ton trône, ô mon Dieu, sera dans les siècles des siècles; ton sceptre de roi est le sceptre de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 7, 'Tu aimes la justice et tu hais l’iniquité; à cause de cela, ô Dieu, ton Dieu a fait de toi son Christ; il a répandu sur toi plus que sur tes compagnons l’huile de l’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 8, 'La myrrhe, les essences et la casse s’exhalent de tes vêtements et de tes palais d’ivoire, et, réunies en ton honneur, elles te réjouissent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 9, 'Les filles des rois. La reine s’est placée à ta droite, revêtue d’un manteau d’or diversement orné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 10, 'Écoute, ma fille, et vois, et incline ton oreille; oublie ton peuple et la maison de ton père;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 11, 'Car le roi s’est épris de ta beauté, lui qui est ton seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 12, 'Et les filles de Tyr t’adoreront avec des présents; les riches du peuple de la terre prieront devant ta face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 13, 'Toute sa gloire est comme celle de la fille du roi d’Esebon, revêtue d’une parure de franges d’or,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 14, 'Et diversement ornée. Les vierges de sa suite amenées au roi; ses compagnes te seront amenées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 15, 'Elles te seront amenées avec joie et allégresse; elles seront conduites en la demeure du Roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 16, 'À la place de tes frères, des fils te sont nés; tu les institueras chefs de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 17, 'Ils se souviendront de ton nom de génération en génération; à cause de cela, les peuples te rendront grâces éternellement et dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 44, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 1, 'O Dieu, notre force et notre refuge, vous êtes notre auxiliaire dans les afflictions qui nous ont violemment assaillis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 2, 'Aussi nous ne craindrions pas, quand même la terre serait bouleversée, quand même les montagnes seraient transportées au sein des mers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 3, 'Leurs eaux ont retenti, et elles ont été troublées; les montagnes ont été ébranlées par sa force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 4, 'L’eau courante du fleuve réjouit la cité de Dieu; le Très-Haut a sanctifié son tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 5, 'Dieu est au milieu de sa cité, elle ne sera point ébranlée; Dieu la défendra par sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 6, 'Les nations ont été troublées, les royaumes ont chancelé; il a élevé la voix, et la terre a tremblé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 7, 'Le Dieu des armées est avec nous; le Dieu de Jacob est notre refuge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 8, 'Venez, et voyez les œuvres du Seigneur, les prodiges qu’il a faits sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 9, 'Mettant fin à la guerre jusqu’aux limites de la terre, il brisera l’arc, il broiera l’armure, il brûlera les boucliers dans le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 10, 'Restez en paix, et voyez que je suis Dieu. Je serai glorifié parmi les nations; je serai exalté sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 11, 'Le Seigneur des armées est avec nous; le Dieu de Jacob est notre refuge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 45, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 1, 'Pour la fin, psaume pour les fils de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 2, 'Nations, battez toutes des mains, chantez à Dieu d’une voix pleine d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 3, 'Car le Seigneur est élevé; il est terrible: c’est le grand Roi de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 4, 'Il nous a assujetti les peuples, et mis les gentils sous nos pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 5, 'Il nous a choisis pour son héritage, nous, la beauté de Jacob, qu’il aime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 6, 'Dieu est monté au milieu de la joie; le Seigneur, au son de la trompette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 7, 'Chantez à notre Dieu; chantez à notre Roi, chantez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 8, 'Et puisque Dieu est le roi de toute la terre, chantez avec intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 9, 'Dieu règne sur les nations; Dieu est assis sur le trône de sa sainteté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 46, 10, 'Les princes des peuples se sont réunis avec le Dieu d’Abraham; car les puissants de la terre ont été élevés par Dieu bien au-dessus des autres hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 1, 'Psaume chanté par les fils de Coré, le second jour de la semaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 2, 'Le Seigneur est grand et digne de toute louange en la ville de notre Dieu, sur sa montagne sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 3, 'Elle est profondément enracinée aux cris de joie de toute la terre, la montagne de Sion; la ville du grand Roi est bâtie sur le côté qui regarde l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 4, 'Dieu est connu dans ses palais, lorsqu’il la défend.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 5, 'Car voilà que les rois de la terre se sont rassemblés; ils sont venus en un même lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 6, 'Mais l’ayant vu, ils ont été si émerveillés, qu’ils se sont troublés et ont été ébranlés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 7, 'L’effroi les a saisis, et ils ont éprouvé comme les douleurs de l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 8, 'D’un coup de vent impétueux vous briserez les vaisseaux de Tharsis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 9, 'Ce que nous avions ouï, ainsi nous l’avons vu en la ville du Seigneur des armées, en la cité de notre Dieu. Dieu l’a fondée pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 10, 'O Dieu, nous avons reçu votre miséricorde au milieu de votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 11, 'Comme votre nom, ô Dieu, votre louange va jusqu’aux confins de la terre; votre droite est pleine de justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 12, 'Que la montagne de Sion se réjouisse; que les filles de Juda tressaillent à cause de vos jugements, ô Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 13, 'Entourez Sion, embrassez-la; discourez au sujet de ses tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 14, 'Mettez vos cœurs dans sa force, et distribuez ses demeures, afin que vous racontiez ces choses à une autre génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 47, 15, 'Car c’est notre Dieu dans le siècle présent et dans tous les siècles à venir; et il sera notre pasteur dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 1, 'Nations, écoutez toutes ces choses; prêtez une oreille attentive, ô vous tous qui peuplez la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 2, 'Fils de la terre, fils des hommes, riches ou pauvres, réunis au même lieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 3, 'Ma bouche vous dira la sagesse, et la méditation de mon cœur, l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 4, 'J’inclinerai mon oreille vers la parabole; j’expliquerai ce que j’avance au son de la harpe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 5, 'Pourquoi craindrais-je dans les mauvais jours? C’est que l’iniquité de mes démarches m’assiégera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 6, 'Ceux qui se fient en leur force et se glorifient de l’abondance de leurs richesses, qu’ils écoutent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 7, 'Si le frère ne rachète pas son frère, un autre homme le rachètera-t-il? Non, et il ne donnera pas à Dieu la rançon de lui-même,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 8, 'Ni le prix de la rédemption de son âme. Travaillerat-il éternellement,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 9, 'Et vivra-t-il sans fin?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 10, 'Ne verra-t-il pas la mort, lorsqu’il aura vu mourir les sages comme le stupide et l’insensé mourront? Et ils laisseront leurs richesses à des étrangers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 11, 'Et le sépulcre sera pour toujours leur demeure; dans les générations des générations ils n’auront point d’autre abri, et ils auront donné leurs noms à leurs terres!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 12, 'Et l’homme élevé en honneur ne l’a pas compris; il est devenu comme les bêtes sans raison, et il s’est rendu semblable à elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 13, 'Pour ceux-là, leur propre voie est un piége; et après cela des gens vanteront ce qu’a dit leur bouche!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 14, 'Ils sont parqués en enfer comme des brebis; la mort s’en repaîtra, et au matin les justes auront pouvoir sur eux; et l’appui qu’ils se faisaient de leur gloire vieillira en enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 15, 'Cependant Dieu rachètera mon âme de la main de l’enfer, lorsqu’il m’aura reçu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 16, 'Ne crains point quand un homme se sera enrichi, et que la gloire de sa maison se sera multipliée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 17, 'Car, lorsqu’il mourra, il n’emportera rien, et sa gloire ne descendra pas avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 18, 'Son âme aura été bénie en sa vie; et il t’aura rendu grâces, lorsque tu lui auras fait du bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 19, 'Il s’en ira où sont les générations de ses pères; et la lumière, il ne la reverra jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 20, 'L’homme élevé en honneurs ne l’a pas compris; il est devenu comme les bêtes sans raison, et il s’est rendu semblable à elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 48, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 1, 'Le Dieu des dieux, le Seigneur a parlé, et il a appelé la terre depuis l’Orient jusqu’à l’Occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 2, 'De Sion vient la splendeur de sa beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 3, 'Dieu, notre Dieu viendra manifestement, et ne gardera pas le silence; un feu sera allumé en sa présence, et tout alentour un vent impétueux soufflera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 4, 'Il convoquera le ciel et la terre, pour juger son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 5, 'Amenez-lui ses saints, ceux qui ont fait alliance avec lui, pour les sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 6, 'Et les cieux annonceront sa justice; car Dieu est le juge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 7, 'Écoute, mon peuple, et je parlerai; Israël, je te l’atteste je suis Dieu, je suis ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 8, 'Je ne te réprimanderai point sur tes sacrifices; car tes holocaustes sont toujours devant mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 9, 'Je ne prendrai pas de bœufs de ta maison, ni de boucs de tes menus troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 10, 'Car toutes les bêtes de la forêt m’appartiennent, et le bétail des montagnes et les taureaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 11, 'Je connais tous les oiseaux du ciel, et la beauté des champs est à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 12, 'Si j’ai faim, je ne te le dis pas; car toute la terre habitée m’appartient et sa plénitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 13, 'Est-ce que je mange la chair des taureaux? est-ce que je bois le sang des boucs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 14, 'Immole à Dieu une victime de louanges; rends au Tout-Puissant tes vœux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 15, 'Invoque-moi au jour de l’affliction, et je te sauverai, et tu me rendras grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 16, 'Mais Dieu a dit au pécheur: Pourquoi publies-tu mes justices et as-tu mon alliance à la bouche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 17, 'Quand tu n’aimes point ma discipline, et que tu as rejeté loin de toi ma parole?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 18, 'Si tu voyais un larron, tu courais avec lui; tu avais ta part avec les adultères;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 19, 'Ta bouche abondait en méchanceté, et ta langue tramait la fraude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 20, 'Assis, tu médisais de ton frère; tu scandalisais le fils de ta mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 21, 'Voilà ce que tu faisais, et j’ai gardé le silence; mais tu t’imaginais faussement que je serais semblable à toi. Je te convaincrai, et je mettrai tes offenses devant ta face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 22, 'Comprenez donc ces choses, vous qui oubliez Dieu; de peur qu’un jour il ne vous ravisse, et que nul ne vous délivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 49, 23, 'C’est un sacrifice de louange qui m’honore, et la voie où je montrerai le salut de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 1, 'Pour être chanté, psaume de David,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 2, 'Quand le prophète Nathan le vint trouver, parce qu’il avait eu commerce avec Bersabée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 3, 'Ayez pitié de moi, Seigneur, selon votre grande miséricorde; et selon l’immensité de votre compassion, effacez mon iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 4, 'Lavez-moi de plus en plus de mon crime, et purifiez-moi de mon péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 5, 'Car je connais mon iniquité, et mon péché est toujours devant ma face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 6, 'C’est contre vous seul que j’ai péché, et devant vous que j’ai fait le mal; vous l’avez permis, afin que vous soyez reconnu juste dans vos paroles et que vous triomphiez dans vos jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 7, 'Car voilà que j’ai été conçu dans l’iniquité, et ma mère m’a conçu dans le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 8, 'Mais vous, vous aimez la vérité, et vous m’avez révélé les choses obscures et profondes de votre sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 9, 'Vous m’aspergerez avec l’hysope, et je serai purifié; vous me laverez, et je serai plus blanc que la neige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 10, 'Vous me ferez entendre la joie et l’allégresse, et mes os affligés se réjouiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 11, 'Détournez votre face de tous mes péchés, et effacez toutes mes iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 12, 'Créez en moi un cœur pur, ô mon Dieu, et rétablissez un esprit droit en mes entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 13, 'Ne me rejetez pas de votre présence, et ne retirez pas de moi votre Esprit-Saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 14, 'Rendez-moi la joie de votre salut, et raffermissez-moi en me donnant l’Esprit de force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 15, 'J’enseignerai vos voies aux méchants, et les impies se convertiront à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 16, 'Lavez-moi du sang versé, ô Dieu, Dieu de mon salut, et ma langue se réjouira de votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 17, 'Seigneur, vous ouvrirez mes lèvres, et ma bouche proclamera vos louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 18, 'Car si vous aviez voulu un sacrifice, je vous l’aurais offert; mais les holocaustes ne vous sont point agréables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 19, 'Le sacrifice qui plaît à Dieu est un esprit contrit; Dieu ne méprisera pas un cœur contrit et humilié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 20, 'Seigneur, faites en votre bonté, pour Sion, que les remparts de Jérusalem soient édifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 50, 21, 'Alors vous agréerez un sacrifice de justice, des oblations et des holocaustes; alors on offrira des veaux sur votre autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 1, 'Pour la fin; instruction pour David,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 2, 'Quand Doeg l’Iduméen alla porter un message à Saül, et lui dit: David est entré dans la maison d’Abimélech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 3, 'Qu’as-tu à t’enorgueillir dans ta malice, homme puissant en iniquité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 4, 'Ta langue tous les jours a tramé l’injustice; tu t’es servi de la fraude comme d’un rasoir tranchant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 5, 'Tu as préféré la malice à la bonté; tu as dit: L’iniquité plutôt que la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 6, 'Tu as préféré les paroles de ruine, ô langue trompeuse!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 7, 'À cause de cela, Dieu à la fin te détruira; il t’arrachera et te chassera de ta demeure, et extirpera ta racine de la terre des vivants..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 8, 'Et les justes le verront, et ils en seront effrayés, et ils riront de toi, et diront:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 9, 'Voilà un homme qui n’avait point pris Dieu pour auxiliaire, mais qui avait mis son espoir en l’abondance de ses richesses, et qui s’était cru fort en sa vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 10, 'Pour moi, comme un olivier fertile en la maison de Dieu, j’ai espéré en la miséricorde de Dieu, à jamais et dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 51, 11, 'Je vous rendrai grâces éternellement, à cause de vos œuvres, et j’attendrai votre nom, parce qu’il est bon pour vos saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 52, 1, 'L’insensé a dit en son cœur: Il n’y a point de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 52, 2, 'Ils se sont corrompus; ils sont devenus abominables en iniquités, et il n’en est pas qui fasse le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 52, 3, 'Dieu, du haut du ciel, s’est penché vers les fils des hommes, pour voir s’il en est qui comprenne ou cherche Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 52, 4, 'Tous ont dévié, et en même temps ils sont devenus inutiles; il n’en est pas qui fasse le bien, pas un seul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 52, 5, 'Nul ne sera-t-il instruit parmi ces ouvriers d’iniquité qui dévorent mon peuple comme du pain?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 52, 6, 'Ils n’ont point invoqué Dieu, et ils ont tremblé de peur là où il n’y avait rien à craindre. Mais Dieu a dispersé les os de ceux qui ne veulent plaire qu’aux hommes. Ils ont été confondus, parce que Dieu les a anéantis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 52, 7, 'Qui fera sortir de Sion le salut d’Israël? Quand le Seigneur aura ramené son peuple de la captivité, Jacob tressaillira d’allégresse, et Israël sera dans la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 1, 'Pour la fin, parmi les hymnes, instruction de David,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 2, 'Quand ceux de Ziph entrèrent, et dirent à Saül: N’as-tu pas vu où David est caché parmi nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 3, 'O Dieu, sauvez-moi par votre nom, et jugez-moi par votre puissance!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 4, 'Dieu, écoutez ma prière; soyez attentif aux paroles de ma bouche!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 5, 'Car des étrangers se sont élevés contre moi, et des hommes puissants en veulent à ma vie; ils n’ont point eu le Seigneur devant les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 6, 'Et voilà que Dieu me vient en aide, et le Seigneur est le sauveur de mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 7, 'Il fera retomber le mal sur ses ennemis; détruisez-les dans votre vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 8, 'Je vous ferai un sacrifice volontaire; je rendrai grâces à votre nom, Seigneur, parce que cela est bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 53, 9, 'Car c’est vous qui m’avez délivré de toutes mes tribulations, et mon œil a regardé de haut tous mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 1, 'Pour la fin, parmi les hymnes, instruction de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 2, 'Ô Dieu, écoutez ma prière, et ne méprisez pas ma supplication.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 3, 'Soyez attentif, et exaucez-moi; j’ai été contristé dans ma méditation, et j’ai été troublé');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 4, 'Par la voix de l’ennemi et la persécution du pécheur; car ils avaient tourné contre moi leur iniquité, et ils étaient pleins de colère contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 5, 'Mon cœur en moi a été troublé, et la terreur de la mort est tombée sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 6, 'La crainte et le tremblement m’ont saisi, et les ténèbres m’ont enveloppé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 7, 'Et j’ai dit: Qui me donnera des ailes, comme à la colombe? Je m’envolerai et je me reposerai');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 8, 'Voilà que j’ai fui au loin, et j’ai demeuré dans la solitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 9, 'J’attendais celui qui pouvait me sauver des défaillances de mon âme et de la tempête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 10, 'Submergez-les, Seigneur, et divisez leurs langues; car j’ai vu l’iniquité et la contradiction dans la cité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 11, 'Jour et nuit l’iniquité assiégera ses remparts; il y aura l’iniquité, la douleur et l’injustice au milieu d’elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 12, 'L’usure et la fraude ne quittent pas ses places publiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 13, 'Si un ennemi m’avait outragé, je l’aurais souffert; et si celui qui me hait avait parlé contre moi avec jactance, je me serais caché de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 14, 'Mais toi, homme de mon cœur, mon guide, mon familier, toi qui goûtais avec moi des plus doux mets,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 15, 'Avec qui j’étais de même cœur dans le temple du Seigneur!...');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 16, 'Que la mort vienne sur eux, qu’ils descendent vivants en enfer; car la méchanceté est dans leurs demeures, au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 17, 'Pour moi, j’ai crié vers Dieu, et le Seigneur m’a exaucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 18, 'Le matin, à midi, le soir, je lui raconterai mes peines; je les lui ferai connaître, et il entendra ma voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 19, 'Il rachètera en paix mon âme de ceux qui m’ont approché; car ils étaient en grand nombre contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 20, 'Dieu m’exaucera, et il les humiliera, lui qui est avant tous les siècles; car il n’y a point en eux de changement, et ils n’ont jamais eu la crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 21, 'Il a étendu la main pour les rétribuer; ils avaient souillé son alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 22, 'Ils ont été dispersés par la colère de sa face; puis son cœur s’est rapproché: leurs paroles avaient été plus douces que l’huile, et elles sont des dards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 23, 'Confie au Seigneur toutes tes inquiétudes, et lui-même te nourrira; il ne laissera pas le juste en une perpétuelle fluctuation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 54, 24, 'Et vous, mon Dieu, vous les ferez tomber dans le puits de perdition; les hommes de sang et de fraude n’arriveront pas à la moitié de leurs jours; pour moi, je mettrai mon espérance en vous, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 1, 'Pour la fin, pour le peuple, quand il fut éloigné des saints lieux, inscription de David, lorsque les Philistins l’eurent maîtrisé dans Geth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 2, 'Ayez pitié de moi, ô Dieu, car l’homme m’a foulé aux pieds; tout le jour, il a bataillé contre moi, et il m’a accablé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 3, 'Mes ennemis m’ont foulé aux pieds tout le jour, à partir de l’aurore; ils étaient nombreux à me combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 4, 'Mais ils sentiront la crainte, et moi j’espèrerai en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 5, 'En Dieu je louerai mes paroles; tout le jour j’ai espéré en Dieu; je ne craindrai rien de ce que la chair fera contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 6, 'Tout le long du jour ils ont eu en mépris mes discours; toutes leurs pensées tendaient à me nuire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 7, 'Ils s’établiront auprès de moi, s’embusqueront et guetteront mes pieds, comme ils ont cherché la perte de mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 8, 'Vous ne les sauverez pas; vous briserez les peuples en votre colère, ô mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 9, 'Je vous ai dévoilé ma vie; vous avez mis devant vous mes larmes, selon votre promesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 10, 'Mes ennemis tourneront le dos, quel que soit le jour où je vous invoque; voilà comment je reconnais que vous êtes mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 11, 'En Dieu je louerai la parole; en Dieu je louerai les discours: j’ai espéré en Dieu, je ne craindrai rien de ce que l’homme fera contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 12, 'En moi sont les vœux de louange que je vous rendrai, ô Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 13, 'Car vous avez délivré mon âme de la mort et mes pieds de la chute, afin que je sois agréable aux yeux de Dieu dans la lumière des vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 55, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 1, 'Pour la fin, avec cette inscription de David: Ne détruisez pas; lorsqu’il se réfugia dans la caverne pour se soustraire aux recherches de Saul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 2, 'Ayez pitié de moi, ô mon Dieu, ayez pitié de moi, car mon âme s’est confiée en vous; j’espérerai à l’ombre de vos ailes, jusqu’à ce que l’iniquité soit passée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 3, 'Je crierai vers le Seigneur très-haut, vers Dieu mon bienfaiteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 4, 'Il a envoyé son secours du ciel, et il m’a sauvé; il a livré aux outrages ceux qui me foulaient aux pieds; Dieu m’a envoyé sa miséricorde et sa vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 5, 'Il a tiré mon âme du milieu des lionceaux. J’ai dormi au milieu du trouble. Les fils des hommes ont leurs dents pour armes et pour traits, et leur langue est un glaive aiguisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 6, 'O Dieu, soyez exalté au-dessus des cieux, et que votre gloire soit sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 7, 'Ils avaient préparé des pièges sur mon passage, et ils avaient fait fléchir mon âme; ils avaient creusé devant mes pas une fosse, et ils y sont tombés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 8, 'Mon cœur est prêt, ô mon Dieu, mon cœur est prêt; je chanterai, je chanterai des psaumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 9, 'Réveille-toi, ô ma gloire; réveillez-vous, ma harpe et ma cithare; je m’éveillerai dès l’aurore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 10, 'Seigneur, je vous confesserai parmi les peuples; je vous chanterai parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 11, 'Car votre miséricorde s’élève jusque au-dessus des cieux, et votre vérité jusqu’aux nues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 56, 12, 'O Dieu, soyez exalté au-dessus des cieux, et que votre gloire soit sur toute la terre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 1, 'Pour la fin, avec cette inscription de David: Ne détruisez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 2, 'O fils des hommes, si vous parlez sincèrement de la justice, jugez donc avec droiture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 3, 'Car vous faites en votre cœur des iniquités sur la terre, et vos mains trament l’injustice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 4, 'Dès le sein de leur mère, les pécheurs ont dévié; à peine hors de ses entrailles, ils se sont égarés; ils ont dit des mensonges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 5, 'Leur colère est comme le venin du serpent, ou du sourd aspic, dont les oreilles sont bouchées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 6, 'Qui n’entendra point la voix des enchanteurs, et résistera aux charmes les plus subtils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 7, 'Dieu leur a brisé les dents dans la bouche; le Seigneur a broyé la mâchoire des lions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 8, 'Ils s’écouleront comme un flot qui passe; le Seigneur tiendra son arc tendu contre eux, jusqu’à ce qu’ils aient péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 9, 'Ils seront réduits à rien, comme la cire qui se fond; le feu est tombé sur eux, ils n’ont plus vu le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 10, 'Avant que vos épines approchent de la hauteur d’un arbrisseau, le Seigneur vous dévorera même pleins de vie, dans l’excès de sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 11, 'Le juste se réjouira, lorsqu’il verra la punition des impies; il se lavera les mains dans le sang des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 57, 12, 'Et l’on dira: Puisqu’il y a des fruits pour les justes, il est donc un Dieu qui les juge sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 1, 'Pour la fin, avec cette inscription de David: Ne détruisez pas; quand Saul envoya et fit garder sa maison pour le mettre à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 2, 'O Dieu, délivrez-moi de mes ennemis; délivrez-moi de ceux qui s’élèvent contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 3, 'Délivrez-moi des ouvriers d’iniquité, et sauvez-moi des hommes de sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 4, 'Car voilà qu’ils ont fait la chasse à mon âme; des hommes puissants se sont jetés sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 5, 'Ce n’est ni mon iniquité ni mon péché, Seigneur, qui en sont la cause: exempt d’iniquité, j’ai couru droit devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 6, 'Réveillez-vous, venez à mon aide, et voyez, Seigneur, Dieu des vertus, Dieu d’Israël; soyez attentif à visiter les nations; n’ayez aucune pitié pour ceux qui commettent l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 7, 'Ils viendront sur le soir, et ils seront affamés comme des chiens, et ils courront autour de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 8, 'Voilà qu’ils vocifèreront, et ils auront une épée sur les lèvres Qui nous entend? s’écrieront-ils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 9, 'Et vous, Seigneur, vous rirez d’eux; vous réduirez toutes les nations à néant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 10, 'Je garderai ma force en vous; car, ô mon Dieu, vous êtes mon défenseur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 11, 'Quant à mon Dieu, sa miséricorde me préviendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 12, 'Dieu me montrera sa vengeance sur mes ennemis. Ne les faites pas mourir, de peur que votre peuple n’en perde la mémoire. Dispersez-les en votre puissance, et renversez-les, Dieu mon protecteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 13, 'Châtiez le péché de leur bouche, les paroles de leurs lèvres; qu’ils soient punis dans leur orgueil; et l’on s’entretiendra de leurs malédictions, de leurs mensonges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 14, 'Détruisez-les, détruisez-les en votre colère; et ils ne subsisteront plus; et l’on saura que le Dieu de Jacob règne jusqu’aux confins de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 15, 'Ils reviendront sur le soir; ils seront affamés comme des chiens, et ils courront autour de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 16, 'Ils se disperseront pour manger; et s’ils ne sont point rassasiés, ils murmureront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 17, 'Pour moi, je chanterai votre puissance, et, dès l’aurore, je me réjouirai de votre miséricorde; car vous êtes mon défenseur et mon refuge au jour de mon affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 18, 'Je vous chanterai mes psaumes, ô mon Sauveur, ô mon Dieu; vous êtes mon défenseur, mon Dieu et ma miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 58, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 1, 'Pour la fin, pour ceux qui seront transformés, avec cette inscription de David: Instruction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 2, 'Lorsqu’il incendia la Mésopotamie syrienne et la Syrie de Sobal, et que Joab revint, et qu’il tailla en pièces douze mille hommes dans le val des salines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 3, 'Ô Dieu, vous nous avez repoussés, vous nous avez détruits, vous vous êtes mis en colère; puis vous avez eu pitié de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 4, 'Vous avez ébranlé la terre, et vous l’avez troublée; guérissez ses meurtrissures, car elle a tremblé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 5, 'Vous avez montré votre sévérité à votre peuple; vous nous avez fait boire le vin de la componction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 6, 'Vous avez donné un signe à ceux qui vous craignent pour qu’ils échappent aux atteintes de l’arc. Afin que vos bien-aimés soient délivrés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 7, 'Sauvez-moi par votre droite, et exaucez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 8, 'Dieu a parlé en son saint temple; je me réjouirai, et je partagerai Sichem, et je mesurerai le val des Tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 9, 'À moi est Galaad, à moi Manassé; Éphraïm est l’appui de ma tête, Juda est mon roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 10, 'Et Moab, le vase de mon espérance; je poserai ma sandale sur l’Idumée; les étrangers me sont soumis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 11, 'Qui me ramènera dans la ville forte? Qui me guidera jusqu’à la terre d’Édom?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 12, 'N’est-ce pas vous, qui nous aviez repoussés, ô Dieu, qui ne sortirez plus à la tête de nos armées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 13, 'Donnez-nous votre secours pour nous tirer de nos tribulations; car il est vain le salut qui vient de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 59, 14, 'En Dieu nous mettrons notre force, et lui-même réduira à néant nos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 1, 'Pour la fin, parmi les hymnes de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 2, 'Dieu, écoutez ma demande, soyez attentif à ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 3, 'Des derniers confins de la terre j’ai crié vers vous, lorsque j’étais dans l’angoisse; vous m’avez élevé sur le rocher, vous m’avez dirigé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 4, 'Parce que vous étiez mon espérance, et comme une tour armée contre mon ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 5, 'Je demeurerai éternellement dans votre tabernacle; je m’abriterai sous l’ombre de vos ailes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 6, 'Car, ô mon Dieu, vous avez exaucé mes prières; vous avez doté d’un héritage ceux qui craignent votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 7, 'Vous ajouterez des jours aux jours du Roi; vous prolongerez ses années jusqu’aux générations des générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 8, 'Il restera durant les siècles en présence de Dieu; qui pourra sonder sa miséricorde et sa vérité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 60, 9, 'Ainsi je chanterai à votre nom dans les siècles des siècles, pour vous rendre mes vœux de jour en jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 1, 'Pour la fin, pour Idithun, psaume de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 2, 'Mon âme n’est-elle pas soumise à Dieu, puisque mon salut vient de lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 3, 'C’est lui qui est mon Dieu, mon Sauveur, mon auxiliaire; je ne serai plus ébranlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 4, 'Jusques à quand vous attaquerez-vous à un homme? Vous réunirez-vous tous pour le tuer? Le traiterez-vous comme un mur qui penche, ou une muraille qui s’écroule?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 5, 'Cependant ils ont résolu d’anéantir mon honneur; j’ai couru, dévoré par la soif. Ils m’avaient béni de la bouche, et ils me maudissaient en leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 6, 'Mais, ô mon âme, reste soumise à Dieu; ma patience vient de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 7, 'Car il est mon Dieu, mon Sauveur, mon auxiliaire, et je ne serai point exilé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 8, 'Ma gloire et mon salut sont en Dieu; Dieu est mon aide, et mon espérance est en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 9, 'Espérez en lui, ô assemblée du peuple, épanchez devant lui vos cœurs; car Dieu est notre protecteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 10, 'Mais les fils des hommes sont vains, les fils des hommes ont de fausses balances pour tromper les hommes tous ensemble dans leur vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 11, 'N’espérez rien de l’injustice, ne convoitez pas de biens mal acquis; si vous regorgez de richesses, n’y attachez point votre cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 12, 'Dieu a parlé une fois, et j’ai ouï ces deux choses: que la puissance est de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 61, 13, 'Et que la miséricorde est à vous, Seigneur; car Vous rétribuerez chacun selon ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 1, 'Psaume de David, quand il était dans l’Idumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 2, 'Ô Dieu, ô mon Dieu, je veille pour vous dès l’aurore; mon âme a soif de vous; avec quelle ardeur ma chair vous désire!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 3, 'Sur une terre déserte, sans chemin et sans eau, je me tiens devant vous, comme dans votre sanctuaire, pour contempler votre puissance et votre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 4, 'Votre miséricorde est préférable à toutes les vies, aussi mes lèvres vous loueront-elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 5, 'Je vous bénirai tant que durera ma vie; j’élèverai les mains en votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 6, 'Que mon âme soit remplie de moelle et de graisse, et que mes lèvres joyeuses chantent votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 7, 'Je me suis souvenu de vous sur ma couche; dès l’aurore, je méditais sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 8, 'Car vous avez été mon auxiliaire, et à l’ombre de vos ailes je tressaillirai de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 9, 'Mon âme s’est attachée à vous suivre, et votre droite m’a soutenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 10, 'Vainement ils ont cherché mon âme; ils seront précipités dans les entrailles de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 11, 'Ils seront livrés à la violence du glaive; ils seront la proie des renards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 62, 12, 'Cependant le roi se réjouira en Dieu; quiconque jure en lui sera loué, parce qu’il aura fermé la bouche de ceux qui proféraient l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 1, 'Pour être chanté, psaume de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 2, 'Ô Dieu, exaucez ma prière pendant que je m’adresse à vous; délivrez mon âme de la crainte de l’ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 3, 'Vous m’avez protégé contre la troupe des méchants, contre la multitude des ouvriers d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 4, 'Ils ont aiguisé leurs langues comme des épées; ils ont tendu leur arc, qui est chose amère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 5, 'Pour percer en secret l’innocent de leurs flèches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 6, 'Ils l’atteindront soudain, et n’auront aucune crainte. Ils se sont affermis en leurs desseins; ils se sont concertés pour cacher leurs pièges; ils ont dit: Qui nous verra?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 7, 'Ils ont cherché des iniquités; mais ils ont défailli en leurs recherches. L’homme descendra dans les profondeurs de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 8, 'Mais Dieu sera glorifié; leurs blessures sont comme celles des traits d’un enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 9, 'Leurs langues avaient méprisé le Seigneur; tous ceux qui les ont vus ont été troublés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 10, 'Et tout homme a eu crainte. Et ils ont annoncé les œuvres du Seigneur; et ils ont eu l’intelligence de ses actes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 63, 11, 'Le juste se réjouira dans le Seigneur, et il espérera en lui, et tous les cœurs droits recevront des louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 1, 'Pour être chanté, psaume de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 2, 'O Dieu, il convient en Sion de vous chanter des hymnes; et des vœux vous seront rendus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 3, 'Exaucez ma prière; toute chair ira à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 4, 'Les paroles des méchants ont prévalu contre nous; mais vous nous pardonnerez nos impiétés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 5, 'Heureux celui que vous aurez élu et adopté; il habitera en vos parvis. Nous nous rassasierons des biens de votre demeure. Votre temple est saint; il est admirable en justice. Exaucez-nous, ô Dieu notre Sauveur, espérance de toute la terre et de ceux qui sont au loin sur la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 6, 'Par votre force vous avez formé les monts; vous êtes revêtu de puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 7, 'Vous ébranlez l’abîme de la mer, et ses flots retentissent; et les nations seront troublées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 8, 'Et ceux qui demeurent aux confins de la terre seront saisis de crainte, à cause de vos signes; vous répandrez la joie de l’Orient à l’Occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 9, 'Vous avez visité la terre, et vous l’avez enivrée; vous avez multiplié vos dons pour l’enrichir. Le fleuve de Dieu a été rempli d’eau; vous avez préparé leur nourriture voilà comment est fertilisée la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 10, 'Abreuvez ses sillons, multipliez ses fruits; la récolte qui germe se réjouira de ses rosées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 11, 'Vous bénirez le cercle des mois qui est la couronne de votre bonté, et vos champs seront remplis d’abondance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 12, 'Les montagnes du désert seront engraissées, et les collines seront revêtues d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 13, 'Les béliers du troupeau sont couverts de toison; les vallées regorgeront de froment; elles crieront, et chanteront un hymne au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 64, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 1, 'Pour la fin, psaume de la Résurrection.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 2, 'Terre, jette tout entière des cris de joie au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 3, 'Chantez des louanges en son nom; rendez gloire à sa louange;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 4, 'Dites à Dieu Que vos œuvres sont redoutables, Seigneur! vos ennemis seront contraints, par la plénitude de votre puissance, à feindre devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 5, 'Que toute la terre vous adore; qu’elle chante vers vous; qu’elle chante à votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 6, 'Venez et voyez les œuvres du Seigneur; il est redoutable en ses conseils, sur les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 7, 'Il change la mer en une plage aride; on traversera le fleuve à pied. Là nous nous réjouirons en lui,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 8, 'Qui en sa force est le maître de toute éternité. Ses yeux regardent les nations; que ceux qui l’irritent ne s’exaltent point en eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 9, 'Nations, bénissez notre Dieu, et faites retentir la voix de sa louange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 10, 'C’est lui qui a vivifié mon âme, et qui n’a point permis que mes pieds soient ébranlés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 11, 'Vous nous avez éprouvés, ô Dieu; vous nous avez purifiés par le feu, comme l’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 12, 'Vous nous avez conduits en un piége; vous avez chargé nos épaules d’affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 13, 'Vous avez fait monter des hommes sur nos têtes; nous avons passé à travers l’eau et le feu, et vous nous avez amenés en un lieu de rafraîchissement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 14, 'J’entrerai dans votre demeure avec des holocaustes; je vous rendrai les vœux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 15, 'Que mes lèvres ont proférés; et ma bouche a parlé en mon affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 16, 'Je vous offrirai des holocaustes pleins de moelle, avec de l’encens et des béliers; je vous sacrifierai des bœufs et des chèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 17, 'O vous qui craignez le Seigneur, vous tous écoutez, et je dirai que de grandes choses il a faites pour mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 18, 'J’ai crié vers lui de ma bouche; je l’ai glorifié de ma langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 19, 'Si, en mon cœur, j’ai connu l’iniquité, que le Seigneur ne m’exauce jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 65, 20, 'À cause de cela, le Seigneur m’a écouté; il a été attentif à la voix de ma prière. Béni soit Dieu, qui n’a jamais rejeté ma prière et n’a point détourné de moi sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 1, 'Pour la fin, psaume d’un des hymnes de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 2, 'Ô Dieu, ayez pitié de nous et bénissez-nous; faites luire sur nous votre visage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 3, 'Pour qu’en cette terre nous connaissions votre voie, et que le salut soit parmi toutes les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 4, 'Que les peuples vous rendent grâces, ô Dieu! que tous les peuples vous rendent grâces!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 5, 'Que les nations se réjouissent et tressaillent, parce que vous jugerez les peuples en votre droiture, et que vous guiderez les nations sur la terre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 6, 'Que les peuples vous rendent grâces, ô Dieu! que tous les peuples vous rendent grâces!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 7, 'La terre a donné son fruit; que Dieu, que notre Dieu nous bénisse!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 66, 8, 'Que Dieu nous bénisse, et que tous les confins de la terre le craignent!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 1, 'Pour la fin, psaume de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 2, 'Que Dieu se lève, et que ses ennemis soient dispersés; que ceux qui le haïssent s’enfuient loin de sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 3, 'Qu’ils s’évanouissent comme s’évanouit la fumée; que les pécheurs, devant la face de Dieu, périssent, comme fond la cire devant le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 4, 'Que les justes se réjouissent, qu’ils tressaillent devant Dieu; qu’ils soient dans la joie et les délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 5, 'Chantez à Dieu, chantez des louanges à son nom; faites une voie pour celui qui monte vers l’Occident: LE SEIGNEUR est son nom, tressaillez en sa présence. Ils seront troublés devant la face de celui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 6, 'Qui est le père des orphelins et le juge des veuves; tel est Dieu en son lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 7, 'Dieu fait habiter en sa demeure ceux d’un même vouloir; il délivre les esclaves de la chair, même ceux qui l’irritent et qui habitent des sépulcres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 8, 'Ô Dieu, quand vous marchiez devant votre peuple, quand vous traversiez le désert,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 9, 'La terre trembla, et les cieux versèrent de l’eau devant le Dieu du Sina, devant le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 10, 'Ô Dieu, vous réservez pour votre héritage une pluie venant de votre grâce; car il languissait, et vous l’avez raffermi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 11, 'Vos animaux y habiteront; en votre bonté, ô Dieu, vous avez préparé ce qu’il faut à l’indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 12, 'Le Seigneur accordera le don de sa parole avec une grande puissance à ceux qui annonceront la bonne nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 13, 'Le roi des armées du peuple bien-aimé et choisi partagera les dépouilles à la beauté de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 14, 'Si vous avez votre couche au milieu des lots, vos ailes seront argentées comme celles de la colombe, et votre dos brillera de la couleur vert et or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 15, 'Tandis que le roi céleste dispersera les rois en sa terre, ils seront blancs comme la neige de Selmon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 16, 'La montagne de Dieu est une montagne grasse, une montagne coagulée, une montagne fertile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 17, 'Pourquoi vous défiez-vous des grasses montagnes du Seigneur? C’est la montagne où il a plu à Dieu de résider; car le Seigneur y aura éternellement son tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 18, 'Le char de Dieu contient une myriade, des milliers de bienheureux; le Seigneur est avec eux en Sina, dans le lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 19, 'Monté en haut, vous avez emmené des captifs; vous avez reçu des présents pour les hommes, même pour abriter des infidèles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 20, 'Béni soit le Seigneur Dieu; béni soit chaque jour le Seigneur; et le Dieu de notre salut nous fera prospérer dans notre voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 21, 'Notre Dieu est le Dieu du salut, et au Seigneur appartiennent les fins de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 22, 'Toutefois Dieu brisera la tête de ses ennemis; il ôtera la couronne des cheveux de ceux qui cheminent en leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 23, 'Le Seigneur a dit à son peuple: Je te ramènerai de Basan, je te ramènerai du fond de la mer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 24, 'Afin que ton pied se baigne dans le sang, et la langue de tes chiens dans le sang des ennemis de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 25, 'Ils ont vu votre marche, ô Dieu, la marche de mon Dieu, du Roi qui est en son lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 26, 'Et les princes, joints aux chanteurs, ont pris l’avance au milieu des jeunes filles frappant des tambours, et chantant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 27, 'Bénissez Dieu dans les églises; bénissez le Seigneur des fontaines d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 28, 'Là Benjamin, le plus jeune des fils de Jacob, est en extase; là sont les princes de Juda, les princes de Zabulon, les princes de Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 29, 'Dieu, commandez à votre force confirmez, ô Dieu, ce que vous avez ordonné en nous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 30, 'À cause de votre temple de Jérusalem, des rois vous apporteront leurs présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 31, 'Châtiez les bêtes fauves des roseaux; châtiez ces taureaux assemblés contre les génisses des peuples, afin que ceux qui ont été éprouvés, comme de l’argent, ne soient point exclus. Dispersez les nations qui veulent la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 32, 'Des anciens viendront de l’Égypte; l’Éthiopie sera la première à étendre les mains vers Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 33, 'Ô vous, royaumes de la terre, chantez à Dieu, chantez des psaumes au Seigneur, chantez à Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 34, 'Qui est monté sur le ciel des cieux vers l’Orient; voilà qu’il va faire entendre le son puissant de sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 35, 'Rendez gloire à Dieu; sa magnificence est sur Israël, et sa puissance dans les nuées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 67, 36, 'Dieu est admirable dans ses saints; le Dieu d’Israël donnera lui-même la force à son peuple et l’affermira; béni soit Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 1, 'Pour être chanté, sur ceux qui seront transformés; de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 2, 'Sauvez-moi, ô mon Dieu, car les flots sont entrés jusqu’à mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 3, 'Je suis enfoncé dans un abîme de fange où il n’y a point de fond; je suis plongé dans les profondeurs de la mer, et la tempête m’a submergé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 4, 'Je me suis fatigué à crier; ma voix s’est enrouée; mes yeux se sont éteints, quand j’ai mis mon espoir en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 5, 'Ceux qui me haïssent sans cause sont devenus plus nombreux que les cheveux de ma tête; mes ennemis, ceux qui me persécutent injustement, se sont fortifiés; j’ai payé ce que je n’avais point ravi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 6, 'O Dieu, vous connaissez ma folie, et mes fautes ne vous sont point cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 7, 'Seigneur, Dieu des armées, que ceux qui vous attendent ne soient point humiliés en moi; ô Dieu d’Israël, que ceux qui vous cherchent ne soient point en moi confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 8, 'Car, pour l’amour de vous, j’ai supporté les outrages; la confusion a couvert ma face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 9, 'Je suis devenu un étranger pour mes frères, un inconnu pour les fils de ma mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 10, 'Parce que le zèle de votre maison m’a dévoré, et que les injures de ceux qui vous outrageaient sont tombées sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 11, 'Et j’ai dompté mon âme par le jeûne, et, par là, je me suis attiré des mépris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 12, 'Et j’ai pris pour vêtement un cilice, et me voilà devenu leur fable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 13, 'Les hommes assis vers la porte parlaient contre moi, et les buveurs de vin chantaient en me raillant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 14, 'Et moi dans ma prière à vous, ô Seigneur, je disais: Mon Dieu, le temps de la bienveillance est venu; écoutez-moi dans la plénitude de votre miséricorde, sauvez-moi par votre vérité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 15, 'Retirez-moi de la fange, afin que je n’y demeure point enfoncé; délivrez-moi de mes ennemis et de la profondeur des eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 16, 'Qu’un flot soulevé par la tempête ne me submerge pas; que l’abîme ne m’engloutisse point; que la pierre du puits de l’abîme ne se ferme point sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 17, 'Exaucez-moi, Seigneur, car votre miséricorde est bonne; jetez un regard sur moi dans l’abondance de votre compassion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 18, 'Ne détournez point votre visage de votre serviteur; je suis opprimé, exaucez-moi promptement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 19, 'Considérez mon âme et rachetez-la; sauvez-moi de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 20, 'Car vous connaissez leurs injures, et ma honte, et mon humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 21, 'Tous ceux qui m’affligent sont en votre présence; mon âme s’est résignée aux opprobres et à la misère; j’ai attendu quelqu’un qui fût contristé avec moi, et nul n’est venu; j’ai cherché un consolateur, et je ne l’ai point trouvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 22, 'Et ils m’ont donné du fiel pour nourriture, et dans ma soif ils m’ont abreuvé de vinaigre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 23, 'Que leur table devienne pour eux un piège; qu’elle soit leur punition et leur scandale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 24, 'Que leurs yeux soient obscurcis et qu’ils ne voient plus; et que leur dos soit perpétuellement courbé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 25, 'Répandez sur eux votre courroux; que le transport de votre colère les saisisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 26, 'Que leur maison des champs soit désolée, et que nul n’habite sous leur toit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 27, 'Parce qu’ils ont persécuté celui que vous aviez frappé, et qu’ils ont ajouté à la douleur de mes blessures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 28, 'Imputez-leur iniquité sur iniquité; qu’ils n’entrent pas en votre justice!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 29, 'Qu’ils soient effacés du livre des vivants; qu’ils ne soient point inscrits parmi les justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 30, 'Pour moi, je suis pauvre et désolé; mais la protection de votre face m’a sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 31, 'Je louerai dans mes cantiques le nom de mon Dieu; je le glorifierai en mes louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 32, 'Et cela plaira à Dieu, plus qu’un jeune veau montrant des ongles et des cornes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 33, 'Que les pauvres voient et se réjouissent; cherchez Dieu, et vous vivrez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 34, 'Car le Seigneur a exaucé les indigents, et jamais n’a méprisé ceux qui sont ses captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 35, 'Qu’il soit loué des cieux, de la terre, de la mer, et de tous les êtres qui se meuvent en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 36, 'Car le Seigneur sauvera Sion, et les villes de la Judée seront édifiées, et des hommes les habiteront, et l’obtiendront pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 68, 37, 'Et la postérité de ses serviteurs les possédera, et ceux qui aiment son nom y auront leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 69, 1, 'Pour être chanté, souvenir de David, pour que le Seigneur le sauve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 69, 2, 'O Dieu, venez à mon aide; Seigneur, hâtez-vous de me secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 69, 3, 'Qu’ils soient humiliés et confondus, ceux qui cherchent mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 69, 4, 'Qu’ils soient mis en fuite et couverts de honte, ceux qui me veulent du mal; qu’ils tournent le dos et soient soudain couverts de honte, ceux qui me disent: Ha! ha!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 69, 5, 'Que tous ceux qui vous cherchent se réjouissent et se complaisent en vous; que ceux qui aiment votre salut disent à jamais: Dieu soit glorifié!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 69, 6, 'Pour moi, je suis indigent et pauvre; ô mon Dieu, secourez-moi; vous êtes mon auxiliaire et mon défenseur; Seigneur, ne tardez pas!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 69, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 1, 'Seigneur, j’ai espéré en vous; que je ne sois pas confondu à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 2, 'Dans votre justice défendez-moi, et délivrez-moi; inclinez vers moi votre oreille, et sauvez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 3, 'Soyez pour moi un Dieu protecteur et une place fortifiée, afin de me sauver; car vous êtes mon appui et mon refuge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 4, 'Mon Dieu, tirez-moi de la main du pécheur, de celle du pervers et du méchant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 5, 'Car vous êtes mon attente, Seigneur; Seigneur, vous êtes mon espérance dès ma jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 6, 'À peine conçu, j’ai été confirmé en vous; dès le sein de ma mère, vous êtes mon abri; mes chants ne cessent de s’adresser à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 7, 'J’ai été comme un prodige pour un grand nombre; et vous, vous êtes ma force et mon appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 8, 'Que ma bouche soit pleine de louanges, afin que je chante tout le jour votre gloire et votre grandeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 9, 'Ne me faites point tomber au temps de la vieillesse; quand ma force sera défaillante, ne m’abandonnez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 10, 'Car mes ennemis ont parlé contre moi; ceux qui épient mon âme ont tenu conseil ensemble,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 11, 'Disant: Dieu l’a délaissé, poursuivez-le, saisissez-le; car nul n’est là pour le défendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 12, 'O Dieu, ne vous éloignez point de moi; mon Dieu, venez à mon aide!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 13, 'Qu’ils soient confondus et détruits, les calomniateurs de mon âme; qu’ils soient revêtus de honte et d’humiliation, ceux qui me veulent du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 14, 'Pour moi, j’espérerai toujours; je vous louerai de plus en plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 15, 'Ma bouche proclamera tout le jour votre justice et votre salut; car je ne connais aucun des travaux de l’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 16, 'Mais j’entrerai dans la contemplation de la puissance de Dieu; Seigneur, je me souviendrai seulement de votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 17, 'Vous m’avez instruit, Seigneur, dès ma jeunesse, et jusqu’ici j’ai annoncé vos merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 18, 'Et je continuerai jusqu’à l’extrême vieillesse; ô Dieu, ne m’abandonnez pas avant que j’aie annoncé, à toute la génération future, votre bras et votre puissance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 19, 'Et votre justice, ô mon Dieu, jusqu’au plus haut des cieux, et les grandes choses que vous avez faites. O Dieu, qui donc est semblable à vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 20, 'Autant de fois vous m’avez fait voir de nombreuses et cruelles afflictions, autant de fois vous êtes revenu à moi pour me vivifier; et vous m’avez ramené des abîmes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 21, 'Vous avez multiplié sur moi votre libéralité, et vous êtes revenu à moi, et vous m’avez consolé, et vous m’avez ramené des abîmes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 22, 'Et moi, sur mes instruments de musique, je confesserai, ô mon Dieu, votre vérité; je vous chanterai des psaumes sur la cithare, ô Saint d’Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 23, 'Mes lèvres se réjouiront quand je chanterai pour vous, et aussi mon âme que vous avez affranchie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 70, 24, 'Ma langue, tout le jour, racontera votre justice, lorsque ceux qui me veulent du mal auront été humiliés et confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 1, 'Sur Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 2, 'Ô Dieu, donnez au roi votre jugement, et au fils du roi votre équité pour juger votre peuple avec justice, et vos pauvres avec équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 3, 'Que les montagnes et les collines reçoivent la paix pour votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 4, 'Il jugera avec justice les pauvres du peuple, et il sauvera les fils des pauvres, et il humiliera le calomniateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 5, 'Durant les générations des générations, il subsistera autant que le soleil et plus que la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 6, 'Il descendra comme la pluie sur une toison, et comme les gouttes de la rosée découlant sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 7, 'En ses jours, la justice se lèvera avec la plénitude de la paix, et durera jusqu’à ce que la lune disparaisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 8, 'Et il règnera d’une mer à l’autre mer, et des fleuves aux limites de la terre habitable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 9, 'Devant lui, les Éthiopiens se prosterneront, et ses ennemis lècheront la poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 10, 'Les rois de Tharsis et les îles lui feront des présents; les rois des Arabes et de Saba lui apporteront leurs offrandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 11, 'Et tous les rois l’adoreront, tous les peuples lui seront asservis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 12, 'Parce qu’il aura protégé contre le puissant le pauvre et l’indigent, à qui nul n’était secourable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 13, 'Il épargnera le mendiant et le pauvre; il sauvera les âmes des indigents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 14, '1 affranchira leurs âmes de l’usure et de l’iniquité; leur nom sera en honneur devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 15, 'Et il vivra, et il lui sera donné de l’or de l’Arabie; perpétuellement on fera des vœux pour lui, et tout le jour on le bénira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 16, 'Il sera l’appui de la terre jusqu’aux cimes des montagnes; ses fruits s’élèveront au-dessus du Liban, et des essaims sortiront de la cité, comme les herbes des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 17, 'Que son nom soit béni dans tous les âges; son nom subsistera plus que le soleil; et en lui toutes les tribus de la terre seront bénies, toutes les nations célébreront sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 18, 'Béni soit le Seigneur Dieu d’Israël, qui seul fait des prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 19, 'Et béni soit son nom glorieux dans l’éternité et dans tous les siècles, et que toute la terre soit pleine de sa gloire. Ainsi soit-il, ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 71, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 1, 'Que Dieu est bon pour Israël, pour ceux qui sont droits en leur cœur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 2, 'Peu s’en est fallu que mes pieds n’aient chancelé; peu s’en est fallu que mes pieds n’aient glissé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 3, 'Car à voir la paix des pécheurs, je les avais enviés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 4, 'En effet, à leur mort ils ne font point paraître qu’ils la refusent, et ils ont de la fermeté en leurs châtiments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 5, 'Ils n’ont point les peines des autres hommes, et comme les autres hommes ils ne seront point flagellés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 6, 'À cause de cela l’orgueil les possède; ils se sont revêtus de leur injustice et de leur impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 7, 'Leur injustice sortira de leur richesse comme de sa source; ils se sont adonnés aux caprices de leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 8, 'Ils ont pensé et parlé méchamment; ils ont parlé du Très-Haut avec injustice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 9, 'Ils ont fait usage de leur bouche contre le ciel, et leur langue a parcouru la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 10, 'À cause de cela mon peuple y retournera, et une grande plénitude de jours sera trouvée en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 11, 'Ils ont dit: Que sait Dieu? et comment y a-t-il quelque science dans le Très-Haut?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 12, 'Voilà les pécheurs qui prospèrent toujours; ils possèdent les richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 13, 'Et moi-même j’ai dit: J’ai donc vainement rendu juste mon cœur, et levé mes mains parmi les innocents!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 14, 'J’ai été châtié tout le jour, et réprimandé tous les matins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 15, 'Si j’avais parlé ainsi, voilà que j’eusse rompu mon alliance avec vos enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 16, 'Et j’ai entrepris de comprendre ces choses; mais ce travail reste inconnu devant moi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 17, 'Tant que je n’aurai pas pénétré dans le sanctuaire de Dieu; car c’est ainsi que je comprendrai les choses de la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 18, 'Or donc, Seigneur, vous avez rendu jugement contre eux à cause de leurs fourberies; et tandis qu’ils s’élevaient, vous les avez renversés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 19, 'Comment sont-ils tombés dans la désolation? Ils ont défailli soudain; ils ont péri à cause de leur iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 20, 'Comme le songe d’un homme qui s’éveille, Seigneur, dans votre cité vous mettrez à néant leur image.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 21, 'C’est pourquoi mon cœur s’est réjoui, et mes reins se sont reposés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 22, 'Parce que moi aussi j’avais été mis à néant, et j’en ignorais la cause;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 23, 'Devant vous, j’étais devenu comme une brute, et je restai sans cesse avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 24, 'Mais vous m’avez pris par la main droite, vous m’avez conduit selon votre volonté; vous m’avez accueilli avec honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 25, 'Or, qu’ai-je au ciel? Et après vous, qu’ai-je désiré sur la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 26, 'Ma chair et mon cœur ont défailli, ô Dieu de mon cœur, et Dieu est mon partage pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 27, 'Car ceux qui se sont éloignés de vous périront, et vous avez exterminé tous ceux qui se prostituaient loin de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 72, 28, 'Pour moi, il est bon que je m’attache à Dieu, que je place en Dieu mon espérance, que je chante ses louanges aux portes de la fille de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 1, 'Pourquoi, mon Dieu, m’avez-vous repoussé pour toujours? Pourquoi votre colère est-elle excitée contre les brebis de vos pâturages?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 2, 'Souvenez-vous du troupeau que, dès le commencement, vous avez acquis; vous avez racheté le rameau de votre héritage, cette montagne de Sion, où vous avez dressé votre tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 3, 'Levez les mains pour mettre fin à leur orgueil; que de mal a fait l’ennemi en vos lieux saints!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 4, 'Comme ceux qui vous haïssent se sont glorifiés au milieu de vos fêtes! Ils ont posé leurs étendards, comme des signaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 5, 'À la porte d’en haut, sans savoir ce qu’ils faisaient. Comme dans une forêt, avec des haches,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 6, 'Ils ont frappé les battants de cette porte au même endroit; ils l’ont brisée avec la hache et le levier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 7, 'Ils ont brûlé par le feu votre sanctuaire sur la terre; ils ont souillé lé tabernacle de votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 8, 'Ils ont dit en leur cœur, et leur race, réunie au même lieu, a dit: Allons, abolissons en cette terre les fêtes du Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 9, 'Nous ne voyons plus nos signes; il n’est plus de prophètes, et l’on ne nous reconnaîtra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 10, 'Jusques à quand, mon Dieu, l’ennemi vous outragera-t-il? L’ennemi provoquera-t-il toujours votre nom?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 11, 'Pourquoi avez-vous détourné votre main, votre droite du milieu de votre sein? Est-ce pour toujours?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 12, 'Cependant Dieu, notre roi avant les siècles, a opéré notre salut au milieu de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 13, 'Par votre puissance vous avez dompté la mer; vous avez brisé sur les eaux la tête des dragons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 14, 'Vous avez brisé les têtes du dragon; vous l’avez donné pour nourriture aux peuples éthiopiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 15, 'Vous avez ouvert les fontaines et les torrents; vous avez desséché les fleuves d’Etham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 16, 'Le jour est à vous, la nuit est à vous, vous avez préparé la lune et le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 17, 'Vous avez fait toutes les limites de la terre; vous avez fait l’été et le printemps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 18, 'Souvenez-vous de ce peuple que vous vous êtes acquis; l’ennemi a outragé le Seigneur, et un peuple insensé a provoqué son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 19, 'Ne livrez point aux bêtes fauves l’âme qui vous loue, et n’oubliez pas pour toujours l’âme de vos pauvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 20, 'Considérez votre alliance; car les lieux obscurs de la terre sont remplis de maisons d’iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 21, 'Que l’affligé, que l’humble ne soient point rejetés; le pauvre et le nécessiteux loueront votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 22, 'Levez-vous, ô Dieu, rendez vos jugements; souvenez-vous des outrages que vous prodigue l’insensé tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 73, 23, 'N’oubliez point la voix de vos suppliants, et que l’orgueil de ceux qui vous haïssent monte toujours jusqu’à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 1, 'Pour être chanté. Ne détruisez pas; psaume ou cantique d’Asaph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 2, 'Nous vous rendrons grâces, ô Dieu, nous vous rendrons grâces, et nous invoquerons votre nom. Je raconterai toutes vos merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 3, 'Quand j’aurai pris mon temps, je jugerai avec droiture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 4, 'La terre s’est liquéfiée avec tous ceux qui l’habitent, et moi j’ai raffermi ses colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 5, 'J’ai dit aux pervers: Gardez-vous de faire le mal; et aux pécheurs: Ne levez pas le front.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 6, 'Ne levez pas le front avec orgueil; ne parlez pas injustement contre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 7, 'Car le secours ne viendra ni de l’Orient, ni du Couchant, ni des montagnes du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 8, 'Car Dieu seul est le juge: il humilie celui-ci, il exalte celui-là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 9, 'Il y a dans la main du Seigneur un calice plein de vin sans mélange. Il l’incline çà et là, mais jamais il ne l’épuise jusqu’à la lie; tous les pécheurs de la terre en boiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 10, 'Pour moi, je tressaillirai d’une allégresse perpétuelle; je chanterai au Dieu de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 74, 11, 'Et je briserai le front de tous les pécheurs, et le front des justes sera exalté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 1, 'Pour être chanté avec les hymnes, psaume d’Asaph, chant concernant les Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 2, 'Dieu est connu en Judée; son nom est grand en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 3, 'Et son lieu est dans la paix, et sa demeure est dans Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 4, 'C’est là qu’il a brisé la force des arcs, et les armures, et le glaive, et la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 5, 'Vous éclairez merveilleusement du haut des montagnes éternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 6, 'Tous les insensés ont été troublés en leur cœur. Ils ont dormi leur sommeil, et tous les favoris de la richesse n’ont rien trouvé dans leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 7, 'À vos approches, Dieu de Jacob, les cavaliers se sont endormis sur leurs chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 8, 'Vous êtes redoutable, et qui donc résisterait à votre colère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 9, 'Du haut du ciel vous avez fait entendre votre jugement; la terre a eu peur, et s’est tenue en repos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 10, 'Lorsque Dieu s’est levé pour juger et pour sauver les doux en leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 11, 'La pensée de l’homme vous rendra grâces, et le mémorial de cette pensée vous fêtera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 12, 'Faites des vœux à Dieu notre Seigneur, et accomplissez-les; tous ceux qui se rassemblent autour de lui feront des offrandes au Dieu terrible,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 75, 13, 'À celui qui ôte l’esprit aux princes et qui est terrible aux rois de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 1, 'Pour être chanté, psaume d’Asaph sur Idithun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 2, 'J’ai crié au Seigneur de ma voix; et ma voix est allée au Seigneur, et il a fait attention à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 3, 'Au jour de mon affliction, j’ai cherché Dieu; la nuit, j’ai étendu vers lui les mains, et je n’ai pas été déçu. Mon âme ne voulait pas être consolée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 4, 'Je me suis souvenu de Dieu, et j’ai été réjoui; j’ai réfléchi comme un enfant, et mon esprit a défailli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 5, 'Tous mes ennemis surprenaient à l’improviste mes gardes; j’ai été troublé, et je n’ai point parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 6, 'J’ai considéré les jours antiques, et je me suis souvenu des années éternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 7, 'J’ai médité, et la nuit j’ai réfléchi en mon cœur, et je me suis creusé l’esprit, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 8, 'Est-ce que le Seigneur me repoussera toujours? est-ce qu’il ne se complaira plus en moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 9, 'Est-ce que, jusqu’à la fin, il privera de sa miséricorde les générations des générations?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 10, 'Dieu oubliera-t-il de s’apitoyer? Confondra-t-il sa miséricorde avec sa colère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 11, 'Et j’ai dit: Maintenant j’ai commencé; ceci est le changement de la droite du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 12, 'Je me suis souvenu des œuvres du Seigneur, et je me souviendrai de vos merveilles dès le commencement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 13, 'Et je méditerai sur toutes vos œuvres, et je réfléchirai sur vos conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 14, 'O Dieu, votre voie est dans la sainteté; quel Dieu est grand comme notre Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 15, 'Vous êtes le Dieu qui faites vos merveilles; vous avez fait connaître aux peuples votre puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 16, 'Par votre bras, vous avez délivré votre peuple, les fils de Jacob et de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 17, 'Les eaux vous ont vu, mon Dieu, les eaux vous ont vu; et elles ont eu peur, et les abîmes ont été troublés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 18, 'Le fracas des eaux a longuement retenti; les nuées ont fait entendre des voix, car vos flèches les ont traversées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 19, 'La voix de votre tonnerre a retenti dans la voûte du ciel; vos éclairs ont brillé sur le monde; la terre a frémi et tremblé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 20, 'Votre voie est au fond de la mer; et vos sentiers sont recouverts par des amas d’eau, et l’on ne reconnaîtra pas vos traces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 76, 21, 'Vous avez conduit votre peuple comme un troupeau par les mains d’Aaron et de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 1, 'O mon peuple, attachez-vous à ma loi; inclinez votre oreille vers les paroles de ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 2, 'J’ouvrirai ma bouche en paraboles; je dirai les choses qui ont existé dès le commencement,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 3, 'Telles que vous les avez ouïes et connues, et que vos pères vous les ont racontées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 4, 'Elles n’ont point été cachées à leurs enfants de la seconde génération, eux-mêmes leur ayant annoncé les louanges du Seigneur, et sa puissance et les merveilles qu’il a faites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 5, 'Et il a suscité un témoignage en Jacob, et il a institué en Israël une loi qu’il a confiée à nos pères, pour qu’ils l’enseignassent à leurs enfants,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 6, 'Afin que chaque génération les transmit à la suivante; les fils l’apprendront à ceux qui naîtront d’eux; et ils en porteront témoignage, et ils en instruiront leurs enfants:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 7, 'Afin qu’ils mettent en Dieu leur espérance, et qu’ils n’oublient point ses œuvres, et qu’ils recherchent ses commandements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 8, 'Et qu’ils ne soient point comme leurs pères, race perverse et provocatrice, qui n’a pas eu de droiture de cœur, et, en son esprit, n’a pas été fidèle à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 9, 'Les fils d’Ephraïm tendant l’arc, lançant des flèches, le jour du combat ont tourné le dos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 10, 'Ils n’ont point gardé l’alliance de Dieu, et ils ont refusé de marcher dans sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 11, 'Et ils ont oublié ses bienfaits, et les miracles qu’il leur a montrés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 12, 'Et les prodiges qu’il a faits devant leurs pères, en la terre d’Égypte et dans la plaine de Tanis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 13, 'Il a séparé la mer, et il les a fait passer; il a contenu les eaux, comme dans une outre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 14, 'Et il les a guidés le jour dans une nuée, et la nuit dans un luminaire de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 15, 'Il a fendu le rocher dans le désert, et il les a abreuvés comme avec l’eau d’un grand abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 16, 'Et de la pierre il a tiré et conduit l’eau comme un fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 17, 'Et ils ont continué de pécher contre lui; ils ont provoqué le Très-Haut dans le désert;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 18, 'Et ils ont tenté Dieu en leurs cœurs, en lui demandant des aliments pour leurs âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 19, 'Et ils ont parlé contre Dieu, et ils ont dit: Est-ce que Dieu pourra nous préparer une table dans le désert?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 20, 'Il a frappé le rocher: l’eau a jailli; un torrent a coulé avec abondance. Mais Dieu pourra-t-il nous donner aussi du pain, ou préparer dans le désert une table à son 4 peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 21, 'C’est pourquoi le Seigneur, les ayant entendus, différa, et un feu fut allumé contre Jacob, et sa colère monta contre Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 22, 'Parce qu’ils n’avaient pas eu foi en Dieu, et qu’ils n’avaient point espéré en sa protection.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 23, 'Et d’en haut il donna ses ordres aux nues, et il ouvrit les portes du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 24, 'Et il fit pleuvoir sur eux la manne pour les nourrir, et il leur donna le pain du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 25, 'L’homme mangea le pain des anges; Dieu leur envoya des aliments en abondance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 26, 'Il chassa le vent du midi, et par sa puissance il amena le vent de l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 27, 'Et il fit pleuvoir pour eux de la chair comme des nuées de poussière, et des oiseaux emplumés comme le sable des mers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 28, 'Et ces oiseaux tombèrent au milieu de leur camp, autour de leurs tentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 29, 'Et ils mangèrent, et ils furent rassasiés; et il satisfit leur désir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 30, 'Rien ne leur manqua de ce qu’ils désiraient, et ils en avaient encore la bouche pleine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 31, 'Et la colère du Seigneur s’éleva contre eux, et il mit à mort leurs riches, et il saisit les élus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 32, 'Et malgré tout cela ils péchèrent encore, et ne crurent point à ses prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 33, 'Et leurs jours défaillirent en vanité, et leurs années se précipitèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 34, 'Quand il eut répandu parmi eux la mort, ils cherchèrent le Seigneur, et ils se convertirent à lui, et ils vinrent dès le matin vers Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 35, 'Et ils se souvinrent que Dieu est leur auxiliaire, et que Dieu le Très-Haut est leur rédempteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 36, 'Et ils l’aimèrent de la bouche; mais leur langue lui mentait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 37, 'Car leur cœur ne fut point droit envers lui, et ils ne furent point fidèles en son alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 38, 'Et cependant il est miséricordieux, et il leur remettra leurs péchés; et il ne les détruira point. Il détournera souvent sa colère, et son courroux ne s’enflammera pas tout entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 39, 'Et il se souvint qu’ils étaient chair, un souffle qui passe et ne revient plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 40, 'Combien de fois l’ont-ils provoqué dans le désert, et l’ont-ils irrité dans la terre sans eau!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 41, 'Et ils se convertissaient, et ils recommençaient à tenter Dieu, et ils aigrissaient encore le Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 42, 'Ils avaient oublié sa main, et le jour où elle les avait tirés des mains de l’oppresseur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 43, 'Et comment il avait fait ses miracles en Égypte, et ses prodiges dans la plaine de Tanis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 44, 'Et comment il avait changé en sang leurs fleuves et leurs pluies, afin qu’ils ne pussent boire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 45, 'Et comment il avait envoyé des mouches de chien qui les dévoraient, et des grenouilles qui les détruisaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 46, 'Ils avaient oublié la nielle attachée à leurs fruits, et les sauterelles dont ils avaient souffert,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 47, 'Et la grêle détruisant leurs vignes, et la gelée faisant périr leurs mûriers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 48, 'Et les grêlons exterminant leur bétail, et le feu consumant leurs richesses,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 49, 'Et sa colère et son indignation tombant sur eux; colère, fureur, afflictions, envois d’anges exterminateurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 50, 'Et la voie ouverte à son courroux, et son dessein de ne point épargner leur vie, et d’enclore leurs troupeaux dans la mort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 51, 'Et le coup dont fut frappé tout premier-né en la terre d’Égypte, prémices de leurs peines sous leurs tentes de Cham;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 52, 'Et le soin qu’il prit d’enlever son peuple comme des brebis, et de les conduire dans le désert, comme un troupeau;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 53, 'Et les espérances qu’il leur donna, et les craintes dont il les délivra, et la mer qui couvrit leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 54, 'Et il les mena sur la montagne qu’il s’était consacrée, cette montagne que sa droite avait acquise. Et il chassa les nations devant leur face, et il leur distribua, à grandes mesures, la terre de leur héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 55, 'Et il établit les tribus d’Israël dans les demeures des vaincus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 56, 'Mais elles tentèrent et provoquèrent Dieu le Très-Haut; elles ne gardèrent point ses témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 57, 'Et son peuple, se détournant de lui, s’endurcit comme ses pères; il devint comme un arc tortu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 58, 'Et ils provoquèrent la colère de Dieu sur leurs hauts lieux; et ils le rendirent jaloux par leurs images sculptées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 59, 'Dieu les entendit et les méprisa, et réduisit à néant Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 60, 'Et il répudia le tabernacle de Silo, son tabernacle où il résidait parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 61, 'Et il livra à la captivité leur force, aux ennemis leur beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 62, 'Et il exposa son peuple au glaive, et il dédaigna son propre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 63, 'La flamme dévora leurs jeunes hommes, et leurs vierges ne furent point pleurées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 64, 'Leurs prêtres tombèrent sous le glaive, et leurs veuves ne furent point pleurées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 65, 'Et le Seigneur s’éveilla comme un homme endormi, ou comme un riche après l’ivresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 66, 'Et il frappa ses ennemis comme ils tournaient le dos, et il les couvrit d’un opprobre éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 67, 'Et il répudia le tabernacle de Joseph, et il ne choisit point la tribu d’Éphraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 68, 'Et il choisit la tribu de Juda, et la montagne de Sion, qu’il a aimée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 69, 'Et il bâtit son sanctuaire, fort comme la corne des licornes, en la terre qu’il a fondée pour les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 70, 'Et choisit David son serviteur, et il le tira de la garde des troupeaux; il le prit tandis qu’il surveillait les brebis mères,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 71, 'Pour qu’il fût le pasteur de Jacob, son serviteur, et d’Israël, son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 77, 72, 'Et David prit soin d’eux en l’innocence de son cœur, et il les mena dans la voie, selon l’intelligence de ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 1, 'Ô Dieu, les gentils sont entrés en votre héritage; ils ont pollué votre temple saint. Ils ont fait de Jérusalem une cabane de jardinier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 2, 'Ils ont donné les cadavres de vos serviteurs en pâture aux oiseaux du ciel, et les chairs de vos saints aux bêtes fauves de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 3, 'Ils ont versé comme de l’eau le sang de votre peuple autour de Jérusalem, et nul n’était là pour ensevelir les morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 4, 'Nous sommes devenus un opprobre pour nos voisins, la dérision et le jouet de ceux qui nous entourent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 5, 'Jusques à quand, Seigneur, serez-vous sans cesse en courroux? Votre jalousie brûlera-t-elle toujours comme le feu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 6, 'Épanchez votre colère sur les nations qui ne vous connaissent point, et sur les royaumes qui n’invoquent pas votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 7, 'Car ils ont dévoré Jacob et désolé sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 8, 'N’ayez point le souvenir de nos iniquités d’autrefois; que vos miséricordes nous devancent promptement, car nous sommes grandement appauvris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 9, 'Secourez-nous, Dieu notre Sauveur, pour la gloire de votre nom; Seigneur, protégez-nous; remettez-nous nos péchés, pour la gloire de votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 10, 'Que l’on ne dise point chez les nations: Où est leur Dieu? Que devant nos yeux les gentils voient la vengeance du sang de vos serviteurs, qui a été répandu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 11, 'Que les gémissenients des captifs pénètrent jusqu’à vous; que les fils de ceux qu’on a mis à mort soient sauvés, selon la grandeur de votre bras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 12, 'Rendez à nos voisins, mettez au septuple dans leur sein les outrages dont ils nous ont déshonorés, ô Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 78, 13, 'Car nous sommes votre peuple et les brebis de votre pâturage; nous vous rendons grâces dans tous les siècles; nous publierons vos louanges, de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 1, 'Pour être chanté, sur ceux qui seront transformés; témoignage d’Asaph. Psaume au sujet de l’Assyrien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 2, 'O pasteur d’Israël, soyez attentif, vous qui conduisez Joseph comme un troupeau de brebis. O vous qui êtes assis sur les chérubins, apparaissez');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 3, 'Devant Éphraïm, et Benjamin et Manassé; réveillez votre puissance, et venez pour nous secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 4, 'O Dieu, convertissez-nous et montrez-nous votre face, et nous serons sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 5, 'Seigneur, Dieu des armées, jusques à quand serez-vous courroucé de la prière de votre serviteur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 6, 'Nous donnerez-vous à manger un pain de larmes, et nous ferez-nous boire des larmes à pleine mesure?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 7, 'Vous nous avez mis en contradiction avec nos voisins, et nos ennemis se sont moqués de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 8, 'Seigneur, Dieu des armées, convertissez-nous et montrez-nous votre face, et nous serons sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 9, 'Vous avez transplanté une vigne de l’Égypte; vous avez chassé les gentils, et vous l’avez plantée sur leur terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 10, 'Vous avez fait un chemin devant elle; vous avez fait germer ses racines, et la terre en a été remplie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 11, 'Son ombre a couvert les montagnes, et ses arbustes ont surpassé les cèdres de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 12, 'Elle a étendu des ceps jusqu’à la mer, et des surgeons jusqu’au fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 13, 'Pourquoi donc avez-vous détruit sa clôture, si bien que tous ceux qui passent sur la voie la vendangent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 14, 'Le sanglier de la forêt l’a dévastée, et une bête solitaire y est venue paître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 15, 'O Dieu des armées, venez à nous; regardez du ciel, et voyez, et visitez cette vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 16, 'Et restaurez-la, elle que votre droite a plantée; ayez la main sur le fils de l’homme, que pour vous-même vous avez confirmé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 17, 'Elle a été brûlée par le feu et arrachée; et à cause du blâme de votre face, votre peuple périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 18, 'Que votre main soit sur l’homme de votre droite et sur le fils de l’homme, que vous-même vous avez confirmé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 19, 'Et nous ne nous éloignerons point de vous; vous nous vivifierez, et nous invoquerons votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 79, 20, 'Seigneur, Dieu des armées, convertissez-nous et montrez-nous votre face, et nous serons sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 1, 'Pour être chanté, psaume d’Asaph, sur les pressoirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 2, 'Réjouissez-vous en Dieu notre auxiliaire; criez joyeusement vers le Dieu de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 3, 'Prenez un psaume, et faites résonner le tambour, la harpe mélodieuse et la cithare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 4, 'Sonnez de la trompette à la nouvelle lune, au jour glorieux de notre fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 5, 'Car tel est le précepte en Israël, tel est le commandement du Dieu de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 6, 'Il a mis ce témoignage en Joseph, quand celui-ci sortit de la terre d’Égypte; il entendit une langue qu’il ne connaissait pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 7, 'Il a ôté le fardeau des épaules de son peuple, quand ses mains tressaient des corbeilles, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 8, 'Tu m’as invoqué en ton affliction, et je t’ai délivré; je t’ai entendu dans l’obscurité d’une tempête; je t’ai éprouvé dans l’eau de la contradiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 9, 'Écoute, mon peuple; et je te parlerai, Israël, et je te prendrai à témoin. Si tu m’écoutes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 10, 'Il n’y aura point chez toi de Dieu nouveau, et tu n’adoreras point de Dieu étranger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 11, 'Car je suis le Seigneur ton Dieu, qui t’ai tiré de la terre d’Égypte; ouvre la bouche, et je la remplirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 12, 'Et mon peuple n’a point écouté ma voix, et Israël n’a point fait attention à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 13, 'Et je les ai fait partir, selon les désirs de leurs cœurs; ils chemineront en leurs désirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 14, 'Si mon peuple m’avait écouté, si Israël avait marché dans mes voies,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 15, 'Certes j’eusse humilié jusqu’au néant leurs ennemis; j’eusse mis la main sur leurs oppresseurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 16, 'Les ennemis du Seigneur lui ont menti, et il y aura temps pour eux dans l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 80, 17, 'Et il les avait nourris de la fleur du froment, et les avait rassasiés du miel des rochers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 1, 'Dieu s’est tenu debout dans l’assemblée des dieux, et Dieu jugera au milieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 2, 'Jusques à quand jugerez-vous selon l’iniquité, et aurez-vous égard à la face des pécheurs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 3, 'Jugez l’orphelin et le pauvre; justifiez l’humble et l’indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 4, 'Délivrez l’indigent, et retirez le pauvre de la main du pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 5, 'Ils ne savent pas, ils n’ont point compris; ils cheminent dans les ténèbres; tous les fondements de la terre seront ébranlés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 6, 'Et moi j’ai dit: Vous êtes dieux, et tous fils du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 7, 'Cependant vous mourrez comme des hommes, et vous tomberez comme l’un des princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 81, 8, 'Levez-vous, ô Dieu, jugez la terre; car toutes les nations seront votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 1, 'Psaume d’Asaph, pour être chanté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 2, 'Ô Dieu, qui sera semblable à vous? Ne gardez point le silence, ô Dieu, ne vous tenez pas en repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 3, 'Car voilà que vos ennemis ont crié, et que ceux qui vous haïssent ont levé la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 4, 'Ils ont formé de perfides conseils, ils ont conspiré contre vos saints;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 5, 'Ils ont dit: Venez, et bouleversons-les; qu’ils ne soient plus une nation, et que l’on ne se souvienne plus du nom d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 6, 'Ils ont délibéré unanimement; ils ont fait ensemble alliance contre vous:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 7, 'Les tentes des Iduméens, et les Ismaélites, et Moab, et les Agaréniens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 8, 'Et Gébal, et Ammon, et Amalec, et les étrangers avec les habitants de Tyr;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 9, 'Assur aussi est venu avec eux; ils sont les auxiliaires des fils de Lot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 10, 'Faites-leur comme à Madian et Sisara, et comme à Jabin au torrent de Cison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 11, 'Ils furent détruits à Endor; ils devinrent comme le fumier de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 12, 'Traitez leurs princes comme Oreb et Zeb, et Zébée et Salmana, tous leurs princes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 13, 'Qui ont dit: Possédons en héritage le sanctuaire de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 14, 'Mon Dieu, faites qu’ils soient comme une roue, comme la paille devant la face du vent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 15, 'Tel un feu brûle la forêt; telle une flamme incendie les montagnes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 16, 'Ainsi vous les poursuivrez de votre tempête, et vous les troublerez en votre colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 17, 'Remplissez leur face d’ignominie, et ils chercheront votre nom, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 18, 'Qu’ils rougissent de honte et soient remplis de trouble dans les siècles des siècles; qu’ils soient confondus, et qu’ils périssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 82, 19, 'Et qu’ils connaissent que votre nom est le Seigneur, et que seul vous êtes le Très-Haut sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 1, 'Pour être chanté sur les pressoirs, psaume du fils de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 2, 'Que vos tabernacles sont aimables, Seigneur, Dieu des armées!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 3, 'Mon âme succombe à désirer les parvis du Seigneur; mon cœur et ma chair ont tressailli dans le Dieu vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 4, 'Car le passereau a trouvé pour lui une demeure, et la tourterelle un nid où elle dépose sa couvée. Vos autels, Seigneur, Dieu des armées, ô mon roi, ô mon Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 5, 'Heureux ceux qui demeurent en votre maison; ils vous loueront dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 6, 'Heureux l’homme dont l’aide vient de vous, Seigneur; il a disposé en son cœur des degrés pour monter');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 7, 'En la vallée des pleurs, au lieu que le Seigneur a établi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 8, 'Car le législateur leur donnera des bénédictions; ils iront de vertus en vertus, et le Dieu des dieux leur apparaîtra en Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 9, 'Seigneur, Dieu des armées, écoutez ma prière; prêtez-moi l’oreille, Dieu de Jacob!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 10, 'Notre protecteur, ô mon Dieu, voyez et regardez la face de votre Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 11, 'Car un seul jour dans vos parvis est meilleur qu’un millier de jours; j’ai mieux aimé être humble dans la maison de Dieu que d’habiter sous les tentes des pécheurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 12, 'Parce que le Seigneur aime la miséricorde et la vérité; Dieu est le distributeur de la grâce et de la gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 83, 13, 'Dieu ne fera pas attendre ses biens à ceux qui marchent dans l’innocence; Seigneur, Dieu des armées, heureux l’homme qui espère en vous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 1, 'Pour être chanté; psaume des fils de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 2, 'Seigneur, vous avez béni votre terre; vous avez ramené Jacob de la captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 3, 'Vous avez remis ses iniquités à votre peuple; vous avez couvert sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 4, 'Vous avez apaisé votre colère; vous avez détourné la force de votre courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 5, 'Convertissez-nous, ô Dieu notre salut; détournez de nous votre colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 6, 'Serez-vous à jamais irrité contre nous; étendrez-vous votre colère sur les générations des générations?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 7, 'O mon Dieu, en vous tournant vers nous, vous nous vivifierez, et votre peuple se réjouira en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 8, 'Seigneur, montrez-nous votre miséricorde, et accordez-nous votre salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 9, 'J’écouterai ce que dira en moi le Seigneur Dieu; car il parlera de la paix à son peuple et à ses saints, et à ceux qui tournent leur cœur vers lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 10, 'Son salut est près de ceux qui le craignent, et sur notre terre habite sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 11, 'La miséricorde et la vérité se sont rencontrées; la justice et la paix se sont embrassées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 12, 'La vérité est née de la terre, et la justice a regardé du haut du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 13, 'Car le Seigneur nous donnera sa bienveillance, et notre terre donnera son fruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 84, 14, 'La justice marchera devant le Seigneur, et mettra ses pieds dans la voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 1, 'Inclinez votre oreille, Seigneur, et exaucez-moi; car je suis pauvre et nécessiteux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 2, 'Veillez sur mon âme, car je suis saint; sauvez, ô Dieu, votre serviteur qui espère en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 3, 'Ayez pitié de moi, Seigneur; car tout le jour j’ai crié vers vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 4, 'Réjouissez l’âme de votre serviteur; car j’ai élevé, Seigneur, mon âme vers vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 5, 'Seigneur, vous êtes bienveillant et doux, et vos miséricordes sont abondantes envers ceux qui vous invoquent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 6, 'Seigneur, prêtez l’oreille à ma prière, et soyez attentif à la voix de ma supplication.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 7, 'Au jour de mon affliction, j’ai crié vers vous, parce que vous m’avez exaucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 8, 'Nul n’est semblable à vous parmi les dieux, Seigneur, et nul n’a fait d’œuvres comme les vôtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 9, 'Toutes les nations que vous avez faites viendront, et se prosterneront devant vous, Seigneur; et elles glorifieront votre nom,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 10, 'Parce que vous êtes grand, et que vous faites des merveilles; vous êtes le seul grand Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 11, 'Guidez-moi, Seigneur, en votre voie, et je cheminerai en votre vérité; que mon cœur se réjouisse d’avoir craint votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 12, 'Je vous rendrai grâces, ô mon Dieu, de tout mon cœur, et je glorifierai votre nom éternellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 13, 'Car votre miséricorde est grande envers moi, et vous avez retiré mon âme du plus profond des enfers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 14, 'O Dieu, les méchants se sont insurgés contre moi, et l’assemblée des puissants a cherché ma vie; et ils ne vous ont pas mis devant leurs yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 15, 'Et vous, Seigneur, vous avez été compatissant et miséricordieux, longanime, abondant en miséricorde et en vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 16, 'Jetez un regard sur moi, et ayez pitié de moi; donnez votre force à votre serviteur, et sauvez le fils de votre servante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 85, 17, 'Faites sur moi un signe favorable, et que ceux qui me haïssent le voient, et qu’ils soient confondus; car, Seigneur, vous êtes venu à mon secours, et vous m’avez consolé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 86, 1, 'Les fondements de Sion sont sur les montagnes saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 86, 2, 'Le Seigneur aime ses portes plus que toutes les tentes de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 86, 3, 'On a dit de toi des choses glorieuses, ô cité de Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 86, 4, 'Je rappellerai Raab et Babylone à ceux qui me connaissent. Et voilà que les étrangers et Tyr, et le peuple des Éthiopiens s’y sont réunis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 86, 5, 'Un homme dira: Ma mère est Sion; et cet homme y est né, et le Très-Haut lui-même en a été le fondateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 86, 6, 'Le Seigneur racontera cela dans l’écrit des peuples et des princes qui sont nés dans Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 86, 7, 'Habiter en Sion, c’est habiter dans la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 1, 'Psaume des fils de Coré, pour être chanté, sur Maeleth, pour l’intelligence d’Eman l’Israélite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 2, 'Seigneur, Dieu de mon salut, j’ai crié devant vous, le jour et la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 3, 'Que mon oraison pénètre en votre présence; inclinez votre oreille vers ma prière, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 4, 'Car mon âme a été remplie de maux, et ma vie s’est approchée de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 5, 'J’ai été compté parmi ceux qui descendent dans la fosse; je suis devenu comme un homme sans secours,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 6, 'Libre parmi les morts, comme ceux qui tombent mortellement blessés, qui dorment dans le sépulcre, et dont vous ne vous souvenez plus; ceux-là aussi ont été repoussés par votre main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 7, 'On m’a mis au plus profond de la fosse, dans les ténèbres et dans l’ombre de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 8, 'Votre colère s’est appesantie sur moi, et vous avez fait passer sur moi tous vos flots.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 9, 'Vous avez éloigné de moi mes proches; ils m’ont eu en abomination. J’ai été livré, et je n’ai pu sortir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 10, 'Mes yeux ont été affaiblis par la misère. Et j’ai crié vers vous tout le jour, Seigneur; j’ai étendu vers vous les mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 11, 'Ferez-vous des prodiges pour les morts? ou des médecins les ressusciteront-ils, afin qu’ils vous louent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 12, 'Quelqu’un dans le sépulcre publiera-t-il votre miséricorde, ou votre vérité dans la perdition?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 13, 'Dans les ténèbres, connaîtra-t-on vos merveilles? Et votre justice est-elle dans une terre oubliée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 14, 'Et moi, Seigneur, j’ai crié vers vous; et dès l’aurore ma prière vous parviendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 15, 'Pourquoi, Seigneur, rejetez-vous ma prière et détournez-vous de moi votre face?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 16, 'Je suis pauvre, et dans les labeurs depuis ma jeunesse; mais après avoir été exalté, j’ai été humilié et confondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 17, 'Sur moi ont passé vos colères, et vos épouvantements m’ont troublé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 18, 'Ils m’ont entouré comme des flots; durant tout le jour, ils m’ont assiégé tous à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 87, 19, 'Vous avez écarté de moi tout ami et mes proches de ma misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 1, 'De l’intelligence d’Étham l’Israélite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 2, 'Je chanterai éternellement vos miséricordes, ô Seigneur; de génération en génération ma bouche annoncera votre vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 3, 'Car vous avez dit: La miséricorde sera édifiée pour tous les siècles; votre vérité sera établie dans les cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 4, 'J’ai fait alliance avec mes élus; j’ai juré à David mon serviteur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 5, 'Durant tous les siècles, j’établirai ta race, et j’édifierai ton trône pour les générations des générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 6, 'Les cieux témoigneront de vos merveilles, Seigneur, et de votre vérité dans l’assemblée des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 7, 'Qui, dans les nuées, sera l’égal du Seigneur? Qui sera semblable au Seigneur parmi les fils de Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 8, 'Dieu est glorifié dans le conseil des saints; il est grand et redoutable pour tous ceux qui l’entourent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 9, 'Seigneur, Dieu des armées, qui vous ressemble? Vous êtes puissant, Seigneur, et votre vérité est à l’entour de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 10, 'Vous dominez la puissance de la mer, et vous apaisez la fureur de ses flots.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 11, 'Vous avez humilié le superbe, comme un homme blessé, et par le bras de votre force vous avez dispersé vos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 12, 'À vous sont les cieux, à vous la terre; vous avez fondé l’univers et les êtres qu’il contient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 13, 'Vous avez créé l’aquilon et la mer; Hermon et Thabor, à votre nom, tressailliront d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 14, 'Votre bras est inséparable de la puissance; que votre main s’affermisse; que votre droite soit exaltée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 15, 'La justice et le jugement sont les bases de votre trône; la miséricorde et la vérité marcheront devant votre face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 16, 'Heureux le peuple qui connaît les cris de joie; Seigneur, il cheminera en la lumière de votre visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 17, 'Et tout le jour il tressaillira d’allégresse à votre nom; et il sera exalté dans votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 18, 'Car vous êtes la gloire de leur force; et, en votre bon plaisir, notre front sera exalté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 19, 'Notre aide vient du Seigneur, du Saint d’Israël, notre Roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 20, 'Autrefois vous avez parlé à vos fils en une vision; et vous avez dit: J’ai mis mon aide sur le puissant; j’ai exalté l’élu de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 21, 'J’ai trouvé David, mon serviteur; je l’ai oint en ma sainte miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 22, 'Car ma main le secourra, et mon bras le fortifiera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 23, 'Nul ennemi ne réussira contre lui, et le fils de l’iniquité ne se présentera point pour l’affliger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 24, 'Et je frapperai ses ennemis devant sa face, et je mettrai en fuite ceux qui le haïssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 25, 'Et ma vérité et ma miséricorde sont avec lui; et en mon nom, sa puissance sera exaltée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 26, 'Et je poserai sa main gauche sur la mer, et sa droite sur les fleuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 27, 'Il m’invoquera, disant: Vous êtes mon père, Ô mon Dieu, et le défenseur de mon salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 28, 'Et moi je le tiendrai pour mon premier-né; je l’élèverai au-dessus des rois de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 29, 'Dans tous les siècles, je lui garderai ma miséricorde, et mon alliance lui sera fidèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 30, 'Et j’affermirai sa race dans les siècles des siècles, et son trône comme les jours du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 31, 'Si ses fils abandonnent ma loi, s’ils ne marchent point selon mes commandements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 32, 'S’ils profanent mes préceptes, s’ils ne gardent pas mes ordonnances,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 33, 'Je visiterai leurs iniquités avec ma verge, et leurs péchés avec mon fouet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 34, 'Mais je n’éloignerai pas entièrement de lui ma miséricorde, et je ne ferai point tort à ma vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 35, 'Je ne violerai point mon alliance, et ce qui est sorti de mes lèvres, je ne le révoquerai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 36, 'J’ai juré une fois par ma sainteté que je ne mentirais pas à David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 37, 'Sa postérité durera dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 38, 'Son trône sera devant moi comme le soleil et comme la lune, et il y en a un témoin fidèle dans les cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 39, 'Cependant, Seigneur, vous avez repoussé et méprisé, vous avez rejeté votre Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 40, 'Vous avez aboli l’alliance faite avec votre serviteur; vous avez profané sa sainteté sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 41, 'Vous en avez abattu les clôtures, et de ses défenses vous avez fait un épouvantail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 42, 'Tous ceux qui ont passé par le chemin l’ont pillé; il est devenu un opprobre pour ses voisins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 43, 'Vous avez exalté la droite de ses ennemis; vous les avez tous réjouis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 44, 'Vous avez ôté la force à son glaive, et dans la guerre vous ne l’avez point secouru.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 45, 'Vous avez terni sa pureté; vous avez brisé son trône contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 46, 'Vous avez abrégé les jours de son règne; vous avez versé sur lui la honte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 47, 'Jusques à quand, Seigneur, vous détournerez-vous pour notre perte? Jusques à quand votre colère brûlera-t-elle comme un feu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 48, 'Souvenez-vous de ma substance; est-ce donc en vain que vous avez créé tous les enfants des hommes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 49, 'Quel est l’homme qui vivra et ne verra point la mort, qui retirera son âme de la main de l’enfer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 50, 'Où sont, Seigneur, vos antiques miséricordes que vous aviez promises à David, en votre vérité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 51, 'Souvenez-vous, Seigneur, de l’opprobre que j’ai renfermé en mon sein, et que vos serviteurs ont souffert de la part de maintes nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 52, 'Cet opprobre, ô Seigneur, est venu de vos ennemis; ils nous imputent à opprobre la récompense de votre Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 88, 53, 'Béni soit le Seigneur dans l’éternité. Ainsi soit-il! Ainsi soit-il!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 1, 'Seigneur, vous avez été notre refuge de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 2, 'Vous êtes dans les siècles des siècles, avant la création des montagnes, et de la terre et du monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 3, 'Ne faites point retomber l’homme en son humiliation, vous qui avez dit: Convertissez-vous, fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 4, 'Car des milliers d’années sont à vos yeux comme le jour d’hier qui s’est écoulé, et comme une veille de la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 5, 'Leurs années seront comme un néant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 6, 'Que l’homme passe le matin comme la verdure; que le matin il fleurisse et passe; que le soir il tombe, soit foulé et se dessèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 7, 'Car nous avons défailli devant votre colère; nous avons été troublés par votre courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 8, 'Vous avez mis nos iniquités devant votre face, et notre vie à la clarté de votre visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 9, 'Et tous nos jours se sont évanouis, et nous avons défailli devant votre colère. Et nos années sont tissues comme une toile d’araignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 10, 'Les jours de nos années font soixante-dix ans; et pour les forts, quatre-vingts; et au delà, ce n’est que peine et labeur. Alors la faiblesse nous vient et nous adoucit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 11, 'Qui peut connaître la force de votre colère, et mesurer la terreur qu’elle inspire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 12, 'Manifestez-nous donc votre droite, et instruisez nos cœurs dans la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 13, 'Revenez à nous, ô Seigneur: jusques à quand ...? Venez consoler vos serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 14, 'Nous avons, dès l’aurore, été remplis de votre miséricorde, et nous avons tressailli, et nous avons été pleins de délices tous les jours de notre vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 15, 'Nous nous sommes réjouis en retour des jours d’humiliation et des années mauvaises que nous avons vues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 16, 'Jetez un regard sur vos serviteurs et sur vos œuvres, et dirigez leurs fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 89, 17, 'Et soit sur nous la clarté du Seigneur notre Dieu; Seigneur, dirigez vous-même les travaux de nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 1, 'Celui qui demeure en la protection du Très-Haut habitera en un séjour abrité par le Dieu du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 2, 'Il dira au Seigneur: Vous êtes mon auxiliaire et mon refuge, ô mon Dieu. J’espérerai en lui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 3, 'Car il te délivrera des filets des chasseurs et des paroles amères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 4, 'Il te couvrira de l’ombre de ses ailes, et sous ses ailes tu auras l’espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 5, 'Sa vérité t’environnera comme une armure; tu n’auras rien à craindre des épouvantements de la nuit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 6, 'Ni des traits qui volent en plein jour, ni des choses qui cheminent dans les ténèbres, ni des accidents, ni du démon du midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 7, 'Mille tomberont à ta gauche, et dix mille à ta droite; mais ils n’approcheront point de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 8, 'Cependant, tu considèreras de tes yeux, et tu verras la punition infligée aux pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 9, 'Car tu as dit: Seigneur, vous êtes mon espérance; et tu as fait du Très-Haut ton refuge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 10, 'Les maux n’arriveront point jusqu’à toi, et les flagellations n’approcheront point de ta tente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 11, 'Car il a donné des ordres à ses anges, pour qu’ils te gardent en toutes tes voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 12, 'Ils te soulèveront de leurs mains, de peur que tes pieds ne heurtent contre une pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 13, 'Tu marcheras sur l’aspic et sur le basilic, et tu fouleras aux pieds le lion et le dragon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 14, 'Car le Seigneur a dit: Il a espéré en moi, et je le délivrerai; je l’abriterai, parce qu’il a connu mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 15, 'Il m’invoquera, et moi je l’exaucerai; je serai avec lui en ses tribulations; et je le délivrerai, et je le glorifierai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 90, 16, 'Je le remplirai de longs jours, et je lui montrerai mon salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 1, 'Psaume pour être chanté le jour du Sabbat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 2, 'Il est bon de proclamer le Seigneur, et de chanter votre nom, Dieu Très-Haut,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 3, 'Et d’annoncer le matin votre miséricorde, la nuit votre vérité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 4, 'Sur la harpe à dix cordes, en chantant sur la cithare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 5, 'Car vous m’avez rempli de délices, Seigneur, dans votre création, et les œuvres de vos mains me feront tressaillir d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 6, 'Que vos œuvres, ô Seigneur, sont magnifiques! que vos pensées sont impénétrables!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 7, 'L’imprudent ne les connaîtra pas, et l’insensé ne les comprendra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 8, 'Quand les pécheurs croissaient comme l’herbe des champs, alors tous les ouvriers d’iniquité ont paru avec eux; mais pour être exterminés dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 9, 'Pour vous, Très-Haut, vous, Seigneur, vous êtes éternellement!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 10, 'Car voilà que vos ennemis périront, et les ouvriers d’iniquité seront tous dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 11, 'Et mon front sera exalté comme celui de la licorne; et je passerai ma vieillesse en une abondante miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 12, 'Et mon œil a méprisé mes ennemis, et mon oreille entendra les méchants qui s’élèvent contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 13, 'Le juste fleurira comme le palmier; il se multipliera comme le cèdre du Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 14, 'Ceux qui sont plantés dans la maison du Seigneur fleuriront dans les parvis de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 15, 'Et ils se multiplieront en une riche vieillesse, et ils seront heureux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 91, 16, 'Afin d’annoncer que le Seigneur, notre Dieu, est juste, et qu’il n’est point en lui d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 92, 1, 'Le Seigneur règne, il s’est revêtu de beauté; le Seigneur s’est revêtu de force, et il s’en est fait une ceinture; car il a affermi le globe de la terre, qui ne sera plus ébranlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 92, 2, 'Votre trône fut dès lors établi; vous êtes de toute éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 92, 3, 'Les fleuves, Seigneur, les fleuves ont élevé leur voix');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 92, 4, 'Au-dessus de la voix des grandes eaux. Les mers sont admirables; le Seigneur est admirable dans les hauteurs des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 92, 5, 'Vos témoignages ont inspiré une foi sans bornes. A votre demeure convient la sainteté, Seigneur, dans la longue suite des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 1, 'Le Seigneur Dieu des vengeances, le Dieu des vengeances a agi librement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 2, 'Levez-vous, ô vous qui jugez la terre; rétribuez les superbes comme ils le méritent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 3, 'Jusques à quand, mon Dieu, subsisteront les pécheurs; jusques à quand les pécheurs se glorifieront-ils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 4, 'Ils parleront, et ils diront des choses iniques; ainsi parleront tous les ouvriers d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 5, 'Seigneur, ils ont humilié votre peuple, et ils ont tourmenté votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 6, 'Ils ont tué la veuve et l’orphelin, et ils ont mis à mort l’étranger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 7, 'Et ils ont dit: Le Seigneur ne le verra pas; le Dieu de Jacob ne s’en apercevra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 8, 'Comprenez maintenant, peuples fous et sans raison: soyez sages enfin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 9, 'Celui qui a créé l’oreille n’entendra-t-il pas? Celui qui a créé l’œil ne verra-t-il point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 10, 'Celui qui châtie les nations ne punira-t-il pas, lui qui apprend la science à l’homme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 11, 'Le Seigneur connaît les pensées des hommes, et il sait qu’elles sont vaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 12, 'Seigneur, heureux l’homme que vous-même avez instruit, et à qui vous enseignerez votre loi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 13, 'Pour le traiter avec douceur après les mauvais jours, jusqu’à ce que soit creusée la fosse du pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 14, 'Car le Seigneur ne répudiera pas son peuple; et il ne délaissera pas son héritage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 15, 'Jusqu’à ce que sa justice apparaisse dans le jugement, et qu’il en fasse jouir tous ceux qui ont le cœur droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 16, 'Qui s’élèvera pour moi contre les pécheurs, ou qui m’assistera contre les ouvriers d’iniquité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 17, 'Si le Seigneur ne m’eût aidé, peu s’en est fallu que mon âme n’ait habité l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 18, 'Si je disais: Mon pied a été ébranlé, votre miséricorde me secourait, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 19, 'Seigneur, votre amour a consolé mon âme, selon la multitude de mes douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 20, 'Le siége de l’iniquité peut-il se dresser près de vous, quand vous attachez la peine à vos préceptes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 21, 'Ils tendront des filets pour prendre l’âme des justes, et ils condamneront le sang innocent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 22, 'Mais le Seigneur est devenu pour moi un refuge, et mon Dieu est l’appui de mon espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 93, 23, 'Et il rétribuera leur injustice et leur méchanceté; le Seigneur notre Dieu les punira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 1, 'Venez, réjouissons-nous dans le Seigneur; poussons des cris de joie vers Dieu, notre Sauveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 2, 'Présentons-nous devant sa face pour lui rendre grâces, et chantons-lui des psaumes avec allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 3, 'Car c’est un grand Dieu que le Seigneur, et un roi plus grand que tous les dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 4, 'Le Seigneur ne répudiera point son peuple; il tient en sa main les confins de la terre, et les cimes des monts sont à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 5, 'La mer lui appartient: c’est lui qui l’a faite, et ses mains ont formé la terre ferme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 6, 'Venez, prosternons-nous devant lui pour l’adorer; et pleurons devant le Seigneur qui nous a faits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 7, 'Car il est notre Dieu, et nous, nous sommes le peuple de son pâturage et les brebis de sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 8, 'Aujourd’hui, si vous entendez sa voix, n’endurcissez pas vos cœurs, comme au jour de la colère et de la tentation dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 9, 'Lorsque vos pères m’ont tenté, ils m’ont éprouvé, et ils ont vu mes œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 10, 'Pendant quarante ans, j’ai conservé ma colère contre cette génération, et j’ai dit: Ils s’égarent toujours en leur cœur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 94, 11, 'Et ils n’ont point connu mes voies. C’est pourquoi, en ma colère, j’ai juré qu’ils n’entreraient pas en mon repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 1, 'Chantez au Seigneur un cantique nouveau; que toute la terre chante au Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 2, 'Chantez au Seigneur; bénissez son nom; publiez avec joie son salut de jour en jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 3, 'Publiez aux gentils sa gloire, et ses merveilles à tous les peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 4, 'Car le Seigneur est grand et digne de louanges infinies; il est plus terrible que tous les dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 5, 'Car tous les dieux des gentils sont des démons; mais le Seigneur a créé les cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 6, 'Louanges et beauté sont en sa présence; la sainteté et la majesté sont en son sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 7, 'Tribus des gentils, rendez au Seigneur, rendez à Dieu gloire et honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 8, 'Rendez gloire au Seigneur et à son nom; prenez des victimes et entrez dans ses parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 9, 'Adorez le Seigneur en son temple saint, et que devant sa face tremble toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 10, 'Dites aux gentils Le Seigneur règne, car il a affermi le globe de la terre, et il ne sera plus ébranlé; il jugera les peuples avec droiture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 11, 'Que les cieux se réjouissent et que la terre tressaille d’allégresse; que la mer en sa plénitude soit émue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 12, 'Les champs et tout ce qu’ils renferment se réjouiront; alors tressailliront les arbres de la forêt');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 95, 13, 'Devant la face du Seigneur; car il vient, car il vient juger la terre. Il jugera le monde selon sa justice, et les peuples selon sa vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 1, 'Le Seigneur a régné; que la terre tressaille d’allégresse; que la multitude des îles se réjouisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 2, 'Les ténèbres et les nuées l’entourent; la justice et le jugement dirigent son trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 3, 'La flamme le précède, et dans son parcours elle brûlera ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 4, 'Les éclairs ont lui sur le globe de la terre; la terre les a vus et en a tremblé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 5, 'Les montagnes ont fondu, comme la cire, devant la face du Seigneur; toute la terre a fondu devant sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 6, 'Les cieux ont annoncé sa justice, et tous les peuples ont vu sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 7, 'Que tous ceux qui adorent des sculptures, et se glorifient dans leurs idoles, soient confondus! Et vous tous, ses anges, adorez-le!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 8, 'Sion l’a entendu, et elle s’est réjouie; et les filles de Juda ont tressailli d’allégresse à cause de vos jugements, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 9, 'Car vous êtes le Seigneur, le Très-Haut, sur toute la terre; vous êtes digne de louanges infinies, plus que tous les dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 10, 'Vous qui aimez le Seigneur, haïssez le mal; le Seigneur garde les âmes de ses saints, il les délivrera de la main des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 11, 'La lumière s’est levée pour le juste, et la joie pour ceux qui ont le cœur droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 96, 12, 'Justes, réjouissez-vous dans le Seigneur, et publiez la mémoire de sa sainteté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 1, 'Chantez au Seigneur un cantique nouveau, car le Seigneur a fait des œuvres merveilleuses; c’est pour lui que sa droite et son bras saint nous ont sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 2, 'Le Seigneur a fait connaître son salut; en présence des gentils, il a révélé sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 3, 'Il s’est souvenu de sa miséricorde pour Jacob, et de sa vérité en faveur de la maison d’Israël. Tous les confins de la terre ont vu le salut de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 4, 'O terre, poussez partout des cris de joie au Seigneur; chantez, tressaillez d’allégresse et entonnez des psaumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 5, 'Chantez au Seigneur sur la cithare; chantez-lui des psaumes avec vos cithares et vos voix,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 6, 'Au son des cors et des trompettes; chantez de joie en présence de notre Roi, le Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 7, 'Que la mer en sa plénitude soit émue, et le monde et ceux qui l’habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 8, 'Et les fleuves applaudiront, et les montagnes bondiront d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 97, 9, 'Car il est venu juger la terre. Il jugera le monde selon la justice, et les peuples selon l’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 1, 'Le Seigneur a régné, que les peuples exhalent leur colère; il est assis sur les chérubins, que la terre tremble!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 2, 'Le Seigneur est grand dans Sion; il est élevé au-dessus de tous les peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 3, 'Que l’on rende gloire à votre grand nom, parce qu’il est terrible et saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 4, 'L’honneur du roi aime la justice: vous avez établi l’équité; vous avez rendu la justice et le jugement en Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 5, 'Exaltez le Seigneur notre Dieu, et adorez l’escabeau de ses pieds; car il est saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 6, 'Moïse et Aaron ont été comptés parmi ses prêtres, et Samuel parmi ceux qui invoquent son nom. Ils invoquaient le Seigneur, et lui les exauçait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 7, 'Il leur parlait du milieu d’une colonne de nuée. Ils gardaient ses témoignages et les commandements qu’il donnait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 8, 'Seigneur notre Dieu, vous les avez écoutés; ô Dieu, vous leur avez été propice, même en vous vengeant de tous leurs desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 98, 9, 'Exaltez le Seigneur notre Dieu, et adorez-le sur sa montagne sainte; car le Seigneur notre Dieu est saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 99, 1, 'Ô terre, poussez partout des cris de joie au Seigneur. Servez le Seigneur dans la joie. Entrez en sa présence, pleins d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 99, 2, 'Sachez que le Seigneur, c’est Dieu même; c’est lui qui nous a faits, ce n’est pas nous; nous sommes son peuple et les brebis de son pâturage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 99, 3, 'Pénétrez dans ses portes avec des actions de grâces; dans ses parvis avec des chants. Louez-le, célébrez son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 99, 4, 'Car le Seigneur est doux, sa miséricorde est éternelle, et sa vérité demeure de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 99, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 1, 'Seigneur, je chanterai votre miséricorde et votre jugement; je chanterai un psaume,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 2, 'Et je marcherai avec intelligence dans la voie sans tache; quand viendrez-vous à moi? J’ai marché au milieu de ma maison, dans l’innocence de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 3, 'Je n’ai mis aucune œuvre mauvaise devant mes yeux; j’ai haï les prévaricateurs. Je ne me suis point attaché');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 4, 'Au cœur dépravé; et le méchant se détournant de moi, je ne l’ai point connu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 5, 'Celui qui venait en secret déchirer son prochain, je l’ai toujours poursuivi. Je n’ai point mangé avec des gens à l’œil superbe, au cœur insatiable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 6, 'Mes yeux s’arrêtent sur les fidèles de la terre, pour les faire asseoir avec moi; celui qui chemine dans la voie sans tache était mon ministre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 7, 'Le superbe n’a point séjourné en ma demeure; le parleur injuste n’a point réussi devant mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 100, 8, 'Le matin, je mettais à mort tous les pécheurs de la terre, afin d’exterminer dans la ville du Seigneur les ouvriers d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 1, 'Prière pour le pauvre, lorsqu’il aura été abandonné et qu’il épanchera ses vœux devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 2, 'Seigneur, exaucez ma prière, et que mon cri arrive jusqu’à vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 3, 'Ne détournez point de moi votre face; au jour de ma tribulation, penchez vers moi votre oreille; le jour où je vous invoquerai, exaucez-moi aussitôt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 4, 'Car mes jours se sont évanouis comme la fumée, et mes os ont été consumés comme des broussailles mortes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 5, 'J’ai été foulé aux pieds comme de l’herbe, et mon cœur s’est desséché, parce que j’ai oublié de manger mon pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 6, 'À force de gémir, mes os se sont collés à ma chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 7, 'Je suis devenu comme le pélican du désert; je suis devenu comme un hibou dans une masure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 8, 'J’ai perdu le sommeil, et me voici comme le passereau solitaire sur un toit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 9, 'Tout le jour, mes ennemis m’ont outragé, et ceux qui me louaient ont juré contre moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 10, 'Parce que je mangeais la cendre comme du pain, et qu’à mon breuvage je mêlais des larmes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 11, 'En face de votre colère et de votre fureur; car vous m’avez élevé, puis brisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 12, 'Mes jours ont décliné comme l’ombre, et moi je me suis flétri comme l’herbe fanée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 13, 'Mais vous, Seigneur, vous demeurez éternellement, et votre mémoire passe de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 14, 'Levez-vous, et ayez pitié de Sion; car le temps est venu d’avoir pitié d’elle; le temps en est venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 15, 'Car ses pierres mêmes ont plu à vos serviteurs, et ils pleurent sur sa poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 16, 'Et les gentils, Seigneur, craindront votre nom, et les rois votre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 17, 'Car le Seigneur édifiera Sion, et y sera vu en sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 18, 'Il a eu égard à la prière des humbles, et il n’a point méprisé leur supplication.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 19, 'Qu’on écrive ces choses pour la génération future, et le peuple d’alors louera le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 20, 'Car le Seigneur s’est penché des hauteurs de son lieu saint, et du ciel il a regardé la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 21, 'Pour ouïr les gémissements des captifs, pour délivrer les fils des hommes mis à mort,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 22, 'Afin qu’ils proclament dans Sion le nom du Seigneur, et sa louange dans Jérusalem;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 23, 'Lorsqu’en un même lieu peuples et rois seront rassemblés pour servir le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 24, 'Le peuple dans la voie de sa force lui a dit: Annoncez-moi la brièveté de mes jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 25, 'Ne me rappelez pas au milieu de mes jours, vous dont les années sont de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 26, 'Au commencement, Seigneur, vous avez créé la terre; et les cieux sont l’œuvre de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 27, 'Ils périront, et vous, vous subsisterez; ils vieilliront tous comme un manteau, et vous les roulerez comme un vêtement, et ils seront changés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 28, 'Seul vous êtes toujours le même, et vos années ne défailliront point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 101, 29, 'Les fils de vos serviteurs habiteront votre terre, et leur race y prospérera dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 1, 'Ô mon âme, bénis le Seigneur, et que tout ce qui est en moi bénisse son saint nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 2, 'Ô mon âme, bénis le Seigneur, et n’oublie aucune de ses louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 3, 'C’est lui qui te remet tes fautes et te guérit de toutes tes infirmités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 4, 'C’est lui qui rachète ta vie de la corruption, et te couronne en sa miséricorde et sa compassion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 5, 'C’est lui qui te rassasie de biens au gré de tes désirs; il renouvellera ta jeunesse comme celle de l’aigle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 6, 'Le Seigneur fait miséricorde et justice aux opprimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 7, 'Il a fait connaître ses voies à Moïse, et ses volontés aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 8, 'Le Seigneur est miséricordieux et compatissant, il est longanime et plein de miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 9, 'Il ne sera pas irrité sans fin; il ne sera pas éternellement indigné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 10, 'Il ne nous a point traités selon nos péchés, et il ne nous a point rétribués selon nos iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 11, 'Car autant le ciel est au-dessus de la terre, autant le Seigneur a confirmé sa miséricorde sur ceux qui le craignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 12, 'Autant il y a de distance de l’orient à l’occident, autant il a éloigné de nous nos iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 13, 'Et comme un père a compassion de ses fils, ainsi le Seigneur a compassion de ceux qui le craignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 14, 'Il sait de quelle matière nous sommes formés: souvenez-vous, Seigneur, que nous sommes poussière!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 15, 'Les jours de l’homme sont comme l’herbe des champs; il fleurira comme la plante sauvage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 16, 'L’esprit a passé en lui, et il n’est plus, et il ne reconnaîtra plus la place où il était.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 17, 'Mais la miséricorde du Seigneur est de siècles en siècles sur ceux qui le craignent; et sa justice sur les fils de leurs fils,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 18, 'Sur ceux qui gardent son alliance et se souviennent de ses commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 19, 'Le Seigneur a préparé son siège dans le ciel, et de son trône il domine sur toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 20, 'Bénissez le Seigneur, vous tous qui êtes ses anges, pleins de force, prompts à exécuter sa parole, à obéir à la voix de ses discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 21, 'Bénissez le Seigneur, vous qui êtes ses armées, vous qui êtes les ministres de ses volontés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 102, 22, 'Bénissez le Seigneur, vous qui êtes tous ses œuvres; en tous les lieux où il règne, ô mon âme, bénis le Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 1, 'O mon âme, bénis le Seigneur; Seigneur, ô mon Dieu, vous êtes très-grand, vous êtes revêtu de gloire et de beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 2, 'Vous êtes enveloppé de lumière comme d’un manteau; vous avez tendu le ciel comme un tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 3, 'Il a fait des eaux le toit de ses plus hautes demeures; il a posé les nuées pour être son char; il marche sur les ailes des vents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 4, 'Des esprits il fait ses anges, et ses serviteurs sont un feu ardent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 5, 'Il fonde la terre sur son axe; elle ne déviera pas dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 6, 'L’abîme, comme un vêtement, est son manteau, et les eaux s’arrêteront au-dessus des montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 7, 'Elles s’enfuiront, Seigneur, à vos reproches; elles auront peur, à la voix de votre tonnerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 8, 'Les montagnes sont montées et les plaines sont descendues au lieu que vous leur aviez marqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 9, 'Vous avez posé des limites que les eaux ne passeront pas; elles ne reviendront plus couvrir la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 10, 'Le Seigneur a fait jaillir des sources dans les vallées; les eaux couleront entre les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 11, 'Elles abreuveront toutes les bêtes fauves des champs; les onagres les chercheront pour apaiser leur soif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 12, 'Au-dessus d’elles, les oiseaux du ciel feront leur nid; ils feront entendre leur chant du milieu des rochers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 13, 'Des lieux supérieurs, Dieu arrose les monts; la terre se rassasiera, Seigneur, du fruit de vos œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 14, 'Vous faites pousser l’herbe pour le bétail, et le fourrage pour le service des hommes, afin qu’ils en fassent sortir le blé de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 15, 'Et le vin réjouit le cœur de l’homme; l’huile égaie son visage; le pain fortifie son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 16, 'Les arbres des champs seront nourris de ces pluies, ainsi que les cèdres du Liban, qu’il a plantés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 17, 'C’est là que les passereaux feront leur nid, et la famille du héron, qui les surpasse de la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 18, 'Les hauteurs des monts seront la demeure des cerfs, et les rochers l’asile du hérisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 19, 'Dieu a créé la lune pour marquer le temps; le soleil sait où il doit se coucher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 20, 'Vous avez fait les ténèbres, et la nuit est venue; c’est l’heure où toutes les bêtes fauves traversent la forêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 21, 'Les lionceaux rugissent après leur proie, et cherchent les aliments que Dieu leur a donnés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 22, 'Mais le soleil se lève; et ils se réunissent, et ils vont dormir dans leur antre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 23, 'Et l’homme s’en va à son travail, et il travaille jusqu’au soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 24, 'Que vos œuvres sont grandes, Seigneur; vous avez fait toutes choses avec sagesse; la terre est pleine de vos créatures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 25, 'La mer est profonde et spacieuse; des reptiles sans nombre y nagent, les petits avec les grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 26, 'Des navires la sillonnent; et le dragon, formé par vous, vient s’y jouer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 27, 'Tous espèrent en vous, pour que vous leur donniez la nourriture au temps opportun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 28, 'Vous la leur donnez, et ils la recueillent; vous ouvrez la main, et ils sont tous remplis des dons de votre bonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 29, 'Détournez-vous le visage, ils sont troublés; si vous leur ôtez le souffle, ils défailliront et retourneront à leur poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 30, 'Et si vous envoyez votre Esprit, ils seront créés, et vous renouvellerez la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 31, 'Que la gloire du Seigneur soit éternelle; le Seigneur se complaira dans ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 32, 'Il regarde la terre, et la fait trembler; il touche les monts, et ils fument.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 33, 'Je chanterai le Seigneur toute ma vie; je chanterai mes psaumes à Dieu, tant que j’existerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 34, 'Puisse ma voix lui être douce, et moi je me réjouirai dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 35, 'Puissent les pécheurs et les méchants défaillir sur la terre, et qu’ils ne soient plus! Ô mon âme, bénis le Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 103, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 1, 'Rendez grâces au Seigneur, et invoquez son nom; annoncez ses œuvres parmi les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 2, 'Chantez en son honneur, chantez-lui des psaumes; racontez toutes ses merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 3, 'Glorifiez-vous en son saint nom; que le cœur de ceux qui cherchent le Seigneur soit réjoui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 4, 'Cherchez le Seigneur, et soyez forts; cherchez perpétuellement sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 5, 'Souvenez-vous des prodiges qu’il a faits, de ses merveilles et des jugements de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 6, 'Enfants d’Abraham, qui êtes ses serviteurs, fils de Jacob, qui êtes ses élus,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 7, 'Le Seigneur est notre Dieu; ses jugements sont sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 8, 'Il s’est souvenu pour toujours de son alliance, de la parole qu’il a intimée à des milliers de générations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 9, 'Et qu’il a conclue avec Abraham; il s’est souvenu de son serment à Isaac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 10, 'Et cette alliance avec Jacob, il l’a érigée en commandement; et avec Israël, en testament éternel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 11, 'Disant Je te donnerai la terre de Chanaan, comme part de votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 12, 'Ils y étaient alors en petit nombre, et passagers en cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 13, 'Et ils allèrent d’une nation à une autre, et d’un royaume à un autre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 14, 'Et à nul homme Dieu ne permit de leur faire tort, et, à cause d’eux, il châtiait les rois, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 15, 'Gardez-vous de toucher à mes oints; gardezvous de maltraiter mes prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 16, 'Et il appela la famine sur la terre, et il brisa la force que donnait le pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 17, 'Et il envoya un homme devant eux, et Joseph fut vendu comme esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 18, 'Ils l’humilièrent, en mettant à ses pieds des entraves; et le fer traversa son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 19, 'Mais quand lui vint la parole du Seigneur, cette voix l’enflamma.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 20, 'Le roi, prince des peuples, envoya des hommes pour le délier, et il le mit en liberté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 21, 'Et il le constitua maître de sa maison et prince de ses richesses,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 22, 'Pour qu’il instruisît les grands comme lui-même, et enseignât la sagesse à ses anciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 23, 'Et Israël entra en Égypte, et Jacob habita en la terre de Cham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 24, 'Et Dieu multiplia extrêmement son peuple; et il l’affermit contre ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 25, 'Puis il changea le cœur de ceux-ci, afin qu’ils haïssent son peuple et usassent de fraude contre ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 26, 'Et il envoya Moïse son serviteur, et Aaron, son élu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 27, 'Il mit en eux les paroles de ses signes et de ses prodiges en la terre de Cham.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 28, 'Il envoya les ténèbres et l’obscurité; et ils s’irritèrent de ses paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 29, 'Il changea leurs eaux en sang, et il fit mourir leurs poissons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 30, 'Leur terre produisit des grenouilles, jusqu’aux chambres les plus retirées des princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 31, 'Il dit, et des mouches de chien et des moucherons vinrent dans toute leur contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 32, 'Il fit tourner leur pluie en grêle, et le feu dévora leur terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 33, 'Et il frappa leurs vignes et leurs figuiers, et brisa tous les arbres sur leur territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 34, 'Il dit, et des sauterelles et des chenilles vinrent en quantité innombrable;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 35, 'Et elles rongèrent toute l’herbe de la terre et en mangèrent tous les fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 36, 'Et il frappa tout premier-né de leur terre, prélude de toutes leurs peines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 37, 'Et il fit sortir les Hébreux avec de l’argent et de l’or, et parmi leurs tribus il n’y avait pas un infirme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 38, 'L’Égypte se réjouit de leur départ, parce que la crainte qu’elle avait d’eux était retombée sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 39, 'Le Seigneur étendit une nuée pour les couvrir, et un feu pour les éclairer la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 40, 'Ils demandèrent, et des cailles vinrent; et il les rassasia d’un pain venu du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 41, 'Il fendit le rocher, et les eaux jaillirent; des fleuves coulèrent sur une terre aride,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 42, 'Parce que le Seigneur se souvint de sa parole sainte, qu’il avait donnée à Abraham, son serviteur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 43, 'Et il délivra son peuple dans l’allégresse, et ses élus dans la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 44, 'Et il leur donna les régions des gentils, et ils héritèrent des travaux des peuples;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 104, 45, 'Afin qu’ils gardassent ses commandements, et recherchassent sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 1, 'Rendez grâces au Seigneur, parce qu’il est bon, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 2, 'Qui dira la puissance du Seigneur, qui fera entendre toutes ses louanges?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 3, 'Heureux ceux qui gardent ses jugements et qui font justice en tout temps!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 4, 'Souvenez-vous de nous, Seigneur, avec votre bonté pour votre peuple; visitez-nous avec votre salut;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 5, 'Afin que nous puissions avoir part aux biens de vos élus, nous réjouir de la joie de votre peuple, vous glorifier avec ceux de votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 6, 'Nous avons péché avec nos pères, nous avons violé votre loi, nous avons commis l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 7, 'Nos pères en Égypte ne comprirent point vos prodiges, et ils ne se souvinrent pas de l’abondance de votre miséricorde; et ils vous provoquèrent, en arrivant à la mer Rouge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 8, 'Et il les sauva pour la gloire de son nom, et pour manifester sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 9, 'Et il menaça la mer Rouge, et elle fut desséchée; et il les ramena dans l’abîme, comme dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 10, 'Et il les sauva des mains de ceux qui les haïssaient, et il les racheta, de la main de l’ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 11, 'L’eau couvrit ceux qui les opprimaient, et pas un d’eux n’échappa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 12, 'Et ils eurent foi en ses paroles, et ils chantèrent ses louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 13, 'Mais ils oublièrent bien vite ses œuvres; ils n’attendirent point son conseil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 14, 'Et ils furent pris de concupiscence dans la solitude, et ils tentèrent Dieu dans le désert sans eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 15, 'Et il leur accorda ce qu’ils demandaient, et il envoya la satiété dans leur âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 16, 'Et ils irritèrent Moïse dans le camp, et Aaron le saint du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 17, 'La terre s’ouvrit, et elle engloutit Dathan, et engouffra le rassemblement d’Abiron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 18, 'Et la flamme dévora leur synagogue, et le feu consuma les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 19, 'Et ils se firent un veau en Choreb, et ils adorèrent une image sculptée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 20, 'Et ils échangèrent leur gloire contre la statue d’un veau qui se repaît de fourrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 21, 'Ils oublièrent le Dieu qui les avait sauvés, qui avait fait de grandes choses en Égypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 22, 'Des prodiges en la terre de Cham, et des actions terribles sur la mer Rouge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 23, 'Et il dit qu’il les exterminerait, si Moïse, son élu, ne s’était placé devant lui, et n’eût brisé l’idole, pour détourner sa fureur et l’empêcher de les détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 24, 'Et ils méprisèrent comme rien la terre désirable, et n’eurent point foi en la parole de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 25, 'Et ils murmurèrent sous leurs tentes, et n’écoutèrent point la voix du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 26, 'Et il leva la main sur eux pour les abattre dans le désert,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 27, 'Et pour rejeter leur race parmi les nations, et les disperser en diverses régions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 28, 'Et ils se prostituèrent à Belphégor, et ils mangèrent des victimes sacrifiées aux morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 29, 'Et ils irritèrent Dieu par leurs désordres, et la ruine se multiplia chez eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 30, 'Et Phinéès se leva, et il apaisa le Seigneur, et la plaie cessa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 31, 'Et cela lui fut imputé à justice, de génération en génération, dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 32, 'Et ils irritèrent Dieu vers les eaux de contradiction, et Moïse eut à souffrir de leur part;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 33, 'Parce qu’ils avaient rempli son esprit d’une amertume qui s’échappa de ses lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 34, 'Ils n’exterminèrent point les nations, comme le Seigneur le leur avait dit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 35, 'Et ils se mêlèrent aux gentils, et ils apprirent leurs œuvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 36, 'Et ils servirent leurs idoles, et ce fut pour eux un sujet de chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 37, 'Et ils sacrifièrent aux démons leurs fils et leurs filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 38, 'Et ils versèrent le sang innocent, le sang de leurs fils et de leurs filles, qu’ils immolèrent aux sculptures de Chanaan. Et la terre fut pleine de carnage et de sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 39, 'Et elle fut souillée par leurs œuvres; et ils se prostituèrent en leurs passions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 40, 'Et le Seigneur s’enflamma de colère contre son peuple, et il eut en abomination son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 41, 'Et il les livra aux mains de leurs ennemis, et ceux qui les haïssaient devinrent leurs maîtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 42, 'Et leurs ennemis les opprimèrent, et ils furent humiliés sous leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 43, 'Souvent Dieu les sauva; mais ils l’irritèrent encore en leurs conseils, et ils furent humiliés dans leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 44, 'Et le Seigneur les vit en leurs tribulations, et il écouta leur prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 45, 'Et il se souvint de son alliance, et il se repentit en la plénitude de sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 46, 'Et il leur accorda ses miséricordes, en face de ceux qui les retenaient captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 47, 'Sauvez-nous, Seigneur notre Dieu, et rassemblez-nous du milieu des gentils, pour que nous proclamions votre saint nom et que nous mettions notre gloire à vous louer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 105, 48, 'Béni soit le Seigneur, Dieu d’Israël, dans tous les siècles des siècles, et tout le peuple dira: Ainsi soit-il! Ainsi soit-il!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 1, 'Rendez gloire au Seigneur, parce qu’il est bon, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 2, 'Qu’ainsi disent ceux qui ont été rachetés par le Seigneur, qu’il a délivrés de la main de leurs ennemis et rassemblés des contrées');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 3, 'Du levant et du couchant, de la mer et de l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 4, 'Ils ont erré dans le désert sans eau; ils n’y ont point trouvé le chemin d’une cité habitable,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 5, 'Et ils avaient faim, ils avaient soif; et leur âme était défaillante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 6, 'Et, dans leur tribulation, ils crièrent au Seigneur, et il les retira de leur détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 7, 'Et il les conduisit dans le droit chemin, afin qu’ils arrivassent à une cité habitable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 8, 'Qu’ils rendent gloire à la miséricorde du Seigneur et à ses prodiges en faveur des fils des hommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 9, 'Car il a rassasié leur âme vide, et rempli de biens leur âme affamée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 10, 'Assis dans les ténèbres et à l’ombre de la mort, ils étaient enchaînés par la pauvreté et le fer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 11, 'Parce qu’ils avaient provoqué les voix du Seigneur, et avaient irrité le conseil du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 12, 'Et leur cœur fut humilié dans leurs labeurs, et ils furent sans force, et nul n’était là pour les secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 13, 'Et dans leurs tribulations ils crièrent au Seigneur, et il les retira de leur détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 14, 'Et il les tira des ténèbres et de l’ombre de la mort, et brisa leurs chaînes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 15, 'Qu’ils rendent gloire au Seigneur de sa miséricorde et de ses prodiges en faveur des fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 16, 'Car il a fait voler en éclats les portes d’airain; il a brisé les verrous de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 17, 'Il les a aidés à sortir de la voie de leur iniquité; car, à cause de leurs infidélités, ils avaient été humiliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 18, 'Leur âme avait pris en abomination tout aliment, et déjà ils étaient près des portes de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 19, 'Et dans leurs tribulations ils crièrent au Seigneur, et il les sauva de leur détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 20, 'Et il envoya sa parole, et il les a guéris, et il les arrachés de leur perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 21, 'Qu’ils rendent gloire au Seigneur de sa miséricorde et de ses prodiges en faveur des fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 22, 'Et qu’ils lui offrent des oblations de louanges, et qu’ils annoncent ses œuvres avec des transports d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 23, 'Ceux qui voguent sur la mer dans leurs barques, et qui trafiquent au milieu des eaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 24, 'Ceux-là ont vu les œuvres du Seigneur, et ses merveilles dans l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 25, 'Il dit, et le vent impétueux de la tempête s’est levé, et les vagues ont bondi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 26, 'Elles montent jusqu’aux cieux et descendent jusqu’aux abîmes, et l’âme des matelots succombe à la violence du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 27, 'Ils sont troublés, ils chancellent comme des hommes ivres, et toute leur sagesse a été engloutie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 28, 'Et dans leur tribulation ils ont crié au Seigneur, et il les a retirés de leur détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 29, 'Et il a commandé à la tempête, et elle s’est changée en une brise légère, et les flots ont fait silence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 30, 'Et les hommes se sont réjouis de leur calme, et le Seigneur les a conduits au port désiré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 31, 'Qu’ils rendent gloire au Seigneur de sa miséricorde et de ses prodiges en faveur des fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 32, 'Qu’ils l’exaltent dans l’assemblée du peuple, et le louent sur le siège des anciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 33, 'Il a changé des fleuves en un désert, et des eaux jaillissantes en une terre altérée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 34, 'Et une terre fertile en un lieu saumâtre, à cause de la malice de ceux qui l’habitaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 35, 'Il a fait d’un désert un étang plein d’eau, et d’une terre sans eau des vallons arrosés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 36, 'Et il y a mis des affamés, et ils ont bâti des cités habitables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 37, 'Et ils ont ensemencé des champs, et ils ont planté des vignes, et ils en ont récolté les produits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 38, 'Et il les a bénis, et ils se sont prodigieusement multipliés, et il n’a pas amoindri le nombre de leur bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 39, 'Puis ils ont déchu, et ils ont été maltraités par les tribulations, les maux et la douleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 40, 'Et le mépris s’est répandu sur leurs princes, et Dieu les a laissés s’égarer en des lieux impraticables et sans voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 41, 'Et il a délivré le pauvre de sa misère, et il a traité sa famille comme des brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 42, 'Les justes le verront et en seront réjouis, et toute iniquité fermera sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 106, 43, 'Quel est le sage qui gardera ces choses, et comprendra les miséricordes du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 1, 'Psaume de David, pour être chanté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 2, 'Mon cœur est prêt, ô Dieu, mon cœur est prêt; je vais chanter des psaumes en ma gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 3, 'Réveillez-vous, ma harpe et ma cithare; je me lèverai dès l’aurore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 4, 'Seigneur, je vous rendrai gloire parmi les peuples; je vous chanterai des psaumes parmi les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 5, 'Car votre miséricorde est plus grande que les cieux; et votre vérité va jusqu’aux nues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 6, 'O Dieu, soyez exalté au-dessus des cieux; que votre gloire soit répandue sur toute la terre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 7, 'Afin que vos bien-aimés soient délivrés, sauvez-moi par votre droite, et exaucez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 8, 'Dieu a parlé dans son sanctuaire; je me réjouirai, et je partagerai Sichem, et je mesurerai le val des Tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 9, 'À moi est Galaad, à moi Manassé; Éphraïm est l’appui de ma tête; Juda est mon roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 10, 'Et Moab le vase de mon espérance. Je poserai ma sandale sur l’Idumée, les étrangers me sont soumis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 11, 'Qui me ramènera dans la ville forte? Qui me guidera jusqu’à la terre d’Édom?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 12, 'N’est-ce pas vous, ô Dieu, qui nous aviez repoussés; ô Dieu, qui ne sortiez plus à la tête de nos armées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 13, 'Donnez-nous votre secours pour nous tirer de la tribulation; car il est vain, le salut qui vient de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 107, 14, 'En Dieu nous mettons notre force, et lui-même réduira à néant nos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 1, 'Pour être chanté, psaume de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 2, 'Ô Dieu, ne passez point ma louange sous silence; car la bouche des pécheurs, la bouche des fourbes est ouverte contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 3, 'Ils ont parlé de moi avec une langue perfide; ils m’ont enveloppé de paroles de haine, et ils m’ont attaqué sans sujet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 4, 'Au lieu de m’aimer, ils me calomnient; et moi je priais;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 5, 'Et ils m’ont rendu le mal pour le bien, la haine pour l’amitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 6, 'Établissez sur mon ennemi un pécheur, et que le démon se tienne à sa droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 7, 'Lorsqu’on le jugera, qu’il s’en aille condamné, et que sa prière soit imputée à péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 8, 'Que ses jours soient abrégés, et qu’un autre reçoive sa dignité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 9, 'Que ses fils deviennent orphelins, et sa femme veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 10, 'Que ses enfants errent sans asile, qu’ils mendient, qu’ils soient chassés de leurs habitations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 11, 'Qu’un usurier extorque tout son bien, et que des étrangers bâtissent sur ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 12, 'Qu’il ne lui reste personne pour protecteur, personne qui ait pitié de ses orphelins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 13, 'Que ses enfants aillent à leur perte, et qu’en une seule génération son nom soit effacé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 14, 'Que le souvenir de l’iniquité de ses pères revive devant le Seigneur; et que le péché de sa mère ne soit point effacé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 15, 'Qu’ils soient toujours devant le Seigneur, et que leur mémoire périsse sur la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 16, 'En punition de ce qu’il n’a point songé à faire miséricorde,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 17, 'Et qu’il a poursuivi, pour le mettre à mort, un homme pauvre, mendiant, et plein de componction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 18, 'Il a aimé la malédiction, et elle viendra sur lui; il n’a point désiré la bénédiction, et elle s’éloignera de lui. Il s’est revêtu de la malédiction comme d’une tunique, et elle a pénétré comme l’eau dans ses entrailles, comme l’huile dans ses os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 19, 'Qu’elle soit pour lui comme le manteau dont il s’enveloppe, et comme la ceinture dont il est ceint toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 20, 'Telle sera la peine de ceux qui me calomnient devant Dieu, et qui disent des méchancetés contre mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 21, 'Et vous, Seigneur, Seigneur, agissez envers moi pour l’amour de votre nom; car votre miséricorde est douce. Protégez-moi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 22, 'Parce que je suis pauvre et nécessiteux, et que mon cœur est troublé au dedans de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 23, 'Je m’en vais comme l’ombre quand elle décline, et j’ai été ballotté comme une nuée de sauterelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 24, 'Mes genoux ont été énervés par le jeûne, et ma chair s’est altérée, faute d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 25, 'Et moi, je suis devenu un opprobre pour mes ennemis; ils m’ont vu, et ont secoué la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 26, 'Secourez-moi, Seigneur mon Dieu, et sauvez-moi selon votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 27, 'Et qu’ils sachent que c’est votre main, que c’est vous, Seigneur, qui avez agi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 28, 'Ils maudiront, et vous bénirez; que ceux qui m’attaqueront soient confondus, et votre serviteur sera réjoui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 29, 'Que nos calomniateurs soient couverts de honte, et enveloppés de honte comme d’un double manteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 30, 'Je rendrai gloire au Seigneur de toute la force de ma bouche, et je le louerai au milieu de la multitude,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 108, 31, 'Parce qu’il s’est placé à la droite du pauvre, pour me sauver de ceux qui persécutaient mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 109, 1, 'Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite, jusqu’à ce que j’aie fait de tes ennemis l’escabeau de tes pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 109, 2, 'Le Seigneur t’enverra de Sion le sceptre de ta puissance; règne au milieu de tes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 109, 3, 'Le principe est avec toi au jour de ta puissance, parmi les splendeurs de tes saints. Je t’ai engendré de mes entrailles, avant l’étoile du matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 109, 4, 'Le Seigneur l’a juré, et il ne s’en repentira pas tu es le prêtre éternel, selon l’ordre de Melchisédech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 109, 5, 'Le Seigneur est à votre droite; il a écrasé les rois le jour de sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 109, 6, 'Il jugera au milieu des nations; il les remplira de ruines; il brisera sur la terre la tête d’une grande multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 109, 7, 'Il boira sur son chemin l’eau du torrent, et, à cause de cela, il relèvera sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 1, 'Seigneur Dieu, je vous rendrai gloire de tout mon cœur, dans le conseil et l’assemblée des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 2, 'Les œuvres du Seigneur sont grandes et parfaites, selon toutes ses volontés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 3, 'Son œuvre est digne d’actions de grâces et de gloire; sa justice durera dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 4, 'Il a perpétué le mémorial de ses merveilles; le Seigneur est compatissant et miséricordieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 5, 'Il a donné la nourriture à ceux qui le craignent; il se souviendra éternellement de son alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 6, 'Il a fait connaître à son peuple la vertu de ses œuvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 7, 'Pour lui donner l’héritage des gentils; les œuvres de ses mains sont vérité et jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 8, 'Tous ses commandements sont stables et fidèles dans tous les siècles, pleins de vérité et de droiture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 9, 'Il a envoyé la rédemption à son peuple; il a intimé son alliance pour toujours; son nom est saint et redoutable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 110, 10, 'La crainte du Seigneur est le commencement de la sagesse; l’intelligence en est donnée à tous ceux qui la pratiquent; on le louera dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 1, 'Heureux l’homme qui craint le Seigneur; il se complaira en ses commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 2, 'Sa postérité sera puissante sur la terre; la génération des justes sera bénie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 3, 'La gloire et la richesse seront en sa demeure, et sa justice durera dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 4, 'La lumière s’est levée dans les ténèbres sur les cœurs droits; le Seigneur est tendre, compatissant et juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 5, 'L’homme bon est miséricordieux; il prête au pauvre; il dirigera ses discours avec discernement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 6, 'Car il ne sera jamais ébranlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 7, 'La mémoire du juste sera éternelle; il n’aura rien à craindre des discours méchants; son cœur est disposé à espérer dans le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 8, 'En lui son cœur est affermi. Il ne craindra point à la vue de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 9, 'Il a distribué et donné ses biens aux pauvres; sa justice demeure dans les siècles des siècles; son front sera élevé en gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 111, 10, 'Le pécheur le verra, et s’en irritera; il grincera des dents, et sera consumé; le désir des pécheurs périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 1, 'Louez le Seigneur, enfants, louez le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 2, 'Béni soit le nom du Seigneur, maintenant et dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 3, 'De l’Orient à l’Occident, le nom du Seigneur est digne de louange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 4, 'Le Seigneur est élevé sur toutes les nations; et sa gloire, au-dessus des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 5, 'Qui est comme le Seigneur notre Dieu, qui habite les hauteurs des cieux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 6, 'Et regarde les humbles dans le ciel et sur la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 7, 'Il retire l’indigent de la poussière, il relève le pauvre de la fange,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 8, 'Pour les faire asseoir avec les princes, avec les princes de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 112, 9, 'Il fait demeurer la femme stérile dans sa maison, où elle trouve les joies d’une mère en ses enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 1, 'Lorsque Israël sortit d’Égypte, et la maison de Jacob d’un peuple barbare,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 2, 'Juda devint son peuple saint, Israël sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 3, 'La mer le vit, et s’enfuit; le Jourdain retourna en arrière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 4, 'Les montagnes bondirent comme des béliers, et les collines comme des agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 5, 'Qu’avais-tu en toi, ô mer, pour fuir ainsi, et toi, Jourdain, pour retourner en arrière?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 6, 'Et vous, montagnes, pourquoi bondissiez-vous comme des béliers, et vous, collines, comme des agneaux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 7, 'La terre a tremblé à la face du Seigneur, à la face du Dieu de Jacob,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 8, 'Qui a changé la pierre en nappes d’eau, et la roche en fontaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 9, 'Non pas à nous, Seigneur, non pas à nous, mais à votre nom, donnez-en la gloire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 10, 'À cause de votre miséricorde et de votre vérité; de peur que les gentils ne viennent à dire: Où est leur Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 11, 'Notre Dieu est dans le ciel et sur la terre; tout ce qu’il a voulu, il l’a fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 12, 'Les idoles des gentils sont argent et or, œuvres de la main des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 13, 'Elles ont une bouche, et ne parleront pas; elles ont des yeux, et ne verront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 14, 'Elles ont des oreilles, et n’entendront pas; elles ont des narines, et ne sentiront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 15, 'Elles ont des mains, et ne toucheront pas; elles ont des pieds, et ne marcheront pas, et nul cri ne sortira de leur gosier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 16, 'Que ceux qui les font leur deviennent semblables, et tous ceux qui croient en elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 17, 'La maison d’Israël a espéré dans le Seigneur, il est son auxiliaire et son appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 18, 'La maison d’Aaron a espéré dans le Seigneur, il est son auxiliaire et son appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 19, 'Ceux qui craignent le Seigneur ont espéré dans le Seigneur; il est leur auxiliaire et leur appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 20, 'Le Seigneur s’est souvenu de nous, et nous a bénis; il a béni la maison d’Israël, il a béni la maison d’Aaron.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 21, 'Il a béni ceux qui craignent le Seigneur, les petits aussi bien que les grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 22, 'Que le Seigneur fasse plus encore pour vous, pour vous et pour vos enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 23, 'Soyez bénis du Seigneur, qui a fait le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 24, 'Le ciel des cieux est au Seigneur; mais la terre il l’a donnée aux fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 25, 'Les morts, Seigneur, ne vous loueront point, ni tous ceux qui descendent en enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 113, 26, 'Mais nous qui vivons, nous bénirons le Seigneur, maintenant, et dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 1, 'J’ai aimé, parce que le Seigneur exaucera la voix de ma prière;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 2, 'Parce qu’il a incliné vers moi son oreille, et tous les jours de ma vie je l’invoquerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 3, 'Les douleurs de la mort m’avaient environné; les périls de l’enfer m’avaient atteint. J’avais trouvé la souffrance et la tribulation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 4, 'Et j’ai invoqué le nom du Seigneur. Seigneur, délivrez mon âme!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 5, 'Le Seigneur est juste et compatissant, et notre Dieu fait miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 6, 'Le Seigneur garde les petits; j’avais été humilié, et il m’a sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 7, 'Ô mon âme, retourne à ton repos, car le Seigneur a été bon pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 8, 'Il a délivré mon âme de la mort, mes yeux des larmes, et mes pieds de la chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 9, 'Je me complairai en présence du Seigneur, en la terre des vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 114, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 1, 'J’ai cru, c’est pourquoi j’ai parlé; et j’avais été humilié à l’excès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 2, 'Or j’ai dit en mon extase: Tout homme est menteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 3, 'Que rendrai-je au Seigneur pour tous les biens qu’il m’a faits?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 4, 'Je prendrai le calice du salut, et j’invoquerai le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 5, 'Je rendrai mes vœux au Seigneur en face de tout son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 6, 'La mort de ses saints est précieuse aux yeux du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 7, 'O Seigneur, je suis votre serviteur, je suis votre serviteur et le fils de votre servante; vous avez rompu mes liens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 8, 'Je vous ferai un sacrifice de louanges, et j’invoquerai le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 9, 'Je rendrai mes vœux au Seigneur en face de tout son peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 10, 'Dans les parvis du Seigneur, au milieu de tes murs, ô Jérusalem!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 115, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 116, 1, 'Nations, louez toutes le Seigneur; peuples, louez-le tous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 116, 2, 'Car sa miséricorde est affermie sur nous, et la vérité du Seigneur demeure dans l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 1, 'Rendez gloire au Seigneur, parce qu’il est bon, et que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 2, 'Que la maison d’Israël dise qu’il est bon, et sa miséricorde éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 3, 'Que la maison d’Aaron dise qu’il est bon, et sa miséricorde éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 4, 'Que tous ceux qui craignent le Seigneur disent qu’il est bon, et sa miséricorde éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 5, 'Dans la tribulation j’ai invoqué le Seigneur, et il m’a exaucé, et il m’a mis au large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 6, 'Que le Seigneur soit mon auxiliaire, et je ne craindrai rien de ce que l’homme peut me faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 7, 'Que le Seigneur soit mon auxiliaire, et moi je mépriserai mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 8, 'Mieux vaut se confier au Seigneur que se confier à l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 9, 'Mieux vaut espérer dans le Seigneur qu’espérer dans les princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 10, 'Toutes les nations m’avaient environné; mais, au nom du Seigneur, je les ai repoussées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 11, 'Elles m’avaient enfermé dans un cercle pour m’envelopper; mais, au nom du Seigneur, je les ai repoussées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 12, 'Elles se pressaient autour de moi comme des abeilles autour d’un rayon de miel; elles lançaient des flammes, comme des épines en feu; mais, au nom du Seigneur, je les ai repoussées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 13, 'À leur choc j’ai craint de tomber, et le Seigneur m’a secouru.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 14, 'Le Seigneur est ma force et ma louange; c’est lui qui m’a sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 15, 'La voix de l’allégresse et du salut est sous les tentes des justes; la droite du Seigneur a fait œuvre de puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 16, 'La droite du Seigneur m’a élevé; la droite du Seigneur a fait œuvre de puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 17, 'Je ne mourrai point; mais je vivrai et je raconterai les œuvres du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 18, 'Le Seigneur m’a châtié pour me corriger; mais il ne m’a point livré à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 19, 'Ouvrez-moi les portes de la justice, et je les franchirai, et je rendrai gloire au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 20, 'C’est la porte du Seigneur, c’est par elle que les justes entreront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 21, 'Je vous rendrai gloire, parce que vous m’avez exaucé, et que vous avez été mon salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 22, 'La pierre que les constructeurs avaient rejetée est devenue la pierre angulaire de l’édifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 23, 'C’est le Seigneur qui a fait cela, et nos yeux en sont émerveillés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 24, 'Voici le jour qu’a fait le Seigneur; tressaillons et réjouissons-nous en ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 25, 'Seigneur, sauvez-moi; Seigneur, faites-moi prospérer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 26, 'Béni soit celui qui vient au nom du Seigneur. Nous vous avons bénis de la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 27, 'Dieu, c’est le Seigneur; il a brillé à nos yeux: célébrez une fête solennelle avec des rameaux touffus, et ombragez jusqu’aux cornes de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 28, 'Vous êtes mon Dieu, et je vous rendrai gloire; vous êtes mon Dieu, et je vous exalterai; je vous rendrai gloire, parce que vous m’avez exaucé, et que vous avez été mon salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 117, 29, 'Rendez gloire au Seigneur, parce qu’il est bon, et que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 1, 'Heureux ceux qui, dans leur voie, conservent l’innocence, et cheminent en la loi du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 2, 'Heureux ceux qui méditent ses témoignages, et qui le cherchent de toute leur âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 3, 'Car les ouvriers d’iniquité n’ont point marché dans ses voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 4, 'Vous avez intimé vos commandements, pour qu’ils soient scrupuleusement gardés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 5, 'Puissent mes voies être dirigées vers l’accomplissement de vos ordonnances!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 6, 'Alors je ne serai point confondu, puisque j’aurai eu les yeux sur tous vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 7, 'Je vous rendrai gloire en la droiture de mon cœur, de ce que j’aurai appris les jugements de votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 8, 'Je garderai vos ordonnances; ne me délaissez pas sans retour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 9, 'Comment le jeune homme maintiendra-t-il droite sa voie? En gardant vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 10, 'Je vous ai cherché de toute mon âme; ne me repoussez pas de vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 11, 'J’ai renfermé dans le secret de mon cœur toutes vos paroles pour ne point pécher contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 12, 'Vous êtes béni, Seigneur, enseignez-moi vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 13, 'J’ai publié de mes lèvres tous les jugements de votre bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 14, 'Je me suis complu dans la voie de vos témoignages, autant que dans la possession de toutes les richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 15, 'Je méditerai sur vos commandements, et je considèrerai vos voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 16, 'J’étudierai à vos préceptes, et je n’oublierai point vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 17, 'Récompensez votre serviteur; et je vivrai, et je garderai vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 18, 'Otez le voile de mes yeux, et je comprendrai les merveilles de votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 19, 'Je suis passager sur la terre, ne me cachez pas vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 20, 'Mon âme a brûlé, en tout temps, du désir de votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 21, 'Vous avez châtié les superbes; maudits soient ceux qui s’écartent de vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 22, 'Délivrez-moi de l’opprobre et du mépris, car j’ai recherché vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 23, 'Les princes se sont assis, et ils ont mal parlé de moi; mais votre serviteur méditait sur vos ordonnances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 24, 'Et vos témoignages sont mon étude, et vos conseils mon conseil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 25, 'Mon âme est attachée à la terre; vivifiez-moi selon votre promesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 26, 'Je vous ai fait connaître mes voies, et vous m’avez écouté; enseignez-moi vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 27, 'Apprenez-moi la voie de vos préceptes, et je méditerai sur vos merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 28, 'Mon âme s’est assoupie dans l’abattement; fortifiez-moi de vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 29, 'Éloignez de moi la voie de l’iniquité, et faitesmoi miséricorde à cause de votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 30, 'J’ai choisi la voie de la vérité, et je n’ai point oublié vos jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 31, 'Je me suis attaché à vos témoignages, Seigneur; ne m’humiliez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 32, 'J’ai couru dans la voie de vos commandements, lorsque vous avez dilaté mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 33, 'Faites, Seigneur, que la voie de vos commandements soit ma loi, et je la chercherai toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 34, 'Donnez-moi l’intelligence, et j’approfondirai votre loi, et je la garderai dans le fond de mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 35, 'Guidez-moi dans le sentier de vos commandements; car c’est celui-là que j’ai désiré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 36, 'Inclinez mon cœur vers vos témoignages, et non vers la convoitise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 37, 'Détournez mes yeux, pour qu’ils ne voient point les vanités; vivifiez-moi en votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 38, 'Confirmez votre parole en votre serviteur, pour qu’il craigne de vous déplaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 39, 'Otez-moi l’opprobre du péché que j’ai appréhendé; car vos jugements me sont délectables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 40, 'Voilà que j’ai désiré vos commandements; vivifiezmoi en votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 41, 'Seigneur, que votre miséricorde me vienne, et votre salut, comme vous me l’avez promis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 42, 'Et je pourrai répondre à ceux qui m’outragent, car j’ai espéré en vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 43, 'Ne retirez point à jamais de ma bouche la parole de vérité, car j’ai surabondamment espéré en vos jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 44, 'Et je garderai votre loi toujours, dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 45, 'Et je marchais au large, parce que j’avais recherché vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 46, 'Et devant les rois je parlais de vos témoignages, et je n’avais aucune honte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 47, 'Et je méditais vos commandements, que j’ai toujours tant aimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 48, 'Et j’ai levé les mains vers vos commandements, que j’aime, et j’ai médité sur vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 49, 'Souvenez-vous de vos paroles à votre serviteur; en elles vous m’avez donné d’espérer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 50, 'Elles m’ont consolé dans mon abaissement, et votre parole m’a vivifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 51, 'Les superbes ont agi envers moi avec une extrême injustice; mais je n’ai point dévié de votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 52, 'Je me suis souvenu, Seigneur, de vos jugements éternels, et j’ai été consolé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 53, 'Le découragement m’a pris, à la vue des pécheurs qui abandonnaient votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 54, 'Mais, dans le lieu de mon pèlerinage, je chantais encore vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 55, 'Je me souvenais de votre nom, Seigneur, pendant la nuit, et je gardais votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 56, 'Et cette grâce m’a été faite, parce que j’avais recherché vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 57, 'Vous êtes mon partage, Seigneur; j’ai dit que je garderais votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 58, 'J’ai demandé de toute mon âme à voir votre visage; faites-moi miséricorde selon votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 59, 'J’ai pensé à vos voies, et j’ai tourné mes pas vers vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 60, 'Je me suis préparé sans trouble à garder vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 61, 'Les liens des pécheurs m’ont enlacé; mais je n’ai point oublié votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 62, 'Au milieu de la nuit, je me levais pour vous rendre grâce de vos jugements et de vos ordonnances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 63, 'Je suis partisan de tous ceux qui vous craignent et qui gardent vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 64, 'La terre, Seigneur, est pleine de vos miséricordes; enseignez-moi tous vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 65, 'Seigneur, vous avez usé de bonté avec votre serviteur, selon votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 66, 'Enseignez-moi la bonté, la discipline et la science, parce que j’ai eu foi en vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 67, 'Avant d’être humilié, j’ai failli; aussi ai-je gardé votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 68, 'Vous êtes bon, Seigneur, et en votre bonté enseignez-moi vos ordonnances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 69, 'L’iniquité des superbes s’est multipliée contre moi; pour moi, j’approfondirai vos commandements au fond de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 70, 'Leur cœur s’est coagulé comme du laitage, et moi j’ai médité votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 71, 'Il est heureux pour moi que vous m’ayez humilié, pour que j’apprisse vos ordonnances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 72, 'La loi qui sort de votre bouche est meilleure pour moi que des millions d’or et d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 73, 'Ce sont vos mains qui m’ont formé et pétri; donnez-moi l’intelligence, et je m’instruirai de vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 74, 'Ceux qui vous craignent me verront, et ils seront réjouis, parce que j’ai surabondamment espéré en vos promesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 75, 'Seigneur, je sais que vos jugements sont la justice même, et que vous m’avez humilié selon votre vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 76, 'Et maintenant, que votre miséricorde me vienne et me console, comme vous l’avez promis à votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 77, 'Que vos miséricordes me viennent, et je vivrai, parce que votre loi est l’objet de ma méditation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 78, 'Qu’ils soient confondus, les superbes, parce qu’ils ont été injustes envers moi; pour moi, je méditerai sur vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 79, 'Que ceux qui vous craignent viennent à moi, et ceux qui connaissent vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 80, 'Qu’en vos préceptes mon cœur soit trouvé sans tache, pour que je ne sois point confondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 81, 'Mon âme s’est épuisée à réclamer votre secours, tant j’avais espéré en vos paroles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 82, 'Mes yeux se sont éteints dans l’attente de votre parole, disant: Quand me consolerez-vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 83, 'Me voici comme une outre pendant la gelée; et pourtant je n’ai point oublié vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 84, 'Combien votre serviteur comptera-t-il encore de jours? Quand jugerez-vous ceux qui me persécutent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 85, 'Les méchants m’ont raconté des choses vaines; mais ce n’était point comme votre loi, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 86, 'Tous vos commandements sont vérité; ils m’ont poursuivi injustement, protégez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 87, 'Peu s’en est fallu qu’ils ne m’aient achevé sur la terre; moi cependant je n’ai point délaissé vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 88, 'Vivifiez-moi selon votre miséricorde, et je garderai les témoignages de votre bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 89, 'Seigneur, votre parole demeure dans le ciel éternellement;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 90, 'Votre vérité passe de génération en génération; vous avez fondé la terre, et elle subsiste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 91, 'Comme vous l’avez réglé, le jour continue de paraître; car tout vous obéit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 92, 'Si votre loi n’était point ma continuelle étude, je périrais dans l’humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 93, 'Je n’oublierai jamais vos ordonnances, car en elles vous m’avez vivifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 94, 'Je suis à vous, sauvez-moi; car j’ai recherché vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 95, 'Les pécheurs m’ont épié pour me perdre; mais j’avais compris vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 96, 'J’ai vu la fin de toute œuvre, même la plus parfaite; seule votre loi est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 97, 'Que j’aime votre loi, Seigneur! elle est tout le jour l’objet de ma méditation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 98, 'Plus qu’à mes ennemis vous m’avez fait goûter votre loi, car elle est toujours devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 99, 'J’ai eu plus d’intelligence que ceux qui m’ont instruit, car vos témoignages sont ma méditation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 100, 'J’ai eu plus d’intelligence que les anciens, car j’ai cherché vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 101, 'J’ai détourné mes pieds de toute voie mauvaise, afin de garder vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 102, 'Je n’ai point dévié de vos jugements, parce que vous avez été mon législateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 103, 'Que vos paroles sont douces à mon palais! elles le sont plus que le miel à ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 104, 'Je tiens mon intelligence de vos préceptes; aussi ai-je en haine toute voie d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 105, 'Votre loi est la lampe de mes pieds et la lumière de mes sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 106, 'J’ai juré et résolu de garder les jugements de votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 107, 'J’ai été profondément humilié, Seigneur; vivifiez-moi selon votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 108, 'Seigneur, ayez pour agréables les offrandes volontaires de ma bouche, et enseignez-moi vos jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 109, 'Mon âme est toujours en vos mains, et je n’ai point oublié votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 110, 'Les pécheurs m’ont tendu des pièges, et je n’ai point dévié de vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 111, 'J’ai eu pour héritage éternel vos témoignages, et ils sont le tressaillement de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 112, 'J’ai incliné mon cœur à toujours agir selon vos ordonnances, en vue de ma rétribution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 113, 'Je hais les méchants, et j’aime votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 114, 'Vous êtes mon auxiliaire et mon appui; j’ai surabondamment espéré en vos promesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 115, 'Éloignez-vous de moi, pervers, et j’approfondirai les commandements de mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 116, 'Soutenez-moi, Seigneur, selon votre parole, et vivifiez-moi; et que je ne sois point confondu en mon attente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 117, 'Secourez-moi, et je serai sauvé, et je méditerai toujours sur vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 118, 'Vous avez réduit à néant tous ceux qui se sont éloignés de vos jugements, parce que leur pensée est inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 119, 'J’ai compté comme pécheurs tous les prévaricateurs de la terre; c’est pourquoi j’aime vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 120, 'Transpercez mes chairs de votre crainte, car j’ai toujours redouté vos jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 121, 'J’ai été droit dans mes jugements et ma justice; ne me livrez pas à ceux qui me nuisent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 122, 'Affermissez votre serviteur dans le bien; que les superbes ne le calomnient pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 123, 'Mes yeux ont défailli à force d’attendre mon salut et la parole de votre équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 124, 'Traitez votre serviteur selon votre miséricorde, et enseignez-moi vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 125, 'Je suis votre serviteur; donnez-moi l’intelligence, et je connaîtrai vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 126, 'Le temps d’agir est venu pour le Seigneur; car ils ont renversé votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 127, 'C’est pour cela que j’ai aimé vos commandements plus que l’or et la topaze.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 128, 'Aussi me suis-je dirigé selon vos commandements; j’ai pris en haine la voie de l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 129, 'Vos témoignages sont merveilleux; aussi mon âme les a recherchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 130, 'La manifestation de vos paroles éclairera et instruira les plus jeunes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 131, 'J’ai ouvert la bouche, et je suis resté haletant du désir de vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 132, 'Regardez-moi, et faites-moi miséricorde, comme il est juste envers ceux qui aiment votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 133, 'Dirigez mes pas selon votre parole, et que nulle iniquité ne soit maîtresse de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 134, 'Délivrez-moi des fausses accusations des hommes, et je garderai vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 135, 'Faites que brille votre visage sur votre serviteur, et enseignez-moi vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 136, 'Mes yeux se sont fondus en des torrents de larmes, parce que je n’avais point gardé votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 137, 'Vous êtes juste, Seigneur, et vos jugements sont droits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 138, 'Vous nous avez recommandé vos témoignages, comme étant la justice et la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 139, 'Votre zèle m’a consumé, parce que mes ennemis avaient oublié vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 140, 'Votre parole est éprouvée comme un feu ardent, et votre serviteur l’aime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 141, 'Et, quoique jeune et méprisé, je n’ai point oublié vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 142, 'Votre justice est la justice éternelle, et votre loi, la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 143, 'La tribulation et la détresse sont venues me trouver; vos commandements ont été ma méditation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 144, 'Vos témoignages sont une justice éternelle; donnez-m’en l’intelligence, et je vivrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 145, 'J’ai crié au fond de mon âme; exaucez-moi, Seigneur, et je rechercherai vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 146, 'J’ai crié vers vous; sauvez-moi, et je garderai vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 147, 'Je me suis levé avant le jour, et j’ai crié, tant j’espérais en vos promesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 148, 'Mes yeux se sont ouverts avant l’aurore, pour méditer vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 149, 'Écoutez ma voix, Seigneur, selon votre miséricorde; vivifiez-moi selon votre jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 150, 'Mes persécuteurs se sont approchés de l’iniquité, et ils se sont éloignés de votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 151, 'Vous êtes proche, Seigneur, et toutes vos voies sont vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 152, 'J’ai reconnu dès le commencement, par vos témoignages, que vous les aviez fondés pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 153, 'Voyez mon humiliation, et délivrez-moi; car je n’ai point oublié votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 154, 'Jugez ma cause, et rachetez-moi; vivifiez-moi selon votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 155, 'Le salut est loin des pécheurs, parce qu’ils n’ont point recherché vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 156, 'Vos miséricordes sont abondantes, Seigneur; vivifiez-moi selon votre jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 157, 'Ceux qui me persécutent et m’oppriment sont nombreux; cependant je ne me suis point écarté de vos témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 158, 'J’ai vu les insensés, et je me suis consumé, parce qu’ils n’avaient point gardé vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 159, 'Voyez, Seigneur, combien j’aime votre loi! vivifiez-moi selon votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 160, 'La vérité est le principe de vos paroles, et tous les jugements de votre justice sont éternels.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 161, 'Les princes m’ont persécuté sans cause; mais mon cœur n’a redouté que vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 162, 'Je me réjouirai de vos paroles, comme celui qui trouve un riche butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 163, 'Je hais l’iniquité, je l’ai en abomination; j’aime votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 164, 'Sept fois le jour je vous ai loué, à cause des jugements de votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 165, 'Ceux qui aiment votre loi jouissent d’une paix profonde, et il n’est point pour eux de scandale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 166, 'J’ai attendu votre salut, Seigneur, et j’ai aimé vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 167, 'Mon âme a gardé vos témoignages; elle les a vivement aimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 168, 'J’ai gardé vos commandements et vos témoignages, parce que toutes mes voies sont en votre présence, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 169, 'Que ma prière, Seigneur, arrive jusqu’à vous; donnez-moi l’intelligence selon votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 170, 'Que ma demande, Seigneur, arrive jusqu’à vous; délivrez-moi selon votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 171, 'Que mes lèvres chantent un hymne, quand vous m’aurez enseigné vos préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 172, 'Que ma langue publie vos promesses, parce que tous vos commandements sont la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 173, 'Que votre main se prête à me sauver, parce que j’ai choisi votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 174, 'J’ai désiré votre salut, Seigneur, et votre loi est l’objet de ma méditation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 175, 'Mon âme vivra et vous louera, et vos jugements seront mon soutien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 118, 176, 'J’ai été errant comme une brebis égarée; cherchez votre serviteur, parce que je n’ai point oublié votre loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 119, 1, 'Dans ma tribulation, j’ai crié vers le Seigneur, et il m’a exaucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 119, 2, 'Seigneur, délivrez mon âme des lèvres injustes et des langues trompeuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 119, 3, 'Que te revient-il, et quel profit as-tu retiré de ta langue trompeuse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 119, 4, 'Les flèches des puissants sont aiguës comme des charbons d’épines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 119, 5, 'Hélas! que mon pèlerinage est long! j’ai habité sous les tentes de Cédar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 119, 6, 'Mon âme a été longtemps en pèlerinage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 119, 7, 'J’ai été pacifique avec les ennemis de ma paix; sitôt que je leur parlais, ils m’attaquaient sans motif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 1, 'J’ai levé les yeux vers les montagnes, d’où me viendra mon secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 2, 'Le secours me viendra du Seigneur, qui a créé le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 3, 'Il ne fera point trébucher ton pied; celui qui te garde ne s’endormira pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 4, 'Il ne sommeillera pas, il ne s’endormira point celui qui garde Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 5, 'Le Seigneur te garderà, le Seigneur sera ton abri; sur toi il étendra sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 6, 'Le soleil ne te brûlera point pendant le jour, ni la lune pendant la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 7, 'Le Seigneur te préservera de tout mal; le Seigneur gardera ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 120, 8, 'Le Seigneur te gardera, que tu entres ou que tu sortes, dès maintenant et dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 1, 'Je me suis réjoui quand ils m’ont dit: Entrons dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 2, 'Nos pieds étaient fermes jadis en tes parvis, ô Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 3, 'Jérusalem est bâtie comme une ville dont toutes les parties sont parfaitement unies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 4, 'Car c’est là que montaient les tribus, les tribus du Seigneur, selon l’ordre donné à Israël, pour rendre gloire au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 5, 'Là étaient établis des trônes pour le jugement, des trônes pour la maison de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 6, 'Priez pour la paix de Jérusalem, et la prospérité de ceux qui t’aiment, ô cité sainte!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 7, 'Que la paix règne dans ta force, et l’abondance dans tes tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 8, 'J’ai désiré pour toi la paix, à cause de mes frères et de mes proches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 121, 9, 'J’ai cherché ce qui t’est bon, à cause de la maison du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 122, 1, 'J’ai levé mes yeux vers vous, qui demeurez au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 122, 2, 'Comme les yeux des serviteurs sont sur les mains de leurs maîtres, et les yeux des servantes sur les mains de la maîtresse; voilà qu’ainsi nos yeux seront sur le Seigneur notre Dieu, jusqu’à ce qu’il nous fasse miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 122, 3, 'Ayez pitié de nous, Seigneur, ayez pitié de nous, parce que nous sommes accablés sous les mépris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 122, 4, 'Notre âme en est pleine, et déborde que l’opprobre soit pour les riches, et le mépris pour les superbes!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 1, 'Si le Seigneur n’avait été avec nous, qu’Israël dise:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 2, 'Si le Seigneur n’avait été avec nous, lorsque des hommes se sont levés contre nous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 3, 'Peut-être nous auraient-ils dévorés tout vivants. Quand leur fureur a éclaté contre nous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 4, 'Peut-être leurs flots nous auraient-ils submergés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 5, 'Ce torrent, notre âme l’a traversé; notre âme a traveré cet abîme sans fond.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 6, 'Béni soit le Seigneur, qui ne nous a point livrés à leurs dents comme une proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 7, 'Notre âme s’est échappée comme un passereau du filet des chasseurs; le filet a été rompu, et nous avons été délivrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 123, 8, 'Notre secours est dans le nom du Seigneur, qui a créé le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 124, 1, 'Ceux qui ont foi dans le Seigneur sont comme la montagne de Sion. Il ne sera point ébranlé dans les siècles des siècles, celui qui habite');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 124, 2, 'En Jérusalem. Des montagnes sont alentour, et le Seigneur à l’entour de son peuple, maintenant et dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 124, 3, 'Le Seigneur ne permettra pas que la verge des pécheurs soit toujours sur l’héritage des justes, de peur que les justes n’étendent leurs mains à l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 124, 4, 'Seigneur, bénissez les bons et ceux qui ont le cœur droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 124, 5, 'Ceux qui vont dans les sentiers détournés, le Seigneur les conduira parmi les ouvriers d’iniquité: paix sur Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 125, 1, 'Quand le Seigneur ramena les captifs de Sion, nous fûmes comblés de consolations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 125, 2, 'Alors notre bouche fut remplie de joie, et notre langue d’allégresse; alors les gentils dirent entre eux: Pour eux le Seigneur a fait de grandes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 125, 3, 'Le Seigneur a fait de grandes choses pour nous, et nous en avons été dans la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 125, 4, 'Seigneur, ramenez nos captifs comme les torrents du Midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 125, 5, 'Ceux qui sèment dans les larmes récolteront dans l’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 125, 6, 'Ils allaient, ils allaient pleurant, jetant leur semence: ils reviendront dans l’allégresse, apportant leurs gerbes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 125, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 126, 1, 'Si le Seigneur n’édifie la maison, ceux qui l’édifient travaillent en vain. Si le Seigneur ne garde la ville, celui qui la garde veille en vain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 126, 2, 'En vain vous vous levez dès l’aurore: levez-vous après le repos, vous qui mangez le pain de la douleur, quand le Seigneur aura donné le sommeil à ses bien-aimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 126, 3, 'Voilà l’héritage du Seigneur des enfants, récompense du labeur des entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 126, 4, 'Telles sont des flèches dans la main des puissants; tels des fils pour ceux qui ont été ébranlés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 126, 5, 'Heureux celui qui, par eux, remplira ses désirs: ils ne seront point confondus quand ils parleront à leurs ennemis aux portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 127, 1, 'Heureux tous ceux qui craignent le Seigneur et qui cheminent en ses voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 127, 2, 'Tu mangeras le fruit des labeurs de tes mains; tu es heureux, et tu prospèreras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 127, 3, 'Ta femme sera comme une vigne féconde dans l’enceinte de ta maison; et tes enfants autour de ta table seront comme de jeunes plants d’olivier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 127, 4, 'Voilà comme sera béni l’homme qui craint le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 127, 5, 'Que le Seigneur du haut de Sion te bénisse; et que tu voies les biens de Jérusalem, tous les jours de ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 127, 6, 'Et que tu voies les fils de tes fils: paix sur Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 1, 'Souvent ils m’ont attaqué dès ma jeunesse; que maintenant Israël dise:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 2, 'Souvent ils m’ont attaqué dès ma jeunesse, et ils n’ont rien pu sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 3, 'Les pécheurs ont frappé sur mon dos; ils ont prolongé leur iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 4, 'Le Seigneur en sa justice a brisé le cou des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 5, 'Qu’ils soient confondus et mis en fuite, tous ceux qui haïssent Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 6, 'Qu’ils deviennent comme l’herbe des toits, qui sèche avant d’être arrachée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 7, 'Et qui ne remplit ni la main du faucheur ni le sein du botteleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 128, 8, 'Sur eux les passants n’ont point dit: Que la bénédiction du Seigneur soit avec vous; nous vous bénissons au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 1, 'Des profondeurs de l’abîme, j’ai crié vers vous, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 2, 'Seigneur, écoutez ma voix; que votre oreille soit attentive à la voix de ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 3, 'Si vous regardez nos iniquités, Seigneur, Seigneur, qui soutiendra votre regard?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 4, 'Car la miséricorde est en vous; à cause de votre nom, je vous ai attendu, Seigneur. Mon âme a mis son attente en votre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 5, 'Mon âme a espéré dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 6, 'Que depuis la veille du matin jusqu’à la nuit, Israël espère dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 7, 'Car la miséricorde est dans le Seigneur, et une abondante rédemption est en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 129, 8, 'Et c’est lui qui rachètera Israël de toutes ses iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 130, 1, 'Seigneur, mon cœur ne s’est point enorgueilli, et mes yeux ne se sont point élevés; je n’ai point cheminé dans les grandeurs ni en des merveilles au-dessus de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 130, 2, 'Si je n’ai point eu d’humbles sentiments, si j’ai trop élevé mon âme, rétribuez mon âme comme un enfant privé du lait de sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 130, 3, 'Qu’Israël espère dans le Seigneur, maintenant et dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 1, 'Seigneur, souvenez-vous de David et de toute sa mansuétude;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 2, 'Comment il a juré au Seigneur et fait vœu au Dieu de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 3, 'Je n’entrerai pas, dit-il, dans le tabernacle de ma demeure; je ne monterai pas sur le lit de mon repos;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 4, 'Je ne donnerai point de sommeil à mes yeux, ni à mes paupières le moindre assoupissement,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 5, 'Ni de repos à mon front, avant que j’aie trouvé un lieu pour le Seigneur, un tabernacle pour le Dieu de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 6, 'Voilà que nous avons ouï dire: Il est en Éphrata; nous l’avons trouvé dans les plaines de la forêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 7, 'Nous entrerons dans le tabernacle du Seigneur; nous l’adorerons dans le lieu où il a arrêté ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 8, 'Levez-vous, Seigneur, pour entrer en votre repos, vous et l’arche de votre sanctification.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 9, 'Vos prêtres se revêtiront de justice, et vos saints seront transportés d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 10, 'À cause de David votre serviteur, ne détournez pas votre face de votre Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 11, 'Le Seigneur a fait à David un serment véritable, et il ne le rétractera pas: Je placerai sur ton trône un roi issu du fruit de ton sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 12, 'Si tes fils gardent mon alliance et mes témoignages que je leur ai enseignés, leurs fils aussi seront assis sur ton trône dans tous les siècles:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 13, 'Parce que le Seigneur a élu Sion; il en a fait un choix privilégié pour sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 14, 'Ce sera mon repos dans les siècles des siècles; j’y résiderai, parce que je l’ai choisi avec prédilection.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 15, 'Je bénirai et bénirai sa chasse; ses pauvres, je les rassasierai de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 16, 'Ses prêtres, je les revêtirai de salut, et ses saints tressailliront d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 17, 'C’est là que j’élèverai le front de David, là que j’ai préparé une lampe pour mon Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 131, 18, 'Pour ses ennemis, je les revêtirai de honte; mais sur lui fleurira ma sanctification.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 132, 1, 'Voyez aujourd’hui qu’il est doux, qu’il est aimable d’avoir des frères, d’habiter dans l’union.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 132, 2, 'C’est comme de la myrrhe sur la tête, celle qui descendit sur la barbe d’Aaron, et de là sur la frange de son vêtement;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 132, 3, 'Ou comme la rosée d’Hermon, qui descend sur les montagnes de Sion; parce que là le Seigneur a voulu que fussent la bénédiction et la vie dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 133, 1, 'Voyez maintenant, et bénissez le Seigneur, vous tous qui êtes ses serviteurs et qui vous tenez en sa maison, dans les parvis de la maison de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 133, 2, 'Durant les nuits, levez vos mains vers le sanctuaire et bénissez le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 133, 3, 'Que de Sion te bénisse le Seigneur, qui a fait le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 1, 'Louez le Seigneur, ô vous qui êtes ses serviteurs; louez le Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 2, 'Vous qui vous tenez en sa maison, dans les parvis de la maison de notre Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 3, 'Louez le Seigneur, parce que le Seigneur est bon; chantez des psaumes à son nom, parce que son nom est beau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 4, 'Car le Seigneur a choisi Jacob pour être à lui Jacob, et Israël pour être sa possession.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 5, 'Et moi j’ai reconnu que le Seigneur est grand, que notre Dieu est au-dessus de tous les dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 6, 'Tout ce que le Seigneur a voulu, il l’a fait; dans le ciel et sur la terre, et dans la mer, et dans tous les abîmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 7, 'Il amène les nuées des extrémités de la terre; il change les éclairs en pluie. C’est lui qui tire les vents de ses trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 8, 'C’est lui qui a frappé les premiers-nés d’Égypte, depuis l’homme jusqu’aux troupeaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 9, 'Lui qui a envoyé ses signes et ses prodiges au milieu de toi, Égypte, devant le Pharaon et tous ses serviteurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 10, 'Lui qui a frappé maintes nations et tué des rois puissants:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 11, 'Séhon, roi des Amorrhéens, et Og, roi de Basan, et tous les rois chananéens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 12, 'Et qui a donné leur héritage en héritage à Israël, son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 13, 'Seigneur, votre nom est éternel, et votre mémoire passe de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 14, 'Car le Seigneur jugera son peuple, et il écoutera les prières de ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 15, 'Les idoles des gentils sont argent et or, œuvres des mains des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 16, 'Elles ont une bouche, et ne parleront pas; elles ont des yeux, et ne verront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 17, 'Elles ont des oreilles, et n’entendront pas; et il n’est point de souffle en leur bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 18, 'Que ceux qui les font leur deviennent semblables, et tous ceux qui croient en elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 19, 'Maison d’Israël, bénis le Seigneur; maison d’Aaron, bénis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 20, 'Maison de Lévi, bénis le Seigneur; vous qui craignez le Seigneur, bénissez le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 134, 21, 'Béni soit le Seigneur en Sion, lui qui habite Jérusalem!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 1, 'Rendez gloire au Seigneur; car il est bon, et sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 2, 'Rendez gloire au Dieu des dieux; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 3, 'Rendez gloire au Seigneur des seigneurs; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 4, 'À lui seul, qui a fait de grandes merveilles; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 5, 'À lui, qui a créé le ciel avec intelligence; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 6, 'À lui, qui a affermi la terre au-dessus des eaux; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 7, 'À lui seul, qui a créé ces grands luminaires; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 8, 'Le soleil, pour présider aux jours; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 9, 'La lune et les astres, pour présider à la nuit; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 10, 'À lui, qui a frappé l’Égypte et ses premiers-nés; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 11, 'À lui, qui a fait partir Israël du milieu des Égyptiens; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 12, 'Par sa main puissante et son bras élevé; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 13, 'À lui, qui a séparé la mer Rouge; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 14, 'Et qui a fait passer Israël au milieu de son lit; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 15, 'Et qui a frappé le Pharaon et toute sa puissance dans la mer Rouge; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 16, 'À lui, qui a conduit son peuple à travers le désert; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 17, 'À lui, qui a frappé de grands rois; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 18, 'Et qui a fait périr des rois puissants; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 19, 'Séhon, roi des Amorrhéens; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 20, 'Et Og, roi de Basan; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 21, 'Et qui a donné leurs terres en héritage; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 22, 'En héritage à Israël, son serviteur; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 23, 'Parce que, en notre humiliation, le Seigneur s’est souvenu de nous; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 24, 'Et qu’il nous a rachetés des mains de nos ennemis; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 25, 'Et qu’il donne la pâture à toute chair; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 135, 26, 'Rendez gloire au Dieu du ciel; car sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 1, 'Sur les fleuves de Babylone nous nous sommes assis, et nous avons pleuré, en nous souvenant de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 2, 'Nous avons suspendu nos harpes aux saules, qui sont au milieu de la contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 3, 'Car ceux qui nous avaient faits captifs nous demandaient les paroles de nos cantiques; et ceux qui nous avaient emmenés nous disaient: Chantez-nous un hymne des cantiques de Sion!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 4, 'Comment chanterons-nous un cantique du Seigneur sur une terre étrangère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 5, 'Si je t’oublie, Jérusalem, que ma main droite s’oublie elle-même!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 6, 'Si je ne me propose Jérusalem comme le principe de mes joies; si je ne me souviens point de toi, que ma langue s’attache à mon gosier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 7, 'Souvenez-vous, Seigneur, des fils d’Édom, qui, au dernier jour de Jérusalem, disaient: Détruisez-la, détruisez-la jusqu’en ses fondements!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 8, 'Fille de Babylone, infortunée! heureux celui qui te rendra le mal en retour du mal que tu as fait!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 136, 9, 'Heureux celui qui saisira tes petits enfants et les écrasera contre la pierre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 1, 'Seigneur, je vous rendrai gloire de toute mon âme, et je vous chanterai mes psaumes devant les anges, parce que vous avez écouté les paroles de ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 2, 'Je vous adorerai en votre saint temple, et je rendrai gloire à votre nom, à cause de votre miséricorde et de votre vérité; car vous avez exalté votre saint nom au-dessus de toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 3, 'En quelque jour que je vous invoque, aussitôt exaucez-moi; et vous agrandirez mon âme par votre force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 4, 'Seigneur, que tous les rois de la terre vous rendent gloire; car ils ont ouï toutes les paroles de votre bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 5, 'Et qu’ils chantent dans les voies du Seigneur; car la gloire du Seigneur est grande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 6, 'Car le Seigneur, quoique très-élevé, regarde les humbles, et reconnaît de loin les superbes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 7, 'Si je marche au milieu des tribulations, vous me vivifierez; vous avez étendu les mains contre la fureur de mes ennemis, et votre droite m’a sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 137, 8, 'Le Seigneur les rétribuera en ma faveur; Seigneur, votre miséricorde est éternelle ne méprisez pas l’œuvre de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 1, 'Seigneur, vous m’avez éprouvé, et vous m’avez connu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 2, 'Vous connaissez mon repos et mon réveil;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 3, 'Vous avez compris de loin toutes mes pensées; vous avez recherché mon sentier et le fil de ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 4, 'Et vous avez prévu toutes mes voies, et reconnu que sur ma langue il n’est point de paroles iniques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 5, 'Voilà, ô Seigneur; que vous savez toutes les choses de la fin et du commencement; vous m’avez formé, et vous avez posé sur moi votre main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 6, 'Votre science sur moi est admirable et pleine de force, et je ne puis en approcher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 7, 'Où aller pour fuir votre esprit? où me réfugier pour échapper à votre face?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 8, 'Si je monte au ciel, vous y êtes; si je descends en enfer, vous y êtes présent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 9, 'Si, dès l’aurore, je déploie mes ailes et que je m’abrite aux extrémités de la mer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 10, 'Là encore votre main me conduit, et votre droite me retient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 11, 'Et j’ai dit: Peut-être les ténèbres me cacheront-elles; et la nuit a été lumière sur mes voluptés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 12, 'Car pour vous, les ténèbres ne sont point ténèbres, et la nuit brille autant que le jour. Les ténèbres sont pour vous comme la lumière du jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 13, 'Seigneur, vous êtes maître de mes reins; vous m’avez pris dès le sein de ma mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 14, 'Je vous rendrai gloire, parce que vos prodiges ont un éclat terrible; vos œuvres sont merveilleuses, et mon âme le sait bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 15, 'Mes os ne vous sont point cachés, puisque vous les avez cachés vous-même; ni ma substance, quoique perdue au fond de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 16, 'Vos yeux m’ont vu quand j’étais encore informe, et les hommes sont tous inscrits sur votre livre; ils se forment jour par jour, et nul n’y échappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 17, 'J’ai beaucoup honoré vos amis, ô mon Dieu, et leur empire s’est grandement affermi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 18, 'J’en ferai le dénombrement, et ils seront plus nombreux que les sables. Je m’éveille, et je suis encore avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 19, 'O Dieu, si vous tuez les pécheurs!... Détournez-vous de moi, hommes de sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 20, 'Car, Seigneur, vous dites en votre pensée: Ils prendront vainement tes cités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 21, 'Seigneur, n’ai-je point haï ceux qui vous haïssent, et ne me suis-je pas consumé en voyant vos ennemis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 22, 'Je les ai haïs d’une haine parfaite; ils sont devenus mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 23, 'Éprouvez-moi, mon Dieu, et connaissez mon cœur; sondez-moi, et connaissez mes sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 138, 24, 'Et voyez s’il est en moi quelque voie d’iniquité, et conduisez-moi dans la voie éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 1, 'Seigneur, délivrez-moi de l’homme pervers; arrachez-moi des mains de l’homme inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 2, 'Ceux qui n’ont eu que des pensées iniques dans le cœur, préparaient contre moi des attaques tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 3, 'Ils ont aiguisé leur langue comme celle du serpent; le venin de l’aspic est sous leurs lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 4, 'Gardez-moi, Seigneur, de la main du pécheur; arrachez-moi des mains des hommes iniques. Ils se proposaient de faire trébucher mes pas:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 5, 'Les superbes m’ont dressé des piéges cachés; et ils ont tendu des cordes, pour que mes pieds s’y prennent; sur mon chemin, ils ont mis des pierres de scandale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 6, 'J’ai dit au Seigneur: Vous êtes mon Dieu; Seigneur, prêtez l’oreille à la voix de ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 7, 'Seigneur, Seigneur, force de mon salut, vous avez mis ma tête à l’ombre le jour du combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 8, 'Seigneur, ne me livrez pas au pécheur contre mon désir; ils ont eu de mauvaises pensées contre moi; ne m’abandonnez point, de peur qu’ils ne soient exaltés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 9, 'Le résultat de leurs artifices, le labeur de leurs lèvres les envelopperont eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 10, 'Des charbons embrasés les atteindront sur la terre; et vous les ferez tomber dans les douleurs, et ils ne les pourront supporter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 11, 'L’homme qui parle trop ne marchera pas droit sur la terre; les calamités pourchasseront l’homme inique jusqu’à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 12, 'Je sais que le Seigneur fera justice au pauvre, et droit à l’indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 13, 'Cependant les justes rendront gloire à votre nom, et les cœurs droits habiteront avec votre face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 139, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 1, 'Seigneur, j’ai crié vers vous, écoutez-moi; soyez attentif à la voix de ma prière, quand je crie vers vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 2, 'Que ma prière se dirige vers vous, comme de l’encens; que l’élévation de mes mains vers vous soit comme le sacrifice du soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 3, 'Mettez, Seigneur, une garde à ma bouche, et une porte de sûreté autour de mes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 4, 'N’inclinez pas mon cœur vers les paroles de la malice, pour trouver des prétextes à mes péchés, en compagnie des ouvriers d’iniquité; préservez-moi d’entrer en communication avec ceux de leur choix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 5, 'Que le juste me réprimande avec miséricorde, et me blâme de même; mais que l’huile des pécheurs ne parfume point ma tête, que ma prière soit toujours en opposition avec leurs cupidités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 6, 'Leurs puissants ont été précipités près des rochers; ils écouteront mes paroles, parce qu’elles sont adoucies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 7, 'Comme les glèbes de la terre sont brisées sur la terre, nos os ont été dispersés aux portes de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 8, 'Seigneur, Seigneur, mes yeux sont tournés vers vous; j’ai espéré en vous; ne prenez point ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 9, 'Gardez-moi des fils qu’on a tendus contre moi, et de la pierre de scandale des ouvriers d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 140, 10, 'Que les pécheurs tombent dans leurs propres filets; pour moi, je vais seul jusqu’à ce que je passe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 1, 'De l’intelligence de David lorsqu’il était dans la caverne en prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 2, 'J’ai crié de ma voix au Seigneur; j’ai conjuré de ma voix le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 3, 'J’épancherai devant lui ma prière; je lui ferai entendre, en sa présence, mon affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 4, 'Pendant que mon esprit était en défaillance, vous aussi vous connaissiez mes sentiers; dans la voie où j’étais cheminant, ils avaient caché pour moi des filets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 5, 'Je regardais à ma droite, je voyais, et il n’était personne qui me connût; tout refuge m’était ôté, et nul n’était là pour me sauver la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 6, 'J’ai crié vers vous, Seigneur, et j’ai dit: Vous êtes mon espérance et mon partage en la terre des vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 7, 'Soyez attentif à ma supplication, car je suis humilié à l’excès; délivrez-moi de ceux qui me poursuivent, car ils sont plus forts que moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 141, 8, 'Tirez mon âme de sa prison pour qu’elle rende grâces à votre nom, Seigneur; et les justes m’attendront jusqu’à ce que vous m’ayez récompensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 1, 'Seigneur, écoutez ma prière; prêtez l’oreille à ma prière, en votre vérité; exaucez-moi en votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 2, 'Et n’entrez point en jugement avec votre serviteur; car nul homme vivant ne sera justifié devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 3, 'L’ennemi a poursuivi mon âme; il a humilié ma vie jusqu’à terre; il m’a mis dans un lieu de ténèbres, comme les morts du siècle passé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 4, 'Et mon esprit a été dans l’anxiété, et moi, mon cœur a été troublé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 5, 'Je me suis souvenu des jours antiques, et j’ai médité sur toutes vos actions; j’ai médité sur les œuvres de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 6, 'Et j’ai étendu les mains vers vous; mon âme est devant vous comme une terre sans eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 7, 'Seigneur, exaucez-moi au plus tôt; mon esprit a défailli; ne détournez pas de moi votre face, car je serais semblable à ceux qui descendent dans le lac.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 8, 'Faites que dès l’aurore j’entende votre miséricorde; car j’ai espéré en vous. Faites-moi connaître, Seigneur, la voie où je dois marcher; car j’ai élevé vers vous mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 9, 'Délivrez-moi de mes ennemis, Seigneur; car je me suis réfugié vers vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 10, 'Enseignez-moi à faire votre volonté; car vous êtes mon Dieu. Votre Esprit, plein de bonté, me guidera dans la droiture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 11, 'Pour l’amour de votre nom, Seigneur, vous me vivifierez en votre justice; vous retirerez mon âme de la tribulation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 142, 12, 'Et dans votre miséricorde vous exterminerez mes ennemis; vous détruirez tous ceux qui tourmentent mon âme, car je suis votre serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 1, 'Béni soit le Seigneur mon Dieu, qui dresse mes mains à la bataille, et mes doigts à la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 2, 'Ma miséricorde et mon refuge, mon salut, mon défenseur et mon appui, j’ai espéré en Celui qui me soumet mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 3, 'Seigneur, qu’est-ce donc que l’homme pour que vous vous soyez révélé à lui, ou le fils de l’homme pour que vous teniez compte de lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 4, 'L’homme est semblable à la vanité même; ses jours passent comme une ombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 5, 'Seigneur, inclinez vos cieux, et descendez; touchez les montagnes, et elles s’en iront en fumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 6, 'Faites briller des éclairs, et vous les réduirez en poudre; lancez vos traits, et vous les troublerez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 7, 'Envoyez d’en haut votre main, délivrez-moi, retirez-moi des grandes eaux et des mains des fils d’étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 8, 'Leur bouche a dit des paroles vaines, et leur droite est une main d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 9, 'Ô Dieu, je vous chanterai un cantique nouveau, je chanterai pour vous sur la harpe à dix cordes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 10, 'Vous donnez le salut aux rois; vous avez sauvé David, votre serviteur, du glaive cruel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 11, 'Délivrez-moi, retirez-moi des mains des fils d’étrangers, dont la bouche a dit des paroles vaines, et dont la droite est une main d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 12, 'Leurs fils sont comme des rejetons fleurissants en leur jeunesse; leurs filles sont arrangées et parées comme l’idole d’un temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 13, 'Leurs celliers sont massifs, regorgeant de telle chose et de telle autre; leurs brebis sont fécondes, et se multiplient dans leurs pacages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 14, 'Leurs bœufs sont gras; leurs murs n’ont ni éboulements ni brèches; on n’entend pas de cris dans leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 143, 15, 'Heureux, disent-ils, le peuple qui a de tels biens: mais plus heureux le peuple dont le Seigneur est le Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 1, 'Je vous exalterai, ô mon Dieu, ô mon Roi, et je bénirai votre nom dans les siècles, et dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 2, 'Chaque jour je vous bénirai et je louerai votre nom dans les siècles, et dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 3, 'Le Seigneur est grand et digne de louanges infinies; à sa grandeur il n’est point de limite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 4, 'Les générations des générations loueront vos œuvres; elles proclameront votre puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 5, 'Elles diront la majesté de votre sainteté, et raconteront vos merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 6, 'Elles diront la force de vos épouvantements; elles raconteront votre grandeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 7, 'Elles rappelleront avec effusion le souvenir de votre inépuisable bonté, et se réjouiront de votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 8, 'Le Seigneur est compatissant et miséricordieux; il est longanime et plein de miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 9, 'Le Seigneur est doux pour ceux qui l’attendent, et ses miséricordes sont encore au-dessus de toutes ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 10, 'Seigneur, que toutes vos œuvres vous louent, et que vos saints vous bénissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 11, 'Qu’ils disent la gloire de votre royaume; qu’ils parlent de votre domination;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 12, 'Pour faire connaître aux fils des hommes votre puissance et la majesté glorieuse de votre royauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 13, 'Votre royaume est le royaume de tous les siècles, et votre domination va de génération en génération; le Seigneur est fidèle en ses paroles; et saint en toutes ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 14, 'Le Seigneur affermit ceux qui tombent; il relève ceux qui ont été brisés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 15, 'Les yeux de tous espèrent en vous, et vous leur donnez la nourriture en temps opportun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 16, 'Vous ouvrez les mains, et vous remplissez de bénédiction tout être animé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 17, 'Le Seigneur est juste en toutes ses voies, et saint en toutes ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 18, 'Le Seigneur est proche de ceux qui l’invoquent, de tous ceux qui l’invoquent en vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 19, 'Il fera la volonté de ceux qui le craignent, et il exaucera leurs prières, et il les sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 20, 'Le Seigneur garde tous ceux qui l’aiment, et il exterminera tous les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 21, 'Que ma bouche dise les louanges du Seigneur, et que toute chair bénisse son saint nom dans les siècles, et dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 144, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 1, 'Alleluia. D’Aggée et de Zacharie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 2, 'Ô mon âme, loue le Seigneur; je louerai le Seigneur toute ma vie; je chanterai des psaumes à mon Dieu tant que j’existerai. Ne mettez point votre confiance dans les princes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 3, 'Ni dans les fils des hommes; car ils n’ont point de salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 4, 'Leur esprit s’évanouira, et ils retourneront en leur terre; en ce jour-là périront toutes leurs pensées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 5, 'Heureux celui qui a pour auxiliaire le Dieu de Jacob, son espérance dans le Seigneur son Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 6, 'Qui a créé le ciel et la terre, et la mer, et tout ce qu’ils renferment;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 7, 'Qui garde la vérité dans tous les siècles, qui rend justice aux opprimés; qui donne aux pauvres la nourriture. Le Seigneur délivre ceux qui sont enchaînés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 8, 'Le Seigneur rend sages les aveugles; le Seigneur relève ceux qui sont brisés; le Seigneur aime les justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 9, 'Le Seigneur garde les étrangers; il secourt l’orphelin et la veuve, et il exterminera la voie des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 145, 10, 'Le Seigneur ton Dieu, ô Sion, régnera dans tous les siècles, de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 1, 'Louez le Seigneur, car le chant d’un psaume lui est agréable; puissent nos louanges être agréables à notre Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 2, 'C’est le Seigneur qui a bâti Jérusalem; il rassemblera les membres dispersés d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 3, 'Il guérit les hommes contrits en leur cœur; il bande leurs plaies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 4, 'Il dénombre la multitude des étoiles, et toutes, il les appelle par leur nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 5, 'Notre-Seigneur est grand; sa force est grande, et son intelligence infinie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 6, 'Le Seigneur élève les doux; il humilie jusqu’à terre les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 7, 'Entonnez des chants de gloire au Seigneur; chantez des psaumes à notre Dieu sur la cithare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 8, 'C’est lui qui revêt le ciel de nuages, lui qui prépare de la pluie pour la terre; lui qui fait naître de l’herbe dans les montagnes, et du fourrage pour le service de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 9, 'Il donne la pâture aux bêtes et aux petits des corbeaux qui l’invoquent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 10, 'Il ne veut pas qu’on se complaise dans la force du cheval, ni que l’on se confie dans les jarrets de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 146, 11, 'Le Seigneur se complaît en ceux qui le craignent, et en tous ceux qui espèrent en sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 1, '(12.) Jérusalem, loue ensemble le Seigneur; ô Sion, loue ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 2, '(13.) Car il a fortifié les verrous de tes portes; il a béni tes fils dans ton enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 3, '(14.) C’est lui qui a établi la paix sur tes frontières, et qui te rassasie de fleur de froment;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 4, '(15.) Lui qui envoie sa parole à la terre, et sa voix court avec rapidité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 5, '(16.) Lui qui couvre la terre de neige comme d’une toison, et verse des brouillards comme de la cendre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 6, '(17.) Lui qui produit la glace comme des morceaux de pain: qui alors peut supporter la rigueur de la froidure?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 7, '(18.) Il enverra sa parole, et la glace fondra; il exhalera son souffle, et les eaux couleront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 8, '(19.) C’est lui qui annonce sa parole à Jacob, ses ordonnances et ses jugements à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 9, '(20.) Il n’a point fait de même pour toutes les nations, et il ne leur a pas révélé ses commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 147, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 1, 'Louez le Seigneur dans les cieux; louez-le sur les plus hautes cimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 2, 'Louez-le tous, ô vous qui êtes ses anges; louez-le, ô vous, ses Dominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 3, 'Louez-le, soleil et lune; louez-le toutes, étoiles et lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 4, 'Louez-le, cieux des cieux; et que les eaux, au delà des cieux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 5, 'Louent le nom du Seigneur: car il a dit, et tout a été fait; il a commandé, et tout a été créé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 6, 'Il les a établies pour les siècles, et les siècles des siècles; il leur a posé une loi, et elle ne passera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 7, 'Louez le Seigneur, louez-le sur la terre, serpents et abîmes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 8, 'Feu, grêle, neige, glace, souffle des tempêtes, vous qui exécutez sa parole;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 9, 'Et vous tous, monts et collines, vous tous, arbres fruitiers et cèdres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 10, 'Et vous tous, bêtes fauves et troupeaux, reptiles et oiseaux ailés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 11, 'Et vous tous, rois de la terre et peuples, princes et juges de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 12, 'Que les adolescents et les vierges, que les vieux et les jeunes louent le nom du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 13, 'Car seul son nom est grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 148, 14, 'Sa louange est sur la terre et dans le ciel, et il exaltera le front de son peuple. Cet hymne est pour tous ses saints, et pour les fils d’Israël, pour le peuple qui s’approche de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 1, 'Chantez au Seigneur un cantique nouveau; que sa louange soit dans l’Église des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 2, 'Qu’Israël se réjouisse en Celui qui l’a créé; que les fils de Sion tressaillent en leur roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 3, 'Qu’ils louent son nom en chœur, qu’ils le chantent au son de la harpe et du tambour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 4, 'Car le Seigneur se complaît en son peuple, et il glorifiera les doux en les sauvant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 5, 'Les saints se réjouissent dans la gloire; ils tressaillent d’allégresse en leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 6, 'Ils ont dans la bouche les louanges de Dieu, et à la main des glaives à double tranchant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 7, 'Pour tirer vengeance des gentils, pour châtier les peuples,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 8, 'Pour enchaîner les pieds des rois et mettre les grands dans des entraves de fer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 149, 9, 'Pour exécuter sur eux le jugement écrit. Telle est la gloire de tous ses saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 150, 1, 'Louez le Seigneur dans ses sanctuaires; louez-le dans le firmament de sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 150, 2, 'Louez-le dans toutes ses dominations; louez-le dans la plénitude de sa grandeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 150, 3, 'Louez-le au son de la trompette; louez-le sur la harpe et la cithare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 150, 4, 'Louez-le en chœur au son du tambour; louez-le sur les cordes des instruments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 150, 5, 'Louez-le sur les cymbales retentissantes; louez-le sur les cymbales de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 150, 6, 'Que tout ce qui respire loue le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 151, 1, 'J’étais petit entre mes frères et le plus jeune dans la maison de mon père; je gardais ses brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 151, 2, 'Mes mains ont fait un instrument, et mes doigts ont accordé un psaltérion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 151, 3, 'Et qui invoquera le Seigneur, que le Seigneur lui-même ne l’exauce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 151, 4, 'Lui-même il a envoyé son ange; il m’a tiré des troupeaux de mon père et m’a oint de l’huile de son onction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 151, 5, 'Mes frères étaient beaux et grands; et le Seigneur ne s’est point plu en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 151, 6, 'Je me suis avancé à la rencontre de l’étranger; il m’a maudit par ses idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 151, 7, 'Mais moi lui ayant arraché son épée je lui ai coupé la tête, et j’ai l’opprobre de dessus les enfants d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Seigneur tout-puissant, Dieu de mes pères, Abraham, Isaac et Jacob, et de leur race sainte!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Vous qui avez créé le ciel et la terre; et tout ce qu’ils renferment!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Vous qui par votre parole avez donné des bornes à la mer, qui avez fermé l’abîme et l’avez scellé de votre nom terrible et adorable!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Vous devant qui toutes les créatures tremblent, et dont elles redoutent la puissance, parce qu’elles ne peuvent soutenir ni l’éclat de votre gloire, ni la colère dont vous menacez les pécheurs!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Seigneur! la miséricorde que vous nous avez promise est infinie et au-dessus de tout ce que l’on peut concevoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Car vous êtes le Seigneur, le Très Haut, bon, patient, miséricordieux, et toujours prêt à vous repentir des maux dont vous nous avez affligés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Vous avez promis de recevoir les pécheurs à la pénitence, et de les sauver dans votre infinie miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Vous donc, Seigneur! Dieu des justes! ce n’est ni à Abraham, ni à Isaac, ni à Jacob, que vous avez ordonné de faire pénitence, ils ne vous ont point offensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Mais à moi qui suis pécheur, puisque le nombre de mes crimes égale celui des sables de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Seigneur! mes iniquités se sont multipliées, elles se sont accrues, et je ne suis pas digne de porter mes regards vers le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Je suis tellement courbé sous la pesanteur de mes chaînes qu’il m’est impossible de lever la tête et il n’y a plus en moi de respiration.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Parce que j’ai excité votre courroux et que j’ai fait le mal en votre présence:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'J’ai été rebelle à votre volonté et je n’ai point gardé vos commandements:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'J’ai introduit de honteuses abominations dans Israël, et mes crimes se sont multipliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Mais à présent je fléchis les genoux dans l’amertume de mon cœur et j’implore votre bonté. J’ai péché, Seigneur, et je reconnais mes iniquités. C’est pourquoi, Seigneur, je vous conjure par les prières les plus vives de me les remettre et de ne point me perdre en les punissant. Ne me réservez pas à des supplices éternels et ne me reléguez point dans les profondeurs de la terre car vous êtes le Dieu des pécheurs pénitents. Vous ferez éclater sur moi toute votre bonté, en me sauvant par votre miséricorde infinie, tout indigne que j’en suis. Et je vous louerai tous les jours de ma vie, puisque toutes les puissances du ciel, font retentir vos louanges, et que la gloire vous appartient dans tous les siècles des siècles. Ainsi-soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Proverbes de Salomon, fils de David, qui régna en Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Pour faire connaître la sagesse et la discipline;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Pour apprendre les paroles de la prudence; pour montrer les artifices des discours; pour enseigner vraiment la justice, pour instruire à juger avec rectitude;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Pour donner aux innocents la sagacité, aux jeunes gens la doctrine et l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Car le sage qui les aura ouïs sera plus sage, et l’homme entendu saura l’art de gouverner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Il pénétrera la parabole et le sens voilé, et les paroles des sages, et leurs énigmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'La crainte du Seigneur est le commencement de la sagesse; la prudence est bonne à tous ceux qui la mettent en pratique; la piété envers Dieu est le principe de la sagesse; les insensés méprisent la sagesse et la doctrine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Écoute, mon fils, les instructions de ton père, et ne repousse pas la loi de ta mère:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Et tu ajouteras une couronne de grâces à ta tête, et à ton cou un collier d’or');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Mon fils, prends garde que des impies ne t’égarent; ne leur donne pas ton consentement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'S’ils te convient, disant: Viens avec nous, prends ta part du sang; cachons en terre injustement l’homme juste;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Engloutissons-le tout vivant, comme dans l’enfer, et effaçons de la terre tout souvenir de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Emparons-nous de ses richesses les plus précieuses, et remplissons nos demeures de ses dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Mets ta part avec la nôtre; faisons tous bourse commune et n’ayons qu’un trésor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Mon fils, ne va pas en leur voie; éloigne ton pied de leurs sentiers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Car ce n’est pas vainement qu’on tend des filets aux oiseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Mais ceux qui participent à un meurtre thésaurisent pour eux des malheurs; et la chute des pervers est funeste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Telles sont les voies de tous les ouvriers d’iniquité; par leur impiété, ils détruisent leur propre vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'La Sagesse chante dans les rues; elle parle librement au milieu des places.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Et du haut des remparts elle crie comme un héraut, et elle s’assied devant les portes des riches; et aux portes de la cité, pleine d’assurance, elle dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Tant que les innocents s’attacheront à la justice, ils ne seront point humiliés; quant aux insensés, pleins de désirs honteux, devenus impies, ils haïssent la science,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 22, 'Et sont exposés aux opprobres. Voilà que je vais proférer pour vous les paroles de mon esprit; je vais vous enseigner mes discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 23, 'J’ai appelé, et vous n’avez point obéi; j’ai parlé longuement, et vous n’étiez pas attentifs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 24, 'Mais vous avez mis à néant mes conseils, et vous avez été rebelles à mes réprimandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 25, 'Aussi moi je rirai au jour de votre perte, et je me réjouirai quand viendra votre ruine,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 26, 'Et quand soudain le trouble fondra sur vous, et que votre catastrophe sera là comme une tempête, et quand viendra sur vous la tribulation et l’oppression, et enfin la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 27, 'Car alors vous m’invoquerez; mais moi je ne vous écouterai point; les méchants me chercheront, et ils ne me trouveront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 28, 'Car ils haïssent la Sagesse; et ils n’ont point choisi de préférence la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 29, 'Et ils n’ont point voulu être attentifs à mes conseils; et ils se sont raillés de mes reproches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 30, 'Aussi mangeront-ils les fruits de leurs voies; et ils se rassasieront de leur propre impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 31, 'Car ils seront mis à mort, pour avoir fait tort aux petits; et l’examen de leur cause perdra les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 32, 'Tandis que celui qui m’écoute s’abritera sous l’espérance, et se reposera sans avoir à craindre aucun mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Mon fils, si tu reçois la parole de mon commandement, si tu la tiens cachée en toi-même,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Ton oreille écoutera la Sagesse, et tu inclineras ton cœur à la prudence, et tu l’appliqueras à l’enseignement de ton fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Car si tu invoques la Sagesse, et si tu appelles à haute voix la prudence, et si tu demandes à grands cris la doctrine,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Et si tu la recherches comme de l’argent, et si tu la creuses comme un trésor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Alors tu comprendras la crainte du Seigneur, et tu trouveras la connaissance de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Car c’est le Seigneur qui donne la sagesse, et de sa face viennent l’intelligence et le savoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Et il thésaurise le salut pour ceux qui font le bien; il protége leurs voies,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Pour qu’ils marchent dans la justice, et lui-même veille sur la voie de ceux qui le révèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Alors tu comprendras la justice et le jugement, et tu garderas droits tes sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Car si la sagesse entre dans ta pensée, et si la doctrine semble bonne à ton âme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Le bon conseil te gardera, et l’intelligence sainte te conservera;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Pour te délivrer de la voie mauvaise et de l’homme dont la parole est infidèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'O vous qui avez abandonné le droit chemin pour marcher dans la voie des ténèbres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Qui vous complaisez dans le mal, et vous réjouissez de la perversité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Dont les sentiers sont obliques, et les ornières tortueuses,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Vous chercherez à éloigner mon fils du droit chemin, et à le rendre étranger à la justice. O mon fils, ne te laisse pas surprendre par leur mauvais conseil!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Celle qui délaisse le compagnon de sa virginité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Et qui oublie l’alliance divine, a mis sa maison près de la mort, et ses voies près de l’enfer avec les fils de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Aucun de ceux qui vont avec elle ne reviendra, et ils ne reprendront pas les droits sentiers; car ils ne se maintiendront pas dans les longues années de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Et s’ils avaient marché dans les bons sentiers, ils auraient sûrement trouvé faciles les sentiers de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Les cœurs droits habiteront la terre, et les saints y seront établis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Les voies des impies seront effacées sur la terre, et les pervers en seront expulsés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Mon fils, n’oublie point mes lois, et garde mes paroles en ton cœur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Car elles te donneront la longueur des jours, des années de vie, et la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Que la miséricorde et la foi ne te quittent point; mais attache-les à ton cou, et tu trouveras grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Et pense au bien devant le Seigneur et devant les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Mets ta confiance en Dieu de tout ton cœur, et ne t’enorgueillis point de ta sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Discerne-la en toutes tes voies, pour marcher droit dans tes sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Ne te crois point sage par toi-même; mais crains Dieu, et détourne-toi de tout mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Alors la santé sera en ton corps, et le bien-être en tes os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Rends hommage au Seigneur de tes labeurs prospères, et offre-lui les prémices des fruits de ta justice,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Afin que tes celliers regorgent de froment, et que tes pressoirs débordent de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Mon fils, ne rejette point la discipline du Seigneur; ne te lasse pas d’être réprimandé par lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Car le Seigneur reprend celui qu’il aime, et frappe l’enfant qu’il préfère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Heureux l’homme qui a trouvé la Sagesse, et le mortel qui a connu la Prudence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Car elle est meilleure à gagner que des trésors entiers d’or et d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Elle est plus précieuse que les pierreries; nul mal ne lui résiste; elle est bien connue de tous ceux qui l’approchent; rien de ce qu’on estime n’est digne d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'En sa main droite sont les longs jours et les années de vie; en sa gauche, la richesse et la gloire; de sa bouche procède la justice, et sa langue porte la loi et la miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Ses voies sont les bonnes voies, et tous ses sentiers pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Elle est l’arbre de vie pour ceux qui l’embrassent; elle est un sûr appui pour ceux qui s’attachent à elle, comme au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Dieu a fondé la terre par la Sagesse; il a affermi le ciel par la Prudence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Grâce à sa prévoyance, les abîmes ont été rompus, et les nuages ont répandu la rosée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Mon fils, que ces choses ne s’éloignent pas de toi; garde mes conseils et ma science,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Afin que ton âme vive, et que la grâce demeure autour de ton cou (la santé sera en ta chair, et le bien-être en tes os);');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Afin que tu marches, en toutes tes voies, plein d’assurance et de paix, et que ton pied ne trébuche pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Si tu reposes, tu seras sans crainte; si tu sommeilles, tu dormiras doucement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Tu ne redouteras ni les alarmes soudaines, ni les attaques des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Car le Seigneur sera sur toutes tes voies, et il affermira ton pied de peur que tu ne chancelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Ne t’abstiens pas de faire du bien à l’indigent, sous prétexte que ta main ne peut le secourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Ne dis pas, quand tu pourrais bien faire: Va et reviens, demain je te donnerai; car tu ne sais ce qu’amènera le jour suivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Ne pense pas à mal contre ton ami qui vit près de toi, et se fie à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Ne prends pas en haine un homme sans motif, de peur qu’il ne vienne à te nuire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 31, 'Ne t’attire pas les outrages d’hommes méchants; ne porte point envie à leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 32, 'Car tout pervers est impur devant le Seigneur, et il ne siégera point dans l’assemblée des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 33, 'La malédiction de Dieu est sur la maison des impies; mais les chaumières des justes sont bénies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 34, 'Le Seigneur résiste aux superbes; mais il donne sa grâce aux humbles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 35, 'Les sages auront la gloire pour héritage; tandis que les impies exalteront leur propre ignominie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Écoutez, enfants, l’enseignement d’un père, et soyez attentifs à connaître la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Car je vous fais un don précieux; ne délaissez point ma loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'J’ai été un fils docile à mon père, et cher aux yeux de ma mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Ils m’ont instruit, disant: Que nos discours soient fixés dans ton cœur; garde nos préceptes; ne les oublie pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Ne méprise pas les paroles de ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Ne les abandonne point, et elles s’attacheront à toi; aime-les, et elles te garderont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Entoure-les de palissades, et elles t’exalteront; honore-les, afin qu’elles t’embrassent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Afin qu’elles mettent sur ta tête une couronne de grâces, et te couvrent d’une couronne de délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Écoute, mon fils, et recueille mes paroles, et les années de ta vie se multiplieront, autant que se multiplieront les voies de ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Car je t’enseignerai les voies de la sagesse, et je te ferai cheminer dans les droits sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Si tu marches, rien n’entravera tes pas; si tu cours, tu ne sentiras point la fatigue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Retiens mes instructions, ne les néglige point; mais garde-les en toi-même toute ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Ne va pas sur la voie des impies; ne porte point envie aux voies des pervers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'N’approche pas du lieu où ils dresseront leur camp; éloigne-toi d’eux; hâte-toi de passer outre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Car ils ne s’endormiront pas qu’ils n’aient fait quelque mal; le sommeil leur est enlevé, et ils ne reposent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Car ils se nourrissent du pain de l’impiété, et s’enivrent du vin des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Les voies des justes brillent comme la lumière; ils marchent, et ils sont illuminés jusqu’à ce que le jour se lève.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Mais les voies des impies sont impures; ils ne savent pas comment ils trébuchent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Mon fils, sois attentif à ma voix, et prête l’oreille à mes paroles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Et pour que les fontaines de vie ne te manquent pas, garde-les en ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Car elles sont la vie de ceux qui les trouvent, et la santé de leur chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Veille de toute ton attention sur ton cœur; car de là sort le principe de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Chasse loin de toi toute langue perverse, et repousse les lèvres iniques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Que tes yeux voient le bien; que tes paupières approuvent le juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Prépare pour tes pieds des sentiers droits, et qu’il n’y ait point de détours en tes voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'N’incline ni à droite ni à gauche, et retire tes pieds de la voie mauvaise; car Dieu seul connaît les voies de la droite, et celles de la gauche sont tortueuses. Lui-même prendra soin de redresser tes sentiers, et il dirigera tes pas dans la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Mon fils, sois attentif à ma sagesse, et prête l’oreille à mes discours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Afin de conserver ta pensée pure. C’est la sagesse de mes lèvres qui te fait cette recommandation: Ne t’attache point à la femme trompeuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Car le miel découle des lèvres de la femme débauchée, qui, pour un temps, charmera ton palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Mais après tu la trouveras plus amère que le fiel, et plus aiguë qu’un glaive à double tranchant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Car les pieds de la folie conduisent ceux qui l’aiment à l’enfer, en compagnie de la mort, et ses pas ne laissent point de traces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Elle ne chemine point dans les voies de vie; mais ses sentiers sont glissants et difficiles à suivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Maintenant donc, ô mon fils, écoute-moi, et ne rends point vaines mes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Fais que ta voie soit loin d’elle; ne t’approche pas des portes de sa demeure,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'De peur qu’elle ne livre ta vie à des étrangers, et tes biens à des gens sans pitié;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'De peur que des étrangers ne se rassasient de tes richesses, et que le fruit de tes labeurs ne s’en aille dans la maison d’autrui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Et tu te repentirais à ton dernier jour, quand les chairs de ton corps seraient consumées, et tu dirais:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Pourquoi ai-je haï la discipline, et pourquoi mon cœur a-t-il éludé les réprimandes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Je n’ai point écouté la voix de celui qui me corrigeait et m’enseignait, et je ne lui ai point prêté l’oreille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'J’ai failli être en butte à tous les maux, au milieu de l’église et de la synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Bois des eaux de tes vases et des sources de ton puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Prends garde que chez toi les eaux ne débordent de ta fontaine, et que tes eaux ne s’écoulent dans les places publiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Possède-les seul, et que nul étranger n’y ait part.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Que l’eau de ta fontaine soit vraiment à toi, et réjouis-toi en la femme de ta jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Qu’elle soit pour toi comme la biche bien-aimée, comme le faon de tes grâces; qu’elle soit considérée comme ton bien propre, qu’elle t’assiste en toute circonstance; car, ravi de son amour, tu vivras longtemps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Garde-toi de l’intimité avec une étrangère; ne te laisse pas enlacer dans les bras d’une femme qui n’est point la tienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Car les voies de l’homme sont devant les yeux du Seigneur, et il observe tous ses sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Les iniquités pourchassent l’homme, et chacun est étreint par les chaînes de son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Un tel homme meurt comme ceux qui n’ont point de discipline, et il a été renversé dans la plénitude de ses jours; et sa folie l’a perdu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Mon fils, si tu t’engages pour un ami, tu livres ta main à un ennemi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Car les lèvres de l’homme sont pour lui un filet très-fort, et il est pris par les lèvres de sa propre bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Fais, ô mon fils, ce que je te recommande, et veille à te sauver; à cause de ton ami, tu t’es mis entre les mains des méchants; hâte-toi de t’affranchir, et stimule l’ami pour qui tu as répondu,.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'N’accorde point de sommeil à tes yeux, ni d’assoupissement à tes paupières,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Pour te sauver comme un daim des filets, et comme un oiseau du piège.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Va voir la fourmi, ô paresseux; regarde, et sois envieux de ses voies, et deviens plus sage qu’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Car elle n’a ni laboureurs, ni maîtres, ni personne qui la contraigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Cependant elle prépare l’été sa nourriture, et en fait d’abondants magasins au temps de la moisson. Ou bien encore va voir l’abeille, et apprends comme elle est industrieuse, et comme son industrie est digne de nos respects; car les rois et les infirmes usent, pour leur santé, des fruits de son labeur. Or elle est glorieuse et désirée de tous, et, si chétive qu’elle soit, on l’honore, parce qu’elle apprécie la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Jusques à quand, ô paresseux, resteras-tu couché? Quand sortiras-tu de ton sommeil?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Tu dors un moment, un moment tu t’assieds, tu t’assoupis un peu, tu te tiens un moment les bras croisés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Et cependant arrive sur toi la pauvreté comme un dangereux voyageur, et le besoin comme un agile courrier. Mais si tu es actif, ta moisson te viendra comme une fontaine, et l’indigence s’enfuira comme un courrier hors de service.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'L’homme insensé et pervers chemine en une voie qui n’est point bonne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Mais il approuve de l’œil, il fait signe du pied, il enseigne par le mouvement de ses doigts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Son cœur pervers pense à mal; en tout temps un tel homme porte le trouble dans la cité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'À cause de cela, soudain arrivera sa perte; ce sera une chute, une ruine sans remède.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Il se réjouit de toutes les choses que hait le Seigneur; aussi sera-t-il brisé à cause de l’impureté de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Son œil est superbe, sa langue inique; sa main verse le sang du juste;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Et son cœur roule de mauvais desseins, et ses pieds courent vers le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Témoin injuste, il fomente des faussetés, et soulève des discordes entre frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'O mon fils, garde les lois de ton père, et ne rejette pas les préceptes de ta mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Tiens-les toujours attachés en ton âme; mets-les comme un collier autour de ton cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Partout où tu iras, porte-les, et qu’ils soient avec toi; et quand tu dormiras, qu’ils te gardent, afin qu’à ton réveil ils s’entretiennent avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Les commandements de la loi sont une lampe, une lumière; c’est la voie de vie, c’est la correction et la discipline,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Qui te garderont de la femme mariée et des artifices de la langue étrangère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Que la convoitise de sa beauté ne triomphe pas de toi; ne te laisse pas prendre par tes yeux, ni ravir par ses paupières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Car la courtisane ne coûte que le prix d’un pain; la femme mariée prend les âmes des hommes qui ont tant de prix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Qui cachera du feu dans son sein sans brûler sa tunique?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Qui marchera sur des charbons ardents sans se brûler les pieds?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 29, 'Tel est celui qui a commerce avec la femme mariée; il ne sera point disculpé, non plus que celui qui l’aura touchée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 30, 'Il n’est pas étonnant qu’un voleur se cache dans la grange; car il vole pour rassasier son âme affamée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 31, 'Et s’il est pris, il rendra au centuple; et, dût-il donner tout ce qu’il possède, il se sauvera lui-même:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 32, 'Mais l’adultère, à cause de l’indigence de son cœur, a causé la perte de son âme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 33, 'Il supportera les hontes et les douleurs, et son opprobre ne sera point effacé dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 34, 'Car l’âme de l’époux est pleine de jalousie; il ne l’épargnera pas le jour du jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 35, 'Nul, au prix d’une rançon, n’éteindra sa haine, et il n’est point de dons si nombreux qui puissent l’apaiser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Mon fils, garde mes paroles, et renferme mes préceptes en toi-même. Mon fils, honore le Seigneur, et tu seras bon; et n’aie pas d’autre crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Garde mes préceptes, et tu vivras; et mes paroles, comme la prunelle de tes yeux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Attache-les autour de tes doigts; grave-les sur la table de ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Dis que la sagesse est ta sœur, et fais de la prudence ton amie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Afin qu’elle te garde de la femme étrangère et perverse, lorsqu’elle te provoquera avec des paroles flatteuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Car de sa fenêtre elle se penche sur les places publiques');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Pour voir un fils des insensés, un jeune homme pauvre d’intelligence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Passant à l’angle de la rue près de sa maison, et parlant');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Dans l’obscurité du soir, au moment du calme de la nuit et des ténèbres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Et la femme descend à sa rencontre; elle a cette beauté de courtisane qui fait tressaillir le cœur des adolescents:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Elle est volage et luxurieuse, et ses pieds ne peuvent se tenir au logis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Car tantôt elle rôde dehors, tantôt elle se tient à l’affût à tous les angles des places.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Puis elle l’arrête; elle l’embrasse, et lui dit d’une voix impudente:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'J’ai chez moi une victime pacifique; je rends grâces aujourd’hui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'C’est pour cela que je suis venue au-devant de toi; j’ai désiré ton visage, je t’ai trouvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'J’ai tressé les sangles de mon lit, et l’ai couvert de doubles tapis d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'J’ai parfumé ma couche de safran, et ma maison de cinnamome.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Viens, et jouissons de l’amitié jusqu’à l’aurore; entre, et livrons-nous à l’amour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Car mon mari n’est pas au logis; il est parti pour un long voyage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Il a pris en sa main un grand sac d’argent; il ne reviendra pas de longtemps dans sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Elle l’égare par ce flux de paroles; elle l’entraîne, avec le filet de ses lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Et lui la suit, sottement dupé, comme le bœuf se laisse conduire à la boucherie, et le chien à la chaîne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Ou comme la biche frappée d’un trait au foie; il se hâte comme un oiseau attiré au piège, ne sachant pas qu’il court à la perte de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Maintenant donc, ô mon fils, écoute-moi, et sois attentif aux paroles de ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Garde-toi de laisser ton cœur s’égarer dans ses voies;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Car elle en a blessé et abattu beaucoup, et ceux qu’elle a tués sont innombrables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Sa maison est le chemin de l’enfer, conduisant au réceptacle de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Tu proclameras la Sagesse, afin que la prudence t’obéisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Car elle se tient sur les cimes des monts; elle est debout au milieu des sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Elle s’assied devant les portes des riches, et à l’entrée des villes; elle chante:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'C’est vous, ô hommes, que j’appelle; j’élève ma voix devant les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Comprenez, innocents, la subtilité; et vous, ignorants, déposez la science en votre cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Écoutez-moi; car je vais dire des choses saintes, et proférer de mes lèvres la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Car ma langue va méditer la vérité, et j’ai en abomination les lèvres menteuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Toutes les paroles de ma bouche sont selon la justice; en elles rien d’oblique et de tortueux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Elles sont toutes offertes à ceux qui comprennent, et justes pour ceux qui trouvent la Sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Recevez l’instruction et non l’argent, et la science plutôt que l’or raffiné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Car la sagesse a plus de prix que les pierres précieuses, et rien de ce que l’on estime de plus précieux ne la vaut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Moi, la Sagesse, j’ai demeuré avec le conseil et le savoir; j’ai appelé à moi l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'La crainte du Seigneur hait l’iniquité, et l’insolence, et l’orgueil et les voies des méchants; et moi aussi, je hais les voies tortueuses des méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'C’est à moi le conseil et la fermeté, à moi la prudence, à moi la force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Par moi, les rois règnent, et les princes écrivent des jugements équitables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Par moi, les grands sont glorifiés; par moi, les monarques commandent à la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Moi j’aime ceux qui m’aiment, et ceux qui me cherchent me trouvent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'De moi dépendent la fortune et la gloire, et les grandes richesses et la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Mieux vaut recueillir mes fruits que de l’or et des pierres précieuses, et mes rejetons sont meilleurs que l’argent le plus pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Je me promène dans les voies de l’équité, et je reviens par les voies de la justice;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Pour distribuer à ceux qui m’aiment une part de mes richesses, et remplir de biens leurs trésors. Après vous avoir publié ce qui arrive chaque jour, je vais énumérer les choses qui sont de toute éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Le Seigneur m’a créée au commencement de ses voies, pour faire ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Il m’a établie avant le temps, au commencement, avant de créer la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Et avant de créer les abîmes, avant que l’eau jaillit des fontaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Il m’a engendrée avant que les montagnes et les collines fussent affermies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Le Seigneur a fait les champs et les déserts, et les cimes habitées sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Quand il a préparé le ciel, j’étais auprès de lui, et lorsqu’il a élevé son trône sur les vents,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 28, 'Et lorsqu’en haut il a donné aux nuées leur cohérence, et aux fontaines qui sont sous le ciel leur équilibre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 29, 'Et lorsqu’il a affermi les fondements de la terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 30, 'J’étais là, près de lui, disposant tout avec lui; j’étais là, et il se délectait en moi; chaque jour, à tout moment, je me réjouissais de la vue de son visage;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 31, 'Lorsqu’il s’applaudissait d’avoir achevé la terre, et se complaisait dans les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 32, 'Maintenant donc, mon fils, écoute-moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 33, 'Heureux l’homme qui m’écoutera, et le mortel qui gardera mes voies, veillant le jour à mes portes et gardant le seuil de ma demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 34, 'Car mes portes sont des portes de vie, et en elles réside la volonté du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 35, 'Ceux qui pèchent contre moi outragent leur âme, et ceux qui me haïssent aiment la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'La Sagesse a édifié pour elle une maison, et elle l’a appuyée sur sept colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Elle a égorgé ses victimes; elle a mêlé son vin dans un cratère et a dressé sa table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Elle a envoyé ses serviteurs, conviant à boire autour de son cratère, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Que l’insensé vienne à moi; et à ceux qui manquent de sens elle a dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Venez, mangez de mon pain; buvez du vin que j’ai mêlé pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Abandonnez la folie, pour régner dans l’éternité; cherchez la sagesse, et dirigez votre intelligence vers le savoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Celui qui veut instruire les méchants n’y gagnera que de la honte; celui qui blâme l’impie se moque de soi-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ne réprimande pas le méchant, de peur qu’il ne te haïsse; mais corrige le sage, et il t’aimera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Donne au sage une occasion d’apprendre, et il sera plus sage; avertis le juste, et il s’instruira de plus en plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'La crainte du Seigneur est le commencement de la sagesse, et le conseil des saints est l’intelligence; car connaître la loi, c’est l’œuvre d’un bon esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Et de cette manière tu vivras longtemps, et des années s’ajouteront à ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Mon fils, si tu es sage, tu le seras pour toi-même et tes proches; mais si tu deviens mauvais, toi seul en recueilleras des maux. Celui qui s’appuie sur des mensonges tente de gouverner les vents ou de poursuivre les oiseaux dans leur vol: car il a quitté les voies qui mènent à sa vigne; il a égaré la charrue de son labourage; il marche au travers d’un désert aride, d’une terre où l’on meurt de soif; il recueille de ses mains la stérilité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'La femme insensée et hardie, qui ne connaît pas la pudeur, en viendra à manquer d’un morceau de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Elle est assise devant la porte de sa maison, sur un siége apparent dans la rue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Appelant les passants qui vont droit leur chemin; disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Que le plus insensé d’entre vous se détourne vers moi; et à ceux qui manquent de sagesse, je m’adresse, en leur disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Goûtez avec joie des pains que je recèle, et de l’eau douce à la dérobée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Or il ne sait pas que des géants mêmes périssent auprès d’elle, et qu’il met le pied sur la trappe de l’enfer; mais hâte-toi, point de retard en ce lieu; n’arrête pas ton regard sur elle: ainsi tu t’abstiendras de l’eau étrangère; garde-toi de cette eau; ne bois pas à cette fontaine étrangère, afin que tu vives longtemps et que des années de vie s’ajoutent à tes années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Le fils sage réjouit son père; le fils insensé est le chagrin de sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Les trésors ne serviront de rien aux pervers; mais l’équité délivrera de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Le Seigneur ne laissera pas mourir de faim l’âme du juste; mais il détruira la vie des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'L’indigence abaisse l’homme; mais des mains fortes enrichissent. Le fils bien enseigné sera sage, et il se fera servir par l’insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Le fils prudent n’a point à souffrir de la grande chaleur; mais le fils pervers est un épi consumé par le vent pendant la moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'La bénédiction du Seigneur est sur la tête du juste; mais des deuils imprévus couvrent la tête des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'La mémoire des justes a la louange pour elle; mais le nom des impies s’éteint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Le sage recueille les commandements en son cœur; mais l’homme aux lèvres indiscrètes prend des détours et trébuche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Celui qui marche en sa simplicité, marche avec confiance; celui qui se détourne dans ses voies sera découvert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Celui qui approuve d’un regard rusé prépare toute sorte de chagrins aux hommes; mais celui qui réprimande avec franchise est un pacificateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Il y a une source de vie dans la main du juste; mais la perdition est cachée dans la bouche des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'La haine suscite la discorde; l’amitié protège tous ceux qui n’aiment point les querelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Celui dont les lèvres professent la sagesse, frappe d’une verge l’homme privé de sens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Les sages cachent leur science; mais la bouche du téméraire le conduit à la confusion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'La fortune des riches est leur forteresse, et la pauvreté est pour les impies le brisement du cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Les œuvres des justes donnent la vie; mais les fruits des impies sont autant de péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'L’instruction garde droites les voies de la vie; mais l’instruction superficielle égare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Les paroles bien mesurées recèlent la haine; mais ceux qui se répandent en injures sont des plus insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Par la multitude des paroles, tu n’éviteras pas le péché; par la discrétion des lèvres, tu seras sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'La langue du juste est de l’argent pur; mais le cœur de l’impie est sans valeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Les lèvres des justes savent les vérités sublimes; les insensés meurent dans l’indigence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 22, 'La bénédiction du Seigneur est sur la tête du juste; elle l’enrichit, et il ne s’y joindra aucune tristesse de cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 23, 'L’insensé fait le mal en riant; la sagesse de l’homme enfante la prudence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 24, 'L’impie est emporté dans sa perdition; mais le désir du juste est exaucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 25, 'Comme la tempête passe, ainsi l’impie disparaît; le juste s’en détourne, et il est sauvé pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 26, 'Comme le fruit vert nuit aux dents et la fumée aux yeux, de même l’iniquité nuit aux injustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 27, 'La crainte du Seigneur multiplie les jours; mais les années des impies seront abrégées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 28, 'La joie du juste est durable; l’espérance des impies périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 29, 'La crainte du Seigneur est la forteresse du saint; mais l’affliction vient à ceux qui font le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 30, 'Le juste ne se relâchera jamais; mais les impies n’habiteront pas la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 31, 'La bouche du juste distille la sagesse; la langue des impies périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 32, 'Les lèvres du juste distillent la grâce; la bouche des impies, la perversité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Les balances fausses sont en abomination au Seigneur; le poids juste lui est agréable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Où est l’orgueil, il y aura confusion; la bouche des humbles s’exerce à la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Le juste en mourant laisse des regrets; la mort des impies cause l’indifférence ou la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'L’équité trace des voies irréprochables; l’impiété trébuche contre l’injustice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'L’équité des hommes droits les sauve; les pervers sont pris dans leur propre perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'L’espérance des justes ne meurt pas avec eux; l’orgueil des impies ne leur survit point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Le juste échappe aux chasseurs d’hommes; à sa place, l’impie leur est livré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'La bouche de l’impie tend un piége aux citoyens; l’intelligence du juste les guide dans la bonne voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Grâce aux justes, une cité prospère; au contraire, elle est renversée par la bouche des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'L’insensé se joue des citoyens; un homme prudent ramène le calme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'L’homme à la langue double divulgue les conseils de l’assemblée; l’homme fidèle garde le secret sur les affaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Ceux qui n’ont point de gouvernail tombent comme des feuilles. Le salut réside dans une grande prudence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Le méchant fait le mal, même quand il se rapproche du juste; il n’aime pas son renom de fermeté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'La femme gracieuse fait la gloire de son mari; la femme qui hait la justice est un trône de déshonneur. Les paresseux manquent de richesses; les forts travaillent à en amasser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'L’homme charitable fait du bien à son âme; l’homme sans pitié perd son corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'L’impie fait des œuvres iniques; la race des justes recueille la récompense de la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Un fils juste est né pour la vie; ce que poursuit l’impie mène à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Les voies tortueuses sont en abomination au Seigneur; mais il agrée tous ceux qui sont irréprochables dans leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Celui qui, dans une pensée injuste, met sa main dans la main d’autrui ne sera point impuni; au contraire, qui sème la justice en récoltera le digne salaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Tel est un pendant d’oreille au museau d’une truie; telle est la beauté chez la femme sans sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Le désir du juste est bon sans réserve; l’espérance des impies périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Il en est qui, en distribuant leurs biens, les augmentent; il en est qui, même en amassant, s’appauvrissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Toute âme simple est bénie; l’homme irascible n’est pas honoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Que celui qui amasse du blé le tienne en réserve pour les peuples; la bénédiction est sur la tête de celui qui en fait part à autrui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Celui qui médite le bien cherche une grâce salutaire; celui qui songe au mal le recueillera pour lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Celui qui se fie en sa richesse tombera; celui qui s’attache aux choses justes fleurira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Celui qui ne s’occupe pas de sa propre maison n’aura que le vent pour héritage; l’insensé sera le serviteur du sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Du fruit de la justice naît l’arbre de vie; les âmes des pervers seront emportées avant le temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Si le juste est difficilement sauvé, que penser de l’impie et du pécheur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Celui qui aime la discipline aime la sagesse; celui qui hait les réprimandes est insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Le meilleur est celui qui a trouvé la grâce du Seigneur; l’homme pervers tombera dans l’oubli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'L’homme ne tire aucun profit de l’injustice; les racines des justes ne seront pas arrachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Une femme forte est une couronne pour son mari; comme un ver qui ronge le bois, une femme malfaisante perd son mari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Les pensées des justes sont des sentences; les impies n’ont pour se gouverner que la ruse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Les paroles des impies sont trompeuses; la bouche des hommes droits les sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Le jour où l’impie tombe, il est effacé; la maison des justes est inébranlable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'On loue la bouche d’un homme intelligent; les esprits vains sont moqués.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Mieux vaut être obscur et utile à soi-même, que se glorifier en manquant de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Le juste est compatissant, même pour la vie de ses bestiaux; les entrailles des impies sont sans pitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Qui travaille à sa terre se rassasiera de pain; mais ceux qui poursuivent des vanités sont dépourvus d’intelligence. Celui qui se plaît aux assemblées des buveurs léguera la honte à sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Les désirs des impies sont mauvais; les racines des hommes pieux sont indestructibles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Par le péché même de ses lèvres, le pécheur tombe en des filets; le juste y échappe, et celui dont l’œil est bon excite l’indulgence; celui qui se dispute aux portes irrite les âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 14, 'L’âme de l’homme sera remplie de biens provenant de sa bouche, et ses lèvres recevront leur récompense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 15, 'Les voies des insensés sont droites à leurs yeux; le sage écoute les conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 16, 'L’insensé à l’instant même montre sa colère; l’homme habile renferme en lui-même l’outrage qu’il a reçu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 17, 'Le juste déclare la pleine vérité; le témoin des méchants est trompeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 18, 'Il en est dont les paroles blessent comme des glaives; la langue des sages guérit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 19, 'Des lèvres véridiques n’ont point de détours dans leur témoignage; le témoin précipité a une langue inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 20, 'La fraude est dans le cœur de celui qui machine le mal; ceux qui veulent la paix seront dans la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 21, 'Rien d’injuste ne plaira au juste; les impies sont remplis de mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 22, 'Les lèvres trompeuses sont en abomination au Seigneur; il agrée l’homme de bonne foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 23, 'L’homme intelligent est un trône de science; le cœur des insensés ne rencontrera que malédictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 24, 'La main des élus aura sans peine la domination; les trompeurs seront livrés au pillage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 25, 'Les rumeurs sinistres troublent le cœur des justes; une bonne nouvelle les réjouit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 26, 'L’arbitre équitable est ami de soi-même; les calamités poursuivront le pécheur, et la voie des impies les mènera aux égarements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 27, 'Le trompeur n’atteindra pas de proie; c’est une richesse précieuse que d’être pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 28, 'Dans les voies de la justice est la vie; les voies des vindicatifs mènent à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 1, 'Le fils habile obéit à son père; le fils indocile marche à sa perte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 2, 'L’homme bon se nourrit des fruits de la justice; les âmes des pécheurs périront avant le temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 3, 'Veiller sur sa bouche, c’est garder son âme; avoir les lèvres téméraires, c’est se préparer des sujets de crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 4, 'L’oisif est toujours dans les regrets; les mains de l’homme fort sont diligentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 5, 'Le juste hait les paroles injustes; l’impie sera confondu, et n’aura pas la liberté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 6, 'Les uns se donnent pour riches, et n’ont rien; et d’autres se font humbles avec une grande richesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 7, 'La richesse d’un homme est la rançon de sa vie; le pauvre ne résiste pas à une menace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 8, 'La lumière brille perpétuellement sur les justes; la lumière des impies s’éteint. Les âmes artificieuses s’égarent dans le péché, tandis que les justes sont compatissants et miséricordieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 9, 'Le méchant fait le mal avec orgueil; pouvoir se juger soi-même, c’est être sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 10, 'La richesse rapidement acquise par le péché décroît; celui qui amasse avec piété s’enrichira. Le juste est compatissant, et il prête au pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 11, 'Mieux vaut d’abord aider de bon cœur que promettre et donner de l’espérance. Un bon désir est un arbre de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 12, 'Celui qui dédaigne une affaire sera dédaigné par elle; celui qui vénère les commandements aura la santé de l’âme. Au fils artificieux il n’arrivera rien de bon; au serviteur sage toute chose réussira; et sa voie sera constamment droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 13, 'La loi du sage est une source de vie; l’insensé mourra pris au piége.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 14, 'Un bon discernement attire la grâce; connaître la loi est d’une saine intelligence; la mépriser, c’est suivre une voie de perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 15, 'Tout homme habile sait ce qu’il fait; l’insensé déploie sur lui-même le malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 16, 'Un roi téméraire tombera dans l’adversité; un sage ministre le sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 17, 'La discipline éloigne la pauvreté et le déshonneur; celui qui est attentif aux réprimandes sera glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 18, 'Les désirs des hommes pieux charment l’âme; les œuvres des impies sont loin de la doctrine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 19, 'En marchant avec les sages, tu seras sage; celui qui marche avec les insensés se fera bientôt reconnaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 20, 'Les calamités poursuivront les pécheurs; les justes sont maîtres de tous les biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 21, 'L’homme bon laissera pour héritiers les fils de ses fils; les richesses des impies sont des trésors pour les justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 22, 'Les justes passeront beaucoup d’années dans la richesse; les injustes périront rapidement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 23, 'Celui qui épargne le bâton n’aime pas son fils; celui qui l’aime le châtie à propos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 24, 'Le juste en mangeant, rassasie son âme; les âmes des impies sont toujours à jeun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 1, 'Les femmes sages bâtissent leurs maisons; l’insensée les détruit de ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 2, 'Celui qui marche droit craint le Seigneur; celui qui s’avance en des voies tortueuses sera déshonoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 3, 'Une verge d’orgueil sort de la bouche des insensés; les lèvres des sages les gardent eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 4, 'Où il n’y a point de bœufs, la crèche est vide; où il y a abondance de grains, la force des bœufs est manifeste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 5, 'Le témoin fidèle ne ment pas; le faux témoin est un brandon de mensonges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 6, 'Tu chercheras la sagesse parmi les méchants, et tu ne la trouveras pas; auprès des sages, le discernement est sous ta main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 7, 'Toutes choses sont contraires à l’insensé; des lèvres sages sont l’arme de la doctrine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 8, 'La sagesse des habiles éclaire leurs voies; l’irréflexion des insensés les conduit à l’erreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 9, 'Les demeures des méchants ont besoin d’être purifiées; la maison du juste est agréable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 10, 'Le cœur de l’homme est inquiet; son âme est triste, et, lorsqu’il se réjouit, c’est qu’il ne se mêle point de honte à sa joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 11, 'Les maisons des impies seront effacées; les tentes des cœurs droits resteront debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 12, 'Il est une voie qui aux hommes semble droite; mais elle aboutit aux abîmes de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 13, 'La tristesse ne se mêle point aux joies sages; toujours le deuil succède aux fausses joies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 14, 'Le cœur audacieux s’enorgueillit de ses voies; l’homme bon se complaît en ses pensées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 15, 'L’ingénuité est crédule; l’expérience mène aux regrets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 16, 'Le sage a peur, et se détourne du méchant; l’insensé, confiant en lui-même, se mêle aux pervers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 17, 'L’homme irascible agit sans réflexion; l’homme sensé supporte beaucoup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 18, 'Les insensés ont le mal en partage; l’homme habile est maître de la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 19, 'Les mauvais tomberont devant les bons; et les impies seront des serviteurs aux portes des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 20, 'On n’aime pas les amis des pauvres; mais les amis des riches sont nombreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 21, 'Mépriser les indigents, c’est pécher; avoir compassion des pauvres, c’est se ménager la plus grande joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 22, 'Les cœurs égarés songent au mal; les bons songent à la miséricorde et à la vérité; ceux qui commettent le mal ne connaissent ni miséricorde ni vérité; les miséricordes et la fidélité sont à ceux qui font le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 23, 'Tout homme diligent a le superflu; tout homme ami des douceurs et des plaisirs serà dans l’indigence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 24, 'La couronne des sages est l’activité; le travail des injustes est mauvais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 25, 'Le témoin fidèle délivrera son âme du mal; le témoin trompeur est un brandon de mensonges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 26, 'Dans la crainte du Seigneur est l’espérance de la force; il laissera à ses enfants un appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 27, 'Les commandements du Seigneur sont une source de vie; ils nous font détourner des pièges de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 28, 'La gloire d’un roi est dans la multitude de la nation; son affliction, dans le petit nombre de ses sujets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 29, 'L’homme patient est un vrai sage; l’impatient, un insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 30, 'L’homme qui a bon cœur est le médecin de l’âme; un cœur trop sensible est un ver qui ronge les os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 31, 'Tromper l’indigent, c’est irriter son Créateur; celui qui honore Dieu a compassion du pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 32, 'L’impie sera rejeté à cause de sa malice; l’homme ferme en sa propre sainteté est vraiment juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 33, 'Dans le bon cœur d’un homme on trouve la sagesse; on ne la trouvera pas dans le cœur de l’insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 34, 'La justice élève une nation; les péchés amoindrissent un peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 35, 'Le serviteur prudent est agréable au prince, et par sa dextérité il évite la disgrâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 1, 'La colère perd même les sages: une réponse soumise détourne la fureur; un mot odieux l’excite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 2, 'La langue des sages sait ce qui est bon, et la bouche des insensés est messagère du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 3, 'En tout lieu, les yeux du Seigneur observent et les méchants et les bons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 4, 'Une langue sensée est l’arbre de vie; celui qui la conservera telle sera plein d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 5, 'L’insensé se raille des instructions d’un père; celui qui garde ses commandements est mieux avisé. Dans une grande justice, il y a une grande force; les impies seront, jusqu’à la racine, effacés de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 6, 'Dans les maisons des justes, il y a beaucoup de force; les fruits des impies périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 7, 'Les lèvres des sages sont liées par la discrétion; le cœur des insensés n’offre pas de sécurité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 8, 'Les victimes des impies sont en abomination au Seigneur; les vœux des cœurs droits lui sont agréables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 9, 'Les voies des impies sont en abomination au Seigneur; il aime ceux qui suivent la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 10, 'L’instruction d’un cœur innocent apparaît même aux yeux des passants; ceux qui haïssent les réprimandes finissent honteusement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 11, 'L’enfer et la perdition sont visibles pour le Seigneur; comment n’en serait-il pas de même du cœur des hommes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 12, 'L’ignorant n’aime point ceux qui le reprennent; il ne fréquente point les sages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 13, 'Le visage fleurit des joies du cœur; il s’assombrit dans la tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 14, 'Un cœur droit cherche la doctrine; la bouche des ignorants connaîtra le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 15, 'Les yeux des méchants ne voient jamais que le mal; ceux des bons sont toujours pleins de sérénité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 16, 'Mieux vaut une modeste part, avec la crainte du Seigneur, que de grands trésors sans cette crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 17, 'Mieux vaut un repas hospitalier, un plat de légumes offert avec bonne grâce et amitié, qu’un bœuf entier servi avec de la haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 18, 'Un homme colère prépare des querelles; un homme patient adoucit même celles qui allaient naître. L’homme patient éteindra les divisions; l’impie les allumera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 19, 'Les voies des paresseux sont semées d’épines; celles des hommes forts sont aplanies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 20, 'Le fils sage réjouira son père; le fils insensé se moque de sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 21, 'Les voies de l’insensé manquent de sagesse; l’homme prudent va droit son chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 22, 'Ceux qui n’honorent pas l’assemblée des anciens sont en désaccord; le conseil demeure dans le cœur des sages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 23, 'Le méchant n’obéit pas à la raison; il ne dira rien qui soit à propos et utile au bien public.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 24, 'Les pensées du sage conduisent à la vie; par elles il se détourne de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 25, 'Le Seigneur abat les maisons des superbes; il affermit l’héritage de la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 26, 'Les desseins iniques sont en abomination au Seigneur; les discours des hommes purs sont vénérés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 27, 'Il se perd lui-même celui qui se laisse gagner par des présents; celui qui les repousse avec indignation est sauvé; les péchés sont effacés par la foi et l’aumône; tout homme se préserve du mal par la crainte du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 28, 'La foi est le sujet des méditations des cœurs justes; de la bouche des impies sortent des paroles coupables. Les voies des hommes justes sont agréables au Seigneur; en les suivant, les ennemis mêmes deviennent amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 29, 'Dieu s’éloigne des méchants; il exaucera les vœux des justes. Mieux vaut petite récolte avec la justice, que grande abondance avec l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 1, 'Que le cœur de l’homme ait des pensées de justice, afin que Dieu le fasse cheminer dans la droite voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 2, 'L’œil réjouit le cœur par la vue des belles choses, et la bonne renommée engraisse les os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 3, 'Celui qui repousse les corrections est ennemi de soi-même; celui qui se rend aux réprimandes aime son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 4, 'La crainte du Seigneur est enseignement et sagesse; les plus grands honneurs lui seront rendus; pour les impies, ils périssent en un jour fatal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 5, 'Tout homme au cœur hautain est impur devant Dieu; celui qui, ayant une pensée injuste, met sa main dans la main d’autrui, ne sera pas innocent pour cela. Pratiquer la justice, c’est le commencement de la bonne voie, plus agréable à Dieu que le sacrifice des victimes. Celui qui cherche le Seigneur trouvera la science et la justice; ceux qui le cherchent avec droiture trouveront la paix. Toutes les œuvres du Seigneur sont selon la justice. L’impie est réservé pour un jour fatal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 6, 'L’oracle est sur les lèvres du roi; sa bouche ne s’égarera pas dans le jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 7, 'La justice du Seigneur tient la balance en équilibre; les œuvres de Dieu ont des poids justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 8, 'Celui qui fait le mal est en abomination au roi; car son trône repose sur la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 9, 'Les lèvres justes sont agréables au roi; il aime les paroles droites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 10, 'La colère du roi est messagère de mort; un homme sage l’apaisera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 11, 'Le fils du roi est dans la lumière de la vie; ses favoris sont comme un nuage d’arrière-saison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 12, 'Les enfants de la sagesse sont préférables à l’or; les enfants de la prudence sont préférables à l’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 13, 'Les sentiers de la vie détournent du mal; les voies de la justice mènent à une longue vie. Celui qui accepte les corrections prospèrera; celui qui se rend aux réprimandes deviendra sage. Celui qui est ferme dans ses voies garde son ami, et celui qui aime la vie sera sobre de paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 14, 'Le regret vient après l’orgueil; la ruine, après la méchanceté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 15, 'Mieux vaut avoir la douceur avec l’humilité, que partager les dépouilles avec les orgueilleux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 16, 'Être intelligent en affaires, c’est trouver des biens; mettre sa confiance dans le Seigneur, c’est être bien heureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 17, 'On dit des intelligents et des sages: Ce sont gens de peu; ou parlera mieux des hommes aux paroles mielleuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 18, 'L’intelligence est pour ceux qui la possèdent une source de vie; les insensés n’ont que la science du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 19, 'Le cœur du sage méditera tout ce que dira sa bouche, et sur ses lèvres il portera sa science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 20, 'Les bonnes paroles sont des rayons de miel; leur douceur est la guérison de l’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 21, 'Il est des voies qui semblent droites à l’homme; mais leur extrémité lui fait voir dans le fond de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 22, 'L’homme, en ses labeurs, travaille pour lui-même, et, de vive force, il éloigne sa ruine. Le fourbe porte sa perte sur sa langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 23, 'L’imprudent creuse pour son malheur, et sur ses lèvres il amasse du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 24, 'Le pervers répand le mal autour de lui, et sa fourbe allume des tisons de malheur, et il sépare les amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 25, 'L’injuste caresse ses amis, et les mène en des voies qui ne sont pas bonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 26, 'Celui qui, les yeux fixes, trame de mauvais desseins, recèle tout mal entre ses lèvres. C’est une fournaise de méchanceté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 27, 'La vieillesse est une couronne de gloire; on la trouve dans les voies de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 28, 'Mieux vaut l’homme patient que le fort, et celui qui maîtrise sa colère que celui qui prend une ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 29, 'Tout mal vient du sein des injustes; et toute justice, du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 1, 'Mieux vaut un morceau de pain avec la joie de la paix, qu’une maison pleine de biens et d’offrandes iniques avec des querelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 2, 'Le serviteur intelligent gouvernera des maîtres insensés, et il fera les parts entre les frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 3, 'Comme dans une fournaise on éprouve l’argent et l’or, ainsi les âmes sont élues par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 4, 'Le méchant obéit à la langue des pervers; le juste ne fait pas attention à des lèvres menteuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 5, 'Railler le mendiant, c’est irriter son Créateur; celui qui se réjouit de la ruine de son prochain ne sera point innocent; celui qui a des entrailles faciles à émouvoir obtiendra miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 6, 'Les fils de ses fils sont la couronne du vieillard; les pères sont la gloire des enfants. Le fidèle a le monde entier pour richesses; l’infidèle n’a pas même une obole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 7, 'Des livres fidèles ne vont pas à l’insensé, ni des livres trompeurs au juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 8, 'Les corrections sont, pour ceux qui les mettent à profit, une récompense de la grâce; où elles s’adressent, elles remettent dans le bon chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 9, 'Celui qui garde le secret sur les mauvaises actions, maintient les amitiés; celui à qui il est odieux de les cacher, sépare les amis et ceux d’une même maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 10, 'Une menace fait naître le repentir dans le cœur du sage; l’insensé ne sent pas même les coups de fouet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 11, 'Tout méchant excite des querelles; mais le Seigneur lui enverra un ange inexorable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 12, 'L’homme prudent n’est pas exempt de soucis; l’injuste ne songe qu’à mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 13, 'Celui qui rend le mal pour le bien n’éloignera pas le mal de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 14, 'L’autorité de la justice donne du pouvoir aux paroles; les séditions et les querelles précèdent la misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 15, 'Celui qui déclare le juste injuste et l’injuste juste, est impur et abominable aux yeux de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 16, 'À quoi servent ses richesses à l’insensé, puisque l’homme sans cœur ne pourra pas en acheter la sagesse? Celui qui exhausse sa maison cherche sa ruine; celui qui prend une voie mauvaise pour s’instruire tombera dans le malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 17, 'Aie en tout temps un ami; que tes frères te soient secourables dans tes nécessités: c’est pour cela qu’ils sont nés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 18, 'L’imprudent bat des mains et se complaît en lui-même, quand il s’est rendu caution d’une somme pour ses amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 19, 'Si l’on aime le péché, on se réjouit des querelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 20, 'Celui qui a le cœur dur ne trouvera pas de biens. L’homme dont la langue est facilement changeante tombera dans le malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 21, 'Le cœur de l’insensé est pour lui un sujet de troubles. Le père ne se réjouit pas en un fils ignorant; le fils sage réjouit sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 22, 'La joie du cœur donne la santé; les os d’un homme triste se dessèchent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 23, 'Les voies de celui qui emporte des présents iniques dans les plis de son manteau ne seront point prospères; l’impie s’écarte des voies de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 24, 'Sur la face du sage brille l’intelligence; les yeux de l’insensé sont égarés aux bouts du monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 25, 'Un fils insensé, courroux du père, douleur de la mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 26, 'Il n’est pas bien de nuire à un homme juste; conspirer contre des princes équitables est une iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 27, 'Celui qui s’abstient de paroles colères est un sage; l’homme patient est sensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 28, 'Si l’insensé cherche la sagesse, il sera réputé sage; et s’il ferme la bouche, il passera pour prudent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 1, 'L’homme qui veut rompre avec ses amis cherche des prétextes, et en tout temps il sera digne de blâme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 2, 'Celui qui manque de sens n’a que faire de la sagesse; il est plutôt conduit par la folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 3, 'Lorsque l’impie est tombé en un abîme de fautes, il n’en tient compte; mais la honte et les ignominies lui arrivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 4, 'La parole dans le cœur de l’homme est une eau profonde; un fleuve en jaillit, et une fontaine de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 5, 'Il n’est pas bien d’avoir égard à la personne de l’impie; se détourner de l’équité dans la jeunesse est une impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 6, 'Les lèvres de l’insensé le mènent à mal, et sa bouche hardie appelle la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 7, 'La bouche de l’insensé est sa ruine; ses lèvres sont un piége pour son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 8, 'La crainte abat les paresseux; les âmes des efféminés sont toujours affamées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 9, 'Qui n’a point d’ardeur en ses travaux est frère de celui qui se détruit lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 10, 'Le nom du Seigneur est d’une force toute - puissante; les justes qui courent à lui sont glorifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 11, 'Les biens du riche sont une forteresse; sa gloire projette au loin de l’ombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 12, 'Le cœur de l’homme s’exalte avant d’être brisé; il s’humilie avant d’être glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 13, 'Répondre avant d’avoir entendu, c’est insensé et blâmable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 14, 'Un serviteur prudent apaise la colère de l’homme; qui peut supporter un homme pusillanime?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 15, 'Le cœur de l’homme sensé possède la doctrine; les oreilles du sage cherchent l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 16, 'Les présents que fait un homme le grandissent et le font siéger parmi les puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 17, 'Le juste s’accuse le premier; mais s’il est ensuite attaqué, c’est son adversaire qu’on blâme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 18, 'L’homme silencieux apaise les contradictions; il juge entre les puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 19, 'Un frère, soutenu par son frère, est comme une puissante et haute cité; il est fort comme un palais solidement bâti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 20, 'L’homme remplit ses entrailles des fruits de sa bouche, et se rassasiera du fruit de ses lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 21, 'La mort et la vie sont au pouvoir de la langue; ceux qui la maîtrisent mangeront ses fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 22, 'Celui qui a trouvé une femme bonne a trouvé des grâces; il a reçu de Dieu l’allégresse. Celui qui répudie une femme bonne répudie une bonne fortune; celui qui garde une adultère est impie et insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 1, 'La folie de l’homme souille ses voies, et c’est Dieu qu’il accuse en son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 2, 'Les richesses attirent à l’homme beaucoup d’amis; au contraire, le pauvre est délaissé même de l’ami qu’il a.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 3, 'Le faux témoin ne sera pas impuni; celui qui appelle à tort en justice en portera la peine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 4, 'Beaucoup se prosternent en face des rois; tout méchant est pour l’homme un opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 5, 'Celui qui hait son frère pauvre est bien loin de l’amitié; c’est une bonne pensée qui fait approcher d’elle ceux qui la connaissent, et le sage la trouvera. Avoir fait beaucoup de mal entraîne à faire plus de mal encore; celui qui use de paroles provocatrices ne sera pas sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 6, 'Celui qui possède la sagesse est ami de soi-même, et celui qui garde la prudence trouvera le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 7, 'Le faux témoin ne sera pas impuni; celui qui attise une méchanceté périra par elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 8, 'Les délices ne sont pas pour l’insensé; qu’un serviteur ne se mette pas à commander avec orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 9, 'L’homme miséricordieux est patient; sa gloire retombe comme la punition sur le pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 10, 'La menace d’un roi est comme le rugissement du lion, et sa sérénité comme une rosée sur une prairie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 11, 'Le fils insensé est la honte de son père; les vœux qu’une courtisane paye de ses faveurs ne sont pas purs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 12, 'Les pères partagent entre les enfants leur maison et leurs richesses; mais la femme bien en harmonie avec un homme vient du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 13, 'La crainte possède l’efféminé; l’âme de l’oisif est indigente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 14, 'Garder les commandements, c’est sauver son âme; se négliger en sa voie, c’est courir à sa perte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 15, 'Celui qui est miséricordieux envers les pauvres prête à usure au Seigneur; Dieu le rétribuera selon ce qu’il aura donné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 16, 'Corrige ton fils; c’est ainsi qu’il sera ton espérance. Ne sois pas exalté en ton âme jusqu’à l’orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 17, 'L’homme malveillant sera puni sévèrement; s’il nuit à autrui, il nuit aussi à son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 18, 'Écoute, ô mon fils, les instructions de ton père pour être sage jusqu’à ta dernière heure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 19, 'De nombreuses pensées roulent dans le cœur de l’homme; le conseil du Seigneur demeure dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 20, 'La miséricorde est un fruit pour l’homme; mieux vaut un mendiant juste qu’un riche trompeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 21, 'La crainte du Seigneur est la vie de l’homme; celui qui n’a pas cette crainte habitera des lieux où la doctrine est inconnue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 22, 'Celui qui cache ses mains sous son manteau, avec de mauvais desseins, n’aura garde de les porter à sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 23, 'Les coups qui le flagellent rendent l’insensé plus réfléchi; mais si l’on reprend le sage, il comprend aussitôt la réprimande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 24, 'Celui qui n’honore pas son père et repousse sa mère sera couvert de honte, et recevra un blâme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 25, 'Le fils qui néglige de garder les instructions de son père tramera de mauvais desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 26, 'Celui qui répond pour un jeune insensé outrage la justice; la bouche des impies dévore l’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 27, 'Des fouets sont préparés pour les pervers, et des châtiments pour les insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 1, 'Le vin est déréglé, et l’ivresse insolente; l’insensé se laisse prendre dans leurs filets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 2, 'La menace d’un roi ne diffère point de la colère du lion; celui qui le provoque pèche contre sa propre vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 3, 'C’est une gloire pour un homme de se détourner des contestations; au contraire, le fou s’y laisse aller.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 4, 'Le paresseux, quand on le blâme, n’en a point honte; il en est de même de celui qui emprunte du blé à usure pendant la moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 5, 'Le conseil dans le cœur de l’homme est une eau profonde; l’homme prudent y saura puiser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 6, 'Un homme est une grande chose; un homme miséricordieux est un trésor; mais un homme fidèle est difficile à trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 7, 'L’homme irréprochable qui se tourne vers la justice laissera ses enfants heureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 8, 'Lorsqu’un roi juste s’est assis sur son trône, nul mal ne résiste à ses regards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 9, 'Qui peut se vanter d’avoir le cœur chaste? Qui osera dire: Je suis pur de tout péché?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 10, 'La lampe de celui qui décrie son père ou sa mère s’éteindra; les prunelles de ses yeux verront les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 11, 'Le bien acquis tout d’abord à la hâte, à la fin ne sera pas béni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 12, 'Garde-toi de dire: Je me vengerai de mon ennemi; mais attends le Seigneur, afin qu’il te seconde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 13, 'Avoir deux poids et deux mesures, et en faire usage deux choses infâmes devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 14, 'Le jeune homme en compagnie d’un saint sera réservé dans ses mœurs, et sa voie sera droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 15, 'L’oreille entend, et l’œil voit; l’un et l’autre sont l’œuvre du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 16, 'Ne te plais pas à médire, și tu ne veux être chassé. Ouvre les yeux, et rassasie-toi de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 17, 'Le double poids est en abomination au Seigneur, et les fausses balances ne sont point bonnes à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 18, 'La marche d’un homme est maintenue droite par le Seigneur; car comment un mortel discernerait-il ses voies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 19, 'L’homme tombe dans un piége, quand il se hâte trop de consacrer ses biens; car après le vœu vient le repentir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 20, 'Un roi sage est le vanneur des impies, et il fait passer sur eux une roue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 21, 'L’esprit de l’homme est une lumière du Seigneur, qui éclaire jusqu’au fond des entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 22, 'La miséricorde et la vérité sont la garde d’un roi, et avec la justice elles font cercle autour de son trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 23, 'La sagesse est la parure des jeunes gens; les cheveux blancs, la gloire des vieillards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 24, 'Les contusions et les blessures sont le partage des méchants; ils ont des plaies jusqu’au fond des entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 1, 'Tel est le cours de l’eau, tel est le cœur du roi dans la main de Dieu; de quelque côté qu’il veuille l’incliner, c’est là qu’il le dirige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 2, 'Tout homme semble juste à ses yeux; mais Dieu dirige les cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 3, 'Faire des choses justes et dire la vérité, est plus agréable au Seigneur que le sang des victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 4, 'Le cœur de l’audacieux est superbe dans son insolence; la lampe des impies est le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 5, 'Amasser des trésors avec une langue trompeuse, c’est poursuivre des vanités sur les filets de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 6, 'La destruction habitera avec les impies, parce qu’ils ne veulent pas pratiquer la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 7, 'Devant les hommes tortueux Dieu place des voies tortueuses; car ses œuvres sont droites et pures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 8, 'Mieux vaut demeurer dans un carrefour en plein air, que dans une grande maison bien crépie avec l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 9, 'Nul homme ne sera miséricordieux pour l’âme des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 10, 'La punition de l’intempérant rend l’innocent plus réfléchi; l’homme sage et intelligent en reçoit une leçon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 11, 'Le juste pénètre le cœur des impies, et les méprise à cause de leur malice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 12, 'Celui qui ferme l’oreille au cri du faible criera lui-même, et nul ne l’écoutera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 13, 'Un don secret détourne les colères; celui qui épargne les présents excite de violents courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 14, 'La joie du juste est de faire justice; le saint n’est pas pur aux yeux des méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 15, 'L’homme qui s’égare loin des voies de la justice se reposera dans l’assemblée des géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 16, 'L’indigent aime la joie; il désire le vin et l’huile en abondance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 17, 'Les déréglés sont en abomination aux justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 18, 'Mieux vaut habiter dans le désert qu’avec une femme bavarde, colère et querelleuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 19, 'Un trésor désirable reposera sur la bouche du sage; mais les insensés le dévorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 20, 'Les voies de la justice et de la miséricorde conduisent à la vie et à la gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 21, 'Le sage a pris d’assaut les villes fortes; il a démoli les forteresses sur lesquelles comptaient les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 22, 'Celui qui est maître de sa bouche et de sa langue garde son âme de la tribulation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 23, 'L’homme audacieux, arrogant et présomptueux peut être appelé un fléau; le vindicatif n’est pas dans la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 24, 'Les désirs tuent le paresseux; car ses mains ne se lèvent pas pour faire quoi que ce soit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 25, 'L’impie, durant tout le jour, a des désirs mauvais; le juste n’est avare ni de compassion ni de miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 26, 'Les sacrifices des impies sont en abomination au Seigneur; car ils les offrent le cœur plein d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 27, 'Le faux témoin périra; un homme docile parlera avec réserve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 28, 'L’impie compose effrontément son visage; mais l’homme droit saura bien discerner ses voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 29, 'Il n’est point de sagesse, point de courage, point de raison chez l’impie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 30, 'Le cheval est tout prêt pour le jour du combat; mais le secours vient du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 1, 'Une bonne renommée vaut mieux que de grandes richesses; la bonne grâce vaut mieux que l’or et l’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 2, 'Le riche et le pauvre se sont rencontrés; c’est le Seigneur qui les a créés tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 3, 'L’homme habile, en voyant le pervers sévèrement châtié, se corrige de lui-même; les imprudents passent outre, et sont punis à leur tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 4, 'La crainte du Seigneur fait naître la sagesse, et les biens, et la gloire, et la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 5, 'Les chausse-trapes et les filets sont dans les voies tortueuses; mais celui qui garde son âme les évitera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 6, 'Les riches commanderont aux pauvres, et des serviteurs prêteront à usure à leurs propres maîtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 7, 'Qui sème la méchanceté récoltera le malheur, et il recevra le châtiment de ses œuvres. Dieu bénit l’homme joyeux et libéral; mais le mauvais semeur sera puni par la vanité même de ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 8, 'Celui qui a pitié des pauvres sera lui-même nourri; car il a donné de son pain au mendiant. Celui qui donne des présents se prépare victoire et honneur; mais il perd l’âme de ceux qui les acceptent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 9, 'Chassez de l’assemblée l’homme de pestilence; la discorde en sortira avec lui; car, lorsqu’il s’y assied, il la déshonore tout entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 10, 'Le Seigneur aime les cœurs saints, et tous les innocents lui sont agréables; un roi gouverne à la parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 11, 'Les yeux du Seigneur surveillent la doctrine; le pervers méprise sa parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 12, 'Le paresseux apporte des excuses, et dit Il y a un lion sur le chemin, et des assassins dans les rues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 13, 'La bouche des méchants est un profond abîme; celui qui hait le Seigneur y tombera. Il Y a devant l’homme des voies mauvaises, et il n’aime pas s’en détourner; cependant il est nécessaire d’éviter toute voie mauvaise et tortueuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 14, 'La folie est attachée au cœur du jeune homme; la verge et la discipline sont loin de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 15, 'Celui qui trompe l’indigent augmente ses biens; mais il les diminue en faisant des présents au riche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 16, 'Incline ton oreille aux discours du sage; sois attentif à mes paroles; affermis ton cœur sur elles, afin que tu saches qu’elles sont bonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 17, 'Si tu les déposes en ton cœur, elles réjouiront ton cœur et tes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 18, 'Que ton espérance soit dans le Seigneur, et qu’il te fasse connaître sa voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 19, 'Grave ces choses trois fois sur la face de ton cœur, afin de posséder la sagesse et la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 20, 'C’est pour cela que je t’enseigne la parole véritable et la doctrine bonne à suivre, afin que tu répondes les ́paroles de la vérité à ceux qui se présenteront devant toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 21, 'Ne fais pas violence au pauvre, car il est dans le besoin; devant les portes de la ville, ne méprise point l’homme sans appui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 22, 'Car le Seigneur lui-même plaidera sa cause; et ainsi tu mettras ton âme en un sûr asile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 23, 'Ne sois pas le compagnon d’un orgueilleux; ne demeure pas avec un ami porté à la colère;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 24, 'De peur que tu n’apprennes leurs voies, et que tu n’en reçoives des filets pour ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 25, 'Ne t’engage pour personne, même par crainte de déplaire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 26, 'Car si tu n’as pas de quoi payer, ils te prendront ta couverture sur les flancs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 27, 'Ne déplace pas les bornes que, de tout temps, tes pères ont posées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 28, 'Il convient que l’homme clairvoyant et habile aú travail s’approche des rois, mais non qu’il s’approche des pervers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 1, 'Si tu t’assieds pour dîner à la table d’un prince, fais bien attention à ce qui te sera présenté:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 2, 'Puis étends la main, sachant qu’il convient qu’on te serve de tels mets; toutefois, même si tu as grand appétit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 3, 'Ne convoite point leurs repas; car c’est là une vie factice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 4, 'Si tu es pauvre, n’aspire pas à la richesse; repousse-la même en pensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 5, 'Si tu fixes ton regard sur elle, tu la vois disparaître; car elle a, comme l’aigle, des ailes prêtes à s’envoler, et retourne à la maison de son premier maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 6, 'Ne dîne pas avec un homme envieux; ne désire rien de sa table;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 7, 'Car il mange et il boit comme on avalerait un cheveu. Ne l’introduis pas chez toi, et ne mange pas un morceau avec lui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 8, 'Car il le vomirait et souillerait tes meilleures paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 9, 'Ne dis rien à l’insensé, de peur que peut-être il ne tourne en dérision tes sages discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 10, 'Ne dépasse pas les bornes anciennes, et n’entre pas dans le champ de l’orphelin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 11, 'Car il est fort celui que le Seigneur rachète; et, si tu es en procès avec lui, Dieu plaidera sa cause.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 12, 'Livre ton cœur à la discipline, et prépare ton oreille aux paroles de la doctrine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 13, 'Ne cesse de corriger un enfant; car si tu le frappes de verges, il n’en mourra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 14, 'Et si tu le frappes de verges, tu sauveras son âme de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 15, 'Mon fils, si ton cœur est sage, tu réjouiras aussi mon cœur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 16, 'Et si tes lèvres sont droites, elles converseront avec mes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 17, 'Que ton cœur ne porte point envie aux pécheurs; mais sois toujours dans la crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 18, 'Car si tu observes ces choses, tu auras des descendants, et ton espérance ne sera pas trompée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 19, 'Écoute, mon fils, et sois sage; et maintiens droites les pensées de ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 20, 'Ne sois pas buveur de vin; évite les longs banquets et la profusion des viandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 21, 'Car l’ivrogne et le débauché mendieront; le paresseux sera revêtu de haillons en lambeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 22, 'Écoute, mon fils, le père qui t’a engendré, et ne méprise pas ta mère parce qu’elle a vieilli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 23, 'Un père juste élève bien ses enfants, et la sagesse d’un fils réjouit son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 24, 'Que ton père et ta mère se réjouissent en toi, et que celle qui t’a enfanté soit heureuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 25, 'Mon fils, donne-moi ton cœur; que tes yeux gardent mes voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 26, 'La maison étrangère est comme un tonneau percé; il est étroit le puits de l’étranger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 27, 'Celui qui les recherche périra bientôt, et tout pécheur sera détruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 28, 'Pour qui les gémissements? pour qui le trouble? pour qui les contestations? pour qui les ennuis et les entretiens frivoles? pour qui les repentirs inutiles? pour qui les yeux livides?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 29, 'N’est-ce pas pour ceux qui passent leur temps dans l’ivresse et qui hantent les lieux où l’on boit? Ne vous enivrez pas; mais faites votre société des hommes justes, et fréquentez-les publiquement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 30, 'Car si vos yeux s’arrêtent sur les fioles et les coupes, plus tard vous marcherez plus nu qu’un pilon à mortier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 31, 'L’homme ivre finit par s’étendre comme si un serpent l’avait mordu; le venin se répand sur lui comme de la dent d’un reptile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 32, 'Si tes yeux regardent une femme étrangère, ta langue aussitôt divaguera,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 33, 'Et tu seras gisant comme au sein de la mer, et comme un pilote au milieu de l’orage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 34, 'Et tu diras: On m’a frappé, et je n’en ai pas souffert; on s’est joué de moi, et je ne m’en suis pas douté; quand viendra l’aurore, pour m’en aller encore chercher des hommes avec qui je puisse me retrouver?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 1, 'Mon fils, ne rivalise point avec les méchants, et ne désire pas être avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 2, 'Car leur cœur médite des fraudes, et leurs lèvres disent des paroles affligeantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 3, 'La sagesse hâtit une maison; l’intelligence la dirige;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 4, 'Avec la doctrine on remplit les celliers de tout ce qu’il y a de riche, de précieux et de bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 5, 'Mieux vaut le sage que le fort, et un homme de bon sens que de vastes domaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 6, 'Avec l’art de gouverner, on conduit la guerre; avec un cœur résolu, on trouve le salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 7, 'La sagesse et les bonnes pensées sont à la porte des sages; les sages ne se détournent pas de la parole du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 8, 'Mais ils sont appréciés dans les conseils. La mort surprend les imprudents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 9, 'L’insensé meurt dans son péché. L’impureté est dans l’homme de pestilence;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 10, 'Il sera déshonoré au jour fatal, au jour de la tribulation, jusqu’à ce qu’il soit renversé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 11, 'Délivre ceux que l’on conduit à la mort; rachète ceux qu’on va faire mourir, et n’y épargne pas tes soins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 12, 'Si tu dis: Je ne connais pas cet homme; sache que Dieu connaît tous les cœurs; celui qui a donné le souffle à tous, sait toutes choses, et il rétribue chacun selon ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 13, 'Mon fils, mange du miel; car le rayon de miel est bon; que ton gosier en goûte la douceur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 14, 'C’est ainsi que tu feras comprendre la sagesse à ton âme; car si tu l’acquiers, ta fin sera bonne, et l’espérance ne t’abandonnera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 15, 'Ne conduis pas l’impie dans les pâturages des justes; ne te laisse pas séduire par l’appât de la gourmandise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 16, 'Car le juste tombera sept fois, et il se relèvera; mais les impies seront sans force dans le malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 17, 'Si ton ennemi tombe, ne te moque pas de lui, et ne t’enorgueillis pas de sa ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 18, 'Car le Seigneur te verrait, et il ne t’aurait point pour agréable, et il détournerait sa colère de ton ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 19, 'Ne prends point part aux joies des méchants; ne porte point envie aux pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 20, 'Car les pervers n’auront point de postérité, et la langue des impies s’éteindra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 21, 'Crains Dieu et le roi, mon fils, et ne leur désobéis jamais. 23. Voici ce que je dis, à vous sages, pour que vous le sachiez: Il n’est pas bien, en justice, d’avoir égard au rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 24, 'Ceux qui disent de l’impie: C’est un juste, seront maudits du peuple et odieux aux nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 25, 'Mais ceux qui le réprimandent paraîtront meilleurs, et la bénédiction viendra sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 26, 'On baisera les livres qui diront de bonnes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 27, 'Prépare ton ouvrage au dehors; arrive à ton champ, tout préparé; marche sur mes traces, et tu réédifieras ta maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 28, 'Ne porte pas contre un concitoyen de faux témoignage, et n’ouvre pas les lèvres contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 29, 'Ne dis pas: Comme il m’a traité, je le traiterai; je me vengerai du tort qu’il m’a fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 30, 'L’insensé est comme un champ; l’homme qui manque d’esprit est comme un vignoble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 31, 'Si tu le délaisses, il sera stérile et tout couvert de mauvaises herbes; il dépérit, et sa clôture de pierres s’écroule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 32, 'À la fin, j’ai réfléchi et j’ai songé à chercher la vraie doctrine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 33, 'Je sommeille un moment; un moment je m’endors, et je me tiens un moment les bras croisés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 34, 'Si tu fais cela, l’indigence t’arrivera à grands pas, et le besoin fondra sur toi comme un agile coursier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 50, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 51, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 52, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 53, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 54, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 55, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 56, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 57, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 58, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 59, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 60, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 61, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 62, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 63, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 64, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 65, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 66, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 67, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 68, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 69, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 70, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 71, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 72, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 73, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 74, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 75, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 76, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 77, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 1, 'Voici maintenant les sentences du roi Salomon qui n’ont point été classées et qu’ont transcrites les amis d’Ézéchias, roi de la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 2, 'La gloire de Dieu cèle sa parole; la gloire d’un roi apprécie toute chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 3, 'Le ciel est haut, la mer est profonde; mais le cœur d’un roi ne peut être sondé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 4, 'Bats de l’argent rouillé, et il sera tout à fait purifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 5, 'Extermine les impies devant le roi, et son trône se maintiendra dans la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 6, 'Ne te vante pas en présence du roi; ne promets rien dans les demeures des princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 7, 'Car il vaut mieux que l’on te dise: Viens auprès de moi, que de t’humilier en présence d’un prince. Ne dis rien que tes yeux ne l’aient vu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 8, 'Ne t’engage pas inopinément dans une querelle, de peur que tu ne t’en repentes à la fin. Si ton ami vient à te réprimander,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 9, 'Retire-toi dans le secret avec lui, et ne le méprise pas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 10, 'De peur que ton ami n’en vienne aux reproches; car alors ce seraient des querelles et des haines sans fin, et qui seraient pour toi comme la mort. La grâce et l’amitié nous délivrent de tout mal; conserve-les en toi, pour ne point devenir un sujet d’outrages, et garde tes voies dans la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 11, 'Parler raison vaut un collier de cornaline mêlé de grains d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 12, 'Une sage parole, dans une oreille docile, vaut un pendant d’oreille où l’or est entrelacé de cornalines de grand prix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 13, 'Le messager fidèle est, pour ceux qui l’envoient, aussi agréable que le serait la neige au temps de la moisson; il réjouit les cœurs de ceux qui l’ont envoyé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 14, 'L’homme qui se glorifie d’un présent trompeur ne vaut pas mieux que des fléaux éclatants, tels que la tempête, les sombres nuées ou les torrents de pluie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 15, 'La patience fait la prospérité des rois, et une langue douce amollit jusqu’aux os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 16, 'Si tu trouves du miel, n’en mange que ce qui te suffit, de peur que tu ne vomisses, si tu t’en es gorgé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 17, 'Entre rarement chez ton ami, de peur que, rassasié de toi, il ne te prenne en haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 18, 'L’homme qui porte contre son ami un faux témoignage ressemble à une massue, à un glaive, à une flèche acérée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 19, 'La dent du méchant et le pied du pervers seront détruits au jour de l’adversité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 20, 'Comme le vinaigre ne vaut rien à un ulcère, ainsi la douleur du corps attriste le cœur; et comme le bois est rongé par la pourriture, et les vêtements par un ver, ainsi le cœur de l’homme est rongé par la tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 21, 'Si ton ennemi a faim, nourris-le; s’il a soif, donne-lui à boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 22, 'En agissant ainsi, tu amasseras sur sa tête des charbons ardents, et le Seigneur te comblera de biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 23, 'L’aquilon excite les nuées; un front sans pudeur irrite la langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 24, 'Mieux vaut demeurer dans un coin de la terrasse qu’avec une femme querelleuse, en une maison commune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 25, 'Comme l’eau fraîche est douce à une âme altérée, ainsi est bonne la nouvelle arrivant d’une terre lointaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 26, 'Si quelqu’un ferme un puits ou corrompt une source d’eau, c’est une chose funeste comme un juste tombant en présence de l’impie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 27, 'Il n’est pas bon de manger beaucoup de miel; mais il est juste d’honorer les sages discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 28, 'Comme une ville dont les remparts sont renversés, et qui n’est plus fortifiée, ainsi est un homme qui agit sans conseil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 1, 'Il y a des rosées pendant la moisson, et des pluies pendant l’été; mais il n’est point de gloire pour l’insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 2, 'Les oiseaux s’envolent et même les autruches: ainsi les vanités s’évanouissent sans arriver à rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 3, 'Comme est le fouet au cheval, l’aiguillon à l’âne, ainsi est la verge à une nature déréglée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 4, 'Ne réponds point au fou selon sa folie, de peur que tu ne deviennes semblable à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 5, 'Mais réponds au fou selon sa folie, de peur qu’il ne semble sage à tes dépens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 6, 'Celui qui envoie ses paroles par un messager imprudent expose ses propres voies à un affront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 7, 'Interdis aux insensés l’usage de leurs jambes, et empêche l’iniquité de sortir de leur bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 8, 'Celui qui attache la pierre à sa fronde ressemble à celui qui glorifie un insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 9, 'Des épines poussent dans la main d’un homme ivre, et la servitude dans la main des insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 10, 'La chair des insensés est pleine de trouble; car leurs passions se brisent dans leur choc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 11, 'Comme le chien, lorsqu’il revient à son vomissement, inspire le dégoût; ainsi est l’insensé qui, en sa malice, retourne à son péché. Il est une honte qui conduit au mal; il est une honte pleine de gloire et de grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 12, 'J’ai vu un homme qui, lui-même, s’estimait sage; cependant l’insensé a plus de confiance que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 13, 'Le paresseux que l’on envoie en voyage dit: Il y a un lion sur le chemin et des assassins dans les rues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 14, 'Comme la porte tourne sur ses gonds, ainsi fait le paresseux sur son lit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 15, 'Le paresseux, s’il a caché sa main sous son manteau, n’aura pas le courage de la porter à sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 16, 'Le paresseux se croit plus sage que celui qui rapporte une dépêche et en reçoit un salaire abondant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 17, 'Se mettre en avant pour la querelle d’autrui, c’est comme prendre un chien par la queue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 18, 'On lance parmi les hommes des paroles comme des traits; celui qu’elles atteignent le premier succombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 19, 'C’est ce qui arrive à tous ceux qui dressent des embûches à leurs amis; et si l’on s’en aperçoit, ils disent Je l’ai fait en jouant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 20, 'Le feu s’active, s’il y a beaucoup de bois; où il n’y a point de contradicteur, les querelles s’apaisent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 21, 'Le charbon et le bois dans le foyer animent le feu; le médisant entretient le trouble des querelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 22, 'Les paroles du trompeur sont douces; mais elles blessent jusqu’au fond des entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 23, 'L’argent donné pour tromper ne vaut pas mieux qu’un coquillage. Des lèvres frivoles cachent un mauvais cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 24, 'Un ennemi que l’on voit pleurer promet beaucoup des lèvres; mais en son cœur il trame quelque fraude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 25, 'Si ton ennemi te prie à grands cris, ne te laisse pas persuader; car il a sept méchancetés dans l’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 26, 'Celui qui dissimule sa haine cherche à tromper; mais il a beau cacher ses fautes, le monde le connaît bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 27, 'Celui qui creuse une fosse pour son prochain y tombera; celui qui roule une pierre la roule sur lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 28, 'Une langue trompeuse hait la vérité; une bouche indiscrète est une cause de ruines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 1, 'Ne te glorifie pas des choses de demain; car tu ne sais pas ce qu’enfantera le jour qui va venir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 2, 'Que ton prochain te loue, et non ta bouche; qu’un étranger fasse ton éloge, et non tes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 3, 'La pierre est lourde et le sable est difficile à transporter; la colère de l’insensé est plus pesante que la pierre et le sable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 4, 'Le courroux est sans pitié, la colère pénétrante; mais l’envie ne peut rien supporter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 5, 'Mieux vaut le blâme à découvert que des amitiés cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 6, 'Les blessures faites par un ami sont plus dignes de confiance que les baisers d’un ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 7, 'L’âme dans la satiété ne fait aucun cas d’un rayon de miel; à l’âme affamée tout semble doux, même les choses amères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 8, 'L’homme qui s’est expatrié est réduit en esclavage, comme le petit oiseau tombé de son nid.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 9, 'Le cœur se réjouit du vin, des parfums et de l’encens; mais l’âme est déchirée par les malheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 10, 'N’abandonne point ton ami ni l’ami de ton père; si tu es en détresse, n’entre point dans la maison de ton frère; mieux vaut un ami auprès de toi qu’un frère qui demeure au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 11, 'Sois sage, ô mon fils, afin que ton cœur se réjouisse; éloigne de toi les paroles de blâme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 12, 'L’homme habile, à l’approche d’un malheur, se tient caché; mais les insensés courent au-devant, et en portent la peine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 13, 'Ote son manteau à quiconque ravage le champ d’autrui; car c’est un méchant qui a passé là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 14, 'Celui qui bénira son ami à haute voix, dès l’aurore, semblera ne différer en rien de celui qui le maudit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 15, 'La pluie, en hiver, tombant dans une maison en chasse le maître; il en est de même d’une femme querelleuse dans sa propre maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 16, 'L’aquilon est un vent rigoureux, et pourtant il est réputé de bon augure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 17, 'Le fer aiguise le fer; ainsi l’ami ranime le visage de son ami.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 18, 'Qui plante un figuier en mange les fruits; qui garde son maître sera honoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 19, 'Les visages ne ressemblent point aux visages; ainsi en est-il des pensées des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 20, 'L’enfer et la perdition ne sont jamais rassasiés; de même les yeux des hommes sont insatiables; l’œil imprudent et la langue déréglée sont en abomination au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 21, 'On éprouve par le feu l’or et l’argent; l’épreuve de l’homme est la bouche de ceux qui le louent. Le cœur déréglé cherche à faire le mal; le cœur droit cherche à s’instruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 22, 'Tu auras beau flageller en pleine assemblée l’imprudent qui se déshonore, tu ne lui ôteras point son imprudence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 23, 'Apprends à bien connaître les besoins de tes brebis, et applique ton cœur au soin de tes grands troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 24, 'La force et le pouvoir de l’homme ne durent pas des siècles; ils ne passent pas de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 25, 'Occupe-toi de l’herbe des champs; fauche tes prés et recueille du fourrage durant l’été,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 26, 'Si tu veux avoir des brebis pour te vêtir. Cultive tes champs pour avoir des agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 27, 'Mon fils, tu tiens de moi des préceptes sûrs pour ta vie et pour la vie de tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 1, 'L’impie prend la fuite, quoique personne ne le poursuive; le juste est ferme comme un lion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 2, 'Les péchés des impies excitent des querelles; l’homme habile saura les éteindre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 3, 'L’homme hardi dans son impiété trompe les pauvres; il est comme une pluie violente et désastreuse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 4, 'De même ceux qui délaissent la loi louent l’impiété; mais ceux qui aiment la loi s’entourent d’un rempart.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 5, 'Les méchants ne conçoivent pas la justice; mais ceux qui cherchent le Seigneur ont l’intelligence de toute chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 6, 'Mieux vaut un pauvre qui marche selon la vérité qu’un riche trompeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 7, 'Le fils intelligent garde la loi; celui qui mène une vie déréglée déshonore son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 8, 'Augmenter sa richesse par l’usure et les biens illicites, c’est thésauriser pour l’homme miséricordieux envers les pauvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 9, 'Quiconque détourne son oreille pour ne point entendre la loi, sa prière sera en abomination au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 10, 'Celui qui égare les justes dans une voie mauvaise marche lui-même à la perdition. Les déréglés passeront auprès des biens, mais n’y entreront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 11, 'Le riche est sage à ses propres yeux; le pauvre doué d’intelligence le condamnera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 12, 'Grâce au secours de Dieu, la gloire des justes est abondante; les hommes se perdent dans les lieux qu’habitent les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 13, 'Celui qui cache son impiété ne prospèrera pas; celui qui se la reproche hautement sera aimé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 14, 'Heureux l’homme qui, par piété, respecte toutes choses; les cœurs durs tomberont dans l’infortune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 15, 'Celui qui, pauvre lui-même, gouverne en tyran une nation pauvre est un lion affanié, un loup altéré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 16, 'Roi sans revenus, grand trompeur; celui qui hait l’iniquité vivra longtemps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 17, 'La caution d’un homme accusé de meurtre ressemble à un fugitif, et n’offre point de garantie. Corrige ton fils, et il t’aimera; il fera gloire à ton âme, et il ne se soumettra pas à une nation perverse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 18, 'Celui qui marche selon la justice sera secouru; celui qui s’engage en des voies tortueuses y sera enlacé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 19, 'Qui laboure sa terre, se rassasiera de pain; qui suit la paresse, se rassasiera de misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 20, 'L’homme digne de foi sera comblé de bénédictions; le méchant ne restera pas impuni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 21, 'Celui qui ne respecte point la face des justes, n’est point bon; un tel homme vendra à autrui même une bouchée de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 22, 'L’envieux se hâte de s’enrichir; il ignore que l’homme miséricordieux l’emportera sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 23, 'Qui blâme les voies d’un homme trouvera grâce ensuite auprès de lui, plus que celui qui le flatte de la langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 24, 'Qui repousse avec mépris son père et sa mère, et s’imagine ne point pécher, celui-là est le complice des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 25, 'L’homme sans foi juge au hasard; mais celui qui se confie au Seigneur juge avec grand soin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 26, 'Celui qui se confie en l’audace de son cœur, un tel homme est insensé; mais celui qui marche dans la sagesse sera sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 27, 'Celui qui donne aux pauvres ne manquera jamais; celui qui en détourne son regard tombera dans une extrême indigence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 28, 'Les justes gémissent dans les demeures des impies; mais ils se multiplieront quand ceux-ci seront tombés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 1, 'L’homme qui reprend vaut mieux que l’indocile; car celui-ci tombera soudain dans des maux cuisants et sans remède.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 2, 'Quand les justes sont loués, les peuples sont dans la joie; mais quand les impies gouvernent, les hommes gémissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 3, 'Un homme qui aime la sagesse fait la joie de son père; celui qui nourrit des prostituées dissipe ses richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 4, 'Le roi juste fait prospérer ses États; le méchant les ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 5, 'Celui qui tend un filet à la face de son ami, s’y prendra lui-même les pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 6, 'Le pécheur marche environné de pièges; le juste vit plein de paix et de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 7, 'Le juste sait rendre justice aux pauvres; mais l’impie n’entend pas cette science, et le nécessiteux n’a pas l’esprit assez intelligent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 8, 'Les hommes déréglés mettent en feu une ville; le sage apaise les colères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 9, 'Un homme sage juge les nations; mais un homme méprisable, s’il se met en colère, fait rire et n’effraie personne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 10, 'Les hommes de sang haïssent un saint; les hommes droits recherchent son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 11, 'L’insensé donne cours à toute sa colère; le sage la contient et la mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 12, 'Quand un roi prête l’oreille à l’injustice, tous ses sujets transgressent la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 13, 'L’usurier et l’emprunteur marchent ensemble; le Seigneur les surveille l’un et l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 14, 'Si un roi juge les pauvres selon la vérité, son trône sera affermi pour servir de témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 15, 'Les réprimandes et les corrections donnent la sagesse; l’enfant qui s’en écarte est la honte de ses parents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 16, 'Plus il y a d’impies, plus il y a de péchés; les justes, avertis par leurs chutes, deviennent craintifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 17, 'Corrige ton fils, et il donnera à toi le repos, à ton âme la gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 18, 'Il n’est point de prophète pour une nation perverse; mais bienheureux est celui qui garde la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 19, 'La parole ne suffit pas pour corriger un mauvais serviteur; car même quand il la comprend, il lui est indocile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 20, 'Si tu vois un homme prompt à parler, sache que l’insensé même a plus d’espoir que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 21, 'Celui qui, dès l’enfance, a vécu dans les délices, un jour sera au service d’autrui et pleurera sur lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 22, 'L’homme enclin à la colère excite des discordes; l’homme irascible se creuse un abîme de péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 23, 'L’orgueil abaisse l’homme; le Seigneur est l’appui des humbles, et les élève en gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 24, 'Celui qui prend sa part d’un larcin hait son âme; ceux qui ayant ouï un serment, n’en ont rien, dit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 25, 'Par crainte ou par égard pour des hommes, ont failli. Celui qui met sa confiance dans le Seigneur sera dans la joie; l’impiété cause la chute de l’homme; celui qui a mis sa confiance dans le Maître, sera sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 26, 'Beaucoup se prosternent devant la face du prince; mais c’est le Seigneur qui est le juge des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 27, 'Le juste est en abomination à l’injuste; et celui qui suit la droite voie est en abomination au pervers. 27. Car ils punissent inopinément les impies; et qui peut prévoir quelle sera leur vengeance? Le fils qui garde la loi se sauvera de la perdition; or celui-ci en a reçu l’enseignement. Qu’aucun mensonge ne soit dit par la langue du roi; que nulle fausseté ne sorte de sa langue. La langue du roi n’est point de chair, c’est un glaive; et celui qui lui sera livré, sera brisé; car si sa colère est excitée, elle détruit les hommes avec leurs nerfs; elle dévore leurs os, elle les consume comme la flamme, au point que les aiglons n’y trouveraient pas de quoi se repaître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 49, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 1, 'Ô mon fils, révère mes paroles; recueille-les et repens-toi. Voici ce que dit un homme à ceux qui se confient en Dieu; mais je m’arrête,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 2, 'Car je suis par moi-même le plus insensé des hommes, et la sagesse des mortels n’est point en moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 3, '25. Mais Dieu m’a enseigné la sagesse, et je connais la doctrine des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 4, 'Qui donc est monté au ciel et en est descendu? Qui a rassemblé les vents dans un pli de son manteau? Qui a contenu les eaux comme dans un vêtement? Qui a pouvoir sur les extrémités de la terre? Quel est son nom? Quel est le nom de ses enfants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 5, 'Toutes les paroles de Dieu sont des flammes, et il protège ceux qui le craignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 6, 'N’ajoute rien à ses paroles, de peur qu’il ne te reprenne et ne t’accuse de mensonge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 7, 'Seigneur, je vous demande deux choses: Ne me retirez pas votre grâce avant que je meure;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 8, 'Éloignez de moi les paroles vaines et le mensonge: ne me donnez ni la richesse ni la pauvreté; mais accordez-moi ce qui m’est nécessaire et suffisant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 9, 'De peur que, rassasié, je ne devienne trompeur, et ne dise: Qui me voit? ou que, poussé par le besoin, je ne dérobe, et que je ne parjure le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 10, 'Ne livre pas l’esclave fugitif à son maître; de peur qu’il ne te maudisse, et que tu ne périsses à ton tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 11, 'Une race pervertie maudit son père, et ne bénit pas sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 12, 'Une race pervertie s’estime juste, et qui pourtant n’a point lavé le devant de sa porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 13, 'Une race pervertie a les yeux hautains; l’orgueil est sur ses paupières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 14, 'D’une race pervertie les dents sont des glaives; et ses mâchoires, des couteaux pour détruire et dévorer, sur la terre, les humbles et les pauvres parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 23, 'Voici ce que je dis, à vous sages, pour que vous le sachiez: Il n’est pas bien, en justice, d’avoir égard au rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 24, 'Ceux qui disent de l’impie: C’est un juste, seront maudits du peuple et odieux aux nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 25, 'Mais ceux qui le réprimandent paraîtront meilleurs, et la bénédiction viendra sur eux. 15. La sangsue avait trois filles qu’elle aimait d’un tendre amour; et à elles trois, elles ne remplissaient pas son cœur; une quatrième ne suffit pas pour lui faire dire: C’est assez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 26, 'L’enfer, l’amour d’une femme, une terre qui manque d’eau, l’eau et le feu ne diront jamais: C’est assez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 27, 'L’œil qui se moque d’un père et qui n’honore point la vieillesse d’une mère, que les corbeaux du vallon l’arrachent, et que les aiglons le dévorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 28, 'Il y a trois choses qu’il m’est impossible de comprendre, et une quatrième que j’ignore:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 29, 'La trace d’un aigle dans les airs, celle d’un serpent dans les rochers, les sentiers d’un ruisseau qui vogue sur l’eau, et les voies d’un homme dans sa jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 30, 'Telle est la voie de la femme adultère, qui, après ce qu’elle a fait, se lave, et dit n’avoir rien fait d’inconvenant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 31, 'Trois choses troublent la terre; il en est une quatrième qu’elle ne peut supporter:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 32, 'Un esclave devenu roi; un insensé regorgeant de biens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 33, 'Une servante qui a supplanté sa maîtresse, et une méchante femme réunie à un bon mari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 34, 'Il y a sur la terre quatre êtres bien petits, et ils sont plus sages que les sages:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 35, 'La fourmi, qui n’a point de force, et prépare en été sa nourriture; Le hérisson, peuple débile, qui fait sa demeure dans les rochers; La sauterelle, qui n’a point de roi et marche comme une armée en bon ordre, au commandement d’une seule; 28. Et le lézard moucheté, qui se tient droit, et, quoique facile à prendre, habite les forteresses des rois. }Il y a trois êtres dont la démarche est belle, et un quatrième dont le maintien est majestueux: Le lionceau, le plus fort des animaux, qui ne recule devant rien, et ne redoute aucune bête; Le coq, qui se promène, plein d’ardeur, parmi les poules; et le bouc qui conduit le troupeau, et le roi qui gouverne une nation. Si tu t’es laissé aller à la joie, et que tu étendes les mains pour te disputer, tu seras confondu. Trais le lait avec trop de force, il deviendra du beurre; blesse-toi les narines, il en sortira du sang; cherche querelle, il s’ensuivra des rixes et des procès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 1, 'Ces paroles de moi ont été dites par Dieu; elles sont l’oracle du roi que sa mère a instruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 2, 'Enfant, que garderas-tu? Quoi? la parole de Dieu. Mon fils premier-né, que me reste-t-il à te dire, enfant de mes entrailles, enfant de mes vœux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 3, 'Ne donne point aux femmes ta richesse, ta pensée et ta vie, de peur d’un remords tardif; fais tout avec prudence; bois du vin avec mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 4, 'Les princes sont irascibles; qu’ils ne boivent point de vin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 5, 'De peur qu’en buvant ils n’oublient la sagesse, et ne puissent plus juger les pauvres avec droiture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 6, 'Enivrez les affligés; donnez du vin à boire à ceux qui souffrent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 7, 'Afin qu’ils oublient leur pauvreté, et ne se souviennent plus de leurs peines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 8, 'Ouvre la bouche à la parole de Dieu, et rends justice à tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 9, 'Ouvre la bouche et juge selon l’équité, et plaide la cause du pauvre et du faible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 10, 'Celui qui tend un filet à la face de son ami, s’y prendra lui-même les pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 11, 'Le pécheur marche environné de pièges; le juste vit plein de paix et de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 12, 'Le juste sait rendre justice aux pauvres; mais l’impie n’entend pas cette science, et le nécessiteux n’a pas l’esprit assez intelligent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 13, 'Les hommes déréglés mettent en feu une ville; le sage apaise les colères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 14, 'Un homme sage juge les nations; mais un homme méprisable, s’il se met en colère, fait rire et n’effraie personne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 15, 'Les hommes de sang haïssent un saint; les hommes droits recherchent son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 16, 'L’insensé donne cours à toute sa colère; le sage la contient et la mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 17, 'Quand un roi prête l’oreille à l’injustice, tous ses sujets transgressent la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 18, 'L’usurier et l’emprunteur marchent ensemble; le Seigneur les surveille l’un et l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 19, 'Si un roi juge les pauvres selon la vérité, son trône sera affermi pour servir de témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 20, 'Les réprimandes et les corrections donnent la sagesse; l’enfant qui s’en écarte est la honte de ses parents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 21, 'Plus il y a d’impies, plus il y a de péchés; les justes, avertis par leurs chutes, deviennent craintifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 22, 'Corrige ton fils, et il donnera à toi le repos, à ton âme la gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 23, 'Il n’est point de prophète pour une nation perverse; mais bienheureux est celui qui garde la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 24, 'La parole ne suffit pas pour corriger un mauvais serviteur; car même quand il la comprend, il lui est indocile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 25, 'Si tu vois un homme prompt à parler, sache que l’insensé même a plus d’espoir que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 26, 'Celui qui, dès l’enfance, a vécu dans les délices, un jour sera au service d’autrui et pleurera sur lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 27, 'L’homme enclin à la colère excite des discordes; l’homme irascible se creuse un abîme de péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 28, 'L’orgueil abaisse l’homme; le Seigneur est l’appui des humbles, et les élève en gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 29, 'Celui qui prend sa part d’un larcin hait son âme; ceux qui ayant ouï un serment, n’en ont rien, dit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 30, 'Par crainte ou par égard pour des hommes, ont failli. Celui qui met sa confiance dans le Seigneur sera dans la joie; l’impiété cause la chute de l’homme; celui qui a mis sa confiance dans le Maître, sera sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 31, 'Beaucoup se prosternent devant la face du prince; mais c’est le Seigneur qui est le juge des hommes. Le juste est en abomination à l’injuste; et celui qui suit la droite voie est en abomination au pervers. Une femme forte, qui la trouvera? Une telle femme a plus de prix que les pierres précieuses. Le cœur de son mari a confiance en elle; jamais une telle femme n’aura besoin de recourir aux riches dépouilles d’un ennemi. Car elle emploie toute sa vie au bien de son époux. Elle dévide le lin et la laine, et elle fait de ses mains d’utiles travaux. Elle est comme un navire qui arrive de loin chargé de vivres; Elle se lève avant le jour pour donner sa provende à la maison, et leur tâche à ses servantes. Elle a considéré le champ, et l’a acheté; et, dans cette propriété, elle sème des graines que ses mains ont recueillies. Elle ceint fortement ses reins, et met à l’œuvre toute la force de ses bras. Elle sait par expérience que le travail est bon, et sa lampe ne s’éteint pas de toute la nuit. Elle étend les bras partout où il est utile, et ses mains ne quittent pas le fuseau. Elle a la main ouverte pour le pauvre, et présente un fruit au mendiant. Son mari n’a pas à s’inquiéter des gens de sa maison, quel que soit le lieu où il est retenu; car elle a vêtu tous ceux qui sont auprès d’elle. Elle a fait pour son mari des manteaux doubles, et pour elle-même des manteaux de fin lin et de pourpre. Son mari est considéré devant les portes de la ville, lorsqu’il siège au conseil avec les anciens de la terre. Elle fait des toiles de fin lin; elle vend des ceintures aux Chananéens. Elle ouvre la bouche avec prudence et mesure; elle a mis un frein à sa langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Paroles de l’Ecclésiaste, fils de David, roi d’Israël en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Vanité des vanités, dit l’Ecclésiaste, vanité des vanités, tout est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Que reste-t-il à l’homme de tout le labeur dont il se consume sous le soleil?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Une génération passe, et une génération vient, et la terre demeure toujours immobile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Et le soleil se lève, et le soleil se couche; il se retire en son lieu, et là, se levant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Il chemine vers le midi, puis il tourne au nord; le souffle du vent va tournant, tournant sans cesse, et toujours il recommence ses circuits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Tous les fleuves vont à la mer, et la mer n’en est pas remplie; du lieu où coulent les fleuves, ils reviennent pour couler encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Toutes choses sont laborieuses, nul homme ne pourra les expliquer; et l’œil ne se lassera pas de voir, et l’oreille ne se rassasiera pas d’entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Qu’est-ce que le passé? La même chose que l’avenir; et qu’a-t-on fait? ce que l’on fera toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Il n’y a rien de nouveau sous le soleil; qui pourra dire: Voyez, ceci est nouveau? Mais cette chose a déjà été dans les siècles qui ont passé avant nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Mais on a perdu la mémoire des premiers, et ceux de la fin n’auront point mémoire de ceux qui naîtront d’ici à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 12, 'Moi, l’Ecclésiaste, j’ai régné sur Israël en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 13, 'Et j’ai appliqué mon cœur à chercher et à observer avec sagesse tout ce qui existe sous le ciel; car Dieu a donné aux fils des hommes cette mauvaise inquiétude, pour qu’ils s’inquiètent en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 14, 'J’ai vu toutes les œuvres qui ont été faites sous le soleil, et voilà que toutes étaient vanité et présomption d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 15, 'On ne peut embellir les pervers; leurs abaissements sont innombrables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 16, 'Pour moi, j’ai dit en mon cœur: Voilà que je suis devenu grand, et que j’ai acquis plus de sagesse qu’aucun de ceux qui, avant moi, ont été en Jérusalem; j’ai appliqué mon cœur à connaître la sagesse et la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 17, 'Et mon cœur a beaucoup vu: sagesse, science, paraboles, interprétation; et j’ai connu que cela même était présomption d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 18, 'Car dans une grande sagesse est une grande science; et qui accroît sa science, accroît son affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'J’ai dit en mon cœur: Viens, et je te tenterai par la joie; vois, c’est ici le bonheur, et voilà que cela aussi est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'J’ai dit au rire: Tu es un égarement; et à la joie: Que fais-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Et j’ai examiné si mon cœur enivrerait ma chair comme du vin; et mon cœur m’a conduit à la sagesse et au désir de posséder le bonheur, jusqu’à ce que j’aie découvert ce qu’il est bon que fassent les hommes, sous le soleil, durant les jours de leur vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'J’ai grandi mon œuvre; je me suis bâti des palais; j’ai planté des vignes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Je me suis fait des vergers et des jardins, et j’y ai planté toute une forêt d’arbres fruitiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'J’ai creusé des réservoirs d’eau, pour arroser les jeunes plants de ma forêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'J’ai acheté des esclaves et des servantes, et il m’en est né dans mes demeures; et j’ai eu en outre plus de bœufs et de menus troupeaux qu’aucun de ceux qui, avant moi, ont été en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'J’ai amassé aussi de l’argent et de l’or, et les trésors des rois et des empires. J’ai eu des chanteurs et des chanteuses; j’ai eu toutes les délices des fils des hommes; j’ai eu des échansons et des femmes pour remplir ma coupe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Et je suis devenu grand, et j’ai possédé plus qu’aucun de ceux qui, avant moi, ont été en Jérusalem, et ma sagesse est demeurée avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Et je n’ai refusé à mes yeux rien de ce qu’ils ont demandé; je n’ai point empêché mon cœur de prendre part à tous mes plaisirs; car mon cœur s’est réjoui en tous mes travaux, et cela même a été le fruit de tous mes labeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Et j’ai considéré toutes mes œuvres, tout ce qu’avaient fait mes mains, et la fatigue que j’avais éprouvée en mes travaux; et voilà que tout cela est vanité et présomption d’esprit: ainsi il n’est rien d’excellent sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Et j’ai tourné mes regards vers la sagesse, et l’égarement, et la folie; car quel est l’homme qui suivra le bon chemin, même après s’être consulté?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Et j’ai vu que la sagesse l’emporte sur la folie autant que la lumière sur les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Les yeux du sage sont à sa tête; l’insensé marche dans les ténèbres; et j’ai connu qu’une même fin adviendra à tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Et j’ai dit en mon cœur: La même fin adviendra à l’insensé et à moi-même; pourquoi donc ai-je acquis la sagesse? J’ai donc, en outre, dit en mon cœur: Cela aussi est vanité, puisque l’insensé parle aussi d’abondance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Car dans les siècles on oubliera le sage, puisque les jours se succèdent, emportant le souvenir de toutes choses. Et pourquoi le sage meurt-il comme l’insensé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Alors j’ai pris en haine la vie, parce que, me suis-je dit le travail que j’ai fait sous le soleil est mauvais, et que tout est vanité et présomption d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Et j’ai pris en haine toute la peine que je m’étais donnée, sous le soleil, parce que j’en laisserai le fruit à un homme qui viendra après moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Et qui sait s’il sera insensé ou sage, et s’il aura pouvoir sur les travaux où j’ai eu fatigue et sagesse sous le soleil? Et cela encore est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Et j’ai fait un retour sur moi-même, pour considérer en mon cœur toute la peine des travaux que j’ai faits sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Car il est un homme, et à ses labeurs il a mis toute sa sagesse, sa science et son courage; et cet homme en laissera le fruit à qui n’en a pas eu la fatigue; et cela encore est vanité et grande affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Car c’est là ce qui arrive à l’homme en tous ses travaux et en tous les choix de son cœur, pour lesquels il s’est fatigué sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Tous ses jours sont des jours de douleurs et d’angoisses de l’âme, et, même pendant la nuit, son cœur ne repose pas; et cela encore est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'L’homme n’a rien de bon que le manger et le boire, et tout ce qui est le fruit de son labeur; mais j’ai vu, moi, que cela vient de la main de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Car qui mange et qui boit sans qu’il l’ait permis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 26, 'Il a donné à l’homme bon à ses yeux la sagesse, la science et la joie, et il a donné au pécheur l’embarras d’amasser, d’accumuler, pour laisser à celui qui est bon devant Dieu. Et cela est aussi vanité et présomption d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Il y a temps pour tout, et toute chose sous le ciel a son moment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Il y a temps pour naître et pour mourir; temps pour planter et pour arracher ce qui a été planté;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Temps pour tuer et pour guérir; temps pour abattre et pour édifier;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Temps pour pleurer et pour rire; temps pour gémir et pour danser;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Temps pour rejeter les pierres et pour les amasser; temps pour embrasser et pour s’éloigner des embrassements;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 6, 'Temps pour acquérir et pour perdre; temps pour conserver et pour rejeter;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 7, 'Temps pour déchirer et pour recoudre; temps pour se taire et pour parler;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 8, 'Temps pour aimer et pour haïr; temps pour combattre et pour faire la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 9, 'Quel avantage a celui qui se fatigue aux choses qu’il fait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 10, 'J’ai vu d’un seul coup d’œil toute l’inquiétude que Dieu a donnée aux fils des hommes, pour qu’ils s’inquiètent en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 11, 'Toutes les choses qu’il a faites sont bonnes en leur temps, et il a mis le monde entier dans le cœur des hommes, en sorte que du commencement à la fin ils ne puissent s’expliquer l’œuvre que Dieu a créée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 12, 'J’ai connu qu’il n’est rien de bon en eux-mêmes, si ce n’est de se réjouir et de faire le bien pendant leur vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 13, 'Et si un homme mange, boit, et voit le bien dans son labeur, c’est là un don de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 14, 'J’ai connu que tout ce qu’a fait Dieu subsistera durant tous les siècles; nous ne pouvons y rien ajouter, en rien ôter. Et Dieu a fait cela pour que les hommes craignissent son visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 15, 'Ce qui a été est encore; et tout ce qui doit être a été, et Dieu cherchera le persécuté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 16, 'Et j’ai vu encore, sous le soleil, le lieu du jugement, où est l’impie, et le lieu de l’équité, où est l’homme pieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 17, 'Et j’ai dit en mon cœur: Dieu jugera ensemble le juste et l’impie; car il y a temps pour toute chose et pour toute œuvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 18, 'J’ai dit en mon cœur, touchant les discours des hommes: Dieu les discernera, et il leur montrera qu’ils sont un bétail à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 19, 'Car le fils des hommes et la bête sont sujets aux mêmes accidents; la mort de celui-ci est la mort de celuilà, et le même souffle les anime tous: et qu’a l’homme de plus que la bête? rien; car tout est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 20, 'Toutes choses vont au même lieu; tout est sorti de la poussière, et tout retournera en poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 21, 'Et qui a vu si le souffle des fils des hommes remonte en haut, ou si le souffle des bêtes descend en bas dans la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 22, 'Et j’ai vu qu’il n’est rien de bon pour l’homme, sinon de se complaire en ses œuvres; car tel est son partage. Car qui le conduira à connaître quelque chose de ce qui sera après lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Et je me suis retourné d’un autre côté, et j’ai vu toutes les oppressions qui se font sous le soleil. Et voilà les larmes de ceux qu’on a opprimés, et nul ne les console; et voilà la force des mains de ceux qui oppriment, et nul ne les console.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Et j’ai félicité tous les morts, tous les trépassés plus que les vivants, quels que soient ceux qui maintenant existent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Plus heureux que les vivants et les morts, celui qui n’a jamais été; il n’a pas vu toute l’œuvre mauvaise qui se fait sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Et j’ai vu tout labeur et toute industrie à l’œuvre; et j’ai vu que cette ardeur provient de l’envie que l’homme porte à son semblable. Et cela encore est vanité et présomption d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'L’insensé se croise les bras, et mange sa propre chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mieux vaut une main pleine avec le repos, que les deux mains pleines avec labeur et peine d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Et je me suis retourné, et j’ai vu une autre vanité sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'C’est un homme seul, et qui n’en a pas un second avec lui; et quoiqu’il n’ait ni fils ni frère, son travail est sans fin, et son œil n’est pas rassasié de richesse`: et pour qui mon labeur, et pour qui privé-je mon âme de tout bien? Or cela encore est vanité et mauvaise inquiétude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Deux valent mieux qu’un, et ils reçoivent de leur commun labeur un salaire abondant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Car, s’ils tombent, l’un relève son compagnon; malheur à l’homme seul, s’il tombe, il n’a personne pour le relever!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Et si deux dorment ensemble, la chaleur est avec eux; et comment un seul se réchauffera-t-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Et si un seul prévaut, les deux lui résisteront; et une triple corde ne sera pas promptement brisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Mieux vaut un enfant pauvre et sage, qu’un roi vieux et insensé qui ne sait rien prévoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Car tel sortira de la prison pour régner, et tel autre qui était roi est devenu indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'J’ai vu tous les vivants, qui cheminent sur la terre, se mettre à la suite du jeune prince qui doit remplacer ce roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Le nombre est infini de tout le peuple, de tous ceux qui ont été avant eux. Et les derniers venus ne se réjouiront pas en ce jeune homme; car cela est encore vanité et affliction d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Prends garde où tu mets le pied dans le temple du Seigneur, et approche pour écouter; ton offrande sera plus agréable que les dons des insensés, car ils ignoreront qu’ils font le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Ne te hâte point d’ouvrir la bouche; que ton cœur ne soit pas pressé de proférer des paroles en présence de Dieu. Car Dieu est au plus haut du ciel, et toi tu es sur la terre; c’est pourquoi parle sobrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Car le songe naît d’un excès d’inquiétude, et la voix de l’insensé naît de l’intempérance de sa langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Lorsque tu auras fait un vœu au Seigneur, ne tarde pas à t’en acquitter; car le bon vouloir n’est pas dans les insensés. Rends donc à Dieu tout ce que tu lui auras voué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Mieux vaut n’avoir point fait de vœu, que d’en faire et ne point l’accomplir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Ne permets pas à ta bouche de faire pécher ta chair; ne dis pas devant Dieu que tu ne savais pas, de peur que Dieu ne s’irrite de tes paroles, et qu’il ne détruise les œuvres de tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Tout cela encore est abondance de songes, de vanités et de paroles; pour toi, crains Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Si tu vois en une contrée le pauvre trompé, le jugement et la justice rendus par violence, n’en sois point surpris; car c’est un grand qui surveille un grand, et il y a plus grands encore au-dessus d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'L’abondance de la terre est pour tous, quand, sous un roi les champs sont cultivés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Celui qui aime l’argent ne sera pas rassasié par l’argent; et celui qui aime le profit, le sera-t-il dans l’abondance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Quand s’accroît la richesse, il y a plus de gens');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Le dormir est doux au serviteur, qu’il ait mangé peu ou beaucoup; quant à celui qui regorge de richesses, rien ne le laisse sommeiller.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Il est une maladie que j’ai vue sous le soleil: c’est la richesse gardée par celui qui la garde à son détriment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Ses richesses périront au milieu de cruelles inquiétudes; il a un fils, et il ne lui laissera rien dans la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Nu il est sorti du sein de sa mère; comme il est venu il s’en ira, sans rien recueillir de son labeur, pour l’emporter dans sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Et cela encore est une maladie mauvaise; car comme il est venu il s’en ira de même; et quel est donc ce profit pour lequel il a travaillé en l’air?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 16, 'Et ainsi il a passé tous ses jours dans les ténèbres, dans la tristesse, dans la colère, dans la maladie et dans la haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 17, 'Voilà ce que j’ai vu de bien: c’est que l’homme mange et boive, et qu’il voie prospérer tout son labeur pour lequel il aura travaillé sous le soleil, tous les jours de sa vie que Dieu lui a donnés; car tel est son partage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 18, 'Or tout homme à qui Dieu a donné richesse, possession, pouvoir de manger ses biens, de jouir de sa part, de se complaire en son labeur, a reçu un don de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 19, 'Car celui-là ne se souviendra guère de la succession des jours de sa vie; Dieu l’en a distrait par la joie de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Il est un autre mal que j’ai vu sous le soleil, et il est fréquent dans l’homme:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'C’est un homme à qui Dieu aura donné richesses, possessions, honneurs, dont l’âme n’aura jamais eu un désir qui n’ait été satisfait; mais à qui Dieu n’aura pas donné le pouvoir de manger de ses biens; car un étranger le dévorera. C’est là une vanité et une malheureuse affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Et si un homme a eu cent enfants, s’il a vécu beaucoup d’années; quelle qu’ait été la multitude de ses jours, si son âme n’a pas été remplie de ses biens, s’il n’a point de sépulcre, je dis: Un fœtus avorté vaut mieux que lui;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Car c’est en vain qu’un fœtus est venu au monde; il s’en va dans l’obscurité, et son nom sera caché dans les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Il n’a pas même vu le soleil ni connu le repos, non plus que l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Et eût-il vécu mille ans, qu’il n’aurait pas vu la prospérité; toutes choses ne vont-elles pas au même lieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Tout le labeur de l’homme est pour sa bouche, et encore son âme n’en sera pas rassasiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Le sage l’emporte sur l’insensé, parce que le pauvre sait marcher en face de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'La vision des yeux est bonne; mais cela aussi est vanité et présomption d’esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Si quelque chose a été, aussitôt un nom lui a été donné; on sait ce qu’est un homme, et qu’il ne pourra entrer en jugement avec un plus puissant que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Car il est maintes choses qui multiplient la vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Quel avantage a l’homme? Qui sait ce qui est bon à l’homme en sa vie, durant le nombre des jours de sa vanité, qu’il a passés dans l’ombre? Qui fera connaître à l’homme ce qui sera après lui sous le soleil?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Bon renom vaut mieux que bon parfum; le jour de la mort vaut mieux que le jour de la naissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Il vaut mieux aller à la maison du deuil qu’à la maison du festin, puisque le deuil est la fin de tout homme, et que le vivant donnera ainsi de bons avertissements à son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'La tristesse vaut mieux que le rire; parce que, par la tristesse du visage, le cœur deviendra bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Le cœur des sages est à la maison des pleurs; le cœur des insensés est à la maison d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Mieux vaut écouter la réprimande d’un sage, que d’entendre le chant des insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Le rire des insensés est comme le petillement des épines sous une chaudière; et cela encore est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'La calomnie trouble le sage, et lui fait perdre sa force d’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'La fin du discours vaut mieux que le commencement; un homme patient vaut mieux qu’un esprit présomptueux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Ne t’abandonne pas trop vite au souffle de la colère; car la colère réside dans le sein des insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Garde-toi de dire: Comment se fait-il que les jours d’autrefois ont été meilleurs que ceux d’à présent? Car il n’est point sage de s’enquérir de ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'La sagesse est bonne, unie aux richesses; elle est alors profitable à ceux qui vivent sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Car on s’abrite à l’ombre de la sagesse, comme à l’ombre de l’argent; mais l’avantage de la science et de la sagesse, c’est qu’elles font vivre celui qui les possède.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Considère les œuvres de Dieu; car qui pourrait redresser celui que Dieu a courbé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Au jour de la prospérité vis dans le bien-être, et prévois le jour du malheur; prévois - le: car Dieu a fait telle chose concordant avec telle autre, à cause des propos des hommes, afin qu’ils ne trouvent rien à blâmer en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'J’ai vu toutes choses au jour de ma vanité. Le juste meurt avec sa justice; l’impie subsiste avec sa perversité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 17, 'Ne sois pas juste à l’excès; ne sois point sage plus qu’il ne faut, de peur que tu ne sois confondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 18, 'Mais ne sois pas non plus impie ni obstiné à l’excès, de peur que tu ne périsses avant le temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 19, 'Il est bon que tu t’attaches à telle chose, et que tu t’éloignes de telle autre, pour ne point souiller tes mains; car tout vient à ceux qui craignent Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 20, 'La sagesse sera utile au sage plus que dix des plus puissants de la cité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 21, 'Car il n’est point sur la terre de juste qui fasse le bien, et ne pèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 22, 'Mais ne dépose pas en ton cœur toutes les paroles que diront les impies, de peur que tu n’entendes ton serviteur te maudire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 23, 'Car maintes fois il t’irritera, et il t’affligera de bien des manières; car toi-même aussi tu as maudit les autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 24, 'J’ai éprouvé toutes choses en ma sagesse, et j’ai dit: Je serai sage; et la sagesse s’est éloignée de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 25, 'Elle était plus loin encore qu’auparavant; l’abîme entre nous était profond: qui le sondera?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 26, 'Pour moi, j’ai tourné autour de toutes choses, et j’ai appliqué mon esprit à les apprendre, à les examiner avec soin, à chercher la sagesse et la raison des choses, à connaître la démence de l’impie, et ses agitations et son inquiétude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 27, 'Et j’ai trouvé cette démence, et je la dis plus amère que la mort; de même est la femme que le veneur poursuit comme une proie, tandis que son cœur est un filet, et qu’elle tient des chaînes en sa main. L’homme bon en face du Seigneur fuira loin d’elle, et le pécheur y sera pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 28, 'Voilà ce que j’ai trouvé, dit l’Ecclésiaste, en prenant les choses une à une, pour en découvrir la raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 29, 'Mon âme l’a cherchée cette raison, et je ne l’ai point trouvée, et j’ai trouvé un homme sur mille; mais parmi toutes les femmes, je n’en ai pas trouvé une seule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 30, 'Seulement voici ce que j’ai trouvé: Dieu a créé l’homme droit, et les hommes ont cherché une multitude de raisons; mais qui connaît les raisons véritables? Qui sait la solution des choses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'La sagesse de l’homme se reflète sur son visage; le front de l’impudent inspire la haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Observe le commandement du roi, et cela, à cause de la parole que Dieu a jurée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Ne te hâte pas de t’éloigner de sa face; ne tiens pas à la parole si elle est coupable: car il fera tout ce qu’il voudra;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Comme fait un roi puissant; et qui pourra lui dire: Qu’as-tu fait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Celui qui observe les commandements ne connaîtra pas le mal, et le cœur du sage sait le temps du jugement de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Car pour toutes choses il y a temps et jugement, et l’homme en sait beaucoup sur lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Mais nul ne sait ce qui doit arriver que sera-ce? qui le lui fera connaître?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Il n’est point d’homme qui ait pouvoir sur la vie, qui puisse la retenir; il n’a pas plus de pouvoir sur le jour de la mort; et il n’est point pour lui de trêve au jour de la bataille, et l’impiété ne sauvera pas ceux qui l’aiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Et j’ai vu toutes ces choses, et j’ai appliqué mon cœur à toute œuvre qui se fait sous le soleil; et j’ai vu les choses où l’homme a pris pouvoir sur l’homme, pour l’affliger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Et j’ai vu des impies conduits à la sépulture, au sortir du lieu saint, et ils étaient allés dans leur voie, et ils avaient été loués dans la ville, parce qu’ils avaient ainsi fait; et cela encore est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Car, parce que ceux qui font mal ne sont point repris incontinent, le cœur des fils des hommes s’enhardit par leur exemple à mal faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Celui qui une fois a péché, a fait le mal depuis lors, et longtemps. Et moi je sais que Dieu est bon pour ceux qui craignent en sa présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Mais le bonheur ne sera pas pour l’impie, et il n’aura pas de longs jours; ils passeront comme l’ombre, parce qu’il ne craint pas la face de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Voici encore une vanité qui existe sur la terre: il est des justes à qui il arrive comme à l’œuvre des impies; il est des impies à qui il arrive comme à l’œuvre des justes. Et cela, ai-je dit, est encore vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 15, 'Et c’est pourquoi (dit l’impie) j’ai loué toutes les joies; car il n’est rien de meilleur pour l’homme sous le soleil, sinon de manger, de boire et de se réjouir. Et cela seul lui restera de tout le labeur qu’il fait durant les jours de la vie que Dieu lui a donnée sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 16, 'Dans ces pensées, j’ai appliqué mon cœur à connaître la sagesse, et à voir l’inquiétude qui naît sur la terre; car la nuit comme le jour, il n’est personne qui de ses yeux voie le sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 17, 'Et j’ai vu toutes les œuvres de Dieu, et j’ai vu que l’homme ne pourra jamais s’expliquer l’œuvre qui se fait sous le soleil. Quelque fatigue qu’il se donne pour chercher, il ne la trouvera pas, et, quelque science même que le sage croie avoir, il ne pourra la trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'C’est pourquoi j’ai déposé toutes ces choses en mon cœur, et mon cœur a vu toutes ces choses; il a vu que les justes et les sages et leurs œuvres sont dans la main de Dieu, et l’homme ne sait s’il est digne d’amour ou de haine; tout ce qu’ils ont devant eux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Est vanité en tous; mêmes choses adviennent au juste et à l’impie, au bon et au méchant, au pur et à l’impur, à celui qui sacrifie et à celui qui ne sacrifie pas. Il en est du bon comme du pécheur, du parjure comme de l’homme qui respecte son serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Et c’est le pire de tout ce qui a été créé sous le soleil, que les mêmes choses adviennent à tous; aussi le cœur des fils des hommes est-il plein de malice, et la mobilité de leur âme dure toute leur vie; et après cela ils s’en vont chez les morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Car quel homme peut vivre avec tous les vivants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Les vivants savent qu’ils mourront, les morts ne savent rien; et il n’est plus pour eux de récompense, et leur mémoire est en oubli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Et leur amour, et leur haine, et leur jalousie ont péri; et, durant les siècles des siècles, ils n’auront plus rien en partage de ce qui a été créé sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Courage donc; mange avec joie ton pain, bois de bon cœur ton vin, car tes œuvres sont agréables à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'En tout temps porte des vêtements blancs, et ne manque pas de te parfumer la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Et passe ta vie avec la femme que tu as aimée tous les jours de ta vie passagère, qui t’ont été donnés sous le soleil; car c’est là ton partage en ta vie, et le prix du labeur que tu as gagné sous le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Tout ce que ta main aura trouvé à faire, fais - le selon tes forces; car il n’y a ni œuvres, ni raison, ni savoir, ni sagesse dans le tombeau où tu cours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Et je me suis tourné d’un autre côté, et j’ai vu sous le soleil que la course n’est pas pour les agiles, ni la guerre pour les braves, ni la paix pour le sage, ni la richesse pour l’intelligent, ni la faveur pour le savant; car l’occasion et la chance est pour tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'L’homme ne connaît pas plus sa fin que le poisson retenu dans le filet perfide ou l’oiseau pris au piége; comme eux, les enfants des hommes sont surpris par l’adversité, lorsque soudain elle tombe sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'J’ai vu encore ceci: j’ai vu la sagesse sous le soleil, et grande elle est à mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Il était une ville petite, et dans ses murs il y avait peu d’hommes; et un grand roi marcha contre elle, et il l’investit, et il éleva tout alentour de hautes palissades.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Et il se trouva, en cette ville, un homme pauvre et sage, et il la sauva par sa sagesse, et nul ne se souvint de cet homme pauvre et sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Et je me suis dit: La sagesse prévaut sur la force, et la sagesse du pauvre est méprisée; ses discours ne sont point écoutés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mieux est écoutée la parole du sage, dans le calme, que la clameur des princes dans leur folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 18, 'Mieux vaut la sagesse que des armes de guerre; une seule faute peut ruiner une grande prospérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Des mouches mortes gâtent une fiole d’huile parfumée; mieux vaut un peu de sagesse qu’une grande gloire avec de la folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Le cœur du sage est dans sa main droite; le cœur de l’impie est dans sa main gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Même quand l’insensé chemine dans sa voie, le cœur lui manque, et tout ce qu’il pense n’est que folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Si le courroux de celui qui a le pouvoir s’élève contre toi, ne quitte point ta demeure; car le silence sera le meilleur remède à tes offenses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Il est encore un mal que j’ai vu sous le soleil, sortant comme involontairement de la face de celui qui a le pouvoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'L’insensé a été promu aux grandeurs, et les riches seront assis au dernier rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'J’ai vu des serviteurs à cheval, et des princes marcher à pied comme des esclaves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Celui qui creuse une fosse y tombera, et celui qui détruit une haie, un serpent le mordra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Celui qui ramasse des pierres s’y blessera lui-même, et celui qui fend du bois se met en péril.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Si son fer lui échappe, il en a le visage troublé; cependant il rassemble ses forces, mais alors sa sagesse ne profite pas à cet homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Un charmeur ne tire pas grand profit de son art, si un serpent le mord sans siffler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'La grâce découle de la bouche du sage, et les lèvres de l’insensé le font trébucher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Il commence par les folies de sa langue; il finit par les méchancetés de ses lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Car l’insensé multiplie les paroles. L’homme ne sait ni le passé ni l’avenir; et ce qui viendra après lui, qui le lui prédira?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Le travail des insensés leur sera funeste, comme celui de l’homme qui ne sait pas le chemin pour aller à la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 16, 'Malheur à toi, ville dont le roi est jeune, et où les princes sont à table dès le matin!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 17, 'Heureuse es-tu, terre dont le roi sera fils d’hommes généreux, et où les princes mangeront au temps opportun, pour soutenir leurs forces, et n’auront pas à rougir de leurs excès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 18, 'Le plancher du paresseux s’affaissera, et, à cause de l’inertie de ses mains, dans sa maison tombera la pluie goutte à goutte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 19, 'On leur prépare du pain pour les réjouir, du vin et de l’huile pour égayer leur vie; et ainsi tout obéit à leur argent, mais pour leur honte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 20, 'Toutefois, même dans le secret de la conscience, ne maudis point le roi; dans ta chambre à coucher, ne maudis point le riche, car quelque oiseau du ciel rapporterait tes paroles, quelque insecte ailé publierait tes discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Laisse aller ton pain au cours de l’eau; car après bien des jours tu le retrouveras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Distribues-en à sept, même à huit personnes; car tu ignores ce qu’il doit y avoir de maux sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Lorsque les nuées sont pleines, elles fondent en pluie sur la terre; et si un arbre tombe au midi ou au nord, il restera là où il sera tombé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Celui qui observe le vent ne sèmera pas; et celui qui regarde aux nuages ne moissonnera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Car nul ne sait quelle est la voie du vent; comme les os cachés dans les entrailles de la femme grosse, de même te sont cachées les œuvres que Dieu a faites et toutes celles qu’il fera encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Sème ton grain dès l’aurore, et que ta main ne s’arrête pas le soir; car tu ignores de celui-ci ou de celuilà lequel doit lever; s’ils lèvent tous deux à la fois, c’est bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'La lumière est douce, et il est bon aux yeux de voir le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'L’homme qui doit vivre beaucoup d’années trouvera en toutes de la joie, et il se souviendra des jours de ténèbres, car ils seront nombreux: tout ce qui est passé est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Jeune homme, réjouis-toi en ta jeunesse; que, durant les jours de ta jeunesse, ton cœur te réjouisse; marche avec innocence dans les voies de ton cœur, et non selon ce que tes yeux auront vu. Mais sache pardessus tout que le Seigneur t’appellera devant sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Éloigne de ton cœur la colère, et bannis de ta chair la méchanceté; car la jeunesse et la folie sont vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Et, durant les jours de ta jeunesse, souviens-toi de Celui qui t’a créé; avant que les jours de l’adversité soient venus, avant que tu sois surpris par les années, où tu diras Je n’ai point en elles de plaisir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Avant que le soleil et la lumière s’obscurcissent, et la terre et les étoiles; avant que les nuées succèdent à la pluie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Comme il arrivera le jour où les gardiens de la maison trembleront; où les hommes les plus forts plieront le dos; où les esclaves attachés à la meule s’arrêteront faute de force; où celles qui regarderont par la fenêtre ne verront que ténèbres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Quand les portes de la bouche se fermeront, parce que la voix de celle qui avait accoutumé de moudre sera affaiblie; qu’on se lèvera au chant du passereau, et que les filles de l’harmonie ne pourront l’entendre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Où on lèvera les yeux, et où on aura des terreurs dans le chemin; où l’amandier sera en fleur; où les sauterelles se multiplieront; où le câprier tombera en poussière, parce que l’homme sera en marche pour sa demeure éternelle, et que sur la place publique iront çà et là des gens en pleurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Avant que la chaîne d’argent soit brisée, que la bandelette d’or soit rompue, que l’urne se brise à la fontaine, et que la roue de la citerne se déroule;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Avant que la poussière revienne sur la terre, comme elle était, et que l’esprit retourne à Dieu, qui l’a donné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Vanité des vanités, a dit l’Ecclésiaste, tout est vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Et de plus, comme l’Ecclésiaste était très-sage, il enseigna la science à l’homme; et l’oreille découvrira le sens voilé des paraboles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'L’Ecclésiaste a cherché avec soin pour trouver des paroles de bonne volonté, des écrits de justice, des paroles de vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Les paroles du sage sont comme des aiguillons, comme des clous qu’on a solidement fixés; elles ont été données dans les conseils des sages par l’unique pasteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Et il est profitable, ô mon fils, de les garder; à faire beaucoup de livres, il n’y a point de fin; et trop d’étude est fatigue de la chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Écoute la conclusion, le résumé de ce discours; crains Dieu, et garde ses commandements, car c’est là tout l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'En effet, Dieu appellera en jugement chaque œuvre, chaque chose qui aura été négligée, bonne ou mauvaise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Cantique des cantiques, qui est de Salomon. Qu’il me baise des baisers de sa bouche; car tes mamelles sont meilleures que le vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Et la senteur de tes parfums l’emporte sur tous les aromates; ton nom est l’essence de parfum: voilà pourquoi les jeunes filles t’aiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Elles t’attirent, et à ta suite nous courons aux senteurs de tes parfums. Le roi m’a introduite dans sa chambre secrète; nous tressaillirons, nous nous réjouirons en toi; nous aimerons tes mamelles plus que le vin; la droiture te chérit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Filles de Jérusalem, je suis noire, et je suis belle, comme les tentes de Cédar, comme les tentures de Salomon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Ne me dédaignez pas, parce que je suis noire; c’est que le soleil a altéré ma couleur. Les fils de ma mère se sont levés contre moi; ils m’avaient fait la gardienne des vignes, et ma propre vigne, je ne l’ai point gardée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'O toi que mon âme a aimé, indique-moi où tu pais ton troupeau, où tu reposes à midi, de peur que peut-être je ne m’égare à la suite des troupeaux de tes compagnons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'O toi, la plus belle des femmes, si tu ne te connais toi-même, suis les traces de mes troupeaux, et pais tes chevreaux près des tentes de mes pasteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Ma bien-aimée, je t’ai comparée à mes cavales attelées aux chars de Pharaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Tes joues, elles sont belles comme la colombe, et ton cou, comme un collier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Nous te ferons des ornements d’or émaillés d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Aussi longtemps que le roi a été à table, mon nard a répandu son parfum.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Mon frère bien-aimé est pour moi un bouquet de myrrhe; il reposera entre mes mamelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Mon frère bien-aimé est pour moi une grappe en fleur dans la vigne d’Engaddi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Que tu es belle, ô ma bien-aimée, que tu es belle! Tes yeux sont ceux d’une colombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Et toi, que tu es beau, mon frère bien-aimé! que tu es charmant à l’ombre de notre couche!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Les solives de vos demeures sont de cèdre, et ses lambris de cyprès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Je suis la fleur des champs et le lis des vallées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Comme le lis des vallées au milieu des épines, est ainsi ma bien-aimée au milieu des jeunes filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Comme le pommier parmi les arbres de la forêt, ainsi est mon frère bien-aimé parmi les jeunes hommes. J’ai désiré son ombre, et je m’y suis assise, et son fruit est doux à mon palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Introduisez-moi dans le cellier au vin; faites-y venir ma bien-aimée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Soutenez-moi avec des parfums; entourez-moi de fruits, car je suis blessée d’amour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Sa main gauche sera sous ma tête, et de sa droite il m’embrassera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Filles de Jérusalem, je vous adjure, par les puissances et les vertus de la campagne, n’éveillez pas, ne réveillez pas ma bien-aimée, qu’elle-même ne le désire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'C’est la voix de mon bien-aimé; le voilà qui vient en bondissant sur les monts, en franchissant les collines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Mon frère bien-aimé ressemble au chevreuil ou au jeune faon sur les montagnes de Béthel. Le voilà derrière notre mur; il se penche par la fenêtre, il regarde à travers le treillis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Mon frère bien-aimé me parle, et me dit: Lève-toi, ma bien-aimée; viens, ô ma belle, ô ma colombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Car voilà que l’hiver est passé; la pluie s’en est allée, elle est partie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Les fleurs se montrent sur la terre; le temps de tailler est venu; le roucoulement de la tourterelle s’entend sur notre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Les jeunes figues montrent leurs bourgeons; les vignes sont en fleur et donnent leur parfum. Lève-toi, ma bien-aimée; viens, ô ma belle, ô ma colombe. Viens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Toi ma colombe, à l’abri sous les roches, dans le creux des murs. Montre-moi ton visage, que j’entende ta voix; car ta voix est douce, et ton visage est plein de grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Prenez les jeunes renards, qui ravagent les vignes, quand nos vignes sont en fleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Mon frère bien-aimé est à moi, et moi à lui; et il fait paître son troupeau parmi les lis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Jusqu’à ce que se lèvent les premières brises du jour et que les ténèbres se dissipent. Reviens, mon frère bien-aimé; accours comme le chevreuil ou le jeune faon sur les ravins des montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Sur ma couche, la nuit, j’ai désiré celui qu’aime mon âme; je l’ai cherché, et ne l’ai point trouvé; je l’ai appelé, et il ne m’a pas écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Je me lèverai donc; j’irai par la ville, les marchés, les places, et je chercherai celui qu’aime mon âme. Je l’ai cherché, et ne l’ai point trouvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Les gardiens m’ont rencontrée, en faisant la ronde dans la ville N’avez-vous pas vu celui qu’aime mon âme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'A peine éloignée d’eux, j’ai trouvé celui qu’aime mon âme; je l’ai pris par la main, et ne l’ai point quitté que je ne l’eusse introduit dans la maison de ma mère, dans la chambre de celle qui m’a conçue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Filles de Jérusalem, je vous adjure par les puissances et les vertus des campagnes, n’éveillez pas, ne réveillez pas ma bien-aimée, qu’elle ne le désire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'Qui est celle qui monte du désert, comme une colonne de fumée sortant de l’encens et de la myrrhe, et de toutes les poudres dont se composent les parfums?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Voilà la couche de Salomon; soixante vaillants des forts d’Israël sont rangés en cercle autour d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Tous exercés aux combats, ils ont l’épée au côté, pour en écarter les terreurs de la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Le roi Salomon s’est fait un lit de cèdres du Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Les montants en sont d’argent, et le siège d’or; le marchepied est de porphyre, et l’intérieur est pavé de pierres précieuses, amour des filles de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Filles de Sion, sortez, contemplez le roi Salomon avec la couronne que lui a posée sa mère le jour de son mariage, le jour de la joie de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, 'Que tu es belle, ô ma bien-aimée! que tu es belle! Tes yeux sont ceux des colombes, sans parler de tes beautés cachées. Ta chevelure est comme la toison des troupeaux de chèvres qu’on voit en Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'Tes dents sont comme la laine des brebis sortant du lavoir après la tonte; toutes ont deux petits, et nulle n’est stérile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'Tes lèvres sont comme un ruban écarlate, et ton langage est plein de grâce; tes joues sont comme la peau de la grenade, sans parler de tes beautés cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Ton cou est comme la tour de David, qu’il a bâtie pour être un arsenal; mille boucliers y sont suspendus, et tous les dards des vaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'Tes deux mamelles sont comme deux faons jumeaux du chevreuil, paissant parmi les lis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'Jusqu’à ce que se lèvent les premières brises du jour, et que les ténèbres se dissipent. J’irai à la montagne de myrrhe et à la colline d’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, 'Tu es toute belle, ô ma bien-aimée; et il n’est point de tache en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'Viens du Liban, mon épouse, viens du Liban; tu iras du puits du serment aux cimes de Sanir et d’Hermon, des antres des lions aux montagnes des panthères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, 'Tu m’as ravi mon cœur, ma sœur, mon épouse; tu m’as ravi mon cœur d’un seul de tes regards, d’un seul des cheveux de ton cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, 'Que tes mamelles sont belles, ma sœur, mon épouse! tes mamelles sont plus précieuses que le vin; et les senteurs de tes vêtements plus douces que tous les aromates.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'De tes lèvres découlent des rayons de miel, ô mon épouse; le miel et le lait sont sous ta langue, et l’odeur de tes vêtements est comme l’odeur de l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, 'Ma sœur, mon épouse, est un jardin enclos; c’est un jardin enclos, une fontaine scellée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Tes rejetons forment un jardin de grenades avec les fruits du noyer, des grappes en fleur et du nard,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'Du nard et du safran, de la canne et du cinnamome, de tous les arbres du Liban, de la myrrhe, de l’aloès, et des parfums les plus exquis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'La fontaine de ce jardin est un puits d’eau vive, qui jaillit du Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, 'Fuis d’ici, vent du nord; viens, vent du midi, souffle sur mon jardin, et que mes parfums en découlent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 1, 'Que mon frère bien-aimé descende en son jardin, qu’il mange de ses fruits. Je suis entré dans mon jardin, ma sœur, mon épouse; j’ai récolté ma myrrhe et mes parfums; j’ai mangé mon pain avec un rayon de miel; j’ai bu mon vin et mon lait. Mangez, ô mes amis; buvez, mes frères, et enivrez-vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 2, 'Pour moi, je dors, et mon cœur veille. C’est la voix de mon frère bien-aimé; il heurte à la porte: Ouvre-moi, dit-il, ma bien-aimée, ma sœur, ma colombe, ma parfaite; ma tête est pleine de rosée, et mes cheveux humides des gouttes de la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 3, 'J’ai ôté ma tunique; comment la revêtirai-je? Je me suis lavé les pieds; comment puis-je maintenant les salir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 4, 'Mon frère bien-aimé a passé la main dans l’ouverture de la porte, et si près de mon bien-aimé mes entrailles ont tressailli,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 5, 'Je me suis levée pour ouvrir à mon frère bienaimé; mes mains ont distillé la myrrhe; mes doigts ont rempli de myrrhe la poignée du verrou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 6, 'Et j’ai ouvert à mon frère bien-aimé, et mon frère bien-aimé n’était plus là; et mon âme était défaillante pendant qu’il parlait. Je l’ai cherché, et ne l’ai point trouvé; je l’ai appelé, et il ne m’a point entendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 7, 'Les gardes m’ont rencontrée, en faisant la ronde dans la ville; ils m’ont battue et meurtrie; les sentinelles des remparts m’ont dépouillée de mon manteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 8, 'Filles de Jérusalem, je vous adjure par les puissances et les vertus des campagnes, si vous avez trouvé mon frère bien-aimé, que lui direz-vous? Dites-lui que je suis blessée d’amour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 9, 'Qu’est donc ton frère bien-aimé auprès d’un autre frère, ô toi belle entre toutes les femmes? qu’est ton frère bien-aimé auprès d’un autre frère, pour que tu nous adjures ainsi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 10, 'Mon frère bien-aimé est blanc et rose, choisi entre dix mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 11, 'Sa tête est de l’or fin de Céphaz; ses cheveux sont souples, et noirs comme le corbeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 12, 'Ses yeux sont comme ceux des colombes sur des étangs pleins d’eau, lavées dans le lait, se reposant sur les étangs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 13, 'Ses joues sont comme des vases d’aromates exhalant des parfums; ses lèvres sont des lis distillant la myrrhe la plus pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 14, 'Ses mains sont gracieuses et d’or, et pleines de béryl; sa poitrine est une tablette d’ivoire sur une pierre de saphir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 15, 'Ses jambes sont des colonnes de marbre posées sur des bases d’or; sa beauté est celle du Liban elle excelle comme le cèdre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 16, 'Sa bouche est pleine de douceur, et fait naître les désirs; tel est mon frère bien-aimé, tel est mon ami, filles de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 17, 'Où est allé ton frère bien-aimé, ô toi belle entre toutes les femmes? Où ton frère bien-aimé s’est-il retiré? et nous le chercherons avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 1, 'Mon frère bien-aimé est descendu dans son jardin parmi les roses d’aromates, pour paître son troupeau dans sesjardins, et y cueillir des lis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 2, 'Je suis à mon frère bien-aimé, et mon frère bienaimé est à moi; il fait paître son troupeau parmi les lis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 3, 'Tu es belle, ô ma bien-aimée, comme la tendresse, gracieuse comme Jérusalem, terrible comme une armée en bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 4, 'Détourne de moi tes yeux, car ils m’ont transporté; ta chevelure est comme les troupeaux de chèvres que l’on voit en Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 5, 'Tes dents sont comme la toison des brebis sortant du lavoir après la tonte, qui toutes ont deux petits, et dont nulle n’est stérile. Tes lèvres sont comme un ruban écarlate, et ton langage est plein de grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 6, 'Tes joues sont comme la peau de la grenade, sans parler de tes beautés cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 7, 'Il y a soixante reines et quatre-vingts concubines, et des jeunes filles sans nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 8, 'Mais ma colombe, ma parfaite est unique; elle est l’unique de sa mère; elle est l’élue de celle qui l’a enfantée. Les jeunes filles l’ont vue, et la déclarent heureuse; les reines et les concubines la loueront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 9, 'Quelle est celle qui regarde dehors comme le matin; belle comme la lune, élue comme le soleil, terrible comme une armée en bataille?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 10, 'Je suis descendu au jardin des noyers, pour voir les fruits du vallon; si la vigne est en fleur, et si les grenades sont fleuries.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 11, 'Là je te donnerai mes mamelles. Mon âme n’a rien su, et j’ai été comme emportée par les chars d’Aminadab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 12, 'Reviens, reviens, ma Sulamite; reviens, reviens, et nous ne verrons que toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 1, 'Que verrez-vous en la Sulamite, qui vient comme les rangs d’une armée? Fille de Nadab, que les sandales donnent de grâce à tes pas! Les contours de tes jambes ressemblent à des colliers, chef-d’œuvre d’un artiste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 2, 'Ton nombril est comme un cratère fait au tour, оù le vin ne manque jamais. Ta poitrine est comme un monceau de froment enveloppé de lis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 3, 'Tes deux mamelles sont comme les deux faons jumeaux d’un chevreuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 4, 'Ton cou est comme une tour d’ivoire, tes yeux comme les étangs d’Hésebon, près des portes de la fille issue de beaucoup de peuples. Ton nez est comme la tour du Liban qui regarde Damas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 5, 'Ta tête est posée sur toi semblable au mont Carmel, et ta chevelure est comme de la pourpre; le roi est retenu dans tes galeries.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 6, 'O ma bien-aimée, que de grâce, que de suavité en tes délices!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 7, 'Ta stature est celle d’un palmier; tes mamelles sont comme des grappes de raisin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 8, 'J’ai dit: Je monterai au palmier; j’atteindrai à son faîte, et tes mamelles seront comme les grappes de la vigne, l’odeur de tes narines comme celle des pommes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 9, 'Et ton gosier comme un bon vin. (Épouse) Qu’aime mon frère bien-aimé (époux), et qui plaît à mes dents et à mes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 10, 'Je suis à mon frère bien-aimé, et son regard est tourné vers moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 11, 'Viens, mon frère bien-aimé, allons aux champs, dormons dans les bourgades.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 12, 'Levons-nous dès l’aurore pour aller aux vignes; voyons si le raisin est en fleur, si les graines sont en fleur, si les grenades fleurissent: c’est là que je te donnerai mes mamelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 13, 'Les mandragores ont donné leur senteur, et, au seuil de nos portes, tous les fruits verts et mùrs, ô mon frère bien-aimé, je les ai gardés pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 1, 'O mon frère bien-aimé, que n’as-tu sucé les mamelles de ma mère! Si je te trouve dehors, je te baiserai, et nul ne me méprisera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 2, 'Je te prendrai par la main, je t’introduirai dans la maison de ma mère, dans la chambre de celle qui m’a conçu. Je te ferai boire du vin parfumé, et du jus de mes grenades.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 3, 'Il posera sa main gauche sur ma tête, et, de la droite, il m’embrassera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 4, 'Je vous adjure, filles de Jérusalem, par les vertus de la campagne, n’éveillez pas, ne réveillez pas ma bien-aimée qu’elle ne le désire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 5, 'Quelle est celle qui se lève blanche comme l’aubépine, appuyée sur son frère bien-aimé (époux)? Je t’ai réveillée sous un pommier (4); c’est là que ta mère t’a enfantée; c’est là que t’a enfantée celle qui t’a conçu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 6, 'Mets-moi comme un sceau sur ton cœur, et comme un sceau sur ton bras. Car l’amour est fort comme la mort, et la jalousie est cruelle comme l’enfer; ses traits sont des traits de feu, ce sont ses flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 7, 'Des torrents d’eau ne pourront point éteindre l’amour, ni les fleuves le submerger. Si un homme donne toute sa vie par amour, les autres hommes auront pour lui le dernier mépris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 8, 'Notre sœur est petite, et n’a point de mamelles; que ferons-nous pour notre sœur, le jour où je viendrai lui parler?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 9, 'Si elle est un mur, couronnons-la de créneaux d’argent; si elle est une porte, incrustons-la de bois de cèdre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 10, 'Moi (l’épouse) je suis un mur, et mes mamelles sont comme des tours; et j’ai été à leurs yeux comme ayant trouvé la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 11, '(Époux) Salomon avait une vigne en Béelamon; il a donné sa vigne à ceux qui la gardent; chacun rendra de ses fruits mille sicles d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 12, 'Ma vigne est à moi; elle est devant mes yeux; que Salomon en ait mille sicles; que ceux qui gardent ses fruits en aient deux cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 13, 'O toi qui demeures dans les jardins, mes compagnes écoutent ta voix; fais-la-moi entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 14, 'Fuis, mon frère bien-aimé; et, rapide comme le chevreuil ou comme le faon de la biche, fuis dans les montagnes des parfums.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Il y avait, en la terre de Hus, un homme appelé Job, et cet homme était sincère, irréprochable, juste, craignant Dieu et s’abstenant de toute chose mauvaise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Or il avait sept fils et trois filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Et ses troupeaux étaient: Sept mille moutons, trois mille chamelles, cinq cents paires de bœufs, cinq cents ânesses au pâturage; il avait une multitude de serviteurs et de grands travaux sur la terre, et cet homme était noble parmi ceux de l’Orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Ses fils, se réunissant les uns chez les autres, faisaient chaque jour un festin, et ils prenaient aussi leurs trois sœurs pour boire et manger avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Et, quand leurs jours de repas étaient écoulés, Job les envoyait chercher, les purifiait, se levant de grand matin; puis il immolait des victimes comme il convenait à leur nombre, et en outre un veau pour le péché et pour leurs âmes. Car Job disait: C’est de peur que mes fils en leur cœur n’aient eu de mauvaises pensées contre Dieu. Ainsi faisait Job toutes les fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Or, un de ces jours-là, voilà que les anges de] Dieu comparurent devant le Seigneur, et le diable vint avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Et le Seigneur dit au diable; D’où viens-tu? Et le diable, répondant au Seigneur, dit: J’arrive après avoir fait le tour de la terre et parcouru tout ce qui est sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Et le Seigneur reprit: As-tu fait bien attention à Job mon serviteur? as-tu vu qu’il n’a point son pareil sur la terre; que c’est un homme irréprochable, sincère, craignant Dieu, et s’abstenant de toute chose mauvaise?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Et le diable répondit, et il dit devant le Seigneur: Est-ce gratis que Job honore le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'N’avez-vous point muni sa maison au dedans et au dehors, et alentour tout ce qui lui appartient? N’avez-vous pas béni les travaux de ses mains et multiplié ses troupeaux sur la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Mais faites tomber votre main, et touchez à tout ce qu’il possède; vous verrez s’il ne vous maudit pas en face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Alors le Seigneur dit au diable: Voilà toutes les choses qui sont à lui, je les remets entre tes mains, mais ne touche pas à sa personne; et le diable sortit, et il s’éloigna de devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Or, peu après ce jour-là, les fils de Job et ses filles buvaient du vin en la maison de l’aîné de leurs frères. Satan de tenter Job.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Voilà qu’un messager entre chez Job, et il lui dit Tes attelages de bœufs étaient au labour, et les ânesses paissaient tout auprès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Et des pillards sont venus, et ils les ont enlevés, et ils ont tué tes serviteurs à coups de glaive; j’ai seul échappé, et j’accours t’en apporter la nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 16, 'Il parlait encore lorsque survint un second messager, qui dit à Job: Le feu du ciel est tombé, et il a brûlé tes brebis, et il a dévoré pareillement les bergers; j’ai seul échappé, et je viens t’en apporter la nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 17, 'Comme celui-ci parlait encore, survint un autre messager, qui dit à Job: Des cavaliers ont formé trois bandes contre nous, et ils ont enveloppé les chamelles, et ils les ont enlevées; et ils ont tué les serviteurs à coups de glaive; j’ai seul échappé, et je viens t’en apporter la nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 18, 'Celui-ci parlait encore, quand un autre messager vint dire à Job: Tandis que tes fils et tes filles étaient à manger et à boire, chez leur frère aîné,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 19, 'Soudain un grand vent est venu du désert; il a frappé les quatre coins de la maison, et la maison s’est écroulée sur tes enfants, et ils sont morts; j’ai seul échappé, et je viens t’en apporter la nouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 20, 'Alors Job, s’étant levé, déchira ses vêtements, et il se coupa toute la chevelure, et, tombant à terre, il adora.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 21, 'Et il dit: Nu je suis sorti des entrailles de ma mère, nu aussi je m’en irai; le Seigneur m’avait donné, le Seigneur m’a ôté, il est advenu comme il a plu au Seigneur; béni soit le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 22, 'En tout ce qui lui était arrivé, Job ne pécha nullement contre le Seigneur, et il n’accusa point la sagesse de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Peu de jours après, les anges s’en vinrent comparaître devant le Seigneur, et le diable vint au milieu d’eux comparaître devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Et le Seigneur dit au diable: D’où viens-tu? Et le diable répondit devant le Seigneur: J’arrive ayant fait le tour de la terre, et parcouru tout ce qui est sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Et le Seigneur dit au diable: As-tu fait bien attention à Job mon serviteur? as-tu vu qu’il n’a point son pareil sur la terre? C’est un homme exempt de méchanceté, sincère, irréprochable, craignant Dieu, s’abstenant de tout mal. Il a gardé son innocence; et toi, tu t’étais vainement proposé de détruire tout ce qu’il possédait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Et le diable, reprenant, dit au Seigneur La peau seule vaut la peau, pour sa vie l’homme donnera tout ce qui lui appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Faites tomber votre main; qu’elle touche ses os et sa chair, et vous verrez s’il ne vous maudit pas en face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Et le Seigneur dit au diable: Voilà que je te le livre; seulement sauve sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Et le diable s’éloigna de devant le Seigneur, et il frappa Job, des pieds à la tête, d’un ulcère malin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Job prit un tesson pour racler le pus, et s’assit sur du fumier, hors de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Et, bien des jours s’étant écoulés, sa femme lui dit: Jusques à quand te résigneras-tu, disant: Oui, j’attendrai encore un peu de temps, persévérant dans l’espérance de mon salut? Voilà que sont effacés de la terre les souvenirs de toi, de tes fils et de tes filles, peine et souffrance de mes entrailles, et que j’ai vainement portés dans la douleur. Te voilà seul, assis dans la pourriture des vers, passant la nuit au serein. Et moi, errante et servant à gages, de lieu en lieu, de maison en maison, j’attends le coucher du soleil pour me reposer des labeurs et des maux qui maintenant m’accablent. Mais dis au Seigneur quelques paroles contre Dieu et meurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Or, l’ayant regardée fixement, il lui dit: Tu as parlé comme une des femmes insensées. Si nous avons reçu des biens de la main du Seigneur, ne supporterons-nous pas les maux? En toutes les choses qui lui étaient arrivées, Job ne pécha nullement des lèvres devant Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Or ses trois amis, ayant ouï tout le mal qui lui était advenu, vinrent à lui chacun de sa contrée: Éliphaz, roi de Théman; Baldad, roi de Sauchée, et Sophar, roi des Minéens. Et ils vinrent à lui d’un commun accord pour le visiter et consoler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Mais quand ils le virent de loin, ils ne le reconnurent pas, et, jetant de grands cris, ils pleurèrent, chacun déchirant sa robe et se couvrant de poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Ils s’assirent près de lui sept jours et sept nuits, et nul d’eux ne parla, car ils voyaient sa plaie, qui était grande et affreuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Après cela, Job ouvrit la bouche et il maudit son premier jour,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Périsse le jour où je suis né et cette nuit où l’on s’écria: C’est un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Que cette nuit reste obscure; que d’en haut jamais le Seigneur ne la rappelle; que jamais lueur ne vienne l’éclairer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Que les ténèbres et les ombres de la mort la pressent; qu’un sombre tourbillon tombe sur elle; maudits soient ce jour');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Et cette nuit; que l’obscurité la ravisse; qu’elle ne compte pas dans les temps de l’année; et que dans le mois elle ne soit point comprise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Mais que cette nuit ne soit que douleur, qu’on n’y voie jamais joie ni fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Qu’elle soit maudite de Celui qui fait de ce jour un jour maudit et qui peut maîtriser le grand monstre marin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Que les étoiles de cette nuit soient éclipsées; qu’elle ne cesse plus; que la lumière ne lui revienne jamais; qu’elle ne voie plus lever l’étoile qui annonce l’aurore;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Parce qu’elle n’a pas fermé les portes du ventre de ma mère, car elle eût ainsi détourné de mes yeux la douleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Pourquoi ne suis-je pas mort dans les entrailles qui m’ont enfanté? Pourquoi ne suis-je pas mort aussitôt que j’en suis sorti?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Pourquoi des genoux m’ont-ils recueilli? Pourquoi ai-je sucé des mamelles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Couché, je serais maintenant tranquille; endormi, je me reposerais;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Avec les rois, arbitres de la terre, qui s’enorgueillissaient de leurs épées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Ou avec les grands qui possédaient beaucoup d’or, et remplissaient d’argent leurs demeures;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 16, 'Ou comme un fœtus avorté, ou comme ces enfants qui n’ont pas vu la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 17, 'Dans ce lieu-là les impies ont consumé tout le feu de leur fureur; là se sont reposés ceux dont le corps était brisé de fatigue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 18, 'Et avec eux la foule qui n’a jamais entendu la voix du collecteur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 19, 'Et le petit et le grand, et le serviteur qui craignait son maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 20, 'Ah! pourquoi le jour a-t-il été donné à ceux qui sont dans l’amertume, et la vie aux âmes pleines de douleurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 21, 'Qui désirent la mort et ne l’obtiennent point, semblables à ceux qui creusent en vain, cherchant un trésor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 22, 'Et que la joie transporte s’ils viennent à le trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 23, 'La mort est à l’homme un repos; c’est le refuge où Dieu l’a réduit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 24, 'Avant mes aliments je connais les sanglots, et je pleure saisi de crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 25, 'Car ce que j’avais redouté m’a atteint; ce que j’avais pressenti m’est survenu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 26, 'Je n’ai point vécu en paix, je n’ai eu ni calme ni repos, et la colère de Dieu est tombée sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Or Eliphaz le Thémanite, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'N’as-tu pas souvent parlé à ceux qui étaient dans la douleur? Qui supportera la violence de tes discours?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Car si tu as instruit beaucoup d’hommes, si tu as raffermi des mains défaillantes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Si, par tes paroles, tu as ranimé des faibles, si tu as donné du courage à ceux dont les genoux fléchissaient,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Maintenant que le mal est venu, et qu’il t’a saisi, tu en es tout accablé!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Ne t’abuses-tu point au sujet de ta crainte de Dieu, de ton espérance et de l’innocence de tes voies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Recueille tes souvenirs; qui donc, étant resté pur, a péri? quel homme sincère a été détruit radicalement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Comme ceux qui labouraient et ensemençaient des terres vaines, et que j’ai vus moissonner pour eux des douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Ceux-là seront anéantis par l’ordre de Dieu; ils seront effacés par le souffle de sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Ainsi, la force du lion, les rugissements de la lionne, l’audace des dragons s’éteint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Ainsi, le fourmi-lion meurt faute d’un brin d’herbe; les lionceaux quittant leurs mères se dispersent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'S’il y avait quelque chose de vrai dans tes paroles, aucun de ces maux ne te serait arrivé. Est-ce que mon oreille ne recueillera pas les révélations extraordinaires me venant de Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Comme l’effroi se répandait parmi les hommes, pendant l’horreur et les bruits sinistres de la nuit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 14, 'Un tremblement, un frisson me saisirent; et mes os s’entre-choquèrent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 15, 'Et un esprit se posa sur mon visage, et mes cheveux et mes chairs en frémirent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 16, 'Je me levai et ne vis rien, et je reconnus qu’il n’y avait aucune forme devant mes yeux; mais j’ouïs un souffle et une voix, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 17, 'Quoi donc! Est-ce qu’un mortel sera pur devant le Seigneur? est-ce qu’un mortel serait irréprochable dans ses œuvres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 18, 'Puisque Dieu ne peut se fier en ses serviteurs et qu’il découvre du mal même en ses anges,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 19, 'Que sera-ce de ceux qui habitent des maisons de boue, de cette boue dont nous avons été tirés? Aussi les écrase-t-il comme des vermisseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 20, 'L’aurore se lève sur eux, et le soir ils ne sont plus; pour n’avoir pu s’aider eux-mêmes, ils ont péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 21, 'Car Dieu, d’un souffle, les a desséchés; ils sont morts, parce qu’ils ne possédaient point la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Appelle donc, s’il est quelqu’un qui t’écoute, ou si tu vois l’un des saints anges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Car la colère détruit l’insensé; l’envie tue celui qui s’égare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'J’ai vu des insensés prendre racine; mais leur demeure a été soudain détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Qu’il n’y ait point de salut pour leurs enfants; qu’ils soient écrasés devant la porte des petits; que nul ne les délivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Les justes mangeront ce qu’ils ont amassé, tandis qu’eux-mêmes ne pourront sortir de leur misère; que leur force soit épuisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Ce n’est point de la terre que naît la fatigue; ce ne sont point les montagnes qui font germer les peines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Mais l’homme est né pour se fatiguer, comme les petits des vautours pour voler sur les hautes cimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Aussi je prierai le Seigneur, j’invoquerai le Seigneur, maître de tout,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Qui fait des choses grandes et incompréhensibles, des merveilles glorieuses et innombrables;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Qui donne à la terre de la pluie, de l’eau à tout ce qui est sous le ciel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Qui met au plus haut les humbles, et relève les perdus;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Qui dissipe les conseils des trompeurs, et empêche leurs mains de les réaliser;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Qui confond la prudence des sages, et détruit les desseins des hommes rusés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'En plein jour les ténèbres les enveloppent; qu’ils marchent à tâtons à midi comme à minuit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Qu’ils périssent dans les batailles, et que le faible soit délivré de la main des puissants;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Que le faible conserve l’espérance; que le Seigneur ferme la bouche de l’injuste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Heureux l’homme que châtie le Seigneur; ne rejette donc pas l’admonition du Tout-Puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Car il fait souffrir, et il répare; il frappe, et ses mains guérissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Six fois il te tirera de peine; la septième fois le mal ne t’atteindra plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Pendant la famine, il te préservera de la mort; à la guerre, il détournera de toi le fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Il te mettra à l’abri des flagellations de la langue, et tu n’auras rien à craindre des maux qui surviendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Tu te riras des injustes et des déréglés; tu ne craindras point les bêtes féroces;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Car les animaux farouches des champs te laisseront en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Tu verras la paix dans ta demeure, et ceux qui habitent sous ta tente ne pècheront point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Tu verras croître une florissante famille, aussi nombreuse que les herbes des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Et tu descendras en la tombe, mûr comme le blé que l’on moissonne en la saison, ou comme le monceau qu’en son temps on a renfermé dans l’aire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Telles sont les pensées que j’ai cherchées sur le sujet; voilà ce que j’ai entendu; examine donc en toimême si tu as fait quelque mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Et Job, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Puisse-t-on peser et peser mes plaintes, et les mettre en balance avec mes douleurs!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Celles-ci seraient plus lourdes que le sable du rivage de la mer; mais, à ce qu’il me semble, mes paroles sont méprisées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Car j’ai dans le corps les traits du Seigneur, leur violence boit tout mon sang, et, dès que je commence à discourir, ils me percent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Mais quoi! est-ce sans motif que l’âne sauvage se met à braire, ou parce qu’il demande à manger? et le bœuf mugit-il devant une crèche pleine de fourrage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Mange-t-on des aliments sans sel? et trouve-t-on du goût aux paroles vaines?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Ma plainte peut-elle se calmer, quand je me repais, pour ainsi dire, d’odeurs infectes comme celle du lion?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Plût au ciel que ma prière fût exaucée! puisse le Seigneur m’accorder ce que j’espère!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Le Seigneur ayant commencé, qu’il me blesse, mais qu’il ne me perde pas pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Que le sépulcre soit ma ville, dont j’aie franchi le mur d’un saut; je ne chercherai pas à l’éviter, car je n’ai jamais éludé les saintes volontés de mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Quelle est donc ma force pour tout supporter? Quel est donc mon temps, pour que mon âme soutienne son courage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Est-ce que ma force est la force des pierres? Est-ce que mes chairs sont d’airain?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'N’ai-je pas mis ma confiance en Dieu? Mais le secours est loin de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'La miséricorde m’a été déniée, la visite du Seigneur m’a délaissé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 15, 'Mes plus proches ne m’ont point regardé; ils ont disparu comme un torrent, ils ont passé devant moi comme un flot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 16, 'Ceux qui me révéraient sont maintenant tombés sur moi, comme la neige ou la glace;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 17, 'Quand elles fondent, la chaleur étant venue, on ne sait plus ce que c’était.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 18, 'C’est ainsi qu’ils m’ont tous abandonné; je suis perdu et je suis devenu sans asile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 19, 'Regardez les chemins de Théman; voyez les sentiers de Saba:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 20, 'Ils auront à rougir de honte, ceux qui se confient en des villes et des richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 21, 'Et vous aussi, vous êtes venus à moi sans pitié, et, quand vous avez vu ma plaie, vous avez eu peur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 22, 'Pourquoi donc? Vous ai-je rien demandé? Est-ce que j’attends de vous quelque force');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 23, 'Pour me sauver des mains de mes ennemis, et me délivrer des mains des puissants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 24, 'Instruisez-moi, et je garderai le silence; si j’ai erré en quoi que ce soit, dites-le-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 25, 'Mais, à ce qu’il me semble, les paroles d’un homme sincère sont méprisées; je ne vous demande aucun secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 26, 'Vos réprimandes ne me rendront pas le calme, car je ne puis supporter le bruit de vos paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 27, 'En effet, vous tombez sur un orphelin, vous vous jetez sur votre ami.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 28, 'Oui, maintenant je vous regarde en face, et ne mens point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 29, 'Asseyez-vous donc, et rejetez l’iniquité; soyez encore avec le juste;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 30, 'Car ma langue dit-elle rien qui ne soit équitable, et mon gosier ne médite-t-il pas la sagesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'La vie de l’homme sur la terre est-elle autre chose qu’une épreuve? Son existence n’est-elle pas celle d’un mercenaire à la journée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Ou comme l’esclave qui craint son maître, et ne gagne que de l’ombre, ou comme celle du journalier qui attend son salaire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Pour moi pareillement j’ai enduré des mois vides, il ne m’a été donné que des nuit de douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Si je me couche, je me dis: Quand viendra le jour? et si je me lève: Quand viendra le soir? Et je suis plein de souffrances du soir à l’aurore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Mon corps est couvert de la poussière des vers; j’amollis les glèbes de la terre avec le pus que je jette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Ma vie est plus rapide que la parole; elle s’est consumée en une espérance déçue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Souvenez-vous, Seigneur que ma vie n’est, qu’un souffle, et que mon œil ne verra plus rien d’heureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'L’œil de celui qui me voit ne me verra plus; vous jetez un regard sur moi, et je ne suis plus,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'De même qu’un nuage qui s’est fondu dans le ciel. Car une fois descendu aux enfers, l’homme n’en remontera jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Il ne reviendra point en la maison qui était la sienne, et sa contrée natale ne le connaîtra plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'C’est pourquoi je n’épargnerai pas les discours; je parlerai dans l’angoisse où je suis; j’ai hâte d’épancher l’amertume de mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Suis-je une mer; suis-je un dragon pour que vous m’enfermiez ainsi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'J’ai dit Mon lit me consolera, et je renfermerai en moi-même les pensées qui me viendront sur ma couche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Vous m’effrayez par des songes, vous m’épouvantez par des visions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Retirez de ma vie le souffle; que la mort désunisse mes os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Je ne puis toujours vivre afin que ma patience soit toujours exercée. Détournez-vous de moi, car ma vie est inutile, est vaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Qu’est-ce donc que l’homme pour que vous l’honoriez, pour que vous attachiez sur lui votre pensée? quoique sa volonté demeurât toujours soumise. Ainsi, Job se laisse aller à des plaintes qui n’affectent en lui que la partie inférieure et sensible de la nature.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 18, 'Ne le visiterez-vous pas avant le jour? et le jugerez-vous pendant les heures du repos?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 19, 'Jusqu’à quand me retiendrez-vous? et ne me laisserez-vous pas même avaler ma salive?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 20, 'Si j’ai péché, que pourrais-je faire, ô vous qui connaissez la pensée des hommes? Pourquoi m’avez-vous contraint de vous adresser mes plaintes, et d’être pour vous un fardeau?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 21, 'Pourquoi n’avez-vous pas mis en oubli mon iniquité et ne m’avez-vous point purifié de mon péché? Je vais tout à l’heure entrer dans la terre; aux premières lueurs du matin je ne suis plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Et Baldad de Sauchée, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Jusqu’à quand parleras-tu de la sorte, et l’esprit de ta bouche sera-t-il si verbeux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Dieu est-il un juge prévaricateur? le créateur de toutes choses torture-t-il l’équité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Si tes fils ont péché devant lui, il a de sa main réprimé leurs déréglements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Commence donc dès l’aurore à prier le Dieu tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Si tu es pur et sincère, il exaucera ta prière et il te restituera la demeure de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Ta prospérité première sera petite en comparaison de la dernière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Informe-toi de la première génération; remonte pas à pas jusqu’à nos pères. prier, et à ne point ressembler à l’impie dont il décrit la chute. Il te rendra la prospérité, qui est la récompense du juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Car nous sommes d’hier et nous ne savons rien, et notre vie sur la terre est une ombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'N’est-ce donc pas à nos pères de t’instruire, de t’éclairer, et de tirer de leur cœur des paroles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Le jonc verdoie-t-il sans eau? le glaïeul croît-il s’il n’est arrosé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Il se tient aujourd’hui sur sa racine, et ne sera pas fauché; mais, avant que toute autre herbe tombe (sous la faux), n’est-il pas desséché?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Tous ceux que le Seigneur oublie finiront ainsi; car l’espérance de l’impie périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Sa maison sera déserte; sa tente se remplira d’araignées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 15, 'Il étaiera sa maison; mais elle ne sera pas solide: il essaiera de la soutenir, et elle ne tiendra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 16, 'Comme une plante humide sous le soleil, mais dont la tige sort d’une racine corrompue;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 17, 'Qui gît parmi les pierres, et vit au milieu d’un amas de cailloux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 18, 'Si on vient à l’arracher, le lieu même la reniera. N’as-tu pas vu de telles choses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 19, 'Ainsi est emporté l’impie; et de la terre une autre plante germera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 20, 'Le Seigneur ne rejettera pas l’innocent: il n’acceptera aucun don de l’impie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 21, 'Il mettra le sourire sur les lèvres de l’homme sincère; et leur bouche sera remplie de ses louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 22, 'Leurs ennemis seront couverts de honte, et la demeure de l’impie périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Et Job, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'En vérité, je sais qu’il en est ainsi: comment un mortel sera-t-il juste aux yeux du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Car, s’il veut entrer en jugement avec lui, Dieu n’y voudra point entendre, et lui n’aura pas à répondre un mot contre mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Dieu est sage en ses pensées, il est fort, il est grand; qui donc, s’étant endurci contre lui, a subsisté?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Il fait disparaître les montagnes, et elles l’ignorent; il les bouleverse dans sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Il ébranle, jusque dans ses fondements, la terre sous le ciel, et les colonnes qui la soutiennent sont chancelantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Il commande au soleil, et il ne se lève pas; il appose son sceau sur les astres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'C’est lui seul qui a tendu le ciel et qui marche sur la mer, comme sur un sol affermi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Lui qui a créé les Pléiades, et l’étoile du soir, et Arcture, et les constellations du Midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Il a fait une multitude de merveilles grandes, glorieuses et incompréhensibles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'S’il m’a dépassé, je ne l’ai point vu; s’il a marché auprès de moi, je n’en ai rien su.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'S’il prend, qui rendra? Qui osera lui dire: Que faites-vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Il ne rappellera point sa colère; les monstres marins qui sont sous le ciel ont plié sous lui. écouté; il le prie de ne point lui inspirer la crainte qui le trouble et l’empêche de démontrer son innocence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'S’il m’écoutait; s’il voulait mes paroles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Quand même je serais juste, je n’aurais pas le dessus; j’implorerais sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 16, 'Et si je l’avais invoqué et qu’il m’exauçât, je ne pourrais croire qu’il eût entendu ma voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 17, 'Oh! qu’il ne me broie pas en un tourbillon; mais il m’a fait une multitude de plaies sans cause.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 18, 'Il ne me laisse point reprendre haleine; mais il me remplit d’amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 19, 'Et il prévaut par la force. Qui donc résisterait à son jugement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 20, 'Quand même je serais juste, ma bouche me reprocherait des fautes, et si je suis irréprochable, je serai encore montré mauvais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 21, 'Car si j’ai péché, je n’en ai pas conscience, et néanmoins la vie m’est arrachée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 22, 'Voilà pourquoi j’ai dit: La colère divine fait périr le parfait et le violent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 23, 'Les méchants meurent d’une manière funeste; mais les justes sont tournés en dérision');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 24, 'Ils sont livrés aux mains des pervers; et le Seigneur a voilé la face des juges. Et si ce n’est lui, qui est-ce donc?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 25, 'Ma vie est plus rapide qu’un coursier; mes jours ont fui, et ils n’ont pas vu le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 26, 'Les navires laissent-ils une trace, ou l’aigle qui vole et cherche sa proie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 27, 'Si je me dis: Je cesserai de parler, et, courbant la tête, je me bornerai à gémir;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 28, 'Voilà que je tremble de tous mes membres; car je sais que vous ne me jugez point innocent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 29, 'Puisque je suis réputé un impie, pourquoi donc ne suis-je pas mort?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 30, 'Lors même que je me serais lavé avec de la neige et que je me serais purifié avec des mains pures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 31, 'Vous m’avez plongé tout entier dans la fange, et ma robe m’est en abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 32, 'Car vous n’êtes point comme moi un homme, avec qui je puisse contester et comparaître en justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 33, 'Que n’existe-t-il entre nous un médiateur, un censeur, qui écoute la cause entre vous et moi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 34, 'Détournez de moi votre verge; que l’effroi qu’elle m’inspire ne me trouble plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 35, 'Et je ne craindrai plus, mais je parlerai; car je ne sais plus où j’en suis!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 1, 'Fatigué en mon âme, gémissant, je laisserai à mon sujet exhaler mes paroles, je parlerai dans l’amertume de mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 2, 'Et je dirai au Seigneur: Ne me traitez pas en impie; pourquoi m’avez-vous jugé de la sorte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 3, 'Est-il bien à vous de me traiter en coupable? Vous avez méconnu l’œuvre de vos mains, vous avez adhéré au conseil des méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 4, 'Est-ce que vous voyez comme voit un mortel? regardez-vous comme regarde un homme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 5, 'Votre vie est-elle la vie humaine; vos années sont-elles les années d’un homme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 6, 'Pour que vous ayez examiné mes iniquités, et que vous ayez scruté mes méfaits?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 7, 'Vous saviez que je n’avais pas commis l’impiété; mais quel est celui qui peut me tirer de vos mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 8, 'Elles m’ont pétri et créé; puis vous avez changé de sentiment et vous m’avez frappé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 9, 'Souvenez-vous que vous m’avez fait d’argile, et que vous me rendrez à la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 10, 'Ne m’avez-vous point trait comme du lait, puis caillé comme du fromage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 11, 'Ensuite vous m’avez revêtu de chair et de peau; vous avez ajusté en moi mes os et mes nerfs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 12, 'Vous m’avez donné la vie et votre miséricorde; votre visite m’a conservé le souffle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 13, 'Quoique vous cachiez en vous ces choses, je sais que vous pouvez tout, que rien ne vous est impossible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 14, 'Si je pèche vous me gardez, et vous ne m’innocenterez point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 15, 'Si j’ai mal agi, malheur à moi; et si je me sens juste je ne puis néanmoins lever la tête, tant je suis rempli d’humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 16, 'Je suis saisi comme par un lion dévorant; vous changez plusieurs fois à mon égard, et me perdez cruellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 17, 'En renouvelant l’examen que j’ai déjà subi, vous m’avez traité avec grande colère, et m’avez envoyé bien des épreuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 18, 'Pourquoi m’avoir tiré des entrailles de ma mère? Pourquoi ne suis-je pas mort afin qu’œil ne me vît,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 19, 'Et que je fusse comme si je n’eusse été? Pourquoi ne suis-je point allé du ventre de ma mère au tombeau?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 20, 'Le temps de ma vie n’est-il pas court? laissez-moi reposer un moment,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 21, 'Avant que j’aille au lieu d’où je ne reviendrai plus');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 22, 'Dans la terre des ténèbres éternelles, où il n’y a pas de lumière, où l’on ne voit point la vie des mortels.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 1, 'Or Sophar le Minéen, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 2, 'Celui qui parle tant, à son tour écoutera. Est-ce que le beau parleur s’imagine être juste? S’il en était ainsi, heureux le fils de la femme qui vit peu de jours!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 3, 'Ne te répands pas en longs discours quand nul n’est là pour te contredire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 4, 'Surtout ne dis pas Je suis pur en mes œuvres; je suis irréprochable devant Lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 5, 'Car, comment le Seigneur répondrait-il et ouvrirait-il ses lèvres devant toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 6, 'Ensuite il te fera connaître la vertu de la sagesse qui te sera alors doublement dévoilée; tu reconnaîtras alors que le Seigneur t’a rétribué justement selon tes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 7, 'Découvriras-tu les traces du Seigneur? es-tu allé jusqu’aux dernières limites de ce que le Tout-Puissant a créé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 8, 'Le ciel est haut; que feras-tu? Est-il rien de plus profond que les choses de l’enfer? qu’en sais-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 9, 'Ou de plus grand que la dimension de la terre, et l’étendue de la mer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 10, 'S’il lui plaît de bouleverser toutes ces choses, qui lui dira: Qu’avez-vous fait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 11, 'Seul il connaît les œuvres des déréglés; s’il voit des méfaits, il ne feindra pas de n’en rien savoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 12, 'L’homme nage au hasard dans ses raisonnements; le mortel, né de la femme, est comme l’âne dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 13, 'Si tu purifies ton cœur, si tu élèves tes mains vers Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 14, 'Si tes mains étant chargées de quelque iniquité, tu te hâtes de la rejeter au loin, et si l’injustice ne séjourne point en ta demeure:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 15, 'Alors ton visage brillera comme une onde pure, tu te dépouilleras de ta souillure, et tu ne sentiras plus de crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 16, 'Tu oublieras tes douleurs; comme une vague qui passe, tu n’auras plus d’effroi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 17, 'Ta prière ressemblera à l’étoile qui annonce l’aurore; ta vie se lèvera au Midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 18, 'Tu seras plein de confiance, parce que l’espérance ne t’aura pas abandonné; de tes soucis, de tes peines naîtra la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 19, 'Tu jouiras du repos et n’auras plus d’ennemis; une foule d’hommes reviendront te prier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 20, 'Cependant le salut délaissera les impies; leur espérance sera leur perte, et leurs yeux fondront en larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 1, 'Et Job, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 2, 'Après tout, vous êtes des hommes; est-ce qu’avec vous la sagesse périra?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 3, 'J’ai comme vous un cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 4, 'Oui, un homme juste et irréprochable a été livré à la raillerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 5, 'Au temps marqué il devait périr par des mains étrangères, et voir sa maison pillée par des méchants; toutefois que personne ne croie, ayant fait le mal, être innocenté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 6, 'Tous ceux qui irritent le Seigneur ne devaient pas être recherchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 7, 'Interroge les bêtes des champs, et elles te parleront; questionne les oiseaux du ciel, et ils t’instruiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 8, 'Raconte tout à la terre, et elle te répondra; les poissons de la mer aussi s’expliqueront avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 9, 'Qui donc ne voit en tous les êtres que la main du Seigneur les a créés?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 10, 'N’a-t-il pas en sa main la vie de tout ce qui existe, et le souffle de tout homme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 11, 'L’oreille discerne les paroles; le gosier goûte les aliments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 12, 'La sagesse est au grand âge, et la science est le fruit d’une longue vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 13, 'Toute force, toute sagesse sont avec Dieu; lui seul a l’intelligence et le conseil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 14, 'S’il a démoli, qui rebâtira? S’il a enfermé les hommes, qui ouvrira?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 15, 'S’il retient les eaux, il dessèche la terre; s’il les laisse partir, il la bouleverse et la ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 16, 'A lui la puissance et la force, à lui la science et l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 17, 'C’est lui qui conduit en captivité les conseillers des peuples et qui trouble l’esprit des juges de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 18, 'Il assied les rois sur leurs trônes; il ceint leurs reins du baudrier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 19, 'Il fait les prêtres captifs; il renverse les grands de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 20, 'I change les lèvres des fidèles; il pénètre la science des anciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 21, 'Il répand la honte sur les chefs; il guérit les humbles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 22, 'Il dévoile l’abîme des ténèbres, et il amène à la lumière l’ombre de la mort?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 23, 'Il égare les nations, il les détruit; il abat les peuples ou il les relève.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 24, 'Il change le cœur des sages de la terre; il les fait errer en un chemin qu’ils ne connaissaient pas, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 25, 'Qu’ils marchent à tâtons dans les ténèbres; qu’il n’y ait pas pour eux de lumière; qu’ils soient incertains comme un homme ivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 1, 'Voilà ce que mon œil a vu, et ce qu’a entendu mon oreille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 2, 'Tout ce que vous savez, je le sais, et non plus que vous je ne manque d’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 3, 'Je parlerai donc au Seigneur; j’entrerai en discussion avec lui s’il ne s’y oppose pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 4, 'Vous êtes des médecins iniques, et vous êtes tous des fauteurs de maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 5, 'Que ne gardez-vous le silence, pour attirer en vous la sagesse!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 6, 'Écoutez les reproches de ma bouche, recueillez le jugement que prononcent mes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 7, 'N’est-ce pas devant le Seigneur que vous avez');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 8, 'Est-ce que vous cédez à la crainte, et voulez-vous être juges de sa cause?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 9, 'C’est bien, qu’il vous scrute; car si, en tout ce que vous faites, vous avez de la partialité pour lui,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 10, 'Il ne vous en reprendra pas moins. Et si en secret vous avez fait acception de sa personne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 11, 'Est-ce que son tourbillon ne vous enlèvera pas? L’épouvante qu’il répand tombera sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 12, 'Votre gloire s’en ira (elatio vestra) comme de la cendre; votre corps sera comme de la boue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 13, 'Taisez-vous, afin que je parle et que j’apaise la colère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 14, 'Qui me fait prendre ma chair entre mes dents, et mettre mon âme dans ma main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 15, 'Quand même le Tout-Puissant m’écraserait, puisqu’il a commencé, je ne laisserais pas de parler, et de m’expliquer avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 16, 'Et ce sera mon salut; car devant Dieu la fraude n’a point accès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 17, 'Écoutez, écoutez mes paroles; car je vous annoncerai la vérité, à vous qui me prêtez l’oreille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 18, 'Me voici tout près de mon jugement, et je sais que je serai reconnu juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 19, 'Car, quel est celui qui comparaîtra avec moi devant le juge, pour que maintenant je me taise et que je déserte ma cause?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 20, 'Accordez-moi deux choses; alors, ô mon Dieu, je ne me cacherai point devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 21, 'Détournez de moi votre main, et que la crainte de vous ne m’épouvante pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 22, 'Ensuite, appelez-moi, et j’obéirai; parlez-moi, et je vous répondrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 23, 'Combien ai-je de péchés et de dérèglements? Apprenez-moi quels ils sont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 24, 'D’où vient que vous vous cachez de moi, et que vous me croyez votre ennemi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 25, 'Avez-vous peur d’une feuille emportée par le vent? ou vous attaquerez-vous à la paille qu’un souffle emporte à moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 26, 'Et vous avez écrit contre moi de durs arrêts, et vous m’avez imputé les péchés de ma jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 27, 'Vous avez mis mes pieds en des entraves, vous');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 28, 'Moi qui suis déjà comme une vieille outre ou comme un vêtement mangé des vers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 1, 'L’homme, né de la femme, vit peu, et il est plein de passions violentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 2, 'Il tombe comme une fleur qui s’est épanouie; il passe comme une ombre, et il ne s’arrête jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 3, 'Et c’est de lui que vous exigez raison, lui que vous faites entrer en jugement devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 4, 'Qui sera exempt de toute souillure? Personne,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 5, 'Sa vie sur la terre n’eût-elle duré qu’un jour. Vous avez supputé le nombre de ses mois; vous avez fixé le terme, nul ne le dépasse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 6, 'Détournez-vous de lui afin qu’il se repose, et qu’il se complaise en sa vie comme le travailleur à gages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 7, 'L’arbre lui-même a l’espérance; même si on l’abat, il repoussera encore, et il ne manquera pas de rejetons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 8, 'Si sa racine a vieilli en terre, si elle a péri au milieu des pierres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 9, 'La fraîcheur de l’eau ranimera le tronc, et il portera des fruits, comme un plant nouveau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 10, 'Mais l’homme meurt, et il disparaît; le mortel tombe, et il n’est plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 11, 'La mer en son temps diminue; le fleuve désolé se dessèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 12, 'L’homme, une fois couché, ne se relèvera pas, jusqu’à ce que le ciel se dissolve; les morts ne sortiront point auparavant de leur sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 13, 'Puissiez-vous me regarder dans les enfers, et me cacher jusqu’à ce que votre courroux s’apaise, me marquer le temps où vous vous souviendrez de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 14, 'Car lorsque l’homme est mort, et lorsqu’il a rempli les jours de sa vie, il vivra; j’attendrai jusqu’à ce que je renaisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 15, 'Vous m’appellerez, et alors je vous obéirai; ne rejetez donc pas les œuvres de mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 16, 'Vous avez compté mes œuvres, et nulle de mes fautes ne vous est échappée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 17, 'Vous avez scellé mes péchés dans un sac; et ceux que j’ai faits comme malgré moi, vous les avez marqués');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 18, 'Mais les monts s’écroulent, les roches s’arrachent de leurs bases;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 19, 'Les eaux usent la pierre, les ondes couvrent les hautes cimes de la terre, et vous avez abîmé la patience de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 20, 'Vous l’avez poussé dans la mort, et il est parti; vous avez tourné vers lui votre visage, et vous l’avez congédié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 21, 'Des fils nombreux sont issus de lui, il n’en sait rien; sa postérité n’est pas nombreuse, il l’ignore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 22, 'Mais ses chairs ont connu la souffrance, et son âme a été affligée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 1, 'Et Éliphaz le Thémanite, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 2, 'Est-ce que le sage répond par des paroles en l’air; remplissant son cœur d’amertume?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 3, 'Exhale-t-il des plaintes inconvenantes et des discours inutiles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 4, 'N’as-tu pas répudié toute crainte pour tenir un tel langage devant le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 5, 'Tu es coupable en ces paroles de ta bouche; tu n’as point apprécié celles des hommes capables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 6, 'C’est ta bouche que j’accuse et non moi; tes lèvres contre toi porteront témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 7, 'Quoi donc! es-tu le premier homme qui ait existé? As-tu été formé avant les montagnes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 8, 'As-tu entendu les décrets du Seigneur? Dieu s’est-il servi de toi comme d’un conseiller? la sagesse s’est-elle réfugiée en toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 9, 'Que sais-tu que nous ne sachions? que comprends-tu que nous ne comprenions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 10, 'Et chez nous aussi il est des vieillards, des anciens plus chargés de jours que ne le fut ton père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 11, 'Tu as été puni faiblement pour tes péchés; et tes paroles dépassent toute mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 12, 'Qu’a donc osé ton cœur, et quelle audace ont tes yeux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 13, 'Pour que tu aies fait éclater ta colère devant le Seigneur, et laissé de telles paroles sortir de ta bouche?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 14, 'Qui donc, étant mortel, sera irréprochable? Qui donc, étant né de la femme, sera démontré comme juste?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 15, 'Puisque Dieu ne trouve pas la perfection en ses saints, et que devant lui le ciel n’est pas pur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 16, 'Souffre donc qu’il considère comme impur et abominable l’homme qui boit l’iniquité à pleine coupe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 17, 'Je vais te dire, écoute-moi, je vais te révéler ce que j’ai vu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 18, 'Ce que rapportent les sages après l’avoir appris de leurs pères,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 19, 'Les sages à qui seuls la terre a été donnée, et que jamais étranger n’a supplantés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 20, 'Les jours de l’impie se passent dans l’inquiétude; les années du puissant de la terre sont comptées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 21, 'La terreur est dans ses oreilles, et lorsqu’il croit jouir d’un moment de paix, sa catastrophe est prochaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 22, 'Qu’il ne s’imagine pas revenir des ténèbres; car il est déjà livré au glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 23, 'Il est réservé à rassasier des vautours; il n’ignore pas en lui-même qu’il attend sa chute; le sombre jour l’emportera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 24, 'L’angoisse et la tribulation vont l’abattre, comme un chef de guerre qui tombe au premier rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 25, 'Car il a porté la main contre le Tout-Puissant, il a levé la tête avec orgueil devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 26, 'Il a couru sur Dieu plein d’arrogance, tendant le dos de son épais bouclier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 27, 'La graisse gonflait son visage, la graisse pendait sur ses cuisses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 28, 'Puisse-t-il passer la nuit en des villes désertes, et loger en des demeures inhabitées! Que d’autres emportent ce que les siens auront préparé!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 29, 'Il n’augmentera pas sa richesse; sa substance ne se conservera pas; elle ne projettera plus d’ombre sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 30, 'Il n’échappera point aux ténèbres; le vent flétrira ses bourgeons, et sa fleur tombera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 31, 'Qu’il ne croie pas subsister, il aboutira à des choses vaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 32, 'Sa moisson sera détruite avant la maturité; ses rameaux ne verdiront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 33, 'Qu’il soit cueilli avant le temps comme un raisin vert; qu’il tombe comme une fleur d’olivier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 34, 'Car la mort est le témoignage de l’impie, et le feu brûlera les demeures de celui qui se laisse gagner par des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 35, 'Il ne concevra que des douleurs, il n’enfantera que mensonges, et le fruit de ses entrailles sera la fraude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 1, 'Et Job, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 2, 'J’ai entendu bien des choses semblables; vous êtes tous de tristes consolateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 3, 'Quoi donc! y a-t-il un frein aux paroles en l’air? est-il bien difficile de répondre ainsi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 4, 'Et moi aussi je discourrais comme vous, si votre âme était mise à la place de la mienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 5, 'Je pourrais vous insulter en paroles, et secouer comme vous la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 6, 'Puisse la force de ma bouche ne pas défaillir, et je n’épargnerais point le mouvement de mes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 7, 'Mais si je parle, ne sentirais-je plus les douleurs de ma plaie et si je me tais, en souffrirais-je moins?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 8, 'Maintenant elle m’a rompu, elle m’a ôté tout sentiment, elle m’a réduit en pourriture; ô plaie, tu m’as garrotté!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 9, 'Elle a porté témoignage et s’est élevée contre moi, la menteuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 10, 'Dans sa colère, mon ennemi m’a renversé; il a grincé des dents contre moi; les traits de ses pirates m’ont atteint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 11, 'Il a dardé sur moi les rayons de ses yeux, il m’a frappé aux genoux avec des pointes aiguisées; ils m’ont assaillis tous à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 12, 'Le Seigneur m’a livré à des mains iniques, il m’a jeté au milieu des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 13, 'Je vivais en paix, et il m’a déchiré; il m’a pris par les cheveux et il me les a arrachés; il m’a planté devant lui comme un but.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 14, 'Des archers m’ont entouré, et, de leur fer, ils m’ont percé les flancs, ils ont fait couler mon fiel jusqu’à terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 15, 'Ils m’ont abattu, me faisant faire chute sur chute; les puissants ont couru contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 16, 'Ils ont cousu un cilice sur ma peau; ma force a été éteinte sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 17, 'Ma poitrine est brûlante, tant j’ai pleuré, et j’ai sur les paupières une ombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 18, 'Et cependant mes mains n’étaient chargées d’aucune iniquité, et ma prière était pure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 19, 'Terre, ne couvre point le sang de ma chair, de sorte qu’il n’y ait plus d’espace pour mes cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 20, 'Et maintenant voilà que mon témoin est dans le ciel; le confident de mes pensées est au plus haut des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 21, 'Puisse ma prière arriver au Seigneur; puissent mes yeux pleurer devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 22, 'Puisse l’homme plaider devant le Seigneur, comme le fils de l’homme plaide avec son voisin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 23, 'Car mes années peu nombreuses s’en vont, et je m’avance par un chemin où je ne reviendrai plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 1, 'Je meurs tourmenté par l’esprit mauvais; j’aspire à la tombe et je n’y arrive pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 2, 'Je prie dans mon affliction, et qu’ai-je fait? Et des étrangers m’ont enlevé mes richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 3, 'Quel est cet homme? et qu’il soit enchaîné par ma main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 4, 'Car vous avez, Seigneur, rendu leur cœur inaccessible à la prudence; aussi ne les glorifiez-vous point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 5, 'Ils annonceront leurs châtiments à leurs amis, et leurs yeux se fondront sur le sort de leurs enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 6, 'Mais moi, Seigneur, vous m’avez rendu la fable des nations; je suis devenu leur risée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 7, 'La douleur alors a séché mes yeux; j’ai été vivement affligé de toutes parts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 8, 'Les hommes droits ont été stupéfaits de cela; faites donc que le juste l’emporte enfin sur le méchant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 9, 'Que le fidèle persévère dans sa voie, que l’homme dont les mains sont pures prenne courage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 10, 'Et vous tous, approchez, écoutez-moi; je ne trouve point en vous la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 11, 'J’ai passé mes journées à trembler, à gémir, et toutes les fibres de mon cœur ont été déchirées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 12, 'La nuit pour moi est devenue le jour; et la lumière qui s’approche me semble ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 13, 'Tout ce que j’ai à attendre c’est la terre pour demeure; ma couche est déjà étendue dans les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 14, 'J’ai appelé le trépas mon père; ma mère et ma sœur, c’est la pourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 15, 'Où donc est désormais mon espérance? Quels sont les biens que je verrai?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 16, 'Est-ce que mon espoir et mes biens descendront avec moi sous la terre? Est-ce que nous irons placés ensemble dans le sépulcre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 1, 'Et Baldad le Sauchite, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 2, 'Quand donc cesseras-tu? Contiens-toi, afin que nous parlions aussi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 3, 'Pourquoi devant toi sommes des quadrupèdes? nous muets comme');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 4, 'La colère t’emporte: eh quoi! si tu meurs, la terre sous le ciel sera-t-elle inhabitée, et les montagnes s’écrouleront-elles jusqu’à la base?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 5, 'La lumière des impies s’éteindra; leur flamme ne resplendira pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 6, 'La lumière est ténèbres en la demeure de l’impie; la lampe qui l’éclaire s’éteindra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 7, 'Que les petits s’emparent de ses richesses; que ses conseils soient dissipés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 8, 'Son pied s’est pris dans un piège; puisse le filet l’envelopper tout entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 9, 'Que des rets tombent sur lui: Dieu fortifiera ceux qui ont soif de sa destruction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 10, 'Le lacs était caché en terre; le nœud où il devait se prendre était dans le chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 11, 'Que les douleurs l’investissent et le perdent; que des ennemis l’entourent en foule,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 12, 'Lui faisant sentir les horreurs de la famine; une chute éclatante lui a été réservée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 13, 'Que les doigts de ses pieds soient rongés, la mort dévorera sa beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 14, 'Que la santé soit bannie de sa demeure; que l’ angoisse le tienne comme s’il eût commis un crime contre le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 15, 'Qu’elle habite sous sa tente pendant la nuit; qu’un feu de soufre pleuve sur sa belle demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 16, 'Au plus profond de la terre, ses racines seront desséchées, et ses fruits tomberont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 17, 'Que tout souvenir de lui périsse sur la terre, et il ne lui restera plus de nom au dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 18, 'Qu’il soit chassé de la lumière dans les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 19, 'Il ne sera pas nommé parmi son peuple, et sa famille ne lui survivra pas sous la voûte du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 20, 'Les étrangers vivront de ses biens; les derniers qui l’ont vu ont gémi, les premiers l’avaient admiré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 21, 'Telles sont les demeures du criminel; tel est le lieu de ceux qui ne connaissent point le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 1, 'Et Job, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 2, 'Jusqu’à quand fatiguerez-vous mon âme, et me tuerez-vous par vos discours? Sachez seulement que c’est le Seigneur qui m’a traité de la sorte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 3, 'Vous parlez contre moi, et vous n’avez point honte de m’opprimer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 4, 'J’ai véritablement erré, soit; l’erreur réside avec moi; j’aurais dit ce qui n’est pas à dire; ma parole s’égare et n’est pas de saison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 5, 'Cessez, car vous vous dressez contre moi; vous m’insultez par vos reproches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 6, 'Apprenez cependant que c’est le Seigneur qui m’a frappé, et qu’il a élevé contre moi des retranchements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 7, 'Voilà que je me ris de vos injures, je me tairai; car lors même que j’aurais crié, je n’obtiendrais pas de jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 8, 'Mais je suis entouré de murailles que je ne puis renverser, et le Seigneur a mis l’obscurité devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 9, 'Il m’a dépouillé de ma gloire; il a ôté la couronne que j’avais sur la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 10, 'Il m’a tiraillé dans tous les sens, et j’ai succombé; il a abattu, comme un arbre, toute mon espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 11, 'Il a déployé contre moi une colère terrible; il m’a considéré comme un ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 12, 'Ses épreuves m’ont assailli toutes ensemble; elles se sont placées en embuscade sur toutes mes voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 13, 'Mes frères se sont éloignés, ils ont reconnu des étrangers plutôt que moi; mes amis n’ont eu aucune compassion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 14, 'Mes plus proches m’ont laissé sans soins, et ceux qui savaient mon nom m’ont oublié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 15, 'Pour mes familiers mêmes et les servantes de ma maison, je suis un étranger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 16, 'J’ai appelé mon serviteur, et il n’est point venu; ma bouche suppliait;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 17, 'J’ai imploré ma femme, j’ai demandé les fils de mes concubines en les flattant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 18, 'Ils m’ont répudié pour toujours; lorsque je me relève, ils parlent contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 19, 'Ceux qui m’ont vu m’ont eu en horreur; ceux que j’avais aimés se sont déclarés mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 20, 'Mes chairs sous ma peau pourrissent; mes os sont comme entre des dents qui les rongent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 21, 'Ayez pitié de moi, ô mes amis, car c’est la main du Seigneur qui m’a touché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 22, 'Pourquoi me poursuivez-vous comme fait le Seigneur; n’êtes-vous pas rassasiés de ma chair?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 23, 'Qui donc écrirà mes paroles pour les déposer en un livre impérissable?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 24, 'Qui les gravera avec un burin sur le plomb ou sur la pierre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 25, 'Car je sais qu’il est éternel Celui qui doit être mon libérateur sur cette terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 26, 'Et faire revivre ma peau qui éprouvera ces choses; car c’est le Seigneur qui a disposé pour moi toutes ces choses');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 27, 'Dont j’ai conscience en moi-même, que mon œil a vues, et non l’œil d’un autre, et qui déjà sont accomplies en mon sein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 28, 'Et si vous demandez: Que dirons-nous contre lui? quel sujet de discours trouverons-nous en sa personne?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 29, 'Prenez garde, vous aussi, à ce qui est caché; car la colère tombera sur les méchants, et alors ils verront où est leur matière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 1, 'Et Sophar le Minéen, répondant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 2, 'Je ne croyais pas que tu répliquerais de la sorte; et vous, vous n’avez pas plus que moi le don d’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 3, 'J’écouterai la doctrine par laquelle on prétend me confondre; et l’esprit d’intelligence répondra pour moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 4, 'Ne sais-tu pas dès longtemps ces choses, depuis que l’homme a été établi sur la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 5, 'Joie des méchants, chute éclatante; plaisirs des pervers, ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 6, 'Lors même que les présents de l’impie monteraient jusqu’au ciel, et que ses sacrifices atteindraient les nuées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 7, 'Au moment où il se croira le plus affermi, il périra enfin, et ceux qui le connaissaient diront: Où est-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 8, 'On ne le voit non plus qu’un songe évanoui, et il s’est envolé comme une vision nocturne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 9, 'L’œil a regardé, et il n’est plus là; et le lieu qu’il habitait ne l’apercevra plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 10, 'Que ses fils meurent sous les coups des petits, et que ses mains allument les douleurs qui le consumeront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 11, 'Ses os seront imprégnés des vices de sa jeunesse, qui dormiront avec lui dans la poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 12, 'Le mal est doux à sa bouche, il le cachera sous sa langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 13, 'Il ne l’épargnera pas, et il ne le laissera pas perdre, et il le gardera au fond de son gosier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 14, 'Mais il ne pourra se porter secours à lui-même; ce sera en ses entrailles du venin d’aspic<ref>Sa malice sera pour lui-même un poison mortel. Quoi de plus vrai! dont il ne goûtera pas plus qu’on ne goûte une chair coriace qui ne peut être ni mâchée ni avalée.</ref>.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 15, 'Il vomira ses richesses injustement acquises; et un ange l’expulsera de la maison où il les aura amassées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 16, 'Qu’il suce le fiel des dragons; que la langue des serpents le fasse périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 17, 'Qu’il ne voie plus de lait trait au pâturage; qu’il ne mange ni beurre ni miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 18, 'Il a travaillé en vain et sans profit pour les biens');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 19, 'Car il a brisé les demeures d’une multitude d’hommes puissants; il a ravagé leurs maisons et ne les a point rétablies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 20, 'Il n’y a point de sécurité en ses possessions; il ne sera pas sauvé par les objets de sa convoitise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 21, 'Il ne restera rien de ses aliments, et ses biens ne fleuriront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 22, 'Lorsqu’il se croira comblé et rassasié, il se verra écrasé par toutes les misères qui fondront sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 23, 'I importe comment il a rempli sa panse, Dieu fera tomber sur lui le poids de sa colère et des flots de douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 24, 'Il n’échappera pas au fer et sera percé par une flèche d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 25, 'Que le trait traverse son corps; que des météores pleins d’horreurs se promènent en sa maison. Que les terreurs pèsent sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 26, 'Que les ténèbres l’enveloppent toujours; qu’une flamme le dévore; que l’étranger ruine sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 27, 'Que le ciel dévoile ses iniquités; que la terre s’élève contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 28, 'Que la perdition entraîne enfin après elle sa maison; que le jour de la colère se lève sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 29, 'Tel est le sort que le Seigneur réserve à l’impie; telle est la part de richesses que lui donnera Celui qui voit tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 1, 'Or Job, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 2, 'Écoutez, écoutez mes paroles, afin que de telles consolations ne me viennent plus de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 3, 'Supportez-moi, et je parlerai; ensuite vous ne rirez plus de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 4, 'Quoi donc! mon épreuve vient-elle de l’homme? Comment retiendrai-je ma douleur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 5, 'Lorsque vous m’aurez examiné à fond, vous serez ébahis, et de vos mains vous vous couvrirez les joues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 6, 'Car, si je recueille mes souvenirs, je n’ai eu que zèle pur, et les douleurs affligent mes chairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 7, 'Pourquoi les impies vivent-ils et vieillissent-ils au sein de la richesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 8, 'Leur famille est nombreuse au gré de leurs désirs; ils ont leurs enfants sous les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 9, 'Leurs maisons prospèrent; chez eux nulle crainte, car le fouet du Seigneur n’est point sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 10, 'Pas d’avortement parmi leurs génisses; leurs bêtes pleines portent sans mal. (S. Grég.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 11, 'Eux-mêmes se perpétuent comme des brebis qui se reproduisent sans fin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 12, 'Leurs enfants dansent au son de la harpe et de la cythare, et ils se complaisent au chant des cantiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 13, 'Leur vie s’écoule au milieu des biens; puis ils se rendorment dans le repos du sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 14, 'Cependant ils ont dit au Seigneur: Détourne-toi de nous; je ne veux point connaître tes voies. Qu’est-ce donc que le Tout-Puissant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 15, 'Pour que nous le priions? Quel profit aurons-nous à aller au-devant de lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 16, 'Les mains pleines de richesses, le Seigneur, disent-ils, ne surveille pas les œuvres des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 17, 'Mais la lampe des impies s’éteint; et des catastrophes tombent sur eux; les douleurs leur sont envoyées par la colère de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 18, 'Ils seront alors comme de la paille qu’entraîne le vent, ou comme la poussière emportée par le tourbillon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 19, 'Que les richesses du méchant échappent à ses fils; le Seigneur le rétribuera, et il saura pourquoi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 20, 'Que ses yeux voient sa propre immolation; qu’il ne soit pas épargné par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 21, 'Car sa volonté mauvaise était avec lui dans sa maison; et le nombre de ses mois a été tranché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 22, 'N’est-ce pas le Seigneur qui enseigne l’intelligence et la science? n’est-ce pas lui qui juge les homicides?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 23, 'Tel mourra dans la plénitude de sa force, complétement heureux et bien portant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 24, 'Les entrailles pleines de graisse, et regorgeant de moelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 25, 'Un autre finit en l’amertume de son âme, n’ayant jamais rien mangé de bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 26, 'Ils dorment ensemble sous la terre; la pourriture les enveloppe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 27, 'Je sais votre hardiesse à m’accuser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 28, 'Ainsi vous demanderez: Où donc est la maison du chef? Qu’est devenue la tente qui abritait des criminels?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 29, 'Interrogez les voyageurs, et ne faussez pas leurs témoignages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 30, 'Ils vous diront que le méchant est élevé pour sa perte, et qu’il sera entraîné le jour de la vengeance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 31, 'Qui donc montrera en face ses voies et ce qu’il a fait? qui se chargera de les punir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 32, 'On le portera au lieu de sépulture; et il a veillé lui-même à la construction de sa tombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 33, 'Les cailloux du torrent ont été doux pour lui; après lui tout le monde s’en ira, de même qu’une multitude innombrable l’a précédé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 34, 'Comment donc me consolez-vous en vain? Car vous n’avez apporté aucun soulagement à mes maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 1, 'Or Éliphaz le Thémanite, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 2, 'N’est-ce point le Seigneur qui enseigne l’intelligence et la science?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 3, 'Qu’importe au Seigneur si tu as été irréprochable en tes œuvres? qu’a-t-il besoin de l’innocence de tes voies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 4, 'Est-ce qu’il craindra tes reproches, et viendra avec toi au jugement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 5, 'Est-ce que ta méchanceté n’est pas immense? est-ce que tes péchés ne sont pas innombrables?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 6, 'Tu as mal à propos exigé des gages de tes frères; tu as enlevé le vêtement des nus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 7, 'Tu n’as point abreuvé d’eau ceux qui avaient soif; et tu as ôté le morceau de pain à ceux qui avaient faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 8, 'Tu as fait acception des personnes: tu as reçu les grands de la terre,.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 9, 'Tu as renvoyé vides les veuves, tu as maltraité les orphelins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 10, 'Voilà pourquoi des filets t’ont enveloppé, et une guerre imprévue s’est attaquée à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 11, 'Ta lumière s’est changée en ténèbres, et, tandis que tu étais endormi, l’eau t’a submergé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 12, 'Celui qui réside au plus haut des cieux ne surveille-t-il plus? n’a-t-il pas toujours humilié les superbes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 13, 'Et tu avais dit: Que sait le Tout-Puissant? est-ce qu’il peut juger ce qui est dans les ténèbres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 14, 'Une nuée le cache, et nul ne le verra, et il parcourt le cercle du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 15, 'Tiendras-tu, toi aussi, la route antique, qu’ont suivie les faux justes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 16, 'Qui ont été enlevés avant le temps? Leur séjour est devenu un fleuve débordé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 17, 'Ils ont dit: Que nous fera le Seigneur? et qu’est-ce que le Tout-Puissant fera tomber sur nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 18, 'Et c’est lui qui a comblé de biens leurs maisons! Mais le conseil des méchants est loin de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 19, 'Les justes, en les voyant, ont ri; l’innocent les a raillés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 20, 'Bientôt leur fortune sera évanouie, et le feu en dévorera les restes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 21, 'Sois donc courageux; car, si tu patientes, tu recueilleras des fruits délicieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 22, 'Reçois la loi de sa bouche; fais entrer ses paroles en ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 23, 'Si tu te convertis, si tu t’humilies devant le Seigneur, et que tu chasses l’iniquité loin de ta mai son,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 24, 'Ta maison sera fondée sur la pierre, et tes ruisseaux rouleront de l’or comme en Ophir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 25, 'Le Tout-Puissant sera ton auxiliaire contre tes ennemis, et te rendra pur comme l’argent qui a passé par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 26, 'Alors tu seras plein de confiance devant le Seigneur, et tu regarderas le ciel avec joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 27, 'Lorsque tu le prieras, il t’exaucera, et il te donnera d’accomplir tes vœux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 28, '11 te réédifiera une demeure de justice, et la lumière luira sur tes voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 29, 'Parce que tu te seras humilié et que tu diras: L’impie s’est enorgueilli. Dieu sauvera celui dont les yeux sont humbles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 30, 'Il protégera l’innocent, et tu seras sauvé par la pureté de tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 1, 'Et Job, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 2, 'Je sais, moi, que je puis me justifier dans mes maux et que mes souffrances surpassent mes gémissements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 3, 'Qui pourrait me dire où je le trouverais? j’irais jusqu’à Lui,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 4, 'Je plaiderais ma cause, et ma bouche serait pleine de bonnes raisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 5, 'Puissé-je apprendre les réponses qu’il me ferait! puissé-je ouïr ce qu’il me dirait!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 6, 'Je verrai s’il vient à moi avec sa force immense, et s’il me traite ou non selon ses menaces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 7, 'Car la vérité, les justes reproches procèdent de lui; puisse-t-il faire triompher ma cause!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 8, 'Si je vais en avant, je me perds sans le trouver; si je vais en arrière, je ne le vois point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 9, 'Il passe à gauche, et je ne le saisis pas; il tourne à droite, et je ne le vois point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 10, 'Mais il connaît ma voie; il m’a éprouvé comme on éprouve l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 11, 'Je cheminerai en ses commandements; car j’ai gardé ses voies, et je ne m’en suis point écarté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 12, 'De ses commandements je n’en ai rien omis; j’ai recueilli dans mon sein toutes ses paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 13, 'Et, puisqu’il m’a ainsi jugé, qui le contredira? Ce qu’il a voulu, il l’a fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 14, 'À cause de cela, j’ai été rempli de crainte à son sujet, et, repris, j’ai été plein de sollicitude pour lui obéir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 15, 'Et néanmoins je suis effrayé devant lui; je le considère et je tremble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 16, 'Dieu m’a amolli le cœur, et le Tout-Puissant m’a troublé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 17, 'J’ignorais que les ténèbres dussent venir, et une nuit sombre s’est étendue devant moi pour me le cacher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 1, 'Pourquoi les moments ont-ils été ignorés du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 2, 'Quand les impies ont franchi la barrière pour ravir les troupeaux et les bergers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 3, 'Et ont emmené l’âne des orphelins; ils ont pris pour gage l’âne de la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 4, 'Ils ont fait dévier le faible de la voie de la justice; tandis que les doux de la terre ensemble se sont cachés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 5, 'Ils se sont précipités comme des ânes dans un champ, débouchant du désert en leur ordre habituel. Ils aiment à donner leur pain aux jeunes hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 6, 'Ils ont moissonné avant la saison le champ qui ne leur appartenait pas. Le pauvre a cultivé les vignes des impies sans avoir aliment ni salaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 7, 'Ceux-ci ont forcé des nus à passer des nuits sans vêtements; ils leur ont ôté la couverture de leurs corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 8, 'Ils les ont réduits à recevoir la pluie des montagnes, et, faute d’abri, à se réfugier dans les rochers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 9, 'Ils ont arraché l’orphelin à la mamelle; ils ont humilié celui qui était tombé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 10, 'Ils ont injustement fait dormir les autres sans couverture; ils ont pris aux affamés leur bouchée de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 11, 'Ils ont, les iniques, épié les voyageurs en des défilés; ils n’ont point connu la voie de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 12, 'Plusieurs ont été chassés de leurs villes et de leurs propres maisons; l’âme des enfants a poussé de grands gémissements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 13, 'Pourquoi le Seigneur n’a-t-il point fait tomber sur eux son regard de vengeance? Tandis que les impies étaient sur la terre, ils ont ignoré la sagesse, ils n’ont point connu les voies de la justice, ils n’ont pas suivi ses sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 14, 'Dieu connaît les œuvres de ceux qu’il a abandonnés aux ténèbres, et la nuit ils seront comme le voleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 15, 'L’œil de l’adultère a guetté l’heure de l’obscurité, disant: Nul ne me soupçonnera; et il s’est voilé le visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 16, 'Dans les ténèbres il a percé les maisons; le jour ils se sont enfermés, et ils ne connaissent point la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 17, 'Car le matin est pour eux comme l’ombre de la mort; et ils sentiront les frayeurs de l’ombre de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 18, 'Ils fuient rapidement comme s’ils glissaient sur l’eau. Maudite soit leur part sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 19, 'Que leurs rejetons apparaissent desséchés sur le sol; car ils ont ravi la gerbe de l’orphelin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 20, 'Dieu, ensuite, s’est souvenu de leur péché; ils se sont évanouis comme la vapeur de la rosée. Puissent-ils être rétribués selon leurs œuvres! que tout homme inique soit brisé comme le bois pourri!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 21, 'Car il n’a fait aucun bien à la femme stérile; il n’a point eu compassion de la femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 22, 'Il a renversé les faibles dans sa fureur; c’est pourquoi, en se levant, il ne se tient point assuré de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 23, 'S’il tombe malade, qu’il n’espère point de guérison; mais qu’il succombe au mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 24, 'Car il a maltraité bien des gens en son orgueil; il se flétrira donc comme la manne sous l’ardente chaleur, ou comme un épi tombé de sa tige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 25, 'Qui donc pourra dire que j’ai menti, et qui réduira mes paroles à néant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 1, 'Or Baldad le Sauchite, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 2, 'Que peut-on attendre, sinon des sujets de crainte, de la part de Celui qui fait tout au plus haut des cieux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 3, 'Que nul ne s’imagine que les pirates sont laissés tranquilles sur qui donc ses escadrons vengeurs ne s’abattront-ils pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 4, 'Comment donc un mortel sera-t-il juste aux yeux du Seigneur? Et quel fils de la femme sera pur devant lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 5, 'S’il le commande à la lune, elle cesse de luire; et les étoiles ne sont point pures devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 6, 'Combien moins l’homme qui n’est que pourriture, le fils de l’homme, ce vermisseau!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 1, 'Or Job, reprenant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 2, 'À quoi t’adjoins-tu? qui crois-tu devoir secourir? n’est-ce pas celui dont la puissance est infinie, dont le bras est tout-puissant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 3, 'Qui veux-tu conseiller? n’est-ce pas celui en qui est toute sagesse? A qui offres-tu tes services? n’est-ce pas à celui dont la force est immense?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 4, 'À qui adresses-tu tes paroles? n’est-ce pas à celui de qui est sorti le souffle qui s’exhale de ton sein?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 5, 'Est-ce que les géants enfanteront encore de dessous les eaux ainsi que leurs voisins?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 6, 'L’enfer est nu devant les yeux du Seigneur, et la perdition n’a pas de voile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 7, 'Il a étendu le septentrion sur le vide; il a suspendu la terre sur le néant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 8, 'Il enchaîne la pluie dans ses nuées, et les nuages cessent de se fendre sous lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 9, 'C’est lui qui tient affermie la face de son trône qu’il voile de ses nuées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 10, 'Son commandement trace un cercle sur la surface des eaux, jusqu’à l’endroit où la lumière finit avec les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 11, 'C’est lui qui a fondé les colonnes du ciel, et à ses reproches elles ont été saisies d’épouvante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 12, 'Sa force a calmé les flots, et sa science, le monstre marin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 13, 'Les parvis mêmes du ciel le redoutent; d’un seul mot il a tué le dragon apostat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 14, 'C’est là une partie de ses voies, et ce que nous avons ouï n’est qu’une goutte de sa parole; mais la force de son tonnerre, lorsqu’il la fera entendre, qui pourra la supporter?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 1, 'Et Job, ajoutant à ce préambule, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 2, 'Vive le Seigneur qui m’a ainsi jugé, le Tout-Puissant qui a rempli mon âme d’amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 3, 'Aussi longtemps que je conserverai le souffle, que l’esprit qui vient de Dieu sera dans mes narines,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 4, 'Mes lèvres ne laisseront échapper aucune parole déréglée, mon âme ne concevra aucune pensée inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 5, 'Dieu me garde jusqu’à la mort de vous dire justes; je ne me dépouillerai point de mon innocence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 6, 'M’attachant à la justice, je ne la quitterai point; car je n’ai pas conscience d’avoir fait rien de mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 7, 'Aussi mes ennemis seront-ils renversés comme des impies; et ceux qui s’élèvent contre moi périront comme des pervers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 8, 'Car quelle est l’espérance de l’impie qui persiste en son impiété? Sera-t-il sauvé, lui aussi, en s’appuyant sur le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 9, 'Ou Dieu exaucera-t-il sa prière? et, aux jours de l’adversité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 10, 'Aura-t-il quelque assurance devant lui, ou, s’il fait semblant de l’invoquer, sera-t-il écouté?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 11, 'Mais je vais vous apprendre ce qui est dans la main du Seigneur, quelle chose a le Tout-Puissant, je ne mentirai point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 12, 'Vous le savez bien tous; vous accumulez vanité sur vanité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 13, 'Voici le partage que le Seigneur réserve aux impies; voici l’héritage que les puissants de la terre recevront du Tout-Puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 14, 'Si leurs fils sont nombreux, ils périront par l’épée, ou, s’ils arrivent à âge d’hommes, ils seront des mendiants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 15, 'Ceux qui leur survivront périront comme eux; nul n’aura pitié de leurs veuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 16, 'Si l’impie recueille de l’argent comme des monceaux de terre, s’il amasse de l’or abondant comme l’argile,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 17, 'Les justes se les approprieront; les hommes sincères possèderont ses richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 18, 'Car sa maison aura disparu comme ce qui est mangé par la teigne, comme une toile d’araignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 19, 'Il se sera couché riche, c’est fini pour lui; il a ouvert les yeux, et déjà il n’est plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 20, 'Les douleurs ont fondu sur lui comme un torrent, pendant la nuit il a été surpris par un sombre tourbillon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 21, 'Le vent brûlant l’enlève, et il passe, et il le fait tourbillonner loin de sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 22, 'Et il tombera sur lui, et il ne l’épargnera pas, quoi qu’il fasse pour échapper à sa violence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 23, 'À son sujet on battra des mains dans la ville qu’il habitait, et les sifflets pleuvront sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 1, 'Il y a des lieux où naît l’argent, d’autres où l’or est affiné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 2, 'Le fer se tire du sol, et l’airain est extrait de mines semblables à la pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 3, 'L’homme a mis un terme aux ténèbres; il atteint les limites de toutes choses, et jusqu’à la pierre, ensevelie dans les ténèbres et l’ombre de la mort,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 4, 'Jusqu’à ce torrent souterrain qui sépare de la terre, au delà duquel sont ceux qui, ayant oublié la voie de la justice, sont tombés et ont été rejetés du reste des mortels.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 5, 'La terre d’où naissait le pain a été tourmentée comme par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 6, 'Ses rochers sont le lieu où l’on trouve le saphir, et dans ses glèbes remuées se trouve l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 7, 'L’oiseau lui-même n’en a pas connu la route; l’œil du vautour ne l’a point aperçue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 8, 'Les fils des superbes n’y ont point cheminé; le lion n’a point passé par elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 9, 'L’homme a étendu sa main sur la pierre la plus dure, et il a bouleversé les montagnes de fond en comble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 10, 'Il a fendu les tourbillons des fleuves, et mon œil a vu tout ce qu’il y a de précieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 11, 'L’homme a exploré le fond des fleuves, et il a mis au jour leurs entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 12, 'Mais la sagesse où a-t-elle été trouvée? en quel lieu réside-t-elle?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 13, 'L’homme n’en sait pas le chemin, et on ne la trouve pas parmi les mortels.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 14, 'L’abîme a dit: Elle n’est point en moi; la mer a dit Elle n’est pas avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 15, 'On ne l’obtiendra point au prix de trésors; elle ne s’échange pas pour de l’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 16, 'On ne la mettra point dans la balance avec de l’or d’Ophir, des saphirs et des onyx.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 17, 'Ni l’or ni le cristal ne la vaudront; on ne l’échangera pas contre des vases d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 18, 'Auprès d’elle les choses éclatantes et hautes seront mises en oubli; recherche la sagesse de préférence à ce que tu as de plus cher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 19, 'On ne lui comparera pas la topaze de l’Éthiopie; on ne la mettra pas dans la balance avec de l’or pur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 20, 'Où la sagesse a-t-elle été trouvée? quel est le lieu où est l’intelligence?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 21, 'Elle est inconnue à tous les hommes; elle est cachée aux oiseaux du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 22, 'La perdition et la mort ont dit: Nous avons entendu parler de sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 23, 'Dieu seul connaît bien sa voie; seul il sait le lieu où elle est.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 24, 'Car il voit, lui, tout ce qui est sous le ciel; il connaît toutes choses sur la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 25, 'Tout ce qu’il a créé, la force des vents, et la mesure des eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 26, 'Aux jours de la créature, après avoir tout considéré, il a tout compté; et il a tracé une route aux ébranlements du tonnerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 27, 'Alors il a vu la sagesse, et il l’a proclamée; la tenant en sa disposition, il en a sondé la profondeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 28, 'Et il a dit à l’homme: La sagesse, c’est la piété; et s’abtenir du mal, c’est la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 1, 'Et Job, ajoutant à ce qui précède, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 2, 'Qui me rendra les jours d’autrefois, les temps où Dieu me gardait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 3, 'Lorsque sa lampe brillait sur ma tête; quand, à sa lumière, je marchais dans les ténèbres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 4, 'Lorsque j’étais chargé de biens, et affermi dans mes voies et que Dieu veillait sur ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 5, 'Alors j’étais comblé de richesses, entouré de mes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 6, 'Alors mes sentiers ruisselaient de beurre, et mes collines de lait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 7, 'Alors j’entrais dès l’aurore en la ville; un siége m’était porté dans la rue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 8, 'Les jeunes gens qui m’apercevaient se cachaient; et tous les anciens restaient debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 9, 'Et les riches cessaient de parler, et ils se mettaient un doigt sur la bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 10, 'Attentifs à mes paroles, ils me félicitaient; puis leur langue était comme collée à leur gosier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 11, 'L’oreille qui avait ouï me béatifiait; l’œil qui m’avait vu se baissait devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 12, 'Car j’avais délivré le pauvre des mains du puissant; j’avais protégé l’orphelin sans appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 13, 'Les bénédictions des abandonnés venaient sur moi, et la bouche de la veuve me bénissait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 14, 'Je m’étais revêtu de justice; je m’étais enveloppé d’équité, comme d’un manteau double.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 15, 'J’étais l’œil de l’aveugle, le pied du boiteux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 16, 'J’étais le père des faibles; j’examinais des causes que je ne connaissais pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 17, 'Aussi ai-je brisé les mâchoires de l’injuste; j’ai arraché de ses dents la proie qu’il avait saisie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 18, 'Et j’ai dit: Mon âge se prolongera comme celui du palmier, et je vivrai longtemps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 19, 'Ma racine s’étend le long des eaux; et la rosée restera toute la nuit sur mes branches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 20, 'Ma gloire sera toujours nouvelle, et mon arc se fortifiera dans ma main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 21, 'Ceux qui m’avaient entendu se taisaient après mon avis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 22, 'Ils n’ajoutaient rien à mes paroles, et ils se réjouissaient quand je leur avais parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 23, 'Comme le cèdre altéré attend la pluie, de même ils attendaient mes discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 24, 'Lorsque je riais avec eux, ils n’y pouvaient croire, et l’éclat de mon visage n’en était pas amoindri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 25, 'Je dirigeais leur voie, et m’asseyais en prince au milieu d’eux; j’habitais comme un roi au milieu de ses gardes, à la manière d’un consolateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 1, 'Maintenant les plus chétifs me raillent; maintenant à leur tour ils me réprimandent ces gens dont je méprisais les pères, ne les estimant pas dignes d’être avec les chiens de mes troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 2, 'Qu’était pour moi la force de leurs mains? l’aisance avait fui loin d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 3, 'Race stérile, indigente et affamée; à peine échappée de la détresse, du désert ou des angoisses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 4, 'Qui se jetait sur les herbes des vallées, dont l’herbe des pauvres était la nourriture abjecte, dénuée de tout ce qui est bon, et rongeant les racines des arbres, tant leur faim était grande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 5, 'Ils se sont élevés contre moi, les larrons,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 6, 'Dont la demeure était dans les cavernes des rochers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 7, 'Dont les cris se mêlaient aux échos agrestes, et qui vivaient près des vignes sauvages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 8, 'Fils d’insensés, d’êtres dégradés, dont le nom et l’honneur sont éteints sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 9, 'Je suis maintenant pour eux une cythare; je suis le sujet de leurs propos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 10, 'Je suis pour eux un objet d’horreur; ils se tiennent loin de moi, et ils n’ont pas épargné leurs crachats à mon visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 11, 'Car le Seigneur a ouvert son carquois pour me frapper; alors ils ont rejeté le frein que leur imposait ma présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 12, 'Ils se sont levés contre la prospérité de mon rameau; ils ont étendu le pied, ils ont dirigé contre moi leur sentier de perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 13, 'Ils ont détruit mes voies, ils m’ont dépouillé de ma robe; le Seigneur m’avait pris pour but de ses flèches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 14, 'Il m’a traité comme il lui a plu; je suis brisé de douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 15, 'Mes souffrances se renouvellent sans cesse; mon espoir s’est envolé comme le vent, et mon salut comme une nuée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 16, 'Mon âme est en moi toute languissante; les jours d’affliction me tiennent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 17, 'La nuit, mes os s’entre-choquent, et mes nerfs se dissolvent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 18, 'Dieu m’a saisi avec force par mon manteau; il m’a étreint comme le collier de ma tunique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 19, 'Vous m’avez estimé non plus que de la boue, ô Seigneur; une part de moi est déjà cendre et terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 20, 'J’ai crié vers vous, et vous ne m’avez point écouté, et eux, ils se sont tenus près de moi, et ils m’ont examiné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 21, 'Et ils m’ont insulté sans miséricorde, et vous m’avez châtié d’une main puissante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 22, 'Vous m’avez livré aux douleurs, et vous m’avez rejeté loin du salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 23, 'Car je sais que la mort me broiera, et que la terre est la demeure de tout être mortel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 24, 'Plût à Dieu que je pusse me porter secours à moi-même ou qu’un autre le fit à ma prière!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 25, 'Moi qui ai pleuré sur tous les affligés, qui ai gémi sur tout homme dans la détresse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 26, 'Moi qui ne m’appliquais qu’au bien; voilà que sur moi sont venus les jours de malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 27, 'Mes entrailles bouillonnent, et rien ne les calme; les jours de la pauvreté ont fondu sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 28, 'Je cheminais en gémissant sans pouvoir me retenir; et je me suis arrêté poussant des cris au milieu du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 29, 'Je suis devenu frère des oiseaux plaintifs, compagnon des autruches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 30, 'J’ai la peau noircie, et les os brûlés par la fièvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 31, 'Ma cythare a fait place aux pleurs, et mes chants aux sanglots.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 1, 'J’avais fait un pacte avec mes yeux pour ne pas même penser à une vierge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 2, 'Quelle part me réserverait d’en haut le Seigneur? quel héritage devrais-je attendre du Tout-Puissant, du plus haut des cieux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 3, 'Malheur, perdition à l’injuste; expulsion pour celui qui fait le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 4, 'Est-ce que le Seigneur ne verra point mes voies? est-ce qu’il ne comptera point mes pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 5, 'Si j’avais été le compagnon des moqueurs, si mes pieds avaient couru à la tromperie!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 6, 'Mais je suis resté dans la juste balance, et le Seigneur connaît mon innocence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 7, 'Si mon pied s’est jamais écarté de la voie, si mon cœur s’est laissé entraîner par mes yeux, si mes mains ont touché des présents,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 8, 'Que d’autres consomment ce que j’ai semé; que sur la terre je devienne sans racines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 9, 'Si mon cœur a convoité la femme d’autrui, si j’ai fait le guet à ses portes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 10, 'Que ma femme plaise à un autre homme; que mes enfants soient humiliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 11, 'Car c’est une passion damnable, dans son emportement, que de souiller la femme de son prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 12, 'C’est un feu qui dévore tout, et qui brûle ce qu’il touche jusqu’à la racine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 13, 'Si j’avais faussé le jugement que je rendais sur mon serviteur ou ma servante, lorsqu’ils avaient eu recours à ma justice,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 14, 'Que ferais-je quand le Seigneur à son tour me jugera? qu’aurais-je à lui répondre s’il me visitait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 15, 'Est-ce que ceux que j’avais à juger n’avaient pas été, comme moi, conçus en des entrailles? N’ont-ils pas été, comme moi, portés dans le sein maternel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 16, 'Aussi les pauvres ont-ils toujours trouvé chez moi ce qui leur manquait, et je n’ai point fait verser des larmes à l’œil de la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 17, 'Si j’ai mangé seul ma bouchée, si je n’en ai point fait part à l’orphelin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 18, 'Si dès ma jeunesse je ne les ai pas nourris comme un père, si du sein de ma mère je n’ai pas eu soin d’eux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 19, 'Si j’ai méprisé l’homme nu qui périssait, et ne l’ai point vêtu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 20, 'Si les indigents ne m’ont point béni, si leurs épaules n’ont pas été réchauffées par la toison de mes agneaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 21, 'Si j’ai levé la main sur le pupille confiant en la supériorité de ma force,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 22, 'Que mon épaule se déboîte; que mon bras soit broyé au-dessous du coude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 23, 'En vérité, la crainte du Seigneur m’a paralysé; je n’aurais pu supporter ses reproches,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 24, 'Si j’avais mis ma confiance dans l’or, si j’avais mis mon espoir dans les pierres précieuses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 25, 'Si je m’étais réjoui d’avoir possédé de grandes richesses, et pu poser ma main sur des trésors innombrables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 26, 'Ne voyons-nous point le soleil dans son éclat s’éclipser, et la lune décroître? car ils n’ont rien d’euxmêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 27, 'Si donc mon cœur en secret s’est laissé séduire, et si j’ai baisé ma main en la portant à ma bouche,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 28, 'Que cette iniquité me soit gravement imputée; car alors j’ai menti au Seigneur Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 29, 'Et si je me suis réjoui de la chute de mes ennemis; et si j’ai dit en mon cœur: Bien!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 30, 'Puisse mon oreille entendre que l’on me maudit, et dans mon affliction que le peuple murmure contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 31, 'Si mes servantes ont dit souvent: Qui nous accordera de nous rassasier de sa chair? tandis que j’usais d’une grande bonté;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 32, 'Car je n’ai jamais laissé l’étranger passer la nuit en plein air, et ma porte était ouverte à tout venant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 33, 'Si, ayant péché involontairement, j’ai caché mon péché:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 34, 'Car je n’étais point retenu par la honte de l’avouer devant la multitude; si j’ai souffert que le pauvre sortit de ma maison le sein vide,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 35, 'Qui me donnera quelqu’un qui m’écoute? Si je n’ai point eu crainte de la main du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 36, 'Si, pour lire le titre que j’avais contre autrui, j’en ai ceint mes épaules comme d’une couronne;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 37, 'Si je ne l’ai point remis après l’avoir déchiré, sans rien exiger de mon débiteur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 38, 'Si jamais la terre a gémi contre moi, si les sillons tous ensemble ont pleuré;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 39, 'Si j’ai seul consommé ses fruits sans les payer, si en recevant d’injustes tributs j’ai affligé l’âme des possesseurs de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 40, 'Que les champs au lieu de froment ne produisent pour moi que des orties, et, au lieu d’orge, que des ronces. Et Job cessa de parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 1, 'Et les trois amis de Job s’abstinrent de lui répondre, car Job était juste devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 2, 'Et Éliu, fils de Barachiel le Buzite, de la famille de Ram, en la terre d’Ausis, se courrouça, et il entra, contre Job, en une violente colère, parce qu’il s’était présenté comme juste devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 3, 'Et il ne fut pas moins irrité contre les trois amis, parce qu’ils ne pouvaient répondre rien qui confondit Job après l’avoir d’abord jugé impie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 4, 'Et Éliu avait différé de répondre à Job, car les trois hommes étaient plus que lui avancés en âge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 5, 'Mais, lorsqu’il vit que nulle réponse ne sortait de leur bouche, il s’emporta.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 6, 'Et Éliu, fils de Barachiel le Buzite, prenant la parole, dit: Je suis le plus jeune; vous êtes mes anciens; voilà pourquoi j’ai gardé le silence, craignant de vous exposer ma science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 7, 'Et je me suis dit: Ce n’est point l’âge qui parle, quoiqu’au nombre des années on accorde la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 8, 'Mais l’esprit réside parmi les mortels, et le souffle du Tout-Puissant est ce qui les instruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 9, 'Les anciens ne sont point sages, les vieillards ne savent pas le jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 10, 'Voilà pourquoi j’ai dit: Écoutez-moi, et je vais vous déclarer ce que je sais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 11, 'Écoutez mes paroles, car je ne cesserai pas que vous n’ayez sondé les paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 12, 'Et j’ai fait attention à ce que vous disiez, et voilà que personne d’entre vous n’a pu répondre aux paroles de Job et les réfuter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 13, 'Je ne voulais pas que vous disiez: Nous adjoignant au Seigneur, nous avons trouvé la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 14, 'Et vous avez permis à cet homme de tenir le langage qu’il a tenu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 15, 'Ils ont été frappés de stupeur, ils n’ont rien trouvé à répondre, ils ont laissé tomber leurs propres arguments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 16, 'J’ai attendu, je n’ai rien dit; et ils demeuraient immobiles sans répliquer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 17, 'Et Éliu, continuant, s’écria: Eh bien, je parlerai!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 18, 'Car je suis plein de paroles; l’esprit en mon sein se consume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 19, 'Ma poitrine est comme une outre close, où bouillonne du vin nouveau; elle ressemble à un soufflet de forge qui éclate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 20, 'Je parlerai pour me soulager un peu; j’ouvrirai mes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 21, 'Je ne craindai point l’homme; je ne me laisserai intimider par aucun mortel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 22, 'Il n’est point de front qui m’impose; s’il en est autrement, que les vers me dévorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 1, 'Cependant, Job, écoute mes paroles, entends mon discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 2, 'Voilà que j’ai ouvert la bouche et que ma langue se meut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 3, 'La pureté de mon cœur se verra en mes paroles; mes lèvres ne laisseront passer que des pensées pures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 4, 'C’est l’Esprit divin qui m’a formé; le souffle du Tout-Puissant m’a instruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 5, 'Tu me répondras si tu le peux; attends, et tenonsnous face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 6, 'Tu es comme moi fait de boue, nous provenons du même créateur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 7, 'La crainte de moi ne te troublera point; ma main ne te sera pas pesante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 8, 'Mais tu as dit à mes oreilles, j’ai ouï le bruit de tes paroles, tu as dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 9, 'Je suis pur et sans péché, je suis irréprochable; je n’ai rien fait de mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 10, 'C’est Dieu qui a cherché une accusation contre moi, il m’a regardé comme un ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 11, 'Il a mis mon pied dans une entrave, il a gardé toutes mes voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 12, 'Mais comment peux-tu dire: Je suis juste, et Dieu ne m’a pas écouté? Car, te dirai - je: Éternel est celui qui est au-dessus des humains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 13, 'Et tu as dit: Pourquoi Dieu n’a-t-il pas écouté un seul mot de ma défense?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 14, 'Le Seigneur parle une fois ou deux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 15, 'En nos songes ou dans nos méditations nocturnes, à l’heure où les hommes, assoupis sur leur couche, ressentent une terreur surnaturelle:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 16, 'Il éclaire leur esprit, il les effraie par des visions redoutables;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 17, 'Afin de les détourner de l’iniquité, et de préserver leur corps de la chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 18, 'Il détourne la mort de leurs âmes et les empêche de succomber dans le combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 19, 'Il les reprend aussi dans la maladie sur leur couche et engourdit tous leurs os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 20, 'Et l’homme ne peut goûter d’aucun aliment, et son âme désirera la nourriture,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 21, 'Jusqu’à ce que ses chairs pourrissent, et que les os exténués se montrent à nu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 22, 'Son âme s’est approchée de la mort, et sa vie de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 23, 'Mais y eût-il là mille anges exterminateurs, pas un seul ne le blessera, si son cœur songe à se convertir au Seigneur, s’il confesse à un autre homme son crime, et découvre sa folie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 24, 'Et Dieu l’empêchera de tomber dans la mort; il renouvellera son corps comme l’enduit d’un mur; il remplira ses os de moelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 25, 'Il lui rendra les chairs délicates comme celles d’un enfant; il lui rendra sa virilité parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 26, 'Et l’homme priera le Seigneur, et ses prières seront exaucées; et il viendra le visage joyeux s’expliquer devant lui; et Dieu rendra sa justice à l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 27, 'Alors il se fera des reproches en lui-même, disant: Qu’ai-je fait? Je n’ai point été puni comme le méritaient mes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 28, 'Mon Dieu, préservez mon âme d’entrer dans la perdition, et ma vie verra la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 29, 'Voilà donc ce que, de trois manières, le Tout-Puissant fait pour chaque homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 30, 'Et il a arraché mon âme à la mort, afin qu’à la lumière ma vie chante les louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 31, 'Écoute, Job, écoute-moi; garde le silence; c’est moi qui parlerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 32, 'Cependant si tu as des raisons à donner, répondsmoi; parle, je veux ta justification.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 33, 'Sinon écoute, garde le silence, et je t’instruirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 1, 'Et Éliu, continuant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 2, 'Écoutez-moi, sages; prêtez l’oreille, vous qui avez la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 3, 'Car l’oreille juge les paroles comme le gosier goûte les aliments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 4, 'Choisissons pour nous ce qui est juste; reconnaissons entre nous ce qui est bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 5, 'Job a dit: Je suis juste, le Seigneur m’a exclu du jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 6, 'Il a faussé mon arrêt, le trait a été violent sans que j’eusse commis d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 7, 'Quel homme, autant que Job, boit le blasphème comme l’eau?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 8, 'Il n’a point péché, dit-il, ni commis d’impiété; il n’a rien eu de commun avec ceux qui font le mal; il n’a point marché avec les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 9, 'Ne dis pas ainsi qu’il n’y a pas de justice qui s’exerce envers l’homme, point de justice pour lui de la part de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 10, 'C’est pourquoi, vous qui êtes sages en votre cœur, soyez attentifs; puissé-je n’être point impie devant le Seigneur, et ne point torturer la justice devant le ToutPuissant!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 11, 'Qu’il rétribue chacun selon ses œuvres, et il saura bien trouver tout homme dans sa voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 12, 'Penses-tu, Job, que le Seigneur fasse des choses injustes, et que le Tout-Puissant fausse la justice, lui qui a créé la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 13, 'Qui donc a fait la terre sous le ciel, et tout ce qu’elle contient?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 14, 'S’il lui plaisait de s’abstenir, de retenir son souffle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 15, 'Toute chair, au même instant, périrait; tout homme retournerait à la terre dont il a été formé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 16, 'S’il ne t’a pas averti, écoute ce que je vais dire; que tes oreilles le recueillent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 17, 'Considère que Celui qui déteste les pervers, qui extermine les méchants, est la justice éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 18, 'Est-ce un impie, celui qui dit au roi: Tu pèches; et aux grands: Vous êtes au comble de l’impiété?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 19, 'Celui-là n’a point égard aux grandeurs, il ne sait point rendre aux puissants des honneurs injustes, ni être ébahi devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 20, 'A crier, à prier un homme, ceux-ci n’obtiendront que des choses vaines; car ils ont été iniques et ils ont dédaigné le pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 21, 'Lui seul voit les œuvres des hommes; rien de ce qu’ils font ne lui est caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 22, 'Il n’est point de lieu où les ouvriers d’iniquité puissent se soustraire à ses regards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 23, 'Il ne s’y prendra pas à deux fois pour juger un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 24, 'Le Seigneur surveille tout; il conçoit une multitude innombrable de merveilles incompréhensibles et glorieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 25, 'Il connaît les travaux des humains; sur eux, il ramènera la nuit, et ils seront humiliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 26, 'Il a éteint les impies, car ils étaient visibles pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 27, 'Et ils s’étaient écartés de la loi de Dieu; ils avaient méconnu ses préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 28, 'Ils avaient fait monter jusqu’à lui les cris du pauvre; et le cri des indigents sera écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 29, 'C’est lui qui donne la paix, et qui donc fera condamner celui à qui il l’accorde? S’il cache son front, soit à l’homme, soit aux peuples, qui le verra?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 30, 'Il place sur le trône l’homme hypocrite, à cause de la perversité du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 31, 'Celui-là dit au Tout-Puissant: J’ai reçu ce qui m’est dû; je ne retiendrai rien en gage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 32, 'Je ne puis voir par moi-même; faites-moi connaître si j’ai commis quelque injustice, et je ne recommencerai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 33, 'Doit-il rendre à l’homme d’après ton sens, puisque tu regrettes mes paroles. Tu vas décider, et non pas moi. Et ce que tu sais, dis-le.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 34, 'Les cœurs intelligents diront, ainsi que l’homme sage qui aura entendu mes paroles:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 35, 'Job n’a point raisonné selon la sagesse; ses discours ne sont point selon la science (8).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 36, 'O Job, instruis-toi donc; ne réponds pas encore la manière des insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 37, 'De peur que nous n’ajoutions à nos fautes; car il nous sera imputé à péché de nous étendre en longs discours contre le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 1, 'Et Éliu, continuant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 2, 'Qu’as-tu pensé obtenir d’un jugement? Qui es-tu, toi qui as osé dire: Je suis juste devant le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 3, 'Je vais faire entendre la réponse à toi et à tes trois amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 4, 'Lève les yeux au ciel, et regarde et contemple les nuées; vois combien elles sont au-dessus de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 5, 'Si tu pèches, que feras-tu? Si tu as commis beaucoup de fautes, qu’as-tu pu faire qui nuise au Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 6, 'Si tu es juste, que lui en revient-il? Que prendrat-il de ta main?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 7, 'C’est l’homme, son semblable, que ton impiété touche; c’est le fils de l’homme qu’intéresse ta justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 8, 'Ceux qui sont opprimés par la calomnie crieront; ils se plaindront de violences nombreuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 9, 'Mais nul d’eux n’a dit: Où est Dieu, mon créateur, qui a distribué les veilles de la nuit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 10, 'Qui m’a distingué des bêtes de la terre et des oiseaux du ciel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 11, 'Mais s’ils crient vers vous à cause des outrages des méchants, ne les entendez-vous pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 12, 'C’est la fausseté, l’absurdité que le Seigneur ne veut pas entendre, car le seul Tout-Puissant');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 13, 'Voit et punit les ouvriers d’iniquité, et il me sauvera. Entre en jugement avec lui, si tu peux le louer d’une manière digne de son être.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 14, 'Sache bien qu’il ne te visite pas encore dans sa colère; et il ne punit pas comme il devrait tes nombreux péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 15, 'Job a donc vainement ouvert la bouche; il multiplie les paroles, dans son ignorance des choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 1, 'Et Éliu, continuant, dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 2, 'Patiente un moment encore, afin que je t’instruise; je sens en moi bien des choses à dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 3, 'Je reprendrai de loin ce que je sais, et, d’accord avec mes œuvres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 4, 'Je te parlerai sincèrement, et tu n’accueilleras pas injustement des paroles injustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 5, 'Apprends que le Seigneur ne repoussera jamais l’innocence; Celui qui a la suprême force en son cœur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 6, 'Ne vivifiera jamais l’impie; il jugera la cause des indigents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 7, 'Il ne détournera pas ses regards du juste, ni des rois sur leur trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 8, 'A ceux qui sont pris par des entraves, et retenus dans les liens de la pauvreté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 9, 'Il fera connaître leurs œuvres et leurs fautes, car elles sont grandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 10, 'Mais il écoutera les justes, à qui il a dit de se détourner de l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 11, 'S’ils lui sont dociles et le servent, ils achèveront Ieurs jours dans l’abondance des biens, et leurs années dans les grandeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 12, 'Il ne protége point les impies, parce qu’ils refusent de connaître le Seigneur, et parce qu’ils sont rebelles à ses avertissements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 13, 'Et les hommes au cœur hypocrite attirent la colère de Dieu; ils ne crieront pas, s’il vient à les enchaîner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 14, 'Que leur âme meure en leur jeunesse; que la vie leur soit ôtée par les anges exterminateurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 15, 'Parce qu’ils auront opprimé le pauvre et le faible: et le Seigneur publiera le jugement des bons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 16, 'Si tu t’es laissé tromper par la bouche de l’ennemi, les flots de l’abîme sont là, sous toi, et ta table y tombera chargée de graisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 17, 'Mais il ne fera pas attendre aux justes sa sentence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 18, 'Et son courroux s’élèvera contre les pervers, à cause des dons impies qu’ils auront reçus pour d’injustes causes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 19, 'Que ton âme ne se détourne pas volontairement de la demande que te feront les pauvres pressés par le besoin; réprime tous ceux qui usent de violence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 20, 'Ne prolonge pas tes nuits, afin que le peuple puisse recourir à toi contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 21, 'Sois attentif à t’abstenir d’œuvres mauvaises; car tu y es tombé entraîné par la misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 22, 'Et le Tout-Puissant t’affermira par sa force: qui peut prévaloir contre lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 23, 'Qui peut discuter ses œuvres? Qui lui dira: Tu as fait des injustices?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 24, 'Souviens-toi que grandes sont ses œuvres, que les hommes ont célébrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 25, 'Tout homme le voit en elles; tous ceux qui sont sujets à la douleur et à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 26, 'Il est puissant par excellence, et nous ne le connaîtrons jamais; le nombre de ses années est infini.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 27, 'Il sait le compte des gouttes de pluie; de la pluie que versent les nuées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 28, 'Elles couleront ces eaux antiques; et les nuées ont couvert d’ombre une foule innombrable de mortels. Il donne aux bestiaux leur heure; par lui, ils savent régler leur sommeil. De toutes ces choses, ton intelligence n’est pas étonnée, et en toi ton cœur n’est pas ému.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 29, 'Si toutes les nuées n’en forment qu’une seule, c’est comme son tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 30, 'Voilà qu’il étend sur elle son arc, et il a caché les profondeurs de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 31, 'C’est avec cela qu’il juge les peuples; les plus puissants lui doivent leur nourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 32, 'Il cache dans ses mains la lumière, et lui ordonne d’apparaître à ceux qui vont au-devant d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 33, 'Il la révèle à ses amis (car elle est la possession du Seigneur), afin de les détourner de l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 1, 'À cause de cela mon cœur a été troublé, et il s’en est allé de sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 2, 'Écoute les accents de la colère du Seigneur; et la méditation qui, pour toi, sortira de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 3, 'Il règne sur tout ce que le ciel recouvre, et sa lumière est sur les ailes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 4, 'Après lui une grande voix se fait entendre; il tonnera avec la voix de sa grandeur, et il ne retiendra pas la pluie et la grêle qui auront entendu sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 5, 'Le Tout-Puissant tonnera de sa voix admirable; car il fait de grandes choses qui nous sont inconnues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 6, 'Il dit à la neige: Sois sur la terre; il envoie les pluies d’orage et les torrents des tempêtes de sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 7, 'Il ferme alors de son sceau les mains de chaque homme, afin que chaque homme connaisse sa propre faiblesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 8, 'Les bêtes fauves sont entrées dans leurs repaires; elles se sont reposées sur leur couche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 9, 'De ses réservoirs sort le vent des douleurs, et des parties extrêmes du nord la froidure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 10, 'Le Tout-Puissant, de son souffle, produit la glace; il dispose l’eau comme il lui plaît.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 11, 'La nuée prépare la production des fruits, et les nuages répandent leur lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 12, 'Il les envoie tout autour du ciel et les dirige selon ses conseils, pour faire tout ce qu’il leur prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 13, 'Toutes ces choses ont été par lui établies sur la terre, soit pour la correction des pécheurs, soit pour le bien de sa terre, afin qu’elle éprouve sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 14, 'Recueille tout ce que j’ai dit, Job; arrête-toi en considérant la puissance du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 15, 'Nous savons que Dieu a fait ses œuvres, lorsqu’il a séparé la lumière des ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 16, 'Il prévoit la dispersion des nuages et la chute éclatante des méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 17, 'Ta robe n’est-elle pas chaude, lorsqu’il fait régner le calme sur la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 18, 'C’est lui qui a affermi les cieux anciens: ce ciel si solide, et qui néanmoins a l’aspect de l’onde qui s’écoule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 19, 'C’est pourquoi, apprends-le-moi; que lui dironsnous? Cessons nos longs discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 20, 'Aurai-je auprès de moi un livre ou un scribe, pour que je me tienne là et que je lui impose silence comme à un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 21, 'Personne ne peut regarder la lumière; elle brille dans les cieux, répandue par lui sur les nuées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 22, 'Surtout, lorsque l’aquilon amène ses nuages éclatants comme l’or. Ces choses montrent la grande gloire et l’honneur du Tout-Puissant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 23, 'Et nous n’en trouvons pas un autre qui lui soit semblable en vertu. Celui qui juge la justice, crois-tu qu’il n’écoute pas les plaintes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 24, 'À cause de cela, les hommes craindront Dieu; les sages en leur cœur auront crainte de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 1, 'Aussitôt qu’Éliu le Buzite eut fini son discours, le Seigneur dit à Job, à travers un nuage et un tourbillon:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 2, 'Quel est celui qui m’obscurcit mon conseil? S’il renferme des pensées en son cœur, croit-il qu’elles m’échappent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 3, 'Ceins-toi les reins, comme un homme. Je vais te questionner; réponds-moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 4, 'Où étais-tu, quand j’ai créé la terre? Répondsmoi, si tu as la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 5, 'Qui en a réglé les dimensions, le sais-tu? Qui a promené sur elle le cordeau?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 6, 'Comment a-t-on attaché ses anneaux? Qui en pose la pierre angulaire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 7, 'Lorsque les astres ont paru, et qu’à grande voix me louaient tous mes anges,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 8, 'J’ai fermé la mer avec des portes, lorsqu’elle s’élançait frémissante des entrailles maternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 9, 'Pour langes, je lui ai donné les brouillards, et pour vêtement les nuées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 10, 'J’ai fixé ses limites; je l’ai entourée de clôtures et de portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 11, 'Je lui ai dit: Tu iras jusque-là, tu n’iras pas plus loin; tes vagues se briseront sur toi-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 12, 'Est-ce par toi que j’ai disposé la lueur de l’aurore, et que l’étoile du matin a vu qu’elle avait pour devoir');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 13, 'De secouer la terre, en la tenant par les deux ailes, et d’en secouer les impies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 14, 'Est-ce toi qui, ayant pris de l’argile, as formé ûn être vivant, et l’as mis sur la terre doué de la parole?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 15, 'As-tu ôté aux méchants la lumière? As-tu broyé le bras de l’orgueilleux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 16, 'Es-tu descendu jusqu’aux sources de la mer? Astu marché dans les profondeurs de l’abîme?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 17, 'Les portes de la mort s’ouvrent-elles devant toi de frayeur, et les portiers de l’enfer, en te voyant, tremblentils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 18, 'Connais-tu l’étendue de cette terre que le ciel recouvre? Dis-moi donc quelle elle est?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 19, 'Quelle est la contrée où réside la lumière? En quel lieu demeurent les ténèbres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 20, 'Pourrais-tu me conduire à leurs confins? Connaistu leurs voies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 21, 'Tu le sais donc; car dès lors tu étais né, et le nombre de tes années est grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 22, 'As-tu visité les trésors de la neige? As-tu vu les trésors de la grêle?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 23, 'Les tiens-tu en réserve pour l’heure où se montreront tes ennemis, pour le jour de la guerre et du combat?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 24, 'D’où viennent les frimas et le vent du midi qui souffle partout sous le ciel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 25, 'Qui a préparé la chute des pluies violentes, et la voix des tempêtes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 26, 'Ces pluies qui tombent sur des contrées où il n’y a point d’hommes, sur des déserts où nul homme n’existe?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 27, 'Qui fécondent des champs inaccessibles ou inhabités, qui leur font produire l’herbe luxuriante?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 28, 'Quel est le père de la pluie? Qui a produit les gouttes de la rosée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 29, 'De quel sein est sortie la glace, et qui, dans le ciel, a enfanté le givre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 30, 'Quand il descend comme une eau s’écoulant? Quel est celui qui frappe de terreur les impies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 31, 'Possèdes-tu le secret du lieu des Pléiades? Auraistu ouvert la clôture d’Orion?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 32, 'Feras-tu apparaître les signes du zodiaque en leur temps, et l’étoile du soir, sa chevelure? sauras-tu la conduire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 33, 'Connais-tu les révolutions du ciel, et ce qui, en même temps, arrive sur la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 34, 'Appelles-tu de la voix le nuage? t’obéit-il, plein de frayeur, en versant des torrents d’eau?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 35, 'Enverras-tu les éclairs, et à ta voix partiront-ils? Est-ce à toi qu’ils diront: Nous voici?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 36, 'Qui donc a enseigné aux femmes la sagesse pour faire les tissus, et l’art d’y tracer des ornements divers?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 37, 'Qui sait, en sa sagesse, compter les nuages, et qui a courbé le ciel vers la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 38, 'Il enceint la terre comme s’il était d’argile, et je l’ai fait solide comme une voûte de pierre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 39, 'Chasseras-tu pour donner aux lions leur nourriture? rempliras-tu l’âme des dragons?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 40, 'Ils craignent dans leurs retraites, et ils se tiennent en embuscade au fond des forêts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 41, 'Qui a préparé au corbeau sa pâture? car ses petits, en voltigeant, ont crié au Seigneur, cherchant leur manger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 1, 'Sais-tu le temps où la gazelle des rochers met bas? As-tu observé les biches dans les douleurs de l’enfantement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 2, 'As-tu compté les mois de leur portée? les as-tu délivrées des douleurs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 3, 'As-tu nourri leurs petits sans qu’ils aient crainte? as-tu fait réussir leur enfantement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 4, 'Elles quittent leurs petits, qui néanmoins prospèrent au pâturage; ils s’éloigneront, et ne reviendront jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 5, 'Qui a mis en liberté l’âne sauvage? Qui a détaché ses liens?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 6, 'Je lui ai donné pour demeure le désert, pour abri la contrée saumâtre et stérile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 7, 'Il se raille de la foule qui peuple les cités; il n’entend jamais les reproches du collecteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 8, 'Il recherche les pâturages des montagnes, et court après toute sorte d’herbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 9, 'La licorne se prêtera-t-elle à te servir? couchera-t-elle jamais en ton étable?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 10, 'Pourras-tu l’attacher au joug avec des courroies, et lui faire creuser les sillons de tes champs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 11, 'Te fieras-tu à elle et à sa grande force, et la chargeras-tu de tes travaux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 12, 'Croiras-tu qu’elle te rende tes semailles? les ferat-elle mettre en ton aire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 13, 'L’aile de l’autruche s’agite joyeusement; est-ce l’aile pieuse et le plumage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 14, 'Nullement. L’autruche laisse ses œufs à terre, et le sable les échauffe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 15, 'Elle oublie que le passant les dispersera, et les bêtes fauves des champs les fouleront aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 16, 'Elle est dure pour ses petits, comme s’ils n’étaient pas siens; elle ne craint pas d’avoir vainement souffert:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 17, 'Parce que Dieu, chez elle, a fait taire la sagesse, et ne lui a pas accordé sa part d’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 18, 'A l’occasion, elle prendra son essor, et raillera le cheval et le cavalier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 19, 'Est-ce toi qui as donné au cheval sa force, et qui as revêtu son cou de terreur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 20, 'Est-ce toi qui l’as revêtu de son armure et de la gloire de son poitrail?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 21, 'Il imprime son sabot dans le sol et s’enorgueillit; il s’élance en sa force à travers la campagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 22, 'Il va au-devant des traits, et s’en moque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 23, 'L’arc et l’épée se glorifient, s’ils l’atteignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 24, 'Il bouleverse le sol en sa fureur; il n’écoute rien, que le signal de la trompette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 25, 'S’il l’entend retentir, il dit: Ah! il sent de loin la bataille, les mouvements et les cris de l’armée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 26, 'Est-ce ta science qui a appris à l’épervier à se tenir immobile, déployant ses ailes et regardant le Midi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 27, 'Est-ce à ton commandement que l’aigle élève son vol, et que le vautour reste perché au-dessus de ses poussins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 28, 'Sur la pointe d’une roche, au fond de șa retraite?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 29, 'De là, il cherche sa pâture; ses yeux voient au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 30, 'Ses petits sont souillés de sang, et partout où il y a des cadavres, soudain il les découvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 31, 'Et le Seigneur Dieu, continuant de parler à Job, dit Est-ce qu’il décline la justice du Tout-Puissant? Celui qui a adressé des reproches à Dieu doit lui répondre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 32, 'Et Job, reprenant, dit au Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 33, 'Pourquoi continuerais-je de contester? Je suis averti, et, après avoir adressé des reproches au Seigneur, j’ai entendu de telles paroles, moi qui ne suis rien. Que pourrais-je répondre? Je n’ai plus qu’à mettre ma main sur ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 34, 'J’ai parlé une fois; je me garderai bien de parler encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 1, 'Et le Seigneur, continuant, dit à Job, à travers la nuée:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 2, 'Nullement; mais ceins-toi les reins, comme un homme. Je vais te questionner, réponds-moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 3, 'Ne refuse pas mon jugement. Pensais-tu que je te répondrais autrement, afin de te faire paraître juste?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 4, 'Ton bras est-il comme le bras du Seigneur? ta voix est-elle comme son tonnerre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 5, 'Revêts-toi de grandeur et de puissance; orne-toi d’honneur et de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 6, 'Envoie des anges dans ta colère; humilie tout orgueilleux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 7, 'Éteins les superbes; fais tomber soudain l’impie en pourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 8, 'Cache-les ensemble sous la terre, couvre leur front de honte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 9, 'Je confesserai alors que ta main droite peut sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 10, 'Mais vois auprès de toi la bête; elle se repaît comme les bœufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 11, 'Sa vigueur est dans ses reins; sa force, dans l’ombilic de son ventre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 12, 'Elle dresse sa queue comme un cyprès; ses nerfs sont liés entre eux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 13, 'Ses côtes sont des côtes d’airain; son échine, de fer fondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 14, 'Elle est le commencement des œuvres du Seigneur, créée pour être le jouet des anges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 15, 'Lorsqu’elle a gravi sur la cime du mont, elle a réjoui les quadrupèdes dans le Tartare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 16, 'Elle se couche sous des arbres de toute sorte: auprès des papyrus, du jonc et du roseau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 17, 'Les grands arbres la couvrent de l’ombre de leurs rameaux, comme les jeunes tiges des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 18, 'Vienne l’inondation, elle ne s’en émeut pas; elle ne craint rien, car le Jourdain lui-même entrerait dans sa gueule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 19, 'Et cependant on la prendra par les yeux, on la liera et l’on percera ses narines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 20, 'Prendras-tu le dragon à l’hameçon? Passerastu autour de sa tête un licou?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 21, 'Attacheras-tu à son nez un anneau? perceras-tu ses lèvres avec un bracelet?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 22, 'Te parlera-t-il? Te priera-t-il avec douceur comme un suppliant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 23, 'Fera-t-il un pacte avec toi? Le prendras-tu pour esclave dans les siècles des siècles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 24, 'Te joueras-tu de lui comme d’un oisillon? l’attacheras-tu comme un passereau pour ton petit enfant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 25, 'Les nations le mangent; les peuples phéniciens se le partagent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 26, 'Tous leurs navires réunis n’emporteront pas une des peaux de sa queue, et les barques des pêcheurs n’auront pas sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 27, 'Tu mettras la main sur lui en te souvenant du combat que livre sa bouche; et qu’il soit fini.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 28, 'Ne l’as-tu pas vu? N’es-tu pas étonné de ce qui en est dit?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 1, 'N’avais-tu pas été effrayé, par ce que je t’avais préparé? car quel est celui qui s’est opposé à moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 2, 'Quel est celui qui, m’ayant résisté, pourra se soutenir, puisque tout ce que le ciel recouvre m’appartient?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 3, 'Je ne me tairai pas, à cause de lui et de sa puissance; me fera-t-il grâce comme à son égal?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 4, 'Qui découvrira la face de son vêtement? Qui pénètrera sous l’écaille de sa poitrine?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 5, 'Qui ouvrira les portes de son visage? Ses dents alentour inspirent la terreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 6, 'Ses entrailles sont garnies de boucliers d’airain; ses écailles sont comme la pierre d’émeri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 7, 'L’une tient à l’autre; nul souffle n’y passe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 8, 'Chacune est adhérente à sa sœur; elles se tiennent, et on ne les séparera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 9, 'S’il éternue, des étincelles jaillissent; ses yeux brillent comme Lucifer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 10, 'Sa bouche vomit des flammes qui jettent au loin des étincelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 11, 'De ses narines sort une fumée semblable à celle d’une fournaise de charbons ardents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 12, 'Son âme est de charbons embrasés; sa bouche exhale du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 13, 'La force réside en son encolure; la perdition court devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 14, 'Les chairs de son corps sont indissolubles; répandues sur lui, elles sont d’une immobile fermeté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 15, 'Son cœur est dur comme une pierre; il est inflexible comme une enclume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 16, 'S’il se retourne, il répand l’effroi parmi les bêtes fauves, qui bondissent sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 17, 'Les javelines, les traits, les cuirasses ne peuvent rien contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 18, 'Il fait cas du fer comme de la paille, et de l’airain comme du bois pourri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 19, 'Ce n’est pas une flèche d’airain qui le blessera; les pierres de la fronde lui font l’effet d’un brin d’herbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 20, 'Les marteaux sont pour lui comme des joncs; il rit de coups qui font jaillir des étincelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 21, 'Il a pour couche des obélisques aigus; l’or de la mer est sous ses pieds, comme une boue qu’on ne pourrait mesurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 22, 'Il fait bouillir l’abîme comme un vase d’airain; il prend la mer pour un vase à parfums,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 23, 'Le Tartare de l’abîme pour un captif, et l’abîme pour un lieu de promenade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 24, 'Rien sur la terre n’est semblable à lui, qui a été créé pour être le jouet de mes anges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 25, 'Il voit tout ce qui s’élève; il règne sur ce que contiennent les eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 1, 'Or Job, reprenant, dit au Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 2, 'Je sais que vous pouvez tout, et que rien ne vous est impossible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 3, 'Qui peut vous cacher ses desseins? Croira-t-on que vous les ignorez, parce qu’on aura épargné les paroles? Qui me révèlera ce que je ne savais pas, les grandes merveilles dont je n’avais pas connaissance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 4, 'Écoutez-moi désormais, Seigneur, et je parlerai; je vous interrogerai, instruisez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 5, 'Mon oreille vous a d’abord entendu, et maintenant mon œil vous voit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 6, 'C’est pourquoi je me méprise moi-même; je me confonds, et je sens que je ne suis que cendre et poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 7, 'Or ceci advint: après que le Seigneur eut tenu à Job tout ce discours, le Seigneur dit à Éliphaz le Thémanite Tu as péché, toi et tes deux amis; car vous n’avez rien dit devant moi qui fût véritable, comme l’a fait Job, mon serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 8, 'Allez donc chercher sept béliers et sept bœufs, et revenez auprès de Job mon serviteur, et il offrira pour vous un sacrifice; et Job mon serviteur priera pour vous, car je n’écouterai que lui. Si ce n’était en sa considération, je vous détruirais; car vous n’avez pas dit la vérité, comme Job mon serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 9, 'Et Éliphaz le Thémanite, et Baldad le Sauchite, et Sophar le Minéen, partirent et firent ce que leur avait prescrit le Seigneur, et il leur remit leur péché à cause de Job.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 10, 'Et le Seigneur fortifia Job, et à sa prière il remit à ses amis leur péché. Et le Seigneur donna à Job le double de ce qu’il possédait auparavant; il doubla toute chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 11, 'Et tous ses frères et toutes ses sœurs apprirent ce qui lui était arrivé; et ils vinrent auprès de lui, et tous ceux qui le connaissaient précédemment. En mangeant et en buvant chez lui, ils le consolèrent, et ils témoignèrent leur admiration au sujet de tout ce que le Seigneur lui avait envoyé; et chacun d’eux lui donna une brebis et un sicle d’or non monnayé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 12, 'Et le Seigneur bénit Job en la fin de sa carrière, plus que dans les commencements; et ses troupeaux furent quatorze mille brebis, six mille chamelles, mille paires de bœufs et mille ânesses au pâturage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 13, 'Et il lui naquit sept fils et trois filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 14, 'Et il appela la première Héméra, la seconde Casia, et la troisième Corne d’Amalthée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 15, 'Et, en toute l’étendue que le ciel recouvre, on n’eût pas trouvé femmes plus belles que les filles de Job, et leur père leur donna des parts d’héritage comme à ses fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 16, 'Et Job, après ses jours d’affliction, vécut cent soixante-dix ans; et la durée de toute sa vie fut de deux cent quarante ans. Et Job vit ses fils et les fils de ses fils, jusqu’à la quatrième génération, et Job finit très-avancé en âge et plein de jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Aimez la justice, vous qui jugez la terre; ayez le cœur bon en pensant au Seigneur; cherchez-le dans la simplicité du cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Car il est trouvé par ceux qui ne le tentent point, et il se manifeste à ceux qui ont foi en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Les pensées tortueuses séparent de Dieu, et sa puissance confond les insensés, quand ils la mettent à l’épreuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'La sagesse n’entrera pas dans une âme artificieuse; elle ne résidera pas en un corps esclave du péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Car l’Esprit-Saint, maître de la discipline, fuit le déguisement; il s’éloigne d’un cœur insensé, et se retire à l’approche de l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'La sagesse est un esprit de charité; elle ne pardonne pas aux lèvres médisantes: car Dieu sonde les reins, il scrute le cœur en toute vérité; ce que dit la langue, il l’entend.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'L’Esprit du Seigneur remplit l’univers, et comme il contient tout, il a connaissance de tout ce que dit la voix de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'C’est pourquoi celui qui dit des paroles iniques ne lui sera point caché, et il n’échappera point au jugement qui doit le châtier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Les diffamations des impies seront poursuivies, et le bruit de leurs paroles parviendra jusqu’au Seigneur, pour les punir de leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Car l’oreille du Dieu jaloux entend toutes choses, et le tumulte des murmures ne lui sera point caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Gardez-vous donc de plaintes inutiles; préservez votre langue de toute médisance; car pas une parole secrète ne sera perdue, et la bouche menteuse tue l’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Ne cherchez point la mort par les égarements de votre vie; n’attirez point votre perdition par les œuvres de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Car Dieu n’a point fait la mort, et il ne se réjouit point de la perdition des vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Il a créé toutes choses pour qu’elles fussent; les générations du monde peuvent se sauver; il n’est point en elles de venin mortel, et l’empire de l’enfer n’est pas sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Car la justice est immortelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Mais les impies appellent la mort de la parole et des mains; ils l’ont estimée une amie, et ils ont été consumés, et ils ont fait un pacte avec elle; car ils sont dignes d’être de son parti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 1, 'Ceux qui en eux-mêmes ne pensent pas avec droiture, ont dit: Notre vie est courte et pleine de tristesse, et la fin de l’homme n’est pas un remède à ses maux; l’on ne connaît personne qui soit revenu de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 2, 'Car nous avons été engendrés sans réflexion, et, après cela, nous serons comme n’ayant pas été; le souffle qui s’échappe de nos narines, c’est une fumée, et la pensée est une étincelle, dans l’agitation de nos cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 3, 'Quand elle sera éteinte, le corps sera cendre, et le souffle se répandra comme l’air insaisissable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 4, 'Et notre nom sera oublié dans le temps, et nul ne se souviendra de nos œuvres; et notre vie passera comme l’ombre d’un nuage; elle se dissipera comme un brouillard chassé par les rayons du soleil, et tombant sous la chaleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 5, 'Car notre vie est le passage d’une ombre; notre fin est sans retour; elle est scellée, et nul ne revient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 6, 'Venez donc, et jouissons des biens présents; hâtons-nous d’user de la créature pendant notre jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 7, 'Enivrons-nous de parfums et de vins délicieux, et ne laissons point passer la fleur de la saison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 8, 'Couronnons-nous de roses, avant qu’elles soient flétries.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 9, 'Que nul de nous ne soit privé de nos plaisirs; laissons partout des signes de nos joies: car c’est là notre partage, c’est notre sort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 10, 'Opprimons le juste, s’il est pauvre; n’épargnons pas la veuve; ne respectons point les cheveux blancs du vieillard chargé d’années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 11, 'Que la force soit notre loi de justice; car tout ce qui est faible est inutile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 12, 'Tendons des pièges au Juste; car il nous est importun; il est contraire à nos œuvres; il nous reproche nos manquements à la loi; il nous diffame en décriant notre conduite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 13, 'Il assure qu’il a la science de Dieu, et il se nomme le Fils de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 14, 'Il est pour nous comme un blâme vivant de nos pensées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 15, 'Il nous est odieux, même à voir; parce que sa vie n’est point comme celle des autres, et que ses sentiers sont différents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 16, 'Nous sommes estimés par lui de mauvais aloi, et il se détourne de nos voies comme de choses impures; il déclare heureuse la fin du juste, et il se glorifie d’avoir Dieu pour Père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 17, 'Voyons s’il y a quelque vérité en ses paroles; éprouvons les choses de sa fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 18, 'Car si le Juste est Fils de Dieu, Dieu le protégera, et le tirera des mains de ses adversaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 19, 'Interrogeons-le dans l’outrage et la torture, afin que nous connaissions sa douceur, et que nous jugions de sa patience.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 20, 'Condamnons-le à une mort infamante; car alors nous verrons s’il y a vérité en ses paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 21, 'Voilà comme ils ont raisonné, et ils sont tombés dans l’erreur; car leur malice les a aveuglés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 22, 'Et ils n’ont rien pénétré des mystères de Dieu; ils n’ont point cru qu’il y eût un salaire pour la sainteté, et ils n’ont fait nul cas de la récompense destinée aux innocents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 23, 'Car Dieu a créé l’homme pour l’immortalité; et il l’a créé à son image et ressemblance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 24, 'Mais la mort est entrée dans le monde par l’envie du démon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 25, 'Et ceux qui sont de son parti sont ses imitateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 1, 'L’âme des justes est dans la main de Dieu, et nulle torture ne les atteindra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 2, 'Aux yeux des insensés, il semble qu’ils meurent; leur fin est regardée comme une infortune,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 3, 'Et leur sortie du monde comme une tribulation. Cependant ils sont en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 4, 'Lors même qu’aux yeux des hommes ils auraient souffert, leur espérance est pleine d’immortalité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 5, 'Leur affliction fut légère, grande sera leur récompense; car Dieu les a mis à l’épreuve, et les a trouvés dignes de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 6, 'Il les a fait passer au creuset comme de l’or, et il les a accueillis comme une hostie d’holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 7, 'Et, au temps de sa visite, ils brilleront comme des étincelles qui courent à travers les roseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 8, 'Ils jugeront les nations, ils domineront sur les peuples, et leur Seigneur régnera dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 9, 'Ceux qui ont foi en lui comprendront la vérité, et les fidèles persévéreront dans leur amour pour lui; car sa grâce et sa miséricorde seront pour ses élus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 10, 'Mais les impies, qui n’ont point eu d’égards pour le Juste, et se sont retirés du Seigneur, seront punis selon leurs pensées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 11, 'Malheur à ceux qui méprisent la sagesse et la discipline; vaine est leur espérance, leur labeur infructueux, leurs œuvres inutiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 12, 'Leurs femmes sont insensées, et leurs enfants pervers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 13, 'Leur race est maudite. Heureuse la femme stérile, mais non souillée, qui n’a pas déshonoré sa couche par le péché; elle aura sa récompense le jour de la visite des âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 14, 'Et l’eunuque qui, de ses mains, n’aura pas fait œuvre d’iniquité, et n’aura point pensé à mal contre le Seigneur, recevra une grâce particulière de foi, et, dans le temple du Seigneur, un partage digne d’envie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 15, 'Le fruit des bons labeurs est glorieux, et la racine de la prudence ne se perd pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 16, 'Les enfants des adultères finiront mal, et la race issue d’une couche criminelle disparaîtra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 17, 'Et s’ils vivent longtemps, ils seront comptés pour rien; et les derniers jours de leur vieillesse seront sans honneurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 18, 'Et s’ils meurent jeunes, ils n’auront ni espérance ni consolation au jour du jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 19, 'Car d’une lignée inique, mauvaise est la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 1, 'Mieux vaut la virginité avec la vertu; car sa mémoire est immortelle, elle est connue et de Dieu et des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 2, 'Présente, on l’imite; absente, on la regrette; dans tous les siècles, elle marche couronnée et triomphante: car elle a remporté le prix des chastes luttes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 3, 'La multitude féconde des impies ne fera aucun bien; et ces boutures bâtardes ne jetteront point de profondes racines, ni ne s’établiront sur une base solide.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 4, 'Et si, pour un moment, l’un des rejetons vient à germer, comme il sera sans force, le moindre vent l’ébranlera, et la violence de la tempête finira par le déraciner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 5, 'Ses chétifs rameaux seront brisés, et ses fruits seront mauvais, amers au goût, entièrement inutiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 6, 'Car interrogez les enfants nés de sommeils illégitimes, ils témoignent de la perversité de ceux qui les ont engendrés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 7, 'Mais le juste, s’il est prévenu par la mort, sera en repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 8, 'Car ce n’est ni la longueur des jours ni le nombre des années qui rendent la vieillesse vénérable;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 9, 'Mais la prudence dans les hommes leur tient lieu de cheveux blancs; une vie pure a le même âge que la vieillesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 10, 'L’homme agréable à Dieu est aimé de lui; et, s’il vivait au milieu des impies, il en a été retiré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 11, 'Il a été enlevé, de peur que leur malice ne pervertît son intelligence, ou que la ruse ne trompât son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 12, 'Car les fascinations de la frivolité obscurcissent la vertu, et l’inquiétude de la concupiscence ébranle une âme innocente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 13, 'L’homme parfait, en peu de temps, a rempli de longs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 14, 'Car son âme a plu au Seigneur; c’est pourquoi il a eu hâte de la séparer du milieu de l’iniquité; mais les peuples voient, et ne comprennent pas; ils ne se mettent point dans la pensée');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 15, 'Que la grâce et la miséricorde sont aux élus de Dieu, et sa visite à ses saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 16, 'Le juste mort condamne les impies vivants, et la jeunesse qui finit prématurément, condamne la vieillesse de l’impie chargé d’années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 17, 'Les impies verront la mort du sage, et ne comprendront point les desseins du Seigneur sur lui, ni pourquoi Dieu l’a mis en sûreté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 18, 'Ils la verront, et n’en tiendront aucun compte; mais le Seigneur se rira d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 19, 'Et, après cela, ils tomberont sans honneur, et pour l’éternité ils seront en opprobre parmi les morts; car le Seigneur les brisera sans voix, le front en avant; et il les ébranlera, et, de la base au sommet, ils seront désolés, et ils seront dans la douleur, et leur mémoire périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 20, 'Ils viendront tout tremblants âu souvenir de leurs péchés, et leurs iniquités passeront devant eux pour les accuser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 1, 'Alors le juste se placera avec confiance en face de ceux qui l’auront opprimé, et qui lui auront ravi le fruit de son labeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 2, 'A son aspect, ils seront troublés, pleins de crainte, stupéfaits de son salut inespéré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 3, 'Ils se diront repentants, gémissants en l’angoisse de leur esprit: Voilà donc celui que nous tenions autrefois en dérision et en opprobre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 4, 'Insensés, nous imputions leur vie à folie, leur mort à déshonneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 5, 'Comment a-t-il compté parmi les fils de Dieu? Comment son héritage est-il avec les saints?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 6, 'Nous nous sommes donc écartés des voies de la vérité; la lumière de la justice ne nous a pas éclairés, et le soleil ne s’est pas levé sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 7, 'Nous nous sommes lassés dans les sentiers de l’iniquité et de la perdition, et nous avons cheminé dans des déserts infréquentés, et nous n’avons point connu la voie du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 8, 'De quoi nous a servi notre superbe? Que nous a rapporté la richesse dont nous étions si fiers?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 9, 'Tout cela a passé comme l’ombre, comme un messager qui court en avant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 10, 'Comme un navire qui fend l’onde, vogue sans laisser de traces, et dont la carène ne creuse pas de sentier dans les flots;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 11, 'Comme l’oiseau qui traverse les airs sans que l’on voie des marques de son vol; mais se mouvant à grands coups d’ailes, fendant avec force et bruit l’espace silencieux, allant toujours en agitant ses ailes, et ne laissant après lui nulle trace de son passage;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 12, 'Ou comme la flèche lancée au but, et dont on ne peut reconnaître le parcours, parce que l’air qu’elle a fendu s’est aussitôt refermé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 13, 'Ainsi nous naissons, nous mourons, et nous ne pouvons montrer signe de vertu; mais nous nous sommes consumés en notre propre méchanceté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 14, 'L’espérance des impies est donc comme la poussière emportée par le vent; comme la gelée blanche fondue par la tempête; comme la fumée dispersée; au moindre souffle, elle s’est évanouie, comme le souvenir d’un hôte qui n’est resté qu’un jour, et a passé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 15, 'Mais les justes vivront éternellement, et leur salaire est dans le Seigneur, et leur pensée dans le Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 16, 'C’est pourquoi ils recevront, de la main du Seigneur, un trône de grâce et un diadème de beauté, et il les abritera sous sa droite, et les défendra de son bras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 17, 'Il s’armera de son zèle, et il en couvrira sa créature pour la venger de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 18, 'Pour cuirasse il revêtira sa justice, et pour casque il prendra l’intégrité de son jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 19, 'Il aura la sainteté pour invincible bouclier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 20, 'I aiguisera sa terrible colère pour en faire sa lance, et le monde, de concert avec lui, subjuguera les insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 21, 'Les traits infaillibles de son tonnerre partiront, et, comme ceux de l’arc des nuées, ils s’élanceront au but.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 22, 'Et la grêle tombera avec violence comme une pluie de pierres. Les eaux de la mer tourneront contre eux leur fureur, et les fleuves déborderont en courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 23, 'Contre eux se tiendra l’Esprit de vertu, et il les vannera comme un tourbillon, et l’iniquité fera de la terre une solitude; et la méchanceté renversera le trône des puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 1, 'Écoutez donc, rois; apprenez, juges de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 2, 'Prêtez l’oreille, ô vous qui gouvernez les peuples et qui êtes si fiers de leur multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 3, 'Votre puissance vous a été donnée par le Seigneur; votre autorité vient du Très-Haut, qui interrogera vos œuvres, et scrutera vos desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 4, 'Vous, ministres de son royaume, vous ne jugez point avec droiture; vous n’observez point la loi; vous ne marchez point selon la volonté de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 5, 'Et quand soudain il fondra sur vous, vous en frissonnerez; car son jugement est bien plus sévère contre ceux qui ont la puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 6, 'Car le petit reçoit le pardon de la miséricorde; mais les puissants seront poursuivis avec rigueur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 7, 'Le maître de toutes choses n’aura point égard au rang; il ne considèrera pas la grandeur: c’est lui qui a créé le petit et le grand, et sa providence veille également sur tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 8, 'Une enquête plus rigide est réservée aux plus puissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 9, 'O rois, c’est à vous que s’adressent mes paroles, afin que vous appreniez la sagesse, et que vous ne vous en écartiez point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 10, 'Car ceux qui gardent saintement les choses saintes seront sanctifiés, et ceux qui les auront apprises y trouveront ce qu’ils ont à répondre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 11, 'Soyez donc avides de mes paroles; aimez-les, et corrigez-vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 12, 'La sagesse brille et ne s’obscurcit jamais; ceux qui l’aiment, la voient facilement; ceux qui la cherchent, la trouvent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 13, 'Elle prévient ceux qui désirent la connaître avant tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 14, 'Celui qui, pour elle, se lève dès l’aurore, ne se fatiguera pas; car il la trouvera assise près de sa porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 15, 'Penser à elle est une prudence consommée; celui qui veille pour elle sera bientôt exempt d’inquiétude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 16, 'Elle s’en va à la ronde, cherchant ceux qui sont dignes d’elle, et se manifeste avec bienveillance en leurs sentiers, et va à la rencontre de tous leurs desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 17, 'Le commencement de la sagesse est donc un vrai désir de s’instruire; et le soin de s’instruire, c’est l’amour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 18, 'L’amour de la sagesse, c’est l’observance de ses lois; l’observance des lois, c’est une pureté accomplie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 19, 'Enfin la pureté nous approche de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 20, 'Donc le désir de la sagesse nous conduit au royaume éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 21, 'Ainsi, rois des peuples, si vous mettez votre joie dans les trônes et les sceptres, honorez la sagesse, afin que vous soyez rois éternellement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 22, 'Ce qu’est la sagesse et comment elle est née, je vais le dire, et je ne vous cacherai point ces mystères; je la suivrai à la trace depuis les premiers jours de sa naissance; et je mettrai sa doctrine en lumière, et je ne m’écarterai point de la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 23, 'Je ne cheminerai point avec celui que l’envie consume; car celui-là n’aura point de part à la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 24, 'La multitude des sages est le salut du monde, et un roi sage est l’appui de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 25, 'Recevez donc l’instruction qui sortira de mes paroles; elle vous profitera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 1, 'Et moi aussi, je suis un homme mortel, semblable à tous, né de la race du premier créé; et j’ai été fait chair, dans les entrailles d’une femme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 2, 'Coagulé dans le sang en dix mois; fruit de la semence d’un homme, et du plaisir qui vient avec le sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 3, 'Et moi aussi, aussitôt né, j’ai respiré l’air commun à tous; je suis tombé sur une terre également misérable, et, comme tous, j’ai jeté ma première voix en pleurant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 4, 'J’ai été élevé dans les langes entouré de soins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 5, 'Car nul des rois ne commence autrement à naître;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 6, 'Même entrée dans la vie, et même sortie pour tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 7, 'C’est pourquoi j’ai prié, et la sagesse m’a été donnée; j’ai invoqué Dieu, et en moi est venu l’esprit de sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 8, 'Je l’ai estimée plus que les sceptres et les trônes, et, au prix d’elle, j’ai tenu pour rien les richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 9, 'Je ne lui ai point comparé de pierre précieuse; tout l’or, à son aspect, ne paraît plus qu’un peu de sable, et, devant elle, l’argent ne vaut pas plus que de la boue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 10, 'Je l’ai aimée plus que la santé, plus que la beauté; et je l’aurais choisie de préférence à la lumière, parce que sa lumière ne s’éteint jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 11, 'Tous les biens à la fois me sont venus avec elle, et dans ses mains elle a d’innombrables richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 12, 'Et je me suis réjoui de toutes ces choses, parce que la sagesse elle-même me les amenait, et pourtant j’ignorais qu’elle en fût la mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 13, 'Je l’ai apprise en toute sincérité; je la communique sans épargne; je ne cèle point ses trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 14, 'Car ils sont inépuisables pour les hommes; ceux qui en usent en vue de Dieu se sont acquis son amour, et ils ont été recommandables par les dons de la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 15, 'Pour moi, que Dieu m’accorde de parler selon ma pensée, d’avoir des sentiments dignes des choses qui m’ont été données, parce que c’est lui le guide de la sagesse, c’est lui qui redresse les sages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 16, 'Car nous sommes en ses mains, nous et nos paroles, et toute notre sagesse, et la science de nos œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 17, 'C’est lui qui m’a donné la vraie science des choses de la nature; c’est lui qui m’a enseigné l’arrangement du monde, et la vertu des éléments;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 18, 'Le commencement, la fin et le milieu des temps, la course irrégulière des sphères et les changements des saisons;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 19, 'Le cercle de l’année, et la position des étoiles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 20, 'La nature des animaux, l’instinct des bêtes, la force des vents, les pensées des hommes, les variétés des plantes et les vertus des racines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 21, 'J’ai su toutes les choses cachées, comme celles qui sont manifestes; car l’artisan universel, la Sagesse, m’a instruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 22, 'En elle réside un esprit intelligent, saint, unique et multiple, subtil, vif, pénétrant, pur, clair, incorruptible, ami du bien, rapide, libre et bienfaisant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 23, 'Ami des hommes, ferme, constant, infaillible, tout-puissant; voyant tout, et l’emportant sur tous les esprits les plus intelligents, les plus purs, les plus subtils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 24, 'En effet, la Sagesse est plus active que toute activité; et, grâce à sa pureté, partout elle s’ouvre passage, elle pénètre partout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 25, 'Car c’est un souffle de la vertu de Dieu; c’est une émanation pure de la gloire du Tout-Puissant. C’est pourquoi rien de souillé ne pénètre en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 26, 'C’est la splendeur de la lumière éternelle, le miroir sans tache de la puissance de Dieu, et l’image de sa bonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 27, 'Unique, elle peut tout; immuable, elle renouvelle tout; et, de génération en génération, pénétrant dans les âmes saintes, elle forme les amis de Dieu et les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 28, 'Car Dieu n’aime que celui qui cohabite avec la Sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 29, 'Elle est plus belle que le soleil, plus belle que la disposition des étoiles; comparée à la lumière, elle a le premier rang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 30, 'Car la nuit succède au jour; mais le mal ne prévaut pas sur la Sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 1, 'La Sagesse, dans sa force, s’étend d’une extrémité de la terre à l’autre; elle règle toutes choses avec perfection.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 2, 'Je l’ai aimée et je l’ai choisie dès ma jeunesse; je l’ai cherchée afin de la prendre pour épouse, tant j’étais épris de sa beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 3, 'Elle honore sa noble origine en cohabitant avec Dieu; le maître de toutes choses la chérit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 4, 'C’est l’interprète de la science de Dieu; c’est la directrice de ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 5, 'Et si, dans la vie, la richesse est une chose désirable, qu’y a-t-il de plus riche que la Sagesse, l’artisan universel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 6, 'Or, si la Sagesse coopère à nos œuvres, qui plus qu’elle parmi les êtres est habile ouvrier?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 7, 'Et si quelqu’un aime la justice, ses vertus sont l’œuvre de la Sagesse; car il apprend la modération, la prudence, l’équité, le courage, que rien dans la vie de l’homme ne surpasse en efficacité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 8, 'Et si quelqu’un désire une grande expérience, la Sagesse sait le passé, elle prévoit l’avenir, elle connaît les subtilités du langage, et les solutions des problèmes; d’avance elle connaît les signes et les prodiges, les vicissitudes des saisons et des temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 9, 'J’ai donc résolu de la prendre pour épouse, sachant qu’elle ne me conseillerait que le bien, et me consolerait de mes peines et de mes inquiétudes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 10, 'Par elle j’aurai gloire parmi les peuples, et honneur parmi les vieillards, malgré ma jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 11, 'On me trouvera pénétrant quand je rendrai la justice; je ferai l’admiration des puissants en paraissant devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 12, 'Quand je me tairai, ils seront dans l’attente; quand je parlerai, ils auront les yeux sur moi; et si je parle plus longuement, ils se mettront une main sur la bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 13, 'Par elle j’aurai l’immortalité, et, dans la postérité, je laisserai une mémoire éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 14, 'Je régirai les peuples, et les nations me seront soumises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 15, 'Les rois, qui font trembler les hommes, en m’entendant seront saisis de crainte; je me montrerai bon envers la multitude, et fort à la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 16, 'Rentré dans mon palais, je me reposerai avec la Sagesse; car son entretien est sans amertume; son commerce donne non de la douleur, mais du bonheur et de la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 17, 'Après avoir pensé ces choses, et songé, en mon cœur, que l’immortalité est parente de la Sagesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 18, 'Que son amitié est pleine de charmes; que des travaux de ses mains naît une richesse inépuisable; que l’on acquiert la prudence dans l’exercice de sa société, et la gloire en devisant avec elle, je l’ai cherchée de toutes parts, afin de la prendre en moi-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 19, 'Or j’étais un enfant heureusement né, et j’étais doué d’une belle âme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 20, 'Et, en devenant meilleur, j’en vins à avoir un corps sans souillure;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 21, 'Et quand je sus qu’en aucune manière je ne serais chaste, à moins que Dieu ne me fit ce don, et que cela même était de la sagesse, de savoir de qui en venait la grâce, j’allai au Seigneur, et je le priai, et je lui dis de toute mon âme:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 1, 'Dieu de mes pères, Seigneur miséricordieux, qui par votre Parole avez créé toutes choses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 2, 'Qui en votre Sagesse avez formé l’homme, pour qu’il régnât sur toutes les créatures;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 3, 'Pour qu’il gouvernât le monde avec sainteté et justice, et qu’il jugeât dans la droiture de son âme:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 4, 'Donnez-moi la Sagesse, celle qui siége avec vous sur vos trônes, et ne me réprouvez pas d’entre vos enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 5, 'Je suis votre serviteur et le fils de votre servante, homme faible et de peu de durée, et des moindres en intelligence du jugement et de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 6, 'Car, si l’un des fils des hommes était parfait, votre Sagesse lui manquant, il serait compté pour rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 7, 'Vous m’avez élu roi de votre peuple, juge de vos fils et de vos filles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 8, 'Vous m’avez dit de bâtir un temple sur votre montagne sainte, et un autel dans la cité de votre tabernacle, image du saint tabernacle que, dès le commencement, vous avez préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 9, 'Et avec vous est la Sagesse qui connaît vos œuvres; elle était présente, lorsque vous avez créé le monde; elle sait ce qui est agréable à vos yeux, et quelle est la droiture de vos commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 10, 'Faites-la descendre des cieux, qui sont votre sanctuaire; envoyez-la du trône de votre gloire, afin qu’elle soit avec moi, qu’elle travaille avec moi, et que je sache ce qui vous est agréable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 11, 'Car elle sait et comprend tout; elle me dirigera avec prudence dans toutes mes œuvres; elle me gardera par sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 12, 'Et mes œuvres seront bien accueillies; et je jugerai votre peuple avec prudence, et je serai digne des trônes de mon père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 13, 'Car quel homme connaîtra le conseil de Dieu? Qui se mettra dans l’esprit ce que veut le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 14, 'Les pensées des mortels sont craintives, et nos projets mal assurés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 15, 'Car le corps corruptible appesantit l’âme, et la demeure terrestre déprime l’intelligence par la multiplicité des soins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 16, 'Et à peine pouvons-nous apprécier les choses qui sont sur la terre; et ce qui est en nos mains, nous le trouvons avec labeur. Mais les choses qui sont dans les cieux, qui saura les découvrir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 17, 'Qui connaît votre conseil, si vous ne lui avez donné la Sagesse, et si, d’en haut, vous ne lui avez envoyé votre Esprit-Saint?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 18, 'C’est lui qui redresse les sentiers de ceux qui cheminent sur la terre; c’est de lui que les hommes apprennent les choses qui vous sont agréables,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 19, 'Et par la Sagesse ils sont sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 1, 'C’est elle qui a conservé le premier créé, le père du monde, formé d’abord seul, et elle l’a tiré de sa propre chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 2, 'Elle lui a donné le pouvoir de maîtriser toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 3, 'Le méchant dans sa colère s’étant séparé d’elle, se perdit en même temps par des fureurs fratricides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 4, 'Inondée à cause de lui, la terre fut de nouveau sauvée par la Sagesse, qui fut le pilote du juste, voguant sur un bois de peu de prix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 5, 'C’est elle qui, lorsque toutes les nations furent unies en un même esprit de malice, choisit le juste, et le garda pur devant Dieu, et le fortifia contre les entrailles de sa tendresse pour son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 6, 'C’est elle, quand les méchants périrent, qui sauva un juste fuyant la descente du feu sur la Pentapole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 7, 'Et, en témoignage de leur perversité, cette terre demeure aride et fumante, et de ses arbres les fruits ne mûrissent pas; et une statue de sel est le mémorial de la femme incrédule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 8, 'Car ceux qui abandonnent la Sagesse, non-seulement se sont fait le tort de ne plus connaître le bien, mais encore ils ont laissé à la terre le mémorial de leur démence, de telle sorte qu’ils ne puissent même cacher en quoi ils avaient failli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 9, 'Au contraire, la Sagesse a tiré de peine ceux qui l’avaient servie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 10, 'C’est elle qui conduisit dans la voie droite le juste fuyant le courroux d’un frère; elle qui lui montra le royaume de Dieu, et lui donna la science des choses saintes; elle qui le récompensa de ses fatigues, et multiplia le fruit de ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 11, 'C’est elle qui l’assista contre la convoitise de ceux qui lui faisaient violence, et qui l’enrichit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 12, 'C’est elle qui le protégea contre ses ennemis, l’affermit contre les séducteurs, et lui décerna le prix d’une lutte pénible, pour lui apprendre que la piété est plus forte que toute chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 13, 'Elle ne délaissa point le juste qu’on avait vendu; mais elle le préserva du péché. Elle descendit avec lui dans la citerne;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 14, 'Et, dans la prison, elle ne l’abandonna point avant de lui avoir donné le sceptre royal et le pouvoir sur ceux qui le tyrannisaient. Elle convainquit de mensonge ses accusateurs, et lui assura une gloire éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 15, 'Elle délivra d’une nation qui l’opprimait un peuple saint, une race irréprochable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 16, 'Elle entra dans l’âme d’un serviteur de Dieu, et il tint tête à des rois redoutables, en faisant des signes et des prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 17, 'Elle rendit aux saints le salaire de leurs travaux; elle les guida dans une voie merveilleuse; elle fut pour eux comme un voile le jour, et la nuit comme la lumière des étoiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 18, 'Elle leur fit passer la mer Rouge et les conduisit à travers les grandes eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 19, 'Puis, ayant submergé leurs ennemis, elle les fit sortir du fond de l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 20, 'C’est pourquoi les justes s’emparèrent de la dépouille des impies, et ils chantèrent, ô Seigneur, votre saint nom, et louèrent tout d’une voix votre main tutélaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 21, 'Car la Sagesse a ouvert la bouche des muets, et a fait éloquente la langue des enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 1, 'Elle a dirigé leurs œuvres par les mains du saint prophète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 2, 'Ils ont parcouru un désert inhabité; ils ont dressé leurs tentes en des lieux infréquentés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 3, 'Ils ont tenu tête à leurs ennemis, et ils ont repoussé leurs adversaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 4, 'Ils ont eu soif, et ils vous ont invoqué; et, du sommet du rocher, l’eau a jailli pour eux; et le remède à leur soif est sorti de la pierre dure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 5, 'Par là, leurs ennemis ont été punis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 6, 'Par là, eux, dans leur détresse, ont été comblés de biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 7, 'Car, au lieu de la source intarissable du fleuve, les uns, tremblants, ont bu un sang immonde,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 8, 'Et ont été châtiés par le massacre ordonné de leurs petits enfants; mais aux autres vous avez donné une eau abondante et inespérée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 9, 'Vous avez montré alors, par cette soif, comment vous savez châtier vos ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 10, 'Car, lorsqu’ils eurent été tentés et qu’ils eurent été repris, quoique avec miséricorde, ils reconnurent combien souffrent les impies que vous jugez en votre courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 11, 'Mais eux, vous les avez éprouvés en les admonestant comme un père; et les autres, après les avoir interrogés, vous les avez condamnés comme un roi irrité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 12, 'Absents comme présents, les impies ont été pareillement torturés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 13, 'Car une double affliction les a saisis, et ils ont gémi en se souvenant du passé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 14, 'En effet, ils ont ouï que, par leur propre tourment, d’autres avaient reçu des bienfaits, et alors ils ont senti le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 15, 'Quand jadis il était entré en explication avec eux, ils l’avaient méconnu et raillé; mais ils ont été bien surpris de l’issue des événements, n’ayant pas eu la même soif que les justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 16, 'En expiation des faux raisonnements de leurs iniquités, qui les avaient égarés et entraînés à adorer des reptiles engourdis et des bêtes méprisables, vous leur avez envoyé une multitude d’animaux sans raison,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 17, 'Afin qu’ils sachent que l’on est puni par où l’on a péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 18, 'Votre main toute - puissante, la main qui, d’une matière informe, a créé le monde, n’aurait pas eu de peine à leur envoyer une multitude d’ours, de lions audacieux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 19, 'Ou de bêtes inconnues d’une nouvelle espèce, et pleines de rage: les unes soufflant un air enflammé ou une fumée infecte; les autres lançant de leurs yeux de terribles étincelles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 20, 'Telles que non-seulement leurs atteintes auraient pu les détruire, mais que leur aspect seul les eût frappés d’un effroi mortel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 21, 'Et sans cela même, un souffle eût suffi pour les abattre, poursuivis par votre justice et vannés au vent de votre puissance. Mais vous avez tout réglé avec poids et mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 22, 'Car c’est à vous qu’il appartient de prévaloir en tous lieux par la force; et qui donc résisterait à la puissance de votre bras?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 23, 'L’univers est devant vous comme le grain de sable qui fait pencher la balance, ou comme la goutte de rosée qui, le matin, descend sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 24, 'Mais vous avez pitié de tous, parce que vous pouvez tout; et vous feignez de ne point voir les péchés des hommes, en vue du repentir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 25, 'Vous aimez tous les êtres; vous n’avez en abomination rien de ce que vous avez créé, et vous n’avez rien préparé que vous dussiez haïr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 26, 'Quelle chose subsisterait, si vous ne le vouliez; ou durerait, si vous ne l’aviez appelée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 27, 'Mais vous pardonnez à tout, parce que tout vous appartient, ô Maître qui aimez les âmes!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 1, 'Votre Esprit en toute chose est infaillible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 2, 'Aussi, peu à peu vous réprimandez ceux qui tombent; vous avertissez les pécheurs, en ranimant leurs souvenirs, afin que, se corrigeant de leur malice, ils aient foi en vous, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 3, 'Car vous avez pris en haine les anciens habitants de votre terre sainte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 4, 'Parce qu’ils avaient fait les œuvres odieuses des enchanteurs, et qu’ils avaient des initiations impies;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 5, 'Parce qu’ils égorgeaient sans pitié leurs enfants, qu’ils mangeaient des entrailles humaines, et buvaient le sang au milieu de vos fêtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 6, 'Et qu’ils étaient ainsi pères et homicides d’âmes abandonnées; vous avez donc voulu les exterminer, par les mains de nos pères,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 7, 'Afin que cette terre qui, entre toutes, était la plus aimée de vous, devint un lieu de passage pour les enfants de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 8, 'Cependant vous avez eu pour eux des ménagements comme hommes; vous leur avez envoyé, comme les avant-coureurs d’une armée, des essaims de guêpes pour les détruire peu à peu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 9, 'Vous pouviez sans doute en une seule bataille soumettre les impies aux justes, ou les livrer à des bêtes terribles, ou les exterminer d’un seul mot;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 10, 'Mais, en les jugeant peu à peu, vous avez donné place au repentir, quoique n’ignorant pas qu’ils avaient une origine mauvaise, que la malice était chez eux innée, et que leur pensée ne changerait pas dans la suite des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 11, 'Leur race, en effet, dès le commencement était maudite, et nul égard ne vous portait à laisser leurs péchés impunis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 12, 'Car qui dira: Qu’avez-vous fait? Et qui se lèvera contre vos jugements? Qui vous imputera ce que vous avez fait aux nations que vous avez détruites? Et qui se posera devant vous comme vengeur des méchants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 13, 'Nul, hormis vous, n’est Dieu; vous seul prenez soin de toutes choses, pour montrer que vous ne jugez pas injustement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 14, 'Il n’est point de roi ou de tyran qui puisse vous reprocher en face ceux que vous avez perdus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 15, 'Mais vous êtes juste, et vous gouvernez avec justice; et vous estimez indigne de votre vertu de punir celui qui ne doit pas être puni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 16, 'Car votre force est le commencement de la justice, et le pouvoir que vous avez sur tout vous fait tout épargner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 17, 'Vous montrez cette force à ceux qui doutent de la perfection de votre vertu, et vous punissez l’audace de ceux qui la connaissent et la bravent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 18, 'Maître de votre force, vous jugez avec douceur et vous nous gouvernez avec beaucoup de ménagements; car il vous appartient de pouvoir quand vous voulez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 19, 'Et, par de telles œuvres, vous avez appris à votre peuple qu’il doit être juste et humain, et vous avez rempli vos fils d’espérance, en leur donnant le repentir après leurs fautes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 20, 'Mais si en punissant les ennemis de vos enfants, voués justement à la mort, vous y avez mis tant de prudence et d’égards; si vous leur avez accordé le temps et l’occasion de se corriger de leur malice,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 21, 'Avec quelle attention n’avez-vous pas jugé vos fils, en faisant avec leurs pères des alliances et des serments de bonnes promesses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 22, 'Lors donc que vous nous corrigez, vous flagellez de mille manières nos ennemis, afin que, jugeant, nous songions à votre amour, et que, jugés, nous espérions en votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 23, 'De là vient aussi que vous avez fait souffrir, à cause de leurs abominations, les méchants qui avaient vécu dans la folie et l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 24, 'Ils s’étaient au loin égarés dans les voies de l’erreur, prenant pour dieux les plus vils des animaux malfaisants, égarés comme des enfants sans raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 25, 'Ainsi les avez-vous frappés d’un jugement dérisoire, comme des enfants insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 26, 'Et ceux que n’ont point avertis les dérisions de la réprimande, ont fait l’épreuve d’un jugement digne de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 27, 'Touchés de leurs souffrances, ils se sont indignés contre ce qu’ils croyaient des dieux; châtiés par eux, ils ont reconnu que ce Dieu qu’ils avaient d’abord rejeté est le vrai Dieu, et c’est ainsi que la fin de leur condamnation est venue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 1, 'Tous les hommes, en qui est l’ignorance de Dieu, sont vains par nature; ayant vu le bien, ils n’ont pu connaître Celui qui est; ayant considéré les œuvres, ils n’ont pas connu l’artisan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 2, 'Ils ont regardé comme des dieux, régulateurs du monde, soit le feu, soit le vent, soit l’air mobile, soit le cercle des étoiles, soit l’onde impétueuse, soit les luminaires du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 3, 'Si, charmés de leur beauté, ils les ont pris pour des dieux, qu’ils comprennent combien est plus beau le maître, puisque le créateur même de la beauté a créé ces êtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 4, 'S’ils ont été émerveillés de leur force et de leur énergie, qu’ils songent combien celui qui les a mis en ordre est plus fort qu’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 5, 'Car il est visible qu’à la grandeur et à la beauté des créatures correspondent la grandeur et la beauté du Créateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 6, 'Mais enfin, à ces hommes il y a d’abord peu de reproches à faire; car ils s’égarent facilement, cherchant Dieu et le voulant trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 7, 'Attirés par ses œuvres, ils s’enquièrent et ont foi en l’apparence, tant ce qu’ils voient est beau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 8, 'Mais ensuite, s’ils persistent, ils sont impardonnables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 9, 'Car s’ils ont pu en savoir assez pour estimer les choses du temps, comment ont-ils tardé à trouver celui qui en dispose?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 10, 'Mais ceux-là sont malheureux (et leur espérance est parmi les morts), qui ont appelé Dieu des ouvrages de la main des hommes, or ou argent, productions de l’art, images des animaux ou pierre inerte, travail d’un artisan irréfléchi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 11, 'Si quelque ouvrier habile à travailler le bois, ayant scié un arbre facile à tourner, l’a dépouillé adroitement de son écorce et en a fait un meuble utile aux usages de la vie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 12, 'Les rebuts de son œuvre, il les a pris pour apprêter ses aliments, et il s’est rassasié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 13, 'Et ce qu’il en doit rejeter encore, ce qui n’est bon à rien, le bois tortu et noueux, il l’a pris, il l’a sculpté avec soin, à ses heures de loisir; il lui a donné une figure avec la science de son art: il en a reproduit l’image d’un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 14, 'Ou bien il en a fait là ressemblance de quelque vil animal; puis il l’a frotté de vermillon, il l’a fardé de rouge, et il en a masqué tous les défauts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 15, 'Ensuite il a fait dans son mur une niche digne de son œuvre; il l’y a posé, et il l’a assujetti avec du fer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 16, 'De peur qu’il ne vînt à tomber; il a tout prévu pour lui, sachant qu’il ne pourrait s’aider lui-même, puisque ce n’est qu’une image ayant besoin d’appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 17, 'Enfin, il le prie pour ses biens, ses noces, ses enfants; il n’a point honte de parler à cette chose sans âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 18, 'Il invoque pour sa santé ce qui est infirme, et pour sa vie ce qui est mort; il appelle à son aide l’objet le plus inerte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 19, 'Veut-il faire un voyage, il s’adresse à ce qui ne peut se tenir sur ses pieds; veut-il acheter ou faire œuvre de ses mains, il implore l’habileté des mains les plus inhabiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 1, 'D’autre part, un homme se met en mer; il est sur le point de traverser les flots indomptés; il invoque à grands cris un bois plus frêle que le navire qui le porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 2, 'Car c’est là ce que le désir du gain a inventé, et la sagesse de l’artisan l’a ainsi préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 3, 'Mais vous, ô Père, votre providence gouverne ellemême; car vous avez donné une voie à la mer, et des sentiers certains sur les vagues,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 4, 'Montrant que partout il est en votre pouvoir de sauver, lors même qu’on ose s’embarquer sans le secours de l’art.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 5, 'Vous avez voulu que nulle des œuvres de votre sagesse ne fût inutile; c’est pour cela que les hommes confient leur âme à un peu de bois, et que, fendant les vagues');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 6, 'Et, au commencement, quand furent exterminés les géants superbes, l’espérance du monde, réfugiée dans une arche, conserva au monde la semence de la génération d’où il devait naître, en la confiant à votre main qui l’avait dirigée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 7, 'Car le bois est béni, par lequel justice est faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 8, 'Mais le bois que la main a façonné est maudit, lui et l’homme qui a fait l’œuvre: l’un pour y avoir travaillé, l’autre parce que, quoique corruptible, elle a été appelée Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 9, 'Car Dieu hait pareillement et l’impie et son impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 10, 'Et l’œuvre sera condamnée, de même que l’artisan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 11, 'C’est pourquoi aussi les idoles des gentils ne seront pont épargnées; en effet, elles sont pour la création de Dieu une souillure; pour les âmes des hommes, un piége; pour les pieds des insensés, un filet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 12, 'La pensée de faire des idoles est le principe de la prostitution; leur invention est la perdition de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 13, 'Car, au commencement, l’idolâtrie n’était point, et elle ne sera pas toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 14, 'Elle est venue dans le monde par la vanité des hommes, et c’est pourquoi on a senti que la fin en serait prochaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 15, 'Un père accablé d’une douleur excessive par la perte prématurée de son fils a fait faire son image; et celui qui était tout à l’heure un homme mort, il l’a honoré comme un Dieu, et il a confié à des serviteurs ses mystères et ses initiations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 16, 'Avec le temps, cette coutume impie, s’étant fortifiée, a été gardée comme loi; et, par l’ordre des tyrans, des statues ont été adorées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 17, 'Ceux que les hommes ne pouvaient honorer en face, parce qu’ils habitaient au loin, ils en ont fait prendre l’image, et ont exposé à tous les regards la statue d’un roi qu’ils voulaient vénérer, afin que, présent ou absent, ils le flattassent avec le même zèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 18, 'De plus, l’émulation de l’artiste attira les ignorants dans l’égarement de cette superstition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 19, 'Car, voulant s’empresser de plaire au maître, il s’efforça par son art d’embellir le modèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 20, 'Et la multitude, séduite par la grâce de l’œuvre, honora d’un culte celui que naguère elle honorait comme un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 21, 'Et ce fut le piège où tombèrent les humains; soit hasard, soit servilité envers la tyrannie, ils donnèrent à la pierre ou au bois un nom qui ne pouvait lui appartenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 22, 'Ensuite il ne leur suffit pas d’avoir erré dans la connaissance de Dieu; mais, vivant dans la rude bataille de l’ignorance, ils donnèrent le nom de paix à tant et de si grands maux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 23, 'Soit en des initiations infanticides, soit en de secrets mystères, soit emportés, selon les lois, en des orgies furieuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 24, 'Ils ne gardent plus aucune pureté, ni dans la vie ni dans le mariage: l’un tue l’autre en une embuscade, ou l’afflige par l’adultère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 25, 'Tout est pêle-mêle, sang et meurtre, larcin et fraude, perdition, perfidie, trouble, parjure, persécution des justes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 26, 'Oubli de la grâce, souillure des âmes, confusion des naissances, dérèglement dans le mariage, adultère et débauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 27, 'Le culte d’idoles infâmes est le principe, la cause et le comble des maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 28, 'Les joies de ceux qui les adorent sont des fureurs, leurs prophéties des mensonges, leur vie une suite d’iniquités, et ils sont toujours prêts à se parjurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 29, 'En se confiant à des images sans âme, en prêtant de faux serments, ils ne croient pas se nuire à eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 30, 'Un double et juste châtiment les atteindra, parce qu’ils ont de Dieu une idée mauvaise en s’attachant aux idoles, et parce que, au mépris de toute sainteté, ils ont juré dans un esprit de fraude');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 31, 'Car ce n’est point la puissance de ceux par qui on a juré, mais la justice infligée au péché, qui s’élève toujours contre l’iniquité des prévaricateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 1, 'Mais vous, ô mon Dieu, vous êtes bon et vrai; vous êtes patient, et vous gouvernez toutes choses avec miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 2, 'Lors même que nous péchons, nous ne cessons pas d’être à vous, connaissant votre puissance; et si nous ne péchons pas, nous savons que nous sommes comptés parmi ceux qui vous appartiennent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 3, 'Vous connaître, c’est la parfaite justice; connaître votre puissance, c’est la racine de l’immortalité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 4, 'Pour nous, les inventions de l’art dépravé des hommes ne nous ont pas égarés, ni le travail stérile des peintres, image d’une sculpture aux couleurs changeantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 5, 'Leur vue seule cause la honte des insensés; car ils se passionnent pour une image morte, pour une apparence inanimée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 6, 'Les hommes amis du mal sont dignes de tels dieux, et ceux qui ont fait ces dieux, et ceux qui les aiment, et ceux qui les adorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 7, 'Le potier, en pétrissant de la terre molle, à grand\' peine façonne toute chose à notre usage; il fait avec la même argile les vases qui servent aux œuvres pures et aux œuvres qui ne le sont pas, et il juge à quoi chacun d’eux sera employé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 8, 'Ensuite, par un vain labeur, avec la même argile, il fait un dieu, lui qui, tout à l’heure né de la terre, ne tardera pas à retourner d’où il est sorti, quand on lui réclamera la dette de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 9, 'Mais ce qui le préoccupe, ce n’est pas la fatigue, ni la brièveté de sa vie, c’est de rivaliser avec le sculpteur en or ou en argent, et d’imiter le fondeur en cuivre; et il estime comme une gloire d’avoir fait une œuvre trompeuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 10, 'Son cœur est cendre; son espérance est plus vile que la terre, et sa vie plus méprisable que la boue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 11, 'Parce qu’il a méconnu Celui qui l’a créé, qui l’a doué d’une âme créatrice, qui l’a inspiré de l’esprit de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 12, 'Mais ils se sont imaginé que notre vie est un jeu d’enfants, et notre conduite un divertissement lucratif; il faut, dit-on, acquérir n’importe comment, même par le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 13, 'Car ce potier sait mieux que personne qu’il pèche en fabriquant avec une matière terrestre des idoles et des vases fragiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 14, 'Mais tous les ennemis de votre peuple, ceux qui ont dominé sur lui, sont plus malheureux et plus insensés que l’enfant qui vient de naître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 15, 'En effet, ils ont réputé dieux toutes les idoles des gentils, qui ne font point usage de leurs yeux pour voir, ni de leurs narines pour respirer l’air, ni de leurs oreilles pour entendre, ni des doigts de leurs mains pour toucher, ni de leurs pieds inertes pour se mouvoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 16, 'Car un homme les a forgées, les a façonnées, lui qui avait reçu l’intelligence: or nul homme n’a le pouvoir de faire un dieu semblable à lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 17, 'Mortel, il fait de sa main inique un mort; il vaut mieux lui-même que ce qu’il vénère, puisque, ayant reçu l’être, il a vécu, et ses dieux, jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 18, 'Cependant on honore d’un culte les animaux les plus vils; car, comparés aux autres, ils les dépassent en stupidité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 19, 'Aussi rien de bien n’arrive à qui n’a d’autre désir que de contempler les bêtes; celui-là fuit les louanges de Dieu et sa bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 1, 'C’est pourquoi les gentils ont été justement châtiés par des êtres semblables; ils ont été tourmentés par une multitude de bêtes malfaisantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 2, 'Au lieu de ces corrections, vous avez donné des biens à votre peuple; en sa concupiscence d’appétit, vous lui avez préparé pour sa nourriture des râles, des cailles d’une saveur exquise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 3, 'Tandis que les désirs des Égyptiens, quand le besoin d’aliments les sollicitait, étaient détournés par l’horreur des plaies qui leur étaient envoyées, votre peuple, après une courte détresse, se délectait d’une exquise nourriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 4, 'Ceux-là, en punition de leur tyrannie, devaient souffrir d’une indigence sans remède; à ceux-ci vous vous borniez à leur faire voir comment leurs ennemis étaient tourmentés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 5, 'Sur eux aussi, à la vérité, se tourna la rage furieuse d’animaux terribles; ils furent mordus par des serpents tortueux, mais votre colère ne persista pas au point de les détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 6, 'Ils furent un moment troublés par cet avertissement, et ils élevèrent un signe de salut, comme mémorial de votre loi que vous leur aviez intimée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 7, 'Et celui qui se convertissait n’était point sauvé pour avoir regardé ce signe, mais à cause de vous, Sauveur universel!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 8, 'Et de cette manière vous avez convaincu nos ennemis que vous êtes celui qui délivre de tout mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 9, 'Car les morsures des sauterelles et des mouches avaient tué les Égyptiens, et il ne s’était point trouvé de guérison pour leurs âmes, parce qu’ils méritaient d’être punis comme ils l’avaient été.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 10, 'Mais vos enfants ne furent point vaincus par les dents venimeuses des dragons, parce que votre miséricorde survint et les guérit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 11, 'Pour qu’ils se souvinssent de vos commandements, ils avaient été aiguillonnés; mais ils furent promptement guéris, de peur que, tombant dans un profond oubli, ils ne pussent jouir de vos bienfaits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 12, 'Or il n’y eut ni herbe ni émollient qui les guérît; mais, ô Seigneur, ce fut votre Parole, cette Parole qui guérit tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 13, 'Car vous avez pouvoir de vie et de mort; vous conduisez aux portes de l’enfer, et vous en ramenez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 14, 'Un homme tue dans sa perversité, et l’âme, une fois sortie, ne revient pas; et cet homme ne peut la rappeler pour la prendre de nouveau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 15, 'Mais il est impossible d’échapper à votre main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 16, 'Les impies, refusant de vous connaître, ont été flagellés par la force de votre bras; ils ont été persécutés par des plaies surnaturelles, par de la grêle, par des orages, et ils ont été dévorés par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 17, 'Et, merveille suprême! le feu redoublait de fureur au milieu de l’eau qui éteint tout; car l’univers est l’auxiliaire des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 18, 'Ainsi, il advint que la flamme s’adoucit pour ne point consumer les bêtes envoyées contre les impies, et pour qu’eux-mêmes, ouvrant les yeux, vissent qu’ils étaient poursuivis par la justice de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 19, 'Or il advint encore qu’au milieu même de l’eau le feu s’enflammait d’une force nouvelle, pour détruire les rejetons d’une terre inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 20, 'Au contraire, vous avez distribué à votre peuple le pain des anges; vous avez envoyé pour lui le pain du ciel préparé sans labeur, plein de délices et en harmonie avec tous les goûts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 21, 'Cette substance, venue de vous, manifesta votre bonté pour vos enfants; et, se conformant aux désirs de ceux qui la mangeaient, elle prit le goût que chacun voulait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 22, 'Au contraire, c’était pour vos ennemis une neige, une glace qui résistait au feu sans se fondre; et l’on n’ignorait pas que la flamme, en consumant les fruits des Égyptiens, brûlait au milieu de la grêle, et resplendissait au milieu des pluies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 23, 'Et encore, pour que les justes fussent nourris, le feu oubliait même sa vertu propre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 24, 'Car la créature, soumise à son Créateur, trouve des forces nouvelles pour le châtiment des hommes iniques, et s’adoucit pour le bien de ceux qui croient en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 25, 'C’est pourquoi la manne, en se transformant de toute manière, servait votre grâce nourricière de toutes choses, au gré des désirs de ceux qui la désiraient;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 26, 'Afin que les enfants aimés de vous, Seigneur, apprissent que ce n’est point le fruit qui nourrit l’homme, mais que votre Parole conserve ceux qui mettent leur confiance en vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 27, 'Car cette substance, que le feu ne détruisait pas, fondait rapidement à la chaleur d’un faible rayon de soleil;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 28, 'Afin qu’il fût notoire que l’on doit devancer le soleil pour vous rendre grâces, et vous adorer avant la lumière du matin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 29, 'Car l’espérance de l’ingrat se dissipe comme le givre en hiver; elle s’écoule comme une onde inutile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 1, 'Vos jugements sont grands et inénarrables; c’est pourquoi des âmes sans discipline se sont égarées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 2, 'Des pervers croyaient opprimer le peuple saint; mais eux-mêmes, enclos dans leurs demeures, enchaînés par les ténèbres, esclaves de la profonde nuit, ils se couchèrent, cherchant à fuir l’éternelle Providence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 3, 'Et, tandis qu’ils s’imaginaient tenir cachés leurs péchés secrets, ils ont été dispersés, revêtus des sombres voiles de l’oubli, frappés d’un effroi terrible, troublés par de lugubres apparitions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 4, 'Car il n’y eut point de réduit assez profond pour les recevoir et les sauver de la terreur, parce que des bruits sinistres les étourdissaient, et que de mornes fantômes leur montraient des fronts sans sourire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 5, 'Et il n’y eut point de flamme assez éclatante pour les éclairer, et les feux scintillants des étoiles ne continuèrent pas à briller durant cette nuit lamentable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 6, 'Il n’y eut de visible pour eux qu’un feu spontané, plein d’épouvantements; et terrifiés par une apparition qu’ils ne voyaient pas, les choses qu’ils voyaient leur semblaient pires qu’elles ne sont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 7, 'Alors on laissa de côté les illusions de l’art magique, et l’on repoussa avec mépris l’arrogance de ceux qui vantaient leur sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 8, 'Car ceux qui, habituellement, promettaient de bannir des âmes malades la crainte et l’inquiétude, étaient eux-mêmes malades d’une terreur ridicule,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 9, 'N’y eût-il rien qui dût les troubler; mis en fuite par le pas des bêtes ou le sifflement des reptiles, ils périssaient tout tremblants; ils n’osaient plus même regarder l’air que nulle part on ne peut éviter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 10, 'Car la méchanceté, naturellement craintive, se condamne par son propre témoignage; et, pressée par la conscience, elle attire d’avance sur elle des peines affligeantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 11, 'Car la crainte n’est autre chose que la défaillance des secours de la raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 12, 'Et moins on a d’espérance en dedans, plus on calcule, sans les connaître, les causes de ses tourments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 13, 'Ces hommes cependant, durant cette nuit d’effroi, venue des abîmes effroyables de l’enfer, et plongés dans un même sommeil,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 14, 'D’une part, étaient poursuivis par la vision de fantômes; d’autre part, étaient énervés par la défaillance de leurs âmes: aussi furent-ils saisis d’une terreur soudaine et imprévue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 15, 'Et si l’un d’eux venait à tomber, n’importe où, il restait là enfermé dans cette prison sans fers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 16, 'Laboureur, pâtre, journalier travaillant dans le désert, s’il était surpris, demeurait là, contraint par une inflexible nécessité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 17, 'Car tous étaient retenus par une même chaîne de ténèbres. Le doux chant des oiseaux dans les arbres touffus, le bruit cadencé de l’eau courant avec force,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 18, 'Le fracas étrange des rochers qui s’écroulaient, la course des animaux bondissant inaperçus, les voix des bêtes farouches, l’écho répété par le creux des montagnes, les glaçaient de terreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 19, 'Le monde entier jouissait d’une lumière sereine, et se livrait sans entrave à ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 20, 'Eux seuls étaient accablés sous le poids d’une profonde nuit, image des ténèbres qui leur étaient réservées, et ils étaient pour eux-mêmes plus importuns que les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 1, 'Cependant la plus vive lumière brillait pour vos saints; ils entendaient les cris des Égyptiens sans voir leur visage, et ils se glorifiaient de ne point souffrir comme eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 2, 'Et ils vous rendaient grâces de ce que ceux qui les avaient maltraités ne pouvaient plus leur nuire; et ils demandaient comme une faveur qu’il y eût cette différence entre eux et leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 3, 'Et c’est pourquoi vous leur avez donné une colonne ardente pour les conduire dans une terre inconnue, soleil tempéré d’un voyage rempli de vos bienfaits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 4, 'Mais les Égyptiens méritaient d’être privés de lumière et d’être emprisonnés dans les ténèbres, pour avoir retenus enfermés vos enfants, par qui la lumière inaltérable de votre loi devait être répandue dans le siècle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 5, 'Et comme ils avaient résolu de faire périr les enfants des saints, un de ces enfants ayant été exposé et sauvé, pour leur opprobre, vous avez frappé la multitude de leurs fils; et eux, vous les avez tous submergés sous les flots impétueux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 6, 'Cette nuit avait été annoncée à nos pères, afin qu’instruits avec certitude par des serments auxquels ils crurent, ils eussent bon courage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 7, 'Votre peuple fut témoin à la fois du salut des justes et de la ruine de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 8, 'Car, en même temps, vous avez puni ces derniers, et nous, vous nous avez appelés et bénis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 9, 'Les saints enfants des bons offraient en secret leurs sacrifices; ils établissaient d’un sentiment unanime cette loi divine, que les saints participeraient également au bien et au mal; et déjà ils chantaient les louanges de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 10, 'Cependant résonnait la voix confuse des ennemis, pleurant amèrement la mort de leurs fils premiers-nés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 11, 'L’esclave et le maître étaient frappés du même châtiment; le peuple et le roi souffraient de la même peine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 12, 'Tous à la fois n’entendaient d’autre nom que la mort; ils avaient sous les yeux une multitude innombrable de cadavres, et les survivants étaient sans force pour les ensevelir; car, en un instant, le plus précieux de leur race venait d’être exterminé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 13, 'A cause de leurs enchantements, ils n’avaient pas d’abord été convaincus; mais après l’extermination de leurs premiers--nés, ils reconnurent que ce peuple était fils de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 14, 'Car un profond silence enveloppait toutes choses, et la nuit était au milieu de son cours,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 15, 'Quand la parole du Tout-Puissant, adversaire sans pitié, jaillit du trône royal des cieux au milieu de cette terre perdue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 16, 'Portant le glaive rapide de votre commandement, sans détour elle s’arrêta, et soudain elle remplit tout de mort; et elle touchait au ciel, et elle marchait sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 17, 'Alors les terribles visions des songes les troublent soudain; alors des épouvantements imprévus les arrêtent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 18, 'Ils tombent épars à demi morts, et reconnaissent la cause qui les a fait mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 19, 'Car les songes qui les ont troublés la leur ont fait connaître, afin qu’en mourant ils sussent d’où leur venaient ces maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 20, 'L’épreuve de la mort atteignit aussi les justes, et un grand nombre fut frappé dans le désert; mais votre colère ne dura qu’un moment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 21, 'Car un homme irréprochable se hâta d’intercéder pour eux; revêtu de l’armure de son propre sacerdoce, de la prière et de l’encens de l’expiation, il s’opposa à votre colère, et mit fin à cette calamité en se montrant serviteur de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 22, 'Il triompha de votre colère, non par la force du corps ni par la force des armes, mais par la parole il subjugua l’ange exterminateur, en lui rappelant le souvenir de l’alliance de Dieu et de ses promesses à nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 23, 'Il y avait déjà, çà et là, des monceaux de cadavres, quand il se mit entre Dieu et le peuple, et arrêta le courroux du Seigneur et l’empêcha d’aller à ceux qui vivaient encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 24, 'Car le monde entier était dans sa robe sacerdotale, et la gloire des patriarches sur les quatre rangs de pierres gravées, et votre magnificence, ô Seigneur, sur le diadème de sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 25, 'A ces signes, l’exterminateur s’arrêta, et le peuple en trembla de crainte; car cette seule épreuve de votre colère suffisait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 1, 'Au contraire, un impitoyable courroux resta suspendu jusqu’à la fin sur les impies; car le Seigneur avait prévu ce qu’ils devaient faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 2, 'En effet, après s’être convertis pour laisser partir le peuple, et l’avoir congédié avec empressement, les Égyptiens se repentent et le poursuivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 3, 'Plongés encore dans le deuil, arrosant de leurs larmes les sépulcres des morts, ils se laissent entraîner par un autre calcul de démence; et ceux qu’ils avaient renvoyés en les suppliant, ils les poursuivent comme des fugitifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 4, 'Une juste nécessité les poussait à cette fin; et l’oubli de ce qui venait d’arriver les abusait, afin que le châtiment achevât ce qui manquait à leurs tortures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 5, 'Et que votre peuple fit l’essai d’une voie miraculeuse, tandis qu’eux-mêmes allaient trouver un genre de mort inconnu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 6, 'Car alors toute créature reçut d’en haut, sans changer de nature, une forme nouvelle, en obéissant à vos ordres, afin que vos fils échappassent sains et saufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 7, 'Une nuée ombragea leur camp, et, à la place où l’eau était auparavant, on vit une issue à travers la terre sèche, une voie facile dans la mer Rouge, et un champ verdoyant au fond des flots;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 8, 'Par où, tous à la fois, ceux que votre main abritait passèrent en contemplant ces merveilleux prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 9, 'Ils étaient en un pâturage comme des chevaux; ils bondissaient comme des agneaux en vous louant, Seigneur, vous qui les sauviez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 10, 'Ils se rappelaient encore les faits qui avaient eu lieu en la terre de leur passage: les moucherons produits par les champs, au lieu des animaux habituels; le fleuve vomissant une multitude de grenouilles, au lieu de poissons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 11, 'Plus tard, ils virent une nouvelle espèce d’oiseaux, lorsque, dans leur concupiscence, ils demandèrent des mets délicats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 12, 'Au gré de leurs désirs, Dieu fit lever pour eux de la mer des râles de cailles, dans le même temps que le châtiment atteignait les pécheurs, non sans en avoir été avertis par de grands coups de tonnerre; mais ils souffraient justement à cause de leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 13, 'Car ils avaient été inhospitaliers de la manière la plus cruelle; en effet, ce n’étaient point des inconnus qu’ils avaient accueillis, mais des hôtes bienfaisants qu’ils avaient réduits en esclavage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 14, 'Et ce n’est pas tout: une autre considération, c’est que c’était un peuple étranger qu’ils avaient traité indignement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 15, 'Après avoir reçu au milieu des fêtes ceux qui étaient accoutumés déjà à vivre sous leurs lois, ils les ont accablés de cruels travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 16, 'Mais ils ont été frappés d’aveuglement, comme ceux qui, devant la porte d’un juste, enveloppés de ténèbres impénétrables, cherchaient tous la porte de leur propre demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 17, 'Les éléments furent métamorphosés en leur essence, comme dans la harpe les tons du rhythme changent de nom, quoique le son subsiste; comparaison qui montre exactement ce qui alors se passa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 18, 'Les animaux terrestres furent transformés en poissons; ceux qui nageaient marchèrent à terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 19, 'Le feu redoubla d’énergie au milieu de l’eau, et l’eau ne se souvint plus de son pouvoir d’éteindre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 20, 'Les flammes, en revanche, ne consumaient pas les chairs des faibles animaux qui les traversaient; elles ne fondaient pas l’aliment divin, quoiqu’il fût aussi facile à fondre que la glace;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 21, 'car, Seigneur, vous avez grandi votre peuple en toutes choses; vous l’avez glorifié, loin de le mépriser; vous l’avez assisté en tout temps et en tout lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Toute sagesse vient du Seigneur; elle est avec lui de toute éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Qui comptera le sable de la mer, les gouttes de pluie et les jours de l’éternité? La hauteur des cieux, et l’étendue de la terre et l’abîme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Et la sagesse: qui les découvrira?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'La sagesse a été créée avant toutes choses, et la lumière de la raison est née dès le commencement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, '(Vulg. 6.) À qui la racine de la sagesse a-t-elle été dévoilée? Qui en connaît les voies mystérieuses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, '(8.)Un seul est sage, infiniment terrible, assis sur son trône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, '(9.)Le Seigneur lui-même a créé la sagesse, et l’a vue et l’a mesurée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, '(10.)Et il l’a répandue sur toutes ses œuvres; elle est avec toute chair, selon qu’il l’a donnée, et il l’a libéralement distribuée à ceux qui l’aiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, '(11.)La crainte du Seigneur est une gloire et un titre d’orgueil; c’est une joie et une couronne d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, '(12.)La crainte du Seigneur charme l’âme; elle donne paix, joie et longue vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, '(13.)Celui qui craint le Seigneur prospèrera jusqu’à la fin, et le jour de sa mort il trouvera grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, '(16.)La crainte de Dieu est le commencement de la sagesse; elle a été créée avec les fidèles dans le sein de leur mère. Elle réside avec les hommes dès le berceau du monde, et les races futures croiront en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, '(20.)La crainte du Seigneur est la plénitude de la sagesse; elle enivre les hommes de ses fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, '(21.)Elle remplira toute sa maison de trésors désirables, et ses greniers de récoltes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, '(22.)La crainte du Seigneur est la couronne de la sagesse; elle fait fleurir la paix et la santé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, '(23.)Et le Seigneur l’a vue, et il l’a mesurée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '(24.) Elle a versé, comme des torrents de pluie, la science et la lumière de la raison;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 18, 'Elle a relevé la gloire de ceux qui l’embrassent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 19, '(25.) La crainte du Seigneur est la racine de la sagesse, et ses rameaux ont de longs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 20, '(28.)Le cœur inique ne pourra être justifié, car le moindre mouvement de sa colère est sa chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 21, '(29.)L’homme patient tiendra bon jusqu’à l’heure opportune; et, à la fin, la joie lui sera rendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 22, '(30.)Jusqu’à l’heure opportune, il retiendra ses paroles, et les lèvres des fidèles publieront sa prudence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 23, '(31.) La parabole de la science est dans les trésors de la sagesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 24, '(32.)La piété est en abomination aux pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 25, '(33.)Désires-tu la sagesse? garde les commandements, et le Seigneur te la donnera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 26, '(34.)Car la crainte du Seigneur est la sagesse et la discipline, et ce qui lui plaît,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 27, '(35.)C’est la foi et la douceur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 28, '(36.)Ne te défie pas de la crainte du Seigneur, et garde-toi de t’approcher de lui avec un cœur double.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 29, '(37.)Ne sois pas hypocrite en présence des hommes, et veille sur tes lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 30, '(38.)Ne t’élève pas, de peur de tomber, et de conduire ton âme à l’humiliation. (39.)Le Seigneur alors révélerait tes secrets, et te briserait au milieu même de la synagogue. (40.)Parce que tu ne te serais pas approché de lui avec crainte, mais avec un cœur manquant de sincérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Mon fils, si tu t’approches pour servir le Seigneur Dieu, prépare ton âme à la tentation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Dirige vers lui ton cœur, fortifie-le, et ne hâte point le moment de la délivrance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Attache-toi étroitement à Dieu, et ne t’en éloigne pas, afin de grandir jusque dans tes derniers jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Accepte tout ce qui te surviendra, et sois patient dans les vicissitudes de ton humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Car l’or est éprouvé par le feu, et les hommes agréables à Dieu sont éprouvés au foyer de l’humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Aie confiance en Dieu, et il te protégera; dirige vers lui ta voix, et mets en lui ton espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Ô vous qui craignez le Seigneur, attendez sa miséricorde. Ne déviez pas, si vous ne voulez pas tomber.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Ô vous qui craignez le Seigneur, ayez foi en lui, et la récompense ne vous manquera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Ô vous qui craignez le Seigneur, espérez en ses biens, et en la joie de l’éternité et de la miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, '(Vulg. 11.)Considérez les générations antiques et jugez: qui a mis sa confiance dans le Seigneur, et a été confondu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, '(12.)Qui a persévéré dans la crainte de Dieu, et a été délaissé? Qui, l’ayant invoqué, a été méprisé de lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 12, '(13.)Car le Seigneur est compatissant et miséricordieux, et il remet les péchés, et il sauve au temps de la tribulation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 13, '(14.)Malheur aux cœurs faibles, et aux mains négligentes, et au pécheur qui chemine par deux sentiers!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 14, '(15.)Malheur à l’âme indolente, parce qu’elle manque de foi! elle ne sera point abritée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 15, '(16.)Malheur à vous qui avez perdu la patience! (17.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 16, 'Que ferez-vous quand le Seigneur viendra vous visiter?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 17, '(18.)Ceux qui craignent le Seigneur ne seront pas incrédules à ses paroles, et ceux qui l’aiment garderont ses voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 18, '(19.)Ceux qui craignent le Seigneur chercheront son bon plaisir, et ceux qui l’aiment seront pénétrés de sa loi. (20.)Ceux qui craignent le Seigneur prépareront (21.)Nous tomberons dans les mains du Seigneur, et non dans celles des hommes. (22.)Car autant il a de grandeur, autant il a de miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, '(Vulg. 2.) Enfants, écoutez les leçons de votre père, et faites ainsi, afin d’être sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '(3.)Car le Seigneur a honoré le père dans ses fils, et il a affermi sur le fils l’autorité de la mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, '(4.)Celui qui honore son père sera purifié de ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, '(5.)Celui qui glorifie sa mère est comme l’homme qui amasse un trésor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, '(6.)Celui qui honore son père sera réjoui dans ses enfants, et le jour où il priera, il sera exaucé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, '(7.)Celui qui glorifie son père vivra longuement. (8.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Et celui qui écoute docilement le Seigneur sera le soutien de sa mère, et il servira comme ses maîtres ceux qui l’ont engendré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, '(9.)Honore ton père en œuvres et en paroles, (10.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Afin que sa bénédiction vienne sur toi. (11.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'La bénédiction d’un père rend inébranlable la maison des enfants; la malédiction d’une mère en déracine les fondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 11, '(12.)Ne te glorifie pas en l’opprobre de ton père; car sa honte n’est pas une gloire pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 12, '(13.)En effet, la gloire de l’homme vient de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 13, '(14.)Enfant, sois l’appui de ton père en sa vieillesse, et ne le contriste pas en sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 14, '(15.)Et lors même que son intelligence faiblirait, sois indulgent pour lui, et ne l’outrage point, toi qui es dans toute la force de la raison. Car la miséricorde envers un père ne sera point oubliée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 15, '(16.)Et, en te pardonnant tes péchés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 16, '(17.)Elle t’affermira dans la justice. Au jour de la tribulation, le Seigneur se souviendra de toi; et comme la glace fond au soleil, ainsi tes péchés s’évanouiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 17, '(18.)Celui qui abandonne son père est comme un blasphémateur, et celui qui irrite sa mère est maudit du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 18, '(19.)Enfant, accomplis tes œuvres avec douceur, et tu seras aimé de l’homme agréable à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 19, '(20.)Plus tu es grand, plus tu dois t’humilier, et tu trouveras grâce devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 20, '(21.)Car la puissance du Seigneur est grande; c’est par les humbles qu’elle est glorifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 21, '(22.)Ne cherche point ce qui est trop difficile pour toi; ne t’informe point de ce qui est plus fort que toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 22, '(23.)Songe à ce qui t’est prescrit; tu n’as que faire des choses cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 23, '(24.)Ne sois point curieux de ce qui est inutile à tes œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 24, '(25.)Car il t’a été révélé plus que ne le comporte l’intelligence des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 25, '(26.)Et beaucoup ont été égarés dans leurs recherches, et de mauvaises pensées ont fait chanceler leur esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 26, '(27.)Qui aime le péril, y périra; un cœur dur aura une mauvaise fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 27, '(29.)Un cœur dur succombera sous le poids des peines, et le pécheur amassera péchés sur péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 28, '(30.)Il n’est point de remède aux séductions de l’orgueil; car le germe de la méchanceté a pris racine en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 29, '(31.)Le cœur de l’homme sensé comprend les paraboles, et le désir du sage, c’est une oreille qui écoute. L’eau éteint une flamme ardente, et l’aumône efface les péchés. Celui qui n’est point avare de reconnaissance se recommande pour l’avenir, et au temps du malheur il trouvera un appui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Mon fils, n’ôte pas à l’indigent ce qui le fait vivre, et ne fais pas attendre les yeux de l’indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Ne contriste pas un homme qui a faim, et n’irrite pas un cœur dans sa misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Ne trouble pas un cœur irrité, et ne fais pas attendre un don au mendiant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Ne rebute pas la supplication du malheureux, et ne détourne pas ton visage du pauvre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Ne détourne pas tes yeux de celui qui demande, et ne donne pas lieu à un homme de te maudire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Car, s’il te maudit dans l’amertume de son âme, celui qui l’a créé exaucera sa prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Fais-toi aimer de la synagogue, et humilie ta tête devant les grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Incline l’oreille vers le pauvre, et réponds - lui des paroles de douceur et de paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Retire le persécuté de la main des persécuteurs; et quand tu juges, prends garde de manquer de courage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Sois pour les orphelins comme un père, et pour leur mère comme un époux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Et tu seras comme un fils du Tout-Puissant, et ta mère t’aimera plus encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 12, 'La sagesse a exalté ses fils; elle prend soin de ceux qui la cherchent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 13, 'Celui qui l’aime aime la vie; et ceux qui, pour elle, se lèvent dès l’aurore, seront remplis de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 14, 'Celui qui en est le maître aura la gloire pour héritage, et tout lieu où elle entre est béni du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 15, 'Car ceux qui la servent; servent le Saint, et le Seigneur aime ceux qui l’aiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 16, 'Celui qui l’écoute jugera les nations, et celui qui s’approche d’elle habitera près d’elle en toute confiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 17, 'Celui qui croit en elle l’aura pour héritage; ses descendants la possèderont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 18, 'D’abord elle chemine avec lui dans les voies difficiles de la tentation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 19, 'Puis elle le conduit dans la circonspection et la crainte; elle l’exerce par ses corrections jusqu’à ce qu’elle soit sûre de son âme, et qu’elle l’ait éprouvé par ses jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 20, 'Enfin elle revient à lui sans réserve; elle le réjouit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 21, 'Et lui dévoile ses secrets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 22, 'Mais, s’il s’était égaré, elle l’aurait délaissé, et livré au pouvoir de sa propre ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 23, 'Prends donc le temps favorable, évite le mal;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 24, 'Et quand il s’agit de ton âme, garde-toi de la confusion;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 25, 'Car il est une confusion qui amène le péché, et il en est une toute de gloire et de grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 26, 'N’aie point d’égard pour le rang aux dépens de ton âme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 27, 'Et garde-toi de commettre un manquement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 28, 'Ne retiens pas une parole qui peut être salutaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 29, 'Car à la parole on reconnaît la sagesse, et la doctrine aux mots que la langue prononce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 30, 'Ne dispute pas contre la vérité; sois plutôt confus de ton ignorance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 31, '32. Ne rougis pas de confesser tes péchés, et ne cherche pas à remonter le cours d’un fleuve. Ne te soumets pas à un insensé, et ne te laisse pas imposer par le visage d’un grand. Jusqu’à la mort lutte pour la vérité, et le Seigneur Dieu combattra pour toi. Ne sois point acrimonieux en tes discours, ni paresseux et négligent dans tes œuvres. Ne sois pas comme un lion dans ta famille, ni capricieux avec tes serviteurs. Que ta main ne soit point ouverte pour recevoir, ni fermée pour donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 1, 'Ne t’occupe pas uniquement de tes richesses, et ne dis pas: J’ai ce qui me suffit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 2, 'Ne mets pas toutes tes forces et toute ton âme à cheminer selon la concupiscence de ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 3, 'Et ne dis pas: Qui sera mon maître? car le Dieu vengeur se vengera de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 4, 'Ne dis pas: J’ai péché; que m’en est-il advenu? car le Seigneur est patient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 5, 'Ne sois pas sans crainte sur l’expiation, et n’amasse pas péchés sur péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 6, 'Et ne dis pas: Sa miséricorde est grande; elle aura pitié de la multitude de mes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 7, 'Car la miséricorde et la colère viennent de lui, et sur les pécheurs reposera sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 8, 'Ne tarde pas à te convertir au Seigneur, et ne remets pas de jour en jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 9, 'Car elle viendra soudaine la colère du Seigneur, et à l’heure de la vengeance tu seras perdu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 10, 'Ne cherche pas à acquérir injustement des richesses; elles te seraient inutiles au jour de sa visite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 11, 'Ne vanne pas à tout vent, et ne marche pas en tout sentier, comme le pécheur dont la langue est double.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 12, 'Sois ferme en ta sagesse; sois franc en tes discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 13, 'Sois prompt à écouter, et lent à répondre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 14, 'Si tu es dans ton bon sens, réponds à ton prochain; sinon, que ta main soit sur ta bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 15, 'À parler on se fait gloire ou honte, et la langue des hommes est souvent leur ruine. Prends garde que l’on ne t’appelle médisant, et ne tends pas de pièges avec ta langue. Car à l’homme dissimulé est la honte, et au fourbe une détestable réputation. Grande ou petite, évite de commettre une faute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 1, 'D’ami ne deviens pas ennemi; car tu aurais pour héritage un mauvais renom, la confusion et la honte, comme le pécheur et le fourbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 2, 'Ne t’exalte pas toi-même dans les pensées de ton âme, de peur que ton âme ne s’emporte comme un taureau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 3, 'Garde-toi de manger tes feuilles, de perdre tes fruits, et de devenir comme un bois aride.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 4, 'Une âme perverse ruinera celui qui la possède, et le rendra la joie de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 5, 'Une langue douce multiplie les amis; des lèvres bienveillantes abondent en paroles affables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 6, 'Vis en paix avec le grand nombre; mais sur mille n’en prends qu’un pour ami.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 7, 'Si tu acquiers un ami, ne le prends pas sans l’avoir éprouvé, et ne lui donne pas facilement ta confiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 8, 'Car tel est ami à son temps, et celui-là, tu ne le trouveras point près de toi au jour de la tribulation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 9, 'Et tel autre change en haine l’amitié, et celui-là révèlera des querelles qui seront à ta honte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 10, 'Tel autre est ton compagnon de table, et tu ne l’auras point près de toi au jour de la tribulation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 11, 'En ta prospérité il sera comme toi; il parlera librement à tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 12, 'Mais si tu es humilié, il sera contre toi; et, à ta vue, il se cachera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 13, 'Tiens-toi loin de tes ennemis, et attache-toi à tes amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 14, 'Un ami fidèle est un abri solide, et qui l’a trouvé a trouvé un trésor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 15, 'Rien ne vaut un ami fidèle, et sa bonté est inappréciable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 16, 'Un ami fidèle est un remède aux maux de la vie, et ceux qui craignent le Seigneur le trouveront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 17, 'Celui qui craint le Seigneur place bien son amitié; car son meilleur ami est celui qui lui ressemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 18, 'Mon fils, dès ta jeunesse reçois la doctrine, et jusqu’à tes vieux jours tu trouveras la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 19, 'Occupe-toi d’elle, comme le laboureur et le semeur, et tu en recueilleras de bons fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 20, 'À ce labeur tu te fatigueras un peu; mais bientôt tu mangeras de ses fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 21, 'Mais c’est une rude tâche pour les esprits indociles, et celui qui manque de courage n’y persévère pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 22, 'Elle est pour lui comme une pierre à éprouver la force, et il se hâte de la rejeter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 23, 'Car la sagesse est comme son nom l’indique, et elle ne se manifeste pas au grand nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 24, 'Écoute, mon fils, recueille mes leçons, et ne repousse pas mes conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 25, 'Mets tes pieds dans ses chaînes, et ton cou dans son collier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 26, 'Courbe tes épaules et porte-la, et endure sans impatience ses liens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 27, 'Occupe-toi d’elle de toute ton âme, et garde ses voies de toutes tes forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 28, 'Cherche-la, mets-toi à sa poursuite, et elle se manifestera à toi; et, une fois maître d’elle, ne la laisse pas échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 29, 'En tes vieux jours, tu goûteras son repos, et elle sera ta joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 30, 'Et ses chaînes te seront un puissant abri, et ses colliers, une robe de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 31, 'Car elle porte une parure d’or, et ses fers sont des franges d’hyacinthe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 32, 'Tu te revêtiras d’elle comme d’une robe de gloire, et tu poseras sur ta tête une couronne d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 33, 'Si tu veux la suivre, ô mon fils, tu seras instruit; et, si tu t’y appliques de toute ton âme, tu deviendras habile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 34, 'Si tu te plais à l’écouter, tu en recueilleras les fruits; et si tu lui prêtes une oreille attentive, tu seras sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 35, 'Va dans la compagnie des anciens, et quiconque est sage, attache-toi à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 36, 'Désire entendre toute parole qui vient de Dieu, et que les paroles de la sagesse ne te fassent point fuir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 37, 'Si tu connais un sage, va le trouver dès le matin, et que ton pied passe souvent les degrés de sa porte. Aie souvent en pensée les préceptes du Seigneur, et médite toujours sur ses commandements. Lui-même affermira ton âme et ton désir de la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 1, 'Ne fais rien de mal, et le mal ne sera pas maître de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 2, 'Éloigne-toi de l’homme inique, et il se détournera de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 3, 'Mon fils, ne sème pas dans les sillons de l’iniquité, de peur d’y moissonner au septuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 4, 'Ne demande pas au Seigneur la souveraineté, ni au roi un siége d’honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 5, 'Ne te donne pas pour juste devant le Seigneur, et, en présence du roi, n’affecte point d’être un sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 6, 'Ne cherche pas à être juge, craignant de n’être point assez fort pour déraciner l’iniquité, d’être intimidé en face des grands, et d’exposer ta droiture à faire un faux pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 7, 'N’offense point la multitude d’une ville, et ne te jette pas dans les mouvements populaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 8, 'Ne te mets pas deux fois dans les liens du péché; car, même pour une seule fois, tu ne seras pas impuni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 9, '(Vulg. 11.) Ne dis pas: Le Seigneur regardera la multitude de mes dons, et quand je les offrirai au Dieu Tout-Puissant, il les agréera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 10, '(9.)Ne sois pas pusillanime en ta prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 11, '(10.) Ne néglige pas de faire l’aumône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 12, 'Ne ris pas d’un homme en l’amertume de son âme; car il en est un qui élève et qui humilie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 13, 'Ne forge pas de mensonges contre ton frère ni contre ton ami.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 14, 'Garde-toi du moindre mensonge; car il n’est pas bon d’en prendre l’habitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 15, 'Ne parle pas longuement dans la compagnie des anciens, et en priant ne te répète jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 16, 'N’aie point en haine les œuvres laborieuses ni la culture des champs; car c’est le Tout-Puissant qui les a instituées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 17, 'Ne fais pas nombre avec les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 18, '(Vulg. 19.) Humilie grandement ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 19, '(18.) Souviens-toi que la colère de Dieu ne se fait pas attendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 20, '(19.)Car le feu et les vers sont la punition des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 21, '(20.)Ne délaisse pas ton ami pour un indifférent, ni ton propre frère pour l’or d’Ophir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 22, '(21.)Ne t’éloigne pas d’une femme bonne et sage; car sa grâce est préférable à l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 23, '(22.)Ne maltraite point le serviteur qui travaille avec zèle, ni le journalier qui te donne sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 24, '(23.)Que ton âme aime un serviteur intelligent, et ne lui refuse pas la liberté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 25, '(24.)As-tu des bêtes de somme? visite-les, et, si elles te sont utiles, garde-les avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 26, '(25.)As-tu des enfants? instruis-les, et, dès leur jeunesse, courbe leur front.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 27, '(26.)As-tu des filles? veille sur leur personne, et devant elles ne montre pas un visage trop joyeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 28, '(27.)Marie ta fille, et tu feras grande œuvre, et donne-la à un homme sensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 29, '(28.)Ta femme est-elle selon ton âme? ne la répudie jamais. De tout ton cœur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 30, '(29.)Glorifie ton père, et n’oublie point les douleurs de ta mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 31, '(30.)Souviens-toi que c’est par eux que tu existes; et que leur rendras-tu pour ce qu’ils ont fait pour toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 32, '(31.)De toute ton âme crains le Seigneur, et honore ses prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 33, '(32.)De toute ta force aime celui qui t’a créé, et ne délaisse pas ses ministres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 34, '(33.)Crains le Seigneur, et glorifie le prêtre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 35, '(34.)Et donne à celui-ci la part qui est prescrite; les prémices des offrandes pour le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 36, '(35.)Et les épaules des victimes, et les sacrifices de sanctification, et les prémices des saints. (36.)Tends la main aux pauvres, pour que ta bénédiction soit parfaite. (37.)Les dons sont agréables aux vivants; n’exclus pas les morts de cette grâce. (38.)Ne délaisse pas ceux qui pleurent, et affligetoi avec les affligés. (39.)Ne néglige pas de visiter les malades, et ainsi tu te feras aimer. (40.)En toutes tes paroles considère la fin, et tu ne pècheras jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 1, 'N’aie point de querelles avec un grand, de peur de tomber en ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 2, 'N’aie point de contestations avec un riche, de peur qu’il ne fasse pencher de son côté la balance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 3, 'Car l’or a perdu nombre d’hommes; il a fait dévier le cœur des rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 4, 'Ne discute pas avec un grand parleur, et ne mets point de bois dans son feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 5, 'Ne plaisante pas avec un homme grossier, de peur qu’il n’outrage tes parents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 6, 'Ne dis pas d’injures à celui qui se retire du péché; souviens - toi que nous sommes tous dignes de punition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 7, 'Ne méprise pas un homme à cause de sa vieillesse; car nous-mêmes nous vieillirons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 8, 'Ne te réjouis de la mort de personne; souviens-toi que tous nous mourrons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 9, 'Ne dédaigne pas les récits des sages; et occupe-toi de pénétrer les sens de leurs paraboles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 10, 'Car c’est d’eux que tu apprendras la discipline, et comme il faut servir les grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 11, 'Ne manque pas d’écouter les récits des vieillards; car eux-mêmes ont été instruits par leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 12, 'C’est d’eux que tu apprendras la sagesse et l’art de répondre en temps nécessaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 13, 'N’allume pas les charbons du pécheur, de peur que la flamme de son foyer ne te consume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 14, 'Ne te lève pas contre la face d’un insolent, de peur qu’il ne dresse des pièges à tes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 15, 'Ne prête point à plus puissant que toi; car ce que tu lui prêtes, regarde-le comme perdu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 16, 'Ne t’engage pas au-delà de tes ressources; car si tu es caution, considère-toi comme débiteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 17, 'N’entre pas en procès avec un juge; car l’on te jugera sur son avis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 18, 'Ne te mets pas en route avec un audacieux, de peur qu’il ne te soit à charge; car il n’en fera qu’à sa volonté, et, par son extravagance, vous périrez ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 19, 'Ne te querelle pas avec un homme enclin à la colère, et garde-toi de traverser le désert avec lui; car le sang à ses yeux est comme rien, et, où tu ne pourras être secouru, il te renversera. Ne délibère pas de tes affaires avec un fou; car il ne saura garder ton secret. Ne traite rien de secret devant un étranger; car tu ignores ce qu’il pourra machiner contre toi. N’ouvre pas ton cœur à tout venant, de peur qu’en retour il ne révèle tes confidences.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 1, 'Ne sois point jaloux de la femme de ton amour, de peur que tu ne lui enseignes à ton détriment une doctrine qui te soit funeste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 2, 'Ne donne point ton âme à une femme, de peur qu’elle ne prenne trop d’ascendant sur ton autorité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 3, 'Évite de regarder une femme volage, de peur de tomber dans ses filets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 4, 'Ne fréquente pas une chanteuse, de peur que tu ne périsses victime de ses attraits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 5, 'N’arrête pas tes yeux sur une vierge, de peur que ses charmes ne soient un piége pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 6, 'Ne donne pas ton âme à des prostituées, de peur qu’elles ne te fassent perdre ton héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 7, 'Ne regarde pas çà et là dans les rues d’une ville; ne te promène pas à l’aventure dans les quartiers déserts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 8, 'Détourne ton œil d’une femme belle, et ne fais pas attention à une beauté étrangère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 9, 'Beaucoup ont été égarés par la beauté d’une femme; la tendresse qui en naît brûle comme du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 10, 'Surtout ne t’assieds pas auprès d’une femme mariée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 11, 'Ne fais pas avec elle de repas égayés par le vin, de peur que ton âme ne penche pour elle, et qu’en ton esprit tu ne tombes dans la perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 12, 'Ne délaisse pas un ancien ami; car le nouveau ne lui est point semblable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 13, 'Un nouvel ami, c’est un vin nouveau; lorsqu’il aura vieilli, tu le boiras avec joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 14, 'Ne porte point envie à la gloire du pécheur; car tu ne sais pas quelle catastrophe l’attend.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 15, 'Ne te complais pas dans le bon vouloir des impies; souviens-toi que jusqu’aux enfers ils ne seront point justifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 16, 'Tiens-toi loin de celui qui a pouvoir de tuer, si tu ne veux avoir toujours peur de la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 17, 'Et si tu l’abordes, prends garde de lui manquer, de peur qu’il ne t’ôte la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 18, 'Sache que tu marches au milieu des pièges, et que tu te promènes sur les créneaux d’une ville. Étudie ton prochain, autant que possible, et prends conseil des sages. Recherche l’entretien des hommes sensés, et que ta conversation roule entièrement sur la loi du Très-Haut. Que tes convives soient des justes, et mets toute ta gloire dans la crainte du Seigneur. L’artisan est loué pour l’œuvre de ses mains, et le prince du peuple pour la sagesse de ses discours. Le grand parleur est l’effroi de sa ville, et l’indiscret en paroles est odieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 1, 'Un juge sage instruira son peuple, et l’autorité d’un roi prudent sera réglée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 2, 'Tel juge du peuple, tels ministres; tel chef d’une ville, tels habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 3, 'Un roi ignorant perd son peuple, et une ville est florissante par la sagesse de ceux qui la gouvernent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 4, 'Toute puissance sur la terre est en la main du Seigneur, et il suscite à propos celui qui doit lui être utile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 5, 'La prospérité d’un homme est dans la main du Seigneur, et il mettra sa gloire sur la face du scribe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 6, 'Que nulle injustice ne t’irrite contre ton prochain, et ne fais aucune des œuvres de la violence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 7, 'L’orgueil est haï du Seigneur et des hommes, et l’iniquité les offense également.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 8, 'L’empire passe d’une nation à une autre nation, à cause des injustices, des violences et des richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 9, 'Pourquoi tant de superbe en celui qui n’est que cendre et poussière?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 10, 'C’est qu’il s’est dépouillé tout vivant de ses propres entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 11, 'Le médecin se raille d’une longue maladie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 12, 'Ainsi tel est roi aujourd’hui, qui mourra demain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 13, 'Quand l’homme meurt, les reptiles, les bêtes fauves et les vers sont son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 14, 'Le commencement de l’orgueil en l’homme, c’est son éloignement du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 15, 'C’est quand son cœur s’est retiré de celui qui l’a fait. Car le péché est le principe de l’orgueil, et celui qui s’y tient attaché fera pleuvoir sur lui l’abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 16, 'C’est pourquoi le Seigneur a signalé ses attaques contre les méchants, et il les détruira jusqu’à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 17, 'Le Seigneur a renversé les trônes des rois, et, à leur place, il y a fait asseoir les doux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 18, 'Le Seigneur a arraché les racines des gentils, et à leur place il a planté les humbles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 19, 'Le Seigneur a bouleversé les terres des gentils, et il les a ruinés jusqu’aux fondements de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 20, 'Il les a fait périr en rendant leur territoire à jamais aride; et ceux-là, il a effacé de la terre leur mémoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 21, 'L’orgueil n’a point été créé avec les hommes, ni les transports de la colère avec les générations des femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 23, 'Quelle est la race honorable? la race de l’homme. Quelle est la race honorable? la race de ceux qui craignent le Seigneur. Quelle est la race sans honneur? celle de l’homme. Quelle est la race sans honneur? la race de ceux qui transgressent les commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 24, 'Parmi des frères, celui qui est leur chef est honorable, et tels sont, aux yeux du Seigneur, ceux qui le craignent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 25, 'Riche, illustre, mendiant, leur gloire est la crainte du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 26, 'Il n’est point juste de mépriser un sage dans la pauvreté; il n’est point convenable de glorifier un homme pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 27, 'Le grand, le juge et le puissant seront honorés; mais nul d’entre eux n’est plus grand que celui qui craint le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 28, 'Des hommes libres serviront le serviteur sage, et l’homme expérimenté n’en murmurera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 29, 'Ne te donne pas pour sage parce que tu fais œuvre de tes mains, et ne fais pas le fier au temps de ton indigence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 30, 'Mieux vaut celui qui travaille et abonde en toutes choses, que celui qui se promène ou se glorifie, quand il manque de pain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 31, 'Mon fils, glorifie ton âme par la mansuétude, et honore-la comme un trésor. Qui justifiera celui qui pèche contre son âme? qui honorera celui qui déshonore sa vie? Le pauvre sera glorifié à cause de son savoir, et le riche sera glorifié à cause de ses richesses. Mais celui que l’on glorifie dans la pauvreté, que serait-ce donc s’il était riche? et celui qui est sans gloire dans la richesse, que serait-ce s’il était pauvre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 1, 'La sagesse de l’humble porte haut la tête; elle le fera asseoir parmi les grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 2, 'Ne loue point un homme pour sa beauté, et ne méprise point un homme pour son peu d’apparence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 3, 'L’abeille est petite parmi les êtres qui volent, et son fruit est un principe de douceur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 4, 'Ne tire point vanité de la richesse de tes vêtements, et ne t’enorgueillis pas en tes jours de gloire; car les œuvres du Seigneur sont admirables, et elles sont cachées pour les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 5, 'Nombre de rois se sont assis à terre, et un inconnu a porté le diadème.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 6, 'Nombre de grands sont tombés sans honneur, et leur gloire a passé en d’autres mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 7, 'Ne blâme pas avant d’être informé; réfléchis d’abord, et alors tu puniras. Ne réponds pas avant d’avoir entendu, et ne te jette pas à travers un discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 8, 'Ne discute pas une affaire où il n’est pas besoin de toi, et pour juger ne t’assieds pas avec les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 9, 'Mon fils, ne fais pas beaucoup d’entreprises;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 10, 'Car si tu t’enrichis, tu ne seras pas sans reproches; si tu poursuis, tu ne saisiras pas, et si tu t’enfuis, tu n’échapperas point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 11, 'Tel prend de la peine, et se fatigue et s’évertue, et n’en est que plus indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 12, 'Tel est lent et a besoin d’aide; il manque de force, et il abonde en misères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 13, 'Mais les yeux du Seigneur l’ont regardé pour son bien, et il l’a relevé de son abaissement. Et il a élevé sa tête, et plusieurs se sont étonnés en le voyant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 14, 'Bien et mal, vie et mort, pauvreté et richesse, tout vient du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 15, '(Vulg., 17.)Les dons du Seigneur aux hommes pieux sont durables, et son bon vouloir les fera prospérer dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 16, '(18.)Tel s’enrichit à force de soins et de parcimonie, et la richesse est sa seule récompense;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 17, '(19.)Et lorsqu’il dit: J’ai trouvé le repos et je vais maintenant vivre de mes biens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 18, '(20.)Il ne sait rien du moment qui va suivre, et tout à l’heure il laissera sa richesse à d’autres, et il mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 19, '(21.)Sois ferme en ton alliance avec Dieu; que ce soit là ton entretien, et vieillis dans la pratique de ses commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 20, '(22.)N’admire point les œuvres des pécheurs; mets ta confiance en Dieu, et persévère en ton labeur. (23.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 21, 'Car il est facile aux yeux du Seigneur d’enrichir soudain un indigent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 22, '(24.)La bénédiction du Seigneur est le salaire des hommes pieux, et dans le court espace d’une heure il lui fait porter des fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 23, '(25.)Ne dis pas: Que me manque-t-il? quels biens me viendront désormais?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 24, '(26.)Ne dis pas: J’ai ce qui me suffit, et en quoi désormais serai-je affligé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 25, '(27.)Au jour de la prospérité, on oublie tous les maux; au jour de l’adversité, on ne se souvient plus des temps heureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 26, '(28.)Or il est facile au Seigneur de rétribuer un homme au jour de sa mort, selon ses voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 27, '(29.)Il transforme en une plénitude de délices une heure d’affliction, et, par la fin qu’il lui donne, il dévoile les œuvres de cet homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 28, '(30.)Ne déclare personne heureux avant son dernier jour; par ses enfants, on reconnaîtra ce qu’a été un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 29, '(31.)N’introduis pas tout venant dans ta maison; car les artifices du trompeur sont nombreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 30, '(32.)Telle est la perdrix dans sa cage; tel est le cœur du superbe, lorsque, comme un espion, il médite la chute d’autrui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 31, '(33.)Car il dresse ses pièges, changeant les biens en maux, et il déverse le blâme sur les élus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 32, '(34.)Une seule étincelle embrase une multitude de charbons, et le pécheur fait le guet pour verser le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 33, '(35.)Tiens-toi loin du méchant, car il est l’artisan du mal, et crains qu’il ne t’imprime une tache ineffaçable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 34, '(36.)Accueille un étranger, et il te pervertira et te jettera dans le trouble, et il te chassera de ton propre foyer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 1, 'Si tu fais du bien, sache à qui, et tes faveurs seront pour les bons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 2, 'Fais du bien à l’homme pieux, et tu recevras ta récompense; et si ce n’est de lui, ce sera du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 3, 'Il n’y a rien de bon en celui qui a l’habitude du mal et qui ne donne point d’aumônes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 4, 'Donne à l’homme pieux, et ne secours point le pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 5, '(Vulg. 6.) Fais du bien aux humbles, et ne donne rien à l’impie. Empêche qu’on ne lui donne des pains, et ne lui en donne pas, de peur qu’il ne s’en serve pour t’opprimer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 6, '(7.)Car, en échange de chacun de tes bienfaits, tu recueilleras double mal. Or le Seigneur hait les pécheurs, et c’est lui qui infligera une peine aux impies. Donne au bon, et ne secours pas les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 8, 'Dans la prospérité, un ami ne peut être apprécié; dans l’adversité, un ennemi ne se cachera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 9, 'Dans la prospérité d’un homme, ses ennemis s’affligent; dans l’adversité, son ami lui-même s’éloignera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 10, 'Ne te fie jamais à ton ennemi; car sa méchanceté est comme la rouille qui s’attache à l’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 11, 'Et lors même qu’il s’humilierait et marcherait tout courbé, réprime ton âme et garde-toi de lui; fais comme si tu essuyais un miroir, et tu verras s’il n’est pas rouillé jusqu’au fond de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 12, 'Ne l’engage point à s’arrêter auprès de toi, et, en voyage, ne t’arrête pas chez lui; ne le fais pas asseoir à ta droite, de peur qu’il n’exige ton siége, et qu’enfin tu ne reconnaisses que j’ai raison, et que le regret ne te vienne au souvenir de mes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 13, 'Qui aura pitié de l’enchanteur mordu par un serpent, ou de ceux qui approchent des bêtes fauves? Il en est de même de celui qui fréquente un pécheur, et qui se souille de ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 14, 'Il demeurera quelque temps avec toi; mais s’il te voit près de tomber, il perdra patience.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 15, 'Ton ennemi aura la douceur sur les lèvres; mais en son cœur il roulera le projet de te pousser dans l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 16, 'Ton ennemi aura les yeux larmoyants, et, s’il en trouve l’occasion, tout ton sang ne suffira pas à le rassasier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 17, 'Si des malheurs te surviennent, tu le trouveras là, arrivé le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 18, 'Et, sous prétexte de te secourir, il te donnera un croc-en-jambe. Il secouera la tête et battra des mains, et il chuchotera, et il changera de visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 1, 'Qui touche à de la poix en sera sali, et qui fréquente un orgueilleux lui ressemblera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 2, 'Ne soulève pas un poids au-dessus de tes forces; de même ne sois point le compagnon de plus puissant et plus riche que toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 3, 'Qu’y a-t-il de commun entre le pot de terre et le pot de fer? l’un heurtera, l’autre sera brisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 4, 'Le riche a fait une injure, il y ajoute la colère; le pauvre a été lésé, et c’est lui qui demandera pardon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 5, 'Si tu es utile au premier, il abuse de toi; si tu ne lui es bon à rien, il te délaissera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 6, 'Si tu as quelque chose, il fera bonne chère avec toi, et il t’épuisera, et il n’en prendra nul souci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 7, 'A-t-il encore besoin de toi? il te trompera, il te sourira, il te donnera des espérances, il te fera de belles promesses, et dira: Que désires-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 8, 'Et il te confondra par ses grands festins, jusqu’à ce que deux ou trois fois il t’ait épuisé; enfin il se moquera de toi. Puis il te regardera, t’abandonnera et secouera sur toi sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 9, '(Vulg., 10.)Sois attentif, de peur que l’on ne t’égare, et qu’au milieu de ta joie tu ne sois humilié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 10, '(12.)Si un grand t’appelle à lui, éloigne-toi peu à peu, et il t’appellera d’autant plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 11, '(13.)Ne t’introduis pas de force chez lui, de peur d’être repoussé, et ne sois pas longtemps sans le voir, si tu ne veux qu’il t’oublie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 12, '(14.)Évite de t’entretenir souvent seul avec lui, et n’ajoute point foi à l’abondance de ses discours; car il t’éprouvera par des paroles sans fin, et il te sondera comme en se jouant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 13, '(15.)Malheur à celui qui ne s’observe point en parlant! on ne lui épargnera ni les mauvais traitements ni la prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 14, '(16.)Observe-toi, et sois très-attentif; car tu chemines vers ta perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 15, '(19.)Tout animal aime son semblable, et tout homme aime son prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 16, '(20.)Toute chair s’attache à ceux de son espèce, et l’homme s’unit à qui lui ressemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 17, '(21.)Quel rapport y a-t-il entre le loup et l’agneau? Il en est de même du pécheur et de l’homme pieux. (22.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 18, 'Quelle paix y a-t-il entre l’hyène et le chien? Quelle paix entre le riche et le pauvre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 19, '(23.)L’âne sauvage est, dans le désert, le gibier du lion; de même les pauvres sont la pâture des riches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 20, '(24.)L’humilité est en abomination à l’orgueilleux; de même le pauvre est en abomination au riche. (25.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 21, 'Si le riche est ébranlé, ses amis le soutiennent; si l’humble tombe, par surcroît il est repoussé par ses amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 22, '(26.)Le riche tombe-t-il? les secours abondent; a-t-il dit des choses inconvenantes? on le justifie encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 23, '(27.)L’humble est renversé, et, de plus, on l’accable de reproches; il parle avec sagesse, et on ne tient pas compte de ce qu’il a dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 24, '(28.)Le riche parle, et chacun se tait, et on élève son discours jusqu’aux nues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 25, '(29.)Le pauvre parle, et l’on se demande: Qu’est cet homme? S’il fait un faux pas, c’est à qui le renver');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 26, '(30.)La richesse est bonne à celui qui vit sans péché; la pauvreté est méchante dans la bouche des impies. (31.)Le cœur de l’homme change sa face soit en bien, soit en mal. (32.)L’allégresse du visage est pour les bons l’image du cœur; pour comprendre les paraboles, il faut réfléchir avec peine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 1, 'Heureux l’homme qui n’a point failli en paroles, et qui n’est point tombé dans les tristesses du péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 2, 'Heureux celui que son âme n’a point condamné, et qui n’a point perdu son espérance!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 3, 'La fortune n’est bonne à rien chez l’avare; et chez un envieux, à quoi bon les richesses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 4, 'Celui qui amasse aux dépens de son âme, amasse pour autrui; d’autres jouiront de ses richesses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 5, 'Celui qui est mauvais pour soi-même, pour qui sera-t-il bon? Il ne trouvera aucune joie dans ses biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 6, 'Il n’est pire que l’envieux de soi-même, et cela même est la peine de sa malice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 7, 'Et s’il vient à faire du bien, c’est par oubli, et finalement il manifeste sa malice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 8, 'L’envieux a le regard mauvais; il détourne le visage, et méprise les âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 9, 'L’œil du convoiteux n’est pas rassasié de sa part, et sa perverse iniquité dessèche son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 10, 'Un œil mauvais est même envieux de son pain, et il est indigent à sa table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 11, 'Mon fils, selon ce que tu as, fais - toi du bien, et présente au Seigneur de dignes offrandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 12, 'Souviens-toi que la mort ne tardera pas, et l’arrêt de l’enfer ne t’a pas été dévoilé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 13, 'Avant ta mort, fais du bien à un ami; autant qu’il est en ton pouvoir, étends la main pour lui donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 14, 'Ne te prive pas d’un jour heureux, et ne laisse pas échapper ta part d’un bon désir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 15, 'Ne laisseras-tu pas à autrui le fruit de tes labeurs, et tes biens ne seront-ils pas tirés au sort?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 16, 'Donne et reçois, et charme ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 17, 'Car dans l’enfer il n’y a plus à chercher des délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 18, 'Toute chair vieillira comme un manteau; car tel est l’arrêt porté de toute éternité: Tu mourras de mort. Telles sont les feuilles verdoyantes d’un arbre touffu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 19, 'Les unes tombent, les autres germent, ainsi des générations de chair et de sang; l’une meurt, l’autre naît.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 20, 'Toute œuvre corruptible périt, et son auteur s’en ira comme elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 21, '(Vulg. 22.) Heureux l’homme qui finit dans la sagesse, et dont la prudence inspire les méditations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 22, '(23.)Celui qui, en son cœur, pense aux voies de la sagesse, en comprendra les mystères. Attache-toi à ses pas, comme on suit une proie, et mets-toi aux aguets sur son chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 23, '(24.)Heureux celui qui se penche pour la voir par sa fenêtre, et qui écoute à sa porte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 24, '(25.)Et qui loge tout contre sa maison, et plante dans sa muraille le pieu qui soutient sa propre tente. Il s’abritera sous ses mains, et il reposera dans la tente des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 25, '(26.)Il placera ses enfants sous son ombre, et Ini-même s’arrêtera sous ses rameaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 26, '(27.)Elle le garantira des ardeurs de l’été, et il reposera dans sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 1, 'Ainsi fera celui qui craint le Seigneur, et celui qui possède la loi embrassera la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 2, 'Et elle viendra à sa rencontre comme une mère, et elle l’accueillera comme une épouse vierge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 3, 'Elle le nourrira du pain de l’intelligence, et l’abreuvera de l’eau du savoir. Elle s’affermira en lui, et il ne déviera pas;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 4, 'Et il s’appuiera sur elle, et il ne sera point confondu. Elle l’élèvera au-dessus de ses proches;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 5, 'Et au milieu de l’assemblée elle lui ouvrira la bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 6, 'La joie, une couronne d’allégresse et un nom immortel seront son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 7, 'Mais les insensés n’embrasseront pas la sagesse, et les pécheurs ne la verront même point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 8, 'Elle est loin de l’orgueil, et les fourbes ne se souviendront pas d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 9, 'Sa louange est déplacée dans la bouche du pécheur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 10, 'Parce que ce n’est pas le Seigneur qui l’a envoyée; car sa louange ne découle que de la sagesse même, et alors Dieu la rend agréable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 11, 'Ne dis point: C’est le Seigneur qui l’a éloignée de moi; tu n’as qu’à ne pas faire ce qu’elle hait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 12, 'Ne dis point: C’est lui qui m’a égaré; car il n’a que faire d’un pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 13, 'Le Seigneur déteste toutes les abominations, et ceux qui le craignent ne les aiment pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 14, 'Dès le commencement il a créé l’homme, et il l’a laissé aux mains de son propre conseil. De sorte que,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 15, '(Vulg. 16.) Si telle est ta volonté, tu garderas les commandements et la foi qui produit les bonnes œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 17, 'Il a placé devant toi l’eau et le feu; étends la main où il te plaira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 18, 'La vie et la mort sont devant l’homme; celle qu’il aura choisie lui sera donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 19, 'Car la sagesse du Seigneur est abondante; son autorité est puissante, et voit tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 15, 20, 'Et il a les yeux sur ceux qui le craignent, et nulle des œuvres de l’homme ne lui échappe. Il n’a prescrit à personne d’être impie, et à personne il n’a donné la permission de pécher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 1, 'Ne désire pas un grand nombre d’enfants inutiles; ne te réjouis pas en tes fils, s’ils ne sont pieux. Et s’ils sont nombreux, ne mets pas en eux ta joie, à moins que la crainte du Seigneur ne soit avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 2, 'Ne te fie pas à leur vie, et ne t’appuie pas sur leur bien;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 3, 'Car un seul vaut mieux souvent que mille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 4, 'Mieux vaut mourir sans enfants, qu’avoir des enfants impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 5, 'Un seul sage repeuplera la ville; une tribu de pervers la rendra déserte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 6, 'J’ai vu de mes yeux beaucoup de ces choses, et mon oreille en a entendu de plus fortes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 7, 'La flamme s’allumera dans l’assemblée des pécheurs, et la colère de Dieu éclatera contre une nation sans foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 8, 'Il n’a pas fait grâce aux antiques géants qui, dans leur force, s’étaient révoltés contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 9, 'Il n’a point épargné la ville où Lot était passager; il avait pris ses habitants en abomination à cause de leur insolence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 10, 'Il n’a point eu pitié de cette nation perdue, qui se faisait gloire de ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 11, 'Et il en fut ainsi des six cent mille hommes de pied qui s’étaient rassemblés, dans l’endurcissement de leur cœur. Et il n’en eût pas même sauvé un seul, s’il eût été rebelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 12, 'Car la miséricorde et la colère sont de lui; il est maître de pardonner ou de répandre son courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 13, 'Autant sa miséricorde est grande, autant sont grands ses châtiments; il juge chacun selon ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 14, 'Le pécheur n’évitera pas d’être sa proie, et Dieu ne trompera pas l’attente du juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 15, 'Il donnera place à toute miséricorde, et chacun sera rétribué selon ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 16, 'Ne dis point: Je me cacherai du Seigneur; et qui, du haut des cieux, se souviendra de moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 17, 'Je suis déjà oublié parmi cette multitude; qu’est-ce donc que mon âme au milieu de l’immense création?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 18, 'Car voilà que le ciel, et le ciel des cieux du Seigneur, et l’abîme et la terre seront ébranlés au jour de sa visite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 19, 'Les montagnes et les fondements de la terre trembleront d’effroi sous son regard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 20, 'Et le cœur ne saura que penser de ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 21, 'Et qui donc comprendra ses voies? c’est un tourbillon que nul homme ne verra;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 22, 'Et la plupart de ses œuvres sont cachées. Qui publiera ses œuvres de justice? Qui les supportera? Son alliance est au delà de notre intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 23, 'Celui qui s’humilie en son cœur méditera sur ces choses; l’homme insensé et perverti ne concevra que des folies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 24, 'Écoute-moi, mon fils, applique-toi à t’instruire, et, de toute ton âme, sois attentif à mes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 25, 'Je te révélerai la doctrine avec mesure, et je t’initierai à la science avec exactitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 26, 'Dès le commencement, les ouvrages du Seigneur ont été selon son jugement, et, après leur création, il en a distingué les parties.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 27, 'Il les a mis en ordre pour les siècles des siècles, et il en a fixé les principes pour toutes leurs périodes. Nul de ces corps n’a jamais senti la faim ni la fatigue; nul n’a manqué de remplir sa tâche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 28, 'Nul n’a détruit celui qui lui était proche;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 29, 'Et, jusqu’à la consommation des siècles, ils ne désobéiront point à sa parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 16, 30, 'Et, après cela, le Seigneur a considéré la terre, et il l’a remplie de ses biens; Il en a couvert la face de tous les êtres ayant vie, et en elle ils retournent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 1, 'Le Seigneur a créé l’homme de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 2, 'Et il a voulu qu’il y rentrât.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 3, 'Il a mesuré la durée et le nombre de ses jours, et il lui a donné pouvoir sur les êtres qui sont sur la terre. Et lui-même, il l’a revêtu de force, et il l’a fait à son image.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 4, 'Il a mis en toute chair la crainte de l’homme, pour qu’il fût le maître des bêtes et des oiseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 5, 'Il a donné aux hommes le conseil, et le langage, et les yeux, et les oreilles, et un cœur pour penser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 6, 'Il les a remplis de la science de l’esprit, et leur a montré le bien et le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 7, 'Il a mis son œil sur leurs cœurs, pour leur faire voir la magnificence de ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 8, 'Et ils loueront la sainteté de son nom, afin de raconter la magnificence de ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 9, 'Il leur a ajouté le savoir; il leur a donné pour héritage la loi de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 10, 'Il a formé avec eux une alliance éternelle, et il leur a fait connaître ses jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 11, 'Leurs yeux ont vu la grandeur de sa gloire, et leur oreille a entendu la majesté de sa voix. Et il leur a dit: Abstenez-vous de toute iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 12, 'Et il a appris à chacun d’eux ses devoirs envers son prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 13, 'Leurs voies seront toujours devant lui; elles ne seront point cachées à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 14, 'Pour chaque nation, il a institué un chef;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 15, 'Et Israël est la part du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 16, 'Toutes les œuvres des hommes sont visibles pour lui, comme le soleil; et ses regards sont toujours fixés sur leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 17, 'Ils n’ont jamais pu lui cacher leurs iniquités, et tous leurs péchés sont devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 18, 'L’aumône d’un homme est comme le sceau qui l’unit à Dieu, et le Seigneur gardera le souvenir du bienfait de l’homme comme la prunelle de l’œil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 19, 'Ensuite il les ressuscitera, et les rétribuera; et il déposera une récompense sur la tête de chacun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 20, 'Cependant, à ceux qui se repentent il a donné le retour, et il a consolé ceux qui avaient manqué de constance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 21, 'Convertis-toi donc au Seigneur, et quitte le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 22, 'Fais ta prière en sa présence, et diminue tes scandales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 23, 'Retourne au Tout-Puissant; détourne-toi de l’iniquité; déteste ce qui est abominable. Qui donc dans les enfers glorifiera le Très-Haut,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 24, 'À la place des vivants et de ceux qui, dès cette vie, lui rendent grâce?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 25, 'Un mort est comme s’il n’avait jamais été, et ses actions de grâces sont mortes comme lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 26, 'Celui qui vit et se porte bien rendra gloire au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 27, '(Vulg. 28.) Que la miséricorde du Seigneur est grande, et sa clémence pour ceux qui se convertissent à lui!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 28, '(29.)Car toute chose ne peut être dans les hommes, puisque le fils de l’homme n’est pas immortel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 29, '(30.)Qu’y a-t-il de plus brillant que le soleil? Cependant il s’éclipse; la pensée du méchant sera chair et sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 30, '(31.)Dieu lui-même, du haut des cieux, surveille toute puissance, et les hommes ne sont tous que cendre et poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 17, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 1, 'Celui qui vit de toute éternité a créé à la fois toutes choses. Le Seigneur seul sera reconnu juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 2, 'Il n’a donné à personne le soin de publier ses œuvres:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 3, 'Et qui pourra suivre à la trace ses magnificences?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 4, 'Qui aura la mesure de sa force et de sa grandeur? Qui pourra énumérer ses miséricordes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 5, 'Nul n’existe qui puisse amoindrir, augmenter ou expliquer les merveilles du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 6, 'Lorsque l’homme a achevé, il lui faut recommencer; et s’il s’arrête, il demeure interdit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 7, 'Qu’est-ce que l’homme? À quoi est-il bon? Qu’y a-t-il de bien en lui-même? Qu’y a-t-il de mal?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 8, 'Le nombre des jours de l’homme forme au plus cent ans. Telle est une goutte de l’eau de la mer, tel un grain de sable, tel est ce peu d’années au jour de l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 9, 'C’est pour cela que le Seigneur est patient envers les hommes, et qu’il a répandu sur eux sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 10, 'Il a vu et reconnu que leur fin est malheureuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 11, 'C’est pour cela qu’il a multiplié son pardon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 12, 'La piété de l’homme est envers son prochain; la compassion du Seigneur est envers toute chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 13, 'Il reprend, il châtie, il enseigne, il ramène, comme fait un pasteur avec son troupeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 14, 'Il est miséricordieux pour ceux qui accueillent ses instructions, et se soumettent avec zèle à ses jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 15, 'Mon fils, ne mêle pas les reproches aux bienfaits, ni aux présents des paroles affligeantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 16, 'Est-ce que la rosée ne tempère pas l’extrême chaleur? De même la parole est meilleure que le don.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 17, 'Un mot agréable ne vaut-il pas mieux que le don? L’homme bienfaisant distribue l’un et l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 18, 'Le fou injurie avec violence, et le présent de l’indiscret dessèche les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 19, 'Apprends avant de parler,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 20, 'Et, avant d’être malade, soigne-toi. Avant de juger, interroge-toi toi-même, et, à l’heure du jugement, tu obtiendras le pardon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 21, 'Avant de tomber en faute, humilie-toi; et, si tu viens à pécher, montre que tu te convertiras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 22, 'Que rien ne t’empêche de prier au moment voulu, et pour être absous n’attends pas jusqu’à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 23, 'Prépare-toi avant de prier, et ne sois pas comme un homme qui tente le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 24, 'Souviens-toi de sa colère qui éclatera au dernier jour, et du temps de la punition, si ton visage se détourne de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 25, 'Au temps de l’abondance, souviens-toi du temps de la famine, et, dans la richesse, n’oublie point les jours de l’indigence et de la pauvreté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 26, 'Du matin au soir, le temps change, et tout passe vite devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 27, 'L’homme sage en toute chose sera circonspect, et, dans les jours de péché, il se gardera de négligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 28, 'Tout homme de bon sens connaît la sagesse, louera celui qui l’aura trouvée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 29, 'Les sages sont aussi sages en paroles, et ils répandent, comme une pluie, des paraboles pleines de justesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 30, 'Ne marche pas à la suite de tes concupiscences, et détourne-toi de tes convoitises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 31, 'Si tu accordes à ton âme la satisfaction de sa concupiscence, elle te rendra la risée de tes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 32, 'Ne mets point ta joie dans la multitude des délices; et ne t’attache pas aux réunions mondaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 18, 33, 'Prends garde de devenir pauvre en empruntant à usure, pour faire bonne chère quand tu n’as rien dans tą bourse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 1, 'L’ouvrier qui s’enivre ne deviendra pas riche; celui qui méprise les petites choses tombera peu à peu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 2, 'Le vin et les femmes égareront les sages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 3, 'Celui qui s’attache aux prostituées perdra toute honte; la pourriture et les vers seront son héritage, et son âme impudente sera retranchée du nombre des vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 4, 'Celui qui croit facilement a le cœur léger, et celui qui pèche en son âme pèchera en ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 5, 'Celui qui se complaît en son cœur sera condamné; celui qui hait un vain babil aura moins de malice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 6, 'Ne répète jamais une mauvaise parole, et tu ne perdras rien de ta considération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 7, 'Ne la redis pas à ton ami, non plus qu’à ton');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 8, 'Car il t’a écouté, il t’a observé, et, à l’occasion, il te haïra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 9, 'As-tu entendu une parole? qu’elle meure avec toi, et assure-toi qu’elle ne t’échappera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 10, 'L’insensé, à cause d’une parole, souffrira des douleurs comme celles de l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 11, 'Une parole dans les entrailles d’un fou est comme une flèche dans les chairs de la cuisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 12, 'Reprends ton ami, de peur qu’il n’ait pas bien fait, ou, s’il a fait quelque mal, de peur qu’il ne recommence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 13, 'Reprends ton ami, de peur qu’il n’ait pas bien parlé, ou, s’il a dit quelque mauvaise parole, de peur qu’il ne la répète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 14, 'Reprends ton ami; car bien souvent on calomnie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 15, 'Et ne crois pas tout ce que l’on rapporte. Tel pèche, mais non de cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 16, 'Et quel est celui dont la langue n’a jamais péché? Reprends ton prochain avant de le menacer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 17, 'Et donne lieu à la loi du Très-Haut. La crainte du Seigneur est toute sagesse, et en toute sagesse est la pratique de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 18, 'L’habileté à mal faire n’est point sagesse, et le bon sens n’est pas où se tient le conseil des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 19, 'Il est une méchanceté qui est l’abomination même, et il est une folie qui n’est que manque de sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 20, 'Mieux vaut le pauvre en intelligence, mais craignant Dieu, que le riche en pensées, mais transgressant la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 21, 'Il est une habileté complète, qui est l’iniquité même;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 22, 'Celle-là détourne la grâce pour montrer au grand jour le jugement de Dieu. Tel fait le mal, en s’humiliant avec noirceur, et son cœur est plein de ruse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 23, 'Il courbe le front, il fait la sourde oreille, et où il n’est pas connu, il cherchera à te surprendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 24, 'Et lors même que, faute de moyen, il ne pourrait pécher, s’il en trouve l’occasion, il te nuira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 25, 'À la vue, on reconnaît un homme, et, en se rencontrant avec lui face à face, on reconnaît l’homme intelligent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 26, 'Le costume d’un homme, le rire de ses dents, sa démarche en apprennent beaucoup sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 27, 'Tel réprimande hors de propos; tel se tait, et celui-ci est le sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 19, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 1, 'Il vaut mieux reprendre que s’irriter, et celui qui s’accuse ne s’amoindrit pas pour cela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 2, 'La concupiscence de l’ennuque déflore une vierge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 3, 'Violer la justice dans le jugement, c’est lui ressembler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 4, '(Vulg. 5.) Tel se tait, et on le trouve sage; tel se fait haïr par son vain babil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 5, '(6.)Tel se tait, qui n’a rien à dire; tel se tait, sachant parler à propos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 7, 'Le sage garde le silence jusqu’au moment opportun; l’impertinent et l’insensé parlent à tort et à travers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 8, 'Celui qui prodigue les discours se rendra odieux, et celui qui s’arroge le droit de parler se fait détester.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 9, 'Il est pour l’homme telle heureuse issue dans les maux; mais aussi tel avantage tourne à l’humiliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 10, 'Tel don sera pour toi sans profit; tel autre te vaudra une récompense double. L’abaissement peut provenir de la gloire, et par l’humilité on peut en venir à relever la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 12, 'Tel achète beaucoup de choses à vil prix, qui les payera sept fois leur valeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 13, 'Le sage se fera aimer par ses discours; les grâces des insensés s’écouleront comme l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 14, 'Le don d’un insensé ne te sera pas utile; car cet homme a non un œil, mais une quantité d’yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 15, 'Il donnera peu, et il le reprochera beaucoup, il aura la bouche ouverte comme un héraut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 16, 'Il prête aujourd’hui, et il demandera demain; un tel homme est haïssable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 17, 'Le fou dira: Je n’ai point d’ami; on n’a point de reconnaissance du bien que je fais;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 18, 'Ceux qui mangent mon pain sont de vils flatteurs. Et que de fois, tous tant qu’ils sont, ils se moqueront de lui!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 19, '(Vulg. 20.) Mieux vaut glisser à cause de la terre qu’à cause de la langue, comme tombent les méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 20, '(21.)Un récit sans à-propos est comme un homme sans grâce; il sort habituellement de la bouche des gens grossiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 21, '(22.)Dans la bouche d’un fou, une parabole est choquante; car il n’a garde de la dire en temps opportun.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 22, '(23.)Tel est empêché de mal faire faute de moyens, et à l’état de repos il ne se sent point tenté. (24.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 23, 'Tel perd son âme par fausse honte; il la perd à cause de la présence de l’insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 24, '(25.)Tel par fausse honte promet une grâce à son ami, et s’en fait ensuite gratuitement un ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 25, '(26.)Le mensonge est pour l’homme une infamante tache; il est habituellement sur les lèvres des gens grossiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 26, '(27.)Mieux vaut un voleur qu’un menteur invétéré; mais tous les deux auront la perdition pour héritage. (28.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 27, 'Le déshonneur s’attache au mensonge, et la honte réside sans cesse avec le menteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 28, '(29.)Le sage s’élèvera aux honneurs par ses discours, et l’homme sensé se rendra agréable aux grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 29, '(30.)Celui qui travaille à la terre augmentera sa richesse, et celui qui plaît aux grands se fera pardonner une iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 30, '(31.)Les dons de l’hospitalité et les présents aveuglent les juges; ils sont dans leur bouche comme un frein qui détourne les réprimandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 31, '(32.)Sagesse cachée, trésor enfoui; à quoi servent-ils l’un et l’autre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 20, 32, '(33.)Mieux vaut un homme qui cache sa folie, qu’un homme qui cache sa sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 1, 'Mon fils, as-tu péché? ne recommence pas, et prie pour détourner la peine due à tes fautes passées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 2, 'Fuis le péché comme le serpent; car, si tu t’en approches, il te mordra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 3, 'Ses dents sont comme les dents du lion; elles tuent les âmes des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 4, 'Tout péché est comme un glaive à deux tranchants il n’est de guérison à ses blessures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 5, 'L’insolence et ses vertiges détruiront la richesse; ainsi sera détruite la maison du superbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 6, 'La prière de l’indigent s’élève de sa bouche jusqu’aux oreilles de Dieu, dont le jugement ne se fait pas attendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 7, 'Celui qui hait la réprimande suit les traces du pécheur, et celui qui craint Dieu se convertira du fond de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 8, 'On reconnaît de loin le riche à son langage; l’homme de bon sens sait comment lui échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 9, 'Celui qui bâtit une maison avec l’argent d’autrui, est comme celui qui appareille ses pierres dans la saison d’hiver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 10, 'L’assemblée des pécheurs est comme un monceau d’étoupes; leur fin sera d’être dévorés par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 11, 'Les pavés rendent unie la voie du pécheur; mais elle aboutit à l’abîme de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 12, 'Celui qui garde la loi est maître de ses pensées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 13, 'Et la sagesse est la crainte parfaite du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 14, 'Celui qui n’étudie pas ne s’instruira jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 15, 'Il est une habileté qui abonde en amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 16, 'La science du sage est aussi abondante que les eaux d’une inondation, et ses conseils sont comme une source de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 17, 'Le cœur du fou est comme une urne fêlée; il ne retiendra aucune connaissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 18, 'Si l’homme sensé entend une parole sage, il la louera et s’attachera à elle. Celui qui vit dans les plaisirs l’a aussi entendue; mais elle lui a été désagréable, et il l’a rejetée derrière ses épaules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 19, 'Le récit d’un fou est comme un fardeau que l’on porte en chemin; mais la grâce découlera des lèvres du sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 20, 'La parole du sage sera désirée dans les assemblées, et les cœurs méditeront sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 21, 'La sagesse est au fou comme une maison en ruines, et l’insensé ne sait dire que des paroles sans suite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 22, 'La doctrine est au fou comme des fers aux pieds, ou comme des menottes à la main droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 23, 'Le fou rit aux éclats; l’homme sage à peine sourit doucement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 24, 'La doctrine est à l’homme sensé comme un ornement d’or, comme un bracelet à la main droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 25, 'Le pied du fou est prêt à entrer en n’importe quel logis; l’homme habile est réservé à la porte des grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 26, 'L’indiscret se penchera par la porte pour voir dans la maison; l’homme bien élevé se tiendra debout au dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 27, 'C’est une grossièreté d’écouter aux portes; l’homme prudent ne pourra supporter une telle ignominie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 21, 28, 'Les lèvres des imprudents seront insupportables, là où les discours du sage seront mesurés. Le cœur des insensés est dans leur bouche; la bouche des sages est dans leur cœur. Lorsque l’impie maudit Satan, il se maudit luimême. Le semeur de rapports souille son âme; il se rendra odieux partout où il demeurera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 1, 'Le paresseux est comparé à une pierre couverte de fange, et c’est à qui le sifflera pour son ignorance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 2, 'Le paresseux est comparé à de la fiente de vache; tous ceux qui la ramassent se secouent les mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 3, 'Les enfants mal élevés sont la honte de leur père; une telle fille est digne d’abaissement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 4, 'La fille prudente est un héritage pour son mari, et celle qui se déshonore est l’affliction du père qui l’a engendrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 5, 'La femme hardie fait la honte de son mari et de son père; l’un et l’autre la méprisent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 6, 'Un récit fait hors de propos est comme de la musique dans la douleur; mais les réprimandes et les châtiments sont en tout temps l’œuvre de la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 7, 'Instruire un fou, c’est rajuster des tessons;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 8, 'C’est réveiller d’un profond sommeil un homme endormi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 9, 'Parler à un fou, c’est parler à un homme assoupi; à la fin, il dira: Qu’y a-t-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 10, 'Pleure sur un mort, car il est privé de lumière; pleure sur un fou, car il est privé d’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 11, 'Pleure plus doucement sur un mort, parce qu’il a trouvé le repos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 12, 'Et que la vie d’un fou est pire que la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 13, 'On s’afflige sur un mort pendant sept jours; on doit s’affliger sur un fou ou sur un impie tous les jours de leur vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 14, 'Ne multiplie point les discours avec un fou, et ne t’adresse pas à un homme sans intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 15, 'Garde-t’en, de peur d’en être embarrassé, et d’être souillé par son contact.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 16, 'Évite-le, et tu assureras ton repos, et tu ne t’affligeras point de sa démence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 17, 'Quoi de plus lourd que le plomb, et quel autre nom donner à l’insensé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 18, 'Le sable, le sel, un bloc de fer, sont plus faciles à supporter qu’un homme sans intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 19, 'Un revêtement de bois, bien lié à une bâtisse, ne bougera pas, même si la terre tremble; tel est un cœur affermi par les conseils de sa pensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 20, 'En aucun temps il ne faiblira; un cœur solidement assis sur la sagesse de la pensée est comme l’enduit ensablé qui orne un mur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 21, 'Des palissades placées sur une hauteur ne résisteront pas à la violence du vent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 22, 'Tel le cœur d’un fou, timide en ses pensées, fléchira devant tout sujet de crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 23, '(Vulg. 24.)Celui qui blesse un œil en tire des larmes; celui qui blesse un cœur en fait éclater les sentiments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 24, '(25.)En jetant une pierre à des oiseaux, on les disperse; en outrageant un ami, on rompt l’amitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 25, '(26.)Si tu as tiré l’épée contre ton ami, ne désespère pas; car il y a du retour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 26, '(27.)Si tu as ouvert la bouche contre un ami, ne crains rien; il reviendra. Mais il n’est point d’ami que ne chassent l’outrage, l’orgueil, la révélation d’un secret, les plaies de la fraude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 22, 27, '(28.)Sois fidèle à ton ami dans la pauvreté, pour te rassasier avec lui dans la richesse. (29.)Sois inébranlable au temps de son affliction, pour qu’en son héritage tu hérites avec lui. (30.)Avant la flamme, la vapeur et la fumée sortent de la fournaise; ainsi les injures précèdent l’effusion du sang. (31.)Je n’aurai point honte d’abriter un ami, et je ne me déroberai pas à sa vue, dût quelque malheur m’arriver de sa part. (32.)Mais ceux qui l’apprendront auront soin de l’éviter. (33.)Qui mettra une garde à ma bouche? qui posera sur mes lèvres un sceau inviolable, afin qu’elles ne me fassent point tomber, et que ma langue ne me perde point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 1, 'Seigneur, père et maître de ma vie, ne m’abandonnez pas à leur conseil; ne souffrez pas qu’à cause d’elles je tombe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 2, 'Qui mettra auprès de mes pensées les corrections, et auprès de mon cœur les leçons de la sagesse? afin que les hommes n’aient point à me reprocher mes inadvertances, et que mes péchés ne soient pas apparents;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 3, 'Afin que mes ignorances et mes fautes ne se multiplient point; que je ne succombe pas devant mes adversaires, et que je ne fasse point la joie de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 4, 'Seigneur, père et Dieu de ma vie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 5, 'Ne donnez pas à mes yeux de l’orgueil; détournez de moi la concupiscence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 6, 'Que ni la gourmandise ni l’appétit charnel ne s’emparent de moi; ne me livrez pas à une âme impudique!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 7, 'Enfants, écoutez la doctrine de la bouche; celui qui la gardera ne périra point par ses lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 8, 'Le pécheur sera pris par elles; l’insolent et le superbe trouveront en elles un sujet de chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 9, 'N’habitue point ta bouche à prêter des serments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 10, 'Ne t’accoutume pas à prononcer le nom du Saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 11, 'Car, comme un esclave que l’on met sans cesse à la question ne voit pas s’effacer ses meurtrissures, de même celui qui toujours prononce et jure le nom de Dieu ne sera pas pur de la tache du péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 12, 'L’homme qui jure beaucoup sera rempli d’iniquité, et le châtiment ne s’éloignera jamais de sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 13, 'S’il pèche par négligence, son péché est sur lui; si c’est par mépris, il aura péché doublement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 14, 'S’il jure en vain, il ne sera pas justifié, et sa maison sera envahie par une multitude de maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 15, 'Il est une parole qui nous expose à la mort; qu’elle ne se trouve pas en l’héritage de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 16, 'Toutes ces choses seront écartées des hommes pieux, et ils ne seront point entraînés dans le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 17, 'N’accoutume point ta bouche à la grossièreté impure; car il y a en elle des paroles de péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 18, 'Souviens-toi de ton père et de ta mère; car tu siéges parmi les grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 19, 'Garde-toi de t’oublier devant eux, et de prendre avec eux des habitudes légères; car tu désireras ensuite n’être jamais né, et tu maudiras le jour de ta naissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 20, 'L’homme accoutumé aux paroles outrageuses ne se corrigera de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 21, 'On multiplie les péchés de deux manières; une troisième attirera la colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 22, 'Une âme ardente est comme une flamme qui brûle; elle ne s’éteindra pas qu’elle ne soit rassasiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 23, 'Un homme débauché en la chair de son corps ne s’arrêtera pas qu’il n’ait allumé le feu qui le consumera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 24, 'Toute espèce de pain est bonne pour le débauché; il ne se lassera point jusqu’à ce qu’il meure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 25, 'L’homme qui transgresse la loi de la couche conjugale, se dit en son âme: Qui me voit?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 26, 'Les ténèbres m’environnent, les murs me cachent; nul ne me voit: qu’ai-je à craindre? Le Très-Haut ne se souviendra pas de mes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 27, 'Cet homme n’a peur que des regards des hommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 23, 28, 'Et il ignore que les regards du Seigneur, dix mille fois plus brillants que le soleil, surveillent toutes les voies des hommes, et pénétrent jusqu’aux recoins les plus cachés. Avant de naître, toutes choses sont connues de lui, et de même après qu’elles ont été faites. Cet homme sera puni sur la place de la ville, et il sera pris où il ne s’en doutait pas. (Vulg. 32.)Même chose adviendra à la femme qui a quitté son mari, et qui, d’un étranger, lui a donné un héritier. (33.)Car d’abord elle a désobéi à la loi du Très-Haut; secondement, elle a offensé son mari; en troisième lieu, elle s’est livrée à une débauche adultère, et a eu des enfants d’un autre homme. (34.)On l’entraînera elle-même devant l’assemblée des anciens, et on aura l’œil sur ses fils. (35.)De tels enfants n’étendront point leurs racines, et leurs rameaux ne porteront point de fruits. (36.)Quant à elle, sa mémoire périra dans les malédictions, et son opprobre sera ineffaçable. (37.)Et ceux qui lui survivront apprendront qu’il n’est rien de meilleur que la crainte de Dieu, et que rien n’est plus doux que de s’attacher aux commandements du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 1, 'La Sagesse louera son âme, et au milieu de son peuple elle se glorifiera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 2, 'Elle ouvrira la bouche en l’Église du Très-Haut, et devant sa milice elle se glorifiera, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 3, '(Vulg. 5.)Je suis sortie de la bouche du Très-Haut;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 4, '(6.)Et comme une nuée j’ai enveloppé la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 5, '(7.)J’ai eu mon tabernacle au plus haut des cieux, et mon trône sur une colonne de nuée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 6, '(8.)Seule j’ai fait le tour du ciel, et je me suis promenée au fond de l’abîme. Sur les flots de la mer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 7, '(9.)Sur toute la terre, sur chaque peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 8, '(10.)Sur toute nation, j’ai ma part de l’empire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 9, '(11.)En tous ces lieux j’ai cherché le repos, et j’ai dit: Quel est celui dont j’habiterai l’héritage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 10, '(12.)Alors le Créateur de toutes choses m’a donné ses ordres, et celui qui m’a créée a fixé mon tabernacle dans le repos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 11, '(13.)Et il m’a dit: Demeure en Jacob; prends ton héritage en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 12, '(14.)Il m’a créée au commencement, avant les temps, et je ne périrai point jusqu’à la consommation des siècles. Je suis attachée au service du Seigneur, devant lui, dans le saint tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 13, 'Et c’est ainsi que j’ai été établie dans Sion. Dieu m’a donné pour lieu de repos, comme à lui-même, la ville bien-aimée, et mon pouvoir est en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 16, 'Et j’ai pris racine chez un peuple glorifié, dans la part que possède le Seigneur en son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 17, 'Je me suis élevée comme le cèdre sur le Liban, ou le cyprès dans les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 18, 'Je me suis élevée comme le palmier des rivages de la mer, comme un plant de rosier de Jéricho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 19, 'Je me suis élevée comme un bel olivier, comme un platane.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 20, 'J’ai donné un parfum comme le cinnamome, comme le genêt aromatique; j’ai eu l’odeur suave de la myrrhe la plus exquise,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 21, 'Ou celle du galbanum, de l’onyx et de l’huile de myrrhe, ou celle de la vapeur d’encens dans le tabernacle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 22, 'J’ai étendu mes branches comme le térébinthe, et mes rameaux sont des rameaux d’honneur et de grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 23, 'Je suis comme une vigne d’où naît la grâce, et mes fleurs sont des fruits de gloire et de richesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 24, 'Venez à moi, vous qui me désirez, et rassasiez-vous de mes fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 25, '(27.)Mon souvenir est plus doux que le miel; mon héritage, plus doux qu’un rayon de miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 26, '(29.)Ceux qui me mangent auront encore faim; ceux qui me boivent auront encore soif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 27, '(30.)Celui qui m’écoute ne sera jamais confondu; ceux qui travaillent avec moi ne pèchent point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 28, '(32.)Tout ce que je viens de dire est le livre de l’alliance de Dieu Très-Haut; c’est la loi qu’a intimée Moïse; c’est l’héritage des tribus de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 29, '(35.)C’est Dieu qui remplit la sagesse comme le Phison, ou comme le Tigre, au retour des jours nouveaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 30, '(36.)C’est lui qui remplit l’intelligence comme l’Euphrate, ou comme le Jourdain au temps de la moisson.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 31, '(37.)C’est lui qui révèle la doctrine comme la lumière aussi abondante que le Géhon, aux jours de la vendange. Le premier n’a point connu parfaitement la Sagesse; de même, le dernier n’a pu la suivre à la trace. Car ses pensées sont plus nombreuses que les vagues de la mer, et ses conseils plus vastes que l’abîme. J’ai jailli dans le paradis, comme un canal sort d’un fleuve, ou comme l’eau que transporte un conduit. Et j’ai dit: J’arroserai mon verger; j’abreuverai mon potager. Et voilà que soudain mon canal s’est changé en fleuve, et mon fleuve est devenu une mer. Je rendrai encore la doctrine aussi lumineuse que l’aurore, et je révèlerai ces choses dans le lointain des siècles. Je répandrai en outre l’instruction comme une prophétie, et je la laisserai aux générations futures. Sachez que je n’ai point pris de la peine pour moi seule, mais pour tous ceux qui me cherchent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 24, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 1, 'Trois choses m’ont embellie, et m’ont rendue agréable au Seigneur et aux hommes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 2, 'La concorde entre les frères, l’amour du prochain; l’accord entre l’époux et l’épouse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 3, 'Mon âme a trois sortes d’hommes en haine, et je m’indigne de ce qu’elles existent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 4, 'Un mendiant orgueilleux, un riche trompeur, un vieillard adultère, dont l’intelligence est appauvrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 5, 'Jeune, tu n’as point amassé: comment acquerras-tu dans ta vieillesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 6, 'Qu’il est beau, avec des cheveux blancs, d’avoir l’équité! que la science du conseil convient bien aux anciens!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 7, 'Que la sagesse des vieillards est belle! que le conseil et l’intelligence siéent bien à ceux que le Seigneur a glorifiés!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 8, 'L’expérience est la couronne des vieillards; la crainte du Seigneur est leur gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 9, 'Neuf choses auxquelles je pense, je les ai en mon cœur estimées bienheureuses, et une dixième qui est sur mes lèvres:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 10, 'C’est un homme qui trouve sa joie en ses enfants, et qui, de son vivant, voit la chute de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 11, 'Heureux celui qui a pour compagne une femme sensée; qui n’est point tombé à cause de sa langue, et qui n’a point servi un homme indigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 12, 'Heureux celui qui a trouvé la prudence, et qui l’enseigne à des oreilles attentives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 13, 'Que celui qui a trouvé la sagesse est grand! mais il ne l’est pas plus que celui qui craint le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 14, 'La crainte du Seigneur est supérieure à tout;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 15, 'Celui qui la possède, à qui sera-t-il comparé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 16, '(Vulg. 18.) Toute plaie est supportable, mais non celle du cœur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 17, '(19.)Toute méchanceté, mais non celle de sa femme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 18, '(20.)Toute attaque, mais non celle de l’homme qui vous hait;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 19, '(21.)Toute vengeance, mais non celle d’un ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 20, '(22.)Il n’est point de tête pire que celle du serpent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 21, '(23.)De même il n’est point de colère pire que celle d’un ennemi. J’aimerais mieux demeurer avec un lion ou un serpent qu’avec une méchante femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 22, '(24.)La méchanceté d’une femme change son aspect; son visage est sombre comme un cilice. Au milieu de ses proches,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 23, '(25.)Son mari se met à table; et s’il vient à l’entendre, il gémit amèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 24, '(26.)Toute méchanceté est légère auprès de la méchanceté d’une femme; puisse le sort du pécheur tomber sur elle!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 25, '(27.)Telle est pour les pieds d’un vieillard une montée sablonneuse, telle la langue d’une femme pour un mari paisible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 25, 26, '(28.)Ne te laisse pas prendre à la beauté d’une femme, et garde-toi de la désirer pour épouse. (29.)Grand sujet de colère, d’importunité, de honte, (30.)Est la femme si elle surpasse en autorité son mari. (31.)Une méchante femme est la plaie du cœur, elle abaisse l’âme, elle attriste le visage. (32.)Une femme qui ne rend pas heureux son mari, lui affaiblit les mains, lui affaisse les genoux. (33.)Le commencement du péché vient de la femme; c’est à cause d’elle que nous mourons tous. (34.)Ne donne point d’issue à l’eau; ne donne pas d’autorité à la femme. (35.)Si elle ne marche pas à ta main, (36.) Sépare-la de ta chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 1, 'Heureux l’époux d’une femme bonne! le nombre de ses jours est doublé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 2, 'Une femme forte est la joie de son mari; elle multiplie ses jours au sein de la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 3, 'Une femme bonne est un bon partage; c’est le partage qui sera donné à ceux qui craignent le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 4, 'Riche ou pauvre, si leur cœur est bon, en tout temps leur visage sera joyeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 5, 'De trois choses mon cœur a crainte, et à la quàtrième j’ai le visage abattu:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 6, 'L’accusation injuste d’une ville, le rassemblement tumultueux du peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 7, 'Et la calomnie. Tout cela est plus terrible que la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 8, 'Mais une femme, tourment et deuil du cœur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 9, 'Jalouse d’une autre femme, porte le fléau de la langue, et en frappe tout le monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 10, 'Une méchante femme est comme le joug qui se balance sur le cou des bœufs; celui qui la possède ressemble à l’homme qui tient un scorpion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 11, 'Une femme adonnée au vin est un grand sujet d’amertume; elle ne pourra cacher son opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 12, 'Une femme débauchée se reconnaît à l’impudence de ses regards et de ses paupières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 13, 'Veille avec fermeté sur la fille qui ne rougit pas, de peur que, trouvant qui la loue, elle ne se livre ellemême.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 14, 'Veille sur son œil immodeste, et ne sois pas surpris si elle a commis une faute contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 15, 'Comme le voyageur altéré ouvre la bouche, et boit toute eau à sa portée, elle s’assoira devant chaque poteau, et devant toute flèche elle ouvrira son carquois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 16, 'La grâce d’une femme charmera son mari; elle engraissera ses os');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 17, 'Par son intelligence. C’est un don du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 18, 'Qu’une femme soit silencieuse; une âme bien disciplinée est sans prix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 19, 'Une femme modeste accumule grâce sur grâce,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 20, 'Et il n’est pas de trésor préférable à une âme maîtresse d’elle-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 21, 'La beauté d’une femme bonne, c’est l’ornement de sa maison; c’est le soleil se levant aux cieux du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 22, 'La beauté du visage dans l’âge mûr, c’est la lampe brillant sur le chandelier saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 23, 'De beaux pieds, avec une âme inébranlable, sont comme la base d’argent d’une colonne d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 24, 'Mon cœur s’attriste de deux choses; à la troisième, la colère vient en moi:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 25, 'L’homme de guerre indigent et délaissé, le sage méprisé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 26, 'Et celui qui passe de justice à péché; ce dernier, le Seigneur l’a réservé pour son \'glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 27, 'Le trafiquant évitera difficilement de commettre des fautes, et le tavernier ne pourra guère s’exempter du péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 26, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 1, 'Nombre d’hommes ont péché pour des choses sans intérêt; et tel, en cherchant à s’enrichir, a détourné les yeux de la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 2, 'Entre deux pierres, dans la jointure, il y a place pour planter un clou; de même, le péché est resserré entre le vendeur et l’acheteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 3, '(Vulg. 4.) Si tu ne te tiens avec zèle en la crainte de Dieu, ta maison sera bientôt renversée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 4, '(5.)L’ordure reste au crible remué; il en est de même des souillures de l’homme en ses raisonnements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 5, '(6.)La fournaise éprouve les vases de poterie; l’épreuve de l’homme est en ses réflexions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 6, '(7.)Aux fruits d’un arbre on voit sa culture; de même, aux discours d’un homme on voit les pensées de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 7, '(8.)Ne loue pas un homme avant qu’il ait parlé; car c’est là l’épreuve de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 8, '(9.)Si tu poursuis la justice, tu la prendras, et tu t’en revêtiras comme d’une robe de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 9, '(10.)Les oiseaux feront leur nid auprès de leurs semblables; la vérité retournera vers ceux qui en ont fait les œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 10, '(11.)Le lion guette sa proie; ainsi fait le péché aux ouvriers d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 11, '(12.)La sagesse est toujours l’entretien de l’homme pieux; l’insensé est changeant comme la lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 12, '(13.)Au milieu des insensés observe le moment de partir; au milieu des sages continue de demeurer. (14.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 13, 'L’entretien des fous irrite, et leur rire est l’ébat du péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 14, '(15.)Le langage d’un homme qui jure souvent fait dresser les cheveux, et à ce bruit tumultueux on se bouche les oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 15, '(16.)Querelle des orgueilleux, effusion du sang; il est dur d’entendre leurs invectives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 16, '(17.)À dévoiler les secrets on perd toute confiance; on ne trouvera plus d’ami de l’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 17, '(18.)Aime ton ami; engage-lui ta foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 18, '(19.)Mais, si tu as révélé son secret, ne retourne pas avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 19, '(20.)Car, de même qu’un homme détruit son ennemi, ainsi tu as détruit l’amitié de ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 20, '(21.)Et, comme celui qui de ses mains laisse échapper un oiseau, ainsi es-tu après avoir fait partir ton ami; tu ne le reprendras plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 21, '(22.)Ne le poursuis pas, car il est déjà loin; il s’est enfui comme le chevreuil qui se sauve du filet. Il est des blessures');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 22, '(23.)Que l’on peut guérir; on peut se réconcilier après des injures:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 23, '(24.)Mais celui qui a révélé des secrets n’a rien à espérer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 24, '(25.)Tel, en approuvant du regard, trame de mauvais artifices, et nul n’aura songé à l’éloigner de soi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 25, '(26.)Devant toi il adoucit son langage; il admire tout ce que tu dis; derrière toi il changera de ton, et fera scandale de tes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 26, '(27.)J’ai haï bien des choses, mais nul autant que lui, et le Seigneur le hait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 27, '(28.)Celui qui lance en l’air une pierre, la jette sur sa tête; les atteintes de la fraude rouvrent les blessures. (29.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 28, 'Celui qui creuse une fosse y tombera, et celui qui dresse un piége y sera pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 29, '(30.)Celui qui fait le mal en est lui-même enveloppé, et il ne saura d’où cela lui est venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 27, 30, '(31.)Les superbes raillent et outragent; mais la vengeance les guette comme un lion. (32.)Ceux qui se réjouissent de la ruine des justes seront pris au filet, et des douleurs les consumeront avant leur mort. (33.)La colère et ses emportements sont des abominations, et le pécheur les renferme en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 1, 'Celui qui se venge ressentira la vengeance du Seigneur, qui garde et gardera ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 2, 'Remets à ton prochain son offense; et alors, quand tu prieras, tes péchés te seront remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 3, 'Un homme peut-il conserver sa colère contre un homme, et demander le pardon du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 4, 'Il n’a point de miséricorde envers un homme son semblable, et il priera pour ses péchés!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 5, 'Chair lui-même, il nourrit sa colère; qui donc l’absoudra de ses péchés?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 6, 'Songe à ta fin, et cesse de haïr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 7, 'Souviens-toi de la corruption et de la mort, et reste fidèle aux commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 8, 'Souviens-toi des commandements, et ne sois pas irrité contre ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 9, 'Souviens-toi de l’alliance du Très-Haut, et ferme les yeux sur la faute de ton prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 10, 'Abstiens-toi de querelles, et tu diminueras tes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 11, 'Car un homme irascible allumera des querelles; un pécheur troublera des amis, et, parmi des gens vivant en paix, il sèmera la calomnie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 12, 'La flamme s’allumera selon la nature du bois; ainsi la colère d’un homme sera selon sa force; il s’exaspèrera selon sa richesse; il s’enflammera selon le sujet de la querelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 13, 'La discorde, dans sa précipitation, allume la flamme; la querelle, dans sa précipitation, verse le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 14, 'Si tu souffles sur une étincelle, tu la ranimes; si tu craches dessus, elle s’éteindra; et l’un et l’autre viennent de ta bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 15, 'Maudits soient le médisant et le fourbe; car ils ont perdu nombre d’hommes vivant en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 16, 'Une langue tierce a ému bien des hommes; elle les a dispersés de nations en nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 17, 'Elle a renversé les villes entourées de remparts; elle a ruiné les maisons des grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 18, '(Vulg. 19.) Une langue tierce a fait répudier des femmes fortes; elle les a privées de leurs labeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 20, 'Celui qui l’écoute n’aura point de repos, il n’aura plus de pain en sa demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 21, 'Les coups de fouet laissent des meurtrissures; les coups de langue brisent les os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 22, 'Nombre d’hommes ont péri par l’épée, mais pas autant que par la langue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 23, 'Heureux ceux qui sont à l’abri de ses atteintes, qui n’ont point essuyé sa colère, qui n’ont point traîné son joug, qui n’ont point été liés de ses chaînes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 24, 'Car son joug est un joug de fer, et ses chaînes sont des chaînes d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 25, 'La mort qu’elle cause est une mort funeste, et l’enfer est moins odieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 28, 26, 'Elle ne saisira pas les justes; ils ne seront point consumés par ses flammes. Ceux qui délaissent le Seigneur tomberont par elle; elle les brûlera et ne s’éteindra point. Elle se lancera sur eux comme un lion; elle les mettra en pièces comme une panthère. Prends garde; entoure d’épines ton enclos. Tiens renfermés ton argent et ton or; ne parle qu’avec poids et mesure, et à ta bouche mets une porte et des verrous. Sois attentif à ne point tomber par elle, et à ne te point laisser prendre à ses pièges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 1, 'L’homme miséricordieux prête à son prochain; celui qui a la main ouverte garde les commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 2, 'Prête à ton prochain au temps de sa nécessité, et, à ton tour, rends à ton prochain au temps convenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 3, 'Tiens ta promesse, engage-lui ta foi, et en toute occasion tu trouveras selon ton besoin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 4, 'Beaucoup ont regardé comme un gain l’argent prêté, et ils ont causé de la peine à ceux qui les avaient secourus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 5, 'Jusqu’à ce qu’il ait reçu, l’emprunteur baisera la main du prêteur, et, pour avoir de ses biens, il lui parlera d’une voix humble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 6, 'Mais, quand il faudra rendre, il traînera en longueur; il payera avec des promesses en l’air; il accusera les temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 7, 'S’il le peut, il donnera moitié avec peine, et il considèrera cela comme un gain que fait le préteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 8, 'S’il ne le peut, il l’aura dépouillé de ses biens, et se sera fait de lui gratuitement un ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 9, 'Il le payera en malédictions et injures, et, au lieu de le glorifier, il cherchera à lui faire honte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 10, 'Plusieurs à cause de cette perversité se sont excusés de préter; ils ont craint de se priver sans profit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 11, 'Néanmoins\' sois patient avec le pauvre, et ne lui fais pas attendre ton aumône.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 12, 'À cause du commandement, assiste le pauvre, et, à cause de son besoin, ne le renvoie pas les mains vides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 13, 'Perds de l’argent pour ton frère ou ton ami, et ne laisse pas cet argent se rouiller sous une pierre pour ta perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 14, 'Que ton trésor soit de faire les commandements du Très-Haut, et.il te profitera plus que l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 15, 'Renferme l’aumône dans tes celliers, et elle te préservera de tout mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 16, 'Elle combattra mieux pour toi, devant ton ennemi, que le bouclier du fort et la javeline du vaillant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 17, 'L’homme bienfaisant répondra pour son ami, et qui a perdu toute pudeur l’abandonnera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 18, 'N’oublie point la bonté de celui qui t’a cautionné; car il a engagé pour toi son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 19, '(Vulg. 20.) Le pécheur détruira les bienfaits de sa caution, et, en son cœur, l’ingrat abandonnera celui qui l’a protégé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 20, '(22.)Plusieurs qui prospéraient se sont perdus pour avoir cautionné, et ils ont été ébranlés comme les vagues de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 21, '(23.)Des hommes puissants ont quitté leurs demeures, et ils ont erré chez des nations étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 22, '(24.)Le pécheur tombant aux mains d’un mauvais débiteur, et poursuivant des entreprises, tombera sous le coup de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 23, 'Assiste ton prochain selon tes ressources, et veille à ne pas tomber toi-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 24, 'Avant tout, il faut pour vivre de l’eau, du pain, des vêtements, et une maison où cacher sa nudité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 25, 'Mieux vaut le repas du pauvre sous des solives, que des festins splendides chez des étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 26, 'Reçois de bonne grâce peu comme beaucoup.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 27, 'Triste existence que d’aller de maison en maison; où l’on s’arrête, on n’ose pas ouvrir la bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 29, 28, 'Traite tel hôte, et fais-le boire, pour être ensuite payé d’ingratitude, et en outre pour entendre des paroles amères: Va, apprête la table, et, si tu-as quelque chose sous la main, mange-le avec moi. (32.)Sors, mon hôte, fais place à un autre plus honorable; je dois recevoir mon frère, j’ai besoin de ma maison. (33.)Telles sont les deux choses insupportables à un homme sensé: les reproches d’une maison hospitalière et les insultes d’un créancier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 1, 'Qui aime son fils ne cessera de le châtier, afin qu’il se réjouisse en ses derniers jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 2, 'Qui corrige son fils sera récompensé en lui, et au milieu de ses reproches il en tirera gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 3, 'Qui instruit son fils sera envié par ses ennemis, et devant ses amis il se réjouira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 4, 'Le père n’est plus, et c’est comme s’il n’était pas mort: car, après lui, il a laissé qui lui ressemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 5, 'Quand il vivait encore, le père a vu son fils, et il s’est réjoui, et en mourant il ne s’est pas attristé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 6, 'Car contre ses ennemis il a laissé un vengeur, et à ses amis, un cœur reconnaissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 7, 'Pour ranimer son fils le père bandera ses plaies, et à chaque cri ses entrailles seront troublées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 8, 'Un cheval que l’on ne dompte pas devient rétif; un enfant laissé libre est indiscipliné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 9, 'Soigne ton fils à l’excès, et tu auras toujours peur pour lui; joue avec lui, et il t’affligera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 10, 'Ne ris pas avec lui, pour ne pas pleurer avec lui, et de peur que tu ne grinces des dents à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 11, 'Ne lui donne aucune autorité dans son enfance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 12, 'Façonne-lui les reins pendant qu’il est tout petit, de peur que, s’étant endurci, il ne te désobéisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 13, 'Instruis ton fils, travaille à le former, de peur qu’il ne t’offense à ton déshonneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 14, 'Ne lui pardonne aucune de ses négligences.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 15, 'Courbe son cou dès sa première jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 16, '(Vulg. 14.) Mieux vaut être pauvre avec la santé, et vigoureux avec la force, que riche, mais affligé en son corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 17, '(15.)Mieux vaut être en santé avec une bonne complexion que posséder tout l’or du monde; mieux vaut un corps robuste que d’innombrables trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 18, '(16.)Il n’est richesse préférable à la santé du corps, et il n’est plaisir au-dessus de la joie du cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 19, '(17.) Mieux vaut la mort qu’une vie amère, ou une maladie sans fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 20, '(18.)Un repas servi à une bouche close, c’est comme un festin déposé sur un sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 21, '(19.)À quoi bon des offrandes devant une idole? elle ne les mangera pas; elle n’en sentira pas le parfum.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 22, '(20.)Ainsi est celui que le Seigneur bannit de devant sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 23, '(21.)Il voit en gémissant les biens sous ses yeux, et il soupire comme l’eunuque qui tient une vierge en ses bras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 24, '(22.)N’abandonne pas ton âme à la tristesse, et ne t’afflige pas toi-même en ton conseil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 25, '(23.)La joie du cœur est la vie de l’homme, et l’allégresse promet une longue vie à l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 26, '(24.)Aime ton âme, console ton cœur, et chasse loin de toi la tristesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 27, '(25.)Car la tristesse en a tué un grand nombre, et elle n’est bonne à rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 28, '(26.)L’envie et la colère abrégent les jours, et les soucis engendrent une vieillesse prématurée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 29, '(Vulg., XXXIII, 16.) Comme celui qui grappille derrière les vendangeurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 30, '(17.)J’ai pris l’avance pour recevoir la bénédiction du Seigneur, et, comme un vendangeur, j’ai rempli le pressoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 31, '(18.)Considérez que je n’ai point travaillé pour moi seul, mais pour tous ceux qui cherchent la doctrine. (19.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 32, 'Écoutez-moi, grands du peuple, et vous, princes de l’Église, prêtez-moi une oreille attentive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 33, '(20.)À ton fils, à ta femme, à ton frère, à ton ami, ne donne de ton vivant aucun pouvoir sur toi, et n’abandonne pas tes biens à autrui, de peur que tu ne les regrettes et ne les leur redemandes ensuite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 34, '(21.)Tant que tu existes et que tu respires, ne trafique de toi avec aucune chair;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 35, '(22.)Car mieux vaut être prié par tes enfants que de recourir à leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 36, '(23.)En toutes tes œuvres, fais toujours le mieux possible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 37, '(24.)N’imprime pas de tache à ta gloire; mais le');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 38, '(25.)Fourrage, coups de verge et fardeaux à l’âne; pain, discipline et travail à l’esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 39, '(26.)Fais travailler ton serviteur, et tu auras du repos; laisse ses mains se relâcher, et il demandera la liberté. (27.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 30, 40, 'Le joug et les courroies doivent courber son cou; (28.)Et à l’esclave méchant, inflige la question et les tortures; mets-le à l’ouvrage, de peur qu’il ne devienne oisif; (29.)Car l’oisiveté enseigne le mal. (30.)Emploie-le à des travaux selon aptitude, et s’il est indocile, appesantis ses entraves; mais ne commets d’excès contre aucune chair, et ne fais rien sans jugement. (31.)Si tu as un esclave, qu’il soit comme toi; car tu l’as acheté du même sang que toi. Si tu as un esclave, traite-le comme toi-même; car tu auras besoin de lui comme de ton âme. (33.)Et que, s’étant échappé, il prenne la fuite, sur quelle voie le chercheras-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 1, '(Vulg., XXXIV.) Les espérances vaines et les chimères appartiennent à l’homme sans intelligence; les songes sur leurs ailes ravissent les insensés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 2, 'S’occuper d’un songe, c’est embrasser une ombre, ou courir après les vents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 3, 'La vision d’un songe, c’est comme le reflet d’un visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 4, 'Que peut-on purifier avec l’impur? et comment du mensonge pourra sortir la vérité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 5, 'La divination, les augures, les songes sont des choses vaines,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 6, 'Des fantaisies de l’âme comme celles d’une femme grosse. À moins qu’en sa visite le Très-Haut ne les ait envoyés, n’y mets point ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 7, 'Les songes ont égaré beaucoup d’hommes, et ceux qui se sont confiés en eux ont péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 8, 'La loi doit s’accomplir sans mensonge, et la sagesse a sa perfection dans une bouche fidèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 9, '(Vulg., 10.)Un homme instruit sait beaucoup; un homme expérimenté ne dit que des paroles pleines de sens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 10, '(11.)Celui qui n’a point d’expérience sait peu, et celui qui a été trompé acquiert plus d’habileté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 11, '(12.)J’ai vu beaucoup de choses en mes voyages, et plus encore par mon intelligence et mes réflexions. (13.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 12, 'Plus d’une fois j’ai été en danger de mort, et, grâce à elles, j’ai été sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 13, '(14.)L’âme qui craint le Seigneur vivra;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 14, '(15.)Car elle a mis son espérance en celui qui sauve les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 15, '(16.)Celui qui craint le Seigneur n’aura ni crainte ni inquiétude; car Dieu même est son espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 16, '(17.)Heureux l’âme de celui qui craint le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 17, '(18.)Vers qui se tourne-t-il, et qui sera son appui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 18, '(19.)Les yeux du Seigneur sont sur ceux qui l’aiment protecteur des puissances, soutien de la force, abri contre l’ardente chaleur, ombre à l’heure de midi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 19, '(20.)Il préserve des mauvais pas; il secourt dans les chutes; il élève l’âme; il éclaire les yeux; il donne la santé, la vie et la bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 20, '(21.)Un sacrifice d’iniquité est une oblation dérisoire; les moqueries des méchants sont réprouvées de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 21, '(22.)Le Très-Haut n’agrée point les offrandes des impies, et ce n’est point à cause de l’abondance des sacrifices qu’il remettra les péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 22, '(24.)Celui qui fait un sacrifice aux dépens des pauvres, est comme celui qui sacrifie le fils sous les yeux du père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 23, '(25.)Le pain des indigents est leur vie; celui qui les en prive est un homme de sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 24, '(26.)Celui qui détruit la paix du mariage est le meurtrier de son prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 25, '(27.)Celui qui détourne le salaire du journalier, c’est comme s’il répandait son sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 26, '(28.)Si l’un bâtit et que l’autre détruise, qu’y ont-ils gagné, sinon de la peine?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 27, '(29.)Si l’un prie et que l’autre maudisse, duquel le maître écoutera-t-il la voix?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 28, '(30.)Si l’on se baigne, après avoir touché un mort, et qu’on revienne le toucher, à quoi bon s’être purifié?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 29, '(31.)Tel est l’homme qui jeûne à cause de ses');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 31, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 1, '(Vulg., XXXV.) Garder la loi, c’est multiplier les oblations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 2, 'S’attacher aux commandements, c’est faire des victimes de salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 3, '(Vulg., 4.)Offrir de la fleur de farine, c’est rendre grâce; faire l’aumône, c’est offrir un sacrifice de louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 4, '(5.)S’abstenir du péché, c’est faire la volonté du Seigneur; s’abstenir de l’iniquité, c’est se le rendre propice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 5, '(6.)Ne comparais pas vide devant le Seigneur; (7.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 6, 'Car toutes ces choses sont faites pour obéir aux commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 7, '(8.)L’offrande du juste engraisse l’autel; elle est en odeur de suavité pour le Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 8, '(9.)Le sacrifice du juste est agréable, et le souvenir ne s’en perdra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 9, '(10.)Rends gloire au Seigneur d’un œil riant, et ne retranche rien des prémices de tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 10, '(11.)Egaye ton visage en faisant ton offrande, et sanctifie la dîme par ta joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 11, '(12.)Donne au Très-Haut selon ce qu’il t’a donné, et offre lui, l’œil riant, ce que tes mains ont gagné. (13.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 12, 'Car le Seigneur est celui qui rétribue, et il te rétribuera au septuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 13, '(14.)Ne fais pas des dons pour acheter des grâces; car il ne les agréera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 14, '(15.)Ce n’est pas la peine que tu fasses un sacrifice d’iniquité; car le Seigneur est juge, et près de lui la gloire du rang n’est rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 15, '(16.)Il n’aura égard à personne contre le pauvre, et il exaucera l’oraison de celui que l’on a injustement traité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 16, '(17.)Il ne négligera pas la prière de l’orphelin; il ne méprisera pas la veuve lorsqu’elle épanchera ses plaintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 17, '(18.)Les larmes de la veuve ne descendent-elles pas sur son visage; ne crie-t-elle pas contre celui qui les fait couler?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 18, '(20.)Celui qui adore Dieu avec bonne volonté lui sera agréable, et sa prière s’élèvera jusqu’aux nuées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 19, '(21.)L’oraison de l’humble traverse les nuées; et elle ne sera pas rappelée qu’elle ne soit près de Dieu, elle ne se retirera pas avant la visite du Très - Haut; car c’est le juge équitable qui rendra justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 20, '(22.)Et le Seigneur ne tardera pas, et il ne patientera pas avec les hommes sans miséricorde, qu’il ne leur ait brisé les reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 21, '(23.)Et aux gentils il fera sentir sa vengeance, jusqu’à ce qu’il ait exterminé la multitude des superbes, et broyé les sceptres des mauvais rois;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 22, '(24.)Jusqu’à ce qu’il ait rétribué chacun selon ses œuvres (or les œuvres des hommes sont selon leurs pensées);');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 23, '(25.)Jusqu’à ce qu’il ait rendu justice à son peuple, et qu’il l’ait réjoui de sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 24, '(26.)Cette miséricorde est salutaire aux jours de l’affliction, comme les nuées pluvieuses au temps de la sécheresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 32, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 1, 'Ô Dieu, maître de toutes choses, ayez pitié de nous, jetez sur nous vos regards!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 2, '(Vulg., XXXVI.) Faites tomber votre épouvante sur tous les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 3, 'Levez la main sur les nations étrangères, et qu’elles voient votre puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 4, 'De même que, devant elles, vous avez été sanctifié parmi nous; de même, devant nous, glorifiez-vous par elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 5, 'Qu’elles vous connaissent, comme nous vous connaissons; car nul n’est Dieu, hormis vous, ô Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 6, 'Renouvelez vos signes; faites éclater d’autres prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 7, 'Glorifiez votre main et votre bras droit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 8, 'Éveillez votre courroux, et versez votre colère;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 9, 'Exterminez l’adversaire, et broyez l’ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 10, 'Hâtez l’heure, souvenez-vous de votre serment, et qu’ils racontent vòs merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 11, 'Celui qui aura échappé au glaive, qu’il soit dévoré par la fureur du feu, et ceux qui ont maltraité votre peuple, qu’ils trouvent leur perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 12, 'Brisez la tête des princes de nos ennemis, qui disent: Il n’est point de Dieu, hormis nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 13, 'Réunissez toutes les tribus de Jacob; votre cœur, bon et magnifique, prendra soin de l’abondance de leurs festins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 33, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 1, 'À veiller pour des richesses, on se dessèche la chair; les soucis qu’elles donnent éloignent le sommeil. (Vulg. XXXI.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 2, 'L’inquiétude de l’insomnie demandera l’assoupissement, et le sommeil remédiera à une grave maladie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 3, 'Le riche a pris de la peine pour amasser des biens, et au temps du repos il sent la satiété de ses délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 4, 'Le pauvre a pris de la peine quand ses ressources ont diminué, et au temps du repos il sent le besoin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 5, 'Celui qui aime l’or ne sera pas justifié, et celui qui poursuit la corruption en sera plein lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 6, 'Plusieurs sont tombés à cause de l’or; étalé à leur face, il a été leur perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 7, 'C’est une idole, une pierre d’achoppement pour ceux qui lui offrent des sacrifices, et tous les insensés y sont pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 8, 'Heureux le riche qui a été trouvé sans tache, et qui n’a point marché à la suite de l’or!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 9, 'Quel est-il? et nous le proclamerons heureux; car il a fait des merveilles au milieu de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 10, 'Qui donc a été éprouvé par l’or et reconnu parfait? Gloire à celui-là! Qui a pu transgresser la loi, et ne l’a pas transgressée? Qui a pu faire le mal, et ne l’a pas fait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 11, 'De celui-là les biens seront affermis, et l’Église racontera ses aumônes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 12, 'Es-tu assis devant une grande table? n’ouvre pas le gosier en la voyant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 13, 'Et ne dis pas: Qu’il y a de mets sur cette table!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 14, 'Souviens-toi qu’il est mal d’avoir l’œil mauvais');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 15, 'Quelle chose pire que l’œil a été créée? c’est pour cela que sur tout visage il tombe des larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 16, 'Garde-toi d’étendre la main où il regardera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 17, 'Ne te froisse pas avec autrui dans le plat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 18, 'Distingue ce qui est à ton voisin de ce qui est à toi-même, et en toute chose observe-toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 19, 'Mange comme un homme ce que l’on t’a servi, et ne sois pas avide, pour ne point te rendre odieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 20, 'Arrête-toi le premier par savoir-vivre, et ne te montre pas insatiable, de peur d’offenser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 21, 'Et si tu es à table avec beaucoup de monde, ne sois pas le premier de tous à étendre la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 22, 'Il faut peu à un homme bien élevé, et il ne suffoque pas sur la couche du festin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 23, '(Vulg., 24.) Un estomac modéré procure un sommeil salutaire; on se lève de bonne heure, et on est maître de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 24, '(23.)L’homme insatiable a une insomnie laborieuse, des tranchées et la colique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 25, 'Et si l’on t’a contraint de trop manger, lève-toi au milieu du festin, et tu recouvreras le calme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 26, 'Écoute-moi, mon fils, ne me dédaigne pas, et tu finiras par approuver mes conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 27, 'Sois diligent en tous tes travaux, et nulle infirmité ne t’atteindra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 28, 'Les lèvres de plusieurs béniront celui qui est magnifique en ses festins, et les témoignages sur sa libéralité seront unanimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 29, 'La ville murmurera contre l’avare, et les témoignages que l’on rendra sur son avarice seront exacts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 30, 'Ne fais pas le vaillant en buvant beaucoup; car le vin a perdu bien des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 34, 31, 'La forge, par un bain, éprouve la trempe de l’acier; ainsi le vin éprouve par des querelles le cœur des superbes. Le vin pour l’homme est une seconde vie, si on le boit avec modération. Qu’est la vie pour l’homme avili par le vin? Le vin a été créé pour la joie de l’homme: Bu selon le besoin et à temps, il est l’allégresse du cœur et le charme de l’âme; Bu avec excès, il est l’amertume de l’âme, il cause la colère et les désastres. L’ivresse augmente l’audace de l’insensé; elle est son écueil, elle l’énerve et lui attire des blessures. Dans un repas où l’on boit du vin, ne réprimande pas ton voisin, et garde-toi de le mépriser dans sa gaieté. Ne lui dis point d’injures, et ne le presse pas en lui réclamant ce qu’il te doit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 1, 'Es-tu institué chef? ne t’en glorifie pas; sois avec les autres comme l’un d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 2, '(Vulg., XXXII.) Aie soin d’eux d’abord; alors seulement assieds-toi, et ne te mets pas à table avant d’avoir fait tout ce que tu leur dois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 3, 'Afin que tu trouves ta joie en eux, et que tu reçoives d’eux une couronne d’action de grâces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 4, 'Parle, toi qui es le plus ancien, cela t’appartient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 5, 'Parle avec connaissance de cause, et n’interromps pas la musique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 6, 'Quand c’est le moment d’écouter, ne te répands pas en paroles, et ne fais pas étalage de sagesse hors de propos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 7, 'Un concert de musiciens, tandis que boivent les convives, est comme l’escarboucle que scelle un joyau d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 8, 'La mélodie ajoute à la douceur du vin, comme un cachet de jaspe à l’éclat de l’or qui l’enchâsse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 9, '(Vulg., 10.)Jeune homme, parle à peine, et quand il est nécessaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 10, '(11.)Laisse-toi questionner deux fois, et réponds brièvement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 11, '(12.)Dis beaucoup en peu de mots; sois comme celui qui sait et se tait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 12, '(13.)Parmi les grands, ne t’égale pas à eux; et, quand un autre parle, ne cause pas longuement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 13, '(14.)L’éclair devance le tonnerre; la grâce ánnonce la modestie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 14, '(15.)Lève-toi à l’heure, et ne sois pas le dernier; retourne à ta maison sans retard, et là réjouis-toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 16, 'Fais ce que tu avais médité, et ne pèche point en paroles orgueilleuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 17, 'Et, sur toutes choses, bénis Celui qui t’a créé et enivré de ses biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 18, 'Ceux qui craignent le Seigneur accepteront sa doctrine, et ceux qui pour lui se lèvent de grand matin seront bénis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 19, 'Qui cherche la loi en sera rempli; qui feint de la chercher sera scandalisé en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 20, 'Ceux qui craignent le Seigneur trouveront justification, et feront briller ses justices comme la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 21, 'Mais le pécheur évitera la réprimande, et trouvera un interprète de la loi au gré de ses désirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 22, 'L’homme de conseil ne dédaigne pas la considération; l’étranger et l’orgueilleux ne craindront point');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 23, 'D’agir d’eux-mêmes sans réflexion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 24, 'Ne fais rien sans conseil; n’attends pas, pour te repentir, que ce soit chose faite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 25, 'Évite la voie des achoppements, et ne te heurte pás contre des pierres. Ne te fie pas à un chemin inexploré,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 35, 26, 'Et tiens-toi en garde de tes propres enfants. En toute œuvre, confie-toi en ton âme; car telle est l’observation des commandements. Qui croit à la loi s’attache aux commandements, et qui est fidèle au Seigneur ne déchoira pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 1, '(Vulg., XXXIII.) Il n’arrivera aucun mal à celui qui craint le Seigneur; mais plus d’une fois il sera sauvé de la tentation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 2, 'L’homme sage ne haïra point la loi; celui qui, en la cherchant, use de feinte, est comme une barque dans la tempête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 3, 'L’homme sensé croit à la loi, et la loi lui est fidèle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 4, 'Comme la prière des justes. Prépare ta parole, et tu seras écouté; recueille ta doctrine et réponds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 5, 'Les entrailles d’un fou sont comme la roue d’un chariot; sa pensée est comme un essieu qui tourne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 6, 'Un ami moqueur est comme un étalon qui hennit sous tout cavalier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 7, 'Pourquoi un jour serait-il plus long qu’un autre jour, puisque la lumière de chaque jour de l’année vient du soleil?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 8, 'Le Seigneur lui-même, en sa sagesse, les a distingués.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 9, 'Et il a diversifié les temps et les fêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 10, 'Il a glorifié les uns, il a sanctifié les autres; il en a laissé dans le nombre des jours. Ainsi les hommes sortent tous de la terre, de la terre dont Adam a été créé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 11, 'Dans la plénitude de sa sagesse, le Seigneur les a distingués, et il a diversifié leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 12, 'Il en a glorifié, il en a béni, il en a sanctifié, il en a rapproché de lui. Il en a maudit, il en a humilié, il en a chassé du lieu où ils s’étaient fixés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 13, 'Telle est l’argile dans la main du potier;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 14, 'Il la façonne selon son bon plaisir. Tels sont les hommes dans les mains de leur Créateur; il les rétribue comme il le juge à propos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 15, 'Contre le mal est le bien; contre la mort est la vie; de même contre le juste est le pécheur. Contemple pareillement les œuvres du Très-Haut; tu verras deux à deux l’une opposée à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 16, 'Pour moi, j’ai veillé le dernier, et j’ai hérité de ceux qui m’ont devancé depuis le commencement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 17, '(Vulg., XXXVI, 14.) Seigneur, ayez pitié de votre peuple, qui a été appelé de votre nom, et d’Israël, que vous avez fait l’égal de votre premier-né.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 18, '(15.) Prenez en compassion Jérusalem, cité de votre sanctification, cité de votre repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 19, '(16.) Remplissez Sion pour exalter la vérité de vos paroles; remplissez votre peuple de votre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 20, '(17.) Rendez par lui témoignage à vos créatures, créées dès le commencement; faites vivre les prophéties faites en votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 21, '(18.) Donnez leur salaire à ceux qui vous attendent, et que vos prophètes soient reconnus dignes de foi. Exaucez, Seigneur, la prière de vos suppliants,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 22, '(19.) Selon la bénédiction d’Aaron à votre peuple; et tous ceux qui sont sur la terre reconnaîtront que vous êtes, Seigneur, le Dieu des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 23, '(20.) Les entrailles se nourrissent de tout aliment; mais il en est de meilleurs les uns que les autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 24, '(21.) Le palais goûte les mets provenant de la chasse; de même, le cœur intelligent discerne les paroles mensongères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 25, '(22.) Un cœur tortueux donnera de la tristesse; l’homme expérimenté lui résistera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 26, '(23.) Telle femme épousera n’importe quel homme; mais telle fille est préférable à telle autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 28, '(24.)La beauté d’une femme égaie le visage; elle l’emporte sur toutes les concupiscences de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 29, '(25.)Si sa langue a la douceur et la miséricorde, son mari n’est point dans la condition ordinaire des fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 30, '(26.)Celui qui prend une femme commence sa fortune; c’est une aide semblable à lui, c’est la colonne de son repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 36, 31, '(27.)Où il n’y a point de clôture, le champ est ravagé; où il n’y a point de femme, l’homme gémit et s’égare. (28.)Car qui se fiera au voleur habile, errant de ville en ville? Tel est l’homme qui n’a point de nid, et qui se couche où la nuit le surprend.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 1, 'Tout ami dira: Et moi aussi j’ai lié amitié avec lui; mais il est tel ami qui n’est ami que de nom. N’est-ce pas une tristesse qui dure jusqu’à la mort,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 2, 'Quand le compagnon et ami change en haine son amitié?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 3, 'Ô mauvaise pensée, d’où viens - tu, en tourbillonnant, couvrir la terre de tes fourberies?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 4, 'Tel compagnon se réjouit avec son ami dans la prospérité; au jour de la tribulation il sera contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 5, 'Tel compagnon s’afflige avec son ami; mais c’est en vue de sa gourmandise; vienne la guerre, il prendra même un bouclier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 6, 'N’oublie jamais en ton âme un ami, et souvienstoi de lui dans ta richesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 7, '(Vulg., 8.)Tout conseiller donne un conseil; mais il en est qui conseillent pour eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 8, '(9.)Mets ton âme en garde contre le conseiller; sache d’abord de quoi il a besoin; car il te conseillera pour lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 9, 'Prends garde que, pour toi, il ne s’en remette au hasard, qu’il ne te dise:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 10, 'Ta voie est bonne; puis qu’il ne se tienne à l’écart, pour voir ce qui t’adviendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 11, 'Ne prends pas conseil de celui qui te regarde d’un œil soupçonneux; cache ton conseil à tes envieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 12, 'Ne prends pas conseil d’une femme sur sa rivale, ni d’un poltron sur la guerre, ni d’un marchand sur une emplette, ni d’un acheteur sur ce que tu veux vendre, ni d’un envieux sur la reconnaissance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 13, 'Ni d’un homme sans pitié sur la miséricorde, ni d’un paresseux sur n’importe quelle œuvre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 14, 'Ni d’un journalier, que tu as pris à demeure, sur l’achèvement de tes travaux, ni d’un domestique indolent sur le plus ou le moins d’ouvrage; de tous ces hommes, n’attends pas un bon conseil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 15, 'Mais recherche la société d’un homme pieux qui, à ta connaissance, garde les commandements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 16, 'Dont l’âme est selon ton âme, et qui, si tu tombes, souffrira avec toi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 17, 'Et prends un conseil venant du cœur; car il n’est point pour toi de plus sûr conseiller.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 18, 'En effet, l’âme d’un tel homme annonce habituellement plus que sept sentinelles au guet sur un lieu d’observation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 19, 'Et surtout prie le Très-Haut, afin qu’il rende ta voie droite, selon la vérité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 20, 'Avant toute œuvre, la raison; avant toute affaire, le conseil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 21, 'Traces des changements du cœur: quatre choses en naissent: le bien et le mal, la vie et la mort; et une cinquième, qui domine les autres, une langue qui ne sait pas s’arrêter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 22, 'Tel homme est habile, il en instruit un grand nombre, et, pour son âme, il est inutile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 23, 'Celui qui n’est sage qu’en paroles est odieux; il finira par manquer de pain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 24, 'Car il n’a pas reçu la grâce du Seigneur, puisqu’il est dépourvu de toute sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 25, 'Tel est sage en son âme, et l’on peut se fier aux fruits de son intelligence qui sortent de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 26, 'Un homme sage instruira son peuple, et l’on peut se fier aux fruits de son intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 27, 'Un homme sage sera comblé de bénédictions, et tous ceux qui le voient l’estimeront heureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 28, 'La vie d’un homme est le nombre de ses jours; mais les jours d’Israël sont innombrables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 29, 'Le sage aura, parmi son peuple, la confiance pour héritage, et son nom vivra dans l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 30, 'Mon fils, éprouve ton âme pendant ta vie; vois ce qui mauvais pour elle, et garde-toi de le lui donner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 37, 31, 'Car toutes choses ne conviennent pas à tous, et toute âme n’agrée pas toutes choses. Ne sois insatiable d’aucune volupté, et ne t’abandonne pas à la bonne chère. Car l’excès d’aliments est une fatigue, et la gourmandise est proche du choléra. Beaucoup ont fini par intempérance; mais celui qui s’observe ajoutera à la durée de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 1, 'Honore le médecin de ses honoraires, à cause de la nécessité de recourir à lui; parce que le Seigneur aussi l’a créé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 2, 'Car la guérison vient du Très-Haut, et celui qui l’opère recevra les présents du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 3, 'La science du médecin relèvera sa tête, et devant les grands il sera respecté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 4, 'Le Seigneur a créé les médicaments qui sortent de la terre, et un homme sensé n’aura point de répugnance contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 5, 'L’eau n’a-t-elle pas été adoucie par du bois, dans le temps que Dieu faisait connaître sa puissance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 6, 'Et lui-même a donné la science aux hommes, pour être glorifié en ses merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 7, 'Le Seigneur guérit par ces plantes, et il ôte la douleur de l’homme. Celui qui en a la science fera une composition de ces simples, et jamais il ne viendra à bout d’achever son ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 8, 'La paix de Dieu est sur la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 9, 'Mon fils, si tu tombes malade, ne néglige pas de te soigner; mais prie le Seigneur, et lui-même te guérira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 10, 'Retire-toi du péché, rends droites tes mains, et purifie ton cœur de toute faute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 11, 'Fais un don d’agréable odeur; présente un mémorial de fleur de farine, et une oblation en t’humiliant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 12, 'Et ensuite appelle le médecin; car le Seigneur l’a créé; et qu’il ne s’éloigne point de toi, puisque tu as besoin de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 13, 'Il est un temps où eux aussi ont en leurs mains des offrandes de suave odeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 14, 'Eux aussi prieront le Seigneur de les faire prospérer en soulagement et guérison, pour la conservation d’une vie en danger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 15, 'Celui qui pèche contre son Créateur tombera dans les mains des médecins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 16, 'Mon fils, verse des larmes sur un mort; donne le signal des lamentations, comme un homme cruellement affligé; ensevelis son corps selon sa condition, et ne néglige point son sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 17, 'Pleure amèrement, pleure à chaudes larmes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 18, 'Et mène son deuil, selon son mérite, un jour ou deux, de peur de la médisance; puis laisse-toi consoler de cette tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 19, 'Car de la tristesse provient la mort, et la tristesse du cœur énerve le courage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 20, 'La tristesse aussi chemine avec celui que l’on mène en prison, et la vie du mendiant est telle que son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 21, 'N’abandonne pas ton cœur à la tristesse; mais éloigne-la, et souviens-toi de ta fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 22, 'Ne la perds pas de vue; car il n’est point de retour; et, sans utilité pour celui que tu pleures, tu te seras nui à toi-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 23, 'N’oublie pas la loi qu’il a subie; elle est la même pour toi; hier c’était moi, c’est toi aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 24, 'Fais reposer le souvenir du mort en son repos, et console-toi sur lui de la séparation de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 25, 'La sagesse du docteur lui vient à ses heures de repos; en rendant moindres ses distractions on devient sage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 26, 'Celui qui mène la charrue, qui se glorifie de tenir l’aiguillon, poussant et retournant les bœufs au labourage, et qui ne s’entretient qu’avec les fils des taureaux, comment deviendra-t-il sage?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 27, 'Il appliquera son cœur à tracer des sillons, et ses veilles seront pour la nourriture de ses vaches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 28, 'Il en est de même de tout artisan ou constructeur; il passe au travail les nuits comme les jours; ceux qui gravent des sceaux s’occupent constamment à diversifier leurs figures. Ils appliqueront leur cœur à faire une gravure ressemblante, et leurs veilles seront pour la perfection de leur ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 29, 'Il en est de même du forgeron se tenant près de l’enclume et observant le fer encore brut; la vapeur du feu dessèchera ses chairs, et il s’évertuera à la chaleur de sa fournaise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 30, 'Le bruit du marteau exercera son oreille, et ses yeux seront fixés sur le modèle de son ouvrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 31, 'Il appliquera son cœur à la perfection de ses travaux, et ses veilles seront consacrées à les orner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 32, 'Il en est de même du potier, assis à la besogne; avec ses pieds il fait tourner la roue; il est toujours en souci pour ses vases, et il en fait un grand nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 33, 'Il moulera l’argile à la main; il l’assouplira en la foulant aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 34, 'Il appliquera son cœur à la vernir, et ses veilles seront consacrées à nettoyer sa fournaise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 38, 35, 'Tous ceux-là ont mis leur confiance en l’adresse de leurs mains, et chacun d’eux est expert en son art. Sans eux, une ville ne serait point habitée; Ils n’y seront point comme passagers; ils ne la quitteront pas: mais ils ne seront pas haut placés dans l’Église; Ils ne siégeront pas sur la chaise du juge; ils ne concevront pas les motifs du jugement; ils seront incapables de déployer au grand jour la jurisprudence et l’équité. On ne les trouvera pas occupés aux paraboles. Mais ils affermiront l’ordre en s’occupant des choses du siècle; leur prière se fera en travaillant à leur art, auquel ils appliqueront leur âme en pensant à la loi du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 1, 'Pour le sage, il recherchera la sagesse de tous les anciens, et s’occupera de l’étude des prophéties.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 2, 'Il gardera les récits des hommes renommés, et entrera dans les secrets des paraboles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 3, 'Il recherchera le sens caché des proverbes, et comprendra les allusions des paraboles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 4, 'Il prêtera son ministère aux grands, et paraîtra devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 5, 'Il parcourra les contrées étrangères; car ainsi il éprouvera le bien et le mal parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 6, 'Il appliquera son cœur à veiller de grand matin, devant Dieu son créateur, et il priera en présence du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 7, 'Et il fera sa prière à haute voix; il demandera la rémission de ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 8, 'Si cela plaît au Seigneur tout-puissant, il sera rempli de l’esprit d’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 9, 'Il répandra, comme des torrents de pluie, les paroles de sa sagesse, et dans sa prière il rendra grâces au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 10, 'Le Seigneur dirigera ses conseils et son instruction, et il sera initié aux secrets du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 11, 'Il manifestera la doctrine qu’on lui a enseignée, et il se glorifiera de garder l’alliance de la loi du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 12, 'Beaucoup loueront sa prudence, et son nom ne sera jamais effacé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 13, 'Sa mémoire ne périra pas, et son nom vivra dans les générations des générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 14, 'Les gentils raconteront sa sagesse, et l’Église annoncera ses louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 15, 'S’il vit, il laissera meilleure renommée que mille autres; et, s’il entre dans le repos, il sera heureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 16, 'J’ai médité encore, et je vais parler; la lumière abonde en moi, comme celle de la lune en son plein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 17, 'Écoutez-moi, fils religieux, et croissez comme la rose sur le bord des eaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 18, 'Et répandez une odeur de suavité comme l’encens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 19, 'Et portez des fleurs comme le lis, exhalez-en le parfum, et chantez ensemble un cantique de louanges. Bénissez le Seigneur en toutes ses œuvres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 20, 'Faites voir la grandeur de son nom; rendez-lui grâce par des louanges, en chantant des lèvres, au son des cithares, et dites pour lui rendre grâces:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 21, 'Toutes les œuvres du Seigneur sont souverainement belles; tous ses commandements seront accomplis en leur temps, et toute chose sera attendue au temps marqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 22, 'À sa parole l’eau s’est arrêtée comme un bloc, et à un seul mot de sa bouche il y a eu des réservoirs d’eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 23, 'À son ordre tout se fait selon son bon plaisir, et nul ne peut rien diminuer du salut qu’il donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 24, 'Les œuvres de toute chair sont devant lui, et il n’y a pas à se cacher de ses regards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 25, 'Il a tout vu dans les siècles des siècles, et rien n’est merveilleux devant sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 26, 'Il n’y a point à dire: Pourquoi ceci? À quoi bon cela? Car toutes choses ont été créées pour leur utilité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 27, 'Sa bénédiction, comme un fleuve, a tout inondé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 28, 'Et, comme un déluge, elle a enivré la terre; de même les gentils auront sa colère pour héritage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 29, 'Comme quand il a changé des eaux en une mer saumâtre. De même que ses voies sont droites pour les saints, ainsi il y aura des pierres d’achoppement pour les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 30, 'Les biens, dès le commencement, ont été créés pour les bons, et les maux pour les méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 31, 'Les premières choses utiles dans la vie de l’homme sont l’eau, le feu, le fer, le sel, la fleur de froment,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 32, 'Tout pour les justes vient à bien, et tourne à mal pour les pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 33, 'Il est des esprits qui ont été créés pour punir, et dans leur colère ils ont appesanti leurs fouets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 34, 'Et quand les temps seront accomplis, ils déploieront leur force; ils assouviront la fureur de Celui qui les a créés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 39, 35, 'Le feu, la grêle, la famine, la mort, tout cela a été créé pour la vengeance de Dieu. Les dents des bêtes fauves, et les scorpions, et les vipères, et le glaive tiré pour l’extermination des impies, Se réjouiront d’exécuter ses ordres; ils se tiendront prêts sur la terre pour le moment du besoin; et, l’heure venue, ils ne désobéiront pas à sa parole. À cause de cela, dès le commencement, je me suis affermi, j’ai médité, et j’ai écrit. Toutes les œuvres du Seigneur sont bonnes, et à l’heure voulue elles donneront toute leur utilité. Et il n’y a point à dire: Ceci est pire que cela; car chaque chose sera éprouvée en son temps. Et maintenant chantez à pleine voix et de toute votre âme, et bénissez le nom du Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 1, 'Un grand sujet d’inquiétude a été créé pour tout homme, et un joug bien dur pèse sur les fils d’Adam, du jour où ils sortent du sein de leur mère, jusqu’au jour où ils sont ensevelis dans la mère commune à tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 2, 'C’est le jour de la fin, c’est l’appréhension de l’avenir; toutes les pensées, tous les cœurs en sont épouvantés:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 3, 'Depuis le roi assis sur le trône, dans l’éclat de sa gloire, jusqu’à l’homme abaissé dans la terre et la cendre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 4, 'Depuis celui qui porte une couronne et de l’hyacinthe, jusqu’au pauvre qui se revêt de lin écru. La colère et l’envie, le trouble et l’agitation, et la crainte de la mort, et le ressentiment, et la discorde,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 5, 'Même à l’heure du repos, sur la couche dressée pour le sommeil de la nuit, troublent sa pensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 6, 'Il est en repos si peu que rien; et pendant ce court moment, il fait le guet, en songe, comme durant le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 7, 'Il est inquiété par les visions de son âme, comme celui qui s’est enfui d’un combat. Au temps de son salut, il se réveille, stupéfait de sa terreur qui était sans objet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 8, 'Cette terreur est avec toute chair, depuis l’homme jusqu’aux bestiaux, et avec les pécheurs sept fois');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 9, 'Plus. La mort, le sang, la discorde, le glaive, les oppressions, la famine, les brisements, les fléaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 10, 'Ont été créés contre les méchants; et c’est à cause d’eux qu’est arrivé le déluge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 11, 'Tout ce qui vient de la terre retourne à la terre, et tout ce qui vient des eaux rentre dans la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 12, 'Tout don corrupteur et toute iniquité périront; la bonne foi subsistera dans l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 13, 'Les richesses des injustes sècheront comme un ruisseau; elles auront le retentissement du tonnerre pendant la pluie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 14, 'Tel met sa joie à ouvrir des mains avides; ceux qui pèchent ainsi périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 15, 'La race des impies ne multipliera pas ses rameaux, et les racines des impurs sont sur l’escarpement des rochers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 16, 'Elle avait fait grand bruit; elle sera arrachée du bord des eaux et des rives des fleuves, avant toute herbe des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 17, 'La grâce est comme un jardin béni, et la miséricorde existe toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 18, 'La vie est douce quand, en travaillant, on se suffit à soi-même; mieux vaut cependant trouver un trésor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 19, 'Les enfants et la fondation d’une ville affermissent une renommée; mieux que l’un et l’autre vaut une femme sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 20, 'Le vin et la musique charment le cœur; mieux que l’un et l’autre vaut l’amour de la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 21, 'La flûte et la harpe ont la douceur du miel; mieux que l’un et l’autre vaut une langue gracieuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 22, 'Ton œil désirera la grâce et la beauté; mieux que l’un et l’autre vaut l’herbe du champ que tu as ensemencé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 23, 'Un ami et son compagnon vont à l’occasion l’un au-devant de l’autre; mieux vaut l’accord d’un époux et d’une épouse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 24, 'Des frères se prêtent secours au temps de l’afflic');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 25, 'L’or et l’argent donnent une démarche assurée; le bon conseil est plus estimé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 26, 'Les richesses et la force exaltent le cœur; mieux vaut la crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 27, 'Rien n’affaiblit celui qui a la crainte du Seigneur; il n’a pas besoin de chercher d’autre secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 28, 'La crainte du Seigneur est comme un jardin de bénédictions, revêtu d’une gloire au-dessus de toute gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 29, 'Mon fils, ne mène pas la vie d’un mendiant; mieux vaut mourir que mendier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 40, 30, 'L’homme qui regarde la table d’autrui n’a pas une vie raisonnable; il souille son âme avec des mets étrangers. L’homme instruit et bien élevé s’en gardera. La mendicité sera douce à une bouche sans pudeur, et le feu s’allumera dans ses entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 1, 'Ô mort, que ton souvenir est amer à l’homme vivant en paix au milieu de ses richesses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 2, 'À l’homme exempt de soucis, prospérant dans toutes choses, et pouvant encore goûter les plaisirs de la table!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 3, 'Ô mort, ta sentence est bonne à l’homme indigent, dont la force est défaillante,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 4, 'Déjà vieux, inquiet sur toutes choses, sans espoir, et ayant perdu patience.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 5, 'Ne crains pas ta sentence de mort; souviens-toi de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 6, 'Qu’avez-vous à refuser au bon plaisir du Très-Haut? Ni dix, ni cent, ni mille ans de vie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 7, 'Ne sont en enfer l’objet d’une accusation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 8, 'Les enfants des pécheurs sont des enfants exécrés, ainsi que ceux qui hantent les demeures des impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 9, 'Les enfants des pécheurs perdront leur héritage, et une honte ineffaçable s’attachera à leur race.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 10, 'Les enfants feront des reproches à un père impie; car à cause de lui ils seront dans l’opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 11, 'Malheur à vous, impies, qui avez délaissé la loi dù Dieu Très-Haut!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 12, 'Tant que vous vivrez, vous vivrez maudits; quand vous mourrez, vous serez rétribués en malédictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 13, 'Tout ce qui est sorti de la terre retournera dans la terre; ainsi les impies, sortis de la malédiction, retourneront à la perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 14, 'Le deuil des hommes est pour le corps; le nom des pécheurs n’est point bon et sera effacé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 15, 'Songe à ta renommée; elle sera durable, plus que mille grands monceaux d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 16, 'Les jours d’une bonne vie sont comptés; une bonne renommée subsiste dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 17, 'Enfants, gardez en paix la discipline; la sagesse cachée, c’est un trésor enfoui: de quelle utilité sont-ils l’un et l’autre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 18, 'Mieux vaut un homme qui cache sa folie, qu’un homme qui cache sa sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 19, 'Ayez honte pour les choses que je vais dire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 20, 'Il n’est pas toujours à propos de rougir; et toutes choses, quoique faites de bonne foi, ne sont pas approuvées de tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 21, 'Devant votre père et votre mère, ayez honte de la débauche; devant le roi et les grands, ayez honte du mensonge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 22, 'Devant le juge et le prince, ayez honte de la négligence; devant la synagogue et le peuple, ayez honte des déréglements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 23, 'Devant votre associé et votre ami, ayez honte de l’iniquité; à cause du lieu de votre résidence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 24, 'Ayez honte du vol. Ayez honte d’offenser la vérité ou l’alliance de Dieu, de mettre les coudes sur la table, de prendre ou de donner avec mépris,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 25, 'De ne point rendre un salut, d’être regardé par une prostituée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 26, 'Ayez honte de vous détourner de l’un de vos proches, de prendre soit le bien d’autrui, soit ce que vous avez donné;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 41, 27, 'D’être d’intelligence avec une femme mariée, et de circonvenir sa servante; gardez-vous d’approcher de sa couche. Ayez honte de prononcer des paroles injurieuses sur un ami; et, après lui avoir fait un don, ne le lui reprochez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 1, 'Aie honte aussi de répéter et de redire ce que tu as entendu, de révéler le secret qu’on t’a confié. Alors tu');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 2, 'N’aie point honte de garder la loi du Très-Haut et son alliance, ni de rendre un jugement qui condamne un impie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 3, 'Ni de te prononcer dans une affaire entre ton compagnon et un voyageur, ni dans l’attribution d’un héritage où tes amis sont intéressés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 4, 'Ni de te servir de balances et de poids justes, ni d’acquérir peu ou beaucoup;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 5, 'Ni d’être indifférent à la vente ou au trafic, ni de châtier avec sévérité tes enfants, ni d’ensanglanter le flanc d’un méchant esclave.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 6, 'La clôture est bonne à une méchante femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 7, 'Où il y a beaucoup de mains tiens tout fermé; quoi que tu donnes, saches-en le poids et la mesure; écris ce que tu livres et ce que tu reçois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 8, 'N’aie point honte de corriger l’insensé ou le fou, même le vieillard repris en justice avec des jeunes gens, et tu seras un homme vraiment instruit, et tous les vivants t’estimeront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 9, 'Une fille est pour son père une cause secrète d’insomnie; le souci qu’elle lui donne chasse le sommeil; il craint que sa fraîcheur ne se passe pendant sa jeunesse, ou que mariée elle ne soit peut-être haïe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 10, 'Il craint que, vierge, elle ne soit profanée et enceinte dans la maison paternelle; ou qu’étant avec un mari, elle ne manque à sa foi; ou que mariée, elle ne demeure stérile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 11, 'Autour d’une fille que rien ne fait rougir, fais bonne garde, de peur qu’elle ne te rende le jouet de tes ennemis, la fable de la ville, la réprobation du peuple, et qu’elle ne te couvre de honte aux yeux de la multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 12, 'Ne fais pas attention à la beauté d’un homme, et ne passe point ton temps au milieu des femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 13, 'Car comme le ver s’engendre dans un manteau, ainsi l’iniquité de la femme naît de la femme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 14, 'Mieux vaut la méchanceté d’un homme que les bontés d’une femme; la femme déshonore et conduit à l’opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 15, 'Je me souviendrai toujours des œuvres du Seigneur, et je raconterai ce que j’ai vu; les œuvres du Seigneur sont conformes à ses paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 16, 'Le soleil illumine tout ce qu’il a regardé, et la création est pleine de sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 17, 'Le Seigneur n’a-t-il pas inspiré les saints pour qu’ils publient toutes les merveilles qu’il a affermies, lui le Tout-Puissant, afin que l’univers fût affermi pour sa gloire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 18, 'Il a sondé l’abîme et les cœurs, et il a pénétré tous les artifices des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 19, 'Car le Seigneur connaît toute science, et il a regardé les signes du temps; il révèle le passé et l’avenir; il découvre les traces des choses secrètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 20, 'Nulle pensée ne lui échappe; nulle parole ne lui est cachée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 21, 'Il a décoré les merveilles de sa sagesse, et, ni avant les siècles, ni dans le siècle présent, il n’y est rien ajouté;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 22, 'Il n’en est rien ôté, et il n’a eu nul besoin de conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 23, 'Que ses œuvres sont louables! et ce qui est visible n’en est qu’une étincelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 24, 'Elles vivent toutes, elles subsistent pour tous les siècles; et, en toute circonstance, toutes lui obéissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 25, 'Il y a toujours deux choses, l’une opposée à l’autre, et Dieu n’a rien créé d’imparfait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 26, 'L’une complète le bien de l’autre; et qui sera rassasié en voyant sa gloire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 42, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 1, 'Le firmament dans sa pureté est la gloire des cieux, et la beauté du ciel est une vision de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 2, 'Le soleil, apparaissant à son lever, annonce le jour, luminaire merveilleux, œuvre du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 3, 'Il dessèche les champs à son midi; et qui résistera à son ardeur? Soufflant une fournaise allumée pour les œuvres de la flamme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 4, 'Le soleil, avec une triple force, brûle les montagnes, exhale une vapeur embrasée, et, en dardant ses rayons, affaiblit les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 5, 'Le Seigneur qui l’a créé est grand, et de sa parole il en a hâté la course.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 6, 'Et la lune, en toutes choses, on observe ses phases; elle indique les temps, elle est le signe des changements de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 7, 'Elle est le signe des fêtes; sa lumière diminue après sa plénitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 8, 'Le mois tient d’elle son nom; sa lumière s’accroît merveilleusement à partir du moment où elle se renouvelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 9, 'Lampe des camps, du haut des cieux elle brille dans le firmament du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 10, 'La gloire des étoiles est la beauté des cieux; mais au plus haut des cieux, la splendeur qui éclaire, c’est le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 11, 'À la parole du Saint, les astres sont debout, prêts à lui obéir; ils ne se fatigueront jamais de leurs veilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 12, 'Vois l’arc-en-ciel, et bénis celui qui l’a créé; qu’il est beau quand il brille de tout son éclat!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 13, 'Il trace dans le ciel un cercle de gloire, et c’est la main du Très-Haut qui l’a tendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 14, 'À son ordre, la neige se hâte de tomber; et quand il le juge bon, les éclairs s’empressent de resplendir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 15, 'Les trésors de sa colère s’ouvrent, et les nuées volent comme des oiseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 16, 'Dans sa grandeur, il durcit les nuées; elles se brisent, et tombent en grêle comme des pierres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 17, 'À sa vue, les montagnes s’ébranlent; à un signe de sa volonté, le vent du midi se déchaîne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 18, 'Il donne à la terre les douleurs de l’enfantement, et par la voix du tonnerre, et par le souffle impétueux de l’aquilon, et par les tourbillons de la tempête,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 19, 'Il répand la neige comme des bandes d’oiseaux qui s’abattent, ou comme une nuée de sauterelles qui descend et se pose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 20, 'L’œil admire la beauté de sa blancheur, et le cœur est épouvanté de ses inondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 21, 'Il répand aussi sur la terre des frimas comme le sel, et la glace se cristallise en pointes comme des épines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 22, 'Le vent froid de l’aquilon souffle, et la glace se gèle au-dessus des eaux; elle rend immobile toute surface liquide; elle revêt les ruisseaux comme d’une cuirasse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 23, 'Elle dévore les montagnes; elle brûle le désert; elle détruit la verdure comme le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 24, 'Le remède à tout cela est qu’un brouillard humide accoure; telle la rosée réjouit après une ardente chaleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 25, 'Par sa seule pensée, le Sauveur apaise l’abîme, et c’est lui qui l’a creusé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 26, 'Ceux qui naviguent sur la mer racontent ses dangers, et nous sommes en admiration de ce qu’entendent nos oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 27, 'C’est là que sont les œuvres étranges et surprenantes de Dieu, et la diversité des êtres vivants; c’est là qu’ont été créées les baleines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 28, 'Par sa volonté, toutes choses tendent heureusement à leur but, et par sa parole elles sont coordonnées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 29, 'Nous parlerons beaucoup, et nous manquerons de paroles; lui seul est l’achèvement des discours; il est tout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 30, 'Nous lui rendons gloire; mais jusqu’à quel point le pouvons-nous? car lui seul est grand; il est au-dessus de ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 31, 'Le Seigneur est très-grand, et il est redoutable, et merveilleuse est sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 32, 'En rendant gloire au Seigneur, élevez-le autant que vous le pourrez; il sera plus élevé encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 43, 33, 'En le glorifiant, déployez toutes vos forces, ne vous lassez pas; car vous ne l’atteindrez jamais. Qui l’a vu, qui en pourra rien dire? Qui parlera de sa grandeur telle qu’elle est? Nous ne connaissons qu’un petit nombre de ses ouvrages; beaucoup d’autres nous sont cachés plus grands encore. Car le Seigneur a tout créé, et aux justės il a donné la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 1, 'Louons maintenant les hommes illustres, nos pères, de qui nous sommes issus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 2, 'Le Seigneur, dès les premiers âges, les a comblés de beaucoup de gloire et d’honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 3, 'Dominateurs en leurs royaumes, hommes célèbres par leur puissance, ils ont pris conseil de leur sagesse, ayant annoncé l’avenir par des prophéties.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 4, 'Ils ont été les chefs du peuple en ses conseils, et ils l’ont été par l’intelligence des lettres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 5, 'Leur doctrine renfermait de sages paroles; ils ont eu recours aux accords de la musique, et nous ont transmis les cantiques au moyen de l’écriture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 6, 'C’étaient des hommes riches, doués d’une grande force, faisant régner la paix en leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 7, 'Ils ont tous été glorifiés en leur postérité, après avoir été la gloire de leur temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 8, 'Tels, parmi leurs descendants, ont laissé un grand nom pour avoir chanté leurs louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 9, 'D’autres sont oubliés; leur souvenir s’est perdu comme s’ils n’avaient point existé; ils ont vécu comme s’ils n’étaient point nés, et leurs enfants après eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 10, 'Mais les premiers ont été des hommes miséricordieux, et leurs actes de justice ne sont pas livrés à l’oubli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 11, 'Avec leur postérité subsiste');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 12, 'Un bon héritage; leurs enfants sont dans l’alliance du Seigneur; leur postérité s’est affermie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 13, 'Et leurs enfants se sont affermis à cause d’eux; leur race demeurera dans tous les siècles, et leur gloire ne sera point effacée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 14, 'Leurs corps ont été ensevelis en paix, et leur nom vit d’âge en âge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 15, 'Les peuples rediront leur sagesse, et l’Église publie leurs louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 16, 'Énoch fut agréable au Seigneur, et il a été transporté au ciel, modèle de pénitence pour les générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 17, 'Noé fut trouvé parfaitement juste, et au temps de la colère il est devenu un signe de réconciliation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 18, 'À cause de cela il est resté des hommes sur la terre, et à cause de cela advint le déluge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 19, 'Et Dieu fit avec lui une alliance éternelle, pour que désormais il n’y eût plus un déluge effaçant toute chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 20, 'Le grand Abraham, père d’une multitude de nations, n’a point eu son égal en gloire; il a gardé la loi du Très-Haut; il est entré dans son alliance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 21, 'Et l’a scellée de sa chair, et à l’épreuve il a été trouvé fidèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 22, 'À cause de cela, Dieu lui a déclaré avec serment qu’en sa semence toutes les nations seraient bénies, et son peuple multiplié comme les grains de poussière;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 23, 'Et sa race élevée autant que les étoiles; et qu’elle aurait pour héritage la terre promise depuis ses confins jusqu’au fleuve, et d’une mer à l’autre mer..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 44, 24, 'Et il a renouvelé à Isaac les promesses faites à son père Abraham, De bénir tous les hommes et de perpétuer l’alliance, et il a déposé cette alliance sur la tête de Jacob. Il l’a reconnu en ses bénédictions, et lui a donné pour héritage la terre de Chanaan; et il l’a partagée, et il l’a distribuée aux douze tribus. Et il a suscité un homme issu de lui, plein de miséricorde, trouvant grâce aux yeux de toute chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 1, 'Moïse fut aimé de Dieu et des hommes, et sa mémoire est en bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 2, 'Le Seigneur l’a rendu en gloire l’égal des saints, et il l’a fait grand et terrible à ses ennemis, et à sa parole il a fait cesser les prodiges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 3, 'Il l’a glorifié à la face des rois; il lui a donné ses commandements devant son peuple, et il lui a montré sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 4, 'Il l’a sanctifié dans sa foi et dans sa douceur; il l’a élu entre toute chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 5, 'Il lui a fait entendre sa voix, et l’a conduit dans la nuée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 6, 'Et il lui a donné face à face les commandements, la loi de vie et de science, pour qu’il enseignât à Jacob son alliance, à Israël ses jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 7, 'Et il a élevé en sainteté autant que lui Aaron son frère, de la tribu de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 8, 'Il a fait avec celui-ci une alliance éternelle, et il lui a donné le sacerdoce du peuple; il l’a comblé de gloire et de bonheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 9, 'Et il l’a revêtu d’une robe de gloire, il l’a fait briller d’une majesté glorieuse, et il l’a fortifié par l’appareil de la puissance:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 10, 'Les caleçons de lin, la robe traînante, l’éphod; et il l’a entouré de boutons de grenades d’or, et d’une multitude de clochettes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 11, 'Afin qu’à chacun de ses pas elles rendissent un son que l’on entendît dans le temple comme un avertissement pour les enfants de son peuple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 12, 'La robe sainte, tissue d’or, d’hyacinthe et de pourpre entremêlés; le rational du jugement, manifestation de la vérité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 13, 'Tissu d’écarlate, œuvre d’art; avec ses pierres précieuses, gravures de cachet enchâssées d’or, œuvre de lapidaire, mémorial des noms gravés, selon le nombre des tribus d’Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 14, 'La couronne d’or au-dessus de la tiare, empreinte en relief de sa sainteté, gloire d’honneur, œuvre de force, charme des yeux, ornement');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 15, 'Plein de grâce. Avant lui, depuis les premiers âges, il n’y avait rien eu de pareil;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 16, 'Et nul n’a revêtu un tel costume, hormis ses fils et leurs descendants à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 17, 'Deux fois par jour, sans exception, ses victimes seront offertes en holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 18, 'Moïse lui a consacré les mains, et l’a oint avec l’huile sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 19, 'Dieu a fait avec Aaron et avec sa semence une alliance perpétuelle pour qu’ils le servent; qu’ils aient le sacerdoce, et qu’en son nom ils bénissent son peuple tant que dureront les jours du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 20, 'Il l’a choisi entre tous les vivants pour faire au Seigneur des sacrifices et des oblations d’une odeur de suavité comme mémorial, et pour prier en faveur de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 21, 'Il lui a donné, avec ses commandements, l’autorité dans les motifs des jugements; celle d’enseigner à Jacob ses témoignages, et d’éclairer Israël en sa loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 22, 'Des étrangers à sa tribu l’envièrent, et se soulevèrent contre lui dans le désert, avec des transports de fureur: c’étaient les hommes qui suivaient Dathan et Abiron, et la troupe de Coré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 23, 'Le Seigneur vit cela, et ne l’agréa point, et ils périrent en l’impétuosité de sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 24, 'Il fit en eux des prodiges, et les flammes du feu qu’il alluma les consumèrent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 25, 'Et il ajouta à la gloire d’Aaron, et il lui donna un héritage: il lui donna pour sa part les prémices de tous les fruits;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 45, 26, 'Il prépara pour ses fils d’abord des vivres en abondance; car ils se nourrissent des sacrifices offerts au Seigneur, et il les a donnés à lui et à sa semence. Mais ils ne doivent pas avoir en héritage de terre parmi le peuple, et ils n’y auront point de part; car leur part d’héritage est le Seigneur. Et Phinéès, fils d’Éléazar, fut le troisième en gloire; il rivalisa avec son aïeul en la crainte de Dieu. Et quand le peuple se pervertit, il lui résista, malgré la bonté de son âme, et il pria pour Israël. À cause de cela, Dieu fit une alliance de paix avec lui; il le fit chef des choses saintes et de son peuple, afin que la dignité du sacerdoce fût assurée pour tous les siècles à lui et à sa semence. Il fit aussi alliance avec David, de la tribu de Juda; l’héritage du roi se transmit, de fils en fils, à un seul; l’héritage d’Aaron se transmit à tous. Que le Seigneur nous donne, en notre cœur, la sagesse de juger son peuple avec équité, afin que leurs biens subsistent et que leur gloire passe à leur dernière postérité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 1, 'Josué, fils de Navé, fut puissant à la guerre; il succéda comme prophète à Moïse, et il fut, suivant son nom,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 2, 'Grand pour sauver les élus, pour tirer vengeance des ennemis soulevés, et pour se mettre en possession de l’héritage d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 3, 'Qu’il eut de gloire lorsqu’il leva les mains, et qu’il fit tomber son glaive sur les cités!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 4, 'Qui donc avant lui fut si vaillant? car le Seigueur lui-même conduisait les guerriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 5, 'De sa main n’arrêta-t-il pas le soleil, quand il n’y eut qu’un seul jour à la place de deux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 6, 'Il invoqua le Très-Haut, le Tout-Puissant, lorsqu’il brisa les ennemis tout alentour, et le souverain Seigneur l’exauça en faisant tomber sur eux une grêle de pierres d’une force terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 7, 'Dieu souleva la guerre contre les gentils, et il les extermina, comme ils résistaient en la descente d’Oronin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 8, 'Afin que les nations connussent l’armure invincible qui les écrasait; car la guerre de Josué était en présence du Seigneur, et il avait suivi le Tout-Puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 9, 'Et, du temps de Moïse, il avait fait acte de miséricorde avec Caleb, fils de Jéphonné, en tenant tête à un ennemi, en s’opposant à ce que le peuple tombât dans le péché, en imposant silence aux murmures des méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 10, 'Aussi tous les deux furent-ils sauvés seuls des six cent mille hommes de pied, pour faire entrer le peuple dans son héritage, en la terre où coulent le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 11, 'Et le Seigneur doua Caleb d’une grande force, et il demeura avec lui jusqu’à sa vieillesse, pour l’établir sur les hauts lieux de la terre promise; et sa postérité recueillit son héritage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 12, 'Afin que tous les fils d’Israël vissent qu’il est bon de marcher à la suite du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 13, 'Et les Juges, tous tant qu’ils furent, chacun au nom du Seigneur, dont le cœur ne se pervertit pas, et qui ne se détournèrent point du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 14, 'Que leur mémoire soit bénie! que leurs os refleurissent dans leurs sépulcres!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 15, 'Que leur renommée se transmette à leurs fils glorifiés par eux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 16, 'Samuel fut aimé de son Seigneur; il en fut le prophète; il institua la royauté; il sacra les chefs de son peuple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 17, 'Il jugea la Synagogue selon la loi du Seigneur, et le Seigneur visita Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 18, 'À cause de sa foi il fut un prophète infaillible, et il fut reconnu fidèle en ses visions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 19, 'Et il invoqua le Seigneur tout-puissant lorsqu’il brisa ses ennemis de toutes parts, en faisant l’oblation d’un agneau à la mamelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 20, 'Et du haut du ciel le Seigneur tonna, et au milieu d’un grand bruit il fit entendre sa voix. Et il écrasa les chefs des Tyriens et tous les princes des Philistins. Et au temps du repos éternel il prit à témoin le Seigneur et le Christ. Je n’ai pris, dit-il, à chair vivante rien de ses richesses, jusqu’à la sandale, et nul homme n’a rien à réclamer de moi. Et, après s’être endormi, il prophétisa, et fit voir au roi sa fin; et de la terre il éleva la voix en prophétisant, pour effacer le dérèglement du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 1, 'Et après cela Nathan se leva pour prophétiser, du temps de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 2, 'De même que l’on met à part la graisse d’une hostie pacifique, de même David fut distingué parmi les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 3, 'Il se joua des lions comme des chevreaux, et des ours comme de jeunes brebis. Dès sa jeunesse');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 4, 'Ne tua-t-il point un géant? ne tira-t-il point le peuple de son opprobre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 5, 'Il leva la main, et avec la pierre de sa fronde il abattit la superbe de Goliath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 6, 'Car il avait invoqué le Seigneur très-haut, qui voulut que sa main tuât un homme redoutable à la guerre, pour relever le front de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 7, 'Ainsi le peuple le glorifia par myriades, et le loua à cause de la bénédiction du Seigneur, qui lui faisait porter un diadème de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 8, 'Car il brisa les ennemis tout alentour; il anéantit les Philistins armés contre lui; il leur écrasa le front, qu’ils n’ont plus relevé jusqu’à nos jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 9, 'Dans toutes ses œuvres il rendit grâces au Saint, au Très-Haut, en des chants de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 10, 'Il le loua de toute son âme, et il aima celui qui l’avait créé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 11, 'Et il institua des chantres devant l’autel, et par le son des cithares il adoucit leurs chants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 12, 'Il donna aux fêtes leur solennité, et il sanctifia toutes les heures du jour en prescrivant aux chantres de louer le saint nom du Seigneur, et, dès l’aurore, de faire retentir le lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 13, 'Le Seigneur lui remit ses péchés, et il éleva son front pour toujours, et il lui donna une alliance de rois et un trône de gloire en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 14, 'Après lui vint un fils plein de sagesse, et, à cause de ses victoires, il jouit au loin du repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 15, 'Salomon régna en des jours de paix; pour lui Dieu avait tout calmé alentour, afin qu’il bâtit un temple en son nom, et qu’il lui préparât pour toujours un lieu consacré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 16, 'Combien tu as été sage dès ta jeunesse! quelle plénitude d’intelligence tu as reçue, abondante comme un fleuve! Ton âme a découvert la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 17, 'Et tu l’as remplie des mystères de tes paraboles; ta renommée s’est étendue jusqu’aux îles, et tu as été aimé en ta paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 18, 'Les nations ont admiré tes chants, tes proverbes, tes paraboles, tes interprétations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 19, 'Au nom du Seigneur, du Dieu qui est surnommé Dieu d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 20, 'Tu as amassé l’or comme de l’étain; tu as multiplié l’argent comme du plomb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 21, 'Puis tu t’es adonné aux femmes, et tu as été dissolu en ton corps;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 22, 'Tu as terni ta gloire; tu as souillé ta race aù point d’attirer sur tes enfants la colère de Dieu (je suis pénétré de douleur en songeant à ta folie);');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 23, 'Au point que ton royaume fut partagé en deux, et que d’Éphraïm sortit une royauté rebelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 24, 'Mais le Seigneur ne délaissera pas sa miséricorde, et ne détruira pas son ouvrage; il n’exterminera pas la race de son élu, et n’anéantira pas la postérité de celui qui l’a aimé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 47, 25, 'Il a donné un rejeton à Jacob, et à David une racine issue de lui. Et Salomon s’endormit avec ses pères. Et il laissa après lui une race insensée parmi son peuple, Roboam, faible d’intelligence, qui s’aliéna le peuple par son conseil. Alors Jéroboam, fils de Nabat, égara Israël, et mit Ephraïm sur la voie du péché. Et leurs crimes se multiplièrent, Au point qu’ils furent chassés de leur pays. Et ils cherchèrent à faire toute sorte de mal, jusqu’à ce que la vengeance tombât sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 1, 'Et le prophète Élie s’éleva comme un feu, et sa parole brilla comme une lampe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 2, 'Il fit venir sur eux la famine, et, à cause de l’envie qu’ils lui portaient, il les réduisit à un petit nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 3, 'À la parole du Seigneur il tint le ciel fermé, et en fit descendre trois fois la flamme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 4, 'Combien tu t’es glorifié, ô Élie, par tes prodiges! et qui sera célébré autant que toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 5, 'Tu as ressuscité un homme que possédait la mort; à la parole du Très-Haut tu l’as rappelé des enfers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 6, 'Tu as conduit les rois à leur perte; et les superbes, tu les as fait tomber de leur couche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 7, 'Tu as ouï en Sina les reproches, et en Horeb l’arrêt de la vengeance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 8, 'Tu as sacré des rois pour en punir d’autres, et des prophètes pour être tes successeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 9, 'Tu as été ravi par un tourbillon de feu, avec un char et des chevaux de feu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 10, 'Tu es inscrit pour réprimander, quand les temps seront venus, afin d’apaiser la colère avant qu’elle éclate, de réconcilier le cœur du père avec les enfants, et de rétablir les tribus de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 11, 'Heureux ceux qui t’ont vu, et qui ont été honorés de ton amitié!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 12, 'Car nous aussi nous vivrons de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 13, 'Élie a été enveloppé d’un tourbillon; cependant Élisée a été rempli de son esprit, et, tant qu’il a vécu, nul roi ne l’a ébranlé, nul n’a eu pouvoir sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 14, 'Nul ne l’a surpassé par la parole, et, même dans la mort, son corps a prophétisé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 15, 'Et, de son vivant, il a fait des prodiges, et à sa mort ses œuvres ont été merveilleuses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 16, 'Mais le peuple, après toutes ces choses, ne se repentit pas; il ne se retira point du péché, jusqu’à ce qu’il fût enlevé comme un butin de sa contrée, et dispersé sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 17, 'Et il n’est resté qu’un peuple peu nombreux, et un prince de la maison de David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 18, 'De ceux-ci, quelques-uns ont fait ce qui est agréable à Dieu; mais d’autres ont multiplié les péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 19, 'Ézéchias fortifia sa ville; et, dans ses murs, il amena de l’eau; avec le fer, il creusa les flancs escarpés de la montagne, et il bâtit des fontaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 20, 'De son temps s’éleva Sennachérib, qui envoya Rabsacès, et celui-ci vint, et il leva la main sur Sion, et il se glorifia en son orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 21, 'Alors les cœurs et les mains dans la ville furent ébranlés, et ils souffrirent comme les femmes dans les douleurs de l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 22, 'Et ils invoquèrent le Seigneur miséricordieux, en étendant les mains vers lui. Et, du haut des cieux, le Saint fut prompt à les exaucer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 23, 'Et il les délivra par la main d’Isaïe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 24, 'Il frappa le camp des Assyriens, et son ange les extermina;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 48, 25, 'Car Ézéchias avait fait ce qui est agréable au Seigneur, et il s’était affermi dans les voies de David son père, comme le lui avait prescrit Isaïe, le grand prophète, fidèle en ses visions. C’est lui qui, en ses jours, arrêta le soleil et prolongea la vie du roi. Par son grand esprit, il vit les choses de la fin, et il consola ceux qui pleuraient en Sion. Jusqu’à la consommation des siècles, Il dévoila l’avenir; il découvrit les choses cachées avant qu’elles vinssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 1, 'La mémoire de Josias est un mélange d’aromates préparé par celui qui compose les parfums.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 2, 'Dans toutes les bouches elle sera douce comme le miel, douce comme la musique dans un banquet où l’on boit du vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 3, 'Il eut le bonheur de convertir le peuple, et fit disparaître les abominations du péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 4, 'Il dirigea vers Dieu son âme; en des jours de déréglement, il affermit la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 5, 'Hormis David, Ézéchias et Josias, tous les rois ont commis le péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 6, 'Car les rois de Juda ont délaissé la loi du Seigneur; ils l’ont abandonnée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 7, 'Ils ont livré leur force à autrui, et leur gloire à une nation étrangère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 8, 'Ils ont causé l’incendie de la ville élue et sanctifiée, et la dévastation qui a fait de ses rues un désert à la voix de Jérémie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 9, 'Car ils l’avaient maltraité, et il avait été consacré prophète dans les entrailles de sa mère pour déraciner, ravager et détruire, aussi bien que pour bâtir et planter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 10, 'Ézéchiel eut la vision de gloire qui lui fit voir les chérubins sur un char.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 11, 'Et il avait en vue les ennemis en annonçant une pluie violente, tandis qu’il se montra bienveillant envers ceux qui suivaient la droite voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 12, 'Que les os des douze prophètes refleurissent dans leurs sépulcres! car ils ont consolé Jacob et affranchi ses enfants, en affermissant leur espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 13, 'Comment glorifierons-nous Zorobabel? Lui aussi est comme un cachet sur l’anneau que l’on porte à la main droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 14, 'Tel fut encore Jésus, fils de Josédec. Ceux-ci, de leur vivant, rebâtirent le temple; ils relevèrent le peuple saint, dévoué au Seigneur, pour le glorifier durant tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 15, 'Et Néhémias, on se souviendra de lui surtout; c’est lui qui a relevé nos remparts abattus, qui a replacé les portes et les verrous, qui a restauré nos demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 49, 16, 'Nul n’a été créé sur la terre semblable à Énoch, qui, lui aussi, a été enlevé au ciel. Nul homme n’a existé semblable à Joseph, chef de ses frères, soutien du peuple; Et ses os ont été abrités. Sem et Seth, parmi les hommes, ont été glorifiés, et plus que tout être vivant Adam, le premier créé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 1, 'Simon, fils d’Onias, le grand prêtre, de son vivant a repris les fondations de la maison du Seigneur, et en ses jours a raffermi le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 2, 'Il a doublé la profondeur des fondations, et tout alentour il a surélevé les murs du lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 3, 'De son temps, le réservoir des eaux a été diminué; son périmètre est comme celui de la mer d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 4, 'Il a eu soin de prévenir la chute du peuple; et, après avoir fortifié la ville pour qu’elle soutînt un siége,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 5, 'Combien il fut glorifié pour avoir bien conduit le peuple, et agrandi l’entrée du temple!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 6, 'Telle est l’étoile du matin au milieu des nuages; telle est la lune dans son plein;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 7, 'Tel le soleil lorsqu’il brille sur le temple du Très-Haut;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 8, 'Tel l’arc de gloire paraissant dans la nue; telle la rose aux jours du renouveau; tel le lis près d’une eau courante; tel en été un cèdre du Liban;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 9, 'Telle la flamme; tel l’encens au-dessus d’un brasier;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 10, 'Tel un vase d’or fait au marteau, orné de toutes sortes de pierres précieuses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 11, 'Tel l’olivier couvert de fruits; tel le cyprès s’élançant jusqu’aux cieux: tel il était, lorsqu’il eut pris sa robe de gloire, et qu’il se fut revêtu des ornements de sa dignité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 12, 'Et qu’il monta au saint autel, et qu’il glorifia ses vêtements sanctifiés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 13, 'Et qu’il reçut des mains des prêtres les membres des victimes, qu’il se tint devant le foyer de l’autel, et fut entouré d’une couronne de ses frères semblables aux rameaux d’un cèdre du Liban,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 14, 'Et qu’ils se placèrent autour de lui, comme des tiges de palmiers, et que tous les fils d’Aaron apparurent dans toute leur gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 15, 'Ils prirent alors dans leurs mains les oblations offertes au Seigneur devant toute l’assemblée d’Israël, et ils accomplirent le sacrifice à l’autel, et ils apprêtèrent les offrandes pour le Dieu très-haut et très-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 16, 'Alors il étendit la main vers le vase aux libations, et il répandit le sang de la grappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 17, 'Il versa sur la base de l’autel un parfum d’une odeur de suavité pour le Très-Haut, roi de toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 18, 'Alors les fils d’Aaron poussèrent un grand cri, au son de leurs trompettes d’airain frappées au marteau, et ils firent retentir une grande clameur, pour mémorial, devant le Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 19, 'Alors tout le peuple, d’un commun accord, s’empressa, et il tomba la face contre terre, pour adorer le Seigneur tout-puissant, le Dieu très-haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 20, 'Et les chantres le louèrent en leurs cantiques, et leur harmonie remplit le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 21, 'Et le peuple pria le Seigneur très haut, et il adressa une prière au Dieu miséricordieux, afin que sa gloire fût restaurée, et que le service du temple fût entièrement rétabli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 22, 'Alors le grand prêtre descendit de l’autel, et leva les mains sur toute l’assemblée des fils d’Israël pour qu’ils bénissent de leurs lèvres le Seigneur, et missent leur joie en son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 23, 'Et une seconde fois il adora, afin de recevoir la bénédiction du Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 24, 'Et maintenant, ô vous tous, bénissez Dieu, qui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 25, 'Qu’il nous donne la joie du cœur, qu’il fasse régner la paix en Israël, de nos jours et durant tous les siècles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 26, 'Qu’il nous affermisse dans la foi en sa miséricorde, et que, tous les jours, il veille à notre affranchissement!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 27, 'Mon âme s’est irritée contre deux nations, et la troisième n’est pas une nation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 28, 'Ce sont ceux qui demeurent sur la montagne de Samarie, les Philistins et le peuple insensé de Sichem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 50, 29, 'J’ai écrit, en ce livre, les instructions de la prudence et du savoir, moi, Jésus, fils de Sirach, de Jérusalem, qui ai répandu la sagesse dans mon cœur, comme un torrent de pluie. Heureux celui qu’elles convertiront; celui qui les aura déposées dans son âme sera sage; Car s’il agit selon ces paroles, elles le fortifieront, et la lumière du Seigneur conduira ses pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 1, 'Seigneur roi, je vous rendrai grâces; je vous louerai, ô Dieu mon Sauveur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 2, 'Je rendrai grâces à votre nom, parce que vous êtes mon abri et mon secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 3, 'Vous avez délivré mon corps de la perdition, des pièges de la langue calomnieuse, et des lèvres des ouvriers de mensonge; vous êtes venu à mon aide contre ceux qui se mettaient devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 4, 'Vous m’avez délivré, selon la plénitude de votre miséricorde et de votre nom, des bêtes rugissantes prêtes à me dévorer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 5, 'Et des mains de ceux qui cherchaient ma vie, et des tribulations nombreuses qui m’assiégeaient,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 6, 'Et du feu qui, tout alentour, me suffoquait, et que je n’avais point allumé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 7, 'Et des profondes entrailles de l’enfer, et de la langue impure, et de la parole menteuse, et de la langue inique d’un roi accusateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 8, 'Mon âme s’est approchée de la mort,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 9, 'Et ma vie est descendue tout près de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 10, 'J’ai été assiégé de toutes parts, et il n’y avait là personne qui me secourût; j’ai attendu l’aide des hommes, et il n’y en avait pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 11, 'Et je me suis souvenu de votre miséricorde, Seigneur, et de vos œuvres depuis que les temps ont commencé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 12, 'Car vous tirez du danger ceux qui vous attendent, et vous les sauvez des mains de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 13, 'Et j’ai élevé mon oraison au-dessus de la terre, et j’ai prié pour être délivré de la mort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 14, 'Et j’ai invoqué le Seigneur, Père de mon Seigneur, pour qu’il ne m’abandonnât point dans mes jours d’affliction, et au moment où les superbes ne me donnaient aucun secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 15, 'Je louerai sans cesse votre nom; je chanterai pour vous rendre grâces, parce que ma prière a été exaucée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 16, 'Vous m’avez sauvé de la perdition; vous m’avez réclamé au jour du malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 17, 'À cause de cela, je vous rendrai grâces, et je vous louerai, et je bénirai le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 18, 'Dès ma première jeunesse, avant de voyager, j’ai demandé publiquement la sagesse en mes prières;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 19, 'À cause d’elle, j’ai loué Dieu devant le temple; et jusqu’à la fin de ma vie je la chercherai comme une fleur de raisin qui commence à mûrir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 20, 'Mon cœur s’est réjoui en elle, mon pied a marché droit, et depuis mon enfance je l’ai suivie à la trace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 21, 'J’ai un peu incliné mon oreille, et je l’ai reçue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 22, 'Et j’ai trouvé beaucoup de sagesse en moi-même, et j’en ai tiré un grand profit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 23, 'Je rendrai gloire à celui qui m’a donné la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 24, 'J’ai été disposé à la pratiquer, et j’ai été rempli de zèle pour le bien, et je ne serai pas confondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 25, 'Mon âme a lutté à cause d’elle, et je me suis consumé dans le jeûne pour l’observer avec diligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 26, 'J’ai levé les mains au ciel, et j’ai pleuré sur les défaillances de mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 27, 'Et je l’ai remise dans la droite voie par le secours de la sagesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 28, 'Et d’abord mon cœur était enclin à ses fautes, et j’ai trouvé la sagesse en le purifiant; c’est pourquoi elle ne me délaissera jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 29, 'Et mes entrailles, en la cherchant, ont été troublées; et c’est pourquoi j’ai possédé en elle un grand bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 51, 30, 'Le Seigneur, pour récompense, m’a donné une langue, et je m’en servirai pour le louer. Approchez, vous qui n’êtes point instruits, venez auprès de moi, abritez-vous dans la maison de la science. Pourquoi tardez-vous? vos âmes ne sont-elles pas altérées? J’ai ouvert la bouche, et j’ai parlé; pour vous, achetez de moi la sagesse, sans me la payer (en argent). Placez votre cou sous le joug, et que vos âmes recueillent l’instruction; il ne faut pas aller loin pour la trouver. Voyez de vos yeux combien je me suis fatigué, et pourtant j’ai acquis pour moi-même un bon repos. Prenez votre part des instructions qui vous tiendront lieu de beaucoup d’argent, et en elles vous vous serez procuré des amas d’or. Que votre âme se réjouisse de la miséricorde du Seigneur, et ne rougissez point de le louer. Faites votre œuvre, achevez-la avant l’heure, et à son heure il vous donnera votre salaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'J’ai poussé des cris vers le Seigneur lorsque j’étais dans la tribulation, j’ai crié vers Dieu lorsque les pécheurs me persécutaient,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Le tumulte de la guerre s’est subitement fait entendre devant moi, le Seigneur m’a écouté parce que je suis plein de justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'J’ai pensé dans mon cœur que j’étais plein de justice, dans l’abondance et dans la multitude des fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Leurs richesses sont parvenues dans toute la terre, et leur gloire s’est répandue jusqu’aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Ils ont été élevés jusqu’aux astres; ils ont dit qu’ils ne pouvaient tomber.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Ils ont été dans l’abondance des biens et ils n’ont point apporté d’offrandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Leurs iniquités ont été commises dans les lieux cachés, et je ne les ai pas connues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Leurs iniquités sur les nations qui les avaient précédés ont profané le sanctuaire du Seigneur en le souillant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Le pécheur s’est enorgueilli de son pouvoir; il est venu avec des machines renverser des murailles, et tu ne l’en a pas empêché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Les nations étrangères sont montées à ton autel; elles marchaient avec orgueil, et leurs chaussures foulaient le sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Parce que les fils d’Israël ont souillé le sanctuaire du Seigneur; ils ont profané les dons de Dieu dans leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'C’est pourquoi il a dit: Rejetez loin de moi ces offrandes, qui n’ont point le parfum de la douceur; la beauté de la gloire du Seigneur n’y est point,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Ils ont été réduits au néant devant Dieu, leur fin a été déshonorée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Les fils et les filles (des pécheurs) seront conduits dans une dure captivité, leur tête sera marqué d’un stigmate comme un signe parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Dieu les as traités selon leur iniquité, car il les a abandonnés aux mains des forts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Car il a détourné sa face de la miséricorde qu’il avait eue sur eux; le jeune homme et le vieillard et leurs fils ont été frappés ensemble,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Parce que les impies ont agi d’accord pour ne pas entendre (la parole du Seigneur.)');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Et le ciel s’est irrité, et la terre les a eus en abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Parce que nul homme n’a fait ce qu’ils ont fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Et la terre connaîtra tes jugements; elle connaîtra toutes tes justices, ô mon Dieu; tu as fait des fils de Jérusalem un objet le division à cause des fornications qui se commettaient en son enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Tout homme qui marche dans l’iniquité, marche contre le soleil (c’est-à-dire, rommet des fautes qui seront mises au grand jour); ils se raillaient de ses iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 14, 'Ce qu’ils ont fait contre le soleil servira de modèle pour le traitement réservé à leurs iniquités, et les filles de Jérusalem seront souillées selon ton jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 15, 'Parce qu’elles se sont souillées elles-mêmes par l’approche du mélange (avec les étrangers).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 16, 'Je proclamerai ta justice, Seigneur, dans la droiture de mon cœur; ta justice céleste, Seigneur, dans tes jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 17, 'Car tu as traité les pécheurs selon leurs crimes et selon leurs péchés dont la griéveté est extrême.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 18, 'Tu as révélé leurs péchés, afin que ton jugement paraisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 19, 'Tu as effacé leur mémoire de dessus la terre, Seigneur, qui juge avec justice, et tu ne fais acception de personne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 20, 'Il a arraché son éclat de dessus le trône de majesté, parce que les nations ont raillé Jérusalem en la foulant aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 21, 'Il a pris un sac pour vêtement d’honneur; il a mis une corde autour de sa tête en guise de couronne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 22, 'Il a enlevé le diadème de gloire que Dieu lui avait imposé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 23, 'La beauté a été renversée à terre dans l’ignominie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 24, 'Et j’ai vu ces choses, et j’ai prié la face du Seigneur, et j’ai dit: Qu’il te suffise, Seigneur, d’appesantir la main sur Jérusalem dans la captivité des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 25, 'Parce qu’elles se railleront de Jérusalem, et que dans leur colère et leur fureur pleine d’emportement, elles ne l’épargneront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 26, 'Et elles la consumeront, à moins que toi, Seigneur, tu ne les gourmandes dans ta colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 27, 'Parce qu’elles ne l’ont pas fait par suite de zèle, mais dans la concupiscence de l’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 28, 'Pour qu’elles répandent leur colère sur nous dans la rapine, ne diffère pas, mon Dieu, de faire tomber la rétribution sur leurs têtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 29, 'Afin qu’elles aient l’orgueil du dragon tombé dans l’ignominie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 30, 'Et je n’ai pas attendu jusqu’à ce que Dieu m’ait montré son opprobre; il a été frappé dans les montagnes d’Egypte, et il disparaîtra de dessus la terre et la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 31, 'Son cadavre, devenu la proie de la pourriture, sera le jouet des flots et couvert d’ignominie; il n’y aura personne pour l’ensevelir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 32, 'Parce que le Seigneur l’a réduit au néant dans l’ignominie; il n’a pas pensé qu’il était homme, et il n’a pas songé à sa fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 33, 'Il a dit: Je serai le Seigneur de la terre et de la mer, et il n’a pas su que le Dieu grand était puissant dans sa force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 34, 'Il est le roi dans les cieux; il juge les rois et les principautés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 35, 'Il me rétablira dans la gloire et fera dormir les superbes dans la perdition éternelle et dans l’ignominie, parce qu’ils ne l’ont pas connu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 36, 'Et maintenant, grands de la terre, voyez le jugement du Seigneur; il est le Roi juste et grand qui juge sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 37, 'Bénissez Dieu, vous qui craignez le Seigneur et qui savez que la miséricorde du Seigneur s’étend sur ceux qui le craignent dans ses jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 38, 'Pour qu’il discerne entre le juste et le pécheur et qu’il rétribue les pécheurs pour l’éternité selon leurs œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 39, 'Et qu’il ait compassion du juste, prenant en considération l’humilité du pécheur, et qu’il traite le pécheur selon ce qu’il a fait au juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 40, 'Parce que le Seigneur est plein de bonté pour ceux qui l’invoquent dans la patience, pour qu’il agisse selon sa miséricorde à l’égard de ceux qui sont toujours en sa présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 41, 'Béni soit le Seigneur dans l’éternité en présence de ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Pourquoi dors-tu, mon âme, et pourquoi ne bénis-tu pas le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Chantez un hymne nouveau en l’honneur de Dieu digne de louange; chantez et veillez, adressez à Dieu un cantique du fond de votre cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Les justes se souviennent toujours du Seigneur; ils confessent la justice de ses jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Le juste repris par le Seigneur, ne tombera pas dans la négligence; sa pensée sera toujours devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Dans ses calamités le juste reconnaît la justice de Dieu, et dans ses malheurs il attend l’appui du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Il s’attend à ce que son salut, lui vienne du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'La vérité des justes est auprès de Dieu leur Sauveur; le péché n’habitera pas dans la maison du juste,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Le juste visite toujours sa maison afin d’ôter l’injustice qui la ferait tomber.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Il a expié son erreur dans le jeûne et dans l’humilité de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Et le Seigneur purifie tout homme saint et sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Le pécheur offense le Seigneur et il maudira sa vie, le jour de sa génération et les douleurs (qui ont accompagné sa naissance).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Il a ajouté péché sur péché en sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 13, 'Il est tombé parce que ses actions sont mauvaises, et la perdition du pécheur sera irréparable pour l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 14, 'Et le Seigneur, lorsqu’il visite les justes, ne se souviendra pas de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 15, 'Tel est la part du pécheur pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 16, 'Mais ceux qui craignent le Seigneur ressusciteront pour la vie éternelle, et leur vie sera dans la lumière du Seigneur, et elle ne cessera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Tu es assis dans le conseil, profane, mais ton cœur a longtemps été éloigné de Dieu, exaspérant par tes transgressions le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Tenant des discours inutiles, rude dans tes paroles, condamnant les pécheurs dans ton jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Et sa main est toujours sur le pécheur comme étant animée de zèle, tandis qu’il se rend coupable par ses péchés multipliés et ses incontinences.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Ses yeux s’arrêtent indistinctement sur toute femme, sa langue affirme des mensonges avec serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Il pêche dans le secret et dans les lieux cachés, comme s’il n’était pas vu; ses yeux s’adressent à toutes les femmes, son langage est empreint du signe de la malice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Il est prompt à entrer dans toute maison pour se réjouir, comme s’il n’était pas plein d’iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Détruis, Seigneur, les pécheurs qui simulent la sainteté; frappe leur chair de corruption et leur vie de détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Révèle les œuvres des hommes qui s’étudient à plaire aux hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Et les saints justifieront les jugements de leur Dieu, qui a ôté les pécheurs de devant la face des justes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Ainsi que le flatteur qui parle de la foi d’une manière trompeuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Et leurs yeux sont toujours fixés dans la maison de l’homme quí prospère; déruits leur sagesse, et montre ce que c’est que les paroles des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Leurs paroles ne sont que tromperies afin d’agir selon leur concupiscence coupable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Le Seigneur s’est enfin levé, il est venu détruire l’homme inique et l’a jeté dans la détresse et l’indigence à cause de sa concupiscence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Le pécheur trompe dans ses discours comme s’il n’y avait personne pour le voir et le juger.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 15, 'Il est rempli de son iniquité; son âme est insatiable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 16, 'Seigneur, que sa portion devant toi soit l’ignominie; que sa fin soit dans l’affliction et son entrée dans le malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 17, 'Que sa vie, Seigneur, circule dans les douleurs, la pauvreté et la détresse; que son sommeil soit dans les douleurs, et son réveil dans l’indigence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 18, 'Que le sommeil soit éloigné de lui pendant la nuit; qu’il tombe dans l’ignominie à chaque œuvre de ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 19, 'Qu’il rentre dans sa maison n’ayant rien dans ses mains, et que sa maison soit privée de tout ce qui pourrait rassasier son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 20, 'Que sa vieillesse s’écoule dans la solitude et sans rejetons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 21, 'Les chairs de ceux qui s’étudient à plaire aux hommes ont été déchirées par les bêtes féroces: les ossements des pécheurs restent exposés au soleil dans l’ignominie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 22, 'Que les corbeaux arrachent les yeux des hommes trompeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 23, 'Parce qu’ils ont détruit une multitude de maisons, réduisant leurs possesseurs à l’ignominie, et parce qu’ils ont dissipé leurs biens au gré de leur concupiscence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 24, 'Et ils ne se sont pas souvenus de Dieu, et ils n’ont pas craint Dieu dans tout ce qu’ils faisaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 25, 'Et ils ont exaspéré le Seigneur, et ils l’ont irrité jusqu’à ce qu’il les ôte de la terre, parce qu’ils font simulation de vivre selon la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 26, 'Heureux ceux qui, dans leur innocence, craignent le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 27, 'Le Seigneur les délivrera des hommes trompeurs et pécheurs: il nous délivrera de tous les scandales de l’homme injuste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 28, 'Détruis, Seigneur, ceux qui, dans leur orgueil, commettent toute injustice; car tu es un juge équitable et puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 29, 'Le Seigneur est notre Dieu dans la justice; que ta miséricorde, Seigneur, s’étende sur tous ceux qui t’aiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Seigneur Dieu, que ton nom soit béni avec transport, du milieu de ceux qui connaissent tes jugements équitables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Parce que tu es miséricordieux et bon, le refuge des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Lorsque je crierai vers toi, ne garde pas le silence à mon égard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Parce que l’homme ne pourra prendre les dépouilles d’un homme puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Et qui pourra s’emparer de toutes les choses que tu as faites, si ce n’est celui à qui tu les as données?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Car l’homme et ses actions sont pesées dans la balance, Seigneur, et il ne peut s’élever contre ton jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Lorsque nous serons dans l’affliction, nous t’invoquerons pour que tu nous assistes, et tu ne repousseras pas notre prière, parce que tu es notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'N’appesantis pas ta main sur nous, de peur que la nécessité ne nous fasse tomber dans le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Et, quoique tu ne nous assistes pas, nous ne nous éloignerons pas de toi, mais nous viendrons vers toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Si j’ai faim, je viendrai vers toi, Seigneur, et tu me donneras (des aliments).');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Tu nourris les oiseaux et les poissons, tu fais tomber la pluie dans le désert pour préparer la nourriture pour tout être vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Et, s’ils ont faim, ils élèvent vers toi leurs faces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Tu nourris, mon Dieu, les rois et les princes et les peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Et tu m’exauceras, car qui est bon et doux si ce n’est toi? Tu réjouis l’âme des humbles lorsque tu ouvres ta main dans la miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Ta bonté s’étend sur l’homme comme sur un ami, et tu le soutiens dans ses épreuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 16, 'Tu accordes tes dons avec bonté et largesse, et celui qui met son espoir en toi, Seigneur, ne s’enorgueillira pas de tes dons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 17, 'Ta miséricorde, Seigneur, s’étend sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 18, 'Heureux celui dont Dieu se souvient, et qui observe la modération dans la frugalité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 19, 'Si l’homme est dans l’abondance, il pèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 20, 'Une médiocrité suffisante dans la justice, et la bénédiction du Seigneur pour être rassasié dans la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 21, 'Ceux qui craignent le Seigneur se sont réjouis; la bonté s’étend sur Israel dans ton royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 22, 'Que la gloire du Seigneur soit bénie; car il est notre roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Heureux l’homme dont le cœur est préparé à invoquer le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Lorsqu’il se souviendra du nom du Seigneur, il sera sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Ses voies seront dirigées par le Seigneur, et les œuvres de ses mains seront aimées du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Il ne sera pas troublé par les visions fâcheuses de ses songes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Son âme ne s’effrayera point dans le passage des fleuves et dans les tempêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Il s’est levé de son sommeil, et il a béni le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Dans la constance de son cœur, il a béni le nom de son Dieu, et il a prié la face du Seigneur pour toute sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Et le Seigneur a écouté la prière de tout homme qui est dans la crainte de Dieu, et le Seigneur exaucera toutes les demandes de l’âme qui espère en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Que le Seigneur soit béni, lui qui fait miséricorde a ceux qui l’aiment dans la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Ne t’éloigne pas de nous, ô mon Dieu! de peur que ceux qui nous haïssent sans raison ne se jettent sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Tu les a repoussés, Seigneur, pour que leur pied ne foule pas l’héritage qui est consacré à ta sainteté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Châtie-nous selon ta volonté, et ne nous livre pas aux gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Ne nous envoie pas la mort avec l’ordre de nous frapper; épargne-nous, Seigneur, parce que tu es miséricordieux, et que ta colère ne nous consume pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Lorsque ton nom habitera au milieu de nous, nous obtiendrons miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Et les nations (infidèles) ne prévaudront pas contre nous, parce que tu es notre protecteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Et nous t’invoquerons, et tu nous exauceras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Parce que tu auras pitié de la race d’Israël dans l’éternité, et que tu ne nous repousseras pas, et que tu ne nous tiendras');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Tu nous diriges dans le temps où tu viens nous secourir, ayant pitié du peuple de Jacob, dans le jour que tu lui as annoncé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 1, 'Mon oreille a entendu la tribulation et la voix de la guerre; elle a entendu les cris de la trompette qui sonne le carnage et la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 2, 'La voix d’un peuple nombreux, comme les vents dont l’impétuosité est extrême, comme les tourbillons d’un grand feu qui parcourt le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 3, 'Et j’ai dit dans mon cœur: Est-ce que Dieu ne le jugera pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 4, 'J’ai entendu une voix en Jérusalem, la ville de la sanctification.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 5, 'Mes reins se sont brisés en entendant cette voix; mes genoux se sont rompus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 6, 'Mon cœur a tremblé; mes os se sont troublés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 7, 'Et j’ai dit: Ils dirigent leurs voies selon la justice, ceux qui contemplent les jugements de Dieu; j’ai contemplé ces jugements depuis la création du ciel et de la terre; j’ai justifié Dieu en ses jugements qui sont depuis tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 8, 'Dieu a révélé les péchés des méchants en présence du soleil; toute la terre a connu les justes jugements de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 9, 'Il révélera, dans sa colère, les iniquités des méchants cachées dans les ténèbres souterraines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 10, 'Le fils s’est mêlé avec sa mère, et le père avec sa fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 11, 'Plusieurs ont commis adultère avec la femme de leur prochain; ils ont fait des pactes sous foi de serment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 12, 'Ils ont pillé les choses consacrées à Dieu; ils n’y voient pas d’héritier pour les revendiquer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 13, 'Ils ont foulé aux pieds l’autel de Dieu, le souillant de toutes les immondices; et, Jans l’effusion du sang, ils ont souillé les hosties comme des choses profanes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 14, 'Ils n’ont pas laissé un péché qu’ils n’aient commis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 15, 'C’est pourquoi Dieu a mêlé en eux l’esprit d’erreur; il leur a fait couler jusqu’à l’ivresse le calice de son vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 16, 'Il les a conduits des extrémités de la terre, les frappant fortement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 17, 'Il a jugé la guerre à Jérusalem, et en son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 18, 'Les princes de la terre sont accourus au-devant de lui; ils lui ont dit avec joie: ta voie a été élargie, venez, entrez en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 19, 'Ils ont élargi les voies qui étaient difficiles et étroites; ils ont ouvert des portes à Jérusalem; ils ont couronné ses murs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 20, 'Il est arrivé comme un père dans la maison de ses fils; il a posé ses pieds avec une grande sécurité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 21, 'Il a occupé les murs de Jérusalem et ses tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 22, 'Parce que Dieu l’a conduit avec sécurité dans la déception.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 23, 'Il a perdu leurs princes dans le conseil; il a versé le sang des habitants de Jérusalem comme de l’eau immonde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 24, 'Il a emmené leurs fils et leurs filles parce qu’ils les avaient engendrés dans la profanation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 25, 'Ils ont fait selon leurs immondices comme leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 26, 'Ils ont souillé Jérusalem et les choses consacrées au nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 27, 'Dieu a été justifié dans ses jugements, dans les nations de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 28, 'Et les saints et Dieu seront comme des agneaux dans leur innocence, au milieu de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 29, 'Louange au Seigneur qui juge toute terre en sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 30, 'Et voici, maintenant, Seigneur, que tu nous a montré ton jugement dans ta justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 31, 'Leurs yeux ont vu tes jugements, ô mon Dieu! Nous avons justifié ton nom digue d’hommage dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 32, 'Parce que tu es le Dieu de justice qui juge Israël et qui le corrige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 33, 'Tourne, Seigneur, ta miséricorde vers nous et aie pitié de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 34, 'Réunis Israël par un effet de ta miséricorde et de la bonté, car il est dispersé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 35, 'Ta foi est en nous, mais nous avons endurci notre tête, et tu nous a corrigés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 36, 'Ne nous méprise pas, Seigneur; que les nations ennemies ne nous méprisent pas, et ne nous trouvent pas privés d’un Rédempteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 37, 'Tu es notre Dieu depuis le commencement, et nous avons espéré en toi, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 38, 'Et nous te louerons, car tes jugements sont pleins de bonté pour nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 39, 'Pour nous et pour nos fils sois toujours bienveillant, ô Seigneur notre Dieu! nous ne serons point troublés dans l’éternité. 40. Le Seigneur est louable dans ses jugements, dans la bouche des saints. Et toi, Israël, tu es béni du Seigneur, dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 1, 'Lorsqu’Israël fut conduit dans une terre étrangère, lorsqu’il s’était éloigné de Dieu son Rédempteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 2, 'Il fut privé de l’héritage que Dieu lui avait donné parmi toutes les nations; Israël fut dispersé selon la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 3, 'Afin que tu fusses, ô mon Dieu! justifié dans ta justice et selon nos iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 4, 'Parce que tu es un juge équitable sur tous les peuples de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 5, 'Car tout homme qui commet l’iniquité ne se dérobera pas à ta connaissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 6, 'Et la justice de tes saints est devant tes regards; Seigneur, l’homme ne se dérobera pas à ta connaissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 7, 'Seigneur, tu vois si notre cœur est disposé à faire ce qui est juste, et tu vois ce qu’il y a d’iniquités dans les œuvres de nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 8, 'Et tu visites dans ta justice les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 9, 'Celui qui fait ce qui est juste amasse un trésor devant le Seigneur, et celui qui commet l’iniquité est lui-même cause de la perte de son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 10, 'Car les jugements du Seigneur sont dans la justice selon l’homme et la maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 11, 'Pour qui Dieu montrera-t-il sa bonté, si ce n’est pour ceux qui invoquent le Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 12, 'Il a purifié l’âme dans les péchés, dans la confession, dans les accusations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 13, 'Parce que nos fautes sont pour nous et pour nos frères, en toutes choses, un sujet de confusion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 14, 'Et à qui le Seigneur remettra-t-il les péchés, si ce n’est aux pécheurs?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 15, 'Tu béniras les justes, &mon Dieu! et ne les puniras selon leurs péchés, et ta bonté s’étendra sur les pécheurs dans leur pénitence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 16, 'Tu es le Dieu d’Israël, et nous sommes à toi; tu ne sépareras pas ta miséricorde de nous, de peur que nos ennemis ne fondent sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 17, 'Car tu as choisi la race d’Abraham de préférence à toutes les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 18, 'Mets ton nom sur nous, Seigneur, et qu’il ne nous manque pas dans l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 19, 'Tu as fait un pacte avec nos pères et une promesse sur nous; nous espérons en toi dans la conversion de nos âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 20, 'Que la miséricorde du Seigneur soit sur la maison d’Israël dans tous les siècles et jusqu’à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 1, 'Heureux l’homme dont le Seigneur se souvient pour le reprendre et qui, sous les coups du châtiment, s’est détourné de la voie de la malice, afin qu’il soit purifié de son péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 2, 'Celui qui tend le aos aux coups, sera purifié; le Seigneur est bon pour ceux qui endurent le châtiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 3, 'Il rendra droits les chemins des justes, et il ne déviera pas dans ses châtiments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 4, 'La miséricorde du Seigneur s’étend sur ceux qui l’aiment dans la vérité; le Seigneur se souviendra de ses serviteurs dans sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 5, 'Le témoignage dans la loi du testament éternel est un témoignage du Seigneur, pour qu’il invite les soutiens des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 6, 'Notre Seigneur est juste et saint dans ses jugements dans l’éternité: Israël bénira avec allégresse le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 7, 'Et les saints le confesseront dans l’assemblée des peuples, et Dieu se souviendra des peuples dans l’allégresse d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 8, 'Parce que le Seigneur est miséricordieux et doux dans tous les siècles, et les Synagogues d’Israël glorifieront le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 9, 'Que le salut du Seigneur soit sur la maison d’Israël, dans une allégresse éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 1, 'Sonnez de la trompette en Sion, trompette de la signification des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 2, 'Prêchez dans Jérusalem la croix et celui qui annonce de bonnes choses, parce que Dieu s’est souvenu des enfants d’Israël dans leurs épreuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 3, 'Tiens-toi élevée, Jérusalem et vois tes fils dans l’Orient et dans l’Occident réunis par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 4, 'Ils viendront poussés par l’aquilon; la joie de leur Dieu les appellera du côté du midi; Dieu les rassemblera des pays les plus éloignés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 5, 'Il abaissera pour eux au niveau des plaines les montagnes les plus élevées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 6, 'Les collines fuiront à leur approche; les bois les couvriront pendant leur voyage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 7, 'Tout bois odoriférant sera en abondance devant eux, o mon Dieu! afin qu’Israël s’achemine dans les imitations de la gloire de son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 8, 'Revêts-toi, Jérusalem, des vêtements de ta gloire; prépare la robe de ta sanctification, parce que Dieu a parlé avec bonté à Israël, lui faisant des promesses pour l’éternité et au delà.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 9, 'Le Seigneur fera ce qu’il a annoncé pour Israël et Jérusalem; il élèvera Jérusalem pour l’éternité et au delà.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 1, 'Seigneur, délivre-nous donc de l’homme prévaricateur et injuste, de la langue du pécheur et du perfide, de celle qui profère des mensonges et des fourberies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 2, 'Les paroles de la langue de l’homme inique qui fait les œuvres de l’injustice, sont comme le feu dans l’aire, lorsqu’il incendie la paille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 3, 'Il remplira tout ce qui l’entoure des maux causés par sa langue perfide; détruis, Seigneur, les arbres du pécheur rempli de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 4, 'Confonds les maisons iniques et ferme les livres du médisant; éloigne, Seigneur, ee tison ardent, éloigne-le des innocents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 5, 'Que la langue qui médit périsse et qu’elle ne fasse aucun mal aux saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 6, 'Que le Seigneur protège l’âme qui garde le silence et qui déteste l’injustice, et que le Seigneur dirige dans la maison de la paix l’homme qui fait le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 7, 'Que le salut du Seigneur soit à toujours sur Israël, son fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 8, 'Et que les pécheurs périssent de devant la face du Seigneur, et que les saints du Seigneur héritent de ce qu’il leur a promis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 1, 'La droite du Seigneur nous a soutenus, la droite du Seigneur nous a épargnés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 2, 'Le bras de Dieu nous a sauvés de la famine et de la mort des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 3, 'Des bêtes féroces accouraient sur les voies qu’ils suivaient, elles déchiraient leurs chairs et broyaient leurs os sous leurs dents, et Dieu nous a délivrés de tous ces maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 4, 'L’impie a été troublé à cause ses péchés; il a craint d’être saisi chargé de toutes ses fautes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 5, 'La punition du pécheur est terrible, mais le juste sera exempt de tous ces maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 6, 'Car la correction du juste qui a erré dans l’ignorance n’est pas semblable à la punition infligée au pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 7, 'Le juste sera châtié en saint, afin que le pécheur n’insulte pas un juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 8, 'Car le Seigneur admonestera le juste comme le fils de sa tendresse, et il le punira comme on punit un premier-né.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 9, 'Car le Seigneur épargnera ses saints, et effacera leurs fautes en les corrigeant, car la vie des justes dure à toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 10, 'Les pécheurs s’élèveront pour leur perte, et leur mémoire ne se retrouvera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 1, 'Dieu est fidèle à ceux qui l’aiment dans la vérité et qui supportent sa correction, à ceux qui marchent dans la voie de ses préceptes, comme il nous l’a ordonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 2, 'Les saints du Seigneur vivront en lui dans l’éternité; le paradis du Seigneur est le germe de la vie des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 3, 'Leur plantation est enracinée dans tous les siècles; ils ne seront jamais arrachés parce qu’Israël est la portion et l’hérédité de Dien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 4, 'Il n’en est pas ainsi des pécheurs et des injustes qui ont aimé le jour dans la participation de leur péché et dans la pourriture de leur concupiscence');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 5, 'Et ils ne se sont pas souciés de Dieu, mais les vices des hommes sont toujours notés en sa présence, et il connaît les pensées de leur cœur avant qu’elles ne naissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 6, 'Aussi auront-ils pour héritage l’enfer, les ténèbres et la perdition, et ils ne se rencontreront pas dans le jour de la miséricorde des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 7, 'Mais les saints du Seigneur hériteront de la vie dans l’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 1, 'Dans mon affliction, j’ai invoqué le nom du Seigneur; j’ai mis mon espoir dans l’assistance du Dieu de Jacob, et j’ai été sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 2, 'Car tu es, Seigneur, l’espoir et le refuge des pauvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 3, 'Quelle puissance a l’homme, Seigneur, à moins qu’il ne te confesse dans la vérité? 4. Et que peut-il s’il ne confesse ton âme? 5. Qu’il chante tes hommages dans la joie de son cœur, qu’il t’offre les prémices de ses lèvres inspirées par un cœur saint et juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 6, 'Agissant ainsi, il sera préservé du mal dans l’éternité; la flamme du feu et la colère des injustes ne l’atteindra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 7, 'Car il est venu de devant la face du Seigneur, et il a surpris les pécheurs afin de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 8, 'Car le signe du Seigneur est sur les justes, et leur sert de salut; la famine, le glaive et la mort s’éloignent d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 9, 'Les pécheurs fuiront loin des saints comme si la famine les poursuivait, et le jugement de Dieu surprendra, comme un chasseur habile, ceux qui commettent l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 10, 'Car le signe de la perdition est sur leur front.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 11, 'Et l’héritage des pécheurs est la perdition, et les ténèbres et leurs iniquités les suivront jusqu’aux enfers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 12, 'Leur héritage ne se trouvera pas dans leurs fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 13, 'Les iniquités désoleront les maisons des pécheurs, et ils périront pour l’éternité dans le jour du jugement de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 14, 'Lorsque Dieu invitera la terre dans son jugement afin de traiter dans le temps éternel les pécheurs selon leurs mérites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 15, 'Mais ceux qui craignent le Seigneur obtiendront miséricorde, et ils vivront dans la miséricorde de leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 1, 'Lorsque mon âme dormait, Seigneur, j’ai été au moment de m’écarter de Dieu dans l’accablement du sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 2, 'Lorsque j’étais loin de Dieu, mon âme est presque arrivée à la mort à cause des portes de l’enfer qui attendent le pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 3, 'Mon âme se serait écartée du Seigneur Dieu d’Israël, si le Seigneur ne m’avait prévenu par sa miséricorde qui est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 4, 'Le Sauveur m’a frappé comme d’un éperon; mon défenseur m’a préservé en tout temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 5, 'Je te célébrerai, mon Dieu, car tu as veillé sur mon salut, et tu ne me confondras pas avec les pécheurs dans leur perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 6, 'N’éloigne pas ta miséricorde de moi, Seigneur; n’éloigne pas ta miséricorde de mon cœur jusqu’à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 7, 'Préserve-moi, mon Dieu, du péché et de toute femme méchante qui est un sujet de chute pour l’insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 8, 'Que la beauté de la femme perverse ne me séduise pas et que je sois préservé du péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 9, 'Dirige les œuvres de mes mains vers ta demeure, et guide mes pas dans la mémoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 10, 'Protége ma langue et mes lèvres dans les paroles de la vérité; éloigne de moi la colère et la fureur insensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 11, 'Eloigne de moi le murmure et l’abattement dans la tribulation; si j’ai péché, corrige-moi pour que je revienne à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 12, 'Affermis mon âme dans la joie de te servir; si tu fortifies mon âme, Seigneur, ce don me suffit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 13, 'Qui soutiendra tes châtiments, si ta miséricorde ne les adoucit?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 14, 'Lorsque l’âme était chatiée dans les mains de sa pourriture, ton bon plaisir vint soutenir sa chair dans la tribulation de la détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 15, 'Le juste sera soutenu dans ses épreuves, il obtiendra la miséricorde du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 1, 'Seigneur, tu es notre roi pour l’éternité, et c’est en toi, ô mon Dieu, que notre âme sera glorifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 2, 'Quelle est la durée de la vie de l’homme sar la terre auprès du temps du Seigneur? c’est en lui que nous devons mettre notre espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 3, 'Nous espérons en Dieu notre sauveur, car la puissance de notre Dieu s’étend dans tous les siècles, accompagnée de sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 4, 'Et le règne de notre Dieu s’étend dans l’éternité, au-dessus des nations qu’il juge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 5, 'Seigneur, tu as choisi David pour roi d’Israël, et tu lui as fait un serment en faveur de sa race pour tous les siècles; tu as promis que son royaume ne déclinerait pas en la présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 6, 'Les pécheurs se sont élevés contre nous à cause de nos péchés; ils se sont jetés sur nous; ceux qui ne te connaissent pas nous ont expulsés; ils nous ont enlevé avec violence ce que nous possédions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 7, 'Ils n’ont pas glorifié ton nom digne d’honneur; dans leur orgueil ils ont mis un diadème sur leur tête comme symbole de leur puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 8, 'Ils ont renversé le trône de David dans l’exaltation de leur orgueil; tu les renverseras, Seigneur, et tu ôteras leur race de dessus la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 9, 'Lorsque tu exciteras contre eux l’homme qui est de la race des guerriers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 10, 'Tu les traiteras selon leurs péchés, Seigneur; qu’ils trouvent selon leurs œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 11, 'Dieu aura pitié d’eux selon leurs œuvres; il a scruté leur race et il ne les a pas délivrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 12, 'Le Seigneur est fidèle dans tous les jugements qu’il rend sur la terre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 13, 'Le vent a désolé notre pays; ils ont renversé le jeune homme et le vieillard et leurs enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 14, 'Le Seigneur les a frappés dans sa colère jusqu’à la fin du jour; il n’a point épar gné les princes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 15, 'Nos ennemis se livrent à l’orgueil et leur cœur est bien loin de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 16, 'Et de tout ce qu’il a fait à Jérusalem; les nations ont dans leurs cités rendu hommages à leurs dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 17, 'Les enfants de l’alliance ont été conduits au milieu des nations; il n’y avait plus personne qui agit, au milieu de Jérusalem, selon la miséricorde et la vérité');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 18, 'Ceux qui aiment les assemblées des saints ont fui loin d’eux comme des passereaux s’envolent de leur nid.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 19, 'Ils ont été frappés dans les déserts pour que leur âme fût préservée du mal, et à peine un seul a-t-il échappé en conservant la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 20, 'Ils ont été dispersés sur toute la terre par les hommes iniques, parce que le ciel a cessé de répandre la pluie sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 21, 'Les fontaines éternelles ont été fermées parce qu’il n’y a parmi eux personne qui agisse selon la justice; depuis leur prince jusqu’au dernier du peuple, il n’y a parmi eux un seul qui ne soit pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 22, 'Le roi transgresse la loi, et le peuple est dans le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 23, 'Vois, Seigneur, et rends à ton peuple son roi, le fils de David; tu enverras ton fils pour régner en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 24, 'Ceins-le de force afin qu’il renverse les princes injustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 25, 'Purifie Jérusalem des nations qui marchent dans la perdition, et traite-les selon ta justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 26, 'Repousse les pécheurs de l’héritage, brise l’orgueil des pécheurs, détruis tout leur pouvoir comme une baguette de fer brise des vases de terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 27, 'Que la parole de la bouche de ton envoyé subjugue les nations iniques; que les nations fuient devant son visage et reprends les pécheurs dans la parole de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 28, 'Et il rassemblera le peuple saint qu’il conduira selon la justice, et il rendra la justice aux tribus du peuple sanctifié par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 29, 'Il ne permettra pas à l’injustice d’habiter au milieu d’eux, et tout homme expert en malice n’habitera pas avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 30, 'Il saura qu’ils sont tous les fils de son Dieu, et il les distribuera dans leurs tribus sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 31, 'Et l’étranger n’habitera plus avec eux; il jugera les nations et les peuples dans la sagesse de sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 32, 'Et il aura sous son joug les peuples des nations pour le servir, et il sera glorifié; sa renommée s’étendra sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 33, 'Et il purifiera Jérusalem, la sanctifiant et la rétablissant comme elle était dès le commencement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 34, 'Afin que les nations viennent des extrémités de la terre parmi sa gloire, en apportant des présents;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 35, 'Pour voir la gloire du Seigneur; il est le roi juste que Dieu a instruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 36, 'Et, de son temps, il n’y a pas d’injustice au milieu des hommes, parce que tous sont muets, et que leur roi est le Christ, le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 37, 'Il ne met pas son espoir dans le cheval, ni dans l’art, ni dans les machines de guerre; il n’a pas ramassé de l’or et de l’argent pour faire la guerre, et il n’a pas confiance dans les événements de la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 38, 'Le Seigneur est son roi; son espoir est en Dieu; il aura pitié de toutes les nations qui sont en sa présence dans la frayeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 39, 'Il fera trembler la terre jusque dans l’éternité par la parole de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 40, 'Il bénira le peuple de Dieu dans la sagesse avec allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 41, 'Et lui-même sera pur de péchés pour gouverner un grand peuple, pour réprimander les princes; il détruira les pécheurs par la puissance de sa parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 42, 'Et il conservera toute sa puissance devant Dieu, parce que Dieu lui a donné de la force dans l’Esprit saint, et lui a donné la sagesse et la prudence avec la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 43, 'La bénédiction du Seigneur sera sur lui et lui conservera sa force, et il ne sera point affaibli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 44, 'Son espérance est dans le Seigneur, et qui a de la puissance contre lui? Il est fort en ses œuvres et puissant dans la crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 45, 'Il fera paître le troupeau du Seigneur dans la foi et la justice; il ne permettra pas que la dissolution se répande dans ses pâturages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 46, 'Il les conduira tous dans la sainteté; il n’y aura point parmi eux l’orgueil d’exercer de la domination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 47, 'Il sera l’éclat du roi d’Israël que Dieu connaît, et qu’il suscitera dans la maison d’Israël pour la rétablir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 48, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 49, 'Ses discours sont comme les paroles des saints au milieu des peuples sanctifiés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 50, 'Heureux ceux qui naissent dans ces jours pour voir le bonheur d’Israël dans la réunion des tribus que Dieu accomplira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 51, 'Étends Seigneur, la miséricorde sur Israël. Il nous a délivrés de l’impureté de ses ennemis profanes; le Seigneur est notre roi dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 1, 'Seigneur, ta miséricorde s’étend sur l’œuvre de tes mains pour l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 2, 'Ta bonté a fait de riches présents aux fils d’Israël; tes yeux se sont arrêtés sur eux et tu ne les abandonnes pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 3, 'Que tes oreilles entendent la demande du pauvre qui met son espoir en toi; tes jugements s’étendent sur toute la terre avec ta miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 4, 'Et ton affection s’étend sur la race d’Abraham, sur le fils d’Israël; ton attachement pour eux est comme celui d’un homme pour un fils unique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 5, 'Détourne l’âme obéissante des péchés qu’elle commettrait dans l’ignorance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 6, 'Purifie, Seigneur, Israël dans le jour de ta miséricorde; donne-lui ta bénédiction, dans le jour que tu auras choisi pour le règne du Christ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 7, 'Heureux ceux qui sont nés dans les jours qui leur permettront de voir le bien que fera le Seigneur à la génération future.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 8, 'Le Christ gouvernera Israël dans la crainte de Dieu, dans la sagesse de l’esprit, dans la justice et la force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 9, 'Il dirigera les hommes dans la voie de la justice, leur inspirant à tous la crainte de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 10, 'Une génération bonne dans la crainte de Dieu, dans les jours de la miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 11, 'Notre Dieu est grand et glorieux; il habite dans les régions les plus élevées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 12, 'Il a réglé dans sa puissance les luminaires dans le cours des heures et ils ne s’écarteront pas de la voie qu’il leur a tracée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 13, 'Leur vie s’effectue chaque jour dans la crainte de Dieu, depuis le jour où Dieu les a créés jusque dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 14, 'Et ils ne s’en sont pas écartés depuis le jour de leur création, dans les générations anciennes; ils n’ont pas dévié de leur voie, à moins que Dieu ne leur ait commandé d’obéir aux ordres de ses serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Paroles du Seigneur qui vinrent à Osée, fils de Béeri, durant les jours d’Ozias, et de Joathan, et d’Achaz, et d’Ézéchias, rois de Juda, et durant les jours de Jéroboam, fils de Joas, roi d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Commencement des paroles du Seigneur à Osée. Et le Seigneur dit à Osée: Va et prends pour toi une femme de prostitution; aie des enfants de la prostitution, parce que la terre se prostitue, et se prostituera en se retirant du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Et il alla, et il prit Gomer, fille de Debélaïm, et elle conçut, et elle lui enfanta un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Et le Seigneur lui dit: Donne-lui le nom de Jezraël, parce que, encore un peu de temps, et je vengerai le sang de Jezraël sur la maison de Juda, et je ferai cesser la royauté de la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Et il arrivera, en ce jour-là, que je briserai l’arc d’Israël dans la vallée de Jezraël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Et elle conçut encore, et elle enfanta une fille. Et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Envers les fils de Juda je serai miséricordieux, et je les sauverai par le Seigneur leur Dieu; mais je ne les sauverai pas par l’arc, ni par le glaive, ni par la guerre, ni par les chevaux, ni par les cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Et elle sevra cette fille Sans-Pitié; et elle conçut encore, et elle enfanta un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Le Seigneur dit à Osée: Appelle-le Non-Mon-Peuple; parce que vous n’êtes plus mon peuple, et je ne suis plus votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Et le nombre des fils d’Israël a été comme le sable de la mer, que l’on ne peut ni mesurer ni compter; et ceci arrivera dans le lieu même où il leur a été dit: Vous n’êtes plus mon peuple; et ils seront appelés fils du Dieu vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Et les fils de Juda se réuniront, et en même temps ceux d’Israël, et ils institueront pour eux une seule principauté, et ils se répandront sur la terre, parce que le jour de Jezraël est grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Dites à votre frère, Mon - Peuple, et à votre sœur Pitié:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Plaidez contre votre mère; car elle n’est point ma femme, et je ne suis pas son mari. Et j’ôterai de devant ma face sa prostitution, et son adultère du milieu de ses mamelles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Afin de la mettre nue, et de la remettre comme elle était le jour de sa naissance; et je ferai d’elle un désert, et je la traiterai comme une terre aride; et je la tuerai par la soif;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Et je n’aurai point pitié de ses enfants; car ce sont des enfants de prostitution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Leur mère s’est prostituée; celle qui les a portés les a couverts de honte; elle a dit: Je m’en irai après mes amants qui me donnent mon pain, et mon eau, et mes vêtements, et mon linge, et mon huile, et tout ce qui m’est nécessaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'C’est pourquoi je ferme sa voie avec des épines, et je bâtirai sur ses routes; elle ne retrouvera plus son sentier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Elle poursuivra ses amants, et ne les atteindra pas; elle les cherchera, et ne les trouvera pas. Et elle dira: Je vais partir, je vais retourner auprès de mon premier mari; car, pour moi, il faisait meilleur alors que maintenant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Et elle n’a point connu que je lui avais donné du pain, du vin et de l’huile, et que je l’avais comblée d’argent, et elle a fait à Baal des idoles d’argent et d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'À cause de cela, je m’en retournerai, je prendrai mon blé lors de la moisson, et mon vin lors de la vendange; et je reprendrai mes vêtements et mon linge, pour ne plus couvrir sa nudité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Et désormais je révélerai à ses amants son impureté, et nul ne la délivrera de mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Et je supprimerai toutes ses joies, toutes ses fêtes, toutes ses nouvelles lunes, ses sabbats et toutes ses solennités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Et je détruirai sa vigne et ses figuiers, parce qu’elle a dit: Ce sont les salaires que m’ont donnés mes amants. Et moi, j’en ferai un témoignage; les bêtes des champs viendront y paître, et les oiseaux du ciel, et les reptiles de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Je lui ferai expier les jours où elle a sacrifié à Baal, et où elle a mis ses pendants d’oreilles et ses colliers pour s’en aller après son amant. Et elle n’a oublié, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, 'C’est pourquoi je l’égarerai et je l’enverrai dans le désert, et je parlerai à son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 15, 'Et de là je lui rendrai ses possessions et la vallée d’Achor, pour lui ouvrir l’intelligence. Et là elle s’humiliera autant de jours qu’a duré sa jeunesse, et autant de jours qu’elle a mis à revenir de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 16, 'Et ceci arrivera en ce jour-là, dit le Seigneur; elle m’appellera Mon époux, et elle ne m’appellera plus Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 17, 'Et j’ôterai de sa bouche les noms de Baal, et l’on ne s’en souviendra plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 18, 'Et en ce jour-là j’établirai une alliance entre eux et les bêtes sauvages, et les oiseaux du ciel, et les reptiles de la terre; et je briserai sur la terre l’arc, le glaive et les armes de guerre, et je t’y installerai avec l’espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 19, 'Et je te prendrai pour épouse dans tous les siècles, et je te prendrai pour épouse en mon équité, en mes jugements, en ma pitié, en ma miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 20, 'Et je te prendrai pour épouse avec confiance, et tu reconnaîtras le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 21, 'Et il arrivera en ce jour-là, dit le Seigneur, que j’exaucerai le ciel, et le ciel exaucera la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 22, 'Et la terre exaucera le blé, et le vin, et l’huile, et toutes ces choses exauceront Jezraël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 23, 'Et je la sèmerai pour moi sur la terre, et j’aimerai celle que je n’aimais pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 24, 'Et je dirai à Non-Mon-Peuple: Tu es mon peuple; et il dira: Vous êtes le Seigneur mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Et le Seigneur m’a dit: Pars encore, aime une femme qui aime le mal, une femme adultère, comme Dieu aime les fils d’Israël, tandis qu’ils regardent les dieux étrangers, et se régalent de pâtes aux raisins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Et moi, j’ai loué une telle femme quinze sicles d’argent et un gomor d’orge, et un nebel d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Et je lui ai dit: Tu te tiendras tranquille avec moi bien des jours; garde-toi de te prostituer; ne sois pas à un autre homme, et je te serai attaché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Car les fils d’Israël seront bien des jours sans roi, sans chef, sans sacrifices, sans autels, sans sacerdoce, sans manifestation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Et, après cela, les fils d’Israël se convertiront, et ils chercheront le Seigneur leur Dieu, et David leur roi, et ils seront pleins d’admiration, sur les derniers jours, pour le Seigneur et ses bienfaits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 1, 'Écoutez la parole du Seigneur, ô fils d’Israël; car le Seigneur va entrer en jugement avec les habitants de la terre, parce qu’il n’existe plus sur la terre ni vérité, ni miséricorde, ni connaissance de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 2, 'Les malédictions, le mensonge, le meurtre, le vol, l’adultère, sont répandus sur la terre, et le sang se mêle au sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 3, 'C’est pourquoi la terre sera en deuil, et elle sera affaiblie avec tout ce qui l’habite, avec les bêtes des champs, les reptiles et les oiseaux du ciel; et même les poissons de la mer dépériront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 4, 'Que nul n’ait de contestation, que nul ne reprenne autrui; mon peuple est comme un peuple révolté contre ses prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 5, 'Et il perdra sa force de jour en jour, et, avec toi, le prophète aussi perdra sa force; j’ai comparé ta mère à la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 6, 'Mon peuple est comme s’il ne savait rien; car tu as repoussé la science, et moi je te repousserai à mon tour, pour que tu n’aies plus mon sacerdoce; tu as oublié la loi de Dieu, et moi j’oublierai tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 7, 'Plus ils se sont multipliés, plus ils ont péché contre moi; je changerai leur gloire en opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 8, 'Ils se nourriront des péchés de mon peuple, et ils mettront leurs âmes en leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 9, 'Et tel sera le peuple, tel sera le prêtre; et sur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 10, 'Ils mangeront, et ne seront pas rassasiés; ils se sont prostitués, et ne prospèreront point, parce qu’ils ont cessé de prendre garde au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 11, 'Le cœur de mon peuple s’est complu dans la prostitution, le vin et l’ivresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 12, 'Ils ont consulté des présages, et avec des baguettes on leur a fait des prédictions; ils ont été égarés en un esprit de débauche, et ils se sont prostitués en s’éloignant de leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 13, 'Ils ont sacrifié sur les hauts lieux; ils ont brûlé de l’encens sur des collines, sous un chêne ou sous un peuplier, ou sous tout arbre touffu, parce qu’ils se plaisent à l’ombre. A cause de cela, vos filles se prostitueront, et vos femmes seront adultères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 14, 'Et je ne visiterai plus vos filles quand elles se prostitueront, ni vos femmes quand elles seront adultères, parce que vous-mêmes vous vous êtes souillés avec des prostituées, et que vous avez sacrifié avec des initiés, et que le peuple (un peuple intelligent!) s’est laissé prendre aux filets d’une prostituée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 15, 'Or sache-le bien, toi, Israël, et toi, Juda: n’allez point en Galgala, ne montez point à la maison de On, et ne jurez point par le Dieu vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 16, 'Car Israël, comme une génisse aiguillonnée par un taon, a eu des transports frénétiques, et maintenant le Seigneur le fera paître comme un agneau dans un lieu spacieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 17, 'Éphraïm, qui participe aux idoles, a mis devant lui des pierres d’achoppement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 18, 'Il a provoqué les Chananéens; ils se sont prostitués et prostitués, et ils ont aimé l’ignominie et ses rugissements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 19, 'Seigneur, vous êtes un tourbillon de vent emporté sur ses ailes; pour eux, ils seront confondus à cause même de leurs autels.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 1, 'O prêtres, écoutez ce que je vais dire, recueillez-le; maison d’Israël, maison du roi, prêtez-moi une oreille attentive: le jugement est près de vous; car vous êtes comme un filet vers l’affût, comme un lacs tendu sur le Thabor,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 2, 'Et que des chasseurs ont attaché; et moi, je suis celui qui vous instruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 3, 'Je connais Éphraïm, et Israël ne m’a point échappé; parce que maintenant Éphraïm s’est prostitué, et qu’Israël s’est couvert de souillures,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 4, 'Ils n’ont point pensé, en leur conseil, à se convertir à Dieu; car l’esprit de prostitution est en eux, et ils ne connaissent point le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 5, 'Et l’orgueil d’Israël sera abaissé en sa face, et Israël et Éphraïm trébucheront en leurs iniquités, et Juda aussi tombera avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 6, 'Ils s’en iront, avec leurs bœufs et leurs brebis, pour chercher le Seigneur, et ils ne le trouveront pas; car il s’est éloigné d’eux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 7, 'Parce qu’ils l’ont abandonné et qu’il leur est né des fils d’étrangères, maintenant la nielle les dévorera eux et leurs enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 8, 'Trompettes, sonnez sur les collines, retentissez');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 9, 'Éphraïm a été effacé au jour du châtiment. J’ai montré aux tribus d’Israël des choses dignes de foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 10, 'Les chefs de Juda sont devenus comme ceux qui déplacent les bornes des champs, je répandrai sur eux ma fureur comme un torrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 11, 'Ephraïm a prévalu sur son adversaire; il a foulé aux pieds le jugement, parce qu’il avait commencé à adorer des choses vaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 12, 'Et moi je suis comme une épouvante pour Éphraïm, comme un aiguillon pour la maison de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 13, 'Et Éphraïm a subi son infirmité, et Juda sa douleur. Et Éphraïm est allé aux Assyriens, et il a envoyé ses anciens chez le roi Jarim. Mais celui-ci n’a pu vous guérir, et vos douleurs ne se sont point calmées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 14, 'Parce que je suis comme une panthère pour Éphraïm, et comme un lion pour Juda; et je m’élancerai, et je saisirai et ravirai ma proie, et nul ne pourra me l’arracher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 15, 'Et je partirai, et je retournerai en ma demeure, jusqu’à ce qu’ils soient exténués et qu’ils recherchent ma présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 1, 'Dans leur tribulation, ils se lèveront de grand matin, et viendront à moi, en disant: Allons et retournons au Seigneur notre Dieu; car c’est lui qui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 2, 'Nous a pris, et il nous guérira; il nous a frappés, et il pansera nos blessures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 3, 'En deux jours il nous rendra la santé; le troisième jour, nous nous lèverons et nous vivrons devant lui, et nous le connaîtrons; notre désir sera de connaître le Seigneur; nous le trouverons prêt dès l’aurore; il viendra à nous, comme à la terre les pluies du matin et du soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 4, 'Que te ferai-je, Éphraïm? Que te ferai-je, Juda? Votre miséricorde est comme le brouillard du matin, comme la rosée du soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 5, 'À cause de cela j’ai moissonné vos prophètes; je les ai tués d’un mot de ma bouche, et mon jugement apparaîtra comme la lumière,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 6, 'Parce que je préfère la miséricorde aux sacrifices, et la connaissance de Dieu aux holocaustes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 7, 'Mais ils sont comme l’homme qui viole l’alliance; c’est là que m’a méprisé');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 8, 'Galaad, ville qui fabrique des choses vaines, ville qui trouble l’eau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 9, 'Et sa force est celle d’un pirate. Les prêtres ont caché des embûches sur la voie; ils ont tué Sichem; ils ont commis des crimes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 10, 'En la maison d’Israël; là j’ai vu des choses horribles: la prostitution d’Ephraïm, la souillure d’Israël');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 11, 'Et de Juda. Commence à vendanger pour toi-même, tandis que je ramènerai mon peuple de la captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 1, 'Pendant que je guérissais Israël, l’iniquité d’Éphraïm et la méchanceté de Samarie ont été révélées; car ils étaient ouvriers de mensonges. Et le larron entrera chez Éphraïm, et le brigand le pillera dans ses chemins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 2, 'Comme des chanteurs qui s’accordent entre eux. Je me suis souvenu de toute leur malice; et maintenant leurs pensées les ont enveloppés, et elles sont venues devant ma face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 3, 'Ils ont réjoui les rois par leur perversité, et les princes par leurs mensonges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 4, 'Ils sont tous adultères; ils sont comme un feu brûlant pour la cuisson, tout échauffé par la flamme, lorsque l’on a pétri la pâte, jusqu’à ce qu’elle ait fermenté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 5, 'Du temps de vos rois, vos princes commençaient la journée par s’enflammer avec le vin; le roi lui-même étendait la main avec des hommes de pestilence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 6, 'Parce que leurs cœurs étaient brûlants comme un four pendant qu’ils s’exaltaient, Éphraïm se rassasiait de sommeil toute la nuit; et quand venait l’aurore il brûlait encore comme la flamme du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 7, 'Ils étaient tous échauffés comme un four, et ils dévorèrent leurs juges; tous leurs rois tombèrent, et nul ne fut parmi eux pour m’invoquer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 8, 'Ephraïm se mêla à leurs peuples; Éphraïm devint comme un gâteau cuit sous la cendre et qu’on n’a pas retourné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 9, 'Les étrangers dévorèrent sa force, et il n’en sut rien; ses cheveux blanchirent, et il ne le sut pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 10, 'Et l’orgueil d’Israël sera humilié en sa face; et ils ne sont point revenus au Seigneur leur Dieu, et ils ne l’ont point cherché dans tous leurs malheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 11, 'Et Ephraïm demeura comme une colombe insensée et sans cœur. Il invoqua l’Égypte, et alla aux Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 12, 'Tandis qu’ils chemineront, je jetterai sur eux mon filet, je les ramènerai comme des oiseaux du ciel; je les punirai avec la rumeur même de leurs afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 13, 'Malheur à eux parce qu’ils se sont retirés de moi! les voilà tous craintifs parce qu’ils ont péché contre moi. Je les avais rachetés, et ils ont dit des mensonges contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 14, 'Et leurs cœurs n’ont point crié vers moi; et ils ont hurlé sur leurs couches; ils ont séché faute de pain et de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 15, 'Et ils ont été instruits par moi, et j’ai fortifié leurs mains; et ils ont eu contre moi des pensées de malice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 16, 'Ils sont devenus à rien; les voilà comme un arc détendu; leurs princes tomberont sous le glaive à cause de l’intempérance de leur langue; tel est leur avilissement dans la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 1, 'Ils seront frappés au sein d’un coup rapide contre terre, ou comme l’aigle s’abattant sur la maison du Seigneur, parce qu’ils ont transgressé mon alliance et péché contre ma loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 2, 'Et ils crieront vers moi, en disant: 0 Dieu, nous vous reconnaissons!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 3, 'Israël a pris en haine le bien; ils m’ont poursuivi comme un ennemi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 4, 'Ils ont fait pour eux, et non pour moi, des rois qui ont régné, sans me les faire connaître; avec leur argent et leur or, ils se sont fabriqué des idoles, et c’est pour cela qu’ils ont été exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 5, 'Répudie ton veau, Samarie; ma colère est exaspérée contre eux: jusques à quand sera-t-il impossible qu’ils soient purifiés');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 6, 'En Israël? C’est un artisan qui l’a fait; il n’est point Dieu; c’est pourquoi ton veau t’a égaré, Samarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 7, 'Ils ont semé du grain éventé, et leur destruction en fera la récolte. Ils n’ont pas une gerbe dont on puisse faire de la farine, et s’il y en a, les étrangers la mangeront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 8, 'Israël a été dévoré; il est maintenant parmi les nations comme un vase inutile,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 9, 'Parce qu’ils sont allés aux Assyriens. Éphraïm a refleuri contre lui-même; ils ont aimé les présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 10, 'Et c’est pourquoi ils seront livrés aux gentils; alors je les recevrai, et ils cesseront en peu de temps d’oindre des rois et des princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 11, 'Car Ephraïm avait multiplié les autels; mais ceux qu’il a aimés étaient des autels de péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 12, 'J’avais écrit pour lui une multitude de préceptes; mais ces lois ont été réputées par lui comme étrangères, même les autels qu’il aime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 13, 'Aussi quand ils immoleront une victime et en mangeront les chairs, le Seigneur ne les agréera pas. Alors il se souviendra de leur iniquité, et tirera vengeance de leurs crimes. Ils sont retournés en Égypte, et ils mangeront des viandes impures chez les Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 14, 'Tel Israël aussi a oublié son Créateur, et ils ont planté des bois sacrés, et Juda a multiplié les villes fortifiées; mais sur ces villes j’enverrai la flamme, et elles seront dévorées jusqu’aux fondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 1, 'Ne te réjouis pas, Israël, ne te mets pas en fête, comme les gentils, parce que tu t’es prostitué en t’éloignant de ton Dieu, tu as aimé les dons plus que des aires pleines de blé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 2, 'Mais l’aire et le pressoir les ont méconnus, et le vin les a trompés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 3, 'Ils ne sont point restés en la terre du Seigneur; Éphraïm a demeuré en Égypte, et ils mangeront des viandes impures chez les Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 4, 'Ils n’ont point fait au Seigneur des libations de vin, et ils ne lui ont point été agréables. Leurs victimes sont pour eux comme des pains d’affliction; tous ceux qui en mangent seront souillés, parce que leurs pains, s’ils soutiennent la vie, n’entreront point dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 5, 'Que ferez-vous les jours de réunions solennelles, et les jours de fête du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 6, 'À cause de cela, voilà qu’ils sortent des misères de l’Égypte, et Memphis les recevra, et Machmas les ensevelira. Quant à leur argent, la dévastation en héritera, et les ronces pousseront dans leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 7, 'Ils sont venus les jours de la vengeance, ils sont venus les jours de la rétribution, et Israël sera maltraité, comme un prophète en délire, comme un homme possédé par un malin esprit. Tes folies se sont multipliées à cause de la multitude de tes iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 8, 'La sentinelle d’Ephraïm était avec Dieu; mais un faux prophète a été comme un lacs tortueux sur toutes ses voies, et ils ont transplanté leur folie dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 9, 'Ils se sont perdus comme aux jours de la colline; mais Dieu se souviendra de leurs iniquités, et il tirera vengeance de leurs crimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 10, 'J’ai aimé Israël comme une grappe de raisin dans le désert, et j’ai vu leurs pères comme un fruit mûr dans un figuier. Pour eux, ils se sont approchés de Béelphégor, et dans leur opprobre ils se sont détournés de moi, et ils me sont devenus abominables autant qu’ils m’avaient été chers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 11, 'Ephraïm s’est envolé comme l’oiseau, et, à peine nées, ses gloires se sont évanouies, ou pendant l’enfantement, ou aussitôt conçues;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 12, 'Car, eût-il élevé ses enfants, il n’en sera pas moins sans postérité: malheur donc à lui, ma chair n’est plus avec eux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 13, 'Éphraïm, je l’ai vu, a fait une proie de ses enfants; Éphraïm a exposé ses fils à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 14, 'Donnez-leur, ô mon Dieu; mais que pouvez-vous leur donner? donnez-leur un sein stérile et des mamelles taries.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 15, 'Toutes leurs méchancetés se font en Galgala; c’est là que je les ai pris en haine pour leurs inventions abominables. Je les chasserai de ma maison, et je ne les aimerai plus, car tous leurs princes sont indociles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 16, 'Éphraïm s’est épuisé; il a desséché ses racines; il ne portera plus de fruits, et, dût-il en naître, je ferai mourir les fruits désirés de leurs entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 17, 'Dieu les a repoussés parce qu’ils ne lui ont point obéi, et ils seront errants parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 1, 'Israël était une vigne riche en sarments, abondante en fruits; mais plus ses grappes se sont multipliées, plus il a multiplié ses autels, et plus il a recueilli les biens de la terre, plus il a élevé de colonnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 2, 'Ils ont partagé leur cœur, et maintenant ils périront; Dieu lui-même renversera leurs autels, et leurs colonnes s’écrouleront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 3, 'Et alors ils diront: Nous n’avons point de roi, parce que nous n’avons pas craint le Seigneur; et un roi, que fera-t-il pour nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 4, 'Il dira de vaines paroles et des raisons mensongères; il fera une alliance perverse, et les jugements de Dieu abonderont comme l’herbe sauvage dans les champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 5, 'Ceux de Samarie habiteront auprès du veau de la maison de On, car son peuple a pleuré sur lui. Et autant');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 6, 'Et, après l’avoir lié pour les Assyriens, ils l’ont offert en présent au roi Jarim. Et il recevra en sa demeure Éphraïm, et Israël en ses conseils sera confondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 7, 'Samarie a renversé son roi comme un fétu qu’emporte le courant de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 8, 'Et les autels d’or, péchés d’Israël, seront détruits, et les ronces et les mauvaises herbes pousseront sur leurs autels. Et ils diront aux montagnes: Cachez-nous; et aux collines Écroulez-vous sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 9, 'Depuis qu’il y a des collines, Israël a péché, et c’est là qu’ils se sont arrêtés; mais la guerre que l’on fera aux fils de l’iniquité ne se bornera pas à les surprendre sur une colline');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 10, 'Pour les châtier. Les peuples se réuniront contre eux, pour qu’ils soient punis de leur double péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 11, 'Ephraïm est une génisse instruite à aimer la révolte; mais moi je tomberai sur son cou superbe. Je monterai sur Éphraïm, je forcerai Juda au silence; Jacob prévaudra contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 12, 'Semez pour vous-mêmes avec équité; recueillez les fruits de la vie; éclairez-vous de la lumière de la science, et cherchez le Seigneur jusqu’à ce que les fruits de la justice vous arrivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 13, 'Mais pourquoi gardez-vous le silence sur votre impiété et récoltez-vous des injustices? Tu as mangé le fruit du mensonge, parce que tu as mis ton espérance en tes péchés et dans la multitude de tes forces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 14, 'Mais la perdition s’élèvera parmi ton peuple, et tous tes remparts disparaîtront. Comme le prince Salaman partit de la maison de Jéroboam durant les jours de la guerre, et jeta à terre avec violence les mères sur les enfants,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 15, 'De même je te traiterai, ô maison d’Israël, à la vue de tes injustices et de tes méchancetés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 1, 'Ils sont tombés dès l’aurore: le roi d’Israël est tombé; Israël est un enfant, et moi je l’aimais, et j’ai rappelé ses fils de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 2, 'Autant je les ai rappelés, autant ils sont éloignés de moi; ils ont sacrifié à Baal, et ils ont encensé des idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 3, 'Et moi j’ai bandé les pieds d’Éphraïm, et je l’ai pris dans mes bras, et ils n’ont point connu que je les guérissais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 4, 'Au milieu de la perdition des hommes, je les ai enveloppés dans les langes de mon amour, et maintenant je serai pour eux comme un homme qui en frappe un autre à la joue, et je me retournerai sur Éphraim, et je prévaudrai contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 5, 'Éphraïm a demeuré en Égypte, et Åssur lui-même a été son roi, parce qu’il n’a pas voulu se convertir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 6, 'Et dans ses villes il a été vaincu par le glaive, et il a cessé de le tenir en ses mains; et ils se nourriront des fruits de leurs conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 7, 'Et le peuple de Dieu sera en suspens dans le lieu');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 8, 'Que ferai-je avec toi, Éphraïm? serai-je ton protecteur? O Israël, que ferai-je avec toi? Je te traiterai comme Adama et Seboïm. Mon cœur a changé pour toi, et tu as excité tous mes regrets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 9, 'Mais je n’agirai point selon le courroux de mon âme; je n’abandonnerai point Éphraïm, pour qu’il soit effacé; car je suis Dieu, et non un homme; un Saint est en toi, et je n’entrerai pas dans ta ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 10, 'Je marcherai après le Seigneur. Il rugira comme un lion; il rugira, et les enfants des eaux seront saisis de stupeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 11, 'Les enfants de mon peuple aussi seront saisis de stupeur, et fuiront de l’Égypte comme un oiseau, et de la terre des Assyriens comme une colombe, et je les ferai rentrer dans leurs demeures, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 12, 'Éphraïm m’a entouré de ses mensonges, Israël et Juda de leurs impiétés; maintenant Dieu les connaît, et le peuple saint s’appellera le peuple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 1, 'Éphraïm a poursuivi un vent funeste qui a fait durer tout le jour l’ardente chaleur; il a multiplié les vanités et les folies; il a fait alliance avec les Assyriens; il a vendu de l’huile en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 2, 'Et le Seigneur entrera en jugement avec Juda, afin de punir Jacob; et il le rétribuera selon ses voies et ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 3, 'Dans les entrailles de sa mère, il supplanta son frère, et, dans ses travaux, il fut fort contre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 4, 'Il fut fort avec un ange, et il prévalut; et ils pleurèrent, et ils me prièrent, ils me trouvèrent en la maison d’On; et là il leur fut parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 5, 'Et le Seigneur Dieu tout-puissant sera le mémorial de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 6, 'Et toi, Éphraïm, tu te convertiras à ton Dieu; garde donc sa miséricorde et sa justice, et approche - toi toujours de ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 7, 'Chanaan tient dans sa main une balance d’iniquité; il a aimé à opprimer avec violence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 8, 'Et Éphraïm a dit: Cependant je me suis enrichi, je me suis acquis le repos. Mais aucun de ses labeurs ne lui sera compté, à cause des injustices qu’il a commises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 9, 'Moi, le Seigneur ton Dieu, je t’ai fait sortir de l’Égypte; je te ferai encore camper sous des tentes, comme dans les jours de fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 10, 'J’ai parlé aux prophètes, et j’ai multiplié les visions, et j’ai parlé par la bouche des prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 11, 'Si Galaad n’est plus, c’est qu’il y avait en Galaad des princes menteurs faisant des sacrifices, et leurs autels sont comme des amas de pierres dans un champ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 12, 'Et Jacob se retira en Syrie, et Israël servit pour une femme, et pour une femme il garda les troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 13, 'Et par son prophète le Seigneur conduisit Israël hors de la terre d’Égypte, et c’est encore par son prophète qu’il le sauva.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 14, 'Et Éphraïm le provoqua et souleva sa colère; mais le sang versé par Éphraïm retombera sur sa tête, et le Seigneur le rétribuera selon son opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 1, 'À la parole de Jéroboam, Éphraïm a pris lui-même des commandements en Israël et les a mis devant Baal, et Éphraim est mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 2, 'Et maintenant ils continuent de pécher, et ils se sont fait de leur argent des statues en fonte à l’image des idoles, œuvres accomplies d’un artiste; et ils se disent entre eux: Sacrifiez des hommes, car il y a disette de bœufs!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 3, 'À cause de cela, ils seront comme le nuage du matin, comme la rosée qui vient à l’aurore, comme la poudre que le vent emporte hors de l’aire, comme la vapeur des larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 4, 'Moi, le Seigneur ton Dieu, qui ai affermi le ciel; moi, le créateur de la terre, moi, dont les mains ont créé toute l’armée céleste, je ne t’ai point montré ces créatures pour que tu chemines après elles; c’est moi qui t’ai délivré de la terre d’Égypte, et tu ne connaîtras point d’autre Dieu que moi, et nul autre que moi ne sauve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 5, 'J’ai été ton pasteur dans le désert, en une terre inhabitée');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 6, 'Et sans pâturages; et ils s’y sont rassasiés et remplis, et leurs cœurs se sont enorgueillis, et à cause de cela ils m’ont oublié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 7, 'Et je serai pour eux comme une panthère et comme un léopard, sur la route de l’Assyrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 8, 'J’accourrai au-devant d’eux comme une ourse affa');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 9, 'En ta destruction, ô Israël, qui te portera secours?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 10, 'Où est celui-là? est-ce ton roi? Qu’il te sauve en toutes tes villes; qu’il te juge celui à qui tu as dit: Donne-moi un roi et un prince!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 11, 'Je t’ai donné un roi dans ma colère, et je t’ai traité dans mon courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 12, 'Éphraïm a fait un complot d’iniquité; son impiété a été cachée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 13, 'Les douleurs de la femme qui enfante lui viendront. Celui-là est ton fils, le Sage, parce qu’il ne se tiendra pas immobile pendant le massacre de tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 14, 'Je les tirerai de l’enfer, dira-t-il; je les affranchirai tous de la mort. O mort, où est ta sentence? Enfer, où est ton aiguillon? Mais cette consolation est cachée à mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 15, 'Et quand l’enfer sèmera la division entre les frères, le Seigneur enverra contre lui un vent brûlant du désert, et il desséchera les veines de la mort, et il tarira ses sources; lui-même fera de ses champs une terre aride, et enlèvera ses vases les plus précieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 1, 'Samarie sera détruite, parce qu’elle s’est révoltée contre son Dieu. Ils périront par le glaive; tous ses enfants à la mamelle seront écrasés à terre, et les femmes enceintes seront déchirées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 2, 'Israël, reviens à ton Dieu; car tes fils s’énervent, à cause de tes iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 3, 'Prenez avec vous de bonnes paroles, et convertissez-vous au Seigneur votre Dieu: dites-lui que vous renoncez aux récompenses de l’iniquité pour choisir le bien; dites-lui: Nous vous offrons les fruits de nos lèvres!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 4, 'Assur ne nous sauvera pas; nous ne monterons plus à cheval; nous ne dirons plus aux œuvres de nos mains: Vous êtes nos dieux; Celui qui est en vous, Seigneur, aura pitié de l’orphelin!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 5, 'Le Seigneur a dit: Je restaurerai leurs demeures, je les aimerai manifestement, parce qu’ils ont détourné d’eux ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 6, 'Je serai pour Israël comme la rosée; il fleurira comme le lis, et il jettera ses racines comme le cèdre du Liban.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 7, 'Ses rameaux s’étendront; il sera chargé de fruits comme un olivier, et il répandra son parfum comme l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 8, 'Les peuples se convertiront et viendront s’asseoir sous son ombre; ils vivront et se rassasieront de son pain; et son mémorial fleurira comme une vigne, comme le vin du Liban');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 9, 'En Éphraïm. Qu’y a-t-il encore de commun entre lui et les idoles? Je l’ai humilié, et je rétablirai ses forces. Je suis comme un genièvre touffu; c’est de moi que viennent tes fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 10, 'Qui est sage et comprendra ces choses? Qui est savant et les connaîtra? Les voies du Seigneur sont droites; les justes y marchent, les impies y trébucheront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Paroles d’Amos qui lui vinrent en la bergerie de Thécué et dont il eut la vision concernant Jérusalem, durant les jours d’Ozias, roi de Juda, et durant les jours de Jéroboam, fils de Joas, roi d’Israël, deux ans avant le tremblement de terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Et il dit: Le Seigneur a parlé du haut de Sion, il a fait entendre sa voix de Jérusalem, et les pâturages des bergers ont été désolés, et la cime du Carmel a été desséchée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Et le Seigneur a dit: Ce n’est point à cause des triples et quadruples impiétés de Damas que je la prendrai en aversion; c’est parce qu’avec des scies de fer ils ont scié les femmes enceintes en Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Et je lancerai la flamme sur la maison d’Azaël, et elle dévorera les fondations des fils d’Ader.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Et je briserai les verrous de Damas, et j’exterminerai ceux qui habitent la plaine d’On, et je taillerai en pièces la tribu des hommes d’Haran, et l’élite du peuple de Syrie sera emmenée en captivité, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Voici ce que dit le Seigneur: Ce n’est point à cause des triples et quadruples impiétés de Gaza que je les prendrai en aversion, c’est parce qu’ils ont fait prisonniers les captifs pour les enclore en Idumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Et je lancerai la flamme sur les murs de Gaza, et elle dévorera les fondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Et j’exterminerai les habitants d’Azot; et la tribu d’Ascalon sera détruite, et j’étendrai la main sur Accaron, et le reste des Philistins périra, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Voici ce que dit le Seigneur: Ce n’est point à cause des triples et quadruples impiétés de Tyr que je les prendrai en aversion, c’est parce qu’ils ont enclos en Idumée les captifs de Salomon, et qu’ils ne se sont point souvenus de l’alliance de leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Et je lancerai la flamme sur les remparts de Tyr, et elle en dévorera les fondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Voici ce que dit le Seigneur: Ce n’est point à cause des triples et quadruples impiétés de l’Idumée que je les prendrai en aversion, c’est parce qu’ils ont poursuivi leurs frères à coups de glaive, et profané leur mère sur la terre, et pris en témoignage son effroi, et qu’ils ont gardé leur emportement dans la victoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Et je lancerai la flamme sur Thaman; et elle dévorera les fondations de leurs remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Voici ce que dit le Seigneur: Ce n’est point à cause des triples et quadruples impiétés d’Ammon que je le prendrai en aversion, c’est parce qu’ils ont déchiré les femmes enceintes des Galaadites, pour étendre les limites de leur territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Et j’allumerai la flamme sur les murs de Rabbath, et elle en dévorera les fondations, au milieu des cris, en un jour de combat; et au jour de sa destruction cette ville tremblera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Et ses rois seront emmenés en captivité, et avec eux ses prêtres et ses princes, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Voici ce que dit le Seigneur: Ce n’est point à cause des triples et quadruples impiétés de Moab que je le prendrai en aversion, c’est parce qu’il a brûlé les os du roi de l’Idumée, jusqu’à les réduire en poudre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Et je lancerai la flamme sur Moab; et elle dévorera les fondations de ses villes, et Moab périra dans l’impuissance, au milieu des cris et au son des trompettes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Et je détruirai son juge, et j’exterminerai ses princes avec lui, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Voici ce que dit le Seigneur: Ce n’est point à cause des triples et quadruples impiétés des fils de Juda que je les prendrai en aversion, c’est parce qu’ils ont répudié la loi du Seigneur, et qu’ils n’ont point gardé les commandements, et que les vaines idoles qu’ils avaient fabriquées et qu’avaient suivies leurs pères les ont eux-mêmes égarés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Et je lancerai la flamme sur Juda, et elle dévorera les fondations de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Voici ce que dit le Seigneur: Ce n’est pas à cause des triples et quadruples impiétés d’Israël que je le prendrai en aversion; c’est parce qu’il a livré le juste à prix d’argent, et le pauvre pour des sandales');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Que l’on traîne dans la poussière des chemins; c’est parce qu’ils ont frappé du poing la tête de l’indigent, qu’ils ont fait dévier le faible, et que le fils et le père ont eu la même concubine, afin de profaner le nom de leur Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Et parce que, liant avec des cordes leurs manteaux, ils en ont voilé l’autel, et bu le vin des calomnies, dans le temple de leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Cependant c’est moi qui ai, devant leur face, chassé l’Amorrhéen d’où il était; sa taille était celle du cèdre, sa force celle du chêne; et j’ai desséché ses fruits au-dessus de la terre, et ses racines au-dessous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Et vous, je vous ai ramenés de la terre d’Égypte, et je vous ai conduits çà et là dans le désert, pendant quarante ans, pour vous donner ensuite en héritage la terre des Amorrhéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Et j’ai pris de vos fils pour en faire des prophètes, et de vos jeunes enfants pour me les consacrer; tout cela n’est-il pas vrai, fils d’Israël? dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Et vous faites boire du vin aux Nazaréens, et vous donnez des ordres aux prophètes, disant: Ne prophétisez pas!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Et, à cause de cela, voilà que je vais rouler sur vous, comme roule un chariot chargé de paille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Et il n’y aura pas de fuite pour le coureur, et le fort ne pourra se prévaloir de sa force, et le guerrier ne sauvera pas sa vie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Et l’archer ne résistera pas, et l’homme aux pieds légers ne saura s’échapper, et le cavalier ne sauvera pas sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Et le fort ne mettra plus son cœur en ses forces; et, nu, il s’enfuira en ce jour, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Écoutez cette parole qu’a dite le Seigneur contre vous, ô maison d’Israël, et contre toute ta famille que j’ai ramenée de la terre d’Égypte, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Hormis vous, je n’ai connu aucune des tribus de la terre; et, à cause de cela, je tirerai vengeance de vos péchés contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Deux hommes peuvent-ils marcher d’accord en toutes choses, s’ils ne se connaissent l’un l’autre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Le lion rugira-t-il en sa forêt, s’il n’a quelque proie? Le lionceau donnera-t-il de la voix en son antre, s’il n’a rien ravi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'L’oiseau tombera-t-il à terre sans oiseleur? Détendra-t-on le filet avant qu’il ait rien pris?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Sonnera-t-on de la trompette dans la ville sans que le peuple tremble, et y surviendra-t-il calamité qui ne soit envoyée par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Or le Seigneur ne fera rien qu’il n’ait révélé ses instructions à ses serviteurs les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Le lion rugira, et qui n’en sera pas épouvanté? Le Seigneur Dieu a parlé: qui ne prophétisera point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Faites des proclamations dans les villes des Assyriens, et dans les villes d’Égypte, et dites: Réunissez');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Elle n’a point connu ce qui allait arriver contre ses habitants, et ils thésaurisent en leurs maisons l’iniquité et la misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'À cause de cela, voici ce que dit le Seigneur Dieu: Autour de toi, Tyr, on fera de ton territoire un désert; et ta puissance t’échappera, et tes champs seront dévastés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Voici ce que dit le Seigneur: Tels, par le berger, sont arrachés de la gueule du lion deux jambes ou un lambeau d’oreille; tels seront arrachés les fils d’Israël qui demeureront en Samarie en face de la tribu de Jacob, et emmenés à Damas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Prêtres, écoutez, et portez votre témoignage en la maison de Jacob, dit le Seigneur Dieu tout-puissant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Le jour où je punirai sur lui-même les impiétés d’Israël, je tirerai vengeance des autels de Béthel. Et les cornes de l’autel seront abattues et tomberont à terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Je renverserai et je foulerai aux pieds la maison entourée de colonnes sur la maison d’été; et les maisons d’ivoire périront, et bien d’autres maisons seront enveloppées dans leur ruine, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 1, 'Écoutez cette parole, génisses de la Basanite, qui êtes en la montagne de Samarie, vous qui opprimez les pauvres, qui foulez aux pieds les indigents, et qui dites à vos maîtres: Donnez-nous afin que nous buvions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 2, 'Le Seigneur jure par ses saints que les temps arrivent contre vous, où l’on vous enlèvera avec des armes, et où des hommes de pestilence, enflammés de colère, jetteront ceux qui seront avec vous en des chaudières bouillantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 3, 'Et vous, vous serez entraînées nues, les unes devant les autres, et vous serez précipitées en la montagne de Rhomman, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 4, 'Vous êtes entrés à Béthel, et vous avez péché, et vous avez multiplié vos impiétés en Galgala; dès le matin, vous avez offert vos oblations, et donné vos dîmes durant les trois jours. ·');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 5, 'Et ils ont lu la loi au dehors; et ils ont fait des invocations à haute voix. Publiez que les fils d’Israël ont aimé ces choses, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 6, 'Et moi, en toutes vos villes, je vous ferai grincer des dents; il y aura disette de pain en toutes vos maisons, et vous ne vous êtes point convertis à moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 7, 'Et moi, je vous ai refusé la pluie, trois mois avant la vendange; je ferai pleuvoir sur telle ville; sur telle autre, je ne ferai point pleuvoir; sur tel terrain, il pleuvra; et tel autre, où il n’aura pas plu, sera desséché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 8, 'Et les habitants de deux ou trois villes se rassembleront en une seule ville, pour boire de l’eau, et ils ne seront point désaltérés; et vous ne vous êtes point convertis à moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 9, 'Je vous ai frappés de la fièvre et de la jaunisse. Vous avez multiplié vos jardins et vos vignes; mais les chenilles ont dévoré vos plants de figuiers et d’oliviers; et vous ne vous êtes point convertis à moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 10, 'Je vous ai envoyé la mort par les chemins de l’Égypte; j’ai fait tomber vos jeunes gens sous le glaive, et vos chevaux ont été pris; dans ma colère, j’ai livré vos camps à la flamme; et, même après cela, vous ne vous êtes point convertis à moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 11, 'Je vous ai renversés, comme Dieu renversa Sodome et Gomorrhe, et vous êtes devenus semblables au tison que l’on retire du foyer; et, même après cela, vous ne vous êtes point convertis à moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 12, 'Et c’est pourquoi j’agirai ainsi envers toi, ô Israël; et parce que j’agirai ainsi, prépare-toi à invoquer ton Dieu, ô Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 13, 'Car me voici, moi qui affermis le tonnerre, qui fais naître les vents, qui annonce aux hommes mon Christ, qui fais l’aurore et la brume, qui monte sur les hauts lieux de la terre. Le Seigneur Dieu tout-puissant, voilà mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 1, 'Écoutez cette parole du Seigneur que j’ai recueillie à votre sujet, écoutez cette plainte: La maison d’Israël est tombée, jamais elle ne se relèvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 2, 'La vierge d’Israël est tombée sur la terre, nul ne pourra la remettre debout.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 3, 'À cause de cela, le Seigneur Dieu dit ces choses: La ville d’où sortaient mille hommes, il en sera laissé cent; celle d’où sortaient cent hommes, il en sera laissé dix en la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 4, 'C’est pourquoi, voici ce que dit le Seigneur à la maison d’Israël: Cherchez-moi, et vous vivrez;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 5, 'Mais ne cherchez point Béthel, et n’allez point en Galgala, et ne dépassez point le puits du serment; car Galgala sera emmenée captive, et Béthel sera comme n’étant plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 6, 'Cherchez le Seigneur et vivez, de peur que la maison de Joseph ne brûle comme un feu, et ne vous dévore; car nul ne sera là pour éteindre l’incendie en la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 7, 'Celui qui juge au haut des cieux, a de même établi la justice sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 8, 'Celui qui a créé toutes choses les change à son gré il change les ténèbres en matin; il change le jour en nuit sombre; c’est lui qui appelle l’eau de la mer, qui la répand sur la surface de la terre; le Seigneur est son nom:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 9, 'Lui qui amène la ruine contre la force, et déchaîne la misère contre le lieu fortifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 10, 'Ils ont haï l’homme qui les réprimandait devant leurs portes, et ils ont eu en abomination la parole sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 11, 'À cause de cela, et en punition de ce que vous avez frappé du poing les pauvres, et de ce que vous avez accepté d’eux de beaux présents, bâtissez des maisons de pierres de taille, et vous ne les habiterez pas; plantez des vignes excellentes, et vous n’en boirez pas le vin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 12, 'Car je connais vos nombreuses impiétés, et vos péchés sont grands; vous foulez aux pieds la justice; pour juger, vous prenez des présents; et vous vous détournez des pauvres devant les portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 13, 'C’est pourquoi l’homme intelligent, en ces tempslà, gardera le silence; car c’est le temps de la perversité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 14, 'Cherchez le bien et non le mal, afin que vous viviez; et, de cette manière, le Seigneur Dieu tout-puissant sera avec vous. Comme vous avez dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 15, 'Nous avons haï le mal, et nous aimons le bien; faites revivre la justice devant les portes de la ville, afin que le Seigneur Dieu tout - puissant ait pitié des restes de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 16, 'À cause de cela, voici ce que dit le Seigneur Dieu tout-puissant: On se frappera la poitrine sur toutes les places; et dans toutes les rues on criera: Malheur! malheur! On appellera le laboureur à ce deuil et à cette plainte, pour qu’il se joigne à ceux qui savent se lamenter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 17, 'Et sur toutes les voies on se frappera la poitrine, parce que je viendrai au milieu de vous, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 18, 'Malheur à ceux qui désirent le jour du Seigneur. Et pourquoi ce jour-là est-il pour vous le jour du Seigneur? C’est que ce jour est ténèbres, et non lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 19, 'Vous serez comme un homme qui s’enfuit en voyant un lion, puis aussitôt rencontre une ourse; et qui, s’il bondit jusqu’à sa demeure, s’il appuie sa main contre le mur, est mordu par un serpent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 20, 'Le jour du Seigneur n’est-il pas ténèbres, et non lumière? Ce jour n’est-il pas obscurité sans la moindre lueur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 21, 'Je hais, je répudie vos fêtes; je ne puis souffrir l’odeur de vos victimes en vos solennités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 22, 'Si donc vous m’offrez des holocaustes et des sacrifices, je ne les agréerai pas; je n’aurai point égard à vos hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 23, 'Éloignez de moi le bruit de vos cantiques, je n’écouterai pas le son de vos harpes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 24, 'Et mon jugement roulera comme une pluie violente, et ma justice comme un torrent où l’on ne peut naviguer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 25, 'Maison d’Israël, ne m’avez-vous pas offert des sacrifices et des victimes durant quarante ans dans le désert?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 26, 'Vous avez élevé le tabernacle de Moloch, et l’étoile de votre dieu Raiphan, et leurs images que vous aviez fabriquées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 27, 'Et je vous ferai émigrer au delà de Damas, dit le Seigneur; le Dieu tout - puissant est son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 1, 'Malheur à ceux qui méprisent Sion, et qui mettent leur confiance en la montagne de Samarie! Ils ont recueilli les prémices des nations, puis ils sont entrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 2, 'Passez tous auprès, et voyez; et de là traversez Ematrabba, et de là descendez à Geth des Philistins; ce sont les plus puissants de tous les royaumes. Voyez si leurs frontières sont plus étendues que vos frontières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 3, 'Vous qui venez pour le mauvais jour, vous qui approchez des sabbats trompeurs, et vous y attachez;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 4, 'Vous qui dormez sur des lits d’ivoire, et vous y étendez pour vivre avec mollesse; vous qui mangez les chevreaux de votre menu bétail, et de jeunes veaux tirés de vos troupeaux et nourris de lait;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 5, 'Vous qui battez des mains au son des instruments! Ils ont cru que ces choses seraient durables, et non fugitives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 6, 'Vous qui buvez du vin clarifié, et vous parfumez de la meilleure myrrhe, et ne souffrez nullement de l’affliction de Joseph.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 7, 'À cause de cela, ils passeront de la puissance des forts à la captivité, et l’on n’entendra plus le hennissement des chevaux en Éphraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 8, 'Car le Seigneur en lui-même a juré, disant: Puisque j’ai en abomination toute l’insolence de Jacob, j’ai pris également en haine leurs contrées, j’effacerai donc la ville avec tous ceux qui l’habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 9, 'Et voici ce qui arrivera: Si dans une maison il y dix hommes, ils mourront; et ceux qui y resteront cachés mourront aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 10, 'Et leurs parents les prendront, et ils se feront violence pour enlever leurs os de la maison; et l’on dira au chef de la maison: Y a-t-il encore quelqu’un avec toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 11, 'Et celui-ci répondra: Il n’y a personne; et le premier répondra: Tais-toi, garde-toi de prononcer le nom du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 12, 'Car voilà que le Seigneur a donné ses ordres; et il frappera les grandes maisons pour ouvrir des brèches, et les petites pour y faire des crevasses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 13, 'Les chevaux peuvent-ils courir au milieu des rochers? Peuvent-ils s’empêcher de hennir au milieu des cavales? Vous qui à la place du jugement avez mis la colère, et qui avez changé en amertume les fruits de la justice;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 14, 'Vous qui mettez votre joie dans le néant; vous qui dites N’est-ce point par notre force que nous avons des fronts puissants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 15, 'Maison d’Israël, j’exciterai contre vous une nation, dit le Seigneur Dieu des armées; et elle vous brisera depuis l’entrée d’Émath jusqu’au torrent du désert d’Occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 1, 'Ceci est la vision que m’a envoyée le Seigneur Dieu; voilà une nuée de sauterelles qui vient de l’Orient, et voilà de grandes sauterelles sur les champs du roi Gog.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 2, 'Et quand elles eurent achevé de dévorer l’herbe de la terre, je dis: Seigneur, Seigneur, soyez miséricordieux. Qui relèvera Jacob? car il est réduit à rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 3, 'Seigneur, repentez-vous pour cela. Et cela ne sera point, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 4, 'Ceci est la vision que m’a envoyée le Seigneur: Voilà que le Seigneur appela le châtiment par la flamme, et le feu dévora une grande part de l’abîme, et il consuma l’héritage du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 5, 'Je dis Seigneur, cessez donc; qui relèvera Jacob, car il est réduit à rien?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 6, 'Seigneur, repentez-vous pour cela. Et cela ne sera point, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 7, 'Ceci est la vision que m’a envoyée le Seigneur: Voilà que le Seigneur se tient debout sur un mur de diamant, et il avait un diamant à la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 8, 'Et le Seigneur me dit: Que vois-tu, Amos? et je dis: Un diamant; et le Seigneur me dit: Voilà que je mets un diamant sur un diamant entre moi et mon peuple d’Israël; je ne continuerai plus de me montrer à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 9, 'Mais les autels de la division seront effacés; et les fêtes d’Israël seront délaissées; et je me lèverai avec le glaive contre la maison de Jéroboam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 10, 'Or Amasias, prêtre de Béthel, envoya au roi d’Israël Jeroboam, disant: Amos fait des complots contre toi, au milieu de la maison d’Israël; la terre ne pourrait pas souffrir toutes ses paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 11, 'Car voilà ce que dit Amos: Jéroboam périra par le glaive, et Israël sera emmené captif hors de sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 12, 'Et Amasias dit à Amos: O Voyant, pars, retire-toi dans la terre de Juda; c’est là que tu vivras, et là que tu prophétiseras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 13, 'Tu ne continueras plus de prophétiser en Béthel; c’est la ville sainte du roi, et la demeure royale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 14, 'Et Amos répondit, et dit à Amasias: Je n’étais');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 15, 'Et le Seigneur m’a pris au milieu de mon troupeau, et le Seigneur m’a dit: Pars et prophétise à mon peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 16, 'Et maintenant écoute la parole du Seigneur: Tu dis Ne prophétise point sur Israël, et n’ameute pas la foule contre la maison de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 17, 'À cause de cela, voici ce que dit le Seigneur: Ta femme se prostituera dans la ville, et tes fils et tes filles périront par le glaive, et tes champs seront partagés au cordeau, et tu mourras en une terre impure, et Israël sera emmené captif hors de sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 1, 'Ceci est la vision que m’a envoyée le Seigneur; voilà un vase d’oiseleur à la glu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 2, 'Et le Seigneur me dit: Que vois-tu, Amos? et je dis: Un vase d’oiseleur à la glu; et le Seigneur me dit: La fin de mon peuple d’Israël est arrivée; je ne continuerai plus de me montrer à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 3, 'Et en ce jour-là les lambris du temple pousseront des cris de douleur, dit le Seigneur. Une multitude d’hommes tomberont en tous lieux; et j’étendrai sur eux le silence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 4, 'Écoutez donc ces choses, vous qui le matin opprimez l’indigent, et qui foulez aux pieds les pauvres de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 5, 'Disant: Quand donc le mois sera-t-il écoulé pour');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 6, 'Pour que nous achetions le pauvre à prix d’argent; l’indigent pour des sandales, et que nous trafiquions sur toutes les denrées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 7, 'Le Seigneur fait serment de punir l’orgueil de Jacob Nulle de vos œuvres, en ma victoire, ne sera oubliée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 8, 'Et n’est-ce pas à cause de ces choses que la terre sera troublée, que tous ceux qui l’habitent seront dans la douleur; et que la destruction montera comme le fleuve d’Égypte, et descendra comme lui?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 9, 'Et en ce jour-là ceci arrivera, dit le Seigneur Maître Le soleil se couchera à midi, et sur la terre, la lumière fera place aux ténèbres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 10, 'Et je changerai vos fêtes en deuil, et tous vos cantiques en lamentations; et je ceindrai vos reins de cilices, et toute tête deviendra chauve; et Israël pleurera, comme on pleure un bien-aimé, et ceux qui l’accompagneront souffriront comme en un jour de douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 11, 'Voilà que ces jours arrivent, dit le Seigneur, et j’enverrai la famine sur la terre, non la disette de pain et d’eau, mais la soif d’entendre la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 12, 'Et d’une mer à l’autre les hommes seront agités, et du nord au levant ils courront, cherchant la parole du Seigneur, et ils ne la trouveront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 13, 'En ce jour-là, les vierges les plus belles et les jeunes hommes tomberont de soif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 14, 'Ceux qui jurent par la propitiation de Samarie, et disent: Vive ton Dieu, Dan! vive ton Dieu, Bersabée! ceux-là tomberont et ne se relèveront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 1, 'J’ai vu le Seigneur debout sur l’autel, et il a dit: Frappe sur le propitiatoire, et le temple sera ébranlé; frappe ensuite sur toutes les têtes. Et ceux qui resteront, je les ferai périr par le glaive; nul n’échappera par la fuite, nul ne sera sauvé, ni ne trouvera de salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 2, 'Dussent-ils se cacher en enfer, ma main les en arracherait; dussent-ils monter aux cieux, je les en précipiterais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 3, 'Dussent-ils s’enfermer dans les grottes du Carmel, je saurais les y trouver et les prendre; dussent-ils, hors de ma vue, plonger dans les abîmes de la mer, je donnerais mes ordres au dragon, et il les suivrait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 4, 'Dussent ils partir captifs devant leurs ennemis, là je commanderais au glaive, et il les exterminerait tous. Et j’attacherai sur eux mes regards pour leur malheur, et non pour leur bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 5, 'Et le Seigneur Maître, Dieu tout-puissant, touche la terre, et elle est ébranlée; et tous ceux qui l’habitent seront dans la douleur; et la destruction montera comme le fleuve de l’Égypte, et descendra comme lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 6, 'C’est lui qui bâtit des degrés pour monter au ciel, et affermit sa promesse sur les fondements de la terre; c’est lui qui appelle les eaux de la mer, et les verse sur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 7, 'Fils d’Israël, n’êtes-vous point pour moi comme les fils des Éthiopiens? dit le Seigneur. N’est-ce point moi qui ai fait venir Israël de l’Égypte, comme les Philistins de la Cappadoce, et les Syriens de la mer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 8, 'Voilà que le Seigneur Dieu a les yeux sur le royaume des pécheurs, et je l’effacerai de la terre. Mais je n’enlèverai pas entièrement la maison de Jacob, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 9, 'Car c’est moi qui commande, et je vannerai, parmi toutes les nations, la maison d’Israël, comme on vanne le blé au van, et pas un débris ne tombera par terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 10, 'Tous les pécheurs de mon peuple périront par le glaive, eux qui disent: Le malheur ne nous approchera pas, il ne viendra pas sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 11, 'Et ce jour-là je relèverai le tabernacle de David, qui était tombé; j’en réparerai les brèches, j’en réédifierai les ruines, et je le restaurerai comme il était dans les anciens jours,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 12, 'Afin que le reste des hommes et tous les gentils, par qui mon nom a été invoqué, me cherchent, dit le Seigneur, qui fera toutes ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 13, 'Voilà que les jours arrivent, dit le Seigneur, où la moisson atteindra la vendange, et où la grappe noircira pendant les semailles. Et les montagnes ruisselleront de douceur, et toutes les collines seront plantées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 14, 'Et je ramènerai mon peuple Israël de la captivité, et ils réédifieront les villes détruites, et ils les habiteront; ils planteront des vignes, et ils en boiront le vin; ils cultiveront des jardins, et ils en mangeront les fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 15, 'Et je les rétablirai dans leur héritage, et ils ne seront plus arrachés de la terre que je leur ai donnée, dit le Seigneur Dieu tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Et la parole de Dieu vint à Michée, fils de Morasthi, aux jours de Joatham, Achaz et Ézéchias, rois de Juda, sur les choses qu’il vit concernant Samarie et Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Écoutez, peuples, ces paroles; que toute la terre soit attentive, et tous ceux qu’elle contient. Et le Seigneur Maître sera parmi nous comme un témoignage, le Seigneur du haut de sa maison sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Car voilà que le Seigneur sortira du lieu où il réside, et il descendra, et il marchera sur les hauteurs de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Et sous lui les montagnes seront émues, et les vallées fondront comme la cire devant le feu, et comme les eaux d’une cataracte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Et tout cela arrivera à cause de l’impiété de Jacob et des péchés de la maison d’Israël. Quelle est l’impiété de Jacob? n’est-ce pas Samarie? Quel est le péché de Juda? n’est-ce pas Jérusalem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Je rendrai Samarie comme la cabane d’un garde de vergers dans les champs, comme un plant de vigne; et j’arracherai ses pierres pour les jeter dans le ravin, et je mettrai à découvert ses fondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Et toutes ses statues tomberont; et tous les salaires qu’elle a reçus seront livrés aux flammes; et j’anéantirai toutes ses idoles; car elle a amassé des salaires de prostitution; et de ces salaires de prostitution elle s’est enrichie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'À cause de cela, elle se frappera la poitrine et se lamentera; elle ira nue et déchaussée; ses lamentations seront comme les sifflements du dragon, et ses plaintes comme celles des filles des Sirènes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Car la plaie l’accable; sa plaie s’est étendue jusqu’en Juda, et touche aux portes de mon peuple, à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'O vous, gens de Geth, ne vous glorifiez pas; vous, gens d’Énacim, n’édifiez pas avec les ruines du temple par dérision; mais répandez de la poussière sur vos tétes par dérision de vous-mêmes!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'La populeuse Sennaar, qui habite en joie ses villes, n’en est point sortie pour pleurer une maison voisine; elle entendra votre plainte douloureuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Qui a commencé à faire du bien à celle qui habitait dans la douleur? Car les maux sont aussi descendus, par le Seigneur, jusqu’aux portes de Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Avec le tumulte des chars et des cavaliers. Celle qui demeure en Lachis est pour la fille de Sion le principe de son péché; car en toi se sont trouvées les impiétés d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'À cause de cela, le Seigneur enverra des vengeurs jusqu’aux héritages de Geth, et jusqu’aux maisons vaines qui ont été vanités pour les rois d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Et ils emmèneront tes héritiers, ô toi qui demeures en Lachis! L’héritage de gloire de la fille d’Israël ne subsistera pas au delà d’Odollam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Rase-toi, coupe ta chevelure à cause de tes enfants, qui font tes délices; dilate ton veuvage comme un aigle; car on les a emmenés en captivité hors de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Ils se préparent des peines; même sur leurs couches, ils songent à faire le mal; ils le font, dès que le jour paraît, parce qu’ils n’ont pas élevé les mains vers Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Ils ont désiré des champs, et ils ont dépouillé des orphelins; ils ont opprimé des familles; ils ont pris l’un avec sa demeure, l’autre avec son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'À cause de cela, le Seigneur a dit: Voilà que je pense à me venger de cette tribu; vous ne relèverez plus la tête, et vous ne marcherez plus droit d’un pas superbe, parce que les temps sont mauvais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'En ces jours-là, vous serez des sujets de fables, et l’on chantera sur vous une lamentation, disant: Nous sommes accablés de misère; la part de mon peuple a été mesurée au cordeau, et nul n’était là pour empêcher le ravisseur et le mettre en fuite, et nos champs ont été partagés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'À cause de cela, nul n’étendra plus le cordeau pour te faire ta part de terre. Dans l’Église du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Ne versez point de larmes, et qu’on ne pleure point sur ces choses; car il ne rétractera pas ses reproches,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Celui qui dit: La maison de Jacob a irrité l’Esprit du Seigneur. N’est-ce point sa coutume? Les paroles du Seigneur ne sont-elles pas justes sur ce peuple? Et n’ont-elles pas cheminé avec droiture?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Jadis mon peuple s’est soulevé en ennemi contre sa paix. On l’a écorché et on lui a enlevé la peau comme pour lui ôter l’espérance, dans les brisements de la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Les chefs de mon peuple seront précipités de leurs maisons de délices; et à cause de leurs mœurs perverses, ils ont été rejetés. Allez aux montagnes éternelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Lève-toi et marche; car il n’est plus pour toi de repos à cause de ton impureté. Vous êtes perdus de corruption;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Vous avez fui quand personne ne vous poursuivait. L’esprit du mal a produit le mensonge, il s’est infiltré en toi comme le vin et l’ivresse. Et voici ce qui arrivera: d’une goutte de sang de ce peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Il en naîtra la réunion de Jacob et de toutes ses tribus; je recueillerai avec amour les restes d’Israël, et je les ferai retourner au même lieu. Comme des brebis dans l’angoisse, comme un menu troupeau au milieu de son parc, ils s’élanceront des contrées des hommes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'À travers la brèche ouverte devant eux; ils en ont franchi l’ouverture, ils ont passé la porte par où ils étaient sortis; leur roi est devant eux, et le Seigneur sera le premier à leur tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Et il dira: Écoutez maintenant ces paroles, princes de la maison de Jacob, restes de la maison d’Israël; n’est-ce pas à vous de connaître le jugement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Ceux qui haïssent le bien et cherchent le mal, arrachent eux-mêmes la peau de leur corps et la chair de leurs os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'De même qu’ils ont mangé les chairs de mon peuple, qu’ils l’ont écorché pour lui enlever la peau, qu’ils ont rompu ses os, qu’ils l’ont dépecé, comme les viandes qu’on fait cuire dans une marmite ou une chaudière:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'De même ils crieront au Seigneur, et il ne les écoutera pas; et en ce temps-là il détournera d’eux sa face, parce qu’ils ont fait le mal en leurs pratiques contre le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Voici ce que dit le Seigneur contre les prophètes qui égarent mon peuple, qui mordent à pleines dents, qui lui annoncent la paix, et qui, si rien n’est donné à leur bouche, excitent la guerre contre lui:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'À cause de cela, la nuit sera pour vous sans visions, il y aura pour vous ténèbres sans prophéties; et le soleil se couchera sur les prophètes, et pour eux le jour sera obscurci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Et les voyants qui devinent les songes seront confondus, et les devins seront moqués, et tout le monde parlera contre eux, parce qu’il n’y aura personne pour les écouter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Pour moi, je me remplirai de force, inspiré par le Seigneur, par le jugement et l’autorité, pour faire connaître ses impiétés à Jacob et ses péchés à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Écoutez donc ces paroles, chefs de la maison de Jacob, restes de la maison d’Israël, vous qui haïssez la justice et pervertissez toute droiture,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Qui bâtissez Sion dans le sang et Jérusalem dans l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Les princes de Jérusalem ont jugé pour des présents; ses prêtres ont parlé pour un salaire; ses prophètes ont prédit pour de l’argent, et ils se sont reposés sur le Seigneur, disant: Est-ce que le Seigneur n’est pas avec nous? Jamais il ne nous arrivera malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'À cause de cela, à cause de vous, la charrue passera sur Sion comme sur un champ; Jérusalem ressemblera à la cabane d’un garde de vergers, et la montagne du temple sera une forêt de chênes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 1, 'Et voici ce qui arrivera: au dernier jour, la montagne du Seigneur apparaîtra; on la verra au-dessus des cimes des monts; elle s’élèvera plus haut que les collines. Et les peuples auront hâte de s’en approcher;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 2, 'Et les gentils viendront en grand nombre, et diront Venons, montons sur la montagne du Seigneur, et au temple du Dieu de Jacob. On nous en montrera le chemin, et nous cheminerons en ses sentiers; car de Sion sortira la loi, et de Jérusalem la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 3, 'Et il jugera entre beaucoup de peuples, et il châtiera, même au loin, des nations puissantes; et chez elles on forgera les glaives pour en faire des socs de charrue, et des javelines pour en faire des faux; de nation à nation, on ne s’attaquera plus par l’épée, on n’apprendra plus à combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 4, 'Et chacun se reposera sous sa vigne et sous son figuier; et nul ne leur inspirera de crainte, parce que le Seigneur tout-puissant l’a dit de sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 5, 'Tous les peuples alors suivront chacun sa voie; mais nous, nous marcherons au nom du Seigneur, notre Dieu, dans tous les siècles et au delà.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 6, 'En ce jour, dit le Seigneur, je réunirai celle qui a le cœur contrit et celle que j’avais repoussée, et j’accueillerai ceux que j’avais chassés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 7, 'Et je mettrai en réserve celle qui a eu le cœur contrit; et je ferai une nation puissante de celle que j’avais repoussée; et le Seigneur règnera sur elles en la montagne de Sion, depuis ce moment jusqu’à la fin des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 8, 'Et toi, vieille tour du troupeau, Sion, ma fille, la principauté te reviendra et rentrera dans tes murs; et le premier royaume de Babylone reviendra à ma fille Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 9, 'Et maintenant pourquoi as - tu connu le malheur? n’avais-tu pas un roi? Ou ta raison avait-elle péri pour que tu aies senti les douleurs de l’enfantement?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 10, 'Souffre et prends courage, et approche, Sion, ma fille; souffre comme une femme qui enfante; car bientôt tu sortiras de tes murs, tu dresseras tes tentes dans la plaine, et tu iras jusqu’à Babylone; puis le Seigneur ton Dieu t’en délivrera, et il te tirera des mains de tes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 11, 'Et maintenant, contre toi maintes nations se sont rassemblées, elles disaient: Réjouissons-nous, et que nos yeux surveillent Sion!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 12, 'Mais elles ne savaient pas la pensée du Seigneur; elles n’avaient point compris ses conseils; car il les avait rassemblées comme des gerbes dans une aire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 13, 'Lève-toi, Sion, ma fille, tombe sur elles comme le fléau; je te donnerai des cornes de fer; je te couvrirai d’armes d’airain, et tu briseras maintes nations, et tu consacreras leurs grains nombreux au Seigneur, et leurs richesses au Seigneur de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 1, 'Maintenant la fille sera investie; le Seigneur a ordonné que nous fussions assiégés, et l’on battra de verges les joues des tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 2, 'Et toi, Bethlehem, maison d’Éphratha, toi si petite parmi les milliers des fils de Juda, de toi me sortira un rejeton pour être prince d’Israël, et ses origines existent depuis le commencement, de toute éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 3, 'À cause de cela, le Seigneur les fera attendre jusqu’au temps de celle qui doit enfanter; elle enfantera, et les restes de leurs frères reviendront aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 4, 'Et le Seigneur s’arrêtera, et il surveillera, et il fera paître son troupeau dans sa force, et ils demeureront dans la gloire du Seigneur leur Dieu. Car alors ils seront glorifiés jusqu’aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 5, 'Et ce sera la paix, quand Assur aura envahi votre terre et marché sur vos champs; ensuite sept pasteurs et huit morsures d’hommes seront suscités contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 6, 'Et ils gouverneront Assur par le glaive, et la terre de Nebrod par des retranchements; et le Seigneur vous délivrera d’Assur, après que celui-ci aura envahi votre territoire, et marché sur vos frontières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 7, 'Et les restes de Jacob seront parmi les gentils au milieu de maintes nations comme la rosée qui tombe envoyée par le Seigneur, et comme des agneaux dans un pré, afin que nuls ne se rassemblent parmi les fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 8, 'Et les restes de Jacob seront, parmi les gentils, au milieu de maintes nations, comme un lion dans une forêt avec du bétail, et comme un lionceau avec un troupeau de brebis. Partout où il passe, il déchire et ravit, et nul n’est capable de le détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 9, 'Ta main se lèvera sur ceux qui t’oppriment, et tous tes ennemis seront exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 10, 'Et en ce jour voici ce qui arrivera, dit le Seigneur: Je ferai périr tes chevaux au milieu de toi, et je briserai tes chars;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 11, 'Je raserai les villes de ta terre, et je détruirai tes forteresses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 12, 'J’ôterai de ta main les sortilèges, et il n’y aura plus de devins avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 13, 'J’anéantirai tes statues et tes colonnes, et tu n’adoreras plus les œuvres de tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 14, 'Je déracinerai les bois sacrés du milieu de tes champs, et j’effacerai tes cités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 5, 15, 'Et dans les transports de ma colère je tirerai vengeance des gentils, parce qu’ils ne m’auront point entendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 1, 'Écoutez donc la parole: Le Seigneur, le Seigneur a dit: Lève-toi, annonce le jugement aux montagnes, et que les collines entendent ta voix!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 2, 'Écoutez, montagnes, le jugement du Seigneur, et vous aussi, vallées, fondements de la terre; car le Seigneur vient en jugement devant son peuple, et il plaidera avec Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 3, 'Mon peuple, que t’ai-je fait? En quoi t’ai-je contristé? En quoi t’ai-je déplu? Réponds-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 4, 'Est-ce parce que je t’ai fait sortir de la terre d’Égypte, que je t’ai affranchi de la maison de servitude, et que j’ai envoyé devant toi Moïse, Aaron et Marie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 5, 'Mon peuple, souviens-toi donc de ce qu’a médité contre toi Balac, roi de Moab, et de la réponse que lui a rapportée Balaam, fils de Béor, depuis Sétim jusqu’à Galgala, afin que l’on connût la justice du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 6, 'Comment prendrai-je le Seigneur? Comment serai-je agréable à mon Dieu très-haut? Le prendrai-je par des holocaustes, par des veaux d’un an?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 7, 'Le Seigneur accueillera-t-il des milliers de béliers, des myriades de chèvres grasses? Donnerai-je, pour mes impiétés, les premiers - nés de mes troupeaux, et, pour les péchés de mon âme, le fruit de mes entrailles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 8, 'O homme, faut-il te dire ce qui est bon? Est-ce que le Seigneur demande de toi quelque chose, sinon que tu pratiques la justice, que tu aimes la miséricorde, et que tu sois prêt à cheminer avec le Seigneur ton Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 9, 'La voix du Seigneur sera invoquée dans la ville, et sauvera ceux qui craignent son nom. Écoute, tribu: Qui donc mettra l’ordre en ta cité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 10, 'Est-ce le feu? Est-ce la maison de l’impie amassant des trésors iniques, avec une insolente impiété?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 11, 'Sera-t-il absous, l’homme injuste avec ses fausses balances et ses faux poids en un sac?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 12, 'Car c’est ainsi que ceux qui demeurent dans la ville ont amassé leurs richesses impies; et ils ne disent que des mensonges, et dans leur bouche leur langue s’est enorgueillie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 13, 'Et moi je commencerai par te frapper, et je t’effacerai à cause de tes crimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 14, 'Tu mangeras, et ne seras point rassasié, et il y aura sur toi des ténèbres; et le Seigneur se détournera; tu ne seras point, sauvée; et ceux qui échapperont seront livrés au glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 15, 'Tu sèmeras et ne moissonneras pas; tu pressureras l’olive, et tu ne seras pas oint de son huile; tu pressureras la grappe, et tu n’en boiras pas le vin; et les lois de mon peuple seront abolies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 6, 16, 'Car tu as gardé les ordonnances de Zambri, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 1, 'Malheur à moi! me voilà comme celui qui ramasse du chaume en la moisson, ou qui cueille un grappillon de la vendange, n’ayant pas à lui une seule grappe pour en manger les prémices; malheur à mon âme!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 2, 'Car le juste a péri sur la terre; et parmi les hommes il n’en est pas qui marche droit. Tous sont en justice pour avoir versé le sang; et chacun d’eux accable son prochain sous l’oppression.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 3, 'Et leurs mains sont prêtes à faire le mal. Le prince exige; le juge dit des paroles douces; et voici le désir de son âme: Je prendrai leurs biens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 4, 'Comme le ver qui ronge, marchant décemment au jour de la visite. Malheur! Vos vengeances, Seigneur, sont venues, et maintenant vont venir leurs lamentations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 5, 'Ne vous fiez pas à vos amis, n’espérez pas en vos princes; garde-toi même de ton épouse, et ne lui confie quoi que ce soit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 6, 'Car le fils outragera le père; la fille se révoltera contre sa mère, la bru contre sa belle-mère; l’homme aura pour ennemis tous ceux de sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 7, 'Pour moi, je regarderai le Seigneur; j’attendrai le Dieu mon Sauveur, et mon Dieu m’exaucera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 8, 'Ne m’insulte pas, ô mon ennemie, parçe que je suis tombée, je me relèverai; car, si je suis à terre dans les ténèbres, le Seigneur m’éclairera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 9, 'Parce que j’ai péché contre le Seigneur, je supporterai sa colère jusqu’à ce qu’il ait reconnu juste ma cause. Et alors il me rendra justice, et il me ramènera à la lumière, et je verrai son équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 10, 'Et mon ennemie verra cela; et elle sera couverte de honte, celle qui dit maintenant: Où est le Seigneur ton Dieu? Mes yeux la regarderont alors, et elle sera foulée aux pieds comme la boue des rues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 11, 'Voici le jour où l’on enduit la brique; ce jour sera celui de ta destruction, et ce jour-là tes lois seront effacées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 12, 'Et tes villes seront mises au niveau du sol; elles seront partagées entre les Assyriens; et tes forteresses seront partagées, depuis Tyr jusqu’au fleuve, d’une mer à l’autre, et d’une montagne à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 13, 'Et ta terre et tous ceux qui l’habitent seront désolés, à cause des fruits de leur convoitise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 14, 'Votre verge à la main, Seigneur, paissez les brebis de votre héritage, qui d’elles-mêmes se sont abritées dans la forêt du Carmel. Elles trouveront leur pâture en Basan et Galaad, comme aux jours d’autrefois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 15, 'Comme aux jours où vous nous avez fait sortir d’Égypte. Vous verrez des prodiges;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 16, 'Et les gentils les verront aussi, et ils en seront confondus malgré toute leur puissance, ils se mettront la main sur la bouche, et leurs oreilles n’entendront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 17, 'Ils lécheront la terre comme les serpents qui rampent dans la poussière; ils seront pleins de trouble dans l’enceinte de leurs remparts; ils seront hors d’eux-mêmes, à cause du Seigneur notre Dieu, et ils auront peur de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 18, 'Qui donc est Dieu comme vous, qui ôtez les péchés, et passez sous silence les impiétés de ce qui reste de votre héritage! Le Seigneur n’a point maintenu le témoignage de sa colère; il se complaît en sa miséricorde;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 19, 'Il reviendra; il aura compassion de nous; il submergera nos iniquités; il jettera nos péchés au fond de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 7, 20, 'Il fera ses dons à Jacob, en vérité; il sera miséricordieux envers Abraham, comme il l’a juré à nos pères aux jours d’autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Parole du Seigneur qui vint à Joël, fils de Bathuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Écoutez ce que je vais dire, vieillards; prêtez l’oreille, vous tous qui habitez la terre: Est-il rien arrivé de pareil, soit de nos jours, soit du temps de nos pères?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Plus que vos pères, vous aurez à raconter à vos enfants, et plus encore vos enfants à leurs enfants, et ceuxci plus encore à la génération suivante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'La sauterelle a dévoré ce qu’avait laissé la chenille; la grosse sauterelle a dévoré ce qu’avait laissé la sauterelle; la nielle a dévoré ce qu’avait laissé la grosse sauterelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Réveillez-vous, ô vous qui vous enivrez de votre vin, et pleurez. Lamentez-vous, ô vous qui buvez du vin jusqu’à l’ivresse; car la gaieté et la joie sont ôtées de vos lèvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Une nation puissante et innombrable est montée sur ma terre; ses dents sont des dents de lion, et ses mâchoires des mâchoires de lionceau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Elle a rasé ma vigne, elle a brisé mon figuier, elle a cherché ma vigne et l’a tout arrachée; elle a pelé les rameaux de mon figuier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Pleurez avec moi, plus que la jeune femme ceinte d’un cilice ne pleure l’époux de sa virginité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'La victime et les libations ont été enlevées du temple du Seigneur; pleurez, prêtres, qui serviez l’autel du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Car les champs sont désolés. Que la terre soit en deuil, car le blé manque, les sources du vin sont desséchées, l’olivier est stérile,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Les laboureurs sont épuisés. Pleurez vos richesses, votre froment, votre orge; car dans les champs la récolte a péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'La vigne a été desséchée, les figuiers ont perdu leur fertilité; le grenadier, le palmier, le pommier, tous les arbres fruitiers de la campagne sont morts, parce que les fils des hommes sont confondus dans leur joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Prêtres, ceignez-vous, frappez-vous la poitrine; pleurez, vous qui servez à l’autel. Entrez et dormez avec vos cilices, ministres de Dieu, parce que les victimes et les libations sont ravies au temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Sanctifiez le jeûne, proclamez le service du Seigneur; rassemblez dans le temple de notre Dieu les anciens de tout le peuple de la terre, et criez sans relâche au Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Malheur, malheur, malheur sur ce jour! Car le jour du Seigneur approche, et il viendra comme une calamité naissant d’une calamité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 16, 'Sous vos yeux, votre subsistance a été détruite; et les réjouissances et la joie ont disparu du temple de votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 17, 'Les génisses ont bondi devant leurs crèches vides; les trésors de vos granges sont dissipés; les pressoirs sont détruits; les froments desséchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 18, 'Que mettrons-nous en réserve pour nous? Les bœufs du troupeau ont mugi, parce qu’ils n’avaient plus de pâturage, et les petits des agneaux ont entièrement péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 19, 'Je crierai vers vous, Seigneur; car le feu a consumé les beautés du désert, et la flamme tous les arbres des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 20, 'Et les bêtes de la plaine ont tourné les yeux vers vous, parce que les cours d’eau étaient à sec, et que le feu a dévoré les beautés du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Sonnez de la trompette du haut de Sion, publiez à grands cris sur la montagne sainte; et que tous ceux qui habitent la terre soient confondus, parce que voilà lẻ jour du Seigneur; il est près de vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Ce jour d’obscurité et de ténèbres, ce jour de nuées et de brouillards. Un peuple nombreux et puissant va se répandre sur les montagnes, comme la lumière du matin; jamais, dans les temps passés, on n’a vu son pareil, et après lui on n’en verra point de semblable durant les années, de générations en générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Ce qui marche devant lui est un feu dévorant; ce qui marche à sa suite est une flamme ardente. La terre, avant qu’il arrive, était comme un jardin de délices; quand il fut passé, c’était un champ désert, et nul ne lui échappera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Ils apparaîtront comme une vision de chevaux; ils courront comme des cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Ils s’élanceront sur les cimes des montagnes, comme un bruit de chars, comme un bruit de flammes dévorant des maisons, comme un peuple puissant et nombreux se rangeant en bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Devant leur force, les peuples seront broyés; tout visage sera comme le côté brûlé d’une chaudière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Ils courront comme des combattants; ils escaladeront les murailles comme des hommes de guerre; et chacun d’eux marchera dans sa voie, et ils ne dévieront pas de leurs sentiers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Et nul ne s’écartera de son frère; ils marcheront chargés de leurs armes; ils tomberont avec leurs traits, et ils ne seront pas détruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Ils prendront la ville; ils courront sur les remparts; ils monteront sur les maisons; ils entreront comme des larrons par les fenêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Devant leur face, la terre sera confondue, et le ciel tremblera. Le soleil et la lune seront voilés de ténèbres, et les étoiles retireront leur lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Et le Seigneur fera entendre sa voix devant son armée, car son camp est très-nombreux, et les œuvres qui accomplissent ses paroles sont puissantes, et le jour du Seigneur est un grand jour: il est éclatant; et qui sera capable de le soutenir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Et maintenant le Seigneur Dieu vous dit: Convertissez-vous à moi de toute votre âme; jeûnez, pleurez, frappez-vous la poitrine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Déchirez vos cœurs, et non vos vêtements. Et convertissez-vous au Seigneur votre Dieu, parce qu’il est plein de clémence et de compassion, patient, abondant en miséricorde, et repentant des maux qu’il fait en punissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Qui sait s’il ne se repentira pas, s’il ne laissera pas après lui des bénédictions, des offrandes et des libations pour le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Sonnez de la trompette en Sion; sanctifiez le jeûne; publiez le service de Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Réunissez le peuple; sanctifiez l’Église; rassemblez les anciens; rassemblez les enfants à la mamelle; que l’époux quitte sa couche, et la femme son lit nuptial.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Que les prêtres qui servent le Seigneur pleurent au pied de l’autel; qu’ils disent: Seigneur, épargnez votre peuple; ne livrez pas votre héritage à l’opprobre; ne laissez pas les gentils dominer sur lui, de peur que l’on ne dise parmi les nations: Où est leur Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Mais le Seigneur a été jaloux de sa terre, et il a épargné son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Et le Seigneur a parlé, et il a dit à son peuple: Voilà que je vous enverrai du blé, du vin et de l’huile, et vous vous en rassasierez, et je ne vous livrerai pas plus longtemps aux opprobres des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Et je chasserai loin de vous celui qui est venu de l’aquilon; je le repousserai dans une contrée aride, et je ferai disparaître sa tête dans la première mer, et sa queue dans la dernière; et sa pourriture montera, et son infection s’élèvera; car il s’est glorifié de ses œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Rassure-toi, terre; réjouis-toi et tressaille d’allégresse, parce que le Seigneur se glorifie d’agir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Rassurez-vous, bêtes des champs, les plaines du désert ont bourgeonné; les arbres ont porté leurs fruits; le figuier et la vigne ont donné toute leur force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Et vous, enfants de Sion, réjouissez-vous, tressaillez d’allégresse dans le Seigneur votre Dieu; il vous a donné abondance de vivres; il fera pleuvoir pour vous, comme autrefois, les pluies du printemps et de l’automne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 24, 'Et vos granges seront remplies de blé; et vos pressoirs regorgeront de vin et d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 26, 'Et vous mangerez, et vous serez rassasiés, et vous louerez le nom du Seigneur votre Dieu, à cause des prodiges qu’en votre faveur il aura faits. Et mon peuple ne sera plus humilié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 27, 'Et vous connaîtrez que je suis au milieu d’Israël, et que je suis le Seigneur votre Dieu, et qu’il n’est point d’autre Dieu que moi, et mon peuple ne sera plus humilié à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 28, 'Et ensuite, voici ce qui arrivera Je répandrai mon esprit sur toute chair; et vos fils prophétiseront, et vos anciens auront des songes, et vos jeunes hommes des visions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 29, 'Et en ce jour-là je répandrai mon esprit sur mes serviteurs et sur mes servantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 30, 'Et je mettrai des signes au ciel; et sur la terre, du sang, du feu et de la fumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 31, 'Le soleil sera changé en ténèbres, et la lune en sang, avant qu’arrive le grand jour, le jour éclatant du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 32, 'Et il arrivera que quiconque invoquera le nom du Seigneur sera sauvé; car alors sera sauvé tout ce qui sera sur la montagne de Sion et de Jérusalem, et avec eux tous les évangélisés que le Seigneur a élus, comme l’a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 1, 'Car voici qu’en ce temps, et en ces jours-là, quand j’aurai fait revenir de la captivité Juda et Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 2, 'J’assemblerai toutes les nations et les conduirai dans la vallée de Josaphat; là je plaiderai avec elles pour mon peuple et pour Israël, mon héritage: car elles l’ont dispersé parmi les Gentils, qui se sont partagé ma terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 3, 'Et ils ont tiré mon peuple au sort, et ils ont livré des enfants à la prostitution, et ils ont vendu des jeunes filles pour du vin, et ils ont bu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 4, 'Or, qu’y a-t-il entre vous et moi, Tyr, Sidon, Galilée des Philistins? Est-ce que vous pourrez user de représailles avec moi? Ou me garderez-vous rancune en votre cœur? Je vous rétribuerai, moi, vite et sévèrement, sur vos têtes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 5, 'Parce que vous avez pris mon argent et mon or; parce que vous avez porté dans vos temples mes ornements précieux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 6, 'Parce que vous avez vendu aux fils des Grecs les fils de Juda et les fils de Jérusalem, pour les chasser de leurs frontières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 7, 'Mais voilà que je les ramènerai des contrées où vous les avez conduits, et je vous rétribuerai sur vos têtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 8, 'Et je donnerai vos fils et vos filles aux fils de Juda, pour qu’ils les vendent comme captifs chez une nation lointaine; ainsi a parlé le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 9, 'Publiez ces choses parmi les Gentils; sanctifiez la guerre; excitez les combattants, vous tous hommes exercés aux armes; rassemblez-vous, et partez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 10, 'Forgez des glaives avec vos socs de charrue, et, avec vos faux, des javelines. Que le faible lui-même dise: Je suis fort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 11, 'Venez toutes ensemble et entrez, vous nations d’alentour; vous, fils d’Israël, réunissez-vous là: que l’homme pacifique devienne un guerrier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 12, 'Que toutes les nations se lèvent; qu’elles se rendent dans la vallée de Josaphat; c’est là que je siége pour juger les nations d’alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 13, 'Envoyez des faucilles, car le vendangeur est prêt; entrez et foulez aux pieds les grappes, car le pressoir est plein; laissez déborder les cuves, car leur méchanceté a comblé la mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 14, 'Les échos ont retenti dans la vallée du jugement; car le jour du Seigneur est proche dans la vallée du jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 15, 'Le soleil et la terre seront enveloppés de ténèbres, et les étoiles retireront leur lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 16, 'Le Seigneur jettera de grands cris du haut de Sion; il fera entendre sa voix du haut de Jérusalem; le ciel et la terre trembleront; mais le Seigneur épargnera son peuple, et il fortifiera les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 17, 'Et vous reconnaîtrez que je suis le Seigneur votre Dieu, qui réside en Sion, sur la montagne sainte; et Jérusalem sera sainte, et les étrangers n’y passeront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 18, 'Et il arrivera qu’en ce jour-là les montagnes ruisselleront de douceur, et les collines de lait; et l’eau coulera de toutes les sources de Juda, et une fontaine jaillira de la maison du Seigneur, et elle abreuvera le val de Sétim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 19, 'L’Égypte sera mise à néant; l’Idumée sera un champ de désolation, à cause des iniquités de ses fils contre Juda, parce qu’ils ont versé le sang innocent sur leur terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 20, 'Et la Judée sera habitée dans tous les siècles, et Jérusalem dans les générations des générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 21, 'Et je rechercherai leur sang, et je n’absoudrai point ceux qui l’ont versé, et le Seigneur aura son tabernacle en Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 1, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 2, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Vision d’Abdias. Voici ce que le Seigneur Dieu dit à l’Idumée: J’ai entendu la parole du Seigneur, et il a envoyé un message aux gentils, disant: Levez-vous, et allons combattre Édom!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Voilà que je t’ai réduit à un petit nombre parmi les peuples; et tu es maintenant sans honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'L’orgueil de ton cœur t’avait enivré, toi qui résides dans les trous des rochers; élevant ta demeure sur les hauts lieux, tu disais: Qui me fera descendre à terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Quand même tu te serais élevé autant que l’aigle, quand tu aurais placé ton nid au milieu des étoiles, je t’en précipiterais, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Si des larrons ou des voleurs de nuit étaient entrés chez toi, à quel point t’auraient-ils abattu? N’auraient-ils pas seulement enlevé ce qui leur eût convenu? Et si des vendangeurs étaient entrés en ta vigne, ne t’auraient-ils pas laissé au moins un grappillon?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Comment Ésau a-t-il été fouillé, et comment lui a-t-on pris ce qu’il cachait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Ils t’ont chassé jusqu’à tes extrêmes limites; tous tes alliés sont devenus tes ennemis; des hommes pacifiques avec qui tu vivais en paix ont prévalu contre toi; ils ont placé des piéges sous tes pas; mais Édom est sans intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Ce jour-là, dit le Seigneur, je détruirai les sages de l’Idumée, et je bannirai l’intelligence des montagnes d’Ésau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Et tes guerriers de Théman trembleront de peur, afin que tout homme soit exterminé sur le mont d’Ésau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'A cause de tes meurtres, et de tes péchés contre ton frère Jacob, tu seras couvert de confusion, et tu seras effacé pour jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Du jour où tu t’es levé contre lui, quand des peuples étrangers emmenèrent son armée captive, quand ils franchirent ses portes, et tirèrent au sort les richesses de Jérusalem, dès lors tu fus comme l’un d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Ne méprise pas la chute de ton frère au jour des étrangers: ne te raille pas des fils de Juda au jour de leur ruine; ne te gonfle pas d’orgueil au jour de leur angoisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'N’entre point par les portes de mon peuple au jour de ses souffrances; ne surveille pas sa Synagogue au jour de sa destruction; n’attaque pas son armée le jour où ils périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Ne te tiens pas sur leur chemin pour massacrer ceux qui se sont échappés; n’enferme pas leurs fuyards au jour de la désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Car le jour du Seigneur est proche pour toutes les nations; comme tu as fait à autrui, il te sera fait à toimême; ta rétribution retombera sur ta tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Car de même que tu auras bu sur ma montagne sainte, ainsi toutes les nations boiront le vin de ma colère; elles boiront, et elles tomberont, et elles seront comme ceux qui ne sont plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Et le salut sera en la montagne de Sion, et elle sera sainte, et la maison de Jacob possèdera ceux qui l’auront possédée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Et la maison de Jacob sera un feu, et la maison de Joseph une flamme; et la maison d’Ésau sera comme un chaume; et ceux d’Israël porteront chez elle l’incendie, et ils la dévoreront; et il n’y aura plus un champ qui porte du blé, en la maison d’Ésau; car le Seigneur a parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Et ceux de Nageb auront pour héritage la montagne d’Ésau, et ceux de Sephéla le pays des Philistins; et ils auront aussi pour héritage la montagne d’Éphraïm, et la plaine de Samarie, et Benjamin et Galaad.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Et voici le domaine des fils d’lsraël qui reviendront de la captivité: la terre des Chananéens jusqu’à Sarepta; ceux de Jérusalem possèderont jusqu’à Éphratha; ils auront les cités de Nageb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Et ceux de la montagne de Sion qui auront été sauvés monteront pour punir la montagne d’Ésau; et alors arrivera le règne du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Et la parole du Seigneur vint à Jonas, fils d’Amathi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Lève-toi, et pars pour Ninive, la grande ville, et proclame dans ses murs que le cri de sa méchanceté est monté jusqu’à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Et Jonas se leva pour s’enfuir à Tharsis, loin de la face du Seigneur; et il descendit à Joppé; il y trouva une barque allant à Tharsis, et il paya son passage, et il s’embarqua pour naviguer avec les matelots, jusqu’à Tharsis, loin de la face du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Et le Seigneur excita un grand vent sur la mer, et les vagues s’élevèrent, et la barque fut en danger de se rompre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Et les matelots eurent crainte, et ils crièrent chacun vers son dieu, et ils lancèrent à la mer le chargement de la barque, pour s’en alléger. Jonas descendit à fond de cale, et là il s’endormit, et il ronfla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Et le pilote l’alla trouver, et il lui dit: Pourquoi ronfles-tu? Lève-toi, et invoque ton Dieu, afin que Dieu nous sauve, et que nous ne mourions pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Et chacun des matelots dit à son voisin: Allons, agitons les sorts, et sachons par qui ce malheur nous arrive. Et ils agitèrent des sorts, et le sort tomba sur Jonas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Et ils lui dirent: Déclare-nous quel est ton métier; d’où viens-tu? de quelle contrée, de quel peuple es-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Et il leur dit: Je suis un serviteur du Seigneur; j’adore le Seigneur Dieu du ciel, qui a créé la mer et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Et ces hommes eurent grande crainte, et ils lui dirent Pourquoi as-tu fait cela? Car ces hommes connurent qu’il fuyait loin de la face du Seigneur; car il le leur avait déclaré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Et ils lui dirent: Que te ferons-nous, afin que pour nous la mer se calme? Car la mer allait, et soulevait encore plus de vagues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Et Jonas leur dit: Prenez-moi et jetez-moi à la mer, et la mer se calmera pour vous; car je sais que c’est à cause de moi qu’il y a contre vous ces grandes vagues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Et ces hommes s’efforcèrent de retourner à la côte; mais ils ne le purent, parce que la mer allait et soulevait contre eux toujours plus de vagues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Et ils crièrent au Seigneur, et ils dirent: Non, Seigneur, que nous ne périssions pas pour la vie de cet homme; ne faites pas retomber sur nous un sang innocent; car, Seigneur, vous avez fait selon votre volonté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 15, 'Et ils prirent Jonas, et ils le lancèrent à la mer; et la mer cessa de s’agiter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 16, 'Et ces hommes eurent grande crainte du Seigneur; et ils offrirent au Seigneur un sacrifice, et ils lui firent des vœux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Et le Seigneur prescrivit à une grande baleine d’avaler Jonas, et Jonas fut dans le ventre de la baleine trois jours et trois nuits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Et Jonas pria le Seigneur son Dieu, dans le ventre de la baleine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Et il dit: J’ai crié dans mà tribulation au Seigneur mon Dieu, et il m’a exaucé; mon cri est parti des entrailles de l’enfer, et vous avez écouté ma voix;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Vous m’avez précipité au plus profond du cœur de la mer; et les fleuves m’ont enveloppé, et toutes vos grandes vagues, tous vos flots ont passé sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Et j’ai dit: C’est moi qui me suis éloigné de vos yeux; me permettrez-vous de voir encore votre saint temple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'L’eau s’est répandue autour de moi, jusqu’à l’âme; l’abîme le plus profond m’a enclos, et ma tête a plongé');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Jusqu’aux racines des monts; je suis descendu sous la terre, dont les verrous sont des barrières éternelles. Seigneur mon Dieu, que la destruction de ma vie remonte à la surface des flots.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'En la défaillance de mon âme, je me suis souvenu de vous, Seigneur; que ma prière arrive à vous dans votre saint temple!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Ceux-là seuls qui s’attachent aux vanités et aux mensonges ont renoncé à votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Pour moi, je vous offrirai dans mes chants un');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Et le Seigneur donna ordre à la baleine, et elle rejeta Jonas sur la terre ferme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Et la parole du Seigneur vint à Jonas pour la seconde fois, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Lève-toi, et pars pour Ninive, la grande ville, et proclame dans ses murs la prédiction que je t’ai déjà prescrit de proclamer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Et Jonas se leva; et il s’en alla à Ninive, comme lui avait dit le Seigneur. Or la ville de Ninive était grande de trois jours de marche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Et Jonas commença par entrer dans la ville et par faire environ un jour de marche, et il cria, et il dit: Encore trois jours, et Ninive sera détruite!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Et les hommes de Ninive crurent en Dieu, et ils proclamèrent un jeûne, et ils se ceignirent de cilices, depuis le grand jusqu’au petit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Et la parole de Jonas arriva au roi de Ninive, et il se leva de son trône, et il ôta sa robe, et il se ceignit d’un cilice, et il s’assit sur la cendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Et il fut proclamé, et il fut dit en Ninive de la part du roi et de la part de ses grands, ce qui suit: Que ni hommes, ni bêtes, ni bœufs, ni brebis ne mangent, ne paissent, ne boivent même de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Et les hommes et les bêtes furent couverts de cilices, et les hommes crièrent sans relâche au Seigneur. Et chacun revint de sa voie coupable et de l’iniquité de ses mains, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Qui sait si le Seigneur ne se repentira pas, et s’il ne calmera pas les transports de sa colère, pour que nous ne périssions point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Et Dieu vit leurs œuvres; il vit qu’ils revenaient de leurs voies coupables; et Dieu se repentit du mal qu’il avait voulu leur faire, et il ne le leur fit pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Et Jonas fut affligé d’une grande tristesse, et il fut confondu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Et il pria le Seigneur, et il dit: Seigneur, n’est-ce pas là ce que je disais, quand j’étais encore en mon pays? Je m’étais hâté de fuir à Tharsis, parce que je vous sais plein de clémence et de compassion, patient et abondant en miséricorde, et que vous vous repentez du mal que vous vouliez faire aux hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Maintenant donc, Seigneur mon maître, prenez-moi ma vie; car il vaut mieux pour moi mourir que vivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Et le Seigneur dit à Jonas: Pourquoi es-tu si vivement contristé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Et Jonas sortit de Ninive, et il s’assit en face de la ville, et là il se fit une tente et il s’y établit, jusqu’à ce qu’il eut vu de loin ce qui arriverait à la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Et le Seigneur Dieu donna ordre à une gourde, et sa tige et ses feuilles montèrent au-dessus de la tête de Jonas pour l’ombrager et le préserver de tout mal. Et Jonas eut une grande joie de cette gourde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 7, 'Et Dieu donna ordre dès l’aurore à un ver qui rongea la gourde, et elle se dessécha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 8, 'Et il arriva, aux premiers rayons du soleil, que Dieu donna ordre à un vent chaud et ardent, et le soleil frappa sur la tête de Jonas, et celui-ci défaillit, et il désespéra de sa vie, et il dit: Mieux vaut pour moi mourir que vivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 9, 'Et le Seigneur dit à Jonas: Est-ce à cause de la gourde que tu es si fortement contristé? Et il répondit: Je suis triste jusqu’à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 10, 'Et le Seigneur dit: Tu as grande pitié pour une gourde qui ne t’avait donné aucune peine, que tu n’avais point cultivée, qui était venue en une nuit, et qui en une nuit a été détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 11, 'Et moi, je n’épargnerai pas Ninive la grande ville, où demeurent plus de douze myriades d’hommes, qui ne savent pas distinguer leur main droite de leur main gauche; et des troupeaux si nombreux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Prédiction à Ninive, livre de la vision de Nahum, Elcéséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Dieu est jaloux, le Seigneur se venge, le Seigneur se venge avec colère, le Seigneur tire vengeance de ceux qui lui sont opposés; il extermine ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Le Seigneur est longanime, sa force est grande; mais le Seigneur ne laissera pas impuni celui qu’il n’a pas encore puni; sa voie est dans la destruction et les ébranlements; et les nuages sont la poussière de ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'C’est lui qui menace la mer et qui la dessèche; c’est lui qui change en désert tous les fleuves. Basan et le Carmel ont défailli, et les fleurs du Liban se sont fanées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Par lui, les montagnes ont tressailli et les collines ont tremblé; devant sa face toute la terre a reculé, et ceux qui l’habitent:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Qui soutiendra le regard de sa fureur? Qui résistera aux transports de son courroux? sa colère ronge les fondations; les rochers se fendent devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Le Seigneur est doux pour ceux qui l’attendent au jour de la tribulation; il connaît ceux qui le révèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Il détruira votre voie par une inondation; les ténèbres poursuivront ceux qui se lèvent contre lui et le haïssent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Pourquoi vos pensées sont-elles contre le Seigneur? Lui seul mène toutes choses à leur fin; il ne s’y prendra pas à deux fois pour vous briser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Et celui-là sera dévasté jusqu’aux fondations, il sera dévoré par la flamme comme l’if aux rameaux entrelacés, comme le chaume tout à fait desséché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'De toi, ô Ninive, sortira contre le Seigneur une pensée méchante et ennemie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Or voici ce que dit le Seigneur, souverain maître des grandes eaux. Ils seront séparés pareillement, et l’on n’entendra plus parler de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Et maintenant, mon peuple, je vais briser loin de toi sa verge, et rompre tes liens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Voici ce que sur toi, Ninive, a prescrit le Seigneur Ta renommée ne sera plus semée au loin; je détruirai dans le temple de ton dieu les images sculptées ou jetées en fonte; je vais comme en courant préparer ton sépulcre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Voici sur les montagnes les pieds de Celui qui apporte la bonne nouvelle et qui annonce la paix. Juda, célèbre tes fêtes, accomplis tes vœux, car tes ennemis ne passeront plus sur ta terre, encouragés par ta décrépitude. Tout est fini pour eux, ils ont été retranchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Il est monté celui qui délivre de l’affliction, te soufflant au visage. Observe la voie; ceins-toi les reins; agis en homme selon ta force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Le Seigneur a détourné l’outrage fait à Jacob, ainsi que l’outrage fait à Israël; car les envahisseurs les ont arrachés, et ils ont détruit leurs plantations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Ils ont détruit les armes qui les rendaient puissants parmi les hommes, et leurs vaillants qui se jouaient de la flamme; mais au jour de sa venue, les rênes de leurs chars et leurs cavaliers seront en désordre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Dans les rues, les chars s’entre-choqueront; ils s’embarrasseront les uns les autres au milieu des places. Leur aspect sera comme des lampes de feu, ou des éclairs sillonnant la nue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Et leurs grands se souviendront alors, et ils fuiront le jour, et ils défailleront en leur chemin, et ils se hâteront de courir à leurs remparts, et ils y placeront des sentinelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Mais les portes des villes ont été forcées, et les palais du roi ont croulé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Et les fondations en ont été mises à découvert, et n’ont plus été qu’un monceau de ruines, et les femmes ont été emmenées comme des colombes, gémissant en leurs cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Et les eaux de Ninive ont été comme un étang plein d’eau, et ses habitants ont fui, et ils ne s’y sont pas arrêtés, et pas un n’a regardé en arrière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Les vainqueurs ont pillé l’argent, ils ont pillé l’or;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Ce n’est partout que coups et contre-coups, tumulte et brisement du cœur, défaillance des genoux et violentes douleurs de reins; toute face est comme le fond noir d’une chaudière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Où est le repaire des lions, et le pâturage des lionceaux? Où est allé le lion pour que le lionceau y entre avec lui? et n’y avait-il personne pour les effrayer?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Le lion ravissait ce qui convenait à ses lionceaux, et pour eux il multipliait les meurtres; il remplissait de gibier son antre, et de rapines son repaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Voilà que je viens à toi, dit le Seigneur tout-puissant, et je brûlerai au milieu de la fumée ton peuple nombreux, et le glaive dévorera tes lions, et je détruirai sur la terre le fruit de tes rapines, et l’on n’entendra plus parler de tes œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Ô ville de sang, toute pleine de mensonges et d’iniquités, tes rapines ne s’amoncelleront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Voilà le bruit des fouets, le bruit des roues ébranlées, des chevaux lancés, des chars frémissants et des cavaliers en marche;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Voilà le glaive étincelant, l’armure brillante de la multitude des blessés, et une ruine profonde. Et ses peuples étaient sans nombre, mais ils ont énervé leurs corps dans la multitude de leurs prostitutions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Courtisane belle et gracieuse, reine des enchantements, tu vendais les peuples par tes débauches, et les nations par tes sortiléges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Et voilà que je m’attaque à toi, dit le Seigneur Dieu tout puissant; je dévoilerai tes nudités à tous les yeux, je montrerai aux nations ta honte, et aux royaumes ton opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Et je ferai retomber sur toi l’abomination que méritent tes impuretés, et je ferai de toi un exemple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Et il arrivera que tout homme, en te voyant, s’éloignera de toi, disant: Malheureuse Ninive, qui se lamentera sur elle? où chercher pour elle une consolation?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Prépare ta partie, ajuste tes cordes, prépare ta partie pour Ammon, qui demeure au milieu des fleuves; les flots l’entourent; la mer est son empire, et l’eau lui sert de remparts,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Et l’Éthiopie est sa force, et aussi l’Égypte; et pourtant il n’y aura pas de terme à sa fuite. En vain les Libyens sont ses auxiliaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Elle-même sera transportée captive, et ses enfants seront écrasés à terre, à l’entrée de toutes les rues, et l’on se partagera au sort toutes les richesses qui faisaient sa gloire; et tous ses grands auront les mains chargées de chaînes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Et toi, tu seras enivrée, et tu seras méprisée, et tu solliciteras l’appui de tes propres ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Toutes tes forteresses seront comme des figuiers gardés; si on les secoue, les figues tombent dans la bouche et sont mangées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Voilà que ton peuple sera comme un peuple de femmes; les portes de ton pays seront ouvertes à tes ennemis; le feu consumera tes barrières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Tire de l’eau pour soutenir un siège; fortifie tes remparts; entre dans l’argile; foule-la aux pieds; mêle-la de lits de paille; sois toi - même plus ferme que la brique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'C’est là que la flamme te dévorera, que le glaive te détruira; comme une nuée de sauterelles tu seras engloutie; tu seras appesantie comme de grandes sauterelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Tu as multiplié tes marchandises plus que les étoiles du ciel; la nuée de sauterelles les a attaquées et s’est envolée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'La multitude étrangère mêlée à toi s’est enfuie comme l’escarbot, ou comme la sauterelle perchée sur la haie un jour de gelée; le soleil s’élève, elle saute dehors, et nul ne sait où elle s’était posée. Malheur à eux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 18, 'Tes pasteurs se sont assoupis; ton roi assyrien s’est endormi avec tes hommes de guerre; ton peuple s’est enfui sur les montagnes, et nul n’était là pour lui donner asile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 19, 'Il n’est point de guérison pour tes blessures, ta plaie s’est enflammée; tous ceux qui entendent parler de tes malheurs battent des mains; car contre qui n’as-tu pas constamment tourné ta scélératesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Vision d’Habacuc le prophète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Jusques à quand, Seigneur, crierai-je sans que vous m’écoutiez? jusques à quand vous crierai-je que l’on me fait violence? Ne me sauverez-vous pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Pourquoi m’avez-vous affligé et m’avez-vous donné la douleur de voir la misère et l’impiété? Je suis en procès, et le juge reçoit des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'À cause de cela, la loi a été déchirée, et le jugement n’arrivera pas à bonne fin, parce que l’impie opprime le juste, et la sentence sera torturée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Voyez, contempteurs de la loi, regardez et admirez ces merveilles, et soyez anéantis: car, de vos jours, je vais faire une œuvre que vous ne croirez pas, quoiqu’on vous l’annonce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Voilà que je vais susciter les Chaldéens, nation cruelle et rapide, qui marche sur les plaines de la terre, pour prendre possession de tentes qui ne sont point les siennes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Redoutable et fameuse, c’est d’elle que le jugement procédera; tout son butin proviendra d’elle-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Et ses chevaux s’élanceront plus agiles que le léopard; ils courront plus rapides que les loups de l’Arabie. Et ses cavaliers sortiront à cheval, et ils prendront de loin leur élan, et ils se déploieront comme l’aigle ardent à dévorer sa proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'La perdition tombera sur les impies qui leur feront face, et leur tiendront tête; et l’envahisseur emmènera des captifs aussi nombreux que les grains de sable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Et il se raillera des rois, et les tyrans seront pour lui des jouets, et il rira de chaque forteresse, et il l’entourera de levées de terre, et il la prendra de force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Alors son esprit changera, et il se transformera, et il fera pitié; telle est la force de mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Seigneur, mon Dieu et mon Saint, n’êtes-vous pas dès le commencement? Est-ce que nous mourrons? Vous avez établi ces choses pour le jugement, et vous m’avez formé, Seigneur, pour annoncer votre châtiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'L’œil du Seigneur est trop pur pour regarder le mal et s’arrêter sur les labeurs de l’affliction. Pourquoi, Seigneur, considérez-vous ceux qui vous méprisent? Pourquoi gardez-vous le silence quand l’impie dévore le juste?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Traiterez-vous les hommes comme les poissons de la mer, ou comme les reptiles qui n’ont point de guide?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Il a pris toute l’espèce à l’hameçon; il en a');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'À cause de cela, il sacrifiera à sa nasse, il encensera son filet, parce qu’avec leur aide il aura engraissé sa part, et recueilli des aliments de choix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Et, à cause de cela, il jettera encore son filet, et ne se fera jamais faute de tuer les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Je me tiendrai en garde, et je monterai sur une roche, et je veillerai pour savoir ce qu’on dira contre moi, et ce que je répondrai quand je serai repris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Et le Seigneur me parla, et il me dit: Écris ta vision, écris - la clairement sur une tablette, afin qu’on la lise couramment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Car ta vision est véritable; elle se réalisera au temps marqué; elle ne sera point vaine. S’il ne vient pas encore, attends-le; car sûrement il viendra et ne tardera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Celui qui se retire de moi, mon âme ne se complaira pas avec lui; le juste vivra de sa foi en moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'L’homme présomptueux, méprisant, imposteur, n’arrivera point à ses fins; celui qui a rendu son âme vaste comme l’enfer est aussi insatiable que la mort; il réunira sous lui toutes les nations, et il recevra sous lui tous les peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Mais toutes ces choses ne feront-elles pas de lui un sujet d’histoires et de récits qu’on se répétera? On dira Malheur à l’homme qui, sans se lasser, accumule les biens d’autrui, et fait cruellement sentir le poids de son collier!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Car soudain s’élèveront contre toi des gens qui te mordront, et autour de toi veilleront des assassins, et tu seras pour eux une proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Parce que tu as pillé une multitude de nations, les peuples qui restent encore te pilleront à leur tour, à cause du sang des hommes, à cause de tes impiétés contre la terre, contre la ville et ses habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Malheur à celui qui, en sa maison, a de mauvaises convoitises, qui veut placer haut son nid, pour se délivrer de la main du malheur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Tu as médité la honte de ta maison, tu as épuisé beaucoup de peuples, et ton âme a péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Aussi la pierre des murailles criera-t-elle contre toi, et l’escarbot du haut des solives lui fera écho.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Malheur à celui qui bâtit une ville avec le sang, et qui la fonde avec l’iniquité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Ces choses ne sont-elles pas du Seigneur tout-puissant? maints peuples forts ont été épuisés par le feu, et maintes nations ont défailli,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Pour que la terre soit remplie de la connaissance de la gloire du Seigneur, qui la couvrira comme l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Malheur à celui qui donne à boire à son ami de la lie de vin, et l’enivre pour voir dans ses cavernes!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Toi aussi, bois, au lieu de gloire, la plénitude de la honte; que ton cœur s’agite et tremble: te voilà');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Car l’impiété du Liban te couvrira, et les ravages des bêtes fauves te feront trembler, à cause du sang des hommes et de tes impiétés contre la terre, contre la ville et tous ses habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'À quoi peut servir une statue qu’eux-mêmes ont sculptée? on l’a jetée en fonte, apparence mensongère, et, pour faire une idole muette, l’artiste a eu foi en l’œuvre qu’il a façonnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Malheur à celui qui dit au bois: Sors de ton assoupissement, réveille-toi; et à la pierre: Lève-toi; car ce n’est qu’une image; c’est de l’or ou de l’argent battus au marteau, et il n’y a en cette œuvre aucun esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Mais le Seigneur réside en son saint temple; que toute la terre révère son visage!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Seigneur, j’ai entendu votre voix, et j’ai eu crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'J’ai considéré vos œuvres, et je me suis extasié. Entre deux animaux vous vous manifesterez; quand les années seront proches, on vous connaîtra; quand les temps seront venus, vous apparaîtrez; quand mon âme est troublée de votre colère, souvenez-vous de votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Dieu viendra de Théman, et le Saint de la montagne ténébreuse de Pharan. Sa vertu est le vêtement des cieux, et la terre est pleine de sa louange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Sa splendeur sera comme la lumière; il a dans sa main des cornes (de puissance), et de la force il a fait un puissant amour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Devant sa face ira une parole; elle cheminera dans les plaines; sur ses pieds');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Il s’est dressé, et la terre en a tremblé; il a regardé, et les nations se sont évanouies. Les montagnes ont été violemment agitées; les collines se sont fondues, sous les pas de sa marche éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'À cause des troubles, j’ai vu les tentes des Éthiopiens renversées; les tentes de la terre de Madian seront aussi frappées d’épouvante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Seigneur, est-ce contre les fleuves que vous êtes irrité? Est-ce que votre colère s’en prend aux fleuves? Attaquerez-vous la mer? car vous êtes monté sur votre char, et vos chevaux amènent le salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Tu as fortement tendu ton arc contre les sceptres, dit le Seigneur. Le cours des fleuves sera déchiré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Les peuples vous verront, Seigneur, et ils auront des douleurs comme celles de l’enfantement. Quand vous détruisiez la voie par une inondation, l’abîme a fait entendre sa voix, et il a élevé ses vagues vers vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Le soleil s’est levé; la lune s’est tenue au lieu qui lui est prescrit: vos rayons s’avanceront dans la lumière, à la lueur des éclairs qui jaillissent de vos armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Par vos menaces, vous abaisserez la terre, et dans votre courroux vous abattrez les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Vous êtes venu pour le salut de votre peuple, pour sauver votre Christ; vous enverrez la mort sur la tête des impies; vous les avez chargés de chaînes jusqu’au cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Vous avez frappé de stupeur les bêtes des puissants; ils en trembleront; ils laisseront voir leur frein en ouvrant la bouche, comme un pauvre qui mange en se cachant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'Et, monté sur vos chevaux, vous êtes entré dans la mer, et ils en ont troublé l’eau profonde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'J’ai veillé, et mes entrailles ont frémi au son de la prière de mes lèvres, et l’effroi est entré dans mes os, et tout mon être a été bouleversé. Je me reposerai au jour de l’affliction, et je monterai chez le peuple où je suis passager.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Car alors le figuier ne portera pas de fruits; il n’y aura pas de raisin à la vigne; l’œuvre de l’olivier sera trompeuse, et les champs ne produiront pas de nourriture. Les brebis manqueront de fourrage, et il n’y aura pas de bœufs à la crèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Pour moi, je tressaillirai dans le Seigneur; je mettrai ma joie en Dieu, mon sauveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'Le Seigneur mon Dieu est ma force; il placera mes pieds sur une base inébranlable; il m’a fait monter sur les hautes cimes, pour chanter en son honneur un chant de triomphe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Parole du Seigneur, qui vint à Sophonie, fils de Chusi, fils de Godolias, fils d’Amorias, fils d’Ézécias, durant les jours de Josias, fils d’Amon, roi de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Que toute chose tombe de défaillance sur la face de la terre, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Que l’homme et les bêtes disparaissent; que disparaissent les oiseaux du ciel et les poissons de la mer; et les impies seront sans force, et je chasserai les pécheurs de la face de la terre, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Et j’étendrai ma main sur Juda et sur les habitants de Jérusalem; et j’effacerai de ce lieu les noms de Baal et de ses prêtres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Et ceux qui adorent sur leurs terrasses l’armée du ciel, et se prosternent en jurant par le Seigneur, et ceux qui jurent par leur roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Et ceux qui s’éloignent du Seigneur, et ceux qui ne cherchent pas le Seigneur, et ceux qui ne s’attachent pas au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Craignez la face du Seigneur Dieu; car le jour du');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Et il arrivera que, le jour du sacrifice du Seigneur, je tirerai vengeance des princes et de la maison du roi, et de tous ceux qui ont porté des vêtements étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Et ce jour-là je tirerai dans les parvis une vengeance éclatante de ceux qui remplissent d’impiété et de fraude le temple du Seigneur leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Et ce jour-là, dit le Seigneur, il y aura des cris à la porte des Assaillants, des hurlements à la seconde porte, et de grands brisements de cœur sur les collines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Pleurez, vous qui habitez cette ville abattue; car tout le peuple est devenu comme Chanaan, et tous ceux qui se glorifiaient de leur argent ont été exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Et en ce jour-là, je rechercherai Jérusalem la lampe à la main, et je tirerai vengeance des hommes qui méprisent mes commandements, et qui disent en leur cœur Le Seigneur ne fera pas de bien, il ne fera pas de mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Leur richesse sera mise au pillage, et leurs maisons en ruines. Ils se bâtiront des demeures, et ils ne les habiteront pas; ils planteront des vignes, et ils n’en boiront pas le vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Car le grand jour du Seigneur est proche; il est proche, il accourt. Le bruit du jour du Seigneur est lamentable et terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Le jour de sa colère est un grand jour; ce jour-là est un jour d’affliction et de calamité; c’est un jour d’angoisse et d’extermination, un jour d’ombre et de ténèbres, un jour de nuages et de vapeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'En ce jour-là, sur les villes fortes et sur les cimes élevées, les cris et les trompettes retentissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Et j’écraserai tous les hommes, et ils marcheront comme des aveugles; car ils ont péché contre le Seigneur; et il répandra leur sang comme la poussière, et leurs chairs comme le fumier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Et au jour de la colère du Seigneur, ni leur argent ni leur or ne pourront les sauver; et, dans le feu de son zèle, toute la terre périra, car il aura hâte d’exterminer jusqu’au dernier tous ceux qui l’habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Rassemblez-vous et priez en commun, ô nation ignorante,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Avant qu’il soit de vous comme de la fleur qui passe, avant que la colère du Seigneur fonde sur vous, avant que n’arrive sur vous le jour de la colère du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Cherchez tous le Seigneur, ô vous humbles de la terre, pratiquez la justice, interrogez l’équité, et répondez-lui, afin d’être abrités au jour de la colère du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Car Gaza sera pillée, Ascalon sera détruite, Azot tombera en plein midi, et Accaron sera déracinée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Malheur à vous, qui habitez les rivages de la mer, colons des Crétois. La parole du Seigneur est contre vous, Chanaan, terre des Philistins, et je vous chasserai de vos demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Et votre territoire sera un pâturage pour les troupeaux, un parc pour les brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Et le rivage de la mer appartiendra aux restes de la maison de Juda; ceux-ci seront nourris dans les demeures d’Ascalon, et ils s’y reposeront le soir, loin de la face des fils de Juda; car le Seigneur leur Dieu les a visités, et il les fera revenir de la captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'J’ai entendu les injures de Moab, et les outrages des fils d’Ammon; ils ont insulté mon peuple, et se sont glorifiés sur ma terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'A cause de cela, par ma vie, dit le Seigneur d’Israël, Dieu des armées, Moab sera comme Sodome, et les fils d’Ammon comme Gomorrhe, et Damas disparaîtra comme le monceau de blé d’une aire, et elle sera effacée pour jamais. Et les restes de mon peuple les pilleront, et les restes de ma nation possèderont leur héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Voilà comment sera punie leur insolence; car en se glorifiant ils ont outragé le Seigneur, maître de toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Le Seigneur se manifestera contre eux, et il anéantira tous les dieux de la terre et tout homme, en son pays, et toutes les îles des nations finiront par l’adorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Et vous, Éthiopiens, vous serez aussi blessés de mon glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Et le Seigneur étendra la main vers l’Aquilon, et il détruira l’Assyrien, et il fera de Ninive une ruine sans eau, comme un désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Et les troupeaux viendront paître au milieu d’elle; et toutes les bêtes fauves de la contrée, et les caméléons, et les hérissons coucheront dans ses palais, et les bêtes farouches hurleront dans ses fossés, et les corbeaux croas');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Voilà cette ville si méprisante, qui se reposait dans sa confiance et disait en son cœur: J’existe, et il n’est point de ville telle que moi. Comment est-elle devenue une solitude, un repaire de bêtes fauves? Et celui qui passera par là sifflera et battra des mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'O ville insigne et mise à rançon, malheur à toi! la colombe');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'N’a pas entendu ma voix ni recueilli l’avertissement; elle n’a point eu foi au Seigneur, et ne s’est point approchée de son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Ses princes sont, au milieu d’elle, comme des lions rugissants, et ses juges comme des loups d’Arabie; et ils n’ont pas subsisté jusqu’à l’aurore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Ses prophètes, hommes méprisants, sont inspirés par le mauvais esprit; ses prêtres profanent les choses saintes, et ne respectent point la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Mais le Seigneur juste est au milieu d’elles, et il ne fera rien d’inique; demain il produira son jugement à la lumière: car Dieu ne se cache point; il ne connaît l’iniquité ni par exaction ni par violence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'J’ai attiré les superbes dans la ruine; leurs tours sont en poussière; je ferai leurs rues si désertes, que nul n’y passera; leurs villes ont dépéri, parce qu’il n’y a plus personne qui vive et demeure en elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'J’ai dit: Craignez-moi, recueillez mon enseignement, et vous ne serez pas exterminés de la face de la terre, partout où je me suis vengé d’elle; tiens-toi prêt, lève-toi et fuis dès l’aurore, car tous leurs raisins sont gâtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Attends-moi, dit le Seigneur, jusqu’au jour de ma résurrection, où je rendrai témoignage; car mon jugement s’exercera dans l’assemblée des nations pour y recevoir les rois et répandre sur eux toute ma colère, parce que dans le feu de mon zèle toute la terre périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Alors je rendrai aux peuples une langue comme à l’origine, afin que tous invoquent le nom du Seigneur, et le servent sous un joug unique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Depuis les sources des fleuves de l’Éthiopie, j’accueillerai les gentils avec ceux de mon peuple qui sont dispersés, et ils m’offriront leurs sacrifices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'En ce jour, tu n’auras plus à rougir des œuvres où tu as prévariqué contre moi; car alors je t’aurai ôté ton orgueil dédaigneux, et tu ne continueras plus de te glorifier sur la montagne de mon sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Et je trouverai en toi un peuple rempli d’humilité et de douceur; et ils auront en vénération le nom du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Ceux qui resteront encore d’Israël; et ils ne feront plus d’iniquité; et ils ne parleront plus de vanités, et, dans leur bouche, la langue ne sera plus trouvée trompeuse; et mon troupeau pourra paître et se reposer sans être effrayé de personne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Réjouis-toi, Sion, ma fille; proclame ton allégresse, Jérusalem, ma fille; tressaille et réjouis-toi de tout ton cœur, Jérusalem, ma fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Le Seigneur t’a remis tes iniquités; il t’a racheté des mains de tes ennemis; le roi d’Israël, qui est le Seigneur, est au milieu de toi: tu ne verras plus de malheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'En ce temps-là, le Seigneur dira à Jérusalem: Rassure-toi, Sion, que tes mains ne soient pas défaillantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Le Seigneur ton Dieu est avec toi; le Tout-Puissant te sauvera: il te rendra la joie; il te rajeunira de son amour; en toi il sera ravi de joie, comme en un jour de fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Et je rassemblerai tes affligés; malheur à qui l’a outragée!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Voilà que j’agirai en toi, pour l’amour de toi, en ce temps-là, dit le Seigneur; et je sauverai celle qui a été opprimée, et je recueillerai celle qui a été répudiée, et je glorifierai ses fils, et ils auront un nom par toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Et en ce temps-là vos ennemis seront confondus lorsque j’en userai ainsi avec vous, et que je vous aurai bien accueillis; car je vous donnerai un nom célèbre, et vous serez glorifiés par tous les peuples de la terre, après que je vous aurai ramené tous vos captifs, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'En la deuxième année du règne de Darius, le sixième mois, le premier jour du mois, la parole du Seigneur vint à Aggée, le prophète, disant: Parle à Zorobabel, fils de Salathiel, de la tribu de Juda, et à Jésus, fils de Josedec, le grand prêtre, et dis');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Voici ce que dit le Seigneur tout-puissant: Ils disent que le temps n’est pas venu de réédifier la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Or la parole du Seigneur est venue à Aggée, le prophète, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Le temps est-il venu pour vous de demeurer en vos maisons lambrissées en voûte, quand notre temple est désert?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Et maintenant, voici ce que dit le Seigneur tout-puissant: Dirigez vos cœurs en vos voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Vous avez semé beaucoup, et peu recueilli; vous avez mangé, mais pas à satiété; vous avez bu, mais point jusqu’à l’ivresse; vous vous êtes vêtus, et vous n’avez pas été réchauffés; et celui qui a thésaurisé ses salaires, les a déposés dans un sac troué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Or voici ce que dit le Seigneur tout-puissant: Dirigez vos cœurs en vos voies;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Montez sur la montagne; abattez des arbres, et réédifiez le temple; et je m’y complairai, et je serai glorifié, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Vous avez convoité beaucoup, et peu vous est venu; et ce peu vous l’avez emporté dans vos maisons, et d’un souffle je l’en ai fait sortir; c’est pourquoi voici ce que dit le Seigneur tout-puissant: En punition de ce que ma demeure est déserte, et que chacun de vous court à sa demeure,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Le ciel vous refusera sa rosée, et la terre vous retirera ses fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Et je ferai passer un glaive sur la terre et sur les montagnes, sur le blé et sur le vin, sur l’huile et sur les fruits de la terre, sur les hommes, leur bétail et tous les travaux de leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Et Zorobabel, fils de Salathiel, de la tribu de Juda, et Jésus, fils de Josédec, le grand prêtre, et tout le reste du peuple entendirent la voix du Seigneur leur Dieu, et les paroles d’Aggée, le prophète, telles que par lui le Seigneur, leur Dieu, les leur avait envoyées. Et le peuple révéra la face du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Et Aggée, le messager du Seigneur, rapporta au peuple le message du Seigneur, disant: Je suis avec vous, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Et le Seigneur suscita l’esprit de Zorobabel, fils de Salathiel, de la tribu de Juda, et l’esprit de Jésus, fils de Josédec, le grand prêtre, et l’esprit du reste du peuple; et ils entrèrent dans le temple du Seigneur, leur Dieu tout-puissant, et ils y firent des travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Le vingt-quatrième jour du sixième mois, la seconde année du règne de Darius;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Et le vingt-unième jour du septième mois, le Seigneur confia sa parole aux mains d’Aggée, le prophète, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Parle à Zorobabel, fils de Salathiel, de la tribu de Juda, et à Jésus, fils de Josédec, le grand prêtre, et à tout le reste du peuple, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Qui de vous a vu ce temple en sa première gloire? Et comment le voyez-vous aujourd’hui? N’est-il pas devant vous comme n’étant point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Et maintenant arme-toi de force, Zorobabel, fils de Salathiel, de la tribu de Juda; arme-toi de force, Jésus, fils de Josédec, le grand prêtre; arme-toi de force, peuple de la terre, dit le Seigneur, et travaille; car je suis avec vous, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Et mon Esprit est debout au milieu de vous; ayez confiance;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Car voici ce que dit le Seigneur tout-puissant: Encore une fois, j’ébranlerai le ciel et la terre, la mer et le désert;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Et j’ébranlerai toutes les nations; et celles des nations que j’aurai élevées viendront; et je remplirai de gloire ce temple, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'À moi est l’or, à moi est l’argent, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'La gloire de ce temple sera grande; mais celle de la fin surpassera celle du commencement, dit le Seigneur Dieu tout-puissant; et à cette terre je donnerai la paix, dit le Seigneur Dieu tout puissant, et je donnerai la paix en ce lieu à tous ceux qui travaillent à réédifier le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Le vingt-troisième jour du neuvième mois de la seconde année du règne de Darius, la parole du Seigneur vint à Aggée, le prophète, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Voici ce que dit le Seigneur, maître de toutes choses Consulte les prêtres sur la loi; dis-leur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Si un homme prend dans le coin de son manteau de la chair consacrée, et si le coin de son manteau touche du pain ou de la viande cuite, du vin ou de l’huile, ou tout autre aliment, cet aliment sera-t-il sanctifié? Et les prêtres répondirent et dirent: Non.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Et Aggée dit: Si un homme souillé et non purifié en son âme touche l’une de ces choses, sera-t-elle souillée? Et les prêtres répondirent et dirent: Elle sera souillée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Et Aggée reprit, et dit: Tel est ce peuple; telle est cette nation devant moi, dit le Seigneur; telles sont toutes les œuvres de leurs mains; tel est celui qui approchera de ce lieu souillé à cause des présents qu’il a reçus le matin; et ils souffriront à l’aspect de leurs travaux; et ils ont haï celui qui les a réprimandés devant les portes de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Et maintenant, en vos cœurs, remontez dans le passé à partir de ce jour, avant qu’on eût posé pierre sur pierre dans le temple du Seigneur; ce qui vous arrivait');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Lorsque vous jetiez dans le coffre à orge vingt mesures de grain, et qu’elles se réduisaient à dix; lorsque vous alliez à la cuve, sous le pressoir, pour y puiser');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Je vous ai frappés par la stérilité; j’ai frappé les œuvres de vos mains par les ravages du vent et par la grêle; et vous ne vous êtes point convertis à moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Pensez donc en vos cœurs, à partir de ce jour et au delà, à partir du vingt-troisième jour du neuvième mois, et du jour où le temple du Seigneur a été fondé; considérez en vos cœurs');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Si l’on voit pareille chose dans les granges; vigne, figuier, grenadier ou olivier: rien n’a encore porté des fruits; mais à partir de ce jour je vous bénirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Et la parole du Seigneur vint une seconde fois à Aggée, le prophète, le vingt-quatrième jour du mois, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Parle à Zorobabel, fils de Salathiel, de la tribu de Juda; dis-lui: J’ébranlerai le ciel et la terre, la mer et le désert,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Et je renverserai le trône des rois, et je détruirai la puissance des rois des nations, et je ferai tomber leurs chars et leurs écuyers; et les chevaux et leurs cavaliers seront abattus; et le frère frappera du glaive son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Or, en ce jour-là, dit le Seigneur, maître de toutes choses, je protégerai Zorobabel, fils de Salathiel, mon serviteur, dit le Seigneur Dieu; et tu seras pour moi comme un sceau d’alliance, parce que je t’ai choisi, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Le huitième mois de la seconde année, sous Darius, la parole du Seigneur vint à Zacharie, fils de Barachie, fils d’Addo, le prophète, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Le Seigneur a été transporté d’un grand courroux contre vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Et tu diras au peuple: Voici ce que dit le Seigneur tout-puissant: Convertissez-vous à moi, dit le Seigneur des armées, et je reviendrai à vous, dit le Seigneur des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Et ne soyez pas comme vos pères, à qui les prophètes d’autrefois firent des reproches, disant: Voici ce que dit le Seigneur, maître de toutes choses: Quittez vos mauvaises voies et vos œuvres criminelles; et ils n’écoutèrent pas, et il ne s’empressèrent pas de m’obéir, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Où sont vos pères? Où sont les prophètes? Est-ce qu’ils vivront toujours?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Accueillez donc mes paroles et mes ordonnances, et tout ce que par mon Esprit j’ai intimé à mes serviteurs les prophètes, qui ont repris vos pères; or ceux-ci ont répondu, et ont dit: Le Seigneur nous a traités selon ce qu’il avait résolu, et ainsi a-t-il fait, à cause de nos voies et de nos œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Le vingt-quatrième jour du onzième mois, celui du Sabbat, la deuxième année du règne de Darius, la parole du Seigneur vint à Zacharie, fils de Barachie, fils d’Addo, le prophète, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'J’ai eu la nuit une vision. Et voilà qu’un homme était monté sur un cheval fauve, et il se tenait entre des montagnes ombreuses, et il y avait derrière lui des chevaux roux, gris-pommelé, tachetés et blancs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Et je dis Qui sont ceux-là, Seigneur? Et l’ange qui parlait avec moi me dit: Je te montrerai ce que c’est.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Et l’homme, qui se tenait debout entre les montagnes, parla, et il me dit: Ceux-ci sont ceux que le Seigneur a envoyés pour aller par toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Et ils parlèrent à l’ange du Seigneur qui se tenait entre les montagnes, et ils dirent: Nous sommes allés par toute la terre, et voilà que toute la terre est habitée, et elle est en repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Et l’ange du Seigneur répondit: Seigneur tout-puissant, dit-il, jusques à quand serez-vous sans miséricorde pour Jérusalem et pour les villes de Juda, que vous avez délaissées depuis soixante-dix ans?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Et le Seigneur tout-puissant répondit à l’ange qui parlait avec moi, et lui dit des paroles bonnes et consolantes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Et l’ange qui parlait avec moi me dit: Crie de toute ta force. Voilà ce que dit le Seigneur tout-puissant: Je suis pris d’un grand zèle pour Jérusalem et pour Sion;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Mais j’ai une grande colère contre les gentils qui se sont coalisés; car me voyant un peu irrité contre elle, ils se sont coalisés pour lui faire du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'C’est pourquoi voici ce que dit le Seigneur: Je reviendrai à Jérusalem en ma miséricorde, et mon temple y sera réédifié, dit le Seigneur tout-puissant; et il étendra encore le cordeau sur Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Et l’ange qui parlait avec moi ajouta: Crie encore de toute ta force: Voilà ce que dit le Seigneur Tout-Puissant Leurs villes seront de nouveau remplies de biens, et le Seigneur sera miséricordieux envers Sion, et Jérusalem sera son élue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Et je levai les yeux, et je regardai, et je vis quatre cornes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Et je dis à l’ange qui parlait avec moi: Qu’est cela, Seigneur? Et il me dit: Ce sont les cornes qui ont dispersé Juda, Israël et Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Et le Seigneur me montra quatre ouvriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Et je dis Que vont faire ceux-ci? Et il dit: Voilà les cornes qui ont dispersé Juda et brisé Israël, sans que nul ait levé la tête; or ceux-ci sont venus pour les aiguiser de leurs mains, et les quatre cornes sont les nations qui ont levé la corne contre la terre du Seigneur, pour disperser mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Et je levai les yeux, et je regardai, et voilà qu’un homme tenait en sa main un cordeau de mesureur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Et je lui dis: Où vas-tu? Et il me dit: Je vais mesurer Jérusalem, et voir quelle est sa largeur et quelle est sa longueur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Et voilà que l’ange qui parlait avec moi s’arrêta, et un autre ange marchait à sa rencontre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Et il lui parla, disant: Cours et parle à ce jeune homme, et dis-lui: Jérusalem regorgera d’une multitude d’hommes et d’un nombreux bétail en son enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Et moi, dit le Seigneur, je serai un rempart de feu autour d’elle; et je résiderai au milieu d’elle en ma gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Fuyez, fuyez de la terre de l’Aquilon, dit le Seigneur; car je vous ramènerai des quatre vents du ciel, dit le Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Je vous ramènerai dans Sion; sauvez-vous, vous qui.habitez chez la fille de Babylone!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Car voici ce que dit le Seigneur tout-puissant: Sur les pas de leur gloire, il m’a envoyé contre les nations qui vous ont dépouillés; car celui qui touche à vous est comme celui qui touche à la prunelle de son œil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Aussi voilà que je porte la main sur eux, et ils seront la proie de ceux qu’ils ont asservis; et vous connaîtrez que je suis l’envoyé du Seigneur tout-puissant..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Réjouis-toi, tressaille d’allégresse, Sion, ma fille; car voilà que j’arrive, et je placerai ma tente au milieu de toi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Et en ce jour nombre de nations se réfugieront auprès du Seigneur, et elles seront à lui comme un peuple nouveau; et elles résideront au milieu de toi, et tu connaîtras que le Seigneur tout-puissant m’a envoyé près de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Et le Seigneur aura Juda pour héritage; ce sera sa part dans la terre sainte, et Jérusalem sera encore son élue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Que toute chair craigne en face du Seigneur; car il s’est élancé de ses nuées saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Et le Seigneur me montra Jésus, le grand prêtre, se tenant devant l’ange du Seigneur, et le diable était à sa droite, pour s’opposer à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Et le Seigneur dit au diable: Que le Seigneur te réprime, ô Satan; que le Seigneur, qui a choisi Jérusalem, te réprime! Vois: cela n’est-il pas comme un tison retiré du feu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Or Jésus avait des vêtements sordides, et il se tenait debout devant la face de l’ange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Et celui-ci parla, et dit à ceux qui se tenaient debout devant sa face: Otez au prêtre ses vêtements sordides; et, s’adressant à lui, il ajouta: Voilà que je t’ai ôté tes iniquités; et vous, revêtez-le de la robe traînante,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Et posez sur sa tête une tiare pure. Et ils le couvrirent d’une tiare pure, et ils lui donnèrent d’autres vêtements; et l’ange du Seigneur se tenait auprès d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Et l’ange du Seigneur, s’expliquant avec Jésus, lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Voici ce que dit le Seigneur, maître de toutes choses: Si tu chemines en mes voies, si tu gardes mes commandements, tu seras le juge de ma maison; et si tu gardes mes parvis, je te donnerai des hommes pour marcher au milieu de ceux qui sont ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Écoute donc, Jésus, grand prêtre, écoutez aussi, vous qui êtes assis avec lui devant moi; car vous êtes des hommes attentifs aux prodiges; or voilà que j’amène mon serviteur ORIENT.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Car voici la pierre que j’ai placée devant la face de Jésus; sur cette pierre unique il y a sept yeux; et voilà que je creuse une fosse, dit le Seigneur tout-puissant, et en un seul jour j’ôterai toute l’iniquité de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'En ce jour, dit le Seigneur tout-puissant, chacun de vous invitera son ami sous sa vigne et sous son figuier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Et l’ange qui parlait avec moi revint, et il me réveilla, et je fus comme un homme éveillé de son sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Et il me dit: Vois-tu? Et je dis: J’ai vu; voilà un chandelier tout d’or, et dessus un lampion et sept lampes, et sept burettes à verser l’huile, pour les sept lampes qui sont sur le chandelier;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Et au-dessus de lui deux oliviers, l’un à droite du lampion, l’autre à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Et je questionnai, et je parlai à l’ange qui était avec moi, disant: Qu’est-ce que cela, Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Et l’ange qui était avec moi répondit, et il me parla, disant: Tu ne sais pas ce que c’est? Et je repris: Nullement, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Et il reprit, et il me parla, disant: C’est la parole du Seigneur à Zorobabel, disant: Il te faut non une grande puissance, ni la force, mais mon Esprit, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Qui es-tu pour prospérer, ô grande montagne que je vois devant Zorobabel? Or je transporterai la pierre de l’héritage, dont la grâce est l’égale de ma grâce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Les mains de Zorobabel ont fondé ce temple, et ses mains l’achèveront; et tu connaîtras que le Seigneur tout-puissant m’a envoyé à toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Car qui a méprisé le temple dans les mauvais jours? Or on se réjouira, et on verra Zorobabel le plomb à la main. Ces sept yeux sont ceux qui regardent toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Et je parlai, et je lui dis: Que sont ces deux oliviers, l’un à droite, l’autre à gauche du chandelier?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Et je l’interrogeai de nouveau, et lui dis: Que sont ces deux rameaux d’olivier, à côté des deux becs de lampe où coule l’huile des sept burettes d’or?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Et il me répondit: Tu ne sais pas ce que c’est? et je répondis: Nullement, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Et il dit: Ce sont les deux fils de l’onction qui se tiennent auprès du Seigneur de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Et je me retournai, et je levai les yeux, et je regardai; et voilà une faux volante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Et l’ange me dit: Que vois-tu? Et je dis: Je vois une faux volante, longue de vingt coudées, et large de dix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Et il me dit: C’est la malédiction qui se promène sur toute la face de la terre; car de ce côté-ci tout larron sera puni de mort, et de ce côté-là tout parjure sera puni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Et je la ferai cheminer, dit le Seigneur tout-puissant; et elle entrera dans la maison du voleur et dans la maison de celui qui jure en vain mon nom, et elle demeurera au milieu de sa maison, et elle en consumera le bois et les pierres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Et l’ange qui parlait avec moi sortit, et il me dit: Lève les yeux, et regarde ce qui s’avance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Et je dis: Qu’est-ce? Et il reprit: C’est la mesure qui s’avance; et il ajouta: C’est leur iniquité qui couvre toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Et voilà qu’un talent de plomb s’élevait, et voilà qu’une femme était assise au milieu de la mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Et l’ange dit: Celle-ci est le péché; et il fit tomber la femme au fond de la mesure, et il fit tomber la masse de plomb dans sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Et je levai les yeux, et je regardai, et voilà deux');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Et je dis à l’ange qui parlait avec moi: Où emportent-elles la mesure?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Et il répondit: Elles vont lui bâtir une demeure en la terre de Babylone, et préparer pour cela une place; elles la mettront sur sa base.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Et je me retournai, et je levai les yeux, et je regardai, et voilà quatre chars sortant entre deux montagnes, et ces montagnes étaient d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Au premier char il y avait des chevaux roux, et au second char, des chevaux noirs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Et au troisième char, des chevaux blancs, et au quatrième char, des chevaux gris-pommelé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Et je parlai, et je dis à l’ange qui parlait avec moi: Qu’est cela, Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Et l’ange qui parlait avec moi me répondit, et me dit: Ce sont les quatre vents du ciel; ils sortent pour se tenir devant le Seigneur de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Or les chevaux noirs s’en allaient sur toute la terre du septentrion; et les blancs venaient ensuite; et les gris-pommelé s’en allaient sur la terre du midi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Et les autres sortirent, et ils regardèrent pour s’en aller et parcourir toute la terre; et l’ange leur dit: Marchez et parcourez toute la terre. Et ils parcoururent toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Et il cria, et il me parla, disant: Voilà que ceux qui s’en vont sur la terre du septentrion ont satisfait à ma colère, en la terre du septentrion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Et la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Prends les dons des captifs, soit de leurs princes, soit des hommes serviables de la captivité, soit de ceux qui l’honorent; et ce jour-là entre en la maison de Josias, fils de Sophonie, qui est arrivé de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Et tu prendras l’argent et l’or, et tu en feras des couronnes, et tu les poseras sur la tête de Jésus, fils de Josédec, le grand prêtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Et tu lui diras: Voici ce que dit le Seigneur tout-puissant: Voilà un homme: Orient est son nom, et il se lèvera venant de ce qui est sous lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Et il bâtira le temple du Seigneur, et il recevra la force, et il siégera, et il régnera sur son trône; et le prêtre sera à sa droite, et un conseil de la paix sera entre eux deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Et la couronne sera pour ceux qui ont souffert patiemment, et pour ceux de la captivité qui auront été serviables, et pour ceux qui l’ont honorée, afin de rendre des actions de grâces au fils de Sophonie, et les chanter dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Et ceux qui demeurent au loin viendront et travailleront aussi à réédifier le temple du Seigneur; et vous saurez que le Seigneur tout-puissant m’a envoyé près de vous; et ces choses arriveront si vous êtes dociles à la voix du Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Et en la quatrième année du règne de Darius, le quatrième jour du neuvième mois de chaseleu, la parole du Seigneur vint à Zacharie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Sarasar et Arbeséer, le roi et ses hommes, envoyèrent en Béthel pour prier le Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'Disant aux prêtres du temple du Seigneur tout-puissant et aux prophètes: Les saintes offrandes sont entrées ici le cinquième mois, comme il a déjà été fait en un grand nombre d’années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Et la parole du Seigneur, Dieu des armées, vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Parle à tout le peuple de la terre et aux prêtres, et dis-leur: Quand vous avez jeûné et pleuré les cinquième et septième mois de ces soixante-dix années, est-ce pour moi que vous avez jeûné?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Et quand vous avez mangé et bu, n’est-ce pas pour vous que vous mangiez et buviez?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'N’est-ce point là ce que vous a dit le Seigneur, par les prophètes d’autrefois, lorsque Jérusalem était habitée et prospérait, ainsi que les villes d’alentour, et que les montagnes et la plaine regorgeaient d’habitants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Et la parole du Seigneur vint à Zacharie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Voici ce que dit le Seigneur, maître de toutes choses Soyez justes quand vous jugez, et que chacun soit compatissant et miséricordieux envers son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Gardez-vous d’opprimer la veuve, l’orphelin, l’étranger, le pauvre; et ne conservez point en vos cœurs un mauvais souvenir des méchancetés de vos frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Et ils ne le voulurent point entendre, et ils lui tournèrent le dos avec mépris, et pour ne point ouïr ils se bouchèrent les oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Et ils se firent des cœurs désobéissants, au point d’être indociles à ma loi et aux paroles que leur envoyait le Seigneur tout-puissant, par son Esprit et par les prophètes d’autrefois. Et le Seigneur tout-puissant en eut un grand courroux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Or voici ce qui arrivera, dit le Seigneur tout-puissant: le Seigneur a parlé et ils n’ont point écouté; de même, quand ils crieront, je ne les écouterai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Et je les chasserai; et je les disperserai parmi les nations qu’ils n’ont point connues; et derrière eux la terre sera dénuée d’allants et venants; et ils auront voué à la destruction une terre que j’avais choisie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Et la parole du Seigneur, maître de toutes choses, me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Voici ce que dit le Seigneur, maître de toutes choses Je suis pris d’un grand zèle pour Jérusalem et pour Sion, et je suis en même temps pris d’une grande colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Voici ce que dit le Seigneur: Je reviendrai à Sion; je résiderai au milieu de Jérusalem, et Jérusalem sera appelée la ville de vérité, et la montagne du Seigneur sera la montagne sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Voici ce que dit le Seigneur tout-puissant: Des anciens et des anciennes s’assoiront encore dans les rues de Jérusalem, ayant chacun à la main un bâton de vieillesse, à cause de la plénitude de leurs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Et les places de la ville seront remplies de jeunes garçons et de jeunes filles qui joueront dans ses rues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Voici ce que dit le Seigneur tout-puissant: Si en ces jours cela est impossible aux yeux de ceux qui sont restés de ce peuple, est-ce que cela sera impossible à mes yeux? dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Voici ce que dit le Seigneur tout-puissant: Je sauverai mon peuple des contrées de l’Orient et de celles de l’Occident;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Et je l’en ferai sortir, et je le ramènerai au milieu de Jérusalem; et il sera mon peuple, et moi je serai son Dieu de vérité et de justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Voici ce que dit le Seigneur tout-puissant: Que vos mains soient fortes, ô vous qui entendez en ces jours les paroles de la bouche des prophètes, en ce jour où l’on a jeté les fondations de la maison du Seigneur tout-puissant, et où le temple a été relevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Car avant ces jours le salaire des hommes ne sera point lucratif, le travail des bêtes ne profitera point, et ceux qui sont entrés, ceux qui sont sortis, n’auront pas trouvé de paix, à cause de leurs afflictions. Et alors je ferai marcher tous les hommes l’un contre l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Mais maintenant je ne traiterai plus les restes de ce peuple comme aux jours d’autrefois, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Je lui ferai connaître la paix. La vigne produira son fruit; la terre produira ses récoltes; le ciel donnera sa rosée, et au reste de mon peuple je laisserai toutes ces choses en héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Et voici ce qui arrivera: autant vous recevrez de malédictions chez les gentils, vous, maison de Juda, et vous, maison d’Israël, autant je mettrai de soins à vous sauver, et autant vous recevrez de bénédictions. Ayez bon courage, et fortifiez vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Car voici ce que dit le Seigneur tout-puissant: De même que j’ai songé à vous affliger parce que vos pères avaient excité mon courroux, dit le Seigneur tout-puissant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Sans que je m’en repente de même je suis disposé et je songe, en ces jours, à combler de biens Jérusalem et la maison de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Voici les choses que vous ferez parlez selon la vérité à votre prochain; jugez devant vos portes selon la vérité, la justice et la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Ne pensez pas à mal en vos discours contre votre prochain, et n’aimez pas le faux serment; car je hais toutes ces choses, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Et la parole du Seigneur tout-puissant vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Voici ce que dit le Seigneur tout-puissant: Le jeûne du quatrième mois, le jeûne du cinquième, le jeûne du septième, le jeûne du dixième, seront alors pour la maison de Juda un sujet de joie, d’allégresse et de bonnes fêtes; réjouissez-vous; aimez la vérité et la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Voici ce que dit le Seigneur tout-puissant: Vous deviendrez encore un peuple nombreux, et vous habiterez beaucoup de villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Et les habitants de cinq villes se réuniront en une seule, en disant: Allons prier devant la face et sous les yeux du Seigneur tout-puissant; et moi, j’irai à eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Et des peuples nombreux et des nations nombreuses viendront à Jérusalem chercher la face du Seigneur tout-puissant, et prier devant la face du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Voici ce que dit le Seigneur tout-puissant: En ces jours, dix hommes de toutes les langues prendront par la frange de son manteau un homme de la Judée, disant: Nous irons avec toi, parce que nous avons ouï dire que Dieu est avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Parole du Seigneur contre la terre de Sedrach; et celle de Damas sera sacrifiée comme elle; car le Seigneur surveille les hommes et toutes les tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Et cette parole est contre la terre d’Emath qui contient Tyr et Sidon, parce qu’elles ont trop connu la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Or Tyr s’est bâti des forteresses, et elle a thésaurisé de l’argent par monceaux comme de la poussière, et des amas d’or comme la boue des chemins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Et à cause de cela le Seigneur en prendra possession, et il jettera ses forces à la mer, et elle-même sera dévorée par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Ascalon le verra et en tremblera; Gaza le verra et en souffrira cruellement; Ascaron le verra et sera confondue de sa chute; et le roi de Gaza périra, et Ascalon ne sera plus habitée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Et des étrangers repeupleront Azot; et j’abattrai l’orgueil des Philistins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Et j’ôterai de leur bouche le sang des victimes, et l’abomination d’entre leurs dents; et ils seront aussi délaissés par notre Dieu, et ils seront comme un chef de mille hommes en Juda, et Accaron sera comme un Jébuséen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Et j’élèverai un rempart autour de ma maison, pour qu’on ne puisse plus la traverser et y revenir, et que nul envahisseur n’y pénètre désormais; car maintenant je la vois de mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Réjouis-toi grandement, Sion, ma fille, annonce à haute voix, Jérusalem, ma fille: Voilà que ton roi vient à toi, juste et sauveur, et il est plein de douleur, il est monté sur un âne, et sur un ânon, petit de l’ânesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Et il détruira les chars d’Éphraïm et la cavalerie de Jérusalem; et l’arc des batailles sera brisé, et il y aura paix et abondance parmi les nations; et il règnera depuis les eaux jusqu’à la mer, depuis les fleuves jusqu’aux confins de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Et toi, à cause du sang de ton alliance, tu as retiré tes captifs d’une citerne sans eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Et vous, captifs de la Synagogue, établissez-vous en des forteresses; et, pour un jour de captivité, je vous rétribuerai doublement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Juda, tu es mon arc, et je l’ai tendu; j’ai rempli Éphraïm; j’exciterai tes enfants, ô Sion, contre les enfants des Hellènes, et je te manierai comme le glaive des combattants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Et le Seigneur sera près d’eux; son trait partira comme un éclair; et le Seigneur tout-puissant sonnera de la trompette, et il s’avancera dans le tumulte de ses menaces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mais le Seigneur tout-puissant protégera les siens; ils extermineront leurs ennemis; ils les couvriront des pierres de leurs frondes; ils boiront leur sang comme du vin, et ils en rempliront leurs coupes, comme l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Et en ce jour le Seigneur leur Dieu les sauvera; il sauvera son peuple, comme un troupeau de brebis, parce que des pierres saintes sont roulées sur sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Car si quelque chose est son bien, si quelque chose est sa beauté, c’est le pain pour les jeunes hommes, et le vin d’odeur de suavité pour les vierges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Demandez au Seigneur de la pluie selon la saison, le matin et le soir. Le Seigneur a créé des signes manifestes; il donnera aux hommes les pluies d’hiver, et à chacun de l’herbe en son champ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Les faux prophètes ont fait des prédictions funestes; le devins ont rapporté des visions fausses et des songes trompeurs; ils ont donné de vaines consolations; à cause de cela, ils ont dépéri comme des brebis abandonnées; ils ont été affligés, parce qu’il n’y avait pas de remède.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Ma colère s’est enflammée contre les pasteurs, et je visiterai les agneaux. Et le Seigneur Dieu tout-puissant visitera son troupeau, la maison de Juda; et il la formera comme son coursier, prêt aux combats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'C’est de lui que vient la visite; de lui, l’ordre de bataille; de lui, l’arc de la colère; et aussi tout exacteur sortira de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Et ils seront comme des guerriers, foulant aux pieds la boue des chemins dans la bataille; et ils en viendront aux mains, parce que le Seigneur sera avec eux; et les cavaliers seront confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Et je fortifierai la maison de Juda; et je sauverai la maison de Joseph, et je les rétablirai, parce que je les aime; et ils seront comme si je ne les avais pas répudiés; car je suis le Seigneur leur Dieu, et je les exaucerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Et ils seront comme les guerriers d’Éphraïm, et leur cœur se réjouira, comme dans le vin; voilà ce que verront leurs enfants, et ils en seront charmés, et leur âme se réjouira dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Je leur donnerai le signal et je les rassemblerai; car je les affranchirai et les multiplierai, comme lorsqu’ils étaient le plus nombreux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Et je les disséminerai parmi les peuples, et les plus lointains se souviendront de moi; ils élèveront leurs enfants, et ils reviendront de captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Et je les ramènerai de la terre d’Égypte; je les accueillerai à leur retour de l’Assyrie, et je les conduirai en Galaad et sur le Liban; et pas un seul d’entre eux ne sera laissé en oubli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Et ils traverseront les détroits de la mer, et ils frapperont ses vagues, et le fond des fleuves sera à sec, et tout l’orgueil des Assyriens sera abattu, et le sceptre de l’Égypte sera brisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Et je les fortifierai dans le Seigneur leur Dieu; et ils se feront gloire de son nom, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Liban, ouvre tes portes, et que le feu dévore tes cèdres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Que le pin gémisse, parce que le cèdre est tombé, parce que les plus grands sont détruits; chênes de Basan, gémissez, parce que la forêt épaisse est abattue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Que la voix des pasteurs en larmes se fasse entendre, parce que leur grandeur s’est changée en détresse; et que les lions rugissent, parce que le Jourdain souffre en son orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Voici ce que dit le Seigneur tout-puissant: Paissez les brebis du sacrifice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Leurs possesseurs les égorgeaient sans regret, tandis que ceux qui en avaient vendu disaient: Béni soit le Seigneur, nous voilà riches; et leurs bergers ne souffraient aucunement pour elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'C’est pourquoi je n’épargnerai aucun des habitants de la terre, dit le Seigneur; et voilà que je livrerai chacun de ces hommes aux peuples voisins et aux mains de leurs rois; et ceux-ci désoleront la terre, et je ne la dětivrerai point de leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Et je ferai paître dans le pays de Chanaan les brebis du sacrifice, et je prendrai pour moi deux houlettes, l’une que j’ai nommée la Beauté, l’autre que j’ai nommée le Cordeau; et je ferai paître les brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Et je ferai périr trois pasteurs en un mois, et mon âme s’appesantira sur eux; car leurs âmes ont rugi contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Et j’ai dit: Je ne serai plus votre pasteur; que ce qui est mort soit mort, que ce qui est tombé soit tombé, et que les survivants dévorent les chairs les uns des autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Et je prendrai ma belle houlette, et je la rejetterai pour briser mon alliance, l’alliance que j’avais faite en faveur de tous les peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Et ce jour-là elle sera rompue, et les Chananéens connaîtront les brebis que je garde; car telle est la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Et je leur dirai: S’il vous semble bon, donnez-moi un salaire; sinon, refusez-le-moi. Et ils ont pesé pour mon salaire trente sicles d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Et le Seigneur me dit: Jette-les dans le creuset, et je verrai si l’argent a été éprouvé de la même manière que j’ai été éprouvé pour l’amour d’eux. Et je pris les trente sicles d’argent, et je les jetai au creuset, dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Et je rejetai la seconde houlette, le Cordeau, pour briser les liens entre Juda et Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Et le Seigneur me dit: Prends encore pour toi le bagage d’un pasteur, d’un pasteur insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Car voilà que je susciterai un pasteur contre la terre; et il ne visitera pas ce qui périt; et il ne cherchera pas ce qui est égaré; et il ne guérira pas ce qui est blessé; et il ne gardera pas même ce qui est entier; et il mangera les chairs des bêtes d’élite, et il disloquera les jointures des os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Malheur au pasteur des idoles, à celui qui délaisse les brebis! le glaive est levé sur son bras et sur son œil droit; son bras sera desséché, et son œil droit ne verra plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Parole du Seigneur concernant Israël; ainsi parle le Seigneur qui a tendu le ciel, fondé la terre et formé l’esprit de l’homme en lui:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Voilà que devant tout le peuple d’alentour je ferai Jérusalem comme le linteau tremblant d’une porte; et en Judée même on assiégera Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Et voici ce qui arrivera: en ce jour je ferai de Jérusalem une pierre que fouleront aux pieds tous les Gentils. Quiconque marchera sur elle s’en raillera, et toutes les nations de la terre se réuniront contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'En ce jour, dit le Seigneur tout-puissant, je frapperai de stupeur le cheval, et de démence le cavalier. J’aurai les yeux ouverts sur la maison de Juda, et je frapperai d’aveuglement les chevaux de tous les peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Et les chefs de mille hommes de Juda diront en leur cœur: Puissions-nous trouver pour nous les habitants de Jérusalem revenus au Seigneur leur Dieu tout-puissant!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'En ce jour-là je rendrai les chefs de mille hommes de Juda comme un tison enflammé dans un bûcher, comme une lampe allumée dans la paille; ils dévoreront, à droite et à gauche, tous les peuples d’alentour, et Jérusalem d’elle-même repeuplera encore Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Et le Seigneur sauvera les habitants de Juda, comme dans les premiers jours; de telle sorte que l’orgueil de la maison de David et des hommes de Jérusalem ne s’élève point contre Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Et voici ce qui arrivera: en ce jour le Seigneur protégera les habitants de Jérusalem; et le faible chez eux sera, ce jour-là, comme David, et la maison de David, comme la maison de Dieu, comme l’ange du Seigneur devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Et voici ce qui arrivera: en ce jour je rechercherai pour les anéantir toutes les nations qui auront marché contre Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Et je répandrai sur la maison de David et sur Jérusalem un esprit de grâce et de miséricorde; et ils tourneront les yeux vers moi, parce qu’ils m’auront insulté; et ils se lamenteront sur le peuple, comme sur un enfant bien-aimé; et ils seront pénétrés de douleur, comme sur un fils premier-né.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'En ce jour les gémissements redoubleront en Jérusalem tel dans la campagne gémit, sous la hache du bûcheron, un bois de grenadiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Et la terre gémira famille par famille; la famille de la maison de David, et ses femmes à part; la famille de la maison de Nathan, et ses femmes à part;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'La famille de la maison de Lévi, et ses femmes à part; la famille de Siméon, et ses femmes à part.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Et toutes les autres tribus, et leurs femmes à part.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'En ce jour tout lieu sera ouvert à la maison de David et aux habitants de Jérusalem, pour le départ et la séparation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Et ce jour-là voici ce qui arrivera, dit le Seigneur Dieu des armées: j’effacerai les noms des idoles sur la terre, et il n’y aura plus de ces noms aucun souvenir; et j’exterminerai de la terre les faux prophètes et l’esprit immonde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Et voici ce qui arrivera si un homme prophétise encore, son père et sa mère qui l’ont engendré lui diront: Tu mourras, parce que tu as dit des mensonges au nom du Seigneur. Et son père et sa mère qui l’ont engendré l’empêcheront de prophétiser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Et ce jour-là voici ce qui arrivera: les prophètes menteurs seront confondus, chacun par la vision même pour laquelle il aura prophétisé, et ils se ceindront de cilices de crin, parce qu’ils auront menti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Et chacun d’eux dira: Je ne suis point prophète; je suis un homme travaillant à la terre, et c’est un homme qui m’a donné le jour, et m’a ainsi élevé depuis ma jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Et je lui dirai: Qu’est-ce que ces plaies que tu as au milieu des mains? Et il répondra: Ce sont les plaies que j’ai reçues dans une maison bien-aimée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Glaive, lève-toi contre mes pasteurs et contre l’homme qui habite ma ville, dit le Seigneur tout-puissant; frappez le berger, enlevez les brebis, et j’étendrai ma main sur les petits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Et voici ce qui arrivera sur toute la terre, dit le Seigneur: j’en exterminerai deux parts, elles périront; et la troisième part sera épargnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Et je ferai passer la troisième part dans la flamme, et je la purifierai au feu, comme on purifie l’argent, et je l’éprouverai comme on éprouve l’or. Elle invoquera mon nom, et je l’exaucerai; et je dirai: Voici mon peuple; et elle dira: Le Seigneur est mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Voici que les jours du Seigneur arrivent; et tes dépouilles au milieu de toi vont être partagées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Et je rassemblerai toutes les nations pour qu’elles combattent contre Jérusalem; et la ville sera prise, et les maisons seront livrées au pillage, et les femmes seront profanées; et la moitié des habitants sera emmenée captive, et le reste de mon peuple ne sera point massacré dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Et le Seigneur sortira et il combattra les gentils, comme il combat au jour de la bataille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Et ce jour-là ses pieds poseront sur la montagne des Oliviers, vis-à-vis Jérusalem, du côté de l’Orient. Et la montagne des Oliviers se fendra, moitié vers l’Orient, moitié du côté de la mer; il y aura entre les deux moitiés un immense ravin. Et l’une des deux moitiés s’inclinera au nord, et l’autre au midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Et la gorge de mes montagnes se fermera; et la gorge des montagnes sera resserrée jusqu’à Jasod, et elle sera close comme elle l’a été du temps du tremblement de terre, durant les jours d’Ozias, roi de Juda. Et le Seigneur mon Dieu viendra, et tous ses saints avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Et voici ce qui arrivera: en ce jour-là il n’y aura point de lumière, mais du froid et de la gelée, qui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Dureront tout le jour; et ce jour-là sera connu du Seigneur, et ce ne sera pas le jour, et ce ne sera pas la nuit; et, sur le soir, il y aura une lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Et ce jour-là une eau vive sortira de Jérusalem, et la moitié coulera à la première mer, et l’autre moitié à la dernière; et il en sera ainsi pendant le printemps et l’été.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Et le Seigneur sera roi de toute la terre; et ce jour-là le Seigneur sera le seul Dieu, et son nom sera UN,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Tout autour de la terre et du désert de Gaza à Remmon, au midi de Jérusalem. Rama subsistera où il est, de la porte de Benjamin à la place de l’ancienne porte, et à la porte des Angles, et de la tour d’Anaméel aussi loin que les pressoirs du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Jérusalem sera repeuplée; elle ne sera plus frappée d’anathème, et elle sera assise en assurance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Et voici le fléau dont le Seigneur frappera tous les peuples qui auront marché contre elle. Leurs chairs se liquéfieront, eux debout sur leurs pieds; leurs yeux s’écouleront hors de leurs orbites, et leur langue se liquéfiera dans leur bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Et ce jour-là voici ce qui arrivera: il y aura contre eux un grand transport du Seigneur; et ils se prendront par la main les uns les autres, et les mains entrelaceront les mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Et Juda se rangera en bataille contre Jérusalem; et on recueillera les richesses de tous les peuples d’alentour, l’or, l’argent et des vêtements innombrables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Et les chevaux, les mulets, les chameaux, les ânes et toutes les bêtes qui seront dans les camps seront pareillement détruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Voici ce qui arrivera: les survivants parmi les gentils qui auront marché contre Jérusalem Y monteront chaque année pour y adorer le Roi, Seigneur tout-puissant, et pour célébrer la fête des Tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Et voici ce qui arrivera: si de toutes les tribus de la terre on ne monte pas à Jérusalem pour adorer le Roi, Seigneur tout-puissant, ceux qui s’en abstiendront seront pareillement punis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Et s’il est une des tribus de l’Égypte qui ne monte pas au temple, les mêmes fléaux l’atteindront; elle sera frappée comme toutes les nations qui ne viendront pas célébrer la fête des Tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Ce sera le péché de l’Égypte, et le péché de toutes les nations qui ne viendront pas célébrer la fête des Tabernacles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Et ce jour-là tout ce qui orne le frein des chevaux sera consacré au Seigneur tout-puissant; les chaudières seront dans le temple du Seigneur comme les coupes devant l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Et toutes les chaudières de Jérusalem et de Juda seront consacrées au Seigneur tout-puissant. Et tous ceux qui offriront des sacrifices viendront, et ils prendront de ces chaudières, et ils s’en serviront pour faire cuire les victimes; et ce jour-là il n’y aura plus de Chananéens dans la maison du Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Parole du Seigneur sur Israël transmise à son envoyé; déposez-la maintenant dans vos cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Je vous ai aimés, dit le Seigneur, et vous avez dit: En quoi donc nous avez-vous aimés? Ésau n’était-il pas le frère de Jacob? dit le Seigneur; n’ai-je point aimé Jacob');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Et pris en haine Ésau? J’ai voulu que ses confins fussent dévastés, et que son héritage devînt comme les maisons du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Or si l’on dit: L’Idumée est détruite, revenons et repeuplons le désert, voici ce que dit le Seigneur: Ils rebâtiront, et je renverserai, et leur terre sera surnommée l’impiété, et ce sera un peuple à qui le Seigneur sera hostile pour jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Et vos yeux verront cela, et vous direz: Le Seigneur a montré sa puissance au delà des limites d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Le fils glorifie le père, et le serviteur son maître; et si je suis père, où est ma gloire? Et si je suis maître, où est la crainte que j’inspire? dit le Seigneur toutpuissant. Et vous, prêtres, c’est vous qui méprisez mon nom, et qui dites: En quoi méprisons-nous votre nom?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'C’est vous qui présentez à l’autel des aliments souillés, et qui dites: En quoi les avons nous souillés? Vous les avez souillés en disant: La table du Seigneur est souillée; et ce qu’on y déposait vous l’avez méprisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Si vous présentez pour le sacrifice une victime aveugle, n’est-ce point mal? Si vous en présentez une boiteuse ou malade, n’est-ce point mal? Offre - les à ton prince, et tu verras s’il te recevra, s’il accueillera ton visage, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Maintenant priez devant votre Dieu, et adressez-lui votre oraison; mais si de telles offrandes me sont faites par vos mains, pourrai-je bien accueillir vos visages? dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Et cependant chez vous les portes sont fermées, et vous n’allumez pas pour rien le feu de l’autel. Aussi je ne me complais pas en vous, dit le Seigneur tout-puissant, et je n’accueillerai pas le sacrifice de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Du lever du soleil à son coucher, mon nom a été glorifié parmi les gentils; en tout lieu on brûle en mon nom de l’encens et on offre une victime pure (3); parce que mon nom est grand parmi les nations, dit le Seigneur, maître de toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Et ce nom vous le profanez quand vous dites: La table du Seigneur est souillée, et les chairs que l’on y dépose sont méprisables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Vous avez dit encore: Ces offrandes sont le fruit de notre labeur; c’est pourquoi je les ai rejetées avec mépris, dit le Seigneur tout-puissant; car vous me présentez des victimes dérobées, ou boiteuses ou infirmes; et si vous me les offrez en sacrifice, puis-je les accepter de vos mains? dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Maudit soit le riche qui possédait en son bétail un bélier voué au sacrifice, et qui sacrifie au Seigneur une chose corrompue; car moi je suis un grand roi, dit le Seigneur Dieu tout-puissant, et mon nom est éclatant parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Et maintenant voici un ordre pour vous, ô prêtres:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Si vous me désobéissez, et si vous ne mettez pas en vos cœurs qu’il faut glorifier mon nom, dit le Seigneur tout-puissant, je vous enverrai ma malédiction; et votre bénédiction sera maudite, et je la maudirai, et je la rendrai vaine, et la mienne ne sera pas en vous, parce que vous n’aurez point déposé mes paroles en vos cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Voilà que je vous prive de l’épaule des victimes, et je répandrai sur votre face leur fiente, la fiente de vos fêtes, et je vous prendrai en même temps à leur place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Et vous connaîtrez que c’est moi qui vous ai envoyé ce commandement, que mon alliance doit être avec les lévites, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Mon alliance était avec Lévi, une alliance de vie et de paix, et je lui avais donné ma crainte, de sorte qu’à mon nom il était frappé de crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'La loi de vérité était en sa bouche\', et nulle iniquité n’eût été trouvée sur ses lèvres; il marchait avec moi, dirigeant sa voie en paix, et il a détourné du mal nombre d’hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Les lèvres du prêtre doivent garder la doctrine; on cherchera la loi dans les paroles de sa bouche; car il est l’envoyé du Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Mais vous vous êtes retirés de la voie, et vous avez détourné plusieurs de la loi, et vous avez profané l’alliance de Lévi, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Aussi ai-je fait de vous le mépris et le rebut de toutes les nations, parce que vous n’avez point gardé mes voies, mais qu’en la loi vous avez fait acception des personnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'N’avez-vous pas tous un seul père? N’est-ce pas le Dieu unique qui vous a créés? Pourquoi donc chacun de vous a-t-il abandonné son frère en souillant l’alliance de vos ancêtres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Juda a failli, et l’abomination a été en Israël et en Jérusalem, parce que Juda a profané les choses saintes du Seigneur, où Dieu se complaisait, et qu’il s’est attaché à des dieux étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Le Seigneur exterminera tout homme qui fera ainsi pour l’expulser des tentes de Jacob, et le séparer de ceux qui sacrifient au Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Et vous avez fait ce que je déteste; vous avez couvert de larmes l’autel du Seigneur: vous vous êtes frappé la poitrine au milieu des cris et des gémissements. Est-il convenable que je considère vos victimes, ou que j’agrée quelque chose de vos mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Et vous avez dit: Pour quel motif? C’est parce que le Seigneur a porté témoignage entre toi et la femme de ta jeunesse que tu as abandonnée: elle qui était ta compagne; elle qui était la femme de ton alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Ne l’a-t-il pas éternellement créée? n’est-elle pas son esprit? Et tu as dit: Que demande Dieu, sinon des enfants issus de moi? Or garde cette parole en ton esprit: N’abandonne pas la femme de ta jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Mais si, l’ayant haïe, tu la répudies, dit le Seigneur Dieu d’Israël, l’impiété couvrira toutes tes pensées, dit le Seigneur tout-puissant; c’est pourquoi garde cette parole en ton esprit: N’abandonne pas la femme de ta jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'O vous qui, par vos paroles, provoquez Dieu, et qui dites: En quoi l’avons-nous provoqué? C’est en disant: Quiconque fait le mal est bien vu du Seigneur; il se complaît en ceux-là; où donc est le Dieu de la justice?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Voilà que j’envoie mon ange, et il surveillera la voie devant moi, et le Seigneur que vous cherchez viendra soudain dans son temple, avec l’ange de l’alliance que vous avez désiré; le voici, il vient, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Et qui donc aura le pied ferme le jour de sa venue? Qui supportera sa présence? Il vient comme le feu d’une fournaise, ou comme l’herbe à foulons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Il siégera pour fondre et purifier, comme on purifie l’argent et l’or, et il purifiera les fils de Lévi, et il les coulera comme l’or et l’argent. Et ils offriront des victimes au Seigneur selon la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Et les sacrifices de Juda et de Jérusalem seront agréables au Seigneur, comme durant les jours anciens, comme durant les années d’autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Et je m’approcherai de vous en jugement, et je serai un témoin empressé contre les magiciens, contre les femmes adultères, contre ceux qui prennent en vain mon nom, contre ceux qui retiennent le salaire du journalier, contre ceux qui oppriment la veuve, contre ceux qui maltraitent l’orphelin, contre ceux qui faussent le jugement envers l’étranger et n’ont pas la crainte de moi, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Car je suis le Seigneur votre Dieu, et je ne change pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Et vous, fils de Jacob, vous ne vous êtes point abstenus des iniquités de vos pères; vous vous êtes retirés de ma loi, et vous ne l’avez point gardée. Convertissez-vous à moi, et je reviendrai à vous, dit le Seigneur tout-puissant. Et vous avez dit: En quoi nous convertirons-nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Est-ce que l’homme fera tomber Dieu dans ses pièges? Car vous cherchez à me tromper; et vous direz: En quoi cherchons-nous à vous tromper? C’est en retenant pour vous les dîmes et les prémices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Vous m’avez regardé avec mépris, et vous avez cherché à me tromper. L’année est révolue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Et vous avez porté toutes les récoltes dans vos greniers; mais elles seront mises au pillage en chaque maison. Convertissez-vous sur ce point, dit le Seigneur tout-puissant. Et vous verrez alors si je n’ouvrirai pas pour vous les cataractes du ciel, et si je ne répandrai pas sur vous ma bénédiction, jusqu’à ce que vous soyez satisfaits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Et je vous distribuerai votre nourriture, et je n’endommagerai pas les fruits de votre champ, et votre vigne ne souffrira d’aucune maladie dans votre terre, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Et toutes les nations vous estimeront heureux, parce que vous serez une terre bien-aimée, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Vous avez tenu contre moi des discours injurieux, dit le Seigneur, et vous avez dit: En quoi avons-nous parlé contre vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Et vous avez dit: Bien fou qui sert le Seigneur; qu’avons-nous de plus pour avoir gardé ses commandements, et avoir paru comme suppliants devant sa face?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Et maintenant nous estimons heureux les étrangers, ils se sont enrichis à mal faire; ils ont résisté à Dieu et ils ont été sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Mais bien autrement ont parlé les hommes craignant Dieu. Et le Seigneur a été attentif, et il a écouté, et il a écrit un livre, un mémorial devant lui, pour ceux qui craignent le Seigneur et vénèrent son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Et ils seront à moi, dit le Seigneur Dieu tout-puissant, le jour que je ferai naître, pour me les réserver; et je les aimerai comme un homme aime son fils qui le sert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Et vous vous convertirez, et vous distinguerez le juste du méchant; le serviteur de Dieu, de celui qui refuse de le servir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Voilà que le jour approche, brûlant comme une fournaise, et il les consumera; et tous les étrangers et tous ceux qui font le mal seront comme de la paille; et le jour qui approche les dévorera, dit le Seigneur tout-puissant; et il ne restera d’eux ni branche ni racine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Et le soleil de justice se lèvera pour vous qui craignez mon nom; et sur ses ailes il portera le salut; et vous sortirez, et vous bondirez comme de jeunes bœufs délivrés de leurs liens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Et vous foulerez les impies; car ils seront sous vos pieds comme de la cendre, le jour que je ferai naître, dit le Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Et voilà que je vous enverrai Élie le Thesbite, avant que vienne ce jour du Seigneur, jour grand et éclatant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Qui réunira au fils le cœur de son père, à l’homme le cœur de son prochain, de peur que je ne survienne et que je n’anéantisse la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Souvenez-vous de la loi de Moïse, mon serviteur, telle que je la lui ai intimée, en Horeb, devant tout Israël, dans ses commandements et ses préceptes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Vision d’Isaïe, fils d’Amos, qu’il eut sur la Judée et Jérusalem, sous le règne d’Ozias et de Joatham, d’Achaz et d’Ézéchias, qui furent rois de la Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Écoute, ciel; prête l’oreille, terre, parce que le Seigneur a parlé, disant: J’ai engendré des fils, et je les ai élevés en gloire; mais eux, ils m’ont méprisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Le bœuf connaît son possesseur, et l’âne, la crèche de son maître; pour Israël, il m’a méconnu, et son peuple ne m’a pas compris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Malheur à toi, peuple pécheur, nation pleine de péchés, race de méchants, fils pervertis! vous avez abandonné le Seigneur, et irrité le Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'À quoi bon vous frapper encore, en ajoutant à votre iniquité? Toute tête est en souffrance, et tout cœur en tristesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Des pieds à la tête, rien n’est sain en lui, rien qui ne soit contusion, meurtrissure, plaie enflammée; point d’émollients à y appliquer, point d’huile, point de ligature.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Votre terre est déserte, vos villes consumées par le feu; votre contrée, des étrangers la dévorent sous vos yeux; elle est désolée et bouleversée par des nations étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'La fille de Sion sera délaissée comme une tente dans une vigne, comme la cabane d’un garde dans un champ de concombres, comme une ville prise d’assaut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Et si le Seigneur des armées ne nous eût laissé une semence, nous serions comme Sodome, nous ressemblerions à Gomorrhe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Écoutez la parole du Seigneur, princes de Sodome; soyez attentifs à la loi de Dieu, peuple de Gomorrhe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Qu’ai-je besoin de la multitude de vos victimes? Je suis rassasié des holocaustes de béliers; la graisse des agneaux, le sang des taureaux et des boucs, je n’en veux plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Ne venez plus vous montrer à moi; car` qui vous a demandé ces offrandes de vos mains? Ne continuez plus de fouler mon parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Quand vous m’apportez de la fleur de farine, ou un encens inutile, c’est pour moi une abomination. Vos nouvelles lunes, vos sabbats, votre grand jour, je ne puis les souffrir; votre jeûne, votre repos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Vos nouvelles lunes, vos fêtes, mon âme les déteste. Je vous ai en dégoût, je ne vous remettrai plus vos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Si vous étendez la main, je détournerai de vous mes yeux; et si vous multipliez vos prières, je ne vous écouterai pas; car vos mains sont pleines de sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Lavez-vous, soyez purs; ôtez de devant mes yeux la malice de vos âmes; mettez fin à vos méfaits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Apprenez à faire le bien, cherchez la justice, protégez l’opprimé; jugez équitablement l’orphelin, rendez justice à la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Et puis venez m’accuser, dit le Seigneur. Et quand même vos péchés seraient comme la pourpre, je les rendrai blancs comme la neige; et quand ils seraient comme de l’écarlate, je les rendrai blancs comme une toison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Et si vous êtes de bonne volonté, si vous m’écoutez, vous mangerez les biens de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Mais si vous n’êtes point de bonne volonté, si vous ne m’écoutez point, le glaive vous dévorera; car voici ce qu’a dit la bouche du Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Comment est devenue prostituée Sion, la cité fidèle, jadis pleine de justice? L’équité reposait en elle, et maintenant ce sont des meurtriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Votre argent n’est pas de bon aloi; vos cabaretiers mêlent de l’eau à leur vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Vos princes sont incrédules, associés aux voleurs, amis des présents, gagnés par les salaires, sans justice pour les orphelins, sans égard pour la cause des veuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'C’est pourquoi voici ce que dit le Seigneur, maître des armées: Malheur aux puissants d’Israël! car ma fureur contre mes adversaires ne s’apaisera point, et je tirerai vengeance de mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Et je ferai tomber ma main sur toi, et je te purifierai par le feu; et j’exterminerai les incrédules, et j’enlèverai tous les prévaricateurs loin de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Et je rétablirai tes juges comme autrefois, et tes conseillers comme dès le commencement. Et après cela tu seras appelée Ville de justice, métropole fidèle, Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Car ses captifs seront délivrés par le jugement et par la miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Et les méchants seront écrasés, et avec eux les pécheurs; et ceux qui auront abandonné le Seigneur périront avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'C’est pourquoi ils seront confondus par les idoles mêmes qu’ils avaient voulues, et ils rougiront des jardins qu’ils avaient convoités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Car ils seront comme un térébinthe dépouillé de ses feuilles, et comme un jardin sans eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Et leur force sera comme le chaume du concombre, et leurs œuvres comme des étincelles, et les méchants seront consumés, et avec eux le pécheur; et nul ne sera là pour éteindre la flamme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Parole qui vint à Isaïe, fils d’Amos, sur la Judée et sur Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Aux derniers jours la montagne du Seigneur sera glorieuse; sur la cime des monts apparaîtra la maison de Dieu; elle s’élèvera au-dessus des collines, et tous les gentils y viendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Et maintes nations partiront, disant: Allons et montons à la montagne du Seigneur et à la maison du Dieu de Jacob, et il nous annoncera sa voie, et nous y marcherons; car la loi sortira de Sion, et la parole du Seigneur, de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Et il jugera entre les nations, et il réprimandera nombre de peuples. Et de leurs glaives ils forgeront des charrues, et des faux de leurs javelines; et l’on ne tirera plus l’épée nation contre nation, et l’on n’apprendra plus à se faire la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Et maintenant venez, maison de Jacob, et marchons à la lumière du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Car il avait abandonné son peuple, la maison d’Israël; parce qu’au commencement leur terre était remplie de devins et d’augures, comme celle des Philistins, et que beaucoup d’enfants leur étaient nés de femmes étrangères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Leur terre regorgeait d’argent et d’or, et leurs trésors étaient sans nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Et leur pays était couvert de chevaux, et l’on ne pouvait compter leurs chars. Et la terre était remplie de leurs œuvres d’abomination, faites de leurs mains, et ils adoraient des dieux façonnés de leurs doigts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Et l’homme se courbait, et le guerrier s’humiliait; non, je ne leur pardonnerai point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Et maintenant entrez parmi les rochers, et cachez-vous dans la terre devant la crainte du Seigneur, devant sa gloire et sa puissance, lorsqu’il se lèvera pour frapper la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Car les yeux du Seigneur sont en haut, et l’homme en bas. Et la hauteur des hommes sera abattue, et en ce jour le Seigneur seul sera élevé en gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Le jour du Seigneur des armées sera contre tout homme insolent et superbe, contre tout homme altier et orgueilleux, et ils seront abaissés. à la lumière de l’Évangile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Ce jour sera contre le grand cèdre du Liban qui s’élève jusqu’au ciel, et contre le palmier de Basan;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Contre les hautes montagnes et les hautes collines,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Contre les tours altières et les remparts altiers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Contre tous les vaisseaux de la mer, et contre les plus beaux navires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 17, 'Et tout homme sera humilié, et l’orgueil des hommes tombera, et en ce jour le Seigneur sera seul élevé en gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 18, 'Et ils cacheront toutes les idoles, œuvres de leurs mains,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 19, 'Les emportant dans les cavernes, dans les fentes des rochers, dans les profondeurs de la terre, devant la crainte du Seigneur, devant sa gloire et sa puissance, lorsqu’il se lèvera pour frapper la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 20, 'Car ce jour-là l’homme rejettera les abominations d’or et d’argent qu’il aura faites pour adorer de vaines idoles et des oiseaux de nuit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 21, 'En pénétrant dans les creux, dans les cavernes et les fentes des plus durs rochers, devant la crainte du Seigneur, devant sa gloire et sa puissance, quand il se lèvera pour frapper la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Voilà que le Dominateur, Dieu des armées, va enlever de la Judée et de Jérusalem le puissant et la puissante, la force du pain et la force de l’eau;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Le grand, le fort et l’homme de guerre, le juge, le sage et l’ancien;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Le chef de cinquante hommes et le conseiller vénérable, l’habile architecte et l’auditeur intelligent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Et je ferai des jeunes gens leurs princes, et des railleurs les gouverneront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Et le peuple en viendra aux mains, homme contre homme, ami contre ami; l’enfant frappera sur le vieillard, l’infâme sur l’honnête homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'L’homme prendra son frère ou son proche parent dans la famille de son père, et il lui dira: Tu as un manteau, sois notre prince, et que ma nourriture soit dans ta main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Et ce jour-là l’autre répondra: Je ne serai pas ton prince, car il n’y a en ma maison ni pain ni manteau; je ne serai pas le prince de ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Car Jérusalem est ruinée et Juda est tombé; et leurs langues sont avec l’iniquité, et ils n’obéissent point au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'C’est pourquoi leur gloire est maintenant abaissée, et la confusion de leur visage porte témoignage contre eux; et, comme Sodome, ils ont montré et proclamé leur péché. Malheur à leurs âmes! car ils ont pris une funeste résolution contre eux-mêmes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Disant Enchaînons le juste, parce qu’il nous est insupportable. Aussi goûteront-ils les fruits de leurs œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Malheur à l’impie! il lui arrivera mal à cause des œuvres de ses mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Mon peuple, tes exacteurs rapinent et des usuriers te maîtrisent; mon peuple, ceux qui te déclarent heureux t’égarent, et ils bouleversent le sentier où tu marches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Mais maintenant le Seigneur va siéger pour juger, et il entrera en jugement avec son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Le Seigneur en personne entrera en jugement avec les anciens et les princes du peuple. O vous donc, pourquoi avez-vous mis le feu à ma vigne? pourquoi la dépouille du pauvre est-elle en vos maisons?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Pourquoi faites-vous tort à mon peuple? pourquoi couvrez-vous de confusion la face des pauvres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Or voici ce que dit le Seigneur: Parce que les filles de Sion sont altières, et qu’elles ont marché la tête haute, en faisant signe des yeux, et qu’elles ont traîné leurs tuniques du mouvement de leurs pieds, et qu’elles ont eu une démarche étudiée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Dieu humiliera dans Sion les filles du premier rang, et le Seigneur les dépouillera de leurs ornements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Et ce jour-là le Seigneur détruira la gloire de leur parure, leurs réseaux, leurs tresses et leurs épingles d’or,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Et leurs colliers et le fard de leur visage,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Et l’ensemble de leurs joyaux de gloire, bracelets, anneaux, chaînettes, bagues et pendants d’oreilles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Et leurs franges de pourpre et leurs robes de pourpre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Et leurs habits de l’intérieur de la maison, et leurs habits transparents de Laconie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Et leurs robes de fin lin, d’hyacinthe et d’écarlate, et leurs tissus de fin lin, d’or et d’hyacinthe, et leurs longs voiles d’été.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 24, 'Et au lieu de suaves parfums tu te couvriras de cendre; et au lieu de tes rubans tu te ceindras d’une corde; et au lieu d’une tête ornée de bijoux d’or tu auras un crâne chauve, en punition de tes œuvres; et au lieu d’une tunique de pourpre tu te revêtiras d’un cilice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 25, 'Et le fils si beau que tu chéris tombera sous le glaive, et tes forts périront par l’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 26, 'Et ils seront humiliés, et les trésors où tu gardais tes bijoux pleureront; et tu resteras seule, et tu seras brisée contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Et sept femmes prendront un homme, disant: Nous mangerons notre pain, et nous nous revêtirons de robes à nous; seulement que ton nom soit notre nom, ôte-nous notre opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Et ce jour-là Dieu, en son conseil, brillera avec gloire sur la terre, pour relever et glorifier le reste d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Et il arrivera que le reste de Sion, le reste de Jérusalem, tous ceux qui auront été inscrits à Jérusalem dans la vie, seront appelés saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Car le Seigneur lavera la souillure des fils et des filles de Sion; et du sang versé parmi eux i la purifiera en un esprit de justice et un esprit d’ardeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Et voici ce qui arrivera: tout lieu de la montagne de Sion et tout ce qui l’entoure sera ombragé le jour par une nuée qui deviendra la nuit comme une fumée, comme la lumière d’un foyer ardent, et le Seigneur les abritera de toute sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Ce sera comme de l’ombre contre la chaleur, comme une toiture et un abri contre le froid et la pluie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Je chanterai pour mon bien-aimé le cantique que mon bien-aimé chante à ma vigne. Mon bien-aimé avait une vigne, sur une éminence, en un lieu fertile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Et je l’ai entourée d’une haie, et je l’ai palissadée, et je l’ai plantée du plant de Sorec; et au milieu j’ai bâti une tour, où j’ai creusé un cellier; et j’ai compté qu’elle me donnerait du raisin, mais elle a produit des épines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Et maintenant, vous, habitants de Jérusalem, et toi, homme de Juda, jugez entre moi et ma vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Que ferai-je encore pour ma vigne que je n’aie point déjà fait? J’avais compté qu’elle me donnerait du raisin, mais elle a produit des épines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Or je vais maintenant vous déclarer ce que je ferai à ma vigne. Je lui arracherai sa haie, et elle sera mise au pillage; j’abattrai son mur, et elle sera foulée aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Et j’abandonnerai ma vigne, et elle ne sera plus ni taillée ni bêchée; et sur elle s’élèveront des épines comme sur une terre aride, et j’ordonnerai aux nuées de ne jamais l’arroser de pluie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Or la vigne du Seigneur Dieu des armées, c’est la maison d’Israël, et l’homme de Juda est mon nouveau plant bien-aimé. J’ai compté qu’il ferait la justice, et il a fait l’iniquité; et ce n’est pas la voix de l’équité, mais des cris que j’y entends.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Malheur à ceux qui joignent maison à maison, qui rapprochent leur champ d’un autre champ, afin de prendre quelque chose au voisin! est-ce que vous habiterez seuls la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Ces choses sont venues aux oreilles du Seigneur Dieu des armées. Si nombreuses que soient vos maisons, elles seront désertes; quoique grandes et belles, ceux qui les habitent ne seront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Où labourent dix paires de bœufs, on ne récoltera qu’une mesure; et celui qui sème six artabes, n’en retirera que trois mesures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Malheur à ceux qui se lèvent le matin pour boire, et qui boivent jusqu’au soir! car le vin les brûlera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Au son des cithares, des harpes, des tambours et des flûtes, ils boivent du vin; mais les œuvres du Seigneur, ils ne les considèrent pas; les œuvres de ses mains, ils n’y font pas attention.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Aussi mon peuple est-il devenu captif, parce qu’il n’a pas connu le Seigneur; et la faim et la soif en ont fait périr une multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 14, 'Et l’enfer s’en est dilaté l’âme, et il a ouvert sa bouche pour n’en point laisser échapper; et les grands, et les riches, et les hommes en honneur, et les hommes de pestilence, y descendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 15, 'Et l’homme sera humilié, et le guerrier méprisé, et les yeux hautains se baisseront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 16, 'Et le Seigneur sera exalté dans son jugement, et le Dieu saint sera glorifié dans sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 17, 'Et ceux qu’on aura pillés brouteront en paix comme des taureaux, et les agneaux iront paître dans les champs déserts de ceux qu’on aura emmenés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 18, 'Malheur à ceux qui traînent leurs péchés comme avec un long câble, et leurs iniquités comme avec la courroie du joug d’une génisse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 19, 'Et qui disent: Que bientôt advienne ce qu’il doit faire, afin que nous le voyions; que s’accomplisse la volonté du saint d’Israël, afin que nous la connaissions!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 20, 'Malheur à ceux qui appellent mal le bien, et bien le mal; qui donnent aux ténèbres le nom de lumière, et à la lumière le nom de ténèbres; qui tiennent pour amer le doux et pour doux l’amer!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 21, 'Malheur à ceux qui sont sages à leur sens et savants à leurs yeux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 22, 'Malheur à vos puissants qui boivent le vin, et à vos riches qui se préparent une boisson fermentée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 23, 'À ceux qui justifient l’impie à prix d’argent, et qui ne rendent pas justice au juste!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 24, 'À cause de cela, comme le chaume est mis en feu par un charbon embrasé, et consumé par une flamme légère, ainsi leur racine sera réduite en cendres, et leur fleur s’envolera en poussière; car ils n’ont pas voulu de la loi du Seigneur des armées, mais ils ont irrité la parole du Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 25, 'Et le Seigneur des armées a été transporté de colère contre son peuple, et il a étendu sa main sur eux, et il les a frappés. Et les montagnes ont frémi, et les cadavres des hommes ont, comme de la boue, couvert les chemins. Et au milieu de ces fléaux, sa fureur ne s’est point détournée, et sa main est encore levée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 26, 'C’est pourquoi il fera signe aux nations lointaines, et il sifflera pour les appeler des extrémités de la terre, et voilà qu’elles accourent au plus vite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 27, 'Elles ne sentiront ni la faim ni la fatigue; elles ne reposeront point la nuit; elles ne dormiront point; elles ne dénoueront pas la ceinture de leurs reins, et les cordons de leurs sandales ne seront point déliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 28, 'Leurs traits sont acérés, leurs arcs tendus; les pieds de leurs chevaux sont fermes comme le roc, les roues de leurs chars sont comme un tourbillon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 29, 'Elles frémissent comme des lions; elles s’élancent comme des lionceaux. Ce peuple pillera, rugira comme une bête fauve, et il renversera tout, et nul ne pourra lui ravir sa proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 30, 'Et en ce jour il criera contre Israël, comme la voix d’une mer agitée; et ils tourneront leurs yeux vers la terre, et dans leur détresse ils n’y verront que d’affreuses ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Et l’année où mourut le roi Ozias, je vis le Seigneur assis sur un trône élevé au plus haut des cieux, et le temple était plein de sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Et des Séraphins étaient debout autour de lui, et chacun avait six ailes; de deux ailes ils se voilaient la face, et de deux autres les pieds; des deux dernières ils volaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Et ils criaient l’un à l’autre, et ils disaient: Saint, saint, saint est le Seigneur des armées; toute la terre est pleine de sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Et au retentissement de leurs voix le portique se souleva, et le temple se remplit de fumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Et je dis Malheur à moi, parce que je suis percé de douleur, parce que je suis homme, et que j’ai des lèvres impures; j’habite au milieu d’un peuple dont les lèvres sont impures; et le Roi, Seigneur des armées, je l’ai vu de mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Et l’un des Séraphins me fut envoyé, et dans sa main il tenait un charbon qu’avec des pinces il avait pris sur l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Et il m’en toucha la bouche, et il dit: Maintenant que ceci a touché tes lèvres, tes péchés te seront remis, et tu seras purifié de tes iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Et j’entendis la voix du Seigneur, disant: Qui enverrai-je? qui donc ira trouver ce peuple? Et je dis: Me voici, envoyez-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Et il dit: Pars, et dis à ce peuple: Vous entendrez de vos oreilles, et ne comprendrez point; vous regarderez de vos yeux, et ne verrez point;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Car le cœur de ce peuple s’est endurci; et ils ont fait la sourde oreille, et ils ont fermé les yeux, de peur que leurs yeux ne voient, que leurs oreilles n’entendent, que leur cœur ne comprenne, qu’ils ne se convertissent à moi, et que je ne les guérisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Et je dis Jusques à quand, Seigneur? Et il dit: Jusqu’à ce que leurs villes soient désertes faute d’habitants, leurs maisons désertes faute d’hommes, et que leur terre soit abandonnée comme un désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Et après cela Dieu en bannira au loin les hommes; mais ceux qui seront restés sur cette terre se multiplieront;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Et l’on y offrira encore la dîme; et de nouveau elle sera bonne à piller, comme le térébinthe, et comme le gland, quand il est tombé de son enveloppe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Et dans les jours d’Achaz, fils de Joatham, fils d’Ozias, roi de Juda, il arriva que Rasin, roi d’Aram, et Phacée, fils de Romélie, roi d’Israël, marchèrent contre Jérusalem pour lui faire la guerre; mais ils ne purent la tenir assiégée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Et un message fut apporté en la maison de David, disant: Aram est coalisé avec Éphraïm. Et l’âme du roi fut saisie de stupeur, ainsi que l’âme de son peuple; comme dans une forêt les feuilles sont agitées par le vent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Et le Seigneur dit à Isaïe: Va à la rencontre d’Achaz, toi et ton fils Jasub qui te reste; prends le chemin d’en haut dans le champ du Foulon près la piscine;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Et dis au roi: Tiens-toi en repos, et sois sans crainte; que ton âme ne soit pas abattue par ces deux bouts de tison qui fument; car, lorsque le transport de ma colère éclatera, je te guérirai encore une fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Quant au fils d’Aram et au fils de Romélie, parce qu’ils ont conçu un mauvais dessein, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Montons en Judée, et, nous liguant contre eux, soumettons-les à nous, et donnons-leur pour roi le fils de Tabéel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Voici ce que dit le Seigneur des armées: Ce complot ne subsistera pas, il ne s’accomplira point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Mais Damas la capitale de Syrie, et Rasin, roi de Damas. Et soixante-cinq ans encore, le royaume d’Éphraïm cessera d’être un peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Et Samarie, la capitale d’Éphraïm, et le fils de Romélie, de Samarie. Et si vous ne me croyez point, c’est que vous manquerez d’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Et le Seigneur continua de parler à Achaz, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Demande un signe au Seigneur ton Dieu, soit dans le ciel, soit dans l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Et Achaz dit: Non, je ne demanderai rien, et je ne tenterai point le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Et le Seigneur reprit: Écoutez donc, maison de David. Est-ce pour vous si peu de chose que de soutenir une lutte contre des hommes? Et comment soutiendrez-vous une lutte contre Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'C’est pourquoi le Seigneur lui-même vous donnera un signe. Voilà que la Vierge concevra dans son sein, et elle enfantera un fils, et tu lui donneras le nom d’Emmanuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Il mangera du beurre et du miel, avant de savoir discerner le mal ou choisir le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Aussi même avant de connaître le bien et le mal, cet enfant rejettera le mal, pour choisir le bien. Et cette terre, que tu crains, elle sera abandonnée de la présence de ces deux rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Et le Seigneur enverra sur toi, et sur ton peuple,. et sur la maison de ton père, des jours tels qu’il n’en est point venu depuis le jour où Éphraïm a repoussé de Juda le roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Et voici ce qui arrivera: en ce jour le Seigneur sifflera pour appeler les mouches qui dominent sur une partie du fleuve d’Égypte, et les abeilles qui sont dans la région d’Assyrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Et elles viendront toutes dans les vallons de la terre, et dans les creux des rochers, et dans les cavernes, et dans tous les ravins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Ce jour-là, avec un rasoir loué sur les rives du fleuve du roi assyrien, le Seigneur rasera la tête de son peuple, et lui ôtera les poils de ses pieds et de sa barbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Et en ce jour un homme à peine nourrira une vache et deux brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Et, au lieu de boire du lait en abondance, tout homme resté dans la contrée à peine y mangera du beurre et du miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Et en ce jour il arrivera que tout lieu où il y aura eu des milliers de vignes, estimées des milliers de sicles, sera aride et couvert de ronces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'On y entrera avec l’arc et la flèche; parce que toute la terre sera aride et couverte de ronces;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Et toute montagne jadis labourée sera inculte. Et la crainte ne l’envahira plus; car, à cause de son aridité et de ses ronces, ce ne sera plus qu’un pâturage pour les brebis et un passage pour les bœufs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Et le Seigneur me dit: Prends avec toi un grand livre tout neuf, et avec le stylet d’un écrivain écris sur ce livre que l’on ait à recueillir promptement du butin; car voici l’heure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Et assure-toi pour moi de deux témoins fidèles, Urie, et Zacharie, fils de Barachie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Et je m’approchai de la prophétesse, et elle conçut, et elle enfanta un fils, et le Seigneur me dit: Appelle-le de ce nom: Dépouille vite, pille promptement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Car, avant que l’enfant sache dire le nom de son père et de sa mère, il s’emparera des richesses de Damas et des dépouilles de Samarie devant le roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Et le Seigneur continua de me parler:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Puisque ce peuple ne veut point de l’eau de Siloé, qui coule si paisible, mais qu’il veut avoir pour roi Rasin et le fils de Romélie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Voilà que le Seigneur amène sur vous l’eau d’un fleuve profond et impétueux, le roi des Assyriens et sa gloire; et il s’élèvera sur toutes vos vallées, et il foulera aux pieds tous vos remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Et il enlèvera de la Judée tout homme capable de lever la tête, tout guerrier capable de faire un exploit. Et son camp sera assez vaste pour couvrir toute l’étendue de ton pays; mais Dieu est avec nous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Apprenez ceci, ô nations, vous êtes vaincues; prêtez-moi l’oreille jusqu’aux extrémités de la terre; vous êtes fières de vos forces, et vous êtes vaincues; et si vous réunissez de nouvelles forces vous serez de nouveau vaincues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Et quels que soient vos conseils, le Seigneur les dissipera; et quelles que soient vos paroles, elles ne s’accompliront point; car le Seigneur est avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Voici ce que dit le Seigneur: Que d’une main ferme on s’éloigne de la voie de ce peuple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Que l’on ne dise pas: Cela est dur. Toute parole que dit ce peuple est toujours dure. N’aie cependant aucune crainte, et ne sois point dans le trouble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Ne sanctifie que le Seigneur, et que seul il soit l’objet de ta crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 14, 'Et si tu mets en lui ta confiance, il sera ta sanctification; et tu ne te heurteras pas à lui comme à une pierre d’achoppement, comme à une roche qui croule. Mais les maisons de Jacob sont dans un piège, et les habitants de Jérusalem sont dans une fosse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 15, 'C’est pourquoi beaucoup d’entre eux seront sans force, et ils tomberont, et ils seront brisés; ils approcheront du filet, et ils y seront pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 16, 'Alors apparaîtront manifestement ceux qui ont été marqués d’un sceau pour n’avoir pas appris la loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 17, 'Et je dirai: J’attendrai Dieu, qui a détourné sa face de la maison de Jacob, et je mettrai en lui ma confiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 18, 'Et moi, me voici avec les fils que Dieu m’a donnés. Et il y aura des signes et des prodiges dans la maison d’Israël, envoyés par le Seigneur Dieu des armées, qui habite sur la montagne de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 19, 'Et si l’on vous dit: Consultez les magiciens et ceux qui font sortir leur voix de la terre, et les diseurs d’imposture qui parlent du ventre, répondez: Est-ce que chaque nation ne consulte pas son Dieu? Pourquoi consulter les morts au sujet des vivants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 20, 'Car Dieu a donné une loi pour qu’on y ait recours, et qu’on dise Ce n’est pas selon ce précepte, qui interdit de donner pour cela des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 21, 'Et il viendra sur vous une cruelle famine, et, quand vous aurez faim, il arrivera que vous serez dans l’affliction, et vous maudirez le prince et les coutumes de vos ancêtres; et le peuple lèvera les yeux au ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 22, 'Puis il les abaissera vers la terre; et voilà qu’il y aura détresse et ténèbres, tribulation et angoisses; et les ténèbres seront telles qu’on ne verra plus, et celui qui sera dans l’angoisse y sera pour longtemps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Bois d’abord ceci, hâte-toi, terre de Zabulon, et toi, terre de Nephthali, et vous, restes des habitants de la côte, et toi, Galilée des gentils au-delà du Jourdain!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Peuples qui marchez dans les ténèbres, voyez une grande lumière; et vous qui habitez dans la région ténébreuse de la mort, une lumière luira sur vous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Sur vous qui êtes la plus grande part d’un peuple que vous avez amené, Seigneur, à vos joies; et ils se réjouiront de votre vue, comme ceux qui se réjouissent d’une moisson, ou qui se partagent des dépouilles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Parce que vous avez ôté le joug qui pesait sur eux, et la verge qui courbait leur cou. Car le Seigneur a brisé la verge de ceux qui les pressuraient, comme au jour où il s’est déclaré contre Madian.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Ils rendront le prix des robes qu’ils ont accumulées par fraude, et des manteaux qu’ils ont eus par les vicissitudes de la guerre; et ils consentiront à les voir brûlés par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Car un petit enfant nous est né, et un fils nous a été donné; la principauté repose sur son épaule, et il est appelé de ce nom, l’Ange du grand conseil. Par lui j’amènerai la paix sur les princes, par lui la santé et la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Sa principauté est grande, et à la paix qu’il donne il n’est point de limites; il s’assoira sur le trône de David, et il possèdera son royaume, pour le conduire, et l’affermir dans l’équité et la justice, maintenant et dans tous les siècles; l’amour du Seigneur des armées fera ce prodige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Le Seigneur a envoyé la mort contre Jacob, et elle est venue contre Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Et tout le peuple d’Éphraïm et ceux qui résident en Samarie le connaîtront, eux qui disent dans l’orgueil et l’arrogance de leur cœur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Les briques sont tombées, mais venez; taillons des pierres, abattons des sycomores et des cèdres, et bâtissons-nous une tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Et le Seigneur brisera ceux qui s’élèvent contre lui sur la montagne de Sion, et il dispersera les ennemis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'La Syrie à l’Orient, les Hellènes à l’Occident, qui dévorent Israël à pleine bouche. Contre eux tous s’est tournée sa fureur, et sa main est encore levée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Et le peuple ne s’est point converti, et il n’a point cherché le Seigneur, avant d’avoir été frappé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Et en un seul jour le Seigneur a retranché d’Israël la tête et la queue, le grand et le petit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Le vieillard et tous ceux qui n’admirent que les apparences, c’est la tête; et le faux prophète qui enseigne l’iniquité, c’est la queue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Et ceux qui déclarent heureux ce peuple sont dans l’égarement, et ils l’égarent afin de le dévorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'C’est pourquoi le Seigneur ne mettra pas sa joie en leurs jeunes gens, et il n’aura pitié ni de leurs orphelins ni de leurs veuves, parce qu’ils sont tous déréglés et pervers, et que leurs bouches profèrent toutes l’iniquité. Contre eux tous s’est tournée sa fureur, et sa main est encore levée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Et leur iniquité brûlera comme un feu; elle sera consumée par la flamme comme une herbe sèche; elle s’allumera comme une épaisse forêt de chênes, et tout ce qui environne la colline sera dévoré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'À cause de la colère du Seigneur la terre entière sera livrée au feu, et le peuple sera la proie des flammes, et le frère n’aura point pitié de son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Il ira à droite, parce qu’il aura faim; il mangera à gauche, et ne sera point rassasié de la chair de son bras. Car Manassé mangera Éphraïm, et Éphraïm, Manassé, parce qu’ensemble ils auront assiégé Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Contre eux tous s’est tournée sa fureur, et sa main est encore levée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Malheur à ceux qui écrivent l’iniquité! car en écrivant ainsi, c’est l’iniquité qu’ils gravent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'Ils écartent du pauvre là justice, ils arrachent tout moyen de défense aux indigents de mon peuple, afin que la veuve soit pour eux un butin, l’orphelin une proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'Et que feront-ils au jour de la visite du Seigneur? car la tribulation viendra sur vous de loin. Vers qui vous réfugierez-vous pour avoir du secours? Et où cacherez-vous votre gloire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'Pour n’être point entraînés en captivité? Sur vous tous s’est tournée la colère du Seigneur, et sa main est encore levée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Malheur aux Assyriens! la verge de mon courroux, ma colère est dans leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'J’enverrai ma colère contre une nation inique, et je commanderai à mon peuple de recueillir du butin et des dépouilles, de fouler aux pieds les villes et de les réduire en poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Mais lui, telle n’est point sa pensée, tel n’est point le sentiment de son âme. Il mettra son orgueil à exterminer de nombreuses nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Et si elles lui disent: Toi seul es roi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Il répondra: En effet, n’ai-je point pris la contrée au-dessus de Babylone, et Chalane où une tour a été construite? N’ai-je point pris l’Arabie, et Damas, et Samarie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Comme je les ai prises, ainsi je prendrai tous les royaumes. Lamentez-vous, statues de Jérusalem et de Samarie!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Comme j’ai traité Samarie et les dieux fabriqués de ses mains, je traiterai Jérusalem et ses idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Puis voici ce qui arrivera: quand le Seigneur aura achevé d’accomplir ce qu’il veut faire en la montagne de Sion et à Jérusalem, je visiterai ce cœur superbe, ce roi des Assyriens, et la gloire altière de ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Car il a dit: J’agirai dans ma force; et dans la sagesse de mon intelligence j’effacerai les bornes des nations, et je les dépouillerai de leur puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Et j’ébranlerai les villes habitées; et la terre entière, je la prendrai comme un nid dans ma main; et je l’enlèverai comme des œufs abandonnés; car nul ne peut m’échapper ou me contredire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Mais la cognée peut-elle se glorifier sans celui qui s’en sert pour abattre? La scie peut-elle s’enorgueillir sans celui qui la tire? Il faut bien que quelqu’un lève la verge ou le bâton; mais non.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Le Seigneur des armées enverra contre ton honneur le déshonneur, et contre ta gloire il allumera un feu ardent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Et la lumière d’Israël sera cette flamme; elle le sanctifiera avec un feu ardent, et dévorera la forêt comme une herbe sèche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'En ce jour s’évanouiront montagnes, collines et forêts, et la lumière d’Israël dévorera tout, depuis l’âme jusqu’aux chairs. Et celui qui fuira sera comme un homme qui fuit une flamme ardente;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Et ceux qui resteront seront en petit nombre, et un petit enfant pourra les compter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Et en ce jour voici ce qui arrivera: ce qui restera d’Israël, et ceux de Jacob qui auront été sauvés n’auront plus foi en ceux qui leur auront nui; mais ils se confieront en vérité à Dieu, au Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Et ce qui restera de Jacob se confiera au Dieu tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Et quand le peuple d’Israël serait aussi nombreux que le sable de la mer, un reste en sera seul sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Parole abrégée et accomplie avec justice; car cette parole abrégée, le Seigneur l’étendra à toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'À cause de cela, voici ce que dit le Seigneur des armées Ne crains pas, ô mon peuple; habitants de Sion, ne craignez pas l’Assyrien; il te frappera avec une verge; car j’amènerai sur toi cette plaie, pour que tu y reconnaisses la voie d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Encore un peu de temps, et ma colère s’apaisera; mais alors mon courroux se tournera contre les conseils de tes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Et le Seigneur suscitera contre eux une plaie semblable à celle de Madian dans le lieu de l’affliction; et son courroux éclatera comme autrefois contre l’Égypte sur le chemin de la mer Rouge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Et en ce jour voici ce qui arrivera: ton joug sera ôté de ton épaule, et tu seras délivré de ta crainte, et le joug qui pesait sur tes épaules sera réduit en poudre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Il marchera d’abord sur la ville d’Aggaï, passera par Maggédo et déposera à Machma ses appareils de guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Puis il traversera la vallée et entrera dans Aggaï; la terreur saisira Rama, ville de Saul.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'La fille de Gallim prendra la fuite; on l’apprendra à Laïsa, on l’apprendra à Anathoth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Et la stupeur a frappé Madebina, et les habitants de Gibbeïr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Pour vous, consolez-vous aujourd’hui et restez fermes dans la voie; ô vous, collines de Jérusalem, consolez la montagne et Sion, ma fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Voilà que le maître, le Seigneur des armées, va de sa puissance confondre ces glorieux; et les grands seront brisés avec leur orgueil; et les superbes seront humiliés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 34, 'Et les superbes périront par le glaive; et le Liban tombera avec ses cimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Et il sortira un rejeton de la racine de Jessé, et de cette racine une fleur naîtra;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Et sur lui reposera l’Esprit de Dieu, l’esprit de sagesse et d’intelligence, l’esprit de conseil et de force, l’esprit de science et de piété;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'L’esprit de crainte du Seigneur le remplira. Il ne jugera pas selon la gloire; il ne condamnera point selon la rumeur commune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Mais il rendra justice aux humbles, et il relèvera les humbles de la terre; il frappera la terre d’une parole de sa bouche, et d’un souffle de ses lèvres il détruira les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Il se ceindra les reins de justice, et il revêtira ses flancs de vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Et le loup broutera avec l’agneau; et la panthère se reposera avec la chèvre; et le bœuf, le taureau et le lion brouteront ensemble; et un petit enfant les conduira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Ensemble brouteront l’ours et la génisse, ensemble seront leurs petits; et le lion se nourrira de paille comme le bœuf;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Et l’enfant au berceau mettra sa main dans les trous des aspics, dans le nid même de leurs petits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Et ils ne lui feront aucun mal, et ils ne pourront nuire à aucun des miens sur ma montagne sainte; car l’univers est plein de la connaissance du Seigneur, comme les eaux couvrent la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Et en ce jour apparaîtra la racine de Jessé et celui qui s’élèvera pour régner sur les nations, et les nations espéreront en lui, et sa mort fera sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Et en ce jour le Seigneur montrera encore sa main, et il montrera son zèle pour les restes de son peuple, échappés aux Assyriens, à l’Égypte, à Babylone, aux Éthiopiens, aux Élamites, aux peuples du Levant et aux Arabes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Et il élèvera son étendard sur les nations, et il rassemblera les égarés d’Israël, les dispersés de Juda, et il les réunira des quatre ailes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Et la jalousie d’Éphraïm sera détruite, et les ennemis de Juda périront; Éphraïm ne portera plus envie à Juda, et Juda n’affligera plus Éphraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Ils voleront sur les eaux dans les barques des Philistins; ils se feront une proie des peuples de la mer, de ceux de l’Orient et de l’Idumée, et d’abord ils mettront la main sur Moab; mais les fils d’Ammon seront les premiers soumis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Et le Seigneur désolera la mer d’Égypte, et au milieu d’une violente tempête il fera tomber son bras sur le fleuve, et il en frappera les sept bouches, de sorte qu’on les traversera avec des sandales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Et ce sera un passage pour mon peuple resté en Égypte, et il arrivera à Israël comme au temps où il sortit de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'En ce jour-là, Israël, tu diras: Je vous bénis, Seigneur, parce que vous avez été irrité contre moi; puis vous avez détourné votre colère, et vous avez eu pitié de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Voici mon Dieu et mon Sauveur; je mettrai en lui ma confiance, et je serai sans crainte; parce que le Seigneur est ma gloire, il est ma louange, il est mon salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Puisez avec joie l’eau des fontaines du salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Et vous direz en ce jour: Chantez le Seigneur, célébrez son nom, annoncez sa gloire aux gentils; souvenez-vous que son nom est glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Chantez le nom du Seigneur; car il a fait de grandes choses; publiez-les par toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Tressaillez d’allégresse et réjouissez-vous, peuple de Sion; car au milieu de vous a été glorifié le Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Vision d’Isaïe, fils d’Amos, concernant Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Faites flotter l’étendard sur la montagne de la plaine; élevez la voix vers eux, appelez-les de la main; princes, ouvrez vos portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'C’est moi qui les commande, c’est moi qui les conduis; des géants viennent assouvir ma colère, pleins de joie et d’insolence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'On entend sur les montagnes la voix de maintes nations; et la voix de ces rois et de ces nations ressemble à celle d’une multitude assemblée. Le Seigneur des armées a donné ses ordres à une nation belliqueuse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Afin que le Seigneur et ses belliqueux combattants vinssent d’une terre lointaine et des extrémités du monde pour détruire toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Poussez des cris de douleur; car il est proche le jour du Seigneur, où cette destruction viendra de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'C’est pourquoi toute main sera énervée, et toute âme aura peur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Les anciens seront dans le trouble, et ils souffriront des maux comme ceux d’une femme qui enfante; et ils se regarderont l’un l’autre dans une même douleur; et ils seront hors d’eux-mêmes, et ils changeront de visage comme saisis par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Car le voilà qui vient le jour du Seigneur, inévitable, plein de vengeance et de colère, pour rendre la terre déserte et en détruire les pécheurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Car les astres du ciel, Orion, toute la splendeur céleste, ne donneront plus de lumière; et le soleil levant sera voilé de ténèbres, et la lune ne donnera plus sa clarté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Et je punirai les méfaits de toute cette terre et les iniquités de ces impies; et je détruirai l’orgueil des pécheurs, et j’humilierai l’orgueil des superbes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Et ceux qui resteront seront plus rares que l’or naturel, et un de ces hommes sera plus rare que la pierre d’Ophir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Car le ciel sera irrité, et la terre ébranlée dans ses fondements par la colère terrible du Seigneur des armées au jour où surviendra sa colère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 14, 'Et ceux qui resteront fuiront comme un jeune chevreuil, comme une brebis errante, et nul ne sera là pour les réunir; et chacun retournera chez son peuple, chacun s’enfuira dans son pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 15, 'Quiconque sera surpris seul sera opprimé, et ceux qui seront réunis périront par le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 16, 'Et sous leurs yeux on écrasera leurs enfants; on pillera leurs maisons, on violera leurs femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 17, 'Voici que je vais susciter contre vous les Mèdes, qui comptent pour rien l’argent, et n’ont pas besoin d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 18, 'Ils briseront les arcs des jeunes hommes, ils seront sans pitié pour vos enfants; et vos fils, ils ne les épargneront point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 19, 'Ainsi en sera-t-il de Babylone, que le roi des Chaldéens appelle glorieuse, comme de Sodome et de Gomorrhe, que Dieu a renversées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 20, 'Elle ne sera plus jamais habitée, et l’on n’y rentrera plus durant de longues générations; et les Arabes ne la traverseront plus, et les pasteurs ne viendront plus s’y reposer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 21, 'Mais les bêtes fauves s’y reposeront, et ses maisons seront pleines de leurs cris; les dragons y feront leur séjour, et les démons y danseront;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 22, 'Et les onocentaures y habiteront, et les hérissons feront leurs nids dans leurs demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Le moment arrive, et il ne tardera point, où le Seigneur aura pitié de Jacob, où Israël sera encore son élu; alors ils reposeront dans leur terre, et l’étranger viendra se joindre à eux, et s’unira à la maison de Jacob,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Et les gentils se les adjoindront et ils les introduiront dans leur pays; et les enfants d’Israël auront leur héritage, et y multiplieront leurs serviteurs et leurs servantes; et ceux qui les avaient tenus captifs seront leurs captifs à leur tour, et ceux qui les avaient dominés seront dominés par eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Et voici ce qui arrivera en ce jour: le Seigneur apaisera ta douleur, et ton humiliation, et la dure servitude à laquelle ils t’avaient assujetti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Et tu composeras cette lamentation sur le roi de Babylone: Comment est mort cet exacteur? Comment est mort ce maître impitoyable?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Le Seigneur a brisé le joug des impies, le joug des dominateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Il a frappé avec colère cette nation d’une plaie incurable, puis il l’a renversée dans sa colère et ne l’a point épargnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Et toute la terre s’est reposée avec confiance et a poussé des cris de joie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Et les arbres du Liban se sont réjouis de ta chute; et le cèdre du Liban, depuis que tu es mort, dit: Celui qui nous abattait ne monte plus ici!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'L’enfer en ses abîmes s’est troublé à ton approche; et ils se sont levés ensemble contre toi, tous les géants, jadis princes de la terre, qui faisaient descendre de leurs trônes tous les rois des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Ils te parleront tous et te diront: Te voilà pris comme nous, et te voilà l’un des nôtres!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Ta gloire et ta longue prospérité sont descendues aux enfers; la pourriture est ta couche, les vers ta couverture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Comment est tombée des cieux l’étoile du matin qui se levait dès l’aurore? Comment a été brisé contre terre celui qui commandait à toutes les nations?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Tu disais dans ton cœur: Je monterai au ciel; je placerai mon trône au- dessus des astres; je m’assoirai sur une haute montagne, sur ces hautes montagnes qui s’étendent vers l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Je monterai au-dessus des nuages; je serai semblable au Très-Haut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Et maintenant tu es descendu en enfer, et jusqu’aux fondements de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Ceux qui t’ont vu seront étonnés de ta chute, et ils diront: Voilà cet homme qui exaspérait la terre, qui ébranlait, les rois;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Qui avait fait de toute la terre une solitude, qui en détruisait les cités, et qui ne délivrait pas ceux qu’il avait faits captifs..18. Tous les rois des nations se sont endormis dans la mort, tous avec honneur et dans leurs palais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Mais toi, tu seras jeté dans les montagnes, comme un cadavre impur, avec une multitude de morts percés du glaive et descendus aux enfers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Comme un manteau souillé de sang ne peut être pur, ainsi tu seras impur; et parce que tu as désolé ma terre et tué mon peuple, toi, semence perverse, tu ne subsisteras pas longtemps!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Prépare tes enfants pour qu’on les égorge en punition du péché de leur père; qu’ils ne se relèvent pas, qu’ils n’héritent pas de leur royaume, qu’ils ne remplissent pas la terre du bruit de leurs batailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Et je m’élèverai contre eux, dit le Seigneur des armées, et je détruirai leur nom, leurs restes et leur race. Voilà ce que dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Et je ferai de la Babylonie un désert, une demeure pour les hérissons; et je la réduirai au néant; et j’en ferai pour la perdre un abîme de fange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Or voici ce que dit le Seigneur des armées: Comme j’ai dit, il sera fait; ce que j’ai résolu s’accomplira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Je détruirai les Assyriens sur ma terre et sur mes montagnes; et ils seront foulés aux pieds; et mon peuple sera délivré de leur joug, et leur gloire à eux sera enlevée de leurs épaules.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Voilà le dessein que le Seigneur a décrété sur toute la terre, et voilà sa main levée sur toutes les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Et ce que le Dieu saint a décrété, qui pourra s’y opposer? Sa main levée, qui la détournera?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'C’est l’année où mourut le roi Achaz que cette parole a été prédite:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Ne vous réjouissez pas, ô Philistins, de ce que le joug de celui qui vous frappait a été brisé; car d’une race de serpents sortira une famille d’aspics, et de cette famille sortiront des serpents ailés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Et les pauvres seront nourris par le Seigneur; les pauvres se reposeront en paix; tandis qu’il fera mourir de faim ta race, et détruira tes restes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Poussez des cris de douleur, portes des cités; que vos villes, ô Philistins, jettent des cris d’épouvante; car de l’aquilon vient un tourbillon de fumée, et nul ne peut y échapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Moab périra pendant la nuit; c’est la nuit que périront les murs de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Affligez-vous sur vous-mêmes; car Dibon, où était votre autel, périra. Montez-y pour pleurer sur Nabau, ville des Moabites. Poussez des cris de douleur; là toutes les têtes sont chauves, là tous les bras sont coupés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Dans les rues ceignez-vous de cilices, pleurez sur les terrasses, sur les places et dans les faubourgs; gémissez tous et pleurez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Ésebon et Éléalé ont jeté des cris, el jusqu’à Jassa leur clameur a été entendue; c’est pourquoi les reins de Moab crient, et son âme va s’instruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'Moab crie en son cœur jusqu’à Ségor; comme une génisse de trois ans sur la montée de Luith, ainsi vers toi, vaine idole, ils monteront pleurant par la voie d’Aroniim; ils crieront misère et désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'L’eau de Nemrim sera tarie, et son gazon séchera, et l’herbe n’y verdira plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Est-ce que Moab s’attend à être sauvé? Je conduirai les Arabes dans sa vallée, et ils la prendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Les cris de Moab retentissent jusqu’à ses frontières, et celles mêmes d’Agalim et ses hurlements vont jusqu’au puits d’Élim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'L’eau de Dimon sera pleine de sang; car je conduirai les Arabes sur Dimon, et j’anéantirai la semence de Moab, Ariel et les restes d’Adama.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'J’enverrai comme des reptiles sur la terre. La montagne de Sion, ma fille, n’est-elle pas une roche déserte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Comme le petit oiseau enlevé à sa mère, ainsi tu seras, fille de Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'À ton tour, Arnon, prends plus mûrement conseil, fais à Moab un abri pour y pleurer toujours; ils voudraient l’ombre pour fuir en plein midi, et ils sont dans la stupeur. Si tu veux échapper à la captivité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'O Moab, que mes fugitifs demeurent chez toi; et ils seront pour toi un refuge aux yeux de ton persécuteur; car ton auxiliaire t’est ravi; il a péri le prince qui foulait la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Mais un trône sera érigé avec miséricorde, et un roi y siégera avec vérité dans le tabernacle de David, jugeant et cherchant la justice, et plein de zèle pour l’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Nous avons appris l’insolence de Moab; son insolence était extrême, et je l’ai abattue; et ses divinations ne se sont point accomplies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Moab poussera des hurlements de douleur, tous les Moabites verseront des pleurs; médite sur les habitants de Seth, et tu ne seras point confondue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Les champs d’Ésebon et la vigne de Sebama seront dans le deuil. O vous qui dévorez les nations, foulez aux pieds les vignes de Sebama jusqu’à Jazer; ne venez pas en foule, errez dans le');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'C’est pourquoi je pleurerai la vigne de Sebama, comme ceux de Jazer la pleurent. Ésebon et Éléalé ont jeté bas tes arbres, ô Moab, et moi, je foulerai tes blés au temps de la moisson, et tes ceps au temps de la vendange; et tout tombera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Et la joie et les fêtes seront enlevées à tes vignes, et dans tes vignes il n’y aura plus de réjouissances; et on ne foulera plus le vin dans tes pressoirs, car il n’y aura plus de vendange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'C’est pourquoi mes entrailles pleureront sur Moab comme une cithare; Seigneur, vous avez tout renouvelé en moi, comme un mur en ruines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Et il arrivera pour sa confusion que Moab, lassé de ses autels, ira vers les idoles fabriquées de ses mains, et il les priera; mais elles ne pourront le sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Telle est la prédiction que le Seigneur a prononcée sur Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Et maintenant je dis: Dans trois ans, trois ans d’homme à gages, la gloire de Moab sera confondue avec toutes ses nombreuses richesses; et il n’échappera qu’un petit nombre de ses enfants, et ils seront sans honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 1, 'Voilà que Damas va être retranchée du nombre des villes; elle sera en ruines,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 2, 'Abandonnée pour toujours; les menus troupeaux s’y reposeront, et nul ne sera là pour les en chasser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 3, 'Et il n’y aura plus de forteresse où Éphraïm puisse se réfugier; et il n’y aura plus de royauté pour Damas, ni pour le reste des Syriens. Car tu ne vaux pas mieux que les fils d’Israël; ta gloire ne vaut pas mieux que leur gloire voilà ce que dit le Seigneur des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 4, 'En ce jour, la gloire de Jacob sera obscurcie, et les richesses qui font sa gloire seront ébranlées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 5, 'Et ce sera comme lorsque un homme glane ou ramasse les grains des épis dans une vallée féconde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 6, 'Et des glanures y ont été laissées, comme les trois ou quatre olives de rebut qu’on laisse à la cime de l’arbre, comme les quatre ou cinq qui restent au bout des branches: voilà ce que dit le Seigneur, Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 7, 'Ce jour-là, l’homme mettra sa confiance en son Créateur; il tournera ses yeux vers le Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 8, 'Et ils ne croiront plus à leurs autels, ni aux ouvrages de leurs mains que leurs doigts ont façonnés; ils ne regarderont plus leurs bois sacrés ni leurs abominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 9, 'En ce jour tes villes seront abandonnées, comme le furent celles des Amorrhéens et des Hévéens, en présence des fils d’Israël; et elles seront désertes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 10, 'Parce que tu as délaissé Dieu ton Sauveur, et que tu ne t’es plus souvenu du Seigneur qui t’avait secouru; et, à cause de cela, tu planteras des arbres trompeurs et des graines infidèles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 11, 'Le jour où tu planteras, tu seras déçu. Si tu sèmes le matin, ta semence fleurira pour être moissonnée le jour où tu laisseras ton héritage, et où, comme le père de l’homme, tu distribueras ton patrimoine à tes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 12, 'Malheur à la multitude des nations! Comme une mer agitée, ainsi vous serez bouleversées; et leurs armes retentiront sur leur dos, comme des vagues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 13, 'Cette multitude ressemblera à des flots tumultueux, à des ondes emportées par le vent. Le Seigneur exterminera le peuple assyrien, et il le rejettera au loin, comme au moindre souffle vole la paille légère des vanneurs, ou le tourbillon de poussière que soulève un ouragan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 17, 14, 'Sa douleur durera jusqu’au soir, et avant l’aurore il ne sera plus. Tel sera le partage de ceux qui ont fait de vous leur proie; tel sera l’héritage de ceux qui ont pris possession de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 1, 'Malheur à la terre fière de ses barques ailées, au delà des fleuves de l’Éthiopie!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 2, 'À cette terre, qui envoie des otages par la mer et des lettres sur les eaux! Car des messagers rapides s’en iront vers une nation superbe, vers un peuple étranger et cruel. Qui habite au delà? Une nation désespérée et foulée aux pieds. Alors les fleuves de leur terre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 3, 'Seront tous habités comme une région habitée. Leur terre sera comme un signal élevé sur la montagne, comme le son d’une trompette qui se fait entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 4, 'Car le Seigneur m’a ainsi parlé: Il y aura sécurité dans ma ville, comme la lumière à l’ardeur de midi, comme le nuage de rosée un jour de moisson,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 5, 'Avant la coupe des blés, quand la fleur est passée, que le raisin hors de fleur commence à mûrir, et que les fleurs sont devenues des grains. Alors le Seigneur ôtera les jeunes pousses avec la faux, et il arrachera les sarments et il les coupera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 6, 'Et il les abandonnera aux oiseaux du ciel et aux bêtes fauves de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 7, 'Et tous les oiseaux du ciel viendront s’y rassembler, et toutes les bêtes fauves de la terre accourront contre l’Éthiopien. En ce temps-là, des présents seront offerts au Seigneur, Dieu des armées, par un peuple contrit et opprimé, par un grand peuple, maintenant et par tous les siècles. Et c’est ce peuple qui espère aujourd’hui, que l’on foule aux pieds, qui habite la terre de ce côté du fleuve, dans le lieu où réside le nom du Seigneur, sur la montagne de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 1, 'Voici que le Seigneur s’est assis sur une nuée légère, et il arrivera en Égypte, et les idoles de l’Égypte seront ébranlées devant sa face, et elle faiblira au fond de son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 2, 'Et les Égyptiens s’élèveront contre les Égyptiens, et le frère combattra le frère, ami contre ami, ville contre ville, nom contre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 3, 'Et l’esprit des Égyptiens sera troublé en eux-mêmes, et je dissiperai leurs conseils; et ils interrogeront leurs dieux, et leurs statues, et ceux qui font sortir leurs voix de la terre, et les magiciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 4, 'Et je livrerai l’Égypte aux mains de maîtres cruels, et des rois cruels y régneront: voilà ce que dit le Seigneur Dieu des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 5, 'Et les Égyptiens boiront de l’eau près de la mer; car leur fleuve tarira, et il sera desséché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 6, 'Et les fleuves tariront et les canaux du fleuve; et tout amas d’eau sera desséché, et tous les marais où croissent le roseau et le papyrus;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 7, 'Et le gazon verdoyant au bord du fleuve; et tout ce qui est semé le long du fleuve sera flétri et desséché par le vent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 8, 'Et les pêcheurs gémiront; et ils gémiront tous ceux qui jettent l’hameçon dans le fleuve; et ceux qui jettent des seines et des filets pleureront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 9, 'Et ceux qui travaillent le lin et le byssus, ou qui font des robes, seront confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 10, 'Et tous les artisans seront dans la douleur, et ceux qui font la bière seront attristés, et ils souffriront en leur âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 11, 'Et les princes de Tanis, sages conseillers du roi, deviendront fous; leur conseil sera folie. Comment pourrez-vous dire au roi: Nous sommes les fils des sages, les fils des anciens rois?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 12, 'Où sont maintenant tes sages? Qu’ils prophétisent, et qu’ils disent: Qu’a résolu contre l’Égypte le Seigneur Dieu des armées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 13, 'Les princes de Tanis ont défailli; ceux de Memphis se sont enorgueillis, et ils ont égaré l’Égypte en toutes ses tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 14, 'Car le Seigneur a répandu sur eux un esprit d’erreur, et ils ont égaré l’Égypte en toutes ses œuvres, et ils l’ont fait marcher comme un homme ivre qui vomit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 15, 'Et les Égyptiens ne feront plus rien qui ait une tête et une queue, un commencement et une fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 16, 'Et, en ce jour, les Égyptiens seront comme des femmes effrayées et tremblantes sous la main du Seigneur des armées, qu’il fera tomber sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 17, 'Et la terre de la Judée sera pour les Égyptiens un objet de terreur; et quiconque prononcera son nom devant eux les frappera de crainte, à cause des desseins que le Seigneur des armées a formés sur eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 18, 'Ce jour-là, il y aura cinq villes d’Égypte qui parleront la langue de Chanaan, et jureront par le Seigneur Dieu des armées. L’une de ces villes s’appellera Asédec.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 19, 'Ce jour-là, il y aura sur le territoire d’Égypte un autel du Seigneur, et à sa frontière une colonne élevée au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 20, 'Et ce sera un signe éternel au Seigneur en la terre d’Égypte. Dès lors ils crieront au Seigneur dans leurs tribulations, et il leur enverra un homme pour les sauver; et il les sauvera en les jugeant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 21, 'Et le Seigneur sera connu des Égyptiens. Et les Égyptiens en ce jour connaîtront le Seigneur, et ils lui sacrifieront des victimes, et ils lui feront des vœux, et ils les accompliront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 22, 'Et le Seigneur frappera d’une plaie les Égyptiens, puis il la guérira; et ils se convertiront au Seigneur, et il les exaucera, et il leur enverra une entière guérison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 23, 'En ce jour, il y aura une voie de l’Égypte à l’Assyrie; et les Assyriens entreront en Égypte; et les Égyptiens iront en Assyrie, et ils seront asservis aux Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 24, 'En ce jour, Israël sera la troisième avec les Égyptiens et les Assyriens, et il sera béni sur la terre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 19, 25, 'Que le Seigneur des armées a bénie, disant: Béni soit mon peuple qui est en Égypte et qui est en Assyrie; et béni soit Israël mon héritage!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 20, 1, 'L’année que Tanathan entra dans Azot, quand il y fut envoyé par Arna, roi des Assyriens, et qu’il assiégea la ville et s’en empara;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 20, 2, 'Le Seigneur parla à Isaïe, fils d’Amos, disant: Pars, et ôte le cilice de tes reins; dénoue les sandales de tes pieds, et fais comme je te dis; voyage nu et déchaussé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 20, 3, 'Et le Seigneur dit: Comme mon serviteur Isaïe a voyagé trois ans nu et déchaussé, pour être pendant trois ans un sujet de signes et de prodiges pour les Éthiopiens et les Égyptiens;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 20, 4, 'Ainsi le roi des Assyriens emmènera une foule de captifs de l’Égypte et de l’Éthiopie, jeunes et vieux, nus, déchaussés, laissant à découvert la honte de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 20, 5, 'Alors les Israélites rougiront à juste titre des Éthiopiens, en qui ils espéraient; car ils avaient mis leur gloire en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 20, 6, 'Et en ce jour les habitants de cette terre diront: Voilà que nous avions cru trouver en eux un refuge et un secours, et ils n’ont pu se sauver du roi des Assyriens; comment nous sauverons-nous nous-mêmes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 1, 'Comme une tempête venant de la terre passe de désert en désert, ainsi terrible');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 2, 'Et épouvantable une vision m’a été révélée: Le prévaricateur marche à ses prévarications, l’homme inique à ses iniquités. Sur moi viennent les Élamites, sur moi les anciens des Perses. Maintenant je gémirai et je me consolerai moi- même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 3, 'Voilà pourquoi mes reins ont défailli, et des douleurs comme celles de l’enfantement m’ont saisi. Ce que j’entends me fait mal, et je fais tout pour ne pas voir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 4, 'Mon cœur s’égare, l’iniquité m’inonde, mon âme succombe dans la terreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 5, 'Dressez la table, mangez, buvez. Levez-vous, princes, préparez vos boucliers;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 6, 'Car voici ce que m’a dit le Seigneur: Va, place-toi en sentinelle, et ce que tu verras, publie-le.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 7, 'Et je vis deux cavaliers: un cavalier monté sur un âne, un autre sur un chameau. Écoute avec une grande attention,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 8, 'Et appelle Urie au lieu d’observation. Ainsi dit le Seigneur. Et moi je me tins debout tout le jour, et je surveillai le camp toute la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 9, 'Et voilà que vint à moi un homme sur un char à deux chevaux. Et, répondant à ma demande, il dit: Elle est tombée, elle est tombée, Babylone; et toutes ses statues et toutes les œuvres de ses mains sont brisées contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 10, 'Écoutez, ô vous qui êtes délaissés; et vous qui pleurez, écoutez ce que j’ai appris du Seigneur Dieu des armées, ce que m’a annoncé le Dieu d’Israël. VISION DE L’IDUMÉE');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 11, 'On me crie de Séir: Gardez les créneaux!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 12, 'Je les garde dès le matin et durant la nuit. Si tu cherches un secours, cherche-le bien, et demeure près de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 13, 'Tu dormiras le soir dans la forêt sur le chemin de Daïdan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 14, 'Portez de l’eau à la rencontre de l’homme qui a soif; et vous qui habitez la terre de Théman, portez des pains au-devant de ceux qui fuient;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 15, 'Multitude d’hommes massacrés, multitude d’égarés, multitude de glaives et d’arcs tendus, multitude de guerriers tombés dans le combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 16, 'Car voici ce que m’a dit le Seigneur: Encore une année, une année de mercenaire, et la gloire des fils de Cédar sera effacée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 21, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 1, 'D’où vient que maintenant vous êtes montés sur vos terrasses, disant de vaines paroles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 2, 'La ville est pleine de clameurs; tes blessés ne sont pas blessés par le glaive, et tes morts ne sont pas morts en combattant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 3, 'Tous tes princes sont en fuite; tes captifs sont durement enchaînés, et tes forts se sont réfugiés au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 4, 'Et c’est pourquoi j’ai dit: Laissez-moi et je pleurerai amèrement; ne cherchez pas à me consoler, quand vient d’être brisée la fille de mon sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 5, 'Car le jour du trouble et de la ruine, où tout est brisé et s’égare, vient du Seigneur Dieu des armées. Ils errent dans la vallée de Sion; du petit au grand ils errent sur les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 6, 'Les Élamites ont pris leurs carquois; les cavaliers sont à cheval, les armées se rassemblent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 7, 'Et tes vallons préférés seront remplis de chars, et des cavaliers envahiront les portes de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 8, 'Et ils en ouvriront les portes; et ce jour-là ils pénétreront dans les demeures choisies de la cité; et, dans la citadelle de David, ils découvriront les endroits les plus cachés des maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 9, 'Et ils ont vu combien elles sont nombreuses, et comme on a détourné l’eau de l’ancienne piscine pour l’amener dans la ville,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 10, 'Et comme on a abattu les maisons de Jérusalem pour fortifier ses remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 11, 'Et ainsi pour vous-mêmes, vous avez fait venir l’eau entre les deux enceintes, plus avant que l’ancienne piscine; mais vous n’avez point considéré celui qui, dès le principe, a bâti la ville, et vous n’avez point vu son Créateur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 12, 'Et le Seigneur, le Seigneur des armées, vous a en ce jour appelés à pleurer et à gémir, à vous raser la tête et à vous ceindre de cilices;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 13, 'Mais eux, ils étaient en joie et en plaisirs à égorger des veaux, à immoler des brebis, à manger de la chair et à boire du vin, disant: Mangeons et buvons, car nous mourrons demain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 14, 'Et ces choses ont été révélées aux oreilles du Dieu des armées; car ce péché ne vous a pas été remis jusqu’à votre mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 15, 'Voici donc ce que dit le Seigneur Dieu des armées: Va trouver, au vestibule du temple, Somna, le trésorier, et dis-lui:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 16, 'Pourquoi es-tu ici, et qu’y fais-tu? Pourquoi as-tu taillé ici ton sépulcre? pourquoi l’as-tu placé sur un lieu élevé, et y as-tu creusé pour toi un lieu de repos?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 17, 'Voilà qu’à présent le Seigneur Dieu des armées va chasser et briser cet homme; il va t’enlever ta robe');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 18, 'Et ta couronne de gloire, et il te jettera dans une grande et immense campagne, et là tu mourras; et Dieu fera de ton char brillant un objet de honte, et le palais de ton prince sera foulé aux pieds;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 19, 'Et tu seras renversé de ton rang et de ton ministère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 20, 'Et ce jour-là j’appellerai mon serviteur Éliacim, fils d’Helcias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 21, 'Et je le revêtirai de ta robe, et je lui donnerai ta couronne avec l’empire, et je confierai ton ministère à ses mains, et il sera comme un père pour ceux qui résident à Jérusalem et habitent en Judée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 22, 'Et je lui donnerai la gloire de David, et il gouvernera, et il n’aura point de contradicteur; et je mettrai sur son épaule la clef de la maison de David; il ouvrira, et nul ne fermera; il fermera, et nul n’ouvrira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 23, 'Et je l’établirai prince en un lieu sûr, et il sera comme un trône de gloire pour la maison de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 24, 'Et tout homme en honneur dans la maison de son père, du petit au grand, mettra sa confiance en lui, et tous dépendront de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 22, 25, 'En ce jour, voilà ce que dit le Seigneur Dieu des armées: L’homme qui avait été établi en un lieu sûr, y sera ébranlé; il en sera arraché, et il tombera, et sa gloire sera anéantie; parce qu’ainsi l’a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 1, 'Poussez des cris de douleur, vaisseaux de Carthage; car elle a péri, et ses matelots ne reviendront plus de la terre des Citiens; elle a été emmenée captive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 2, 'À qui sont-ils devenus semblables ces habitants de l’île, ces trafiquants de Phénicie, qui traversaient la mer');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 3, 'Sur les grandes eaux, cette race de marchands? Comme une moisson qu’on emporte, ainsi ils trafiquaient des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 4, 'Rougis, Sidon, a dit la mer; et la force de la mer a dit: Je n’ai point enfanté, je n’ai point mis au monde, je n’ai point nourri de fils, je n’ai point élevé de vierges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 5, 'Or quand l’Égypte apprendra ces choses, elle sera saisie de douleur à cause de Tyr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 6, 'Allez à Carthage, poussez des cris de douleur, ô vous qui habitez cette île.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 7, 'N’est-ce pas elle qui faisait votre orgueil depuis les premiers temps, avant d’avoir été livrée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 8, 'Qui a résolu ces choses contre Tyr? Comment estelle amoindrie? comment est- elle sans force? Ses marchands étaient renommés, c’étaient les princes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 9, 'Le Seigneur a résolu d’abattre l’orgueil de tous ces glorieux, et d’humilier leur superbe sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 10, 'Travaille maintenant à la terre; car il ne vient plus chez toi de vaisseaux de Carthage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 11, 'Ta main ne prévaut plus sur la mer, cette main qui irritait les rois. Le Seigneur Dieu des armées a donné un ordre contre Chanaan pour que sa force fût détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 12, 'Et l’on dira: Vous ne continuerez plus à outrager et à maltraiter la fille de Sidon. Et quand tu t’en iras chez les Citiens, tu n’y trouveras plus le repos,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 13, 'Ni dans la terre des Chaldéens; elle aussi a été désolée par les Assyriens, car son rempart est tombé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 14, 'Poussez des cris de douleur, vaisseaux de Carthage, parce que votre force a péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 15, 'Et il arrivera ce jour-là que Tyr sera abandonnée durant soixante-dix ans, le temps que vit un homme, le temps que vit un roi; et après ces soixante-dix ans, Tyr chantera comme une courtisane.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 16, 'Prends la cithare, cours à l’aventure, ville prostituée, livrée à l’oubli; joue bien, chante beaucoup, pour qu’on se souvienne de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 17, 'Et après ces soixante-dix ans le Seigneur visitera Tyr, et il la rétablira comme autrefois, et elle sera un marché pour tous les royaumes qui couvrent la face de la terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 23, 18, 'Et son commerce et ses revenus seront consacrés au Seigneur; et ce n’est point pour eux qu’ils amasseront, mais pour ceux qui résident devant le Seigneur; et tous ses gains seront employés à manger et à boire, et à se rassasier dans des banquets commémoratifs devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 1, 'Voilà que le Seigneur va dévaster la terre; il va la rendre déserte; il va dévoiler sa face et disperser ceux qui habitent en elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 2, 'Et le peuple sera comme le prêtre, le serviteur comme le maître, et la servante comme la maîtresse; le marchand sera comme l’acheteur, le prêteur comme l’emprunteur, et le débiteur comme le créancier');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 3, 'La terre sera entièrement détruite, la terre sera entièrement dépouillée; car la bouche du Seigneur a dit ces choses:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 4, 'La terre est dans le deuil, le monde est désolé, les grands de la terre ont pleuré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 5, 'Elle a péché par ceux qui l’habitent, parce qu’ils ont transgressé la loi et altéré les commandements de l’éternelle alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 6, 'C’est pourquoi une malédiction consumera cette terre en punition du péché de ceux qui l’habitent. C’est pourquoi ses habitants seront pauvres, et il n’y restera qu’un petit nombre d’hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 7, 'Le vin pleurera, la vigne pleurera; et ils gémiront, tous ceux qui avaient l’âme en joie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 8, 'Il a cessé, le bruit joyeux des tambours; elle a cessé, la voix de la cithare.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 9, 'Les hommes sont confondus; ils ne boivent plus de vin, et la bière est pleine d’amertume pour ceux qui en boivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 10, 'Toute la ville est déserte; elle ferme ses maisons pour qu’on n’y puisse entrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 11, 'Partout elle crie pour avoir du vin; toute joie sur la terre a cessé, toute joie est partie de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 12, 'Et les villes seront inhabitées, et les maisons vides crouleront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 13, 'Toutes ces choses arriveront sur la terre au milieu des nations. Et de même que l’on secoue un olivier, ainsi seront-elles secouées. Et si la vendange s’arrête,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 14, 'Ils pousseront de grandes clameurs; mais ceux qui auront été épargnés sur la terre se réjouiront tous ensemble de la gloire du Seigneur, et la mer en sera troublée dans ses eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 15, 'C’est pourquoi la gloire du Seigneur ira jusqu’aux îles de la mer, le nom du Seigneur y sera glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 16, 'Seigneur Dieu d’Israël, des extrémités de la terre nous avons appris vos prodiges, vous, espérance de l’homme pieux. Et l’on dira: Malheur aux prévaricateurs qui transgressent la loi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 17, 'La peur, l’abîme et les pièges sont pour vous qui habitez la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 18, 'Et voici ce qui arrivera: celui qui fuira de peur tombera dans l’abîme; et celui qui sortira de l’abîme sera pris au piège; car les cataractes du ciel seront ouvertes, et les fondements de la terre en seront ébranlés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 19, 'La terre sera pleine de trouble, la terre sera pleine d’angoisse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 20, 'Elle s’est détournée de sa voie comme un homme ivre et débauché; elle sera chancelante comme la cabane du gardien des vergers; et parce que l’iniquité a prévalu en elle, elle tombera et ne pourra se relever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 21, 'Et le Seigneur étendra sa main sur l’armée du ciel et sur les rois de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 22, 'Et la grande Synagogue de la terre sera réunie et jetée en prison; et la forteresse sera fermée; et après plusieurs générations ils seront visités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 24, 23, 'Et la brique sera liquéfiée, et le mur croulera; parce que le Seigneur régnera du haut de Sion et de Jérusalem, et en présence des anciens il sera glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 1, 'Seigneur Dieu, je vous glorifierai, je louerai votre nom, parce que vous avez fait des choses merveilleuses, selon votre conseil antique, fondé sur la vérité. Ainsi soit-il.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 2, 'Vous avez réduit des villes en des monceaux de ruines, des villes fortes, dont les fondations ne devaient point faillir; la ville des impies ne sera point réédifiée dans l’avenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 3, 'C’est pourquoi un peuple pauvre vous bénira, et les villes des hommes vous béniront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 4, 'Car vous êtes le protecteur de toute humble cité, vous êtes l’abri du pauvre en son indigence; vous les sauverez des méchants, vous, abri de ceux qui ont soif, vous, rafraîchissement des opprimés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 5, 'Nous étions défaillants dans Sion, comme des hommes consumés par la soif, à cause des impies auxquels vous nous avez livrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 6, 'Et le Seigneur Dieu des armées préparera un festin pour tous les gentils; sur cette montagne ils boiront la joie, en buvant le vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 7, 'Ils se parfumeront de myrrhe sur cette montagne. Donnez toutes ces choses aux gentils; car sur les gentils repose le conseil de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 8, 'La mort, ayant prévalu, dévorera les hommes, et de nouveau le Seigneur séchera les larmes de tous les visages; il effacera sur toute la terre l’opprobre de son peuple; car la bouche du Seigneur a parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 9, 'Et en ce jour on dira: Voici notre Dieu, en qui nous espérons, il nous sauvera. Voici le Seigneur, c’est lui que nous attendions; et nous avons tressailli d’allégresse, et nous nous réjouirons en Celui qui est notre salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 10, 'Dieu donnera le repos à cette montagne, et il foulera Moab à ses pieds, comme l’aire sous les chars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 11, 'Et le Seigneur étendra sur lui ses mains, comme quand il abat un homme pour le perdre; ainsi il abattra sa superbe, en étendant ses mains sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 25, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 1, 'En ce jour-là, on chantera ce cantique en la terre de Juda: Voilà une ville forte, son mur et son avant-mur seront notre salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 2, 'Ouvrez les portes; laissez entrer un peuple qui garde la justice et garde la vérité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 3, 'Qui reçoive la vérité et maintienne la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 4, 'C’est en vous qu’ils ont éternellement espéré, Seigneur, Dieu grand et éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 5, 'C’est vous qui avez humilié et fait descendre ceux qui habitaient les hauts lieux. C’est vous qui renverserez les villes fortes, et les égalerez au sol.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 6, 'Et les doux et les humbles les fouleront aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 7, 'La voie des hommes pieux est droite; la voie des hommes pieux leur a été d’avance préparée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 8, 'Car la voie du Seigneur est la justice. Nous avons espéré en votre nom dans le souvenir et le désir de notre âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 9, 'Avant l’aurore, mon esprit s’élève vers vous, ô mon Dieu, parce que vos commandements sont la lumière du monde. Apprenez la justice, vous qui habitez la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 10, 'Car c’en est fait de l’impie. Quiconque sur la terre n’apprend pas la justice ne pratiquera pas la vérité. Que l’impie disparaisse, afin de ne point voir la gloire du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 11, 'Seigneur, votre bras est levé, et ils ne le savaient pas, et, le sachant, ils seront confondus. La jalousie saisira ce peuple ignorant, et le feu dévorera les ennemis du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 12, 'Seigneur, notre Dieu, donnez-nous la paix; car vous nous avez tout donné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 13, 'Seigneur, notre Dieu, prenez possession de nous; Seigneur, nous ne connaissons pas d’autre Dieu que vous, d’autre nom que votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 14, 'Les morts ne verront point la vie, les médecins ne les ressusciteront pas. C’est pourquoi vous les avez visités, vous les avez punis, vous leur avez enlevé tous leurs enfants mâles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 15, 'Ajoutez à leurs maux, Seigneur, ajoutez aux maux des superbes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 16, 'Seigneur, dans l’affliction je me suis souvenu de vous; vous nous frappez d’une affliction légère pour nous instruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 17, 'Et comme une femme en mal d’enfant et près d’être délivrée pousse des cris en sa douleur, ainsi avons-nous fait pour votre bien-aimé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 18, 'Nous avons conçu dans votre crainte, Seigneur, nous avons été dans les douleurs de l’enfantement, et nous avons enfanté votre esprit de salut, et par lui nous avons produit des œuvres sur la terre. Nous ne tomberons pas; mais ils tomberont ceux qui habitent la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 19, 'Les morts ressusciteront, et ceux qui sont dans leurs sépulcres se lèveront, et ceux qui sont sur la terre tressailliront de joie; car la rosée qui vient de vous est leur guérison, et la terre des impies périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 20, 'Va, mon peuple, entre dans ton appartement secret, ferme ta porte, cache-toi un peu, bien peu de temps, jusqu’à ce que la colère du Seigneur soit passée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 26, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 1, 'En ce jour-là Dieu tirera son épée sainte, sa grande et forte épée, contre le dragon fuyant, contre le dragon aux replis tortueux, et il tuera le dragon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 2, 'Et ce jour-là il y aura un beau vignoble, et le désir de chanter sur la vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 3, 'Je suis une ville forte, une ville assiégée; vainement je lui porterai à boire. Car elle sera prise la nuit, et le jour ses murs tomberont; il n’est point de femme qui ne s’en soit emparée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 4, 'Qui me placera pour garder la récolte dans un champ? À cause de cet état de guerre, je l’ai négligée. C’est pourquoi le Seigneur a fait toutes les choses qu’il avait ordonnées. J’ai été brûlée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 5, 'Ses habitants crieront: Faisons la paix avec lui, faisons la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 6, 'Ceux qui viennent sont des enfants de Jacob. Et Israël germera, et il fleurira, et la terre sera remplie de son fruit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 7, 'Est-ce que Dieu les frappera, comme il a frappé? Les tuera-t-il comme il a tué les autres, et qu’ils les auront réduits en poudre, et que leurs arbres n’existeront plus, et que leurs idoles seront abattues, comme leurs grands bois sacrés.</ref>?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 8, 'Il les renverra avec des paroles de reproche et de colère. N’est-ce pas vous qui, dans un esprit de dureté, vouliez les tuer du souffle de votre courroux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 9, 'À cause de cela l’iniquité de Jacob lui sera remise; et cela même sera pour lui une bénédiction, puisque je lui remettrai ses péchés lorsqu’ils auront brisé les pierres');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 10, 'Le troupeau qui demeure la sera épars comme un troupeau abandonné; et il restera longtemps au pâturage, et le bétail s’y reposera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 11, 'Et à la longue il ne trouvera plus d’herbe, à cause de la sécheresse. Femmes qui venez de voir un tel specfacle, approchez; car ce peuple est sans intelligence. À cause de cela, celui qui les a formés sera pour eux sans miséricorde; celui qui les a formés ne leur pardonnera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 12, 'Et ce jour-là Dieu parquera les hommes depuis le lit du fleuve jusqu’au Rhinocorure. Et vous, rassemblez un à un les fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 27, 13, 'Et ce jour-là on sonnera à grand bruit de la trompette; et ceux qui étaient perdus en Assyrie, et ceux qui étaient perdus en Égypte reviendront, et ils adoreront le Seigneur sur la montagne sainte, en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 1, 'Malheur à la couronne d’orgueil, ô mercenaires d’Éphraïm; fleur qui tombe de sa gloire sur la cime de la montagne fertile; hommes ivres sans vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 2, 'Voilà que la colère du Seigneur est violente et terrible, comme la grêle tombant où il n’y a point d’abri, tombant avec force comme une inondation qui ravage une');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 3, 'Et les pieds sera foulée votre couronne d’orgueil, ô mercenaires d’Éphraïm!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 4, 'Et la fleur détachée de l’espérance de votre gloire, sur la cime de la haute montagne, sera comme le premier fruit mûr du figuier; celui qui l’aura vu, avant que sa main l’ait saisi, désirera le dévorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 5, 'Ce jour-là, le Seigneur Dieu des armées sera une couronne d’espérance, et comme une guirlande de gloire, pour le reste de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 6, 'Ils seront restés en esprit de justice pour rendre la justice, et détruire les forces de ceux qui les entravent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 7, 'Car ils ont été entraînés au péché par le vin; ils ont été égarés par les boissons fermentées; prêtres et prophètes ont perdu le sens, à cause des boissons fermentées; ils ont été absorbés par le vin; ils ont chancelé dans l’ivresse, ils ont erré: telle est ma vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 8, 'La malédiction consumera leurs conseils; car leurs conseils sont nés de la cupidité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 9, 'À qui avons-nous prédit ces maux? à qui avons-nous porté ce message? À vous qui venez d’être sevrés, vous qu’on vient de retirer de la mamelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 10, 'Attendez affliction sur affliction, espérance sur espérance; encore un peu de temps, encore un peu de temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 11, 'Avec des lèvres dédaigneuses, en une langue étrangère, Dieu parlera à ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 12, 'Il lui dira: Voici le repos de celui qui a faim, et voilà son affliction; et ils n’ont pas voulu écouter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 13, 'Et la prédiction du Seigneur sera pour eux: affliction sur affliction, espérance sur espérance; encore un peu de temps, encore un peu de temps; afin qu’ils partent, et qu’ils tombent à la renverse; et ils seront broyés, et ils seront pris au piége, et ils périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 14, 'À cause de cela, écoutez la parole du Seigneur, hommes opprimés, et vous, princes de ce peuple qui est en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 15, 'Vous disiez: Nous avons fait un pacte avec l’enfer, et des conventions avec la mort; s’il passe un tourbillon impétueux, il ne viendra pas sur nous; nous avons fait du mensonge notre espérance, nous serons abrités par le mensonge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 16, 'À cause de cela, ainsi dit le Seigneur, voilà que je mets dans les fondations de Sion une pierre de grand prix, une pierre choisie et précieuse; c’est la pierre angulaire et honorable des fondations; et celui qui croira en elle ne sera point confondu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 17, 'Et je rendrai un jugement, pour qu’il soit une espérance; et ma miséricorde sera pesée avec mesure; et vainement ils seront appuyés sur le mensonge; si le tourbillon a passé près de vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 18, 'Est-ce parce que Dieu n’a pu rompre votre alliance avec la mort, ni l’espérance que vous placiez sur l’enfer? Si le tourbillon impétueux passe, il vous foulera aux pieds;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 19, 'S’il passe, il vous prendra dès l’aurore; dès l’aurore il passera, et il durera tout le jour, et la nuit votre attente sera pire encore. Instruisez-vous à comprendre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 20, 'O vous qui êtes tourmentés, vous dites: Nous ne pouvons combattre, nous sommes trop faibles pour nous rassembler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 21, 'Le Seigneur s’élèvera contre vous, comme contre la montagne des impies, et il se tiendra dans la vallée de Gabaon; et il fera ses œuvres avec colère, œuvres d’amertume; et il agira avec un courroux qui lui est étranger, et il vous frappera d’une plaie qui lui est étrangère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 22, 'Gardez-vous de vous réjouir et de rendre plus forts vos liens; car j’ai appris du Seigneur Dieu des armées les œuvres accomplies et prochaines qu’il fera par toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 23, 'Prêtez l’oreille, écoutez ma voix, soyez attentifs et recueillez mes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 24, 'Est-ce que le laboureur laboure toute la journée? Ne prépare-t-il pas la semence avant de travailler à la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 25, 'Après en avoir aplani la surface, ne sème-t-il pas de la poivrette et du cumin? Ne sème-t-il pas ensuite du froment, de l’orge, du millet, de l’épeautre, selon ses desseins?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 26, 'Or tu seras instruit par le jugement de ton Dieu, et tu te réjouiras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 27, 'Car la poivrette n’est point nettoyée durement; on ne fait point passer les roues d’un char sur le cumin\'; mais on bat la poivrette avec une verge;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 28, 'Et on mange le cumin avec du pain. Ainsi moi, je ne serai pas éternellement irrité contre vous, et la voix de mon amertume ne vous écrasera point toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 28, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 1, 'Malheur à la ville d’Ariel, que David a combattue Assemblez vos récoltes; encore une année, puis une année, ensuite vous mangerez, vous mangerez avec Moab.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 2, 'Car je briserai Ariel; sa force et sa richesse seront à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 3, 'Et je t’investirai comme a fait David, et je t’entourerai de palissades, et j’élèverai des tours autour de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 4, 'Et tes paroles tomberont à terre; et tes paroles seront enfouies dans la terre; et ta voix sera comme celle des hommes qui la font sortir de terre, et tu n’auras qu’un filet de voix à rase terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 5, 'Mais la richesse des impies sera comme la poussière que soulèvent des roues, et la multitude de ceux qui t’oppriment, comme le duvet emporté par le vent. Et ce sera comme un moment insaisissable,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 6, 'Soudain, venu du Seigneur Dieu des armées; car sa visite sera accompagnée de tonnerres, de tremblements de terre et de grands bruits; tourbillon impétueux, flamme dévorante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 7, 'Et la richesse de toutes les nations qui auront attaqué Ariel, et tous ceux qui auront combattu Jérusalem, et tous ceux qui se seront réunis contre elle et l’auront opprimée seront comme le songe d’un homme qui s’éveille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 8, 'Comme ceux qui, dans le sommeil, boivent et mangent, et ils s’éveillent, et c’était un vain songe; comme un homme qui s’était endormi altéré rêve qu’il boit, et se réveille avec sa soif, voyant que son âme a espéré en vain telle sera la richesse de tous les gentils qui auront porté les armes contre la montagne de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 9, 'Soyez dans l’étonnement, soyez hors de vous, et chancelez d’ivresse, non à cause des boissons fermentées ou du vin;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 10, 'Mais parce que le Seigneur vous a abreuvés d’un esprit de componction; et il vous fermera les yeux, et il aveuglera vos prophètes, vos princes et vos voyants, instruits des choses cachées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 11, 'Et toutes ces choses seront pour vous comme les paroles de ce livre scellé que l’on donne à un homme qui sait lire, en lui disant: Lis cela; et il dit: Je ne puis, car il est scellé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 12, 'Et on donne ce livre à un homme qui ne sait pas lire, en lui disant: Lis cela; et il dit: Je ne sais lire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 13, 'Et le Seigneur a dit: Ce peuple s’approche de moi en parole, et il m’honore des lèvres; mais son cœur est loin de moi. Ils m’honorent en vain, enseignant la science et les maximes des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 14, 'À cause de cela, voilà que je vais encore transporter ce peuple; je les transporterai, et je perdrai la sagesse des sages, et je tromperai la prudence des prudents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 15, 'Malheur à ceux qui approfondissent leurs conseils, mais non avec le Seigneur! Malheur à ceux qui méditent en secret! ils feront leurs œuvres dans les ténèbres, et ils diront: Qui nous a vus? et qui saura ce que nous faisons?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 16, 'Ne serez-vous pas comptés comme l’argile du potier? Est-ce que l’ouvrage dira à l’ouvrier: Tu ne m’as point façonné? Est-ce que l’œuvre dira à l’artisan: Tu ne m’as pas faite avec intelligence?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 17, 'Est-ce que dans peu de temps le Liban ne sera point changé comme le mont Carmel? Est-ce que le mont Carmel ne sera pas réputé une forêt?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 18, 'Et en ce jour les sourds entendront les paroles du livre, avec ceux qui sont dans les ténèbres et ceux qui sont dans les brouillards. Les yeux des aveugles verront;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 19, 'Et à cause du Seigneur les pauvres tressailliront d’allégresse, et les hommes désespérés seront rassasiés de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 20, 'L’injuste n’est plus, le superbe a péri; ceux qui méchamment s’écartaient de la loi ont été exterminés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 21, 'Ainsi que ceux qui, par leurs discours, entraînaient les hommes à pécher; et on tiendra à scandale tous ceux qui tendaient des pièges aux portes de la ville, parce qu’ils auront conduit le juste dans l’injustice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 22, 'À cause de cela, voici ce que dit le Seigneur sur la maison de Jacob, qu’il avait retranchée d’Abraham: Jacob ne sera plus confondu, il ne changera plus de visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 23, 'Mais lorsque mes enfants auront vu mes œuvres, pour l’amour de moi, ils sanctifieront le Saint de Jacob, et ils craindront le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 29, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 1, 'Malheur à vous, enfants rebelles! dit le Seigneur; vous avez tenu conseil, et ce n’est pas avec moi; vous avez pris des résolutions, et ce n’est pas avec mon Esprit; vous entassez péchés sur péchés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 2, 'Ô vous qui êtes partis pour descendre en Égypte, sans me consulter, pour demander du secours au Pharaon, et trouver un abri chez les Égyptiens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 3, 'Car l’appui du Pharaon sera pour vous une honte; et l’opprobre attend ceux qui se reposent sur l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 4, 'Car vos princes sont allés à Tanis, messagers de malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 5, 'Ils ont pris une peine inutile auprès d’un peuple qui ne les aidera point pour le secours, mais pour la confusion et l’opprobre. VISION DES QUADRUPÈDES');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 6, 'Ils vont dans l’affliction et la détresse, là où il y a un lion et un lionceau, et d’où viennent aussi des aspics et des petits d’aspics volants; ils ont transporté sur des ânes et des chamelles leurs richesses près d’une nation qui ne les aidera point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 7, 'Les Égyptiens vous donneront un secours vain et inutile; dis-leur: Cette consolation pour vous est vaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 8, 'Maintenant donc, assieds-toi; écris ces choses sur le buis et dans un livre; car ce sera pour les jours de l’avenir et même pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 9, 'Parce que ce peuple est indocile; fils menteurs, qui ne veulent point écouter la loi de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 10, 'Ils disent aux prophètes: Ne nous annoncez rien; ils disent à ceux qui ont des visions: Ne nous parlez pas; mais annoncez-nous quelque autre erreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 11, 'Détournez-nous de cette voie; ôtez-nous le sentier, ôtez-nous l’oracle d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 12, 'À cause de cela, voici ce que dit le Saint d’Israël: Parce que vous n’avez point obéi à ces paroles, parce que vous avez espéré dans le mensonge, parce que vous avez murmuré et que vous avez mis votre confiance en vos murmures;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 13, 'À cause de cela, ce péché sera pour vous comme un mur qui s’écroule soudain, lorsque est prise une ville dont la chute est inopinée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 14, 'Et sa chute sera comme quand on brise un vase de poterie; les fragments en sont tels qu’on n’y peut trouver un tesson à transporter du feu, ou à puiser un peu d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 15, 'Voici ce que dit le Seigneur, le Seigneur saint d’Israël: Lorsque après t’être perverti tu te lamenteras, tu seras sauvé, et tu sauras où tu étais; car tu croyais en des vanités, des vanités étaient ta force, et tu n’as pas voulu m’entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 16, 'Mais vous avez dit: Nous fuirons à cheval; à cause de cela, vous fuirez. Vous avez dit: Nous serons sur des chevaux agiles; à cause de cela, ils seront agiles aussi les chevaux qui vous poursuivront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 17, 'Mille des vôtres fuiront à la voix d’un seul ennemi; une multitude fuira à la voix de cinq hommes, jusqu’à ce que vous restiez comme un mât sur une montagne, ou comme la hampe qui porte un étendard sur une colline.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 18, 'Et Dieu vous attendra encore pour vous prendre en compassion; et en cela il signalera sa gloire en vous faisant miséricorde; car le Seigneur votre Dieu est le juge. Heureux ceux qui l’attendent!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 19, 'Car le peuple saint demeurera en Sion, et Jérusalem pleurera à chaudes larmes, disant: Ayez pitié de moi! Et le Seigneur aura pitié de toi, quand il t’aura vue crier et qu’il t’aura entendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 20, 'Et le Seigneur vous donnera le pain de l’affliction et l’eau de la détresse; et ceux qui t’égarent n’approcheront plus de toi; car tes yeux verront ceux qui t’égarent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 21, 'Et tes oreilles entendront les discours de ceux qui, derrière toi, t’auront égarée, disant: Voici la voie, suivons-la, soit à droite, soit à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 22, 'Alors tu souilleras les idoles argentées, et tu réduiras en poudre les idoles d’or, et tu les jetteras au loin comme l’eau des menstrues, et tu les repousseras comme la fange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 23, 'Alors il tombera de la pluie sur les grains que tu auras semés; alors le pain des fruits de la terre sera plantureux et succulent. Et en ce jour tout bétail broutera dans des pâturages spacieux et fertiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 24, 'Et vos taureaux et vos bœufs de labour mangeront de la paille assaisonnée d’orge vannée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 25, 'Et en ce jour l’eau coulera sur toute haute montagne, sur toute colline élevée, lorsque beaucoup d’hommes auront péri et que leurs tours seront tombées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 26, 'Et la lumière de la lune sera comme la lumière du soleil; et la lumière du soleil sera septuple durant le jour, lorsque le Seigneur aura pansé les meurtrissures de son peuple, et guéri les douleurs de ses plaies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 27, 'Voici que le nom du Seigneur arrive après un long temps; sa fureur est ardente; la parole de ses lèvres est pleine de gloire; sa parole est pleine de colère, et les transports de sa fureur dévorent comme le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 28, 'Et son souffle, comme l’eau qui se précipite dans un vallon, montera jusqu’au cou; et il se divisera pour troubler les nations au sujet de leurs vaines erreurs; et l’erreur aussi les poursuivra, et les prendra en face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 29, 'Ne devrez-vous pas alors être toujours en joie, et toujours entrer dans mes lieux saints, comme aux jours de fête? Ne devrez-vous pas, comme ceux qui se réjouissent, venir au son des flûtes sur la montagne du Seigneur, devant le Dieu d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 30, 'Et le Seigneur fera entendre sa voix glorieuse, et la fureur de son bras, qui se manifestera par des transports de colère et une flamme dévorante; sa foudre éclatera violemment comme de l’eau et de la grêle qui tombe avec impétuosité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 31, 'Car les Assyriens seront vaincus à la voix du Seigneur, par la plaie dont il les frappera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 32, 'Et c’est là ce qui lui arrivera de tous les alentours, de toute contrée d’où il espérait du secours, et en qui il se confiait; les peuples, au contraire, viendront le combattre au son des tambours et des cithares.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 30, 33, 'Car vous serez requis avant le temps, Seigneur; tout n’est-il pas préparé pour votre règne, un ravin profond, des arbres abattus, le feu et un vaste bûcher? La colère du Seigneur est comme une vallée embrasée par le soufre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 1, 'Malheur à vous qui descendez en Égypte pour chercher du secours, et qui mettez votre confiance en des chevaux et des chars, parce que les chars sont nombreux et que la multitude des cavaliers est grande! Ils n’ont point eu foi au Saint d’Israël, et ils n’ont point cherché le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 2, 'Et dans sa sagesse il leur à envoyé les maux prédits; et sa parole ne sera pas trompée; il s’élèvera contre les maisons des hommes pervers, et contre leur vaine espérance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 3, 'En un Égyptien, il y à un homme et non un Dieu; en des chairs de chevaux, il n’y à pas de secours; le Seigneur portera la main sur eux; et leurs auxiliaires seront défaillants, et ils périront tous à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 4, 'Car voici ce que m’a dit le Seigneur: De même qu’un lion ou un lionceau rugit sur la proie qu’il a saisie, et crie jusqu’à ce qu’il ait rempli de sa voix les montagnes; alors les animaux sont abattus, et cette colère les fait tous trembler: ainsi le Seigneur Dieu des armées descendra pour combattre sur la montagne de Sion, sur ses montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 5, 'Tel un oiseau étend les ailes, tel le Seigneur couvrira Jérusalem; il la protégera et lui fera miséricorde;* il prendra soin d’elle et la sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 6, 'Convertissez-vous, fils d’Israël, qui avez formé au fond de vos cœurs un conseil impie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 7, 'Car ce jour-là les hommes renonceront aux idoles d’or, aux idoles d’argent, œuvres de leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 8, 'Et Assur tombera; ce n’est pas le glaive d’un guerrier, ce n’est pas le glaive d’un homme qui le dévorera, et il ne fuira pas devant la face d’un glaive; et ses jeunes hommes seront en servitude;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 31, 9, 'Ils seront entourés de pierres comme d’une palissade, et ils seront défaits; et quiconque essayera de fuir sera pris. Voici ce que dit le Seigneur: Heureux celui qui à sa race en Sion, et sa demeure en Jérusalem!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 1, 'Voilà qu’un roi juste va régner, et que les princes gouverneront selon la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 2, 'Et ce sera un homme cachant ses discours, et il se cachera comme on se détourne d’une eau rapide; et il apparaîtra dans Sion comme un fleuve qui coule glorieux sur une terre altérée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 3, 'Et le peuple ne mettra plus sa confiance en des hommes; mais ils prêteront l’oreille pour écouter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 4, 'Et le cœur des faibles sera attentif à s’instruire; et les langues mêmes qui bégayent apprendront vite à prononcer des paroles de paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 5, 'Et alors on ne dira plus à l’insensé: Règne, et tes serviteurs ne te diront plus: Tais-toi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 6, 'Car l’insensé parlera follement, et son cœur méditera des vanités; il ne pensera qu’à mal faire, à tromper le Tout-Puissant, à disperser les âmes affamées, à renvoyer vides les âmes altérées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 7, 'Car le conseil des méchants projettera des choses iniques, pour détruire les petits avec des paroles injustes, et ruiner dans le jugement la cause des humbles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 8, 'Cependant les hommes pieux ont délibéré des choses sensées, et tel leur conseil demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 9, 'Femmes riches, levez-vous et soyez attentives à ma voix; filles, écoutez mes paroles avec confiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 10, 'Gardez-en la mémoire durant une année entière, dans une douleur mêlée d’espérance. La vendange est détruite, elle à cessé, elle ne reviendra plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 11, 'Soyez stupéfaites, soyez tristes, vous si confiantes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 12, 'Frappez vos poitrines, à cause des moissons regrettées de vos champs, et des fruits de vos vignes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 13, 'La terre de mon peuple ne produira plus que des ronces et de mauvaises herbes; et de toute demeure la joie sera bannie. Cette ville opulente');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 14, 'Et ses maisons sont délaissées; ils abandonneront les richesses de la ville et leurs maisons si convoitées. Les bourgs seront à jamais des cavernes, délices des ânes sauvages, abri pour les pasteurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 15, 'Jusqu’à ce que sur vous vienne l’Esprit d’en haut. Et le Carmel devenu désert sera réputé une forêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 16, 'Et la justice habitera dans le désert, et l’équité résidera sur le Carmel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 17, 'Et la paix sera l’œuvre de l’équité, et la justice vivra en repos, et le peuple aura confiance jusqu’à la fin des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 18, 'Et le peuple du Seigneur habitera en assurance la ville de la paix, et il s’y reposera au sein de la richesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 19, 'Et si la grêle tombe, ce ne sera pas sur vous, et ceux qui habiteront la forêt seront en sûreté comme ceux de la plaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 32, 20, 'Heureux ceux qui sèment des terres arrosées, que le bœuf et l’âne foulent aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 1, 'Malheur à ceux qui vous affligent! Que nul ne vous rende misérables; que celui qui vous méprise cesse de vous mépriser. Ceux qui vous comptent pour rien seront');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 2, 'Seigneur, faites-nous miséricorde; car nous avons eu confiance en vous; la race des incrédules est allée à sa perte; notre salut viendra au temps de la tribulation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 3, 'À votre voix redoutable, les peuples ont eu peur de vous, et ils ont été hors d’eux-mêmes, et les gentils se sont dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 4, 'Maintenant on recueillera vos dépouilles, celles du petit comme celles du grand; tel un homme ramasse des sauterelles, ainsi on se jouera de vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 5, 'Le Saint, le Seigneur Dieu, qui réside au plus haut des cieux, À rempli Sion de justice et d’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 6, 'Ils se soumettront à la loi; notre salut est dans ses trésors; c’est là que la sagesse, la science et la piété sont auprès du Seigneur; ce sont là les trésors de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 7, 'Voilà qu’ils vont avoir peur de vous, ceux que vous craigniez; ils crieront à cause de vous; des messagers seront envoyés, pleurant amèrement et implorant la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 8, 'Car toutes leurs voies seront désertes; la crainte qu’inspiraient les gentils est calmée: l’alliance avec eux est rompue; vous ne les compterez plus parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 9, 'La terre est en deuil; le Liban est confondu; Saron cst devenu un marécage; la Galilée et le Carmel sont à découvert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 10, 'Alors je me lèverai, dit le Seigneur; alors je serai loué, je serai glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 11, 'Vous verrez alors, et vous comprendrez; votre force d’esprit sera vaine, et le feu vous dévorera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 12, 'Et les nations seront consumées, comme les ronces d’un champ qu’on arrache et qu’on brûle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 13, 'Ceux qui demeurent au loin apprendront ce que j’aurai fait; ceux qui sont près de moi connaîtront ma force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 14, 'Les pécheurs sont partis de Sion, un tremblement à saisi les impies. Qui vous annoncera que le feu est allumé? Qui vous fera connaître le séjour éternel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 15, 'Celui qui marche dans la justice, qui parle avec droiture, qui hait les transgressions et l’iniquité, qui de ses mains repousse les présents, qui fait la sourde oreille quand on excuse l’effusion du sang, qui ferme les yeux pour ne pas voir le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 16, 'Celui-là résidera dans une grotte élevée en une roche inexpugnable. Là on lui donnera des vivres et de l’eau toujours fidèle à couler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 17, 'Vous verrez le roi dans sa gloire, vos yeux verront de loin la terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 18, 'Et votre âme s’occupera de l’objet de sa crainte. Où sont les scribes? Où sont les conseillers? Où est celui qui apprenait à compter les petits enfants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 19, 'On ne verra plus un peuple, grands et petits, sans sagesse, parlant une langue inconnue, qu’un peuple ne pourrait ni ouïr ni comprendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 20, 'Voici la ville de Sion, notre salut; tes yeux verront Jérusalem, riche cité; ses tabernacles ne chancelleront pas; les pieux de son tabernacle demeureront inébranlables dans les siècles des siècles, et ses cordages ne se rompront jamais;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 21, 'Parce que le nom du Seigneur est grand pour vous pour vous il y aura une contrée, des fleuves et des canaux larges et spacieux. Mais toi, tu ne prendras pas cette voie; le navire que poussent tes rameurs ne la prendra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 22, 'Car mon Dieu est grand; le Seigneur mon juge ne me dédaignera pas; le Seigneur est notre roi, le Seigneur est notre prince: c’est le Seigneur qui nous sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 23, 'Tes cordages sont rompus, parce qu’ils n’avaient pas de force; ton mât penche, il ne fera descendre pas les voiles; il n’élèvera pas le signal, jusqu’à ce que le navire soit livré au pillage. Et beaucoup de boiteux même y feront du butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 33, 24, 'Et l’on ne dira pas parmi le peuple qui y demeure: Je suis trop las; car leur péché leur à été remis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 1, 'Approchez, nations; princes, écoutez; que la terre soit attentive, et ceux qui l’habitent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 2, 'Parce que la colère du Seigneur éclate contre toutes les nations, son courroux menace leur multitude; il les perdra et les livrera au meurtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 3, 'Leurs blessés tomberont avec leurs morts; et l’odeur s’en répandra dans l’air, et les montagnes seront humectées de leur sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 4, 'Et toute la milice des cieux dépérira, et le ciel sera roulé comme un livre, et toutes les étoiles tomberont comme des feuilles de vigne, comme les feuilles d’un figuier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 5, 'Mon glaive s’est enivré dans les cieux; voilà qu’il va fondre sur l’Idumée, et sur un peuple justement condamné à périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 6, 'Le glaive du Seigneur s’est rempli de sang; il s’est alourdi de graisse, du sang des boucs et du sang des agneaux, de la graisse des boucs et de la graisse des béliers; car le sacrifice du Seigneur est en Bosor, et une grande immolation de victimes en Idumée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 7, 'Et avec elle les forts tomberont, et les béliers et les taureaux; la terre s’enivrera de leur sang et se rassasiera de leur graisse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 8, 'Car c’est le jour du jugement du Seigneur; c’est l’année de la juste vengeance de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 9, 'Et leurs torrents seront changés en poix, et leur terre en soufre; et leurs champs seront comme de la poix qui brûle');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 10, 'Nuit et jour, et ne s’éteindra jamais dans la suite des siècles; et la fumée s’en élèvera en l’air; et le pays sera pour longtemps désolé dans ses générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 11, 'Les oiseaux, les hérissons, les ibis, les corbeaux en feront leur séjour; le cordeau de la destruction les nivellera, et les onocentaures y résideront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 12, 'Il n’y aura plus de princes; car ses rois et ses grands ont péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 13, 'Et des arbres épineux croîtront dans ses villes et dans ses forteresses; elles seront l’asile des sirènes et l’abri des passereaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 14, 'Et les démons s’y rencontreront avec les onocentaures, et ils se crieront l’un à l’autre. C’est là que demeureront les onocentaures; car ils y trouveront un lieu de repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 15, 'C’est là que le hérisson a fait son nid, et que la terre y à caché en sûreté ses petits. C’est là que les cerfs se sont rencontrés, et qu’ils se sont vus face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 16, 'Ils y sont venus très-nombreux, et pas un n’a péri; ils ne se cherchaient pas l’un l’autre; mais le Seigneur les à conduits, et son souffle les à rassemblés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 34, 17, 'Et il les à tirés au sort, et sa main leur à distribué des pâturages, disant: Que ce soit à jamais votre héritage; et de génération en génération ils demeureront en cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 1, 'Réjouis-toi, désert altéré; que le désert tressaille d’allégresse, qu’il se couvre de fleurs comme le lis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 2, 'Et les déserts du Jourdain fleuriront, et ils seront dans la joie la gloire du Liban leur à été donnée, et les honneurs du Carmel; et mon peuple verra la gloire du Seigneur et la grandeur de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 3, 'Fortifiez-vous, mains affaiblies, genoux tremblants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 4, 'Consolez-vous l’un l’autre, cœurs défaillants; prenez courage, n’ayez pas peur; voici notre Dieu, il Vous rend et il vous rendra justice; il viendra lui-même, et il nous sauvera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 5, 'Alors s’ouvriront les yeux des aveugles, et les oreilles des sourds ouïront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 6, 'Alors le boiteux sautera comme un cerf; la langue nouée parlera facilement, parce que l’onde aura jailli dans le désert, et un torrent sur une terre altérée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 7, 'Et les champs arides seront changés en nappes d’eau, et il y aura des fontaines sur une terre altérée; là seront la joie des oiseaux, le séjour du roseau et des étangs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 8, 'Là il y aura une voie pure, qu’on nommera la voie sainte, et jamais être impur n’y passera; et il n’y aura point de voie impure, mais les dispersés y marcheront et ne s’égareront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 9, 'Il n’y aura pas de lion; nulle bête farouche n’y viendra ou n’y sera trouvée; mais là marcheront les hommes rachetés');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 35, 10, 'Et rassemblés par le Seigneur; là sera leur refuge, et ils rentreront à Sion, transportés d’allégresse; et une joie perpétuelle couronnera leurs têtes; on verra sur leur front la louange et le ravissement; la joie aura pris possession d’eux; la douleur, la tristesse, les gémissements se seront enfuis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 1, 'Et la quatorzième année du règne d’Ézéchias, Sennacherib, roi des Assyriens, vint assièger les villes de la Judée; et il s’en rendit maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 2, 'Et le roi des Assyriens envoya de Lachis, au roi Ézéchias, Rabsacès avec une armée nombreuse; celui-ci s’arrêta vers l’aqueduc de la piscine d’en haut, sur le chemin du champ du Foulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 3, 'Et Éliacim, fils d’Helcias l’économe, et Somna le scribe, et Joach fils d’Asaph l’archiviste, sortirent, et vinrent le trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 4, 'Et Rabsacès leur dit: Dites à Ézéchias: Voici ce que dit le grand roi des Assyriens: D’où te vient ta confiance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 5, 'Livre-t-on bataille avec le conseil ou les paroles des lèvres? Maintenant donc, en qui t’es-tu confié, pour te révolter contre moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 6, 'Voilà que tu te fies à ce roseau brisé qu’on appelle l’Égypte; il entrera dans la main de quiconque s’appuiera sur lui, et il la percera; ainsi en est-il du Pharaon d’Égypte et de tous ceux qui ont confiance en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 7, 'Et si vous dites: Nous nous confions dans le Seigneur notre Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 8, 'Eh bien, combattez aujourd’hui mon maître, le roi des Assyriens, et je vous donnerai deux mille chevaux, si vous pouvez leur donner deux mille hommes pour les monter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 9, 'Et comment pourrez-vous seulement résister en face à l’un de nos chefs? Il n’y à que des esclaves qui ont mis leur confiance dans les Égyptiens, dans leurs chevaux et leurs cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 10, 'Mais est-ce que nous sommes venus combattre cette terre sans le Seigneur? Le Seigneur m’a dit: Marche sur cette terre, et détruis-la.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 11, 'Et Éliacim et Somna, et Joach lui dirent: Parle syrien à tes serviteurs, car nous le comprenons; mais ne nous parle pas en langue judaïque. Pourquoi parlestu? pour être ouï du peuple qui se tient sur les remparts?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 12, 'Mais Rabsacès leur répondit: Est-ce que mon maître ne m’a envoyé dire ces paroles qu’à votre maître et à vous? Ne sont-elles pas pour les hommes qui se tiennent sur le rempart, et qui seront réduits, comme à manger leurs excréments et à boire leur urine?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 13, 'Et Rabsacès se redressa, il éleva la voix et dit en langue judaïque: Écoutez les paroles du grand roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 14, 'Voici ce que dit le roi: Qu’Ézéchias ne vous trompe point par des discours, car il ne pourra vous sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 15, 'Qu’Ézéchias ne vous dise pas que Dieu vous protégera et qu’il ne livrera point cette ville aux mains du roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 16, 'N’écoutez pas Ézéchias, car voici ce que dit le roi des Assyriens: Si vous voulez être bénis, venez à moi, chacun mangera le fruit de sa vigne et ses figues, et vous boirez l’eau de vos citernes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 17, 'Jusqu’à ce que je revienne pour vous transporter en une terre comme votre terre, pleine de pain et de vin, de vignes et de froment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 18, 'Qu’Ézéchias ne vous trompe pas, disant: Dieu vous délivrera; les dieux des nations qui tour à tour sont tombées dans la main du roi les ont-ils délivrées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 19, 'Où est le dieu d’Émath et d’Arphath? Où est le dieu de la ville d’Éppharvaïm? Est-ce qu’ils ont eu le pouvoir de délivrer Samarie de mes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 20, 'Quel est celui des dieux de toutes ces nations qui ait délivré sa terre de mes mains? Dieu délivrera-t-il Jérusalem de mes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 21, 'Et le peuple resta muet, et personne ne répondit à ce discours; car le roi avait ordonné de ne rien répondre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 36, 22, 'Et l’économe Éliacim, fils d’Helcias, et le scribe de l’armée Somna, et l’archiviste Joach, fils d’Asaph, rentrèrent auprès d’Ézéchias, et, ayant déchiré leurs tuniques, ils lui rapportèrent les paroles de Rabsacès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 1, 'Lorsque le roi Ézéchias les eut ouïs, il déchira ses vêtements, se couvrit d’un cilice, et alla au temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 2, 'Et il envoya, couverts de cilices, l’économe Éliacim, et le scribe Somna, et les anciens des prêtres, auprès du prophète Isaïe, fils d’Amos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 3, 'Et ils lui dirent Voici ce que dit Ézéchias: Ce jour est un jour d’affliction et d’opprobre, de reproches et de colère; car les douleurs de l’enfantement sont venues à la femme, mais elle n’a pas la force d’enfanter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 4, 'Puisse le Seigneur ton Dieu entendre les paroles de Rabsacès, que le roi des Assyriens à envoyé pour outrager le Dieu vivant et le blasphémer par les paroles que le Seigneur ton Dieu à entendues; et prie le Seigneur ton Dieu pour ce qui reste encore des siens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 5, 'Et les serviteurs du roi Ézéchias vinrent auprès d’Isaïe;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 6, 'Et le prophète leur dit: Dites à votre maître: Voici ce que dit le Seigneur: Ne crains pas les paroles de blasphème que tu as entendues des envoyés du roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 7, 'Voilà que je mets en lui un esprit; il va apprendre une nouvelle, et il retournera en son royaume, et il périra par le glaive en son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 8, 'Et Rabsacès s’en retourna, et il rejoignit le roi des Assyriens qui assiègeait Lobna, et il avait ouï dire qu’il était parti de Lachis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 9, 'Et Tharaca, roi d’Éthiopie, se mit en campagne');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 10, 'Voici ce que vous direz à Ézéchias, roi de la Judée Que ton Dieu, en qui tu as mis ta confiance, ne te trompe pas, en te disant: Jérusalem ne sera pas livrée au roi des Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 11, 'Ne sais-tu pas de quelle manière les rois des Assyriens ont traité toutes les contrées qu’ils ont détruites? Et toi, tu leur échapperais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 12, 'Est-ce que les dieux des nations, que nos pères ont anéanties, les ont sauvés? ont-ils sauvé Gozan, Harran et Rapheth, qui sont dans la terre de Théémath?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 13, 'Où sont les rois d’Émath? Où sont ceux d’Arphath et de la ville d’Eppharvaïm, et d’Anagougana?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 14, 'Et Ézéchias prit la lettre de Sennacherib des mains des messagers, et il la lut; puis il monta au temple du Seigneur, et il la déploya devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 15, 'Et Ézéchias pria le Seigneur, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 16, 'Seigneur des armées, Dieu d’Israël, qui êtes assis sur les chérubins, vous êtes le seul Dieu de tous les royaumes de la terre; vous avez créé le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 17, 'Seigneur, inclinez votre oreille; Seigneur, écoutez; Seigneur, ouvrez les yeux, regardez et voyez les paroles que Sennacherib envoie pour outrager le Dieu vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 18, 'Il est vrai, Seigneur, que les Assyriens ont dépeuplé toute la terre et les contrées des nations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 19, 'Et qu’ils ont jeté au feu leurs idoles; car ce n’étaient pas des dieux, mais des œuvres de la main des hommes, du bois, de la pierre, et ils les ont répudiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 20, 'Maintenant, Seigneur notre Dieu, délivrez-nous des mains de Sennacherib, afin que tout royaume de la terre sache que vous êtes le seul Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 21, 'Et Isaïe, fils d’Amos, envoya un messager chez');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 22, 'Or voici les paroles que Dieu à dites sur lui: Il ta méprisée, ô vierge, fille de Sion, il t’a raillée; il a secoué la tête sur toi, fille de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 23, 'Qui as-tu outragé et irrité? Contre qui as-tu élevé la voix? N’as-tu pas levé tes regards hautains contre le Saint d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 24, 'Tu as outragé le Seigneur par tes messagers, et tu as dit: Avec la multitude de mes chars je suis monté sur la cime des montagnes et sur les pics du Liban; j’ai abattu ses grands cèdres et ses plus beaux cyprès, et je suis venu au plus haut de la forêt de chênes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 25, 'Et j’ai fait une digue, et j’ai desséché les eaux et tous les rassemblements d’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 26, 'N’as-tu pas ouï parler des choses que j’ai faites jadis? Dès les anciens jours je les ai ordonnées; et aujourd’hui j’ai montré mon dessein de désoler des nations dans leurs forteresses et les habitants des villes fortes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 27, 'J’ai énervé leurs mains, et ils se sont flétris, ils sont devenus comme le gazon des terrasses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 28, 'Et maintenant je connais ta demeure, ton départ et ton arrivée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 29, 'Ta fureur, tes paroles superbes sont parvenues jusqu’à moi; mais je mettrai un harpon dans tes narines et un mors à tes lèvres, et je te renverrai par le chemin que tu as pris en venant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 30, 'Pour toi, Ézéchias, voici mon signe: Mange cette année ce que tu auras semé, et la seconde année,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 31, 'Et ceux qui seront restés en Judée enfonceront leurs racines dans le sol, et produiront des fruits jusqu’au haut des branches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 32, 'Car il sortira de Jérusalem des restes, et de la montagne de Sion des hommes sauvés. Et c’est l’amour du Seigneur des armées qui fera ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 33, 'À cause de cela, voici ce que dit le Seigneur sur le roi des Assyriens: Il n’entrera point en cette ville; il ne lancera pas contre elle une flèche; il ne poussera pas contre elle un bouclier; il ne l’entourera point de palissades.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 34, 'Il s’en retournera par le chemin qu’il a pris, et il n’entrera point en cette ville voilà ce que dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 35, 'J’étendrai mon bouclier sur cette ville pour la sauver à cause de moi, et à cause de David, mon serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 36, 'Et l’ange du Seigneur s’avança, et il extermina dans le camp des Assyriens cent quatre-vingt-cinq mille hommes; et les survivants se levèrent dès l’aurore, et ils ne trouvèrent que des cadavres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 37, 'Et Sennachérib, roi des Assyriens, partit et il s’en retourna, et il ne sortit plus de Ninive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 37, 38, 'Et comme il adorait, dans le temple de Nasarach, le premier de ses dieux, ses fils Adramelech et Sarasar le tuèrent de leurs épées; puis ils se sauvèrent en Arménie, et Asordan, son fils, régna à sa place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 1, 'En ces jours-là, Ézéchias tomba malade d’une maladie mortelle, et le prophète Isaïe, fils d’Amos, l’alla');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 2, 'Et Ézéchias se retourna la face contre le mur, et il pria le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 3, 'Disant: Seigneur, souvenez-vous que j’ai marché devant vous dans la vérité, avec un cœur sincère, et que j’ai fait ce qui était agréable à vos yeux. Et Ézéchias pleura des larmes abondantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 4, 'Et la parole du Seigneur vint à Isaïe, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 5, 'Va et dis à Ézéchias: Ainsi parle le Seigneur, Dieu de David, ton aïeul: J’ai entendu ta prière, et j’ai vu tes larmes, et voilà que j’ajoute quinze années à ta vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 6, 'Et je te sauverai, toi et cette ville, du roi des Assyriens, et j’étendrai mon bouclier sur cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 7, 'Tel est le signe du Seigneur qui te montrera que sa parole s’accomplira:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 8, 'Voilà que je vais faire reculer l’ombre des marches où le soleil est descendu, de dix degrés sur la maison de ton père; je ferai reculer le soleil de ces dix degrés. Et le soleil remonta les dix marches que l’ombre avait descendues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 10, 'J’ai dit: Dans la plénitude de mes jours, je descendrai aux portes de l’enfer, j’abandonnerai le reste de mes années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 11, 'J’ai dit: Je ne verrai plus le salut de Dieu sur la terre des vivants; je ne verrai plus le salut d’Israël sur la terre; je ne verrai plus aucun homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 12, 'Le reste de ma vie a disparu, il a été retranché de ma race; il s’en est allé et il m’a quitté, comme le voyageur qui replie sa tente après l’avoir dressée; mon souffle est comme un fil de laine dont l’ouvrière s’approche pour le couper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 13, 'En ce jour, avant l’aurore, j’ai été livré comme à un lion; c’est ainsi qu’il a broyé tous mes os; car je lui ai été livré depuis le point du jour jusqu’à la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 14, 'Je crierai comme l’hirondelle, je gémirai comme la colombe; car mes yeux se sont obscurcis à force de regarder au plus haut des cieux vers le Seigneur, qui enfin m’a relevé, qui m’a ôté les douleurs de mon âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 15, 'Seigneur, vous m’avez fait connaître votre volonté sur ma vie, et vous avez ranimé mon souffle; et consolé j’ai vécu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 16, 'Vous avez délivré mon âme pour m’empêcher de mourir; et vous avez rejeté derrière moi tous mes péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 17, 'Car ceux qui sont en enfer ne vous loueront point, les morts ne vous béniront pas; en enfer on n’espère plus en votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 18, 'Les vivants vous béniront, comme je le fais moimême; à partir de ce jour, j’enseignerai des enfants à publier votre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 19, 'Dieu de mon salut, je ne cesserai de vous bénir au son de la harpe, tous les jours de ma vie, devant le temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 20, 'Et Isaïe dit à Ézéchias: Prends un panier de figues, écrase-les, et te les applique, et tu seras guéri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 21, 'Et Ézéchias dit: Quel miracle qu’Ézéchias puisse monter encore au temple de Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 38, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 1, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 2, 'Et à cause d’eux Ézéchias fut réjoui, et il leur montra la maison de Nechotha, et l’or, et l’argent, les parfums, les aromates et la myrrhe, puis l’arsenal et ses magasins, enfin tout ce qui se trouvait dans ses trésors. Et il n’y eut rien qu’Ézéchias ne fit voir dans son palais et dans ses domaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 3, 'Mais le prophète Isaïe alla trouver le roi Ézéchias, et il lui dit: Que vous ont dit ces hommes, et d’où sont-ils venus? Ézéchias répondit: Ils sont venus vers moi d’une contrée lointaine, de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 4, 'Et le prophète reprit: Qu’ont-ils vu dans ton palais? Et le roi répondit: Ils ont vu tout ce que mon palais renferme; il n’y à rien que je ne leur aie montré, soit dans mon palais, soit dans mes trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 5, 'Et le prophète Isaïe dit à Ézéchias: Écoute la parole du Seigneur des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 6, 'Voilà que les jours approchent où tout ce que renferme ton palais, tous les trésors que tes pères ont amassés jusqu’à ce moment, seront pris et iront à Babylone, et ils n’en laisseront rien; ainsi l’a dit Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 7, 'Quant à tes fils que tu as engendrés, ils les prendront, ils les feront eunuques dans le palais du roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 39, 8, 'Et Ézéchias dit à Isaïe: Juste est la parole que le Seigneur à prononcée; mais que la paix et la justice se maintiennent tous les jours de ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 1, 'Consolez, consolez mon peuple, dit le Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 2, 'Prêtres, parlez au cœur de Jérusalem; consolez-la, car son humiliation est accomplie; son péché lui est remis, parce qu’elle à reçu de la main du Seigneur un châtiment double de ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 3, 'On entend la voix de celui qui crie dans le désert: Préparez la voie du Seigneur, redressez les sentiers de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 4, 'Toute vallée sera remplie, toute montagne sera abaissée; les chemins tortueux seront redressés, ceux qui étaient raboteux seront aplanis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 5, 'Et la gloire du Seigneur se manifestera, et toute chair verra le salut de Dieu; car le Seigneur à parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 6, 'Une voix m’a dit: Crie; et j’ai répondu: Que crierai-je? Toute chair est de l’herbe; toute gloire humaine est comme la fleur des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 7, 'L’herbe s’est desséchée, et la fleur est tombée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 8, 'Mais la parole de notre Dieu subsistera dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 9, 'O toi qui annonces à Sion la bonne nouvelle, monte sur le sommet de la montagne; élève la voix de toutes tes forces, toi qui annonces à Jérusalem la bonne nouvelle; dis-leur: Glorifiez-vous, ne craignez point; dis aux villes de Juda: Voilà votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 10, 'Voilà le Seigneur, le Seigneur vient avec la force, son bras à la puissance; voilà dans ses mains le salaire, et l’œuvre est devant ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 11, 'Il fera paître son troupeau comme un pasteur; il rassemblera les agneaux, et il encouragera les brebis pleines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 12, 'Qui à mesuré les eaux à la main, le ciel à la palme, et toute la terre à la poignée? Qui à placé les montagnes dans une balance? Qui à pesé les forêts?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 13, 'Qui sait la pensée du Seigneur? Qui à tenu conseil avec lui pour l’instruire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 14, 'Avec qui a-t-il tenu conseil, et qui l’a instruit? Qui lui à enseigné le jugement? Qui lui à montré la voie de la sagesse?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 15, 'Est-ce que toutes les nations ne sont pas à ses yeux comme la goutte d’eau qui s’échappe du vase? comme l’oscillation d’une balance? Ne seront-elles pas à ses yeux comme un peu de salive?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 16, 'Le Liban ne suffirait pas pour un bûcher; tous les quadrupèdes ne suffiraient pas pour un holocauste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 17, 'Toutes les nations sont comme un néant; elles sont comptées comme un néant à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 18, 'À qui avez-vous comparé le Seigneur? À quel simulacre l’avez-vous assimilé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 19, 'Est-ce qu’un artisan à jamais fait son image? Est-ce qu’un fondeur, en jetant de l’or dans un moule, l’a fait en or et à reproduit sa ressemblance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 20, 'L’ouvrier à choisi un bois incorruptible; puis il cherche avec soin de quelle manière il posera sa statue, pour qu’elle ne soit point ébranlée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 21, 'Ne savez-vous pas cela? Ne l’avez-vous pas ouï dire? Ne vous l’a-t-on pas appris dès le commencement? Ne connaissez-vous pas les fondements de la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 22, 'C’est lui qui tient dans sa main le cercle de la terre, et, comme une nuée de sauterelles, tous ceux qui l’habitent. C’est lui qui à posé les cieux comme une voûte, et qui les à tendus comme la tente où l’on s’abrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 23, 'C’est lui par qui règnent les princes, qui sont comme un néant devant lui. C’est lui qui à créé la terre et la regarde comme un néant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 24, 'Car ces princes ne planteront pas, ils ne sèmeront pas, et leur racine ne prendra pas en terre. Il a soufflé sur eux, et ils se sont desséchés; la tempête les emportera comme des broussailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 25, 'Maintenant donc, à qui m’avez-vous comparé, pour que je m’en glorifie? dit le Saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 26, 'Levez les yeux et voyez; qui vous à montré toutes ces choses? C’est celui qui à produit les innombrables ornements des cieux, qui dans sa gloire les appelle tous par leur nom, et qui, dans la plénitude de sa puissance, ne vous à rien caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 27, 'Et toi, qu’as-tu dit, Jacob? Pourquoi as-tu ainsi parlé, Israël? Ma voix est ignorée de Dieu, et mon Dieu m’a retiré sa justice, et il s’est éloigné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 28, 'Et maintenant n’as-tu pas appris, n’as-tu pas entendu? Dieu, c’est l’Éternel; c’est Dieu qui à assigné des limites à la terre; il ne sentira jamais la faim ni la fatigue; et il n’y à pas à pénétrer sa sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 29, 'C’est lui qui donne la force aux affamés, et non la tristesse à ceux qui sont dans la douleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 30, 'Car les adolescents auront faim, les jeunes gens seront fatigués, les hommes d’élite seront affaiblis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 40, 31, 'Mais ceux qui attendent le Seigneur trouveront des forces nouvelles; il leur poussera des ailes comme aux aiglons; ils courront, et ne seront point fatigués; ils marcheront, et n’auront pas faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 1, 'Faites-moi fête; car les princes ont recouvré leurs forces qu’ils approchent, qu’ils parlent tous à la fois, et qu’alors ils proclament le jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 2, 'Qui donc à suscité de l’Orient la justice? Il lui à dit: Viens à mes pieds; et elle y viendra. Il la fera comparaître devant les nations; il frappera les rois de stupeur. Il fera tomber à terre leurs glaives; il repoussera comme des broussailles leurs arcs et leurs flèches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 3, 'Et il les poursuivra; et il parcourra en paix la voie de ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 4, 'Qui à opéré, qui à fait ces choses? C’est celui qui à appelé la justice, qui l’a appelée dès le commencement des générations. Je suis Dieu, le premier, et pour tous les siècles à venir je suis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 5, 'Les nations ont vu, et elles ont eu crainte, et elles sont accourues des extrémités de la terre; et elles sont venues toutes à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 6, 'Chaque homme, jugeant pour son prochain, et pour secourir son frère, dira:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 7, 'L’artisan à réuni tous ses efforts, ainsi que l’ouvrier qui forge au marteau; et il dira: Voilà une pièce bien jointe; on en à ajusté les parties avec des clous, on va les fixer, et elles ne seront pas ébranlées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 8, 'Et toi, Israël, toi, Jacob, mon serviteur, toi que j’ai choisi, postérité d’Abraham, mon bien-aimé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 9, 'Toi que j’ai fait revenir des extrémités de la terre; je t’ai convoqué du haut de toutes ses collines, et je t’ai dit: Tu es mon serviteur; je t’ai élu, et je ne t’ai pas abandonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 10, 'Ne crains pas, car je suis avec toi; ne t’égare pas, car je suis ton Dieu; c’est moi qui t’ai fortifié, moi qui t’ai secouru, et t’ai affermi par la justice de ma droite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 11, 'Voilà que tous tes adversaires vont être humiliés et confondus; car ils seront comme s’ils n’étaient pas, et tous tes ennemis périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 12, 'Tu les chercheras et tu ne trouveras plus ces hommes qui t’insultaient dans l’ivresse; car ils seront comme s’ils n’étaient pas, et ceux qui te faisaient la guerre n’existeront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 13, 'Je suis ton Dieu qui t’ai pris par la main droite et qui te dis: Ne crains pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 14, 'Jacob, Israël, si amoindri que tu sois, c’est moi qui t’ai secouru, dit ton Dieu; c’est moi, ô Israël, qui');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 15, 'Voilà que je t’ai façonné comme les roues d’un char à moudre, neuves et dentelées; et tu moudras les montagnes, et tu aplaniras les collines, et tu les réduiras en poudre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 16, 'Et tu les vanneras, et le vent les emportera, et un tourbillon les dispersera. Cependant tu te réjouiras dans les saints d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 17, 'Et les pauvres et les indigents tressailliront d’allégresse; car ils auront cherché de l’eau, et il n’y en avait pas; et leur langue était desséchée par la soif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 18, 'Je ferai jaillir des fleuves sur les monts, et des sources dans la plaine; je changerai le désert en étangs, et la terre altérée en eaux courantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 19, 'Dans la terre sans eau je placerai le cèdre, le buis, le myrte, le cyprès et le peuplier:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 20, 'Afin que partout on voie, on sache, on comprenne, on sente à la fois que la main du Seigneur à fait ces choses, et que le Saint d’Israël les à montrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 21, 'Votre jugement est proche, dit le Seigneur Dieu, et proches sont vos conseils, dit le Roi de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 22, 'Qu’ils approchent, qu’ils vous annoncent ce qui doit arriver, ou ce qui d’abord à existé; parlez, et nous appliquerons notre pensée à votre parole, et nous saurons ce que sont les choses de la fin, les choses à venir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 23, 'Dites-nous, annoncez-nous les choses de la fin, et nous reconnaîtrons que vous êtes des dieux. Faites le bien, faites le mal, et nous admirerons, et en même temps nous verrons');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 24, 'D’où vous venez et d’où viennent vos œuvres: on vous à tirés de l’abomination de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 25, 'Mais moi j’ai suscité celui qui vient de l’Aquilon et celui qui vient de l’Orient; ils seront appelés en mon nom. Que viennent les princes, et vous serez foulés aux pieds, comme l’argile du potier; ils vous fouleront comme le potier foule l’argile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 26, 'Qui donc, en effet, publiera les choses du, afin que nous sachions ce qui précédemment à existé? Alors nous dirons: Cela est véritable. Mais il n’est personne qui prédise, ni qui écoute vos discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 27, 'Je donnerai la principauté à Sion, et dans la voie je consolerai Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 28, 'Car nul des gentils, nulle des idoles ne peut rien apprendre; et si je leur demande: D’où venez-vous? nul ne pourra répondre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 41, 29, 'Ce sont ceux qui vous fabriquent qui induisent les hommes en erreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 1, 'Jacob mon serviteur, je te protégerai; Israël est mon élu, mon âme l’a agréé; j’ai répandu sur lui mon esprit, et il révèlera mon jugement aux nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 2, 'Il ne criera pas, il ne faiblira pas; sa voix au dehors ne sera pas entendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 3, 'Il ne broiera pas le roseau déja brisé; il n’éteindra pas la mèche qui fume encore; mais il révèlera le jugement selon la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 4, 'Il brillera et ne sera point détruit jusqu’à ce qu’il ait placé le jugement sur la terre, et les gentils mettront leur espérance en son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 5, 'Ainsi dit le Seigneur Dieu, qui à créé le ciel et l’a tendu, qui à affermi la terre et tout ce qu’elle contient, qui à donné le souffle au peuple qui l’habite, et la vie à ceux qui y marchent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 6, 'Moi, le Seigneur Dieu, je t’ai appelé avec justice, et je te prendrai par la main, et je te fortifierai, et je t’ai donné d’être l’alliance du genre humain et la lumière des nations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 7, 'D’ouvrir les yeux aux aveugles, de tirer de la prison les captifs enchaînés et assis dans les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 8, 'Je suis le Seigneur Dieu, c’est mon nom; je ne donnerai pas ma gloire à un autre, ni mes vertus à des idoles d’argile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 9, 'Voilà que les choses du commencement sont venues, comme viendront les choses nouvelles que je vous annonce, et qui, avant que je les annonce, Vous ont été prédites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 10, 'Chantez au Seigneur un cantique nouveau, Vous qui êtes son royaume; glorifiez son nom des extrémités de la terre, ô vous qui descendez sur la mer pour y naviguer; et vous, îles, et vous qui les habitez!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 11, 'Désert, réjouis-toi; que tes bourgs se réjouissent et tes hameaux, et le peuple de Cédar; et ceux qui habitent parmi les rochers pousseront des cris de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 12, 'Ils rendront gloire à Dieu; ils feront connaître aux îles ses vertus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 13, 'Le Seigneur Dieu des armées s’avancera; il brisera tout à la guerre; il excitera son zèle; il criera avec force contre ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 14, 'J’ai gardé le silence; mais est-ce que je me tairai et me contiendrai toujours? J’ai souffert avec patience comme une femme qui enfante; je vais tout frapper de stupeur; je vais tout flétrir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 15, 'Je rendrai désertes les montagnes et les collines; j’y sécherai l’herbe; je changerai les fleuves en îles; je mettrai à sec les étangs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 16, 'Je conduirai les aveugles par une voie qu’ils ne connaissaient point; je leur ferai fouler des sentiers inconnus; je ferai que devant eux les ténèbres soient lumière et que les voies tortueuses deviennent droites. Voilà ce que j’accomplirai en leur faveur, et je ne les abandonnerai point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 17, 'Mais arrière ceux qui se sont détournés de moi! Soyez confondus, vous qui mettez votre confiance en des idoles d’argile et qui dites à des statues de fonte: Vous êtes nos dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 18, 'Sourds, écoutez; aveugles, levez les yeux pour voir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 19, 'Et qui est aveugle, sinon mes serviteurs? Qui est sourd, sinon ceux qui les gouvernent? Oui, les serviteurs de Dieu sont devenus aveugles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 20, 'Vous avez vu tant de fois, et vous n’y avez pas pris garde; vos oreilles étaient ouvertes, et vous n’avez pas entendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 21, 'Le Seigneur à pris conseil, afin qu’on reconnût sa justice et qu’on publiât sa louange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 22, 'Et j’ai vu, et le peuple était pillé et dispersé. Le filet était tendu dans les retraites, dans les demeures, partout où ils se cachaient; et on les saisissait comme un butin, et nul n’était là pour arracher cette proie, nul n’était là pour dire: Rends-la-moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 23, 'Qui de vous recueillera ces choses en ses oreilles? Écoutez l’avenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 24, 'Qui à livré comme une proie Jacob et Israël à ceux qui l’ont pris? n’est-ce point Dieu, contre qui ils ont péché, refusant de marcher dans sa voie et d’obéir à ses commandements?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 42, 25, 'Et il a fait éclater contre eux les transports de sa fureur; et la guerre à prévalu sur eux; et.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 1, 'Et maintenant voici ce que dit le Seigneur: Qui t’a créé, Jacob? qui t’a formé, Israël? Ne crains pas, car je t’ai racheté; je t’ai donné ton nom, tu es à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 2, 'Si tu traverses les eaux, je suis avec toi; et les fleuves ne pourront te submerger; et si tu passes à travers la flamme, tu ne seras point brûlé, le feu ne te brûlera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 3, 'Car je suis le Seigneur ton Dieu, le Saint d’Israël, ton sauveur. J’ai fait de l’Égypte et de l’Éthiopie ta rançon, et pour toi j’ai livré Soène.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 4, 'Depuis que tu es devenu précieux devant moi, tu as été glorifié, et je t’aime, et je donnerai pour toi les hommes, et pour ta tête les princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 5, 'Ne crains pas, car je suis avec toi. De l’Orient je ramènerai ta race; je te ferai revenir de l’Occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 6, 'Je dirai à l’aquilon: Ramène-les; et au midi: Ne retiens pas, ramène de loin mes fils, ramène mes filles des extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 7, 'Ramène tous ceux qui ont invoqué mon nom; car j’ai préparé ce peuple, je l’ai formé, je l’ai fait pour ma gloire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 8, 'Et j’ai éloigné de moi un peuple aveugle, et ses yeux étaient comme aveuglés, et ses oreilles étaient sourdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 9, 'Voilà tous les gentils rassemblés à la fois, voilà');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 10, 'Soyez pour moi des témoins, et moi-même je porterai témoignage, dit le Seigneur Dieu; et aussi mon serviteur, celui que j’ai élu, afin que vous sachiez, que vous croyiez et compreniez que je suis. Avant moi il n’y à pas eu d’autre Dieu, et il n’en sera point après moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 11, 'Je suis Dieu, et, hormis moi, nul ne sauve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 12, 'J’ai prédit, j’ai sauvé, j’ai fait des reproches, et il n’y avait pas avec vous d’étranger. Vous êtes mes témoins, et moi je suis le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 13, 'Je suis depuis le commencement, et il n’est personne qui puisse rien arracher de mes mains. Je ferai mon œuvre, et qui la détruira?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 14, 'Voici ce que dit le Seigneur Dieu qui vous à racheté, le Saint d’Israël: À cause de vous, j’enverrai un ennemi contre Babylone, et je les ferai tous fuir, et les Chaldéens seront enchaînés dans des vaisseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 15, 'Je suis le Seigneur Dieu, votre Saint, qui ai institué votre roi en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 16, 'Voici ce que dit le Seigneur, qui traça une voie dans la mer, et des sentiers sur les grandes eaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 17, 'Qui y fit entrer des chars, des chevaux et une puissante multitude. Mais ils se sont endormis et ils ne se réveilleront plus; ils se sont éteints comme une mèche qu’on a éteinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 18, 'Mais vous ne vous souvenez pas des choses du commencement; vous ne considérez point ce qui s’est fait autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 19, 'Eh bien, je ferai de nouveaux prodiges, qui vont naître tout à l’heure, et vous les connaîtrez; je tracerai une voie dans le désert, et je ferai jaillir des fleuves sur une terre sans eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 20, 'Les bêtes des champs me béniront avec les petits oiseaux et les jeunes passereaux, parce que j’aurai donné de l’eau à une terre aride, et des fleuves au désert, pour abreuver ma race élue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 21, 'Mon peuple dont j’ai pris soin, pour qu’il raconte mes vertus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 22, 'Et pourtant je ne t’ai pas appelé, Jacob; je ne t’ai point coûté de fatigues, Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 23, 'Tu ne m’as point offert d’holocauste de tes brebis; tu ne m’as point glorifié par tes sacrifices; je ne t’ai point assujetti à m’immoler des victimes; je ne t’ai pas donné la peine de brûler pour moi de l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 24, 'Tu n’as pas acheté pour moi des victimes à prix d’argent; je n’ai point désiré la génisse de tes sacrifices, mais tu t’es présenté devant moi avec tes péchés et ton injustice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 25, 'C’est moi cependant, c’est moi qui efface tes transgressions et tes péchés, à cause de moi-même, et je n’en garderai pas le souvenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 26, 'De ton côté souviens-toi, et plaidons ensemble; confesse d’abord tes iniquités, afin que tu sois justifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 27, 'Vos pères les premiers, et vos princes ont péché contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 43, 28, 'Et vos princes ont profané mes choses saintes, et j’ai livré Jacob et Israël à l’opprobre et à la destruction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 1, 'Maintenant écoute, Jacob mon serviteur, Israël mon élu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 2, 'Voici ce que dit le Seigneur Dieu qui t’a créé, qui t’a formé dès les entrailles de ta mère: Tu seras encore secouru; ne crains pas, mon serviteur Jacob, mon bienaimé, Israël mon élu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 3, 'Je donnerai de l’eau dans leur soif à ceux qui traversent la terre aride; je ferai descendre mon esprit sur ta semence, et mes bénédictions sur tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 4, 'Et ils croîtront comme l’herbe entre les ruisseaux, comme le saule sur le bord d’une eau courante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 5, 'Celui-ci dira: Je suis de Dieu. Celui-là se glorifiera du nom de Jacob; cet autre écrira de sa main: Je suis de Dieu, et se glorifiera du nom d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 6, 'Voici ce que dit le Dieu, roi d’Israël, le Dieu des armées, rédempteur de Jacob: Je suis le premier, et je suis le dernier; hormis moi, il n’est point de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 7, 'Qui est semblable à moi? Que celui-là se présente; qu’il rappelle, proclame et m’explique ce que j’ai fait pour l’homme depuis le commencement des siècles; qu’ils vous fassent connaître d’avance les choses de l’avenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 8, 'Ne dissimulez pas, ne divaguez point, dès le commencement n’avez-vous pas ouï cela de vos oreilles? Ne vous l’ai-je pas déclaré? Vous êtes mes témoins; hormis moi, il n’est point de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 9, 'Mais alors les artisans, les sculpteurs d’idoles ne m’ont point écouté, tous insensés, faisant à leur fantaisie des choses qui ne leur serviront de rien. Mais ils seront confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 10, 'Tous ceux qui façonnent un dieu, et qui sculptent des choses inutiles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 11, 'Tous les auteurs de ces vanités ont tous disparu; rassemblez ces hommes sourds, tenez-les réunis; que tous ensemble ils soient humiliés, qu’ils soient tous confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 12, 'L’artisan a aiguisé le fer; il a pris la hache, il a employé la tarière; il a fait son œuvre par l’effort de ses bras; et il aura faim, et il sera sans force, et il n’aura pas d’eau à boire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 13, 'L’artisan ayant choisi l’arbre, l’a dressé avec la mesure, l’a collé et ajusté; puis il lui à donné la forme d’un mortel et la beauté d’un homme pour le placer dans un temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 14, 'Il a abattu un arbre de la forêt, un arbre qu’avait planté le Seigneur, un pin que la pluie avait fait croître');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 15, 'Pour qu’il fût brûlé par les hommes; il en a pris une part et s’en est chauffé; sur la braise ils ont cuit des pains; et avec le reste ils ont façonné des dieux, et ils les adorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 16, 'Il n’en à pas brûlé la moitié; et sur cette moitié il s’est servi des braises pour faire cuire des pains et rôtir des chairs qu’il a mangées; il s’est rassasié, et après s’être chauffé il a dit: Il m’est doux de me chauffer et de voir la flamme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 17, 'Et avec le reste il a sculpté un dieu; et il l’adorera et le priera, disant: Protège-moi, car tu es mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 18, 'Ils n’ont rien su comprendre; leurs yeux obscurcis ne voient plus; leurs cœurs ne sentent rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 19, 'Et cet homme n’a point raisonné en son âme; il n’a pas su comprendre qu’il a brûlé la moitié de l’arbre, et que sur ses braises il a cuit du pain, il a rôti des chairs dont il s’est nourri, et qu’avec le reste il a fabriqué une abomination qu’on adore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 20, 'Sache que le cœur de ces dieux n’est que cendre; mais ils sont égarés, et nul d’eux ne peut sauver son âme. Voyez, et ne direz-vous pas: Cette œuvre de ma main n’est qu’un mensonge?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 21, 'Souviens-toi de ces choses, ô Jacob, ô Israël, car tu es mon serviteur; je t’ai créé pour me servir; ô Israël, ne m’oublie pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 22, 'Car voilà que j’ai effacé tes péchés comme un nuage; et ton iniquité, comme une vapeur. Reviens à moi, et je te rachèterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 23, 'Cieux, réjouissez-vous. Dieu a eu pitié d’Israël; sonnez de la trompette, fondements de la terre; montagnes, poussez des cris d’allégresse; et vous, collines, et vous, arbres qui les couvrez, le Seigneur à racheté Jacob, et Israël sera glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 24, 'Voici ce que dit le Seigneur, qui t’a racheté et qui t’a formé dès les entrailles de ta mère: Je suis le Seigneur qui accomplit toutes choses; seul j’ai tendu les cieux et j’ai affermi la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 25, 'Quel autre que moi dissipera les signes des magiciens et détournera des cœurs les prédictions des devins? Je suis le Seigneur; c’est moi qui renverse la sagesse des sages, et qui rends vains leurs conseils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 26, 'C’est moi qui affermis la parole de mon serviteur, qui confirme les conseils de mes messagers, et qui dis à Jérusalem: Tu seras repeuplée; et aux villes de l’Idumée Vous serez rebâties, et vos champs dévastés refleuriront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 27, 'C’est moi qui dis à l’abîme: Tu seras épuisé, et je dessècherai tes fleuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 44, 28, 'C’est moi qui dis à Cyrus: Sois prudent, et tu accompliras toutes mes volontés; et qui dis à Jérusalem: Tu seras rebâtie, et je jetterai les fondations de mon saint temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 1, 'Voici ce que dit le Seigneur Dieu: J’ai dit à mon christ Cyrus que j’ai pris par la main, avant que les nations lui obéissent: Je briserai la force des rois; j’ouvrirai devant toi les portes, et les villes ne te seront pas fermées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 2, 'Je marcherai devant toi; j’aplanirai les montagnes; je briserai les portes d’airain; je broierai les verrous de fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 3, 'Je te donnerai des trésors enfouis dans les ténèbres; j’ouvrirai pour toi les retraites cachées, invisibles; afin que tu saches que je suis le Seigneur ton Dieu, qui t’appelle par ton nom, le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 4, 'À cause de mon serviteur Jacob, à cause de mon élu Israël, je t’appellerai par ton nom, et je t’agréerai, toi qui cependant ne m’as pas connu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 5, 'Je suis le Seigneur Dieu; et, hormis moi, il n’y a point de Dieu; je t’ai fortifié, et tu ne me connaissais pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 6, 'Je t’ai fortifié pour que du lever au coucher du soleil on sache qu’il n’y à point de Dieu, hormis moi. Je suis le Seigneur Dieu, et il n’en n’est point d’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 7, 'C’est moi qui ai préparé la lumière, qui ai formé les ténèbres, qui fais la paix, qui crée les maux; je suis le Seigneur Dieu, qui fais toutes ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 8, 'Que du plus haut le ciel se réjouisse; que les nuées répandent la justice comme une rosée. Que la terre produise, qu’elle fasse naître la miséricorde et qu’elle produise en même temps la justice. Moi je suis le Seigneur qui t’ai créé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 9, 'Ai-je fait l’argile supérieure au potier? Le laboureur laboure-t-il tout un jour? L’argile dit-elle au potier: Que fais-tu? tu ne travailles pas; n’as-tu pas des mains? Est-ce que l’œuvre parle à l’ouvrier?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 10, 'C’est comme si on disait à son père: Pourquoi engendrez-vous? et à sa mère: Pourquoi enfantezvous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 11, 'Voici ce que dit le Seigneur, le Saint d’Israël, le créateur des choses futures: Questionnez-moi sur mes fils; demandez-moi compte des œuvres de mes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 12, 'C’est moi qui ai créé la terre, et l’homme sur elle; moi qui de ma main ai affermi le ciel; moi qui ai donné des lois à tous les astres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 13, 'C’est moi qui l’ai suscité; il sera roi selon la justice; toutes ses voies seront droites; il rebâtira ma ville; il fera revenir mon peuple de la captivité, sans rançons, sans présents, dit le Seigneur des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 14, 'Voici ce que dit le Seigneur des armées I\'Égypte à travaillé pour toi; les marchandises des Éthiopiens et des hommes superbes de Saba traverseront la mer pour venir te trouver; ils te seront asservis; ils te suivront les fers aux mains, ils t’aborderont, ils se prosterneront devant toi, et t’adresseront leurs prières, parce que Dieu est avec toi. Et, hormis vous, Seigneur, il n’est point de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 15, 'Car vous êtes Dieu, et nous ne le savions pas, Dieu d’Israël, Dieu Sauveur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 16, 'Que tous tes adversaires soient humiliés, qu’ils rougissent, qu’ils marchent pleins de honte. Et vous, célébrez des solennités en mon honneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 17, 'Israël est sauvé par le Seigneur, sauvé pour tous les siècles; ses enfants ne seront plus humiliés ni confondus à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 18, 'Ainsi dit le Seigneur qui à créé le ciel, le Dieu qui à fait paraître la terre, qui l’a créée, qui lui à donné ses limites; et il ne l’a point formée en vain, mais pour qu’elle fût habitée. Je suis le Seigneur, et il n’en est point d’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 19, 'Je n’ai point parlé en secret, ni dans quelque lieu obscur de la terre; je n’ai point dit à la race de Jacob En vain cherchez-vous; c’est moi, c’est moi le Seigneur qui parle selon la justice, qui annonce la vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 20, 'Rassemblez-vous, venez, prenez conseil ensemble, vous qui avez été sauvés des nations qui élevaient des sculptures et des statues de bois, qui vivaient dans l’ignorance et priaient des dieux incapables de sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 21, 'Si elles ont quelque chose à dire, qu’elles approchent, afin d’apprendre toutes à la fois qui à fait connaître ces choses; vous les avez sues dès lors, vous avez su que je suis Dieu; il n’en est point d’autre que moi; je suis le Dieu juste et sauveur; il n’en est point, hormis moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 22, 'Convertissez-vous à moi, et vous serez sauvés, ô vous qui venez des extrémités de la terre. C’est moi qui suis Dieu, et il n’en est point d’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 23, 'Je le jure par moi-même, la justice seule va sortir de ma bouche, et ma parole ne sera pas vaine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 24, 'Tout genou fléchira devant moi; toute langue confessera Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 25, 'Disant: La justice et la gloire viendront à lui, et tous ceux qui se séparent du Seigneur seront confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 45, 26, 'Et les autres seront justifiés, et toute la postérité des fils d’Israël mettra sa gloire en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 1, 'Bel est tombé, Nabo À été brisé, leurs statues sont comme des bêtes fauves, comme des bêtes de somme; enlevez-les, attachés comme la charge d’un homme de peine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 2, 'Accablés, affamés, sans force, ils n’ont pu se sauver de la guerre; ils ont été emmenés captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 3, 'Écoutez-moi, maison de Jacob, et vous tous, restes d’Israël, vous que je porte depuis que vous êtes sortis des entrailles de votre mère, vous que j’instruis depuis votre enfance');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 4, 'Jusqu’à la vieillesse. Je suis, et jusqu’à ce que vous soyez parvenus à l’extrême vieillesse, je suis; je vous');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 5, 'À qui me comparerez-vous? Voyez, imaginez, vous qui vivez dans l’erreur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 6, 'Vous qui accumulez de l’or dans un sac et de l’argent dans une balance; et ils en ont pesé une part, ils ont payé un fondeur, puis ils feront une idole, et, s’étant prosternés, ils l’adoreront;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 7, 'Ils la porteront sur leurs épaules, et se mettront en marche; et s’ils la placent en son lieu, elle y demeurera et ne pourra en bouger. Et celui qui l’invoquera, elle ne pourra l’entendre ni le préserver du mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 8, 'Rappelez-vous ces choses, et gémissez; repentezvous, ô vous qui êtes égarés; convertissez-vous en vos cœurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 9, 'Et souvenez-vous des premiers âges, des âges d’autrefois; souvenez-vous que je suis Dieu, et qu’il n’en est point, hormis moi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 10, 'Moi qui annonce les choses de la fin avant qu’elles soient, et déjà elles sont accomplies. Et j’ai dit: Tous mes conseils seront stables, et tout ce que j’ai résolu, je le ferai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 11, 'J’ai appelé un prince ailé de l’Orient, et d’une contrée lointaine, pour accomplir les choses que j’ai résolues; je lui ai parlé, je l’ai amené, je l’ai créé et formé, je l’ai conduit, et je l’ai mis dans la bonne voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 12, 'Écoutez-moi, vous dont le cœur est perverti, vous qui vous êtes éloignés de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 46, 13, 'Ma justice est proche, et le salut qui viendra de moi ne sera pas différé. J’ai donné dans Sion le salut à Israël pour ma glorification.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 1, 'Descends et assieds-toi sur la terre, vierge, fille de Babylone; assieds-toi sur la terre, fille des Chaldéens; on ne t’appellera plus la tendre et voluptueuse Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 2, 'Prends une meule, mouds de la farine, lève ton voile, montre tes cheveux blancs, dépouille tes jambes, et traverse les fleuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 3, 'Ta honte sera mise à nu, et ton opprobre apparaîtra; et je tirerai de toi une juste vengeance. Pour toi, mon peuple, je ne te livrerai plus aux hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 4, 'Celui qui t’a délivré, c’est le Seigneur des armées; son nom est le Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 5, 'Assieds-toi le cœur attristé; entre dans les ténèbres, fille des Chaldéens; tu ne seras plus appelée force du royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 6, 'J’ai été courroucé contre mon peuple, et tu as souillé mon héritage. Et moi, je les ai livrés à tes mains, et tu ne leur as pas donné de pitié; tu as rendu bien pesant le joug du vieillard.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 7, 'Et tu as dit: Je serai reine dans tous les siècles! N’as-tu donc pas soupçonné ces choses en ton cœur? N’as-tu point songé à la fin?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 8, 'Or maintenant écoute, fille voluptueuse, qui t’assieds pleine d’assurance, et qui dis en ton cœur: Je suis reine, et il n’en est point d’autre; je ne serai jamais veuve, et je ne connaîtrai point la perte de mes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 9, 'Et maintenant sur toi soudain vont fondre ces deux afflictions en un seul jour; le veuvage et la perte de tes enfants te viendront tout à coup, malgré tes enchantements et la puissance de tes magiciens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 10, 'Au sein des désirs de ta perversité. Car tu as dit: Je suis reine, et il n’en est point d’autre. Sache donc que ta science et ta prostitution tourneront à ta honte. Tu as dit en ton cœur: Je suis reine, et il n’en est point d’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 11, 'Or la perdition viendra sur toi, et tu ne l’auras point su; il y aura un abîme, et tu y tomberas; et sur toi viendra la misère, et tu ne pourras te purifier; et la perdition viendra sur toi tout à coup, et tu n’en auras rien su.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 12, 'Et maintenant repose-toi sur tes nombreux enchantements et sur les charmes magiques que tu as appris dès ta jeunesse; tu verras s’ils te peuvent être utiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 13, 'Tu t’es fatiguée en tes conseils; que tes astrologues soient donc debout, qu’ils te sauvent; que ceux qui observent les étoiles te prédisent ce qui doit t’arriver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 14, 'Mais voilà qu’ils seront tous brûlés par le feu comme des broussailles; ils ne sauveront point leur vie de la flamme; et toi, puisque tu as des charbons embrasés, assieds-toi dessus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 47, 15, 'Tel sera pour toi leur secours; tu t’es fatiguée dès ta jeunesse au trafic; l’homme s’est égaré en luimême; il n’y aura point de salut pour toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 1, 'Écoutez, maison de Jacob, vous qui portez le nom d’Israël, qui sortez de Juda et qui jurez au nom du Seigneur Dieu d’Israël, qui faites mention de tout cela, mais non dans la vérité et la justice;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 2, 'Qui gardez le nom de la ville sainte, et qui vous appuyez sur le Dieu d’Israël; le Seigneur des armées est son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 3, 'Je vous ai déjà fait connaître les choses des premiers temps: elles sont sorties de ma bouche, et tout s’est fait.comme vous l’aviez entendu; j’ai agi soudain, et les faits sont advenus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 4, 'Je sais que tu es dur; ton cou est un nerf de fer, et tu as un front d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 5, 'Aussi t’ai-je prédit les choses longtemps avant qu’elles te fussent arrivées, et je te les ai fait connaître afin que tu ne puisses dire: Ce sont mes idoles qui m’ont fait ceci; et que tu ne puisses dire: Ce sont mes sculptures ou mes statues en fonte qui m’ont ordonné cela.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 6, 'Tout ce que vous avez entendu autrefois, vous ne le connaissiez pas; mais je vais vous faire connaître des choses nouvelles, des choses présentes, et qui sont sur le point d’arriver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 7, 'Et vous n’avez point dit: Maintenant tout s’accomplit; quant à ceci, ce n’est pas une prédiction d’autrefois, et tu n’en as pas entendu parler les jours précédents; ne dis donc pas: Assurément je connais ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 8, 'Tu ne les connais pas, tu n’en as rien su; je ne t’ai point ouvert les oreilles dès le commencement; car je savais que tu serais prévaricateur, et que dès le sein de ta mère, et encore maintenant, tu devais être appelé violateur de ma loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 9, 'Mais à cause de mon nom je te montrerai ma colère; puis j’accomplirai devant toi mes merveilles, afin que je ne t’extermine pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 10, 'Voilà que je t’ai vendu, non a prix d’argent; mais je t’ai retiré d’une fournaise de misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 11, 'À cause de moi, j’agirai ainsi pour toi; car mon nom à été profané, et je ne donnerai pas ma gloire à un autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 12, 'Écoute-moi donc, Jacob; écoute-moi, Israël, que j’appelle à moi: Je suis le premier, et je suis pour l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 13, 'Et ma main à fondé la terre, et ma droite à affermi le ciel. Je les appellerai, et ils se présenteront à la fois;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 14, 'Et ils se rassembleront tous, et ils m’écouteront. Qui à fait connaître ces choses à tes idoles? Par amour pour toi, j’ai fait contre Babylone ce que tu désirais, afin d’exterminer la race des Chaldéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 15, 'J’ai parlé, j’ai appelé, je l’ai conduit et je lui ai préparé la voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 16, 'Approchez-vous de moi, écoutez ce que je vais vous dire Dès le commencement je n’ai point parlé en secret; quand les choses ont été résolues, j’étais là, et maintenant le Seigneur Maître m’a envoyé, et avec lui son Esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 17, 'Voici ce que dit le Seigneur, qui t’a délivré, le Saint d’Israël: Je suis ton Dieu, je t’ai montré comment tu trouverais la voie où tu dois marcher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 18, 'Et si tu avais été docile à mes commandements, ta paix aurait été comme un fleuve, et ta justice comme les vagues de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 19, 'Et ta race aurait été comme le sable, et es fruits de tes entrailles comme la poussière des champs; et maintenant tu ne seras pas entièrement détruit, ton nom ne périra pas devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 20, 'Sortez de Babylone, fuyez loin des Chaldéens; poussez un cri d’allégresse; écoutez ces paroles, publiez-les jusqu’aux extrémités de la terre, et dites: Le Seigneur à délivré son serviteur Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 21, 'Et s’ils ont soif, il les guidera à travers le désert; il fera jaillir pour eux l’eau des rochers; la pierre s’ouvrira, des eaux en couleront, et mon peuple boira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 48, 22, 'Mais pour les impies, il n’y à point de joie, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 1, 'Îles, écoutez-moi; nations, soyez attentives: Après un long temps, ceci arrivera, dit le Seigneur; dès les entrailles de ma mère, le Seigneur m’a donné mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 2, 'Il a rendu ma bouche aiguë comme un glaive; il m’a caché en m’abritant de sa main; il a fait de moi sa flèche d’élite, et il m’a caché dans son carquois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 3, 'Et il m’a dit: Tu es mon serviteur, Israël, et par toi je serai glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 4, 'Et j’ai dit: En vain je me suis fatigué; j’ai vainement et sans fruit déployé ma force; c’est pourquoi j’attends mon jugement du Seigneur, et mon labeur est devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 5, 'Et maintenant voici ce que dit le Seigneur, qui, dès les entrailles de ma mère, m’a formé pour être son serviteur, pour ramener ensemble devant lui Jacob et Israël Je me réunirai au Seigneur, et je serai glorifié devant lui, et mon Dieu sera ma force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 6, 'Et il m’a dit: C’est déjà pour toi une grande chose d’être appelé mon serviteur, d’établir les tribus de Jacob et de ramener Israël dispersé; mais voilà que je t’ai choisi pour être l’alliance des races, la lumière des gentils, le salut de tous, jusqu’aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 7, 'Ainsi dit le Seigneur, qui t’a délivré, le Dieu d’Israël Sanctifiez celui qui n’a pas épargné sa vie, et qui cependant est abominable parmi les nations esclaves des princes. Les rois le verront, les princes se lèveront devant lui, et ils l’adoreront pour l’amour du Seigneur; car le Saint d’Israël est fidèle; et je t’ai choisi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 8, 'Voici ce que dit encore le Seigneur Au temps opportun, je t’ai exaucé; au jour du salut, je t’ai porté secours, je t’ai formé, et je t’ai choisi pour l’alliance des nations, pour l’apaisement de la terre, pour la possession d’héritages dépeuplés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 9, 'Et tu diras à ceux qui sont dans les chaînes: Sortez; et à ceux qui sont dans les ténèbres: Voyez la lumière. Et ils se repaîtront sur toutes les voies, et leur pâturage sera dans tous les sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 10, 'Ils ne sentiront ni la faim ni la soif; la chaleur ni le soleil ne les accableront; mais celui qui leur fait miséricorde les consolera; il les conduira à travers des sources d’eau vive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 11, 'Et je ferai de toute montagne un chemin, et de tout sentier un pâturage pour eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 12, 'Voilà que ceux-ci viendront de loin, ceux-là du Septentrion et de la mer, d’autres de la terre des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 13, 'Cieux, réjouissez-vous; terre, tressaille d’allégresse; que les montagnes éclatent de joie: le Seigneur à eu pitié de son peuple, et les humbles de son peuple, il les à consolés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 14, 'Sion avait dit: Le Seigneur m’a délaissée, le Seigneur m’a oubliée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 15, 'Est-ce qu’une mère oublie son enfant? Est-ce qu’elle n’a point compassion du fruit de ses entrailles? Et lors même que la mère les oublierait, moi je ne t’oublierai jamais, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 16, 'Voilà que j’ai gravé sur mes mains la trace de tes murailles; tu es sans cesse devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 17, 'Et bientôt tu seras rebâtie par ceux qui t’ont détruite; et ceux qui t’ont désolée sortiront de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 18, 'Lève les yeux alentour, et regarde-les tous; ils ont été rassemblés, et ils sont venus à toi. Par ma vie, dit le Seigneur, tu te revêtiras d’eux tous comme d’une parure; tu en seras ornée comme des habits d’une fiancée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 19, 'Tes solitudes, tes places détruites et ruinées seront alors trop étroites pour ceux qui t’habiteront; et les hommes qui te dévoraient s’en iront au loin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 20, 'Et tes fils, ceux que tu avais perdus, viendront dire à tes oreilles: Ce lieu est trop resserré, fais-moi une place où je puisse m’établir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 21, 'Et tu diras en ton cœur: Qui m’a engendré ceuxlà? J’étais veuve, et je n’avais point d’enfant: qui m’a élevé ceux-là? J’étais seule et abandonnée; d’où ceux-là me viennent-ils?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 22, 'Ainsi dit le Seigneur: Voilà que je lève la main sur les gentils; j’élèverai mon signe sur les îles, et ils');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 23, 'Et les rois seront tes pères nourriciers, et les reines tes nourrices; ils t’adoreront la face contre terre; ils lècheront la poussière de tes pieds, et tu connaîtras que je suis le Seigneur; et ceux qui m’attendaient ne seront pas confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 24, 'Est-ce que l’on enlève son butin à un géant? Est-ce que celui qu’on a fait injustement captif sera délivré?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 25, 'Or voici ce que dit le Seigneur: Si l’on fait captif un géant, on lui enlèvera son butin; si l’on reprend des mains du fort son captif, celui-ci sera sauvé. C’est moi qui plaiderai ta cause, moi qui délivrerai tes enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 49, 26, 'Et ceux qui t’auront opprimée mangeront leurs propres chairs, et ils boiront leur propre sang comme du vin nouveau, et ils s’enivreront; et toute chair sentira que je suis le Seigneur, que c’est moi qui t’ai sauvé, et qui ai protégé la force de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 1, 'Ainsi dit le Seigneur: Quel est cet écrit de divorce par lequel j’ai répudié votre mère? Pour quelle dette vous ai-je vendus? Vous avez été vendus pour vos péchés, et j’ai répudié votre mère pour vos dérèglements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 2, 'Pourquoi suis-je venu, sans trouver un homme? pourquoi ai-je appelé, sans que nul m’obéît? Ma main n’est-elle pas assez forte pour racheter? Ne suis-je point');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 3, 'Je revêtirai le ciel de ténèbres, et je lui mettrai une couverture comme un cilice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 4, 'Le Seigneur Maître m’a donné le langage de la doctrine, pour savoir quand il est à propos de parler. Il m’a mis à l’œuvre dès l’aurore; il m’a accordé une oreille pour entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 5, 'Et l’enseignement du Seigneur Maître m’a ouvert les oreilles; et je n’y ai pas été indocile, et je n’y ai point contredit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 6, 'J’ai abandonné mon dos aux flagellations, et mes joues aux soufflets, et je n’ai point détourné mon visage de l’humiliation des crachats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 7, 'Et le Seigneur Maître m’a prêté son secours; aussi n’ai-je point eu de confusion; mais j’ai rendu mon visage aussi ferme qu’un rocher, et j’ai reconnu que je n’aurais point à rougir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 8, 'Car celui qui m’a jugé innocent est proche; quel est mon adversaire? qu’il comparaisse avec moi; quel est mon adversaire? qu’il s’approche de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 9, 'Et si le Seigneur Maître vient à mon secours, qui me maltraitera? Voilà que vous allez tous vieillir comme un manteau, et les vers vous dévoreront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 10, 'Qui de vous craint le Seigneur? Que celui-là écoute la voix du serviteur de Dieu. Vous qui marchez dans les ténèbres, et qui n’avez point de lumière, mettez votre confiance dans le nom du Seigneur, et appuyezvous sur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 50, 11, 'Voilà que vous allumez tous du feu, que vous activez la flamme; vous marcherez à la lumière de votre feu, à la flamme que vous avez allumée; c’est par moi que tout cela vous arrivera, et vous vous endormirez dans votre malheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 1, 'Pour vous, écoutez-moi, vous qui suivez la justice et qui cherchez le Seigneur. Regardez la roche solide que vous avez taillée, et le fond de la source que vous avez creusée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 2, 'Regardez Abraham votre père, et Sara qui vous à enfantés dans la douleur; car il était unique, et je l’ai appelé, je l’ai béni, je l’ai chéri et multiplié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 3, 'De même, je vais maintenant te consoler, ô Sion; j’ai déjà consolé toutes ses solitudes, je changerai ses déserts en jardins, et ceux qui s’étendent au couchant seront comme le paradis du Seigneur; en elle on trouvera joie et allégresse, actions de grâces et paroles de louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 4, 'Écoutez-moi, mon peuple, écoutez-moi, et vous, rois, prêtez-moi une oreille attentive; car la loi sortira de moi, et ma justice sera la lumière des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 5, 'Elle est proche ma justice, et mon salut va se lever comme une lumière; et les gentils espéreront en mon bras; les îles m’attendront et elles espéreront aussi en mon bras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 6, 'Levez les yeux au ciel, et regardez au-dessous la terre; le ciel n’est pas plus solide que la fumée, la terre vieillira comme un manteau, et comme eux mourront ceux qui l’habitent; mais mon salut subsistera durant tous les siècles, et ma justice ne défaillira point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 7, 'Écoutez-moi, vous qui connaissez le jugement, et vous, mon peuple, qui conservez ma loi dans votre cœur. Ne craignez pas les outrages des hommes; ne soyez pas abattus par leur mépris;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 8, 'Car ils seront consumés comme un manteau par l’effet du temps; ils seront rongés des vers comme de la laine; mais ma justice subsistera dans tous les siècles, et mon salut durant les générations des générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 9, 'Réveille-toi, réveille-toi, Jérusalem, arme de force ton bras; réveille-toi comme au commencement des jours, comme les antiques générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 10, 'N’es-tu pas celle qui à desséché la mer et la plénitude des eaux de l’abîme? N’as-tu pas fait du fond de la mer une voie pour le passage de mon peuple délivré');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 11, 'Et racheté? Car tes enfants seront ramenés par le Seigneur, et ils reviendront dans Sion pleins d’une joie et d’une allégresse éternelle; ils seront couronnés de louanges et transportés de joie; les douleurs, la tristesse, les gémissements se sont enfuis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 12, 'C’est moi, c’est moi ton consolateur; sache qui tu es, et si tu devais craindre un homme mortel, un fils de l’homme, qui sèchera comme l’herbe des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 13, 'Et tu avais oublié Dieu ton créateur, le créateur du ciel et de la terre; et tous les jours tu avais peur en voyant en face la furie de ton persécuteur! Il a péri comme il avait résolu de te faire périr; et la furie de ton persécuteur, où est-elle à présent?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 14, 'Le Seigneur ne s’arrêtera point, il ne mettra point de lenteur à te sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 15, 'Car je suis ton Dieu; c’est moi qui trouble la mer, et qui fais retentir ses flots. Mon nom est le Seigneur des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 16, 'Je mettrai mes paroles en ta bouche; je t’abriterai à l’ombre de ma main, qui à fixé le ciel et affermi la terre, et je dirai à Sion: Tu es mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 17, 'Réveille-toi, réveille-toi, lève-toi, Jérusalem, qui as bu de la main du Seigneur le calice de sa colère. Car tu as bu, tu as épuisé le calice de la ruine, la grande coupe de la fureur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 18, 'Et de tous les enfants que tu as mis au jour, nul ne t’a consolée; et de tous les fils que tu as élevés, nul ne t’a prise par la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 19, 'Quand ces choses fondront sur toi, qui partagera ta tristesse? Quand il y aura ruine et désolation, famine et coups de glaive, qui te consolera?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 20, 'Tes fils ont été pressés par la détresse, couchés au bout de chaque rue, comme une bette à demi cuite, pleins de la colère du Seigneur, énervés par le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 21, 'C’est pourquoi, écoute, ô toi qui es humiliée et enivrée, mais non de vin:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 22, 'Ainsi dit le Seigneur Dieu, juge de son peuple: Voilà que j’ai ôté de tes mains le calice de la ruine, la grande coupe de ma fureur; tu ne continueras plus d’y boire à l’avenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 51, 23, 'Je la mettrai dans les mains de ceux qui t’ont nui injustement, de ceux qui t’ont abaissée, de ceux qui disaient à ton âme: Couche-toi, afin que nous passions; et tu faisais de ton corps un chemin pour ceux qui passaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 1, 'Réveille-toi, réveille-toi, Sion; revêts-toi de ta force; Jérusalem, ville sainte, revêts-toi de ta gloire; l’impur, l’incirconcis ne continueront plus à te traverser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 2, 'Secoue ta poussière et lève-toi; assieds-toi, Jérusalem; ôte les chaînes de ton cou, Sion, ma fille captive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 3, 'Car voici ce que dit le Seigneur: Vous avez été vendus pour rien, et vous serez rachetés sans argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 4, 'Ainsi dit le Seigneur: Mon peuple est descendu jadis en Égypte pour y demeurer, et il a été traîné de force chez les Assyriens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 5, 'Et maintenant pourquoi y êtes-vous encore? Ainsi dit le Seigneur: Parce que mon peuple à été pris gratuitement, soyez dans la stupeur, et poussez des hurlements; car voici ce que dit le Seigneur: À cause de vous, mon nom est sans cesse blasphémé chez les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 6, 'Aussi mon peuple en ce jour-là connaîtra-t-il mon nom; car c’est moi qui parle, et me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 7, 'Me voici, comme le printemps sur les montagnes, comme les pieds de celui qui annonce la bonne nouvelle de la paix, comme celui qui annonce les biens; car je publierai ton salut, disant: Sion, ton Dieu va régner!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 8, 'Tes gardiens ont élevé la voix, et ils se réjouiront tous à grands cris; car ils verront de leurs yeux, quand le Seigneur aura fait miséricorde à Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 9, 'Que la joie éclate dans les solitudes de Jérusalem; car le Seigneur lui à fait miséricorde, et il a sauvé Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 10, 'Et le Seigneur montrera son bras saint à tous les gentils; et de toutes les extrémités de la terre on verra le salut qui vient de notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 11, 'Éloignez-vous, éloignez-vous, sortez de là; ne touchez à rien d’impur. Sortez du milieu de cette ville, tenez-vous à part, vous qui portez les vases du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 12, 'Car vous ne sortirez pas en tumulte; vous ne marcherez pas comme des fuyards. Le Seigneur marchera le premier devant vous; car c’est lui qui vous aura réunis; c’est le Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 13, 'Voilà que mon serviteur comprendra; et il sera élevé, et il montera au comble de la gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 14, 'Mais de même qu’à cause de toi beaucoup auront été dans la stupeur, de même ta forme sera sans honneur aux yeux des hommes, et ta gloire méprisée des fils des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 52, 15, 'Et comme maintes nations s’étonneront de ses œuvres, les rois aussi se tiendront en silence; parce que ceux à qui rien de lui n’aura été annoncé verront, et ceux qui n’auront rien appris comprendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 1, 'Mais, Seigneur, qui à cru à notre parole? À qui le bras du Seigneur a-t-il été révélé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 2, 'Nous l’avons annoncé, comme un petit enfant devant le Seigneur, comme une racine dans une terre altérée; il n’est point en lui de beauté ni de gloire; nous l’avons vu, et il n’avait ni éclat ni beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 3, 'Mais son aspect était méprisable, au-dessous de celui des fils des hommes. C’était un homme couvert de plaies, et sachant ce que c’est que la souffrance; car son visage était repoussant, sans honneur, et compté pour rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 4, 'Il porte nos péchés, il souffre pour nous; et nous avons remarqué qu’il était dans la peine, dans la douleur, dans la torture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 5, 'Mais il avait été blessé pour nos péchés, il était brisé pour nos crimes; le châtiment qui devait nous rendre la paix est tombé sur lui; nous avons été guéris par ses meurtrissures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 6, 'Nous étions égarés comme des brebis, tout homme errait dans sa voie. Et le Seigneur l’a livré pour nos péchés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 7, 'Et lui, si fort qu’on l’ait maltraité, il n’ouvre pas la bouche. Il a été conduit sous le couteau comme une brebis; et comme l’agneau muet devant le tondeur, ainsi il n’ouvre pas la bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 8, 'Tout jugement lui à été enlevé en son humiliation. Qui racontera sa génération? car sa vie est effacée de la terre; il a été conduit à la mort à cause des péchés de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 9, 'Je donnerai les méchants pour prix de sa sépulture, et les riches pour prix de sa mort; parce qu’il n’a point commis de péchés, et que le mensonge n’a jamais été dans sa bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 10, 'Et il a plu au Seigneur de le purifier par l’effet de sa souffrance. Si vous faites une offrande pour vos péchés, votre vie verra une postérité qui vivra longtemps. Et il a plu au Seigneur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 11, 'D’effacer une part des douleurs de son âme, de lui montrer la lumière, de la former à l’intelligence, de justifier le Juste qui s’est sacrifié pour un grand nombre, et qui à porté leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 53, 12, 'C’est pourquoi il aura pour héritage une grande multitude; il partagera les dépouilles des forts, en récompense de ce que sa vie aura été livrée au supplice, qu’il aura été regardé comme un pécheur, qu’il aura porté sur lui les péchés de beaucoup d’hommes, et que, pour leurs iniquités, il aura été livré à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 1, 'Réjouis-toi, femme stérile qui n’as point enfanté; éclate et crie de joie, toi qui n’as point souffert les douleurs de l’enfantement; parce que la femme délaissée à plus d’enfants que celle qui à un mari; car le Seigneur à dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 2, 'Élargis l’espace de ta tente et de tes couvertures; enfonce les autant que possible; allonge tes cordages, et affermis tes pieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 3, 'Dilate-toi à droite et à gauche, et ta race aura les nations pour héritage, et tu repeupleras des villes désertes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 4, 'Ne crains point parce que tu auras été humiliée; ne rougis point parce que tu auras été outragée; car tu ne te souviendras plus de tes longues humiliations, et tu oublieras l’opprobre de ton veuvage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 5, 'Car c’est le Seigneur qui t’a créée; son nom est le Seigneur des armées; c’est le Dieu d’Israël qui t’a rachetée, et il sera invoqué par toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 6, 'Le Seigneur ne t’a point appelée comme une femme abandonnée et sans courage, ni comme une femme haïe dès sa jeunesse; ton Dieu à dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 7, 'Je t’ai délaissée un peu de temps, mais je vais te traiter avec une grande miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 8, 'J’ai détourné de toi mon visage avec une colère de peu de durée; mais je vais t’accorder ma miséricorde éternelle, À dit le Seigneur qui t’a rachetée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 9, 'Depuis le déluge du temps de Noé, il me souvient, comme je le lui ai juré alors, de dire à la terre: Je ne veux plus être irrité contre toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 10, 'Ni te menacer de transplanter tes montagnes, et d’ébranler tes collines. Ainsi ma miséricorde ne t’abandonnera point, et mon alliance de paix avec toi ne sera point altérée; car le Seigneur Dieu t’a parlé favorablement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 11, 'Humble et désolée, nul ne te consolait. Et voilà que je prépare pour toi des escarboucles au lieu de pierres, et pour tes fondations des saphirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 12, 'Et je te ferai des créneaux de jaspe, des portes de cristal, et une enceinte de pierres précieuses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 13, 'Et tous tes fils seront des disciples de Dieu, et tes enfants jouiront d’une paix abondante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 14, 'Et tu seras rebâtie selon la justice. Abstiens-toi de l’iniquité, et tu n’auras rien à craindre, et la frayeur ne s’approchera point de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 15, 'Voilà que des prosélytes te viendront envoyés par moi; ils habiteront avec toi, et tu seras leur refuge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 16, 'Voilà que je t’ai créée, non comme le forgeron qui souffle sur les charbons et qui porte avec lui les instruments de son art; mais je t’ai créée pour que tu sois impérissable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 54, 17, 'Toute arme préparée contre toi, j’empêcherai qu’elle ne t’atteigne; toute voix qui s’élèvera contre toi en justice, tu en triompheras; et ceux qui t’auront accusée seront déclarés coupables. Tel est l’héritage de ceux qui servent le Seigneur, et vous l’aurez, vous qui êtes mes justes, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 1, 'Vous qui êtes altérés, venez à l’eau; vous qui n’avez point d’argent, allez et achetez; sans argent et sans échange, nourrissez-vous de graisse et de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 2, 'Pourquoi faites-vous cas de l’argent et vous fatiguez-vous pour ce qui ne rassasie pas? Écoutez-moi, et vous mangerez ce qui est vraiment bon; et votre âme se délectera des vrais biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 3, 'Prêtez-moi des oreilles attentives, et suivez mes voies; écoutez-moi, et votre âme vivra des vrais biens, et je ferai avec vous une alliance éternelle, et les promesses faites à David seront vérifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 4, 'Voilà que j’ai donné aux nations un témoignage; c’est LUI, le prince, le maître des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 5, 'Des nations qui ne te connaissaient pas t’invoqueront, et des peuples à qui tu étais inconnu se réfugieront auprès de toi, à cause du Seigneur ton Dieu, le Saint d’Israël, parce qu’il t’aura glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 6, 'Cherchez le Seigneur, et, quand vous l’aurez trouvé, invoquez-le. Et lorsqu’il sera près de vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 7, 'Que l’impie quitte ses voies, et le prévaricateur ses conseils; qu’il se convertisse au Seigneur, et il lui sera fait miséricorde, parce qu’il vous remettra beaucoup de péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 8, 'Car mes conseils ne sont pas comme vos conseils, ni mes voies comme vos voies, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 9, 'Mais autant le ciel est loin de la terre, autant ma voie est loin de vos voies, et vos pensées, loin de ma pensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 10, 'Car telle la pluie ou la neige descend du ciel et n’y retournera point avant d’avoir abreuvé la terre et humecté les champs; avant d’avoir produit des graines pour le semeur, et donné du pain pour sa nourriture;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 11, 'Telle sera ma parole; toute parole qui sortira de ma bouche ne reviendra point à moi que mes volontés ne soient accomplies; et je ferai prospérer tes voies, et mes ordres auront leur effet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 12, 'Car vous sortirez pleins d’allégresse, et vous serez enseignés dans la joie. Les montagnes et les collines bondiront de joie pour votre bienvenue, et les arbres de la plaine vous applaudiront du bruit de leurs ra');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 55, 13, 'Où croissaient la mousse et les épines, s’élèveront le myrte et le cyprès. Et le nom du Seigneur sera proclamé, et ce sera un signe éternel, et il ne disparaîtra jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 1, 'Voici ce que dit le Seigneur: Observez le jugement et agissez selon la justice; car mon salut est près d’arriver, et ma miséricorde va se révéler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 2, 'Heureux l’homme qui fait ces choses! Heureux celui qui s’y attache, qui se garde de profaner les sabbats, et conserve ses mains pures de toute iniquité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 3, 'Que l’étranger qui se donne au Seigneur ne dise pas Le Seigneur me séparera certainement de son peuple! Que l’eunuque ne dise pas: Je suis un bois mort!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 4, 'Voici ce que le Seigneur dit aux eunuques, à tous ceux qui garderont mes sabbats, qui choisiront les choses que j’aime, et s’attacheront à mon alliance:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 5, 'Je leur donnerai dans ma demeure et dans mes murailles une place honorable, meilleure pour eux que des fils et des filles; je leur donnerai un nom éternel, qui ne défaillira jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 6, 'Quant aux étrangers qui se donnent au Seigneur pour le servir, pour aimer le nom du Seigneur, et pour être dévoués à son service; quant à tous ceux qui sont attentifs à ne point profaner mes sabbats, et qui s’attachent à mon alliance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 7, 'Je les conduirai sur ma montagne sainte; je les réjouirai dans la maison de ma prière. Leurs holocaustes et leurs victimes seront agréés sur mon autel. Car ma maison sera appelée une maison de prière pour toutes les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 8, 'Car ainsi dit le Seigneur, qui rassemble les fils dispersés d’Israël: Je rassemblerai près d’Israël une nouvelle synagogue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 9, 'Et vous, bêtes fauves des champs, venez; bêtes fauves de la forêt, dévorez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 10, 'Voyez comme ils sont tous aveuglés; ils ne connaissent rien; ce sont des chiens muets; ils ne peuvent pas aboyer, ils sont endormis sur leurs couches, ils n’aiment qu’à sommeiller.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 11, 'Ce sont des chiens impudents en leur âme, ils ne savent ce que c’est que d’être rassasiés. Ils sont méchants et sans intelligence; ils ont suivi toutes leurs voies, chacun à son gré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 56, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 1, 'Voyez comme le Juste à péri, et nul ne le porte en son cœur; et des hommes justes sont retirés de la terre, et nul n’y fait attention. Car le Juste à été enlevé du milieu de l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 2, 'Son sépulcre sera en paix; il a été enlevé de la voie d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 3, 'Et vous, venez ici, fils pervers, race d’adultères et de prostituées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 4, 'De qui vous êtes-vous joués? contre qui avez-vous ouvert la bouche? contre qui s’est exercée votre langue? N’êtes-vous pas des enfants de perdition, une race sans loi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 5, 'Vous qui invoquez des idoles sous des arbres touffus, vous qui sacrifiez vos enfants dans des vallons au milieu des rochers?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 6, 'C’est là ton partage, c’est là ton lot; tu as répandu des libations pour ces idoles, tu leur as offert des victimes: et je n’en serais pas irrité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 7, 'Là est ton lit, sur une haute montagne, élevée dans les airs; là tu as transporté tes oblations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 8, 'Et derrière les jambages de ta porte tu as placé ton mémorial; pensais-tu qu’à t’éloigner de moi tu aurais quelque profit? Tu as aimé ceux qui partageaient ta couche;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 9, 'Et tu as multiplié tes adultères avec eux, et tu en as gagné beaucoup qui étaient loin de toi, et tu as envoyé des messagers au delà de tes frontières, et tu as été abaissée jusqu’à l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 10, 'Tu t’es fatiguée en maints voyages, et tu n’as pas dit: Je cesserai de me fortifier dans le mal; ainsi astu fait; c’est pourquoi tu ne m’as plus prié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 11, 'Qui as-tu craint, qui t’a retenue, quand tu m’as menti, quand tu m’as oublié, et que tu ne m’as plus donné place dans ta pensée ni dans ton cœur? Et moi, en te voyant, je te dédaigne à mon tour; et tu n’as pas eu peur de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 12, 'Et moi, je publierai ta justice et tes péchés, qui ne te profiteront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 13, 'Et si tu jettes des cris, que tes complices te sauvent dans ton affliction; mais le vent les saisira tous, un tourbillon les emportera. Au contraire, ceux qui s’attachent à moi acquerront la terre, et ils auront ma montagne sainte pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 14, 'Et ils diront: Purifiez devant lui les voies; enlevez les pierres d’achoppement de la voie de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 15, 'Voici ce que dit le Très-Haut, qui réside éternellement au plus haut des cieux, le Saint des saints; son nom est le Très-Haut, reposant parmi les saints; c’est lui qui donne aux faibles la patience, et aux cœurs contrits la vie:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 16, 'Je ne vous punirai pas éternellement; je ne serai pas toujours irrité contre vous; car tout esprit est sorti de moi, et c’est moi qui ai créé toute vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 17, 'À cause de son péché, j’ai affligé quelque temps mon peuple; je l’ai frappé et j’ai détourné de lui mon visage; et il en à éprouvé de la douleur, et triste il a marché dans ses voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 18, 'J’ai vu ces voies, et je l’ai guéri, et je l’ai consolé, et je lui ai donné une consolation véritable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 19, 'La paix, et encore la paix, à ceux qui sont au loin, et à ceux qui sont près. Et le Seigneur à dit: Je les guérirai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 20, 'Quant aux méchants, ils seront agités comme les flots, et ils ne pourront se calmer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 57, 21, 'Il n’y à point de joie pour les impies, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 1, 'Crie de toute ta force, et ne cesse point; élève ta voix comme le son d’une trompette, et fais connaître ses péchés à mon peuple, et à la maison de Jacob ses iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 2, 'Ils me cherchent de jour en jour; ils désirent connaître mes voies comme un peuple qui à pratiqué la justice, et n’a point abandonné le jugement de son Dieu. Ils me demandent maintenant un jugement équitable, et ils désirent s’approcher de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 3, 'Pourquoi, disent-ils, avons-nous jeûné sans que vous l’ayez vu? Pourquoi avons-nous humilié nos âmes sans que vous en ayez rien su? C’est qu’en vos jours de jeûne vous avez trouvé votre plaisir, et vous affligez tous tous ceux qui vous sont soumis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 4, 'Si vous jeûnez pour vous livrer à vos procès et à vos querelles, si vous frappez du poing le pauvre, à quel propos jeûnez-vous pour moi, comme aujourd’hui, criant et élevant la voix afin d’être entendus?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 5, 'Je n’ai point choisi ce jeûne ni ce jour pour qu’un homme humilie son âme; cesse donc de courber ton cou comme un cerceau, de t’étendre sur la cendre et les cilices, et après cela d’appeler ce jeûne agréable à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 6, 'Ce n’est pas un tel jeûne que j’ai choisi, dit le Seigneur; mais romps tous tes liens avec l’iniquité; dénoue les nœuds des contrats violents; renvoie quittes ceux que tu as lésés; déchire toute obligation inique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 7, 'Romps ton pain avec l’affamé; recueille dans ta maison le pauvre sans abri. Si tu vois un homme nu, donne-lui des vêtements, et garde-toi de mépriser ceux de ta propre chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 8, 'Alors ta lumière éclatera comme le matin; ta guérison sera prompte, ta justice te devancera, et la gloire de Dieu t’environnera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 9, 'Tu crieras alors, et Dieu t’exaucera; tu n’auras pas fini de parler qu’il te dira: Me voici. Si tu éloignes de toi les piéges et les votes injustes, et les paroles de murmure;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 10, 'Si tu donnes de bon cœur du pain à l’affamé; si tu rassasies l’âme du pauvre, alors ta lumière brillera dans les ténèbres, et tes ténèbres seront comme le midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 11, 'Et Dieu sera toujours avec toi; et tu seras rassasié selon les désirs de ton âme; et tes os seront pleins de moelle; ils seront comme un verger arrosé, comme une fontaine où l’eau ne tarit jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 12, 'Et tes places, autrefois désertes, seront rebâties; et tes fondations dureront dans tous les siècles pour les générations des générations; et tu seras appelé le réparateur des haies détruites, et tu feras régner la paix en tes sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 13, 'Si tu défends à tes pieds de transgresser les sabbats pour ne point faire à ta volonté en un jour saint; si tu trouves des délices aux sabbats consacrés à Dieu; si tu t’abstiens de tes travaux; si aucun mot de colère ne sort de ta bouche;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 58, 14, 'Si tu mets ta confiance dans le Seigneur, il t’élèvera au-dessus des félicités de la terre; il te donnera pour te nourrir l’héritage de ton père Jacob; car ainsi à parlé la bouche du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 1, 'La main du Seigneur n’a-t-elle pas la force de sauver? A-t-il endurci ses oreilles pour ne pas entendre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 2, 'Non; mais vos péchés mettent une barrière entre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 3, 'Car vos mains sont souillées de sang, et vos doigts de péchés; vos lèvres parlent l’iniquité, et votre langue médite l’injustice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 4, 'Nul ne dit des choses justes; il n’y à point de jugement sincère. Ils ont foi en des idoles; ils parlent vainement; et comme ils conçoivent la douleur, ils enfantent l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 5, 'Ils ont fait éclore des œufs d’aspic; ils filent des toiles d’araignée; et celui qui se dispose à manger de leurs œufs, après avoir cassé un œuf gâté, y trouve un basilic.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 6, 'Leur tissu ne fera jamais un manteau; ils ne se vêtiront jamais de leurs œuvres, car leurs œuvres sont des œuvres d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 7, 'Leurs pieds courent au mal; ils sont prompts à répandre le sang, et leurs pensées sont des pensées de meurtre. L’oppression et la misère sont dans leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 8, 'Ils ne connaissent pas le chemin de la paix, et il n’est point de justice en leurs voies. Les sentiers où ils marchent sont tortueux, et ils ne connaissent point la paix..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 9, 'C’est pourquoi l’équité s’est éloignée d’eux, et jamais la justice ne les à maintenus. Ils attendaient la lumière, et les ténèbres leur sont venues; ils comptaient sur l’éclat du jour, et ils marchent dans la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 10, 'Ils touchent aux murailles comme des aveugles; ils vont à tâtons, comme s’ils n’avaient point d’yeux; ils tombent à midi comme à minuit; et ils gémissent comme des mourants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 11, 'Ils marchent tous ensemble comme l’ours et comme la colombe; ils disent: Nous attendions le jugement, et il n’est point de salut, et il est bien loin de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 12, 'Notre iniquité est grande devant vous, Seigneur, et nos péchés se sont élevés contre nous; car nos iniquités sont en nous, et nous connaissons nos injustices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 13, 'Nous avons vécu dans l’impiété et le mensonge; nous nous sommes éloignés de notre Dieu; nous avons dit des paroles injustes; nous avons désobéi; nous avons conçu et nourri dans nos cœurs des paroles d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 14, 'Nous nous sommes détournés du jugement, et la justice s’est tenue loin de nous; car la vérité est anéantie dans leurs voies, et ils n’y peuvent plus marcher dans le sentier de la droiture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 15, 'Et la vérité leur à été ravie, et ils ont détourné leur esprit des choses de l’intelligence. Et le Seigneur l’a vu, et il s’est offensé de ce qu’ils n’avaient plus de justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 16, 'Il a vu, et il n’y avait pas un homme; il a observé, et nul n’était là pour résister; et il les à secourus de son bras, et il les à raffermis par sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 17, 'Il s’est revêtu de la justice comme d’une cuirasse; et il a posé sur sa tête une couronne de salut; et il s’est enveloppé d’un manteau de vengeance, et il a pris son armure,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 18, 'Comme pour se préparer à répondre par l’outrage à ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 19, 'Et les hommes de l’Occident craindront le nom du Seigneur, et ceux de l’Orient craindront aussi son nom glorieux; car la violence du Seigneur sera comme un fleuve impétueux: elle viendra avec des transports.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 20, 'En faveur de Sion viendra le Rédempteur, et il éloignera les impiétés de Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 59, 21, 'Et voici mon alliance avec eux, dit le Seigneur: Mon Esprit qui est en toi, et les paroles que j’ai mises en ta bouche, ne manqueront pas à ta bouche, ni à celle de ta postérité; car le Seigneur l’a dit, maintenant et pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 1, 'Resplendis, Jérusalem, resplendis de lumière; car ta lumière est venue, et la gloire du Seigneur s’est levée sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 2, 'Voilà que les ténèbres enveloppent la terre, et que les gentils sont dans l’obscurité; mais le Seigneur apparaîtra sur toi, et sa gloire va se montrer en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 3, 'Et les rois viendront à ta lumière, et les nations à ta splendeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 4, 'Lève les yeux autour de toi, et vois tes enfants rassemblés; tous tes fils sont venus de loin, et tes filles seront transportées sur les épaules des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 5, 'Tu verras alors, et tu seras dans l’admiration, et tu seras extasiée en ton cœur; car les richesses de la mer, des nations et des peuples seront transportées chez toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 6, 'Et il te viendra des troupeaux de chamelles, et des chameaux de Madian et de Gépha couvriront tes chemins. Tous les hommes de Saba viendront chargés d’or, et t’offriront de l’encens, et publieront la bonne nouvelle du salut de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 7, 'Et toutes les brebis de Cédar seront rassemblées, et les béliers de Nabajoth viendront à toi; et sur mon autel on fera des offrandes qui me seront agréables, et ma maison de prière sera glorifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 8, 'Qui sont ceux-là qui volent vers moi comme des nuages, ou comme des colombes avec leurs petits?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 9, 'Les îles m’ont attendu, et les navires de Tarsis sont les premiers à ramener de loin tes enfants, et avec eux leur argent et leur or, pour sanctifier le nom du Seigneur saint, et glorifier le Saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 10, 'Et les étrangers réédifieront tes remparts, et leurs rois s’empresseront autour de toi; car je t’ai frappée dans ma colère, et je t’ai aimée dans ma miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 11, 'Et tes portes seront toujours ouvertes; on ne les fermera ni jour ni nuit pour introduire chez toi les richesses des gentils et leurs rois qu’on t’amènera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 12, 'Car les nations et les rois qui ne te seront pas assujettis périront, et ces nations seront complétement dévastées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 13, 'La gloire du Liban viendra à toi, avec le cyprès, le pin et le cèdre, pour glorifier mon lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 14, 'Et les fils de ceux qui t’ont humiliée et irritée viendront à toi, tout tremblants, et tu seras appelée Sion, la ville du Saint d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 15, 'Parce que tu auras été abandonnée et haïe, sans');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 16, 'Et tu seras allaitée du lait des nations, et tu seras nourrie des richesses des rois. Et tu sauras que je suis le Seigneur qui te sauve, le Dieu d’Israël qui te rachète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 17, 'Et au lieu d’airain je t’apporterai de l’or; au lieu de fer, je t’apporterai de l’argent; au lieu de bois, je t’apporterai de l’airain, et au lieu de pierre, je t’apporterai du fer. Et je te donnerai des princes dans la paix, et des surveillants dans la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 18, 'Et l’on n’entendra plus parler d’iniquité sur ta terre, de misère ni d’oppression sur ton territoire; mais tes remparts seront appelés Salut, et tes portes, Louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 19, 'Et ce ne sera plus le soleil qui éclairera tes jours, ni la lune tes nuits; mais le Seigneur sera ta lumière éternelle, et Dieu ta gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 20, 'Et pour toi le soleil ne se couchera point, la lune ne sera point éclipṣée; car le Seigneur sera ta lumière éternelle, et tes jours de deuil seront accomplis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 21, 'Et ton peuple entier sera juste, et il héritera de la terre pour toujours; et il conservera ses rejetuns et les œuvres de ses mains pour ma gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 60, 22, 'Du plus petit il en sortira des milliers, et du plus faible, une grande nation. Et moi le Seigneur, au temps marqué, je les réunirai tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 1, 'L’Esprit du Seigneur est sur moi; c’est pourquoi il m’a consacré de son onction; il m’a envoyé pour évangéliser les pauvres, guérir les cœurs contrits, annoncer aux captifs la délivrance, et aux aveugles la vue;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 2, 'Pour publier l’année agréable au Seigneur, et le jour de la rétribution, et consoler tous les affligés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 3, 'Pour donner aux affligés de Sion, au lieu de cendres la gloire; au lieu des larmes, l’onction de la joie; au lieu d’un cœur affligé, un vêtement de gloire; et ils seront appelés générations de justice, plantes du Seigneur pour sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 4, 'Et ils rebâtiront des places depuis longtemps désertes; ils relèveront celles qui avaient été abandonnées jadis et désolées pendant des générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 5, 'Et les étrangers viendront paître tes brebis, et les fils des Philistins seront tes laboureurs et tes vignerons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 6, 'Et vous, vous serez appelés prêtres du Seigneur, ministres de Dieu; vous vous nourrirez de la force des gentils, et leurs richesses vous feront admirer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 7, 'Ainsi, pour la seconde fois, ils auront la terre pour héritage, et leur tête sera couronnée d’une joie éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 8, 'Car moi je suis le Seigneur, j’aime la justice et je déteste les rapines de l’iniquité. Je donnerai aux justes le fruit de leur labeur, et je ferai avec eux une alliance éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 9, 'Et on reconnaîtra leur race parmi les gentils, et leurs enfants au milieu des peuples. Quiconque les verra les reconnaîtra, parce que c’est une semence bénie de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 10, 'Et ils se réjouiront dans la joie du Seigneur. Que mon âme se réjouisse donc dans le Seigneur; car il m’a revêtu d’un manteau de salut et d’une tunique d’allégresse; il m’a mis la mitre d’un jeune époux; et toute la parure d’une jeune épousée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 61, 11, 'Telle la terre fait croître ses fleurs, et le jardin ses semences; tel le Seigneur Maître fera fleurir la justice et la joie aux yeux de tous les gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 1, 'Je ne me tairai point sur Sion; je ne cesserai de parler de Jérusalem, jusqu’à ce que la lumière de sa justice ait paru, et que mon salut soit allumé comme une');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 2, 'Et les nations verront ta justice, et les rois ta gloire, et on t’appellera d’un nom nouveau, et c’est le Seigneur qui te le donnera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 3, 'Et tu seras une couronne de beauté dans la main du Seigneur, et un diadème royal dans la main de ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 4, 'Et on ne t’appellera plus la Délaissée, et ta terre ne sera plus appelée Déserte. Car tu seras appelée Mon plaisir, et ta terre, la Terre habitée; parce que le Seigneur s’est complu en toi, et que ta terre sera repeuplée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 5, 'Tel le jeune homme demeure avec la vierge qu’il a épousée, tels tes fils résideront en toi; et le Seigneur se réjouira en toi, comme l’époux en son épouse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 6, 'Et sur tes remparts, Jérusalem, j’ai placé tout le jour, et toute la nuit, des sentinelles qui ne cesseront jamais de faire mention du Seigneur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 7, '(Car nul n’est semblable à vous), jusqu’à ce qu’il ait affermi son peuple, et fait de Jérusalem la joie de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 8, 'Ainsi à juré le Seigneur par sa gloire, et par la puissance de son bras: Je ne donnerai plus ton pain et tes vivres à tes ennemis; les fils des étrangers ne boiront plus ton vin, fruit de tes fatigues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 9, 'Mais ceux qui auront récolté le froment s’en nourriront, et ils loueront le Seigneur; et ceux qui auront recueilli le vin le boiront dans mes saints parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 10, 'Franchissez mes portes; préparez la voie à mon peuple; ôtez du chemin les pierres d’achoppement; levez l’étendard pour les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 11, 'Car voilà que le Seigneur à proclamé ces mots jusqu’aux extrémités de la terre: Dites à la fille de Sion: Voilà que le Sauveur est venu à toi ayant ses récompenses et son œuvre devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 62, 12, 'Et il donnera à ton peuple le nom de peuple saint, racheté par le Seigneur; et tu seras appelée la Ville désirée et non la Ville abandonnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 1, 'Quel est Celui qui vient d’Édom, avec un manteau rouge; qui vient de Bosra, si beau dans sa robe,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 2, 'Pourquoi tes vêtements sont-ils rouges, comme s’ils sortaient du pressoir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 3, 'Je suis plein de la grappe foulée, et nul homme des nations n’est venu avec moi; je les ai foulés dans ma colère, je les ai broyés comme de la poudre, et j’ai fait couler leur sang sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 4, 'Car voici le jour de ma vengeance pour eux, et voici l’année de la Rédemption.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 5, 'J’ai promené mes regards, et nul n’est venu me secourir; j’ai cherché, et je n’ai trouvé nul secours. Et mon bras les à délivrés, et ma colère est survenue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 6, 'Je les ai foulés dans ma fureur, et j’ai fait couler leur sang à terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 7, 'Je me suis souvenu de la miséricorde et des vertus du Seigneur, en toutes les grâces qu’il nous à faites. Le Seigneur est un juge bienveillant pour la maison d’Israël; il nous traite selon sa miséricorde et selon la plénitude de sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 8, 'Il a dit: N’est-ce pas mon peuple? Mes enfants ne me répudieront pas! Et il a été leur salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 9, 'En toutes leurs afflictions, ce n’est point un ambassadeur ni un ange, mais lui-même qui les à sauvés, parce qu’il les aime, et qu’il les à épargnés. Il les à luimême rachetés, il les à relevés, il les à glorifiés dans tous les siècles écoulés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 10, 'Mais ils ont désobéi, ils ont irrité son Esprit-Saint. Et il les à pris en haine, et lui-même à combattu contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 11, 'Puis il s’est souvenu des jours antiques, disant: Où est celui qui à fait sortir de la mer le pasteur des brebis? Où est celui qui à placé en eux son Esprit-Saint?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 12, 'Où est celui qui à conduit Moïse de sa main droite et de son bras glorieux? Il a dompté les flots devant lui pour se donner à lui-même un nom éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 13, 'Il les à conduits à travers l’abîme comme un cheval à travers le désert, et ils n’ont point défailli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 14, 'Ils étaient là, comme des troupeaux dans les champs. L’Esprit du Seigneur est descendu et les à guidés. C’est ainsi que vous avez conduit votre peuple, pour vous donner un nom glorieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 15, 'Revenez du ciel, regardez de votre maison sainte et du sein de votre gloire. Où est votre amour et votre force? Où est la plénitude de votre compassion et de vos miséricordes qui nous soutenait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 16, 'Vous êtes notre Père; car ni Abraham ni Jacob ne nous ont connus, mais bien vous, Seigneur; sauvez-nous, vous qui êtes notre Père; depuis le commencement votre nom est avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 17, 'Pourquoi, Seigneur, nous avez-vous égarés loin de votre voie? Pourquoi avez-vous endurci nos cœurs au point que nous n’avons plus eu peur de vous? Revenez pour l’amour de vos serviteurs et des tribus de votre héritage;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 18, 'Afin que nous héritions d’une petite part de votre montagne sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 19, 'Nous sommes redevenus ce que nous étions au commencement, lorsque vous ne régniez pas sur nous, et que votre nom n’était pas encore invoqué pour nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 63, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 1, 'Lorsque vous ouvrirez le ciel, la crainte de vous, Seigneur, saisira les montagnes, et elles s’écrouleront,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 2, 'Comme la cire devant le feu, et la flamme consumera vos ennemis, et votre nom sera signalé parmi eux. À votre aspect les nations seront troublées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 3, 'Lorsque vous ferez des prodiges; et la crainte de vous saisira les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 4, 'Depuis le commencement des siècles nous n’avons point entendu, nos yeux n’ont point vu de Dieu, hormis vous; nous ne connaissons d’œuvres que les vôtres, et vous les accomplirez pour ceux qui attendent votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 5, 'Elle viendra au-devant de ceux qui pratiquent la justice, et ils se souviendront de votre voie. Vous vous êtes irrité, parce que nous avons péché, et que nous nous sommes égarés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 6, 'Et nous sommes tous devenus impurs; et notre justice n’a pas mieux valu qu’un linge souillé de sang. Et à cause de nos péchés nous sommes tombés comme des feuilles, et, comme elles, le vent nous balayera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 7, 'Et il n’est personne qui invoque votre nom et qui se souvienne de recourir à vous. Car vous avez détourné de nous votre visage, et vous nous avez livrés à cause de nos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 8, 'Et maintenant, Seigneur, vous êtes notre Père; pour nous, nous sommes de l’argile, nous sommes tous l’œuvre de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 9, 'Ne vous irritez pas si fort contre nous, et ne gardez pas pour toujours le souvenir de nos péchés. Mais regardez-nous aujourd’hui; car nous sommes tous votre peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 10, 'Notre ville sainte était déserte, Sion comme un désert, Jérusalem maudite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 11, 'Le temple, notre sanctuaire, et la gloire que nos pères avaient édifiés, étaient des racines brûlées par le feu, et tout ce qui faisait notre orgueil était tombé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 64, 12, 'Et pour toutes ces raisons, Seigneur, vous vous êtes contenu; vous avez gardé le silence; vous nous avez humiliés sévèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 1, 'Je me suis manifesté à ceux qui ne me demandaient point; j’ai été trouvé par ceux qui ne me cherchaient pas; j’ai dit à un peuple qui n’avait point invoqué mon nom: Me voici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 2, 'Durant tout le jour j’ai tendu les mains à un peuple désobéissant et contradicteur, à des hommes qui marchaient non dans la bonne voie, mais à la suite de leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 3, 'Ce peuple est celui qui ne cesse pas de m’irriter en face; ils sacrifient dans leurs jardins, et ils brûlent de l’encens sur des briques, pour des divinités qui n’existent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 4, 'Ils se couchent sur des sépulcres ou des cavernes, à propos de leurs songes; et ils mangent de la chair de porc avec le jus de leurs victimes; et tous leurs vases sont souillés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 5, 'Ce sont eux qui disent: Loin de moi, ne m’approche pas; car je suis pur. Mon courroux les réduira en fumée, et en eux brûlera un feu éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 6, 'Voilà qu’il est écrit devant mes yeux: Je ne garderai point le silence jusqu’à ce que j’aie puni dans leur sein');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 7, 'Leurs péchés et ceux de leurs pères, dit le Seigneur. Ceux qui ont sacrifié sur les montagnes, ceux qui m’ont outragé sur les collines, recevront dans leur sein la punition de leurs œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 8, 'Ainsi dit le Seigneur: De même que s’il se trouve un grain mûr dans un verjus, on dit: Ne le gâtez point, parce que la bénédiction est en lui; ainsi ferai-je pour l’amour d’un seul qui me sert; pour l’amour de celui-là je ne les détruirai pas tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 9, 'Et je délivrerai la postérité de Jacob et de Juda; elle aura pour héritage ma montagne sainte; mes élus et mes serviteurs l’auront pour héritage, et ils y demeureront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 10, 'Et il y aura dans la forêt des bergeries pour les menus troupeaux; et dans la vallée d’Achor se reposeront les bœufs de mon peuple, de ceux qui m’auront cherché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 11, 'Et vous qui m’abandonnez et qui oubliez ma montagne sainte, qui dressez une table pour le démon et qui mêlez le vin pour faire des libations à la fortune,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 12, 'Je vous livrerai au glaive, vous tomberez sous le couteau; car je vous ai appelés, et vous ne m’avez point obéi; j’ai parlé, et vous n’avez pas entendu, et devant moi vous avez fait le mal, et ce que je rejetais, vous l’avez choisi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 13, 'C’est pourquoi, voici ce que dit le Seigneur: Ceux qui me servent mangeront; et vous, vous aurez faim; ceux qui me servent boiront, et vous, vous aurez soif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 14, 'Ceux qui me servent vivront dans la joie, et vous, vous serez confondus; ceux qui me servent tressailliront d’allégresse, et vous, vous crierez dans la tristesse de votre cœur, et vous hurlerez dans le déchirement de votre esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 15, 'Et vous laisserez votre nom comme un objet de dégoût à mes élus, et le Seigneur vous détruira, et un nom nouveau sera donné à ceux qui me servent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 16, 'Et ce nom sera béni sur la terre; car ils béniront le Dieu véritable; et ceux qui jureront sur la terre jureront par le Dieu véritable; ils oublieront leur ancienne affliction, qui ne reviendra plus en leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 17, 'Car il y aura un ciel nouveau et une terre nouvelle; on ne se souviendra plus des choses d’autrefois, et le souvenir n’en reviendra plus en leur cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 18, 'Mais ils y trouveront la joie et l’allégresse; car moi-même je ferai de Jérusalem l’allégresse, et de mon peuple la joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 19, 'Et à mon tour je ferai de Jérusalem mes délices, et de mon peuple ma joie; et l’on n’y entendra plus la voix des pleurs, ni celle des gémissements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 20, 'Il n’y aura plus là ni enfant qui meure avant l’âge, ni vieillard qui ne remplisse son temps. Le jeune homme vivra cent ans, et le pécheur à sa mort aura aussi cent ans; mais celui-là sera maudit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 21, 'Et ils bâtiront des maisons, et ils y demeureront, et ils y planteront des vignes, et ils en mangeront les fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 22, 'Et ils ne bâtiront plus pour autrui, et ils ne planteront plus pour que d’autres mangent. Les jours de mon peuple seront comme les jours de l’arbre de vie, et les travaux où ils auront pris de la peine atteindront la vieillesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 23, 'Mes élus ne se fatigueront pas en vain; ils n’auront point d’enfants pour leur malédiction, car c’est une race bénie de Dieu; et leurs petits enfants comme eux seront bénis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 24, 'Et avant qu’ils aient crié je les aurai exaucés; pendant qu’ils parleront encore, je dirai: Qu’y-a-t-il?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 65, 25, 'Alors les loups et les agneaux viendront paître ensemble; le lion mangera de la paille comme le bœuf, et le serpent mangera la terre comme du pain. Ils ne nuiront à personne; ils ne détruiront rien sur ma montagne sainte, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 1, 'Voici ce que dit le Seigneur: Le ciel est mon trône, et la terre l’escabeau de mes pieds. Quelle maison me bâtirez-vous? Et quel sera le lieu où je résiderai?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 2, 'Car ma main à tout fait, et tout est à moi, dit le Seigneur. Et sur qui jetterai-je mes regards, sinon sur l’humble et le doux, sur l’homme qui tremble à ma parole?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 3, 'L’injuste me sacrifie un bœuf, c’est comme s’il tuait un chien; un autre m’offre de la fleur de farine, c’est pour moi comme du sang de pourceau; un autre brûle de l’encens pour mémorial, c’est comme s’il blasphémait; ils ont choisi leurs voies, leur âme s’est complu en leurs abominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 4, 'Et moi, je leur ferai payer leurs moqueries, et je punirai leurs péchés; car je les ai appelés, et ils ne m’ont pas obéi; j’ai parlé, et ils n’ont pas entendu; et devant moi ils ont fait le mal, et ce que je ne voulais pas, ils l’ont voulu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 5, 'Écoutez ce que dit le Seigneur, vous qui tremblez à sa parole; vous avez dit: Nos frères, à ceux que vous avez en haine et en abomination; que le nom du Seigneur soit glorifié en eux, et se manifeste en leur joie; mais ils seront confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 6, 'On entendra la voix de la ville, la voix du temple, la voix du Seigneur qui punira ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 7, 'Avant d’avoir été en mal d’enfant, avant que le moment des douleurs fût arrivé, elle à été délivrée, et elle à donné le jour à un fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 8, 'Qui à jamais ouï pareille chose? qui à vu rien de semblable? La terre n’a-t-elle été en travail d’enfant qu’un seul jour? une nation est-elle née tout d’une fois, pour que Sion ait été en travail et ait mis au jour ses enfants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 9, 'Mais c’est moi qui ai fait naître cette attente, et tu ne t’es point souvenue de moi, dit le Seigneur. N’est-ce point moi qui rends une femme féconde ou stérile? dit ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 10, 'Jérusalem, réjouis-toi; rassemblez-vous dans ses murs, vous tous qui l’aimez; réjouissez-vous de sa joie, vous qui vous êtes affligés sur elle:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 11, 'Afin que vous vous allaitiez et que vous puisiez la plénitude à la mamelle de sa consolation; afin qu’après vous être allaités, vous trouviez des délices dans le retour de sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 12, 'Car ainsi dit le Seigneur: Voilà que je détourne vers eux comme une flamme de paix, comme un torrent qui leur apportera dans ses flots la gloire des gentils. Les enfants de mon peuple seront portés à bras; on les prendra sur les genoux pour les consoler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 13, 'Telle une mère console son enfant, et je vous consolerai, et c’est en Jérusalem que vous serez consolés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 14, 'Et vous le verrez, et votre cœur sera réjoui, et vos os fleuriront comme l’herbe. Et la main du Seigneur sera connue de ceux qui le craignent, et ellè menacera les rebelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 15, 'Car voilà que le Seigneur viendra comme une flamme; les roues de son char seront comme un vent impétueux, apportant sa colère, sa vengeance et sa menace, dans une flamme de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 16, 'Car toute la terre sera jugée par le feu du Seigneur, et toute chair par son glaive; une multitude d’hommes seront blessés par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 17, 'Ceux qui se sanctifient et se purifient dans les jardins, qui mangent sous leurs portiques de la chair de porc, des souris, et d’autres mets abominables, seront tous ensemble consumés par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 18, 'Et moi qui connais leurs œuvres et leurs pensées, je vais réunir tous les peuples et toutes les langues, et ils viendront, et ils verront ma gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 19, 'Et je laisserai sur eux un signe, et j’enverrai ceux d’entre eux qui auront été sauvés chez les gentils à Tharsis, à Phud, à Lud, à Mosoch, à Thobel, en Grèce, et aux îles lointaines, où mon nom n’a jamais été prononcé, où l’on n’a point vu ma gloire; et ils publieront ma gloire parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 20, 'Et ils amèneront vos frères de toutes les nations pour en faire offrande au Seigneur, avec des chevaux et des litières traînées par des mules empanachées, dans la ville sainte, dit le Seigneur; comme lorsque les fils d’Israël offraient leurs sacrifices, en chantant des psaumes, dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 21, 'Et je choisirai parmi eux des prêtres et des lévites, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 22, 'Car de même que le ciel nouveau et la terre nouvelle que je créerai subsisteront devant moi, dit le Seigneur, de même votre race et votre nom seront fermement établis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 23, 'Et ceci sera de lune en lune, de sabbat en sabbat: toute chair viendra en Jérusalem pour adorer devant moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 66, 24, 'Et ils sortiront, et ils verront les membres épars de ceux qui auront péché contre moi; car le ver qui les rongera ne finira point; le feu qui les brûlera ne sera jamais éteint, et ils seront exposés à la vue de toute chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Parole de Dieu à Jérémie, fils d’Helcias, l’un des prêtres qui demeurèrent à Anathoth, en la terre de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'La parole du Seigneur vint à lui dans les jours de Josias, fils d’Amon, roi de Juda, la treizième année de son règne;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Elle lui vint encore dans les jours de Joacim, fils de Josias, roi de Juda, jusqu’à la onzième année de Sédécias, fils de Josias, roi de Juda, jusqu’à la captivité de Jérusalem, le cinquième mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Et la parole du Seigneur vint à lui:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Avant de te former en des entrailles, je te connaissais, et avant que tu sortisses du sein de ta mère, je t’avais sanctifié; et je t’ai fait prophète pour les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Et je répondis: O vous qui êtes, Seigneur Dieu, voilà que je ne sais parler; car je ne suis qu’un enfant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Et le Seigneur me répondit: Ne dis pas, Je suis un enfant; car vers tous ceux à qui je t’enverrai, tu iras; et tout ce que je t’aurai commandé, tu le leur diras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Ne crains pas en leur présence, parce que je suis avec toi pour te sauver, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Et le Seigneur étendit la main et il me toucha la bouche, et le Seigneur me dit: Voilà que j’ai mis mes paroles en ta bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Voilà que je t’ai aujourd’hui institué sur les nations et sur les royaumes, pour déraciner, détruire, perdre, dissiper, réédifier et planter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Et la parole du Seigneur vint à moi, disant: Que vois-tu? Et je répondis: Je vois une verge de coudrier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Et le Seigneur me dit: Tu as bien vu; car je veillerai sur mes paroles pour les accomplir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Et la parole du Seigneur vint à moi de nouveau, disant Que vois-tu? Et je répondis: Je vois une chaudière chauffée en dessous, et sa face est du côté de l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Et le Seigneur reprit: C’est de l’aquilon que s’allumeront les maux sur tous ceux qui habitent la terre de l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Car voilà que je convoquerai tous les royaumes de la terre, dit le Seigneur. Et ils viendront, et chaque roi placera son trône à l’entrée des portes de Jérusalem, et sur ses remparts, et dans son enceinte, et sur toutes les villes de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Et je prononcerai mon jugement sur mon peuple au sujet de toutes les iniquités; car ils m’ont abandonné, ils ont sacrifié à des dieux étrangers, et ils ont adoré les œuvres de leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Et toi, ceins-toi les reins, et lève-toi, et disleur toutes les choses que je te commanderai; n’aie point peur de leur face, ne tremble pas devant eux, car je suis avec toi pour te sauver, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Voilà que je t’ai établi aujourd’hui comme une ville forte, une colonne de fer et un mur d’airain, contre les rois de Juda et ses princes, et le peuple de cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Et ils t’attaqueront, mais ne prévaudront point sur toi; car je suis avec toi pour te sauver, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Et voici ce que dit encore le Seigneur: Je me suis souvenu de ta jeunesse en ma miséricorde, et de mon amour pour ta consécration, quand tu suivais le Saint d’Israël, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Israël est le peuple saint du Seigneur, prémices de ses fruits; tous ceux qui le dévorent sont coupables; les maux viendront sur eux, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Écoutez la parole du Seigneur, maison de Jacob, et vous, famille entière de la maison d’Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Voici ce que dit le Seigneur: Quelle faute vos pères ont-ils trouvée en moi, pour s’éloigner ainsi de moi et marcher après les vanités et devenir vains euxmêmes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Et ils n’ont point dit: Où est le Seigneur qui nous a ramenés de la terre d’Égypte, qui nous a conduits dans le désert, en une terre inhabitée et sans chemin, terre sans eau et sans fruit, que nul n’avait traversée et que nul n’habitait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Et je vous ai menés sur le Carmel, pour vous en faire manger les fruits et les biens; et vous êtes entrés dans ma terre, et vous l’avez souillée, et vous avez fait de mon héritage une abomination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Les prêtres n’ont pas dit: Où est le Seigneur? Et les dépositaires de la loi ne m’ont point connu; et les pasteurs ont péché contre moi, et les prophètes ont prophétisé pour Baal, et ils ont marché après des vanités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'À cause de cela, j’entrerai encore en jugement avec vous, et j’entrerai en jugement avec vos fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Allez aux îles de Céthim et voyez, envoyez à Cédar, informez-vous et voyez si on y fait pareilles choses;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Si les gentils ont changé leurs dieux (et ce ne sont pas des dieux). Cependant mon peuple a échangé sa gloire pour des choses sans utilité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Le ciel en a été stupéfait et il a frémi de choses pires encore, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Car mon peuple a fait deux choses mauvaises: ils m’ont délaissé, moi la fontaine d’eau vive, et ils se sont creusé des citernes crevassées qui ne pourront retenir l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Israël est-il un esclave? est-il né dans la servitude? Pourquoi est-il devenu une proie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Les lions ont rugi contre lui; et ceux qui ont fait de ses champs un désert ont jeté des clameurs; et ses cités ont été détruites, parce qu’elles n’étaient plus habitées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Et les fils de Memphis et de Taphnès t’ont connue, ô Jérusalem, et ils se sont joués de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Et n’as tu pas été traitée de la sorte pour m’avoir abandonné? dit le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Et maintenant qu’as-tu à faire avec la voie de l’Égypte, pour y boire l’eau du Géhon? Qu’as-tu à faire avec la voie des Assyriens, pour y boire l’eau de leurs fleuves?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 18, 'Ta rébellion même te punira, et ta malice t’accusera; sache donc, et vois comme il est amer pour toi de m’avoir abandonné, dit le Seigneur ton Dieu; je ne me suis point complu en toi, dit le Seigneur ton Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 19, 'Dès les premiers temps, tu as rompu ton joug, tu as mis en pièces tes liens, et tu as dit: Je ne vous servirai pas, mais j’irai sur tous les hauts lieux, et à l’ombre de tous les bois touffus je me livrerai à ma prostitution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 20, 'Moi cependant j’ai planté pour toi une vigne féconde en fruits, toute de bon plant; pourquoi as-tu tourné à l’amertume, ô vigne étrangère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 21, 'Quand même on te laverait dans le nitre, quand tu multiplierais pour toi la saponaire, tu serais toujours souillée de tes iniquités devant moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 22, 'Comment peux-tu dire: Je ne me suis point souillée, je n’ai point couru après Baal? Considère tes voies dans le cimetière, et reconnais ce que tu as fait; sa voix a poussé des hurlements jusqu’à l’entrée de la nuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 23, 'Elle a dilaté ses voies vers les eaux du désert; elle a été emportée au gré des désirs de son âme; elle a été asservie; qui la ramènera? Tous ceux qui la cherchent n’auront pas de peine; ils la trouveront dans son abaissement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 24, 'Détourne ton pied de la voie escarpée, et ton gosier de la soif; mais elle a dit: J’aurai du courage, parce que j’aime les étrangers; et elle a cheminé après eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 25, 'Comme un larron est confondu quand il est surpris, ainsi seront confondus les enfants d’Israël, et leurs rois, et leurs princes, et leurs prêtres, et leurs prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 26, 'Ils ont dit au bois: Tu es mon père; et au marbre: Tu m’as engendré; et ils m’ont tourné le dos, et non la face. Et au jour de leurs maux ils diront: Seigneur, levez-vous et sauvez-nous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 27, 'Et où sont tes dieux, que tu t’es fabriqués? Se lèveront-ils? te sauveront-ils au jour de ton malheur? car tu avais autant de dieux que de villes, Juda; et dans toutes les rues de Jérusalem on sacrifiait à Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 28, 'Pourquoi me parlez-vous? Vous avez tous été impies, et tous vous avez péché contre moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 29, 'En vain j’ai frappé vos enfants; vous n’en avez point été corrigés; le glaive a détruit vos prophètes, comme un lion dévorant, et vous n’en avez pas été épouvantés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 30, 'Écoutez la parole du Seigneur: Voici ce que dit le Seigneur Ai-je été un désert, ou une terre aride pour Israël? Pourquoi mon peuple a-t-il dit: Nous ne voulons pas de maître, nous n’irons plus à vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 31, 'Est-ce qu’une jeune épouse oublie sa parure, et une vierge les bandelettes de son sein? Et moi, mon peuple m’a oublié durant des jours sans nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 32, 'Quel bien fais-tu encore dans ta voie, pour rechercher ma tendresse? Tu ne fais rien; au contraire, tu as fait le mal pour souiller tes voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 33, 'Et l’on a trouvé dans tes mains le sang d’âmes innocentes. Je ne les ai point vus dans des tombeaux, mais au pied de chaque chêne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 34, 'Et tu as dit: Je suis innocente, détournez de moi votre colère. Mais voilà que j’entrerai en jugement avec toi, parce que tu as dit: Je n’ai point péché;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 35, 'Parce que, pleine de mépris pour moi, tu es rentrée dans tes anciennes voies. Et tu seras déshonorée par l’Égypte, comme tu l’as été par Assur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 36, 'D’où tu es sortie les mains sur la tête; car le Seigneur a rejeté ton espérance, et en Égypte tu n’auras aucune prospérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Si un homme répudie sa femme, et si elle s’éloigne de lui, et se donne à un autre, est-ce qu’elle reviendra à son premier époux? Cette femme ne sera-t-elle pas souillée? Et toi, tu t’es prostituée à un grand nombre de pâtres, et tu es revenue à moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Lève les yeux droit devant toi, et vois où tu n’es pas souillée. Tu t’es assise dans les rues mêmes, comme une corneille solitaire, et tu as souillé la terre de tes prostitutions et de tes méchancetés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Et tu as eu quantité de pâtres qui ont été pour toi des pierres d’achoppement; tu as eu le regard d’une prostituée; tu as perdu toute pudeur envers tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Ne m’as-tu pas invoqué comme un asile, comme un père, comme le gardien de ta virginité, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Est-ce que votre colère subsistera dans tous les siècles? est-elle réservée à triompher de moi? Voilà comme tu as parlé, après avoir fait ces mauvaises œuvres, et tu l’as osé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Et le Seigneur m’a dit, dans les jours du roi Josias: As-tu vu ce que m’a fait la maison d’Israël? Ils sont allés sur tous les hauts lieux, et sous l’ombrage de tous les arbres, et là ils se sont prostitués.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Et je lui ai dit, après toutes ses prostitutions: Reviens à moi; et elle n’est pas revenue, et l’infidèle Juda a vu l’infidélité d’Israël. Et moi j’ai vu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Après qu’Israël eut été convaincu de tous ses péchés et de ses adultères, après que je l’eus répudié, et remis dans ses mains un acte de répudiation, j’ai vu que l’infidèle maison de Juda n’a pas eu peur de moi, et qu’elle est partie, et qu’elle s’est prostituée elle-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Elle a regardé sa prostitution comme rien; elle a commis ses adultères avec la pierre et le bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Et en toutes ces œuvres, l’infidèle maison de Juda ne s’est jamais non plus convertie à moi de tout son cœur; mais c’était encore un mensonge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Et le Seigneur m’a dit: Israël a justifié son âme plus que l’infidèle maison de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Pars et lis ces paroles, du côté de l’aquilon, et dis: Maison d’Israël, reviens à moi, dit le Seigneur, et je ne tournerai plus contre vous ma face, parce que je suis miséricordieux, dit le Seigneur, et je ne serai pas');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Seulement, reconnais ton iniquité; car tu, as péché contre le Seigneur ton Dieu, et tu as dispersé tes voies chez les étrangers, sous chaque arbre touffu, et tu n’as point obéi à ma parole, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Convertissez-vous, fils rebelles, dit le Seigneur, parce que je serai votre maître, et je vous prendrai même un par ville, deux par tribu, et je vous introduirai dans Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Et je vous donnerai des pasteurs selon mon cœur; et ils vous mèneront paître dans les pâturages de la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Et voici ce qui arrivera: lorsque vous vous serez multipliés, et que vous aurez grandi sur la terre, dit le Seigneur, en ces jours-là, on ne dira plus: Voici l’arche de l’alliance du Saint d’Israël. Elle n’aura plus de place dans les cœurs, elle n’aura plus de nom, on ne la visitera plus, on ne construira plus rien de pareil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'En ces jours et en ce temps-là, on appellera Jérusalem le trône de Dieu, et tous les gentils y seront rassemblés, et ils ne courront plus après les désirs de leurs cœurs pervers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'En ces jours-là, la maison de Juda reviendra avec la maison d’Israël; ensemble elles reviendront de la terre de l’aquilon et de toutes les contrées, en la terre que j’ai donnée à leurs pères pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 19, 'Et moi j’ai dit: Seigneur, qu’il soit fait ainsi; car vous avez dit: Je te mettrai au nombre de mes enfants, je te donnerai une terre choisie, l’héritage du Dieu toutpuissant des nations; et de plus, vous m’appellerez votre père, et vous ne vous détournerez plus de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 20, 'Cependant, comme une femme est infidèle à son époux, de même la maison d’Israël m’a été infidèle, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 21, 'On a entendu sortir de leurs lèvres une voix et des pleurs, et la prière des enfants d’Israël; parce qu’ils avaient failli dans leurs voies, et oublié leur Dieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 22, 'Convertissez-vous, fils rebelles, et je guérirai vos meurtrissures. Dites: Voilà que nous serons vos serviteurs; car vous êtes le Seigneur notre Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 23, 'En vérité les collines et la puissance des montagnes n’étaient que mensonge. Mais c’est du Seigneur notre Dieu que vient le salut d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 24, 'Dès notre jeunesse, l’opprobre de nos pères a consumé leurs travaux, leurs brebis et leurs bœufs, leurs fils et leurs filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 25, 'Nous nous sommes endormis dans notre honte, notre déshonneur nous a enveloppés; car nos pères et nous avons péché devant notre Dieu, depuis notre adolescence jusqu’à ce jour. Et nous n’avons point obéi à la parole du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Si Israël revient à moi, dit le Seigneur, s’il se convertit, s’il retire de sa bouche ses abominations et s’il craint devant ma face,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Et s’il jure, Vive le Seigneur! avec sincérité, équité et justice, les nations seront bénies en lui, et loueront Dieu dans Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Car ainsi dit le Seigneur aux hommes de Juda et aux habitants de Jérusalem: Labourez une terre neuve, et ne semez point parmi les chardons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'Circoncisez-vous pour votre Dieu, circoncisez la dureté de vos cœurs, hommes de Juda, et vous, habitants de Jérusalem, de peur que ma colère ne jaillisse comme une flamme et ne vous brûle, et que nul ne soit là pour l’éteindre à la vue de la malice de vos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Annoncez à Juda, et qu’on vous entende en Jérusalem; dites: Donnez le signal de la trompette sur la terre; criez fort et dites: Rassemblez-vous tous, et entrez dans les villes fortifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Emportez tout ce que vous pourrez; réfugiez-vous dans Sion; hâtez-vous, ne faites point de halte; car moi, je vais vous amener de l’aquilon des maux et de grands brisements de cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Le lion est sorti de son antre; il s’est élancé exterminant les nations, et il est parti de sa contrée pour faire de la terre une solitude; et les cités seront abattues, parce qu’il n’y aura plus d’habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'C’est pourquoi ceignez-vous de cilices, frappez-vous la poitrine, jetez de grands cris; car la colère du Seigneur ne s’est point détournée de vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Et en ce jour, dit le Seigneur, périra le cœur du roi et le cœur des princes; les prêtres seront saisis de stupeur, et les prophètes seront confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Et je dis O Seigneur, maître, est-ce donc que vous avez trompé ce peuple et Jérusalem, disant: La paix régnera, et voilà que le glaive a pénétré jusqu’à leur âme!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'En ce temps-là, on viendra dire à ce peuple et à Jérusalem: Un esprit d’erreur souffle au désert; la voie de la fille de mon peuple ne conduit ni à la pureté ni à la sainteté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Mais un souffle de plénitude me viendra; et alors moi je dirai mes jugements contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Voilà qu’il va venir comme une nuée, et son char sera comme un vent impétueux, ses chevaux plus rapides que l’aigle: Malheur à nous! car nous serons accablés de souffrances.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Jérusalem, lave ton cœur de tes méchancetés, afin que tu sois sauvée. Jusques à quand resteront-elles en ton cœur, les pensées qui causent tes maux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Car la voix du messager de malheur viendra de Dan, et on ouïra des cris de douleur des montagnes d’Éphraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Vous êtes averties, nations; voilà qu’ils sont arrivés, proclamez-le dans Jérusalem; leurs bandes viennent d’une terre lointaine, et elles ont poussé des cris contre la ville de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Comme les gardiens d’un champ, ils font une enceinte autour d’elle; parce que tu m’as négligé, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Tes voies et tes pensées ont attiré sur toi de tels maux, parce que ta méchanceté a été pleine d’amertume, et a pénétré jusqu’au fond de ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 19, 'Mes entrailles, je souffre en mes entrailles et dans les sensations de mon cœur; mon âme est agitée de transports; mon cœur est déchiré. Je ne garderai point le silence; car mon âme a entendu le son de la trompette et les cris de la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 20, 'Et de sa profonde misère elle appelle le secours de la contrition; car toute la terre a été dans la désolation, le tabernacle a été soudain désolé, et les tentures en ont été dispersées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 21, 'Jusques à quand verrai-je mes guerriers en fuite, et entendrai-je le son de la trompette?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 22, 'Les princes de mon peuple ne m’ont point reconnu; ce sont des fils insensés et privés d’intelligence; ils sont habiles pour mal faire, et ne savent pas faire le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 23, 'J’ai regardé la terre, et voilà qu’il n’y avait plus rien; j’ai regardé le ciel, et ses astres n’étaient plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 24, 'J’ai vu les montagnes, et elles étaient tremblantes, toutes les collines pleines de troubles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 25, 'J’ai regardé, et voilà qu’il n’y avait pas un homme, et tous les oiseaux du ciel étaient effarouchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 26, 'J’ai vu, et voilà que le Carmel était désert, et toutes les villes brûlées par le feu, devant la face du Seigneur; elles avaient toutes été effacées devant la face de sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 27, 'Or voici ce que dit le Seigneur: Toute la terre sera déserte; mais je ne la ferai point périr tout entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 28, 'Que la terre pleure sur ces maux; que le ciel s’obscurcisse en ses hauteurs; j’ai parlé et je ne me repentirai pas; je me suis élancé en avant, et je ne me détournerai pas du but.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 29, 'Aux cris du cavalier, à l’aspect de l’arc tendu, toute la terre s’est enfuie; ils sont entrés dans les cavernes, ils se sont cachés dans les bois, ils sont montés sur les rochers. Toute ville a été abandonnée; il n’y reste pas un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 30, 'Et toi, que feras-tu? Tu auras beau te revêtir d’écarlate, mettre tes joyaux d’or, teindre en noir tes sourcils; tu te seras parée en vain. Tes amants t’ont repoussée, c’est ta vie qu’ils demandent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 31, 'J’ai entendu tes cris comme ceux d’une femme en mal d’enfant, tes gémissements comme ceux d’une mère qui enfante pour la première fois; la voix de la fille de Sion sera brisée, et elle laissera tomber ses mains. Malheur à moi! dira-t-elle, mon âme est défaillante au milieu des morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Parcourez les rues de Jérusalem, voyez et informez-vous, cherchez dans ses places si vous y trouverez un homme, s’il en est un seul qui fasse la justice et qui désire la foi; et je leur pardonnerai, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Ils disent: Vive le Seigneur! et en cela ne font-ils pas un faux serment?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Seigneur, vos yeux considèrent la foi; vous les avez flagellés, et ils ne l’ont point senti; vous les avez consumés, et ils n’ont point profité de la correction. Ils se sont fait un front plus dur que le roc, et n’ont point voulu se convertir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Et j’ai dit: Peut-être sont-ils pauvres, et est-ce pour cela qu’ils sont faibles, et n’ont connu ni la voie du Seigneur ni le jugement de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'J’irai donc vers les riches, et je leur parlerai; car ceux-là ont appris à connaître la voie du Seigneur et le jugement de Dieu; mais voilà qu’unanimement ils ont brisé le joug et mis en pièces les liens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'C’est pourquoi, le lion sortant de la forêt les a blessés, et le loup les a détruits jusque dans leurs demeures, et la panthère s’est élevée contre leurs cités. Quiconque est issu d’eux sera poursuivi comme une proie, parce qu’ils ont multiplié leurs impiétés et se sont endurcis dans leurs rébellions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Comment puis-je leur être propice? Tes fils m’ont délaissé, et ils ont juré par ce qui n’est point Dieu; je les ai nourris en abondance, et ils ont commis des adultères, et ils ont logé dans les maisons des prostituées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Ils sont devenus comme des chevaux courant après des cavales; chacun s’est mis à hennir auprès de la femme de son prochain:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Est-ce que je ne les visiterai pas pour ces choses? dit le Seigneur; est-ce que mon âme ne tirera pas vengeance d’un tel peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Montez sur ses créneaux et renversez-les; mais ne la détruisez pas de fond en comble; laissez-en les fondations, parce qu’elles appartiennent au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Parce que la maison d’Israël et la maison de Juda');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Elles ont menti au Seigneur, disant: Les choses ne sont pas ainsi, les maux ne viendront pas sur nous, et nous ne verrons ni le glaive ni la famine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Nos prophètes ont parlé en l’air, et la parole du Seigneur n’était pas en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'À cause de cela, voici ce que dit le Seigneur tout-puissant: En punition de ce que vous avez ainsi parlé, voilà que je fais de mes paroles un feu dans ta bouche, et le peuple sera le bois, et le feu consumera le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Je vais amener de loin une nation sur vous, Ô maison d’Israël, dit le Seigneur, une nation dont vous n’entendrez pas le langage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Ce sont tous des hommes forts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Et ils mangeront votre moisson et votre pain; ils dévoreront vos fils et vos filles, ils dévoreront vos brebis et vos bœufs, ils dévoreront vos vignes, vos figuiers et vos oliviers, et ils détruiront de fond en comble, par le glaive, vos places fortes, en qui vous aviez mis votre confiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'En ces jours-là, dit le Seigneur votre Dieu, je ne vous exterminerai pas entièrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Et lorsque vous direz: Pourquoi le Seigneur, notre Dieu, nous a-t-il fait ces choses? tu leur diras: En punition de ce que vous avez servi, dans votre terre, des dieux étrangers, vous aussi vous servirez des étrangers en une terre qui ne sera pas la vôtre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Publiez ces choses dans la maison de Jacob, qu’elles soient entendues dans la maison de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Écoutez donc ces choses, peuple insensé et sans cœur qui avez des yeux, et ne voyez pas; qui avez des oreilles, et n’entendez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 22, 'Ne me craindrez-vous point? dit le Seigneur; n’aurez-vous point de respect pour moi qui ai donné à la mer les sables pour limites? C’est un commandement éternel; et elle ne l’enfreindra point; elle s’agitera, mais elle ne prévaudra point; et ses flots bruiront, mais ils ne me désobéiront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 23, 'Le cœur de ce peuple est indocile et incrédule; ils se sont détournés et éloignés de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 24, 'Et ils n’ont point dit en leur âme: Craignons maintenant le Seigneur notre Dieu, qui nous a donné la pluie du printemps et celle de l’automne, comme il convient pour l’achèvement de la moisson au temps prescrit, et qui a veillé sur nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 25, 'Vos iniquités ont troublé ce cours des choses, et vos péchés ont éloigné de vous mes biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 26, 'Parce que, parmi mon peuple, il s’est trouvé des impies, et ils ont placé des piéges pour perdre les hommes, et ils les ont surpris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 27, 'Tel un filet tendu est plein d’oiseaux, telle leur maison est pleine de fraude. Et c’est ainsi qu’ils sont devenus grands et se sont enrichis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 28, 'Et ils ont transgressé la justice, et ils n’ont point jugé la cause de l’orphelin ni jugé celle de la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 29, 'Et pour tout cela est-ce que je ne les visiterai pas? dit le Seigneur; est-ce que mon âme ne tirera pas vengeance d’un tel peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 30, 'La stupeur et l’horreur ont régné sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 31, 'Les prophètes prophétisent l’iniquité; les prêtres applaudissent des mains, et mon peuple les aime pour avoir fait ainsi. Que pouvez-vous faire de plus après cela?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Armez-vous de force, fils de Benjamin, pour fuir du milieu de Jérusalem; sonnez de la trompette à Thécué, et levez l’étendard de Béthacharam, parce que, du côté de l’aquilon, des maux nous menacent, et qu’une grande affliction arrive sur nous;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Et ton orgueil sera abaissé, fille de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Contre elle marcheront les pasteurs avec leurs troupeaux, et ils dresseront leurs tentes autour d’elle, et chacun y viendra paître sa part de bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Préparez-vous à la combattre; levez-vous, et donnons-lui l’assaut en plein midi. Malheur à nous! parce que le jour décline, et que les ombres du jour s’évanouissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'Levez-vous, et donnons-lui l’assaut dans les ténèbres, et arrachons-lui ses fondations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'Car voici ce que dit le Seigneur: Abats ses arbres, répands tes forces autour de Jérusalem. O ville menteuse, il y a en elle toute sorte d’oppression.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Comme une citerne refroidit l’eau, ainsi sa méchanceté glace de froid; sans cesse on entend parler devant elle d’impiétés et d’afflictions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Jérusalem, tu seras instruite par le fouet et la douleur; mon âme ne se séparera point de toi que je n’aie fait de toi une terre impraticable, qui ne sera plus habitée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Car voici ce que dit le Seigneur: Grappillez, grappillez comme une vigne les restes d’Israël; allez et revenez, comme le vendangeur pour remplir son panier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'À qui vais-je parler et attester, et qui m’écoutera? Voilà que leurs oreilles sont incirconcises, et ils ne pourront entendre. Voilà que la parole du Seigneur leur inspire du mépris, et ils n’en veulent point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Et j’ai assouvi ma colère, et je l’ai contenue en moi, et je ne les ai pas entièrement détruits. Mais je la répandrai au dehors sur les enfants à la mamelle, sur la synagogue des jeunes gens; en même temps l’on prendra les hommes et les femmes, et le vieillard plein de jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Et leurs maisons, leurs champs, leurs femmes aussi appartiendront à d’autres, parce que j’étendrai la main sur les habitants de cette terre, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Car, du petit au grand, ils ont commis des iniquités; depuis le prêtre jusqu’au faux prophète, ils ont fait des œuvres de mensonge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ils pansaient les plaies de mon peuple, mais avec dédain, en lui disant: La paix, la paix! Et où est-elle la paix?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Aussi ont-ils été confondus parce qu’ils ont failli. Et encore ils n’ont pas été confondus comme ceux qui le sont réellement; car leur confusion même ne les a pas confondus. Et à cause de cela ils tomberont, et ce sera leur ruine; et au temps de ma visite ils périront, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Voici ce que dit le Seigneur: Tenez-vous dans les voies, et regardez, et informez-vous des éternels sentiers du Seigneur. Voyez quelle est la bonne voie et marchez-y, et vous trouverez la purification de vos âmes. Et ils ont dit: Nous n’irons pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'J’ai établi sur vous des sentinelles, disant: Écoutez la voix de la trompette. Et ils ont dit: Nous n’écouterons pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'À cause de cela, ils ont entendu les nations, et ceux qui paissaient leurs troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 19, 'Terre, écoute: Voilà que je vais amener sur ce peuple des malheurs, fruit de leur rébellion; car ils n’ont point eu souci de mes paroles, et ils ont répudié ma loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 20, 'À quoi bon m’offrir de l’encens de Saba et du cinnamome d’une contrée lointaine, vos holocaustes ne me sont point agréables, et vos victimes ne me causent point de joie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 21, 'Et c’est pourquoi le Seigneur a dit: Voilà que je vais envoyer une maladie sur ce peuple; les pères et les fils tomberont malades ensemble, les proches périront avec leurs voisins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 22, 'Et le Seigneur a dit: Voilà qu’un peuple vient de l’aquilon, et les nations se lèveront des extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 23, 'Ils tiendront l’arc et le javelot. Ce peuple est audacieux, il sera sans pitié; sa voix est comme les flots de la mer; il combattra à cheval et sur des chars et tombera sur toi comme la flamme, ô fille de Sion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 24, 'Nous avons entendu ce qu’on en dit, et nos mains en sont défaillantes; l’angoisse nous a saisis avec des douleurs comme celles de l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 25, 'Ne sortez pas dans les champs, n’allez pas sur les chemins; car le glaive des ennemis est là tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 26, 'Fille de mon peuple, ceins-toi d’un cilice; couvretoi de cendre; frappe amèrement ta poitrine, comme lorsqu’on pleure un bien-aimé; car soudain le malheur tombera sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 27, 'Je t’ai établi pour mettre à l’épreuve ces peuples tant de fois éprouvés, et tu me connaîtras à ma manière d’éprouver moi-même leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 28, 'Ils sont tous indociles, ils ne marchent point droit; c’est de l’airain et du fer, ils sont tous corrompus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 29, 'Le soufflet manque à la forge, le plomb y manque, le batteur d’argent frappe à vide; seule leur malice n’est point épuisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 30, 'Appelez-les de l’argent réprouvé; car ils sont réprouvés par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Écoutez tous la parole du Seigneur, peuples de la Judée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Voici ce que dit le Seigneur Dieu d’Israël: Redressez vos voies et vos pensées, et j’habiterai avec vous en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Ne mettez pas votre confiance en vous-mêmes, ni en des paroles de mensonge; car il ne vous servira nullement de dire: Le temple du Seigneur, le temple du Seigneur est ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Car si vous redressez vos voies et vos actions, si vous rendez la justice entre un homme et son prochain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Si vous n’opprimez pas l’étranger, ni l’orphelin, ni la veuve; si vous ne versez pas le sang innocent dans ce');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'J’habiterai ce lieu avec vous, en la terre que j’ai donnée, de siècle en siècle, à vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Mais si vous mettez votre confiance en des paroles de mensonge, dont vous ne retirerez aucun secours;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Si vous tuez, si vous commettez des adultères, si vous volez, si vous jurez faussement, si vous brûlez de l’encens à Baal, et si vous courez, pour votre malheur, après des dieux étrangers qui vous étaient inconnus;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Et après cela, si vous venez, si vous vous placez devant moi en cette maison où mon nom a été invoqué, disant Nous nous sommes abstenus de commettre ces abominations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Moi je vous dirai: Est-ce une caverne de voleurs, ma maison où mon nom a été invoqué devant vous? Je vous ai vus, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Allez en ce lieu qui m’appartient, à Silo, où d’abord j’avais abrité mon nom; et voyez comment je l’ai traité, à la vue de la méchanceté de mon peuple Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Et maintenant parce que vous avez fait toutes ces œuvres, parce que je vous ai parlé, et que vous ne m’avez pas écouté; parce que je vous ai appelés et que vous ne m’avez pas répondu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Je traiterai cette maison où mon nom a été invoqué, et en qui vous mettiez votre confiance, je traiterai cette terre que j’ai donnée à vos pères et à vous, comme j’ai traité Silo.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Et je vous rejetterai loin de ma face, comme j’ai rejeté vos frères, toute la race d’Éphraïm.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Et toi, garde-toi de prier pour ce peuple; ne demande pas que je lui fasse miséricorde; ne prie pas et ne viens pas à moi pour eux, car je ne t’exaucerai point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Ne vois-tu pas ce qu’ils font dans les villes de Juda et dans les rues de Jérusalem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 17, 'Leurs fils amassent le bois, et les pères allument le feu, et leurs femmes pétrissent la pâte pour offrir des gâteaux à la reine du ciel, et ils répandent des libations pour des dieux étrangers, afin de provoquer ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 18, 'Est-ce moi qu’ils provoquent ainsi? dit le Seigneur. N’est-ce pas eux-mêmes, pour que leur front soit couvert de honte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 19, 'Et c’est pourquoi le Seigneur a dit: Voilà que ma vengeance et ma colère vont fondre sur ce lieu et sur les hommes, et sur le bétail, et sur tous les arbres de leurs champs, et sur les fruits de la terre; ma colère brûlera et ne s’éteindra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 20, 'Voici ce que dit le Seigneur: Multipliez vos holocaustes et vos victimes, et mangez-en les chairs:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 21, 'Parce que je n’ai point parlé à vos pères, et que je ne leur ai rien prescrit, le jour où je les ai ramenés de la terre d’Égypte, concernant les holocaustes et les sacrifices:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 24, 'Et ils ne m’ont point écouté, et ils ne m’ont point prêté l’oreille; mais ils ont couru après tous les désirs de leurs cœurs pervers, et ils ont reculé au lieu d’avancer,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 25, 'Depuis le jour où leurs pères sont sortis de l’Égypte jusqu’à ce jour. Et je vous ai envoyé mes serviteurs les prophètes de jour en jour dès l’aurore; je les leur ai envoyés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 26, 'Et ils ne m’ont point écouté, et ils ne m’ont point prêté l’oreille, et ils ont endurci leur tête plus que leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 27, 'et 28. Or tu leur diras cette parole: Voici la nation qui n’a point écouté la voix du Seigneur, et n’a point profité des corrections; la foi est bannie de leur bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 29, 'Coupe tes cheveux, et jette-les loin de toi; et mets une lamentation sur tes lèvres; car le Seigneur a réprouvé, il a répudié la race qui a fait ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 30, 'Car les enfants de Juda ont fait le mal devant moi, dit le Seigneur; ils ont introduit leurs abominations dans la maison où était invoqué mon nom, afin de le profaner.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 31, 'Et ils ont bâti l’autel de Tapheth dans la vallée des fils d’Ennom pour y brûler par le feu leurs fils et leurs filles, sacrifice que je ne leur ai point prescrit et auquel je n’ai jamais songé en mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 32, 'À cause de cela, voilà que les jours arrivent, dit le Seigneur, et on ne dira plus: L’autel de Tapheth, la vallée des fils d’Ennom; mais, la vallée des égorgés; et on inhumera les morts en Tapheth, parce qu’on n’aura point d’autre place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 33, 'Et les morts de ce peuple seront la proie des oiseaux du ciel et des bêtes fauves des champs; et nul ne sera là pour les chasser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 34, 'Et dans les villes de Juda et dans les rues de Jérusalem je ferai taire la voix de la joie et de l’allégresse, la voix du fiancé et de la fiancée; car toute la terre sera devenue une solitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'En ce temps-là, dit le Seigneur, on retirera de leurs sépulcres les os des rois de Juda, les os de ses princes, les os des prêtres, les os des prophètes, et les os des habitants de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Et on les étalera pour qu’ils sèchent aux rayons du soleil, de la lune, de toutes les étoiles, et de toute l’armée céleste que ces hommes avaient aimés, qu’ils avaient servis, après lesquels ils avaient couru, auxquels ils s’étaient attachés et qu’ils avaient adorés. Et ces hommes, on ne pleurera plus sur eux, ils ne seront pas ensevelis et ils seront en exemple sur la face de la terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Parce qu’ils ont préféré la mort à la vie, et ceux qui seront restés de cette race, en quelque lieu que ce soit, je les expulserai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Car voici ce que dit le Seigneur: Celui qui tombe ne se relève-t-il pas, et celui qui s’est détourné du chemin n’y revient-il pas?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Pourquoi donc mon peuple a-t-il dévié sans pudeur? pourquoi s’est-il opiniâtré dans son mauvais choix, et a-til refusé de se convertir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Maintenant prêtez l’oreille et écoutez Nul ne se repent de sa méchanceté; en est-il qui diront: Qu’ai-je');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'La grue dans le ciel connaît sa saison; la tourterelle, l’hirondelle des champs et le passereau observent le moment où ils couvent; mais mon peuple n’a pas connu les jugements du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Comment direz-vous: Nous sommes sages, et la loi du Seigneur est avec nous? La plume menteuse de vos scribes écrit des erreurs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Vos sages ont été confondus, et ils ont tremblé, et ils ont été pris, parce qu’ils ont rejeté la loi du Seigneur; quelle sagesse y a-t-il donc en eux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'À cause de cela, je donnerai leurs femmes à d’autres, et leurs champs à des héritiers étrangers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, '12. et 13. Qui en recueilleront les fruits, dit le Seigneur; il n’y aura pas de raisins dans leurs vignes, pas de figues sur leurs figuiers, et les feuilles en tomberont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Pourquoi demeurons-nous en repos? Rassemblons-nous, et retirons-nous dans nos places fortes, et là soyons comme des rebuts, puisque le Seigneur nous a rejetés, et qu’il nous a abreuvés d’eau mêlée de fiel en punition de nos péchés envers lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Nous nous attendions à la paix, et il ne nous est venu rien de bon; à la guérison, et voilà que c’était la souffrance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'De Dan nous entendons le bruit de leur cavalerie rapide; toute la terre a tremblé au bruit des hennissements de ses chevaux; elle viendra, elle dévorera la terre et ses richesses, la ville et ses habitants;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Car voilà que je vous envoie des serpents mortels contre lesquels il n’est point de charmes, et ils vous mordront,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Sans qu’il y ait de remède, et vous aurez en outre les douleurs de vos cœurs défaillants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'J’entends les cris que jette, en une terre lointaine, la fille de mon peuple: Est-ce que le Seigneur n’est pas à Sion? est-ce qu’en Sion il n’y a plus de roi? Non, parce qu’ils m’ont exaspéré avec leurs idoles et leurs dieux étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'L’été est passé, la moisson est finie, et nous ne sommes point sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'En mon angoisse, j’ai pris des vêtements de deuil en voyant l’affliction de la fille de mon peuple; j’ai été accablé de douleurs telles que celles de l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'N’y a-t-il plus de baume en Galaad? n’y a-t-il plus de médecin? D’où vient que la fille de mon peuple n’est point encore guérie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Qui donnera à ma tête un réservoir d’eau, et à mes yeux une source de larmes? Et je pleurerai mon peuple nuit et jour, et la mort de la fille de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Qui me donnera, dans le désert, une cabane lointaine? Et j’abandonnerai mon peuple, et je m’éloignerai de lui; car ce sont tous des adultères, c’est une assemblée de prévaricateurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Et ils ont tendu leur langue comme un arc; le mensonge, et non la bonne foi, a prévalu sur la terre; car ils ont passé de péché en péché, et ils ne m’ont point connu, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Gardez-vous chacun de votre prochain, ne vous fiez pas à votre frère tout frère supplantera son frère; tout ami s’approchera traîtreusement de son ami.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Chacun se joue de ses amis; on ne dit pas la vérité. Leur langue a appris à dire des mensonges; ils ont commis l’injustice; ils ne font rien pour se convertir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Usure sur usure, fraude sur fraude; ils n’ont point voulu me connaître, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'À cause de cela, voici ce que dit le Seigneur: Je les ferai passer par le feu, et je les éprouverai, et j’agirai ainsi en voyant la perversité de la fille de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Leur langue est une flèche acérée; les paroles de leur bouche sont trompeuses; au prochain, on parle de paix, et on a la haine au cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Est-ce que je ne les visiterai pas pour ces choses? dit le Seigneur; est-ce que mon âme ne tirera pas vengeance d’un tel peuple?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Faites entendre une lamentation sur les montagnes, chantez un cantique funèbre dans les sentiers du désert; car ces lieux sont désolés faute d’hommes. On n’y entend plus la voix d’êtres vivants, depuis les oiseaux du ciel jusqu’aux troupeaux: ils ont été frappés de stupeur, et ils ont fui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Et je ferai sortir de Jérusalem ses habitants, et elle sera la demeure des dragons; et je mettrai la désolation dans les villes de Juda au point qu’elles ne seront plus habitées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Quel homme est assez intelligent pour comprendre ces choses? Et la parole du Seigneur viendra à lui; qu’il vous annonce pourquoi la terre a péri, et a été brûlée comme un désert, au point qu’on n’y peut plus passer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Et le Seigneur me dit: C’est parce qu’ils ont abandonné la loi que je leur ai donnée face à face, et n’ont pas écouté ma voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Mais ils ont couru après les convoitises de leur cœur pervers, et après des idoles que leurs pères leur avaient appris à adorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'À cause de cela, dit le Seigneur Dieu d’Israël, voilà que je vais les nourrir d’angoisses et les abreuver d’eau mêlée de fiel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 16, 'Et je les disperserai parmi les nations, chez des hommes que ni eux ni leurs pères n’ont connus; et je ferai tomber sur eux le glaive, jusqu’à ce que le glaive les ait détruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 17, 'Voici ce que dit le Seigneur: Appelez des pleureuses, et qu’elles viennent; envoyez chercher les plus habiles à pleurer, et qu’elles élèvent la voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 18, 'Et qu’elles chantent une lamentation sur vous, et que des larmes tombent de vos yeux, et que vos paupières soient inondées de pleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 19, 'Car leur voix lamentable a été entendue en Sion: Comment sommes-nous réduits à cet état de misère, tellement confondus que nous avons abandonné notre terre et renversé nos tabernacles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 20, 'Femmes, écoutez la parole de Dieu, et que vos oreilles recueillent les paroles de sa bouche: Apprenez à vos filles des lamentations, apprenez-vous les unes aux autres des cantiques funèbres:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 21, 'Parce que la mort est montée par vos fenêtres, et qu’elle est entrée dans votre terre pour exterminer au dehors les enfants à la mamelle, et dans les rues les adolescents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 22, 'Et les cadavres des hommes resteront en exemple sur la surface de votre terre, comme le chaume reste derrière le moissonneur; et nul ne sera là pour les recueillir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 23, 'Voici ce que dit le Seigneur: Que le sage ne se glorifie pas dans sa sagesse; que le fort ne se glorifie pas dans sa force; que le riche ne se glorifie pas dans sa richesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 24, 'Mais que celui qui se glorifie se glorifie de comprendre et de savoir que c’est moi le Seigneur, moi qui fais sur la terre miséricorde, jugement et justice; car c’est en cela que je me complais, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 25, 'Voilà que les jours viennent, dit le Seigneur, où je visiterai tous les circoncis en leur chair,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 26, 'Et l’Égypte, et l’Idumée, et Édom, et les fils d’Ammon, et les fils de Moab et tous ceux qui se coupent la chevelure au-dessus du front, et qui habitent le désert; car tous ces peuples sont incirconcis en leur chair, et toute la maison d’Israël incirconcise en son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Écoutez la parole du Seigneur, celle qu’il a dite pour vous, maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Voici ce que dit le Seigneur: Ne vous instruisez point selon les voies des gentils; ne craignez point les signes du ciel qu’ils adorent en se prosternant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Car les objets du culte des gentils sont choses vaines: c’est un arbre abattu dans la forêt, œuvre d’un charpentier;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'C’est un métal fondu, orné d’argent ou d’or battus; et on les a affermis avec des clous:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'On les a dressés, et ils ne bougeront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, '(Vulg., 9.) C’est de l’argent travaillé, il ne marchera jamais; c’est une image en argent de Tharsis; viendra aussi l’or de Mophaz, et la main du fondeur; ce sont');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Elles ne peuvent aller qu’on ne les porte; elles ne monteront pas à cheval. Ne les craignez point, elles ne vous feront point de mal, et il n’y a pas de bien à en attendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Dites-leur: Que des dieux qui n’ont créé ni le ciel ni la terre périssent sur la terre et sous le ciel. 9. (12.) C’est le Seigneur qui a fait la terre par sa puissance, qui a affermi le monde par sa sagesse, qui a étendu le ciel par son intelligence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, '(13.) Et l’amas des eaux sous le ciel. Et il a rassemblé les nuages des extrémités de la terre; il a mêlé les éclairs à la pluie, et tiré la lumière de ses trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, '(14.) Tout homme n’est qu’un insensé en fait de science; l’orfévre a été confondu dans ses idoles; car il a fait des choses mensongères, des corps sans vie. 12. (15.) Vaines et ridicules sont ces œuvres, de la visite elles périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, '(16.) Tel n’est point le partage de Jacob, parce que le Créateur de toutes choses est lui-même son héritage; son nom est le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, '(17.) Il a recueilli du dehors ta substance qui était en des vases choisis, la substance de son peuple, c’està-dire les patriarches, qui étaient des vases d’élection, choisis par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, '(18.) Or ainsi parle le Seigneur: Voilà que je vais accabler de tribulations les habitants de cette terre, afin que ta plaie soit mise à nu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, '(19.) Malheur sur ta meurtrissure, ta plaie est douloureuse. Et moi j’ai dit: En vérité c’est ta blessure, c’est elle qui te punit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, '(20.) Ton tabernacle est dévasté, il a péri, et toutes les tentures en sont déchirées. Mes fils et mes brebis ne sont plus, il n’y a plus de place pour mon tabernacle ni pour ses tentures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, '(21.) Parce que mes pasteurs ont été insensés et n’ont point cherché le Seigneur, à cause de cela le troupeau a été sans intelligence et les agneaux dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 19, '(22.) Voilà qu’un bruit de voix arrive; et la terre a tremblé du côté de l’aquilon, pour rendre désertes les villes de Juda, et en faire la demeure des autruches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 20, '(23.) Seigneur, je sais que la voie de l’homme n’est point en lui, et que ce n’est point un homme qui viendra pour redresser sa marche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 21, '(24.) Châtiez-nous, Seigneur, mais avec justice, et non avec colère, afin que nous ne soyons pas réduits à un petit nombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 22, '(23.) Versez votre courroux sur les nations qui ne vous connaissent pas, et sur les races qui n’ont point invoqué votre nom; car celles-ci ont dévoré Jacob, elles l’ont épuisé, et de son pâturage elles ont fait une solitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Voici la parole du Seigneur qui est venue à Jérémie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Écoutez tous les paroles de cette alliance; et toi parle aux hommes de Juda et à ceux qui habitent Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Dis-leur Voici ce que dit le Seigneur Dieu d’Israël: Maudit soit l’homme qui n’écoutera pas les paroles de cette alliance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Que j’ai commandée à vos pères, le jour où je les ai conduits hors de la terre d’Égypte, hors de la fournaise de fer, disant: Soyez dociles à ma voix, et faites toutes les choses que je vous prescris; et vous serez mon peuple, et moi je serai votre Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Afin que j’accomplisse le serment que j’ai fait à vos pères de leur donner une terre où coulent le lait et le miel, comme en ce jour. Et je répondis: Seigneur, qu’il soit ainsi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Et le Seigneur me dit: Lis ces paroles dans les villes de Juda et hors de Jérusalem, disant: Écoutez les paroles de cette alliance, et mettez-les en pratique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Et ils ne les ont point pratiquées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Et le Seigneur me dit: On a découvert un complot tramé contre moi par les hommes de Juda, et ceux qui habitent Jérusalem;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Ils sont revenus aux iniquités de leurs pères, qui autrefois n’ont point voulu écouter mes paroles, et voilà qu’ils marchent à la suite des dieux étrangers pour les servir; et la maison d’Israël et la maison de Juda ont déchiré l’alliance que j’avais faite avec leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'À cause de cela, ainsi dit le Seigneur: Voilà que je vais amener sur ce peuple des maux dont il ne pourra se tirer; et ils crieront vers moi, et je ne les écouterai pas,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Et les villes de Juda et les habitants de Jérusalem s’en iront, et ils crieront vers les dieux étrangers, pour qui ils ont brûlé de l’encens; et ces dieux ne les sauveront pas au temps de leurs malheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Car, Juda, tu as autant de dieux que de villes; et vous avez dressé autant d’autels pour sacrifier à Baal qu’il y a de rues à Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Et toi, ne prie point pour ce peuple, n’inter');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'D’où vient que ma bien-aimée a commis l’abomination dans ma demeure? Les prières ou les chairs sanctifiées effaceront-elles les malices ou te les feront-elles éviter?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Le Seigneur t’a donné le nom d’olivier, beau à la vue et donnant un bon ombrage; mais au bruit de son ébranchement, un feu a été allumé contre lui; grande est ton affliction, car ses rameaux sont devenus inutiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Et le Seigneur, qui t’avait plantée, a prononcé des maux contre toi en punition de ta méchanceté, maison d’Israël, et de la tienne, maison de Juda; car ils se sont nui à eux-mêmes pour m’irriter, en brûlant de l’encens à Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Seigneur, instruisez-moi, et je saurai. Et alors j’ai vu leurs machinations contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Mais moi, comme un agneau innocent conduit au sacrifice, je ne remarquais rien. Ils avaient conçu mêlons contre moi un mauvais dessein, disant: Allons, du bois à son pain, effaçons-le de la terre des vivants, nul ne se souvienne de son nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Seigneur, qui jugez selon la justice, qui sondez les reins et les cœurs, puissé-je voir la vengeance que vous tirerez d’eux; car je vous ai exposé ma cause.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'À cause de cela, voici ce que dit le Seigneur contre les hommes d’Anathoth qui en veulent à ma vie, et qui disent: Tu cesseras de prophétiser au nom du Seigneur, sinon tu périras de nos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Et moi, voilà que je les visiterai; leurs jeunes gens mourront par le glaive, et leurs fils et leurs filles mourront de faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Et il ne restera rien d’eux, parce que je vais amener des maux sur les habitants d’Anathoth, en l’année où je les visiterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Seigneur, vous êtes juste; aussi je me défendrai devant vous; je vous demanderai justice. Pourquoi la voie des impies est-elle prospère? pourquoi ceux qui vous ont répudié sont-ils florissants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Vous les avez plantés, et ils ont pris racine; ils ont engendré, et ils ont produit des fruits. Vous êtes près de leur bouche, et loin de leurs reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Et vous, Seigneur, vous me connaissez, vous avez devant vous éprouvé mon cœur; purifiez-les pour le jour de leur égorgement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Jusques à quand la terre sera-t-elle en deuil avec des pâturages et des champs desséchés par la malice de ceux qui l’habitent? Les oiseaux et le bétail ont été détruits, parce que les hommes ont dit: Dieu ne verra point nos voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Tes pieds courent, et te voilà énervé; comment feras-tu donc pour combattre des cavaliers et te confier dans une terre de paix? Que feras-tu contre les débordements du Jourdain?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Tes frères eux-mêmes et la maison de ton père t’ont méprisé; ils ont eux-mêmes crié contre toi, ils se sont donc unis à ceux qui te poursuivaient par derrière; ne te fie pas à eux, quoiqu’ils te disent de belles paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'J’ai abandonné ma maison; j’ai renoncé à mon héritage; j’ai livré aux mains de ses ennemis celle qui était ma bien-aimée et ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Mon héritage est devenu contre moi comme le lion dans une forêt; il a rugi contre moi; à cause de cela je l’ai pris en haine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Mon héritage est-il pour moi un antre d’hyène ou l’enceinte d’une caverne? Allez, rassemblez toutes les bêtes fauves de la terre, et qu’elles viennent dévorer mon héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Maints pasteurs ont ravagé ma vigne; ils ont souillé mon partage; ils ont fait de ma part bien-aimée un désert sans chemin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Elle a été livrée au ravage et à la dévastation. Toute la terre a été frappée de ruine à cause de moi, parce que nul homme n’a souci de moi en son cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Ceux qui la dévastaient sont venus par toutes les voies du désert, parce que le glaive du Seigneur va dévorer la terre d’une extrémité à l’autre; il n’est plus de paix pour aucune chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Semez des froments, et vous récolterez des chardons; leur part d’héritage ne leur rapportera rien; soyez confondus à cause de votre orgueil et de vos outrages à la face du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Car ainsi parle le Seigneur contre tous les méchants voisins qui touchent à mon héritage, que j’ai distribué à mon peuple d’Israël: Voilà que je vais les arracher de leur terre, et je rejetterai Juda du milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Et voici ce qui arrivera: après les avoir bannis, je changerai, et j’aurai pitié d’eux, et je les ferai rentrer dans leurs demeures, chacun dans son héritage et chacun dans son champ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Et ceci arrivera encore s’ils s’instruisent, s’ils apprennent la voie de mon peuple, et à jurer en mon nom: Vive le Seigneur! comme ils avaient enseigné mon peuple à jurer par le nom de Baal, ils seront édifiés au milieu de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Et s’il est une de ces nations qui ne se convertisse pas, je la détruirai, et elle sera perdue à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Voici ce que dit le Seigneur: Pars et achète-toi une ceinture de lin, et mets-la autour de tes reins, et elle ne passera pas l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Et j’achetai la ceinture, selon la parole du Seigneur, et je la mis autour de mes reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Et la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Prends la ceinture qui entoure tes reins, et lèvetoi; puis va sur l’Euphrate, et en ce lieu cache-la dans une crevasse de rocher,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Et je partis, et je cachai la ceinture près de l’Euphrate, comme me l’avait commandé le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Et ceci arriva bien des jours après, le Seigneur me dit: Lève-toi, et va sur l’Euphrate, et retire de ce lieu la ceinture que je t’ai ordonné d’y cacher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Et j’allai sur l’Euphrate, et je creusai, et je retirai la ceinture du lieu où je l’avais enfouie, et voilà qu’elle était si consumée, qu’elle n’était plus bonne à rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Et la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Voici ce que dit le Seigneur: Ainsi je consumerai l’orgueil de Juda et l’orgueil de Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Et ce grand orgueil des hommes qui ne veulent point écouter ma parole, et qui ont marché à la nuit des dieux étrangers, pour les adorer et les servir. Et ils seront comme une ceinture qui n’est plus bonne à rien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Car de même qu’on attache une ceinture aux reins de l’homme, de même je m’étais attaché la maison d’Israël et toute la maison de Juda, pour qu’elles fussent mon peuple renommé, ma fierté et ma gloire; et ils ne m’ont point écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Et tu diras à ce peuple: Chaque outre sera remplie de vin; et s’ils te disent: Ne savons-nous pas que chaque outre sera remplie de vin?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Tu leur diras: Ainsi dit le Seigneur: Voilà que je vais remplir de boisson enivrante ceux qui habitent cette terre, et leurs rois, fils de David assis sur le trône, et leurs prêtres, et tous les hommes de Juda et de Jérusalem;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Et je les disperserai tous: je séparerai le frère du frère, et le père de ses fils. Je n’en aurai point de regrets, dit le Seigneur, et je n’épargnerai personne, et je serai sans pitié en les détruisant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 15, 'Écoutez, prêtez l’oreille, et ne vous élevez pas; car le Seigneur a parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 16, 'Rendez gloire au Seigneur votre Dieu, avant la nuit, avant que vos pieds se heurtent à des montagnes de ténèbres. Et vous attendez la lumière; et ce sera l’ombre de la mort, et les hommes resteront dans l’obscurité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 17, 'Si vous ne m’écoutez point, votre âme pleurera secrètement sur son orgueil, et vos yeux verseront des larmes, parce que le troupeau du Seigneur aura été');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 18, 'Dites au roi et aux princes: Humilicz-vous, prosternez-vous; car votre couronne de gloire a été enlevée de votre tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 19, 'Les villes du midi ont été fermées, et il n’est resté personne pour les ouvrir. Juda a été transporté tout entier; ils ont tous été émigrants et captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 20, 'Lève les yeux, Jérusalem, et vois ceux qui viennent de l’aquilon. Où est le troupeau qui t’a été donné? où sont les brebis qui faisaient ta gloire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 21, 'Que diras-tu, quand ils te visiteront? C’est toi qui les as instruits contre toi, et tes leçons datent de loin. Ne seras-tu pas saisie de douleurs, comme la femme qui enfante?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 22, 'Et si tu dis en ton cœur: Pourquoi ces choses m’arrivent-elles? À cause de la multitude de tes iniquités; ta robe a été soulevée par derrière, pour que tes jambes reçoivent un châtiment infâme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 23, 'Quand un Éthiopien changera la couleur de sa peau, et la panthère sa bigarrure, vous pourrez faire le bien, vous qui n’avez appris que le mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 24, 'Et je les ai dispersés comme des broussailles qu’emporte le vent du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 25, 'Tel sera ton sort, tel sera ton partage pour m’avoir désobéi, dit le Seigneur. Comme tu m’as oublié pour mettre ton espérance en des mensonges,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 26, 'De même je relèverai ta robe sur ta face, et ton ignominie apparaîtra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 27, 'Et tes adultères, et tes hennissements, et ta prostitution à des étrangers; j’ai vu tes abominations sur les collines et dans les champs. Malheur à toi, Jérusalem; car tu n’as pas été purifiée, pour marcher à ma suite. Et jusques à quand en sera-t-il ainsi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 1, 'Et la parole du Seigneur vint à Jérémie au sujet de la sécheresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 2, 'La Judée a pleuré, et ses portes sont solitaires, et la terre est pleine de ténèbres, et un cri s’est élevé en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 3, 'Et les plus grands ont envoyé les plus petits puiser de l’eau. Ceux-ci sont allés aux puits; mais ils n’ont point trouvé d’eau, et ils sont revenus les cruches vides.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 4, 'Et les travaux de la terre ont péri, parce qu’il ne pleuvait pas; les laboureurs ont été confondus, et ils se sont voilé la tête;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 5, 'Et les biches ont mis bas dans la plaine, et elles ont abandonné leurs faons, parce qu’il n’y avait point d’herbe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 6, 'Les ânes sauvages se sont arrêtés dans les vallons ombragés, et ils ont aspiré l’air; leurs yeux ont défailli, parce qu’il n’y avait point de fourrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 7, 'Nos péchés se sont élevés contre nous, Seigneur; prenez soin de nous à cause de vous-même; car nos péchés contre vous sont nombreux, c’est contre vous que nous avons péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 8, 'Seigneur, vous êtes l’espérance d’Israël; c’est vous qui sauvez au temps de l’affliction. Pourquoi êtes-vous devenu à notre égard comme un passager sur la terre, ou comme un indigène allant dans une hôtellerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 9, 'Serez-vous comme un homme endormi ou comme un homme impuissant à sauver? Vous êtes avec nous Seigneur, et votre nom est le nom qui nous est donné; ne nous oubliez plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 10, 'Ainsi dit le Seigneur à ce peuple: Ils ont aimé à remuer leurs pieds, et ils n’y ont pas mis de mesure, et Dieu ne les a pas fait prospérer; maintenant il va se souvenir de leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 11, 'Et le Seigneur me dit: Ne me prie pas en faveur de ce peuple pour le bénir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 12, 'Car lors même qu’ils jeûneraient, je n’exaucerai point leur prière; et s’ils m’offrent des holocaustes et des victimes, je ne les agréerai point. Car moi, je les exter\'minerai par le glaive, la famine et la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 13, 'Et je répondis: O vous, Seigneur vivant, voilà que leurs prophètes prophétisent, et disent: Vous ne verrez pas de glaive; il n’y aura pas de famine parmi vous; car je donnerai à cette terre et à ce lieu la vérité et la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 14, 'Et le Seigneur me dit: Leurs prophètes prophétisent faussement en mon nom; je ne les ai point envoyés; je ne leur ai rien commandé; je ne leur ai rien dit. Ils vous prophétisent d’après des visions mensongères, des augures, des présages, des caprices de leur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 15, 'À cause de cela, dit le Seigneur, et pour ce qui regarde les prophètes qui prophétisent faussement en mon nom, et que je n’ai point envoyés, et qui disent: Il n’y aura en cette terre ni glaive ni famine, ces prophètes mourront d’une maladie cruelle, et ils seront consumés par la faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 16, 'Et le peuple pour qui ils prophétisent, gisant dans les rues de Jérusalem, périra par le glaive ou la famine; et nul n’ensevelira les morts, ni leurs femmes, ni leurs fils, ni leurs filles, et je ferai refluer sur eux leur propre mécha nceté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 17, 'Et tu leur diras cette parole: Que vos yeux versent des larmes nuit et jour, et que vos pleurs ne s’arrêtent pas; car la fille de mon peuple a été écrasée et broyée, et sa blessure est pleine de douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 18, 'Si je sors dans la plaine, voilà des cadavres frappés par le glaive; si je rentre dans la ville, voilà les horreurs de la famine, et le prêtre et le prophète sont allés en une terre qu’ils ne connaissaient pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 19, 'Est-ce que vous avez répudié Juda; et votre âme s’est-elle éloignée de Sion? Pourquoi nous avez-vous frappés, et n’y a-t-il pas pour nous de remède? Nous attendions la paix, et il n’est rien venu d’heureux; la guérison, et voilà le trouble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 20, 'Nous reconnaissons nos péchés et les iniquités de nos pères; car c’est contre vous que nous avons péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 21, 'Cessez, en faveur de votre nom, de détruire le trône de votre gloire; souvenez-vous et ne rompez point votre alliance avec nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 22, 'Y a-t-il une seule idole des nations qui fasse tomber la pluie? Et si le ciel nous accorde ses largesses, n’est-ce point par vous? Aussi nous espérons en vous, Seigneur; car c’est vous qui avez fait toutes ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 1, 'Et le Seigneur me dit: Quand même Moïse et Samuël comparaîtraient devant ma face, mon âme n’est pas pour ce peuple; chasse-le et qu’il s’en aille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 2, 'Et s’ils te disent: Où irons-nous? réponds, voici ce que dit le Seigneur: Vous irez les uns à la peste, les autres au glaive, d’autres à la famine, d’autres à la captivité, autant que ces fléaux en pourront frapper.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 3, 'Et je les punirai de quatre manières, dit le Sei-gneur; il Y aura le glaive pour égorger, les chiens pour déchirer, les bêtes de la terre et les oiseaux du ciel pour dévorer et consumer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 4, 'Et je les livrerai, pour leur affliction, à toutes les nations de la terre, à cause de Manassès, fils d’Ézéchias, roi de Juda, et de tout ce qu’il a fait dans Jérusalem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 5, 'Qui t’épargnera, Jérusalem? Qui craindra de te punir? Qui se penchera vers toi pour te rendre la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 6, 'Tu t’es détournée de moi, dit le Seigneur, tu as reculé loin de moi; et j’étendrai la main sur toi, et je te détruirai, et je ne leur donnerai pas de rémission.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 7, 'Et je les disperserai de toutes parts; aux portes mêmes de mon peuple, ils ont été privés de leurs enfants; ils ont perdu mon peuple par leurs méchancetés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 8, 'Les veuves chez eux ont été multipliées plus que le sable du rivage. J’ai en plein midi envoyé le malheur sur les fils et sur les mères; et la ville, soudain je l’ai frappée de trouble et de terreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 9, 'Celle qui avait sept enfants en est privée; son âme a défailli; son soleil s’est couché au milieu du jour; elle a été confondue et maudite. Ce qui reste d’eux, je le livrerai au glaive en face de leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 10, 'Hélas! ma mère, pourquoi m’avez-vous enfanté, pour être un homme de contradiction par toute la terre? Je n’ai été utile à personne, et personne ne m’a été utile; la force m’a manqué contre ceux qui me maudissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 11, 'Soit, Maître, qu’ils aient raison contre moi si je ne me suis tenu auprès de vous au temps de leurs calamités et au temps de leur tribulation, pour les servir contre leurs ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 12, 'En vain le fer est connu de toi, en vain un vêtement d’airain est ta force;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 13, 'Je livrerai tes trésors au pillage sur ton territoire entier pour prix de tous tes péchés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 14, 'Et je t’asservirai à tes ennemis d’alentour, en une terre que tu ne connaissais pas; car le feu de ma colère est allumé, et il vous brûlera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 15, 'Seigneur, souvenez-vous de moi et visitez-moi; protégez-moi contre ceux qui me poursuivent, et ne tardez pas; sachez que c’est à cause de vous que je suis outragé');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 16, 'Par ceux qui tiennent pour rien votre parole; exterminez-les, et votre parole fera mes délices et la joie de mon cœur, parce que j’ai été appelé de votre nom, Seigneur tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 17, 'Je ne me suis point assis dans leur assemblée quand ils vous raillaient; mais j’ai été saisi de crainte en face de votre main; je me suis assis solitaire, parce que j’étais rempli d’amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 18, 'Pourquoi ceux qui m’affligent ont-ils prévalu sur moi? Ma blessure est profonde: comment en guérirai-je? me voici comme dans une eau trompeuse, à laquelle on ne peut se fier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 19, 'À cause de cela, voici ce que dit le Seigneur: Si tu reviens toujours à moi, je te fortifierai, et tu resteras de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 20, 'Et je te donnerai contre ce peuple une défense et un rempart d’airain; et ils te combattront et ne pourront rien contre toi, parce que je suis avec toi pour te sauver');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 21, 'Et te retirer des mains des méchants, et je te rachèterai de la main des hommes de pestilence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 1, 'Et tu ne prendras point femme, dit le Seigneur Dieu d’Israël,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 2, 'Et il ne te naîtra ni fils ni fille en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 3, 'Car voici ce que dit le Seigneur sur les fils et les filles nés en ce lieu, et sur leurs mères qui les auront mis au monde, et sur leurs pères qui les auront engendrés en cette terre:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 4, 'Ils mourront d’une mort cruelle; on ne pleurera pas sur eux; ils ne seront pas ensevelis; ils resteront en exemple sur la face de la terre; ils seront pour les bêtes de la terre et les oiseaux du ciel; ils périront par le glaive ou seront consumés par la faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 5, 'Voici ce que dit le Seigneur: N’entre pas dans leurs festins funèbres; ne va pas te frapper la poitrine et ne pleure pas sur eux; car j’ai retiré ma paix de ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 6, 'On ne pleurera point sur eux; on ne se fera pas d’incisions; on ne se rasera pas la tête;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 7, 'On ne rompra point dans leur deuil les pains de la consolation sur un mort; on ne fera pas boire le fils dans le calice de consolation, sur son père ou sa mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 8, 'Et toi, tu n’entreras pas dans la maison du banquet pour t’y asseoir, et manger et boire avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 9, 'Car ainsi parle le Seigneur Dieu d’Israël: Voilà qu’en ce lieu, devant vous et de vos jours, je ferai taire la voix des réjouissances et la voix des fêtes, la voix du jeune époux et la voix de l’épousée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 10, 'Et ceci arrivera lorsque tu feras connaître à ce peuple toutes ces paroles, et qu’il te dira: Pourquoi le Seigneur a-t-il dit tant de mal sur nous? Quelle est notre iniquité? quel péché avons-nous commis devant le Seigneur notre Dieu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 11, 'Tu leur diras: C’est en punition de ce que vos pères m’ont abandonné, dit le Seigneur, et ils ont marché à la suite des dieux étrangers; ils les ont servis, et les ont adorés; ils m’ont abandonné, et n’ont point gardé ma loi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 12, 'Et vous-mêmes vous avez fait le mal plus que vos pères; et voilà que chacun de vous court après ce qui plaît à son cœur perverti, si bien qu’on ne m’obéit plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 13, 'Et je vous rejetterai de cette terre, et je vous enverrai en une terre que vous n’avez connue ni vous ni vos pères, où vous servirez d’autres dieux, et de ceux-là n’attendez aucune miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 14, 'À cause de cela, voilà que viennent les jours, dit le Seigneur, où ils ne diront plus: Vive le Seigneur, qui a ramené de la terre d’Égypte les fils d’Israël!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 15, 'Mais, Vive le Seigneur, qui a ramené la maison d’Israël de la terre du nord et de toutes les contrées où ils avaient été transportés! et je les rétablirai dans l’héritage que j’ai donné à leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 16, 'Voilà que je vais envoyer maints pêcheurs, dit le Seigneur Dieu, et ils les pêcheront, et après cela j’enverrai maints chasseurs, et ils leur feront la chasse sur toutes les montagnes, sur toutes les collines, dans toutes les crevasses des rochers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 17, 'Car j’ai les yeux sur toutes leurs voies; et leurs iniquités n’ont point été cachées à mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 18, 'Et je donnerai une double rétribution à leurs méchancetés et aux péchés dont ils ont souillé cette terre, avec les cadavres mêmes de leurs abominations et avec les iniquités qu’ils ont faites en mon héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 19, 'Seigneur, dans les jours de calamités, vous êtes ma force, mon appui, mon refuge. Les gentils viendront à vous des extrémités de la terre, et ils diront: Quelles idoles trompeuses ont possédées nos pères! Il n’y avait en elles aucun secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 20, 'Est-ce que des dieux peuvent être faits par l’homme? et encore ce ne sont pas des dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 21, 'À cause de cela, en ce temps-là, je leur montrerai ma main, et je leur ferai connaître ma puissance, et ils sauront que mon nom est le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 1, '(Vulg., 5.) Maudit l’homme qui a mis en l’homme son espérance, et appuie sur lui la chair de son bras, quand son cœur s’est éloigné de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 2, '(6.) Il sera comme la bruyère dans le désert; il ne verra pas le bien lui venir; il demeurera dans un désert de sel, dans une terre saumâtre et inhabitable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 3, '(7.) Béni l’homme qui a mis sa confiance dans le Seigneur, le Seigneur sera son espoir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 4, '(8.) Il sera comme un arbre croissant au bord des eaux; il enfoncera ses racines dans un terrain humide; il ne craindra rien quand viendra l’ardente chaleur; ses branches touffues l’ombrageront; il ne craindra rien en une année de sécheresse, et il ne cessera de porter des fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 5, '(9.) Le cœur est profond plus que toute chose, et le cœur, c’est l’homme. Qui le connaîtra?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 6, '(10.) Moi, le Seigneur, qui sonde les cœurs, et qui éprouve les reins pour rétribuer chacun selon ses voies et selon les fruits de ses travaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 7, '(11.) La perdrix a crié, elle rassemble les perdreaux qu’elle n’a point produits; tel est l’homme acquérant sa richesse injustement: au milieu de ses jours ses biens l’abandonneront, et à sa dernière heure il sera insensé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 8, '(12.) Pour nous, un trône de gloire élevé est notre sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 9, '(13.) Vous êtes l’attente d’Israël, Seigneur; que tous ceux qui vous ont abandonné soient confondus; que les rebelles soient inscrits sur la terre, parce qu’ils ont abandonné la fontaine de vie, qui est le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 10, '(14.) Guérissez-moi, Seigneur, et je serai guéri; sauvez-moi, et je serai sauvé, parce que vous êtes l’objet de ma gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 11, '(15.) Voilà qu’ils me disent: Où est la parole du Seigneur? Qu’elle vienne!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 12, '(16.) Pour moi, je ne me suis point lassé de vous suivre, et je n’ai point désiré le jour de l’homme; vous le savez, ce qui sort de mes lèvres est devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 13, '(17.) Ne soyez point pour moi un étranger; épargnez-moi quand viendra le jour mauvais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 14, '(18.) Qu’ils soient confondus ceux qui me persécutent, et que je ne sois pas confondu; qu’ils soient alarmés, et que je n’aie point d’alarmes; faites venir sur eux les jours mauvais; affligez-moi d’une double affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 15, '(19.) Voici ce que dit le Seigneur: Va, et tiens-toi sur les portes des enfants de ton peuple, celles par où entrent les rois de Juda, et par où ils sortent, sur toutes les portes de Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 16, '(20.) Et dis-leur: Écoutez la parole du Seigneur, rois de Juda, peuple de la Judée, peuple de Jérusalem, vous tous qui entrez par ces portes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 17, '(21.) Voici ce que dit le Seigneur: Veillez sur vos âmes, ne portez point de fardeaux les jours de sabbat, et ne sortez point des portes de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 18, '(22.) N’emportez point de fardeaux hors de vos maisons les jours de sabbat, et ne faites aucune œuvre; sanctifiez le jour du sabbat, comme je l’ai commandé à vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 19, '(23.) Et ils n’ont point écouté, et ils ont détourné l’oreille, et ils ont endurci leur tête plus que leurs pères, pour ne point m’obéir et ne point recevoir d’avertissement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 20, '(24.) Or ceci arrivera: Si vous êtes dociles, dit le Seigneur, à mon commandement; si vous ne transportez pas de fardeaux par les portes de la ville les jours de sabbat, et si vous sanctifiez les jours de sabbat, en ne faisant aucune œuvre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 21, '(25.) Les rois et les princes assis sur le trône de David, ceux qui montent sur des chars traînés par leurs chevaux, eux et leurs princes, les hommes de Juda et les habitants de Jérusalem, entreront par les portes de cette ville, et elle sera habitée dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 22, '(26.) Et l’on y viendra des villes de Juda qui entourent Jérusalem, et de la terre de Benjamin, et de la plaine et des montagnes, et des régions du midi, pour apporter des holocaustes et des victimes, des parfums, de la manne et de l’encens, et pour offrir des louanges au Seigneur en son temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 23, '(27.) Et ceci arrivera, si vous êtes indociles à mon commandement de sanctifier les jours de sabbat, de ne point porter de fardeaux et de n’en point faire entrer par les portes de Jérusalem les jours de sabbat: j’allumerai à ces portes un feu qui dévorera les rues de Jérusalem, et ne sera pas éteint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 1, 'Parole du Seigneur qui est venue à Jérémie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 2, 'Lève-toi et entre dans la maison d’un potier, et là tu entendras mes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 3, 'Et je descendis dans la maison d’un potier, et voilà qu’il était à l’ouvrage sur sa roue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 4, 'Et le vase qu’il faisait se rompit dans ses mains, et il fit aussitôt un autre vase, comme il lui plut de le faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 5, 'Et la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 6, 'Maison d’Israël, ne puis-je faire avec vous comme ce potier? Voilà que vous êtes dans mes mains comme l’argile du potier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 7, 'Je prononcerai mon souverain jugement contre un peuple ou un royaume, pour le perdre et le détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 8, 'Mais si cette nation se détourne de tous ses péchés, moi aussi, je me repentirai du mal que je songeais à lui faire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 9, 'Et je prononcerai mon jugement contre un peuple ou un royaume, pour le réédifier et le planter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 10, 'Mais s’ils font le mal devant moi, en désobéissant à ma voix, je me repentirai du bien que j’avais promis de leur faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 11, 'Et maintenant j’ai dit aux hommes de Juda et aux habitants de Jérusalem: Voilà que je forge pour vous des maux, et mes pensées sont contre vous; que chacun se détourne de sa mauvaise voie, et faites des œuvres meilleures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 12, 'Et ils ont répondu Nous nous conduirons en hommes, et nous irons à ce qui nous fait dévier; et chacun de nous fera ce qui est agréable à son cœur perverti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 13, 'À cause de cela, voici ce que dit le Seigneur: Demandez maintenant, parmi les gentils, qui a jamais entendu parler de choses aussi horribles que celles qu’a faites la vierge d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 14, 'Les réservoirs manquent-ils jamais aux rochers, ou la neige au Liban? L’eau poussée par un vent violent se détourne-t-elle de sa voie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 15, 'Mon peuple m’a oublié; ils ont encensé de vaines idoles; ils ont défailli dans leurs voies, abandonnant les sentiers battus, pour marcher en des chemins impraticab les;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 16, 'Et ils font de leur terre une désolation et un éternel sujet de raillerie; tous ceux qui la traverseront en seront stupéfaits, et ils secoueront la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 17, 'Comme je disperse un vent brûlant, je les disperserai devant leurs ennemis; je leur ferai voir le jour de leur destruction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 18, 'Et ils ont dit: Allons et formons des desseins contre Jérémie. Car la loi ne périra pas chez le prêtre, ni les conseils chez l’homme intelligent, ni la parole chez le prophète; allons, frappons-le de la langue, puis nous entendrons tous ses discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 19, 'Écoutez-moi, Seigneur, écoutez la voix de ma justification.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 20, 'Est-ce que l’on doit rendre le mal pour le bien, pour qu’ils aient dit des paroles contre mon âme et qu’ils m’aient caché la punition qu’ils me réservent? Souvenezvous que je me suis tenu devant votre face, pour vous parler en leur faveur et détourner d’eux votre colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 21, 'À cause de cela, faites que leurs fils soient consumés par la faim, et rassemblez-les pour les livrer aux mains armées de glaives. Que leurs femmes deviennent stériles et veuves; que leurs époux soient frappés de mort, que leurs jeunes gens tombent percés de l’épée dans le combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 22, 'Qu’il y ait des cris en leurs demeures; amenez soudain sur eux des brigands, parce qu’ils ont cherché à me surprendre, et ont caché des filets sous mes pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 23, 'Et vous, Seigneur, vous connaissez leur dessein de me mettre à mort; ne les absolvez pas de leurs iniquités, et que leurs péchés ne soient pas effacés devant vos yeux; qu’ils soient impuissants devant vous, et colère éclate sur eux en son temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 1, 'Alors le Seigneur me dit: Va et achète un vase de terre fait par un potier, et emmène quelques-uns des anciens du peuple et des prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 2, 'Et sors pour aller au cimetière des fils de leurs enfants, qui est devant la porte de Charsith, et fais-leur lecture de toutes les paroles que je vais te dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 3, 'Et dis-leur: Écoutez la parole du Seigneur, rois de Juda, hommes de Juda, habitants de Jérusalem et vous qui entrez par les portes. Ainsi parle le Seigneur Dieu d’Israël: Voilà que je vais amener sur ce lieu des maux tels que les oreilles en tinteront de ceux qui en entendront parler,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 4, 'En punition de ce qu’ils m’ont abandonné, de ce qu’ils ont aliéné ce lieu, et y ont sacrifié à des dieux étrangers, inconnus d’eux et de leurs pères, et de ce que les rois de Juda ont rempli ce lieu du sang des innocents;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 5, 'Et de ce qu’ils ont bâti des hauts lieux à Baal pour y brûler leurs fils dans la flamme; ce que je n’ai point commandé, et dont je n’ai jamais eu la pensée en mon');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 6, 'À cause de cela, voilà que les jours arrivent, dit le Seigneur, où l’on n’appellera plus ce lieu Topheth ni cimetière des fils d’Ennom, mais cimetière des égorgés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 7, 'Car en ce lieu j’égorgerai les conseils de Juda et Ce cimetière était dans la vallée des fils d’Ennom. Vulg. Voy. encore ci-dessus, vII, 3 Et j’amènerai sur cette ville la désolation et les sifflets; quiconque passera près d’elle se moquera et sifflera sur toutes ses plaies. Et ils mangeront les chairs de leurs fils et les chairs de leurs filles; et chacun mangera les chairs de son prochain, dans l’enceinte des fortifications que leurs ennemis auront investie. Et puis brise le vase de terre aux yeux des hommes qui t’auront accompagné; Et ajoute: Voici ce que dit le Seigneur: Ainsi je briserai ce peuple et cette ville, comme on brise un vase de terre qu’on ne peut plus rajuster. Ainsi ferai-je, dit le Seigneur, de ce lieu et de ceux qui l’habitent, pour que cette ville soit comme un lieu de carnage. Et les maisons de Jérusalem et les palais des rois de Juda seront comme un lieu de carnage, à cause de leurs impuretés dans toutes leurs maisons ou sur leurs terrasses; ils y ont encensé toute l’armée céleste et fait des libations à des dieux étrangers. Et Jérémie revint au lieu du carnage où l’avait envoyé le Seigneur pour y prophétiser, et il se tint dans le parvis du temple du Seigneur, et il dit à tout le peuple: Ainsi parle le Seigneur: Voilà que je vais amener sur cette ville et sur toutes ses villes et sur tous ses villages tous les maux dont je l’ai menacée, parce qu’ils ont endurci leur tête pour ne point obéir à mes commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 1, 'Et Paschor, fils d’Emmer le prêtre, qui était établi intendant du temple du Seigneur, entendit Jérémie comme il prophétisait en ses discours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 2, 'Et il le frappa, et il le jeta dans un cachot, à la porte haute d’une maison séparée dans le temple de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 3, 'Puis Paschor fit sortir Jérémie du cachot, et Jérémie lui dit Le Seigneur ne t’appelle plus Paschor, mais l’exilé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 4, 'Car ainsi dit le Seigneur: Voilà que je vais faire emmener en exil toi et tes proches; et ceux-ci tomberont sous le glaive de leurs ennemis, et tes yeux le verront, et je livrerai toi et tout Juda au roi de Babylone, et il vous transportera au loin, et il vous frappera du glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 5, 'Et je livrerai aux mains de ses ennemis toute la richesse de cette ville, tout le fruit de ses travaux, et tous les trésors des rois de Juda, pour les emporter à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 6, 'Et toi et tous ceux qui résident en ta maison, vous irez en captivité, et tụ mourras à Babylone, et tu y seras enseveli avec tes proches, à qui tu as prophétisé le mensonge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 7, 'Vous m’avez trompé, Seigneur, et j’ai été séduit. Vous avez prévalu, car vous avez la force; je suis devenu pour eux un sujet de dérision, et chaque jour ils ne cessent de me railler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 8, 'Je rirai moi-même avec amertume de mon impuissance; j’appellerai sur moi la misère, parce que la parole du Seigneur m’est devenue un opprobre, et que je suis insulté tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 9, 'Et j’ai dit: Je ne prononcerai plus le nom du Seigneur, et je ne parlerai plus en son nom. Et j’ai dans mes os comme un feu ardent; tout mon corps est défaillant; je ne puis plus supporter');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 10, 'De m’entendre outrager par tous ceux qui s’attroupent autour de moi. Conspirez, disent-ils, conspirons tous contre cet homme, nous qui étions ses amis; surveillez ses intentions, s’il peut être séduit, sur lui nous prévaudrons, et de lui nous tirerons vengeance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 11, 'Mais le Seigneur est avec moi, comme un puissant homme de guerre. Aussi m’ont-ils persécuté, mais ils n’ont pu rien découvrir contre moi; et ils ont été grandement confondus, parce qu’ils n’avaient point prévu leur propre honte, qui ne sera plus jamais oubliée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 12, 'Seigneur, qui jugez les choses justes, qui sondez les reins et les cœurs, puissé-je voir la vengeance que vous tirerez d’eux; car je vous ai expliqué ma cause.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 13, 'Chantez le Seigneur; louez-le parce qu’il a dérobé l’âme du pauvre aux mains des méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 14, 'Maudit soit le jour où j’ai été conçu; que le jour où ma mère m’a enfanté ne soit pas glorifié!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 15, 'Maudit soit l’homme qui est venu annoncer à mon père une bonne nouvelle, en disant: II t’est né un fils!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 16, 'Que cet homme se réjouisse comme les villes que le Seigneur, sans pitié, a renversées dans sa colère; qu’il entende des clameurs le matin, et des cris de guerre à midi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 17, 'Parce qu’il ne m’a point tué dans le sein de ma');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 18, 'Fallait-il que je sortisse de ses entrailles, pour ne voir que peines et douleurs, tandis que mes jours s’écoulent dans la honte?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 1, 'Parole du Seigneur qui vint à Jérémie, quand le roi Sédécias lui eut envoyé Paschor, fils de Melchias, et Sophonie, fils de Basaïe le prêtre, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 2, 'Interroge le Seigneur à notre sujet; car le roi de Babylone s’est levé contre nous; demande si le Seigneur fera selon ses merveilles, et si l’ennemi s’éloignera de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 3, 'Et Jérémie leur répondit: Parlez ainsi à Sédécias, roi de Juda:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 4, 'Voici ce que dit le Seigneur: Je ferai retourner contre vous les armes que vous prendrez pour combattre les Chaldéens, qui vous assiègent et entourent vos remparts; et je rassemblerai ceux-ci au milieu de votre ville,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 5, 'Et je vous combattrai dans les transports d’une grande colère avec ma main étendue et mon bras tout-puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 6, 'Et tout ce qui habite cette ville, hommes et bétail, je les frapperai d’une grande peste, et ils mourront,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 7, 'Et après cela voici ce que dit le Seigneur: Sédécias, roi de Juda, et ses serviteurs et ceux du peuple de cette ville, que la peste, la famine, et le glaive n’auront pas enlevés, je les livrerai à leurs ennemis qui en veulent à leur vie; et ceux-ci les passeront au fil de l’épée; je ne les épargnerai pas et je n’aurai d’eux aucune pitié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 8, 'Et je dis à ce peuple: Ainsi parle le Seigneur: Voilà que j’ai mis devant vos yeux le chemin de la vie et le chemin de la mort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 9, 'Celui qui demeurera dans cette ville mourra par le glaive ou la famine; et celui qui en sortira pour se soumettre aux Chaldéens assiégeants vivra, et sa vie lui sera comme un butin, et il vivra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 10, 'Car j’ai arrêté ma face sur cette ville, pour son malheur, et non pour son bien. Elle sera livrée aux mains du roi de Babylone, elle sera brûlée par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 11, 'Maison du roi de Juda, écoutez la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 12, 'Maison de David, voici ce que dit le Seigneur: Rendez la justice dès le matin; marchez avec droiture et délivrez l’homme dépouillé des mains du spoliateur, afin que ma colère ne s’allume plus comme la flamme; car elle brûlera, et nul ne pourra l’éteindre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 13, 'Voilà que je suis contre toi, habitant de la plaine dans la vallée de Sor, et contre vous tous qui dites: Qui nous effrayera? qui entrera dans nos demeures?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 14, 'C’est moi. Je mettrai le feu à la forêt, et l’incendie dévorera tout ce qui l’entoure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 1, 'Voici ce que dit le Seigneur: Va et descends dans le palais du roi de Juda, et là tu diras ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 2, 'Tu diras: Écoute la parole du Seigneur, roi de Juda, qui t’assieds sur le trône de David; écoute-la,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 3, 'Voici ce que dit le Seigneur: Rendez équitablement la justice et délivrez l’homme dépouillé des mains du spoliateur; n’opprimez ni l’étranger, ni l’orphelin, ni la veuve; ne péchez pas, ne versez pas le sang innocent en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 4, 'Car si vous faites selon cette parole, les rois assis sur le trône de David, et ceux qui montent à cheval ou sur des chars, et leurs serviteurs, et leur peuple, continueront d’entrer par ces portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 5, 'Que si vous ne faites pas selon cette parole, par moi-même, je l’ai juré, dit le Seigneur, cette maison sera livrée à la désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 6, 'Car voici ce que dit le Seigneur, touchant la maison du roi de Juda Galaad, tu es pour moi comme la tête du Liban; or je ferai de toi un désert, et tes villes ne seront plus habitées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 7, 'Et je conduirai contre toi un exterminateur armé de sa hache; et ils abattront tes plus beaux cèdres, et ils les jetteront au feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 8, 'Et les gentils traverseront cette ville, et chacun dira à son voisin Pourquoi le Seigneur a-t-il ainsi traité cette grande cité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 9, 'Et on leur répondra: En punition de ce qu’ils ont abandonné l’alliance du Seigneur leur Dieu, et adoré des dieux étrangers, et qu’ils les ont servis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 10, 'Ne pleurez point celui qui est mort; ne vous lamentez pas sur lui; pleurez autrement celui qui sortira; car il ne reviendra plus, et ne verra plus la terre de sa patrie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 11, 'Or voici ce qu’a dit le Seigneur sur Sellum, fils de Josias, lorsque, régnant à la place de son père, il sortit de ce lieu Il ne reviendra plus ici;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 12, 'Mais il mourra au lieu où je l’ai transporté, et il ne verra plus cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 13, 'Ô toi qui te bâtis une maison sans justice, et de grands appartements sans équité, qui travailles avec l’aide de ton voisin gratuitement, et ne lui payes point son salaire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 14, 'Tu t’es bâti une maison symétrique, avec un étage aéré, percé de fenêtres, revêtu de cèdres, peint en vermillon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 15, 'Est-ce que tu régneras parce que tu es violent comme Achaz, ton aïeul? De tels princes ne mangeront pas, ils ne boiront pas. Il eût mieux valu pour toi rendre la justice et le jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 16, 'Mais ils n’ont point su ce qu’ils devaient faire, ils n’ont point rendu justice à l’humble, ni rendu justice à l’indigent; n’est-ce point là me méconnaître? dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 17, 'Voilà que tes yeux ni ton cœur ne sont bons; ils vont après les convoitises et après le sang innocent, pour le répandre, après les iniquités et les meurtres, pour les commettre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 18, 'À cause de cela, voici ce que dit le Seigneur sur Joakim, fils de Josias, roi de Juda, et sur cet homme: On ne se frappera pas la poitrine, disant: Ah! frère; on ne le pleurera point, disant: Hélas! Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 19, 'Il aura la sépulture d’un âne, il sera jeté en lambeaux hors de la porte de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 20, 'Monte sur le Liban et crie; fais entendre ta voix vers le Basan; crie encore du côté de la mer; tous tes amants ont été broyés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 21, 'Je t’ai parlé quand tu chancelais, et tu as dit: Je n’écouterai pas; telle a été ta voie depuis ta jeunesse, tu n’as pas écouté ma parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 22, 'Tous tes pasteurs se repaîtront de vent, et tes amants seront emmenés captifs; et alors tu seras confondue et tu rougiras de tous ceux qui t’auront aimée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 23, 'Ô toi qui résides sur le Liban, qui as fait ton nid parmi les cèdres, tu gémiras quand viendront sur toi des maux comme ceux de l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 24, 'Par ma vie, dit le Seigneur, quand même, ô Jéchonias, fils de Joakim, roi de Juda, tu serais l’anneau de ma main droite, je t’en arracherai!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 25, 'Et je te livrerai à ceux qui en veulent à ta vie, à ceux dont tu crains le visage, aux mains des Chaldéens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 26, 'Et je te rejetterai, toi et la mère qui t’a enfanté, en une terre où tu n’es point né; et vous y mourrez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 27, 'Mais pour la terre que leurs âmes désirent, ils n’y reviendront jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 28, 'Jéchonias a été sans honneur, comme un vase inutile; il a été rejeté et banni en une terre qu’il ne connaissait pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 29, 'Terre, terre, écoute la parole du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 30, 'Inscris cet homme; c’est un roi détrôné; il n’aura point de rejeton assis sur le trône de David, ni de prince pour régner en Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 1, 'Maudits soient les pasteurs qui perdent et dispersent les brebis de leur pâturage!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 2, 'À cause de cela, voici ce que dit le Seigneur sur les pasteurs de mon peuple: Vous avez dispersé et repoussé mes brebis, et vous ne les avez pas visitées. Et moi je vous punirai de vos méchantes œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 3, 'Moi-même je recueillerai les restes de mon peuple sur toute terre où je les ai bannis, et je les rétablirai en leurs pâturages, et ils croîtront et ils se multiplieront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 4, 'Et je susciterai pour eux des pasteurs qui les mèneront paître, et ils n’auront plus peur, et ils ne trembleront plus, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 5, 'Voilà que les jours arrivent, dit le Seigneur, où je susciterai pour David un soleil de justice, et un roi règnera, et il comprendra, et il rendra justice selon le jugement à toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 6, 'De son temps, Juda sera sauvé, et Israël s’abritera dans ses demeures en toute assurance. Et le nom que lui donnera le Seigneur sera Josédec, parmi les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 7, 'Mon cœur a été brisé en moi, tous mes os ont été ébranlés; je suis devenu comme un homme meurtri ou comme un homme pris de vin, à la vue du Seigneur et de la magnificence de sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 8, '(10.) Devant sa face, la terre est en deuil, et les pâturages du désert sont desséchés; et la course de ces');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 9, '(11.) Le prêtre et le prophète se sont souillés; jusque dans mon temple j’ai vu leur corruption.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 10, '(12.) À cause de cela, que leur voie soit glissante et sombre, et ils y trébucheront, et ils y tomberont; car j’amènerai sur eux des maux en l’année où je les visiterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 11, '(13.) Et les prophètes de Samarie, j’ai vu en eux des iniquités; ils ont prophétisé par Baal, et ils ont égaré mon peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 12, '(14.) Et les prophètes de Jérusalem, j’ai vu en eux des choses horribles; adultères, cheminant dans le mensonge, prenant de toutes mains pour ne point détourner les méchants de leurs voies, ils ont tous été pour moi comme Sodome, et les habitants de Jérusalem comme Gomorrhe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 13, '(15.) À cause de cela, ainsi dit le Seigneur: Voilà que je vais les nourrir de douleurs, et je les abreuverai d’eau saumâtre, parce que des prophètes de Jérusalem est sortie la souillure de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 14, '(16.) Voici ce que dit le Seigneur tout-puissant: N’écoutez point les discours des prophètes, parce qu’ils ont des visions vaines; ils parlent selon leur cœur, et non selon la bouche de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 15, '(17.) Ils disent à ceux qui rejettent la parole du Seigneur La paix sera avec vous; et à ceux qui courent après leurs désirs et après les égarements de leurs cœurs: Il ne vous arrivera rien de mal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 16, '(18.) Car qui a assisté au conseil du Seigneur? qui a vu sa parole? qui l’a entendue de ses oreilles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 17, '(19.) Voilà un tremblement de terre venu du Seigneur, et sa colère produit ce tremblement; elle viendra frapper les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 18, '(20.) Et la colère du Seigneur ne se détournera plus qu’elle n’ait accompli toutes les résolutions de son cœur; et à la fin des jours ils comprendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 19, '(21.) Je n’ai point envoyé ces prophètes, et ils ont couru d’eux-mêmes; je ne leur ai rien dit, et d’euxmêmes ils ont prophétisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 20, '(22.) Et s’ils avaient assisté à mon conseil, s’ils avaient entendu mes paroles, je les aurais corrigés, et corrigé mon peuple de ses mauvaises inclinations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 21, '(23.) Je suis Dieu de près, dit le Seigneur; ne suis-je pas aussi Dieu de loin?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 22, '(24.) Qui se cachera dans le secret, sans que je le découvre? Est-ce que je ne remplis pas le ciel et la terre? dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 23, '(25.) J’ai entendu ce que disent les prophètes, ce qu’ils prophétisent en mon nom; ils mentent quand ils disent: J’ai eu un songe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 24, '(26.) Jusques à quand en sera-t-il ainsi du cœur de ces prophètes, qui prophétisent le mensonge, en prophétisant les séductions de leur cœur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 25, '(27.) Ils s’imaginent faire oublier ma loi par des songes que chacun se raconte, comme d’autres ont fait oublier mon nom à leurs pères à cause de Baal?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 26, '(28.) Que le prophète qui a eu un songe le raconte; que celui à qui est venue ma parole annonce selon la vérité. Qu’est-ce que la paille auprès du grain? Ainsi en est-il de mes paroles, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 27, '(29.) Mes paroles ne sont-elles pas comme le feu, dit le Seigneur, ou comme la hache qui fend un rocher?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 28, '(30.) Voilà pourquoi je suis contre les prophètes, dit le Seigneur Dieu, qui dérobent mes paroles à leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 29, '(31.) Voilà pourquoi je suis contre les prophètes qui prophétisent de la langue et disent les rêves de leur sommeil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 30, '(32.) Voilà pourquoi je suis contre les prophètes qui prophétisent d’après des songes trompeurs et les racontent, et qui ont égaré mon peuple par leurs mensonges et leurs erreurs; et je ne les avais pas envoyés, et je ne leur avais rien prescrit, et ils ne seront d’aucun secours à ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 31, '(33.) Et si ce peuple, ou le prêtre, ou le prophète demandent quel est le fardeau du Seigneur, dis-leur: Vous êtes ce fardeau, et je vous briserai, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 32, '(34.) Si le prophète ou quelqu’un des prêtres ou du peuple se sert de ce mot: Le fardeau du Seigneur, je punirai cet homme et sa maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 33, '(35.) Voici ce que vous direz chacun à votre ami, chacun à votre frère: Qu’a dit le Seigneur? quelle est la parole du Seigneur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 34, '(36.) Mais ne prononcez plus ce mot: Le fardeau du Seigneur; car c’est votre parole qui sera un fardeau pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 35, '(37.) C’est pourquoi il faut dire Le Seigneur Dieu nous a-t-il parlé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 36, '(38.) Voici donc ce que dit le Seigneur notre Dieu: En punition de ce que vous avez prononcé ce mot: Fardeau du Seigneur, après que j’eus envoyé vers vous, et que je vous eus fait dire: Ne dites plus: Le fardeau du Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 37, 'À cause de cela, voilà que moi je vous prends et vous brise, vous et cette ville, que j’ai donnée à vous et à vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 38, 'Et je vous marquerai d’un éternel opprobre, d’une honte éternelle qui ne sera jamais oubliée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 39, 'À cause de cela, voilà que les jours approchent, dit le Seigneur, où ils ne diront plus: Vive le Seigneur, qui a tiré la maison d’Israël de la terre d’Égypte!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 40, 'Mais: Vive le Seigneur, qui a rassemblé toute la race d’Israël, et l’a ramenée de la terre du nord et de toutes les contrées où il les avait bannis, et qui les a rétablis dans leur héritage!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 1, 'Le Seigneur me montra deux corbeilles de figues posées devant la façade du temple du Seigneur, après que Nabuchodonosor eut enlevé Jéchonias, fils de Joakim, roi de Juda, et les princes, et les artisans, et les prisonniers, et les riches de Jérusaleni, et qu’il les eut emmenés à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 2, 'L’une de ces corbeilles contenait de très-bonnes figues, comme celles de la primeur; et l’autre de trèsmauvaises figues qu’on ne pouvait manger, tant elles étaient mauvaises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 3, 'Et le Seigneur me dit: Jérémie, que vois-tu? Et je répondis: Des figues; des figues bonnes, très-bonnes, et d’autres mauvaises, très-mauvaises, qu’on ne peut manger, tant elles sont mauvaises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 4, 'Et la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 5, 'Voici ce que dit le Seigneur Dieu d’Israël: Comme les bonnes figues, je reconnaîtrai les Juifs emmenés en captivité, que j’ai expulsés de ce lieu et envoyés en Chaldée, je les traiterai bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 6, 'Et j’attacherai sur eux mes regards pour leur bien,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 7, 'Et je leur donnerai un cœur pour qu’ils me connaissent, pour qu’ils sachent que je suis le Seigneur; et ils seront mon peuple, et je serai leur Dieu, parce qu’ils se seront convertis à moi de toute leur âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 8, 'Et comme les mauvaises figues qu’on ne peut manger, tant elles sont mauvaises, dit le Seigneur, je livrerai Sédécias, roi de Juda, et ses grands, et le reste de Jérulem qui est demeuré en cette terre, et ceux qui habitent l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 9, 'Et je les livrerai à la dispersion dans tous les royaumes de la terre, et dans les lieux où je les aurai bannis, et ils seront un sujet d’outrages et de railleries, de haine et de malédiction;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 10, 'Et je leur enverrai la famine, et la peste, et le glaive, jusqu’à ce qu’il n’y en n’ait plus sur cette terre que je leur ai donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 1, 'Parole du Seigneur qui vint à Jérémie, touchant tout le peuple de Juda, en la quatrième année du règne de Joakim, fils de Josias, roi de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 2, 'Et qu’il a répétée devant tout le peuple de Juda et devant les habitants de Jérusalem, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 3, 'Depuis la treizième année de Josias, fils d’Amos, roi de Juda, jusqu’à ce jour, il s’est écoulé vingt-trois ans, et je vous ai parlé, me levant au point du jour, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 4, 'Je vous ai envoyé mes serviteurs les prophètes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 5, 'Que chacun de vous se retire de sa mauvaise voie, et se corrige de ses mauvaises habitudes; et vous demeurerez en la terre que j’ai donnée à vous et à vos pères, de siècle en siècle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 6, 'Ne marchez pas à la suite des dieux étrangers, pour les servir et les adorer, de peur que je ne sois irrité par les idoles, œuvres de vos mains, et que je ne vous opprime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 7, 'Et vous ne m’avez point écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 8, 'À cause de cela, dit le Seigneur, puisque vous n’avez point eu foi dans mes paroles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 9, 'Voilà que je vais prendre et vous envoyer une famille qui viendra de l’aquilon, et je la conduirai contre cette terre et ceux qui l’habitent, et contre tous les gentils qui l’entourent; et je leur ferai de leurs champs un désert, un lieu de désolation, un sujet de raillerie et d’opprobre éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 10, 'Et je ferai taire chez eux le bruit de la joie et le bruit des fêtes, la voix de l’époux et la voix de l’épousée; et je disperserai le parfum de la myrrhe, et j’éteindrai la lumière de la lampe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 11, 'Et toute la terre sera désolée, et ils seront en servitude chez les gentils durant soixante-dix ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 12, 'Et lorsque les soixante-dix ans seront accomplis, je punirai la nation qui les aura retenus, et j’en ferai un lieu d’éternelle désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 13, 'Et j’amènerai sur cette terre toutes les paroles que');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 14, '(Vulg., XLIX, 34.) Prophéties de Jérémie contre le peuple d’Élam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 15, '(35.) Voici ce que dit le Seigneur: L’arc d’Élam, le principe de sa force a été brisé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 16, '(36.) Et je ferai venir sur Élam les quatre vents des quatre coins du ciel; et je les disperserai au souffle de ces vents, et il n’y aura point de nation où ne se réfugient les exilés d’Élam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 17, '(37.) Et je les ferai trembler en face de ceux qui en veulent à leur vie; j’amènerai sur eux les coups de ma fureur, et j’enverrai sur eux mon glaive, jusqu’à ce que je les aie exterminés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 18, '(38.) Et je placerai mon trône en Élam, et j’en chasserai le roi et les grands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 19, '(39.) Et voici ce qui arrivera au dernier jour: je ramènerai Elam de la captivité, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 1, 'Au commencement du règne de Sédécias, cette parole vint contre Élam,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 2, 'Pour l’Égypte contre l’armée du Pharaon Néchao, roi d’Égypte, qui était en Charcamis sur l’Euphrate, et que vainquit Nabuchodonosor, roi de Babylone, la quatrième année du règne de Joakim, roi de Juda:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 3, 'Prenez vos armures et vos boucliers, et partez pour la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 4, 'Harnachez les chevaux, cavaliers; montez-les; mettez vos casques; faites vibrer vos javelines et revêtez-vous de vos cuirasses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 5, 'Pourquoi tremblent-ils et tournent-ils le dos? Parce que leurs forts seront taillés en pièces; ils ont pris la fuite; ils ne se sont point retournés; ils sont entourés de toutes parts, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 6, 'L’homme agile n’échappera point; le fort ne se sauvera point du côté de l’aquilon; les nations que baigne l’Euphrate ont été impuissantes, et elles sont tombées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 7, 'Quel est celui qui déborde comme un fleuve, et comment les fleuves roulent-ils une onde agitée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 8, 'Les eaux de l’Égypte monteront comme un fleuve; elle a dit: Je monterai et je couvrirai la terre, et je ferai périr ses habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 9, 'Montez à cheval, guerriers de l’Éthiopie; Libyens couverts d’armures, préparez vos chars, sortez, et vous, Lydiens, partez et tendez vos arcs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 10, 'Ce jour est pour le Seigneur notre Dieu un jour de vengeance; il va punir ses ennemis. Et le glaive du Seigneur dévorera, et il se rassasiera, et il s’enivrera de leur sang; car il y a un sacrifice au Seigneur, un sacrifice de la terre de l’aquilon, sur le fleuve Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 11, 'Va, Galaad, prends du baume pour la vierge, fille de l’Égypte; ô Égypte, tu as vainement multiplié tes remèdes; il n’est rien en toi qui puisse te guérir!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 12, 'Les nations ont entendu ta voix; et la terre a été remplie de ta clameur, parce que combattants contre combattants ont été blessés, et au même instant ils sont tombés tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 13, 'Prophéties que le Seigneur a dites par la voix de Jérémie, concernant la venue du roi de Babylone, pour frapper la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 14, 'Proclamez-le à Magdolon, annoncez-le à Memphis, dites: Lève-toi et te prépare; car le glaive a dévoré tes ifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 15, 'Pourquoi donc ton Apis s’est-il enfui, ce bœuf que tu avais choisi? Il n’est point demeuré en place, parce que le Seigneur l’a délié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 16, 'Et la multitude a perdu sa force, et elle est tombée; et ils se sont dit entre eux: Levons-nous et retournons à notre peuple; fuyons loin du glaive hellénique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 17, 'Donnez au Pharaon Néchao, roi d’Égypte, le nom de Saon Esbéié Moed.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 18, 'Par ma vie, dit le Seigneur Dieu, il viendra, aussi vrai que le Thabor est une montagne, et que le Carmel est auprès de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 19, 'Prépare pour toi l’appareil de l’esclavage, fille de l’Égypte; car Memphis sera désolée, et je l’appellerai Malheur, parce qu’il n’y restera plus d’habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 20, 'L’Égypte est une belle génisse; l’esclavage lui vient de l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 21, 'Pourquoi ses mercenaires, nourris chez elle comme les bœufs à l’engrais, ont-ils tourné le dos et se sont-ils enfuis tous ensemble? Ils n’ont point résisté, parce que le jour de la destruction est venu pour eux, et le temps de la vengeance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 22, 'Leur voix ressemble au sifflement du dragon; ils s’avancent sur le sable, et ils viendront en portant des haches,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 23, 'Comme des bûcherons; ils abattront sa forêt, dit le Seigneur; car on ne peut les compter, ils sont plus nombreux qu’une nuée de sauterelles, et leur multitude est innombrable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 24, 'La fille de l’Égypte a été confondue; elle a été livrée aux mains d’un peuple de l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 25, 'Et moi, voilà que je vais punir Ammon, son fils, en frappant le Pharaon, et tous ceux qui mettent en lui leur confiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 26, 'Pour toi, ne crains rien, Jacob, mon serviteur; ne tremble pas, Israël; car me voici, moi qui le sauve de loin et qui ramènerai ta race de sa captivité. Et Jacob reviendra, et il sera en repos, et il dormira, et nul ne le troublera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 27, 'N’aie point peur, Jacob mon serviteur, dit le Seigneur, car je suis avec toi; celle qui ne craignait rien et qui vivait dans la mollesse a été livrée, parce que je perdrai toute nation chez qui je t’ai banni. Mais toi, je ne te ferai point périr; seulement je te châtierai selon la justice, et coupable, je ne te laisserai pas impuni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 1, 'Parole du Seigneur qu’il a prononcée sur Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 2, 'Proclamez parmi les nations, faites entendre ces choses et ne les cachez pas. Dites que Babylone a succombé, que Bel a été confondu, et que Mérodach, qui vivait sans crainte et dans la mollesse, a été livré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 3, 'Car un peuple de l’aquilon est en marche contre elle; il effacera cette contrée, depuis l’homme jusqu’à la bête, et nul ne l’habitera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 4, 'En ces jours et en ce temps-là, les fils d’Israël reviendront eux-mêmes, et avec eux, au même instant, les');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 5, 'Ils interrogeront la voie pour aller à Sion; car c’est de ce côté qu’ils tourneront le visage; ils Y arriveront et ils se réfugieront auprès du Seigneur Dieu; car l’alliance éternelle ne sera point mise en oubli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 6, 'Mon peuple est devenu un troupeau de brebis errantes; leurs pasteurs les ont dispersées; ils les ont égarées dans les montagnes; elles ont passé de colline en colline; elles ont oublié leur bergerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 7, 'Tous ceux qui les ont trouvées les ont détruites; leurs ennemis disaient: Ne les laissons pas aller, en punition de ce qu’elles ont péché contre le Seigneur. Celui qui a rassemblé leurs pères a des pâturages de justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 8, 'Maintenant sortez du milieu de Babylone; revenez de la terre des Chaldéens; soyez comme des dragons en face des agneaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 9, 'Car voilà que je vais susciter contre Babylone les rassemblements des peuples de l’aquilon, et ils marcheront contre elle, et ils la prendront; tel le javelot d’un guerrier habile n’est jamais sans effet en revenant du combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 10, 'Et la Chaldée sera livrée au pillage, et tous ceux qui en prendront une part seront rassasiés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 11, 'Parce que vous vous êtes réjouis et glorifiés en pillant mon héritage, vous avez bondi comme des génisses dans la prairie, et vous avez frappé de vos cornes comme des taureaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 12, 'Votre mère a été profondément confondue; cette mère, qui vous avait enfantés au milieu des biens, a été couverte de honte; elle est la dernière des nations et désolée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 13, 'Et à cause de la colère du Seigneur elle ne sera plus habitée. Elle ne sera plus partout qu’une solitude, et quiconque traversera Babylone sera troublé, et on la sifflera en voyant ses plaies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 14, 'Investissez Babylone, vous tous qui savez tendre un arc; lancez-lui des flèches, et ne les lui épargnez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 15, 'Et prévalez sur elle; ses mains sont énervées, ses créneaux détruits, ses remparts minés. La vengeance vient de Dieu, vengez-vous d’elle; traitez-la comme elle a traité les vaincus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 16, 'Exterminez la semence de Babylone et celui qui tient la faucille au temps de la moisson; en face du glaive hellénique, chacun reviendra à son peuple, et chacun se réfugiera en sa terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 17, 'Israël était ma brebis égarée; les lions l’avaient chassée. Le roi Assur le premier l’avait dévorée, et le roi de Babylone ensuite en avait rongé les os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 18, 'À cause de cela, ainsi dit le Seigneur: Voilà que je tire vengeance du roi de Babylone, et je punis sa terre comme j’ai puni le roi Assur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 19, 'Et je rétablirai Israël dans son pâturage, et il reviendra paître sur le Carmel et dans les montagnes d’Éphraïm, et en Galaad, et son âme sera rassasiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 20, 'En ces jours et en ces temps-là, on cherchera l’iniquité d’Israël, et il n’y en aura plus; on cherchera les péchés de Juda, et l’on n’en trouvera plus; parce que je serai propice à tous ceux qui me seront restés');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 21, 'Sur la terre, dit le Seigneur. Attaque sans merci les murs de Babylone et ceux qui l’habitent; punis-les avec le glaive; détruis-les, dit le Seigneur, et fais ce que je te commande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 22, 'Il y a une voix de guerre et une grande affliction en la terre des Chaldéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 23, 'Comment a été rompu et broyé le marteau qui frappait toute la terre? Comment Babylone a-t-elle été désolée parmi les nations?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 24, 'Ils te donneront l’assaut, Babylone, et tu ne sauras comment tu as été surprise. Tu as été trouvée et prise, parce que tu as résisté au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 25, 'Le Seigneur a ouvert son trésor, et il en a tiré les instruments de sa colère; et le Seigneur Dieu a frappé la terre des Chaldéens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 26, 'Parce que leurs temps sont venus. Ouvrez ses réceptacles; fouillez-la comme une caverne; exterminez-la et qu’il ne reste rien d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 27, 'Desséchez tous ses fruits, et que l’on emmène ses hommes pour les égorger. Malheur à eux; car leur jour est venu; il est venu le temps de leur rétribution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 28, 'La voix des fugitifs et de ceux qui se sont sauvés de Babylone annoncera à Sion que leur châtiment vient du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 29, 'Appelez contre Babylone une multitude de guerriers, tous ceux qui tendent un arc; dressez votre camp autour de son enceinte; que nul des siens n’échappe; rétribuez-la selon ses œuvres: ce qu’elle a fait, faites-le-lui; car elle s’est élevée contre le Seigneur, contre le Dieu saint d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 30, 'À cause de cela, ses jeunes hommes tomberont dans ses places, et tous ses hommes de guerre succomberont, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 31, 'Voilà que je suis contre toi, superbe, dit le Seigneur; ton jour est venu; voilà le temps de ta rétribution,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 32, 'Et ton orgueil fléchira et il sera abattu, et nul ne le relèvera; et je mettrai le feu à ta forêt, et il dévorera tout ce qui l’entoure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 33, 'Voici ce que dit le Seigneur: Tous les fils d’Israël et tous les fils de Juda ont été opprimés; tous ceux qui les ont faits captifs les ont tenus sous l’oppression; et ils n’ont point voulu les renvoyer libres;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 34, 'Mais leur rédempteur est le Dieu fort; le Seigneur tout-puissant est son nom; il entrera en jugement avec ses ennemis pour délivrer la terre; et il aiguisera un glaive contre les habitants de Babylone;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 35, 'Un glaive contre eux et les Chaldéens, contre tous leurs grands et tous leurs sages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 36, 'Un glaive contre tous leurs guerriers, et ils seront énervés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 37, 'Un glaive contre leurs chevaux et leurs chars, contre leurs cavaliers et le peuple mêlé parmi eux, et ils seront comme des femmes; un glaive contre leurs trésors, et ils seront dispersés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 38, 'Un glaive sur les eaux de Babylone; et les Chaldéens seront confondus, parce que leur terre est une terre d’idoles, ainsi que les îles dont ils faisaient leur orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 39, 'À cause de cela, des idoles monstrueuses habiteront dans leurs îles, et les filles des sirènes dans Babylone, et elle ne sera pas repeuplée dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 40, 'De même que Dieu a renversé Sodome et Gomorrhe et les villes voisines, dit le Seigneur, ainsi nul homme n’habitera en Babylone, et nul fils de l’homme n’y demeurera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 41, 'Voilà qu’un peuple vient de l’aquilon; et une grande nation, et nombre de rois seront suscités des extrémités de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 42, 'Tenant l’arc et le glaive: ce peuple est hardi et il sera sans pitié. Leur voix retentira comme la mer; ils seront montés sur des chevaux exercés; à la guerre ils seront comme la flamme; et c’est toi qu’ils attaqueront, fille de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 43, 'Le roi de Babylone a entendu leur rumeur, et ses mains en ont été énervées, et l’angoisse l’a saisi comme les douleurs de l’enfantement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 44, 'Voilà que ce peuple va bondir comme un lion bondit du Jourdain à Étham; je détournerai promptement les miens de cette terre; je conduirai contre elle tout jeune homme: car qui est semblable à moi? Qui me résistera? Et quel est le pasteur qui se placera devant moi, face à face?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 45, 'À cause de cela, écoutez le conseil que le Seigneur a décrété contre Babylone, et les pensées qu’il a eues contre les Chaldéens qui l’habitent Je jure que les agneaux de leurs brebis périront, et que leur pâturage sera désolé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 46, 'Car au bruit de la prise de Babylone, la terre tremblera, et une clameur sera entendue parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 1, 'Voici ce que dit le Seigneur: Je susciterai contre Babylone et les habitants de la Chaldée un vent brûlant et empoisonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 2, 'Et j’enverrai contre Babylone des hommes insolents, et ils l’accableront d’insolence, et ils désoleront sa terre. Malheur à Babylone et à ses alentours le jour de son affliction!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 3, 'Que l’archer tende son arc, que celui qui a une armure s’en revête; n’épargnez pas les jeunes gens de Babylone et renversez toute sa puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 4, 'Les morts tomberont sur la terre des Chaldéens, et les hommes percés de coups hors de la ville;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 5, 'Parce que la race d’Israël et de Juda n’est point veuve de son Dieu, le Seigneur tout-puissant, et que la terre des Chaldéens a été remplie d’iniquités contre les saints d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 6, 'Fuyez du milieu de Babylone; que chacun sauve son âme; ne vous laissez pas comprendre dans son iniquité; car le temps de la vengeance du Seigneur est venu, et il la punira sévèrement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 7, 'Babylone dans la main du Seigneur était une coupe d’or qui enivrait toute la terre; les nations ont bu de son vin, c’est pourquoi elles ont été ébranlées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 8, 'Et Babylone est tombée soudain, et elle a été brisée; pleurez-la, prenez du baume pour sa plaie gangrenée, pour voir si elle pourra guérir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 9, 'Nous avons pansé Babylone, et elle n’est point guérie; abandonnons-la, partons chacun pour notre terre; car son jugement est monté jusqu’au ciel, il s’est élevé jusqu’aux étoiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 10, 'Le Seigneur a prononcé son jugement; venez et publions en Sion les œuvres du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 11, 'Préparez les flèches; remplissez les carquois. Le Seigneur a suscité l’esprit du roi des Mèdes; car sa colère est contre Babylone, et il l’exterminera; car c’est la vengeance du Seigneur, c’est la vengeance de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 12, 'Levez un étendard sur les remparts de Babylone; prenez des carquois; réveillez les gardes; apprêtez les armures; car le Seigneur a mis la main à l’œuvre, et il va faire ce qu’il a dit contre les habitants de Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 13, 'Qui demeurent sur les grandes eaux et sur la multitude de leurs trésors. Ta fin est venue; en vérité, elle est dans tes entrailles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 14, 'Car le Seigneur a juré par son bras: Je te remplirai d’hommes comme d’une nuée de sauterelles; et ils crieront en descendant sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 15, 'Le Seigneur a créé la terre par sa puissance; il a affermi le monde par sa sagesse; il a étendu le ciel par sa prudence;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 16, 'Il a mis dans le ciel, pour tenir lieu de sa voix, le bruit des eaux; il a fait venir les nuées des extrémités de la terre; il a mêlé les éclairs à la pluie et a fait jaillir la lumière de ses trésors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 17, 'L’homme a tiré vanité de ses connaissances; l’orfévre a été confondu par ses propres idoles; car il a fait des choses mensongères et sans vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 18, 'Ces œuvres sont vaines et ridicules, et au jour de la vérité elles périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 19, 'Tel n’est point le partage de Jacob, parce que le Créateur de toutes choses est son héritage; le Seigneur est');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 20, 'Tu es pour moi un instrument de guerre, et par toi je disperserai les nations et je détruirai les rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 21, 'Par toi je disperserai les chevaux et les cavaliers; et par toi je disperserai les chars et ceux qui les montent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 22, 'Par toi je disperserai les jeunes gens et les vierges; et par toi je disperserai les hommes et les femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 23, 'Par toi je disperserai les pasteurs et les brebis; et par toi je disperserai le laboureur et le labour, et les chefs et les capitaines;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 24, 'Et je rétribuerai Babylone et tous les Chaldéens qui l’habitent selon toutes les méchancetés qu’ils ont faites sous vos yeux contre Sion, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 25, 'Voilà que je suis contre toi, montagne corrompue, qui as corrompu toute la terre; et j’étendrai sur toi les mains et je te ferai rouler sur les rochers, et je ferai de toi une montagne brûlée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 26, 'Et on n’extraira de toi ni pierre angulaire ni pierre fondamentale; car tu seras détruite pour tous les siècles, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 27, 'Levez un étendard sur la terre; sonnez de la trompette parmi les nations; consacrez contre elle tous les gentils; assemblez-les contre elle, et soulevez en mon nom les rois et ceux d’Ascenez; dressez contre elle des balistes; lancez contre elle une cavalerie aussi nombreuse qu’une nuée de sauterelles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 28, 'Lancez contre elle les nations, le roi des Mèdes et de toute la terre, ses chefs et tous ses capitaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 29, 'La terre a tremblé et a été en travail, parce que la pensée du Seigneur s’est élevée contre Babylone, pour désoler sa terre au point qu’elle ne soit plus habitée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 30, 'Le guerrier de Babylone a défailli dans le combat; ils s’entasseront dans leur enceinte; leur pouvoir est brisé, les voilà comme des femmes; leurs maisons sont incendiées, et les verrous en sont rompus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 31, 'Le courrier se croisera avec le courrier, le messager avec le messager, quand ils iront annoncer au roi de Babylone que sa ville est prise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 32, 'Ils ont été pris par l’extrémité de leurs passages; leurs barricades ont été brûlées par le feu, et leurs hommes de guerre s’en sont allés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 33, 'Car voici ce que dit le Seigneur: Les palais des rois de Babylone seront battus comme l’aire en été; encore un peu de temps, et sa moisson viendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 34, 'Nabuchodonosor, roi de Babylone, m’a dévorée; il m’a mise en pièces; il m’a surprise comme une obscurité soudaine; il m’a engloutie; tel qu’un serpent, il a rempli ses entrailles de mes délices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 35, 'Mon trouble et ma détresse m’ont exilée à Babylone, dira la femme de Sion; que mon sang retombe sur les Chaldéens, dira Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 36, 'À cause de cela, ainsi dit le Seigneur: Voilà que je vais juger ton ennemi; je vais te venger, et j’épuiserai sa mer, et je dessècherai ses fontaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 37, 'Et Babylone ne sera plus qu’une solitude, et nul n’y demeurera plus;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 38, 'Car ils se sont levés tous ensemble comme des lions, comme des lionceaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 39, 'Dans leur chaleur, je leur donnerai à boire et je les enivrerai, afin qu’ils tombent dans un sommeil pesant, qu’il s’endorment pour toujours et ne se réveillent plus, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 40, 'Mène-les comme des agneaux qu’on va égorger, ou comme des béliers avec des chevreaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 41, 'Comment celle qui faisait l’orgueil de toute la terre a-t-elle été prise et pillée? Comment Babylone a-t-elle été effacée parmi les nations?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 42, 'La mer a débordé sur Babylone, avec un grand bruit de vagues, et elle l’a recouverte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 43, 'Ses villes sont devenues comme une terre sans eau et sans chemin; nul n’y habitera plus, et les fils des hommes ne s’y arrêteront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 44, 'Et je tirerai vengeance de Babylone, et je ferai sortir de sa bouche ce qu’elle a dévoré, et les nations ne s’y rassembleront plus,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 45, '(Vulg., 49.) Et dans Babylone tomberont les morts de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 46, '(50.) Et vous, hommes de mon héritage qui êtes sauvés, partez, ne vous arrêtez pas; vous qui revenez de loin, souvenez-vous de Dieu, et que Jérusalem s’élève en votre cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 47, '(51.) Nous avons été confondus quand nous avons appris notre opprobre; notre front s’est couvert de honte, des étrangers sont entrés dans nos saints lieux, dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 48, '(52.) Mais à cause de cela même voilà que les jours arrivent, dit le Seigneur, où je me vengerai de leurs idoles, et sur toute leur terre tomberont leurs morts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 49, '(53.) Si Babylone est montée jusqu’au ciel, si elle a mis sa force en ses remparts, ceux qui la détruiront viendront de ma part, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 50, '(54.) On entend des voix et des clameurs en Babylone, et il y a une grande affliction en la terre des Chaldéens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 51, '(55.) Parce que le Seigneur a exterminé Babylone, et il y a fait taire cette grande rumeur qui retentissait comme les grandes eaux, et il a livré sa voix à la destruction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 52, '(56.) Le malheur est venu sur Babylone, ses combattants ont été pris et leur arc a tremblé, parce que le Seigneur a voulu les punir à leur tour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 53, '(57.) Le Seigneur sait punir; et il enivrera ses');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 54, '(58.) Voici ce que dit le Seigneur: Les murs de Babylone ont été ouverts; ils seront sapés et abattus, ses portes superbes brûlées par le feu, et les peuples ennemis ne travailleront pas en vain, et les nations qui dominaient en elle défailliront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 55, '(59.) Parole que le Seigneur a commandée à Jérémie le prophète de dire à Saraïas, fils de Nérias, fils de Maasie, lorsqu’il alla en Babylone, envoyé par Sédécias, roi de Juda, en la quatrième année de son règne, et Saraïas était le chef de l’ambassade.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 56, '(60.) Et Jérémie écrivit en un livre tous les malheurs qui devaient arriver à Babylone, toutes les paroles qui furent écrites contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 57, '(61.) Et Jérémie dit à Saraïas: Lorsque tu seras à Babylone, et que tu verras et que tu liras toutes ces paroles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 58, '(62.) Tu diras: Seigneur, Seigneur, vous avez parlé contre ce lieu pour l’exterminer, pour que nul ne l’habite, depuis l’homme jusqu’à la bête, et il sera effacé pour jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 59, '(63.) Et quand tu auras fini de lire ce livre, tu l’attacheras à une pierre et tu le jetteras au milieu de l’Euphrate.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 60, '(64.) Et tu diras: Ainsi s’abîmera Babylone, et elle ne se relèvera plus à cause des maux que j’amènerai sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 61, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 62, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 63, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 64, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 1, 'Sur les Philistins, voici ce que dit le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 2, 'Voilà que les eaux viendront du nord, et elles seront comme un torrent débordé, et elles inonderont la terre et tout ce qui la remplit, la ville et ses habitants. Et les hommes crieront, et tous les habitants de la terre gémiront,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 3, 'En entendant les tumultes de l’invasion, le bruit des sabots de la cavalerie, le tremblement des chars et le fracas des roues. Les pères ne se sont point retournés pour regarder leurs fils, car leurs mains étaient défaillantes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 4, 'En ce jour qui est venu pour la ruine des Philistins. Et j’effacerai Tyr et Sidon, avec le reste de leurs auxiliaires, parce que le Seigneur exterminera tous ceux des îles qui auront survécu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 5, 'Gaza est devenue chauve, Ascalon est tombée, et ce qu’il y avait encore d’Énacim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 6, 'Jusques à quand frapperas-tu, glaive du Seigneur? Combien de temps s’écoulera avant que tu sois au repos? rentre dans ton fourreau; arrête-toi et reste suspendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 7, 'Comment se reposerait-il? Le Seigneur lui a ordonné de s’élever contre Ascalon, contre la région maritime et contre les autres cités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 8, '(Vulg., 7.) À l’Idumée voici ce que dit le Seigneur: Il n’y a plus de sagesse à Théman; le conseil a péri chez ses sages; leur sagesse s’en est allée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 9, '(8.) Leur pays a été foulé; creusez des retraites pour vous abriter, hommes de Dédam; car le Seigneur a fait venir contre vous la destruction. J’ai amené ce peuple, dit-il, au temps où je l’ai visité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 10, '(9.) Car des vendangeurs sont venus, qui ne te laisseront pas une grappe; ils étendront la main sur toi comme des voleurs de nuit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 11, '(10.) Car j’ai pillé Ésau; j’ai découvert ses retraites cachées; ils n’ont pu se cacher eux-mêmes. Ils ont péri par la main de leur frère et de leur voisin; et il n’est pas possible');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 12, '(11.) Qu’il survive chez toi un seul orphelin; quant à moi je vivrai, et les veuves ont mis en moi leur confiance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 13, '(12.) Car voici ce que dit le Seigneur: Ceux qui n’avaient point coutume de boire ce calice y boiront; et, coupable, tu ne seras pas impuni.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 14, '(13.) J’ai juré par moi-même, dit le Seigneur, que tu serais, au milieu de la terre, inhabitée, outragée et maudite; et toutes tes villes seront désertes dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 15, '(14.) J’ai entendu une voix venant du Seigneur, et il a envoyé des messagers aux nations, disant: Rassemblez-vous, marchez contre Édom; levez-vous pour le combattre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 16, '(15.) Je t’ai rendu petit parmi les nations, méprisable parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 17, '(16.) Tes plaisirs t’ont séduit, et l’audace de ton cœur; Edom s’est logé dans le creux des rochers; il s’est emparé de la force des hautes collines; il a placé haut son nid comme l’aigle; c’est de là que je te précipiterai;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 18, '(17.) Et l’Idumée sera un désert, et le passant sifflera sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 19, '(18.) Voilà comme ont été bouleversées Sodome et Gomorrhe et les villes voisines, dit le Seigneur toutpuissant; nul homme ne s’y reposera; nul fils de l’homme n’y demeurera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 20, '(19.) Voilà que contre elle l’ennemi va bondir comme un lion bondit du Jourdain à Étham; car je le conduirai promptement contre elle; dirigez vos jeunes guerriers contre l’Idumée: car qui est semblable à moi? Qui me résistera? Quel pasteur se placera devant moi face à face?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 21, '(20.) À cause de cela, écoutez le conseil que le Seigneur a tenu contre l’Idumée et contre ceux de Théman: Je jure que leurs moindres brebis périront, et que leur demeure sera pour eux inhabitable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 22, '(21.) La terre a été effrayée du bruit de leur chute, et l’on n’y a plus entendu la voix de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 23, '(22.) Voilà que l’ennemi va regarder comme l’aigle; puis il étendra ses ailes sur les forteresses d’Édom, et le cœur des forts de l’Idumée sera en ce jour comme le cœur d’une femme qui enfante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 29, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 1, 'Voici ce que dit le Seigneur aux fils d’Ammon: N’y a-t-il point de fils en Israël? N’y a-t-il point chez eux d’héritiers? Pourquoi donc Melchol s’est-il emparé de Galaad, et a-t-il établi son peuple dans ses villes?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 2, 'À cause de cela, voilà que les jours arrivent, dit le');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 3, 'Pousse des gémissements, Ésebon; car Haï est détruite; criez, filles de Rabbath, ceignez des cilices et frappez-vous la poitrine, parce que Melchol sera banni, et avec lui ses prêtres et ses princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 4, 'Pourquoi vous réjouissez-vous dans les plaines d’Énacim; et toi aussi, fille de l’orgueil, qui te confies en tes trésors, disant: Qui donc marchera contre moi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 5, 'C’est moi qui t’apporterai l’épouvante, dit le Seigneur, de tous les pays qui t’environnent; et devant eux vous vous disperserez tous, et nul ne vous rassemblera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 6, '(Vulg., 28.) À Cédar, reine du palais, qui a frappé Nabuchodonosor, roi de Babylone, voici ce que dit le Seigneur: Levez-vous et marchez sur Céðar, et rassasiez les fils de Cedem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 7, '(29.) Ils prendront leurs tentes et leurs brebis; ils prendront leurs vêtements, leurs meubles et leurs chameaux; appelez contre eux la destruction de toutes parts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 8, '(30.) Fuyez, creusez des retraites profondes pour vous cacher, vous qui êtes assis dans le palais, parce que le roi de Babylone a tenu conseil et pris des résolutions contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 9, '(31.) Lève-toi et marche sur une nation tranquillement assise dans le repos, sans portes, sans verrous, sans barrières, seule à l’écart.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 10, '(32.) Et ses chameaux seront ton butin, et la multitude de son bétail sera détruite; et je les vannerai à tous les vents, ces hommes qui se coupent la chevelure au-dessus du front; je leur apporterai le bouleversement de toutes leurs frontières, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 11, '(33.) Et leur palais sera le séjour des autruches et il sera à jamais désert; nul homme ne s’y reposera; nul fils des hommes n’y demeurera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 12, '(23.) À Damas, Émath et Arphath sont dans la confusion, parce qu’elles ont entendu une nouvelle funeste; elles sont stupéfaites, elles sont furieuses et ne peuvent plus se tenir en repos.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 13, '(24.) Damas a perdu courage; elle s’est enfuie; elle a été prise de terreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 14, '(25.) Pourquoi n’a-t-elle pas épargné ma ville, le lieu que j’aime?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 15, '(26.) À cause de cela, tes jeunes gens tomberont au milieu de tes places, et tous tes hommes de guerre périront, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 16, '(27.) Et je mettrai le feu aux remparts de Damas, et il dévorera les carrefours du fils d’Ader.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 30, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 1, 'À Moab voici ce que dit le Seigneur: Malheur à Nabau, parce qu’elle a été détruite; Cariathim est abandonnée; Amath et Agath sont confondues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 2, 'Il n’y a plus de guérison en Moab, ni de jactance en Ésebon; car le Seigneur a formé le dessein de détruire ce peuple, disant: Nous l’avons retranché du nombre des nations; il sera réduit à néant; derrière toi marchera le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 3, 'On entend des voix et des cris à Oronaïm; il y a ruine et ravage immense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 4, 'Moab est anéantie, proclamez-le en Zogor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 5, 'Aloth a été remplie de deuil; elle est montée, pleurante sur la voie d’Oronaïm; vous avez entendu ses cris de détresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 6, 'Fuyez et sauvez votre vie, et vous, courez comme l’onagre dans le désert,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 7, 'Parce que tu as mis ta confiance en tes forteresses, tu seras prise, et Chamos partira pour l’exil, et avec lui ses prêtres et ses princes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 8, 'Et la destruction viendra sur chaque cité; nulle ne sera épargnée; et le vallon périra, et la plaine sera dépeuplée, comme l’a dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 9, 'Donnez des signes à Moab, parce qu’on va mettre la main sur sa plaie, et que toutes ses villes seront désertes. Où trouver un habitant pour elles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 10, 'Maudit soit celui qui fait négligemment les œuvres du Seigneur, et qui retient son glaive loin du sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 11, 'Moab s’est reposé dès son enfance, et, confiant dans sa bonne renommée, on ne l’a point transvasé de vaisseau en vaisseau; on ne l’a jamais transporté: à cause de cela il a gardé son goût, et son parfum ne s’est pas évaporé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 12, 'À cause de cela, voilà que les jours arrivent, dit le Seigneur, où je lui enverrai des gens qui l’abaisseront, et ils épuiseront ses vaisseaux, et ils briseront ses cornes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 13, 'Et Moab sera confondu à cause de Chamos, comme la maison d’Israël a été confondue à cause de Béthel, son espérance, sur laquelle elle s’appuyait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 14, 'Comment direz-vous: Nous sommes forts et nos hommes sont vaillants à la guerre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 15, 'La ville de Moab a péri; ses guerriers d’élite ont été égorgés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 16, 'Le jour de Moab est proche, et son iniquité amène rapidement la vengeance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 17, 'Secouez la tête sur elle, vous tous qui l’entourez; prononcez son nom, dites: Comment son sceptre glorieux, sa verge de magnificence ont-ils été brisés?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 18, 'Descends de ta gloire; assieds-toi sur la terre humide. Dibon sera broyée, car Moab n’est plus; l’ennemi t’a enlevé d’assaut en détruisant tes remparts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 19, 'Femme d’Aroër, tiens-toi sur le chemin; assiedstoi et regarde; interroge celui qui fuit, celui qui s’est échappé, et dis-lui: Qu’est-il arrivé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 20, 'Moab est confondu et brisé. Gémis et crie, et fais savoir à Arnon que Moab n’est plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 21, 'Et le jugement arrive contre la terre de Misor, contre Hélon, contre Réphas et Mophas;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 22, 'Et contre Dibon, et contre Nabau, et contre la maison de Daïth lathaïm;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 23, 'Et contre Cariathaïm, et contre la maison de Gémol, et contre la maison de Maon;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 24, 'Et contre Carioth, et contre Bosor, et contre toutes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 25, 'La corne de Moab est brisée et son glaive rompu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 26, 'Enivrez Moab, parce qu’il s’est glorifié contre le Seigneur; et Moab battra des mains, et c’est de luimême que l’on rira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 27, 'En vérité, Israël a été pour toi un sujet de raillerie, et il s’est trouvé parmi ceux que tu as volés quand tu lui as fait la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 28, 'À leur tour, ils ont abandonné les villes; ils sont allés dans les rochers ceux qui habitaient Moab; ils sont devenus comme des colombes qui font leur nid dans les rochers, à l’entrée des crevasses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 29, 'Et j’ai appris l’humiliation de Moab: il a été grandement humilié pour son orgueil et son insolence; son cœur s’est glorifié à l’excès;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 30, 'Mais moi, je connaissais ses œuvres; et ses efforts n’ont-ils pas été au delà de son pouvoir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 31, 'À cause de cela, gémissez partout sur Moab; criez contre les hommes qui se coupent les cheveux en signe de deuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 32, 'Vigne d’Asérima, je te pleurerai comme j’ai pleuré Jazer; tes sarments ont traversé la mer; ils ont atteint la ville de Jazer; et la ruine est tombée sur tes fruits et sur tes vendangeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 33, 'La joie et les fêtes ont été détruites ensemble sur la terre de Moab, et quoiqu’il y eût du raisin dans les pressoirs, le matin on ne l’a point foulé, et le soir on n’a point chanté un chant joyeux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 34, 'À cause du cri d’Ésebon qui a été entendu jusqu’à Étham, les villes de Moab ont élevé leur voix de Zogor à Oronaïm; elles se sont plaintes, comme une génisse de trois ans, parce que l’eau de Nebrin est tarie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 35, 'Et je détruirai Moab, dit le Seigneur, parce qu’il monte à l’autel et encense ses dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 36, 'C’est pourquoi le cœur de Moab gémira comme un chalumeau; et de même mon cœur gémira sur les hommes qui se coupent les cheveux en signe de deuil; car ce que chacun aura gagné sera perdu pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 37, 'En tous lieux ils se raseront la tête; toute barbe sera rasée; de leurs mains ils se frapperont la poitrine; tous les reins seront ceints de cilices,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 38, 'Sur toutes les terrasses et sur toutes les places de Moab; car je l’ai brisé, dit le Seigneur, comme un vase dont on ne se sert plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 39, 'Comment a-t-il ainsi changé? Comment Moab a-t-il tourné le dos? Moab a été confondu et est devenu un sujet de raillerie et de ressentiment pour tous ceux qui l’entourent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 40, 'Car voici ce qu’a dit le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 41, 'Carioth est prise; ses forteresses ont été enlevées toutes à la fois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 42, 'Moab cessera d’être un peuple, parce qu’il s’est glorifié contre le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 43, 'Homme de Moab, le filet, la fosse, l’épouvante, sont préparés contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 44, 'Celui qui fuit l’épouvante tombera dans la fosse; et en remontant hors de la fosse, il sera pris dans le filet; car je ferai arriver toutes ces choses en Moab l’année où je le visiterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 45, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 46, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 31, 47, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 1, '(Vulg., 15.) Voici ce que dit le Seigneur Dieu d’Israël: Prends de ma main cette coupe de vin pur, et fais-en boire à toutes les nations chez qui je t’enverrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 2, '(16.) Et elles boiront, et elles vomiront, et elles');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 4, '(18.) Jérusalem et les villages de Juda, les rois de Juda et ses princes, afin de faire de ces contrées un désert, une désolation, un sujet de raillerie;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 5, '(19.) Et le Pharaon, roi d’Égypte, et ses serviteurs, et ses grands et tout son peuple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 6, '(20.) Et ses alliés, et tous les rois des Philistins, et Ascalon, et Gaza, et Accaron, et le roi d’Azot;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 7, '(21.) Et l’Idumée, et Moab, et les fils d’Ammon; 8. (22.) Et les rois de Tyr, et les rois de Sidon, et les rois de la terre des îles au delà de la mer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 9, '(23.) Et Dédan, et Théman, et Rhos, et tous ceux qui se coupent les cheveux autour du front;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 10, '(24.) Et tous les peuples mêlés, qui ont leurs tentes dans le désert;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 11, '(25.) Et tous les rois d’Élam, et tous les rois de Perse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 12, '(26.) Et tous les rois de l’Orient, proches ou lointains, les uns après les autres, et tous les royaumes qui sont sur la surface de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 13, '(27.) Et tu leur diras: Ainsi parle le Seigneur tout-puissant: Buvez, enivrez-vous, et vous vomirez; vous tomberez, et vous ne vous relèverez pas sous le glaive que j’enverrai sur vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 14, '(28.) Et voici ce qui arrivera: lorsqu’ils refuseront de prendre de ta main la coupe pour y boire, tu leur diraş Ainsi dit le Seigneur: Buvez, buvez,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 15, '(29.) Car je commence à sévir contre la ville où mon nom est prononcé, et vous ne serez point purifiés; car j’appelle un glaive sur tous ceux qui habitent la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 16, '(30.) Et tu prophétiseras contre eux en ces termes, et tu diras: Le Seigneur du haut des cieux parlera; de son sanctuaire il fera entendre sa voix; il parlera contre ce lieu, et les hommes lui répondront comme des vendangeurs ivres; et la destruction arrivera sur tous ceux qui habitent la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 17, '(31.) Et même aux extrémités du monde; car le Seigneur entre en jugement contre toutes les nations; il plaide avec toute chair; et les impies ont été livrés au glaive, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 18, '(32.) Ainsi dit le Seigneur: Voilà que les maux passeront de nation à nation, et un immense tourbillon partira des extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 19, '(33.) Et il y aura des morts tués par le Seigneur, au jour du Seigneur, dans toutes les parties de la terre; on ne les enterrera point, et ils seront comme du fumier sur la surface de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 20, '(34.) Poussez des gémissements, pasteurs, criez; lamentez-vous, béliers du troupeau; car vos jours finiront par le meurtre, et vous tomberez comme des béliers de choix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 21, '(35.) Et il n’y aura pas de refuge pour les pasteurs; il n’y aura point de salut pour les béliers du troupeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 22, '(36.) On entend la voix et les cris des pasteurs, les gémissements des brebis et des béliers, parce que le Seigneur a détruit leurs pâturages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 23, '(37.) Et toute demeure autrefois paisible sera détruite en face de ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 24, '(38.) Dieu, comme un lion, a abandonné le lieu de sa retraite; et leur terre est devenue déserte en face de son grand glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 38, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 39, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 42, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 43, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 32, 44, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 1, 'Au commencement du règne de Joakim, fils de Josias, cette parole me vint du Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 2, 'Voici ce que dit le Seigneur: Tiens-toi dans le parvis du temple du Seigneur, et prophétise à tous les Juifs et à tous ceux qui viennent adorer dans le temple du Seigneur; dis-leur toutes les paroles que je t’ai commandé de leur prophétiser; et n’en omets pas un seul mot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 3, 'Peut-être ils t’écouteront et se détourneront chacun de leur mauvaise voie; et je ne leur ferai point le mal que je pense leur faire en punition de leurs habitudes perverses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 4, 'Et dis-leur: Ainsi parle le Seigneur: Si vous m’êtes indociles, au lieu de marcher selon les commandements que je vous ai donnés face à face,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 5, 'Pour écouter mes serviteurs les prophètes que je vous envoie dès l’aurore (car je vous les ai envoyés, mais vous ne m’avez point obéi),');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 6, 'Je traiterai ce temple comme j’ai traité Silo; et je maudirai cette ville parmi toutes les nations de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 7, 'Et les prêtres, et les faux prophètes, et tout le peuple entendirent Jérémie, comme il disait ces paroles dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 8, 'Et quand Jérémie eut cessé de dire au peuple tout ce que le Seigneur lui avait commandé de dire, les prêtres');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 9, 'Parce que tu as prophétisé au nom du Seigneur, disant Le temple sera comme Silo, et cette ville sera vide d’habitants. Et toute l’assemblée du peuple se réunit contre Jérémie, dans la maison du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 10, 'Et les princes de Juda apprirent ces choses; et, de la maison du roi, ils allèrent au temple, et ils siégèrent devant la porte neuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 11, 'Et les prêtres et les faux prophètes dirent aux princes et à tout le peuple: Condamnation à mort contre cet homme, parce qu’il a prophétisé sur cette ville, comme vous l’avez ouï de vos oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 12, 'Et Jérémie parla aux princes et à tout le peuple, disant Le Seigneur m’a envoyé prophétiser sur ce temple et sur cette ville, et dire les paroles que vous avez ouïes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 13, 'Et maintenant faites meilleures vos voies et vos œuvres; et obéissez à la voix du Seigneur, et le Seigneur ne vous fera point le mal qu’il a prononcé contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 14, 'Voilà que je suis dans vos mains; traitez-moi comme bon vous semble et comme il vaut mieux pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 15, 'Mais sachez que si vous me faites périr, vous ferez retomber le sang innocent sur vous, sur cette ville, et sur ceux qui l’habitent: car, en vérité, le Seigneur m’a envoyé à vous pour porter ces paroles à vos oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 16, 'Et les princes et tout le peuple dirent aux prêtres et aux faux prophètes: Il n’y a pas lieu de condamner cet homme à mort; car il nous a parlé au nom du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 17, 'Et des hommes, des anciens de la terre, se levèrent, et ils dirent à toute la synagogue du peuple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 18, 'Michée de Morasthi était du temps d’Ézéchias, roi de Juda, et il dit à tout le peuple de Juda: Voici ce que dit le Seigneur: Sion sera labourée comme un champ, et Jérusalem déserte, et la montagne du temple un bois de chênes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 19, 'Ézéchias et tout Juda l’ont-ils fait périr? N’est-ce pas parce qu’ils craignirent le Seigneur et le prièrent, qu’il ne leur fit pas le mal qu’il avait prononcé contre eux? Nous aussi, nous avons fait de grandes fautes contre nos âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 20, 'Mais il y eut aussi un homme prophétisant au nom du Seigneur, Urie, fils de Séméi de Cariathiarim; et il avait prophétisé sur cette terre les mêmes choses que Jérémie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 21, 'Et le roi Joakim et tous les princes, ayant ouï toutes ses paroles, cherchèrent à le faire mourir; mais Urie en fut informé, et il s’enfuit en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 22, 'Et le roi envoya des hommes en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 23, 'Et ils en ramenèrent Urie, et ils le conduisirent devant le roi, et le roi le frappa du glaive, et le jeta dans le sépulcre des fils de son peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 33, 24, 'Mais la main d’Achicam, fils de Saphan, était avec Jérémie pour qu’il ne fût pas livré aux mains du peuple, et qu’on ne le fît point mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 1, '(Vulg., 2.) Voici ce que dit le Seigneur: Fais-toi chaînes et un collier, et mets-les autour de ton cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 2, '(3.) Et tu les enverras au roi de l’Idumée, et au roi de Moab, et au roi des fils d’Ammon, et au roi de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 3, '(4.) Et tu prescriras à ces messagers de dire à leurs maîtres: Voici ce que dit le Seigneur Dieu d’Israël; voici ce que vous direz à vos maîtres:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 4, '(5.) J’ai créé la terre par ma toute-puissance et mon bras très-haut, et je la donnerai à celui qui sera le plus agréable à mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 5, '(6.) J’ai donné la terre à Nabuchodonosor, roi de Babylone, afin qu’elle le serve; je lui ai donné les bêtes des champs, afin qu’elles travaillent pour lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 6, '(8.) Et la nation et le royaume qui ne passeront point leur cou sous le joug du roi de Babylone, je les visiterai par le glaive et la famine, dit le Seigneur, jusqu’à ce qu’ils tombent défaillants sous ma main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 7, '(9.) Quant à vous, n’écoutez pas vos faux prophètes, ni vos devins, ni les interprètes de vos songes, ni vos augures, ni vos magiciens qui disent: Ne travaillez pas pour le roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 8, '(10.) Car ils vous prophétisent des mensonges, pour que vous soyez transportés loin de votre pays,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 9, '(11.) Et toute nation qui passera son cou sous le joug du roi de Babylone, et qui travaillera pour lui, je la laisserai sur sa terre, et elle Y travaillera et Y demeurera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 10, '(12.) Et je parlerai à Sédécias, roi de Juda, conformément à ces paroles, disant: Passez votre cou sous le joug, et travaillez pour le roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 11, '(14.) Car ceux-ci vous prophétisent l’iniquité:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 12, '(15.) Car je ne les ai pas envoyés, dit le Seigneur, et ils prophétisent à tort en mon nom pour vous perdre; et vous périrez, vous et vos prophètes qui vous prophétisent le mensonge et l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 13, '(16.) Je vous ai parlé à vous, et à tout le peuple, et aux prêtres, disant: Ainsi dit le Seigneur: N’écoutez pas les discours des prophètes qui vous prophétisent, disant: Voilà que les vases du temple du Seigneur reviendront de Babylone; parce qu’ils vous prophétisent à tort et faussement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 14, '(17.) Je ne les ai point envoyés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 15, '(18.) S’ils sont prophètes, et si la parole du Seigneur est en eux, qu’ils aient une entrevue avec moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 16, '(19.) Car voici ce que dit le Seigneur: Quant à ce qui reste des vases');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 17, 'Que n’a pas pris le roi de Babylone, lorsqu’il a transporté de Jérusalem le roi Jéchonias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 18, 'Ils iront à Babylone, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 34, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 1, 'Et la quatrième année de Sédécias, roi de Juda, le cinquième mois, Ananie, fils d’Azor le faux prophète de Gabaon dans le temple du Seigneur, me parla devant les prêtres et devant tout le peuple, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 2, 'Voici ce que dit le Seigneur: J’ai brisé le joug du roi de Babylone;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 3, 'Encore deux ans, et je ramènerai dans ce lieu les vases du temple du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 4, 'Et Jéchonias et les captifs de Juda; car je briserai le joug du roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 5, 'Et Jérémie répondit à Ananie, devant tout le peuple');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 6, 'Et Jérémie dit: Puisse réellement le Seigneur faire ainsi, confirmer ce que tu prophétises, ramener les vases du temple et tous les captifs de Babylone en ce lieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 7, 'Mais écoutez la parole du Seigneur que je vais dire à vos oreilles, et aux oreilles de tout le peuple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 8, 'Les prophètes qui ont été avant moi et avant vous, dans tous les siècles, ont prophétisé la guerre à maintes contrées et à maints grands royaumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 9, 'Quant au prophète qui a prophétisé la paix, lorsque sa parole sera accomplie, on reconnaîtra que c’est un prophète vraiment envoyé du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 10, 'Et Ananie, aux yeux de tout le peuple, retira du cou de Jérémie son collier et le brisa.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 11, 'Et Ananie parla devant tout le peuple, disant: Ainsi dit le Seigneur: Voilà comme je briserai le joug du roi de Babylone, en le retirant du cou d’un grand nombre de nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 12, 'Et Jérémie s’en alla dans sa voie; et la parole du Seigneur vint à Jérémie, après qu’Ananie eut brisé le collier de son cou, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 13, 'Va et parle à Ananie, disant: Ainsi parle le Seigneur Tu as brisé un collier de bois, je le remplacerai par un collier de fer;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 14, 'Car voici ce que dit le Seigneur: J’ai mis un joug de fer sur le cou de toutes les nations, afin qu’elles travaillent pour le roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 15, 'Et Jérémie dit à Ananie: Le Seigneur ne t’a pas envoyé, et tu as fait croire à ce peuple ce qui n’est point vrai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 16, 'À cause de cela, ainsi dit le Seigneur: Voilà que je t’expulserai de la face de la terre, et cette année tu mourras.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 17, 'Et il mourut le septième mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 35, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 1, 'Voici les paroles de l’écrit que Jérémie envoya de Jérusalem aux anciens de l’émigration, aux prêtres et aux faux prophètes; lettre adressée en Babylone aux captifs et à tout le peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 2, 'Après le départ du roi Jéchonias, et de la reine, et des eunuques, et de tout homme libre, et de tout esclave, et de tout artisan de Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 3, 'Par les mains d’Éléasar, fils de Sapha et de Gamarias, fils d’Helcias, que Sédécias, roi de Juda, envoya au roi de Babylone, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 4, 'Ainsi parle le Seigneur, Dieu d’Israël, sur les captifs que j’ai transportés de Jérusalem:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 5, 'Bâtissez des maisons, et habitez-les; plantez des arbres et mangez-en les fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 6, 'Prenez des femmes et engendrez des fils et des filles; prenez pour vos fils des femmes, et donnez vos filles à des hommes: multipliez et ne décroissez pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 7, 'Et cherchez la paix en la contrée où je vous ai transportés, et priez le Seigneur pour ses peuples; car en leur paix réside votre paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 8, 'Car voici ce que dit le Seigneur: Que les faux prophètes qui sont avec vous, que vos devins ne vous séduisent pas; et n’ayez point confiance aux songes que vous aurez songés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 9, 'C’est à tort qu’ils vous prophétisent en mon nom, et je ne les ai pas envoyés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 10, 'Car voici ce que dit le Seigneur Lorsque les soixante-dix ans seront près d’être révolus en Babylone, je vous visiterai et je confirmerai mes paroles sur vous, en ramenant votre peuple en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 11, 'Car j’ai sur vous des pensées de paix, et non de malheur, pour vous donner ces biens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 12, 'Priez-moi, et je vous exaucerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 13, 'Cherchez-moi, et vous me trouverez. Parce que, si vous me cherchez de tout votre cœur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 14, 'Je me manifesterai à vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 15, 'Parce que vous direz: Le Seigneur a institué pour nous des prophètes en Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 16, '(Vulg., 21.) Ainsi dit le Seigneur sur Achiab et sur Sédécias: Voilà que je les livrerai aux mains du roi de Babylone, et il les frappera devant vos yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 17, '(22.) Et parmi tous les captifs en Babylone, c’est d’eux que l’on se servira pour maudire, disant: Puisse le Seigneur te traiter comme il a traité Sédécias et Achiab, que le roi de Babylone a fait frire dans le feu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 18, '(23.) Parce qu’ils avaient fait l’iniquité en Israël; qu’ils avaient commis des adultères avec les femmes de leurs concitoyens, et dit en mon nom des paroles que je ne leur avais point commandé; et j’en porte témoignage, dit le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 19, '(24.) Et à Séméi l’Élamite tu diras:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 20, '(25.) Je ne t’ai point envoyé en mon nom. Et à Sophonias, fils de Maasie, le prêtre, dis encore:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 21, '(26.) Le Seigneur t’a établi prêtre à la place du prêtre Joad, pour que tu sois, dans le temple du Seigneur, le maître de tout faux prophète et de tout homme en délire; et ceux-là, fais-les mettre en prison et au cachot.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 22, '(27.) Et maintenant pourquoi tous ensemble injuriez-vous Jérémie, d’Anathoth, qui prophétisait pour vous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 23, '(28.) Ne vous a-t-il pas envoyé une lettre à ce sujet? Dans le cours de ce mois, il vous l’a envoyée à Babylone, disant: Ce sera long; bâtissez donc des maisons et habitez-les; plantez des jardins et mangez-en les fruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 24, '(29.) Or Sophonie lut la lettre aux oreilles de Jérémie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 25, '(30.) Et la parole du Seigneur vint à Jérémie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 26, '(31.) Envoie-les aux captifs, disant: Ainsi parle le Seigneur sur Jérémie l’Élamite: Puisque Séméi vous a prophétisé sans être envoyé par moi, et qu’il a gagné votre confiance injustement,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 27, '(32.) À cause de cela, dit le Seigneur, je visiterai Séméi et sa race, et il n’en restera pas un homme parmi vous, pour voir le bien que je vous ferai; non, ils ne le verront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 36, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 1, 'Parole du Seigneur à Jérémie, pour qu’il dise:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 2, 'Ainsi parle le Seigneur Dieu d’Israël, disant: Écris dans un livre toutes les paroles que je t’ai révélées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 3, 'Car voilà que les jours arrivent, dit le Seigneur, où je ramènerai les captifs de mon peuple d’Israël et de Juda; et je les ramènerai, dit le Seigneur, en la terre que j’ai donnée à leurs pères, et ils la possèderont.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 4, 'Et voici les paroles que le Seigneur a dites sur Israël et sur Juda:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 5, 'Voici ce que dit le Seigneur: Vous entendrez une voix épouvantable; c’est l’épouvante, et non la paix;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 6, 'Demandez et voyez est-ce que le mâle enfante? D’où vient donc la terreur qui les fait se tenir les reins et attendre leur délivrance? Pourquoi ai-je vu ainsi tout homme ayant les mains sur ses reins? Et tout visage a pâli.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 7, 'C’est que ce jour-là est grand; il n’en est point de semblable; c’est un temps de détresse pour Jacob; mais il en sera sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 8, 'En ce jour-là, dit le Seigneur, je briserai le joug de leur cou, je romprai leurs liens; et ils ne travailleront plus pour les étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 9, 'Mais ils travailleront pour le Seigneur leur Dieu, et je ressusciterai pour eux leur roi David.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 10, '(Vulg., 12.) Voici ce que dit le Seigneur: J’ai amené sur toi la destruction; ta plaie est douloureuse. 11. (13.) Il n’est personne qui juge ta cause; tu as été soignée en ta douleur, et rien ne te soulage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 12, '(14.) Tu as été oubliée de tous tes amis; nul ne s’est informé de toi; car je t’ai frappée en ennemi, d’une plaie cruelle, d’un châtiment sévère; tes péchés s’étaient multipliés au delà de toute iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 13, '(15, 16.) C’est pourquoi tous ceux qui te dévorent seront dévorés; et tous tes ennemis mangeront leur propre chair. Tes péchés avaient surpassé la multitude de tes iniquités; à cause de cela ils ont fait ces choses; mais ceux qui t’ont tourmentée seront tourmentés à leur tour, et ceux qui t’ont pillée, je te les donnerai en proie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 14, '(17.) Je t’apporterai le remède; je te guérirai de ta plaie douloureuse, dit le Seigneur; on t’appelait la répudiée; on disait: C’est notre proie; car nul ne s’informait de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 15, '(18.) Mais ainsi parle le Seigneur: Voilà que je ramènerai les exilés de Jacob; j’aurai compassion de ses captifs. La ville sera rebâtie sur sa montagne, et le peuple rétabli en la justice de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 16, '(19.) Et il sortira d’eux des chants et des voix d’hommes pleins d’allégresse, et je les multiplierai, et leur nombre ne diminuera pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 17, '(20.) Et leurs fils entreront, comme autrefois, dans le temple; et ils porteront devant moi leurs témoignages avec droiture; et je visiterai ceux qui les affligent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 18, '(21.) Et les forts de mon peuple prévaudront sur eux, et le prince de mon peuple sortira de lui, et je les rassemblerai, et ils reviendront à moi; car quel est celui qui a disposé leur cœur à revenir à moi? dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 19, '(22.) La colère du Seigneur ne se détournera pas avant qu’il ait accompli, avant qu’il ait réalisé les pensées de son cœur. Dans les derniers jours vous saurez ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 20, '(23.) Cependant la colère du Seigneur a éclaté avec transport, sa colère a éclaté comme un tourbillon; elle tombera sur les impies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 37, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 1, 'En ce temps-là, dit le Seigneur, je serai le Dieu de la maison d’Israël, et elle sera mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 2, 'Voici ce que dit le Seigneur: J’ai trouvé dans le désert mon peuple encore vivant parmi les cadavres d’hommes tués par le glaive; allez et ne perdez pas Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 3, 'Le Seigneur lui est apparu de loin. Je t’ai aimé d’un amour éternel; c’est pourquoi, dans ma miséricorde, je t’ai attiré à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 4, 'Je te réédifierai, et tu seras réédifiée vierge d’Israël; tu prendras encore ton tambour, et tu sortiras avec une troupe de chanteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 5, 'Puisque vous avez planté des vignes sur les montagnes de Samarie, plantez, et chantez des louanges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 6, 'Car c’est le jour où ceux qui plaident en la montagne d’Ephraïm appelleront leurs frères, disant: Levezvous, et allez à Sion auprès du Seigneur, votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 7, 'Voici ce que dit le Seigneur à Jacob: Réjouissezvous et tressaillez à la tête des nations; proclamez et chantez des louanges, disant: Le Seigneur a sauvé son peuple, le reste d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 8, 'Voilà que je les ramènerai de l’aquilon; je les rassemblerai des extrémités de la terre pour la fête de la Pâque. Et mon peuple engendrera une nombreuse multitude, et ils reviendront ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 9, 'Ils sont partis pleurant, et je les ramènerai consolés; ils logeront sur le bord des eaux, dans une voie droite, et ils ne s’y égareront pas; parce que je suis devenu pour Israël un père, et qu’Ephraïm est mon premier-né.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 10, 'Peuples, écoutez les paroles du Seigneur, publiezles dans les îles lointaines, et dites: Celui qui a vanné Israël, le rassemblera; et il le gardera, comme le pasteur son troupeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 11, 'Car le Seigneur est le rédempteur de Jacob; il l’a retiré des mains d’un plus fort que lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 12, 'Et ils viendront, et ils se réjouiront en la montagne de Sion, et ils viendront jouir des biens du Seigneur, en une terre pleine de blé et de vin, et de fruits, et de grand bétail, et de menus troupeaux; et leur âme sera comme un arbre fruitier, et ils n’auront plus faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 13, 'Alors les jeunes filles se réjouiront dans l’assemblée des jeunes gens, et les vieillards se réjouiront, et je changerai leur deuil en fête, et je les remplirai d’allégresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 14, 'Je glorifierai et j’enivrerai l’âme des prêtres fils de Lévi, et mon peuple se rassasiera de mes biens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 15, 'Voici ce que dit le Seigneur: Une voix a été entendue en Rama, avec des lamentations, des gémissements et des larmes; et Rachel pleurante n’a point voulu être consolée sur ses fils, car ils ne sont plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 16, 'Voici ce que dit le Seigneur: Que tes sanglots s’arrêtent, que tes yeux cessent de verser des larmes; car tes œuvres auront leur récompense, et tes fils reviendront de la terre des ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 17, 'Il y aura une demeure stable pour tes fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 18, 'J’ai entendu Éphraïm gémissant; il disait: Vous m’avez châtié, et je suis corrigé; j’étais comme un taureau indompté, ramenez-moi, et je reviendrai; car vous êtes le Seigneur, mon Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 19, 'Après ma captivité je me suis repenti, et après m’être reconnu j’ai pleuré sur mes jours de honte, et je me suis montré à vous; car dès ma jeunesse j’ai porté mon opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 20, 'Éphraïm est pour moi un fils bien-aimé, un enfant de prédilection, et, puisque mes paroles sont en lui, je ne l’oublierai pas; c’est pourquoi je l’ai secouru avec sollicitude, et je le traiterai avec miséricorde, dit le Seigneur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 21, 'Prononce sur toi-même, Sion, charge-toi de te punir; donne ton cœur aux droits chemins; reviens en la voie où tu marchais, vierge d’Israël, reviens pleurante en tes cités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 22, 'Quand reviendras-tu vers moi, fille déshonorée; car le Seigneur a fait naître le salut d’une plantation nouvelle, et des hommes la parcourront pour y trouver leur salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 23, 'Voici ce que dit le Seigneur: On dira encore cette parole en la terre de Juda et en ses villes, lorsque j’aurai ramené ses captifs: Béni soit le Seigneur sur la montagne sainte qui lui est consacrée!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 24, 'C’est là qu’habiteront les villes de Juda; et le laboureur et le pâtre, avec ses troupeaux, parcourront tout son territoire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 25, 'J’ai enivré toute âme altérée; j’ai rassasié toute âme affamée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 26, 'Et après cela je me suis éveillé et j’ai vu, et mon sommeil avait été doux pour moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 27, 'Voilà que les jours arrivent, me dit encore le Seigneur, où je sèmerai Israël et Juda, semence d’hommes et semence de bêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 28, 'Et ceci arrivera: comme j’avais veillé sur eux pour');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 29, 'En ces jours-là, on ne dira point: Les pères ont mangé le verjus, et les dents de leurs fils en ont été agacées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 30, 'Mais chacun mourra pour son péché, et celui qui mangera le verjus en aura les gencives agacées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 31, 'Voilà que les jours arrivent, dit le Seigneur, où je ferai une alliance nouvelle avec la maison d’Israël et la maison de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 32, 'Non comme l’alliance que je fis avec leurs pères le jour où, les ayant pris par la main, je les tirai de la terre d’Égypte; car ils n’ont point maintenant mon alliance, et moi, je ne me suis plus occupé d’eux, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 33, 'Mais voici l’alliance qu’après ces jours-là je ferai avec la maison d’Israël, dit le Seigneur: je leur donnerai mes lois, et je les mettrai en leur pensée, et je les écrirai dans leur cœur; je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 34, 'Et ils n’enseigneront plus chacun son concitoyen ou son frère, disant: Connais le Seigneur; car alors tous me connaîtront du petit au grand, et je serai miséricordieux pour leurs iniquités, et je ne me souviendrai plus de leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 35, '(Vulg., 37.) Comme le ciel ne peut s’élever, ni les fondements de la terre s’abaisser, dit le Seigneur, ainsi je n’éprouverai point la race d’Israël en retour de ce qu’ils ont fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 36, '(38.) Voici ce que dit le Seigneur: Celui qui a créé le soleil pour éclairer les jours, la lune et les étoiles pour éclairer les nuits; celui qui a donné à la mer ses');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 37, 'Si tes lois cessent d’être devant moi, dit le Seigneur, la race d’Israël cessera désormais d’être un peuple à mes yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 38, 'Et voilà que les jours arrivent, dit le Seigneur, où la ville du Seigneur sera rebâtie, depuis la tour d’Anaméhel jusqu’à la porte de l’Angle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 39, 'Et sa mesure s’étendra jusqu’à la colline de Gareb, et on l’entourera de pierres de choix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 38, 40, 'Et tout le terrain, depuis Asarimoth jusqu’au torrent de Cédron et à l’angle de la porte orientale des chevaux, sera consacré au Seigneur; et il ne sera plus abandonné, et il n’y aura plus rien de détruit jusqu’à la fin des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 1, 'Parole du Seigneur, qui vint à Jérémie en la dixième année du règne de Sédécias; cette année était la dix-huitième du règne de Nabuchodonosor à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 2, 'Et l’armée du roi de Babylone planta des palissades autour de Jérusalem, et Jérémie était gardé dans le préau qui est dans le palais du roi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 3, 'Où l’avait renfermé Sédécias, disant: Pourquoi prophétises-tu, disant: Ainsi parle le Seigneur: Voilà que je livre cette ville au roi de Babylone; et il la prendra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 4, 'Et Sédécias n’échappera pas aux Chaldéens; car très-certainement il sera livré aux mains du roi de Babylone, et il lui parlera face à face, et ses yeux verront ses yeux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 5, 'Et Sédécias sera emmené à Babylone, et il y restera?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 6, 'Et la parole du Seigneur vint donc à Jérémie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 7, 'Voilà que Anaméhel, fils de Salom, frère de ton père, va venir le trouver, disant: Achète pour toi mon champ d’Anathoth, parce qu’il est juste que tu le possèdes en l’achetant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 8, 'Et Anaméhel, fils de Salom, frère de mon père, vint me trouver dans le préau de la prison, et me dit: Achète pour toi mon champ en la terre de Benjamin en Anathoth, parce que tu as le droit de l’acheter, étant le plus ancien. Et je reconnus que c’était la parole du. Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 9, 'Et j’achetai le champ d’Anaméhel, fils du frère de mon père, et je pesai pour lui sept sicles et dix pièces d’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 10, 'Et je fis un écrit, je le scellai, et je pris des témoins, et je mis l’argent dans la balance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 11, 'Et je gardai l’écrit d’acquisition scellé,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 12, 'Et je le remis à Baruch, fils de Nérias, fils de Maasie, sous les yeux d’Anaméhel, fils du frère de mon père, et sous les yeux des hommes qui étaient là, et dont le nom était écrit dans l’acte d’acquisition, et sous les yeux des Juifs se trouvant dans le préau de la prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 13, 'Et je donnai mes ordres à Baruch sous leurs yeux, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 14, 'Voici ce qué dit le Seigneur tout-puissant: Prends cet acte d’acquisition, acte que tu as lu, et mets-le dans un pot de terre, afin qu’il soit conservé longtemps;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 15, 'Car voici ce que dit le Seigneur: On bâtira encore ici des maisons; on cultivera encore des champs et des vignes en cette terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 16, 'Et je priai le Seigneur, après avoir remis l’acte d’acquisition à Baruch, fils de Nérias, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 17, 'Ô Dieu vivant, Seigneur, vous avez créé le ciel et la terre par votre toute-puissance et la force de votre bras; rien ne vous est caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 18, 'Vous faites miséricorde à des milliers de générations, et vous reversez la punition des péchés des pères dans le sein de leurs enfants, après eux: ô Dieu, plein de grandeur et de force,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 19, 'Seigneur, vos desseins sont grands, vous êtes puissant en vos œuvres; ô Dieu, grand et tout-puissant, Seigneur, dont le nom est grand, vos yeux sont sur les voies des fils des hommes pour rétribuer chacun selon sa voie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 20, 'C’est vous qui jusqu’à ce jour avez multiplié les signes et les prodiges en la terre d’Égypte et en Israël, et parmi les enfants de la terre; et vous avez fait votre nom tel qu’il est aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 21, 'Et vous avez ramené votre peuple Israël de la terre d’Égypte, par vos signes et vos prodiges, par votre main puissante, par votre bras souverain et par de grandes visions;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 22, 'Et vous leur avez donné cette terre que vous aviez promise avec serment à leurs pères, et où coulent le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 23, 'Et ils y sont entrés, et ils l’ont prise, et ils n’ont plus écouté votre voix, et ils n’ont point marché selon vos commandements; ils n’ont point fait tout ce que vous leur aviez prescrit, et ils sont cause de tous les maux qui leur sont arrivés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 24, 'Voilà qu’une multitude est venue contre cette ville pour la prendre, et la ville a été livrée aux Chaldéens, qui lui font la guerre par le glaive et la famine; et comme vous l’aviez dit il est advenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 25, 'Et vous m’avez dit: Achète un champ à prix d’argent, et j’ai fait l’écrit et je l’ai scellé, et j’ai pris des témoins, et la ville a été livrée aux Chaldéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 26, 'Et la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 27, 'Je suis le Seigneur Dieu de toute chair; est-ce que quelque chose m’est caché?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 28, 'C’est pourquoi voici ce que dit le Seigneur Dieu d’Israël Cette ville sera livrée au roi de Babylone, et il la prendra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 29, 'Et les Chaldéens viendront combattre cette ville, et ils la brûleront par le feu, et ils brûleront les maisons où sur les terrasses on brûlait de l’encens à Baal, et où l’on faisait des libations à des dieux étrangers, afin de m’exaspérer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 30, 'Car les fils d’Israël et les fils de Juda ont été les seuls à faire le mal, sous mes yeux, depuis leur jeunesse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 31, 'Car cette ville a toujours été le sujet de mon indignation et de ma colère, depuis le jour où ils l’ont bâtie jusqu’à ce jour; il faut qu’elle disparaisse de ma présence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 32, 'En punition de tous les péchés d’Israël et de Juda, qu’ils ont commis pour m’exaspérer, eux et leurs rois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 33, 'Ils m’ont tourné le dos au lieu de me regarder en face; je les avais instruits dès l’aurore, et ils ont refusé d’accueillir mon enseignement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 34, 'Et ils ont fait leurs profanations, au milieu de leurs impuretés, dans la maison où mon nom était invoqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 35, 'Et ils ont élevé à Baal des autels dans la vallée des fils d’Ennom, pour offrir leurs fils et leurs filles au roi Moloch, choses que je ne leur ai point commandées; car il n’est jamais entré dans mon cœur qu’ils fissent pareille abomination pour induire Israël à pécher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 36, 'Et maintenant voici ce que dit le Seigneur Dieu d’Israël sur la ville dont tu parles: Elle sera livrée au roi de Babylone par le glaive, par la famine et par l’exil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 37, 'Et voilà que je les rassemblerai de toutes les parties de la terre où je les aurai dispersés dans les transports de mon indignation et de ma fureur extrême; et je les ramènerai en ce lieu, et je les y ferai demeurer en assurance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 38, 'Et ils seront mon peuple, et je serai leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 39, 'Et je leur donnerai une autre voie et un autre cœur, afin qu’ils me craignent tous les jours pour leur bien et pour le bien de leurs enfants après eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 40, 'Et je ferai avec eux une alliance éternelle que je ne détruirai point après eux; et je donnerai à leur cœur la crainte de mon nom pour qu’ils ne s’éloignent plus de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 41, 'Et je les visiterai pour leur faire du bien, et je les planterai en cette terre fidèle, de tout mon cœur et de toute mon âme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 42, 'Car voici ce que dit le Seigneur: De même que j’ai amené sur ce peuple tous ces grands maux, de même je lui amènerai tous les biens que je lui ai promis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 43, 'Et on achètera encore des champs en cette terre, dont tu as dit: Elle sera abandonnée des hommes et des bêtes, et ils ont été livrés aux Chaldéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 39, 44, 'Et l’on achètera des champs à prix d’argent. Et tu feras un écrit, et tu le scelleras, et tu prendras des témoins en la terre de Benjamin et autour de Jérusalem, et dans les villes de Juda, et dans les villes des montagnes, et dans les villes de Séphila, et dans les villes de Nacheb; parce que je ramènerai leurs captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 1, 'Et la parole du Seigneur vint de nouveau à Jérémie, lorsqu’il était encore enchaîné dans le préau de la prison;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 2, 'Voici ce que lui dit le Seigneur, créateur de la terre, qui l’a formée pour la redresser; son nom est le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 3, 'Crie vers moi et je te répondrai, et je te ferai connaître de grandes choses et très-certaines que tu ne sais pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 4, 'Car voici ce que dit le Seigneur, concernant les maisons de cette ville et les palais du roi de Juda, qui ont été détruits pour en faire des palissades et des ouvrages avancés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 5, 'Qu’on opposait aux Chaldéens, et qui furent remplis de cadavres d’hommes frappés par moi dans mon indignation et ma colère, quand je détournai d’eux ma face en punition de leurs méchancetés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 6, 'Voilà que je lui apporte le remède et la guérison; je me montrerai à elle et je la guérirai; je lui donnerai la sécurité et la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 7, 'Et je ramènerai les captifs de Juda et les captifs d’Israël, et je les réédifierai comme ils étaient autrefois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 8, 'Et je les purifierai de toutes les iniquités qu’ils ont commises envers moi, et je ne me souviendrai plus des péchés où ils sont tombés en se révoltant contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 9, 'Et ce sera un sujet de joie, de louange et de grandeur pour tout peuple de la terre qui apprendra le bien que je leur ferai; et les gentils seront effrayés et jaloux des biens et de toute la paix que je lui donnerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 10, 'Voici ce que dit le Seigneur: On entendra encore en ce lieu dont vous dites: C’est un désert abandonné des bêtes et des hommes; les villes de Juda, les alentours de Jérusalem sont dépeuplés; car il n’y a plus ni hommes ni bétail;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 11, 'On y entendra la voix des fêtes et des joies, la voix de l’époux et la voix de l’épouse, et les voix de ceux qui diront: Rendez gloire au Seigneur tout-puissant; car le Seigneur est bon, et sa miséricorde est éternelle. Alors on apportera des présents au temple du Seigneur, parce que je ferai revenir tous les captifs de cette terre, et qu’ils seront comme ils étaient autrefois, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 12, 'Voici ce que dit le Seigneur Dieu des armées: En ce lieu désert où l’on ne voit ni hommes ni bétail, il Ꭹ aura encore, dans toutes ses villes, des cabanes de pasteurs qui y feront reposer leurs troupeaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 13, 'Il y en aura dans les villes des montagnes, dans');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 40, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 1, 'Parole du Seigneur qui vint à Jérémie quand Nabuchodonosor, roi de Babylone, et toute son armée et toute la terre qu’il gouvernait, combattirent contre Jérusalem et contre toutes les villes de Juda, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 2, 'Voici ce que dit le Seigneur: Va trouver Sédécias, roi de Juda, et dis-lui: Ainsi parle le Seigneur: Cette ville sera livrée au roi de Babylone, et il la prendra, et il la brûlera par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 3, 'Et tu n’échapperas pas de ses mains; mais tu seras pris, tu seras livré entre ses mains, et tes yeux verront ses yeux, et tu iras à Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 4, 'Cependant, écoute la parole du Seigneur, Sédécias, roi de Juda; voici ce que dit le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 5, 'Tu mourras en paix; et, comme on a pleuré tes pères qui ont régné avant toi, on te pleurera aussi, disant: Hélas! Seigneur! et à ta mort on se frappera la poitrine à cause de toi; car telle est la sentence que j’ai prononcée, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 6, 'Ainsi Jérémie dit toutes ces paroles au roi Sédécias en Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 7, 'Et l’armée du roi de Babylone combattait contre Jérusalem et contre les villes de Juda Lachis et Azica; car parmi les villes fortes de Juda celles-là n’étaient pas encore prises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 8, 'Voici la parole du Seigneur qui vint à Jérémie après que le roi Sédécias eut fait alliance avec le peuple pour publier la remise;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 9, 'Afin que chacun affranchît son serviteur et sa servante, que l’Hébreu des deux sexes fût libre, et qu’il n’y eût plus de servitude en Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 10, 'Et tous les grands changèrent d’avis, et tout le peuple qui était entré dans l’alliance, pour que chacun affranchît son serviteur et sa servante, et ils affranchirent');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 11, 'Leurs serviteurs et leurs servantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 12, 'Et la parole du Seigneur vint à Jérémie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 13, 'Ainsi parle le Seigneur: J’ai fait alliance avec vos pères le jour où je les ai ramenés d’Égypte, de la maison de servitude, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 14, 'Lorsque six années seront révolues, tu affranchiras ton frère hébreu qui t’aura été vendu, et qui aura travaillé six ans pour toi; alors tu le renverras libre. Et ils ne m’ont pas écouté, et ils n’ont point prêté l’oreille à mes commandements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 15, 'Et aujourd’hui ils se sont convertis, voulant faire ce qui est juste à mes yeux, pour que chacun proclamât la libération de son prochain; et ils ont fait alliance devant moi dans le temple où mon nom est invoqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 16, 'Puis vous avez changé d’avis et vous avez profané mon nom en promettant que chacun affranchirait son serviteur et sa servante; et vous ne les avez point renvoyés libres, maîtres d’eux-mêmes; vous les avez gardés, serviteurs et servantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 17, 'À cause de cela, voici ce que dit le Seigneur: Vous ne m’avez point écouté pour proclamer la libération de vos frères. Et moi, voilà que je proclame votre expulsion par le glaive, par la peste et par la famine; je vous disperserai dans tous les royaumes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 18, 'Et je livrerai les hommes qui ont rompu mon alliance, qui n’ont point maintenu l’alliance faite devant moi et confirmée par le veau qu’ils avaient préparé pour le sacrifice;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 19, 'Ainsi que les princes de Juda, et les grands, et les prêtres, et le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 20, 'Et je les livrerai à leurs ennemis; et leurs cadavres seront en pâture aux oiseaux du ciel et aux bêtes des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 21, 'Et je livrerai aux mains de leurs ennemis Sédécias, roi de Judée, et ses princes; car l’armée du roi de Babylone ramènera ceux qui s’étaient quelque temps éloignés d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 41, 22, 'Voilà ce que j’ordonne, dit le Seigneur: Je les ramènerai sur cette terre, et ils combattront contre elle, et ils la prendront, et ils la brûleront par le feu; et je ferai des villes de Juda un désert où il n’y aura point d’habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 1, 'Parole du Seigneur qui vint à Jérémie dans les jours de Joakim, roi de Juda, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 2, 'Va dans la maison des Réchabites et amène-les au temple du Seigneur, dans l’un des parvis, et donneleur à boire du vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 3, 'Et j’amènerai Jéchonias, fils de Jérémin, fils de Habasin, et ses frères et ses fils, et toute la maison des Réchabites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 4, 'Et je les fis entrer dans le temple du Seigneur, dans la chambre des fils de Jonas, fils d’Ananie, fils de Godolias, homme de Dieu; laquelle est près de la maison des princes, au-dessus de la maison de Maasie, fils de Selom, gardien du parvis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 5, 'Et je mis devant eux une coupe de vin et des vases, et je leur dis: Buvez du vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 6, 'Et ils dirent: Nous ne boirons pas de vin, parce que Jonadab, fils de Réchab, notre père, nous l’a défendu, disant: Ne buvez jamais de vin, ni vous ni vos fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 7, 'Ne bâtissez point de maisons, ne semez point de graines et n’ayez point de vignes, parce que vous demeu-');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 8, 'Et nous avons été dociles aux instructions de Jonadab, notre père; nous n’avons de nos jours bu de vin, nous ni nos femmes, nos fils ni nos filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 9, 'Nous n’avons point bâti de maisons pour y demeurer; nous n’avons possédé ni vignes, ni champs, ni semence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 10, 'Et nous avons demeuré sous des tentes, et nous avons obéi, et nous avons fait tout ce qu’avait prescrit Jonadab, notre père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 11, 'Et lorsque Nabuchodonosor est entré dans le pays, nous avons dit: Nous entrerons à Jérusalem; et nous y sommes entrés par crainte de l’armée des Chaldéens et de l’armée des Assyriens; nous avons donc demeuré ici.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 12, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 13, 'Ainsi parle le Seigneur: Va et dis à tout homme de Juda et aux habitants de Jérusalem: Ne profitez-vous point de la correction pour être indociles à mes paroles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 14, 'Les fils de Jonadab, fils de Réchab, ont gardé la parole qu’il avait dite à ses enfants, leur prescrivant de ne point boire de vin, et ils n’en ont point bu. Et moi, je vous ai parlé dès l’aurore, et vous ne m’avez pas écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 15, 'Je vous ai envoyé mes serviteurs les prophètes, disant Détournez-vous de votre mauvaise voie, ayez de meilleures habitudes; ne marchez pas à la suite des dieux étrangers pour les servir; et vous demeurerez en la terre que j’ai donnée à vous et à vos pères. Et vous ne m’avez point prêté l’oreille, et vous ne m’avez pas écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 16, 'Et les fils de Jonadab, fils de Réchab, ont observé les commandements de leur père; et ce peuple ne m’a pas écouté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 17, 'À cause de cela, ainsi parle le Seigneur: Voilà que j’amènerai sur Juda et sur les habitants de Jérusalem tous les maux dont je les ai menacés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 18, 'À cause de cela, voici ce que dit encore le Seigneur Puisque les fils de Jonadab, fils de Réchab, ont obéi aux commandements de leur père, et qu’ils ont fait ce qu’il leur avait prescrit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 19, 'Jamais il ne manquera d’hommes parmi les fils de Jonadab, fils de Réchab, qui se tiennent devant ma face, durant tous les jours que cette terre subsistera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 42, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 1, 'La quatrième année du règne de Joakim, fils de Josias, la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 2, 'Prends une feuille d’un livre, et écris sur cette');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 3, 'Peut-être la maison de Juda fera-t-elle attention à tous les maux que j’ai résolu de leur faire, afin qu’ils se détournent de leur mauvaise voie, et je serai miséricordieux pour leurs iniquités et leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 4, 'Et Jérémie appela Baruch, fils de Nérias; et celui-ci écrivit, de la bouche même de Jérémie, sur les feuilles du livre, toutes les paroles que le Seigneur lui avait dites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 5, 'Et Jérémie donna ses ordres à Baruch, disant: Je suis surveillé, et je ne puis entrer dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 6, 'C’est donc toi qui liras cet écrit aux oreilles du peuple, dans le temple du Seigneur, le jour du jeûne, et tu feras cette lecture aux oreilles de tous ceux de Juda, qui sont venus de leurs villes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 7, 'Peut-être leur prière touchera-t-elle de compassion la face du Seigneur, et se détourneront-ils de leur mauvaise voie; car grande est la colère que le Seigneur a dénoncée contre ce peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 8, 'Et Baruch fit tout ce que lui avait commandé Jérémie, et il lut dans le livre les paroles du Seigneur, dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 9, 'En la huitième année du règne de Joakim, dans le temple du Seigneur, la maison de Juda s’étant rassemblée pour le jeûne en Jérusalem, devant le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 10, 'Baruch lut l’écrit contenant la parole de Jérémie, dans le temple du Seigneur, en la demeure de Gamarias, fils de Saphan le scribe, dans les parvis du Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 11, 'Et Michée, fils de Gamarias, fils de Saphan, entendit toutes les paroles du Seigneur contenues dans l’écrit;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 12, 'Et il descendit au palais du roi, en la demeure du scribe; et voilà que tous les princes y siègeaient; il y avait Élisama le scribe, et Dalaïas, fils de Sélémias, et Jonathan, fils d’Acchobor, et Gamarias, fils de Saphan, et Sédécias, fils d’Ananie, et tous les princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 13, 'Et Michée leur rapporta toutes les paroles qu’il avait entendues, pendant que Baruch les lisait aux oreilles du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 14, 'Et tous les princes envoyèrent à Baruch, fils de Nérias, Judi, fils de Nathanie, fils de Sélémias, fils de Chusi, disant Prends à ta main l’écrit que tu as lu aux oreilles du peuple, et viens; et Baruch prit l’écrit, et il descendit près d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 15, 'Et ils lui dirent: Relis-le à nos oreilles; et Baruch le lut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 16, 'Il arriva qu’après avoir ouï ces paroles ils se consultèrent entre eux, et dirent: Rapportons au roi toutes ces paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 17, 'Et ils questionnèrent Baruch, disant: Où as-tu écrit ces paroles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 18, 'Et Baruch dit: Jérémie de sa bouche m’a dit toutes ces paroles, et je les ai écrites en un livre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 19, 'Et ils dirent à Baruch Va, et cachez-vous, toi et Jérémie, et que nul homme ne sache où vous êtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 20, 'Et ils entrèrent auprès du roi, dans son palais, et ils donnèrent l’écrit à l’un d’eux pour le garder, dans la demeure d’Élisama, et ils rapportèrent au roi toutes ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 21, 'Et le roi envoya Judi prendre l’écrit, et il le prit dans la maison d’Élisama; et Judi se mit à le lire aux oreilles du roi et de tous les princes qui se tenaient autour du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 22, 'Et le roi était assis dans son appartement d’hiver, et il y avait un grand brasier devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 23, 'Et il arriva que, quand Judi eut lu trois ou quatre pages, le roi coupa les feuilles avec le canif du scribe, et les jeta dans le feu du brasier, et elle fut tout entière brûlée par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 24, 'Or, ni le roi ni ses serviteurs, en écoutant ces paroles, ne cherchèrent le Seigneur, et ils ne déchirèrent point leurs vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 25, 'Et ce furent Elnathan et Godolias qui suggérèrent au roi de brûler l’écrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 26, 'Et le roi prescrivit à Jéréméhel, fils du roi, et à Saraïas, fils d’Esrihel, de prendre Baruch et Jérémie; mais ils étaient cachés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 27, 'Et la parole du Seigneur vint à Jérémie, après que le roi eut brûlé la feuille, et toutes les prophéties que Baruch avait écrites de sa bouche, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 28, 'Prends une autre feuille, et écris toutes les paroles qui étaient sur la première, et que le roi Joakim a brûlées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 29, 'Et dis: Voici ce que dit le Seigneur: Tu as brûlé cette feuille, disant: Pourquoi as-tu écrit sur cette feuille de telles paroles? Le roi de Babylone viendra, et entrera dans cette terre, et il la dévastera, et il ne s’y trouvera plus ni homme ni bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 30, 'Et à cause de cela, voici ce que dit le Seigneur sur Joakim, roi de Juda: Il n’aura point de fils solidement assis sur le trône de David; quant à lui, son cadavre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 31, 'Etje le visiterai, lui, et sa race, et ses serviteurs, et j’amènerai sur lui et sur les habitants de Jérusalem, et sur la terre de Juda, tous les maux que je leur ai promis et qu’ils n’ont pas écoutés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 43, 32, 'Et Baruch prit une autre feuille, et il y écrivit de la bouche de Jérémie toutes les paroles de l’écrit qu’avait brûlé Joakim, et ils y ajoutèrent beaucoup d’autres paroles semblables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 1, 'Et Sédécias, fils de Josias, régna à la place de Joakim, et il fut mis sur le trône par Nabuchodonosor, roi de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 2, 'Et ni lui, ni ses serviteurs, ni le peuple de cette terre, n’écoutèrent les paroles du Seigneur, qu’il avait dites par la bouche de Jérémie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 3, 'Et le roi Sédécias envoya Joachal, fils de Sélémias, et Sophonie, le prêtre, fils de Maasie, auprès de Jérémie, disant Prie maintenant pour nous le Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 4, 'Et Jérémie allait et venait au milieu de la ville; car on ne l’avait pas enfermé dans la prison; et l’armée du Pharaon sortit de l’Égypte, et les Chaldéens apprirent cette nouvelle, et ils s’éloignèrent de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 5, 'Et la parole du Seigneur vint à Jérémie, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 6, 'Ainsi parle le Seigneur: Voici ce que tu diras au roi de Juda qui a envoyé des gens auprès de toi pour me consulter: Voilà que l’armée du Pharaon vient à votre secours; mais elle retournera en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 7, 'Les Chaldéens, à leur tour, reviendront, et ils assiègeront cette ville, et ils la prendront, et ils la brûleront par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 8, 'Car voici ce que dit le Seigneur: Ne faites point de conjectures en vos âmes, disant: Les Chaldéens partiront et s’éloigneront de nous; car ils ne s’en iront pas;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 9, 'Et quand même vous écraseriez toute l’armée des Chaldéens qui vous font la guerre, quand même il n’en resterait qu’un petit nombre d’hommes blessés, ils se lèveront chacun en sa province, et ils brûleront cette ville par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 10, 'Et il arriva que, lorsque l’armée des Chaldéens se fut éloignée de Jérusalem, en face de l’armée de Pharaon,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 11, 'Jérémie sortit de Jérusalem, et alla en la terre de Benjamin, pour y acheter un champ, au milieu du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 12, 'Comme il passait la porte de Benjamin, un homme avec qui il logeait, Sarvias, fils de Sélémias, fils d’Ananie, l’arrêta, disant: Tu t’enfuis chez les Chaldéens?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 13, 'Et il répondit: C’est faux, je ne m’enfuïs pas chez les Chaldéens. Mais Sarvias ne l’écouta point, et il l’arrêta, et il le conduisit devant les princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 14, 'Et les princes se mirent en colère contre Jérémie, et ils le frappèrent, et l’envoyèrent en la maison de Jonathan le scribe; car ils en avaient fait une prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 15, 'Ainsi Jérémie fut mis dans la basse-fosse, au cachot, et il y demeura plusieurs jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 16, 'Et Sédécias l’envoya chercher, et il le questionna');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 17, 'Et Jérémie dit au roi: Quel tort ai-je fait à toi et à tes serviteurs, et à tout ce peuple, pour que vous me mettiez en prison?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 18, 'Et où sont vos prophètes qui vous prophétisaient, disant: Le roi de Babylone ne marchera pas contre cette terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 19, 'Et maintenant, ô roi mon maître, que mon appel à ta compassion tombe devant ta face! Pourquoi me renvoyer en la maison de Jonathan le scribe? Fais que je n’y meure point!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 20, 'Et le roi donna ses ordres; et on le mit dans la prison ordinaire, et on lui donna, outre la viande que l’on cuisait, un pain par jour, jusqu’à ce que le pain manquât dans la ville; et Jérémie demeura dans le préau de la prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 44, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 1, 'Et Saphanias, fils de Nathan, et Godolias, fils de Paschor, et Joachal, fils de Sélémias, entendirent les paroles que Jérémie avait dites au peuple, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 2, 'Voici ce que dit le Seigneur: Quiconque demeure en cette ville, mourra par le glaive ou la famine; mais celui qui s’en ira vers les Chaldéens vivra, et sa vie lui sera comme un butin, et il vivra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 3, 'Car voici ce que dit le Seigneur: Cette ville sera livrée à l’armée du roi de Babylone, et il la prendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 4, 'Et ils dirent au roi: Que cet homme soit mis à mort, parce qu’il énerve les bras des hommes de guerre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 5, 'Et le roi dit: Voilà qu’il est dans vos mains. Car le roi ne pouvait leur résister.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 6, 'Et ils le jetèrent dans la citerne de Melchias, fils du roi, laquelle était dans le préau de la prison; ils le descendirent dans la citerne avec des cordes, et il n’y avait point d’eau, mais de la fange dans la citerne; et il était dans cette fange.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 7, 'Et Abdémélech l’Éthiopien, qui était de la maison du roi, apprit qu’ils avaient jeté Jérémie dans la citerne; or le roi était à la porte de Benjamin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 8, 'Il sortit done pour l’aller trouver, et il parla au roi, et lui dit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 9, 'Tu as mal fait en agissant ainsi; cet homme-là va mourir de faim, car il n’y a plus de pain dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 10, 'Et le roi donna ses ordres à Abdémélech, disant: Emmène avec toi trente hommes, et retire-le de la citerne, afin qu’il ne meure point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 11, 'Et Abdémélech prit les hommes, et il entra dans les souterrains du palais du roi, et il emporta de vieux morceaux d’étoffes et de vieilles cordes, et il les jeta à Jérémie dans la citerne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 12, 'Et il dit: Mets ces vieilles étoffes sous les cordes; et Jérémie fit comme il avait dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 13, 'Et ils le tirèrent avec les cordes, et ils le firent sortir de la citerne; et Jérémie demeura dans le préau de la prison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 14, 'Et le roi l’envoya chercher, et il le fit venir en la');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 15, 'Et Jérémie répondit: Si je te parle, ne me ferastu pas mourir? Et si je te donne un conseil, n’est-il pas vrai que tu ne m’écouteras point?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 16, 'Et le roi le lui jura et dit: Vive le Seigneur, qui a mis notre âme en nous; je ne te ferai pas mourir, et je ne te livrerai pas aux mains de ces hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 17, 'Et Jérémie reprit: Voici ce que dit le Seigneur: Si tu sors pour aller trouver les princes du roi de Babylone, ta vie sera sauve, et cette ville ne sera pas brûlée par le feu; et tu vivras, toi et ta maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 18, 'Et si tu ne sors pas, cette ville sera livrée aux Chaldéens, et ils la brûleront par le feu, et tu ne seras point sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 19, 'Et le roi dit à Jérémie: Je suis en peine des Juifs qui se sont réfugiés auprès des Chaldéens; ne va-t-on pas me livrer à eux, qui feront de moi un sujet de dérision?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 20, 'Et Jérémie répondit: On ne te livrera pas aux Juifs; écoute la parole du Seigneur que je te dis; ilen ira mieux pour toi, et ta vie sera sauve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 21, 'Et si tu ne veux point sortir, telle est la parole que m’a fait voir le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 22, 'Voilà que toutes les femmes qui étaient restées dans le palais du roi de Juda ont été conduites aux princes du roi de Babylone, disant: Les hommes qui se disaient tes amis te trompaient; ils ont prévalu contre toi, ils sont cause que ton pied glisse et trébuche; ils se sont détournés de toi;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 23, 'Et ils conduiront aux Chaldéens tes femmes et tes enfants, et toi, tu ne seras point sauvé; car tu tomberas dans les mains du roi de Babylone, et cette ville sera brûlée par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 24, 'Et le roi lui dit: Que nul ne sache aucune de ces paroles, et tu ne mourras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 25, 'Et si les princes apprennent que je t’ai parlé, et s’ils vont à toi, disant: Parle-nous; que t’a dit le roi? ne nous le cache point, et nous ne te ferons pas mourir; voyons, que t’a dit le roi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 26, 'Dis-leur: J’ai fait appel à la compassion devant la face du roi, pour qu’il ne me renvoie pas dans la maison de Jonathan, et que je n’y meure point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 27, 'Et tous les princes vinrent trouver Jérémie, et ils le questionnèrent, et il leur répondit comme l’avait commandé le roi; et ils gardèrent le silence, parce qu’ils n’avaient rien ouï de la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 45, 28, 'Et Jérémie demeura dans le préau de la prison, jusqu’au temps de la prise de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 1, 'Et le deuxième mois du règne de Sédécias, Nabuchodonosor, roi de Babylone, vint avec toute son armée contre Jérusalem, et il l’assiègea.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 2, 'Et dans l’année onzième de Sédécias, le quatrième mois, le neuvième jour du mois, la ville fut ouverte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 3, 'Et tous les princes du roi de Babylone y entrèrent; et Marganasar, Samagoth, Nabusachar, Nabusaris, Nagargas et Naserrabamath et tous les autres généraux du roi de Babylone se logèrent sous la porte du milieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 4, '(Vulg., 14.) Et ils envoyèrent des gens pour retirer');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 5, '(15.) Et la parole du Seigneur vint à Jérémie, lorsqu’il était encore dans le préau de la prison, disant: 6. (16.) Va et dis à Abdémélech l’Éthiopien: Voici ce que dit le Seigneur Dieu d’Israël Je vais accomplir mes paroles sur cette ville, pour son malheur, et non pour son bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 7, '(17.) Mais en ce jour-là je te sauverai, et je ne te livrerai point à des hommes que tu crains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 8, '(18.) Et je te sauverai, et tu ne périras point par le glaive; et ta vie te sera comme un butin, parce que tu as eu confiance en moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 46, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 1, 'Parole du Seigneur qui vint à Jérémie après que le chef des cuisines Nabuzardan l’eut renvoyé de Rama, quand il avait des menottes au milieu des captifs de Juda que l’on emmenait à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 2, 'Et le chef des cuisines le prit, et lui dit: Le Seigneur ton Dieu a prononcé tout ce mal sur ce pays.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 3, 'Et le Seigneur a fait cela, parce que vous avez péché contre lui, et que vous n’avez point écouté sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 4, 'Et moi, voilà que j’ai ôté les menottes que tu avais aux mains. S’il te plaît de venir avec moi à Babylone, j’aurai les yeux sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 5, 'Sinon va-l’en, retourne auprès de Godolias, fils d’Achicam, fils de Saphan, que le roi de Babylone a fait gouverneur de la terre de Juda, et demeure avec lui, parmi le peuple de Juda; et où il te semblera bon d’aller va;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 6, 'Et il se rendit près de Godolias en Masphath, et il demeura parmi ceux de son peuple qui étaient restés en la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 7, 'Et tous les chefs de l’armée du peuple qui étaient dans le pays, et leurs hommes, apprirent que le roi de Babylone avait fait Godolias gouverneur de la terre, et qu’il lui avait confié les hommes qu’il n’emmenait pas à Babylone, et leurs femmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 8, 'Alors Ismaël, fils de Nathanias, Joanan, fils de Carée, et Saraïas, fils de Thanaémeth, et les fils de Jophé, de Nétophath, et Ezoni, fils de Mochati, avec leurs hommes, allèrent trouver Godolias à Masphath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 9, 'Et Godolias leur prêta serment, à eux et à leurs hommes, disant: Ne craignez point devant les enfants des Chaldéens; demeurez en la terre, et travaillez pour le roi de Babylone; il en ira mieux pour vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 10, 'Pour moi, voilà que je demeure devant vous à Masphath, pour m’y tenir à la portée des Chaldéens qui viendraient contre vous; récoltez dunc votre vin, vos fruits, votre huile; remplissez vos vases et restez dans les villes que vous occupez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 11, 'Or tous les Juifs qui étaient, soit en Moab ou chez les fils d’Ammon, soit en Idumée, soit dans toute la terre sainte, apprirent que le roi de Babylone avait gracié quelques restes de Juda, et qu’il avait mis à leur tête Godolias, fils d’Achicam.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 12, 'Ils allèrent donc trouver Godolias en la terre de Juda, à Masphath, et ils récoltèrent du vin, beaucoup de fruits et de l’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 13, 'Et Joanan, fils de Carée, et tous les chefs de l’armée qui étaient dans les champs, allèrent à Masphath auprès de Godolias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 14, 'Et ils lui dirent: Sais-tu bien que Bélissa, roi des fils d’Ammon, a envoyé contre toi Ismaël, pour te frapper à mort? Et Godolias ne les crut pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 15, 'Et Joanan dit secrètement à Godolias en Masphath: Je partirai et je tuerai Ismaël, et que nul ne le sache; de peur qu’il ne te frappe à mort, que tout Juda, qui est réuni auprès de toi, ne soit dispersé, et que ce qui reste de Juda ne périsse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 47, 16, 'Et Godolias dit à Joanan: Ne fais pas cela; car tu parles faussement contre Ismaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 1, 'Et le septième mois, Ismaël fils de Nathanias, fils d’Eléasa, de la famille royale, vint avec dix hommes chez Godolias à Masphath, et ils y mangèrent ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 2, 'Et Ismaël et ses dix hommes se levèrent, et ils tuèrent Godolias, que le roi de Babylone avait fait gouverneur de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 3, 'Et tous les Juifs qui étaient avec lui, et tous les Chaldéens qui se trouvaient là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 4, 'Et le lendemain de la mort de Godolias, que nul ne savait encore,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 5, 'Quatre-vingts hommes vinrent de Sichem, de Salem et de Samarie, le menton rasé, les vêtements déchirés, se frappant la poitrine, portant dans leurs mains de l’encens et de la manne, pour les offrir dans le temple du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 6, 'Et Ismaël sortit de la ville à leur rencontre, et ils marchaient et ils pleuraient, et il leur dit: Entrez chez Godolias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 7, 'Et lorsqu’ils furent au milieu de la ville il les égorgea et les jeta dans un puits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 8, 'Mais il s’en trouva dix qui dirent à Ismaël: Ne nous tue pas; car nous avons dans les champs des trésors, du froment, de l’orge et de l’huile. Et il passa outre, et il ne les tua pas au milieu de leurs frères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 9, 'Or le puits où Ismaël jeta ceux qu’il avait tués, c’est le grand puits que fit le roi Asa, par crainte de Baasa, roi d’Israël, et qu’Ismaël remplit de cadavres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 10, 'Et Ismaël emmena tout le peuple qui était resté en Masphath, et les filles du roi, que le chef des cuisines avait confiées à Godolias, fils d’Achicam; et il partit pour la terre au delà des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 11, 'Or Joanan, fils de Carée, et tous les chefs de l’armée qui étaient avec lui, apprirent tout le mal qu’avait fait Ismaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 12, 'Et ils mirent en marche toute leur armée; et ils partirent pour le combattre, et ils l’atteignirent près des grandes eaux de Gabaon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 13, 'Et quand tout le peuple qui était avec Ismaël vit Joanan et les chefs de l’armée qu’il commandait,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 14, 'Ils retournèrent auprès de Joanan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 15, 'Mais Ismaël échappa avec huit hommes, et s’enfuit chez les fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 16, 'Et Joanan et les officiers de l’armée qui étaient avec lui recueillirent tous les restes du peuple, qui s’étaient éloignés d’Ismaël, et les hommes capables de porter');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 17, 'Et ils marchèrent, et ils firent halte à Gaberochamaa, près de Bethlehem, pour se rendre en Égypte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 18, 'Loin des Chaldéens; car ils en avaient crainte, parce que Ismaël avait tué Godolias, que le roi de Babylone avait fait gouverneur de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 20, '');
