INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 40, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 41, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 48, 42, '');
