INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 1, 'Et quand Jérémie eut fini de répéter au peuple les paroles du Seigneur, pour lesquelles le Seigneur l’avait envoyé à eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 2, 'Azarias, fils de Maasie, et Joanan, fils de Carée, et tous les hommes qui avaient parlé à Jérémie, dirent: Tu mens, le Seigneur ne t’a pas envoyé à nous, disant: N’entrez pas en Égypte pour y demeurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 3, 'Mais Baruch, fils de Nérias, te donne des conseils contre nous, afin que tu nous livres aux Chaldéens, et qu’ils nous tuent ou nous emmènent à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 4, 'Ainsi Joanan, les chefs de l’armée et le peuple refusèrent d’écouter la voix du Seigneur, et de demeurer en la terre de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 5, 'Joanan et les chefs de l’armée prirent tous les restes de Juda, qui étaient revenus demeurer en la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 6, 'Les hommes en état de porter les armes, et les femmes, et le reste des enfants, et les filles du roi, et les âmes que Nabuzardan avait laissées avec Godolias, fils d’Achicam, et Jérémie le prophète, et Baruch, fils de Nérias.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 7, 'Et ils entrèrent en Égypte, parce qu’ils n’avaient pas écouté la voix du Seigneur; et ils allèrent à Taphnès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 8, 'Et la parole du Seigneur vint à Jérémie en Taphnès, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 9, 'Prends de grandes pierres et cache-les, sous le portique du palais de Pharaon en Taphnès, aux yeux des hommes de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 10, 'Et dis-leur: Ainsi parle le Seigneur: Voilà que j’enverrai et conduirai en Égypte Nabuchodonosor, roi de Babylone, et il placera son trône sur ces pierres que tu as cachées, et sur ces pierres il élèvera ses armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 11, 'Et il entrera par cette porte, et il frappera la terre d’Égypte, et il enverra la peste à qui doit mourir de la peste, la captivité à ceux qui doivent être en captivité, et le glaive à qui doit périr par le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 12, 'Et il mettra le feu aux temples de leurs dieux, et il les brûlera; il fera les hommes captifs, il purgera l’Égypte de la vermine, comme un pâtre purge de la vermine son manteau, et il ira en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 13, 'Et il brisera les colonnes d’Héliopolis, qui sont en On, et il brûlera leurs maisons par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 50, 14, '');
