INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 58, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 59, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 60, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 61, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 62, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 51, 63, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 1, 'Sédécias avait vingt et un ans quand il monta sur le trône, et il régna onze ans à Jérusalem, et sa mère s’aplait Amitaal, et elle était fille de Jérémie, de Lobna.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 2, '(Vulg., 4.) Dans la neuvième année de son règne, le neuvième mois, le dixième jour du mois, Nabuchodonosor, roi de Babylone, vint avec toutes ses forces vers Jérusalem; et ils l’entourèrent de retranchements, et ils bâtirent alentour un mur en grandes pierres de taille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 3, '(5.) Et la ville fut investie jusqu’à la onzième année du règne de Sédécias,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 4, '(6.) Jusqu’au neuvième jour du mois; et alors la famine prévalut dans la cité, et il n’y avait plus de pain pour le peuple de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 5, '(7.) Une brèche fut faite aux murailles; les hommes de guerre sortirent de nuit par le chemin de la porte, entre les remparts et les forts avancés qu’on avait élevés près du jardin du roi; et les Chaldéens entouraient le reste de la ville, et les fugitifs prirent la route d’Araba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 6, '(8.) Et l’armée des Chaldéens les poursuivit, et ils prirent le roi auprès de Jéricho, et tous ses serviteurs s’étaient dispersés loin de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 7, '(9.) Les Chaldéens firent donc le roi captif et ils le menèrent au roi de Babylone, à Déblatha, et Nabuchodonosor prononça contre lui son arrêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 8, '(10.) Et il égorgea les fils de Sédécias sous ses yeux, et il égorgea tous les princes de Juda en Déblatha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 9, '(11.) Et il arracha les yeux de Sédécias; puis, après l’avoir chargé de chaînes, il l’emmena à Babylone; là il le mit avec les esclaves qui tournaient la meule, jusqu’au jour où il mourut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 10, '(12.) Et le cinquième mois, le sixième jour du mois, Nabuzardan, chef des cuisines, qui se tenait devant le roi de Babylone, marcha sur Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 11, '(13.) Et il livra aux flammes le temple du Seigneur, le palais du roi et toutes les maisons de la ville, et il mit le feu à toutes les grandes maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 12, '(14.) Et l’armée des Chaldéens qui étaient avec le chef des cuisines rasa les remparts dont la ville était entourée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 13, '(16.) Mais Nabuzardan y laissa les restes du peuple, pour être vignerons et laboureurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 14, '(17.) Et les Chaldéens brisèrent les colonnes d’airain et leurs bases et la mer d’airain qui étaient dans le temple du Seigneur, et ils en emportèrent le métal à Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 15, '(18.) Avec les couronnes, les coupes et les chaudières, et tous les vases d’airain employés au service du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 16, '(19.) Et il prit aussi les cassolettes et les bassins,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 17, '(20.) Et les deux colonnes, et la mer, et les douze bœufs d’airain sous la mer, qu’avait faits le roi Salomon pour le temple du Seigneur. On ne sut pas le poids des vases d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 18, '(21.) Et les colonnes étaient hautes chacune de trente-cinq coudées, et elles étaient entourées de chaînes longues de douze coudées, épaisses de quatre doigts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 19, '(22.) Et leurs chapiteaux d’airain avaient cinq coudées de haut, et elles étaient entourées d’un filet et de grenades d’airain, et il y avait huit grenades par coudée, et il y avait douze coudées,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 20, 'Et il y avait quatre-vingt-seize grenades sur les côtés, et il y avait en tout cent grenades sur le filet tout autour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 21, 'Et Nabuzardan prit le premier prêtre, puis le second et les trois gardiens de la voie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 22, 'Et un eunuque, chef des gens de guerre, et sept hommes distingués se tenant devant le roi, qui se trouvaient dans la ville, et le scribe des armées, chargé des écritures du peuple de la terre, et soixante hommes de la campagne qui se trouvaient dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 23, 'Et Nabuzardan, cuisinier en chef du roi, les prit et les conduisit au roi de Babylone à Déblatha.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 24, 'Et le roi les fit mettre à mort à Déblatha, en la terre d’Émath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 25, 'En la trente-septième année de la captivité de Joakim, roi de Juda, le douzième mois, le vingt-troisième jour du mois, Ulémadachar, roi de Babylone, l’année même où il monta sur le trône, prit la tête de Joakim et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 26, 'Et il lui parla avec douceur, et il lui donna un trône plus élevé que les trônes des autres rois qui l’entouraient à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 27, 'Et il lui fit changer la robe qu’il avait en prison; et il le fit manger en sa présence tous les jours qu’il vécut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 28, 'Et tous les jours, jusqu’à ce qu’il mourût, il régla constamment toute sa dépense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 52, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Or voici les paroles qu’écrivit Baruch, fils de Nérias, fils de Maasie, fils de Sédécias, fils d’Asadias, fils d’Helcias, en Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'En la cinquième année, le septième jour du mois, dans le temps que les Chaldéens prirent Jérusalem et la livrèrent aux flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Et Baruch lut les paroles de ce livre aux oreilles de Jéchonias, fils de Joakim, roi de Juda, et de tout le peuple qui était venu en écouter la lecture,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Et aux oreilles des grands, des fils du roi et des anciens, et aux oreilles du peuple, du petit au grand, et de tous ceux qui demeuraient en Babylone, sur le fleuve Sody.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Et ils pleurèrent, et ils jeûnèrent, et ils prièrent devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Et ils recueillirent de l’argent, et chacun donna ce qu’il put.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Et ils l’envoyèrent en Jérusalem à Joakim, fils d’Helcias, fils de Salom, le prêtre, et à tous les prêtres, et à tous ceux du peuple qui se trouvaient avec lui à Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Après que Baruch eut reçu les vases du temple du Seigneur, qui avaient été transportés du temple pour les renvoyer dans la terre de Juda, le dixième jour du mois de Sivan; c’étaient les vases d’argent qu’avait faits Sédécias, fils de Josias, roi de Juda,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Quand Nabuchodonosor, roi de Babylone, eut transporté Jéchonias, et les princes et les esclaves, et les riches, de la terre de Jérusalem, et les eut emmenés à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Et ils dirent: Voilà que nous vous envoyons de l’argent; avec cet argent achetez des holocaustes et des victimes pour le péché, et de l’encens; préparez aussi la manne, et faites ces offrandes sur l’autel du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Et priez pour la vie de Nabuchodonosor, roi de Babylone, et pour la vie de Balthasar, son fils, afin que leurs jours soient comme les jours du ciel sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Et le Seigneur nous donnera la force, et il éclairera nos yeux; et nous vivrons à l’ombre de Nabuchodonosor, roi de Babylone, et à l’ombre de Balthasar, son fils, et nous les servirons de longs jours, et nous trouverons grâce devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Priez pour nous le Seigneur notre Dieu, parce que nous avons péché contre le Seigneur notre Dieu, et que la colère du Seigneur ne s’est point détournée, et qu’il est encore aujourd’hui courroucé contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Et lisez-leur ce livre que nous vous avons envoyé pour le lire dans le temple du Seigneur, le jour de la fête et aux jours prescrits,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Et dites: Au Seigneur notre Dieu, la justice; à nous, la honte au front, comme il arrive aujourd’hui à tout homme de Juda, et à tout habitant de Jérusalem,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Et à nos rois, et à nos princes, et à nos prêtres, et à nos prophètes, et comme il est arrivé à nos pères;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'En punition de ce que nous avons péché devant le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Et de ce que nous lui avons désobéi, et de ce que nous n’avons point écouté la voix du Seigneur notre Dieu, pour marcher dans les commandements qu’il nous a donnés face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Depuis le jour où le Seigneur a ramené nos pères de la terre d’Égypte jusqu’à ce jour, nous avons été infidèles au Seigneur notre Dieu, et nous nous étourdissions pour ne point entendre sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Et les maux et les malédictions se sont attachés à nous, comme l’avait réglé le Seigneur avec son serviteur Moïse, le jour où il a ramené nos pères de l’Égypte pour nous donner une terre où coulent encore aujourd’hui le lait et le miel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Et nous n’avons point écouté la voix du Seigneur notre Dieu, selon les paroles des prophètes qu’il nous a envoyés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Et nous avons tous marché dans la pensée de nos cœurs pervertis, pour fabriquer d’autres dieux, et faire le mal aux yeux du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Et le Seigneur a confirmé la parole qu’il avait dite contre nous et contre nos juges, les juges d’Israël, et contre nos rois, et contre nos princes, et contre les hommes d’Israël et de Juda;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Menaçant d’amener sur nous de si grands maux que, sous le ciel entier, il ne s’en est point vu d’aussi grands que ceux qu’il a faits à Jérusalem, selon ce qui est écrit en la loi de Moïse,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Et de nous forcer à manger, l’un les chairs de son fils, l’autre les chairs de sa fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Et il les a livrés à tous les rois qui nous environnent, pour être outragés et désolés, parmi tous les peuples d’alentour, chez qui le Seigneur nous a dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Ils ont ainsi été dessous et non dessus, parce que nous avons péché contre le Seigneur notre Dieu, en refusant d’écouter sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Au Seigneur notre Dieu la justice; à nous et à nos pères, la honte au front, comme il arrive aujourd’hui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Le Seigneur avait prédit, contre nous, tous les maux qui nous sont advenus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'Et nous n’avons point prié devant le Seigneur, pour qu’il détournât chacun de nous des pensées de son cœur perverti.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Et le Seigneur a veillé sur nos maux, et il les a amenés sur nous; car le Seigneur est juste en toutes ses œuvres qu’il nous a commandées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Et nous n’avons point écouté sa voix pour marcher selon les commandements qu’il nous avait donnés face à face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Et maintenant, Seigneur Dieu d’Israël, qui avez ramené votre peuple d’Égypte, par votre main puissante, par vos signes et vos prodiges, par votre grande vertu et par votre bras souverain, et qui vous êtes fait à vous-même un nom comme encore aujourd’hui,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Nous avons péché, nous avons été impies, nous avons été iniques, Seigneur notre Dieu, en tous vos jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Que votre colère se détourne de nous; car nous sommes restés en petit nombre parmi les nations où vous nous avez dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Écoutez, Seigneur, notre prière, et sauvez-nous pour l’amour de vous-même, et faites que nous trouvions grâce devant ceux qui nous ont transportés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Afin que toute la terre sache que vous êtes le Seigneur notre Dieu, et qu’Israël et sa race ont été appelés de votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Seigneur, regardez de votre demeure sainte; exaucez-nous; penchez votre oreille, Seigneur, et écoutez nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Ouvrez les yeux et considérez que ce ne sont point les morts aux enfers, quand leur âme a abandonné leurs entrailles, qui rendront gloire et justice au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Mais l’âme contristée dans sa grandeur, et marchant courbée et sans force, mais les yeux défaillants, et l’âme affamée vous rendront gloire et justice, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Ce n’est point à cause de la justice de nos pères et de nos rois que, devant votre face, Seigneur notre Dieu, nous déposons l’appel à votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'C’est parce que vous avez envoyé contre nous votre fureur et votre colère, comme vous l’aviez dit par la bouche de vos serviteurs les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Voici ce qu’avait dit le Seigneur Courbez les épaules, travaillez pour le roi de Babylone, et demeurez en la terre que j’ai donnée à vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 22, 'Et si vous n’écoutez pas la voix du Seigneur, si vous refusez de travailler pour le roi de Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 23, 'Je ferai disparaître des villes de Juda et des rues de Jérusalem la voix de l’allégresse et la voix des fêtes, la voix des jeunes époux et la voix des épousées, et toute la terre sera déserte, faute d’habitants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 24, 'Or nous n’avons point écouté votre voix; nous avons refusé de travailler pour le roi de Babylone, et vous avez confirmé les menaces que vous aviez faites par la bouche de vos serviteurs les prophètes, de transporter hors de leur sépulcre les ossements de nos rois et les ossements de nos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 25, 'Et voilà qu’ils ont été jetés et exposés à l’ardeur des jours et à la gelée des nuits; et les hommes sont morts en de rudes labeurs, par le glaive, par la famine et par l’exil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 26, 'Et vous avez fait du temple où votre nom était invoqué ce qu’il est aujourd’hui, à cause des iniquités de la maison d’Israël et de la maison de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 27, 'Et vous nous avez traités, Seigneur notre Dieu, selon votre bonté et selon votre grande miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 28, 'Comme vous l’aviez dit à votre serviteur Moïse, le jour où vous lui avez ordonné d’écrire votre loi devant les fils d’Israël, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 29, 'Si vous n’écoutez point ma voix, n’en doutez point, de la multitude vous passerez au petit nombre, parmi les nations où je vous disperserai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 30, 'Car je sais qu’ils ne m’écouteront point, parce que ce peuple a la tête dure. Et ils ne convertiront leur cœur que dans la terre de l’exil;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 31, 'Et ils connaîtront alors que je suis le Seigneur leur Dieu, et je leur donnerai un cœur, et des oreilles qui m’écoutent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 32, 'Et ils me loueront dans la terre de la captivité, et le souvenir de mon nom leur reviendra;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 33, 'Et ils plieront leur dos rebelle, et ils corrigeront leurs inclinations perverses, parce qu’ils se souviendront de la voie de leurs pères qui ont péché devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 34, 'Et je les ramènerai en la terre que j’ai promise à leurs pères, Abraham, Isaac et Jacob, et ils en seront les maîtres; et je les multiplierai, et ils ne seront plus amoindris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 35, 'Et je ferai avec eux une alliance éternelle, pour que je sois leur Dieu et qu’ils soient mon peuple. Et je ne ferai plus sortir mon peuple Israël de la terre que je leur ai donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Seigneur tout-puissant, Dieu d’Israël, mon âme en détresse, mon esprit dans l’angoisse crie vers vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Écoutez, Seigneur, et soyez miséricordieux; car nous avons péché devant vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Vous, vous êtes immuable pour l’éternité, et nous, nous sommes perdus pour jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Seigneur tout-puissant, Dieu d’Israël, écoutez la prière des morts d’Israël, et des fils de pécheurs devant vous, qui n’ont point écouté votre voix, vous le seul Dieu; c’est pourquoi les maux se sont attachés à nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'N’ayez plus souvenir des iniquités de nos pères, mais de votre main et de votre nom, au temps où nous sommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Souvenez-vous que vous êtes le Seigneur notre Dieu, et nous vous louerons, ô Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Et c’est pour cela même que vous avez mis votre crainte en nos cœurs, et que nous invoquerons votre nom. Et nous chanterons vos louanges en notre exil; car nous avons rejeté de nos cœurs toute l’iniquité de nos pères qui avaient péché devant vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Voilà qu’aujourd’hui nous sommes exilés, en la terre où vous nous avez dispersés, pour y être outragés, maudits et persécutés pour toutes les iniquités de nos pères, qui se sont éloignés du Seigneur notre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Écoute, Israël, les préceptes de vie; prête l’oreille, et apprends la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Comment se fait-il, Israël, et d’où vient que tu es en la terre de tes ennemis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Tu as vieilli dans une terre étrangère; tu t’es souillé avec les morts; tu as été compté parmi ceux qui sont aux enfers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Tu as abandonné la source de la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Si tu avais cheminé dans la voie du Seigneur, tu demeurerais en paix dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Apprends où est la sagesse, où est la force, où est l’intelligence, afin de connaître en même temps où est la longue vieillesse, où est la vie, où est la lumière des yeux, où est la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Qui a trouvé le lieu de la sagesse, et qui est entré dans ses trésors?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Où sont les princes des nations, et ceux qui maîtrisaient les bêtes de la terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Ceux qui se faisaient un jouet des oiseaux du ciel, et qui thésaurisaient de l’argent et de l’or, en quoi les hommes se confient, et ne mettent point de bornes à leurs possessions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Ils forgent l’argent, ils y appliquent tous leurs soins; et de leurs œuvres il ne résulte aucune découverte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Et eux-mêmes sont effacés, et ils sont descendus aux enfers, et d’autres se sont élevés à leur place.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'De nouveaux venus ont vu la lumière, et ils ont demeuré sur la terre; mais ils n’ont point connu la voie de la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Ils n’en ont point connu les sentiers, et leurs fils ne l’ont point reçue, et ils se sont trouvés bien loin de la voie qu’ils auraient dû suivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'On n’a pas ouï parler d’elle en Chanaan; on ne l’a point vue à Théman.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Les fils d’Agar qui cherchent la science sur la terre, les trafiquants de Merrha et de Théman, les conteurs de fables, les chercheurs de vaine science, n’ont pas connu la voie de la sagesse, et en ont oublié les sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'O Israël, que la maison du Seigneur est grande, et que le lieu qu’il possède a d’étendue!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Il est grand, et n’a point de bornes; il est haut, et ne peut être mesuré.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Là sont nés les géants renommés des premiers jours, de grande taille, sachant la guerre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Et cependant Dieu ne les a point choisis; il ne leur a point donné la voie de la science.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Et ils ont péri pour n’avoir pas eu la raison; ils ont péri victimes de leur témérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Qui est monté au ciel, y a pris la sagesse et l’a fait descendre des nuées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 30, 'Qui a passé les mers, et l’a trouvée et la rapportera plutôt que de l’or très-pur?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 31, 'Il n’est personne qui connaisse sa voie, qui songe à ses sentiers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 32, 'Mais celui qui fait tout la connaît; il l’a trouvée par son intelligence; il est celui qui a créé la terre pour les siècles, et l’a remplie de quadrupèdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 33, 'C’est lui qui envoie la lumière, et elle marche; il l’a appelée, et, en tremblant, elle a obéi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 34, 'Et les étoiles ont brillé en leurs veilles, et elles se sont réjouies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 35, 'Il les a appelées, et elles ont dit: Nous voici; et elles ont brillé avec joie pour celui qui les a créées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 36, 'C’est là notre Dieu, et nul autre ne sera compté pour quelque chose devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 37, 'Il a trouvé toute la voie de la science; il l’a montrée à Jacob son serviteur et à Israël son bien-aimé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 38, 'Après cela, il a même été vu sur la terre et il a conversé avec les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Voici le livre des commandements de Dieu, et la loi qui subsiste éternellement; tous ceux qui s’y attachent seront dans la vie, ceux qui l’abandonnent, mourront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Convertis-toi, Jacob, et embrasse cette loi; chemine en la voie qui mène à sa clarté et à sa lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Ne donne pas ta gloire à autrui, ni ce qui est si précieux à une nation étrangère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Nous sommes heureux, Israël, parce que nous savons ce qui est agréable à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Rassurez-vous, mon peuple, vous, mémorial d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Vous avez été vendus aux nations, mais non pour votre perte; parce que vous aviez provoqué votre Dieu, vous avez été livrés aux ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Vous aviez excité la colère de votre Créateur, en sacrifiant aux démons et non à Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Vous aviez oublié celui qui vous avait nourris, le Dieu éternel; vous aviez contristé Jérusalem, votre nourrice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Car elle a vu la colère de Dieu éclater contre vous, et elle a dit: Écoutez, frontières de Sion, le Seigneur m’envoie une grande affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Car j’ai vu la captivité de mes fils et de mes filles qu’a fait venir sur eux l’Éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Je les avais nourris avec joie; je les ai délaissés avec larmes et douleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Que nul ne se réjouisse en me voyant veuve et abandonnée de la multitude de mes enfants; je suis dépeuplée pour leurs péchés, parce qu’ils se sont écartés de la loi de Dieu,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Et qu’ils ont méconnu ses jugements, et qu’ils n’ont point cheminé dans les voies de ses commandements et n’ont point marché avec justice dans les sentiers de sa doctrine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Venez, frontières de Sion; souvenez-vous de la captivité de mes fils et de mes filles qu’a fait venir sur eux l’Éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Car c’est lui qui a conduit contre eux une nation lointaine, une nation impudente, et parlant une langue étrangère, qui n’a pas respecté les vieillards et n’a pas eu pitié des enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Et ils ont emmené les bien-aimés de la veuve, et ils l’ont laissée seule et privée de ses filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Et moi, comment puis-je vous secourir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Partez, enfants, partez; car moi je reste abandonnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'J’ai quitté la robe du bonheur; j’ai ceint le cilice de ma prière; je crierai vers l’Éternel durant tous mes jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Ayez confiance, enfants, criez vers notre Dieu; et il vous sauvera de l’oppression, il vous délivrera des mains des ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Je mets en l’Éternel l’espérance de votre salut, et je me suis réjouie, dans le Dieu saint, de la miséricorde qui vous viendra bientôt de l’Éternel votre Sauveur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Je vous ai vus emmener avec larmes et douleur; mais Dieu vous rendra à moi, avec joie et bénédiction pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'De même que maintenant les femmes étrangères et établies en Sion ont vu votre captivité, de même elles verront bientôt votre salut, qui vous viendra de Dieu avec la grande gloire et l’éclat même de l’Éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Enfants, supportez avec patience cette colère de Dieu qui est tombée sur vous; l’ennemi t’a poursuivi, et bientôt lui-même verra sa ruine, et tu marcheras sur leur cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mes fils les plus tendres ont cheminé en des voies pleines d’aspérités; ils ont été emportés comme un menu troupeau que des ennemis ravissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Rassurez-vous, enfants, et criez à votre Dieu; car votre souvenir reviendra à celui même qui vous a exilés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Car si votre pensée vous a égarés loin de Dieu, quand vous serez convertis, vous le chercherez avec dix fois plus d’ardeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Parce que celui qui a amené des maux sur vous, amènera sur vous une éternelle allégresse avec votre salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Rassure-toi, Jérusalem; celui qui t’a donné ton nom te consolera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Malheur à ceux qui t’ont maltraitée, et qui se sont réjouis de ta chute!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 32, 'Malheur aux villes qui ont asservi tes fils! Malheur à celle qui t’a pris tes enfants!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 33, 'Car de même qu’elle s’est réjouie de ta chute, et qu’elle a été charmée de ta ruine, de même elle sera contristée en sa propre désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 34, 'Et je lui ôterai la joie d’être si populeuse, et le sujet de son orgueil sera pour elle une source de deuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 35, 'L’Éternel à la longue fera tomber le feu sur elle; et dans la suite des temps elle sera la demeure du démon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 36, 'Jérusalem, regarde à l’orient, et vois la bénédiction qui te vient de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 37, 'Voici que reviennent tes fils, ceux mêmes que tu as vus dispersés; ils reviennent après s’être rassemblés de l’aurore au couchant, à la parole du Saint, se réjouissant en la gloire de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Quitte, ô Jérusalem, ta tunique de deuil et d’affliction; revêts la beauté de la gloire divine pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Enveloppe-toi du double manteau de la justice qui te vient de Dieu; pose sur ta tête le diadème de la gloire de l’Éternel:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Car Dieu montrera ta splendeur à toute la terre qui est sous le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Dieu te nommera, durant tous les siècles: Paix de la justice, Gloire de la piété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Lève-toi, Jérusalem, tiens-toi la tête haute et regarde à l’Orient, et vois tes enfants rassemblés du couchant à l’aurore, à la parole du Saint, et se réjouissant au souvenir de Dieu!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Ils sont sortis de toi à pied, emmenés par des ennemis; mais Dieu te les ramène, portés avec gloire, comme le trône d’un empire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Dieu a commandé d’abaisser toutes les hautes montagnes et les collines éternelles, de combler les vallons, de niveler la terre, afin qu’Israël chemine avec sécurité, en la gloire de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Les forêts et tous les arbres odoriférants ont couvert Israël de leur ombre, par l’ordre de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Car Dieu conduira Israël réjoui à la lumière de sa gloire, avec la justice et la miséricorde qui viennent de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Comment cette ville, jadis pleine de peuple, est-elle assise solitaire? Elle est devenue comme une veuve celle qui avait grandi parmi les nations; la reine des provinces est assujettie au tribut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Elle pleure, elle a pleuré la nuit, et les larmes sont encore sur ses joues, et de tous ceux qui l’aimaient, il n’en est pas un qui la console; ses amis l’ont méprisée, et sont devenus ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'La fille de Juda s’est expatriée dans son humiliation et dans l’excès de sa servitude; elle s’est assise parmi les nations et n’y a point trouvé de repos; et tous ses persécuteurs l’ont prise au milieu de ses angoisses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Les voies de Sion pleurent, parce que nul ne vient plus à ses solennités; toutes ses portes sont en ruine; ses prêtres gémissent; ses vierges ont été emmenées; elle-même est pleine d’amertume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Les oppresseurs sont montés sur sa tête; ses ennemis prospèrent, parce que le Seigneur l’a humiliée, à cause de la multitude de ses péchés; ses jeunes gens sont partis en captivité, devant la face de l’oppresseur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Toute la beauté de la fille de Sion lui a été ravie; ses princes sont devenus comme des béliers qui ne trouvent point de pâturage; ils sont partis énervés devant la face des persécuteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'Jérusalem s’est souvenue de ses jours d’humiliation et de ses prévarications, et de tout ce que, depuis les anciens jours, elle avait accumulé de choses désirables, quand son peuple est tombé dans les mains de l’oppresseur; et nul n’était là pour la secourir, et ses ennemis l’ont raillée en la voyant captive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Jérusalem a grandement péché, c’est pourquoi elle est comme une mer agitée. Tous ceux qui l’honoraient l’ont affligée; car ils ont vu sa honte, et, en gémissant, elle s’est détournée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Son impureté est devant ses pieds, et elle ne s’est point souvenue de sa fin; mais elle a rabattu sa fierté; il n’est personne qui la console. Voyez, Seigneur, mon abaissement; voyez comme mon ennemi s’est glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'L’oppresseur a étendu la main sur tout ce qu’elle a de plus précieux; elle a vu les gentils entrer dans son sanctuaire; et pourtant vous aviez défendu qu’ils entrassent jamais dans son enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Tout son peuple gémissant cherche du pain; ils ont donné leurs choses les plus précieuses pour avoir des aliments, afin de ranimer leurs âmes. Voyez, Seigneur, considérez comme elle est tombée dans le mépris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'O vous tous qui passez par la voie, retournez-vous, et voyez s’il est une douleur semblable à la douleur qui m’est venue. Le Seigneur a parlé contre moi; il m’a humilié au jour de sa colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'De ses hautes demeures, il m’a lancé un feu, et il l’a fait entrer dans mes os. Il a déployé un filet sous mes pieds; il m’a ramenée en arrière; il m’a détruite et contristée durant tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Il a veillé sur toutes mes impiétés; elles ont enlacé mes mains; elles sont descendues autour de mon cou; il m’a ôté ma force; le Seigneur m’a chargé les mains de douleurs que je ne pourrai supporter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Le Seigneur a enlevé du milieu de moi tous mes forts; il a appelé le temps contre moi, pour broyer mes hommes d’élite; le Seigneur a foulé le pressoir de la vierge fille de Juda, et c’est pourquoi je pleure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Mes yeux fondent en larmes, parce que mon consolateur, celui qui ranimait mon âme, s’est éloigné de moi; mes fils ont péri; l’ennemi a prévalu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Sion a eu beau tendre la main, il n’est personne qui la console; le Seigneur a donné ses ordres contre Jacob; ses oppresseurs l’entourent; Jérusalem, au milieu d’eux, est comme une femme assise dans sa souillure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Le Seigneur est juste, car j’ai irrité sa bouche. Écoutez donc, ô peuples, et considérez ma douleur. Mes vierges et mes jeunes gens ont été emmenés captifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'J’ai appelé mes amants, et ils m’ont trompée; mes prêtres et mes anciens sont morts dans la ville; ils ont cherché des aliments pour ranimer leur âme, et ils n’en ont point trouvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Voyez, Seigneur, comme je suis affligée; mes entrailles sont troublées, mon cœur en moi-même est confondu, parce que je suis pleine d’amertume. Dans les rues, c’est le glaive qui m’a privée de mes enfants; dans ma maison, c’est la peste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Écoutez donc, je gémis, et il n’est personne qui me console; mes ennemis ont ouï parler de mes maux, et ils se sont réjouis, parce que c’est vous qui avez fait cela; mais vous avez amené le jour de la consolation; vous avez appelé le moment, et ils sont devenus semblables à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Que toute leur malice apparaisse devant votre face; grappillez en eux comme vous avez grappillé pour chacun de mes péchés; car mes sanglots redoublent, et mon cœur est contristé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Comment le Seigneur, dans sa colère, a-t-il obscurci la fille de Sion? Il a précipité du ciel sur la terre la gloire d’Israël; il a oublié l’escabelle de ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Au jour de sa colère, le Seigneur a submergé la gloire d’Israël, et il ne l’a pas épargnée; il a détruit, dans sa colère, toute la beauté de Jacob; il a souillé son roi et ses princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Dans sa colère, il a brisé tout le front d’Israël; il a détourné sa main droite de la face de l’ennemi, et il a allumé dans Jacob comme un feu flamboyant, et il a tout dévoré alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Il a tendu son arc, comme un ennemi menaçant; il a affermi sa main droite, comme un adversaire; et il a détruit tout ce qui la rendait belle à mes yeux; dans le tabernacle de la fille de Sion, il a répandu sa fureur, comme un fou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Le Seigneur est devenu comme un ennemi; il a submergé Israël; il a submergé ses édifices; il a renversé ses remparts, et il a multiplié les humiliations pour la ville de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Et il a jeté çà et là son tabernacle, comme une vigne qu’on arrache; il a détruit ses fêtes. Le Seigneur a oublié ce qu’il avait fait en Sion pour les fêtes et le sabbat; et il a transpercé des grondements de sa colère le roi, le prêtre et le prince.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Le Seigneur a répudié son autel, et il a ébranlé et renversé son sanctuaire; il a brisé, par la main de l’ennemi, les murs de son palais; des étrangers ont crié dans la maison du Seigneur, comme en un jour de fête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Et le Seigneur a résolu d’abattre le rempart de la fille de Sion; il a tendu le cordeau; il n’a point détourné sa main que tout ne fût broyé; et l’avant-mur a pleuré, et le rempart partout à la fois s’est senti défaillir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Ses portes se sont enfoncées dans le sol; il a détruit et mis en pièces ses verrous; il a banni son roi et ses princes parmi les nations; et ses prophètes n’ont pas eu de vision envoyée par le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Les vieillards de Sion se sont assis à terre; ils sont demeurés dans le silence; ils ont couvert de cendre leur tête; ils ont ceint des cilices; ils ont fait asseoir à terre les jeunes vierges de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Mes yeux se sont éteints dans les larmes, mon cœur est troublé, ma gloire s’est répandue à terre, à cause de l’affliction de la fille de mon peuple dans le temps que le petit enfant, et ceux encore à la mamelle, mouraient dans les rues de la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Ils disaient à leurs mères: Où est le pain, où est le vin? dans le temps que dans les rues de la ville ils tombaient défaillants, comme des blessés à mort, et qu’ils rendaient l’âme sur le sein de leurs mères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Quel témoignage puis-je te rendre? qui puis-je comparer à toi, fille de Jérusalem? Qui te sauvera, qui te consolera, vierge fille de Sion? Le calice de ton affliction s’est agrandi; qui te guérira?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Tes prophètes ont eu pour toi des visions vaines et folles, et ils ne t’ont point découvert ton iniquité, pour empêcher que tu ne sois captive, et ils ont eu pour toi des rêves de mensonge; ils t’ont vue poursuivant tes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Les passants, sur la voie, ont battu des mains; ils ont sifflé, ils ont secoué la tête sur la fille de Jérusalem. Ils ont dit: Est-ce là cette ville, couronne de joie sur toute la terre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Tous tes ennemis ont ouvert la bouche contre toi; ils ont sifflé et grincé des dents, et ils ont dit: Dévorons-la. Sans doute, voici le jour que nous attendions, nous l’avons trouvé, nous l’avons vu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Le Seigneur a fait ce qu’il avait résolu; il a accompli sa parole; il a fait les choses qu’il avait commandées depuis les anciens jours; il a tout détruit, il n’a rien épargné, et il a fait de toi la joie de ton ennemi; et il a relevé le front de ton oppresseur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Leur cœur a crié au Seigneur; remparts de Sion, versez nuit et jour des larmes par torrents; ne te donne pas de relâche; que la prunelle de tes yeux ne soit pas muette.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Lève-toi, réjouis-toi en Dieu; la nuit, pendant la première veille, épanche ton cœur, comme de l’eau, devant la face du Seigneur; élève vers lui les mains pour la vie de tes petits enfants, qui sont défaillants de faim à tous les coins de rue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Voyez, Seigneur, considérez à quel point vous nous avez vendangés. Des mères peuvent-elles manger le fruit de leurs entrailles? Jamais cuisinier a-t-il apprêté un bourgeon? Peut-on tuer des enfants à la mamelle? Peut-on, dans le sanctuaire, tuer le prêtre et le prophète?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'L’enfant et le vieillard sont gisants dans la rue; mes vierges et mes jeunes hommes ont été emmenés captifs; vous avez tout tué par le glaive et par la faim. Au jour de votre colère, vous avez tout massacré, et vous n’avez rien épargné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Le Seigneur a signalé un jour de fête pour tous mes ennemis d’alentour, le jour de sa colère; nul n’a été sauvé ni épargné, et c’est moi-même qui ai fortifié et multiplié tous mes ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Je suis l’homme qui voit sa misère, parce que la verge de la colère du Seigneur est sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Il m’a saisi et il m’a conduit dans les ténèbres, et non à la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Il n’a fait que tourner la main sur moi, durant tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Il a envieilli ma peau et ma chair; il a brisé mes os. Beth.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Il a bâti contre moi; il a entouré ma tête; il a travaillé à ma perte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Il m’a mis dans les ténèbres, comme les morts des siècles passés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Il a bâti contre moi, et je ne sortirai plus; il a appesanti mes fers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Et quand je crierais, quand je l’invoquerais, c’est en vain; il a clos ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Il a muré mes voies; il a barricadé mes sentiers; il les a confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Il est pour moi une ourse qui me guette, un lion dans son repaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Il m’a poursuivi, comme je me détournais; il m’a arrêté, il m’a effacé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Il a tendu son arc; il m’a fait tenir comme un but de flèches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Il a plongé dans mes reins les traits de son carquois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Je suis devenu la risée de tout mon peuple, le sujet de leurs chants, pendant tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Il m’a nourri d’amertume; il m’a enivré de fiel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Il m’a brisé les dents avec des cailloux; il m’a donné à manger de la cendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Il a banni la paix de mon âme; j’ai oublié toutes mes joies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Mes biens ont péri; mais mon espérance est dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Je me suis souvenu de ma misère; et, persécuté comme je suis, mon amertume et mon fiel');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Ne seront pas oubliés; et les méditations de mon âme se tourneront contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Je les enfermerai dans mon cœur, et à cause de cela je souffrirai avec patience.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 22, 'Car les miséricordes du Seigneur ne m’ont pas abandonné; sa compassion n’est pas épuisée; Seigneur, ayez pitié de nous de mois en mois, car nous n’avons point entièrement péri, et votre compassion n’est pas épuisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 23, 'Chaque matin apporte des grâces nouvelles, et votre fidélité en vos promesses est grande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 24, 'Món âme a dit: Le Seigneur est mon partage; à cause de cela, j’espérerai en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 25, 'Le Seigneur est bon pour ceux qui l’attendent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 26, 'C’est un bien pour l’âme de le chercher; elle patientera, elle attendra paisiblement le salut du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 27, 'Il est bon à l’homme d’être soumis au joug dès sa jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 28, 'Il se tiendra solitaire; et il se taira, parce qu’il l’aura porté sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 29, '30. Il tendra la joue à qui le frappe; il se rassasiera d’opprobre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 31, 'Parce que le Seigneur ne répudie pas pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 32, 'Si c’est lui qui a humilié, il aura compassion dans la plénitude de sa miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 33, 'Car ces paroles de colère ne sont pas selon son cœur, et ceux qu’il a abaissés sont des fils de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 34, 'Mettre sous ses pieds tous les captifs de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 35, 'Refuser justice à un homme devant le Très-Haut,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 36, 'Condamner un homme quand on doit le juger, le Seigneur ne l’a pas dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 37, 'Qui est celui qui a dit de telles choses, et a été obéi? Ce n’est pas le Seigneur qui les a commandées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 38, 'Le mal ne sortira pas de la bouche du Seigneur en même temps que le bien.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 39, 'Pourquoi murmure-t-il, l’homme vivant, l’homme qui songe à son péché?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 40, 'Votre voie a été examinée et recherchée, retournez au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 41, 'Élevons nos cœurs sur nos mains, vers le Très-Haut, dans le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 42, 'Nous avons péché, nous avons été impies, et vous ne nous avez point pardonné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 43, 'Vous avez gardé votre ressentiment, et vous nous avez poursuivis; vous avez tué, et vous n’avez rien épargné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 44, 'Vous vous êtes voilé d’une nuée pendant ma prière, pour ne plus me voir');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 45, 'Et pour me répudier;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 46, 'Tous nos ennemis ont ouvert la bouche contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 47, 'La crainte et la fureur, l’orgueil et la ruine sont venus en nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 48, 'Mon œil répandra des torrents de larmes sur la destruction de la fille de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 49, 'Mon œil s’est consumé; et je ne me tairai point, parce qu’il n’y aura point de repos pour moi');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 50, 'Avant que le Seigneur, du haut des cieux, se penche et regarde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 51, 'Mon œil ravagera mon âme, à la vue de toutes les filles de la cité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 52, 'Des oiseleurs m’ont fait la chasse comme à un passereau; ce sont tous ceux qui me haïssent sans raison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 53, 'Ils m’ont jeté dans une citerne pour m’ôter la vie, et ils en ont posé le couvercle sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 54, 'L’eau s’est répandue sur ma tête, et j’ai dit: Je suis perdu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 55, 'J’ai invoqué votre nom, ô Seigneur, du fond de la citerne;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 56, 'Vous avez entendu ma voix, et vous n’avez point fermé les oreilles à ma prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 57, 'Vous êtes venu à mon secours le jour où je vous avais invoqué, et vous m’avez dit: Ne crains pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 58, 'Seigneur, vous avez plaidé la cause de mon âme; vous avez racheté ma vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 59, 'Seigneur, vous avez vu mes troubles; vous m’avez rendu justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 60, 'Vous avez vu toute leur vengeance, tous leurs desseins sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 61, 'Vous avez entendu leurs outrages, et tous leurs desseins contre moi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 62, 'Et les lèvres de mes oppresseurs, et leurs complots tramés contre moi tout le jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 63, 'Soit qu’ils s’asseyent, soit qu’ils se lèvent, considérez leurs yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 64, 'Seigneur, vous les rétribuerez selon les œuvres de leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 65, 'Vous leur ferez expier votre protection et les peines de mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 66, 'Vous les poursuivrez en votre colère, et vous les ferez disparaître de dessous le ciel, ô Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Comment l’or s’est-il terni? Comment l’argent pur s’est-il changé? Comment les pierres saintes ont-elles été dispersées aux coins de toutes les rues?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Les fils de Sion les plus honorés, ceux que l’on prisait autant que l’or, comment ont-ils été traités comme des vases de terre, œuvre des mains du potier?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Les dragons eux-mêmes ont découvert leurs mamelles; et leurs petits ont allaité les filles de mon peuple, pour leur communiquer leur incurable instinct, comme l’autruche dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'La langue de l’enfant à la mamelle s’est collée à son palais dans sa soif; les enfants ont demandé du pain, et nul n’était là pour leur en distribuer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Ceux qui se nourrissaient de mets délicats ont péri dans les rues; ceux qu’on avait élevés dans la pourpre ont été enfouis dans le fumier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'L’iniquité de la fille de mon peuple a dépassé l’iniquité de Sodome, jadis renversée en un moment, sans que des hommes y aient fatigué leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Les Nazaréens étaient plus blancs que la neige, plus éclatants que le lait; ils étaient comme purifiés par le feu; leur poli était supérieur à celui du saphir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Et leur visage est devenu plus noir que la suie, on ne les reconnaît pas dans les rues; leur peau s’est collée sur leurs os; ils se sont desséchés comme du bois mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Les hommes tués par le glaive étaient plus beaux que les hommes morts de faim; car ceux-ci s’en étaient allés transpercés par la disette des fruits de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Les mains des femmes, naturellement compatissantes, ont fait cuire leurs propres enfants; elles s’en sont nourries dans la ruine de la fille de mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Le Seigneur a assouvi sa colère; il a répandu son indignation et ses fureurs, et il a allumé dans Sion un feu qui l’a dévorée jusqu’en ses fondements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Les rois de la terre, les peuples du monde entier ne croyaient pas qu’un ennemi, qu’un oppresseur pût entrer par les portes de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'À cause des péchés de ses prophètes, et des iniquités de ses prêtres, qui au milieu d’elle versaient le sang innocent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Les gardes ont chancelé dans les rues, ne pouvant éviter d’y marcher; ils se sont souillés de sang, et leurs robes y ont touché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Éloignez-vous des impurs; criez-leur: Retirez-vous, retirez-vous, ne nous touchez pas; car ceux que les impurs ont touché ont chancelé; dites aux nations: Ils n’habiteront plus parmi nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'La présence du Seigneur était leur partage; il ne les considérera plus; ils n’ont pas respecté le visage des prêtres; ils ont été sans miséricorde pour les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Quand nous vivions encore, nos yeux se sont lassés à vainement regarder, et à attendre du secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Nous nous sommes tournés vers une nation qui ne pouvait nous sauver; nous avons fait la chasse à nos petits enfants, de peur qu’ils ne sortissent dans les places publiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Notre temps est proche; nos jours sont remplis; le moment est arrivé; nos persécuteurs sont venus, plus agiles que l’aigle dans le ciel; ils se sont élancés des montagnes; ils nous ont tendu des pièges dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'L’esprit de notre face, le Christ Seigneur a été pris dans leurs filets, lui dont nous avons dit: Nous vivrons à son ombre parmi les nations!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Réjouis-toi, sois dans l’allégresse, fille de l’Idumée qui habite la terre; le calice du Seigneur passera aussi sur toi, tu t’enivreras, et tu vomiras ton ivresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Ton iniquité a cessé, fille de Sion; ta captivité touche à son terme; mais le Seigneur a visité ton iniquité, fille d’Édom, et il a mis tes impiétés à découvert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Souvenez-vous, Seigneur, de ce qui nous est advenu; regardez et voyez notre opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Notre héritage est passé à un autre peuple, et nos demeures à des étrangers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Nous sommes orphelins; notre père n’est plus; nos mères sont comme des veuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Nous avons bu de l’eau à prix d’argent; nous avons porté notre bois sur notre cou.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Nous avons été persécutés; nous avons travaillé et nous n’avons pas eu de relâche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'L’Égypte nous a donné la main, Assur aussi, mais pour leur propre intérêt.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Nos pères ont péché, ils ne sont plus; nous avons porté leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Des esclaves ont été nos maîtres, et il n’est pas de rédempteur pour nous tirer de leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Nous apporterons notre pain pour nourrir nos âmes en face des glaives du désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Notre peau a été brûlée comme un four; elle a été contractée par les orages de la faim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Ils ont outragé les femmes en Sion, et les vierges dans les villes de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Ils ont pendu de leurs mains les princes; ils n’ont point honoré les vieillards.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Les plus vaillants ont appris à pleurer, et les jeunes gens ont succombé sous le bois qu’ils portaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Et les vieillards ont cessé de siéger devant les portes; les plus habiles chanteurs ont cessé de chanter des psaumes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'La joie a défailli dans notre âme; nos chœurs de danse se sont changés en deuil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'La couronne est tombée de notre tête. Malheur à nous, parce que nous avons péché!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Et c’est pourquoi la douleur nous est venue; notre cœur a été contristé; nos yeux se sont couverts de ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Les renards courent sur la montagne de Sion, parce qu’elle est dépeuplée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Mais vous, Seigneur, vous demeurez dans tous les siècles; votre trône subsistera de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Pourquoi, dans quel but nous oublierez-vous? Nous abandonnerez-vous aussi longtemps que dureront les jours?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Revenez à nous, Seigneur, et nous reviendrons à vous, et renouvelez pour nous les jours d’autrefois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Quoique vous nous ayez répudiés et que vous soyez violemment irrité contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Copie de la lettre que Jérémie envoya aux captifs en Babylone, emmenés par le roi des Babyloniens; afin de leur dire ce qui lui avait été commandé par le Seigneur: À cause des péchés que vous avez commis devant Dieu, vous serez emmenés captifs à Babylone, par Nabuchodonosor, roi des Babyloniens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Étant donc entrés à Babylone, vous y serez beaucoup d’années; vous y serez longtemps, jusqu’à la septième génération. Mais après cela je vous en tirerai en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Maintenant vous allez voir, en Babylone, des dieux d’argent, d’or et de bois, que l’on porte sur les épaules, et qui inspirent la crainte aux gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Soyez donc attentifs à ne ressembler aucunement aux étrangers, et à ne vous pas laisser surprendre par la crainte des idoles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'En voyant devant et derrière elles la foule les adorer. Dites en pensée: C’est vous qu’il faut adorer, Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Car mon ange est avec vous, et c’est lui qui recherche vos âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Et la langue de ces idoles a été ciselée par un artiste, et elles sont elles-mêmes dorées ou argentées; mais elles sont mensongères et ne peuvent parler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Et, de même qu’avec de l’or on fait des parures pour une vierge,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'De même ils font des couronnes pour la tête de leurs dieux. Mais en réalité, lorsque les prêtres ont détourné de ces dieux l’or et l’argent, ils le prennent pour euxmêmes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Et ils en donnent même sous le toit des prostituées. Et ils parent leurs dieux d’argent, d’or et de bois, comme les hommes de vêtements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Mais ces dieux ne se préservent ni de la rouille ni des vers, quoique portant des manteaux de pourpre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Les prêtres leur essuient la figure à cause de la poussière du temple qui s’amasse sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Et l’idole a un sceptre, comme un homme, juge de la contrée, qui ne peut faire mourir celui qui l’offense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Elle a dans sa main droite un poignard et une hache; mais elle ne sauve elle-même ni de la guerre ni des voleurs. Par là elles rendent manifeste qu’elles ne sont point des dieux; ainsi n’ayez d’elles aucune crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Car tel est un vase brisé qui est inutile à l’homme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Tels sont leurs dieux placés dans leurs temples. Ils ont les yeux pleins de la poussière que soulèvent les pas des entrants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Leurs niches sont entourées de clôtures, comme un homme qui a offensé le roi; les prêtres fortifient leurs demeures comme le cachot d’un condamné à mort, avec des portes, des ferrures et des verrous, de peur que les voleurs ne les emportent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Ils allument pour elles des lampes, bien plus que pour eux-mêmes, et elles n’en peuvent voir aucune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Elles sont comme l’une des poutres de l’édifice; ils disent que des reptiles, sortant de terre, leur lèchent le cœur; et quand elles-mêmes ou leurs vêtements sont rongés, elles ne le sentent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Leur visage est noirci par la fumée du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Les hiboux, les hirondelles, les oiseaux voltigent autour de leur corps et de leur tête, et les chats viennent s’y poser;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Par là vous connaîtrez qu’elles ne sont point des dieux; ainsi n’ayez d’elles aucune crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Car si de l’or dont on les entoure pour les orner on n’avait pas soin d’ôter la rouille, elles ne brilleraient pas; et, lorsqu’on les fond, elles ne le sentent pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Ce sont des choses que l’on a achetées à tout prix, et elles n’ont point d’âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'On les porte sur les épaules, sans tenir compte de leurs pieds; on montre ainsi aux hommes leur propre honte, et leurs adorateurs sont pareillement confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Car si elles tombent à terre, ce n’est pas d’ellesmêmes qu’elles se relèveront; si personne ne les maintient droites, d’elles-mêmes elles chancelleront; et si personne ne les appuie, elles ne se tiendront pas debout; mais, comme à des morts, il faut leur présenter les dons qu’on leur fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Les prêtres, ayant sacrifié des victimes, les consomment, tandis que leurs femmes en salent une part, et ils n’en donnent rien aux pauvres ni aux infirmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'La femme dans sa souillure, et celle qui vient d’accoucher, touchent aux victimes. Reconnaissant par là que les idoles ne sont point des dieux, n’ayez d’elles aucune crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'D’où vient donc qu’on les appelle des dieux? C’est parce que des femmes font des offrandes à ces dieux d’or, d’argent et de bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Et les prêtres siègent en leurs temples, ayant des tuniques fendues, la tête et le menton rasés, et la tête découverte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 31, 'Et ils poussent des clameurs et des hurlements devant leurs dieux, comme on fait à un repas funèbre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 32, 'Les prêtres leur enlèvent une partie de leurs vêtements, et ils en habillent leurs enfants et leurs femmes; mais qu’on leur fasse du mal à elles-mêmes, elles n’en souffriront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 33, 'Qu’on leur fasse du bien, elles n’en pourront rien rendre; ce n’est pas elles qui pourront ni établir ni détrôner un roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 34, 'Pareillement, elles ne donneront ni richesse ni airain; si on leur a fait un vœu sans l’accomplir, elles ne feront point de recherches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 35, 'Elles ne sauveront pas un homme de la mort; elles ne tireront pas le faible des mains du puissant;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 36, 'Elles ne rendront point la vue à un aveugle; elles ne tireront pas un homme de la misère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 37, 'Elles n’auront point pitié de la veuve; elles ne soulageront pas l’orphelin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 38, 'Ces dieux de bois doré et argenté sont comme les pierres des montagnes, et leurs adorateurs seront confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 39, 'Comment donc peut-on les croire ou les appeler des dieux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 40, 'Les Chaldéens eux-mêmes aident à les déshonorer; quand ils voient un muet, ils le présentent à Bel, croyant qu’il va le faire parler, comme si lui-même avait le sentiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 41, 'Et quand ils comprendront que de tels dieux ne peuvent rien, ils les abandonneront comme des êtres privés de sentiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 42, 'Et les femmes, ceintes de cordes, s’assoient dans les voies après avoir offert du son.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 43, 'Et quand l’une d’elles, emmenée par un passant, dort avec lui, elle injurie sa voisine qui n’a pas été prisée autant qu’elle, et dont la corde n’a pas été rompue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 44, 'Tout ce que l’on fait pour ces dieux est mensonge; comment peut-on les croire et les appeler des dieux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 45, 'Ils sont l’œuvre des sculpteurs et des fondeurs d’or; ils ne sont pas autre chose que ce que les ouvriers ont pu les faire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 46, 'Ceux qui les ont fabriqués ne vivent pas longtemps: comment leurs œuvres seraient-elles durables?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 47, 'Ils ont laissé à leurs descendants l’imposture et l’opprobre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 48, 'Lorsque survient la guerre ou quelque désastre, les prêtres se demandent entre eux où ils se cacheront, eux et leurs idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 49, 'Comment se fait-il qu’ils ne comprennent pas que ce ne sont point des dieux, ceux qui ne se sauvent euxmêmes ni de la guerre ni des désastres?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 50, 'Puisqu’ils ne sont que bois doré ou argenté, on finira par reconnaître qu’ils ne sont que mensonge. Il sera manifeste pour toutes les nations et pour les rois que ce ne sont point des dieux, mais les œuvres de la main des hommes, et qu’il n’y a point là œuvre de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 51, 'Comment donc est-il reconnaissable que ce ne sont point des dieux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 52, 'C’est qu’ils n’élèveront pas un roi sur une province; ils ne donneront pas de la pluie aux humains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 53, 'Ils ne jugeront point par eux-mêmes; ils ne protégeront point contre l’injustice; car ils sont impuissants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 54, 'Ils sont comme des corneilles qui volent entre le ciel et la terre; car, lorsque le feu tombe sur la demeure de ces dieux de bois doré ou argenté, leurs prêtres fuient et se sauvent; mais les idoles brûlent en même temps que les solives intérieures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 55, 'Ils ne résisteront jamais à un roi ni à des ennemis en armes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 56, 'Comment donc peut-on les croire des dieux, et les accepter comme tels? Des dieux de bois doré ou argenté ne se sauveront jamais des brigands ou des voleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 57, 'Ceux-ci, étant les plus forts, enlèveront les lames d’or et d’argent, et les manteaux dont ils sont revêtus; ils s’en iront avec ce butin, et les dieux ne se porteront pas secours à eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 58, 'C’est pourquoi il vaut mieux être un roi qui montre lui-même sa valeur, ou dans une maison un vase utile dont le maître se sert, que l’un de ces faux dieux; mieux vaut encore la porte de la maison qui préserve les choses renfermées dans l’intérieur, ou la colonne de bois d’un palais, que l’un de ces faux dieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 59, 'Car le soleil, la lune, les étoiles au moins brillent, ils ont été créés pour être utiles, et ils obéissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 60, 'De même les éclairs, lorsqu’ils apparaissent, frappent tous les regards. De même le vent souffle à la fois en toute contrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 61, 'Et les nuées, lorsque Dieu leur commande de passer sur toute la terre, font ce qui leur est prescrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 62, 'Le feu lancé d’en haut pour détruire les monts et les forêts exécute l’ordre qui lui est donné. Or ces choses, ni par leurs beautés, ni par leurs vertus, ne sont point comparables aux idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 63, 'Par là, on sait qu’il ne faut ni croire aux idoles, ni les appeler des dieux; puisqu’elles n’ont le pouvoir ni de rendre justice, ni de faire du bien aux hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 64, 'Sachant donc que ce ne sont point des dieux, n’ayez d’elles aucune crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 65, 'Elles ne règneront pas; elles ne maudiront pas; elles ne béniront pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 66, 'Elles ne montreront point aux nations des signes dans le ciel; elles ne brilleront pas comme le soleil; elles n’éclaireront pas comme la lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 67, 'Les bêtes valent mieux qu’elles; celles-là, une fois réfugiées dans leur tanière, peuvent se servir elles-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 68, 'Mais de toute façon il est manifeste que ce ne sont pas des dieux; ainsi n’ayez d’elles aucune crainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 69, 'Ces dieux de bois et d’argent sont comme un épouvantail dans un champ de concombres, qu’il ne garde nullement;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 70, 'Ils sont encore comme dans un verger le néprun sur lequel chaque oiseau se perche. Ces dieux de bois doré et argenté sont comme un mort tombé dans les ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 71, 'On reconnaîtra que ce ne sont point des dieux à la vétusté de leur pourpre, et à l’éclat terni de leurs vêtements; eux-mêmes plus tard seront rongés, et en tout pays ils seront un sujet d’outrage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 72, 'L’homme juste qui n’a point d’idoles vaut donc mieux; car il sera toujours à l’abri de toute confusion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 73, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Et il arriva que, en ma trentième année, le quatrième mois, le cinquième jour du mois, j’étais assis au milieu des captifs, sur le fleuve Chobar; et les cieux furent ouverts, et j’eus les visions de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Le cinquième jour de ce mois, en cette année, la cinquième de la captivité du roi Joakim,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'La parole du Seigneur vint à Ézéchiel, fils de Buzi, le prêtre, en la terre des Chaldéens, sur le fleuve Chobar. Et la main du Seigneur fut sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Et je vis, et voilà qu’un vent violent vint de l’aquilon, et avec lui une grande nuée, et tout alentour une lueur et un feu brillant, et, au milieu, comme une vision d’émail au milieu du feu, et cet émail était lumineux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Et au milieu du feu il y avait comme la ressemblance de quatre animaux, et voici leur aspect: il y avait en eux la ressemblance d’un homme;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Et à chacun quatre faces, et à chacun quatre ailes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Et leurs jambes étaient droites, et leurs pieds ailés; et ils lançaient des étincelles, comme de l’airain brillant. Et leurs ailes étaient légères,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Et il y avait une main d’homme sous leurs ailes, aux quatre côtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Et les faces de ces quatre animaux ne se retournaient pas, quand ils marchaient; ils allaient chacun droit devant sa face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Et voici la ressemblance de leurs faces: une face d’homme et une face de lion à droite des quatre, une face de veau à gauche des quatre, et une face d’aigle aux quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Et quatre ailes étaient étendues au-dessus d’eux; deux de ces ailes les joignaient l’un à l’autre, et deux couvraient leur corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Et chacun marchait droit en avant; où le vent allait, ils allaient, et ils ne se retournaient pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Et au milieu des animaux, il y avait comme une vision de charbons en feu, comme une vision de lampes courant ensemble entre les animaux, et une flamme éclatante, et de la flamme sortaient des éclairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'Et je vis, et voilà qu’il y avait une roue sur la terre auprès des quatre animaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Et l’aspect des roues était comme l’aspect de Tharsis, et toutes les quatre étaient semblables. Et elles étaient faites comme s’il y avait eu une roue dans une roue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Et elles allaient sur leurs quatre parties, et elles ne se retournaient pas en marchant,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Ni elles ni leurs moyeux; et elles étaient hautes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Et quand les animaux marchaient, les quatre roues à côté d’eux marchaient, et quand les animaux s’élevaient au-dessus de terre, les roues s’élevaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Et partout où était la nuée, là aussi le vent soufflait; et les roues marchaient et s’élevaient avec les animaux; car un souffle de vie était dans les roues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Quand les animaux marchaient, elles marchaient; quand ils s’arrêtaient, elles s’arrêtaient, et quand ils s’élevaient au-dessus de la terre, elles s’élevaient avec eux; car un souffle de vie était dans les roues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Et au-dessus de la tête des animaux il y avait une image comme celle d’un firmament, semblable à du cristal, qui s’étendait au-dessus de leurs ailes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Et, au-dessus du firmament, leurs ailes étaient étendues, battant l’une contre l’autre, et celles de dessous couvrant leurs corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Et j’entendis le bruit de leurs ailes pendant qu’ils marchaient, comme la voix des grandes eaux; et quand ils s’arrêtaient, leurs ailes se reposaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Et voilà qu’une voix sortit du firmament qui était au-dessus de leurs têtes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Et qui ressemblait à un saphir, et qui supportait l’image d’un trône, sur lequel était une image semblable à un homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Et je vis comme une vision d’émail, depuis ses reins jusqu’en haut; et depuis ses reins jusqu’en bas je vis une vision de feu, et sa lueur formait un cercle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Semblable à l’arc qui est dans la nuée les jours de pluie; telle était la forme de cette lueur en cercle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'C’est ainsi que je vis l’image de la gloire du Seigneur; je la vis, et je tombai la face contre terre, et j’entendis la voix d’un esprit qui parlait, et il me dit: Fils de l’homme, tiens-toi sur tes pieds, et je te parlerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Et un esprit vint en moi; il me prit et il me releva, et m’affermit sur mes pieds, et je l’entendis qui me parlait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Et il me dit: Fils de l’homme, je t’envoie en la maison d’Israël qui m’irrite; car ils m’ont irrité, eux et leurs pères, jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Et tu leur diras: Voici ce que dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Peut-être écouteront-ils et auront-ils peur, car c’est une maison qui m’irrite; peut-être ils connaîtront que tu es un prophète au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Pour toi, fils de l’homme, ne les crains pas, ne sois point intimidé devant leur face; car ils se mettront en fureur, et ils t’assiégeront de toutes parts, et tu demeureras au milieu des scorpions; mais ne crains pas leurs discours, ne sois pas intimidé devant leur face; car c’est une maison qui m’irrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Et tu leur répéteras mes paroles; peut-être écouteront-ils et auront-ils peur; car c’est une maison qui m’irrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Et toi, fils de l’homme, obéis à celui qui te parle; ne sois pas irritant comme cette maison qui m’irrite. Ouvre la bouche, et mange ce que je te donne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Et je vis, et voilà qu’une main était étendue vers moi, et elle tenait le rouleau d’un livre, et elle le déroula devant moi, et il y avait des lettres des deux côtés des pages, et il y était écrit: Une lamentation, un chant de deuil, et des hélas!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Et l’esprit me dit: Fils de l’homme, mange ce rouleau et pars, et parle aux fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Et il m’ouvrit la bouche, et il me fit manger le rouleau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Et il me dit: Fils de l’homme, ta bouche mangera, et tes entrailles seront rassasiées de ce rouleau qui t’est donné. Et je le mangeai, et il fut à ma bouche comme du miel le plus doux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Et l’esprit me dit: Fils de l’homme, pars et va trouver la maison d’Israël, et répète-leur mes paroles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Car c’est à la maison d’Israël que je t’envoie, et non à un peuple qui parle une langue inconnue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Ni à maintes nations parlant d’autres langues, des langues étrangères, difficiles, inintelligibles pour toi; et quand même je t’aurais envoyé à de tels peuples, ils t’écouteraient encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Mais la maison d’Israël ne voudra pas t’écouter; car ils ne veulent pas m’écouter moi-même, parce que toute la maison d’Israël est opiniâtre et a le cœur endurci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Et voilà que j’ai fait ta face puissante devant leurs faces, et j’affermirai en toi un pouvoir plus fort que leur pouvoir,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Et qui sera toujours plus ferme qu’un rocher. Ne les crains pas, ne tremble pas devant leur visage; car c’est une maison qui m’irrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Et l’esprit me dit: Fils de l’homme, toutes les paroles que je t’ai dites, reçois-les dans ton cœur, entends-les de tes oreilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Et pars, va parmi les captifs près des fils de mon peuple; parle-leur et dis: Voici ce que dit le Seigneur; pour voir si par hasard ils t’écouteront, si par hasard ils rentreront en eux-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Et l’esprit me saisit, et j’entendis derrière moi une voix, comme le bruit d’un grand tremblement de terre, disant: Bénie soit la gloire du Seigneur du lieu où il réside.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Et je recueillis le bruit des ailes des quatre animaux ailés, battant l’une contre l’autre, et la voix semblable à un tremblement de terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Et l’esprit me souleva, et il me ravit, et je m’en allai soulevé par l’impulsion de mon propre esprit, et la main puissante du Seigneur était sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Et je traversai l’air, et j’arrivai parmi les captifs, et je parcourus les demeures de ceux qui étaient sur le fleuve Chobar. Et je restai là sept jours, allant et venant au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Et après sept jours la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Fils de l’homme, je t’ai mis en sentinelle parmi la maison d’Israël, et tu entendras la parole de ma bouche, et tu les menaceras en mon nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Quand tu diras de ma part à l’impie: Tu mourras de mort; si tu ne lui enjoins pas de faire effort sur luimême pour se détourner de ses voies afin qu’il vive, cet impie mourra dans son iniquité, et je réclamerai son sang de ta main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Mais si tu as averti l’impie, et qu’il ne se soit détourné ni de son impiété ni de sa voie, cet impie mourra dans son iniquité, et toi tu auras sauvé ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Et quand le juste se détournera de la justice et fera une faute, je lui mettrai le châtiment devant la face; et il mourra parce que tu ne l’auras point averti; et il mourra dans ses péchés; car je ne garderai plus la mémoire de ses actes de justice, et je réclamerai son sang de ta main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Mais si tu as enjoint au juste de ne pas pécher, et s’il ne pèche plus, le juste vivra, parce que tu l’auras averti, et toi tu auras sauvé ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Et la main du Seigneur vint sur moi, et il me dit: Lève-toi, et sors dans la plaine, et là il te sera parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Et je me levai et je sortis dans la plaine, et voilà que la gloire du Seigneur s’y tenait, pareille à la vision et à la gloire du Seigneur que j’avais vue sur le fleuve Chobar. Et je tombai la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Et un esprit vint en moi, et il me remit sur mes pieds, et il parla et me dit: Rentre, et enferme-toi au milieu de ta maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Et toi, fils de l’homme, voilà que des chaînes sont préparées pour toi, et ils te chargeront de ces chaînes, et tu n’en sortiras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 26, 'Et je te nouerai la langue, et tu seras muet, et tu ne seras plus pour eux un reproche vivant; car c’est une maison qui m’irrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 27, 'Mais quand je t’aurai parlé, je t’ouvrirai la bouche et tu leur diras: Voilà ce que dit le Seigneur: Que celui qui veut écouter écoute; que celui qui veut désobéir désobéisse; car c’est une maison qui m’irrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Et toi, fils de l’homme, prends une brique, et tu la placeras devant toi, et tu dessineras sur cette brique la ville de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Et tu y représenteras un siège, et tu bâtiras des ouvrages contre elle, et tu l’entoureras de palissades, et tu établiras des camps devant elle, et tu dresseras des balistes autour de son enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Prends ensuite pour toi-même une poêle de fer; puis tu en feras un mur de fer, que tu placeras entre toi et la ville; et tu tourneras ton visage contre la ville, et elle sera assiégée, et tu l’assiègeras; or ceci est un signe pour les enfants d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Et tu te coucheras sur le côté gauche, et tu mettras sur ce côté les iniquités de la maison d’Israël, au nombre de cent cinquante, égal à celui des jours où tu te seras couché sur ce côté, et tu porteras leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Et je t’ai chargé de leurs iniquités pour un nombre de cent quatre-vingt-dix jours, et tu porteras les iniquités de la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Et tu accompliras ce que j’ai dit d’abord; puis tu te coucheras sur le côté droit, et tu prendras les iniquités de la maison d’Israël, quarante jours; je te donne un jour pour une année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Et tu tourneras le visage vers le siège de Jérusalem, et tu fortifieras ton bras, et tu prophétiseras contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Et voilà que je t’ai préparé des chaînes, et tu ne');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Prends encore pour toi du froment, de l’orge, des fèves, des lentilles, du millet, de l’épeautre, et jette le tout dans un pot de terre; tu en feras ensuite des pains, pour autant de jours que tu dois dormir sur le côté, et tu en mangeras pendant cent quatre-vingt-dix jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Et tu pèseras tes aliments, et tu en mangeras vingt-six sicles par jour, et tu les mangeras par intervalles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Et tu boiras de l’eau à la mesure; tu boiras par in tervalle, le sixième du hin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Et tu les mangeras comme des galettes d’orge, cuites sous la cendre, et tu les feras cuire sous la cendre d’un feu de mottes d’excréments humains, aux yeux de tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Et tu diras: Ainsi parle le Seigneur Dieu d’Israël. Ainsi les fils d’Israël mangeront des choses impures parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Et je dis Que cela ne soit pas, Seigneur Dieu d’Israël; car jamais mon âme n’a été souillée de choses impures depuis ma naissance jusqu’à ce jour, je n’ai point mangé de corps morts ni de bêtes déchirées par des bêtes, et jamais chair corrompue n’est entrée dans ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Et le Seigneur me dit: Voilà que je t’accorde des mottes de bouse de vache au lieu de mottes d’excréments humains, et tu prépareras tes pains sur ces mottes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Et il me dit: Fils de l’homme, voilà que je vais briser dans Jérusalem le soutien du pain, et ils le man');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'C’est au point qu’ils manqueront de pain et d’eau, et le frère tombera mort dans les bras de son frère, et ils se consumeront dans leurs iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 1, 'Et toi, fils de l’homme, prends avec toi un glaive plus tranchant que le rasoir d’un barbier; achète-le pour toi, et passe-le sur ta tête et sur ton menton; tu prendras ensuite des poids et une balance; puis tu sépareras ta barbe et tes cheveux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 2, 'Tu en brûleras dans le feu `un quart, au milieu de la ville, pendant que s’accompliront les jours du siège; tu en prendras un autre quart pour le brûler dans son enceinte; puis, avec le glaive, tu couperas le troisième quart autour de ses murailles; enfin tu jetteras au vent le dernier quart, que je poursuivrai à coups d’épée nue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 3, 'Et tu prendras quelque peu de poils, et tu les attacheras au bord de ton manteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 4, 'Et tu en prendras encore, et tu les jetteras au milieu du feu, et tu les brûleras dans le feu; il en sortira une flamme, et tu diras à toute la maison d’Israël:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 5, 'Voici ce que dit le Seigneur: C’est là Jérusalem; je l’ai placée, elle et son territoire, au milieu des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 6, 'Et tu diras mes ordonnances à cette ville coupable');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 7, 'À cause de cela, voici ce que dit le Seigneur: En punition de ce que les nations qui vous entourent ont été pour vous une occasion de péché; de ce que vous n’avez point cheminé selon mes préceptes, que vous n’avez point exécuté mes lois, mais que vous avez suivi celles des nations qui vous entourent;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 8, 'À cause de cela, ainsi parle le Seigneur: Voilà que je suis contre toi, et au milieu de toi j’exécuterai mon jugement devant les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 9, 'Et je ferai en toi des choses que je n’ai jamais faites, et telles que je n’en ferai jamais de semblables pour punir toutes tes abominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 10, 'À cause de cela, les pères mangeront leurs enfants au milieu de toi, et les enfants mangeront leurs pères; et j’exécuterai en toi mon jugement, et je disperserai tes restes à tous les vents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 11, 'À cause de cela, par ma vie, dit le Seigneur, en punition de ce que par toutes tes abominations tu as souillé mes choses saintes, je te répudierai; et mon œil sera sans pitié, et moi je serai sans miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 12, 'Le quart des tiens périra par la peste; le quart périra par la famine au milieu de toi; le quart sera jeté par moi à tous les vents; le quart périra autour de toi par le glaive; et je les poursuivrai à coups d’épée nue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 13, 'Et ma colère et ma fureur s’assouvira contre eux, et tu connaîtras que moi, le Seigneur, j’ai parlé dans ma jalousie, pendant que j’assouvissais ma colère contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 14, 'Et à la vue de tous les passants, je ferai un désert de toi et de tes filles qui entourent ton enceinte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 15, 'Et tu seras gémissante et digne de pitié au milieu des nations qui t’entourent, pendant que j’exécuterai sur toi mon jugement en me vengeant de toi selon ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 16, 'Moi, le Seigneur, j’ai parlé, et quand je lancerai contre eux les traits de la faim, ils seront en défaillance, et je briserai le soutien de leur pain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 17, 'Et j’enverrai contre toi la famine et les bêtes farouches, et je me vengerai de toi, et la peste et le sang passeront sur toi, et je promènerai sur toi le glaive autour de ton enceinte. Moi, le Seigneur, j’ai parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 2, 'Fils de l’homme, tourne la face contre les monts d’Israël, et prophétise contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 3, 'Et dis-leur: Montagnes d’Israël, écoutez la parole du Seigneur. Ainsi dit le Seigneur aux montagnes, aux collines, aux vallons et aux forêts: Voilà que j’amène contre vous le glaive, et vos hauts lieux seront détruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 4, 'Et vos autels seront brisés, et vos enclos détruits; et je jetterai vos cadavres en face de vos idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 5, 'Et je disperserai vos ossements autour de vos autels,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 6, 'Et dans toutes vos demeures. Vos villes seront dépeuplées et vos hauts lieux abolis, afin que vos autels soient abattus, vos idoles brisées et vos enclos détruits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 7, 'Et les cadavres tomberont au milieu de vous, et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 8, 'Quand ceux de vous qui auront échappé au glaive seront parmi les nations, pendant votre dispersion dans les royaumes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 9, 'Ceux de vous qui auront échappé et qui seront captifs parmi les nations se souviendront de moi. J’ai juré contre leur cœur, qui s’est prostitué loin de moi, contre leurs yeux, qui se sont prostitués à leurs désirs. Et ils se frapperont au visage en souvenir de toutes leurs abominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 10, 'Et ils reconnaîtront que moi, le Seigneur, j’ai parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 11, 'Voici ce que dit le Seigneur: Bats des mains, frappe du pied, et dis: Malheur, malheur sur toutes les abominations de la maison d’Israël! Ils périront par le glaive, par la peste et par la famine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 12, 'Celui qui est près tombera sous le glaive; celui qui est loin périra par la peste; et celui qui est assiégé mourra de faim. Et j’assouvirai sur eux ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 13, 'Et vous saurez que je suis le Seigneur, quand vos cadavres seront au milieu de vos idoles, autour de vos autels sur toute haute colline, sous chaque arbre touffu, où ils offraient les odeurs de l’encens à toutes leurs idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 14, 'Et j’étendrai la main sur eux, et je désolerai la terre, et je la ruinerai dans toutes ses demeures à partir du désert de Déblatha. Et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 1, 'Et la parole du Seigneur vint à moi, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 2, 'Et toi, fils de l’homme, dis: Voici ce que dit le Seigneur La fin est venue pour la terre d’Israël; elle est venue sur les quatre ailes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 3, 'La fin est venue pour toi, habitant de la terre; le temps est venu, le jour est proche; il est venu sans troubles et sans douleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 4, '(8.) Maintenant, à portée de ma main, je répandrai sur toi ma colère, j’assouvirai sur toi ma fureur, et je te jugerai pour tes voies, et je te rétribuerai pour toutes tes abominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 5, '(9.) Mon œil sera sans pitié, et je serai sans miséricorde; car je te rétribuerai selon tes voies, et tes abominations seront au milieu de toi; et tu sauras que je suis le Seigneur, et que c’est moi qui te frappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 6, '(3.) Maintenant ta fin est proche; et j’enverrai mon jugement contre toi, et je te punirai dans tes voies, et je te rétribuerai pour toutes tes abominations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 7, '(4.) Mon œil sera sans pitié, et je serai sans miséricorde; car je te rétribuerai pour tes voies, et tes abominations seront au milieu de toi, et tu sauras que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 8, '(5.) Car ainsi dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 9, '(10.) Voilà que la fin est venue, voilà le jour du Seigneur, puisque la verge a fleuri et que l’orgueil a germé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 10, '(11.) Et le Seigneur brisera la force de l’impie, et cela sans trouble et sans hâte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 11, '(12.) Le temps est venu, voilà le jour. Que l’acheteur ne se réjouisse pas, que le vendeur ne se lamente pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 12, '(13.) Car l’acheteur ne retournera pas vers le vendeur, et l’homme ne prévaudra pas avec l’œil de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 14, 'Sonnez de la trompette, et choisissez entre toutes ces choses:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 15, 'La guerre au dehors avec le glaive, la famine et la peste au dedans; celui qui est aux champs périra par le glaive; ceux qui seront dans la ville, la famine et la peste les consumeront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 16, 'Et parmi eux, ceux qui se seront enfuis seront sauvés, et ils resteront dans les montagnes. Mais les autres, je les tuerai, chacun dans son iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 17, 'Toute main sera défaillante, toute jambe souillée d’humeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 18, 'Et ils ceindront des cilices, et l’effroi les couvrira; et tout visage sera confondu, et toute tête sera chauve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 19, 'On jettera leur argent dans les rues, on méprisera leur or; et leurs âmes n’en seront pas assouvies, et leurs entrailles n’en seront point rassasiées; car le châtiment de leurs iniquités est venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 20, 'Leurs ornements les plus précieux, ils s’en sont servis pour satisfaire leur orgueil; ils en ont fait les images de leurs abominations. C’est pourquoi je les regarde comme choses impures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 21, 'Et je les livrerai aux mains des étrangers, pour les mettre au pillage, et aux fléaux de la terre, pour en être la proie; et on les tiendra choses impures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 22, 'Et je détournerai de ces hommes mon visage; et ils profaneront le lieu de mon repos, et ils y entreront avec insolence, et ils le profaneront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 23, 'Et ils le bouleverseront; car la terre est pleine d’étrangers, et la ville pleine d’iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 24, 'Et je ferai taire les rugissements de leur force; et leurs choses saintes seront souillées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 25, 'Et l’expiation viendra, et chacun cherchera la paix, et il n’y en aura point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 26, 'Et il y aura malheur sur malheur, message sur message; on cherchera quelque vision de prophète, et la loi périra par le prêtre, et le conseil par les anciens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 27, 'Le prince se revêtira de désolation; les mains du peuple seront paralysées. Je les traiterai selon leurs voies, et je les punirai selon leurs jugements, et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 1, 'En la huitième année, le cinquième mois, le cinquième jour du mois, j’étais assis dans ma maison, et les anciens de Juda étaient assis devant moi. Et sur moi vint la main du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 2, 'Et je regardais, et je vis l’image d’un homme; au-dessus des reins, il était feu; au-dessous des reins, il était comme une vision d’émail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 3, 'Et il étendit l’image d’une main, et il me prit par les cheveux, et l’esprit me ravit entre le ciel et la terre, et il me conduisit à Jérusalem, en une vision de Dieu, sur le vestibule de la porte qui regarde l’aquilon, où était la colonne de l’acheteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 4, 'Et voilà qu’il y avait la gloire de Dieu, semblable à la vision que j’avais eue dans le champ.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 5, 'Et le Seigneur me dit: Fils de l’homme, tourne tes yeux du côté de l’aquilon. Et je tournai les yeux du côté de l’aquilon; et voilà que de là je regardai à la porte orientale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 6, 'Et le Seigneur me dit: Fils de l’homme, as-tu vu ce qu’ils font? Ils commettent ici de grandes abominations, telles qu’ils me font partir de mon sanctuaire; mais tu verras des iniquités plus grandes encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 7, 'Et il me conduisit sur le vestibule du parvis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 8, 'Et il me dit: Fils de l’homme, creuse; et je creusai; et voilà qu’il y avait une porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 9, 'Et il me dit Entre, et vois les iniquités qu’ils commettent ici;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 10, 'Et j’entrai, et je regardai, et voilà qu’il y avait des vanités, des abominations, et toutes les idoles de la maison d’Israël dessinées sur les murs tout autour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 11, 'Et il y avait soixante-dix hommes des anciens de la maison d’Israël; et au milieu Jéchonias, fils de Saphan, se tenait debout devant eux, et chacun tenait à la main un encensoir, et la fumée de l’encens s’élevait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 12, 'Et le Seigneur me dit: Tu as vu, fils de l’homme, ce que font les anciens de la maison d’Israël, chacun dans sa chambre la plus secrète, parce qu’ils ont dit: Le Seigneur ne nous voit pas; le Seigneur a délaissé la terre!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 13, 'Et il me dit: Tu verras des iniquités encore plus grandes que celles-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 14, 'Et il me conduisit sur le vestibule de la porte du temple qui regarde l’aquilon, et voilà qu’il y avait là des femmes assises qui pleuraient Thammuz.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 15, 'Et le Seigneur me dit: Fils de l’homme, tu as vu');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 16, 'Et il me conduisit dans le parvis intérieur du');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 17, 'Et il me dit: Tu as vù, fils de l’homme est-ce peu pour la maison de Juda, de commettre les abominations qu’ils ont commises ici; car ils ont rempli d’iniquités la terre? Et voilà qu’ils sont comme des railleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 18, 'Et moi je les traiterai avec colère, et mon œil sera sans pitié, et je serai sans miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 1, 'Et d’une grande voix il cria à mes oreilles, disant: Le jugement de la ville est proche, et chacun a dans la main un instrument de destruction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 2, 'Et voilà que six hommes vinrent par la porte haute qui regarde l’aquilon, et chacun avait à la main une hache. Et au milieu d’eux il y avait un homme vêtu d’une robe traînante, avec une ceinture de saphirs autour des reins; et ils entrèrent, et ils s’arrêtèrent vers l’autel d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 3, 'Et la gloire du Dieu d’Israël s’élevant, portée par des chérubins, alla au portique du temple; puis elle appela l’homme vêtu d’une longue robe, qui avait une ceinture sur les reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 4, 'Et le Seigneur lui dit: Traverse Jérusalem, et marque au front les hommes qui gémissent et pleurent sur toutes les iniquités qui se sont faites au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 5, 'Et il dit aux six hommes pendant que je l’écoutais: Allez derrière lui dans la cité, et que vos yeux soient sans pitié, et vous, soyez sans miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 6, 'Tuez, exterminez le vieillard, le jeune homme et la vierge, les enfants et les femmes; mais n’attaquez point ceux qui auront la marque, et commencez par mon sanctuaire. Ils commencèrent donc par les vieillards qui étaient dans le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 7, 'Et le Seigneur dit aux six hommes: Souillez le temple; allez et remplissez les parvis de cadavres, et frappez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 8, 'Et pendant qu’ils frappaient, je tombai la face contre terre, et je dis: Hélas! Seigneur, détruisez-vous les restes d’Israël, en répandant votre colère sur Jérusalem?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 9, 'Et il me dit: L’iniquité de la maison d’Israël et de Juda a beaucoup, beaucoup grandi, parce que la terre regorge d’étrangers, et que la ville regorge de crimes et d’impuretés; car ils ont dit: Le Seigneur a délaissé la terre, le Seigneur ne nous voit pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 10, 'Et mon œil sera sans pitié, et je serai sans miséricorde, et je fais retomber leurs voies sur leurs têtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 11, 'Et l’homme revêtu d’une robe traînante, avec une ceinture sur les reins, prit la parole, et dit: J’ai fait ce que vous m’avez commandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 1, 'Et je regardai, et voilà que sur le firmament, qui était au-dessus de la tête des chérubins, il y avait comme un saphir, image d’un trône au-dessus d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 2, 'Et le Seigneur dit à l’homme revêtu d’une longue');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 3, 'Et quand l’homme y entra, les chérubins étaient à droite dans le temple, et une nuée remplit le parvis intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 4, 'Alors la gloire du Seigneur s’éleva, et des chérubins passa au portique du temple, et la nuée remplit le temple; et le parvis était rempli des rayons de la gloire du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 5, 'Et le bruit des ailes des chérubins s’entendit jusqu’au parvis extérieur, semblable à la voix du Dieu toutpuissant quand il parle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 6, 'Et ceci advint pendant que le Seigneur donnait ses ordres à l’homme revêtu de la robe sainte, disant: Prends du feu au milieu des roues, parmi les chérubins; l’homme entra et s’arrêta près des roues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 7, 'Et le Seigneur étendit la main sur le feu qui était parmi les chérubins, et il en prit, et il en remplit les mains de l’homme qui était revêtu de la robe sainte; et celui-ci le prit, et il sortit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 8, 'Et je vis les chérubins ayant l’image d’une main d’homme sur leurs ailes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 9, 'Et je vis, et voilà que les quatre roues étaient arrêtées près des chérubins; chaque roue touchait un chérubin, et l’aspect des roues était comme l’aspect d’une escarboucle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 10, 'Et, quant à leur aspect; elles avaient toutes les quatre le même aspect, c’était comme si une roue était au milieu d’une roue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 11, 'Lorsqu’elles allaient, elles allaient de leurs quatre parties, et en allant elles ne se retournaient pas; quel que fut le lieu qu’avait regardé la première tête, elles y allaient, et, en allant, elles ne se retournaient pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 12, 'Et leurs moyeux, leurs mains, leurs ailes et leurs bandes étaient pleins d’yeux, tout alentour aux quatre roues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 13, 'Et tandis que j’écoutais, le nom de Gelgel fut donné aux quatre roues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 15, 'Et les chérubins étaient ces mêmes créatures vivantes que j’avais vues sur le fleuve Chobar.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 16, 'Et quand les chérubins allaient, les roues allaient, et elles étaient tout près d’eux; et quand les chérubins étendaient les ailes pour s’élever au-dessus de terre, les roues ne se détournaient point d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 17, 'Et quand ils s’arrêtaient, elles s’arrêtaient; et quand ils s’élevaient, elles s’élevaient avec eux, parce qu’il y avait en elles un esprit de vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 18, 'Et la gloire du Seigneur sortit du temple, et alla sur les chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 19, 'Et les chérubins déployèrent leurs ailes, et ils planèrent au-dessus de terre devant moi; lorsqu’ils partirent, les roues étaient toujours auprès d’eux, et ils s’arrêtèrent sur le vestibule de la façade du temple du Seigneur; et la gloire du Dieu d’Israël était sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 20, 'Et c’étaient les créatures vivantes que j’avais vues au-dessous du Dieu d’Israël, vers le fleuve de Chobar, et je reconnus que c’étaient des chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 21, 'Chacun avait quatre faces et huit ailes, et sous les ailes l’image d’une main d’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 22, 'Et leurs visages se ressemblaient, et c’étaient les visages que j’avais vus sous la gloire du Dieu d’Israël, vers le fleuve Chobar, et chacun marchait droit devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 1, 'Et l’esprit me ravit, et il me conduisit sur la porte de la façade du temple du Seigneur, celle qui regarde l’Orient. Et voilà qu’il y avait sur le portique environ vingt-cinq hommes, et je vis au milieu d’eux Jéchonias, fils d’Ezer, et Phaltias, fils de Banaïas, princes du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 2, 'Et le Seigneur me dit: Fils de l’homme, voici des hommes qui conçoivent des vanités, et tiennent de mauvais conseils en cette ville,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 3, 'Disant Est-ce que ce temple a été bâti récemment? Il est chaudière, et la chair, c’est nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 4, 'À cause de cela, prophétise contre eux, prophétise, fils de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 5, 'Et sur moi l’esprit du Seigneur tomba, et il me dit: Parle, voici ce que dit le Seigneur: C’est ainsi que vous parlez, maison d’Israël; les conseils téméraires de votre esprit, je les connais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 6, 'Vous avez multiplié vos meurtres en cette ville, et vous avez rempli ses rues de cadavres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 7, 'À cause de cela, voici ce que dit le Seigneur: Les morts que vous avez frappés au milieu de cette ville, sont les chairs, cette ville est la chaudière, et vous, je vous chasserai du milieu de cette ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 8, 'Vous avez peur du glaive, et c’est le glaive que j’amènerai sur vous, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 9, 'Et je vous chasserai du milieu de cette ville, et je vous livrerai à des étrangers, et j’exécuterai mes jugements sur vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 10, 'Vous tomberez sous le glaive; je vous jugerai sur les montagnes d’Israël, et vous reconnaîtrez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 11, '(Vulg., 13.) Et ceci advint: pendant que je prophétisais, Phaltias, fils de Banaïas, mourut, et je tombai la face contre terre, et je criai à haute voix, et je dis: Hélas! hélas! Seigneur, allez-vous détruire les restes d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 12, '(14.) Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 13, '(15.) Fils de l’homme, tes frères, et les hommes avec toi captifs, et toute la maison d’Israël, ce sont tous ceux à qui les habitants de Jérusalem ont dit: Retirezvous loin du Seigneur; c’est à nous que cette terre a été donnée pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 14, '(16.) À cause de cela, dis-leur: Ainsi parle le Seigneur: Je les chasserai parmi les nations; je les disperserai en toute terre, et je serai pour eux comme un petit sanctuaire, en toutes les contrées où ils iront résider.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 15, '(17.) À cause de cela, dis-leur: Ainsi parle le Seigneur: Je les recueillerai parmi les nations; je les rassemblerai des contrées où je les aurai dispersés, et je leur donnerai la terre d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 16, '(18.) Et ils y rentreront, et ils en déracineront toutes les abominations et toutes les iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 17, '(19.) Et je leur donnerai un autre cœur, et je mettrai en eux un esprit nouveau, et je retirerai de leur chair le cœur de pierre, et je leur donnerai un cœur de chair;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 18, '(20.) Afin qu’ils marchent en mes commandements, et qu’ils gardent mes ordonnances et les accomplissent; et ils seront mon peuple, et je serai leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 19, '(21.) Pour ceux dont le cœur a cheminé, comme leur cœur, en des abominations et des iniquités, je ferai retomber leurs voies sur leurs têtes, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 20, '(22.) Et les chérubins déployèrent leurs ailes, et ils s’élevèrent ayant à côté d’eux les roues, et au-dessus d’eux la gloire du Dieu d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 21, '(23.) Et la gloire du Seigneur monta du milieu de la ville, et elle s’arrêta en face de la ville sur les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 22, '(24.) Et l’esprit me ravit; et en ma vision venant de l’Esprit de Dieu il me ramena sur la terre des Chaldéens, parmi les captifs. Et je descendis de la vision que j’avais eue,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 23, '(25.) Et je répétai aux captifs toutes les paroles que Dieu m’avait révélées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 2, 'Fils de l’homme, tu demeures au milieu des iniquités de ceux qui ont des yeux pour voir, et ne voient point; qui ont des oreilles pour entendre, et n’entendent point; car c’est une maison qui m’irrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 3, 'Et maintenant, fils de l’homme, prépare ton bagage, pour aller en captivité devant eux en plein jour; et devant eux tu seras emmené captif de ce lieu en un autre lieu, afin qu’ils te voient; car c’est une maison qui m’irrite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 4, 'Et tu transporteras ton bagage pour aller en captivité devant eux, en plein jour; puis, sous leurs yeux, tu sortiras le soir, comme sort un captif.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 5, 'Creuse-toi un trou dans le mur de ta maison, et tu passeras par ce trou,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 6, 'Devant eux. Tu te feras porter sur des épaules, et tu sortiras dans les ténèbres; tu te cacheras le visage, et tu ne verras pas la terre; car je t’ai donné comme un signe à la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 7, 'Et je fis toutes ces choses, comme le Seigneur me l’avait commandé, et je transportai en plein jour mon bagage pour aller en captivité; et le soir je fis pour moi un trou au mur, et je sortis dans les ténèbres, et je me fis porter sur des épaules devant eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 8, 'Et le matin, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 9, 'Fils de l’homme, la maison d’Israël, cette maison qui m’irrite, n’a-t-elle pas dit: Que fais-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 10, 'Dis-leur: Ainsi parle le Seigneur: Moi, le prince et le chef de Jérusalem, à tout le peuple d’Israël, à tous ceux qui sont dans la ville,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 11, 'J’ai dit: Je fais pour eux des signes; et comme j’ai fait, il leur adviendra. Ils partiront pour l’exil et la captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 12, 'Et, au milieu d’eux, le roi sera porté sur des épaules, et il sortira dans les ténèbres, par une brèche de mur, et il aura fait cette brèche pour sortir; il se cachera le visage, de sorte que nul œil ne le verra, et lui-même ne verra pas la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 13, 'Et je tendrai mon filet sur lui, et il y sera pris, et je le conduirai à Babylone, en la terre des Chaldéens; et il ne la verra pas, et il y mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 14, 'Et tous ses auxiliaires d’alentour, et tous ses alliés, je les disperserai à tous les vents, et je les poursuivrai à coups d’épée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 15, 'Et ils connaîtront que je suis le Seigneur, quand je les aurai dispersés parmi les nations, et ils seront dispersés dans toutes les contrées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 16, 'Et parmi eux je ferai échapper un petit nombre d’hommes au glaive, à la famine et à la peste, afin qu’ils racontent toutes leurs iniquités chez les nations où ils iront résider, et qu’elles sachent que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 17, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 18, 'Fils de l’homme, mange ton pain dans la tristesse; bois ton eau dans les tourments et l’affliction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 19, 'Et dis au peuple de la terre: Ainsi parle le Seigneur à ceux qui demeurent à Jérusalem et sur le territoire d’Israël: Ils mangeront leur pain dans la détresse, et ils boiront leur eau dans la désolation, lorsque cette terre sera détruite avec sa richesse; car tous ceux qui l’habitent vivent dans l’impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 20, 'Et je rendrai désertes leurs villes si peuplées, et leur terre sera dévastée; et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 21, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 22, 'Fils de l’homme, quelle est cette parabole que l’on dit sur la terre: Les jours sont loin, la vision a péri?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 23, 'À cause de cela, dis-leur: Ainsi parle le Seigneur: Je changerai cette parabole, et on ne répètera plus cette parabole en la maison d’Israël; car tu lui diras: Les jours sont proches, et toutes les paroles de la vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 24, 'Car il n’y aura plus de vision fausse, ni de faux prophètes qui prédisent au milieu des fils d’Israël pour leur plaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 25, 'Car moi-même, le Seigneur, je dirai mes paroles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 26, 'Et le parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 27, 'Fils de l’homme, voilà que la maison d’Israël m’irrite; ils disent: La vision que cet homme a eue est pour des jours lointains, et il prophétise ainsi pour des temps loin de nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 28, 'À cause de cela, dis-leur: Ainsi parle le Seigneur: La parole que j’ai dite ne tardera pas à s’accomplir: je vais parler et j’exécuterai, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 2, 'Fils de l’homme, prophétise contre les prophètes d’Israël, prophétise et dis-leur: Écoutez la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 3, 'Voici ce que dit le Seigneur: Malheur à ceux qui prophétisent d’après leur cœur, et ne considèrent aucune chose!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 4, 'Israël, tes prophètes sont comme des renards dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 5, 'Ils ne s’appuient sur rien, et ils ont rassemblé de menus troupeaux contre la maison d’Israël. Ils ne se sont pas levés, le jour du Seigneur, ceux qui parlent,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 6, 'Ayant des visions fausses, prédisant des choses vaines, disant: Le Seigneur dit; mais le Seigneur ne les a pas envoyés, et ils ont pris sur eux de confirmer leur propre parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 7, 'N’avez-vous pas eu de fausses visions? n’avez-vous point prédit des choses vaines?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 8, 'À cause de cela, dis-leur: Ainsi parle le Seigneur: En punition de ce que vos paroles sont fausses, et vos prédictions vaines, voilà que je suis contre vous, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 9, 'Et j’étendrai la main sur les prophètes qui ont des visions fausses, et qui disent des choses vaines; ils ne seront pas pour l’instruction de mon peuple; ils ne seront pas inscrits parmi la maison d’Israël; ils n’entreront pas dans l’héritage d’Israël, et ils sauront que je suis le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 10, 'En punition de ce qu’ils ont égaré mon peuple, disant La paix, quand il n’y a point de paix: mon peuple bâtit un mur, ils le crépissent, et le mur tombera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 11, 'Dis à ceux qui le crépissent: Le mur tombera; il y aura de la pluie pour le faire crouler. Je lancerai des pierres sur ses jointures, et elles tomberont; et sur lui, un grand vent, et il se fendra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 12, 'Et voilà que le mur est tombé, et ils ne diront pas: Où est le plâtre avec lequel nous l’avons crépi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 13, 'À cause de cela, voici ce que dit le Seigneur: Je ferai éclater un souffle qui détruira avec fureur, et il y aura en ma colère une pluie qui débordera; et je lancerai en mon courroux des pierres qui détruiront jusqu’à l’anéantissement;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 14, 'Et j’abattrai le mur que vous avez crépi, et il tombera; et je le coucherai sur la terre, et ses fondations seront à découvert, et il tombera; et vous périrez au milieu d’outrages, et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 15, 'Et j’assouvirai ma colère sur le mur, et sur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 16, 'C’étaient les prophètes d’Israël qui prophétisaient pour Jérusalem, et qui en leurs visions voyaient pour elle la paix, quand il n’y a point de paix, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 17, 'Et toi, fils de l’homme, tourne la face contre les filles de ton peuple, contre celles qui prophétisent d’après leur cœur, et qui prophétisent contre elles-mêmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 18, 'Et dis-leur: Ainsi parle le Seigneur: Malheur à celles qui cousent des coussins pour les mettre sous les deux coudes, et qui en font des oreillers pour toute tête de tout âge, afin de pervertir les âmes. Les âmes de mon peuple ont été perverties, et ces femmes conservaient ces âmes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 19, 'Et elles m’ont profané devant mon peuple pour une poignée d’orge et pour un morceau de pain, afin de tuer des âmes qui ne devaient point mourir, et conserver la vie à des âmes qui ne devaient point vivre; c’est pour cela, ò filles, que vous avez prononcé devant mon peuple qui vous écoutait des prédictions vaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 20, 'À cause de cela, ainsi dit le Seigneur maître: Voilà que je suis contre ces coussins sur lesquels vous ramassez les âmes; je les mettrai en pièces sous vos bras, et je disperserai les âmes que vous avez perverties.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 21, 'Et je déchirerai vos oreillers, et je délivrerai mon peuple de vos mains, et ils ne seront plus ramassés par vous; et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 22, 'En punition de ce que vous pervertissez le cœur du juste que je n’avais point perverti, de ce que vous avez fortifié les mains du méchant pour qu’il fût entièrement incapable de revenir de sa voie mauvaise et de vivre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 23, 'À cause de cela vous n’aurez plus vos visions fausses; vous ne prophétiserez plus vos mensonges, et je délivrerai mon peuple de vos mains; et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 1, 'Et quelques-uns des anciens du peuple d’Israël vinrent me trouver, et ils s’assirent devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 2, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 3, 'Fils de l’homme, ces hommes ont conçu leurs pensées en leurs cœurs, et ils ont mis devant leur visage la punition de leurs iniquités: que dois-je leur répondre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 4, 'Parle et dis-leur: Voici ce que dit le Seigneur: Tout homme, un homme d’Israël, qui aura conçu des pensées en son cœur et qui aura mis devant son visage la punition de son iniquité, et qui viendra devant le prophète, moi le Seigneur je lui répondrai selon les engagements de sa pensée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 5, 'Car il désire tromper la maison d’Israël, pour qu’elle se laisse entraîner par ses convoitises et qu’elle éloigne son cœur de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 6, 'À cause de cela, dis à la maison d’Israël: Ainsi parle le Seigneur Convertissez-vous et détournez-vous de vos mauvaises œuvres et de toutes vos iniquités, et détournezen vos visages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 7, 'Car tout homme, un homme de la maison d’Israël, et tout étranger prosélyte en Israël, qui se sera éloigné de moi et aura conçu des pensées en son cœur et aura mis devant son visage la punition de son iniquité, et qui viendra ensuite au prophète pour le questionner sur moi, moi le Seigneur, je lui répondrai selon les engagements où il est lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 8, 'Et je tournerai mon visage contre cet homme, et je le livrerai à la solitude et à l’extermination, et je l’effacerai du milieu de mon peuple, et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 9, 'Et si un prophète s’est égaré, et s’il a parlé, c’est moi le Seigneur (qui ai égaré ce prophète; et j’étendrai la main sur lui, et je l’exterminerai du milieu de mon peuple d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 10, 'Et ils porteront la peine de leur iniquité, selon l’iniquité de celui qui aura interrogé, laquelle sera punie de la même manière que l’iniquité du prophète;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 11, 'Afin que la maison d’Israël ne s’égare plus en s’éloignant de moi, qu’elle ne se souille plus par ses péchés; de sorte qu’elle soit mon peuple, et que je sois son Dieu, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 12, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 13, 'Fils de l’homme, la terre qui aura péché contre moi en ses transgressions, j’étendrai la main sur elle; je briserai la force du pain, je lui enverrai la famine, et je détruirai les hommes et son bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 14, 'Et si, au milieu d’elle, se trouvent trois hommes comme Noé, Daniel et Job, ils seront sauvés à cause de leur justice, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 15, 'Et si j’amène les bêtes farouches sur cette terre, et si je la punis, et si elle est désolée, et que nul ne la traverse en face des bêtes farouches;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 16, 'Si ces trois hommes s’y trouvent, par ma vie, dit le Seigneur, ni leurs fils ni leurs filles ne seront sauvés; eux seuls seront sauvés, mais la terre sera détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 17, 'Ou bien encore, si je promène le glaive sur cette terre, et si je dis: Que le glaive sillonne toute cette terre, et j’en ôterai les hommes et le bétail;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 18, 'Et si ces trois hommes s’y trouvent, par ma vie, dit le Seigneur, ils ne sauveront ni leurs fils ni leurs filles; eux seuls seront sauvés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 19, 'Ou bien encore, si j’envoie la peste en cette terre, et si je verse sur elle ma colère, avec le sang, pour détruire ses hommes et son bétail,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 20, 'Et si Noé, Daniel et Jacob s’y trouvent, par ma vie, dit le Seigneur, ni leurs fils ni leurs filles n’échapperont; eux seuls, à cause de leur justice, auront sauvé leurs âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 21, 'Voici ce que dit le Seigneur: Si j’envoie contre Jérusalem les quatre fléaux: le glaive, la famine, les bêtes farouches et la peste, pour y détruire les hommes et le bétail;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 22, 'Voilà qu’il restera quelques hommes; et ceux-là seront sauvés; et ils emmèneront de la ville leurs fils et leurs filles; puis voilà qu’ils viendront à vous, et vous verrez leurs voies et leurs pensées; et le repentir vous pénètrera, à cause des maux que j’aurai fait tomber sur Jérusalem, à cause de toutes les afflictions que je lui aurai envoyées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 23, 'Et ils vous consoleront, parce que vous verrez leurs voies et leurs pensées; et vous reconnaîtrez que ce n’est point à tort que j’ai fait tout ce que j’ai fait contre elle, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 2, 'Dis, fils de l’homme, qu’est-ce que le bois de la vigne, en comparaison des arbres qui se trouvent dans les forêts?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 3, 'Prendra-t-on le bois pour le rendre propre à être mis en œuvre? En fera-t-on des chevilles pour y suspendre quelque objet?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 4, 'Il n’est bon qu’à être jeté au feu et consumé; le feu chaque année consume le sarment qu’on ôte à la vigne en la taillant, et finalement il n’en reste rien; est-ce qu’il est propre à être mis en œuvre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 5, 'Et même lorsqu’il est encore entier, il ne peut servir à aucune œuvre si donc le feu l’a entièrement consumé, sera-t-il propre à être mis en œuvre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 6, 'À cause de cela, dis-leur: Ainsi parle le Seigneur: De même que j’ai abandonné au feu, pour être consumé, le bois de la vigne parmi les arbres de la forêt; ainsi j’ai abandonné les habitants de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 7, 'Et je tournerai contre eux mon visage; ils sortiront du feu, et cependant le feu les dévorera, et ils sauront que je suis le Seigneur, lorsque j’aurai tourné mon visage contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 8, 'Et je livrerai leur terre à la désolation pour les punir de leurs transgressions, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 2, 'Fils de l’homme, fais connaître à Jérusalem ses iniquités;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 3, 'Et dis: Ainsi parle le Seigneur à Jérusalem: Ta racine et ton origine sortent de la terre de Chanaan; ton père était Amorrhéen, et ta mère une fille des Héthéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 4, 'Quant à ta naissance, le jour où tu as été enfantée, tu n’as point lié tes mamelles; tu n’as point été lavée dans l’eau; tu n’as point été salée avec du sel; tu n’as pas été enveloppée de langes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 5, 'Et mon œil ne s’est point apitoyé sur toi, et je ne t’ai fait aucune de ces choses, et je n’ai rien senti en ta faveur. Et tu as été jetée sur la terre d’un champ, dans la dépravation de ton âme, le jour où tu as été enfantée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 6, 'Et j’ai passé près de toi, et je t’ai vue souillée de ton sang, et je t’ai dit: Que ta vie vienne de ton sang;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 7, 'Multiplie-toi! Et je t’ai faite comme l’herbe qui pousse dans les champs; et tu as crû, et tu as grandi, et tu es entrée dans les villes des villes. Et tes mamelles se sont gonflées, et tu es devenue nubile, et tu étais nue et confuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 8, 'Et j’ai passé près de toi, et je t’ai vue, et voilà que c’était ton temps, le temps où l’on dénoue les ceintures des vierges. Et j’ai étendu sur toi mes ailes, et j’ai caché ta nudité, et je t’ai fait des promesses, et j’ai fait alliance avec toi, dit le Seigneur. Et tu as été à moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 9, 'Et je t’ai lavée dans l’eau, et j’ai enlevé le sang qui te souillait, et je t’ai parfumée d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 10, 'Et je t’ai vêtue de robes brodées, et je t’ai chaussée');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 11, 'Et je t’ai parée de joyaux; je t’ai mis des bracelets et un collier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 12, 'Et je t’ai donné un anneau pour tes narines, et je t’ai mis des boucles d’oreilles, et j’ai posé sur ta tête une couronne de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 13, 'Et tu as été ornée d’or et d’argent, et tes voiles étaient de fin lin, et ils étaient délicatement tissus, et ils étaient brodés. Et tu te nourrissais de fleur de farine, de miel et d’huile, et tu es devenue merveilleusement belle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 14, 'Et ta renommée s’est répandue parmi les nations, à cause de ta beauté; car elle était accomplie par la convenance, par le charme que j’avais mis en toi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 15, 'Mais tu t’es confiée en ta beauté, tu t’es prostituée au milieu de ta gloire; et tu t’es livrée à la fornication avec tous les passants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 16, 'Et tu as pris tes vêtements; et tu en as fabriqué des idoles; et tu t’es prostituée sur elles, et tu ne peux aller plus loin, et nul ne le pourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 17, 'Et tu as pris tes parures de gloire, faites de mon argent et de mon or, et tu en as fabriqué pour toi des images d’hommes auxquelles tu t’es prostituée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 18, 'Et tu as pris tes robes brodées, et tu les en as revêtues; et tu leur as fait offrande de mon huile et de mes parfums,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 19, 'Et de mes pains que je t’avais donnés (car je te nourrissais de fleur de farine, d’huile et de miel); et tu les as posés devant ces idoles en odeur de suavité. Et voici ce qui est advenu, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 20, 'Tu as pris tes fils et tes filles que tu avais engendrés, et tu les leur as sacrifiés, pour qu’ils soient consumés par le feu. Et comme si c’était peu de t’être ainsi prostituée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 21, 'Tu as égorgé tes enfants pour les livrer à tes idoles, comme des victimes expiatoires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 22, 'Mais ceci dépasse toute ton infamie: tu ne t’es point souvenue de ta jeunesse, quand tu étais nue et confuse, et que tu vivais souillée dans ton sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 23, 'Et voici ce qui est advenu après toutes tes abominations, dit le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 24, 'Tu as bâti pour toi une maison de débauche, et tu t’es affichée toi-même sur toutes les places;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 25, 'Et à chaque coin de rue tu as bâti tes lieux de prostitution; et tu as souillé ta beauté, tu as livré tes membres à tous les passants, tu as multiplié tes débauches,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 26, 'Et tu t’es prostituée aux fils de l’Égypte, tes voisins, peuple charnu, et tu t’es prostituée de toute manière, au point de provoquer ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 27, 'Mais je vais étendre la main contre toi; et je déracinerai tes habitudes, et je te livrerai aux âmes qui te haïssent, aux filles des étrangers, qui rougissent ellesmêmes de la voie où tu as commis tes impiétés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 28, 'Et tu t’es prostituée avec les filles d’Assur, et même ainsi tu n’as pas été assouvie; tu t’es prostituée, et tu n’as pas été rassasiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 29, 'Et tu as multiplié tes alliances en la terre des Chaldéens, et tu n’as pas été rassasiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 30, 'Comment ferais-je alliance avec ta fille, dit le Seigneur, pendant que tu fais toutes les œuvres d’une femme prostituée? Or tu as triplé tes débauches en tes filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 31, 'Tu as bâti une maison de débauche à chaque coin de rue; tu as des lieux de prostitution sur toutes les places. Et tu es devenue comme une prostituée, qui met toujours ses faveurs à plus haut prix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 32, 'Une femme adultère te ressemble; elle prend l’argent que gagne son mari,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 33, 'Et le donne à tous ceux à qui elle s’est prostituée. De même tu as donné tes salaires à tous tes amants, et tu les as chargés de présents, pour qu’ils vinssent à toi de toutes parts en ta prostitution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 34, 'Car tu as agi autrement que les autres femmes en ta prostitution, envers ceux à qui tu t’es prostituée: c’est toi qui les as payés, et aucun salaire ne t’a été donné; et voilà comment a tourné ta perversité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 35, 'À cause de cela, prostituée, écoute la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 36, 'Voici ce que dit le Seigneur: En punition de ce que tu as prodigué ton argent monnayé, ta honte sera dévoilée dans ta prostitution à tes amants, dans toutes tes pensées, dans tes abominations et dans le sang de tes enfants, que tu as livrés à tes idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 37, 'À cause de cela, voilà que je vais rassembler contre toi tous les amants à qui tu t’es donnée; et tous ceux que tu as aimés, je les réunirai à ceux que tu haïssais. Et je les placerai en cercle autour de toi, et je leur dévoilerai tes iniquités, et ils verront toute ta honte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 38, 'Et je te punirai comme on punit la femme adultère, et je te plongerai dans le sang de la fureur et de la jalousie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 39, 'Et je te livrerai à leurs mains, et ils démoliront ta maison de débauche, et ils détruiront les lieux où tu te prostituais, et ils te dépouilleront de tes vêtements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 40, 'Et ils te feront poursuivre par la populace, et ils te lapideront, et ils t’égorgeront avec leurs glaives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 41, 'Et ils brûleront ta maison par le feu, et ils tireront vengeance de toi devant un grand nombre de femmes. Et je te détournerai de la débauche, et je ne te permettrai plus de donner des salaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 42, 'Alors je ne déchaînerai plus ma fureur contre toi, et ma jalousie se détournera de toi, et je me tiendrai en repos, et je n’aurai plus souci de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 43, 'En punition de ce que tu ne t’es point souvenue de ta jeunesse, et que tu m’as contristé par toutes ces choses, voilà que j’ai rétribué toutes tes voies sur ta tête, dit le Seigneur; car tu as mis le comble à tes désordres par ton impiété.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 44, 'Toutes ces choses font que l’on dit de toi en proverbe Telle fut la mère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 45, 'Telle est la fille de la mère; tu es celle qui as répudié son époux et ses enfants, et les sœurs de tes sœurs ont répudié leurs époux et leurs enfants. Ta mère était Héthéenne, et ton père Amorrhéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 46, 'Samarie est votre sœur aînée; elle et sa fille habitent à ta gauche. Et ta plus jeune sœur, qui habite à ta droite, c’est Sodome et ses filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 47, 'Et tu n’as pas seulement marché comme elles en leurs voies, tu ne t’es pas contentée de leurs abominations; mais encore en tes voies tu les as surpassées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 48, 'Par ma vie, dit le Seigneur, Sodome et ses filles');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 49, 'Or voici l’iniquité de Sodome, ta sœur: c’est l’orgueil; elle et ses filles nageaient dans la prospérité, dans l’abondance du pain, dans l’excès des plaisirs; elles avaient tout cela, et jamais elles n’ont tendu la main au pauvre ni au mendiant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 50, 'Elles se sont donc enorgueillies, et elles ont fait des iniquités devant moi, et je les ai détruites comme je l’ai jugé bon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 51, 'Samarie, de son côté, n’a point péché moitié autant que toi; mais tu les as surpassées l’une et l’autre en abominations; et tu as tellement multiplié tes iniquités, que tes sœurs en ont paru justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 52, 'Reçois donc ton châtiment, parce que tu as corrompu tes sœurs par tes péchés que tu as multipliés plus qu’elles; ce qui les a fait paraître plus justes que toi. Rougis donc, et accepte ton ignominie, car tu as justilié tes sœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 53, 'Et je ferai revenir leurs captifs; je relèverai Sodome et ses filles, je relèverai Samarie et ses filles, et je te relèverai toi-même au milieu d’elles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 54, 'Afin que tu acceptes ton châtiment et que tu sois confuse de tout ce que tu as fait pour m’irriter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 55, 'Et ta sœur Sodome et ses filles seront rétablies comme elles étaient au commencement; et toi-même et tes filles, vous serez rétablies comme vous étiez au commencement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 56, 'Certes, on n’a pas entendu le nom de Sodome, ta sœur, sortir de ta bouche aux jours de ta superbe,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 57, 'Avant que tes méchancetés eussent été dévoilées. De même, tu es aujourd’hui un sujet d’opprobre pour les filles de la Syrie et pour les filles de tous ceux qui l’entourent, et pour toutes les filles des Philistins qui forment un cercle autour de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 58, 'Quant à tes impiétés et à tes crimes, tu en as porté peine, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 59, 'Or voici ce que dit le Seigneur: Comme tu as agi, j’agirai envers toi, puisque tu méprises tes promesses en violant mon alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 60, 'Mais je me souviendrai de l’alliance que j’ai faite avec toi dans ta jeunesse, et je la ferai revivre, et ce sera une alliance éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 61, 'Et tu te souviendras de ta voie, et tu seras couverte de honte, lorsque tu recevras tes sœurs aînées et tes sœurs puînées, et je te les donnerai pour que tu les réédifies, mais non par une alliance qui vienne de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 62, 'Et je ferai revivre mon alliance avec toi, et tu connaîtras que je suis le Seigneur;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 63, 'Afin que tu te souviennes, et que tu rougisses, sans oser même ouvrir la bouche en face de ta honte, lorsque je t’aurai pardonné tout ce que tu as fait, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 2, 'Fils de l’homme, fais un récit, et dis ma parabole à la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 3, 'Dis-leur: Ainsi parle le Seigneur: Un grand aigle, aux grandes ailes, à la vaste envergure, aux fortes serres, ayant dirigé son essor vers le Liban, y vint et choisit les meilleures branches d’un cèdre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 4, 'Il arracha les pointes des bourgeons et il les transporta en la terre de Chanaan, et il les déposa dans une ville fortifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 5, 'Et il prit de la graine en terre, et il la sema dans un champ fertilisé par beaucoup d’eau, et il la déposa en un lieu apparent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 6, 'Et elle germa, et elle devint une vigne basse et rampante, de sorte que les bourgeons apparaissaient au-dessus de la semence, tandis que les racines étaient en terre. Et elle devint une vigne, et elle provigna, et elle étendit en haut ses sarments.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 7, 'Et il vint un autre grand aigle, aux grandes ailes, aux serres nombreuses; et voilà que la vigne se plia autour de lui, et ses racines étaient près de lui, et elle lui envoya ses rameaux pour lui donner à boire de la séve de son plant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 8, 'Elle-même engraissa dans une bonne terre, sur des eaux abondantes, au point de pousser des jets, de porter des fruits, et d’être une grande vigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 9, 'Et à cause de cela, dis-leur: Ainsi parle le Seigneur: Prospérera-t-elle? Ses tendres racines, son fruit ne pourriront-ils pas? Ses bourgeons ne se dessécheront pas? Ne sera-t-elle pas déracinée par un bras puissant et par un peuple nombreux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 10, 'Et voilà qu’elle a engraissé; mais pourra-t-elle s’élever? Ne sera-t-elle pas flétrie aussitôt que le vent brûlant la touchera? Oui, elle sera flétrie, avec la sève de ses bourgeons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 11, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 12, 'Fils de l’homme, dis à la maison qui m’irrite: Ne savez-vous pas ce que cela signifie? Dis encore: Quand le roi de Babylone viendra contre Jérusalem, il prendra son roi et ses princes, et il les emmènera avec lui à Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 13, 'Et il choisira un homme de famille royale, et il fera alliance avec lui, et il le liera par des serments; et il emmènera les princes de la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 14, 'Pour que le royaume soit affaibli, que le roi ne puisse se relever, qu’il garde son alliance et la maintienne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 15, 'Mais si le roi se révolte contre lui, s’il envoie des émissaires en Égypte pour en obtenir des chevaux et une nombreuse armée, réussira-t-il, sera-t-il sauvé en agissant comme un ennemi? Sera-t-il sauvé en violant l’alliance?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 16, 'Par ma vie, dit le Seigneur, il sera emmené où réside le roi qui l’a mis sur le trône, parce qu’il a méprisé le serment prêté en mon nom, et violé l’alliance où j’ai été pris à témoin, et il mourra au milieu de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 17, 'Et le Pharaon ne fera pas la guerre aux Assyriens avec une grande multitude et une forte armée, ni avec des retranchements et des balistes pour exterminer les âmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 18, 'Et le roi de Jérusalem a méprisé son serment, et il a violé l’alliance, quand j’avais engagé sa main, il a fait toutes ces choses pour sa sûreté, mais il ne sera pas sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 19, 'À cause de cela, dis-leur: Ainsi parle le Seigneur Par ma vie, il a méprisé un serment prêté en mon nom, il a violé l’alliance où j’ai été pris à témoin, et je ferai retomber son crime sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 20, 'Et je jetterai sur lui un filet, et il sera pris au piège.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 21, 'Dans toutes les batailles, ses hommes périront par le glaive, et je disperserai leurs restes à tous les vents, et vous saurez que c’est moi, le Seigneur, qui ai parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 22, 'Car voici ce que dit le Seigneur: C’est moi qui prendrai sur la cime d’un cèdre ses plus belles branches; j’en retirerai la moelle, et je la planterai sur une haute montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 23, 'Je la suspendrai sur la haute montagne d’Israël, et je la planterai; elle produira un rejeton, elle portera son fruit et deviendra un grand cèdre. Et chaque oiseau s’arrêtera sous ses branches, et tout ce qui vole se reposera sous son ombre, et ses rameaux seront pleins de force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 24, 'Et tous les arbres des champs sauront que je suis le Seigneur, qui abaisse les grands arbres et élève les petits; qui dessèche l’arbre vert et fait reverdir l’arbre desséché. C’est moi, le Seigneur, qui ai parlé, et j’exécuterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 2, 'Fils de l’homme, d’où vient cette parabole qui se dit parmi les enfants d’Israël: Les pères ont mangé du verjus, et les dents des enfants en ont été agacées?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 3, 'Par ma vie, dit le Seigneur, on ne répètera plus cette parabole en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 4, 'Car toutes les âmes sont à moi; les âmes des fils sont à moi, comme l’âme du père. L’âme qui pèche, voilà celle qui mourra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 5, 'L’homme qui sera juste, qui observera les jugements et l’équité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 6, 'Ne mangera pas sur les hauts lieux; il ne lèvera pas les yeux sur les idoles de la maison d’Israël; il ne profanera point la femme de son prochain; il ne s’approchera pas de sa femme dans son impureté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 7, 'Il n’opprimera pas âme qui vive; il rendra le gage du débiteur; il ne commettra aucune rapine; il donnera de son pain au pauvre, et il vêtira les nus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 8, 'Et il ne placera pas son argent à usure, et il ne prendra pas plus qu’il ne lui est dû, et il détournera sa main de l’iniquité, et il rendra un jugement juste entre un homme et son prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 9, 'Celui-là aura marché en mes commandements; il aura gardé mes ordonnances pour les mettre en pratique. Celui-là est juste, et il vivra de la vie, dit le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 10, 'Et s’il a engendré un fils corrompu qui verse le sang et commette des péchés,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 11, 'Celui-là n’aura pas marché dans la voie de son père; mais il aura mangé sur les hauts lieux, il aura profané la femme de son prochain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 12, 'Il aura opprimé le pauvre et le mendiant; il aura pris avec violence; il n’aura pas rendu le gage; il aura arrêté ses regards sur les idoles; il ́aura fait l’iniquité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 13, 'Il aura placé à usure; il se sera fait rendre plus qu’il ne lui était dû; celui-là ne vivra pas de la vie: pour avoir fait toutes ces iniquités, il mourra de mort, et son sang sera sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 14, 'Et si cet homme a engendré un fils qui ait vu tous les péchés commis par son père, mais qui en ait eu peur et ne les ait pas commis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 15, 'Qui ne monte pas sur les hauts lieux; qui n’arrête pas ses regards sur les idoles de la maison d’Israël; qui ne profane point la femme de son prochain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 16, 'Qui n’opprime pas âme qui vive; qui ne retienne pas de gages; qui ne commette aucune rapine; qui donne de son pain au pauvre et vêtisse les nus;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 17, 'Qui détourne sa main de l’iniquité, qui ne reçoive ni usure ni plus qu’il ne lui est dû; qui fasse justice; qui marche en mes commandements: il ne mourra pas à cause des iniquités de son père, il vivra de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 18, 'Et son père, pour avoir opprimé, pour avoir pris avec violence, pour avoir fait le mal devant mon peuple, mourra dans son iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 19, 'Et vous direz: Pourquoi le fils n’a-t-il pas porté la peine de l’iniquité du père? Parce que le fils a fait justice. et miséricorde, qu’il a gardé mes ordonnances et les a mises en pratique: il vivra de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 20, 'Et l’âme qui pèche mourra; le fils ne portera pas la peine de l’iniquité du père; le père ne portera pas la peine de l’iniquité du fils. La justice du juste sera sur lui, et l’iniquité de l’injuste sera sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 21, 'Et le pécheur, s’il revient de ses dérèglements, s’il garde tous mes commandements, s’il fait justice et miséricorde, vivra de la vie et ne mourra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 22, 'Toutes ses iniquités seront oubliées; il vivra dans son équité et à cause d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 23, 'Est-ce que je veux la mort du pécheur? dit le Seigneur. Est-ce que je ne veux pas plutôt qu’il se détourne de sa voie mauvaise et qu’il vive?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 24, 'Si le juste se détourne de sa justice et tombe dans tous les péchés que fait l’homme inique, toutes les œuvres de sa justice seront oubliées; il mourra dans sa chute et dans ses péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 25, 'Et vous dites: La voie du Seigneur n’est pas droite! Écoutez donc, ô vous tous, maison d’Israël: Est-ce ma voie qui n’est pas droite? Est-ce votre voie qui est droite?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 26, 'Quand le juste se détourne de sa justice, quand il fait un péché, quand il meurt dans le péché qu’il a fait, il meurt en ce péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 27, 'Et quand l’impie revient de son impiété, et qu’il fait jugement et justice, celui-là sauve son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 28, 'Il s’est converti de toutes les impiétés qu’il avait faites; il vivra de la vie et ne mourra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 29, 'Et en la maison d’Israël ils disent: La voie du Seigneur n’est pas droite! Est-ce ma voie qui n’est pas droite, maison d’Israël? N’est-ce pas votre voie qui n’est pas droite?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 30, 'Je jugerai chacun de vous selon sa voie, maison d’Israël, dit le Seigneur; convertissez-vous, revenez de toutes vos impiétés, et vous ne serez point punis pour cause d’iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 31, 'Repoussez loin de vous toutes les impiétés que vous avez commises contre moi; faites-vous un nouveau cœur, un esprit nouveau; et pourquoi péririez-vous, maison d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 32, 'Ce n’est pas moi qui veux la mort de celui qui périt, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 1, 'Et toi, chante une lamentation sur le prince d’Israël;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 2, 'Et dis: Pourquoi ma mère est-elle devenue une jeune lionne au milieu des lions? Pourquoi, au milieu des lions, a-t-elle multiplié ses lionceaux?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 3, 'Et un de ses lionceaux s’est élancé, et il est devenu lion, et il a appris à ravir sa proie, et il a dévoré des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 4, 'Et les nations en ont ouï parler, et il a été pris comme il les détruisait, et elles l’ont emmené, dans un filet, en la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 5, 'Et la lionne, ayant vu qu’il était séparé d’elle, et que son espérance en lui avait péri, prit un autre de ses lionceaux, et le fit lion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 6, 'Et celui-ci se montra au milieu des lions, et il devint lion, et il apprit à ravir\' sa proie, et il dévora des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 7, 'Et il se reput en son audace, et il dépeupla les villes de la voix de ses rugissements; et il désola la terre et ce qui la remplit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 8, 'Et les peuples des royaumes l’entourèrent, et ils tendirent contre lui leurs filets, et pendant qu’il les détruisait il fut pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 9, 'Et on le mit dans une cage de fer, enveloppé de son filet; et il arriva chez le roi de Babylone, qui le jeta en prison, afin qu’on n’entendit plus sa voix sur la montagne d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 10, 'Ta mère est comme une vigne et comme une fleur de grenadier planté au bord des eaux; son fruit et ses bourgeons ont crû dans l’abondance de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 11, 'Mais elle est devenue une verge pour la tribu des rois, et elle s’est élevée dans sa grandeur, au milieu des autres tiges. Et elle a vu sa grandeur en la multitude de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 12, 'Et elle a été brisée avec fureur; elle a été jetée à terre, et un vent brûlant a flétri ses meilleures branches; ils se sont vengés d’elle, et la verge de sa puissance a été desséchée. Le feu l’a dévorée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 13, 'Et maintenant on l’a plantée dans le désert en une terre aride.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 14, 'Et une flamme est sortie d’une verge de ses meilleurs rameaux, et elle l’a dévorée, et elle n’eut plus la verge de sa puissance. Sa race est devenue une parabole de lamentation, une lamentation que l’on chantera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 1, 'Et en la septième année, le quinzième jour du premier mois, quelques-uns des anciens de la maison d’Israël vinrent interroger le Seigneur, et ils s’assirent devant ma face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 2, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 3, 'Fils de l’homme, réponds aux anciens de la maison d’Israël, et dis-leur: Ainsi parle le Seigneur: Êtes-vous venus m’interroger? Par ma vie, dit le Seigneur, je ne vous répondrai pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 4, 'Les punirai-je sévèrement, fils de l’homme? Faisleur connaître les iniquités de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 5, 'Et dis-leur: Ainsi parle le Seigneur: Depuis le jour où je choisis la maison d’Israël, où je me manifestai à la race des fils de Jacob, où ils me connurent en Égypte, je les protégeai de ma main, disant: Je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 6, 'Ce jour-là même je les protégeai de ma main pour les conduire, de la terre d’Égypte, en la terre que je leur avais préparée, terre où coulent le lait et le miel, où les rayons des abeilles abondent plus qu’en aucune terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 7, 'Et je leur dis: Que chacun de vous rejette loin de ses yeux les abominations; gardez-vous de vous souiller par les idoles de l’Égypte: je suis le Seigneur votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 8, 'Et ils s’éloignèrent de moi, et ils ne voulurent point m’obéir, et ils ne rejetèrent pas loin de leurs yeux les abominations, et ils n’abandonnèrent pas les idoles de l’Égypte. Et je résolus de faire tomber sur eux ma fureur, et, au milieu même de l’Égypte, d’assouvir contre eux ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 9, 'Mais je fis en sorte que mon nom ne fût pas entièrement profané à la vue des gentils au milieu desquels ils sont, et parmi lesquels je me suis manifesté à eux, pour les retirer de la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 10, 'Et je les conduisis dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 11, 'Et je leur donnai mes commandements, et je leur fis connaître mes ordonnances, qui sont telles que l’homme, en les observant, vivra en elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 12, 'Et je leur prescrivis mes sabbats, pour être un signe entre eux et moi; pour qu’ils sussent que je suis le Seigneur qui les sanctifie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 13, 'Et je dis à la maison d’Israël dans le désert: Vous cheminerez en mes commandements; et ils n’y cheminèrent pas, et ils répudièrent mes ordonnances qui sont telles que parmi eux l’homme, en les observant, vivra en elles; et ils profanèrent à l’excès mes sabbats; et je résolus de faire tomber sur eux ma fureur dans le désert et de les exterminer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 14, 'Mais je fis en sorte que mon nom ne fût pas entièrement profané devant les gentils aux yeux desquels je les avais fait sortir de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 15, 'Et je retirai d’eux tout à fait ma main dans le désert, pour que nul d’eux n’entrât dans la terre que je leur avais donnée, terre où coulent le lait et le miel, et où les rayons des abeilles abondent plus qu’en aucune autre terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 16, 'En punition de ce qu’ils avaient répudié mes ordonnances, de ce qu’ils n’avaient pas cheminé en mes commandements, qu’ils avaient profané mes sabbats, et avaient couru après les imaginations de leurs cœurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 17, 'Mais mon œil s’apitoya sur eux quand je les fis périr, et je ne les détruisis pas tous entièrement dans le désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 18, 'Et je dis à leurs enfants dans le désert: Ne marchez point sur les traces de vos pères; gardez mes ordonnances; ne vous mêlez point à ceux qui adorent les idoles, et ne vous souillez point par elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 19, 'Je suis le Seigneur votre Dieu: cheminez en mes commandements; gardez mes ordonnances et mettez-les en pratique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 20, 'Sanctifiez mes sabbats; qu’ils soient un signe entre');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 21, 'Et leurs enfants m’irritèrent, et ils ne cheminèrent point en mes commandements, et ils ne regardèrent ni n’observèrent mes ordonnances, qui sont telles que parmi eux l’homme, en les observant, vivra en elles; et ils profanèrent mes sabbats, et je résolus de faire tomber sur eux ma fureur dans le désert et d’assouvir contre eux ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 22, 'Mais je fis en sorte que mon nom ne fût pas entièrement profané devant les gentils, et je menai mon peuple hors de la vue de ses ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 23, 'Je levai la main, dans le désert, contre les enfants de mon peuple, pour les disperser parmi les nations et les disséminer dans les royaumes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 24, 'En punition de ce qu’ils n’avaient point observé mes ordonnances, de ce qu’ils avaient répudié mes commandements, profané mes sabbats, suivi des yeux les imaginations de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 25, 'Alors je leur donnai des commandements qui n’étaient point bons, et des ordonnances en lesquelles ils ne pourraient vivre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 26, 'Et je les souillerai en leurs propres croyances, lorsque je passerai sur leurs nouveau-nés pour les détruire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 27, 'À cause de cela, fils de l’homme, réponds à la maison d’Israël, et dis-lui: Ainsi parle le Seigneur: Vos pères ont provoqué ma colère par leurs péchés contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 28, 'Je les ai fait entrer dans la terre sur laquelle j’avais levé la main, pour la leur donner; et ils en ont vu toutes les hautes collines, tous les arbres touffus, et ils y ont sacrifié à leurs dieux, et ils y ont offert des odeurs suaves, et ils y ont répandu des libations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 29, 'Et je leur ai dit: Qu’est-ce donc Abama, pour que vous y alliez? et ce nom d’Abama s’est conservé jusqu’à ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 30, 'À cause de cela, dis à la maison d’Israël: Ainsi parle le Seigneur: Si vous vous souillez des iniquités de vos pères, si vous vous prostituez à leurs abominations;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 31, 'Si vous vous souillez dans les prémices de vos dons, dans vos offrandes et dans toutes vos pensées, comme vous l’avez fait jusqu’à ce jour, je vous en réponds, maison d’Israël, par ma vie, dit le Seigneur, je ne vous parlerai plus, et je ne viendrai plus dans votre esprit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 32, 'Et il n’arrivera point comme vous désirez quand vous dites Nous serons comme les nations et comme les tribus de la terre, qui adorent des dieux de pierre et de bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 33, 'À cause de cela, par ma vie, dit le Seigneur, je règnerai sur vous avec un bras levé, une main puissante et une fureur déchaînée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 34, 'Je vous retirerai du milieu des peuples; je vous recueillerai des royaumes où vous avez été dispersés, avec un bras levé, une main puissante et une fureur déchaînée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 35, 'Et je vous conduirai dans le désert des gentils, et là, face à face, je plaiderai avec vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 36, 'De même que j’ai plaidé avec vos pères dans le désert de l’Égypte, ainsi je vous jugerai, dit le Seigneur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 37, 'Et je vous ferai passer sous ma verge, et je vous poursuivrai, si nombreux que vous soyez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 38, 'Et je choisirai parmi vous les impies et les rebelles; car je les ferai sortir des royaumes où ils sont comme passagers, et ils n’entreront pas en la terre d’Israël. Et vous saurez que je suis le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 39, 'Et vous, maison d’Israël, voilà ce que dit le Seigneur Maître: Que chacun de vous déracine ses habitudes d’idolâtrie; et après cela si vous m’écoutez, si vous ne profanez plus mon saint nom, par vos offrandes et vos imaginations,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 40, 'Un jour, sur ma montagne sainte, sur ma haute montagne, dit le Seigneur Maître, viendra me servir enfin toute la maison d’Israël. C’est là que je vous accueillerai et que je regarderai vos prémices, et les prémices de vos dons, en toutes vos cérémonies saintes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 41, 'Je vous accueillerai avec vos offrandes de suave odeur, quand je vous aurai retirés du milieu des peuples, et que je vous aurai recueillis des royaumes où vous aurez été dispersés; et je serai sanctifié parmi vous aux yeux des gentils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 42, 'Et vous saurez que je suis le Seigneur, lorsque je vous aurai ramenés en la terre d’Israël, dans la terre sur laquelle j’ai levé la main pour en faire don à vos pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 43, 'Et là vous vous rappellerez vos voies, et les habitudes d’idolâtrie dont vous vous êtes souillés, et vous vous frapperez au visage au souvenir de toutes vos iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 44, 'Et vous saurez que je suis le Seigneur, parce que je vous aurai ainsi traités, afin que mon nom ne soit pas profané en vos mauvaises voies et selon vos pensées corrompues, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 45, 'Et la parole du Seigneur me vint,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 46, 'Fils de l’homme, tourne ton visage contre Théman, et regarde vers Darom, et prophétise contre la grande forêt du Nageb,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 47, 'Et dis à la forêt du Nageb: Écoute la parole du Seigneur; ainsi parle le Seigneur Maître: Voilà que je vais allumer le feu en toi; et il brûlera en toi tout bois vert et tout bois sec, et la flamme une fois allumée ne s’éteindra pas, et elle brûlera tout visage, de l’orient à l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 48, 'Et toute chair saura que moi, le Seigneur, j’ai allumé ce feu, et qu’il ne s’éteindra pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 49, 'Et je dis: Qu’il n’en soit pas ainsi, Seigneur, Seigneur! car ils me disent: Pourquoi ne nous parle-t-il jamais qu’en paraboles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 2, 'À cause de cela, prophétise, fils de l’homme, tourne ton visage contre Jérusalem, et regarde ses lieux saints, et prophétise contre la terre d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 3, 'Et dis à la terre d’Israël: Ainsi parle le Seigneur: Voilà que je suis contre toi, et je tirerai le glaive du fourreau, et j’exterminerai parmi toi l’injuste et le pécheur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 4, 'Et parce que j’exterminerai en toi l’injuste et le pécheur, mon glaive sortira du fourreau, contre toute chair, de l’orient à l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 5, 'Et toute chair saura que moi, le Seigneur, j’aurai tiré le glaive du fourreau, et je ne le remettrai plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 6, 'Et toi, fils de l’homme, pousse des soupirs à te rompre les reins; et en tes douleurs gémis devant leurs yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 7, 'Et s’ils te disent: Pourquoi génis-tu? réponds: À cause d’une nouvelle, parce que l’ennemi vient; et tout cœur sera brisé, et toutes mains seront énervées; et toute chair, tout souffle seront défaillants, et tous genoux souillés d’humeurs; car voilà qu’il vient, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 8, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 9, 'Fils de l’homme, prophétise, et dis: Ainsi parle le Seigneur: Dis: Glaive, glaive, aiguise-toi, et mets-toi en fureur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 10, 'Pour égorger des victimes; aiguise-toi pour briller; prépare-toi pour tout affaiblir. Égorge, anéantis, abats');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 11, 'Et il l’a préparé pour le tenir en sa main. Le glaive est aiguisé, il est préparé pour être dans la main de celui qui transperce.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 12, 'Pousse des cris et des hurlements, fils de l’homme; car ce glaive est venu sur mon peuple, il est venu sur tous les princes d’Israël; ils seront comme des passagers; le jugement avec le glaive est venu sur mon peuple. C’est pourquoi bats des mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 13, 'Car il est condamné. Et qu’arrivera-t-il, si la famille entière est répudiée? Cela ne sera pas, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 14, 'Et toi, fils de l’homme, prophétise et bats des mains; prends deux glaives; et prends-en un troisième, le glaive, le grand glaive des tués. Mets-les hors d’eux-mêmes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 15, 'De peur que leur cœur ne se brise, et que les malades ne se multiplient auprès de toutes les portes; c’est par le glaive qu’ils doivent périr; il est tout prêt à les égorger; il est tout prêt à resplendir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 16, 'Accours, glaive, aiguise-toi à droite, aiguise-toi à gauche, aiguise-toi sur toutes tes faces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 17, 'Et moi aussi, je battrai des mains, et j’assouvirai ma colère; c’est moi, le Seigneur, qui ai parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 18, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 19, 'Et toi, fils de l’homme, représente-toi deux voies par où entrera le glaive du roi de Babylone. Toutes les deux partiront d’une même contrée; et il y aura une main à l’extrémité du chemin de la ville; tu la traceras à l’extrémité du chemin,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 20, 'Par où le glaive entrera pour attaquer Rabbath, l’un des fils d’Ammon, puis la Judée, et au milieu Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 21, 'Car le roi de Babylone s’arrêtera sur le vieux chemin, à la tête des deux chemins; attendant que les devins prennent les augures, que l’eau bouillante rejette une baguette, que l’on consulte les idoles, et que l’on interroge à droite le foie des victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 22, 'Et la divination a été faite contre Jérusalem; et le roi y plantera des palissades, il ouvrira la bouche pour crier, et il poussera une voix formidable; il plantera des palissades devant les portes de la ville, il fera des levées de terre, et il établira des balistes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 23, 'Cependant à leurs yeux il ne sera pour eux qu’un devin prenant les augures; mais il se rappellera les iniquités de leur prince.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 24, 'C’est pourquoi voici ce que dit le Seigneur: Parce que vous lui avez donné occasion de se rappeler le souvenir de votre iniquité, en dévoilant votre impiété, en faisant voir vos péchés; à cause de toutes vos impiétés et de vos idoles, en punition des crimes que vous lui avez rappelés, vous périrez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 25, 'Et toi, profane, impie roi d’Israël, dont le jour est venu, le jour marqué comme terme à ton iniquité,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 26, 'Voici ce que dit le Ssigneur: Tu lui as ôté la tiare, tu as mis à sa place ta couronne, et il n’y en aura plus de pareille; tu as abaissé ce qui était haut; tu as élevé ce qui était bas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 27, 'À cette couronne j’imputerai iniquité, iniquité, iniquité. Malheur à elle! telle elle restera, jusqu’à ce que vienne celui à qui elle est destinée, et je la lui livrerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 28, 'Et toi, fils de l’homme, prophétise et dis: Ainsi parle le Seigneur aux fils d’Ammon pour leur opprobre: Glaive, glaive, tiré pour le carnage, et tiré pour la destruction, lève-toi pour briller!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 29, 'Pendant ta vision vaine, ô Ammon, pendant ta fausse divination, glaive, anime-toi pour frapper au col les impies dont le jour est venu, le jour marqué comme terme à l’iniquité d’Ammon!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 30, 'Rentre dans le fourreau; mais tu ne trouveras pas le repos au lieu où tu es né; je te jugerai en ta propre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 31, 'Et je ferai tomber ma colère sur toi; je soufflerai soufflerai contre toi dans le feu de ma colère, et je te livrerai aux mains d’hommes barbares, habiles à porter avec eux la destruction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 32, 'Tu seras la pâture du feu; ton sang sera au milieu de ta terre, et il ne restera de toi aucun souvenir; car c’est moi, le Seigneur, qui ai parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 2, 'Et toi, fils de l’homme, ne jugeras-tu pas une ville de sang?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 3, 'Montre-lui toutes ses iniquités, et dis-lui: Ainsi parle le Seigneur Maître: Malheur à toi, ville, qui dans ton sein verses le sang pour que ton temps arrive, et qui t’es forgé des idoles pour te souiller');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 4, 'Du sang de tes enfants que tu as répandu! Tu es tombée et tu t’es souillée, en te forgeant des idoles; tu as avancé tes jours, et hâté le temps de tes années. À cause de cela, je t’ai livrée aux outrages des gentils; et on fera de toi un sujet de raillerie en tous les royaumes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 5, 'Qui t’avoisinent, et en ceux qui sont loin de toi; et l’on se moquera de toi, toi que l’on appelle impure et féconde en iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 6, 'Voilà que les princes de la maison d’Israël, chacun avec sa famille, ont conspiré en toi, afin de verser le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 7, 'C’est chez toi qu’ils ont médit de leur père et de leur mère, qu’ils ont été iniques envers l’étranger, et qu’ils ont opprimé l’orphelin et la veuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 8, 'Et ils ont méprisé mes choses saintes, et ils ont profané mes sabbats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 9, 'Chez toi il est des voleurs prompts à verser le sang; chez toi ils ont mangé sur les hauts lieux, et ils ont commis des crimes au milieu de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 10, 'Chez toi ils ont dévoilé la honte de leur père, et ils ont humilié la femme assise en sa souillure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 11, 'Chez toi chacun a abusé de la femme de son prochain; chacun a souillé criminellement sa bru; chacun a humilié sa sœur et la fille de son père.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 12, 'Chez toi ils ont reçu des dons pour verser le sang; chez toi ils ont prêté à usure, et ont reçu plus qu’il ne leur était dû. Et tu as porté la méchanceté au comble par tes actes d’oppression; et moi, tu m’as oublié, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 13, 'Et si je frappe des mains au sujet des iniquités que tu as consommées, et de ton sang qui a été répandu au milieu de toi,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 14, 'Ton cœur se soutiendra-t-il? et tes mains conserveront-elles leur force en ces jours que je vais amener sur toi? C’est moi, dit le Seigneur, qui ai parlé, et j’exécuterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 15, 'Et je te disperserai parmi les gentils, et je te disséminerai en tous les royaumes, et ton impureté te sera ôtée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 16, 'Et je ferai de toi mon héritage, aux yeux de toutes les nations; et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 17, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 18, 'Fils de l’homme, voilà que la maison d’Israël est devenue pour moi comme un alliage d’airain, de fer, d’étain et de plomb, mêlé avec de l’argent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 19, 'À cause de cela, dis-lui: Ainsi parle le Seigneur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 20, 'De même que dans la fournaise on rassemble l’argent, l’airain, le fer, l’étain et le plomb, pour souffler sur eux le feu et les fondre; ainsi je vous recueillerai en ma colère, et je vous rassemblerai, et je vous ferai fondre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 21, 'Et je soufflerai sur vous le feu de ma colère, et vous serez fondus au milieu de Jérusalem.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 22, 'De même que l’argent est fondu au milieu d’une fournaise, ainsi vous serez fondus au milieu de Jérusalem, et vous saurez que c’est moi, le Seigneur, qui ai versé sur vous ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 23, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 24, 'Fils de l’homme, dis à cette ville: Tu es une terre sans rosée; il n’est point venu de pluie sur toi au jour de ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 25, 'Ses princes au milieu d’elle sont comme des lions rugissants, ravissant leur proie, dévorant des âmes en leur violence, et recevant des présents. Et ils ont multiplié tes veuves au milieu de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 26, 'Et ses prêtres ont méprisé ma loi, et ils ont profané mes choses saintes. Ils n’ont point distingué le sacré du profane; ils n’ont point distingué le pur de l’impur; ils ont voilé leurs yeux pour ne point voir mes sabbats, et j’ai été déshonoré au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 27, 'Ses princes au milieu d’elle sont comme des loups ravissant leur proie, prêts à verser le sang pour s’emparer du bien d’autrui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 28, 'Et ses prophètes qui caressent le peuple tombe');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 29, 'Oppresseurs iniques du peuple de la terre, ravisseurs du bien d’autrui, spoliateurs du pauvre et de l’indigent, violateurs de la justice envers l’étranger!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 30, 'J’ai cherché parmi eux un homme qui revînt à la droiture, qui se tînt devant ma face de toute son âme au temps de ma colère, pour ne point effacer entièrement cette ville, et je ne l’ai pas trouvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 31, 'Et j’ai versé sur elle le feu de ma colère, pour la détruire, et j’ai fait retomber leurs voies sur leurs têtes, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 2, 'Fils de l’homme, il y avait deux femmes, filles d’une seule mère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 3, 'Et dans leur jeunesse, elles se sont prostituées en Égypte; c’est là que leurs mamelles sont tombées et qu’elles ont été déflorées de leur virginité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 4, 'Et elles s’appelaient: l’aînée Oola; sa sœur Ooliba. Et elles ont été à moi, et elles ont enfanté des fils et des filles, et voici leurs vrais noms: Samarie était Oola, et Jérusalem était Ooliba.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 5, 'Et Oola me quitta pour se prostituer; elle aima jusqu’à la fureur ses amants les Assyriens, qui demeuraient auprès d’elle,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 6, 'Vêtus d’hyacinthe, princes et capitaines, jeunes gens d’élite, tous cavaliers montant à cheval.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 7, 'Et c’est à eux qu’elle se livra dans sa débauche, et tous les fils choisis des Assyriens, et tous ceux qu’elle aima si furieusement, la souillèrent au gré de tous leurs désirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 8, 'Et elle ne renonça pas à sa débauche de l’Égypte; car c’est là que des hommes avaient dormi avec elle dans sa jeunesse, et ils l’avaient déflorée, et ils avaient versé sur elle leur propre infamie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 9, 'À cause de cela, je l’ai livrée aux mains de ses amants, aux mains des fils des Assyriens qu’elle a aimés avec fureur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 10, 'Ils ont dévoilé sa honte; ils ont pris ses fils et ses filles; et ils l’ont tuée elle-même à coups de glaive. Et elle est devenue la fable des femmes, et ils ont tiré vengeance d’elle sur sa fille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 11, 'Et sa sœur Ooliba la vit; et en ses passions elle fut plus dépravée qu’elle, et en sa prostitution elle surpassa la prostitution de sa sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 12, 'Elle aima avec fureur les fils des Assyriens, princes et capitaines, ses voisins, revêtus d’habits brodés, cavaliers montant à cheval, tous jeunes gens d’élite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 13, 'Et je les vis toutes deux marcher dans les mêmes souillures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 14, 'Et Ooliba alla plus loin dans sa débauche; elle vit des hommes dessinés sur un mur, images de Chaldéens tracés au pinceau,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 15, 'Les reins ceints d’étoffes bigarrées, la tête couverte d’étoffes de couleur, trois fois plus grands que les autres hommes, images de fils des Chaldéens, de la terre de leurs aïeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 16, 'Et les ayant contemplés de ses yeux, elle les aima');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 17, 'Et les fils de Babylone vinrent à elle; ils partagèrent sa couche; ils la souillèrent en sa prostitution, et elle fut souillée par eux; puis son âme s’éloigna d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 18, 'Et elle dévoila sa débauche, et elle dévoila sa honte. Et mon âme s’éloigna d’elle comme mon âme s’était éloignée de sa sœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 19, 'Et tu as multiplié tes débauches, comme pour rappeler le souvenir des jours de ta jeunesse, où tu t’es prostituée en Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 20, 'Et tu as aimé avec fureur les Chaldéens, qui avaient des chairs commes des ânes, et des membres comme des chevaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 21, 'Et tu as renouvelé le dérèglement de ta jeunesse, et ce que tu as fait durant ton séjour en Égypte quand tu avais les mamelles de ta jeunesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 22, 'À cause de cela, Ooliba, voici ce que dit le Seigneur: Voilà que je vais susciter contre toi tes amants, de qui ton âme s’est éloignée; je les rassemblerai en cercle contre toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 23, 'Les fils de Babylone et tous les Chaldéens, Phacuc, et Sué, et Hychué, et avec eux tous les fils des Assyriens, jeunes gens d’élite, princes et capitaines, tous ayant grand air et grand renom, cavaliers montant à cheval.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 24, 'Et ils viendront tous contre toi du nord, chars et roues, avec une multitude de peuples, longs boucliers, écus légers, et ils poseront autour de toi des gardes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 25, 'Et je rendrai mon arrêt devant eux, et ils te puniront selon leurs lois. Et j’amènerai contre toi ma jalousie; et ils te traiteront avec des transports de colère. Ils te couperont les narines et les oreilles; ils frapperont du glaive ceux des tiens qui survivront; ils prendront tes fils et tes filles, et le feu dévorera ce qui restera de toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 26, 'Et ils te dépouilleront de tes vêtements, et ils te prendront les joyaux qui faisaient ton orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 27, 'Puis je détournerai de toi tes impiétés, et tes débauches de la terre d’Égypte, et tu ne lèveras plus les yeux sur eux, et tu ne te souviendras plus de l’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 28, 'Ainsi parle encore le Seigneur Maître: Voilà que je te livre aux mains de ceux que tu hais, de ceux de qui ton âme s’est éloignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 29, 'Ils te traiteront avec haine, et ils te prendront le fruit de tes fatigues et de tes labeurs, et tu seras nue et confuse; et la honte de ta prostitution sera dévoilée; et ton impiété et ta débauche');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 30, 'T’auront attiré ces maux, parce que tu t’es prostituée en courant après des gentils, et que tu t’es souillée avec leurs idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 31, 'Tu as marché dans la voie de ta sœur, et je mettrai sa coupe en tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 32, 'Voici ce que dit le Seigneur: Bois la coupe de ta sœur, coupe large et profonde; bois-la jusqu’à l’ivresse;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 33, 'Et tu seras tout à fait énervée; la coupe de ta sœur Samarie est une coupe d’extermination.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 34, 'Bois-la, et je répudierai tes fêtes et tes jours de nouvelle lune; car c’est moi qui ai parlé, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 35, 'À cause de cela, voici ce que dit le Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 36, 'Et le Seigneur me dit: Fils de l’homme, ne jugeras-tu pas Oola et Ooliba? Ne leur feras-tu pas connaître leurs dérèglements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 37, 'Et leurs adultères, et le sang qu’elles ont versé? Elles se sont prostituées à leurs idoles; et leurs enfants qu’elles avaient enfantés pour moi, elles les ont fait passer pour elles à travers la flamme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 38, 'Et aussi longtemps qu’elles ont ainsi fait, elles ont souillé mes choses saintes et profané mes sabbats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 39, 'Et quand elles égorgeaient leurs enfants pour des idoles, elles entraient dans mon sanctuaire pour le souiller; et voilà ce qu’elles ont fait au milieu de mon temple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 40, 'Avec des hommes venant de loin, à qui elles avaient envoyé des messages. Et comme ils arrivaient tu t’es aussitôt lavée, tu t’es fardée autour des yeux, tu t’es parée de tes joyaux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 41, 'Tu t’es assise sur un long siège, et une table était préparée devant toi; et ils se sont réjouis de mes parfums et de mon huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 42, 'Et elles ont entonné des chants harmonieux devant quelques-uns des hommes qui étaient venus en foule du désert, et elles leur ont mis des bracelets, et elles leur ont posé sur la tête des couronnes de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 43, 'Et j’ai dit: Ne commettent-elles pas des adultères avec ceux-ci? Cette femme ne se conduit-elle pas comme une prostituée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 44, 'Ils sont entrés chez elle comme on entre chez une femme débauchée; et voilà comme ils sont entrés chez Oola et Ooliba, pour s’abandonner au dérèglement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 45, 'Aussi ce sont des hommes justes, ceux qui tireront vengeance contre ces femmes, de leurs adultères et du sang versé; car elles sont adultères et elles ont versé le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 46, 'Voici ce que dit le Seigneur Maître Ameute contre elles la foule, et répands chez elles le trouble et le pillage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 47, 'Qu’elles soient lapidées par les pierres de la multitude, qu’elles soient percées par ses glaives; on tuera leurs fils et leurs filles, on brûlera leurs maisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 48, 'Ensuite je détournerai de cette terre l’impiété, et toutes les femmes seront instruites, elles n’imiteront pas l’impiété de celles-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 49, 'Et votre iniquité retombera sur vous, et vous porterez la peine de vos idoles, et vous connaîtrez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 1, 'Et la parole du Seigneur vint à moi, en la neuvième année, le dixième mois, le dixième jour du mois, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 2, 'Fils de l’homme, à partir de ce jour où le roi de Babylone a fait tomber sa colère sur Jérusalem, à partir d’aujourd’hui, écris pour toi chaque jour;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 3, 'Et parle en parabole à cette maison qui m’irrite, et dis-lui: Ainsi parle le Seigneur: Mets sur le feu une chaudière et verses-y de l’eau;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 4, 'Et jettes-y des parts de victimes, des parts de choix, de la cuisse et de l’épaule réservées, la chair séparée des os,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 5, 'Et prises des bêtes choisies; et brûle les os sous les chairs. La chaudière a bouillonné, et les os ont cui au milieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 6, 'Voici donc ce que dit le Seigneur: Malheur à toi, ville de sang! tu es la chaudière où il y a de la rouille, et la rouille n’en est point partie; cette ville a offert des parts de victimes, et le sort n’est pas tombé sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 7, 'Parce que son sang est au milieu d’elle, je l’ai posé sur une pierre lisse; je ne l’ai point répandu sur la terre où il aurait été caché,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 8, 'Afin que ma colère éclate et châtie; j’ai mis le sang sur une pierre lisse, de peur qu’il ne soit caché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 9, 'À cause de cela, voici ce que dit le Seigneur: Et moi j’agrandirai le foyer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 10, 'Et je prodiguerai le bois, et j’y mettrai le feu, afin que les chairs soient consumées, et que le jus se réduise,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 11, 'Et que la chaudière pose sur les braises, que son airain s’échauffe et devienne brûlant, qu’il entre en fusion au milieu de son impureté, et que la rouille soit consumée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 12, 'Et la rouille qui abonde en elle ne sortira pas d’elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 13, 'Et sa rouille sera hideuse, en punition de ce que tu t’es souillée. Et pourquoi ne resterais-tu pas impure, jusqu’à ce que j’aie assouvi ma colère?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 14, 'C’est moi, le Seigneur, qui ai parlé, et le jour viendra où j’exécuterai, et je ne ferai pas de distinction, et je serai sans pitié. Selon tes voies et selon tes imaginations je te jugerai, dit le Seigneur. À cause de cela, je te jugerai selon le sang que tu as versé; je te jugerai selon les');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 15, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 16, 'Fils de l’homme, voilà que je vais te prendre par violence les délices de tes yeux; mais tu ne te lamenteras point, tu ne pleureras point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 17, 'Tu auras un soupir de sang, une douleur de reins; tes cheveux sur la tête ne seront point tressés, et tes sandales ne seront point à tes pieds; nulle lèvre ne te consolera, et tu ne mangeras pas le pain des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 18, 'Et je parlai au peuple le matin, comme le Seigneur me l’avait prescrit le soir; et je fis le matin même ce qui m’était commandé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 19, 'Et le peuple me dit: Ne nous expliques-tu pas pourquoi tu agis ainsi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 20, 'Et je leur répondis: La parole du Seigneur m’est venue, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 21, 'Dis à la maison d’Israël: Ainsi parle le Seigneur: Voilà que je vais profaner mon sanctuaire, l’orgueil de ta force, les délices de tes yeux, et pour lequel vous tremblez de toutes vos âmes. Vos fils et vos filles que vous aurez laissés périront par le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 22, 'Et vous ferez comme je viens de faire: nulle bouche ne vous consolera, et vous ne mangerez pas le pain des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 23, 'Et vos cheveux sur votre tête et vos sandales à vos pieds seront comme les miens; vous ne vous lamenterez point, vous ne pleurerez point, et vous vous consumerez en vos iniquités, et chacun de vous invoquera son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 24, 'Et Ézéchiel sera pour vous un signe; vous ferez comme je viens de faire, lorsque ces choses arriveront; et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 25, 'Et toi, fils de l’homme, n’est-ce pas le jour où je leur prendrai ce qui fait leur force, le sujet de leur orgueil, les délices de leurs yeux, la joie de leur âme, leurs fils et leurs filles,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 26, 'N’est-ce pas ce jour-là qu’un homme échappé à la mort viendra te trouver et te parler à l’oreille?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 27, 'Ce jour-là ta bouche s’ouvrira pour parler à cet homme sauvé; et tu ne seras pas muet plus longtemps, et tu seras pour eux un signe; et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 2, 'Fils de l’homme, tourne ta face contre les fils d’Ammon, et prophétise contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 3, 'Et dis aux fils d’Ammon: Écoutez la parole du Seigneur; ainsi parle le Seigneur: En punition de ce que vous vous êtes réjouis contre mes choses saintes, parce qu’elles ont été profanées, et contre Israël, parce qu’il a été détruit, et contre la maison de Juda, parce qu’elle a été emmenée en captivité;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 4, 'En punition de cela, je vous livre en héritage aux fils de Cédem, et ils séjourneront chez toi, avec leurs bagages, et ils y dresseront leurs tentes; ils mangeront tes fruits et ils boiront ton lait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 5, 'Et je ferai de la ville d’Ammon un pâturage pour leurs chameaux, et des fils d’Ammon un pâturage pour leurs brebis, et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 6, 'Car voici ce que dit le Seigneur: En punition de ce');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 7, 'En punition de cela, j’étendrai sur toi ma main, et je te livrerai en proie aux nations, et je te détruirai parmi les peuples, et je t’anéantirai, et tu sauras que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 8, 'Voici ce que dit le Seigneur: En punition de ce que Moab a dit: La maison d’Israël n’est-elle point maintenant comme toutes les nations?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 9, 'En punition de cela, voilà que je vais briser l’épaule de Moab, loin de ses villes frontières, sa terre choisie, la maison de Béthasimuth, située sur la fontaine de la ville maritime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 10, 'J’ai envoyé les fils de Cédem contre les fils d’Ammon, pour qu’ils en fassent leur héritage, et qu’il ne reste plus de souvenir des fils d’Ammon:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 11, 'Et je tirerai aussi vengeance de Moab, et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 12, 'Voici ce que dit le Seigneur: En punition de ce qu’a fait l’Idumée, qui, en châtiant la maison de Juda, s’est souvenue de sa propre haine, et s’est elle-même vengée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 13, 'À cause de cela, voici ce que dit le Seigneur: J’étendrai aussi la main sur l’Idumée, et j’y exterminerai les hommes et le bétail, et j’en ferai un désert; et ceux de Théman que l’on poursuivra tomberont sous le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 14, 'Et je punirai l’Idumée par les mains de mon peuple d’Israël, et ils traiteront l’Idumée selon ma colère et ma fureur, et ils connaîtront ma vengeance, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 15, 'À cause de cela, voici ce que dit le Seigneur: En punition de ce que les Philistins, en châtiant mon peuple, ont fait revivre leur propre vengeance, et se sont');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 16, 'À cause de cela, ainsi dit le Seigneur: Voilà que j’étendrai ma main sur les étrangers, et j’exterminerai les Crétois, et je détruirai le reste des habitants de la côte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 17, 'Et je les frapperai de mes grandes vengeances, et ils sauront que je suis le Seigneur, quand ma vengeance tombera sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 1, 'Et en l’année onzième, le premier jour du mois, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 2, 'Fils de l’homme, en punition de ce que Tyr a dit de Jérusalem: C’est bien! elle est brisée, son peuple a péri, son trafic est revenu à moi; elle qui était remplie, la voilà vide;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 3, 'En punition de cela, ainsi dit le Seigneur: Voilà que je suis contre toi, Tyr, et je conduirai contre toi maintes nations, comme la mer monte avec ses vagues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 4, 'Et elles abattront tes remparts, ô Tyr, et elles abattront tes tours; et je vannerai loin d’elle sa poussière, et je ferai d’elle une roche nue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 5, 'Elle sera au milieu de la mer un lieu à faire sécher les filets; car c’est moi qui ai parlé, dit le Seigneur. Et elle sera livrée en proie aux nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 6, 'Et ses filles, dans les champs, périront par le glaive, et elles sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 7, 'Car ainsi dit le Seigneur: Voilà que de l’aquilon je conduis contre toi, Tyr, Nabuchodonosor, roi de Babylone; il est le roi des rois, avec des chevaux et des chars, et des cavaliers, et un rassemblement de maintes nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 8, 'Il fera périr tes filles par le glaive dans les champs; il placera contre toi des gardes avancées; il bâtira autour de toi des forts; il t’enveloppera de palissades; il t’entourera de camps; il lancera devant toi ses javelines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 9, 'Il renversera de ses glaives tes remparts et tes tours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 10, 'À cause de la multitude de ses chevaux, tu seras couverte de poussière par le fracas de ses cavaliers et des roues de ses chars; tes murs seront ébranlés quand il franchira tes portes, comme on franchit dans la plaine l’entrée d’une ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 11, 'Les sabots de ses coursiers fouleront toutes tes places, et il passera ton peuple au fil de l’épée, et tout ce qui fait ta force, il le renversera par terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 12, 'Et il pillera tes richesses, et il enlèvera tes marchandises; il abattra tes murs; il détruira tes maisons si convoitées, et il jettera au fond de la mer qui te baigne tes pierres, tes bois et ta poussière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 13, 'Et il fera cesser tes nombreux concerts, et on n’entendra plus la voix de tes harpes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 14, 'Et je ferai de toi une roche nue, un lieu à faire sécher les filets, et tu ne seras plus rebâtie; car moi, le Seigneur, j’ai parlé, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 15, 'Car voici ce que dit à Tyr le Seigneur Maître: Les îles ne trembleront-elles pas au bruit de ta chute, quand tes blessés gémiront et que le glaive sera tiré au milieu de toi?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 16, 'Et tous les rois des nations maritimes descendront de leur trône, et ils déposeront leurs mitres de leurs. têtes, et ils se dépouilleront de leurs vêtements brodés. Ils seront frappés de stupeur; ils s’asseyeront à terre, et ils craindront de périr, et ils gémiront sur toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 17, 'Et ils feront de toi un sujet de lamentation, et ils te diront Comment as-tu cessé de sillonner la mer, Ô ville si célèbre, toi qui inspirais ta crainte à tous ceux qui demeurent sur tes rives?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 18, 'Et les îles trembleront au jour de ta chute.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 19, 'Car voici ce que dit le Seigneur Maître: Lorsque j’aurai fait de toi une solitude comme des villes qui ne seront plus habitées, quand j’aurai fait passer sur toi l’abîme, et que les grandes eaux te couvriront,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 20, 'Je te précipiterai parmi ceux qui sont tombés dans le gouffre, chez le peuple éternel, et je te placerai au plus profond de la terre, comme en un désert éternel parmi ceux qui sont tombés dans le gouffre, afin que tu ne sois plus habitée; et tu ne reviendras plus sur la terre des vivants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 21, 'Je te perdrai, et tu ne subsisteras plus dans les siècles, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 2, 'Et toi, fils de l’homme, chante sur Tyr une lamentation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 3, 'Et dis à cette Tyr, qui réside à l’entrée de la mer, dis à ce marché des peuples venant d’une multitude d’îles: Ainsi parle le Seigneur à Tyr: Tu as dit: C’est de moimême que je tiens ma beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 4, 'Au cœur de la mer, tes fils t’ont revêtue de beauté pour te consacrer à Baal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 5, 'Le cèdre de Sénir a servi à construire tes vaisseaux; tes planches ont été prises en des poutres de cy');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 6, 'On a fait tes rames de bois de Basan; on a fait en ivoire tes choses saintes, et tes chambres ombragées d’arbres en bois des îles de Cétim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 7, 'Le fin lin d’Égypte avec des broderies a formé ta couche; il en a été l’ornement; tu as été vêtue d’hyacinthe et de la pourpre des îles d’Élisa; c’était là ton manteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 8, 'Et tes princes, ceux qui habitent Sidon, et ceux d’Arad, te servaient de rameurs; et tes sages, ô Tyr, ceux qui résidaient en toi, étaient là tes pilotes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 9, 'Les anciens de Biblos et leurs sages, ceux qui étaient en toi, ceux-là fortifiaient ton conseil. Et tous les navires de la mer, et tous leurs rameurs trafiquaient pour toi, jusqu’aux confins de l’Occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 10, 'Les Perses, les Lydiens, les Libyens étaient dans ton armée; tes hommes de guerre avaient suspendu chez toi leurs boucliers et leurs casques, pour servir à ta gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 11, 'Les fils d’Arad et ton armée étaient sur tes remparts; ils faisaient bonne garde sur tes tours; ils avaient suspendu leurs carquois autour de tes édifices; c’était l’achèvement de ta beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 12, 'Les Carthaginois, par leur trafic, t’apportaient une grande part de tes richesses; ils remplissaient ton marché d’argent, d’or, de fer, d’étain et de plomb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 13, 'La Grèce tout entière et ses colons entraient chez toi avec des âmes d’hommes, et ils apportaient sur ton marché des vases d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 14, 'Ils t’amenaient des chevaux de Thogarma et des cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 15, 'Les fils des Rhodiens trafiquaient avec toi; ils multipliaient sur ton marché ce qui provenait des îles; ils t’apportaient des dents d’éléphants; et à ceux qui entraient chez toi, tu donnais des marchandises en échange:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 16, 'Des esclaves pris dans la multitude de ceux que tu avais à vendre, de l’huile de myrrhe et des broderies de Tharsis; Rhamoth et Chorchor approvisionnaient aussi ton marché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 17, 'Juda et les fils d’Israël trafiquaient avec toi; ils te vendaient du blé, des parfums et de la cannelle; ils t’apportaient le meilleur miel, de l’huile et de la résine pour tes marchands.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 18, 'Damas trafiquait avec toi; ils t’achetaient une part de la multitude de tes marchandises, et apportaient sur ton marché les laines de Milet et le vin de Chelbon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 19, 'D’Asel venaient chez tes marchands du fer travaillé et des roues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 20, 'Dédan trafiquait avec toi; elle t’amenait des bêtes de somme, choisies pour les chars.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 21, 'L’Arabie et tous les princes de Cédar trafiquaient avec toi; ils venaient chez toi avec des chameaux, des agneaux et des béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 22, 'Les marchands de Saba et de Rhamma trafiquaient avec toi; ils apportaient à ton marché les épices les plus recherchées, des pierres précieuses et de l’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 23, 'Charrha et Chanaa trafiquaient avec toi; Assur et Charman trafiquaient avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 24, 'Ils t’apportaient de l’hyacinthe et des ballots de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 25, 'Pour en faire des navires. Ceux qui trafiquaient avec toi se mêlaient à la multitude de tes marchands, et tu étais remplie et pesamment chargée au cœur de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 26, 'Tes rameurs t’ont conduite dans les grandes eaux; et le souffle du midi t’a brisée au cœur de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 27, 'Tes richesses, tes trésors, ceux de tes marchands; tes rameurs, tes pilotes, tes conseillers; ces hommes qui trafiquent avec toi, ces guerriers qui sont chez toi, toute la multitude rassemblée en toi, tomberont au cœur de la mer le jour de ta ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 28, 'Au cri de ta voix, tes pilotes seront frappés d’épouvante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 29, 'Tous tes rameurs, tous tes matelots descendront des navires; tous les pilotes de la mer resteront sur le rivage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 30, 'Et ils te plaindront à haute voix, et ils crieront amèrement, et ils mettront de la poussière sur leurs têtes, et ils se couvriront de cendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 31, 'Et leurs fils feront sur toi une lamentation, une lamentation sur Tyr, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 32, 'Quel profit as-tu retiré de la mer? Tu avais rempli de ton abondance toutes les nalions; tu avais enrichi par ton trafic tous les rois de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 33, 'Maintenant tu es brisée dans la mer; tes trafiquants sont au fond de l’abîme, avec toute la multitude assemblée en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 34, 'Tous tes rameurs sont tombés; tous les habitants des îles se sont affligés sur toi; leurs rois ont été saisis de stupeur, et leur visage s’est couvert de larmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 35, 'Les marchands des nations t’ont sifflée; tu es perdue, et tu ne seras plus dans les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 2, 'Et toi, fils de l’homme, dis au roi de Tyr: Voici ce que dit le Seigneur: En punition de ce que ton cœur s’est enorgueilli, et de ce que tu as dit: Je suis Dieu, j’habite au cœur de la mer une demeure de Dieu; tu verras que tu es un homme et non un Dieu; et tu as élevé ton cœur, comme s’il eût été le cœur de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 3, 'Es-tu plus sage que Daniel? Les sages ne t’ontils pas instruit de leur science?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 4, 'Est-ce par ton propre savoir et ton intelligence que tu t’es rendu puissant, et que tu as entassé l’or et l’argent dans tes trésors?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 5, 'Tu as accru ta puissance par ta science et par ton commerce, et ton cœur s’est enorgueilli de ta puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 6, 'C’est pourquoi ainsi parle le Seigneur: Puisque tu as élevé ton cœur comme s’il eût été le cœur de Dieu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 7, 'À cause de cela, voilà que j’amène contre toi des fléaux étrangers, venus des nations; et elles arriveront l’épée nue pour frapper toi, ta beauté, ta science, et elles jetteront à terre ta beauté, qu’elles détruiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 8, 'Et elles te renverseront, et tu mourras de mort avec ceux qui périront au cœur de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 9, 'Diras-tu Je suis Dieu, devant ceux qui te tueront? Tu es un homme, et non un Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 10, 'Tu périras par les mains des étrangers, au milieu');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 11, 'Et la parole du Seigneur me vint, disant: Fils de l’homme, fais une lamentation sur le roi de Tyr;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 12, 'Et dis-lui: Ainsi parle le Seigneur Maître: Toi, le sceau de la ressemblance de Dieu; toi, couronné de beauté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 13, 'Tu as été dans les délices du paradis de Dieu; tu t’es paré de toute pierre précieuse, de la sardoine, de la topaze, de l’émeraude, de l’escarboucle, du saphir, du jaspe, de l’argent, de l’or, de l’ambre, de l’agate, de l’améthyste, de la chrysolithe, du béryl, de l’onyx; tu as rempli d’or tes trésors et tes celliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 14, 'Le jour où tu as été créé, tu as été avec le chérubin; je t’ai mis en la montagne sainte de Dieu, au milieu de pierres de feu lançant des flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 15, 'Tu as été irréprochable en ta vie, du jour où tu as été créé jusqu’au jour où des iniquités ont été trouvées en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 16, 'En multipliant ton commerce, tu as rempli d’iniquités tes trésors, et tu as péché, et tu as été blessé et exclu de la montagne de Dieu; et le chérubin t’a banni du milieu des pierres de feu lançant des flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 17, 'Ton cœur s’est enorgueilli de ta beauté; ta science a péri avec ta beauté. À cause de la multitude de tes péchés, je t’ai jeté à terre, je t’ai rendu infâme en présence de tous les rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 18, 'À cause de la multitude de tes péchés et de l’iniquité de tes trafics, j’ai souillé tes choses saintes; et je ferai sortir du milieu de toi un feu qui te dévorera; et je te réduirai en cendres sur la terre aux yeux de tous ceux qui te verront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 19, 'Et tous ceux qui te connaissent parmi les nations gémiront sur toi. Tu es anéanti, et tu ne seras plus dans les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 20, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 21, 'Fils de l’homme, tourne ton visage contre Sidon, et prophétise contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 22, 'Et je dis Ainsi parle le Seigneur: Voilà que je suis contre toi, Sidon, et je serai glorifié en toi, et tu connaîtras que je suis le Seigneur, lorsque j’aurai exercé mes jugements sur toi, et que je serai sanctifié en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 23, 'Le sang et la mort seront sur tes places, et autour de toi tomberont ceux que chez toi le glaive aura blessés; et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 24, 'Et il n’y aura plus dans la maison d’Israël d’aiguillon d’amertume ni d’épine de douleur venant de ceux qui l’entourent; et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 25, 'Voici ce que dit le Seigneur Maître: Alors je rassemblerai Israël d’entre les nations où il a été dispersé; et je serai sanctifié en lui, devant les peuples et les nations; et ils demeureront en leur terre, que j’ai donnée à mon serviteur Jacob.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 26, 'Et ils l’habiteront pleins d’espérance; et ils bâtiront des maisons, et ils planteront des vignes, et ils habiteront leur terre, pleins d’espérance, lorsque j’aurai exercé mes jugements sur tous ceux qui les entourent et qui les ont méprisés; et ils sauront que je suis le Seigneur leur Dieu, et le Dieu de leurs pères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 1, 'En la douzième année, le dixième mois, le premier jour du mois, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 2, 'Fils de l’homme, tourne ton visage contre le Pharaon, roi d’Égypte, et prophétise contre lui et contre l’Égypte entière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 3, 'Et dis Ainsi parle le Seigneur: Voilà que je suis contre toi, Pharaon, grand dragon couché au milieu de tes fleuves, et disant: Les fleuves sont à moi, c’est moi qui les ai créés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 4, 'Je mettrai un hameçon dans tes mâchoires; je collerai à tes nageoires les poissons de ton fleuve, et je te tirerai du milieu de ton fleuve.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 5, 'Et je te jetterai soudain sur le rivage avec tous les poissons de ton fleuve. Tu tomberas sur la face de la terre; tu ne seras pas relevé; tu ne seras pas enseveli; je t’ai donné en pâture aux bêtes de la terre et aux oiseaux du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 6, 'Et tous ceux qui habitent l’Égypte sauront que je suis le Seigneur. En punition de ce que tu as été pour la maison d’Israël un appui faible comme un roseau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 7, 'Lorsqu’elle te tenait par la main, tu as plié; et lorsque par dérision on l’applaudissait des mains, et qu’elle se reposait sur toi, tu t’es brisé, et tu lui as rompu les reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 8, 'À cause de cela, ainsi dit le Seigneur: Voilà que je tire contre toi le glaive, et j’exterminerai les hommes et le bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 9, 'Et il y aura ruine et désolation en la terre d’Égypte; et ils sauront que je suis le Seigneur; en punition de ce que tu as dit: Les fleuves sont à moi, c’est moi qui les ai créés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 10, 'En punition de cela, voilà que je suis contre toi et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 11, 'Le pied de l’homme n’y posera plus, les troupeaux n’y passeront plus, et pendant quarante ans elle ne sera plus habitée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 12, 'Et je mettrai la terre d’Égypte au rang d’une terre déserte, et ses villes seront au rang des villes désertes pendant quarante ans. Et je disperserai l’Égypte parmi les nations, et je vannerai son peuple en tous lieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 13, 'Et voici ce que dit le Seigneur: Après quarante ans, je rassemblerai les Égyptiens d’entre les nations où ils auront été dispersés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 14, 'Et je ferai rentrer les Égyptiens captifs, et je les établirai en la terre de Phathorès, en la terre d’où ils auront été enlevés; et ce sera un royaume humilié');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 15, 'Plus qu’aucun autre royaume. Elle ne s’élèvera plus au-dessus des nations; je les aurai réduits à un petit nombre pour qu’ils ne soient plus les plus grands parmi les peuples.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 16, 'Et ils ne seront plus pour la maison d’Israël un espoir en qui elle ait confiance, lui rappelant son iniquité, lorsqu’elle se mit à leur suite; et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 17, 'Et la vingt-septième année, le premier jour du premier mois, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 18, 'Fils de l’homme, Nabuchodonosor, roi de Babylone, a fait servir son armée à frapper Tyr d’une grande servitude; toute tête y est devenue chauve, toute épaule ensanglantée. Et ni lui ni son armée n’ont reçu de salaire pour m’avoir servi contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 19, 'Ainsi dit le Seigneur Maître: Voilà que je donne à Nabuchodonosor la terre d’Égypte, et il en fera sa proie, et il en enlèvera des dépouilles; ce sera le salaire de son armée;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 20, 'En récompense du service qu’il m’a rendu contre Tyr, je lui donne la terre d’Égypte; voici ce que dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 29, 21, 'En ce jour une corne sortira du front de toute la maison d’Israël; et, au milieu d’elle, je t’ouvrirai la houche, et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 2, 'Fils de l’homme, prophétise et dis: Voici ce que dit le Seigneur: Malheur, malheur en ce jour!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 3, 'Car le jour du Seigneur est proche; c’est un jour de nuages; c’est la fin des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 4, 'Et le glaive viendra sur l’Égypte, et le trouble sera dans l’Éthiopie, et les morts tomberont tous à la fois en la terre d’Égypte, et avec eux tomberont ses fondements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 5, 'Perses et Crétois, Lydiens et Libyens, et tous ceux parmi les fils de mon alliance qui se seront mêlés à ces peuples, périront chez elle par le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 6, 'Et les appuis de l’Égypte s’écrouleront, et l’orgueil de sa force sera abaissé de Magdolos à Syène; et ils périront par le glaive, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 7, 'Et elle sera au rang des terres désertes, et ses villes au rang des villes désertes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 8, 'Et l’on saura que je suis le Seigneur, lorsque j’aurai');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 9, 'En ce jour, des messagers partiront rapidement pour détruire l’Éthiopie, et le trouble sera en elle au jour fatal de l’Égypte; et voilà que ce jour approche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 10, 'Voici ce que dit le Seigneur Maître: Je détruirai la multitude des Égyptiens par la main de Nabuchodonosor, roi de Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 11, 'Par sa main et celle de son peuple, comme des fléaux envoyés des nations pour détruire la terre. Et tous s’avanceront l’épée nue sur l’Égypte, et la terre sera pleine de blessés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 12, 'Et je dessècherai leurs fleuves, et je détruirai leur terre et leur richesse, par les mains des étrangers; moi, le Seigneur, j’ai parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 13, 'Car voici ce que dit le Seigneur Maître: Je détruirai les grands de Memphis, et les princes de Memphis de la terre d’Égypte, et ils ne seront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 14, 'Et je détruirai la terre de Phathorès, et je lancerai le feu contre Taphnis, et je tirerai vengeance de Diospolis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 15, 'Et je verserai ma colère sur Saïs, la force de l’Égypte, et je détruirai la multitude de Memphis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 16, 'Et je lancerai le feu sur l’Égypte, et Syène sera dans un grand trouble, et il y aura une inondation à Diospolis, et les eaux s’y répandront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 17, 'Les jeunes hommes d’Héliopolis et de Bubaste périront par le glaive, et les femmes s’en iront en captivité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 18, 'Et le jour sera obscurci à Taphnis lorsque j’y');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 19, 'Et j’exercerai mes jugements contre l’Égypte, et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 20, 'Et en l’année onzième, le premier mois, le septième jour du mois, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 21, 'Fils de l’homme, j’ai brisé les bras du Pharaon, roi d’Égypte, et voilà qu’il n’a point été entouré de bandes pour que ses plaies guérissent, pour qu’un baume y soit appliqué, pour qu’il recouvre la force de tenir un glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 22, 'À cause de cela, ainsi dit le Seigneur Maître: Voilà que je suis contre le Pharaon, roi d’Égypte, et je briserai ses bras forts et tendus, et je ferai tomber l’épée de sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 23, 'Et je disperserai l’Égypte parmi les nations, et je les vannerai sur la terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 24, 'Et je fortifierai les bras du roi de Babylone, et je lui mettrai le glaive à la main, et il le promènera sur l’Égypte, et il fera de l’Égypte sa proie, et il en enlèvera des dépouilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 25, 'Et je fortifierai les bras du roi de Babylone, et les bras du Pharaon tomberont défaillants, et l’on saura que je suis le Seigneur, quand j’aurai mis mon glaive à la main du roi de Babylone, et qu’il l’étendra sur la terre d’Égypte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 30, 26, 'Et je disperserai l’Égypte parmi les nations, et je les vannerai sur la terre; et ils sauront tous que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 1, 'Et en l’année onzième, le troisième mois, le premier jour du mois, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 2, 'Fils de l’homme, dis au Pharaon, roi d’Égypte, et à son peuple: À qui t’es-tu comparé en ton orgueil?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 3, 'Voilà qu’Assur était un cyprès du Liban, et il était beau par ses branches, par la hauteur de sa tige et par sa cime s’élevant au milieu des nuées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 4, 'Les eaux l’avaient nourri; l’abîme l’avait fait croître en conduisant ses fleuves autour de ses racines, et ses ondes se répandaient vers tous les arbres des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 5, 'Aussi dépassait-il en hauteur tous les arbres des champs, et ses rameaux s’étaient déployés, grâce à l’abondance des eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 6, 'Tous les oiseaux du ciel faisaient leurs nids dans ses branches, et toutes les bêtes des champs mettaient bas sous son feuillage, une multitude de nations habitaient sous son ombre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 7, 'Il était beau par sa grandeur et par la multitude de ses rameaux; car ses racines étaient arrosées d’une eau abondante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 8, 'Tels sont les cyprès du paradis de Dieu; les pins ne peuvent lui être comparés pour leurs rejetons; les sapins ne peuvent lui être comparés pour leurs rameaux; nul autre arbre du paradis de Dieu ne lui ressemble en beauté,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 9, 'Pour la multitude de ses rameaux. Et les arbres du paradis de délices de Dieu lui portaient envie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 10, 'À cause de cela, voici ce que dit le Seigneur: En');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 11, 'Je l’ai livré aux mains du prince des nations, et il a préparé sa ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 12, 'Et des hommes de pestilence, des étrangers, venus des nations, l’ont détruit, et ils l’ont abattu sur les montagnes; ses rameaux sont tombés dans tous les vallons; sa tige a été brisée dans toutes les plaines de la terre, et tous les peuples des nations se sont retirés de son ombre, et ils l’ont rasé au niveau du sol.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 13, 'Sur ses ruines se sont reposés tous les oiseaux du ciel, et toutes les bêtes des champs se sont blotties sous ses grosses branches;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 14, 'Afin que nul des arbres qui croissent au bord des eaux ne se glorifiât de sa grandeur. Ils ont élevé leur cime Iau milieu des nues; mais ils ne se maintiendront pas en leur élévation; tous ces arbres, baignés des eaux, ont tous été donnés à la mort; ils iront tous au fond de la terre, au milieu des fils des hommes, avec ceux qui descendent à l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 15, 'Et voici ce que dit le Seigneur Maître: Le jour où cet arbre est descendu aux enfers, l’abîme a pleuré sur lui. Et j’ai suspendu le cours de tous ses fleuves, et j’ai arrêté les grandes eaux qui l’arrosaient; et le Liban, à cause de lui, s’est couvert de ténèbres, et tous les arbres se sont affaissés de douleur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 16, 'Au bruit de sa chute, les nations ont tremblé; car je l’ai fait descendre aux enfers avec ceux qui étaient tombés dans l’abîme; et tous les arbres de délices de la');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 17, 'Et ceux-là aussi sont descendus avec lui aux enfers, parmi les morts frappés par le glaive; et sa race, qui demeurait sous son abri, a péri au milieu de sa vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 31, 18, 'À quoi te comparer? Descends; sois entraîné, avec tous les arbres de délices, au plus profond de la terre; tu seras étendu au milieu des incirconcis avec les morts frappés par le glaive. Tel sera le Pharaon, telle sera la multitude qui faisait sa force, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 1, 'En la dixième année, le dixième mois, le premier jour du mois, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 2, 'Fils de l’homme, fais une lamentation sur le Pharaon, roi d’Égypte, et dis-lui: Tu étais semblable au lion des peuples et au dragon de la mer; tu frappais tes fleuves de la corne; tu troublais l’eau sous tes pieds; tu marchais sur tes fleuves.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 3, 'Or voici ce que dit le Seigneur: Je jetterai sur toi un filet formé d’une multitude de peuples, et je t’amènerai avec mon hameçon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 4, 'Et je t’étendrai sur le rivage, et tu couvriras les champs; et je ferai reposer sur toi tous les oiseaux du ciel, et je rassasierai de ta chair toutes les bêtes fauves de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 5, 'Et je donnerai ta chair aux montagnes, et je les remplirai de ton sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 6, 'Et sur les montagnes la terre s’abreuvera de la');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 7, 'Et je cacherai le ciel, lorsque tu t’étendras; et j’obscurcirai ses étoiles; je voilerai le soleil d’un nuage, et la lune ne fera plus briller sa lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 8, 'Tout ce qui luit au ciel sera sombre sur toi, et je répandrai les ténèbres sur la terre, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 9, 'Et je soulèverai contre toi le cœur d’une multitude de peuples, quand j’emmènerai tes captifs chez les nations, en une terre que tu ne connaissais pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 10, 'Et maintes nations te lanceront des regards d’épouvante, et leurs rois seront saisis de stupeur, lorsque mon glaive volera devant leur face, et qu’ils pressentiront leur ruine en voyant le jour de ta ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 11, 'Car voici ce que dit le Seigneur Maître: Le glaive du roi de Babylone viendra sur toi');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 12, 'Avec des épées de géants, et j’abattrai ta puissance; et des hommes de pestilence venant tous des nations seront avec lui, et ils détruiront l’orgueil de l’Égypte, et toute sa puissance sera brisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 13, 'Et je ferai périr tous les troupeaux qu’elle nourrissait le long des grandes eaux; et le pied de l’homme ne la troublera plus, et les ongles des troupeaux ne la fouleront plus jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 14, 'Alors leurs eaux redeviendront calmes, et leurs fleuves couleront comme de l’huile, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 15, 'Lorsque je livrerai l’Égypte à la destruction, la terre et tout ce qu’elle renferme deviendra un désert; et je disperserai tous ceux qui l’habitent, et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 16, 'Telle est la lamentation que tu répèteras, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 17, 'Et la douzième année, le premier mois, le quinzième jour du mois, la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 18, 'Fils de l’homme, lamente-toi sur la puissance de l’Égypte, car les nations feront descendre ses filles mortes au fond de la terre, parmi ceux qui descendent à l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 19, '20. Et ils tomberont avec leur roi dans la foule frappée par le glaive, et toute sa puissance périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 21, 'Et les géants te diront: Reste au fond de l’abîme; qui est moindre que toi? Descends et dors avec les incirconcis, au milieu des morts frappés du glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 22, 'Là est Assur avec tout son peuple; là sont tous ceux que le glaive a tués.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 23, 'Et leur sépulture est au fond de l’abîme, et le peuple d’Assur est autour de son monument; ce sont tous les morts qui sont tombés sous le glaive, et qui sur la terre de vie avaient inspiré de l’effroi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 24, 'Là est Élam, avec toute son armée autour de son monument; ce sont tous les morts qui sont tombés sous le glaive et qui sont descendus incirconcis dans l’abîme, et qui sur la terre de vie avaient inspiré de l’effroi. Et ils ont subi leur châtiment avec ceux qui sont descendus dans l’abîme,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 25, 'Au milieu des cadavres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 26, 'Là ont été livrés Mosoch et Thobel, et toutes leurs forces; et tous leurs morts entourent leur monument, tous incirconcis frappés du glaive, et qui sur la terre de vie inspirèrent de l’effroi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 27, 'Et ils dorment avec les géants qui sont tombés');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 28, 'Et toi aussi, tu dormiras au milieu des incirconcis, avec les morts que le glaive a frappés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 29, 'Là sont les princes d’Assur, dont la force n’a pas résisté à la blessure du glaive; ils dorment avec ceux que le glaive a tués, avec ceux qui sont descendus dans l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 30, 'Là sont les princes de l’Aquilon, tous capitaines d’Assur, qui sont descendus blessés; ils dorment incirconcis avec leur force, avec l’effroi qu’ils inspiraient, parmi ceux que le glaive a tués; et ils ont reçu leur châtiment avec ceux qui sont descendus dans l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 31, 'Le roi Pharaon les verra, et il sera consolé en voyant toute cette multitude, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 32, 32, 'Car j’ai répandu la crainte de ce qu’il avait craint lui-même sur la terre de vie; et lui, Pharaon, et tout son peuple dormiront parmi les incirconcis, avec ceux qui ont péri par le glaive, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 2, 'Fils de l’homme, parle aux enfants de ton peuple, et dis-leur: En toute terre où je conduirai le glaive, et où le peuple, ayant pris l’un de ses hommes, l’aura mis en sentinelle;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 3, 'Si cet homme, voyant le glaive venir sur cette terre, sonne de la trompette pour donner l’alarme au peuple,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 4, 'Et si celui qui entend le son de la trompette prête l’oreille et ne se met point sur ses gardes, le glaive viendra et le surprendra; et son sang retombera sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 5, 'Si donc, après avoir entendu le son de la trompette, il ne s’est pas mis sur ses gardes, son sang retombera sur lui; et tel autre qui se sera mis sur ses gardes aura sauvé son âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 6, 'Et si la sentinelle, ayant vu le glaive venir, n’a point sonné de la trompette, si le peuple ne s’est pas mis sur ses gardes, si le glaive, survenant parmi eux, prend une âme, cette âme est prise à cause de son iniquité; mais tout ce sang, je le réclamerai de la main de la sentinelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 7, 'Et toi, fils de l’homme, je t’ai mis en sentinelle pour la maison de Jacob, et tu écouteras toute parole de ma bouche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 8, 'Si je dis au pécheur: Tu mourras de mort; et que tu ne parles pas pour avertir l’impie de se retirer de ses voies, lui-même, l’impie, mourra en son iniquité; mais son sang, je le réclamerai de ta main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 9, 'Que si tu as averti l’impie de se retirer de sa voie, et qu’il ne s’en retire pas, il mourra en son impiété, mais tu auras sauvé ton âme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 10, 'Et toi, fils de l’homme, dis à la maison d’Israël: Voici ce que vous dites: Nos fautes et nos iniquités sont sur nous, nous languissons à cause d’elles; et comment vivrons-nous?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 11, 'Réponds-leur: Par ma vie, dit le Seigneur, je ne');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 12, 'Dis aux enfants de mon peuple: La justice du juste ne le sauvera point le jour où il s’égare; l’iniquité de l’impie ne le perdra pas le jour où il sortira de son iniquité; et le juste même ne pourra être sauvé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 13, 'Lorsque j’aurai dit au juste: Tu vivras; si, se confiant à sa justice, il commet une iniquité, toutes ses actions justes seront mises en oubli; il mourra dans l’iniquité qu’il aura commise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 14, 'Lorsque j’aurai dit à l’impie Tu mourras de mort; s’il se retire de son péché, je le jugerai et le traiterai avec justice et discernement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 15, 'S’il rend le gage, s’il restitue ce qu’il a dérobé, s’il marche dans les commandements de vie et ne fait rien d’inique, il vivra et ne mourra point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 16, 'Tous ses péchés seront mis en oubli; et parce qu’il aura pratiqué l’équité et la justice, il vivra dans sa justice et son équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 17, 'Les fils de mon peuple diront encore: La voie du Seigneur n’est pas droite. Mais c’est leur voie qui n’est pas droite!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 18, 'Le juste qui se détournera de sa justice et fera des iniquités mourra dans ses iniquités.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 19, 'Le pécheur qui sortira de son iniquité et agira selon l’équité et la justice, vivra dans la justice et l’équité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 20, 'Et voici ce que vous dites: La voie du Seigneur n’est pas droite! Je vous jugerai tous, chacun selon sa voie, maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 21, 'Et en la douzième année de notre captivité, le douzième mois, le cinquième jour du mois, un homme');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 22, 'Et avant qu’il vînt, le soir, la main du Seigneur avait été sur moi; et le Seigneur m’ouvrit la bouche, quand le matin cet homme vint chez moi. Et ma bouche ouverte ne put se contenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 23, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 24, 'Fils de l’homme, ceux qui habitent les villes dévastées de la terre d’Israël disent: Abraham était seul, et il a possédé cette terre; nous, nous sommes nombreux; c’est donc à nous que cette terre a été donnée pour héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 25, 'À cause de cela, réponds-leur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 26, '27. Voici ce que dit le Seigneur Maître: Par ma vie, ceux qui sont en ces villes désolées périront par le glaive; et ceux qui demeurent aux champs seront donnés en pâture aux bêtes sauvages; et je ferai mourir de mort ceux qui sont dans des forteresses et dans des cavernes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 28, 'Et je ferai de la terre un désert; et la superbe de leur force périra; et les montagnes d’Israël seront une solitude, car nul n’y passera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 29, 'Et ils sauront que je suis le Seigneur; et je ferai de leur héritage un désert, et il sera dévasté à cause de toutes les abominations qu’ils y ont commises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 30, 'Et toi, fils de l’homme, les enfants de ton peuple parlent de toi dans leurs demeures, et devant les portes de leurs maisons, et ils se disent l’un à l’autre: Allons ensemble, et écoutons quelles paroles nous viennent aujourd’hui du Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 31, 'Ils s’approchent de toi comme un peuple qui s’as');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 32, 'Et tu es pour eux comme le son d’une harpe douce et harmonieuse; et ils écoutent tes paroles, mais ils ne les pratiquent point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 33, 33, 'Et quand le jour sera venu ils diront: Voilà que les choses sont accomplies; et ils sauront alors qu’au milieu d’eux il y avait un prophète.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 2, 'Fils de l’homme, prophétise contre les pasteurs d’Israël; prophétise, et dis aux pasteurs: Voici ce que dit le Seigneur Maître: Malheur aux pasteurs d’Israël! Est-ce que les pasteurs se paissent eux-mêmes? Est-ce que les pasteurs ne doivent pas paître les brebis?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 3, 'Voilà que vous mangez le laitage; vous vous faites des vêtements avec la laine; vous égorgez les bêtes les plus grasses; vous ne paissez point mes brebis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 4, 'Vous n’avez point fortifié les faibles, vous n’avez point guéri les malades, vous n’avez point entouré de bandes les blessées, vous n’avez point ramené les égarées; vous n’avez point cherché ce qui était perdu; et ce qui était plein de force, vous l’avez accablé de labeurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 5, 'Aussi mes brebis ont été dispersées, parce qu’elles n’avaient pas de pasteurs; et elles ont été la pâture des bêtes fauves des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 6, 'Et mes brebis ont été dispersées dans toutes les montagnes et sur toutes les hautes collines; elles ont');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 7, 'À cause de cela, pasteurs, écoutez la parole du Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 8, 'Par ma vie, dit le Seigneur Maître, en punition de ce que mes brebis ont été une proie, de ce que mes brebis ont été dévorées par toutes les bêtes fauves des champs, parce qu’elles n’avaient pas de pasteurs, et que les pasteurs ne cherchaient pas mes brebis, et que les pasteurs se paissaient eux-mêmes et ne paissaient pas mes brebis;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 9, 'En punition de cela, pasteurs,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 10, 'Ainsi dit le Seigneur Maître: Voilà que je suis contre les pasteurs, et je réclamerai mes brebis de leurs mains, et je les empêcherai de paître mes brebis, et les pasteurs ne les feront plus paître; je retirerai mes brebis de leur bouche, et ils ne s’en nourriront plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 11, 'Car ainsi dit le Seigneur Maître: Voilà que je vais moi-même chercher mes brebis, et je les visiterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 12, 'Tel le pâtre cherche ses troupeaux le jour où il y a des nuages et des ténèbres, au milieu des brebis dispersées, tel je chercherai mes brebis, et je les ramènerai de tous les lieux où elles auront été dispersées dans les jours de ténèbres et de nuages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 13, 'Et je les retirerai d’entre les nations, et je les réunirai de toutes les contrées, et je les ferai rentrer dans leur terre, et je les ferai paître sur la montagne d’Israël, et dans tous les vallons et dans tous les lieux habités de leur héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 14, 'Je les ferai paître en un bon pâturage, sur la haute montagne d’Israël; et c’est là que seront leurs berge');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 15, 'Moi-même je ferai paître mes brebis; je leur donnerai moi-même le repos; et elles sauront que je suis le Seigneur Maître. Voici ce que dit le Seigneur Maître:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 16, 'Je chercherai celle qui sera perdue; je ramènerai celle qui sera égarée; j’entourerai de bandes celle qui sera blessée; je fortifierai les faibles; je veillerai sur les fortes, et je les ferai paître selon la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 17, 'Et vous, brebis, dit le Seigneur Maître, voilà que je distinguerai entre brebis et brebis, entre boucs et béliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 18, 'Ne vous suffisait-il pas de brouter un bon pâturage? Pourquoi fouler aux pieds le reste de votre pâturage? Ne vous suffisait-il pas de boire de l’eau paisible? Pourquoi troubler encore de vos pieds ce que vous n’aviez pas bu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 19, 'Mes autres brebis n’ont-elles pas brouté l’herbe que vos pieds avaient foulée? N’ont-elles pas bu l’eau que vous aviez troublée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 20, 'À cause de cela, voici ce que dit le Seigneur Maître: Je distinguerai entre les brebis fortes et les brebis faibles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 21, 'Vous heurtiez de vos flancs et de vos épaules, vous frappiez de vos cornes, vous opprimiez toute brebis faible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 22, 'Et moi je sauverai mes brebis, et elles ne seront plus une proie, et je jugerai entre bélier et bélier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 23, 'Et je susciterai pour eux un seul pasteur, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 24, 'Et moi, le Seigneur, je serai leur Dieu, et David, au milieu d’eux, sera leur roi. Moi, le Seigneur, j’ai parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 25, 'Et je ferai avec David une alliance de paix, et je ferai disparaître de la terre les bêtes malfaisantes, et l’on habitera le désert, et l’on dormira dans les forêts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 26, 'Et je donnerai à mes brebis tout le contour de ma montagne; et je leur donnerai de la pluie, une pluie de bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 27, 'Et les terres des champs produiront leurs fruits; et la terre aura toute sa fertilité; et mes brebis habiteront leur héritage dans l’espérance de la paix; et elles sauront que je suis le Seigneur quand j’aurai brisé leur joug, et que je les aurai retirées des mains de ceux qui les ont asservies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 28, 'Et elles ne seront plus livrées en proie aux nations; et les bêtes fauves ne les dévoreront plus, et elles habiteront leur héritage dans l’espérance, et nul ne les épouvantera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 29, 'Et je ferai naître pour elles une plante de paix, et elles ne périront plus par la famine sur la terre, et elles ne subiront plus les outrages des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 30, 'Et elles sauront que je suis le Seigneur leur Dieu, et qu’elles sont mon peuple. Maison d’Israël, dit le Seigneur Maître,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 34, 31, 'Vous êtes mes brebis, les brebis de mon troupeau; et je suis votre Dieu, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 2, 'Fils de l’homme, tourne ton visage contre la montagne de Séir, prophétise contre elle, et dis-lui:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 3, 'Ainsi dit le Seigneur: Voilà que je suis contre toi, montagne de Séir, et j’étendrai sur toi la main, et je ferai de toi un désert, et tu seras dépeuplée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 4, 'Et tes villes seront désertes, et tu seras un désert, et tu sauras que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 5, 'En punition de ton inimitié perpétuelle, et de ce que tu as tendu des embûches à la maison de Jacob, quand ses ennemis avaient le glaive à la main, au temps de son iniquité, lorsqu’elle était à son comble;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 6, 'En punition de cela, par ma vie, dit le Seigneur Maître, puisque tu as péché dans le sang, le sang te poursuivra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 7, 'Et je ferai de la montagne de Séir un désert, et elle sera dépeuplée, et j’y détruirai hommes et bétail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 8, 'Et je remplirai de cadavres tes collines et tes vallées, et dans toutes tes plaines tomberont des morts percés du glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 9, 'Je ferai de toi un désert éternel, et tes villes ne seront plus habitées, et tu sauras que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 10, 'Parce que tu as dit: Deux nations et deux terres seront à moi, et je les aurai pour héritage, et le Seigneur y réside;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 11, 'À cause de cela, par ma vie, dit le Seigneur, je te traiterai selon ta haine, et je me ferai connaître à toi, lorsque je te jugerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 12, 'Et tu sauras que je suis le Seigneur. J’ai entendu la voix de tes blasphèmes, quand tu as dit: Les montagnes d’Israël, devenues désertes, nous ont été données pour que nous les dévorions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 13, 'Et ta bouche a dit contre moi des paroles superbes, et j’ai tout entendu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 14, 'Voici ce que dit le Seigneur: À la joie de toute la terre, je te rendrai déserte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 35, 15, 'Tu seras un désert, montagne de Séir, et toute l’Idumée sera détruite, et tu sauras que je suis le Seigneur leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 1, 'Ettoi, fils de l’homme, prophétise pour les montagnes d’Israël; montagnes d’Israël, écoutez la parole du Seigneur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 2, 'Voici ce que dit le Seigneur Maître: Parce que l’ennemi a dit contre vous: Bien, ces déserts éternels seront désormais en notre possession;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 3, 'À cause de cela, prophétise et dis: Parce que vous avez été méprisées, dit le Seigneur Maître, parce que vous avez été haïes de tous les peuples d’alentour, que vous avez été au pouvoir du reste des nations, et que vous êtes devenues leur fable et le sujet de leurs outrages;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 4, 'À cause de cela, montagnes d’Israël, écoutez la parole du Seigneur; voici ce que dit le Seigneur aux montagnes et aux collines, aux torrents et aux vallées, à ces lieux qui ont été désolés et détruits, et aux villes qui ont été abandonnées, pillées et foulées aux pieds par les nations laissées alentour;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 5, 'À cause de cela: Puisque dans le feu de ma colère, dit le Seigneur Maître, j’ai parlé contre les autres nations et contre toute l’Idumée, pour s’être approprié avec joie ma terre comme leur héritage, méprisant les âmes, quand il s’agissait de piller et de détruire;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 6, 'Prophétise donc en faveur de la terre d’Israël, et dis aux montagnes et aux collines, aux vallées et aux forêts Ainsi dit le Seigneur: Voilà que j’ai parlé dans ma jalousie et ma colère, parce que vous avez subi les outrages des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 7, 'Je lèverai la main contre les nations qui vous entourent; elles-mêmes porteront la peine de leurs outrages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 8, 'Et vous, montagnes d’Israël, mon peuple mangera vos grappes et vos fruits; car ils espèrent revenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 9, 'Voilà que je suis près de vous, et je me retournerai vers vous, et vous serez labourées, et vous serez ensemencées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 10, 'Sur vous je multiplierai les hommes, et toute la maison d’Israël, jusqu’à ce qu’elle soit complète; et les villes seront habitées, et les déserts couverts de demeures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 11, 'Et je multiplierai sur vous les hommes et les troupeaux, et je vous rendrai peuplées comme en vos premiers jours, et je vous comblerai de biens comme jadis; et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 12, 'Et je ferai naître sur vous des hommes, mon peuple Israël; et ils vous possèderont, et vous serez leur héritage; et jamais plus vous ne serez sans enfants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 13, 'Voici ce que dit le Seigneur Maître: Parce que l’on t’a dit: Tu es une terre qui dévore les hommes, et que tu as été privée de ta nation et de tes enfants;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 14, 'À cause de cela, tu ne dévoreras plus les hommes et tu ne seras plus privée de ta nation ni de tes enfants, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 15, 'Et l’on n’entendra plus contre vous les injures des gentils, et vous ne subirez plus les outrages des peuples, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 16, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 17, 'Fils de l’homme, la maison d’Israël a demeuré sur sa terre; et ils l’ont souillée en leurs voies par leurs idoles et leurs impuretés; et leurs voies sont devenues à mes yeux comme la souillure d’une femme en son impureté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 18, 'Et j’ai répandu sur eux ma colère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 19, 'Et je les ai dispersés parmi les nations, et je les ai vannés à travers les royaumes; car je les ai jugés selon leur voie et selon leur péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 20, 'Et ils se sont mêlés aux nations où ils étaient entrés, et ils ont profané mon saint nom; car les nations disaient Voilà le peuple du Seigneur; voilà ceux qui sont sortis de son héritage!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 21, 'Cependant je les ai épargnés à cause de mon saint nom que la maison d’Israël avait profané chez les nations où elle était allée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 22, 'À cause de cela, dis à la maison d’Israël: Je ne fais point cela à cause de vous, dit le Seigneur, mais à cause de mon saint nom, que vous avez profané chez les nations où vous êtes allés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 23, 'Et je sanctifierai mon grand nom, ce nom profané parmi les gentils, profané par vous au milieu d’eux; et les nations sauront que je suis le Seigneur quand j’aurai été sanctifié par vous devant leurs yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 24, 'Et je vous retirerai des nations, et je vous rassemblerai de toutes les contrées, et je vous ramènerai en votre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 25, 'Et je vous arroserai d’une eau pure, et vous serez purifiés de toutes vos impuretés et de toutes vos idoles, et je vous purifierai moi-même;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 26, 'Je vous donnerai un nouveau cœur, et je mettrai en vous un esprit nouveau; j’ôterai de votre sein votre cœur de roche, et j’y placerai un cœur de chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 27, 'Et je mettrai en vous mon esprit, et je vous ferai marcher dans la voie de mes ordonnances, et vous garderez mes jugements, et vous les mettrez en pratique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 28, 'Et vous demeurerez en la terre que j’ai donnée à vos pères; et vous serez mon peuple, et moi, je serai votre Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 29, 'Et je vous sauverai de toutes vos impuretés; et j’appellerai le froment, et je le multiplierai, et je ne ferai point venir sur vous la famine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 30, 'Et je multiplierai les fruits de l’arbre et les récoltes du champ, afin que vous ne subissiez plus l’outrage de la faim parmi les nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 31, 'Et vous vous souviendrez alors de vos voies corrompues et de vos habitudes déréglées; et vous vous détesterez vous-mêmes, en considérant vos péchés et les abominations de vos idoles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 32, 'Mais je ne ferai point cela à cause de vous, dit le Seigneur Maître; sachez-le bien. Soyez donc honteuse et confuse, maison d’Israël, à cause de vos voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 33, 'Voici ce que dit Adonaï le Seigneur: Le jour où je vous purifierai de toutes vos iniquités, où je repeu-plerai vos villes, où l’on rebâtira des demeures dans les-lieux dévastés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 34, 'Où cette terre désolée sera cultivée, au lieu d’être effacée, comme elle l’était aux yeux de tous les passants;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 35, 'Ils diront: Cette terre ravagée est devenue comme un jardin de délices; ses villes, jadis dépeuplées, détruites, abattues, sont relevées maintenant et fortifiées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 36, 'Et les autres nations, toutes celles qui vous entourent encore, sauront que moi, le Seigneur, j’ai réédifié des ruines et replanté des terres en friche; moi, le Seigneur, j’ai parlé, et j’exécuterai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 37, 'Voici ce que dit encore Adonaï le Seigneur: La maison d’Israël me demandera en outre une chose, et je la lui accorderai: je multiplierai chez eux les hommes comme des troupeaux de brebis,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 36, 38, 'Comme des brebis saintes, comme les brebis de Jérusalem en ses fêtes. Ainsi les villes dépeuplées seront remplies de troupeaux d’hommes, et ils sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 1, 'Et la main du Seigneur fut sur moi, et le Seigneur me ravit en esprit; et il me déposa au milieu d’un champ, et ce champ était rempli d’ossements humains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 2, 'Et le Seigneur me conduisit tout autour de ces os,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 3, 'Et le Seigneur me dit: Fils de l’homme, ces os revivront-ils? Et je répondis: Seigneur, Seigneur, vous le savez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 4, 'Et il me dit: Prophétise sur ces ossements, et disleur: Ossements desséchés, écoutez la parole du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 5, 'Or voici ce que dit le Seigneur à ces ossements: Je vais amener sur vous un souffle de vie,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 6, 'Et je poserai sur vous des nerfs, et j’amènerai sur vous des chairs, et sur vous j’étendrai de la peau, et je mettrai en vous mon souffle, et vous vivrez, et vous saurez que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 7, 'Et je prophétisai comme le Seigneur me l’avait · prescrit, et ceci advint pendant que je prophétisais: Voilà que les ossements s’agitèrent et vinrent se placer chacun dans sa jointure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 8, 'Et je regardai; et voilà que sur les os des nerfs et des chairs se produisirent, et de la peau les recouvrit; mais l’esprit n’était pas encore en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 9, 'Et le Seigneur me dit: Prophétise à l’esprit, prophétise, fils de l’homme, et dis à l’esprit: Voici ce que dit le Seigneur: Viens des quatre vents, et souffle dans ces morts, et qu’ils vivent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 10, 'Et je prophétisai comme le Seigneur me l’avait prescrit, et l’esprit entra dans les morts, et ils furent vivants, et ils se dressèrent sur leurs pieds en immense multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 11, 'Et le Seigneur me parla, disant: Fils de l’homme, ces os sont toute la maison d’Israël, et eux-mêmes disent: Nos ossements sont desséchés, notre espérance a péri, et nous sommes sans voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 12, 'À cause de cela, prophétise et dis: Voilà que');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 13, 'Et vous saurez que moi je suis le Seigneur, quand j’aurai ouvert vos sépulcres, et que de ces sépulcres j’aurai tiré mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 14, 'Et je vous donnerai mon esprit, et vous vivrez, et je vous établirai sur votre terre, et vous saurez que je suis le Seigneur. J’ai parlé, et j’exécuterai, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 15, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 16, 'Fils de l’homme, prends une baguette, et sur elle écris Juda et tous les enfants d’Israël de son parti. Prends une autre baguette, et écris sur elle: Pour Joseph; puis une baguette pour Éphraïm; inscris enfin tous les enfants appartenant à Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 17, 'Et tu les réuniras ensemble pour n’être qu’une baguette, après les avoir liées, et elles seront dans ta main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 18, 'Et ceci adviendra: Lorsque les enfants de ton peuple te diront: Ne nous expliqueras-tu point ce que cela signifie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 19, 'Tu leur diras: Ainsi parle le Seigneur: Voilà que je vais prendre la tribu de Joseph, qui est dans la main d’Ephraïm, et les tribus d’Israël qui appartiennent à celle-ci, et je les réunirai à la tribu de Juda, et elles ne formeront qu’une baguette dans la maison de Juda.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 20, 'Et les baguettes sur lesquelles tu as écrit seront en ta main en présence du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 21, 'Et tu leur diras: Ainsi parle le Seigneur Maître: Voilà que je vais retirer toute la maison d’Israël du milieu des nations où elle est entrée; je les rassemblerai d’entre toutes les contrées d’alentour, et je les ramènerai en la terre d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 22, 'Et j’en ferai une nation dans la terre qui m’appartient et sur les montagnes d’Israël. Et il y aura pour eux un seul prince, et ils ne formeront plus deux nations, et ils ne seront plus jamais divisés en deux royaumes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 23, 'Afin de ne plus se souiller de leurs idoles; et je les préserverai de tous les dérèglements où ils sont tombés, et je les purifierai; et ils seront mon peuple, et moi, le Seigneur, je serai leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 24, 'Et mon serviteur David sera prince au milieu d’eux; il y aura pour eux tous un seul pasteur, parce qu’ils marcheront dans la voie de mes ordonnances et qu’ils garderont mes commandements et les pratiqueront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 25, 'Et ils habiteront leur terre que j’ai donnée à mon serviteur Jacob, que leurs pères ont habitée; et euxmêmes y habiteront. Et David, mon serviteur, sera leur prince dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 26, 'Et je ferai avec eux une alliance de paix; et mon alliance avec eux sera éternelle. Et j’établirai au milieu d’eux mon sanctuaire dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 27, 'Et mon tabernacle sera chez eux, et je serai leur Dieu; et ils seront mon peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 37, 28, 'Et les nations sauront que je suis le Seigneur qui sanctifie les fils d’Israël, en établissant chez eux mon sanctuaire pour tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 1, 'Et la parole du Seigneur me vint, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 2, 'Fils de l’homme, tourne ton visage contre la terre de Magog et contre Gog, prince de Rhos, de Mésoch et de Thubal, et prophétise contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 3, 'Et dis-lui: Ainsi parle le Seigneur Maître: Voilà que je suis contre toi, prince de Rhos, de Mésoch et de Thubal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 4, 'Je rassemblerai ton peuple et toute ton armée, chevaux et cavaliers, tous portant cuirasse; troupe nombreuse armée d’écus, de casques et de glaives.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 5, 'Perses, Éthiopiens et Libyens, tous portant casque et bouclier,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 6, 'Gomer et tous ceux qui lui appartiennent, la maison de Thorgama aux dernières limites du nord, et tous ceux qui lui appartiennent, et beaucoup de nations seront avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 7, 'Prépare-toi, sois tout prêt, toi et toute ta troupe réunie autour de toi, et sois pour moi un rempart;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 8, 'Et il se préparera à la fin de bien des jours, et à la fin des temps il viendra, et il entrera dans une terre sauvée du glaive, quand les peuples de maintes nations étaient rassemblés contre la terre d’Israël, qui avait été entièrement dévastée; et il est venu d’entre les gentils, et ils habiteront tous en paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 9, 'Et tu te répandras comme la pluie; et comme une nuée tu viendras couvrir la terre, et tu seras là, toi et tous ceux qui t’appartiennent, et beaucoup de nations avec toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 10, 'Or voici ce que dit le Seigneur Maître: En ce jourlà ceci adviendra: des pensées s’élèveront en ton cœur, et tu concevras de mauvais desseins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 11, 'Et tu diras: J’entrerai en une terre répudiée; je marcherai contre des hommes qui vivent dans le repos, qui demeurent chez eux en paix, qui habitent une terre où il n’y a ni remparts, ni portes, ni verrous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 12, 'Saisis donc cette proie; pille ces dépouilles; porte les mains sur cette terre déserte et repeuplée, sur ce peuple rassemblé d’entre maintes nations, ayant acquis des richesses, et habitant l’intérieur des terres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 13, 'Saba et Dédan, les marchands de Carthage et toutes leurs villes te diront: Tu es venu pour saisir une proie et piller des dépouilles; tu as rassemblé tes troupes pour prendre de l’argent et de l’or, pour emporter des richesses et recueillir du butin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 14, 'À cause de cela, prophétise, fils de l’homme, et dis à Gog: Ainsi parle le Seigneur: N’est-ce pas dans le temps même où mon peuple Israël sera en paix dans sa demeure, que tu t’élèveras?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 15, 'Alors tu viendras des régions les plus lointaines du nord, et il y aura avec toi divers peuples, tous rassemblés en grand nombre, immense armée de cavaliers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 16, 'Et tu marcheras contre mon peuple d’Israël, comme une nuée qui vient couvrir la terre. Or ceci arrivera vers les jours de la fin: je te conduirai sur ma terre, afin que toutes les nations me connaissent quand devant elles je me sanctifierai en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 17, 'Voici ce que le Seigneur dit à Gog: Tu es celui de qui j’ai parlé dès les jours d’autrefois, par la voix de mes serviteurs les prophètes d’Israël, annonçant qu’en ces années et ces jours-là je te conduirais contre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 18, 'Et ceci adviendra: le jour où Gog viendra sur la terre d’Israël, dit le Seigneur Maître, ma colère éclatera');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 19, 'Avec ma jalousie; j’ai parlé dans le feu de ma colère; et, en vérité, ce jour-là il y aura un grand ébranlement dans la terre d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 20, 'Et les poissons de la mer trembleront en présence du Seigneur, ainsi que les oiseaux du ciel, et les bêtes des champs, et les reptiles qui se traînent à terre, et tous les hommes qui seront encore sur la face de la terre. Et les montagnes se fendront, et les vallons seront bouleversés, et toute muraille s’écroulera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 21, 'Mais alors contre lui-même j’appellerai tous les épouvantements, dit le Seigneur; et l’épée de l’homme se tournera contre son frère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 22, 'Et à mon tour j’exercerai sur lui mes jugements par la peste, par le sang, par les inondations, par une grêle de pierres; et je ferai tomber sur lui, sur ses compagnons et sur toutes les nations qui seront avec lui, une pluie de soufre et de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 38, 23, 'Et je serai célébré, et je serai sanctifié, et je serai glorifié; et je me ferai connaître devant maintes nations, et elles sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 1, 'Et toi, fils de l’homme, prophétise maintenant contre Gog, et dis: Ainsi parle le Seignenr: Voilà que je suis contre toi, Gog, prince de Rhos, de Mésoch et de Thubal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 2, 'Je réunirai tes troupes, et je te guiderai; je te ferai partir des régions les plus lointaines de l’aquilon, et je te conduirai sur les montagnes d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 3, 'Et alors je briserai ton arc dans ta main gauche, et tes flèches dans ta main droite, et je te renverserai');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 4, 'Sur les montagnes d’Israël; et tu tomberas, toi et ceux qui t’appartiennent; et les nations qui t’accompagnent seront données à la multitude des oiseaux; et je t’ai donné toi-même à tous les oiseaux et à toutes les bêtes fauves des champs pour qu’ils te dévorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 5, 'Tu tomberas sur la face de la terre; car moi j’ai parlé, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 6, 'Puis je lancerai la flamme sur Gog et sur les îles qui demeuraient en paix, et elles sauront que je suis le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 7, 'Et mon saint nom sera connu au milieu de mon peuple d’Israël, et ils ne profaneront plus mon saint nom, et les nations sauront que je suis le Seigneur saint en Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 8, 'Voilà que le jour est venu, et l’on saura qu’il est venu, dit le Seigneur; le voilà le jour dont j’avais parlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 9, 'Les habitants des villes en sortiront, et ils se chaufferont en brûlant les armes, les boucliers, les épieux, les arcs, les flèches, les bâtons et les javelines; et ils en allumeront leur feu pendant sept ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 10, 'Et ils ne prendront plus de bois dans les champs, et ils n’abattront plus d’arbres dans les forêts; mais ils feront du feu avec les armes, et ils pilleront ceux qui les ont pillés, et ils dépouilleront ceux qui les ont dépouillés, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 11, 'Et ceci adviendra en ce jour-là je donnerai à Gog une place de renom, un sépulcre en Israël; ce sera le cimetière des voyageurs du côté de la mer, et l’on entourera de murs l’entrée de la vallée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 12, 'Là on enterrera Gog et toute sa multitude, et on l’appellera le cimetière de Gog.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 13, 'Et la maison d’Israël les y enterrera, afin qu’en sept mois la terre soit purifiée; et tout le peuple de la terre les y enterrera; et ce sera pour eux une place de renom, le jour où Israel sera glorifié, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 14, 'Et ils ne cesseront pas d’envoyer des hommes qui parcourront la contrée pour ensevelir ceux qui seraient restés sur la face de la terre, et la purifier en sept mois; et ces hommes chercheront avec soin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 15, 'Et chacun de ceux qui parcourront la terre, à la vue d’un ossement hunain, placera auprès une marque, afin que les fossoyeurs l’enterrent dans la vallée, au cimetière de Gog.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 16, 'Car le nom de la vallée sera Cimetière; et la terre sera purifiée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 17, 'Et toi, fils de l’homme, dis: Ainsi parle le Seigneur Dis à tout oiseau du ciel et à toute bête des champs: Rassemblez-vous, et partez; réunissez-vous de tous les alentours pour mon sacrifice, que je vous ai préparé, grand sacrifice sur les montagnes d’Israël; et mangez-en les chairs, et buvez-en le sang.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 18, 'Mangez les chairs des géants; buvez le sang des princes de la terre; mangez des béliers, des bœufs, des boucs et des bœufs, tous bien engraissés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 19, 'Mangez de la chair à satiété; buvez du sang jusqu’à l’ivresse; c’est la chair et le sang de mon sacrifice, que je vous ai préparé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 20, 'Et vous serez rassasiés à ma table de la chair du cavalier et du cheval, du géant et de tout guerrier, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 21, 'Et je mettrai en vous ma gloire, et toutes les nations verront mon jugement que j’aurai exécuté, et ma main que j’aurai portée sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 22, 'Et la maison d’Israël saura de ce jour-là et pour tous les temps que je suis le Seigneur leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 23, 'Et les nations sauront que la maison d’Israël a été captive à cause de ses péchés, et qu’en punition de ce qu’elle m’a répudié, j’ai détourné d’elle mon visage; que je l’ai livrée à ses ennemis, et qu’elle est tombée sous le glaive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 24, 'Je les ai traités selon leurs impuretés et leurs égarements, et j’ai détourné d’eux mon visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 25, 'C’est pourquoi voici ce que dit le Seigneur Maître: Maintenant je ramènerai les captifs en Jacob, et je ferai miséricorde à la maison d’Israël, et je serai jaloux pour l’amour de mon saint nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 26, 'Et ils subiront leur déshonneur et l’iniquité qu’ils ont commise quand ils habitèrent leur terre en paix; et nul ne les épouvantera,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 27, 'Lorsque je les aurai retirés d’entre les nations et réunis de toutes les contrées des gentils; et en présence des nations je serai sanctifié parmi eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 28, 'Et ils sauront que je suis le Seigneur leur Dieu, quand je me serai manifesté à eux en présence des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 39, 29, 'Et je ne détournerai plus d’eux mon visage, parce que j’aurai assouvi ma colère contre la maison d’Israël, dit le Seigneur Maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 1, 'Et en la vingt-cinquième année de notre captivité, le premier mois, le premier jour du mois; quatorze ans après que la ville eut été détruite, en ce jour-là la main du Seigneur fut sur moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 2, 'Et elle me conduisit en une vision de Dieu, sur la terre d’Israël, et elle me déposa au sommet d’une très-haute montagne; et en face il y avait comme les constructions d’une ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 3, 'Et elle me conduisit en ce lieu, et voilà qu’il y avait un homme; et son apparence était comme l’apparence de l’airain resplendissant, et il avait en sa main un cordeau de maçon et une canne pour mesure; et il se tenait près de la porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 4, 'Et l’homme me dit: Celui que tu vois, fils de l’homme, regarde-le bien de tes yeux, écoute-le bien de tes oreilles, et dépose en ton cœur tout ce que je vais te montrer; car tu es venu ici pour que je te le montre, et tu montreras ensuite à la maison d’Israël tout ce que tu auras vu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 5, 'Et voilà qu’il y avait un mur tout autour du temple, et la mesure que l’homme tenait à la main était de six coudées et d’un palme; et il mesura le mur, et le mur était en largeur comme sa mesure, et comme sa mesure en hauteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 6, 'Et il monta sept degrés, et il entra par la porte');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 7, 'Et la chambre était égale en longueur et en largeur à sa mesure, et le vestibule entre les chambres, de six coudées; et la seconde chambre était égale en longueur et en largeur à la mesure, et le vestibule de cinq coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 8, 'Et la troisième chambre était égale en longueur et en largeur à sa mesure, et le vestibule du porche, près du vestibule de la porte, avait huit coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 9, 'Et les frontispices étaient de deux coudées; et le vestibule de la porte intérieure,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 10, 'Et les chambres de la porte, communiquant avec la chambre d’entrée, étaient au nombre de trois d’un côté, trois de l’autre; et toutes trois avaient une même mesure, comme les vestibules des deux côtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 11, 'Et l’homme mesura la largeur de la porte du porche, et elle était de dix coudées, et la largeur du porche, de treize coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 12, 'Et l’espace devant les chambres était réduit à une coudée sur le front de chaque chambre de chaque côté; et l’intérieur des chambres avait six coudées de long et six de large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 13, 'Et l’homme mesura la porte depuis le mur d’une chambre jusqu’au mur d’une autre chambre; la largeur était de vingt-cinq coudées; et une porte était vis-à-vis une autre porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 14, 'Et l’espace découvert du vestibule de la porte extérieure avait vingt coudées, jusqu’aux chambres qui régnaient autour de la porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 15, 'Et l’espace découvert de la porte extérieure avait cinquante coudées, jusqu’à l’espace découvert du vestibule de la porte intérieure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 16, 'Et il y avait des fenêtres de biais aux chambres et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 17, 'Et l’homme me conduisit au parvis le plus intérieur; et voilà qu’il y avait des chambres et un péristyle autour du parvis: trente chambres pour tout le péristyle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 18, 'Et les portiques étaient derrière les portes, et le péristyle intérieur avait la même longueur que les portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 19, 'Et l’homme mesura la largeur du parvis, depuis l’espace découvert de la porte regardant le dehors; et il y avait cent coudées à partir de la porte qui regardait l’orient. Et l’homme me conduisit vers l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 20, 'Et voilà qu’il y avait une porte regardant l’aquilon et appartenant au parvis extérieur; et il mesura la longueur et la largeur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 21, 'Et ses chambres trois de chaque côté, et son frontispice, ses vestibules et ses palmes; et, comme à la porte qui regardait l’orient, sa longueur était de cinquante coudées et sa largeur de vingt-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 22, 'Et ses fenêtres, son vestibule et ses palmes étaient comme ceux de la porte qui regardait l’orient; et l’on y montait par sept degrés, et le vestibule était intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 23, 'Et il y avait une porte au parvis intérieur regardant la porte de l’aquilon, semblable à la porte qui regardait l’orient; et l’homme mesura le parvis d’une porte à l’autre, et il y avait cent coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 24, 'Et il me conduisit au côté méridional, et voilà');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 25, 'Les fenêtres et les vestibules environnants étaient comme les fenêtres du vestibule; le tout avait cinquante coudées de long et vingt-cinq de large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 26, 'Et l’on y montait par sept degrés, et le vestibule était extérieur, et il y avait des palmes des deux côtés du frontispice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 27, 'Et il y avait une porte en face de la porte du parvis intérieur du côté méridional; et il mesura le parvis d’une porte à l’autre; et la largeur du côté du midi était de cinquante coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 28, 'Et il me conduisit au parvis intérieur en entrant par la porte du midi, et il mesura la porte, et elle avait les mêmes dimensions;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 29, 'Les chambres, les frontispices et les vestibules avaient aussi les mêmes dimensions; et il y avait des fenêtres au parvis et au vestibule environnants; et le parvis était long de cinquante coudées et large de vingt-cinq,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 30, '31. À partir du vestibule du parvis extérieur; et il y avait des palmes au frontispice, et on y montait par huit degrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 32, 'Et l’homme me conduisit à la porte qui regardait l’orient, et il la mesura, et elle avait les mêmes dimensions;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 33, 'Les chambres, les frontispices et les vestibules avaient aussi les mêmes dimensions; et il y avait des fenêtres au parvis et au vestibule environnants; et le parvis était long de cinquante coudées et large de vingt-cinq.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 34, 'Et il y avait des vestibules ouvrant sur le parvis intérieur, et des palmes des deux côtés du frontispice; et on y montait par huit degrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 35, 'Et l’homme me conduisit à la porte de l’aquilon, et il la mesura, et elle avait les mêmes dimensions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 36, 'Et les chambres, et les frontispices et les vestibules et le parvis avaient des fenêtres tout alentour avec des vestibules; et il avait cinquante coudées de long et vingt-cinq de large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 37, 'Et les vestibules ouvraient sur le parvis extérieur, et il y avait des palmes des deux côtés du frontispice, et on y montait par huit degrés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 38, 'Et ses chambres, ses portes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 39, 'Et ses vestibules, situés vers la seconde porte, servaient d’écoulement, afin qu’en ce parvis on immolât les victimes pour le péché et pour les fautes d’inadvertance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 40, 'Et derrière la rigole des holocaustes il y avait deux tables à l’orient, vers la porte qui regarde l’aquilon; derrière la seconde porte, et derrière le vestibule de la porte, deux tables à l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 41, 'C’étaient donc quatre tables d’un côté et quatre de l’autre côté, derrière la porte; et sur ces tables on sacrifiait les victimes. Devant ces huit tables destinées aux victimes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 42, 'Il y avait de plus, pour les holocaustes, quatre tables en pierre de taille, larges d’une demi-coudée, longues de deux coudées et demie, épaisses d’une coudée. Sur ces tables on posait les instruments avec lesquels on y égorgeait les holocaustes et les autres victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 43, 'Et ces tables avaient en dedans, tout alentour, une gouttière creusée au ciseau, profonde d’un palme, et au-dessus d’elles un toit pour les préserver de la pluie et de la sécheresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 44, 'Et l’homme me conduisit au parvis intérieur; et voilà qu’il y avait deux chambres dans le parvis intérieur, l’une derrière la porte septentrionale, se prolongeant au midi, l’autre derrière la porte méridionale et se prolongeant à l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 45, 'Et il me dit: Cette chambre, située au midi, est pour les prêtres qui gardent le temple;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 46, 'Et la salle située à l’aquilon est pour les prêtres qui gardent l’autel. Ce sont les fils de Sadduc, de la tribu de Lévi, qui s’approchent du Seigneur pour le servir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 47, 'Et il mesura le parvis qui était long de cent coudées dans tous les sens, et l’autel devant le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 48, 'Et il me conduisit dans le vestibule du temple, et il mesura les deux poteaux du vestibule, ayant chacun cinq coudées de large, et les portes larges de treize coudées, et les montants et chambranles de la porte du vestibule, qui avaient trois coudées de chaque côté;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 40, 49, 'Et la longueur du vestibule était de vingt coudées, et sa largeur de douze. Et l’on y montait par douze degrés, et près du vestibule il y avait des colonnes, une d’un côté, une de l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 1, 'Et l’homme me conduisit dans le temple, et il en mesura les deux poteaux du vestibule, larges chacun de six coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 2, 'Et la largeur de la grande porte était de six coudées, et ses chambranles montants en avaient cinq de chaque côté; et il mesura le temple, qui avait quarante coudées de long et vingt de large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 3, 'Et il entra dans le parvis intérieur, et il mesura les');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 4, 'Puis il en mesura la longueur à partir des portes, et elle était de quarante coudées, et la longueur dans le sens de la façade du temple, et elle était de vingt coudées. Et il dit: C’est ici le saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 5, 'Et il mesura l’épaisseur des murs du temple, qui était de six coudées, et la largeur des appartements d’alentour, qui était de quatre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 6, 'Et ces appartements, à la suite les uns des autres, étaient au nombre de deux fois trente-trois, et il y avait un espace entre le mur du temple et les appartements alentour, pour que l’on pût voir sans toucher le mur du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 7, 'Et la largeur du côté supérieur faisait saillie sur le mur, tout à l’entour de la partie supérieure du temple, de sorte qu’en haut le temple était plus large qu’en bas, et que des appartements du bas on pouvait monter à ceux d’en haut, et du seuil inférieur au troisième étage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 8, 'Et l’étage supérieur du temple était élevé tout alentour, et l’espace entre les côtés était égal à la mesure, c’est-à-dire avait six coudées. Les espaces');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 9, 'Et l’épaisseur du mur extérieur de cinq coudées, et le surplus de l’espace compris entre les côtés');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 10, 'Et les appartements, avaient vingt coudées de large autour du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 11, 'Et les portes des appartements s’ouvraient sur l’espace laissé par celle des portes qui regardait l’aquilon; il y avait aussi une porte au midi, et la largeur de l’espace éclairé était de cinq coudées tout alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 12, 'Et le mur de séparation en face de l’espace laissé par la porte occidentale occupait une largeur de soixante-dix coudées; et l’épaisseur du mur de séparation était de cinq coudées autour du temple, et sa longueur de quatre-vingt-dix coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 13, 'Et l’homme mesura en face du temple une longueur de cent coudées; et les bâtiments séparés avec leurs murs avaient aussi cent coudées de long.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 14, 'Et la largeur de la place située devant la façade du temple, et les espaces laissés par les portes devant le temple étaient de cent coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 15, 'Et l’homme mesura la longueur des bâtiments séparés derrière le temple et les galeries ouvertes de l’un et de l’autre côté; et cette longueur était également de cent coudées. Et le temple, les angles et les vestibules extérieurs étaient lambrissés et plafonnés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 16, 'Et les fenêtres réticulées laissaient pénétrer le jour dans les trois étages, de sorte qu’on pouvait se pencher et regarder au travers. Et le temple et ses accessoires étaient lambrissés tout alentour, et le sol planchéié; et le lambris montait du sol aux fenêtres, et les volets des fenêtres se repliaient en trois, pour que l’on pût regarder en dehors.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 17, 'Et le lambris s’élevait presque jusqu’au côté intérieur et au côté extérieur. Et sur tout le mur du temple en dedans et en dehors');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 18, 'Étaient gravés des chérubins, et il y avait des palmes entre deux chérubins, et chaque chérubin avait deux faces,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 19, 'Une face d’homme du côté d’une palme, et une face de lion du côté d’une autre palme; et tout le contour du temple était ainsi gravé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 20, 'Ces chérubins et ces palmes étaient gravés depuis le sol jusqu’au plafond.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 21, 'Et le saint des saints et le temple étaient ouverts de quatre côtés, et en face des saints apparaissait comme une vision,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 22, 'L’autel, qui était de bois, avait trois coudées de haut, deux de long et deux de large. Et il avait des cornes, et sa base et ses parois étaient de bois. Et l’homme me dit: Voici la table qui est devant la face du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 23, 'Et il y avait double porte au temple, et double porte au saint des saints,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 24, 'Ayant chacune deux battants à charnières: deux battants à la première porte, et deux à la seconde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 25, 'Elles étaient sculptées; et il y avait des chérubins aux portes du temple, et des palmes comme à celles du sanctuaire, et de fortes pièces de bois devant le vestibule extérieur,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 41, 26, 'Et des fenêtres cachées en biais. Et l’homme mesura tous les côtés, et les toitures du vestibule et les côtés du temple qui lui étaient adjacents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 1, 'Et l’homme me conduisit dans le parvis intérieur, du côté du levant, vis-à-vis la porte qui regarde l’aquilon, et il m’y introduisit; et là il y avait cinq chambres vers l’espace vide, et près du mur de séparation au nord,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 2, 'Ayant cent coudées de long vers l’aquilon et cinquante de large,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 3, 'Distribuées de la même manière que les portes du parvis intérieur et que le péristyle du parvis extérieur, avec de triples portiques faisant face l’un à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 4, 'Et devant les chambres une galerie large de dix coudées, longue de cent. Et leurs portes regardaient l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 5, 'Et les galeries de l’étage supérieur étaient pareilles; car son péristyle était en saillie sur le péristyle d’en bas, et il y avait entre eux un espace. Tels étaient le péristyle et l’espace entre eux, tels étaient les deux portiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 6, 'Car il y en avait trois étages, et ces colonnes n’étaient pas semblables aux colonnes des bâtiments extérieurs. C’est pourquoi elles faisaient saillie sur l’étage inférieur et sur l’étage intermédiaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 7, 'Et la lumière se tirait du dehors de la même manière qu’aux chambres du parvis extérieur qui regardaient les chambres tournées vers l’aquilon, et leur longueur était de cinquante coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 8, 'Car la longueur des chambres qui regardaient le parvis extérieur était de cinquante coudées, et elles se faisaient face les unes aux autres; la longueur totale était de cent coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 9, 'Et il y avait des portes à ces chambres pour sortir du côté de l’orient, de manière que l’on pût, de ces chambres, aller au parvis extérieur');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 10, 'Par les ouvertures du coin de la galerie; et les parties méridionales de l’édifice étaient au midi vers l’espace vide, et vers le mur de séparation, et les chambres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 11, 'Et la galerie qui longeait leur façade avait la même mesure que les chambres du côté de l’aquilon; elle avait la même longueur, la même largeur, les mêmes issues, les mêmes contours, les mêmes fenêtres, les mêmes portes');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 12, 'Que les chambres du côté du midi; elle régnait depuis la porte d’entrée jusqu’à la fenêtre de l’espace vide, et l’entrée du côté de l’orient, partout large d’une mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 13, 'Et l’homme me dit: Les chambres du côté de l’aquilon et celles du côté du midi qui font face à l’espace vide sont les chambres du sanctuaire; c’est là que les prêtres, fils de Sadduc, qui s’approchent du Seigneur, mangent les choses saintes; c’est là qu’ils déposent les victimes saintes, ainsi que les victimes pour le péché et pour l’inadvertance; car ce lieu est saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 14, 'Nul n’entre ici, hormis les prêtres; et ceux-ci ne sortent point du lieu saint pour passer au parvis extérieur, afin que ceux qui approchent du Seigneur soient toujours saints, et que les vêtements avec lesquels il font le service divin ne touchent à rien qui les souille; car ces vêtements sont sacrés. Et ils en mettent d’autres, quand ils sont en contact avec le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 15, 'Ainsi la mesure intérieure du temple était complète. Et l’homme me conduisit par la voie de la porte qui regarde l’orient, et il mesura tout ce plan du temple, alentour et avec ordre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 16, 'Et il s’arrêta derrière la porte qui regarde l’orient, et il se mit à mesurer, et il trouva cinq cents coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 17, 'Et il se tourna vers l’aquilon, et il mesura la façade septentrionale, et il la trouva de cinq cents coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 18, 'Et il se tourna du côté de l’occident, et il mesura la façade occidentale, et il la trouva de cinq cents coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 19, 'Et il se tourna du côté du midi, et il mesura la façade méridionale, et il la trouva de cinq cents coudées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 42, 20, 'Il mesura avec la même mesure les quatre côtés, il détermina l’extérieur du temple, et la circonférence des accessoires qui l’entouraient, espace de cinq cents coudées au levant, et de cinq cents coudées de large, pour séparer les saints du mur extérieur, destiné à cette séparation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 1, 'Et il me conduisit vers la porte qui regarde l’orient, et il me fit entrer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 2, 'Et voilà que la gloire du Dieu d’Israël vint par la voie de l’orient, et le bruit qu’elle fit à son entrée était comme le bruit d’une grande multitude qui redouble ses clameurs; et à l’entour de cette gloire la terre resplendit comme une flamme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 3, 'Et la vision que j’eus fut comme la vision que j’avais eue lorsque je vins pour marquer la ville. Et j’eus la vision d’un char, comme dans la vision que j’avais eue sur le fleuve Chobar. Et je tombai la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 4, 'Et la gloire du Seigneur entra dans le temple par la voie de la porte qui regarde l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 5, 'Et l’Esprit me ravit, et il m’introduisit dans le parvis intérieur, et voilà que le temple était plein de la gloire de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 6, 'Et je me tins immobile; et voilà qu’une voix me parla du temple, et l’homme se tenait auprès de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 7, 'Et la voix me dit: Fils de l’homme, tu vois la place de mon trône et la trace de mes pieds; c’est ici que mon nom s’abritera pour tous les siècles au milieu de la maison d’Israël. Et la maison d’Israël, ses enfants et leurs rois ne');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 8, 'Lorsqu’ils avaient mon portique près de leurs portiques, et mes portes auprès de leurs portes. Et ils avaient fait de mon mur comme un lien entre eux et moi; mais ils ont profané mon saint nom par leurs iniquités. Et je les ai broyés en ma colère, et ils ont péri.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 9, 'Et maintenant, qu’ils répudient loin de moi leurs prostitutions, et je m’abriterai au milieu d’eux dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 10, 'Et toi, fils de l’homme, montre ce temple à la maison d’Israël, et ils cesseront de pécher; montre-leur son plan et sa distribution.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 11, 'Et eux-mêmes accepteront les châtiments de toutes les choses qu’ils ont faites. Décris-leur le temple, ses issues, toute sa structure; fais-leur connaître ses règlements et toutes ses lois; décris-les devant eux, et ils garderont mes ordonnances et mes commandements, et ils les mettront en pratique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 12, 'Et tu leur montreras le plan du temple sur le sommet de la montagne, et toute son étendue sera sainte et sacrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 13, 'Et voici les mesures de l’autel: il sera d’une grande coudée, c’est-à-dire d’une coudée et un palme; sa cavité aura une coudée; il aura une coudée de large, et un palme pour la corniche du rebord tout alentour. Et voici la hauteur de l’autel:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 14, 'À partir du commencement de la cavité jusqu’au grand propitiatoire, deux coudées de haut sur une de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 15, 'Et l’Ariel sera de quatre coudées, et à partir de l’Ariel, au-dessous des cornes, il y aura une coudée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 16, 'Et l’Ariel sera long de douze coudées sur douze de large; c’est un tétragone aux côtés égaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 17, 'Et le propitiatoire sera long de quatorze coudées sur quatorze de large; ses quatre côtés sont égaux. Et il a tout alentour une corniche d’une demi-coudée en saillie d’une coudée de hauteur; et ses degrés regardent l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 18, 'Et la voix me dit: Fils de l’homme, ainsi parle le Seigneur Dieu d’Israël: Voici la règle pour l’autel: du jour où il aura été fait, on y offrira des holocaustes, et on y versera le sang des victimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 19, 'Et tu donneras aux prêtres lévites, à ceux de la famille de Sadduc, qui s’approchent de moi, dit le Seigneur Dieu, un veau choisi parmi le troupeau, afin de me le sacrifier pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 20, 'Et ils prendront de son sang, et ils le mettront sur les quatre cornes de l’autel et sur les quatre angles du propitiatoire, et sur la base tout alentour, et ainsi ils le purifieront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 21, 'Et ils prendront le veau offert pour le péché, et il sera brûlé par le feu, dans le lieu séparé du temple, hors du sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 22, 'Et le second jour ils prendront deux chevreaux sans tache pour le péché, et ils purifieront l’autel, comme ils l’auront purifié avec le veau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 23, 'Et lorsqu’ils auront achevé la purification, ils offriront un veau sans tache et un bélier sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 24, 'Et vous les offrirez devant le Seigneur; et les prêtres les saupoudreront de sel, et ils les offriront en holocauste au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 25, 'Pendant sept jours, tu offriras chaque jour pour le péché un chevreau, un veau et un bélier choisis parmi les bœufs et les brebis; et on sacrifiera ces victimes, toutes sans tache,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 26, 'Durant sept jours. Et ils purifieront l’autel, ils le sanctifieront, et ils consacreront leurs mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 43, 27, 'Et à partir du huitième jour et dans la suite les prêtres sacrifieront sur l’autel vos holocaustes et vos victimes pour le salut; et je vous agréerai, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 1, 'Et l’homme me ramena par le chemin de la porte intérieure du sanctuaire qui regarde l’orient, et elle était fermée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 2, 'Et le Seigneur me dit: Cette porte restera fermée, et jamais elle ne sera ouverte, et nul n’y passera; parce que le Seigneur Dieu d’Israël entrera par cette porte, et elle sera fermée pour tout autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 3, 'Quant au prince, il s’y assiéra pour manger du pain devant le Seigneur. Il entrera par le chemin de la porte du vestibule, et sortira par cette même porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 4, 'Et l’homme me fit entrer par le chemin de la porte qui regarde l’aquilon devant le temple. Et je regardai, et voilà que le temple était plein de la gloire de Dieu; et je tombai la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 5, 'Et le Seigneur me dit: Fils de l’homme, mets en');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 6, 'Et tu diras à cette maison qui m’irrite, à la maison d’Israël Voici ce que dit le Seigneur Dieu: Qu’il vous suffise, maison d’Israël, d’avoir commis tous vos péchés;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 7, 'D’avoir introduit parmi vous des fils d’étrangers incirconcis par le cœur, et incirconcis par la chair, pour qu’ils se tinssent dans mon saint des saints, et qu’ils se souillassent quand vous offriiez des pains, des chairs et du sang; vous avez transgressé mon alliance par toutes vos iniquités;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 8, 'Et à la garde de mon sanctuaire vous avez préposé d’autres hommes que les lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 9, 'À cause de cela, voici ce que dit le Seigneur Dieu: Tout fils étranger incirconcis par le cœur et incirconcis par la chair, sera exclu de mon saint des saints, ainsi que tous les fils d’étrangers qui résident au milieu de la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 10, 'Quant aux lévites qui se sont éloignés de moi, lorsque la maison d’Israël s’est égarée loin de moi pour marcher à la suite de ses idoles, ils porteront la peine de leur iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 11, 'Toutefois ils demeureront dans mes lieux saints pour me servir, comme gardiens des portes du temple et serviteurs dans le temple; ils égorgeront les victimes et les holocaustes pour le peuple, ils se tiendront devant le peuple, prêts à le servir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 12, 'Mais en punition de ce qu’ils ont servi pour lui devant ses idoles, et qu’ils ont attiré sur la maison d’Israël');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 13, 'Ils ne s’approcheront plus de moi pour être mes prêtres ni pour être employés, soit dans les saints des fils d’Israël, soit dans mon saint des saints. Ils porteront la honte de leurs égarements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 14, 'On les commettra à la garde du temple en tous les offices et en toutes les choses qu’ils feront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 15, 'Pour les prêtres lévites, fils de Sadduc, qui ont gardé les offices de mon sanctuaire pendant que la maison d’Israël s’égarait loin de moi, ceux-là s’approcheront de moi pour me servir; ils se tiendront devant ma face pour m’offrir les sacrifices, le sang et la graisse, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 16, 'Ceux-là entreront dans mon sanctuaire, ceux-là s’approcheront de ma table pour me servir; et ils garderont mes offices.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 17, 'Et lorsqu’ils entreront par la porte du parvis intérieur, ils seront revêtus de robes de lin; ils ne porteront point de laine pour me servir, dès qu’ils auront franchi la porte du parvis intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 18, 'Et ils auront sur la tête des mitres de lin, et ils auront autour des reins des caleçons de lin; mais ils n’en serreront pas la ceinture.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 19, 'Et lorsqu’ils sortiront du parvis intérieur pour rejoindre le peuple, ils ôteront les robes avec lesquelles ils font leur service liturgique, et ils les déposeront dans les chambres du sanctuaire; ils mettront d’autres robes et ne sanctifieront pas le peuple avec leurs propres robes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 20, 'Et ils ne se raseront point les cheveux, et ils ne les épileront point, et ils se couvriront soigneusement la tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 21, 'Et nul prêtre ne boira de vin lorsqu’il devra entrer dans le parvis intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 22, 'Et ils ne prendront pour femmes ni veuve ni épouse répudiée, mais des vierges de la race d’Israël; toutefois, s’il se trouve qu’une femme soit veuve d’un prêtre, ils pourront l’épouser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 23, 'Et ils instruiront mon peuple à distinguer le sacré du profane, et le pur de l’impur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 24, 'Et dans les causes où il y aura du sang ils auront mission de juger; et ils feront justice selon mes ordonnances; ils jugeront selon mes jugements; ils garderont mes lois et mes préceptes concernant toutes les fêtes, et ils sanctifieront mes sabbats.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 25, 'Ils n’entreront point auprès d’un homme mort, de peur d’être souillés; néanmoins le prêtre se souillera sans devenir impur, si le mort est son père, sa mère, son fils, sa fille, son frère ou sa sœur non mariée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 26, 'Et lorsqu’un prêtre aura été purifié, on lui comptera encore sept jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 27, 'Et quel que soit le jour où il rentrera dans le parvis intérieur, pour le service du sanctuaire, il offrira une victime propitiatoire, dit le Seigneur-Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 28, 'Et voici quel sera leur héritage: c’est moi qui serai leur héritage, et il ne leur sera point donné de partage parmi les fils d’Israël; car c’est moi qui serai leur partage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 29, 'Et ils mangeront les victimes celles pour le péché, celles pour l’inadvertance; et toute part réservée en Israël leur appartiendra,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 30, 'Les prémices de toutes choses, les premiers-nés de tous les troupeaux et toutes les parts réservées. Les prêtres auront de toutes vos prémices, et vous donnerez');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 44, 31, 'Et les prêtres ne mangeront, parmi les oiseaux ou le bétail, ni corps mort, ni animal pris par d’autres bêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 1, 'Or, lorsque vous mesurerez la terre de votre héritage, vous en séparerez les prémices pour le Seigneur; c’està-dire un lieu consacré en cette terre, long de vingt-cinq mille mesures, large de vingt mille; et ce lieu sera consacré dans toute son étendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 2, 'Et de cet espace vous séparerez pour le lieu saint un carré de cinq cents mesures de côté, avec un passage de cinquante coudées alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 3, 'En mesurant la terre, vous mesurerez donc un espace qui aura vingt-cinq mille mesures de long sur vingt mille de large, et dans cet espace sera le saint des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 4, 'Ce sera dans la terre la part des prêtres qui serviront dans le lieu saint, et de ceux qui s’approcheront du Seigneur pour le servir. Et ce sera pour eux un espace où ils auront leurs maisons séparées du lieu saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 5, 'Cette part aura vingt-cinq mille mesures de long sur vingt mille de large. Et aux lévites attachés au service du temple il sera assigné des villes où ils résideront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 6, 'Et à la possession des villes tu ajouteras un espace de vingt-cinq mille mesures de long, sur vingt mille de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 7, 'Quant au prince, il aura, outre ces parts, une part égale à ce qui est désigné pour les prémices du sanctuaire et pour l’espace des villes; elle sera en face des prémices du sanctuaire et en face de l’espace des villes, tant à l’occident que de l’occident à l’orient. Et la longueur sera la même que celle de l’une des parts, depuis les limites occidentales jusqu’aux limites orientales de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 8, 'Et ce sera la part du prince en Israël; et les princes d’Israël n’opprimeront plus mon peuple, et la maison d’Israël se partagera la terre par tribus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 9, 'Voici maintenant ce que dit le Seigneur Dieu: Que cela vous suffise, princes d’Israël; renoncez à l’iniquité et aux vexations; pratiquez la justice et l’équité; éloignez de mon peuple l’oppression, dit le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 10, 'Que votre balance soit juste, que votre mesure soit juste, que votre éphi soit juste selon la mesure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 11, 'Que votre éphi soit égal et uniforme, qu’il soit le dixième du gomor, et que le gomor soit uniforme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 12, 'Que vos poids pèsent vingt oboles, cinq sicles, quinze sicles; et que cinquante sicles fassent une mine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 13, 'Et voici les prémices que vous séparerez: une mesure pour le sixième d’un gomor de froment; le sixième d’un éphi pour un cor d’orge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 14, 'Quant à l’huile, voici la règle: un cotyle d’huile sur dix cotyles; car dix cotyles font un gomor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 15, 'Parmi les menus troupeaux, une tête sur dix sera offerte, en toutes les tribus d’Israël, pour les sacrifices');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 16, 'Et tout le peuple donnera ces prémices au prince d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 17, 'Et le prince sera chargé d’offrir les holocaustes, les oblations et les libations les jours de fêtes, aux nouvelles lunes, les jours de sabbat et à toutes les fêtes de la maison d’Israël. Il offrira les offrandes pour le péché, les oblations, les holocaustes et les hosties pacifiques pour la purification de la maison d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 18, 'Voici ce que dit le Seigneur Dieu: Le premier mois, et le premier jour du mois, vous prendrez un veau sans tache pour purifier le sanctuaire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 19, 'Et le prêtre prendra du sang de la purification; et il en mettra sur les portes du temple, sur les quatre coins du sanctuaire, sur l’autel et sur les jambages de la porte du parvis intérieur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 20, 'Et tu feras pareillement le septième mois; le premier du mois, tu prendras une part de chaque chose, et vous purifierez le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 21, 'Et le premier mois, le quatorzième jour de ce mois, vous aurez la fête de la Pâque; pendant sept jours, vous mangerez des azymes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 22, 'Et ce jour-là le prince sacrifiera un veau pour lui-même, pour le temple et pour tout le peuple de la terre; ce sera un sacrifice pour le péché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 23, 'Et pendant les sept jours de la fête il offrira en holocauste au Seigneur sept veaux et sept béliers sans tache, par jour, et il sacrifiera pour le péché un chevreau par jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 24, 'Et il fera cuire un gâteau pour chaque veau, et des gâteaux pour chaque bélier; et il y aura un hin d’huile par gâteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 45, 25, 'Et le septième mois, le quinzième jour du mois, tu célèbreras une fête semblable à celle-ci, durant sept jours; il y aura les mêmes victimes pour le péché, les mêmes holocaustes, les mêmes oblations, les mêmes mesures d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 1, 'Voici ce que dit le Seigneur Dieu: La porte du parvis intérieur qui regarde l’orient sera fermée les six jours de travail; elle sera ouverte les jours du sabbat et à chaque nouvelle lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 2, 'Et le prince entrera par le chemin du vestibule de la porte intérieure, et il s’arrêtera au seuil de la porte, et les prêtres prépareront ses holocaustes et ses hosties pacifiques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 3, 'Et il adorera au seuil même de la porte, puis il sortira, et la porte ne sera pas fermée jusqu’au soir; et le peuple de la terre adorera près de cette porte, et il se prosternera devant le Seigneur, les jours de sabbat et de nouvelle lune.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 4, 'Et le prince offrira les jours de sabbat, en holocauste au Seigneur, six agneaux sans tache et un bélier sans tache,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 5, 'Et l’oblation d’un gâteau pour le bélier, et un don volontaire de sa main par agneau; et il y aura dans le gâteau un hin d’huile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 6, 'Et il offrira, le jour de la nouvelle lune, un veau sans tache, et six agneaux et un bélier sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 7, 'Et il y aura un gâteau pour le bélier; et le gâteau');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 8, 'Et lorsque le prince entrera dans le temple, il passera par le chemin du vestibule du parvis, et il sortira par le chemin de la porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 9, 'Et lorsque le peuple de la terre viendra devant le Seigneur, celui qui arrivera les jours de fête pour adorer par le chemin de la porte qui regarde l’aquilon, sortira par la porte du midi; et celui qui arrivera par le chemin de la porte du midi sortira par la porte de l’aquilon; nul ne s’en ira par le chemin qu’il aura pris pour entrer, mais il marchera droit devant lui pour sortir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 10, 'Et le prince au milieu d’eux entrera avec eux quand ils entreront, et il sortira quand ils sortiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 11, 'Et aux fêtes et aux solennités générales il y aura oblation d’un gâteau par veau et d’un gâteau par bélier; et le prince donnera par agneau selon le pouvoir de sa main, et il y aura un hin d’huile par gâteau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 12, 'Si le prince prépare en action de grâces un holocauste pacifique au Seigneur, il ouvrira pour lui seul la porte qui regarde l’orient, et il préparera l’holocauste et les hosties pacifiques, comme il fait le jour du sabbat; puis il sortira, et en sortant il fermera les portes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 13, 'Et chaque jour, dès le matin, il offrira en holocauste au Seigneur un agneau d’un an sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 14, 'Et il fera dès le matin, pour cet agneau, l’oblation d’un sixième d’éphi de fleur de farine et du tiers d’un hin d’huile pour y être mêlée; cette oblation au Seigneur sera de règle perpétuelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 15, 'Vous sacrifierez l’agneau, et vous offrirez dès le matin l’huile et la farine; cet holocauste sera perpétuel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 16, 'Voici ce que dit le Seigneur: Si le prince fait sur sa part de bien un don à l’un de ses fils, celui-ci le transmettra à ses fils comme héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 17, 'S’il fait un don à l’un de ses serviteurs, celui-ci ne le possèdera que jusqu’à l’année du jubilé, et alors il le rendra au prince; quant à ce qui est possédé par ses fils, c’est à eux que la possession continuera d’appartenir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 18, 'Et le prince ne prendra rien de l’héritage du peuple il se gardera de l’opprimer; il fera part à ses fils de ce que lui-même possède, afin que nul de mon peuple ne soit expulsé de son héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 19, 'Et l’homme me conduisit derrière la porte à la chambre des saints, consacrée aux prêtres, qui regarde l’aquilon; et là était un lieu réservé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 20, 'Et il me dit: Voici le lieu où les prêtres feront cuire les victimes pour le péché et pour l’inadvertance; ils y feront cuire aussi tous les gâteaux de l’oblation, afin de ne les point emporter dans le parvis extérieur, quand ils purifieront le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 21, 'Et l’homme me conduisit au parvis extérieur, et il me fit faire le tour de ses quatre côtés, et là il y avait une cour à chacun de ses côtés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 22, 'Il y avait quatre petites cours, une par côté, toutes longues, pareillement de quarante coudées, larges de trente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 23, 'Et à l’entour de chacune il y avait des chambres; et au-dessous des chambres les cuisines étaient bâties alentour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 46, 24, 'Et il me dit: Voici les demeures des cuisiniers; c’est ici que les desservants du temple feront cuire les offrandes du peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 1, 'Et il me conduisit sous les portiques du temple; et là de l’eau sortait de la cour et coulait à l’orient; car la façade du temple regardait l’orient, et l’eau descendait à droite au midi de l’autel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 2, 'Et il me fit sortir par le chemin de la porte de l’aquilon; et il me fit tourner par le chemin extérieur jusqu’à la porte du parvis qui regarde l’orient, et voilà que l’eau coulait du côté droit,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 3, 'Dans la direction qu’avait prise l’homme en sortant, et devant lui; or il tenait à la main son cordeau, et il mesura mille coudées, et il traversa l’eau, cette eau qui jaillissait de la cour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 4, 'Et il mesura mille coudées, et il traversa l’eau, et il en eut jusqu’aux cuisses. Et il mesura mille coudées, et il traversa l’eau, et il en eut jusqu’aux reins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 5, 'Et il mesura mille coudées, et il ne put traverser, parce que l’eau débordait comme un torrent infranchissable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 6, 'Et il me dit: As-tu vu, fils de l’homme? et il me guida, et il me ramena sur la rive du fleuve');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 7, 'Par laquelle je pouvais revenir. Et voilà qu’il y avait sur les deux rives du fleuve une grande multitude d’arbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 8, 'Et il me dit: Cette eau sort de la Galilée, qui est vers l’Orient, puis elle descend vers l’Arabie, et va jusqu’à la mer, jusqu’à l’eau qui en sort, et elle assainira toutes les eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 9, 'Et ceci arrivera: toute âme de créature vivant et se mourant sur tout lieu où ce fleuve passera, vivra; et il y aura là une multitude de poissons, parce que l’eau y sera venue; et où sera passé le fleuve tout être sera sain, et il vivra, et il vivra en ce lieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 10, 'Et il y viendra des pêcheurs depuis Engaddi jusqu’à Engallim; et le long de ce fleuve ils feront sécher leurs filets; et ses poissons seront, comme ceux de la grande mer, en grande multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 11, 'Et à son embouchure et dans ses détours, et dans ses débordements, ses eaux ne seront point assainies; on s’en servira pour en tirer le sel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 12, 'Et tout arbre fruitier croîtra au bord du fleuve sur ses deux rives; nul n’y dépérira et n’y manquera de fruits; dès sa première pousse, il produira, parce que les eaux qui l’arrosent sortent du lieu saint; et ses fruits seront bons à manger, et ses feuilles rendront la santé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 13, 'Voici ce que dit le Seigneur: Je vais vous indiquer les limites de cette terre que vous vous partagerez au cordeau, entre les douze tribus des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 14, 'Et dans ce partage chacun aura autant que son frère, de cette terre sur laquelle j’ai levé la main pour la donner à vos pères; et elle sera votre héritage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 15, 'Et voici les limites de cette terre à l’aquilon: depuis la grande mer, qui s’y enfonce et forme un golfe à l’entrée d’Émaseldam:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 16, 'Maabthéras, Hébraméliam, entre les confins de');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 17, 'Voilà les limites depuis la mer; depuis le val d’Énan, ce sont les confins de Damas et les limites du côté de l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 18, 'Celles du côté du levant passeront entre la Loranitide, Damas, la Galaaditide, et entre la terre d’Israël; le Jourdain les limitera vers la mer qui est au levant de la ville des Palmiers. Voilà les limites à l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 19, 'Celles du midi et du sud-ouest s’étendront de Théman et de la ville des Palmiers, jusqu’aux eaux de Barimoth-Cadès, d’où elles rejoindront la grande mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 20, 'Telle est la limite du sud et du sud-ouest; celle de l’occident est la grande mer elle-même; elle va jusqu’au golfe d’Émath; telle est la limite vers la mer d’Émath.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 21, 'Et vous partagerez pour eux cette terre entre les tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 22, 'Vous les partagerez au sort, pour vous et pour les étrangers qui résident parmi vous, et qui ont eu des enfants au milieu de vous; et ils seront pour vous comme des indigènes au milieu des fils d’Israël. Ils mangeront avec vous les fruits de votre héritage au milieu des fils d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 47, 23, 'Et dans la tribu où se trouveront des prosélytes, vous leur donnerez un héritage, dit le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 1, 'Et voici les noms des tribus, en commençant par l’aquilon, à partir de la descente qui tire une ligne jusqu’à l’entrée d’Émath et au parvis du vestibule; tenant à Damas, vers l’aquilon, du côté du parvis d’Émath. Il y aura depuis l’orient jusqu’à la mer: Dan, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 2, 'Et à partir des limites de Dan, depuis l’orient jusqu’à l’occident: Aser, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 3, 'Et à partir des limites d’Aser, depuis l’orient jusqu’à l’occident, Nephthali, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 4, 'Et à partir des limites de Nephthali, depuis l’orient jusqu’à l’occident, Manassé, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 5, 'Et à partir des limites de Manassé, depuis l’orient jusqu’à l’occident, Ephraïm, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 6, 'Et à partir des limites d’Éphraïm, depuis l’orient jusqu’à l’occident, Ruben, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 7, 'Et à partir des limites de Ruben, depuis l’orient jusqu’à l’occident, Juda, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 8, 'Et à partir des limites orientales de Juda il y aura les prémices que vous séparerez vingt-cinq mille mesures de long et autant de large, le côté oriental étant égal à celui de l’occident, et mon sanctuaire sera au milieu de cet espace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 9, 'Les prémices que vous séparerez pour le Seigneur auront vingt-cinq mille mesures de long, et vingt-cinq mille de large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 10, 'On y prendra les prémices du sanctuaire pour les prêtres, savoir: vingt-cinq mille mesures du côté de l’aquilon, dix mille du côté de l’occident, vingt-cinq');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 11, 'Pour les prêtres, pour les fils sanctifiés de Sadduc, pour ceux qui gardent les offices du temple, et qui ne se sont point égarés avec les fils d’Israël, comme l’ont fait des lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 12, 'Et ils auront pour prémices, au milieu des prémices de la terre, le saint des saints, proche du partage des lévites.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 13, 'Et pour les lévites à côté du partage des prêtres, il y aura vingt-cinq mille mesures de long, sur dix mille de large ce sera toute leur part, vingt-cinq mille mesures de long, sur dix mille de large.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 14, 'Il n’en sera rien vendu ni distrait; on ne pourra rien soustraire des fruits de ce territoire, parce que cette part sera consacrée au Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 15, 'Et les cinq mille mesures de surplus sur le total de la largeur, qui est de vingt-cinq mille coudées, seront occupées par le faubourg de la ville, par ses maisons et son esplanade, et la ville sera au milieu de cet espace.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 16, 'Voici maintenant les dimensions de la ville: du côté de l’aquilon, quatre mille cinq cents mesures; du côté du midi, quatre mille cinq cents; du côté de l’orient, quatre mille cinq cents; et du côté de l’occident, quatre mille cinq cents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 17, 'Et du côté de l’aquilon il y aura, à la ville, une esplanade de deux cent cinquante mesures, et trois autres de même dimension au midi, à l’orient et à l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 18, 'Et le reste de la longueur, consacré aux prémices des saints, sera de dix mille mesures à l’orient, et de dix mille à l’occident: telles seront les prémices des saints; et de leurs récoltes on donnera du pain à ceux qui rendent des services dans la ville.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 19, 'Et ceux qui rendront ainsi des services dans la ville même seront de toutes les tribus d’Israël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 20, 'Les prémices entières auront donc vingt-cinq mille mesures de long, et vingt-cinq mille de large. Vous séparerez du territoire que possèdera la ville ce carré pour les prémices des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 21, 'Or ce qui restera de ce carré, à partir du sanctuaire, sera pour le prince; il sera compris dans le territoire de la ville, sur une longueur de vingt-cinq mille mesures jusqu’à ses limites du côté de l’orient et de l’occident, et sur vingt-cinq mille de large jusqu’aux limites du côté de l’occident, tenant à la part du prince. Et ce seront les prémices des saints; et au milieu d’elles il y aura le sanctuaire du temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 22, 'Et la part des lévites et le territoire de la ville, au milieu duquel sera la part du prince, seront entre les limites de Juda et les limites de Benjamin; ce sera la résidence des princes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 23, 'Or voici la part du reste des tribus, depuis l’orient jusqu’à l’occident, Benjamin, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 24, 'À partir des limites de Benjamin, depuis l’orient jusqu’à l’occident, Siméon, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 25, 'À partir des limites de Siméon, depuis l’orient jusqu’à l’occident, Issachar, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 26, 'À partir des limites d’Issachar, depuis l’orient jusqu’à l’occident, Zabulon, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 27, 'À partir des limites de Zabulon, depuis l’orient jusqu’à l’occident, Gad, une tribu;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 28, 'À partir des limites de Gad, depuis l’orient, et');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 29, 'Telle est la terre que vous vous partagerez au sort entre les tribus d’Israël, et tels seront les lots, dit le Seigneur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 30, 'Or voici les issues de la ville: celles du côté de l’aquilon, sur une longueur de quatre mille cinq cents mesures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 31, 'Les portes de la ville prendront les noms des tribus d’Israël; il y aura trois portes à l’aquilon la porte de Ruben, la porte de Juda, la porte de Lévi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 32, 'Celles de l’orient, percées dans une longueur de quatre mille cinq cents mesures, seront au nombre de trois la porte de Joseph, la porte de Benjamin, la porte de Dan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 33, 'Celles du midi, percées dans une longueur de quatre mille cinq cents mesures, seront au nombre de trois la porte de Siméon, la porte d’Issachar, la porte de Zabulon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 34, 'Celles du côté de l’occident, percées dans une longueur de quatre mille cinq cents mesures, seront au nombre de trois: la porte de Gad, la porte d’Aser, la porte de Nephthali.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 48, 35, 'L’enceinte entière aura dix-huit mille mesures, et, à partir de ce jour, le nom de la ville sera: C’est le nom du Seigneur.');
