INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Il y avait un homme demeurant à Babylone, et son nom était Joakim.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Et il avait épousé une femme dont le nom était Susanne, fille de Helcias, merveilleusement belle et craignant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Et les parents de Susanne étaient justes, et ils avaient instruit leur fille selon la loi de Moïse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Et Joakim était extrêmement riche; et il possédait un jardin, tenant à sa maison; et les Juifs le fréquentaient, parce qu’il était le plus considérable d’entre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Et cette année-là furent nommés juges deux anciens du peuple, desquels le Seigneur a dit: L’iniquité est sortie de Babylone par des juges avancés en âge, qui semblaient gouverner le peuple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Ils venaient assidûment en la maison de Joakim, et ceux qui étaient en procès les y allaient trouver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Et, lorsque, au milieu du jour, le peuple s’était éloigné, Susanne entrait, et se promenait dans le jardin de son mari.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Et les deux vieillards la virent chaque jour arriver et se promener, et ils eurent d’elle un violent désir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Et ils pervertirent leur esprit, et ils détournèrent leurs yeux pour ne point voir le ciel, et ne point se souvenir des justes jugements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Et ils étaient tous les deux blessés d’amour pour elle, et ils ne se parlaient point l’un à l’autre de leur passion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Car ils avaient honte de faire connaître leur concupiscence, et ils désiraient la posséder.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Et chaque jour ils épiaient à l’envi l’occasion de la voir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 13, 'Et un jour ils se dirent l’un à l’autre: Allons à la maison, c’est l’heure du dîner. Ils sortirent donc, et ils se séparèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 14, 'Mais, revenant sur leurs pas, ils arrivèrent en même temps, et, après s’en être demandé la cause, ils se confessèrent leur passion; et alors ils se concertèrent ensemble sur le moment où ils pourraient trouver Susanne seule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 15, 'Or il advint que, pendant qu’ils épiaient le jour favorable, elle entra comme la veille et l’avant-veille, n’ayant avec elle que deux suivantes, et elle voulut se baigner dans le jardin, parce qu’il faisait très-chaud.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 16, 'Et il n’y avait là personne que les deux vieillards cachés, qui la regardaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 17, 'Or elle dit aux jeunes filles: Allez me chercher de l’huile et des essences, et fermez les portes du jardin, afin que je me baigne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 18, 'Et elles firent comme elle avait dit, et elles fermèrent les portes du jardin, et sortirent par une porte dérobée, pour apporter ce qu’avait demandé leur maîtresse, et elles ne virent point les deux vieillards, parce qu’ils étaient cachés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 19, 'Et ceci advint: dès que les jeunes filles furent sorties, les vieillards se levèrent et coururent auprès de Susanne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 20, 'Et ils dirent: Voilà que les portes du jardin sont fermées; personne ne nous voit, et nous sommes épris de toi; consens donc à nos désirs, et sois à nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 21, 'Sinon, nous t’accuserons, nous porterons témoignage qu’il y avait avec toi un jeune homme, et qu’à cause de cela tu as éloigné tes suivantes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 22, 'Et Susanne soupira, et elle dit: Quelle angoisse pour moi de toutes parts! car si je fais ce que vous dites, c’est pour moi la mort; et si je ne le fais, je n’échapperai pas de vos mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 23, 'Mais j’aime mieux, sans vous avoir cédé, tomber entre vos mains que pécher devant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 24, 'Et Susanne jeta un grand cri, et les deux vieillards crièrent aussi contre elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 25, 'Et l’un des deux courut ouvrir les portes du jardin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 26, 'Au cri jeté dans le jardin, les gens de la maison s’élancèrent par la porte dérobée pour voir ce qui se passait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 27, 'Lorsque les vieillards eurent fait leur récit, les serviteurs furent extrêmement confus; car jamais on n’avait rien dit de pareil sur leur maîtresse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 28, 'Et ceci arriva: le lendemain, dès que le peuple fut rassemblé chez Joakim, son mari, les deux vieillards entrèrent pleins de mauvais desseins contre Susanne pour la faire condamner à mort, et ils dirent devant le peuple:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 29, 'Que l’on aille chercher Susanne, fille de Helcias, femme de Joakim; et on l’alla chercher.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 30, 'Et elle vint, et ses parents avec elle, et ses enfants, et toute sa famille.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 31, 'Or Susanne était d’une extrême délicatesse et d’une grande beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 32, 'Et les deux méchants commandèrent qu’on lui ôtât son voile (car elle était voilée), pour se rassasier au moins de sa beauté.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 33, 'Et ceux qui l’accompagnaient pleurèrent, et tous ceux qui la virent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 34, 'Et les deux vieillards s’étant levés au milieu du peuple, imposèrent leurs mains sur sa tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 35, 'Mais elle, en pleurant, regarda le ciel; car son cœur était confiant dans le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 36, 'Et les vieillards dirent: Comme nous nous promenions seuls dans le jardin, cette femme sortit avec deux suivantes, et elle ferma les portes du jardin, et elle renvoya ses filles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 37, 'Et il vint près d’elle un jeune homme qui se tenait caché, et qui s’étendit à terre avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 38, 'Et nous, du coin du jardin où nous étions, nous vîmes l’iniquité; nous courûmes à eux, et nous les trouvâmes ensemble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 39, 'À la vérité, nous ne pûmes saisir le jeune homme, parce qu’il était plus fort que nous, et qu’ayant ouvert la porte, il s’enfuit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 40, 'Mais elle, nous la retînmes, et nous lui demandâmes quel était ce jeune homme; et elle ne voulut point nous le déclarer; nous témoignons de ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 41, 'Et l’assemblée les crut, car c’étaient les anciens du peuple et les juges; et ils la condamnèrent à mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 42, 'Et Susanne jeta un grand cri, et elle dit: O Dieu éternel, vous qui voyez les choses cachées, vous qui savez toutes choses, même avant leur naissance,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 43, 'Vous savez que ces hommes viennent de porter sur moi un faux témoignage. Et voilà que je meurs, sans avoir rien fait de ce qu’ils ont méchamment inventé contre moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 44, 'Et le Seigneur entendit sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 45, 'Et comme on la menait au supplice, Dieu suscita l’esprit saint d’un jeune enfant que l’on nommait Daniel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 46, 'Et ce jeune homme cria à haute voix: Je suis innocent du sang de celle-ci!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 47, 'Et tout le peuple se tourna vers lui, disant: Que veulent dire ces paroles?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 48, 'Et, s’étant placé au milieu du peuple, il dit: Êtes-vous à ce point insensés, fils d’Israël, que, sans rien examiner, sans être clairement informés, vous ayez condamné une fille d’Israël?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 49, 'Revenez sur le jugement; car ces hommes ont porté contre elle un faux témoignage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 50, 'Et le peuple se hâta de rentrer, et les anciens dirent au jeune homme: Viens, assieds-toi au milieu de nous, et instruis-nous; car Dieu t’a donné l’honneur de la vieillesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 51, 'Et Daniel leur dit: Séparez-les, placez-les loin l’un de l’autre, et je les interrogerai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 52, 'Quand ils furent séparés et loin l’un de l’autre, il appela l’un des deux, et il lui dit: O toi, qui as vieilli dans le crime, maintenant ils retournent contre toi ces péchés que tu as commis autrefois,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 53, 'En rendant des jugements iniques, en condamnant les innocents, en absolvant les coupables, quand Dieu a dit: Tu ne feras mourir ni l’innocence ni le juste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 54, 'Si donc il est vrai que tu aies vu cette femme, dis sous quel arbre tu les as vus ensemble? Il répondit: Sous un lentisque.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 55, 'Et Daniel reprit: Tu as menti justement contre ta tête; car l’ange qui reçoit de Dieu la parole de Dieu est déjà prêt à te fendre par le milieu du corps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 56, 'Et, ayant fait retirer celui-ci, il ordonna qu’on amenât l’autre, et il lui dit: Race de Chanaan, et non de Juda, la beauté t’a séduit, et la concupiscence a perverti ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 57, 'Voilà comme vous en usiez avec les filles d’Israël, et, par peur, elles cédaient à vos désirs; mais la fille de Juda n’a pu souffrir votre iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 58, 'Maintenant donc dis-moi sous quel arbre tu les as surpris ensemble. Il répondit: Sous un houx.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 59, 'Et Daniel reprit: Et toi aussi tu as menti justement contre ta tête; car l’ange de Dieu attend le glaive à la main, et il te sciera par le milieu du corps, pour vous faire mourir tous les deux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 60, 'Et toute la synagogue jeta de grands cris, et elle bénit Dieu, qui sauve ceux qui espèrent en lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 61, 'Et ils s’élevèrent contre les deux vieillards; car Daniel les avait convaincus, par leur propre bouche, d’avoir porté de faux témoignages, et on leur fit comme ils avaient voulu méchamment faire à leur prochain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 62, 'Afin d’exécuter la loi de Moïse, on les mit à mort tous les deux, et le sang innocent ne fut point versé ce jour-là.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 63, 'Or Helcias et sa femme louèrent Dieu, au sujet de leur fille, avec Joakim, son mari, et tous leurs parents, parce qu’elle avait été reconnue sans tache.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 64, 'Et Daniel devint grand devant le peuple, à partir de ce jour et dans la suite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'En la troisième année du règne de Joakim, roi de Juda, Nabuchodonosor, roi de Babylone, vint à Jérusalem, et il l’investit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Et le Seigneur lui livra le roi Joakim avec une partie des vases du temple de Dieu, et il emporta ces vases en la terre de Sennaar, où était le temple de son dieu, et il les déposa dans la maison du trésor de son dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Et le roi dit à Asphanez, chef de ses eunuques, de lui amener quelques-uns des fils des captifs d’Israël de la race royale et des princes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Jeunes gens sans infirmité, beaux de formes, initiés à toute sagesse, savants, doués de prudence et dignes d’habiter le palais en présence du roi, et il lui ordonna de les instruire dans la langue et les lettres des Chaldéens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Et le roi ordonna que chaque jour on les nourrît durant trois ans des mets de sa table royale, et du vin dont lui-même buvait, et qu’ensuite ils se tinssent en présence du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Et parmi eux se trouvèrent des fils de Juda, Daniel, Ananias, Azarias et Misaël.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Et le chef des eunuques leur donna des noms: il appela Daniel Baltasar, et Ananias Sidrach, et Misaël Misach, et Azarias Abdénago.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Mais Daniel eut à cœur de ne point se souiller des mets de la table du roi, ni du vin dont il faisait usage, et il pria le chef des eunuques de lui permettre de ne s’en point souiller.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Et Dieu accorda que Daniel obtînt les bonnes grâces et la compassion du chef des eunuques.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Et le chef des eunuques dit à Daniel: J’ai peur que le roi, mon maître, après m’avoir donné des ordres pour vos aliments et votre breuvage, ne vous voie peutêtre mauvais visage, en comparaison des jeunes gens de votre âge; et vous me feriez condamner à mort par le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Et Daniel dit à Amelsad, à qui le chef des eunuques avait confié la garde de Daniel, d’Ananias, de Misaël et d’Azarias:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Éprouve tes serviteurs pendant dix jours, et faisnous donner quelques graines que nous mangerons; et nous boirons de l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Puis regarde notre visage et le visage des jeunes gens qui se seront nourris de la table du roi; et selon ce que tu auras vu, agis à l’égard de tes serviteurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Et il les exauça, et il les éprouva pendant dix jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Et au bout des dix jours il fut reconnu qu’ils avaient le visage meilleur et les chairs plus fermes que les jeunes gens nourris de la table du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Alors Amelsad prit pour lui leurs mets et leur vin, et il leur donna des graines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Et Dieu doua ces quatre jeunes gens de l’intelligence et du savoir, dans tous les exercices de la sagesse et des lettres; et Daniel sut interpréter les visions et les songes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Et à la fin des jours que le roi avait fixés pour qu’on les lui amenât, le chef des eunuques les introduisit devant Nabuchodonosor.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Et le roi leur parla, et, parmi tous ces jeunes gens, il ne s’en trouva point de comparables à Daniel, Ananias, Misaël et Azarias; et ils demeurèrent en présence du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Et dans toutes les questions de sagesse et de science sur lesquelles le roi les interrogea, il les reconnut dix fois plus habiles que les devins et les mages qui étaient en tout son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 21, 'Et Daniel vécut ainsi jusqu’à la première année du règne de Cyrus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'En la seconde année de son règne, Nabuchodonosor eut un songe, et son esprit en fut saisi de stupeur, et le sommeil s’éloigna de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Et le roi ordonna de convoquer les devins et les mages, les sorciers et les Chaldéens, pour interpréter le songe qu’il avait eu. Ils vinrent donc, et ils comparurent devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Et le roi leur dit: J’ai eu un songe, et mon esprit en a été frappé de stupeur au point de ne rien connaître à ce songe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Et les Chaldéens dirent au roi en langue syriaque: 0 roi, vis à jamais, dis ton songe à tes serviteurs, et nous t’en donnerons l’interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Le roi répondit aux Chaldéens: Les paroles se sont éloignées de moi; si vous ne me faites connaître le songe et son interprétation, vous serez mis à mort, et vos maisons seront pillées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Mais si vous me faites connaître le songe et son interprétation, vous recevrez de moi des dons, des présents et de grands honneurs; seulement faites-moi connaître mon songe et son interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Ils répondirent une seconde fois, et dirent: Que le roi dise à ses serviteurs quel songe il a eu, et nous lui en ferons connaître l’interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Et le roi reprit, et dit: En vérité, je sais, moi, que vous voulez gagner du temps, parce que vous voyez que les paroles du songe se sont éloignées de moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Si donc vous ne me dites pas mon songe, je sais que vous êtes convenus entre vous de me dire des paroles fausses et altérées, jusqu’à ce que le temps se soit écoulé. Dites-moi mon songe, et alors je saurai que vous m’en ferez connaître aussi l’interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Les Chaldéens répondirent devant le roi, et ils dirent: Il n’est point d’homme sur la terre qui puisse faire connaître cette parole au roi, de même qu’il n’est point de grand roi ni de prince qui fasse pareille question à un devin, ou mage, ou Chaldéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Car la parole sur laquelle le roi nous questionne est grave, et nul autre que nous ne pourra la découvrir au roi, sinon des dieux dont la demeure n’est pas en la chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Alors le roi, plein de fureur et d’indignation, ordonna que l’on mît à mort tous les sages de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Et sa sentence s’exécuta, et les sages furent mis à mort, et on chercha Daniel et ses amis pour les tuer aussi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Alors Daniel parla avec réflexion et sagesse à Arioch, chef des cuisines du roi, qui était sorti pour mettre à mort les sages de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Ministre du roi, lui dit-il, à quel sujet cet ordre impitoyable est-il sorti de la bouche du roi? Et Arioch fit connaître l’affaire à Daniel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 16, 'Et Daniel demanda au roi de lui accorder du temps, promettant de lui faire connaître l’interprétation du songe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 17, 'Et Daniel rentra dans sa maison, et il raconta l’affaire à Ananias, Misaël, Azarias, ses amis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 18, 'Et ils implorèrent les miséricordes du Dieu du ciel sur ce mystère, afin que ni Daniel ni ses amis ne périssent avec le reste des sages de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 19, 'Alors à Daniel, en une vision nocturne, le mystère fut révélé, et il bénit le Dieu du ciel,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 20, 'Disant: Que le nom du Seigneur soit béni, maintenant et dans tous les siècles, parce que toute sagesse et toute intelligence lui appartiennent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 21, 'C’est lui qui change les heures et les temps, lui qui place et déplace les rois, lui qui donne la sagesse aux sages, et la prudence aux prudents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 22, 'C’est lui qui révèle les choses profondes et cachées, lui qui sait ce qui est dans les ténèbres; et la lumière est avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 23, 'Vous donc, Dieu de mes pères, je vous rends hommage et je vous loue, parce que vous m’avez donné la force et la sagesse, que vous m’avez appris ce que nous vous avons demandé, et que vous m’avez révélé la vision du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 24, 'Et Daniel alla trouver Arioch, que le roi avait chargé de mettre à mort les sages de Babylone, et il lui dit: N’exécute pas les sages de Babylone; mais introduis-moi en présence du roi, et je donnerai au roi l’interprétation du songe qu’il a eu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 25, 'Aussitôt Arioch s’empressa d’introduire Daniel en présence du roi, et il lui dit: J’ai trouvé un homme des fils des captifs de la Judée, qui donnera au roi l’interprétation du songe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 26, 'Et le roi prit la parole, et il dit à Daniel, que l’on nommait Baltasar: Pourras-tu me faire connaître le songe que j’ai eu et son interprétation?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 27, 'Et Daniel répondit devant le roi, disant: Le mystère que le roi me demande, il n’appartient ni aux juges, ni aux mages, ni aux devins, ni aux augures, de le révéler au roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 28, 'Mais c’est Dieu qui, dans le ciel, révèle tous les mystères, et qui a fait connaître au roi Nabuchodonosor ce qui doit arriver dans les derniers jours. Ton songe et les visions de ta tête sur ta couche, les voici:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 29, 'O roi, tes pensées sur ta couche s’étaient portées sur ce qui doit arriver après le moment présent; et Celui qui révèle les mystères t’a fait connaître ce qui doit arriver,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 30, 'Et c’est à moi qu’il a révélé ce mystère, non à cause de la sagesse qui est en moi, ni dans les autres vivants; mais afin que je te découvre, ô roi, l’interprétation de ton songe, et que tu connaisses les pensées de ton cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 31, 'Toi donc, ô roi, tu regardais; et voilà qu’une statue se tint debout devant ta face; cette statue était grande, et son aspect terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 32, 'C’était une statue dont la tête était d’or pur, les mains, la poitrine et les bras d’argent, le ventre et les cuisses d’airain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 33, 'Les jambes de fer, et les pieds partie de fer, partie d’argile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 34, 'Tu regardais, quand une pierre détachée de la montagne, sans qu’une main la poussât, vint frapper la statue à ses pieds de fer et d’argile, et à la fin elle les broya.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 35, 'Alors furent broyés à la fois l’argile, le fer, l’airain, l’argent et l’or, et ils devinrent comme la poudre qui l’été s’élève au-dessus d’une aire; et un souffle violent les emporta, et l’on n’en trouva plus la place. Et la pierre qui avait frappé la statue devint une grande montagne, et elle couvrit toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 36, 'Voilà ton songe, et nous allons en dire l’interprétation devant le roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 37, 'O roi, tu es le roi des rois, à qui le Dieu du ciel a donné un empire puissant, fort et glorieux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 38, 'En tout lieu où demeurent les fils des hommes; toi à qui il a soumis les bêtes fauves des champs, et les oiseaux du ciel, et les poissons de la mer; toi qu’il a établi maître de toutes choses, tu es la tête d’or.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 39, 'Et le royaume qui s’élèvera après toi sera moindre que le tien; puis viendra un troisième royaume, qui sera d’airain, et qui commandera à toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 40, 'Puis viendra un quatrième royaume qui sera fort comme le fer: de même que le fer broie et dompte toutes choses, il broiera et domptera toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 41, 'Et comme tu as vu les pieds et les doigts partie de fer, et partie d’argile, ce royaume sera divisé, et il sera détaché de ses racines de fer, comme tu as vu le fer mêlé à l’argile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 42, 'Et les doigts des pieds étant partie de fer, partie d’argile, une part de ce royaume sera forte, une autre sera broyée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 43, 'Et de même que tu as vu le fer confondu avec l’argile, de même il y aura des mélanges dans la race des hommes; mais ce ne sera pas un tout parfaitement uni, pas plus qu’il n’y a d’alliage entre l’argile et le fer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 44, 'Et du temps de ces rois le Dieu du ciel suscitera un royaume qui ne périra point dans les siècles; et jamais son royaume ne sera subjugué par un autre peuple; et son royaume nivellera et vannera tous les royaumes, et il se maintiendra durant tous les siècles;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 45, 'Comme tu as vu la pierre se détacher de la montagne, sans qu’une main la poussât, et broyer l’argile, le fer, l’airain, l’argent et l’or. C’est ainsi que le grand Dieu a fait connaître au roi ce qui doit arriver après ces temps. Et véritable est le songe, et l’interprétation digne de foi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 46, 'Alors le roi Nabuchodonosor tomba la face contre terre, et il adora Daniel, et il ordonna qu’on lui offrit des oblations et de l’encens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 47, 'Et le roi, prenant la parole, dit à Daniel: En vérité, votre Dieu seul est le Dieu des dieux et le Seigneur des rois; c’est lui qui révèle les mystères; car tu n’aurais pu révéler celui-ci.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 48, 'Et le roi glorifia Daniel; il lui fit de grands et magnifiques présents, et il le mit à la tête de toute la province de Babylone, et il l’institua chef des satrapes et de tous les sages de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 49, 'Et sur la demande de Daniel le roi chargea de toutes les affaires de la province de Babylone Sidrach, Misach et Abdénago, et Daniel resta dans le palais du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'La dix-huitième année de son règne, Nabuchodonosor fit faire une statue d’or, haute de soixante coudées, sur six d’épaisseur, et il l’érigea en la plaine de Déira, dans la province de Babylone.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Et il convoqua les grands, les généraux et les gouverneurs, les rois, les tyrans et les dignitaires, et tous les chefs des provinces pour venir à l’inauguration de la statue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Et les gouverneurs, les grands, les généraux, les rois, les principaux tyrans, les dignitaires et les chefs des provinces se rassemblèrent pour l’inauguration de la statue qu’avait érigée le roi Nabuchodonosor, et ils se placèrent debout devant la statue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Et le héraut proclama à haute voix: Ceci vous est prescrit, peuples, tribus, hommes de toutes langues:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'À l’instant où vous entendrez le son de la trompette et de la flûte, de la cithare, de la harpe et du psaltérion, et des instruments de toute sorte, tombez la face contre terre, et adorez la statue d’or que le roi Nabuchodonosor a érigée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Et celui qui n’adorera pas, en tombant à genoux, sera jeté aussitôt dans la fournaise ardente où le feu est allumé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Or ceci advint: dès que les peuples entendirent le son de la trompette et de la flûte, de la cithare, de la harpe et du psaltérion, et des instruments de toute sorte, les peuples tombèrent la face contre terre, et ils adorèrent la statue d’or que le roi Nabuchodonosor avait érigée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Alors vinrent des hommes de la Chaldée et ils accusèrent les Juifs');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Devant le roi, disant: Ô roi, vis à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Ô roi, tu as fait une ordonnance, disant: Que tout homme qui entendra le son de la trompette et de la flûte, de la cithare, de la harpe et du psaltérion, et des instruments de toute sorte,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Et qui ne tombera pas la face contre terre pour adorer la statue d’or, soit jeté dans la fournaise ardente où le feu est allumé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Or il y a des hommes, des Juifs, que tu as chargés de toutes les affaires de la province de Babylone, Sidrach, Misach et Abdénago, qui n’ont point obéi à ton ordre, ô roi; tes dieux, ils ne les honorent pas; et la statue d’or que tu as érigée, ils ne l’adorent point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Alors Nabuchodonosor, plein de colère et de fureur, commanda de lui amener Sidrach, Misach et Abdénago, et on les amena en présence du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Et Nabuchodonosor prit la parole, et leur dit: Est-il vrai, Sidrach, Misach et Abdénago, que vous ne servez point mes dieux, et que vous n’adorez pas la statue d’or que j’ai élevée?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Maintenant donc, si vous y êtes disposés, aussitôt que vous entendrez le son de la trompette, de la flûte et de la cithare, de la harpe et du psaltérion, et le concert des instruments de toute sorte, tombez la face contre terre, et adorez la statue d’or que j’ai faite. Que si vous ne l’adorez pas, à l’instant même vous serez jetés dans la fournaise ardente, où le feu est allumé; et quel est le Dieu qui vous tirera de mes mains?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Sidrach, Misach et Abdénago répondirent au roi Nabuchodonosor, disant: Il n’est pas nécessaire que nous te fassions une réponse à cette question.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 17, 'Car notre Dieu qui est au ciel, le Dieu que nous servons, peut nous tirer de la fournaise ardente et nous sauver, ô roi, d’entre tes mains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 18, 'Et quand même il ne le ferait pas, sache, ô roi, que tes dieux nous ne les servons pas, et que la statue d’or que tu as élevée, nous ne l’adorons point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 19, 'Alors Nabuchodonosor, plein de colère, changea de visage envers Sidrach, Misach et Abdénago, et il ordonna de rendre sept fois plus ardent le feu de la fournaise, jusqu’à ce qu’enfin il ne fût plus qu’un brasier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 20, 'Et il ordonna à des hommes robustes de mettre des entraves à Sidrach, Misach et Abdénago, puis de les jeter dans la fournaise ardente.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 21, 'Aussitôt ces jeunes gens furent enchaînés sans qu’on leur ôtât ni leurs hauts-de-chausses, ni leurs tiares, ni leurs chaussures, et ils furent jetés au milieu des flammes de la fournaise;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 22, 'Car la parole du roi était pressante, et la fournaise était plus ardente que jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 23, 'Et Sidrach, Misach et Abdénago tombèrent tous trois enchaînés au milieu des flammes de la fournaise embrasée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 24, 'Et ils marchèrent au milieu des flammes, chantant Dieu et bénissant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 25, 'Et Azarias, debout, pria ainsi, et ayant ouvert la bouche au milieu des flammes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 26, 'Béni soyez-vous, dit-il, Seigneur Dieu de nos pères, soyez loué; que votre nom soit glorifié dans tous les siècles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 27, 'Car vous êtes juste en toutes les choses que vous avez faites; toutes vos œuvres sont vraies, vos voies sont droites, et tous vos jugements sont vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 28, 'Et vous avez fait des jugements équitables dans tous les maux que vous avez amenés contre nous et contre Jérusalem, ville sainte de nos pères, puisque vous avez fait toutes ces choses en vérité et en justice, à cause de nos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 29, 'Car nous avons péché, nous nous sommes égarés en nous éloignant de vous, et nous avons failli en toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 30, 'Nous avons été indociles à vos commandements; nous ne les avons pas observés; nous n’avons point fait comme vous nous l’aviez prescrit pour que nous fussions heureux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 31, 'Et tout ce que vous avez amené contre nous, tout ce que vous nous avez fait, vous l’avez fait en justice et en vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 32, 'Et vous nous avez livrés aux mains d’ennemis pervers, d’infidèles abominables, d’un roi inique et le plus méchant de toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 33, 'Et maintenant il ne nous est plus permis d’ouvrir la bouche; nous sommes un sujet de confusion et d’opprobre pour ceux qui vous servent et vous adorent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 34, 'Pour l’amour de votre nom, ne nous livrez pas à jamais; ne rompez pas votre alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 35, 'Ne détournez pas de nous votre miséricorde, en considération d’Abraham, votre bien-aimé, d’Isaac, votre serviteur, de Jacob, votre saint,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 36, 'À qui vous avez promis de multiplier leur postérité autant que les étoiles du ciel et que le sable du rivage de la mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 37, 'Seigneur, nous sommes les moindres en nombre, parmi toutes les nations, et nous sommes humiliés aujourd’hui dans toute la terre, à cause de nos péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 38, 'Et dans le temps présent il n’y a plus pour nous ni chef, ni prophète, ni roi, ni holocaustes, ni sacrifices, ni oblations, ni encens, ni de lieu où nous puissions porter les prémices de nos fruits en votre présence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 39, 'Et obtenir votre miséricorde. Mais l’âme contrite et l’esprit humilié, puissions-nous être accueillis de vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 40, 'Comme un holocauste de béliers et de taureaux comme l’oblation de dix mille agneaux gras, et qu’il arrive jusqu’à vous! car ceux qui ont confiance en vous ne seront jamais confondus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 41, 'Et maintenant, nous nous consacrons à vous de tout notre cœur, nous vous craignons, et nous cherchons votre visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 42, 'Ne nous couvrez pas de honte; mais traitez-nous selon votre mansuétude et selon l’abondance de votre miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 43, 'Délivrez-nous par un de vos prodiges, et donnez la gloire à votre nom, ô Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 44, 'Et qu’ils tremblent tous ceux qui font connaître ces maux à vos serviteurs; qu’ils soient humiliés par votre toute-puissance, et que toute leur force soit brisée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 45, 'Qu’ils sachent que vous êtes le Seigneur, le seul Dieu, le Dieu de gloire qui règne sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 46, 'Cependant les serviteurs du roi qui les avaient jetés dans la fournaise ne cessaient pas d’y brûler du naphte et de la poix, des étoupes et du sarment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 47, 'Et la flamme s’élevait au-dessus de la fournaise à quarante-neuf coudées;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 48, 'Et elle se promena, et brûla ceux des Chaldéens qu’elle trouva autour de la fournaise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 49, 'Et l’ange du Seigneur descendit en même temps vers ceux qui étaient dans la fournaise avec Azarias, et il secoua la flamme hors de la fournaise.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 50, 'Et il fit souffler au milieu de la fournaise comme un vent chargé de rosée; et le feu ne les atteignit aucunement, et il ne leur fit point de mal, et même il ne les incommoda point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 51, 'Alors tous les trois se mirent à chanter d’une seule voix, et ils glorifièrent Dieu, et ils le bénirent du fond de la fournaise, disant:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 52, 'Soyez béni, Seigneur Dieu de nos pères; soyez loué et infiniment exalté dans tous les siècles! Que béni soit votre nom saint et glorieux; qu’il soit célébré, qu’il soit exalté dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 53, 'Vous êtes béni dans le temple de votre gloire sainte; vous êtes au-dessus de toute louange et de toute gloire dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 54, 'Vous êtes béni, vous qui regardez les abîmes, vous qui êtes assis sur les chérubins; vous êtes infiniment loué et exalté dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 55, 'Vous êtes béni sur le trône de votre royauté; vous êtes infiniment loué et exalté dans tous les siècles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 56, 'Vous êtes béni dans le firmament du ciel; vous êtes chanté et glorifié dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 57, 'Œuvres du Seigneur, bénissez toutes le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 58, 'Cieux, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 59, 'Anges du Seigneur, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 60, 'Eaux de la terre, eaux du ciel, bénissez le Seigneur; chantez-le, exaltez-le, infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 61, 'Armée du Seigneur bénis tout entière le Seigneur; chante-le, exalte-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 62, 'Soleil et lune, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 63, 'Étoiles du ciel, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 64, 'Pluie et rosée, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 65, 'Vents, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 66, 'Chaleur et feu, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 67, 'Nuits et jours, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 68, 'Lumière et ténèbres, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 69, 'Froidure et chaleur, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 70, 'Glaces et neiges, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 71, 'Éclairs et nuées, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 72, 'Que la terre bénisse le Seigneur; qu’elle le chante, qu’elle l’exalte infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 73, 'Monts et collines, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 74, 'Plantes de la terre, bénissez toutes le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 75, 'Mer et fleuves, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 76, 'Fontaines, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 77, 'Monstres marins qui vous mouvez dans les ondes, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 78, 'Oiseaux du ciel, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 79, 'Bêtes fauves et troupeaux, bénissez tous le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 80, 'Fils des hommes, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 81, 'Israël, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 82, 'Prêtres, bénissez le Seigneur; chantcz-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 83, 'Serviteurs, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 84, 'Esprits et âmes des justes, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 85, 'Saints et humbles de cœur, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 86, 'Ananias, Azarias, Misaël, bénissez le Seigneur; chantez-le, exaltez-le infiniment dans tous les siècles, parce qu’il nous a tirés des enfers, qu’il nous a sauvés des mains de la mort, délivrés du milieu de la fournaise en flammes, et protégés au milieu du feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 87, 'Rendez gloire ensemble au Seigneur, parce qu’il est bon, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 88, 'Hommes pieux, bénissez le Seigneur, Dieu des dieux; chantez-le et rendez-lui gloire, parce que sa miséricorde est éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 89, 'Et Nabuchodonosor les entendit chanter des hymnes, et il fut frappé d’étonnement, et il se leva précipitamment, et il dit aux grands qui l’entouraient: N’avons-nous pas jeté au milieu du feu trois hommes enchaînés? et ils dirent au roi: Oui, seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 90, 'Et le roi dit: Et moi, je vois quatre hommes sans liens, se promenant au milieu des flammes, et la destruction n’est pas avec eux, et l’aspect du quatrième ressemble à un fils de Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 91, 'Alors Nabuchodonosor s’approcha de la porte de la fournaise ardente, et il dit: Sidrach, Misach, Abdénago, serviteurs du Dieu tout-puissant, sortez et venez! Et Sidrach, Misach et Abdénago sortirent du milieu des flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 92, 'Et les satrapes, et les généraux, et les gouverneurs et les lieutenants du roi se rassemblèrent, et ils virent ces hommes sur qui le feu n’avait eu nulle puissance en leur corps; pas un cheveu de leur tête n’était brûlé; leur vêtement n’était point altéré, et nulle odeur de feu n’était en eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 93, 'Et le roi Nabuchodonosor prit la parole, et il dit: Béni soit le Dieu de Sidrach, de Misach et d’Abdénago, qui a envoyé son ange, et délivré ses serviteurs, parce qu’ils avaient eu confiance en lui; ils désobéirent à la parole du roi, et ils abandonnèrent leurs corps à la flamme, pour ne point adorer ni servir d’autre dieu que leur Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 94, 'Et moi je proclame ce décret: Tout peuple, toute tribu, tout homme, de quelque langue qu’il soit, qui proférera un blasphème contre le Dieu de Sidrach, de Misach et d’Abdénago, sera exterminé; ses maisons seront livrées au pillage; parce qu’il n’est point d’autre Dieu qui puisse sauver ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 95, 'Ensuite le roi rétablit Sidrach, Misach et Abdénago à la tête de la province de Babylone; et il les éleva en honneur, et les jugea dignes de commander à tous les Juifs qui étaient dans son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 96, 'Le roi Nabuchodonosor dit à tous les peuples, à toutes les tribus, à tous les hommes de langues diverses Que la paix se multiplie parmi vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 97, 'Les signes et les prodiges que vient d’accomplir devant moi le Dieu très haut, il me plaît de vous annoncer en personne');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 98, 'Combien ils sont grands et irrésistibles; son royaume est le royaume éternel, et sa puissance s’étend de génération en génération.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 99, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 100, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Moi, Nabuchodonosor, comme j’étais en paix et florissant dans mon palais,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'J’eus un songe, et il m’effraya, et je fus troublé sur ma couche, et les visions de ma tête me troublèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Et, de moi-même, je donnai ordre d’amener en ma présence tous les sages de Babylone, et qu’ils me fissent connaître l’interprétation de mon songe..');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Et les devins et les mages, les sorciers et les Chaldéens arrivèrent, et je dis mon songe devant eux, et ils ne m’en firent pas connaître l’interprétation;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Jusqu’à ce que vînt Daniel, que l’on nommait Baltasar, selon le nom de mon dieu, et qui avait en lui l’Esprit-Saint de Dieu, et je lui dis:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Baltasar, comme chef des devins, je sais que l’Esprit-Saint de Dieu est en toi, et que nul mystère pour toi n’est impénétrable; écoute donc la vision de mon songe, et dis-m’en l’interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Je regardais sur ma couche, et voilà qu’un arbre était au milieu de la terre, et sa hauteur était grande.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'L’arbre crût encore et se fortifia, et sa cime arrivait jusqu’au ciel, et son tronc jusqu’aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Ses feuilles étaient belles, et ses fruits abondants; et l’aliment de tous les êtres se trouvait en lui; sous son ombre s’abritaient les bêtes sauvages, et sur ses rameaux les oiseaux du ciel faisaient leurs nids, et de lui toute chair se nourrissait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'J’étais attentif sur ma couche à cette vision de la nuit, et voilà qu’un veillant et un saint descendit des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Et, parlant à haute voix, il dit: Abattez l’arbre, arrachez ses rameaux, secouez ses feuilles, et dispersez ses fruits; que les bêtes soient chassées de dessous lui, et les oiseaux du ciel de ses branches.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Cependant laissez en terre la souche de ses racines; quant à lui, qu’il reste étendu en des chaînes de fer et d’airain, parmi l’herbe qui l’entoure, à la rosée du ciel; et qu’avec les bêtes il ait sa part de l’herbe de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Son cœur deviendra différent du cœur des hommes; et un cœur de bête lui sera donné; et sept fois les temps changeront sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Telle est la sentence du veillant et la parole des saints, afin que les vivants sachent que le Seigneur est le dominateur du royaume des hommes, et qu’il le donne à qui bon lui semblera, et qu’il élèvera pour le gouverner celui qui est en mépris parmi les hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Tel est le songe que j’ai eu, moi, le roi Nabuchodonosor, et toi, Baltasar, dis-m’en l’interprétation; car nul des sages de mon royaume ne peut me la donner; mais toi, Daniel, tu le peux, parce que l’Esprit-Saint de Dieu est en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Alors Daniel, surnommé Baltasar, réfléchit environ une heure, et ses pensées le troublèrent. Enfin Baltasar répondit: Seigneur, dit-il, que ton songe soit pour ceux qui te haïssent, et son interprétation pour tes ennemis!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 17, 'L’arbre que tu as vu grand et fort, dont la cime allait au ciel, et le tronc sur toute la terre;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 18, 'Dont les feuilles étaient florissantes et les fruits abondants, en qui se trouvait l’aliment de tous, et sous lequel s’abritaient les bêtes sauvages, tandis que les oiseaux du ciel faisaient leur nid dans ses rameaux;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 19, 'Cet arbre, ô roi, c’est toi-même; car tu as grandi et tu t’es fortifié, et ta grandeur n’a cessé de croître, et elle est allée jusqu’au ciel, et ta domination jusqu’aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 20, 'Or quand le roi a vu le veillant et le saint descendre du ciel, et que le saint a dit: Arrachez l’arbre, détruisez-le, mais laissez en terre la souche de ses racines; quant à lui, qu’il reste étendu en des chaînes de fer et d’airain, parmi l’herbe qui l’entoure, exposé à la rosée du ciel, et qu’il partage avec les bêtes l’herbe des champs, jusqu’à ce que les temps aient changé sept fois sur lui:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 21, 'Voici ce que cela signifie, ô roi, et c’est la sentence du Très-Haut, qui d’avance vient avertir le roi mon maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 22, 'On t’exclura du commerce des hommes, et ta demeure sera parmi les bêtes sauvages, et l’on te donnera ta part de fourrage comme à un bœuf, et tu passeras les nuits à la rosée du ciel, et les temps changeront sept fois sur toi, jusqu’à ce que tu reconnaisses que le Très-Haut est le maître du royaume des hommes, et qu’il le donne à qui bon lui semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 23, 'Et puisqu’il a été dit: Laissez en terre la souche des racines de l’arbre, ta royauté subsistera, après que tu auras reconnu la puissance du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 24, 'C’est pourquoi, ô roi, que mon conseil te soit agréable; rachète tes péchés par des aumônes, et tes iniquités par la compassion pour les indigents, et Dieu peut-être sera longanime à tes offenses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 25, 'Or les choses suivantes arrivèrent au roi Nabuchodonosor:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 26, 'Après le douzième mois, comme il se promenait dans son palais royal, en Babylone,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 27, 'Le roi prit la parole, et dit: N’est-ce point là Babylone la grande, que j’ai bâtie pour être ma résidence royale, dans ma force et ma puissance, en l’honneur de ma gloire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 28, 'Cette parole était encore dans la bouche du roi, quand une voix vint du ciel, disant: À toi, roi Nabuchodonosor, il est dit: Ton royaume t’échappe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 29, 'On va te chasser loin des hommes, et ta demeure sera parmi les bêtes sauvages; on te donnera du foin comme à un bœuf, et les temps changeront sept fois sur toi, jusqu’à ce que tu reconnaisses que le Très-Haut est le maître du royaume des hommes, et qu’il le donnera à qui bon lui semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 30, 'À l’heure même, cette parole sur Nabuchodonosor s’accomplit: il fut chassé loin des hommes, il mangea de l’herbe comme un bœuf, et son corps fut baigné par la rosée du ciel, jusqu’à ce que ses cheveux eussent crû comme la crinière d’un lion, et ses ongles comme les griffes des oiseaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 31, 'Et à la fin des jours moi, Nabuchodonosor, je levai les yeux au ciel, et les pensées me revinrent, et je bénis le Très-Haut, et je louai l’Éternel, et je lui rendis gloire, parce que sa puissance est inébranlable, et son royaume pour toutes les générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 32, 'Et tous ceux qui habitent la terre sont comptés pour rien. En l’armée du ciel et parmi les habitants de la terre, il fait à sa volonté, et nul ne peut résister à sa puissance, ni lui dire: Qu’avez-vous fait?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 33, 'Au même instant les pensées me revinrent, et je rentrai dans les honneurs de ma royauté, et ma forme me fut rendue, et mes princes et mes grands me recherchèrent, et une plus grande magnificence me fut rendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 34, 'Maintenant donc, moi, Nabuchodonosor, je louerai et j’exalterai, et je glorifierai le Roi du ciel, parce que toutes ses œuvres sont vraies, que ses sentiers sont la justice, et qu’il est en son pouvoir d’humilier tous ceux qui marchent dans leur orgueil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Le roi Baltasar offrit un magnifique repas à ses grands au nombre de mille, et devant les mille convives il y avait du vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Et Balthasar buvait, et dans l’ivresse du vin i dit que l’on apportât les vases d’or et d’argent enlevés par Nabuchodonosor son père au temple de Jérusalem, et que le roi et ses grands, ses concubines et ses femmes, bussent dans ces vases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Et l’on apporta les vases d’or et d’argent que l’on avait rapportés du temple de Jérusalem, et le roi et ses grands, ses concubines et ses femmes burent dans ces vases.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Ils burent du vin, et ils louèrent leurs dieux d’or et d’argent, d’airain, de fer, de pierre et de bois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Au même instant apparurent des doigts d’homme, et ils écrivirent devant le luminaire sur l’enduit du mur du palais du roi, et le roi suivait du regard le mouvement des phalanges de la main qui écrivait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Alors le roi changea de visage, et ses pensées le troublèrent, et la ceinture de ses reins se dénoua, ses genoux s’entre-choquèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Et le roi, criant de toute sa force, ordonna d’amener les mages, les Chaldéens et les sorciers. Et il dit aux sages de Babylone: Celui qui lira ce qui est écrit, et qui m’en fera connaître l’interprétation, sera revêtu de pourpre, et il aura autour du cou un collier d’or, et dans mon royaume il commandera le troisième après moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Et tous les sages du roi s’avancèrent, et ils ne purent lire ce qui était écrit ni en donner au roi l’interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Et le roi Baltasar fut troublé, et il changea de visage, et ses grands furent troublés comme lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Et la reine entra dans la salle du festin, et elle dit: Roi, vis à jamais, que tes pensées ne se troublent pas, et ne change pas de visage!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Il est dans ton royaume un homme en qui est l’Esprit de Dieu; et du temps de ton père la vigilance et la sagesse furent trouvées en lui, et le roi Nabuchodonosor ton père le fit chef des devins, des mages, des Chaldéens et des sorciers,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Parce que l’esprit était supérieur en lui, et que la prudence et la sagesse étaient en lui pour interpréter les songes, pour répondre aux questions difficiles, pour dénouer les choses inextricables; c’est Daniel, et ton père l’appelait Baltasar; maintenant donc, qu’on l’appelle, et il te fera connaître son interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Alors Daniel fut introduit devant le roi, et le roi dit à Daniel Es-tu Daniel, l’un des fils des captifs de la Judée qu’a transportés mon père?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'J’ai ouï dire que l’Esprit de Dieu est en toi, et que la vigilance, l’intelligence et une sagesse supérieure ont été trouvées en toi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Or maintenant les sages, les mages, les sorciers sont venus devant moi, pour lire cette écriture, et m’en faire connaître l’interprétation; et ils n’ont pu me rien dire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Et moi, j’ai appris que tu peux interpréter les jugements; si donc tu peux lire cette écriture et me l’interpréter, tu seras revêtu de pourpre, tu auras un collier d’or autour du cou, et tu commanderas dans mon royaume, le troisième après moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Et Daniel dit en présence du roi: Que tes présents te restent, donne à un autre les dons de ton palais; pour moi, je te lirai ce qui est écrit, et je t’en ferai connaître l’interprétation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Roi, le Dieu très-haut a donné à Nabuchodonosor ton père la royauté et la magnificence, les honneurs et la gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Et devant la grandeur que Dieu lui avait donnée, les peuples, les tribus, les hommes de toutes langues étaient tremblants et pleins de crainte devant son visage; ceux d’entre eux qu’il voulait tuer, il les tuait; ceux qu’il voulait frapper, il les frappait; ceux qu’il voulait glorifier, il les glorifiait; et ceux qu’il voulait humilier, il les humiliait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Et quand son cœur se fut élevé, et que son esprit se fut endurci dans son orgueil, il fut précipité du trône, et ses honneurs lui furent enlevés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Et il fut chassé loin des hommes, et un cœur lui fut donné comme aux bêtes, et sa demeure fut parmi les ânes sauvages; on lui donna sa part de fourrage comme à un bœuf, et son corps fut baigné par la rosée du ciel, jusqu’à ce qu’il eût reconnu que le Dieu très-haut est le maître du royaume des hommes, et qu’il le donne à qui bon lui semble.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Et toi donc, son fils Baltasar, tu n’as pas non plus humilié ton cœur devant Dieu: ne sais-tu point toutes ces choses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Tu t’es enorgueilli contre le Seigneur Dieu du ciel, et l’on a apporté devant toi les vases de son temple; et toi et tes grands, tes concubines et tes femmes, vous avez bu du vin dans ces vases; et tu as loué les dieux d’or et d’argent, d’airain, de fer, de pierre et de bois, qui ne voient, n’entendent ni ne comprennent; et le Dieu qui tient en sa main ton souffle et toutes tes voies, tu ne l’as point glorifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'C’est pourquoi il a envoyé de devant lui les doigts de cette main, et lui a ordonné de tracer cette inscription.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Or, cette inscription, la voici: Mané, Thécel, Pharès.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 26, 'Et voici l’interprétation de ces paroles: Mané, Dieu a mesuré ton règne, et en a marqué la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 27, 'Thécel, ta royauté a été placée sur la balance, et elle a été trouvée trop légère.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 28, 'Pharès, ton royaume a été divisé, et donné aux Mèdes et aux Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 29, 'Et Baltasar donna ses ordres: et l’on revêtit Daniel de pourpre, et on lui mit autour du cou un collier d’or, et le roi lui-même le proclama le troisième chef du royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 30, 'Et cette même nuit fut tué Baltasar, le roi chaldéen.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 31, 'Et le Mède Darius reçut le gouvernement de son royaume, à l’âge de soixante-deux ans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Et il plut à Darius d’instituer cent vingt satrapes pour être en tout son royaume;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Et au-dessus d’eux, trois gouverneurs, dont l’un fut Daniel, pour que les satrapes leur rendissent compte, et que lui-même n’en fût pas surchargé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Et Daniel fut au-dessus d’eux, parce qu’il y avait en lui un esprit supérieur, et le roi le mit à la tête de tout son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Or les autres gouverneurs et les satrapes s’efforcèrent de trouver un sujet d’accusation contre Daniel, et ils ne purent trouver contre lui ni grief, ni délit, ni soupçon, parce qu’il était fidèle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Et les gouverneurs se dirent: Nous ne trouverons pas de sujet d’accusation contre Daniel, sinon à cause des lois de son Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Alors les gouverneurs et les satrapes comparurent devant le roi, et lui dirent: O roi Darius, vis à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Tous les officiers de ton royaume, généraux et satrapes, magistrats et intendants, ont tenu conseil pour qu’il fût rendu un édit royal, et formellement ordonné que tout homme qui durant trente jours fera une demande soit à un dieu, soit à un homme autre que le roi, sera jeté dans la fosse aux lions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Maintenant, ô roi, rends l’édit, et publie-le, afin que rien ne soit changé à cẽ qu’ont résolu les Perses et les Mèdes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Et le roi Darius fit publier l’édit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Or Daniel, aussitôt qu’il sut ce que prescrivait l’édit, entra dans sa maison, à l’étage supérieur, les fenêtres ouvertes; tourné vers Jérusalem, trois fois par jour il se mit à genoux, priant son Dieu, et lui rendant grâces, comme il avait coutume de le faire auparavant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Cependant ces hommes l’épièrent, et ils surprirent Daniel rendant grâces à son Dieu et lui faisant sa prière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Et s’approchant du roi, ils lui dirent: 0 roi, n’as-tu point rendu cet édit, que tout homme qui, durant trente jours, fera une demande à un dieu ou à un homme autre que le roi, soit jeté dans la fosse aux lions? Et le roi répondit: Ce que vous dites est véritable, et l’édit des Perses et des Mèdes ne sera pas violé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Et ils reprirent, disant au roi: Daniel, l’un des fils des captifs de la Judée, ne s’est point soumis à ton édit, et trois fois par jour il demande à son Dieu ce qu’il veut lui demander.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Aussitôt que le roi eut ouï ces paroles, il en fut fort contristé, et il fut combattu par le désir de sauver Daniel, et jusqu’au soir il fut combattu par le désir de le sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Mais ces hommes dirent à Darius: Sache, ô roi, qu’il est réglé chez les Mèdes et les Perses que nul changement ne peut être fait à un édit, à un décret du roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Et le roi donna ses ordres, et l’on emmena Daniel, et on le jeta dans la fosse aux lions, et le roi dit à Daniel: Ton Dieu que tu sers avec constance, lui-même te délivrera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Et l’on apporta une pierre, et on la posa sur l’ouverture de la fosse, et le roi la scella de son anneau et de l’anneau de ses grands, afin que rien concernant Daniel ne fût changé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Et le roi rentra dans son palais; mais il se coucha sans avoir soupé; on ne lui présenta point d’aliments, et le sommeil s’éloigna de lui. Et Dieu ferma la gueule des lions, et ils ne firent aucun mal à Daniel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Et le roi se leva de grand matin, dès les premières lueurs du jour, et il alla en toute hâte à la fosse aux lions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Et, quand il fut près de la fosse, il cria à haute voix: Daniel, serviteur du Dieu vivant, ton Dieu, que tu sers avec constance, a-t-il pu te sauver de la gueule des lions?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Et Daniel dit à Darius: Roi, vis à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 22, 'Mon Dieu m’a envoyé son ange, et il a fermé la gueule des lions, et ils ne m’ont fait aucun mal, parce qu’à ses yeux j’ai été trouvé juste, et qu’à ton égard, ô roi, je n’ai fait aucune offense.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 23, 'À ces mots le roi fut extrêmement réjoui, et il ordonna de retirer Daniel de la fosse, et il fut trouvé sain et sauf, parce qu’il avait mis sa confiance en Dieu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 24, 'Et le roi donna ses ordres, et l’on amena les hommes qui avaient accusé Daniel, et on les jeta dans la fosse aux lions, eux, leurs fils et leurs femmes; et avant qu’ils eussent touché le fond de la fosse, les lions s’en emparèrent et leur broyèrent tous les os.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 25, 'Alors le roi Darius écrivit à tous les peuples, aux tribus, aux hommes de toutes langues, à tous les habitants de la terre: Que la paix se multiplie parmi vous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 26, 'Le présent édit est rendu par moi pour toutes les principautés de mon royaume, afin que chacun soit plein de crainte et de tremblement devant la force du Dieu de Daniel; car lui seul est le Dieu vivant, et il demeure dans tous les siècles, et son royaume ne périra jamais, et son règne durera jusqu’à la fin des temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 27, 'Il protège et il sauve, et il fait des signes et des miracles dans le ciel et sur la terre; c’est lui qui a tiré Daniel de la griffe des lions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 28, 'Et Daniel vécut plein de prospérité, sous le règne de Darius et sous le règne de Cyrus le Perse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 1, 'La première année du règne de Baltasar, roi des Chaldéens, Daniel eut un songe et des visions comme sa tête reposait sur sa couche, et il écrivit sa vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 2, 'Moi, Daniel, je regardais, et voilà que les quatre vents du ciel se déchaînèrent sur la grande mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 3, 'Et quatre grandes bêtes sortirent de la mer, différentes les unes des autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 4, 'La première était comme une lionne, et ses ailes étaient comme les ailes d’un aigle; et pendant que je la regardais, ses ailes lui furent arrachées; et elle fut relevée de terre, et elle se tint sur des pieds d’homme, et un cœur d’homme lui fut donné.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 5, 'Et voilà que la seconde bête ressemblait à une ourse, et elle était couchée sur le flanc, et elle tenait dans ses dents trois côtes, et on lui disait: Lève-toi, et rassasie-toi de carnage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 6, 'Après cela, je regardai, et voilà qu’il y avait une autre bête, comme un léopard; et elle avait sur le haut du corps quatre ailes d’oiseau, et elle avait quatre têtes, et la puissance lui avait été donnée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 7, 'Après cela, je regardai, et voilà qu’il y avait une quatrième bête, effroyable, horrible, et d’une force prodigieuse; et ses dents étaient de fer; et elle allait dévorant, broyant, foulant le reste à ses pieds; et la différence était très-grande entre elle et toutes les bêtes qui la précédaient; et elle avait dix cornes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 8, 'Je fis attention à ses cornes; et voilà qu’au milieu d’elles s’éleva une petite corne, et devant elle trois des premières cornes furent déracinées; et voilà que cette corne avait des yeux, comme des yeux d’homme, et une bouche disant de grandes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 9, 'Et je regardai jusqu’à un endroit où des trônes étaient placés; et l’Ancien des jours était assis; et sa robe était blanche comme de la neige, et ses cheveux ressemblaient à la laine la plus pure; son trône était de flamme et ses roues un feu ardent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 10, 'Un fleuve de feu coulait en sa présence; il avait des mille milliers de serviteurs; et des myriades de myriades l’assistaient; le jugement s’assit, et les livres furent ouverts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 11, 'Je fus attentif alors au bruit des paroles superbes que cette corne disait, quand la bête fut tuée, exterminée, et son corps jeté au feu pour être brûlé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 12, 'Et la puissance des autres bêtes leur fut ôtée; mais leur vie fut encore prolongée quelque temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 13, 'Je considérais cette vision de la nuit; et voilà qu’avec les nuées du ciel vint comme le Fils de l’homme, et il s’avança jusqu’à l’Ancien des jours, et il se présenta devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 14, 'Et il lui fut donné pouvoir, honneur et royauté; et les peuples, les tribus et les hommes de toutes langues le servirent. Sa puissance est une puissance éternelle qui ne passera point, et son royaume ne périra jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 15, 'Pour moi, Daniel, mon âme frémit en tout mon être, et les visions de ma tête me troublèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 16, 'Et je m’approchai de l’un des assistants, et je cherchai à apprendre de lui le sens vrai de toutes ces choses, et il me dit la vérité, et il me fit connaître l’interprétation de ces choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 17, 'Ces quatre bêtes sont les quatre empires qui s’élèveront sur la terre et qui seront renversés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 18, 'Et les saints du Très-Haut recueilleront la royauté, et ils la conserveront pendant les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 19, 'Et je m’informai avec soin de la quatrième bête, parce qu’elle était différente de toutes les autres, et encore plus épouvantable; ses dents étaient de fer et ses griffes d’airain; et elle allait dévorant, broyant et foulant le reste à ses pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 20, 'Et je m’informai des dix cornes de sa tête, et de cette autre qui s’était élevée et avait déraciné quelquesunes des premières, et qui avait des yeux et une bouche disant de grandes choses, et dont l’aspect était plus terrible que celui des autres bêtes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 21, 'J’étais attentif, et cette corne engagea la bataille avec les saints, et elle prévalut sur eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 22, 'Jusqu’à la venue de l’Ancien des jours; et il rendit justice aux saints du Très-Haut; et le temps arriva, et les saints possédèrent le royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 23, 'Et l’assistant me dit: La quatrième bête sera le quatrième empire sur la terre; elle dominera sur tous les royaumes; elle dévorera toute la terre; elle la foulera aux pieds et la détruira.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 24, 'Et ses dix cornes sont dix rois qui s’élèveront, et après eux un autre s’élèvera, qui surpassera en mal tous les précédents et subjuguera trois rois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 25, 'Et il parlera contre le Très-Haut, et il effacera les saints du Très-Haut, et il pensera changer les temps et la loi; et les saints lui seront livrés pendant un temps, et deux temps, et un demi-temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 26, 'Et le jugement sera rendu, et la royauté lui sera ôtée, et il sera effacé, et il sera détruit à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 27, 'Et la royauté, la puissance et la magnificence des rois qui sont sous le ciel a été donnée aux saints du Très-Haut. Et son royaume est un royaume éternel, et toutes les dominations le serviront et lui obéiront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 28, 'Là finit le songe. Pour moi, Daniel, mes pensées me troublèrent longtemps, et je changeai de visage, et je conservai toutes ces paroles en mon cœur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 1, 'En la troisième année du règne de Baltasar, une vision m’apparut à moi, Daniel, après celle qui m’était d’abord apparue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 2, 'J’étais dans le palais à Suse, qui est au pays d’Élam, et j’étais sur la rive du fleuve Ubal.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 3, 'Et je levai les yeux, et je regardai; et voilà qu’un bélier se tenait devant l’Ubal. Et il avait de grandes cornes, et l’une était plus grande que l’autre, et allait toujours croissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 4, 'Et je vis le bélier frappant de ses cornes du côté de la mer, de l’aquilon et du midi; et devant lui nulle bête ne pouvait tenir, et nul ne pouvait échapper à ses coups, et il fit ce qu’il voulut, et il devint grand.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 5, 'Et j’étais là, le regardant; et voilà qu’un jeune bouc vint du sud-ouest, sur la face de toute la terre, et il ne touchait pas à terre; et ce bouc avait une corne entre les yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 6, 'Et il arriva jusqu’au bélier qui avait des cornes, celui que j’avais vu en face de l’Ubal; et il s’élança contre lui dans toute la force de sa fureur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 7, 'Et je le vis atteindre le bélier, et il se rua sur lui, et il le frappa, et lui brisa les deux cornes et le bélier fut sans force pour lui résister en face. Puis il le jeta contre terre, et il le foula aux pieds, et nul n’était là pour délivrer le bélier de ses coups.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 8, 'Or le bouc grandit à l’excès; et pendant qu’il croissait en force, sa grande corne se brisa, et quatre autres cornes lui poussèrent au-dessous de celle-ci, des quatre côtés du ciel, d’où viennent les vents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 9, 'Et de l’une de ces cornes sortit une autre corne puissante, qui s’éleva prodigieusement contre le midi et contre un peuple fort;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 10, 'Et même elle s’éleva jusqu’à l’armée du ciel; et elle fit tomber du ciel une partie de l’armée et une partie des étoiles, et elles furent foulées aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 11, 'Et il en fut ainsi, jusqu’à ce que le chef de l’armée eût délivré ses captifs; et à cause de ce bouc les sacrifices furent interrompus, et il prospérera, et le sanctuaire sera désolé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 12, 'Et au lieu de victimes les offrandes furent le péché, et la justice fut renversée à terre. Pour lui, il fera son œuvre, et il prospérera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 13, 'Et j’entendis l’un des saints qui parlait, et l’un des saints dit à un autre qui m’était inconnu: Jusques à quand durera cette vision des sacrifices abolis, du péché, cause de cette désolation, du sanctuaire et de l’armée céleste foulés aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 14, 'Et le premier répondit: Du soir au matin, durant deux mille quatre cents jours, puis le sanctuaire sera purifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 15, 'Et ceci advint: tandis que moi, Daniel, j’avais cette vision et que je cherchais à la comprendre, voilà que la vision d’un homme se dressa devant moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 16, 'Et j’entendis une voix d’homme, entre l’Ubal et moi, et elle appela et dit: Gabriel, explique à celui-ci sa vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 17, 'Et Gabriel s’approcha, et il se tint auprès de moi, et pendant qu’il venait j’étais frappé de crainte; et je tombai la face contre terre, et il me dit: Comprends, fils de l’homme; car cette vision s’accomplira au temps marqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 18, 'Et pendant qu’il me dit ces paroles, je retombai encore la face contre terre, et il me toucha, et il me remit debout sur mes pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 19, 'Et il me dit: Je vais te faire savoir ce qui adviendra aux derniers jours de la colère; car c’est aussi le temps marqué pour l’accomplissement de ta vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 20, 'Le bélier que tu as vu ayant des cornes est le roi des Mèdes et des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 21, 'Le bouc est le roi des Hellènes; et la grande corne qu’il avait entre les deux yeux est leur premier roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 22, 'Et quand elle a été brisée, les quatre cornes qui se sont élevées au-dessous sont quatre rois qui s’élèveront parmi les nations, mais non par leur propre force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 23, 'Et à la fin de leurs règnes, quand la mesure de leurs péchés sera remplie, un roi s’élèvera, au front impudent, comprenant les énigmes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 24, 'Et sa force sera grande, et il détruira des choses admirables, et il prospérera, et il entreprendra, et il détruira les forts et le peuple saint.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 25, 'Et le joug de sa chaîne sera bien dirigé; la fraude à la main, il se glorifiera en son cœur; il fera périr par ses ruses une multitude d’hommes, et il s’affermira par la ruine de plusieurs; et il les écrasera comme un œuf dans la main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 26, 'Cette vision que tu as eue du soir au matin est véritable; mets-y le sceau, parce qu’elle ne s’accomplira qu’après bien des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 27, 'Après cela, moi, Daniel, je fus alité et je tombai dans la langueur; puis je me levai, et je m’appliquai aux affaires du roi, et je fus émerveillé de ma vision; mais il n’y eut personne pour la comprendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 1, 'En la première année du règne de Darius, fils d’Assuérus, de la race des Mèdes, qui régna sur l’empire des Chaldéens,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 2, 'Moi, Daniel, je compris, au moyen des livres, le nombre des années que la parole du Seigneur avait fait connaître à Jérémie le prophète, sur le temps que devait durer la désolation de Jérusalem, et qui devait être de soixante-dix années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 3, 'Et je tournai mon visage vers le Seigneur mon Dieu, pour l’implorer et le prier, en jeûnant, et revêtu d’un cilice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 4, 'Et je fis ma prière au Seigneur mon Dieu, et je lui rendis gloire, et je dis: Seigneur, Dieu grand et admirable, qui gardez votre alliance, et réservez votre miséricorde en faveur de ceux qui vous aiment et observent vos commandements;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 5, 'Nous avons péché; nous avons commis l’injustice et l’iniquité; nous nous sommes retirés de vous; nous avons dévié de vos ordonnances et de vos jugements,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 6, 'Et nous n’avons point écouté vos serviteurs les prophètes, qui, en votre nom, parlaient à nos rois, à nos princes, à nos pères et à tout le peuple de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 7, 'À vous, Seigneur, est la justice; à nous la honte au visage, comme aujourd’hui à tout homme de Juda, à tout habitant de Jérusalem, à tout Israël, soit près d’ici, soit au loin, en toute région où vous les avez dispersés à cause des prévarications qu’ils ont commises.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 8, 'En vous, Seigneur, est notre justice; à nous la honte au visage, à nous, à nos rois, à nos princes et à nos pères; car nous avons tous péchés contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 9, 'À vous, Seigneur notre Dieu, les miséricordes et le pardon; car nous nous sommes retirés de vous,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 10, 'Et nous n’avons point écouté la voix du Seigneur notre Dieu, pour marcher dans les lois qu’il nous a données, face à face, par les mains de ses serviteurs les prophètes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 11, 'Tout Israël a transgressé votre loi; il s’est détourné tout entier, pour ne pas entendre votre parole. Et votre malédiction est tombée sur nous, ainsi que l’imprécation écrite dans la loi de Moïse, serviteur de Dieu, parce que nous avons péché contre vous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 12, 'Et Dieu a confirmé ses paroles prononcées contre nous et contre les juges qui nous jugeaient, et qui ont amené sur nous de si grands maux, que jamais rien sous le ciel n’advint comme ce qui est advenu à Jérusalem;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 13, 'Comme il est écrit en la loi de Moïse: Tous ces maux sont arrivés sur nous, et nous n’avons point, prié devant la face du Seigneur notre Dieu, pour qu’il nous retirât de nos iniquités, et nous fit comprendre toute sa vérité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 14, 'Mais le Seigneur a veillé sur nous, et il a amené sur nous ces maux, parce que le Seigneur notre Dieu est juste en toutes ses œuvres, et que nous n’avions point écouté sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 15, 'Et maintenant, Seigneur notre Dieu, qui par votre main puissante avez délivré votre peuple de la terre d’Égypte, et qui vous êtes fait alors un nom comme aujourd’hui, nous avons péché, nous avons commis l’iniquité!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 16, 'Seigneur, votre miséricorde est pour tous; que votre indignation et votre colère se détourne de votre ville de Jérusalem et de votre montagne sainte; car nous avons péché, et à cause de nos iniquités et de celles de nos pères, Jérusalem et votre peuple sont devenus un sujet d’opprobre pour tous ceux qui nous entourent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 17, 'Et maintenant, Seigneur notre Dieu, écoutez la prière de votre serviteur et ses supplications; faites briller votre face dans votre sanctuaire délaissé; faites-le pour vous, Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 18, 'Inclinez votre oreille, Seigneur mon Dieu, et exaucez-nous; ouvrez les yeux, et voyez notre anéantissement et celui de la cité à laquelle était donné votre nom; car ce n’est point dans l’attente de vos jugements que nous jetons devant vous notre cri de pitié, mais en vue de vos abondantes miséricordes, ô Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 19, 'Exaucez-moi, Seigneur; apaisez-vous, Seigneur; aimez-moi, Seigneur: ne différez pas, ô mon Dieu, pour l’amour de vous-même; car cette cité et ce peuple sont ceux à qui a été donné votre nom.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 20, 'Et comme je parlais encore, comme je priais, et que je confessais mes péchés et les péchés d’Israël, mon peuple; comme je jetais en face du Seigneur mon Dieu mon cri de pitié pour la montagne sainte;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 21, 'Tandis que je parlais encore, voilà que l’homme Gabriel, qui m’était apparu au commencement de ma vision, vint en volant, et me toucha vers l’heure du sacrifice du soir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 22, 'Et il m’ouvrit l’intelligence, et il me parla et me dit Daniel, je suis venu pour t’apporter l’intelligence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 23, 'Au commencement de ta prière, un ordre m’est venu, et je suis venu pour t’instruire; car tu es l’homme des désirs, dit-il. Réfléchis donc à ma parole et comprends ta vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 24, 'Soixante-dix semaines ont été assignées à ton peuple et à la cité sainte, pour que le péché soit à sa fin, que les péchés soient abolis, que les iniquités soient effacées et expiées, que l’éternelle justice soit ramenée, que le sceau soit mis à la vision et au prophète, et que le Saint des saints soit marqué de l’onction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 25, 'Sache donc et comprends qu’à partir de l’ordre qui sera donné de parler et de rebâtir Jérusalem, jusqu’au roi Christ, il y aura sept semaines et soixante-deux semaines; et l’ancien temps reviendra, les places et les remparts seront relevés, et les temps accomplis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 26, 'Et après les soixante-deux semaines le Christ sera mis à mort, et il n’y aura pas en lui de sujet de condamnation; et il détruira la ville et le sanctuaire, à l’aide d’un chef qui surviendra; et ils disparaîtront dans un cataclysme, et à la fin de la guerre, qui sera abrégée, il livrera la ville aux désolations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 27, 'Et durant une semaine il confirmera l’alliance avec plusieurs. Et au milieu de la semaine la victime et les libations me seront ôtées, et l’abomination de la désolation sera sur le temple, et la désolation aura sa fin à la consommation des temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 1, 'En la troisième année du règne de Cyrus, roi des Perses, une parole fut révélée à Daniel, que l’on nommait Baltasar. Et cette parole était véritable, et une grande force et une grande intelligence lui furent données en cette vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 2, 'En ces jours-là, moi, Daniel, je fus pleurant durant trois semaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 3, 'Je ne mangeai point de pain agréable au goût; ni chair ni vin n’entrèrent dans ma bouche, et je n’usai d’aucun parfum, jusqu’à ce que les trois semaines fussent accomplies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 4, 'Le vingt-quatrième jour du premier mois, j’étais sur les bords du grand fleuve que l’on appelle le Tigre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 5, 'Et je levai les yeux, et je regardai; et voilà qu’il y avait un homme vêtu de lin, et ses reins étaient ceints d’or d’Ophaz;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 6, 'Et son corps était comme Tharsis, et son front avait l’aspect d’un éclair; et ses yeux étaient comme des lampes de feu; ses bras et ses jambes avaient l’aspect de l’airain resplendissant; et sa voix, quand il parlait, était comme la voix d’une multitude.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 7, 'Et moi, Daniel, j’eus seul cette vision, et les hommes qui étaient avec moi ne la virent point; mais un grand trouble les saisit, et ils s’enfuirent de terreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 8, 'Et moi je restai seul, et j’eus cette grande vision; et mes forces m’abandonnèrent, et la gloire de mon visage en fut altérée, et je ne pus recouvrer ma force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 9, 'Et j’entendis retentir ces paroles; et, en les entendant, j’étais plein d’épouvante, et j’avais la face contre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 10, 'Et voilà qu’une main me toucha, et me releva sur mes genoux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 11, 'Et il me dit: Daniel, homme des désirs, comprends les paroles que je te dis, et tiens-toi debout; car je suis envoyé vers toi; et pendant qu’il me dit ces mots je me relevai tremblant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 12, 'Et il me dit: N’aie point peur, Daniel; car du premier jour où tu as appliqué ton cœur à converser avec le Seigneur ton Dieu, et à t’affliger devant lui, tes prières ont été entendues, et je suis venu à tes prières.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 13, 'Or le prince du royaume des Perses m’a résisté vingt et un jours, et Michel, l’un des archanges, est venu à mon aide, et je l’ai laissé au lieu où j’étais, avec le prince du royaume des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 14, 'Et je suis venu t’enseigner les choses qui adviendront à ton peuple dans les derniers jours; car cette vision est pour bien des jours encore.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 15, 'Et pendant qu’il me dit ces paroles, je retombai la face contre terre, et je fus rempli d’épouvante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 16, 'Et voilà qu’une image du fils de l’homme me toucha les lèvres, et j’ouvris la bouche, et je parlai; et je dis à celui qui se tenait devant moi: Seigneur, à votre vue mes entrailles ont été émues, et j’ai perdu ma force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 17, 'Et comment, ô seigneur, votre serviteur pourra-t-il s’entretenir avec vous, mon seigneur? Je ne puis plus recouvrer aucune force, et il n’est plus de souffle en moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 18, 'Et celui qui avait l’apparence d’un homme s’approcha, me toucha de nouveau et me raffermit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 19, 'Et il me dit: N’aie point peur, homme des désirs; la paix soit avec toi; sois homme et sois fort. Et pendant qu’il me dit ces mots je me fortifiai, et je dis: Parlez-moi, seigneur, car vous m’avez fortifié.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 20, 'Et il me dit: Sais-tu pourquoi je suis venu te trouver? Maintenant je vais retourner combattre le roi des Perses; car comme j’entrais ici, le roi des Hellènes est venu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 21, 'Or je te dirai ce qui est prescrit en l’Écriture au livre de vérité: Nul ne m’assiste en toutes ces choses, sinon Michel, votre prince.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 1, 'Je suis celui qui, en la première année du règne de Cyrus, se tint près de lui pour le fortifier et l’affermir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 2, 'Et maintenant je te ferai connaître la vérité: trois rois régneront encore sur la Perse; le quatrième prospérera et les surpassera tous en richesses; et lorsqu’il sera en possession de ses richesses, il fera la guerre à tous les royaumes des Hellènes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 3, 'Et un roi puissant s’élèvera, et il sera maître d’un grand empire, et il fera ce qu’il voudra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 4, 'Et, au moment où son empire sera affermi, il sera brisé et partagé aux quatre vents du ciel; et il ne passera point à ses descendants, et il ne gardera point sa puissance selon ses désirs; car sa royauté lui sera arrachée; puis elle passera à d’autres après lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 5, 'Et le roi du midi se fortifiera; mais l’un de ces princes prévaudra contre lui, et il dominera sur un grand royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 6, 'Et quelques années après ils s’uniront; et la fille du roi du midi ira trouver le roi de l’aquilon pour faire alliance avec lui; mais elle ne retirera pas de là un bras puissant; et la race du vainqueur ne se maintiendra pas; et elle-même sera livrée avec ceux qui la conduisaient, et la jeune fille, et celui qui la fortifiait en ces temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 7, 'Mais un rejeton de la fleur de sa racine s’élèvera bientôt après; et il s’avancera à la tête d’une armée, et il entrera dans les forteresses du roi de l’aquilon; il combattra contre elles, et il s’en rendra maître.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 8, 'Et il transportera en Égypte, avec les captifs, leurs dieux et leurs statues de fonte et leurs objets précieux d’argent et d’or; et lui-même subsistera plus longtemps que le roi de l’aquilon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 9, 'Celui-ci à son tour entrera dans le royaume du roi du midi, puis il retournera en sa propre terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 10, 'Et ses fils parmi maintes nations rassembleront une grande multitude; et l’un d’eux se mettra en campagne; et en sa marche il s’avancera comme un torrent débordé; il passera, il campera et rassemblera ses forces pour le combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 11, 'Et le roi du midi s’effarouchera, et il s’avancera pour combattre le roi de l’aquilon; et il lèvera une grande armée, et une grande multitude d’ennemis lui sera livrée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 12, 'Et il prendra captive cette multitude, et son cœur s’enorgueillira, et il massacrera des myriades d’ennemis; mais il n’en sera pas plus puissant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 13, 'Car le roi de l’aquilon reviendra, et il conduira des troupes en plus grand nombre que la première fois; et à la fin des temps et des années une armée envahissante arrivera avec une grande force et de grands approvisionnements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 14, 'Et en ce temps-là plusieurs se soulèveront contre le roi du midi, et des fils de ton peuple s’élèveront comme un fléau pour accomplir une vision; mais ils manqueront de force.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 15, 'Car le roi de l’aquilon s’avancera; il élèvera des terrasses; il prendra des villes fortes; et les bras du roi du midi soutiendront le choc, et ses troupes d’élite se lèveront; mais ils ne seront pas de force à résister.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 16, 'Et le roi de l’aquilon, après l’avoir ainsi envahi, fera tout ce qu’il voudra, et nul ne tiendra devant lui. Et il s’arrêtera en la terre de Sabé; et il la détruira de sa main.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 17, 'Et il tournera son visage pour entrer en forces dans le royaume du midi, et toutes choses prospéreront devant lui; il donnera au roi ennemi une fille des femmes pour le perdre; mais il n’y réussira point, et elle ne sera pas à lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 18, 'Alors il tournera son visage contre les îles, et il en prendra plusieurs; et il arrêtera d’abord les princes de son opprobre; mais son opprobre retombera sur lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 19, 'Et il retournera son visage vers la force de sa terre; mais il sera affaibli, et il tombera, et on ne le retrouvera plus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 20, 'Et de sa racine s’élèvera un rejeton qui sera comme un plant sur le trône qu’il occupait avec gloire. Et en ces jours-là il sera encore brisé, mais non en face, non dans un combat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 21, 'Un autre prendra sa place, qui sera méprisé; on ne lui aura point accordé les honneurs de la royauté; mais il viendra avec ruse, et à force d’artifices il se rendra maître du royaume,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 22, 'Et les bras de son adversaire seront énervés devant sa face; ils seront brisés, ainsi que le chef de l’alliance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 23, 'Et après leur traité, il trompera encore celui-ci; il s’avancera, et prévaudra sur lui avec un petit nombre de troupes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 24, 'Il viendra en des régions paisibles et opulentes; et il fera ce que n’ont fait ni ses pères ni les pères de ses pères; il emportera leur butin, leurs dépouilles, leurs richesses, et il concevra de mauvais desseins contre l’Égypte; mais cela n’aura qu’un temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 25, 'Et sa force et son cœur s’élèveront avec une grande force contre le roi du midi; et le roi du midi soutiendra aussi la guerre avec une force très-grande et très-redoutable; mais ses armées ne tiendront pas, parce que de mauvais desseins auront été formés contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 26, 'On mangera avec lui; puis on le brisera, et son ennemi engloutira ses armées, et les morts tomberont en foule.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 27, 'Et les deux rois, le cœur plein de perversité, assis à la même table, se diront des mensonges; mais cela ne réussira pas, parce que leur fin arrivera au temps marqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 28, 'Et le roi de l’aquilon retournera en sa terre avec de grandes richesses; et son cœur sera opposé à l’alliance sainte, et il fera de grandes choses, et il rentrera dans son royaume.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 29, 'Il reviendra au temps marqué, et marchera contre le midi; mais cette dernière invasion ne sera pas comme la première.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 30, 'Les Citians, sortis de leurs pays, marcheront contre lui; et par eux il sera abaissé, et il battra en retraite; il s’irritera contre l’alliance sainte, et agira contre elle; puis il se remettra en campagne, et s’entendra avec ceux qui auront abandonné l’alliance sainte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 31, 'Et des rejetons de lui s’élèveront, et ils profaneront le sanctuaire de la Toute-Puissance, et ils feront cesser le sacrifice perpétuel, et ils le remplaceront par l’abomination de la désolation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 32, 'Et les impies feront alliance entre eux pour faire le mal; mais un peuple connaissant son Dieu prévaudra et agira vaillamment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 33, 'Et les sages du peuple comprendront beaucoup de choses; toutefois ils seront affaiblis par le glaive, par le feu, par la captivité, et par un pillage qui durera bien des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 34, 'Et dans leur détresse ils recevront un faible secours; mais plusieurs se joindront à eux avec des vues perfides,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 35, 'Et parmi les sages quelques-uns auront beaucoup à souffrir pour être purifiés, élus et manifestés aux derniers jours; car ces choses doivent s’accomplir au temps marqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 36, 'Et le roi fera selon sa volonté; il s’élèvera, et il se glorifiera contre toute divinité, et il parlera un langage superbe, et il prospèrera jusqu’à ce que la colère de Dieu s’accomplisse; car cela doit finir ainsi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 37, 'Et il ne reconnaîtra aucun des dieux de ses pères; il sera épris des femmes, et ne reconnaîtra aucun dieu; car il se croira plus grand qu’eux tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 38, 'Et il honorera le dieu Maozim en son temple, et il le glorifiera en lui offrant de l’or, de l’argent, des pierres précieuses et des choses de prix, ce dieu que ses pères ne connaissaient pas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 39, 'Et il donnera place dans les forteresses de refuge à un dieu étranger; il multipliera ses honneurs; il lui assujettira beaucoup d’hommes, et il partagera la terre pour en faire des présents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 40, 'Et au temps marqué il sera aux prises avec le roi du midi; et le roi de l’aquilon conduira contre lui une multitude de chars, de cavaliers, de vaisseaux, et il envahira sa terre, et il la traversera, et il la foulera aux pieds.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 41, 'Et il entrera dans la terre de Sébaïm, et beaucoup succomberont. Et voici ceux qui échapperont à sa main: Édom, Moab et la principauté des fils d’Ammon.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 42, 'Et il étendra son bras sur la terre de Palestine, et l’Égypte ne sera pas sauvée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 43, 'Et il se rendra maître des lieux où sont cachés l’or et l’argent et tout ce qu’il y a de précieux en Égypte, en Libye et en Éthiopie, et dans leurs forteresses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 44, 'Puis des rumeurs, des nouvelles pressantes, de l’orient et du nord, le troubleront; et il viendra plein de colère pour exterminer beaucoup d’ennemis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 45, 'Et il dressera les tentes de son palais entre les mers, sur la montagne sainte de Sébaïn, et il y viendra jusqu’à sa fin, et nul ne pourra le sauver.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 1, 'En ce temps-là s’élèvera Michel le grand prince, celui qui veille sur les fils de ton peuple. Et ce sera un temps de tribulation, de tribulation telle qu’il n’y en a jamais eu de semblable depuis qu’il y a des nations sur la terre jusqu’à ce jour. En ce temps-là sera sauvé tout homme de ton peuple qui sera inscrit dans le livre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 2, 'Et nombre de ceux qui dorment sous des amas de terre se réveilleront, les uns pour la vie éternelle, les autres pour la honte et la confusion éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 3, 'Et les sages brilleront comme les luminaires du firmament, et nombre de justes comme les étoiles, dans les siècles et au delà.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 4, 'Pour toi, Daniel, renferme ces paroles, scelle le livre jusqu’au temps de l’accomplissement de ces choses; car beaucoup viendront y apprendre, et par lui la science se multipliera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 5, 'Et moi, Daniel, je regardai, et voilà qu’il y avait comme deux autres hommes se tenant l’un sur une rive du fleuve, l’autre sur l’autre rive.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 6, 'Et l’un d’eux dit à l’homme vêtu de lin, qui était au-dessus de l’eau du fleuve: Quand s’accompliront ces prodiges dont tu as parlé?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 7, 'Et j’entendis l’homme vêtu de lin, qui était au-dessus de l’eau du fleuve; il leva les deux mains vers le ciel, et il jura par Celui qui vit éternellement qu’après un temps, deux temps et la moitié d’un temps à la fin de la dispersion, toutes ces choses seraient connues.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 8, 'Et j’entendis, mais je ne compris pas, et je dis: Seigneur, quelle sera la fin de ces choses?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 9, 'Et il dit: Va, Daniel; car ces paroles seront renfermées et scellées, jusqu’à ce que les temps soient venus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 10, 'Plusieurs seront élus, blanchis, éprouvés comme par le feu et sanctifiés; et les pécheurs pècheront, et nul des pécheurs ne comprendra, mais les sages comprendront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 11, 'Et à partir du temps où a été supprimé le sacrifice perpétuel, l’abomination de la désolation durera douze cent quatre-vingt-dix jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 12, 'Heureux celui qui attendra et parviendra jusqu’à mille trois cent trente-cinq jours!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 13, 'Pour toi, va, et sois en repos; car bien des jours et des heures s’écouleront encore avant que les temps s’accomplissent, et à la fin des temps tu ressusciteras pour recueillir ton partage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, '(Vulg., XIII, 65.) Et le roi Astyage fut réuni à ses pères, et Cyrus lui succéda comme roi des Perses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, '(Vulg., XIV, 1.) Et Daniel était l’un des convives du roi, et plus honoré qu’aucun de ses favoris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, '(2.) Et il y avait chez les Babyloniens une idole qu’on appelait Bel, et chaque jour on consumait pour elle douze artabes de fleur de farine, quarante brebis et six mesures de vin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, '(3.) Et le roi l’honorait, et chaque jour il allait l’adorer; mais Daniel adorait son Dieu. Et le roi lui dit: Pourquoi n’adores-tu point Bel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, '(4.) Et il répondit: Parce que je n’honore point des idoles, œuvres de la main des hommes, mais le Dieu vivant, créateur du ciel et de la terre, et maître de toute chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, '(5.) Et le roi reprit: Bel ne te semble donc pas un Dieu vivant? Ne vois-tu pas combien il mange et boit par jour?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, '(6.) Et Daniel dit en riant: O roi, ne t’y trompe point; ce dieu intérieurement est d’argile, extérieurement d’airain, et il ne mange quoi que ce soit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, '(7.) 21. Et le roi irrité appela ses prêtres, et il leur dit: Si vous ne me dites point qui mange ce que l’on dépense,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, '(8.) 22. Vous mourrez; mais si vous me faites voir que Bel mange ces offrandes, Daniel mourra, parce qu’il a blasphémé contre Bel. Et Daniel reprit: Qu’il soit fait comme tu as dit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, '(9.) 23. Or les prêtres de Bel étaient soixante-dix, sans compter les femmes et les enfants; et le roi alla avec Daniel au temple de Bel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, '(10.) 24. Et les prêtres de Bel dirent: Voilà que nous allons nous tenir dehors; cependant, ô roi, dépose les aliments et le vin préparé; puis ferme la porte, et scelle-la de ton anneau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, '(11.) 25. Et en revenant demain matin, si tu ne trouves pas que tout a été consommé par Bel, nous mourrons; sinon ce sera Daniel, pour avoir menti contre nous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, '(12.) 26. Ils tenaient ce langage sans rien craindre, parce qu’ils avaient pratiqué sous la table un passage secret, par où ils s’introduisaient toujours pour consommer les offrandes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, '(13.) 27. Et ceci advint: lorsqu’ils furent sortis et que le roi eut déposé les aliments devant Bel, Daniel donna ses ordres à ses serviteurs, et ils apportèrent de la cendre, et ils la répandirent dans tout le temple en présence du roi seul. Ensuite ils sortirent et ils fermèrent la porte, et ils la scellèrent avec l’anneau du roi et s’éloignèrent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, '(14.) 28. Et les prêtres vinrent pendant la nuit, comme d’habitude, avec leurs femmes et leurs enfants, et ils mangèrent tout et ils burent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, '(15.) 29. Et le roi se leva de grand matin, et Daniel avec lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, '(16.) 30. Et il dit: Les sceaux sont-ils intacts, Daniel? Et celui-ci reprit: Ils sont intacts, ô roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, '(17.) 31. Et ceci advint aussitôt qu’ils eurent ouvert la porte le roi regarda la table, et il jeta un grand cri, et il dit: Tu es grand, ô Bel, et il n’est point d’artifice en toi!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 19, '(18.) 32. Et Daniel vit, et il prit le roi par la main pour l’empêcher de sortir, et il lui dit: Vois donc le pavé, et reconnais de qui sont ces traces.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 20, '(19.) 33. Et le roi lui dit: Je vois des traces d’hommes, de femmes et d’enfants. Et le roi, transporté de colère,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 21, '(20.) 34. Soudain fit arrêter les prêtres avec leurs femmes et leurs enfants; et ils lui montrèrent la porte secrète par laquelle ils s’introduisaient pour consommer ce qui était sur la table.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 22, '(21.) 35. Et le roi les fit mourir, et il abandonna Bel à Daniel, et celui-ci abattit l’idole et le temple.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 23, '(22.) 36. Il y avait aussi un grand dragon, et les Babyloniens l’adoraient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 24, '(23.) 37. Et le roi dit à Daniel Diras-tu aussi de celui-ci que ce n’est que de l’airain? Il vit, il mange et il boit; tu ne peux dire qu’il n’est pas un Dieu vivant; adore-le donc.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 25, '(24.) 38. Et Daniel répondit: J’adorerai le Seigneur mon Dieu, parce que c’est lui qui est le Dieu vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 26, '(25.) 39. Cependant, ô roi, donne-moi la permission, et je tuerai le dragon sans glaive ni bâton. Et le roi reprit Je te le permets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 27, '(26.) 40. Et Daniel prit de la poix, de la graisse et des poils, et il fit cuire le tout à la fois, et il en fit des gâteaux qu’il mit dans la gueule du dragon, et en mangeant le dragon creva, et Daniel dit: Voilà ce que vous adoriez!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 28, '(27.) 41. Et ceci advint lorsque les Babyloniens eurent appris ce qu’il avait fait, ils en conçurent une violente colère, et ils se réunirent contre le roi, et ils dirent: Le roi est devenu juif; il a renversé Bel; il a fait mourir le dragon; il a égorgé les prêtres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 29, '(28.) 42. Et ils allèrent trouver le roi, et lui dirent: Livre-nous Daniel; sinon nous le tuerons, toi et ceux de ta maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 30, '(29.) 43. Et le roi vit qu’ils le pressaient avec violence, et par contrainte il leur livra Daniel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 31, '(30.) 44. Et ils le jetèrent dans la fosse aux lions, et il y demeura six jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 32, '(31.) 45. Or il y avait sept lions dans la fosse, et on leur donnait par jour deux corps et deux brebis; mais on ne les leur donna pas alors, pour qu’ils dévorassent Daniel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 33, '(32.) 46. Et il y avait en Judée le prophète Habacuc, et il s’était fait cuire une bouillie, et il avait rompu des pains dans une corbeille, et il allait aux champs les porter aux moissonneurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 34, '(33.) 47. Et l’ange du Seigneur dit à Habacuc: Porte le déjeuner que tu tiens en Babylone, pour Daniel qui est dans la fosse aux lions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 35, '(34.) 48. Et Habacuc répondit: Seigneur, je n’ai point vu Babylone, et je ne connais pas la fosse aux lions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 36, '(35.) 49. Et l’ange du Seigneur le prit par les cheveux, et il le porta ainsi, et il le déposa en Babylone, au-dessus de la fosse, aussi rapide que son souffle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 37, '(36.) 50. Et Habacuc cria: Daniel, Daniel, prends le déjeuner que t’envoie le Seigneur!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 38, '51. Et Daniel dit: Vous vous êtes souvenu de moi, ô Dieu, vous n’avez point abandonné ceux qui vous aiment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 39, '(37-38.) 52. Et Daniel, s’étant levé, mangea; et soudain l’ange de Dieu remit Habacuc où il l’avait pris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 40, '(39.) 53. Et le roi vint le septième jour pour pleurer sur Daniel, et il vint près de la citerne; il regarda, et voilà que Daniel était assis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 41, '(40.) 54. Et le roi s’écria: Vous êtes grand, Seigneur Dieu de Daniel, et il n’est point d’autre Dieu que vous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 42, '(41.) 55. Et il retira Daniel; mais il fit jeter dans la fosse ceux qui l’avaient voulu perdre, et ils furent dévorés en un instant sous ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Voici les paroles d’Énoch par lesquelles il bénit les élus et les justes qui vivront au temps de l’affliction, quand seront réprouvés tous les méchants et les impies. Énoch, homme juste qui marchait devant le Seigneur, quand ses yeux furent ouverts, et qu’il eut contemplé une sainte vision dans les cieux, parla, et il prononça: Voici ce que me montrèrent les anges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Ces anges me révélèrent toutes choses et me donnèrent l’intelligence de ce que j’avais vu, qui ne devait point avoir lieu dans cette génération, mais dans une génération éloignée, pour le bien des élus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'C’est par eux que je pus parler et converser avec celui qui doit quitter un jour sa céleste demeure, le saint et le Tout-Puissant, le Seigneur de ce monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Qui doit fouler un jour le sommet du mont Sinaï, apparaître dans son tabernacle, et se manifester dans toute la force de sa céleste puissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Tous les vigilants seront effrayés, tous seront consternés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Tous seront saisis de crainte et d’effroi, même aux extrémités de la terre. Les hautes montagnes seront ébranlées; les collines élevées seront déprimées; elles s’écouleront devant sa face comme la cire devant la flamme. La terre sera submergée, et tout ce qui l’habite périra; or tous les êtres seront jugés, tous, même les justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Mais les justes obtiendront la paix; il conservera les élus, et exercera sur eux sa clémence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Alors ils deviendront la propriété de Dieu; il les comblera de bonheur et de bénédictions; et la splendeur de la Divinité les illuminera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Voici! Il arrive avec dix mille de ses saints, pour juger toutes les créatures pour détruire la race des méchants, et réprouver toute chair à cause des crimes que le pécheur et l’impie ont commis contre lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Tous ceux qui habitent dans les cieux savent ce qui se passe là-bas. Ils savent que les globes célestes qui nous illuminent ne changent point leur voie; que chacun d’eux se lève et se couche régulièrement, dans le temps qui lui est propre, sans jamais transgresser les ordres qu’il a reçus. Ils regardent la terre, et soudain ils connaissent tout ce qui s’y passe depuis le commencement jusqu’à la fin. Ils voient que chacune des créations de Dieu suit invariablement la voie qui lui est tracée. Ils voient l’été et l’hiver; ils voient que toute la terre est remplie d’eau, et que les nuages, les vapeurs et la pluie en rafraîchissent la température.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 1, 'Ils considèrent et admirent comme chaque arbre se couronne de feuilles; comment il les perd ensuite, à l’exception de quatorze arbres privilégiés qui reste toujours verts, et qui pendant plusieurs hivers présentent l’apparence du printemps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 1, 'Ils admirent ensuite dans les jours de l’été comment le soleil échauffe la terre, dès le commencement de sa carrière, tandis que vous cherchez la fraîcheur du feuillage; tandis que le sol est crevassé par la chaleur torride, et que vous êtes incapable de vous promener soit dans la plaine, soit sur la montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 2, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 1, 'Ils admirent ensuite comment les arbres en se couvrant de feuilles poussent en même temps des fruits; mais aussi ils comprennent en même temps et reconnaissent que celui qui vit éternellement fait pour nous toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 2, 'Que toutes les œuvres de chaque année, que toutes ses créations suivent invariablement les ordres qu’il leur a donnés; toutefois, quand Dieu a résolu ainsi, toutes choses doivent s’évanouir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 3, 'Ils voient comment les mers et les fleuves accomplissent chacun leur mission respective.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 4, 'Tandis que vous, vous ne supportez qu’avec peine, vous ne remplissez qu’imparfaitement les commandements de votre Seigneur; vous transgressez ses ordres, vous calomniez sa grandeur; et votre bouche impie va prononcer des blasphèmes contre sa majesté!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 5, 'Pécheurs au cœur endurci, il n’y aura point de paix pour vous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 6, 'Vos jours seront maudits, et les années de votre vie seront effacées du livre des vivants; vous serez en exécration à toutes les créatures, et vous n’obtiendrez point de miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 7, 'Dans ce jour, votre paix sera troublée par l’éternelle malédiction de tous les justes; et les pécheurs mêmes exécreront à tout jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 8, 'Oui, ils vous exécreront aussi bien que les impies. Mais pour les élus, à eux la lumière, la joie, la paix; à eux l’héritage terrestre. Pour vous, impies, pour vous malédiction. Alors les élus recevront la sagesse, et il n’y aura plus ni transgression, ni impiété, ni orgueil; mais ils se conduiront avec prudence, s’humilieront eux-mêmes, et ne violeront plus les saints commandements. Aussi ne seront-ils pas condamnés tout le temps de leur vie, et leur mort sera sans trouble et sans douleur; la somme de leurs jours sera complète; ils vieilliront dans la joie et la paix; et leurs années de bonheur se multiplieront avec la joie, avec la paix, sans nuage, sans trouble, tout le temps de leur existence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 1, 'Quand les enfants des hommes se furent multipliés multipliés dans ces jours, il arriva que des filles leur naquirent élégantes et belles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 2, 'Et lorsque les anges, les enfants des cieux, les eurent vues, ils en devinrent amoureux; et ils se dirent les uns aux autres choisissons-nous des femmes de la race des hommes, et ayons des enfants avec elles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 3, 'Alors Samyaza leur chef leur dit: Je crains bien que vous ne puissiez accomplir votre dessein.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 4, 'Et que je supporte seul la peine de votre crime.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 5, 'Mais ils lui répondirent: nous vous le jurons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 6, 'Et nous nous lions tous par de mutuelles exécrations; nous ne changerons rien à notre dessein, nous exécuterons ce que nous avons résolu. En effet ils jurèrent et se lièrent entre eux par de mutuelles exécrations. Ils étaient au nombre de deux cents, qui descendirent sur Aradis, lieu situé près le mont Armon. Cette montagne avait été appelée Armon, parce que c’est là qu’ils avaient juré et s’étaient liés par de mutuelles exécrations. Voici le nom de leurs chefs: Samyaza, leur chef, Urakabarameel, Akibeel, Tainiel, Ramuel, Danel, Azkeel, Sarakmyal, Asael, Armers, Batraal, Anane, Zavebe, Samsaveel, Ertael, Turel, Yomyael, Arazeal. Tels furent les chefs de ces deux cents anges; et le reste étaient tous avec eux. Et ils se choisirent chacun une femme, et ils s’en approchèrent, et ils cohabitèrent avec elles; et ils leur enseignèrent la sorcellerie, les enchantements, et les propriétés des racines et des arbres. Et ces femmes conçurent et elles enfantèrent des géants. Dont la taille avait trois cents coudées. Ils dévoraient tout ce que le travail des hommes pouvait produire, et il devint impossible de les nourrir. Alors ils se tournèrent contre les hommes eux-mêmes, afin de les dévorer. Et ils commencèrent à se jeter sur les oiseaux, les bêtes, les reptiles et les poissons, pour se rassasier de leur chair et se désaltérer de leur sang. Et alors la terre réprouva les méchants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 1, 'Azazyel enseigna encore aux hommes à faire des épées, des couteaux, des boucliers, des cuirasses et des miroirs; il leur apprit la fabrication des bracelets et des ornements, l’usage de la peinture, l’art de se peindre les sourcils, d’employer les pierres précieuses, et toute espèce de teintures, de sorte que le monde fut corrompu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 2, 'L’impiété s’accrut; la fornication se multiplia, les créatures transgressèrent et corrompirent toutes leurs voies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 3, 'Amazarak enseigna tous les sortilèges tous les enchantements et les propriétés de racines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 4, 'Armers enseigna l’art de résoudre les sortilèges. Barkayal enseigna l’art d’observer les étoiles. Akibeel enseigna les signes. Tamiel enseigna l’astronomie. Et Asaradel enseigna les mouvements de la lune. Et les hommes sur le point de périr élevèrent leurs voix, et leurs voix montèrent jusqu’au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 1, 'Alors Michael et Gabriel, Raphael, Suryal et Uriel, abaissèrent des cieux leurs regards sur la terre, et virent les flots de sang qui la rougissaient, et les iniquités qui s’y commettaient; et ils se dirent les uns aux autres: C’est le bruit de leurs cris.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 2, 'La terre privée de ses enfants a élevé sa voix jusqu’aux portes du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 3, 'Et c’est à vous, ô essences célestes c’est à vous que les âmes adressent leurs plaintes en disant: Obtenez-nous justice du Très-Haut. Alors ils dirent à leur Seigneur et maître: Tu es le Seigneur des seigneurs, le Dieu des dieux, le Roi des rois. Le trône de ta gloire s’élève de toute éternité, et de toute éternité ton nom est sanctifié et glorifié. Tu es béni, et glorifié à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 4, 'Tu es le créateur, le maître souverain de toutes choses; rien n’est caché à ton regard perçant. Tu domines sur tout, et rien ne peut se soustraire à ton autorité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 5, 'Tu as vu ce que Azaryel a fait; comment il a enseigné aux hommes toute espèce d’iniquités, et comment il a révélé au monde tout ce qui se passe dans les cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 6, 'Samyaza aussi a enseigné aux hommes la sorcellerie, lui que tu avais placé au-dessus de tous ses compagnons. Ils se sont alliés aux filles des hommes; ils ont péché avec elles, et se sont souillés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 7, 'Ils leur ont découvert les crimes les plus abominables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 8, 'Et les femmes ont enfanté les géants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 9, 'Et toute la terre a été remplie de sang et d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 10, 'Et voici maintenant que les âmes de ceux qui sont morts, élèvent la voix vers toi');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 11, 'Et font monter leurs plaintes jusqu’aux portes du ciel. Leurs gémissements montent vers toi; les hommes ne peuvent se soustraire à l’iniquité qui couvre la face de la terre. Or tu connais toutes choses, avant même qu’elles existent. Tu connais toutes choses; tu sais tout ce qui se passe, et cependant tu ne nous dis rien. Pour tant de crimes, que devons-nous faire aux méchants?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 1, 'Alors le Très-Haut, le grand et le saint fit entendre sa voix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 2, 'Et il envoya Arsayalalyur, au fils de Lamech.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 3, 'Disant parle-lui en mon nom; mais cache-toi à ses yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 4, 'Puis dévoile-lui le grand cataclysme qui doit faire périr tous les hommes; car les eaux du déluge se répandront sur la face de la terre, et toute créature sera détruite.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 5, 'Mais enseigne-lui les moyens d’échapper; dis-lui comment sa race se perpétuera sur toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 6, 'Puis le Seigneur dit à Raphal Prends Azaziel, lie-lui les pieds et les mains; jette-le dans les ténèbres; et abandonne-le dans le désert de Dudael.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 7, 'Fais pleuvoir sur lui des pierres lourdes et pointues; enveloppe-le de ténèbres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 8, 'Qu’il y reste à jamais, que sa face soit couverte d’un voile épais; et qu’il ne voie jamais la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 9, 'Et quand se lèvera le jour du jugement, plonge-le dans le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 10, 'Cependant purifie la terre, que les anges ont souillée; annonce-lui la vie; annonce-lui que je la revivifierai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 11, 'Les fils des hommes ne périront pas tous à cause des secrets que les vigilants leur ont révélés et qu’ils ont enseignés à leurs descendants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 12, 'Mais la terre a été souillée par les enseignements impurs d’Azaziel. Aussi est-ce lui qui doit être responsable de tous les crimes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 13, 'Le Seigneur dit ensuite à Gabriel: Va vers les méchants, vers les réprouvés, vers les enfants de fornication; extermine ces enfants de fornication, ces rejetons des vigilants, du milieu des hommes; pousse-les, excite-les les uns contre les autres. Qu’ils périssent de leurs propres mains; car leurs jours ne seront pas complets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 14, 'Ils te suppliront, mais leurs prières n’obtiendront rien pour eux; et c’est en vain qu’ils espéreront pour leurs enfants la vie éternelle, et une même vie de cinq cents années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 15, 'Le Seigneur dit ensuite à Michael: Va et annonce le châtiment qui attend Samyaza et tous ceux qui ont participé à ces crimes, qui se sont unis à des femmes, qui se sont souillés par toutes sortes d’impureté. Et quand leurs fils seront exterminés, quand ils auront vu la ruine de ce qu’ils ont de plus cher au monde, enchaîne-les sous la terre, pour soixante-dix générations, jusqu’au jour du jugement, et de la consommation universelle; et l’effet de ce jugement sera pour eux éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 16, 'Alors ils seront jetés dans les profondeurs d’un feu qui les tourmentera sans cesse; et ils y resteront toute l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 17, 'Avec eux leur chef brûlera dans les flammes; et tous ils y seront enchaînés jusqu’à la consommation d’un grand nombre de générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 18, 'Extermine en même temps toutes les âmes adonnées à de coupables jeux; extermine les rejetons des vigilants; assez et trop longtemps ils ont tyrannisé le genre humain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 19, 'Que les oppresseurs soient enlevés de la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 20, 'Que le mal soit anéanti!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 21, 'Mais que la plante de la justice et de l’équité refleurisse, et devienne un gage de bénédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 22, 'Car la justice et l’équité doit refleurir avec la joie pour des temps sans fin. Et alors tous les saints adresseront au ciel leurs actions de grâces, et vivront jusqu’à ce qu’ils aient engendré mille enfants, tandis que les jours de leur jeunesse et leurs sabbats s’écouleront dans la joie et la paix. À cette époque toute la terre sera cultivée dans la justice: elle se remplira d’arbres et de bénédictions; des arbres délicieux y seront plantés. La vigne y croîtra en abondance, et produira du fruit à satiété; toutes les semences qui seront confiées à la terre, rapporteront mille mesures pour une; et une mesure d’olive, fournira à dix pressées d’huile. Délivre la terre de toute tyrannie, de toute injustice, de tout crime, de toute impiété, de tout ce qui peut la souiller. Que le mal en soit banni à jamais. Alors, les enfants des hommes vivront dans la justice, et toutes les nations me rendront les honneurs qui me sont dus; toutes me béniront, toutes m’adoreront. La terre sera délivrée de toute corruption, de tout crime, de tout châtiment, de toute souffrance; et elle n’aura plus à craindre de moi un déluge exterminateur. Dans ces jours, j’ouvrirai les trésors de bénédictions que recèle le ciel, je les répandrai sur la terre, et ils féconderont les œuvres et le travail des hommes. La paix et la justice feront alliance avec les hommes, et ces unions sacrées dureront autant que le monde et que les générations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 1, 'Manque dans les manuscrits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 2, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 1, 'Avant l’accomplissement de toutes ces choses, Enoch fut enlevé de la terre; et personne ne sut où il avait été enlevé, ni ce qu’il était devenu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 2, 'Tous ses jours, il les passa avec les saints, et avec les vigilants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 3, 'Moi, Enoch, je bénissais le grand Seigneur, le roi de la paix.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 4, 'Et voici: les vigilants me nommèrent Enoch le scribe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 5, 'Et le Seigneur me dit: Enoch, scribe de justice, va dire aux vigilants du ciel, qui ont abandonné les hauteurs sublimes des cieux et leurs éternelles demeures, qui se sont souillés avec les femmes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 6, 'Et ont pratiqué les œuvres des hommes, en prenant des femmes à leur exemple, qui se sont enfin corrompus sur la terre. Dis-leur que sur la terre, ils n’obtiendront jamais ni paix, ni rémission de leurs péchés. Jamais ils ne se réjouiront dans leurs rejetons; ils verront leurs bien-aimés exterminés; ils pleureront leurs fils exterminés; ils me prieront pour eux, mais jamais ils n’obtiendront paix ou miséricorde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 1, 'Enoch partit donc, et il dit à Azaziel: Il n’y a plus de paix pour toi, Une grande sentence a été prononcée contre toi. Il t’enchaînera;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 2, 'Il n’y aura jamais pour toi ni soulagement ni miséricorde, ni intercession, à cause de l’oppression que tu as enseignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 3, 'Et parce que tu as appris aux hommes à outrager Dieu, à pécher et à tyranniser leurs semblables.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 4, 'Et je le quittai, et j’allai annoncer la même nouvelle à tous les compagnons de ses crimes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 5, 'Et ils furent terrifiés et saisis d’un affreux tremblement;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 6, 'Et ils me supplièrent d’écrire pour eux une humble supplique pour obtenir le pardon de leurs fautes; ils me prièrent de la faire parvenir au trône du Dieu du ciel, car ils n’osaient ni s’adresser à lui, ni même lever les yeux au ciel, à cause du grand crime pour lequel ils avaient été jugés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 7, 'Alors, j’écrivis une humble supplique à leur sujet, afin de leur faire obtenir repos et miséricorde pour tout ce qu’ils avaient fait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 8, 'Puis je les quittai, et continuai ma route, tout en lisant leur requête, vers les eaux du Danendan, qui se trouvent à l’ouest d’Armon, et je m’endormis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 9, 'Et voici que j’eus un songe, et une céleste vision. Je tombai en extase, et je vis dans une vision, la punition dont je devais annoncer la triste nouvelle aux enfants des cieux, et les réprimander. Quand je m’éveillai, je me rendis auprès d’eux. Ils étaient réunis, pleurant et la face voilée dans Ubelseiael, lieu situé entre le Liban et Seneser.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 10, 'Je leur fis part de mes visions et de mes songes. Et je leur adressai ces paroles de la justice, et les réprimandes que méritaient les enfants des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 1, 'Ceci est le livre des paroles de la justice, et des paroles adressées aux vigilants, qui sont de ce monde, selon l’ordre que m’a donné dans la vision le Saint et le Grand. Je vis donc en songe que je parlais avec ma langue de chair et avec le même souffle dont le Tout-Puissant a animé la bouche des hommes, pour converser entre eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 2, 'Et je compris avec le cœur. Et de même que le Seigneur a créé et donné aux hommes le pouvoir de comprendre les mots qui s’adressent à l’intelligence, de même aussi, il a créé pour nous, et il m’a donné le pouvoir de reprendre les vigilants, les enfants du ciel. J’ai donc rédigé vos prières; mais j’ai vu dans une vision, que tant que le monde existera, jamais vous n’obtiendriez ce que vous demandez.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 3, 'Le jugement a été prononcé contre vous; toutes vos prières sont inutiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 4, 'Ainsi, désormais, vous ne monterez plus au ciel; et sur la terre, vous serez enchaînés aussi longtemps qu’existera le monde lui-même.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 5, 'Mais auparavant, vous serez témoins de la misère de tout ce qui vous est cher; vous ne les posséderez plus. Ils tomberont par le glaive sous vos propres yeux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 6, 'Et n’adressez point de prières ni pour eux ni pour vous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 7, 'Mais vous pleurerez, et vous supplierez en silence. Telles sont les paroles du livre que j’écrivis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 8, 'Voici maintenant la vision que j’eus:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 9, 'Voici: Je me voyais environné de nuages et de brouillards épais; je contemplais avec inquiétude le mouvement des astres et celui des éclairs, tandis que des vents favorables soulevaient mes ailes, et accéléraient ma course.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 10, 'Je fus enlevé ainsi jusqu’au ciel, et j’arrivai bientôt à son mur bâti avec des pierres de cristal. Des flammes mobiles en enveloppaient les contours. Je commençai à être saisi d’effroi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 11, 'Cependant, je m’enfonçai au milieu de ces flammes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 12, 'Et je pénétrai dans une vaste habitation dont le pavé était en pierres de cristal. Les murs comme le pavé, étaient également en cristal, aussi bien que les fondements. Son toit était formé d’étoiles errantes et d’éclairs de lumière, et l’on voyait, au milieu, des chérubins de feu dans un ciel orageux. Des flammes vibraient autour de ces murailles, et la porte était de feu. Quand je fus entré dans cette habitation, elle était à la fois brûlante comme le feu, et froide comme la glace; et il n’y avait là, trace ni de bonheur, ni de vie. Alors, une terreur soudaine s’empara de moi; je tressaillis d’effroi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 13, 'Tout tremblant, je tombai la face contre terre, et j’eus une vision.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 14, 'Voici Il y avait une autre habitation plus spacieuse que la première, dont toutes les portes étaient ouvertes devant moi, au milieu d’une flamme vibrante.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 15, 'Telle était sa gloire, sa magnificence, sa grandeur, qu’il m’est impossible de vous dépeindre, ni la splendeur qui l’environne, ni sa vaste étendue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 16, 'Le pavé en était de feu; au-dessus, brillaient des éclairs et des étoiles errantes, et le comble était tout entier d’un feu étincelant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 17, 'Je l’examinai avec attention, et je vis qu’il y avait un trône élevé;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 18, 'Dont l’aspect ressemblait à la grêle, tandis que son contour était comme l’orbe éclatant du soleil; et il en sortait des voix de chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 19, 'De ce trône puissant, s’échappaient des torrents de flammes,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 20, 'Qu’il était impossible d’envisager.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 21, 'Et il y avait quelqu’un assis sur ce trône de gloire,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 22, 'Dont le vêtement était plus brillant que le soleil et plus blanc que la neige.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 23, 'Et aucun ange n’était capable de regarder en face le Glorieux et le Magnifique, ni de s’approcher de lui; aucun œil mortel ne pouvait le contempler. Un feu brillant brûlait autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 24, 'Il s’élevait aussi devant lui, un feu d’une grande étendue; en sorte qu’aucun de ceux qui l’entouraient ne pouvaient en approcher, et des myriades de myriades étaient devant lui. Il n’avait besoin ni de conseils, ni d’assistance, et les saints qui formaient sa cour, ne le quittaient ni jour ni nuit. Je m’approchai autant que je pus, voilant ma face, et plein de frayeur. Alors, le Seigneur lui-même daigna de sa propre bouche, m’appeler par mon nom: Approche, dit-il, approche de plus près, et viens entendre ma sainte parole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 25, 'Et il me prit, et il me fit pencher jusqu’à la porte. Et moi, je tenais mes yeux baissés vers la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 1, 'Alors s’adressant à moi, il me parla ainsi: Écoute, écoute sans crainte, ô juste Enoch, ô scribe de justice, approche, et écoute ma voix. Va, dis aux vigilants du ciel qui t’ont envoyé pour me prier pour eux: Vous deviez prier pour les hommes, et non pas les hommes pour vous!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 2, 'Pourquoi avez-vous abandonné les saintes hauteurs du ciel, votre demeure éternelle, pour aller vous souiller avec des femmes? Pourquoi vous êtes-vous épris des filles des hommes; en avez-vous fait vos épouses; avez-vous pratiqué avec elles les œuvres des enfants de la terre, et donné naissance à une race impie?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 3, 'Vous qui étiez des esprits célestes, en possession de la sainteté, de la vie éternelle, vous vous êtes souillés avec des femmes; vous avez travaillé aux œuvres de la chair, vous avez engendré dans le sang, vous avez agi comme ceux qui ne sont que de sang et de chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 4, 'Eux, ils ont été créés pour mourir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 5, 'Voilà pourquoi je leur ai donné des femmes, afin qu’ils puissent cohabiter avec elles, engendrer des enfants qui perpétuent leur race sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 6, 'Mais vous, vous avez été créé de purs esprits dès le commencement, vous possédez une vie éternelle, vous n’êtes point sujets à la mort.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 7, 'Aussi ne vous avais-je point donné de femmes, parce que, esprits purs, vous deviez habiter dans le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 8, 'Et maintenant les géants, qui sont le prix du commerce de l’esprit et de la chair, seront appelés sur la terre de mauvais esprits, et leur demeure sera sur la terre. Ils procréeront à leur tour de mauvais esprits, parce qu’ils tiennent au ciel par un côté de leur être, parce que c’est des saints vigilants qu’ils tirent leur origine. Ils seront donc de mauvais esprits sur la terre, et on les appellera esprits du mal. La demeure des esprits célestes est le ciel; mais c’est la terre qui doit être la demeure des esprits terrestres qui sont nés sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 9, 'Les esprits des géants seront comme les nuages, qui apportent sur la terre les fléaux de toute espèce, la peste, la guerre, la famine');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 10, 'Et le deuil. Ils ne boiront ni ne mangeront, invisibles à tous les regards, ils s’insurgeront encore entre les hommes et les femmes; parce qu’ils ont reçu la vie dans les jours de destruction et de carnage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 1, 'Lors de la mort des géants, quelque part qu’aillent leurs âmes lorsqu’elles abandonneront leurs corps, tâche que ce qui est chair en eux, périsse avant le jugement. Qu’elle soit exterminée jusqu’au jour de la grande consommation de l’univers; alors que les vigilants et les impies seront détruits pour toujours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 2, 'Quant aux vigilants, qui t’ont envoyé pour m’implorer pour eux,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 3, 'Dis-leur, à ces intelligences célestes: Vous avez eu le ciel pour demeure; mais les secrets d’en haut ne vous ont pas été révélés; cependant vous avez connu un secret d’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 4, 'Et vous l’avez dévoilé aux femmes dans les mouvements de votre cœur, et par là vous avez multiplié le mal sur la surface de la terre. Dis-leur donc: Jamais vous n’obtiendrez grâce, ni jamais vous ne recevrez la paix!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 1, 'Puis ils m’enlevèrent dans un endroit où il y avait comme un feu dévorant; et où, selon leur bon plaisir, ils prenaient la ressemblance de l’homme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 2, 'Ils me conduisirent sur un lieu élevé, sur une montagne dont le sommet s’élançait dans les cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 3, 'Et je vis les trésors des éclairs et du tonnerre aux extrémités de ce lieu, dans l’endroit le plus profond. Il y avait là un arc de feu, et des flèches dans un carquois, et une épée de feu et toute espèce d’éclairs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 4, 'Puis ils me transportèrent auprès d’une eau jaillissante, et du côté de l’occident, vers les feux du soleil couchant. J’arrivai à une rivière de feu qui coulait comme de l’eau et se jetait dans la grande mer occidentale.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 5, 'Je vis tous les grands fleuves, et j’arrivai bientôt au milieu des noires ténèbres; dans ces lieux où toute chair émigre; je vis les montagnes de ténèbres qui produisent l’hiver, et l’endroit d’où l’eau s’écoule dans leurs abîmes respectifs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 6, 'Je vis aussi l’embouchure de tous les fleuves du monde, et celle de l’abîme.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 1, 'Puis j’arrivai aux réservoirs de tous les vents, et je remarquai comment ils servaient à l’ornement de la terre, et à la conservation des fondements de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 2, 'Je vis la pierre qui supporte les angles de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 3, 'Je vis aussi les quatre vents qui soutiennent la terre et le firmament du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 4, 'Je vis les vents qui soufflent dans les hauteurs du ciel;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 5, 'Ceux qui s’élèvent entre le ciel et la terre, et qui forment les colonnes du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 6, 'Je vis les vents qui font tourner le ciel et qui entraînent dans leurs orbites le soleil et les étoiles; et, au-dessus de la terre, je vis le vent qui supporte les nuages.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 7, 'Je vis la voie des anges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 8, 'Je vis, de l’extrémité de la terre, le firmament du ciel qui pèse sur elle. Alors je me tournai vers le midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 9, 'Là brûlaient nuit et jour six montagnes de pierres précieuses, trois du côté de l’orient, trois du côté du midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 10, 'Celles du côté de l’orient se composaient de pierres de diverses couleurs; de perles et d’antimoine; celles du côté du midi étaient de pierres rouges. Leur sommet s’élevait jusqu’au ciel, comme le trône de Dieu; il était d’albâtre, et, dans sa partie supérieure, de saphir. Je vis aussi le feu ardent qui brûlait sur les montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 11, 'Là aussi je vis dans une région immense le lieu où les eaux étaient rassemblées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 12, 'J’y vis aussi les sources de la terre, cachées dans les colonnes embrasées des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 13, 'Et dans ces colonnes du ciel je vis des feux qui jaillissaient sans nombre, mais ni en haut ni en bas. Au-dessus de ces sources, je vis un endroit qui n’avait ni le firmament au-dessus, ni la terre au-dessous; il n’y avait pas non plus d’eau; et rien à droite ni à gauche; c’était une plage déserte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 14, 'Et là j’aperçus sept étoiles, brillantes comme des montagnes de feu, ou comme de sublimes esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 15, 'Alors l’ange dit: cet endroit sera jusqu’à la consommation du ciel et de la terre la prison des étoiles et des armées du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 16, 'Ces étoiles qui roulent au-dessus du feu sont celles qui ont transgressé les commandements de Dieu, avant la fin de leur épreuve. Aussi les a-t-il enchaînées dans ce lieu, jusqu’à ce qu’elles aient expié leur crime dans l’année mystérieuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 1, 'Alors Uriel s’écria: Voici les anges qui ont cohabité avec les femmes, et se sont désignés des chefs;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 2, 'Qui ont souillé les hommes, multiplié parmi eux les erreurs, au point de leur faire faire des sacrifices aux démons, comme à des dieux. Mais au grand jour, ils seront jugés et ils périront, et leurs femmes avec eux, parce qu’elles se sont laissé séduire sans résistance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 3, 'Et moi, Enoch, moi seul, j’ai vu la fin de toutes choses, et il n’a été donné à personne de la voir comme moi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 1, 'Voici le nom des anges qui veillent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 2, 'Uriel, un des saints anges, qui préside aux cris et à la terreur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 3, 'Raphaël, un des saints anges, qui préside aux esprits des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 4, 'Raguel, un des saints anges, qui punit le monde et les luminaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 5, 'Michael, un des saints anges qui préside à la vertu des hommes, et commande aux nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 6, 'Sarakiel, un des saints anges qui préside aux enfants des hommes qui pèchent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 7, 'Gabriel, un des saints anges, qui préside sur Ikisat, sur le paradis et sur les chérubins.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 1, 'Je fis ensuite un long circuit pour arriver à un lieu où rien n’était au complet.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 2, 'Je ne vis là ni l’œuvre admirable du ciel élevé, ni la terre et ses merveilles; ce n’était qu’un désert solitaire et terrible.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 3, 'Là aussi je vis sept étoiles enchaînées les unes aux autres, comme de grandes montagnes, comme des feux embrasés. Et je m’écriai à cette vue: Pour quel crime ces étoiles sont-elles enchaînées; pourquoi ont-elles été reléguées dans ce lieu? Alors Uriel, un des saints anges qui était avec moi et qui me servait de guide, me répondit: Enoch, pourquoi cette question? pourquoi cette inquiétude, cette anxiété? Ces étoiles ont transgressé le commandement du Dieu Très-Haut; et pour expier leur crime, elles ont été enchaînées dans ce lieu pour un nombre infini de siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 4, 'De là je passai dans un autre lieu de terreur:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 5, 'Là je vis l’œuvre d’un feu immense, ardent et dévorant, au milieu duquel il y avait une division. Et des colonnes de feu se combattaient entre elles et elles s’enfonçaient dans l’abîme. Et il me fut impossible d’évaluer ni sa grandeur, ni sa hauteur; je ne pus pas non plus connaître son origine. Et je m’écriai encore à cette vue: Quel lieu terrible! qu’il est difficile d’en sonder les mystères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 6, 'Uriel, un des anges qui étaient avec moi, me répondit et me dit: Enoch, pourquoi ces alarmes, pourquoi cet étonnement la vue de ce lieu terrible, à la vue de ce lieu de souffrance? C’est ici, ajouta-t-il, la prison des anges; et ils y seront renfermés à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 1, 'De là, je m’avançai vers un autre lieu, où du côté de l’occident je vis une grande et haute montagne, un rocher escarpé, et quatre réceptacles délicieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 2, 'À l’intérieur, ce lieu était profond, spacieux, poli et égal, mais d’une profonde obscurité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 3, 'Alors Raphaël, un des saints anges, qui m’accompagnait, me dit: Voici les bienheureuses régions où sont rassemblés les esprits, les âmes des morts; c’est là que doivent se réunir toutes les âmes des enfants des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 4, 'C’est dans ces lieux qu’elles resteront jusqu’au jour du jugement, jusqu’au temps qui leur est marqué.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 5, 'Or, ce temps sera long à venir, c’est le jour du grand jugement. Et je vis les esprits des enfants des hommes qui étaient morts, et leurs cris accusateurs s’élevaient jusqu’au ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 6, 'Alors j’interrogeai Raphaël, l’ange qui m’accompagnait, et je lui dis: De qui est cette voix accusatrice qui monte vers le ciel?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 7, 'Il me répondit: C’est la voix de l’esprit d’Abel, qui a été tué par son frère Caïn, et qui l’accusera jusqu’à ce que sa race soit exterminée de dessus la face de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 8, 'Jusqu’à ce que sa race soit effacée d’au milieu des hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 9, 'Alors je l’interrogeai sur lui, sur le jugement universel, et je lui dis: Pourquoi les uns sont-ils séparés des autres? Il me répondit: Il y a trois classes distinctes pour les esprits des morts; trois classes parmi les esprits des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 10, 'Ces classes sont distinguées par un gouffre, par l’eau et par la lumière qui est sur l’eau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 11, 'Les pécheurs sont également classés; après leur mort, ils sont déposés dans la terre, si le jugement ne les a pas prévenus de leur vivant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 12, 'C’est ici que leurs âmes sont enfermées; c’est ici qu’elles sont en proie à des douleurs intolérables, châtiment de ceux qui sont maudits pour l’éternité, et dont les âmes seront punies et enchaînées à tout jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 13, 'Et voilà ce qui existe depuis le commencement du monde. Les âmes de ceux qui se plaignent sont séparées de celles qui veillent pour leur ruine, pour leur extermination au jour des péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 14, 'Tel est le séjour destiné aux âmes des hommes injustes et pécheurs, aux âmes de ceux qui ont commis l’iniquité et qui se sont mêlés à la société des impies, auxquels ils ressemblent. Leurs âmes ne seront point anéanties au jour du jugement; mais enfermées dans ce lieu, elles n’en sortiront jamais. Et je dis: Béni soit mon Seigneur, le Seigneur de gloire et de justice, le dominateur suprême et éternel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 1, 'De là j’arrivai dans un autre lieu, du côté de l’occident, aux extrémités de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 2, 'Où je vis un feu ardent et un mouvement perpétuel, qui roulait nuit et jour, sans jamais s’arrêter.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 3, 'Et j’interrogeai l’ange qui m’accompagnait, et je lui dis: Qu’est cela? Pourquoi ce mouvement incessant?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 4, 'Alors Raguel, un des anges qui m’accompagnaient, me répondit: Ce feu ardent, qui se meut sans cesse vers l’occident, est le feu qui embrase tous les luminaires du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 1, 'De là je parvins dans un autre lieu, et je vis une montagne de feu brûlant nuit et jour. Dès que j’en fus rapproché, j’aperçus sept brillantes montagnes, dont l’une était distincte de l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 2, 'Les pierres dont elles étaient formées étaient belles et étincelantes; elles brillent et rayonnent à la vue, et leur surface est polie. Il y en avait trois à l’orient, et d’autant plus inébranlables, qu’elles étaient l’une sur l’autre; et il y en avait trois au midi, également inébranlables. Il y avait aussi de profondes vallées, mais qui étaient séparées les unes des autres. Au milieu s’élevait la septième montagne. Et toutes ces montagnes apparaissaient au loin comme des trônes majestueux, et elles étaient couronnées d’arbres odoriférants.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 3, 'Parmi ces arbres, il y en avait un d’une odeur sans cesse renaissante, et tellement suave, qu’il n’y en avait pas un dans le jardin d’Éden qui exhalât un parfum aussi délicieux. Ses feuilles, ses fleurs, son bois, ne se flétrissaient jamais, et ses fruits étaient beaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 4, 'Ses fruits ressemblaient aux fruits du palmier. À cette vue, je m’écriai: Voilà un arbre admirable à voir; quelles belles feuilles, quels fruits délicieux! Alors Michaël, un des saints et glorieux anges qui m’accompagnait, et qui était à leur tête, me répondit:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 5, 'Énoch, pourquoi ces questions au sujet de l’odeur de cet arbre?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 6, 'Pourquoi es-tu avide de le connaître? Alors moi, Énoch, je lui répondis: Je voudrais tout savoir, mais surtout ce qui regarde cet arbre. L’ange me répondit: Cette montagne que tu vois, et dont la tête élevée égale en hauteur le trône du Seigneur, sera le siège où se reposera le Seigneur de sainteté et de gloire, le Roi éternel, quand il viendra et descendra pour visiter la terre dans sa bonté. Quant à cet arbre à la suave odeur, dont le parfum n’a rien de charnel, personne n’y portera la main, jusqu’au jour du jugement. Quand les méchants auront été livrés aux tourments éternels, cet arbre sera donné aux justes et aux humbles. Ses fruits seront réservés aux élus. Car la vie sera plantée dans le saint lieu, du côté du septentrion, vers la demeure du Roi éternel. Alors ils se réjouiront et tressailleront d’allégresse, dans le Saint des saints; une odeur délicieuse pénétrera leurs os, et ils couleront, comme tes ancêtres, une vie longue sur la terre; et cette vie ne sera troublée ni par les malheurs, ni par les peines, ni par les misères. Et je louai le Seigneur de gloire, le Roi éternel, de ce qu’il avait préparé cet arbre et avait daigné le promettre aux saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 25, 1, 'De là je me dirigeai vers le centre de la terre, et j’aperçus un lieu fortuné et fertile, où des arbres poussaient sans cesse des rameaux toujours verts. Là je vis encore une montagne sacrée, et au-dessous, sur le flanc oriental, une eau qui coulait vers le midi. J’aperçus encore vers l’orient une autre montagne, également élevée, placée au milieu de vallées profondes, mais étroites');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 25, 2, 'L’eau s’écoulait vers la montagne, du côté de sa partie occidentale; au-dessous s’élevait une autre montagne.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 25, 3, 'Et au pied de cette montagne une vallée étroite, et au milieu d’autres vallées profondes et desséchées vers l’extrémité de ces trois montagnes. Or, toutes ces vallées, qui étaient profondes, mais étroites, se composaient d’un immense rocher, sur lequel un arbre était planté. Et dans mon étonnement j’admirai le rocher et les vallées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 25, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 25, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 25, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 25, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 26, 1, 'Alors je m’écriai: Que signifie cette terre bénie, ces arbres élevés, et cette vallée maudite qui les sépare?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 26, 2, 'Et Uriel, un des saints anges qui étaient avec moi, me répondit: Cette vallée est maudite d’une malédiction éternelle. C’est ici que seront rassemblés tous ceux qui se servent de leurs langues pour blasphémer Dieu, qui ouvrent la bouche pour maudire sa gloire. C’est ici qu’ils seront rassemblés, c’est ici que sera leur demeure.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 26, 3, 'Dans le jour suprême du jugement, il sera fait d’eux un grand exemple de justice aux yeux de tous les saints; car ceux-ci obtiendront grâce devant Dieu, et le béniront tous les jours de leur vie, comme leur Seigneur et leur Roi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 26, 4, 'Et ils le célébreront dans ce jour redoutable du jugement, à cause de la clémence qu’il aura fait éclater sur eux. Alors je me tournai naturellement vers Dieu, et je louai son nom, sa grandeur et sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 26, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 26, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 27, 1, 'De là je me dirigeai du côté de l’orient, vers une montagne qui s’élève au milieu du désert, et dont je ne pus apercevoir que la superficie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 27, 2, 'Elle était couverte d’arbres issus de la semence dont on a parlé, et une eau en descendait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 27, 3, 'De là une cataracte, composée en apparence de plusieurs autres, s’échappait à l’occident et à l’orient. D’un côté s’élevaient des arbres, de l’autre on voyait de l’eau et de la rosée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 27, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 27, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 28, 1, 'Alors je m’avançai vers un autre endroit du désert, vers l’orient de la montagne, de laquelle je m’étais approché.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 28, 2, 'Là j’aperçus des arbres de choix, ceux-là surtout qui produisent les aromates aux suaves odeurs, l’encens, la myrrhe, tous arbres distincts les uns des autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 28, 3, 'Et il y avait encore en ce lieu, dominant tous ces arbres, une élévation vers l’orient, qui n’était pas éloignée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 29, 1, 'Je vis encore un autre endroit, avec des vallées où s’écoulaient des eaux qui ne tarissaient jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 29, 2, 'Je vis un arbre magnifique qui, pour l’odeur, égalait le Lentisque. Et sur les flancs de cette vallée j’aperçus le cinnamome au délicieux parfum. Et je m’avançai vers l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 30, 1, 'Alors j’aperçus une autre montagne, remplie d’arbres, d’où s’échappait une eau semblable au neketra. Son nom était Sarira et Calbanen. Et sur cette montagne j’en vis une autre sur laquelle s’élevaient les arbres d’aloës.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 30, 2, 'Ces arbres étaient chargés comme des amandiers et gros, et le fruit qu’ils produisaient surpassait tout parfum.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 30, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 31, 1, 'Après cela, je me tournai du côté du nord et je me mis à en considérer les entrées par-dessus les montagnes et j’aperçus sept montagnes couvertes de spic fin, d’arbres odoriférants, de cannelliers et de papyrus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 31, 2, 'Puis je laissai derrière moi les sommets de ces montagnes et m’avançant vers l’orient, je passai la mer Érythrée. Et quand je l’eus dépassée, je tournai mes pas vers l’ange Zatael, et je parvins au jardin de Justice. Là je vis entre autres, plusieurs arbres élevés, couverts de fleurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 31, 3, 'Leurs parfums étaient délicieux, leurs formes variées et élégantes. Il y avait là aussi l’arbre de la science, dont les fruits illuminent l’intelligence de celui qui s’en nourrit. Il était semblable au tamarin, et ses fruits, d’une beauté remarquable, à des grappes de raisins; son parfum embaumait les lieux d’alentour. Et je m’écriai: Quel bel arbre quel spectacle délicieux! Alors l’ange Raphaël, qui était avec moi, me répondit: Ceci est l’arbre de la science, dont ont mangé ton vieux père et ta vieille mère; ses fruits les ont illuminés; leurs yeux ont été ouverts, et après s’être aperçus qu’ils étaient nus, ils ont été chassés du Paradis terrestre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 32, 1, 'Ensuite, je m’avançai vers les confins de la terre; là, je vis de grandes bêtes, d’apparences diverses, des oiseaux différents de formes et d’aspect, et doués de voix différentes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 32, 2, 'À l’orient du lieu où se trouvaient ces bêtes, j’aperçus les limites de la terre, et l’endroit où le ciel finissait. Les portes du ciel étaient ouvertes et j’en vis sortir les étoiles. Alors je les comptais à mesure qu’elles sortaient, et j’en notais exactement le nombre. Je pris note également de leurs noms, de leurs courses périodiques, de leurs vicissitudes, à mesure que l’ange Uriel, qui était avec moi, me les expliquait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 32, 3, 'Car il me les montra toutes, et de toutes il me donna connaissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 32, 4, 'Il me fit connaître encore leurs noms, leurs rangs et leurs diverses influences.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 32, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 32, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 33, 1, 'Puis je me dirigeai vers le septentrion, aux limites de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 33, 2, 'Et là, vers les confins du monde, je vis un prodige grand et magnifique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 33, 3, 'Je vis les portes du ciel ouvertes, il y en avait trois distinctes entre elles. Par elles s’échappaient les vents du nord, père du froid, de la grêle, de la glace, de la rosée et de la pluie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 33, 4, 'D’une de ces portes, les vents soufflaient légèrement; mais par les deux autres ils soufflaient avec violence, et leur souffle se répandait sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 34, 1, 'De là, je me dirigeai du côté de l’occident, vers les confins de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 34, 2, 'Et je vis trois portes, comme du côté du septentrion. Or ces portes étaient de la même grandeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 34, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 35, 1, 'Ensuite je me dirigeai du côté du sud, vers les confins de la terre. Il y avait là également trois portes, par où s’échappaient la rosée, la pluie et le vent. Puis je me dirigeai vers l’orient, aux confins de la terre, où je vis trois portes du ciel tournées du côté de l’orient, et dont l’ouverture était plus petite. Par ces petites portes sortaient les étoiles du ciel, qui suivaient leur route invariable vers l’occident; et cette route brillante était visible en tout temps. Quand je les aperçus, j’élevai ma voix et je louai le Seigneur qui avait formé ces corps lumineux et resplendissants, afin de révéler aux intelligences angéliques et humaines, la magnificence de ses œuvres; afin qu’ils célébrassent les uns et les autres, les merveilles de sa puissance, qu’ils glorifiassent les labeurs divins de ses mains, et afin qu’ils le louassent à tout jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 36, 1, 'Manque dans les manuscrits');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 36, 2, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 36, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 36, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 37, 1, 'Voici une autre vision, la seconde vision de sagesse, la vision qu’eut Enoch, fils de Jared, fils de Malaléel, fils de Caïnan, fils d’Enos, fils de Seth, fils d’Adam. C’est là le commencement de cette sagesse, que j’ai reçue pour expliquer et faire aimer à ceux qui habitent sur la terre. Écoutez donc, et comprenez les choses saintes que je viens vous révéler, en présence du Seigneur des esprits. Ceux qui existèrent avant nous ont regardé le ministère de la parole comme un de leurs devoirs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 37, 2, 'Et nous, qui venons après eux, nous ne mettons aucun empêchement à la prédication de la sagesse; mais jamais jusqu’à ce jour, il n’a été donné à personne ce qui m’a été donné à moi, la sagesse selon mon entendement, et dans la mesure du bon plaisir de Dieu. Ce que j’ai reçu de lui est vraiment une portion de la vie éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 37, 3, 'Cette sagesse était formulée dans cent trois paraboles, que je me suis fait un devoir d’annoncer aux habitants de ce monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 37, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 37, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 37, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 38, 1, 'Première parabole. Quand l’assemblée des justes sera manifestée à la terre, que les pécheurs seront punis, et recevront aux yeux de tous le châtiment mérité par leurs crimes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 38, 2, 'Quand la justice se manifestera devant les justes eux-mêmes; que leurs œuvres seront pesées par le Seigneur des esprits et leur mériteront de recevoir la récompense promise; quand la lumière des justes et des élus qui habitent sur la terre, brillera d’un éclat immortel, à ce moment, que deviendra la demeure du pécheur? où sera le lieu de repos de celui qui aura rejeté le Seigneur? Oh! qu’il vaudrait mieux pour lui, qu’il n’eût jamais existé!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 38, 3, 'Quand seront révélées les secrètes pensées des justes, les pécheurs subiront un jugement sévère, et les impies seront tourmentés en leur présence.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 38, 4, 'Dès ce moment, les maîtres de la terre cesseront d’être puissants et élevés. Il leur deviendra impossible de contempler les saints en face; car la lumière des justes et des élus ne peut être contemplée que du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 38, 5, 'Cependant les puissants de ce monde ne seront point anéantis, ils seront livrés aux mains des justes et des saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 38, 6, 'Désormais plus de miséricorde pour eux de la part du Seigneur, car avec le temps de la vie, le temps de la clémence aura passé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 1, 'Dans ces jours-là la race sainte et bénie descendra des hauteurs des cieux, et sa génération habitera avec les fils des hommes. Énoch a reçu les livres de l’indignation et de la colère, les livres du trouble et de l’agitation.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 2, 'Jamais ils n’obtiendront miséricorde, dit le Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 3, 'Alors la nuée m’enleva, et le vent me souleva sur la surface de la terre, et me transporta aux frontières des cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 4, 'Là j’eus une autre vision. Je vis la demeure et le séjour tranquille des saints. Oui, mes yeux eurent le bonheur de contempler leurs demeures avec celles des anges; le séjour de leur repos avec celui des saints. Là il y avait des demandes, des prières, des supplications pour les enfants des hommes. La justice coule devant eux comme une onde pure, et la clémence se répand sur la terre comme une précieuse rosée. Et telle est leur existence pour l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 5, 'En ce temps-là donc mes yeux contemplèrent la demeure des élus, le séjour de la vérité, de la foi et de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 6, 'Le nombre des saints et des élus de Dieu sera infini dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 7, 'J’ai vu leur demeure placée sous les ailes du Seigneur des esprits. Tous les saints, tous les élus chantaient devant lui, brillant comme le feu; leurs bouches étaient pleines des louanges de Dieu, et leurs lèvres s’ouvraient pour célébrer le nom du Seigneur des esprits. La justice se tenait debout devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 8, 'Là je désirai rester, là mon âme soupira après cette demeure. Là était la portion de mon héritage, depuis le commencement; car telle était sur moi la volonté du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 9, 'En ce temps-là je célébrai et j’exaltai le nom du Seigneur des esprits, par des bénédictions et des louanges. Car tel est le bon plaisir du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 10, 'Longtemps mes yeux contemplèrent ces demeures fortunées, et je louai Dieu, en disant: Béni soit-il, béni soit-il à jamais! depuis le commencement, avant la création du monde, jusqu’à la fin des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 11, 'Quel est ce monde? Oui, de toutes les générations ils doivent te bénir, tous ceux qui ne dorment point dans la poussière, mais qui contemplent ta gloire, qui te célèbrent, te magnifient et te bénissent, en disant Saint, saint, saint est le Seigneur des esprits, qui remplit de son immensité le monde entier des intelligences.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 12, 'Là, mes yeux contemplèrent tous ceux qui ne sont point endormis devant lui, qui se tiennent debout devant lui, qui le glorifient en disant: Béni sois-tu, béni soit le nom de Dieu à tout jamais! Et ma face fut tout à coup changée, en sorte que je ne pouvais plus voir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 39, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 1, 'Après cela j’aperçus des milliers de milliers, des myriades de myriades, et un nombre infini d’hommes, qui se tenaient debout devant le Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 2, 'Sous les quatre ailes du Seigneur des esprits, à ses quatre côtés, j’en vis encore d’autres, outre les premiers, qui se tenaient devant lui. J’appris en même temps leurs noms, parce que les anges qui étaient avec moi me les expliquaient, m’en révélant tous les mystères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 3, 'Alors j’entendis la voix de ceux qui étaient aux quatre côtés; ils célébraient le Seigneur de toute gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 4, 'La première voix célébrait le Seigneur des esprits dans tous les siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 5, 'La seconde voix que j’entendis célébrait l’élu et les élus qui sont tourmentés pour le Seigneur des esprits');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 6, 'La troisième voix que j’entendis suppliait et priait pour ceux qui sont sur la terre, et qui invoquent le Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 7, 'La quatrième voix que j’entendis repoussait les anges impies, et leur défendait de se présenter devant le Seigneur des esprits afin qu’ils ne suscitent point d’accusations contre les habitants de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 8, 'Après cela je demandai à l’ange de paix qui était avec moi, de m’expliquer tous ces mystères. Je lui dis: Quels sont ceux que j’ai vus aux quatre côtés du Seigneur, et dont j’ai entendu et écrit les paroles. Il me répondit: C’est d’abord saint Michel, l’ange clément et patient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 9, 'C’est ensuite saint Raphaël, l’ange qui préside aux douleurs et aux blessures des hommes. Vient ensuite Gabriel, qui préside à tout ce qui est puissant. Enfin c’est Phanuel, qui préside à la pénitence et à l’espérance de ceux qui doivent hériter de la vie éternelle. Tels sont les quatre anges du Dieu très-haut. Ce sont leurs quatre voix que tu viens d’entendre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 40, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 1, 'Ensuite je vis les secrets des cieux et du paradis dans toutes les parties, et les secrets des actions humaines, chacune selon leur poids et leur valeur. Je contemplai les habitations des élus, les demeures des saints. Là aussi mes yeux aperçurent tous les pécheurs qui ont repoussé et nié le Seigneur de gloire, et qui en ont été repoussés. Car le châtiment de leurs crimes n’avait pu encore être décrété par le Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 2, 'Là encore mes yeux contemplèrent les secrets de la foudre et du tonnerre, les secrets des vents, comment ils se divisent quand ils soufflent sur la terre; les secrets des vents, de la rosée et des nuées. Je vis le lieu de leur origine, l’endroit d’où ils s’échappent, pour aller se rassasier de la poussière de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 3, 'Là je vis les réceptacles d’où sortent les vents en se séparant; les trésors de la grêle, les trésors de la neige, les trésors des nuages, et cette même nuée qui, avant la création du monde planait sur la surface de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 4, 'Je vis également les trésors de la lune, où ses phases prenaient naissance; leur commencement, leur glorieux retour; comme l’une est plus brillante que l’autre; leur progrès éclatant, leur cours invariable, leur amitié entre elles, leur docilité, et leur obéissance qui les porte sur les pas du soleil, d’après l’ordre du Seigneur des esprits. Oh! que son nom est puissant dans tous les siècles!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 5, 'Ensuite fut achevé le sentier de la lune, tant sa partie cachée que sa partie visible, le parcours de son sentier aussi bien de jour que de nuit, chacune, l’une comme l’autre, tournait ses regards vers le Seigneur des esprits, l’exaltant et le louant sans interruption; d’autant plus que louer est pour elles comme un temps de repos, mais dans le soleil ce sont des retours fréquents à la bénédiction et à la malédiction.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 6, 'La lumière de la lune est pour les élus, comme les ténèbres sont pour les pécheurs; telle est la volonté du Seigneur des esprits, qui a distingué la lumière des ténèbres, comme il a distingué les esprits des hommes, fortifiant ceux des justes de sa propre justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 7, 'Et aucun ange ne les précédera, car aucun d’eux n’a reçu ce pouvoir. Quant au Seigneur, du haut de son trône, il voit toutes les créatures et les juge en souverain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 41, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 42, 1, 'La sagesse n’a point trouvé sur la terre de demeure où reposer sa tête; c’est pourquoi elle fait sa résidence dans le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 42, 2, 'La sagesse est descendue du ciel pour habiter avec les enfants des hommes, mais elle n’a point trouvé de demeure. Alors la sagesse est retournée vers son divin séjour, et a pris place au milieu des saints anges. Après sa retraite l’iniquité s’est présentée, et elle a trouvé une demeure, et elle a été reçue par les enfants des hommes, comme la pluie est reçue par le désert, comme la rosée est reçue par une terre desséchée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 42, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 43, 1, 'Je vis une autre splendeur, et les étoiles du ciel. Je remarquai qu’il les appelait toutes par leur nom, et qu’elles répondaient à son appel. Je le vis qui les pesait dans sa balance de justice, selon leur lumière, la grandeur des espaces qu’elles parcourent, et le jour où elles doivent apparaître ou s’éclipser. La splendeur engendre la splendeur, et leurs mouvements correspondent à ceux des anges et des fidèles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 43, 2, 'Alors j’interrogeai l’ange qui était avec moi, et qui m’expliquait les mystères, et je lui demandai quels étaient leurs noms. Il me répondit: « Le Seigneur des esprits t’en a fait voir une image. Ce sont les noms des justes, qui sont sur la terre, et qui croient au nom du Seigneur des esprits dans tous les siècles. »');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 43, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 43, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 44, 1, 'Je vis encore une autre chose remarquable par sa splendeur; elle émanait des étoiles, et devenait brillante, mais elle ne s’en séparait point.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 45, 1, 'Parabole seconde, qui s’adresse à ceux qui nient le nom et la demeure des saints et du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 45, 2, 'Ils ne monteront point au ciel; ils ne descendront point sur la terre. Voilà quel sera le sort des pécheurs qui renient le nom du Seigneur des esprits; il seront réservés pour le jour du châtiment et de la vengeance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 45, 3, 'En ce jour l’Élu siégera sur un trône de gloire. Il statuera sur leur sort, et, confirmant par sa présence les esprits des saints, il assignera une demeure à ceux qui ont mis leur confiance et leur amour dans son nom saint et glorieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 45, 4, 'En ce jour, je placerai mon élu au milieu d’eux, je changerai la face du ciel, je l’illuminerai pour l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 45, 5, 'Je changerai aussi la face de la terre, je la bénirai ainsi que tous ceux que j’ai choisis, et que je ferai habiter sur la terre, mais pour ceux qui ont commis l’iniquité, ils n’y demeureront plus, car je les ai vus et remarqués. Mais les justes, je les rassasierai de ma paix, je les placerai devant moi; aux pécheurs la damnation éternelle; ils seront effacés de dessus la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 45, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 1, 'Là je vis l’Ancien des jours, dont la tête était comme de la laine blanche, et avec lui un autre, qui avait la figure d’un homme. Cette figure était pleine de grâce, comme celle d’un des saints anges. Alors j’interrogeai un des anges qui étaient avec moi, et qui m’expliquaient tous les mystères qui se rapportent au Fils de l’homme. Je lui demandais qui il était, d’où il venait, et pourquoi il accompagnait l’Ancien des jours?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 2, 'Il me répondit en ces mots: « Ceci est le Fils de l’homme, à qui toute justice se rapporte, avec qui elle habite, et qui tient la clef de tous les trésors cachés; car le Seigneur des esprits l’a choisi de préférence, et il lui a donné une gloire au-dessus de toutes les créatures. »');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 3, 'Ce Fils de l’homme que tu as vu, arrachera les rois et les puissants de leur couche voluptueuse, les sortira de leurs terres inébranlables; il mettra un frein aux puissants, il brisera les dents des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 4, 'Il chassera les rois de leurs trônes et de leurs royaumes, parce qu’ils refusent de l’honorer, de publier ses louanges et de s’humilier devant celui à qui tout royaume a été donné. Il mettra le trouble dans la race des puissants; il les forcera de se coucher devant lui. Les ténèbres deviendront leur demeure, et les vers seront les compagnes de leur couche; point d’espérance pour eux de sortir de ce lit immonde, car ils n’ont pas consulté le nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 5, 'Ils mépriseront les astres du ciel, et lèveront les mains contre le Tout-Puissant, leurs pensées ne seront tournées que vers la terre, dont ils voudraient faire leur demeure éternelle; et leurs œuvres ne seront que les œuvres de l’iniquité. Ils mettront leurs joies dans leurs richesses, et leur confiance dans des dieux fabriqués de leurs propres mains. Ils refuseront d’invoquer le Seigneur des esprits; ils le chasseront de ses temples,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 6, 'Ainsi que les fidèles qui seront persécutés pour le nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 46, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 47, 1, 'En ce jour-là, les prières des saints monteront de la terre jusqu’au pied du trône du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 47, 2, 'Dans ce jour, les saints qui habitent au-dessus des cieux se rassembleront, et d’une voix unanime, ils prieront, ils supplieront, ils célébreront, ils loueront, ils exalteront le nom du Seigneur des esprits, à cause du sang des justes, répandu pour lui; et ces prières des justes s’élèveront incessamment vers le trône du Seigneur des esprits, afin qu’il leur rende enfin justice, et que sa patience pour les méchants ne soit point éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 47, 3, 'Dans ce temps, je vis l’Ancien des jours, assis sur le trône de sa gloire. Le livre de la vie était ouvert devant lui, et toutes les puissances du ciel se tinrent debout devant lui et autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 47, 4, 'Alors les cœurs des saints étaient inondés de joie, parce que le temps de la justice était arrivé, que la prière des saints avait été entendue, et que le sang des justes avait été apprécié par le Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 1, 'Dans ce temps-là, j’aperçus la source de la justice, qui ne tarissait jamais, et d’où s’émanaient une multitude de petits ruisseaux, qui étaient les ruisseaux de la sagesse. C’est là que tous ceux qui avaient soif venaient boire, et ils se trouvaient soudain remplis de sagesse, et ils faisaient leur demeure avec les justes, les élus et les saints.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 2, 'Et à cette heure, le Fils de l’homme fut invoqué devant le Seigneur des esprits, et son nom devant l’Ancien des jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 3, 'Et avant la création du soleil et des astres, avant que les étoiles ne fussent formées au firmament, on invoquait le nom du Fils de l’homme devant le Seigneur des esprits. Il sera le bâton des justes et des saints, ils s’appuieront sur lui, et ils ne seront point ébranlés; il sera la lumière des nations.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 4, 'Il sera l’espérance de ceux dont le cœur est dans l’angoisse. Tous ceux qui habitent sur la terre se prosterneront devant lui, et l’adoreront; ils le célébreront, ils le loueront; ils chanteront les louanges du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 5, 'Ainsi l’Élu et le Mystérieux a été engendré, avant la création du monde, et son existence n’aura point de fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 6, 'Il vit en sa présence, et il a révélé aux saints et aux justes la sagesse du Seigneur des esprits car c’est lui qui leur conserve la portion de leur héritage. Car ils ont haï et repoussé loin d’eux ce monde d’iniquité, ils ont détesté ses œuvres et ses voies, et n’ont voulu invoquer que le nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 7, 'Aussi c’est par ce nom qu’ils seront sauvés, et sa volonté sera leur vie. Dans ce jour là, les rois et les puissants de la terre qui auront conquis le monde par la force de leurs bras, seront humiliés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 8, 'Car au jour de l’anxiété et du trouble, leurs âmes ne seront point sauvées, mais ils seront soumis à ceux que j’ai choisis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 9, 'Je les jetterai comme on jette la paille dans le feu, comme on précipite le plomb dans l’eau. Ils brûleront en présence des justes, ils seront submergés aux yeux des saints, et on n’en trouvera pas même la dixième partie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 48, 10, 'Mais au jour de leur trouble, la paix régnera sur la terre. Ils tomberont en sa présence, et ne se relèveront plus; et il n’y aura personne qui puisse l’arracher de ses mains et le secourir; car ils ont repoussé le Seigneur des esprits et son Messie. Que le nom du Seigneur des esprits soit béni. La sagesse s’écoule comme de l’eau, et la gloire devant lui est intarissable dans tous les siècles des siècles, car il est puissant dans tous les mystères de la justice. Mais l’iniquité passe comme l’ombre, pour elle point de demeure stable, car l’Élu se tient debout devant le Seigneur des esprits, et sa gloire dure dans les siècles des siècles, et sa puissance est éternelle. Avec lui habite l’esprit de la sagesse et de l’intelligence, l’esprit de savoir et de puissance, les esprits de ceux qui dorment dans la justice: il juge et discerne les choses les plus cachées. Personne ne peut prononcer un seul mot devant lui, car l’Élu est devant la face du Seigneur des esprits, selon son bon plaisir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 49, 1, 'Dans ces jours, les saints et les élus auront leur tour. La lumière du jour habitera en eux, et la splendeur et la gloire les illuminera.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 49, 2, 'Dans les jours de trouble, tous les maux fonderont sur les pécheurs, mais les justes triompheront au nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 49, 3, 'D’autres comprendront enfin qu’il leur faut se repentir et en finir avec les œuvres mauvaises de leurs mains; ils comprendront qu’ils n’ont pas à attendre de louanges devant le Seigneur des esprits, mais qu’ils peuvent encore être sauvés par son nom. Le Seigneur des esprits exercera sa miséricorde sur eux; car, grande est sa clémence et la justice est en ses jugements, et il n’y a point d’iniquité. Aussi quiconque ne fera point pénitence, périra.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 49, 4, 'Non, ils n’auront plus de grâce à attendre de moi, dit le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 50, 1, 'Dans ces jours-là, la terre rendra de son sein et l’enfer du sien ce qu’ils ont reçu, et l’abîme rendra ce dont il est redevable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 50, 2, 'Il séparera les justes et les saints des méchants, car ce sera pour les premiers des jours de grâce et de salut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 50, 3, 'Dans ces jours, l’Élu siégera sur son trône, et tous les secrets de la sagesse et de l’intelligence s’échapperont de sa bouche; car le Seigneur des esprits l’a doté d’une gloire éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 50, 4, 'Dans ces jours, les montagnes tressailleront comme des béliers, et les collines bondiront comme des agneaux rassasiés de lait, et les justes seront des anges dans le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 50, 5, 'Leur visage resplendira d’une joie ravissante; car dans ces jours, l’Élu sera exalté; la terre tressaillera d’allégresse, les justes l’habiteront, et les élus la fouleront de leurs pieds innocents.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 51, 1, 'Après ce temps, dans le lieu même où j’avais vu tant de mystères, je fus enlevé par un tourbillon et emporté vers l’Occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 51, 2, 'Là, mes yeux aperçurent les secrets du ciel et ceux de la terre; une montagne de fer, une montagne d’airain, une montagne d’argent, une montagne d’or, une montagne d’un métal liquide, enfin une montagne de plomb.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 51, 3, 'Et j’interrogeai l’ange qui était avec moi, et je lui dis: Que signifient ces choses que je viens d’apercevoir?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 51, 4, 'Et l’ange me répondit: Toutes ces choses que tu as vues, regardent l’empire du Messie, et sont un symbole de son règne et de sa puissance sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 51, 5, 'Et cet ange de paix me répondit encore: Patience encore un peu de temps, et tu verras, et il te sera révélé toutes les choses qu’à décrétées la sagesse du Seigneur des esprits. Ces montagnes que tu as aperçues, et qui sont l’une d’airain, l’autre de fer, la troisième d’argent, la quatrième d’or, la cinquième d’un métal liquide, la sixième enfin, de plomb; toutes ces montagnes, dis-je, seront en la présence de l’Élu, comme un gâteau de miel devant une fournaise ardente, où comme l’eau qui coule du haut d’une montagne; elles tomberont à ses pieds. Dans ces jours là, les hommes ne trouveront leur salut ni dans l’or, ni l’argent. Ils ne pourront ni fuir, ni se défendre. Alors il n’y aura plus d’armes à fabriquer avec l’airain, ni de cuirasse pour protéger la poitrine. Le fer deviendra inutile: cela même ne servira à rien qui ne se rouille ni ne s’use, et le plomb ne sera plus recherché. Tout sera rejeté, tout sera effacé de dessus la terre, quand l’Élu apparaîtra en la présence du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 1, 'Alors, mes yeux aperçurent une vallée profonde dont l’entrée était vaste et spacieuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 2, 'Tous ceux qui habitent sur la terre, dans la mer et dans les îles, y apporteront leurs tributs et leurs présents, et cependant rien ne pourra en combler la profondeur. Leurs mains commettront l’iniquité. Tout ce que les nobles labeurs des justes auront produits, les pécheurs le dévoreront honteusement. Mais ils périront de la face du Seigneur des esprits, et de la face de la terre elle-même. Quant aux justes ils se relèveront et ils vivront dans tous les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 3, 'Je vis les anges des châtiments qui y habitaient et qui préparaient les instruments de Satan.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 4, 'Alors j’interrogeai l’ange de la paix, qui était avec moi, et je lui demandai pour qui ces instruments?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 5, 'Il me répondit: Ils sont préparés pour les rois et les puissants de la terre; c’est par là qu’ils doivent périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 6, 'Ensuite apparaîtra le temple auguste où les élus et les justes se réuniront pour ne plus se séparer, par la vertu du nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 7, 'Ces montagnes ne subsisteront point en sa présence, pas plus que la terre et les collines; mais elles s’écouleront devant lui comme des sources d’eau vive. Les justes seront alors délivrés des persécutions des pécheurs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 52, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 53, 1, 'Alors je vis une autre partie de la terre, vers laquelle je me tournai, et j’aperçus une vallée profonde tout embrasée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 53, 2, 'À cette vallée les rois et les puissants étaient conduits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 53, 3, 'Là, mes yeux virent des instruments de supplices, des chaînes d’un fer sans pesanteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 53, 4, 'Alors j’interrogeai l’ange de paix qui était avec moi, et je lui dis: Pour qui réserve-t-on ces chaînes et ces instruments de supplice?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 53, 5, 'Il me répondit: Tous ces tourments sont préparés pour l’armée d’Azazeel; c’est là que ses soldats impies seront précipités sur des pierres aiguës; ainsi le veut le Seigneur des armées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 53, 6, 'Quant à Michel, Gabriel, Raphaël et Phanuel, ils seront confirmés en ce jour; et ils seront chargés de jeter dans la fournaise ardente les anges rebelles; c’est ainsi que sera vengé le Seigneur des esprits; c’est ainsi que leurs crimes seront punis; car ils se sont faits les ministres et les serviteurs de Satan, ils sont devenus les séducteurs de ceux qui demeurent sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 53, 7, 'En ce jour, le Seigneur donnera le signal du supplice; les réservoirs d’eau qui sont sur le ciel, s’ouvriront ainsi que les sources qui sont sous le ciel et sous la terre. Toutes les eaux, tant supérieures qu’inférieures seront confondues. L’eau supérieure remplira le rôle de l’homme. L’eau inférieure, celui de la femme; tous ceux qui habitent la terre, tous ceux qui habitent sur les confins du ciel, tous, dis-je, seront exterminés. Ils comprendront, par la grandeur du châtiment, la grandeur de leur iniquité, et ils périront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 1, 'Et puis l’ancien des jours se repentit, et il dit: C’est en vain que j’ai détruit tous les habitants de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 2, 'Et il jura par son grand nom, en disant: Non, je n’agirai plus ainsi avec les habitants de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 3, 'Mais je placerai un signe dans le ciel, et il sera un témoin entre eux et moi, pour l’éternité, pour tout le temps que durera le ciel et la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 4, 'De plus, voici ce que j’ai résolu si je veux les surprendre, je me servirai des anges comme d’instruments de vengeance, au jour de l’affliction et du trouble, et ma colère s’appesantira sur eux, dit le Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 5, 'Ô rois, ô puissants de ce monde, vous verrez mon Élu assis sur le trône de ma gloire; il jugera Azazeel, tous ses complices et toutes ses cohortes, au nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 6, 'Là je vis les compagnies des anges au milieu des supplices, enfermés dans des rets de fer et d’airain. Alors, je demandai à l’ange de paix qui était avec moi: vers qui vont tous ces prisonniers?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 7, 'Il me dit: Vers chacun de leurs élus et enfants bien-aimés, afin qu’ils soient tous précipités dans les profondeurs de la vallée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 8, 'Et cette vallée sera remplie de leurs élus et de leurs bien-aimés, dont les jours sont terminés, sans doute, mais dont les jours d’erreurs ne doivent point finir.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 9, 'Alors les princes se réuniront et conspireront ensemble. Les principaux de l’Orient, parmi les Parthes et les Mèdes, chasseront les rois, dominés par l’esprit de vertige et d’erreur. Ils les renverseront de leurs trônes, bondissant comme des lions hors de leurs repaires, et comme des loups affamés au milieu des troupeaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 54, 10, 'Ils s’avanceront et fouleront sous leurs pas la terre de leurs élus. La terre de leurs élus s’étendra devant eux; l’aire, la voie et la ville de mon juste arrêtera leurs coursiers. Ils se lèveront pour se détruire mutuellement; leur droite sera fortifiée et nul homme ne reconnaîtra son frère ou son ami. Ni son père, ni sa mère, jusqu’à ce que le nombre des cadavres ait été complété par leur mort et leur châtiment. Et ce sera justice. Dans ces jours, l’abîme ouvrira sa gueule dévorante, et engloutira les pécheurs qui disparaîtront ainsi devant la face des élus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 55, 1, 'Après cela, j’aperçus une autre armée de chars, et ces chars étaient pleins de guerriers.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 55, 2, 'Portés sur l’aile des vents, ils venaient de l’Orient, de l’Occident et du Midi.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 55, 3, 'On entendait au loin le bruit de leurs chars roulant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 55, 4, 'Et ce bruit était si grand, que les saints l’entendirent du ciel; les colonnes et les fondements de la terre en furent ébranlées, et le bruit retentit en même temps des extrémités de la terre jusqu’à celles du ciel. Alors tous se prosternèrent et adorèrent le Seigneur des esprits. Ceci est la fin de la deuxième parabole.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 1, 'Alors je commençai à produire la troisième parabole, au sujet des justes et des élus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 2, 'Soyez bénis justes et élus, car votre destinée est glorieuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 3, 'Les justes demeureront dans la lumière du soleil, et les élus dans la lumière de la vie éternelle, de cette vie dont les jours n’ont point de déclin; les jours des saints ne seront point comptés; ils ont cherché la lumière, ils ont trouvé la justice du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 4, 'Paix soit donc aux saints par le Seigneur du monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 5, 'Dès ce moment, on dira que les justes cherchent dans le ciel les secrets de la justice, et la part d’héritage que la foi leur promet. Car ils se sont levés comme le soleil sur la terre et les ténèbres ont disparu. Là, il y aura une lumière sans fin, et des jours innombrables. Les ténèbres seront dissipées, et la lumière grandira devant le Seigneur des esprits; la lumière de la justice brillera sur eux d’un éclat sans pareil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 56, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 57, 1, 'Dans ces jours là mes yeux aperçurent les secrets des éclairs et des foudres et leur jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 57, 2, 'Ils brillent tantôt pour bénir tantôt pour maudire, suivant la volonté du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 57, 3, 'Je vis aussi les secrets de tonnerres, quand il tonne dans le ciel, et que la terre en retentit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 58, 1, 'Au quatorzième jour du septième mois de la cinq centième année de la vie d’Énoch, je vis dans cette parabole que le ciel des cieux fut ébranlé, et que les puissances très élevées, que des milliers de milliers et des myriades de myriades d’anges étaient dans une très-grande agitation. Et en regardant, je vis l’Ancien des jours assis sur son trône de gloire, et entouré des anges et des saints. Je fus saisi d’une grande frayeur, et comme frappé de stupéfaction; mes jambes se dérobèrent sous moi, et je tombai prosterné la face contre terre. Alors l’ange saint Michel, autre saint ange, fut envoyé pour me relever.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 58, 2, 'Et quand je fus debout, je repris les sens que j’avais perdus, ne pouvant supporter cette vision trop forte pour ma faiblesse, et les agitations et ce tressaillement du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 58, 3, 'Alors saint Michel me dit: Pourquoi te troubles-tu de cette vision?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 58, 4, 'Jusqu’aujourd’hui, c’était le temps de sa miséricorde et il a été miséricordieux et patient envers les habitants de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 58, 5, 'Mais quand viendront le jour et les puissances, le châtiment et le jugement que le Seigneur des esprits a préparés pour ceux qui s’inclinent devant le jugement de la justice et pour ceux qui nient le jugement de la justice et pour ceux qui prononcent son nom en vain;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 58, 6, 'Ce jour sera pour les élus un jour d’alliance, pour les pécheurs un jour de châtiment. Dans ce jour on fera sortir pour se repaître des méchants deux monstres, l’un mâle, l’autre femelle; la femelle s’appelle Léviathan; il habite dans les entrailles de la mer, sur les sources des eaux. Le monstre mâle se nomme Behemoth; il roule dans un désert invisible ses replis tortueux. Son nom était Dendagin à l’orient du jardin où habiteront les élus et les justes, et où fut placé mon aïeul, le septième après Adam, le premier homme créé par le Seigneur des esprits. Alors je demandai à l’autre ange qu’il me montre la puissance de ces monstres, et comment ils avaient été séparés dans le même jour pour être précipités, l’un dans le fond de la mer, l’autre dans le fond d’un désert. Et il me dit: Ô fils de l’homme, tu veux savoir les choses mystérieuses et cachées. Et l’ange de la paix qui était avec moi me dit: Ces deux monstres sont des créatures de la puissance divine, ils doivent dévorer ceux qu’aura punis la vengeance de Dieu. Alors les enfants tomberont avec leurs mères, les fils avec leurs pères. Et ils recevront le châtiment qu’ils auront mérité, et la justice de Dieu sera satisfaite, mais après ce jugement viendra l’heure de la miséricorde et de la longanimité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 59, 1, 'Alors l’autre ange qui était avec moi, me parla,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 59, 2, 'Et me révéla les premiers et les derniers secrets sur le ciel et sur la terre,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 59, 3, 'Sur les confins du ciel, et dans ses fondements, dans les réceptacles des vents; Il me montra comment leurs souffles sont divisés et pesés, comment les vents et les fontaines sont classés, d’après leur énergie et leur abondance. Il me fit voir l’éclat de la lumière de la lune, c’est une puissance de justice; comment des étoiles se subdivisent entre elles, et quel nom est propre à chacune. Il me montra encore les tonnerres distingués aussi entr’eux, par leur poids, par leur énergie, par leur puissance. Je vis l’obéissance de ces fléaux célestes à sa divine volonté. J’appris que la lumière ne se séparait point de la foudre, et quoique l’un et l’autre soient unis par des esprits différents, ils n’en sont pas moins inséparables Car quand la foudre sillonne la nue, le tonnerre gronde, mais leurs esprits s’arrêtent au moment opportun, et font un juste équilibre; leurs trésors sont aussi nombreux que les grains de sable. L’un et l’autre s’apaisent quand il le faut, et suivant les circonstances, ils compriment leurs forces ou ils les déchaînent. Également l’esprit de la mer est puissant et fort, et de même qu’une puissance prodigieuse la retire en arrière avec une bride, de même elle est chassée en avant et dispersée contre les montagnes. L’esprit des frimas, c’est son ange; l’esprit de la grêle est un bon ange ainsi que l’esprit de la neige, à cause de sa force, et il y a en elle principalement un esprit qui en fait élever comme de la fumée, et son nom est fraîcheur. L’esprit des nuages n’habite point avec ceux dont je viens de parler, mais il a sa demeure particulière; sa marche s’opère dans la splendeur, Dans la lumière et dans les ténèbres, dans l’hiver et dans l’été son séjour est splendide, et son ange est toujours lumineux. L’esprit de la rosée fait sa demeure sur les confins mêmes des cieux, son séjour est voisin de celui de la pluie; son empire s’exerce pendant l’hiver, pendant l’été. Quant aux nuages, voici leur origine: une première nuée est produite, elle s’en adjoint plusieurs autres; bientôt elles s’amoncellent portant la pluie dans leurs humides flancs; alors l’ange apparaît, il ouvre les trésors supérieurs, et la pluie est ainsi créée. Même chose arrive quand la pluie se répand sur la face de la terre, qu’elle va se réunir à toutes les eaux qui coulent dans son sein, après l’avoir fécondée; car les eaux sont la nourriture de la terre, telle est la volonté du Très-Haut. Voilà pourquoi il y a des limites à la pluie et les anges qui y procèdent, la répartissent avec une juste mesure. Je vis toutes ces merveilles, aussi bien que le jardin des justes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 1, 'Dans ces jours je vis des anges qui tenaient de longues cordes, et qui, portés sur leurs ailes légères, volaient vers le septentrion.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 2, 'Et je demandai à l’ange, pourquoi ils avaient en mains ces longues cordes, et pourquoi ils s’étaient envolés. Il me répondit: Ils sont allés mesurer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 3, 'L’ange qui était avec moi, me dit encore: Ce sont les mesures des justes; ils apporteront les cordes des justes, afin qu’ils s’appuient sur le nom du Seigneur des esprits à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 4, 'Les élus commenceront à habiter avec l’Élu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 5, 'Voilà les mesures qui seront données à la foi, et qui confirmeront la parole de la justice. 6. Ces mesures révéleront tous les secrets dans les profondeurs de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 7, 'Et il arrivera que ceux qui ont péri dans le désert, qui ont été dévorés par les poissons de la mer ou par les bêtes sauvages; — reviendront pleins d’espérance dans le jour de l’Élu; car personne ne périra en la présence du Seigneur des esprits, personne ne peut périr.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 8, 'Et tous ceux qui étaient dans le ciel, ont reçu l’empire, et la jouissance; la gloire et la splendeur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 9, 'Ils loueront par leur voix l’Élu de Dieu, et ils l’exalteront et le loueront avec sagesse, et ils feront voir leur sagesse dans la parole et dans l’esprit de la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 10, 'Alors le Seigneur des esprits plaça son élu sur le trône de sa gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 11, 'Pour qu’il juge toutes les œuvres des saints, du haut des cieux, et pèse leurs actions dans la balance de la justice. Et quand il élèvera sa face pour discerner les voies secrètes, qu’ils ont suivies, confiant dans le nom du Seigneur des esprits, et leurs progrès dans les sentiers de la justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 12, 'Tous réuniront leurs voix, le béniront, le loueront, l’exalteront, le célébreront au nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 13, 'Et il appellera à son tribunal toutes les puissances des airs et tous les saints, les chérubins, les séraphins et les ophanims, tous les anges de la puissance, tous les anges des dominations, c’est-à-dire les anges de l’Élu, et les autres puissances, qui au premier jour planaient sur les eaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 14, 'D’une voix unanime ils les exalteront, les béniront, les loueront, les célébreront, les magnifieront ces esprits de foi, ces esprits de sagesse et de patience, ces esprits de clémence, ces esprits de justice et de paix, ces esprits de bienveillance; tous s’écrieront à la fois: Béni soit-il; que le nom du Seigneur des esprits soit béni. Tous ceux qui ne dorment point, le loueront dans les cieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 15, 'Tous te loueront, les saints dans le ciel, les élus qui vivent dans le jardin, et tout esprit de lumière, capable de bénir, de louer, d’exalter, de célébrer ton sacré nom; toute chair, toute puissance, louera et célébrera ton nom dans les siècles des siècles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 16, 'Car la miséricorde du Seigneur des esprits est grande, grande est sa patience, et il a révélé ses œuvres, sa puissance, et tout ce qu’il est aux saints et aux élus, au nom du Seigneur des esprits.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 21, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 60, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 1, 'Le Seigneur a commandé aux rois, aux princes, aux puissants, à tous ceux qui habitent sur la terre, en disant: Ouvrez les yeux, levez au ciel vos fronts, et essayez de comprendre l’Élu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 2, 'Et le Seigneur des esprits siégeait sur son trône de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 3, 'Et l’esprit de justice était répandu autour de lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 4, 'Le verbe de sa bouche exterminera tous les pécheurs et tous les impies; aucun d’eux ne subsistera devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 5, 'Dans ce jour les rois, les princes, les puissants, et ceux qui possèdent la terre se lèveront, verront, et comprendront; ils le verront assis sur son trône de gloire, et devant lui les saints qu’il jugera dans sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 6, 'Et rien de ce qui sera dit devant lui, ne sera vain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 7, 'Alors le trouble les saisira, ils seront semblables à une femme surprise par les douleurs de l’enfantement, dont le travail est pénible, dont la délivrance est difficile.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 8, 'Ils se regarderont les uns les autres; et dans leur stupeur ils baisseront le visage.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 9, 'Et ils seront frappés d’effroi quand ils verront le Fils de la femme assis sur son trône de gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 10, 'Alors les rois, les princes, et tous ceux qui possèdent la terre, célébreront celui qui les gouverne tous, celui qui était caché. Car depuis le commencement le Fils de l’homme était caché; le Très-Haut le retenait en présence de sa puissance et ne le révélait qu’aux élus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 11, 'C’est lui qui a rassemblé les saints et les élus; aussi tous les élus seront-ils devant lui en ce jour.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 12, 'Tous les rois, les princes, les puissants, et ceux qui gouvernent sur la terre, se prosterneront devant lui, et l’adoreront.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 61, 13, 'Ils mettront leur espérance dans le Fils de l’homme, ils lui adresseront leurs prières, et invoqueront sa miséricorde. Alors le Seigneur des esprits se hâtera de les chasser de sa présence. Leurs visages seront alors pleins de confusion, et se couvriront de ténèbres épaisses. Puis les anges des châtiments célestes les saisiront, et la vengeance de Dieu s’appesantira sur ceux qui ont persécuté ses enfants et ses saints. Exemple terrible pour les saints et pour les élus, qui se réjouiront de cette justice infinie; car la colère du Seigneur des esprits persévérera sur eux. Alors le glaive du Seigneur des esprits se rassasiera du sang des méchants; mais les saints et les élus seront sauvés dans ce jour, et n’auront plus devant les yeux le spectacle des méchants et des impies. Le Seigneur des esprits planera seul désormais sur eux. Et ils habiteront avec le Fils de l’homme, ils mangeront, ils dormiront, ils se lèveront avec lui dans les siècles des siècles. Les saints et les élus s’élèveront de la terre; ils cesseront de baisser les yeux, en signe de dépendance et d’humilité; ils seront revêtus d’un vêtement de vie. Ce vêtement de vie leur est commun avec le Seigneur des esprits en sa présence votre vêtement ne vieillira point et votre gloire n’aura point de déclin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 1, 'Dans ces jours-là, les rois, les puissants et ceux qui possèdent la terre, imploreront les anges des châtiments célestes auxquels ils auront été livrés, de leur donner quelque repos, pour se prosterner devant le Seigneur des esprits et pour l’adorer et confesser leurs péchés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 2, 'Ils loueront et célébreront le Seigneur des esprits, en disant: Béni soit le Seigneur des esprits, le Roi des rois, le Prince des princes, le Seigneur des seigneurs, le Seigneur de la gloire, le Seigneur de la sagesse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 3, 'Il mettra au jour tout ce qui est secret.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 4, 'Ta puissance est dans les siècles des siècles, ainsi que ta gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 5, 'Tes secrets sont profonds et innombrables, et ta justice est incommensurable.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 6, 'Ah! nous voyons maintenant qu’il nous faut célébrer et louer le Roi des rois, celui qui est le maître absolu de toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 7, 'Et ils diront: Qui nous a donné quelque soulagement à nos maux pour célébrer, pour louer, pour bénir, pour confesser nos péchés et nos crimes en présence de sa gloire?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 8, 'Le soulagement que nous demandons est de quelques instants, et cependant nous ne pouvons l’obtenir; notre lumière s’est éteinte pour l’éternité, et les ténèbres nous environnent à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 9, 'Car nous ne l’avons pas confessé, nous n’avons pas célébré le nom du Roi des rois, nous n’avons pas glorifié le Seigneur dans toutes ses œuvres; mais nous avons mis notre confiance dans notre puissance et dans le sceptre de notre gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 10, 'Aussi, au jour de la douleur et de l’effroi, il ne nous sauvera pas, et nous ne trouverons point de repos. Nous le comprenons maintenant, le Seigneur est fidèle dans toutes ses œuvres, dans tous ses jugements, dans sa justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 11, 'Dans ses jugements, il ne fait point acception de personne; et voici que nous sommes repoussés loin de sa présence, à cause de nos mauvaises œuvres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 12, 'Nos péchés ne sont que trop bien pesés!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 13, 'Puis ils se diront les uns aux autres: Nos âmes se sont rassasiées des richesses de l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 14, 'Et voici qu’elles ne nous sont d’aucun secours dans ce moment que nous descendons dans les flammes de l’enfer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 15, 'Alors leurs visages seront remplis de ténèbres et de confusion en présence du Fils de l’homme; et ils seront repoussés loin de lui, car devant lui le glaive de la justice se dressera pour les exterminer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 62, 16, 'Et le Seigneur a dit: Voilà ce qu’a décrété ma justice contre les princes, les rois, les puissants, et ceux qui possèdent la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 1, 'Je vis encore d’autres visions dans ce lieu désert. J’entendis la voix de l’ange qui disait: Voici les anges qui sont descendus du ciel sur la terre, qui ont révélé les secrets aux fils des hommes, et leur ont enseigné à connaître l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 2, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 63, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 64, 1, 'Dans ce temps-là, Noé vit la terre s’incliner et menacer ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 64, 2, 'C’est pourquoi il se mit en route et se dirigea vers les limites de la terre, du côté de l’habitation de son aïeul Énoch. Et Noé s’écria trois fois d’une voix amère: Écoute-moi, écoute-moi, écoute-moi! Et il lui dit: Dis-moi ce qui se passe sur la terre, car elle paraît souffrir et être violemment tourmentée; assurément je périrai avec elle. En effet, il y avait une grande perturbation sur la terre, et une voix fut entendue du ciel. Je tombai la face contre terre; alors mon aïeul Énoch vint et se tint devant moi. Et il me dit: Pourquoi m’as-tu appelé d’une voix si amère et si lamentable? Le Seigneur a décidé dans sa justice que tous les habitants de la terre périraient, parce qu’ils connaissaient tous les secrets des anges, qu’ils ont en leurs mains la puissance ennemie des démons, la puissance de la magie, et ceux qui fondent des idoles sur toute la terre. Ils savent comment l’argent se tire de la poussière de la terre, comment il existe dans le sol des lames métalliques; car le plomb et l’étain ne sont point les fruits de la terre; il faut aller les chercher jusque dans ses entrailles. Et un ange a été préposé à leur garde, qui s’est laissé corrompre. Alors mon aïeul Énoch me prit par la main, et me relevant il me dit: Va! car j’ai consulté le Seigneur sur cette perturbation de la terre, et il m’a répondu: Ils ont rempli la coupe de leur impiété, et ma justice crie vengeance! Ils ont consulté les lunes, et ils ont connu que la terre devait périr avec tous ses habitants. Ils ne trouveront point de refuge dans l’éternité. Ils ont découvert des secrets qu’ils ne devaient point connaître; voilà pourquoi ils seront jugés; mais pour toi, mon fils, le Seigneur des esprits connaît ta pureté et ton innocence; il sait que tu blâmes la révélation des secrets. Le Seigneur, le Saint par excellence, a conservé ton nom au milieu de celui des saints; il te conservera pur de la corruption des habitants de la terre. Il donnera à tes descendants des royaumes et une grande gloire, et il naîtra de toi une race de justes et de saints dont le nombre sera infini.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 1, 'Après cela, il me montra les anges des châtiments célestes, qui se disposaient à venir donner aux eaux de la terre toute leur violence,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 2, 'Afin qu’elles servissent à la justice de Dieu et qu’elles fissent le supplice mérité de tous ceux qui habitent la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 3, 'Et le Seigneur des esprits défendit aux anges de porter aucuns secours aux hommes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 4, 'Car ces anges présidaient à la puissance des eaux. Alors je me retirai de la présence d’Énoch.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 65, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 66, 1, 'Dans ces jours-là, la parole de Dieu se fit entendre à mon oreille; elle disait: Noé, voici: ton existence est montée jusqu’à moi, existence pure de crime, existence pleine d’amour et de justice.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 66, 2, 'Déjà les anges élèvent des prisons; et dès qu’ils auront terminé cette tâche, j’étendrai ma main, et je te conserverai.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 66, 3, 'De toi sortira une semence de vie, qui renouvellera la terre; afin qu’elle ne reste pas vide. Je confirmerai ta race devant moi, et la race de ceux qui habiteront avec toi sera bénie et se multipliera sur la face de la terre, par la vertu du nom du Seigneur. J’ai vu cette vallée, et il y avait une grande confusion; et les eaux en jaillissaient. Et après que tout cela fut fait, il s’exhala, d’une masse fluide de feu, une forte odeur de soufre, avec des eaux jaillissantes, et la vallée des anges coupables de séduction brûlait sous cette terre. Dans cette vallée il coulait aussi des fleuves de feu, dans lesquels étaient précipités les anges, qui avaient égarés les habitants de la terre. En ces jours-là, elles serviront de guérison de l’âme et du corps aux rois, aux puissants, aux grands et à ceux qui habitent la terre, et, d’un autre côté, elles serviront pour la condamnation de l’esprit. Leur esprit sera tout entier aux plaisirs, afin qu’ils soient jugés dans leur corps, parce qu’ils ont méconnu le Seigneur des esprits, et que tout en prévoyant le châtiment qui les menace, ils n’en invoquent pas davantage son saint nom. Et comme leurs corps subiront un supplice terrible, de même aussi leurs âmes auront à supporter une punition éternelle. Car la parole du Seigneur des esprits à toujours son effet. Son jugement fondra sur eux, parce qu’ils se sont confiés dans les voluptés de leurs corps, et qu’ils ont nié le Seigneur des esprits. Dans ces jours les eaux de cette vallée seront changées; quand les anges seront jugés, l’ardeur de ces sources prendra une intensité nouvelle. Et quand les anges monteront, les eaux de ces sources se refroidiront après s’être échauffées. Alors j’entendis saint Michel qui me disait: Le jugement que subiront les anges menace également les rois, les princes et ceux qui possèdent la terre. Car ces eaux, en donnant la vie aux esprits des anges, donneront la mort à leur corps. Mais ils ne comprendront pas, ils ne croiront pas que ces eaux rafraîchissantes puissent se changer en un brasier ardent, qui brûlera pendant toute l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 1, 'Après cela mon aïeul Enoch me donna la connaissance de tous les secrets contenus dans son livre, et m’expliqua les paraboles, qui lui avaient été revélées, me les développant au milieu des paroles du livre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 2, 'Dans ce temps saint Michel répondit et dit à Raphaël: Mon esprit se soulève et s’ir rite contre la sévérité du jugement secret contre les anges; qui pourra supporter un jugement aussi terrible, qui ne sera jamais modifié, qui doit les perdre pour l’éternité?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 3, 'La sentence a été prononcee contre eux par ceux qui les ont fait sortir de cette façon. Et il arriva que se tenant devant le Seigneur des esprits. Saint Michel répondit, et dit à saint Raphaël: Quel cœur n’en serait point ému, quel esprit n’en aurait pas compassion?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 4, 'Puis saint Michel dit à Raphaël: je ne les défendrai point en présence du Seigneur; car ils ont offensé le Seigneur des esprits, en se conduisant comme des dieux; aussi la justice suprême s’exercera sur eux pendant toute l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 5, 'Ni l’ange innocent, ni l’homme n’en sentiront les effets; mais ceux-là seuls qui sont coupables, et dont la punition sera éternelle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 67, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 68, 1, 'Après cela ils seront frappés de stupeur et d’effroi à cause du jugement porté sur eux, en punition des révélations qu’ils ont faites aux habitants de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 68, 2, 'Voici le nom des coupables: le I de tous est Semiâzâ, le II Arstikifâ, le III Armên, le IV Kakabâel, le V Tur-el. le VI Rumia, le VII Dan-el, le VIII Nukael, le IX Barûq-êl, le X Azaz-êl, le XI Armers, le XII Batar-iâl, le XIII Basasaël, le XIV Auân-êl, le XV, Tur-iâl, le XVI Simâtisiel, le XVII letar-el, le XVIII Tumaël, le XIX Tar-él, le XX Rumaëi, le XXI Izêzéel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 68, 3, 'Tels sont les noms des princes des anges coupables, Voici maintenant les noms des chefs de leurs centaines, de leurs cinquantaines et de leurs dizaines.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 68, 4, 'Le nom du premier est Yekum; c’est celui qui séduisit tous les fils des saints anges, qui les poussa à descendre sur la terre, pour procréer des enfants avec des êtres humains.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 68, 5, 'Le nom du second est Kesabel, qui inspira de mauvaises pensées aux fils des anges, et les poussa à souiller leurs corps en s’accouplant avec les filles des hommes. Le nom du troisième est Gadrel; c’est lui qui a révélé aux fils des hommes les moyens de donner la mort. C’est lui qui séduisit Eve, et enseigna aux fils des hommes les instruments qui donnent la mort, la cuirasse, le bouclier, le glaive, et tout ce qui peut donner ou faire éviter la mort. Ces instruments passèrent de ses mains dans celles des habitants de la terre, et ils y resteront à tout jamais. Le nom du quatrième est Ténémue; c’est lui qui révéla aux fils des hommes l’amertume et la douceur, Et qui leur découvrit tous les secrets de la fausse sagesse. Il leur enseigna l’écriture, et leur montra l’usage de l’encre et du papier. Aussi par lui on a vu se multiplier ceux qui se sont égarés dans leur vaine sagesse, depuis le commencement du monde jusqu’à ce jour. Car les hommes n’ont point été créés pour consigner leur croyance sur du papier au moyen de l’encre. Ils ont été créés pour imiter la pureté et la justice des anges. Ils n’auraient point conçu la mort, qui détruit tout; c’est pourquoi la puissance me dévore. Ils ne périssent que par leur trop grande science. Le nom du cinquième est Kasyade; c’est lui qui a révélé aux enfants des hommes tous les arts diaboliques et mauvais. Ces moyens infâmes de tuer un enfant dans le sein de sa mère, ces arts qui se pratiquent par la morsure des serpents, par l’énergie, en plein midi, dans la semence du serpent qu’on nomme Tabaet. Ceci est le nombre de Kesbel, le principal serment que le Tout-Puissant, du sein de sa gloire, a révélé aux saints. Son nom est Beka. Celui-ci demanda à saint Michel de lui montrer le nom secret, afin d’en avoir l’intelligence, et afin de rappeler dans la mémoire le serment redoutable de Dieu; et de faire trembler, à ce nom et à ce serment, ceux qui ont révélé aux hommes tous les secrets dangereux. Tel est, en effet, l’office magique de ce serment; il est redoutable et sans merci. Et il mit ce serment d’Aka entre les mains de saint Michel. Voici les effets de ce serment: Par sa vertu magique, le ciel a été suspendu avant la création du monde. Par lui, la terre s’est élevée sur les eaux; et des parties cachées des collines les sources limpides jaillissent depuis la création du monde jusqu’en éternité. Par ce serment, la mer a été fixée dans ses limites, et sur ses fondements. Il a place des grains de sable pour l’arrêter au temps de sa fureur; et jamais elle ne pourra dépasser cette limite. Par ce serment redoutable, l’abîme a été creusé, et il conserve sa place à jamais. Par ce serment, le soleil et la lune accomplissent chacun leur course périodique, sans jamais s’écarter de la voie qui leur a été tracée. Par ce serment, les étoiles suivent leur éternelle route. Et quand elles sont appelées par leurs noms, elles répondent: Me voici! Par ce même serment, les vents président aux eaux; tous ont chacun leurs esprits, qui établissent entre eux une heureuse harmonie. Là se gardent les trésors des tonnerres et l’éclat de la foudre. Là sont conservés les trésors de la grêle et de la glace, les trésors de la neige, de la pluie et de la rosée. Tous ces anges conserveront et béniront le nom du Seigneur des esprits. Ils le célébreront par toute espèce de louange, et le Seigneur des esprits les soutiendra, les encouragera dans ces actions de grâces, et ils loueront, célébreront et exalteront le nom du Seigneur des esprits dans les siècles des siècles. Et ce serment a été confirmé sur eux, et leurs routes ont été tracées, et rien ne peut les empêcher de les suivre. Grande était leur joie. Ils le bénissaient, ils le célébraient, ils l’exaltaient, parce que le secret du Fils de l’homme leur avait été révélé. Et lui siégeait sur un trône de gloire; et la principale partie du jugement lui a été réservée. Les pécheurs s’évanouiront et seront exterminés de la face de la terre, et ceux qui les ont séduits seront entourés de chaînes à tout jamais. Selon le degré de leur corruption, ils seront livrés à différents supplices: quant à leurs œuvres, elles s’évanouiront de la face de la terre, et désormais il n’y aura plus de séducteurs, parce que le Fils de l’homme a paru assis sur son trône de gloire. Toute iniquité cessera, tout mal disparaîtra devant sa face, et la parole du Fils de l’homme subsistera seule en présence du Seigneur des esprits. Voilà la troisième parabole d’Énoch.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 1, 'Après cela, le nom du Fils de l’homme, vivant avec le Seigneur des esprits, fut exalté par les habitants de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 2, 'Il fut exalté dans leurs chars, et fut célébré au milieu d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 3, 'Depuis ce moment, je ne vais plus au milieu des enfants des hommes, mais il me plaça entre deux esprits, entre le septentrion et l’occident, où les anges avaient reçu des cordes pour mesurer le lieu réservé aux justes et aux élus.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 4, 'Là je vis les premiers pères, les saints qui habitaient dans ces beaux lieux pour l’éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 69, 13, '');
