INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 23, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 24, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 25, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 26, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 27, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 28, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 29, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 30, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 31, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 32, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 33, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 34, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 35, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 36, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 72, 37, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 1, 'Alors je vis une autre loi, qui consiste dans la détermination des mois lunaires: Uriel mon saint ange, et mon conducteur ne me laissa rien ignorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 2, 'J’ai donc tout écrit, dans la manière qu’il me l’a révélé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 3, 'J’ai noté les mois, dans l’ordre qu’ils arrivent, l’apparition et les phases de la lune pendant quinze jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 4, 'J’ai inscrit à quelle époque la lune perd complètement sa lumière, et à quelle époque elle jouit de tout son éclat.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 5, 'En certains mois la lune s’avance seule, et pendant deux autres mois elle se couche avec le soleil par les deux portes qui se trouvent au milieu, c’est-à-dire, par la troisième et la quatrième. Elle sort pendant sept jours, et accomplit sa course.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 6, 'Puis elle se rapproche de la porte qu’a franchie le soleil, et pendant huit jours elle passe par la seconde porte, ainsi que le soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 7, 'Et lorsque le soleil sort par la quatrième porte, la lune en sort pendant sept jours, jusqu’à ce que le soleil passe par la cinquième porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 73, 8, 'Pendant sept jours encore, elle décline vers la quatrième porte; elle est alors dans tout son éclat; mais elle diminue bientôt et s’avance par la première porte pendant huit jours. Puis elle se dirige de nouveau vers la quatrième porte, d’où le soleil se lève. Je vis donc leur position, ainsi que le lever et le coucher du soleil, suivant l’ordre de ses mois. Et dans ces jours à chaque cinq années on ajoutera trente jours, parce qu’ils sont en plus dans l’année solaire. Et tous les jours qui appartiendront à une de ces cinq années seront au nombre de trois cent soixante-quatre. Il y aura en plus six jours pour chacune d’elles, de manière à former un mois supplémentaire de trente jours. Le mois lunaire est plus court que le mois solaire et sidéral. Du reste, c’est elle qui règle les années, de manière qu’elles ne varient pas d’un seul jour et se composent invariablement de trois cent soixante-quatre jours. En trois ans, il y a mille quatre-vingt-douze jours; en cinq années, dix-huit-cent-vingt; en huit années, deux mille neuf cent-douze jours. Quant aux années lunaires, trois années comprennent mille soixante-deux jours; cinq années, moins longues que celles du soleil de cinquante jours, n’embrassent que mille sept cent soixante-dix jours, et huit années lunaires comprennent deux mille huit cent trente-deux jours. Aussi huit années lunaires sont-elles plus courtes que huit années solaires de quatre-vingts jours. L’année se forme donc par la course du soleil ou de la lune; elle est donc, suivant qu’on le rapporte à l’un ou à l’autre de ces astres, ou plus longue ou plus courte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 1, 'Voici maintenant les chefs et les princes qui président à toute la création, à toutes les étoiles, ainsi qu’aux quatre jours intercalaires ajoutés pour compléter l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 2, 'Ils ont besoin de ces quatre jours, qui ne font point partie de l’année.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 3, 'Les hommes se trompent respectivement au sujet de ces jours; car il faut se rapporter à ces luminaires pour s’en rendre compte, puisque l’un est intercalé à la première porte, le second à la troisième, un autre à la quatrième, et le dernier à la sixième.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 4, 'C’est ainsi que se trouve complété le nombre de trois cent soixante-quatre positions, qui forment autant de jours. Voilà les signes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 5, 'Les saisons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 6, 'Les années.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 7, 'Et les jours tels qu’Uriel me les fit connaître. Uriel est l’ange que le Seigneur de gloire a préposé à toutes les étoiles');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 8, 'Qui brillent dans le ciel et éclairent la terre. Ce sont:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 9, 'Les dispensateurs des jours et des nuits, savoir: le soleil, la lune, les astres de toute la milice céleste qui, avec tous les autres chars, parcourent le ciel en tous sens.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 10, 'Ainsi Uriel me fit voir douze portes qui s’ouvrent pour le char du soleil, d’où jaillissent des infinités de rayons.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 11, 'C’est par eux que l’été se forme en la terre quand ces portes s’ouvrent aux époques fixéees; d’elles aussi s’échappent les vents et les esprits de la rosée, quand les fenêtres aux extrémités du ciel s’ouvrent aux époques fixées par la volonté divine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 12, 'Je vis douze portes dans le ciel aux extrémités de la terre, desquelles sortent le soleil et la lune et les étoiles et tous les ouvrages du ciel au levant et au couchant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 13, 'Bien d’autres fenêtres s’ouvrent encore à droite et à gauche.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 14, 'L’une de ces fenêtres augmente la chaleur de l’été, aussi bien que les portes d’où sortent et où rentrent sans cesse les étoiles dans un cercle sans fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 15, 'Et je vis dans le ciel le char de ces étoiles qui tournait sur le monde sans jamais décliner. Une d’entre elles est plus brillante que les autres; celle-ci fait le tour du monde entier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 74, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 1, 'Et vers les frontières de la terre, je vis douze portes pour tous les vents, qui s’en échappent de temps en temps pour se répandre sur la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 2, 'Trois de ces portes s’ouvrent dans la partie opposée du ciel, trois autres à l’occident, trois à droite et trois à gauche. Les trois premières regardent l’orient; les trois dernières le nord. Celles qui sont placées à droite et à gauche regardent respectivement le midi et l’occident.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 3, 'Par quatre portes sortent des vents de bénédiction et de salut, et par les huit autres des vents de désolation. Quand ils en ont mission, ils corrompent la terre et ses habitants, l’eau et tout ce qui vit dedans.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 4, 'Le prince des vents sort par la porte placée à l’orient et par la première porte à l’orient qui s’incline vers le midi. Če vent apporte la destruction, l’aridité, la chaleur suffocante et la corruption.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 5, 'De la seconde porte, qui est au milieu, sortent l’égalité ou la juste mesure de toutes choses, la pluie, la fertilité, la salubrité et la force; de la dernière porte, tournée vers le nord, proviennent le froid et l’aridité');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 6, 'Après ces vents viennent les vents du Notus, qui soufflent par trois portes principales; par la première, tournée vers l’orient, s’échappe un vent chaud.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 7, 'Mais par la porte du milieu s’exhale une odeur agréable, la rosée, la pluie, le salut et la vie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 8, 'De la troisième porte, vers l’occident, proviennent la rosée, la pluie, la nielle et la perdition.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 75, 9, 'Les Aquilons soufflent par trois portes. De la septième, placée près de celle qui regarde le midi, sortent la rosée, la pluie, la nielle et la perdition. De celle du milieu viennent la pluie, la rosée, la vie et le salut. De la troisième porte, tournée à l’occident, mais se rapprochant du nord, viennent les nuées, les glaces, la neige, la pluie et la rosée. Viennent ensuite, dans la quatrième région, les vents occidentaux. De la première porte sortent la rosée, la pluie, la glace, le froid, la neige et la gelée; de la porte du milieu, la pluie, la rosée, le calme et l’abondance. De la dernière, du côté du-midi, l’aridité, la destruction, la sécheresse et la mort. Ainsi se termine la description des douze portes placées aux quatre coins du ciel. Toutes leurs lois, toutes leurs influences bonnes on mauvaises, je te les ai expliquées, o mon fils Mathusala!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 1, 'Le premier vent s’appelle oriental, parce qu’il est le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 2, 'Le second, se nomme vent du midi, parce que c’est à ce moment que descend l’éternel, le Béni à jamais.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 3, 'Le vent d’occident, s’appelle encore vent de la diminution, parce que c’est de son côté que tous les luminaires célestes s’affaiblissent et descendent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 4, 'Le quatrième vent, le vent du septentrion, se subdivise en trois parties; l’une est consacrée à l’habitation des hommes, l’autre est occupée par des lacs, des vallées, des forêts, des rivières, des lieux couverts de ténèbres ou de neige; la troisième enfin, est le paradis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 5, 'Je vis sept montagnes plus hautes que toutes les montagnes de la terre, d’où sortent les frimas, les jours, les saisons, et les années y vont et s’y évanouissent.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 6, 'Je vis sept fleuves sur la terre, plus grands que tous les autres fleuves; l’un coule de l’occident à l’orient, et va se jeter dans la grande mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 7, 'Deux autres coulent du nord à la mer, et vont se jeter dans la mer Érrythrée, vers l’orient. Quant aux quatre autres, deux coulent du nord vers la mer Érythrée, les deux derniers vont se jeter dans la grande mer, là où se trouve un immense désert.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 8, 'Je vis sept grandes îles sur cette mer, 2 proche de la terre, cinq dans la grande mer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 76, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 1, 'Les noms du soleil sont: Oz-iâres et Tomas.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 2, 'La lune a quatre noms: le premier est Asonia, le second Ebla; le troisième Benaces, et le quatrième Erae.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 3, 'Tels sont ces deux grands luminaires, dont les orbites sont comme les orbites du ciel, et dont les dimensions sont égales.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 4, 'Dans l’orbite du soleil, il y a sept parties de lumière, qui sont réfléchies par la June. Ces sept parties vont frapper la June jusqu’à la dernière. Ils sortent par la porte de l’occident, après avoir éclairé le septentrion, et reviennent dans le ciel par la porte de l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 5, 'Lorsque la lune se lève, elle apparaît dans le ciel; et elle est éclairée par la moitié de la septième partie de la lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 6, 'Cette lumière se complète au bout de quatorze jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 7, 'Bientôt se complètent trois fois cinq parties de lumière, en sorte qu’après quinze jours, elle soit arrivée à sa parfaite croissance.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 8, 'La lune alors réfléchit toute la lumière qu’elle reçoit du soleil.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 77, 9, 'Elle décroît ensuite, et elle suit dans sa décroissance la même marche qu’elle avait mise dans sa croissance En certains mois, la lune a vingt-neuf jours. Il y a d’autres mois où elle n’a que vingt-huit jours. Uriel me révéla encore une autre loi. C’est la manière dont la lumière émanant du soleil vient se répandre sur la lune. Pendant tout le temps que la lune progresse dans sa lumière, elle s’avance devant le soleil, jusqu’à ce qu’au bout de quatorze jours sa lumière devienne pleine dans le ciel. Mais quand elle décroît, ou que cette lumière est absorbée peu à peu dans le ciel, le premier jour s’appelle nouvelle lune, parce que c’est dans ce jour qu’elle recommence à recevoir la lumière du soleil. Elle se trouve complète, le jour où le soleil descend à l’occident, pendant que la lune monte à l’orient. Alors la lune brille pendant toute la nuit jusqu’à ce que le soleil se lève avant elle; alors la lune s’évanouit devant le soleil. Quand la lumière s’approche de la June, elle décroît encore, jusqu’à ce qu’elle soit complétement éclipsée; alors son temps est terminé. Alors son orbite vide est sans aucun éclat. Pendant trois mois elle accomplit sa période en trente jours, et pendant trois autres mois, elle l’accomplit en vingt-neuf jours. La nuit, elle apparaît pendant vingt jours comme une figure d’homme, et dans le jour, elle se confond avec le ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 1, 'Et maintenant, mon fils Mathusala, je t’ai tout fait connaître; et la description du ciel est terminée.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 2, 'Je t’ai fait voir le cours de tous les globes lumineux qui président aux saisons, aux différents temps de l’année, et leurs diverses influences, produisant les mois, les semaines et les jours. Je t’ai également fait voir les décroissements de la lune, qui ont lieu à la sixième porte, car c’est à cette porte que la lune perd sa lumière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 3, 'C’est par là que commence la lune; c’est aussi là qu’elle finit à époque certaine, lorsqu’elle a parcouru cent soixante-dix-sept jours, c’est-à-dire, vingt-cinq semaines et deux jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 4, 'Sa période est plus petite que celle du soleil; elle a cinq jours de moins par semestre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 5, 'Quand elle se trouve dans son plein, elle présente la face d’un homme. C’est ainsi que me l’a fait connaître Uriel, le grand ange qui la régit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 12, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 78, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 79, 1, 'Dans ces jours-là, Uriel me dit: Voici, je t’ai fait tout connaître, ô Enoch.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 79, 2, 'Je t’ai tout révélé. Tu vois le soleil, la lune et les anges qui dirigent les étoiles du ciel, qui président à leurs mouvements, à leurs phases, à leurs conversions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 79, 3, 'Les jours des pécheurs ne seront point complets.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 79, 4, 'Leurs semences manquerout dans les champs et dans les campagnes; les travaux de terre seront bouleversés, rien ne viendra pour eux en son temps. La pluie restera dans les airs, et le ciel sera d’airain.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 79, 5, 'En ce temps-là les produits de la terre seront tardifs; iis ne fleuriront point en leur temps, et les arbres retiendront leurs fruits. 6. La lune changera son cours, elle n’apparaîtra point en son temps; le ciel brůlant et sans nuages sera, visible, et la stérilité s’étendra sur la face de la terre. Des météores sillonneront le ciel; car beaucoup d’étoiles, se détournant de leur course accoutumée, erreront dans l’espace. Et les anges qui les régissent ne seront point là pour les faire rentrer dans leur route; et toutes les étoiles se soulèveront contre les pécheurs. Les habitants de la terre seront confondus dans leurs pensées; ils pervertiront toutes leurs voies. Ils transgresseront les commandements du Seigneur et se croiront des dieux; cependant le mal ne fera que se multiplier au milieu d’eux. Mais le châtiment céleste ne se fera pas attendre: ils périront tous.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 79, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 1, 'Et il me dit « O Enoch, regarde ce livre qui est descendu des cieux; lis ce qui y est contenu, et cherche à comprendre tout ce qu’il contient. »');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 2, 'Alors j’aperçus tout ce qui venait du ciel, et je compris tout ce qui était écrit dans le livre. En le lisant, je connus toutes les œuvres des hommes;');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 3, 'Toutes les œuvres des enfants de la chair, depuis le commencement jusqu’à la fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 4, 'Et je louai le Seigneur, le Roi de gloire, l’Ouvrier de toutes ces merveilles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 5, 'Et je le célébrai à cause de sa longanimité, à cause de sa miséricorde envers les enfants du monde.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 6, 'Et je m’écriai: Bienheureux est l’homme qui meurt dans la justice et le bien, et auquel on ne peut opposer aucun livre de crimes; qui n’a point connu l’iniquité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 7, 'Alors les trois saints me saisirent, et, me transportant sur la terre, me déposèrent devant la porte de ma maison.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 80, 8, 'Et ils me dirent: Explique toutes ces choses à ton fils Mathusala; annonce à tous tes enfants que nulle chair ne sera justifiée devant le Seigneur, car il est le Créateur. Pendant une année entière nous te laisserons avec tes enfants, jusqu’à ce que tu recouvres ta force première et que tu sois en état d’instruire ta famille, d’écrire toutes les choses que tu as vues, et de les expliquer à tes enfants. Mais, au milieu de l’année prochaine, on t’enlèvera du milieu des tiens; et ton cœur retrouvera sa première force; car l’élu découvrira à l’élu les secrets de la justice, le juste se réjouira avec le juste; ils confesseront Dieu ensemble. Quant aux pécheurs, ils périront avec les pécheurs; Et les pervers avec les pervers. Ceux-là mêmes qui auront vécu dans la justice mourront à cause des méfaits des hommes, et ils expireront à cause des actions des méchants. Dans ces jours, ils cesseront de me parler. Et je revins à mes frères, en louant et en bénissant le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 1, 'Or, mon fils Mathusala, je t’ai tout dit, tout écrit; je t’ai tout révélé, et je t’ai donné un traité sur chaque chose.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 2, 'Conserve, mon fils, les livres écrits de la main de ton père, et transmets-les aux générations futures.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 3, 'Je t’ai donné la sagesse, à toi, à tes enfants et à la postérité, afin qu’ils la transmettent, cette sagesse supérieure à toutes leurs pensées, à leur postérité. Et ceux qui la comprendront ne dormiront point; mais ils ouvriront leurs oreilles pour la recevoir, afin de se rendre dignes de cette sagesse, qui sera pour eux comme une nourriture céleste.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 4, 'Bienheureux les justes, bienheureux ceux qui marchent dans la justice, qui ne connaissent point l’iniquité, et qui ne ressemblent point aux pécheurs dont les jours sont comptés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 5, 'Quant à la marche du soleil dans le ciel, il entre et il sort par les différentes portes pendant trente jours, avec les chefs des mille espèces d’étoiles, avec les quatre qui leur sont ajoutés et qui sont relatifs aux quatre jours supplémentaires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 6, 'Les hommes sont dans de grandes erreurs au sujet de ces jours; ils n’en font point mention dans leurs calculs. Mais ces jours supplémentaires existent: un à la première porte, un second à la troisième, un troisième à la quatrième, un dernier à la sixième porte.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 7, 'L’année est ainsi composée de trois cent soixante-quatre jours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 8, 'Ainsi le calcul est exact. Car ces luminaires, ces mois, ces périodes, ces années et ces jours, Uriel me les a révélés et expliqués, lui qui, de par Dieu, a puissance sur tous ces astres, et qui règle leurs influences.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 9, 'Voilà l’ordre de ces astres, chacun suivant l’endroit du ciel où il se lève et se couche, suivant les saisons, les temps, les périodes, les jours et les mois.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 81, 10, 'Voici les noms de ceux qui les dirigent, qui veillent sur leurs voies, sur leurs périodes, sur leurs influences. Quatre d’entre eux ouvrent la marche; ils partagent l’année en quatre parties. Douze autres viennent ensuite, qui forment les douze mois de l’année, divisés en trois cent soixante-quatre jours, avec les chefs des mille qui distinguent les jours, les jours ordinaires comme les jours supplémentaires; qui, comme les premiers chefs, partagent l’année en quatre parties. Les chefs des mille sont placés au milieu des autres, et chacun d’eux est à sa place. Or, voici les noms de ceux qui président aux quatre parties de l’année, savoir: Melkel, Helammelak; Meleyal et Narel. Quant aux noms des autres, ce sont: Adnarel, Jyasural et Jeyelumeal. Ces trois derniers marchent après les chefs de la classe des étoiles; chacun marche régulièrement après ceux qui partagent l’année en quatre parties. Dans la première partie de l’année apparaft Melkel, qu’on nomme encore Tamaa et Zahaïa. Les jours soumis à son influence sont au nombre de quatre-vingt-onze. Et voici ce que l’on voit sur la terre pendant ces jours: sueur, chaleur et travail. Tous les arbres deviennent fertiles, les feuilles poussent, la moisson réjouit le laboureur, la rose et toutes les fleurs embellissent la campagne, et les arbres morts dans l’hiver se dessèchent. Voici ceux qui commandent en second Barkel, Zehabel et Heloyalel, auquel s’adjoint encore Helammelak, appelé aussi Soleil, ou très-brillant. Les jours soumis à leur influence sont au nombre de quatre-vingt-onze. Voici ce qui se passe sur la terre pendant ce temps: chaleur et sécheresse; les arbres donnent leurs fruits, et les fruits sont excellents à sécher. Les troupeaux vont à leurs pâturages, et les brebis mettent bas. On ramasse tous les biens de la terre; on amoncelle les grains dans les greniers, et on porte le raisin dans les pressoirs. Les noms des autres sont Gédael, Keel, Héel; Auxquels il faut ajouter Asphael. Et les jours de son autorité sont expirés et tinis.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 1, 'Et maintenant, mon fils Mathusala, je t’ai fait part de toutes les visions que j’ai vues avant toi. J’en eus encore deux autres avant de me marier, et l’une d’elles ne ressemblait pas à l’autre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 2, 'La première m’apparut pendant que j’étais occupé à lire; et la seconde quelque temps avant d’épouser ta mère. C’étaient deux importantes visions.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 3, 'Au sujet desquelles j’interrogeai le Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 4, 'Je reposais dans la maison de mon aïeul Malaleel, et je vis le ciel brillant et radieux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 5, 'Et je me prosternai, et vis la terre dévorée par un grand gouffre, et des montagnes suspendues au-dessus des montagnes.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 6, 'Des collines tombaient sur les collines, les arbres les plus hauts se fendaient dans toute leur hauteur, et ils étaient précipités dans l’abîme et descendaient au fond.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 7, 'A la vue de ce chaos, ma voix balbutiait. Je m’écriai: C’en est fait de la terre. Alors mon aïeul Malaleel me releva, et il me dit: Pourquoi t’écries-tu, mon fils, pourquoi te lamentes-tu?');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 8, 'Je lui racontai la vision que j’avais eue, et il me dit: Ce que tu as vu est grave, mon fils.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 9, 'Et la vision que tu as eue est frappante: elle se rapporte évidemment aux péchés de la terre, que l’abîme doit dévorer. Oui, il arrivera une grande catastrophe.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 10, 'C’est pourquoi, o mon fils, lève-toi et implore le Dieu de gloire, car tu es fidèle, et pour qu’il laisse quelques personnes sur la terre, et que les hommes ne périssent pas tous. Mon fils, la catastrophe viendra du ciel sur la terre; et ce sera une grande ruine.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 11, 'Alors je me levai et je suppliai le Seigneur; j’écrivis mes prières pour les générations du monde, donnant à mon fils Mathusala toutes les explications qu’il pouvait désirer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 12, 'Et quand je fus sorti, et que j’eus vu le soleil se levant à l’orient, la lune descendant à l’occident, toutes les étoiles que Dieu a créées s’avançant majestueusement dans le ciel, alors je célébrai le Seigneur de toute justice, j’exaltai son saint nom, parce qu’il avait fait surgir le soleil aux fenêtres de l’orient; il monte et s’élève à la face du ciel et il parcourt sa brillante carrière.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 13, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 14, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 15, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 16, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 17, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 18, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 19, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 82, 20, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 1, 'Et j’élevai les mains au ciel et je louai le saint et le Très-Haut. Et j’ouvris la bouche, et me servant de la langue que Dieu a donnée à tous les enfants des hommes, pour servir d’instrument à leurs pensées, je le célébrai en ces termes:');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 2, 'Tu es béni, Seigneur, roi puissant et sublime, seigneur de toutes les créatures du ciel, Roi des rois, Dieu de tout l’univers, dont le règne, la domination et la majesté n’auront jamais de fin.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 3, 'De siècle en siècle ton règne subsistera. Les cieux constituent ton trône à jamais, et la terre est ton marchepied d’éternité en éternité.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 4, 'Car c’est toi qui les a faites, c’est toi qui les gouverne. Rien ne peut se soustraire à ta puissance infinie. Avec toi la sagesse est immuable: elle veille sans cesse auprès de ton trône. Tu connais, tu vois, tu entends tout, rien ne peut se soustraire à ton puissant regard, car ton œil est partout!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 5, 'Voici les anges qui ont transgressé tes commandements; et ta colère plane sur la chair de l’homme, jusqu’au grand jour du jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 6, 'Or, Seigneur, mon Dieu, roi puissant et clément, je t’implore, je te supplie; perpétue sur la terre, que le genre humain exauce mes prières; que ma postérité se ne périsse pas tout entier!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 7, 'N’abandonne point la terre désolée, et qu’elle ne soit point détruite à jamais!');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 8, 'O Seigneur, extermine de la face de la terre la chair qui t’a offensé. Mais conserve la race des justes pour la perpétuer à jamais. O Seigneur ne détourne point ta face de ton serviteur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 83, 11, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 84, 1, 'Ensuite j’eus une autre vision, que je vais encore t’expliquer, ô mon fils. Et Enoch se leva et dit à son fils Mathusala: Laissemoi t’entretenir, ô mon fils. Ecoute la parole de ma bouche, et prête l’oreille à la vision et au songe de ton père. Avant d’épouser ta mère, j’eus une vision dans mon lit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 84, 2, 'Voici un taureau sortant de la terre. 3. Et ce taureau était blanc. 4. Ensuite sortit une génisse, et avec elle deux jeunes veaux, dont l’un était noir et l’autre rouge.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 84, 3, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 84, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 84, 5, 'Le noir frappa le rouge et le poursuivait par toute la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 84, 6, 'Dès ce moment je n’aperçus plus le veau rouge; mais le noir survint à une extrême vieillesse, et il y avait avec lui une génisse. Ensuite je vis beaucoup de taureaux nés de ce couple, qui leur ressemblaient et qui les suivaient. Et la première génisse sortit de la présence du premier taureau; et elle chercha le veau rouge, mais elle ne le trouva point. Et elle poussait des gémissements lamentables, en le cherchant. Et elle continua ses cris jusqu’à ce que le taureau s’approcha d’elle; dès ce moment elle cessa de se plaindre et de gémir. Et puis elle mit au monde un taureau blanc. Et après celui-ci beaucoup d’autres taureaux et d’autres génisses. Je vis encore dans mon songe un bœuf blanc, qui grandit de la même manière, et finit par devenir un grand bœuf blanc. Et de lui sortirent beaucoup d’autres bœufs qui lui étaient semblables. Et ils commencèrent à produire d’autres bœufs blancs, qui leur étaient semblables, et ils se succédaient les uns aux antres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 1, 'Je levai encore les yeux, et je vis le ciel au-dessus de ma tête.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 2, 'Et voici qu’une étoile tomba du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 3, 'Et elle se dressait au milieu de ces taureaux et paraissait paître avec eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 4, 'Ensuite je vis d’autres taureaux grands et noirs; et voici qu’ils changeaient sans cesse de pâturages et d’étables, lorsque leurs jeunes veaux commencèrent à se lamenter avec eux; et en regardant encore au ciel, je voyais beaucoup d’autres astres qui redescendaient et se précipitaient vers cette étoile unique.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 5, 'Au milieu des jeunes veaux, les taureaux étaient avec eux et paissaient avec terre frémissaient à ce spectacle et fuyaient épouvantés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 7, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 8, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 9, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 85, 10, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 86, 1, 'Je les regardai encore, et je ses vis se frapper les uns les autres, se dévorer, et j’entendis la terre qui en gémissait. Alors je tournai une seconde fois mes regards vers le ciel, et dans une seconde vision, je vis sortir des hommes semblables à des hommes blancs. Il y en avait un, et trois autres qui l’accompagnaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 86, 2, 'Ces trois hommes qui sortirent les derniers, me prirent par la main, et m’élevant au-dessus de la terre et de ses habitants, me conduisirent dans un lieu élevé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 86, 3, 'Et de là ils me montrèrent une haute tour environnée de collines plus basses; et ils me dirent: Reste ici, jusqu’à ce que tu voies ce qui doit arriver par ces éléphants, ces chameaux et ces ânes, ces astres et toutes ces génisses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 86, 4, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 86, 5, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 86, 6, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 87, 1, 'Alors j’aperçus celui de ces quatre hommes blancs qui était sorti le premier.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 87, 2, 'Et il saisit la première étoile qui était tombée du ciel.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 87, 3, 'Et il lui lia les pieds et les mains, et la jeta dans une vallée, vallée étroite, profonde, horrible et ténébreuse.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 87, 4, 'Alors un des quatre tira un glaive et le donna aux éléphants, aux chameaux et aux ânes, qui commencèrent à s’en frapper mutuellement; et toute la terre en frémit. Et dans ma vision, voici: je vis un des quatre hommes qui étaient descendus du ciel, qui rassembla et saisit toutes les grandes étoiles, dont les parties sexuelles étaient semblables aux parties sexuelles des chevaux, et il les jeta toutes, pieds et mains liés, dans les cavernes de la terre.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 88, 1, 'Alors un des quatre hommes s’approcha des autres taureaux, et leur enseigna des mystères tels, qu’ils en tremblaient. Et un homme naquit, et il bâtit un grand navire. Il habitait dans ce navire, et avec lui trois taureaux et une couverture se fit au-dessus d’eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 88, 2, 'Je levai de nouveau mes regards au ciel, et j’aperçus une grande voûte; et il y avait au-dessus sept cataractes qui versaient des torrents de pluie dans un village.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 88, 3, 'Je regardai encore, et voici que les fontaines de la terre se répandaient sur la terre dans ce village. Et l’eau commença à tourbillonner et à monter sur la terre, en sorte que je ne pouvais plus apercevoir ce village, parce qu’il était tout couvert d’eau. Il y avait en effet beaucoup d’eau, de ténèbres et de nuages; et voici que la hauteur de l’eau surpassait la hauteur de tous les villages. L’eau les couvrait en entier, et enveloppait la terre. Et tous les taureaux qui y étaient réunis furent submergés et périrent dans les eaux. Mais le navire flottait sur la surface de ces mêmes eaux. Cependant tous les taureaux, les éléphants, les chameaux et les ânes, et les troupeaux périssaient dans cette immense inondation; ils disparaissaient engloutis, et je ne pouvais plus les voir dans l’abîme d’où ils ne pouvaient plus se retirer. Je regardai encore, et voici les cataractes qui cessèrent de tomber d’en haut, et les fontaines de la terre de couler, et les abîmes s’entrouvrirent. Et les eaux s’y précipitèrent, et la terre apparut. Et le navire s’arrêta sur la terre, les ténèbres se dissipèrent et la lumière apparut. Alors, le bœuf blanc, qui avait été fait homme, sortit de l’arche, et avec lui trois taureaux. Et un des trois taureaux était blanc, et semblable à ce bœuf; un autre était rouge comme du sang, et le troisième était noir; et le taureau blanc se retira des autres. Et les bêtes des champs, et les oiseaux commencèrent à se multiplier. Et les différentes espèces de ces animaux se rassemblèrent, les lions, les tigres, les loups, les chiens, les sangliers, les renards, les chameaux et les porcs. Les sirets, les milans, les vautours, les congas et les corbeaux. Et parmi eux naquit un bœuf blanc. Et ils commencèrent à se mordre les uns les autres; et le bœuf blanc, qui était né parmi eux, engendra un onagre et un bœuf blanc, et ensuite plusieurs onagres. Et le bœuf blanc qui fut aussi engendré par lui, engendra à son tour un sanglier noir et une brebis blanche. Le sanglier engendra beaucoup d’autres sangliers. Et la brebis engendra douze autres brebis. Quand ces douze brebis furent grandes, elles en vendirent une d’entre elles à des ânes. Et les ânes vendirent la brebis à des loups. Et elle grandissait parmi eux. Alors le Seigneur amena les autres brebis pour habiter avec la première et paître avec elle au milieu des loups. Et elles se multiplièrent, et leurs pâturages étaient en abondance. Mais les loups commencèrent à les épouvanter et à les persécuter, et ils exterminaient leurs petits. Et ils les placèrent dans les profondeurs d’un grand fleuve. Alors les brebis commencèrent à se lamenter à cause de la perte de leurs petits, et à se tourner vers leur Seigneur; une d’elles cependant parvint à s’échapper et se retira parmi les onagres. Et je vis les brebis gémissant, priant et implorant le Seigneur De toutes leurs forces, jusqu’à ce que le Seigneur descendit à leurs cris du haut de son séjour céleste et daigna les visiter. Et il appela la brebis, qui avait échappé à la dent des loups, et lui enjoignit d’aller trouver ces loups meurtriers, et de les avertir de ne plus offenser les brebis. Alors la brebis alla trouver les loups, forte de la parole du Seigneur, et une autre brebis vint au-devant de la première et marcha avec elle. Et toutes deux étant entrées dans la demeure des loups leur défendirent de persécuter encore les brebis. Ensuite je vis les loups opprimant de plus en plus le troupeau de brebis. Et les brebis crièrent encore vers le Seigneur, et le Seigneur descendit au milieu d’elles. Et il commença à exterminer les loups, qui hurlaient; mais les brebis gardaient le silence et ne poussaient plus de cris. Et voici que je vis qu’elles émigrèrent du pays des loups. Les yeux de ces loups étaient aveuglés, et ils sortirent et ils poursuivirent les brebis de toutes leurs forces. Mais le Seigneur des brebis marchait avec elles et les conduisait. Et toutes les brebis le suivaient. Son visage était terrible; son aspect brillant et magnifique. Cependant les loups commencèrent à poursuivre les brebis, jusqu’à ce qu’ils les eurent atteintes au bord d’une grande mer. Alors la mer fut divisée, et les eaux se tinrent de chaque côté, comme un mur. Et le Seigneur des brebis, qui les conduisait, se plaça entre elles et les loups. Cependant les loups n’apercevaient point les brebis, mais ils les poursuivaient jusqu’au milieu de la mer, et alors les eaux se refermèrent derrière eux. Mais dès qu’ils virent le Seigneur, ils se retournèrent pour fuir de devant sa face. Mais alors les eaux se réunirent d’après les lois naturel es; et elles engloutirent les loups: Et je vis tous ceux qui avaient poursuivi les brebis, surmergés dans les flots. Mais pour les brebis, elles passèrent la mer, et s’avancèrent dans ce désert qui n’avait ni arbre, ni eau, ni verdure. Et elles commencèrent à ouvrir les yeux et à voir. Et Je vis le Seigneur de ces brebis vivre avec elles, et leur fournir les eaux nécessaires, Avec la brebis qui conduisait les autres. Et cette brebis monta sur le sommet d’un rocher élevé, et le Seigneur des brebis l’envoya vers les autres. Et je vis le Seigneur de ces brebis au milieu d’elles; et son visage était sévère et terrible. Et dès quelles l’eurent aperçu, les brebis furent épouvantées. Et toutes tremblantes elles envoyèrent la brebis qui les conduisait, et celle qui était avec elle, et elles lui disaient: Nous ne pouvons ni rester devant le Seigneur, ni le regarder en face. Alors la brebis, qui les conduisait, remonta de nouveau sur le sommet de la montagne. Et les autres brebis commencèrent à être aveuglées, et à s’égarer dans la voie que leur avait montrée la brebis. Mais celle-ci n’en savait rien. Et le Seigneur était courroucé contre elles; et quand la brebis apprit ce qui se passait au pied de la montagne, Elle en descendit à la hâte, et s’étant approchée d’elles, elle en trouva beaucoup, Qui étaient aveuglées, Et qui avaient quitté leur voie. Et quand les autres brebis l’aperçurent, elles craignaient et tremblaient en sa présence. Et elles désiraient revenir à leur étable. Alors cette brebis, conduisant les autres brebis avec elle, s’approcha de celles qui s’étaient égarées. Et elle commença à les frapper; et elles étaient épouvantées en sa présence. Alors elle ramena au bercail, celles qui s’étaient égarées. Je vis aussi dans une vision, que cette brebis se faisait homme, et il bâtit au Seigneur une bergerie, et il les y établit. Je vis encore tomber une brebis qui était venue au-devant de celle qui était le conducteur des autres. Je vis enfin périr un grand nombre d’autres brebis, leurs petits grandir à leur place, entrer dans un pâturage nouveau et venir au bord d’un fleuve. Et la brebis qui les avait conduites et qui était devenue homme, se sépara d’elles et mourut. Et toutes les brebis la cherchaient, et l’appelaient avec des cris lamentables. Je vis aussi qu’elles cessèrent de la pleurer, et qu’elles franchirent les eaux d’un fleuve. Là s’élevèrent d’autres brebis, pour remplacer celles qui étaient mortes, et qui les avaient conduites auparavant. Enfin je les vis entrer dans ce lieu fortuné, dans une terre de bénédiction et de joie. Elles s’y rassasiaient; et leurs bergeries étaient élevées sur cette terre bienheureuse, et leurs yeux étaient tantôt ouverts, tantôt aveuglés, jusqu’à ce qu’une brebis se leva au milieu d’elles, et les conduisit de telle sorte qu’elle les ramena toutes et leur ouvrit les yeux. Mais les chiens, les renards et les sangliers commencèrent à les dévorer, jusqu’à ce qu’une autre brebis devint la ruine du troupeau, et le bélier qui les conduisit. Ce bélier commença en effet à frapper de ses cornes les chiens, les renards et les sangliers, et à les exterminer tous. Mais la première brebis en ouvrant les yeux vit la gloire du bélier pâlir et s’éteindre. Car il commença à frapper aussi les brebis, à les persécuter, et à oublier toute sa dignité. Alors le seigneur envoya cette première brebis à une autre brebis, pour l’élever comme le bélier et le conducteur du troupeau en place de celle qui a terni sa gloire. Elle y alla et lui parla et l’institua bélier; et les chiens ne cessaient de vexer les brebis. Et le premier bélier persécutait le second. Alors celui-ci se leva, et s’enfuit de devant la face du premier bélier. Et je vis des chiens qui maltraitaient ce premier bélier. Mais le second se leva, et il conduisait les jeunes brebis. Et il engendra beaucoup d’autres brebis, mais enfin il succomba. Et il eut pour successeur un jeune bélier qui devint le chef et le conducteur du troupeau. Et sous lui, les brebis croissaient et se multipliaient. Et tous les chiens, les renards et les sangliers le craignaient et fuyaient de devant lui. Car ce bélier frappait et mettait en déroute toutes les bêtes féroces, en sorte qu’il leur était désormais impossible d’opprimer les brebis ou d’en ravir une seule. Et la bergerie devint grande et magnifique, et on y éleva une haute tour au moyen de ces brebis. La bergerie était peu élevée, mais la tour était fort haute. Et le Seigneur des brebis se plaça en cette tour, et voulut qu’on lui dressât une table magnifique. Mais je vis bientôt que les brebis commencèrent à errer de nouveau, à suivre diverses routes et à abandonner leur bergerie. Et le Seigneur en appela quelques unes et les envoya vers les autres. Mais celles-ci commencèrent à tuer les premières. Une d’elles cependant parvint à éviter le châtiment dout on la menaçait, et prenant la fuite, prêcha contre ceux qui voulaient la tuer. Et le Seigneur des brebis la délivra de leurs mains, la fit monter et asseoir auprès de moi et y rester. Il envoya encore à ces brebis prévaricatrices de ses commandements, d’autres brebis, pour avoir des témoins contre elles. Je vis encore que ces brebis, en abandonnant le Seigneur, et la tour élevée en son honneur, erraient en aveugles en des régions inconnues. Enfin je vis le Seigneur lui-même se venger, car il en faisait un grand carnage; mais elles crièrent vers lui; alors il abandonna son temple et les laissa en la puissance des lions, des tigres, des loups, des renards et de toute espèce de bêtes. Et ces bêtes commencèrent à les déchirer. Je vis aussi que le Seigneur, qu’elles avaient abandonné, les livrait à des lions féroces et cruels, et à toute espèce de bêtes. Alors je criai de toutes mes forces, et j’implorai le Seigneur pour ces brebis que dévoraient toute espèce de bêtes féroces. Mais il ne répondit point, et il regardait d’un œil satisfait ces brebis qu’on dévorait, qu’on exterminait. Enfin il appela soixante-dix pasteurs et leur donna le soin de veiller sur le troupeau. Et il leur dit Que chacun de vous veille sur les brebis, et qu’il fasse ce que je lui commanderai; je vous en donnerai à chacun un certain nombre à conduire. Et celles que je vous dirai d’exterminer, vous les exterminerez; et il les leur livra. Alors il en appela un autre et lui dit: Comprends et fais attention à tout ce que les pasteurs feront à ces brebis; car ils en feront périr beaucoup plus que je ne leur en désignerai. Et toute transgression, tout meurtre que les pasteurs commettront, sera noté; c’est-à-dire qu’il faudra indiquer celles qu’ils auront tuées par mon ordre, et celles qu’ils auront fait périr de leur propre autorité. Tout meurtre commis par les pasteurs leur est compté. Ne manque donc pas d’écrire combien de brebis ils auront fait périr de leur propre autorité, combien ils en auront livré au supplice, afin que ce compte soit contre eux un témoignage, que je sache tout ce qu’ils auront fait; s’ils ont exécuté mes ordres, ou s’ils ont négligé de les accomplir. Mais qu’ils ignorent ce que je te commande; ne leur ouvre point les yeux; ne leur donne point d’avertissement; mais compte avec soin tous les meurtres qu’ils commettront, et donnes-en-moi une connaissance exacte. Et ils abandonnèrent les brebis dans la puissance des lions, en sorte que plusieurs d’entre elles furent dévorées par les lions et par les tigres; et que les sangliers se jetèrent sur elles, brûlèrent la tour consacrée au Seigneur et détruisirent la bergerie. Et je fus bien chagrin de l’incendie de cette tour, et de la ruine de la bergerie. Car ensuite il me fut impossible de la voir. Quant aux pasteurs et leurs complices, ils livraient eux-mêmes les brebis à toutes les bêtes féroces, pour les faire dévorer. Chacune d’elles leur était livrée à son tour, et en son temps. Or, chacune aussi était inscrite dans un livre; et toutes celles qui périssaient y étaient soigneusement notées. Cependant chaque pasteur en faisait périr bien plus qu’il ne le devait. Alors je commençai à pleurer et à m’indigner sur le sort misérable de ces. brebis. Et je vis dans ma vision comment celui qui écrivait, notait jour par jour les meurtres commis par les pasteurs; comment il monta, se présenta au Seigneur des brebis et lui donna le livre qui renfermait le compte exact de tout ce que les pasteurs avaient fait, la note de tous ceux qu’ils, avaient fait périr. Et de tout le mal qu’ils avaient commis. Et le livre fut lu devant le Seigneur des esprits, qui, étendant la main, le signa et puis le déposa. Ensuite je vis comment les pasteurs avaient l’empire pendant douze heures. Et voici que trois de ces brebis revenues de la captivité, retournèrent et rentrèrent dans le lieu de la bergerie, et commencèrent à relever tout ce qui y avait été détruit. Mais les sangliers les en empêchaient, mais leurs efforts étaient inutiles. Et les brebis continuèrent à édifier, comme auparavant, et relevèrent la tour qu’on nomma la tour haute. Et ils recommencèrent à placer une table devant la tour, mais le pain qu’ils y placèrent était impur et pollué. De plus, toutes les brebis étaient aveuglées; elles ne pouvaient voir, pas plus que les pasteurs. Les pasteurs les livraient aussi pour les faire périr en grand nombre. Mais le Seigneur des brebis se taisait, et toutes les brebis furent entraînées. Pasteurs et brebis, tout était confondu, et nul ne les défendait des attaques des bêtes sauvages. Alors celui qui écrivait le livre, monta et le remit au Seigneur des brebis. Mais en même temps il le pria pour elles, en portant témoignage contre les pasteurs qui les avaient fait périr. Et après avoir déposé le livre, il s’en alla.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 1, 'Et je remarquai comment trente-sept pasteurs reprirent soin du troupeau jusqu’à ce que chacun disparût à son tour, comme les premiers. Alors les brebis furent confiées à d’autres pasteurs, qui les gardèrent chacun un certain temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 2, 'Puis j’aperçus dans ma vision tous les oiseaux du ciel qui accouraient, les aigles, les milans et les corbeaux. Et les aigles conduisaient tous les autres.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 3, 'Et ils commencèrent à dévorer les brebis, à leur crever les yeux avec leurs becs, et à se nourrir de leur chair.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 4, 'Et les brebis poussaient des cris lamentables, de se sentir ainsi dévorer.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 5, 'Et je criais aussi, et je gémissais dans mon sommeil contre le pasteur chargé de la garde du troupeau.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 6, 'Et je vis les brebis dévorées par les chiens, par les aigles et les vautours. Leur chair, leur peau, leurs muscles, tout était consommé; il ne leur restait que les os, qui tombaient à terre. Et le nombre des brebis diminuait considérablement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 7, 'Et je vis ensuite vingt-trois pasteurs placés à la tête du troupeau, et dont les temps respectifs accumulés forment cinquante-huit âges.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 8, 'Alors les agneaux furent mis au monde par les brebis blanches, et ils commencèrent à ouvrir les yeux et à voir, et à appeler leurs mères.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 9, 'Mais les brebis ne les regardaient pas, n’écoutaient point leurs plaintes; mais elles étaient sourdes, aveugles et endurcies.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 10, 'Et j’aperçus dans ma vision les corbeaux qui s’abattaient sur ces agneaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 11, 'Qui les saisissaient, et qui dévoraient les brebis après les avoir déchirées.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 12, 'Je vis aussi les cornes de ces agneaux s’accroître, mais les corbeaux cherchaient à les ébranler.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 13, 'Voici enfin qu’une grande corne poussa sur la tète d’une de ces brebis, et les yeux de toutes les autres furent ouverts.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 14, 'Et la première les regardait, et leurs yeux furent ouverts, et elle les appelait.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 15, 'Les bœufs la voyant, se précipitèrent sur elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 16, 'Cependant les aigles, les milans, les corbeaux et les vautours continuèrent à persécuter les brebis, volant sur elles et les dévorant. Et les brebis se taisaient, mais les bœufs se lamentaient et poussaient des gémissements.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 17, 'Alors les corbeaux luttèrent avec elle.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 18, 'Cherchant à briser la corne, mais leurs efforts étaient inutiles.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 19, 'Et je regardai jusqu’à ce que vinrent les pasteurs, les aigles, les inilans et les vautours,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 20, 'Qui poussaient les corbeaux à briser la corne de ce bœuf, et qui combattaient avec lui. Mais il soutenait leur choc et demandait du secours.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 21, 'Alors je vis venir l’homme qui avait inscrit les noms des pasteurs, et qui était monté en la présence du Seigneur des brebis. 22. Il vint porter du secours au bœuf, et annonça à tous qu’il était venu porter du secours au bœuf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 22, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 23, 'Et voici que le Seigneur des brebis descendit enflammé de colère, et tous ceux qui l’aperçurent s’enfuirent. Les autres se prosternèrent dans son tabernacle, et les aigles, les milans, les corbeaux et les vautours se réunirent et entraînèrent avec eux toutes les brebis des champs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 24, 'Tous se réunirent et cherchèrent à briser la corne du bœuf.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 25, 'Alors je vis l’homme qui écrivait par l’ordre du Seigneur, prendre le livre de la destruction accomplie par les douze derniers pasteurs, et il prouva qu’ils avaient fait périr plus de monde que ceux qui les avaient précédés.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 26, 'Je vis encore venir à eux le Seigneur des brebis, tenant en sa main le sceptre de sa colère, en frapper la terre, qui s’entrouvrit, et les bêtes et les oiseaux du ciel cessèrent de persécuter les brebis, et tombèrent dans les gouffres béants de la terre, qui se referma sur eux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 27, 'Je vis aussi donner une grande épée aux brebis, qui poursuivaient à leur tour les bêtes sauvages, et les exterminaient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 28, 'Mais toutes les bêtes et tous les oiseaux du ciel se retirèrent de devant leur face.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 29, 'Et je vis un trône élevé dans une région fortunée,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 30, 'Sur lequel siégeait le Seigneur des esprits, qui prit tous les livres,');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 31, 'Et les ouvrit.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 32, 'Alors le Seigneur appela les sept premiers hommes blancs, et leur ordonna d’amener la première étoile, qui avait précédé toutes les autres, dont les parties sexuelles étaient semblables aux parties sexuelles des chevaux, qui enfin était tombée la première, et tous l’amenaient devant lui.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 33, 'Et il dit à l’homme qui écrivait en sa présence, et qui était un des sept hommes blancs: Prends ces soixante-dix pasteurs, auxquels j’ai confié les brebis, et qui en ont fait périr beaucoup plus que je ne l’avais ordonné. Et voici; je les vis enchaînés et debout devant lui. Et on commença par juger Jes étoiles, et elles furent reconnues coupables, et amenées au lieu du jugement; et on les jeta dans un lieu profond, et rempli de flammes. Ensuite les soixante-dix pasteurs furent jugés et reconnus coupables; ils furent également précipités dans l’abîme enflammé.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 34, 'Dans le même temps, je vis au milieu de la terre un abîme rempli de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 35, 'C’est là qu’étaient conduites les brebis aveugles, qui avaient été jugées coupables; toutes elles étaient précipitées dans ce gouffre de feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 36, 'Et ce gouffre se trouvait situé à la droite de cette bergerie.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 37, 'Et je vis les brebis brûler et leurs os consumés par le feu.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 38, 'Et je me tenais debout, considérant comment cette antique bergerie fut détruite; mais auparavant on en avait enlevé les colonnes, l’ivoire et toutes les richesses qu’elle renfermait, et on les avait amoncelées dans un lieu situé à l’orient.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 39, 'Je vis aussi le Seigneur des brebis élever une maison plus grande et plus haute que la première, et la bâtir dans le même endroit où avait été la première. Toutes ses colonnes étaient neuves, l’ivoire neuf, et en plus grande quantité qu’auparavant.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 40, 'Et le Seigneur des brebis habitait à l’intérieur. Et toutes les bêtes sauvages, tous les oiseaux du ciel s’inclinèrent devant les brebis qui restaient et les adorèrent, leur adressèrent des prières, en leur obéissant en toutes choses.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 41, 'Alors les trois hommes, qui étaient revêtus de blanc, et qui me prenant par la main m’avaient fait monter, m’enlevèrent encore, et me placèrent au milieu des brebis, avant le commencement du jugement.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 42, 'Les brebis étaient toutes blanches, la laine longue et pure de toute tache. Et toutes celles qui avaient péri ou qu’on avait exterminées, toutes les bêtes sauvages, tous les oiseaux du ciel se réunirent dans cette maison, et le Seigneur des brebis tressaillait d’allégresse de voir rentrer les brebis au bercail.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 43, 'Et je vis qu’elles déposaient l’épée qui leur avait été donnée, qu’elles la reportaient dans la bergerie, et la scellaient en présence du Seigneur.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 44, 'Les brebis étaient enfermées dans la maison, qui avait peine à les contenir toutes. Et leurs yeux étaient ouverts, et elles contemplaient le Bon, et il n’en était pas une parmi elles qui ne l’aperçut.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 45, 'Je vis aussi que la maison était grande et large, et pleine de monde. Et voici qu’il naquit un veau blanc, dont les cornes étaient grandes, et toutes les bêtes sauvages, tous les oiseaux du ciel l’adoraient et l’imploraient incessamment.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 46, 'Alors je vis leur nature à tous se transformer, et ils devenaient des veaux blancs.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 47, 'Et le premier d’entre eux fut fait Verbe, et le Verbe devint un grand animal, et il portait sur sa tête de grandes cornes noires.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 48, 'Et le Seigneur des brebis se réjouissait à la vue de tous ces veaux.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 49, 'Et moi qui m’étais prosterné, je fus réveillé, mais je conservais la mémoire de tout ce que j’avais vu. Telle est la vision qui m’apparut pendant mon sommeil. Je célébrai à mon réveil le Seigneur de toute justice, et je lui en rendis toute la gloire.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 50, 'Ensuite je répandis beaucoup de larmes, et elles coulaient sans s’arrêter par le souvenir de ce que j’avais vu. Car toutes ces choses s’accompliront et toutes les actions des heureux se manifesteront en leur temps.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 51, 'Et je pensai la nuit au songe que j’avais eu, et je pleurai amèrement, plein de trouble encore de la vision que j’avais eue.');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 52, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 53, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 54, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 55, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 56, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 57, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 58, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 59, '');
INSERT INTO `FreLXXGiguet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 89, 60, '');
